def _merge_pm_periods_into_cycles(c):
    """Fold the old `pm_periods` table into `cycles`, once.

    PM shipped with its own period table; HR then created the same review
    period in both and kept them aligned by hand. They are one thing, so every
    table that hung off a period is repointed at the cycle it already meant.

    Runs at most once -- the guard is whether pm_periods still exists. Safe to
    call on a fresh database (nothing to merge) and on an already-merged one.

    Two details are load-bearing, both learned from the earlier CHECK-widening
    rebuilds in this file: the caller's connection must have foreign_keys OFF
    (dropping a parent with them ON fires ON DELETE across the very children
    being moved), and legacy_alter_table must be ON around the RENAME or SQLite
    rewrites the children's foreign keys to point at the temporary name.
    """
    have = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    if "pm_periods" not in have:
        return
    if c.execute("PRAGMA foreign_keys").fetchone()[0]:
        raise RuntimeError("pm_periods merge needs foreign_keys OFF")

    # 1. Every period becomes a cycle. Match on (year, half) -- pm_periods
    #    stores half as 'HY1'/'HY2', cycles as 1/2. A period with no matching
    #    cycle becomes one, so nothing is stranded.
    cyc_by_yh = {(r[1], r[2]): r[0] for r in c.execute("SELECT id, year, half FROM cycles")}
    mapping = {}
    for p in c.execute("SELECT id, code, name, half, year, starts_on, ends_on, "
                       "closed_at, archived_at FROM pm_periods ORDER BY id").fetchall():
        pid, code, name, half, year = p[0], p[1], p[2], p[3], p[4]
        h = 2 if str(half).upper() in ("HY2", "2") else 1
        if (year, h) in cyc_by_yh:
            mapping[pid] = cyc_by_yh[(year, h)]
        else:
            cur = c.execute(
                "INSERT INTO cycles(code, name, starts_on, ends_on, is_active, "
                "closed_at, archived_at, year, half) VALUES (?,?,?,?,0,?,?,?,?)",
                (code, name, p[5], p[6], p[7], p[8], year, h))
            mapping[pid] = cur.lastrowid
            cyc_by_yh[(year, h)] = cur.lastrowid

    targets = [t for t in sorted(have)
               if t != "pm_periods"
               and "period_id" in [x[1] for x in c.execute(f"PRAGMA table_info({t})")]]

    # An inner join on a real map table, not a computed default: a row whose
    # period has no cycle must fail the row-count check rather than be quietly
    # carried through with a NULL.
    c.execute("CREATE TEMP TABLE _pmap(period_id INTEGER PRIMARY KEY, cycle_id INTEGER)")
    c.executemany("INSERT INTO _pmap VALUES (?,?)", list(mapping.items()))
    c.execute("PRAGMA legacy_alter_table=ON")
    orphaned = {}
    for t in targets:
        sql = c.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                        (t,)).fetchone()[0]
        new_sql = re.sub(r'CREATE TABLE (IF NOT EXISTS )?["\[]?' + re.escape(t) + r'["\]]?',
                         f"CREATE TABLE {t}__new", sql, count=1)
        if f"{t}__new" not in new_sql:
            raise RuntimeError(f"could not rewrite the CREATE statement for {t}")
        new_sql = new_sql.replace("REFERENCES pm_periods(id)", "REFERENCES cycles(id)")
        new_sql = re.sub(r"\bperiod_id\b", "cycle_id", new_sql)
        cols = [x[1] for x in c.execute(f"PRAGMA table_info({t})")]
        # LEFT JOIN + COALESCE, deliberately not an inner join: a row whose
        # period_id has no pm_periods row (already-orphaned data) must survive
        # the merge keeping the id it had, exactly as orphaned as before. An
        # inner join would silently DROP it and then trip the row-count check,
        # turning pre-existing debris into a failed boot.
        src = ", ".join(("COALESCE(m.cycle_id, t.period_id)" if x == "period_id" else f"t.{x}")
                        for x in cols)
        dst = ", ".join(("cycle_id" if x == "period_id" else x) for x in cols)
        before = c.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
        stranded = c.execute(
            f"SELECT COUNT(*) FROM {t} t LEFT JOIN _pmap m ON m.period_id = t.period_id "
            "WHERE m.cycle_id IS NULL").fetchone()[0]
        if stranded:
            orphaned[t] = stranded
        # Explicit indexes die with the table, so carry their statements over.
        idx_sql = [r[0] for r in c.execute(
            "SELECT sql FROM sqlite_master WHERE type='index' AND tbl_name=? "
            "AND sql IS NOT NULL", (t,)).fetchall()]
        idx_names = [r[0] for r in c.execute(
            "SELECT name FROM sqlite_master WHERE type='index' AND tbl_name=? "
            "AND sql IS NOT NULL", (t,)).fetchall()]
        c.execute(new_sql)
        c.execute(f"INSERT INTO {t}__new ({dst}) SELECT {src} FROM {t} t "
                  f"LEFT JOIN _pmap m ON m.period_id = t.period_id")
        after = c.execute(f"SELECT COUNT(*) FROM {t}__new").fetchone()[0]
        if before != after:
            raise RuntimeError(f"{t}: {before} rows in, {after} out -- aborting merge")
        for n in idx_names:
            c.execute(f"DROP INDEX IF EXISTS {n}")
        c.execute(f"DROP TABLE {t}")
        c.execute(f"ALTER TABLE {t}__new RENAME TO {t}")
        for s in idx_sql:
            c.execute(re.sub(r"\bperiod_id\b", "cycle_id", s))
    c.execute("DROP TABLE _pmap")
    c.execute("DROP TABLE pm_periods")
    c.execute("PRAGMA legacy_alter_table=OFF")
    if orphaned:
        # Reported, never fatal: these rows already pointed at a period that
        # was not there, and they come through the merge keeping that id. Data
        # debris predating this change is not a reason to refuse to start.
        app.logger.warning("pm_periods merge: rows kept with an unmatched id: %s", orphaned)


# Set by _ensure_runtime_schema(): None while the migration has not run,
