# computed codes: a prefix and what it is about (pm_kpi_setting_<step>, talent_<pip|promotion>_<decision|lock|reopen>)
_ACTION_PREFIXES = (("pm_kpi_setting_", "KPI setting: "), ("talent_pip_", "PIP list: "),
                    ("talent_promotion_", "Promotion list: "), ("succession_", "Succession: "), ("reward_", "Reward: "),
                    ("pm_", "Performance: "), ("tc_", "Competency: "), ("idp_", "Development plan: "))


def action_label(code):
    """A stored activity_log action in plain words: the list above, else its prefix's subject and the rest as words."""
    code = (code or "").strip()
    if code in ACTION_LABELS:
        return ACTION_LABELS[code]
    for pre, subject in _ACTION_PREFIXES:
        if code.startswith(pre) and len(code) > len(pre):
            return subject + code[len(pre):].replace("_", " ")
    return code.replace("_", " ").capitalize() or "—"


app.add_template_filter(action_label, "action_label")


def _form_int(name):
    """Parse a required integer form field; abort 400 on bad/missing input
    instead of raising a 500."""
    try:
        return int(request.form.get(name, ""))
    except (TypeError, ValueError):
        abort(400)


# Admin tables default to 30 rows/page; the admin can switch to a larger size.
PER_PAGE_OPTIONS = [10, 30, 50, 100, 200]


def _per_page(default=30):
    """Validated rows-per-page from ?per_page=, restricted to PER_PAGE_OPTIONS."""
    try:
        v = int(request.args.get("per_page", default))
    except (TypeError, ValueError):
        return default
    return v if v in PER_PAGE_OPTIONS else default


@app.template_filter("from_json")
def _from_json(raw):
    """Parse a JSON config column for display.
    Returns {} for anything missing or unparseable, so one malformed blob can
    never take down an admin page for every other row on it."""
    if not raw:
        return {}
    try:
        v = json.loads(raw)
    except (ValueError, TypeError):
        return {}
    return v if isinstance(v, dict) else {}


@app.template_filter("dict_drop")
def _dict_drop(d, *keys):
    """A copy of a dict without these keys (and never 'page', nor a name url_for owns): a filter's Clear link keeps
    everything else."""
    return {k: v for k, v in (d or {}).items() if k not in keys and k != "page" and k not in _URL_FOR_OWN_ARGS}


@app.template_filter("thousands")
def _thousands(n):
    """Format an integer with thousands separators (e.g. 8654 -> '8,654').
    Non-integers (None, blanks, floats-as-text) pass through unchanged."""
    try:
        return f"{int(n):,}"
    except (TypeError, ValueError):
        return n


@app.template_filter("commas")
def _commas(n):
    """Comma-group a number for display without discarding a genuine
    decimal part (unlike `thousands`, which truncates via int() -- fine
    for counts, but not for a KPI threshold/target that could legitimately
    be fractional). A whole-number value renders with no decimal point
    (5150000.0 -> '5,150,000'); a real fractional value keeps it
    (4.5 -> '4.5', 5150000.25 -> '5,150,000.25'). None/non-numeric pass
    through unchanged."""
    try:
        f = float(n)
    except (TypeError, ValueError):
        return n
    if not math.isfinite(f):
        # inf/nan have no comma-grouped form, and `f == int(f)` below RAISES
        # on them rather than returning False (OverflowError on inf,
        # ValueError on nan) -- an uncaught 500 from a display filter, which
        # is how a single bad stored value took out an employee's whole
        # scorecard page and their manager's review page. Pass it through
        # untouched, exactly like any other value float() can't handle. The
        # write paths reject non-finite input (see performance_kpi_autosave
        # and performance_kpi_submit_all); this is the second line of
        # defence, and what lets an already-poisoned row still render.
        return n
    if f == int(f):
        return f"{int(f):,}"
    return f"{f:,}"


@app.template_filter("myt")
def _myt(ts):
    """Render a stored UTC timestamp (SQLite datetime('now')) in Malaysia time
    (MYT, UTC+8), e.g. '2026-06-24 15:37'. Passes through anything unparseable."""
    if not ts:
        return ts
    s = str(ts).strip().replace("T", " ")
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return (datetime.strptime(s, fmt) + timedelta(hours=8)).strftime("%Y-%m-%d %H:%M")
        except (ValueError, TypeError):
            continue
    return ts


@app.template_filter("myt_day")
def _myt_day(ts):
    """A stored UTC timestamp as a day people read: '12 Jan 2026' (the release page, 2026-10-12)."""
    return _myt_date_str(ts) or ""


@app.template_filter("myt_date")
def _myt_date(ts):
    """The DATE of a stored UTC timestamp, in Malaysia time -- '2026-08-22'.

    Exists because fourteen templates wrote ``x[:10]``, which is the date half
    of a UTC string: anything that happened between 00:00 and 08:00 MYT was
    shown a day EARLY. Slicing the formatted value would work too, but a named
    filter cannot be copied to a fifteenth site with the wrong index, and it
    absorbs the ``if x else ''`` guard as well."""
    out = _myt(ts)
    return out[:10] if out else ""


