def init_db():
    con = sqlite3.connect(DB_PATH)
    con.executescript(SCHEMA)
    con.commit()
    con.close()


# ---------------------------------------------------------------------------
# Auth
# ---------------------------------------------------------------------------
# --- Demo role switching ----------------------------------------------------
# One seeded login can view the product as each of the five employee-facing
# roles. It is real impersonation, not a display toggle, because every role's
# pages are gated on real relationships -- HOD is "does anyone's hod_id point at
# me", BUCEO/BGCEO are stored flags -- so a cosmetic switch would render pages
# that lie about what that role can actually see.
#
# Ordered worst-to-best privilege, which is also the order the switcher shows.
DEMO_PERSONA_ORDER = ["employee", "gradeh", "gradeh_b", "manager", "gradeh_hlm", "hod", "buceo", "bgceo", "groupchief", "chair", "admin"]
# The persona keys that exist for the Grade H demo login ALONE (2026-10-30): the KPI-route staff person, the no-KPI (line manager
# route) staff person and the Grade H line manager (a supervisor who is himself on the Grade H list). demo_personas lists them only
# for that login on a server with ONEHR_GRADEH=1; every other demo login reads as production does. One tuple, one filter.
DEMO_GRADEH_PERSONAS = ("gradeh", "gradeh_b", "gradeh_hlm")
DEMO_PERSONA_LABELS = {
    # There was a sixth persona, 'setter', standing before KPI agreement. It is
    # not a distinct ROLE -- it is the same Employee standing earlier in the
    # period -- which is exactly why it read as a duplicate here. It now lives
    # on the cohort axis below instead (demo_state 'setting'), so the switcher
    # says "Employee, at the point KPIs are still being agreed" rather than
    # inventing a second job title for it. seed_kpi_library_chbm.py files that
    # account as persona 'employee' + state 'setting'; reset_chbm_demo_open.py
    # re-homes any legacy row still carrying the old key, because dropping it
    # from here alone would leave those accounts in the switcher labelled with
    # the raw key.
    # There was an "Employee (LMS)" persona too (2026-10-20), retired 2026-10-21 (Chris: "since we have the learning
    # toggle already, we can take out the employee (LMS) persona"): the demo menu's LMS: Yes / No does its job, and
    # the Learning demo now sits on the Employee persona (deploy/demo/seed_lms_demo.py).
    "employee": "Employee",
    # the Grade H demo login's own sign-in account (2026-10-29; deploy/demo/seed_gradeh_demo_login.py): ZZGHDEMO-EMP, a Grade H
    # person on the Grade H list. Listed only for that login (_gradeh_demo_login) and only where the server has ONEHR_GRADEH=1
    # (demo_personas); the main demo login (ZZDEMO-CHBM-EMP) and every other demo login have no Grade H persona at all
    "gradeh": "Employee (Grade H, KPI)",
    # route B (no KPI lines; the line manager rates eight attributes): ZZGHDEMO-H5, so a tester can see that side of the staff page
    "gradeh_b": "Employee (Grade H, no KPI)",
    "manager": "Line manager",
    # a line manager who is on the Grade H list himself (ZZGHDEMO-HLM, JG H, language BM): the line manager pages in his own language
    "gradeh_hlm": "Line manager (Grade H)",
    "hod": "HOD",
    "buceo": "Business unit CEO", "bgceo": "Business group CEO",
    # a Group Chief calls people outside their own line (admin round 4, row 7: deploy/demo/seed_chbm_group_chief.py)
    "groupchief": "Group Chief",
    # the Executive Chairman (2026-10-29, Chris: a persona on THIS login, labelled EC; deploy/demo/seed_exec_chair.py); he only
    # does anything where ONEHR_CHAIR=1 and the seat (exec_chair_id) is his
    "chair": "EC",
    # Only ever reachable where L360_DEMO_ADMIN=1 -- the pool query filters
    # admin-role rows out everywhere else, so this label stays unused there.
    "admin": "Group People admin",
}

# the longer words where the switcher can show them (an option's tooltip)
DEMO_PERSONA_TITLES = {"chair": "Executive Chairman"}
app.jinja_env.globals["nav_demo_titles"] = DEMO_PERSONA_TITLES

# The cohorts a persona can belong to (users.demo_state), ordered the way a
# period actually runs -- which is also the order the switcher shows: KPIs
# still being agreed, then agreed and taking results, then everything closed.
DEMO_STATE_ORDER = ["setting", "open", "filled"]
DEMO_STATE_LABELS = {
    "setting": "Setting KPIs",
    "open": "Open for submission",
    "filled": "Submissions complete",
}
# Stays 'open'. A NULL demo_state predates the cohort axis and belongs to the
# original open cohort, so widening the list above must not silently re-file
# those rows into the new first cohort.
DEMO_STATE_DEFAULT = "open"


def demo_actor():
    """The REAL logged-in account, before any persona switch.

    Everything that must answer "who is actually sitting here" -- the switcher
    itself, and its own authorisation -- reads this rather than current_user(),
    which deliberately returns the persona."""
    uid = session.get("user_id")
    if not uid:
        return None
    row = get_db().execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
    if row is not None and row["left_at"]:
        # Marked as left: login already refuses them, and now a session they still had open ends on their next click
        # too, with the login page's own sentence (handoff review, 2026-10-12: it kept working until the browser closed).
        session.clear()
        flash("This account is no longer active. Please contact Group People.", "error")
        return None
    return row


def demo_personas(actor=None):
    """The personas `actor` may become: a fixed, seeded set inside their own
    business group. Empty for everyone else, which is every real login.

    This list IS the authorisation boundary -- the switch route and
    current_user() both resolve a target through it rather than trusting a
    session value, so the worst a tampered session can do is name an id that
    isn't in here and get ignored."""
    actor = actor if actor is not None else demo_actor()
    if not actor or not demo_accounts_on() or not _row_get(actor, "demo_switcher") or actor["role"] == "admin":
        return []
    state = demo_state()
    cached = getattr(g, "_demo_personas", None)
    if cached is not None and cached[0] == (actor["id"], state):
        return cached[1]
    # An HR admin is exempt from the cohort filter, deliberately. The cohort
    # axis models how far an ASSESSMENT has got -- KPIs still being agreed,
    # open for submission, submissions complete -- and an admin is not in the
    # assessment population at all, so their view is the same in every one of
    # them. Filtering them by it would only ever hide the persona for no
    # reason, which is exactly what it did before this clause: the seeded row
    # carries no demo_state, so it read as 'open' and vanished the moment the
    # cohort moved to 'filled'. Every other persona stays cohort-scoped.
    rows = get_db().execute(
        "SELECT * FROM users WHERE demo_persona IS NOT NULL AND TRIM(demo_persona)!='' "
        f"AND (role='admin' OR {_demo_state_sql()}=?) "
        f"{_DEMO_ADMIN_SQL}AND left_at IS NULL AND business_group=?",
        (state, actor["business_group"])).fetchall()
    # the Grade H personas (DEMO_GRADEH_PERSONAS) exist only for the Grade H demo login, on a server that has the module (ONEHR_GRADEH=1): every other
    # demo login reads as production does, with no Grade H at all (2026-10-29)
    rows = [r for r in rows if r["demo_persona"] not in DEMO_GRADEH_PERSONAS
            or (os.environ.get("ONEHR_GRADEH") == "1" and _gradeh_demo_login(actor))]
    rows = sorted(rows, key=lambda r: (DEMO_PERSONA_ORDER.index(r["demo_persona"])
                                       if r["demo_persona"] in DEMO_PERSONA_ORDER else 99))
    g._demo_personas = ((actor["id"], state), rows)
    return rows


def _demo_state_sql(prefix=""):
    """SQL for a persona's cohort, reading NULL/'' as 'open' -- every persona
    seeded before the cohort split predates the column and is an open one."""
    return f"COALESCE(NULLIF(TRIM({prefix}demo_state),''),'{DEMO_STATE_DEFAULT}')"


def demo_state():
    """Which cohort the demo views: always the open one now. The Period switch that chose between cohorts is gone
    (Chris, 2026-09-30: "does the demo 'period' serve anymore purpose ... If not, remove it") -- on staging the
    'setting' and 'filled' personas carry no KPIs on the active cycle, so they showed empty screens, and the view-aware
    Reset rewinds the open cohort instead. A session left on another cohort comes back here."""
    return DEMO_STATE_DEFAULT


def current_user():
    """The user the app should behave as -- the persona when a demo switch is
    active, otherwise the real account.

    Returning the persona here (rather than special-casing hundreds of call
    sites) is what makes every page, permission check and query behave exactly
    as it would for that person."""
    actor = demo_actor()
    if not actor:
        return None
    target_id = session.get("demo_as")
    if not target_id or target_id == actor["id"]:
        return actor
    for p in demo_personas(actor):
        if p["id"] == target_id:
            return p
    # Not a persona this account may be -- a stale session after a re-seed, or
    # a tampered one. Drop it and carry on as the real account rather than
    # erroring, so a demo can never get wedged out of the app.
    session.pop("demo_as", None)
    return actor


def login_required(view):
    @wraps(view)
    def wrapped(*a, **kw):
        if not current_user():
            return redirect(url_for("login"))
        return view(*a, **kw)
    return wrapped


def is_admin(u):
    return bool(u and u["role"] == "admin")


def is_super(u):
    """Super admin = an admin with no BG restriction (org-wide)."""
    return is_admin(u) and not u["admin_bg"]


def is_system(u):
    """A system admin (Chris, 2026-10-28): a super admin that tools/make_system_admin.py made. It passes every super
    check untouched (is_super is unchanged); only a system admin can change such an account, and only a system admin
    gets AI+ Connect. A row or dict with no such key is not one."""
    return bool(is_super(u) and _row_get(u, "is_system_admin"))


class SystemAdminLocked(Exception):
    """A change to a system admin's account, asked by someone who isn't one. Raised by _system_admin_refuse; the error
    handler below turns it into the sentence, a flash on a page or a 403 for a fetch."""


SYSTEM_ADMIN_LOCK_MSG = "Only a system admin can change this account."


def _system_admin_locked(me, target, db=None):
    """THE guard (2026-10-28): None when `me` may change `target`'s account, else the plain sentence refusing.
    `target` is a users row, a dict or an id; `me` a row, dict or id (an id is looked up). Everything that writes
    another account (role, scope, password, notification emails, close, email, details, line manager, a roster import)
    calls this or _system_admin_refuse, and test_system_admin lints that every such writer does."""
    d = db or get_db()

    def row(x):
        if x is None or isinstance(x, (dict, sqlite3.Row)):
            return x
        return d.execute("SELECT * FROM users WHERE id=?", (x,)).fetchone()
    t = row(target)
    if not t or not _row_get(t, "is_system_admin"):
        return None
    return None if is_system(row(me)) else SYSTEM_ADMIN_LOCK_MSG


def _system_admin_refuse(me, target, db=None):
    """_system_admin_locked, raising SystemAdminLocked instead of returning the sentence."""
    msg = _system_admin_locked(me, target, db)
    if msg:
        raise SystemAdminLocked(msg)


def _local_path(nxt, default):
    """A same-site path from a `next` / `back` field or a Referer, else `default` (security test 3-02 + 3-06, 2026-10-31).

    One rule for every redirect that comes back to a page: control characters (a tab or newline inside "/\t/evil.example"
    is dropped by the browser, leaving "//evil.example") are stripped first; then exactly one "/" must open it, followed
    by something that is neither "/" nor a backslash (a browser reads "/\\host" as "//host"); no scheme or host may
    survive. A path with "//" later on, a query and a #fragment are fine. Never redirect to a raw field without this."""
    raw = "".join(ch for ch in str(nxt or "") if unicodedata.category(ch)[0] != "C").strip()
    if raw[:1] != "/" or raw[1:2] in ("/", "\\"):
        return default
    if "\\" in raw.split("?", 1)[0].split("#", 1)[0]:
        return default
    u = urlparse(raw)
    if u.scheme or u.netloc:
        return default
    return raw


def _referer_path(default):
    """The page a form was posted from, as a same-site path (query kept), else `default`: the Referer must name this
    host, and its path goes through _local_path ("http://host//evil.example" no longer comes back as "//evil.example")."""
    ref = urlparse(request.referrer or "")
    if ref.netloc != request.host or not ref.path:
        return default
    return _local_path(ref.path + ("?" + ref.query if ref.query else ""), default)


@app.errorhandler(SystemAdminLocked)
def _system_admin_locked_handler(e):
    msg = str(e) or SYSTEM_ADMIN_LOCK_MSG
    if request.is_json or request.headers.get("X-Requested-With") in ("XMLHttpRequest", "fetch"):
        return jsonify(ok=False, error=msg), 403
    flash(msg, "error")
    return redirect(_referer_path(url_for("admin_admins")))


def is_demo(u):
    """True if this is a demo/briefing account (set up for live demonstrations).
    Demo users bypass the cycle start-date gate and the submit-lock, and are
    hidden from real admin views, headcount, panels and reminders."""
    return bool(u and _row_get(u, "is_demo"))


def admin_bg_of(u):
    """The Business Group a BGHR admin is scoped to, or None for the super admin and for an admin whose role acts on the
    whole company (Roles & access, 2026-10-20: admin_bg holds ADMIN_COMPANY_SCOPE; such an admin is never the super
    admin, since is_super() reads admin_bg itself, and what they may do is their role's)."""
    if not (is_admin(u) and u["admin_bg"]) or u["admin_bg"] == ADMIN_COMPANY_SCOPE:
        return None
    return u["admin_bg"]


def admin_companies_of(u):
    """The set of companies a sub-admin is restricted to (empty = whole BG).

    An admin with rows in admin_companies is a "sub-admin" confined to those
    companies within its Business Group. Cached per-request per admin id.
    """
    if not u or not is_admin(u) or not u["admin_bg"]:
        return frozenset()
    cache = getattr(g, "_admin_comps", None)
    if cache is None:
        cache = {}
        g._admin_comps = cache
    if u["id"] not in cache:
        rows = get_db().execute(
            "SELECT company FROM admin_companies WHERE admin_id=?", (u["id"],)).fetchall()
        cache[u["id"]] = frozenset(r["company"] for r in rows)
    return cache[u["id"]]


def is_sub_admin(u):
    """A BG admin further restricted to specific companies."""
    return bool(admin_bg_of(u)) and bool(admin_companies_of(u))


def buceo_seats(db, uid):
    """[(business_group, company)] this person holds as BU CEO, in unit order -- one holder per unit, several units
    per person (admin round 4). Cached per request."""
    cache = _req_cache()
    k = "_bus_%s" % uid
    if k not in cache:
        cache[k] = [(r[0], r[1]) for r in db.execute(
            "SELECT business_group, company FROM buceo_seats WHERE user_id=? ORDER BY business_group, company", (uid,))]
    return cache[k]


def buceo_holder(db, bg, company):
    """The users row holding (bg, company)'s BU CEO seat, or None."""
    return db.execute("SELECT u.* FROM buceo_seats s JOIN users u ON u.id=s.user_id WHERE s.business_group=? AND "
                      "s.company=?", (bg, company)).fetchone()


def buceo_holders(db, bg=None):
    """{(bg, company): users row} of every held BU CEO seat (one group's, with `bg`)."""
    q = "SELECT s.business_group sbg, s.company sco, u.* FROM buceo_seats s JOIN users u ON u.id=s.user_id"
    rows = db.execute(q + (" WHERE s.business_group=?" if bg else ""), ((bg,) if bg else ())).fetchall()
    return {(r["sbg"], r["sco"]): r for r in rows}


def bu_scope_pick_key(s):
    """The ?bu_unit= value and session scope_key of a BU-level scope: a unit's name, or a group's 'grp:<id>'."""
    return BU_GROUP_PREFIX + str(s[2]) if len(s) > 2 else s[1]


def _bu_unit_pick(db, u, seats):
    """The unit (or calibration group, 2026-10-22) a leader with several BU-level scopes is working on: ?bu_unit= (one
    of theirs, remembered in the session), else the remembered one, else the first not yet locked on both axes, else
    the first. `seats`: (bg, company) units and (bg, company, group id) groups."""
    if len(seats) < 2:
        return seats[0] if seats else None
    by_co = {bu_scope_pick_key(s_): s_ for s_ in seats}
    if has_request_context():
        want = (request.values.get("bu_unit") or "").strip()
        if want in by_co:
            session["bu_unit"] = want
            return by_co[want]
        if session.get("bu_unit") in by_co:
            return by_co[session["bu_unit"]]
    cid = active_cycle_id(db)
    for s_ in seats:
        bg, key = s_[0], bu_scope_pick_key(s_)
        pm = db.execute("SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=? "
                        "AND business_group=?", (cid or 0, key, bg)).fetchone()
        pot = db.execute("SELECT locked_at FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=? "
                         "AND business_group=?", (cid or 0, key, bg)).fetchone()
        if not (pm and pm["locked_at"] and pot and pot["locked_at"]):
            return s_
    return seats[0]


def _sync_buceo_primary(db, uid):
    """users.buceo_bg / buceo_company = the person's first seat, or nothing -- the columns every older read uses."""
    first = db.execute("SELECT business_group, company FROM buceo_seats WHERE user_id=? ORDER BY business_group, company "
                       "LIMIT 1", (uid,)).fetchone()
    db.execute("UPDATE users SET buceo_bg=?, buceo_company=? WHERE id=?",
               ((first[0], first[1]) if first else (None, None)) + (uid,))
    _req_cache().pop("_bus_%s" % uid, None)


def calib_join(db, cid, bg, company):
    """{"lead", "members", "label"} when (bg, company) is calibrated together with other units in cycle `cid` (admin
    round 4, row 6), else None. Members in unit order, the lead first. Cached per request."""
    if not (cid and bg and company):
        return None
    cache = _req_cache()
    k = "_cj_%s_%s_%s" % (cid, bg, company)
    if k not in cache:
        r = db.execute("SELECT lead FROM calib_unit_joins WHERE cycle_id=? AND business_group=? AND company=?",
                       (cid, bg, company)).fetchone()
        out = None
        if r:
            rows = db.execute("SELECT company, curve_of FROM calib_unit_joins WHERE cycle_id=? AND business_group=? "
                              "AND lead=? ORDER BY company", (cid, bg, r["lead"])).fetchall()
            mem = [x[0] for x in rows]
            mem = [r["lead"]] + [m for m in mem if m != r["lead"]]
            if len(mem) > 1:
                cof = next((x[1] for x in rows if x[1]), None)
                # the one PAT curve the joined population follows: the unit the super admin picked, else the lead's
                out = {"lead": r["lead"], "members": mem, "label": _join_label(bg, mem),
                       "curve_of": cof if cof in mem else r["lead"]}
        cache[k] = out
    return cache[k]


def _join_label(bg, members):
    """'[Unit B] and [Unit D]' / '[A], [B] and [C]' in display names."""
    names = [display_company(bg, m) or m for m in members]
    return names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]


# Calibration groups in a unit (Chris, 2026-10-22; canvas [design canvas link removed], his picks
# 2A / 3A / 4A): a named set of one unit's departments that the leader the super admin names (a CFO, a COO) calibrates at
# BU CEO level instead of the unit's BU CEO; every other department stays with the BU CEO. A group's session is tier
# 'buceo' with scope_key 'grp:<id>', so every reader of a person's BU CEO band asks bu_scope_key(). The group follows its
# unit's PAT curve and the BU CEO's curve rule on its own (3A); the BU CEO sees its people read only (4A).
BU_GROUP_PREFIX = "grp:"

# A calibration panel's tag (Chris, 2026-11-04, canvas "BGCFO: the BG CFO's tag on a calibration panel"): 'CG' is the
# Calibrator (CG), as every panel was before; 'BGCFO' is a business group's CFO calibrating that group's finance people.
# A label only: the abilities stay the Calibrator role's (cg.*), the gates, bands and the view key ("bu") do not move.
# short = the chip / tab / switch; word = the Roles line; full = the role's name. Anything else is read as CG
# (bu_panel_tag). The calibrators' own dicts already have a `tag` (their short label), so the panel's rides as `role_tag`.
BU_PANEL_TAGS = {"CG": {"short": "CG", "word": "Calibrator", "full": "Calibrator (CG)"},
                 "BGCFO": {"short": "BGCFO", "word": "BG CFO", "full": "BG CFO (BGCFO)"}}


def bu_panel_tag(v):
    """'CG' or 'BGCFO' for a stored tag: anything else (a NULL, a stray value) reads as CG."""
    return v if v in BU_PANEL_TAGS and v != "CG" else "CG"


def bu_groups_all(db):
    """{id: row + `depts` (a set of (unit, department)) + `people` ({user id: unit}) + `units` (its units, sorted)} of
    the active calibrators, read once per request. Each calibrator is a calib_bu_groups row of a panel (`panel_id`,
    2026-10-26); `company` is the unit whose PAT its curve follows (the panel's)."""
    cache = _req_cache()
    if "_bug_all" not in cache:
        try:
            gs = {r["id"]: dict(r, depts=set(), people={}, role_tag=bu_panel_tag(r["role_tag"])) for r in db.execute(
                "SELECT g.*, (SELECT p.tag FROM calib_bu_panels p WHERE p.id=g.panel_id) AS role_tag "
                "FROM calib_bu_groups g WHERE g.active=1")}
            for r in db.execute("SELECT group_id, company, department FROM calib_bu_group_units"):
                if r[0] in gs:
                    gs[r[0]]["depts"].add((r[1], r[2]))
            for r in db.execute("SELECT p.group_id, u.id, u.company FROM calib_bu_group_people p JOIN users u ON "
                                "u.id=p.user_id AND u.business_group=p.business_group"):
                if r[0] in gs:
                    gs[r[0]]["people"][r[1]] = r[2]
        except sqlite3.OperationalError:   # before the migration has run
            gs = {}
        for g in gs.values():
            g["left"] = set()   # the units this calibrator takes "everyone left" in (2026-10-27)
        try:
            for r in db.execute("SELECT group_id, company FROM calib_bu_group_left"):
                if r[0] in gs:
                    gs[r[0]]["left"].add(r[1])
        except sqlite3.OperationalError:   # before the migration has run
            pass
        idx, ppl, lft = {}, {}, {}
        for g in sorted(gs.values(), key=lambda x: x["id"]):
            g["units"] = sorted({c for c, _d in g["depts"]} | {c for c in g["people"].values() if c} | g["left"]
                                or {g["company"]})
            g["split"] = 100   # the BU CEO no longer shares a group's call (2026-10-26): several calibrators do
            for c, d in g["depts"]:
                idx.setdefault((g["business_group"], c, d), []).append(g)
            for uid in g["people"]:
                ppl.setdefault(uid, []).append(g)
            for c in g["left"]:
                lft.setdefault((g["business_group"], c), []).append(g)
        cache["_bug_all"], cache["_bug_idx"], cache["_bug_ppl"], cache["_bug_left"] = gs, idx, ppl, lft
    return cache["_bug_all"]


def bu_panels_all(db):
    """{id: panel row + `units` (sorted) + `groups` (its active calibrators, in id order) + `weights` ({combo: {group id:
    weight}})} of the active calibration panels (2026-10-26), read once per request."""
    cache = _req_cache()
    if "_bup_all" not in cache:
        try:
            ps = {r["id"]: dict(r, units=[], groups=[], weights={}, role_tag=bu_panel_tag(r["tag"])) for r in db.execute(
                "SELECT * FROM calib_bu_panels WHERE active=1")}
            for r in db.execute("SELECT panel_id, company FROM calib_bu_panel_units ORDER BY company"):
                if r[0] in ps:
                    ps[r[0]]["units"].append(r[1])
            for r in db.execute("SELECT panel_id, combo, group_id, weight FROM calib_bu_panel_weights"):
                if r[0] in ps:
                    ps[r[0]]["weights"].setdefault(r[1], {})[r[2]] = r[3]
        except sqlite3.OperationalError:   # before the migration has run
            ps = {}
        for g in sorted(bu_groups_all(db).values(), key=lambda x: x["id"]):
            if g.get("panel_id") in ps:
                ps[g["panel_id"]]["groups"].append(g)
        cache["_bup_all"] = ps
    return cache["_bup_all"]


def bu_groups_forget():
    """Drop the request's cached calibrators and panels (after one is written)."""
    cache = _req_cache()
    for k in ("_bug_all", "_bug_idx", "_bug_ppl", "_bug_left", "_bup_all"):
        cache.pop(k, None)


_BUG_NO_COL = object()


def _bu_groups_of_person(db, subject, left=True):
    """The resolver behind bu_groups_of_person; `left=False` reads only the first two tiers (a panel's own check of who
    else holds someone by name or department)."""
    if not subject or not bu_groups_all(db):
        return []
    cache = _req_cache()
    named = cache.get("_bug_ppl", {}).get(_row_get(subject, "id") or _row_get(subject, "subject_id"))
    if named:   # picked by name: those calibrators whatever their department (2026-10-22)
        return list(named)
    bg, co = (_row_get(subject, "business_group") or ""), (_row_get(subject, "company") or "")
    dept = _row_get(subject, "department", _BUG_NO_COL)
    if dept is _BUG_NO_COL:   # a row read without its department: fetch it, but only where the unit has a calibrator
        if not any(g["business_group"] == bg and co in g["units"] for g in bu_groups_all(db).values()):
            return []
        sid = _row_get(subject, "id") or _row_get(subject, "subject_id")
        r = db.execute("SELECT department FROM users WHERE id=?", (sid,)).fetchone() if sid else None
        dept = r[0] if r else None
    hit = cache.get("_bug_idx", {}).get((bg, co, (dept or "").strip()))
    if hit:
        return list(hit)
    # everyone left in the unit (2026-10-27): whoever no calibrator names and none holds the department of
    return list(cache.get("_bug_left", {}).get((bg, co), [])) if left else []


def bu_groups_of_person(db, subject):
    """Every calibrator who calibrates this person at BU level, in id order (2026-10-26: "same person can be assign to
    more than one calibrator"). In this order, the first tier that has anyone decides (2026-10-27): the ones naming them
    (a name picked wins over their department); else the ones holding their department in their own unit; else the
    ones who took "Everyone left" in their unit. [] for someone their BU CEO calibrates."""
    return _bu_groups_of_person(db, subject, True)


def bu_group_of(db, subject):
    """The first calibrator of this person (their only one, for most grouped people), or None."""
    gs = bu_groups_of_person(db, subject)
    return gs[0] if gs else None


def bu_panel_of(db, subject):
    """The calibration panel this person sits in, or None."""
    g = bu_group_of(db, subject)
    return bu_panels_all(db).get(g.get("panel_id")) if g else None


def bu_scope_key(db, subject):
    """The scope key of this person's BU CEO tier: their (first) calibrator's 'grp:<id>', else their own unit. A person
    with several calibrators has a key each (bu_scope_keys) and a blended band (bu_panel_call)."""
    g = bu_group_of(db, subject)
    return BU_GROUP_PREFIX + str(g["id"]) if g else subject["company"]


def bu_scope_keys(db, subject):
    """Every BU-level scope key of this person: one per calibrator (2026-10-26), else their unit."""
    gs = bu_groups_of_person(db, subject)
    return [BU_GROUP_PREFIX + str(g["id"]) for g in gs] if gs else [subject["company"]]


def bu_shared(db, subject):
    """Whether several calibrators share this person's BU-level band."""
    return len(bu_groups_of_person(db, subject)) > 1


def bu_group(db, gid):
    """One active calibrator (calib_bu_groups row) by id, or None."""
    try:
        return bu_groups_all(db).get(int(gid))
    except (TypeError, ValueError):
        return None


def bu_panel(db, pid):
    """One active panel by id, or None."""
    try:
        return bu_panels_all(db).get(int(pid))
    except (TypeError, ValueError):
        return None


def bu_groups_of_unit(db, bg, company):
    """The active calibrators holding anyone of this unit (a panel can reach several units, 2026-10-22)."""
    return sorted((g for g in bu_groups_all(db).values() if g["business_group"] == bg and company in g["units"]),
                  key=lambda g: (g["name"].lower(), g["id"]))


def bu_groups_of_bg(db, bg):
    return sorted((g for g in bu_groups_all(db).values() if g["business_group"] == bg),
                  key=lambda g: (g["name"].lower(), g["id"]))


def bu_panels_of_bg(db, bg):
    return sorted((p for p in bu_panels_all(db).values() if p["business_group"] == bg),
                  key=lambda p: (p["name"].lower(), p["id"]))


def bu_groups_of_calibrator(db, uid):
    return sorted((g for g in bu_groups_all(db).values() if g["calibrator_id"] == uid),
                  key=lambda g: (g["company"], g["name"].lower(), g["id"]))


def _calibrator_group_names(db, ids=None):
    """{user id: [group names]} of everyone who calibrates an active calibration group (the CG tag, 2026-10-26), one
    batched read of the cached groups; `ids` narrows it to those on screen. Names repeat across a panel: listed once."""
    ids = set(ids) if ids is not None else None
    out = {}
    for g in sorted(bu_groups_all(db).values(), key=lambda x: ((x["name"] or "").lower(), x["id"])):
        uid = g["calibrator_id"]
        if uid is None or (ids is not None and uid not in ids):
            continue
        if g["name"] not in out.setdefault(uid, []):
            out[uid].append(g["name"])
    return out


def _calibrator_tags(db, ids=None):
    """{user id: {"CG": [panel names], "BGCFO": [panel names]}} of everyone who calibrates an active panel, by the panel's
    tag (BGCFO tag, 2026-11-04): one batched read of the cached groups, like _calibrator_group_names; `ids` narrows it to
    those on screen. A kind a person has no panel of is absent; names repeat across a panel: listed once."""
    ids = set(ids) if ids is not None else None
    out = {}
    for g in sorted(bu_groups_all(db).values(), key=lambda x: ((x["name"] or "").lower(), x["id"])):
        uid = g["calibrator_id"]
        if uid is None or (ids is not None and uid not in ids):
            continue
        names = out.setdefault(uid, {}).setdefault(bu_panel_tag(g.get("role_tag")), [])
        if g["name"] not in names:
            names.append(g["name"])
    return out


def bu_group_label(bg, g):
    """'Sales & shared services · Coral Living and Coral Trading': the panel, then its units, or how many."""
    us = g.get("units") or [g["company"]]
    where = (" and ".join(display_company(bg, c) or c for c in us) if len(us) <= 2 else "%d units" % len(us))
    return "%s · %s" % (g["name"], where)


def bu_group_split(g):
    """A group's old split with the BU CEO: always 100 now (2026-10-26). The BU CEO shares a call as one of a panel's
    calibrators, by the panel's weights, never by a split."""
    return 100


def bu_combo(gids):
    """A set of calibrators as calib_bu_panel_weights keys it: their row ids in order, joined by commas."""
    return ",".join(str(int(g)) for g in sorted(gids))


def bu_equal_weights(gids):
    """Equal whole-number shares adding up to 100, the first calibrators taking the remainder: 50/50, 34/33/33."""
    gids = sorted(gids)
    if not gids:
        return {}
    base, extra = divmod(100, len(gids))
    return {g: base + (1 if i < extra else 0) for i, g in enumerate(gids)}


def bu_weights_for(db, groups):
    """{calibrator id: weight} for one person's calibrators: 100 for one; for several, the panel's saved weights for
    that set of calibrators, or equal shares where none is saved (or it no longer adds up)."""
    gids = sorted(g["id"] for g in groups or ())
    if len(gids) <= 1:
        return {gids[0]: 100} if gids else {}
    p = bu_panels_all(db).get(groups[0].get("panel_id")) or {}
    w = (p.get("weights") or {}).get(bu_combo(gids)) or {}
    if set(w) == set(gids) and sum(w.values()) == 100 and all((v or 0) > 0 for v in w.values()):
        return {g: int(w[g]) for g in gids}
    return bu_equal_weights(gids)


def bu_blend_n(parts, order):
    """The BU-level band from several calibrators' bands (Chris, 2026-10-26): each band as its place in `order` (UA 1 ...
    OU 5; Low 1, Mid 2, High 3), weighted, averaged and rounded; exactly halfway takes the LOWER band ("ME (average of
    Calibrator A (50%) - ME, and Calibrator B (50%) - AE"). `parts`: (band, weight); one with no band is left out and
    the others share its weight. None when no part has a band."""
    o = list(order)
    ps = [(o.index(b), w) for b, w in parts if b in o and (w or 0) > 0]
    if not ps:
        return None
    x = sum(i * w for i, w in ps) / float(sum(w for _i, w in ps))
    lo = int(math.floor(x + 1e-9))
    return o[lo] if x - lo <= 0.5 + 1e-9 else o[min(lo + 1, len(o) - 1)]


def bu_blend(cal_band, ceo_band, split, order):
    """Two bands blended by a split (the first `split`, the second the rest): bu_blend_n's rule, exactly halfway the
    lower. One band in: that one."""
    return bu_blend_n([(cal_band, split), (ceo_band, 100 - split)], order)


def _bu_cal_tag(c, name):
    """A calibrator's short tag: the C-suite initials of a "Chief ... Officer" title (CFO, COO), else `name`."""
    title = proper_name(c["job_title"]) if c and c["job_title"] else ""
    words = [w for w in re.split(r"[\s,/-]+", title) if w]
    low = [w.lower() for w in words]
    tag = ""
    if "chief" in low:
        tag = "".join(w[0].upper() for w in words[low.index("chief"):]
                      if w.lower() not in ("of", "and", "the", "&") and w[0].isalpha())
    return tag if 2 <= len(tag) <= 5 else name


def bu_cal_parts(db, axis, cycle_id, subject, groups=None):
    """Each calibrator's part in this person's BU-level band (2026-10-26), in calibrator order: {gid, key, who, title,
    tag, weight, band (their band on them as it stands, None where they haven't moved them), locked (their session
    locked), note, locked_at, locked_by}. Two reads for the person."""
    groups = groups if groups is not None else bu_groups_of_person(db, subject)
    if not groups:
        return []
    st, at = (("pm_calibration_sessions", "pm_calibration_adjustments") if axis == "pm"
              else ("calibration_sessions", "calibration_adjustments"))
    keys = [BU_GROUP_PREFIX + str(g["id"]) for g in groups]
    rows = {r["scope_key"]: r for r in db.execute(
        "SELECT cs.scope_key, cs.locked_at, cs.locked_by, ca.adjusted_band, ca.justification FROM %s cs LEFT JOIN %s ca "
        "ON ca.session_id=cs.id AND ca.subject_id=? WHERE cs.cycle_id=? AND cs.tier='buceo' AND cs.scope_key IN (%s)"
        % (st, at, ",".join("?" * len(keys))), [subject["id"], cycle_id] + keys)}
    cal_ids = sorted({g["calibrator_id"] for g in groups})
    names = {r["id"]: r for r in db.execute("SELECT id, full_name, job_title FROM users WHERE id IN (%s)"
                                            % ",".join("?" * len(cal_ids)), cal_ids)}
    w = bu_weights_for(db, groups)
    out = []
    for g, k in zip(groups, keys):
        r, c = rows.get(k), names.get(g["calibrator_id"])
        out.append({"gid": g["id"], "key": k, "who": c["full_name"] if c else "their calibrator",
                    "title": proper_name(c["job_title"]) if c and c["job_title"] else "",
                    "tag": _bu_cal_tag(c, (c["full_name"] if c else g["name"])), "weight": w.get(g["id"], 0),
                    "band": (r["adjusted_band"] if r else None) or None, "locked": bool(r and r["locked_at"]),
                    "note": ((r["justification"] if r else "") or "").strip(),
                    "locked_at": r["locked_at"] if r else None, "locked_by": r["locked_by"] if r else None})
    return out


def _bu_came_in(db, axis, cycle_id, subject, raw_band=None):
    """The band that came in to the BU level for this person: the tiers below it (HOD, line manager, their own)."""
    skip = ("super", "group", "bgceo", "buceo")
    if axis == "pm":
        return (pm_effective_band(db, subject, cycle_id, raw_band, skip_tiers=skip) or {}).get("band")
    return (effective_band(db, subject, cycle_id, skip_tiers=skip) or {}).get("band")


def bu_panel_call(db, axis, cycle_id, subject, came_in=None, raw_band=None, parts=None):
    """(band, note, {locked_at, locked_by}) of a person several calibrators share (2026-10-26): the bands of those who
    have LOCKED, weighted (bu_blend_n); a calibrator who locked without moving them keeps the band that came in. Each
    counts once their own session is locked, as every tier does; None while none has locked."""
    parts = parts if parts is not None else bu_cal_parts(db, axis, cycle_id, subject)
    locked = [p for p in parts if p["locked"]]
    if not locked:
        return None
    if came_in is None and any(not p["band"] for p in locked):
        came_in = _bu_came_in(db, axis, cycle_id, subject, raw_band)
    band = bu_blend_n([(p["band"] or came_in, p["weight"]) for p in locked],
                      PM_BAND_ORDER if axis == "pm" else list(_POT_BANDS))
    if not band:
        return None
    last = max(locked, key=lambda p: p["locked_at"] or "")
    note = "; ".join("%s: %s" % (p["who"], p["note"]) for p in locked if p["note"])
    return band, note, {"locked_at": last["locked_at"], "locked_by": last["locked_by"]}


def bu_parts_view(db, axis, cycle_id, subject, raw_band=None):
    """What a leader reads of one person's BU level (Chris, 2026-10-26: "it should show for the calibrated band,
    (calibrator name, weigh, final band)"): {parts: [{who, title, tag, weight, band, locked, kept}], band, waiting}, or
    None for someone their BU CEO calibrates. A locked calibrator who left them as they came in shows that band, kept."""
    parts = bu_cal_parts(db, axis, cycle_id, subject)
    if not parts:
        return None
    came = None
    if any(p["locked"] for p in parts):   # what a locked calibrator kept, or moved them from
        came = _bu_came_in(db, axis, cycle_id, subject, raw_band)
    call = bu_panel_call(db, axis, cycle_id, subject, came_in=came, parts=parts)
    return {"parts": [{"who": p["who"], "title": p["title"], "tag": p["tag"], "weight": p["weight"],
                       "band": (p["band"] or came) if p["locked"] else None, "locked": p["locked"],
                       "kept": p["locked"] and not p["band"], "note": p["note"] if p["locked"] else ""}
                      for p in parts],
            "band": call[0] if call else None, "came_in": came,
            "waiting": [p["who"] for p in parts if not p["locked"]]}


def bu_level_trail(db, axis, cycle_id, subject, came_in=None, raw_band=None, parts=None):
    """The BU level of someone several calibrators share, as trail entries (Chris, 2026-10-26: "with more than one
    calibrator, it should show as Calibrator A, Calibrator B, Average of Calibration band ... and the AI should pick
    these up first for the AI insight"): one per calibrator who has LOCKED -- their band, or the band that came in where
    they kept it, with their weight and note -- then the weighted average (bu_blend_n). [] for one calibrator or while
    none has locked: a tier's working state never shows, as everywhere."""
    parts = parts if parts is not None else bu_cal_parts(db, axis, cycle_id, subject)
    locked = [p for p in parts if p["locked"]]
    if len(parts) < 2 or not locked:
        return []
    if came_in is None:
        came_in = _bu_came_in(db, axis, cycle_id, subject, raw_band)
    order = PM_BAND_ORDER if axis == "pm" else list(_POT_BANDS)
    out = [{"tier": "buceo", "cal": True, "label": "BU level · %s (%d%%)" % (p["who"], p["weight"]),
            "by": p["who"], "weight": p["weight"], "from": came_in, "band": p["band"] or came_in, "seen": came_in,
            "note": p["note"]} for p in locked]
    out.append({"tier": "buceo", "avg": True, "label": "Calibration average", "by": "", "from": came_in,
                "band": bu_blend_n([(p["band"] or came_in, p["weight"]) for p in locked], order), "seen": came_in,
                "note": "", "waiting": [p["who"] for p in parts if not p["locked"]]})
    return out


def bu_groups_by(db, groups):
    """Who calibrates a person, for the BU CEO's read-only rows and the Talent Box (Chris's pick 4A; several since
    2026-10-26): a short tag (each calibrator's: the C-suite initials of a "Chief ... Officer" title, e.g. CFO, else
    the panel's name for a panel of one, the calibrator's initials in a panel of several, joined by +) and the whole
    line on hover, with the weights."""
    groups = [g for g in groups or () if g]
    if not groups:
        return {}
    ids = sorted({g["calibrator_id"] for g in groups})
    cs = {r["id"]: r for r in db.execute("SELECT id, full_name, job_title FROM users WHERE id IN (%s)"
                                         % ",".join("?" * len(ids)), ids)}
    w = bu_weights_for(db, groups)
    p = bu_panels_all(db).get(groups[0].get("panel_id")) or {}
    pname = p.get("name") or groups[0]["name"]

    def who(g):
        c = cs.get(g["calibrator_id"])
        t = proper_name(c["job_title"]) if c and c["job_title"] else ""
        return (c["full_name"] if c else "their calibrator") + (", " + t if t else "")
    # a calibrator of a panel with several, by their C-suite initials, else their name's initials (CA + CB + CFO): the
    # row's name keeps its room; a panel of one keeps its name as the tag
    ini = lambda n: "".join(x_[0].upper() for x_ in re.split(r"[\s,/-]+", n or "") if x_[:1].isalpha())[:3] or "?"
    short = lambda g: _bu_cal_tag(cs.get(g["calibrator_id"]), ini(cs[g["calibrator_id"]]["full_name"]
                                                                  if g["calibrator_id"] in cs else ""))
    if len(groups) == 1:
        c = cs.get(groups[0]["calibrator_id"])
        tag = short(groups[0]) if len(p.get("groups") or []) > 1 else _bu_cal_tag(c, pname)
        title = "%s · calibrated by %s" % (pname, who(groups[0]))
    else:
        tag = " + ".join(short(g) for g in groups)
        title = "%s · calibrated by %s" % (pname, "; ".join("%s (%d%%)" % (who(g), w.get(g["id"], 0)) for g in groups))
    return {"by": tag, "by_title": title, "group": pname, "group_id": groups[0]["id"],
            "panel_id": groups[0].get("panel_id"), "n_cal": len(groups)}


def bu_group_by(db, g):
    """bu_groups_by for one calibrator (the older callers)."""
    return bu_groups_by(db, [g] if g else [])


def _bu_left_tier_sql(t="users"):
    """SQL on the users row `t`: no active calibrator names them and none holds their department in their own unit, so
    "Everyone left" (2026-10-27) is the tier that decides."""
    return ("(NOT EXISTS (SELECT 1 FROM calib_bu_group_people glp_ JOIN calib_bu_groups glq_ ON glq_.id=glp_.group_id "
            "WHERE glq_.active=1 AND glp_.user_id={t}.id AND glp_.business_group={t}.business_group) AND NOT EXISTS "
            "(SELECT 1 FROM calib_bu_group_units glu_ JOIN calib_bu_groups glw_ ON glw_.id=glu_.group_id WHERE "
            "glw_.active=1 AND glu_.business_group={t}.business_group AND glu_.company={t}.company AND "
            "glu_.department=TRIM(COALESCE({t}.department,''))))").format(t=t)


def bu_grouped_sql(t="users"):
    """SQL on the users row `t`: an active calibration group holds this person's department in their own unit, or
    picked them by name, or took everyone left in their unit and nobody else holds them (2026-10-27)."""
    return ("(EXISTS (SELECT 1 FROM calib_bu_group_units gd_ JOIN calib_bu_groups gg_ ON gg_.id=gd_.group_id "
            "WHERE gg_.active=1 AND gd_.business_group={t}.business_group AND gd_.company={t}.company "
            "AND gd_.department=TRIM(COALESCE({t}.department,''))) OR EXISTS (SELECT 1 FROM calib_bu_group_people gp_ "
            "JOIN calib_bu_groups gq_ ON gq_.id=gp_.group_id WHERE gq_.active=1 AND gp_.user_id={t}.id "
            "AND gp_.business_group={t}.business_group) OR (EXISTS (SELECT 1 FROM calib_bu_group_left gl_ JOIN "
            "calib_bu_groups gk_ ON gk_.id=gl_.group_id WHERE gk_.active=1 AND gl_.business_group={t}.business_group "
            "AND gl_.company={t}.company) AND {lt}))").format(t=t, lt=_bu_left_tier_sql(t))


def bu_unit_others(db, cid, bg, units, axis="pm"):
    """The people of these units whose departments sit in a calibration group, under the axis's own population rule:
    the BU CEO reads them and never moves them (Chris's pick 4A, 2026-10-22)."""
    if not units or not bu_groups_all(db):
        return []
    pop_sql, pop_args = ((pm_calibration_population_sql(), [cid]) if axis == "pm" else (calibration_population_sql(), []))
    return db.execute("SELECT * FROM users WHERE business_group=? AND company IN (%s) AND role!='admin' AND %s AND %s "
                      "ORDER BY full_name" % (",".join("?" * len(units)), bu_grouped_sql(), pop_sql),
                      [bg] + list(units) + pop_args).fetchall()


def bu_group_member_sql(t="users"):
    """SQL on the users row `t`, one ? = the calibrator's id: they name this person, or hold their department in their
    own unit and no calibrator names them (a name picked wins over the department, 2026-10-22; with several calibrators
    a person named goes only to those who name them, 2026-10-26), or took everyone left in their unit and no other
    tier holds them (2026-10-27). The caller also holds them to the business group."""
    return ("{t}.id IN (SELECT u_.id FROM (SELECT ? AS gid) k_ JOIN users u_ ON EXISTS (SELECT 1 FROM "
            "calib_bu_group_people gp_ WHERE gp_.group_id=k_.gid AND gp_.user_id=u_.id) OR (EXISTS (SELECT 1 FROM "
            "calib_bu_group_units gm_ WHERE gm_.group_id=k_.gid AND gm_.company=u_.company AND "
            "gm_.business_group=u_.business_group AND gm_.department=TRIM(COALESCE(u_.department,''))) AND NOT EXISTS "
            "(SELECT 1 FROM calib_bu_group_people gx_ JOIN calib_bu_groups gy_ ON gy_.id=gx_.group_id WHERE "
            "gy_.active=1 AND gx_.user_id=u_.id AND gx_.business_group=u_.business_group)) OR (EXISTS (SELECT 1 FROM "
            "calib_bu_group_left gl_ WHERE gl_.group_id=k_.gid AND gl_.company=u_.company AND "
            "gl_.business_group=u_.business_group) AND {lt}))").format(t=t, lt=_bu_left_tier_sql("u_"))


CALIB_DEPT_FILTER_VIEWS = (("bu", "BU CEO calibration"), ("tb", "BG CEO Talent Box"))


def calib_dept_filter_map(db, bg):
    """{(company, view): True} for the units of business group `bg` whose department filter the super admin switched on
    (calib_dept_filter). Everything else is hidden."""
    try:
        return {(r[0], r[1]): True for r in db.execute(
            "SELECT company, view FROM calib_dept_filter WHERE business_group=? AND shown=1", (bg or "",))}
    except sqlite3.OperationalError:   # pre-migration DB
        return {}


CALIB_CAL_FILTER_VIEWS = (("tb", "BG CEO Talent Box"),)   # "Talent Box only for now" (Chris, 2026-10-26)


def calib_cal_filter_map(db, bg):
    """{(company, view): shown} of the calibrator filter rows the super admin saved for a business group."""
    try:
        return {(r[0], r[1]): bool(r[2]) for r in db.execute(
            "SELECT company, view, shown FROM calib_cal_filter WHERE business_group=?", (bg or "",))}
    except sqlite3.OperationalError:
        return {}


def calib_cal_filter_shown(db, bg, companies, view):
    """Whether the CAL row shows on `view` for the unit(s) on screen (Chris, 2026-10-26: "can the BU calibrator becomes
    the filter here", then canvas A: DEPT | CAL | JG, each on or off): only where a unit has BU-level calibrators, on the
    BG CEO's Talent Box ("Talent Box only for now"); shown unless the super admin switched it off on Calibration &
    Talent › Settings › Filters at BU level."""
    cos = [c for c in (companies or []) if c]
    if not bg or not cos or view not in dict(CALIB_CAL_FILTER_VIEWS):
        return False
    off = calib_cal_filter_map(db, bg)
    return any(bu_groups_of_unit(db, bg, c) and off.get((c, view), True) for c in cos)


def calib_dept_filter_shown(db, bg, companies, view):
    """Whether the department pill row shows on `view` ('bu': a BU CEO's calibration, both axes; 'tb': the BG CEO's
    Talent Box) for the unit(s) on screen -- units calibrated together show it when any one of them has it on. Hidden
    unless the super admin switched it on (Chris, 2026-10-17: "hide the department filter, make it a setting configurable
    by super admin to show or hide it ... make it BU specific")."""
    cos = [c for c in (companies or []) if c]
    if not bg or not cos or view not in dict(CALIB_DEPT_FILTER_VIEWS):
        return False
    try:
        return db.execute("SELECT 1 FROM calib_dept_filter WHERE business_group=? AND view=? AND shown=1 AND company IN "
                          "(%s) LIMIT 1" % ",".join("?" * len(cos)), [bg, view] + cos).fetchone() is not None
    except sqlite3.OperationalError:
        return False


# THE JOB GRADE FILTER (Chris, 2026-10-21: "add one more configuration for JG display ... the super admin can define the
# band of JG12-14, 15-18, 19 and above, or just individual JG as selection filter"; canvas "OneHR JG Filter", built as
# Max recommended): shown per unit and view like the department filter, the grades grouped per business group.
CALIB_JG_DEFAULT_BANDS = ({"name": "", "lo": 12, "hi": 14}, {"name": "", "lo": 15, "hi": 18},
                          {"name": "", "lo": 19, "hi": None})
CALIB_JG_MAX_BANDS = 6
CALIB_JG_NAME_MAX = 30
CALIB_JG_GRADE_MAX = 30   # the highest grade a band's edge can name
CALIB_JG_SMALL = 10   # under this many people a filtered curve shows counts, never "fewer / more than expected"


def calib_jg_band_name(b):
    """A band's pill: its own name, else its range ("JG 12–14", "JG 19 and above", "JG 15")."""
    if (b.get("name") or "").strip():
        return b["name"].strip()
    if b.get("hi") is None:
        return "JG %d and above" % b["lo"]
    return "JG %d" % b["lo"] if b["hi"] == b["lo"] else "JG %d–%d" % (b["lo"], b["hi"])


def calib_jg_band_key(b):
    """A band's stable key: its range, "12-14" or "19-" (and above)."""
    return "%d-%s" % (b["lo"], "" if b.get("hi") is None else b["hi"])


def calib_jg_config(db, bg):
    """{"mode": "bands" | "each", "bands": [{name, lo, hi}], "set": bool} for business group `bg`: what the super admin
    saved, else the default bands (12-14, 15-18, 19 and above). A stored grouping that no longer reads is the default."""
    row = None
    try:
        row = db.execute("SELECT mode, bands FROM calib_jg_bands WHERE business_group=?", (bg or "",)).fetchone()
    except sqlite3.OperationalError:   # pre-migration DB
        pass
    if row:
        try:
            bands = [{"name": str(b.get("name") or "")[:CALIB_JG_NAME_MAX], "lo": int(b["lo"]),
                      "hi": None if b.get("hi") is None else int(b["hi"])} for b in json.loads(row["bands"] or "[]")]
        except (ValueError, TypeError, KeyError, AttributeError):
            bands = []
        mode = row["mode"] if row["mode"] in ("bands", "each") else "bands"
        if mode == "each" or bands:
            return {"mode": mode, "bands": bands or [dict(b) for b in CALIB_JG_DEFAULT_BANDS], "set": True}
    return {"mode": "bands", "bands": [dict(b) for b in CALIB_JG_DEFAULT_BANDS], "set": False}


def calib_jg_bands_error(bands, floor=None):
    """Why a set of bands can't be saved, else None: 2 to 6 bands, each From at or under its To, no grade in two bands,
    no grade between two bands, the last one running "and above" (a JG above it would match no pill), and the first
    starting at or under `floor` (the cycle's minimum grade) so every grade that takes part has a pill."""
    if len(bands) < 2:
        return "Give at least two bands, or pick Each grade on its own."
    if len(bands) > CALIB_JG_MAX_BANDS:
        return "At most %d bands." % CALIB_JG_MAX_BANDS
    bs = sorted(bands, key=lambda b: b["lo"])
    for i, b in enumerate(bs):
        if b["hi"] is not None and b["hi"] < b["lo"]:
            return "%s ends below where it starts." % calib_jg_band_name(b)
        if b["hi"] is None and i < len(bs) - 1:
            return "Only the last band can run “and above”."
        if i:
            prev = bs[i - 1]
            if b["lo"] <= prev["hi"]:
                return "JG %d is in two bands, %s and %s." % (b["lo"], calib_jg_band_name(prev), calib_jg_band_name(b))
            if b["lo"] > prev["hi"] + 1:
                gap = "JG %d" % (prev["hi"] + 1) if b["lo"] == prev["hi"] + 2 else \
                    "JG %d to %d" % (prev["hi"] + 1, b["lo"] - 1)
                return "%s is in no band. Stretch a band to cover it." % gap
    if bs[-1]["hi"] is not None:
        return "The last band stops at JG %d: let it run “and above”." % bs[-1]["hi"]
    if floor is not None and bs[0]["lo"] > floor:
        return "The first band starts at JG %d, above the cycle's minimum JG %d: start it at JG %d." % (
            bs[0]["lo"], floor, floor)
    return None


def calib_jg_key_of(cfg, grade):
    """The pill a job grade falls on: a band's key, the grade itself ("14") when each grade is its own, or "other" for
    a grade that isn't a number (H, GM) or sits under every band."""
    n = grade_num(grade)
    if n is None:
        return "other"
    if cfg["mode"] == "each":
        return str(n)
    for b in cfg["bands"]:
        if b["lo"] <= n and (b["hi"] is None or n <= b["hi"]):
            return calib_jg_band_key(b)
    return "other"


def calib_jg_options(cfg, grades):
    """[{key, label, n}] for the JG row over the job grades on screen: bands in order, or each grade held, lowest first;
    "Other" last, and only when someone holds one. A pill nobody would fill isn't drawn."""
    cnt = {}
    for g in grades:
        k = calib_jg_key_of(cfg, g)
        cnt[k] = cnt.get(k, 0) + 1
    if cfg["mode"] == "each":
        opts = [{"key": k, "label": "JG %s" % k, "n": cnt[k]} for k in sorted((k for k in cnt if k != "other"), key=int)]
    else:
        opts = [{"key": calib_jg_band_key(b), "label": calib_jg_band_name(b), "n": cnt.get(calib_jg_band_key(b), 0)}
                for b in sorted(cfg["bands"], key=lambda b: b["lo"])]
        opts = [o for o in opts if o["n"]]
    if cnt.get("other"):
        opts.append({"key": "other", "label": "Other", "n": cnt["other"]})
    return opts


def calib_jg_filter_map(db, bg):
    """{(company, view): True} for business group `bg`'s units whose JG row is switched on (calib_jg_filter)."""
    try:
        return {(r[0], r[1]): True for r in db.execute(
            "SELECT company, view FROM calib_jg_filter WHERE business_group=? AND shown=1", (bg or "",))}
    except sqlite3.OperationalError:   # pre-migration DB
        return {}


def calib_jg_filter_shown(db, bg, companies, view):
    """Whether the JG pill row shows on `view` ('bu' | 'tb') for the unit(s) on screen -- as calib_dept_filter_shown:
    hidden unless the super admin switched it on; units calibrated together show it when any one has it on."""
    cos = [c for c in (companies or []) if c]
    if not bg or not cos or view not in dict(CALIB_DEPT_FILTER_VIEWS):
        return False
    try:
        return db.execute("SELECT 1 FROM calib_jg_filter WHERE business_group=? AND view=? AND shown=1 AND company IN "
                          "(%s) LIMIT 1" % ",".join("?" * len(cos)), [bg, view] + cos).fetchone() is not None
    except sqlite3.OperationalError:
        return False


def calib_jg_payload(db, bg, companies, view, force=False):
    """The JG row's grouping for a BU CEO's calibration card, or None where it isn't switched on: the client keys each
    row's job_grade with the same rule (calJgKey mirrors calib_jg_key_of). `force`: a calibrator's own set has it on."""
    if not force and not calib_jg_filter_shown(db, bg, companies, view):
        return None
    cfg = calib_jg_config(db, bg)
    return {"mode": cfg["mode"], "small": CALIB_JG_SMALL,
            "bands": [{"key": calib_jg_band_key(b), "label": calib_jg_band_name(b), "lo": b["lo"], "hi": b["hi"]}
                      for b in sorted(cfg["bands"], key=lambda b: b["lo"])]}


# ---------------------------------------------------------------------------------------------------------------------
# THE FILTERABLE COLUMNS, ONE LIST (Chris, 2026-10-30, canvas "OneHR Calibration Filter Rules", Option 2 + boards C2 / D2).
# The calibration screens (view 'bu': a BU CEO's calibration, which a calibration group's calibrator shares; view 'tb': the
# BG CEO's Talent Box) filter by the columns listed here, in this order, on ONE filter line. The super admin switches each
# one on per unit and screen (Calibration & Talent > Settings > Filters at BU level, one rule per filter). To add a column
# (Employment type, say): one entry here -- "column" is the users column it reads, no "table" stores it in calib_filter,
# its roster values come from `column`, and the settings rule panel and both screens' chips follow. Department, Calibrator
# and Job grade keep the tables they have always used (their saved values do not move); Cost centre and Branch share
# calib_filter. A filter only narrows the view: no band, lock or move behaviour is tied to it.
#   key      the registry key, also the screens' request parameter (?dept= ?cal= ?jg= ?cc= ?branch=)
#   code     the short caps name under the label on the settings table; "note" its second half ("JG · grouped below")
#   views    the screens it can appear on; default: on without a saved row (only the Calibrator, where a unit has some)
#   proper   the roster's words go through proper_name on screen (departments and titles)
#   column   the users column a roster-backed filter reads (Calibrator has none; Job grade's is read through its bands)
#   chip     optional: the words the chip shows in place of the label ("CC", "JG"); no key = the label. The full label stays in
#            the hover and aria. bare: a picked value that already starts with the chip words shows alone ("JG 12–14", while a
#            band named "Senior" reads "JG: Senior")
#   noun     what the roster calls it, for "No one has a <noun>"; cover "count" says "7 departments" instead of "55 of 60 have one"
CALIB_NOT_SET = "~none"   # the explicit "Not set on the roster" pick of a roster column
CALIB_FILTER_SEARCH_MIN = 9   # a chip's list gets a search box from this many values
CALIB_FILTER_SCREENS = (("bu", "BU CEO view", "BU CEO calibration"),
                        ("tb", "Talent Box", "BG CEO Talent Box"))
CALIB_FILTERS = (
    {"key": "dept", "label": "Department", "plural": "departments", "code": "DEPT", "note": "", "views": ("bu", "tb"),
     "table": "calib_dept_filter", "default": False, "column": "department", "proper": True, "sub": "",
     "noun": "department", "cover": "count"},
    {"key": "cal", "label": "Calibrator", "plural": "calibrators", "code": "CAL", "note": "", "views": ("tb",),
     "table": "calib_cal_filter", "default": True, "column": None, "proper": False, "sub": ""},
    {"key": "jg", "label": "Job grade", "plural": "job grades", "code": "JG", "note": "grouped below",
     "views": ("bu", "tb"), "table": "calib_jg_filter", "default": False, "column": "job_grade", "proper": False,
     "sub": "", "chip": "JG", "bare": True},
    {"key": "cc", "label": "Cost centre", "plural": "cost centres", "code": "CC", "note": "", "views": ("bu", "tb"),
     "table": None, "default": False, "column": "cost_center", "proper": False,
     "sub": "From the roster's cost centre", "noun": "cost centre", "chip": "CC"},
    {"key": "branch", "label": "Branch", "plural": "branches", "code": "BRANCH", "note": "work location",
     "views": ("bu", "tb"), "table": None, "default": False, "column": "work_location", "proper": False,
     "sub": "From the roster's work location", "noun": "work location"},
)
CALIB_FILTER_KEYS = tuple(f["key"] for f in CALIB_FILTERS)


def calib_filter_def(key):
    return next((f for f in CALIB_FILTERS if f["key"] == key), None)


def calib_filter_map(db, bg, key):
    """{(company, view): shown} of the rows the super admin saved for filter `key` in business group `bg`: the filter's own
    table for Department / Calibrator / Job grade (the first two as they always read), calib_filter for the rest."""
    f = calib_filter_def(key)
    if not f:
        return {}
    if key == "dept":
        return calib_dept_filter_map(db, bg)
    if key == "jg":
        return calib_jg_filter_map(db, bg)
    if key == "cal":
        return calib_cal_filter_map(db, bg)
    try:
        return {(r[0], r[1]): bool(r[2]) for r in db.execute(
            "SELECT company, view, shown FROM calib_filter WHERE business_group=? AND filter_key=? AND shown=1",
            (bg or "", key))}
    except sqlite3.OperationalError:   # pre-migration DB
        return {}


def calib_filter_on(db, bg, key, company, view, saved=None):
    """Whether filter `key` is switched on for one unit on one screen: a saved shown row, else its default (the
    Calibrator's: on where the unit has calibrators). `saved` = calib_filter_map's answer, read once for a whole table."""
    f = calib_filter_def(key)
    if not f or view not in f["views"]:
        return False
    m = saved if saved is not None else calib_filter_map(db, bg, key)
    if f["default"]:
        return bool(bu_groups_of_unit(db, bg, company)) and bool(m.get((company, view), True))
    return bool(m.get((company, view)))


def calib_filter_shown(db, bg, companies, view, key):
    """Whether filter `key` shows on `view` for the unit(s) on screen (units calibrated together: when any one has it)."""
    f = calib_filter_def(key)
    cos = [c for c in (companies or []) if c]
    if not f or not bg or not cos or view not in f["views"]:
        return False
    if key == "dept":
        return calib_dept_filter_shown(db, bg, cos, view)
    if key == "cal":
        return calib_cal_filter_shown(db, bg, cos, view)
    if key == "jg":
        return calib_jg_filter_shown(db, bg, cos, view)
    try:
        return db.execute("SELECT 1 FROM calib_filter WHERE business_group=? AND view=? AND filter_key=? AND shown=1 AND "
                          "company IN (%s) LIMIT 1" % ",".join("?" * len(cos)), [bg, view, key] + cos).fetchone() is not None
    except sqlite3.OperationalError:
        return False


def calib_filters_shown(db, bg, companies, view):
    """The registry entries switched on for the unit(s) on `view`, in registry order -- the chips of the filter line."""
    return [f for f in CALIB_FILTERS if calib_filter_shown(db, bg, companies, view, f["key"])]


def calib_filter_chip(f):
    """The words a filter's chip shows in place of its label: the registry's "chip", else the label."""
    return f.get("chip") or f["label"]


def calib_filters_payload(db, bg, companies, view, only=None):
    """The filter line's chips for the BU CEO's calibration card (view 'bu'): what each registry filter is called and
    whether its words go through the proper-name rule. The rows carry the values; the card counts and narrows them.
    `only` (a set of registry keys: a calibrator with filters of its own, calib_card_filters) replaces the units' switches."""
    fs = calib_filters_shown(db, bg, companies, view) if only is None else \
        [f for f in CALIB_FILTERS if f["key"] in only and view in f["views"]]
    return [{"key": f["key"], "label": f["label"], "chip": calib_filter_chip(f), "bare": bool(f.get("bare")),
             "plural": f["plural"], "proper": bool(f["proper"]), "field": f["column"], "search": CALIB_FILTER_SEARCH_MIN}
            for f in fs]


def calib_filter_write(db, bg, company, view, key, shown, uid):
    """Save filter `key`'s switch for one unit and screen (no commit): its own table, or calib_filter."""
    f = calib_filter_def(key)
    if f["table"]:
        db.execute("INSERT INTO %s(business_group, company, view, shown, updated_by, updated_at) VALUES (?,?,?,?,?, "
                   "datetime('now')) ON CONFLICT(business_group, company, view) DO UPDATE SET shown=excluded.shown, "
                   "updated_by=excluded.updated_by, updated_at=excluded.updated_at" % f["table"],
                   (bg, company, view, 1 if shown else 0, uid))
    else:
        db.execute("INSERT INTO calib_filter(business_group, company, view, filter_key, shown, updated_by, updated_at) "
                   "VALUES (?,?,?,?,?,?, datetime('now')) ON CONFLICT(business_group, company, view, filter_key) DO "
                   "UPDATE SET shown=excluded.shown, updated_by=excluded.updated_by, updated_at=excluded.updated_at",
                   (bg, company, view, key, 1 if shown else 0, uid))


# ---------------------------------------------------------------------------------------------------------------------
# FILTERS PER VIEWER (Chris, 2026-11-02, canvas "OneHR Calibration Filters by Viewer", "Yes, as drawn"; his 31 Oct words: "they
# group usually has cross BG and cross BU people", "go with your suggestion"). The unit switches above say what a BU CEO and
# the BG CEO's Talent Box show. Three viewers hold people grouped differently, so each has its own set (calib_viewer_filter):
#   cal  a calibrator (a calib_bu_groups row): several units of ONE business group. No rows = today's rule exactly (every filter
#        switched on for any unit it reaches); rows = its own set (Department, Job grade, Cost centre, Branch).
#   gc   a Group Chief group (pm_calibration_groups): people of any business groups. Segment (the names given to each batch)
#        is always on; no rows = Segment only; rows add Business group, Department, Job grade, Cost centre, Branch.
#   ec   the Executive Chairman (his Group Talent Box is his alone): no rows = no filter line; rows give the filters shown once a business
#        group is picked, counted within it.
# A filter only narrows the view: no band, lock or move changes. The super admin's alone (Calibration & Talent > Settings >
# Filters > per viewer tabs).
CALIB_VIEWER_KINDS = {
    "cal": {"label": "Calibrator", "keys": ("dept", "jg", "cc", "branch")},
    "gc": {"label": "Group Chief", "keys": ("bg", "dept", "jg", "cc", "branch")},
    "ec": {"label": "Executive Chairman", "keys": ("dept", "jg", "cc", "branch")},
}
# the two filters the Group Chief's line has that the registry (the unit switches) has not: not in CALIB_FILTERS, so the unit
# card never lists them. Segment is always first and always on; Business group follows it.
CALIB_VIEWER_EXTRA = (
    {"key": "seg", "label": "Segment", "plural": "segments", "code": "SEGMENT", "chip": "Segment", "note": ""},
    {"key": "bg", "label": "Business group", "plural": "business groups", "code": "BG", "chip": "BG", "note": ""},
)


def calib_viewer_def(key):
    """A filter's definition for the per-viewer screens: the registry's, or Segment / Business group."""
    return calib_filter_def(key) or next((f for f in CALIB_VIEWER_EXTRA if f["key"] == key), None)


def _vf_viewer_exists(db, kind, viewer_id):
    """Whether the calibrator / Group Chief group a per-viewer row belongs to is still there (an active calibrator, a group)."""
    try:
        vid = int(viewer_id)
    except (TypeError, ValueError):
        return False
    try:
        if kind == "cal":
            return db.execute("SELECT 1 FROM calib_bu_groups WHERE id=? AND active=1", (vid,)).fetchone() is not None
        if kind == "gc":
            return db.execute("SELECT 1 FROM pm_calibration_groups WHERE id=?", (vid,)).fetchone() is not None
    except sqlite3.OperationalError:
        return False
    return False


def calib_viewer_filters(db, kind, viewer_id):
    """{filter key: shown} a viewer's own set (kind 'cal' | 'gc' | 'ec'), or None when it has no rows (its default holds: the
    caller's rule) -- also None for an unknown kind, a key the kind does not offer, and a calibrator or Group Chief group that
    no longer exists. The 'ec' viewer has no id."""
    spec = CALIB_VIEWER_KINDS.get(kind)
    if not spec:
        return None
    vid = "" if kind == "ec" else str(viewer_id if viewer_id is not None else "")
    if kind != "ec" and not _vf_viewer_exists(db, kind, vid):
        return None
    try:
        rows = db.execute("SELECT filter_key, shown FROM calib_viewer_filter WHERE kind=? AND viewer_id=?",
                          (kind, vid)).fetchall()
    except sqlite3.OperationalError:   # pre-migration DB
        return None
    out = {r[0]: bool(r[1]) for r in rows if r[0] in spec["keys"]}
    return out or None


def calib_viewer_shown_keys(own, kind):
    """The keys a viewer's own set shows, in the line's order: the registry's order, Business group after Segment and before
    Department (the Group Chief's line)."""
    order = [f["key"] for f in CALIB_VIEWER_EXTRA if f["key"] != "seg"] + [f["key"] for f in CALIB_FILTERS]
    return [k for k in order if k in CALIB_VIEWER_KINDS[kind]["keys"] and (own or {}).get(k)]


def _vf_has_values(key, people):
    """Whether anyone of `people` (users rows) has something for filter `key` to filter by."""
    if key == "dept":
        return any((_row_get(p, "department") or "").strip() for p in people)
    if key == "jg":
        return any(_row_get(p, "job_grade") not in (None, "") and str(_row_get(p, "job_grade")).strip() for p in people)
    if key == "bg":
        return any((_row_get(p, "business_group") or "").strip() for p in people)
    f = calib_filter_def(key)
    return bool(f and f["column"]) and any((str(_row_get(p, f["column"]) or "")).strip() for p in people)



def calib_card_filters(db, ctx, bg, view="bu"):
    """The BU-level card's three filter keys (`dept_filter`, `jg_filter`, `filters`) for one calibration scope: the unit
    switches of the units it reaches (any one on; a BU CEO's own card and a calibrator with no rows of its own), or, for a
    calibrator whose set the super admin edited (calib_viewer_filter, kind 'cal'), exactly its own -- still dropping a filter
    nobody it holds has a value for. Job grade keeps the business group's bands."""
    units = _ctx_units(ctx)
    grp = ctx.get("grp")
    own = calib_viewer_filters(db, "cal", grp["id"]) if grp else None
    if own is None:
        return {"dept_filter": calib_dept_filter_shown(db, bg, units, view),
                "jg_filter": calib_jg_payload(db, bg, units, view),
                "filters": calib_filters_payload(db, bg, units, view)}
    keys = {k for k in calib_viewer_shown_keys(own, "cal") if _vf_has_values(k, ctx["population"])}
    return {"dept_filter": "dept" in keys,
            "jg_filter": calib_jg_payload(db, bg, units, view, force=True) if "jg" in keys else None,
            "filters": calib_filters_payload(db, bg, units, view, only=keys)}


def calib_roster_value(f, person):
    """A person's roster words for a roster-backed filter (cost centre, branch, department): trimmed, '' when not set."""
    return (str(_row_get(person, f["column"]) or "")).strip()


def calib_roster_fields(person):
    """{column: words} for every roster-backed filter column that is not Department or Job grade (their rows carry those
    already): what the BU CEO's card narrows by on the client. A column added to CALIB_FILTERS rides along."""
    return {f["column"]: calib_roster_value(f, person) for f in CALIB_FILTERS
            if f["column"] and not f["table"]}


def calib_roster_filters():
    """The registry entries that read a users column and count (have, distinct) per unit: every entry with a `column`
    except Job grade, whose values are its bands. A column added to CALIB_FILTERS is picked up here with nothing else."""
    return [f for f in CALIB_FILTERS if f["column"] and f["key"] != "jg"]


def calib_filter_coverage(db, bg):
    """{company: {"people": n, <key>: (have, distinct) for every roster-backed filter (calib_roster_filters), "jg": bands in
    use}} for the active units of `bg` -- what the settings rule panel says under each unit, and what decides that a unit
    with no values for a column cannot switch it on. One read of the group; the columns it selects come from the registry
    (checked to be plain column names), never from input."""
    out = {}
    if not bg:
        return out
    cfg = calib_jg_config(db, bg)
    rf = calib_roster_filters()
    cols = sorted({f["column"] for f in rf})
    assert all(re.fullmatch(r"[a-z_]+", c) for c in cols), cols
    grades, per = {}, {}
    for r in db.execute("SELECT company, job_grade%s FROM users WHERE business_group=? AND left_at IS NULL AND "
                        "role!='admin' AND COALESCE(company,'')!=''" % "".join(", " + c for c in cols), (bg,)):
        co = r["company"]
        d = per.setdefault(co, {"people": 0, **{f["key"]: [0, set()] for f in rf}})
        d["people"] += 1
        for f in rf:
            v = (str(r[f["column"]] or "")).strip()
            if v:
                d[f["key"]][0] += 1
                d[f["key"]][1].add(v)
        if r["job_grade"] not in (None, ""):
            grades.setdefault(co, []).append(r["job_grade"])
    for co, d in per.items():
        out[co] = {"people": d["people"], "jg": len(calib_jg_options(cfg, grades.get(co, []))),
                   **{f["key"]: (d[f["key"]][0], len(d[f["key"]][1])) for f in rf}}
    return out


def calib_joins(db, cid, bg=None):
    """[{"business_group", "lead", "members", "label", "created_by", "created_at"}] for cycle `cid` (one group's)."""
    q = "SELECT business_group, lead, MIN(created_by) created_by, MIN(created_at) created_at FROM calib_unit_joins " \
        "WHERE cycle_id=?" + (" AND business_group=?" if bg else "") + " GROUP BY business_group, lead ORDER BY " \
        "business_group, lead"
    out = []
    for r in db.execute(q, (cid, bg) if bg else (cid,)).fetchall():
        j = calib_join(db, cid, r["business_group"], r["lead"])
        if j:
            out.append(dict(j, business_group=r["business_group"], created_by=r["created_by"],
                            created_at=r["created_at"]))
    return out


def _bu_units_of(db, cid, bg, company):
    """The units a BU CEO scope covers this cycle: the joined units (the lead first), or just this one."""
    j = calib_join(db, cid, bg, company)
    return j["members"] if j else [company]


def _join_read_only_msg(db, ctx):
    """What another BU CEO of units calibrated together is told when they try to move someone (row 6)."""
    j = ctx["join"]
    h = buceo_holder(db, ctx["business_group"], j["lead"])
    who = (h["full_name"] if h else None) or "The BU CEO of %s" % (display_company(ctx["business_group"], j["lead"])
                                                                 or j["lead"])
    return "%s calibrates %s together this cycle; you can read it, not change it." % (who, j["label"])


def _ctx_units(ctx):
    """The units a calibration scope covers: the joined units (row 6), the units a calibration group reaches
    (2026-10-22), else its own scope key."""
    if ctx.get("grp"):
        return list(ctx["grp"]["units"])
    return ctx["join"]["members"] if ctx.get("join") else [ctx["scope_key"]]


def _join_payload(ctx, curve=None):
    """What a calibration card shows about units calibrated together (row 6): their label, each unit and its
    headcount (a lens like the department row; the lock still covers them all), and whether this login only reads.
    None for one unit."""
    j = ctx.get("join")
    if not j:
        return None
    n = {}
    for p in ctx["population"]:
        n[p["company"]] = n.get(p["company"], 0) + 1
    bg = ctx["business_group"]
    return {"label": j["label"], "read_only": bool(ctx.get("read_only")),
            "units": [{"company": m, "label": display_company(bg, m) or m, "people": n.get(m, 0),
                       # each unit's own expected spread, for the unit lens (performance: its PAT curve)
                       "target": next((e["dist"] for e in (curve or {}).get("joined") or [] if e["company"] == m), None)}
                      for m in j["members"]],
            "note": "" if not ctx.get("read_only") else _join_read_only_msg(get_db(), ctx)}


def _calib_session_ids(ctx):
    """Every session a calibration scope reads adjustments from: its own, plus each joined unit's (row 6)."""
    ids = [r["id"] for r in (ctx.get("member_sessions") or {}).values() if r]
    if not ids and ctx.get("session"):
        ids = [ctx["session"]["id"]]
    return ids



def calibration_tier_of(db, u):
    """The calibration tier(s) this login holds, as a list of
    ("hod", hod_id) / ("buceo", (bg, company)) / ("bgceo", bg) tuples -- a
    person can hold more than one (a BU CEO who is also a BG CEO). HOD/
    BUCEO/BGCEO are always the SAME single employee login, never role=
    'admin' -- never the Manage-menu admin toolkit. HOD isn't a stored
    flag (unlike buceo_bg/bgceo_bg): it's "does anyone's hod_id point at
    me", the same relationship /hod already reads, so this needs `db`.
    A calibrator holds NO HOD tier (Chris, 2026-10-30): whoever holds a BU CEO seat, a calibration group, a BG CEO
    seat or a Group Chief group is never an HOD, whoever's hod_id points at them (_hod_review_holders)."""
    if not u or u["role"] == "admin":
        return []
    tiers = []
    if hod_has_role(db, u["id"]) and db.execute("SELECT 1 FROM users WHERE hod_id=? AND role!='admin' LIMIT 1",
                                                (u["id"],)).fetchone():
        tiers.append(("hod", u["id"]))
    seats = buceo_seats(db, u["id"]) or _buceo_col_seat(u)
    # and every calibration group they calibrate at BU CEO level (2026-10-22): ("bugrp", (bg, company, group id)), a
    # tier of its own so a reader that knows only the BU CEO's units passes it by
    scopes = list(seats) + [(g["business_group"], g["company"], g["id"]) for g in bu_groups_of_calibrator(db, u["id"])]
    if scopes:   # every unit and group they hold, the one they're working on first (so "the" BU scope is that one)
        pick = _bu_unit_pick(db, u, scopes)
        tiers += [("bugrp" if len(s_) > 2 else "buceo", s_) for s_ in sorted(scopes, key=lambda x: x != pick)]
    if u["bgceo_bg"]:
        tiers.append(("bgceo", u["bgceo_bg"]))
    return tiers


def _hod_review_skip_sql(db, hod_id):
    """(sql, args): the people of this HOD's department who are LEFT OUT of their Department Review. A calibrator is
    no HOD (Chris, 2026-10-30: "If a person is marked as calibrator, then this role will supersede HOD role"): anyone
    who holds a BU CEO seat, a BU calibration group, a BG CEO seat or a Group Chief group has no Department Review, in
    every cycle type, so for them everyone is left out (" AND 0"); their department's people go up on their line
    manager's rating to their own BU CEO / calibrator. "" (and no args) for every other HOD. The fragment is ready to
    append to any `FROM users WHERE hod_id=? ...` population query: `_pot_scope_population`, `_pm_calib_resolve`, the
    dashboard card, the classic pages' writers all append it. The seat test is `_hod_review_holders`."""
    if hod_id and hod_id in _hod_review_holders(db):
        return " AND 0", []
    return "", []


def _hod_seat_kinds(db):
    """(ceo ids, calibrator ids): who holds a CEO seat (a BU CEO seat in `buceo_seats` or the `buceo_*` columns, a BG CEO seat)
    and who holds a calibration seat of the normal review (a BU calibration group's calibrator, a Group Chief group's calibrator).
    One batched read, cached per request. The seat logic lives here ONLY: `_hod_review_holders` (both kinds, the normal review) and
    `gradeh_hod_has_role` (the CEO kind, Grade H) are views of it. Must not call calibration_tier_of (which asks this)."""
    cache = _req_cache()
    if "_hrkinds" not in cache:
        ceo = {r[0] for r in db.execute("SELECT DISTINCT user_id FROM buceo_seats") if r[0]}
        ceo |= {r[0] for r in db.execute("SELECT id FROM users WHERE COALESCE(bgceo_bg,'')!='' OR "
                                         "COALESCE(buceo_company,'')!=''")}
        cal = {g_["calibrator_id"] for g_ in bu_groups_all(db).values() if g_["calibrator_id"]}
        cal |= {r[0] for r in db.execute("SELECT DISTINCT calibrator_id FROM pm_calibration_groups") if r[0]}
        cache["_hrkinds"] = (ceo, cal)
    return cache["_hrkinds"]


def _hod_review_holders(db):
    """The ids of everyone who holds a calibrator seat and so is never an HOD of the normal review (Chris, 2026-10-30): a BU CEO
    seat, a BU calibration group's calibrator, a BG CEO, a Group Chief. Any cycle type. One batched read, cached per request. The
    ONE place that says it for the normal review: every reader of the HOD role asks `hod_has_role` / `_hod_ids_with_review`, never its
    own copy of the seat logic. Grade H asks its own twin, `gradeh_hod_has_role` (same read, CEO seats only). Must not call
    calibration_tier_of (which asks this)."""
    cache = _req_cache()
    if "_hrholders" not in cache:
        ceo, cal = _hod_seat_kinds(db)
        cache["_hrholders"] = ceo | cal
    return cache["_hrholders"]


def hod_has_role(db, hod_id):
    """Whether this person is an HOD in the sense of the review: someone, and not a calibrator (_hod_review_holders).
    The HOD role's tier, tabs, view of the department, notices and counts all ask this. NORMAL REVIEW ONLY: Grade H readers ask
    `gradeh_hod_has_role` (test_ceo_hod lints it)."""
    return bool(hod_id) and hod_id not in _hod_review_holders(db)


def gradeh_hod_has_role(db, hod_id):
    """Whether this person is an HOD in GRADE H (Chris, 2026-11-03: "Yes, allow for Grade H"): someone, and not a BU CEO or BG CEO.
    A calibration seat of the normal review (a BU calibration group's calibrator, a Group Chief group's calibrator) takes the HOD role
    away in the normal review only (hod_has_role): Grade H has no calibrator step, and a BU CEO seat is its own sign-off tier. The ONE
    place that says it; every Grade H HOD reader (_gh_slots, gradeh_hod_scope, gradeh_hod_can, the Grade H list's look groups, the
    Grade H notice's audience) asks this, never hod_has_role. Same cached read as _hod_review_holders (_hod_seat_kinds)."""
    return bool(hod_id) and hod_id not in _hod_seat_kinds(db)[0]


def _gh_hod_ids_with_role(db, hod_ids):
    """The ones of these Grade H HODs who hold the Grade H HOD role (gradeh_hod_has_role). One batched set, never a query per HOD."""
    ceo = _hod_seat_kinds(db)[0]
    return [i for i in hod_ids if i and i not in ceo]


def _hod_ids_with_review(db, hod_ids):
    """The ones of these HODs who hold the HOD role -- a calibrator (_hod_review_holders) has no Department Review, so
    is dropped. One batched set, never a query per HOD."""
    held = _hod_review_holders(db)
    return [i for i in hod_ids if i and i not in held]


def is_hod_of(u, hod_id):
    """Whether this login is the HOD `hod_id` -- never a calibrator (Chris, 2026-10-30)."""
    if not (u and u["role"] != "admin" and u["id"] == hod_id):
        return False
    try:
        return hod_has_role(get_db(), hod_id)
    except RuntimeError:   # no app context
        return True


def is_buceo_of(u, bg, company):
    """Whether this person holds (bg, company)'s BU CEO seat -- any of their seats (admin round 4)."""
    if not u:
        return False
    try:
        return (bg, company) in (buceo_seats(get_db(), u["id"]) or _buceo_col_seat(u))
    except RuntimeError:   # no app context: the first seat's columns
        return u["buceo_bg"] == bg and u["buceo_company"] == company


def _buceo_col_seat(u):
    """[(bg, company)] from the person's own BU CEO columns when no seat row names them -- a login built in memory (the
    triggers keep the table and the columns together for everyone stored)."""
    bg, co = _row_get(u, "buceo_bg"), _row_get(u, "buceo_company")
    return [(bg, co)] if bg and co else []


def is_bgceo_of(u, bg):
    return bool(u) and u["bgceo_bg"] == bg


def bg_scope(u, col="business_group"):
    """SQL fragment + params restricting `col` (a business_group column) to the
    admin's scope.

    Super admin -> ('', []). BGHR admin -> (' AND <col>=?', [bg]). A company-
    scoped sub-admin additionally gets (' AND <company_col> IN (...)'), where the
    company column is derived by swapping 'business_group' -> 'company' in `col`
    (column naming is consistent across queries, e.g. u.business_group/u.company).
    """
    bg = admin_bg_of(u)
    if not bg:
        return "", []
    clause = f" AND {col} = ?"
    params = [bg]
    comps = admin_companies_of(u)
    if comps:
        ccol = col.replace("business_group", "company")
        clause += " AND %s IN (%s)" % (ccol, ",".join("?" * len(comps)))
        params += list(comps)
    return clause, params


def can_access(u, business_group, company):
    """True if this admin may act on a row in (business_group, company)."""
    bg = admin_bg_of(u)
    if bg is None:
        return True                      # super admin
    if business_group != bg:
        return False                     # outside the admin's BG
    comps = admin_companies_of(u)
    return (not comps) or (company in comps)   # sub-admin: must be an allowed company


def can_access_bg(u, business_group):
    """True if this admin may act anywhere in `business_group` (BG-level only).
    Note: for row-level checks that have a company, prefer can_access()."""
    bg = admin_bg_of(u)
    return bg is None or business_group == bg


# Names url_for itself owns: a visitor's ?endpoint=x or ?_external=1 spliced into url_for(**args) raised TypeError or
# changed the link (security test 3-08, 2026-10-31).
_URL_FOR_OWN_ARGS = frozenset({"endpoint", "_anchor", "_method", "_scheme", "_external"})


def _url_args(src, *drop):
    """A page's own query arguments (request.args, or a dict built from them) as a dict that is safe to splat into
    url_for(...): url_for's own names are dropped, and so is every name the call already passes by itself (`key`,
    `format`, `page` ... named in `drop`), which would otherwise be "multiple values for keyword argument" and a 500 for
    anyone who types the name into the address bar. Order and values are kept."""
    gone = _URL_FOR_OWN_ARGS.union(drop)
    return {k: v for k, v in src.items() if k not in gone}


def admin_filter_rows(db, me, endpoint, params=("fbg", "fbu", "fdept"), levels=3, endpoint_kw=None,
                      people_sql="role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0", bg_all=True):
    """The admin page kit's filter rows (canvas K2; Chris, 2026-10-10: "always go by order of BG, BU, then department,
    each in one row, and apply navigation button if there are more than the display allowed"): (rows for
    _filter_rows.html, {"bg", "bu", "dept"} as picked and checked). Business group first (a super admin's choice; a BG
    admin is already in theirs), then unit once a group is picked, then department once a unit is; each option carries
    its headcount (people_sql) and keeps the page's other arguments. A sub-admin's units are theirs only. `params` are the
    page's own argument names; `levels` stops at group (1) or unit (2)."""
    pbg, pbu, pdept = params
    ekw = dict(endpoint_kw or {})
    keep = _url_args(request.args, pbg, pbu, pdept, "page", "fcompany_label", "fdept_label", *ekw)

    def href(**over):
        a = dict(keep)
        a.update({k: v for k, v in over.items() if v})
        return url_for(endpoint, **ekw, **a)
    own = admin_bg_of(me)
    bgs = [b for b in org_bgs(db) if can_access_bg(me, b)]
    want = (request.args.get(pbg) or "").strip()
    bg = own if own else (want if want in bgs else "")
    rows = []
    if not own:
        n = {r[0]: r[1] for r in db.execute("SELECT business_group, COUNT(*) FROM users WHERE " + people_sql +
                                            " GROUP BY business_group")}
        rows.append({"label": "Business group", "opts": ([{"key": "", "label": "All", "n": sum(n.get(b, 0) for b in bgs),
                                                           "on": not bg, "href": href()}] if bg_all else [])
                     + [{"key": b, "label": display_bg(b), "n": n.get(b, 0), "on": b == bg, "href": href(**{pbg: b})}
                        for b in bgs]})
    bu = dept = ""
    if bg and levels >= 2:
        n = {r[0]: r[1] for r in db.execute("SELECT COALESCE(company,''), COUNT(*) FROM users WHERE " + people_sql +
                                            " AND business_group=? GROUP BY COALESCE(company,'')", (bg,))}
        units = sorted((c for c in set(n) | set(org_map(db).get(bg, [])) if c and can_access(me, bg, c)),
                       key=lambda c: (display_company(bg, c) or c).lower())
        want = (request.args.get(pbu) or "").strip()
        bu = want if want in units else ""
        # "All of" counts what it lists: the whole group, people with no unit on record too -- except for an admin of
        # some units only, who sees theirs
        n_all = sum(n.get(c, 0) for c in units) if admin_companies_of(me) else sum(n.values())
        rows.append({"label": "Business unit", "opts": [{"key": "", "label": "All of " + display_bg(bg),
                                                         "n": n_all, "on": not bu,
                                                         "href": href(**{pbg: bg if not own else None})}]
                     + [{"key": c, "label": display_company(bg, c) or c, "n": n.get(c, 0), "on": c == bu,
                         "href": href(**{pbg: bg if not own else None, pbu: c})} for c in units]})
        if bu and levels >= 3:
            n = {(r[0] or "").strip(): r[1] for r in db.execute(
                "SELECT TRIM(COALESCE(department,'')), COUNT(*) FROM users WHERE " + people_sql +
                " AND business_group=? AND company=? GROUP BY TRIM(COALESCE(department,''))", (bg, bu))}
            depts = sorted((d for d in n if d), key=str.lower)
            want = (request.args.get(pdept) or "").strip()
            dept = want if want in depts else ""
            rows.append({"label": "Department", "opts": [{"key": "", "label": "All", "n": sum(n.values()), "on": not dept,
                                                          "href": href(**{pbg: bg if not own else None, pbu: bu})}]
                         + [{"key": d, "label": d, "n": n[d], "on": d == dept,
                             "href": href(**{pbg: bg if not own else None, pbu: bu, pdept: d})} for d in depts]})
    return rows, {"bg": bg, "bu": bu, "dept": dept}


def can_manage_subadmins(u):
    """Who may create/manage company-scoped sub-admins: the super admin, or a
    FULL BG admin (admin_bg set, not itself company-scoped). Sub-admins can't."""
    return is_super(u) or (bool(admin_bg_of(u)) and not admin_companies_of(u) and not is_lnd_admin(u))


