UROLE_LMS_SUBS = ("lms.xp",)
UROLE_PARENT.update({k: "lms" for k in UROLE_LMS_SUBS})
# the rows the matrix indents under the one above
UROLE_SUB_ROWS = frozenset(UROLE_SELF_KEYS[1:]) | frozenset(UROLE_LMS_SUBS)


def urole_modules_shown():
    """The user-role rows an admin sees: AI+ Learning only where it's switched on (ONEHR_LMS=1; production keeps it dark,
    Chris 2026-10-20). A row not shown keeps its ticks as they are."""
    return tuple(m for m in UROLE_MODULES if (not m[0].startswith("lms") or lms_on()) and (m[0] != "gradeh" or gradeh_on()))

# Basic: the dashboard (their released results on it), the Career Plan, AI+ Learning (their own on the dashboard too),
# rating colleagues when asked
UROLE_DEFAULTS = {"full": set(UROLE_MODULE_KEYS), "basic": {"tm_rate", "idp", "lms", "results", "gradeh"} | set(UROLE_SELF_KEYS)
                  | set(UROLE_LMS_SUBS)}
UROLE_BUILTINS = (("full", "Full"), ("basic", "Basic"))
# taking part in the cycle's own review: any of these
UROLE_REVIEW_MODULES = ("pm", "tm_rated", "competency")
# the rollout switch: does more than a year's service still count as confirmed? Chris's rule is no (2026-10-20); on a
# database from before the roles it starts on, so nobody's access changes on the day this ships, until the super admin
# turns it off on Roles & access › User roles (with the list of who it moves in front of him)
UROLE_SERVICE_KEY = "urole_service_counts"


def urole_confirmed_sql(prefix=""):
    """SQL: Full by the automatic rule -- a confirmation date that has come (MYT), or, while the rollout switch is on,
    more than a year's service. Binds no parameter; uncorrelated subqueries only."""
    p = f"{prefix}." if prefix else ""
    return (f"(({p}confirmation_date IS NOT NULL AND trim({p}confirmation_date)!='' "
            f"AND substr({p}confirmation_date, 1, 10) <= date('now', '+8 hours')) OR "
            f"(COALESCE({p}years_of_service, 0) > 1 AND EXISTS (SELECT 1 FROM app_settings "
            f"WHERE key='{UROLE_SERVICE_KEY}' AND value='1')))")


def urole_allows_sql(module, prefix=""):
    """SQL predicate: this person's user role opens `module` (one of UROLE_MODULE_KEYS, or a tuple of them: any).
    A CASE over the row's own columns with uncorrelated subqueries, so a population read stays one statement and a
    module-level query built at import time still follows the roles. Binds no parameter."""
    mods = (module,) if isinstance(module, str) else tuple(module)
    assert all(m in UROLE_MODULE_KEYS for m in mods), mods
    p = f"{prefix}." if prefix else ""
    m = "(SELECT role_id FROM user_role_modules WHERE module IN (%s))" % ",".join("'%s'" % x for x in mods)
    return (f"(CASE WHEN {p}user_role_id IS NOT NULL THEN {p}user_role_id IN {m} "
            f"WHEN {urole_confirmed_sql(prefix)} THEN (SELECT id FROM user_roles WHERE builtin='full') IN {m} "
            f"ELSE (SELECT id FROM user_roles WHERE builtin='basic') IN {m} END)")


def _urole_map(db=None):
    """{"roles": {id: row}, "mods": {id: set(modules)}, "full": id, "basic": id, "service": bool}, read once a request."""
    cache = getattr(g, "_urole_map", None) if has_request_context() else None
    if cache is not None:
        return cache
    db = db or get_db()
    try:
        roles = {r["id"]: r for r in db.execute("SELECT * FROM user_roles")}
        mods = {}
        for r in db.execute("SELECT role_id, module FROM user_role_modules"):
            mods.setdefault(r["role_id"], set()).add(r["module"])
        sv = db.execute("SELECT value FROM app_settings WHERE key=?", (UROLE_SERVICE_KEY,)).fetchone()
    except sqlite3.OperationalError:
        roles, mods, sv = {}, {}, None
    out = {"roles": roles, "mods": mods, "service": bool(sv and sv[0] == "1"),
           "full": next((i for i, r in roles.items() if r["builtin"] == "full"), None),
           "basic": next((i for i, r in roles.items() if r["builtin"] == "basic"), None)}
    if has_request_context():
        g._urole_map = out
    return out


def urole_auto_full(u, service=False):
    """The automatic rule for a fetched row: Full once the confirmation date has come (MYT), or (rollout switch) more
    than a year's service."""
    cd = str(_row_get(u, "confirmation_date") or "").strip()[:10]
    if cd and cd <= _today_myt().isoformat():
        return True
    return bool(service and (_row_get(u, "years_of_service") or 0) > 1)


def urole_of(u, db=None):
    """(role id, how: 'hand' | 'full' | 'basic') for a person -- urole_allows_sql's Python mirror."""
    um = _urole_map(db)
    rid = _row_get(u, "user_role_id")
    if rid and rid in um["roles"]:
        return rid, "hand"
    if urole_auto_full(u, um["service"]):
        return um["full"], "full"
    return um["basic"], "basic"


def urole_modules_of(u, db=None):
    """The modules this person's user role opens. A row without the columns (a hand-built dict) opens everything."""
    if u is None:
        return set()
    try:
        u["id"]
    except (KeyError, IndexError, TypeError):
        return set(UROLE_MODULE_KEYS)
    rid, _how = urole_of(u, db)
    if rid is None:   # no roles yet (a database mid-migration): as before the roles
        return set(UROLE_MODULE_KEYS)
    return set(_urole_map(db)["mods"].get(rid, set()))


def urole_allows(u, module, db=None):
    """Whether their user role opens `module` -- and, for a row under another (UROLE_PARENT), each one above it too."""
    mods = urole_modules_of(u, db)
    while module:
        if module not in mods:
            return False
        module = UROLE_PARENT.get(module)
    return True


def _urole_options(db):
    """[{id, name, summary}] of every active user role, Full and Basic first."""
    um = _urole_map(db)
    rows = sorted((r for r in um["roles"].values() if not r["retired_at"]),
                  key=lambda r: ({"full": 0, "basic": 1}.get(r["builtin"] or "", 2), r["id"]))
    lbl = {k: l.split(":")[0] for k, l, _n in urole_modules_shown() if UROLE_PARENT.get(k) != "lms_self"}
    return [{"id": r["id"], "name": r["name"], "builtin": r["builtin"],
             "summary": ", ".join(lbl[m] for m in lbl if m in um["mods"].get(r["id"], set())) or "nothing"}
            for r in rows]


