def admin_viewonly(u):
    """True for a BG or unit admin the super admin has given no change in any module: they read the portal only."""
    if not (is_admin(u) and not is_super(u)) or is_lnd_admin(u):   # an L&D admin runs Learning: no role ticks
        return False
    return not any(ADMIN_ITEM_BY_KEY[k][2] != "read" for k in admin_items(u) if k in ADMIN_ITEM_BY_KEY)


def admin_access_limited(u):
    """True for a BG or unit admin with at least one change ticked: the page switches off only what they can't do."""
    return bool(is_admin(u) and not is_super(u) and not admin_viewonly(u) and not is_lnd_admin(u))


