def role_preset_items(key):
    """The items of a preset: View only (every module's pages), Run the cycle (edits and adds in the cycle, Performance,
    360, Competency, Career Plan and People; no deletes), Everything. Every import file is the super admin's, whatever the role."""
    out = {i[1] for i in ADMIN_ITEMS if i[2] == "read"}
    for mod, key_, kind, _l in ADMIN_ITEMS:
        if key == "full" or (key == "cycle" and mod in _RUN_CYCLE and kind in ("edit", "add")):
            out.add(key_)
    return out - ADMIN_ITEMS_EXPLICIT - _admin_items_hidden()


def _admin_items_hidden():
    """The items the Roles & access page does not offer on this server: Grade H Appraisal's read item while Grade H is dark
    (ONEHR_GRADEH unset), so a server that has it off draws, presets and saves exactly as before (2026-10-31; as the Executive
    Chairman's rows wait on chair_on). A stored row for one is kept as it is, never shown, never counted."""
    return frozenset() if gradeh_on() else GRADEH_ADMIN_ITEM_KEYS


def _items_from_perms(perms):
    """The items a set of per-admin ticks ({module: kinds}, the 2026-10-19 grid) gave: an item where its kind was
    ticked."""
    out = set()
    for mod, key, kind, _l in ADMIN_ITEMS:
        if kind in perms.get(mod, set()) and key not in ADMIN_ITEMS_EXPLICIT:   # a ticked-by-name item is never inherited
            out.add(key)
    return out


def admin_roles_all(db, with_retired=False):
    """Every admin role, the built-in ones first."""
    q = "SELECT * FROM admin_roles" + ("" if with_retired else " WHERE retired_at IS NULL")
    return db.execute(q + " ORDER BY CASE builtin WHEN 'bg' THEN 0 WHEN 'bu' THEN 1 WHEN 'lnd' THEN 2 ELSE 3 END, id"
                      ).fetchall()


def admin_role_id_builtin(db, builtin):
    r = db.execute("SELECT id FROM admin_roles WHERE builtin=?", (builtin,)).fetchone()
    return r["id"] if r else None


def admin_role_of(u, db=None):
    """This admin's role row, or None (the super admin, or not an admin). An account from before the roles reads as
    the role its scope gives: an L&D admin, a unit admin (units ticked), else a BG admin."""
    if not u or not is_admin(u) or is_super(u):
        return None
    db = db or get_db()
    rid = _row_get(u, "admin_role_id")
    row = db.execute("SELECT * FROM admin_roles WHERE id=?", (rid,)).fetchone() if rid else None
    if row:
        return row
    b = "lnd" if u["admin_bg"] == LMS_ADMIN_BG else (
        "bu" if db.execute("SELECT 1 FROM admin_companies WHERE admin_id=?", (u["id"],)).fetchone() else "bg")
    return db.execute("SELECT * FROM admin_roles WHERE builtin=?", (b,)).fetchone()


def admin_role_items(db, role_id):
    hidden = _admin_items_hidden()
    return {r["item"] for r in db.execute("SELECT item FROM admin_role_access WHERE role_id=?", (role_id,))
            if r["item"] in ADMIN_ITEM_BY_KEY and r["item"] not in hidden}


def admin_items(u, db=None):
    """The items this admin may do: the super admin everything; any other admin their role's. Read once per request."""
    if not u or not is_admin(u):
        return frozenset()
    if is_super(u):
        return frozenset(ADMIN_ITEM_KEYS)
    cache = getattr(g, "_admin_items", None) if has_request_context() else None
    if cache is not None and cache.get("uid") == u["id"]:
        return cache["items"]
    try:
        role = admin_role_of(u, db)
        items = frozenset(admin_role_items(db or get_db(), role["id"])) if role else frozenset()
    except sqlite3.OperationalError:
        items = frozenset()
    if has_request_context():
        g._admin_items = {"uid": u["id"], "items": items}
    return items


def admin_can_item(u, item):
    return item in admin_items(u)


def _seed_access_roles():
    """Once, after the tables exist: the three built-in roles; every admin account given the role its scope gives; and
    the BG and BU admin roles View only (Chris, 2026-10-20: everyone but the super admin read only; production's per-
    admin grid was View only for every one anyway). Prints what it did, and how many had more on their own grid."""
    try:
        c = sqlite3.connect(DB_PATH, timeout=5.0)
        c.row_factory = sqlite3.Row
        if not c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='admin_roles'").fetchone():
            c.close()
            return
        for b, name, sk in ADMIN_ROLE_BUILTINS:
            if not c.execute("SELECT 1 FROM admin_roles WHERE builtin=?", (b,)).fetchone():
                taken = c.execute("SELECT 1 FROM admin_roles WHERE name=?", (name,)).fetchone()
                c.execute("INSERT INTO admin_roles(name, scope_kind, builtin) VALUES (?,?,?)",
                          (name + (" (built in)" if taken else ""), sk, b))
        rid = {r["builtin"]: r["id"] for r in c.execute("SELECT id, builtin FROM admin_roles WHERE builtin IS NOT NULL")}
        units = {r[0] for r in c.execute("SELECT DISTINCT admin_id FROM admin_companies")}
        members = {"bg": [], "bu": [], "lnd": []}
        for a in c.execute("SELECT id, admin_bg, admin_role_id FROM users WHERE role='admin'").fetchall():
            if not a["admin_bg"]:
                continue   # the super admin: no role
            b = "lnd" if a["admin_bg"] == LMS_ADMIN_BG else ("bu" if a["id"] in units else "bg")
            if a["admin_role_id"] is None:
                c.execute("UPDATE users SET admin_role_id=? WHERE id=?", (rid[b], a["id"]))
                members[b].append(a["id"])
            elif a["admin_role_id"] == rid.get(b):
                members[b].append(a["id"])
        # Inactivity sign-out (Chris, 2026-11-02): the built-in L&D admin role is left out of it, ONCE. The key keeps a later
        # change of the super admin's (the switch, _role_idle_set) from being put back at the next boot.
        if not c.execute("SELECT value FROM app_settings WHERE key='idle_role_seeded'").fetchone():
            c.execute("UPDATE admin_roles SET idle_signout=0 WHERE builtin='lnd'")
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('idle_role_seeded', datetime('now'))")
            print("[roles] inactivity sign-out: the built-in L&D admin role is left out of it")
        done = c.execute("SELECT value FROM app_settings WHERE key='access_roles_seeded'").fetchone()
        if not done:
            stored = {}
            for r in c.execute("SELECT * FROM admin_access"):
                k = {kd for kd in ACCESS_KINDS if r["can_" + kd]}
                stored.setdefault(r["admin_id"], {})[r["module"]] = k | ({"read"} if k - {"read"} else set())
            said = []
            for b in ("bg", "bu"):
                sets = []
                for aid in members[b]:
                    perms = {m: {"read"} for m in ACCESS_MODULE_KEYS}
                    perms.update(stored.get(aid, {}))
                    sets.append(_items_from_perms(perms))
                # every role but the super admin starts read only (Chris, 2026-10-20: "for the admin access, except
                # for super admin, set the rest as read only"); what an admin had on their own grid is only counted
                common = role_preset_items("view")
                c.execute("DELETE FROM admin_role_access WHERE role_id=?", (rid[b],))
                c.executemany("INSERT INTO admin_role_access(role_id, item) VALUES (?,?)",
                              [(rid[b], it) for it in sorted(common)])
                dropped = sum(1 for st in sets if st - common)
                said.append("%s: %d admin(s), %d item(s)%s" % (b, len(sets), len(common),
                                                                 ", %d had more on their own grid" % dropped if dropped else ""))
            c.execute("DELETE FROM admin_role_access WHERE role_id=?", (rid["lnd"],))
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('access_roles_seeded', datetime('now'))")
            print("[roles] admin roles seeded: " + "; ".join(said))
        # Remarks and files (Chris, 2026-11-07): the built-in BG admin role reads it, ONCE. The settings key keeps a later untick of the
        # super admin's from being put back at the next boot; the BU and L&D admin roles are not given it, and a custom role is the
        # super admin's to tick. (2026-11-11: it no longer carries KPI files, see pm.files below.)
        if not c.execute("SELECT value FROM app_settings WHERE key='admin_roles_seeded_remarks_files'").fetchone():
            if "bg" in rid:
                c.execute("INSERT OR IGNORE INTO admin_role_access(role_id, item) VALUES (?,?)", (rid["bg"], "people.remarks_files"))
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('admin_roles_seeded_remarks_files', datetime('now'))")
            print("[roles] the built-in BG admin role reads the remarks (the 360's raters by number)")
        # KPI files (Chris, 2026-11-11, "Yes, files-only item"): the built-in BG and BU admin roles see people's KPI files, ONCE (the L&D
        # admin role and a custom role are not given it). The settings key keeps a later untick of the super admin's from being put back
        # at the next boot.
        if not c.execute("SELECT value FROM app_settings WHERE key='admin_roles_seeded_pm_files'").fetchone():
            for b_ in ("bg", "bu"):
                if b_ in rid:
                    c.execute("INSERT OR IGNORE INTO admin_role_access(role_id, item) VALUES (?,?)", (rid[b_], "pm.files"))
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('admin_roles_seeded_pm_files', datetime('now'))")
            print("[roles] the built-in BG and BU admin roles see people's KPI files")
        # people.kpi_files (Add and remove KPI files) is retired: adding or removing a file is the super admin's alone, so no role row
        # for it stays, ONCE.
        if not c.execute("SELECT value FROM app_settings WHERE key='admin_roles_cleared_kpi_files'").fetchone():
            c.execute("DELETE FROM admin_role_access WHERE item='people.kpi_files'")
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('admin_roles_cleared_kpi_files', datetime('now'))")
        # Reorder KPI lines (Chris, 2026-11-08, "those with existing KPI edit access, made into its own access-control item"): every
        # role that holds Edit a KPI line is given it, ONCE. The settings key keeps a later untick of the super admin's from being
        # put back at the next boot (a role without Edit is not touched; the presets carry the item for a role made after this).
        if not c.execute("SELECT value FROM app_settings WHERE key='admin_roles_seeded_kpi_reorder'").fetchone():
            n_ = c.execute("INSERT OR IGNORE INTO admin_role_access(role_id, item) SELECT role_id, 'pm.kpi_reorder' FROM "
                           "admin_role_access WHERE item='pm.kpi_edit'").rowcount
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('admin_roles_seeded_kpi_reorder', datetime('now'))")
            print("[roles] Reorder KPI lines ticked on %d role(s) that hold Edit a KPI line" % max(n_, 0))
        # Grade H Appraisal (2026-10-31): the built-in BG and BU admin roles read People & progress, once, on a server where Grade H is on
        # (a dark server is not touched: the row waits for the boot that switches it on). A custom role stays as the super admin ticked it.
        if gradeh_on() and not c.execute("SELECT value FROM app_settings WHERE key='admin_roles_seeded_gradeh'").fetchone():
            for b in ("bg", "bu"):
                if b in rid:
                    c.executemany("INSERT OR IGNORE INTO admin_role_access(role_id, item) VALUES (?,?)",
                                  [(rid[b], k) for k in sorted(GRADEH_ADMIN_ITEM_KEYS)])
            c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('admin_roles_seeded_gradeh', datetime('now'))")
        # the user roles: Full and Basic built in, with what each opens (Chris's words), once
        if c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='user_roles'").fetchone():
            for b, name in UROLE_BUILTINS:
                if not c.execute("SELECT 1 FROM user_roles WHERE builtin=?", (b,)).fetchone():
                    taken = c.execute("SELECT 1 FROM user_roles WHERE name=?", (name,)).fetchone()
                    c.execute("INSERT INTO user_roles(name, builtin) VALUES (?,?)",
                              (name + (" (built in)" if taken else ""), b))
            # own learning on the dashboard (2026-10-20): on, once, for every role that opens AI+ Learning, as before it
            if not c.execute("SELECT value FROM app_settings WHERE key='user_roles_seeded_lms_self'").fetchone():
                for (urid,) in c.execute("SELECT DISTINCT role_id FROM user_role_modules WHERE module='lms'").fetchall():
                    c.executemany("INSERT OR IGNORE INTO user_role_modules(role_id, module) VALUES (?,?)",
                                  [(urid, m) for m in UROLE_SELF_KEYS])
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('user_roles_seeded_lms_self', "
                          "datetime('now'))")
            # Learning's own parts (phase 3, 2026-10-21: XP and badges): on, once, for every role that opens AI+ Learning
            if not c.execute("SELECT value FROM app_settings WHERE key='user_roles_seeded_lms_subs'").fetchone():
                for (urid,) in c.execute("SELECT DISTINCT role_id FROM user_role_modules WHERE module='lms'").fetchall():
                    c.executemany("INSERT OR IGNORE INTO user_role_modules(role_id, module) VALUES (?,?)",
                                  [(urid, m) for m in UROLE_LMS_SUBS])
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('user_roles_seeded_lms_subs', "
                          "datetime('now'))")
            # My Appraisal (Grade H, 2026-10-28): on, once, for the built-in Full and Basic roles, which are the ones the Grade H
            # people hold; a custom role keeps what the super admin ticked
            if not c.execute("SELECT value FROM app_settings WHERE key='user_roles_seeded_gradeh'").fetchone():
                if c.execute("SELECT value FROM app_settings WHERE key='user_roles_seeded_v2'").fetchone():
                    for (urid,) in c.execute("SELECT id FROM user_roles WHERE builtin IN ('full','basic')").fetchall():
                        c.execute("INSERT OR IGNORE INTO user_role_modules(role_id, module) VALUES (?,?)", (urid, "gradeh"))
                    c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('user_roles_seeded_gradeh', datetime('now'))")
            if not c.execute("SELECT value FROM app_settings WHERE key='user_roles_seeded_v2'").fetchone():
                for b, _n in UROLE_BUILTINS:
                    urid = c.execute("SELECT id FROM user_roles WHERE builtin=?", (b,)).fetchone()[0]
                    c.execute("DELETE FROM user_role_modules WHERE role_id=?", (urid,))
                    c.executemany("INSERT INTO user_role_modules(role_id, module) VALUES (?,?)",
                                  [(urid, m) for m in sorted(UROLE_DEFAULTS[b])])
                # the rollout switch: on for a database with people (today's rule kept), off for a new one
                has_people = c.execute("SELECT 1 FROM users WHERE role!='admin' LIMIT 1").fetchone()
                c.execute("INSERT OR IGNORE INTO app_settings(key, value) VALUES (?, ?)",
                          (UROLE_SERVICE_KEY, "1" if has_people else "0"))
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('user_roles_seeded_v2', datetime('now'))")
                print("[roles] user roles seeded: Full and Basic; years of service count: %s"
                      % ("yes, until the super admin turns it off" if has_people else "no"))
            # The rollout, once (Chris, 2026-10-20, asked how "only a confirmation date counts" goes live: "for those
            # import and more than a year, you can set today date as their confirmation date. For new import and new
            # user, without confirmation date should be marked not confirmed"): everyone here with over a year's
            # service and no confirmation date is confirmed today (MYT), so nobody's access changes on the day; then
            # years of service stop counting. Each one is an audit row; the list is kept (urole_rollout_confirmed) so
            # it can be undone by hand.
            if not c.execute("SELECT value FROM app_settings WHERE key='urole_rollout_done'").fetchone():
                today = _today_myt().isoformat()
                ids = [r[0] for r in c.execute(
                    "SELECT id FROM users WHERE role!='admin' AND left_at IS NULL AND COALESCE(years_of_service, 0) > 1 "
                    "AND (confirmation_date IS NULL OR trim(confirmation_date)='')")]
                for i in range(0, len(ids), 500):
                    chunk = ids[i:i + 500]
                    c.execute("UPDATE users SET confirmation_date=? WHERE id IN (%s)" % ",".join("?" * len(chunk)),
                              [today] + chunk)
                c.executemany("INSERT INTO activity_log(user_id, action, detail, target_user_id) VALUES (NULL, "
                              "'set_confirmed', ?, ?)",
                              [("Confirmed %s: over a year's service and no confirmation date (the Roles & access "
                                "rollout, Chris 2026-10-20)" % today, i) for i in ids])
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('urole_rollout_confirmed', ?)",
                          (json.dumps({"date": today, "ids": ids}),))
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES (?, '0')", (UROLE_SERVICE_KEY,))
                c.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('urole_rollout_done', datetime('now'))")
                print("[roles] rollout: %d people with over a year's service and no confirmation date confirmed %s; "
                      "years of service no longer count" % (len(ids), today))
        c.commit()
        c.close()
    except sqlite3.Error as e:
        if os.environ.get("L360_ALLOW_SCHEMA_FAILURE") == "1":
            print("[roles] WARNING: seeding the admin roles failed: %s" % e)
        else:
            raise


def _it(*items):
    """What a write needs: these items, all of them."""
    return ("items", tuple(items))


def _by(field="action", default="super", **m):
    return {"field": field, "map": m, "default": default}


