# the pages: an admin section's key -> its module; the shared Overview / Progress pages carry the module as `key`
_ACCESS_SECTION_MODULE = {"cycle": "cycle", "pm": "pm", "f360": "f360", "competency": "competency",
                          "calibration": "calibration", "idp": "idp", "people": "people", "leaders": "leaders",
                          "org": "org", "audit": "audit", "reports": "reports", "ticketing": "ticketing",
                          "gradeh": "gradeh"}
# Email (2026-10-24) is in no module: every page of it is the super admin's (Chris, asked before it deployed)
_ACCESS_VIEW_KEY = {"pm": "pm", "f360": "f360", "competency": "competency", "calibration": "calibration",
                    "idp": "idp"}


def admin_access_need(endpoint, form):
    """What a POST to `endpoint` with this form needs: 'always', 'super', or (module, (kinds...))."""
    spec = ADMIN_ACCESS_MAP.get(endpoint, "super")
    if isinstance(spec, dict):
        v = (form.get(spec["field"]) or "").strip().split(":")[0]
        spec = spec["map"].get(v, spec["default"])
    return spec


def admin_perms(u, db=None):
    """{module: set(kinds)} this admin may do, read off their role's items (the super admin: everything)."""
    if not u:
        return {}
    have = admin_items(u, db)
    out = {m: set() for m in ACCESS_MODULE_KEYS}
    for mod, key, kind, _l in ADMIN_ITEMS:
        if key in have:
            out.setdefault(mod, set()).add(kind)
    return out


def admin_can(u, module, kind):
    """Whether this admin's role gives anything of `kind` in `module` (its pages, for kind 'read')."""
    if kind == "read":
        key = ADMIN_READ_ITEM.get(module)
        return bool(key) and key in admin_items(u)
    have = admin_items(u)
    return any(k in have for m_, k, kd, _l in ADMIN_ITEMS if m_ == module and kd == kind)


def _access_page_module(endpoint, view_args=None, path=None):
    """The module a GET page belongs to (None: everyone who opens the admin area reads it): the shared module pages by
    their key, a menu page by its section, anything else (a download, a sub-page) by the menu page that owns its path,
    longest first, as admin_shell finds it."""
    if endpoint in ("admin_module_dashboard", "admin_module_progress", "admin_module_progress_xlsx",
                    "admin_module_settings"):
        return _ACCESS_VIEW_KEY.get((view_args or {}).get("key"))
    if endpoint == "admin_list_view":   # the people behind a count are that count's module's (2026-10-20)
        spec = ADMIN_LISTS.get((view_args or {}).get("key") or "")
        return spec["module"] if spec else None
    if endpoint == "admin_report_view":   # an on-screen report is its module's (2026-10-19)
        rep = HTML_REPORT_BY_KEY.get((view_args or {}).get("key") or "")
        return _HR_SECTION_MODULE.get(rep[0]) if rep else None
    if endpoint == "admin_person":
        # a person's page is People's; a module's tab (the panel a Progress list opens) is that module's
        return _ACCESS_PERSON_TAB.get(request.args.get("tab") or "", "people") if has_request_context() else "people"
    if endpoint in _ACCESS_PAGE_MODULE:
        return _ACCESS_PAGE_MODULE[endpoint]
    if not path:
        return None
    best, mod = -1, None
    for h, m in _access_path_modules():
        if (path == h or path.startswith(h.rstrip("/") + "/")) and len(h) > best:
            best, mod = len(h), m
    return mod


def _access_path_modules():
    """[(menu page path, module)] for the pages of the sections an admin's access covers, built once."""
    global _ACCESS_PATHS
    if _ACCESS_PATHS is None:
        out = []
        for sec in ADMIN_SECTIONS:
            m = _ACCESS_SECTION_MODULE.get(sec["key"])
            if not m:
                continue
            for pg in _section_pages(sec):
                try:
                    out.append((_admin_page_href(pg).split("?")[0], m))
                except Exception:
                    pass
        _ACCESS_PATHS = out
    return _ACCESS_PATHS


_ACCESS_PATHS = None
_ACCESS_PERSON_TAB = {"performance": "pm", "competency": "competency", "f360": "f360", "plan": "idp"}


def _page_access_module(page):
    """The module of a menu page (a dict of ADMIN_SECTIONS)."""
    if page.get("args", {}).get("key"):
        return _ACCESS_VIEW_KEY.get(page["args"]["key"])
    return _ACCESS_PAGE_MODULE.get(page.get("ep"))


def admin_access_refused(u):
    """Whether this request is something this BG or unit admin's access doesn't cover: a page of a module they can't
    read, or a change their ticks don't give. The super admin is never refused here."""
    if not u or is_super(u) or not is_admin(u):
        return False
    if request.method in ("GET", "HEAD", "OPTIONS"):
        mod = _access_page_module(request.endpoint, request.view_args, request.path)
        return bool(mod) and not admin_can(u, mod, "read")
    need = admin_access_need(request.endpoint, request.form)
    if need == "always":
        return False
    if need == "lms":   # AI+ Learning: the super admin (never here) or an L&D admin
        return not is_lnd_admin(u)
    if need == "super":
        return True
    _kind, items = need
    return not all(admin_can_item(u, it) for it in items)


def role_summary(items):
    """('View only' / a preset's name / 'Custom', the number of changes it gives) for a set of items."""
    items = set(items)
    name = next((lbl for key, lbl, _d in ACCESS_PRESETS if role_preset_items(key) == items), "Custom")
    return name, len([k for k in items if ADMIN_ITEM_BY_KEY.get(k, ("", "", "read"))[2] != "read"])


def role_summary_words(items):
    """'View only' / 'View only + 3 changes' / 'Custom: reads 9 of 11 modules, 4 changes' -- a role card's line."""
    items = set(items)
    n = len([k for k in items if ADMIN_ITEM_BY_KEY.get(k, ("", "", "read"))[2] != "read"])
    # a module only ticked by name (Ticketing) isn't part of View only: it is named when the role has it; one with no
    # item at all (Audit and usage, the super admin's alone) isn't a module a role can read
    hidden = _admin_items_hidden()
    base = [m for m in ACCESS_MODULE_KEYS if ADMIN_READ_ITEM.get(m) and ADMIN_READ_ITEM[m] not in ADMIN_ITEMS_EXPLICIT
            and ADMIN_READ_ITEM[m] not in hidden]
    reads = sum(1 for m in base if ADMIN_READ_ITEM.get(m) in items)
    head = "View only" if reads == len(base) else "Reads %d of %d modules" % (reads, len(base))
    more = [ACCESS_LABEL[m] for m in ACCESS_MODULE_KEYS if m not in base and ADMIN_READ_ITEM.get(m) in items]
    return head + "".join(" + " + x for x in more) + (" + %d change%s" % (n, "" if n == 1 else "s") if n else "")


def admin_access_client(u):
    """What the admin portal's script needs to switch off what this admin can't do: their role's items and every admin
    write route's pattern with its rule (admin.js). The server still refuses whatever the page lets through."""
    routes = []
    for r in app.url_map.iter_rules():
        if not r.rule.startswith("/admin") or "POST" not in r.methods:
            continue
        rx = "^" + re.sub(r"<[^>]+>", "[^/]+", re.escape(r.rule).replace(r"\<", "<").replace(r"\>", ">")) + "$"
        spec = ADMIN_ACCESS_MAP.get(r.endpoint, "super")
        routes.append([rx, spec if not isinstance(spec, dict) else {"f": spec["field"], "m": spec["map"],
                                                                     "d": spec["default"]}])
    return {"items": sorted(admin_items(u)), "lms": bool(is_lnd_admin(u)), "routes": routes}


def admin_access_banner(u):
    """The script data on a granted admin's portal pages (no note on the page: Chris, 2026-10-20, board D)."""
    return {"client": admin_access_client(u)}


def admin_required(view):
    @wraps(view)
    def wrapped(*a, **kw):
        u = current_user()
        if not u:
            return redirect(url_for("login"))
        if not is_admin(u):
            abort(403)
        if admin_access_refused(u):   # their ticks (2026-10-19); read only where none are set
            if request.method == "GET" and request.endpoint != "admin_overview":
                mod = _access_page_module(request.endpoint, request.view_args, request.path)
                flash("Your admin role doesn't include %s." % ACCESS_LABEL.get(mod, "that"), "error")
                return redirect(url_for("admin_overview"))
            abort(403)
        return view(*a, **kw)
    return wrapped


def super_required(view):
    """Only the super admin (org-wide). Used for org-level settings."""
    @wraps(view)
    def wrapped(*a, **kw):
        u = current_user()
        if not u:
            return redirect(url_for("login"))
        if not is_super(u):
            abort(403)
        return view(*a, **kw)
    # Read by _admin_nav_allowed(): the nav menu asks the route itself who may
    # open it, instead of keeping a second, hand-maintained copy of the answer
    # that can drift into offering a link that 403s.
    wrapped._nav_gate = "super"
    return wrapped


# ---------------------------------------------------------------------------
# Review cycles (seasons)
# ---------------------------------------------------------------------------
def active_cycle(db=None):
    """The current cycle (is_active=1) — where new ratings/edits happen.
    Cached per request. Returns a row, or None if no cycle exists yet."""
    cyc = getattr(g, "_active_cycle", None)
    if cyc is None:
        db = db or get_db()
        cyc = db.execute(
            "SELECT * FROM cycles WHERE is_active=1 ORDER BY id LIMIT 1").fetchone()
        g._active_cycle = cyc
    return cyc


def active_cycle_id(db=None):
    cyc = active_cycle(db)
    return cyc["id"] if cyc else None


def list_cycles(db=None):
    """All cycles, active first then newest — for the admin switcher."""
    db = db or get_db()
    return db.execute(
        "SELECT * FROM cycles ORDER BY is_active DESC, year DESC, half DESC, id DESC").fetchall()


def viewed_cycle(db=None):
    """The cycle an ADMIN is currently looking at. Defaults to the active
    cycle; an admin may switch to a past cycle (read-only) via ?cycle=<id>,
    persisted in the session. Validated against real cycle ids."""
    db = db or get_db()
    cyc = getattr(g, "_viewed_cycle", None)
    if cyc is not None:
        return cyc
    cid = session.get("view_cycle_id")
    cyc = None
    if cid:
        cyc = db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone()
    if not cyc:
        cyc = active_cycle(db)
    g._viewed_cycle = cyc
    return cyc


def viewed_cycle_id(db=None):
    cyc = viewed_cycle(db)
    return cyc["id"] if cyc else None


