def _fit_gate_ability(db, u):
    """The ability the AI fit's gate checks before the route knows its scope: cg.fit for a pure calibrator, bu.fit
    otherwise, None for a login holding both a unit and a group (the route then checks the scope it works in)."""
    try:
        ts = {t_ for t_, _k in calibration_tier_of(db, u)}
    except Exception:
        return "bu.fit"
    if "bugrp" in ts and "buceo" in ts:
        return None
    return "cg.fit" if "bugrp" in ts else "bu.fit"


def _calib_fit_scope_off(db, u, tier, scope):
    """The sentence when the fit is switched off in the scope the caller works in (a unit's bu.fit, a group's cg.fit),
    else None."""
    return leader_ability_off(db, u, leader_tier_ability(tier, "fit", scope))


@app.before_request
def _leader_gate():
    """A seat ability the super admin switched off: its page goes to the dashboard with one line, a write gets 403
    (JSON for the journey's own posts)."""
    ab = LEADER_ENDPOINTS.get(request.endpoint or "")
    if not ab or not session.get("user_id"):
        return None
    u = current_user()
    if ab == "bu.fit" and u:   # the fit is a unit's (bu.fit) or a calibration group's (cg.fit): by who is asking
        ab = _fit_gate_ability(get_db(), u)
        if not ab:
            return None   # holds both: the route checks the scope it works in (_calib_fit_scope_off)
    if not u or leader_can(u, ab):
        return None
    msg = leader_ability_off(get_db(), u, ab)
    if request.method == "GET":
        flash(msg, "info")
        return redirect(url_for("dashboard"))
    if request.path.startswith("/review/"):
        return jsonify(ok=False, error=msg), 403
    abort(403)


@app.before_request
def _urole_gate():
    """A person's own module that their user role doesn't open is shut for them, as a module switched off: a page goes
    to their dashboard with one line, a write gets a bare 404. Signed-out requests go on to the route's own sign-in."""
    mod = UROLE_ENDPOINTS.get(request.endpoint or "")
    if not mod or not session.get("user_id"):
        return None
    if request.method == "GET" and request.args.get("period"):   # a past cycle's page: its history entry, as before
        return None
    u = current_user()
    if not u or is_admin(u) or urole_allows(u, mod):
        return None
    if request.method == "GET":
        flash("%s isn't part of your OneHR access." % dict((k, l) for k, l, _n in UROLE_MODULES)[mod].split(":")[0],
              "info")
        return redirect(url_for("dashboard"))
    abort(404)


