def _classic_ai_target(db, u, endpoint, args):
    """Where a classic module page lives in the AI+ way for THIS person now, or None to keep serving it."""
    if not u or is_admin(u) or not active_cycle_id(db) or not cycle_module_on("review", db):
        return None
    if not ai_draft.review_agent_available() or not _review_unified_on(u):
        return None
    st = review_state(db, u)
    mine_keys = set(_journey_chat_stage_keys(st))

    def mine(*stages):
        for k in stages:
            if k in mine_keys:
                return url_for("review_journey", stage=k)
        return None

    def team(stage, report=None):
        if not _review_manages_team(db, u) or stage not in {x["key"] for x in _journey_team_live_stages(st, "team")}:
            return None
        if report:
            return url_for("review_journey", view="team", stage=stage, mode="detail", report=report)
        return url_for("review_journey", view="team", stage=stage)

    def lead(*pairs, **extra):
        views = _journey_leader_views(db, u)
        for view, stage in pairs:
            if view in views and stage in {x["key"] for x in _journey_team_live_stages(st, view)}:
                return url_for("review_journey", view=view, stage=stage, **extra)
        return None

    e = endpoint
    if e in ("my_assessments", "rate"):
        # no tour exception: the Account menu's "Show me around" that replayed it is gone (2026-10-12)
        return mine("feedback")
    if e == "technical_my_view":
        return mine("competency")
    if e == "performance_my_view":
        pid = request.args.get("period", type=int)
        if pid and pid != active_pm_period_id(db):
            # a past half: the record panel on the dashboard (it opens from ?record=)
            return (url_for("dashboard", record=pid)
                    if any(pid in (r.get("period_id"), r.get("cycle_id")) for r in _record_rows(db, u)) else None)
        return mine("account", "checkin")
    if e == "performance_kpi_setting_view":
        agree = next((x for x in st["stages"] if x["key"] == "agree"), None)
        # the KPI-setting chat only while the scorecard is being built; agreed or with the approver -> the check-in
        if agree and agree["state"] == REVIEW_STATE_OPEN:
            return url_for("review_setting")
        return mine("account", "checkin") if (agree and agree["state"] != REVIEW_STATE_LATER) else None
    if e in ("idp_view", "idp_career_view"):
        return None if request.args.get("year") else mine("career_plan")
    if e in ("review_account", "review_checkin"):
        return mine("account", "checkin")
    if e == "review_competency":
        return mine("competency")
    if e in ("review_ahead", "review_career"):
        return mine("career_plan")
    if e == "review_summary":
        return url_for("review_journey") if mine_keys else None
    if e in ("performance_team_view", "review_team"):
        return team("pm_review")
    if e in ("performance_team_member_view", "review_team_member"):
        return team("pm_review", args.get("subject_id"))
    if e == "technical_team_view":
        return team("tm_review")
    if e == "technical_team_member_view":
        return team("tm_review", args.get("subject_id"))
    if e == "idp_team_view":
        return team("plan_review")
    if e == "idp_team_member_view":
        return team("plan_review", args.get("subject_id"))
    if e == "pm_calibration_home":
        return lead(("dept", "calibration"), ("bu", "calibration"), ("bg", "talent_box"))
    if e == "pm_calibration_hod_view":
        return lead(("dept", "calibration"))
    if e == "pm_calibration_buceo_view":
        return lead(("bu", "calibration"))
    if e in ("pm_calibration_bgceo_view", "calibration_bg_view", "talent_box_bgceo"):
        return lead(("bg", "talent_box"))   # a group's Talent Box has no AI+ version: kept
    if e == "talent_box_home":
        to = lead(("bg", "talent_box"))
        if to or not any(t == "buceo" for t, _k in calibration_tier_of(db, u)):
            return to
        # a BU CEO's box is their BU calibration now (security finding 1b-08, 2026-10-31); a Group Chief keeps the page,
        # whose chooser holds their group's box beside the unit
        if db.execute("SELECT 1 FROM pm_calibration_groups WHERE calibrator_id=? LIMIT 1", (u["id"],)).fetchone():
            return None
        return lead(("bu", "calibration"), ("bu", "calibration_pot"))
    if e == "talent_box_buceo":   # the unit's box -> that unit's calibration: Performance when live, else Potential
        if not is_buceo_of(u, args.get("bg"), args.get("company")):
            return None   # not their unit: the page answers (403)
        return lead(("bu", "calibration"), ("bu", "calibration_pot"), bu_unit=bu_scope_pick_key((args["bg"], args["company"])))
    if e == "pm_calibration_group_view":   # the Group Chief's AI+ calibration (canvas G2, 2026-10-10)
        return lead(("group", "group_calib"))
    if e == "calibration_home":
        return lead(("dept", "calibration_pot"), ("bu", "calibration_pot"), ("bg", "talent_box"))
    if e == "calibration_hod_view":
        return lead(("dept", "calibration_pot"))
    if e == "calibration_company_view":
        return lead(("bu", "calibration_pot"))
    return None


@app.before_request
def _classic_archive_gate():
    """Send a classic module page to its AI+ replacement (_classic_ai_target). A page load only: never a write, never a
    script's fetch (a fetch that follows a write's redirect to a classic page keeps getting the page), never anyone
    signed out (the route's own login check answers them)."""
    if request.method != "GET" or request.endpoint not in _CLASSIC_PAGES or not session.get("user_id"):
        return None
    mode = request.headers.get("Sec-Fetch-Mode")
    if (mode and mode != "navigate") or request.headers.get("X-Requested-With") == "XMLHttpRequest":
        return None
    db = get_db()
    try:
        target = _classic_ai_target(db, current_user(), request.endpoint, request.view_args or {})
    except Exception as e:   # never stand between someone and the page they asked for
        app.logger.warning("classic archive gate fell through for %s: %s", request.endpoint, e)
        return None
    return redirect(target) if target else None


