@app.before_request
def _window_gate():
    """Refuse a write outside its role's window in that module (WINDOW_CELLS; Chris, 2026-10-02). After the module gate:
    a switched-off module is a 404 first. A fetch / the journey gets {ok: false, error, window_closed}; a form post gets
    the sentence as a flash and goes back where it came from."""
    if request.method in ("GET", "HEAD", "OPTIONS") or not session.get("user_id"):
        return None
    ep = request.endpoint or ""
    cells = list(WINDOW_ENDPOINT_CELLS.get(ep, ()))
    if ep == "review_team_approve_bulk":
        cells = [c for c in [_WINDOW_BULK_STAGE.get((request.form.get("stage") or "").strip())] if c]
    if not cells:
        return None
    if ep in _WINDOW_SUPER_PASS and is_super(current_user()):   # shared with the super admin: the writer asks by tier
        return None
    db = get_db()
    msg = next((m for m in (window_closed(db, c, allow_added=ep in _ADDED_PASS_ROUTES) for c in cells) if m), None)
    if not msg:
        return None
    wants_json = (request.path.startswith("/review/") or request.form.get("ajax") == "1" or request.is_json
                  or "autosave" in ep or request.headers.get("Sec-Fetch-Mode", "navigate") != "navigate"
                  or request.accept_mimetypes.best == "application/json")
    if wants_json:
        return jsonify(ok=False, error=msg, window_closed=True), 409
    flash(msg, "error")
    return redirect(_referer_path(url_for("dashboard")))


# THE TALENT BOX IS HIDDEN UNTIL IT OPENS (Chris, 2026-11-04): every page / fetch that returns the BG CEO's or a Group Chief's box
# (people, bands, counts, the AI's reading of one person) answers with the Talent Box's window sentence while tb_bgceo is not
# open (_tb_hidden_msg). The journey's own readers get nothing through _journey_talent_box_scope (the one scope function);
# these are the classic pages and the person-level fetches that read the box on their own. Read only: the writers keep
# _window_gate and their own checks.
_TB_HIDE_ENDPOINTS = frozenset({
    "talent_box_bgceo", "talent_box_group", "talent_pip_bgceo", "talent_pip_group", "talent_promotion_bgceo",
    "talent_promotion_group", "pm_calibration_bgceo_view", "pm_calibration_group_view", "calibration_bg_view",
    "review_team_tbox_insight", "review_team_tbox_person", "review_team_tbox_remark"})
# shared with the HOD / BU CEO's curve: held back only when the request is the BG or Group view's
_TB_HIDE_VIEW_ENDPOINTS = frozenset({"review_team_calib_summary", "review_team_pot_summary", "review_team_insights"})


@app.before_request
def _tb_hide_gate():
    """Refuse a read of a Talent Box that has not opened (_TB_HIDE_ENDPOINTS). Only for a BG CEO or a Group Chief (anyone else
    keeps the route's own 403), never the super admin. A fetch gets {ok: false, error, window_closed}; a page gets the sentence
    as a flash on the dashboard."""
    if not session.get("user_id"):
        return None
    ep = request.endpoint or ""
    if ep not in _TB_HIDE_ENDPOINTS:
        if ep not in _TB_HIDE_VIEW_ENDPOINTS or (request.values.get("view") or "").strip() not in ("bg", "group"):
            return None
    db = get_db()
    u = current_user()
    if not u or not _review_bg_leader(db, u):
        return None
    msg = _tb_hidden_msg(db, u)
    if not msg:
        return None
    wants_json = (request.path.startswith("/review/") or request.is_json
                  or request.headers.get("Sec-Fetch-Mode", "navigate") != "navigate"
                  or request.accept_mimetypes.best == "application/json")
    if wants_json:
        return jsonify(ok=False, error=msg, window_closed=True), 409
    flash(msg, "error")
    return redirect(url_for("dashboard"))


# ---------------------------------------------------------------------------
# Thresholds / scoring
# ---------------------------------------------------------------------------
def get_thresholds():
    try:
        rows = get_db().execute(
            "SELECT key, value FROM app_settings WHERE key IN ('low_max','mid_max')"
        ).fetchall()
    except sqlite3.OperationalError:
        return DEFAULT_LOW_MAX, DEFAULT_MID_MAX
    d = {r["key"]: float(r["value"]) for r in rows}
    return d.get("low_max", DEFAULT_LOW_MAX), d.get("mid_max", DEFAULT_MID_MAX)


def set_thresholds(low_max, mid_max):
    db = get_db()
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('low_max', ?)",
               (str(low_max),))
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('mid_max', ?)",
               (str(mid_max),))
    db.commit()


# ---------------------------------------------------------------------------
# Whether the potential band is shown OUTSIDE the admin views
#
# The band (Low/Mid/High) is not part of the 360 assessment every round -- when
# it isn't, it comes off the four employee/manager-facing surfaces (a person's
# own My Feedback, a manager's report drill-through, Team view, HOD view) while
# every admin view keeps it. A setting rather than a code change, because
# whether to show it is a per-round HR decision, not an engineering one.
#
# Display only: this changes nothing about how a band is computed, who may open
# a report, or what an export contains. It also does NOT touch the calibration
# modules -- a calibrator's whole job is deciding the band, so those pages are
# governed by their own tier permissions, not by this switch.
# ---------------------------------------------------------------------------
def get_show_potential_band():
    """True if the potential band should be shown to employees and managers.
    Defaults to FALSE when the key was never set -- the band is opt-in per
    round, so a fresh database (or a deploy that lands before HR has touched
    Settings) keeps it hidden rather than leaking it by omission."""
    try:
        row = get_db().execute(
            "SELECT value FROM app_settings WHERE key='show_potential_band'").fetchone()
    except sqlite3.OperationalError:
        return False
    return bool(row) and row["value"] == "1"


def set_show_potential_band(enabled):
    db = get_db()
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('show_potential_band', ?)",
               ("1" if enabled else "0",))
    db.commit()


# ---------------------------------------------------------------------------
# Extreme-assessor score correction
#
# An assessor whose ENTIRE submitted panel this cycle is 100% "no" (or 100%
# "yes") is a possible rater-quality problem -- already surfaced today by
# /admin/assessor-extremes, detection-only. When enabled, every subject rated
# by an always-no assessor gets a configurable bonus added to their score;
# every subject rated by an always-yes assessor gets a configurable penalty
# subtracted. Additive (on top of the still-counted response, not an
# exclusion), stacks per distinct extreme assessor on a subject's panel, and
# applies everywhere a band/score is shown -- including the subject's own
# report -- confirmed with the user, not an admin-only overlay.
# ---------------------------------------------------------------------------
# Which surfaces may offer "Draft with AI". An Azure OpenAI client is wired into
# the 360 rating form, technical self-assessment and manager review, PM results,
# KPI setting, manager moderation and IDP -- and until now the ONLY control
# anywhere was one checkbox on IDP settings. HR could not switch off AI-assisted
# 360 comments or moderation remarks, and no admin screen even showed the
# feature existed, while email by contrast gets a "Not configured" card.
#
# Default ON, so this changes nothing on its own: it hands over a switch that
# was never offered rather than making the decision. Whether 360 free text in
# particular should default off is Chris's call, not this commit's.
# ONE store for every AI switch (2026-10-11, Chris approved): the Career Plan's (once idp_ai_enabled in the IDP rules)
# and the calibration assistant's (once calib_assist) are ai_* keys like the rest -- "1" on, "0" off, absent = on.
# Each still has its card on its own module's Settings page.
AI_MODULES = (
    ("ai_360", "360 feedback", "Rating comments on the 360 form"),
    ("ai_tc", "Technical competency", "Self-assessment and manager review remarks"),
    ("ai_pm", "Performance", "KPI results, KPI setting and manager moderation"),
    ("ai_review", "Guided review", "On-demand summary and suggested citations in the conversation"),
    ("ai_idp", "Career Plan", "Development plan suggestions and the career conversation"),
    ("ai_calib", "Calibration assistant", "The AI+ calibration chat, summaries and curve fit for HODs and CEOs"),
)
# where each switch's card lives (its save goes back there)
_AI_MODULE_HOME = {"ai_360": "f360", "ai_tc": "competency", "ai_pm": "pm", "ai_review": "org", "ai_idp": "idp",
                   "ai_calib": "calibration"}


def ai_module_settings():
    """{key: bool} for every AI surface. Absent means on, so an existing
    deployment keeps behaving as it did before the switch existed."""
    keys = [k for k, _l, _d in AI_MODULES]
    try:
        rows = get_db().execute(
            "SELECT key, value FROM app_settings WHERE key IN (%s)"
            % ",".join("?" * len(keys)), keys).fetchall()
    except sqlite3.OperationalError:
        return {k: True for k in keys}
    d = {r["key"]: r["value"] for r in rows}
    return {k: d.get(k, "1") == "1" for k in keys}


def ai_on(module_key):
    """Whether this surface may offer AI drafting: the transport is configured
    AND HR has not switched this module off. One call, so a template gate and
    its route guard cannot disagree."""
    return ai_draft.is_configured() and ai_module_settings().get(module_key, True)


def set_ai_module_settings(values):
    db = get_db()
    for k, _l, _d in AI_MODULES:
        db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",
                   (k, "1" if values.get(k) else "0"))
    db.commit()


def get_extremes_adjustment_settings():
    """(enabled, bonus_points, penalty_points), same app_settings idiom as
    get_thresholds()."""
    try:
        rows = get_db().execute(
            "SELECT key, value FROM app_settings WHERE key IN "
            "('extremes_adjust_enabled','extremes_bonus_points','extremes_penalty_points')"
        ).fetchall()
    except sqlite3.OperationalError:
        return False, DEFAULT_EXTREMES_BONUS, DEFAULT_EXTREMES_PENALTY
    d = {r["key"]: r["value"] for r in rows}
    enabled = d.get("extremes_adjust_enabled") == "1"
    try:
        bonus = float(d["extremes_bonus_points"]) if "extremes_bonus_points" in d else DEFAULT_EXTREMES_BONUS
    except (TypeError, ValueError):
        bonus = DEFAULT_EXTREMES_BONUS
    try:
        penalty = float(d["extremes_penalty_points"]) if "extremes_penalty_points" in d else DEFAULT_EXTREMES_PENALTY
    except (TypeError, ValueError):
        penalty = DEFAULT_EXTREMES_PENALTY
    return enabled, bonus, penalty


def talent_status_for(db, subject, cycle_id, released_only=True):
    """This person's FINAL talent status for a cycle, or None.

    Took a performance period AND a 360 cycle until those merged into the one
    review cycle; it is a single argument now.

    Final means post-calibration: both axes resolve through their locked
    calibration adjustments (pm_effective_band / effective_band), so what the
    person is shown is the cell the calibrators actually agreed -- not the raw
    derivation that fed into the room. If nothing was adjusted, the resolvers
    fall through to raw and the answer is the same.

    `released_only` is the gate, and it is per-person by design: a talent
    status reaches the individual only when a super admin releases it, exactly
    like the 360 potential report. There is deliberately no org-wide switch --
    two gates that can disagree is worse than one that can't.

    Returns {"name", "slug", "perf", "pot"} so a caller can both name the
    category and place the marker in the miniature grid. At Mid-Year both bands stop at the HOD, so the HOD's final
    bands place them (Chris, 2026-10-12)."""
    if not cycle_id:
        return None
    if released_only and not db.execute(
            "SELECT 1 FROM talent_releases WHERE cycle_id=? AND subject_id=?",
            (cycle_id, subject["id"])).fetchone():
        return None
    overall = _dash_overall(db, subject["id"], cycle_id)
    _pe = pm_effective_band(db, subject, cycle_id, overall["label"] if overall else None)
    # no approved score and no band a calibration tier set directly (2026-09-29) -> nothing to place
    if not overall and _pe.get("source") == "raw":
        return _imported_talent(db, subject, cycle_id)
    perf = _pe["band"]
    pot = effective_band(db, subject, cycle_id)
    pot_band = pot["band"] if pot.get("score_valid") else None
    cat = talent_category(perf, pot_band) if (perf and pot_band) else None
    if not cat:
        return _imported_talent(db, subject, cycle_id)
    return {"name": cat, "slug": TALENT_CATEGORY_SLUG.get(cat, ""),
            "perf": perf, "pot": pot_band}


def _imported_talent(db, subject, cycle_id):
    """A past Year-End's talent status HR imported from before OneHR (tools/import_talent_history.py, the production
    rollout, 2026-10-14: "we have 2023, 2024, and 2025 year end talent status only"), when nothing in OneHR places them
    for that cycle; `imported` says so. perf / pot are the year's performance and potential bands where HR's record
    holds both (Chris, 2026-10-22, HR's fuller 2023-2025 file: "the calibrated performance and potential band and talent
    status ... so it reflects on the user dashboard of their history record"), else None: the import refuses a pair
    its status contradicts, so they always place it. The release gate is the caller's (talent_status_for's)."""
    c = db.execute("SELECT * FROM cycles WHERE id=?", (cycle_id,)).fetchone()
    y, h = _cycle_year_half(c) if c else (None, None)
    if not (y and h == 2):
        return None
    r = db.execute("SELECT category, performance_band, potential_band FROM talent_status_history WHERE subject_id=? "
                   "AND year=? AND source='import'", (subject["id"], y)).fetchone()
    if not r or r["category"] not in TALENT_CATEGORY_SLUG:
        return None
    perf, pot = _imported_bands(r["performance_band"], r["potential_band"])
    return {"name": r["category"], "slug": TALENT_CATEGORY_SLUG[r["category"]], "perf": perf, "pot": pot,
            "imported": True}


def _imported_bands(perf, pot):
    """(performance band, potential band) of an imported year as the app spells them, or (None, None) unless both are
    there and readable: a year shows both of HR's bands or neither."""
    if perf in PM_BAND_ORDER and pot in TALENT_POTENTIAL_ORDER:
        return perf, pot
    return None, None


def _imported_talent_map(db, cycle_id, subject_ids):
    """{subject_id: {"name", "perf", "pot"}} of the imported talent statuses for a past Year-End cycle (see
    _imported_talent), for a list of people -- one read per 900."""
    c = db.execute("SELECT * FROM cycles WHERE id=?", (cycle_id,)).fetchone()
    y, h = _cycle_year_half(c) if c else (None, None)
    if not (y and h == 2) or not subject_ids:
        return {}
    out = {}
    ids = list(subject_ids)
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        for r in db.execute(
                "SELECT subject_id, category, performance_band, potential_band FROM talent_status_history WHERE "
                "year=? AND source='import' AND subject_id IN (%s)" % ",".join("?" * len(chunk)), [y] + chunk):
            if r[1] in TALENT_CATEGORY_SLUG:
                perf, pot = _imported_bands(r[2], r[3])
                out[r[0]] = {"name": r[1], "perf": perf, "pot": pot}
    return out


# A PERSON'S PAST TALENT STATUS, for the BU CEO's and BG CEO's agents only, and only when asked (Chris, 2026-10-22:
# "give the BU CEO and BG CEO agents each person's past three years of talent status ... only answer if the BUCEO or
# BGCEO query about it"; "do not show on the talent box or calibration profile"). A tool of its own, so the years reach
# the model only when it calls it; never on any page.
_PAST_TALENT_YEARS = 3
_PAST_TALENT_TIERS = ("buceo", "bgceo")
_PAST_TALENT_FROM = {"import": "Group People's records (before OneHR)", "calibration": "OneHR"}
_PAST_TALENT_BRIEF = (
    "PAST TALENT STATUS (only when asked): when they ask about someone's talent status in a previous year (last year, "
    "2024, the past few years, their history), call past_talent{subject} and answer from what it returns: give each "
    "year as its line from `years`, keeping where it came from (Group People's records from before OneHR, or OneHR); a year with no "
    "record is said as no record, never guessed. EVERY time they ask, give each year's line in full, even if you gave it "
    "before (never just 'that covers it'). Never bring past years up yourself -- nor again later in the conversation "
    "unless they ask again -- never use them to suggest or justify a move, and never put them in a reason you record.")


def _past_talent(db, subject_id, n=_PAST_TALENT_YEARS):
    """[{year, status, performance, potential, from}] for the n Year-Ends before the active cycle's year, newest first,
    from talent_status_history (HR's import, or OneHR's own lock); a year with no record reads status None."""
    act = active_cycle(db)
    y = _cycle_year_half(act)[0] if act else None
    if not y:
        return []
    got = {r["year"]: r for r in db.execute(
        "SELECT year, category, performance_band, potential_band, source FROM talent_status_history "
        "WHERE subject_id=? AND year < ? AND year >= ?", (subject_id, y, y - n))}
    out = []
    for yr in range(y - 1, y - n - 1, -1):
        r = got.get(yr)
        if not r or r["category"] not in TALENT_CATEGORY_SLUG:
            out.append({"year": yr, "status": None, "note": "no record", "said": "%d: no record" % yr})
            continue
        perf, pot = _imported_bands(r["performance_band"], r["potential_band"])
        frm = _PAST_TALENT_FROM.get(r["source"], "OneHR")
        perf_w = PM_LABEL_NAMES.get(perf, perf) if perf else None
        # the line the agent gives as it stands, so where it came from is never dropped (Luna kept it 1 in 3 without)
        said = "%d: %s%s, from %s" % (yr, r["category"],
                                     " (%s performance, %s potential)" % (perf_w, pot) if perf_w and pot else "", frm)
        out.append({"year": yr, "status": r["category"], "performance": perf_w, "potential": pot, "from": frm,
                    "said": said})
    return out


# A PERSON'S PROFILE for the BG CEO's agent, when asked (Chris, 2026-10-22: "give the BG CEO's agent each person's joined
# date, years of service and confirmation date when asked, like the BU CEO's agent has"; "please ensure this only work
# for CEO and not the other role"). The BU CEO's calibration prompt already lists its population's profiles
# (_journey_team_profiles); the Talent Box has no such list, so a tool for one person at a time, the BG CEO's only.
_PROFILE_TOOL_TIERS = ("bgceo",)
_PROFILE_TOOL_BRIEF = (
    "THEIR PROFILE (when asked): questions about someone's role, job grade, department, company, employment type, "
    "tenure, joined or confirmation date, years of service or line manager: call person_profile{subject} and answer "
    "plainly from what it returns; say so if a field isn't on record. Years of service is as Group People's roster records it.")


def _person_profile_tool(db, tier, ctx, args):
    """The person_profile{subject} tool: one person's profile facts (_TEAM_PROFILE_FIELDS), someone in this BG CEO's own
    scope only; any other tier gets 'unknown tool'."""
    if tier not in _PROFILE_TOOL_TIERS:
        return {"ok": False, "error": "unknown tool"}
    subj, err = _calib_resolve_subject(ctx, (args or {}).get("subject"))
    if err:
        return {"ok": False, "error": err}
    r = db.execute(
        "SELECT x.full_name, x.employee_id, x.job_title, x.job_grade, x.department, x.company, x.business_group, "
        "x.employment_type, x.joined_date, x.confirmation_date, x.years_of_service, x.position_start_date, "
        "x.work_location, m.full_name AS line_manager FROM users x LEFT JOIN users m ON m.id=x.manager_id "
        "WHERE x.id=?", (subj["id"],)).fetchone()
    return {"ok": True, "profile": {label: r[col] for col, label in _TEAM_PROFILE_FIELDS if r[col] not in (None, "")}}


def _past_talent_tool(db, tier, ctx, args):
    """The past_talent{subject} tool: someone in this calibrator's own scope, BU CEO or BG CEO only."""
    if tier not in _PAST_TALENT_TIERS:
        return {"ok": False, "error": "unknown tool"}
    subj, err = _calib_resolve_subject(ctx, (args or {}).get("subject"))
    if err:
        return {"ok": False, "error": err}
    # only the ready lines go to the model: short, and each carries its source (the loop cuts a tool result)
    return {"ok": True, "person": subj["full_name"], "years": [x["said"] for x in _past_talent(db, subj["id"])]}


def set_extremes_adjustment_settings(enabled, bonus, penalty):
    db = get_db()
