def statements_for_grade(db, jg, cycle_id):
    """The behaviours a subject at job grade `jg` is rated on, from the given
    cycle's framework (resolved via that cycle's tier bands)."""
    return statements_for_tier(db, _cycle_tier_n(db, jg, cycle_id), cycle_id)


def statements_for_tier(db, tn, cycle_id):
    """The behaviours of tier `tn` in the given cycle's framework (what statements_for_grade resolves a grade to)."""
    return db.execute(
        """SELECT cs.id AS statement_id, cs.text, cs.seq, cs.is_future,
                  cc.id AS criterion_id, cc.name AS criterion_name,
                  cc.description AS criterion_description, cc.sort_order
           FROM cycle_statements cs JOIN cycle_criteria cc ON cc.id = cs.criterion_id
           WHERE cs.cycle_id = ? AND cs.tier_n = ? ORDER BY cc.sort_order, cs.seq""",
        (cycle_id, tn),
    ).fetchall()


def _fb_assignment_tier(db, aid):
    """The tier of the statements a 360 rating's own answers hold (2026-11-08, profile guards piece 2): what a SUBMITTED
    rating must show, never its subject's live tier (a job grade moved to another tier after the rater submitted left the
    card listing the new tier's statements with the old answers hidden). A rating whose rows span two tiers (left by the
    days before the tier guard) answers with the tier holding the most answers, then the most rows, then the lower tier.
    None when the rating holds no rows. One small query; a reader over many ratings asks _fb_assignment_tiers."""
    return _fb_assignment_tiers(db, [aid]).get(aid)


def _fb_assignment_tiers(db, aids):
    """{assignment_id: held tier_n} for the ratings that hold rows (ONE query per 500): `_fb_assignment_tier` over many."""
    best, out = {}, {}
    ids = list(dict.fromkeys(int(x) for x in aids if x is not None))
    for k in range(0, len(ids), _FB_CHUNK):
        part = ids[k:k + _FB_CHUNK]
        for r in db.execute(
                "SELECT r.assignment_id AS aid, cs.tier_n AS tn, COUNT(r.answer) AS ans, COUNT(*) AS n "
                "FROM responses r JOIN cycle_statements cs ON cs.id=r.statement_id "
                "WHERE r.assignment_id IN (%s) GROUP BY r.assignment_id, cs.tier_n" % ",".join("?" * len(part)),
                part).fetchall():
            key = (-(r["ans"] or 0), -(r["n"] or 0), r["tn"])
            if r["aid"] not in best or key < best[r["aid"]]:
                best[r["aid"]] = key
                out[r["aid"]] = r["tn"]
    return out


def _fb_statements_for_rating(db, aid, jg, cycle_id):
    """The behaviours to LIST for one 360 rating: a SUBMITTED rating shows the statements its answers hold
    (_fb_assignment_tier), a PENDING one its subject's live tier (the 360 tier guard's rule), and so does a submitted
    one that holds no rows. Scores are not touched. The one reader the locked rate view, the admin view and the chat
    card share."""
    st = db.execute("SELECT status FROM assignments WHERE id=?", (aid,)).fetchone()
    if st is not None and st["status"] == "submitted":
        tn = _fb_assignment_tier(db, aid)
        if tn is not None:
            return statements_for_tier(db, tn, cycle_id)
    return statements_for_grade(db, jg, cycle_id)


def max_score_for_grade(db, jg, cycle_id):
    """The most a subject at job grade `jg` can score in the cycle: every behaviour of their tier Demonstrate, at the
    cycle's own points (points_for): the current-level behaviours at dc, the next-level ones at dn."""
    tn = _cycle_tier_n(db, jg, cycle_id)
    n_cur, n_fut = tier_statement_counts(db, cycle_id, tn)
    return float(points_max(points_for(db, cycle_id, "360"), n_cur, n_fut))


def ensure_responses(db, assignment_id, subject, cycle_id):
    """Lazily create a response row per behaviour at the subject's tier. THE only write path that creates rows.

    A PENDING rating is first moved onto the subject's CURRENT tier (2026-11-08, ticket OH-H-0083): rows for another
    tier's behaviours are deleted, so a colleague whose job grade moved to another tier after the rater opened the card
    does not leave the rating holding two tiers (the Submit gate counted both). A SUBMITTED rating that already has rows
    is never touched: its rows, score and result stay as they were (Chris, 2026-11-08)."""
    st = db.execute("SELECT status FROM assignments WHERE id=?", (assignment_id,)).fetchone()
    if st is not None and st["status"] == "submitted":
        if db.execute("SELECT 1 FROM responses WHERE assignment_id=? LIMIT 1", (assignment_id,)).fetchone():
            return
    else:
        _fb_prune_assignment(db, assignment_id, subject["job_grade"], cycle_id)
    for s in statements_for_grade(db, subject["job_grade"], cycle_id):
        db.execute(
            "INSERT OR IGNORE INTO responses(assignment_id, statement_id) VALUES (?,?)",
            (assignment_id, s["statement_id"]),
        )
    db.commit()


_FB_CHUNK = 500


def _fb_prune_assignment(db, assignment_id, jg, cycle_id):
    """Delete a PENDING rating's rows whose behaviour is not in the subject's current tier (answered or blank: an
    answer to another tier's behaviour does not carry over). Never touches a submitted rating. Does not commit.
    Returns the number of rows deleted."""
    tn = _cycle_tier_n(db, jg, cycle_id)
    return db.execute(
        "DELETE FROM responses WHERE assignment_id=? AND statement_id NOT IN "
        "(SELECT id FROM cycle_statements WHERE cycle_id=? AND tier_n=?) "
        "AND EXISTS (SELECT 1 FROM assignments WHERE id=? AND status='pending')",
        (assignment_id, cycle_id, tn, assignment_id)).rowcount


def _fb_retier_pending(db, subject_id=None, cycle_id=None):
    """Move every PENDING, non-archived 360 rating that has been opened onto its subject's CURRENT tier (Chris, 2026-11-08:
    "if a person already answered the 360 before admin changes the JG, leave the result as is, but the 360 should move to
    the right tier after admin changes, so the next person answering will not hit the bug"; ticket OH-H-0083).

    For each such assignment in `cycle_id` (default: the active cycle): the responses whose behaviour is not in the
    subject's current tier set under that cycle's tier bands are deleted, and the current tier's rows are created (INSERT OR
    IGNORE, only where the assignment already has rows: a rating nobody opened stays lazily empty, as ensure_responses
    leaves it). `subject_id` is one user id, an iterable of ids (the roster import), or None for the whole cycle (a tier
    band edit: every subject's tier can move). A SUBMITTED rating is never touched.

    A batched write: the assignments are read in one query per 500 subjects, then one DELETE and one INSERT..SELECT per
    tier per 500 assignments, never a query per person. It does NOT commit: the caller's transaction owns that (the
    admin person page, the roster import and the rules writers commit after calling it). Returns
    {"assignments": n, "removed": n, "created": n}."""
    out = {"assignments": 0, "removed": 0, "created": 0}
    if cycle_id is None:
        cycle_id = active_cycle_id(db)
    if not cycle_id:
        return out
    crow = db.execute("SELECT * FROM cycles WHERE id=?", (cycle_id,)).fetchone()
    if not crow:
        return out
    tiers = effective_tiers(crow)
    if subject_id is None:
        scopes = [("", [])]
    else:
        ids = [int(subject_id)] if isinstance(subject_id, (int, str)) else [int(x) for x in subject_id]
        ids = list(dict.fromkeys(ids))
        scopes = [(" AND a.subject_id IN (%s)" % ",".join("?" * len(ids[k:k + _FB_CHUNK])), ids[k:k + _FB_CHUNK])
                  for k in range(0, len(ids), _FB_CHUNK)]
    by_tier, tn_of = {}, {}
    for clause, params in scopes:
        for r in db.execute(
                "SELECT a.id AS aid, u.job_grade AS jg FROM assignments a JOIN users u ON u.id=a.subject_id "
                "WHERE a.cycle_id=? AND a.status='pending' AND a.archived=0 "
                "AND EXISTS (SELECT 1 FROM responses r WHERE r.assignment_id=a.id)" + clause,
                [cycle_id] + params).fetchall():
            if r["jg"] not in tn_of:
                tn_of[r["jg"]] = tier_for_grade(r["jg"], tiers)["n"]
            by_tier.setdefault(tn_of[r["jg"]], []).append(r["aid"])
    for tn, aids in by_tier.items():
        for k in range(0, len(aids), _FB_CHUNK):
            part = aids[k:k + _FB_CHUNK]
            ph = ",".join("?" * len(part))
            out["removed"] += db.execute(
                "DELETE FROM responses WHERE assignment_id IN (%s) AND statement_id NOT IN "
                "(SELECT id FROM cycle_statements WHERE cycle_id=? AND tier_n=?)" % ph,
                part + [cycle_id, tn]).rowcount
            out["created"] += db.execute(
                "INSERT OR IGNORE INTO responses(assignment_id, statement_id) "
                "SELECT a.id, cs.id FROM assignments a JOIN cycle_statements cs ON cs.cycle_id=? AND cs.tier_n=? "
                "WHERE a.id IN (%s)" % ph, [cycle_id, tn] + part).rowcount
            out["assignments"] += len(part)
    return out


def _fb_tier_moved(db, old_jg, new_jg, cycle_id=None):
    """True when a job grade change puts the person in a different 360 tier under the cycle's tier bands (a same-tier
    move, e.g. 12 -> 13, leaves the rating's rows as they are)."""
    if cycle_id is None:
        cycle_id = active_cycle_id(db)
    if not cycle_id:
        return False
    return _cycle_tier_n(db, old_jg, cycle_id) != _cycle_tier_n(db, new_jg, cycle_id)


def _fb_live_tiers(db, aids):
    """{assignment_id: tier_n} for the given 360 ratings: the subject's CURRENT tier for a PENDING rating, None for a
    SUBMITTED one (its readers keep every row it holds, as submitted: Chris, 2026-11-08). ONE batched read per 500
    assignments (GETs write nothing, so a reader must be right before the next write moves a rating's tier)."""
    out, crow_tiers = {}, {}
    ids = list(dict.fromkeys(int(x) for x in aids if x is not None))
    for k in range(0, len(ids), _FB_CHUNK):
        part = ids[k:k + _FB_CHUNK]
        for r in db.execute(
                "SELECT a.id AS aid, a.status AS status, a.cycle_id AS cid, u.job_grade AS jg FROM assignments a "
                "JOIN users u ON u.id=a.subject_id WHERE a.id IN (%s)" % ",".join("?" * len(part)), part).fetchall():
            if r["status"] == "submitted":
                out[r["aid"]] = None
                continue
            if r["cid"] not in crow_tiers:
                crow_tiers[r["cid"]] = effective_tiers(
                    db.execute("SELECT * FROM cycles WHERE id=?", (r["cid"],)).fetchone())
            out[r["aid"]] = tier_for_grade(r["jg"], crow_tiers[r["cid"]])["n"]
    return out


def _fb_row_counts(db, aids):
    """{assignment_id: {"t": rows, "d": answered, "y": yes, "n": no}} over the rows that COUNT for each rating: a PENDING
    rating's rows of its subject's current tier only (an off-tier row left by a grade move is not a behaviour on the card),
    a SUBMITTED rating's every row. The one reader the 360 progress, the Submit gate and the tallies share."""
    tn = _fb_live_tiers(db, aids)
    out = {a: {"t": 0, "d": 0, "y": 0, "n": 0} for a in tn}
    ids = list(tn)
    for k in range(0, len(ids), _FB_CHUNK):
        part = ids[k:k + _FB_CHUNK]
        for r in db.execute(
                "SELECT r.assignment_id AS aid, cs.tier_n AS tn, COUNT(*) AS t, "
                "SUM(CASE WHEN r.answer IS NOT NULL THEN 1 ELSE 0 END) AS d, "
                "SUM(CASE WHEN r.answer='yes' THEN 1 ELSE 0 END) AS y, "
                "SUM(CASE WHEN r.answer='no' THEN 1 ELSE 0 END) AS n "
                "FROM responses r JOIN cycle_statements cs ON cs.id=r.statement_id "
                "WHERE r.assignment_id IN (%s) GROUP BY r.assignment_id, cs.tier_n" % ",".join("?" * len(part)),
                part).fetchall():
            want = tn.get(r["aid"])
            if want is None or r["tn"] == want:
                c = out[r["aid"]]
                c["t"] += r["t"] or 0
                c["d"] += r["d"] or 0
                c["y"] += r["y"] or 0
                c["n"] += r["n"] or 0
    return out


_FB_AUTO = object()


def assignment_score(db, assignment_id, tier=_FB_AUTO):
    """(score, max, answered) for a single assessor's responses. A PENDING rating counts only its subject's current tier
    (2026-11-08: an off-tier row left by a grade move must not skew it); a submitted one counts every row it holds.
    `tier`: left out, looked up for the assignment; None, every row (a caller that knows the rating is submitted);
    an int, that tier's rows (a caller that already worked out the subject's tier)."""
    if tier is _FB_AUTO:
        tier = _fb_live_tiers(db, [assignment_id]).get(assignment_id)
    # the cycle comes from the SAME query (no extra read per call): the rating's own cycle, never the page's
    rows = db.execute(
        """SELECT s.is_future, r.answer, a.cycle_id AS cid
           FROM responses r JOIN cycle_statements s ON s.id = r.statement_id
           JOIN assignments a ON a.id = r.assignment_id
           WHERE r.assignment_id = ?""" + (" AND s.tier_n = ?" if tier is not None else ""),
        (assignment_id,) + ((tier,) if tier is not None else ()),
    ).fetchall()
    score = max_s = 0.0
    answered = 0
    pts = points_for(db, rows[0]["cid"], "360") if rows else None
    for r in rows:
        w = pts.dn if r["is_future"] else pts.dc
        max_s += w
        if r["answer"] is None:
            continue
        answered += 1
        score += points_earned(pts, r["is_future"], r["answer"])   # Demonstrate dc / dn, Developing vc / vn
    return score, max_s, answered


def subject_result(db, subject, cycle_id=None):
    """Aggregate a subject's panel for one cycle.

    Returns a dict with the per-assessor breakdown plus the averaged score
    and band over assessors who have SUBMITTED. `cycle_id` defaults to the
    active cycle.
    """
    if cycle_id is None:
        cycle_id = active_cycle_id(db)
    assigns = db.execute(
        """SELECT a.*, u.full_name AS assessor_name, u.employee_id AS assessor_eid,
                  u.job_title AS assessor_title
           FROM assignments a JOIN users u ON u.id = a.assessor_id
           WHERE a.subject_id = ? AND a.cycle_id = ? AND a.archived = 0
           ORDER BY CASE a.relationship
                      WHEN 'line_manager' THEN 0 WHEN 'matrix_manager' THEN 1
                      WHEN 'peer' THEN 2 ELSE 3 END,
                    u.full_name""",
        (subject["id"], cycle_id),
    ).fetchall()

    max_s = max_score_for_grade(db, subject["job_grade"], cycle_id)
    rows = []
    submitted_scores = []
    _tn = _cycle_tier_n(db, subject["job_grade"], cycle_id)   # a pending rating counts only this tier's rows
    for a in assigns:
        score, _m, answered = assignment_score(db, a["id"], tier=(None if a["status"] == "submitted" else _tn))
        is_sub = (a["status"] == "submitted")
        if is_sub:
            submitted_scores.append((a["assessor_id"], score))
        rows.append({
            "assignment_id": a["id"],
            "assessor_id": a["assessor_id"],
            "assessor_name": a["assessor_name"],
            "assessor_eid": a["assessor_eid"],
            "assessor_title": a["assessor_title"],
            "relationship": a["relationship"],
            "status": a["status"],
            "submitted_at": a["submitted_at"],
            # reset_at is set when an admin reset a submission -> the assessor
            # needs to resubmit. Used to show "Pending · resubmit" vs plain pending.
            "reset_at": a["reset_at"],
            "score": score if is_sub else None,
            "answered": answered,
        })

    avg_raw, avg, adjustment, band, combo = _score_band_adjusted(
        db, subject, cycle_id, submitted_scores)
    mvs = min_valid_submissions(subject["job_grade"])
    return {
        "panel_size": len(assigns),
        "submitted": len(submitted_scores),
        "max_score": max_s,
        # avg_score/band are the FINAL values (post extreme-assessor
        # correction, if enabled) -- every existing template/caller keeps
        # working unchanged. avg_score_raw/adjustment are additive audit keys
        # for admin-facing surfaces (CSV export, subject detail).
        "avg_score": avg,
        # band is the COMBINED band (360 + approved technical, weighted by job
        # grade); avg_score above stays the 360 average alone, which is what
        # every existing caller has always read. `combined` carries the
        # breakdown -- source is 'combined' or '360_only' -- for the admin
        # audit surfaces that need to show how a band was arrived at.
        "band": band,
        "combined": combo,
        "avg_score_raw": avg_raw,
        "adjustment": adjustment,
        "assessors": rows,
        # Soft display gate: the score/band are only shown in the UI once
        # `min_valid` assessors have submitted. avg_score/band above are still
        # computed (and exported) regardless.
        "min_valid": mvs,
        "score_valid": len(submitted_scores) >= mvs,
        # Per-subject target: 1 for letter-grade subjects (only their LM),
        # PANEL_TARGET for everyone else. Templates use this so JG-H rows
        # don't get mis-flagged with "(target 5)" when 1/1 is already full.
        "target_panel_size": _target_panel_size(subject["job_grade"]),
    }


def subject_band(db, subject, cycle_id):
    """Potential band only — no avg_score, no assessor rows. Reuses the same
    scoring semantics as subject_result() (including the extreme-assessor
    correction, via the same shared _score_band_adjusted() helper so the two
    functions can't drift apart), but the return value has no key that could
    leak a raw score if a template printed it by mistake. The correction is
    unconditional whenever enabled -- confirmed to apply everywhere a band is
    shown, including the subject's own report, not just admin views."""
    assessor_scores = _subject_assessor_scores(db, subject["id"], cycle_id)
    _avg_raw, _avg, _adjustment, band, combo = _score_band_adjusted(
        db, subject, cycle_id, assessor_scores)
    mvs = min_valid_submissions(subject["job_grade"])
    return {
        "band": band,
        "min_valid": mvs,
        "score_valid": len(assessor_scores) >= mvs,
        # Which halves fed the band ('combined' / '360_only'). Deliberately no
        # score of any kind -- this function's whole point is that nothing it
        # returns could leak a raw score if a template printed it by mistake.
        "band_source": combo["source"],
        # The same band computed from the employee's OWN technical answers
        # rather than the line manager's moderated ones -- the Self slot in the
        # calibration chain, against which the LM slot shows what the manager
        # approved. Equal to `band` whenever there's no approved technical half.
        "self_band": potential_band(combo["self_band_score"], thresholds_for_cycle(db, cycle_id)),
    }


def calibration_group_of(db, subject_id):
    """This person's cross-org calibration group id, or None. The whole
    membership table is read ONCE per request and cached on `g` (same
    idiom as org_display_map()/active_cycle()), because both
    effective_band() and pm_effective_band() call this per subject inside
    loops that run over an entire BG -- up to ~1,000 people on the largest
    one, which a per-subject query would turn into ~1,000 queries per page.
    The table is small (one row per grouped person, and only exception
    cases are grouped), so reading it whole is cheaper than any of them."""
    m = getattr(g, "_calib_group_map", None)
    if m is None:
        m = {r["subject_id"]: r["group_id"] for r in db.execute(
            "SELECT subject_id, group_id FROM pm_calibration_group_members")}
        g._calib_group_map = m
    return m.get(subject_id)


def effective_band(db, subject, cycle_id, skip_tiers=()):
    """Like subject_band(), but resolves through any LOCKED calibration
    adjustment first: a cross-org group wins over BG, which wins over
    company, which wins over HOD, which wins over raw. Falls through to a
    lower tier when a session is locked but has no adjustment row for this
    specific subject -- a tier lock doesn't imply every subject in it was
    individually touched. Adds a "source" key ("group"|"bgceo"|"buceo"|
    "hod"|"raw") so a caller can show provenance.

    Precedence deliberately mirrors pm_effective_band()'s, so one person's
    two axes can never disagree about WHICH scope decided them -- a group
    outranks the line on both, for the same reason (someone calibrated by
    the CTO's IT-shared-services group is calibrated there, not by whichever
    BG they happen to sit in). 'super' has no slot here yet: nothing writes
    a super-tier potential adjustment, so looking for one would be a query
    per subject for no result -- it is CHECK-ready in the schema only.

    This is the one function every future consumer of "this person's
    current band" should call instead of subject_band() directly -- the
    calibration module's own UI is the only caller for now (see
    [[project_leadership360_app]] decision: Team/HOD/My Feedback stay on
    raw subject_band() until wiring calibrated bands into general
    employee-facing views is its own explicit, separate decision)."""
    if not cycle_has_potential(db, cycle_id):
        # a cycle with no potential result: no tier's band counts either (subject_band's is None already)
        base = subject_band(db, subject, cycle_id)
        return {**base, "source": "raw", "raw_band": base["band"]}
    bg = subject["business_group"]
    company = subject["company"]
    hod_id = subject["hod_id"]
    if cycle_is_mid_year(db, cycle_id):   # Mid-Year stops at the HOD (2026-10-12)
        skip_tiers = tuple(skip_tiers) + _MY_SKIP_TIERS
    gid = calibration_group_of(db, subject["id"])
    for tier, key in (("super", POT_SUPER_SCOPE_KEY),   # the super admin's final band: never locked, always wins (row 7)
                      (CHAIR_TIER, CHAIR_TIER),   # the Executive Chairman's locked Talent Box (P4, 2026-10-29)
                      ("group", str(gid) if gid else None),
                      ("bgceo", bg), ("buceo", bu_scope_key(db, subject)),
                      ("hod", str(hod_id) if hod_id else None)):
        if tier == CHAIR_TIER:
            cb = _chair_locked_band(db, cycle_id, "pot", subject["id"], skip_tiers)
            if cb:
                base = subject_band(db, subject, cycle_id)
                return {**base, "band": cb, "source": CHAIR_SOURCE, "raw_band": base["band"]}
            continue
        if not key or tier in skip_tiers:
            continue
        # a scope whose two calls BLEND only suggests a band -- the super admin decides it (pm_effective_band's rule)
        if tier == "group" and _calib_group_mode_of(gid)["mode"] == "blend":
            continue
        # the BG CEO's tier: the business group locked, or this person's business unit (2026-10-07); the group's: the
        # whole group locked, or this person (pot_group_locks, row 7); the super tier is never locked
        bu = ("OR (cs.tier='bgceo' AND EXISTS (SELECT 1 FROM talent_box_bu_locks l WHERE l.cycle_id=cs.cycle_id "
              "AND l.business_group=cs.scope_key AND l.company=?))") if tier == "bgceo" else (
             "OR EXISTS (SELECT 1 FROM pot_group_locks gl WHERE gl.cycle_id=cs.cycle_id AND gl.group_id=? AND "
             "gl.subject_id=ca.subject_id)") if tier == "group" else ("OR 1" if tier == "super" else "")
        barg = [company or ""] if tier == "bgceo" else ([gid] if tier == "group" else [])
        if tier == "buceo" and bu_shared(db, subject):   # several calibrators, their bands weighted (2026-10-26)
            sh = bu_panel_call(db, "pot", cycle_id, subject)
            if sh:
                base = subject_band(db, subject, cycle_id)
                return {**base, "band": sh[0], "source": "buceo", "raw_band": base["band"]}
            continue
        memo = _req_cache().get("_band_memo") if has_request_context() else None
        if memo is not None:   # a read-only page that opted in: this scope's locked bands, read once for every person
            mk = (cycle_id, tier, key) + tuple(barg)
            if mk not in memo:
                memo[mk] = {}
                for r_ in db.execute(
                        "SELECT ca.subject_id, ca.adjusted_band FROM calibration_adjustments ca "
                        "JOIN calibration_sessions cs ON cs.id=ca.session_id "
                        "WHERE cs.cycle_id=? AND cs.tier=? AND cs.scope_key=? "
                        "AND (cs.locked_at IS NOT NULL " + bu + ")", [cycle_id, tier, key] + barg):
                    memo[mk].setdefault(r_[0], {"adjusted_band": r_[1]})
            row = memo[mk].get(subject["id"])
        else:
            row = db.execute(
                "SELECT ca.adjusted_band FROM calibration_adjustments ca "
                "JOIN calibration_sessions cs ON cs.id=ca.session_id "
                "WHERE cs.cycle_id=? AND cs.tier=? AND cs.scope_key=? "
                "AND (cs.locked_at IS NOT NULL " + bu + ") AND ca.subject_id=?",
                [cycle_id, tier, key] + barg + [subject["id"]]).fetchone()
        if row:
            base = subject_band(db, subject, cycle_id)
            # raw_band: the band as it came in, before any tier -- the Talent Box's band trail reads it (2026-10-07)
            return {**base, "band": row["adjusted_band"], "source": tier, "raw_band": base["band"]}
    base = subject_band(db, subject, cycle_id)
    return {**base, "source": "raw", "raw_band": base["band"]}


def band_distribution(db, subjects, cycle_id, band_fn=subject_band):
    """{"Low":n,"Mid":n,"High":n} over `subjects` (an iterable of user
    rows), counting only where score_valid is True -- the same display
    gate admin_dashboard() already uses for its own band counts.
    `band_fn` is swappable: pass subject_band (raw) for a tier with
    nothing to roll up yet (HOD), or effective_band for a tier that reads
    locked adjustments from the tier below (BUCEO/BGCEO). Callers inside
    a calibration view should prefer band_distribution_from_rows() instead
    -- this raw version can't see the CURRENT session's own not-yet-locked
    adjustments, so it stays frozen at the pre-adjustment snapshot instead
    of moving live as the person calibrating works."""
    bands = {"Low": 0, "Mid": 0, "High": 0}
    for s in subjects:
        info = band_fn(db, s, cycle_id)
        if info["score_valid"] and info["band"]:
            bands[info["band"]] += 1
    return bands


def _largest_remainder_pct(counts, keys):
    """Integer percentages for `keys` (in order) over `counts` that ALWAYS sum
    to exactly 100 (largest-remainder / Hamilton apportionment) -- naively
    flooring each share independently can under-count the total by 1-2 points
    when a row has few enough people that rounding bites, which would look
    like a bug on a bar meant to visually fill edge-to-edge."""
    total = sum(counts[k] for k in keys)
    if not total:
        return {k: 0 for k in keys}
    shares = {k: 100 * counts[k] / total for k in keys}
    pct = {k: int(shares[k]) for k in keys}
    remainder = 100 - sum(pct.values())
    for k in sorted(keys, key=lambda k: shares[k] - pct[k], reverse=True)[:remainder]:
        pct[k] += 1
    return pct


def band_distribution_rollup(db, subjects, cycle_id, group_key_fn):
    """Group `subjects` by `group_key_fn(user_row)` (e.g. company/department/
    tier name), then band_distribution() each group -- the BU/department/
    job-grade-tier cuts on the reporting dashboard. Reuses band_distribution()
    per group (default band_fn=subject_band) rather than a new counting loop,
    so every cut automatically reflects the extreme-assessor correction.
    Drops empty groups (nobody with a valid score) so callers don't have to
    filter zero-total rows themselves."""
    groups = {}
    for s in subjects:
        groups.setdefault(group_key_fn(s) or "(none)", []).append(s)
    out = {}
    for key, members in groups.items():
        bands = band_distribution(db, members, cycle_id)
        total = sum(bands.values())
        if total:
            out[key] = {**bands, "total": total}
    return out


def band_distribution_from_rows(rows):
    """Same shape as band_distribution(), but derived from already-built
    _calibration_rows() output -- each row's `current_band` already
    reflects THIS session's own adjustments regardless of lock status, so
    the distribution chart moves live as the person calibrating adjusts
    people, instead of staying frozen at the pre-adjustment read.
    Counts a row when it has a statistically valid score OR a manual
    adjustment (someone with no score at all that a tier assigned a band
    to) -- but NOT a row with a real, if immature, score below the
    min-valid-raters threshold that was never touched; that exclusion is
    intentional and stays as-is."""
    bands = {"Low": 0, "Mid": 0, "High": 0}
    for r in rows:
        # A band INHERITED from a locked tier below is a real decision and must
        # count. `adjusted` only means "this session touched them", and
        # score_valid only means "the raw 360 score is mature" -- neither is
        # true of someone the HOD banded and locked, so on the BUCEO/BGCEO
        # pages they silently dropped out of the bar. On one real BG that left
        # a distribution over 31 people captioned as 1018, with gap advice
        # (Low +1 / Mid +9 / High -9) that should have read +11 / +6 / -16.
        # effective_band() has always returned `source` for exactly this;
        # nothing read it. subject_band() (the HOD view's band_fn) has no
        # source key, so .get() leaves that tier's behaviour untouched --
        # an HOD is the first decision, with nothing below to inherit from.
        inherited = (r["band_info"].get("source") or "raw") != "raw"
        if (r["band_info"]["score_valid"] or r["adjusted"] or inherited) and r["current_band"]:
            bands[r["current_band"]] += 1
    return bands


def calibration_target_gaps(distribution, target):
    """Per band, how many people would need to move to exactly hit the
    target percentage at the current population size -- positive = short
    of target (move more people in), negative = over target. Gives the
    person calibrating a concrete headcount, not just a percentage, to
    work against ("15/70/15" alone doesn't say how many people that is)."""
    total = sum(distribution.values())
    gaps = {}
    for band in ("Low", "Mid", "High"):
        target_n = round(target[band] / 100 * total) if total else 0
        gaps[band] = target_n - distribution[band]
    return gaps


def calibration_dept_breakdown(rows, target):
    """Per-department Low/Mid/High spread for the roll-up (BUCEO/BGCEO) views,
    so the person calibrating can see WHICH department pulls the group off the
    target distribution. Grouped by each row's roster department label, band-
    valid rows only, using the current (effective/adjusted) band. Flags a
    department 'High-heavy'/'Low-heavy' when that band runs >=10 points over its
    target share (grade inflation/deflation), else 'On track'. Sorted worst-
    off-target first so the departments needing attention surface at the top."""
    groups, order = {}, []
    for r in rows:
        if not (r["band_info"]["score_valid"] and r["current_band"]):
            continue
        dept = (r["user"]["department"] or "").strip() or "—"
        g = groups.get(dept)
        if g is None:
            g = groups[dept] = {"dept": dept, "Low": 0, "Mid": 0, "High": 0}
            order.append(dept)
        g[r["current_band"]] += 1
    out = []
    for dept in order:
        g = groups[dept]
        total = g["Low"] + g["Mid"] + g["High"]
        pct = {b: (g[b] / total * 100 if total else 0) for b in ("Low", "Mid", "High")}
        high_over, low_over = pct["High"] - target["High"], pct["Low"] - target["Low"]
        if high_over >= 10 and high_over >= low_over:
            skew, skew_over = "High-heavy", True
        elif low_over >= 10:
            skew, skew_over = "Low-heavy", True
        else:
            skew, skew_over = "On track", False
        g.update(total=total, pct=pct, skew=skew, skew_over=skew_over,
                 worst=max(high_over, low_over))
        out.append(g)
    out.sort(key=lambda d: (-d["worst"], -d["total"], d["dept"]))
    return out


def attach_hod_provenance(db, rows, cid, population):
    """For the roll-up (BUCEO) view: annotate each row with the HOD-tier decision
    that fed into it -- the HOD-calibrated band, whether the HOD moved it off the
    raw 360 band, and the HOD's written justification. Reads the locked HOD
    sessions directly. A row whose effective band still comes from raw 360
    (band_info source != 'hod') carries no HOD note -- it was never individually
    touched at the department tier."""
    hod_ids = {p["hod_id"] for p in population if p["hod_id"]}
    sess = {}
    for hid in hod_ids:
        s = db.execute("SELECT id FROM calibration_sessions WHERE cycle_id=? AND tier='hod' "
                       "AND scope_key=?", (cid, str(hid))).fetchone()
        if s:
            sess[hid] = s["id"]
    adj = {}
    if sess:
        ph = ",".join("?" * len(sess))
        for a in db.execute("SELECT subject_id, original_band, adjusted_band, justification "
                            f"FROM calibration_adjustments WHERE session_id IN ({ph})",
                            list(sess.values())):
            adj[a["subject_id"]] = a
    for r in rows:
        info = r["band_info"]
        a = adj.get(r["user"]["id"]) if info.get("source") == "hod" else None
        r["hod_band"] = info["band"]
        r["hod_from_band"] = a["original_band"] if a else None
        r["hod_moved"] = bool(a) and a["adjusted_band"] != a["original_band"]
        r["hod_justification"] = (a["justification"] or "") if a else ""


def _locked_tier_adjustments(db, cid, tier, keys):
    """{subject_id: adjustment_row} across every LOCKED session of `tier` whose
    scope_key is in `keys` (hod: str(hod_id); buceo: company name). One batched
    read per tier -- the provenance helpers below all share this shape."""
    sess = []
    for k in keys:
        s = db.execute("SELECT id FROM calibration_sessions WHERE cycle_id=? AND tier=? "
                       "AND scope_key=? AND locked_at IS NOT NULL", (cid, tier, k)).fetchone()
        if s:
            sess.append(s["id"])
    adj = {}
    if sess:
        ph = ",".join("?" * len(sess))
        for a in db.execute("SELECT subject_id, adjusted_band, justification, original_band, seen_band "
                            f"FROM calibration_adjustments WHERE session_id IN ({ph})", sess):
            adj[a["subject_id"]] = a
    return adj


def attach_tier_chain(db, rows, cid, population, own_tier):
    """Build the Self -> ... -> {own_tier} provenance slots shared by all three
    calibration views. own_tier is 'hod' | 'buceo' | 'bgceo'. Each row gets
    `tier_slots`: an ordered list of {tier, band, own, changed} over Self plus
    every tier up to and including own_tier. `changed` False means that tier
    agreed with the band coming in (the template renders a dash in that fixed
    slot); the own tier is the editable / ring-highlighted one. `chain_incoming`
    is the effective band entering the own tier -- the on-adjust JS compares the
    live dropdown against it to toggle the own slot between pill and dash.
    `prev_note` carries the immediately-lower tier's justification for the note
    popover (the own tier's note is the row's current justification)."""
    tiers = {"hod": ["hod"], "buceo": ["hod", "buceo"],
             "bgceo": ["hod", "buceo", "bgceo"]}[own_tier]
    lower = [t for t in tiers if t != own_tier]
    hod_adj = (_locked_tier_adjustments(db, cid, "hod",
               {str(p["hod_id"]) for p in population if p["hod_id"]}) if "hod" in lower else {})
    buceo_adj = (_locked_tier_adjustments(db, cid, "buceo",
                 {bu_scope_key(db, p) for p in population if p["company"]}) if "buceo" in lower else {})
    if "buceo" in lower:   # several calibrators: their weighted band is the BU level's (2026-10-26)
        for p_ in population:
            if bu_shared(db, p_):
                sh = bu_panel_call(db, "pot", cid, p_)
                buceo_adj[p_["id"]] = {"adjusted_band": sh[0], "justification": sh[1], "original_band": None,
                                       "seen_band": None} if sh else None
    LABEL = {"hod": "HOD", "buceo": "BUCEO", "bgceo": "BGCEO"}
    for r in rows:
        sid = r["user"]["id"]
        info = subject_band(db, r["user"], cid)
        # Self is the band from the employee's OWN technical answers; LM is the
        # one their line manager moderated and approved, which is what the
        # calibration cascade actually starts from. With no approved technical
        # half the two are equal and the LM slot renders a dash, same as any
        # tier that agreed with what came in.
        lm_band = info["band"]
        self_band = info["self_band"]
        ha, ba = hod_adj.get(sid), buceo_adj.get(sid)
        r["self_band"] = self_band
        r["lm_band"] = lm_band
        r["hod_note"] = (ha["justification"] or "") if ha else ""
        r["hod_band"] = ha["adjusted_band"] if ha else None   # the HOD's own band, kept or moved (None = no row of theirs)
        r["hod_late"] = (lm_band if ha and lm_band and lm_band != _calib_seen(ha) and lm_band != ha["adjusted_band"]
                         else None)   # the LM's band came in after the HOD set theirs, and disagrees (2026-10-02)
        r["buceo_note"] = (ba["justification"] or "") if ba else ""
        decided = {
            "hod": (r["current_band"] if own_tier == "hod" else (ha["adjusted_band"] if ha else None)),
            "buceo": (r["current_band"] if own_tier == "buceo" else (ba["adjusted_band"] if ba else None)),
            "bgceo": (r["current_band"] if own_tier == "bgceo" else None),
        }
        slots = [
            {"tier": "Self", "band": self_band, "own": False, "changed": True},
            {"tier": "LM", "band": lm_band, "own": False,
             "changed": lm_band != self_band},
        ]
        # The cascade starts at the LM-approved band, NOT the self band -- this
        # is unchanged behaviour, since subject_band() has always returned the
        # approved one; the Self slot is what's newly distinct from it.
        eff, incoming = lm_band, lm_band
        for t in tiers:
            d = decided[t]
            changed = bool(d) and d != eff
            is_own = (t == own_tier)
            if is_own:
                incoming = eff
            slots.append({"tier": LABEL[t], "band": (d if changed else eff),
                          "own": is_own, "changed": changed,
                          "from": eff})   # what came in to this tier: a move says from which band (2026-10-07)
            if changed:
                eff = d
        r["tier_slots"] = slots
        r["chain_incoming"] = incoming
        r["prev_note"] = (r["buceo_note"] if own_tier == "bgceo"
                          else r["hod_note"] if own_tier == "buceo" else "")
        # EVERY lower tier that moved this person, not just the one immediately
        # below. prev_note carries a single note, so a BG CEO read the BU CEO's
        # reasoning and never the HOD's -- the justification that started the
        # cascade stopped one step short of the person defending the rating.
        # Free: hod_adj/buceo_adj are already fetched above, and both are
        # already restricted to the tiers BELOW own_tier.
        r["note_trail"] = [t for t in (
            ({"tier": "hod", "label": "HOD", "band": ha["adjusted_band"],
              "note": r["hod_note"]} if ha else None),
            ({"tier": "buceo", "label": "BU CEO", "band": ba["adjusted_band"],
              "note": r["buceo_note"]} if ba else None),
        ) if t]


def subject_report_context(db, subject, cycle_id):
    """Everything needed to render one person's anonymized feedback: band +
    statement agreement + comments. Strips assessor identity out of the
    comments even though templates never print it today — a later template
    edit shouldn't be able to leak it by accident."""
    agreement, n_submitted = statement_agreement(db, subject, cycle_id)
    for crit in agreement:
        crit["comments"] = [{"comment": c["comment"]} for c in crit["comments"]]
    return {
        "agreement": agreement,
        "n_submitted": n_submitted,
        "band_info": subject_band(db, subject, cycle_id),
    }


# ---------------------------------------------------------------------------
# Technical competency -- helpers
# ---------------------------------------------------------------------------
# The functional counterpart to the leadership assessment above. Deliberately
# has its own points per answer (points_for(.., 'tc'), independent of the 360's), so a technical score and a leadership
# score are each read as a share of their own maximum and combined into one potential band (_potential_blend) whatever
# the points are.

TC_ANSWER_DEMONSTRATE = "yes"
TC_ANSWER_DEVELOPING = "no"


def tc_assignments_for(db, cycle_id, subject_id):
    """One person's assessed competencies for a cycle, with the skill detail
    the page needs, ordered so the template can group adjacent rows under a
    Skill Category heading. Current-level items sort before future-level ones
    inside a category, because that is the order the employee reasons in
    ("what I do now" then "what I am growing into")."""
    return db.execute(
        "SELECT a.id AS assignment_id, a.is_future, a.seq, a.source, a.added_open, "
        "       s.id AS skill_id, s.skill_code, s.title, s.level, s.skill_type, "
        "       s.skill_category, s.proficiency_description, s.ability_items, "
        "       s.knowledge_items "
        "FROM tc_assignments a JOIN tc_skills s ON s.id = a.skill_id "
        "WHERE a.cycle_id=? AND a.subject_id=? "
        "ORDER BY COALESCE(NULLIF(s.skill_category,''), '~'), a.is_future, a.seq, s.title",
        (cycle_id, subject_id)).fetchall()


def tc_get_or_create_assessment(db, cycle_id, subject_id):
    """The person's assessment row for this cycle, created on first look.

    Created lazily rather than seeded for the whole roster: only people who
    actually have competencies assigned ever get a row, so the table stays a
    record of real participation instead of a copy of the roster."""
    row = db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                     (cycle_id, subject_id)).fetchone()
    if row:
        return row
    db.execute("INSERT INTO tc_assessments(cycle_id, subject_id) VALUES (?,?)",
               (cycle_id, subject_id))
    db.commit()
    return db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                      (cycle_id, subject_id)).fetchone()


def tc_can_self_edit(assessment):
    """The employee may answer while their assessment is still pending. Once
    submitted it is the line manager's to moderate -- same one-way gate the KPI
    result entry uses, and the prototype's UAT explicitly warned users about."""
    return assessment is None or assessment["status"] == "pending"


# --- A competency Group People adds AFTER the person submitted their self-assessment (2026-11-06): only that competency opens
# for them. tc_assignments.added_open is 1 from the add until they answer it and submit it (_tc_submit_added); the assessment's
# status, its submitted_at, their overall remark, every other answer and their manager's review stay exactly as they were.
# Their line manager cannot approve while one is open (_tc_approve_assessment). A Reopen of the self-assessment clears it (the
# whole part is open then).
def tc_added_open(db, subject_id, cid):
    """The competency rows (tc_assignments rows) added after the person submitted that are still open for them: []
    unless their self-assessment is submitted (a pending one is open as a whole; a reviewed one is final)."""
    if not cid:
        return []
    return db.execute(
        "SELECT a.* FROM tc_assignments a JOIN tc_assessments ta ON ta.cycle_id=a.cycle_id AND ta.subject_id=a.subject_id "
        "WHERE a.cycle_id=? AND a.subject_id=? AND a.added_open=1 AND ta.status='submitted' ORDER BY a.id",
        (cid, subject_id)).fetchall()


def tc_row_open(db, subject_id, cid, assignment_id):
    """True when this competency row is one of tc_added_open for the person: the only row a submitted person may answer."""
    return assignment_id is not None and any(r["id"] == assignment_id for r in tc_added_open(db, subject_id, cid))


def tc_score(db, assessment_id, source="effective"):
    """(score, max_score) for one assessment, or (None, max) when nothing has
    been answered yet -- max is still worth returning so the UI can show
    "0 / 12.5" rather than a blank.

    source: 'self' reads only the employee's own answers; 'effective' (the
    default) prefers the line manager's answer where they moderated one, which
    is what any downstream band must use. An assessment their line manager made
    on their behalf (they didn't submit, 2026-10-26) has no 'self': what they
    saved stays their private draft.
    """
    if source == "self" and _row_get(db.execute("SELECT on_behalf FROM tc_assessments WHERE id=?",
                                                (assessment_id,)).fetchone(), "on_behalf"):
        source = "none"
    rows = db.execute(
        "SELECT a.is_future, sc.answer, sc.manager_answer, a.cycle_id AS cid "
        "FROM tc_assignments a "
        "LEFT JOIN tc_scores sc ON sc.assignment_id = a.id AND sc.assessment_id = ? "
        "WHERE a.cycle_id = (SELECT cycle_id FROM tc_assessments WHERE id = ?) "
        "  AND a.subject_id = (SELECT subject_id FROM tc_assessments WHERE id = ?)",
        (assessment_id, assessment_id, assessment_id)).fetchall()
    score = 0.0
    max_score = 0.0
    answered = 0
    pts = points_for(db, rows[0]["cid"], "tc") if rows else None   # the assessment's own cycle's competency points
    for r in rows:
        weight = pts.dn if r["is_future"] else pts.dc
        # Max counts EVERY assigned competency, answered or not, so the
        # denominator is "what this person was asked", not "what they got round
        # to" -- otherwise a half-finished assessment reads as a perfect score.
        max_score += weight
        ans = (None if source == "none" else r["answer"] if source == "self"
               else r["manager_answer"] if source == "manager" else (r["manager_answer"] or r["answer"]))
        if ans is None:
            continue
        answered += 1
        if ans == TC_ANSWER_DEMONSTRATE:
            score += weight
        elif ans == TC_ANSWER_DEVELOPING:
            score += pts.vn if r["is_future"] else pts.vc   # Developing earns vc / vn (0 unless the super admin set it)
    if answered == 0:
        return None, max_score
    return score, max_score


def _jg_sort_key(jg):
    """Order job grades for display: numeric grades ascending, letter grades
    (H) first. Mirrors _jg_level()'s rule that a letter grade sits below the
    numeric ladder rather than sorting alphabetically among it."""
    try:
        return (1, int(jg))
    except (TypeError, ValueError):
        return (0, 0)


def tc_band_weights(db=None):
    """{job_grade: (w_360, w_tech)} for every configured grade, read ONCE per
    request and cached on `g` -- same idiom as org_display_map()/active_cycle().
    The whole table is ~13 rows, and the alternative is one query per subject
    inside loops that already run over a whole BG (up to ~1,000 people)."""
    m = getattr(g, "_tc_band_weights", None)
    if m is None:
        db = db or get_db()
        try:
            m = {r["job_grade"]: (float(r["w_360"]), float(r["w_tech"]))
                 for r in db.execute("SELECT job_grade, w_360, w_tech FROM tc_band_weights")}
        except sqlite3.OperationalError:
            # Table not created yet (a DB that predates this schema). Fall back
            # to 360-only rather than erroring, matching get_thresholds().
            m = {}
        g._tc_band_weights = m
    return m


def tc_weights_for(db, job_grade):
    """(w_360, w_tech) for one job grade, as percentages summing to 100.
    Falls back to 100:0 -- i.e. 360 only -- for a grade with no configured
    row, so an unrecognised grade can never silently score as if its
    technical half were zero."""
    jg = "" if job_grade is None else str(job_grade).strip()
    w = tc_band_weights(db).get(jg)
    return w if w else (100.0, 0.0)


def tc_reviewed_score(db, subject_id, cycle_id):
    """(self_score, approved_score, max) for a subject's technical assessment,
    or (None, None, None) when it can't count toward a band.

    Both figures come out of ONE query, because both are needed per subject and
    the calibration chain calls this inside a loop over an entire population --
    a second pass would double the cost of an already-heavy page.
      self_score     the employee's own answers
      approved_score the line manager's, where they moderated one

    Only a REVIEWED assessment counts here, for BOTH figures -- and a SUBMITTED one nobody reviews (the Executive Chairman's
    direct report while his Competency tick is off: their own answers stand, 2026-11-06, _tc_chair_unreviewed), read exactly
    as a reviewed one with no manager changes. (The Self potential figure no longer waits on it:
    since 2026-10-01 combined_potential() reads their SUBMITTED own answers through _tc_submitted_self -- Chris:
    "For self, it will use self-rated competency + 360 score" -- and the department review shows no LM band until
    the competency is approved, so a Self band beside a 360-only LM band no longer reads as a mark-down there.)"""
    row = db.execute(
        "SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=? AND status IN %s"
        % (("('submitted','reviewed')" if _tc_chair_unreviewed(db, subject_id) else "('reviewed')"),),
        (cycle_id, subject_id)).fetchone()
    if not row:
        return None, None, None
    self_score, max_score = tc_score(db, row["id"], source="self")
    approved, _m = tc_score(db, row["id"], source="effective")
    if approved is None or not max_score:
        return None, None, None
    # A reviewed assessment always has answers, but be explicit rather than
    # letting a None self_score fall through into the arithmetic below. One
    # their line manager made on their behalf has no self figure (2026-10-26).
    if self_score is None and _row_get(db.execute("SELECT on_behalf FROM tc_assessments WHERE id=?",
                                                  (row["id"],)).fetchone(), "on_behalf"):
        return None, approved, max_score
    return (self_score if self_score is not None else approved), approved, max_score


def _tc_submitted_self(db, subject_id, cycle_id):
    """(their own competency score, max) once their self-assessment is SUBMITTED (or reviewed), else (None, None).
    The Self potential band reads it before the line manager has approved anything; a draft is never read."""
    row = db.execute("SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=? AND status IN "
                     "('submitted','reviewed')", (cycle_id, subject_id)).fetchone()
    if not row:
        return None, None
    sc, mx = tc_score(db, row["id"], source="self")
    return (sc, mx) if (sc is not None and mx) else (None, None)


def _potential_blend(max_360, pct_360, w360, wtech, tech, mx):
    """(score, total, pct, band_score, 360 part, 360 part max, competency part, competency part max): the 360's share and
    a competency score, weighted by grade, on the sum of both maxima. THE arithmetic combined_potential and the line
    manager's preview (_lm_potential_view) share, so the preview can't differ from the figure the lock produces."""
    top = max_360 + mx
    c3, ct = pct_360 * w360 / 100.0 / 100.0 * top, (tech / mx * 100.0) * wtech / 100.0 / 100.0 * top
    tot = c3 + ct
    return tot, top, tot / top * 100.0, tot / top * max_360, c3, w360 / 100.0 * top, ct, wtech / 100.0 * top


def combined_potential(db, subject, cycle_id, avg_360):
    """The potential score: the 360 and the competency their line manager approved, WEIGHTED by the admin's split for
    the person's grade (360 Feedback / Competency -> Settings, tc_band_weights: 40:60 unless an admin sets a grade
    otherwise) and shown as a SUM
    on the total of both maxima (Chris, 2026-10-01: "put the both combined scores to the potential score, sum of
    competency and 360" ... "make sure the weightage is linked with the admin configuration" -- he chose "out of 30.0
    (the sum)"). Each half contributes its share of its own maximum times its weight's slice of that total: at 40:60
    on 17.5 + 12.5 = 30.0, the 360 can add up to 12.0 and the competency up to 18.0 (9.9/17.5 -> 6.8, 7.0/12.5 ->
    10.1, 16.9 / 30.0).

    The band: the share of the total is exactly the weighted blend, so it's read at that share of the 360's own scale
    (band_score = score / max * max_360) and the Low / Mid / High cut-offs (points on the 360 scale) keep their
    meaning. Percent-first matters: the 360 maxes at 17.5 (35.0 on the old framework) and ten competencies at 12.5,
    so adding raw points would make the competency count by its size, not by the configured weight.

    No approved competency (or a grade weighted 360-only): the 360 alone, out of the 360's maximum -- the missing half
    is never a zero. SELF: the same weighting with their OWN competency answers as soon as they have SUBMITTED them
    (Chris, 2026-10-01: "For self, it will use self-rated competency + 360 score"); a draft stays private.

    Returns a dict (never None when avg_360 is not None)."""
    max_360 = max_score_for_grade(db, subject["job_grade"], cycle_id) or 0.0
    none = {"score": None, "max": None, "pct": None, "band_score": None, "self_score": None, "self_max": None,
            "self_band_score": None, "pct_360": None, "pct_tech": None, "pct_tech_self": None,
            "pts_360": None, "max_360": max_360 or None, "pts_tech": None, "max_tech": None,
            "tech_self": None, "tech_self_max": None, "c_360": None, "c_360_max": None, "c_tech": None,
            "c_tech_max": None, "w_360": None, "w_tech": None, "source": "none"}
    if avg_360 is None or not max_360 or not cycle_has_potential(db, cycle_id):
        return none   # no 360 yet -- or a cycle with no potential result at all (cycle_has_potential)
    pct_360 = avg_360 / max_360 * 100.0
    w360, wtech = tc_weights_for(db, subject["job_grade"])

    def _blend(tech, mx):
        return _potential_blend(max_360, pct_360, w360, wtech, tech, mx)

    tc_self, tc_approved, tc_max = tc_reviewed_score(db, subject["id"], cycle_id)
    if tc_approved is None or not tc_max or not wtech:
        s_self, s_max = _tc_submitted_self(db, subject["id"], cycle_id) if wtech else (None, None)
        s3 = st = None
        if s_self is not None and s_max:
            ss, smx, _sp, sb, s3, _s3m, st = _blend(s_self, s_max)[:7]
            pct_tech_self = s_self / s_max * 100.0
        else:
            ss, smx, sb, pct_tech_self = avg_360, max_360, avg_360, None
        return dict(none, score=avg_360, max=max_360, pct=pct_360, band_score=avg_360, self_score=ss, self_max=smx,
                    self_band_score=sb, pct_360=pct_360, pct_tech_self=pct_tech_self, pts_360=avg_360,
                    tech_self=s_self, tech_self_max=s_max, w_360=w360, w_tech=wtech, source="360_only",
                    self_c_360=s3, self_c_tech=st)   # their own score's two parts, for the person's page (2026-10-05)
    score, mx, pct, bscore, c3, c3m, ct, ctm = _blend(tc_approved, tc_max)
    # no self figure when their line manager set the levels on their behalf (they didn't submit, 2026-10-26)
    ss, smx, _sp, sb, s3, _s3m, st = _blend(tc_self, tc_max)[:7] if tc_self is not None else (None,) * 7
    return dict(none, score=score, max=mx, pct=pct, band_score=bscore, self_score=ss, self_max=smx,
                self_c_360=s3, self_c_tech=st,
                self_band_score=sb, pct_360=pct_360, pct_tech=tc_approved / tc_max * 100.0,
                pct_tech_self=(tc_self / tc_max * 100.0 if tc_self is not None else None), pts_360=avg_360,
                pts_tech=tc_approved, max_tech=tc_max,
                tech_self=tc_self, tech_self_max=tc_max, c_360=c3, c_360_max=c3m, c_tech=ct, c_tech_max=ctm,
                w_360=w360, w_tech=wtech, source="combined")


def statement_agreement(db, subject, cycle_id=None, numbered=False):
    """Per-statement: how many SUBMITTED assessors said Demonstrate vs total,
    for one cycle (defaults to the active cycle).

    Returns the 7 criteria, each with its statements and (yes_count, total). Each criterion's `comments` name the assessor
    and the relationship ("assessor_name", "relationship"), except with `numbered=True` (an admin who is not the super admin,
    Chris 2026-11-11, "Yes, super admin only"): then the query never reads the assessor, each comment is {"rater": "Rater N",
    "rank": N, "comment"} (N = the place in `_rater_order`, the number the downloads use) and they run by N."""
    if cycle_id is None:
        cycle_id = active_cycle_id(db)
    sub_ids = [r["id"] for r in db.execute(
        "SELECT id FROM assignments WHERE subject_id=? AND cycle_id=? "
        "AND status='submitted' AND archived=0",
        (subject["id"], cycle_id)).fetchall()]
    # the statements the SUBMITTED answers hold (2026-11-08): the tier most of them were given on; the subject's live tier
    # when nobody has submitted, or when two tiers hold the same number of answers
    _live_tn = _cycle_tier_n(db, subject["job_grade"], cycle_id)
    _held = {}
    for _k in range(0, len(sub_ids), _FB_CHUNK):
        _part = sub_ids[_k:_k + _FB_CHUNK]
        for _r in db.execute("SELECT cs.tier_n AS tn, COUNT(r.answer) AS n FROM responses r "
                             "JOIN cycle_statements cs ON cs.id=r.statement_id WHERE r.assignment_id IN (%s) "
                             "GROUP BY cs.tier_n" % ",".join("?" * len(_part)), _part):
            _held[_r["tn"]] = _held.get(_r["tn"], 0) + (_r["n"] or 0)
    _held = {t: n for t, n in _held.items() if n}
    _tn = max(_held, key=lambda t: (_held[t], t == _live_tn, -t)) if _held else _live_tn
    stmts = statements_for_tier(db, _tn, cycle_id)
    # tally answers
    tally = {}  # statement_id -> [yes, answered]
    if sub_ids:
        q = ("SELECT statement_id, answer FROM responses "
             "WHERE assignment_id IN (%s) AND answer IS NOT NULL"
             % ",".join("?" * len(sub_ids)))
        for r in db.execute(q, sub_ids).fetchall():
            t = tally.setdefault(r["statement_id"], [0, 0])
            t[1] += 1
            if r["answer"] == "yes":
                t[0] += 1

    # Per-principle written comments from submitted assessors.
    comments_by_crit = defaultdict(list)
    if sub_ids and numbered:
        rank = {aid: i + 1 for i, aid in enumerate(_rater_order(db, [subject["id"]], cycle_id).get(subject["id"], []))}
        q = ("SELECT cc.criterion_id, cc.assignment_id AS aid, cc.comment FROM criterion_comments cc "
             "WHERE cc.assignment_id IN (%s) AND cc.comment IS NOT NULL AND TRIM(cc.comment) != ''"
             % ",".join("?" * len(sub_ids)))
        for r in db.execute(q, sub_ids).fetchall():
            if r["aid"] in rank:
                comments_by_crit[r["criterion_id"]].append({
                    "rater": "Rater %d" % rank[r["aid"]], "rank": rank[r["aid"]], "comment": r["comment"]})
        for _lst in comments_by_crit.values():
            _lst.sort(key=lambda c: (c["rank"], c["comment"]))
    elif sub_ids:
        q = ("SELECT cc.criterion_id, cc.comment, u.full_name AS assessor_name, "
             "a.relationship FROM criterion_comments cc "
             "JOIN assignments a ON a.id = cc.assignment_id "
             "JOIN users u ON u.id = a.assessor_id "
             "WHERE cc.assignment_id IN (%s) AND cc.comment IS NOT NULL "
             # by the TEXT, never the rater (2026-09-28): the name order survived into the anonymised report
             # (subject_report_context strips the name but kept the order), so it could be matched to a panel
             "AND TRIM(cc.comment) != '' ORDER BY cc.comment"
             % ",".join("?" * len(sub_ids)))
        for r in db.execute(q, sub_ids).fetchall():
            comments_by_crit[r["criterion_id"]].append({
                "assessor_name": r["assessor_name"],
                "relationship": r["relationship"],
                "comment": r["comment"],
            })

    grouped = []
    seen = {}
    for s in stmts:
        cid = s["criterion_id"]
        if cid not in seen:
            seen[cid] = {"name": s["criterion_name"],
                         "description": s["criterion_description"],
                         "comments": comments_by_crit.get(cid, []),
                         "statements": []}
            grouped.append(seen[cid])
        yes, tot = tally.get(s["statement_id"], [0, 0])
        seen[cid]["statements"].append({
            "text": s["text"], "is_future": s["is_future"],
            "yes": yes, "total": tot,
        })
    return grouped, len(sub_ids)


def principle_agreement_rollup(db, cycle_id, scope_clause="", scope_params=()):
    """Unweighted yes/total agreement per Leadership Principle, across every
    SUBMITTED response in `cycle_id` -- the cross-subject analog of
    statement_agreement() (which is strictly per-subject), powering the
    reporting dashboard's top/bottom-2 principles section. `scope_clause`/
    `scope_params` is a bg_scope()-shaped SQL fragment on subj.business_group
    / subj.company, so this reuses the same scoping idiom as every other
    admin view instead of a bespoke business_group/company parameter pair.
    One grouped query, no per-subject loop -- and no tier-matching filter: a
    SUBMITTED rating is never touched after it is submitted, so it holds whatever tier its rater answered, and a subject
    whose job grade moved to another tier AFTER their raters submitted keeps those old-tier answers (a pending rating is
    moved onto the new tier, _fb_retier_pending; a submitted one stays as it is, Chris 2026-11-08). The old comment here
    called a response outside the subject's current tier "structurally impossible": it is not (ticket OH-H-0083). Agreement is unweighted (yes/total),
    matching statement_agreement()'s existing precedent -- "agreement %" and
    "score" are deliberately distinct concepts in this app."""
    rows = db.execute(f"""
        SELECT cc.id, cc.name, cc.sort_order, cc.description,
               SUM(CASE WHEN r.answer='yes' THEN 1 ELSE 0 END) AS yes_count,
               COUNT(r.answer) AS total_answered
        FROM responses r
        JOIN cycle_statements cs ON cs.id = r.statement_id
        JOIN cycle_criteria   cc ON cc.id = cs.criterion_id
        JOIN assignments       a ON a.id = r.assignment_id
        JOIN users           subj ON subj.id = a.subject_id
        WHERE a.cycle_id=? AND a.status='submitted' AND a.archived=0
          AND subj.role!='admin' AND subj.is_demo=0
          {scope_clause}
        GROUP BY cc.id ORDER BY cc.sort_order
    """, [cycle_id] + list(scope_params)).fetchall()
    out = []
    for r in rows:
        pct = round(100 * r["yes_count"] / r["total_answered"]) if r["total_answered"] else None
        out.append({"id": r["id"], "name": r["name"], "sort_order": r["sort_order"],
                    "description": r["description"],
                    "yes_count": r["yes_count"], "total_answered": r["total_answered"], "pct": pct})
    return out


def principle_breakdown(db, subject, cycle_id):
    """One subject's WEIGHTED score per Leadership Principle, meaned across the
    assessors who submitted -- the per-principle analogue of subject_result()'s
    overall score, and the body of the Leadership Principle report.

    Weighted with the cycle's 360 points (points_for) exactly as assignment_score() is,
    and NOT the unweighted yes/total that principle_agreement_rollup() reports.
    The two are different measures on purpose and both are right for their own
    surface: agreement answers "how many behaviours did the panel agree on",
    this answers "how much of the available score did they earn". This one sits
    directly beneath the overall score in the same report, and a breakdown that
    cannot be reconciled with the total above it is worse than no breakdown.

    Dividing by the submitted-assessor count -- not by a per-principle count of
    who happened to answer that principle -- is what makes the reconciliation
    hold: sum(principles) == subject_result()['avg_score_raw'].

    Bands are DERIVED, not configured: the cycle's thresholds are calibrated against
    the whole instrument, so each principle's cut points are those thresholds
    scaled by its share of the tier's max. Callers must label them as derived.
    (Ported from production's main at the AI+ rollout, 2026-10-14: the cut-offs are now the cycle's own,
    thresholds_for_cycle, since a cycle carries its own Low/Mid cut-offs.)
    """
    n_sub = db.execute(
        "SELECT COUNT(*) n FROM assignments WHERE subject_id=? AND cycle_id=? "
        "AND status='submitted' AND archived=0", (subject["id"], cycle_id)).fetchone()["n"]

    tn = _cycle_tier_n(db, subject["job_grade"], cycle_id)
    # The denominator is the subject's OWN tier, so a principle is scored out of
    # what was actually asked of them rather than out of some other tier's set.
    pts = points_for(db, cycle_id, "360")   # the cycle's own points: Demonstrate dc / dn, Developing vc / vn
    maxes = db.execute(
        "SELECT cc.id, cc.name, cc.sort_order, cc.description, "
        "       SUM(CASE WHEN cs.is_future=1 THEN ? ELSE ? END) AS pmax "
        "FROM cycle_statements cs JOIN cycle_criteria cc ON cc.id = cs.criterion_id "
        "WHERE cs.cycle_id=? AND cs.tier_n=? GROUP BY cc.id ORDER BY cc.sort_order",
        (pts.dn, pts.dc, cycle_id, tn)).fetchall()

    got = {r["cid"]: r["got"] for r in db.execute(
        "SELECT cs.criterion_id AS cid, "
        "       SUM(CASE WHEN r.answer='yes' "
        "                THEN (CASE WHEN cs.is_future=1 THEN ? ELSE ? END) "
        "                WHEN r.answer='no' "
        "                THEN (CASE WHEN cs.is_future=1 THEN ? ELSE ? END) ELSE 0 END) AS got "
        "FROM responses r "
        "JOIN cycle_statements cs ON cs.id = r.statement_id "
        "JOIN assignments a ON a.id = r.assignment_id "
        "WHERE a.subject_id=? AND a.cycle_id=? AND a.status='submitted' AND a.archived=0 "
        "GROUP BY cs.criterion_id",
        (pts.dn, pts.dc, pts.vn, pts.vc, subject["id"], cycle_id))}

    low_max, mid_max = thresholds_for_cycle(db, cycle_id)
    total_max = max_score_for_grade(db, subject["job_grade"], cycle_id) or 0.0
    out = []
    for m in maxes:
        pmax = float(m["pmax"] or 0.0)
        score = (float(got.get(m["id"], 0.0)) / n_sub) if n_sub else None
        share = (pmax / total_max) if total_max else 0.0
        p_low, p_mid = low_max * share, mid_max * share
        band = None
        if score is not None:
            band = "Low" if score <= p_low else ("Mid" if score <= p_mid else "High")
        out.append({
            "id": m["id"], "name": m["name"], "sort_order": m["sort_order"],
            "tagline": PRINCIPLE_TAGLINES.get(m["sort_order"], m["description"] or ""),
            "score": round(score, 2) if score is not None else None,
            "max": round(pmax, 2),
            "pct": round(100.0 * score / pmax) if (score is not None and pmax) else None,
            "band": band,
            "low_max": round(p_low, 2), "mid_max": round(p_mid, 2),
        })
    return out


