def panel_suggestions(db, subject):
    # Any ACTIVE employee may be an assessor (confirmed or not), so suggestions
    # are gated on assessor_eligible_sql() — unconfirmed colleagues/reports are
    # offered too; only leavers are excluded.
    sid = subject["id"]
    mgr = (db.execute(
        f"SELECT id, employee_id, full_name, job_title, job_grade FROM users "
        f"WHERE id=? AND {assessor_eligible_sql()}", (subject["manager_id"],)).fetchone()
        if subject["manager_id"] else None)
    peers = db.execute(
        f"SELECT id, employee_id, full_name, job_title, job_grade FROM users "
        f"WHERE manager_id=? AND id!=? AND role!='admin' AND {assessor_eligible_sql()} "
        f"ORDER BY full_name",
        (subject["manager_id"], sid),
    ).fetchall() if subject["manager_id"] else []
    reports = db.execute(
        f"SELECT id, employee_id, full_name, job_title, job_grade FROM users "
        f"WHERE manager_id=? AND role!='admin' AND {assessor_eligible_sql()} ORDER BY full_name",
        (sid,),
    ).fetchall()
    return {"line_manager": mgr, "peers": peers, "reports": reports}


