def _device_signer():
    from itsdangerous import URLSafeTimedSerializer
    return URLSafeTimedSerializer(app.secret_key, salt="onehr-known-device")


def _known_device():
    """The browser's known-device cookie as {"d": its random id}, or None when there is none or it isn't ours (a bad
    signature or over DEVICE_COOKIE_DAYS old reads as no cookie). The cookie names no one: who signed in on this browser
    is in known_devices, keyed by the id (security test 2-13, 2026-10-31). A cookie from before that carried a list of
    Employee IDs as well: the id is still read and the list ignored, so such a browser counts as new for the lock rule
    until its next good sign-in puts it in the table."""
    raw = request.cookies.get(DEVICE_COOKIE)
    if not raw:
        return None
    try:
        v = _device_signer().loads(raw, max_age=DEVICE_COOKIE_DAYS * 86400)
    except Exception:  # noqa: BLE001 -- any bad cookie is just no cookie
        return None
    if not isinstance(v, dict) or not isinstance(v.get("d"), str) or not v["d"]:
        return None
    return {"d": v["d"]}


def _login_device_key(username):
    """The key a sign-in attempt is counted under: this browser's device id when it has signed in as `username`
    before, else None (every other browser shares the username's one count)."""
    dev = _known_device()
    if not dev:
        return None
    seen = get_db().execute("SELECT 1 FROM known_devices WHERE device=? AND username=? AND last_at > datetime('now', ?)",
                            (dev["d"], username, "-%d days" % DEVICE_COOKIE_DAYS)).fetchone()
    return dev["d"] if seen else None


def _remember_device(resp, username):
    """After a good sign-in: name `username` for this browser's device id in known_devices (the newest
    DEVICE_COOKIE_MAX_USERS kept), and refresh the cookie, which holds the id and nothing else."""
    db = get_db()
    dev = _known_device() or {"d": secrets.token_hex(16)}
    db.execute("INSERT OR REPLACE INTO known_devices(device, username, last_at) VALUES (?,?,datetime('now'))",
               (dev["d"], username))
    db.execute("DELETE FROM known_devices WHERE device=? AND username NOT IN (SELECT username FROM known_devices "
               "WHERE device=? ORDER BY last_at DESC, rowid DESC LIMIT ?)", (dev["d"], dev["d"], DEVICE_COOKIE_MAX_USERS))
    if secrets.randbelow(LOGIN_PRUNE_ODDS) == 0:   # a browser not seen for as long as the cookie lasts is gone for good
        db.execute("DELETE FROM known_devices WHERE last_at < datetime('now', ?)", ("-%d days" % DEVICE_COOKIE_DAYS,))
    db.commit()
    resp.set_cookie(DEVICE_COOKIE, _device_signer().dumps({"d": dev["d"]}),
                    max_age=DEVICE_COOKIE_DAYS * 86400, secure=_PROD, httponly=True, samesite="Lax")
    return resp


# A real hash to check against when the Employee ID matches no account, so a wrong password costs the same whether the
# ID exists or not (security test 2-03, 2026-10-31: 230 ms against 3 ms listed which IDs exist). Made the way every real
# hash is, at start-up, so it carries the same number of rounds.
_DUMMY_PW_HASH = generate_password_hash(secrets.token_hex(16), method="pbkdf2:sha256")


def _login_lock_trail(db, row, fails):
    """One Audit-log row when a sign-in lock trips (security test 2-10): against the account, nobody signed in, at most
    one an hour per account so a spray of wrong passwords can't flood the log. An Employee ID with no account has no one
    to write it against and writes nothing."""
    if db.execute("SELECT 1 FROM activity_log WHERE action='login_locked' AND target_user_id=? "
                  "AND created_at > datetime('now','-60 minutes')", (row["id"],)).fetchone():
        return
    _pw_trail(db, row["id"], "login_locked", "locked for %d minutes after %d failed sign-ins" % (LOGIN_WINDOW_MIN, fails))


def _login_account(db, typed, linked_only=False):
    """The users row a typed sign-in name belongs to, or None: the account whose sign-in name is exactly `typed` (as it
    always was), else the account that carries `typed` as an ACTIVE linked Employee ID (user_employee_ids, removed_at
    NULL), so a person who was given a new ID can still sign in, ask for a reset link or ask for help with an older one
    (Chris, 2026-11-03: "Use linked ID"). Exact match, case as typed (Employee ID is case-sensitive, Chris 2026-11-02).
    A linked ID never resolves to an admin or a demo account. `linked_only` skips the sign-in name (a caller that already
    looked it up its own way). Used by /login, Forgot password and sign-in help; the caller judges left_at."""
    typed = typed or ""
    if not typed:
        return None
    if not linked_only:
        row = db.execute("SELECT * FROM users WHERE username=?", (typed,)).fetchone()
        if row:
            return row
    return db.execute("SELECT u.* FROM user_employee_ids l JOIN users u ON u.id=l.user_id "
                      "WHERE l.removed_at IS NULL AND l.employee_id=? AND COALESCE(u.role,'')!='admin' "
                      "AND COALESCE(u.is_demo,0)=0 ORDER BY u.id LIMIT 1", (typed,)).fetchone()


@app.route("/login", methods=["GET", "POST"])
def login():
    # Already signed in (e.g. returned to /login without logging out)? Don't show
    # the login form again — that renders with a logged-in nav, looking half
    # signed-in. Send them to their landing page. A POST still processes, so
    # signing in as a different account from the form keeps working.
    if request.method == "GET" and current_user():
        return redirect(_landing_for(current_user()))
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        if not username or not password:
            # an empty field never counts as a failed attempt (the page checks this first; this is for no script)
            flash("Enter your Employee ID and password.", "error")
            return _login_page(username=username)
        db = get_db()
        # The account the typed name belongs to: its sign-in name, or an ACTIVE linked ID of a person (_login_account).
        row = _login_account(db, username)
        # what login_attempts stores and counts under: a typed ID is never kept past LOGIN_ID_MAX characters (2-11).
        # An account's tries are counted under ITS OWN sign-in name, so a person can't double them by alternating the
        # IDs they carry; a name that matches no account is counted as typed.
        ukey = (row["username"] if row else username)[:LOGIN_ID_MAX]
        # Throttle: too many recent failures for this username -> lock out. Counted per known device (see
        # DEVICE_COOKIE): a browser this person has signed in on keeps its own count, so another browser's failures
        # never lock them out of it.
        dkey = _login_device_key(ukey)
        fails = db.execute(
            "SELECT COUNT(*) FROM login_attempts WHERE username=? AND device IS ? "
            "AND ts > datetime('now', ?)",
            (ukey, dkey, f"-{LOGIN_WINDOW_MIN} minutes")).fetchone()[0]
        if fails >= LOGIN_MAX_FAILS:
            # the page says "Too many failed attempts" with a way to reset now (the sign-in redesign, 2026-10-15)
            return _login_page(locked=True, username=username)
        # ONE hash check whatever the row is (2-03): a dummy hash when there is no account, so how long a wrong password
        # takes never says whether the Employee ID exists, and a closed account costs the same as an open one
        good = check_password_hash(row["password_hash"] if row else _DUMMY_PW_HASH, password)
        if row and good and _row_get(row, "is_demo") and not demo_accounts_on():
            good = False   # a demo account signs in only where the server has demo accounts (2-01); is_demo alone, never an ID prefix
        if row and good and row["left_at"]:
            # Correct credentials but the account is closed (the person has left).
            flash("This account is no longer active. Please contact Group People.", "error")
            return _login_page(username=username)
        if row and good:
            _session_start(row)
            # clears only this browser's count: a good sign-in here mustn't wipe what another browser has failed
            db.execute("DELETE FROM login_attempts WHERE username=? AND device IS ?", (ukey, dkey))
            tkey = username[:LOGIN_ID_MAX]
            if tkey != ukey:   # signed in by a linked ID: tries recorded under that name before it was accepted go too
                db.execute("DELETE FROM login_attempts WHERE username=? AND device IS ?", (tkey, _login_device_key(tkey)))
            db.commit()
            _stamp_last_seen(force=True)   # Online now: signing in is use
            log_activity(db, row["id"], "login")
            return _remember_device(redirect(_landing_for(row)), row["username"])
        db.execute("INSERT INTO login_attempts(username, ip, device) VALUES (?,?,?)",
                   (ukey, request.remote_addr or "", dkey))
        if secrets.randbelow(LOGIN_PRUNE_ODDS) == 0:   # the lock reads only the last LOGIN_WINDOW_MIN minutes
            db.execute("DELETE FROM login_attempts WHERE ts < datetime('now', '-1 day')")
        db.commit()
        if row and fails + 1 >= LOGIN_MAX_FAILS:
            _login_lock_trail(db, row, fails + 1)
        flash("That Employee ID and password don't match. Check both and try again.", "error")
        return _login_page(username=username)
    return _login_page()


def _reset_by_email_available():
    """Whether Forgot password can email a link here: always on a laptop (the link shows on screen), and on staging or
    production only when Microsoft Graph mail is set up. The same for everyone, so it gives nothing away."""
    return not (_PROD and not mailer.is_configured())


def _login_page(locked=False, username=""):
    """The sign-in page (redesigned 2026-10-15): the brand panel, the form, and Forgot password as a pop-out on the
    page. `username` puts back the Employee ID they typed after an error; `locked` shows the lock-out message.
    ?forgot=1 opens the pop-out on load (the expired-link page sends people here)."""
    # the idle sentence, only for the one value the page's own countdown sends; the query's text is never echoed
    idle_note = (_session_idle_sentence() if SESSION_IDLE_MIN and request.args.get("signed_out") == "idle" else None)
    return render_template("login.html", locked=locked, username=(username or "")[:64], idle_note=idle_note,
                           reset_available=_reset_by_email_available(),
                           open_forgot=request.args.get("forgot") == "1",
                           LOGIN_WINDOW_MIN=LOGIN_WINDOW_MIN, RESET_TTL_MIN=RESET_TTL_MIN,
                           LOGIN_MAX_FAILS=LOGIN_MAX_FAILS, help_issues=SIGNIN_HELP_ISSUES,
                           help_max=SIGNIN_HELP_MAX_TEXT)


@app.route("/logout", methods=["GET", "POST"])
def logout():
    """Sign out: a POST with the form's token from every Log out button (security test 2-14). A GET still works for an
    old bookmark, but not when the browser says another site sent it (Sec-Fetch-Site other than same-origin or none):
    a link on another page must not sign someone out, so that one goes on to the dashboard, still signed in. A browser
    that sends no such header is let through. `?why=idle` (the page's countdown ran out, static/session_alive.js, a GET from
    the page itself) ends the session all the same and lands on the sign-in page with the idle sentence; any other value
    is ignored."""
    if request.method == "GET" and request.headers.get("Sec-Fetch-Site", "none") not in ("same-origin", "none"):
        return redirect(url_for("dashboard"))
    _online_clear()   # Online now: off the count at once (before the session, and so who they are, is cleared)
    _session_end_now()
    if request.method == "GET" and request.args.get("why") == "idle":
        return redirect(url_for("login", signed_out="idle"))
    return redirect(url_for("login"))


@app.route("/session/alive")
def session_alive():
    """The page's ping while someone types, clicks or scrolls with nothing sent (static/session_alive.js), so working on
    a long remark is activity too. The request gate has already counted it, or ended the session: this says which, with
    the words OneHR's box shows them. Always 200 (the deploy's route probe reads it signed out).
    `?peek=1` only reads, and counts as nothing: {signed_in, idle_left} (seconds left by the server's clock, null for an
    account the idle limit does not cover), so the page can check its own clock against the server's."""
    if current_user():
        left = None
        if _idle_applies(demo_actor()):
            seen = session.get("seen")
            left = (SESSION_IDLE_MIN * 60 + SESSION_SEEN_EVERY if not seen
                    else max(0, _idle_deadline(seen) - int(time.time())))
        return jsonify(signed_in=True, idle_left=left)
    why = getattr(g, "session_ended", None)
    copy = "Copy anything you've typed, then reload the page to sign in again."
    say = _session_idle_sentence(copy) if why == "idle" else "%s %s" % (
        _session_end_words(why) if why else "You're signed out.", copy)
    return jsonify(signed_in=False, why=why, say=say)


@app.route("/demo/switch", methods=["POST"])
@login_required
def demo_switch():
    """Switch which seeded persona the demo login is viewing the product as.

    404 rather than 403 for a login with no personas: on any database that was
    never demo-seeded the route should look like it doesn't exist, because
    effectively it doesn't."""
    actor = demo_actor()
    personas = demo_personas(actor)
    if not personas:
        abort(404)
    key = (request.form.get("persona", "") or "").strip()
    if key in ("", "self"):
        session.pop("demo_as", None)
    else:
        target = next((p for p in personas if p["demo_persona"] == key), None)
        if not target:
            abort(400)
        session["demo_as"] = target["id"]
        log_activity(get_db(), actor["id"], "demo_switch",
                     f"viewing as {DEMO_PERSONA_LABELS.get(key, key)}",
                     target_user_id=target["id"])
    # Grade H Appraisal's pages belong to the persona that is on them (2026-10-28): a Grade H person lands on their own page,
    # and no other persona is left on one (the staff page, the line manager's, the calibration or the admin pages)
    nxt0 = (request.form.get("next", "") or "").strip().split("?", 1)[0].rstrip("/")
    if key in ("gradeh", "gradeh_b") and gradeh_on():
        return redirect(url_for("my_appraisal"))
    if key == "gradeh_hlm" and gradeh_on():   # the Grade H line manager lands on the team list, in his own language (BM)
        return redirect(url_for("review_gradeh"))
    if any(nxt0 == x or nxt0.startswith(x + "/") for x in GRADEH_PATHS):
        return redirect(url_for("dashboard"))
    # Come back to the page they switched from, but only if it is a path on
    # this site -- a bare redirect to request.referrer is an open redirect.
    nxt = _local_path(request.form.get("next", ""), "")
    if nxt:
        # a review page belongs to the persona that was on it: a per-stage page (the KPI-setting chat, the old stage
        # chats) would show the new persona a step that isn't theirs, so they start where their own review says
        # (2026-10-13: switching from the Group Chief left the Employee on the KPI-setting chat). The journey keeps its
        # page; it checks the view and part against the new persona itself.
        _path = nxt.split("?", 1)[0].rstrip("/")
        if _path.startswith("/review") and _path not in ("/review", "/review/journey"):
            return redirect(url_for("review_home"))
        return redirect(nxt)
    return redirect(url_for("dashboard"))


# Demo only: the dashboard between cycles (Chris, 2026-10-12: "on the demo, can we also make the cycle selectable so i
# can view the dashboard look for offcycle time"). The demo's own cycle is open, so a demo login only ever saw the
# running dashboard. A seeded demo login -- one with personas, the same boundary as the role switch -- picks a past
# cycle in the top bar, and the dashboard shows its record view as it stood after that cycle: that cycle's journey and
# results, the history up to it, what they led in it, and the cycle after it as the next one. It is read-only and kept
# in the session, so it holds across a persona switch; "running" goes back to the live dashboard. Real logins never see
# it, and its route 404s for them.
DEMO_DASH_CYCLE_KEY = "demo_dash_cycle"


def demo_dash_cycles(db):
    """The cycles before the active one, newest first, that a demo login may see its dashboard after; [] for every real
    login. Ordered like the record (year, half, id), so a cycle that sorts after the active one is never offered."""
    if not demo_personas():
        return []
    rows = [dict(r) for r in db.execute("SELECT id, name, starts_on, is_active FROM cycles "
                                        "ORDER BY year DESC, half DESC, id DESC")]
    act = next((i for i, r in enumerate(rows) if r["is_active"]), None)
    return rows[act + 1:] if act is not None else rows


def demo_dash_as_of(db):
    """The past cycle the demo dashboard is showing, or None for the live one: {id, name, upto (its id and every older
    one), next (the cycle after it, which the record view names as the next)}."""
    try:
        cid = int(session.get(DEMO_DASH_CYCLE_KEY) or 0)
    except (TypeError, ValueError):
        return None
    if not cid:
        return None
    past = demo_dash_cycles(db)
    i = next((i for i, c in enumerate(past) if c["id"] == cid), None)
    if i is None:
        return None
    allc = [dict(r) for r in db.execute("SELECT id, name, starts_on FROM cycles ORDER BY year DESC, half DESC, id DESC")]
    j = next(j for j, c in enumerate(allc) if c["id"] == cid)
    return dict(past[i], upto={c["id"] for c in past[i:]}, next=(allc[j - 1] if j else None))


@app.route("/demo/dashboard-cycle", methods=["POST"])
@login_required
def demo_dash_cycle():
    """Set which past cycle the demo dashboard shows (or none, for the live one). 404 for a login with no personas."""
    db = get_db()
    past = demo_dash_cycles(db)
    if not past:
        abort(404)
    v = (request.form.get("cycle", "") or "").strip()
    if v in ("", "now"):
        session.pop(DEMO_DASH_CYCLE_KEY, None)
    else:
        if not v.isdigit() or int(v) not in {c["id"] for c in past}:
            abort(400)
        session[DEMO_DASH_CYCLE_KEY] = int(v)
    return redirect(url_for("dashboard"))


