    db = get_db()
    actor = demo_actor()
    ok, words, counts = demo_gradeh_reset(db, active_cycle_id(db))
    if ok:
        log_activity(db, actor["id"], "demo_gradeh_reset", words, commit=False)
    db.commit()
    flash(words, "ok" if ok else "error")
    cu = current_user()
