# only"; "the agent should offer the Go button card"). Reopen is never named outside the admins' list (Chris: "don't
# mention about the reopen ... we don't socialize this to ensure everyone owns their check-in process"). -------------
HELP_ABOUT = (("broken", "Something isn't working"), ("figure", "A figure or result looks wrong"),
              ("find", "I can't find or do something"), ("access", "My sign-in or access"),
              # what their Profile shows from their record (2026-10-22): its "Report it with Help" opens on this one
              ("details", "My work details are wrong"), ("other", "Something else"))
HELP_ABOUT_LABEL = dict(HELP_ABOUT)   # the topics a person may PICK (help_report refuses any other key)
# Topics OneHR opens by itself, never picked and never posted (help_report validates against HELP_ABOUT_LABEL alone). The Grade H "I do
# not agree" ticket (2 Nov 2026): the SUPER ADMIN's alone (_tk_scope_ok), and no AI model ever reads it (admin_tickets_agent refuses it
# before any model call, _tk_agent_facts refuses to build facts for it).
HELP_SYSTEM_ABOUT = {"gradeh_disagree": "Grade H: does not agree with their result"}
HELP_ABOUT_ALL = {**HELP_ABOUT_LABEL, **HELP_SYSTEM_ABOUT}   # every topic as a label (a list or a panel reads this)
HELP_MAX_TEXT = 1000
HELP_REPLY_MAX = 1000
HELP_SHOT_MAX_BYTES = 2 * 1024 * 1024
HELP_PER_HOUR = 10            # reports an hour from one person; more are answered calmly, not stored
HELP_UPLOAD_DIR = os.path.join(DATA_DIR, "uploads", "help")
HELP_STATUS = (("new", "New"), ("progress", "In progress"), ("sorted", "Sorted"))
HELP_STATUS_LABEL = dict(HELP_STATUS)
HELP_KIND = "help_request"
HELP_ADDRESS = "group.people@example.com"
HELP_LIST_MAX = 5


def help_ref(rid):
    return "OH-H-%04d" % rid


def _help_shot_kind(data):
    """The image type of a screenshot by its own bytes (never the name or the browser's word): png / jpg / gif /
    webp, else None. No SVG: it can carry script."""
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "png"
    if data[:3] == b"\xff\xd8\xff":
        return "jpg"
    if data[:6] in (b"GIF87a", b"GIF89a"):
        return "gif"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "webp"
    return None


_HELP_SHOT_MIME = {"png": "image/png", "jpg": "image/jpeg", "gif": "image/gif", "webp": "image/webp"}


def _help_browser(ua):
    """'Chrome on Windows': the browser and the system, nothing else of the user-agent string."""
    ua = ua or ""
    b = next((n for k, n in (("Edg/", "Edge"), ("OPR/", "Opera"), ("Firefox/", "Firefox"), ("Chrome/", "Chrome"),
                             ("Safari/", "Safari")) if k in ua), "A browser")
    o = next((n for k, n in (("Windows", "Windows"), ("iPhone", "iPhone"), ("iPad", "iPad"), ("Android", "Android"),
                             ("Mac OS X", "Mac"), ("Linux", "Linux")) if k in ua), "")
    return "%s on %s" % (b, o) if o else b


