# The Go card (board E): a reply of OneHR Agent's that points to Help gets a card that opens it on Report a problem.
# Decided here from the words, never by the model; the welcome's own line about Help is left without one.
_HELP_POINT_RE = re.compile(r"\bHelp\b[^.!?\n]{0,40}\baccount menu\b")


def _help_points(say):
    return bool(say and isinstance(say, str) and _HELP_POINT_RE.search(say))


def _help_go_mark(rv):
    """A chat turn's JSON with help_go set when its reply points to Help."""
    resp = rv[0] if isinstance(rv, tuple) else rv
    try:
        d = resp.get_json(silent=True)
    except Exception:   # noqa: BLE001 -- not JSON: leave it as it is
        return rv
    if isinstance(d, dict) and _help_points(d.get("say")):
        d["help_go"] = True
        resp.set_data(json.dumps(d))
    return rv


@app.route("/reset/<token>", methods=["GET", "POST"])
def reset_password(token):
    """Set a new password from a valid (unused, unexpired) reset link."""
    db = get_db()
    th = _hash_token(token)
    # a link is good while it is unused and young, the account is open, and no password has been written for the account
    # since the link was made (security test 2-06): a password change, an admin's reset or an import ends every link
    # from before it, whichever writer it was, because each stamps pw_set_at
    row = db.execute(
        "SELECT r.user_id, u.employee_id, u.username, u.full_name, u.password_hash FROM password_resets r JOIN users u ON u.id=r.user_id "
        "WHERE r.token_hash=? AND r.used_at IS NULL AND r.created_at > datetime('now', ?) AND u.left_at IS NULL "
        "AND NOT COALESCE(datetime(u.pw_set_at) > datetime(r.created_at), 0)",
        (th, f"-{RESET_TTL_MIN} minutes")).fetchone()
    if not row:
        return render_template("reset_password.html", valid=False, RESET_TTL_MIN=RESET_TTL_MIN)
    if request.method == "POST":
        new = request.form.get("new", "")
        confirm = request.form.get("confirm", "")
        bad = _password_problem(new, row["employee_id"], row["username"], names=row["full_name"])
        if bad:
            flash(bad, "error")
        elif new != confirm:
            flash("New password and confirmation don't match.", "error")
        elif _pw_reused(db, row["user_id"], new, row["password_hash"]):   # the last 5, the current one too (2026-10-31)
            flash(PW_REUSED_MSG, "error")
        else:
            uid = row["user_id"]
            _pw_history_push(db, uid)
            db.execute("UPDATE users SET password_hash=?, pw_source='own', pw_set_at=datetime('now') WHERE id=?",
                       (generate_password_hash(new, method="pbkdf2:sha256"), uid))
            db.execute("UPDATE password_resets SET used_at=datetime('now') WHERE token_hash=?", (th,))
            _pw_close_resets(db, uid)
            # clear any login lockout so they can sign in immediately
            db.execute("DELETE FROM login_attempts WHERE username="
                       "(SELECT username FROM users WHERE id=?)", (uid,))
            db.commit()
            _pw_trail(db, uid, "password_reset", "password set via reset link", by_them=True)
            flash("Your password is reset. Sign in with your new password.", "ok")
            return redirect(url_for("login"))
    return render_template("reset_password.html", valid=True, token=token, RESET_TTL_MIN=RESET_TTL_MIN)


