@app.route("/my-assessments")
@login_required
def my_assessments():
    u = current_user()
    if u["role"] == "admin":
        return redirect(url_for("admin_overview"))
    db = get_db()
    # Employees only ever work the single ACTIVE cycle. The deadline is a soft
    # target (no date cutoff while the cycle is active); launching the next
    # cycle archives this one and moves everyone to the new active season.
    cid = active_cycle_id(db)
    rows = db.execute(
        """SELECT a.id, a.relationship, a.status, a.submitted_at, a.reset_at,
                  s.id AS subject_id, s.full_name AS subject_name,
                  s.job_title AS subject_title, s.department AS subject_dept,
                  s.job_grade AS subject_jg
           FROM assignments a JOIN users s ON s.id = a.subject_id
           WHERE a.assessor_id = ? AND a.cycle_id = ? AND a.archived = 0 AND """ + rater_task_sql("a") + """
           ORDER BY a.status, s.full_name""",
        (u["id"], cid),
    ).fetchall()
    # The 7 leadership principles for this cycle — shown on the friendly empty
    # state for people who have no tasks and aren't a subject, so the page is a
    # positive touchpoint rather than a dead end.
    principles = db.execute(
        "SELECT name, description FROM cycle_criteria WHERE cycle_id=? ORDER BY sort_order, id",
        (cid,)).fetchall()
    return render_template("my_assessments.html", rows=rows, principles=principles)


@app.route("/performance/summary")
@login_required
def performance_summary():
    """One of this person's own periods as JSON, for the record's pop-out.

    Read-only by construction -- it returns what was decided, never a way to
    change it. The period must be one they hold targets in (pm_user_periods()
    is already scoped to that), so this can only ever return their own halves.

    Deliberately the outcome, not the working surface: what each KPI was, what
    they reported, what it was moderated to, and the rating that came out.
    Filling a result in is a different job, on a different page.

    RETIRED 2026-10-31 (security stage 1, the classic pages' removal): its one caller was /me's pop-out and /me goes to
    the dashboard now, so a GET goes there too. The body stays until stage 2 takes the route and its template out."""
    return redirect(url_for("dashboard"))
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    try:
        pid = int(request.args.get("period", ""))
    except (TypeError, ValueError):
        abort(400)
    period = next((p for p in pm_user_periods(db, u["id"]) if p["id"] == pid), None)
    if not period:
        abort(404)
    if pid != active_pm_period_id(db):
        # a past half shows its final band only, never its KPI table (Chris, 2026-10-08: it "will show different
        # results and raise confusion")
        abort(404)
    out = _pm_period_summary(db, u, pid)
    return jsonify({"period": period["name"], "lines": out["lines"], "overall": out["overall"],
                    "url": url_for("performance_my_view", period=pid)})


def _pm_period_summary(db, u, pid):
    """One of this person's periods, decided outcome only: {lines, overall}. Shared by the record's pop-out JSON
    (performance_summary) and the record panel (2026-10-08). Each line: their own result, the moderated one only once
    the line is locked, the score and its band; drafts are absent (attach_pm_chains' default); the overall only once
    every line is locked (pm_overall_for_targets)."""
    targets = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY " + PM_LINE_ORDER,
        (pid, u["id"]))]
    attach_pm_chains(db, targets)
    pm_score_targets(db, targets)
    lines = []
    for t in targets:
        sc = t.get("score")
        self_v = t["result"]["actual_value"] if t.get("result") else None
        lines.append({
            "name": t["kpi_name"], **kpi_line_parts(t), "unit": t["unit"] or "",
            "weightage": t["weightage"],
            "self": self_v,
            "moderated": (t["effective_value"] if t.get("locked") else None),
            "score": (round(sc["value"], 2) if sc and sc["mechanism"] == "A"
                      else (round(sc["value"], 1) if sc else None)),
            "mechanism": (sc["mechanism"] if sc else None),
            "label": (sc.get("label") if sc else None),
            "locked": bool(t.get("locked")),
            # the targets themselves (2026-10-18, Where you stand > Details): the 1-5 rating figures, or threshold /
            # target / excellence (or the cap multiple) by the group's mechanism; method more / less
            "category": t.get("category") or "", "method": t.get("method"), "mech": t.get("mechanism"),
            "rates": [t.get("rate%d" % i) for i in range(1, 6)],
            "threshold": t.get("threshold"), "target": t.get("target"),
            "multiple": t.get("multiple"), "excellence": t.get("excellence"),
        })
    overall = pm_overall_for_targets(db, targets)
    return {
        "lines": lines,
        "scale": _pm_scale_for(db, targets[0]["business_group"], subject=u["id"], cycle_id=pid) if targets else None,
        "overall": ({"value": (None if overall["value"] is None else round(overall["value"], 2) if overall["mechanism"] == "A"
                               else round(overall["value"], 1)),
                     "mechanism": overall["mechanism"],
                     "label": overall["label"],
                     "label_name": PM_LABEL_NAMES.get(overall["label"], overall["label"]),
                     # a transferred person's blend says so (2026-11-03): the weights, never the Mid-Year figure's own line
                     **({"split": {"weight_mid": overall["split"]["weight_mid"], "weight_ye": overall["split"]["weight_ye"],
                                   "mixed": overall["split"]["mixed"], "text": pm_split_text(overall),
                                   "ye_text": _kpi_total_text(overall["split"]["ye"]) or overall["split"]["ye"].get("label")}}
                       if overall.get("split") else {})}
                    if overall else None),
    }


def _pm_scale_for(db, bg, subject=None, *, cycle_id):
    """A business group's KPI scale for reading targets (2026-10-18): {mechanism, variant, bands}. Mechanism A is the
    one global 1-5 scale; B is the group's own achievement cut-offs, label and floor %, or -- for this `subject` (a user
    id, a user row or a KPI line) -- their unit's or department's own (pm_bands_for, band rules 2026-10-29), so the
    page agrees with the label the server gives, read in `cycle_id` (band starts are per cycle). None when unconfigured."""
    cfg = db.execute("SELECT mechanism, variant FROM pm_bg_config WHERE business_group=?", (bg,)).fetchone()
    if not cfg:
        return None
    bands = []
    if cfg["mechanism"] == "B":
        uid, company, department = _pm_subject_who(db, subject) if subject is not None else (None, None, None)
        bands = [{"label": lab, "min": lo}
                 for lab, lo in pm_bands_for(db, bg, company, department, cycle_id=cycle_id, user_id=uid)]
    return {"mechanism": cfg["mechanism"], "variant": cfg["variant"], "bands": bands}


@app.route("/my-report/summary")
@login_required
def my_report_summary():
    """One released season of this person's own report, as JSON for the
    record's pop-out.

    Same gate as my_report(): the cycle must be one THIS person has a release
    row for, so the endpoint can only ever return their own released seasons
    -- a spoofed id 404s rather than falling back to another season, because a
    silent fallback in a pop-out reads as "here is your 2024 report" while
    showing 2026.

    Deliberately a summary, not the whole page: band, per-principle agreement,
    and the comments -- which is what someone opening an old season actually
    wants to re-read. The full report stays one click further on.

    RETIRED 2026-10-31 (security stage 1, the classic pages' removal): its one caller was /me's pop-out and /me goes to
    the dashboard now, so a GET goes there too. The body stays until stage 2 takes the route and its template out."""
    return redirect(url_for("dashboard"))
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    try:
        cid = int(request.args.get("cycle", ""))
    except (TypeError, ValueError):
        abort(400)
    cyc = db.execute(
        "SELECT c.id, c.name FROM report_releases rr JOIN cycles c ON c.id=rr.cycle_id "
        "WHERE rr.subject_id=? AND c.id=?", (u["id"], cid)).fetchone()
    if not cyc:
        abort(404)
    rep_ = _report_season_principles(db, u, cid)
    return jsonify({
        "cycle": cyc["name"],
        "band": rep_["band"],
        "n_submitted": rep_["n_submitted"],
        "principles": rep_["principles"],
        "url": url_for("my_report", cycle=cid),
    })


def _report_season_principles(db, u, cid):
    """One RELEASED season of this person's own 360, as the record shows it: {band, n_submitted, principles}. The
    CALLER checks the release (report_releases) first. Shared by the pop-out JSON (my_report_summary) and the record
    panel (2026-10-08). subject_report_context() has already stripped assessor identity."""
    s = db.execute("SELECT * FROM users WHERE id=?", (u["id"],)).fetchone()
    ctx = subject_report_context(db, s, cid)
    ctx["band_info"] = _report_band_info(db, s, cid, ctx["band_info"])   # the FINAL band, once released (2026-10-02)
    principles = []
    for crit in ctx["agreement"]:
        yes = sum(st["yes"] for st in crit["statements"])
        total = sum(st["total"] for st in crit["statements"])
        principles.append({
            "name": crit["name"],
            "description": crit.get("description") or "",
            "yes": yes, "total": total,
            "pct": round(100 * yes / total) if total else 0,
            # subject_report_context() has already stripped assessor identity.
            "comments": [c["comment"] for c in crit["comments"] if c["comment"]],
        })
    info = ctx["band_info"]
    return {"band": info["band"] if info.get("score_valid") else None,
            "n_submitted": ctx["n_submitted"], "principles": principles}


@app.route("/my-report")
@login_required
def my_report():
    """The employee's own anonymized 360 report — visible only once an admin
    has released it. Assessor identities (names AND relationships) are never
    shown here, and neither is the raw numeric score — only the potential
    band (Low/Mid/High)."""
    u = current_user()
    if u["role"] == "admin":
        return redirect(url_for("admin_overview"))
    db = get_db()
    s = db.execute("SELECT * FROM users WHERE id=?", (u["id"],)).fetchone()
    # Cycles in which this employee's report has been released to them — newest
    # first. This is their feedback history across review seasons.
    released_cycles = db.execute(
        """SELECT c.id, c.code, c.name, c.ends_on, rr.released_at
           FROM report_releases rr JOIN cycles c ON c.id = rr.cycle_id
           WHERE rr.subject_id = ? ORDER BY c.year DESC, c.half DESC, c.id DESC""",
        (u["id"],)).fetchall()
    if not released_cycles:
        return render_template("my_report.html", released=False, s=s,
                               released_cycles=[], active_view="mine")
    # Which season to show: ?cycle=<id> if it's one of theirs, else the latest.
    try:
        sel_id = int(request.args.get("cycle", ""))
    except (TypeError, ValueError):
        sel_id = None
    sel = next((c for c in released_cycles if c["id"] == sel_id), released_cycles[0])
    agreement, n_submitted = statement_agreement(db, s, sel["id"])
    # the band beside the report is the FINAL potential band, shown only once a super admin has released it
    # (2026-10-02) -- the report's own release brings the report, not the band.
    band_info = _report_band_info(db, s, sel["id"], subject_band(db, s, sel["id"]))
    return render_template("my_report.html", released=True, s=s,
                           agreement=agreement, n_submitted=n_submitted,
                           released_cycles=released_cycles, sel_cycle=sel,
                           band_info=band_info, active_view="mine")


def can_view_report(db, viewer, uid):
    """True if `viewer` may see uid's band/report as their line manager or
    HOD. hod_id is a flat per-person field (may span several management
    layers), so a match there is sufficient on its own — no chain-walk
    needed for this permission check (only the /hod tree layout walks the
    manager_id chain)."""
    row = db.execute("SELECT manager_id, hod_id, left_at FROM users WHERE id=?",
                     (uid,)).fetchone()
    if not row or row["left_at"] is not None:
        return False
    return row["manager_id"] == viewer["id"] or (row["hod_id"] == viewer["id"]
                                                 and hod_has_role(db, viewer["id"]))   # a calibrator is no HOD (2026-10-30)


def calibration_can_view_subject(db, viewer, uid):
    """True if `viewer` calibrates `uid` -- i.e. that person sits inside a
    scope this login actually holds: their HOD department, their BUCEO
    company, their BGCEO business group, or a PM calibration group this login
    is the calibrator of. Super admin always passes.

    Two deliberate differences from can_view_report():

    * Release-independent. report_releases gates the EMPLOYEE's own view of
      their feedback; a calibrator is deciding this person's band right now,
      so gating on it would withhold exactly the evidence the decision rests
      on. Confirmed: "within their scope, ignoring release."
    * Org-relationship, not population predicate. The two modules' populations
      genuinely differ (potential = confirmed + not-demo; performance also
      requires KPI targets for the period), and one helper serves both report
      surfaces plus the Talent Box -- so this is the union bound by real
      reporting relationships rather than either module's own filter. The
      calibration pages only ever render the icon for someone already in
      their list; this is the backstop for a hand-typed URL.
    """
    if is_super(viewer):
        return True
    s = db.execute("SELECT business_group, company, department, hod_id, role FROM users WHERE id=?",
                   (uid,)).fetchone()
    if not s or s["role"] == "admin":
        return False
    tb_early = bool(_tb_hidden_msg(db, viewer))   # the BG CEO's and a Group Chief's reach waits for their Talent Box (Chris, 2026-11-04)
    # a calibrator of theirs at BU level (2026-10-22; any of several since 2026-10-26)
    if any(g_["calibrator_id"] == viewer["id"] for g_ in bu_groups_of_person(db, s)):
        return True
    for tier, key in calibration_tier_of(db, viewer):
        if tier == "hod" and s["hod_id"] == key:
            return True
        if tier == "buceo" and (s["business_group"], s["company"]) == key:
            return True
        if tier == "bgceo" and s["business_group"] == key and not tb_early:
            return True
    return not tb_early and bool(db.execute(
        "SELECT 1 FROM pm_calibration_group_members m "
        "JOIN pm_calibration_groups g ON g.id = m.group_id "
        "WHERE m.subject_id=? AND g.calibrator_id=? LIMIT 1",
        (uid, viewer["id"])).fetchone())


@app.route("/calibration/subject/<int:uid>/kpi-report")
@login_required
def calibration_kpi_report(uid):
    """The KPI evidence behind one person's performance rating, for whoever is
    calibrating it: every KPI line with its target, self-submitted result,
    moderated result and per-line rating, plus the approved overall. Rendered
    as a fragment -- the calibration pages fetch it into a modal so the
    calibrator never loses their place in the grid or the table."""
    db = get_db()
    u = current_user()
    s = db.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
    if not s or not calibration_can_view_subject(db, u, uid):
        abort(403)
    _out = _one_person_report_refusal(db, u, uid, ("pm",))   # out means out (1b-03)
    if _out:
        return Response(_out, 403, mimetype="text/plain")
    period = active_pm_period(db)
    targets = []
    if period:
        targets = [dict(t) for t in db.execute(
            "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY " + PM_LINE_ORDER,
            (period["id"], uid)).fetchall()]
        if targets:
            attach_pm_chains(db, targets)
            pm_score_targets(db, targets)
    # The approved figure, on the same require_locked=True rule the calibration
    # row itself uses -- so the report can never show an overall the calibration
    # table calls "not finalised".
    overall = pm_overall_for_targets(db, targets) if targets else None
    remark = db.execute(
        "SELECT remark FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=? AND draft=0",
        (period["id"], uid)).fetchone() if period else None
    # Every approver's remark on the period, beside the employee's -- a matrix
    # split gives one subject more than one, so they are listed and attributed
    # rather than collapsed. Held back until every line is locked:
    # pm_manager_remarks has no draft column (it autosaves as the manager
    # types), so showing it earlier would put a half-written sentence in front
    # of the person calibrating them.
    all_locked = bool(targets) and all(t["locked"] for t in targets)
    mgr_remarks = [dict(r) for r in db.execute(
        "SELECT r.remark, u.full_name AS author, r.submitted_by AS author_id FROM pm_manager_remarks r "
        "LEFT JOIN users u ON u.id = r.submitted_by "
        "WHERE r.cycle_id=? AND r.subject_id=? AND TRIM(COALESCE(r.remark,'')) != '' "
        "ORDER BY r.submitted_at", (period["id"], uid)).fetchall()] if all_locked else []
    for _mr in mgr_remarks:   # the super admin alone is given a "Pasted" chip (_paste_chip)
        _mr["paste"] = _paste_chip(db, current_user(), _mr.get("author_id"), period["id"], "pm_review", uid)
    return render_template("_calib_report_kpi.html", s=s, period=period,
                           paste_self=(_paste_chip(db, current_user(), uid, period["id"], "account") if period else None),
                           targets=targets, overall=overall,
                           label_names=PM_LABEL_NAMES,
                           self_remark=(remark["remark"] if remark else ""),
                           manager_remarks=mgr_remarks,
                           # The ledger reaching the room -- the one thing the
                           # report did not already show. Subject-scoped read.
                           cited=_pm_cited_evidence(db, uid))


def _calib_tc_evidence(db, s, cycle_id):
    """The technical half of one person's potential, for the potential report:
    the score, how it is weighted against the 360 half at their grade, the
    per-section demonstrated counts, and every remark either side wrote.

    None when the person was never assigned any competencies -- there is
    nothing to say, and an empty section would read as a gap in the record
    rather than a module they aren't in.

    The section detail is gated on 'reviewed' for the same reason
    tc_reviewed_score() gates the band: before the line manager has looked,
    the answers are the employee's own unchallenged self-rating, and putting
    them beside a 360 band a calibrator is about to act on would lend them a
    standing they haven't earned yet. The status still shows, so a calibrator
    can see the review is outstanding rather than wonder why it's blank.
    """
    a = db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                   (cycle_id, s["id"])).fetchone()
    n_assigned = db.execute(
        "SELECT COUNT(*) FROM tc_assignments WHERE cycle_id=? AND subject_id=?",
        (cycle_id, s["id"])).fetchone()[0]
    if not n_assigned:
        return None
    # a submitted one nobody reviews (the Executive Chairman's direct report, 2026-11-06) stands as it is: read as reviewed
    out = {"status": _tc_status_eff(db, s["id"], a["status"]) if a else "pending", "n_assigned": n_assigned, "groups": [],
           "score": None, "max": None, "pct": None,
           "overall_remark": "", "manager_overall_remark": "",
           "nobody": bool(a and a["status"] == "submitted" and _tc_status_eff(db, s["id"], "submitted") == "reviewed")}
    if not a:
        return out
    # A remark reaches the calibration room only once it is FINAL (2026-09-28): theirs once submitted, the line
    # manager's once the review is done. Both autosave as they are typed, so reading them earlier put a draft --
    # half a sentence -- in front of the calibrator.
    ob = bool(_row_get(a, "on_behalf"))   # set on their behalf (2026-10-26): nothing of theirs was submitted
    out["on_behalf"] = ob
    if a["status"] in ("submitted", "reviewed") and not ob:
        out["overall_remark"] = a["overall_remark"] or ""
    if out["status"] == "reviewed":
        out["manager_overall_remark"] = a["manager_overall_remark"] or ""
    if out["status"] != "reviewed":
        return out
    score, mx = tc_score(db, a["id"], "effective")
    out["score"], out["max"] = score, mx
    if score is not None and mx:
        out["pct"] = round(100.0 * score / mx)
    _rows, groups = _tc_rows(db, cycle_id, s["id"], a["id"])
    for grp in groups:
        grp["n_total"] = len(grp["rows"])
        grp["n_yes"] = sum(1 for r in grp["rows"] if r["effective"] == TC_ANSWER_DEMONSTRATE)
        if ob:   # their saved answers and notes were never submitted: not theirs to show
            for r in grp["rows"]:
                r["answer"], r["remark"] = None, None
    out["groups"] = groups
    return out


