def _tc_submit(db, cid, u, assessment):
    """Validate + submit a competency self-assessment: every competency answered,
    then flip status to 'submitted'. ONE gate+write authority, shared by the
    /technical page's form route and the /review competency chat's JSON submit, so
    the two can never disagree about what a submittable assessment is. Returns
    (ok, error)."""
    _w = window_closed(db, "tc_self")
    if _w:
        return False, _w
    if not tc_can_self_edit(assessment):
        if tc_added_open(db, u["id"], cid):   # submitted, with a competency added since: only it is submitted now
            return _tc_submit_added(db, cid, u, assessment)
        return False, "Your technical competency assessment has already been submitted."
    done, total = _tc_progress(db, cid, u["id"], assessment["id"])
    if not total or done < total:
        return False, ("Answer all %d competencies before submitting — %d still blank."
                       % (total, total - done))
    db.execute("UPDATE tc_assessments SET status='submitted', "
               "submitted_at=datetime('now') WHERE id=?", (assessment["id"],))
    _reopen_close(db, _row_get(assessment, "subject_id"), ["tc_self"], actor_id=u["id"])   # HR's reopen is redone
    _late_close(db, _row_get(assessment, "subject_id"), "tc_self", "used")   # ...and so is a late pass (2026-10-31)
    _rating_record_refresh(db, cid, [_row_get(assessment, "subject_id")], "tc_submit", u["id"])
    db.commit()
    log_activity(db, u["id"], "tc_submit", "technical competency self-assessment")
    return True, None


def _tc_submit_added(db, cid, u, assessment):
    """Submit the competencies Group People added after the person submitted: every one answered, then they are closed
    (added_open 0). The assessment's status and submitted_at, their overall remark, every other answer and their manager's
    review are not touched; nothing is asked again. The one shared function (the page's Submit, the card's Save & submit and
    the typed confirm all come here through _tc_submit). (ok, error)."""
    rows = tc_added_open(db, u["id"], cid)
    if not rows:
        return True, None
    blank = [r["id"] for r in rows if not db.execute(
        "SELECT 1 FROM tc_scores sc JOIN tc_assignments x ON x.id=sc.assignment_id WHERE sc.assessment_id=? AND "
        "sc.assignment_id=? AND x.cycle_id=? AND x.subject_id=? AND sc.answer IS NOT NULL",
        (assessment["id"], r["id"], cid, u["id"])).fetchone()]
    if blank:
        return False, ("Answer the new competenc%s before submitting -- %d still blank." % (
            "y" if len(rows) == 1 else "ies", len(blank)))
    db.execute("UPDATE tc_assignments SET added_open=0 WHERE cycle_id=? AND subject_id=? AND added_open=1", (cid, u["id"]))
    _late_close(db, u["id"], "tc_self", "used")   # a pass for the new competency is used
    _rating_record_refresh(db, cid, [u["id"]], "tc_submit_added", u["id"])
    db.commit()
    log_activity(db, u["id"], "tc_submit", "technical competency self-assessment: competencies added after submit")
    return True, None


