def build_hod_forest(hod_id, population):
    """Arrange an HOD's whole population (everyone whose hod_id points at
    them) into a parent-child forest using manager_id edges. Roots are
    members who report straight to the HOD, have no manager, or whose
    manager isn't in this population. A defensive `ancestry` set stops a
    bad/circular manager_id chain from recursing forever."""
    by_id = {p["id"]: p for p in population}
    children = defaultdict(list)
    roots = []
    for p in population:
        mgr = p["manager_id"]
        if mgr == hod_id or mgr is None or mgr not in by_id:
            roots.append(p["id"])
        else:
            children[mgr].append(p["id"])

    def build_node(pid, ancestry):
        node = {"user": by_id[pid], "is_direct": by_id[pid]["manager_id"] == hod_id,
                "children": []}
        for cid in sorted(children.get(pid, []), key=lambda i: by_id[i]["full_name"]):
            if cid in ancestry:
                continue
            node["children"].append(build_node(cid, ancestry | {cid}))
        return node

    roots.sort(key=lambda i: by_id[i]["full_name"])
    return [build_node(rid, {rid}) for rid in roots]


def flatten_forest(forest, depth=0):
    """Depth-first flatten of build_hod_forest()'s tree into row order, for
    the table layout (hierarchy conveyed by depth-based indent instead of
    nested <ul>s)."""
    rows = []
    for node in forest:
        rows.append({**node, "depth": depth})
        rows.extend(flatten_forest(node["children"], depth + 1))
    return rows


@app.route("/hod")
@login_required
def hod_view():
    """An HOD's whole department as a table, with each person's potential
    band (once released) and a Direct/Indirect relationship tag. Row order
    keeps each manager's people clustered (parent immediately followed by
    its children, per build_hod_forest()/flatten_forest()), even though the
    table itself is flat."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    cid = active_cycle_id(db)
    population = db.execute(
        f"SELECT * FROM users WHERE hod_id=? AND role!='admin' AND {team_hod_member_sql()} "
        f"ORDER BY full_name", (u["id"], cid)).fetchall() if hod_has_role(db, u["id"]) else []
    if not population:
        # Same query nav_is_hod runs — if the tab wouldn't show, the page
        # itself is off-limits too (not just a friendly empty state).
        abort(403)
    forest = build_hod_forest(u["id"], population)

    def annotate(node):
        released = is_released(db, node["user"]["id"], cid)
        node["released"] = released
        node["band_info"] = subject_band(db, node["user"], cid) if released else None
        for c in node["children"]:
            annotate(c)
    for root in forest:
        annotate(root)
    return render_template("hod_view.html", active_view="hod", flat_rows=flatten_forest(forest))


# ---------------------------------------------------------------------------
# Calibration (Module 1 of the HR platform expansion) -- a cascading 3-level
# workflow against a 15/70/15 Low/Mid/High target: HOD calibrates their
# department and locks, BUCEO rolls up their company from the locked HOD
# outputs and locks, BGCEO does the final Business Group pass. HOD/BUCEO/
# BGCEO are always the SAME employee login (never role='admin'), so these
# routes live under /calibration/, not /admin/ -- see calibration_tier_of(),
# is_hod_of()/is_buceo_of()/is_bgceo_of() (near is_super, above).
# ---------------------------------------------------------------------------
CALIBRATION_TARGET = {"Low": 15, "Mid": 70, "High": 15}

# Short business-unit labels for the BGCEO pill row -- long "... SDN BHD" names
# are unreadable as pills. Keyed by the exact company name; anything not listed
