def _hub_can_reward(db, u):
    """Whether the Reward card has any door this person can actually open.

    A BGCEO decides the merit run; an admin owns the ranges and the matrix
    behind it. Everyone else would get a 403 on every page in the module, and
    a card whose links all refuse is a worse door than no card -- the same
    rule Promotion Nomination and Competency Assessment already follow."""
    if is_admin(u):
        return True
    return any(tier == "bgceo" for tier, _key in calibration_tier_of(db, u))


def _hub_calibration_children(db, u, tiers=None):
    """Only the calibration doors this viewer can actually open.

    A door they can't use is left out entirely rather than listed as
    "Restricted": the Hub is a launcher, and the overwhelming majority of
    staff will never hold a calibration tier, so a permanently-unclickable
    row is noise on every visit rather than information. Returning [] is a
    meaningful answer -- it's what tells the Hub to drop the whole card."""
    only = tiers   # the dashboard passes ("buceo",): an HOD's doors are the Dept Review card's (2026-09-30)
    tiers = calibration_tier_of(db, u)
    # Performance + potential doors for an HOD / BU CEO only: a BG CEO calibrates both on the Talent Box (2026-09-29).
    # a calibrator's calibration group is a BU-level scope (tier 'bugrp', 2026-10-22): it calibrates both axes like a BU CEO
    has_calib = any(("buceo" if t == "bugrp" else t) in (only or _CALIB_AXIS_TIERS) for t, _k in tiers)
    # The box starts at business unit level -- an HOD calibrates the two axes
    # separately on their own pages -- so holding only an 'hod' tier is not a
    # box scope; nor is a calibrator's group (the Talent Box is the BU CEO's and the BG CEO's, 2026-10-27). A Group
    # Chief (pm_calibration_groups) holds no tier at all, hence the OR.
    has_box = any(t not in ("hod", "bugrp") for t, _k in tiers) or bool(db.execute(
        "SELECT 1 FROM pm_calibration_groups WHERE calibrator_id=? LIMIT 1",
        (u["id"],)).fetchone())
    out = []
    if has_calib:
        # Performance first, then potential -- the order the calendar actually
        # runs in (a period's ratings are moderated before the potential read
        # that sits alongside them), and the same order the module tab bar uses.
        _pp = _lead_pm_counts(db, u, tiers=only)
        out.append({
            "name": "Performance Calibration",
            "status": "live",
            "pending_count": _pp["count"], "unlocked": _pp["unlocked"], "window": _pp["window"],
            "url": url_for("pm_calibration_home"),
            "icon_svg": '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">'
                        '<path d="M3 3v18h18M7 14l4-4 3 3 5-6"/></svg>',
        })
        _pp = _lead_pot_counts(db, u, tiers=only)
        out.append({
            "name": "360 Potential Calibration",
            "status": "live",
            "pending_count": _pp["count"], "unlocked": _pp["unlocked"], "window": _pp["window"],
            "url": url_for("calibration_home"),
            "icon_svg": '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">'
                        '<circle cx="12" cy="8" r="4"/><path d="M4 20c0-3.5 3.5-6 8-6s8 2.5 8 6"/></svg>',
        })
    if has_box:
        _pp = _lead_box_counts(db, u)
        out.append({
            # Renamed from "Talent 9-Box": the confirmed design is the full
            # 5x3 grid (15 cells), and the collapsed 9-box view is deferred.
            "name": "Talent Box Calibration",
            "status": "live",
            "pending_count": _pp["count"], "unlocked": _pp["unlocked"], "window": _pp["window"],
            "url": url_for("talent_box_home"),
            "icon_svg": '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">'
                        '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/>'
                        '<rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg>',
        })
    return out


