def _hub_tc_flags(db, u, cycle_id):
    """(has_own, is_manager, awaiting) for the technical competency module.

    has_own / is_manager are the same two questions the module's own nav asks
    (nav_is_tc / nav_is_tc_manager), so the Hub card and the page can't disagree
    about whether someone has an assessment or a team. `awaiting` counts reports
    who have SUBMITTED and not yet been reviewed -- the same definition the Team
    view's own badge uses."""
    if not cycle_id:
        return False, False, 0
    has_own = bool(db.execute(
        "SELECT 1 FROM tc_assignments WHERE cycle_id=? AND subject_id=? LIMIT 1",
        (cycle_id, u["id"])).fetchone())
    mids = _tc_team_mids(db, u["id"])   # not the Executive Chairman's while his Competency tick is off (2026-10-29)
    if not mids:
        return has_own, False, 0
    ph = ",".join("?" * len(mids))
    skip = _tc_chair_unreviewed_sql(db, "r")   # nobody reviews his direct reports then (2026-11-06)
    # ...of reports who take part in the competency review and whose unit the cycle doesn't leave out (2026-10-30)
    gate = " AND NOT %s AND %s" % (unit_out_sql("r"), participant_sql("r", "competency"))
    is_manager = bool(db.execute(
        "SELECT 1 FROM users r WHERE r.manager_id IN (%s) AND r.left_at IS NULL "
        "AND r.role!='admin'%s%s AND EXISTS (SELECT 1 FROM tc_assignments t "
        "  WHERE t.subject_id=r.id AND t.cycle_id=?) LIMIT 1" % (ph, skip, gate),
        mids + [cycle_id]).fetchone())
    awaiting = db.execute(
        "SELECT COUNT(*) c FROM users r JOIN tc_assessments a "
        "  ON a.subject_id = r.id AND a.cycle_id = ? "
        "WHERE r.manager_id IN (%s) AND r.left_at IS NULL AND r.role!='admin'%s%s "
        "  AND a.status='submitted'" % (ph, skip, gate), [cycle_id] + mids).fetchone()["c"]
    return has_own, is_manager, awaiting


def _tc_team_mids(db, uid):
    """The manager ids whose direct reports are this person's competency team: themself, except the Executive Chairman while
    his competency tick is off (2026-10-29). His delegate no longer takes his team over, nobody does (2026-11-06). The Hub
    card and the nav share it (_hub_tc_flags, nav_is_tc_manager) so they never disagree."""
    drop, _extra = _chair_team_adjust(db, uid, "competency")
    return [] if drop else [uid]


def _tc_self_pending(db, u, cycle_id):
    """1 while this person still owes their own self-assessment, else 0 -- the
    Hub badge is 'things waiting on you', not a progress bar."""
    if not cycle_id:
        return 0
    row = db.execute("SELECT status FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                     (cycle_id, u["id"])).fetchone()
    if row and row["status"] in ("submitted", "reviewed"):
        return 1 if tc_added_open(db, u["id"], cycle_id) else 0   # a competency added since is still theirs (2026-11-06)
    return 1


def _hub_can_nominate(db, u):
    """Who may nominate for promotion: anyone with people under them. That is
    a line manager (somebody's manager_id), an HOD (somebody's hod_id), or a
    BUCEO (a stored company scope) -- the same three relationships the rest of
    the app already reads, so this needs no new flag.

    Leavers don't count: you don't nominate someone on their way out.

    A BGCEO is excluded outright, even when they also line-manage somebody:
    they are the one who APPROVES promotions on the promotion page, and the
    same person shouldn't sit on both ends of that decision."""
    if not u or u["role"] == "admin":
        return False
    if u["bgceo_bg"]:
        return False
    if u["buceo_bg"] and u["buceo_company"]:
        return True
    return bool(db.execute(
        "SELECT 1 FROM users WHERE (manager_id=? OR hod_id=?) "
        "AND role!='admin' AND left_at IS NULL LIMIT 1",
        (u["id"], u["id"])).fetchone())




@app.route("/hub/<group_key>")
@login_required
def hub_group(group_key):
    # Retired with the Hub (2026-08-29). Kept as a redirect for old links.
    return redirect(url_for("dashboard"))


# --------------------------------------------------------------------------
# Personal dashboard
#
# The landing page. Every module already knows how to count what it is owed --
# _assessor_pending_count(), _pm_pending_split(), _tc_self_pending() and so on
# feed the Hub's badges. What nobody had was ONE list: the question a person
# actually opens the app with is "what do I owe anyone", and that question does
# not respect module boundaries. So these helpers deliberately call the
# existing counters rather than re-deriving "pending" a second time -- if the
# Hub badge and this list ever disagreed, one of them would be lying.
# --------------------------------------------------------------------------

DASH_SOON_DAYS = 7          # inside a week, a deadline reads as urgent


def _dash_days_left(ends_on):
    """Whole days from today until `ends_on` ('YYYY-MM-DD'), or None when no
    deadline is set. Negative once it has passed -- the page says "overdue"
    rather than hiding it, because a passed deadline is exactly the thing
    somebody needs to see."""
    if not ends_on:
        return None
    try:
        return (date.fromisoformat(str(ends_on)[:10]) - _today_myt()).days
    except ValueError:
        return None


# ---------------------------------------------------------------------------
# The guided review  (Phase C -- the stage engine)
#
# THE CONVERSATION IS A PROJECTION OVER MODULE ROWS. There is no cursor, no
# transcript, and no second definition of "done". Resumption is RE-DERIVATION:
# review_state() runs on every request and lands you where the data says you
# are, so closing the laptop in March and returning in December needs nothing
# stored, and doing half the work on /performance means the next turn simply
# skips those lines. Nothing has to be kept in step because nothing is copied.
#
# AI is OFF in this phase. Every sentence the agent says comes from REVIEW_PHRASES
# below, selected deterministically. Phase D is where a model gets involved.
# ---------------------------------------------------------------------------

# (key, owning module, rail label). ORDER IS CALENDAR ORDER and it is fixed
# rather than sorted, which also repairs a real ordering fault: since the
# pm_periods -> cycles merge, active_cycle() and active_pm_period() run the same
# query, so every deadline-bearing task TIES and dash_tasks()'s sort falls back
# to insertion order -- putting "submit your results" above "agree your targets",
# the reverse of reality.
#
# 'feedback' sits above the employee's own work on purpose: a 360 assessment is
# work OTHER PEOPLE are waiting on, where an unfilled KPI result blocks only you.
#
# The evidence ledger is deliberately NOT a stage. It has no deadline and no
# completion, by design -- it is the rail's footer and a chip inside every other
# stage, never a step in a sequence that could nag.
# (key, module, rail label, endpoint the stage sends you to).
#
# A STAGE EITHER HAS A TURN OR HANDS OFF, and which is which is a deliberate
# call. It shipped with only Account and Check-in conversational, on the argument
# that a form was genuinely worse only for one number and one sentence. Agree,
# Competency and Ahead have since become conversations too, each in its own
# round: what changed the argument is that the agent PROPOSES and the server
# validates, so a chat can carry a whole scorecard or plan without becoming the
# authority on it. Feedback still hands off -- rating a colleague across seven
# principles is a form that works.
#
# In every case the module page STAYS, reachable and unchanged; only the rail
# link moved. "Nothing existing is removed" is still the rule this phase ships
# under, and it is what the Ahead chat falls back to when the assistant is off.
#
# What the rail adds for the handoff stages is what dash_tasks() never had:
# ORDER, a completion state, and the WAITING split -- so the journey is one
# place that knows what is next and how much is left, even where the doing
# happens elsewhere.
# Module short codes for the rail (CYCLE_MODULE_LABELS spell the modules out
# -- "Performance"/"Talent Management"/"Development plans" -- the rail wants the
# codes the business uses).
REVIEW_MODULE_CODE = {"pm": "PM", "tm": "TM", "idp": "IDP"}

# (key, module, group, rail label, endpoint). group 'self' shows for everyone;
# 'team' shows only for a line manager (each team stage carries its module's own
# team predicate in review_state). Order is rail order -- a person's own work
# resumes before their team's.
#
# account and checkin are the SAME rail slot, "PM – KPI Check-in": a period that
# COLLECTS RESULTS (mid-year/year-end) shows `account` (enter the actual +
# rating + evidence); a QUARTERLY period shows `checkin` (trajectory only). Never
# both -- review_state includes exactly one, per pm_period_collects_results().
REVIEW_STAGES = (
    ("agree",         "pm",  "self", "PM – KPI Setting",               "review_setting"),
    ("account",       "pm",  "self", "PM – KPI Check-in",              "review_account"),
    ("checkin",       "pm",  "self", "PM – KPI Check-in",              "review_checkin"),
    ("feedback",      "tm",  "self", "TM – 360 Feedback",              "my_assessments"),
    ("competency",    "tm",  "self", "TM – Competency Assessment",     "review_competency"),
    ("ahead",         "idp", "self", "IDP – Development Self-planning", "review_ahead"),
    ("career",        "idp", "self", "IDP – Career Profiling",         "review_career"),
    ("pm_review",     "pm",  "team", "PM – KPI Review",                "performance_team_view"),
    ("tm_review",     "tm",  "team", "TM – Competency Review",         "technical_team_view"),
    ("plan_review",   "idp", "team", "IDP – Development Plan Review",  "idp_team_view"),
    ("career_review", "idp", "team", "IDP – Career Profile Review",    "idp_team_view"),
)
REVIEW_STAGE_KEYS = tuple(k for k, _m, _g, _l, _e in REVIEW_STAGES)
REVIEW_STAGE_ENDPOINT = {k: e for k, _m, _g, _l, e in REVIEW_STAGES}
REVIEW_STAGE_GROUP = {k: g for k, _m, g, _l, _e in REVIEW_STAGES}
REVIEW_STAGE_LABEL = {k: l for k, _m, _g, l, _e in REVIEW_STAGES}

# All six are live as of step 3, so the rail IS the journey. Kept as a tuple
# rather than deleted: a stage under construction should be absent from the rail,
# never a dead heading, and this is where that is expressed.
REVIEW_STAGES_LIVE = REVIEW_STAGE_KEYS

# Trajectory, not completion -- which is why these are not the IDP's progress
# keys. A KPI check-in asks "where is this heading"; a goal check-in asks "is it
# done". One vocabulary for both would make the two questions look
# interchangeable, and they are not.
PM_CHECKIN_ANSWERS = (
    {"key": "on_track", "label": "On track"},
    {"key": "at_risk", "label": "At risk"},
    {"key": "off_track", "label": "Off track"},
    {"key": "nothing_yet", "label": "Nothing yet"},
)
PM_CHECKIN_KEYS = tuple(x["key"] for x in PM_CHECKIN_ANSWERS)

REVIEW_STATE_OFF = "off"          # module switched off -- absent from the rail
REVIEW_STATE_LATER = "later"      # will open, has not yet
REVIEW_STATE_OPEN = "open"        # outstanding, and it is yours
REVIEW_STATE_WAITING = "waiting"  # outstanding, but on somebody else
REVIEW_STATE_DONE = "done"


def pm_period_collects_results(period):
    """True for the review periods that collect the actual result + rating +
    evidence (mid-year / year-end); False for a quarterly period, which collects
    only a trajectory. The one predicate the PM self-KPI stage branches on --
    never a status literal in review_state. A period with no kind (legacy) is
    treated as a results period, matching the back-fill (half -> mid/year-end)."""
    if not period:
        return True
    kind = (period["kind"] if "kind" in period.keys() else None) or ""
    return kind != "quarterly"


def pm_review_locked(db, subject_id, cid):
    """Has this person CONFIRMED (signed off + locked) their check-in this cycle?
    True if they clicked Confirm (a session row), OR -- for check-ins submitted
    BEFORE this sign-off existed -- if every one of their result rows is already
    submitted (draft=0). Without the legacy clause, an old submitted check-in
    (draft=0, no lock row) would wrongly read as not-done. The one authority for
    'done'; results stay amendable until this is True.
    The legacy clause counts only the EMPLOYEE's own result rows: an HR fill (Fill BU KPI
    writes admin_filled=1, draft=0 onto the subject's row) is never their sign-off. Without
    that, HR filling a BU KPI such as PAT before the person keyed anything left HR's row as
    the only row -- so the whole check-in read as submitted and locked (2026-09-23)."""
    row = db.execute("SELECT locked_at FROM pm_review_session "
                     "WHERE subject_id=? AND cycle_id=?", (subject_id, cid)).fetchone()
    if row and row["locked_at"]:
        return True
    agg = db.execute(
        "SELECT COUNT(*) n, COALESCE(MAX(r.draft), 1) maxd FROM pm_kpi_results r "
        "JOIN pm_kpi_targets t ON t.id=r.kpi_target_id "
        "WHERE t.subject_id=? AND t.cycle_id=? AND COALESCE(r.admin_filled, 0)=0",
        (subject_id, cid)).fetchone()
    return bool(agg and agg["n"] and agg["maxd"] == 0)


# --- A KPI line Group People adds AFTER the person confirmed their check-in (Chris, 2026-11-06: "if we change a person's KPI or
# competency, where a person will need to redo, send an email"; approved scope: only the NEW line opens for them). Nothing is
# stored: the open lines are READ from the rows (pm_added_open_lines), so there is one rule and every reader asks it. A person
# whose check-in is confirmed has their own lines that are entry-open (the KPI setting approved), not BU-level (Group People's
# figure) and with no result or only a draft one (pm_can_self_edit, per line). Those lines, and only those, are writable by
# them (a result, an example, a file) and are submitted by the same Save & submit; their other lines, their submission, their
# overall remark and every approval stay exactly as they were. They may fill them after the Results window has closed
# (_added_pass, a personal pass like a Reopen's), never once their results are out.
def pm_lock_time(db, subject_id, cid):
    """When the person's check-in was confirmed (UTC text, as the database keeps it): the session row's lock, else (a check-in
    confirmed before the sign-off existed) the last of their own results submitted. '' when neither."""
    r = db.execute("SELECT locked_at FROM pm_review_session WHERE subject_id=? AND cycle_id=?", (subject_id, cid)).fetchone()
    if r and r["locked_at"]:
        return r["locked_at"]
    r = db.execute("SELECT MAX(r.submitted_at) FROM pm_kpi_results r JOIN pm_kpi_targets t ON t.id=r.kpi_target_id WHERE "
                   "t.subject_id=? AND t.cycle_id=? AND COALESCE(r.admin_filled,0)=0", (subject_id, cid)).fetchone()
    return (r[0] if r and r[0] else "") or ""


def _pm_line_added_open(t, locked_at):
    """True for one prepared target (attach_pm_chains, bu_level set) that Group People ADDED after the check-in was confirmed
    (the line was made after `locked_at`: a line made before it had to be keyed to confirm) and that is open for entry: not
    BU-level, setting approved, no result or a draft one. A line older than the confirmation never counts, whatever its state."""
    return (not t.get("bu_level")) and (t.get("created_at") or "") > (locked_at or "") and bool(pm_can_self_edit(t))


def pm_added_open_lines(db, subject_id, cid):
    """The person's lines open for them although their check-in is confirmed: [target dict with its chain, result and
    bu_level]. [] when the check-in is not confirmed (the normal rules apply to every line then) or nothing is open."""
    if not cid or not pm_review_locked(db, subject_id, cid):
        return []
    ts = [dict(t) for t in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY " + PM_LINE_ORDER_W,
                                      (cid, subject_id))]
    if not ts:
        return []
    attach_pm_chains(db, ts, include_drafts=True)
    u = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    bu = pm_bu_level_names(db, u, cid) if u else set()
    for t in ts:
        t["bu_level"] = " ".join((t["kpi_name"] or "").lower().split()) in bu
    lt = pm_lock_time(db, subject_id, cid)
    return [t for t in ts if _pm_line_added_open(t, lt)]


def pm_added_open_ids(db, subject_id, cid):
    """The ids of pm_added_open_lines (a set; empty for a person who is not confirmed)."""
    return {t["id"] for t in pm_added_open_lines(db, subject_id, cid)}


def pm_account_done(db, subject_id, cid, own_lines=None):
    """Is the KPI check-in DONE for the person: confirmed (pm_review_locked) AND no line added since still open for them.
    The one answer review_state's KPI part, the navigator, the sign-off pop-up and the journey card read. `own_lines`: the
    person's prepared own lines when the caller has them (review_state), to save a read."""
    if not pm_review_locked(db, subject_id, cid):
        return False
    if own_lines is not None:
        lt = pm_lock_time(db, subject_id, cid)
        return not any(_pm_line_added_open(t, lt) for t in own_lines)
    return not pm_added_open_lines(db, subject_id, cid)


def pm_locked_line_refusal(db, subject_id, cid, kpi_id=None):
    """None when this write on the person's own KPI line is allowed by the confirmed-check-in rule, else the plain sentence:
    nothing once confirmed except a line added since that is still open (`kpi_id` in pm_added_open_ids). A write that belongs
    to no line (the overall remark) passes kpi_id None and is refused for a confirmed check-in, whatever is open."""
    if not pm_review_locked(db, subject_id, cid):
        return None
    if kpi_id is not None and kpi_id in pm_added_open_ids(db, subject_id, cid):
        return None
    return PM_LOCKED_SAYS


PM_LOCKED_SAYS = ("Your check-in is submitted, so this can't be changed. Only a KPI that Group People added after you "
                  "submitted is open for you.")


def pm_career_is_complete(db, subject_id):
    """A career profile counts as done once the person has picked a mobility and
    stated at least one aspiration horizon -- the fields HR reads for succession.
    A living document, so this is the review stage's completion predicate (the
    IDP module owning the rule, not review_state)."""
    row = db.execute("SELECT mobility, aspiration_now, aspiration_mid, aspiration_long "
                     "FROM pm_career_profile WHERE subject_id=?", (subject_id,)).fetchone()
    if not row:
        return False
    return bool((row["mobility"] or "").strip()) and any(
        (row[k] or "").strip() for k in ("aspiration_now", "aspiration_mid", "aspiration_long"))


def review_stage_module(key):
    """The module a stage belongs to. One lookup, so the rail, the route gate
    and the tests cannot disagree about who owns a stage."""
    return next((m for k, m, _g, _l, _e in REVIEW_STAGES if k == key), None)


# a person's own review parts and the user-role module each needs (team parts follow seats, never a user role)
_REVIEW_UROLE_STAGE = {"agree": "pm", "account": "pm", "checkin": "pm", "competency": "competency",
                       "feedback": "tm_rate", "ahead": "idp", "career": "idp"}


def review_state(db, u):
    """Everything the conversation needs, DERIVED. Nothing here is stored and
    nothing is cached across a request.

    THE RULE THE WHOLE DESIGN RESTS ON: this function may not decide whether
    anything is done. It CALLS the module's own predicate -- pm_can_self_edit(),
    pm_result_entry_open(), cycle_module_on() -- on the module's own rows. A
    literal status string in here would be a SECOND DEFINITION OF DONE, which is
    the one way this surface could start disagreeing with the pages it projects.
    tests/test_review.py lints for exactly that, so if a stage ever seems to need
    one, the signal is that its module should expose a predicate instead.

    Returns {"stages": [...], "period": row|None, "targets": [...]}, where each
    stage carries {key, module, label, state, n_open, n_total, blocked_on}.
    """
    period = active_pm_period(db)
    cid = period["id"] if period else None
    # a BG CEO's own KPI / competency / plan aren't asked of them here (2026-10-05: no Mine for a BG CEO)
    out = {"period": period, "targets": [], "stages": [],
           "participant": _review_participant(u) and not _review_bg_leader(db, u),
           # the Career Plan reaches everyone active at the minimum grade, confirmed or not (2026-10-19)
           "idp_participant": _review_idp_participant(u) and not _review_bg_leader(db, u)}

    # The employee's own KPI lines, prepared EXACTLY as performance_my_view()
    # prepares them -- same helpers, same order, same include_drafts=True -- so
    # the two surfaces cannot produce different numbers for the same person.
    targets = []
    if cid:
        targets = [dict(t) for t in db.execute(
            "SELECT t.* FROM pm_kpi_targets t WHERE t.cycle_id=? AND t.subject_id=? "
            "ORDER BY " + PM_LINE_ORDER_TW, (cid, u["id"])).fetchall()]
        if targets:
            attach_pm_chains(db, targets, include_drafts=True)
            bu_names = pm_bu_level_names(db, u, cid)
            for t in targets:
                # A BU-level line is HR's figure to enter. Read-only here for the
                # same reason performance_my_view() and performance_kpi_submit_all()
                # drop it: the conversation must never ask somebody for a number
                # they have no way of knowing, and then block them on it.
                t["bu_level"] = " ".join((t["kpi_name"] or "").lower().split()) in bu_names
                t["can_edit"] = (pm_can_self_edit(t) and not t["bu_level"]
                                 and pm_result_entry_open(t))
                # EDITABLE IS NOT UNANSWERED, and conflating them stalls the
                # whole conversation. pm_can_self_edit() stays True for a saved
                # DRAFT -- correctly, because the module lets you change it --
                # so "first editable line" is satisfied by the line you just
                # answered, and the turn asks the same question forever.
                # What the conversation needs is the first line with no FIGURE.
                t["has_value"] = bool(t["result"]
                                      and t["result"]["actual_value"] is not None)
                t["needs_figure"] = t["can_edit"] and not t["has_value"]
            pm_score_targets(db, targets)
    out["targets"] = targets

    # Which stages this viewer sees, in rail order. The PM self-KPI slot is
    # ONE rail item: a results period (mid-year/year-end) shows `account`
    # (enter the actual), a quarterly period shows `checkin` (trajectory). Team
    # stages appear only when the module's own team predicate holds.
    results_period = pm_period_collects_results(period)
    ef = (_pm_entry_flags(db, u, cid) if cid
          else {"approver": False, "setting_review": False})
    split = (_pm_pending_split(db, u, cid) if cid
             else {"team_pending": 0, "setting_review_pending": 0})
    _tc_has, tc_is_mgr, tc_awaiting = (_hub_tc_flags(db, u, cid) if cid
                                       else (False, False, 0))
    active = ["agree", "account" if results_period else "checkin",
              "feedback", "competency", "ahead", "career"]
    if ef.get("pm_team") or ef.get("setting_review"):   # the KPI team: reports who take part in Performance (2026-10-30)
        active.append("pm_review")
    if tc_is_mgr:
        active.append("tm_review")
    if ef.get("approver") or (cid and _idp_lm_has_plans(db, u)):   # a line manager reviews their people's plans
        active += ["plan_review", "career_review"]
    if cycle_row_is_early_year(period):
        # the Early Year is KPI setting and its approval, nothing else (2026-10-15)
        active = [k for k in active if k in ("agree", "pm_review")]
    else:
        # ...and only it: the Year-End's KPI setting is retired (Chris, 2026-10-15)
        active = [k for k in active if k != "agree"]

    # what their user role opens (Roles & access, 2026-10-20): a part it doesn't is off for them, as a module switched off
    own_mods = urole_modules_of(u, db)
    for key in active:
        module = review_stage_module(key)
        label = REVIEW_STAGE_LABEL[key]
        group = REVIEW_STAGE_GROUP[key]
        bu_only = False
        if not cycle_module_on(module, db, cid) or (key in _REVIEW_UROLE_STAGE
                                                    and _REVIEW_UROLE_STAGE[key] not in own_mods):
            state, n_open, n_total, blocked = REVIEW_STATE_OFF, 0, 0, None
        elif key == "account":
            mine = [t for t in targets if not t["bu_level"]]
            # every line a BU KPI Group People fills (2026-10-26): nothing of theirs to key or submit, so the part
            # stays 'later' with nothing in it, and bu_only says why (an optional note, never "not required")
            bu_only = bool(period and targets and not mine)
            n_total = len(mine)
            n_open = len([t for t in mine if t["needs_figure"]])
            blocked = None
            # DONE only once the employee has CONFIRMED (locked) their check-in.
            # All-keyed-but-unconfirmed is still OPEN -- the remaining action is the
            # confirm/sign-off, not keying -- so the rail dot stays amber until then.
            # ...and a line Group People added after they confirmed re-opens it for that line alone (pm_account_done)
            if not period or not n_total:
                state = REVIEW_STATE_LATER
            elif pm_account_done(db, u["id"], cid, mine):
                state = REVIEW_STATE_DONE
            else:
                state = REVIEW_STATE_OPEN
        elif key == "checkin":
            # Every approved line has to have been ASKED about. "Nothing yet" is
            # a complete answer, which is why this counts rows that EXIST rather
            # than rows with any particular answer.
            mine = [t for t in targets if not t["bu_level"]]
            n_total = len(mine)
            asked = {r["kpi_target_id"] for r in db.execute(
                "SELECT kpi_target_id FROM pm_checkins WHERE kpi_target_id IN (%s)"
                % ",".join("?" * len(mine)), [t["id"] for t in mine])} if mine else set()
            n_open = len([t for t in mine if t["id"] not in asked])
            blocked = None
            state = (REVIEW_STATE_LATER if not period or not n_total
                     else REVIEW_STATE_OPEN if n_open else REVIEW_STATE_DONE)
        elif key == "agree":
            # THE WAITING SPLIT, and the reason this stage needed its own branch.
            # 'proposed' is the employee's row but the APPROVER's move, so
            # counting it as their work asks them forever to finish something
            # they cannot. Both predicates live in Performance, not here.
            st_, n_prop, approved_n, waiting_on = pm_setting_stage(db, u, cid)
            n_total = n_prop + approved_n
            if not period:
                state, n_open, blocked = REVIEW_STATE_LATER, 0, None
            elif pm_setting_is_waiting(st_):
                state, n_open, blocked = REVIEW_STATE_WAITING, n_prop, waiting_on
            elif pm_setting_is_open(st_, approved_n):
                state, n_open, blocked = REVIEW_STATE_OPEN, max(n_prop, 1), None
            else:
                state, n_open, blocked = REVIEW_STATE_DONE, 0, None
        elif key == "feedback":
            # Work OTHER PEOPLE are waiting on, which is why it sits above the
            # employee's own in the rail.
            n_open = _assessor_pending_count(db, u)
            n_total = db.execute(
                "SELECT COUNT(*) FROM assignments WHERE assessor_id=? AND cycle_id=? "
                "AND archived=0 AND " + rater_task_sql("assignments"), (u["id"], cid)).fetchone()[0] if cid else 0
            blocked = None
            state = (REVIEW_STATE_LATER if not n_total
                     else REVIEW_STATE_OPEN if n_open else REVIEW_STATE_DONE)
        elif key == "competency":
            n_total = db.execute(
                "SELECT COUNT(*) FROM tc_assignments WHERE cycle_id=? AND subject_id=?",
                (cid, u["id"])).fetchone()[0] if cid else 0
            n_open = _tc_self_pending(db, u, cid) if n_total else 0
            blocked = None
            state = (REVIEW_STATE_LATER if not n_total
                     else REVIEW_STATE_OPEN if n_open else REVIEW_STATE_DONE)
        elif key == "ahead":
            # A plan is written once a year, at Year-End, for the year ahead --
            # so outside the authoring period this is LATER, not overdue.
            authoring = pm_idp_is_authoring(period)
            yr = pm_idp_plan_year(period)
            idp = db.execute("SELECT * FROM pm_idp WHERE plan_year=? AND subject_id=?",
                             (yr, u["id"])).fetchone() if yr else None
            idp = dict(idp) if idp else None
            n_total, blocked = 1, None
            if not authoring:
                state, n_open = REVIEW_STATE_LATER, 0
            elif pm_idp_is_shared(idp):
                state, n_open = REVIEW_STATE_DONE, 0
            else:
                state, n_open = REVIEW_STATE_OPEN, 1
        elif key == "career":
            # A living profile, authored during a review period. Complete once a
            # mobility choice and one aspiration horizon are set (the IDP module
            # owns that rule via pm_career_is_complete).
            n_total, blocked = 1, None
            if not period:
                state, n_open = REVIEW_STATE_LATER, 0
            elif pm_career_is_complete(db, u["id"]):
                state, n_open = REVIEW_STATE_DONE, 0
            else:
                state, n_open = REVIEW_STATE_OPEN, 1
        elif key == "pm_review":
            # A line-manager handoff to the team KPI page. OPEN while there is
            # team work waiting (results to moderate or proposals to approve).
            pend = split.get("team_pending", 0) + split.get("setting_review_pending", 0)
            n_total = n_open = pend
            blocked = None
            state = REVIEW_STATE_OPEN if pend else REVIEW_STATE_DONE
        elif key == "tm_review":
            n_total = n_open = tc_awaiting
            blocked = None
            state = REVIEW_STATE_OPEN if tc_awaiting else REVIEW_STATE_DONE
        elif key in ("plan_review", "career_review"):
            # Handoff doors to the IDP team page -- no per-item pending count, so
            # they are available (DONE, non-nagging) rather than OPEN; the rail
            # renders a team door without a caption.
            state, n_open, n_total, blocked = REVIEW_STATE_DONE, 0, 0, None
        else:                                   # pragma: no cover
            state, n_open, n_total, blocked = REVIEW_STATE_LATER, 0, 0, None
        out["stages"].append({
            "key": key, "module": module, "label": label, "state": state,
            # The label with the "PM – " / "TM – " / "IDP – " prefix dropped, so
            # the rail can group under a module heading without restating it in
            # every row. Split on the en-dash separator the labels all use.
            "short": label.split(" – ", 1)[-1],
            "group": group,
            "n_open": n_open, "n_total": n_total, "blocked_on": blocked,
            "endpoint": REVIEW_STAGE_ENDPOINT[key],
            "bu_only": bu_only,
        })
    return out


def review_resume(state):
    """Which stage the person lands on. First OPEN, then first WAITING, else
    None -- meaning nothing is waiting and /review/done is the answer."""
    for want in (REVIEW_STATE_OPEN, REVIEW_STATE_WAITING):
        for st in state["stages"]:
            if st["state"] == want:
                return st["key"]
    return None


_REVIEW_OWN_KEYS = ("agree", "account", "checkin", "competency", "ahead", "career")   # the person's OWN parts


def dash_review_summary(db, u):
    """The dashboard's chat-entry projection -- what the "Your review" card shows
    and links to. Returns None when the chat is NOT the to-do surface (an admin,
    no active cycle, or the review phase switched off), and the dashboard then
    falls back to the dash_tasks() "Needs you" list.

    It never re-derives stage state: it CALLS review_state()/review_resume() and
    only counts what they return, so the card and the /review rail can never
    disagree. Safe for managers and leavers -- review_state reads only this
    person's own rows and handles period=None."""
    if is_admin(u) or not active_cycle(db) or not cycle_module_on("review", db):
        return None
    st = review_state(db, u)
    # The dashboard card is about the person's OWN review; team-review handoffs
    # live in the Leadership zone, so the mini-rail and its counts are self only.
    # Someone not taking part this cycle (not confirmed before it opened, and not added -- 2026-10-02) has no own
    # KPI / competency / IDP parts; a 360 they were asked to give on a colleague stays.
    own = st.get("participant", True)
    idp_own = _st_idp_own(st)   # ...but the Career Plan is everyone's (2026-10-19)
    live = [x for x in st["stages"]
            if x["state"] != REVIEW_STATE_OFF and x.get("group") == "self"
            and (own or (x["key"] not in _REVIEW_OWN_KEYS and x.get("n_total"))
                 or (idp_own and x["key"] in ("ahead", "career")))]
    resume = review_resume(st) if own else next(
        (x["key"] for x in live if x["state"] == REVIEW_STATE_OPEN), None)
    label = next((x["label"] for x in live if x["key"] == resume), None)
    return {
        "stages": live,
        "resume": resume, "resume_label": label,
        "all_done": resume is None,
        "not_required": (not own) and not live,
        "open": sum(1 for x in live if x["state"] == REVIEW_STATE_OPEN),
        "waiting": sum(1 for x in live if x["state"] == REVIEW_STATE_WAITING),
        "done": sum(1 for x in live if x["state"] == REVIEW_STATE_DONE),
        "total": len(live),
        "url": url_for("review_home"),
        "period": st["period"],
        "st": st,   # the state it read: the dashboard's Your review panel and Your team card reuse it (2026-10-08)
    }


def review_next_target(state):
    """The KPI line the Account stage is ASKING ABOUT -- the first one still
    editable, in weightage order. Not "the next question after the last one":
    the question the RECORD says is missing, which is what makes this resume
    correctly rather than behave like a wizard with a counter."""
    return next((t for t in state["targets"] if t["needs_figure"]), None)


def review_pick_target(state, target_id):
    """A KPI the person chose on the overview widget, validated as one of their
    OWN lines that still needs a figure. A crafted/foreign id returns None, so
    the picker can never open somebody else's line."""
    if not target_id:
        return None
    return next((t for t in state["targets"]
                 if t["id"] == target_id and t.get("needs_figure")), None)


def _review_kpi_cited(db, subject_id, kpi_id):
    """True if this person already has a shared evidence item cited to this KPI."""
    return db.execute(
        "SELECT 1 FROM pm_evidence e JOIN pm_evidence_links l ON l.evidence_id=e.id "
        "WHERE e.subject_id=? AND e.state='shared' AND l.target_kind='kpi' "
        "AND l.target_ref=? LIMIT 1", (subject_id, str(kpi_id))).fetchone() is not None


def review_strong_prompt(db, u, state, target_id):
    """After a save, the just-keyed line IF it scored strongly (AE/OU) and has no
    evidence cited yet -- the cue to ask for a compliment / justification. The
    band comparison lives HERE, never in review_state (which is lint-forbidden a
    status literal). Returns the target dict (with a friendly score name) or None."""
    if not target_id or not cycle_module_on("evidence"):
        return None
    t = next((x for x in state["targets"] if x["id"] == target_id), None)
    if not t or not t.get("has_value"):
        return None
    sc = t.get("score") or {}
    if sc.get("label") not in ("AE", "OU"):
        return None
    if _review_kpi_cited(db, u["id"], t["id"]):
        return None
    out = dict(t)
    out["score_name"] = PM_LABEL_NAMES.get(sc.get("label"), sc.get("label"))
    return out


def review_overall_examples_pending(db, u, overall):
    """When the account stage is done and the overall SELF-rating is AE/OU and no
    overall example has been recorded yet, the cue to ask for specifics. The
    example is a shared 'recognition' evidence item not tied to one KPI."""
    if not overall or overall.get("label") not in ("AE", "OU"):
        return None
    if not cycle_module_on("evidence"):
        return None
    seen = db.execute(
        "SELECT 1 FROM pm_evidence e WHERE e.subject_id=? AND e.state='shared' "
        "AND e.kind='recognition' AND NOT EXISTS(SELECT 1 FROM pm_evidence_links l "
        "WHERE l.evidence_id=e.id) LIMIT 1", (u["id"],)).fetchone()
    if seen:
        return None
    out = dict(overall)
    out["score_name"] = PM_LABEL_NAMES.get(overall.get("label"), overall.get("label"))
    return out


def review_acknowledge(state, target_id):
    """The "Saved ..." line for a line just keyed, or None.

    The CLIENT says WHICH line it saved; the SERVER says what the number means.
    That split is the whole point: no percentage and no score is ever computed
    in the browser, because a second scoring implementation there would be a
    second source of truth about the figure -- the same failure as a second
    source of truth about "done". The value and its band come straight off
    pm_score_targets(), which has already run."""
    if not target_id:
        return None
    t = next((x for x in state["targets"] if x["id"] == target_id), None)
    if not t or not t.get("has_value"):
        return None
    val = t["result"]["actual_value"]
    unit = (" " + t["unit"]) if t.get("unit") else ""
    sc = t.get("score")
    if not sc or sc.get("value") is None:
        return review_phrase("account.saved", value=_commas(val), unit=unit)
    shape = ("%.0f%%" % sc["value"]) if sc["mechanism"] == "B" else ("%.1f of 5" % sc["value"])
    return review_phrase("account.saved_scored", value=_commas(val), unit=unit,
                         pct=shape, score=sc.get("label") or "no band yet")


# THE AI'S ENTIRE VIEW OF A PERSON, and it is deliberately narrow. Both builders
# read ONE subject's own rows -- evidence_list() is already WHERE subject_id=?
# and joins no assessor, and the KPI notes come from that subject's own targets.
# No assessor identity, no other person's ledger, ever. The guarantee lives here,
# in plain SELECTs a lint can read, rather than in a prompt string. Phase D adds
# NO WRITER: these feed a render, and the only thing written is the human's own
# confirmation through /evidence/<id>/link.
def _review_ai_items(db, subject_id):
    """(n, text) for each of this subject's own SHARED evidence items, numbered
    for citation. Newest-happened first, matching evidence_list()."""
    rows = evidence_list(db, subject_id, include_drafts=False)
    out = []
    for i, r in enumerate(rows, 1):
        body = (r["body"] or "").strip()
        title = (r["title"] or "").strip()
        text = ("%s -- %s" % (title, body)) if title and body else (title or body)
        out.append((i, text, r["id"]))
    return out


def _review_ai_kpi_notes(db, subject_id, cycle_id):
    """This subject's own KPI result notes -- their words, not a score."""
    if not cycle_id:
        return []
    return [r["note"] for r in db.execute(
        "SELECT r.note FROM pm_kpi_results r JOIN pm_kpi_targets t ON t.id=r.kpi_target_id "
        "WHERE t.cycle_id=? AND t.subject_id=? AND TRIM(COALESCE(r.note,''))<>''",
        (cycle_id, subject_id)).fetchall()]


def _review_cite_data(db, u, targets):
    """For the cite turn: each of the person's own KPI lines, with their SHARED
    evidence items and which are already linked to that line. Deterministic --
    no model -- so the cite turn renders instantly and works with the AI off.
    The pre-tick fetch decorates this; it does not produce it."""
    items = [{"eid": eid, "n": n, "text": text}
             for n, text, eid in _review_ai_items(db, u["id"])]
    if not items:
        return []
    linked = {}
    for r in db.execute(
            "SELECT l.evidence_id, l.target_ref FROM pm_evidence_links l "
            "JOIN pm_evidence e ON e.id=l.evidence_id "
            "WHERE e.subject_id=? AND l.target_kind='kpi'", (u["id"],)):
        linked.setdefault(r["target_ref"], set()).add(r["evidence_id"])
    out = []
    for t in targets:
        if t["bu_level"]:
            continue
        on = linked.get(str(t["id"]), set())
        out.append({"kpi_id": t["id"], "kpi_name": t["kpi_name"],
                    "items": [dict(it, linked=(it["eid"] in on)) for it in items]})
    return out


def review_partial_overall(db, targets):
    """(overall|None, weight_covered, weight_total) -- never a bare figure.

    pm_overall_for_targets(require_locked=False) excludes unscored lines, so a
    3.4 over 75% of the weight is a number over three-quarters of a scorecard.
    Returning the coverage alongside it means a template CANNOT print the score
    without saying what it covers. Same rule as Reward's "partial -- 47 of 94
    priced", and the fourth place in this product where presenting a partial
    total as a total would be the dangerous mistake."""
    if not targets:
        return None, 0.0, 0.0
    total = sum((t["weightage"] or 0) for t in targets)
    covered = sum((t["weightage"] or 0) for t in targets if t.get("score"))
    return pm_overall_for_targets(db, targets, require_locked=False), covered, total


# The fixed phrasebook. KEYED, never a rendered sentence: Phase E adds Malay as a
# second dict rather than a migration, and a test can assert the exact key rather
# than matching prose. Selection is deterministic -- no randomness anywhere --
# so a path-walking test can assert which turn comes next.
REVIEW_PHRASES = {
    "account.ask": "What did {kpi} come in at?",
    "account.ask_first": "Let's go through your results. What did {kpi} come in at?",
    "account.saved": "Saved {value}{unit}.",
    "account.saved_scored": "Saved {value}{unit} \u2014 that is {pct}, landing on {score}.",
    "account.bu_level": "{kpi} is filled in by Group People, so it is not yours to key.",
    "account.done": "That is every result keyed.",
    "account.none": "You have no KPI lines this period yet.",
    "checkin.ask": "Where is {kpi} heading?",
    "checkin.done": "That is every line checked in on.",
    "checkin.none": "You have no KPI lines to check in on yet.",
    "account.overview": "Here are your KPIs for {period}. Which would you like to start with?",
    "account.overview_more": "Which KPI next?",
    "account.strong_prompt": "You landed on {score} for {kpi}. Anything you\u2019d like to add \u2014 an example or a note strengthens the record.",
    "account.saved_note": "Added to your record.",
    "account.overall_examples": "Overall you are at {score} \u2014 a strong self-rating. A couple of specific examples will help it stand up in calibration.",
}


def review_phrase(key, **args):
    """One sentence from the phrasebook. No db, no request, no session -- the
    purity is what makes the path-walking tests cheap enough to actually write."""
    return REVIEW_PHRASES[key].format(**args)


# Which module owns each task, so a switched-off one stops being offered.
#
# dash_tasks() called cycle_module_on() ZERO times until 2026-08-28. With `pm`
# off an employee was still told "Submit your KPI results, 3 of 6 filled in"
# over a link that answers errors/module_off.html and a 404 -- the module gate
# (f72c126) closed the door and left the sign up. It matters more now than it
# did: Phase C's conversation is DRIVEN by this aggregator, so an unfiltered
# task becomes a dead conversational STAGE rather than a dead link.
#
# A MAP rather than a guard per block, for the same reason module_of_request()
# is a map: it can be asserted over. tests/test_review_repairs.py requires every
# key _dash_task() can emit to appear here, so a task nobody classified fails
# the suite instead of shipping ungated.
DASH_TASK_MODULE = {
    "360": "tm",            # the 360's own surfaces are tm (MODULE_ENDPOINTS)
    "tc": "tm", "tc_team": "tm", "talent_box": "tm",
    "kpi": "pm", "kpi_set": "pm", "kpi_team": "pm", "kpi_setting": "pm",
    "idp": "idp",
    "calib_pot": "calibration", "calib_perf": "calibration",
}


def _dash_task(key, title, subtitle, url, action, icon,
               done=0, total=0, ends_on=None):
    """One row of "Needs you". `done`/`total` drive the segment bar, so they
    are the same numbers the subtitle states -- a count you read and a shape
    you don't have to."""
    days = _dash_days_left(ends_on)
    return {
        "key": key, "title": title, "subtitle": subtitle,
        "url": url, "action": action, "icon": icon,
        "done": done, "total": total, "days": days,
        "urgency": ("soon" if days is not None and days <= DASH_SOON_DAYS
                    else ("later" if days is not None else "none")),
    }


def dash_tasks(db, u):
    """Everything waiting on this person right now, across every module,
    ordered by how soon it is due (no-deadline items last).

    Each entry is built from the module's own pending counter, so this list
    can never claim work the module itself doesn't show."""
    tasks = []

    cyc = active_cycle(db)
    cid = cyc["id"] if cyc else None
    cyc_ends = cyc["ends_on"] if cyc else None

    # -- 360 feedback ------------------------------------------------------
    if cid and active_cycle_is_open(db):
        pending = _assessor_pending_count(db, u)
        if pending:
            total = db.execute(
                "SELECT COUNT(*) FROM assignments WHERE assessor_id=? AND cycle_id=? "
                "AND archived=0 AND " + rater_task_sql("assignments"), (u["id"], cid)).fetchone()[0]
            tasks.append(_dash_task(
                "360", "Give 360 feedback",
                "%d of %d colleagues done" % (total - pending, total),
                url_for("my_assessments"), "Continue", _HUB_ICON_TEAM,
                done=total - pending, total=total, ends_on=cyc_ends))

    # -- technical competency ---------------------------------------------
    has_tc, is_tc_manager, tc_awaiting = _hub_tc_flags(db, u, cid)
    if has_tc and _tc_self_pending(db, u, cid):
        tasks.append(_dash_task(
            "tc", "Complete your competency self-assessment",
            "Rate yourself against your role's technical competencies",
            url_for("technical_my_view"), "Open", _HUB_ICON_TC,
            ends_on=cyc_ends))
    if is_tc_manager and tc_awaiting:
        tasks.append(_dash_task(
            "tc_team", "Review your team's competency assessments",
            "%d submitted, waiting on you" % tc_awaiting,
            url_for("technical_team_view"), "Review", _HUB_ICON_CHECK,
            done=0, total=tc_awaiting, ends_on=cyc_ends))

    # -- performance -------------------------------------------------------
    period = active_pm_period(db)
    pid = period["id"] if period else None
    if pid:
        pm_ends = period["ends_on"]
        split = _pm_pending_split(db, u, pid)
        own_total = _pm_own_counts(db, u["id"], pid)[0]   # their own lines, not the BU KPIs Group People fills
        if split["my_pending"]:
            tasks.append(_dash_task(
                "kpi", "Submit your KPI results",
                "%d of %d filled in" % (own_total - split["my_pending"], own_total),
                url_for("performance_my_view"), "Open", _HUB_ICON_TARGET,
                done=own_total - split["my_pending"], total=own_total, ends_on=pm_ends))
        own_open = db.execute(
            "SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
            "AND status IN ('draft','proposed','returned')", (pid, u["id"])).fetchone()[0]
        setting_runs = kpi_setting_runs(db.execute("SELECT * FROM cycles WHERE id=?", (pid,)).fetchone())
        if own_open and setting_runs:
            returned = db.execute(
                "SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
                "AND status='returned'", (pid, u["id"])).fetchone()[0]
            tasks.append(_dash_task(
                "kpi_set", "Finish setting your KPIs",
                ("%d sent back for revision" % returned) if returned
                else "%d still to agree with your manager" % own_open,
                url_for("performance_kpi_setting_view"), "Open", _HUB_ICON_TARGET,
                total=own_open, ends_on=pm_ends))
        if split["team_pending"]:
            team_total = db.execute(
                "SELECT COUNT(DISTINCT t.subject_id) FROM pm_kpi_target_approvers a "
                "CROSS JOIN pm_kpi_targets t ON t.id = a.kpi_target_id CROSS JOIN users su ON su.id = t.subject_id "
                "WHERE t.cycle_id=? AND a.approver_id=? AND " + participant_sql("su", "pm"),
                (pid, u["id"])).fetchone()[0]
            tasks.append(_dash_task(
                "kpi_team", "Review your team's KPI results",
                "%d of %d direct reports waiting on you"
                % (split["team_pending"], team_total),
                url_for("performance_team_view"), "Review", _HUB_ICON_TEAM,
                done=team_total - split["team_pending"], total=team_total,
                ends_on=pm_ends))
        if split.get("setting_review_pending") and setting_runs:
            tasks.append(_dash_task(
                "kpi_setting", "Approve your team's proposed KPIs",
                "%d waiting on you" % split["setting_review_pending"],
                url_for("performance_kpi_setting_review"), "Review", _HUB_ICON_CHECK,
                total=split["setting_review_pending"], ends_on=pm_ends))

        # -- development plan ---------------------------------------------
        # No deadline of its own: the IDP is a conversation, not a filing.
        # It still belongs in the list -- an unfinished plan is real work --
        # so it sorts last rather than borrowing the period's date.
        idp = pm_idp_for(db, pm_idp_plan_year(period), u["id"])
        # Only nag about writing a plan during the period plans are written in
        # (Year-End). Mid-Year is for checking in on the plan already agreed,
        # so an unfinished one isn't work waiting on you then.
        if idp and pm_idp_can_edit(idp, pm_idp_is_authoring(period)):
            goals = idp["goals"]
            if not goals:
                tasks.append(_dash_task(
                    "idp", "Start your development plan",
                    "Nothing added yet",
                    url_for("idp_view"), "Open", _HUB_ICON_PERSON))
            else:
                bare = [g for g in goals if not (g["action_experience"]
                                                 or g["action_exposure"]
                                                 or g["action_education"])]
                if bare:
                    tasks.append(_dash_task(
                        "idp", "Finish your development plan",
                        "%d of %d goals have no actions yet" % (len(bare), len(goals)),
                        url_for("idp_view"), "Open", _HUB_ICON_PERSON,
                        done=len(goals) - len(bare), total=len(goals)))

    # Leadership work. Without this the function's own docstring was false: it
    # built tasks from 360, technical competency, PM and IDP only, so a BG CEO
    # holding the final calibration pass for 111 people opened the page the app
    # sends them to and was told, in a green tick, that nothing was waiting.
    # These reuse the module's own counters, so a task cannot claim work the
    # module itself does not show -- the property the docstring promises.
    for _key, _n, _title, _detail, _url, _icon in (
            ("calib_pot", _calibration_pending_count(db, u),
             "Calibrate potential bands",
             "scope", url_for("calibration_home"), _HUB_ICON_CHART),
            ("calib_perf", _pm_calibration_pending_count(db, u),
             "Calibrate performance ratings",
             "scope", url_for("pm_calibration_home"), _HUB_ICON_CHART),
            ("talent_box", _talent_box_pending_count(db, u),
             "Review the talent box",
             "scope", url_for("talent_box_home"), _HUB_ICON_BOLT)):
        if _n:
            tasks.append(_dash_task(
                _key, _title,
                "%d %s awaiting your lock" % (_n, _detail if _n == 1 else _detail + "s"),
                _url, "Open", _icon, total=_n))

    # Drop anything whose module this cycle has switched off. An UNMAPPED key is
    # KEPT, deliberately: never hide work because somebody forgot to classify it.
    # The suite is what stops a key going unclassified, not this line.
    tasks = [t for t in tasks
             if t["key"] not in DASH_TASK_MODULE
             or cycle_module_on(DASH_TASK_MODULE[t["key"]], db, cid)]

    # Soonest first; anything without a deadline sinks to the bottom rather
    # than jumping the queue on an arbitrary tie.
    tasks.sort(key=lambda t: (t["days"] is None, t["days"] if t["days"] is not None else 0))
    return tasks


def dash_team(db, u, pid):
    """The manager strip: counts and a link, never a table. Somebody with
    reports otherwise gets two products stacked on one page, and the team
    pages already do that job properly."""
    if not pid:
        return None
    reports = db.execute(
        "SELECT COUNT(DISTINCT t.subject_id) c FROM pm_kpi_target_approvers a "
        "CROSS JOIN pm_kpi_targets t ON t.id = a.kpi_target_id CROSS JOIN users su ON su.id = t.subject_id "
        "WHERE t.cycle_id=? AND a.approver_id=? AND " + participant_sql("su", "pm"),   # who takes part (2026-10-30)
        (pid, u["id"])).fetchone()["c"]
    if not reports:
        return None
    split = _pm_pending_split(db, u, pid)
    not_submitted = db.execute(
        "SELECT COUNT(DISTINCT t.subject_id) c FROM pm_kpi_target_approvers a "
        "CROSS JOIN pm_kpi_targets t ON t.id = a.kpi_target_id CROSS JOIN users su ON su.id = t.subject_id "
        "WHERE t.cycle_id=? AND a.approver_id=? AND " + participant_sql("su", "pm") + " "
        "AND NOT EXISTS (SELECT 1 FROM pm_kpi_results r "
        "                WHERE r.kpi_target_id=t.id AND r.draft=0)",
        (pid, u["id"])).fetchone()["c"]
    return {"reports": reports, "awaiting": split["team_pending"],
            "not_submitted": not_submitted,
            "url": url_for("performance_team_view")}


# The Leadership doors the retired Hub carried, plus the manager team doors, as
# a flat list for the dashboard's Leadership zone. Empty list => the zone is
# hidden (the same signal the Hub used to drop its Leadership section).
_DASH_DOOR_ARROW = ('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" '
                    'stroke-width="2"><path d="M9 6l6 6-6 6"/></svg>')


def dash_leadership(db, u):
    """Every leadership / manager door this person actually holds, each built
    from its OWN predicate AND gated on its route's OWN module -- so a visible
    door can never 403 and a badge can never disagree with the page it opens.
    Reuses the module predicates and pending counters rather than re-deriving
    them, exactly as dash_tasks() and the Hub did."""
    if is_admin(u):
        return []
    cid = active_cycle_id(db)
    pmpid = active_pm_period_id(db)
    tiers = calibration_tier_of(db, u)
    doors = []

    # Calibration / potential / talent box -- reuse the Hub's own builder, which
    # already computes tier scope, per-door pending and urls. Assign each child
    # its route's module so the talent box (a /talent-box = 'tm' page) is not
    # shown when tm is off even if calibration is on (the R4 mismatch).
    _mod_by_url = {url_for("pm_calibration_home"): "pm",
                   url_for("calibration_home"): "calibration",
                   url_for("talent_box_home"): "tm"}
    # `group` splits the doors for the dashboard cards: "calibration" -> the leader
    # decision card (AI+ Calibration); "team" -> a manager's team review, which folds
    # into the AI+ PM.TM.IDP card. (Ignored by every other caller.)
    for c in _hub_calibration_children(db, u, tiers=("buceo", "bugrp")):   # an HOD's are the Dept Review card's
        doors.append({"name": c["name"], "url": c["url"],
                      "pending": c.get("pending_count") or 0,
                      "unlocked": c.get("unlocked") or 0, "window": c.get("window"),   # the part's window (2026-11-02)
                      "module": _mod_by_url.get(c["url"], "calibration"),
                      "group": "calibration", "icon": c.get("icon_svg")})

    # Succession (BU CEO and up) and Reward (a BG CEO) had doors here -- archived 2026-10-08 (ARCHIVED_MODULES): taken
    # out of OneHR, so no door leads to them.

    # Promotion nomination had a door here (any line manager / HOD / BU CEO) -- archived 2026-10-13 (ARCHIVED_MODULES):
    # it moves to another platform.

    # Manager team doors, gated exactly like the nav flags and dash_tasks.
    if pmpid:
        pf = _pm_entry_flags(db, u, pmpid)
        if pf["pm_team"] or pf["setting_review"]:
            split = _pm_pending_split(db, u, pmpid)
            doors.append({
                "name": "Team performance",
                "url": url_for("performance_team_view") if pf["pm_team"]
                       else url_for("performance_kpi_setting_review"),
                "pending": split["team_pending"] + split["setting_review_pending"],
                "module": "pm", "group": "team", "icon": None})
        if pf["approver"]:
            doors.append({"name": "Team development plans",
                          "url": url_for("idp_team_view"),
                          "pending": 0, "module": "idp", "group": "team", "icon": None})

    # Team competency review -- the ONE Hub door with no other home once the
    # chat replaces the dash_tasks tc_team row.
    if cid:
        _has_own, is_tc_mgr, tc_awaiting = _hub_tc_flags(db, u, cid)
        if is_tc_mgr:
            doors.append({"name": "Team competency review",
                          "url": url_for("technical_team_view"),
                          "pending": tc_awaiting, "module": "tm", "group": "team", "icon": None})

    # Final gate: keep a door only if its route's own module is on this cycle,
    # so nothing on the dashboard links to a module_off page.
    return [d for d in doors if cycle_module_on(d["module"], db, cid)]


def dash_calib_chat_urls(db, u):
    """The chat's Calibration tabs this person can open: {grid door url: chat tab url} for the two calibration doors
    (Performance -> stage=calibration, 360 Potential -> stage=calibration_pot). Chris, 2026-09-29: "this AI+ Calibration
    should link to our chat interface calibration module". The SAME gates the page they open applies (review_journey
    view=dept|bu|bg + _journey_team_live_stages): the review phase on, the unified journey on for them, a leader view
    (_journey_leader_views), Year-End, and a scope with people in it (the tab's own resolver). A door with no chat tab keeps
    its grid page -- a BG CEO's performance door (the chat tab is HOD / BU CEO), Talent Box, Succession, Reward -- so a
    card link can never land on a page that 404s or silently opens the Mine view."""
    out = {}
    if not u or is_admin(u) or not cycle_module_on("review", db) or not _review_unified_on(u):
        return out
    if not _is_year_end(active_pm_period(db)):
        return out
    # Calibration lives in the leader views now (Dept / BU / BG, 2026-09-30): each door opens the first leader view
    # that has that part -- an HOD who is also a BU CEO lands on Dept, and has the BU tab one click away.
    for view in _journey_leader_views(db, u):
        if view in ("dept", "group", CHAIR_VIEW, CHAIRL_VIEW):   # an HOD's department review is its own card (dash_dept_review,
            continue                    # 2026-09-30); a Group Chief's part and the Chairman's box have no classic door
        tier = _VIEW_TIER[view]
        if url_for("pm_calibration_home") not in out and _journey_calib_scope(db, u, tier=tier):
            out[url_for("pm_calibration_home")] = url_for("review_journey", view=view, stage="calibration")
        if url_for("calibration_home") not in out and _pot_calib_scope(db, u, tier=tier):
            out[url_for("calibration_home")] = url_for("review_journey", view=view, stage="calibration_pot")
        if tier == "bgceo" and _journey_talent_box_scope(db, u, tier="bgceo", exists=True):
            out[url_for("talent_box_home")] = url_for("review_journey", view=view, stage="talent_box")
    return out


# The Department Review's two axes (Chris, 2026-09-30), the one place that says which of them an HOD has and whether each is
# submitted: (axis, label, stage, session table, the page it falls back to, the module it needs). The dashboard's Dept Review
# card and the "Ready for you" notices (ready_build) both ask hod_review_axes, so the card and the email can never disagree.
HOD_REVIEW_AXES = (
    ("pm", "Performance review", "calibration", "pm_calibration_sessions", "pm_calibration_hod_view", "pm"),
    ("pot", "Potential review", "calibration_pot", "calibration_sessions", "calibration_hod_view", "calibration"))


def hod_review_axes(db, hod_ids):
    """{hod id: {"pm": True | False | None, "pot": True | False | None}} for the HODs who hold the HOD role (hod_has_role:
    a calibrator has none) and have someone in their Department Review. Per axis: None = the axis doesn't apply to them
    (its module is off this cycle, the cycle has no period for it, or -- Performance only -- nobody in their department
    holds a scorecard); else whether the HOD has SUBMITTED it, i.e. locked their own session on that axis (tier 'hod',
    scope key = their id). ONE batched read of the people and of the locks, never a query per HOD; the dashboard card is
    this with a list of one."""
    ids = _hod_ids_with_review(db, sorted({int(i) for i in hod_ids or [] if i}))
    out = {}
    if not ids:
        return out
    pid, cid = active_pm_period_id(db), active_cycle_id(db)

    def chunks():
        for i in range(0, len(ids), 800):
            yield ids[i:i + 800]
    has = set()   # someone in the department review (the card's own `people`)
    for ch in chunks():
        has |= {r[0] for r in db.execute(
            "SELECT DISTINCT hod_id FROM users WHERE hod_id IN (%s) AND role!='admin' AND " % ",".join("?" * len(ch))
            + calibration_population_sql(), ch)}
    for h in has:
        out[h] = {"pm": None, "pot": None}
    for axis, _label, _stage, tbl, _page, module in HOD_REVIEW_AXES:
        cyc = pid if axis == "pm" else cid
        if not (cyc and cycle_module_on(module, db)):
            continue
        scored = None   # Performance only where someone in the department holds a scorecard
        if axis == "pm":
            scored = set()
            for ch in chunks():
                scored |= {r[0] for r in db.execute(
                    "SELECT DISTINCT hod_id FROM users WHERE hod_id IN (%s) AND role!='admin' AND "
                    % ",".join("?" * len(ch)) + pm_calibration_population_sql(), ch + [cyc])}
        locked = set()
        for ch in chunks():
            locked |= {r[0] for r in db.execute(
                "SELECT scope_key FROM %s WHERE cycle_id=? AND tier='hod' AND locked_at IS NOT NULL AND scope_key IN (%s)"
                % (tbl, ",".join("?" * len(ch))), [cyc] + [str(i) for i in ch])}
        for h in has:
            if scored is None or h in scored:
                out[h][axis] = str(h) in locked
    return out


def hod_review_submitted(axes):
    """Whether one HOD's Department Review is SUBMITTED, from their hod_review_axes entry: every axis that applies to them
    is locked. An HOD with no axis that applies has nothing to submit (True here; ready_build asks `any` for that)."""
    return all(v for v in (axes or {}).values() if v is not None)


def dash_dept_review(db, u):
    """The AI+ Dept Review card (Chris, 2026-09-30: "add a new module called 'AI+ Dept Review'") for anyone holding an
    HOD tier: the department review's two parts, Performance and Potential, each to submit / submitted / closed (a
    review closes once the business unit is locked, _hod_review_closed). The card opens the chat's Dept view when this
    login has it (dash_calib_chat_urls' gates), else the HOD's own pages -- never a page that would 404. Which parts an
    HOD has, and whether each is submitted, is hod_review_axes (shared with the Ready for you notices)."""
    if u and not leader_can(u, "hod.view", db):   # the seat's view is switched off (Roles & access)
        return None
    if not u or is_admin(u):
        return None
    hods = [k for t, k in calibration_tier_of(db, u) if t == "hod"]
    if not hods:
        return None
    hod = hods[0]
    _sk, _sa = _hod_review_skip_sql(db, hod)   # a calibrator is no HOD: nobody (2026-10-30)
    people = db.execute("SELECT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND "
                        + calibration_population_sql() + _sk, [hod] + _sa).fetchall()
    if not people:
        return None
    chat = False
    if (cycle_module_on("review", db) and _review_unified_on(u)   # Mid-Year too (2026-10-12)
            and "dept" in _journey_leader_views(db, u)):
        chat = True
    pid, cid = active_pm_period_id(db), active_cycle_id(db)
    state = hod_review_axes(db, [hod]).get(hod) or {}
    parts = []
    for axis, label, stage, _tbl, page, _module in HOD_REVIEW_AXES:
        cyc = pid if axis == "pm" else cid
        if state.get(axis) is None:   # the module is off, no period, or nobody here holds a scorecard
            continue
        locked = state[axis]   # hod_review_axes: every scorecard-holder check and the lock, shared with the Ready notices
        # before the HOD's window opens the part is not theirs yet: "opens 12 Nov", read from that cell's window (2026-11-02);
        # _hod_review_closed (the writers' and the journey's) still says why it is closed, from the window's open on
        wst, wraw = _lead_window(db, u, ["pm_hod" if axis == "pm" else "pot_hod"], cyc, scope=[str(hod)])
        not_yet = (wst, wraw) if (wst == "not_open" and not locked) else None
        closed = None if (locked or not_yet) else _hod_review_closed(db, axis, cyc, people, hod_id=hod)
        has_chat = chat and bool(_journey_calib_scope(db, u, tier="hod") if axis == "pm"
                                 else _pot_calib_scope(db, u, tier="hod"))
        url = (url_for("review_journey", view="dept", stage=stage) if has_chat else url_for(page, hod_id=hod))
        _lp = ([] if (locked or closed or not_yet or window_state(db, "pm_hod" if axis == "pm" else "pot_hod", cyc) != "closed")
               else _late_held_rows(db, u["id"], "pm_hod" if axis == "pm" else "pot_hod", cyc, scope=[str(hod)]))
        parts.append({"label": label, "url": url,
                      "meta": ("submitted" if locked else _lead_say(*not_yet, lower=True) if not_yet
                               else "closed" if closed else
                               ("open until " + _late_when(_myt(_lp[0]["until_at"])).split(",")[0].rsplit(" ", 1)[0]) if _lp
                               else "to submit"),
                      "open": not (locked or closed or not_yet), "not_yet": not_yet})
    if not parts:
        return None
    n_open = sum(1 for p in parts if p["open"])
    first = next((p for p in parts if p["open"]), parts[0])
    # no part open and one not yet open: "Opens <the earliest start>" (never a "Closed" before it has opened)
    soon = _lead_rollup([p["not_yet"] for p in parts if p["not_yet"]]) if not n_open else None
    return {"key": "dept_review", "name": "AI+ Dept Review", "url": first["url"],
            "sub": ("%d to submit" % n_open) if n_open else (
                _lead_say(*soon) if soon else
                "Submitted" if all(p["meta"] == "submitted" for p in parts)
                else "Closed" if all(p["meta"] == "closed" for p in parts) else "Done"),
            "disabled": False,
            "pending": [{"label": p["label"], "url": p["url"], "meta": p["meta"]} for p in parts]}


def dash_cards(db, u, review, leadership, tasks):
    """The three AI+ module cards for the dashboard. Card 1 (PM.TM.IDP) is the review
    journey PLUS a manager's team review (Promotion + the three team doors); card 2
    (Calibration, leaders only) is the calibration decisions; card 3 (LMS) is a
    Coming-soon placeholder. Reuses dash_review_summary + dash_leadership -- no state is
    re-derived, so a card can never disagree with the page it opens. Each card:
    {key, name, url, sub, disabled, pending:[{label, meta, url}]}."""
    leadership = leadership or []
    team = [d for d in leadership if d.get("group") == "team"]
    calib = [d for d in leadership if d.get("group") == "calibration"]

    # --- Card 1: AI+ PM.TM.IDP -------------------------------------------------
    pending = []
    if review:
        for st in review["stages"]:
            if st.get("state") in (REVIEW_STATE_DONE, REVIEW_STATE_OFF):
                continue   # only the open / waiting self stages are "pending"
            if st.get("blocked_on"):
                meta = "with " + st["blocked_on"]
            elif st.get("n_total"):
                meta = "%d of %d left" % (st.get("n_open") or 0, st["n_total"])
            else:
                meta = ""
            pending.append({"label": st.get("short") or st.get("label") or "", "meta": meta,
                            "url": review["url"]})
    # Team doors are a manager's surfaces -- list them all (their only home now that
    # the Leadership section is gone), with a count where something is waiting.
    for d in team:
        pending.append({"label": d["name"], "url": d["url"],
                        "meta": ("%d pending" % d["pending"]) if d.get("pending") else ""})
    if review:
        team_pending = sum(d.get("pending") or 0 for d in team)
        if review.get("not_required") and not team_pending:
            sub = "Not required this round"
        elif review["all_done"] and not team_pending:
            sub = "Review complete"
        else:
            sub = "%d of %d done" % (review["done"], review["total"])
            if team_pending:
                sub += " · %d to review" % team_pending
        url1 = review["url"]
    else:
        # Review off / no active cycle: fold the per-stage tasks into the popout (each
        # links to its own module page) so nothing is orphaned. No single /review
        # destination, so the card name is not a link.
        for t in (tasks or []):
            pending.append({"label": t.get("title") or "", "url": t.get("url"),
                            "meta": t.get("subtitle") or ""})
        n = len(tasks or [])
        sub = ("%d to do" % n) if n else "Nothing this cycle"
        url1 = None
    review_card = {"key": "review", "name": "AI+ PM·TM·IDP", "url": url1,
                   "sub": sub, "disabled": False, "pending": pending}

    # --- Card 2: AI+ Calibration (leaders only) --------------------------------
    calib_card = None
    if calib:
        # The two calibration doors open the CHAT's Calibration tabs when this person has them; the card itself opens
        # the first of those (Performance, then Potential), else the grid as before.
        chat = dash_calib_chat_urls(db, u)
        calib = [dict(d, url=chat.get(d["url"]) or d["url"]) for d in calib]
        chat_urls = set(chat.values())
        total = sum(d.get("pending") or 0 for d in calib)
        primary = (next((d for d in calib if d["url"] in chat_urls), None)
                   or next((d for d in calib if d["module"] == "pm"), calib[0]))
        # Nothing counted: "Opens 16 Nov" when every part they still have to do is not open yet, "Closed" when every one's
        # window has closed (no late pass), else "Nothing pending" (2026-11-02; read from the cycle's windows, never a date here)
        sub = ("%d to calibrate" % total) if total else "Nothing pending"
        if not total:
            roll = _lead_rollup([d["window"] for d in calib if d.get("unlocked") and d.get("window")])
            if roll and roll[0] in ("not_open", "closed"):
                sub = _lead_say(*roll)
        calib_card = {"key": "calibration", "name": "AI+ Calibration", "url": primary["url"],
                      "sub": sub, "disabled": False,
                      "pending": [{"label": d["name"], "url": d["url"],
                                   "meta": (("%d pending" % d["pending"]) if d.get("pending") else
                                            _lead_say(*d["window"], lower=True) if (d.get("unlocked") and d.get("window")) else "")}
                                  for d in calib]}

    # --- Card 3: AI+ LMS (Coming soon) -----------------------------------------
    lms_card = {"key": "lms", "name": "AI+ LMS", "url": None, "sub": "Coming soon",
                "disabled": True, "pending": []}

    # --- AI+ Dept Review (an HOD's department review, 2026-09-30) -----------------
    dept_card = dash_dept_review(db, u)
    group_card = dash_group_calib(db, u)   # a Group Chief's calls (admin round 4, row 7)

    return [c for c in (review_card, dept_card, calib_card, group_card, lms_card) if c]


def dash_group_calib(db, u):
    """The AI+ Talent Box card for a Group Chief (admin round 4, row 7; Talent Box calibration since 2026-10-13): their
    group, whether its Talent Box is locked -- one lock for the whole group -- and the Group view their button opens.
    None when the Group view isn't theirs."""
    if not u or is_admin(u) or not cycle_module_on("review", db) or "group" not in _journey_leader_views(db, u):
        return None
    d = _journey_group_overview(db, u)
    if not d or not d["people"]:
        return None
    url = url_for("review_journey", view="group", stage="group_calib")
    n = len(d["people"])
    meta = "locked" if d["locked"] else "%d %s, not locked yet" % (n, "person" if n == 1 else "people")
    sub, pending = "Locked" if d["locked"] else "1 Talent Box to lock", [] if d["locked"] else [
        {"label": d["scope_label"], "url": url, "meta": meta}]
    if not d["locked"]:
        # the display follows the Talent Box window (tb_bgceo; Chris, 2026-11-02): before it opens "Opens 19 Nov" and nothing
        # pending, after it closes "Closed"; a lock wins over both. The Group Chief's writes are unchanged.
        wst, wraw = _lead_window(db, u, ["tb_bgceo"], active_cycle_id(db))
        if wst == "not_open":
            sub, pending = _lead_say(wst, wraw), []
        elif wst == "closed":
            sub, pending = "Closed", [dict(pending[0], meta="closed")]
    return {"key": "group_calib", "name": "AI+ Talent Box", "url": url,
            "sub": sub, "disabled": False, "pending": pending}


# The dashboard's Your review panel and a manager's Your team card (Chris, 2026-10-08, the UX review's F2-F4, with F21
# and F25 riding along: the deadline moves into the panel, the Coming-soon card becomes a line). Built from the
# journey's OWN parts, names and counts -- the builders its top tabs, left panel and Team view read -- so the dashboard
# can never quote a step or a number the journey wouldn't. People on the unified journey only; anyone on the classic
# per-stage flow keeps the AI+ card.
_DASH_PART_CELL = {"account": "pm_results", "checkin": "pm_results", "feedback": "f360", "competency": "tc_self",
                   "career_plan": "idp_self", "agree": "pm_setting"}
_DASH_MODULES = (("pm", "Performance Management"), ("tm", "Talent Management"),
                 ("idp", "Individual Development Plan"))
_DASH_DONE_NOTE = {"account": "Submitted", "checkin": "Submitted", "feedback": "All submitted",
                   "competency": "Submitted", "career_plan": "Shared with your manager"}


def _dash_day(raw):
    """'31 Aug 2026' for a stored date (or date-time), else ''."""
    dt = _parse_when(raw)
    return ("%d %s" % (dt.day, dt.strftime("%b %Y"))) if dt else ""


def _dash_due(db, part_key, cycle_ends_on, days_left):
    """When the part the Continue button opens has to be in. Its window's close from Admin > Open & close dates is a
    hard close ('Closes 15 Oct 2026, 18:00'); else the cycle's end date, which is a soft target that never closes
    anything ('Due 31 Dec 2026', or 'Was due 31 Aug 2026' once it has passed -- never 'Closed' beside a review that is
    still open, the UX review's F21). '' when neither is set."""
    cell = _DASH_PART_CELL.get(part_key)
    if cell and has_request_context() and session.get("user_id") and window_state(db, cell) == "closed":
        _lr = _late_held_rows(db, session["user_id"], cell)   # a late pass is theirs alone, until its time (2026-10-31)
        if _lr:
            return "Open for you until " + _late_disp(_lr[0]["until_at"])
    hard = _window_due_disp(db, cell) if cell else ""
    if hard:
        return "Closes " + hard
    day = _dash_day(cycle_ends_on) if cycle_ends_on else ""
    if day:
        return ("Was due " if (days_left is not None and days_left < 0) else "Due ") + day
    return ""


def _dash_next(part, kpi, tm, idp):
    """(title, sub) for the next step: what to do in the part the Continue button opens."""
    k = part["key"]
    if k == "account" and kpi:
        cur = next((x for x in kpi if x.get("current")), None)
        n = kpi[0]["total"]
        if cur and cur["key"] == "justify":
            return ("Next: write your overall remark",
                    "It goes to your BU CEO with your results, with a file for any KPI above target.")
        if cur and cur["key"] == "confirm":
            return ("Next: review and submit your KPI check-in", "Save & submit is at the foot of the KPI card.")
        return ("Next: enter your KPI results",
                "%d KPI%s, then your overall remark." % (n, "" if n == 1 else "s"))
    if k == "feedback" and tm.get("feedback"):
        g = tm["feedback"]
        left = max(0, (g.get("n_all") or 0) - (g.get("n_done") or 0))
        return ("Next: 360 feedback for %d colleague%s" % (left, "" if left == 1 else "s"),
                "Mark each behaviour Demonstrate or Developing, then submit.")
    if k == "competency" and tm.get("competency"):
        g = tm["competency"]
        return ("Next: rate your competencies",
                "%d of %d answered, then one overall remark." % (g.get("n_done") or 0, g.get("n_all") or 0))
    if k == "career_plan":
        return ("Next: your Career Plan", "Your goals, where you want to go, and how far you'd move.")
    return ("Next: " + (part["name"] or "your review"), "")


def _dash_setting_approvals(db, u, cid):
    """An approver's KPI-setting share of an Early Year: (people whose proposal waits on them, people approved)."""
    if not cid:
        return 0, 0
    r = db.execute(
        "SELECT COUNT(DISTINCT CASE WHEN t.status='proposed' THEN t.subject_id END), "
        "COUNT(DISTINCT CASE WHEN t.status='approved' THEN t.subject_id END) FROM pm_kpi_targets t "
        "JOIN pm_kpi_target_approvers a ON a.kpi_target_id=t.id WHERE t.cycle_id=? AND a.approver_id=? "
        "AND t.subject_id!=?", (cid, u["id"], u["id"])).fetchone()
    return (r[0] or 0), (r[1] or 0)


def _dash_setting_panel(db, u, st, cycle_ends_on, days_left):
    """The Your review panel in an Early Year (Chris, 2026-10-15: "our new early year cycle (on kpi setting after year
    end closes)"): its one part is KPI setting, in its own AI chat (/review/setting); the approver's yes comes next, and
    then the lines carry into the Mid-Year. Same shape as dash_review_panel's answer."""
    cid = st["period"]["id"] if st.get("period") else None
    own = bool(st.get("participant", True))
    agree = next((x for x in st["stages"] if x["key"] == "agree"), None)
    # an approver's share: the KPI-setting approval has no AI+ version, so it is the one place the dashboard links its
    # page (performance_kpi_setting_review) -- in the Early Year only, where it is the leader's whole job
    n_wait, n_ok = _dash_setting_approvals(db, u, cid)
    appr = ({"waiting": n_wait, "approved": n_ok, "url": url_for("performance_kpi_setting_review")}
            if (n_wait or n_ok) else None)
    out = {"label": _journey_checkin_title(db), "next": None, "url": url_for("review_setting"), "due": "",
           "modules": [], "complete": False, "not_required": False, "own": own, "early_year": True,
           "approvals": appr}
    if not own or not agree or agree["state"] == REVIEW_STATE_OFF:
        return dict(out, title="Not required this round", sub=_JOURNEY_NOT_REQUIRED, button=None, not_required=True,
                    own=False)
    state, n_prop, approved_n, waiting_on = pm_setting_stage(db, u, cid)
    p = {"key": "agree", "module": "pm", "name": "KPI setting", "frac": None, "your_turn": False,
         "count": ("%d KPI%s" % (n_prop + approved_n, "" if n_prop + approved_n == 1 else "s"))
         if (n_prop + approved_n) else "", "note": ""}
    if agree["state"] == REVIEW_STATE_DONE:
        p["state"], p["note"] = "done", "Agreed · carries into the Mid-Year"
        title, sub, button = ("Your KPIs are agreed", "They carry into your Mid-Year check-in.", None)
        out["complete"] = True
    elif agree["state"] == REVIEW_STATE_WAITING:
        p["state"], p["note"] = "waiting", ("With " + waiting_on) if waiting_on else "With your approver"
        title = "Your KPIs are with %s" % (waiting_on or "your approver")
        sub, button = "They approve them, or send them back to you with a note.", None
    else:
        p["state"], p["your_turn"] = "open", True
        returned = state == "returned"
        title = "Next: %s" % ("update the KPIs your manager sent back" if returned else "set your KPIs")
        sub = ("Read their note, change what they asked, then submit again." if returned
               else "Build your scorecard for the year with the AI, then submit it to your manager.")
        button = "Continue KPI setting with AI" if (n_prop or returned) else "Start KPI setting with AI"
        out["next"] = "agree"
        shut = window_closed(db, "pm_setting")
        if shut:
            p["state"], p["note"], p["your_turn"], button = "closed", shut, False, None
        else:
            out["due"] = _dash_due(db, "agree", cycle_ends_on, days_left)
    out["modules"] = [{"key": "pm", "name": "Performance Management", "parts": [p], "current": p["your_turn"]}]
    return dict(out, title=title, sub=sub, button=button)


def dash_review_panel(db, u, review, cycle_ends_on=None, days_left=None):
    """The Your review panel: the next step named with one Continue button, when it is due, and each module's parts
    with the journey's own counts. None when the unified journey isn't this person's review surface."""
    if not review or not _review_unified_on(u):
        return None
    st = review.get("st") or review_state(db, u)
    if cycle_row_is_early_year(st.get("period")):
        return _dash_setting_panel(db, u, st, cycle_ends_on, days_left)
    live = _journey_live_stages(st)
    keys = {x["key"] for x in live}
    kpi = _journey_kpi_steps(db, u) if "account" in keys else None
    tm = {g_["key"]: g_ for g_ in (_journey_tm_steps(db, u, live, None) or [])}
    idp = _journey_idp_steps(db, u) if "career_plan" in keys else None
    active = _journey_active_stage(st, None)
    # what Group People reopened for them (2026-10-16, canvas board 10): that part leads Your next step, with HR's reason
    reo = {}
    for r in _reopen_rows(db, active_cycle_id(db), actor_id=u["id"], parts=list(_REOPEN_DASH_KEY), live=True):
        if not r["follows"]:
            reo.setdefault(_REOPEN_DASH_KEY[r["part"]], r)
    parts = []
    bu_note = None
    for x in live:
        k, state = x["key"], x["state"]
        if x.get("bu_only"):
            # every KPI a BU KPI Group People fills (2026-10-26): nothing waits on them, so the part reads as theirs
            # done, with Group People named; the optional note is offered beside it, never as something to do
            nf = kpi_note_for(db, u)
            has_note = bool(_review_overall_remark(db, u).strip())
            bu_note = {"title": "KPI check-in", "sub": "Group People fills your business unit KPIs", "for": nf,
                       "written": has_note, "button": "Edit your note" if has_note else "Add a note (optional)",
                       "url": url_for("review_journey", stage=k)}
            parts.append({"key": k, "module": x.get("module"), "name": x.get("short") or x.get("label") or "",
                          "count": "", "frac": None, "note": "Group People fills it", "word": "Group People",
                          "state": "done", "your_turn": False, "bu_only": True})
            continue
        if state == REVIEW_STATE_LATER and not x.get("n_total") and not x.get("locked"):
            continue   # nothing in it for them this round (a 360 on no panel, a check-in with no KPIs)
        p = {"key": k, "module": x.get("module"), "name": x.get("short") or x.get("label") or "",
             "count": "", "frac": None, "note": "",
             "state": ("locked" if x.get("locked") else "done" if state == REVIEW_STATE_DONE
                       else "waiting" if state == REVIEW_STATE_WAITING
                       else "open" if state == REVIEW_STATE_OPEN else "later")}
        if k == "account" and kpi:
            r = kpi[0]
            p["count"] = "%d of %d results" % (r["keyed"], r["total"])
            p["frac"] = r["frac"]
        elif k in ("feedback", "competency") and tm.get(k):
            g_ = tm[k]
            na, nd = g_.get("n_all") or 0, g_.get("n_done") or 0
            p["count"] = ("%d of %d colleagues" if k == "feedback" else "%d of %d answered") % (nd, na)
            p["frac"] = round(nd / na, 3) if na else 0.0
        elif k == "career_plan" and idp:
            items = [s_ for s_ in idp if not s_.get("na")]
            nd = sum(1 for s_ in items if s_["done"])
            p["count"] = "%d of %d done" % (nd, len(items))
            p["frac"] = round(nd / len(items), 3) if items else 0.0
        elif x.get("n_total"):
            nd = (x["n_total"] or 0) - (x.get("n_open") or 0)
            p["count"] = "%d of %d done" % (nd, x["n_total"])
            p["frac"] = round(nd / x["n_total"], 3)
        if p["state"] == "locked":
            p["note"] = "Opens once your KPI check-in and competency are in"
        elif p["state"] == "waiting":
            p["note"] = ("With " + x["blocked_on"]) if x.get("blocked_on") else "Waiting on someone else"
        elif p["state"] == "done":
            p["note"] = ("Shared. Nobody reviews it" if (k == "career_plan" and _idp_chair_unreviewed(db, u["id"]))
                         else _DASH_DONE_NOTE.get(k, "Done"))   # the Executive Chairman's direct reports (2026-11-06)
        cell = _DASH_PART_CELL.get(k)
        shut = window_closed(db, cell) if (cell and p["state"] in ("open", "later")) else None
        if shut:
            p["state"], p["note"] = "closed", shut
        elif cell and p["state"] == "open" and window_state(db, cell, active_cycle_id(db)) == "closed":
            _lr = _late_held_rows(db, u["id"], cell)   # a late pass: the step says its time, not "Closed" (2026-10-31)
            if _lr:
                p["late"], p["note"] = True, "Open for you until " + _late_disp(_lr[0]["until_at"])
        if k in reo and p["state"] == "open":   # Group People reopened it for them (2026-10-16)
            p["reopened"], p["note"] = True, "Reopened by Group People"
            if reo[k].get("until_at"):   # made past the deadline (2026-11-07): it is open for them until a date
                p["until"] = _days_disp(reo[k]["until_at"])
        p["your_turn"] = (k == active and p["state"] == "open")
        parts.append(p)
    modules = [{"key": mk, "name": mn, "parts": [p for p in parts if p["module"] == mk],
                "current": any(p["your_turn"] for p in parts if p["module"] == mk)}
               for mk, mn in _DASH_MODULES]
    modules = [m for m in modules if m["parts"]]
    complete = _journey_review_complete(st)
    not_req = _journey_not_required(st)
    # The buttons say they open an AI conversation (Chris, 2026-10-08: "instead of naming the button as open review or
    # continue, name it more AI, like Continue with AI check-in"): Start before anything is in, Continue after.
    started = any(p["state"] in ("done", "waiting") or (p["frac"] or 0) > 0 for p in parts)
    part, reopen_pass = None, ""
    # no review of their own this cycle -- a BG CEO, or someone not in its own review -- only the 360 they give
    # (Chris, 2026-10-12: "why is there 'your own check-in is done'? Since BGCEO will not have the self check in")
    own = bool(st.get("participant", True))
    if complete and not own and not _st_idp_own(st):
        title, sub, button = ("Your 360 feedback is done", "Thank you. Your feedback for your colleagues is in.",
                              "See your 360 feedback")
    elif complete:
        title, sub, button = ("Your review is complete", "Thank you. It's with your manager now.",
                              "See your AI check-in summary")
    elif any(p_.get("reopened") for p_ in parts):
        part = next(p_ for p_ in parts if p_.get("reopened"))
        title, sub, reopen_pass = _dash_reopen_next(db, reo[part["key"]])
        button = "Continue with AI check-in"
    elif not_req:
        title, sub, button = ("Not required this round", _JOURNEY_NOT_REQUIRED, None)
    elif bu_note and not any(p_["state"] in ("open", "waiting") for p_ in parts):
        # their KPIs are Group People's figures and nothing else is open (canvas board 3B, 2026-10-26): never "not
        # required" -- what their KPIs are, and the optional note
        title = "Your KPIs are business unit results"
        sub = ("Group People fills them in once your unit's figures are final, so nothing is waiting on you. If "
               "there's something %s should know about the year behind them, you can leave a note." % bu_note["for"])
        button = ("Edit your note for %s" if bu_note["written"] else "Add a note for %s") % bu_note["for"]
    else:
        part = next((p for p in parts if p["key"] == active), None) or (parts[0] if parts else None)
        title, sub = _dash_next(part, kpi, tm, idp) if part else ("Your review", "")
        button = "Continue with AI check-in" if started else "Start your AI check-in"
    note_only = bool(bu_note) and title == "Your KPIs are business unit results"
    return {"label": _journey_checkin_title(db), "title": title, "sub": sub, "button": button,
            "next": part["key"] if part else None,   # the part the button's next step names (the rail marks it)
            "url": bu_note["url"] if note_only else (review.get("url") or url_for("review_home")),
            "due": "" if (complete or not_req or reopen_pass or note_only)
                   else _dash_due(db, active, cycle_ends_on, days_left),
            "reopen_pass": reopen_pass,
            "modules": modules, "complete": complete, "not_required": not_req, "own": own,
            "bu_note": bu_note if (bu_note and not note_only) else None, "note_only": note_only}


_REOPEN_DASH_KEY = {"pm_self": "account", "tc_self": "competency", "idp_self": "career_plan", "f360": "feedback"}


def _dash_reopen_next(db, r):
    """(title, sub, pass line) of Your next step for a part Group People reopened for them (canvas board 10)."""
    d = REOPEN_PARTS[r["part"]]
    noun = d["noun"]
    if r["part"] == "f360":
        nm = db.execute("SELECT full_name FROM users WHERE id=?", (r["subject_id"],)).fetchone()
        noun = "360 feedback on %s" % (nm["full_name"] if nm else "a colleague")
    verb = "share it" if r["part"] == "idp_self" else "submit it"
    return ("Your %s is open again" % noun,
            "Group People reopened it on %s: \u201c%s\u201d Everything you entered is still there." % (
                _st_day(_myt(r["reopened_at"])), r["reason"]),
            ("Open for you until %s." % _days_disp(r["until_at"])) if r.get("until_at")
            else "Open for you until you %s again." % verb)   # a reopen made past the deadline has its date (2026-11-07)


def dash_team_card(db, u, review):
    """A manager's Your team card: per Team part, who is waiting on them (by name, with what to do), who they're
    waiting on, and how many are done -- from the Team view's own lists (_journey_team_reports, the rows its navigator
    and summary read), so the two can never disagree. People on the unified journey with a Team view only."""
    if not review or not _review_unified_on(u) or not _review_manages_team(db, u):
        return None
    st = review.get("st") or review_state(db, u)
    if cycle_row_is_early_year(st.get("period")):   # no results to moderate: the approvals are the panel's (2026-10-15)
        return None
    people, parts = set(), []
    for s_ in _journey_team_live_stages(st, "team"):
        rows = _journey_team_reports(db, u, s_["key"])
        if not rows:
            continue
        people.update(r["id"] for r in rows)
        turn = sorted((r for r in rows if not r["done"] and r.get("action")), key=lambda r: (r["name"] or "").lower())
        wait = sorted((r for r in rows if not r["done"] and not r.get("action")), key=lambda r: (r["name"] or "").lower())
        cell = _JOURNEY_STAGE_CELL.get(s_["key"])
        w_state, w_raw = _lead_window(db, u, [cell]) if cell else ("open", None)   # the line manager's own dates (2026-11-06)
        parts.append({"key": s_["key"], "name": s_.get("short") or s_.get("label") or "",
                      "cell": cell, "opens": _lead_say(w_state, w_raw) if w_state == "not_open" else None,
                      "turn": [{"id": r["id"], "name": r["name"], "meta": r["meta"],
                                "action": r.get("action") or "Review with AI",
                                "url": url_for("review_journey", view="team", stage=s_["key"], mode="detail",
                                               report=r["id"])} for r in turn],
                      "wait": [{"name": r["name"], "meta": r["meta"]} for r in wait],
                      "done": sum(1 for r in rows if r["done"]), "total": len(rows),
                      # missed their own deadline with nothing shared: counted done, said so on the step (2026-11-08)
                      "didnt": sum(1 for r in rows if r["done"] and r.get("meta") == "Didn't submit"),
                      "url": url_for("review_journey", view="team", stage=s_["key"])})
    if not parts:
        return None
    # A part whose line-manager dates have not started is nobody's turn yet: the dashboard counts only the open parts and,
    # with every part not open, says when the earliest opens ("Opens 9 Nov"). Each part's own `turn` list stays whole
    # (the reminder builder gates by window itself). Display only: the writes were already window-gated.
    live = [p for p in parts if not p["opens"]]
    opens = None
    if not live:
        w_state, w_raw = _lead_window(db, u, [p["cell"] for p in parts if p.get("cell")])
        opens = _lead_say(w_state, w_raw) if w_state == "not_open" else None
    return {"people": len(people), "turn": sum(len(p["turn"]) for p in live), "parts": parts, "opens": opens,
            "url": url_for("review_journey", view="team")}


# The dashboard as the cycle's journey (Chris, 2026-10-09: direction C on the "OneHR Personal Dashboard Directions"
# canvas -- "go with C"). One rail of the whole cycle in order: your own parts, your team, what you lead, then the
# results. Under it, what needs you now ("You are here") beside where you stand. Every step and action comes from the
# panel, the team card and the leader rows the page already reads, so a step can't disagree with the page it opens.
_DASH_RAIL_TAG = {"pm": "AI+ PM", "tm": "AI+ TM", "idp": "AI+ IDP"}
_DASH_LEAD_NAME = {"AI+ Dept Review": "Department review", "AI+ Calibration": "Calibration",
                   "AI+ Talent Box": "Talent Box"}


def _dash_lead_state(c):
    """A leader row's state: 'turn' while its sub counts something left ("2 to submit", "1 to calibrate"), 'later' while
    its window isn't open yet ("Opens 16 Nov", "Not open yet"), 'closed' when every part closed, else 'done'."""
    sub = c.get("sub") or ""
    m = re.match(r"\s*(\d+)\s", sub)
    if m and int(m.group(1)):
        return "turn"
    if sub.startswith("Opens ") or sub == "Not open yet":   # its window isn't open yet: not a turn (2026-11-02)
        return "later"
    return "closed" if sub == "Closed" else "done"


# WHAT YOU LED (Chris, 2026-10-12; the "OneHR Release, What You Led and Agents" canvas, boards W1-W5): the people a
# leader is over, one tab per seat they hold. The timeline's calibration and release steps read the same people.
_LED_FINAL_SOURCES = ("bgceo", "group", "top", "super")


def _led_tabs(db, u):
    """The leader's people, one tab per seat, narrowest first: Direct reports (manager_id), Department (an HOD's
    people), Business unit (a BU CEO's), Business group (a BG CEO's) -- each {key, label, where, args, n}. Never
    themselves, an admin or a leaver, nor a Grade H person (their appraisal is Grade H Appraisal, never the normal review:
    no360_sql, 2026-10-30); a seat with nobody in it has no tab."""
    if not u or u["role"] == "admin":
        return []
    base = "role!='admin' AND left_at IS NULL AND id!=? AND " + no360_sql()
    cand = [("direct", "Direct reports", "manager_id=?", [u["id"]])]
    if hod_has_role(db, u["id"]) and db.execute("SELECT 1 FROM users WHERE hod_id=? AND role!='admin' LIMIT 1",
                                                (u["id"],)).fetchone():   # a calibrator is no HOD (2026-10-30)
        cand.append(("dept", "Department", "hod_id=?", [u["id"]]))
    _seats = buceo_seats(db, u["id"])
    if _seats:   # every unit they lead (admin round 4)
        cand.append(("bu", "Business unit" if len(_seats) == 1 else "Business units",
                     "(" + " OR ".join(["(business_group=? AND company=?)"] * len(_seats)) + ")",
                     [x for s_ in _seats for x in s_]))
    groups = _gc_groups(db, u)
    if groups:   # a Group Chief's people: everyone in the calibration group they call (Chris, 2026-10-14) -- before
        # the business group, so a BG CEO who is also a Group Chief still opens on their business group (the last tab)
        gids = [g_["id"] for g_ in groups]
        cand.append(("group", groups[0]["name"] if len(groups) == 1 else "Calibration groups",
                     "id IN (SELECT subject_id FROM pm_calibration_group_members WHERE group_id IN (%s))"
                     % ",".join("?" * len(gids)), gids))
    if u["bgceo_bg"]:
        cand.append(("bg", "Business group", "business_group=?", [u["bgceo_bg"]]))
    out = []
    for key, label, where, args in cand:
        w = "%s AND %s" % (where, base)
        n = db.execute("SELECT COUNT(*) FROM users WHERE " + w, args + [u["id"]]).fetchone()[0]
        if n:
            out.append({"key": key, "label": label, "where": w, "args": args + [u["id"]], "n": n})
    return out


def _gc_groups(db, u):
    """The calibration groups this login is the Group Chief of ({id, name, created_at}), by id. Cached per request."""
    if not u or u["role"] == "admin":
        return []
    cache = _req_cache()
    ck = "_gcg_%s" % u["id"]
    if ck not in cache:
        cache[ck] = [dict(r) for r in db.execute(
            "SELECT id, name, created_at FROM pm_calibration_groups WHERE calibrator_id=? ORDER BY id", (u["id"],))]
    return cache[ck]


def _gc_members_sql(gids):
    """(sql, args) selecting the people of these calibration groups -- leavers too (their records stay in history)."""
    return ("SELECT subject_id FROM pm_calibration_group_members WHERE group_id IN (%s)" % ",".join("?" * len(gids)),
            list(gids))


def _gc_batches(db, gids):
    """{subject_id: batch} for a Group Chief's groups: the name the super admin gave their batch, else their department
    -- the names the group's Talent Box filters by (_tb_dept_counts). Never an admin."""
    if not gids:
        return {}
    q, a_ = _gc_members_sql(gids)
    return {r["subject_id"]: ((r["segment"] or "").strip() or (r["department"] or "").strip() or "No department")
            for r in db.execute(
                "SELECT m.subject_id, m.segment, x.department FROM pm_calibration_group_members m JOIN users x ON "
                "x.id=m.subject_id WHERE m.group_id IN (%s) AND x.role!='admin'" % ",".join("?" * len(gids)), a_)}


def _gc_lock_at(db, cid, gids):
    """When the Group Chief's calls stood locked in this cycle: the whole group's lock, else the last person locked one
    by one. None when nothing is locked."""
    if not cid or not gids:
        return None
    ph = ",".join("?" * len(gids))
    keys = [str(g_) for g_ in gids]
    return _dash_max_at(db, "SELECT MAX(at) FROM (SELECT locked_at at FROM pm_calibration_sessions WHERE cycle_id=? AND "
                        "tier='group' AND scope_key IN (%s) AND locked_at IS NOT NULL UNION ALL SELECT locked_at FROM "
                        "pm_group_locks WHERE cycle_id=? AND group_id IN (%s))" % (ph, ph),
                        [cid] + keys + [cid] + list(gids))


def _led_people_sql(tabs):
    """(sql, args) selecting the ids of everyone across the leader's tabs, once each."""
    if not tabs:
        return "SELECT NULL WHERE 0", []
    return (" UNION ".join("SELECT id FROM users WHERE " + t["where"] for t in tabs),
            [a_ for t in tabs for a_ in t["args"]])


def _calib_state_of(rec, mid_year=False):
    """'not_started' / 'calibrating' / 'done' from a stored rating record, the calibration_progress rule. At Mid-Year
    the HOD's review (or HR) makes it final (2026-10-12)."""
    if mid_year:
        rec = _rr_mid_year(rec)
    have = [(rec["pm_final_band"], rec["pm_final_source"]), (rec["pot_final_band"], rec["pot_final_source"])]
    have = [h for h in have if h[0]]
    if not have:
        return "not_started"
    fin = ("hod", "super") if mid_year else _LED_FINAL_SOURCES
    return "done" if all(src in fin for _b, src in have) else "calibrating"


def _dash_rail_results(db, u, cid, own, tabs):
    """The two steps that close the cycle on the timeline (Chris, 2026-10-12: "before the HR result released, add one
    more status on the calibration"; canvas boards T1-T2): Calibration, then Results released. Their own results, and
    for a leader their people's too. The calibration step names no band and no tier; the release step says it reaches
    a leader before their people, with a way to their people's results once it has. [step, step]."""
    states = []
    mid_year = cycle_is_mid_year(db, cid)
    if own and cid:
        states.append(calibration_progress(db, u, cid)["state"])
    pq, pa = _led_people_sql(tabs)
    n_people = 0
    if tabs and cid:
        n_people = db.execute("SELECT COUNT(*) FROM (%s)" % pq, pa).fetchone()[0]
        recs = db.execute("SELECT pm_final_band, pm_final_source, pot_final_band, pot_final_source, pm_super_band, "
                          "pm_hod_band, pm_mgr_band, pot_hod_band, pot_raw_band, f360_valid, tiers_json FROM "
                          "rating_records WHERE cycle_id=? AND subject_id IN (%s)" % pq, [cid] + pa).fetchall()
        states += [_calib_state_of(dict(r), mid_year) for r in recs]
        states += ["not_started"] * max(0, n_people - len(recs))
    if not states:
        return []
    started = [x for x in states if x != "not_started"]   # someone with no result yet has nothing to calibrate
    cal = "not_started" if not started else "done" if all(x == "done" for x in started) else "calibrating"
    lead = bool(tabs)
    # a BG CEO, and a Group Chief (who is "like the BG CEO", Chris 2026-10-13): no results of their own, their Talent
    # Box decides their people's, and they read them at once
    bg_only = lead and not own and any(t["key"] in ("bg", "group") for t in tabs)
    who = ("Your results" if not lead else "Your people" if not own
           else "You and your team" if [t["key"] for t in tabs] == ["direct"] else "All results")
    yours = "your results" if not lead else "results"
    step_c = {"who": who, "tag": "", "name": "Calibration", "url": None,
              "state": {"done": "done", "calibrating": "progress"}.get(cal, "later"),
              "line": {"done": "%s come once Group People releases them" % yours.capitalize(),
                       "calibrating": "%s are being calibrated" % yours.capitalize()}.get(
                  cal, "after the line manager's review" if own and not lead else "once the reviews are in")}
    # Results released
    own_rel = bool(own and cid and (result_released(db, "pm", u["id"], cid) or result_released(db, "pot", u["id"], cid)))
    n_lead = n_emp = 0
    first_lead = None
    if lead and cid:
        r_ = db.execute("SELECT COUNT(DISTINCT subject_id), MIN(released_at) FROM leader_releases WHERE cycle_id=? "
                        "AND subject_id IN (%s)" % pq, [cid] + pa).fetchone()
        n_lead, first_lead = r_[0], r_[1]
        n_emp = db.execute("SELECT COUNT(DISTINCT subject_id) FROM (SELECT subject_id FROM result_releases WHERE "
                           "cycle_id=? UNION SELECT subject_id FROM talent_releases WHERE cycle_id=?) WHERE subject_id "
                           "IN (%s)" % pq, [cid, cid] + pa).fetchone()[0]
    team_word = "your team" if [t["key"] for t in tabs] == ["direct"] else "your people"
    is_bg = any(t["key"] in ("bg", "group") for t in tabs)
    after = ("after the HOD's review" if mid_year else "after your Talent Box" if is_bg else "after calibration")
    if not lead:
        step_r = {"state": "done" if own_rel else "later", "word": "Released" if own_rel else "Not yet",
                  "line": ("see your results below" if own_rel
                           else "to your line manager first, then to you" if cal == "done" else after)}
    elif bg_only:
        step_r = ({"state": "done", "word": "Released", "line": "to all %d of %s" % (n_people, team_word)}
                  if n_people and n_emp >= n_people else
                  {"state": "progress" if n_emp else "later", "word": "Released" if n_emp else "Not yet",
                   "line": ("to %d of %d of %s" % (n_emp, n_people, team_word)) if n_emp else after})
    elif not n_lead:
        step_r = {"state": "later", "word": "Not yet", "line": "to you first, then to %s" % team_word}
    elif n_emp < n_lead:
        step_r = {"state": "progress", "word": "To you %s" % (_myt_date_str(first_lead) or "").rsplit(" ", 1)[0],
                  "line": "to %s: not yet. Talk to each person first" % team_word}
    else:
        step_r = {"state": "done", "word": "Released", "line": "to you and %s%s" % (team_word, ", yours too" if own_rel else "")}
    step_r.update({"who": "Group People", "tag": "", "name": "Results released", "url": None})
    if lead and (n_lead or (bg_only and cal != "not_started")):
        step_r["act"] = {"label": "See your people", "panel": "led"}
    if cal == "done" and step_r["state"] != "done":
        step_r["here"] = True
    # no calibration at Mid-Year, and none for a BG CEO, whose Talent Box decides it (Chris, 2026-10-12)
    if mid_year or is_bg:
        return [step_r]
    return [step_c, step_r]


def _dash_open_url(db, u, url):
    """A dashboard link to an AI+ check-in view (/review/journey?view=team | dept | bu | bg | group), or None when that view's tab is
    greyed because its window has not opened (_view_not_open): the link would only land on Mine, which is not what the card names
    (Chris's known bug, "Team / HOD dashboard cards link to a greyed-out view", 2026-11-09). Any other link, and no link, as it is."""
    if not url or "/review/journey" not in url:
        return url
    view = dict(parse_qsl(urlparse(url).query)).get("view", "")
    return None if (view and _view_not_open(db, u, view)) else url


def dash_rail(db, u, panel, team, leaders, not_in=None, gradeh=None):
    """The cycle as one rail: {title, steps, done, total}, or None with nothing to show. A step is {who, tag, name,
    state (turn / open / waiting / locked / later / closed / done), line, url}; 'turn' is a step waiting on them now."""
    steps = []
    for m_ in (panel or {}).get("modules") or []:
        for p in m_["parts"]:
            st_ = p["state"]
            state = "turn" if (p.get("your_turn") or (st_ == "open" and p["key"] == (panel or {}).get("next"))) else st_
            line = p.get("note") if st_ in ("done", "waiting", "locked", "closed") else p.get("count")
            steps.append({"who": "You", "tag": _DASH_RAIL_TAG.get(m_["key"], ""), "name": p["name"],
                          "state": state, "line": "" if (p.get("reopened") or p.get("late")) else (line or ""),
                          **({"word": "Reopened by Group People"} if p.get("reopened") else
                             {"word": p["note"]} if p.get("late") else   # "Open for you until ...": more time given (2026-10-31)
                             {"word": p["word"]} if p.get("word") else {}),   # "Group People": their BU KPIs
                          "url": None if st_ == "locked" else (url_for("review_setting") if p["key"] == "agree"
                                                               else url_for("review_journey", stage=p["key"]))})
    appr = (panel or {}).get("approvals")
    if appr:   # an Early Year approver (2026-10-15)
        steps.append({"who": "Your team", "tag": "PM", "name": "Approve their KPIs",
                      "state": "turn" if appr["waiting"] else "done",
                      "line": ("%d waiting on you" % appr["waiting"]) if appr["waiting"]
                      else "%d approved" % appr["approved"], "url": appr["url"]})
    if team:
        waiting = {w["name"] for p in team["parts"] if not p.get("opens") for w in p["wait"]}
        didnt = sum(p.get("didnt") or 0 for p in team["parts"] if not p.get("opens"))
        later = not team["turn"] and bool(team.get("opens"))   # every part's dates are still ahead (2026-11-06)
        steps.append({"who": "Your team", "tag": "AI+ Review", "name": "Team review",
                      "state": "turn" if team["turn"] else ("later" if later else ("waiting" if waiting else "done")),
                      "line": (("%d waiting on you" % team["turn"]) if team["turn"]
                               else team["opens"] if later
                               else ("%d %s" % (len(waiting), "person" if len(waiting) == 1 else "people"))
                               if waiting else ("All done · %d didn't submit" % didnt) if didnt else "All done"),
                      "url": team["url"]})
    if gradeh:   # Grade H Appraisal, the line manager's 4th stop (2026-10-28, piece 4; canvas L0)
        steps.append({"who": "Your team", "tag": "Grade H", "name": GRADEH_LABEL, "state": gradeh["state"],
                      "line": ("%d ready" % gradeh["ready"]) if gradeh["state"] == "turn"
                      else ("%d with staff" % gradeh["staff"]) if gradeh["state"] == "waiting" else "All done",
                      "url": gradeh["url"]})
    for c in leaders or []:
        dest = c.get("dest") or c.get("name") or ""
        steps.append({"who": "You lead", "tag": "", "name": _DASH_LEAD_NAME.get(dest, dest),
                      "state": _dash_lead_state(c), "line": c.get("sub") or "", "url": c.get("url")})
    if not steps and not not_in:
        return None
    pid, cid = active_pm_period_id(db), active_cycle_id(db)
    if (panel or {}).get("early_year"):
        # an Early Year closes into its Mid-Year, not into calibration and results (2026-10-15)
        steps.append({"who": "Group People", "tag": "", "name": "Mid-Year check-in", "state": "later",
                      "line": "the agreed KPIs carry into it", "url": None, "word": "Next", "uncounted": True})
    elif not_in:   # not in this cycle's own review: say so first; the results at the end are their team's (2026-10-10)
        steps.insert(0, {"who": "You", "tag": "", "name": "Your own review", "state": "closed",
                         "line": not_in["why"], "url": None, "word": "Not this cycle", "uncounted": True})
        if team or leaders:
            steps.append({"who": "Group People", "tag": "", "name": "Your department's results" if (leaders and not team)
                          else "Your team's results", "state": "later", "line": "After calibration", "url": None})
    else:
        # calibration, then the release (2026-10-12): their own results, and their people's for a leader
        own = bool(panel and panel.get("own", True) and panel.get("modules"))
        steps += _dash_rail_results(db, u, cid or pid, own, _led_tabs(db, u) if (team or leaders) else [])
        # one Calibration step, not two (Chris, 2026-10-29: "can it be combined as one to avoid confusion?"): the leader's
        # own calibration row folds into the cycle's step, which keeps its place before "Results released"
        lead_c = next((s_ for s_ in steps if s_["who"] == "You lead" and s_["name"] == "Calibration"), None)
        res_c = next((s_ for s_ in steps if s_["name"] == "Calibration" and s_["who"] != "You lead"), None)
        if lead_c and res_c:
            steps.remove(lead_c)
            res_c["url"] = lead_c["url"]
            if lead_c["state"] == "turn":   # people still wait on them: their count, not the cycle's state
                res_c["state"], res_c["line"] = "turn", lead_c["line"]
                res_c.pop("word", None)
            elif lead_c["state"] == "later" and res_c["state"] == "later":   # their part opens on a date: say which
                res_c["line"] = lead_c["line"]
            elif lead_c["state"] == "closed" and res_c["state"] != "done":   # their window has closed: say so (2026-11-02)
                res_c["state"], res_c["line"] = "closed", ""   # the word says it: "Closed" (no "Closed · Closed" on hover)
                res_c.pop("word", None)
    for s_ in steps:   # a step whose view is greyed (its window not open, the tab is no link) is no link here either (2026-11-09)
        s_["url"] = _dash_open_url(db, u, s_.get("url"))
    first = next((s_ for s_ in steps if s_["state"] == "turn"), None)
    if first:   # their turn comes first; only with nothing to do is "here" where the cycle is
        for s_ in steps:
            s_.pop("here", None)
        first["here"] = True
    elif not any(s_.get("here") for s_ in steps):
        prog = next((s_ for s_ in steps if s_["state"] == "progress"), None)
        if prog:
            prog["here"] = True
    cyc = re.sub(r"^Your\s+|\s+Check-in$", "", _journey_checkin_title(db) or "").strip() or "This cycle"
    counted = [s_ for s_ in steps if not s_.get("uncounted")]   # "Your own review: not this cycle" isn't a step to do
    done = sum(1 for s_ in counted if s_["state"] == "done")
    for s_ in steps:
        s_["short"], s_["full"] = _dash_step_short(s_)
        s_["label"] = _DASH_RAIL_LABEL.get(s_["name"], s_["name"])   # the rail's one line; the full name on hover
    ends = db.execute("SELECT ends_on FROM cycles WHERE id=?", (cid,)).fetchone() if cid else None
    ends = str(ends["ends_on"] or "")[:10] if ends else ""
    closes = (("Closes " if ends >= _today_myt().isoformat() else "Closed ") + _myt_date_str(ends)) if ends else ""
    return {"title": cyc, "steps": steps, "done": done, "total": len(counted), "closes": closes}


_DASH_RAIL_LABEL = {"Competency Assessment": "Competency"}   # fits the calmer rail's one line (2026-10-16)
_DASH_STATE_WORD = {"turn": "Your turn", "open": "To do", "waiting": "Waiting", "locked": "Locked", "later": "Not yet",
                    "closed": "Closed", "done": "Done", "progress": "In progress"}


def _dash_step_short(s_):
    """(short, full) for a rail step: the calmer rail's one quiet line (2026-10-16, canvas board B) and the whole
    "word · line" for its tooltip. A step to do shows its count ("0 of 2"), a team or leader step its waiting count
    ("33 waiting"), anything else its one state word."""
    word = s_.get("word") or _DASH_STATE_WORD.get(s_["state"], "")
    line = s_.get("line") or ""
    full = word + (" · " + line if line else "")
    if s_["state"] == "open" and line:
        return line, full
    if s_["state"] == "later" and line.startswith("Opens "):   # a leader's part that opens on a date (2026-11-02): say when
        return line, full
    if s_["state"] == "turn" and s_.get("who") != "You" and line:
        return re.sub(r"\s+on you$", "", line), full
    return word, full


def dash_here(panel, team, leaders, learn_acts=None):
    """What needs them now, for the You are here card: {head, acts, waits, done, summary}. An act is
    {tag, title, sub, due, button, url, aria}; the first is the page's one solid AI button. Own review first, then
    each Team part with people waiting on them, then each leader row with something left, then AI+ Learning's rows
    (dash_learning, 2026-10-20; staging only while Learning is)."""
    acts, waits = [], []
    if panel and panel.get("button") and not panel.get("complete") and not panel.get("not_required") \
            and not panel.get("note_only"):   # an optional note is never a thing that needs them (2026-10-26)
        t = panel["title"] or ""
        t = t[6:] if t.startswith("Next: ") else t
        acts.append({"tag": "Your KPI setting" if panel.get("early_year") else "Your AI check-in",
                     "title": t[:1].upper() + t[1:], "sub": panel.get("sub") or "",
                     "due": panel.get("due") or "", "button": panel["button"], "url": panel["url"], "aria": None,
                     "kind": "own", "pass": panel.get("reopen_pass") or ""})
    appr = (panel or {}).get("approvals")
    if appr and appr["waiting"]:
        # an Early Year approver: the KPI-setting approval page, which has no AI+ version -- so a navy button, not AI
        n = appr["waiting"]
        acts.append({"tag": "Your team", "title": "%d %s KPIs to approve" % (n, "person's" if n == 1 else "people's"),
                     "sub": "Approve each scorecard, or send it back with a note.", "due": "",
                     "button": "Review their KPIs", "url": appr["url"], "aria": None, "ai": False, "kind": "approve"})
    for m_ in (panel or {}).get("modules") or []:
        for p in m_["parts"]:
            if p["state"] == "waiting":
                waits.append("%s · %s" % (p["name"], p.get("note") or "Waiting on someone else"))
    if team:
        for p in team["parts"]:
            if not p["turn"] or p.get("opens"):   # a part whose dates have not started is not an act (2026-11-06)
                continue
            if len(p["turn"]) == 1:
                r = p["turn"][0]
                acts.append({"tag": p["name"], "title": r["name"], "sub": r["meta"], "due": "",
                             "button": "Review with AI", "url": r["url"],
                             "aria": "Review %s with AI (%s)" % (r["name"], r["action"]), "kind": "team"})
            else:
                names = [r["name"] for r in p["turn"]]
                acts.append({"tag": p["name"], "title": "%d people waiting on you" % len(names),
                             "sub": ", ".join(names[:2]) + ((" +%d more" % (len(names) - 2)) if len(names) > 2 else ""),
                             "due": "", "button": "Move on to AI+ team review", "url": p["url"], "aria": None,
                             "kind": "team"})
        who = {}
        for p in team["parts"]:
            if p.get("opens"):
                continue
            for w in p["wait"]:
                who.setdefault(w["name"], []).append(p["name"])
        if 0 < len(who) <= 2:
            waits += ["%s · %s" % (n, ", ".join(ps)) for n, ps in who.items()]
        elif who:
            waits.append("%d people · %s" % (len(who), ", ".join(sorted({x for ps in who.values() for x in ps}))))
    for c in leaders or []:
        if _dash_lead_state(c) != "turn":
            continue
        dest = c.get("dest") or c.get("name") or ""
        acts.append({"tag": "You lead", "title": _DASH_LEAD_NAME.get(dest, dest), "sub": c.get("sub") or "",
                     "due": "", "button": c.get("button") or ("Move on to " + dest), "url": c["url"], "aria": None,
                     "kind": "lead"})
    acts += [dict(a_) for a_ in (learn_acts or [])]
    complete = bool(panel and panel.get("complete"))
    if acts:
        head = "One thing needs you" if len(acts) == 1 else "%d things need you" % len(acts)
    elif complete:
        head = "You're all caught up"
    elif panel and panel.get("not_required"):
        head = panel["title"]
    else:
        head = "Nothing needs you right now"
    return {"head": head, "acts": acts, "waits": waits[:3],
            "done": (("Your KPIs are agreed" if panel.get("early_year") else "Your own check-in is done"
                      if panel.get("own", True) else "Your 360 feedback is done") if complete else ""),
            "summary": ({"button": panel["button"], "url": panel["url"]} if complete and panel.get("button") else None),
            "not_required": (panel["sub"] if (panel and panel.get("not_required") and not acts) else ""),
            "calm": _dash_calm(acts, team),
            # their KPIs are all BU KPIs Group People fills (2026-10-26): the optional note, as You are here when
            # nothing else is open (note_only), else a quiet row under the next step (bu_note)
            "note_only": ({"title": panel["title"], "sub": panel["sub"], "button": panel["button"], "url": panel["url"],
                           "kind": "own", "solid": True, "aria": None}
                          if (panel and panel.get("note_only") and not acts) else None),
            "bu_note": (dict(panel["bu_note"], kind="own", solid=False, aria=None)
                        if (panel and panel.get("bu_note")) else None)}


def _dash_calm(acts, team):
    """You are here, calmer (Chris, 2026-10-16: "Go with option B with a calmer view", the "OneHR Dashboard, Calmer"
    canvas): {next, rest}. `next` is the one next step -- their own check-in, else the first other thing -- and `rest`
    the others as compact rows: the team's reviews grouped as ONE row ("Your team · N reviews waiting on you", a chip
    per part), then each approval and each thing they lead. Only `next` has the solid button; the page's acts list (the
    guide reads it) is unchanged."""
    own = next((dict(a_) for a_ in acts if a_.get("kind") == "own"), None)
    grp = None
    n = (team or {}).get("turn") or 0
    if n:
        parts = [p for p in team["parts"] if p["turn"] and not p.get("opens")]
        grp = {"title": "Your team · %d review%s waiting on you" % (n, "" if n == 1 else "s"), "sub": "", "due": "",
               "chips": [{"name": re.sub(r"\s+review$", "", p["name"], flags=re.I) or p["name"], "n": len(p["turn"]),
                          "url": p["url"]} for p in parts], "kind": "team"}
        if n == 1:   # one person: straight to them
            r = parts[0]["turn"][0]
            grp.update({"button": "Review with AI", "url": r["url"],
                        "aria": "Review %s with AI (%s)" % (r["name"], r["action"])})
        else:
            grp.update({"button": "Open team review", "url": team["url"], "aria": None})
    items = ([own] if own else []) + ([grp] if grp else []) + [
        dict(a_) for a_ in acts if a_.get("kind") in ("approve", "lead", "basic")] + [
        dict(a_) for a_ in acts if a_.get("kind") == "learning"]
    for i, x in enumerate(items):
        x["solid"] = i == 0
    return {"next": items[0] if items else None, "rest": items[1:]}


def _name_initials(name):
    """Two letters for a name's circle: the first and last words that start with a letter, brackets stripped ("Given
    Family (Preferred)" gives GP, never "G("), one word gives its first two letters, none gives "?"."""
    words = [w.strip("()[]{}<>.,").strip() for w in (name or "").split()]
    words = [w for w in words if w[:1].isalpha()]
    if len(words) >= 2:
        return (words[0][0] + words[-1][0]).upper()
    return words[0][:2].upper() if words else "?"


def welcome_identity(u):
    """Greeting, first name, initials and role line for the welcome band.

    One derivation for every page that says hello. The Hub and the dashboard
    each had their own -- same idea, different code, and they had already
    drifted (only one showed job grade; one title-cased the name in the
    template rather than here).

    "Hello" rather than a time-of-day greeting: "Good evening" is wrong for
    anyone working late, wrong the moment a colleague opens the same page from
    another time zone, and it goes stale on a tab left open for hours."""
    full = (u["full_name"] or "").strip()
    parts = full.split()
    first_name = parts[0].title() if parts else "there"
    # what they asked OneHR to call them (2026-10-15): this greets the person themselves only -- every caller is about
    # their own page or their own AI conversation -- so it never reaches anyone else
    chosen = (_row_get(u, "display_name") or "").strip()
    if chosen:
        first_name, full, parts = chosen, chosen, chosen.split()
    # Initials come from the first and last LETTER-STARTING words. A trailing
    # preferred name in brackets -- "Given Family Name (Preferred)" -- is the
    # house convention in this roster, and taking parts[-1][0] blindly rendered
    # it as "G(" for 332 real people, several of them on the exec team. Strip
    # the bracket characters and ignore any word that still doesn't start with
    # a letter, so "(Preferred)" contributes P rather than an open paren.
    initials = _name_initials(" ".join(parts))
    bits = [(_row_get(u, "job_title") or "").strip(),
            (_row_get(u, "department") or "").strip()]
    jg = (_row_get(u, "job_grade") or "")
    if str(jg).strip():
        bits.append("JG %s" % jg)
    return {"greeting": "Hello", "first_name": first_name, "initials": initials,
            "subtitle": " \u2022 ".join([b for b in bits if b])}


def _dash_overall(db, subject_id, cycle_id):
    """This person's approved performance rating for a period, or None while
    any KPI line is still moving. Goes through the same three calls the
    Performance pages use, in the same order, so the dashboard can never
    quote a number the module itself wouldn't."""
    targets = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY id",
        (cycle_id, subject_id)).fetchall()]
    if not targets:
        return None
    attach_pm_chains(db, targets)
    pm_score_targets(db, targets)
    return pm_overall_for_targets(db, targets)


def _dash_potential(db, u, cycle_id, released_only=True):
    """The person's potential band for a cycle: the FINAL band (after HOD / CEO calibration), shown only once a super
    admin has released their Potential result (2026-10-02) -- the 360 report's release no longer brings a band.
    released_only=False is the final band regardless (admin use)."""
    if not cycle_id:
        return None
    if released_only:
        return released_final_band(db, u, cycle_id, "pot")
    fr = final_result(db, u, cycle_id, "pot")
    return fr["band"] if fr else None


def dash_standing(db, u, period, cyc, asked=True):
    """Where this person stands in the CURRENT cycle -- up to the line manager's level and no further (Chris,
    2026-10-08: "it stops at LM approved level, HOD, BUCEO and BGCEO will be hidden from user display"). The calibrated
    bands and the talent status are not here: once a super admin releases them they reach the history. Every entry is
    either an answer or an honest statement of what it is waiting on -- a pending state is never dressed up as a
    result."""
    out = []
    early = cycle_row_is_early_year(period or cyc)
    if early:
        # an Early Year has no result and no 360: where they stand is their KPIs for the year (2026-10-15)
        if period and asked:
            st_, n_prop, approved_n, _w = pm_setting_stage(db, u, period["id"])
            agreed = bool(approved_n and not n_prop)
            out.append({"key": "kpis", "label": "Your KPIs", "value": None, "band": None,
                        "text": ("%d agreed" % approved_n) if agreed else None,
                        "pending": None if agreed else ("With your approver" if pm_setting_is_waiting(st_)
                                                        else "Not set yet"),
                        "note": ("They carry into your Mid-Year check-in" if agreed
                                 else "Your approver reads them next" if pm_setting_is_waiting(st_)
                                 else "Set them in your KPI setting")})
        period = cyc = None
    # once a result is released to them, the line manager's score and band are gone and the final band takes the row
    # (Chris, 2026-10-26: "once a result is released to the person, Where you stand drops the line manager's band and
    # shows the final bands"), whatever else still waits on them -- as the history and Details already show it
    if period and result_released(db, "pm", u["id"], period["id"]):
        fb = released_final_band(db, u, period["id"], "pm")
        out.append({"key": "performance", "label": "Final performance", "value": None, "band": fb,
                    "pending": None if fb else "Not recorded", "note": "After calibration, released by Group People"})
    elif period:
        overall = _dash_overall(db, u["id"], period["id"])
        out.append({
            "key": "performance", "label": "Performance rating",
            "value": (None if not overall or overall["value"] is None   # a transferred person's by-band blend has no figure
                      else ("%.1f" % overall["value"]) if overall["mechanism"] == "A" else ("%.1f%%" % overall["value"])),
            "band": (overall["label"] if overall else None),
            "pending": None if overall else "Awaiting your manager",
            "note": ("Approved by your line manager" if overall
                     else "Appears once every KPI line is approved"),
        })
    if cyc:
        ta = db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?", (cyc["id"], u["id"])).fetchone()
        n = db.execute("SELECT COUNT(*) FROM tc_assignments WHERE cycle_id=? AND subject_id=?",
                       (cyc["id"], u["id"])).fetchone()[0]
        if result_released(db, "pot", u["id"], cyc["id"]):   # released: the final potential band, never the count
            fb = released_final_band(db, u, cyc["id"], "pot")
            out.append({"key": "competency", "label": "Final potential", "band": fb, "value": None,
                        "pending": None if fb else "Not recorded", "note": "After calibration, released by Group People"})
        elif n and (asked or (ta and ta["status"] in ("submitted", "reviewed"))):
            if ta and _tc_status_eff(db, u["id"], ta["status"]) == "reviewed":   # or a submitted one nobody reviews (2026-11-06)
                yes = db.execute(
                    "SELECT COUNT(*) FROM tc_assignments a JOIN tc_scores sc ON sc.assignment_id=a.id "
                    "AND sc.assessment_id=? WHERE a.cycle_id=? AND a.subject_id=? "
                    "AND COALESCE(sc.manager_answer, sc.answer)='yes'", (ta["id"], cyc["id"], u["id"])).fetchone()[0]
                out.append({"key": "competency", "label": "Competency", "band": None,
                            "text": "%d of %d demonstrated" % (yes, n), "pending": None,
                            "note": ("Reviewed by your line manager" if ta["status"] == "reviewed"
                                     else "Submitted. Nobody reviews it, so your own answers count")})
            else:
                out.append({"key": "competency", "label": "Competency", "band": None,
                            "pending": ("With your manager" if (ta and ta["status"] == "submitted") else "Not submitted yet"),
                            "note": ("Your manager reviews it next" if (ta and ta["status"] == "submitted")
                                     else "Rate your competencies in your AI check-in")})
        rep_out = is_released(db, u["id"], cyc["id"])
        out.append({"key": "f360", "label": "360 feedback", "band": None,
                    "text": "Report released" if rep_out else None,
                    "pending": None if rep_out else "Not released yet",
                    "note": ("Open your 360 report" if rep_out else "Group People releases it after the cycle"),
                    # opens in the dashboard's panel, never the classic report page (2026-10-09)
                    "panel": "report" if rep_out else None, "panel_arg": cyc["id"] if rep_out else None})
    # Where this person is heading, if they've said. Not an outcome -- but it
    # is what the whole development half of the product hangs off, and a blank
    # one is a prompt rather than an absence.
    prof = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?",
                      (u["id"],)).fetchone()
    target = None
    if prof and prof["target_profile_id"]:
        target = db.execute("SELECT job_title, active FROM tc_job_profiles WHERE id=?",
                            (prof["target_profile_id"],)).fetchone()
    out.append({
        "key": "career", "label": "Career target", "value": None, "band": None,
        "text": (_tc_retired_title(target["job_title"], target["active"]) if target else None),
        "pending": None if target else "Not set yet",
        "note": "Open your Career Plan",   # in the dashboard's panel (2026-10-09)
        "panel": "plan" if cycle_module_on("idp", db) else None, "panel_arg": None,
    })
    return out


def dash_record(db, u):
    """One row per cycle, newest first -- the record reads downward so a
    trajectory is visible rather than three separate report cards. Nothing for someone whose user role doesn't show
    them their released results (Roles & access, 2026-10-20).

    The 360 cycle and the PM period are separate records that happen to run
    together, so they are matched by NAME. Both are admin-named and the naming
    now matches ("2026 Mid-Year"); anything that doesn't match simply stands
    on its own row rather than being dropped."""
    if not urole_allows(u, "results", db):
        return []
    # an Early Year (KPI setting only) has no result, so no row (2026-10-15)
    cycles_by_name = {c["name"]: c for c in db.execute(
        "SELECT * FROM cycles c WHERE NOT %s ORDER BY year DESC, half DESC, id DESC" % early_year_sql("c"))}
    rows = []
    seen = set()
    for p in db.execute("SELECT * FROM cycles c WHERE NOT %s ORDER BY year DESC, half DESC, id DESC"
                        % early_year_sql("c")):
        c = cycles_by_name.get(p["name"])
        if c:
            seen.add(c["name"])
        rows.append(_dash_record_row(db, u, p, c))
    for name, c in cycles_by_name.items():
        if name not in seen:
            rows.append(_dash_record_row(db, u, None, c))
    # Only rows this person actually appears in; an empty row is noise.
    return [r for r in rows if r["has_anything"]]


def _dash_record_row(db, u, period, cyc):
    overall = _dash_overall(db, u["id"], period["id"]) if period else None
    band = _dash_potential(db, u, cyc["id"]) if cyc else None
    talent = (talent_status_for(db, u, cyc["id"])
              if (period and cyc) else None)
    final_pm = released_final_band(db, u, period["id"], "pm") if period else None
    if talent and talent.get("imported") and talent.get("perf"):
        # a year from before OneHR with HR's bands (2026-10-22): they are its final bands, released with its status
        final_pm, band = final_pm or talent["perf"], band or talent["pot"]
    # A record you can only read is half a record -- each row opens the thing
    # behind it. Both links are gated on there being a RESULT to open: a
    # rating for the KPI page, a released band for the report. A half with
    # targets but no final rating stays unlinked -- an empty row that goes
    # nowhere is better than one that goes somewhere with nothing in it.
    idp = pm_idp_for(db, pm_idp_plan_year(period), u["id"]) if period else None
    goals = len(idp["goals"]) if idp else 0
    open_now = (bool((period and period["is_active"]) or (cyc and cyc["is_active"]))
                and not cycle_wound_down(db, period or cyc))   # 2026-10-15: a finished-for-employees cycle reads as past
    return {
        "name": (period["name"] if period else cyc["name"]),
        "open": open_now,
        "closed_on": (period["ends_on"] if period else (cyc["ends_on"] if cyc else None)),
        "overall": overall, "band": band, "talent": talent,
        # the FINAL performance band (after HOD / CEO calibration), once released (2026-10-02)
        "final_pm": final_pm,
        "kpi_url": (url_for("performance_my_view", period=period["id"])
                    if (period and overall) else None),
        # the 360 report opens once IT is released; the band beside it waits for the Potential release
        "report_url": (url_for("my_report", cycle=cyc["id"]) if (cyc and is_released(db, u["id"], cyc["id"]))
                       else None),
        "cycle_id": (cyc["id"] if cyc else None),
        "period_id": (period["id"] if period else None),
        "mid_year": cycle_is_mid_year(db, (period or cyc)["id"]),   # no talent status at Mid-Year (2026-10-12)
        # a cycle with no potential result: no potential band and no talent status, ever -- "none", not "not released"
        "no_pot": bool(cyc) and not cycle_has_potential(db, cyc["id"]),
        # the full record reads by YEAR (2026-10-14): each row knows its year and half
        "year": _cycle_year_half(period or cyc)[0], "half": _cycle_year_half(period or cyc)[1],
        "goals": goals,
        "idp_url": url_for("idp_view") if goals else None,
        "has_anything": bool(overall or band or talent or goals or open_now or (cyc and is_released(db, u["id"], cyc["id"]))),
    }


@app.route("/me")
@login_required
def my_profile():
    """The record, in full.

    Split out from the dashboard on purpose: a landing page answers "what
    needs me now" and is read daily; this answers "what is my track record"
    and is read at a career conversation. Squashing both onto one page is
    what made the second one look empty. Same split the benchmark HRMS
    products make between a home page and a worker/talent profile.

    This is also where training and movement will land once they have a data
    source -- their columns are already stated as missing rather than dropped.

    RETIRED 2026-10-31 (security stage 1, the classic pages' removal): no page links it; the dashboard's record panels
    hold the record. A GET goes to the dashboard. The body stays until stage 2 takes the route and its template out."""
    u = current_user()
    if is_admin(u):
        return redirect(url_for("admin_overview"))
    return redirect(url_for("dashboard"))
    db = get_db()
    prof = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?",
                      (u["id"],)).fetchone()
    target = None
    if prof and prof["target_profile_id"]:
        target = db.execute("SELECT * FROM tc_job_profiles WHERE id=?",
                            (prof["target_profile_id"],)).fetchone()
        if target and not target["active"]:   # a job retired in OneHR: the plan keeps it, marked
            target = dict(target, job_title=_tc_retired_title(target["job_title"], 0))
    cid = active_cycle_id(db)
    tc = db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                    (cid, u["id"])).fetchone() if cid else None
    return render_template(
        "my_profile.html",
        record=dash_record(db, u),
        label_names=PM_LABEL_NAMES,
        profile=prof, target=target, tc=tc)


# ---------------------------------------------------------------------------
# The record panel: a past cycle slides in from the right, with an AI snapshot (Chris, 2026-10-08: "For the past or
# completed reports, build a new view that slides from the right when clicked, and also add in AI element to the history
# record, like a quick summary or snapshot of how the person did or the past talent status").
#
# SELF-SCOPED and RELEASE-GATED throughout: the panel reads only the dashboard record's own rows (dash_record -- the
# line manager's approved rating once every line is locked, the FINAL bands only through released_final_band, the talent
# status only through talent_status_for, the 360 only inside a report_releases row) plus the person's own words. It never
# reads rating_records, a tier's band, talent_status_history, or any manager-side insight cache. The AI snapshot is built
# from that same case, checked against it, cached per person per cycle with the case in its fingerprint (a revoked
# release changes the case, so cached text about it is never served), and falls back to a reading from the figures.
# ---------------------------------------------------------------------------
_RECORD_AGREE = ((90, "seen consistently"), (75, "seen by most"), (40, "seen by some"), (0, "seen by few"))


def _record_agree_words(pct):
    """A 360 principle's agreement in words -- the record never shows a percentage or how many rated."""
    for floor, words in _RECORD_AGREE:
        if (pct or 0) >= floor:
            return words
    return "seen by few"


def _record_released(r):
    """Anything of this record row released to the person: the final performance band, the final potential band, or
    the talent status."""
    return bool(r.get("final_pm") or r.get("band") or r.get("talent"))


def _record_rows(db, u):
    """The cycles the history lists, newest first: the past ones, plus the current one once anything of it has been
    released to the person (Chris, 2026-10-08: the super admin releases "the final bands and talent status to user to
    be updated in the history record")."""
    return [r for r in dash_record(db, u) if (not r["open"]) or _record_released(r)]


def _record_key(r):
    return r.get("period_id") or r.get("cycle_id")


def _cycle_year_half(c):
    """A cycle's (year, half): its own columns, else read off its name ('2025 Year-End', '2026 Mid-Year'). Either is
    None when neither says. A legacy text half ('HY2') reads as its number."""
    if not c:
        return None, None
    name = _row_get(c, "name") or ""
    y = _row_get(c, "year")
    try:
        y = int(y) if y else None
    except (TypeError, ValueError):
        y = None
    if not y:
        m = re.search(r"\b(20\d\d)\b", name)
        y = int(m.group(1)) if m else None
    h0 = _row_get(c, "half")
    h = str(h0 if h0 is not None else "").strip().upper()
    h = 0 if h in ("0", "EY") else 1 if h in ("1", "HY1", "H1") else (2 if h in ("2", "HY2", "H2") else None)
    if h is None:
        h = (0 if re.search(r"early", name, re.I) else 1 if re.search(r"mid", name, re.I)
             else (2 if re.search(r"year[- ]?end", name, re.I) else None))
    return y, h


_RECORD_FINAL_TAG = "Final · decides your reward"
_RECORD_CHECK_TAG = "Checkpoint · after your HOD's review"


def _record_years(db, u, rows, as_of=None):
    """The full record by YEAR, newest first (Chris, 2026-10-14: "what is important to user is the final year score, as
    that determines the final reward, where mid year is only a checkpoint ... show it in year rather than cycle, then
    expand into mid year and year end, for the year display, use the year end result"; board A of the canvas "OneHR Full
    Record by Year"). Reads only the record's own rows (the released final bands and talent status), so it shows
    nothing the cycle rows don't.

    Each year: its Year-End row (the year's result), its Mid-Year rows (checkpoints), anything whose half isn't known,
    and a state for the Year-End --
      final        the Year-End is in the record with something of it released
      pending      the Year-End is in the record, nothing of it released yet
      running      no Year-End in the record and that year's Year-End is the open cycle
      coming       no Year-End in the record and none for that year yet (or, on the demo's cycle switch, not yet then)
      none         that year's Year-End is closed and holds nothing of theirs
    A year with no Year-End shows its latest checkpoint, labelled as one."""
    groups, order = {}, []
    for r in rows:
        k = r.get("year") or ("~%s" % _record_key(r))
        if k not in groups:
            groups[k] = []
            order.append(k)
        groups[k].append(r)
    order.sort(key=lambda k: (0, -k) if isinstance(k, int) else (1, 0))
    active = db.execute("SELECT * FROM cycles WHERE is_active=1 ORDER BY id DESC LIMIT 1").fetchone()
    act_yh = _cycle_year_half(active) if active else (None, None)
    today = _today_myt().isoformat()
    upto = set((as_of or {}).get("upto") or [])

    def _later(c):
        """A Year-End not reached yet: after the open cycle, or not started yet (an admin creates one ahead)."""
        cy_, ch_ = _cycle_year_half(c)
        if act_yh[0] and cy_ and (cy_, ch_ or 0) > (act_yh[0], act_yh[1] or 0):
            return True
        return bool(_row_get(c, "starts_on") and str(_row_get(c, "starts_on"))[:10] > today)
    out = []
    for k in order:
        rs = groups[k]
        year = k if isinstance(k, int) else None
        ye = next((r for r in rs if r.get("half") == 2), None)
        mids = [r for r in rs if r.get("half") == 1]
        rest = [r for r in rs if r is not ye and r.get("half") != 1]
        released = bool(ye and _record_released(ye))
        closes = None
        if ye:
            state = "final" if released else "pending"
        elif year is None:
            state = "none"
        else:
            yes = [c for c in db.execute("SELECT * FROM cycles WHERE year=? OR name LIKE ?", (year, "%%%d%%" % year))
                   if _cycle_year_half(c) == (year, 2)]
            if as_of:
                state = "none" if any(c["id"] in upto for c in yes) else "coming"
            elif active and any(c["id"] == active["id"] for c in yes):
                state = "running"
                # a calendar date (a time after it once left "2027-01-31" unformatted, 2026-10-26)
                closes = _myt_date_str(str(active["ends_on"])[:10]) if active["ends_on"] else None
            elif not yes or any(_later(c) for c in yes):
                state = "coming"
            else:
                state = "none"
        check = mids[0] if mids else (rest[0] if rest else None)
        if state == "final":
            sub = ("Year-End result · released to you" if ye.get("open") else
                   "Year-End result · closed %s" % ye["closed_on"] if ye.get("closed_on") else "Year-End result")
            if not mids and year:
                sub = "Year-End result · no Mid-Year on record"
        elif state == "pending":
            sub = "Year-End closed%s · not released to you yet" % (" " + ye["closed_on"] if ye.get("closed_on") else "")
        elif state == "running":
            sub = "Year-End in progress · closes %s" % closes if closes else "Year-End in progress"
        elif state == "coming":
            sub = "Year-End still to come"
        else:
            sub = "No Year-End on record" if year else "Not a Mid-Year or a Year-End"
        cycles = []
        if ye:
            cycles.append({"r": ye, "kind": "Year-End", "final": True, "tag": _RECORD_FINAL_TAG})
        elif state in ("running", "coming"):
            cycles.append({"r": None, "kind": "Year-End", "final": True, "tag": _RECORD_FINAL_TAG,
                           "sub": "In progress" if state == "running" else "Not started yet",
                           "note": "Your result comes after calibration and Group People's release."})
        cycles += [{"r": m, "kind": "Mid-Year", "final": False, "tag": _RECORD_CHECK_TAG} for m in mids]
        cycles += [{"r": x, "kind": x["name"], "final": False, "tag": ""} for x in rest]
        out.append({"year": year, "label": str(year) if year else rs[0]["name"], "state": state, "sub": sub,
                    "ye": ye, "check": None if ye else check, "cycles": cycles})
    return out


def _record_panel(db, u, key, rows=None):
    """ONE cycle of the history for the record panel, or None when it isn't one of this person's (a spoofed id never
    falls back to another). Chris, 2026-10-08: "for past cycle record, we should only show the final band for
    performance and potential and user wouldn't be able to look into their KPI table as it will show different results
    and raise confusion. What is important is the talent status ... User gets to see their full IDP history in details
    and their LM remarks on it. User will also able to view the 360 report. For KPI, competency, only the calibrated
    bands are shown without the details." So: the FINAL bands and the talent status, each only once released; the 360
    once released; the plan in full with the manager's remark. Never a KPI line, a competency answer, a line manager's
    score or a tier's band."""
    rows = _record_rows(db, u) if rows is None else rows
    i = next((n for n, r in enumerate(rows) if key in (r.get("period_id"), r.get("cycle_id"))), None)
    if i is None:
        return None
    r = rows[i]
    pid, cid = r.get("period_id"), r.get("cycle_id")
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (pid or cid,)).fetchone()
    report = _record_report(db, u, cid)
    talks = bool(cid and db.execute("SELECT 1 FROM pm_review_chat WHERE subject_id=? AND cycle_id=? LIMIT 1",
                                    (u["id"], cid)).fetchone())
    fin = r.get("final_pm")
    return {
        "mode": "record", "key": key, "name": r["name"], "current": bool(r["open"]),
        "closed_on": (_myt_date_str(r.get("closed_on")) if (r.get("closed_on") and not r["open"]) else None),
        "newer": _record_key(rows[i - 1]) if i > 0 else None,
        "older": _record_key(rows[i + 1]) if i + 1 < len(rows) else None,
        "position": i + 1, "count": len(rows),
        "final": {"pm": ({"band": fin, "name": PM_LABEL_NAMES.get(fin, fin)} if fin else None),
                  "pot": r.get("band")},
        "talent": r.get("talent"),
        "mid_year": bool(r.get("mid_year")),   # final after the HOD's review, no talent status (2026-10-12)
        "no_pot": bool(r.get("no_pot")),       # the cycle has no potential result (cycle_has_potential)
        "report": report,
        "plan": _record_plan(db, u, cyc),
        "comp_calls": _record_comp_calls(db, u, cid),
        "links": {"report": (report or {}).get("url"), "report_cycle": (report or {}).get("cycle"),
                  "conversation": (url_for("review_history", cycle=cid) if talks else None)},
    }


def _record_comp_calls(db, u, cid):
    """The line manager's review of their competencies, in words only (Chris, 2026-10-18: once released a person sees
    "their LM moderated strongest and weakest competencies (without score)"). Strongest: where the manager said they
    already show the NEXT level (a future row demonstrated); to grow: still developing at their CURRENT level (a current
    row not demonstrated). Titles only, up to 3 each, never a count or a score. None unless the review is done."""
    if not cid:
        return None
    ta = db.execute("SELECT id, status FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                    (cid, u["id"])).fetchone()
    if not ta or ta["status"] != "reviewed":
        return None
    strong, grow = [], []
    for r in db.execute(
            "SELECT a.is_future, s.title, COALESCE(sc.manager_answer, sc.answer) AS ans FROM tc_assignments a "
            "JOIN tc_skills s ON s.id=a.skill_id LEFT JOIN tc_scores sc ON sc.assignment_id=a.id AND sc.assessment_id=? "
            "WHERE a.cycle_id=? AND a.subject_id=? ORDER BY s.skill_category, s.title", (ta["id"], cid, u["id"])):
        if r["is_future"] and r["ans"] == "yes" and r["title"] not in strong:
            strong.append(r["title"])
        if not r["is_future"] and r["ans"] == "no" and r["title"] not in grow:
            grow.append(r["title"])
    strong = [t for t in strong if t not in grow]
    return {"strong": strong[:3], "grow": grow[:3]}


def _record_report(db, u, cid):
    """The 360 of one season in words (strongest / to grow), once its report is released -- or None."""
    if not (cid and is_released(db, u["id"], cid)):
        return None
    rp = _report_season_principles(db, u, cid)
    ps = sorted([p for p in rp["principles"] if p["total"]], key=lambda p: -p["pct"])
    top = ps[0]["pct"] if ps else 0
    strong = [p for p in ps if p["pct"] == top][:2] if ps else []
    grow = [p for p in reversed(ps) if p["pct"] < top][:2]
    return {"strong": [{"name": p["description"] or p["name"], "short": p["name"],
                        "words": _record_agree_words(p["pct"])} for p in strong],
            "grow": [{"name": p["description"] or p["name"], "short": p["name"],
                      "words": _record_agree_words(p["pct"])} for p in grow],
            "even": bool(ps) and not grow,
            "cycle": cid, "url": url_for("my_report", cycle=cid)}


def _record_plan(db, u, period):
    """The development plan for a cycle's plan year (_record_plan_year), or None."""
    if not period:
        return None
    return _record_plan_year(db, u, pm_idp_plan_year(period))


def _record_plan_year(db, u, year):
    """The development plan for one plan year, in full: each goal's area, target date, its 70:20:10 actions and
    where it got to, and the line manager's remark -- the plan's own, and any on a goal. A manager's remark shows once
    the plan is closed, or once its year is behind the one being planned now (the box autosaves as they type, so an
    open review's half-written remark never surfaces early, 2026-09-29). None when there is no plan."""
    if not year:
        return None
    idp = pm_idp_for(db, year, u["id"])
    if not idp:
        return None
    now_year = pm_idp_plan_year(active_pm_period(db)) if active_pm_period(db) else None
    show_lm = idp["status"] == "closed" or (now_year is not None and (year or 0) < now_year)
    prog = {p["key"]: p["label"] for p in PM_IDP_PROGRESS}
    log = _idp_checkin_log(db, [g["id"] for g in idp["goals"]])
    goals = []
    for g in idp["goals"]:
        area = (g.get("area") or "").strip()
        if not area:
            continue
        goals.append({
            "id": g["id"], "status": g.get("progress_status") or "not_started",
            "checkins": log.get(g["id"], []),
            "area": area, "target_date": _plan_target_str(g.get("target_date")),
            "actions": [{"label": m["label"], "pct": m["pct"], "text": (g.get("action_" + m["key"]) or "").strip()}
                        for m in PM_IDP_MODES if (g.get("action_" + m["key"]) or "").strip()],
            "progress": prog.get(g.get("progress_status")) if g.get("progress_status") else None,
            "progress_note": (g.get("progress_note") or "").strip() or None,
            "lm_comment": ((g.get("manager_comment") or "").strip() or None) if show_lm else None,
        })
    takes = plan_takes_checkins(idp["status"], idp.get("shared_at"), year)
    nobody = idp["status"] == "shared" and _idp_chair_unreviewed(db, u["id"])   # nobody reviews it: final once shared (2026-11-06)
    return {"year": year, "status": idp["status"], "final": nobody,
            "status_label": {"draft": "Draft", "shared": "Shared" if nobody else "Shared with your manager",
                             "closed": "Approved" if idp.get("shared_at") else "Closed"}.get(idp["status"],
                                                                                              idp["status"]),
            "shared_on": _myt_date_str(idp["shared_at"]) if idp.get("shared_at") else None,
            "closed_on": _myt_date_str(idp["closed_at"]) if idp.get("closed_at") else None,
            "goals": goals,
            # a shared plan, approved or not, takes check-ins through its year (plan_takes_checkins), between cycles
            # only (plan_checkin_open); a draft isn't agreed yet, and once its year is over the plan is the record
            "can_checkin": takes and plan_checkin_open(db, u),
            "checkin_paused": takes and not plan_checkin_open(db, u),
            "checkin_ended": not takes and plan_takes_checkins(idp["status"], idp.get("shared_at")),
            "last_checkin": _myt_date_str(max((c_["on_at"] for l_ in log.values() for c_ in l_), default=None)),
            "lm_remark": ((idp.get("manager_comment") or "").strip() or None) if show_lm else None,
            "lm_pending": (not show_lm) and idp["status"] == "shared" and not nobody}


def _record_present(db, u):
    """THIS cycle in detail, up to the line manager's level and no further (Chris, 2026-10-08: "user can view their
    present cycle status and record in detail but it stops at LM approved level, HOD, BUCEO and BGCEO will be hidden
    from user display"): their KPI lines with the manager's figure once a line is locked, the overall the manager
    approved, the manager's remarks once every line is locked; their competency answers with the manager's calls once
    reviewed; the 360 once released; their plan. Never a calibrated band -- those reach the history once released."""
    cyc = active_cycle(db)
    period = active_pm_period(db)
    if not (cyc or period):
        return None
    pid = (period or cyc)["id"]
    perf = _pm_period_summary(db, u, pid)
    all_locked = bool(perf["lines"]) and all(ln["locked"] for ln in perf["lines"])
    mrem = ([{"author": r["author"] or "Your manager", "remark": r["remark"]} for r in db.execute(
        "SELECT r.remark, u.full_name AS author FROM pm_manager_remarks r LEFT JOIN users u ON u.id=r.submitted_by "
        "WHERE r.cycle_id=? AND r.subject_id=? AND TRIM(COALESCE(r.remark,'')) != '' ORDER BY r.submitted_at",
        (pid, u["id"]))] if all_locked else [])
    own = db.execute("SELECT remark FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=? AND draft=0",
                     (pid, u["id"])).fetchone()
    comp = None
    cid = (cyc or period)["id"]
    ta = db.execute("SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?", (cid, u["id"])).fetchone()
    items = db.execute(
        "SELECT a.id, a.is_future, s.title, s.skill_category, s.level, s.proficiency_description, s.ability_items, "
        "sc.answer, sc.manager_answer "
        "FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
        "LEFT JOIN tc_scores sc ON sc.assignment_id=a.id AND sc.assessment_id=? "
        "WHERE a.cycle_id=? AND a.subject_id=? ORDER BY s.skill_category, s.title, a.is_future",
        ((ta["id"] if ta else -1), cid, u["id"])).fetchall()
    if items:
        reviewed = bool(ta and ta["status"] == "reviewed")
        by = {}
        for it in items:
            k = (it["skill_category"] or "", it["title"])
            by.setdefault(k, {"title": it["title"], "category": it["skill_category"] or "", "you": [], "lm": [],
                              "levels": []})
            by[k]["you"].append(it["answer"])
            # what each level means, now and next (2026-10-18): the description, then the abilities that show it
            by[k]["levels"].append({"future": bool(it["is_future"]), "level": it["level"],
                                    "desc": (it["proficiency_description"] or "").strip(),
                                    "abilities": _tc_ability_list(it["ability_items"])})
            if reviewed:
                by[k]["lm"].append(it["manager_answer"] or it["answer"])
        comp = {"status": (ta["status"] if ta else "pending"), "reviewed": reviewed,
                # a submitted one nobody reviews (the Executive Chairman's direct report, 2026-11-06) is final as it stands
                "final": bool(ta and ta["status"] == "submitted" and _tc_chair_unreviewed(db, u["id"])),
                "items": list(by.values()),
                "lm_yes": (sum(1 for it in items if (it["manager_answer"] or it["answer"]) == "yes") if reviewed else None),
                "total": len(items),
                "own_remark": ((ta["overall_remark"] or "").strip() or None) if ta else None,
                # their line manager's remark only once their potential result is released to them (Chris,
                # 2026-10-21): it may be written with their 360 in view, which they haven't seen until then
                "lm_remark": (((ta["manager_overall_remark"] or "").strip() or None)
                              if (ta and reviewed and result_released(db, "pot", u["id"], cid)) else None)}
    c_ = cyc or period
    y_, h_ = _row_get(c_, "year"), _row_get(c_, "half")
    title = ("%s %s" % (y_, "Year-End" if _is_year_end(c_) else "Mid-Year") if (y_ and h_)
             else (re.sub(r"\s*\([^)]*\)", "", c_["name"] or "").strip() or c_["name"]))
    rep = _record_report(db, u, cid)
    last = None
    if not rep:   # the 360 tab's way to the last report HR did release (This cycle in detail, 2026-10-11)
        for c2 in db.execute("SELECT id, name FROM cycles WHERE id != ? ORDER BY id DESC LIMIT 12", (cid,)).fetchall():
            if is_released(db, u["id"], c2["id"]):
                last = {"cycle": c2["id"], "name": re.sub(r"\s*\([^)]*\)", "", c2["name"] or "").strip() or c2["name"]}
                break
    prof = tc_profile_for_user(db, u)[0] if comp else None
    return {"mode": "present", "key": "current", "name": title, "cycle_id": cid,
            # started, nothing open yet (2026-10-18): Details shows the targets and the competencies, nothing to do
            "awaiting": bool(cyc and cycle_awaiting_open(db, cyc)),
            "job": ({"title": prof.get("job_title"), "grade": prof.get("job_grade")} if prof else None),
            "perf": {"lines": perf["lines"], "overall": perf["overall"], "all_locked": all_locked,
                     "scale": perf.get("scale"),
                     # a transferred person's Mid-Year half (the toggle), until their result is released to them (2026-11-03)
                     "split_mid": _split_mid_payload(db, u, pid, "employee"),
                     "lm_remarks": mrem, "own_remark": ((own["remark"] or "").strip() if own else "")},
            "competency": comp,
            "report": rep, "report_last": last,
            "plan": _record_plan(db, u, period or cyc),
            "plan_year": pm_idp_plan_year(period or cyc)}


def _rp_num(v):
    """A KPI figure as the record shows it: 12, 12.5 -- never 12.0."""
    try:
        return "%g" % float(v)
    except (TypeError, ValueError):
        return str(v)


_NUM_WORDS = ("zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve")


def _rp_count(n):
    """A count for the model's case as '3 (three)', so the read may say either: the live probe (2026-10-12) had a
    correct 'three goals' refused because the case only said 3."""
    n = int(n or 0)
    return "%d (%s)" % (n, _NUM_WORDS[n]) if 0 <= n < len(_NUM_WORDS) else str(n)


def _rp_lower(t):
    """'Shared with your manager' as it reads mid-sentence."""
    t = (t or "").strip()
    return t[:1].lower() + t[1:] if t[:2] != t[:2].upper() else t


def _record_present_case(p):
    """The case for the AI read of the cycle in progress -- ONLY what the person can see in This cycle in detail: their
    KPI lines (an approved figure and rating only once their line manager approved the line), the competency review,
    the 360 only once released, and their plan. Never a calibrated band: none is in the present record."""
    out = ["Cycle in progress: %s." % p["name"]]
    pf = p.get("perf") or {}
    lines = pf.get("lines") or []
    for ln in lines:
        unit = (" " + ln["unit"]) if ln.get("unit") else ""
        bit = "KPI '%s' (weight %s%%): you entered %s." % (ln["name"], _rp_num(ln.get("weightage")),
                                                           (_rp_num(ln["self"]) + unit) if ln.get("self") is not None else "nothing yet")
        if ln.get("locked"):
            bit += " Your line manager approved %s%s" % (
                (_rp_num(ln["moderated"]) + unit) if ln.get("moderated") is not None else "it",
                (", rating " + PM_LABEL_NAMES.get(ln["label"], ln["label"])) if ln.get("label") else "") + "."
        else:
            bit += " Waiting for your line manager's approval."
        out.append(bit)
    if lines:
        n_ok = sum(1 for ln in lines if ln.get("locked"))
        out.append("Your line manager has approved %s of your %s KPI lines." % (_rp_count(n_ok), _rp_count(len(lines))))
    ov = pf.get("overall")
    if ov:
        out.append("The overall your line manager approved: %s." % (ov.get("label_name") or ov.get("label") or ""))
    c = p.get("competency")
    if c:
        if c.get("reviewed"):
            dev = [it["title"] for it in c["items"] if any(x != "yes" for x in (it.get("lm") or []))]
            out.append("Competency review by your line manager: %s of %s demonstrated%s." % (
                _rp_count(c.get("lm_yes")), _rp_count(c.get("total")), ("; to develop: " + ", ".join(dev[:4])) if dev else ""))
        elif c.get("final"):
            out.append("Your competency self-assessment is submitted. Nobody reviews it, so your own answers count.")
        elif c.get("status") == "submitted":
            out.append("Your competency self-assessment is submitted and waiting for your line manager's review.")
        else:
            answered = sum(1 for it in c["items"] for a in it["you"] if a in ("yes", "no"))
            out.append("Your competency self-assessment is not submitted yet: %s of %s answered." % (
                _rp_count(answered), _rp_count(c.get("total") or 0)))
    rp = p.get("report")
    if rp:
        if rp.get("strong"):
            out.append("Your 360 (released to you): colleagues saw these as your strengths: %s." % ", ".join(x["name"] for x in rp["strong"]))
        if rp.get("grow"):
            out.append("Where colleagues would like to see more: %s." % ", ".join(x["name"] for x in rp["grow"]))
    else:
        out.append("Your 360 report for this cycle is released by Group People after calibration.")
    pl = p.get("plan")
    if pl:
        out.append("Your %s development plan is %s, with %s goal(s): %s." % (
            pl.get("year"), _rp_lower(pl.get("status_label")) or "started", _rp_count(len(pl.get("goals") or [])),
            "; ".join(g.get("area") or "" for g in (pl.get("goals") or [])[:4])))
    else:
        out.append("Your %s development plan is not started yet." % p.get("plan_year"))
    return "\n".join(out)


def _record_present_plain(p):
    """The read of the cycle in progress built from the figures alone -- it cannot invent."""
    bits = []
    lines = (p.get("perf") or {}).get("lines") or []
    if lines:
        n_ok = sum(1 for ln in lines if ln.get("locked"))
        bits.append("Your line manager has approved %d of your %d KPI lines." % (n_ok, len(lines)) if n_ok
                    else "Your %d KPI lines are with your line manager." % len(lines))
    c = p.get("competency")
    if c:
        bits.append("Your competency review is back: %s of %s demonstrated." % (c.get("lm_yes"), c.get("total"))
                    if c.get("reviewed") else ("Your competency self-assessment is submitted, and your own answers count."
                                               if c.get("final") else
                                               "Your competency self-assessment is with your line manager."
                                               if c.get("status") == "submitted" else "Your competency self-assessment is still to submit."))
    bits.append("Your 360 report is released." if p.get("report") else "Group People releases your 360 after calibration.")
    pl = p.get("plan")
    bits.append(("Your %s plan is %s, with %d goal%s." % (pl.get("year"), _rp_lower(pl.get("status_label")) or "started",
                 len(pl.get("goals") or []), "" if len(pl.get("goals") or []) == 1 else "s")) if pl
                else "Your %s plan isn't started yet." % p.get("plan_year"))
    return " ".join(bits)


def _record_present_snapshot(db, u, p, generate=False):
    """(text, source) of the AI read of the cycle in progress -- 'ai', or 'plain' from the figures; (None, None) when not
    cached and generate is False. Cached under the cycle's NEGATIVE id, beside that cycle's past-record snapshot."""
    src = _record_present_case(p)

    def _make(ai_ok):
        if ai_ok:
            try:
                raw = ai_draft.summarise_record((_row_get(u, "full_name") or "").split(" ")[0], src, kind="present")
                obj = json.loads(re.sub(r"^```(?:json)?|```$", "", (raw or "").strip()).strip(), strict=False)
                txt = _insight_polish(obj.get("snapshot") or "").strip()
                err = _record_snapshot_error(src, txt) or (len(txt.split()) > 75 and "too long")
                if not err:
                    return txt, "ai"
                app.logger.info("present snapshot refused for %s: %s", u["id"], err)
            except Exception as e:
                app.logger.info("present snapshot fell back for %s: %s", u["id"], e)
        return _record_present_plain(p), "plain"
    return _record_cache(db, u["id"], -int(p["cycle_id"]), src, "present", _make if generate else None)


def _plan_target_str(v):
    """A goal's target date as the plan shows it: an ISO date reads '31 Dec 2026'; anything typed free-form stays as typed."""
    s_ = str(v or "").strip()
    if not s_:
        return None
    try:
        return datetime.strptime(s_, "%Y-%m-%d").strftime("%d %b %Y").lstrip("0")
    except ValueError:
        return s_


def _myt_date_str(v):
    """A stored date or UTC timestamp as the record shows it ('15 Jan 2026'); a bare date is a calendar date a person
    set (ends_on) and is never shifted."""
    s_ = str(v or "").strip()
    if not s_:
        return None
    try:
        if len(s_) <= 10:
            d = datetime.strptime(s_[:10], "%Y-%m-%d")
        else:
            d = datetime.strptime(s_[:19], "%Y-%m-%d %H:%M:%S") + timedelta(hours=8)
        return d.strftime("%d %b %Y").lstrip("0")
    except ValueError:
        return s_[:10]


def _record_case(p):
    """(case text, facts) for the AI snapshot -- ONLY the panel's own content (the released final bands, talent status,
    360 and plan), so the model can't be shown anything the person can't see, nor a KPI result."""
    out = ["Cycle: %s" % p["name"]]
    imp = bool(p["talent"] and p["talent"].get("imported"))
    if p["final"]["pm"]:
        out.append(("Your performance band that year, from Group People's records before OneHR: %s." if imp else
                    "Your final performance band after calibration (released to you): %s.") % p["final"]["pm"]["name"])
    if p["final"]["pot"]:
        out.append(("Your potential band that year, from Group People's records before OneHR: %s." if imp else
                    "Your final potential band after calibration (released to you): %s.") % p["final"]["pot"])
    if imp:
        out.append("Your talent status for this year, from Group People's records before OneHR: %s.%s" % (
            p["talent"]["name"], "" if p["talent"].get("perf") else
            " No performance or potential band was recorded that year."))
    elif p["talent"]:
        out.append("Your talent status (released to you): %s." % p["talent"]["name"])
    rep = p["report"]
    if rep:
        if rep["strong"]:
            out.append("Your 360 (released to you), strongest: %s" % "; ".join(
                "%s (%s)" % (x["name"], x["words"]) for x in rep["strong"]))
        if rep["grow"]:
            out.append("Your 360, where colleagues would like to see more: %s" % "; ".join(
                "%s (%s)" % (x["name"], x["words"]) for x in rep["grow"]))
        if rep["even"]:
            out.append("Your 360: your colleagues saw every principle about the same.")
        if not (rep["strong"] or rep["grow"] or rep["even"]):
            out.append("Your 360 report was released to you.")
    pl = p["plan"]
    if pl and pl["goals"]:
        out.append("Your development plan for %s (%s): %s." % (pl["year"], pl["status_label"].lower(),
                                                              "; ".join(g["area"] for g in pl["goals"][:5])))
        if pl["lm_remark"]:
            out.append("Your line manager's remark on the plan: \"%s\"" % pl["lm_remark"][:600])
    return "\n".join(out), {"name": p["name"]}


# Ordinary words a snapshot may add beyond the case (no numbers, no bands -- those must come from the case).
_RECORD_VOCAB = (
    "you your you're yours yourself the a an and or but with without while both each every all any some most more less "
    "than this that these those there is are was were be been being has have had not no yet still also only just even "
    "well strong stronger strongest solid clear clearly mixed steady good great held hold holds lifted lift carried "
    "carry drove drive driven led lead pulled pull kept keep came come ended end finished finish landed land result "
    "results rating ratings rated overall half year cycle period target targets ahead behind short of on above below "
    "beyond your colleagues colleague saw see seen most where like would more growth grow area areas strength strengths "
    "principle principles leadership 360 feedback plan plans goal goals development took take taking focus focused on "
    "after calibration final band status talent released performance potential kpi kpis remark wrote written said "
    "own up down from to for in at as it its into over across along by which what how when then so too very "
    "biggest main key highlight highlights mark marked line manager approved approval achievement they they'd they're "
    "they've their them rose risen rising climbed improved moved stayed dipped slipped fell went each checkpoint "
    "checkpoints"
)
_RECORD_STARTERS = frozenset((
    "you your this that the a an in on over across after with by colleagues overall a strong solid steady it "
    "looking still and but they they'd they're their").split())
_RECORD_ADVICE_RE = re.compile(
    r"\b(pay|bonus|salary|promotion|promote\w*|increment|raise)\b|"
    r"\b(should|ought to|deserved?|merited?)\b[^.]{0,40}\b(rated|rating|band|higher|lower|status)\b", re.I)


def _record_snapshot_error(src, text):
    """Why the model's snapshot may not be shown, or None: grounded in the case, a band or talent status only if the
    case gives it (only released ones are in it), and nothing about pay, promotion or what the rating should have been."""
    t = (text or "").strip().replace("\u2019", "'").replace("\u2018", "'")   # "They’d" reads as "They'd"
    if not t:
        return "empty"
    low = (src or "").lower()
    for nm in list(PM_LABEL_NAMES.values()) + list(TALENT_CATEGORY_SLUG.keys()):
        if re.search(r"\b%s\b" % re.escape(nm.lower()), t.lower()) and nm.lower() not in low:
            return "names %s, which isn't in the record" % nm
    if re.search(r"\b(low|mid|medium|high)[- ]potential\b|\bpotential (?:band )?(?:was |is |of |at )?(low|mid|medium|high)\b",
                 t, re.I) and "potential band" not in low:
        return "names a potential band that wasn't released"
    if _RECORD_ADVICE_RE.search(t):
        return "advice on pay, promotion or a rating"
    return _summary_grounding_error(src, "", t, _RECORD_VOCAB, _RECORD_STARTERS, "record_snapshot", ratio=0.4, floor=6)


def _record_snapshot_plain(p):
    """The snapshot built ONLY from what was released and the plan -- it cannot invent."""
    bits = []
    # a year from before OneHR was never calibrated here: its bands and status are HR's record of it (2026-10-22)
    imp = bool(p["talent"] and p["talent"].get("imported"))
    if imp:
        bits.append("From Group People's records before OneHR:")
    if p["final"]["pm"]:
        bits.append(("Your performance band was %s." if imp else "After calibration your final performance band was %s.")
                    % p["final"]["pm"]["name"])
    if p["final"]["pot"]:
        bits.append(("Your potential band was %s." if imp else "Your final potential band was %s.") % p["final"]["pot"])
    if p["talent"]:
        bits.append("Your talent status was %s." % p["talent"]["name"])
    rep = p["report"]
    if rep and rep["strong"]:
        bits.append("Your colleagues saw %s most." % rep["strong"][0]["name"])
    elif rep:
        bits.append("Your 360 report was released to you.")
    pl = p["plan"]
    if pl and pl["goals"]:
        n = len(pl["goals"])
        bits.append("Your %s plan had %d goal%s." % (pl["year"], n, "" if n == 1 else "s"))
    return " ".join(bits) or "Nothing from this cycle has been released to you yet."


def _record_cache(db, uid, key, src, kind, make):
    """The cached AI text for one panel (key = the cycle) or the trend (key = 0): reused while the case is unchanged; a
    plain one is retried after 10 minutes while the model is up. `make` returns (text, source)."""
    fp = hashlib.sha256(("v2\n%s\n%s\n%s" % (kind, src, ai_draft.summary_signature())).encode("utf-8")).hexdigest()
    row = db.execute("SELECT data, source, fingerprint, (created_at < datetime('now','-10 minutes')) AS stale "
                     "FROM record_snapshots WHERE subject_id=? AND cycle_id=?", (uid, key)).fetchone()
    ai_ok = bool(ai_draft.is_configured()) and ai_on("ai_review")
    if row and row["fingerprint"] == fp and not (row["source"] == "plain" and row["stale"] and ai_ok):
        return row["data"], row["source"]
    if make is None:
        return None, None
    text, source = make(ai_ok)
    db.execute("INSERT INTO record_snapshots(subject_id, cycle_id, fingerprint, data, source, created_at) "
               "VALUES (?,?,?,?,?,datetime('now')) ON CONFLICT(subject_id, cycle_id) DO UPDATE SET "
               "fingerprint=excluded.fingerprint, data=excluded.data, source=excluded.source, "
               "created_at=excluded.created_at", (uid, key, fp, text, source))
    db.commit()
    return text, source


# A sentence about what the record does NOT hold ("No development plan details were provided.") -- the GPT-6 Luna probe
# (2026-10-08) found the model narrating the gaps in its case, which reads to an employee like a system message.
_RECORD_MISSING_RE = re.compile(
    r"\b(provided|included|includes|information|available)\b|\bnot (?:yet )?released\b|"
    r"\bno (?:released |final )?(?:bands?|talent|plan|development|360|feedback|remark|details|outcomes?)\b", re.I)


def _record_tidy(text):
    """The snapshot without any sentence about what isn't in the record; '' when nothing else is left."""
    sents = re.split(r"(?<=[.!?])\s+", (text or "").strip())
    return " ".join(x for x in sents if x and not _RECORD_MISSING_RE.search(x)).strip()


def _record_snapshot(db, u, p, generate=False):
    """(text, source) of the panel's AI snapshot -- 'ai', or 'plain' from the figures; (None, None) when not cached and
    generate is False. A record holding nothing but its cycle's name never goes to the model."""
    src, _facts = _record_case(p)
    has_content = len(src.strip().splitlines()) > 1

    def _make(ai_ok):
        if ai_ok and has_content:
            try:
                raw = ai_draft.summarise_record((_row_get(u, "full_name") or "").split(" ")[0], src, kind="cycle")
                obj = json.loads(re.sub(r"^```(?:json)?|```$", "", (raw or "").strip()).strip(), strict=False)
                txt = _record_tidy(_insight_polish(obj.get("snapshot") or ""))
                err = _record_snapshot_error(src, txt) or (len(txt.split()) > 75 and "too long")
                if not err:
                    return txt, "ai"
                app.logger.info("record snapshot refused for %s: %s", u["id"], err)
            except Exception as e:
                app.logger.info("record snapshot fell back for %s: %s", u["id"], e)
        return _record_snapshot_plain(p), "plain"
    return _record_cache(db, u["id"], p["key"], src, "cycle", _make if generate else None)


def _record_trend_lines(db, u, rows):
    """The trend's lines, oldest first: each year's Year-End result -- its RELEASED final performance band and talent
    status -- and, for the newest year while its Year-End is still to come, its Mid-Year checkpoint, said as one
    (2026-10-14: the year-end result decides the reward; a mid-year is only a checkpoint). Never a line manager's score."""
    def bits(r):
        b = ["final performance band %s" % PM_LABEL_NAMES.get(r["final_pm"], r["final_pm"])]
        if r.get("talent"):
            b.append("talent status %s" % r["talent"]["name"])
        return "; ".join(b)
    years = _record_years(db, u, rows)
    lines = []
    for g in reversed(years[:4]):
        if g["ye"] and g["ye"].get("final_pm"):
            lines.append(("ye", g, "- %s Year-End, the year's final result: %s" % (g["label"], bits(g["ye"]))))
    top = years[0] if years else None
    if (top and top["year"] and top["state"] in ("pending", "running", "coming")
            and not (top["ye"] and top["ye"].get("final_pm"))):
        ck = next((c["r"] for c in top["cycles"] if c["r"] is not None and not c["final"]), None)
        if ck and ck.get("final_pm"):
            lines.append(("ck", top, "- %s Mid-Year checkpoint, not a final result (the %s Year-End result is still "
                                     "to come): %s" % (top["label"], top["label"], bits(ck))))
    return lines


def _record_trend_case(db, u, rows):
    """The trend's case (needs two lines): the Year-End results, oldest first, and the newest year's checkpoint while
    its Year-End is still to come."""
    lines = _record_trend_lines(db, u, rows)
    if len(lines) < 2:
        return ""
    return ("Your review years, oldest to newest. A Year-End result is that year's final result; a Mid-Year is only "
            "a checkpoint on the way:\n" + "\n".join(l_[2] for l_ in lines))


def _record_trend_plain(db, u, rows):
    lines = _record_trend_lines(db, u, rows)
    if len(lines) < 2:
        return None
    yes = [g for kind, g, _ in lines if kind == "ye"]
    ck = next((g for kind, g, _ in lines if kind == "ck"), None)
    out = ""
    if len(yes) >= 2:
        a_, b_ = yes[0]["ye"], yes[-1]["ye"]
        la, lb = (PM_LABEL_NAMES.get(x["final_pm"], x["final_pm"]) for x in (a_, b_))
        tail = ""
        if a_.get("talent") and b_.get("talent") and a_["talent"]["name"] != b_["talent"]["name"]:
            tail = ", and your talent status from %s to %s" % (a_["talent"]["name"], b_["talent"]["name"])
        if la == lb:
            out = "Your Year-End result has held at %s from %s to %s%s." % (la, yes[0]["label"], yes[-1]["label"], tail)
        else:
            out = "Your Year-End result went from %s in %s to %s in %s%s." % (la, yes[0]["label"], lb, yes[-1]["label"],
                                                                            tail)
    elif yes:
        out = "Your %s Year-End result was %s." % (yes[0]["label"], PM_LABEL_NAMES.get(yes[0]["ye"]["final_pm"],
                                                                                      yes[0]["ye"]["final_pm"]))
    if ck:
        r = next(c["r"] for c in ck["cycles"] if c["r"] is not None and not c["final"])
        out += " Your %s Mid-Year checkpoint is %s; the Year-End result is still to come." % (
            ck["label"], PM_LABEL_NAMES.get(r["final_pm"], r["final_pm"]))
    return out.strip() or None


def _record_trend(db, u, rows, generate=False):
    """(text, source) of the history card's one-line trend, or (None, None)."""
    src = _record_trend_case(db, u, rows)
    if not src:
        return None, None

    def _make(ai_ok):
        if ai_ok:
            try:
                raw = ai_draft.summarise_record((_row_get(u, "full_name") or "").split(" ")[0], src, kind="trend")
                obj = json.loads(re.sub(r"^```(?:json)?|```$", "", (raw or "").strip()).strip(), strict=False)
                txt = _insight_polish(obj.get("trend") or "")
                err = _record_snapshot_error(src, txt) or (len(txt.split()) > 50 and "too long")
                if not err:
                    return txt, "ai"
                app.logger.info("record trend refused for %s: %s", u["id"], err)
            except Exception as e:
                app.logger.info("record trend fell back for %s: %s", u["id"], e)
        return _record_trend_plain(db, u, rows), "plain"
    return _record_cache(db, u["id"], 0, src, "trend", _make if generate else None)


