# WHAT YOU LED: the panel (Chris, 2026-10-12; canvas boards W2-W5). The people a leader is over, tab by seat, each
# with their talent status and final bands once HR releases them to the leader (the BG CEO, who decides them, at once);
# before that the bands up to the leader's own step, the rest "in calibration". Opening one shows how both bands moved,
# step by step, with each tier's reason. Read from the stored rating record (built on the fly, within a budget, for
# anyone not recorded yet), through band_chain -- so it can't show a leader more than release 1 allows.
_BAND_RANK = {"pm": {b: i for i, b in enumerate(("UA", "BE", "ME", "AE", "OU"))},
              "pot": {"Low": 0, "Mid": 1, "High": 2}}
_LED_BUILD_BUDGET = 2.0   # seconds spent building records nobody has stored yet, per request


def _led_cycles(db, tabs):
    """The cycles where any of the leader's people has a rating record -- or a talent status released to their leaders,
    which is all an imported past Year-End holds (2026-10-14) -- newest first, plus the active one."""
    pq, pa = _led_people_sql(tabs)
    rows = [dict(r) for r in db.execute(
        "SELECT id, name, is_active FROM cycles WHERE id IN (SELECT DISTINCT cycle_id FROM rating_records WHERE "
        "subject_id IN (%s)) OR id IN (SELECT DISTINCT cycle_id FROM leader_releases WHERE kind='talent' AND "
        "subject_id IN (%s)) ORDER BY year DESC, half DESC, id DESC" % (pq, pq), list(pa) + list(pa))]
    act = active_cycle(db)
    if act and act["id"] not in {r["id"] for r in rows}:
        rows.insert(0, {"id": act["id"], "name": act["name"], "is_active": 1})
    return rows


def _led_record(db, cid, subject, recs, t0):
    rec = recs.get(subject["id"])
    if rec is None and time.time() - t0 < _LED_BUILD_BUDGET:
        try:
            rec = _rating_record_row(db, cid, subject)
        except Exception as e:   # one person's record never takes the list down
            app.logger.info("led: record build failed for %s: %s", subject["id"], e)
            rec = None
    return rec


def _led_summary(rec, role, lead, sid, mid_year=False):
    """One row of the list: what this leader may read of the person's results now. At Mid-Year the chain ends at the
    HOD, whose bands place the talent status (2026-10-12)."""
    if mid_year:
        rec = _rr_mid_year(rec)
    # an axis with no result (no band from the line manager or a calibrator: e.g. KPIs not approved yet) has nothing
    # to calibrate or release -- it shows "—" and never holds the row back (found testing on staging, 2026-10-12)
    have = [k for k in ("pm", "pot") if rec and rec.get("%s_final_band" % k)]
    out = {"talent": None, "pm": None, "pot": None, "full": False, "moves": 0, "you": [],
           "none": not have}   # nothing recorded, or no result on either axis yet
    if out["none"]:
        return out
    full_all = True
    for k in have:
        ch = band_chain(rec, k, role, sid in lead[k], mid_year)
        if not ch:
            full_all = False
            continue
        vis = [x for x in ch["steps"] if x["state"] != "hidden"]
        if ch["full"]:
            out[k] = ch["final"]
        else:
            full_all = False
            out[k] = next((x["band"] for x in reversed(vis) if x["band"]), None)
        out["moves"] += sum(1 for x in vis if x["state"] == "moved")
        if any(x["step"] == role and x["state"] == "moved" for x in vis):
            out["you"].append("performance" if k == "pm" else "potential")
    out["full"] = full_all
    if role in _LEADER_SEES_AT_ONCE or sid in lead["talent"] or full_all:
        cat = talent_category(rec.get("pm_final_band"), rec.get("pot_final_band"))
        if cat:
            out["talent"] = {"name": cat, "slug": TALENT_CATEGORY_SLUG.get(cat, "")}
    return out


@app.route("/me/led")
@login_required
def my_led():
    """The leader's people for the What you led panel (JSON): ?cycle=&tab=. Only the people they lead; the result each
    row shows is what release 1 lets them read (band_chain). 404 for anyone who leads nobody, and for an admin."""
    u = current_user()
    if is_admin(u):
        abort(404)
    db = get_db()
    tabs = _led_tabs(db, u)
    if not tabs:
        abort(404)
    cycles = _led_cycles(db, tabs)
    try:
        cid = int(request.args.get("cycle") or 0) or None
    except ValueError:
        cid = None
    if cid not in {c["id"] for c in cycles}:
        cid = cycles[0]["id"] if cycles else None
    if not cid:
        abort(404)
    tab = next((t for t in tabs if t["key"] == request.args.get("tab")), tabs[-1])
    subs = db.execute("SELECT * FROM users WHERE %s ORDER BY full_name" % tab["where"], tab["args"]).fetchall()
    ids = [x["id"] for x in subs]
    recs = {}
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        recs.update({r["subject_id"]: dict(r) for r in db.execute(
            "SELECT * FROM rating_records WHERE cycle_id=? AND subject_id IN (%s)" % ",".join("?" * len(chunk)),
            [cid] + chunk)})
    lead = {k: leader_released_ids(db, k, cid) for k in LEADER_RELEASE_KINDS}
    lead_at = {r[0]: r[1] for r in db.execute(
        "SELECT subject_id, MIN(released_at) FROM leader_releases WHERE cycle_id=? GROUP BY subject_id", (cid,))}
    emp_at = {r[0]: r[1] for r in db.execute(
        "SELECT subject_id, MIN(at) FROM (SELECT subject_id, released_at at FROM result_releases WHERE cycle_id=? "
        "UNION ALL SELECT subject_id, released_at FROM talent_releases WHERE cycle_id=?) GROUP BY subject_id",
        (cid, cid))}
    t0 = time.time()
    people, n_full, at_once = [], 0, False
    mid_year = cycle_is_mid_year(db, cid)
    # an imported past Year-End (2026-10-14): its talent status, once released to the leader; nothing else to build
    hist = {} if mid_year else _imported_talent_map(db, cid, ids)
    if hist and not recs:
        t0 = 0   # no record to build for a year from before OneHR

    # a Group Chief's people filter by their batch -- the names their Talent Box uses (2026-10-14)
    batch = _gc_batches(db, [g_["id"] for g_ in _gc_groups(db, u)]) if tab["key"] == "group" else {}
    for x in subs:
        role = leader_role_of(db, u, x)
        if not role:
            continue
        once = sees_at_once(db, role, cid)
        at_once = at_once or once
        sm = _led_summary(_led_record(db, cid, x, recs, t0), role, lead, x["id"], mid_year)
        if sm["none"] and x["id"] in hist and (once or x["id"] in lead["talent"]):
            h_ = hist[x["id"]]
            sm = dict(sm, none=False, full=True, imported=True, pm=h_["perf"], pot=h_["pot"],
                      talent={"name": h_["name"], "slug": TALENT_CATEGORY_SLUG.get(h_["name"], "")})
        n_full += 1 if sm["full"] else 0
        if sm.get("imported"):
            rel, tone = (("From Group People's records before OneHR" if sm.get("pm") else
                          "Talent status only · from Group People's records before OneHR"), "none")
        elif x["id"] in emp_at:
            rel, tone = "Released to them %s" % (_myt_date_str(emp_at[x["id"]]) or ""), "ok"
        elif once:   # they decided it: say where the two releases are instead
            rel, tone = (("With their leaders since %s" % (_myt_date_str(lead_at[x["id"]]) or ""), "you")
                         if x["id"] in lead_at else ("Not released yet", "none"))
        elif sm["full"] and x["id"] in lead_at:
            rel, tone = "With you since %s" % (_myt_date_str(lead_at[x["id"]]) or ""), "you"
        elif sm["full"]:
            rel, tone = "Not released to them yet", "you"
        elif sm["none"]:
            rel, tone = "No result yet this cycle", "none"
        else:
            rel, tone = ("With the HOD" if mid_year else "In calibration"), "none"
        people.append(dict(sm, id=x["id"], name=x["full_name"], company=x["company"] or "",
                           company_label=display_company(x["business_group"], x["company"]) if x["company"] else "",
                           department=(x["department"] or "").strip(),
                           meta=" · ".join(v for v in ((x["department"] or "").strip(),
                                                       ("Grade %s" % x["job_grade"]) if x["job_grade"] else "") if v),
                           batch=batch.get(x["id"], ""), rel=rel, rel_tone=tone))
    n_res = sum(1 for p_ in people if not p_["none"])   # someone with no result has nothing to release
    state = "after" if n_res and n_full == n_res else ("before" if not n_full else "mixed")
    rows_key = {"bg": ("company", "Business unit"), "bu": ("department", "Department"),
                "group": ("batch", "Batch")}.get(tab["key"])
    filt = None
    if rows_key:
        cnt = {}
        for p_ in people:
            v = p_[rows_key[0]]
            if v:
                cnt[v] = cnt.get(v, 0) + 1
        filt = {"key": rows_key[0], "label": rows_key[1],
                "items": [{"v": v, "label": next((p_["company_label"] for p_ in people if p_["company"] == v), v)
                           if rows_key[0] == "company" else v, "n": n} for v, n in sorted(cnt.items())]}
    cyc = next(c for c in cycles if c["id"] == cid)
    return jsonify(
        cycles=[{"id": c["id"], "name": _cycle_label(c["name"]), "active": bool(c["is_active"])} for c in cycles],
        cycle=cid, name=_cycle_label(cyc["name"]),
        tabs=[{"key": t["key"], "label": t["label"], "n": t["n"]} for t in tabs], tab=tab["key"],
        state=state, at_once=at_once, n_full=n_full, n_res=n_res, filter=filt, people=people,
        bands={"pm": ["UA", "BE", "ME", "AE", "OU"], "pot": ["Low", "Mid", "High"]},
        mid_year=mid_year,   # Self, LM and HOD only (2026-10-12)
        talent_order=list(reversed(TALENT_CATEGORY_ORDER)))


@app.route("/me/led/<int:sid>")
@login_required
def my_led_person(sid):
    """One person's band movement on both axes for the What you led panel (JSON) -- step by step with each tier's
    reason, cut at the leader's own step until release 1. 404 unless the viewer leads them."""
    u = current_user()
    if is_admin(u):
        abort(404)
    db = get_db()
    x = db.execute("SELECT * FROM users WHERE id=?", (sid,)).fetchone()
    role = leader_role_of(db, u, x) if x else None
    if not role:
        abort(404)
    try:
        cid = int(request.args.get("cycle") or 0) or active_cycle_id(db)
    except ValueError:
        abort(400)
    rec = db.execute("SELECT * FROM rating_records WHERE cycle_id=? AND subject_id=?", (cid, sid)).fetchone()
    imp = _imported_talent(db, x, cid)
    if not rec and imp:   # a year from before OneHR: its talent status, no band movement (2026-10-14)
        shown = sees_at_once(db, role, cid) or leader_released(db, "talent", sid, cid)
        return jsonify(id=sid, name=x["full_name"], axes=[], you=role, imported=imp["name"] if shown else None,
                       imported_perf=imp["perf"] if shown else None, imported_pot=imp["pot"] if shown else None)
    rec = dict(rec) if rec else _led_record(db, cid, x, {}, time.time())
    if not rec:
        return jsonify(id=sid, name=x["full_name"], axes=[], you=role)
    mid_year = cycle_is_mid_year(db, cid)
    if mid_year:   # Self, LM and HOD only (2026-10-12)
        rec = _rr_mid_year(rec)
    axes = []
    for k, label in (("pm", "Performance"), ("pot", "Potential")):
        # no result on this axis: nothing is being calibrated, so show the steps as they stand, never "in calibration"
        has = bool(rec.get("%s_final_band" % k))
        ch = band_chain(rec, k, role, leader_released(db, k, sid, cid) if has else True, mid_year)
        if not ch:
            continue
        if not has:
            ch = dict(ch, final=None)
        before, steps = None, []
        for st in ch["steps"]:
            d = ""
            if st["state"] == "moved" and before and st["band"]:
                d = "up" if _BAND_RANK[k].get(st["band"], 0) > _BAND_RANK[k].get(before, 0) else "down"
            steps.append(dict(st, dir=d, you=(st["step"] == role)))
            before = st["band"] or before
        axes.append({"kind": k, "label": label, "steps": steps, "final": ch["final"], "full": ch["full"]})
    return jsonify(id=sid, name=x["full_name"], axes=axes, you=role, mid_year=mid_year)


