# ---------------------------------------------------------------------------
# The dashboard's tools open in the record's right-hand panel (Chris, 2026-10-09: "rebuild the view into the right slide
# page by clicking each, like clicking the career plan, it will open the right pop out window with the person's career
# plan with the year selection to select which year to view, for 360, similarly it will show the person's 360 report in
# the same view with the year selection"; designed on the canvas "OneHR Tools Slide-out Panels", "default to 2026").
# SELF-SCOPED and read-only, like the record panel: a person's own plans (a draft is theirs to read) and their own 360,
# only once its report is released, in words -- never a percentage, a count or who said what.
# ---------------------------------------------------------------------------
_PLAN_STATUS_WORD = {"draft": "draft", "shared": "shared", "closed": "approved", None: "not started"}


def _plan_status_word(status, shared):
    """A plan's status in a word: a closed plan that was shared is approved (Approve plan closes it); one closed without
    ever being shared stays 'closed'."""
    return "closed" if status == "closed" and not shared else _PLAN_STATUS_WORD.get(status, status or "")


def _cycle_label(name):
    """A cycle's name as people read it ('2026 Year-End', never the '(staging)' suffix)."""
    return re.sub(r"\s*\(staging\)\s*$", "", name or "").strip()


def _plan_years(db, u):
    """This person's plan years, newest first: [{year, status}]. At Year-End the year being written now is listed too,
    'not started' until they begin it in the AI check-in."""
    years = [{"year": r["plan_year"], "status": r["status"], "shared": bool(r["shared_at"])} for r in db.execute(
        "SELECT plan_year, status, shared_at FROM pm_idp WHERE subject_id=? AND plan_year IS NOT NULL "
        "ORDER BY plan_year DESC", (u["id"],)).fetchall()]
    period = active_pm_period(db)
    writing = pm_idp_plan_year(period) if (period and _is_year_end(period)) else None
    if writing and writing not in {y["year"] for y in years}:
        years = sorted(years + [{"year": writing, "status": None}], key=lambda y: -y["year"])
    now = _today_myt().year
    for y in years:
        rel = "this year" if y["year"] == now else ("next" if y["year"] > now else "")
        word = _plan_status_word(y["status"], y.get("shared"))
        y["tag"] = ("%s · %s" % (rel, word)) if rel else word
        y["writing"] = y["year"] == writing
    return years


def _plan_profile(db, u):
    """Where they want to go, as their career profile reads TODAY (it isn't kept per year)."""
    prof = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?", (u["id"],)).fetchone()
    if not prof:
        return {"next": None, "longer": None, "target": None, "mobility": None}
    target = None
    if prof["target_profile_id"]:
        t = db.execute("SELECT job_title, active FROM tc_job_profiles WHERE id=?", (prof["target_profile_id"],)).fetchone()
        target = _tc_retired_title(t["job_title"], t["active"]) if t else None
    mob = {m["key"]: m["label"] for m in PM_CAREER_MOBILITY}
    return {"next": (prof["aspiration_mid"] or "").strip() or None, "longer": (prof["aspiration_long"] or "").strip() or None,
            "target": target, "mobility": mob.get(prof["mobility"]) if prof["mobility"] else None}


def plan_goal_levels(db, u, year=None):
    """The dashboard's Career Plan card (2026-10-20, the dashboards plan): the plan year the Career Plan panel opens on,
    each goal with where it stands -- its status, and its level now and the level it aims for where it names a
    competency (have_level / required_level) -- the role they aim for, the last check-in, and the manager's remark,
    which shows under _record_plan_year's own rule. None with no plan."""
    years = [y for y in _plan_years(db, u) if y["status"]]
    if not years:
        return None
    ys = [y["year"] for y in years]
    now = _today_myt().year
    sel = year if year in ys else (now if now in ys else ys[0])
    plan = _record_plan_year(db, u, sel)
    if not plan:
        return None
    idp = pm_idp_for(db, sel, u["id"])
    lv = {g["id"]: (g.get("have_level"), g.get("required_level")) for g in (idp or {}).get("goals", [])}
    prog = {p_["key"]: p_["label"] for p_ in PM_IDP_PROGRESS}
    goals = [{"id": g["id"], "area": g["area"], "status": g["status"], "status_label": prog.get(g["status"], "Not started"),
              "have": lv.get(g["id"], (None, None))[0], "need": lv.get(g["id"], (None, None))[1]} for g in plan["goals"]]
    return {"year": sel, "status": plan["status"], "target": _plan_profile(db, u)["target"], "goals": goals,
            "last_checkin": plan["last_checkin"], "lm_remark": plan["lm_remark"], "can_checkin": plan["can_checkin"]}


def _plan_panel(db, u, year=None):
    """The Career Plan panel: the plan years to pick from and one year's plan in full -- this calendar year's by
    default (Chris: "default to 2026"), else the newest. Where they want to go is their profile as it reads today, so
    it shows for this year's and next year's plan only. The year being written now links to the AI check-in."""
    years = _plan_years(db, u)
    out = {"mode": "plan", "years": years, "year": None, "plan": None, "profile": None, "edit_url": None,
           "edit_label": None, "progress": [{"key": p_["key"], "label": p_["label"]} for p_ in PM_IDP_PROGRESS]}
    if not years:
        out["profile"] = _plan_profile(db, u)
        return out
    ys = [y["year"] for y in years]
    now = _today_myt().year
    sel = year if year in ys else (now if now in ys else ys[0])
    info = next(y for y in years if y["year"] == sel)
    out["year"] = sel
    out["plan"] = _record_plan_year(db, u, sel) if info["status"] else None
    out["profile"] = _plan_profile(db, u) if sel >= now else None
    if info["writing"] and info["status"] in (None, "draft"):
        out["edit_url"] = url_for("review_journey", stage="career_plan")
        out["edit_label"] = "Continue in your AI check-in" if info["status"] else "Start it in your AI check-in"
    # AI+ Learning (S10, board 1D): each goal's learning and what's gained beyond the plan, where Learning is on
    if lms_on() and urole_allows(u, "lms", db):
        out["learning_on"] = True
        out["find_url"] = url_for("learning_home", tab="find")
        if out["plan"]:
            lines = lms_goal_learning(db, u["id"], [g["id"] for g in out["plan"]["goals"]])
            for g in out["plan"]["goals"]:
                g["learning"] = lines.get(g["id"], [])
        out["gained"] = [dict(g, roles=[r["title"] for r in lms_explore_roles(db, u, g["key"], limit=2)])
                         for g in lms_gained(db, u) if not g["in_plan"]]
        out["gained_add"] = bool(out["edit_url"])
        out["gained_url"] = url_for("learning_gained")
    return out


def _report_cycles(db, u):
    """The cycles with a 360 about this person, newest first: released ones, and any they were rated in (so this
    cycle shows as not released yet). None when their user role doesn't rate them in the 360 (Roles & access)."""
    if not urole_allows(u, "tm_rated", db):
        return []
    rel = {r["cycle_id"]: r["released_at"] for r in db.execute(
        "SELECT cycle_id, released_at FROM report_releases WHERE subject_id=?", (u["id"],)).fetchall()}
    ids = set(rel) | {r["cycle_id"] for r in db.execute(
        "SELECT DISTINCT cycle_id FROM assignments WHERE subject_id=? AND archived=0", (u["id"],)).fetchall()}
    if not ids:
        return []
    rows = db.execute("SELECT id, name, is_active, year FROM cycles WHERE id IN (%s) "
                      "ORDER BY year DESC, half DESC, id DESC" % ",".join("?" * len(ids)), list(ids)).fetchall()
    return [{"id": c["id"], "name": _cycle_label(c["name"]), "released": c["id"] in rel,
             # the dropdown groups cycles by year (Chris, 2026-10-10: "a cycle year dropdown list instead of showing all")
             "year": c["year"], "half": re.sub(r"^\d{4}\s+", "", _cycle_label(c["name"])) or _cycle_label(c["name"]),
             "released_on": _myt_date_str(rel[c["id"]]) if rel.get(c["id"]) else None,
             "current": bool(c["is_active"]),
             "tag": "released" if c["id"] in rel else "not released"} for c in rows]


def _agree_level(pct):
    """A principle's agreement as 1-4 steps, the same cut-offs as its words (_RECORD_AGREE)."""
    p = pct or 0
    return 4 if p >= 90 else 3 if p >= 75 else 2 if p >= 40 else 1


def _report_panel(db, u, cid=None):
    """The 360 report panel: the cycles to pick from and one cycle's report -- the newest released by default. A
    released report shows the final potential band (only once Potential is released), where they're strongest and
    where to grow, each principle and its behaviours in words, and what colleagues wrote, anonymous. Nothing of a
    report that isn't released."""
    cycles = _report_cycles(db, u)
    out = {"mode": "report", "cycles": cycles, "cycle": None, "name": None, "released": False}
    if not cycles:
        return out
    sel = (next((c for c in cycles if c["id"] == cid), None)
           or next((c for c in cycles if c["released"]), None) or cycles[0])
    out.update(cycle=sel["id"], name=sel["name"], released=sel["released"], released_on=sel["released_on"])
    if not sel["released"]:
        return out
    s = db.execute("SELECT * FROM users WHERE id=?", (u["id"],)).fetchone()
    ctx = subject_report_context(db, s, sel["id"])   # assessor identity already stripped
    principles = []
    for crit in ctx["agreement"]:
        yes = sum(st["yes"] for st in crit["statements"])
        total = sum(st["total"] for st in crit["statements"])
        if not total:
            continue
        pct = round(100 * yes / total)
        principles.append({
            "name": crit.get("description") or crit["name"], "short": crit["name"], "pct": pct,
            "words": _record_agree_words(pct), "level": _agree_level(pct),
            "behaviours": [{"text": st["text"], "next": bool(st["is_future"]),
                            "words": _record_agree_words(round(100 * st["yes"] / st["total"]))}
                           for st in crit["statements"] if st["total"]],
            "comments": [c["comment"] for c in crit["comments"] if (c.get("comment") or "").strip()],
        })
    ps = sorted(principles, key=lambda p: -p["pct"])
    top = ps[0]["pct"] if ps else 0
    strong = [p for p in ps if p["pct"] == top][:2]
    grow = [p for p in reversed(ps) if p["pct"] < top][:2]
    for p in principles:
        p.pop("pct")
    out.update(band=released_final_band(db, s, sel["id"], "pot"), principles=principles,
               strong=[{"name": p["name"], "short": p["short"], "words": p["words"]} for p in strong],
               grow=[{"name": p["name"], "short": p["short"], "words": p["words"]} for p in grow],
               even=bool(ps) and not grow)
    return out


def dash_tool_cards(db, u, as_of=None):
    """The dashboard's two tools, each a card that opens its panel: the Career Plan (this year's plan, and the one
    being written) and the 360 report (the latest released, and this cycle's while it isn't). Each gated on its
    module. as_of (the demo's cycle switch): as they stood after that cycle -- no plan being written, no later report."""
    out = []
    if cycle_module_on("idp", db):
        years = _plan_years(db, u)
        now = _today_myt().year
        cur = next((y for y in years if y["year"] == now), None) or (years[0] if years else None)
        if cur and cur["status"]:
            pl = _record_plan_year(db, u, cur["year"])
            n = len((pl or {}).get("goals") or [])
            line1 = "%d plan · %s · %d goal%s" % (cur["year"], _plan_status_word(cur["status"], cur.get("shared")), n,
                                                  "" if n == 1 else "s")
            if (pl or {}).get("last_checkin"):
                line1 += " · checked in " + re.sub(r"\s\d{4}$", "", pl["last_checkin"])
        elif cur:
            line1 = "%d plan · not started" % cur["year"]
        else:
            line1 = "No plan yet"
        w = None if as_of else next((y for y in years if y["writing"] and y is not cur), None)
        line2 = (("%d plan: %s in your AI check-in" % (w["year"], "draft" if w["status"] else "not started")) if w
                 else ("%d plans on record" % len(years)) if len(years) > 1
                 else "You write it at Year-End, in your AI check-in" if not years else "")
        out.append({"key": "plan", "name": "Career Plan", "line1": line1, "line2": line2})
    if cycle_module_on("tm", db):
        cyc = [c for c in _report_cycles(db, u) if not as_of or c["id"] in as_of["upto"]]
        latest = next((c for c in cyc if c["released"]), None)
        waiting = next((c for c in cyc if c["current"] and not c["released"]), None)
        n_rel = sum(1 for c in cyc if c["released"])
        out.append({"key": "report", "name": "My 360 report",
                    "line1": ("Latest: %s · released" % latest["name"]) if latest else "Nothing released yet",
                    "line2": (("%s not released yet" % waiting["name"]) if waiting
                              else ("%d reports on record" % n_rel) if n_rel > 1 else "")})
    if lms_on() and not as_of:   # AI+ Learning (2026-10-20), all year; dark unless ONEHR_LMS=1
        if urole_allows(u, "lms", db):   # their user role opens AI+ Learning (Roles & access, 2026-10-20)
            out.append(lms_tool_card(db, u))
    return out


