@app.before_request
def _super_band_remark_gate():
    """The super admin's remark on a band action (SUPER_BAND_ENDPOINTS): checked before the route runs, so nothing
    changes without one; kept on g for the audit rows and band rows the action writes."""
    if request.method != "POST" or not session.get("user_id") or not _super_band_action(request.endpoint, request.form):
        return None
    if any(request.path == x or request.path.startswith(x + "/") for x in GRADEH_PATHS) and not gradeh_on():
        return None   # Grade H dark (2026-10-31): _gradeh_gate answers 404 whatever the form holds, never a remark prompt first
    me = current_user()
    if not me or not is_super(me):
        return None
    raw = request.form.get("remark") or request.form.get("override_reason")
    if raw is None and request.is_json:
        raw = (request.get_json(silent=True) or {}).get("remark")
    if not (raw or "").strip() and request.endpoint in TB_ROUND_REMARK_ENDPOINTS:
        # Talent Box Round 2 (2026-11-15): the one remark given when the round was opened rides on every move and on the lock,
        # when the form names the round
        raw = _tb_round_remark_of(get_db(), request.form.get("round_id"))
    remark, err = _super_band_remark(raw)
    if err:
        if request.headers.get("X-Requested-With") in ("XMLHttpRequest", "fetch") or request.is_json:
            return jsonify({"ok": False, "error": err}), 400
        flash(err, "error")
        return redirect(_referer_path(url_for("admin_overview")))
    g.super_band_remark = remark
    return None


PAT_CURVE_SHORT = {"negative": "Negatively skewed", "normal": "Normal", "positive": "Positively skewed"}


def _pat_figure(raw):
    """One posted PAT figure: (None, None) blank (clear it), (pct, None) a figure, (None, why) refused."""
    raw = (raw or "").strip()
    if raw == "":
        return None, None
    try:
        pct = float(raw.replace(",", ""))
    except ValueError:
        return None, "must be a number, e.g. 84 or 132.5"
    if not math.isfinite(pct) or pct < 0:
        return None, "must be a positive number"
    return pct, None


def _pat_save(db, me, period, bg, rows, _round_ok=False):
    """The ONE write of unit PAT achievement figures (PAT Ref, Chris, 2026-10-27: one Save for the whole table). `rows`
    is [(unit, raw figure)]. Every row is checked first -- a real unit of `bg` the admin may reach, a figure that is a
    number or blank (clear it), no unit twice, and a unit its BU CEO has locked changes only for the super admin -- and
    if any is refused NOTHING is written. Only the rows whose figure differs from what is stored are written and audited
    (pm_pbt_set, one row a unit), in one transaction with the locked units' flags (_pat_flag_changes). There is no
    business group figure any more: a blank unit is refused. A unit the BG CEO has locked on the Talent Box (or that has a
    Round 2) is read only here (2026-11-15): its figure changes only as the ACTUAL PAT on the Talent Box's Round 2 view
    (_tb_round_actual_save, the one caller passing `_round_ok`), so the forecast the BG CEO calibrated on is never changed out of
    sight. Returns (saved: [(unit, old, new)], error or None)."""
    org = org_map(db)
    seen, parsed = set(), []
    for company, raw in rows:
        company = (company or "").strip()
        if not company:
            return [], "A figure belongs to a business unit: the business group has none of its own."
        if company not in org.get(bg, []) or not can_access(me, bg, company):
            abort(403)
        if company in seen:
            return [], "%s is in the list twice." % (display_company(bg, company) or company)
        seen.add(company)
        pct, why = _pat_figure(raw)
        if why:
            return [], "PAT achievement for %s %s." % (display_company(bg, company) or company, why)
        parsed.append((company, pct))
    stored = {r["company"]: r["achievement_pct"] for r in db.execute(
        "SELECT company, achievement_pct FROM pm_pbt_achievement WHERE cycle_id=? AND business_group=?",
        (period["id"], bg))}
    changes = [(c_, stored.get(c_), pct) for c_, pct in parsed
               if (stored.get(c_) is None) != (pct is None) or (pct is not None and abs(stored[c_] - pct) > 1e-9)]
    if not _round_ok:   # the BG CEO's lock makes the forecast theirs: read only here, changed on Round 2 · Actual
        held = [c_ for c_, _o, _n in changes if _pat_bg_locked(db, period["id"], bg, c_) or _tb_round_row(db, period["id"], bg, c_)]
        if held:
            return [], ("Nothing was saved: the BG CEO has locked %s on the Talent Box, so its PAT is read only here. Change it on "
                        "Talent Box › Round 2 · Actual." % ", ".join(display_company(bg, c_) or c_ for c_ in held))
    # once a unit's BU CEO has locked calibration, only the super admin changes the PAT its curve reads (Chris,
    # 2026-10-17)
    locked = [(c_, _pat_unit_lock(db, period["id"], c_)) for c_, _o, _n in changes]
    locked = [(c_, lk) for c_, lk in locked if lk]
    if locked and not is_super(me):
        return [], ("Nothing was saved: the BU CEO locked calibration for %s, so only the super admin can change "
                    "this PAT now." % ", ".join(display_company(bg, c_) or c_ for c_, _l in locked))
    before = {c_: pm_curve_for(db, period["id"], bg, c_) for c_, _l in locked}
    try:
        for c_, _old, pct in changes:
            if pct is None:
                db.execute("DELETE FROM pm_pbt_achievement WHERE cycle_id=? AND business_group=? AND company=?",
                           (period["id"], bg, c_))
                log_activity(db, me["id"], "pm_pbt_set", f"{bg} / {c_}: cleared", commit=False)
            else:
                if c_ in stored:
                    db.execute("UPDATE pm_pbt_achievement SET achievement_pct=?, updated_at=datetime('now'), "
                               "updated_by=? WHERE cycle_id=? AND business_group=? AND company=?",
                               (pct, me["id"], period["id"], bg, c_))
                else:
                    db.execute("INSERT INTO pm_pbt_achievement(cycle_id, business_group, company, achievement_pct, "
                               "updated_by) VALUES (?,?,?,?,?)", (period["id"], bg, c_, pct, me["id"]))
                log_activity(db, me["id"], "pm_pbt_set",
                             f"{bg} / {c_}: {pct:g}% ({pm_curve_key_for_pct(pct)} curve)", commit=False)
        _pat_flag_changes(db, period["id"], bg, locked, before, me["id"], commit=False)
        if not _round_ok:   # the Round 2 writer commits the figure with its own rows, in one transaction
            db.commit()
    except Exception:
        db.rollback()
        raise
    return changes, None


@app.route("/admin/performance/pbt", methods=["GET", "POST"])
@admin_required
def admin_performance_pbt():
    """Calibration & Talent > Run > PAT Ref (2026-10-27; it was Settings > PAT achievement): record each business
    unit's PAT achievement % for the active period, for ONE business group at a time. That figure is what selects
    the reference distribution curve the PM Calibration pages show (<70 negatively skewed / 70-130 normal / >130
    positively skewed) -- stored as the percentage, not the curve name, so the reason a curve applied stays auditable
    afterwards. The whole table saves at once (_pat_save).

    Scoped by admin_bg_of() exactly like admin_performance_config(): a BGHR admin only sees their own BG's units,
    super admin picks a group. Entering a figure is optional -- a unit with none simply calibrates against the normal
    curve, flagged as not-yet-entered rather than silently implying a real number. A business group has no figure of
    its own any more: calibration goes unit by unit, and an old group row is never read."""
    db = get_db()
    me = current_user()
    period = active_pm_period(db)
    org = org_map(db)

    if request.method == "POST":
        bg = (request.form.get("business_group", "") or "").strip()
        back = lambda: redirect(url_for("admin_performance_pbt", fbg=bg or None))   # noqa: E731
        if not period:
            flash("No active performance period.", "error")
            return back()
        # Defence in depth: bg_scope() isn't in play here (a direct per-unit write), so re-check the caller can
        # actually reach this BG rather than trusting the posted value.
        if bg not in org or not can_access_bg(me, bg):
            abort(403)
        units, figs = request.form.getlist("company"), request.form.getlist("achievement_pct")
        if not units or len(units) != len(figs):
            flash("Nothing was saved: the figures and the units did not match. Reload the page and try again.", "error")
            return back()
        saved, err = _pat_save(db, me, period, bg, list(zip(units, figs)))
        if err:
            flash(err, "error")
        elif not saved:
            flash("Nothing changed, so nothing was saved.", "ok")
        else:
            flash("Saved %d unit%s." % (len(saved), "" if len(saved) == 1 else "s"), "ok")
        return back()

    frows, fsel = admin_filter_rows(db, me, "admin_performance_pbt", params=("fbg", "fbu", "fdept"), levels=1,
                                    bg_all=False)
    bg = fsel.get("bg") or ""
    if not bg and frows and frows[0]["opts"]:   # one group at a time: the first in scope until one is picked
        bg = frows[0]["opts"][0]["key"]
        frows[0]["opts"][0]["on"] = True
    units, counts, n_in = [], {"negative": 0, "normal": 0, "positive": 0}, 0
    if period and bg:
        for company in org.get(bg, []):
            if not can_access(me, bg, company):
                continue
            curve = pm_curve_for(db, period["id"], bg, company)
            lk = _pat_unit_lock(db, period["id"], company)
            n_in += 1
            if curve["entered"]:
                counts[curve["key"]] += 1
            lock_full = _myt_date_str(lk["at"]) if lk else None
            _rr = _tb_round_row(db, period["id"], bg, company)
            units.append({"name": company, "curve": curve, "lock": lk, "lock_full": lock_full,
                          "lock_short": lock_full.rsplit(" ", 1)[0] if lock_full else None,
                          # the BG CEO's lock makes the figure read only here (2026-11-15): "Change it on Talent Box › Round 2 · Actual"
                          "tb_locked": bool(_pat_bg_locked(db, period["id"], bg, company) or _rr),
                          "tb_round": ({"state": _tb_round_state(_rr), "mode": _rr["mode"]} if _rr else None),
                          "flag": _pat_lock_view(db, me, period["id"], bg, company, curve)})
    return render_template("admin_pat_ref.html", period=period, frows=frows, bg=bg, units=units, counts=counts,
                           n_in=n_in, n_entered=sum(counts.values()), curves=PM_DIST_CURVES,
                           curve_labels=PM_CURVE_LABELS, curve_short=PAT_CURVE_SHORT, band_order=PM_BAND_ORDER,
                           label_names=PM_LABEL_NAMES, is_sup=is_super(me), remark_max=SUPER_BAND_REMARK_MAX)


# ---- PAT AFTER A LOCK (Chris, 2026-10-17: "add the warning and flag to the admin, and set control level, for BG and BU
# admin, they can't change the PAT score after BUCEO locked, only super admin can do so, and there should be an added
# function for super admin to run AI fit to the new curve ... as an option for super admin to have one click to complete
# it"; and "for any action that will impact or change the final band of an employee by super admin, there must be a
# mandatory remark logged by super admin ... saved in the audit trail"). A changed PAT moves the curve a locked result
# is read against; the lock itself never moves. The page says so before the change, flags the unit after it, and the
# super admin can fit the locked bands to the new curve: the BU CEO tier's own AI fit (_pm_calib_fit_moves: the fewest
# adjacent-band moves, nearest score and strongest case first), written into the BU CEO's session, which stays locked.
SUPER_BAND_REMARK_MAX = 1000


def _super_band_remark(raw):
    """(remark, error): THE check on a super admin's remark for an action that changes a final band (Chris,
    2026-10-17). Required, at most SUPER_BAND_REMARK_MAX characters, screened like every stored remark."""
    remark = " ".join((raw or "").split())
    if not remark:
        return None, "Write your remark first: a change to someone's final band needs one, and it goes in the audit trail."
    if len(remark) > SUPER_BAND_REMARK_MAX:
        return None, "Keep the remark under %d characters." % SUPER_BAND_REMARK_MAX
    if ai_draft.stored_text_refusal(remark, "manager"):
        return None, "Reword the remark: it reads like an instruction rather than a reason."
    return remark, None


ADMIN_RESULT_REASON_MAX = 500


def _admin_result_reason(raw):
    """(reason, error): THE check on an admin's reason for a result-level edit (Chris, 2026-10-18: "for setting up the
    user profile, assigning kpi and competency, no reason is needed ... only result level edit requires reason inputed
    by admin"). Required, at most ADMIN_RESULT_REASON_MAX characters, screened like every stored remark; the caller
    writes it into the audit trail."""
    reason = " ".join((raw or "").split())
    if not reason:
        return None, "Give a reason first: a change to someone's result needs one, and it goes in the audit trail."
    if len(reason) > ADMIN_RESULT_REASON_MAX:
        return None, "Keep the reason under %d characters." % ADMIN_RESULT_REASON_MAX
    if ai_draft.stored_text_refusal(reason, "manager"):
        return None, "Reword the reason: it reads like an instruction rather than a reason."
    return reason, None


# THE SUPER ADMIN'S REMARK ON EVERY BAND ACTION (Chris, 2026-10-17: "for any action that will impact or change the final
# band of an employee by super admin, there must be a mandatory remark logged by super admin ... saved in the audit
# trail"; the sweep, 2026-10-18: "yes, extend the band remark for super admin"). Each POST below made by the super admin
# carries a `remark` (or, on a lock with override, its `override_reason`), checked by _super_band_remark before the route
# runs: without it nothing changes (a flash and back, or JSON 400 for the pages that autosave). The remark then rides on
# every audit row the action writes (log_activity / _leader_log) and on the band row it writes, where no note was given.
# A seat holder at their own tier is never asked: the super admin holds no seat (calibration_tier_of, is_hod_of and
# _ceo_candidate_error all exclude admins). None = every POST; a set = only those `action` values (the default action
# when the form sends none is in SUPER_BAND_DEFAULT_ACTION). test_super_band_remark fails a calibration writer missing
# here. The PAT fit (admin_performance_pbt_fit) and Reopen ask their own, so they are not listed.
SUPER_BAND_ENDPOINTS = {
    # the super tier and the Final bands queue
    "pm_calibration_override": None,
    "pm_calibration_override_clear": None,
    "admin_final_bands": frozenset({"decide", "accept_agreed", "clear", "reopen"}),
    # acting at a tier: performance (adjust, reset, lock, unlock; the Group Chief's lock of people)
    **{"pm_calibration_%s_%s" % (t, a): None for t in ("hod", "buceo", "bgceo", "group")
       for a in ("adjust", "reset", "lock", "unlock")},
    "pm_calibration_group_lock_people": None,
    # acting at a tier: potential (the classic pages)
    **{"calibration_%s_%s" % (t, a): None for t in ("hod", "company", "bg") for a in ("adjust", "reset", "lock", "unlock")},
    "calibration_bugroup_lock": None, "calibration_bugroup_unlock": None,   # a calibration group's (2026-10-22)
    # the Talent Box (a move, a lock)
    **{"talent_box_%s_%s" % (t, a): None for t in ("buceo", "bgceo", "group") for a in ("move", "lock")},
    # Talent Box Round 2 (2026-11-15): the actual PAT moves the curve every locked band is read against, opening a round and
    # locking it again move bands, and Apply all moves them through the shared writer. Each takes the super admin's remark (a
    # form that names its round and gives none takes the round's: TB_ROUND_REMARK_ENDPOINTS); the BG CEO is never asked.
    "admin_tb_round_actual": None, "admin_tb_round_open": None, "admin_tb_round_lock": None, "tb_round_apply": None,
    # rules that re-band people at once
    "admin_pm_calibration_groups": frozenset({"set_mode", "unlock"}),
    "admin_performance_config": frozenset({"set_mechanism", "set_bands", "set_five", "rule_save", "rule_remove"}),
    # points_360 / points_tc (2026-11-09): the points per answer re-score a cycle's potential at once; the reason is the
    # remark. Their `_check` steps write nothing and are not here.
    "admin_settings": frozenset({"cycle_cutoffs", "thresholds", "band_weights", "extremes", "rules", "tb_limits",
                                 "points_360", "points_tc"}),
    # Grade H Appraisal (piece 6): the super admin's change to a final band, and the two saves that re-work bands at once
    "admin_gradeh_final": None,
    # BU KPI setup (2026-11-14): bringing the lines still on earlier figures onto the saved setup re-scores them against the new target; the
    # late amendment of a saved setup's target, unit and method (the Department Review has started) re-scores lines already calibrated
    "admin_bu_kpis": frozenset({"bring_held", "save_kpi_late"}),
    # Fill BU result (2026-11-14): the super admin's fill reaches people a calibrator has acted on (only a released result is left); the page
    # posts this action only then, and the route refuses a plain apply that would reach them
    "admin_performance_bu_fill": frozenset({"apply_calibrated"}),
    "admin_gradeh_settings": frozenset({"perf_cuts", "pot", "points"}),   # "points" (2026-11-09): the points re-work the potential at once; its check is the GET ?preview=points
    # Transferred (2026-11-03): a person's Year-End KPI result blends their Mid-Year score; the mark and its removal move the band
    "admin_person_split_year": None, "admin_person_split_year_remove": None,
}
SUPER_BAND_DEFAULT_ACTION = {"admin_performance_config": "set_mechanism", "admin_settings": "thresholds"}
# the endpoints whose remark may be the round's own (a form that names `round_id`): a move and the lock on a Round 2, Lock Round 2, Apply all
TB_ROUND_REMARK_ENDPOINTS = frozenset({"talent_box_bgceo_move", "talent_box_bgceo_lock", "admin_tb_round_lock", "tb_round_apply"})
SUPER_BAND_REMARK_LABEL = "Your remark (required): why, for the audit trail"


def _super_band_action(endpoint, form):
    """Is this POST one of the band actions above? (The endpoint, and for a multi-action page the action.)"""
    if endpoint not in SUPER_BAND_ENDPOINTS:
        return False
    acts = SUPER_BAND_ENDPOINTS[endpoint]
    return acts is None or ((form.get("action") or SUPER_BAND_DEFAULT_ACTION.get(endpoint, "")) in acts)


def _super_remark_now():
    """The super admin's remark for this request's band action, once the gate has checked it; else None."""
    return getattr(g, "super_band_remark", None) if has_request_context() else None


def _with_super_remark(detail):
    """An audit row's detail with the super admin's remark on it (unless it already says it)."""
    r = _super_remark_now()
    if not r or (detail and r in detail):
        return detail
    return ("%s · remark: %s" % (detail, r)) if detail else "remark: " + r


@app.template_global()
def super_remark_attrs(confirm=None, ok=None):
    """The confirm box's remark, for a form or an autosaving row that changes a band, when the super admin is the one
    looking; nothing for anyone else (a seat holder on the same page is never asked). `confirm` / `ok` add the box's
    message and button for a form that had no confirm of its own."""
    me = current_user() if has_request_context() else None
    if not me or not is_super(me):
        return Markup("")
    attrs = []
    if confirm:
        attrs.append('data-confirm="%s"' % _mescape(confirm))
    if ok:
        attrs.append('data-confirm-ok="%s"' % _mescape(ok))
    attrs += ['data-confirm-reason="%s"' % _mescape(SUPER_BAND_REMARK_LABEL), 'data-confirm-reason-field="remark"',
              'data-confirm-reason-max="%d"' % SUPER_BAND_REMARK_MAX,
              'data-confirm-reason-placeholder="What this changes and why, e.g. agreed at the group calibration meeting"']
    return Markup(" " + " ".join(attrs))


def _pat_unit_lock(db, pid, company):
    """The BU CEO's lock on one unit's performance calibration: None, or {at, by}."""
    if not company:
        return None
    r = db.execute("SELECT s.locked_at, u.full_name FROM pm_calibration_sessions s LEFT JOIN users u ON u.id=s.locked_by "
                   "WHERE s.cycle_id=? AND s.tier='buceo' AND s.scope_key=? AND s.locked_at IS NOT NULL",
                   (pid, company)).fetchone()
    return {"at": r[0], "by": r[1]} if r else None


def _pat_locked_units(db, pid, bg, company):
    """[(unit, lock)] for one unit whose BU CEO has locked: the unit itself, or nothing. A business group has no figure
    of its own any more (PAT Ref, 2026-10-27), so an empty company locks nothing."""
    if not company:
        return []
    lk = _pat_unit_lock(db, pid, company)
    return [(company, lk)] if lk else []


def _pat_bg_locked(db, pid, bg, company):
    """Whether the BG CEO's Talent Box lock already decided this unit (their bands are then final)."""
    return bool(db.execute("SELECT 1 FROM talent_box_bu_locks WHERE period_id=? AND business_group=? AND company=?",
                           (pid, bg, company)).fetchone()
                or db.execute("SELECT 1 FROM pm_calibration_sessions WHERE cycle_id=? AND tier='bgceo' AND scope_key=? "
                              "AND locked_at IS NOT NULL", (pid, bg)).fetchone())


def _pat_flag_changes(db, pid, bg, locked, before, actor_id, commit=True):
    """After a PAT change, flag each locked unit it moved: the curve the BU CEO locked on is kept from the first change
    since their lock; a later change keeps it and clears an earlier fit."""
    for c_, lk in locked:
        row = db.execute("SELECT changed_at FROM pm_pat_lock_flags WHERE cycle_id=? AND business_group=? AND company=?",
                         (pid, bg, c_)).fetchone()
        if not row or (row[0] or "") < (lk["at"] or ""):
            prior = before.get(c_) or {}
            db.execute("INSERT OR REPLACE INTO pm_pat_lock_flags(cycle_id, business_group, company, locked_curve, "
                       "locked_pct, changed_at, changed_by) VALUES (?,?,?,?,?,datetime('now'),?)",
                       (pid, bg, c_, prior.get("key") or "normal", prior.get("pct") if prior.get("entered") else None,
                        actor_id))
        else:
            db.execute("UPDATE pm_pat_lock_flags SET changed_at=datetime('now'), changed_by=?, fitted_at=NULL, "
                       "fitted_by=NULL, fit_moves=NULL, fit_remark=NULL WHERE cycle_id=? AND business_group=? AND "
                       "company=?", (actor_id, pid, bg, c_))
    if commit:
        db.commit()


def _pat_fit_fingerprint(moves):
    return hashlib.sha256(json.dumps([(m["id"], m["from"], m["to"]) for m in moves]).encode()).hexdigest()[:16]


def _pat_lock_view(db, me, pid, bg, company, curve):
    """The PAT page's flag for one unit, or None: the BU CEO locked on one curve and the PAT has since moved it to
    another. For the super admin it carries the breaches and the AI fit's moves (write-free), when the BG CEO hasn't
    decided the unit yet."""
    lk = _pat_unit_lock(db, pid, company)
    row = db.execute("SELECT * FROM pm_pat_lock_flags WHERE cycle_id=? AND business_group=? AND company=?",
                     (pid, bg, company)).fetchone() if lk else None
    if not row or (row["changed_at"] or "") < (lk["at"] or "") or row["locked_curve"] == curve["key"]:
        return None
    who = db.execute("SELECT full_name FROM users WHERE id=?", (row["changed_by"],)).fetchone() if row["changed_by"] else None
    fby = db.execute("SELECT full_name FROM users WHERE id=?", (row["fitted_by"],)).fetchone() if row["fitted_by"] else None
    rnd = _tb_round_row(db, pid, bg, company)
    out = {"lock": lk, "was": PM_CURVE_LABELS.get(row["locked_curve"], ("Normal",))[0], "now": curve["label"],
           "changed_at": row["changed_at"], "changed_by": who[0] if who else None, "fitted_at": row["fitted_at"],
           "fitted_by": fby[0] if fby else None, "fit_moves": row["fit_moves"], "fit_remark": row["fit_remark"],
           "bg_locked": _pat_bg_locked(db, pid, bg, company), "moves": None, "off": None,
           # a unit with a Talent Box Round 2 points there, not to the BU CEO fit (2026-11-15)
           "round": {"state": _tb_round_state(rnd), "mode": rnd["mode"], "actual_pct": rnd["actual_pct"],
                     "forecast_pct": rnd["forecast_pct"]} if rnd else None}
    if is_super(me) and not out["bg_locked"] and not rnd:
        try:
            ctx = _pm_calib_resolve(db, me, "buceo", bg=bg, company=company)
            sess = db.execute("SELECT * FROM pm_calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=?",
                              (pid, company)).fetchone()
            out["off"] = _pm_calib_lock_breaches(db, "buceo", ctx, sess)
            if out["off"]:
                fit = _pm_calib_fit_moves(db, me, ctx, "buceo")
                out["moves"] = fit["moves"]
                out["within_after"] = fit["within_after"]
                out["fp"] = _pat_fit_fingerprint(fit["moves"])
                out["list"] = ["%s: %s → %s" % (m["name"], PM_LABEL_NAMES.get(m["from"], m["from"]),
                                                 PM_LABEL_NAMES.get(m["to"], m["to"])) for m in fit["moves"]]
        except Exception as e:   # the flag still shows; only the fit is held back
            app.logger.warning("PAT fit preview skipped for %s / %s: %s", bg, company, e)
    return out


@app.route("/admin/performance/pbt/fit", methods=["POST"])
@super_required
def admin_performance_pbt_fit():
    """The super admin's one-click AI fit of a locked unit to its new PAT curve, with their mandatory remark. The moves
    are the ones the page showed (a fingerprint), written into the BU CEO's session -- which stays locked -- each with
    the remark; the record, the flag and the audit trail follow."""
    db = get_db()
    me = current_user()
    period = active_pm_period(db)
    bg = (request.form.get("business_group") or "").strip()
    company = (request.form.get("company") or "").strip()
    back = url_for("admin_performance_pbt")
    if not period or not company or company not in org_map(db).get(bg, []):
        abort(400)
    remark, err = _super_band_remark(request.form.get("remark"))
    if err:
        flash(err, "error")
        return redirect(back)
    lk = _pat_unit_lock(db, period["id"], company)
    if not lk:
        flash("%s isn't locked by its BU CEO, so there is nothing to fit: they calibrate it themselves."
              % display_company(bg, company), "error")
        return redirect(back)
    if _pat_bg_locked(db, period["id"], bg, company):
        flash("The BG CEO has already locked %s on the Talent Box: their bands are final. Unlock it first to refit."
              % display_company(bg, company), "error")
        return redirect(back)
    ctx = _pm_calib_resolve(db, me, "buceo", bg=bg, company=company)
    fit = _pm_calib_fit_moves(db, me, ctx, "buceo")
    if not fit["moves"]:
        flash("%s already sits within its curve: nothing to move." % display_company(bg, company), "ok")
        return redirect(back)
    if _pat_fit_fingerprint(fit["moves"]) != (request.form.get("fp") or ""):
        flash("%s's bands changed since the page was opened: look at the moves again." % display_company(bg, company),
              "error")
        return redirect(back)
    curve = pm_curve_for_scope(db, ctx)
    who = {p["id"]: p for p in ctx["population"]}
    note = "%s (super admin, fitted to the %s curve after the PAT change)" % (remark, curve["label"])
    for m in fit["moves"]:
        co = who[m["id"]]["company"] if m["id"] in who else company
        sess = _pm_calib_get_or_create_session(db, period["id"], "buceo", co, bg, display_company(bg, co))
        _pm_calib_upsert_adjustment(db, sess["id"], m["id"], m["from"], m["to"], note[:SUPER_BAND_REMARK_MAX + 120],
                                    me["id"])
        log_activity(db, me["id"], "pm_pat_fit", "%s / %s: %s -> %s. Remark: %s. AI fit: %s" % (
            bg, co, m["from"], m["to"], remark, "; ".join(m.get("reasons") or [])[:400]), target_user_id=m["id"])
    db.execute("UPDATE pm_pat_lock_flags SET fitted_at=datetime('now'), fitted_by=?, fit_moves=?, fit_remark=? "
               "WHERE cycle_id=? AND business_group=? AND company=?",
               (me["id"], len(fit["moves"]), remark, period["id"], bg, company))
    log_activity(db, me["id"], "pm_pat_fit", "%s / %s: %d moved to the %s curve%s. Remark: %s" % (
        bg, company, len(fit["moves"]), curve["label"], "" if fit["within_after"] else " (closer, not all within)",
        remark))
    _rating_record_refresh(db, period["id"], [m["id"] for m in fit["moves"]], "pm_pat_fit", me["id"])
    db.commit()
    flash("%s: %d %s moved to fit the %s curve, with your remark; the BU CEO's lock stays. %s" % (
        display_company(bg, company), len(fit["moves"]), "person" if len(fit["moves"]) == 1 else "people",
        curve["label"], "" if fit["within_after"] else "Some bands still sit outside it: they need a calibrator's call."),
        "ok")
    return redirect(back)


def _pm_kpi_values(rec, cfg, kpi_name):
    """One KPI line's numbers from a record keyed by normalised column names: (values, None) or (None, why). The
    import reads its file rows through it and the person page reads its form through it, so a line the person page
    saves is a line the import would have accepted. `cfg` is the subject's pm_bg_config row (it says which columns
    the line must carry)."""
    bg = cfg["business_group"]
    weightage_raw = _pick(rec, "weightage", "weightage %", "weight")
    try:
        weightage = float(weightage_raw.rstrip("%")) if weightage_raw else None
    except ValueError:
        weightage = None
    if weightage is None:
        return None, f"'{kpi_name}' has no valid Weightage."
    # Weightage is the denominator of pm_overall_mechanism_a/b's
    # weighted average, so a zero, negative or non-finite one isn't a
    # cosmetic data-quality issue -- it makes the person's whole
    # overall unscorable. Deliberately a per-ROW check only: no
    # per-person "must total 100%" rule here, because a real imported
    # BG summed to 105 and normalizing by the weightage actually
    # present is the confirmed behaviour (the employee-driven
    # /performance/setting path enforces 100% because the employee is
    # composing the set themselves; an HR import is not).
    if not math.isfinite(weightage) or weightage <= 0:
        return None, f"'{kpi_name}' Weightage must be a positive number (got '{weightage_raw}')."
    method_raw = _pick(rec, "method").strip().lower()
    method = {"more": "more", "less": "less"}.get(method_raw)
    if not method:
        return None, f"'{kpi_name}' Method must be 'More' or 'Less' (got '{method_raw}')."
    v = {"category": _pick(rec, "strategic thrust / category", "category", "strategic thrust") or None,
         "description": _pick(rec, "kpi description", "description") or None,
         "weightage": weightage, "unit": kpi_unit_normalise(_pick(rec, "unit of measure", "unit")), "method": method,
         "rate1": None, "rate2": None, "rate3": None, "rate4": None, "rate5": None,
         "threshold": None, "target": None, "multiple": None, "excellence": None}
    if cfg["mechanism"] == "A":
        try:
            rates = [float(_pick(rec, f"rate {i}", f"rate{i}")) for i in range(1, 6)]
        except ValueError:
            return None, f"'{kpi_name}' needs Rate 1-5 (Mechanism A for {bg})."
        v["rate1"], v["rate2"], v["rate3"], v["rate4"], v["rate5"] = rates
    else:
        try:
            v["threshold"] = float(_pick(rec, "threshold"))
            v["target"] = float(_pick(rec, "target"))
        except ValueError:
            return None, f"'{kpi_name}' needs Threshold and Target (Mechanism B for {bg})."
        if cfg["variant"] == "excellence":
            try:
                v["excellence"] = float(_pick(rec, "excellence"))
            except ValueError:
                return None, f"'{kpi_name}' needs Excellence ({bg} uses the Excellence variant)."
        else:
            try:
                v["multiple"] = int(float(_pick(rec, "multiple") or "0"))
            except ValueError:
                return None, f"'{kpi_name}' has an invalid Multiple."
    scale_err = pm_scale_error(cfg, method, v, kpi_name)
    if scale_err:
        return None, scale_err
    return v, None


def _pm_kpi_moderator(db, subject, mm_eid, kpi_name):
    """The ONE moderator of a KPI line (Chris, 2026-10-10): the matrix manager whose Employee ID is given, else the
    subject's line manager. ({approver_ids, route: 'lm'|'matrix'|'none', moderator_name}, None) or (None, why).
    Shared by the import and the person page. The LM's own ID counts as the line manager."""
    if mm_eid:
        mm = _eid_resolve(db, mm_eid)[0]   # their main ID, or another of their IDs (a linked ID, 2026-10-29)
        if mm is not None and mm["role"] == "admin":
            mm = None
        if not mm or mm["left_at"]:
            return None, f"'{kpi_name}' matrix manager '{mm_eid}' is not an active employee."
        if mm["id"] == subject["id"]:
            return None, f"'{kpi_name}' names them as their own matrix manager; nobody moderates their own KPI."
        lm_ = mm["id"] == subject["manager_id"]   # the LM's own ID counts as the line manager
        # the Executive Chairman's direct reports have no moderator while his Moderate tick is off (2026-11-03): the LM route
        # gives an EMPTY chain, and the delegate is never named as a matrix manager of theirs either
        if (lm_ and _pm_chair_unmoderated(db, subject["id"], mm["id"])) or (
                not lm_ and _pm_chair_delegate_barred(db, subject["manager_id"], mm["id"])):
            return {"approver_ids": [], "route": "chair", "moderator_name": None}, None
        return {"approver_ids": [mm["id"]], "route": "lm" if lm_ else "matrix", "moderator_name": mm["full_name"]}, None
    if subject["manager_id"]:
        if _pm_chair_unmoderated(db, subject["id"], subject["manager_id"]):
            return {"approver_ids": [], "route": "chair", "moderator_name": None}, None
        return {"approver_ids": [subject["manager_id"]], "route": "lm", "moderator_name": None}, None
    return {"approver_ids": [], "route": "none", "moderator_name": None}, None


def _pm_carry_kpis(db, src_id, new_id, by_id):
    """Carry the AGREED KPI lines of one cycle into a new one (2026-10-15: an Early Year's agreed KPIs are the ones its
    Mid-Year checks in on). Approved lines only, of people taking part in the new cycle (the active one by now --
    participant_sql reads it); each line keeps every column of its own (name, weight, scale, matrix manager's chain)
    but none of its results, approvals or files, which belong to the cycle they were made in. A moderator who has left
    is replaced by the person's line manager. The caller commits. Returns {lines, people, skipped, source}."""
    src = db.execute("SELECT name FROM cycles WHERE id=?", (src_id,)).fetchone()
    keep = [r[1] for r in db.execute("PRAGMA table_info(pm_kpi_targets)")
            if r[1] not in ("id", "cycle_id", "created_at", "created_by", "updated_at", "updated_by")]
    rows = db.execute("SELECT t.id, t.subject_id, %s FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
                      "WHERE t.cycle_id=? AND t.status='approved' AND %s ORDER BY t.subject_id, %s"
                      % (", ".join("t." + c for c in keep), participant_sql("u", 'pm'), PM_LINE_ORDER_T), (src_id,)).fetchall()
    every = {r[0] for r in db.execute("SELECT DISTINCT subject_id FROM pm_kpi_targets WHERE cycle_id=? "
                                      "AND status='approved'", (src_id,))}
    # a name merged in the library's merge queue comes in as the KPI it went into: a variant's qualifier becomes the
    # line's Focus ("Channel sales: A tier" -> "Channel sales · A tier"), a near-duplicate takes the kept name
    # (2026-10-18; "lines that used an old name keep their history and read the new name from the next cycle")
    alias = {(r["business_group"], r["alias_key"]): r for r in db.execute(
        "SELECT * FROM pm_kpi_aliases WHERE kind IN ('variant','dupe')")}
    lines, people = 0, set()
    nomod = _pm_chair_unmod_ids(db)   # the Executive Chairman's direct reports carry no moderator while his tick is off (2026-11-03)
    for r in rows:
        vals = {c: r[c] for c in keep}
        al = alias.get((r["business_group"], _kpi_key(r["kpi_name"])))
        if al:
            focus = al["qualifier"] if al["kind"] == "variant" else (r["focus"] if "focus" in keep else None)
            vals["kpi_name"] = kpi_line_name(al["into_name"], focus)
            if "focus" in vals:
                vals["focus"] = focus or None
        if "unit" in vals:   # its unit read as the standard spells it (KPI_UNITS); the figures stay as agreed
            vals["unit"] = kpi_unit_normalise(vals["unit"])
        cur = db.execute("INSERT OR IGNORE INTO pm_kpi_targets(cycle_id, created_by, %s) VALUES (?, ?, %s)"
                         % (", ".join(keep), ",".join("?" * len(keep))), [new_id, by_id] + [vals[c] for c in keep])
        if not cur.rowcount:
            continue
        chain = [a[0] for a in db.execute(
            "SELECT a.approver_id FROM pm_kpi_target_approvers a JOIN users v ON v.id=a.approver_id "
            "WHERE a.kpi_target_id=? AND v.left_at IS NULL ORDER BY a.seq", (r["id"],))]
        if r["subject_id"] in nomod:   # a matrix manager of record stays; the chair and his delegate never moderate them
            chain = [a for a in chain if a not in (_chair_state(db)["chair"], _chair_state(db)["delegate"])]
        elif not chain:
            lm = db.execute("SELECT m.id FROM users s JOIN users m ON m.id=s.manager_id WHERE s.id=? "
                            "AND m.left_at IS NULL", (r["subject_id"],)).fetchone()
            chain = _pm_default_moderators(db, r["subject_id"], lm[0]) if lm else []
        _pm_set_moderator(db, cur.lastrowid, chain)
        lines += 1
        people.add(r["subject_id"])
    return {"lines": lines, "people": len(people), "skipped": len(every - people),
            "source": src["name"] if src else "the earlier cycle"}


def _pm_set_moderator(db, kpi_target_id, approver_ids):
    """Replace a KPI line's chain with this one (one step, or none). The caller has checked nobody has acted on it."""
    db.execute("DELETE FROM pm_kpi_target_approvers WHERE kpi_target_id=?", (kpi_target_id,))
    for seq, aid in enumerate(approver_ids, start=1):
        db.execute("INSERT INTO pm_kpi_target_approvers(kpi_target_id, seq, approver_id) VALUES (?,?,?)",
                   (kpi_target_id, seq, aid))


# ---- Every import in four steps (Chris, 2026-10-26: "for all our import function, we should have the 4 steps flow,
# first is the file upload, second is QC, third is to mark the changes (preview on how it will affect the production
# data) and get the inputs from the super admin, lastly is final preview and apply"; canvas
# [design canvas link removed]; "super admin only, KPI targets first then the rest"). The People
# import's kept file, made shared: step 1 keeps the file on the server under a token for a day, every later step re-checks
# THAT file against today's OneHR, and Apply needs the quality step and the changes step seen on the same findings, plus
# the super admin's decisions. Nothing is written before Apply, which backs the database up first.
IMPORT_CHECK_DIR = os.path.join(DATA_DIR, "uploads", "import_check")
IMPORT_KEEP_SECONDS = 86400
IMPORT_BACKUPS_KEEP = 10


def _imp_dir(kind):
    d = os.path.join(IMPORT_CHECK_DIR, re.sub(r"[^a-z0-9_]", "", kind))
    os.makedirs(d, exist_ok=True)
    return d


def _imp_stage(kind, me, filename, data, **meta):
    """Keep an uploaded import file for its later steps: (token). Only its uploader goes on with it, for a day."""
    d = _imp_dir(kind)
    for f in os.listdir(d):   # tidy: anything older than a day is gone
        fp = os.path.join(d, f)
        try:
            if time.time() - os.path.getmtime(fp) > IMPORT_KEEP_SECONDS:
                os.remove(fp)
        except OSError:
            pass
    token = secrets.token_hex(16)
    with open(os.path.join(d, token + ".bin"), "wb") as fh:
        fh.write(data)
    os.chmod(os.path.join(d, token + ".bin"), 0o600)   # a roster carries personal data
    with open(os.path.join(d, token + ".json"), "w") as fh:
        json.dump(dict(meta, admin=me["id"], filename=filename), fh)
    return token


def _imp_meta(kind, token, me=None):
    """A kept import's record (its uploader, file name, what each step saw, the decisions, the result), {} if none, or
    if `me` is given and it isn't theirs."""
    if not re.fullmatch(r"[0-9a-f]{32}", token or ""):
        return {}
    p = os.path.join(_imp_dir(kind), token + ".json")
    try:
        meta = json.load(open(p))
        if time.time() - os.path.getmtime(p) > IMPORT_KEEP_SECONDS:
            return {}
    except (OSError, ValueError):
        return {}
    if me is not None and meta.get("admin") != me["id"]:
        return {}
    return meta


def _imp_staged(kind, me, token):
    """(record, bytes) of a kept import file, or None (unknown, expired, applied, or someone else's)."""
    meta = _imp_meta(kind, token, me)
    if not meta:
        return None
    try:
        return meta, open(os.path.join(_imp_dir(kind), token + ".bin"), "rb").read()
    except OSError:
        return None


def _imp_meta_set(kind, token, **kv):
    p = os.path.join(_imp_dir(kind), token + ".json")
    try:
        meta = json.load(open(p))
    except (OSError, ValueError):
        return
    meta.update(kv)
    with open(p, "w") as fh:
        json.dump(meta, fh)


def _imp_unstage(kind, token):
    """The file is gone once applied; its record stays for the done page and its download, until the day is out."""
    try:
        os.remove(os.path.join(_imp_dir(kind), token + ".bin"))
    except OSError:
        pass


def _imp_fp(obj):
    return hashlib.sha1(json.dumps(obj, sort_keys=True, default=str, ensure_ascii=False).encode()).hexdigest()[:16]


def _imp_backup_dir():
    """Where an import's backup goes: L360_IMPORT_BACKUP_DIR; else the server's backups folder beside a live app
    (the server's own backups folder); else a folder beside the database (a local copy, the test harness)."""
    env = os.environ.get("L360_IMPORT_BACKUP_DIR")
    if env:
        return env
    return os.path.join(os.path.dirname(os.path.abspath(DB_PATH)), "import-backups")


def _import_backup(kind):
    """A copy of the database taken just before an import applies: (file name, None) or (None, why). Named
    leadership360-<UTC time>-import-<kind>.db; OneHR keeps the newest IMPORT_BACKUPS_KEEP (production's database was
    38 MB on 2026-10-25, so a copy takes a moment). backup_db.sh's own copies are untouched by this tidy."""
    d = _imp_backup_dir()
    try:
        os.makedirs(d, exist_ok=True)
        name = "leadership360-%s-import-%s.db" % (time.strftime("%Y%m%d-%H%M%S", time.gmtime()),
                                                  re.sub(r"[^a-z0-9]+", "-", kind))
        dest = os.path.join(d, name)
        src, out = sqlite3.connect(DB_PATH), sqlite3.connect(dest)
        try:
            src.backup(out)
        finally:
            out.close()
            src.close()
        chk = sqlite3.connect(dest)
        try:
            ok = chk.execute("PRAGMA quick_check").fetchone()[0]
        finally:
            chk.close()
        if ok != "ok":
            os.remove(dest)
            return None, "the backup taken before applying didn't check out"
        os.chmod(dest, 0o600)
        mine = sorted((f for f in os.listdir(d)
                       if re.fullmatch(r"leadership360-\d{8}-\d{6}-import-[a-z0-9-]+\.db", f)), reverse=True)
        for f in mine[IMPORT_BACKUPS_KEEP:]:
            try:
                os.remove(os.path.join(d, f))
            except OSError:
                pass
        return name, None
    except (OSError, sqlite3.Error) as e:
        app.logger.warning("import backup failed: %s", e)
        return None, "the backup taken before applying failed"


# ---- Every import in four steps (Chris, 2026-10-26: "for all our import function, we should have the 4 steps flow,
# first is the file upload, second is QC, third is to mark the changes (preview on how it will affect the production
# data) and get the inputs from the super admin, lastly is final preview and apply"; canvas
# [design canvas link removed]). The KPI targets import has its own pages (below); every other
# import page registers a spec here and runs on _imp_page / _imp_post, with templates/_import_steps.html drawing the
# steps. A spec's callables:
#   load(db, me, meta, data) -> ctx: {"errors": [{row, eid, why}], "rows": n, "valid": [...], "look": {key: [found]},
#       "blank_rows": n, ...}; each found item {row, eid, rows, detail}. Never writes.
#   changes(db, me, ctx, decisions) -> {"tiles", "sections", "decide", "fp"}: step 3 (decide: the groups of items only
#       the super admin answers, each item {key, cells, choice?}).
#   after(db, me, ctx, decisions) -> {"lede", "tiles", "head", "rows", "more", "confirm"}: step 4.
#   apply(db, me, ctx, decisions) -> {"summary", "lines"}: writes, commits and logs (its audit row names the decisions).
#   downloads(db, me, ctx, decisions, what) -> (file name, header, rows) for what = changes / final.
# The quality step, the fingerprints that send an admin back a step when OneHR moved, the super admin's decisions, the
# backup before Apply and the done page are the same for all of them.
_IMP = {}


def _imp_register(kind, **spec):
    _IMP[kind] = dict(kind=kind, **spec)


def _imp_quality(spec, ctx):
    """The quality step from a spec's check: {fix, look, rows, n_fix, n_look, clean, fingerprint}, as the KPI import's."""
    fix = {}
    for e in ctx["errors"]:
        fix.setdefault(_imp_err_kind(spec, e["why"]), []).append(e.get("row") or 0)
    fix_l = sorted(({"kind": k, "n": len(v), "rows": sorted({r for r in v if r})} for k, v in fix.items()),
                   key=lambda x: (-x["n"], x["kind"]))
    look = ctx.get("look") or {}
    look_l = [{"key": k, "what": one if len(look.get(k) or ()) == 1 else many, "why": y, "n": len(look[k]),
               "found": look[k]} for k, one, many, y in spec.get("look", ()) if look.get(k)]
    flagged = {rw for g in look_l if g["key"] not in spec.get("look_skips", ()) for f in g["found"]
               for rw in (f.get("rows") or [f.get("row")]) if rw}
    rows = ctx.get("rows") or 0
    bad = {e.get("row") for e in ctx["errors"] if e.get("row")}
    fp = _imp_fp([fix_l, [(g["key"], [(f.get("eid"), f["detail"]) for f in g["found"]]) for g in look_l]])
    return {"fix": fix_l, "look": look_l, "rows": rows, "n_fix": len(ctx["errors"]),
            "n_look": sum(g["n"] for g in look_l),
            "clean": max(0, rows - len(bad | flagged) - sum(1 for e in ctx["errors"] if not e.get("row"))),
            "fingerprint": fp}


def _imp_err_kind(spec, why):
    if spec.get("err_kind"):
        return spec["err_kind"](why)
    for label, pat in spec.get("fix_kinds", ()):
        if re.search(pat, why, re.I):
            return label
    return "Other"


def _imp_items(ch):
    """Every item step 3 asks about, each with its form field (d_ + a hash of its key)."""
    out = []
    for g in ch.get("decide") or ():
        if g.get("reason"):   # a group's one written reason, kept with the answers (the roster's hand-over)
            g["reason"].setdefault("fid", "d_" + hashlib.sha1(g["reason"]["key"].encode()).hexdigest()[:10])
        for it in g["items"]:
            it.setdefault("fid", "d_" + hashlib.sha1(it["key"].encode()).hexdigest()[:10])
            it.setdefault("options", g["options"])
            out.append(it)
    return out


def _imp_reason_issue(ch, decisions):
    """The sentence why a group's written reason isn't good enough yet, or None: when any row of a group is answered with
    the option that needs it, the reason must be there, within its limit and not an instruction (it reaches people)."""
    for g in ch.get("decide") or ():
        rs = g.get("reason")
        if not rs or not any(decisions.get(it["key"]) == rs["needs"] for it in g["items"] if it["key"] in rs.get("only", {it["key"]})):
            continue
        txt = (decisions.get(rs["key"]) or "").strip()
        if not txt:
            return rs["missing"]
        if len(txt) > rs["max"]:
            return "Keep the reason under %d characters." % rs["max"]
        if ai_draft.stored_text_refusal(txt, "manager"):
            return "Reword the reason: it reads like an instruction rather than a reason."
    return None


def _imp_load(kind, db, me, token):
    """(spec, meta, ctx, quality) of a kept file, checked again against today's OneHR, or None."""
    spec = _IMP[kind]
    got = _imp_staged(kind, me, token)
    if not got:
        return None
    meta, data = got
    try:
        ctx = spec["load"](db, me, meta, data)
    except Exception as e:  # noqa: BLE001 -- a file that read at step 1 and no longer does is chosen again
        app.logger.warning("import %s re-check failed: %s", kind, e)
        return None
    return spec, meta, ctx, (spec["quality"](db, me, ctx) if spec.get("quality") else _imp_quality(spec, ctx))


def _imp_view(kind, db, me, token, step):
    """What the page draws for a kept file at a step (quality / changes / apply), gated: each step needs the one before
    it seen, on what OneHR holds now."""
    got = _imp_load(kind, db, me, token)
    if not got:
        flash("That file's check has expired or isn't yours: choose the file again.", "error")
        return None
    spec, meta, ctx, q = got
    decisions = dict(meta.get("decisions") or {})
    seen = meta.get("quality") == q["fingerprint"] and not ctx["errors"]
    ch = spec["changes"](db, me, ctx, decisions) if seen else None
    items = _imp_items(ch) if ch else []
    for it in items:
        it["choice"] = decisions.get(it["key"]) or it.get("default")
    undecided = _imp_undecided(ch, decisions) if ch else []
    reason_issue = _imp_reason_issue(ch, decisions) if ch else None
    st = "quality"
    if seen and step in ("changes", "apply"):
        st = "changes"
        if step == "apply" and meta.get("changes") == _imp_fp(ch["fp"]) and not undecided and not reason_issue:
            st = "apply"
    v = {"kind": kind, "token": token, "filename": meta.get("filename"), "opts": spec.get("opts_label",
         lambda m: "")(meta), "step": st, "quality": q, "blank_rows": ctx.get("blank_rows") or 0,
         "ch": ch, "n_decide": len(items), "n_done": len(items) - len(undecided), "page": spec["page"],
         "pa": spec.get("page_args") or {},
         "dl": spec["dl"], "checks": spec.get("checks"), "decided_by_super": True}
    if st == "apply":
        v["af"] = spec["after"](db, me, ctx, decisions)
        recap = []
        for g in ch["decide"]:
            if g.get("recap_by"):   # one line a answer, the people together, the reason quoted on the line that needs it (2026-11-09)
                for val, lbl in g["recap_by"]:
                    names = [it["short"] for it in g["items"] if it["choice"] == val]
                    if names:
                        txt = ", ".join(names)
                        if g.get("reason") and val == g["reason"]["needs"] and decisions.get(g["reason"]["key"]):
                            txt += ". Why: " + decisions[g["reason"]["key"]]
                        recap.append((lbl, {"label": txt, "key": val}))
            else:
                recap += [(dict(g["options"]).get(it["choice"], it["choice"]), it) for it in g["items"]]
        v["recap"] = recap
        # the written reasons that count (a group answered with the option that needs one), shown beside the answers
        v["reasons"] = [(g["reason"]["label"], decisions.get(g["reason"]["key"])) for g in ch["decide"]
                        if g.get("reason") and not g.get("recap_by")
                        and any(decisions.get(it["key"]) == g["reason"]["needs"] for it in g["items"]
                                if it["key"] in g["reason"].get("only", {it["key"]}))]
    return v


def _imp_undecided(ch, decisions):
    # an item may carry a `default` (pre-picked, 2026-11-09: the left-out unit move's Keep): it counts as answered
    return [it for it in _imp_items(ch) if (decisions.get(it["key"]) or it.get("default")) not in {o for o, _l in it["options"]}]


def _imp_upload(kind, db, me, opts=None):
    """Step 1: keep the chosen file (after a first read) and go to its quality step."""
    spec = _IMP[kind]
    f = request.files.get("file")
    if not f or not f.filename:
        flash("Choose a CSV or XLSX file to upload.", "error")
        return redirect(url_for(spec["page"], **spec.get("page_args", {})))
    data = f.read()
    try:
        _read_records(f.filename, data)   # a file OneHR can't read stops here
        kept = spec["stage"](db, me, f.filename, data, opts or {}) if spec.get("stage") else data
    except ValueError as e:
        flash(str(e), "error")
        return redirect(url_for(spec["page"], **spec.get("page_args", {})))
    except Exception as e:  # noqa: BLE001
        app.logger.warning("import %s parse failed: %s", kind, e)
        flash("Could not read the file. Check it's a valid CSV or XLSX and try again.", "error")
        return redirect(url_for(spec["page"], **spec.get("page_args", {})))
    token = _imp_stage(kind, me, f.filename, kept, **(opts or {}))
    return redirect(url_for(spec["page"], check=token, **spec.get("page_args", {})))


IMP_STEPS_ONLY_MSG = ("Nothing was imported: choose the file on this page and go through its steps (File, Quality, "
                      "Changes, Apply).")


def _imp_steps_only(endpoint):
    """A POST that is neither step 1 (preview=1) nor a later step (a token) changes nothing (finding 1a-01, 2026-10-31):
    an import applies only through the four steps, so the quality step, the super admin's answers, the final preview and
    the database backup can't be skipped."""
    flash(IMP_STEPS_ONLY_MSG, "error")
    return redirect(url_for(endpoint))


def _imp_post(kind, db, me):
    """Steps 2 to 4 on a kept file: quality_ok (2 -> 3), decide / to_apply (3, the super admin's decisions; -> 4) and
    apply (4). Each checks the file again against today's OneHR."""
    spec = _IMP[kind]
    token = (request.form.get("token") or "").strip()
    action = request.form.get("action") or ""
    here = lambda step=None: redirect(url_for(spec["page"], check=token, **dict(  # noqa: E731
        spec.get("page_args", {}), **({"step": step} if step else {}))))
    got = _imp_load(kind, db, me, token)
    if not got:
        flash("That file's check has expired or isn't yours: choose the file again.", "error")
        return redirect(url_for(spec["page"], **spec.get("page_args", {})))
    spec, meta, ctx, q = got
    if ctx["errors"]:
        flash("Fix the rows that can't be imported in your file and choose it again: nothing was applied.", "error")
        return here()
    if action == "quality_ok":
        if q["n_look"] and request.form.get("ack") != "1":
            flash("Tick “I've looked at these” to go on, or fix them in your file and choose it again.",
                  "error")
            return here()
        _imp_meta_set(kind, token, quality=q["fingerprint"])
        return here("changes")
    if meta.get("quality") != q["fingerprint"]:
        flash("Check the file's quality first: %s" % ("something in OneHR has changed since you looked."
              if meta.get("quality") else "nothing was applied."), "error")
        return here()
    decisions = dict(meta.get("decisions") or {})
    ch = spec["changes"](db, me, ctx, decisions)
    items = _imp_items(ch)
    if action in ("decide", "to_apply"):
        if items:
            if not is_super(me):
                flash("The super admin answers these: ask them to import this file.", "error")
                return here("changes")
            for it in items:
                val = request.form.get(it["fid"])
                if val in {o for o, _l in it["options"]}:
                    decisions[it["key"]] = val
            for g in ch.get("decide") or ():   # a group's written reason: kept as typed (spaces tidied), never a placeholder
                rs = g.get("reason")
                if rs and rs["fid"] in request.form:
                    txt = " ".join(request.form.get(rs["fid"], "").split())
                    if txt:
                        decisions[rs["key"]] = txt
                    else:
                        decisions.pop(rs["key"], None)
            _imp_meta_set(kind, token, decisions=decisions, decided_by=me["id"])
            ch = spec["changes"](db, me, ctx, decisions)
        if action == "decide":
            return here("changes")
        left = _imp_undecided(ch, decisions)
        if left:
            flash("Answer each one to go on: %d still to answer." % len(left), "error")
            return here("changes")
        why = _imp_reason_issue(ch, decisions)
        if why:
            flash(why, "error")
            return here("changes")
        _imp_meta_set(kind, token, changes=_imp_fp(ch["fp"]))
        return here("apply")
    if action == "apply":
        if meta.get("changes") != _imp_fp(ch["fp"]) or _imp_undecided(ch, decisions) or _imp_reason_issue(ch, decisions):
            flash("Something in OneHR changed since you looked at the changes: look at them again. Nothing was "
                  "applied.", "error")
            return here("changes")
        if items and not is_super(me):
            flash("The super admin answers these: ask them to import this file.", "error")
            return here("changes")
        backup, why = _import_backup(kind)
        if not backup:
            flash("Not applied: %s. Nothing changed; try again in a moment." % why, "error")
            return here("apply")
        try:
            res = spec["apply"](db, me, ctx, decisions)
        except ValueError as e:   # refused part way: none of it is kept
            db.rollback()
            flash("Not applied: %s Nothing changed." % e, "error")
            return here("apply")
        _imp_meta_set(kind, token, result=dict(res, at=time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime()),
                                               backup=backup, n_decided=len(items)))
        _imp_unstage(kind, token)
        return redirect(url_for(spec["page"], done=token, **spec.get("page_args", {})))
    return here()


def _imp_get(kind, db, me):
    """The page's (v, done) for a GET: a kept file at its step, or the done page of one just applied."""
    token = request.args.get("check") or ""
    if token:
        return _imp_view(kind, db, me, token, request.args.get("step")), None
    dt = request.args.get("done") or ""
    if dt:
        meta = _imp_meta(kind, dt, me)
        if meta.get("result"):
            return None, dict(meta["result"], filename=meta.get("filename"), token=dt)
    return None, None


def _imp_download(kind, db, me, token):
    """A kept file's issues (?what=issues[&kind=]), every change (?what=changes) or the final preview (?what=final),
    checked again so the file is exactly what the page counted."""
    got = _imp_load(kind, db, me, token)
    if not got:
        abort(404)
    spec, meta, ctx, q = got
    what = request.args.get("what") or "issues"
    what = "issues" if what == "errors" else what   # the roster's old address
    decisions = dict(meta.get("decisions") or {})
    if what == "issues":
        k = request.args.get("kind") or ""
        rows = [] if k else [[e.get("row") or "", e.get("eid") or "", "Can't be imported",
                              _imp_err_kind(spec, e["why"]), e["why"]] for e in ctx["errors"]]
        for g in q["look"]:
            if not k or g["key"] == k:
                rows += [[i.get("row") or "", i.get("eid") or "", "Worth a look", g["what"], i["detail"]]
                         for i in g["found"]]
        return _xlsx_response("%s-issues.xlsx" % spec["file"], [("Issues", ["Row", "Employee ID", "Severity",
                                                                              "What", "Detail"], rows)])
    if what in ("changes", "final"):
        fn, head, rows = spec["downloads"](db, me, ctx, decisions, what)
        return _xlsx_response("%s-%s.xlsx" % (spec["file"], fn), [(fn.replace("-", " ").capitalize()[:31], head,
                                                                    rows)])
    abort(404)


# ---- The KPI targets import (Performance > Run > Import KPI targets) in four steps ----
KTI_KIND = "kpi_targets"
_KTI_LOOK = (   # (key, said of one, said of several, why it matters)
    # a linked Employee ID (2026-10-29) is informational: the line goes in right, so it never makes a row "not clean"
    ("linked", "row uses another of the person's IDs (a linked ID)", "rows use another of the person's IDs (linked IDs)",
     "The file uses another of their IDs: their lines go in under their main ID."),
    ("weights", "person's KPI weights don't add up to 100%", "people's KPI weights don't add up to 100%",
     "Each person's KPIs should total 100%, or their score is off. The import doesn't stop them."),
    ("not_part", "person isn't taking part in this cycle", "people aren't taking part in this cycle",
     "Their rows are skipped. Add them on Participants first if they should take part."),
    ("units", "unit written another way", "units written another way", "They're stored in OneHR's standard units."),
    ("library", "KPI isn't in the library", "KPIs aren't in the library",
     "They go in as typed. Propose them for the library afterwards."),
)
_KTI_BU_WHY = {
    "closed": "BU KPI setup reads only now, so it goes in as their own line.",
    "rule": "The unit's BU KPI doesn't cover them (who carries it is set by department or grade), so it goes in as "
            "their own line.",
    "band": "Their grade falls in none of the unit's weight bands, so it goes in as their own line.",
    "clash": "They already carry the unit's KPI by its own name, so this one goes in as their own line.",
    "locked": "Someone has already acted on this line, so it stays as it is.",
}


def _kti_err_kind(verr):
    """The quality step's heading for a row the line check refused."""
    v = verr or ""
    if "Weightage" in v:
        return "A missing or invalid weight"
    if "Method must be" in v:
        return "A method that isn't More or Less"
    if "needs " in v or "invalid Multiple" in v:
        return "A column its scoring needs"
    return "A scale out of order"


def _kti_check(db, me, period, records):
    """The KPI targets import's check of a file's rows, read only: {rows, valid, errors, not_part, blank_rows}. A valid
    row carries the line it would write; an error says why its row can't go in. row = the spreadsheet's row number (the
    header is row 1). Each row's group, unit and department come from the PERSON, never the file, and so does the
    scoring its columns must fit."""
    errors, valid, not_part = [], [], []
    seen_keys, bg_config_cache = {}, {}   # seen_keys: (person, KPI) -> the Employee ID the file used for it first
    blank_rows = rows = 0
    # Linked Employee IDs (2026-10-29): a row's ID can be another of a person's IDs; one batched read finds them, the line
    # goes in under the person's MAIN ID, and the quality step says so (linked)
    resolved = _eid_resolve_many(db, [_pick(rec, "employee id", "eid", "id", "staff id") for rec in records])
    linked = []

    def err(row_n, eid, kind, why):
        errors.append({"row": row_n, "eid": eid or "", "kind": kind, "why": why})

    for i, rec in enumerate(records):
        row_n = i + 2
        eid = _pick(rec, "employee id", "eid", "id", "staff id")
        kpi_raw = _pick(rec, "kpi", "kpi name")
        if eid and not kpi_raw and not any(_pick(rec, _norm_header(c)) for c in KPI_TARGETS_IMPORT_COLUMNS[2:]):
            blank_rows += 1
            continue
        # an optional Focus column: the line is the KPI and its Focus (2026-10-18)
        focus_ = " ".join((_pick(rec, "focus") or "").split())
        kpi_name = kpi_line_name(kpi_raw, focus_) if kpi_raw and focus_ else kpi_raw
        if not eid and not kpi_name:
            continue  # blank line
        rows += 1
        if not eid:
            err(row_n, "", "No Employee ID", f"Row for KPI '{kpi_name}' has no Employee ID.")
            continue
        if eid.upper().startswith("EXAMPLE-"):   # the template's own rows, uploaded unchanged (2026-10-14)
            err(row_n, eid, "The template's example row",
                f"{eid}: this is the template's example row -- replace it with a real Employee ID.")
            continue
        file_cycle = " ".join((_pick(rec, "cycle") or "").split())   # a KPI lines download carries its cycle's name
        if file_cycle and file_cycle != " ".join((period["name"] or "").split()):
            err(row_n, eid, "A different cycle's file",
                f"{eid}: this row is from {file_cycle}, but this import is for {period['name']}.")
            continue
        if not kpi_name:
            err(row_n, eid, "No KPI name", f"{eid}: missing KPI name.")
            continue
        got = resolved.get(eid)
        subject, via_link = got if got and got[0]["role"] != "admin" else (None, False)
        key_ = (subject["id"] if subject else eid, kpi_name)
        if key_ in seen_keys:
            if seen_keys[key_] == eid:
                err(row_n, eid, "The same KPI twice for one person",
                    f"{eid}: KPI '{kpi_name}' appears more than once in the file.")
            else:   # their main ID and a linked ID: one person, the same line twice
                err(row_n, eid, "The same KPI twice for one person",
                    f"{_eid_same_person(seen_keys[key_], eid, subject)}: KPI '{kpi_name}' appears under both.")
            continue
        seen_keys[key_] = eid
        if not subject:
            err(row_n, eid, "Unknown Employee ID", f"{eid}: no such employee.")
            continue
        if via_link:
            linked.append({"row": row_n, "eid": eid, "main": subject["employee_id"], "name": subject["full_name"]})
        if not can_access(me, subject["business_group"], subject["company"]):
            err(row_n, eid, "Outside the data you manage", f"{eid}: outside the data you manage (BG/business unit).")
            continue
        if not is_participant(db, subject, period):
            not_part.append({"row": row_n, "eid": subject["employee_id"]})
            continue
        if setup_released_at(db, subject["id"], period["id"], "pm"):
            err(row_n, eid, "A result already released",
                f"{eid}: their performance result for {period['name']} is released, so their KPI lines are final.")
            continue
        bg = subject["business_group"]
        if bg not in bg_config_cache:
            bg_config_cache[bg] = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?", (bg,)).fetchone()
        cfg = bg_config_cache[bg]
        if not cfg:
            err(row_n, eid, "No scoring set for the group",
                f"{eid}: {bg} has no scoring mechanism configured yet (Business Group config).")
            continue
        vals, verr = _pm_kpi_values(rec, cfg, kpi_name)
        if verr:
            err(row_n, eid, _kti_err_kind(verr), f"{eid}: {verr}")
            continue
        row = dict(vals, row=row_n, eid=subject["employee_id"], subject_id=subject["id"], kpi_name=kpi_name, base_name=kpi_raw,
                   focus=focus_ or None, business_group=bg, company=subject["company"],
                   department=subject["department"], subject_name=subject["full_name"],
                   job=subject["job_title"] or "", unit_typed=" ".join((_pick(rec, "unit of measure", "unit")
                                                                         or "").split()))
        # One moderator for this line: the matrix manager named on the row, else the person's line manager.
        # Unresolved is NOT an error (the row still imports; it surfaces on the Exceptions page).
        mod, merr = _pm_kpi_moderator(db, subject, _pick(rec, "matrix manager id", "matrix manager employee id",
                                                         "matrix manager"), kpi_name)
        if merr:
            err(row_n, eid, "A matrix manager OneHR can't use", f"{eid}: {merr}")
            continue
        row.update(mod)
        valid.append(row)
    return {"rows": rows, "valid": valid, "errors": errors, "not_part": not_part, "blank_rows": blank_rows,
            "linked": linked}


def _kti_num(x):
    try:
        return None if x is None or x == "" else round(float(x), 6)
    except (TypeError, ValueError):
        return None


def _kti_scale_text(v, unit=None):
    """A KPI line's target as one line: "1–5: 2 · 2.4 · 2.8 · 3.2 · 3.6 RM (mil)", or "Threshold … · Target …"."""
    u = (" " + unit) if unit else ""

    def f(x):
        n = _kti_num(x)
        return "–" if n is None else ("%g" % n)
    if any(_kti_num(v[c]) is not None for c in ("rate1", "rate2", "rate3", "rate4", "rate5")):
        return "1–5: " + " · ".join(f(v["rate%d" % i]) for i in range(1, 6)) + u
    if _kti_num(v["threshold"]) is not None or _kti_num(v["target"]) is not None:
        s = "Threshold %s · Target %s" % (f(v["threshold"]), f(v["target"]))
        if _kti_num(v["excellence"]) is not None:
            s += " · Excellence %s" % f(v["excellence"])
        elif _kti_num(v["multiple"]):
            s += " · Multiple %s" % f(v["multiple"])
        return s + u
    return "–"


def _kti_same_scale(a, b):
    return tuple(_kti_num(a[c]) for c in _BU_SCALE_COLS) == tuple(_kti_num(b[c]) for c in _BU_SCALE_COLS)


def _kti_in(db, sql, ids):
    """Rows of `sql` (one IN (%s) slot) for many ids, in chunks, so a large file never hits SQLite's variable limit."""
    ids = list(ids)
    out = []
    for i in range(0, len(ids), 500):
        part = ids[i:i + 500]
        out += db.execute(sql % ",".join("?" * len(part)), part).fetchall()
    return out


def _kti_classify(db, period, chk):
    """Each valid row's fate, worked out once so every step and Apply agree: existing_id; skip = 'approved' (a moderator
    has acted on the line: new targets would re-score a decision they signed off) or 'bu' (it follows its unit's BU KPI
    setup); and an update's changes [(field, from, to)]. Returns the person's current lines too."""
    cid = period["id"]
    valid = chk["valid"]
    sids = sorted({r["subject_id"] for r in valid})
    current = {}
    for t in _kti_in(db, "SELECT * FROM pm_kpi_targets WHERE cycle_id=%d AND subject_id IN (%%s)" % int(cid), sids):
        current.setdefault(t["subject_id"], {})[t["kpi_name"]] = t
    tids = [t["id"] for lines in current.values() for t in lines.values()]
    acted = {r[0] for r in _kti_in(db, "SELECT DISTINCT kpi_target_id FROM pm_kpi_approvals WHERE kpi_target_id IN (%s)",
                                   tids)}
    chain = {}
    for r in _kti_in(db, "SELECT kpi_target_id, approver_id FROM pm_kpi_target_approvers WHERE kpi_target_id IN (%s) "
                         "ORDER BY kpi_target_id, seq", tids):
        chain.setdefault(r[0], []).append(r[1])
    ids = {a for v in chain.values() for a in v} | {a for r in valid for a in r["approver_ids"]}
    names = {u["id"]: u["full_name"] for u in _kti_in(db, "SELECT id, full_name FROM users WHERE id IN (%s)", ids)}
    mgr = {u["id"]: u["manager_id"] for u in _kti_in(db, "SELECT id, manager_id FROM users WHERE id IN (%s)", sids)}

    def who(sid, ap):
        if not ap:
            return "No moderator"
        return "Line manager" if ap[0] == mgr.get(sid) else "%s (matrix manager)" % names.get(ap[0], "?")
    for r in valid:
        t = current.get(r["subject_id"], {}).get(r["kpi_name"])
        r["existing_id"] = t["id"] if t else None
        r["skip"] = None
        r["changes"] = []
        if not t:
            continue
        if t["id"] in acted:
            r["skip"] = "approved"
            continue
        if t["bu_kpi_id"]:
            r["skip"] = "bu"
            continue
        ch = []
        if not _kti_same_scale(t, r):
            ch.append(("Target", _kti_scale_text(t, t["unit"]), _kti_scale_text(r, r["unit"])))
        if _kti_num(t["weightage"]) != _kti_num(r["weightage"]):
            ch.append(("Weight", "%g%%" % (t["weightage"] or 0), "%g%%" % r["weightage"]))
        for field, col in (("Method", "method"), ("Unit", "unit"), ("Category", "category"),
                           ("Description", "description"), ("Focus", "focus")):
            if (t[col] or "") != (r[col] or ""):
                ch.append((field, t[col] or "(none)", r[col] or "(none)"))
        if list(chain.get(t["id"], [])) != list(r["approver_ids"]):
            ch.append(("Moderator", who(r["subject_id"], chain.get(t["id"], [])), who(r["subject_id"], r["approver_ids"])))
        r["changes"] = ch
    return {"current": current}


_KTI_WORD = "(?<![A-Za-z0-9])%s(?![A-Za-z0-9])"   # a unit's name as WHOLE words, any case ("Starken 1" never matches "Starken 10")


def _kti_names(text, term):
    """Whether `text` names `term` as whole words, any case, white space folded: the cross-unit match's one test."""
    term = " ".join((term or "").split())
    return bool(term) and re.search(_KTI_WORD % re.escape(term), " ".join((text or "").split()), re.I) is not None


def _kti_qualifier(name):
    """A saved BU KPI's variant qualifier: what follows the first ': ' in its name ("PAT: Starken 2" -> "Starken 2"), or ''."""
    parts = (name or "").split(": ", 1)
    return parts[1].strip() if len(parts) > 1 else ""


def _kti_unit_terms(bg, co, setups):
    """The words that name a unit in a file's text: its display name, its HRIS name and the variant qualifier of each of its saved BU KPIs
    in `setups` (those of the KPI's root). Deduped without case, none empty."""
    out, seen = [], set()
    for t in [display_company(bg, co), co] + [_kti_qualifier(x["kpi_name"]) for x in setups]:
        t = " ".join((t or "").split())
        if t and t.lower() not in seen:
            seen.add(t.lower())
            out.append(t)
    return out


_KTI_FIELDS = (("Name", "base_name"), ("Focus", "focus"), ("Description", "description"))   # where a file row can name a unit, in this order


def _kti_named_in(row, terms):
    """The field of a file row that names one of `terms` first ('Name', 'Focus' or 'Description'), or None."""
    for label, col in _KTI_FIELDS:
        if any(_kti_names(row.get(col) or "", t) for t in terms):
            return label
    return None


def _kti_pick_setup(cands, row):
    """Among one unit's saved BU KPIs of the row's root, the one the row follows: a row named like a variant ("PAT: Starken 2") is that
    variant; else the variants whose qualifier the row names (one: it; several: all of them, so the super admin picks); else the setup the
    row's name is (the root); else the root setup; else the only one. A list: one (picked) or several (to choose among); empty only when
    `cands` is."""
    if not cands:
        return []
    key = _kpi_key(row["base_name"])
    exact = [x for x in cands if _kpi_key(x["kpi_name"]) == key]
    if exact and _kti_qualifier(exact[0]["kpi_name"]):
        return exact[:1]
    text = " ".join(str(row.get(c) or "") for _l, c in _KTI_FIELDS)
    named = [x for x in cands if _kti_qualifier(x["kpi_name"]) and _kti_names(text, _kti_qualifier(x["kpi_name"]))]
    if named:
        return named
    if exact:
        return exact[:1]
    root = [x for x in cands if not _kti_qualifier(x["kpi_name"])]
    if root:
        return root[:1]
    return list(cands)


def _kti_lib_row(libs, bg, key, co):
    """The library row a new BU KPI of `key` for unit `co` is made from, and whether it is BU-level for that unit already:
    (row, bu_level_here) or (None, False). The unit's own row wins over the group-wide one, a BU-level row over one that is not. Where the
    library marks the KPI BU-level for OTHER units only, that row is the one it is copied from (the KPI becomes BU-level for this unit only,
    `_bu_kpi_unit_row`). A KPI no row of the group marks BU-level is not a BU KPI at all: (None, False)."""
    rows = libs.get((bg, key), [])
    if not any(x["bu_level"] for x in rows):
        return None, False
    here = [x for x in rows if (x["company"] or "*") in ("*", co)]
    if not any(x["bu_level"] for x in here):
        here = [x for x in rows if x["bu_level"]]   # BU-level for another unit: the template to copy for this one
        here.sort(key=lambda x: x["id"])
        return here[0], False
    here.sort(key=lambda x: ((x["company"] or "*") != co, not x["bu_level"], x["id"]))
    return here[0], bool(here[0]["bu_level"])


def _kti_target_sig(r):
    """What a file row's target is, as one comparable value: its method, unit and figures."""
    return (r["method"] or "", kpi_unit_normalise(r["unit"]) or "", tuple(_kti_num(r[c]) for c in _BU_SCALE_COLS))


def _kti_sig_id(sig):
    return hashlib.sha1(json.dumps(sig, sort_keys=True, default=str).encode()).hexdigest()[:8]


def _kti_ctx(db, period, chk, cls, rows, me):
    """The lookups every row of the file is matched against, read once: the cycle's saved BU KPIs (by unit, by root), aliases, the people,
    the library of the groups in the file, and what each person holds after the import."""
    c = {"db": db, "period": period, "me": me, "by_unit": {}, "by_root": {}, "roots": set(), "units": {}, "other_units": None,
         "bu_names": {}}
    for s_ in db.execute("SELECT * FROM pm_bu_kpis WHERE cycle_id=? ORDER BY company, kpi_name", (period["id"],)):
        s_ = dict(s_)
        c["by_unit"].setdefault((s_["business_group"], s_["company"]), {})[_kpi_key(s_["kpi_name"])] = s_
        rk = _kpi_key(_bu_root(s_["kpi_name"]))
        c["by_root"].setdefault((s_["business_group"], rk), []).append(s_)
        c["roots"].add(rk)
    c["aliases"] = {(a["business_group"], a["alias_key"]): a for a in db.execute("SELECT * FROM pm_kpi_aliases")}
    c["people"] = {u["id"]: u for u in _kti_in(db, "SELECT * FROM users WHERE id IN (%s)", {r["subject_id"] for r in rows})}
    c["holds"] = {(sid, _kpi_key(n)) for sid, lines in cls["current"].items() for n in lines}
    c["holds"] |= {(r["subject_id"], _kpi_key(r["kpi_name"])) for r in chk["valid"]}
    groups = sorted({r["business_group"] for r in rows})
    c["libs"] = {}
    for lr in db.execute("SELECT * FROM pm_kpi_library WHERE active=1 AND business_group IN (%s)" % ",".join("?" * len(groups)), groups):
        c["libs"].setdefault((lr["business_group"], _kpi_key(lr["kpi_name"])), []).append(dict(lr))
    # what each person holds once the file is in: {person: {line name: (weight, the KPI's folded base name)}}
    after = {}
    for sid, lines in cls["current"].items():
        for n, t in lines.items():
            after.setdefault(sid, {})[n] = (t["weightage"] or 0, _kpi_key(kpi_line_base(n, t["focus"])))
    for r in chk["valid"]:
        if not r["skip"]:
            after.setdefault(r["subject_id"], {})[r["kpi_name"]] = (r["weightage"] or 0, _kpi_key(r["base_name"]))
    c["after"] = after
    # creating a BU KPI is the writers' own cycle rule (`_bu_add_cycle_refusal`): the super admin, an active cycle outside an Early Year,
    # setup open, a setup of those who carry it now at their own weight
    c["new_why"] = (_bu_add_cycle_refusal(db, me, period, {"cycle_id": period["id"], "carriers": "holders", "weight_mode": "own"})
                    if me is not None else "No one is signed in.")
    return c


def _kti_units(c, bg):
    """{company: display name} of a business group's units: its org units, the companies of its people and of its saved BU KPIs."""
    if bg not in c["units"]:
        db = c["db"]
        cos = {x[0] for x in db.execute("SELECT company FROM org_units WHERE business_group=?", (bg,))}
        cos |= {x[0] for x in db.execute("SELECT DISTINCT company FROM users WHERE business_group=? AND left_at IS NULL AND role!='admin'", (bg,))}
        cos |= {co for (b, co) in c["by_unit"] if b == bg}
        c["units"][bg] = {co: display_company(bg, co) or co for co in cos if (co or "").strip()}
    return c["units"][bg]


def _kti_info(item, kind_why, how, unit, text, gkey):
    item.update(kind="info", status="info", why=kind_why, gkey=gkey, target_unit=unit, how=how, setup_id=None, setup_name=item["kpi_name"],
                unit_target="", same=False, unit_weight=None, weight_rule="", why_text=text)
    return item


def _kti_row_options(c, r):
    """The options one file row has (see `_kti_bu_matches`): ("item", the item), ("library_only", the info row) or None (nothing to ask)."""
    db, me, period = c["db"], c["me"], c["period"]
    person = c["people"][r["subject_id"]]
    bg, own_co = r["business_group"], r["company"]
    by_root, by_unit = c["by_root"], c["by_unit"]
    cand = by_unit.get((bg, own_co), {})
    base_key = _kpi_key(r["base_name"])
    al = c["aliases"].get((bg, base_key))
    item = {"key": "%s|%s" % (r["eid"], r["kpi_name"]), "row": r["row"], "eid": r["eid"], "name": r["subject_name"], "job": r["job"],
            "subject_id": r["subject_id"], "kpi_name": r["kpi_name"], "unit": display_company(bg, own_co), "unit_co": own_co,
            "file_target": _kti_scale_text(r, r["unit"]), "weight": r["weightage"], "snippet": "", "options": [], "rec": None,
            "alias_of": None, "existing_id": r["existing_id"]}
    # the roots this row's KPI has: its own name's and its library alias's, kept where a saved BU KPI has them or the library marks the KPI BU-level
    roots = [rk for rk in dict.fromkeys([_kpi_key(_bu_root(r["base_name"]))] + ([_kpi_key(_bu_root(al["into_name"]))] if al else []))
             if by_root.get((bg, rk)) or any(x["bu_level"] for x in c["libs"].get((bg, rk), []))]
    # ---- (1) another unit of the group named: its saved BU KPI, or a new one ---------------------------------------------------
    named, own_named, rk_used, field_of = [], False, None, {}
    if me is not None:
        for rk in roots:
            for co, disp in sorted(_kti_units(c, bg).items(), key=lambda kv: kv[1].lower()):
                f = _kti_named_in(r, _kti_unit_terms(bg, co, [x for x in by_root.get((bg, rk), []) if x["company"] == co]))
                if not f:
                    continue
                if co == own_co:
                    own_named = True
                else:
                    named.append(co)
                    field_of[co] = f
            if named:
                rk_used = rk
                break
            own_named = False
    options = []   # (kind, setup row or library row, unit company, bu_level_here)
    how = ""
    if named:
        targets = list(named)
        if own_named and any(x["company"] == own_co for x in by_root.get((bg, rk_used), [])):
            targets.append(own_co)
        targets.sort(key=lambda co: (_kti_units(c, bg).get(co) or co).lower())
        variants = []
        if len(targets) >= 2:   # the variant saved for all of them ("PAT: Starken 1 & Starken 2"), when there is exactly one
            variants = [x for x in by_root.get((bg, rk_used), []) if x["company"] in targets and _kti_qualifier(x["kpi_name"]) and all(
                any(_kti_names(_kti_qualifier(x["kpi_name"]), t) for t in (display_company(bg, co), co)) for co in targets)]
        if len(variants) == 1:
            options = [("saved", variants[0], variants[0]["company"], False)]
        else:
            for co in targets:
                ss = _kti_pick_setup([x for x in sorted(by_root.get((bg, rk_used), []), key=lambda x: _kpi_key(x["kpi_name"]))
                                      if x["company"] == co], r)
                if ss:
                    options += [("saved", x, co, False) for x in ss]
                else:
                    lr, bu_here = _kti_lib_row(c["libs"], bg, rk_used, co)
                    if lr is not None:
                        options.append(("new", lr, co, bu_here))
        first_unit = _kti_units(c, bg).get(named[0]) or named[0]
        label = field_of[named[0]]
        how = ("%s names %s" % (label, first_unit)) if len(targets) == 1 else "%s names %d units" % (label, len(targets))
        if not options:   # it names a unit it cannot be offered for: no BU KPI of that root there and the KPI is not in the library
            return "item", _kti_info(item, "xnone", how, first_unit,
                                     "Names %s, which has no BU KPI of that name, and the KPI isn't in the KPI library: it goes in as their own line."
                                     % first_unit, "info|%s" % rk_used)
    else:
        # ---- (2) a unit of ANOTHER business group named: an info row ------------------------------------------------------------
        if me is not None and (roots or base_key in c["roots"] or _kpi_key(_bu_root(r["base_name"])) in c["roots"]):
            if c["other_units"] is None:
                c["other_units"] = sorted({(x[0], x[1]) for x in db.execute("SELECT business_group, company FROM org_units")
                                           if (x[1] or "").strip()}, key=lambda x: (display_company(x[0], x[1]) or "").lower())
            for b2, co2 in c["other_units"]:
                d2 = display_company(b2, co2) or co2
                f = b2 != bg and _kti_named_in(r, [d2, co2])
                if f:
                    return "item", _kti_info(item, "xgroup", "%s names %s" % (f, d2), d2,
                                             "Names %s, another business group: it goes in as their own line." % d2,
                                             "info|%s" % (roots[0] if roots else base_key))
        # ---- (3) naming none: the person's OWN unit's BU KPI by name, library alias or Focus (today's rule), then the library ---------
        s, how0, alias_of = cand.get(base_key), None, None
        if s is not None:
            how0 = "focus" if r["focus"] else "name"
        elif al is not None and _kpi_key(al["into_name"]) in cand:
            s, how0, alias_of = cand[_kpi_key(al["into_name"])], "alias", al["into_name"]
        if s is not None:
            options = [("saved", s, own_co, False)]
            how = {"focus": "Same KPI with a Focus", "name": "Same name",
                   "alias": "Library alias of %s" % (alias_of or s["kpi_name"])}[how0]
            item["alias_of"] = alias_of
        else:
            if r["subject_id"] not in c["bu_names"]:
                c["bu_names"][r["subject_id"]] = pm_bu_level_names(db, person)
            if base_key not in c["bu_names"][r["subject_id"]]:
                return None
            lr, bu_here = _kti_lib_row(c["libs"], bg, base_key, own_co)
            rk0 = _kpi_key(_bu_root(r["base_name"]))
            if me is not None and lr is not None and not any(x["company"] == own_co for x in by_root.get((bg, rk0), [])):
                options, how = [("new", lr, own_co, bu_here)], "BU-level in the library"
            else:   # the unit has no target for it and a variant of it exists, or nobody can set it up: info, as before
                return "library_only", {"row": r["row"], "eid": r["eid"], "name": r["subject_name"], "kpi_name": r["kpi_name"],
                                        "unit": display_company(bg, own_co), "file_target": _kti_scale_text(r, r["unit"])}
    # ---- the options, each one's state the writer's own -------------------------------------------------------------------------
    item["how"] = how
    held = {b for n, (_w, b) in c["after"].get(r["subject_id"], {}).items() if n != r["kpi_name"]}
    total = float(sum(w for n, (w, _b) in c["after"].get(r["subject_id"], {}).items() if n != r["kpi_name"]))
    for kind, x, co, bu_here in options:
        unit = display_company(bg, co) or co
        if kind == "saved":
            own_unit = co == own_co
            if own_unit:
                w = _bu_kpi_weight(x, person, {"weightage": r["weightage"]})
                renamed = _kpi_key(r["kpi_name"]) != _kpi_key(x["kpi_name"])
                why = ("closed" if not c.get("open") else "locked" if r["existing_id"] and _bu_line_locked(db, r["existing_id"])
                       else "rule" if not (_bu_kpi_covers(x, person) or x["carriers"] in ("pick", "holders"))
                       else "band" if w is None
                       else "clash" if renamed and (r["subject_id"], _kpi_key(x["kpi_name"])) in c["holds"] else None)
                text = _KTI_BU_WHY.get(why, "")
            else:
                w = r["weightage"]
                if r["existing_id"] and _bu_line_locked(db, r["existing_id"]):
                    why, text = "locked", _KTI_BU_WHY["locked"]
                else:
                    gw = _bu_guest_refusal(db, me, period, x, person, r["weightage"], held, total)
                    why = ("xclash" if "already carry" in gw else "xrefused") if gw else None
                    text = (gw + " It goes in as their own line.") if gw else ""
            opt = {"kind": "saved", "setup_id": x["id"], "co": co, "unit": unit, "setup_name": x["kpi_name"], "own_unit": own_unit,
                   "disabled": bool(why), "why": why, "why_text": text, "weight": w}
        else:
            opt = {"kind": "new", "setup_id": None, "co": co, "unit": unit, "setup_name": x["kpi_name"], "lib_id": x["id"], "bu_here": bu_here,
                   "own_unit": co == own_co, "disabled": bool(c["new_why"]), "why": "xcycle" if c["new_why"] else None,
                   "why_text": (c["new_why"] + " It goes in as their own line.") if c["new_why"] else "", "weight": r["weightage"],
                   "gkey": "new|%s|%s|%s" % (bg, co, _kpi_key(x["kpi_name"]))}
        item["options"].append(opt)
    one = len(item["options"]) == 1
    for opt in item["options"]:   # one option is "bu" / "new"; with several each says which: "bu:<setup id>" / "new:<unit>"
        opt["value"] = ("bu" if opt["kind"] == "saved" else "new") if one else (
            "bu:%d" % opt["setup_id"] if opt["kind"] == "saved" else "new:%s" % opt["co"])
    free = [o for o in item["options"] if not o["disabled"]]
    first = item["options"][0]
    item.update(kind="new" if first["kind"] == "new" else ("own" if first["own_unit"] else "other"),
                setup_id=first["setup_id"], setup_name=first["setup_name"], target_unit=first["unit"],
                gkey=first["gkey"] if first["kind"] == "new" else "s|%d" % first["setup_id"])
    if first["kind"] == "saved":
        s0 = next(x for k, x, co, _b in options if k == "saved")
        item.update(unit_target=_kti_scale_text(s0, s0["unit"]), same=_kti_same_scale(r, s0) and (r["unit"] or "") == (s0["unit"] or ""),
                    weight_rule=("theirs, from the file" if not first["own_unit"] else
                                 "each person's own" if s0["weight_mode"] == "own" else "by grade band" if s0["weight_mode"] == "grade"
                                 else "%g%% for all" % (s0["weight"] or 0)), unit_weight=first["weight"])
    else:
        item.update(unit_target="", same=False, weight_rule="each person's own, from the file", unit_weight=None)
    item["rec"] = free[0]["value"] if one and free else None   # pre-picked only where exactly one option was named
    item["status"] = "decide" if free else "info"
    item["why"], item["why_text"] = (None, "") if free else (first["why"], first["why_text"])
    if "Description" in how or "Focus" in how:   # the words that named the unit, quoted under the line
        item["snippet"] = " ".join(str((r.get("description") if "Description" in how else r.get("focus")) or "").split())
    return "item", item


def _kti_bu_matches(db, period, chk, cls, me=None):
    """The rows that match a BU KPI (Chris, 2026-10-26: "flag to admin to determine if super admin would like to classify it as BU KPI or
    not"; 2026-11-07: "if a person A from BU 1 kpi line 1 is to follow PAT from BU 2 (a BU KPI), the import should recommend to tag to
    BU 2 BU KPI"). Plain text matching, no model, deterministic. {items, library_only, new_groups, open, note}. In this order, a row:
      * names ANOTHER unit of the person's business group: a saved BU KPI of that unit when (a) its KPI name or library alias has the
        setup's ROOT (`_bu_root`: "PAT" matches "PAT" and "PAT: Starken 2") and (b) its name, Focus or description names the unit (its display
        name, its HRIS name or the setup's own variant qualifier) as whole words, any case. That wins over the person's own unit's BU KPI of
        the same name. One unit named: that setup is pre-picked. Two or more (the person's own counts when it names it and has one): the
        variant saved for all of them if exactly one, else every option and none picked. A named unit with no setup of the root is offered
        "a new BU KPI" when the root is in the KPI library; named but neither: an info row.
      * names a unit of ANOTHER business group: an info row, it goes in as their own.
      * names none: the person's OWN unit's BU KPI by name, library alias or the same KPI with a Focus (today's rule); the library marks the
        KPI BU-level for their unit and the unit has no saved BU KPI of its root: "a new BU KPI" for their unit (library_only keeps the rows
        that cannot be offered).
    Each item has options (value, label parts, kind saved|new, disabled, why), rec (the pre-picked value or None) and status 'decide' (an option
    is open) or 'info' (none: why_text says so). Every state rule is the writers' own (`_bu_guest_refusal`, `_bu_add_cycle_refusal`). `me` None
    keeps today's own-unit rule only (no cross-unit, no new)."""
    is_open, note = _bu_kpi_state(db, period)
    rows = [r for r in chk["valid"] if not r["skip"]]
    out = {"items": [], "library_only": [], "new_groups": {}, "open": is_open, "note": note}
    if not rows:
        return out
    c = _kti_ctx(db, period, chk, cls, rows, me)
    c["open"] = is_open
    for r in rows:
        got = _kti_row_options(c, r)
        if got is None:
            continue
        (out["items"] if got[0] == "item" else out["library_only"]).append(got[1])
    # a new BU KPI's lines form one group per unit and KPI: its target is picked from the file's own targets, the one most lines hold first
    sigs = {}
    by_key = {(r["eid"], r["kpi_name"]): r for r in rows}
    for it in out["items"]:
        for o in it["options"]:
            if o["kind"] == "new":
                g = out["new_groups"].setdefault(o["gkey"], {
                    "gkey": o["gkey"], "bg": by_key[(it["eid"], it["kpi_name"])]["business_group"], "co": o["co"], "unit": o["unit"],
                    "kpi": o["setup_name"], "lib_id": o["lib_id"], "bu_here": o["bu_here"], "why": o["why"], "why_text": o["why_text"]})
                r = by_key[(it["eid"], it["kpi_name"])]
                sg = sigs.setdefault(o["gkey"], {}).setdefault(_kti_sig_id(_kti_target_sig(r)), {"n": 0, "row": r})
                sg["n"] += 1
    for gk, g in out["new_groups"].items():
        ts = sorted(sigs[gk].items(), key=lambda kv: (-kv[1]["n"], kv[0]))
        g["targets"] = [{"id": i, "n": t["n"], "row": t["row"], "scale": _kti_scale_text(t["row"], t["row"]["unit"]),
                         "text": "%s · %d line%s" % (_kti_scale_text(t["row"], t["row"]["unit"]), t["n"], "" if t["n"] == 1 else "s")}
                        for i, t in ts]
        g["default"] = ts[0][0] if ts and (len(ts) == 1 or ts[0][1]["n"] > ts[1][1]["n"]) else None   # a tie pre-picks nothing
    out["items"].sort(key=lambda x: ({"own": 0, "other": 1, "new": 2, "info": 3}[x["kind"]], x["target_unit"] or x["unit"] or "",
                                     _kpi_key(x["setup_name"]), x["eid"]))
    return out


def _kti_quality(db, period, chk, cls):
    """The quality of a checked file: {fix: [{kind, n, rows}], look: [{key, what, why, n, found: [{row, eid, detail,
    rows}]}], rows, clean, n_fix, n_look, fingerprint}. Reads only; the same file on the same OneHR gives the same
    findings, so the fingerprint tells the later steps whether what the admin looked at still holds."""
    fix = {}
    for e in chk["errors"]:
        fix.setdefault(e["kind"], []).append(e["row"])
    fix_l = sorted(({"kind": k, "n": len(v), "rows": sorted(set(v))} for k, v in fix.items()),
                   key=lambda x: (-x["n"], x["kind"]))
    look = {k: [] for k, _one, _many, _y in _KTI_LOOK}
    by_person = {}
    for r in chk["valid"]:
        by_person.setdefault(r["subject_id"], []).append(r)
    for sid, rs in by_person.items():
        weights = {n: (t["weightage"] or 0) for n, t in cls["current"].get(sid, {}).items()}
        for r in rs:
            if not r["skip"]:
                weights[r["kpi_name"]] = r["weightage"]
        total = sum(weights.values())
        if abs(total - 100) > 0.005:
            look["weights"].append({"row": rs[0]["row"], "eid": rs[0]["eid"], "rows": [r["row"] for r in rs],
                                    "detail": "%s totals %g%% after the import" % (rs[0]["eid"], round(total, 2))})
    for x in chk.get("linked", ()):
        look["linked"].append({"row": x["row"], "eid": x["eid"], "rows": [x["row"]],
                               "detail": "Row %d: %s is %s (main ID %s)" % (x["row"], x["eid"], x["name"], x["main"])})
    np_ = {}
    for x in chk["not_part"]:
        np_.setdefault(x["eid"], []).append(x["row"])
    for eid, rws in np_.items():
        look["not_part"].append({"row": rws[0], "eid": eid, "rows": rws,
                                 "detail": "%s: %d row%s skipped" % (eid, len(rws), "" if len(rws) == 1 else "s")})
    lib = {(r[0], _kpi_key(r[1])) for r in db.execute("SELECT business_group, kpi_name FROM pm_kpi_library "
                                                      "WHERE active=1")}
    lib |= {(r[0], r[1]) for r in db.execute("SELECT business_group, alias_key FROM pm_kpi_aliases")}
    seen_lib = {}
    for r in chk["valid"]:
        if r["unit_typed"] and r["unit_typed"] != (r["unit"] or ""):
            look["units"].append({"row": r["row"], "eid": r["eid"], "rows": [r["row"]],
                                  "detail": '"%s" is stored as %s' % (r["unit_typed"], r["unit"] or "(no unit)")})
        k = (r["business_group"], _kpi_key(r["base_name"]))
        if k not in lib:
            if k in seen_lib:
                seen_lib[k]["rows"].append(r["row"])
            else:
                seen_lib[k] = {"row": r["row"], "eid": r["eid"], "rows": [r["row"]], "detail": '"%s"' % r["base_name"]}
                look["library"].append(seen_lib[k])
    look_l = [{"key": k, "what": one if len(look[k]) == 1 else many, "why": y, "n": len(look[k]), "found": look[k]}
              for k, one, many, y in _KTI_LOOK if look[k]]
    flagged = {rw for g in look_l if g["key"] not in ("not_part", "linked") for f in g["found"] for rw in f["rows"]}
    fp = _imp_fp([fix_l, [(g["key"], [(f["eid"], f["detail"]) for f in g["found"]]) for g in look_l]])
    return {"fix": fix_l, "look": look_l, "rows": chk["rows"], "n_fix": len({e["row"] for e in chk["errors"]}),
            "n_look": sum(g["n"] for g in look_l), "clean": sum(1 for r in chk["valid"] if r["row"] not in flagged),
            "fingerprint": fp}


def _kti_load(db, me, period, token):
    """Re-check a kept KPI targets file against today's OneHR: (record, check, classification, quality, BU matches), or
    None (expired, someone else's, or the active cycle changed since it was checked)."""
    st = _imp_staged(KTI_KIND, me, token)
    if not st or not period:
        return None
    meta, data = st
    if meta.get("cycle_id") != period["id"]:
        return None
    try:
        records = _read_records(meta["filename"], data)
    except Exception:  # noqa: BLE001 - it was read once at step 1
        return None
    chk = _kti_check(db, me, period, records)
    cls = _kti_classify(db, period, chk)
    q = _kti_quality(db, period, chk, cls)
    m = _kti_bu_matches(db, period, chk, cls, me)
    return meta, chk, cls, q, m


def _kti_changes_fp(chk, m):
    """What the changes step showed: every line's fate, every BU KPI match with each option's state, and each new BU KPI's targets.
    Apply refuses if it moved since."""
    return _imp_fp([[(r["eid"], r["kpi_name"], r["existing_id"], r["skip"], r["changes"]) for r in chk["valid"]],
                    [(i["key"], i["setup_id"], i["status"], i["why"],
                      [(o["value"], o["setup_id"], o["co"], o["disabled"]) for o in i.get("options", [])]) for i in m["items"]],
                    [(g["gkey"], g["why"], [(t["id"], t["n"]) for t in g["targets"]]) for g in (m.get("new_groups") or {}).values()]])


def _kti_choice(it, v):
    """The option a stored decision names for an item: {"kind": "own"} for "own", else the OPEN option whose value it is, or None
    (nothing decided, or a value the item no longer offers or whose option has closed since: it is asked again)."""
    if v == "own":
        return {"kind": "own", "value": "own"}
    return next((o for o in it.get("options", []) if o["value"] == v and not o["disabled"]), None)


def _kti_choice_label(it, ch):
    """A decision in words, for the final preview and the audit trail."""
    if ch is None:
        return ""
    if ch["kind"] == "own":
        return "Their own"
    if ch["kind"] == "new":
        return "A new BU KPI for %s" % ch["unit"]
    return "The unit's BU KPI" if ch["own_unit"] else "%s's BU KPI" % ch["unit"]


def _kti_new_plan(m, decisions):
    """The new BU KPIs the decisions set up: one per (unit, KPI) with at least one line decided "a new BU KPI", in unit then name order.
    Each: gkey, bg, co, unit, kpi (the library KPI's own name), lib_id, bu_here (the library already marks it BU-level for the unit),
    target (the picked file row: the group's posted pick, else the one most lines hold; None on a tie until picked), holders (the unit's own
    people's items), guests (the others'). The one read of it: the undecided check, the final preview and Apply."""
    dec = decisions or {}
    plan = {}
    for it in m["items"]:
        ch = _kti_choice(it, dec.get(it["key"]))
        if ch is None or ch["kind"] != "new":
            continue
        g = (m.get("new_groups") or {}).get(ch["gkey"])
        if g is None:
            continue
        pg = plan.setdefault(ch["gkey"], dict(g, holders=[], guests=[]))
        pg["holders" if it["unit_co"] == g["co"] else "guests"].append(it)
    for pg in plan.values():
        pick = dec.get("target|" + pg["gkey"])
        by_id = {t["id"]: t for t in pg["targets"]}
        t = by_id.get(pick) or by_id.get(pg["default"])
        pg["target"], pg["target_id"] = (t["row"], t["id"]) if t else (None, None)
        pg["target_text"] = t["scale"] if t else ""
    return sorted(plan.values(), key=lambda g: ((g["unit"] or "").lower(), (g["kpi"] or "").lower()))


def _kti_undecided(m, decisions):
    """What still blocks Next: the lines nobody has decided (or whose decision is not an open option any more), and a new BU KPI whose
    target is not picked yet (an item-like {"key": "target|...", "kind": "target"}: a tie waits for the pick)."""
    dec = decisions or {}
    left = [i for i in m["items"] if i["status"] == "decide" and _kti_choice(i, dec.get(i["key"])) is None]
    return left + [{"key": "target|" + g["gkey"], "kind": "target"} for g in _kti_new_plan(m, dec) if g["target"] is None]


def _kti_routing(chk):
    """Who moderates the lines it writes: the people with a split named, everyone else as one count."""
    people = {}
    for r in chk["valid"]:
        if r["skip"]:
            continue
        p = people.setdefault(r["subject_id"], {"eid": r["eid"], "name": r["subject_name"], "n": 0, "lm": 0,
                                                "matrix": 0, "none": 0, "chair": 0, "mm": []})
        p["n"] += 1
        p[r["route"]] += 1
        if r["route"] == "matrix" and r["moderator_name"] not in p["mm"]:
            p["mm"].append(r["moderator_name"])
    split = sorted((p for p in people.values() if p["matrix"]), key=lambda p: p["eid"])
    plain = [p for p in people.values() if not p["matrix"]]
    return {"split": split[:30], "split_n": len(split), "lm_lines": sum(p["lm"] for p in people.values()),
            "matrix_lines": sum(p["matrix"] for p in people.values()),
            "none_lines": sum(p["none"] for p in people.values()), "plain_n": len(plain),
            "chair_lines": sum(p["chair"] for p in people.values())}


def _kti_after(chk, cls, m, decisions):
    """Each person after the import, with the decisions in: [{eid, name, lines, weight, says}], by Employee ID."""
    dec = decisions or {}
    by_item = {i["key"]: i for i in m["items"]}
    out = {}
    for r in chk["valid"]:
        sid = r["subject_id"]
        p = out.get(sid)
        if p is None:
            cur = cls["current"].get(sid, {})
            p = out[sid] = {"eid": r["eid"], "name": r["subject_name"], "names": set(cur),
                            "weights": {n: (t["weightage"] or 0) for n, t in cur.items()}, "added": 0, "updated": 0,
                            "notes": []}
        if r["skip"] == "approved":
            p["notes"].append("%s left as it is (moderated)" % r["kpi_name"])
            continue
        if r["skip"] == "bu":
            p["notes"].append("%s left as it is (the unit's BU KPI)" % r["kpi_name"])
            continue
        p["names"].add(r["kpi_name"])
        p["weights"][r["kpi_name"]] = r["weightage"]
        p["added" if not r["existing_id"] else "updated"] += 1
        if r["route"] == "matrix":
            p["notes"].append("%s goes to %s" % (r["kpi_name"], r["moderator_name"]))
        it = by_item.get("%s|%s" % (r["eid"], r["kpi_name"]))
        if it and it["status"] == "decide":
            ch = _kti_choice(it, dec.get(it["key"]))
            if ch is not None and ch["kind"] == "saved" and ch["own_unit"]:
                p["notes"].append("%s joins %s's BU KPI" % (r["kpi_name"], it["unit"]))
                if ch["weight"] is not None:
                    p["weights"][r["kpi_name"]] = ch["weight"]
            elif ch is not None and ch["kind"] == "saved":   # another unit's: a guest at the weight the file gave
                p["notes"].append("%s joins %s's BU KPI as a guest" % (r["kpi_name"], ch["unit"]))
            elif ch is not None and ch["kind"] == "new":
                p["notes"].append("%s joins a new BU KPI for %s" % (r["kpi_name"], ch["unit"]))
            elif ch is not None and ch["kind"] == "own":
                p["notes"].append("%s stays their own line" % r["kpi_name"])
    res = []
    for p in out.values():
        bits = []
        if p["added"]:
            bits.append("%d added" % p["added"])
        if p["updated"]:
            bits.append("%d updated" % p["updated"])
        total = round(sum(p["weights"].values()), 2)
        res.append({"eid": p["eid"], "name": p["name"], "lines": len(p["names"]), "weight": total,
                    "weight_off": abs(total - 100) > 0.005, "says": " · ".join([", ".join(bits)] + p["notes"]
                                                                              if bits else p["notes"])})
    return sorted(res, key=lambda x: x["eid"])


def _kti_view(db, me, period, token, step):
    """The page's data for a kept file at one step: quality, changes or apply (a later step only once the earlier one
    has been seen on these same findings; otherwise the earlier step shows)."""
    got = _kti_load(db, me, period, token)
    if not got:
        return None
    meta, chk, cls, q, m = got
    decisions = meta.get("decisions") or {}
    seen_q = not chk["errors"] and meta.get("quality") == q["fingerprint"]
    fp = _kti_changes_fp(chk, m)
    seen_c = seen_q and meta.get("changes") == fp and not _kti_undecided(m, decisions)
    if step == "apply" and not seen_c:
        step = "changes"
    if step == "changes" and not seen_q:
        step = "quality"
    if step not in ("quality", "changes", "apply"):
        step = "quality"
    valid = chk["valid"]
    appl = [r for r in valid if not r["skip"]]
    by_field = {}
    changes = []
    for r in appl:
        for field, a, b in r["changes"]:
            by_field[field] = by_field.get(field, 0) + 1
            changes.append({"eid": r["eid"], "name": r["subject_name"], "kpi": r["kpi_name"], "field": field,
                            "from": a, "to": b})
    # the step-3 table's groups (board D1): one per BU KPI the lines follow (the unit's own, another unit's, a new one), then the info rows.
    # Decide is a select on every line: the stored choice, else the one recommended, else "Pick one..."
    groups, by_g = [], {}
    row_of = {(r["eid"], r["kpi_name"]): r for r in valid}
    plan = _kti_new_plan(m, decisions)
    plan_by = {g["gkey"]: g for g in plan}
    for it in m["items"]:
        ch = _kti_choice(it, decisions.get(it["key"]))
        it = dict(it, choice=(ch["value"] if ch else None), ch=ch, ch_label=_kti_choice_label(it, ch),
                  sel=(ch["value"] if ch else (it["rec"] or "")), fid="d_" + hashlib.sha1(it["key"].encode()).hexdigest()[:10])
        g = by_g.get(it["gkey"])
        if g is None:
            g = by_g[it["gkey"]] = {"gkey": it["gkey"], "kind": it["kind"], "unit": it["target_unit"], "kpi": it["setup_name"],
                                    "target": it["unit_target"], "weight_rule": it["weight_rule"], "lines": [],
                                    "gid": "g%d" % (len(groups) + 1), "new": None}
            groups.append(g)
        g["lines"].append(it)
    for gk, ng in (m.get("new_groups") or {}).items():   # a new BU KPI's head carries the target pick, even when only a line naming two units offers it
        g = by_g.get(gk)
        if g is None:
            g = by_g[gk] = {"gkey": gk, "kind": "new", "unit": ng["unit"], "kpi": ng["kpi"], "target": "", "weight_rule": "", "lines": [],
                            "gid": "g%d" % (len(groups) + 1), "new": None}
            groups.append(g)
        picked = (decisions.get("target|" + gk) if (decisions.get("target|" + gk) in {t["id"] for t in ng["targets"]}) else None) or ng["default"]
        g["new"] = dict(ng, picked=picked, tid="t_" + hashlib.sha1(gk.encode()).hexdigest()[:10], used=gk in plan_by, why=ng["why"])
        for it in g["lines"]:
            it["same_target"] = picked is not None and _kti_sig_id(_kti_target_sig(row_of[(it["eid"], it["kpi_name"])])) == picked
    groups.sort(key=lambda g: ({"own": 0, "other": 1, "new": 2, "info": 3}[g["kind"]], (g["unit"] or "").lower(), (g["kpi"] or "").lower()))
    for i, g in enumerate(groups, 1):
        g["gid"] = "g%d" % i
    n_decide = sum(1 for i in m["items"] if i["status"] == "decide")
    n_open = [i for i in _kti_undecided(m, decisions) if i.get("kind") != "target"]
    n_done = n_decide - len(n_open)
    chs = [c_ for c_ in (_kti_choice(i, decisions.get(i["key"])) for i in m["items"] if i["status"] == "decide") if c_ is not None]
    to_bu = sum(1 for c_ in chs if c_["kind"] == "saved" and c_["own_unit"])
    to_x = sum(1 for c_ in chs if c_["kind"] == "saved" and not c_["own_unit"])
    to_new = sum(1 for c_ in chs if c_["kind"] == "new")
    n_own = sum(1 for c_ in chs if c_["kind"] == "own")
    after = _kti_after(chk, cls, m, decisions) if step == "apply" else []
    return {"token": token, "filename": meta["filename"], "step": step, "quality": q, "seen_q": seen_q,
            "counts": {"add": sum(1 for r in appl if not r["existing_id"]),
                       "update": sum(1 for r in appl if r["existing_id"] and r["changes"]),
                       "same": sum(1 for r in appl if r["existing_id"] and not r["changes"]),
                       "left": sum(1 for r in valid if r["skip"]), "skipped": len(chk["not_part"]),
                       "people": len({r["subject_id"] for r in appl})},
            "left": [r for r in valid if r["skip"]][:30], "n_left": sum(1 for r in valid if r["skip"]),
            "by_field": sorted(by_field.items(), key=lambda x: -x[1]), "changes": changes[:12],
            "n_changes": len(changes), "routing": _kti_routing(chk), "bu": m, "groups": groups,
            "n_decide": n_decide, "n_done": n_done, "to_bu": to_bu, "to_x": to_x, "to_new": to_new, "plan": plan,
            "n_own": n_own, "after": after[:30], "n_after": len(after),
            "weights_off": sum(1 for p in after if p["weight_off"]), "blank_rows": chk["blank_rows"]}


def _kti_apply(db, me, period, chk, m, decisions):
    """Write a checked file's lines, then the super admin's decisions (each line's choice among its options, `_kti_choice`): the unit's own BU
    KPI: the person added to those who carry it where it's a list, the line linked, given the unit's target, what the file gave it kept to go
    back to (`_kti_bu_join`); ANOTHER unit's BU KPI: the person joins it as a guest at the weight the file gave, through the one guest writer
    (`_bu_kpi_add_guest`, the imported line adopted); a NEW BU KPI: the setup is made once per unit and KPI through the setup writer
    (`_bu_kpi_save_one`: carriers "holders", weight "own", the target picked), the unit's people its holders, the others guests; their own: marked so
    BU KPI setup never adopts it. A join a writer refuses at this moment (the state moved) leaves the line as the person's own and is said
    (res["fell"]). The caller commits.
    Everyone whose lines this changed (a line written, a BU KPI joined or made) has their rating record rebuilt ONCE at the end, in this
    same transaction, under "kpi_import" (`_bu_follow_flush`: only a person with a record or something entered on a line; the rest
    only ask the AI pre-run), so the figures they and their approvers read never wait for the next sign-off or Capture (2026-11-08).
    No more than one Capture click's worth (`_RR_CAPTURE_BATCH`) is rebuilt in the request: res["records_left"] counts the rest, whose
    records wait for Capture."""
    created = updated = joined = kept = guests = made = 0
    fell = []
    tid_of = {}
    touched = {}
    for r in chk["valid"]:
        if r["skip"]:
            continue
        if r["existing_id"]:
            tid = r["existing_id"]
            db.execute(
                "UPDATE pm_kpi_targets SET category=?, description=?, weightage=?, unit=?, "
                "method=?, rate1=?, rate2=?, rate3=?, rate4=?, rate5=?, "
                "threshold=?, target=?, multiple=?, excellence=?, "
                "business_group=?, company=?, department=?, focus=?, "
                "updated_at=datetime('now'), updated_by=? WHERE id=?",
                (r["category"], r["description"], r["weightage"], r["unit"], r["method"],
                 r["rate1"], r["rate2"], r["rate3"], r["rate4"], r["rate5"],
                 r["threshold"], r["target"], r["multiple"], r["excellence"],
                 r["business_group"], r["company"], r["department"], r["focus"], me["id"], tid))
            updated += 1
        else:
            tid = db.execute(
                "INSERT INTO pm_kpi_targets(cycle_id, subject_id, kpi_name, category, "
                "description, weightage, unit, method, rate1, rate2, rate3, rate4, rate5, "
                "threshold, target, multiple, excellence, business_group, company, "
                "department, created_by, focus) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (period["id"], r["subject_id"], r["kpi_name"], r["category"], r["description"],
                 r["weightage"], r["unit"], r["method"], r["rate1"], r["rate2"], r["rate3"],
                 r["rate4"], r["rate5"], r["threshold"], r["target"], r["multiple"],
                 r["excellence"], r["business_group"], r["company"], r["department"], me["id"], r["focus"])).lastrowid
            created += 1
            _redo_collect(db, period, {"id": r["subject_id"]}, {"kind": "kpi", "tid": tid, "name": r["kpi_name"]})
        _pm_set_moderator(db, tid, r["approver_ids"])   # re-resolve the moderator on every import
        tid_of[(r["subject_id"], r["kpi_name"])] = tid
        _bu_touch(touched, r["subject_id"])
    plan = {g["gkey"]: g for g in _kti_new_plan(m, decisions)}
    new_id = {}   # gkey -> the new setup's id, or None when it could not be made (its lines stay their own)
    for it in m["items"]:
        if it["status"] != "decide":
            continue
        tid = tid_of.get((it["subject_id"], it["kpi_name"]))
        ch = _kti_choice(it, (decisions or {}).get(it["key"]))
        if not tid or ch is None:
            continue
        if ch["kind"] == "own":
            db.execute("UPDATE pm_kpi_targets SET bu_keep_own=1 WHERE id=?", (tid,))
            kept += 1
            continue
        if ch["kind"] == "saved":
            sid = ch["setup_id"]
        else:
            gk = ch["gkey"]
            if gk not in new_id:
                new_id[gk] = _kti_make_setup(db, me, period, plan[gk], touched)
                made += 1 if new_id[gk] else 0
            sid = new_id[gk]
            if not sid:
                fell.append((it["eid"], it["kpi_name"], "the new BU KPI for %s could not be set up" % ch["unit"]))
                continue
        if it["unit_co"] == ch["co"]:   # the unit's own person: the setup lists who carries it (`_kti_bu_join`)
            if _kti_bu_join(db, me, period, it, tid, sid, touched=touched):
                joined += 1
        else:                           # someone of another unit: a guest, through the one writer
            why = _kti_bu_guest(db, me, period, it, tid, sid, touched=touched)
            if why is None:
                guests += 1
            else:
                fell.append((it["eid"], it["kpi_name"], why))
    _done, _ask, left = _bu_follow_flush(db, me, period["id"], touched, "kpi_import")
    return {"created": created, "updated": updated, "joined": joined, "kept": kept, "guests": guests, "made": made, "fell": fell,
            "records_left": left}


def _kti_make_setup(db, me, act, g, touched=None):
    """Set up a new BU KPI for a unit from the import (the plan `_kti_new_plan` made): through the setup writer `_bu_kpi_save_one`, so the library
    mark ("this unit only", `_bu_kpi_unit_row`) and the trail are the card's own. Its name is the library KPI's own, the carriers "holders"
    (the unit's people in the plan), the weight rule "own" (each line keeps the weight the file gave it), the target the one picked. Nothing is applied here:
    each line joins afterwards (the unit's own through `_kti_bu_join`, the others as guests) so the setup adopts the lines the file wrote and puts no
    second one beside them. The new setup's id, or None when the setup is refused or exists already (then the lines stay the person's own)."""
    lib = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (g["lib_id"],)).fetchone()
    tr = g["target"]
    if not lib or tr is None or _bu_add_cycle_refusal(db, me, act, {"cycle_id": act["id"], "carriers": "holders", "weight_mode": "own"}):
        return None
    lib = dict(lib)
    if db.execute("SELECT 1 FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=? AND kpi_name=?",
                  (act["id"], g["bg"], g["co"], lib["kpi_name"])).fetchone():
        return None
    eids = sorted({ja_eid(db.execute("SELECT employee_id FROM users WHERE id=?", (i["subject_id"],)).fetchone()[0]) for i in g["holders"]})
    st = {c: tr[c] for c in _BU_SCALE_COLS}
    st.update({"carriers": "holders", "carriers_json": json.dumps({"people": eids}), "weight_mode": "own", "weight": None, "bands_json": None,
               "library_id": lib["id"], "category": lib["category"], "unit": kpi_unit_normalise(tr["unit"] or lib["unit"]),
               "method": tr["method"], "kpi_name": lib["kpi_name"], "n": len(g["holders"]) + len(g["guests"]), "pick": not g["bu_here"]})
    try:
        row, _n = _bu_kpi_save_one(db, me, act, g["bg"], g["co"], lib, st, [], touched=touched)
    except GradehRefusal:
        return None
    return row["id"]


def _kti_bu_join(db, me, act, it, tid, setup_id=None, touched=None):
    """One imported line joins its unit's BU KPI (the super admin's decision): where the setup lists who carries it,
    the person is added; the line is linked first, so the setup adopts THIS line even when it came in under an alias
    or with a Focus, and BU KPI setup's own writer (_bu_kpi_apply) gives it the unit's name, target and weight and keeps
    what it held (bu_prev_json; its Focus and description set aside), so taking the person off gives the line back as
    the file had it. `setup_id`: a setup the import has just made (default: the item's)."""
    s = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (setup_id or it["setup_id"],)).fetchone()
    person = db.execute("SELECT * FROM users WHERE id=?", (it["subject_id"],)).fetchone()
    if not s or not person:
        return False
    if not _bu_kpi_covers(s, person):
        if s["carriers"] not in ("pick", "holders"):
            return False
        data = json.loads(s["carriers_json"] or "{}") or {}
        ppl = list(data.get("people") or [])
        e = ja_eid(person["employee_id"])
        if e not in ppl:
            ppl.append(e)
        data["people"] = ppl
        db.execute("UPDATE pm_bu_kpis SET carriers_json=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
                   (json.dumps(data), me["id"], s["id"]))
        s = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (s["id"],)).fetchone()
    db.execute("UPDATE pm_kpi_targets SET bu_kpi_id=?, bu_keep_own=0 WHERE id=?", (s["id"], tid))
    res = _bu_kpi_apply(db, me, act, s, [person], only=person["id"], touched=touched)
    if res.get("held"):   # acted on in the meantime: leave it as the person's own
        db.execute("UPDATE pm_kpi_targets SET bu_kpi_id=NULL WHERE id=? AND bu_prev_json IS NULL", (tid,))
        return False
    # the line was linked above, so the apply saw it as already on the setup: a unit Group People already filled gives it
    # its figure here (2026-11-07); a line with a result of its own is skipped
    _bu_fill_carry(db, me, act, s, [tid])
    return True


def _kti_bu_guest(db, me, act, it, tid, setup_id, touched=None):
    """One imported line joins ANOTHER unit's BU KPI as a guest (the super admin's decision): the one guest writer, the line the import has just
    written adopted (`adopt`) at the weight the file gave it. None when it joined, else the writer's own refusal words (the line stays theirs)."""
    s = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (setup_id,)).fetchone()
    w = db.execute("SELECT weightage FROM pm_kpi_targets WHERE id=?", (tid,)).fetchone()
    if not s or not w:
        return "its BU KPI is not there any more"
    n, why = _bu_kpi_add_guest(db, me, act, s, {"id": it["subject_id"]}, w[0], adopt=tid, touched=touched)
    return why


def _kti_log_and_flash(db, me, period, chk, res, backup, m, decisions):
    skipped = [r for r in chk["valid"] if r["skip"]]
    appl = [r for r in chk["valid"] if not r["skip"]]
    no_approver_n = sum(1 for r in appl if not r["approver_ids"] and r["route"] != "chair")   # (the chair's reports have none by design)
    matrix_n = sum(1 for r in appl if r["route"] == "matrix")
    dec = []   # (Employee ID, KPI, what was decided in words) for every decided line
    for i in m["items"]:
        ch = _kti_choice(i, decisions.get(i["key"])) if i["status"] == "decide" else None
        if ch is not None:
            dec.append((i["eid"], i["kpi_name"], "their own" if ch["kind"] == "own" else "a new BU KPI for %s" % ch["unit"] if ch["kind"] == "new"
                        else "the unit's BU KPI" if ch["own_unit"] else "%s's BU KPI (another unit, as a guest)" % ch["unit"]))
    log_activity(db, me["id"], "pm_kpi_import",
                 f"{period['name']}: {res['created']} created, {res['updated']} updated"
                 + (f", {res['joined']} joined their unit's BU KPI" if res["joined"] else "")
                 + (f", {res['guests']} joined another unit's BU KPI as guests" if res.get("guests") else "")
                 + (f", {res['made']} new BU KPI{'' if res['made'] == 1 else 's'} set up" if res.get("made") else "")
                 + (f", {len(res['fell'])} could not join and stayed their own (" + "; ".join(f"{e} {k}: {w}" for e, k, w in res["fell"][:10]) + ")"
                    if res.get("fell") else "")
                 + (f", {res['kept']} kept their own" if res["kept"] else "")
                 + (f", {len(skipped)} skipped (moderated or the unit's BU KPI: "
                    + "; ".join(f"{r['eid']} {r['kpi_name']}" for r in skipped[:20])
                    + (f" and {len(skipped) - 20} more" if len(skipped) > 20 else "") + ")" if skipped else "")
                 + (f", {matrix_n} to a matrix manager" if matrix_n else "")
                 + (f", {no_approver_n} with no resolvable approver" if no_approver_n else "")
                 + (" · decided by the super admin: " + "; ".join("%s %s -> %s" % (e, k, v) for e, k, v in dec[:40]) if dec else "")
                 + (f" · backup {backup}" if backup else ""))
    flash(f"Import complete: {res['created']} created, {res['updated']} updated"
          + (f", {len(skipped)} skipped." if skipped else ".")
          + (f" {matrix_n} KPI line(s) go to a matrix manager; the rest to each person's line manager."
             if matrix_n else ""), "ok")
    if res.get("made") or res.get("guests"):
        flash(("%d new BU KPI%s set up for %s. " % (res["made"], "" if res["made"] == 1 else "s", ", ".join(
            sorted({g["unit"] for g in _kti_new_plan(m, decisions)}))) if res.get("made") else "")
              + ("%d line%s joined another unit's BU KPI as guests." % (res["guests"], "" if res["guests"] == 1 else "s")
                 if res.get("guests") else ""), "ok")
    if res.get("fell"):
        flash("%d line%s could not join the BU KPI picked, so %s as the person's own: " % (
            len(res["fell"]), "" if len(res["fell"]) == 1 else "s", "it stays" if len(res["fell"]) == 1 else "they stay")
              + "; ".join("%s '%s' (%s)" % (e, k, w) for e, k, w in res["fell"][:10]), "warn")
    if res.get("records_left"):
        flash(_records_left_note(res["records_left"]), "warn")
    if skipped:
        # Named, not just counted: "3 skipped" tells an admin nothing they can act on.
        flash(f"{len(skipped)} KPI line(s) were left unchanged because an approver has already acted on them (or they "
              f"follow their unit's BU KPI setup), so the targets they signed off stay: "
              + ", ".join(f"{r['eid']} '{r['kpi_name']}'" for r in skipped[:15])
              + (f" and {len(skipped) - 15} more." if len(skipped) > 15 else "."), "warn")
    if no_approver_n:
        flash(f"{no_approver_n} KPI line(s) have no resolvable approver — see the "
              f"Exceptions page to assign one manually.", "warn")
    if chk["not_part"]:
        eids = sorted({x["eid"] for x in chk["not_part"]})
        flash(f"{len(eids)} person(s) in the file aren't taking part in {period['name']} (not confirmed, or "
              f"confirmed after it opened), so their lines were skipped: " + ", ".join(eids[:20])
              + (f" and {len(eids) - 20} more" if len(eids) > 20 else "")
              + ". Add them on Participants first if they should take part.", "warn")


def _kti_old_approver_cols(records):
    """A file still carrying a value in the old Approver 1/2/3 columns: refused before any row is read, since it was
    written for a chain of up to three and importing it would quietly drop every step but one."""
    return any(isinstance(k, str) and re.fullmatch(r"approver [123]( employee id)?", k.strip()) and _pick(rec, k)
               for rec in records for k in list(rec))


def _kti_post_step(db, me, period, token):
    """Steps 2 to 4 on a kept file: quality_ok (2 -> 3), decide / to_apply (3, the super admin's decisions; -> 4) and
    apply (4). Each re-checks the file against today's OneHR."""
    action = request.form.get("action") or ""
    here = lambda step=None: redirect(url_for("admin_import_kpi_targets", check=token, **({"step": step} if step
                                                                                          else {})))
    got = _kti_load(db, me, period, token)
    if not got:
        flash("That file's check has expired, isn't yours, or the active cycle changed: choose the file again.",
              "error")
        return redirect(url_for("admin_import_kpi_targets"))
    meta, chk, cls, q, m = got
    if chk["errors"]:
        flash("Fix the rows that can't be imported in your file and choose it again: nothing was applied.", "error")
        return here()
    if action == "quality_ok":
        if q["n_look"] and request.form.get("ack") != "1":
            flash("Tick “I've looked at these” to go on, or fix them in your file and choose it again.",
                  "error")
            return here()
        _imp_meta_set(KTI_KIND, token, quality=q["fingerprint"])
        return here("changes")
    if meta.get("quality") != q["fingerprint"]:
        flash("Check the file's quality first: %s" % ("something in OneHR has changed since you looked."
              if meta.get("quality") else "nothing was applied."), "error")
        return here()
    decisions = dict(meta.get("decisions") or {})
    if action in ("decide", "to_apply"):
        asked = [i for i in m["items"] if i["status"] == "decide"]
        if asked:
            if not is_super(me):
                flash("The super admin decides whether these lines join their unit's BU KPI: ask them to import "
                      "this file.", "error")
                return here("changes")
            for i in asked:
                v = request.form.get("d_" + hashlib.sha1(i["key"].encode()).hexdigest()[:10])
                if v is not None and _kti_choice(i, v) is not None:   # only an option the line offers and that is open; "Pick one..." keeps what was stored
                    decisions[i["key"]] = v
            for gk, g in (m.get("new_groups") or {}).items():   # a new BU KPI's target: one of the file's own targets, never a typed figure
                v = request.form.get("t_" + hashlib.sha1(gk.encode()).hexdigest()[:10])
                if v and v in {t["id"] for t in g["targets"]}:
                    decisions["target|" + gk] = v
            _imp_meta_set(KTI_KIND, token, decisions=decisions, decided_by=me["id"])
        if action == "decide":
            return here("changes")
        left = _kti_undecided(m, decisions)
        if left:
            flash("Decide every line that matches a BU KPI to go on: %d still to decide." % len(left), "error")
            return here("changes")
        _imp_meta_set(KTI_KIND, token, changes=_kti_changes_fp(chk, m))
        return here("apply")
    if action == "apply":
        if meta.get("changes") != _kti_changes_fp(chk, m) or _kti_undecided(m, decisions):
            flash("Something in OneHR changed since you looked at the changes: look at them again. Nothing was "
                  "applied.", "error")
            return here("changes")
        if any(i["status"] == "decide" for i in m["items"]) and not is_super(me):
            flash("The super admin decides whether these lines join their unit's BU KPI.", "error")
            return here("changes")
        backup, why = _import_backup(KTI_KIND)
        if not backup:
            flash("Not applied: %s. Nothing changed; try again in a moment." % why, "error")
            return here("apply")
        res = _kti_apply(db, me, period, chk, m, decisions)
        db.commit()
        _redo_flush(db, me["id"])   # a line added for someone who already started: one email each, in waves (2026-11-06)
        _kti_log_and_flash(db, me, period, chk, res, backup, m, decisions)
        after = _kti_after(chk, cls, m, decisions)
        _imp_meta_set(KTI_KIND, token, result=dict(
            res, at=time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime()), backup=backup,
            left=sum(1 for r in chk["valid"] if r["skip"]), skipped=len(chk["not_part"]),
            weights_off=sum(1 for p in after if p["weight_off"]), records_note=_records_left_note(res.get("records_left")),
            no_approver=sum(1 for r in chk["valid"] if not r["skip"] and not r["approver_ids"] and r["route"] != "chair"),
            chair_lines=sum(1 for r in chk["valid"] if not r["skip"] and r["route"] == "chair"),
            people=[[p["eid"], p["name"], p["lines"], p["weight"], p["says"]] for p in after]))
        _imp_unstage(KTI_KIND, token)
        return redirect(url_for("admin_import_kpi_targets", done=token))
    return here()


@app.route("/admin/performance/import", methods=["GET", "POST"])
@admin_required
def admin_import_kpi_targets():
    """Import KPI targets for the active cycle in four steps (Chris, 2026-10-26): 1 File, 2 Quality, 3 Changes and
    the super admin's decisions, 4 the final preview and Apply. Rows are keyed on (cycle, person, KPI name); each row's
    group, unit and department come from the PERSON's profile, which also decides the columns its scoring needs (a group
    with no scoring set is an error, not a skip). One moderator per KPI line (Chris, 2026-10-10): the "Matrix manager
    ID" column names one for that line, blank means the person's line manager; the old "Approver 1/2/3" columns are
    refused outright. A line a moderator has already acted on is left as it is, and so is one that follows its unit's
    BU KPI setup. A line matching its unit's BU KPI is the super admin's decision: the unit's BU KPI, or their own.
    Choosing a file with preview=1 keeps it (step 1); a post without the steps changes nothing (_imp_steps_only)."""
    db = get_db()
    me = current_user()
    period = active_pm_period(db)
    if request.method == "POST":
        if not period:
            flash("Open a performance period first (Performance periods).", "error")
            return redirect(url_for("admin_import_kpi_targets"))
        token = (request.form.get("token") or "").strip()
        if token:
            return _kti_post_step(db, me, period, token)
        if request.form.get("preview") != "1":
            return _imp_steps_only("admin_import_kpi_targets")
        f = request.files.get("file")
        if not f or not f.filename:
            flash("Choose a CSV or XLSX file to upload.", "error")
            return redirect(url_for("admin_import_kpi_targets"))
        data = f.read()
        try:
            records = _read_records(f.filename, data)
        except Exception as e:  # noqa: BLE001
            app.logger.warning("KPI target parse failed: %s", e)
            flash("Could not read the file. Check it's a valid CSV or XLSX and try again.", "error")
            return redirect(url_for("admin_import_kpi_targets"))
        if _kti_old_approver_cols(records):
            flash("This file still uses the old Approver 1/2/3 columns, so nothing was imported. Each KPI now has "
                  "one moderator: leave the new Matrix manager ID column blank for the person's line manager, or "
                  "put the matrix manager's Employee ID. Download the new template below.", "error")
            return redirect(url_for("admin_import_kpi_targets"))
        token = _imp_stage(KTI_KIND, me, f.filename, data, cycle_id=period["id"])   # step 1: keep it, then check it
        return redirect(url_for("admin_import_kpi_targets", check=token))

    view = done = None
    token = request.args.get("check") or ""
    if token:
        view = _kti_view(db, me, period, token, request.args.get("step") or "quality")
        if view is None:
            flash("That file's check has expired, isn't yours, or the active cycle changed: choose the file again.",
                  "error")
    elif request.args.get("done"):
        meta = _imp_meta(KTI_KIND, request.args.get("done"), me)
        if meta.get("result"):
            done = dict(meta["result"], token=request.args.get("done"), filename=meta.get("filename"))
    return render_template("admin_import_kpi_targets.html", period=period, v=view, done=done, is_super=is_super(me))


@app.route("/admin/performance/import/check/<token>.xlsx")
@admin_required
def admin_import_kpi_targets_check_xlsx(token):
    """A kept file's downloads, re-checked so each is exactly what the page counted: ?what=issues (every issue the
    quality step found, or one kind with &kind=), changes (every change an update makes), final (each person after the
    import, with the decisions in) or done (what the applied file changed, kept for the day)."""
    db = get_db()
    me = current_user()
    what = request.args.get("what") or "issues"
    if what == "done":
        meta = _imp_meta(KTI_KIND, token, me)
        if not meta.get("result"):
            abort(404)
        return _csv_response("kpi-import-applied.csv", ["Employee ID", "Name", "KPI lines", "Weights total",
                                                        "What changed"], meta["result"].get("people") or [])
    got = _kti_load(db, me, active_pm_period(db), token)
    if not got:
        abort(404)
    meta, chk, cls, q, m = got
    if what == "changes":
        rows = [[r["eid"], r["subject_name"], r["kpi_name"], f, a, b] for r in chk["valid"] if not r["skip"]
                for f, a, b in r["changes"]]
        return _csv_response("kpi-import-changes.csv", ["Employee ID", "Name", "KPI", "Field", "From", "To"], rows)
    if what == "final":
        rows = [[p["eid"], p["name"], p["lines"], p["weight"], p["says"]]
                for p in _kti_after(chk, cls, m, meta.get("decisions") or {})]
        return _csv_response("kpi-import-final-preview.csv", ["Employee ID", "Name", "KPI lines", "Weights total",
                                                              "What changes"], rows)
    kind = request.args.get("kind") or ""
    rows = [] if kind else [[e["row"], e["eid"], "Can't be imported", e["kind"], e["why"]] for e in chk["errors"]]
    for g in q["look"]:
        if not kind or g["key"] == kind:
            rows += [[f["row"] or "", f["eid"], "Worth a look", g["what"], f["detail"]] for f in g["found"]]
    return _csv_response("kpi-import-issues.csv", ["Row", "Employee ID", "Severity", "What", "Detail"], rows)


# The KPI targets import's columns: its template and the "People with no KPI line" download both use them, so a
# download filled in goes straight back in (Chris, 2026-10-21: "the export needs to follow our import format").
KPI_TARGETS_IMPORT_COLUMNS = ("Employee ID", "KPI", "Focus", "Strategic Thrust / Category", "KPI Description",
                              "Unit of Measure", "Weightage", "Method", "Rate 1", "Rate 2", "Rate 3",
                              "Rate 4", "Rate 5", "Threshold", "Target", "Multiple", "Excellence",
                              "Matrix manager ID")


def _import_blank_note(n):
    """The one line an import says about rows left with only an Employee ID (the pre-filled downloads), or ''."""
    return ("%d row%s had only an Employee ID and %s skipped: not filled in yet. Fill %s in and import the file "
            "again when ready." % (n, "" if n == 1 else "s", "was" if n == 1 else "were", "it" if n == 1 else "them")
            ) if n else ""


@app.route("/admin/performance/import/template.csv")   # the old address, kept
@app.route("/admin/performance/import/template.xlsx")
@admin_required
def admin_import_kpi_targets_template():
    """CSV template covering both mechanisms' columns (a BG only needs the
    set matching its own pm_bg_config, the rest can be left blank). Its rows are EXAMPLE- placeholders the import
    refuses, as the roster template's are (2026-10-14: it used to seed the first two real Employee IDs, so a template
    uploaded unchanged imported KPI lines onto two real people), via the shared _csv_response() helper."""
    header = list(KPI_TARGETS_IMPORT_COLUMNS)
    # Matrix manager ID: blank = the person's line manager moderates this KPI;
    # an Employee ID sends this KPI to that matrix manager alone.
    rows = [
        ["EXAMPLE-EMPLOYEE-ID-1", "Sales", "", "Financial", "Achieve RM10.3mil sales contribution", "RM", 20,
         "More", 60, 70, 80, 90, 100, "", "", "", "", ""],
        ["EXAMPLE-EMPLOYEE-ID-2", "Profit After Tax", "", "Financial", "Achieve target PAT", "RM", 25,
         "More", "", "", "", "", "", 350000, 500000, 100, "", ""],
        ["EXAMPLE-EMPLOYEE-ID-1", "Project milestones on time", "Northern region", "Operational",
         "Hit the project's milestone dates",
         "%", 25, "More", 80, 85, 90, 95, 100, "", "", "", "", "EXAMPLE-MATRIX-MANAGER-ID"],
    ]
    return _csv_response("pm_kpi_targets_template.csv", header, rows)


# ---------------------------------------------------------------------------
# KPI Library -- curated, reusable KPI templates keyed by BG + department +
# tier band. This is the source material an employee assembles their own
# scorecard FROM (the "AI-led KPI setting" journey, Phase 2) and the candidate
# set the grounded AI draft (Phase 3) selects from. Admin-curated config,
# scoped exactly like admin_performance_config() -- holds no per-person data.
# ---------------------------------------------------------------------------
def _pm_library_scope_msg(bg, company, department, tier_n, job_grade):
    """Readable scope for a flash/log line, e.g.
    'CHBM / GCAST / Sales / Tier 2 / JG 14' with '(any)' where a dimension is
    left open. Kept separate from pm_library_scope_label(), which is the
    compact employee-facing version."""
    def _any(v):
        return "(any)" if v in (None, "", "*") else v
    tier = "(any tier)" if not tier_n else f"Tier {tier_n}"
    return " / ".join([bg, _any(company), _any(department), tier,
                       "JG " + _any(job_grade) if job_grade not in (None, "", "*")
                       else "(any JG)"])


PM_PERSPECTIVES = ("Financial", "Customer", "Internal Process", "Learning & Growth")


def _kpi_key(name):
    """A KPI's identity across business groups: its name, case and spacing folded."""
    return " ".join((name or "").lower().split())


def _kpi_usage_cycle(db):
    """The cycle whose KPI lines say who uses a KPI: the active one when it has lines, else the latest that has."""
    act = active_cycle(db)
    if act and db.execute("SELECT 1 FROM pm_kpi_targets WHERE cycle_id=? LIMIT 1", (act["id"],)).fetchone():
        return act
    return db.execute("SELECT c.* FROM cycles c WHERE EXISTS (SELECT 1 FROM pm_kpi_targets t WHERE t.cycle_id=c.id) "
                      "ORDER BY c.id DESC LIMIT 1").fetchone()


def _kpi_lib_index(db, bgs):
    """The KPI library as the redesign reads it (2026-10-18, the libraries canvas board 1): one identity per KPI name
    across the business groups in `bgs`, each with its library rows (its placements), who uses it on the usage cycle's
    scorecards (people, groups, units, job families and specialisations, from P&R's architecture), and the level it
    files under -- each KPI at the widest level its meaning holds:
      * a BU-level KPI (a unit-wide result): Global when two or more groups use it, else its group;
      * a KPI 70% or more of whose holders (3+) sit in one job family: that job family (and its main specialisation);
      * else Global when two or more groups use it; its group when two or more units do (or nobody yet); its unit when
        one unit's 3 or more people do;
      * one or two holders: their job family, tagged Specialised (a filter, not a level).
    Derived on every read from the library and the lines, never stored. {"ids": {key: identity}, "cycle": row}.
    Batched: one query for the rows, one for the lines."""
    if not bgs:
        return {"ids": {}, "cycle": None, "alias": {}}
    ph = ",".join("?" * len(bgs))
    ids = {}
    # a merged name reads as the KPI it went into, in its own group (pm_kpi_aliases, the merge queue)
    alias = {(r["business_group"], r["alias_key"]): dict(r) for r in db.execute(
        "SELECT * FROM pm_kpi_aliases WHERE business_group IN (%s)" % ph, bgs)}
    # a name merged into a name that was itself merged (a plant's variant into Plant GP, grouped into GP) reads as the
    # last one: follow the chain, a few steps at most
    for (bg_, _k), al_ in alias.items():
        seen_ = {al_["into_key"]}
        nxt = alias.get((bg_, al_["into_key"]))
        while nxt and nxt["into_key"] not in seen_ and len(seen_) < 5:
            seen_.add(nxt["into_key"])
            al_["into_key"], al_["into_name"] = nxt["into_key"], nxt["into_name"]
            nxt = alias.get((bg_, al_["into_key"]))
    for r in db.execute("SELECT * FROM pm_kpi_library WHERE business_group IN (%s) ORDER BY kpi_name, id" % ph, bgs):
        al = alias.get((r["business_group"], _kpi_key(r["kpi_name"])))
        k = al["into_key"] if al else _kpi_key(r["kpi_name"])
        it = ids.setdefault(k, {"key": k, "name": al["into_name"] if al else r["kpi_name"], "rows": [],
                                "people": set(), "lines": 0, "bgs": set(), "units": set(), "fams": {}, "specs": {},
                                "by_bg": {}, "aliases": []})
        rr = dict(r)
        rr["merged_kind"] = al["kind"] if al else None
        rr["scope_word"] = al["qualifier"] if al and al["kind"] == "scope" else None
        if al and r["kpi_name"] not in it["aliases"]:
            it["aliases"].append(r["kpi_name"])
        if not al and _kpi_key(r["kpi_name"]) == k:
            it["name"] = r["kpi_name"]
        it["rows"].append(rr)
    cyc = _kpi_usage_cycle(db)
    if cyc:
        for r in db.execute(
                "SELECT t.kpi_name, t.subject_id, u.business_group, u.company, j.sub_code, j.spec_code "
                "FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
                "LEFT JOIN ja_people j ON j.employee_id = UPPER(TRIM(u.employee_id)) "
                "WHERE t.cycle_id=? AND u.business_group IN (%s)" % ph, [cyc["id"]] + list(bgs)):
            lk = _kpi_key(r["kpi_name"])
            al = alias.get((r["business_group"], lk))
            it = ids.get(al["into_key"] if al else lk)
            if not it:
                continue
            it["lines"] += 1
            if r["subject_id"] in it["people"]:
                continue
            it["people"].add(r["subject_id"])
            it["bgs"].add(r["business_group"])
            if r["company"]:
                it["units"].add((r["business_group"], r["company"]))
            it["by_bg"][r["business_group"]] = it["by_bg"].get(r["business_group"], 0) + 1
            if r["sub_code"]:
                it["fams"][r["sub_code"]] = it["fams"].get(r["sub_code"], 0) + 1
            if r["spec_code"]:
                it["specs"][r["spec_code"]] = it["specs"].get(r["spec_code"], 0) + 1
    for it in ids.values():
        rows = it["rows"]
        live = [x for x in rows if x["active"]] or [x for x in rows if x["merged_kind"] in (None, "scope")] or rows
        first = live[0]
        it["active"] = any(x["active"] for x in rows)
        it["bu_level"] = any(x["bu_level"] for x in live)
        it["perspective"] = next((x["perspective"] for x in live if x.get("perspective")), None)
        cat = next((x["category"] for x in live if x["category"]), "") or ""
        fam, _sep, grp = cat.partition(" · ")
        it["family"], it["group"] = (fam.strip() or "Not grouped"), grp.strip()
        it["unit"], it["method"] = first["unit"], first["method"]
        it["definition"] = next((x["description"] for x in live if x["description"]), None)
        it["lib_bgs"] = sorted({x["business_group"] for x in rows})
        all_bgs = it["bgs"] | set(it["lib_bgs"])
        n = len(it["people"])
        top_fam = max(it["fams"].items(), key=lambda kv: kv[1]) if it["fams"] else (None, 0)
        top_spec = max(it["specs"].items(), key=lambda kv: kv[1]) if it["specs"] else (None, 0)
        it["specialised"] = 0 < n <= 2
        lib_units = {(x["business_group"], x["company"]) for x in live if x["company"] != "*"}
        if it["bu_level"]:
            level = ("global", None) if len(all_bgs) >= 2 else ("bg", first["business_group"])
        elif n >= 3 and top_fam[0] and top_fam[1] >= 0.7 * n:
            level = ("jf", top_fam[0])
        elif len(all_bgs) >= 2:
            level = ("global", None)
        elif 0 < n <= 2 and top_fam[0]:
            level = ("jf", top_fam[0])
        elif len(it["units"]) == 1 and n >= 3:
            level = ("bu", next(iter(it["units"])))
        elif not n and len(lib_units) == 1 and not any(x["company"] == "*" for x in live):
            level = ("bu", next(iter(lib_units)))
        else:
            level = ("bg", first["business_group"])
        it["level"], it["where"] = level
        it["spec"] = top_spec[0] if level[0] == "jf" and top_spec[0] and str(top_spec[0]).startswith(
            str(level[1])) else None
        it["n_people"], it["n_bgs"], it["n_units"] = n, len(it["bgs"]), len(it["units"])
    return {"ids": ids, "cycle": cyc, "alias": alias}


def _kpi_root_key(it, ids, alias):
    """The identity key a variant ("<root>: <qualifier>") rides under (2026-11-06): its plain root key, or, when no identity
    has that key because the root name was merged (pm_kpi_aliases), the alias's chain-followed into_key, looked up only in
    the business groups of the variant's own library rows. '' when it has no root."""
    rk = _kpi_key(_bu_root(it["name"]))
    if not rk or rk in ids:
        return rk
    for bg_ in it.get("lib_bgs") or ():
        al = alias.get((bg_, rk))
        if al:
            return al["into_key"]
    return rk


def _kpi_node_of(it):
    """The tree node an identity files under: 'global', 'bg:<BG>', 'bu:<BG>|<unit>', 'jf:<sub>' (+ 'sp:<spec>')."""
    lv, wh = it["level"], it["where"]
    if lv == "global":
        return "global"
    if lv == "bg":
        return "bg:" + wh
    if lv == "bu":
        return "bu:%s|%s" % wh
    return "jf:" + wh


# ---- The Chart of KPI (Chris, 2026-10-30; docs/chart-of-kpi.md) ------------------------------------------------------
# One group-wide chart of numeric, fixed codes over the KPI library: perspective 1-4, KPI group 11-19, KPI 1101, variant
# 1101-01. Dark unless ONEHR_COA=1 (staging only until after the hypercare). A line's code is DERIVED on read from the
# name map (kpi_chart_names) plus an optional per-line override (pm_kpi_targets.chart_node_id); no writer of
# pm_kpi_targets knows the chart exists.
def coa_on():
    """Whether the Chart of KPI is switched on for this server: ONEHR_COA=1 (staging only). Read on every call, so a
    suite can switch it. Off: the library page is today's, and the chart's POST actions are 404s."""
    return os.environ.get("ONEHR_COA") == "1"


app.jinja_env.globals["coa_on"] = coa_on

# level -> (how many a parent holds, what they are called, what holds them)
COA_LIMITS = {"group": (9, "KPI groups", "a perspective"), "kpi": (99, "KPIs", "a KPI group"),
              "variant": (99, "variants", "a KPI")}
COA_PARENT_LEVEL = {"group": "persp", "kpi": "group", "variant": "kpi"}
COA_NAME_MAX = 120
COA_LEVEL_WORDS = {"global": "Global", "bg": "One group", "bu": "One unit", "jf": "Job family"}


def _chart_clean_name(raw):
    """A chart name as stored: its spaces folded. Blank stays blank; the caller refuses it (and a too-long one)."""
    return re.sub(r"\s+", " ", (raw or "").strip())


def _chart_used_codes(db):
    """Every code any node holds or ever held: a code is never reused, a retired node's and a moved node's old ones
    included (was_codes is a JSON list)."""
    used = set()
    for r in db.execute("SELECT code, was_codes FROM kpi_chart"):
        used.add(r["code"])
        if r["was_codes"]:
            try:
                used.update(str(x) for x in json.loads(r["was_codes"]))
            except (ValueError, TypeError):
                pass
    return used


def _chart_next_code(db, level, parent, used=None):
    """The next free code for a new node of `level` under `parent` (a kpi_chart row or its id). A group is its
    perspective's digit + 1-9, a KPI its group's code + 01-99, a variant its KPI's code + -01 to -99. The lowest code
    nobody ever held. A full level raises ValueError naming the limit; it never wraps or widens. `used` (the set
    _chart_used_codes returns) lets a caller that previews many codes read the chart once."""
    if level not in COA_LIMITS:
        raise ValueError("Unknown chart level: %r." % (level,))
    pid = parent["id"] if hasattr(parent, "keys") else parent
    prow = db.execute("SELECT * FROM kpi_chart WHERE id=?", (pid,)).fetchone()
    limit, plural, under = COA_LIMITS[level]
    if not prow or prow["level"] != COA_PARENT_LEVEL[level]:
        raise ValueError("A %s goes under %s." % (plural[:-1] if plural.endswith("s") else plural, under))
    label = "%s %s" % (prow["code"], prow["name"])
    if prow["retired_at"]:
        raise ValueError("%s is retired, so nothing new goes under it." % label)
    used = _chart_used_codes(db) if used is None else used
    for n in range(1, limit + 1):
        code = prow["code"] + (str(n) if level == "group" else ("-%02d" % n if level == "variant" else "%02d" % n))
        if code not in used:
            return code
    raise ValueError("%s already holds %d %s, the most %s can: codes are fixed and never reused, so it is full."
                     % (label, limit, plural, under))


def _chart_add_node(db, level, parent_id, name, user_id, definition=None, qualifier=None):
    """Write one node under a parent with its next code. Returns (id, code). The caller commits."""
    code = _chart_next_code(db, level, parent_id)
    cur = db.execute("INSERT INTO kpi_chart(code, level, parent_id, name, qualifier, definition, created_by) "
                     "VALUES (?,?,?,?,?,?,?)", (code, level, parent_id, name, qualifier, definition, user_id))
    return cur.lastrowid, code


def _chart_map_name(db, node_id, name, bg, source, user_id):
    """Put a name on a node's name map (group-wide when bg is ''). False when that name is already mapped there."""
    cur = db.execute("INSERT OR IGNORE INTO kpi_chart_names(node_id, name_key, name_shown, business_group, source, "
                     "created_by) VALUES (?,?,?,?,?,?)", (node_id, _kpi_key(name), name, bg or "", source, user_id))
    return cur.rowcount > 0


def _chart_index(db):
    """The whole chart in memory, from ONE batched read of the nodes and the name map -- every population read goes
    through this, never a query per line. {"nodes": {id: node}, "by_code": {code: node}, "children": {id: [node]},
    "names": {(name_key, business_group): node_id}, "names_of": {node_id: [name_shown]}}. A node carries "was" (the
    codes it held before a move)."""
    nodes, by_code, children, names, names_of = {}, {}, {}, {}, {}
    for r in db.execute("SELECT * FROM kpi_chart ORDER BY code"):
        n = dict(r)
        try:
            n["was"] = [str(x) for x in json.loads(r["was_codes"])] if r["was_codes"] else []
        except (ValueError, TypeError):
            n["was"] = []
        nodes[n["id"]] = n
        by_code[n["code"]] = n
    for n in nodes.values():
        if n["parent_id"] in nodes:
            children.setdefault(n["parent_id"], []).append(n)
    for r in db.execute("SELECT node_id, name_key, name_shown, business_group FROM kpi_chart_names ORDER BY id"):
        if r["node_id"] in nodes:
            names[(r["name_key"], r["business_group"])] = r["node_id"]
            names_of.setdefault(r["node_id"], []).append(r["name_shown"])
    return {"nodes": nodes, "by_code": by_code, "children": children, "names": names, "names_of": names_of}


def _chart_aliases(db):
    """The library's merged names ({(business_group, alias_key): row}), read once for a batch of lines."""
    return {(r["business_group"], r["alias_key"]): dict(r) for r in db.execute("SELECT * FROM pm_kpi_aliases")}


def _chart_alias_final(aliases, bg, key):
    """The key a merged name reads as in its group (a merge into a merge is followed, a few steps), or None."""
    al = aliases.get((bg, key))
    if not al:
        return None
    into, seen = al["into_key"], {key}
    for _ in range(5):
        seen.add(into)
        nxt = aliases.get((bg, into))
        if not nxt or nxt["into_key"] in seen:
            break
        into = nxt["into_key"]
    return into


def _chart_lookup(idx, aliases, key, bg):
    """Steps 2 to 4 of the resolution on one name key: the group's own map, then the group-wide map, then the same two on
    the name it was merged into. The node, or None."""
    names, nodes = idx["names"], idx["nodes"]

    def look(k):
        for b in ((bg, "") if bg else ("",)):
            nid = names.get((k, b))
            if nid in nodes and not nodes[nid].get("archived_at"):   # an archived node is out of the chart
                return nodes[nid]
        return None
    hit = look(key)
    if hit:
        return hit
    into = _chart_alias_final(aliases, bg, key) if bg else None
    return look(into) if into and into != key else None


def chart_node_of_line(idx, line, aliases):
    """The chart node a KPI line reads as, or None ("Not in the chart yet"). `line` is a row or dict with kpi_name,
    business_group (the holder's), and optionally focus and chart_node_id. The first found:
      1. the line's own chart_node_id, when that node exists and is not archived (a RETIRED node still answers: its lines keep
         their code and figures; retiring only stops it being offered for new lines and matched);
      2. the name map for the line's business group, on the name's key;
      3. the group-wide map on the same key;
      4. the same two on the name the library merged it into (pm_kpi_aliases);
      5. the same on the line's root ("Root: qualifier" gives Root) and on its base (the name less " · Focus"): a root
         gives the KPI, never a variant;
      6. nothing."""
    nodes = idx["nodes"]
    nid = _row_get(line, "chart_node_id")
    if nid:
        n = nodes.get(nid)
        if n and not n.get("archived_at"):
            return n
    name = _row_get(line, "kpi_name") or ""
    bg = _row_get(line, "business_group") or ""
    key = _kpi_key(name)
    n = _chart_lookup(idx, aliases, key, bg)
    if n:
        return n
    for cand in (_kpi_key(_bu_root(name)), _kpi_key(kpi_line_base(name, _row_get(line, "focus")))):
        if cand and cand != key:
            n = _chart_lookup(idx, aliases, cand, bg)
            if n:
                return nodes.get(n["parent_id"], n) if n["level"] == "variant" else n
    return None


def chart_code_of_line(idx, line, aliases):
    """A line's code ("1101" or "1101-01"), or None; see chart_node_of_line for the order it is found in."""
    n = chart_node_of_line(idx, line, aliases)
    return n["code"] if n else None


def chart_nodes_of_lines(db, lines, idx=None, aliases=None):
    """The node (or None) of each of many lines: the chart and the aliases are read ONCE, then every line is a few
    dictionary lookups. Returns a list aligned with `lines`."""
    idx = idx or _chart_index(db)
    aliases = aliases if aliases is not None else _chart_aliases(db)
    return [chart_node_of_line(idx, ln, aliases) for ln in lines]


def _chart_line_coverage(db, cycle_id, idx, aliases):
    """(lines with a code, all lines) on one cycle, from one grouped read of the lines."""
    if not cycle_id:
        return 0, 0
    rows = db.execute(
        "SELECT t.kpi_name, COALESCE(t.focus,'') AS focus, t.chart_node_id, u.business_group AS business_group, "
        "COUNT(*) AS n FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id WHERE t.cycle_id=? "
        "GROUP BY t.kpi_name, COALESCE(t.focus,''), t.chart_node_id, u.business_group", (cycle_id,)).fetchall()
    coded = sum(r["n"] for r, nd in zip(rows, chart_nodes_of_lines(db, rows, idx, aliases)) if nd)
    return coded, sum(r["n"] for r in rows)


def _chart_name_node(db, key, bg=""):
    """The node a name key is mapped to in one scope, or None (a direct read, for the seed and the writers)."""
    r = db.execute("SELECT node_id FROM kpi_chart_names WHERE name_key=? AND business_group=?", (key, bg)).fetchone()
    return r["node_id"] if r else None


def _chart_keys_of(aliases):
    """An identity's key -> the merged names that read as it: [(business_group, alias_key, alias_name)]."""
    keys_of = {}
    for (bg_, ak_), al in aliases.items():
        fk = _chart_alias_final(aliases, bg_, ak_)
        if fk:
            keys_of.setdefault(fk, []).append((bg_, ak_, al["alias_name"]))
    return keys_of


def _chart_map_aliases(db, nid, key, keys_of, ids, user_id, source="seed", skip=()):
    """Map every name merged into the identity `key` onto node `nid`. A merged name goes group-wide, unless that spelling is
    another KPI's own name or already mapped elsewhere: then this group's own map holds it. How many names were added."""
    n = 0
    for bg_, ak_, an_ in keys_of.get(key, []):
        if ak_ in skip:   # a name an archived node parked: it stays off the map until that node is restored
            continue
        scope = bg_ if (ak_ in ids or _chart_name_node(db, ak_) not in (None, nid)) else ""
        if _chart_map_name(db, nid, an_, scope, source, user_id):
            n += 1
    return n


def _chart_lib_ids(db):
    """The library's identities across EVERY business group, retired groups and rows included ({key: identity}, as
    _kpi_lib_index returns them): the seed and retire / bring back read the whole library, whoever is looking."""
    bgs = sorted(set(org_bgs(db, active_only=False))
                 | {r[0] for r in db.execute("SELECT DISTINCT business_group FROM pm_kpi_library")})
    return _kpi_lib_index(db, bgs)["ids"]


def _chart_archived_keys(db):
    """Every name key a node has parked on archive (kpi_chart.archived_names): the seed never builds a node for them again."""
    out = set()
    for r in db.execute("SELECT archived_names FROM kpi_chart WHERE archived_names IS NOT NULL"):
        try:
            out.update(str(x["name_key"]) for x in json.loads(r[0]))
        except (ValueError, TypeError, KeyError):
            pass
    return out


def _chart_seed(db, user_id):
    """Build the chart from today's library (the plan's seed). Groups come from each KPI's family · group (the part after
    " · ") under its perspective; one KPI node per library identity across EVERY business group; the name map takes
    the identity's key and every name merged into it. A KPI with no perspective, or none with a group, stays in "Needs a
    place". Idempotent: a second run adds only what is missing. Does not commit. Returns the counts."""
    ids = _chart_lib_ids(db)
    aliases = _chart_aliases(db)
    keys_of = _chart_keys_of(aliases)
    parked = _chart_archived_keys(db)   # an archived identity is not re-created
    persp = {r["name"]: r["id"] for r in db.execute("SELECT id, name FROM kpi_chart WHERE level='persp'")}
    out = {"groups": 0, "kpis": 0, "names": 0, "untagged": 0, "no_group": 0, "full": 0}

    def put(node_id, name, bg, source="seed"):
        if _chart_map_name(db, node_id, name, bg, source, user_id):
            out["names"] += 1
            return True
        return False

    for it in sorted(ids.values(), key=lambda x: (x["name"].lower(), x["key"])):
        if it["key"] in parked:
            continue
        nid = _chart_name_node(db, it["key"])
        if nid is None:
            nid = next((m for m in (_chart_name_node(db, it["key"], b) for b in it["lib_bgs"]) if m), None)
        if nid is None:
            pid = persp.get(it["perspective"])
            if not pid:
                out["untagged"] += 1
                continue
            gname = _chart_clean_name(it["group"])
            if not gname:
                out["no_group"] += 1
                continue
            g = db.execute("SELECT id FROM kpi_chart WHERE parent_id=? AND level='group' AND LOWER(name)=?",
                           (pid, gname.lower())).fetchone()
            try:
                if g:
                    gid = g["id"]
                else:
                    gid, _c = _chart_add_node(db, "group", pid, gname[:COA_NAME_MAX], user_id)
                    out["groups"] += 1
                nid, _c = _chart_add_node(db, "kpi", gid, _chart_clean_name(it["name"])[:COA_NAME_MAX], user_id,
                                          definition=it["definition"])
                out["kpis"] += 1
            except ValueError:
                out["full"] += 1
                continue
            put(nid, it["name"], "")
        else:
            put(nid, it["name"], "")   # a no-op unless the identity key itself was missing from the map
        out["names"] += _chart_map_aliases(db, nid, it["key"], keys_of, ids, user_id, skip=parked)
    return out


# ---- piece A2: a KPI's place in the chart, its variants, and named people on a library row --------------------------------
COA_QUALIFIER_MAX = 60
PM_LIB_PEOPLE_MAX = 50   # named people on one library row (board 4b)


def _chart_node_of_identity(idx, aliases, it):
    """The node a library identity files under (its key through _chart_lookup: this group's map, then the group-wide one,
    then the name it was merged into), or None. The first of the identity's own groups that finds one wins."""
    for b in ("",) + tuple(it["lib_bgs"]):
        n = _chart_lookup(idx, aliases, it["key"], b)
        if n:
            return n
    return None


def _chart_place_of(idx, node):
    """(perspective node, KPI group node) a KPI (or a variant, through its KPI) sits under; None where it has no parent."""
    n = idx["nodes"].get(node["parent_id"]) if node and node["level"] == "variant" else node
    g = idx["nodes"].get(n["parent_id"]) if n else None
    p = idx["nodes"].get(g["parent_id"]) if g else None
    return p, g


def _chart_cycle_lines(db, cycle_id, idx, aliases):
    """Every KPI line of one cycle with the node it reads as: [(line dict, node or None)]. ONE read of the lines and one
    pass over the chart in memory (chart_nodes_of_lines)."""
    if not cycle_id:
        return []
    rows = [dict(r) for r in db.execute(
        "SELECT t.id, t.subject_id, t.kpi_name, COALESCE(t.focus,'') AS focus, t.chart_node_id, "
        "u.business_group AS business_group, u.company AS company FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
        "WHERE t.cycle_id=?", (cycle_id,))]
    return list(zip(rows, chart_nodes_of_lines(db, rows, idx, aliases)))


def _chart_place_opts(db, idx=None):
    """What the place pickers offer: [{"id", "code", "name", "next_group" (the code a new group would take, or None when
    the perspective is full), "groups": [{"id", "code", "name", "next" (the next KPI code, or None when the group is
    full)}]}], by perspective. The chart is read once and the used codes once."""
    idx = idx or _chart_index(db)
    used = _chart_used_codes(db)
    out = []
    for p in sorted((n for n in idx["nodes"].values() if n["level"] == "persp" and not n["retired_at"]),
                    key=lambda n: n["code"]):
        try:
            ng = _chart_next_code(db, "group", p, used)
        except ValueError:
            ng = None
        grs = []
        for g in sorted((x for x in idx["children"].get(p["id"], []) if x["level"] == "group" and not x["retired_at"]),
                        key=lambda x: x["code"]):
            try:
                nk = _chart_next_code(db, "kpi", g, used)
            except ValueError:
                nk = None
            grs.append({"id": g["id"], "code": g["code"], "name": g["name"], "next": nk})
        out.append({"id": p["id"], "code": p["code"], "name": p["name"], "next_group": ng, "groups": grs})
    return out


def _chart_place_resolve(db, form, idx=None):
    """Read the place a form chose (Perspective by name, KPI group by id or "__new__" + group_new) WITHOUT writing:
    (plan, error). plan is None when nothing was chosen (the KPI stays "Not in the chart yet"), else {"persp": node,
    "group": node or None, "new_group": the new group's name or None}. A group that isn't under the perspective, a
    retired one, a blank or repeated new name, a full perspective: refused, in words."""
    idx = idx or _chart_index(db)
    pname = (form.get("perspective") or "").strip()
    graw = (form.get("chart_group") or "").strip()
    if not pname and not graw:
        return None, None
    if not pname or not graw:
        return None, "Choose the perspective and the KPI group together, or leave both blank."
    persp = next((n for n in idx["nodes"].values() if n["level"] == "persp" and n["name"] == pname), None)
    if not persp:
        return None, "Choose a perspective from the list."
    if graw == "__new__":
        nm = _chart_clean_name(form.get("group_new"))
        if not nm:
            return None, "Type the name of the new KPI group, or pick one from the list."
        if len(nm) > COA_NAME_MAX:
            return None, "Keep the name of the KPI group to %d characters." % COA_NAME_MAX
        if any(x["level"] == "group" and not x["retired_at"] and x["name"].lower() == nm.lower()
               for x in idx["children"].get(persp["id"], [])):
            return None, "%s %s already has a KPI group called '%s': pick it from the list." % (
                persp["code"], persp["name"], nm)
        try:
            _chart_next_code(db, "group", persp)
        except ValueError as e:
            return None, str(e)
        return {"persp": persp, "group": None, "new_group": nm}, None
    try:
        grp = idx["nodes"].get(int(graw))
    except ValueError:
        grp = None
    if not grp or grp["level"] != "group" or grp["parent_id"] != persp["id"] or grp["retired_at"]:
        return None, "Choose a KPI group under %s %s." % (persp["code"], persp["name"])
    return {"persp": persp, "group": grp, "new_group": None}, None


def _chart_place_apply(db, plan, name, definition, user_id):
    """Write a resolved place: the new group when one was asked for, then the KPI node under it. (node id, code). The
    caller maps the name and commits; a full level raises ValueError naming its limit (the caller undoes the group)."""
    gid = plan["group"]["id"] if plan["group"] else _chart_add_node(db, "group", plan["persp"]["id"],
                                                                     plan["new_group"], user_id)[0]
    return _chart_add_node(db, "kpi", gid, _chart_clean_name(name)[:COA_NAME_MAX], user_id, definition=definition)


def _chart_after_add(db, me, plan, kpi_name, description, bg):
    """After a library KPI is added with a place chosen: its node and its name-map row. A name that already has a code (this
    group's map, the group-wide one, or the name it was merged into) reuses it: no new node. Says what happened."""
    idx, aliases = _chart_index(db), _chart_aliases(db)
    have = _chart_lookup(idx, aliases, _kpi_key(kpi_name), bg)
    if have:
        flash("'%s' already has the code %s, so it keeps it: no new code was made." % (kpi_name, have["code"]), "ok")
        return
    try:
        nid, code = _chart_place_apply(db, plan, kpi_name, description, me["id"])
    except ValueError as e:
        db.rollback()
        flash("Added to the library, but not given a code: %s" % e, "error")
        return
    _chart_map_name(db, nid, kpi_name, "", "add", me["id"])
    gname = plan["new_group"] or plan["group"]["name"]
    log_activity(db, me["id"], "pm_kpi_chart", "code %s given to KPI %s, under %s %s" % (code, kpi_name, code[:2], gname))
    flash("'%s' has the code %s." % (kpi_name, code), "ok")


# ---- retire and archive (Chris, 2026-10-30; the canvas boards 8 and 9) ---------------------------------------------------
# RETIRE (any time, even in use): the node is not offered for new lines and not matched, but every line that carries it keeps
# its code and figures. Retiring a KPI also retires its active variants and active library placements and records them
# (retired_with), so Bring back reopens exactly those. ARCHIVE (only when nothing uses it): the node leaves the chart, its name-map
# rows are parked on the node (archived_names) so the names can be matched elsewhere, and its code stays used for good.
def _chart_status(n):
    """'archived', 'retired' or 'active' for a chart node (a dict or a row)."""
    return "archived" if n["archived_at"] else ("retired" if n["retired_at"] else "active")


def _chart_day(ts):
    """A stored UTC timestamp as '30 Oct' (Malaysia time, no year)."""
    s_ = _myt_date_str(ts) or ""
    return s_.rsplit(" ", 1)[0] if s_.count(" ") == 2 else s_


def _chart_cycle_names(db):
    return {r["id"]: r["name"] for r in db.execute("SELECT id, name FROM cycles")}


def _chart_node_usage(db, idx=None, aliases=None):
    """How many KPI lines, in EVERY cycle, read as each node: {node_id: {cycle_id: lines}}. ONE grouped read of the lines
    and one pass through chart_nodes_of_lines -- the same resolution as everywhere, so a line counts for the node it reads as
    (an override first, then the name map, a retired node included). Called once per request, never per row."""
    idx = idx or _chart_index(db)
    aliases = aliases if aliases is not None else _chart_aliases(db)
    rows = [dict(r) for r in db.execute(
        "SELECT t.cycle_id, t.kpi_name, COALESCE(t.focus,'') AS focus, t.chart_node_id, u.business_group AS business_group, "
        "COUNT(*) AS n FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
        "GROUP BY t.cycle_id, t.kpi_name, COALESCE(t.focus,''), t.chart_node_id, u.business_group")]
    out = {}
    for r, nd in zip(rows, chart_nodes_of_lines(db, rows, idx, aliases)):
        if nd:
            per = out.setdefault(nd["id"], {})
            per[r["cycle_id"]] = per.get(r["cycle_id"], 0) + r["n"]
    return out


def _chart_family(idx, node):
    """The node and, for a KPI, every variant under it (archived ones too): [ids]."""
    ids_ = [node["id"]]
    if node["level"] == "kpi":
        ids_ += [v["id"] for v in idx["children"].get(node["id"], []) if v["level"] == "variant"]
    return ids_


def _chart_links_set(db):
    return {r[0] for r in db.execute("SELECT node_id FROM kpi_chart_links")}


def _chart_archive_block(idx, node, usage, cycle_names, linked):
    """What stops Archive on a KPI or variant, in words (the first thing), or '' when nothing does: a line in ANY cycle that
    reads as it (for a KPI, as it or any variant), a data link on it (or any variant), a variant not yet archived."""
    fam = _chart_family(idx, node)
    per = {}
    for i in fam:
        for cid, n in usage.get(i, {}).items():
            per[cid] = per.get(cid, 0) + n
    if per:
        parts = ["%d line%s in %s" % (n, "" if n == 1 else "s", cycle_names.get(cid, "cycle %s" % cid))
                 for cid, n in sorted(per.items(), key=lambda kv: -kv[0])]
        text = parts[0] if len(parts) == 1 else (" and ".join(parts) if len(parts) == 2 else
                                                 "%s and %d more cycles" % (", ".join(parts[:2]), len(parts) - 2))
        total = sum(per.values())
        own = sum(usage.get(node["id"], {}).values())
        return "%s still carr%s %s%s" % (text, "ies" if total == 1 else "y", node["code"],
                                         " or its variants" if node["level"] == "kpi" and total > own else "")
    if node["id"] in linked:
        return "It has a data link"
    if any(i in linked for i in fam[1:]):
        return "A variant has a data link"
    open_v = [v for v in idx["children"].get(node["id"], []) if v["level"] == "variant" and not v["archived_at"]] \
        if node["level"] == "kpi" else []
    if open_v:
        return "Archive its %d variant%s first" % (len(open_v), "" if len(open_v) == 1 else "s")
    return ""


def _chart_node_lib_rows(idx, aliases, ids, node):
    """The library rows (placements, every business group) of the identities that file under one KPI node: [row dict]."""
    out = []
    for it in ids.values():
        n = _chart_node_of_identity(idx, aliases, it)
        if n and n["id"] == node["id"]:
            out.extend(it["rows"])
    return out


def _chart_retire(db, idx, aliases, ids, node, user_id):
    """Retire a KPI or a variant. A KPI also retires its active variants and its active library placements (active=0, as
    the per-placement Retire does) and records exactly those in retired_with. (variant nodes, placements) retired. The
    caller checks the rules and commits."""
    vs, ls = [], []
    if node["level"] == "kpi":
        vs = [v for v in idx["children"].get(node["id"], []) if v["level"] == "variant" and not v["retired_at"]
              and not v["archived_at"]]
        ls = [r for r in _chart_node_lib_rows(idx, aliases, ids, node) if r["active"]]
        for v in vs:
            db.execute("UPDATE kpi_chart SET retired_at=datetime('now'), retired_by=?, retired_with=NULL, updated_by=?, "
                       "updated_at=datetime('now') WHERE id=?", (user_id, user_id, v["id"]))
        for r in ls:
            db.execute("UPDATE pm_kpi_library SET active=0, updated_at=datetime('now'), updated_by=? WHERE id=?",
                       (user_id, r["id"]))
    with_ = json.dumps({"lib": [r["id"] for r in ls], "nodes": [v["id"] for v in vs]}) if node["level"] == "kpi" else None
    db.execute("UPDATE kpi_chart SET retired_at=datetime('now'), retired_by=?, retired_with=?, updated_by=?, "
               "updated_at=datetime('now') WHERE id=?", (user_id, with_, user_id, node["id"]))
    return vs, ls


def _chart_with(node):
    """What a KPI's Retire took with it: {"lib": [ids], "nodes": [ids]}; empty lists where nothing was recorded."""
    try:
        d = json.loads(node["retired_with"]) if node["retired_with"] else {}
    except (ValueError, TypeError):
        d = {}
    return {"lib": [int(x) for x in d.get("lib", [])], "nodes": [int(x) for x in d.get("nodes", [])]}


def _chart_bring_back(db, idx, node, user_id):
    """Reopen a retired KPI or variant and, for a KPI, exactly what was retired with it (variants retired on their own stay
    retired). (variants reopened, placements reopened). The caller checks the rules and commits."""
    w = _chart_with(node)
    nv = nl = 0
    for vid in w["nodes"]:
        v = idx["nodes"].get(vid)
        if v and v["parent_id"] == node["id"] and v["retired_at"] and not v["archived_at"]:
            db.execute("UPDATE kpi_chart SET retired_at=NULL, retired_by=NULL, retired_with=NULL, updated_by=?, "
                       "updated_at=datetime('now') WHERE id=?", (user_id, vid))
            nv += 1
    for lid in w["lib"]:
        nl += db.execute("UPDATE pm_kpi_library SET active=1, updated_at=datetime('now'), updated_by=? WHERE id=? AND active=0",
                         (user_id, lid)).rowcount
    db.execute("UPDATE kpi_chart SET retired_at=NULL, retired_by=NULL, retired_with=NULL, updated_by=?, "
               "updated_at=datetime('now') WHERE id=?", (user_id, node["id"]))
    return nv, nl


def _chart_archive(db, idx, aliases, ids, node, user_id):
    """Archive an unused node (the caller has checked): retire it first when it is in use, park its name-map rows on the node
    and take them off the map, stamp archived_at / archived_by. (retired in the same step?, names parked)."""
    was_active = not node["retired_at"]
    if was_active:
        _chart_retire(db, idx, aliases, ids, node, user_id)
    names = [dict(r) for r in db.execute("SELECT name_key, name_shown, business_group, source FROM kpi_chart_names "
                                         "WHERE node_id=? ORDER BY id", (node["id"],))]
    db.execute("DELETE FROM kpi_chart_names WHERE node_id=?", (node["id"],))
    db.execute("UPDATE kpi_chart SET archived_at=datetime('now'), archived_by=?, archived_names=?, updated_by=?, "
               "updated_at=datetime('now') WHERE id=?", (user_id, json.dumps(names), user_id, node["id"]))
    return was_active, len(names)


def _chart_restore(db, node, user_id):
    """Put an archived node back as RETIRED: archived_at off, its parked names back on the map. A name another node has taken
    since is skipped. (names put back, names skipped). The caller checks the rules and commits."""
    try:
        names = json.loads(node["archived_names"]) if node["archived_names"] else []
    except (ValueError, TypeError):
        names = []
    put = skipped = 0
    for nm in names:
        src = nm.get("source") if nm.get("source") in ("add", "match", "variant", "seed", "move") else "add"
        cur = db.execute("INSERT OR IGNORE INTO kpi_chart_names(node_id, name_key, name_shown, business_group, source, created_by) "
                         "VALUES (?,?,?,?,?,?)", (node["id"], nm["name_key"], nm["name_shown"], nm.get("business_group") or "",
                                                  src, user_id))
        if cur.rowcount > 0:
            put += 1
        else:
            skipped += 1
    db.execute("UPDATE kpi_chart SET archived_at=NULL, archived_by=NULL, archived_names=NULL, "
               "retired_at=COALESCE(retired_at, datetime('now')), updated_by=?, updated_at=datetime('now') WHERE id=?",
               (user_id, node["id"]))
    return put, skipped


def _chart_confirm(kind, node, **kw):
    """The words of one action's confirm box (the canvas boards 8 and 9): {"title", "msg", "ok", "list"}."""
    code, label = node["code"], "%s %s" % (node["code"], node["name"])
    if kind == "retire":
        extras = []
        if kw.get("n_vars"):
            extras.append("its %d variant%s" % (kw["n_vars"], "" if kw["n_vars"] == 1 else "s"))
        if kw.get("n_lib"):
            extras.append("its %d placement%s" % (kw["n_lib"], "" if kw["n_lib"] == 1 else "s"))
        what = label + ((", " if len(extras) == 2 else " and ") + " and ".join(extras) if extras else "")
        items = []
        if kw.get("lines"):
            items.append("%s keep %s and their figures" % (kw["lines"], code))
        else:
            items.append("No line carries %s now; any that did would keep it and its figures" % code)
        if kw.get("linked"):
            items.append("Its data link stays saved")
        items.append("Bring back reverses it")
        return {"title": "Retire %s?" % code, "ok": "Retire %s" % code, "list": items,
                "msg": "Retire %s? Nobody can pick it for a new line and Match lines stops suggesting it." % what}
    if kind == "bringback":
        extras = []
        if kw.get("n_vars"):
            extras.append("%d variant%s" % (kw["n_vars"], "" if kw["n_vars"] == 1 else "s"))
        if kw.get("n_lib"):
            extras.append("%d placement%s" % (kw["n_lib"], "" if kw["n_lib"] == 1 else "s"))
        return {"title": "Bring back %s?" % code, "ok": "Bring back %s" % code,
                "msg": "Bring back %s%s? It can be picked for new lines and matched again." % (
                    label, (" with its " + " and ".join(extras) + " that were retired with it") if extras else ""),
                "list": (["Variants retired on their own stay retired"] if node["level"] == "kpi" else
                         ["It comes back as it was, with its code and names"])}
    if kind == "archive":
        items = ["The code %s is kept and never used again" % code, "Restore brings it back as retired"]
        if kw.get("in_use"):
            items.insert(0, "It is retired in the same step")
        return {"title": "Archive %s?" % code, "ok": "Archive %s" % code, "list": items,
                "msg": "Archive %s? It leaves the chart and goes to the Archived list. No line in any cycle carries it and it "
                       "has no data link." % label}
    return {"title": "Restore %s?" % code, "ok": "Restore %s" % code,
            "msg": "Restore %s? It comes back as retired, with its names on the map again." % label,
            "list": ["Bring back then reopens it", "A name another KPI has taken since stays with that KPI"]}


def _chart_kpi_panel(db, it, cyc, ids=None):
    """What the KPI panel's chart sections draw for one library identity: its node, where it sits, its variants with their
    holders, the lines that read as it by business group (the usage cycle's, from ONE read), the groups it could move to
    and the code its next variant would take. node is None when the KPI has no code yet (then "place_opts" is what the
    Give it a place form offers)."""
    idx = _chart_index(db)
    aliases = _chart_aliases(db)
    node = _chart_node_of_identity(idx, aliases, it)
    out = {"node": node, "bu_level": any(r["active"] and r["bu_level"] for r in it["rows"]),
           "place_opts": _chart_place_opts(db, idx), "cycle": cyc}
    if not node:
        return out
    kpi = node if node["level"] == "kpi" else idx["nodes"].get(node["parent_id"], node)
    persp, grp = _chart_place_of(idx, kpi)
    vs = sorted((v for v in idx["children"].get(kpi["id"], []) if v["level"] == "variant" and not v["archived_at"]),
                key=lambda v: v["code"])
    mine, via = {"lines": 0, "people": set(), "bgs": {}}, {v["id"]: set() for v in vs}
    held = {}   # node id -> who holds a line of it (the data link's preview reads it)
    for ln, nd in _chart_cycle_lines(db, cyc["id"] if cyc else None, idx, aliases):
        if not nd:
            continue
        if nd["id"] == kpi["id"] or nd["id"] in via:
            held.setdefault(nd["id"], set()).add(ln["subject_id"])
        if nd["id"] == kpi["id"]:
            b = mine["bgs"].setdefault(ln["business_group"] or "", {"lines": 0, "people": set(), "names": {}})
            b["lines"] += 1
            b["people"].add(ln["subject_id"])
            b["names"][ln["kpi_name"]] = b["names"].get(ln["kpi_name"], 0) + 1
            mine["lines"] += 1
            mine["people"].add(ln["subject_id"])
        elif nd["id"] in via:
            via[nd["id"]].add(ln["subject_id"])
    used = _chart_used_codes(db)
    moves = []
    for p in _chart_place_opts(db, idx):
        gs = [g for g in p["groups"] if not grp or g["id"] != grp["id"]]
        if gs:
            moves.append((p, gs))
    try:
        nv = _chart_next_code(db, "variant", kpi, used) if not kpi["retired_at"] else None
        nv_err = None
    except ValueError as e:
        nv, nv_err = None, str(e)
    # retire and archive: the status row of this node and of each variant (ONE read of the lines of every cycle, one of the links)
    usage = _chart_node_usage(db, idx, aliases)
    cnames, linked = _chart_cycle_names(db), _chart_links_set(db)
    ids = ids if ids is not None else _chart_lib_ids(db)
    ccid = cyc["id"] if cyc else None

    def st_of(n):
        st = _chart_status(n)
        fam = _chart_family(idx, n)
        own_now = usage.get(n["id"], {}).get(ccid, 0) if ccid else 0
        fam_now = sum(usage.get(i, {}).get(ccid, 0) for i in fam) if ccid else 0
        why = _chart_archive_block(idx, n, usage, cnames, linked) if st != "archived" else ""
        d = {"st": st, "day": _chart_day(n["retired_at"]) if n["retired_at"] else "", "why": why, "own_now": own_now,
             "fam_now": fam_now, "linked": n["id"] in linked}
        words = ("%d line%s in %s" % (fam_now, "" if fam_now == 1 else "s", cyc["name"])) if (ccid and fam_now) else ""
        d["lines_words"] = words
        if st == "active":
            nv = sum(1 for v in idx["children"].get(n["id"], []) if v["level"] == "variant" and not v["retired_at"]
                     and not v["archived_at"]) if n["level"] == "kpi" else 0
            nl = sum(1 for r in _chart_node_lib_rows(idx, aliases, ids, n) if r["active"]) if n["level"] == "kpi" else 0
            d["retire"] = _chart_confirm("retire", n, n_vars=nv, n_lib=nl, lines=words, linked=d["linked"])
            d["archive"] = _chart_confirm("archive", n, in_use=True)
        elif st == "retired":
            w = _chart_with(n)
            nv = sum(1 for vid in w["nodes"] if idx["nodes"].get(vid) and idx["nodes"][vid]["retired_at"]
                     and not idx["nodes"][vid]["archived_at"])
            lib_back = {r["id"]: r for r in db.execute("SELECT id, active FROM pm_kpi_library WHERE id IN (%s)" % (
                ",".join("?" * len(w["lib"])) or "NULL"), w["lib"])} if w["lib"] else {}
            nl = sum(1 for r in lib_back.values() if not r["active"])
            d["bringback"] = _chart_confirm("bringback", n, n_vars=nv, n_lib=nl)
            d["archive"] = _chart_confirm("archive", n)
        d["blocked_back"] = ""
        if st == "retired" and n["level"] == "variant":
            par = idx["nodes"].get(n["parent_id"])
            if par and par["retired_at"]:
                d["blocked_back"] = "Bring back %s first" % par["code"]
        return d
    out.update({"kpi": kpi, "is_variant": node["level"] == "variant", "persp": persp, "group": grp,
                "status": st_of(node),
                "variants": [{"node": v, "people": len(via[v["id"]]), "status": st_of(v)} for v in vs], "n_via": sum(len(x) for x in via.values()),
                "by_bg": sorted(({"bg": b, **d, "n_people": len(d["people"])} for b, d in mine["bgs"].items()),
                                key=lambda d: (-d["lines"], d["bg"])),
                "n_lines": mine["lines"], "n_holders": len(mine["people"]), "moves": moves if not kpi["retired_at"] else [],
                "next_variant": nv,
                "next_variant_err": nv_err, "held": held})
    return out


def _chart_move_kpi(db, kpi, group, user_id):
    """Move a KPI (and its variants) under another KPI group: each takes the next free code there, its old code goes into
    was_codes (never used again), and the name map and every line's override follow the NODE, so they are not touched.
    [(old code, new code)], the KPI first. Raises ValueError (nothing written by the caller) when the group is full or
    retired. The caller commits."""
    if kpi["retired_at"]:
        raise ValueError("%s is retired: bring it back first." % kpi["code"])
    if group["level"] != "group" or group["retired_at"]:
        raise ValueError("Choose a KPI group that is not retired.")
    if kpi["parent_id"] == group["id"]:
        raise ValueError("%s %s already sits under %s %s." % (kpi["code"], kpi["name"], group["code"], group["name"]))
    kids = db.execute("SELECT * FROM kpi_chart WHERE parent_id=? AND level='variant' AND archived_at IS NULL ORDER BY code",
                      (kpi["id"],)).fetchall()   # an archived variant keeps its code for good

    def step(row, level, parent_id):
        code = _chart_next_code(db, level, parent_id)
        was = []
        try:
            was = [str(x) for x in json.loads(row["was_codes"])] if row["was_codes"] else []
        except (ValueError, TypeError):
            was = []
        if row["code"] not in was:
            was.append(row["code"])
        db.execute("UPDATE kpi_chart SET code=?, parent_id=?, was_codes=?, updated_by=?, updated_at=datetime('now') "
                   "WHERE id=?", (code, parent_id, json.dumps(was), user_id, row["id"]))
        return (row["code"], code)
    done = [step(kpi, "kpi", group["id"])]
    for v in kids:
        done.append(step(v, "variant", kpi["id"]))
    return done


def _pm_lib_people_map(db, business_group=None):
    """{library id: {user id}} for the library rows that name people (all of them, or one business group's). A row that
    names people matches only them (pm_library_matches_person); ONE read, never a query per row. {} on a database
    from before the table."""
    sql, args = "SELECT p.library_id, p.user_id FROM pm_kpi_library_people p", []
    if business_group is not None:
        sql += " JOIN pm_kpi_library l ON l.id=p.library_id WHERE l.business_group=?"
        args = [business_group or ""]
    out = {}
    try:
        for r in db.execute(sql, args):
            out.setdefault(r[0], set()).add(r[1])
    except sqlite3.OperationalError:
        return {}
    return out


def _pm_lib_people_parse(db, form, bg, bu_level):
    """The people a library form names (flag on): (user ids or None, error). Mode "scope" (or anything but "people") names
    none, which on an update clears the set. Mode "people" takes the picker's Employee IDs through the roster's own
    resolver and refuses: a BU-level KPI, none picked, more than PM_LIB_PEOPLE_MAX, an ID that is nobody, a leaver, an
    admin account, or a person outside the row's business group."""
    if form.get("mode") != "people":
        return [], None
    if bu_level:
        return None, ("A business-unit level KPI is the whole unit's, so it can't be limited to named people: choose "
                      "units, departments and grades, and pick its carriers in BU KPI setup.")
    eids = list(dict.fromkeys(e.strip() for e in (form.get("people_eids") or "").replace("\n", ",").split(",")
                              if e.strip()))
    if not eids:
        return None, "Pick at least one person, or choose Units, departments and grades."
    if len(eids) > PM_LIB_PEOPLE_MAX:
        return None, ("Named people takes up to %d (you picked %d): for more, use units, departments and grades."
                      % (PM_LIB_PEOPLE_MAX, len(eids)))
    found = _eid_resolve_many(db, eids)
    gone = [e for e in eids if e not in found]
    left = [e for e in eids if e in found and (found[e][0]["left_at"] or found[e][0]["role"] == "admin")]
    other = [e for e in eids if e in found and e not in left and (found[e][0]["business_group"] or "") != bg]
    for ids_, msg in ((gone, "%s is nobody on the roster"), (left, "%s has left, or is an admin account"),
                      (other, "%s is not in " + display_bg(bg))):
        if ids_:
            return None, ("Named people are active people in %s only: " % display_bg(bg)) + msg % ", ".join(ids_) + "."
    uids = list(dict.fromkeys(found[e][0]["id"] for e in eids))
    return uids, None


def _pm_lib_people_set(db, lib_id, uids, user_id):
    """Make a library row's named people exactly `uids` (the ones already there keep who added them and when). The caller
    commits."""
    have = {r[0] for r in db.execute("SELECT user_id FROM pm_kpi_library_people WHERE library_id=?", (lib_id,))}
    for u in have - set(uids):
        db.execute("DELETE FROM pm_kpi_library_people WHERE library_id=? AND user_id=?", (lib_id, u))
    for u in uids:
        if u not in have:
            db.execute("INSERT INTO pm_kpi_library_people(library_id, user_id, added_by) VALUES (?,?,?)",
                       (lib_id, u, user_id))


def _pm_lib_people_detail(db, lib_ids):
    """{library id: {"chips": [{eid, name}], "n": people who can pick it now}} for the rows asked about, in one read. A
    person who left, or moved to another business group, stays listed but does not count."""
    out = {i: {"chips": [], "n": 0} for i in lib_ids}
    if not lib_ids:
        return out
    ph = ",".join("?" * len(lib_ids))
    for r in db.execute("SELECT p.library_id, u.employee_id, u.full_name, u.left_at, u.business_group AS ubg, "
                        "l.business_group AS lbg FROM pm_kpi_library_people p JOIN users u ON u.id=p.user_id "
                        "JOIN pm_kpi_library l ON l.id=p.library_id WHERE p.library_id IN (%s) "
                        "ORDER BY LOWER(u.full_name)" % ph, list(lib_ids)):
        d = out[r["library_id"]]
        d["chips"].append({"eid": r["employee_id"] or "", "name": r["full_name"]})
        if not r["left_at"] and (r["ubg"] or "") == (r["lbg"] or ""):
            d["n"] += 1
    return out


def _chart_view(db, ids, cyc, cn, q, status, tax):
    """What the library page's Chart view draws (the plan's Phase 1 screens): the tree (perspectives, their groups, "Needs
    a place") with counts, and the list of the node picked (`cn`: all, p:<code>, g:<code> or none), variants under their
    KPI. Level and used-by come from the library's derived identity (`ids`, from _kpi_lib_index), never stored. `status` is
    the list's pill: "active" (In use), "retired" (retired KPIs and variants, with the lines they still carry) or "archived"
    (out of the chart, with when and who); the tree counts follow it."""
    idx = _chart_index(db)
    aliases = _chart_aliases(db)
    nodes, kids = idx["nodes"], idx["children"]
    ident, unplaced = {}, []
    for it in ids.values():
        hit = next((nodes[m] for m in (idx["names"].get((it["key"], b)) for b in ("",) + tuple(it["lib_bgs"]))
                    if m in nodes), None)
        if not hit:
            unplaced.append(it)
        elif hit["id"] not in ident or it["n_people"] > ident[hit["id"]]["n_people"]:
            ident[hit["id"]] = it
    status = status if status in ("active", "retired", "archived") else "active"

    def st_of(n):   # a KPI whose every library placement is retired reads as retired too, as it always has
        if n["archived_at"]:
            return "archived"
        if n["retired_at"]:
            return "retired"
        it = ident.get(n["id"])
        return "retired" if (n["level"] == "kpi" and it is not None and not it["active"]) else "active"

    def vs_of(k):
        return sorted((v for v in kids.get(k["id"], []) if v["level"] == "variant"), key=lambda v: v["code"])

    def in_view(g):   # the KPIs and variants of one KPI group that the pill lists: (KPI or None, [variants to show])
        out = []
        for k in sorted((x for x in kids.get(g["id"], []) if x["level"] == "kpi"), key=lambda x: x["code"]):
            vs = vs_of(k)
            if status == "active":
                if st_of(k) == "active":
                    out.append((k, [v for v in vs if st_of(v) == "active"], True))
            else:
                vshow = [v for v in vs if st_of(v) == status]
                if st_of(k) == status or vshow:
                    out.append((k, vshow, st_of(k) == status))
        return out

    def count(g):   # In use counts KPIs; Retired and Archived count KPIs and variants
        return sum((1 if ink else 0) + (0 if status == "active" else len(vshow)) for _k, vshow, ink in in_view(g))
    persps = sorted((n for n in nodes.values() if n["level"] == "persp"), key=lambda n: n["code"])
    tree, n_all = [], 0
    for p in persps:
        grs = [{"id": g["id"], "code": g["code"], "name": g["name"], "n": count(g), "node": g}
               for g in sorted((x for x in kids.get(p["id"], []) if x["level"] == "group"), key=lambda x: x["code"])]
        tree.append({"id": p["id"], "code": p["code"], "name": p["name"], "n": sum(g["n"] for g in grs), "groups": grs})
        n_all += tree[-1]["n"]
    n_ret = n_arc = 0   # the pills' counts, whichever pill is on
    for n in nodes.values():
        if n["level"] in ("kpi", "variant"):
            st_ = st_of(n)
            n_ret += st_ == "retired"
            n_arc += st_ == "archived"
    needs = [it for it in unplaced if it["active"] == (status == "active")] if status != "archived" else []
    # the picked node
    sel, sel_label, sel_sub = cn, "Whole chart", ""
    pick_p = pick_g = None
    if cn.startswith("p:") and cn[2:] in idx["by_code"] and idx["by_code"][cn[2:]]["level"] == "persp":
        pick_p = idx["by_code"][cn[2:]]
    elif cn.startswith("g:") and cn[2:] in idx["by_code"] and idx["by_code"][cn[2:]]["level"] == "group":
        pick_g = idx["by_code"][cn[2:]]
    elif cn != "none":
        sel = "all"
    ql = (q or "").strip().lower()
    arch_names = {}
    if status == "archived":
        for n in nodes.values():
            if n["archived_names"]:
                try:
                    arch_names[n["id"]] = [str(x.get("name_shown") or "") for x in json.loads(n["archived_names"])]
                except (ValueError, TypeError, AttributeError):
                    pass

    def word(it):
        return ("%s %s" % (it["unit"] or "no unit", "· higher is better" if it["method"] == "more"
                           else "· lower is better"))

    def used(it):
        if not it["n_people"]:
            return "Nobody yet"
        lv, wh = it["level"], it["where"]
        if lv == "global":
            tail = "%d BG%s · %d unit%s" % (it["n_bgs"], "" if it["n_bgs"] == 1 else "s", it["n_units"],
                                            "" if it["n_units"] == 1 else "s")
        elif lv == "bg":
            tail = display_bg(wh) if wh else ""
        elif lv == "bu":
            tail = display_company(*wh) if wh else ""
        else:
            tail = tax.get(wh, wh) if wh else ""
        return "%d %s%s" % (it["n_people"], "person" if it["n_people"] == 1 else "people", " · " + tail if tail else "")

    def matches(n):
        if not ql:
            return True
        it = ident.get(n["id"])
        hay = [n["code"], n["name"], n["definition"] or ""] + idx["names_of"].get(n["id"], []) + arch_names.get(n["id"], [])
        if it:
            hay += [it["key"], it["definition"] or ""] + list(it["aliases"])
        return any(ql in (h or "").lower() for h in hay)

    usage = _chart_node_usage(db, idx, aliases) if status != "active" else {}
    who = {}
    if status == "archived":
        uids = [n["archived_by"] for n in nodes.values() if n["archived_by"]]
        if uids:
            who = {r["id"]: r["full_name"] for r in db.execute(
                "SELECT id, full_name FROM users WHERE id IN (%s)" % ",".join("?" * len(set(uids))), list(set(uids)))}

    def row(n, it, parent=None):
        sub = word(it) if it else "Not in the library yet"
        if parent is not None:
            sub = "Variant of %s · %s" % (parent["code"], sub) if it else "Variant of %s" % parent["code"]
        nv = sum(1 for v in kids.get(n["id"], []) if v["level"] == "variant")
        if nv and parent is None:
            sub += " · %d variant%s" % (nv, "" if nv == 1 else "s")
        u = used(it) if it else "No one yet"
        base = ident.get(parent["id"]) if parent is not None else it
        d = {"code": n["code"], "is_var": parent is not None, "name": n["name"],
             "bu_level": bool(it and it["bu_level"]), "sub": sub, "key": it["key"] if it else None,
             "lvl": COA_LEVEL_WORDS.get(it["level"], "") if it else "", "used": u,
             "target": ("BU target, set in the Early Year" if it["bu_level"] else "Per person") if it else "—",
             "retired": False, "open_key": base["key"] if base else None, "node_id": n["id"]}
        if status == "retired":
            lines = usage.get(n["id"], {}).get(cyc["id"], 0) if cyc else 0
            d["chip"] = "Retired " + _chart_day(n["retired_at"]) if n["retired_at"] else "All placements retired"
            d["lines_now"] = ("%d in %s" % (lines, cyc["name"])) if lines else "None"
            d["lines_n"] = lines
            d["sub"] = ("Variant of %s" % parent["code"]) if parent is not None else (
                word(it) if it else "Not in the library yet")
        elif status == "archived":
            par = nodes.get(n["parent_id"]) if n["level"] == "variant" else None
            d["sub"] = ("Variant of %s" % par["code"]) if par else (word(it) if it else "KPI")
            d["arch"] = "%s · %s" % (_myt_date_str(n["archived_at"]) or "", who.get(n["archived_by"]) or "Super admin")
            blocked = "Restore %s first" % par["code"] if par and par["archived_at"] else ""
            d["restore_block"] = blocked
            d["restore"] = _chart_confirm("restore", n)
        return d

    sections, n_k, n_v = [], 0, 0
    if cn == "none" and not (pick_p or pick_g):
        rows = [{"code": "—", "is_var": False, "name": it["name"], "bu_level": bool(it["bu_level"]),
                 "sub": word(it) + ("" if it["perspective"] else " · not tagged"), "key": it["key"],
                 "lvl": COA_LEVEL_WORDS.get(it["level"], ""), "used": used(it),
                 "target": "BU target, set in the Early Year" if it["bu_level"] else "Per person", "retired": False}
                for it in sorted(needs, key=lambda x: x["name"].lower())
                if not ql or ql in it["key"] or any(ql in a.lower() for a in it["aliases"])]
        sel, sel_label, sel_sub = "none", "Needs a place", "Library KPIs with no code yet"
        n_k = len(rows)
        if rows:
            sections.append({"label": "Not in the chart yet", "rows": rows})
    else:
        picked = [p for p in tree if not pick_p or p["id"] == pick_p["id"]]
        for p in picked:
            for g in p["groups"]:
                if pick_g and g["id"] != pick_g["id"]:
                    continue
                rws = []
                for k, vshow, ink in in_view(g["node"]):
                    if status == "active":
                        if not (matches(k) or any(matches(v) for v in vshow)):
                            continue
                        rws.append(row(k, ident.get(k["id"])))
                        n_k += 1
                        for v in vshow:
                            rws.append(row(v, ident.get(v["id"]), parent=k))
                            n_v += 1
                        continue
                    if ink and matches(k):
                        rws.append(row(k, ident.get(k["id"])))
                        n_k += 1
                    for v in vshow:
                        if matches(v):
                            rws.append(row(v, ident.get(v["id"]), parent=k))
                            n_v += 1
                if rws:
                    lab = "%s. %s" % (g["code"], g["name"])
                    if not (pick_p or pick_g):
                        lab = "%s. %s › %s" % (p["code"], p["name"], lab)
                    sections.append({"label": lab, "rows": rws})
        if pick_p:
            sel_label = "%s. %s" % (pick_p["code"], pick_p["name"])
        elif pick_g:
            sel_label = "%s. %s" % (pick_g["code"], pick_g["name"])
        sel_sub = "%d KPI group%s · %d KPI%s, %d variant%s" % (
            len(sections), "" if len(sections) == 1 else "s", n_k, "" if n_k == 1 else "s", n_v,
            "" if n_v == 1 else "s")
    cov = _chart_line_coverage(db, cyc["id"] if cyc else None, idx, aliases)
    return {"tree": tree, "n_all": n_all, "n_none": len(needs), "n_retired": n_ret, "n_archived": n_arc,
            "status": status, "sel": sel, "sel_label": sel_label,
            "sel_sub": sel_sub, "sections": sections, "n_kpis": n_k, "n_variants": n_v, "cov": cov,
            "pick_p": pick_p, "pick_g": pick_g, "empty": not nodes or not any(n["level"] != "persp" for n in nodes.values()),
            "group_opts": [(p["code"], p["name"], [(g["code"], g["name"], g["id"]) for g in p["groups"]]) for p in tree],
            "kpi_opts": [(p["code"] + ". " + p["name"] + " › " + g["code"] + ". " + g["name"],
                          [(k["id"], k["code"], k["name"]) for k in sorted(
                              (x for x in kids.get(g["id"], []) if x["level"] == "kpi" and not x["archived_at"]),
                              key=lambda x: x["code"])])
                         for p in tree for g in p["groups"]
                         if any(x["level"] == "kpi" and not x["archived_at"] for x in kids.get(g["id"], []))]}


def _chart_status_post(db, me, action):
    """Retire, Bring back, Archive and Restore a KPI or a variant (`node_id`), through the library page's POST (the caller has
    checked the flag and the super admin). The server re-checks every rule -- the button's state is never trusted -- and
    writes one activity_log row. Returns the redirect."""
    try:
        nid = int(request.form.get("node_id", ""))
    except (TypeError, ValueError):
        abort(400)
    idx, aliases = _chart_index(db), _chart_aliases(db)
    node = idx["nodes"].get(nid)
    if not node or node["level"] not in ("kpi", "variant"):
        abort(400)
    ids = _chart_lib_ids(db)
    label = "%s %s" % (node["code"], node["name"])
    what = "KPI" if node["level"] == "kpi" else "variant"
    key = _kpi_key(request.form.get("kpi"))
    chart_status = request.form.get("status") if request.form.get("status") in ("retired", "archived") else None

    def back(status=None):
        if key and key in ids and status is None:
            return redirect(url_for("admin_kpi_library", kpi=key, panel="kpi"))
        return redirect(url_for("admin_kpi_library", view="chart", status=status or chart_status))

    def refuse(msg, status=None):
        db.rollback()
        flash(msg, "error")
        return back(status)
    st = _chart_status(node)
    par = idx["nodes"].get(node["parent_id"]) if node["level"] == "variant" else None
    if action == "chart_retire":
        if st == "archived":
            return refuse("%s is archived: restore it first." % label)
        if st == "retired":
            return refuse("%s is already retired." % label)
        vs, ls = _chart_retire(db, idx, aliases, ids, node, me["id"])
        extra = ""
        if node["level"] == "kpi":
            extra = " with %d variant%s and %d placement%s" % (len(vs), "" if len(vs) == 1 else "s", len(ls),
                                                                "" if len(ls) == 1 else "s")
        log_activity(db, me["id"], "pm_kpi_chart", "retired %s %s%s (lines keep the code)" % (what, label, extra), commit=False)
        db.commit()
        flash("Retired %s%s. Nobody can pick it for a new line and Match lines no longer suggests it; the lines that carry %s "
              "keep it and their figures." % (label, extra, node["code"]), "ok")
        return back()
    if action == "chart_bringback":
        if st == "archived":
            return refuse("%s is archived: restore it first." % label)
        if st != "retired":
            return refuse("%s is already in use." % label)
        if par is not None and par["retired_at"]:
            return refuse("Bring back %s first: %s sits under it." % (par["code"], node["code"]))
        nv, nl = _chart_bring_back(db, idx, node, me["id"])
        extra = " and what was retired with it (%d variant%s, %d placement%s)" % (
            nv, "" if nv == 1 else "s", nl, "" if nl == 1 else "s") if node["level"] == "kpi" else ""
        log_activity(db, me["id"], "pm_kpi_chart", "brought back %s %s%s" % (what, label, extra), commit=False)
        db.commit()
        flash("Brought back %s%s." % (label, extra), "ok")
        return back()
    if action == "chart_archive":
        if st == "archived":
            return refuse("%s is already archived." % label)
        why = _chart_archive_block(idx, node, _chart_node_usage(db, idx, aliases), _chart_cycle_names(db), _chart_links_set(db))
        if why:
            return refuse("%s cannot be archived: %s." % (label, why[0].lower() + why[1:] if why.startswith("It ") else why))
        was_active, n_names = _chart_archive(db, idx, aliases, ids, node, me["id"])
        log_activity(db, me["id"], "pm_kpi_chart", "archived %s %s%s (its code is kept and never used again; %d name%s parked)" % (
            what, label, ", retired in the same step" if was_active else "", n_names, "" if n_names == 1 else "s"), commit=False)
        db.commit()
        flash("Archived %s. It left the chart; its code %s is kept and never used again, and Restore brings it back as retired." % (
            label, node["code"]), "ok")
        return back("archived")
    # chart_restore
    if st != "archived":
        return refuse("%s is not archived." % label)
    if par is not None and par["archived_at"]:
        return refuse("Restore %s first: %s sits under it." % (par["code"], node["code"]), "archived")
    put, skipped = _chart_restore(db, node, me["id"])
    log_activity(db, me["id"], "pm_kpi_chart", "restored %s %s as retired (%d name%s back on the map%s)" % (
        what, label, put, "" if put == 1 else "s", ", %d skipped: another KPI holds them" % skipped if skipped else ""),
        commit=False)
    db.commit()
    flash("Restored %s as retired, with %d name%s back on the map.%s" % (
        label, put, "" if put == 1 else "s",
        " %d name%s skipped because another KPI holds %s now." % (skipped, "" if skipped == 1 else "s",
                                                                  "it" if skipped == 1 else "them") if skipped else ""), "ok")
    return back("retired")


def _chart_post(db, me, action):
    """The Chart's super-admin writes, through the library page's POST (the caller has checked the flag and the super
    admin). Each is double-confirmed in the page, refuses a blank or unknown value, and writes the activity log."""
    def back(**kw):
        return redirect(url_for("admin_kpi_library", view="chart", **kw))

    def node_of(field, level):
        try:
            nid = int(request.form.get(field, ""))
        except (TypeError, ValueError):
            abort(400)
        n = db.execute("SELECT * FROM kpi_chart WHERE id=?", (nid,)).fetchone()
        if not n or n["level"] != level:
            abort(400)
        return n

    def new_name(field, what):
        nm = _chart_clean_name(request.form.get(field))
        if not nm:
            flash("Type the %s." % what, "error")
        elif len(nm) > COA_NAME_MAX:
            flash("Keep the %s to %d characters." % (what, COA_NAME_MAX), "error")
        else:
            return nm
        return None

    def taken(parent_id, level, nm, own_id=0):
        return db.execute("SELECT 1 FROM kpi_chart WHERE parent_id=? AND level=? AND LOWER(name)=? AND id!=? AND "
                          "retired_at IS NULL", (parent_id, level, nm.lower(), own_id)).fetchone()

    if action in ("chart_retire", "chart_bringback", "chart_archive", "chart_restore"):
        return _chart_status_post(db, me, action)
    if action == "chart_seed":
        c = _chart_seed(db, me["id"])
        left = c["untagged"] + c["no_group"] + c["full"]
        msg = "%d KPI group%s, %d KPI%s and %d name%s added to the chart" % (
            c["groups"], "" if c["groups"] == 1 else "s", c["kpis"], "" if c["kpis"] == 1 else "s", c["names"],
            "" if c["names"] == 1 else "s")
        if left:
            msg += "; %d left in Needs a place (%d with no perspective, %d with no group%s)" % (
                left, c["untagged"], c["no_group"], ", %d where a level was full" % c["full"] if c["full"] else "")
        log_activity(db, me["id"], "pm_kpi_chart", "seeded from the library: " + msg, commit=False)
        db.commit()
        flash("Seeded: %s." % msg, "ok")
        return back()
    if action == "chart_group_add":
        p = node_of("parent_id", "persp")
        nm = new_name("group_name", "name of the KPI group")
        if not nm:
            return back()
        if taken(p["id"], "group", nm):
            flash("%s %s already has a KPI group called '%s'." % (p["code"], p["name"], nm), "error")
            return back()
        try:
            _gid, code = _chart_add_node(db, "group", p["id"], nm, me["id"])
        except ValueError as e:
            flash(str(e), "error")
            return back()
        log_activity(db, me["id"], "pm_kpi_chart", "added KPI group %s %s under %s %s" % (code, nm, p["code"], p["name"]))
        flash("Added KPI group %s. %s." % (code, nm), "ok")
        return back(cn="g:" + code)
    if action in ("chart_group_rename", "chart_kpi_rename"):
        is_group = action == "chart_group_rename"
        n = node_of("node_id", "group" if is_group else "kpi")
        if n["archived_at"]:
            flash("%s %s is archived: restore it first." % (n["code"], n["name"]), "error")
            return back()
        nm = new_name("group_name" if is_group else "node_name", "new name")
        if not nm:
            return back()
        if nm == n["name"]:
            flash("%s %s already has that name." % (n["code"], n["name"]), "error")
            return back()
        if taken(n["parent_id"], n["level"], nm, n["id"]):
            flash("%s already has a %s called '%s'." % ("That perspective" if is_group else "That KPI group",
                                                        "KPI group" if is_group else "KPI", nm), "error")
            return back()
        db.execute("UPDATE kpi_chart SET name=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
                   (nm, me["id"], n["id"]))
        log_activity(db, me["id"], "pm_kpi_chart", "renamed %s %s: '%s' to '%s' (the code stays)" % (
            "KPI group" if is_group else "KPI", n["code"], n["name"], nm))
        flash("%s %s is now '%s'. Its code stays %s." % ("KPI group" if is_group else "KPI", n["code"], nm, n["code"]), "ok")
        return back(cn=("g:" + n["code"]) if is_group else "all")
    # ---- the KPI panel's actions (piece A2): each names its KPI by the library identity's key (`kpi`) ----
    def identity():
        ix = _kpi_lib_index(db, org_bgs(db))["ids"]
        it = ix.get(_kpi_key(request.form.get("kpi")))
        if not it:
            abort(400)
        return it, ix

    def back_kpi(it, panel="kpi"):
        return redirect(url_for("admin_kpi_library", kpi=it["key"], panel=panel))

    if action == "chart_move":
        it, _ix = identity()
        idx = _chart_index(db)
        node = _chart_node_of_identity(idx, _chart_aliases(db), it)
        if not node or node["level"] != "kpi":
            flash("%s has no code of its own to move: give it a place first." % it["name"], "error")
            return back_kpi(it)
        try:
            grp = idx["nodes"].get(int(request.form.get("to_group", "")))
        except ValueError:
            abort(400)
        if not grp or grp["level"] != "group":
            abort(400)
        p0, g0 = _chart_place_of(idx, node)
        try:
            done = _chart_move_kpi(db, node, grp, me["id"])
        except ValueError as e:
            db.rollback()
            flash(str(e), "error")
            return back_kpi(it)
        p1 = idx["nodes"].get(grp["parent_id"])
        log_activity(db, me["id"], "pm_kpi_chart", "moved KPI %s %s from %s to %s %s: %s (the old codes are never used again)" % (
            node["code"], node["name"], ("%s %s" % (g0["code"], g0["name"])) if g0 else "no group", grp["code"], grp["name"],
            ", ".join("%s to %s" % (o, n) for o, n in done)))
        flash("%s now sits under %s. %s %s. Its code is %s (it was %s); lines keep their words and history." % (
            node["name"], p1["code"] if p1 else "", grp["code"], grp["name"], done[0][1], done[0][0]), "ok")
        return back_kpi(it)
    if action == "chart_place":
        it, ix = identity()
        idx, aliases = _chart_index(db), _chart_aliases(db)
        have = _chart_node_of_identity(idx, aliases, it)
        if have:
            flash("%s already has the code %s." % (it["name"], have["code"]), "error")
            return back_kpi(it)
        plan, err = _chart_place_resolve(db, request.form, idx)
        if err or not plan:
            flash(err or "Choose the perspective and the KPI group.", "error")
            return back_kpi(it)
        try:
            nid, code = _chart_place_apply(db, plan, it["name"], it["definition"], me["id"])
        except ValueError as e:
            db.rollback()
            flash(str(e), "error")
            return back_kpi(it)
        _chart_map_name(db, nid, it["name"], "", "add", me["id"])
        _chart_map_name(db, nid, it["key"], "", "add", me["id"])
        _chart_map_aliases(db, nid, it["key"], _chart_keys_of(aliases), ix, me["id"], source="add")
        gname = plan["new_group"] or plan["group"]["name"]
        log_activity(db, me["id"], "pm_kpi_chart", "code %s given to KPI %s, under %s %s" % (
            code, it["name"], code[:2], gname))
        flash("%s now has the code %s." % (it["name"], code), "ok")
        return back_kpi(it)
    if action == "chart_variant_add":
        it, _ix = identity()
        idx, aliases = _chart_index(db), _chart_aliases(db)
        node = _chart_node_of_identity(idx, aliases, it)
        if not node or node["level"] != "kpi":
            flash("Give %s a place in the chart before it takes variants." % it["name"], "error")
            return back_kpi(it)
        if node["retired_at"]:
            flash("%s is retired: bring it back first. A retired KPI takes no new variant." % node["code"], "error")
            return back_kpi(it)
        if any(r["active"] and r["bu_level"] for r in it["rows"]):
            flash("%s is a BU-level KPI: its variants are made in BU KPI setup, one per unit, and they read as this code "
                  "once matched." % it["name"], "error")
            return back_kpi(it)
        q = _chart_clean_name(request.form.get("qualifier"))
        full = "%s: %s" % (node["name"], q)
        clash = next((v for v in idx["children"].get(node["id"], []) if v["level"] == "variant" and not v["archived_at"]
                      and (v["qualifier"] or "").lower() == q.lower()), None) if q else None
        named = idx["nodes"].get(idx["names"].get((_kpi_key(full), ""))) if q else None
        err = None
        if not q:
            err = "Type what makes it a variant."
        elif len(q) > COA_QUALIFIER_MAX:
            err = "Keep what makes it a variant to %d characters." % COA_QUALIFIER_MAX
        elif len(full) > COA_NAME_MAX:
            err = "The whole name, '%s', runs past %d characters: shorten what makes it a variant." % (full, COA_NAME_MAX)
        elif clash or named:
            err = "%s already has a variant called '%s' (%s)." % (node["name"], q, (clash or named)["code"])
        if err:
            flash(err, "error")
            return back_kpi(it, "variant")
        cyc = _kpi_usage_cycle(db)
        eids = list(dict.fromkeys(e.strip() for e in (request.form.get("move_eids") or "").replace("\n", ",").split(",")
                                  if e.strip()))
        moving = []
        if eids:
            found = _eid_resolve_many(db, eids)
            hold = {}
            for ln, nd in _chart_cycle_lines(db, cyc["id"] if cyc else None, idx, aliases):
                if nd and nd["id"] == node["id"]:
                    hold.setdefault(ln["subject_id"], []).append(ln["id"])
            bad = [e for e in eids if e not in found or found[e][0]["id"] not in hold]
            if bad:
                flash("Only people who hold a line of %s%s can be moved onto the variant: %s %s not one of them." % (
                    node["name"], " on " + cyc["name"] if cyc else "", ", ".join(bad), "is" if len(bad) == 1 else "are"),
                    "error")
                return back_kpi(it, "variant")
            moving = list(dict.fromkeys(lid for e in eids for lid in hold[found[e][0]["id"]]))
        try:
            vid, code = _chart_add_node(db, "variant", node["id"], full, me["id"], qualifier=q)
        except ValueError as e:
            db.rollback()
            flash(str(e), "error")
            return back_kpi(it, "variant")
        _chart_map_name(db, vid, full, "", "variant", me["id"])
        for i in range(0, len(moving), 500):   # ONLY the override: no name, target or result is touched
            part = moving[i:i + 500]
            db.execute("UPDATE pm_kpi_targets SET chart_node_id=? WHERE cycle_id=? AND id IN (%s)" % ",".join("?" * len(part)),
                       [vid, cyc["id"]] + part)
        log_activity(db, me["id"], "pm_kpi_chart", "variant %s added: %s%s" % (
            code, full, " (%d line%s moved onto it)" % (len(moving), "" if len(moving) == 1 else "s") if moving else ""))
        flash("Added variant %s, '%s'.%s" % (code, full, " %d line%s moved onto it; their names, targets and results are "
                                             "as they were." % (len(moving), "" if len(moving) == 1 else "s") if moving else ""),
              "ok")
        return back_kpi(it)
    if action in ("chart_link_save", "chart_link_remove"):   # a KPI's (or variant's) data link (piece C, board 6)
        it, _ix = identity()
        idx, aliases = _chart_index(db), _chart_aliases(db)
        base = _chart_node_of_identity(idx, aliases, it)
        if not base:
            flash("Give %s a place in the chart before it takes a data link." % it["name"], "error")
            return back_kpi(it)
        kpi = idx["nodes"].get(base["parent_id"], base) if base["level"] == "variant" else base
        fam = {base["id"], kpi["id"]} | {v["id"] for v in idx["children"].get(kpi["id"], []) if v["level"] == "variant"}
        try:
            nid = int(request.form.get("node_id", ""))
        except (TypeError, ValueError):
            abort(400)
        if nid not in fam:
            abort(400)
        nd = idx["nodes"][nid]
        if action == "chart_link_save":
            ok, msg = _coa_link_save(db, me, nd, idx, aliases, request.form)
        else:
            ok, msg = _coa_link_remove(db, me, nd)
        if ok:
            db.commit()
        else:
            db.rollback()
        flash(msg, "ok" if ok else "error")
        if nid == base["id"]:
            return back_kpi(it)
        return redirect(url_for("admin_kpi_library", kpi=it["key"], panel="link", link=nid))
    abort(400)


@app.route("/admin/performance/library", methods=["GET", "POST"])
@admin_required
def admin_kpi_library():
    """Admin: curate the reusable KPI Library, keyed on (business_group,
    department, tier_n). Scoped by admin_bg_of() exactly like
    admin_performance_config(): a BGHR admin only sees/edits their own BG,
    super admin sees every BG in the org master. The library holds what a KPI
    IS (no numbers, Chris 2026-11-02), so a row needs no scoring mechanism."""
    db = get_db()
    me = current_user()
    scoped_bg = admin_bg_of(me)
    bgs = [scoped_bg] if scoped_bg else org_bgs(db)

    if request.method == "POST":
        if request.form.get("action", "").startswith("chart_") and not coa_on():
            abort(404)   # the Chart of KPI is dark where ONEHR_COA isn't 1
        if not is_super(me):   # the super admin edits the libraries; BG and unit admins propose (Chris, 2026-10-18)
            abort(403)
        action = request.form.get("action", "")
        if action.startswith("chart_"):
            return _chart_post(db, me, action)

        if action in ("add", "update"):
            target_bg = (request.form.get("business_group", "") or "").strip()
            if target_bg not in bgs:
                abort(403)
            # Every scope dimension takes a sentinel for "any": '*' for the text
            # ones, 0 for the tier. A row scoped to nothing is the BG-wide
            # fallback everyone in the BG can draw on.
            company = (request.form.get("company", "") or "").strip() or "*"
            department = (request.form.get("department", "") or "").strip() or "*"
            job_grade = (request.form.get("job_grade", "") or "").strip() or "*"
            # Multi-value scope + the BU-level mark. Blank leaves the row on the
            # original single-value path, so nothing about existing rows changes.
            # ticked from lists (2026-10-19): every box posts one value; an older form's comma-joined text still reads
            job_grades = ",".join(sorted(_pm_csv_set(",".join(request.form.getlist("job_grades")))))
            departments = ",".join(sorted(_pm_csv_set(",".join(request.form.getlist("departments")))))
            _lib_old = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (_form_int("library_id"),)).fetchone() \
                if action == "update" else None
            _known = {k.casefold() for k, _u in kpi_library_lists(db, [target_bg])["depts"].get(target_bg, [])}
            _unknown = sorted(_pm_csv_set(departments) - _known - _pm_csv_set(_lib_old["departments"] if _lib_old
                                                                               else ""))
            if _unknown:
                flash("Pick departments from the list: %s %s no department in %s." % (
                    ", ".join(_unknown), "is" if len(_unknown) == 1 else "are", display_bg(target_bg)), "error")
                return redirect(url_for("admin_kpi_library"))
            _mode_in = request.form.get("department_mode") or "any"
            dept_mode = "exclude" if _mode_in == "exclude" else "include"
            if _mode_in == "any":
                # "All departments" is the absence of a list, not a list plus a
                # mode -- otherwise switching back to All would silently keep
                # scoping the rule by whatever was typed before.
                departments = ""
            bu_level = 1 if request.form.get("bu_level") else 0
            # Named people (Chart of KPI, flag on; board 4b): "Named people" replaces the scope with a list of active people
            # in this group, so the row's own scope is stored as "any" and never read (pm_library_matches_person)
            people_uids, chart_place = None, None
            if coa_on() and request.form.get("mode") in ("scope", "people"):
                people_uids, _perr = _pm_lib_people_parse(db, request.form, target_bg, bu_level)
                if _perr:
                    flash(_perr, "error")
                    return redirect(url_for("admin_kpi_library", panel="add" if action == "add" else "kpi",
                                            addbg=target_bg, kpi=_kpi_key(_lib_old["kpi_name"]) if _lib_old else None))
                if request.form.get("mode") == "people":
                    company = department = job_grade = "*"
                    job_grades = departments = ""
                    dept_mode = "include"
            if coa_on() and action == "add":   # a name whose code is retired is not reused: bring that code back first
                _cidx = _chart_index(db)
                _chave = _chart_lookup(_cidx, _chart_aliases(db), _kpi_key(request.form.get("kpi_name")), target_bg)
                if _chave and _chave["retired_at"]:
                    flash("%s is retired: bring it back first. A retired code is not reused for a new KPI." % _chave["code"],
                          "error")
                    return redirect(url_for("admin_kpi_library", panel="add", addbg=target_bg))
            if coa_on() and action == "add":   # its place in the chart: read now, written after the row is
                chart_place, _cperr = _chart_place_resolve(db, request.form)
                if _cperr:
                    flash(_cperr, "error")
                    return redirect(url_for("admin_kpi_library", panel="add", addbg=target_bg))
            try:
                tier_n = int((request.form.get("tier_n", "") or "").strip())
            except ValueError:
                tier_n = 0
            if tier_n not in (0, 1, 2, 3, 4):
                flash("Choose a tier band (1–4), or Any tier.", "error")
                return redirect(url_for("admin_kpi_library"))
            scope_msg = _pm_library_scope_msg(target_bg, company, department,
                                              tier_n, job_grade)
            kpi_name = (request.form.get("kpi_name", "") or "").strip()
            if not kpi_name:
                flash("KPI name is required.", "error")
                return redirect(url_for("admin_kpi_library"))
            method = (request.form.get("method", "") or "").strip().lower()
            if method not in ("more", "less"):
                flash("Method must be More or Less.", "error")
                return redirect(url_for("admin_kpi_library"))
            # The library holds no numbers (Chris, 2026-11-02): this save never reads or writes a rate, threshold,
            # target, multiple, excellence, weight or spread. test_kpi_library_no_numbers lints it.
            perspective = (request.form.get("perspective") or "").strip() or None
            if perspective and perspective not in PM_PERSPECTIVES:
                abort(400)
            category, _cnew, _cerr = _admin_list_choice(request.form, "category", kpi_library_lists(db, bgs)["cats"],
                                                        _lib_old["category"] if _lib_old else None, "family · group",
                                                        120)
            if _cerr:
                flash(_cerr, "error")
                return redirect(url_for("admin_kpi_library"))
            if chart_place and not category:   # the place stands in for "Family · group", so Where used files it there too
                category = "%s · %s" % (chart_place["persp"]["name"],
                                        chart_place["new_group"] or chart_place["group"]["name"])
            description = (request.form.get("description", "") or "").strip() or None
            if kpi_def_figure_msg(description):
                flash(kpi_def_figure_msg(description), "error")
                return redirect(url_for("admin_kpi_library"))
            unit = kpi_unit_normalise(request.form.get("unit"))

            if action == "add":
                try:
                    _cur = db.execute(
                        "INSERT INTO pm_kpi_library(business_group, company, department, "
                        "tier_n, job_grade, kpi_name, category, description, unit, method, "
                        "created_by, bu_level, job_grades, departments, department_mode, perspective) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (target_bg, company, department, tier_n, job_grade, kpi_name, category,
                         description, unit, method,
                         me["id"], bu_level, job_grades, departments, dept_mode, perspective))
                    if people_uids:
                        _pm_lib_people_set(db, _cur.lastrowid, people_uids, me["id"])
                    db.commit()
                except sqlite3.IntegrityError:
                    flash(f"A KPI named '{kpi_name}' already exists for {scope_msg}.", "error")
                    return redirect(url_for("admin_kpi_library"))
                log_activity(db, me["id"], "pm_kpi_library",
                             f"add: {scope_msg} / {kpi_name}" + (f" (named people: {len(people_uids)})" if people_uids else ""))
                if chart_place:
                    _chart_after_add(db, me, chart_place, kpi_name, description, target_bg)
                flash(f"Added '{kpi_name}' to the library.", "ok")
                return redirect(url_for("admin_kpi_library", kpi=_kpi_key(kpi_name), panel="kpi"))

            # update
            try:
                lib_id = int((request.form.get("library_id", "") or "").strip())
            except ValueError:
                abort(400)
            row = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (lib_id,)).fetchone()
            if not row or row["business_group"] not in bgs or row["business_group"] != target_bg:
                abort(403)
            if bu_level and people_uids is None:   # no mode posted (flag-off form): named people must not outlive the flag
                try:
                    _named = db.execute("SELECT 1 FROM pm_kpi_library_people WHERE library_id=? LIMIT 1",
                                        (lib_id,)).fetchone()
                except sqlite3.OperationalError:
                    _named = None
                if _named:
                    flash("'%s' names people, so it can't be a business-unit level KPI: choose Units, departments and "
                          "grades for it first." % row["kpi_name"], "error")
                    return redirect(url_for("admin_kpi_library", panel="kpi", addbg=target_bg,
                                            kpi=_kpi_key(row["kpi_name"])))
            try:
                db.execute(
                    "UPDATE pm_kpi_library SET company=?, department=?, tier_n=?, job_grade=?, "
                    "kpi_name=?, category=?, description=?, unit=?, method=?, bu_level=?, job_grades=?, "
                    "departments=?, department_mode=?, perspective=?, updated_at=datetime('now'), "
                    "updated_by=? WHERE id=?",
                    (company, department, tier_n, job_grade, kpi_name, category, description,
                     unit, method, bu_level, job_grades,
                     departments, dept_mode, perspective, me["id"], lib_id))
                if people_uids is not None:
                    _pm_lib_people_set(db, lib_id, people_uids, me["id"])
                db.commit()
            except sqlite3.IntegrityError:
                flash(f"Another library KPI already uses {scope_msg} / '{kpi_name}'.", "error")
                return redirect(url_for("admin_kpi_library"))
            log_activity(db, me["id"], "pm_kpi_library",
                         f"update: {scope_msg} / {kpi_name}" + (f" (named people: {len(people_uids)})" if people_uids else ""))
            flash(f"Updated '{kpi_name}'.", "ok")
            return redirect(url_for("admin_kpi_library", kpi=_kpi_key(kpi_name), panel="kpi"))

        if action in ("toggle_active", "delete"):
            try:
                lib_id = int((request.form.get("library_id", "") or "").strip())
            except ValueError:
                abort(400)
            row = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (lib_id,)).fetchone()
            if not row or row["business_group"] not in bgs:
                abort(403)
            if action == "toggle_active":
                db.execute(
                    "UPDATE pm_kpi_library SET active = 1 - active, "
                    "updated_at=datetime('now'), updated_by=? WHERE id=?", (me["id"], lib_id))
                db.commit()
                log_activity(db, me["id"], "pm_kpi_library",
                             f"{'deactivate' if row['active'] else 'activate'}: "
                             f"{row['business_group']} / {row['kpi_name']}")
                flash(f"'{row['kpi_name']}' "
                      f"{'deactivated' if row['active'] else 'reactivated'}.", "ok")
            else:
                db.execute("DELETE FROM pm_kpi_library_people WHERE library_id=?", (lib_id,))
                db.execute("DELETE FROM pm_kpi_library WHERE id=?", (lib_id,))
                db.commit()
                log_activity(db, me["id"], "pm_kpi_library",
                             f"delete: {row['business_group']} / {row['kpi_name']}")
                flash(f"'{row['kpi_name']}' removed from the library.", "ok")
            return redirect(url_for("admin_kpi_library"))

        abort(400)

    # ----- GET: the tree (2026-10-18, the libraries canvas boards 1-2) -----
    configs = {r["business_group"]: r for r in db.execute("SELECT * FROM pm_bg_config") if r["business_group"] in bgs}
    idx = _kpi_lib_index(db, bgs)
    ids = idx["ids"]
    status = "retired" if request.args.get("status") == "retired" else "active"
    if request.args.get("status") == "archived" and coa_on() and is_super(me) and not scoped_bg \
            and request.args.get("view") == "chart":
        status = "archived"   # the Chart's third pill (retire and archive); the "Where used" view only has two
    show_spec = request.args.get("spec") == "1"
    node = request.args.get("node") or "global"
    q = (request.args.get("q") or "").strip()
    persp = request.args.get("persp") or ""
    fam = request.args.get("fam") or ""
    tax = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}

    def on_tab(it, active):   # the status tab alone
        return it["active"] if active else not it["active"]

    def keep(it):   # what the tree counts: the status tab and the Specialised filter
        return on_tab(it, status == "active") and (show_spec or not it["specialised"])
    shown = [it for it in ids.values() if keep(it)]

    def riders(active):
        """The variants that ride under a root the list shows on that status tab (2026-11-06): the status tab applies, the
        Specialised filter does not (a BU variant has 1-2 holders and would hide), so a shown root brings all its variants.
        A variant whose root is not shown keeps the filter. {root key: [variant identity]}."""
        root_keys = {it["key"] for it in ids.values() if on_tab(it, active) and (show_spec or not it["specialised"])}
        out = {}
        for it in ids.values():
            rk_ = _kpi_root_key(it, ids, idx["alias"])
            if on_tab(it, active) and rk_ and rk_ != it["key"] and rk_ in root_keys:
                out.setdefault(rk_, []).append(it)
        return out
    kids = riders(status == "active")
    child_keys = {c["key"] for v_ in kids.values() for c in v_}
    shown = [it for it in shown if it["key"] not in child_keys]
    for it in shown:
        it["variants"] = sorted(kids.get(it["key"], []), key=lambda c: c["name"].lower())
    counts = {}
    for it in shown:
        nd = _kpi_node_of(it)
        counts[nd] = counts.get(nd, 0) + 1
        if nd.startswith("bu:"):
            b = nd[3:].split("|", 1)[0]
            counts["bg:" + b] = counts.get("bg:" + b, 0) + 1
        if it["spec"]:
            counts["sp:" + it["spec"]] = counts.get("sp:" + it["spec"], 0) + 1
    tree_bgs = [{"bg": b, "n": counts.get("bg:" + b, 0),
                 "units": sorted([(k.split("|", 1)[1], v) for k, v in counts.items()
                                  if k.startswith("bu:%s|" % b)], key=lambda x: -x[1])} for b in bgs]
    fams = sorted([(k[3:], v) for k, v in counts.items() if k.startswith("jf:")], key=lambda x: -x[1])
    tree_fams = [{"code": c, "name": tax.get(c, c), "n": v,
                  "specs": sorted([(k[3:], tax.get(k[3:], k[3:]), n_) for k, n_ in counts.items()
                                   if k.startswith("sp:%s-" % c)], key=lambda x: -x[2])} for c, v in fams]

    def in_node(it):
        nd = _kpi_node_of(it)
        if node.startswith("bg:"):
            return nd == node or nd.startswith("bu:%s|" % node[3:])
        if node.startswith("sp:"):
            return it["spec"] == node[3:]
        return nd == node
    at_node = [it for it in shown if in_node(it)]
    balance = {p_: sum(1 for it in at_node if it["perspective"] == p_) for p_ in PM_PERSPECTIVES}
    balance["none"] = sum(1 for it in at_node if not it["perspective"])
    ql = q.lower()
    def _match(it):
        return ((not ql or ql in it["key"] or ql in (it["definition"] or "").lower()
                 or any(ql in _kpi_key(x["kpi_name"]) for x in it["rows"]))
                and (not persp or (it["perspective"] or "none") == persp) and (not fam or it["family"] == fam))
    # judged on the parent or any of its variants: one that matches brings the parent and all its variants
    rows = [it for it in at_node if _match(it) or any(_match(v_) for v_ in it["variants"])]
    n_variants = sum(len(it["variants"]) for it in at_node)
    rows.sort(key=lambda it: (it["family"] == "Not grouped", it["family"].lower(), it["group"].lower(),
                              -it["n_people"], it["name"].lower()))
    groups = []
    for it in rows:
        g = (it["family"], it["group"])
        if not groups or groups[-1][0] != g:
            groups.append((g, []))
        groups[-1][1].append(it)
    spec_riding = {c["key"] for v_ in riders(True).values() for c in v_}   # the Specialised count leaves out a variant that rides
    families = sorted({it["family"] for it in ids.values()})
    if node == "global":
        node_label, node_sub = "Global", "Used in two or more business groups"
    elif node.startswith("bg:"):
        node_label, node_sub = display_bg(node[3:]), "Used in one business group, across its units"
    elif node.startswith("bu:"):
        b_, c_ = (node[3:].split("|", 1) + [""])[:2]
        node_label, node_sub = display_company(b_, c_) or c_, "Used in one business unit"
    elif node.startswith("sp:"):
        node_label, node_sub = tax.get(node[3:], node[3:]), "A specialisation of its job family"
    else:
        node_label, node_sub = tax.get(node[3:], node[3:]), "Mostly held by one job family"
    # a KPI opened in the side panel (?kpi=<key>): its placements, who uses it, its trail
    opened = ids.get(request.args.get("kpi") or "")
    history = []
    opened_vars, opened_root = [], None
    if opened:
        ork_ = _kpi_root_key(opened, ids, idx["alias"])
        opened_vars = sorted([x for x in ids.values() if x["key"] != opened["key"]
                              and _kpi_root_key(x, ids, idx["alias"]) == opened["key"]], key=lambda x: x["name"].lower())
        if ork_ and ork_ != opened["key"]:
            opened_root = ids.get(ork_)
        history = [dict(r) for r in db.execute(
            "SELECT a.created_at, a.detail, u.full_name AS who FROM activity_log a LEFT JOIN users u ON u.id=a.user_id "
            "WHERE a.action IN ('pm_kpi_library'%s) AND LOWER(a.detail) LIKE ? ORDER BY a.id DESC LIMIT 8"
            % (", 'pm_kpi_chart'" if coa_on() else ""),
            ("%" + opened["key"] + "%",))]
    add_bg = request.args.get("addbg") if request.args.get("addbg") in bgs else (bgs[0] if len(bgs) == 1 else "")
    # Match lines' "New KPI" opens Add a KPI with the name already in (the Chart of KPI, flag on, the super admin)
    add_name = (_chart_clean_name(request.args.get("kpi_name"))[:COA_NAME_MAX]
                if (coa_on() and is_super(me) and not scoped_bg) else "")
    lib_lists = kpi_library_lists(db, bgs)
    _omap = org_map(db)
    org_companies = {b: _omap.get(b, []) for b in bgs}
    # the Chart of KPI (ONEHR_COA=1, the super admin): a switch on the tree; "Where used" stays the default view
    coa_switch = coa_on() and is_super(me) and not scoped_bg
    chart_view = coa_switch and request.args.get("view") == "chart"
    cn = request.args.get("cn") or "all"
    chart = _chart_view(db, ids, idx["cycle"], cn, q, status, tax) if chart_view else None
    # the KPI panel's chart sections, the Add / Edit forms' place and named people (flag on, super admin)
    coa_place, coa_panel, lib_people, coa_links = None, None, {}, None
    if coa_switch:
        coa_place = _chart_place_opts(db)
        if opened:
            coa_panel = _chart_kpi_panel(db, opened, idx["cycle"])
            lib_people = _pm_lib_people_detail(db, [r["id"] for r in opened["rows"]])
            if coa_panel.get("node"):
                coa_links = _coa_links_view(db, coa_panel, idx["cycle"], request.args.get("link", type=int))
    return render_template("admin_kpi_library.html", bgs=bgs, configs=configs, tiers=default_tiers(),
                           coa_switch=coa_switch, chart_view=chart_view, chart=chart, cn=chart["sel"] if chart else cn,
                           coa_place=coa_place, coa_panel=coa_panel, lib_people=lib_people, coa_links=coa_links,
                           link_test=request.args.get("link_test", type=int) if coa_links else None,
                           org_companies=org_companies, label_names=PM_LABEL_NAMES, perspectives=PM_PERSPECTIVES,
                           tree_bgs=tree_bgs, tree_fams=tree_fams, n_global=counts.get("global", 0), node=node,
                           node_label=node_label, node_sub=node_sub, groups=groups, n_rows=len(rows),
                           n_node=len(at_node), n_variants=n_variants,
                           n_lines=sum(it["lines"] + sum(v_["lines"] for v_ in it["variants"]) for it in at_node), balance=balance,
                           opened_vars=opened_vars, opened_root=opened_root,
                           families=families, q=q, persp=persp, fam=fam, status=status, show_spec=show_spec,
                           opened=opened, history=history, add_bg=add_bg, add_name=add_name, usage_cycle=idx["cycle"],
                           n_retired=sum(1 for it in ids.values() if not it["active"]),
                           n_merges=len(_kpi_merge_suggestions(db, bgs)), can_edit=is_super(me),
                           n_requests=db.execute("SELECT COUNT(*) FROM pm_library_requests WHERE status='waiting'"
                                                 + ("" if is_super(me) else " AND created_by=%d" % me["id"])
                                                 ).fetchone()[0],
                           my_units=sorted(admin_companies_of(me)) or org_companies.get(scoped_bg or "", []),
                           fam_opts=[(r[0], r[1]) for r in db.execute(
                               "SELECT code, name FROM ja_taxonomy WHERE level='sub' ORDER BY name")],
                           lib_lists=lib_lists,
                           n_spec=sum(1 for it in ids.values() if it["specialised"] and it["active"] and it["key"] not in spec_riding))


# ---- the library's merge queue (2026-10-18, the libraries canvas board 3) -------------------------------------------
KPI_SCOPE_WORDS = ("business unit", "plant", "company", "group", "branch", "site", "factory", "bu", "unit")


def _kpi_dupe_key(name):
    """Two names that differ only in an abbreviation in brackets, punctuation or spacing read the same."""
    t = re.sub(r"\([^)]*\)", " ", (name or "").lower())
    return " ".join(re.findall(r"[a-z0-9]+", t))


def _kpi_merge_suggestions(db, bgs):
    """The merges the library suggests, per business group, from its in-use names (2026-10-18; the library study):
      * scope: one measure stored at several scopes ("Plant gross profit (GP)", "Company gross profit (GP)", "Gross
        profit (GP)") -> the plain name, grouped as one KPI with each row kept;
      * variant: "KPI: qualifier" names -> the KPI, the qualifier moving into each line's Focus (2+ variants, or one
        whose KPI exists);
      * dupe: names the same but for a bracketed abbreviation or punctuation -> the super admin chooses which.
    Not a suggestion once kept apart (pm_kpi_merge_apart) or already merged. [dict], by group then kind then size."""
    if not bgs:
        return []
    ph = ",".join("?" * len(bgs))
    apart = {(r[0], r[1]) for r in db.execute("SELECT business_group, sig FROM pm_kpi_merge_apart WHERE business_group "
                                              "IN (%s)" % ph, bgs)}
    aliased = {(r[0], r[1]) for r in db.execute("SELECT business_group, alias_key FROM pm_kpi_aliases WHERE "
                                                "business_group IN (%s)" % ph, bgs)}
    names = {}
    for r in db.execute("SELECT business_group, kpi_name, bu_level FROM pm_kpi_library WHERE active=1 AND "
                        "business_group IN (%s)" % ph, bgs):
        if (r[0], _kpi_key(r[1])) in aliased:
            continue
        names.setdefault(r[0], {})[_kpi_key(r[1])] = (r[1], r[2])
    out = []
    for bg, nm in names.items():
        # one measure, several scopes
        base = {}
        for k, (n, bu) in nm.items():
            word = next((w for w in KPI_SCOPE_WORDS if k.startswith(w + " ") and len(k) > len(w) + 3), None)
            b = k[len(word) + 1:] if word else k
            base.setdefault(b, []).append((n, word, bu))
        for b, grp in base.items():
            if len(grp) < 2 or not any(w for _n, w, _bu in grp):
                continue
            plain = next((n for n, w, _bu in grp if not w), None)
            into = plain or (b[:1].upper() + b[1:])
            out.append({"bg": bg, "kind": "scope", "names": sorted(n for n, _w, _bu in grp), "into": into,
                        "scopes": sorted({(w or "the person's own") for _n, w, _bu in grp}),
                        "bu_mixed": len({bu for _n, _w, bu in grp}) > 1})
        # a variant of a KPI
        par = {}
        for k, (n, _bu) in nm.items():
            m = re.match(r"^(.+?)\s*:\s+(.+)$", n)
            if m and len(m.group(1)) > 3:
                par.setdefault(_kpi_key(m.group(1)), []).append((n, m.group(1).strip(), m.group(2).strip()))
        for pk, grp in par.items():
            if len(grp) < 2 and pk not in nm:
                continue
            into = nm[pk][0] if pk in nm else grp[0][1]
            out.append({"bg": bg, "kind": "variant", "names": sorted(n for n, _p, _q in grp), "into": into,
                        "focus": sorted(q for _n, _p, q in grp), "parent_exists": pk in nm})
        # near-duplicate wording
        dk = {}
        for k, (n, _bu) in nm.items():
            dk.setdefault(_kpi_dupe_key(n), []).append(n)
        for d, grp in dk.items():
            if len(grp) >= 2 and d:
                out.append({"bg": bg, "kind": "dupe", "names": sorted(grp), "into": None})
    for x in out:
        x["sig"] = "|".join(sorted(_kpi_key(n) for n in x["names"]))
    out = [x for x in out if (x["bg"], x["sig"]) not in apart]
    order = {"scope": 0, "variant": 1, "dupe": 2}
    out.sort(key=lambda x: (x["bg"], order[x["kind"]], -len(x["names"]), x["names"][0].lower()))
    return out


@app.route("/admin/performance/library/merges", methods=["GET", "POST"])
@admin_required
def admin_kpi_merges():
    """Performance > KPI library > Merge queue (2026-10-18, the libraries canvas board 3): the same measure stored at
    several scopes, a KPI with a qualifier stored as a new KPI, and near-duplicate wording. The super admin merges
    or keeps apart (Chris: the super admin edits the libraries); everyone in scope sees the queue. A variant or a
    near-duplicate retires its old rows into the one KPI (created from the first when it isn't there yet), and the
    old name is kept as an alias, so the tree reads it as that KPI and lines that used it keep their history; one
    measure at several scopes is grouped as one KPI with every row kept, its BU-level mark included. Double-confirmed,
    in the trail."""
    db = get_db()
    me = current_user()
    scoped_bg = admin_bg_of(me)
    bgs = [scoped_bg] if scoped_bg else org_bgs(db)
    sugg = _kpi_merge_suggestions(db, bgs)
    if request.method == "POST":
        if not is_super(me):
            abort(403)
        sig, bg = request.form.get("sig") or "", request.form.get("bg") or ""
        x = next((y for y in sugg if y["sig"] == sig and y["bg"] == bg), None)
        if not x:
            flash("That suggestion has already been settled, or no longer applies.", "error")
            return redirect(url_for("admin_kpi_merges", kind=request.args.get("kind")))
        act = request.form.get("action")
        if act == "apart":
            db.execute("INSERT OR IGNORE INTO pm_kpi_merge_apart(business_group, sig, decided_by) VALUES (?,?,?)",
                       (bg, sig, me["id"]))
            log_activity(db, me["id"], "pm_kpi_library", "kept apart in %s: %s" % (bg, ", ".join(x["names"])))
            db.commit()
            flash("Kept apart: %s." % ", ".join(x["names"]), "ok")
            return redirect(url_for("admin_kpi_merges", kind=request.args.get("kind")))
        if act != "merge":
            abort(400)
        into = x["into"]
        if x["kind"] == "dupe":
            into = request.form.get("into") or ""
            if into not in x["names"]:
                flash("Choose which name the KPI keeps.", "error")
                return redirect(url_for("admin_kpi_merges", kind=request.args.get("kind")))
        ik = _kpi_key(into)
        moving_bu = [r[0] for r in db.execute(
            "SELECT kpi_name FROM pm_kpi_library WHERE business_group=? AND active=1 AND bu_level=1 AND kpi_name IN (%s)"
            % ",".join("?" * len(x["names"])), [bg] + x["names"]) if _kpi_key(r[0]) != ik]
        if x["kind"] in ("variant", "dupe") and moving_bu:
            # a BU-level line is known by its library name (pm_bu_level_names): retiring that row would make HR's unit
            # result look like the person's own
            flash("%s is a BU-level KPI, so it can't be retired into another: keep them apart, or change it in the "
                  "library by hand." % moving_bu[0], "error")
            return redirect(url_for("admin_kpi_merges", kind=request.args.get("kind")))
        if x["kind"] in ("variant", "dupe"):
            have = db.execute("SELECT id FROM pm_kpi_library WHERE business_group=? AND kpi_name=? COLLATE NOCASE "
                              "AND active=1", (bg, into)).fetchone()
            if not have:   # the KPI isn't in the library yet: made from the first variant, for the whole group
                src = db.execute("SELECT * FROM pm_kpi_library WHERE business_group=? AND kpi_name=? AND active=1 "
                                 "ORDER BY (company='*') DESC, id LIMIT 1", (bg, x["names"][0])).fetchone()
                db.execute("INSERT INTO pm_kpi_library(business_group, company, department, tier_n, job_grade, kpi_name, "
                           "category, description, unit, method, created_by, bu_level, perspective) "
                           "VALUES (?, '*', '*', 0, '*', ?, ?, ?, ?, ?, ?, 0, ?)",
                           (bg, into, src["category"], src["description"], src["unit"], src["method"],
                            me["id"], src["perspective"]))
        moved = [n for n in x["names"] if _kpi_key(n) != ik]
        for n in moved:
            q = None
            if x["kind"] == "variant":
                m = re.match(r"^(.+?)\s*:\s+(.+)$", n)
                q = m.group(2).strip() if m else None
            elif x["kind"] == "scope":
                k = _kpi_key(n)
                q = next((w for w in KPI_SCOPE_WORDS if k.startswith(w + " ")), None)
            db.execute("INSERT OR REPLACE INTO pm_kpi_aliases(business_group, alias_key, alias_name, into_key, into_name, "
                       "kind, qualifier, created_by) VALUES (?,?,?,?,?,?,?,?)",
                       (bg, _kpi_key(n), n, ik, into, x["kind"], q, me["id"]))
            if x["kind"] in ("variant", "dupe"):
                db.execute("UPDATE pm_kpi_library SET active=0, updated_at=datetime('now'), updated_by=? WHERE "
                           "business_group=? AND kpi_name=? AND active=1", (me["id"], bg, n))
        log_activity(db, me["id"], "pm_kpi_library", "merged in %s: %s into %s (%s)" % (
            bg, ", ".join(moved), into, {"scope": "one measure at several scopes, rows kept",
                                         "variant": "variants, the qualifier into each line's Focus",
                                         "dupe": "near-duplicate wording"}[x["kind"]]))
        db.commit()
        flash("Merged into %s: %s." % (into, ", ".join(moved)), "ok")
        return redirect(url_for("admin_kpi_merges", kind=request.args.get("kind")))
    kind = request.args.get("kind") if request.args.get("kind") in ("scope", "variant", "dupe") else ""
    n = {k: sum(1 for y in sugg if y["kind"] == k) for k in ("scope", "variant", "dupe")}
    rows = [y for y in sugg if not kind or y["kind"] == kind]
    return render_template("admin_kpi_merges.html", rows=rows, kind=kind, n=n, n_all=len(sugg), can=is_super(me),
                           multi=len(bgs) > 1)


# ---- the Chart of KPI, piece B: Match lines (Chris, 2026-10-30, docs/chart-of-kpi.md; the canvas board 5) ---------------------
# Every distinct uncoded KPI name (the usage cycle's lines and the active library) with the code OneHR suggests; the super
# admin confirms one name or all the suggestions. A confirm writes one name-map row (source 'match'): no line is touched.
COA_MATCH_STOP = frozenset("of the and for in on to a an by".split())
COA_MATCH_MIN = (3, 5)   # token overlap of at least 0.6, kept as a fraction so 3 of 5 words is exactly 0.6
COA_MATCH_WHY = {"dupe": "Same KPI, written differently", "same": "Same name, coded in another group",
                 "root": "Its root KPI has a code", "scope": "Same measure, with a scope word"}


def _chart_match_tokens(text):
    """The words a name is compared by: lowercase, one-letter words and little words dropped."""
    return frozenset(t for t in re.findall(r"[a-z0-9]+", (text or "").lower()) if len(t) > 1 and t not in COA_MATCH_STOP)


def _chart_scope_free(name):
    """A name as its dupe key with the scope words (KPI_SCOPE_WORDS) taken out as whole words ('Plant gross profit (GP)'
    reads 'gross profit')."""
    words = "|".join(re.escape(w) for w in sorted(KPI_SCOPE_WORDS, key=len, reverse=True))
    return " ".join(re.sub(r"\b(?:%s)\b" % words, " ", _kpi_dupe_key(name)).split())


def _chart_match_population(db, idx=None, aliases=None):
    """What Match lines lists, from ONE batched read of the usage cycle's lines and one of the active library names, both
    resolved through chart_nodes_of_lines: {"cycle", "coded", "uncoded" (lines), "rows": {(name_key, business_group): row}}.
    A row: key, name (as first written), bg, lines (on the usage cycle; 0 for a library name nobody holds), foci, in_lib."""
    idx = idx or _chart_index(db)
    aliases = aliases if aliases is not None else _chart_aliases(db)
    cyc = _kpi_usage_cycle(db)
    rows, coded, uncoded = {}, 0, 0

    def row_of(name, bg):
        k = (_kpi_key(name), bg or "")
        if k not in rows:
            rows[k] = {"key": k[0], "name": name, "bg": k[1], "lines": 0, "foci": set(), "in_lib": False}
        return rows[k]
    if cyc:
        lines = [dict(r) for r in db.execute(
            "SELECT t.kpi_name, COALESCE(t.focus,'') AS focus, t.chart_node_id, u.business_group AS business_group, "
            "COUNT(*) AS n FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id WHERE t.cycle_id=? "
            "GROUP BY t.kpi_name, COALESCE(t.focus,''), t.chart_node_id, u.business_group "
            "ORDER BY t.kpi_name, u.business_group", (cyc["id"],))]
        for ln, nd in zip(lines, chart_nodes_of_lines(db, lines, idx, aliases)):
            if nd:
                coded += ln["n"]
                continue
            uncoded += ln["n"]
            r = row_of(ln["kpi_name"], ln["business_group"])
            r["lines"] += ln["n"]
            if ln["focus"]:
                r["foci"].add(ln["focus"])
    lib = [dict(r) for r in db.execute("SELECT DISTINCT business_group, kpi_name FROM pm_kpi_library WHERE active=1 "
                                       "ORDER BY kpi_name, business_group")]
    for ln, nd in zip(lib, chart_nodes_of_lines(db, lib, idx, aliases)):
        if not nd:
            row_of(ln["kpi_name"], ln["business_group"])["in_lib"] = True
    return {"cycle": cyc, "coded": coded, "uncoded": uncoded, "rows": rows}


def _chart_match_options(idx):
    """The codes a name can be given: every KPI and variant that is not retired, by code. [(node, "1101 Gross profit")]."""
    return [(n, "%s %s" % (n["code"], n["name"])) for n in sorted(
        (x for x in idx["nodes"].values() if x["level"] in ("kpi", "variant") and not x["retired_at"]),
        key=lambda x: x["code"])]


def _chart_match_suggest(idx, aliases, rows):
    """Put the suggestion on each row (row["sugg"], or None). Only against coded KPI and variant nodes that are not retired,
    best first: (a) the same dupe key as a coded name; (b) the root of 'Root: q' or the line's base has a code (the KPI's,
    never a variant's); (c) the scope words taken out equal a coded name; (d) word overlap of 0.6 or more. Within a rule the
    higher score, then the lower code, so the same data always suggests the same."""
    nodes = idx["nodes"]
    ents, by_dupe, by_tok, by_key = [], {}, {}, {}
    cand = {}
    for n in nodes.values():
        if n["level"] in ("kpi", "variant") and not n["retired_at"]:
            cand[n["id"]] = {_kpi_key(n["name"])}
    for (key, _bg), nid in idx["names"].items():
        if nid in cand:
            cand[nid].add(key)
    for nid, keys in cand.items():
        for key in keys:
            e = {"node": nodes[nid], "key": key, "dupe": _kpi_dupe_key(key), "tok": _chart_match_tokens(key)}
            ents.append(e)
            by_key.setdefault(key, []).append(e)
            if e["dupe"]:
                by_dupe.setdefault(e["dupe"], []).append(e)
            for t in e["tok"]:
                by_tok.setdefault(t, []).append(e)

    def lowest(es):
        return min(es, key=lambda e: e["node"]["code"])

    def kpi_of(n):   # a root gives the KPI, never a variant
        if n["level"] == "variant":
            n = nodes.get(n["parent_id"])
        return n if n and n["level"] == "kpi" and not n["retired_at"] else None
    for r in rows.values():
        r["sugg"] = None
        name, key, bg = r["name"], r["key"], r["bg"]
        dk = _kpi_dupe_key(name)
        hit = lowest(by_dupe[dk]) if dk and dk in by_dupe else None
        if hit:   # (a)
            same = [e for e in by_dupe[dk] if e["key"] == key]
            hit = lowest(same) if same else hit
            r["sugg"] = {"node": hit["node"], "rule": "same" if hit["key"] == key else "dupe", "score": 1.0, "via": hit["key"]}
        if not r["sugg"]:   # (b)
            ck = [_kpi_key(_bu_root(name))] + [_kpi_key(kpi_line_base(name, f)) for f in sorted(r["foci"])]
            found = []
            for c in dict.fromkeys(c for c in ck if c and c != key):
                n0 = _chart_lookup(idx, aliases, c, bg)
                n0 = n0 if n0 and not n0["retired_at"] and n0["level"] in ("kpi", "variant") else None
                n0 = kpi_of(n0) if n0 else (kpi_of(lowest(by_key[c])["node"]) if c in by_key else None)
                if n0:
                    found.append((n0["code"], n0, c))
            if found:
                _c, n0, c = min(found, key=lambda x: x[0])
                r["sugg"] = {"node": n0, "rule": "root", "score": 1.0, "via": c}
        if not r["sugg"]:   # (c)
            sf = _chart_scope_free(name)
            if sf and sf != dk and sf in by_dupe:
                hit = lowest(by_dupe[sf])
                r["sugg"] = {"node": hit["node"], "rule": "scope", "score": 1.0, "via": hit["key"]}
        if not r["sugg"]:   # (d)
            tk = _chart_match_tokens(name)
            seen, best = set(), None
            for t in tk:
                for e in by_tok.get(t, []):
                    if id(e) in seen:
                        continue
                    seen.add(id(e))
                    inter = len(tk & e["tok"])
                    union = len(tk | e["tok"])
                    if inter * COA_MATCH_MIN[1] >= union * COA_MATCH_MIN[0]:
                        cmp_ = (-inter / union, e["node"]["code"])
                        if best is None or cmp_ < best[0]:
                            best = (cmp_, e, inter / union)
            if best:
                r["sugg"] = {"node": best[1]["node"], "rule": "words", "score": best[2], "via": best[1]["key"]}
        s_ = r["sugg"]
        if s_:
            s_["reason"] = ("Similar words (%d%%)" % round(s_["score"] * 100)) if s_["rule"] == "words" else COA_MATCH_WHY[s_["rule"]]
    return rows


def _chart_match_rows(db, q="", kind=""):
    """The Match lines page's data: the tiles (whole population), the rows under the search and the pill, the pill counts
    (under the search) and the code options."""
    idx = _chart_index(db)
    aliases = _chart_aliases(db)
    pop = _chart_match_population(db, idx, aliases)
    _chart_match_suggest(idx, aliases, pop["rows"])
    allrows = sorted(pop["rows"].values(), key=lambda r: (r["sugg"] is None, -r["lines"], r["name"].lower(), r["bg"]))
    ql = (q or "").strip().lower()
    seen = [r for r in allrows if not ql or ql in r["key"] or ql in display_bg(r["bg"]).lower()]
    for r in allrows:
        r["pair"] = json.dumps([r["sugg"]["node"]["id"], r["bg"], r["key"]]) if r["sugg"] else ""
    shown = [r for r in seen if not kind or (kind == "sugg") == bool(r["sugg"])]
    n_sugg = sum(1 for r in seen if r["sugg"])
    return {"cycle": pop["cycle"], "coded": pop["coded"], "uncoded": pop["uncoded"],
            "n_names": len(allrows), "t_sugg": sum(1 for r in allrows if r["sugg"]),
            "t_none": sum(1 for r in allrows if not r["sugg"]),
            "n_all": len(seen), "n_sugg": n_sugg, "n_none": len(seen) - n_sugg, "rows": shown,
            "options": _chart_match_options(idx), "idx": idx, "pop": pop}


@app.route("/admin/performance/library/match", methods=["GET", "POST"])
@admin_required
def admin_kpi_chart_match():
    """Performance > KPI library > Match lines (the Chart of KPI, board 5; ONEHR_COA=1, the super admin). The uncoded KPI
    names, each with the code OneHR suggests and why; Confirm gives a name its code, Confirm all does every suggestion
    shown. A confirm adds one row to the name map (group-wide, or this group's only), so every line of that name reads as the
    code; a line keeps its own name, target and result. Double-confirmed, in the trail."""
    if not coa_on():
        abort(404)
    db = get_db()
    me = current_user()
    if not is_super(me):
        abort(403)
    kind = request.values.get("kind") if request.values.get("kind") in ("sugg", "none") else ""
    q = " ".join((request.values.get("q") or "").split())[:120]

    def back():
        return redirect(url_for("admin_kpi_chart_match", kind=kind or None, q=q or None))
    if request.method == "POST":
        action = request.form.get("action", "")
        if action not in ("confirm", "confirm_all"):
            abort(400)
        idx = _chart_index(db)
        aliases = _chart_aliases(db)
        live = _chart_match_population(db, idx, aliases)["rows"]

        def node_ok(nid):
            n = idx["nodes"].get(nid)
            return n if n and n["level"] in ("kpi", "variant") and not n["retired_at"] else None
        if action == "confirm":
            key, bg = " ".join((request.form.get("key") or "").lower().split()), request.form.get("bg") or ""
            row = live.get((key, bg))
            if not row:
                flash("That name already has a code, or is no longer on the list.", "error")
                return back()
            try:
                nid = int(request.form.get("code_node", ""))
            except (TypeError, ValueError):
                flash("Pick a code from the list.", "error")
                return back()
            nd = node_ok(nid)
            if not nd:
                flash("Pick a code from the list: that one is not a KPI or variant in use.", "error")
                return back()
            scope = bg if request.form.get("scope_bg") else ""
            if not _chart_map_name(db, nd["id"], row["name"], scope, "match", me["id"]):
                flash("That name already has a code.", "error")
                return back()
            log_activity(db, me["id"], "pm_kpi_chart", "matched 1 name (%d line%s) to a code: %s -> %s %s%s" % (
                row["lines"], "" if row["lines"] == 1 else "s", row["name"], nd["code"], nd["name"],
                " (%s only)" % bg if scope else ""), commit=False)
            db.commit()
            flash("“%s” now reads as %s %s%s. %d line%s coded; their names, targets and results are as they were." % (
                row["name"], nd["code"], nd["name"], " in %s only" % display_bg(bg) if scope else "", row["lines"],
                "" if row["lines"] == 1 else "s"), "ok")
            return back()
        names = lines = skipped = 0
        done, written = [], set()
        for raw in request.form.getlist("pair"):
            try:
                nid, bg, key = json.loads(raw)
                nid = int(nid)
                if not isinstance(key, str) or not isinstance(bg, str):
                    raise ValueError
            except (ValueError, TypeError):
                skipped += 1
                continue
            row = live.get((key, bg))
            if not row and key in written:
                continue   # a group-wide name an earlier pair of this post has just given its code
            nd = node_ok(nid)
            if not row or not nd or not _chart_map_name(db, nd["id"], row["name"], "", "match", me["id"]):
                skipped += 1
                continue
            written.add(key)
            done.append("%s -> %s" % (row["name"], nd["code"]))
            for k_b in [k_b for k_b in live if k_b[0] == key]:   # a group-wide name codes every group's copy of it
                names += 1
                lines += live[k_b]["lines"]
                del live[k_b]
        if names:
            log_activity(db, me["id"], "pm_kpi_chart", "matched %d name%s (%d line%s) to codes, all suggestions: %s%s" % (
                names, "" if names == 1 else "s", lines, "" if lines == 1 else "s", "; ".join(done[:20]),
                " and %d more" % (len(done) - 20) if len(done) > 20 else ""), commit=False)
            db.commit()
        flash("Coded %d name%s (%d line%s).%s" % (
            names, "" if names == 1 else "s", lines, "" if lines == 1 else "s",
            " %d skipped: already coded, or no longer valid." % skipped if skipped else ""), "ok" if names else "error")
        return back()
    d = _chart_match_rows(db, q, kind)
    for r in d["rows"]:
        r["new_url"] = url_for("admin_kpi_library", panel="add", addbg=r["bg"] or None, kpi_name=r["name"])
    shown_sugg = [r for r in d["rows"] if r["sugg"]]
    return render_template("admin_kpi_chart_match.html", d=d, rows=d["rows"], kind=kind, q=q,
                           n_confirm=len(shown_sugg), n_confirm_lines=sum(r["lines"] for r in shown_sugg),
                           pairs=[r["pair"] for r in shown_sugg], multi=len(org_bgs(db)) > 1)


# ---- the Chart of KPI, piece C: the handshake keys (Chris, 2026-10-30, docs/chart-of-kpi.md "Phase 2"; the canvas boards 6-7) --
# Systems (a name each, never a credential), a KPI's data link (which measure of which system fills it), a person's ID and a
# unit's code in a system. Nothing here connects to anything: the Test answers a fixed sentence until Phase 3.
COA_SYSTEM_MAX = 60
COA_EXT_MAX = 60
COA_METRIC_MAX = 120
COA_LINK_PERIODS = (("month", "Month"), ("quarter", "Quarter"), ("half", "Half year"), ("year", "Year"))
COA_LINK_WHOSE = (("person", "The person's"), ("unit", "The business unit's"), ("group", "The business group's"))
COA_LINK_MATCH = {"person": ("employee_id", "system_person_code"), "unit": ("unit_code",), "group": ()}
COA_LINK_MATCH_WORDS = {"employee_id": "Employee ID", "system_person_code": "The person's ID in the system",
                        "unit_code": "The unit's code in the system"}
COA_LINK_TEST = "No system connected yet: the link is saved and will be used once the system is connected."
app.jinja_env.globals.update(coa_link_periods=COA_LINK_PERIODS, coa_link_whose=COA_LINK_WHOSE,
                             coa_link_match_words=COA_LINK_MATCH_WORDS, coa_link_test=COA_LINK_TEST)


def _coa_clean(raw):
    """A typed name or code with its spaces folded; None when it carries a control character."""
    t = re.sub(r"\s+", " ", (raw or "").strip())
    return None if any(ord(ch) < 32 for ch in t) else t


def _coa_pick(raw, allowed):
    """The listed spelling of `raw` (case ignored), or None: a unit or group comes from a list, never from free text."""
    t = (raw or "").strip().lower()
    return next((a for a in allowed if a.lower() == t), None) if t else None


def _coa_systems(db):
    """Every system with how many KPIs link to it, how many people hold an ID in it and how many units hold a code in it:
    ONE read. Live ones first, then the retired, by name."""
    return [dict(r) for r in db.execute(
        "SELECT s.*, (SELECT COUNT(*) FROM kpi_chart_links l WHERE l.system_id=s.id) AS n_kpis, "
        "(SELECT COUNT(*) FROM user_ext_ids u WHERE u.system_id=s.id AND u.removed_at IS NULL) AS n_people, "
        "(SELECT COUNT(*) FROM org_ext_ids o WHERE o.system_id=s.id) AS n_units "
        "FROM kpi_ext_systems s ORDER BY (s.retired_at IS NOT NULL), LOWER(s.name)")]


def _coa_system_add(db, me, raw):
    """(ok, message): the super admin adds a system by name. Refused: blank, over COA_SYSTEM_MAX, an address (a system is a name,
    never a login), and a name some system has already (case ignored; a retired one is brought back instead)."""
    if not is_super(me):
        return False, "Only the super admin adds a system."
    nm = _coa_clean(raw)
    if not nm:
        return False, "Type the system's name (letters and numbers only, no control characters)."
    if len(nm) > COA_SYSTEM_MAX:
        return False, "Keep the system's name to %d characters." % COA_SYSTEM_MAX
    if "://" in nm:
        return False, "A system is added by its name only. OneHR stores no address with a login, key or password."
    hit = db.execute("SELECT * FROM kpi_ext_systems WHERE name=?", (nm,)).fetchone()
    if hit:
        return False, "%s is already a system%s." % (hit["name"], " (it is retired: bring it back instead)" if hit["retired_at"] else "")
    db.execute("INSERT INTO kpi_ext_systems(name, added_by) VALUES (?,?)", (nm, me["id"]))
    log_activity(db, me["id"], "pm_kpi_chart", "system added: %s" % nm, commit=False)
    return True, "Added the system %s. KPIs can now link to it." % nm


def _coa_system_retire(db, me, sid, retire=True):
    """(ok, message): hide a system from new links (its links, IDs and codes stay and stay readable), or bring it back."""
    if not is_super(me):
        return False, "Only the super admin changes a system."
    r = db.execute("SELECT * FROM kpi_ext_systems WHERE id=?", (sid,)).fetchone()
    if not r:
        return False, "Pick a system from the list."
    if retire == bool(r["retired_at"]):
        return False, "%s is already %s." % (r["name"], "retired" if retire else "in use")
    if retire:
        db.execute("UPDATE kpi_ext_systems SET retired_at=datetime('now') WHERE id=?", (r["id"],))
    else:
        db.execute("UPDATE kpi_ext_systems SET retired_at=NULL WHERE id=?", (r["id"],))
    log_activity(db, me["id"], "pm_kpi_chart", "system %s: %s" % ("retired" if retire else "brought back", r["name"]), commit=False)
    return True, ("%s is retired: it is hidden from new links; what already uses it stays." % r["name"]) if retire \
        else "%s is back: it can be linked again." % r["name"]


def _coa_live_system(db, raw):
    """(row or None, reason): the system a form named, which must exist and not be retired."""
    try:
        r = db.execute("SELECT * FROM kpi_ext_systems WHERE id=?", (int(raw),)).fetchone()
    except (TypeError, ValueError):
        r = None
    if not r:
        return None, "Pick a system from the list."
    if r["retired_at"]:
        return None, "%s is retired, so nothing new can use it. Pick another system, or bring it back on the Systems tab." % r["name"]
    return r, None


def _coa_unitcode_add(db, me, bg_raw, co_raw, sid_raw, code_raw):
    """(ok, message): a unit's code in a system, set once per unit and system. The unit must be a real, active one of the org
    (picked, never typed); the system must not be retired; a code is at most COA_EXT_MAX and no two units share one in a system."""
    if not is_super(me):
        return False, "Only the super admin sets a unit's code."
    om = org_map(db)
    bg = _coa_pick(bg_raw, list(om))
    co = _coa_pick(co_raw, om.get(bg, [])) if bg else None
    if not bg or not co:
        return False, "Pick the business group and the unit from the lists."
    sysr, why = _coa_live_system(db, sid_raw)
    if why:
        return False, why
    code = _coa_clean(code_raw)
    if not code:
        return False, "Type the unit's code in %s." % sysr["name"]
    if len(code) > COA_EXT_MAX:
        return False, "A code is at most %d characters." % COA_EXT_MAX
    shown = display_company(bg, co) or co
    own = db.execute("SELECT * FROM org_ext_ids WHERE business_group=? AND company=? AND system_id=?", (bg, co, sysr["id"])).fetchone()
    if own:
        return False, "%s already has the code %s in %s. Remove it first to set another." % (shown, own["ext_code"], sysr["name"])
    other = db.execute("SELECT business_group, company FROM org_ext_ids WHERE system_id=? AND ext_code=?", (sysr["id"], code)).fetchone()
    if other:
        return False, "%s is already %s's code in %s. A code belongs to one unit. Nothing changed." % (
            code, display_company(other["business_group"], other["company"]) or other["company"], sysr["name"])
    db.execute("INSERT INTO org_ext_ids(business_group, company, system_id, ext_code, linked_by) VALUES (?,?,?,?,?)",
               (bg, co, sysr["id"], code, me["id"]))
    log_activity(db, me["id"], "pm_kpi_chart", "unit code set: %s / %s is %s in %s" % (bg, co, code, sysr["name"]), commit=False)
    return True, "%s is %s in %s." % (shown, code, sysr["name"])


def _coa_unitcode_remove(db, me, rid):
    """(ok, message): take a unit's code off (the row goes; nothing else holds it)."""
    if not is_super(me):
        return False, "Only the super admin changes a unit's code."
    try:
        r = db.execute("SELECT o.*, s.name AS sname FROM org_ext_ids o JOIN kpi_ext_systems s ON s.id=o.system_id WHERE o.id=?",
                       (int(rid),)).fetchone()
    except (TypeError, ValueError):
        r = None
    if not r:
        return False, "That code is no longer there."
    db.execute("DELETE FROM org_ext_ids WHERE id=?", (r["id"],))
    log_activity(db, me["id"], "pm_kpi_chart", "unit code removed: %s / %s was %s in %s" % (
        r["business_group"], r["company"], r["ext_code"], r["sname"]), commit=False)
    return True, "%s is off %s in %s." % (r["ext_code"], display_company(r["business_group"], r["company"]) or r["company"], r["sname"])


def _coa_systems_page(db):
    """The Systems tab's data: the systems with their counts, every unit code, and the org's groups and units for the pickers."""
    codes = [dict(r) for r in db.execute(
        "SELECT o.*, s.name AS sname, s.retired_at AS sretired FROM org_ext_ids o JOIN kpi_ext_systems s ON s.id=o.system_id "
        "ORDER BY o.business_group, o.company, LOWER(s.name)")]
    for c_ in codes:
        c_["unit_shown"] = display_company(c_["business_group"], c_["company"]) or c_["company"]
    om = org_map(db)
    return {"systems": _coa_systems(db), "codes": codes, "org": [(b, [(c_, display_company(b, c_) or c_) for c_ in cs])
                                                                for b, cs in om.items() if cs]}


@app.route("/admin/performance/library/systems", methods=["GET", "POST"])
@admin_required
def admin_kpi_systems():
    """Performance > KPI library > Systems (the Chart of KPI, piece C; ONEHR_COA=1, the super admin). The other systems a KPI's
    figure can come from -- a name each, never a credential -- how many KPIs, people and units use each, and the code each unit
    has in a system. Every change is double-confirmed and in the trail."""
    if not coa_on():
        abort(404)
    db = get_db()
    me = current_user()
    if not is_super(me):
        abort(403)
    if request.method == "POST":
        action = request.form.get("action", "")
        f = request.form
        if action == "system_add":
            ok, msg = _coa_system_add(db, me, f.get("system_name"))
        elif action in ("system_retire", "system_restore"):
            ok, msg = _coa_system_retire(db, me, _form_int("system_id"), action == "system_retire")
        elif action == "unitcode_add":
            ok, msg = _coa_unitcode_add(db, me, f.get("business_group"), f.get("company"), f.get("system_id"), f.get("ext_code"))
        elif action == "unitcode_remove":
            ok, msg = _coa_unitcode_remove(db, me, f.get("code_id"))
        else:
            abort(400)
        if ok:
            db.commit()
        else:
            db.rollback()
        flash(msg, "ok" if ok else "error")
        return redirect(url_for("admin_kpi_systems"))
    d = _coa_systems_page(db)
    return render_template("admin_kpi_systems.html", d=d, live=[s_ for s_ in d["systems"] if not s_["retired_at"]],
                           n_systems=len(d["systems"]), max_sys=COA_SYSTEM_MAX, max_ext=COA_EXT_MAX)


def _coa_node_bu_level(db, idx, aliases, node):
    """Whether a node's KPI is a BU-level one: an active library row marked BU-level reads as this KPI (or, for a variant,
    as its KPI or a variant of it). Its figure is a unit's, so its link can only be the unit's."""
    root = idx["nodes"].get(node["parent_id"], node) if node["level"] == "variant" else node
    for r in db.execute("SELECT business_group, kpi_name FROM pm_kpi_library WHERE active=1 AND bu_level=1"):
        n = _chart_lookup(idx, aliases, _kpi_key(r["kpi_name"]), r["business_group"])
        if n:
            nr = idx["nodes"].get(n["parent_id"], n) if n["level"] == "variant" else n
            if nr["id"] == root["id"]:
                return True
    return False


def _coa_link_text(row):
    """A saved link in words, for the trail."""
    return "%s metric %s, %s, %s figure%s%s" % (
        row["system_name"], row["metric_id"], row["period"], row["whose"],
        ", matched on %s" % row["matched_on"] if row["matched_on"] else "",
        ", unit %s" % row["unit"] if row["unit"] else "") + (", x%g" % row["factor"])


def _coa_link_row(db, node_id):
    return db.execute("SELECT l.*, s.name AS system_name, s.retired_at AS system_retired FROM kpi_chart_links l "
                      "JOIN kpi_ext_systems s ON s.id=l.system_id WHERE l.node_id=?", (node_id,)).fetchone()


def _coa_link_save(db, me, node, idx, aliases, form):
    """(ok, message): save a KPI's (or variant's) data link. Refused, writing nothing: not the super admin, a retired node,
    an unknown or retired system, a blank or long metric ID, an unknown period or whose, a 'matched on' that does not fit
    whose (a person by Employee ID or the system's person code, a unit by its unit code, a group by none), a BU-level KPI that
    is not the unit's figure, and a factor that is not a number above 0. One activity_log row; the caller commits."""
    if not is_super(me):
        return False, "Only the super admin links a KPI to a system."
    label = "%s %s" % (node["code"], node["name"])
    if node["level"] not in ("kpi", "variant") or node["retired_at"]:
        return False, "%s is retired or is not a KPI, so it takes no link." % label
    sysr, why = _coa_live_system(db, form.get("system_id"))
    if why:
        return False, why
    metric = _coa_clean(form.get("metric_id"))
    if not metric:
        return False, "Type the measure's ID in %s." % sysr["name"]
    if len(metric) > COA_METRIC_MAX:
        return False, "A measure's ID is at most %d characters." % COA_METRIC_MAX
    if "://" in metric:
        return False, "Type the measure's ID, not an address. OneHR stores no address with a login."
    period = (form.get("period") or "").strip()
    if period not in dict(COA_LINK_PERIODS):
        return False, "Pick the period the figure covers."
    whose = (form.get("whose") or "").strip()
    if whose not in dict(COA_LINK_WHOSE):
        return False, "Pick whose figure it is: the person's, the business unit's or the business group's."
    mo = (form.get("matched_on") or "").strip()
    if whose == "group":
        if mo:
            return False, "A business group's figure needs nothing to match on."
        mo = None
    elif mo not in COA_LINK_MATCH[whose]:
        return False, "%s figure is matched on %s." % (dict(COA_LINK_WHOSE)[whose], " or ".join(
            COA_LINK_MATCH_WORDS[m_].lower() for m_ in COA_LINK_MATCH[whose]))
    if whose != "unit" and _coa_node_bu_level(db, idx, aliases, node):
        return False, ("%s is a BU-level KPI: its figure goes once to the unit in BU KPI setup, never to each person, so its "
                       "link can only read the business unit's figure." % label)
    try:
        factor = float((form.get("factor") or "").strip() or "1")
    except ValueError:
        factor = float("nan")
    if not math.isfinite(factor) or factor <= 0 or factor > 1e15:
        return False, "Type the factor as a number above 0 (1 leaves the figure as the system sends it)."
    unit = kpi_unit_normalise(form.get("unit"))
    old = _coa_link_row(db, node["id"])
    same = (old and old["system_id"] == sysr["id"] and old["metric_id"] == metric and old["period"] == period
            and old["whose"] == whose and old["matched_on"] == mo and (old["unit"] or None) == unit and old["factor"] == factor)
    if same:
        return False, "%s's link is already exactly that. Nothing changed." % label
    db.execute("INSERT INTO kpi_chart_links(node_id, system_id, metric_id, period, whose, matched_on, unit, factor, updated_by) "
               "VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(node_id) DO UPDATE SET system_id=excluded.system_id, "
               "metric_id=excluded.metric_id, period=excluded.period, whose=excluded.whose, matched_on=excluded.matched_on, "
               "unit=excluded.unit, factor=excluded.factor, updated_by=excluded.updated_by, updated_at=datetime('now')",
               (node["id"], sysr["id"], metric, period, whose, mo, unit, factor, me["id"]))
    new = _coa_link_row(db, node["id"])
    log_activity(db, me["id"], "pm_kpi_chart", "data link %s on %s: %s" % ("changed" if old else "saved", label, _coa_link_text(new)),
                 commit=False)
    return True, "%s now reads %s's %s. Nothing is pulled yet: it is used once the system is connected." % (
        label, sysr["name"], metric)


def _coa_link_remove(db, me, node):
    """(ok, message): take a node's data link off."""
    if not is_super(me):
        return False, "Only the super admin removes a link."
    old = _coa_link_row(db, node["id"])
    if not old:
        return False, "%s %s has no link to remove." % (node["code"], node["name"])
    db.execute("DELETE FROM kpi_chart_links WHERE node_id=?", (node["id"],))
    log_activity(db, me["id"], "pm_kpi_chart", "data link removed from %s %s: it was %s" % (
        node["code"], node["name"], _coa_link_text(old)), commit=False)
    return True, "%s %s is no longer linked to %s." % (node["code"], node["name"], old["system_name"])


def _coa_preview(db, link, held, limit=5):
    """What a pull would fill, read-only: up to `limit` holders of the code in the usage cycle, in Employee ID order, with their
    ID in the link's system, their unit and its code there. Employee IDs only, never a name. Three batched reads (the holders,
    their IDs in the system, the system's unit codes); nothing is written."""
    ids = sorted(held)
    people = []
    for i in range(0, len(ids), 500):
        part = ids[i:i + 500]
        people += [dict(r) for r in db.execute("SELECT id, employee_id, business_group, company FROM users WHERE id IN (%s)"
                                               % ",".join("?" * len(part)), part)]
    people.sort(key=lambda r: ((r["employee_id"] or "").lower(), r["id"]))
    top = people[:limit]
    ext, codes = {}, {}
    if top:
        ext = {r["user_id"]: r["ext_id"] for r in db.execute(
            "SELECT user_id, ext_id FROM user_ext_ids WHERE system_id=? AND removed_at IS NULL AND user_id IN (%s)"
            % ",".join("?" * len(top)), [link["system_id"]] + [p_["id"] for p_ in top])}
        codes = {(r["business_group"], r["company"]): r["ext_code"] for r in db.execute(
            "SELECT business_group, company, ext_code FROM org_ext_ids WHERE system_id=?", (link["system_id"],))}
    rows = [{"eid": p_["employee_id"], "ext": ext.get(p_["id"]), "unit": display_company(p_["business_group"], p_["company"]) or p_["company"] or "",
             "code": codes.get((p_["business_group"], p_["company"]))} for p_ in top]
    return {"total": len(people), "rows": rows}


def _coa_links_view(db, cp, cyc, open_id=None):
    """The data-link parts of the KPI panel: the systems to pick from, whether the KPI is BU-level, and for the panel's own node
    and every variant its link in words (one read of the links); the panel's node and `open_id` (a variant opened in its own
    panel) also carry the preview of what a pull would fill."""
    node = cp["node"]
    fam = [node["id"]] + [v["node"]["id"] for v in cp.get("variants", []) if v["node"]["id"] != node["id"]]
    ph = ",".join("?" * len(fam))
    links = {r["node_id"]: r for r in db.execute(
        "SELECT l.*, s.name AS system_name, s.retired_at AS system_retired FROM kpi_chart_links l JOIN kpi_ext_systems s "
        "ON s.id=l.system_id WHERE l.node_id IN (%s)" % ph, fam)}
    idx, aliases = _chart_index(db), _chart_aliases(db)
    out = {"systems": [s_ for s_ in _coa_systems(db) if not s_["retired_at"]], "bu": cp["bu_level"] or _coa_node_bu_level(db, idx, aliases, node),
           "by_node": {}, "node_id": node["id"], "open_id": open_id if open_id in fam and open_id != node["id"] else None}
    for nid in fam:
        lk = links.get(nid)
        view = {"link": lk, "preview": None}
        if lk and (nid == node["id"] or nid == out["open_id"]):
            view["preview"] = _coa_preview(db, lk, cp.get("held", {}).get(nid, set()))
        out["by_node"][nid] = view
    return out


# A person's IDs in other systems (board 7): the Account panel's box, the super admin's alone
def _ext_ids_of(db, uid):
    """A person's ACTIVE IDs in other systems, oldest first: [{id, system, ext, retired, by, day}]."""
    return [{"id": r["id"], "system": r["sname"], "ext": r["ext_id"], "retired": bool(r["sretired"]),
             "by": r["by_name"] or "the super admin", "day": " ".join((_myt_date_str(r["linked_at"]) or "").split()[:2])}
            for r in db.execute("SELECT x.*, s.name AS sname, s.retired_at AS sretired, b.full_name AS by_name FROM user_ext_ids x "
                                "JOIN kpi_ext_systems s ON s.id=x.system_id LEFT JOIN users b ON b.id=x.linked_by "
                                "WHERE x.user_id=? AND x.removed_at IS NULL ORDER BY x.id", (uid,))]


def _ext_gate(db, me, p):
    """The refusals every change to a person's IDs in other systems shares, or None: the super admin only, a system admin's
    account is theirs, and an admin or demo account has no such IDs."""
    if not is_super(me):
        return "Only the super admin changes a person's IDs in other systems."
    locked = _system_admin_locked(me, p, db)
    if locked:
        return locked
    if p["role"] == "admin" or p["is_demo"]:
        return "Pick a person from the list."
    return None


def _ext_link(db, me, p, system_raw, raw):
    """(ok, message): the super admin adds a person's ID in a system. Refused: anyone else, a system admin's account, an admin
    or demo account, someone who has left, an unknown or retired system, a blank ID or one over COA_EXT_MAX, a second active ID
    for the same system (Remove the first), and an ID some other person holds in that system (the message names their Employee
    ID). Audited; the caller commits."""
    why = _ext_gate(db, me, p)
    if why:
        return False, why
    if p["left_at"]:
        return False, "%s has left; their IDs are not changed." % p["full_name"]
    sysr, why = _coa_live_system(db, system_raw)
    if why:
        return False, why
    ext = _coa_clean(raw)
    if not ext:
        return False, "Type the person's ID in %s." % sysr["name"]
    if len(ext) > COA_EXT_MAX:
        return False, "An ID is at most %d characters." % COA_EXT_MAX
    mine = db.execute("SELECT ext_id FROM user_ext_ids WHERE user_id=? AND system_id=? AND removed_at IS NULL",
                      (p["id"], sysr["id"])).fetchone()
    if mine:
        return False, "%s already has the ID %s in %s. Remove it first to add another." % (p["full_name"], mine["ext_id"], sysr["name"])
    held = db.execute("SELECT u.employee_id FROM user_ext_ids x JOIN users u ON u.id=x.user_id WHERE x.system_id=? AND "
                      "x.ext_id=? AND x.removed_at IS NULL", (sysr["id"], ext)).fetchone()
    if held:
        return False, "%s is already the ID of %s in %s. An ID belongs to one person in a system. Nothing changed." % (
            ext, held["employee_id"], sysr["name"])
    try:
        db.execute("INSERT INTO user_ext_ids(user_id, system_id, ext_id, linked_by) VALUES (?,?,?,?)",
                   (p["id"], sysr["id"], ext, me["id"]))
    except sqlite3.IntegrityError:
        db.rollback()
        return False, "%s is already someone's ID in %s. Nothing changed." % (ext, sysr["name"])
    _leader_log(db, me["id"], "ext_link", "%s: ID %s in %s added (main ID %s)" % (p["full_name"], ext, sysr["name"], p["employee_id"]),
                p["id"])
    return True, "%s is %s in %s. A KPI that reads their own figure from it finds them by that ID." % (p["full_name"], ext, sysr["name"])


def _ext_unlink(db, me, p, row_id):
    """(ok, message): take one of a person's IDs in a system off (the row is kept, with removed_at and removed_by)."""
    why = _ext_gate(db, me, p)
    if why:
        return False, why
    try:
        r = db.execute("SELECT x.*, s.name AS sname FROM user_ext_ids x JOIN kpi_ext_systems s ON s.id=x.system_id "
                       "WHERE x.id=? AND x.user_id=? AND x.removed_at IS NULL", (int(row_id), p["id"])).fetchone()
    except (TypeError, ValueError):
        r = None
    if not r:
        return False, "That isn't one of %s's IDs in another system. Nothing changed." % p["full_name"]
    db.execute("UPDATE user_ext_ids SET removed_at=datetime('now'), removed_by=? WHERE id=?", (me["id"], r["id"]))
    _leader_log(db, me["id"], "ext_unlink", "%s: ID %s in %s removed (main ID %s)" % (p["full_name"], r["ext_id"], r["sname"], p["employee_id"]),
                p["id"])
    return True, "%s is off %s in %s. You can add one again later." % (r["ext_id"], p["full_name"], r["sname"])


# ---- proposals to the KPI library (2026-10-18, the libraries canvas boards 10-11) ------------------------------------


def _kpi_closest(db, bg, name, limit=1):
    """The library KPIs of a group closest to a proposed name, by shared words (no model): [(name, score)], best first."""
    want = _ja_words(name)
    if not want:
        return []
    seen, out = set(), []
    for r in db.execute("SELECT kpi_name FROM pm_kpi_library WHERE business_group=? AND active=1", (bg,)):
        k = _kpi_key(r[0])
        if k in seen:
            continue
        seen.add(k)
        sc = len(want & _ja_words(r[0])) / max(1, len(want | _ja_words(r[0])))
        if sc >= 0.25:
            out.append((r[0], sc))
    out.sort(key=lambda x: -x[1])
    return out[:limit]


def _library_request_email(db, req, word, note=""):
    """The answer, to every address on the proposer's notification emails (production only: a server with no
    Microsoft Graph sends nothing). A short word for the flash; a failure never
    undoes the decision."""
    if not mailer.is_configured():
        return "No email: this server sends none."
    if not admin_notify_addresses(db, req["created_by"]):
        return "No email: they have no notification emails set."
    pl = json.loads(req["payload_json"])
    what = pl.get("name") or pl.get("kpi_name") or "your proposal"
    esc = lambda v: html.escape(str(v))   # noqa: E731
    n = _admin_task_email(
        db, req["created_by"], "Your KPI library proposal: %s" % word, "Your KPI library proposal: %s" % word,
        ["The super admin has %s your proposal for <b>%s</b>." % (esc(word), esc(what))],
        box=_em_box(["&ldquo;%s&rdquo;" % esc(note)]) if note else "",
        button=("Open your proposals", app_base_url() + url_for("admin_library_requests")))
    return "Emailed them." if n else "The email to them failed to send."


@app.route("/admin/performance/library/propose", methods=["POST"])
@admin_required
def admin_library_propose():
    """A BG or unit admin proposes a new KPI for their group, or a change to a KPI's definition (2026-10-18, the
    libraries canvas board 10; Chris: the super admin edits the libraries and approves the BG / unit admins'
    proposals). Global KPIs are the super admin's own; a unit admin proposes for their units or a job family. The super
    admin decides on Requests; the proposer sees the answer there and by email. Their reason is required."""
    db = get_db()
    me = current_user()
    bg = admin_bg_of(me)
    if not bg:   # the super admin edits the library directly
        abort(403)
    kind = request.form.get("kind")
    reason = (request.form.get("reason") or "").strip()
    back = lambda **kw: redirect(url_for("admin_kpi_library", **kw))   # noqa: E731
    if not reason or len(reason) > 500 or ai_draft.stored_text_refusal(reason, "manager"):
        flash("Say why it's needed (up to 500 characters).", "error")
        return back(panel="propose")
    units = admin_companies_of(me)
    if kind == "new_kpi":
        name = " ".join((request.form.get("name") or "").split())
        scope = request.form.get("scope") or "bg"
        company = (request.form.get("company") or "").strip()
        fam = (request.form.get("family") or "").strip()
        method = request.form.get("method") if request.form.get("method") in ("more", "less") else None
        persp = (request.form.get("perspective") or "").strip() or None
        defn = (request.form.get("definition") or "").strip()
        why = None
        if not name or len(name) > 120:
            why = "Give the KPI a name (up to 120 characters)."
        elif scope not in ("bg", "unit", "jf") or (scope == "bg" and units):
            why = "Choose where it applies."
        elif scope == "unit" and (not company or not can_access(me, bg, company)):
            why = "Choose one of your units."
        elif scope == "jf" and not db.execute("SELECT 1 FROM ja_taxonomy WHERE code=? AND level IN ('sub','spec')",
                                              (fam,)).fetchone():
            why = "Choose the job family."
        elif not method:
            why = "Say whether higher or lower is better."
        elif persp and persp not in PM_PERSPECTIVES:
            abort(400)
        elif not defn or len(defn) > 600:
            why = "Give a short definition: what is measured, and how."
        elif kpi_def_figure_msg(defn):
            why = kpi_def_figure_msg(defn)
        elif db.execute("SELECT 1 FROM pm_kpi_library WHERE business_group=? AND kpi_name=? COLLATE NOCASE", (bg, name)
                        ).fetchone():
            why = "'%s' is in %s's library already: use it, with a Focus if it's about one thing." % (name, display_bg(bg))
        if why:
            flash(why, "error")
            return back(panel="propose")
        pl = {"name": name, "scope": scope, "company": company if scope == "unit" else None,
              "family": fam if scope == "jf" else None, "method": method, "perspective": persp,
              "category": _admin_list_choice(request.form, "category", kpi_library_lists(db, org_bgs(db))["cats"],
                                             None, "family · group", 120)[0], "definition": defn,
              "unit": kpi_unit_normalise(request.form.get("unit")), "bu_level": 1 if request.form.get("bu_level") else 0,
              "close_to": [n for n, _s in _kpi_closest(db, bg, name)]}
    elif kind == "change_def":
        key = (request.form.get("kpi") or "").strip()
        defn = (request.form.get("definition") or "").strip()
        rows = [r for r in db.execute("SELECT id, kpi_name, description, business_group FROM pm_kpi_library")
                if _kpi_key(r["kpi_name"]) == key]
        if not rows or not any(r["business_group"] == bg for r in rows):
            abort(404)
        if not defn or len(defn) > 600 or kpi_def_figure_msg(defn):
            flash(kpi_def_figure_msg(defn) or "Give the definition as you'd have it.", "error")
            return back(kpi=key, panel="kpi")
        cur = next((r["description"] for r in rows if r["business_group"] == bg and r["description"]), None)
        pl = {"kpi": key, "kpi_name": rows[0]["kpi_name"], "now": cur, "definition": defn,
              "bgs": sorted({r["business_group"] for r in rows})}
    else:
        abort(400)
    db.execute("INSERT INTO pm_library_requests(kind, business_group, payload_json, reason, created_by) VALUES "
               "(?,?,?,?,?)", (kind, bg, json.dumps(pl), reason, me["id"]))
    log_activity(db, me["id"], "pm_kpi_library", "proposed (%s): %s" % (
        "a new KPI" if kind == "new_kpi" else "a definition change", pl.get("name") or pl.get("kpi_name")))
    db.commit()
    esc = html.escape
    _notify_super_admins(
        db, "A KPI library proposal is waiting for you", "A KPI library proposal is waiting for you",
        ["%s has proposed %s for %s's library:" % (esc(me["full_name"] or me["username"]),
                                                    "a new KPI" if kind == "new_kpi" else "a change to a definition",
                                                    esc(display_bg(bg))),
         "Approve it, point them to a KPI the library has, or reject it with a reason. They get one email either way."],
        box=_em_box(["<b>%s</b>" % esc(pl.get("name") or pl.get("kpi_name")),
                     esc(pl.get("definition") or ""), "Their reason: &ldquo;%s&rdquo;" % esc(reason)]),
        button=("Open Requests", app_base_url() + url_for("admin_library_requests")))
    flash("Sent to the super admin. You'll see the answer under Requests, and by email.", "ok")
    return redirect(url_for("admin_library_requests"))


@app.route("/admin/performance/library/requests", methods=["GET", "POST"])
@admin_required
def admin_library_requests():
    """Performance > KPI library > Requests (2026-10-18, the libraries canvas board 11): the super admin decides each
    proposal -- approve (the same change the library page makes, in one step), merge into an existing KPI (the proposer
    uses that one, with a Focus), or reject with a reason; a BG or unit admin sees their own proposals and the answers.
    The proposer gets one email either way. Double-confirmed, in the trail."""
    db = get_db()
    me = current_user()
    sup = is_super(me)
    if request.method == "POST":
        if not sup:
            abort(403)
        req = db.execute("SELECT * FROM pm_library_requests WHERE id=? AND status='waiting'",
                         (_form_int("request_id"),)).fetchone()
        if not req:
            flash("That proposal has been decided already.", "error")
            return redirect(url_for("admin_library_requests"))
        act = request.form.get("action")
        pl = json.loads(req["payload_json"])
        note = (request.form.get("note") or "").strip()[:500] or None
        lib_id, word = None, None
        if act == "reject":
            if not note:
                flash("Say why it's rejected: the proposer reads it.", "error")
                return redirect(url_for("admin_library_requests"))
            status, word = "rejected", "rejected"
        elif act == "merge" and req["kind"] == "new_kpi":
            into = (request.form.get("into") or "").strip()
            if not db.execute("SELECT 1 FROM pm_kpi_library WHERE business_group=? AND kpi_name=? AND active=1",
                              (req["business_group"], into)).fetchone():
                flash("Choose the library KPI it's the same as.", "error")
                return redirect(url_for("admin_library_requests"))
            status, word = "merged", "pointed to %s for" % into
            note = note or "Use %s, with a Focus if it's about one thing." % into
        elif act == "approve":
            if req["kind"] == "new_kpi":
                try:
                    lib_id = db.execute(
                        "INSERT INTO pm_kpi_library(business_group, company, department, tier_n, job_grade, kpi_name, "
                        "category, description, unit, method, bu_level, perspective, created_by) VALUES "
                        "(?, ?, '*', 0, '*', ?, ?, ?, ?, ?, ?, ?, ?)",
                        (req["business_group"], pl.get("company") or "*", pl["name"], pl.get("category"),
                         pl["definition"], pl.get("unit"), pl["method"], pl.get("bu_level") or 0, pl.get("perspective"),
                         me["id"])).lastrowid
                except sqlite3.IntegrityError:
                    flash("'%s' is in the library already." % pl["name"], "error")
                    return redirect(url_for("admin_library_requests"))
            else:
                for r in db.execute("SELECT id, kpi_name FROM pm_kpi_library").fetchall():
                    if _kpi_key(r["kpi_name"]) == pl["kpi"]:
                        db.execute("UPDATE pm_kpi_library SET description=?, updated_at=datetime('now'), updated_by=? "
                                   "WHERE id=?", (pl["definition"], me["id"], r["id"]))
            status, word = "approved", "approved"
        else:
            abort(400)
        db.execute("UPDATE pm_library_requests SET status=?, decided_by=?, decided_at=datetime('now'), decision_note=?, "
                   "result_library_id=? WHERE id=?", (status, me["id"], note, lib_id, req["id"]))
        log_activity(db, me["id"], "pm_kpi_library", "request %d %s: %s%s" % (
            req["id"], status, pl.get("name") or pl.get("kpi_name"), ("; " + note) if note else ""))
        db.commit()
        mail = _library_request_email(db, req, word, note or "")
        flash("%s %s. %s" % ((pl.get("name") or pl.get("kpi_name")), status, mail), "ok")
        return redirect(url_for("admin_library_requests"))
    tab = request.args.get("tab") if request.args.get("tab") in ("waiting", "decided") else "waiting"
    where, args = "", []
    if not sup:
        where, args = " WHERE r.created_by=?", [me["id"]]
    rows = [dict(r) for r in db.execute(
        "SELECT r.*, u.full_name AS who, d.full_name AS decider FROM pm_library_requests r LEFT JOIN users u ON "
        "u.id=r.created_by LEFT JOIN users d ON d.id=r.decided_by" + where + " ORDER BY r.id DESC", args)]
    for r in rows:
        r["pl"] = json.loads(r["payload_json"])
        if r["kind"] == "new_kpi":
            r["where"] = ({"bg": display_bg(r["business_group"]) + ", the whole group",
                           "unit": display_company(r["business_group"], r["pl"].get("company"))
                           or r["pl"].get("company"),
                           "jf": None}[r["pl"]["scope"]])
            if r["pl"]["scope"] == "jf":
                t_ = db.execute("SELECT name FROM ja_taxonomy WHERE code=?", (r["pl"]["family"],)).fetchone()
                r["where"] = "%s, %s" % (t_["name"] if t_ else r["pl"]["family"], display_bg(r["business_group"]))
            r["options"] = [x[0] for x in db.execute(
                "SELECT DISTINCT kpi_name FROM pm_kpi_library WHERE business_group=? AND active=1 ORDER BY kpi_name",
                (r["business_group"],))] if sup and r["status"] == "waiting" else []
    n_wait = sum(1 for r in rows if r["status"] == "waiting")
    shown = [r for r in rows if (r["status"] == "waiting") == (tab == "waiting")]
    n_comp = db.execute("SELECT COUNT(*) FROM tc_library_requests WHERE status='waiting'%s" % (
        "" if sup else " AND created_by=?"), () if sup else (me["id"],)).fetchone()[0]
    return render_template("admin_library_requests.html", rows=shown, tab=tab, n_wait=n_wait,
                           n_done=len(rows) - n_wait, sup=sup, lib="kpi", n_other=n_comp)


# The columns an older library file may still carry: read as nothing (the library holds no numbers, Chris 2026-11-02).
_LIB_LEGACY_COLS = (("Rate 1-5", re.compile(r"^(spread )?rate ?[1-5]$")), ("Threshold", re.compile(r"^(spread )?threshold$")),
                    ("Target", re.compile(r"^target$")), ("Multiple", re.compile(r"^multiple$")),
                    ("Excellence", re.compile(r"^(spread )?excellence$")),
                    ("Weightage", re.compile(r"^weight(age)?( default)?$")))


def _kpi_library_ignored(records):
    """(the legacy number columns a library file carries, the rows with a figure in one of them): the Quality step says
    so in one line and the write never reads them."""
    found, rows = [], 0
    for lbl, pat in _LIB_LEGACY_COLS:
        keys = {k for rec in records for k in rec if isinstance(k, str) and pat.match(k.strip().lower())}
        if keys:
            found.append((lbl, keys))
    keys_all = set().union(*[k for _l, k in found]) if found else set()
    for rec in records:
        if any(rec.get(k) is not None and str(rec.get(k)).strip().lower() not in ("", "nan") for k in keys_all):
            rows += 1
    return ([lbl for lbl, _k in found] if rows else []), rows


def _kpi_library_check(db, me, records):
    """The KPI library file's rows, checked, nothing written: (errors [{row, eid, why}], valid [row dicts]). Keyed on
    (business group, company, department, tier, job grade, KPI). A row says what the KPI is: scope, definition, unit,
    method, perspective and BU level; no numbers (Chris, 2026-11-02: an older file's number columns are ignored, see
    _kpi_library_ignored). BU level (optional, 2026-10-26): Yes / No, blank leaves it as it is (a new KPI: No)."""
    scoped_bg = admin_bg_of(me)
    bgs = [scoped_bg] if scoped_bg else org_bgs(db)
    errors, valid, seen = [], [], set()
    for i, rec in enumerate(records, start=2):
        err = lambda why: errors.append({"row": i, "eid": "", "why": why})  # noqa: E731
        bg = _pick(rec, "business group", "bg")
        kpi_name = _pick(rec, "kpi", "kpi name")
        if not bg and not kpi_name:
            continue  # blank line
        if not bg:
            err(f"Row for KPI '{kpi_name}' has no Business Group.")
            continue
        _co_ = _pick(rec, "company", "bu")
        if _co_ and not scoped_bg:   # HR's file still names the group a moved unit left: its lines go under the new group (2026-11-06)
            bg = _unit_canonical(db, bg, _co_)
        if bg not in bgs:
            err(f"'{bg}' is not a Business Group you manage.")
            continue
        if not kpi_name:
            err(f"{bg}: a row is missing its KPI name.")
            continue
        # Blank = the "any" sentinel for that dimension, so a file only has to name the dimensions it scopes on.
        company = _pick(rec, "company", "bu") or "*"
        department = _pick(rec, "department", "dept") or "*"
        job_grade = _pick(rec, "job grade", "jg", "job_grade") or "*"
        tier_raw = _pick(rec, "tier", "tier band", "tier_n")
        try:
            tier_n = int(float(tier_raw)) if tier_raw else 0
        except ValueError:
            tier_n = -1
        if tier_n not in (0, 1, 2, 3, 4):
            err(f"{bg} / {kpi_name}: Tier must be 1, 2, 3, 4 or blank for any tier (got '{tier_raw}').")
            continue
        scope_msg = _pm_library_scope_msg(bg, company, department, tier_n, job_grade)
        key = (bg, company, department, tier_n, job_grade, kpi_name)
        if key in seen:
            err(f"{scope_msg} / '{kpi_name}' appears more than once in the file.")
            continue
        seen.add(key)
        method = _pick(rec, "method").strip().lower()
        if method not in ("more", "less"):
            err(f"{bg} / '{kpi_name}': Method must be More or Less.")
            continue
        if kpi_def_figure_msg(_pick(rec, "kpi description", "description")):
            err(f"{bg} / '{kpi_name}': " + kpi_def_figure_msg(_pick(rec, "kpi description", "description")))
            continue
        bu_raw = _pick(rec, "bu level", "bu-level", "bu_level", "bu kpi").strip().lower()
        if bu_raw not in ("", "yes", "no", "y", "n", "1", "0", "true", "false"):
            err(f"{bg} / '{kpi_name}': BU level must be Yes, No or blank (got '{bu_raw}').")
            continue
        persp_raw = _pick(rec, "perspective")
        persp = next((p for p in PM_PERSPECTIVES if p.lower() == persp_raw.lower()), None) if persp_raw else None
        if persp_raw and not persp:
            err(f"{bg} / '{kpi_name}': Perspective must be Financial, Customer, Internal Process, Learning & Growth "
                f"or blank (got '{persp_raw}').")
            continue
        valid.append({
            "row": i, "business_group": bg, "company": company, "department": department, "tier_n": tier_n,
            "job_grade": job_grade, "kpi_name": kpi_name, "scope_msg": scope_msg,
            "category": _pick(rec, "strategic thrust / category", "category") or None,
            "description": _pick(rec, "kpi description", "description") or None,
            "unit": kpi_unit_normalise(_pick(rec, "unit of measure", "unit")),
            "method": method,
            "perspective": persp,
            "bu_level": None if not bu_raw else (1 if bu_raw in ("yes", "y", "1", "true") else 0),
        })
    return errors, valid


_LIB_FIELDS = (("category", "Category"), ("description", "Definition"), ("unit", "Unit"), ("method", "Direction"),
               ("perspective", "Perspective"))


def _pm_lib_named_ids(db):
    """The library rows that name people, in one read (a database from before the table: none)."""
    try:
        return {r[0] for r in db.execute("SELECT DISTINCT library_id FROM pm_kpi_library_people")}
    except sqlite3.OperationalError:
        return set()


def _kpi_library_write(db, me, valid, merge=(), bu_keep=()):
    """Write checked library rows: a match on the scope key updates it in place, else a new row. `merge` -- the
    file rows (by row number) the super admin merged into a KPI already in the library: no row, the file's name an
    alias of it (pm_kpi_aliases 'dupe'); `bu_keep` -- rows whose BU-level mark stays as it is. (created, updated,
    merged)."""
    created = updated = merged = 0
    named = _pm_lib_named_ids(db)
    for r in valid:
        if r["row"] in merge:
            into = merge[r["row"]]
            db.execute("INSERT OR IGNORE INTO pm_kpi_aliases(business_group, alias_key, alias_name, into_key, into_name, "
                       "kind, created_by) VALUES (?,?,?,?,?, 'dupe', ?)", (r["business_group"], _kpi_key(r["kpi_name"]),
                                                                          r["kpi_name"], _kpi_key(into), into, me["id"]))
            merged += 1
            continue
        existing = db.execute(
            "SELECT id, bu_level FROM pm_kpi_library WHERE business_group=? AND company=? AND department=? AND tier_n=? "
            "AND job_grade=? AND kpi_name=?", (r["business_group"], r["company"], r["department"], r["tier_n"],
                                              r["job_grade"], r["kpi_name"])).fetchone()
        bu = r["bu_level"] if r["bu_level"] is not None and r["row"] not in bu_keep else None
        if bu and existing and existing["id"] in named:
            bu = None   # a row that names people is a person's own KPI: its mark stays as it is
        if existing:
            db.execute(
                "UPDATE pm_kpi_library SET category=?, description=?, unit=?, method=?, perspective=COALESCE(?, perspective), "
                "bu_level=COALESCE(?, bu_level), active=1, updated_at=datetime('now'), updated_by=? WHERE id=?",
                (r["category"], r["description"], r["unit"], r["method"], r["perspective"], bu, me["id"],
                 existing["id"]))
            updated += 1
        else:
            db.execute(
                "INSERT INTO pm_kpi_library(business_group, company, department, tier_n, job_grade, kpi_name, category, "
                "description, unit, method, perspective, bu_level, created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (r["business_group"], r["company"], r["department"], r["tier_n"], r["job_grade"], r["kpi_name"],
                 r["category"], r["description"], r["unit"], r["method"], r["perspective"], bu or 0, me["id"]))
            created += 1
    return created, updated, merged


# The KPI library import in the four steps (2026-10-26), the super admin's (the libraries are theirs, 2026-10-18). Two
# answers at step 3: a NEW KPI whose name is close to one the group's library has (merge it in, its name an alias of
# that KPI; or add it as new), and a row that marks or unmarks BU level on a KPI people carry in the active cycle
# (change it, or leave it as it is).
def _limp_load(db, me, meta, data):
    records = _read_records(meta["filename"], data)
    errors, valid = _kpi_library_check(db, me, records)
    ign_cols, ign_rows = _kpi_library_ignored(records)
    bgs = sorted({r["business_group"] for r in valid})
    lib = {}
    for bg in bgs:
        for x in db.execute("SELECT * FROM pm_kpi_library WHERE business_group=?", (bg,)):
            lib.setdefault(bg, []).append(dict(x))
    act = active_cycle(db)
    named_ids = _pm_lib_named_ids(db)
    carried = Counter()
    if act and bgs:
        for bg_, nm, n in db.execute("SELECT business_group, kpi_name, COUNT(DISTINCT subject_id) FROM pm_kpi_targets "
                                     "WHERE cycle_id=? AND business_group IN (%s) GROUP BY business_group, kpi_name" %
                                     ",".join("?" * len(bgs)), [act["id"]] + bgs):
            carried[(bg_, _kpi_key(nm))] += n
    for r in valid:
        rows = lib.get(r["business_group"]) or []
        key = (r["company"], r["department"], r["tier_n"], r["job_grade"], r["kpi_name"])
        ex = next((x for x in rows if (x["company"], x["department"], x["tier_n"], x["job_grade"], x["kpi_name"]) == key),
                  None)
        r["ex"] = ex
        r["ex_named"] = bool(ex and ex["id"] in named_ids)
        r["fields"] = [lbl for c, lbl in _LIB_FIELDS if ex and not (c == "perspective" and r.get(c) is None)
                       and not _imp_same(ex.get(c), r.get(c))] if ex else []
        k = _kpi_key(r["kpi_name"])
        r["named"] = any(_kpi_key(x["kpi_name"]) == k and x["active"] for x in rows)
        r["bu_now"] = 1 if any(_kpi_key(x["kpi_name"]) == k and x["active"] and x["bu_level"] for x in rows) else 0
        r["carried"] = carried[(r["business_group"], k)]
        r["close"] = None
        if not ex and not r["named"]:
            near = _kpi_closest(db, r["business_group"], r["kpi_name"])
            if near and near[0][1] >= 0.5 and _kpi_key(near[0][0]) != k:
                r["close"] = near[0]
    look = {"ignored": [{"row": None, "eid": "", "rows": [],
                         "detail": "Ignored: %s (in %d row%s). The library holds no numbers." % (
                             ", ".join(ign_cols), ign_rows, "" if ign_rows == 1 else "s")}]} if ign_cols else {}
    return {"errors": errors, "rows": len(valid) + len(errors), "valid": valid, "look": look}


def _imp_same(a_, b_):
    """Two stored values the same, numbers by value ('3' and 3.0 alike)."""
    if a_ in (None, "") and b_ in (None, ""):
        return True
    try:
        return float(a_) == float(b_)
    except (TypeError, ValueError):
        return str(a_) == str(b_)


def _limp_scope(r):
    """Where a library row applies, in words: the group, then any unit, department, grade band and job grade it names."""
    parts = [display_company(r["business_group"], r["company"]) or r["company"]] if r["company"] != "*" else []
    if r["department"] != "*":
        parts.append(proper_name(r["department"]))
    if r["tier_n"]:
        parts.append("grade band %d" % r["tier_n"])
    if r["job_grade"] != "*":
        parts.append("JG %s" % r["job_grade"])
    return "%s%s" % (display_bg(r["business_group"]), (" · " + ", ".join(parts)) if parts else ", the whole group")


def _limp_bu_held(r):
    """The file marks BU-level a row that names people: the writer leaves its mark as it is."""
    return bool(r["bu_level"]) and r.get("ex_named")


def _limp_bu_asked(r):
    return (r["bu_level"] is not None and r["bu_level"] != r["bu_now"] and r["carried"] > 0
            and not _limp_bu_held(r))


def _limp_answers(ctx, decisions):
    merge = {r["row"]: r["close"][0] for r in ctx["valid"]
             if r["close"] and decisions.get("near:%d" % r["row"]) == "merge"}
    bu_keep = {r["row"] for r in ctx["valid"] if _limp_bu_asked(r) and decisions.get("bu:%d" % r["row"]) == "no"}
    return merge, bu_keep


def _limp_says(r, merge, bu_keep):
    if r["row"] in merge:
        return "Merged into %s: its name becomes an alias" % merge[r["row"]]
    says = ("Updated: " + ", ".join(r["fields"])) if r["ex"] and r["fields"] else (
        "No change to its words" if r["ex"] else "Added")
    if _limp_bu_held(r):
        says += "; names people: its BU-level mark stays as it is"
    elif r["bu_level"] is not None and r["bu_level"] != r["bu_now"]:
        says += ("; BU level left as it is" if r["row"] in bu_keep else
                 "; marked BU-level" if r["bu_level"] else "; no longer BU-level")
    return says


def _limp_changes(db, me, ctx, decisions):
    valid = ctx["valid"]
    n_add, n_upd = sum(1 for r in valid if not r["ex"]), sum(1 for r in valid if r["ex"] and r["fields"])
    n_bu = sum(1 for r in valid if r["bu_level"] is not None and r["bu_level"] != r["bu_now"] and not _limp_bu_held(r))
    tiles = [(n_add, "KPI%s to add" % ("" if n_add == 1 else "s"), "#1a7a54")]
    if n_upd:
        tiles.append((n_upd, "to update", "#2f64d6"))
    if n_bu:
        tiles.append((n_bu, "BU-level mark changes" if n_bu == 1 else "BU-level marks change", "#252A59"))
    if any(r["ex"] and not r["fields"] for r in valid):
        tiles.append((sum(1 for r in valid if r["ex"] and not r["fields"]), "no change", "#9aa1b5"))
    sections = [{"title": "Each KPI", "dl": "changes", "head": ["KPI", "Scope", "What it does"],
                 "rows": [[r["kpi_name"], _limp_scope(r), _limp_says(r, {}, set())] for r in valid[:15]],
                 "more": max(0, len(valid) - 15)}]
    near = [r for r in valid if r["close"]]
    bu = [r for r in valid if _limp_bu_asked(r)]
    decide = []
    if near:
        decide.append({"title": "A new name close to a KPI the library has (%d)" % len(near),
                       "why": "Merge it in: no new KPI; the file's name becomes another name for the library's, so a "
                              "line under it matches. Add it as new: a KPI of its own.",
                       "options": [("merge", "Merge it in"), ("new", "Add as new")],
                       "head": ["KPI in the file", "Scope", "Closest in the library"],
                       "items": [{"key": "near:%d" % r["row"], "label": "%s, close to %s" % (r["kpi_name"], r["close"][0]),
                                  "cells": [r["kpi_name"], _limp_scope(r), (r["close"][0], "%d%% of the words shared" %
                                                                            round(r["close"][1] * 100))]}
                                 for r in near]})
    if bu:
        decide.append({"title": "BU level changes on a KPI people carry (%d)" % len(bu),
                       "why": "A BU-level KPI is one figure Group People fills for the whole unit, and the people carrying "
                              "it don't enter it. Change it: the file's mark applies. Leave it as it is: the rest of the "
                              "row still goes in.",
                       "options": [("yes", "Change it"), ("no", "Leave it as it is")],
                       "head": ["KPI", "Now", "The file says", "People carrying it"],
                       "items": [{"key": "bu:%d" % r["row"], "label": "%s: %s" % (
                           r["kpi_name"], "mark BU-level" if r["bu_level"] else "no longer BU-level"),
                                  "cells": [(r["kpi_name"], _limp_scope(r)), "BU-level" if r["bu_now"] else "Personal",
                                            "BU-level" if r["bu_level"] else "Personal", r["carried"]]} for r in bu]})
    fp = [(r["row"], r["kpi_name"], bool(r["ex"]), tuple(r["fields"]), r["bu_now"], r["carried"],
           r["close"][0] if r["close"] else None) for r in valid]
    return {"tiles": tiles, "sections": sections, "decide": decide, "fp": fp}


def _limp_after(db, me, ctx, decisions):
    merge, bu_keep = _limp_answers(ctx, decisions)
    valid = ctx["valid"]
    add = sum(1 for r in valid if not r["ex"] and r["row"] not in merge)
    upd = sum(1 for r in valid if r["ex"])
    tiles = [(add, "added", "#1a7a54"), (upd, "updated", "#2f64d6")]
    if merge:
        tiles.append((len(merge), "merged in", "#252A59"))
    return {"lede": "%d KPI%s in the file." % (len(valid), "" if len(valid) == 1 else "s"), "tiles": tiles,
            "table_title": "Each KPI after the import", "head": ["KPI", "Scope", "What happens"],
            "rows": [[r["kpi_name"], _limp_scope(r), _limp_says(r, merge, bu_keep)] for r in valid[:30]],
            "more": max(0, len(valid) - 30),
            "confirm": "Import %d KPI%s to the library? %d added and %d updated%s. The backup taken first is the way "
                       "back." % (len(valid), "" if len(valid) == 1 else "s", add, upd,
                                  (", %d merged into a KPI it has" % len(merge)) if merge else "")}


def _limp_apply(db, me, ctx, decisions):
    merge, bu_keep = _limp_answers(ctx, decisions)
    created, updated, merged = _kpi_library_write(db, me, ctx["valid"], merge, bu_keep)
    db.commit()
    marks = [r["kpi_name"] for r in ctx["valid"] if r["bu_level"] is not None and r["bu_level"] != r["bu_now"]
             and r["row"] not in bu_keep and r["row"] not in merge and not _limp_bu_held(r)]
    log_activity(db, me["id"], "pm_kpi_library_import", "%d created, %d updated%s%s%s" % (
        created, updated, (", %d merged in (%s)" % (merged, "; ".join("%s into %s" % (r["kpi_name"], merge[r["row"]])
                                                                    for r in ctx["valid"] if r["row"] in merge)[:600]))
        if merged else "", ("; BU level changed: %s" % ", ".join(marks[:40])) if marks else "",
        ("; the super admin left %d BU-level mark(s) as they were" % len(bu_keep)) if bu_keep else ""))
    return {"summary": "Library import: %d added, %d updated%s." % (created, updated,
                                                                  (", %d merged in" % merged) if merged else ""),
            "lines": (["%d BU-level mark%s changed." % (len(marks), "" if len(marks) == 1 else "s")] if marks else [])}


def _limp_downloads(db, me, ctx, decisions, what):
    merge, bu_keep = _limp_answers(ctx, decisions) if what == "final" else ({}, set())
    return ("changes" if what == "changes" else "final-preview"), ["Business group", "KPI", "Scope", "What happens"], [
        [r["business_group"], r["kpi_name"], _limp_scope(r), _limp_says(r, merge, bu_keep)] for r in ctx["valid"]]


_imp_register(
    "library", page="admin_kpi_library_import", dl="admin_kpi_library_import_check", file="kpi-library",
    load=_limp_load, changes=_limp_changes, after=_limp_after, apply=_limp_apply, downloads=_limp_downloads,
    fix_kinds=(("A group you don't manage", r"not a Business Group you manage"), ("No Business Group", r"no Business "
               "Group"), ("No KPI name", r"missing its KPI name"), ("A grade band that isn't 1 to 4", r"Tier must"),
               ("In the file twice", r"more than once"), ("Direction not More or Less", r"Method must"),
               ("A figure in the definition", r"definition|figure"), ("BU level not Yes or No", r"BU level must"),
               ("Perspective not one of the four", r"Perspective must")),
    look=(("ignored", "set of number columns is ignored", "sets of number columns are ignored",
           "The library holds no numbers: targets, rates and weights are set on each person's line."),),
    look_skips=("ignored",),
    checks=("a group you don't manage, a row with no group or KPI name, a grade band that isn't 1 to 4, a direction "
            "that isn't More or Less, a figure in the definition, a BU level that isn't Yes or No, a perspective that "
            "isn't one of the four, the same KPI twice.",
            "Rate, Threshold, Target, Multiple, Excellence, Weightage or Spread columns: they are ignored."))


@app.route("/admin/performance/library/import", methods=["GET", "POST"])
@admin_required
def admin_kpi_library_import():
    """Bulk-import KPI Library rows, keyed on (business_group, company, department, tier_n, job_grade, kpi_name): the
    business group / department / tier come from the FILE (the library is not per person), and each row's numeric
    columns must match that BG's own pm_bg_config mechanism. The super admin's (2026-10-18). In four steps since
    2026-10-26 (_imp_post): a new name close to a library KPI and a BU-level change on a KPI people carry are asked.
    A post without the steps changes nothing (_imp_steps_only)."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        if not is_super(me):   # the super admin edits the libraries (Chris, 2026-10-18)
            abort(403)
        if (request.form.get("token") or "").strip():
            return _imp_post("library", db, me)
        if request.form.get("preview") == "1":
            return _imp_upload("library", db, me)
        return _imp_steps_only("admin_kpi_library_import")
    v, done = _imp_get("library", db, me) if is_super(me) else (None, None)
    return render_template("admin_kpi_library_import.html", v=v, done=done, is_super=is_super(me))


@app.route("/admin/performance/library/import/check/<token>.xlsx")
@super_required
def admin_kpi_library_import_check(token):
    """A kept KPI library file's issues, each KPI, or the final preview (_imp_download)."""
    return _imp_download("library", get_db(), current_user(), token)


# The KPI library import's columns, in order: its template and the KPI library download (Reports, 10 Nov 2026) both use them, so
# the file that comes out goes back in with nothing changed
KPI_LIBRARY_IMPORT_HEAD = ("Business Group", "Company", "Department", "Tier", "Job Grade", "KPI",
                           "Strategic Thrust / Category", "KPI Description", "Unit of Measure", "Method", "Perspective", "BU Level")


@app.route("/admin/performance/library/template.csv")   # the old address, kept
@app.route("/admin/performance/library/template.xlsx")
@admin_required
def admin_kpi_library_template():
    """Template for the KPI Library import, keyed on Business Group + Company + Department + Tier + Job Grade + KPI.
    What a KPI IS only: no target, rate or weight columns (Chris, 2026-11-02). Example rows are EXAMPLE- placeholders."""
    header = list(KPI_LIBRARY_IMPORT_HEAD)
    # Blank in Company / Department / Tier / Job Grade means "any" -- so row 1 is a BG-wide KPI, row 2 is scoped to
    # one company + department + grade. No figures: the library holds no numbers (Chris, 2026-11-02).
    rows = [
        ["EXAMPLE-Business Group", "", "", 2, "", "EXAMPLE-Sales contribution", "EXAMPLE-Financial · Sales",
         "EXAMPLE: what is measured, and how", "RM", "More", "Financial", "No"],
        ["EXAMPLE-Business Group", "EXAMPLE-Company", "EXAMPLE-Department", "", 14, "EXAMPLE-Profit after tax",
         "EXAMPLE-Financial · Profitability", "EXAMPLE: the unit's profit after tax", "RM", "More", "Financial", "Yes"],
    ]
    return _csv_response("pm_kpi_library_template.csv", header, rows)


@app.route("/admin/performance/exceptions")
@admin_required
def admin_performance_exceptions():
    """KPI lines for the active period with zero resolved approvers (mostly
    the ~230+ no-reliable-manager_id cohort) -- an admin/HR exception list for
    manual assignment, never silently excluded or auto-routed to HOD, per the
    confirmed requirement. A BU-level line admin-filled via
    admin_performance_bu_fill() is ALSO chainless by design (it deliberately
    skips approver review) -- excluded here so it doesn't nag forever for an
    approver assignment it will never need."""
    db = get_db()
    period = active_pm_period(db)
    if not period:
        flash("No active performance period.", "error")
        return redirect(url_for("admin_cycles"))
    # t.business_group, not the default unqualified "business_group" -- both
    # pm_kpi_targets and the joined users table have that column, and an
    # unqualified reference is ambiguous (throws for any BG-scoped admin).
    bclause, bparams = bg_scope(current_user(), "t.business_group")
    # Two ways a line can be un-approvable, and only the first was ever listed.
    # A line whose approver has LEFT still has an approver row, so NOT EXISTS
    # never matched it: the KPI routes to an account that can no longer sign in
    # (app.py's login blocks a user with left_at), and _mark_user_inactive()
    # touches users and 360 assignments only, never a PM table. The line then
    # sits submitted forever, on no screen anywhere.
    #
    # `acted` is carried because it decides whether the repair form below can
    # safely replace the chain -- see admin_performance_exceptions_assign().
    rows = db.execute(
        f"SELECT t.*, u.full_name, u.employee_id, "
        f"       (SELECT COUNT(*) FROM pm_kpi_approvals k WHERE k.kpi_target_id = t.id) AS acted, "
        f"       (SELECT GROUP_CONCAT(au.full_name, ', ') FROM pm_kpi_target_approvers a "
        f"          JOIN users au ON au.id = a.approver_id "
        f"         WHERE a.kpi_target_id = t.id AND COALESCE(au.left_at,'') != '') AS gone, "
        f"       CASE WHEN NOT EXISTS (SELECT 1 FROM pm_kpi_target_approvers a "
        f"                              WHERE a.kpi_target_id = t.id) "
        f"            THEN 'none' ELSE 'left' END AS reason "
        f"FROM pm_kpi_targets t "
        f"JOIN users u ON u.id = t.subject_id "
        f"WHERE t.cycle_id=? AND ("
        f"  NOT EXISTS (SELECT 1 FROM pm_kpi_target_approvers a WHERE a.kpi_target_id = t.id) "
        f"  OR EXISTS (SELECT 1 FROM pm_kpi_target_approvers a JOIN users au ON au.id = a.approver_id "
        f"             WHERE a.kpi_target_id = t.id AND COALESCE(au.left_at,'') != '')) "
        f"AND NOT EXISTS "
        f"(SELECT 1 FROM pm_kpi_results r WHERE r.kpi_target_id = t.id AND r.admin_filled=1)"
        f"{_pm_chair_unmod_sql(db, 'u')}"   # the Executive Chairman's direct reports have no moderator by design (2026-11-03)
        f"{bclause} ORDER BY u.full_name, t.kpi_name",
        [period["id"]] + bparams).fetchall()
    # business group, unit and department as rows over the list (the admin table standard, 2026-10-11), not column
    # filters; the person's own unit and department
    frows, fsel = admin_filter_rows(db, current_user(), "admin_performance_exceptions")
    if fsel["bg"]:
        rows = [r for r in rows if r["business_group"] == fsel["bg"]]
    if fsel["bu"]:
        rows = [r for r in rows if (r["company"] or "") == fsel["bu"]]
    if fsel["dept"]:
        rows = [r for r in rows if (r["department"] or "").strip() == fsel["dept"]]
    return render_template("admin_performance_exceptions.html", period=period, rows=rows, frows=frows)


@app.route("/admin/performance/exceptions/assign", methods=["POST"])
@admin_required
def admin_performance_exceptions_assign():
    """Manually assign a single-approver chain to one exception row."""
    db = get_db()
    me = current_user()
    tid = _form_int("kpi_target_id")
    eid = (request.form.get("approver_employee_id", "") or "").strip()
    target = db.execute(
        "SELECT t.*, u.full_name FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
        "WHERE t.id=?", (tid,)).fetchone()
    if not target:
        flash("KPI line not found.", "error")
        return redirect(url_for("admin_performance_exceptions"))
    if not can_access(me, target["business_group"], target["company"]):
        abort(403)
    approver = db.execute(
        "SELECT id, full_name, left_at FROM users WHERE employee_id=? AND role!='admin'",
        (eid,)).fetchone()
    if not approver:
        flash(f"'{eid}' is not a valid Employee ID.", "error")
        return redirect(url_for("admin_performance_exceptions"))
    # This page exists to repair lines pointing at someone who has gone, so
    # pointing one at another leaver is the one mistake worth refusing outright.
    if approver["left_at"]:
        flash(f"{approver['full_name']} has left, so the line would still be stuck. "
              "Choose someone currently employed.", "error")
        return redirect(url_for("admin_performance_exceptions"))
    if approver["id"] == target["subject_id"]:
        flash("Nobody can moderate their own KPI line.", "error")
        return redirect(url_for("admin_performance_exceptions"))
    if _pm_chair_unmod_subject(db, target["subject_id"]):   # the Executive Chairman's direct reports (2026-11-03)
        flash(_PM_CHAIR_UNMOD_WHY, "error")
        return redirect(url_for("admin_performance_exceptions"))

    # Preserve the acted prefix. pm_next_approver() looks for the approver whose
    # seq equals (recorded approvals + 1), so replacing a chain where step 1 has
    # already approved with a single row at seq=1 leaves NOTHING matching, and
    # the line becomes permanently unactionable -- worse than the state we are
    # repairing. Insert AFTER whatever has been acted on, and only clear the
    # rows beyond it.
    acted = db.execute("SELECT COUNT(*) FROM pm_kpi_approvals WHERE kpi_target_id=?",
                       (tid,)).fetchone()[0]
    db.execute("DELETE FROM pm_kpi_target_approvers WHERE kpi_target_id=? AND seq > ?",
               (tid, acted))
    db.execute("INSERT INTO pm_kpi_target_approvers(kpi_target_id, seq, approver_id) "
               "VALUES (?,?,?)", (tid, acted + 1, approver["id"]))
    db.commit()
    log_activity(db, me["id"], "pm_exception_assign",
                 f"{target['full_name']}: '{target['kpi_name']}' approver set to {approver['full_name']}")
    flash(f"{approver['full_name']} now moderates {target['full_name']}'s '{target['kpi_name']}'.", "ok")
    return redirect(url_for("admin_performance_exceptions"))


# ---- BU KPI setup (2026-10-18, the libraries canvas board 4) ----------------------------------------------------------
# A BU KPI's weight follows the person's grade (Chris, 2026-10-26: "weightage would follow job grade, e.g. 12-15 can carry
# 15%, 16-18 carries 20%, 19 and above 25%"), from an Early Year on; the super admin sets each BU KPI's bands ("super
# admin to define and decide"), and a new one starts from these.
BU_KPI_BANDS_DEFAULT = [{"min": 19, "max": None, "w": 25}, {"min": 16, "max": 18, "w": 20}, {"min": None, "max": 15, "w": 15}]
# the library's number columns: kept in the schema, empty, never read or written (test_kpi_library_no_numbers)
_LIB_NUMBER_COLS = ("rate1", "rate2", "rate3", "rate4", "rate5", "threshold", "target", "multiple", "excellence",
                    "weightage_default", "spread_json")
_BU_SCALE_COLS = ("rate1", "rate2", "rate3", "rate4", "rate5", "threshold", "target", "multiple", "excellence")


def _bu_unit_people(db, bg, co):
    """Everyone in this unit taking part in the active cycle, by name: [dict]. One query."""
    return [dict(r) for r in db.execute(
        "SELECT id, employee_id, full_name, department, job_grade, manager_id, business_group, company FROM users "
        "WHERE business_group=? AND company=? AND role!='admin' AND COALESCE(is_demo,0)=0 AND " + participant_sql(module='pm')
        + " ORDER BY full_name", (bg, co))]


def _bu_band_of(bands, g):
    """The grade band (a dict with min / max, either None for open) that grade g falls in, or None."""
    if g is None:
        return None
    for b in bands or []:
        if (b.get("min") is None or g >= b["min"]) and (b.get("max") is None or g <= b["max"]):
            return b
    return None


def _bu_kpi_guests(s):
    """The guest carriers of a BU KPI setup (a pm_bu_kpis row or its dict): {Employee ID (ja_eid): their weight}. A guest is
    someone in ANOTHER unit of the setup's own business group who carries the unit's BU KPI (2026-11-07, Chris: "a person in BU 1
    carries BU 2's BU KPI"); `carriers_json["guests"]` holds them, whatever the carrier mode. Tolerates a missing or bad JSON,
    a missing or bad weight (that guest's weight is then None: their line's own weight rules) and a guests value that is not a map."""
    try:
        data = json.loads(s["carriers_json"]) if s["carriers_json"] else {}
    except (ValueError, TypeError):
        return {}
    g = data.get("guests") if isinstance(data, dict) else None
    if not isinstance(g, dict):
        return {}
    out = {}
    for e, w in g.items():
        e = ja_eid(e)
        if not e:
            continue
        try:
            w = float(w)
            w = w if w == w and w not in (float("inf"), float("-inf")) else None
        except (TypeError, ValueError):
            w = None
        out[e] = w
    return out


def _bu_kpi_pool(db, act, s, people):
    """Everyone a BU KPI setup's lines are (re)applied to: the unit's `people` as passed, plus its guests who take part
    (`_bu_kpi_guests`: same business group as the setup, `participant_sql(module='pm')`, not an admin, not a demo), deduped by id,
    the unit's own first. ONE batched read (900 Employee IDs a query); with no guests it is `people` as it came. Every writer that
    applies a setup to "everyone it covers" (the card's save, taking the KPI off the unit, a move to a variant, the carriers a card
    lists) goes through here, so a guest is never forgotten or applied twice."""
    out = list(people)
    guests = _bu_kpi_guests(s)
    if not guests:
        return out
    have = {p["id"] for p in out}
    ids = sorted(guests)
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        for r in db.execute(
                "SELECT id, employee_id, full_name, department, job_grade, manager_id, business_group, company FROM users "
                "WHERE business_group=? AND role!='admin' AND COALESCE(is_demo,0)=0 AND UPPER(TRIM(employee_id)) IN (%s) AND "
                % ",".join("?" * len(part)) + participant_sql(module='pm') + " ORDER BY full_name",
                [s["business_group"]] + part):
            if r["id"] not in have and ja_eid(r["employee_id"]) in guests:
                have.add(r["id"])
                out.append(dict(r))
    return out


def _bu_guest_drop(data, eid):
    """Take `eid` out of a setup's carriers_json map `data` (the dict, changed in place) -- "guests", and the key itself when it is left
    empty (the one place a guest is kept, so every writer that takes one off does it here): whether they were a guest."""
    was = eid in _bu_kpi_guests({"carriers_json": json.dumps(data)})
    if was:
        data["guests"] = {e: w for e, w in (data.get("guests") or {}).items() if ja_eid(e) != eid}
        if not data["guests"]:
            del data["guests"]
    return was


def _bu_kpi_covers(s, person):
    """Whether a BU KPI setup (a pm_bu_kpis row or its dict) puts its line on this person of its unit: everyone, their
    department, their grade range, picked by Employee ID, or one of those who carried it when it was saved ('holders',
    2026-10-23, their Employee IDs kept like a pick's). A guest of the setup (`_bu_kpi_guests`) is covered whatever the mode."""
    if ja_eid(person["employee_id"]) in _bu_kpi_guests(s):
        return True
    try:   # the setup is the UNIT's: someone of another unit is covered only as its guest (a caller passing the unit's people never notices)
        if (person["business_group"], person["company"]) != (s["business_group"], s["company"]):
            return False
    except (KeyError, IndexError, TypeError):
        pass
    mode = s["carriers"]
    data = json.loads(s["carriers_json"]) if s["carriers_json"] else {}
    if mode == "everyone":
        return True
    if mode == "departments":
        return (person["department"] or "").strip() in set(data.get("departments") or [])
    if mode == "grade":
        g = grade_num(person["job_grade"])
        return g is not None and (data.get("min") is None or g >= data["min"]) and (
            data.get("max") is None or g <= data["max"])
    if mode in ("pick", "holders"):
        return ja_eid(person["employee_id"]) in set(data.get("people") or [])
    return False


def _bu_kpi_weight(s, person, line=None):
    """The weight a BU KPI setup gives this person's line: the one weight, or their grade band's; None when their grade
    falls in no band (a letter grade). 'own' (2026-10-23): the weight on the line they hold now; with no line, the weight the
    save that is adding them gave them (carriers_json "added_w", 2026-11-06), else None. A guest (2026-11-07) keeps their
    OWN weight whatever the mode: the weight on the line they hold, else the one given when they were added ("guests")."""
    guests = _bu_kpi_guests(s)
    if guests and ja_eid(person["employee_id"]) in guests:
        if line and line["weightage"] is not None:
            return line["weightage"]
        return guests[ja_eid(person["employee_id"])]
    if s["weight_mode"] == "own":
        if line:
            return line["weightage"]
        # no line yet: someone the super admin is adding in this save (2026-11-06) takes the weight given to them there
        try:
            added = (json.loads(s["carriers_json"] or "{}") or {}).get("added_w") or {}
        except ValueError:
            added = {}
        return added.get(ja_eid(person["employee_id"]))
    if s["weight_mode"] == "grade":
        b = _bu_band_of(json.loads(s["bands_json"] or "[]"), grade_num(person["job_grade"]))
        return b["w"] if b else None
    return s["weight"]


def _bu_kpi_lib(db, bg, co):
    """The BU-level KPIs of the library a unit can pick from: active, bu_level, its group's, BG-wide or the unit's own
    (the unit's own row wins over a BG-wide one of the same name), by name."""
    best = {}
    for r in db.execute("SELECT * FROM pm_kpi_library WHERE active=1 AND bu_level=1 AND business_group=? "
                        "AND company IN ('*', ?) ORDER BY (company='*'), id", (bg, co)):
        best.setdefault(" ".join((r["kpi_name"] or "").lower().split()), dict(r))
    return sorted(best.values(), key=lambda r: (r["kpi_name"] or "").lower())


def _bu_kpi_state(db, act):
    """BU KPI setup on the active cycle: (open, the note to show). An Early Year, where KPIs are set: open. Any other
    cycle: open until the HOD Department Review starts (pm_hod), then it reads only. Chris, 2026-11-03: open until the
    HOD Department Review starts, and a change reaches every line in the unit, those with results too (it was open
    until the results check-in started, 2026-10-23: "BU KPI should be enabled anytime before the start date of the KPI
    result entry")."""
    if not act:
        return False, "There is no active cycle, so nothing can be set."
    if cycle_row_is_early_year(act):
        return True, None
    opens, _closes = window_dates(db, "pm_hod", act["id"])
    if window_state(db, "pm_hod", act["id"]) == "not_open":
        return True, ("Open until the Department Review starts on %s." % _when_disp(opens) if _parse_when(opens)
                      else "Open until the Department Review starts. Its start date isn't set yet.")
    return False, ("The Department Review started on %s, so BU KPIs read only." % _when_disp(opens)
                   if _parse_when(opens) else "The Department Review is open, so BU KPIs read only.")


def _bu_kpi_facts(db, act, bg, co):
    """What the people taking part hold on the active cycle, by KPI name (folded): ({key: the unit's facts}, {key: how
    many in the group}). A unit fact: n, eids (Employee IDs), depts, scales (the different targets held), wmin / wmax
    (their weights), scale (the one target when all hold the same), n_keys (how many different targets, each counted
    with its unit), major (the target, with its unit, held by the most carriers: the _BU_SCALE_COLS figures plus
    "unit" and "n"; None when two or more targets tie for the most). One read for the group."""
    unit, grp = {}, {}
    if not act:
        return unit, grp
    for r in db.execute(
            "SELECT t.id AS tid, t.method, t.kpi_name, t.weightage, t.unit, t.bu_kpi_id, %s, u.employee_id, u.company, u.department FROM pm_kpi_targets t "
            "JOIN users u ON u.id=t.subject_id WHERE t.cycle_id=? AND u.business_group=? AND u.role!='admin' "
            "AND COALESCE(u.is_demo,0)=0 AND %s" % (", ".join("t." + c for c in _BU_SCALE_COLS),
                                                    participant_sql("u", "pm")), (act["id"], bg)):
        k = _kpi_key(r["kpi_name"])
        grp[k] = grp.get(k, 0) + 1
        if r["company"] != co:
            continue
        f = unit.setdefault(k, {"n": 0, "eids": set(), "depts": set(), "scales": set(), "wmin": None, "wmax": None,
                                "lines": {}, "held": {}})
        f["n"] += 1
        f["eids"].add(ja_eid(r["employee_id"]))
        f["lines"][ja_eid(r["employee_id"])] = dict(r)   # the holder's own line today, for the card's holder list
        if (r["department"] or "").strip():
            f["depts"].add(r["department"].strip())
        f["scales"].add(tuple(r[c] for c in _BU_SCALE_COLS))
        mk = (kpi_unit_normalise(r["unit"]) or "", tuple(r[c] for c in _BU_SCALE_COLS))
        f["held"][mk] = f["held"].get(mk, 0) + 1
        w = r["weightage"]
        if w is not None:
            f["wmin"] = w if f["wmin"] is None else min(f["wmin"], w)
            f["wmax"] = w if f["wmax"] is None else max(f["wmax"], w)
    for f in unit.values():
        f["scale"] = dict(zip(_BU_SCALE_COLS, next(iter(f["scales"])))) if len(f["scales"]) == 1 else None
        top = max(f["held"].values())
        best = [k_ for k_, n_ in f["held"].items() if n_ == top]
        f["n_keys"] = len(f["held"])
        f["major"] = (dict(zip(_BU_SCALE_COLS, best[0][1]), unit=best[0][0], n=top) if len(best) == 1 else None)
        del f["held"]
    return unit, grp


def _bu_line_cells(line, mech):
    """What a holder's line holds today, for the holder list on a BU KPI card: (weight text, target text), "—" for a
    missing value. A 5-point rating line reads its five figures; a target line its target (and excellence), with the unit."""
    def g(v):
        return "—" if v is None else "%g" % v
    w = "—" if not line or line.get("weightage") is None else "%g%%" % line["weightage"]
    if not line:
        return w, "—"
    if mech == "A":
        vals = [line.get("rate%d" % i) for i in range(1, 6)]
        t = "—" if all(v is None for v in vals) else " / ".join(g(v) for v in vals)
    else:
        t = "—" if line.get("target") is None else "T " + g(line["target"])
        if t != "—" and line.get("excellence") is not None:
            t += " · E " + g(line["excellence"])
    u = (line.get("unit") or "").strip()
    return w, (t + " " + u if u and t != "—" else t)


def _bu_kpi_pickable(db, bg, co):
    """The group's library KPIs a super admin can make one unit's BU KPI (2026-10-23, Chris: "allow super admin to
    select which KPIs to be inserted as the BU KPIs from the KPI library list"): active, the group's or the unit's own,
    not BU-level already. {id: row}; the unit's own row of a name wins over the group's."""
    best = {}
    for r in db.execute("SELECT * FROM pm_kpi_library WHERE active=1 AND business_group=? AND company IN ('*', ?) "
                        "ORDER BY (company='*'), id", (bg, co)):
        best.setdefault(_kpi_key(r["kpi_name"]), dict(r))
    named = _pm_lib_people_map(db, bg)   # a row that names people is a person's own KPI, never a unit's
    return {r["id"]: r for r in best.values() if not r["bu_level"] and r["id"] not in named}


def _bu_kpi_unit_row(db, me, lib, co):
    """Make a library KPI BU-level for one unit only (Chris, 2026-10-23: "This unit only"): pm_bu_level_names then marks
    it HR's for that unit's people and nobody else's. A group row is copied as the unit's own (an earlier copy taken
    off is put back); a unit row of its own is marked. (row id, how: 'copy' | 'flag'), the how kept on the setup so
    taking the KPI off undoes exactly this."""
    if (lib["company"] or "*") == co:
        db.execute("UPDATE pm_kpi_library SET bu_level=1, updated_at=datetime('now'), updated_by=? WHERE id=?",
                   (me["id"], lib["id"]))
        return lib["id"], "flag"
    cols = [r[1] for r in db.execute("PRAGMA table_info(pm_kpi_library)")
            if r[1] not in ("id", "created_at", "created_by", "updated_at", "updated_by")
            and r[1] not in _LIB_NUMBER_COLS]   # the library holds no numbers: the copy has none (Chris, 2026-11-02)
    vals = {c: lib.get(c) for c in cols}
    vals.update({"company": co, "bu_level": 1, "active": 1})
    same = db.execute("SELECT id FROM pm_kpi_library WHERE business_group=? AND company=? AND department=? AND tier_n=? "
                      "AND job_grade=? AND kpi_name=?", (lib["business_group"], co, lib["department"], lib["tier_n"],
                                                         lib["job_grade"], lib["kpi_name"])).fetchone()
    if same:
        db.execute("UPDATE pm_kpi_library SET %s, updated_at=datetime('now'), updated_by=? WHERE id=?"
                   % ", ".join("%s=?" % c for c in cols), [vals[c] for c in cols] + [me["id"], same[0]])
        return same[0], "copy"
    return db.execute("INSERT INTO pm_kpi_library(%s, created_by) VALUES (%s, ?)" % (", ".join(cols), ",".join(
        "?" * len(cols))), [vals[c] for c in cols] + [me["id"]]).lastrowid, "copy"


def _bu_kpi_unit_row_undo(db, me, row):
    """Taking a unit-only BU KPI off its unit undoes _bu_kpi_unit_row: the unit's copy is retired, a unit row of its own
    loses the mark, so the KPI is each holder's own again. A group-wide BU KPI's row is never touched."""
    data = json.loads(row["carriers_json"]) if row["carriers_json"] else {}
    how, lid = data.get("made"), row["library_id"]
    if not lid or how not in ("copy", "flag"):
        return
    db.execute("UPDATE pm_kpi_library SET bu_level=0%s, updated_at=datetime('now'), updated_by=? WHERE id=? AND "
               "company=?" % (", active=0" if how == "copy" else ""), (me["id"], lid, row["company"]))


def _bu_weight_kept(db, act, bg, co, lib, form):
    """A BG or unit admin's save in an Early Year keeps the weight rule the super admin set (Chris, 2026-10-26: "super
    admin to define and decide"): the card's weight fields become the saved setup's, or the starting bands for a new
    one. The rest of the card is theirs."""
    k = "k%d_" % lib["id"]
    row = db.execute("SELECT weight_mode, weight, bands_json FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND "
                     "company=? AND kpi_name=?", (act["id"], bg, co, lib["kpi_name"])).fetchone()
    mode, w, bands = (row["weight_mode"], row["weight"], json.loads(row["bands_json"] or "[]")) if row else (
        "grade", None, BU_KPI_BANDS_DEFAULT)
    f = form.copy()
    f.setlist(k + "wmode", [mode])
    f.setlist(k + "weight", ["" if w is None else "%g" % w])
    f.setlist(k + "bmin", ["" if b["min"] is None else str(b["min"]) for b in bands])
    f.setlist(k + "bmax", ["" if b["max"] is None else str(b["max"]) for b in bands])
    f.setlist(k + "bw", ["%g" % b["w"] for b in bands])
    return f


def _bu_kpi_parse(db, form, lib, cfg, people, depts, early=True, holders=None, gh_only=False, add_ok=False, totals=None):
    """One BU KPI card from the form, checked: (setup dict, None) or (None, why). The scale through the import's own
    rules (_pm_kpi_values, the scale check included); carriers that name at least one person taking part in the unit;
    a weight above 0 and at most 100, or grade bands that cover every grade once with every carrier's grade a number.
    `gh_only` (2026-11-03): a variant made for Grade H lines alone (Move some to a variant): nobody of the normal review carries it, so
    the empty carriers are not refused (it holds a target, a name and its Grade H lines).
    `add_ok` (2026-11-06, the super admin outside an Early Year; canvas MYkFfimk8GjcFJ4unL8nDv board A1): the card may also
    add someone who does not carry the KPI yet -- `k<id>_addp` (ticked Employee IDs) with `k<id>_addw_<eid>` (their weight).
    Each added person is in the unit's people taking part, not a holder, under 100% today (`totals` = {eid: (n KPIs, weight
    sum)}, _bu_kpi_totals) and given a weight above 0 that keeps them at 100% or under; the weights ride in
    data["added_w"] for _bu_kpi_weight. A post of `addp` anywhere else is refused, never ignored."""
    k = "k%d_" % lib["id"]
    name = lib["kpi_name"]
    rec = {"kpi": name, "weightage": "1", "method": lib["method"]}
    for i in range(1, 6):
        rec["rate %d" % i] = form.get(k + "rate%d" % i, "")
    for c in ("threshold", "target", "multiple", "excellence"):
        rec[c] = form.get(k + c, "")
    vals, err = _pm_kpi_values(rec, cfg, name)
    if err:
        return None, err
    mode = form.get(k + "carriers") or ("everyone" if early else "holders")
    if not early and mode != "holders":
        return None, ("'%s': outside an Early Year a BU KPI goes only on those who carry it now: their KPIs already add "
                      "up to 100%%." % name)
    data = {}
    if form.getlist(k + "addp") and not (add_ok and not early and mode == "holders"):
        return None, ("'%s': adding someone who doesn't carry it yet is the super admin's, outside an Early Year." % name)
    if mode == "holders":
        eids = {ja_eid(p["employee_id"]) for p in people}
        now = set(holders or ()) & eids
        # the card's list of holders (2026-10-27): unticked ones keep their own line. Absent is not empty: a post
        # without the list (no marker, no ticks) is every holder, as before; a marker with no ticks is a refusal.
        # Only a current holder in the unit can stay in: nobody new is added by a posted Employee ID.
        if (k + "holder_set") in form or form.getlist(k + "holder"):
            ticked = {ja_eid(x) for x in form.getlist(k + "holder")}
            data["people"] = sorted(ticked & now)
            if not data["people"] and not gh_only:
                return None, ("'%s': tick at least one of those who carry it." % name) if now else (
                    "'%s': nobody in the unit carries it now." % name)
        else:
            data["people"] = sorted(now)
        if add_ok and not early:
            added, why = _bu_kpi_added(form, k, name, people, set(holders or ()), totals)
            if why:
                return None, why
            if added:
                data["people"] = sorted(set(data["people"]) | set(added))
                data["added_w"] = added
        if not data["people"] and not gh_only:
            return None, "'%s': nobody in the unit carries it now." % name
    elif mode == "departments":
        data["departments"] = [d for d in form.getlist(k + "dept") if d in depts]
        if not data["departments"]:
            return None, "'%s': tick at least one department to carry it." % name
    elif mode == "grade":
        lo, hi = form.get(k + "gmin", "").strip(), form.get(k + "gmax", "").strip()
        try:
            data["min"] = int(float(lo)) if lo else None
            data["max"] = int(float(hi)) if hi else None
        except ValueError:
            return None, "'%s': the grades that carry it must be numbers." % name
        if data["min"] is None and data["max"] is None:
            return None, "'%s': give the lowest grade, the highest, or both." % name
        if data["min"] is not None and data["max"] is not None and data["min"] > data["max"]:
            return None, "'%s': the lowest grade is above the highest." % name
    elif mode == "pick":
        eids = {ja_eid(p["employee_id"]) for p in people}
        data["people"] = sorted({ja_eid(x) for x in form.getlist(k + "people") if ja_eid(x) in eids})
        if not data["people"]:
            return None, "'%s': pick at least one person to carry it." % name
    elif mode != "everyone":
        return None, "'%s': choose who carries it." % name
    s = {"carriers": mode, "carriers_json": json.dumps(data) if data else None}
    covered = [p for p in people if _bu_kpi_covers(s, p)]
    if not covered and not gh_only:
        return None, "'%s': nobody taking part in the unit is covered by that choice." % name
    wmode = form.get(k + "wmode") or ("grade" if early else "own")
    s.update({"weight_mode": wmode, "weight": None, "bands_json": None})
    if not early and wmode != "own":
        return None, "'%s': outside an Early Year each person keeps the weight on their line." % name
    if wmode == "own":
        if mode != "holders":
            return None, "'%s': keeping each person's own weight goes with those who carry it now." % name
    elif wmode == "one":
        try:
            w = float(form.get(k + "weight", "").replace("%", "").strip())
        except ValueError:
            return None, "'%s': give its weight on their scorecard." % name
        if not 0 < w <= 100:
            return None, "'%s': its weight must be above 0 and at most 100%%." % name
        s["weight"] = w
    elif wmode == "grade":
        bands = []
        for lo, hi, w in zip(form.getlist(k + "bmin"), form.getlist(k + "bmax"), form.getlist(k + "bw")):
            try:
                b = {"min": int(float(lo)) if lo.strip() else None, "max": int(float(hi)) if hi.strip() else None,
                     "w": float(w.replace("%", "").strip())}
            except ValueError:
                return None, "'%s': each grade band needs its grades and a weight, as numbers." % name
            if not 0 < b["w"] <= 100:
                return None, "'%s': each band's weight must be above 0 and at most 100%%." % name
            bands.append(b)
        order = sorted(bands, key=lambda b: -10 ** 6 if b["min"] is None else b["min"])
        ok = bool(order) and order[0]["min"] is None and order[-1]["max"] is None and all(
            (b["min"] is None or b["max"] is None or b["min"] <= b["max"]) for b in order) and all(
            order[i]["max"] is not None and order[i + 1]["min"] == order[i]["max"] + 1 for i in range(len(order) - 1))
        if not ok:
            return None, ("'%s': the grade bands must cover every grade once, from the lowest to the highest, with no "
                          "gap or overlap." % name)
        odd = [p for p in covered if grade_num(p["job_grade"]) is None]
        if odd:
            return None, ("'%s': %d of the people carrying it have a grade that isn't a number, so no band fits them: "
                          "use one weight for all, or fix their grade." % (name, len(odd)))
        s["bands_json"] = json.dumps(sorted(bands, key=lambda b: -(b["min"] if b["min"] is not None else -10 ** 6)))
    else:
        return None, "'%s': choose how its weight is set." % name
    s.update({c: vals[c] for c in _BU_SCALE_COLS})
    s.update({"library_id": lib["id"], "kpi_name": name, "category": lib["category"],
              "unit": kpi_unit_normalise(form.get(k + "unit") or lib["unit"]),
              "method": vals["method"], "n": len(covered)})
    return s, None


def _bu_kpi_totals(db, act, people):
    """{Employee ID: (how many KPI lines, their weights added up)} on the active cycle for the unit's people, ONE batched
    read (900 ids a query). A person with no line is (0, 0.0). For the Add block of a BU KPI card (2026-11-06)."""
    out = {ja_eid(p["employee_id"]): (0, 0.0) for p in people}
    byid = {p["id"]: ja_eid(p["employee_id"]) for p in people}
    ids = list(byid)
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        for r in db.execute("SELECT subject_id, COUNT(*), SUM(weightage) FROM pm_kpi_targets WHERE cycle_id=? AND "
                            "subject_id IN (%s) GROUP BY subject_id" % ",".join("?" * len(part)), [act["id"]] + part):
            out[byid[r[0]]] = (r[1], float(r[2] or 0))
    return out


_BU_FULL = 100 - 0.001   # a person at or over this already adds up to 100% (float tolerance)


def _bu_add_weight(raw):
    """A weight typed for an added person, as a number: 0.0 when it is blank, words, not finite (the checks refuse 0)."""
    try:
        w = float(str(raw if raw is not None else "").replace("%", "").strip())
    except ValueError:
        return 0.0
    return w if w == w and w not in (float("inf"), float("-inf")) else 0.0


def _bu_add_refusal(eid, in_unit, holder, total, weight, person=False):
    """THE per-person rules of adding someone who does not carry a BU KPI yet (2026-11-07; one check for both ways in: the BU
    KPI card's Add block, `_bu_kpi_added`, and the person page's Add a KPI, `_bu_kpi_add_one`): why not, or None. `in_unit`: one of
    the unit's people taking part; `holder`: already holds a line of this KPI; `total`: what their KPI weights add up to
    now; `weight`: the weight given (text or number; None skips the weight rules, for a page that has not asked yet). In order:
    in the unit, not a holder, under 100%, a weight above 0 (and finite), and a total of 100% or under with it. The words are
    the card's own ("<eid> already adds up to 100%."); `person=True` speaks of "they" for the person page's panel."""
    who = "They" if person else eid
    if not in_unit:
        return "%s %s one of the people taking part in this unit." % (who, "aren't" if person else "isn't")
    if holder:
        return "They already carry it." if person else "%s carries it already." % eid
    if total >= _BU_FULL:
        return ("Their KPIs already add up to 100%. Lower a weight first." if person
                else "%s already adds up to 100%%." % eid)
    if weight is None:
        return None
    w = _bu_add_weight(weight)
    if not w > 0:
        return "Give their weight." if person else "give %s's weight." % eid
    if total + w > 100 + 0.001:
        return ("Their KPIs hold %g%%, so at most %g%% more." % (total, 100 - total) if person
                else "%s holds %g%%, so at most %g%% more." % (eid, total, 100 - total))
    return None


def _bu_person_cycle_refusal(db, me, act, srow):
    """The cycle-level rules both person-page BU KPI actions (Add and Take off, 2026-11-07) share, or None: the super admin's
    alone, on a setup of the active cycle, outside an Early Year (there a BU KPI goes on by department, grade or everyone),
    while BU KPI setup is still open (`_bu_kpi_state`: until the HOD Department Review starts)."""
    if not is_super(me):
        return "Adding a BU KPI to someone is the super admin's."
    if not act or not srow or srow["cycle_id"] != act["id"]:
        return "That BU KPI is not set up on the active cycle."
    if cycle_row_is_early_year(act):
        return "This is an Early Year: a BU KPI goes on by department, grade or everyone, set on BU KPI setup."
    open_, note = _bu_kpi_state(db, act)
    if not open_:
        return note
    return None


def _bu_add_cycle_refusal(db, me, act, srow):
    """The cycle-level rules of adding someone to a saved BU KPI from the person page, or None: `_bu_person_cycle_refusal`, and a
    setup that goes on those who carry it now, each at their own weight (outside an Early Year every saved one does; one saved
    in an Early Year by department, grade or everyone, or at one weight or by grade, does not: it is saved again on BU KPI setup
    first)."""
    why = _bu_person_cycle_refusal(db, me, act, srow)
    if why:
        return why
    if srow["carriers"] != "holders" or srow["weight_mode"] != "own":
        return "It goes on by department, grade or a pick, or at one weight, so it is set on BU KPI setup."
    return None


_BU_LOCKED_WHY = "Their line has a result, a check-in or a moderation, so it stays."
_BU_CLEAR_WORDS = 300   # the most words of the reason that "Clear result and take off" asks for


def _bu_clear_reason(raw):
    """(reason, error): the super admin's reason for clearing a BU-filled result with a take-off (2026-11-07). Required, at most
    `_BU_CLEAR_WORDS` words, screened like every stored remark; it goes on the audit row beside the result's old values."""
    reason = " ".join((raw or "").split())
    if not reason:
        return None, "Give a reason first: clearing a result needs one, and it goes in the audit trail."
    if len(reason.split()) > _BU_CLEAR_WORDS:
        return None, "Keep the reason under %d words." % _BU_CLEAR_WORDS
    if ai_draft.stored_text_refusal(reason, "manager"):
        return None, "Reword the reason: it reads like an instruction rather than a reason."
    return reason, None


def _bu_clear_refusal(db, act, t):
    """Why this line's BU-filled result cannot be cleared along with the take-off, or None (the `clear_bu_result` half of
    `_bu_remove_refusal`, 2026-11-07). The line `t` may be cleared only while the ONLY thing anyone has done on it is Group
    People's fill: one result row with admin_filled=1 and draft=0 (what Fill BU result writes; nothing else writes one on a BU
    line), no check-in, no moderation (an approval or a moderator's draft), no file or remark of the person's own (an attachment,
    or a recognition item linked to the line). And not once the person's result is released, or a calibrator, Group Chief or
    calibration lock has acted over them (`_pm_calibration_hold`, the rule that stops a refill)."""
    if setup_released_at(db, t["subject_id"], act["id"], "pm"):
        return "Their result is released, so it is final."
    subj = db.execute("SELECT * FROM users WHERE id=?", (t["subject_id"],)).fetchone()
    held = _pm_calibration_hold(db, act["id"], [subj]).get(t["subject_id"]) if subj else None
    if held:
        return "Their result stays: %s." % held
    tid = t["id"]
    res = db.execute("SELECT * FROM pm_kpi_results WHERE kpi_target_id=?", (tid,)).fetchone()
    if res and res["draft"]:   # their own unsent draft: nothing to reopen, it simply stays
        return _BU_LOCKED_WHY
    if (db.execute("SELECT 1 FROM pm_kpi_approvals WHERE kpi_target_id=? UNION SELECT 1 FROM pm_kpi_moderation_drafts "
                   "WHERE kpi_target_id=? UNION SELECT 1 FROM pm_checkins WHERE kpi_target_id=? LIMIT 1",
                   (tid, tid, tid)).fetchone()
            or (res and res["admin_filled"] != 1)):
        return _BU_LOCKED_WHY + " Reopen first."
    if (db.execute("SELECT 1 FROM pm_attachments WHERE kpi_target_id=? UNION SELECT 1 FROM pm_evidence_links WHERE "
                   "target_kind='kpi' AND target_ref=? LIMIT 1", (tid, str(tid))).fetchone()):
        return "Their line has a file or a remark of their own on it, so it stays."
    if not res:
        return "Their line has no filled result to clear: take them off without it."
    return None


def _bu_remove_refusal(db, me, act, srow, t, person, clear_bu_result=False):
    """Why this person cannot be taken off this BU KPI from the person page, or None (one helper: the panel shows its words as the
    reason the button is not offered, `_bu_kpi_remove_one` refuses with them, 2026-11-07). `t` is the line they hold (a
    pm_kpi_targets row). In order: the cycle's rules (`_bu_person_cycle_refusal`); the line is theirs, on the active cycle and linked
    to this setup of their own unit; the setup goes on those who carry it now; nobody has acted on the line (a result, a check-in
    or a moderation: `_bu_line_locked`, so it stays); they are not the last carrier (a BU KPI with nobody carrying it is taken off
    on BU KPI setup). What unticking them there does, no more.
    `clear_bu_result=True` (the super admin's "Clear result and take off", 2026-11-07) changes ONE rule: a line whose only act is
    Group People's own BU fill may go, its result cleared with it (`_bu_clear_refusal`; anything else on the line still keeps it,
    with 'Reopen first' where a reopen would free it). Every other rule, the last-carrier one included, is as above."""
    why = _bu_person_cycle_refusal(db, me, act, srow)
    if why:
        return why
    guest = bool(person) and ja_eid(person["employee_id"]) in _bu_kpi_guests(srow) and person["business_group"] == srow["business_group"]
    if (not t or not person or t["subject_id"] != person["id"] or t["cycle_id"] != act["id"] or t["bu_kpi_id"] != srow["id"]
            or ((person["business_group"], person["company"]) != (srow["business_group"], srow["company"]) and not guest)):
        return "That line is not on a BU KPI of their unit."
    if srow["carriers"] != "holders" and not guest:   # a guest comes off whatever the setup's carrier mode (2026-11-07)
        return "It goes on by department, grade or a pick, so taking someone off is set on BU KPI setup."
    if clear_bu_result:
        why = _bu_clear_refusal(db, act, t)
        if why:
            return why
    elif _bu_line_locked(db, t["id"]):
        return _BU_LOCKED_WHY
    try:
        people = set((json.loads(srow["carriers_json"] or "{}") or {}).get("people") or [])
    except ValueError:
        people = set()
    if guest:   # the others are the unit's carriers and the other guests: a guest is never "the only one" while the unit still has carriers
        people |= set(_bu_kpi_guests(srow))
    n_linked = db.execute("SELECT COUNT(*) FROM pm_kpi_targets WHERE bu_kpi_id=? AND cycle_id=?", (srow["id"], act["id"])).fetchone()[0]
    if n_linked <= 1 or not (people - {ja_eid(person["employee_id"])}):
        return "They're the only one who carries it: take the KPI off on BU KPI setup."
    return None


def _bu_kpi_added(form, k, name, people, holders, totals):
    """The people a BU KPI card adds who do not carry the KPI yet: ({Employee ID: weight}, None) or (None, why).
    Each is in `people` (the unit's, taking part), not in `holders`, under 100% today (`totals`) and given a weight
    above 0 that keeps them at 100% or under (`_bu_add_refusal`, the rules the person page's Add shares). Absent is empty:
    nothing ticked is no adds."""
    ticked = []
    for x in form.getlist(k + "addp"):
        e = ja_eid(x)
        if e and e not in ticked:
            ticked.append(e)
    if not ticked:
        return {}, None
    eids = {ja_eid(p["employee_id"]) for p in people}
    out = {}
    for e in ticked:
        n_, tot = (totals or {}).get(e, (0, 0.0))
        raw = form.get("%saddw_%s" % (k, e)) or ""
        why = _bu_add_refusal(e, e in eids, e in holders, tot, raw)
        if why:
            return None, "'%s': %s" % (name, why)
        out[e] = _bu_add_weight(raw)
    return out, None


def _bu_kpi_add_pool(db, act, people, holders):
    """The Add block of a BU KPI card outside an Early Year (the super admin's): {"rows": [...], "full": how many are left
    out}. A row: eid, name, dept, g, n (KPI lines today), w (their weights added up), room (100 - w). Taking part in the
    unit (`people`), not a holder, under 100%."""
    totals = _bu_kpi_totals(db, act, people)
    rows, full = [], 0
    for p in people:
        e = ja_eid(p["employee_id"])
        if e in holders:
            continue
        n_, tot = totals.get(e, (0, 0.0))
        if tot >= _BU_FULL:
            full += 1
            continue
        rows.append({"eid": e, "name": p["full_name"], "dept": p["department"] or "", "g": grade_num(p["job_grade"]),
                     "n": n_, "w": round(tot, 2), "room": round(100 - tot, 2)})
    return {"rows": rows, "full": full}


def _bu_line_locked(db, tid):
    """A line someone has acted on (a moderation, a result or a check-in): never removed by the setup, and changed only by
    a setup save (_bu_kpi_apply locked_ok; Chris, 2026-11-03), which gives it the unit's target and leaves its result."""
    return bool(db.execute("SELECT 1 FROM pm_kpi_approvals WHERE kpi_target_id=? UNION SELECT 1 FROM pm_kpi_results "
                           "WHERE kpi_target_id=? UNION SELECT 1 FROM pm_checkins WHERE kpi_target_id=? LIMIT 1",
                           (tid, tid, tid)).fetchone())


def _bu_line_unit_fill(db, tid):
    """True when the ONLY thing a line holds is Group People's own Fill BU result for the unit (2026-11-14): one result row, final
    (`admin_filled=1`, not a draft) and no moderation on it. That figure is the unit's, entered against the BU KPI setup, so a
    change of the setup's unit or method does not make it mean something else: the setup's unit is what it is read in. A person's
    own result or draft, a moderation (an approver's figure is typed in the line's old unit), or no result at all is False.
    Check-ins are not asked: they never held a line here."""
    r = db.execute("SELECT admin_filled, COALESCE(draft,0) AS draft FROM pm_kpi_results WHERE kpi_target_id=?", (tid,)).fetchall()
    return (len(r) == 1 and bool(r[0]["admin_filled"]) and not r[0]["draft"]
            and not db.execute("SELECT 1 FROM pm_kpi_approvals WHERE kpi_target_id=? LIMIT 1", (tid,)).fetchone())


def _bu_kpi_apply(db, me, act, s, people, only=None, remove=False, locked_ok=False, touched=None, late=False):
    """Put a saved BU KPI setup's line on everyone in the unit it covers (or only the person `only`), at its one target
    and their weight, and take it off anyone it no longer covers -- or off everyone, remove=True (the KPI unticked).
    A line someone already holds with the same name is adopted (linked and brought to the target); one the super admin
    kept the person's own in the KPI import (bu_keep_own, 2026-10-26) is never adopted, and no second line put beside it.
    A line someone has acted on (a moderation, a result or a check-in) is left as it is and counted as held when the
    person is no longer covered or the KPI comes off. Chris, 2026-11-03: a SETUP SAVE (locked_ok=True, _bu_kpi_save_one)
    changes every line in the unit, those with results too: such a line takes the unit's target figures like any other
    ('updated', 'with_results'); the person's result, remark and files are never touched; a line a moderator had signed
    off goes back to its moderators ('remoderated': _bu_kpi_back_to_moderation); a line whose method or unit would change
    stays as it is ('held', and 'differs' says why), EXCEPT a line whose only result is Group People's own Fill BU
    result (`_bu_line_unit_fill`, 2026-11-14; Chris: "edited BU KPI target must reach the Fill BU KPI page"): that figure
    is the unit's, entered against this setup, not something the person typed in their own unit, so the line takes the
    setup's figures, unit and method like any other locked line ('updated', 'with_results', retargeted) and the figure
    itself is never touched: it now reads in the new unit. Check-ins never held a line for this. A line with the person's
    own result (or a draft) is held as before. Every other caller (a person added, a unit moved, the KPI import's
    join) leaves an acted-on line held, as before. The caller commits and logs.
    A line that NEWLY joins the setup in this call (added, or adopted from another link or from none) takes the unit's
    figure when Group People has already filled it (`_bu_fill_carry`, 2026-11-07; 'carried'): a line already linked before
    the call is never touched by it, and a line with a result or check-in keeps its own.
    `touched` (2026-11-08): a dict the caller passes to follow the rating records of everyone whose line this call changed (added,
    updated, taken off or given back; `_bu_touch`), which it then rebuilds once with `_bu_follow_flush` before its commit; a line with a
    result whose target moved is noted under "bu_kpi_retarget" and `_bu_kpi_back_to_moderation` leaves the rebuild to that flush
    instead of doing its own. None (every other caller): as before.
    A setup save (`locked_ok`, 2026-11-14) never touches a person whose pm result is released (one batched read; 'released' counts
    them): a released result is final, whatever the setup says now.
    `late=True` (the super admin's late save, 2026-11-14: "amend the BU KPI target ... till the result release", `_bu_kpi_save_late`): the
    Department Review has started, so nobody is added or taken off and no weight changes: only a line ALREADY linked to this setup takes
    its target figures, unit and method, at the weight it holds. A moderated line keeps its moderation (the line manager's window has
    closed: sending it back would leave it stuck) and is scored on read against the new target ('kept_moderated' counts them); the
    person is still told in their own conversation, with no "moderated again". Default False: as before.
    {added, updated, removed, returned, held, own, with_results, remoderated, differs, carried, released, kept_moderated}."""
    out = {"added": 0, "updated": 0, "removed": 0, "returned": 0, "held": 0, "own": 0, "with_results": 0,
           "remoderated": 0, "differs": 0, "carried": 0, "released": 0, "kept_moderated": 0}
    joined = []   # the lines newly linked to this setup in this call (the carry below reads only these)
    pool = [p for p in people if only is None or p["id"] == only]
    if not pool:
        return out
    rel_ = setup_released_many(db, [p["id"] for p in pool], act["id"], "pm") if locked_ok else {}
    retarget = []   # (person, line, the target figures changed) for each acted-on line this save changed
    ph = ",".join("?" * len(pool))
    have = {}
    for r in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id IN (%s) AND (bu_kpi_id=? OR "
                        "lower(kpi_name)=lower(?)) ORDER BY (bu_kpi_id IS NULL), id" % ph,
                        [act["id"]] + [p["id"] for p in pool] + [s["id"], s["kpi_name"]]):
        have.setdefault(r["subject_id"], dict(r))
    lib = {"id": s["library_id"]} if s["library_id"] else None
    for p in pool:
        t = have.get(p["id"])
        if late and (not t or t.get("bu_kpi_id") != s["id"] or t.get("weightage") is None):
            continue   # the late save only retargets lines already on this setup: nobody is added, adopted or taken off
        if rel_.get(p["id"]):
            if t or _bu_kpi_covers(s, p):   # someone the save would have reached (a released person it never concerns is not counted)
                out["released"] += 1   # a setup save never reaches a released result (2026-11-14)
            continue
        if t and t.get("bu_keep_own") and t.get("bu_kpi_id") != s["id"]:
            out["own"] += 1   # not linked, so it never stops the KPI coming off
            continue
        w = (t["weightage"] if late else (None if remove or not _bu_kpi_covers(s, p) else _bu_kpi_weight(s, p, t)))
        if w is None:
            if t and t.get("bu_kpi_id") == s["id"]:
                if _bu_line_locked(db, t["id"]):
                    out["held"] += 1
                else:
                    out[_bu_line_release(db, me, t)] += 1
                    _bu_touch(touched, p["id"])   # the line is gone or back as it was: their totals moved
            continue
        vals = {c: s[c] for c in _BU_SCALE_COLS}
        vals.update({"weightage": w, "method": s["method"], "unit": s["unit"], "category": s["category"]})
        if t:
            locked = _bu_line_locked(db, t["id"])
            if locked and not locked_ok:
                out["held"] += 1
                continue
            if (locked and (_bu_meaning(t["method"], t.get("unit")) != _bu_meaning(s["method"], s["unit"]))
                    and not _bu_line_unit_fill(db, t["id"])):
                out["held"] += 1   # the person's typed result would no longer mean the same thing: left as it is
                out["differs"] += 1
                continue
            cur = (t["kpi_name"], t["weightage"], t["method"], t.get("bu_kpi_id"), t.get("library_id"),
                   t.get("unit"), t.get("focus") or None, t.get("description") or None) + tuple(
                t[c] for c in _BU_SCALE_COLS)
            new = (s["kpi_name"], w, s["method"], s["id"], s["library_id"], s["unit"], None, None) + tuple(
                vals[c] for c in _BU_SCALE_COLS)
            if tuple(None if v is None else (float(v) if isinstance(v, (int, float)) else v) for v in cur) != tuple(
                    None if v is None else (float(v) if isinstance(v, (int, float)) else v) for v in new):
                # adopted for the first time: keep what it held, so taking the KPI off gives it back as it was
                prev = t.get("bu_prev_json") if t.get("bu_kpi_id") is not None else None
                if not prev:
                    prev = json.dumps({c: t.get(c) for c in _BU_PREV_COLS})
                else:   # kept before the focus and description were set aside (2026-10-26): they're still the holder's
                    try:
                        pd_ = json.loads(prev) or {}
                    except ValueError:
                        pd_ = {}
                    if not pd_.get("added") and any(c not in pd_ for c in ("focus", "description")):
                        for c in ("focus", "description"):
                            pd_.setdefault(c, t.get(c))
                        prev = json.dumps(pd_)
                # the BU KPI's own name and definition (Chris, 2026-10-26: the name, description, target, unit and
                # multiplier are the unit's): the holder's Focus and description wait in bu_prev_json
                db.execute("UPDATE pm_kpi_targets SET kpi_name=?, weightage=?, method=?, unit=?, category=?, %s, "
                           "focus=NULL, description=NULL, "
                           "bu_kpi_id=?, library_id=?, bu_prev_json=?, updated_at=datetime('now'), updated_by=? "
                           "WHERE id=?" % ", ".join("%s=?" % c for c in _BU_SCALE_COLS),
                           [s["kpi_name"], w, s["method"], s["unit"], s["category"]]
                           + [vals[c] for c in _BU_SCALE_COLS] + [s["id"], s["library_id"], prev, me["id"], t["id"]])
                out["updated"] += 1
                _bu_touch(touched, p["id"])   # a weight alone moves their total, with a result or not
                if t.get("bu_kpi_id") != s["id"]:
                    joined.append(t["id"])
                if locked:
                    out["with_results"] += 1
                    retarget.append((p, t, any(
                        _bu_num(t[c]) != _bu_num(vals[c]) for c in _BU_SCALE_COLS)))
            continue
        vals["description"] = None
        mod, _err = _pm_kpi_moderator(db, p, "", s["kpi_name"])
        tid = _admin_kpi_insert(db, me, p, act, s["kpi_name"], vals, mod or {"approver_ids": []}, lib,
                                bu_kpi_id=s["id"], log=False)
        db.execute("UPDATE pm_kpi_targets SET bu_prev_json=? WHERE id=?", (json.dumps({"added": 1}), tid))
        out["added"] += 1
        _bu_touch(touched, p["id"])
        joined.append(tid)
    if retarget:
        _bu_kpi_back_to_moderation(db, me, act, [(p, t) for p, t, moved in retarget if moved], out, touched=touched,
                                   keep=late)
    if joined:   # a line that newly joins a unit Group People already filled takes the unit's figure (2026-11-07)
        out["carried"] = _bu_fill_carry(db, me, act, s, joined)
    return out


def _bu_fill_carry(db, me, act, s, tids):
    """The unit's BU-filled figure goes onto lines that JOIN setup `s` after Group People filled it (2026-11-07): Fill BU KPI
    writes a result only on the lines linked at that moment, so a person linked later had none and the Fill page read
    "Filled, N to fill" until someone filled again. `tids` are the lines that just joined (the caller says which, so a line
    that was already linked and still has no result is never back-filled here: that is a data step). The figure is the
    LATEST final admin-filled result on a line of this setup outside `tids` (after a refill some lines keep the older figure).
    It is copied as it is, value, remark, who and when, so the Fill page's "Filled <date>" stays the unit's date. A line
    with any result row (a draft included), a check-in or a moderation is left alone (_bu_line_locked): a person's own work is
    never overwritten. No email and no new note for the person; one audit row each (ids only, no figure) and the AI pre-run
    for the people written, as the fill does. The caller commits. Returns how many lines took the figure."""
    tids = [int(x) for x in tids if x]
    if not tids:
        return 0
    ph = ",".join("?" * len(tids))
    src = db.execute("SELECT r.actual_value, r.note, r.submitted_by, r.submitted_at, t.id AS src_tid FROM pm_kpi_results r "
                     "JOIN pm_kpi_targets t ON t.id=r.kpi_target_id WHERE t.cycle_id=? AND t.bu_kpi_id=? AND r.admin_filled=1 "
                     "AND COALESCE(r.draft,0)=0 AND t.id NOT IN (%s) ORDER BY r.submitted_at DESC, r.id DESC LIMIT 1" % ph,
                     [act["id"], s["id"]] + tids).fetchone()
    if not src:
        return 0
    sids, n = set(), 0
    for tid in tids:
        t = db.execute("SELECT id, subject_id FROM pm_kpi_targets WHERE id=? AND cycle_id=? AND bu_kpi_id=?",
                       (tid, act["id"], s["id"])).fetchone()
        if not t or _bu_line_locked(db, tid):
            continue
        db.execute("INSERT INTO pm_kpi_results(kpi_target_id, actual_value, note, submitted_by, submitted_at, admin_filled, draft) "
                   "VALUES (?,?,?,?,?,1,0)",
                   (tid, src["actual_value"], src["note"], src["submitted_by"], src["submitted_at"]))
        log_activity(db, me["id"], "pm_bu_fill", "setup %d, line %d: the unit's filled result carried on joining (copied from "
                     "line %d)" % (s["id"], tid, src["src_tid"]), target_user_id=t["subject_id"], commit=False)
        sids.add(t["subject_id"])
        n += 1
    if sids:
        _prerun_on_event(db, act["id"], sids, "pm_bu_fill")   # their insights read the unit's figure (2026-11-07)
    return n


def _bu_num(v):
    """A target figure for comparing: None stays None, a number is a float (5 and 5.0 are the same figure)."""
    try:
        return None if v is None else float(v)
    except (TypeError, ValueError):
        return v


def _bu_meaning(method, unit):
    """What a typed result on a line means: its method (More or Less) and its unit as the app stores it."""
    return ((method or "").strip().lower(), kpi_unit_normalise(unit) or "")


def _bu_kpi_back_to_moderation(db, me, act, changed, out, touched=None, keep=False):
    """Lines with results whose target FIGURES a BU KPI save just changed (Chris, 2026-11-03: "a change updates every
    line in the unit, including lines that already have results"). `changed` is [(person, the line as it was)].
    What a target moves, by what the app stores and what it computes:
      * stored, so cleared here: the line's moderation (pm_kpi_approvals), as _reopen_pm_seed lifts it: each step becomes
        its moderator's private starting point (pm_kpi_moderation_drafts), so the line is theirs to moderate again and
        nothing they wrote is lost; the moderated result figures go with it, since pm_effective_value reads them;
      * computed on read from the targets and the approvals, so nothing to clear: the line's score and label, the
        Total KPI score (needs every line locked), the band (pm_effective_band), the AI readings (their fingerprints
        hold the targets), the line manager's remark (shown only once every line is locked);
      * a snapshot, so rebuilt: the rating record (_rating_record_refresh).
    A line HR filled (admin_filled) has no moderation: its result stays and the new target scores it. The person's result,
    remark and files are never touched, and a submission stays submitted. Each person with a line that took a new target
    is told in their own conversation (and which of them are being moderated again), each moderator in theirs only for
    a moderation lifted (no email). Adds 'remoderated' (lines) to `out`. With `touched` (`_bu_touch`) the rating record is not rebuilt
    here: each person is noted as a retarget and the caller's `_bu_follow_flush` rebuilds it once, after every change of the save.
    `keep=True` (the super admin's late save, once the Department Review has started): a moderated line KEEPS its moderation, since the
    line manager's window has closed and a lifted moderation would leave the line stuck; it is scored on read against the new target,
    `out["kept_moderated"]` counts such lines, and the person's note has no "moderated again" part."""
    sids = sorted({p["id"] for p, _t in changed})
    if not sids:
        return
    tids = [t["id"] for _p, t in changed]
    ph = ",".join("?" * len(tids))
    had = {r[0] for r in db.execute("SELECT DISTINCT kpi_target_id FROM pm_kpi_approvals WHERE kpi_target_id IN (%s)" % ph,
                                    tids)}
    by_person = {}
    for p, t in changed:
        by_person.setdefault(p["id"], (p, []))[1].append(t)
    for sid in sids:
        p, lines = by_person[sid]
        mine = [t for t in lines if t["id"] in had]
        if keep:
            moved = {}
            out["kept_moderated"] += len(mine)
            mine = []
        else:
            moved = _reopen_pm_seed(db, [t["id"] for t in mine]) if mine else {}
            out["remoderated"] += len(mine)
        # the person is told of every line of theirs that took a new target; each moderator only of a moderation lifted
        _bu_kpi_notice(db, act, p, [t["kpi_name"] for t in lines], [t["kpi_name"] for t in mine], sorted(moved))
    if touched is not None:
        for sid in sids:
            _bu_touch(touched, sid, True)
    else:
        _rating_record_refresh(db, act["id"], sids, "bu_kpi_retarget", me["id"])


def _bu_kpi_notice(db, act, person, names, lifted, approver_ids):
    """The in-app notes for lines with results that took a new target in a BU KPI save (no email): a fixed line, no model,
    in the person's own conversation (their AI+ check-in) for every such line, and in each moderator's Team review of them
    only for a line whose moderation was lifted (`lifted`, a subset of `names`), the two places the app already puts such
    a line (_reopen_post_note). They say the target moved and the result did not; they never say reopen."""
    q = lambda ns: ", ".join("\u201c%s\u201d" % n for n in ns)   # noqa: E731
    many = len(names) > 1
    txt = ("The target for your KPI%s %s changed in your unit's BU KPI setup. Your result%s and your note stay as you "
           "entered them." % ("s" if many else "", q(names), "s" if many else ""))
    if lifted:
        txt += " %s %s being moderated again." % (q(lifted), "are" if len(lifted) > 1 else "is")
    _kpi_note_person(db, act, person["id"], txt)
    stage = REOPEN_PARTS["pm_mod"]["stage"]
    lm = len(lifted) > 1
    for aid in approver_ids:
        db.execute("INSERT INTO pm_manager_chat(reviewer_id, cycle_id, report_id, stage, role, content, scope) "
                   "VALUES (?,?,?,?,'agent',?,?)",
                   (aid, act["id"], person["id"], stage,
                    "The target for %s's KPI%s %s changed in their unit's BU KPI setup, so your moderation of %s is lifted and %s "
                    "back with you to moderate again. Their result%s unchanged; what you wrote is kept as your starting point."
                    % (person["full_name"], "s" if lm else "", q(lifted), "them" if lm else "it",
                       "they are" if lm else "it is", "s are" if lm else " is"), _mchat_scope(stage)))


# What an adopted line held before BU KPI setup gave it the unit's target, kept on the line (bu_prev_json).
_BU_PREV_COLS = ("weightage", "method", "unit", "category", "library_id", "kpi_name", "focus",
                 "description") + _BU_SCALE_COLS


def _bu_line_release(db, me, t):
    """Take a line off its BU KPI setup: one the setup put on comes off ('removed'); one it adopted goes back to its
    holder as it was (Chris, 2026-10-23: "back as they were"), its earlier weight, target, unit, category and library
    link, Focus and description ('returned'). A line adopted before its earlier values were kept is unlinked, never
    deleted."""
    try:
        prev = json.loads(t.get("bu_prev_json") or "{}") or {}
    except ValueError:
        prev = {}
    if prev.get("added"):
        db.execute("DELETE FROM pm_kpi_targets WHERE id=?", (t["id"],))
        return "removed"
    back = [c for c in _BU_PREV_COLS if c in prev]
    db.execute("UPDATE pm_kpi_targets SET %sbu_kpi_id=NULL, bu_prev_json=NULL, updated_at=datetime('now'), updated_by=? "
               "WHERE id=?" % "".join("%s=?, " % c for c in back), [prev[c] for c in back] + [me["id"], t["id"]])
    return "returned"


def _bu_kpi_setups_for(db, act, person):
    """The saved BU KPI setups of the active cycle that cover this person, each with the weight it gives them:
    [(setup row, weight)]. For Add a person's KPI step."""
    if not act or not person["company"]:
        return []
    out = []
    for s in db.execute("SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=? ORDER BY kpi_name",
                        (act["id"], person["business_group"], person["company"])):
        if _bu_kpi_covers(s, person):
            w = _bu_kpi_weight(s, person)
            if w is not None:
                out.append((s, w))
    return out


_BU_SAVE_COLS = ("library_id", "category", "unit", "method") + _BU_SCALE_COLS + (
    "carriers", "carriers_json", "weight_mode", "weight", "bands_json")


def _bu_apply_trail(n):
    """The audit trail's words for what `_bu_kpi_apply` did beyond its added / updated / taken-off counts (one place, so the card's
    save and Bring them onto this setup say the same things): ', 3 with results took the target, 1 went back to their moderators,
    2 held: the method or unit differs, ...'; empty when none of them happened."""
    return (((", %d with results took the target" % n["with_results"]) if n["with_results"] else "")
            + ((", %d went back to their moderators" % n["remoderated"]) if n["remoderated"] else "")
            + ((", %d held: the method or unit differs" % n["differs"]) if n["differs"] else "")
            + ((", %d held: someone acted on them" % (n["held"] - n["differs"])) if n["held"] - n["differs"] else "")
            + ((", %d kept their own in a KPI import" % n["own"]) if n["own"] else "")
            + ((", %d kept their moderation (the Department Review has started: the line is scored against the new target)"
                % n["kept_moderated"]) if n.get("kept_moderated") else "")
            + ((", %d left as they are: their result is released" % n["released"]) if n.get("released") else ""))


def _bu_kpi_save_one(db, me, act, bg, co, lib, st, people, gh_refresh=True, touched=None):
    """Save ONE BU KPI of a unit (the one writer, 2026-10-27: the page saves a KPI at a time; the older whole-unit save
    loops over it): `st` is what _bu_kpi_parse made, `lib` the library row, st["pick"] a super admin's pick from the
    library (made BU-level for this unit only). Upserts that KPI's setup row, puts its line on everyone it covers or
    takes it off anyone it no longer covers, and logs it. Touches no other KPI's setup or lines. The caller commits.
    (the setup row, the _bu_kpi_apply counts). `touched`: see `_bu_kpi_apply`."""
    row = db.execute("SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=? AND kpi_name=?",
                     (act["id"], bg, co, st["kpi_name"])).fetchone()
    data = json.loads(st["carriers_json"]) if st["carriers_json"] else {}
    made = (json.loads(row["carriers_json"]).get("made") if row and row["carriers_json"] else None)
    # the guests from other units (2026-11-07) are not on the card's form: the saved row's are carried over on EVERY write, or the next
    # save of the card would silently drop them (a write that names its own "guests", the move to a variant, keeps what it says)
    guests_saved = (json.loads(row["carriers_json"]).get("guests") if row and row["carriers_json"] else None) or None
    if st["pick"]:   # the super admin's pick from the library: BU-level for this unit only, from now
        st["library_id"], made = _bu_kpi_unit_row(db, me, lib, co)
    if made or (guests_saved and "guests" not in data):   # made is kept on the setup, so taking the KPI off undoes exactly what was made
        if made:
            data["made"] = made
        if guests_saved and "guests" not in data:
            data["guests"] = guests_saved
        st["carriers_json"] = json.dumps(data)
    cols = _BU_SAVE_COLS
    if row:
        db.execute("UPDATE pm_bu_kpis SET %s, updated_by=?, updated_at=datetime('now') WHERE id=?"
                   % ", ".join("%s=?" % c for c in cols), [st[c] for c in cols] + [me["id"], row["id"]])
        sid = row["id"]
    else:
        sid = db.execute("INSERT INTO pm_bu_kpis(cycle_id, business_group, company, kpi_name, %s, updated_by) "
                         "VALUES (?,?,?,?,%s,?)" % (", ".join(cols), ",".join("?" * len(cols))),
                         [act["id"], bg, co, st["kpi_name"]] + [st[c] for c in cols] + [me["id"]]).lastrowid
    srow = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (sid,)).fetchone()
    # a setup save reaches lines with results too (2026-11-03), the unit's people AND its guests (2026-11-07: _bu_kpi_pool)
    n = _bu_kpi_apply(db, me, act, srow, _bu_kpi_pool(db, act, srow, people), locked_ok=True, touched=touched)
    added_w = data.get("added_w") or {}
    if added_w:   # the weights given to the people added in this save were read by _bu_kpi_weight; they do not stay on the setup
        clean = {a: b for a, b in data.items() if a != "added_w"}
        if made:
            clean["made"] = made
        db.execute("UPDATE pm_bu_kpis SET carriers_json=? WHERE id=?", (json.dumps(clean), sid))
        srow = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (sid,)).fetchone()
    if gh_refresh:   # a changed target scores Group People's filled figure again for the Grade H lines that follow it (2026-11-03)
        ok_, why_, _c = gradeh_bu_refresh(db, me, srow)
        if not ok_:
            raise GradehRefusal(why_)
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' set for %d %s (%d added, %d updated, %d taken off%s)%s" % (
        act["name"], display_company(bg, co) or co, st["kpi_name"], st["n"],
        "person" if st["n"] == 1 else "people", n["added"], n["updated"], n["removed"], _bu_apply_trail(n),
        (", made a BU KPI for this unit only, from the KPI library" if st["pick"] else "")
        + ((" · %d added who did not carry it (%s)" % (len(added_w), ", ".join(
            "%s at %g%%" % (e, w) for e, w in sorted(added_w.items())))) if added_w else "")), None)
    return srow, n


def _bu_kpi_late_parse(form, srow, cfg):
    """The super admin's late amendment of a saved BU KPI setup, read from the form (2026-11-14): (the figures, None) or (None, why).
    ONLY the target figures (`_BU_SCALE_COLS`, through the import's own rules `_pm_kpi_values`, the scale check included), the unit and
    the method are read here; carriers, weight, bands, category and the library link are never in what this returns, so a form that
    posts them changes nothing: the saved setup keeps them. The method and the unit are the saved ones when the form does not post
    them (absent is not empty)."""
    name = srow["kpi_name"]
    method = (form.get("method") if "method" in form else srow["method"]) or ""
    rec = {"kpi": name, "weightage": "1", "method": method}
    for i in range(1, 6):
        rec["rate %d" % i] = form.get("rate%d" % i, "")
    for c in ("threshold", "target", "multiple", "excellence"):
        rec[c] = form.get(c, "")
    vals, err = _pm_kpi_values(rec, cfg, name)
    if err:
        return None, err
    out = {c: vals[c] for c in _BU_SCALE_COLS}
    out["method"] = vals["method"]
    out["unit"] = kpi_unit_normalise(form.get("unit")) if "unit" in form else kpi_unit_normalise(srow["unit"])
    return out, None


def _bu_late_reach(db, act, srow, people):
    """Who the super admin's late save of this setup reaches (read only, ONE batched read of the setup's lines, the people and the
    release / calibration facts): {"n": people holding a line of this setup, "released": how many of them are released (a late save
    leaves them as they are), "calibrated": how many of the rest a calibrator has acted on (their band stays as they set it; a band
    nobody moved follows the new score), "reach": n - released}. `_pm_calibration_hold`'s rule; the lines are `_bu_kpi_apply(late)`'s."""
    pool = {p["id"] for p in _bu_kpi_pool(db, act, srow, people)}
    linked = sorted({r[0] for r in db.execute("SELECT subject_id FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=?",
                                              (act["id"], srow["id"]))} & pool)
    out = {"n": len(linked), "released": 0, "calibrated": 0, "reach": len(linked)}
    if not linked:
        return out
    rel = setup_released_many(db, linked, act["id"], "pm")
    subj = []
    for i in range(0, len(linked), 900):
        part = linked[i:i + 900]
        subj += db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part).fetchall()
    hold = _pm_calibration_hold(db, act["id"], subj)
    out["released"] = sum(1 for i in linked if rel.get(i))
    out["calibrated"] = sum(1 for i in linked if i in hold and not rel.get(i))
    out["reach"] = out["n"] - out["released"]
    return out


def _bu_kpi_save_late(db, me, act, srow, vals, people, touched=None):
    """The super admin's late amendment of one saved BU KPI setup (Chris, 2026-11-14: "allow super admin to amend the BU KPI target and
    result, with a warning message that the Department Review has already begun. BU KPI can still be amended till the result
    release"): the setup's target figures, unit and method (`vals`, `_bu_kpi_late_parse`) are written and NOTHING else of it -- carriers,
    guests, weight and bands, category and library link stay as saved -- then `_bu_kpi_apply(late=True)` puts them on the lines already
    linked to it (nobody added or taken off; a released person never touched; a moderated line keeps its moderation), and the Grade H lines
    that follow it are scored again (`gradeh_bu_refresh`, which leaves a released unit as it is; GradehRefusal when refused). The caller
    commits, flushes `touched`, and checks the super admin and the remark first (SUPER_BAND_ENDPOINTS). One audit row (the remark rides on
    it). Returns (the setup row, the apply counts, the reach `_bu_late_reach` read before)."""
    reach = _bu_late_reach(db, act, srow, people)
    db.execute("UPDATE pm_bu_kpis SET unit=?, method=?, %s, updated_by=?, updated_at=datetime('now') WHERE id=?"
               % ", ".join("%s=?" % c for c in _BU_SCALE_COLS),
               [vals["unit"], vals["method"]] + [vals[c] for c in _BU_SCALE_COLS] + [me["id"], srow["id"]])
    row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (srow["id"],)).fetchone()
    n = _bu_kpi_apply(db, me, act, row, _bu_kpi_pool(db, act, row, people), locked_ok=True, touched=touched, late=True)
    ok_, why_, _c = gradeh_bu_refresh(db, me, row)
    if not ok_:
        raise GradehRefusal(why_)
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' amended late, after the Department Review started (%d updated%s; %d reached, of them %d "
                "calibrated: a band a calibrator moved stays)" % (
                    act["name"], display_company(srow["business_group"], srow["company"]) or srow["company"], srow["kpi_name"],
                    n["updated"], _bu_apply_trail(n), reach["reach"], reach["calibrated"]), None)
    return row, n, reach


def _bu_late_words(n, reach):
    """What the page says after the super admin's late amendment (`_bu_kpi_save_late`), from the apply counts and the reach read before."""
    pl = lambda k, one="line", many="lines": one if k == 1 else many   # noqa: E731
    s = "%d of %d %s took the new target, unit and method." % (n["updated"], reach["reach"], pl(reach["reach"]))
    if n.get("with_results"):
        s += " %d had results: the results themselves are untouched." % n["with_results"]
    if n.get("kept_moderated"):
        s += " %d moderated %s kept %s moderation and %s scored against the new target." % (
            n["kept_moderated"], pl(n["kept_moderated"]), "its" if n["kept_moderated"] == 1 else "their",
            "is" if n["kept_moderated"] == 1 else "are")
    if reach.get("calibrated"):
        s += " %d calibrated: a band a calibrator moved stays, a band nobody moved follows the new score." % reach["calibrated"]
    if n.get("released"):
        s += " %d left as they are: their result is released." % n["released"]
    if n.get("differs"):
        s += " %d held because their own result is in another unit or method." % n["differs"]
    return s


def _bu_late_warning(db, act):
    """The super admin's warning on BU KPI setup once the Department Review has started (2026-11-14): said once at the top of the page
    and again in the amend card, in Group People's words."""
    opens, _c = window_dates(db, "pm_hod", act["id"]) if act else (None, None)
    when = ("started on %s" % _when_disp(opens)) if _parse_when(opens) else "has already begun"
    return ("The Department Review %s. As super admin you can still change a KPI's target, unit and method until results are released. "
            "A change reaches lines already reviewed and calibrated: a band a calibrator moved stays; a band nobody moved follows the new "
            "score. Released people are left as they are." % when)


def _bu_line_differs(line, setup):
    """Whether a line linked to a saved BU KPI setup holds other figures, unit or method than the setup (2026-11-14): its nine
    scale figures (5 and 5.0 are the same), its unit as the app stores it and its method. `line` is a pm_kpi_targets row or a dict
    of one with those columns (a dict without `method` is not compared on it); weight, name and the holder's own words are not
    part of it."""
    line = dict(line)
    if any(_bu_num(line[c]) != _bu_num(setup[c]) for c in _BU_SCALE_COLS):
        return True
    if (kpi_unit_normalise(line.get("unit")) or "") != (kpi_unit_normalise(setup["unit"]) or ""):
        return True
    m = line.get("method")
    return m is not None and m.strip().lower() != (setup["method"] or "").strip().lower()


def _bu_kpi_held_lines(db, act, srow, people):
    """The lines still on earlier figures (2026-11-14): lines already linked to this saved setup (`bu_kpi_id`) whose person it still
    covers (`_bu_kpi_covers`; its guests too, `_bu_kpi_pool`) and whose figures, unit or method differ from it (`_bu_line_differs`):
    [(person, line row)]. A setup save leaves such a line where a person's own result would mean something else in a new unit. It
    never lists anyone without a linked line, so acting on it can only bring a line onto the setup, never add or take one off. One
    batched read."""
    pool = {p["id"]: p for p in _bu_kpi_pool(db, act, srow, people) if _bu_kpi_covers(srow, p)}
    out = []
    ids = sorted(pool)
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        for t in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=? AND subject_id IN (%s)"
                            % ",".join("?" * len(part)), [act["id"], srow["id"]] + part):
            # a person the setup gives no weight (a grade in no band) is one a save would take off: never brought here
            if _bu_line_differs(t, srow) and _bu_kpi_weight(srow, pool[t["subject_id"]], dict(t)) is not None:
                out.append((pool[t["subject_id"]], t))
    out.sort(key=lambda x: (x[0]["full_name"] or "").lower())
    return out


def _bu_kpi_held_plan(db, act, srow, people):
    """Who Bring them onto this setup would act on, read only (2026-11-14; the job kit's check reads it too, so the rule is written once):
    {"found": [(person, line)] every line on earlier figures (`_bu_kpi_held_lines`), "released": [person ids] left as they are (their result
    is released), "calibrated": [person ids] left as they are (`_pm_calibration_hold`, Fill BU result's own rule), "keep": [people] handed to
    `_bu_kpi_apply`, "typed": {person ids} of `keep` whose line the apply will still hold, because the person's own typed result (or a
    moderated fill) would mean something else in the setup's unit or method}. The lines that will take the saved figures are keep minus typed."""
    found = _bu_kpi_held_lines(db, act, srow, people)
    plan = {"found": found, "released": [], "calibrated": [], "keep": [], "typed": set()}
    if not found:
        return plan
    ids = [p["id"] for p, _t in found]
    rel = setup_released_many(db, ids, act["id"], "pm")
    subj = db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(ids)), ids).fetchall()
    hold = _pm_calibration_hold(db, act["id"], subj)
    for p, t in found:
        if rel.get(p["id"]):
            plan["released"].append(p["id"])
        elif p["id"] in hold:
            plan["calibrated"].append(p["id"])
        else:
            plan["keep"].append(p)
            if (_bu_line_locked(db, t["id"]) and _bu_meaning(t["method"], t["unit"]) != _bu_meaning(srow["method"], srow["unit"])
                    and not _bu_line_unit_fill(db, t["id"])):
                plan["typed"].add(p["id"])
    return plan


def _bu_kpi_bring_held(db, me, act, srow, people, touched=None):
    """Bring the lines still on earlier figures onto the saved setup (Chris, 2026-11-14: "edited BU KPI target must reach the Fill BU KPI
    page"): the lines `_bu_kpi_held_plan` keeps, through the one writer `_bu_kpi_apply` (locked_ok), so each takes the setup's figures, unit
    and method exactly as a save would give them, a line with a result goes back to its moderators when one had signed it off, and the
    result itself is never touched. The setup is not changed and nobody is added or taken off. Not brought: a person whose result is
    released, or whom `_pm_calibration_hold` holds (the rule Fill BU result uses: "Calibrated, left as is"); a line a person's own
    typed result holds because its unit or method would change stays held, counted in `n["differs"]`. The caller commits, then
    flushes `touched`. Returns (_bu_kpi_apply's counts, {"released": n, "calibrated": n} people skipped, how many lines were on earlier figures)."""
    plan = _bu_kpi_held_plan(db, act, srow, people)
    skipped = {"released": len(plan["released"]), "calibrated": len(plan["calibrated"])}
    return (_bu_kpi_apply(db, me, act, srow, plan["keep"], locked_ok=True, touched=touched), skipped, len(plan["found"]))


def _bu_held_words(n, skipped, found):
    """What the page says after Bring them onto this setup: how many lines took the saved figures, and what was left (released,
    calibrated, a person's own result whose unit or method would change)."""
    pl = lambda k: "line" if k == 1 else "lines"   # noqa: E731
    s = "%d of %d %s now on the saved figures" % (n["updated"], found, pl(found))
    if n.get("with_results"):
        s += " (%d with results took the new target%s: the results themselves are untouched)" % (
            n["with_results"], ("; %d went back to %s" % (n["remoderated"], "its moderator" if n["remoderated"] == 1 else "their moderators"))
            if n.get("remoderated") else "")
    s += "."
    if skipped["released"]:
        s += " %d left as they are: their result is released." % skipped["released"]
    if skipped["calibrated"]:
        s += " %d calibrated, left as is." % skipped["calibrated"]
    if n.get("differs"):
        s += " %d held because their own result is in another unit or method." % n["differs"]
    return s


def _bu_unit_person(db, bg, co, uid):
    """One of the unit's people taking part in the active cycle (what `_bu_unit_people` lists, for one person), as a dict, or
    None when they are not in that unit, not taking part or an admin. One query."""
    r = db.execute(
        "SELECT id, employee_id, full_name, department, job_grade, manager_id, business_group, company FROM users "
        "WHERE id=? AND business_group=? AND company=? AND role!='admin' AND COALESCE(is_demo,0)=0 AND "
        + participant_sql(module='pm'), (uid, bg, co)).fetchone()
    return dict(r) if r else None


def _bu_kpi_add_one(db, me, act, srow, person, weight):
    """Add ONE person who does not carry a saved BU KPI, from the person page's Add a KPI (2026-11-07, Chris: "i can go to the BU
    KPI to select the person to add, or I can add her from her KPI page"): (the _bu_kpi_apply counts, None) or (None, why),
    nothing written on a refusal. The server trusts nothing the page said: the cycle's rules (`_bu_add_cycle_refusal`), the
    person in the setup's own unit and taking part, and the per-person rules (`_bu_add_refusal`, the BU KPI card's Add block
    shares them) are all checked here. The setup keeps the person in carriers_json "people", the weight rides in "added_w" for
    `_bu_kpi_weight` while `_bu_kpi_apply(only=their id)` puts the line on at the unit's target (an acted-on line of anyone
    else is never touched: no locked_ok), then it is not left on the setup. The caller commits, then `_redo_flush`: the line is
    added through `_admin_kpi_insert`, which collects the "something changed" email for someone who already started, as the
    card's save does. Logged with the BU KPI trail's words."""
    why = _bu_add_cycle_refusal(db, me, act, srow)
    if why:
        return None, why
    bg, co = srow["business_group"], srow["company"]
    person = _bu_unit_person(db, bg, co, person["id"]) if person else None
    eid = ja_eid(person["employee_id"]) if person else ""
    held = {_kpi_key(r[0]) for r in db.execute("SELECT kpi_name FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=?",
                                               (act["id"], person["id"]))} if person else set()
    n_, tot = _bu_kpi_totals(db, act, [person])[eid] if person else (0, 0.0)
    why = _bu_add_refusal(eid, bool(person), _kpi_key(srow["kpi_name"]) in held, tot, weight if weight is not None else "",
                          person=True)
    if why:
        return None, why
    w = _bu_add_weight(weight)
    data = json.loads(srow["carriers_json"]) if srow["carriers_json"] else {}
    data["people"] = sorted(set(data.get("people") or []) | {eid})
    data["added_w"] = {eid: w}
    db.execute("UPDATE pm_bu_kpis SET carriers_json=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
               (json.dumps(data), me["id"], srow["id"]))
    row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (srow["id"],)).fetchone()
    n = _bu_kpi_apply(db, me, act, row, [person], only=person["id"])
    clean = {a: b for a, b in data.items() if a != "added_w"}
    db.execute("UPDATE pm_bu_kpis SET carriers_json=? WHERE id=?", (json.dumps(clean), srow["id"]))
    if n["added"] != 1:   # nothing else can come of it: the caller rolls back
        return None, "That did not come out as planned, so nothing was changed."
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' set for %d %s (%d added, %d updated, %d taken off) \u00b7 1 added from the "
                "person page (%s at %g%%)" % (act["name"], display_company(bg, co) or co, srow["kpi_name"], len(clean["people"]),
                                             "person" if len(clean["people"]) == 1 else "people", n["added"], n["updated"],
                                             n["removed"], eid, w), person["id"])
    return n, None


def _bu_guest_refusal(db, me, act, srow, person, weight=None, held=None, total=None, adopt=None):
    """THE check of adding someone from ANOTHER unit of the setup's business group to a saved BU KPI as a guest carrier (2026-11-07,
    Chris: "a person in BU 1 carries BU 2's BU KPI"; one check for the person page's Add a KPI, the BU KPI card's Add block, the
    people search that offers them and the KPI targets import's "another unit's BU KPI", so all four refuse the same things in the same words): why not, or None. `person` is a users
    row / dict (or None). `weight` None skips the weight rules (a page that has not asked for one yet). `held` / `total` are what
    they hold now ({folded KPI names of their lines in the cycle}, what their weights add up to) when the caller read them for
    many people in one batch; left None they are read here for this one person. In order: the cycle's rules
    (`_bu_add_cycle_refusal`: the super admin, the active cycle, not an Early Year, setup open, a setup of those who carry it now at their
    own weight); the person is taking part, in the setup's business group (another group is refused: groups score differently) and in
    ANOTHER unit of it; they are not already a guest or a holder; they hold no line whose root (`_bu_root`) is this setup's root (one PAT a
    person: take that off first); then the weight rules of `_bu_add_refusal` (under 100%, a weight above 0, a total of 100% or under)."""
    why = _bu_add_cycle_refusal(db, me, act, srow)
    if why:
        return why
    bg, co = srow["business_group"], srow["company"]
    if not person or _row_get(person, "role") == "admin" or _row_get(person, "is_demo"):
        return "They aren't taking part in %s, so a BU KPI can't go on them." % act["name"]
    if (person["business_group"] or "") != bg:
        return "%s is in another business group: a BU KPI is carried within its own group." % (
            display_company(person["business_group"], person["company"]) or person["company"] or "Their unit")
    if not (person["company"] or "").strip():
        return "They aren't in a unit of %s, so a BU KPI can't go on them as a guest." % display_bg(bg)
    uname = display_company(bg, co) or co
    if person["company"] == co:
        return "They are in %s itself: a guest is someone from another unit." % uname
    if not db.execute("SELECT 1 FROM users WHERE id=? AND role!='admin' AND COALESCE(is_demo,0)=0 AND " + participant_sql(module='pm'),
                      (person["id"],)).fetchone():
        return "They aren't taking part in %s, so a BU KPI can't go on them." % act["name"]
    eid = ja_eid(person["employee_id"])
    # `adopt` (2026-11-07, the KPI targets import): the id of the line the import has just written for them. It is the line that will become
    # the guest's, so it is not "a line they already carry" and its weight is not on top of the weight they are given: held and total leave it out
    if held is None:
        held = {_kpi_key(kpi_line_base(r[0], r[1])) for r in db.execute(
            "SELECT kpi_name, focus FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? AND id!=?", (act["id"], person["id"], adopt or 0))}
    if total is None:
        total = _bu_kpi_totals(db, act, [person])[eid][1]
        if adopt:
            total = max(0.0, total - float(db.execute("SELECT COALESCE(weightage,0) FROM pm_kpi_targets WHERE id=? AND subject_id=?",
                                                     (adopt, person["id"])).fetchone()[0] or 0))
    try:
        carried = set((json.loads(srow["carriers_json"] or "{}") or {}).get("people") or [])
    except ValueError:
        carried = set()
    why = _bu_add_refusal(eid, True, eid in _bu_kpi_guests(srow) or eid in carried or _kpi_key(srow["kpi_name"]) in held, 0.0, None, person=True)
    if why:
        return why
    root = _kpi_key(_bu_root(srow["kpi_name"]))
    if any(_kpi_key(_bu_root(n)) == root for n in held):
        return "They already carry a KPI named %s: take that off first." % _bu_root(srow["kpi_name"])
    return _bu_add_refusal(eid, True, False, total, weight, person=True)


def _bu_kpi_add_guest(db, me, act, srow, person, weight, adopt=None, touched=None):
    """Add ONE person of another unit in the setup's business group to a saved BU KPI as a guest carrier (2026-11-07; canvas boards A1 to
    B2): (the `_bu_kpi_apply` counts, None) or (None, why), nothing written on a refusal. THE writer for both ways in (the person page's
    Add a KPI and the BU KPI card's "From another unit" part), every refusal `_bu_guest_refusal`'s. The guest is kept in carriers_json
    "guests" {Employee ID: weight} (their weight is their own, given here, whatever the setup's rule) and `_bu_kpi_apply(only=their id)`
    puts the line on at the setup's target, linked by bu_kpi_id (never locked_ok: nobody else's line is touched); their own business group and
    company stay on the line, so their own line manager moderates and their own unit's BU CEO calibrates them. One line must come of it, else
    (None, why) and the caller rolls back. The caller commits, then `_redo_flush` (the line goes through `_admin_kpi_insert`). Logged
    with the BU KPI trail's words.
    `adopt` (2026-11-07, the KPI targets import's join to another unit's BU KPI): the id of the line the import has just written for this
    person. Their line is not added but linked first, so `_bu_kpi_apply` brings THAT line to the setup's name and target (what the file gave
    it is kept to go back to) at the weight it holds; the checks leave it out of "already carries" and out of their total (`_bu_guest_refusal`)."""
    pid = person["id"] if person else None
    p = db.execute("SELECT id, employee_id, full_name, department, job_grade, manager_id, business_group, company, role, is_demo FROM users "
                   "WHERE id=?", (pid,)).fetchone() if pid else None
    p = dict(p) if p else None
    why = _bu_guest_refusal(db, me, act, srow, p, weight if weight is not None else "", adopt=adopt)
    if why:
        return None, why
    if adopt and not db.execute("SELECT 1 FROM pm_kpi_targets WHERE id=? AND subject_id=? AND cycle_id=?", (adopt, p["id"], act["id"])).fetchone():
        return None, "That did not come out as planned, so nothing was changed."
    eid = ja_eid(p["employee_id"])
    w = _bu_add_weight(weight)
    data = json.loads(srow["carriers_json"]) if srow["carriers_json"] else {}
    guests = dict(data.get("guests") or {})
    guests[eid] = w
    data["guests"] = guests
    db.execute("UPDATE pm_bu_kpis SET carriers_json=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
               (json.dumps(data), me["id"], srow["id"]))
    row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (srow["id"],)).fetchone()
    if adopt:   # linked first: the setup adopts THIS line, whatever name the file gave it (as the import's own-unit join does)
        db.execute("UPDATE pm_kpi_targets SET bu_kpi_id=?, bu_keep_own=0 WHERE id=?", (srow["id"], adopt))
    n = _bu_kpi_apply(db, me, act, row, [p], only=p["id"], touched=touched)
    if adopt:   # an adopted line comes out as updated (or unchanged when the file already gave the unit's own figures), never added or held
        ok_ = n["held"] == 0 and n["added"] == 0 and db.execute("SELECT 1 FROM pm_kpi_targets WHERE id=? AND bu_kpi_id=?", (adopt, srow["id"])).fetchone()
    else:
        ok_ = n["added"] == 1
    if not ok_:   # nothing else can come of it: the caller rolls back
        return None, "That did not come out as planned, so nothing was changed."
    bg, co = srow["business_group"], srow["company"]
    n_carry = len(data.get("people") or []) + len(guests)
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' set for %d %s (%d added, %d updated, %d taken off) \u00b7 1 added from another unit "
                "(%s, %s at %g%%)%s" % (act["name"], display_company(bg, co) or co, srow["kpi_name"], n_carry,
                                        "person" if n_carry == 1 else "people", n["added"], n["updated"], n["removed"], eid,
                                        display_company(p["business_group"], p["company"]) or p["company"], w,
                                        " \u00b7 their imported line joined it" if adopt else ""), p["id"])
    return n, None


def _bu_kpi_guest_posts(form, lid):
    """The guests a BU KPI card's save names (2026-11-07, canvas B2): [(Employee ID, the weight text)] from `k<lid>_gadd` (the picked
    people's Employee IDs) with `k<lid>_gaddw_<eid>`, in order, each once. Absent is empty: a post without them adds nobody."""
    k = "k%d_" % lid
    out, seen = [], set()
    for x in form.getlist(k + "gadd"):
        e = ja_eid(x)
        if e and e not in seen:
            seen.add(e)
            out.append((e, form.get("%sgaddw_%s" % (k, e)) or ""))
    return out


def _bu_kpi_add_guests(db, me, act, srow, posts, touched=None):
    """Add the card's picked guests, one `_bu_kpi_add_guest` each (the one writer, so the card refuses what the person page refuses, in the
    same words), in the caller's transaction: (the people added [(Employee ID, name, unit, weight)], None) or (None, why): the first
    refusal, naming the person, and the caller rolls the whole save back. Each person is found by their Employee ID, never by what a
    form says about them."""
    done = []
    for eid, raw in posts:
        # an Employee ID can have a leaver's account and an active one: the account taking part first, never just the oldest
        u = db.execute("SELECT id, employee_id, full_name, business_group, company FROM users WHERE UPPER(TRIM(employee_id))=? AND role!='admin' "
                       "AND COALESCE(is_demo,0)=0 ORDER BY CASE WHEN " + participant_sql("users", "pm") + " THEN 0 ELSE 1 END, id",
                       (eid,)).fetchone()
        if not u:
            return None, "%s isn't someone in OneHR, so they can't be added." % eid
        row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (srow["id"],)).fetchone()
        n, why = _bu_kpi_add_guest(db, me, act, row, u, raw, touched=touched)
        if why:
            return None, "%s (%s): %s" % (u["full_name"], eid, why)
        done.append((eid, u["full_name"], display_company(u["business_group"], u["company"]) or u["company"], _bu_add_weight(raw)))
    return done, None


def _bu_kpi_remove_one(db, me, act, srow, person, tid=None, clear_bu_result=False, reason=None):
    """Take ONE person off a saved BU KPI from the person page (2026-11-07, Chris: "allow remove the person from the BU KPI list"):
    (the _bu_kpi_apply counts, None) or (None, why), nothing written on a refusal. Exactly what unticking them under Who carries
    it on BU KPI setup does: their Employee ID leaves carriers_json "people", then `_bu_kpi_apply(only=their id)` (not locked_ok)
    puts that person off: a line the setup put on comes off ('removed'), a line it took over goes back as it was before
    ('returned', `_bu_line_release`, the one rule). The next save of the setup keeps them off. Every refusal is
    `_bu_remove_refusal`'s; `tid` (the line the page named) must be that line. The caller commits.
    `clear_bu_result=True` (the super admin's "Clear result and take off", 2026-11-07; the SAME writer, never a second path):
    the line's one BU-filled result goes first, in this transaction. `reason` is then required (`_bu_clear_reason`); an audit
    row (action pm_kpi_result_clear, on the person) holds the old result's values and the line's id and name as JSON, so the
    row can be put back by hand; then the take-off runs as above through the same refusal helper (a result gone leaves the line
    unlocked), and the person's rating record is rebuilt (`_rating_record_refresh`). Any refusal or a take-off that does not
    come out as planned returns (None, why) and the caller's rollback puts the result back."""
    p = db.execute("SELECT id, employee_id, full_name, department, job_grade, manager_id, business_group, company FROM users "
                   "WHERE id=?", (person["id"],)).fetchone() if person else None
    p = dict(p) if p else None
    t = db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? AND bu_kpi_id=?",
                   (act["id"], p["id"], srow["id"])).fetchone() if (p and srow) else None
    if t and tid is not None and t["id"] != tid:
        t = None
    why = _bu_remove_refusal(db, me, act, srow, dict(t) if t else None, p, clear_bu_result=clear_bu_result)
    if why:
        return None, why
    old = None
    if clear_bu_result:
        reason, why = _bu_clear_reason(reason)
        if why:
            return None, why
        res = db.execute("SELECT * FROM pm_kpi_results WHERE kpi_target_id=?", (t["id"],)).fetchone()
        if not res:   # the refusal helper has said so already; the writer never assumes it
            return None, "Their line has no filled result to clear: take them off without it."
        old = {"line": t["id"], "kpi": t["kpi_name"], "result_id": res["id"], "actual_value": res["actual_value"],
               "note": res["note"], "submitted_at": res["submitted_at"], "submitted_by": res["submitted_by"],
               "admin_filled": res["admin_filled"], "draft": res["draft"]}
        if db.execute("DELETE FROM pm_kpi_results WHERE id=? AND kpi_target_id=? AND admin_filled=1 AND draft=0",
                      (res["id"], t["id"])).rowcount != 1:
            return None, "That did not come out as planned, so nothing was changed."
    eid = ja_eid(p["employee_id"])
    data = json.loads(srow["carriers_json"]) if srow["carriers_json"] else {}
    data["people"] = sorted(set(data.get("people") or []) - {eid})
    was_guest = _bu_guest_drop(data, eid)   # a guest leaves "guests" (2026-11-07), the one place they were kept
    db.execute("UPDATE pm_bu_kpis SET carriers_json=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
               (json.dumps(data), me["id"], srow["id"]))
    row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (srow["id"],)).fetchone()
    n = _bu_kpi_apply(db, me, act, row, [p], only=p["id"])
    if n["removed"] + n["returned"] != 1:   # nothing else can come of it: the caller rolls back
        return None, "That did not come out as planned, so nothing was changed."
    bg, co = srow["business_group"], srow["company"]
    if old:
        _leader_log(db, me["id"], "pm_kpi_result_clear", "%s, %s: '%s' BU-filled result %s cleared for %s with their take-off "
                    "(put it back by hand from this) \u00b7 reason: %s \u00b7 old row: %s" % (
                        act["name"], display_company(bg, co) or co, srow["kpi_name"], _commas(old["actual_value"]), eid, reason,
                        json.dumps(old, sort_keys=True)), p["id"])
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' set for %d %s (0 added, 0 updated, %d taken off%s) \u00b7 1 taken off from the "
                "person page (%s%s)%s" % (act["name"], display_company(bg, co) or co, srow["kpi_name"], len(data["people"]) + len(data.get("guests") or {}),
                                        "person" if len(data["people"]) + len(data.get("guests") or {}) == 1 else "people", n["removed"],
                                        (", %d given back as they were" % n["returned"]) if n["returned"] else "", eid,
                                        (", a guest from %s" % (display_company(p["business_group"], p["company"]) or p["company"] or "another unit"))
                                        if was_guest else "",
                                        " \u00b7 its BU-filled result cleared first" if old else ""), p["id"])
    if old:   # the result is gone: their rating record is rebuilt without it, after the line has come off
        _rating_record_refresh(db, act["id"], [p["id"]], "bu_result_clear", me["id"])
    return n, None


def _bu_save_words(n):
    """What the page says after a BU KPI save, from the _bu_kpi_apply counts: lines added, updated (and of those how many
    had results and how many of them went back to their moderators), taken off, given back, and the ones held with the
    reason -- someone acted on them (a person no longer covered) or the method or unit differs."""
    pl = lambda k, one="line", many="lines": one if k == 1 else many   # noqa: E731
    s = "%d line%s added, %d updated, %d taken off" % (n["added"], "" if n["added"] == 1 else "s", n["updated"],
                                                        n["removed"])
    if n.get("returned"):
        s += ", %d given back as they were" % n["returned"]
    s += "."
    if n.get("with_results"):
        s += " Of the updated lines, %d had results and took the new target" % n["with_results"]
        if n.get("remoderated"):
            s += "; %d went back to %s" % (n["remoderated"], "its moderator" if n["remoderated"] == 1 else "their moderators")
        s += ": the results themselves are untouched."
    acted = n["held"] - n.get("differs", 0)
    if acted > 0:
        s += " %d %s left as they were: someone has acted on them." % (acted, pl(acted))
    if n.get("differs"):
        s += " %d %s held because the method or unit differs." % (n["differs"], pl(n["differs"]))
    if n.get("released"):
        s += " %d %s left as they %s: %s released." % (n["released"], "person" if n["released"] == 1 else "people",
                                                        "are", "their result is" if n["released"] == 1 else "their results are")
    return s


def _bu_kpi_take_off(db, me, act, bg, co, row, people, touched=None):
    """Take ONE saved BU KPI off its unit (what unticking it and saving did): its lines come off or go back to their
    holders as they were (_bu_kpi_apply remove=True); unless a line someone acted on is held, the setup goes and so does
    the unit-only library mark it made. Touches no other KPI. The caller commits. The _bu_kpi_apply counts.
    The Grade H lines that follow it go back to their own (gradeh_bu_unlink_setup); GradehRefusal, nothing written, when that is refused
    (an appraisal already submitted with no figure of the person's own on that line: Reopen first)."""
    ok_, why_, n_gh = gradeh_bu_unlink_setup(db, me, row)
    if not ok_:
        raise GradehRefusal(why_)
    n = _bu_kpi_apply(db, me, act, row, _bu_kpi_pool(db, act, row, people), remove=True, touched=touched)   # the guests' lines go back too (2026-11-07)
    n["gh_unlinked"] = n_gh
    if not n["held"]:
        db.execute("UPDATE pm_kpi_targets SET bu_kpi_id=NULL WHERE bu_kpi_id=?", (row["id"],))
        db.execute("DELETE FROM pm_bu_kpis WHERE id=?", (row["id"],))
        _bu_kpi_unit_row_undo(db, me, row)
    _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' no longer a BU KPI (%d taken off, %d given back as they "
                "were%s)" % (act["name"], display_company(bg, co) or co, row["kpi_name"], n["removed"], n["returned"],
                             (", %d held: someone acted on them" % n["held"]) if n["held"] else ""), None)
    return n


# ---- Move some of a BU KPI's carriers to a variant (Chris, 2026-10-29; canvas [design canvas link removed]) --
# A saved BU KPI is one name and one target for everyone who carries it. When some of them turn out to hold their own
# target, the super admin moves THEM to a variant: the same KPI under its root, with a name and target of its own, for this
# unit only ("Profit after tax (PAT): Group"), or into a variant that already exists (moving back to the root, or merging
# two whose targets turned out the same). The data move is what pat_split.py did by script on 29 Oct, done by one writer.
def _bu_root(name):
    """A BU KPI's root: the part of its name before the first ': ' (the whole name when it has none)."""
    return (name or "").split(": ", 1)[0].strip()


def _bu_rail_layout(rows):
    """THE one grouping of a BU rail's saved rows (dicts with "name"), shared by BU KPI setup and Fill BU result (2026-11-06; the
    Fill rail followed the setup rail on 5 Nov). A variant ("<root>: <qualifier>") sits right under its root when the root is
    saved in the unit too (sub=True); when it is NOT, the saved variants of one root (one or more, since 2026-11-08: a lone variant
    sits under its root too) sit under a heading row for the root ({"heading": True, "name": <root>, "n": <variants>}, not a
    link, not a setup) placed where the root's name would sort among the rows. A name with no ': ' stays a plain row. Takes rows already in name order. Returns
    (real, view): `real` the setups in display order (selection, counts and the first pick read this), `view` the same with
    the heading rows (what the template draws). Display only: names, setups and targets are untouched."""
    keys = {_kpi_key(x["name"]) for x in rows}
    unsaved = {}
    for x in rows:
        rk = _kpi_key(_bu_root(x["name"]))
        if rk and rk != _kpi_key(x["name"]) and rk not in keys:
            unsaved.setdefault(rk, []).append(x)
    head = dict(unsaved)   # one or more saved variants of an unsaved root get its heading (2026-11-08)
    top, subs = [], {}
    for x in rows:
        rk = _kpi_key(_bu_root(x["name"]))
        under = rk and rk != _kpi_key(x["name"]) and (rk in keys or rk in head)
        x["sub"] = bool(under)
        if under:
            subs.setdefault(rk, []).append(x)
        else:
            top.append(x)
    ents = [(x["name"].lower(), "row", x) for x in top]
    for rk, v in head.items():
        h = {"heading": True, "name": _bu_root(v[0]["name"]), "n": len(v), "sub": False}
        at = next((i for i, e in enumerate(ents) if e[0] > h["name"].lower()), len(ents))
        ents.insert(at, (h["name"].lower(), "head", h))
    real, view = [], []
    for _k, kind, x in ents:
        if kind == "head":
            view.append(x)
            kids_ = head[_kpi_key(x["name"])]
            real.extend(kids_)
            view.extend(kids_)
        else:
            kids_ = subs.get(_kpi_key(x["name"]), [])
            real.append(x)
            view.append(x)
            real.extend(kids_)
            view.extend(kids_)
    return real, view


def _bu_siblings(rows, name):
    """The saved setups (dicts with a kpi_name) that share `name`'s root, the root itself first, then by name. The setup
    `name` belongs to is in the list."""
    rk = _kpi_key(_bu_root(name))
    out = [r for r in rows if _kpi_key(_bu_root(r["kpi_name"])) == rk]
    out.sort(key=lambda r: (_kpi_key(r["kpi_name"]) != rk, (r["kpi_name"] or "").lower()))
    return out


def _bu_kpi_carriers(db, act, row, people):
    """{Employee ID: (the line, the person)} for the lines linked to this setup, of the unit's people taking part and its guests
    (2026-11-07: `_bu_kpi_pool`, so a card lists them and a move can take them along)."""
    byid = {p["id"]: p for p in _bu_kpi_pool(db, act, row, people)}
    out = {}
    for r in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=? ORDER BY id", (act["id"], row["id"])):
        p = byid.get(r["subject_id"])
        if p:
            out[ja_eid(p["employee_id"])] = (dict(r), p)
    return out


def _bu_kpi_guest_lines(db, act, sids):
    """{setup id: [(the line, the person)]}: the guest carriers' lines (2026-11-07) -- the lines linked to these saved BU KPIs
    (`sids`) of people who work in ANOTHER unit than the setup's -- with who holds them (users columns the cards show, and their unit as
    `unit`). By name within a setup. ONE batched query, whatever the number of setups; empty with none."""
    sids = [i for i in dict.fromkeys(sids) if i]
    out = {i: [] for i in sids}
    if not (act and sids):
        return out
    for r in db.execute(
            "SELECT t.*, u.employee_id AS u_eid, u.full_name AS u_name, u.department AS u_dept, u.job_grade AS u_jg, "
            "u.business_group AS u_bg, u.company AS u_co, u.manager_id AS u_mgr FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
            "JOIN pm_bu_kpis b ON b.id=t.bu_kpi_id WHERE t.cycle_id=? AND t.bu_kpi_id IN (%s) AND u.company!=b.company "
            "AND u.business_group=b.business_group ORDER BY u.full_name" % ",".join("?" * len(sids)), [act["id"]] + sids):
        d = dict(r)
        who = {"id": d["subject_id"], "employee_id": d.pop("u_eid"), "full_name": d.pop("u_name"), "department": d.pop("u_dept"),
               "job_grade": d.pop("u_jg"), "business_group": d.pop("u_bg"), "company": d.pop("u_co"), "manager_id": d.pop("u_mgr")}
        who["unit"] = display_company(who["business_group"], who["company"]) or who["company"] or ""
        out[d["bu_kpi_id"]].append((d, who))
    return out


def _bu_carrier_sig(eids):
    """A short checksum of who carries a setup, so a form posted after the carriers changed is told so."""
    return hashlib.sha1("|".join(sorted(eids)).encode()).hexdigest()[:12]


def _bu_lines_lock_words(db, ids):
    """{line id: why it is held} for the lines (pm_kpi_targets ids) someone has acted on: 'Moderated', 'Result entered',
    'Checked in'. The words only; whether a line is held is _bu_line_locked's answer. One read per source."""
    ids = list(ids)
    out = {}
    if not ids:
        return out
    ph = ",".join("?" * len(ids))
    for tb, word in (("pm_checkins", "Checked in"), ("pm_kpi_results", "Result entered"), ("pm_kpi_approvals", "Moderated")):
        for r in db.execute("SELECT DISTINCT kpi_target_id FROM %s WHERE kpi_target_id IN (%s)" % (tb, ph), ids):
            out[r[0]] = word
    return out


class _BuMoveError(Exception):
    """A move that found its own result not what it planned: the caller rolls the whole transaction back."""


_BU_ROLE_RE = re.compile(r"^[A-Za-z0-9 &-]{1,20}$")   # a new role label: letters, digits, spaces, "&" and "-", 20 characters at most
_BU_ROLE_NEW = "__new__"   # the select's "A new role label..." option
_BU_ROLE_BASE = ("GCEO", "CEO")   # always on offer beside the labels already in use


def _bu_join_units(names):
    """Unit names as a name reads them: "A", "A & B", "A, B & C"."""
    names = list(names)
    return names[0] if len(names) == 1 else (", ".join(names[:-1]) + " & " + names[-1] if names else "")


def _bu_role_labels(db, bg, cid):
    """The role labels a new variant's name can take (Chris, 2026-11-07, "PAT: GCEO"): the qualifiers of this business group's saved BU
    KPIs on the cycle (the part after "<root>: ") that are NOT a unit's display name or code, nor the names of units joined ("A & B"),
    plus GCEO and CEO; sorted, case-folded, one spelling each. The one list the page offers and the server checks a pick against."""
    units = set()
    for r in db.execute("SELECT DISTINCT company FROM org_units WHERE business_group=? UNION SELECT DISTINCT company FROM pm_bu_kpis "
                        "WHERE business_group=?", (bg, bg)):
        if (r[0] or "").strip() and r[0] != "*":
            units |= {_kpi_key(r[0]), _kpi_key(display_company(bg, r[0]))}
    seen = {}
    for lab in _BU_ROLE_BASE:
        seen[_kpi_key(lab)] = lab
    for r in db.execute("SELECT kpi_name FROM pm_bu_kpis WHERE cycle_id=? AND business_group=?", (cid, bg)):
        name = r[0] or ""
        if ": " not in name:
            continue
        qual = " ".join(name.split(": ", 1)[1].split())
        parts = [x.strip() for x in re.split(r" & |, ", qual) if x.strip()]
        if not qual or _kpi_key(qual) in units or (parts and all(_kpi_key(x) in units for x in parts)):
            continue
        seen.setdefault(_kpi_key(qual), qual)
    return sorted(seen.values(), key=str.lower)


def _bu_variant_qualifier(db, act, bg, co, form, guest_units=()):
    """What a NEW variant's name says after "<root>: " (Chris, 2026-11-07, canvas C1): (qualifier, None) or (None, why). Built here, on the
    server, from the posted pick `name_by` and nothing else: no typed text ever reaches the name, bar a new role label that passed
    `_BU_ROLE_RE`. `unit` (the default the page starts on): this unit's display name. `units`: the units the ticked people come from, this
    unit first and the others by name ("A & B", "A, B & C"); only when a ticked mover is a guest from another unit (`guest_units`, their
    display names), refused over 80 characters. `role`: `name_role`, one of `_bu_role_labels` or, with `name_role` = "__new__", the new label
    in `name_role_new`. Any other pick, or none, is refused (absent is not empty). The old typed `qualifier` is never read."""
    by = (form.get("name_by") or "").strip()
    uname = display_company(bg, co) or co
    if by == "unit":
        return uname, None
    if by == "units":
        others = sorted({u for u in guest_units if u and _kpi_key(u) != _kpi_key(uname)}, key=str.lower)
        if not others:
            return None, "\"Their units\" is for when someone ticked comes from another unit. Name it after %s, or tick a guest." % uname
        qual = _bu_join_units([uname] + others)
        if len(qual) > 80:
            return None, "The units' names together are too long for a name (%d characters, at most 80). Name it after a role instead." % len(qual)
        return qual, None
    if by == "role":
        role = " ".join((form.get("name_role") or "").split())
        if role == _BU_ROLE_NEW:
            new = " ".join((form.get("name_role_new") or "").split())
            if not _BU_ROLE_RE.match(new):
                return None, "A new role label takes letters, digits, spaces, & and -, up to 20 characters."
            return new, None
        for lab in _bu_role_labels(db, bg, act["id"]):
            if _kpi_key(lab) == _kpi_key(role):
                return lab, None
        return None, "Pick a role from the list, or give a new role label."
    return None, "Pick what the new variant is named after: this unit, their units or a role."


def _bu_kpi_move(db, me, act, bg, co, src, dest, eids, form, people, cfg, early, gh_ids=(), touched=None):
    """Move SOME of a saved BU KPI's carriers to a variant, in the caller's transaction (it commits; nothing is written
    until every check has passed). `src`: the saved setup (pm_bu_kpis row); `dest`: 'new' (a variant with its own name and
    target) or the id of a sibling setup of the same root (moving back to the root, or into another variant: merging when
    that takes all of them); `eids`: the Employee IDs ticked; `form`: the posted panel (qualifier, v_* target fields,
    src_n / src_sig). The super admin's alone. (the result dict, None) or (None, why the move was refused).
    The lines move by name: each ticked line is renamed to the destination and the destination's own save (_bu_kpi_save_one)
    adopts it, keeping the bu_prev_json it already holds, so taking the variant off later gives each line back as it was
    before it ever became a BU KPI. The source's people list loses the movers before anything else could re-apply it, so
    nobody gains a line. Touches no other KPI, unit or weight.
    `gh_ids` (2026-11-03): Grade H lines (gradeh_kpi_lines ids) ticked beside the people: each starts following the destination (a line that
    followed the source is moved off it, one that followed nothing is linked) through gradeh_bu_link. A variant may be made of Grade H lines
    alone (no one of the normal review moves)."""
    if not is_super(me):
        return None, "Only the super admin can move people to a variant."
    src = dict(src)
    if src["cycle_id"] != act["id"] or src["business_group"] != bg or src["company"] != co:
        return None, "That KPI isn't a BU KPI of this unit in %s." % act["name"]
    uname = display_company(bg, co) or co
    sname = src["kpi_name"]
    if src["carriers"] not in ("holders", "pick"):
        return None, ("%s is set for %s, so who carries it follows that rule. Edit it to those who carry it now first." % (
            sname, {"everyone": "everyone", "departments": "some departments", "grade": "a grade range"}.get(
                src["carriers"], "a rule")))
    carriers = _bu_kpi_carriers(db, act, src, people)
    # a form posted before someone changed the KPI (2026-10-29): who carries it must be what the panel showed
    n_post = str(form.get("src_n") or "").strip()
    if n_post != str(len(carriers)) or (form.get("src_sig") or "") != _bu_carrier_sig(carriers):
        if n_post.isdigit() and int(n_post) != len(carriers):
            return None, "%s changed since you opened this: %d carry it now, not %s. Look again, then move." % (
                sname, len(carriers), n_post)
        return None, "%s changed since you opened this: who carries it is not the same now. Look again, then move." % sname
    movers = {ja_eid(x) for x in eids if str(x).strip()}
    gh_ids = [int(x) for x in dict.fromkeys(gh_ids or []) if str(x).isdigit()]
    if gh_ids and not gradeh_on():
        return None, "Grade H Appraisal is not switched on here."
    if not movers and not gh_ids:
        return None, "Tick at least one person to move."
    gh_now = sorted(r[0] for r in db.execute("SELECT id FROM gradeh_kpi_lines WHERE bu_kpi_id=?", (src["id"],)))   # the Grade H lines that follow the source
    if gh_ids:
        gh_post = str(form.get("src_gh") or "").strip()
        if gh_post and gh_post != _bu_carrier_sig([str(x) for x in gh_now]):
            return None, "%s changed since you opened this: the Grade H lines that follow it are not the same now. Look again, then move." % sname
    stray = movers - set(carriers)
    if stray:
        return None, "%d of the people ticked don't carry %s now. Look again, then move." % (len(stray), sname)
    guest_w = _bu_kpi_guests(src)   # the guests from other units (2026-11-07) ride along: they land in the destination's "guests"
    guest_movers = {e for e in movers if e in guest_w}
    unit_movers = movers - guest_movers
    held = [(e, carriers[e]) for e in sorted(movers) if _bu_line_locked(db, carriers[e][0]["id"])]
    if held:
        words = _bu_lines_lock_words(db, [ln["id"] for _e, (ln, _p) in held])
        verb = {"Moderated": "been moderated", "Result entered": "a result entered", "Checked in": "been checked in"}
        w0 = words.get(held[0][1][0]["id"])
        if len(held) == 1:
            return None, "%s's line has %s, so it stays where it is. Reopen it first if it must move." % (
                held[0][1][1]["full_name"], verb.get(w0, "been acted on"))
        return None, ("%s's line and %d other%s have been acted on (moderated, a result or a check-in), so they stay where "
                      "they are. Reopen them first if they must move." % (
                          held[0][1][1]["full_name"], len(held) - 1, "" if len(held) == 2 else "s"))
    rows_unit = [dict(r) for r in db.execute("SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=?",
                                             (act["id"], bg, co))]
    left = set(carriers) - movers
    sdata = json.loads(src["carriers_json"]) if src["carriers_json"] else {}
    mids = [carriers[e][0]["id"] for e in sorted(movers)]
    st, lib_new, drow = None, None, None
    if dest == "new":
        root = _bu_root(sname)
        # Part 2 (2026-11-07): the qualifier is PICKED, never typed; built here from the pick (`_bu_variant_qualifier`)
        qual, why = _bu_variant_qualifier(db, act, bg, co, form, [
            display_company(carriers[e][1]["business_group"], carriers[e][1]["company"]) or carriers[e][1]["company"] or ""
            for e in sorted(guest_movers)])
        if why:
            return None, why
        if len(qual) > 80:
            return None, "What the variant covers is too long: at most 80 characters."
        if not left and movers:
            return None, ("All %d are ticked. That renames the whole KPI and leaves %s with nobody. To change its target "
                          "for all of them, use Edit." % (len(carriers), sname))
        name = root + ": " + qual
        key = _kpi_key(name)
        if any(_kpi_key(r["kpi_name"]) == key for r in rows_unit):
            return None, "%s is already a KPI of %s. Pick it under Move them to, or give another name." % (name, uname)
        taken = any(_kpi_key(r[0]) == key for r in db.execute(
            "SELECT kpi_name FROM pm_kpi_library WHERE active=1 AND business_group=? AND company IN ('*', ?)", (bg, co)))
        if not taken:
            taken = any(_kpi_key(r[0]) == key for r in db.execute(
                "SELECT DISTINCT t.kpi_name FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id WHERE t.cycle_id=? AND "
                "u.business_group=? AND u.company=?", (act["id"], bg, co)))
        if taken:
            return None, "%s is already a KPI of %s: in its library or on someone's scorecard. Give another name." % (name, uname)
        lib0 = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (src["library_id"],)).fetchone() if src["library_id"] else None
        if not lib0:
            return None, "%s has no KPI library row to copy, so it can't be given a variant." % sname
        lib_new = dict(dict(lib0), kpi_name=name, company="*")
        pseudo = dict(dict(lib0), id=0, kpi_name=name, method=src["method"], unit=src["unit"], category=src["category"])
        from werkzeug.datastructures import MultiDict
        pf = MultiDict()
        for fld in ("unit",) + _BU_SCALE_COLS:
            pf["k0_" + fld] = form.get("v_" + fld, "")
        pf["k0_carriers"], pf["k0_holder_set"] = "holders", "1"
        pf.setlist("k0_holder", sorted(unit_movers))
        wmode = (form.get("v_wmode") or "own") if early else "own"
        pf["k0_wmode"] = wmode
        pf["k0_weight"] = form.get("v_weight", "")
        for a_, b_ in (("bmin", "bmin"), ("bmax", "bmax"), ("bw", "bw")):
            pf.setlist("k0_" + a_, form.getlist("v_" + b_))
        st, why = _bu_kpi_parse(db, pf, pseudo, cfg, people, [], early=early, holders=set(unit_movers),
                                gh_only=not unit_movers)   # a variant of guests alone (or of Grade H lines alone) has no unit carrier
        if why:
            return None, why + " Nothing was moved."
        if guest_movers:   # each guest keeps their own weight: the line's, which the variant adopts as it is
            sd_ = json.loads(st["carriers_json"]) if st["carriers_json"] else {}
            sd_["guests"] = {e: (carriers[e][0].get("weightage") if carriers[e][0].get("weightage") is not None else guest_w[e])
                             for e in sorted(guest_movers)}
            st["carriers_json"] = json.dumps(sd_)
        st["pick"] = True
        dname = name
    else:
        drow = next((r for r in _bu_siblings(rows_unit, sname) if str(r["id"]) == str(dest) and r["id"] != src["id"]), None)
        if not drow:
            return None, "Pick one of %s's variants to move them to." % _bu_root(sname)
        dname = drow["kpi_name"]
        if drow["carriers"] not in ("holders", "pick"):
            return None, "%s is set for a rule (everyone, departments or a grade range), so people can't be moved into it." % dname
        ddata = json.loads(drow["carriers_json"]) if drow["carriers_json"] else {}
        dkey = _kpi_key(dname)
        have_dest = [r for r in db.execute(
            "SELECT subject_id, kpi_name FROM pm_kpi_targets WHERE cycle_id=? AND subject_id IN (%s)" % ",".join(
                "?" * len(movers)), [act["id"]] + [carriers[e][1]["id"] for e in sorted(movers)]) if _kpi_key(r[1]) == dkey]
        if have_dest:
            byid = {carriers[e][1]["id"]: carriers[e][1] for e in movers}
            return None, "%s already holds a line named %s, so can't be moved into it." % (
                byid[have_dest[0][0]]["full_name"], dname)
        ppl = sorted(set(ja_eid(x) for x in (ddata.get("people") or [])) | unit_movers)
        dguests = dict(ddata.get("guests") or {})   # the destination's own guests stay; the guests who move join them at their own weight
        for e in sorted(guest_movers):
            dguests[e] = carriers[e][0].get("weightage") if carriers[e][0].get("weightage") is not None else guest_w[e]
        dnew = dict(ddata, people=ppl)
        if dguests:
            dnew["guests"] = dguests
        probe = dict(drow, carriers_json=json.dumps(dnew))
        odd = [e for e in sorted(movers) if _bu_kpi_weight(probe, carriers[e][1], carriers[e][0]) is None]
        if odd:
            return None, "%s's weight rule has no weight for %s, so they can't be moved into it." % (dname, carriers[odd[0]][1]["full_name"])
        st = {c: drow[c] for c in _BU_SAVE_COLS}
        st["carriers_json"] = json.dumps(dnew)
        st["kpi_name"], st["n"], st["pick"] = dname, len(ppl), False
    # ---- every check passed: write ----
    gh_left = [x for x in gh_now if x not in gh_ids]   # Grade H lines still following the source: it is not "nobody left" while they do
    merged = not left and not gh_left
    ph = ",".join("?" * len(mids))
    linked_before = db.execute("SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=?", (act["id"], src["id"])).fetchone()[0]
    if mids:
        db.execute("UPDATE pm_kpi_targets SET kpi_name=?, updated_at=datetime('now'), updated_by=? WHERE id IN (%s)" % ph,
                   [dname, me["id"]] + mids)
    if not merged and movers:   # the source stops listing the movers before anything could apply it again
        sdata["people"] = [x for x in (sdata.get("people") or []) if ja_eid(x) not in movers]
        if guest_movers:   # ... guests included, or the source's next save would put them back
            sdata["guests"] = {e: w for e, w in (sdata.get("guests") or {}).items() if ja_eid(e) not in movers}
            if not sdata["guests"]:
                del sdata["guests"]
        db.execute("UPDATE pm_bu_kpis SET carriers_json=?, updated_by=?, updated_at=datetime('now') WHERE id=?",
                   (json.dumps(sdata), me["id"], src["id"]))
    drow_saved, n = _bu_kpi_save_one(db, me, act, bg, co, lib_new, st, people, gh_refresh=False, touched=touched)
    landed = db.execute("SELECT COUNT(*) FROM pm_kpi_targets WHERE id IN (%s) AND bu_kpi_id=?" % ph, mids + [drow_saved["id"]]).fetchone()[0] if mids else 0
    still = db.execute("SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=?", (act["id"], src["id"])).fetchone()[0]
    if n["added"] or n["removed"] or n["returned"] or landed != len(movers) or still != linked_before - len(movers):
        raise _BuMoveError("the move would have been %s, %d of %d landed, %d left on the source" % (n, landed, len(movers), still))
    n_gh = 0
    if gh_ids:   # the Grade H lines follow the destination now (a line that followed the source is moved off it); every check runs again
        ok_, why_, n_gh = gradeh_bu_link(db, me, drow_saved, gh_ids, allow_from=src["id"])
        if not ok_:
            return None, why_ + " Nothing was moved."
    if merged:
        n0 = _bu_kpi_take_off(db, me, act, bg, co, db.execute("SELECT * FROM pm_bu_kpis WHERE id=?", (src["id"],)).fetchone(), people, touched=touched)
        if n0["held"] or n0["removed"] or n0["returned"]:
            raise _BuMoveError("taking %s off would have %s" % (sname, n0))
    total = db.execute("SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id=?", (act["id"], drow_saved["id"])).fetchone()[0]
    ids = ", ".join(sorted(movers))
    rest = ("%d stay on '%s'" % (len(left), sname)) if not merged else "'%s' taken off: nobody left on it" % sname
    _leader_log(db, me["id"], "pm_bu_kpi", ("%s, %s: %d %s moved from '%s' to %s'%s' (%s); Employee IDs: %s%s" % (
        act["name"], uname, len(movers), "person" if len(movers) == 1 else "people", sname,
        "a new variant, " if dest == "new" else "", dname, rest, ids,
        ("; %d Grade H line%s now follow it" % (n_gh, "" if n_gh == 1 else "s")) if n_gh else ""))[:3500], None)
    return {"moved": len(movers), "src": sname, "dest": dname, "new": dest == "new", "left": len(left), "merged": merged,
            "total": total, "dest_row": dict(drow_saved), "uname": uname, "gh": n_gh}, None


def _bu_move_flash(r, src_is_variant_of_dest=False):
    """What the move says on the page (canvas board 4)."""
    k = r["moved"]
    lines = "%d line%s" % (k, "" if k == 1 else "s")
    gh = r.get("gh") or 0
    if gh:   # Grade H lines moved with them (or alone): said first, the rest as before
        base = _bu_move_flash(dict(r, gh=0, moved=k), src_is_variant_of_dest) if k else (
            "%s made for %s." % (r["dest"], r["uname"]) if r["new"] else "")
        return (base + " " if base else "") + "%d Grade H line%s now follow%s %s and wait%s for its figure." % (
            gh, "" if gh == 1 else "s", "s" if gh == 1 else "", r["dest"], "s" if gh == 1 else "")
    if r["new"]:
        return "%s made for %s: %s moved from %s, which %d now carry." % (r["dest"], r["uname"], lines, r["src"], r["left"])
    if r["merged"]:
        return ("%s moved from %s to %s in %s, which %d now carry. %s has nobody left and is no longer a BU KPI of %s." % (
            lines, r["src"], r["dest"], r["uname"], r["total"], r["src"], r["uname"]))
    return "%s moved from %s %s %s in %s: %s now carries %d, %s keeps %d." % (
        lines, r["src"], "back to" if src_is_variant_of_dest else "to", r["dest"], r["uname"], r["dest"], r["total"],
        r["src"], r["left"])


def _bu_fmt(v):
    return "—" if v is None else "%g" % v


def _bu_scale_text(st, mech, unit, short=False):
    """A saved setup's target in words: (label, value) pairs for the tiles, and a short line for the rail."""
    u = (unit or "").strip()
    suf = (u if u == "%" else (" " + u if u else ""))
    if mech == "A":
        pairs = [("Rate %d" % i, _bu_fmt(st.get("rate%d" % i)) + (suf if st.get("rate%d" % i) is not None else ""))
                 for i in range(1, 6)]
        line = "Rates %s to %s%s" % (_bu_fmt(st.get("rate1")), _bu_fmt(st.get("rate5")), suf)
    else:
        last = ("Excellence", _bu_fmt(st.get("excellence")) + (suf if st.get("excellence") is not None else "")) if (
            st.get("excellence") is not None and st.get("multiple") is None) else (
            "Multiplier", _bu_fmt(st.get("multiple")))
        pairs = [("Threshold", _bu_fmt(st.get("threshold")) + (suf if st.get("threshold") is not None else "")),
                 ("Target", _bu_fmt(st.get("target")) + (suf if st.get("target") is not None else "")), last]
        line = "Target %s%s" % (_bu_fmt(st.get("target")), suf)
    return pairs, line


def _bu_rail(db, act, bg, co, saved, libs, adds, add_ids, facts, by_key, early, open_, cfg):
    """The left rail of BU KPI setup (2026-10-27): the unit's saved BU KPIs, those being set up in this visit (added,
    not saved), and the library's BU-level KPIs it could add. Each: lid (the library id the address keeps), name, the
    one-line summary. One read of the unit's facts (_bu_kpi_facts) feeds all three."""
    mech = cfg["mechanism"] if cfg else None
    out = {"saved": [], "new": [], "add": []}
    done = set()
    # 2026-11-04: the rail's "N carry it" matches the read view's Carried-by tile, which counts the Grade H lines that follow a setup too
    # (Grade H lines are never in f.n, so "keep their own" is untouched). ONE batched read for every saved setup, the same joins as
    # gradeh_bu_linked (gradeh_bu_linked_counts).
    n_gh = gradeh_bu_linked_counts(db, list(saved.values())) if gradeh_on() else {}
    # the guests from other units carry it too (2026-11-07): their lines are not the unit's facts, so counted here, one batched read
    n_guest = {i: len(v) for i, v in _bu_kpi_guest_lines(db, act, [x["id"] for x in saved.values()]).items()}
    for name, st in sorted(saved.items(), key=lambda kv: kv[0].lower()):
        k = _kpi_key(name)
        lib = by_key.get(k)
        f = facts.get(k) or {}
        n_bu = sum(1 for ln in (f.get("lines") or {}).values() if ln.get("bu_kpi_id") == st["id"])
        keep = (f.get("n") or 0) - n_bu
        n_bu += n_gh.get(st["id"], 0) + n_guest.get(st["id"], 0)
        _pairs, tl = _bu_scale_text(st, mech, st["unit"])
        summ = tl + " · %d carry it" % n_bu + (" · %d keep their own" % keep if keep > 0 else "")
        done.add(k)
        out["saved"].append({"lid": lib["id"] if lib else st["library_id"], "name": name, "state": "saved", "st": st,
                             "lib": lib, "summary": summ, "tag": "", "sub": False})
    # a variant sits right under its root when the root is saved in the unit too (2026-10-29, canvas board 4)
    # ... and the variants (1+) of a root that is not saved sit under a heading for it (2026-11-06): _bu_rail_layout, the Fill rail's too
    out["saved"], out["saved_view"] = _bu_rail_layout(out["saved"])
    for x in out["saved"]:
        if x["sub"]:
            x["summary"] = "Variant · " + x["summary"]
    for l in list(libs) + adds:
        k = _kpi_key(l["kpi_name"])
        if k in done:
            continue
        f = facts.get(k) or {}
        n = f.get("n") or 0
        who = ("%d carry it now" % n) if n else "Nobody here carries it now"
        if l["id"] in add_ids:
            out["new"].append({"lid": l["id"], "name": l["kpi_name"], "state": "new", "st": None, "lib": l,
                               "summary": who, "tag": "This unit" if l.get("pick") or (l["company"] or "*") == co else "Group-wide"})
        elif not l.get("pick"):
            dis = ""
            if not open_ or not cfg:
                dis = "BU KPI setup reads only now"
            elif not n and not early:
                dis = "Nobody in this unit carries it, and outside an Early Year a BU KPI goes only on those who carry it now"
            out["add"].append({"lid": l["id"], "name": l["kpi_name"], "summary": who, "disabled": dis,
                               "ids": add_ids + [l["id"]]})
    return out


def _bu_who(db, uid):
    """Who saved a setup, in words: 'the super admin' for the org-wide admin, else the admin's name."""
    if not uid:
        return "someone"
    u = db.execute("SELECT full_name, role, admin_bg FROM users WHERE id=?", (uid,)).fetchone()
    if not u:
        return "someone"
    return "the super admin" if (u["role"] == "admin" and not u["admin_bg"]) else (u["full_name"] or "someone")


def _bu_when(ts):
    """A stored UTC timestamp as '27 Oct 2026, 17:42' in MYT."""
    m = _myt(ts)
    try:
        return datetime.strptime(m, "%Y-%m-%d %H:%M").strftime("%-d %b %Y, %H:%M")
    except (ValueError, TypeError):
        return m or ""


def _bu_filled_map(db, me, period, bg, company=""):
    """What Group People has already entered, by (unit, KPI name folded) -> {"values": {value: lines}, "last": when,
    "n": lines}: final admin-filled results on this cycle's lines in the group (or one unit). A name with a saved setup
    counts only the lines linked to it, the selection _bu_fill_targets makes; a line linked to a setup of its own name counts for
    THAT setup's unit (2026-11-07: a guest's line counts once, with the unit whose KPI it is, not with the guest's own unit)."""
    rows = list(db.execute("SELECT id, company, kpi_name FROM pm_bu_kpis WHERE cycle_id=? AND business_group=?", (period["id"], bg)))
    setups = {(r["company"], _kpi_key(r["kpi_name"])): r["id"] for r in rows}
    by_id = {r["id"]: (r["company"], _kpi_key(r["kpi_name"])) for r in rows}
    bclause, bparams = bg_scope(me, "t.business_group")
    out = {}
    for r in db.execute(
            "SELECT t.company, t.kpi_name, t.bu_kpi_id, r.actual_value, r.submitted_at FROM pm_kpi_results r JOIN "
            "pm_kpi_targets t ON t.id=r.kpi_target_id WHERE t.cycle_id=? AND t.business_group=? AND r.admin_filled=1 "
            "AND COALESCE(r.draft,0)=0" + bclause, [period["id"], bg] + bparams):
        k = _kpi_key(r["kpi_name"])
        lk = by_id.get(r["bu_kpi_id"]) if r["bu_kpi_id"] else None
        if lk is not None and lk[1] == k:
            unit = lk[0]
        else:
            sid = setups.get((r["company"], k))
            if sid is not None and r["bu_kpi_id"] != sid:
                continue
            unit = r["company"]
        if company and unit != company:
            continue
        o = out.setdefault((unit, k), {"values": {}, "last": None, "n": 0})
        o["values"][r["actual_value"]] = o["values"].get(r["actual_value"], 0) + 1
        o["n"] += 1
        if not o["last"] or (r["submitted_at"] or "") > o["last"]:
            o["last"] = r["submitted_at"]
    return out


def _bu_kpi_read(db, act, bg, co, st, f, people, mech, cfg, sel, editable):
    """The read view of one saved BU KPI (2026-10-27): its head, the three tiles, who carries it and how, and whether
    its result has been entered. Everything from the setup row and the lines (one batched read, in `facts`)."""
    uname = display_company(bg, co) or co
    unit = kpi_unit_normalise(st["unit"]) or ""
    pairs, _ = _bu_scale_text(st, mech, unit)
    byeid = {ja_eid(p["employee_id"]): p for p in people}
    rows, n_bu = [], 0
    for eid, ln in sorted((f.get("lines") or {}).items(), key=lambda kv: (byeid.get(kv[0]) or {}).get("full_name") or ""):
        p = byeid.get(eid)
        if not p:
            continue
        mine = ln.get("bu_kpi_id") == st["id"]
        n_bu += 1 if mine else 0
        w, t = _bu_line_cells(ln, mech)
        g = grade_num(p["job_grade"])
        ts = t   # a 5-point line is five figures: the table shows its two ends, the whole row's title the five
        if mech == "A" and ln.get("rate1") is not None and ln.get("rate5") is not None:
            u_ = (ln.get("unit") or "").strip()
            ts = "%g to %g%s" % (ln["rate1"], ln["rate5"], u_ if u_ == "%" else (" " + u_ if u_ else ""))
        rows.append({"name": p["full_name"], "eid": eid, "g": g, "dept": p["department"] or "", "w": w, "t": t, "ts": ts,
                     "bu": mine, "guest": False, "unit": uname})
    # the guests from other units (2026-11-07, canvas B1): listed with everyone who carries it, marked with their unit
    n_guest = 0
    for ln, gp in _bu_kpi_guest_lines(db, act, [st["id"]]).get(st["id"], []):
        w, t = _bu_line_cells(ln, mech)
        ts = t
        if mech == "A" and ln.get("rate1") is not None and ln.get("rate5") is not None:
            u_ = (ln.get("unit") or "").strip()
            ts = "%g to %g%s" % (ln["rate1"], ln["rate5"], u_ if u_ == "%" else (" " + u_ if u_ else ""))
        rows.append({"name": gp["full_name"], "eid": ja_eid(gp["employee_id"]), "g": grade_num(gp["job_grade"]),
                     "dept": gp["department"] or "", "w": w, "t": t, "ts": ts, "bu": True, "guest": True, "unit": gp["unit"],
                     "uid": gp["id"]})
        n_bu += 1
        n_guest += 1
    # the lines still on earlier figures (2026-11-14): the same list Bring them onto this setup acts on, so the note's count and the
    # button agree; a quiet chip on each row, the count and (the super admin's) the button under the table
    held_ = {ja_eid(p_["employee_id"]) for p_, _t in _bu_kpi_held_lines(db, act, st, people)}
    for r_ in rows:
        r_["earlier"] = r_["eid"] in held_
    rows.sort(key=lambda r: (not r["bu"], r["guest"], r["name"].lower()))
    n_all = len(rows)
    keep = n_all - n_bu
    # the Grade H lines that follow this setup (2026-11-03): listed after the normal holders with the Grade H chip, counted in "Who carries it"
    # and the Carried-by tile; their own weight, no target of their own (they take the shared achievement %)
    gh = []
    if gradeh_on():
        for r_ in gradeh_bu_linked(db, st):
            gh.append({"name": r_["name"], "eid": r_["eid"], "g": r_["grade"] or "H", "dept": r_["dept"] or "",
                       "w": "%g%%" % r_["weight"],
                       "t": ("A Grade H line rated 1 to 5 takes the rating this result scores."
                             if r_["scale"] in GRADEH_BU_RATED_SCALES else "A Grade H line takes the shared achievement %. Its own scale rates it."),
                       "ts": "—", "bu": True, "gh": True, "stage": r_["stage"], "pct": r_["bu_pct"], "rating": r_["bu_rating"],
                       "filled": _gh_shared_filled(r_), "value": r_["bu_value"], "when": r_["filled_at"]})
    rows = rows + gh
    n_gh = len(gh)
    n_all += n_gh
    mode, d = st["carriers"], st["data"]
    nb = n_bu + n_gh   # the Carried-by number counts the Grade H lines that follow it too
    if mode == "holders":
        carried = ("%d" % nb, ("of the %d who carry it" % n_all) if keep else "who carry it")
    elif mode == "everyone":
        carried = ("%d" % nb, "carry it · everyone in %s taking part" % uname)
    elif mode == "departments":
        carried = ("%d" % nb, "carry it · departments: " + ", ".join(proper_name(x) for x in (d.get("departments") or [])))
    elif mode == "grade":
        carried = ("%d" % nb, "carry it · JG %s" % (
            "%s to %s" % (d["min"], d["max"]) if d.get("min") is not None and d.get("max") is not None
            else ("%s and above" % d["min"] if d.get("min") is not None else "%s and below" % d.get("max"))))
    else:
        carried = ("%d" % nb, "carry it · picked people")
    wm = st["weight_mode"]
    if wm == "own":
        lo, hi = f.get("wmin"), f.get("wmax")
        w = {"head": "Each keeps their own", "big": ("%g" % lo + ("" if lo == hi else " to %g" % hi) + "%") if lo is not None else "",
             "tail": "today" if lo is not None else ""}
    elif wm == "one":
        w = {"head": "One weight for all", "big": "%g%%" % st["weight"], "tail": ""}
    else:
        def bw(b):
            return ("JG %s to %s" % (b["min"], b["max"]) if b["min"] is not None and b["max"] is not None
                    else ("JG %s and above" % b["min"] if b["min"] is not None else "to JG %s" % b["max"])) + " " + "%g%%" % b["w"]
        w = {"head": "By grade", "big": "", "tail": " · ".join(bw(b) for b in st["bands"])}
    fm = _bu_filled_map(db, current_user(), act, bg, co).get((co, _kpi_key(st["kpi_name"])))
    filled = None
    if fm:
        vs = sorted(fm["values"])
        filled = {"value": ("%g" % vs[0] + (" %s" % unit if unit else "")) if len(vs) == 1 else "%d different values" % len(vs),
                  "when": _bu_when(fm["last"]), "n": fm["n"]}
    if filled is None:   # a variant held by Grade H lines alone has no normal result: its figure is the one Group People typed for them
        gv = sorted({x["value"] for x in gh if x["value"] is not None})
        if gv:
            filled = {"value": ("%g" % gv[0] + (" %s" % unit if unit else "")) if len(gv) == 1 else "%d different values" % len(gv),
                      "when": _bu_when(max(x["when"] or "" for x in gh)), "n": len(gh)}
    return {"unit": unit, "pairs": pairs, "rows": rows, "n_bu": n_bu, "n_all": n_all, "keep": keep, "carried": carried,
            "weight": w, "by": _bu_who(db, st["updated_by"]), "at": _bu_when(st["updated_at"]),
            "more": (st["method"] == "more"), "filled": filled, "editable": editable, "uname": uname, "n_gh": n_gh,
            "n_guest": n_guest, "gh_wait": sum(1 for x in gh if not x["filled"]), "n_earlier": len(held_)}


def _bu_card_lid(db, bg, co, row):
    """The library id a saved setup's card is addressed by (?kpi=): the unit's BU-level library row of its name, else its own."""
    lib = next((l for l in _bu_kpi_lib(db, bg, co) if _kpi_key(l["kpi_name"]) == _kpi_key(row["kpi_name"])), None)
    return lib["id"] if lib else row["library_id"]


def _bu_variant_panel(db, act, bg, co, st, saved, facts, people, mech, cfg, early, read):
    """What the Move-to-a-variant panel (canvas boards 1-2) shows for one saved BU KPI, for the super admin: its carriers
    (who, what they hold, whether the line is held), the siblings that can take people, and the checksum the form posts
    back. None when there is nothing to move to or from. One read of the carriers, one of who is held."""
    if st["carriers"] not in ("holders", "pick"):
        return None
    carriers = _bu_kpi_carriers(db, act, st, people)
    root = _bu_root(st["kpi_name"])
    cnt = Counter(ln.get("bu_kpi_id") for f in facts.values() for ln in (f.get("lines") or {}).values())
    sibs = []
    for r in _bu_siblings(list(saved.values()), st["kpi_name"]):
        if r["id"] == st["id"] or r["carriers"] not in ("holders", "pick"):
            continue
        sibs.append({"id": r["id"], "name": r["kpi_name"], "n": cnt.get(r["id"], 0), "wmode": r["weight_mode"],
                     "line": _bu_scale_text(r, mech, r["unit"])[1], "root": _kpi_key(r["kpi_name"]) == _kpi_key(root)})
    ghc = gradeh_bu_candidates(db, st) if gradeh_on() else []   # Grade H people of the unit with a line of this name (2026-11-03)
    if len(carriers) < 2 and not sibs and not any(c["ok"] for c in ghc):
        return None
    words = _bu_lines_lock_words(db, [ln["id"] for ln, _p in carriers.values()])
    plist = []
    for eid, (ln, p) in sorted(carriers.items(), key=lambda kv: (kv[1][1]["full_name"] or "").lower()):
        w, t = _bu_line_cells(ln, mech)
        g = grade_num(p["job_grade"])
        guest_ = (p["company"] or "") != (st["company"] or "")   # a guest from another unit (2026-11-07): named with their unit
        uname_ = (display_company(p["business_group"], p["company"]) or p["company"] or "") if guest_ else ""
        plist.append({"eid": eid, "name": p["full_name"], "w": w, "t": t, "lock": words.get(ln["id"]),
                      "guest": guest_, "unit": uname_,
                      "idl": eid + ((" · JG %s" % g) if g is not None else "") + (
                          (" · " + proper_name(p["department"])) if p["department"] else "") + ((" · " + uname_) if guest_ else ""),
                      "fig": [kpi_unit_normalise(ln.get("unit")) or ""] + [ln.get(c) for c in _BU_SCALE_COLS]})
    root_sib = next((x for x in sibs if x["root"]), None)
    wm = st["weight_mode"]
    # Grade H rows: those that can move (ok: a line on a % scale, following this setup or nothing), then those that cannot, greyed with why.
    # They are in the list and its "x of N" (N counts the ones that can move) but never in the normal carriers' figures.
    ghp = []
    for c in sorted(ghc, key=lambda c: (not c["ok"], (c["name"] or "").lower())):
        ln = c["line"]
        ghp.append({"gh": True, "key": "gh%d" % ln["id"] if ln else "gh-%d" % c["pid"], "lid": ln["id"] if ln else 0, "eid": c["eid"], "name": c["name"],
                    "ok": bool(c["ok"]), "why": c["why"], "here": c["linked"] == "this",
                    "idl": "%s · JG %s" % (c["eid"], c["grade"] or "H") + ((" · " + proper_name(c["dept"])) if c["dept"] else ""),
                    "w": ("%g%%" % ln["weight"]) if ln else "—", "t": "Grade H line" if (ln and c["ok"]) else "—", "fig": None,
                    "lock": None if c["ok"] else c["why"]})
    return {"name": st["kpi_name"], "root": root, "n": len(carriers), "sig": _bu_carrier_sig(carriers),
            "gh": ghp, "ngh": sum(1 for x in ghp if x["ok"]),
            "gh_sig": _bu_carrier_sig([str(r[0]) for r in db.execute("SELECT id FROM gradeh_kpi_lines WHERE bu_kpi_id=? ORDER BY id", (st["id"],))]) if ghp else "",
            "line": _bu_scale_text(st, mech, st["unit"])[1], "people": plist, "sibs": sibs, "early": early,
            "mech": mech, "more": st["method"] == "more", "excl": bool(cfg and cfg["variant"] == "excellence"),
            "wsub": ("each keeps their own weight" if wm == "own" else (
                "weight " + read["weight"]["head"].lower() + (" " + read["weight"]["big"] if read["weight"]["big"] else ""))),
            "back": root_sib["name"] if root_sib and _kpi_key(st["kpi_name"]) != _kpi_key(root) else None,
            "unit": kpi_unit_normalise(st["unit"]) or "", "bands": json.loads(st["bands_json"] or "[]") or BU_KPI_BANDS_DEFAULT,
            "weight": st["weight"], "wmode": wm, "uname": display_company(bg, co) or co, "cycle": act["name"],
            "roles": _bu_role_labels(db, bg, act["id"]),   # the role labels "A role" picks from (2026-11-07, canvas C1)
            "made": (json.loads(st["carriers_json"]).get("made") if st["carriers_json"] else None)}


@app.route("/admin/performance/bu-kpis", methods=["GET", "POST"])
@admin_required
def admin_bu_kpis():
    """Performance > BU KPI setup (2026-10-18, the libraries canvas board 4; Chris: "it should start with the BG filter
    row, then selection of the BU to assign the BU KPI ... show the KPI list from BU level KPI library, and the admin can
    select from there on the BU KPIs, and also the selection of who from the BU will carry them, and setting of the
    rating or target depending on the mechanism of the BG"). A business group, then a unit; tick its BU-level KPIs; for
    each, its one target on the group's scale, who carries it (everyone, departments, a grade range, picked people) and
    its weight (one for all, or by grade band: "show it as Everyone selected, then apply the job grade band"). Saving
    puts the line on each carrier's scorecard, moderated by their line manager. No reason is asked: set-up.

    Open in an Early Year, and in any other cycle until the HOD Department Review starts (Chris, 2026-11-03; it was
    until the results check-in started, 2026-10-23, canvas SZxWbP8ej2mvHgdijDq83J). A save changes every line in the
    unit, those with results too: they take the unit's target, a line a moderator had signed off goes back to its
    moderators, and one whose method or unit would change is held (_bu_kpi_apply), unless its only result is Group People's own
    Fill BU result: that line takes the unit and method too (2026-11-14, Chris: "edited BU KPI target must reach the Fill BU KPI
    page"). The super admin's `bring_held` action (2026-11-14, with the mandatory remark: SUPER_BAND_ENDPOINTS) brings the lines still
    on earlier figures onto the saved setup (`_bu_kpi_bring_held`): only lines already linked to it whose person it still covers, nobody
    added or taken off, nobody whose result is released or whom a calibrator holds; allowed while the page reads only, since it changes
    no setup. The super admin's `save_kpi_late` action (2026-11-14, Chris: "allow super admin to amend the BU KPI target and result, with a
    warning message that the Department Review has already begun. BU KPI can still be amended till the result release") amends ONE saved
    setup's target figures, unit and method after the Department Review started (`_bu_kpi_save_late`): only while the page reads only,
    only the super admin's, with the mandatory remark (SUPER_BAND_ENDPOINTS); carriers, weight, library link and every other KPI stay as
    saved, nobody is added or taken off, a released person is left as they are, a moderated line keeps its moderation. Outside an Early Year it goes only
    on those who carry the KPI now, each keeping their line's weight, since their KPIs already add up
    to 100%; their line is adopted, and taking the KPI off gives it back as it was. The super admin can add any of the
    group's library KPIs as this unit's BU KPI ("allow super admin to select which KPIs to be inserted as the BU KPIs
    from the KPI library list, and show how many people carrying this KPIs"), for this unit only: saving makes the
    unit's own BU-level library row (_bu_kpi_unit_row); nothing changes before the save."""
    db = get_db()
    me = current_user()
    act = active_cycle(db)
    early = bool(act and cycle_row_is_early_year(act))
    open_, note = _bu_kpi_state(db, act)
    sup = is_super(me)
    frows, fsel = admin_filter_rows(db, me, "admin_bu_kpis", params=("fbg", "fbu", "fdept"), levels=2, bg_all=False,
                                    people_sql="role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0 AND "
                                    + participant_sql(module='pm'))
    bg, co = fsel.get("bg") or "", fsel.get("bu") or ""
    back = lambda **kw: redirect(url_for("admin_bu_kpis", fbg=bg or None, fbu=co or None, **kw))   # noqa: E731
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?", (bg,)).fetchone() if bg else None
    if request.method == "POST":
        action = request.form.get("action")
        if action not in ("save", "save_kpi", "take_off", "move_variant", "bring_held", "save_kpi_late"):
            abort(400)
        if not (bg and co) or not can_access(me, bg, co):
            abort(403)
        if action in ("move_variant", "bring_held", "save_kpi_late") and not sup:   # the super admin's alone, whatever the page's access item says
            abort(403)
        # Bring them onto this setup changes no setup (it only brings lines already linked to what was saved), so it runs while the
        # page reads only too; it still needs an active cycle (2026-11-14). The late amendment is the page reading only: while it is
        # open the card's own Save is the way
        if open_ and action == "save_kpi_late":
            flash("BU KPI setup is open, so use the card's own Save. Nothing was saved.", "error")
            return back()
        if not open_ and not (action in ("bring_held", "save_kpi_late") and act):
            flash(note + " Nothing was saved.", "error")
            return back()
        if not cfg:
            flash("%s has no scoring set for its KPIs yet (Performance settings)." % display_bg(bg), "error")
            return back()
        people = _bu_unit_people(db, bg, co)
        depts = sorted({(p["department"] or "").strip() for p in people if (p["department"] or "").strip()})
        # one KPI at a time (2026-10-27, Chris: "per-KPI save"): the page posts the KPI it shows, and only that KPI's
        # setup and lines change. The same _bu_kpi_parse / _bu_kpi_apply as the whole-unit save below.
        keep_add = [x for x in request.form.getlist("add") if str(x).isdigit()]
        if action == "move_variant":
            sid = request.form.get("setup", "")
            row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=? AND cycle_id=? AND business_group=? AND company=?",
                             (int(sid) if sid.isdigit() else 0, act["id"], bg, co)).fetchone()
            if not row:
                abort(400)
            slid = _bu_card_lid(db, bg, co, row)
            touched = {}   # whose lines the move changed: their records are rebuilt once, before the commit (2026-11-08)
            try:
                res, why = _bu_kpi_move(db, me, act, bg, co, row, (request.form.get("dest") or "").strip(),
                                        request.form.getlist("who"), request.form, people, cfg, early,
                                        gh_ids=request.form.getlist("ghwho"), touched=touched)
            except GradehRefusal as e:
                db.rollback()
                res, why = None, "%s Nothing was moved." % e
            except _BuMoveError:
                db.rollback()
                app.logger.exception("BU KPI move undone")
                res, why = None, "That move did not come out as planned, so nothing was changed."
            if why:
                db.rollback()
                flash(why, "error")
                return back(kpi=slid, panel="bkvar")
            left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
            db.commit()
            flash((_bu_move_flash(res, _kpi_key(res["dest"]) == _kpi_key(_bu_root(res["src"]))) + " " + _records_left_note(left)).strip(), "ok")
            return back(kpi=_bu_card_lid(db, bg, co, res["dest_row"]))
        if action == "save_kpi_late":
            sid = request.form.get("setup", "")
            row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=? AND cycle_id=? AND business_group=? AND company=?",
                             (int(sid) if sid.isdigit() else 0, act["id"], bg, co)).fetchone()
            if not row:
                abort(400)
            slid = _bu_card_lid(db, bg, co, row)
            vals, why = _bu_kpi_late_parse(request.form, row, cfg)
            if why:
                flash(why + " Nothing was saved.", "error")
                return back(kpi=slid, edit=1)
            touched = {}   # whose lines took the new target: their rating records are rebuilt once, before the commit
            try:
                row, n, reach = _bu_kpi_save_late(db, me, act, row, vals, people, touched=touched)
            except GradehRefusal as e:
                db.rollback()
                flash("%s Nothing was saved." % e, "error")
                return back(kpi=slid, edit=1)
            left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
            db.commit()
            flash("%s amended for %s: %s%s" % (row["kpi_name"], display_company(bg, co) or co, _bu_late_words(n, reach),
                                               (" " + _records_left_note(left)) if left else ""), "ok")
            return back(kpi=slid)
        if action == "bring_held":
            sid = request.form.get("setup", "")
            row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=? AND cycle_id=? AND business_group=? AND company=?",
                             (int(sid) if sid.isdigit() else 0, act["id"], bg, co)).fetchone()
            if not row:
                abort(400)
            touched = {}   # whose lines took the saved figures: their records are rebuilt once, before the commit
            try:
                n, skipped, found = _bu_kpi_bring_held(db, me, act, row, people, touched=touched)
                if n["updated"]:   # a changed target scores Group People's filled figure again for the Grade H lines that follow it
                    ok_, why_, _c = gradeh_bu_refresh(db, me, row)
                    if not ok_:
                        raise GradehRefusal(why_)
            except GradehRefusal as e:
                db.rollback()
                flash("%s Nothing was changed." % e, "error")
                return back(kpi=_bu_card_lid(db, bg, co, row))
            _leader_log(db, me["id"], "pm_bu_kpi", "%s, %s: '%s' held lines brought onto the saved setup (%d of %d updated%s%s%s)" % (
                act["name"], display_company(bg, co) or co, row["kpi_name"], n["updated"], found, _bu_apply_trail(n),
                (", %d left: result released" % skipped["released"]) if skipped["released"] else "",
                (", %d left: calibrated" % skipped["calibrated"]) if skipped["calibrated"] else ""), None)
            left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
            db.commit()
            _redo_flush(db, me["id"])
            flash("%s for %s: %s%s" % (row["kpi_name"], display_company(bg, co) or co, _bu_held_words(n, skipped, found),
                                       (" " + _records_left_note(left)) if left else ""), "ok")
            return back(kpi=_bu_card_lid(db, bg, co, row))
        if action == "take_off":
            sid = request.form.get("setup", "")
            row = db.execute("SELECT * FROM pm_bu_kpis WHERE id=? AND cycle_id=? AND business_group=? AND company=?",
                             (int(sid) if sid.isdigit() else 0, act["id"], bg, co)).fetchone()
            if not row:
                abort(400)
            touched = {}   # whose lines came off or went back: their records are rebuilt once, before the commit (2026-11-08)
            try:
                n = _bu_kpi_take_off(db, me, act, bg, co, row, people, touched=touched)
            except GradehRefusal as e:   # a Grade H line that cannot let go (an appraisal already submitted with no figure of its own)
                db.rollback()
                flash("%s Nothing was taken off." % e, "error")
                return back(kpi=row["library_id"], add=keep_add or None)
            left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
            db.commit()
            flash("%s is no longer a BU KPI of %s: %d line%s taken off%s%s%s." % (
                row["kpi_name"], display_company(bg, co) or co, n["removed"], "" if n["removed"] == 1 else "s",
                (", %d given back as they were" % n["returned"]) if n["returned"] else "",
                (", %d Grade H line%s back to %s own" % (n["gh_unlinked"], " goes" if n["gh_unlinked"] == 1 else "s go",
                                                         "its" if n["gh_unlinked"] == 1 else "their")) if n.get("gh_unlinked") else "",
                (", %d left as they were: someone has acted on them (the KPI stays saved)" % n["held"])
                if n["held"] else "") + (" " + _records_left_note(left) if left else ""), "ok")
            return back(kpi=(row["library_id"] if n["held"] else None), add=keep_add or None)
        if action == "save_kpi":
            libs1 = {r["id"]: r for r in _bu_kpi_lib(db, bg, co)}
            picks1 = _bu_kpi_pickable(db, bg, co) if sup else {}
            facts1, _g1 = _bu_kpi_facts(db, act, bg, co)
            lid = int(request.form.get("kpi")) if str(request.form.get("kpi", "")).isdigit() else 0
            lib = libs1.get(lid) or picks1.get(lid)
            if not lib:
                abort(403 if lid in _bu_kpi_pickable(db, bg, co) else 400)   # a library pick is the super admin's
            form = request.form if sup or not early else _bu_weight_kept(db, act, bg, co, lib, request.form)
            st, why = _bu_kpi_parse(db, form, lib, cfg, people, depts, early=early,
                                    holders=(facts1.get(_kpi_key(lib["kpi_name"])) or {}).get("eids"),
                                    add_ok=sup, totals=_bu_kpi_totals(db, act, people) if sup and not early else None)
            if why:
                flash(why + " Nothing was saved.", "error")
                return back(kpi=lid, edit=1, add=keep_add or None)
            st["pick"] = lid not in libs1
            gh_msg = ""
            touched = {}   # whose lines the save changed (added, taken off, re-weighted, re-targeted): rebuilt once, before the commit (2026-11-08)
            try:
                srow, n = _bu_kpi_save_one(db, me, act, bg, co, lib, st, people, touched=touched)
                gdone, gwhy = _bu_kpi_add_guests(db, me, act, srow, _bu_kpi_guest_posts(request.form, lid), touched=touched)   # same transaction (2026-11-07)
                if gwhy:
                    db.rollback()
                    flash("%s Nothing was saved." % gwhy, "error")
                    return back(kpi=lid, edit=1, add=keep_add or None)
                if gdone:
                    gh_msg += " %d added from another unit: %s." % (len(gdone), ", ".join(
                        "%s (%s) at %g%%" % (nm, un, w_) for _e, nm, un, w_ in gdone))
                if sup and gradeh_on() and request.form.get("k%d_ghset" % lid):   # the Grade H picklist was on the card (absent is not empty)
                    ok_, why_, nl, nu = _gh_bu_set_links(db, me, srow, request.form.getlist("k%d_ghline" % lid))
                    if not ok_:
                        raise GradehRefusal(why_)
                    gh_msg += (" %d Grade H line%s now follow it." % (nl, "" if nl == 1 else "s") if nl else "") + (
                        " %d Grade H line%s back to their own." % (nu, "" if nu == 1 else "s") if nu else "")
            except GradehRefusal as e:
                db.rollback()
                flash("%s Nothing was saved." % e, "error")
                return back(kpi=lid, edit=1, add=keep_add or None)
            left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
            db.commit()
            _redo_flush(db, me["id"])   # lines added for people who already started: one email each (2026-11-06)
            flash("%s saved for %s: %s%s%s" % (lib["kpi_name"], display_company(bg, co) or co, _bu_save_words(n), gh_msg,
                                               (" " + _records_left_note(left)) if left else ""), "ok")
            return back(kpi=lid, add=[x for x in keep_add if int(x) != lid] or None)
        libs = {r["id"]: r for r in _bu_kpi_lib(db, bg, co)}
        picks = _bu_kpi_pickable(db, bg, co) if sup else {}
        facts, _grp = _bu_kpi_facts(db, act, bg, co)
        picked = []
        totals_ = _bu_kpi_totals(db, act, people) if sup and not early else None
        for x in request.form.getlist("kpi"):
            lid = int(x) if str(x).isdigit() else 0
            lib = libs.get(lid) or picks.get(lid)
            if not lib:
                abort(403 if lid in _bu_kpi_pickable(db, bg, co) else 400)   # a library pick is the super admin's
            if _bu_kpi_guest_posts(request.form, lid):   # a guest is added from one card's own save, never in the whole-unit save
                flash("'%s': adding someone from another unit is done on that KPI's own card. Nothing was saved." % lib["kpi_name"], "error")
                return back()
            form = request.form if sup or not early else _bu_weight_kept(db, act, bg, co, lib, request.form)
            st, why = _bu_kpi_parse(db, form, lib, cfg, people, depts, early=early,
                                    holders=(facts.get(_kpi_key(lib["kpi_name"])) or {}).get("eids"),
                                    add_ok=sup, totals=totals_)
            if why:
                flash(why + " Nothing was saved.", "error")
                return back()
            if totals_ is not None:   # a person added on two KPIs in one post: the second is checked against the first's weight too
                for e_, w_ in ((json.loads(st["carriers_json"] or "{}") or {}).get("added_w") or {}).items():
                    n0_, t0_ = totals_.get(e_, (0, 0.0))
                    totals_[e_] = (n0_ + 1, t0_ + w_)
            st["pick"] = lid not in libs
            picked.append((st, lib))
        saved = {r["kpi_name"]: dict(r) for r in db.execute(
            "SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=?", (act["id"], bg, co))}
        words = []
        touched = {}   # whose lines the save changed: rebuilt once each, before the commit (2026-11-08)
        try:
            for st, lib in picked:
                saved.pop(st["kpi_name"], None)
                words.append((st["kpi_name"], _bu_kpi_save_one(db, me, act, bg, co, lib, st, people, touched=touched)[1]))
            for name, row in saved.items():   # unticked: off every scorecard it was put on, adopted lines given back
                words.append((name, _bu_kpi_take_off(db, me, act, bg, co, row, people, touched=touched)))
        except GradehRefusal as e:
            db.rollback()
            flash("%s Nothing was saved." % e, "error")
            return back()
        left = _bu_follow_flush(db, me, act["id"], touched, "bu_kpi_change")[2]
        db.commit()
        _redo_flush(db, me["id"])
        tot = {k: sum(n[k] for _w, n in words) for k in ("added", "updated", "removed", "returned", "held",
                                                          "with_results", "remoderated", "differs", "released")}
        flash("%s's BU KPIs saved: %s%s" % (display_company(bg, co) or co, _bu_save_words(tot),
                                           (" " + _records_left_note(left)) if left else ""), "ok")
        return back()
    # the super admin's late amendment (2026-11-14): the page reads only because the Department Review started, in an ordinary cycle
    late = bool(sup and act and not early and not open_ and cfg)
    # the top-of-page note (2026-11-14, Chris: "the default display page still shows the wrong line"): the super admin reads the late
    # warning on the default page too (no group picked, so no cfg); `late` stays the unit's amend gate
    late_note = late or bool(sup and act and not early and not open_ and not bg)
    ctx = {"frows": frows, "bg": bg, "co": co, "act": act, "early": early, "cfg": cfg, "open_": open_, "note": note,
           "sup": sup, "late": late, "late_note": late_note, "late_warning": _bu_late_warning(db, act) if late_note else "", "late_card": None}
    if bg and co:
        people = _bu_unit_people(db, bg, co)
        dn = {}
        for p in people:
            d = (p["department"] or "").strip()
            if d:
                dn[d] = dn.get(d, 0) + 1
        libs = _bu_kpi_lib(db, bg, co)
        facts, grp = _bu_kpi_facts(db, act, bg, co)
        pickable = _bu_kpi_pickable(db, bg, co) if sup and open_ else {}
        have = {_kpi_key(l["kpi_name"]) for l in libs}
        add_ids = [int(x) for x in request.args.getlist("add") if str(x).isdigit()]
        adds = []   # library KPIs the super admin picked on the panel: being set up until that KPI is saved
        for x in add_ids:
            r = pickable.get(x)
            if r and _kpi_key(r["kpi_name"]) not in have:
                have.add(_kpi_key(r["kpi_name"]))
                adds.append(dict(r, pick=True))
        saved = {r["kpi_name"]: dict(r) for r in db.execute(
            "SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=?",
            (act["id"] if act else 0, bg, co))}
        for st in saved.values():
            st["data"] = json.loads(st["carriers_json"]) if st["carriers_json"] else {}
            st["bands"] = json.loads(st["bands_json"]) if st["bands_json"] else []
        by_key = {_kpi_key(l["kpi_name"]): l for l in list(libs) + adds}
        mech = cfg["mechanism"] if cfg else None
        rail = _bu_rail(db, act, bg, co, saved, libs, adds, add_ids, facts, by_key, early, open_, cfg)
        want = int(request.args["kpi"]) if str(request.args.get("kpi", "")).isdigit() else None
        pool = rail["saved"] + rail["new"]
        sel = next((x for x in pool if x["lid"] == want), None) or (pool[0] if pool else None)
        mode, card, read, var, kick = None, None, None, None, None
        if sel:
            editable = bool(open_ and cfg and sel["lib"])
            mode = "new" if sel["state"] == "new" else (
                "edit" if request.args.get("edit") and editable else "read")
            if mode == "read" and late and request.args.get("edit") and sel["state"] == "saved" and sel["st"]:
                mode = "late"   # the super admin's amendment: figures, unit and method of a saved setup only
            l, st = sel["lib"], sel["st"]
            f = facts.get(_kpi_key(sel["name"])) or {}
            if mode in ("edit", "new"):
                # A new card starts on the target most of its carriers hold (Chris, 2026-10-29), with that target's unit; a
                # tie has no such target, so the boxes stay empty; nobody carrying it, blank boxes.
                if st:
                    pre, unit_ = st, (st["unit"] or l["unit"])
                elif f.get("major"):
                    pre, unit_ = f["major"], f["major"]["unit"]
                elif f.get("n"):
                    pre, unit_ = dict.fromkeys(_BU_SCALE_COLS), ""
                else:   # nobody carries it: blank boxes (the library holds no numbers, Chris 2026-11-02)
                    pre, unit_ = dict.fromkeys(_BU_SCALE_COLS), l["unit"]
                card = {"l": l, "st": st, "f": f, "pre": pre, "unit": unit_, "pick": bool(l.get("pick")),
                        "unit_only": bool(l.get("pick")) or (l["company"] or "*") == co,
                        "holders": sorted(f.get("eids") or []),
                        "hcells": {e: _bu_line_cells(ln, mech) for e, ln in (f.get("lines") or {}).items()},
                        "depts": sorted(f.get("depts") or []),
                        # the unit's Grade H people with a line of this name, for the super admin's picklist (2026-11-03): the ones that can
                        # follow first, the rest greyed with why
                        "gh": (sorted(gradeh_bu_candidates(db, st or {"id": None, "cycle_id": act["id"], "business_group": bg, "company": co,
                                                                      "kpi_name": l["kpi_name"]}),
                                      key=lambda c_: (not c_["ok"], (c_["name"] or "").lower()))
                               if (sup and open_ and gradeh_on()) else []),
                        # the super admin, outside an Early Year (2026-11-06): the unit's people taking part who do not carry
                        # it and whose KPIs do not add up to 100% yet, with what they hold today; ONE batched read
                        "add": (_bu_kpi_add_pool(db, act, people, f.get("eids") or ())
                                if (sup and open_ and cfg and not early) else None),
                        # the super admin's "From another unit in <group>" part (2026-11-07, canvas B2): only on a SAVED setup that goes on
                        # those who carry it now at their own weight (`_bu_add_cycle_refusal`'s rule), outside an Early Year; the guests
                        # it already has stay (listed read-only, taken off on their page)
                        "gadd": ({"sid": st["id"], "group": display_bg(bg), "unit": display_company(bg, co) or co,
                                  "n": len(_bu_kpi_guest_lines(db, act, [st["id"]]).get(st["id"], []))}
                                 if (sup and open_ and cfg and not early and st and not _bu_add_cycle_refusal(db, me, act, st)) else None)}
            else:
                read = _bu_kpi_read(db, act, bg, co, st, f, people, mech, cfg, sel, editable and True)
                if mode == "late" and st:   # the amend card: what the save reaches, ONE batched read
                    ctx["late_card"] = {"reach": _bu_late_reach(db, act, st, people), "st": st, "unit": kpi_unit_normalise(st["unit"]) or "",
                                        "more": st["method"] == "more", "excl": bool(cfg and cfg["variant"] == "excellence")}
                rk_ = _kpi_key(_bu_root(sel["name"]))
                if rk_ != _kpi_key(sel["name"]):   # a variant says whose (2026-10-29, canvas board 4)
                    kick = next((n_ for n_ in saved if _kpi_key(n_) == rk_), None)
                if sup and editable:   # the super admin's Move some to a variant (admin_bu_kpis, move_variant)
                    var = _bu_variant_panel(db, act, bg, co, st, saved, facts, people, mech, cfg, early, read)
        lib_rows = []
        for r in pickable.values():
            k = _kpi_key(r["kpi_name"])
            f = facts.get(k) or {}
            fam, _s, grp_ = (r["category"] or "").partition(" · ")
            lib_rows.append({"id": r["id"], "name": r["kpi_name"], "family": fam or "Not grouped", "group": grp_,
                             "unit_n": f.get("n", 0), "bg_n": grp.get(k, 0), "depts": sorted(f.get("depts") or []),
                             "n_scales": len(f.get("scales") or ()), "wmin": f.get("wmin"), "wmax": f.get("wmax"),
                             "unit": r["unit"] or "", "more": r["method"] == "more", "added": k in have})
        lib_rows.sort(key=lambda x: (-x["unit_n"], -x["bg_n"], x["name"].lower()))
        fams = {}
        for x in lib_rows:
            fams[x["family"]] = fams.get(x["family"], 0) + 1
        ctx.update({"people": people, "depts": sorted(dn.items()), "libs": libs, "rail": rail, "sel": sel,
                    "mode": mode, "card": card, "read": read, "mech": mech, "var": var, "kick": kick,
                    "bands_default": BU_KPI_BANDS_DEFAULT, "lib_rows": lib_rows,
                    "fams": sorted(fams.items(), key=lambda x: (-x[1], x[0])), "lib_total": len(pickable),
                    "add_ids": add_ids,
                    "pick": [{"eid": ja_eid(p["employee_id"]), "name": p["full_name"], "dept": p["department"] or "",
                              "g": grade_num(p["job_grade"])} for p in people]})
    return render_template("admin_bu_kpis.html", **ctx)


def _bu_fill_targets(db, me, period, business_group, company, kpi_name):
    """The KPI lines Fill BU result fills for `kpi_name` in a unit (company) or the whole business group in scope: the one
    selection both the preview and the apply use. By the KPI's name, except where the unit has a saved BU KPI setup for
    that name this cycle (pm_bu_kpis): then only the lines linked to it (pm_kpi_targets.bu_kpi_id = the setup's id), so
    a holder left out of "Those who carry it now" keeps their own line and result. Per company: a company with no setup
    for the name keeps the name rule. A line linked to a setup of this name belongs to THAT setup's unit whatever company the person
    works in (2026-11-07: a guest from another unit of the group), so it is filled with the unit it follows, once, and never by its own
    unit's name rule; the name rule also skips a line linked to another unit's setup. Each target carries "_fill_unit", the unit whose
    fill reaches it (the apply checks the admin's access to that unit)."""
    bclause, bparams = bg_scope(me, "t.business_group")
    targets = [dict(t) for t in db.execute(
        f"SELECT t.* FROM pm_kpi_targets t WHERE t.cycle_id=? AND t.business_group=? "
        f"AND t.kpi_name=?{bclause} ORDER BY t.subject_id",
        [period["id"], business_group, kpi_name] + bparams).fetchall()]
    key = " ".join((kpi_name or "").lower().split())
    allst = {r["id"]: (r["company"], " ".join((r["kpi_name"] or "").lower().split())) for r in db.execute(
        "SELECT id, company, kpi_name FROM pm_bu_kpis WHERE cycle_id=? AND business_group=?", (period["id"], business_group))}
    setups = {c: i for i, (c, k) in allst.items() if k == key}
    out = []
    for t in targets:
        lk = allst.get(t.get("bu_kpi_id")) if t.get("bu_kpi_id") else None
        if lk is not None and lk[1] == key:
            unit = lk[0]   # linked to a setup of this name: its unit's, a guest's line included
        elif lk is not None and lk[0] != t["company"]:
            continue       # a guest's line of another unit's setup (another name): never this unit's name rule
        elif t["company"] in setups:
            continue       # their unit has a setup of this name and the line is not linked to it: their own
        else:
            unit = t["company"]
        if company and unit != company:
            continue
        t["_fill_unit"] = unit
        out.append(t)
    return out


def _bu_fill_score(cfg, t, value):
    """One KPI line's score for a result, the app's own scoring (pm_score_kpi_line): None with no value or no scoring set."""
    if value is None or not (cfg or _row_get(t, "rating_line")):
        return None
    return pm_score_kpi_line(cfg, t, value)


def _bu_band_text(rep, rating, unit):
    """Where a 5-point rating falls on a line's own Rate 1-5 (pm_rating_mechanism_a's floors), in words: '60 to under 65'."""
    r = [rep.get("rate%d" % i) for i in range(1, 6)]
    if any(v is None for v in r):
        return ""
    u = (unit or "").strip()
    sf = (u if u == "%" else (" " + u if u else ""))
    g = lambda v: "%g%s" % (v, sf)   # noqa: E731
    if rep["method"] == "more":
        return ("under " + g(r[1]) if rating == 1 else (g(r[4]) + " and above" if rating == 5
                                                         else "%s to under %s" % (g(r[rating - 1]), g(r[rating]))))
    return ("over " + g(r[1]) if rating == 1 else (g(r[4]) + " or less" if rating == 5
                                                   else "over %s up to %s" % (g(r[rating]), g(r[rating - 1]))))


def _bu_refill_candidate(t):
    """True when the ONLY reason this line reads locked is Group People's own earlier fill: a visible admin-filled result
    and no approver has acted (a line whose chain finished, or that holds any approval, is locked for another reason)."""
    return bool(t["locked"] and t.get("result") and t["result"]["admin_filled"] and not t.get("approvals"))


def _bu_moderated(t):
    """True when an approver (the line manager, or any later step) has acted on this line and Group People has not filled it:
    a partly moderated line, or one whose chain is complete. Fill BU result replaces such a line's moderation with the
    unit's figure (Chris, 2026-11-13: "all BU KPIs follow the number filled by Group People"), unless a calibrator
    has acted on the person or the result is released (_pm_calibration_hold)."""
    return bool(t.get("approvals")) and not (t.get("result") and t["result"]["admin_filled"])


def _pm_release_hold(db, cycle_id, ids):
    """The ids, among `ids` (user ids), whose PM result is released for the cycle (a release to the person, or to their leaders as pm or talent):
    ONE batched read. The release half of `_pm_calibration_hold`, which the super admin's Fill BU result reads alone (`released_only`)."""
    if not ids or not cycle_id:
        return set()
    ph = ",".join("?" * len(ids))
    return {r[0] for r in db.execute(
        "SELECT DISTINCT subject_id FROM result_releases WHERE cycle_id=? AND kind='pm' AND subject_id IN (%s) UNION SELECT DISTINCT "
        "subject_id FROM leader_releases WHERE cycle_id=? AND kind IN ('pm','talent') AND subject_id IN (%s)" % (ph, ph),
        [cycle_id] + list(ids) + [cycle_id] + list(ids))}


def _pm_calibration_hold(db, cycle_id, subjects, released_only=False):
    """{subject_id: why} for the people, among `subjects` (users rows), whose PM band a calibrator has acted on or whose
    result is released for the cycle: the one shared answer Fill BU result's calc and apply use to decide whether a
    Group People figure may still be corrected (Chris, 2026-10-27: "until the line is calibrated or results are
    released"). Conservative: any of
      * a row in pm_calibration_adjustments for them at any tier, locked or not (a HOD / BU CEO / BG CEO / Group Chief /
        super admin move, or a Talent Box pin),
      * a Group Chief lock on them (pm_group_locks),
      * a LOCKED calibration session of any tier over their own scope: their HOD's (hod_id), their BU calibrator's or
        unit's (bu_scope_keys), their business group's, their calibration group's; or their business unit's Talent Box
        lock (talent_box_bu_locks),
      * their result released to leaders or to them (result_releases / leader_releases, pm or talent).
    A tier locked with no row for them still holds them: the lock decided their band as it stood. One batched read per
    source, never one per person.
    `released_only=True` (2026-11-14, the super admin's Fill BU result and late BU KPI amendment: "until results are released"): only the
    last source, the release, is read, so the answer holds nobody a calibrator acted on."""
    out = {}
    ids = [s_["id"] for s_ in subjects]
    if not ids or not cycle_id:
        return out
    ph = ",".join("?" * len(ids))
    if released_only:
        return {i: "their result is released" for i in _pm_release_hold(db, cycle_id, ids)}
    for r in db.execute("SELECT DISTINCT ca.subject_id FROM pm_calibration_adjustments ca JOIN pm_calibration_sessions cs "
                        "ON cs.id=ca.session_id WHERE cs.cycle_id=? AND ca.subject_id IN (%s)" % ph, [cycle_id] + ids):
        out.setdefault(r[0], "a calibrator has moved or pinned their band")
    for r in db.execute("SELECT DISTINCT subject_id FROM pm_group_locks WHERE cycle_id=? AND subject_id IN (%s)" % ph,
                        [cycle_id] + ids):
        out.setdefault(r[0], "a Group Chief has locked their band")
    if chair_on():   # his locked band holds them too (worded neutrally: nothing here says whose it is)
        for r in db.execute("SELECT DISTINCT subject_id FROM chair_locks WHERE cycle_id=? AND subject_id IN (%s)" % ph,
                            [cycle_id] + ids):
            out.setdefault(r[0], "their band is locked at group level")
    for i in _pm_release_hold(db, cycle_id, ids):
        out.setdefault(i, "their result is released")
    locked = {(r["tier"], r["scope_key"]) for r in db.execute(
        "SELECT tier, scope_key FROM pm_calibration_sessions WHERE cycle_id=? AND locked_at IS NOT NULL", (cycle_id,))}
    bu_locks = {(r["business_group"], r["company"]) for r in db.execute(
        "SELECT business_group, company FROM talent_box_bu_locks WHERE period_id=?", (cycle_id,))}
    if locked or bu_locks:
        for u in subjects:
            if u["id"] in out:
                continue
            gid = calibration_group_of(db, u["id"])
            hit = ((u["hod_id"] and ("hod", str(u["hod_id"])) in locked)
                   or any(("buceo", k) in locked for k in bu_scope_keys(db, u))
                   or ("bgceo", u["business_group"]) in locked
                   or (gid and ("group", str(gid)) in locked)
                   or (u["business_group"], u["company"] or "") in bu_locks)
            if hit:
                out[u["id"]] = "a calibration tier has locked over them"
    return out


def _bu_fill_buckets(db, me, period, business_group, company, kpi_name, actual_value):
    """The one selection and sorting Fill BU result's calc and apply share (Chris, 2026-10-27: preview and apply use the
    same selection): the lines _bu_fill_targets picks, each with its score for `actual_value` (None = none typed yet),
    sorted into buckets by what has happened to them (2026-11-13: every BU KPI follows Group People's figure, so a line an
    approver has acted on is filled too; only a calibrated or released person's line is left):
      will_fill       nothing on the line yet
      will_overwrite  the person's own figure, or (the super admin) Group People's earlier fill: replaced
      has_approval    the line manager's (or a later approver's) moderation, partly or fully: replaced, its approval rows archived
      locked          left as it is: a calibrator has acted on the person or their result is released (row["held"] says why), or a
                      line Group People already filled that this viewer may not change
    (targets, buckets, subjects, cfg)."""
    targets = _bu_fill_targets(db, me, period, business_group, company, kpi_name)
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?", (business_group,)).fetchone()
    buckets = {"will_fill": [], "will_overwrite": [], "has_approval": [], "locked": []}
    subjects = {}
    if not targets:
        return targets, buckets, subjects, cfg
    attach_pm_chains(db, targets)
    ph = ",".join("?" * len(targets))
    subjects = {r["id"]: r for r in db.execute(
        f"SELECT * FROM users WHERE id IN ({ph})", [t["subject_id"] for t in targets]).fetchall()}
    # a line carrying only Group People's own earlier fill can be refilled by the super admin, and a line an approver has acted
    # on is replaced by anyone who fills, both until a calibrator has acted on the person or the result is released
    # (Chris, 2026-10-27, 2026-11-13); _bu_refill_candidate / _bu_moderated say which lines, ONE batched read says which of
    # those are held
    # (2026-11-05: the hold is read for every viewer, so the filled card can say "Calibrated, stays as filled"; only the super admin's
    # decision below depends on it, as before)
    cands = [t for t in targets if _bu_refill_candidate(t) or _bu_moderated(t)]
    cand_subj = [subjects[t["subject_id"]] for t in cands]
    # the super admin (2026-11-14, Chris: "BU KPI can still be amended till the result release"): a line is left only once the person's
    # result is released; a person a calibrator has acted on is filled like anyone else, their band staying as the calibrator set it (it is
    # computed on read), and the row says so (row["calibrated"], the page's chip and the apply's remark). Everyone else: held on either.
    sup_ = is_super(me)
    cal = _pm_calibration_hold(db, period["id"], cand_subj) if cands else {}
    held = _pm_calibration_hold(db, period["id"], cand_subj, released_only=True) if (cands and sup_) else cal
    cand_ids = {t["id"] for t in cands}
    for t in targets:
        row = {"target": t, "subject": subjects[t["subject_id"]], "score": _bu_fill_score(cfg, t, actual_value),
               "held": held.get(t["subject_id"]) if t["id"] in cand_ids else None, "own_score": None,
               "calibrated": bool(sup_ and t["id"] in cand_ids and t["subject_id"] in cal and t["subject_id"] not in held),
               "rel_view": sup_}
        if t.get("result") and t["result"]["admin_filled"]:   # the line scored on its own filled figure (the filled card's Rating column)
            row["own_score"] = _bu_fill_score(cfg, t, t["result"]["actual_value"])
        if _bu_refill_candidate(t) and is_super(me) and not row["held"]:
            row["previous_value"] = t["result"]["actual_value"]
            row["previous_note"] = t["result"]["note"]
            row["refill"] = True
            buckets["will_overwrite"].append(row)
        elif _bu_moderated(t) and not row["held"]:
            buckets["has_approval"].append(row)
        elif t["locked"] or _bu_moderated(t):   # held (a calibrated person's moderated line, too), or Group People's fill this viewer cannot change
            buckets["locked"].append(row)
        elif t["result"]:
            row["previous_value"] = t["result"]["actual_value"]
            row["previous_note"] = t["result"]["note"]
            buckets["will_overwrite"].append(row)
        else:
            buckets["will_fill"].append(row)
    return targets, buckets, subjects, cfg


def _bu_fill_eligible(buckets):
    """The rows a save writes and the page counts as "N to fill": one list for the preview, the button and the apply, so they
    cannot differ (Chris, 2026-10-27)."""
    return buckets["will_fill"] + buckets["will_overwrite"] + buckets["has_approval"]


GRADEH_BU_STAGE_WORDS = {"before": "Not started", "submitted": "Line manager submitted", "acknowledged": "Acknowledged · their result updates"}


def _bu_fill_gh(db, me, period, business_group, company, kpi_name, value=None):
    """The Grade H lines Fill BU result also fills for `kpi_name` (2026-11-03): per saved setup of that name in scope (a unit, or the whole
    group), the lines that follow it, and the result the typed `value` scores on that setup (None with no value or when the setup gives
    none: `err` says why): the achievement % for lines on a % scale, the rating for lines rated 1-5 (2026-11-06; gradeh_bu_result_of, once
    per setup for the scale of its lines). [{setup, lines, kind 'pct' | 'rating' | None, res (the % or the rating), pct (res on a
    % kind, else None), rating (res on a rating kind, else None), err}]. Empty where Grade H is off. One read per setup."""
    if not gradeh_on():
        return []
    key = _kpi_key(kpi_name)
    out = []
    for st in db.execute("SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=?" + (" AND company=?" if company else "") + " ORDER BY company, id",
                         [period["id"], business_group] + ([company] if company else [])):
        if _kpi_key(st["kpi_name"]) != key or not can_access(me, st["business_group"], st["company"]):
            continue
        lines = gradeh_bu_linked(db, st)
        if not lines:
            continue
        kinds = _gh_bu_kinds(lines)
        kind = next(iter(kinds)) if len(kinds) == 1 else None
        res, err = None, ""
        if value is not None:
            if kind is None:   # a mix is never half-filled (the link refuses a mismatch, so this is not expected)
                err = _gh_bu_mix_words(st)
            else:
                try:
                    res = gradeh_bu_result_of(db, st, value, lines[0]["scale"])[1]
                except GradehRefusal as e:
                    err = str(e)
        out.append({"setup": dict(st), "lines": lines, "kind": kind, "res": res, "err": err,
                    "pct": res if kind == "pct" else None, "rating": res if kind == "rating" else None})
    return out


def _bu_fill_gh_counts(gh):
    """{lines, people, before, submitted, acknowledged} over _bu_fill_gh's setups (the confirm box's numbers)."""
    c = {"lines": 0, "people": 0, "before": 0, "submitted": 0, "acknowledged": 0}
    seen = set()
    for g in gh:
        for r in g["lines"]:
            c["lines"] += 1
            c[r["stage"]] += 1
            seen.add(r["pid"])
    c["people"] = len(seen)
    return c


def _bu_fig(v, unit):
    """A figure with its unit as the page writes it: '104%', '5 pcs'."""
    return "%g" % v + (" " + unit if unit and unit != "%" else ("%" if unit == "%" else ""))


def _bu_day(ts):
    """A stored UTC timestamp as '5 Nov' in MYT."""
    m = _myt(ts)
    try:
        return datetime.strptime(m, "%Y-%m-%d %H:%M").strftime("%-d %b")
    except (ValueError, TypeError):
        return m or ""


def _gh_res_text(kind, v):
    """A Grade H result as Fill BU KPI's Rating column writes it: '92.0%' for the achievement % of a line on a % scale, 'Rating 4' for the
    rating of a line rated 1-5 (the normal holders' rows read 'Rating 4' too), '—' for none."""
    if v is None:
        return "—"
    return ("Rating %d" % v) if kind == "rating" else "%.1f%%" % v


def _gh_line_res_text(r):
    """The result a Grade H line (a gradeh_bu_linked dict) holds, in the same words; '—' while it waits."""
    if r["scale"] in GRADEH_BU_RATED_SCALES:
        return _gh_res_text("rating", r.get("bu_rating"))
    return _gh_res_text("pct", r.get("bu_pct"))


_BU_HELD_WORDS = "Calibrated, left as is"   # a line Fill BU result leaves: a calibrator has acted on the person, or their result is released
_BU_RELEASED_WORDS = "Released, left as is"   # what the super admin's Fill BU result leaves (2026-11-14): only a released result


def _bu_fill_rows(buckets, unit, gh=None, view=None, typed=None):
    """The 'Who gets this result' rows, one list over the buckets: name, ID / JG / department, the line's weight, its
    rating for the result typed, and a status (will fill / filled before X to Y / moderated, will be replaced / calibrated, left as is).
    `gh` (_bu_fill_gh): the Grade H
    lines, after the normal holders, with the Grade H chip, the achievement % for the result typed and where each person is.
    `view` (2026-11-05, the filled card): None = a KPI nobody has filled, today's words; "read" = the filled card (Filled with its figure
    and day, Not filled yet, Calibrated, stays as filled; each line's rating from its own figure); "edit" = the same card being edited
    (Changes: 104% -> 106%, Stays: 104%, Will be filled), `typed` the figure in the box."""
    def fmt(v):
        return _bu_fig(v, unit)

    def rt_of(sc):
        return "—" if not sc else (("Rating %d" % sc["value"]) if sc["mechanism"] == "A" else "%.1f%%" % sc["value"])

    def chg(old):   # edit: what the typed figure does to a filled line
        if typed is None:
            return "Filled: " + fmt(old), "is-ok"
        if abs(typed - old) < 1e-9:
            return "Stays: " + fmt(old), "is-grey"
        return "Changes: %s → %s" % (fmt(old), fmt(typed)), "is-warn"
    out = []
    for key in ("will_fill", "will_overwrite", "has_approval", "locked"):
        for row in buckets[key]:
            t, u, sc = row["target"], row["subject"], row["score"]
            res = t.get("result")
            filled = bool(res and res["admin_filled"])
            sub = ""
            held_words = _BU_RELEASED_WORDS if row.get("rel_view") else _BU_HELD_WORDS   # the super admin's view leaves only a released result
            if view is None:
                rt = "—"
                if sc and key != "locked":
                    rt = ("Rating %d" % sc["value"]) if sc["mechanism"] == "A" else "%.1f%%" % sc["value"]
                st = {"will_fill": ("Will be filled", "is-navy"), "will_overwrite": ("", "is-warn"),
                      "has_approval": ("Moderated, will be replaced", "is-warn"), "locked": (held_words, "is-grey")}[key]
                label = st[0]
                if key == "will_overwrite":
                    new = ""
                    if sc:
                        new = (" → %d" % sc["value"]) if sc["mechanism"] == "A" else (" → %.1f%%" % sc["value"])
                    label = "Filled before: %s%s" % (fmt(row["previous_value"]), new if sc else "")
                cls = st[1]
            elif filled:
                fig = res["actual_value"]
                if row.get("held"):
                    label, cls, rt = ("Released, stays as filled" if row.get("rel_view") else "Calibrated, stays as filled"), "is-grey", rt_of(row.get("own_score"))
                    sub = "%s · %s" % (fmt(fig), _bu_day(res["submitted_at"]))
                elif view == "read":
                    label, cls, rt = "Filled", "is-ok", rt_of(row.get("own_score"))
                    sub = "%s · %s" % (fmt(fig), _bu_day(res["submitted_at"]))
                elif row.get("refill"):   # edit: the super admin's refill line
                    label, cls = chg(fig)
                    rt = rt_of(sc) if (typed is not None and cls != "is-grey") else rt_of(row.get("own_score"))
                else:   # edit, a filled line this admin cannot change (not the super admin)
                    label, cls, rt = "Stays: " + fmt(fig), "is-grey", rt_of(row.get("own_score"))
            elif key == "has_approval":   # the line manager's moderation goes; the typed figure scores like any line that will be filled
                label, cls, rt = "Moderated, will be replaced", "is-warn", rt_of(sc)
            elif key == "locked":   # a calibrated person's moderated line: the only unfilled line left as it is
                label, cls, rt = held_words, "is-grey", "—"
            else:   # nothing filled on this line yet; it may hold the person's own submitted figure
                if view == "read":
                    label, cls, rt = "Not filled yet", "is-warn", "—"
                else:
                    label, cls, rt = "Will be filled", "is-navy", rt_of(sc)
                if key == "will_overwrite":
                    sub = ("Their own figure: %s" if view == "read" else "Replaces their own figure: %s") % fmt(row["previous_value"])
            out.append({"name": u["full_name"], "eid": ja_eid(u["employee_id"]), "g": grade_num(u["job_grade"]),
                        "dept": u["department"] or "", "w": ("%g%%" % t["weightage"]) if t.get("weightage") is not None else "—",
                        "rt": rt, "label": label, "cls": cls, "key": key, "sub": sub, "cal": bool(row.get("calibrated"))})
    for g in gh or []:
        for r in g["lines"]:
            has = r.get("bu_value") is not None
            if view is None:
                label, cls, rt, sub = "Will be filled", "is-navy", _gh_res_text(g["kind"], g["res"]), GRADEH_BU_STAGE_WORDS[r["stage"]]
            elif has:
                stage = GRADEH_BU_STAGE_WORDS[r["stage"]]
                if view == "read":
                    label, cls = "Filled", "is-ok"
                    sub = "%s · %s · %s" % (fmt(r["bu_value"]), _bu_day(r["filled_at"]), stage)
                    rt = _gh_line_res_text(r)
                else:
                    label, cls = chg(r["bu_value"])
                    sub = stage
                    rt = _gh_res_text(g["kind"], g["res"]) if (typed is not None and g["res"] is not None and cls != "is-grey") else _gh_line_res_text(r)
            else:
                stage = GRADEH_BU_STAGE_WORDS[r["stage"]]
                sub = stage
                if view == "read":
                    label, cls, rt = "Not filled yet", "is-warn", "—"
                else:
                    label, cls, rt = "Will be filled", "is-navy", _gh_res_text(g["kind"], g["res"])
            out.append({"name": r["name"], "eid": r["eid"], "g": r["grade"] or "H", "dept": r["dept"] or "",
                        "w": ("%g%%" % r["weight"]) if r["weight"] is not None else "—",
                        "rt": rt, "label": label, "cls": cls, "key": "gh", "gh": True, "sub": sub})
    return out


def _bu_fill_rail(db, me, period, business_group, company, units):
    """The left rail of Fill BU result (2026-10-27): the saved BU KPI setups of the unit (or, for the whole group, of
    its units), then the library's BU-level KPIs that have no setup but have lines, so nothing fillable today
    disappears. Each with who carries it, who keeps their own, and whether its result is filled. One read of the
    lines (grouped), one of the setups, one of the filled results. {"saved": [...], "lib": [...], "reps": {key: line}}."""
    cos = [company] if company else list(units)
    bclause, bparams = bg_scope(me, "t.business_group")
    setups = [dict(r) for r in db.execute(
        "SELECT * FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? ORDER BY kpi_name",
        (period["id"], business_group)) if r["company"] in cos]
    sid = {(r["company"], _kpi_key(r["kpi_name"])): r["id"] for r in setups}
    allst = {r["id"]: (r["company"], _kpi_key(r["kpi_name"])) for r in db.execute(
        "SELECT id, company, kpi_name FROM pm_bu_kpis WHERE cycle_id=? AND business_group=?", (period["id"], business_group))}
    lines = {}   # (company, key) -> {"n": all, "linked": by setup, "rep": a line's scale}
    # the whole group's lines, grouped: a guest's line (2026-11-07) belongs to the unit whose setup it is linked to, not to the
    # guest's own unit, so a unit's own view must see lines of other companies too
    for r in db.execute(
            "SELECT t.company, t.kpi_name, t.bu_kpi_id, COUNT(*) AS n, MAX(t.id) AS mid, t.method, t.unit, t.rate1, t.rate2, "
            "t.rate3, t.rate4, t.rate5, t.threshold, t.target, t.multiple, t.excellence FROM pm_kpi_targets t WHERE "
            "t.cycle_id=? AND t.business_group=?" + bclause
            + " GROUP BY t.company, t.kpi_name, t.bu_kpi_id", [period["id"], business_group] + bparams):
        lk = allst.get(r["bu_kpi_id"]) if r["bu_kpi_id"] else None
        if lk is not None and lk[1] == _kpi_key(r["kpi_name"]) and lk[0] != r["company"]:   # a guest's line: the setup's unit's
            if lk[0] in cos:
                o = lines.setdefault(lk, {"n": 0, "linked": 0, "rep": None, "name": r["kpi_name"]})
                o["n"] += r["n"]
                o["linked"] += r["n"]
                o["rep"] = dict(r)
            continue
        if lk is not None and lk[0] != r["company"]:   # linked to another unit's setup under another name: not this unit's
            continue
        if r["company"] not in cos:
            continue
        o = lines.setdefault((r["company"], _kpi_key(r["kpi_name"])), {"n": 0, "linked": 0, "rep": None, "name": r["kpi_name"]})
        o["n"] += r["n"]
        if r["bu_kpi_id"] and r["bu_kpi_id"] == sid.get((r["company"], _kpi_key(r["kpi_name"]))):
            o["linked"] += r["n"]
            o["rep"] = dict(r)
        elif o["rep"] is None and not sid.get((r["company"], _kpi_key(r["kpi_name"]))):
            o["rep"] = dict(r)
    filled = _bu_filled_map(db, me, period, business_group, company)
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?", (business_group,)).fetchone()
    libkeys = {}
    for r in db.execute("SELECT l.kpi_name, l.company, l.business_group FROM pm_kpi_library l WHERE l.active=1 AND "
                        "l.bu_level=1 AND l.business_group=?", (business_group,)):
        libkeys.setdefault(_kpi_key(r["kpi_name"]), []).append(r["company"] or "*")

    # the Grade H lines that follow each setup (2026-11-05): carriers too, and filled once they hold the typed figure; one batched read
    ghs = gradeh_bu_filled_stats(db, setups) if gradeh_on() else {}

    def mk(key, name, setup_cos, scope):
        n = sum(lines.get((c, key), {}).get("n", 0) for c in cos if (c, key) in lines)
        linked = sum(lines.get((c, key), {}).get("linked", 0) for c in setup_cos)
        in_setup = sum(lines.get((c, key), {}).get("n", 0) for c in setup_cos)
        g_n = g_filled = 0
        g_vals = {}
        for c in setup_cos:
            sid_ = sid.get((c, key))
            o_ = ghs.get(sid_) if sid_ is not None else None
            if o_:
                g_n += o_["n"]
                g_filled += o_["filled"]
                for v_, k_ in o_["values"].items():
                    g_vals[v_] = g_vals.get(v_, 0) + k_
        carry = linked + sum(lines[(c, key)]["n"] for c in cos if (c, key) in lines and c not in setup_cos) + g_n
        keep = in_setup - linked
        fm = [filled[(c, key)] for c in cos if (c, key) in filled]
        res = None
        if fm or g_filled:
            vals = sorted({v for f_ in fm for v in f_["values"]} | set(g_vals))
            rep = next((lines[(c, key)]["rep"] for c in cos if (c, key) in lines and lines[(c, key)]["rep"]), None)
            res = {"value": vals[0] if len(vals) == 1 else None, "many": len(vals) > 1, "nfig": len(vals), "rate": None, "pct": None,
                   "to_fill": max(carry - sum(f_["n"] for f_ in fm) - g_filled, 0)}
            if res["value"] is not None and rep and (cfg or rep.get("rate1") is not None):
                sc = _bu_fill_score(cfg, rep, res["value"])
                if sc:
                    res["rate" if sc["mechanism"] == "A" else "pct"] = sc["value"]
            res["unit"] = (rep or {}).get("unit") or ""
            if not res["unit"] and g_n:
                res["unit"] = next((st_["unit"] for st_ in setups if st_["company"] in setup_cos and _kpi_key(st_["kpi_name"]) == key), "") or ""
        return {"name": name, "scope": scope, "units": len(setup_cos), "carry": carry, "keep": keep, "n": n, "filled": res, "n_gh": g_n, "sub": False}

    libco = {r["id"]: r["company"] for r in db.execute(
        "SELECT id, company FROM pm_kpi_library WHERE business_group=?", (business_group,))}
    saved_rows, seen = [], set()
    by_key = {}
    for st in setups:
        by_key.setdefault(_kpi_key(st["kpi_name"]), []).append(st)
    for key, sts in sorted(by_key.items(), key=lambda kv: kv[1][0]["kpi_name"].lower()):
        scope = "Group-wide" if libco.get(sts[0]["library_id"], "") in ("*", None, "") and sts[0]["library_id"] in libco \
            else "This unit"
        saved_rows.append(mk(key, sts[0]["kpi_name"], [st["company"] for st in sts], scope))
        seen.add(key)
    # a variant sits right under its root when the root is saved in the unit too (as on BU KPI setup)
    # (the variants, 1+, of a root that is not saved sit under a heading for it: _bu_rail_layout, shared with BU KPI setup)
    saved_rows, saved_view = _bu_rail_layout(saved_rows)
    lib_rows = []
    for key, names in sorted(libkeys.items()):
        if key in seen:
            continue
        have = [(c, k) for (c, k) in lines if k == key]
        if not have:
            continue
        lib_rows.append(mk(key, lines[have[0]]["name"], [], "Group-wide" if "*" in names else "This unit"))
    seen |= {_kpi_key(x["name"]) for x in lib_rows}
    other = {}
    for (c, key), o in lines.items():   # every other name with lines stays fillable by name, as the drop-down offered
        if key not in seen:
            other.setdefault(key, o["name"])
    other_rows = []
    for key, nm in sorted(other.items(), key=lambda kv: kv[1].lower()):
        r_ = mk(key, nm, [], "")
        r_["other"] = True
        other_rows.append(r_)
    return {"saved": saved_rows, "saved_view": saved_view, "lib": lib_rows, "other": other_rows, "setups": setups}


@app.route("/admin/performance/bu-fill", methods=["GET", "POST"])
@admin_required
def admin_performance_bu_fill():
    """Batch-fill a BU-level KPI (one figure shared across many people, e.g.
    a factory-line-wide GP% target) in one shot instead of re-typing the
    same number per person. Confirmed design: no new "is this KPI BU-level"
    schema flag -- admin just picks the KPI by name; the fill applies to
    EVERY pm_kpi_targets row sharing that exact kpi_name this period, within
    scope; an admin fill is immediately FINAL -- it auto-locks and skips the
    normal approver chain entirely (see attach_pm_chains()'s admin_filled
    OR-clause and _pm_line_actionable_by()'s matching locked guard, both
    upstream of this route).

    Every BU KPI follows the number Group People fills (Chris, 2026-11-13). A line an approver has acted on, partly or
    to the end of its chain, is filled too: pm_effective_value() prioritizes the last approval over the raw result,
    so the moderation is archived (lm_handover_archive, part "pm_bu_fill") and taken off THAT line only, in the same
    transaction and before the result is written; the person's other lines and the line manager's moderation of them
    stay. The one exception is a person a calibrator has acted on, or whose result is released
    (_pm_calibration_hold): their line is left exactly as it is and the page says so. Preview and commit both
    re-derive the eligible set fresh from the DB (_bu_fill_buckets, no serialized target list carried between
    requests) so a status change between preview and commit -- e.g. a calibrator acts in the meantime -- is never
    silently missed. Nothing is emailed (a fill never emails).
    A line linked to a BU KPI setup AFTER this fill takes the unit's figure as it joins (_bu_fill_carry, 2026-11-07), so the
    page does not read "N to fill" for a person added later."""
    db = get_db()
    me = current_user()
    period = active_pm_period(db)
    scoped_bg = admin_bg_of(me)
    if scoped_bg:
        bgs = [scoped_bg]
    else:
        bgs = [r["business_group"] for r in db.execute(
            "SELECT DISTINCT business_group FROM org_units "
            "WHERE active=1 ORDER BY business_group").fetchall()]

    if not period:
        flash("No active performance period.", "error")
        return redirect(url_for("admin_cycles"))

    # Business group, then unit, as rows (the admin review, 2026-10-10), counting the people with KPI lines this
    # cycle; the unit row's first option is the whole of what you look after
    frows, fsel = admin_filter_rows(
        db, me, "admin_performance_bu_fill", params=("business_group", "company", "dept"), levels=2, bg_all=False,
        people_sql="role!='admin' AND left_at IS NULL AND id IN (SELECT subject_id FROM pm_kpi_targets WHERE "
                   "cycle_id=%d)" % int(period["id"]))
    business_group = (request.values.get("business_group", "") or "").strip() or fsel["bg"]
    if business_group and business_group not in bgs:
        abort(403)
    # The unit (business unit = company) to fill, or "" for everything in
    # scope: the whole BG for a BG admin, all of a BU admin's own units for
    # them (Chris, 2026-10-10: "the bu or bg admin can update for the BU one
    # shot"). A unit with no KPI line this cycle simply offers no KPI.
    company = (request.values.get("company", "") or "").strip()
    units, kpi_names = [], []
    whole_label = "All your units" if admin_companies_of(me) else "Whole business group"
    for row in frows:
        if row["label"] == "Business unit" and row["opts"]:
            row["opts"][0]["label"] = whole_label
    if business_group:
        units = [r["company"] for r in db.execute(
            "SELECT DISTINCT company FROM pm_kpi_targets WHERE cycle_id=? AND business_group=? "
            "AND COALESCE(company,'')!='' ORDER BY company", (period["id"], business_group)).fetchall()
            if can_access(me, business_group, r["company"])]
        if company and not can_access(me, business_group, company):
            abort(403)
        kpi_names = [r["kpi_name"] for r in db.execute(
            "SELECT DISTINCT kpi_name FROM pm_kpi_targets t "
            "WHERE t.cycle_id=? AND t.business_group=?" + (" AND t.company=?" if company else "")
            # a guest's line (linked to ANOTHER unit's setup, 2026-11-07) is filled with the unit whose KPI it is: it adds no name here
            + " AND NOT EXISTS (SELECT 1 FROM pm_bu_kpis b WHERE b.id=t.bu_kpi_id AND b.company!=t.company)"
            + " ORDER BY kpi_name",
            (period["id"], business_group) + ((company,) if company else ())).fetchall()]
        if gradeh_on():   # a BU KPI held by Grade H lines alone (a variant made for them) has no scorecard line, yet it is fillable
            have_ = {_kpi_key(x) for x in kpi_names}
            for r in db.execute("SELECT DISTINCT s.kpi_name, s.company FROM pm_bu_kpis s JOIN gradeh_kpi_lines l ON l.bu_kpi_id=s.id "
                                "WHERE s.cycle_id=? AND s.business_group=?" + (" AND s.company=?" if company else ""),
                                (period["id"], business_group) + ((company,) if company else ())):
                if _kpi_key(r["kpi_name"]) not in have_ and can_access(me, business_group, r["company"]):
                    have_.add(_kpi_key(r["kpi_name"]))
                    kpi_names.append(r["kpi_name"])
            kpi_names.sort()
    back = dict(business_group=business_group, company=company or None)
    where = company or (business_group + ("" if not admin_companies_of(me) else ", your units"))

    if request.method == "POST":
        kpi_name = (request.form.get("kpi_name", "") or "").strip()
        note = (request.form.get("note", "") or "").strip() or None
        if business_group not in bgs:
            abort(403)
        calc = request.form.get("action") == "calc"
        if not kpi_name:
            if calc:
                return jsonify(ok=False, error="Choose a KPI."), 400
            flash("Choose a KPI.", "error")
            return redirect(url_for("admin_performance_bu_fill", **back))
        actual_raw = (request.form.get("actual_value", "") or "").strip()
        try:
            actual_value = float(actual_raw)
        except ValueError:
            actual_value = None
            if not calc:
                flash("Enter a valid number for the result.", "error")
                return redirect(url_for("admin_performance_bu_fill", kpi_name=kpi_name, **back))
        back_k = dict(back, kpi_name=kpi_name)

        targets, buckets, _subjects, cfg = _bu_fill_buckets(db, me, period, business_group, company, kpi_name, actual_value)
        # the Grade H lines that follow this BU KPI (2026-11-03): one figure, filled for them in the same transaction (gradeh_bu_fill)
        gh = _bu_fill_gh(db, me, period, business_group, company, kpi_name, actual_value)
        if calc:   # live as you type: the page asks, the server scores (pm_score_kpi_line), nothing is written
            return jsonify(_bu_fill_calc(buckets, targets, cfg, actual_value, gh))
        if not targets and not gh:
            flash(f"No KPI lines found for '{kpi_name}' in {where} within your scope.", "error")
            return redirect(url_for("admin_performance_bu_fill", **back_k))
        if gh and not is_super(me):   # Grade H lines share this result and only the super admin fills for them: nothing is half-filled
            flash("%d Grade H line%s share this KPI's result, and only the super admin can fill it. Nothing was filled." % (
                sum(len(g_["lines"]) for g_ in gh), "" if sum(len(g_["lines"]) for g_ in gh) == 1 else "s"), "error")
            return redirect(url_for("admin_performance_bu_fill", **back_k))
        if gh and any(g_["res"] is None for g_ in gh):
            flash((next((g_["err"] for g_ in gh if g_["err"]), "") or "That figure gives no result for the Grade H lines.") + " Nothing was filled.", "error")
            return redirect(url_for("admin_performance_bu_fill", **back_k))

        # ----- commit -----
        # the super admin's fill reaches people a calibrator has acted on (2026-11-14: until results are released), and the remark
        # SUPER_BAND_ENDPOINTS asks for is asked only under the action "apply_calibrated": a plain apply that would reach them is
        # refused here, so the remark cannot be skipped (a stale page, a hand-made post). Nothing is written.
        n_cal = sum(1 for row in _bu_fill_eligible(buckets) if row.get("calibrated"))
        if n_cal and request.form.get("action") != "apply_calibrated":
            flash("This fill reaches %d calibrated %s, which needs your remark. Reload the page and fill again. Nothing was filled." % (
                n_cal, "person" if n_cal == 1 else "people"), "error")
            return redirect(url_for("admin_performance_bu_fill", **back_k))
        # a result-level edit: the admin's reason is required and goes in the trail (Chris, 2026-10-18); where the remark was asked
        # (calibrated people reached) it is the reason
        reason, rerr = _admin_result_reason(request.form.get("reason") or _super_remark_now())
        if rerr:
            flash(rerr, "error")
            return redirect(url_for("admin_performance_bu_fill", **back_k))
        eligible = _bu_fill_eligible(buckets)
        # Bucketing above (t["result"]) deliberately hides drafts -- an
        # employee's own not-yet-submitted draft correctly reads as
        # "will_fill", not "will_overwrite a real submission". But a raw
        # existence check is needed here, independent of that display
        # gating: pm_kpi_results.kpi_target_id is UNIQUE, so INSERTing over
        # a hidden draft row would raise IntegrityError. This is a
        # different question from the bucketing one and needs its own
        # answer, not a reuse of t["result"].
        eligible_ids = [row["target"]["id"] for row in eligible]
        existing_ids = set()
        if eligible_ids:
            ph2 = ",".join("?" * len(eligible_ids))
            existing_ids = {r["kpi_target_id"] for r in db.execute(
                f"SELECT kpi_target_id FROM pm_kpi_results WHERE kpi_target_id IN ({ph2})", eligible_ids)}
        # the moderated lines this fill replaces (2026-11-13): what an approver left on each is kept first (one batched read of the
        # people's own rows and the moderation drafts for all of them), then taken off that line only
        mod_ids = [row["target"]["id"] for row in eligible if _bu_moderated(row["target"])]
        mod_drafts, mod_results = {}, {}
        if mod_ids:
            ph3 = ",".join("?" * len(mod_ids))
            for r in db.execute(f"SELECT * FROM pm_kpi_moderation_drafts WHERE kpi_target_id IN ({ph3})", mod_ids):
                mod_drafts.setdefault(r["kpi_target_id"], []).append(dict(r))
            mod_results = {r["kpi_target_id"]: dict(r) for r in db.execute(
                f"SELECT * FROM pm_kpi_results WHERE kpi_target_id IN ({ph3})", mod_ids)}
        filled, unchanged, replaced, fill_sids, mod_sids = 0, 0, 0, set(), set()
        for row in eligible:
            t = row["target"]
            if not can_access(me, t["business_group"], t.get("_fill_unit") or t["company"]):
                continue  # defense-in-depth; bg_scope() already filtered the query (a guest's line: the unit whose KPI it is)
            # a line that already holds exactly this figure and remark, filled by Group People and final (2026-11-09): it is left
            # as it is, no UPDATE, so "Filled <date>" and who filled it stay, and its person is not asked about again (no pre-run).
            # Only a visible final admin-filled row counts; a person's own result or a hidden draft is still written (absent is not
            # the same as equal: a missing note is read as no note).
            _res = t.get("result")
            if (_res and _res["admin_filled"] and not _res["draft"] and t["id"] in existing_ids and _res["actual_value"] is not None
                    and abs(float(_res["actual_value"]) - actual_value) < 1e-9
                    and ((_res["note"] or "").strip() or None) == note):
                unchanged += 1
                continue
            if _bu_moderated(t):
                # the approvers' work on THIS line goes in the archive (rows as they were, JSON: never shown on a page), then off the
                # line, in this transaction and before the result is written; the person's other lines keep their moderation
                _lm_archive(db, period["id"], t["subject_id"], "pm_bu_fill", t["approvals"][0]["acted_by"], None, reason, {
                    "kpi_target_id": t["id"], "kpi_name": t["kpi_name"], "filled_value": actual_value,
                    "approvals": [dict(x) for x in t["approvals"]], "chains": [dict(x) for x in t["approver_chain"]],
                    "drafts": mod_drafts.get(t["id"], []), "result": mod_results.get(t["id"])}, me["id"])
                db.execute("DELETE FROM pm_kpi_approvals WHERE kpi_target_id=?", (t["id"],))
                db.execute("DELETE FROM pm_kpi_moderation_drafts WHERE kpi_target_id=?", (t["id"],))
                replaced += 1
                mod_sids.add(t["subject_id"])
            # draft=0: an admin fill is always immediately final, regardless
            # of whether the row being overwritten started as a private
            # employee draft.
            if t["id"] in existing_ids:
                db.execute(
                    "UPDATE pm_kpi_results SET actual_value=?, note=?, submitted_by=?, "
                    "admin_filled=1, submitted_at=datetime('now'), draft=0 WHERE kpi_target_id=?",
                    (actual_value, note, me["id"], t["id"]))
            else:
                db.execute(
                    "INSERT INTO pm_kpi_results(kpi_target_id, actual_value, note, "
                    "submitted_by, admin_filled, draft) VALUES (?,?,?,?,1,0)",
                    (t["id"], actual_value, note, me["id"]))
            filled += 1
            fill_sids.add(t["subject_id"])
        gh_tot = {"lines": 0, "people": 0, "before": 0, "submitted": 0, "acknowledged": 0, "rescored": 0}
        for g_ in gh:   # in the same transaction: a refusal here undoes the normal fill too
            ok_, why_, c_ = gradeh_bu_fill(db, me, g_["setup"], g_["pct"], value=actual_value, rating=g_["rating"])
            if not ok_:
                db.rollback()
                flash(why_ + " Nothing was filled.", "error")
                return redirect(url_for("admin_performance_bu_fill", **back_k))
            for k_ in gh_tot:
                gh_tot[k_] += c_[k_]
        if mod_sids:   # a replaced moderation moves the person's moderated figure: their rating record follows (it asks the pre-run too)
            _rating_record_refresh(db, period["id"], sorted(mod_sids), "pm_bu_fill", me["id"])
        if fill_sids - mod_sids:
            _prerun_on_event(db, period["id"], fill_sids - mod_sids, "pm_bu_fill")   # their insights read HR's figure (2026-10-14)
        db.commit()
        n_refill = sum(1 for row in eligible if row.get("refill") and row["target"]["subject_id"] in fill_sids)
        skipped_held = len(buckets["locked"])   # only calibrated or released people's lines (and Group People's own fill this admin cannot change)
        n_cal_done = sum(1 for row in eligible if row.get("calibrated") and row["target"]["subject_id"] in fill_sids)
        if filled or gh_tot["lines"]:   # nothing written means nothing for the trail: an unchanged line gets no audit row
            log_activity(db, me["id"], "pm_bu_fill",
                         f"{business_group}" + (f" / {company}" if company else "") + f" - '{kpi_name}': filled {filled}, "
                         f"skipped {skipped_held} calibrated, released or already filled"
                         + (f"; replaced {replaced} line managers' moderation" if replaced else "")
                         + (f"; {unchanged} already held this figure and were left as they were" if unchanged else "")
                         + (f"; refilled {n_refill} replacing Group People's earlier figure" if n_refill else "")
                         + (f"; {n_cal_done} calibrated {'person' if n_cal_done == 1 else 'people'} included (a band a calibrator moved stays)" if n_cal_done else "")
                         + (f"; also {gh_tot['lines']} Grade H line(s) of {gh_tot['people']} people ({gh_tot['acknowledged']} already acknowledged)" if gh_tot["lines"] else "")
                         + f"; reason: {reason}")
        ack_ = f", {gh_tot['acknowledged']} of them already acknowledged: their result updates" if gh_tot["acknowledged"] else ""
        if not targets:   # a KPI held by Grade H lines alone has no scorecard line to count (2026-11-05)
            flash(f"Filled {gh_tot['lines']} Grade H line{'' if gh_tot['lines'] == 1 else 's'} for '{kpi_name}' in {where}" + ack_ + ".", "ok")
        else:
            flash(f"Filled {filled} of {len(targets)} matching KPI line(s) for '{kpi_name}' in {where}."
                  + (f" {unchanged} already held that figure and were left as they are." if unchanged else "")
                  + (f" {replaced} had a line manager's moderation, which the new figure replaces." if replaced else "")
                  + (f" {n_cal_done} calibrated: a band a calibrator moved stays; a band nobody moved follows the new score." if n_cal_done else "")
                  + (f" {skipped_held} skipped (calibrated, released or already filled)." if skipped_held else "")
                  + ((f" Also filled {gh_tot['lines']} Grade H line{'' if gh_tot['lines'] == 1 else 's'}" + ack_ + ".")
                     if gh_tot["lines"] else ""), "ok")
        return redirect(url_for("admin_performance_bu_fill", **back_k))

    ctx = dict(period=period, bgs=bgs, frows=frows, business_group=business_group, kpi_names=kpi_names, units=units,
               company=company, whole_label=whole_label, where=where, rail=None, sel=None)
    if business_group and kpi_names:
        rail = _bu_fill_rail(db, me, period, business_group, company, units)
        pool = rail["saved"] + rail["lib"] + rail["other"]
        want = (request.args.get("kpi_name", "") or "").strip()
        sel = next((x for x in pool if _kpi_key(x["name"]) == _kpi_key(want)), None) or (pool[0] if pool else None)
        ctx["rail"] = rail
        if sel:
            targets, buckets, _subjects, cfg = _bu_fill_buckets(db, me, period, business_group, company, sel["name"], None)
            gh = _bu_fill_gh(db, me, period, business_group, company, sel["name"])
            gc = _bu_fill_gh_counts(gh)
            rep = dict(targets[0]) if targets else (dict(gh[0]["setup"]) if gh else None)
            mech = "A" if (cfg and cfg["mechanism"] == "A") or (rep and rep.get("rating_line")) else "B"
            scales = {tuple(t.get(c) for c in _BU_SCALE_COLS) for t in targets}
            unit = kpi_unit_normalise((rep or {}).get("unit")) if rep else ""
            st1 = next((x for x in rail["setups"] if _kpi_key(x["kpi_name"]) == _kpi_key(sel["name"])), None)
            pairs = _bu_scale_text(rep, mech, unit)[0] if rep else []
            w = "Each line keeps its own weight"
            if st1 and len({x["weight_mode"] for x in rail["setups"] if _kpi_key(x["kpi_name"]) == _kpi_key(sel["name"])}) == 1:
                w = {"own": "Each keeps their own weight", "grade": "Weight by grade",
                     "one": "One weight for all" + (" · %g%%" % st1["weight"] if st1["weight"] is not None else "")}[st1["weight_mode"]]
            fs = _bu_fill_state(db, me, buckets, targets, cfg, gh, unit, rep)   # None until a line carries Group People's fill
            ctx["sel"] = {"item": sel, "name": sel["name"], "rep": rep, "mech": mech, "unit": unit, "pairs": pairs,
                          "differ": len(scales) > 1, "weight": w, "more": bool(rep and rep["method"] == "more"),
                          "rows": _bu_fill_rows(buckets, unit, gh, view="read" if fs else None),
                          "n_fill": len(_bu_fill_eligible(buckets)), "n_mod": len(buckets["has_approval"]),
                          "n_gh": gc["lines"], "n_gh_people": gc["people"], "n_gh_ack": gc["acknowledged"], "n_gh_sub": gc["submitted"],
                          "n_refill": sum(1 for r_ in buckets["will_overwrite"] if r_.get("refill")),
                          "n_cal": sum(1 for r_ in _bu_fill_eligible(buckets) if r_.get("calibrated")),
                          "n_total": len(targets), "keep": max(sel["n"] - len(targets), 0) if st1 else 0,
                          "fs": fs,
                          "label": display_company(business_group, company) if company else (
                              display_bg(business_group) + (", your units" if whole_label == "All your units" else ""))}
    return render_template("admin_performance_bu_fill.html", **ctx)


def _bu_fill_headline(rep, cfg, unit, value):
    """What a result scores, in the page's words: {mech, achievement, rating, rate, band, value_text} (all "" / None with no value or no scoring
    set). The one place Fill BU KPI's calc and its filled card get Achievement and Score / Rating from pm_score_kpi_line."""
    out = {"mech": None, "achievement": "", "rating": "", "rate": None, "band": "",
           "value_text": "" if value is None else _bu_fig(value, unit or "")}
    sc = _bu_fill_score(cfg, rep, value) if rep else None
    if sc and value is not None:
        out["mech"] = sc["mechanism"]
        u = unit or ""
        sf = (u if u == "%" else (" " + u if u else ""))
        if sc["mechanism"] == "A":
            out["achievement"] = "%g%s" % (value, sf)
            out["rate"] = sc["value"]
            out["rating"] = "%d" % sc["value"]
            out["band"] = _bu_band_text(rep, sc["value"], unit)
        else:
            out["achievement"] = "%.1f%%" % sc["value"]
            out["rating"] = "%.1f%%" % sc["value"]
    return out


def _bu_filled_any(buckets, gh):
    """True when at least one line of the selected KPI carries Group People's fill: a final admin-filled result on a normal line, or a
    typed figure on a Grade H line (bu_value). The one test the filled card and the calc's rows share."""
    for key in ("will_fill", "will_overwrite", "has_approval", "locked"):
        for row in buckets[key]:
            res = row["target"].get("result")
            if res and res["admin_filled"]:
                return True
    return any(r.get("bu_value") is not None for g in (gh or []) for r in g["lines"])


def _bu_fill_state(db, me, buckets, targets, cfg, gh, unit, rep):
    """The filled card of one BU KPI (Chris, 2026-11-05, canvas: Fill BU KPI filled / edit): None when no line carries Group People's
    fill, else the facts the read view draws, from what the page already read (the buckets and the Grade H lines: no query per
    person; one for the name of whoever filled last). Figures: the distinct filled figures with their line counts; the single one drives
    Achievement and Score through the server's own scoring (_bu_fill_headline). `action` says what the foot offers the viewer:
    "edit" (the super admin, something can still change), "edit_off" (all held), "fill" (an admin who cannot refill, lines still
    unfilled), or None. The server's own rules are unchanged: this only reflects them."""
    if not _bu_filled_any(buckets, gh):
        return None
    sup = is_super(me)
    gc = _bu_fill_gh_counts(gh or [])
    fl = []   # (value, when, by user id, note, is_normal)
    open_ = held = n_unf_n = 0
    for key in ("will_fill", "will_overwrite", "has_approval", "locked"):
        for row in buckets[key]:
            res = row["target"].get("result")
            if res and res["admin_filled"]:
                fl.append((res["actual_value"], res["submitted_at"] or "", res["submitted_by"], res["note"], True))
                if row.get("held"):
                    held += 1
                elif row.get("refill"):
                    open_ += 1
            elif key in ("will_fill", "will_overwrite", "has_approval"):
                n_unf_n += 1
    n_unf_g = n_gh_filled = 0
    for g in gh or []:
        for r in g["lines"]:
            if r.get("bu_value") is not None:
                fl.append((r["bu_value"], r["filled_at"] or "", r.get("filled_by"), None, False))
                n_gh_filled += 1
            else:
                n_unf_g += 1
    n_carry = len(targets) + gc["lines"]
    n_filled = len(fl)
    figs = {}
    for v, *_ in fl:
        figs[v] = figs.get(v, 0) + 1
    figures = sorted(figs.items(), key=lambda kv: (-kv[1], kv[0]))
    single = figures[0][0] if len(figures) == 1 else None
    last = max(fl, key=lambda x: x[1])
    notes = [x for x in fl if x[4]]
    note = (max(notes, key=lambda x: x[1])[3] or "") if notes else ""
    gh_only = not targets
    by = db.execute("SELECT full_name FROM users WHERE id=?", (last[2],)).fetchone() if last[2] else None
    fs = {"n_filled": n_filled, "n_carry": n_carry, "n_to_fill": max(n_carry - n_filled, 0), "figures": figures, "single": single,
          "gh_only": gh_only, "note": note, "when": _bu_when(last[1]), "by": (by["full_name"] if by and by["full_name"] else "Group People"),
          "unit": unit or "", "init_val": ("%g" % single) if single is not None else "", "init_note": note,
          "n_open": open_, "n_held": held, "n_unf": n_unf_n + (n_unf_g if sup else 0), "n_gh": gc["lines"],
          "ach": "—", "score": "—", "band": "", "score_label": "Score", "was_ach": "", "was_score": "", "filled_text": "", "figure_text": ""}
    if single is not None:
        h = _bu_fill_headline(rep, cfg, unit, single)
        fs["figure_text"] = h["value_text"]
        fs["filled_text"] = h["value_text"]
        fs["score_label"] = "Rating" if h["mech"] == "A" else "Score"
        if h["achievement"]:
            fs["ach"], fs["score"], fs["band"] = h["achievement"], h["rating"] or "—", h["band"]
            fs["was_ach"], fs["was_score"] = h["achievement"], h["rating"] or "—"
        elif gh_only:   # no scale to score on here: the shared achievement % the Grade H lines hold
            pcts = {r["bu_pct"] for g in (gh or []) for r in g["lines"] if r.get("bu_pct") is not None}
            if len(pcts) == 1:
                fs["ach"] = fs["was_ach"] = "%g%%" % next(iter(pcts))
            else:   # lines rated 1-5 hold a rating, not a %
                rts = {r["bu_rating"] for g in (gh or []) for r in g["lines"] if r.get("bu_rating") is not None}
                if len(rts) == 1:
                    fs["score"] = fs["was_score"] = "%d" % next(iter(rts))
                    fs["score_label"] = "Rating"
        fs["box"] = ""
    else:
        if len(figures) <= 3:
            parts = ["%s on %d line%s" % (_bu_fig(v, unit or ""), n, "" if n == 1 else "s") if i == 0 else "%s on %d" % (_bu_fig(v, unit or ""), n)
                     for i, (v, n) in enumerate(figures)]
            fs["box"] = "%s figures: %s" % ({2: "Two", 3: "Three"}[len(figures)], " · ".join(parts))
        else:
            fs["box"] = "%d figures" % len(figures)
        fs["filled_text"] = ""
    if sup:
        can = open_ > 0 or fs["n_unf"] > 0 or gc["lines"] > 0
        fs["action"] = "edit" if can else "edit_off"
        fs["action_label"] = "Edit"
        fs["off_title"] = "All %d have their result released" % n_filled if not can else ""
        fs["foot"] = ("Filled %s MYT by %s" % (fs["when"], fs["by"])
                      + (" · final, skips the moderator." if can else ". All %d have their result released: the figure stays as filled." % n_filled))
    else:
        fillable = sum(1 for r_ in _bu_fill_eligible(buckets) if not r_.get("refill"))
        fs["n_unf"] = fillable if not gc["lines"] else 0
        fs["action"] = "fill" if fs["n_unf"] > 0 else None
        fs["action_label"] = "Fill the %d not filled" % fs["n_unf"]
        fs["foot"] = "Filled %s MYT by %s · only the super admin changes a filled result." % (fs["when"], fs["by"])
        if gc["lines"] and fs["n_to_fill"]:
            fs["foot"] += " The Grade H lines share this result, so only the super admin can fill the rest."
        fs["off_title"] = ""
    return fs


def _bu_fill_calc(buckets, targets, cfg, value, gh=None):
    """The JSON the Fill page draws as you type: the headline achievement and rating, the table of who gets it, and the
    button's words. Scored by the server's own pm_score_kpi_line (_bu_fill_buckets); the page only draws it. On a KPI that
    already carries Group People's fill the rows read as an edit (Changes: 104% -> 106%, Stays: 104%)."""
    rep = targets[0] if targets else (dict(gh[0]["setup"]) if gh else None)   # a variant held by Grade H lines alone scores on its own setup
    unit = kpi_unit_normalise(rep.get("unit")) if rep else ""
    gc = _bu_fill_gh_counts(gh or [])
    h = _bu_fill_headline(rep, cfg, unit, value)
    out = {"ok": True, "n_fill": len(_bu_fill_eligible(buckets)), "n_mod": len(buckets["has_approval"]), "n_total": len(targets),
           "n_refill": sum(1 for r_ in buckets["will_overwrite"] if r_.get("refill")),
           "n_cal": sum(1 for r_ in _bu_fill_eligible(buckets) if r_.get("calibrated")),
           "achievement": h["achievement"], "rating": h["rating"], "rate": h["rate"], "band": h["band"], "mech": h["mech"],
           "n_gh": gc["lines"], "n_gh_people": gc["people"], "n_gh_ack": gc["acknowledged"], "n_gh_sub": gc["submitted"],
           "gh_err": next((g["err"] for g in (gh or []) if g["err"]), ""), "value_text": h["value_text"]}
    view = "edit" if _bu_filled_any(buckets, gh) else None
    out["rows"] = render_template("_bu_fill_rows.html", rows=_bu_fill_rows(buckets, unit, gh, view=view, typed=value))
    return out


@app.route("/admin/performance/export.csv")   # the old address, kept
@app.route("/admin/performance/export.xlsx")
@admin_required
def admin_performance_export():
    """One row per KPI line for the active period, in the KPI targets import's own columns so it goes back in edited
    (2026-10-28), with Result: columns beside them -- the person's own value, the moderated value, the score, lock state
    and the approver chain by name. The subject's overall/label columns are populated only once every one of their
    lines is locked (same all-locked gate pm_overall_for_targets() itself uses), never a misleading partial average."""
    db = get_db()
    me_ = current_user()
    period = active_pm_period(db)
    if not period:
        flash("No active performance period.", "error")
        return redirect(url_for("admin_cycles"))
    bclause, bparams = bg_scope(me_, "t.business_group")
    targets = [dict(t) for t in db.execute(
        f"SELECT t.* FROM pm_kpi_targets t WHERE t.cycle_id=?{bclause} "
        f"ORDER BY t.subject_id, {PM_LINE_ORDER_T}", [period["id"]] + bparams).fetchall()]
    attach_pm_chains(db, targets)
    pm_score_targets(db, targets)
    by_subject = defaultdict(list)
    for t in targets:
        by_subject[t["subject_id"]].append(t)
    # the export lists everyone: the plain totals, then the transferred people's blend in ONE batched call (2026-11-03)
    overalls = pm_split_apply(db, period["id"], {sid: pm_overall_for_targets(db, ts, split=False) for sid, ts in by_subject.items()})
    subject_ids = list(by_subject.keys())
    subjects = {}
    if subject_ids:
        ph = ",".join("?" * len(subject_ids))
        subjects = {r["id"]: r for r in db.execute(
            f"SELECT * FROM users WHERE id IN ({ph})", subject_ids).fetchall()}

    # one sheet that goes back in through Import KPI targets (Chris, 2026-10-28): who it is about, the cycle, the
    # import's own columns (what you edit), then Result: columns that are only read. The framework columns follow the
    # business groups in the file.
    targets = [t for t in targets if t["subject_id"] in subjects and dl_keep(subjects[t["subject_id"]])]
    cfgs = {}
    for bg in {t["business_group"] for t in targets}:
        cfgs[bg] = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?", (bg,)).fetchone()
    fw = set()
    for t in targets:
        cfg = cfgs.get(t["business_group"])
        if t["mechanism"] == "A":
            fw |= {"Rate %d" % i for i in range(1, 6)}
        elif t["mechanism"] == "B":
            fw |= {"Threshold", "Target"} | ({"Excellence"} if cfg and cfg["variant"] == "excellence" else {"Multiple"})
    if not fw:
        fw = set(_KPI_FRAMEWORK_COLS)
    fw_cols = [c for c in _KPI_FRAMEWORK_COLS if c in fw]
    mechs = {t["mechanism"] for t in targets if t["mechanism"]} or {"A", "B"}
    approver_ids = {c["approver_id"] for t in targets for c in t["approver_chain"][:1]}
    approver_eid = {r[0]: r[1] for r in _rpt_ids(db, "SELECT id, employee_id FROM users WHERE id IN (%s)", approver_ids)}
    mgr_of = {sid: subjects[sid]["manager_id"] for sid in subjects}
    head, ident = _dl_ident(db, me_, [subjects[sid] for sid in sorted({t["subject_id"] for t in targets})])
    # each line's share of the person's overall: its score times its weight, over the weights of ALL the person's lines;
    # a line with no result counts as 0 (it is not dropped from the total, so the share never inflates -- 2026-11-06)
    total_w = defaultdict(float)
    for t in targets:
        total_w[t["subject_id"]] += t["weightage"] or 0
    rows = []
    for t in targets:
        s = subjects[t["subject_id"]]
        score, overall = t["score"], overalls.get(t["subject_id"])
        sv = score["value"] if score and score["value"] is not None else None
        first = t["approver_chain"][0]["approver_id"] if t["approver_chain"] else None
        w = t["weightage"]
        framework = {"Rate %d" % i: t["rate%d" % i] for i in range(1, 6)}
        framework.update({c: t[c.lower()] for c in ("Threshold", "Target", "Multiple", "Excellence")})
        rows.append(ident(s) + [
            period["name"], kpi_line_base(t["kpi_name"], t["focus"]), t["focus"] or "", t["category"] or "",
            t["description"] or "", t["unit"] or "", int(w) if w is not None and float(w).is_integer() else w,
            (t["method"] or "").capitalize()]
            + [framework[c] for c in fw_cols]
            + [approver_eid.get(first, "") if first and first != mgr_of.get(t["subject_id"]) else "",
               t["result"]["actual_value"] if t["result"] else None, t["effective_value"]]
            + ([round(sv, 2) if sv is not None and score["mechanism"] == "A" else None] if "A" in mechs else [])
            + ([round(sv, 1) if sv is not None and score["mechanism"] == "B" else None] if "B" in mechs else [])
            + [round((sv or 0) * (w or 0) / total_w[t["subject_id"]], 2) if total_w[t["subject_id"]]
               else None,
               "Yes" if t["locked"] else "No",
               "; ".join(c["approver_name"] for c in t["approver_chain"]) or "(unassigned)",
               None if not overall or overall["value"] is None else round(overall["value"], 2 if overall["mechanism"] == "A" else 1),
               overall["label"] if overall else ""])
    # the identity block carries Employee ID; the import's own headings follow it, Employee ID taken out
    own = [c for c in KPI_TARGETS_IMPORT_COLUMNS[1:] if c not in _KPI_FRAMEWORK_COLS and c != "Matrix manager ID"]
    header = (head + ["Cycle"] + own + fw_cols + ["Matrix manager ID", "Result: own value",
                                                      "Result: moderated value"]
              + (["Result: rating (of 5)"] if "A" in mechs else []) + (["Result: achievement %"] if "B" in mechs else [])
              + ["Result: weighted", "Result: locked", "Result: approvers", "Result: overall", "Result: overall label"])
    return _dl_book(
        db, me_, "KPI lines", header, rows,
        "One row per KPI line for the active period. The columns from KPI to Matrix manager ID are the KPI targets "
        "import's own: edit them and import the file back on Performance > Run > Import KPI targets. Columns headed "
        "Result: are only for reading and are ignored on import.",
        [("Cycle", "The period's name. The import refuses a row whose cycle is not the import's own."),
         ("Matrix manager ID", "Blank when the line manager moderates the line."),
         ("Result: rating (of 5)", "Mechanism A groups: the line's 1-5 rating."),
         ("Result: achievement %", "Mechanism B groups: the line's achievement."),
         ("Result: weighted", "The line's score times its weight, over the total weight of all the person's lines. "
                              "A line with no result counts as 0."),
         ("Result: overall", "Shown only once every one of the person's lines is locked.")], cyc=period)


_KPI_FRAMEWORK_COLS = ("Rate 1", "Rate 2", "Rate 3", "Rate 4", "Rate 5", "Threshold", "Target", "Multiple", "Excellence")


def _attach_clean_name(filename):
    """A file name safe to store and to show: control characters and double quotes dropped, a pasted Windows path cut to
    its last part (so no backslash survives), trailing spaces and dots stripped, at most PM_ATTACHMENT_NAME_MAX
    characters with the extension kept. Returns "" when nothing is left. Security test 3-03."""
    name = re.sub(r"[\x00-\x1f\x7f\u2028\u2029\"]", "", str(filename or ""))
    name = name.replace("\\", "/").rsplit("/", 1)[-1].strip().rstrip(". ").strip()
    if len(name) > PM_ATTACHMENT_NAME_MAX:
        ext = name.rsplit(".", 1)[1] if "." in name else ""
        if ext and len(ext) <= 10:
            name = name[:PM_ATTACHMENT_NAME_MAX - len(ext) - 1].rstrip(". ") + "." + ext
        else:
            name = name[:PM_ATTACHMENT_NAME_MAX]
    return name


def _kpi_attach_check(filename):
    """What a KPI line's uploaded file may be: (clean name, ".ext", None) when its extension is on the evidence list
    (EVIDENCE_ATTACH_EXTS), else (None, None, the refusal sentence). The extension is read from the CLEANED name, so
    "x.exe " and "x.EXE<NUL>.pdf" mean what the stored name says; the type served later comes from it too, never from
    what the uploader's browser declared."""
    name = _attach_clean_name(filename)
    ext = name.rsplit(".", 1)[1].lower() if "." in name else ""
    if ext in EVIDENCE_ATTACH_EXTS:
        return name, "." + ext, None
    if ext and re.fullmatch(r"[a-z0-9]{1,10}", ext):
        return None, None, "'.%s' files aren't allowed as evidence attachments -- use %s." % (ext, EVIDENCE_ATTACH_TYPES_TEXT)
    return None, None, "That file has no type (like .pdf), so it can't be attached -- use %s." % EVIDENCE_ATTACH_TYPES_TEXT


# --- An uploaded file must be what its name says (Chris, 2026-11-11, "Yes, fix all 3") ---------------------------------------
# EVIDENCE_ATTACH_EXTS is checked by the NAME only, so an HTML page named .pdf, a program named .docx or a Word file with
# macros would have been stored and handed to a reviewer. ONE pure function, called by every writer of those files after
# its extension and size checks and before the bytes are stored (a lint, tests/test_upload_content.py, holds that).
# Files already stored are never re-read. Reads at most 64 KB for text, 256 KB of one zip member and the member NAMES of an
# Office file; nothing else is unpacked.
_UP_OLE = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"
_UP_BINARY_SIGS = (b"%PDF-", b"PK\x03\x04", _UP_OLE, b"MZ", b"\x7fELF")
_UP_KIND_WORDS = {"pdf": "PDF", "png": "PNG image", "jpg": "JPG image", "jpeg": "JPG image", "gif": "GIF image",
                  "webp": "WebP image", "doc": "Word file", "docx": "Word file", "xls": "Excel file",
                  "xlsx": "Excel file", "ppt": "PowerPoint file", "pptx": "PowerPoint file", "txt": "text file",
                  "csv": "CSV file"}
_UP_OOXML_MAIN = {"docx": "word/document.xml", "xlsx": "xl/workbook.xml", "pptx": "ppt/presentation.xml"}
_UP_OLE_EXTS = frozenset({"doc", "xls", "ppt"})
_UP_IMAGE_EXTS = frozenset({"png", "jpg", "jpeg", "gif", "webp"})
_UP_ZIP_MEMBERS_MAX = 2000
_UP_CT_READ_MAX = 256 * 1024
_UP_TEXT_SCAN = 64 * 1024
_UP_MACRO_WHY = ("That file holds macros, so it can't be attached. Save it as a normal .docx, .xlsx or .pptx "
                 "(without macros) and attach that.")
_UP_PASSWORD_WHY = ("That file is password-protected, so reviewers couldn't open it. Remove the password, then attach "
                    "it again.")


def _up_mismatch_why(ext):
    return ("That file isn't the %s its name says. Save it again in that format and attach it."
            % _UP_KIND_WORDS.get(ext, "kind of file"))


def _up_ole_has_name(data, names):
    """True when one of `names` (UTF-16LE, as a compound file stores a directory entry's name) starts a 128-byte
    directory entry. Entries sit on 128-byte boundaries (sectors are 512 or 4096 bytes), so a sentence of the
    document's own text that happens to hold the word is not taken for it."""
    for nm in names:
        raw = nm.encode("utf-16-le")
        i = data.find(raw)
        while i >= 0:
            if i % 128 == 0:
                return True
            i = data.find(raw, i + 1)
    return False


def _up_is_image(data):
    return (data.startswith(b"\x89PNG\r\n\x1a\n") or data.startswith(b"\xff\xd8\xff") or data[:6] in (b"GIF87a", b"GIF89a")
            or (data[:4] == b"RIFF" and data[8:12] == b"WEBP"))


def _upload_content_refusal(ext, data):
    """None when `data` really is the kind of file its extension says (and holds no macros and no password), else the
    sentence to show the person. `ext` is the lower-case extension, with or without the dot; an extension that is not on
    EVIDENCE_ATTACH_EXTS is not this function's business (the caller refuses it first). Pure: never raises, never reads
    beyond the limits above."""
    ext = (ext or "").lstrip(".").lower()
    if ext not in EVIDENCE_ATTACH_EXTS:
        return None
    data = bytes(data or b"")
    bad = _up_mismatch_why(ext)
    try:
        if ext in ("docx", "xlsx", "pptx", "doc", "xls", "ppt") and data.startswith(_UP_OLE) \
                and _up_ole_has_name(data, ("EncryptionInfo", "EncryptedPackage")):
            return _UP_PASSWORD_WHY            # an encrypted Office file is a compound file, whatever it is named
        if ext == "pdf":
            return None if b"%PDF-" in data[:1024] else bad
        if ext in _UP_IMAGE_EXTS:
            # any of the five image kinds will do under any image name (a PNG screenshot saved as .jpg is common and harmless:
            # it is served as an image, nosniff, sandboxed inline); only bytes that are no image at all are refused
            return None if _up_is_image(data) else bad
        if ext in ("txt", "csv"):
            if b"\x00" in data[:_UP_TEXT_SCAN] or data.startswith(_UP_BINARY_SIGS):
                return bad
            return None
        if ext in _UP_OLE_EXTS:
            if not data.startswith(_UP_OLE):
                return bad
            if _up_ole_has_name(data, ("_VBA_PROJECT", "Macros")):
                return _UP_MACRO_WHY
            return None
        main = _UP_OOXML_MAIN.get(ext)
        if main:
            with zipfile.ZipFile(io.BytesIO(data)) as zf:
                infos = zf.infolist()
                if len(infos) > _UP_ZIP_MEMBERS_MAX:
                    return bad
                names = [zi.filename for zi in infos]
                if "[Content_Types].xml" not in names or main not in names:
                    return bad
                if any(n.replace("\\", "/").rsplit("/", 1)[-1].lower() == "vbaproject.bin" for n in names):
                    return _UP_MACRO_WHY
                with zf.open("[Content_Types].xml") as fh:
                    ct = fh.read(_UP_CT_READ_MAX)
                if b"macroenabled" in ct.lower():
                    return _UP_MACRO_WHY
            return None
    except Exception:  # noqa: BLE001 -- a corrupt or hostile file is just "not that kind of file"
        return bad
    return None


def pm_store_attachment(cycle_id, kpi_target_id, ext, data, content_type=None):
    """Persist one KPI attachment's bytes -- Blob if configured, else local
    disk (today's behavior, byte-for-byte unchanged). Returns
    (stored_path, storage_backend) to insert into pm_attachments. Never
    dual-writes: Blob-only once blob_storage.get_client() is non-None;
    local disk stays reachable exactly as before whenever Blob isn't
    configured (e.g. staging today, before RBAC is granted)."""
    client = blob_storage.get_client()
    if client is not None:
        name = blob_storage.blob_name(cycle_id, kpi_target_id, ext)
        blob_storage.upload(name, data, content_type=content_type)
        return name, "blob"
    safe_name = f"{uuid.uuid4().hex}{ext}"
    target_dir = os.path.join(PM_UPLOAD_DIR, str(cycle_id), str(kpi_target_id))
    os.makedirs(target_dir, exist_ok=True)
    stored_path = os.path.join(target_dir, safe_name)
    with open(stored_path, "wb") as out:
        out.write(data)
    return stored_path, "local"


def pm_read_attachment(att):
    """Bytes for one pm_attachments row, dispatching on the ROW'S OWN
    storage_backend -- not current config -- so historical local rows keep
    working after a future switch to Blob-primary. None if missing (local
    file deleted, or blob not found) so the caller aborts(404) exactly as
    today; a genuine BlobStorageError propagates uncaught, same as an
    unhandled local-disk IOError today."""
    if att["storage_backend"] == "blob":
        client = blob_storage.get_client()
        if client is None:
            raise blob_storage.BlobStorageError(
                "pm_attachments row is on blob but PM_BLOB_ACCOUNT_NAME isn't set")
        return blob_storage.download(att["stored_path"])
    if not os.path.isfile(att["stored_path"]):
        return None
    with open(att["stored_path"], "rb") as f:
        return f.read()


def pm_can_view(u, target):
    """Visibility for a KPI target row: the subject themselves, anyone in
    its approver chain, or a BGHR/admin scoped to the row's BG/company --
    the confirmed deliberate widening beyond 360's anonymized-aggregate
    model (employee/manager/HOD/BGHR-admin all see raw named results)."""
    if u["id"] == target["subject_id"]:
        return True
    if is_admin(u):
        return can_access(u, target["business_group"], target["company"])
    return get_db().execute(
        "SELECT 1 FROM pm_kpi_target_approvers WHERE kpi_target_id=? AND approver_id=?",
        (target["id"], u["id"])).fetchone() is not None


@app.route("/performance")
@login_required
def performance_my_view():
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    # Period history (decision #53): default to the active period ("Year End"
    # once HY2 is running), but let this person switch to one of their OWN past
    # periods read-only via ?period=<id>. Validated against pm_user_periods()
    # so the param can only ever name a period they hold targets in. Every
    # query below then scopes to `period` (the VIEWED one), so switching also
    # brings that period's own remarks/AI quota with it.
    period, periods, is_active_period = pm_viewed_period(db, u)
    if period and not is_active_period:
        # A past half: its final band (once released) and talent status are the record, never its KPI table, which
        # shows results that differ from the calibrated outcome (Chris, 2026-10-08). The history panel has it.
        return redirect(url_for("dashboard", record=period["id"]))
    targets = []
    provisional = None
    overall_remark = None
    manager_remarks = []
    all_locked = False
    if period:
        # Only AGREED targets belong on the results page. A KPI still going
        # through the setting journey (draft / proposed / returned) lives on
        # /performance/setting until its chain approves it -- see
        # pm_result_entry_open(). Admin-imported and pre-existing rows are
        # 'approved' by default, so this filter is a no-op for them.
        targets = [dict(t) for t in db.execute(
            "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
            "AND status='approved' ORDER BY " + PM_LINE_ORDER,
            (period["id"], u["id"])).fetchall()]
        remark_row = db.execute(
            "SELECT * FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=?",
            (period["id"], u["id"])).fetchone()
        overall_remark = dict(remark_row) if remark_row else None
        # EVERY approver's remark on THIS employee's own period, attributed.
        # Matrix approval means a person can be reviewed by more than one
        # manager and each now writes their own, so the employee sees each
        # with a name on it rather than whichever happened to be saved last.
        # Scoped to the caller's own id, leak-proof by construction; and the
        # template holds it back until all_locked, never merely because a row
        # exists -- there is no draft column here, so a half-written sentence
        # must not surface early (same rule as the justification icon).
        manager_remarks = [dict(r) for r in db.execute(
            "SELECT r.remark, r.submitted_at, u.full_name AS author "
            "FROM pm_manager_remarks r LEFT JOIN users u ON u.id = r.submitted_by "
            "WHERE r.cycle_id=? AND r.subject_id=? AND TRIM(COALESCE(r.remark,'')) != '' "
            "ORDER BY r.submitted_at", (period["id"], u["id"])).fetchall()]
    ai_enabled = ai_on("ai_pm")
    remark_ai_remaining = None
    remark_ai_reset_seconds = None
    if targets:
        # include_drafts=True: this is the employee's own data -- their
        # inputs must pre-fill from an auto-saved draft, and the mandatory-
        # fill gate must treat a drafted-but-unretyped row as "filled".
        attach_pm_chains(db, targets, include_drafts=True)
        bu_names = pm_bu_level_names(db, u, period["id"])
        for t in targets:
            # A PAST period is read-only no matter what the line's own draft
            # state says -- pm_can_self_edit() alone would happily re-open a
            # never-submitted line from a closed half. Everything downstream
            # (any_editable -> Submit button + remark textarea, the per-row
            # inputs/autosave/AI widgets) keys off can_edit, so this one
            # clause makes the whole page read-only. The real enforcement is
            # the server-side guard on the write routes, not this.
            # A BU-level KPI is HR's figure to enter, not this person's, so it
            # is read-only whatever else is true -- and it is excluded from the
            # mandatory-fill gate, which would otherwise demand a number the
            # employee has no way of knowing and block their whole submission.
            t["bu_level"] = " ".join((t["kpi_name"] or "").lower().split()) in bu_names
            t["can_edit"] = (pm_can_self_edit(t) and is_active_period
                             and not t["bu_level"])
            if ai_enabled:
                _used, t["ai_remaining"], t["ai_reset_seconds"] = _pm_ai_draft_quota(
                    db, u["id"], f"note:{t['id']}")
        pm_score_targets(db, targets)
        provisional = pm_overall_for_targets(db, targets, require_locked=False)
        all_locked = all(t["locked"] for t in targets)
        # Per-line self-rated score alongside the existing moderated 'score'
        # (which reads effective_value) -- same shallow-copy-and-rescore
        # trick already used for the team-member page's aggregate, just
        # zipped back per-line here instead of only aggregated. Always the
        # RAW self-submission, never effective_value, so "self-rated" means
        # the same thing everywhere on this page and on the team page.
        self_targets = [dict(t) for t in targets]
        for st in self_targets:
            st["effective_value"] = st["result"]["actual_value"] if st.get("result") else None
        pm_score_targets(db, self_targets)
        for t, st in zip(targets, self_targets):
            t["self_score"] = st["score"]
    if period and ai_enabled:
        _used, remark_ai_remaining, remark_ai_reset_seconds = _pm_ai_draft_quota(
            db, u["id"], f"overall_remark:{period['id']}")
    return render_template("performance_my.html", period=period, targets=targets,
                          periods=periods, is_active_period=is_active_period,
                          provisional=provisional, label_names=PM_LABEL_NAMES,
                          overall_remark=overall_remark, manager_remarks=manager_remarks,
                          all_locked=all_locked, ai_enabled=ai_enabled,
                          ai_limit=AI_DRAFT_DAILY_LIMIT,
                          remark_ai_remaining=remark_ai_remaining,
                          remark_ai_reset_seconds=remark_ai_reset_seconds)


@app.route("/performance/kpi/<int:kpi_target_id>/autosave", methods=["POST"])
@login_required
def performance_kpi_autosave(kpi_target_id):
    """Background draft save for one KPI line -- result value + note (once a
    value exists; note alone has nowhere to live, actual_value is NOT NULL)
    and/or an evidence attachment (independent of whether a value exists
    yet, pm_attachments has no FK dependency on pm_kpi_results). Called from
    the page's own debounced/immediate-on-file-pick JS, not a form
    navigation -- JSON in, JSON out.

    Always writes draft=1. A row already promoted to draft=0 by a real
    Submit can never reach this far -- pm_can_self_edit()'s 409 guard below
    blocks it first, since Submit is now a one-way, permanent lock (see
    pm_can_self_edit()'s own docstring) -- so this route's own writes only
    ever touch a line still on its way toward that first real Submit,
    exactly the "auto-save is a private draft, Submit is the real action"
    model."""
    u = current_user()
    db = get_db()
    target = db.execute("SELECT * FROM pm_kpi_targets WHERE id=? AND subject_id=?",
                        (kpi_target_id, u["id"])).fetchone()
    if target and " ".join((target["kpi_name"] or "").lower().split()) in pm_bu_level_names(db, u, target["cycle_id"]):
        # HR's figure, not theirs -- refuse rather than quietly storing a draft
        # the Fill BU KPI run would later overwrite anyway.
        return jsonify(ok=False, error="Group People sets this KPI, not you."), 409
    if not target:
        abort(404)
    target = dict(target)
    # Past periods are read-only. The fetch above is scoped to the caller but
    # NOT to a period, and pm_can_self_edit() returns True for any line with
    # no result row -- so without this a never-submitted line from a closed
    # half stays writable once the My PM period switcher can surface it.
    if target["cycle_id"] != active_pm_period_id(db):
        return jsonify(ok=False, error="This period is closed to edits."), 409
    # Own data -- include_drafts=True is load-bearing here, not a
    # preference: it's what lets the UPDATE-vs-INSERT branches below see an
    # existing draft row instead of trying to INSERT a second one over the
    # UNIQUE kpi_target_id constraint.
    attach_pm_chains(db, [target], include_drafts=True)
    if not pm_can_self_edit(target):
        return jsonify({"ok": False, "reason": "locked"}), 409
    _t, _err = _store_text((request.form.get("note", "") or "").strip())
    if _err:   # nothing is saved, the number included: the screen shows why (security test 4-03)
        return jsonify({"ok": False, "reason": "screened", "error": _err}), 400

    value_saved = attachment_saved = False
    filename = None

    if "actual_value" in request.form:
        raw = (request.form.get("actual_value", "") or "").strip()
        if raw:
            try:
                actual_value = float(raw)
            except ValueError:
                return jsonify({"ok": False, "reason": "invalid_number"}), 400
            # float() happily accepts 'inf'/'Infinity'/'1e400'/'nan', and the
            # result box is a free-text input, so these are typeable. Neither
            # survives contact with the rest of the app: inf raises inside the
            # `commas` display filter (500 on this page AND the approver's
            # review page, unrecoverable once Submit has locked the row), and
            # nan is stored by SQLite as NULL, violating actual_value's NOT
            # NULL constraint (500 here and on submit). Reject at the door,
            # with the same 400 the route already returns for 'abc'. The
            # /performance/setting number routes have always guarded this;
            # result entry never did.
            if not math.isfinite(actual_value):
                return jsonify({"ok": False, "reason": "invalid_number"}), 400
            _rl = _rating_line_error(target, actual_value)   # a 1-5 rating line takes a whole rating only (2026-10-30)
            if _rl:
                return jsonify({"ok": False, "reason": "bad_rating", "error": _rl}), 400
            # Absent is not empty -- see performance_kpi_submit_all(). Posting only
            # a number used to blank an existing note. Still a draft here, so it is
            # recoverable, but a conversation posts exactly one field at a time.
            note_given = "note" in request.form
            note = (request.form.get("note", "") or "").strip() or None
            if target["result"]:
                if note_given:
                    db.execute("UPDATE pm_kpi_results SET actual_value=?, note=?, "
                               "submitted_at=datetime('now'), submitted_by=?, draft=1 "
                               "WHERE kpi_target_id=?",
                               (actual_value, note, u["id"], kpi_target_id))
                else:
                    db.execute("UPDATE pm_kpi_results SET actual_value=?, "
                               "submitted_at=datetime('now'), submitted_by=?, draft=1 "
                               "WHERE kpi_target_id=?", (actual_value, u["id"], kpi_target_id))
            else:
                db.execute("INSERT INTO pm_kpi_results(kpi_target_id, actual_value, note, "
                           "submitted_by, draft) VALUES (?,?,?,?,1)",
                           (kpi_target_id, actual_value, note, u["id"]))
            value_saved = True

    f = request.files.get("file")
    if f and f.filename:
        clean_name, ext, why = _kpi_attach_check(f.filename)
        if why:
            return jsonify({"ok": False, "reason": "bad_file", "message": why}), 400
        content_type = _ATTACH_SERVE_TYPES.get(ext[1:], "application/octet-stream")   # by extension, never the uploader's
        data = f.read()
        if len(data) > PM_ATTACHMENT_MAX_BYTES:
            return jsonify({"ok": False, "reason": "bad_file",
                           "message": "That file is over the 10MB attachment limit."}), 400
        why = _upload_content_refusal(ext, data)   # what its name says, no macros, no password (2026-11-11)
        if why:
            return jsonify({"ok": False, "reason": "bad_file", "message": why}), 400
        stored_path, storage_backend = pm_store_attachment(
            target["cycle_id"], kpi_target_id, ext, data, content_type=content_type)
        # (a row an admin removed is hidden from target["attachment"] but still holds the one slot: a new upload takes it over)
        if target["attachment"] or db.execute("SELECT 1 FROM pm_attachments WHERE kpi_target_id=?", (kpi_target_id,)).fetchone():
            db.execute(
                "UPDATE pm_attachments SET filename=?, stored_path=?, storage_backend=?, "
                "content_type=?, size_bytes=?, uploaded_by=?, uploaded_at=datetime('now'), draft=1, "
                "removed_at=NULL, removed_by=NULL, remove_reason=NULL "
                "WHERE kpi_target_id=?",
                (clean_name, stored_path, storage_backend, content_type, len(data), u["id"], kpi_target_id))
        else:
            db.execute(
                "INSERT INTO pm_attachments(kpi_target_id, filename, stored_path, storage_backend, "
                "content_type, size_bytes, uploaded_by, draft) VALUES (?,?,?,?,?,?,?,1)",
                (kpi_target_id, clean_name, stored_path, storage_backend, content_type, len(data), u["id"]))
        attachment_saved = True
        filename = clean_name

    db.commit()

    final_rating = None
    if value_saved:
        period_targets = [dict(t) for t in db.execute(
            "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=?",
            (target["cycle_id"], u["id"])).fetchall()]
        attach_pm_chains(db, period_targets, include_drafts=True)
        pm_score_targets(db, period_targets)
        provisional = pm_overall_for_targets(db, period_targets, require_locked=False)
        all_scored = all(t.get("score") for t in period_targets)
        if all_scored and provisional and provisional["label"] is not None:
            final_rating = {
                "value": (round(provisional["value"], 2) if provisional["mechanism"] == "A"
                         else round(provisional["value"], 1)),
                "mechanism": provisional["mechanism"], "label": provisional["label"],
                "label_name": PM_LABEL_NAMES[provisional["label"]]}

    return jsonify({"ok": True, "value_saved": value_saved, "attachment_saved": attachment_saved,
                    "filename": filename, "final_rating": final_rating})


@app.route("/performance/overall-remark/autosave", methods=["POST"])
@login_required
def performance_overall_remark_autosave():
    """Background draft save for the one optional period-level remark --
    always writes draft=1, same "editing reverts to private draft" rule as
    performance_kpi_autosave(). Locked once every KPI line for this period
    is no longer pm_can_self_edit(), mirroring why the Submit button itself
    disappears at that point (any_editable)."""
    u = current_user()
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    targets = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=?",
        (period["id"], u["id"])).fetchall()]
    attach_pm_chains(db, targets, include_drafts=True)
    if targets and not any(pm_can_self_edit(t) for t in targets):
        return jsonify({"ok": False, "reason": "locked"}), 409
    if pm_review_locked(db, u["id"], period["id"]):   # confirmed: a line added since is open, the remark never is (2026-11-06)
        return jsonify({"ok": False, "reason": "locked"}), 409
    remark = (request.form.get("remark", "") or "").strip()
    _t, _err = _store_text(remark)
    if _err:
        return jsonify({"ok": False, "reason": "screened", "error": _err}), 400
    existing = db.execute(
        "SELECT id FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=?",
        (period["id"], u["id"])).fetchone()
    if existing:
        db.execute("UPDATE pm_overall_remarks SET remark=?, submitted_at=datetime('now'), "
                   "submitted_by=?, draft=1 WHERE id=?", (remark, u["id"], existing["id"]))
    elif remark:
        db.execute("INSERT INTO pm_overall_remarks(cycle_id, subject_id, remark, submitted_by, draft) "
                   "VALUES (?,?,?,?,1)", (period["id"], u["id"], remark, u["id"]))
    db.commit()
    return jsonify({"ok": True})


@app.route("/performance/submit-all", methods=["POST"])
@login_required
def performance_kpi_submit_all():
    """One-shot bulk submit for the table-format My Performance page: every
    editable (not-yet-submitted) KPI must have a filled-in actual_value_<id>
    field, or the whole submission is rejected -- a blank on an editable
    row is a validation error, not a silent skip. All-or-nothing like
    admin_import_kpi_targets(): every row is validated BEFORE anything is
    written, and the whole batch is rejected with a per-row error list if
    any row is invalid -- never a partial commit where some rows land and
    others don't."""
    u = current_user()
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    targets = [dict(t) for t in db.execute(
        "SELECT t.* FROM pm_kpi_targets t WHERE t.cycle_id=? AND t.subject_id=?",
        (period["id"], u["id"])).fetchall()]
    # BU-level lines are HR's to fill, so they are dropped from the batch here
    # rather than merely hidden in the template. Two things depend on this: the
    # mandatory-fill check below must not demand a value nobody has, and a
    # crafted POST naming a BU-level target must not be able to set one.
    _bu = pm_bu_level_names(db, u, period["id"])
    targets = [t for t in targets
               if " ".join((t["kpi_name"] or "").lower().split()) not in _bu]
    # include_drafts=True: load-bearing, not a preference -- an existing
    # draft row (from auto-save) must be visible here so the UPDATE branch
    # below fires instead of an INSERT that would violate the UNIQUE
    # kpi_target_id constraint.
    attach_pm_chains(db, targets, include_drafts=True)
    targets = [t for t in targets if pm_can_self_edit(t)]
    # a CONFIRMED check-in (2026-11-06): only a line Group People added since is theirs to submit, saved as a draft here and
    # promoted by the one shared function (_review_do_confirm_added) after the same per-line gates; their overall remark,
    # session and other lines are not touched
    locked_now = pm_review_locked(db, u["id"], period["id"])
    if locked_now:
        _open = pm_added_open_ids(db, u["id"], period["id"])
        targets = [t for t in targets if t["id"] in _open]
    if not targets:
        flash("Nothing to submit.", "error")
        return redirect(url_for("performance_my_view"))

    errors, valid = [], []
    aggregate_bytes = 0
    for target in targets:
        raw = (request.form.get(f"actual_value_{target['id']}", "") or "").strip()
        if not raw:
            errors.append(f"'{target['kpi_name']}': a result is required before you can submit.")
            continue
        try:
            actual_value = float(raw)
        except ValueError:
            errors.append(f"'{target['kpi_name']}': enter a valid number.")
            continue
        # inf/nan parse fine but poison everything downstream -- same reason
        # as the autosave route's own guard; see performance_kpi_autosave().
        if not math.isfinite(actual_value):
            errors.append(f"'{target['kpi_name']}': enter a valid number.")
            continue
        _rl = _rating_line_error(target, actual_value)   # a 1-5 rating line takes a whole rating only (2026-10-30)
        if _rl:
            errors.append(f"'{target['kpi_name']}': {_rl}")
            continue
        note = (request.form.get(f"note_{target['id']}", "") or "").strip() or None
        _t, _err = _store_text(note or "")
        if _err:
            errors.append(f"'{target['kpi_name']}': {_err}")
            continue
        file_bytes, filename, content_type, ext = None, None, None, None
        f = request.files.get(f"file_{target['id']}")
        if f and f.filename:
            filename, ext, why = _kpi_attach_check(f.filename)
            if why:
                errors.append(f"'{target['kpi_name']}': {why}")
                continue
            file_bytes = f.read()  # buffered once here, reused below -- FileStorage.read() is single-use
            if len(file_bytes) > PM_ATTACHMENT_MAX_BYTES:
                errors.append(f"'{target['kpi_name']}': that file is over the 10MB attachment limit.")
                continue
            why = _upload_content_refusal(ext, file_bytes)   # what its name says, no macros, no password (2026-11-11)
            if why:
                errors.append(f"'{target['kpi_name']}': {why}")
                continue
            aggregate_bytes += len(file_bytes)
            content_type = _ATTACH_SERVE_TYPES.get(ext[1:], "application/octet-stream")   # by extension
        valid.append({"target": target, "actual_value": actual_value, "note": note,
                      "file_bytes": file_bytes, "filename": filename,
                      "content_type": content_type, "ext": ext})

    if not valid and not errors:
        flash("Nothing to submit.", "error")
        return redirect(url_for("performance_my_view"))
    _t, _err = _store_text((request.form.get("overall_remark", "") or "").strip())
    if _err:
        errors.append("Overall remark: " + _err)
    if aggregate_bytes > PM_ATTACHMENT_AGGREGATE_MAX_BYTES:
        errors.append(f"Attachments across this submission total over "
                      f"{PM_ATTACHMENT_AGGREGATE_MAX_BYTES // (1024 * 1024)}MB combined -- "
                      f"remove or shrink one and try again.")
    if errors:
        flash(f"Submission rejected — no changes applied. Fix these {len(errors)} issue(s):", "error")
        for e in errors[:50]:
            flash(e, "error")
        return redirect(url_for("performance_my_view"))

    for row in valid:
        target = row["target"]
        # draft=0 explicitly: this is the promotion moment. A row that was
        # sitting as draft=1 (from auto-save) must become visible to the
        # approver now, not stay hidden.
        if target["result"]:
            db.execute("UPDATE pm_kpi_results SET actual_value=?, note=?, "
                       "submitted_at=datetime('now'), submitted_by=?, draft=? WHERE kpi_target_id=?",
                       (row["actual_value"], row["note"], u["id"], 1 if locked_now else 0, target["id"]))
        else:
            db.execute("INSERT INTO pm_kpi_results(kpi_target_id, actual_value, note, submitted_by, draft) "
                       "VALUES (?,?,?,?,?)", (target["id"], row["actual_value"], row["note"], u["id"],
                                              1 if locked_now else 0))
        if row["file_bytes"] is not None:
            stored_path, storage_backend = pm_store_attachment(
                period["id"], target["id"], row["ext"], row["file_bytes"],
                content_type=row["content_type"])
            if target["attachment"] or db.execute("SELECT 1 FROM pm_attachments WHERE kpi_target_id=?", (target["id"],)).fetchone():
                db.execute(
                    "UPDATE pm_attachments SET filename=?, stored_path=?, storage_backend=?, "
                    "content_type=?, size_bytes=?, uploaded_by=?, uploaded_at=datetime('now'), draft=0, "
                    "removed_at=NULL, removed_by=NULL, remove_reason=NULL "
                    "WHERE kpi_target_id=?",
                    (row["filename"], stored_path, storage_backend, row["content_type"],
                     len(row["file_bytes"]), u["id"], target["id"]))
            else:
                db.execute(
                    "INSERT INTO pm_attachments(kpi_target_id, filename, stored_path, storage_backend, "
                    "content_type, size_bytes, uploaded_by, draft) VALUES (?,?,?,?,?,?,?,0)",
                    (target["id"], row["filename"], stored_path, storage_backend,
                     row["content_type"], len(row["file_bytes"]), u["id"]))
        elif target["attachment"] and target["attachment"]["draft"]:
            # No new file re-selected in this POST (browsers can't pre-fill
            # <input type=file>, so an earlier auto-saved attachment isn't
            # resendable) -- promote the existing draft attachment on its
            # own so it doesn't stay invisible forever once the result row
            # itself has been submitted.
            db.execute("UPDATE pm_attachments SET draft=0 WHERE kpi_target_id=?", (target["id"],))

    if not locked_now:   # a confirmed check-in's remark is final: a line added since never reopens it (2026-11-06)
        # Overall remark promotes in this SAME transaction, alongside the KPI
        # lines -- one Submit action, one commit, matching how the remark's own
        # autosave route always writes draft=1 ("editing reverts to private").
        # ABSENT IS NOT EMPTY. This read the field unconditionally, so a POST that
        # simply did not carry overall_remark wrote '' over the employee's own words
        # AND set draft=0 -- past pm_can_self_edit(), so they could not put it back.
        # The INSERT branch below was already guarded (`elif remark:`); the UPDATE was
        # not, so the damage was permanent and silent and only ever hit somebody who
        # had written something.
        #
        # Latent until now: the textarea lives inside this same form under
        # {% if any_editable %}, so the page always sent it. Phase C's conversation
        # posts one answer at a time, which is exactly what would have made it live.
        # Absent means UNCHANGED; empty string means CLEARED; they are different.
        remark_given = "overall_remark" in request.form
        remark = (request.form.get("overall_remark", "") or "").strip()
        existing_remark = db.execute(
            "SELECT id FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=?",
            (period["id"], u["id"])).fetchone()
        if existing_remark and remark_given:
            db.execute("UPDATE pm_overall_remarks SET remark=?, submitted_at=datetime('now'), "
                       "submitted_by=?, draft=0 WHERE id=?", (remark, u["id"], existing_remark["id"]))
        elif existing_remark:
            # Not sent: promote what is already there, do not rewrite it.
            db.execute("UPDATE pm_overall_remarks SET submitted_at=datetime('now'), "
                       "submitted_by=?, draft=0 WHERE id=?", (u["id"], existing_remark["id"]))
        elif remark:
            db.execute("INSERT INTO pm_overall_remarks(cycle_id, subject_id, remark, submitted_by, draft) "
                       "VALUES (?,?,?,?,0)", (period["id"], u["id"], remark, u["id"]))

    if locked_now:
        db.commit()
        ok_, err_ = _review_do_confirm_added(db, u, period["id"])   # the shared promote, with the per-line gates
        if not ok_:
            flash("Saved, but not submitted yet: %s." % err_.rstrip("."), "error")
            return redirect(url_for("performance_my_view"))
    if pm_review_locked(db, u["id"], period["id"]):   # every line in: HR's reopen is redone (2026-10-16)
        _reopen_close(db, u["id"], ["pm_self"], actor_id=u["id"])
        _late_close(db, u["id"], "pm_results", "used")   # a late pass is used (2026-10-31)
    _rating_record_refresh(db, period["id"], [u["id"]], "pm_self_submit", u["id"])   # the rating record
    db.commit()
    for row in valid:
        log_activity(db, u["id"], "pm_kpi_submit",
                     f"'{row['target']['kpi_name']}': {row['actual_value']}")
    flash(f"Submitted {len(valid)} result(s).", "ok")
    return redirect(url_for("performance_my_view"))


@app.route("/performance/kpi/<int:kpi_target_id>/attachment")
@login_required
def performance_kpi_attachment_download(kpi_target_id):
    """Serve a KPI line's attachment -- auth-checked here (pm_can_view()),
    then streamed from local disk, mirroring _csv_response()'s
    auth-then-Response idiom. Never a static/ URL, so this route is the only
    path to the file's bytes."""
    u = current_user()
    db = get_db()
    target = db.execute("SELECT * FROM pm_kpi_targets WHERE id=?", (kpi_target_id,)).fetchone()
    if not target or not pm_can_view(u, target):
        abort(403)
    att = db.execute("SELECT * FROM pm_attachments WHERE kpi_target_id=? AND removed_at IS NULL", (kpi_target_id,)).fetchone()
    if not att:
        abort(404)
    if att["draft"] and u["id"] not in (target["subject_id"], att["uploaded_by"]):
        abort(403)   # a draft file is private to the person who attached it, whoever else is in the chain (1b-04)
    _out = _one_person_report_refusal(db, u, target["subject_id"], ("pm",), target["cycle_id"])   # out means out (1b-03)
    if _out:
        return Response(_out, 403, mimetype="text/plain")
    data = pm_read_attachment(att)
    if data is None:
        abort(404)
    # the type is the file name's extension, never what the uploader declared, and an unknown one downloads as a plain
    # stream; the name goes through _attachment_header like every download (security test 3-03). Files stored before
    # that stay downloadable the same way. ?disp=inline previews a PDF, image or plain text (the preview box, static/file_preview.js, asks for it
    # from the calibration report); any other extension, and the default, downloads.
    ext = _attach_ext(att["filename"])
    disp = "inline" if request.args.get("disp") == "inline" and ext in _ATTACH_INLINE_EXTS else "attachment"
    return Response(data, mimetype=_ATTACH_SERVE_TYPES.get(ext, "application/octet-stream"),
                    headers=_file_response_headers(att["filename"], ext, disp))


def _pm_team_mine(u, ts_all):
    """CHGP's matrix-split case: an approver may own only a subset of this
    person's KPI lines (different approvers per KPI subset), so only the
    lines THIS viewer is actually in the chain for -- never a teammate's
    unrelated subset. Shared by the overview and the drill-down so both
    always agree on exactly which lines a given manager may see."""
    return [t for t in ts_all if any(c["approver_id"] == u["id"] for c in t["approver_chain"])]


def _pm_approver_subject_ids(db, u, cycle_id):
    """Everyone this person approves at least one KPI line for this period --
    the approver-chain-driven population (A4), a strict superset of manager_id
    scoping. Shared by the Performance team view and the IDP team view so a
    manager's list of people is the same in both modules by construction."""
    if _leader_unit_out(u, db):   # left out of the cycle: they moderate nobody (2026-10-21)
        return []
    if _chair_pm_hidden(db, u):   # the Executive Chairman's Moderate tick is off: his Team tab is the 360 only (2026-10-29)
        return []
    return [r["subject_id"] for r in db.execute(
        "SELECT DISTINCT t.subject_id FROM pm_kpi_targets t "
        "JOIN pm_kpi_target_approvers a ON a.kpi_target_id = t.id "
        "JOIN users su ON su.id = t.subject_id "
        "WHERE t.cycle_id=? AND a.approver_id=? AND NOT " + unit_out_sql("su"), (cycle_id, u["id"])).fetchall()]


def _pm_review_subject_ids(db, u, cycle_id):
    """Whose KPI RESULTS this person reviews and moderates: _pm_approver_subject_ids, less anyone who doesn't take part
    in Performance this cycle -- their user role lacks it, an admin took them out, below the minimum grade (Chris,
    2026-10-30: out means out; a report taken out after they submitted leaves the list with their work). The KPI lists
    and writers use this. The Career Plan's review (_idp_review_subject_ids) keeps the ungated list: Performance is not
    its gate."""
    ids = _pm_approver_subject_ids(db, u, cycle_id) or []
    if not ids:
        return []
    ok = {r[0] for r in db.execute("SELECT id FROM users WHERE id IN (%s) AND %s"
                                   % (",".join("?" * len(ids)), participant_sql("", "pm")), ids)}
    return [i for i in ids if i in ok]


def _idp_review_subject_ids(db, u, cycle_id):
    """Whose Career Plan this person reviews: everyone they approve a KPI line for (the approver chain the Performance
    team view lists), then their own direct reports who write a plan -- including those with no KPI line to carry them
    there, someone not confirmed yet or taking part with no targets (Chris, 2026-10-19: "all employees should be able to
    get access to and fill in the IDP"). Never the Executive Chairman's direct reports while his Career Plan tick is off:
    nobody reviews them, whatever path would reach them (a KPI line's approver included, 2026-11-06)."""
    if _chair_team_adjust(db, u["id"], "plan")[0]:   # the Executive Chairman's Career Plan tick is off (2026-10-29)
        return []
    nobody = _idp_chair_unreviewed_ids(db)
    ids = [i for i in (_pm_approver_subject_ids(db, u, cycle_id) or []) if i not in nobody]
    seen = set(ids)
    mids = _cycle_review_managers(db, u["id"], "plan")   # one level up past a left-out line manager (2026-10-21)
    if not mids:
        return ids
    for r in db.execute("SELECT id FROM users WHERE manager_id IN (%s) AND role!='admin' AND COALESCE(is_demo,0)=0 "
                        "AND %s%s ORDER BY id" % (",".join("?" * len(mids)), idp_participant_sql(),
                                                  _idp_chair_unreviewed_sql(db, "users")), mids):
        if r[0] not in seen:
            ids.append(r[0])
            seen.add(r[0])
    return ids


def _idp_is_reviewer_of(db, u, subject_id, cycle_id):
    """True if this person reviews that subject's Career Plan (_idp_review_subject_ids for one person): an approver of
    any of their KPI lines, or their line manager while they write a plan. Re-derived server-side, never trusted. Nobody
    does for the Executive Chairman's direct reports while his Career Plan tick is off (2026-11-06)."""
    if _chair_team_adjust(db, u["id"], "plan")[0]:   # the Executive Chairman's Career Plan tick is off (2026-10-29)
        return False
    if _idp_chair_unreviewed(db, subject_id):   # nobody reviews his direct reports, KPI approver or not (2026-11-06)
        return False
    if _pm_is_approver_of(db, u, subject_id, cycle_id):
        return True
    mids = _cycle_review_managers(db, u["id"], "plan")   # one level up past a left-out line manager (2026-10-21)
    return bool(mids) and db.execute(
        "SELECT 1 FROM users WHERE id=? AND manager_id IN (%s) AND role!='admin' AND %s"
        % (",".join("?" * len(mids)), idp_participant_sql()), [subject_id] + mids).fetchone() is not None


def _idp_lm_has_plans(db, u):
    """Does this person line-manage anyone who writes a Career Plan? (The Team view's IDP review is theirs then, KPI
    approver or not.) Not the Executive Chairman while his Career Plan tick is off, and nobody for his direct reports
    (2026-11-06)."""
    drop, _extra = _chair_team_adjust(db, u["id"], "plan")   # the Executive Chairman (2026-10-29)
    mids = [] if drop else [u["id"]]
    if not mids:
        return False
    return db.execute("SELECT 1 FROM users WHERE manager_id IN (%s) AND role!='admin' AND COALESCE(is_demo,0)=0 AND "
                      % ",".join("?" * len(mids)) + idp_participant_sql() + _idp_chair_unreviewed_sql(db, "users")
                      + " LIMIT 1", mids).fetchone() is not None


def _pm_is_approver_of(db, u, subject_id, cycle_id):
    """True if this person approves any of that subject's KPI lines. The auth
    check behind every IDP team page -- re-derived server-side, never trusted
    from the URL."""
    if _leader_unit_out(u, db):   # left out of the cycle (2026-10-21)
        return False
    if _chair_pm_hidden(db, u):   # the Executive Chairman's Moderate tick is off (2026-10-29)
        return False
    return db.execute(
        "SELECT 1 FROM pm_kpi_targets t "
        "JOIN pm_kpi_target_approvers a ON a.kpi_target_id = t.id "
        "JOIN users su ON su.id = t.subject_id "
        "WHERE t.cycle_id=? AND t.subject_id=? AND a.approver_id=? AND NOT " + unit_out_sql("su") + " LIMIT 1",
        (cycle_id, subject_id, u["id"])).fetchone() is not None


def _pm_line_actionable_by(t, me_id):
    """True if `me_id` may currently confirm/adjust this KPI line:
    submitted, not locked, and it's their turn. Single source of truth for
    performance_kpi_moderate_autosave()'s auth check, the pm_moderate_cell
    template macro's own branch (registered below as the Jinja global
    'actionable_by'), and the Justification AI-draft route's auth check --
    so the three can never quietly disagree. A line the line manager assessed on the person's behalf (no result of
    theirs, 2026-10-26) goes on to a later approver in its chain like any moderated line."""
    return (bool(t["result"]) or bool(t.get("on_behalf"))) and not t["locked"] and bool(t["next_approver"]) \
        and t["next_approver"]["approver_id"] == me_id


app.jinja_env.globals["actionable_by"] = _pm_line_actionable_by


def _pm_all_previews(db, subject_id, cycle_id):
    """_pm_member_previews for a CALIBRATOR (2026-09-28): every one of the person's lines, not one approver's
    subset -- a calibrator is deciding the person's whole rating. (lines, moderated preview, self preview,
    all_locked), the same shallow-copy-and-rescore as the approver version."""
    ts_all = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY " + PM_LINE_ORDER,
        (cycle_id, subject_id)).fetchall()]
    attach_pm_chains(db, ts_all)
    pm_score_targets(db, ts_all)
    mod = pm_overall_for_targets(db, ts_all, require_locked=False)
    self_ts = [dict(t) for t in ts_all]
    for st in self_ts:
        st["effective_value"] = st["result"]["actual_value"] if st.get("result") else None
    pm_score_targets(db, self_ts)
    self_prev = pm_overall_for_targets(db, self_ts, require_locked=False)
    for t, st in zip(ts_all, self_ts):
        t["self_score"] = st["score"]
    return ts_all, mod, self_prev, bool(ts_all) and all(t["locked"] for t in ts_all)


def _pm_manager_remarks_locked(db, cycle_id, subject_id, all_locked):
    """Every approver's overall remark on the period, attributed -- ONLY once every line is locked (the
    calibration_kpi_report rule: pm_manager_remarks autosaves with no draft flag, so an earlier read would put a
    half-written sentence in the calibration room)."""
    if not all_locked:
        return []
    mgr = (db.execute("SELECT manager_id FROM users WHERE id=?", (subject_id,)).fetchone() or {"manager_id": None})["manager_id"]
    out = [{"author": r["author"] or "Their manager", "remark": (r["remark"] or "").strip(), "author_id": r["submitted_by"],
            # who they are to the person (2026-09-29 review: every approver's remark was headed 'line manager')
            "role": "Line manager" if (mgr and r["submitted_by"] == mgr) else "Approver"} for r in db.execute(
        "SELECT r.remark, r.submitted_by, u.full_name AS author FROM pm_manager_remarks r "
        "LEFT JOIN users u ON u.id = r.submitted_by "
        "WHERE r.cycle_id=? AND r.subject_id=? AND TRIM(COALESCE(r.remark,'')) != '' "
        "ORDER BY r.submitted_at", (cycle_id, subject_id)).fetchall()]
    out.sort(key=lambda m: 0 if m["role"] == "Line manager" else 1)   # the line manager first, not the last to save
    return out


def _pm_member_previews(db, subject_id, cycle_id, me_id, overrides=None):
    """The aggregate self-rated/moderated preview for one manager's view of
    one direct report's period -- factored out so performance_team_member_view()
    and performance_kpi_moderate_autosave() can never quietly drift apart on
    how 'Moderated Rating' is computed. Re-queries ts_all fresh (never trusts
    a caller's possibly-stale copy), scopes to 'mine' only (see
    performance_kpi_moderate_autosave()'s docstring for why -- a matrix-case
    manager must never see enough of a peer co-approver's in-progress line to
    algebraically back out its value), and computes BOTH the moderated
    aggregate (effective_value, i.e. any approver's decision so far) and the
    self-rated aggregate (each line's raw employee submission, ignoring any
    moderation) via the same shallow-copy-and-rescore trick, zero new scoring
    logic. require_locked=False on both -- this is a live preview, not the
    page's official locked-only 'Overall rating' figure (pm_overall_for_targets()
    defaults to require_locked=True; both calls here must override that).
    `overrides` (optional {kpi_target_id: float}) feeds the read-only
    what-if preview endpoint: for each mine line the caller is actually
    allowed to act on right now (_pm_line_actionable_by gate -- so a crafted
    override for a peer's line or an already-locked line is ignored), the
    typed value replaces effective_value on the MODERATED side only, before
    scoring. The self-rated side is always the raw employee submission and is
    never affected by overrides. Returns (mine, mine_preview, self_preview,
    all_locked)."""
    ts_all = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY " + PM_LINE_ORDER,
        (cycle_id, subject_id)).fetchall()]
    attach_pm_chains(db, ts_all)
    me = {"id": me_id}
    mine = _pm_team_mine(me, ts_all)
    if overrides:
        for t in mine:
            if t["id"] in overrides and _pm_line_actionable_by(t, me_id):
                t["effective_value"] = overrides[t["id"]]
    pm_score_targets(db, mine)
    mine_preview = pm_overall_for_targets(db, mine, require_locked=False)
    self_mine = [dict(t) for t in mine]
    for st in self_mine:
        st["effective_value"] = st["result"]["actual_value"] if st.get("result") else None
    pm_score_targets(db, self_mine)
    self_preview = pm_overall_for_targets(db, self_mine, require_locked=False)
    for t, st in zip(mine, self_mine):
        t["self_score"] = st["score"]
    all_locked = bool(mine) and all(t["locked"] for t in mine)
    return mine, mine_preview, self_preview, all_locked


# ---------------------------------------------------------------------------
# KPI SETTING journey (Phase 2). An employee assembles this period's scorecard
# from the KPI Library for their BG / department / tier band, weights it to
# 100%, and proposes it up the same chain that will later moderate the result.
#
# Deliberately a PARALLEL track to result approval: pm_kpi_targets.status +
# pm_kpi_setting_approvals, never pm_kpi_approvals (see the schema comment on
# pm_kpi_setting_approvals). The two stages are temporally disjoint -- result
# entry is gated on status='approved' via pm_result_entry_open().
# ---------------------------------------------------------------------------
PM_SETTING_OPEN_STATUSES = ("draft", "proposed", "returned")

# ---------------------------------------------------------------------------
# Individual Development Plan (IDP). One per person per period: the employee
# authors development goals, the manager comments and agrees. Anchored on
# cycles so it lives inside the year-end appraisal, and gated by the same
# active-period rule as the scorecard -- a past period is read-only.
# ---------------------------------------------------------------------------
def pm_idp_max_goals():
    """The ceiling on goals in one development plan.

    Admin-set (Settings -> IDP), defaulting to the 6 this used to be hardcoded
    at as PM_IDP_MAX_GOALS. That constant is gone rather than kept alongside
    the setting: two ceilings that can disagree is precisely the drift this
    settings work exists to remove. A setting of 0 means "no ceiling" and
    resolves to a large number here, because every caller does arithmetic
    against this rather than branching on None."""
    n = get_idp_settings()[2]
    return n if n else 999

# The 70:20:10 development modes. Keys are the pm_idp_goals column suffixes;
# `pct` is shown as a label only -- never validated against, see the schema
# comment on why the ratios are a prompt and not a rule.
PM_IDP_MODES = (
    {"key": "experience", "pct": 70, "label": "On the job",
     "hint": "The assignment, project or stretch that will build it",
     "ai": "a job-based assignment or stretch project"},
    {"key": "exposure", "pct": 20, "label": "From others",
     "hint": "Who you'll ask to help, and how",
     "ai": "who to learn from and how to ask them"},
    {"key": "education", "pct": 10, "label": "Formal learning",
     "hint": "A course, certification or self-study",
     "ai": "a formal course or self-study step"},
)
PM_IDP_ACTION_FIELDS = tuple("action_" + m["key"] for m in PM_IDP_MODES)
PM_IDP_FIELDS = ("area", "target_date") + PM_IDP_ACTION_FIELDS

# Progress states for a goal on an agreed plan. 'dropped' is first-class and
# deliberately so: priorities genuinely change mid-period, and a plan that can
# only ever say "in progress" teaches people to quietly abandon it instead of
# saying so. `tone` maps to the existing .status-pill families -- no new CSS.
PM_IDP_PROGRESS = (
    {"key": "not_started", "label": "Not started", "tone": "status-progress"},
    {"key": "in_progress", "label": "In progress", "tone": "status-submitted"},
    {"key": "done", "label": "Done", "tone": "status-reviewed"},
    {"key": "dropped", "label": "Dropped", "tone": "status-progress"},
)
PM_IDP_PROGRESS_KEYS = tuple(p["key"] for p in PM_IDP_PROGRESS)


# Career profile. Three horizons, because "what do you want to be doing" is a
# different question at each range and collapsing them produces one vague
# sentence: near-term is about this role, mid is the realistic next move, long
# is direction rather than a job title.
PM_CAREER_HORIZONS = (
    {"key": "aspiration_now", "label": "Right now",
     "hint": "What you want to be known for in your current role"},
    {"key": "aspiration_mid", "label": "In 1-3 years",
     "hint": "The next move you'd like to work towards"},
    {"key": "aspiration_long", "label": "In 5+ years",
     "hint": "The direction, not necessarily a job title"},
)
# Mobility as a controlled choice rather than free text: it's the one field HR
# needs to read across hundreds of people for succession planning, and free
# text can't be counted. The note beside it carries the nuance the list can't.
PM_CAREER_MOBILITY = (
    {"key": "current_role", "label": "Happy where I am"},
    {"key": "same_company", "label": "Open to another role in my business unit"},
    {"key": "within_bg", "label": "Open to another company in my BG"},
    {"key": "across_bg", "label": "Open to another Business Group"},
    {"key": "relocate", "label": "Open to relocating"},
)
PM_CAREER_MOBILITY_KEYS = tuple(m["key"] for m in PM_CAREER_MOBILITY)
PM_CAREER_FIELDS = (tuple(h["key"] for h in PM_CAREER_HORIZONS)
                    + ("strengths", "mobility", "mobility_note", "preferences", "mentor"))


# A role has to share at least this much of your current skill list before the
# map offers it. Tuned to be permissive: the map is for exploring, and a route
# HR dislikes can be hidden, whereas one that never appears cannot be found.
TC_ROUTE_MIN_OVERLAP = 0.30

# Where a role sits once we know how ready this person is for it. Readiness is
# the share of that role's competencies they already hold, so these are read as
# "most of it", "a real piece of it", and "mostly new ground".
TC_READY_CLOSE, TC_READY_STRETCH = 60, 25
TC_READY_GROUPS = (
    ("closest", "Closest to you now", "Most of what these ask, you already hold."),
    ("stretch", "A stretch", "Real overlap, with competencies you would need to build."),
    ("longer", "Longer term", "Mostly new ground \u2014 worth a conversation before a plan."),
)


# --- the job architecture (Chris, 2026-10-17; plan ~/.claude/plans/shiny-puzzling-tarjan.md) -------------------------
JA_MIN_GRADE = 12   # the architecture feeds JG 12 and above only, for now
# A profile's requirement as the job is NOW: its current rows only. Every reader of tc_job_profile_skills that means
# "what the job needs" adds this; a future row (is_future=1) is where the job is heading, never a current requirement.
TC_CURRENT_ROWS = "COALESCE(ps.is_future,0)=0"


def ja_eid(raw):
    """An Employee ID as the architecture and the roster both hold it: trimmed, upper case, an Excel '.0' dropped."""
    t = str(raw if raw is not None else "").strip().upper()
    return t[:-2] if t.endswith(".0") and t[:-2].isdigit() else t


def ja_roles_map(db, employee_ids):
    """{employee_id: ja_people row} for many people in ONE query per 900 (a leader view holds 1,000+)."""
    ids = sorted({ja_eid(x) for x in employee_ids if x})
    out = {}
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        for r in db.execute("SELECT * FROM ja_people WHERE employee_id IN (%s)" % ",".join("?" * len(chunk)), chunk):
            out[r["employee_id"]] = r
    return out


def ja_role(db, u):
    """This person's role in the job architecture (a ja_people row), or None."""
    eid = ja_eid(_row_get(u, "employee_id"))
    return db.execute("SELECT * FROM ja_people WHERE employee_id=?", (eid,)).fetchone() if eid else None


def ja_job_code(db, u, role=None):
    """The person's job code: their unit (else specialisation) code + their LIVE job grade, e.g. CSS-FIN-01-A-14.
    None below JG 12, for a letter grade, or with no role in the architecture. The one place a job code is made."""
    g = grade_num(_row_get(u, "job_grade"))
    if g is None or g < JA_MIN_GRADE:
        return None
    role = role if role is not None else ja_role(db, u)
    base = (role["unit_code"] or role["spec_code"]) if role else None
    return "%s-%d" % (base, g) if base else None


JA_ADMIN_SOURCE = "admin"   # a job HR placed in OneHR (2026-10-18); the Mapper import keeps it for anyone it doesn't have
_JA_STOP = {"and", "of", "the", "for", "a", "an", "in", "to", "dept", "department"}


def _ja_words(text):
    t = (text or "").lower().replace("qa/qc", "qaqc").replace("qa & qc", "qaqc").replace("qa&qc", "qaqc")
    return {w for w in re.findall(r"[a-z0-9]+", t) if w not in _JA_STOP}


def ja_job_suggestions(db, user, limit=2):
    """The job profiles at this person's grade that best fit their title and department, best first: [profile dict]
    (2026-10-18, placing a new joiner's job). Word overlap, no model: their title against each profile's title and job
    scope (twice the weight), their title and department against its sub-family (its department column), ties broken by
    how many people already hold the job. Nothing below JG 12, nothing that shares no word."""
    g = grade_num(_row_get(user, "job_grade"))
    if g is None or g < JA_MIN_GRADE:
        return []
    rows = [dict(r) for r in db.execute(
        "SELECT id, job_code, job_title, job_scope, department FROM tc_job_profiles WHERE active=1 AND job_code LIKE ?",
        ("%%-%d" % g,))]
    if not rows:
        return []
    held = {r[0]: r[1] for r in db.execute("SELECT COALESCE(unit_code, spec_code), COUNT(*) FROM ja_people GROUP BY 1")}
    want_t, want_d = _ja_words(_row_get(user, "job_title")), _ja_words(_row_get(user, "department"))
    scored = []
    for r in rows:
        pt, pd = _ja_words(r["job_title"]) | _ja_words(r["job_scope"]), _ja_words(r["department"])
        sc = 2.0 * len(want_t & pt) / max(1, len(want_t)) + 0.5 * len((want_t | want_d) & pd) / max(1, len(pd))
        if sc > 0:
            scored.append((sc, held.get(re.sub(r"-\d+$", "", r["job_code"]), 0), r))
    scored.sort(key=lambda x: (-x[0], -x[1], x[2]["job_title"]))
    return [r for _sc, _h, r in scored[:limit]]


def ja_place_job(db, user, profile):
    """Place a person's job in the architecture from a job profile (2026-10-18: a joiner P&R's Mapper doesn't have yet,
    or a correction): its job code without the grade is their unit (or specialisation), climbed to the specialisation,
    sub-family and family in ja_taxonomy; its job scope is theirs. Source 'admin'. Their job code then follows their
    live grade (ja_job_code), so a promotion moves them on the same ladder. The caller commits. An error, or None."""
    m = re.match(r"^(.+)-(\d+)$", (profile.get("job_code") or "").strip())
    if not m:
        return "That job has no job code to place."
    eid = ja_eid(_row_get(user, "employee_id"))
    if not eid:
        return "They have no Employee ID to place a job against."
    base, chain, code = m.group(1), {}, m.group(1)
    for _i in range(6):
        row = db.execute("SELECT code, level, parent_code FROM ja_taxonomy WHERE code=?", (code,)).fetchone()
        if not row:
            break
        chain[row["level"]] = row["code"]
        code = row["parent_code"]
        if not code:
            break
    if chain.get("unit") == base:
        unit, spec = base, chain.get("spec")
    elif chain.get("spec") == base:
        unit, spec = None, base
    else:   # a code the loaded taxonomy doesn't list: the code alone still makes the job code
        unit, spec = base, None
    db.execute(
        "INSERT INTO ja_people(employee_id, family_code, sub_code, spec_code, unit_code, job_scope, title, arch_grade, "
        "source, version, imported_at) VALUES (?,?,?,?,?,?,?,?,?, 'admin', datetime('now')) ON CONFLICT(employee_id) DO "
        "UPDATE SET family_code=excluded.family_code, sub_code=excluded.sub_code, spec_code=excluded.spec_code, "
        "unit_code=excluded.unit_code, job_scope=excluded.job_scope, title=excluded.title, "
        "arch_grade=excluded.arch_grade, source=excluded.source, version=excluded.version, "
        "imported_at=excluded.imported_at",
        (eid, chain.get("family"), chain.get("sub"), spec, unit, (profile.get("job_scope") or None) or None,
         profile.get("job_title"), str(_row_get(user, "job_grade") or ""), JA_ADMIN_SOURCE))
    return None


def ja_placement_word(role):
    """Where a person's job in the architecture came from, in words: P&R's Mapper, placed in OneHR, or not placed."""
    if not role:
        return None
    return "Placed in OneHR" if (_row_get(role, "source") or "") == JA_ADMIN_SOURCE else "From P&R's Mapper"


_TC_PLAN_SOURCES = ("profile", "admin_profile", "admin")   # the rows a job's plan replaces (Reset, placing, the swap)


def _tc_swap_split(db, cid, uid, plan):
    """What replacing this person's job-set rows with `plan` does to them, row by row (2026-11-06, the swap of a STARTED
    set): {"keep": rows the plan also lists, same competency and same current / next level (they keep their answers),
    "drop": the other job-set rows, "add": the plan rows (skill_id, is_future, seq) they don't have yet}. Each row is a
    dict with its id, skill_id, is_future, source and `answered` (their answer or their manager's is in). A row of
    another source (nothing writes one today) is never touched, and its competency is not added twice. Reads only."""
    marks = ",".join("?" * len(_TC_PLAN_SOURCES))
    rows = [dict(r) for r in db.execute(
        "SELECT a.id, a.skill_id, a.is_future, a.source, a.seq, EXISTS(SELECT 1 FROM tc_scores sc WHERE "
        "sc.assignment_id=a.id AND (sc.answer IS NOT NULL OR sc.manager_answer IS NOT NULL)) AS answered "
        "FROM tc_assignments a WHERE a.cycle_id=? AND a.subject_id=? AND a.source IN (%s) ORDER BY a.id" % marks,
        (cid, uid) + _TC_PLAN_SOURCES)]
    other = {r[0] for r in db.execute(
        "SELECT skill_id FROM tc_assignments WHERE cycle_id=? AND subject_id=? AND source NOT IN (%s)" % marks,
        (cid, uid) + _TC_PLAN_SOURCES)}
    return _tc_swap_split_calc(rows, other, plan)


def _tc_swap_split_calc(rows, other, plan):
    """_tc_swap_split's arithmetic over rows already read (the profile-change engine reads many people's sets in one query, so it
    can't call _tc_swap_split per person): `rows` = the person's job-set rows (dicts with id, skill_id, is_future, source, seq,
    answered; sources in _TC_PLAN_SOURCES), `other` = the skill ids they hold from any other source, `plan` = the plan rows."""
    want = {}
    for skill_id, is_future, seq in plan:
        want.setdefault((skill_id, int(is_future)), seq)
    keep, drop, seen = [], [], set()
    for r in rows:
        k = (r["skill_id"], int(r["is_future"]))
        if k in want:
            r["plan_seq"] = want[k]
            keep.append(r)
            seen.add(r["skill_id"])
        else:
            drop.append(r)
    add = []
    for skill_id, is_future, seq in plan:
        if skill_id in seen or skill_id in other:
            continue
        seen.add(skill_id)
        add.append((skill_id, is_future, seq))
    return {"keep": keep, "drop": drop, "add": add}


def _tc_swap_counts(split):
    """The split's numbers, for the box, the flash and the trail."""
    return {"kept_answered": sum(1 for r in split["keep"] if r["answered"]),
            "kept_unanswered": sum(1 for r in split["keep"] if not r["answered"]),
            "removed_answered": sum(1 for r in split["drop"] if r["answered"]),
            "removed_unanswered": sum(1 for r in split["drop"] if not r["answered"]),
            "added": len(split["add"])}


def _tc_assign_from_profile(db, cid, uid, profile_id, source="profile", keep_matching=False, stats=None):
    """Replace this person's job-profile competencies for the cycle with the profile's plan, as Reset always has (rows HR
    added by hand and a matched profile's go too): how many. One writer for Reset, placing a job, the New joiners
    page's Assign and the swap of a started set. The caller checks they haven't started or been reviewed and their result
    isn't out, and commits.

    keep_matching=True is the swap of a STARTED set (the super admin's, `_tc_swap_started`): a row the plan also lists
    stays with its answers (its order and source follow the plan), the others go with their scores, and only the plan's
    missing rows are added. `stats`, when given, is filled with `_tc_swap_counts`'s numbers. The caller has checked
    everything that makes this allowed and commits."""
    plan = tc_profile_plan(db, profile_id) if profile_id else []
    if keep_matching:
        split = _tc_swap_split(db, cid, uid, plan)
        if stats is not None:
            stats.update(_tc_swap_counts(split))
        for r in split["keep"]:
            db.execute("UPDATE tc_assignments SET seq=?, source=? WHERE id=?", (r["plan_seq"], source, r["id"]))
        for r in split["drop"]:   # the scores go by name too: nothing here relies on foreign_keys being on
            db.execute("DELETE FROM tc_scores WHERE assignment_id=?", (r["id"],))
            db.execute("DELETE FROM tc_assignments WHERE id=? AND subject_id=? AND cycle_id=?", (r["id"], uid, cid))
        for skill_id, is_future, seq in split["add"]:
            db.execute("INSERT OR IGNORE INTO tc_assignments(cycle_id, subject_id, skill_id, is_future, seq, source) "
                       "VALUES (?,?,?,?,?,?)", (cid, uid, skill_id, is_future, seq, source))
        return len(plan)
    db.execute("DELETE FROM tc_assignments WHERE cycle_id=? AND subject_id=? AND source IN "
               "('profile','admin_profile','admin')", (cid, uid))
    for skill_id, is_future, seq in plan:
        db.execute("INSERT OR IGNORE INTO tc_assignments(cycle_id, subject_id, skill_id, is_future, seq, source) "
                   "VALUES (?,?,?,?,?,?)", (cid, uid, skill_id, is_future, seq, source))
    return len(plan)


def tc_profile_for_user(db, u, career=None):
    """The architecture row this person sits on, and how we know.

    department + job_title + job_grade is the architecture's own key. When it
    misses, fall back to the role they picked themselves on their career
    profile, and only then to a looser read of the architecture: the same
    title at the same grade in another department, then the title on its own.

    The loose steps exist because the roster carries ~1,900 distinct
    (department, title, grade) combinations across ~3,600 people -- demanding
    all three exactly would leave almost everyone with no profile, which is
    the state the architecture has actually been sitting in. They run ONLY
    where the strict steps already returned nothing, so no match that works
    today changes, and a person's own pick still beats a fuzzy roster guess.

    Returns (profile_dict_or_None, 'roster'|'self'|'title_grade'|'title'|None)
    -- the source is not decoration: it is what lets a screen say how sure it
    is, and it is the difference between "HR mapped this role" and "we guessed
    from the title"."""
    # the job architecture first (2026-10-17): someone with a job code is resolved by it alone -- a profile P&R
    # reviewed for their exact job, or none (listed as unmapped), never a title guess
    role = ja_role(db, u)
    jc = ja_job_code(db, u, role)
    if jc:
        # their job scope's profile when the code has one per scope (2026-10-18), else the code's scope-less one, else
        # the code's first (the mapping lists a code's most-held scope first)
        scope = ((role["job_scope"] if role else None) or "").strip().upper()
        rows = db.execute("SELECT * FROM tc_job_profiles WHERE active=1 AND job_code=? ORDER BY id", (jc,)).fetchall()
        r = (next((x for x in rows if scope and (x["job_scope"] or "").strip().upper() == scope), None)
             or next((x for x in rows if not (x["job_scope"] or "").strip()), None) or (rows[0] if rows else None))
        return (dict(r), "job_code") if r else (None, None)
    dept = (u["department"] or "").strip()
    title = (u["job_title"] or "").strip()
    grade = str(u["job_grade"] or "").strip()
    r = db.execute(
        "SELECT * FROM tc_job_profiles WHERE active=1 AND department=? AND job_title=? "
        "AND job_grade=? AND job_code IS NULL", (dept, title, grade)).fetchone()
    if r:
        return dict(r), "roster"
    pid = career["self_profile_id"] if career else None
    if pid:
        r = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1",
                       (pid,)).fetchone()
        if r:
            return dict(r), "self"
    if title:
        # ORDER BY id so a title that several departments define resolves the
        # same way every run -- a generator that reshuffled people between
        # profiles on re-run would be worse than one that never matched.
        for sql, args, src in (
                ("SELECT * FROM tc_job_profiles WHERE active=1 AND job_title=? "
                 "AND job_grade=? AND job_code IS NULL ORDER BY id LIMIT 1", (title, grade), "title_grade"),
                ("SELECT * FROM tc_job_profiles WHERE active=1 AND job_title=? "
                 "AND job_code IS NULL ORDER BY id LIMIT 1", (title,), "title")):
            r = db.execute(sql, args).fetchone()
            if r:
                return dict(r), src
    return None, None


def tc_profile_skill_map(db, profile_id):
    """{skill title -> level this role needs it at}.

    Keyed on TITLE, not skill_code, because the same titled skill exists at
    several levels and that IS the proficiency scale (ACC-AUD-3009 is the
    level-3 form of ACC-AUD-4009). So "does this role need X, and how deep"
    is a title match plus a level comparison -- which is also what makes two
    roles' requirements comparable at all."""
    out = {}
    for r in db.execute(
            "SELECT s.title, COALESCE(ps.required_level, s.level) lvl "
            "FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id = ps.skill_id "
            "WHERE ps.profile_id=? AND s.active=1 AND " + TC_CURRENT_ROWS, (profile_id,)):
        t = (r["title"] or "").strip()
        if t and (r["lvl"] or 0) > out.get(t, -1):
            out[t] = r["lvl"] or 0
    return out


def _profile_skill_titles(db, profile_id):
    """The required competencies for a job profile, as distinct skill TITLES in the
    architecture's own sort order. This is the REAL Column-2 data for the career-direction
    card -- no AI: a role's competencies are exactly what the job architecture records."""
    seen, out = set(), []
    for r in db.execute(
            "SELECT s.title FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id=ps.skill_id "
            "WHERE ps.profile_id=? AND s.active=1 AND " + TC_CURRENT_ROWS + " ORDER BY ps.sort_order, s.title",
            (profile_id,)):
        t = (r["title"] or "").strip()
        if t and t not in seen:
            seen.add(t)
            out.append(t)
    return out


def tc_person_skill_map(db, subject_id):
    """{skill title -> deepest level this person has actually demonstrated}.

    Only REVIEWED assessments count -- an unreviewed self-assessment is a claim,
    not evidence, and the competency module already draws that line everywhere
    else. The manager's answer wins wherever they moderated one. Deliberately
    NOT scoped to a cycle: a competency demonstrated last half is still held. A submitted one nobody reviews (the Executive
    Chairman's direct report while his Competency tick is off) counts as it stands (2026-11-06)."""
    out = {}
    for r in db.execute(
            "SELECT s.title, s.level, "
            "COALESCE(NULLIF(TRIM(sc.manager_answer),''), sc.answer) ans "
            "FROM tc_scores sc "
            "JOIN tc_assignments a ON a.id = sc.assignment_id "
            "JOIN tc_assessments ass ON ass.id = sc.assessment_id "
            "JOIN tc_skills s ON s.id = a.skill_id "
            "WHERE a.subject_id=? AND " + _tc_done_sql(db, "ass", "ass.subject_id"), (subject_id,)):
        if (r["ans"] or "") != "yes":
            continue
        t = (r["title"] or "").strip()
        if t and (r["level"] or 0) > out.get(t, -1):
            out[t] = r["level"] or 0
    return out


def tc_person_skill_self(db, subject_id):
    """{skill title -> deepest level this person has recorded as demonstrated}, from
    their OWN competency answers regardless of assessment status.

    The self-service sibling of tc_person_skill_map: inside the review the person plans
    development against their OWN competency self-assessment, which is submitted but not
    yet manager-reviewed -- so this drops the `status='reviewed'` filter (the manager's
    answer still wins where one exists). tc_person_skill_map stays reviewed-only for the
    calibration-grade career map, where an unreviewed self-claim must not count."""
    out = {}
    for r in db.execute(
            "SELECT s.title, s.level, "
            "COALESCE(NULLIF(TRIM(sc.manager_answer),''), sc.answer) ans "
            "FROM tc_scores sc "
            "JOIN tc_assignments a ON a.id = sc.assignment_id "
            "JOIN tc_skills s ON s.id = a.skill_id "
            "WHERE a.subject_id=?", (subject_id,)):
        if (r["ans"] or "") != "yes":
            continue
        t = (r["title"] or "").strip()
        if t and (r["level"] or 0) > out.get(t, -1):
            out[t] = r["level"] or 0
    return out


def tc_person_assessed_titles(db, subject_id):
    """The skill titles this person has ANY answer on (yes or no, theirs or the manager's), in any cycle: what has
    been assessed at all. tc_person_skill_self keeps only the "yes" answers, so on its own it can't tell "assessed and
    not held" from "never asked" (2026-10-17: staging's demo people answered the old skills, none of the architecture's)."""
    return {(r[0] or "").strip() for r in db.execute(
        "SELECT DISTINCT s.title FROM tc_scores sc JOIN tc_assignments a ON a.id = sc.assignment_id "
        "JOIN tc_skills s ON s.id = a.skill_id WHERE a.subject_id=? "
        "AND COALESCE(NULLIF(TRIM(sc.manager_answer),''), sc.answer) IN ('yes','no')", (subject_id,))} - {""}


def tc_route_gap(db, have, target_profile_id, need=None):
    """What stands between `have` and a target role, skill by skill.

    Three states, because they call for different things: `met` is done,
    `stretch` is a skill you hold but not deep enough (a development goal),
    `missing` is one you have never been assessed on at all (a conversation
    with your manager first). Lumping the last two together would tell someone
    to go train on something nobody has established they lack."""
    if need is None:
        need = tc_profile_skill_map(db, target_profile_id)
    rows = []
    for title in sorted(need):
        req, got = need[title], have.get(title)
        rows.append({"title": title, "required": req, "have": got,
                     "state": "missing" if got is None
                              else ("met" if got >= req else "stretch")})
    met = sum(1 for r in rows if r["state"] == "met")
    return {"rows": rows, "total": len(rows), "met": met,
            "stretch": sum(1 for r in rows if r["state"] == "stretch"),
            "missing": sum(1 for r in rows if r["state"] == "missing"),
            "pct": int(round(100.0 * met / len(rows))) if rows else 0}


def tc_profile_skill_maps(db, profile_ids):
    """tc_profile_skill_map for many profiles in one batched read: {profile id -> {title -> level}}."""
    out = {pid: {} for pid in profile_ids}
    ids = list(out)
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        for r in db.execute(
                "SELECT ps.profile_id pid, s.title, COALESCE(ps.required_level, s.level) lvl "
                "FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id = ps.skill_id "
                "WHERE ps.profile_id IN (%s) AND s.active=1 AND %s" % (",".join("?" * len(chunk)), TC_CURRENT_ROWS),
                chunk):
            t = (r["title"] or "").strip()
            m = out[r["pid"]]
            if t and (r["lvl"] or 0) > m.get(t, -1):
                m[t] = r["lvl"] or 0
    return out


def _ja_parts(job_code):
    """An architecture job code's place in the tree: {base, grade, spec, sub, family}, or None. A job code is the
    unit (or specialisation) code plus the JG -- CSS-ADM-01-B-12 is unit CSS-ADM-01-B, specialisation CSS-ADM-01,
    sub-family CSS-ADM, family CSS, JG 12."""
    m = re.match(r"^([A-Z0-9]+(?:-[A-Z0-9]+)+)-(\d{1,2})$", job_code or "")
    if not m:
        return None
    seg = m.group(1).split("-")
    return {"base": m.group(1), "grade": int(m.group(2)), "family": seg[0], "sub": "-".join(seg[:2]),
            "spec": "-".join(seg[:3]) if len(seg) >= 3 else m.group(1)}


def _tc_rank_routes(out, have, limit):
    """Readiness, group and order for a list of route rows (shared by both derivations)."""
    # Rank by how ready THIS PERSON is, not by how similar the role is. The two
    # disagree constantly and the similarity answer is the less useful one: a
    # role can share every competency your job lists and still be one you hold
    # none of at the depth it needs.
    #
    # With no reviewed assessment there is no readiness to rank on -- every gap
    # would read 0% and the order would be arbitrary -- so fall back to
    # similarity and let the page say so rather than implying a ranking that
    # isn't there.
    ranked = bool(have)
    for r in out:
        pct = r["gap"]["pct"] if (ranked and r.get("gap")) else None
        r["readiness"] = pct
        r["group"] = ("related" if pct is None
                      else "closest" if pct >= TC_READY_CLOSE
                      else "stretch" if pct >= TC_READY_STRETCH
                      else "longer")
    # Pinned first so a curated route can never be pushed off by the limit; then the steps up their own job and the
    # leadership track (2026-10-19), and the next job where their own job stops, so a lateral can't push them off either.
    out.sort(key=lambda r: (not r["pinned"], r.get("route") not in ("next grade in this job", "leadership track")
                            and not r.get("next_job"),
                            -(r["readiness"] if r["readiness"] is not None else -1),
                            -r["score"], r["profile"]["job_title"]))
    return out[:limit]


# Where an architecture route comes from, nearest first (2026-10-17, plan Phase 3): the next grades of the same job,
# then the specialisation's other units, the sub-family's other specialisations, the family's other sub-families.
# A lateral route needs this share of the current role's skills to carry over (the same job's siblings need none:
# the architecture itself puts them side by side).
TC_ARCH_ROUTE_OVERLAP = {"spec": 0.0, "sub": TC_ROUTE_MIN_OVERLAP, "family": 0.40}
TC_ARCH_ROUTE_LABEL = {"vertical": "next grade in this job", "spec": "same specialisation",
                       "sub": "same sub-family", "family": "same job family", "pinned": "suggested by Group People",
                       "leader": "leadership track"}

# The grade ladder (the job architecture's, from what sits at each grade; Chris, 2026-10-19: "12-20 for normal role,
# then 21 should be director or C-suite level, 22 is BUCEO level"; the data adds JG 23, every BG CEO). JG 12 to 20 is
# every job's own ladder; above it, the leadership track.
TC_LADDER_LEVELS = {12: "Executive", 13: "Executive", 14: "Senior Executive", 15: "Assistant Manager", 16: "Manager",
                    17: "Manager", 18: "Senior Manager", 19: "Assistant General Manager", 20: "General Manager",
                    21: "Director / C-suite", 22: "BU CEO", 23: "BG CEO / Group C-suite"}
TC_LADDER_BOTTOM, TC_LADDER_TOP = 12, 20
# the job family that holds the JG 21-23 roles (Management: 7 of 21 JG 21 jobs, 5 of 7 JG 22, every JG 23)
TC_LEADERSHIP_FAMILY = "EXL"
# Two roles are never offered as a career path to anyone (Chris, 2026-11-05): the "Executive Chairman" and the "Board
# Advisor To Ec And Bgceo", both JG 23. Matched by TITLE only (case-insensitive, spaces collapsed), never by job code:
# the codes are shared with other roles in the architecture (EXL-GM-01-23 also holds Group Chief Executive Officer and
# Group Chief Transformation Officer; EXL-GM-02-23 also holds Managing Director), which must stay offered. If P&R ever
# retitles these two roles, this set must be updated. Applied where routes are derived (tc_career_routes_for, both
# paths), so the Career Plan page, the chat's set_direction and the admin role pick all honour it. The profiles
# themselves stay in the architecture.
TC_NOT_A_CAREER_ROUTE_TITLES = frozenset({"executive chairman", "board advisor to ec and bgceo"})


def tc_not_a_career_route(profile):
    """True for a job profile that is never offered as a career target (TC_NOT_A_CAREER_ROUTE_TITLES). `profile` is a
    tc_job_profiles row or dict."""
    try:
        title = " ".join((profile["job_title"] or "").split()).lower()
    except (KeyError, IndexError):
        title = ""
    return title in TC_NOT_A_CAREER_ROUTE_TITLES
# Where a job's own ladder stops (Chris, 2026-10-19: "certain roles like personal driver, admin shouldn't have the
# ladder to high job grade"). App setting career_ladder_tops = {base: {"top": JG, "kind": kind}}; a job not listed runs
# to TC_LADDER_TOP. His picks: one role (a driver, a chargeman, an inspector of work) one grade above the top grade
# anyone holds; administration and support JG 17; a specialist sub-function JG 18; a function JG 20. The tops came
# from OneHR/Production Import/Career ladder ceilings - proposal 2026-10-19.xlsx (tools/set_ladder_tops.py).
TC_LADDER_TOPS_KEY = "career_ladder_tops"
TC_LADDER_KINDS = {"position": "one role", "admin": "administration and support", "specialist": "a specialist "
                   "sub-function", "function": "a function"}


def tc_ladder_tops(db):
    """{base: {"top": JG, "kind": kind}}: the jobs whose own ladder stops below JG 20 (TC_LADDER_TOPS_KEY)."""
    try:
        row = db.execute("SELECT value FROM app_settings WHERE key=?", (TC_LADDER_TOPS_KEY,)).fetchone()
        v = json.loads(row[0]) if row and row[0] else {}
    except (sqlite3.Error, TypeError, ValueError):
        v = {}
    out = {}
    for b, x in (v.items() if isinstance(v, dict) else []):
        try:
            top = int((x or {}).get("top"))
        except (AttributeError, TypeError, ValueError):
            continue
        out[str(b)] = {"top": max(TC_LADDER_BOTTOM, min(top, TC_LADDER_TOP)), "kind": str((x or {}).get("kind") or "")}
    return out


def tc_ladder_top(tops, base):
    """The grade a job's own ladder stops at (TC_LADDER_TOP unless tc_ladder_tops lists it)."""
    return (tops.get(base) or {}).get("top", TC_LADDER_TOP)


def tc_ladder_over_top(db):
    """The active TARGET roles above their job's top: [{id, base, grade, title, picked, pinned}]. `picked`: somebody
    chose it as their next role (pm_career_profile.target_profile_id); `pinned`: HR pinned it as a route."""
    tops = tc_ladder_tops(db)
    if not tops:
        return []
    picked = {r[0] for r in db.execute("SELECT target_profile_id FROM pm_career_profile "
                                       "WHERE target_profile_id IS NOT NULL")}
    pinned = {r[0] for r in db.execute("SELECT to_profile_id FROM tc_career_routes WHERE kind='pinned'")}
    out = []
    for r in db.execute("SELECT id, job_code, job_title FROM tc_job_profiles WHERE active=1 AND source='target' "
                        "AND job_code IS NOT NULL ORDER BY job_code, id"):
        p = _ja_parts(r["job_code"])
        if p and p["base"] in tops and p["grade"] > tc_ladder_top(tops, p["base"]):
            out.append({"id": r["id"], "base": p["base"], "grade": p["grade"], "title": r["job_title"],
                        "picked": r["id"] in picked, "pinned": r["id"] in pinned})
    return out


def tc_retire_over_top(db, actor_id=None):
    """Retire (active=0) the target roles above their job's top. Nobody holds a target role, so no person moves; one
    somebody chose as their next role, or HR pinned, is kept and counted instead. Raising a top later and pressing Fill
    the missing grades takes a retired row back over (tc_fill_ladders). Returns {retired, kept_picked, kept_pinned}."""
    over = tc_ladder_over_top(db)
    go = [x["id"] for x in over if not x["picked"] and not x["pinned"]]
    for i in range(0, len(go), 500):
        chunk = go[i:i + 500]
        db.execute("UPDATE tc_job_profiles SET active=0, updated_at=datetime('now') WHERE source='target' AND id IN (%s)"
                   % ",".join("?" * len(chunk)), chunk)
    res = {"retired": len(go), "kept_picked": sum(1 for x in over if x["picked"]),
           "kept_pinned": sum(1 for x in over if x["pinned"] and not x["picked"])}
    if go:
        log_activity(db, actor_id, "career_targets", "Retired %d target role(s) above their job's ladder top "
                     "(%d kept: chosen as a next role or pinned by Group People)" % (res["retired"],
                                                                          res["kept_picked"] + res["kept_pinned"]))
    return res


def tc_grade_proficiency(g):
    """The proficiency level a grade's job asks for (the ladder accepted 2026-10-17, TC_LADDER_NOTE)."""
    return 3 if g <= 14 else 4 if g <= 17 else 5 if g <= 21 else 6


def tc_routes_ctx(db):
    """What tc_career_routes_arch reads about the whole architecture, read once (a download that walks every job, the career
    routes file, passes it as `ctx` so the walk is a few queries, not a few for each of ~960 jobs): the active job-code
    profiles (in the order the scan reads them), their place in the tree, their skill maps, HR's pins and hides by job,
    the taxonomy names and the ladder tops. The same reads, the same rows: a route worked out with it is the one worked out
    without it."""
    profs = [dict(r) for r in db.execute("SELECT * FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL")]
    over = {}
    for r in db.execute("SELECT from_profile_id, to_profile_id, kind FROM tc_career_routes"):
        over.setdefault(r["from_profile_id"], {})[r["to_profile_id"]] = r["kind"]
    return {"profiles": profs, "parts": {c["id"]: _ja_parts(c["job_code"]) for c in profs},
            "maps": tc_profile_skill_maps(db, [c["id"] for c in profs]), "overrides": over,
            "names": {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")},
            "tops": tc_ladder_tops(db)}


def tc_career_routes_arch(db, profile, have=None, limit=9, ctx=None):
    """Career routes for an architecture profile (one with a job code), read from the job architecture itself.
    `ctx` (tc_routes_ctx): the architecture already read, for a caller that works out every job's routes.

    Vertical: the same job (unit or specialisation) at higher grades; the nearest one is the person's next step
    (`next_step`), kept even when the ladder skips grades. Lateral: one route per other job in the same
    specialisation, then sub-family, then family, at the same grade or up to two above (the nearest grade that
    exists), ranked by how much of the current role's skill list carries over. Never a lower grade. HR's pinned and
    hidden overrides apply. Same row shape as the overlap scan, plus `route` (where it comes from) and `next_step`."""
    me = _ja_parts(profile["job_code"])
    if not me:
        return []
    overrides = ctx["overrides"].get(profile["id"], {}) if ctx else {r["to_profile_id"]: r["kind"] for r in db.execute(
        "SELECT to_profile_id, kind FROM tc_career_routes WHERE from_profile_id=?", (profile["id"],))}
    cands = []
    for c in (ctx["profiles"] if ctx else db.execute(
            "SELECT * FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL AND id!=?", (profile["id"],))):
        if ctx and c["id"] == profile["id"]:
            continue
        p = ctx["parts"][c["id"]] if ctx else _ja_parts(c["job_code"])
        kind = overrides.get(c["id"])
        if not p or kind == "hidden" or p["grade"] < me["grade"] or tc_not_a_career_route(c):   # even when pinned
            continue
        if p["base"] == me["base"] and p["grade"] > me["grade"]:
            rel = "vertical"
        elif p["base"] == me["base"]:
            rel = "spec"            # the same job code's other job scope (2026-10-18): a lateral move, never a next step
        elif (me["grade"] >= TC_LADDER_TOP - 1 and p["family"] == TC_LEADERSHIP_FAMILY and p["grade"] > TC_LADDER_TOP
              and me["grade"] + 1 <= p["grade"] <= me["grade"] + 2 and kind != "pinned"):
            # (from JG 19 too, two grades up: an Assistant General Manager sees the JG 21 roles; Chris, 2026-10-19)
            # the leadership step, for everyone from the top of the normal ladder (Chris, 2026-10-19, option B of canvas
            # [design canvas link removed]): JG 20 to the Director and C-suite roles, 21 to the
            # BU CEO roles, 22 to the BG CEO and Group C-suite roles, whatever family they're in; up to two grades up,
            # like every other route (Chris, 2026-10-19: "allow up to 2 job grades selection for user")
            rel = "leader"
        elif p["grade"] > me["grade"] + 2 and kind != "pinned":
            continue
        elif p["spec"] == me["spec"]:
            rel = "spec"
        elif p["sub"] == me["sub"]:
            rel = "sub"
        elif p["family"] == me["family"]:
            rel = "family"
        elif kind == "pinned":
            rel = "pinned"
        else:
            continue
        cands.append((dict(c), p, rel, kind))
    maps = ctx["maps"] if ctx else tc_profile_skill_maps(db, [profile["id"]] + [c[0]["id"] for c in cands])
    mine = maps.get(profile["id"])
    if mine is None:   # a profile the context did not read (not active, or no job code)
        mine = tc_profile_skill_maps(db, [profile["id"]])[profile["id"]]
    names = ctx["names"] if ctx else {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}
    nearest_up = min((p["grade"] for _c, p, rel, _k in cands if rel == "vertical"), default=None)
    # their own job up to two grades up (Chris, 2026-10-19: "a senior executive should be able to pick assistant manager
    # or manager"), the nearest kept wherever it sits; a grade further up would only take a place the card then drops
    cands = [x for x in cands if not (x[2] == "vertical" and x[1]["grade"] > me["grade"] + 2
                                      and x[1]["grade"] != nearest_up and x[3] != "pinned")]
    # one lateral route per other job: its nearest grade at or above the person's
    best_grade = {}
    for _c, p, rel, _k in cands:
        if rel not in ("vertical", "pinned"):
            best_grade[p["base"]] = min(best_grade.get(p["base"], 99), p["grade"])
    # where their own job's ladder stops at their grade (tc_ladder_tops) with nothing exactly one grade up, the jobs
    # beside it in the specialisation and sub-family also offer their role one grade up: the next job (Chris,
    # 2026-10-19, "nearest role up"; an inspector of work at JG 14 -> Assistant Manager, Project QA/QC at JG 15). The
    # architecture puts them side by side, so no skills share is asked of it. A ladder that only skips a grade below its
    # top keeps its own next step; from JG 20 the leadership track takes over.
    own_up = nearest_up == me["grade"] + 1
    stops = TC_LADDER_TOP > me["grade"] >= tc_ladder_top(ctx["tops"] if ctx else tc_ladder_tops(db), me["base"])
    out = []
    for c, p, rel, kind in cands:
        next_job = (stops and not own_up and rel in ("spec", "sub") and p["grade"] == me["grade"] + 1
                    and p["base"] != me["base"])
        if (rel not in ("vertical", "pinned") and p["grade"] != best_grade[p["base"]] and kind != "pinned"
                and not next_job):
            continue
        theirs = maps.get(c["id"]) or {}
        if not theirs:
            continue
        shared = set(mine) & set(theirs)
        overlap = len(shared) / float(len(mine)) if mine else 0.0
        if (rel in TC_ARCH_ROUTE_OVERLAP and overlap < TC_ARCH_ROUTE_OVERLAP[rel] and kind != "pinned"
                and not next_job):
            continue
        if rel == "vertical":
            score = 3.0 - 0.1 * (p["grade"] - me["grade"])
        else:
            score = {"spec": 2.0, "leader": 1.8, "sub": 1.5, "family": 1.0, "pinned": 1.0}[rel] + overlap
        row = {"profile": c, "overlap": int(round(overlap * 100)), "shared": len(shared),
               "new": len(set(theirs) - shared),
               "track_move": (names.get(p["spec"]) or p["spec"]) if p["spec"] != me["spec"] else None,
               "lane": "deepen" if rel == "vertical" else "cross",
               "step": "up" if p["grade"] > me["grade"] else "same",
               "pinned": kind == "pinned", "score": score,
               "route": TC_ARCH_ROUTE_LABEL["pinned" if kind == "pinned" and rel == "pinned" else rel],
               "next_step": rel == "vertical" and p["grade"] == nearest_up,
               "next_job": next_job,
               "target": (c.get("source") or "") == "target"}   # a grade nobody holds yet (tc_fill_ladders)
        if have is not None:
            row["gap"] = tc_route_gap(db, have, c["id"])
        out.append(row)
    return _tc_rank_routes(out, have, limit)


def tc_ladder_gaps(db):
    """{base: [grades]}: the grades missing from each architecture job's own ladder -- every grade from the first one it
    holds to the top of its ladder (JG 20, or its own top: tc_ladder_tops) that no active profile of it holds. A job
    that starts above JG 20 (the leadership track) has none."""
    held = {}
    for r in db.execute("SELECT job_code FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL"):
        p = _ja_parts(r["job_code"])
        if p:
            held.setdefault(p["base"], set()).add(p["grade"])
    tops = tc_ladder_tops(db)
    out = {}
    for b, gs in held.items():
        miss = [g for g in range(max(min(gs), TC_LADDER_BOTTOM), tc_ladder_top(tops, b) + 1) if g not in gs]
        if miss:
            out[b] = miss
    return out


def _tc_target_title(src_title, g, discipline=""):
    """A job's title at grade g in the ladder's words: the level, then the discipline its own titles use ('Senior
    Manager, Design Engineering' at JG 18 gives 'Assistant General Manager, Design Engineering' at JG 19). A track that
    calls its early grades Engineer keeps that below management (Engineer, Senior Engineer)."""
    t = " ".join((src_title or "").split())
    head, _sep, rest = t.partition(",")
    disc = rest.strip() if _sep else (discipline or t)
    if not _sep and not discipline:
        # the job's own title stands in for its discipline: its seniority word is its level, not its discipline (Chris,
        # 2026-10-20: the JG 16 above a "Senior Site Supervisor" is "Manager, Site Supervisor")
        disc = re.sub(r"^senior\s+", "", disc, flags=re.I) or disc
    noun = TC_LADDER_LEVELS.get(g, "")
    if g <= 14 and "engineer" in head.lower():
        noun = "Senior Engineer" if g == 14 else "Engineer"
    return "%s, %s" % (noun, disc) if disc else noun


def tc_fill_ladders(db, actor_id=None):
    """Fill every job's ladder up to JG 20, or its own top (tc_ladder_tops) (Chris, 2026-10-19, option B of canvas
    [design canvas link removed]): each grade nobody holds becomes a TARGET ROLE, a profile with
    source 'target' and nobody resolving to it. Its title is the ladder's (_tc_target_title); its five are the nearest
    rung below's five (above, at the bottom of a ladder), at the level its grade asks for (tc_grade_proficiency) and the
    same five one level up (none past L6), as a draft for P&R. Idempotent: a grade that already has a profile is never
    touched. Returns {created, jobs}."""
    gaps = tc_ladder_gaps(db)
    if not gaps:
        return {"created": 0, "jobs": 0}
    by = {}
    for r in db.execute("SELECT * FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL ORDER BY id"):
        pp = _ja_parts(r["job_code"])
        if pp:
            by.setdefault(pp["base"], {}).setdefault(pp["grade"], []).append(dict(r))
    cur = {}
    for r in db.execute("SELECT ps.profile_id pid, s.skill_code, s.title FROM tc_job_profile_skills ps "
                        "JOIN tc_skills s ON s.id=ps.skill_id WHERE ps.is_future=0 ORDER BY ps.profile_id, ps.sort_order"):
        k = tc_comp_key(r["skill_code"], r["title"])
        if k not in cur.setdefault(r["pid"], []):
            cur[r["pid"]].append(k)
    levels = {}
    for r in db.execute("SELECT id, skill_code, title, level FROM tc_skills WHERE active=1"):
        if r["level"]:
            levels.setdefault(tc_comp_key(r["skill_code"], r["title"]), {})[int(r["level"])] = r["id"]
    names = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}
    taken = {((r[0] or "").strip().lower(), (r[1] or "").strip().lower(), str(r[2] or "").strip())
             for r in db.execute("SELECT department, job_title, job_grade FROM tc_job_profiles")}
    made = 0
    for base, missing in sorted(gaps.items()):
        rungs = by.get(base) or {}
        spec = (_ja_parts("%s-12" % base) or {}).get("spec")
        for g in missing:
            near = max((x for x in rungs if x < g), default=None)
            if near is None:
                near = min(x for x in rungs if x > g)
            src = sorted(rungs[near], key=lambda r: ((r.get("source") or "") == "target", -len(cur.get(r["id"], [])),
                                                     r["id"]))[0]
            title = _tc_target_title(src["job_title"], g, names.get(base) or names.get(spec) or "")
            dept = src["department"] or ""
            code = "%s-%d" % (base, g)
            # a retired profile can still hold this job code (an earlier mapping's, deactivated by a later import): the
            # target role takes that row over rather than meeting it on the (job code, scope) index (staging, 2026-10-19)
            old = db.execute("SELECT id, department, job_title, job_grade FROM tc_job_profiles WHERE job_code=? AND "
                             "COALESCE(job_scope,'')='' AND active=0 ORDER BY id LIMIT 1", (code,)).fetchone()
            if old:
                taken.discard(((old["department"] or "").strip().lower(), (old["job_title"] or "").strip().lower(),
                               str(old["job_grade"] or "").strip()))
            if (dept.strip().lower(), title.lower(), str(g)) in taken:
                title = "%s (%s)" % (title, base)
            taken.add((dept.strip().lower(), title.lower(), str(g)))
            want = tc_grade_proficiency(g)
            rows = []
            for fam in cur.get(src["id"], [])[:TC_FIVE]:
                lv = levels.get(fam) or {}
                if not lv:
                    continue
                now = want if want in lv else min(lv, key=lambda L: (abs(L - want), -L))
                nxt = min(now + 1, 6)
                rows.append((lv[now], now, lv.get(nxt), nxt))
            if old:
                pid = old["id"]
                db.execute("UPDATE tc_job_profiles SET department=?, job_title=?, job_grade=?, plan_mode='explicit', "
                           "review_status='draft', reviewed_by=NULL, reviewed_at=NULL, content_hash=NULL, arch_version=?, "
                           "source='target', active=1, updated_at=datetime('now') WHERE id=?",
                           (dept, title, str(g), src.get("arch_version"), pid))
                db.execute("DELETE FROM tc_job_profile_skills WHERE profile_id=?", (pid,))
            else:
                pid = db.execute(
                    "INSERT INTO tc_job_profiles(department, job_title, job_grade, plan_mode, review_status, arch_version, "
                    "job_code, source, active) VALUES (?,?,?,'explicit','draft',?,?,'target',1)",
                    (dept, title, str(g), src.get("arch_version"), code)).lastrowid
            for i, (sid, now, fid, nxt) in enumerate(rows):
                db.execute("INSERT INTO tc_job_profile_skills(profile_id, skill_id, required_level, sort_order, is_future) "
                           "VALUES (?,?,?,?,0)", (pid, sid, now, i))
                if fid and fid != sid:   # at L6 there is no level up: no future row (one row a skill a profile)
                    db.execute("INSERT INTO tc_job_profile_skills(profile_id, skill_id, required_level, sort_order, "
                               "is_future) VALUES (?,?,?,?,1)", (pid, fid, nxt, i))
            rungs.setdefault(g, []).append({"id": pid, "job_title": title, "department": dept, "source": "target",
                                            "arch_version": src.get("arch_version")})
            cur[pid] = [k for k in cur.get(src["id"], [])[:TC_FIVE]]
            made += 1
    db.commit()
    log_activity(db, actor_id, "career_targets", "Filled %d grade(s) in %d job(s) as target roles, up to JG %d "
                 "(or the job's own top)" % (made, len(gaps), TC_LADDER_TOP))
    return {"created": made, "jobs": len(gaps)}


def tc_career_tree(db):
    """The career routes page in one read (canvas board 1): {families: [{code, name, n, subs: [{code, name, jobs}]}],
    jobs: {base: job}, check: {...}}. A job (an architecture unit or specialisation) carries its rungs by grade -- each
    rung its profiles (title, scope, people, target) -- its first and top grade, the grades still missing, its target
    roles and people. The leadership family sorts first: the tree reads from the top."""
    holders = _tc_profile_holders(db)
    names = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}
    jobs = {}
    for r in db.execute("SELECT id, job_code, job_scope, job_title, job_grade, source, review_status FROM tc_job_profiles "
                        "WHERE active=1 AND job_code IS NOT NULL ORDER BY job_code, id"):
        pp = _ja_parts(r["job_code"])
        if not pp:
            continue
        j = jobs.setdefault(pp["base"], {"base": pp["base"], "family": pp["family"], "sub": pp["sub"], "spec": pp["spec"],
                                         "rungs": {}, "people": 0, "targets": 0})
        n = len(holders.get(r["id"]) or [])
        target = (r["source"] or "") == "target"
        j["rungs"].setdefault(pp["grade"], []).append({"id": r["id"], "title": r["job_title"], "scope": r["job_scope"],
                                                       "people": n, "target": target,
                                                       "status": r["review_status"] or "draft"})
        j["people"] += n
        j["targets"] += 1 if target else 0
    gaps = tc_ladder_gaps(db)
    tops = tc_ladder_tops(db)
    lead = {}
    for j in jobs.values():
        gs = sorted(j["rungs"])
        j["lo"], j["hi"] = gs[0], gs[-1]
        j["missing"] = gaps.get(j["base"], [])
        j["top"] = tc_ladder_top(tops, j["base"])
        j["top_kind"] = (tops.get(j["base"]) or {}).get("kind") or ""
        first = j["rungs"][gs[0]][0]["title"]
        j["name"] = names.get(j["base"]) or names.get(j["spec"]) or (first.partition(",")[2].strip() or first)
        if j["family"] == TC_LEADERSHIP_FAMILY:
            for g, ps in j["rungs"].items():
                for p_ in ps:
                    if p_["title"] not in lead.setdefault(g, []):
                        lead[g].append(p_["title"])
    fams = {}
    for j in jobs.values():
        f = fams.setdefault(j["family"], {"code": j["family"], "name": names.get(j["family"]) or j["family"], "subs": {}})
        f["subs"].setdefault(j["sub"], {"code": j["sub"], "name": names.get(j["sub"]) or j["sub"], "jobs": []})["jobs"].append(j)
    families = []
    for f in sorted(fams.values(), key=lambda f: (f["code"] != TC_LEADERSHIP_FAMILY, f["name"].lower())):
        subs = sorted(f["subs"].values(), key=lambda x: x["name"].lower())
        for sb in subs:
            sb["jobs"].sort(key=lambda j: j["name"].lower())
        families.append({"code": f["code"], "name": f["name"], "subs": subs, "n": sum(len(x["jobs"]) for x in subs),
                         "lead": f["code"] == TC_LEADERSHIP_FAMILY})
    check = {"jobs": len(jobs), "targets": sum(j["targets"] for j in jobs.values()),
             "missing": sum(len(j["missing"]) for j in jobs.values()),
             "complete": sum(1 for j in jobs.values() if not j["missing"] and j["lo"] <= TC_LADDER_BOTTOM
                             and j["hi"] >= j["top"]),
             "capped": sum(1 for j in jobs.values() if j["top"] < TC_LADDER_TOP),
             "lead_roles": sum(len(v) for g, v in lead.items() if g > TC_LADDER_TOP)}
    return {"families": families, "jobs": jobs, "check": check, "lead": lead}


def tc_career_routes_for(db, profile, have=None, limit=9, ctx=None):
    """Roles reachable from `profile`, ranked, with HR's overrides applied.

    An architecture profile (one with a job code) reads its routes from the architecture
    (tc_career_routes_arch). A legacy profile keeps the overlap scan below.

    Overlap is measured against the CURRENT role's skill list -- "how much of
    what my job already asks of me carries over" is the question the employee
    is actually asking. That ratio is deliberately not symmetric, so a Jaccard
    would quietly answer a different question and rank broad roles too highly.

    A step DOWN in grade is never offered: this is a progression map, and a
    demotion arriving as a suggestion reads as a message about your standing.
    """
    if "job_code" in profile.keys() and profile["job_code"]:
        return tc_career_routes_arch(db, profile, have=have, limit=limit, ctx=ctx)
    mine = tc_profile_skill_map(db, profile["id"])
    if not mine:
        return []
    overrides = {r["to_profile_id"]: r["kind"] for r in db.execute(
        "SELECT to_profile_id, kind FROM tc_career_routes WHERE from_profile_id=?",
        (profile["id"],))}
    here = _jg_rank(profile["job_grade"])
    out = []
    # The demo career ladder (tagged _CAREER_DEMO_SOURCE) is for the demo picker only -- never
    # surface it in a real employee's architecture-derived career map.
    for cand in db.execute(
            "SELECT * FROM tc_job_profiles WHERE active=1 AND id!=? "
            "AND (source IS NULL OR source!=?) AND job_code IS NULL",
            (profile["id"], _CAREER_DEMO_SOURCE)):
        kind = overrides.get(cand["id"])
        if kind == "hidden" or tc_not_a_career_route(cand):
            continue
        there = _jg_rank(cand["job_grade"])
        if there < here:
            continue
        theirs = tc_profile_skill_map(db, cand["id"])
        if not theirs:
            continue
        shared = set(mine) & set(theirs)
        overlap = len(shared) / float(len(mine))
        same_track = bool(profile["ssg_track"]) and cand["ssg_track"] == profile["ssg_track"]
        if kind != "pinned" and overlap < TC_ROUTE_MIN_OVERLAP and not same_track:
            continue
        score = overlap
        if same_track:
            score += 0.25
        if profile["ssg_sector"] and cand["ssg_sector"] == profile["ssg_sector"]:
            score += 0.10
        if (cand["department"] or "") == (profile["department"] or ""):
            score += 0.05
        row = {
            "profile": dict(cand), "overlap": int(round(overlap * 100)),
            "shared": len(shared), "new": len(set(theirs) - shared),
            # Where this role sits relative to the CURRENT one's track. Kept on
            # the card rather than as a second grouping axis: readiness is what
            # people plan around, and two competing groupings on one screen
            # makes neither of them readable.
            "track_move": (cand["ssg_track"] if (cand["ssg_track"]
                           and cand["ssg_track"] != profile["ssg_track"]) else None),
            # Two different questions, deliberately kept apart. `lane` is the
            # one people plan around -- go deeper in the discipline I'm in, or
            # cross into another one -- and it comes from the SSG track, not
            # the grade. `step` is just how the grade moves, shown on the card:
            # keying the lanes off grade instead put every specialist role that
            # happens to sit a grade up into "a step up" and left the sideways
            # lane permanently empty, which told the reader nothing.
            "lane": "deepen" if same_track else "cross",
            "step": "up" if there > here else "same",
            "pinned": kind == "pinned", "score": score,
        }
        if have is not None:
            row["gap"] = tc_route_gap(db, have, cand["id"])
        out.append(row)
    return _tc_rank_routes(out, have, limit)


# The label a role Group People suggested for one person carries (route, and the tag on the person's role card:
# journey_chat.js capitalises it). A person-level pin, as "suggested by HR" is a job-level one.
TC_PERSON_ROUTE_LABEL = "suggested by Group People"


def tc_person_suggested_routes(db, u, here, have=None):
    """The roles Group People suggested for THIS person (tc_person_routes), as route rows shaped like
    tc_career_routes_arch's (profile, overlap, shared, new, lane, step, pinned, route, next_step, next_job, readiness,
    group, gap), active architecture roles only. `route` is TC_PERSON_ROUTE_LABEL; `pinned` and `suggested` are True so a
    limit never cuts one. `here` is their placed job's profile (None when they have none: nothing then shares). A
    suggestion that has since fallen below their grade is returned all the same: _career_cap_grades drops it from what
    they are offered. One batched skills read; the job's routes are tc_career_routes_for's, not read here."""
    rows = db.execute(
        "SELECT p.* FROM tc_person_routes r JOIN tc_job_profiles p ON p.id=r.to_profile_id "
        "WHERE r.subject_id=? AND p.active=1 AND p.job_code IS NOT NULL ORDER BY r.id", (u["id"],)).fetchall()
    if not rows:
        return []
    maps = tc_profile_skill_maps(db, ([here["id"]] if here else []) + [r["id"] for r in rows])
    mine = maps.get(here["id"], {}) if here else {}
    me = _ja_parts(here["job_code"]) if here and "job_code" in here.keys() and here["job_code"] else None
    here_g = _jg_rank(here["job_grade"]) if here else None
    out = []
    for c in rows:
        p = _ja_parts(c["job_code"]) or {}
        theirs = maps.get(c["id"]) or {}
        shared = set(mine) & set(theirs)
        overlap = len(shared) / float(len(mine)) if mine else 0.0
        there = _jg_rank(c["job_grade"])
        spec_move = bool(p) and bool(me) and p.get("spec") != me["spec"]
        row = {"profile": dict(c), "overlap": int(round(overlap * 100)), "shared": len(shared),
               "new": len(set(theirs) - shared),
               "track_move": (db.execute("SELECT name FROM ja_taxonomy WHERE code=?", (p["spec"],)).fetchone() or
                              {"name": p["spec"]})["name"] if spec_move else None,
               "lane": "cross", "step": "up" if here_g is None or there > here_g else "same",
               "pinned": True, "suggested": True, "score": 2.0 + overlap, "route": TC_PERSON_ROUTE_LABEL,
               "next_step": False, "next_job": False, "target": (c["source"] or "") == "target"}
        if have is not None:
            row["gap"] = tc_route_gap(db, have, c["id"])
        out.append(row)
    return _tc_rank_routes(out, have, len(out))


# The label a role the person already holds 3 or more of the 5 competencies of carries (Chris, 2026-11-08, canvas
# [design canvas link removed], "Yes, as drawn"); journey_chat.js capitalises it: "Skills match".
TC_SKILLS_MATCH_ROUTE_LABEL = "skills match"
TC_SKILLS_MATCH_MIN = 3      # at least this many of the role's competencies held at the level it needs ...
TC_SKILLS_MATCH_SHARE = 0.6  # ... and at least this share of them
TC_SKILLS_MATCH_CAP = 3      # the most Skills match roles one person is shown


def tc_person_skills_match_routes(db, u, here, offered_ids, held, basis=None):
    """The Skills match route (Chris, 2026-11-08): up to TC_SKILLS_MATCH_CAP roles in the person's OWN job family, from
    their grade to two grades up, where they already hold at least TC_SKILLS_MATCH_MIN of the role's competencies (and
    TC_SKILLS_MATCH_SHARE of them) at the level it needs, and that today's routes do not offer (`offered_ids`: the
    job's routes and Group People's suggestions, which keep their own tags and are never doubled). Row shape of
    tc_person_suggested_routes plus `skills_match` / `match` / `total`; `route` is TC_SKILLS_MATCH_ROUTE_LABEL, `pinned`
    False. `held` is _career_person_held (the role card's own rule, so card and route cannot disagree). Nothing for a
    person with no placed job, with nothing assessed (no `basis`, _career_person_basis) or a demo account. Never
    the recommended step: it is an aim, never a promotion. One batched read of the roles' competencies."""
    if not here or not here["job_code"] or is_demo_account(u):
        return []
    me = _ja_parts(here["job_code"])
    if not me:
        return []
    if basis is None:
        basis = _career_person_basis(db, u, here, held)[1]
    if not basis:
        return []
    g = _jg_rank(u["job_grade"]) if u["job_grade"] is not None else _jg_rank(here["job_grade"])
    if g <= 0:
        return []
    hidden = {r[0] for r in db.execute(
        "SELECT to_profile_id FROM tc_career_routes WHERE from_profile_id=? AND kind='hidden'", (here["id"],))}
    skip = set(offered_ids or ()) | hidden | {here["id"]}
    cands = []
    for c in db.execute("SELECT * FROM tc_job_profiles WHERE active=1 AND job_code LIKE ? AND (source IS NULL OR source!=?)",
                        (me["family"] + "-%", _CAREER_DEMO_SOURCE)):
        p = _ja_parts(c["job_code"])
        if (not p or p["family"] != me["family"] or c["id"] in skip or tc_not_a_career_route(c)
                or not 0 <= _jg_rank(c["job_grade"]) - g <= 2):
            continue
        cands.append(c)
    if not cands:
        return []
    comps = _career_role_competencies(db, [c["id"] for c in cands])
    found = []
    for c in cands:
        rows = comps.get(c["id"]) or []
        total = len(rows)
        match = sum(1 for t, need in rows if held.get(t, -1) >= need)
        if total and match >= TC_SKILLS_MATCH_MIN and match / float(total) >= TC_SKILLS_MATCH_SHARE:
            found.append((c, match, total))
    found.sort(key=lambda x: (-x[1], _jg_rank(x[0]["job_grade"]), x[0]["job_title"] or ""))
    found = found[:TC_SKILLS_MATCH_CAP]
    if not found:
        return []
    maps = tc_profile_skill_maps(db, [here["id"]] + [c["id"] for c, _m, _t in found])
    mine = maps.get(here["id"], {})
    here_g = _jg_rank(here["job_grade"])
    specs = {_ja_parts(c["job_code"])["spec"] for c, _m, _t in found} - {me["spec"]}
    names = ({r["code"]: r["name"] for r in db.execute(
        "SELECT code, name FROM ja_taxonomy WHERE code IN (%s)" % ",".join("?" * len(specs)), sorted(specs))}
        if specs else {})
    have_map = held   # the gap's rows read the same figures the match was counted on
    out = []
    for c, match, total in found:
        p = _ja_parts(c["job_code"])
        theirs = maps.get(c["id"]) or {}
        shared = set(mine) & set(theirs)
        overlap = len(shared) / float(len(mine)) if mine else 0.0
        out.append({"profile": dict(c), "overlap": int(round(overlap * 100)), "shared": len(shared),
                    "new": len(set(theirs) - shared),
                    "track_move": (names.get(p["spec"]) or p["spec"]) if p["spec"] != me["spec"] else None,
                    "lane": "cross", "step": "up" if _jg_rank(c["job_grade"]) > here_g else "same", "pinned": False,
                    "score": match / float(total), "route": TC_SKILLS_MATCH_ROUTE_LABEL,
                    "next_step": False, "next_job": False, "target": (c["source"] or "") == "target",
                    "skills_match": True, "match": match, "total": total,
                    "gap": tc_route_gap(db, have_map, c["id"], need=theirs)})
    # readiness and group as every other row (_tc_rank_routes), then THIS route's own order: the best match, then the
    # lower grade, then the title -- the order the candidate list shows them in
    out = _tc_rank_routes(out, have_map, len(out))
    out.sort(key=lambda r: (-r["match"], _jg_rank(r["profile"]["job_grade"]), r["profile"]["job_title"] or ""))
    return out


def tc_career_routes_for_person(db, u, here, have=None, limit=9, held=None, basis=None):
    """The roles ONE person's Career Plan offers: the routes their job offers (tc_career_routes_for, when they have a
    placed job `here`) and, after them, the roles Group People suggested for them alone (tc_person_suggested_routes).
    The suggestions come AFTER the job's limit, so one is never cut; a suggestion their job already offers is not
    doubled: that row takes the person's label and flag (its `next_step` and `base_route` stay, so the recommended step
    stays the job's route; since 2026-11-08 a suggestion one grade up is the recommended step, _career_recommended). Last
    come the Skills match roles (tc_person_skills_match_routes, 2026-11-08): roles in their own family where they hold
    3 or more of the 5 competencies, none of them a role already offered above, so they too come after the limit and
    are never doubled. `held` / `basis` are _career_person_held / _career_person_basis's, read here when a caller has
    not (`have` is the reviewed-only map the other rows' gaps read). The person-level readers use this (the chat's career map, the candidate roles; the
    employee's career page); the job-level ones (the career tree, Chairman) keep tc_career_routes_for."""
    base = tc_career_routes_for(db, here, have=have, limit=limit) if here else []
    sugg = tc_person_suggested_routes(db, u, here, have=have)
    by_id = {r["profile"]["id"]: r for r in base}
    extra = []
    for sg in sugg:
        hit = by_id.get(sg["profile"]["id"])
        if hit is None:
            extra.append(sg)
        else:
            hit["base_route"] = hit.get("route")
            hit.update(route=TC_PERSON_ROUTE_LABEL, pinned=True, suggested=True)
    rows = base + extra
    if here and not is_demo_account(u):
        if held is None:
            held = _career_person_held(db, u["id"])
        rows = rows + tc_person_skills_match_routes(db, u, here, {r["profile"]["id"] for r in rows}, held, basis=basis)
    return rows


def pm_career_profile_for(db, subject_id, create=False):
    """This person's career profile, or None. Keyed on the person alone -- there
    is no period dimension and no status, so unlike the IDP there's nothing to
    resolve here beyond 'does a row exist yet'."""
    row = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?",
                     (subject_id,)).fetchone()
    if row is None:
        if not create:
            return None
        db.execute("INSERT INTO pm_career_profile(subject_id) VALUES (?)", (subject_id,))
        db.commit()
        row = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?",
                         (subject_id,)).fetchone()
    return dict(row)


def pm_career_save_field(db, subject_id, field, value, as_admin=False):
    """Write ONE validated career-profile field. Returns (ok, error).

    THE ONE WRITE PATH for the profile, shared by the page's autosave, the
    check-in agent's save_career tool and the career agent's set_field. It used
    to be two: idp_career_autosave capped at 4000 characters and the agent tool
    at 2000, so the same answer was stored differently depending on which
    surface the person happened to be on. Unified on the page's 4000 -- the
    looser of the two, because the tighter one was silently truncating text the
    product elsewhere accepted.

    `value=None` clears the field (what the page does with an emptied box); a
    caller that must not clear checks for that itself before calling.

    `as_admin` (the person page, 2026-10-10): HR correcting a profile on the person's behalf is not held to the
    person's own window or the share lock -- the validation still applies, and the caller logs it as HR's.
    """
    if not as_admin:
        _w = window_closed(db, "idp_self")
        if _w:
            return False, _w
        _t, _serr = _store_text(value or "")   # the person's own words, whichever surface they came through (4-03)
        if _serr:
            return False, _serr
    if field not in PM_CAREER_FIELDS:
        return False, "unknown career field"
    # Locked with the plan it belongs to (Chris, 2026-09-28): once the Career Plan is shared, "where you
    # want to go" and "how far you'd move" are final too. Every profile write comes through here.
    _owner = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    if not as_admin and _owner is not None and _career_locked(db, _owner):
        return False, _CAREER_LOCKED_ERROR
    if field == "mobility" and value is not None and value not in PM_CAREER_MOBILITY_KEYS:
        return False, ("mobility must be one of %s" % ", ".join(PM_CAREER_MOBILITY_KEYS))
    if value is not None:
        value = value[:4000]
    pm_career_profile_for(db, subject_id, create=True)
    db.execute("UPDATE pm_career_profile SET %s=?, updated_at=datetime('now') "
               "WHERE subject_id=?" % field, (value, subject_id))
    db.commit()
    return True, None


_CAREER_LOCKED_ERROR = ("your career plan is shared with your manager and locked -- it can't be changed now")


def _career_locked(db, u):
    """True once the person's current Career Plan is shared (or closed): the profile is locked with it
    (Chris, 2026-09-28). Keyed on the active period's plan year -- the plan the journey shows -- so a new
    plan year (a fresh draft) opens the profile again."""
    # The ACTIVE period's plan year (the one every write is guarded to), read directly so this holds outside a
    # request too -- _idp_context's viewed period reads ?period=.
    period = active_pm_period(db)
    if not period:
        return False
    idp = pm_idp_for(db, pm_idp_plan_year(period), _row_get(u, "id"), create=False)
    # A profile still missing its two answers stays open, so a plan shared before the share gate existed can still be
    # finished (review, 2026-09-28); once complete, it locks with the plan.
    return pm_idp_is_shared(idp) and pm_career_is_complete(db, _row_get(u, "id"))


def pm_career_conversation_for(db, plan_year, subject_id):
    """The recorded career conversation about this PLAN YEAR, or None. Keyed
    the same way the plan is, because this is what closes it."""
    row = db.execute(
        "SELECT c.*, u.full_name AS recorded_by_name FROM pm_career_conversations c "
        "LEFT JOIN users u ON u.id = c.recorded_by "
        "WHERE c.plan_year=? AND c.subject_id=?", (plan_year, subject_id)).fetchone()
    return dict(row) if row else None


def pm_idp_close(db, plan_year, subject_id, closed_by, reason):
    """Close this person's plan for the year. Returns the status it was in
    before, or None if there was no plan at all.

    The career conversation is the normal path and an admin close is the
    backstop, so this is one function rather than two: whatever closes a plan
    stamps it the same way, and 'closed' means the same thing either way. Only
    the activity log distinguishes them.

    A plan still in DRAFT closes too. That reads odd -- the manager never saw
    it -- but the alternative is worse: the conversation happened, the window
    is over, and leaving it editable forever would mean the plan for a year
    that has started is still being written."""
    idp = db.execute("SELECT id, status FROM pm_idp WHERE plan_year=? AND subject_id=?",
                     (plan_year, subject_id)).fetchone()
    if not idp or idp["status"] == "closed":
        return idp["status"] if idp else None
    db.execute("UPDATE pm_idp SET status='closed', closed_at=datetime('now'), "
               "closed_by=?, updated_at=datetime('now') WHERE id=?",
               (closed_by, idp["id"]))
    _reopen_close(db, subject_id, ["idp_review"])   # closed again, by whoever: HR's reopen of the close is done
    _late_close(db, closed_by, "idp_review", "used", subject_id=subject_id)   # a late pass's line manager follow-on
    log_activity(db, closed_by, "idp_close", f"{plan_year}: {reason}",
                 target_user_id=subject_id)
    return idp["status"]


def pm_career_mobility_label(key):
    return next((m["label"] for m in PM_CAREER_MOBILITY if m["key"] == key), None)


def pm_idp_plan_year(period):
    """Which year the plan on screen is FOR, given the period in view.

    A development plan is forward-looking (confirmed): you write it at
    Year-End for the year ahead, then spend that year working it.

        Year-End 2026  -> the 2027 plan   (write it)
        Mid-Year 2027  -> the 2027 plan   (read it, check in on it)
        Year-End 2027  -> the 2028 plan   (write it)

    So Year-End looks forward a year and Mid-Year looks at the year it is
    already in. One rule, used by every IDP surface, so the page title, the
    write gates and the manager's review can't disagree about which plan is
    being discussed."""
    # a cycle can be started with no year (the form allows it): no plan year then, rather than a TypeError that took
    # the admin Home down with it (the admin review, 2026-10-13)
    if not period or period["year"] is None:
        return None
    return period["year"] + 1 if _is_year_end(period) else period["year"]


def _is_year_end(period):
    """Is this period the second half of its year?

    Exists because `cycles.half` is stored as an INTEGER (1 or 2) since the
    pm_periods -> cycles merge, while both IDP helpers still compared it to the
    string "HY2". `2 == "HY2"` is False in Python, so pm_idp_is_authoring()
    returned False for every period ever, pm_idp_can_edit() refused
    unconditionally, and all six IDP write paths -- autosave, suggest,
    progress, submit, draft-AI and the dashboard task -- have been closed since
    the merge. Nothing errored; the feature simply stopped.

    Accepts the legacy string too: a period row assembled by older code, or a
    caller passing a plain dict in a test, must not silently answer False
    again. That is exactly how this got missed the first time."""
    if not period:
        return False
    h = period["half"]
    if h is None:
        return False
    if isinstance(h, str):
        h = h.strip().upper()
        return h in ("2", "HY2", "H2")
    return int(h) == 2


# Templates get the SAME rule rather than a second copy of it. performance_my.html
# carried its own `p['half'] == 'HY2'` until 2026-08-28 and therefore labelled every
# Year-End cycle "Mid-Year" -- the identical 2 == "HY2" defect this helper exists to
# have fixed, surviving in Jinja because the Phase 0 sweep only looked at Python.
# A lint in tests/test_demo_seed.py now fails any template that compares half to a
# string, so the next copy cannot be written silently.
app.jinja_env.globals["is_year_end"] = _is_year_end


def chat_window_note(cell):
    """The closed-window sentence for the signed-in person's own part `cell`, or '' (a per-part assistant's page locks its
    box on it; Chris, 2026-10-20)."""
    u = current_user()
    return (window_closed(get_db(), cell, subject_id=u["id"]) or "") if u else ""


app.jinja_env.globals["chat_window_note"] = chat_window_note


def pm_idp_is_authoring(period):
    """True when the period in view is the one plans are WRITTEN in -- i.e.
    Year-End. Mid-Year is deliberately not an authoring period: the plan for
    that year was agreed the previous Year-End, and mid-year is when you check
    in on it, not rewrite it. Confirmed cadence: one plan per person per year."""
    return bool(period) and _is_year_end(period)


def pm_idp_can_check_in(idp, is_active_period):
    """True while the employee may update PROGRESS (not plan content): the plan
    is out of draft and the period is still the active one. Separate from
    pm_idp_can_edit() on purpose -- those two are mutually exclusive, which is
    what makes an agreed plan's goals fixed while its progress stays live.

    Note this is gated on the ACTIVE period, not the authoring one -- checking
    in during Mid-Year on a plan agreed last Year-End is the main thing this
    exists for."""
    if not is_active_period or not idp:
        return False
    # DEAD UNTIL 2026-08-28. This read ("submitted", "agreed") -- the statuses
    # the vocabulary migration renamed away. The CHECK constraint allows only
    # ('draft','shared','closed') and the migration rewrote every row, so this
    # could never return True and POST /idp/progress has ALWAYS answered 409.
    # Nothing errored; the check-in path simply did not exist.
    #
    # Exactly the 2 == "HY2" bug Phase 0 fixed, in a second place: a rename that
    # moved the SQL and left a Python predicate reading the old vocabulary. Found
    # while mapping Phase C, and fixed here rather than there because shipping a
    # stage called "Check in" beside a dead helper called can_check_in is how the
    # next person loses a day.
    return idp.get("status") in ("shared", "closed")


def pm_idp_is_shared(idp):
    """True once the plan has been shared -- i.e. the employee's own authoring
    work is done, whether or not the career conversation has closed it. Since
    2026-09-28 a shared plan is also LOCKED (see pm_idp_can_edit), and so is the
    career profile that goes with it (_career_locked). The conversation's Ahead
    stage must not spell this out with a status literal of its own."""
    return bool(idp) and idp.get("status") in ("shared", "closed")


def pm_idp_can_edit(idp, is_authoring_period):
    """True while the employee may still edit their own plan: only while it is a DRAFT.

    Sharing LOCKS it (Chris, 2026-09-28: "lock the career plan once user agrees and click the final
    submit button"), the same as the KPI check-in and the TM self-assessment lock on submit. Until
    2026-09-28 a shared plan stayed editable until the manager's career conversation closed it; the
    final card's Edit button (before Share) is now where changes are made. Progress check-ins on a
    shared plan are a separate act (pm_idp_can_check_in) and stay open.

    Gated on the AUTHORING period rather than merely the active one: a plan is
    written once a year, at Year-End. Reaching Mid-Year with the plan still in
    draft doesn't reopen it -- the year it plans has already started."""
    if not is_authoring_period:
        return False
    return (idp or {}).get("status", "draft") == "draft"


def pm_idp_years_for(db, subject_id, period):
    """Plan years this person can reach, oldest first: every year they already
    have a plan for, plus the one the current period resolves to.

    Both matter at once at Year-End -- that is when you are still running this
    year's plan AND writing next year's -- so showing only the resolved year
    would hide the plan they are actually working. Mirrors My PM's switcher in
    shape, not in rule: that one deliberately shows a single year, because a
    scorecard has no equivalent overlap."""
    years = [r["plan_year"] for r in db.execute(
        "SELECT DISTINCT plan_year FROM pm_idp WHERE subject_id=? ORDER BY plan_year",
        (subject_id,)).fetchall()]
    current = pm_idp_plan_year(period)
    if current is not None and current not in years:
        years.append(current)
    return sorted(years)


def pm_idp_for(db, plan_year, subject_id, create=False, cycle_id=None):
    """This person's IDP row for a PLAN YEAR plus its ordered goals, or None.

    Keyed on the year the plan is for, never the period it was typed in --
    see pm_idp_plan_year(). `cycle_id` is recorded on create as authoring
    provenance only; nothing reads it to decide which plan is which.

    `create=True` inserts an empty draft -- used only by the write routes, so a
    plain page view never leaves a row behind for someone who just looked."""
    row = db.execute("SELECT * FROM pm_idp WHERE plan_year=? AND subject_id=?",
                     (plan_year, subject_id)).fetchone()
    if row is None:
        if not create:
            return None
        cur = db.execute(
            "INSERT INTO pm_idp(plan_year, cycle_id, subject_id) VALUES (?,?,?)",
            (plan_year, cycle_id, subject_id))
        db.commit()
        row = db.execute("SELECT * FROM pm_idp WHERE id=?", (cur.lastrowid,)).fetchone()
    idp = dict(row)
    idp["goals"] = [dict(g) for g in db.execute(
        "SELECT * FROM pm_idp_goals WHERE idp_id=? ORDER BY seq", (idp["id"],)).fetchall()]
    return idp


def pm_idp_share_validate(idp):
    """Why this plan cannot be shared yet -- a list of sentences -- plus the goals
    that actually count as filled.

    THE ONE SHARE GATE, used by the /idp page's Submit and by the Ahead agent's
    prepare_submit and submit alike. Extracted from idp_submit when the
    conversation arrived: a chat that tells someone their plan is ready while
    the page refuses it (or the reverse) is exactly the drift _tc_submit and
    _pm_setting_propose were pulled out to prevent. The rules themselves are
    unchanged -- how complete a plan must be is an admin setting.
    """
    def _any_action(g):
        return any((g[f] or "").strip() for f in PM_IDP_ACTION_FIELDS)

    action_rule, min_goals, max_goals, _ai_on = get_idp_settings()
    errors = []
    filled = [g for g in idp["goals"] if (g["area"] or "").strip() or _any_action(g)]
    if len(filled) < min_goals:
        errors.append("Add at least %d development goal%s before sharing it."
                      % (min_goals, "" if min_goals == 1 else "s"))
    if max_goals and len(filled) > max_goals:
        errors.append("This plan has %d goals and the limit is %d \u2014 fold the "
                      "smaller ones into a larger goal, or drop them."
                      % (len(filled), max_goals))
    for g in filled:
        label = (g["area"] or "").strip() or f"Goal {g['seq']}"
        if not (g["area"] or "").strip():
            errors.append(f"Goal {g['seq']}: name the area you want to develop.")
        # 'any' is the default: requiring the full 70:20:10 trio turns a prompt
        # into a quota, which the model's own evidence base doesn't support.
        # An admin can still choose 'all' -- the setting says what that costs.
        if action_rule == "any" and not _any_action(g):
            errors.append(f"'{label}': add at least one action \u2014 on the job, "
                          f"from others, or formal learning.")
        elif action_rule == "all":
            missing = [m["label"].lower() for m in PM_IDP_MODES
                       if not (g["action_" + m["key"]] or "").strip()]
            if missing:
                errors.append(f"'{label}': still needs {', '.join(missing)}.")
    return errors, filled


PM_IDP_SHARE_PROFILE_ERROR = ("Before you share, fill in where you want to go and how far you'd move -- sharing "
                              "locks your whole career plan, so they can't be added afterwards.")


def pm_idp_share_profile_error(db, subject_id):
    """The career profile's share gate: its two answers (an aspiration and a mobility -- pm_career_is_complete) must be
    in before the plan is shared, because sharing locks them. None when ready."""
    return None if pm_career_is_complete(db, subject_id) else PM_IDP_SHARE_PROFILE_ERROR


def pm_idp_share(db, u, period, idp):
    """Share the plan with the manager. Returns (ok, errors).

    Validates through pm_idp_share_validate() itself rather than trusting the
    caller to have done it, so neither the page nor the agent can reach the
    write with the gate skipped."""
    _w = window_closed(db, "idp_self")
    if _w:
        return False, [_w]
    errors, filled = pm_idp_share_validate(idp)
    if errors:
        return False, errors
    # Sharing LOCKS the whole Career Plan -- the profile with it (_career_locked, 2026-09-28) -- so a plan shared
    # while "where you want to go" or "how far you'd move" is blank can never be finished: the profile writes are
    # refused and the part never reads as done. Those two answers come first, on every share path.
    err = pm_idp_share_profile_error(db, _row_get(u, "id"))
    if err:
        return False, [err]
    # Drop rows the employee started and left entirely blank, so the manager
    # sees the plan they meant to send rather than empty scaffolding.
    for g in idp["goals"]:
        if g not in filled:
            db.execute("DELETE FROM pm_idp_goals WHERE id=?", (g["id"],))
    db.execute("UPDATE pm_idp SET status='shared', shared_at=datetime('now'), "
               "updated_at=datetime('now') WHERE id=?", (idp["id"],))
    _reopen_close(db, _row_get(u, "id"), ["idp_self"], actor_id=_row_get(u, "id"))   # HR's reopen is redone
    _late_close(db, _row_get(u, "id"), "idp_self", "used")   # a late pass is used (2026-10-31)
    _prerun_on_event(db, period["id"], [_row_get(u, "id")], "idp_share")   # its fit, read ahead (2026-10-09)
    db.commit()
    log_activity(db, u["id"], "idp_share",
                 f"{period['name']}: {len(filled)} goal(s)")
    return True, []


# A leadership behaviour counts as a gap below this much assessor agreement.
# A judgement call rather than a measured cut: at 60% a clear majority still
# said yes, so below it is where the feedback genuinely disagrees about the
# person. Bounded list because it feeds a prompt, and because a plan built
# from forty items is a plan nobody writes.
PM_IDP_GAP_PCT = 60
PM_IDP_MAX_ITEMS = 14


def pm_idp_attach_editors(db, goals):
    """Put a name on any goal a manager changed. Both sides of the plan show
    it -- the employee so an edit to their own document is never silent, the
    manager so they can see what they already touched."""
    ids = {g["edited_by"] for g in goals if g.get("edited_by")}
    names = {}
    if ids:
        ph = ",".join("?" * len(ids))
        names = {r["id"]: r["full_name"] for r in db.execute(
            f"SELECT id, full_name FROM users WHERE id IN ({ph})", list(ids))}
    for g in goals:
        g["edited_by_name"] = names.get(g.get("edited_by"))
    return goals


def pm_idp_gaps(db, subject):
    """Every competency gap this person's own assessments actually recorded,
    as grounded material for a development plan.

    Two sources, both things this person can already see for themselves:

      * leadership behaviours -- the weakest STATEMENTS from their released
        360, not just the weakest principles. Release-gated exactly as
        pm_idp_suggestions() is: feedback nobody has shown them must not
        arrive sideways through a suggestion.
      * technical competencies -- the ones their line manager's REVIEWED
        assessment left as not demonstrated. Unreviewed is deliberately
        excluded: an unchallenged self-rating is not a moderated gap, the same
        rule tc_reviewed_score() applies before letting the technical half
        count toward a band.

    `future` holds the stretch competencies -- assigned for the next
    proficiency level and not yet demonstrated. That is what a plan gets built
    from when nothing else came back: for someone whose assessments found no
    shortfall, "develop nothing" is the wrong answer and "grow into the next
    level" is the right one.

    Item ids are positional and only ever live inside one request -- they
    exist so the model can cite which items a goal covers and so the server
    can whitelist what it cites. Nothing persists them.
    """
    out = {"items": [], "future": [], "cycle_name": None, "tc_status": None}

    rel = db.execute(
        "SELECT c.id, c.name FROM report_releases rr JOIN cycles c ON c.id = rr.cycle_id "
        "WHERE rr.subject_id=? ORDER BY c.year DESC, c.half DESC, c.id DESC LIMIT 1",
        (subject["id"],)).fetchone()
    if rel:
        out["cycle_name"] = rel["name"]
        agreement, _n = statement_agreement(db, subject, rel["id"])
        weak = []
        for crit in agreement:
            for st in crit["statements"]:
                if not st["total"]:
                    continue
                pct = round(100.0 * st["yes"] / st["total"])
                if pct < PM_IDP_GAP_PCT:
                    weak.append({"pct": pct, "principle": crit["name"], "text": st["text"]})
        weak.sort(key=lambda w: w["pct"])
        # ONE development area per principle, not one per weak descriptor: a principle
        # carries 2 current + 2 future behaviours, so several can fall below the bar and
        # (rendered as label + "N% agreement", the descriptor text dropped) read as
        # duplicate lines. Keep the WEAKEST descriptor per principle -- weak is pct-sorted
        # ascending, so the first time we see a principle is its weakest.
        seen_principle, deduped = set(), []
        for w in weak:
            if w["principle"] in seen_principle:
                continue
            seen_principle.add(w["principle"])
            deduped.append(w)
        for i, w in enumerate(deduped[:PM_IDP_MAX_ITEMS]):
            out["items"].append({
                "id": "lp:%d" % i, "kind": "leadership", "label": w["principle"],
                "detail": w["text"], "note": "%d%% agreement" % w["pct"],
                "source": "leadership behaviour -- only %d%% of assessors agreed "
                          "this person shows it" % w["pct"]})

    cid = active_cycle_id(db)
    a = db.execute(
        "SELECT id, status FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
        (cid, subject["id"])).fetchone() if cid else None
    out["tc_status"] = a["status"] if a else None
    if a and _tc_status_eff(db, subject["id"], a["status"]) == "reviewed":   # or a submitted one nobody reviews (2026-11-06)
        rows = db.execute(
            "SELECT s.title, s.level, s.skill_category, s.proficiency_description, "
            "       t.is_future, sc.answer, sc.manager_answer "
            "FROM tc_assignments t JOIN tc_skills s ON s.id = t.skill_id "
            "LEFT JOIN tc_scores sc ON sc.assignment_id = t.id AND sc.assessment_id = ? "
            "WHERE t.cycle_id=? AND t.subject_id=? ORDER BY t.seq, t.id",
            (a["id"], cid, subject["id"])).fetchall()
        for i, r in enumerate(rows):
            # The manager's call where they made one -- the same "what stands"
            # rule _tc_rows() uses, so a gap here is a gap there.
            if (r["manager_answer"] or r["answer"]) == TC_ANSWER_DEMONSTRATE:
                continue
            item = {"id": "tc:%d" % i, "kind": "technical", "label": r["title"],
                    "detail": (r["proficiency_description"] or "")[:400],
                    "category": r["skill_category"]}
            if r["is_future"]:
                item["note"] = "next level"
                item["source"] = ("technical competency at the next proficiency level "
                                  "(level %s) -- a stretch, not a shortfall"
                                  % (r["level"] if r["level"] is not None else "?"))
                out["future"].append(item)
            else:
                item["note"] = "not demonstrated"
                item["source"] = ("technical competency your line manager's review "
                                  "left as not yet demonstrated")
                out["items"].append(item)
    return out


def pm_idp_readiness(db, subject):
    """The three inputs a development plan is built from, each with whether it
    has actually landed and where the person goes to move it on.

    NONE of them blocks anything. The plan closes at the career conversation,
    and the conversation is exactly where a missing input gets discussed --
    refusing to let someone share a plan because their manager hasn't done the
    technical review yet would block the conversation the review is meant to
    inform. Two of the three aren't even the employee's to move: a 360 release
    is HR's timing, and a career target is a question they may honestly not be
    able to answer yet (pm_career_profile's own schema note refuses to gate
    aspirations for that reason).

    So this is context: it tells the person what their plan is currently built
    on, and what is still to come. The manager sees the same list before
    closing the plan, where an outstanding input is a reason to wait rather
    than an error.

    A person with no technical competencies assigned at all is NOT waiting on
    a review -- most of the roster is unmapped to a job profile today, and a
    gate on something nobody assigned them would block them forever. That row
    is dropped from the list entirely rather than shown as a permanent n/a."""
    items = []

    prof = db.execute("SELECT target_profile_id FROM pm_career_profile WHERE subject_id=?",
                      (subject["id"],)).fetchone()
    items.append({
        "key": "target", "label": "Career target",
        "done": bool(prof and prof["target_profile_id"]),
        "url": url_for("idp_career_view"),
        "done_note": "Set — your plan can aim at it",
        "todo_note": "Not set — pick one on the career map so this plan can aim somewhere",
    })

    rel = db.execute("SELECT 1 FROM report_releases WHERE subject_id=? LIMIT 1",
                     (subject["id"],)).fetchone()
    items.append({
        "key": "feedback", "label": "360 feedback",
        "done": bool(rel),
        "url": url_for("my_report") if rel else None,
        "done_note": "Released — its weakest behaviours seed your goals",
        "todo_note": "Not released yet — Group People releases these after calibration",
    })

    cid = active_cycle_id(db)
    assigned = db.execute(
        "SELECT 1 FROM tc_assignments WHERE cycle_id=? AND subject_id=? LIMIT 1",
        (cid, subject["id"])).fetchone() if cid else None
    if assigned:
        a = db.execute(
            "SELECT status FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
            (cid, subject["id"])).fetchone()
        status = a["status"] if a else "pending"
        nobody = status == "submitted" and _tc_chair_unreviewed(db, subject["id"])   # nobody reviews it: it stands (2026-11-06)
        items.append({
            "key": "technical", "label": "Technical assessment",
            "done": status == "reviewed" or nobody,
            "url": url_for("technical_my_view"),
            "done_note": ("Submitted, and nobody reviews it, so the gaps below are real" if nobody
                          else "Reviewed by your line manager — the gaps below are real"),
            "todo_note": ("Submitted and waiting on your line manager's review"
                          if status == "submitted" else
                          "Not submitted yet — until it is reviewed, the technical "
                          "gaps below are only your own self-rating"),
        })
    return items


def pm_idp_suggestions(db, subject):
    """Grounded seed material for a development plan: this person's WEAKEST
    leadership principles from their own 360 feedback, plus their manager's
    remark on the last completed period.

    Deliberately gated on report_releases -- the same gate my_report() uses.
    Feedback an employee has not been shown must not reach them sideways
    through a development-plan suggestion. Returns [] rather than raising when
    there is nothing released, which is the common case early on."""
    out = {"principles": [], "manager_remark": None, "cycle_name": None}
    rel = db.execute(
        "SELECT c.id, c.name FROM report_releases rr JOIN cycles c ON c.id = rr.cycle_id "
        "WHERE rr.subject_id=? ORDER BY c.year DESC, c.half DESC, c.id DESC LIMIT 1",
        (subject["id"],)).fetchone()
    if rel:
        out["cycle_name"] = rel["name"]
        agreement, n_sub = statement_agreement(db, subject, rel["id"])
        scored = []
        for crit in agreement:
            yes = sum(s["yes"] for s in crit["statements"])
            tot = sum(s["total"] for s in crit["statements"])
            if tot:
                scored.append({"name": crit["name"], "pct": round(100.0 * yes / tot)})
        scored.sort(key=lambda c: c["pct"])
        out["principles"] = scored[:3]
    # The manager's own words on the most recent FINISHED period they
    # commented on. The lock check is the point: pm_manager_remarks has no
    # draft column -- the manager's box autosaves as they type -- so without
    # it a half-written sentence reaches the employee here, through a side
    # door, while their own PM page is still correctly holding it back.
    #
    # Newest period first, then newest remark within it -- a matrix split can
    # leave several approvers' remarks on one period, so the tiebreak is what
    # makes this deterministic rather than whichever row SQLite reaches first.
    # Walking back past an unfinished period is deliberate: an older, settled
    # remark is better material for a plan than nothing at all.
    for mr in db.execute(
            "SELECT r.remark, r.cycle_id, p.name AS period_name "
            "FROM pm_manager_remarks r JOIN cycles p ON p.id = r.cycle_id "
            "WHERE r.subject_id=? AND TRIM(COALESCE(r.remark,'')) != '' "
            "ORDER BY p.year DESC, p.half DESC, r.submitted_at DESC, r.id DESC",
            (subject["id"],)):
        if pm_period_locked_for(db, mr["cycle_id"], subject["id"]):
            out["manager_remark"] = {"remark": mr["remark"], "period": mr["period_name"]}
            break

    # Where they said they want to GO. Everything above is a gap -- what the
    # assessments say they're weakest at -- so a plan built from that alone is
    # steered entirely by remediation and never once by ambition. The career
    # profile is the other half, and it is already sitting one tab away.
    #
    # No release gate needed and none applied: unlike feedback, these are the
    # person's OWN words, shown back to the person who wrote them.
    #
    # Deliberately NOT one-click-addable like a principle is. A principle is a
    # development area and makes a goal title as-is; an aspiration is a
    # destination ("I want to run a plant"), and dropping that into "What do
    # you want to develop?" would be a category error the field label itself
    # exposes. It belongs here as the thing you steer BY while writing goals.
    prof = db.execute("SELECT * FROM pm_career_profile WHERE subject_id=?",
                      (subject["id"],)).fetchone()
    if prof:
        asp = [(lbl, prof[k]) for k, lbl in
               (("aspiration_now", "Next"), ("aspiration_mid", "In 2–3 years"),
                ("aspiration_long", "Longer term")) if prof[k]]
        if asp or prof["strengths"] or prof["mentor"]:
            out["profile"] = {"aspirations": asp, "strengths": prof["strengths"],
                              "mentor": prof["mentor"]}
    return out

# The nine numeric columns a KPI line carries. Which subset is meaningful is
# decided by the BG's mechanism (see pm_score_kpi_line): A uses rate1-5, B uses
# threshold/target/multiple|excellence. `target` doubles as Mechanism A's base
# -- inert in A's scoring (verified), and semantically its real target.
PM_NUMERIC_FIELDS = ("rate1", "rate2", "rate3", "rate4", "rate5",
                     "threshold", "target", "multiple", "excellence")


# How specific each scope dimension is, used to rank competing library rows
# offering the same KPI. Job grade beats tier (a grade-targeted row is a
# deliberate override of the broader tier band); tier beats department; then
# company. The weights are powers of two so a row's total score is an
# unambiguous ordering of its dimension set, never a tie between two different
# combinations.
PM_LIBRARY_SCOPE_WEIGHTS = (("job_grade", 8), ("job_grades", 8), ("tier_n", 4),
                            ("department", 2), ("departments", 2), ("company", 1))


def _tc_cat_from_form(form):
    """A competency's category: picked from the list, or named as new ("__new__" + category_new; 2026-10-19)."""
    v = (form.get("category") or "").strip()
    return (form.get("category_new") or "").strip() if v == "__new__" else v


def kpi_library_lists(db, bgs):
    """What a library row's scope and family are ticked or picked from (Chris, 2026-10-19: "should run as dropdown for
    selection to ensure data validation"): {"depts": {bg: [[department, [its units]]]}, "grades": {bg: [grade]},
    "cats": [every family · group the libraries hold]}."""
    bgs = [b for b in bgs if b]
    ph = ",".join("?" * len(bgs)) or "''"
    depts, grades = {}, {}
    for r in db.execute("SELECT business_group bg, TRIM(department) d, COALESCE(company,'') co FROM users WHERE "
                        "business_group IN (%s) AND TRIM(COALESCE(department,''))!='' AND left_at IS NULL AND "
                        "role!='admin' GROUP BY bg, LOWER(TRIM(department)), co" % ph, bgs):
        e = depts.setdefault(r["bg"], {}).setdefault(r["d"].casefold(), [r["d"], []])
        if r["co"] not in e[1]:
            e[1].append(r["co"])
    for r in db.execute("SELECT DISTINCT business_group bg, job_grade g FROM users WHERE business_group IN (%s) AND "
                        "job_grade IS NOT NULL AND TRIM(job_grade)!='' AND left_at IS NULL AND role!='admin'" % ph, bgs):
        gv = r["g"]
        if isinstance(gv, float) and gv.is_integer():
            gv = int(gv)
        try:
            gv = int(str(gv).strip())
        except ValueError:
            continue   # a letter grade (H, GM) isn't a scope a library row can name
        grades.setdefault(r["bg"], set()).add(str(gv))
    cats = sorted({" ".join(r[0].split()) for r in db.execute(
        "SELECT DISTINCT category FROM pm_kpi_library WHERE TRIM(COALESCE(category,''))!=''")}, key=str.lower)
    return {"depts": {b: sorted(v.values(), key=lambda x: x[0].lower()) for b, v in depts.items()},
            "grades": {b: sorted(v, key=int) for b, v in grades.items()}, "cats": cats}


def _pm_csv_set(val):
    """A stored multi-value scope field as a set, case- and space-normalised.

    The roster holds 22 department names that differ from another only by case
    or spacing ("Production" and "PRODUCTION" both exist), so an exact match
    let a rule that names one of them silently miss the other. For an EXCLUDE
    rule that fails open -- the people it names keep the KPI -- which is the
    dangerous direction, so both sides of every comparison are normalised."""
    return {" ".join(p.split()).casefold() for p in (val or "").split(",") if p.strip()}


def pm_library_matches_person(row, user, tier_n, people=None):
    """Does this library row's scope cover this person?

    The single-value columns (department, job_grade, each with a '*' any-
    sentinel) are the original shape and still work exactly as they did. The
    multi-value ones are additive and win when set:

      job_grades   -- a list, so "JG 19-23" is ONE rule rather than five
      departments  -- a list, read as include OR exclude per department_mode,
                      so "everyone except Production" is one rule rather than
                      one per remaining department (and a department added to
                      the org later is covered automatically, which the
                      one-rule-per-department shape would silently miss)

    Kept as a predicate rather than folded into SQL because an exclusion can't
    be expressed in the same IN (?, '*') clause the include path uses, and
    having two different matching rules in two places is exactly how a scope
    check drifts away from the UI that offers it.

    Named people (Chart of KPI, board 4b): `people` is {library id: {user id}} (_pm_lib_people_map, read once by the caller).
    A row that names people matches ONLY an active person on its list who is still in the row's business group, whatever
    their unit, department or grade; a row that names nobody is read exactly as above."""
    if (row["business_group"] or "") != (user["business_group"] or ""):
        return False
    if people and _row_get(row, "id") in people:
        return _row_get(user, "left_at") is None and _row_get(user, "id") in people[_row_get(row, "id")]
    if (row["company"] or "*") != "*" and (row["company"] or "") != (user["company"] or ""):
        return False

    grades = _pm_csv_set(row["job_grades"] if "job_grades" in row.keys() else "")
    ug = " ".join(str(user["job_grade"] or "").split()).casefold()
    if grades:
        if ug not in grades:
            return False
    elif ((row["job_grade"] or "*") != "*"
          and " ".join(str(row["job_grade"] or "").split()).casefold() != ug):
        return False

    depts = _pm_csv_set(row["departments"] if "departments" in row.keys() else "")
    ud = " ".join((user["department"] or "").split()).casefold()
    mode = (row["department_mode"] if "department_mode" in row.keys() else "") or "include"
    if depts:
        if mode == "exclude":
            if ud in depts:
                return False
        elif ud not in depts:
            return False
    elif ((row["department"] or "*") != "*"
          and " ".join((row["department"] or "").split()).casefold() != ud):
        return False

    tn = row["tier_n"] or 0
    return tn == 0 or tn == (tier_n or 0)


def pm_bu_level_names(db, user, cid=None):
    """Normalised KPI names this person is NOT allowed to fill in themselves.

    A BU-level KPI (a company-wide figure like PAT or Gross Profit) is one
    number the employee has no way of knowing, so HR enters it once for
    everyone via Fill BU KPI. Marking it here is what lets the employee's own
    page grey it out BEFORE that fill happens -- without a marker the app
    cannot tell a company-wide line from a personal one, and the mandatory-
    fill gate would demand a number nobody has.

    Matched by scope + KPI NAME, deliberately not by pm_kpi_targets.library_id:
    targets imported straight from HR's spreadsheet carry no library link, and
    those are exactly the rows that need this. Name matching is also how Fill
    BU KPI itself identifies these lines, so the two cannot disagree about
    which KPIs are BU-level.

    Where a saved BU KPI setup covers the person's unit and that name (pm_bu_kpis), who is BU follows the LINE LINK
    (_pm_bu_names_map): a line of that name not linked to the setup is the person's own (an unticked holder, a
    bu_keep_own line), so they enter it themselves. `cid` is the cycle the caller is about (default: the active one)."""
    return _pm_bu_names_map(db, [user], cid)[user["id"]]


def _pm_bu_names_map(db, users, cid=None, lib=None):
    """{user id: normalised names Group People fills for them} for a list of people, in cycle `cid` (default the active
    one). The one rule behind pm_bu_level_names and kpis_bu_only_ids: the library's BU-level names (by business group,
    unit, department, grade), minus a name where this cycle's saved BU KPI setup of the person's own business group
    and company exists AND the person holds a line of that name that is not linked to that setup
    (pm_kpi_targets.bu_kpi_id != pm_bu_kpis.id). The link is the truth: a covered person whose line was never linked
    (added after the save, held while locked, kept as their own) is their own line too. No line of that name = no
    evidence, so the name rule stands. Where no setup exists for the unit and name (HR's group-wide PAT) the name rule
    is unchanged. One read of the library per business group, one of the cycle's setups, one of the lines."""
    users = [u for u in users if u]
    out = {u["id"]: set() for u in users}
    cid = cid if cid is not None else active_cycle_id(db)
    lib = {} if lib is None else lib
    tiers = None   # read once for the whole list, never a query a person
    for u in users:
        bg = u["business_group"] or ""
        if bg not in lib:
            lib[bg] = _pm_bu_library_rows(db, bg)
        if lib[bg] and tiers is None:
            tiers = effective_tiers()
        out[u["id"]] = _pm_bu_names_for(u, lib[bg], tiers) if lib[bg] else set()
    # a BU KPI of the person's group is saved there only where the library has a BU-level row in that group, so nothing to read otherwise
    if not cid or not any(lib.get(u["business_group"] or "") for u in users):
        return out
    try:
        setups = {}
        unit_of = {}   # setup id -> (business group, company): a line linked to a setup of ANOTHER unit is a guest's (2026-11-07)
        for r in db.execute("SELECT id, business_group, company, kpi_name FROM pm_bu_kpis WHERE cycle_id=?", (cid,)):
            setups[(r["business_group"], r["company"], " ".join((r["kpi_name"] or "").lower().split()))] = r["id"]
            unit_of[r["id"]] = (r["business_group"], r["company"])
        if not setups:
            return out
        todo = [u["id"] for u in users if out[u["id"]]]
        by = {}   # (subject id, normalised name) -> the setups' ids its lines are linked to (None = unlinked)
        for i in range(0, len(todo), 500):
            chunk = todo[i:i + 500]
            for r in db.execute("SELECT subject_id, kpi_name, bu_kpi_id FROM pm_kpi_targets WHERE cycle_id=? AND "
                                "subject_id IN (%s)" % ",".join("?" * len(chunk)), [cid] + chunk):
                by.setdefault((r["subject_id"], " ".join((r["kpi_name"] or "").lower().split())), set()).add(
                    r["bu_kpi_id"])
        # a guest's line (linked to a setup of another unit of their group) is Group People's to fill whatever the library says for
        # their own unit: its name joins the set. Only the setups that have guests are read, one batched query.
        gsetups = [r["id"] for r in db.execute("SELECT id, carriers_json FROM pm_bu_kpis WHERE cycle_id=? AND carriers_json LIKE ?",
                                               (cid, '%"guests"%')) if _bu_kpi_guests(r)]
        who = {u["id"]: u for u in users}
        if gsetups:
            for i in range(0, len(users), 500):
                chunk = [u["id"] for u in users[i:i + 500]]
                for r in db.execute("SELECT subject_id, kpi_name, bu_kpi_id FROM pm_kpi_targets WHERE cycle_id=? AND bu_kpi_id IN (%s) "
                                    "AND subject_id IN (%s)" % (",".join("?" * len(gsetups)), ",".join("?" * len(chunk))),
                                    [cid] + gsetups + chunk):
                    u = who[r["subject_id"]]
                    if unit_of.get(r["bu_kpi_id"]) not in (None, (u["business_group"], u["company"])):
                        out[u["id"]].add(" ".join((r["kpi_name"] or "").lower().split()))
    except sqlite3.OperationalError:          # pre-migration DB
        return out
    for u in users:
        for n in list(out[u["id"]]):
            sid = setups.get((u["business_group"], u["company"], n))
            held = by.get((u["id"], n))
            if sid is not None and held and sid not in held:
                out[u["id"]].discard(n)   # their own line of that name: not the setup's
    return out


def _pm_bu_library_rows(db, business_group):
    """The active BU-level library rows of one business group ([] on a pre-migration DB)."""
    try:
        return db.execute("SELECT * FROM pm_kpi_library WHERE active=1 AND bu_level=1 AND business_group=?",
                          (business_group or "",)).fetchall()
    except sqlite3.OperationalError:          # pre-migration DB
        return []


def _pm_bu_names_for(user, rows, tiers=None):
    """pm_bu_level_names over rows already read (one business group's), so a list of people reads them once."""
    if not rows:   # no BU KPI in their group: nothing to match, and no grade tier to look up
        return set()
    tier = tier_for_grade(user["job_grade"], tiers)["n"] if user["job_grade"] else 0
    return {" ".join((r["kpi_name"] or "").lower().split())
            for r in rows if pm_library_matches_person(r, user, tier)}


def kpis_bu_only_ids(db, cid, ids):
    """The people among `ids` whose EVERY KPI line in cycle `cid` is a BU KPI Group People fills (pm_bu_level_names'
    rule, the one review_state marks bu_level by), one line or several (Chris, 2026-10-26: "say their KPI is a BU result
    Group People fills, an optional remark for the BG CEO, no submit, no reminder", and "the cases could also be BUCEO
    carries 3 BU KPIs"). Nobody with no line. One read of the lines and one of the library per business group."""
    ids = [i for i in dict.fromkeys(ids or []) if i]
    if not cid or not ids:
        return set()
    names = {}
    for i in range(0, len(ids), 500):
        chunk = ids[i:i + 500]
        for r in db.execute("SELECT subject_id, kpi_name FROM pm_kpi_targets WHERE cycle_id=? AND subject_id IN (%s)"
                            % ",".join("?" * len(chunk)), [cid] + chunk):
            names.setdefault(r[0], []).append(" ".join((r[1] or "").lower().split()))
    if not names:
        return set()
    sids = list(names)
    users = {}
    for i in range(0, len(sids), 500):
        chunk = sids[i:i + 500]
        users.update({r["id"]: r for r in db.execute("SELECT * FROM users WHERE id IN (%s)"
                                                       % ",".join("?" * len(chunk)), chunk)})
    bun = _pm_bu_names_map(db, [users[s] for s in names if s in users], cid)
    out = set()
    for sid, ns in names.items():
        bu = bun.get(sid)
        if bu and all(n in bu for n in ns):
            out.add(sid)
    return out


def pm_own_results_map(db, cid, ids=None, approved_only=False):
    """{subject id: {"own_n", "own_sub", "bu_n", "last"}} for everyone with a KPI line in cycle `cid` (or just `ids`).
    THE rule for "has this person's KPI results in" (product owner, 2026-11-05): their OWN lines all carry a submitted
    result (pm_kpi_results.draft=0). A BU-level line is a unit-wide figure Group People fills once for everyone
    (_pm_bu_names_map, the rule review_state marks bu_level by): the employee cannot enter it, so it is left out of both
    sides of the count. own_n = lines they key, own_sub = those submitted, bu_n = lines Group People fills, last = the
    latest submit time among their own lines. `approved_only` counts approved lines only (the employee's own task
    counters read what performance_my_view lists). One read of the lines, one of the people and the BU map, batched."""
    out = {}
    if not cid:
        return out
    ids = None if ids is None else [i for i in dict.fromkeys(ids) if i]
    if ids is not None and not ids:
        return out
    sql = ("SELECT t.subject_id, t.kpi_name, (r.id IS NOT NULL AND r.draft=0) sub, r.submitted_at FROM pm_kpi_targets t "
           "LEFT JOIN pm_kpi_results r ON r.kpi_target_id=t.id WHERE t.cycle_id=?"
           + (" AND t.status='approved'" if approved_only else ""))
    lines = {}
    if ids is None:
        for r in db.execute(sql, (cid,)):
            lines.setdefault(r[0], []).append((" ".join((r[1] or "").lower().split()), r[2], r[3]))
    else:
        for i in range(0, len(ids), 500):
            chunk = ids[i:i + 500]
            for r in db.execute(sql + " AND t.subject_id IN (%s)" % ",".join("?" * len(chunk)), [cid] + chunk):
                lines.setdefault(r[0], []).append((" ".join((r[1] or "").lower().split()), r[2], r[3]))
    if not lines:
        return out
    sids = list(lines)
    users = []
    for i in range(0, len(sids), 500):
        chunk = sids[i:i + 500]
        users += db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(chunk)), chunk).fetchall()
    bun = _pm_bu_names_map(db, users, cid)
    for sid, ls in lines.items():
        bu = bun.get(sid) or set()
        own = [x for x in ls if x[0] not in bu]
        subs = [x[2] or "" for x in own if x[1]]
        out[sid] = {"own_n": len(own), "own_sub": sum(1 for x in own if x[1]), "bu_n": len(ls) - len(own),
                    "last": max(subs) if subs else None}
    return out


def pm_own_all_in(m):
    """One person's pm_own_results_map entry: do they have own lines, every one of them submitted?"""
    return bool(m) and m["own_n"] > 0 and m["own_sub"] == m["own_n"]


def pm_own_bu_only(m):
    """One person's pm_own_results_map entry: lines, but every one a BU KPI Group People fills (nothing to submit)."""
    return bool(m) and m["own_n"] == 0 and m["bu_n"] > 0


def kpis_bu_only(db, u, cid=None):
    """Is every KPI line of theirs this cycle a BU KPI Group People fills (kpis_bu_only_ids)? Then the KPI check-in has
    nothing for them to key or submit: an optional note for their leaders is all of it."""
    cid = cid or active_cycle_id(db)
    return bool(u) and u["id"] in kpis_bu_only_ids(db, cid, [u["id"]])


def kpi_note_for(db, u):
    """Who their optional note is for, as the KPI card's heading names them: a BU CEO's BG CEO, else their leaders.
    The line manager and the leaders who calibrate them read it either way (Chris, 2026-10-26: "the line manager sees
    the note too, as well as the leaders who calibrate them")."""
    seat = db.execute("SELECT 1 FROM buceo_seats WHERE user_id=? LIMIT 1", (u["id"],)).fetchone()
    return "your BG CEO" if seat else "your leaders"


def pm_library_scope_score(row, tier_n):
    """How specifically this library row targets a person. 0 = BG-wide."""
    score = 0
    seen = set()
    for field, weight in PM_LIBRARY_SCOPE_WEIGHTS:
        val = row[field] if field in row.keys() else None
        if field == "tier_n":
            if val == tier_n:
                score += weight
        elif field in ("job_grades", "departments"):
            # A list narrows the same axis as its single-value twin, so it
            # earns the same weight -- and only once, or a rule that set both
            # would outrank one that expressed the same scope in one field.
            axis = field[:-1]
            if val and axis not in seen:
                score += weight
                seen.add(axis)
        elif val and val != "*":
            score += weight
            seen.add(field)
    return score


def pm_library_scope_label(row):
    """Compact human label for a library row's scope, e.g.
    'GCAST - Sales - JG 14' / 'Tier 2' / 'Whole BG'."""
    bits = []
    if row["company"] != "*":
        bits.append(row["company"])
    if row["department"] != "*":
        bits.append(row["department"])
    if row["job_grade"] != "*":
        bits.append("JG " + str(row["job_grade"]))
    elif row["tier_n"]:
        bits.append("Tier %s" % row["tier_n"])
    return " · ".join(bits) if bits else "Whole BG"


def pm_library_for_person(db, user, tier_n):
    """The active KPI Library rows this person may build a scorecard from.

    ONE resolver, used by both the setting page and the add-route's scope
    check, so "may this person use this library row?" can never drift between
    what the UI offers and what the API accepts.

    Matches on every dimension OR its "any" sentinel, then keeps the most
    specific row per KPI name -- job grade > tier > department > company > the
    BG-wide row -- so the full fallback cascade falls out for free: a row
    scoped to nothing scores 0 and only survives when nothing better offers
    that KPI. Ties break on the lowest id, so the result is stable."""
    # Filtered through pm_library_matches_person(), NOT in SQL. The SQL form
    # could only express the single-value columns, so a rule scoped with a
    # job-grade LIST was offered to everyone: job_grade stays '*' on such a
    # row, `job_grade IN (?, '*')` matched it for every grade, and the list was
    # never consulted. Department exclusions were invisible to it for the same
    # reason, and an exclusion cannot be written as an IN clause at all.
    #
    # pm_bu_level_names() already routes through the matcher, so before this
    # the two paths disagreed about the same row: a KPI could be marked
    # BU-level for exactly the right people while being OFFERED to everybody.
    named = _pm_lib_people_map(db, user["business_group"] or "")   # one read of the group's named-people rows
    rows = [r for r in db.execute(
        "SELECT * FROM pm_kpi_library WHERE active=1 AND business_group=? "
        "ORDER BY kpi_name, id", (user["business_group"] or "",)).fetchall()
        if pm_library_matches_person(r, user, tier_n, named)]
    best = {}
    for r in rows:
        key = " ".join((r["kpi_name"] or "").lower().split())
        score = pm_library_scope_score(r, tier_n) + (1000 if r["id"] in named else 0)   # a name beats any scope
        cur = best.get(key)
        if cur is None or score > cur[0]:
            best[key] = (score, r)
    out = []
    for score, r in best.values():
        row = dict(r)
        row["scope_score"] = score
        row["scope_label"] = "Named people" if r["id"] in named else pm_library_scope_label(r)
        out.append(row)
    out.sort(key=lambda r: ((r["category"] or "").lower(), r["kpi_name"].lower()))
    return out


def pm_default_numbers(db, subject, period, lib, cfg):
    """A newly chosen KPI starts BLANK (Chris, 2 Nov 2026: the library holds no numbers; targets and weights follow each
    year's business plan). Returns (numbers all None, 'blank'). Last year's figures are never stored: the page shows
    them as placeholder text (pm_last_figures), a suggestion is never a stored value."""
    return {k: None for k in PM_NUMERIC_FIELDS}, "blank"


def pm_last_figures(db, subject_id, kpi_name, unit, period):
    """This person's own figures for the same KPI on their most recent EARLIER line, in the line's unit, or None.
    A hint only (placeholder text and the approver's "last year" column); nothing here is ever written."""
    prior = db.execute(
        "SELECT t.* FROM pm_kpi_targets t JOIN cycles p ON p.id = t.cycle_id "
        "WHERE t.subject_id=? AND t.kpi_name=? AND t.cycle_id != ? "
        "AND (p.year < ? OR (p.year = ? AND p.half < ?)) "
        "ORDER BY p.year DESC, p.half DESC LIMIT 1",
        (subject_id, kpi_name, period["id"], period["year"], period["year"], period["half"])).fetchone()
    if not prior:
        return None
    nums = {k: prior[k] for k in PM_NUMERIC_FIELDS}
    steps = kpi_unit_steps_between(kpi_unit_normalise(prior["unit"]), kpi_unit_normalise(unit))
    if steps:
        nums.update(kpi_unit_moved(nums, steps))
    return nums if any(v is not None for v in nums.values()) else None


def pm_changed_vs_earlier(row, earlier):
    """Which figures this proposed line carries that differ from the person's earlier line of the same KPI
    (pm_last_figures). With no earlier line nothing is marked."""
    if not earlier:
        return set()
    out = set()
    for f in PM_NUMERIC_FIELDS:
        a, b = row[f], earlier.get(f)
        if a is None and b is None:
            continue
        if a is None or b is None or abs(float(a) - float(b)) > 1e-9:
            out.add(f)
    return out


def pm_scale_error(cfg, method, vals, kpi_name=None):
    """None when a KPI line's scale can be scored, else why not, in words. THE check on every place a scale is set
    (Chris, 2026-10-18: "if the kpi is higher is better, the setting should be in increment order and no 2 rating should
    share the same value, second for the threshold/target mechanism, the target should never be 0 as it won't be able
    to calculate the achievement"): the KPI import and the person page (_pm_kpi_values), the KPI-setting chat
    (pm_ladder_monotonic, _pm_setting_validate) and the KPI library (its form and its import).
      * 5-point rating: higher is better -> Rate 1 to 5 strictly rise; lower is better -> strictly fall. No two equal.
      * Achievement %: the target is never 0 (achievement is worked out against it), and the threshold sits below the
        target when higher is better, above it when lower is better. With the Excellence variant, the excellence sits
        at or beyond the target (its cap scores 100% or more).
    A missing value is the caller's own completeness check, so it passes here. `vals` is a dict or a row."""
    get = (lambda k: vals.get(k)) if isinstance(vals, dict) else (lambda k: vals[k])
    name = ("'%s': " % kpi_name) if kpi_name else ""
    more = (method or "more") != "less"
    if not cfg:
        return None
    if cfg["mechanism"] == "A":
        rates = [get("rate%d" % i) for i in range(1, 6)]
        if any(r is None for r in rates):
            return None
        for i in range(1, 5):
            a, b = rates[i - 1], rates[i]
            if a == b:
                return "%sRate %d can't be the same as Rate %d: each rating needs its own figure." % (name, i + 1, i)
            if more and b < a:
                return ("%sRate %d must be higher than Rate %d: higher is better, so the figures rise from Rate 1 to "
                        "Rate 5." % (name, i + 1, i))
            if not more and b > a:
                return ("%sRate %d must be lower than Rate %d: lower is better, so the figures fall from Rate 1 to "
                        "Rate 5." % (name, i + 1, i))
        return None
    thr, tgt = get("threshold"), get("target")
    if tgt is None:
        return None
    if tgt == 0:
        return "%sThe target can't be 0: achievement is worked out against the target." % name
    if thr is not None and more and thr >= tgt:
        return "%sThe threshold must be below the target: higher is better." % name
    if thr is not None and not more and thr <= tgt:
        return "%sThe threshold must be above the target: lower is better." % name
    if cfg["variant"] == "excellence":
        try:
            exc = get("excellence")
        except (KeyError, IndexError):
            exc = None
        # The cap is the excellence scored against the target (pm_pct_b_transform): under 100% it could never
        # reach full credit, so it must sit at or beyond the target (the audit's B_EXC, 2026-11-01).
        if exc is not None and pm_pct_b_transform(exc, method or "more", tgt) < 100 - 1e-9:
            if more:
                return ("%sThe excellence must be at or beyond the target: higher is better, so it sits at or above "
                        "the target." % name)
            return ("%sThe excellence must be at or beyond the target: lower is better, so it sits at or below "
                    "the target." % name)
    return None


def pm_ladder_monotonic(t, method):
    """True if a Mechanism-A ladder rises (method 'more') or falls ('less')
    across Rate 1-5, strictly: no two rungs equal (pm_scale_error, 2026-10-18). Load-bearing, not cosmetic: pm_rating_mechanism_a() keeps
    the HIGHEST rung met while scanning all five, so an out-of-order ladder
    scores wrongly and silently. Measured, not theorised: rates
    10/50/30/40/20 with an actual of 35 returns **Rating 5** -- the top band --
    because rate5=20 is the last rung it clears, even though the value never
    reaches Rate 2's threshold of 50. Harmless while only admins typed these
    numbers; a real hazard now employees do."""
    rates = [t.get(f"rate{i}") if isinstance(t, dict) else t[f"rate{i}"]
             for i in range(1, 6)]
    if any(r is None for r in rates):
        return False
    pairs = zip(rates, rates[1:])
    return all(a < b for a, b in pairs) if method == "more" \
        else all(a > b for a, b in pairs)


def pm_setting_chain(db, kpi_target_id):
    """This KPI line's ordered approver chain (shared with result moderation --
    the same LM/HOD who agree the target later moderate its result)."""
    return db.execute(
        "SELECT a.*, u.full_name AS approver_name FROM pm_kpi_target_approvers a "
        "JOIN users u ON u.id = a.approver_id WHERE a.kpi_target_id=? ORDER BY a.seq",
        (kpi_target_id,)).fetchall()


def pm_setting_next_approver(db, kpi_target_id):
    """The chain step whose turn it is to act on the PROPOSAL, or None when
    every step has approved. Mirrors pm_next_approver()'s count-based shape,
    but reads pm_kpi_setting_approvals -- never pm_kpi_approvals."""
    chain = pm_setting_chain(db, kpi_target_id)
    if not chain:
        return None
    acted = db.execute(
        "SELECT COUNT(*) FROM pm_kpi_setting_approvals WHERE kpi_target_id=? "
        "AND action='approve'", (kpi_target_id,)).fetchone()[0]
    return chain[acted] if acted < len(chain) else None


def pm_setting_resolve_approvers(db, subject):
    """The one moderator for a newly proposed KPI line: the subject's own line
    manager. One step, one way (Chris, 2026-10-10: Employee -> LM or the
    KPI's matrix manager -> HOD -> BU CEO -> BG CEO); a matrix manager is set
    per KPI by the import, never here. pm_department_approver_defaults is no
    longer read: it had no writer, and a second step is what the fixed flow
    rules out. Returns a possibly-empty list of user ids -- an empty chain
    is not an error; it surfaces on the Exceptions page (except the Executive Chairman's direct reports while his Moderate tick
    is off: they have none by design, 2026-11-03)."""
    if subject["manager_id"]:
        return _pm_default_moderators(db, subject["id"], subject["manager_id"])   # (empty for the chair's reports, 2026-11-03)
    return []


def pm_kpi_matrix_keep(db, t, subject):
    """The matrix manager this line already routes to, or None. A line the
    import sent to a matrix manager keeps them when the employee proposes:
    exactly one step, someone other than their line manager and themselves,
    still employed. Anything else (no chain, an old two-step chain, the LM)
    goes to the line manager."""
    chain = db.execute("SELECT a.approver_id, u.left_at FROM pm_kpi_target_approvers a "
                       "JOIN users u ON u.id = a.approver_id WHERE a.kpi_target_id=? ORDER BY a.seq",
                       (t["id"],)).fetchall()
    if len(chain) != 1:
        return None
    aid = chain[0]["approver_id"]
    if chain[0]["left_at"] or aid == subject["id"] or aid == subject["manager_id"]:
        return None
    return aid


def pm_setting_state(targets):
    """Collapse this person's open setting rows into one set-level state.
    Weightage is agreed as a SET (it must total 100%), so the whole proposal
    moves together: any 'proposed' line freezes the set for review; otherwise
    a 'returned' line reopens it with the approver's comment."""
    if not targets:
        return "none"
    statuses = {t["status"] for t in targets}
    if "proposed" in statuses:
        return "proposed"
    if "returned" in statuses:
        return "returned"
    return "draft"


# THE VOCABULARY LIVES WITH THE MODULE THAT OWNS IT.
#
# review_state() must not compare a status literal -- a lint fails on one,
# because that is a second definition of "done" living in a surface that only
# projects. But the honest answer to "is this waiting on an approver?" IS a
# status comparison; it just belongs here, in Performance, and not there. This
# is the rule the lint exists to force, applied to its first real case.
PM_SETTING_WAITING_STATES = ("proposed",)


def pm_setting_is_waiting(state):
    """True when the proposal is with an APPROVER, not the employee.

    The distinction is load-bearing for the conversation, not cosmetic:
    dash_tasks() counts a 'proposed' target as the employee's work while the
    approver-side setting_review_pending counts THE SAME ROWS for the approver.
    The employee cannot clear it, so a stage driven by that count would ask them
    forever to finish something that is not theirs to finish."""
    return state in PM_SETTING_WAITING_STATES


def pm_setting_is_open(state, approved_n):
    """True while the employee still has setting work of their own.

    Mirrors performance_kpi_setting_view()'s own `editable`: still building
    (draft/returned), or setting for the first time (nothing open and nothing
    approved yet). Once a scorecard is agreed the journey is closed."""
    return (state in ("draft", "returned")
            or (state == "none" and not approved_n))


def pm_setting_stage(db, u, cycle_id):
    """(state, n_open, approved_n, waiting_on) for one person's setting journey.

    A light read: _pm_setting_context() answers the same questions but also
    resolves the whole KPI library for the page, which is far more than a rail
    needs on every turn."""
    mine = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
        f"AND status IN ({','.join('?' * len(PM_SETTING_OPEN_STATUSES))}) ORDER BY {PM_LINE_ORDER}",
        (cycle_id, u["id"], *PM_SETTING_OPEN_STATUSES)).fetchall()]
    approved_n = db.execute(
        "SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
        "AND status='approved'", (cycle_id, u["id"])).fetchone()[0]
    state = pm_setting_state(mine)
    waiting_on = None
    if pm_setting_is_waiting(state) and mine:
        nxt = pm_setting_next_approver(db, mine[0]["id"])
        waiting_on = nxt["approver_name"] if nxt else None
    return state, len(mine), approved_n, waiting_on


def _pm_setting_context(db, u):
    """Everything /performance/setting renders, also reused by the propose
    route's re-validation so the two can't disagree about scope."""
    period = active_pm_period(db)
    if not period:
        return None
    tier = tier_for_grade(u["job_grade"], default_tiers())
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?",
                     (u["business_group"],)).fetchone()
    mine = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
        f"AND status IN ({','.join('?' * len(PM_SETTING_OPEN_STATUSES))}) ORDER BY {PM_LINE_ORDER}",
        (period["id"], u["id"], *PM_SETTING_OPEN_STATUSES)).fetchall()]
    approved_n = db.execute(
        "SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
        "AND status='approved'", (period["id"], u["id"])).fetchone()[0]
    # DEMO ONLY (is_demo_account): fold the AGREED scorecard back into the editable
    # working set, so a tester can exercise the setting chat without first
    # rewinding it. This is a pure READ -- the rows keep status 'approved' until a
    # deliberate propose -- so it does not violate the zero-write GET, and a demo
    # account exists only on a server with L360_DEMO_ACCOUNTS=1, never production.
    _setting_demo = is_demo_account(u)
    if _setting_demo and approved_n and not mine:
        mine = [dict(t) for t in db.execute(
            "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
            "AND status='approved' ORDER BY " + PM_LINE_ORDER, (period["id"], u["id"])).fetchall()]
    # The library resolved for this person's own BG / company / department /
    # tier / job grade, most-specific-row-wins with a full cascade down to the
    # BG-wide row -- so someone whose own scope was never curated still sees
    # something rather than an empty page. Shared with the add route's scope
    # check (see pm_library_for_person).
    library = pm_library_for_person(db, u, tier["n"]) if cfg else []
    chosen = {t["kpi_name"] for t in mine}
    for row in library:
        row["already_chosen"] = row["kpi_name"] in chosen
    state = pm_setting_state(mine)
    lib_by_id = {r["id"]: r for r in library}
    for t in mine:
        nxt = pm_setting_next_approver(db, t["id"]) if t["status"] == "proposed" else None
        t["next_approver_name"] = nxt["approver_name"] if nxt else None
        last_return = db.execute(
            "SELECT comment FROM pm_kpi_setting_approvals WHERE kpi_target_id=? "
            "AND action='return' ORDER BY id DESC LIMIT 1", (t["id"],)).fetchone()
        t["return_comment"] = last_return["comment"] if last_return else None
        # last year's figures for a line that started blank: placeholder text only, never stored
        t["last_figures"] = (pm_last_figures(db, u["id"], t["kpi_name"], t.get("unit"), period)
                             if t.get("number_source") == "blank" else None)
    # Editable while they're still building (draft/returned), or setting for
    # the first time. Once a scorecard is AGREED (approved rows exist and
    # nothing is open) the setting journey is closed for the period -- a
    # mid-period change goes through HR rather than a silent second proposal.
    # Deliberately matches what the template offers, so the API can't accept
    # what the page doesn't show.
    editable = (state in ("draft", "returned")
                or (state == "none" and approved_n == 0))
    if _setting_demo:
        editable = True   # DEMO ONLY (ZZ): keep the setting chat editable for testing
    setting_runs = kpi_setting_runs(period)
    if not setting_runs:
        editable = False   # KPI setting runs in the Early Year only (2026-10-15); the page reads only
    # The agreed scorecard, for the read-only view someone gets once setting is
    # done. Kept OUT of `mine` deliberately: `mine` is the working set the state
    # machine, the weight total and the propose validation all read, and folding
    # approved rows into it would quietly make an agreed scorecard look like an
    # editable proposal to every one of them.
    agreed = []
    if approved_n and not mine:
        agreed = [dict(t) for t in db.execute(
            "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
            "AND status='approved' ORDER BY " + PM_LINE_ORDER, (period["id"], u["id"])).fetchall()]
    return {
        "period": period, "tier": tier, "cfg": cfg, "mine": mine,
        "library": library, "approved_n": approved_n, "state": state,
        "total_weight": round(sum(t["weightage"] or 0 for t in mine), 2),
        "editable": editable, "agreed": agreed, "setting_runs": setting_runs,
        "agreed_weight": round(sum(t["weightage"] or 0 for t in agreed), 2),
    }


def _pm_setting_shut_reason(ctx):
    """Why a setting write is refused, in the words of the state it's actually
    in. 'With your approver' and 'already agreed' are different situations and
    the difference is the whole answer -- one resolves itself when the approver
    acts, the other needs HR. Shared by the three refusal sites so they can
    never describe the same state differently."""
    if not ctx.get("setting_runs", True):
        return _KPI_SETTING_ELSEWHERE
    if ctx["state"] == "proposed":
        return "This scorecard is already with your approver."
    if ctx["approved_n"]:
        return "This scorecard is agreed for the period. To change a KPI, talk to Group People."
    return "This scorecard can no longer be edited."


def pm_viewed_period(db, u):
    """(viewed period, switcher pills, is_it_the_active_one) for an employee.

    Two lists, and the difference is the point:

      pills     -- the ACTIVE year only. The KPI page is the working surface
                   for the half you are in, not an archive (decision #53).
      reachable -- every period this person holds targets in. That is what
                   ?period= is validated against, so the dashboard's record can
                   deep-link straight into any past half. Widening it exposes
                   nothing: pm_user_periods() is already scoped to this
                   person's own targets, and the write routes keep their own
                   separate active-period guard.

    A deep-linked past period is folded back into the pills, or the page would
    render a switcher that doesn't contain the period it is showing."""
    active = active_pm_period(db)
    reachable = pm_user_periods(db, u["id"])
    year = active["year"] if active else max((p["year"] for p in reachable), default=None)
    pills = [p for p in reachable if p["year"] == year]
    # The active period is always an option, even before this person's targets
    # for it are imported -- otherwise someone whose only targets sit in a past
    # half lands there with no pill back (a one-way door).
    if active and not any(p["id"] == active["id"] for p in pills):
        pills = sorted(pills + [active], key=lambda p: (p["year"], p["half"]))
    period = None
    requested = (request.args.get("period", "") or "").strip()
    if requested.isdigit():
        period = next((p for p in reachable if p["id"] == int(requested)), None)
    if period is None:
        period = active
    if period and not any(p["id"] == period["id"] for p in pills):
        pills = sorted(list(pills) + [period], key=lambda p: (p["year"], p["half"]))
    return period, pills, bool(period and active and period["id"] == active["id"])


def _pm_idp_period(db, u):
    """The IDP's viewed period. Thin wrapper on pm_viewed_period() so the IDP
    and the KPI page can never disagree about which period is on screen."""
    return pm_viewed_period(db, u)


# ---------------------------------------------------------------------------
# The evidence ledger  (Phase A)
# ---------------------------------------------------------------------------
def _evidence_shared_identity(db, uid):
    """1 when this login's email address is shared with another active user.

    Snapshotted onto every item at write time rather than joined at read time:
    302 active users share 42 addresses, and /forgot needs only an employee id
    plus the address on file, so for those accounts "the employee's own words"
    is a claim the product cannot make. A later email correction must not
    silently restate a record that was written under the old arrangement.
    """
    row = db.execute(
        "SELECT COUNT(*) c FROM users v WHERE v.left_at IS NULL "
        "AND TRIM(COALESCE(v.email,''))<>'' AND LOWER(TRIM(v.email)) = "
        "(SELECT LOWER(TRIM(COALESCE(email,''))) FROM users WHERE id=?)", (uid,)).fetchone()
    return 1 if row and row["c"] > 1 else 0


def _evidence_clean(form, base=None):
    """Pull the five slots off a form, normalised. Returns (fields, error).

    ABSENT IS NOT EMPTY, which is why `base` exists. This rebuilt all nine
    fields from the form every time, so a caller sending one of them blanked the
    other eight -- including occurred_on, which is NOT NULL, and which is the
    one field a human stated and cannot be re-derived.

    It never fired because /evidence/<id>/autosave has no caller in any template
    or script: the whole card posts at once today. Phase C's conversation is a
    partial writer by definition -- one answer per turn -- so it would have been
    the first caller to hit it, on the employee's own words.

    `base` is the row being edited. A key ABSENT from the form falls back to
    what is already stored; a key PRESENT and empty still clears. Callers
    editing an existing item must pass it; evidence_new() must not, because
    there is nothing to fall back to and absence there really is empty.
    """
    def raw(key, fallback=""):
        if key in form:
            return form.get(key) or ""
        if base is not None:
            try:
                v = base[key]
            except (KeyError, IndexError):
                return fallback
            return "" if v is None else str(v)
        return fallback

    body = raw("body").strip()[:EVIDENCE_BODY_MAX]
    impact = raw("impact").strip()[:EVIDENCE_BODY_MAX]
    who = raw("who").strip()[:300]
    title = raw("title").strip()[:120]
    kind = raw("kind", "other").strip() or "other"
    if kind not in EVIDENCE_KINDS:
        kind = "other"
    prec = raw("occurred_precision", "day").strip() or "day"
    if prec not in EVIDENCE_PRECISIONS:
        prec = "day"
    # occurred_on is a LOCAL CALENDAR DATE the human stated. It is never shifted
    # and never passed through |myt -- that filter is for stored UTC timestamps,
    # and applying it here would move somebody's March to February at 8am.
    occurred = raw("occurred_on").strip()[:10]
    if occurred:
        try:
            date.fromisoformat(occurred)
        except ValueError:
            return None, "Enter a real date for when this happened."
        if occurred > _today_myt().isoformat():
            return None, "That date is in the future."
    unit = raw("metric_unit").strip()[:40]
    raw_val = raw("metric_value").strip().replace(",", "")
    value = None
    if raw_val:
        try:
            value = float(raw_val)
        except ValueError:
            return None, "The measure has to be a number, or left blank."
    rws = (raw("raised_with_subject") or "").strip() or None
    if rws not in (None, "written", "discussed", "no"):
        rws = None
    return {"raised_with_subject": rws,
            "body": body, "impact": impact, "who": who, "title": title,
            "kind": kind, "occurred_on": occurred, "occurred_precision": prec,
            "metric_value": value, "metric_unit": unit}, None


def pm_evidence_write(db, actor, subject_id, fields, evidence_id=None,
                      correction_of=None):
    """THE ONLY WRITER. Returns (row_id, error).

    Everything the ledger promises is enforced here rather than by a CHECK or a
    trigger, because the rules are about WHO and WHEN, not about column values:

    - APPEND-ONLY AFTER SHARE. Once state='shared' the five slots are frozen.
      An edit is refused; a correction is a NEW ROW carrying supersedes_id, and
      the original stays, marked. A ledger you can quietly rewrite is a
      liability in a dispute rather than a defence in one.
    - AUTHORSHIP COMES FROM THE SESSION. `actor` is the logged-in user; the
      form's opinion about author_id is ignored entirely. Nobody writes in
      another person's name, and nobody edits another person's words -- not a
      manager, not an admin.
    - author_role is DERIVED, never posted.
    """
    aid = actor["id"]
    now_utc = "datetime('now')"
    role = "self" if aid == subject_id else "manager"
    for _f in ("title", "body", "impact", "who"):   # the ledger's words reach the manager's agent: one gate (4-03)
        _t, _serr = _store_text(str(fields.get(_f) or ""), role)
        if _serr:
            return None, _serr
    if evidence_id is not None:
        row = db.execute("SELECT * FROM pm_evidence WHERE id=?", (evidence_id,)).fetchone()
        if not row:
            return None, "That entry no longer exists."
        if row["author_id"] != aid:
            return None, "You can only edit what you wrote."
        if row["state"] != "draft":
            return None, ("This entry has been shared, so it can no longer be "
                          "edited. Add a correction instead.")
        sets = ", ".join("%s=?" % f for f in EVIDENCE_FROZEN_FIELDS) + \
            ", title=?, updated_at=" + now_utc
        db.execute("UPDATE pm_evidence SET " + sets + " WHERE id=?",
                   tuple(fields[f] for f in EVIDENCE_FROZEN_FIELDS)
                   + (fields["title"], evidence_id))
        return evidence_id, None

    cur = db.execute(
        "INSERT INTO pm_evidence(subject_id, author_id, author_role, "
        "author_shared_identity, cycle_id, occurred_on, occurred_precision, kind, "
        "title, body, impact, metric_value, metric_unit, who, raised_with_subject, "
        "state, supersedes_id) "
        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft',?)",
        (subject_id, aid, role, _evidence_shared_identity(db, aid),
         active_cycle_id(db), fields["occurred_on"] or _today_myt().isoformat(),
         fields["occurred_precision"], fields["kind"], fields["title"],
         fields["body"], fields["impact"], fields["metric_value"],
         fields["metric_unit"], fields["who"], fields.get("raised_with_subject"),
         correction_of))
    return cur.lastrowid, None


def evidence_list(db, subject_id, include_drafts=True):
    """One person's ledger, newest thing that HAPPENED first.

    Ordered on occurred_on, not created_at: the ledger is a record of a year,
    not of typing. A superseded item is still returned -- it is marked, never
    hidden, which is the difference between a correction and a rewrite.
    """
    clause = "" if include_drafts else " AND state='shared'"
    return db.execute(
        "SELECT e.*, (SELECT COUNT(*) FROM pm_evidence_attachments a "
        "             WHERE a.evidence_id=e.id AND a.removed_at IS NULL) AS n_attach, "
        "       (SELECT COUNT(*) FROM pm_evidence c "
        "             WHERE c.supersedes_id=e.id) AS n_corrections, "
        # How long after the event it was written down. Computed here rather
        # than stored, because storing it would go stale the moment either date
        # were corrected. Shown to the AUTHOR on their own card: a person who
        # can see "written 166 days later" on their own record is the cheapest
        # nudge toward writing the next one sooner.
        "       CAST(julianday(substr(e.created_at,1,10)) "
        "            - julianday(e.occurred_on) AS INTEGER) AS gap_days "
        "FROM pm_evidence e WHERE e.subject_id=? AND e.state<>'retracted'"
        + clause + " ORDER BY e.occurred_on DESC, e.id DESC", (subject_id,)).fetchall()


# ---------------------------------------------------------------------------
# The manager's side (Phase B step 2). THE INVARIANT: everything here is visible
# to the subject. There is no manager-private evidence -- the private scratch is
# pm_kpi_moderation_drafts and stays there.
# ---------------------------------------------------------------------------
def _pm_manages_anyone(db, actor):
    """True when `actor` approves at least one KPI line this period -- i.e. they
    have a team to review. Cheap: the 'Your team' link on the review header."""
    period = active_pm_period(db)
    if not period or not actor:
        return False
    if _chair_pm_hidden(db, actor):   # the Executive Chairman's Moderate tick is off: his Team tab is the 360 only
        return False
    # ...someone who takes part in Performance: a leader whose only KPI reports are out of it has no KPI team (2026-10-30).
    # CROSS JOIN pins the order approver -> line -> person, so the participation test runs on the approver's own lines
    # only: left to choose, SQLite scans every line of the cycle and tests every person (5x slower, once a person on the
    # dashboard and the reminders' count of 3,600 people)
    return db.execute(
        "SELECT 1 FROM pm_kpi_target_approvers ap CROSS JOIN pm_kpi_targets t "
        "ON t.id=ap.kpi_target_id CROSS JOIN users su ON su.id=t.subject_id "
        "WHERE ap.approver_id=? AND t.cycle_id=? AND " + participant_sql("su", "pm") + " LIMIT 1",
        (actor["id"], period["id"])).fetchone() is not None


def _pm_can_review_subject(db, actor, subject_id):
    """True when `actor` may write about `subject` -- i.e. they can act on at
    least one of the subject's KPI lines this period. THE AUTHORISATION GATE for
    every manager write below, reusing the exact predicate
    performance_team_member_view gates on so the two cannot drift. A stranger,
    and a manager who is not in this subject's chain, get False -> the routes
    401/403."""
    if not actor or actor["id"] == subject_id or actor["role"] == "admin":
        return False
    period = active_pm_period(db)
    if not period:
        return False
    if not _report_takes_part(db, subject_id, "pm"):   # a KPI evidence ledger of someone out of Performance (2026-10-30)
        return False
    mine, _mp, _sp, _al = _pm_member_previews(db, subject_id, period["id"], actor["id"])
    return bool(mine)


def pm_evidence_review_write(db, actor, eid, verdict, note=None):
    """Endorse or dispute a SUBJECT'S item. Returns (row_id, error).

    The item must belong to a subject the actor may review, and must be SHARED --
    you cannot pass judgement on a draft nobody has put on the record. One
    standing verdict per (item, reviewer); a second call updates it. Visible to
    the subject by construction: pm_evidence_reviews has no private flag and the
    subject's own ledger reads it."""
    if verdict not in ("endorse", "dispute"):
        return None, "A review is either an endorsement or a dispute."
    ev = db.execute("SELECT * FROM pm_evidence WHERE id=?", (eid,)).fetchone()
    if not ev or ev["state"] != "shared":
        return None, "That item is not on the record to review."
    if not _pm_can_review_subject(db, actor, ev["subject_id"]):
        return None, "You can only review the items of someone you manage."
    role = "self" if actor["id"] == ev["subject_id"] else "manager"
    note = (note or "").strip()[:EVIDENCE_BODY_MAX] or None
    _t, _serr = _store_text(note or "", role)
    if _serr:
        return None, _serr
    db.execute(
        "INSERT INTO pm_evidence_reviews(evidence_id, reviewer_id, reviewer_role, "
        "verdict, note) VALUES (?,?,?,?,?) "
        "ON CONFLICT(evidence_id, reviewer_id) DO UPDATE SET "
        "  verdict=excluded.verdict, note=excluded.note, updated_at=datetime('now')",
        (eid, actor["id"], role, verdict, note))
    row = db.execute("SELECT id FROM pm_evidence_reviews WHERE evidence_id=? AND reviewer_id=?",
                     (eid, actor["id"])).fetchone()
    return row["id"], None


def pm_evidence_cite(db, actor, eid, stance, decision_kind):
    """Cite an item toward a decision, WITH A STANCE. Returns (row_id, error).

    The item must be shared and about a subject the actor may act on. subject_id
    is taken from the EVIDENCE, never the form, so a citation cannot be filed
    against somebody the item is not about. Idempotent per (item, citer,
    decision_kind)."""
    if stance not in ("supports", "qualifies", "contradicts"):
        return None, "A citation needs a stance."
    if decision_kind not in ("kpi_result", "moderation", "band_change"):
        return None, "Unknown decision."
    ev = db.execute("SELECT * FROM pm_evidence WHERE id=?", (eid,)).fetchone()
    if not ev or ev["state"] != "shared":
        return None, "That item is not on the record to cite."
    # The subject may cite their OWN item (supports, into their KPI result); a
    # manager may cite a subject they can act on. Both go through one gate.
    is_own = actor["id"] == ev["subject_id"]
    if not is_own and not _pm_can_review_subject(db, actor, ev["subject_id"]):
        return None, "You can only cite the items of someone you manage."
    role = "self" if is_own else "manager"
    cid = active_cycle_id(db)
    db.execute(
        "INSERT OR IGNORE INTO pm_evidence_citations(evidence_id, subject_id, cited_by, "
        "cited_by_role, stance, decision_kind, cycle_id) VALUES (?,?,?,?,?,?,?)",
        (eid, ev["subject_id"], actor["id"], role, stance, decision_kind, cid))
    db.execute(
        "UPDATE pm_evidence_citations SET stance=? WHERE evidence_id=? AND cited_by=? "
        "AND decision_kind=?", (stance, eid, actor["id"], decision_kind))
    row = db.execute("SELECT id FROM pm_evidence_citations WHERE evidence_id=? AND cited_by=? "
                     "AND decision_kind=?", (eid, actor["id"], decision_kind)).fetchone()
    return row["id"], None


def pm_evidence_citations_for(db, eid):
    """Every citation on one item, with the citer's name and stance -- shown to
    the SUBJECT on their own ledger, so a manager citing their evidence toward a
    decision (a 'contradicts' toward a band change especially) is never hidden
    from them. Full visibility: pm_evidence_citations has no private flag."""
    return db.execute(
        "SELECT c.*, u.full_name AS citer_name FROM pm_evidence_citations c "
        "LEFT JOIN users u ON u.id=c.cited_by WHERE c.evidence_id=? "
        "ORDER BY c.created_at", (eid,)).fetchall()


def pm_evidence_reviews_for(db, eid):
    """Every review on one item, with the reviewer's name -- shown to the subject
    on their own ledger AND to a calibrator in the report. No hidden reviews."""
    return db.execute(
        "SELECT r.*, u.full_name AS reviewer_name FROM pm_evidence_reviews r "
        "LEFT JOIN users u ON u.id=r.reviewer_id WHERE r.evidence_id=? "
        "ORDER BY r.created_at", (eid,)).fetchall()


def pm_why_flags(db, population):
    """{subject_id: flag} for the Why column, where flag is one of
    'endorsed' / 'disputed' / 'both' / 'none' (only for subjects with cited
    evidence; the count already says 'No evidence cited' otherwise). Batched, one
    query per fact, never per row -- the pm_calibration_trails discipline."""
    ids = [p["id"] for p in population]
    if not ids:
        return {}
    ph = ",".join("?" * len(ids))
    endorsed, disputed, both = set(), set(), set()
    for r in db.execute(
            "SELECT DISTINCT e.subject_id AS sid, rv.verdict FROM pm_evidence e "
            "JOIN pm_evidence_links l ON l.evidence_id=e.id "
            "JOIN pm_evidence_reviews rv ON rv.evidence_id=e.id "
            "WHERE e.subject_id IN (%s) AND e.state='shared'" % ph, ids):
        (endorsed if r["verdict"] == "endorse" else disputed).add(r["sid"])
    # "both accounts": the subject has an item AND a manager-authored item exists.
    for r in db.execute(
            "SELECT subject_id AS sid, COUNT(DISTINCT author_role) AS roles "
            "FROM pm_evidence WHERE subject_id IN (%s) AND state='shared' "
            "GROUP BY subject_id HAVING roles > 1" % ph, ids):
        both.add(r["sid"])
    out = {}
    for sid in set(endorsed) | set(disputed) | set(both):
        out[sid] = ("both" if sid in both else
                    "disputed" if sid in disputed else "endorsed")
    return out


def evidence_get(db, eid):
    return db.execute("SELECT * FROM pm_evidence WHERE id=?", (eid,)).fetchone()


def evidence_links(db, eid):
    return db.execute("SELECT * FROM pm_evidence_links WHERE evidence_id=? "
                      "ORDER BY id", (eid,)).fetchall()


def evidence_attachments(db, eid):
    return db.execute("SELECT * FROM pm_evidence_attachments WHERE evidence_id=? AND removed_at IS NULL "
                      "ORDER BY id", (eid,)).fetchall()


def evidence_store_attachment(evidence_id, ext, data, content_type=None):
    """Local disk under uploads/evidence/, mirroring pm_store_attachment().

    Outside static/ on purpose: nothing here is ever web-served directly, only
    through a route that checks who is asking.
    """
    target_dir = os.path.join(EVIDENCE_UPLOAD_DIR, str(evidence_id))
    os.makedirs(target_dir, exist_ok=True)
    name = "%s.%s" % (secrets.token_hex(8), ext)
    path = os.path.join(target_dir, name)
    with open(path, "wb") as fh:
        fh.write(data)
    return os.path.relpath(path, EVIDENCE_UPLOAD_DIR), "local"


def evidence_can_view(actor, row):
    """Who may read an item.

    The subject and the author, plus the subject's line manager. Deliberately
    NOT every admin: a diagnostic page listing what people wrote about their own
    year is a different product from the one anybody agreed to.
    """
    if not row:
        return False
    if actor["id"] in (row["subject_id"], row["author_id"]):
        return True
    if (row["state"] if "state" in row.keys() else None) == "draft":
        return False   # a draft is its author's (and, for a note about them, the person's own): nobody else in the chain (1b-04)
    db = get_db()
    subj = db.execute("SELECT manager_id FROM users WHERE id=?",
                      (row["subject_id"],)).fetchone()
    if subj and subj["manager_id"] == actor["id"]:
        return True
    # ...and an APPROVER of a KPI line the item supports (Chris, 2026-09-24): the supporting file of a
    # result they moderate, shown in their review table. Only lines they approve, only KPI links.
    if db.execute(
            "SELECT 1 FROM pm_evidence_links l JOIN pm_kpi_target_approvers ap "
            "ON CAST(ap.kpi_target_id AS TEXT)=l.target_ref "
            "WHERE l.evidence_id=? AND l.target_kind='kpi' AND ap.approver_id=? LIMIT 1",
            (row["id"], actor["id"])).fetchone():
        return True
    # ...and the person CALIBRATING them (2026-09-28): the KPI supporting files are the evidence a calibrated rating
    # is defended with, and the calibrator's AI insight reads them. KPI-linked, SHARED items only, and only for
    # someone inside a calibration scope this login holds (calibration_can_view_subject; never a stranger).
    if (row["state"] if "state" in row.keys() else None) == "shared" and db.execute(
            "SELECT 1 FROM pm_evidence_links WHERE evidence_id=? AND target_kind='kpi' LIMIT 1",
            (row["id"],)).fetchone():
        return bool(calibration_can_view_subject(db, actor, row["subject_id"]))
    return False


# ---------------------------------------------------------------------------
# The guided review  (Phase C, step 2 -- the shell and the Account stage)
#
# FIVE GETs AND NOT ONE POST. Saving a KPI value reuses the module's own
# performance_kpi_autosave(), which step 1 (df38274) made safe for a caller that
# posts one field at a time. The conversation is a READ SURFACE over other
# people's writes, and that is what keeps the whole phase reversible: switch the
# module off and every page it projects is untouched.
# ---------------------------------------------------------------------------
def _review_guard():
    """Employees only, and only while the phase is switched on.

    THE PHASE CHECK IS HERE, not left to the module gate, because the gate maps
    each STAGE to the module whose work it is -- /review/account is 'pm', so with
    the phase off but Performance on, the gate would let it straight through and
    a bookmark would keep the whole surface usable. That is the exact defect
    f72c126 was written to close, and the first version of this shipped with it:
    the module gate answered 404 for /review and 200 for /review/account.

    So both rules apply, and they are different questions. Is this phase running?
    -- here. Is the module whose work this stage is running? -- the gate, from
    MODULE_ENDPOINTS. A new stage inherits the first for free."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    if not cycle_module_on("review"):
        abort(404)
    return u


# --- Demo-only review controls (reset + mechanism switch) --------------------
# Gated to the synthetic demo accounts (is_demo_account: never on production, and
# never a real "ZZ" + digits Employee ID). Lets a tester reset the check-in and hop between the three scoring
# mechanisms without SQL. The mechanism hop is a ZZ->ZZ base-account switch,
# resolved through a fixed map so a tampered `mech` can only 404, never name an
# arbitrary id -- the same authorisation-boundary principle as demo_personas().
REVIEW_DEMO_MECH = {"a": "ZZPMDEMO-EMP", "fiamma": "ZZPMDEMO-FIA1", "signature": "ZZPMDEMO-SIG1"}


def _review_demo_user():
    """current_user() if this is a synthetic demo account (is_demo_account), else None."""
    u = current_user()
    if u and is_demo_account(u):
        return u
    return None


def _review_demo_mech(db, u):
    """Which mechanism the demo subject is on now, to highlight the active toggle."""
    eid = str(_row_get(u, "employee_id") or "")
    for k, v in REVIEW_DEMO_MECH.items():
        if eid == v:
            return k
    row = db.execute(
        "SELECT cfg.mechanism m, cfg.variant v FROM pm_kpi_targets t "
        "JOIN pm_bg_config cfg ON cfg.business_group=t.business_group "
        "WHERE t.subject_id=? AND t.cycle_id=? LIMIT 1",
        (u["id"], active_cycle_id(db))).fetchone()
    if not row:
        return None
    if row["m"] == "A":
        return "a"
    return "signature" if row["v"] == "excellence" else "fiamma"


def _review_manages(db, u):
    """Whether this login has ANY manager-side view -- Team (direct reports) or a leader view (Dept / BU / BG
    calibration, 2026-09-30) -- so the offers and hand-offs to "your team review" still work for an HOD with no
    direct reports. The Team tab itself is _review_manages_team. The real
    predicate for everyone -- demo accounts included -- so the ONE "Viewing as"
    switcher drives it: a Manager persona (who manages people) shows Team Review, an
    employee persona does not. (There is no separate demo Solo/Manager toggle now;
    switch to the Manager persona to see the Team view.)

    The raw demo LOGIN (no persona picked) is what the dropdown then shows as its first option,
    "Employee" -- so it gets the employee view: no Team (Chris, 2026-09-24: "viewing as employee, but
    team is available to me"). ZZPMDEMO-EMP was seeded a small team on 2026-09-11, back when the Solo /
    Manager toggle existed, and the label never said so. Pick Manager (or above) to see a team."""
    return _review_manages_team(db, u) or bool(_journey_leader_views(db, u))


def _review_manages_team(db, u):
    """Whether this login has a TEAM view: direct reports to review (KPI approvals, or competencies). Calibration is
    no longer part of Team -- it lives in the Dept / BU / BG views (Chris, 2026-09-30), so an HOD with no direct
    reports gets Mine | Dept."""
    if _demo_login_shown_as_employee(u):
        return False
    if _leader_unit_out(u, db):   # their unit or department is out of the cycle: they lead nobody in it (2026-10-21)
        return False
    if _pm_manages_anyone(db, u):
        return True
    # A line manager whose direct reports have competencies to review (the TM team review) has a Team view too --
    # they used to get none unless they also approved a KPI line (review, 2026-09-28).
    if _hub_tc_flags(db, u, active_cycle_id(db))[1]:
        return True
    # ...and one whose people write a Career Plan, at Year-End: review_state gives them the plan review (QC 2026-10-24:
    # 43 such line managers on production, 58 people's plans, had no Team tab and only the classic plan page)
    # ...or whose KPI chain they sit in, now that _pm_manages_anyone counts only reports who take part in Performance: the
    # Career Plan's review is not gated by it (2026-10-30), so a leader of Career Plan writers alone keeps their Team tab
    _pd = active_pm_period(db)
    return bool(cycle_module_on("idp", db) and _is_year_end(_pd)
                and (_idp_lm_has_plans(db, u) or (_pd and _pm_approver_subject_ids(db, u, _pd["id"]))))


# ---- The manager-side VIEWS (Chris, 2026-09-30: "For HOD account, add Dept next to Team, move the calibration in and
# remove from Team. Similarly, add BU for BUCEO access, and add BG for BGCEO access"). Mine | Team | Dept | BU | BG:
# Team is the direct-report reviews; each leader view is ONE calibration tier of the login's own, so someone who is
# both an HOD and a BU CEO sees both (the chat used to reach only their first scope). Calibration is Year-End only.
# The view is never stored: it rides on ?view= / the form and is re-validated against the login on every request.
_LEADER_VIEWS = (("dept", "hod", "Dept", "Department Review"),   # an HOD reviews, not calibrates (2026-09-30)
                 ("bu", "buceo", "BU", "Business unit calibration"),
                 ("bg", "bgceo", "BG", "Business group Talent Box"),
                 # a Group Chief's scope across business groups (Chris, 2026-10-10, canvas G2): their AI+ calibration
                 # ...on the BG CEO's Talent Box, for their group as one unit (2026-10-13)
                 ("group", "group", "Group", "Group Talent Box"),
                 # the Executive Chairman's Group Talent Box over every business group, read only (2026-10-29; dark
                 # unless ONEHR_CHAIR=1 and the seat is his: _journey_leader_views)
                 ("chairgrp", "chairgrp", "Group", "Group Talent Box"),
                 # ...and his leaders' Talent Box, where he places them and locks (P4, 2026-10-29; ec.view)
                 ("chairlead", "chair", "Leaders", "Your leaders' Talent Box"))
_VIEW_TIER = {v: t for v, t, _s, _l in _LEADER_VIEWS}
_TIER_VIEW = {t: v for v, t, _s, _l in _LEADER_VIEWS}
_VIEW_SHORT = dict([("mine", "Mine"), ("team", "Team")] + [(v, s) for v, _t, s, _l in _LEADER_VIEWS])
_VIEW_TITLE = dict([("mine", "My Review"), ("team", "Team Review")] + [(v, l) for v, _t, _s, l in _LEADER_VIEWS])


def _view_is_cg(db, u, view):
    """True when the BU-level view is a calibration group's, not a BU CEO's (Chris, 2026-10-26: "For calibrator ... name
    it as CG Calibration ... Only those tagged as BUCEO will see BU naming"): a login with a calibration group and no BU
    CEO seat. The view KEY stays "bu" everywhere (URLs, ?view=, the page's scripts)."""
    if view != "bu" or not u:
        return False
    try:
        ts = calibration_tier_of(db, u)
    except Exception:
        return False
    return any(t == "bugrp" for t, _k in ts) and not any(t == "buceo" for t, _k in ts)


def _view_cg_label(db, u, view):
    """The calibrator view's visible name for this login (BGCFO tag, 2026-11-04): None when it is not a calibrator's
    (_view_is_cg is False), "BGCFO" when EVERY panel the login calibrates in is tagged BGCFO, else "CG" (the general name,
    also for someone with a CG panel and a BGCFO one: one BU-level view holds all their people, and a tab carries one
    name). A label only: _view_is_cg stays the gate's question (True for both kinds)."""
    if not _view_is_cg(db, u, view):
        return None
    tags = {bu_panel_tag(g.get("role_tag")) for g in bu_groups_of_calibrator(db, u["id"])}
    return "BGCFO" if tags == {"BGCFO"} else "CG"


def _view_short(db, u, view):
    """The tab's short name for this login: CG (BGCFO for a BG CFO) for a pure calibrator in the BU-level view, else
    _VIEW_SHORT's."""
    return _view_cg_label(db, u, view) or _VIEW_SHORT.get(view, view)


def _view_title(db, u, view):
    """The view's title for this login: "CG Calibration" ("BGCFO Calibration") for a pure calibrator, else _VIEW_TITLE's."""
    lab = _view_cg_label(db, u, view)
    return ("%s Calibration" % lab) if lab else _VIEW_TITLE.get(view, view)


def _journey_leader_views(db, u):
    """The leader views this login has, in order: a tier of theirs with people in it -- at Year-End, every tier; at
    Mid-Year, the HOD's Department Review only (2026-10-12) -- while the calibration assistant is on for them. The raw
    demo login shown as Employee has none (as it has no Team)."""
    if not u or _demo_login_shown_as_employee(u) or _leader_unit_out(u, db):   # left out of the cycle (2026-10-21)
        return []
    # cached on the REQUEST, not g: a request pushed inside an existing app context shares that context's g
    cache = _req_cache()
    ck = "_jlv_%s" % u["id"]
    if ck in cache:
        return list(cache[ck])
    out = []
    if cycle_row_is_early_year(active_pm_period(db)):   # KPI setting only: no review tier (2026-10-15)
        cache[ck] = ()
        return []
    year_end = _is_year_end(active_pm_period(db))
    tiers = {("buceo" if t == "bugrp" else t) for t, _k in calibration_tier_of(db, u)}   # a group is BU level (2026-10-22)
    for view, tier, _s, _l in _LEADER_VIEWS:
        # Mid-Year has the HOD's Department Review only (Chris, 2026-10-12: "HOD dept review is not a calibration per
        # se"); the BU CEO, BG CEO and Group Chief seats are Year-End only
        if not year_end and tier != "hod":
            continue
        if tier == "chairgrp":   # the Executive Chairman's, and nobody else's (flag on, seat his)
            if is_chair(u):
                out.append(view)
            continue
        if tier == "chair":   # his leaders' Talent Box: his alone, with ec.view (P4)
            if is_chair(u) and leader_can(u, "ec.view", db):
                out.append(view)
            continue
        if tier == "group":   # a Group Chief isn't a line tier (calibration_tier_of leaves groups out on purpose)
            if _journey_group_scope(db, u):
                out.append(view)
            continue
        if tier not in tiers:
            continue
        if tier == "bgceo":
            ok = bool(_journey_talent_box_scope(db, u, tier="bgceo", exists=True))
        else:
            ok = bool(_journey_calib_scope(db, u, tier=tier)) or bool(_pot_calib_scope(db, u, tier=tier))
        if ok:
            out.append(view)
    cache[ck] = tuple(out)
    return out


def _req_cache():
    """A per-REQUEST dict (a throwaway one outside a request). Not flask.g: a request pushed while an app context is
    already active (the test client inside a test_request_context) reuses that context's g, so a g cache can carry one
    request's answer into the next."""
    if not has_request_context():
        return {}
    obj = request._get_current_object()
    c = getattr(obj, "_onehr_cache", None)
    if c is None:
        c = {}
        setattr(obj, "_onehr_cache", c)
    return c


def _review_bg_leader(db, u):
    """Whether this login is a BG CEO (holds a bgceo calibration tier) or a Group Chief (calls a calibration group).
    Chris, 2026-10-05: "for BGCEO, there should only be Team and BG, team is for their direct report, there is no need
    to have Mine tab" -- so their own KPI, competency and plan aren't asked of them (review_state's participant), and
    Mine goes (_journey_views). A Group Chief is the same (Chris, 2026-10-13: "Like the BG CEO"). Cached per request."""
    if not u:
        return False
    cache = _req_cache()
    ck = "_jbgl_%s" % u["id"]
    if ck not in cache:
        cache[ck] = any(t == "bgceo" for t, _k in calibration_tier_of(db, u)) or bool(db.execute(
            "SELECT 1 FROM pm_calibration_groups WHERE calibrator_id=? LIMIT 1", (u["id"],)).fetchone())
    return cache[ck]


def _review_owes_360(db, u):
    """Whether a colleague's 360 still waits on this login this cycle (Mine is where it's given)."""
    cid = active_cycle_id(db)
    return bool(cid and db.execute(
        "SELECT 1 FROM assignments WHERE assessor_id=? AND cycle_id=? AND archived=0 AND status!='submitted' AND "
        + rater_task_sql("assignments") + " LIMIT 1",
        (u["id"], cid)).fetchone())


def _review_gives_360(db, u):
    """Whether this login rates anyone in the 360 this cycle -- still to give or already given."""
    cid = active_cycle_id(db)
    return bool(cid and db.execute(
        "SELECT 1 FROM assignments WHERE assessor_id=? AND cycle_id=? AND archived=0 AND "
        + rater_task_sql("assignments") + " LIMIT 1",
        (u["id"], cid)).fetchone())


def _journey_views(db, u):
    """Every view this login has, in toggle order: Mine, then Team, then Dept / BU / BG. A BG CEO's Mine holds the 360
    only -- no KPI check-in, competency or plan of their own (review_state's participant) -- and is there whenever they
    rate anyone this cycle, still to give or given (Chris, 2026-10-12: "BGCEO will have the Mine tab too in the AI check
    in for the 360 part only"); with no 360 it goes, unless they'd have no view at all."""
    rest = (["team"] if _review_manages_team(db, u) else []) + _journey_leader_views(db, u)
    if rest and _review_bg_leader(db, u) and not _review_gives_360(db, u):
        return rest
    return ["mine"] + rest


# The window cells that open each leader view's tab (Chris, 2026-11-04: "until a view's window opens, its tab is greyed out,
# is not a link, and its hover text is the open date"). A view is usable once ANY of its counted cells has opened.
# `team` swaps in pm_setting_approve in an Early Year. Grade H's HOD and BU CEO cells also open Dept / BU, but only for a login
# holding that Grade H seat (gradeh_audiences), and only while the module runs: the Grade H calibration is a tab on those two views
# and its page links back to them. Team has none: the Grade H line manager's work is on its own pages (the dashboard), never in the
# journey's Team view (no Grade H stage in _journey_team_live_stages), so gradeh_lm never opens Team -- else every line manager's tab
# would open on Grade H's earlier date (Chris's review, 2026-11-04). The Chairman's "Your leaders" tab (CHAIRL_VIEW) opens with
# the BG CEO's Talent Box, the tb_bgceo cell (Chris, 2026-11-04); his Group view (chairgrp) is never greyed.
_VIEW_OPEN_CELLS = {"team": ("pm_approve", "tc_approve", "idp_review"),
                    "dept": ("pm_hod", "pot_hod"),
                    "bu": ("pm_buceo", "pot_buceo"),
                    "bg": ("tb_bgceo",), "group": ("tb_bgceo",), CHAIRL_VIEW: ("tb_bgceo",)}
_VIEW_OPEN_CELLS_GRADEH = {"dept": ("hod", ("gradeh_hod_pot", "gradeh_hod_perf")), "bu": ("buceo", ("gradeh_buceo",))}


def _view_open_raw(db, u, view):
    """None while this view's tab is usable, else the earliest start among its parts as the stored string ('' when none has
    a date): the one rule behind _view_not_open and the all-greyed notice. Mine and the Chairman's Group view are never greyed (his
    "Your leaders" tab opens with tb_bgceo, as the BG CEO's does). A
    part whose module is off for the cycle is ignored, and a view with no part left is usable. Usable as soon as ANY counted
    part is open or has closed (after the deadline the tab stays, readable). Cached per request."""
    if view not in _VIEW_OPEN_CELLS or not u:
        return None
    cache = _req_cache()
    ck = "_vno_%s_%s" % (u["id"], view)
    if ck in cache:
        return cache[ck]
    cid = active_cycle_id(db)
    out = None
    if cid:
        cells = list(_VIEW_OPEN_CELLS[view])
        if view == "team" and cycle_row_is_early_year(active_pm_period(db)):
            cells = ["pm_setting_approve"]
        gh_seat, gh_cells = _VIEW_OPEN_CELLS_GRADEH.get(view, (None, ()))
        if gh_seat and gh_seat in gradeh_audiences(db, u):   # a seat holder only; empty with Grade H off or for an admin
            cells += list(gh_cells)
        counted = [c for c in cells if cycle_module_on(
            GRADEH_MODULE_KEY if c in GRADEH_CELL_KEYS else _PILL_CELL_MODULE[c], db, cid)]
        if counted and all(window_state(db, c, cid) == "not_open" for c in counted):
            raws = [window_dates(db, c, cid)[0] for c in counted]
            raws = [r for r in raws if _parse_when(r)]
            out = min(raws, key=_parse_when) if raws else ""
    cache[ck] = out
    return out


def _view_not_open(db, u, view):
    """None while this view's tab is usable, else the sentence for its greyed tab's hover: 'Opens 09 Nov 2026, 09:00' (the
    earliest start among its parts) or 'Not open yet' when none has a date (Chris, 2026-11-04)."""
    raw = _view_open_raw(db, u, view)
    if raw is None:
        return None
    return ("Opens " + _when_disp(raw)) if raw else "Not open yet"


def _views_closed_note(db, u):
    """The one line shown in place of the card when EVERY view this login has is greyed (a BG CEO or Group Chief with no
    360 to give, nothing open yet): when their first view opens, or that it isn't open yet. None when any view is usable."""
    held = _journey_views(db, u)
    raws = [_view_open_raw(db, u, v) for v in held]
    if not held or any(r is None for r in raws):
        return None
    dated = [r for r in raws if r]
    return ("Your team's reviews open on %s." % _when_disp(min(dated, key=_parse_when))) if dated else \
        "Your team's reviews aren't open yet."


def _journey_req_view(db=None, u=None):
    """The view THIS request shows -- ?view= / the form's view, only if the login holds it AND it has opened (a greyed tab
    is a view not held, _view_not_open), else 'mine'. Cached per request. A crafted ?view=bu from someone who isn't a BU CEO
    is simply the Mine view. With every view of theirs greyed (a BG CEO with no 360 duty, nothing open yet) it is their first
    view, and the page shows the one-line notice there (review_journey)."""
    if not has_request_context():
        return "mine"
    cache = _req_cache()
    if "_jview" in cache:
        return cache["_jview"]
    u = u or current_user()
    db = db or get_db()
    want = (request.values.get("view") or "").strip().lower()
    views = _journey_views(db, u) if u else ["mine"]
    views = [x for x in views if not (u and _view_not_open(db, u, x))] or views   # a greyed tab is a view not held
    # a view the login holds, else Mine -- or, for a login with no Mine (a BG CEO, 2026-10-05), their first view. A BG
    # CEO's Mine is their 360 alone (2026-10-12): opening the page with no view, they land on it only while a
    # colleague's 360 still waits on them, else on their first leader view, as before. Only the page itself: the Mine
    # page's own requests (history, a turn) carry no view and mean Mine.
    land = (request.endpoint == "review_journey" and "mine" in views and len(views) > 1
            and _review_bg_leader(db, u) and not _review_owes_360(db, u))
    v = want if (want in _VIEW_SHORT and want in views) else (
        "mine" if ("mine" in views and not land) else next((x for x in views if x != "mine"), views[0]))
    cache["_jview"] = v
    return v


def _journey_view_tier(db=None, u=None):
    """The calibration tier of the request's leader view ('hod' / 'buceo' / 'bgceo'), or None."""
    if not has_request_context():
        return None
    return _VIEW_TIER.get(_journey_req_view(db, u))


def _tb_group_mode():
    """Whether this request's Talent Box is the Group Chief's (Chris, 2026-10-13: "for the group chief AI+calibration,
    it should follow the same look as the BGCEO talent box calibration"): the Group view's requests say view=group or
    stage=group_calib, and the Group view's own builders set it (_tb_use_group). Read straight off the request -- never
    through _journey_req_view, which itself asks for the BG CEO's box."""
    if not has_request_context():
        return False
    c = _req_cache()
    if "_tb_group" in c:
        return bool(c["_tb_group"])
    return ((request.values.get("view") or "").strip() == "group"
            or (request.values.get("stage") or "").strip() == "group_calib")


def _chairlead_req():
    """Whether this request is for the Executive Chairman's leaders' box (its view or stage), read straight off the request;
    only ever believed for the chair (_journey_talent_box_scope checks is_chair)."""
    if not has_request_context():
        return False
    return ((request.values.get("view") or "").strip() == CHAIRL_VIEW
            or (request.values.get("stage") or "").strip() == CHAIRL_STAGE)


def _tb_use_group():
    """The rest of this request reads the Group Chief's Talent Box (the Group view's own builders call it first)."""
    if has_request_context():
        _req_cache()["_tb_group"] = True


def _tb_store_key(ctx):
    """What a Talent Box's per-person rows (the remark, the AI insight) are keyed on: the business group for a BG CEO's
    box, the calibration group for a Group Chief's -- never the business group there, or a Group Chief and the BG CEO
    would share one row on the same person."""
    return ("group:%s" % ctx["scope_key"]) if ctx.get("tier") == "group" else ctx["business_group"]


def _journey_talent_box_scope(db, u, fresh=False, tier=None, exists=False):
    """The Talent Box scope of the request (_jtb_scope_raw), or None while that box has not opened for a BG CEO / Group Chief
    (Chris, 2026-11-04: hidden until its window opens, _tb_hidden_msg): every reader of the box's people, bands and counts
    (the card, the navigator, the chat's tools, the AI insights) asks here, so none can read it early. `exists=True` is for
    the callers that only ask WHETHER the person has a Talent Box (their view and stage, the dashboard's door, the background
    pre-run): the scope as it is, shown nothing."""
    sc = _jtb_scope_raw(db, u, fresh=fresh, tier=tier)
    if sc and not exists and sc[0] in ("bgceo", "group") and _tb_hidden_msg(db, u):
        return None
    return sc


def _jtb_scope_raw(db, u, fresh=False, tier=None):
    """('bgceo', {'bg': bg}, ctx) -- the BG CEO's Talent Box for the chat's BG view (Chris, 2026-09-30: "For BGCEO, we
    need the talent box calibration and BU selection function"): the calibration assistant on for them, the Talent
    Box's own module (tm) on, a population. The page's own resolver (_talent_box_resolve), so nobody reaches a box
    that isn't theirs. Year-End is the caller's gate (_journey_leader_views). Cached per request.
    In the Group view (_tb_group_mode, or tier='group') it is ('group', {'group_id'}, ctx) -- the Group Chief's own
    group as ONE unit (Chris, 2026-10-13: "loop all selected department or individual for the group chief under one
    'BU' for Group Chief calibration"), through the same resolver; tier='bgceo' always means the BG CEO's."""
    if not u:
        return None
    if tier == "chair" or (tier is None and _chairlead_req() and is_chair(u)):
        # the Executive Chairman's leaders' box (P4): the page's own frame and insight read this scope as his seat
        cache = _req_cache()
        ck = "_jtbc_%s" % u["id"]
        if ck not in cache:
            S = _chairlead_state(db, u)
            cache[ck] = ("chair", {"bg": ""}, S["ctx"]) if (S and S["people"]) else None
        return cache[ck]
    grp = tier == "group" or (tier is None and _tb_group_mode())
    cache = _req_cache()
    ck = "_jtb%s_%s" % ("g" if grp else "", u["id"])
    if not fresh and ck in cache:
        return cache[ck]
    from werkzeug.exceptions import HTTPException
    out = None
    if grp:
        gs = _journey_group_scope(db, u)
        if gs and cycle_module_on("tm", db):
            try:
                ctx = _talent_box_resolve(db, u, "group", group_id=gs[0])
            except HTTPException:
                ctx = None
            if ctx and ctx.get("population"):
                # the names the super admin gave each batch of people (Chris, 2026-10-13): the box's filter row
                ctx["segments"] = {r[0]: r[1] for r in db.execute(
                    "SELECT subject_id, segment FROM pm_calibration_group_members WHERE group_id=? AND "
                    "COALESCE(segment,'')!=''", (gs[0],))}
                out = ("group", {"group_id": gs[0]}, ctx)
        cache[ck] = out
        return out
    if _calib_assist_on(u) and cycle_module_on("tm", db) and active_pm_period(db):
        for tier, key in calibration_tier_of(db, u):
            if tier != "bgceo":
                continue
            try:
                ctx = _talent_box_resolve(db, u, "bgceo", bg=key)
            except HTTPException:
                continue
            if ctx and ctx.get("population"):
                out = ("bgceo", {"bg": key}, ctx)
                break
    cache[ck] = out
    return out


def _journey_talent_box_company():
    """The business unit on the chat's Talent Box: the one picked (?company= / the form's) or the one the agent switched
    to in this turn (show_business_unit), so the card, the navigator and the rebuilt prompt all follow it. Never the
    whole business group (Chris, 2026-10-07: "remove the whole BG view on talent box calibration, it should go by BU by
    BU"): with none, or one that isn't theirs, the first business unit still to lock -- ready first (_tb_pick_company)."""
    if not has_request_context():
        return ""
    ov = _req_cache().get("_tb_company")
    return _tb_pick_company(ov if ov is not None else (request.values.get("company") or "").strip())


def _tb_companies(ctx):
    """The business units of a Talent Box scope, in the box's order (the pills, the navigator). Units calibrated
    together this cycle are one unit, keyed by their lead (admin round 4, row 6)."""
    return sorted({_tb_unit_key(ctx, p["company"]) for p in ctx["population"] if p["company"]})


def _tb_unit_key(ctx, company):
    """The Talent Box unit a business unit belongs to: the lead of the units calibrated together with it, else itself."""
    if not company:
        return company or ""
    j = calib_join(get_db(), ctx.get("cycle_id") or ctx["period"]["id"], ctx["business_group"], company)
    return j["lead"] if j else company


def _tb_unit_members(ctx, key):
    """The business units a Talent Box unit covers (row 6): the joined units, else just the one."""
    j = calib_join(get_db(), ctx.get("cycle_id") or ctx["period"]["id"], ctx["business_group"], key)
    return j["members"] if j else [key]


def _tb_dept_counts(ctx, company):
    """[(department, people)] of one business unit on a Talent Box, by name -- the department row's pills."""
    n = {}
    grp = ctx.get("tier") == "group"   # the Group Chief's one unit: everyone in their group (2026-10-13)
    units = set(_tb_unit_members(ctx, company)) if (company and not grp) else set()
    segs = ctx.get("segments") or {}
    for p in ctx["population"]:
        # a Group Chief's box: the name the super admin gave their batch, else their department
        d = (segs.get(p["id"]) or "").strip() or (p["department"] or "").strip()
        if (grp or (p["company"] or "") in units) and d:
            n[d] = n.get(d, 0) + 1
    return sorted(n.items(), key=lambda x: x[0].lower())


def _pick_list(v, cap=40, width=120):
    """A filter's picks as the list of distinct, trimmed values (several values in one filter, Chris 2026-10-30, canvas board
    E): `v` is one string, a list of them, or None; each is trimmed and cut at `width` (120) characters, repeats are dropped, order
    kept, and no more than `cap` are read (a request cannot make the box test thousands)."""
    if v is None:
        return []
    out = []
    for x in ([v] if isinstance(v, str) else list(v)):
        x = (x or "").strip()[:width]
        if x and x not in out:
            out.append(x)
        if len(out) >= cap:
            break
    return out


def _journey_talent_box_dept(company):
    """The departments picked on the Talent Box, under its business unit (Chris, 2026-10-12: "on the talent box
    calibration, add one more row below the BU filter for the department filter"): every ?dept= / the form's, only those
    that are one of the business unit's own departments; [] is the whole unit. A unit the agent switched to this turn opens
    on the whole unit."""
    if not has_request_context() or _req_cache().get("_tb_company") is not None:
        return []
    sc = _journey_talent_box_scope(get_db(), current_user())
    if not company and not (sc and sc[0] == "group"):   # a Group Chief's box is one unit: its departments are the group's
        return []
    want = _pick_list(request.values.getlist("dept"))
    # a BG CEO's unit shows departments only where the super admin switched the filter on (2026-10-17); the Group
    # Chief's batches are not a business unit's departments and always show
    if sc and sc[0] != "group" and not calib_dept_filter_shown(get_db(), sc[2]["business_group"], [company], "tb"):
        return []
    if not sc:
        return []
    valid = dict(_tb_dept_counts(sc[2], company))
    return [w for w in want if w in valid]


def _journey_talent_box_cal(company):
    """The BU-level calibrators picked on a BG CEO's Talent Box (every ?cal= / the form's: 'ceo' or 'grp:<id>'), as asked; []
    is the whole unit. Whether each is one of the unit's is checked against the box's own members
    (_journey_talent_box_overview). A unit the agent switched to this turn opens on the whole unit."""
    if not has_request_context() or _req_cache().get("_tb_company") is not None or not company:
        return []
    return [v for v in _pick_list(request.values.getlist("cal"))
            if v == "ceo" or re.fullmatch(re.escape(BU_GROUP_PREFIX) + r"\d+", v)]


def _journey_talent_box_jg(company):
    """The JG pills picked on a BG CEO's Talent Box (every ?jg= / the form's), as the row's keys: only where the super admin
    switched the JG row on for that unit (2026-10-21), and only keys the grouping knows; [] is every grade. Whether anyone
    holds each is checked against the box's own options (_journey_talent_box_overview)."""
    if not has_request_context() or _req_cache().get("_tb_company") is not None or not company:
        return []
    sc = _journey_talent_box_scope(get_db(), current_user())
    if not sc or sc[0] == "group":   # a Group Chief's batches have no JG row (2026-10-21)
        return []
    want = [w for w in _pick_list(request.values.getlist("jg")) if re.fullmatch(r"\d{1,2}(-\d{0,2})?|other", w)]
    return want if want and calib_jg_filter_shown(get_db(), sc[2]["business_group"], [company], "tb") else []


def _journey_talent_box_extra(key, company):
    """The roster picks on a BG CEO's Talent Box for a registry filter that reads the roster (every ?cc= / ?branch= / the
    form's): as asked, trimmed and capped, as a list; CALIB_NOT_SET is the explicit "Not set on the roster". Whether each is
    one of the unit's own values, and whether the filter is on for the unit, is checked by _journey_talent_box_overview. A
    unit the agent switched to this turn opens on the whole unit."""
    if not has_request_context() or _req_cache().get("_tb_company") is not None or not company:
        return []
    return _pick_list(request.values.getlist(key))


def _tb_pick_company(want):
    """`want` when it is one of the BG CEO's business units, else the first one still to lock, in the box's order, then
    the first: each visit lands on the next one to do. The BG CEO never waits on a BU CEO (Chris, 2026-10-07: "BGCEO
    will supersede all entries"), so whether its BU CEO has locked plays no part. Once per request. '' only for a
    scope with no business unit at all."""
    sc = _journey_talent_box_scope(get_db(), current_user()) if has_request_context() else None
    if not sc:
        return want
    if sc[0] == "group":   # the Group Chief's box is one unit: their whole group (2026-10-13)
        return ""
    ctx = sc[2]
    cos = _tb_companies(ctx)
    if want in cos:
        return want
    cache = _req_cache()
    if "_tb_default_co" not in cache:
        db = get_db()
        bul = set(_tb_bu_locks(db, ctx["period"]["id"], ctx["business_group"]))
        whole = bool(ctx["pm_session"] and ctx["pm_session"]["locked_at"]) and \
            bool(ctx["pot_session"] and ctx["pot_session"]["locked_at"])
        cache["_tb_default_co"] = ((None if whole else next((c for c in cos if c not in bul), None))
                                   or (cos[0] if cos else ""))
    return cache["_tb_default_co"]


def _talent_box_bu_label(bg, company):
    if company and has_request_context():   # units calibrated together are one unit on the box (row 6)
        _db = get_db()
        j = calib_join(_db, active_cycle_id(_db), bg, company)
        if j and j["lead"] == company:
            return " and ".join([", ".join(COMPANY_SHORT.get(m) or display_company(bg, m) or m
                                           for m in j["members"][:-1]),
                                 COMPANY_SHORT.get(j["members"][-1]) or display_company(bg, j["members"][-1])
                                 or j["members"][-1]])
    return COMPANY_SHORT.get(company) or display_company(bg, company) or company


def _tb_cal_members(db, ctx, co, bg=None):
    """{key: [subject id]} of a unit on the Talent Box by who calibrates them at BU level (2026-10-26): 'ceo' for the
    people its BU CEO calibrates, 'grp:<id>' for each calibrator's; a person several share sits under each of them."""
    bg = bg or ctx.get("business_group")
    j = calib_join(db, ctx.get("cycle_id") or ctx["period"]["id"], bg, co) if (co and bg) else None
    mem = set(j["members"]) if j else ({co} if co else set())
    out = {}
    for p in ctx.get("population") or ():
        if (p["company"] or "") in mem:
            for k in [BU_GROUP_PREFIX + str(g["id"]) for g in bu_groups_of_person(db, p)] or ["ceo"]:
                out.setdefault(k, []).append(p["id"])
    return out


def _tb_bu_level(db, ctx, bg, co, members=None):
    """The BU level of a unit whose departments are partly in calibration groups (2026-10-22): [{key, who, title, locked,
    n}], its BU CEO first ('ceo'), then each calibrator ('grp:<id>'); locked = both axes; n = the people each calibrates
    on this box (the row is the calibrator filter since 2026-10-26). Empty for a unit with no group. The BG CEO never
    waits on it; the Talent Box says who has locked."""
    grps = bu_groups_of_unit(db, bg, co) if co else []
    if not grps:
        return []
    members = members if members is not None else _tb_cal_members(db, ctx, co, bg)
    pk = bu_unit_scope_keys(db, ctx["period"]["id"], bg, co, "pm")
    qk = bu_unit_scope_keys(db, ctx["cycle_id"], bg, co, "pot")
    out = []
    for k in [co] + [BU_GROUP_PREFIX + str(g["id"]) for g in grps]:
        if k not in pk and k not in qk:
            continue
        locked = all(db.execute("SELECT 1 FROM %s WHERE cycle_id=? AND tier='buceo' AND business_group=? AND scope_key=? "
                                "AND locked_at IS NOT NULL" % t, (c, bg, k)).fetchone() is not None
                     for t, c, keys in (("pm_calibration_sessions", ctx["period"]["id"], pk),
                                        ("calibration_sessions", ctx["cycle_id"], qk)) if k in keys)
        if k == co:
            out.append({"key": "ceo", "who": "BU CEO", "title": "Its BU CEO, for the people outside the groups",
                        "locked": locked, "n": len(members.get("ceo") or ())})
        else:
            g = bu_group(db, k[len(BU_GROUP_PREFIX):])
            mates = [x for x in grps if x.get("panel_id") and x.get("panel_id") == (g or {}).get("panel_id")]
            if g and len(mates) > 1:   # one of a panel's calibrators (2026-10-26): by their own tag, never the panel's name
                c = db.execute("SELECT full_name, job_title FROM users WHERE id=?", (g["calibrator_id"],)).fetchone()
                nm = c["full_name"] if c else "their calibrator"
                out.append({"key": k, "who": _bu_cal_tag(c, nm), "title": "%s%s · %s" % (
                    nm, (", " + proper_name(c["job_title"])) if c and c["job_title"] else "",
                    (bu_panels_all(db).get(g["panel_id"]) or {}).get("name") or ""), "locked": locked,
                    "n": len(members.get(k) or ())})
                continue
            by = bu_group_by(db, g)
            out.append({"key": k, "who": by.get("by") or "Group", "title": by.get("by_title") or "", "locked": locked,
                        "n": len(members.get(k) or ())})
    return out


def _talent_box_pending(db, ctx):
    """The BUs whose CEO hasn't locked BOTH axes yet -- shown on the box for information only; the BG CEO never waits on them (2026-10-07)."""
    bg = ctx["business_group"]
    return ({x[0] for x in pm_calibration_pending_children(db, ctx["period"]["id"], "bgceo", bg)}
            | {x[0] for x in calibration_pending_children(db, ctx["cycle_id"], "bgceo", bg)})


def _tb_band_trails(db, ctx, rows):
    """{subject_id: {"perf": [step...], "pot": [step...]}} -- how each band reached the Talent Box: Self -> line manager
    -> HOD -> BU CEO (Chris, 2026-10-07: "Add an icon to both performance and potential, by hovering it should show the
    movement of the bands from self -> LM -> HOD -> BUCEO"), then this seat's own move, or a tier above that decided it.
    A step is [who, band, state], compact because a business unit can hold hundreds: state "moved" (changed what came
    in), "kept", "set" (a first band), "none" (no record), "wait" (that tier hasn't locked yet) or "na" (no HOD or business
    unit on record). A HOD or BU CEO counts
    once their tier has LOCKED -- the box's own rule, so a tier's working state never shows -- and the band after them is
    what they kept or moved it to. Four reads for the whole scope, never one per person."""
    out = {}
    if not rows:
        return out

    def tier_reads(sess_t, adj_t, cycle_id):
        ses = {(r["tier"], r["scope_key"]): r["id"] for r in db.execute(
            "SELECT id, tier, scope_key FROM %s WHERE cycle_id=? AND tier IN ('hod','buceo') AND locked_at IS NOT NULL"
            % sess_t, (cycle_id,))}
        adj = {}
        if ses:
            ids = sorted(ses.values())
            for a in db.execute("SELECT session_id, subject_id, adjusted_band FROM %s WHERE session_id IN (%s)"
                                % (adj_t, ",".join("?" * len(ids))), ids):
                adj[(a["session_id"], a["subject_id"])] = a["adjusted_band"]
        return ses, adj

    reads = {"perf": tier_reads("pm_calibration_sessions", "pm_calibration_adjustments", ctx["period"]["id"]),
             "pot": tier_reads("calibration_sessions", "calibration_adjustments", ctx["cycle_id"])}

    def step(k, band, before):
        return [k, band or None, "none" if not band else "set" if not before else "kept" if band == before else "moved"]

    for r in rows:
        p = r["user"]
        trail = {}
        for ax in ("perf", "pot"):
            ses, adj = reads[ax]
            selfb, lmb = r.get(ax + "_self"), r.get(ax + "_lm")
            steps = [step("self", selfb, None), step("lm", lmb, selfb)]
            cur = lmb
            for tier, key in (("hod", str(p["hod_id"]) if hod_has_role(db, p["hod_id"]) else None),   # a calibrator is no HOD
                              ("buceo", bu_scope_key(db, p) if p["company"] else None)):
                if tier == "buceo" and key and bu_shared(db, p):
                    # several calibrators (2026-10-26): each one, then their weighted average -- the band the box shows
                    # came up; a step's fourth item is its label
                    parts = bu_cal_parts(db, "pm" if ax == "perf" else "pot",
                                         ctx["period"]["id"] if ax == "perf" else ctx["cycle_id"], p)
                    for x in parts:
                        steps.append((step("cal", x["band"] or cur, cur) if x["locked"] else ["cal", None, "wait"])
                                     + ["%s %d%%" % (x["tag"], x["weight"])])
                    lk = [x for x in parts if x["locked"]]
                    avg = bu_blend_n([(x["band"] or cur, x["weight"]) for x in lk],
                                     PM_BAND_ORDER if ax == "perf" else list(_POT_BANDS)) if lk else None
                    steps.append((step("avg", avg, cur) if avg else ["avg", None, "wait"]) + ["Average"])
                    cur = avg or cur
                    continue
                sid = ses.get((tier, key)) if key else None
                if sid is None:
                    steps.append([tier, None, "wait" if key else "na"])   # na: no HOD / business unit on record
                    continue
                b = adj.get((sid, p["id"]), cur)
                steps.append(step(tier, b, cur))
                cur = b or cur
            src = r.get(ax + "_source")
            if r.get(ax + "_adjusted"):          # this seat's own move on the box
                steps.append(step("you", r.get(ax + "_band"), cur))
            elif src in ("group", "super", "bgceo"):   # a tier above the BU CEO decided it
                steps.append(step(src, r.get(ax + "_band"), cur))
            trail[ax] = steps
        out[p["id"]] = trail
    return out


def _tb_group_tags(db, period_id):
    """{subject_id: tag} for everyone in a Group Chief's scope (canvas G2's right side, 2026-10-10: the BG CEO's box keeps
    them, tagged): the scope's name and Group Chief, how the two calls combine, the Group Chief's call and whether it is
    locked, and the super admin's final band once decided. Whole-table reads (the group tables are small), no IN list."""
    mem = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT gm.subject_id, g.id AS gid, g.name, u.full_name AS chief FROM pm_calibration_group_members gm "
        "JOIN pm_calibration_groups g ON g.id=gm.group_id LEFT JOIN users u ON u.id=g.calibrator_id")}
    if not mem:
        return {}
    calls = {(r["scope_key"], r["subject_id"]): dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band, cs.locked_at, cs.scope_key FROM pm_calibration_adjustments ca "
        "JOIN pm_calibration_sessions cs ON cs.id=ca.session_id WHERE cs.cycle_id=? AND cs.tier='group'", (period_id,))}
    locks = {(r["group_id"], r["subject_id"]) for r in db.execute(
        "SELECT group_id, subject_id FROM pm_group_locks WHERE cycle_id=?", (period_id,))}
    final = {r["subject_id"]: r["adjusted_band"] for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band FROM pm_calibration_adjustments ca JOIN pm_calibration_sessions cs "
        "ON cs.id=ca.session_id WHERE cs.cycle_id=? AND cs.tier='super' AND cs.scope_key=?",
        (period_id, PM_SUPER_SCOPE_KEY))}
    out = {}
    for sid, m_ in mem.items():
        c = calls.get((str(m_["gid"]), sid))
        _sh = gc_chief_share(_calib_group_mode_of(m_["gid"]))
        out[sid] = {"name": m_["name"], "chief": m_["chief"] or "", "mode": "Group Chief %d : BG CEO %d" % (
            _sh, 100 - _sh), "call": c["adjusted_band"] if c else None,
            "locked": bool(c and (c["locked_at"] or (m_["gid"], sid) in locks)), "final": final.get(sid),
            "ro": _sh == 100}   # the split's 100 : 0: the BG CEO reads only (2026-10-22)
    return out


VF_SEP = "\x1f"   # between a business group and its department in a Group Chief's department option (never in a name)
VF_PICK_KEYS = ("seg", "bg", "dept", "jg", "cc", "branch")


def calib_chain(people, specs, picks):
    """THE FILTER LINE FOR A POPULATION (Chris, 2026-11-02, canvas "OneHR Calibration Filters by Viewer": the Group Chief's box and the
    Executive Chairman's, the BG CEO's rules): one chip per spec, in order, each counted within the picks BEFORE it, a person
    matching ANY ticked value of one chip and every chip (AND), a pick the people left no longer hold dropped. The BG CEO's own box
    keeps its path in _journey_talent_box_overview (its output is pinned byte for byte); this builds the same chip dict for the others.
    `specs`: [{key, label, chip, plural, bare?, val(person) -> the person's value ("" = none), label_of(value), order(value),
    notset?}], `picks`: {key: [values]}. Returns {"chips": [chip as the box draws it], "picks": {key: kept values}, "ids": the
    ids of the people who pass every pick (None when nothing is picked), "n": how many that is, "words": the picks in words}."""
    pool = list(people)
    chips, kept, earlier, words = [], {}, [], []
    for sp in specs:
        key = sp["key"]
        cnt, none_n = {}, 0
        for p in pool:
            v = sp["val"](p)
            if v:
                cnt[v] = cnt.get(v, 0) + 1
            else:
                none_n += 1
        notset = none_n if sp.get("notset") else 0
        lab = sp.get("label_of") or (lambda k: k)
        opts = [{"key": k, "label": lab(k), "n": n} for k, n in sorted(cnt.items(), key=lambda kv: sp["order"](kv[0]))]
        want = _pick_list(picks.get(key), width=300)
        sel = [w for w in want if w in cnt or (w == CALIB_NOT_SET and notset)]
        kept[key] = sel
        labels = ["Not set" if k == CALIB_NOT_SET else lab(k) for k in sel]
        if len(opts) + (1 if notset else 0) >= 2 or sel:
            chips.append({"key": key, "label": sp["label"], "chip": sp["chip"], "bare": bool(sp.get("bare")),
                          "plural": sp["plural"], "proper": False, "values": list(sel), "value_labels": labels,
                          "value": sel[0] if sel else "", "value_label": labels[0] if sel else "", "all": len(pool),
                          "options": opts, "not_set": notset, "search": len(opts) >= CALIB_FILTER_SEARCH_MIN,
                          "earlier": list(earlier)})
        if sel:
            w = labels[0] if len(sel) == 1 else "%d %s" % (len(sel), sp["plural"])
            earlier.append(w)
            words.append(("No " + sp["label"].lower()) if sel == [CALIB_NOT_SET] else w)
            pool = [p for p in pool if (sp["val"](p) or (CALIB_NOT_SET if sp.get("notset") else None)) in sel]
    picked = any(kept.values())
    return {"chips": chips, "picks": kept, "ids": {p["id"] for p in pool} if picked else None, "n": len(pool), "words": words}


def _vf_picks(keys=VF_PICK_KEYS):
    """The picks a request carries (every ?seg= ?bg= ?dept= ?jg= ?cc= ?branch=, repeated) as {key: [values]}; none when a unit the agent
    switched to this turn is on screen (as _journey_talent_box_dept), or outside a request."""
    if not has_request_context() or _req_cache().get("_tb_company") is not None:
        return {}
    return {k: request.values.getlist(k) for k in keys}


def _vf_grade(g):
    """A job grade as the line's value: the number ("14"), or a letter grade as written ("GM"); "" when there is none."""
    if g is None or (isinstance(g, str) and not g.strip()):
        return ""
    n = grade_num(g)
    return str(n) if n is not None else str(g).strip()


def _vf_grade_order(v):
    return (0, int(v), "") if v.isdigit() else (1, 0, v.lower())


def _vf_grade_label(v):
    return "JG " + v if v.isdigit() else v


def _vf_group_specs(db, people, shown, seg_of):
    """The Group Chief's line, in order: Segment (always), then the shown ones of Business group, Department, Job grade, Cost
    centre, Branch. A department option is a department AND a business group; its label is its proper name alone when only one
    of the group's business groups holds that name, else "<Department> · <business group>"."""
    holders = {}
    for p in people:
        d = proper_name((p["department"] or "").strip())
        if d:
            holders.setdefault(d, set()).add(p["business_group"] or "")
    bg_name = lambda b: display_bg(b) or b   # noqa: E731

    def dept_label(k):
        bgk, _sep, d = k.partition(VF_SEP)
        n = proper_name(d)
        return n if len(holders.get(n, ())) <= 1 else "%s · %s" % (n, bg_name(bgk))
    specs = [{"key": "seg", "label": "Segment", "chip": "Segment", "plural": "segments", "val": seg_of,
              "label_of": proper_name, "order": lambda k: proper_name(k).lower()}]   # read as the batch pills did
    for k in shown:
        if k == "bg":
            specs.append({"key": "bg", "label": "Business group", "chip": "BG", "plural": "business groups",
                          "val": lambda p: p["business_group"] or "", "label_of": bg_name,
                          "order": lambda k: bg_name(k).lower()})
        elif k == "dept":
            specs.append({"key": "dept", "label": "Department", "chip": "Department", "plural": "departments",
                          "val": lambda p: ((p["business_group"] or "") + VF_SEP + (p["department"] or "").strip())
                          if (p["department"] or "").strip() else "", "label_of": dept_label,
                          "order": lambda k: (dept_label(k).lower(), k)})
        elif k == "jg":
            specs.append({"key": "jg", "label": "Job grade", "chip": "JG", "bare": True, "plural": "job grades",
                          "val": lambda p: _vf_grade(p["job_grade"]), "label_of": _vf_grade_label,
                          "order": _vf_grade_order, "notset": True})
        else:
            f = calib_filter_def(k)
            specs.append({"key": k, "label": f["label"], "chip": calib_filter_chip(f), "plural": f["plural"],
                          "val": (lambda c: lambda p: (str(p[c] or "")).strip())(f["column"]), "order": lambda k: k.lower(),
                          "notset": True})
    return specs


def _tb_group_chain(db, ctx, gid):
    """A Group Chief's filter line (2026-11-02): the chips and what the picks leave, over the group's people. Segment is always on;
    the rest is the group's own set (calib_viewer_filter, kind 'gc'; none = Segment alone). A segment is the name the super admin
    gave a batch of people, else their department (as before: the batches the pills named)."""
    segs = ctx.get("segments") or {}
    own = calib_viewer_filters(db, "gc", gid)
    shown = calib_viewer_shown_keys(own, "gc") if own else []
    pop = list(ctx["population"])
    seg_of = lambda p: (segs.get(p["id"]) or "").strip() or (p["department"] or "").strip()   # noqa: E731
    return calib_chain(pop, _vf_group_specs(db, pop, shown, seg_of), _vf_picks())


def _journey_talent_box_overview(db, u, sc=None, company=None, dept=None, all_filters=False, picks=None):
    """The chat's Talent Box card: the page's own data (_talent_box_data) for the picked BU, as the client draws it --
    a 3x3 of potential (High -> Low) by performance (Low / Mid / High), each box's label, count, reference share and
    people; the unplaced with their reason; the BUs with their lock state; the lock and where it returns. `company`:
    the admin's copy picks its own business unit (admin_talent_box); the chat's follows the BG CEO's.
    `all_filters` + `picks` (the admin's copy, Chris 2026-10-30, canvas board D): every registry filter the unit has
    something to choose between, whatever the Settings rules say (they govern what the leaders see), and the picks as the
    page's own request asked ({dept, cal, jg, cc, branch}, each a list of the values picked: a person matches ANY value of a
    filter, and the filters combine); each is checked against the unit's own values below."""
    picks = {k: _pick_list(v) for k, v in (picks or {}).items()}
    sc = sc or _journey_talent_box_scope(db, u)
    if not sc:
        return None
    tier, kw, ctx = sc
    grp = tier == "group"   # a Group Chief's box: their group as ONE unit (2026-10-13)
    co = "" if grp else (_journey_talent_box_company() if company is None else company)
    if dept is None:   # the chat's follows the departments picked; the admin's copy takes its own request's
        depts_p = _journey_talent_box_dept(co) if company is None else picks.get("dept", [])
    else:
        depts_p = _pick_list(dept)
    _dvalid = dict(_tb_dept_counts(ctx, co))
    depts_p = [d_ for d_ in depts_p if d_ in _dvalid]
    # a Group Chief's box narrows by the filter line (Segment, then the group's own set, 2026-11-02), never the batch pills
    gchain = _tb_group_chain(db, ctx, int(ctx["scope_key"])) if grp else None
    if grp:
        depts_p = []
    # the grid, the list, the counts and both curves are the department's when one is picked; the lock stays the whole
    # business unit's
    bg = ctx["business_group"]
    df_on = (calib_dept_filter_shown(db, bg, [co], "tb") or (all_filters and bool(co))) if not grp else True
    if not df_on:
        depts_p = []   # no department row here, so no department either: the whole unit
    # the CAL row under DEPT (canvas A, 2026-10-26: "we can show both DEPT and CAL"): who calibrates them at BU level,
    # counted within the department picked; a calibrator with nobody there drops out, and a pick of theirs with it
    cal_on = bool(co) and not grp and (all_filters or calib_cal_filter_shown(db, bg, [co], "tb"))
    cal_mem = _tb_cal_members(db, ctx, co) if cal_on else {}
    if cal_on and depts_p:
        _din = {p["id"] for p in ctx["population"] if (p["department"] or "").strip() in depts_p}
        cal_mem = {k: [i for i in v if i in _din] for k, v in cal_mem.items()}
    cals_p = (_journey_talent_box_cal(co) if company is None else picks.get("cal", [])) if cal_on else []
    cals_p = [c_ for c_ in cals_p if cal_mem.get(c_)]   # a calibrator with nobody there falls away
    cal_ids = {i for c_ in cals_p for i in cal_mem[c_]} if cals_p else None
    # the JG row under it (2026-10-21): the grades of the unit (and the department picked) grouped as the business group
    # says, the pill picked narrowing the grid, the list, the counts and both curves; the lock stays the whole unit's
    jg_on = bool(co) and not grp and (all_filters or calib_jg_filter_shown(db, bg, [co], "tb"))
    jgs_p, jgs, f_jgs = [], [], ()
    if jg_on:
        jgs_p = _journey_talent_box_jg(co) if company is None else picks.get("jg", [])
        cfg = calib_jg_config(db, bg)
        _mem = set(_tb_unit_members(ctx, co))
        _grades = [p["job_grade"] for p in ctx["population"] if (p["company"] or "") in _mem
                   and (not depts_p or (p["department"] or "").strip() in depts_p)
                   and (cal_ids is None or p["id"] in cal_ids)]
        jgs = calib_jg_options(cfg, _grades)
        _jkeys = {o["key"] for o in jgs}
        jgs_p = [j_ for j_ in jgs_p if j_ in _jkeys]
        if jgs_p:   # every grade of every band ticked
            f_jgs = sorted({str(g) for g in _grades if g not in (None, "") and calib_jg_key_of(cfg, g) in jgs_p})
    # the roster-backed filters after it (Cost centre, then Branch; CALIB_FILTERS, 2026-10-30): each counted within the
    # picks before it, a value only where the unit has it, "Not set on the roster" for the people without one
    pool = []   # the unit's people the picks so far leave
    if co and not grp:
        _mem2 = set(_tb_unit_members(ctx, co))
        pool = [p for p in ctx["population"] if (p["company"] or "") in _mem2
                and (not depts_p or (p["department"] or "").strip() in depts_p)
                and (cal_ids is None or p["id"] in cal_ids)
                and (not f_jgs or str(p["job_grade"]) in f_jgs)]
    xf = {}   # key -> {"on", "pick", "opts", "notset", "earlier"}
    for _f in CALIB_FILTERS:
        if _f["table"] or not _f["column"]:   # Department, Calibrator and Job grade are built above
            continue
        _k = _f["key"]
        _on = bool(co) and not grp and (all_filters or calib_filter_shown(db, bg, [co], "tb", _k))
        xf[_k] = {"on": _on, "pick": [], "opts": [], "notset": 0}
        if not _on:
            continue
        _cnt, _none = {}, 0
        for p in pool:
            v = calib_roster_value(_f, p)
            if v:
                _cnt[v] = _cnt.get(v, 0) + 1
            else:
                _none += 1
        xf[_k]["opts"] = [{"key": v, "label": v, "n": n} for v, n in sorted(_cnt.items(), key=lambda x: x[0].lower())]
        xf[_k]["notset"] = _none
        xf[_k]["all"] = len(pool)
        _want = _journey_talent_box_extra(_k, co) if company is None else picks.get(_k, [])
        xf[_k]["pick"] = [w for w in _want if w in _cnt or (w == CALIB_NOT_SET and _none)]   # a value the unit lacks falls away
        if xf[_k]["pick"]:   # ANY of the values ticked
            pool = [p for p in pool if (calib_roster_value(_f, p) or CALIB_NOT_SET) in xf[_k]["pick"]]
    x_picked = any(v["pick"] for v in xf.values())
    f_ids = cal_ids
    if x_picked:   # the people who pass every pick (Calibrator included), as the box's own id filter
        f_ids = {p["id"] for p in pool}
    if gchain:
        f_ids = gchain["ids"]
    D = _talent_box_data(db, u, tier, ctx, kw, co, f_depts=depts_p or (), f_jgs=f_jgs, f_ids=f_ids)
    pend = set() if grp else _talent_box_pending(db, ctx)
    # the BG CEO's own lock, one business unit at a time (2026-10-07); a business group locked on BOTH axes locks every
    # one. One axis locked on its classic page alone is no business unit's lock -- the box still refuses every move
    # (D["locked"], the OR) and says so.
    bul = set() if grp else set(_tb_bu_locks(db, ctx["period"]["id"], bg))
    tbl = lambda c: (bool(D["pm_locked"]) and bool(D["pot_locked"])) or (c or "") in bul
    trails = _tb_band_trails(db, ctx, D["rows"])   # the band trail behind each band's icon (2026-10-07)
    gtags = {} if grp else _tb_group_tags(db, ctx["period"]["id"])   # who sits in a Group Chief's scope (2026-10-10)
    below = _tb_group_below(db, ctx, D["rows"]) if grp else {}   # the BG CEO's side of a Group Chief's call
    newly = newly_confirmed_ids(db, ctx["period"]["id"])   # added with a Confirmation rating (2026-10-22)
    behalf_lm = lm_behalf_ids(db, ctx["period"]["id"])   # their line manager assessed them on their behalf (2026-10-26)
    nodata = nodata_map(db, ctx["period"]["id"], [r_["user"]["id"] for r_ in D["rows"]])   # no KPI lines / no 360 (2026-11-02)
    transfer = pm_split_tags(db, ctx["period"]["id"], [r_["user"]["id"] for r_ in D["rows"]],
                             {r_["user"]["id"]: r_.get("overall") for r_ in D["rows"]})   # Transferred (2026-11-03)
    _bgrp = {}   # who calibrates each grouped person at BU level (2026-10-22), by group

    def bugrp_of(user):
        gs_ = bu_groups_of_person(db, user)   # every calibrator of theirs, one tag (2026-10-26)
        if not gs_:
            return None
        k_ = tuple(g_["id"] for g_ in gs_)
        if k_ not in _bgrp:
            _bgrp[k_] = bu_groups_by(db, gs_)
        return _bgrp[k_]

    def bucalls_of(r):
        """Each calibrator's weight and band, and the BU-level band they make, on both axes (Chris, 2026-10-26: "it
        should show for the calibrated band, (calibrator name, weigh, final band)"). None outside a panel."""
        if grp or not bu_groups_of_person(db, r["user"]):
            return None
        return {"perf": bu_parts_view(db, "pm", ctx["period"]["id"], r["user"], raw_band=r.get("perf_lm")),
                "pot": bu_parts_view(db, "pot", ctx["cycle_id"], r["user"])}

    def person(r):
        m = r.get("moved") or {}
        _pbg = (_row_get(r["user"], "business_group") or bg) if grp else bg   # a group spans business groups
        return dict({"id": r["user"]["id"], "name": r["user"]["full_name"], "dept": _row_get(r["user"], "department"),
                "grade": _row_get(r["user"], "job_grade"), "company": _row_get(r["user"], "company"),
                "bg_label": display_bg(_pbg) if (grp and _pbg) else "",
                "bu": _talent_box_bu_label(_pbg, _row_get(r["user"], "company") or "") if _row_get(r["user"], "company") else "",
                "perf": r["perf_band"], "pot": r["pot_band"], "category": r["category"],
                "moved": bool(m), "up": bool(m.get("up")), "from_cat": m.get("from_cat"),
                # ...and where that box sits (a cell key, "col|pot"), so the page can say from which box to which
                # (Chris, 2026-10-07): Solid Core is four boxes, Star and PIP two each
                "from_key": ("%s|%s" % (m.get("from_col"), m.get("from_pot"))) if m else None,
                # what the move cap reads (Chris, 2026-10-07, the box's own Move): the category their RAW bands put
                # them in, and whether this calibration has already changed it -- a second move of someone already
                # re-categorised, or a move back, never uses another one
                "orig_cat": talent_category_of_row(r), "recat": talent_row_recategorised(r),
                # which record each band came from, "default" when there is none (2026-10-07)
                "perf_src": r.get("perf_source"), "pot_src": r.get("pot_source"),
                "locked": tbl(_row_get(r["user"], "company")),   # their business unit is locked: no move
                "trail": trails.get(r["user"]["id"]),
                "grp": gtags.get(r["user"]["id"]),
                "newly": r["user"]["id"] in newly, "behalf_lm": r["user"]["id"] in behalf_lm,
                **_nd_kw(nodata, r["user"]["id"]), **_tr_kw(transfer, r["user"]["id"]),
                "bugrp": None if grp else bugrp_of(r["user"]),
                "bucalls": bucalls_of(r),
                "is_self": r["user"]["id"] == u["id"]},
                # a Group Chief's box: the BG CEO's side of each person and a call they locked one by one before
                **(below.get(r["user"]["id"]) or {}))
    cells = []
    for pot in reversed(TALENT_POTENTIAL_ORDER):
        for col in D["col_order"]:
            key = "%s|%s" % (col, pot)
            ppl = D["cells"][(col, pot)]
            cells.append({"key": key, "col": col, "pot": pot, "label": D["cell_cats"].get(key), "n": len(ppl),
                          "ref": D["cell_ref"].get(key), "target": D["cell_target"].get(key),
                          "people": [person(r) for r in ppl]})
    both = D["pm_locked"] and D["pot_locked"]
    pat = {} if grp else _talent_box_pat(db, ctx)
    # each axis's spread for the view on screen against its expected curve -- the performance curve the BU's PAT picks
    # (a unit's own; the whole group has none), the potential's 15-70-15 -- for the curve pop-outs (2026-10-05)
    pd = {b: 0 for b in PM_BAND_ORDER}
    qd = {b: 0 for b in _POT_BANDS}
    for r in D["rows"]:
        if r["perf_band"] in pd:
            pd[r["perf_band"]] += 1
        if r["pot_band"] in qd:
            qd[r["pot_band"]] += 1

    def _curve(dist, target, order, labels, label, gaps):
        n = sum(dist.values())
        return {"band_order": list(order), "label_names": labels, "distribution": dist, "target": target,
                "gaps": gaps, "total": n, "tolerance": calib_tolerance(n),
                "breaches": _calib_over_framework(gaps, n) if n else {}, "curve": {"label": label}}
    pcv = D["curve"] if isinstance(D["curve"], dict) else None
    if grp and not pcv:   # a group spans business groups, so no PAT of its own: the normal curve, said so (2026-10-13)
        _k = pm_curve_key_for_pct(None)
        pcv = {"dist": PM_DIST_CURVES[_k], "label": PM_CURVE_LABELS[_k][0], "pct": None, "entered": False,
               "scope": "group"}
    perf_curve = _curve(pd, (pcv or {}).get("dist") or {}, PM_BAND_ORDER, PM_LABEL_NAMES,
                        (pcv or {}).get("label") or "", pm_calibration_target_gaps(pd, (pcv or {}).get("dist") or {}))
    if pcv:   # the PAT figure that picked the performance curve, said in the curve's own pop-up
        perf_curve["curve"].update({"pct": pcv.get("pct"), "entered": bool(pcv.get("entered")),
                                    "scope": pcv.get("scope")})
    pot_curve = _curve(qd, CALIBRATION_TARGET, _POT_BANDS, {b: b for b in _POT_BANDS}, "15-70-15",
                       calibration_target_gaps(qd, CALIBRATION_TARGET))
    if grp:
        return _tb_group_overview(db, u, ctx, kw, D, gchain, cells, perf_curve, pot_curve, both)
    # THE FILTER LINE (Chris, 2026-10-30, canvas boards C2 / D2): one chip per filter switched on for this unit, in registry
    # order. Each chip's values are counted within the picks before it; "all" is that count with nothing picked here.
    tb_filters, _earlier = [], []
    if co and D["f_company"]:
        def _chip(f, opts, values, labels, all_n, notset=0):
            # `values` = every key ticked and applied (a person matches ANY of them), `labels` = their words, in step.
            # `value` / `value_label` stay as the FIRST of them (empty with none), for a reader that only asks "is one picked".
            sel = list(values)
            if len(opts) + (1 if notset else 0) < 2 and not sel:
                return   # nothing to choose between: no chip
            tb_filters.append({"key": f["key"], "label": f["label"], "chip": calib_filter_chip(f), "bare": bool(f.get("bare")),
                               "plural": f["plural"], "proper": bool(f["proper"]),
                               "values": sel, "value_labels": list(labels) if sel else [],
                               "value": sel[0] if sel else "", "value_label": labels[0] if sel else "",
                               "all": all_n, "options": opts,
                               "not_set": notset, "search": len(opts) >= CALIB_FILTER_SEARCH_MIN,
                               "earlier": list(_earlier)})
            if sel:
                _earlier.append(labels[0] if len(sel) == 1 else "%d %s" % (len(sel), f["plural"]))
        for _f in CALIB_FILTERS:
            _k = _f["key"]
            if _k == "dept" and df_on:
                _dl = [{"key": d_, "label": d_, "n": n_} for d_, n_ in _tb_dept_counts(ctx, D["f_company"])]
                _dv = list(depts_p) if D["f_depts"] else []
                _chip(_f, _dl, _dv, _dv, sum(o["n"] for o in _dl))
            elif _k == "cal" and cal_on:
                _cl = [{"key": x["key"], "label": x["who"], "n": x["n"], "hint": "Locked" if x["locked"] else "",
                        "title": x.get("title") or "", "ids": sorted(cal_mem.get(x["key"]) or [])}
                       for x in (_tb_bu_level(db, ctx, bg, D["f_company"], cal_mem) or [])
                       if (x.get("n") or 0) > 0 or x["key"] in cals_p]
                _cv = list(cals_p) if D["f_company"] else []
                _chip(_f, _cl, _cv, [next((o["label"] for o in _cl if o["key"] == k_), k_) for k_ in _cv],
                      len({i for v in cal_mem.values() for i in v}))
            elif _k == "jg" and jg_on:
                _jv = list(jgs_p) if D["f_jgs"] else []
                _chip(_f, [dict(o) for o in jgs], _jv, [next((o["label"] for o in jgs if o["key"] == k_), k_) for k_ in _jv],
                      sum(o["n"] for o in jgs))
            elif _k in xf and xf[_k]["on"]:
                _x = xf[_k]
                _xv = list(_x["pick"])
                _chip(_f, _x["opts"], _xv, ["Not set" if k_ == CALIB_NOT_SET else k_ for k_ in _xv], _x["all"], _x["notset"])
    unit_n = sum(1 for p in ctx["population"] if (p["company"] or "") in set(_tb_unit_members(ctx, co))) if co else 0
    _tb_unit_heads = {}   # head count per business unit, in one pass over the population
    for _p in ctx["population"]:
        _tb_unit_heads[_p["company"] or ""] = _tb_unit_heads.get(_p["company"] or "", 0) + 1
    _lim = _tb_limits_payload(D, D["f_company"] or None, _talent_box_bu_label(bg, D["f_company"]) if D["f_company"] else "")
    _limits_kw = {"limits": _lim} if _lim else {}   # the limits on the unit on screen: present only while one is on (2026-11-03)
    out = {"axis": "talent_box", "tier": tier, "scope_label": ctx["scope_label"], "business_group": bg,
            "filters": tb_filters, "show_n": len(D["rows"]), "show_m": unit_n,
            # `locked` = its BU CEO locked both axes (ready for the BG CEO); `tb_locked` = the BG CEO locked it
            # `n` = the unit's head count, the figure the left panel's list gives it (the phone's business-unit list shows it beside the lock)
            "companies": [{"key": c, "label": _talent_box_bu_label(bg, c), "locked": c not in pend, "tb_locked": tbl(c),
                           "pat": pat.get(c), "n": _tb_unit_heads.get(c, 0)} for c in D["all_companies"]],
            "pat": pat.get(D["f_company"] or ""), "perf_curve": perf_curve, "pot_curve": pot_curve,
            "company": D["f_company"],
            "company_label": _talent_box_bu_label(bg, D["f_company"]) if D["f_company"] else "Whole BG",
            "cols": [{"key": g["key"], "label": g["label"], "bands": list(g["bands"]),
                      "n": D["col_counts"].get(g["key"], 0)} for g in TALENT_PERF_GROUPS],
            "rows": [{"key": p, "label": {"High": "High", "Mid": "Medium", "Low": "Low"}.get(p, p),
                      "n": D["row_counts"].get(p, 0)} for p in reversed(TALENT_POTENTIAL_ORDER)],
            "cells": cells, "placed": D["placed"],
            "unplaced": [{"id": r["user"]["id"], "name": r["user"]["full_name"],
                          "dept": _row_get(r["user"], "department"), "missing": r.get("missing") or []}
                         for r in D["unplaced"]],
            "curve": ({"label": D["curve"].get("label")} if isinstance(D["curve"], dict) else None),
            "locked": bool(D["locked"]), "both_locked": bool(both),
            "pm_locked": bool(D["pm_locked"]), "pot_locked": bool(D["pot_locked"]),
            "pending": sorted(_talent_box_bu_label(bg, c) for c in pend),
            # the unit's BU level, where calibration groups share it: its BU CEO's and each group's lock (2026-10-22),
            # each with its people, and the calibrator picked ('' = the whole unit) when the row filters (2026-10-26)
            "bu_level": _tb_bu_level(db, ctx, bg, D["f_company"], cal_mem if cal_on else None),
            "cal_filter": cal_on, "cal": cals_p[0] if (len(cals_p) == 1 and D["f_company"]) else "",
            "cal_all": len({i for v in cal_mem.values() for i in v}) if cal_on else 0,
            # the business unit on screen and its lock (2026-10-07): none on Whole BG
            "lock_company": D["f_company"], "bu_locked": bool(D["f_company"]) and tbl(D["f_company"]),
            # the BG CEO never waits on a BU CEO (Chris, 2026-10-07: "BGCEO will supersede all entries"): any business
            # unit can be locked; `companies[].locked` still says whether its BU CEO has locked both axes
            "bu_ready": bool(D["f_company"]),
            "bu_people": (sum(1 for p in ctx["population"] if (p["company"] or "") == D["f_company"])
                          if (depts_p or jgs_p or cals_p or x_picked) else len(D["rows"])) if D["f_company"] else 0,
            # the department row under the business units: the unit's departments with their headcounts, and the one
            # picked ('' = the whole unit)
            # the one department picked ("" with none or several: the chips carry them all in `filters`)
            "dept": depts_p[0] if (len(depts_p) == 1 and D["f_depts"]) else "",
            "picks": {"dept": list(depts_p) if D["f_depts"] else [], "cal": list(cals_p) if D["f_company"] else [],
                      "jg": list(jgs_p) if D["f_jgs"] else [], **{k_: list(v_["pick"]) for k_, v_ in xf.items()}},
            # none where the super admin hasn't switched the department filter on for this unit (2026-10-17)
            "dept_filter": df_on,
            "depts": ([{"key": d_, "n": n_} for d_, n_ in _tb_dept_counts(ctx, D["f_company"])]
                      if D["f_company"] and df_on else []),
            # the JG row (2026-10-21): its pills within the department picked, and the one picked ('' = every grade)
            "jg_filter": jg_on, "jgs": jgs if D["f_company"] else [],
            "jg": jgs_p[0] if (len(jgs_p) == 1 and D["f_jgs"]) else "",
            "jg_label": next((o["label"] for o in jgs if o["key"] == jgs_p[0]), "") if (len(jgs_p) == 1 and D["f_jgs"]) else "",
            "n_bu": len(D["all_companies"]), "n_bu_locked": sum(1 for c in D["all_companies"] if tbl(c)),
            "cap": D["cap_view"],
            **_limits_kw,
            # each BU's category moves used / allowed (the cap is per company, over the whole BG) and the 15-cell
            # category map the cap counts in, so the box's Move can say whether a move uses one (2026-10-07)
            "cap_on": bool(D["cap_enabled"]),
            "cap_usage": {c: {"used": v["used"], "cap": v["cap"], "left": v["left"]}
                          for c, v in (D.get("cap_usage") or {}).items()},
            "cat15": {"%s|%s" % k: v for k, v in TALENT_BOX_CATEGORIES.items()},
            "band_order": list(PM_BAND_ORDER), "label_names": PM_LABEL_NAMES,
            "pot_order": list(reversed(TALENT_POTENTIAL_ORDER)),
            "move_url": url_for("talent_box_bgceo_move", bg=bg), "lock_url": url_for("talent_box_bgceo_lock", bg=bg),
            "return_to": url_for("review_journey", view="bg", stage="talent_box")}
    # a pushed Round 2 (2026-11-15): the BG CEO's own chat box only (the admin's copy passes a company), and only once Group People
    # pushed it: the output below is the box as it always was for everyone else
    r2 = _tb_round_bg_view(db, u, ctx, D["f_company"]) if (company is None and tier == "bgceo") else None
    return _tb_round_decorate(db, u, out, r2) if r2 else out


def _tb_limits_payload(D, unit, label):
    """What the Talent Box card draws of the limits for the ONE unit on screen (the BU pill picked; a Group Chief's group): None
    with both limits off, so the card then looks exactly as it did. `unit` is the Talent Box unit key (D's cap_usage /
    limit_units are keyed by it); `full` / `msg` name the categories no one may be moved into, with the server's own words."""
    cfg = D.get("limits_cfg") or {}
    if unit is None or not (cfg.get("moves_on") or cfg.get("stars_on")):
        return None
    out = {"unit": label, "curve": None, "moves": None, "star": None, "super": None, "full": {}, "msg": {}}
    if cfg.get("moves_on"):
        u_ = (D.get("cap_usage") or {}).get(unit)
        if u_ and u_.get("cap") is not None:
            out["moves"] = {"used": u_["used"], "cap": u_["cap"], "left": u_["left"], "pct": cfg["moves_pct"],
                            "state": "full" if u_["left"] <= 0 else "ok"}
    e = (D.get("limit_units") or {}).get(unit)
    if e:
        out["unit"], out["curve"] = e["label"], e["curve"]
        for fld in ("star", "super"):
            st = e[fld]
            out[fld] = {"cat": st["cat"], "n": st["n"], "max": st["max"], "pct": st["pct"], "state": st["state"],
                        "over": max(0, st["n"] - st["max"])}
            if st["state"] != "ok":
                out["full"][st["cat"]] = st["state"]
                out["msg"][st["cat"]] = tb_limit_full_msg(e, fld)
    return out


def _tb_limits_bits(lim):
    """The limits on screen as short phrases: used / allowed, FULL or OVER marked."""
    bits = []
    if (lim or {}).get("moves"):
        m = lim["moves"]
        bits.append("category moves used %d of %d (%g%% of the unit's people, never fewer than one person)"
                    % (m["used"], m["cap"], m["pct"]))
    for fld in ("super", "star"):
        st = (lim or {}).get(fld)
        if st:
            bits.append("%ss %d of %d%s" % (st["cat"], st["n"], st["max"],
                                           (" -- FULL" if st["state"] == "full" else " -- OVER by %d" % st["over"])
                                           if st["state"] != "ok" else ""))
    return bits


def _tb_limits_brief(lim):
    """The Talent Box agents' words for the limits on screen (empty with none on): what is full, and how to talk about it."""
    bits = _tb_limits_bits(lim)
    if not bits:
        return ""
    return ("LIMITS Group People set for this unit (%s%s) -- hard limits: %s. "
            "NEVER propose or attempt a move INTO a full category (Star or Super Star at its limit), or a category move "
            "once the moves are used up; a move out, or inside a category, is always free. When a move is refused, say "
            "the refusal's own words in plain language and the way on: move someone out of that category first, or ask "
            "Group People to raise the limit -- you can't change a limit, and nobody can lock a unit that holds more "
            "Stars or Super Stars than its limit until people move out. Never put a person's band or result in the "
            "explanation." % (lim.get("unit") or "this unit", (", " + lim["curve"] + " curve") if lim.get("curve") else "",
                              "; ".join(bits)))


def _tb_group_below(db, ctx, rows):
    """{subject_id: {bgc_perf, bgc_pot, bgc_perf_src, bgc_pot_src, locked?}} on a Group Chief's box: where each person
    stands WITHOUT the Group Chief -- the BG CEO's call when the BG CEO has locked, else what came up through the BU
    CEO, the HOD, the line manager or their own entry (the box's own chain, skipping the group and HR's tiers) -- and
    whether the Group Chief had already locked their call one by one (the classic group page's own lock)."""
    pid, cid = ctx["period"]["id"], ctx["cycle_id"]
    gid = int(ctx["scope_key"])
    held = {r[0] for r in db.execute("SELECT subject_id FROM pm_group_locks WHERE cycle_id=? AND group_id=?", (pid, gid))}
    held |= {r[0] for r in db.execute("SELECT subject_id FROM pot_group_locks WHERE cycle_id=? AND group_id=?",
                                      (pid, gid))}
    out = {}
    for r in rows:
        p = r["user"]
        pf = pm_effective_band(db, p, pid, None, skip_tiers=("super", "group"))
        perf, psrc = talent_chain_pick([(pf["source"], pf["band"] if pf["source"] != "raw" else None),
                                        ("lm", r.get("perf_lm")), ("self", r.get("perf_self"))], "UA")
        qf = effective_band(db, p, cid, skip_tiers=("super", "group"))
        pot, qsrc = talent_chain_pick([(qf["source"], qf["band"] if qf["source"] != "raw" else None),
                                       ("lm", r.get("pot_lm")), ("self", r.get("pot_self"))], "Low")
        x = {"bgc_perf": perf, "bgc_pot": pot, "bgc_perf_src": psrc, "bgc_pot_src": qsrc}
        if p["id"] in held:
            x["locked"] = True   # locked one by one on the classic page: their call is with the super admin
        out[p["id"]] = x
    return out


def _tb_group_overview(db, u, ctx, kw, D, gchain, cells, perf_curve, pot_curve, both):
    """The Group Chief's Talent Box (Chris, 2026-10-13): the BG CEO's box, drawn the same way, for their calibration
    group as ONE unit -- no business units to pick, the filter line under the title (Segment, then what the super admin
    switched on for the group, 2026-11-02: it replaced the batch pills), the BG CEO's side beside each person, and one Lock for
    the whole group (both axes; the calls go to the super admin's Final bands). The same keys the BG CEO's box has, so the
    card draws one way."""
    gid = int(ctx["scope_key"])
    m = calib_group_mode(gid)
    n = len(ctx["population"])
    _glim = _tb_limits_payload(D, "", ctx["scope_label"])
    return {"axis": "talent_box", "tier": "group", "group": True, "group_id": gid,
            "filters": gchain["chips"], "picks": gchain["picks"], "show_n": len(D["rows"]), "show_m": n,
            "pick_words": gchain["words"],
            "scope_label": ctx["scope_label"], "business_group": "", "mode_word": calib_group_mode_word(m),
            "companies": [{"key": "", "label": ctx["scope_label"], "locked": True, "tb_locked": bool(both), "pat": None}],
            "pat": None, "perf_curve": perf_curve, "pot_curve": pot_curve,
            "company": "", "company_label": ctx["scope_label"],
            "cols": [{"key": g["key"], "label": g["label"], "bands": list(g["bands"]),
                      "n": D["col_counts"].get(g["key"], 0)} for g in TALENT_PERF_GROUPS],
            "rows": [{"key": p, "label": {"High": "High", "Mid": "Medium", "Low": "Low"}.get(p, p),
                      "n": D["row_counts"].get(p, 0)} for p in reversed(TALENT_POTENTIAL_ORDER)],
            "cells": cells, "placed": D["placed"], "unplaced": [],
            "curve": None, "locked": bool(D["locked"]), "both_locked": bool(both),
            "pm_locked": bool(D["pm_locked"]), "pot_locked": bool(D["pot_locked"]), "pending": [],
            "lock_company": "", "bu_locked": bool(both), "bu_ready": True, "bu_people": n,
            "dept": "", "depts": [],   # the batch pills are the Segment chip now (2026-11-02)
            "n_bu": 1, "n_bu_locked": 1 if both else 0, "cap": None, "cap_on": False, "cap_usage": {},
            **({"limits": _glim} if _glim else {}),   # the group is one unit; the key only while a limit is on (2026-11-03)
            "cat15": {"%s|%s" % k: v for k, v in TALENT_BOX_CATEGORIES.items()},
            "band_order": list(PM_BAND_ORDER), "label_names": PM_LABEL_NAMES,
            "pot_order": list(reversed(TALENT_POTENTIAL_ORDER)),
            "move_url": url_for("talent_box_group_move", group_id=gid),
            "lock_url": url_for("talent_box_group_lock", group_id=gid),
            "return_to": url_for("review_journey", view="group", stage="group_calib")}


def _talent_box_pat(db, ctx):
    """{company: PAT achievement %} for the business group this period -- what HR records on Admin -> Performance ->
    PAT Ref (pm_pbt_achievement); an old business-group row (company '') is never read (2026-10-27). Shown beside
    each BU on the Talent Box (Chris, 2026-10-05: "For each displayed BU, it should show the BU PAT achievement %")."""
    return {r["company"]: r["achievement_pct"] for r in db.execute(
        "SELECT company, achievement_pct FROM pm_pbt_achievement WHERE cycle_id=? AND business_group=? "
        "AND COALESCE(company,'')!=''",
        (ctx["period"]["id"], ctx["business_group"]))}


def _pat_text(pct):
    if pct is None:
        return "PAT not entered"
    import math   # half up, as the page's tbPat rounds it (Python's round() takes 104.5 to 104)
    if abs(pct) >= 10 or float(pct).is_integer():
        v = int(math.floor(pct + 0.5))
    else:
        v = math.floor(pct * 10 + 0.5) / 10.0
        v = int(v) if float(v).is_integer() else v   # 9.95 -> "10", as the page shows it
    return "PAT %s%%" % v


def _talent_box_nav_items(db, u):
    """The Talent Box's navigator: its business units -- the BU selection (Chris, 2026-09-30) -- with each one's lock
    state; no Whole BG (2026-10-07). Picking one refreshes the card (the client), no chat turn."""
    sc = _journey_talent_box_scope(db, u)
    if not sc:
        return {"kind": "tbox", "items": [], "focus": None}
    ctx = sc[2]
    if sc[0] == "group":   # the Group Chief's group, as its one unit (2026-10-13)
        both = bool(ctx["pm_session"] and ctx["pm_session"]["locked_at"]) and \
            bool(ctx["pot_session"] and ctx["pot_session"]["locked_at"])
        n = len(ctx["population"])
        return {"kind": "tbox", "focus": "",
                "items": [{"id": "", "name": ctx["scope_label"], "done": both, "tag": "",
                           "meta": "%d %s%s" % (n, "person" if n == 1 else "people", " \u00b7 locked" if both else "")}],
                "prog_text": "Locked" if both else "Not locked yet", "prog_frac": 1.0 if both else 0.0,
                "done_text": "Locked \u2014 the super admin decides each final band."}
    bg = ctx["business_group"]
    cos = sorted({(p["company"] or "") for p in ctx["population"] if p["company"]})
    pat = _talent_box_pat(db, ctx)
    # done = the BG CEO has locked it (2026-10-07: one business unit at a time). The business group locked on BOTH axes
    # locks every one.
    whole = bool(ctx["pm_session"] and ctx["pm_session"]["locked_at"]) and \
        bool(ctx["pot_session"] and ctx["pot_session"]["locked_at"])
    bul = set(_tb_bu_locks(db, ctx["period"]["id"], bg))
    # a unit Group People pushed back to them (Round 2): its row says the PAT change, as its pill does (2026-11-15)
    rmap = {m: v for v in _tb_round_pushed(db, ctx["period"]["id"], bg) for m in v["members"]} if is_bgceo_of(u, bg) else {}
    items = []   # business units only -- no Whole BG (Chris, 2026-10-07: "it should go by BU by BU")
    # Two groups (Chris, 2026-10-07: "on left panel, once locked, move them to a locked list. The rest should be under
    # pending calibration"): the group says the state, so the meta is the headcount and PAT only. No "ready" or
    # "waiting": the BG CEO can lock any business unit (Chris, 2026-10-07: "BGCEO will supersede all entries").
    for c in cos:
        n = sum(1 for p in ctx["population"] if (p["company"] or "") == c)
        done = whole or c in bul
        items.append({"id": c, "name": _talent_box_bu_label(bg, c), "done": done, "tag": "",
                      "meta": "%d %s \u00b7 %s" % (n, "person" if n == 1 else "people",
                                                    ("PAT\u00a0%s\u00a0\u2192\u00a0%s" % (rmap[c]["forecast_text"], rmap[c]["actual_text"])) if c in rmap   # (kept whole when the row wraps)
                                                    else _pat_text(pat.get(c)))})
    return {"kind": "tbox", "items": items, "focus": _journey_talent_box_company() or ""}


def _talent_box_opener(db, u):
    """The Talent Box's fixed first line -- no model."""
    sc = _journey_talent_box_scope(db, u)
    if not sc:
        return "There's no Talent Box here for you."
    ctx = sc[2]
    ov = _journey_talent_box_overview(db, u, sc) or {}
    dflt = sum(1 for c in ov.get("cells") or [] for p in c["people"]
               if p.get("perf_src") == "default" or p.get("pot_src") == "default")
    if sc[0] == "group":   # the Group Chief's (2026-10-13)
        if ov.get("both_locked"):
            return ("Here's your Talent Box for %s \u2014 it's locked: the super admin decides each final band now."
                    % ctx["scope_label"])
        return ("Here's your Talent Box for %s: %d people placed%s. Each person's bands are what came up to you \u2014 "
                "the BG CEO's call, else the BU CEO's, the HOD's, the line manager's or their own; your call and the "
                "BG CEO's: %s. Open anyone to move them or ask me about them, then lock the Talent Box when it's "
                "right: your calls go to the super admin, who decides each final band."
                % (ctx["scope_label"], ov.get("placed") or 0,
                   (", %d of them on a default band with no record yet" % dflt) if dflt else "",
                   (ov.get("mode_word") or "").lower()))
    return ("Here's your Talent Box for %s, one business unit at a time \u2014 starting with %s: %d people placed%s. "
            "Switch business unit at the top of the box, in the left panel, or just ask me; open anyone to move them "
            "or ask me about them, then lock the business unit when it's right (%d of %d locked)."
            % (ctx["scope_label"], ov.get("company_label") or "the first business unit", ov.get("placed") or 0,
               (", %d of them on a default band with no record yet" % dflt) if dflt else "",
               ov.get("n_bu_locked") or 0, ov.get("n_bu") or 0)) + _tb_round_say(ov)


def _talent_box_system(db, u):
    """The BG CEO's Talent Box assistant (the calibration assistant's shape): the box as it stands for the picked BU,
    the rules, and the tools. The model proposes; _talent_box_apply validates and writes; only their Lock click locks."""
    sc = _journey_talent_box_scope(db, u)
    if not sc:
        return "There is no Talent Box scope here."
    ov = _journey_talent_box_overview(db, u, sc) or {}
    boxes = [{"box": "%s performance / %s potential" % (c["col"], c["pot"]), "category": c["label"], "n": c["n"],
              "reference_pct": c["ref"], "target_n": c["target"]} for c in ov.get("cells") or []]
    people = [{"name": p["name"], "business_unit": p.get("company"),
               "box": "%s performance / %s potential" % (c["col"], c["pot"]), "performance_band": p["perf"],
               "performance_from": TALENT_SOURCE_LABEL.get(p.get("perf_src"), p.get("perf_src")),
               "potential_band": p["pot"], "potential_from": TALENT_SOURCE_LABEL.get(p.get("pot_src"), p.get("pot_src")),
               "moved_here": p["moved"]}
              for c in ov.get("cells") or [] for p in c["people"]][:150]
    n_dflt = sum(1 for c in ov.get("cells") or [] for p in c["people"]
                 if p.get("perf_src") == "default" or p.get("pot_src") == "default")
    if sc[0] == "group":
        return _tb_group_system(ov, boxes, people, n_dflt)
    parts = [
        "STAGE -- TALENT BOX CALIBRATION: help them, the BG CEO of %s, calibrate the Talent Box -- the 9-box of "
        "PERFORMANCE (columns: Low = UA or BE, Mid = ME, High = AE or OU) by POTENTIAL (rows: Low, Mid, High). Each "
        "person's band on each axis is the first record found, highest first: their move here, the BU CEO's locked "
        "calibration, the HOD's locked review, the line manager's (the approved rating; the 360 with the competency "
        "they approved), the person's own fill-in -- and with none, UA by default for performance and Low for "
        "potential, so EVERYONE is placed. This is the last call before each business unit is locked (one at a time, "
        "below)." % ov.get("scope_label", "their business group"),
        "ON SCREEN: %s. THE BOXES NOW (count vs the reference share and target):\n%s"
        % (ov.get("company_label") or "the whole business group", json.dumps(boxes, ensure_ascii=False)),
        "THE PEOPLE (by box):\n" + json.dumps(people, ensure_ascii=False),
        ("ON A DEFAULT BAND (no record yet on one axis or both): %d -- say so plainly if asked, never present a "
         "default as someone's rating." % n_dflt),
        "BUSINESS UNITS (the box shows ONE at a time -- there is no Whole BG view): " + "; ".join(
            "%s -- %s" % (c["label"], "locked by you" if c.get("tb_locked") else "not locked yet"
                          + ("" if c.get("locked") else " (its BU CEO hasn't locked yet, so its bands come from the HOD, "
                             "line manager or their own)")) for c in ov.get("companies") or []) + ".",
        "THE LOCK is per business unit (Chris, 2026-10-07): on a business unit, its Lock under the box locks both "
        "axes for its people and they can't be moved after. The BG CEO NEVER waits for a BU CEO: their decision "
        "supersedes every entry below, so any business unit can be locked at any time -- never say a unit must wait "
        "for its BU CEO. The lock is FINAL: it closes that unit's BU CEO calibration and HOD department reviews, and "
        "a result that comes in later doesn't change a locked band. Each band on the box is the first record found: "
        "the BU CEO's, the HOD's, the line manager's, "
        "their own, else the default. When every business unit is locked, the whole business group is locked; that is the "
        "end of the BG CEO's part (PIP and promotion are decided on another platform, not in OneHR). %d of %d business "
        "units locked." % (ov.get("n_bu_locked") or 0, ov.get("n_bu") or 0),
        'TOOLS for "action": show_box{} (brings the box into view); show_business_unit{name} (switches the box to a '
        "business unit by its name above); open_person{subject} (opens their page on the box -- the "
        "AI summary of their performance, potential and plan, and what everyone wrote -- and tells you their box, "
        "both bands, where each came from and the start of any summary already read); explain_person{subject} "
        "(their two bands, where they came from, their category); move_person{subject, performance_band, "
        "potential_band, justification} (performance_band one of UA / BE / ME / AE / OU, potential_band one of Low / "
        "Mid / High -- give only the axis that changes; ALWAYS include their OWN reason, and if they have not given "
        "one, ASK -- never make one up); prepare_lock{} (brings the box with the Lock of the business unit on "
        "screen); past_talent{subject} (their talent status in the three Year-Ends before this one, only when they "
        "ask); person_profile{subject} (their role, job grade, department, company, employment type, joined and "
        "confirmation dates, years of service and line manager); search_kb{query}.",
        _PAST_TALENT_BRIEF,
        _PROFILE_TOOL_BRIEF,
        _MOVE_ASK_RULE,
        "MOVING SOMEONE: when they name a person, the new band on ONE axis and their reason, call move_person at once "
        "with exactly that axis -- never ask about the other axis, never turn it into a question. Ask only for what "
        "is missing (who, which band, or their own reason).",
        "LOCKING: when they ask to lock, call prepare_lock{} and tell them the Lock button is under the box; it locks "
        "the business unit on screen only (to lock another, switch to it with show_business_unit first). NEVER "
        "claim you have locked anything; only their Lock click locks, and it is final.",
        "SWITCHING BUSINESS UNIT: when they ask to see, go to or switch to a business unit, call "
        "show_business_unit{name}; the box follows when your reply arrives, and your next prompt shows its boxes. "
        "There is no Whole BG view to switch to: the box goes business unit by business unit.",
        "ABOUT A PERSON: when they ask about someone -- a summary, how they're doing, 'tell me about', 'open' -- call "
        "open_person{subject}. Answer in two or three sentences from what it returns (their box, both bands and where "
        "each came from, and any summary already read) and point them to the page for the rest. Never invent what a "
        "summary says; if none has been read yet, say it's on their page.",
        "360 ANONYMITY (never break it): never say who rated anyone, how many, or which relationship thought what.",
    ]
    _lb = _tb_limits_brief(ov.get("limits"))   # Group People's limits on the unit on screen, when on (2026-11-03)
    if _lb:
        parts.append(_lb)
    _rb = _tb_round_brief(ov)   # a pushed Round 2: the new PAT, the two steps, Suggest with AI (2026-11-15)
    if _rb:
        parts.append(_rb)
    if ov.get("locked"):
        parts.append("NOTE: this Talent Box is LOCKED. Do not move anyone -- explain warmly and answer questions.")
    elif ov.get("bu_locked"):
        parts.append("NOTE: %s is LOCKED -- do not move anyone in it; other business units are still open."
                     % ov.get("company_label"))
    _ln = _late_agent_note(db, u, "talent_box")   # more time Group People gave them (2026-10-31)
    if _ln:
        parts.append(_ln)
    return "\n\n".join(parts)


def _tb_group_system(ov, boxes, people, n_dflt):
    """The Group Chief's Talent Box assistant: the BG CEO's brief, for one calibration group (2026-10-13)."""
    bgc = [{"name": p["name"], "bg_ceo_side": "%s / %s" % (p.get("bgc_perf") or "-", p.get("bgc_pot") or "-")}
           for c in ov.get("cells") or [] for p in c["people"]
           if (p.get("bgc_perf"), p.get("bgc_pot")) != (p.get("perf"), p.get("pot"))][:150]
    parts = [
        "STAGE -- TALENT BOX CALIBRATION FOR A GROUP CHIEF: they are the Group Chief of %s, %d people across business "
        "groups calibrated together as ONE unit. The 9-box is PERFORMANCE (columns: Low = UA or BE, Mid = ME, High = AE "
        "or OU) by POTENTIAL (rows: Low, Mid, High). Each person's band on each axis is their own move here, else what "
        "came up to them: the BG CEO's call, the BU CEO's, the HOD's, the line manager's, their own -- else UA / Low by "
        "default, so EVERYONE is placed. Their call and the BG CEO's: %s. The super admin decides each final band on "
        "Final bands." % (ov.get("scope_label"), ov.get("placed") or 0, ov.get("mode_word") or ""),
        "THE BOXES NOW:\n" + json.dumps(boxes, ensure_ascii=False),
        "THE PEOPLE (by box):\n" + json.dumps(people, ensure_ascii=False),
        "WHERE THEIR BOX DIFFERS FROM THE BG CEO'S SIDE (performance / potential):\n" + json.dumps(bgc, ensure_ascii=False),
        ("ON A DEFAULT BAND (no record yet on one axis or both): %d -- say so plainly if asked, never present a "
         "default as someone's rating." % n_dflt),
        "THE LOCK covers the whole group at once, both axes: their calls on everyone go to the super admin, nobody can "
        "be moved after, and it is final for them. There are no business units to switch between; the Filter line under "
        "the title narrows what's on screen: Segment first (the batches the super admin named, such as People or "
        "Technology, else a department), then the filters Group People switched on for their group (business group, "
        "department, job grade, cost centre, branch). It only narrows the view, and the lock still covers the whole group.",
        'TOOLS for "action": show_box{}; open_person{subject}; explain_person{subject}; move_person{subject, '
        "performance_band, potential_band, justification} (performance_band one of UA / BE / ME / AE / OU, "
        "potential_band one of Low / Mid / High -- only the axis that changes; ALWAYS their OWN reason, ASK if they "
        "haven't given one, never make one up); prepare_lock{} (brings the box with its Lock); search_kb{query}.",
        _MOVE_ASK_RULE,
        "MOVING SOMEONE: when they name a person, the new band on ONE axis and their reason, call move_person at once.",
        "LOCKING: when they ask to lock, call prepare_lock{} and say the Lock is under the box. NEVER claim you locked "
        "anything; only their click locks, and it is final.",
        "ABOUT A PERSON: call open_person{subject} and answer in two or three sentences from what it returns.",
        "360 ANONYMITY (never break it): never say who rated anyone, how many, or which relationship thought what.",
    ]
    _lb = _tb_limits_brief(ov.get("limits"))   # Group People's limits on the group, when on (2026-11-03)
    if _lb:
        parts.append(_lb)
    if ov.get("both_locked"):
        parts.append("NOTE: this Talent Box is LOCKED. Do not move anyone -- explain warmly and answer questions.")
    _ln = _late_agent_note(get_db(), current_user(), "group_calib") if has_request_context() else ""   # a Group Chief's more time (2026-11-07)
    if _ln:
        parts.append(_ln)
    return "\n\n".join(parts)


def _tb_run_tool(db, u, action):
    """The Talent Box's validated tools. move_person writes through _talent_box_apply (the page's own rules)."""
    tool = (action or {}).get("tool")
    args = (action or {}).get("args") or {}
    if not isinstance(args, dict):
        args = {}
    if tool == "search_kb":
        return _journey_tool_search_kb(db, args)
    sc = _journey_talent_box_scope(db, u, fresh=True)
    if not sc:
        return {"ok": False, "error": _tb_hidden_msg(db, u) or "no Talent Box scope"}   # not open yet: the sentence
    tier, kw, ctx = sc
    if tool == "past_talent":   # BG CEO only, only when asked (2026-10-22)
        return _past_talent_tool(db, tier, ctx, args)
    if tool == "person_profile":   # the BG CEO only, when asked (2026-10-22)
        return _person_profile_tool(db, tier, ctx, args)
    focus = {"type": "stage_focus", "data": {"stage": "group_calib" if tier == "group" else "talent_box"}}
    if tool == "show_business_unit":   # the box follows at the end of the turn (2026-10-07)
        if tier == "group":   # a Group Chief's group is one unit (2026-10-13)
            return {"ok": False, "error": "this Talent Box is one group, %s -- there are no business units to switch "
                                          "between" % ctx["scope_label"]}
        return _tb_tool_show_bu(db, u, sc, str(args.get("name") or args.get("business_unit") or "").strip())
    if tool == "open_person":
        return _tb_tool_open_person(db, u, sc, args.get("subject"))
    if tool in ("show_box", "prepare_lock"):
        ov = _journey_talent_box_overview(db, u, sc) or {}
        if tool == "prepare_lock":   # per business unit (2026-10-07): none on Whole BG
            if ov.get("locked"):
                return {"ok": False, "error": "This Talent Box is already locked."}
            if tier == "group":   # the Group Chief's lock is the whole group's (2026-10-13)
                return {"ok": True, "render": focus,
                        "note": "the box is on screen with its Lock for the whole group -- only their click locks it"}
            if not ov.get("lock_company"):
                return {"ok": False, "error": "On Whole BG there's nothing to lock: each business unit locks on its "
                                              "own -- which one?"}
            if ov.get("bu_locked"):
                return {"ok": False, "error": "%s is already locked." % ov.get("company_label")}
        _lm = ov.get("limits") or {}
        _over = [_lm[f_]["cat"] for f_ in ("star", "super") if (_lm.get(f_) or {}).get("state") == "over"]
        return {"ok": True, "render": focus,
                "note": ("the box is on screen with the Lock for %s -- only their click locks it" % ov.get("company_label"))
                if tool == "prepare_lock" else "the box is on screen",
                # Group People's limits on the unit on screen, so the reply can name what is full / over (2026-11-03)
                **({"limits_now": "; ".join(_tb_limits_bits(_lm))} if _tb_limits_bits(_lm) else {}),
                **({"lock_will_refuse": "%s holds more %ss than its limit allows, so its Lock refuses until people move out"
                    % (_lm.get("unit"), " and ".join(_over))} if (tool == "prepare_lock" and _over) else {})}
    if tool == "explain_person":
        subj, err = _calib_resolve_subject(ctx, args.get("subject"))
        if err:
            return {"ok": False, "error": err}
        row = next((r for r in talent_box_rows(db, ctx) if r["user"]["id"] == subj["id"]), None) or {}
        return {"ok": True, "name": subj["full_name"], "performance_band": row.get("perf_band"),
                "potential_band": row.get("pot_band"), "performance_came_in_as": row.get("perf_from"),
                "potential_came_in_as": row.get("pot_from"), "category": row.get("category"),
                "performance_from": TALENT_SOURCE_LABEL.get(row.get("perf_source"), row.get("perf_source")),
                "potential_from": TALENT_SOURCE_LABEL.get(row.get("pot_source"), row.get("pot_source"))}
    if tool == "move_person":
        subj, err = _calib_resolve_subject(ctx, args.get("subject"))
        if err:
            return {"ok": False, "error": err}
        perf = str(args.get("performance_band") or "").strip().upper()
        pot = str(args.get("potential_band") or "").strip().capitalize()
        ok, msg = _talent_box_apply(db, u, tier, ctx, subj["id"], perf, pot,
                                    str(args.get("justification") or "").strip())   # the writer refuses one over its ceiling
        return {"ok": ok, "moved": subj["full_name"], "message": msg} if ok else {"ok": False, "error": msg}
    return {"ok": False, "error": "unknown tool"}


# The Talent Box's tools, by name (one dispatcher, _tb_run_tool) -- registered so the own-words guard's table
# (_PERSON_TEXT_TOOLS: move_person's justification) is checked against a real tool.
_TB_TOOLS = {"show_box": _tb_run_tool, "explain_person": _tb_run_tool, "move_person": _tb_run_tool,
             "prepare_lock": _tb_run_tool, "search_kb": _tb_run_tool, "show_business_unit": _tb_run_tool,
             "open_person": _tb_run_tool, "past_talent": _tb_run_tool,
             "person_profile": _tb_run_tool}


def _tb_match_bu(ov, name, strict=False):
    """(company key, label) for a business-unit name the BG CEO said -- its label or company name, exact first, then
    the only one that starts with / contains it; None when it isn't one (there is no Whole BG view, 2026-10-07).
    strict (the no-model fast path, "Show ARI"): exact, or the only short label it starts -- never a word that merely
    appears inside a company's legal name ("show me glass" goes to the model, which can ask)."""
    q = re.sub(r"\s+", " ", (name or "").strip().lower()).strip(" .!?")
    q = re.sub(r"^(?:the )", "", q)
    if not q:
        return None
    cos = [(c["key"], c["label"]) for c in ov.get("companies") or []]
    for k, lab in cos:
        if q in (k.lower(), lab.lower()):
            return (k, lab)
    tests = ((lambda k, lab: lab.lower().startswith(q)),) if strict else (
        lambda k, lab: lab.lower().startswith(q) or k.lower().startswith(q),
        lambda k, lab: q in lab.lower() or q in k.lower())
    for test in tests:
        hits = [(k, lab) for k, lab in cos if test(k, lab)]
        if len(hits) == 1:
            return hits[0]
        if hits:
            return None
    return None


def _tb_turn_render(render):
    """Queue a box render for the end of this turn (a BU switch, a person's page): the tool's result goes back to the
    model, so its reply can describe what it switched to or found, and the box follows when the reply arrives."""
    q = _req_cache().setdefault("_tb_renders", [])
    q[:] = sorted([r for r in q if r.get("type") != render.get("type")] + [render],
                  key=lambda r: 0 if r.get("type") == "tbox_bu" else 1)   # the business unit first, then a page


def _tb_tool_show_bu(db, u, sc, name):
    """Switch the box to a business unit (Chris, 2026-10-07: "BGCEO can prompt the agent to move between BU"): the rest
    of this turn reads it (_journey_talent_box_company), the client follows with the reply. No Whole BG view."""
    ov = _journey_talent_box_overview(db, u, sc) or {}
    hit = _tb_match_bu(ov, name)
    if not hit:
        return {"ok": False, "error": "no business unit called %r -- the box goes business unit by business unit, one "
                "of: %s" % (name, ", ".join(c["label"] for c in ov.get("companies") or []))}
    _req_cache()["_tb_company"] = hit[0]
    q = _req_cache().setdefault("_tb_renders", [])
    q[:] = [r for r in q if r.get("type") != "tbox_person"]   # a switch after open_person: the box, not that page
    _tb_turn_render({"type": "tbox_bu", "company": hit[0]})
    ov2 = _journey_talent_box_overview(db, u, sc) or {}
    out = {"ok": True, "now_showing": hit[1], "placed": ov2.get("placed")}
    if hit[0]:
        out["state"] = "locked by you" if ov2.get("bu_locked") else "not locked yet"
    return out


def _tb_tool_open_person(db, u, sc, subject):
    """Open someone's page on the box and say where they sit (Chris, 2026-10-07: "ask about a person summary"): their
    box, both bands and where each came from, and the start of any AI summary ALREADY read for this seat -- read from
    the cache only (generate=False), never a model call inside the turn. Their page shows the rest."""
    tier, kw, ctx = sc
    subj, err = _calib_resolve_subject(ctx, subject)
    if err:
        return {"ok": False, "error": err}
    if subj["id"] == u["id"]:
        return {"ok": False, "error": "that's you -- your own band is set above you, not on your box"}
    row = next((r for r in talent_box_rows(db, ctx) if r["user"]["id"] == subj["id"]), None) or {}
    bg = ctx["business_group"]
    co = _row_get(subj, "company") or ""
    cur = _journey_talent_box_company()
    if cur and co and cur != co:   # the box is on another business unit: go to theirs (none: open where it is)
        _req_cache()["_tb_company"] = co
        _tb_turn_render({"type": "tbox_bu", "company": co})
    person = {"id": subj["id"], "name": subj["full_name"], "dept": _row_get(subj, "department"),
              "grade": _row_get(subj, "job_grade"), "company": co, "bu": _talent_box_bu_label(bg, co) if co else "",
              "perf": row.get("perf_band"), "pot": row.get("pot_band"), "category": row.get("category"),
              "perf_src": row.get("perf_source"), "pot_src": row.get("pot_source"), "moved": False,
              "newly": subj["id"] in newly_confirmed_ids(db, ctx["period"]["id"]),
              "behalf_lm": subj["id"] in lm_behalf_ids(db, ctx["period"]["id"]),
              **_nd_kw(nodata_map(db, ctx["period"]["id"], [subj["id"]]), subj["id"]),
              **_tr_kw(pm_split_tags(db, ctx["period"]["id"], [subj["id"]], {subj["id"]: row.get("overall")}), subj["id"])}
    _tb_turn_render({"type": "tbox_person", "person": person})

    def _start(txt, n=170):
        t = re.sub(r"\s+", " ", (txt or "")).strip()
        return (t[:n].rsplit(" ", 1)[0] + "...") if len(t) > n else t
    perf_s = pot_s = ""
    try:
        r1 = _pm_perf_summary_for(db, u, subj["id"], generate=False,
                                  calib={"tier": tier, "scope_key": ctx["scope_key"],
                                         "reviewer": _CALIB_REVIEWER.get(tier, "CALIBRATOR")}) or {}
        perf_s = _start(r1.get("summary") if isinstance(r1.get("summary"), str) else "")
    except Exception as e:
        app.logger.info("talent box person summary (performance) not read: %s", e)
    try:
        r2 = _pot_summary_for(db, u, subj["id"], ctx["cycle_id"], _POT_REVIEWER.get(tier, "CALIBRATOR"),
                              generate=False) or {}
        pot_s = _start(r2.get("summary") if isinstance(r2.get("summary"), str) else "")
    except Exception as e:
        app.logger.info("talent box person summary (potential) not read: %s", e)
    src = lambda k: TALENT_SOURCE_LABEL.get(row.get(k), row.get(k))
    _tn = _split_agent_note(db, ctx["period"]["id"], subj["id"])   # Transferred (2026-11-03)
    return {"ok": True, "opened": subj["full_name"], "business_unit": person["bu"], "box": row.get("category"),
            **({"transferred": _tn} if _tn else {}),
            "performance": "%s (%s)" % (row.get("perf_band"), src("perf_source")),
            "potential": "%s (%s)" % (row.get("pot_band"), src("pot_source")),
            "performance_summary": perf_s or "not read yet -- it's on their page",
            "potential_summary": pot_s or "not read yet -- it's on their page"}


def _demo_login_shown_as_employee(u):
    """True when `u` is a demo-switcher's own login with NO persona picked and the "Viewing as" dropdown
    therefore reads its first option, Employee. Never true for a real login (no personas)."""
    if not has_request_context() or session.get("demo_as"):
        return False
    actor = demo_actor()
    if not actor or actor["id"] != u["id"]:
        return False
    ps = demo_personas(actor)
    return bool(ps) and ps[0]["demo_persona"] == "employee"


# --- Demo reset helpers (ZZ accounts only, self-scoped, no commit/redirect). Each
#     clears one stage; review_demo_reset_all runs them all under one commit. ------
def _demo_reset_checkin(db, u, cid):
    db.execute("DELETE FROM pm_review_chat WHERE subject_id=?", (u["id"],))
    db.execute("DELETE FROM pm_kpi_results WHERE kpi_target_id IN "
               "(SELECT id FROM pm_kpi_targets WHERE subject_id=? AND cycle_id=?)",
               (u["id"], cid))
    # Also clear any RESULT-moderation approvals on these lines. Without this a
    # stale approval (left from testing the manager/moderation flow) survives the
    # reset, and pm_effective_value() then keeps scoring the OLD approved number --
    # so a freshly re-typed result shows the right value but the wrong rating (Chris
    # saw Gross Profit 17 rated as rung 3). ZZ demo accounts only, so synthetic data;
    # a real employee can't re-key a moderated line (pm_can_self_edit is False once
    # submitted), which is why this only bites the demo's ZZ editability bypass.
    db.execute("DELETE FROM pm_kpi_approvals WHERE kpi_target_id IN "
               "(SELECT id FROM pm_kpi_targets WHERE subject_id=? AND cycle_id=?)",
               (u["id"], cid))
    db.execute("DELETE FROM pm_review_session WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    # Also wipe the check-in's OWN narrative content, or it survives the reset and shows on
    # the next confirm card even after the person skips it: the overall remark, and the
    # review-logged examples (recognition evidence -- its links + attachments cascade). ZZ
    # demo accounts only (this whole reset is ZZ-gated), so synthetic data; the durable
    # evidence-ledger guarantees are for real employees and untouched.
    db.execute("DELETE FROM pm_overall_remarks WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    db.execute("DELETE FROM pm_evidence WHERE author_id=? AND kind='recognition'", (u["id"],))


def _demo_reset_setting(db, u, cid):
    tids = [r["id"] for r in db.execute(
        "SELECT id FROM pm_kpi_targets WHERE subject_id=? AND cycle_id=?",
        (u["id"], cid)).fetchall()]
    db.execute("DELETE FROM pm_setting_chat WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    if tids:
        ph = ",".join("?" * len(tids))
        db.execute("DELETE FROM pm_kpi_results WHERE kpi_target_id IN (%s)" % ph, tids)
        db.execute("DELETE FROM pm_kpi_target_approvers WHERE kpi_target_id IN (%s)" % ph, tids)
        db.execute("DELETE FROM pm_kpi_setting_approvals WHERE kpi_target_id IN (%s)" % ph, tids)
        db.execute("UPDATE pm_kpi_targets SET status='draft' WHERE id IN (%s)" % ph, tids)
    db.execute("DELETE FROM pm_review_session WHERE subject_id=? AND cycle_id=?", (u["id"], cid))


def _demo_reset_competency(db, u, cid):
    db.execute("DELETE FROM tc_review_chat WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    row = db.execute("SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                     (cid, u["id"])).fetchone()
    if row:
        db.execute("DELETE FROM tc_scores WHERE assignment_id IN "
                   "(SELECT id FROM tc_assignments WHERE subject_id=? AND cycle_id=?)",
                   (u["id"], cid))
        db.execute("DELETE FROM tc_section_remarks WHERE assessment_id=?", (row["id"],))
        db.execute("UPDATE tc_assessments SET status='pending', submitted_at=NULL, "
                   "reviewed_at=NULL, reviewed_by=NULL, overall_remark=NULL, "
                   "manager_overall_remark=NULL WHERE id=?", (row["id"],))


def _demo_reset_ahead(db, u, cid):
    db.execute("DELETE FROM pm_idp_chat WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    period, _periods, _active = _pm_idp_period(db, u)
    if period:
        idp = pm_idp_for(db, pm_idp_plan_year(period), u["id"], create=False)
        if idp:
            db.execute("DELETE FROM pm_idp_goals WHERE idp_id IN "
                       "(SELECT id FROM pm_idp WHERE id=? AND subject_id=?)",
                       (idp["id"], u["id"]))
            db.execute("UPDATE pm_idp SET status='draft', shared_at=NULL, "
                       "manager_comment=NULL, closed_at=NULL, closed_by=NULL, "
                       "updated_at=datetime('now') WHERE id=? AND subject_id=?",
                       (idp["id"], u["id"]))


def _demo_reset_career(db, u, cid):
    db.execute("DELETE FROM pm_career_chat WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    if pm_career_profile_for(db, u["id"], create=False):
        db.execute("UPDATE pm_career_profile SET %s, updated_at=datetime('now') "
                   "WHERE subject_id=?" % ", ".join("%s=NULL" % f for f in PM_CAREER_FIELDS),
                   (u["id"],))


def _demo_reset_feedback(db, u, cid):
    aids = [r["id"] for r in db.execute(
        "SELECT id FROM assignments WHERE assessor_id=? AND cycle_id=? AND archived=0",
        (u["id"], cid)).fetchall()]
    for aid in aids:
        db.execute("UPDATE responses SET answer=NULL WHERE assignment_id=?", (aid,))
        db.execute("DELETE FROM criterion_comments WHERE assignment_id=?", (aid,))
        db.execute("DELETE FROM feedback_remarks WHERE assignment_id=?", (aid,))
        db.execute("UPDATE assignments SET status='pending', submitted_at=NULL WHERE id=?", (aid,))
    # The feedback-stage transcript too, so the once-per-colleague step-2 guide can show again
    # (the guide dedupe scans the transcript).
    db.execute("DELETE FROM pm_review_chat WHERE subject_id=? AND cycle_id=? AND stage='feedback'",
               (u["id"], cid))


def _demo_reset_team(db, u, cid):
    """Rewind what this ZZ demo account did AS A REVIEWER this cycle, so their team is back to "awaiting your review"
    (Chris, 2026-09-28: "under line manager view, the reset should work on the personal submission, and when i go to
    the team view, the reset will only work for the team view"). Their reports' own submissions are left as they are.
    Only ZZ demo subjects are touched. Returns the subject ids changed (for the rating record)."""
    uid = u["id"]
    zz = demo_account_sql("u.employee_id")
    touched = set()
    # PM: their approvals on the KPI lines they approve (and any later tier's, which built on theirs), their saved
    # moderation drafts, their overall remarks, the cached AI insights and the team transcript.
    lines = db.execute(
        "SELECT ap.kpi_target_id tid, ap.seq, t.subject_id sid FROM pm_kpi_target_approvers ap "
        "JOIN pm_kpi_targets t ON t.id=ap.kpi_target_id JOIN users u ON u.id=t.subject_id "
        "WHERE ap.approver_id=? AND t.cycle_id=? AND t.subject_id<>? AND " + zz, (uid, cid, uid)).fetchall()
    for r in lines:
        db.execute("DELETE FROM pm_kpi_approvals WHERE kpi_target_id=? AND seq>=?", (r["tid"], r["seq"]))
        db.execute("DELETE FROM pm_kpi_moderation_drafts WHERE kpi_target_id=? AND approver_id=?", (r["tid"], uid))
        touched.add(r["sid"])
    db.execute("DELETE FROM pm_manager_remarks WHERE cycle_id=? AND submitted_by=? AND subject_id IN "
               "(SELECT u.id FROM users u WHERE " + zz + ")", (cid, uid))
    db.execute("DELETE FROM pm_perf_summaries WHERE cycle_id=? AND approver_id=?", (cid, uid))
    # the Team threads only -- calibration's live in the leader views and have their own Reset (2026-09-30)
    db.execute("DELETE FROM pm_manager_chat WHERE reviewer_id=? AND cycle_id=? AND (stage IS NULL OR stage NOT IN "
               "(%s))" % ",".join("?" * len(_MCHAT_SCOPED_STAGES)), (uid, cid) + tuple(_MCHAT_SCOPED_STAGES))
    # TM: their calls and remarks on their reports' competency self-assessments; a reviewed one goes back to submitted.
    for r in db.execute("SELECT a.id, a.subject_id, a.status, a.reviewed_by FROM tc_assessments a "
                        "JOIN users u ON u.id=a.subject_id WHERE a.cycle_id=? AND u.manager_id=? AND " + zz,
                        (cid, uid)).fetchall():
        db.execute("UPDATE tc_scores SET manager_answer=NULL, manager_remark=NULL WHERE assessment_id=?", (r["id"],))
        db.execute("UPDATE tc_section_remarks SET manager_remark=NULL WHERE assessment_id=?", (r["id"],))
        db.execute("UPDATE tc_assessments SET manager_overall_remark=NULL WHERE id=?", (r["id"],))
        if r["status"] == "reviewed":
            db.execute("UPDATE tc_assessments SET status='submitted', reviewed_at=NULL, reviewed_by=NULL WHERE id=?",
                       (r["id"],))
        touched.add(r["subject_id"])
    # IDP: their comments on their reports' plans this plan year; a plan they closed goes back to shared.
    period = active_pm_period(db)
    if period:
        py = pm_idp_plan_year(period)
        # The plan remark is the LINE MANAGER's (_idp_remark_owner), so it's cleared only for their own direct reports
        # -- an HOD's team reset never clears the line manager's words.
        own = {r["id"] for r in db.execute("SELECT u.id FROM users u WHERE u.manager_id=? AND " + zz, (uid,)).fetchall()}
        subs = {r["sid"] for r in lines} | own
        for sid in subs:
            for p in db.execute("SELECT id, status, closed_by FROM pm_idp WHERE subject_id=? AND plan_year=?",
                                (sid, py)).fetchall():
                if sid in own:
                    db.execute("UPDATE pm_idp SET manager_comment=NULL WHERE id=?", (p["id"],))
                    db.execute("UPDATE pm_idp_goals SET manager_comment=NULL WHERE idp_id=?", (p["id"],))
                if p["status"] == "closed" and p["closed_by"] == uid:
                    db.execute("UPDATE pm_idp SET status='shared', closed_at=NULL, closed_by=NULL WHERE id=?", (p["id"],))
            db.execute("UPDATE pm_career_profile SET manager_comment=NULL, manager_comment_by=NULL, "
                       "manager_comment_at=NULL WHERE subject_id=? AND manager_comment_by=?", (sid, uid))
    return touched


def _demo_reset_calibration(db, u, cid, tier):
    """Rewind what this ZZ demo account did in ONE leader view's calibration this cycle (Chris, 2026-09-30: the Reset
    follows the view -- Dept / BU / BG reset their own calibration, Team its reviews): their moves and locks at that
    tier, on both axes (the Talent Box writes the same two tables), that view's thread, and -- for a BG CEO -- the
    talent-status snapshot their lock wrote. Only ZZ demo subjects are touched. Returns the subject ids changed."""
    uid = u["id"]
    zz = demo_account_sql("u.employee_id")
    touched = set()
    for sess_t, adj_t in (("pm_calibration_sessions", "pm_calibration_adjustments"),
                          ("calibration_sessions", "calibration_adjustments")):
        for r in db.execute("SELECT a.subject_id FROM " + adj_t + " a JOIN " + sess_t + " s ON s.id=a.session_id "
                            "JOIN users u ON u.id=a.subject_id WHERE s.cycle_id=? AND s.tier=? AND a.adjusted_by=? "
                            "AND " + zz, (cid, tier, uid)).fetchall():
            touched.add(r["subject_id"])
        db.execute("DELETE FROM " + adj_t + " WHERE adjusted_by=? AND subject_id IN (SELECT u.id FROM users u WHERE "
                   + zz + ") AND session_id IN (SELECT id FROM " + sess_t + " WHERE cycle_id=? AND tier=?)",
                   (uid, cid, tier))
        db.execute("UPDATE " + sess_t + " SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier=? "
                   "AND locked_by=?", (cid, tier, uid))
    first = next((t for t, _k in calibration_tier_of(db, u)), None)
    db.execute("DELETE FROM pm_manager_chat WHERE reviewer_id=? AND cycle_id=? AND stage IN (%s) "
               "AND (scope=? OR scope LIKE ? OR (scope IS NULL AND ?))" % ",".join("?" * len(_MCHAT_SCOPED_STAGES)),
               (uid, cid) + tuple(_MCHAT_SCOPED_STAGES) + (tier, tier + "|%", 1 if tier == first else 0))
    if tier == "bgceo":
        _demo_reset_talent_snapshot(db, u, cid)
        # the business units this demo account locked on its Talent Box (2026-10-07), and its remarks on ZZ people
        db.execute("DELETE FROM talent_box_bu_locks WHERE cycle_id=? AND locked_by=?", (cid, uid))
        db.execute("DELETE FROM talent_box_remarks WHERE cycle_id=? AND author_id=? AND subject_id IN "
                   "(SELECT u.id FROM users u WHERE " + zz + ")", (cid, uid))
    return touched


def _demo_reset_talent_snapshot(db, u, cid):
    """The talent-status snapshot a BG CEO's Talent Box lock wrote (_talent_snapshot_history: the period year,
    source 'calibration') -- cleared with their calibration reset, for the ZZ demo people of their BG only."""
    period = active_pm_period(db)
    bg = _row_get(u, "bgceo_bg")
    if not period or not bg or not period["year"]:
        return None
    db.execute("DELETE FROM talent_status_history WHERE year=? AND source='calibration' AND subject_id IN "
               "(SELECT id FROM users WHERE business_group=? AND " + demo_account_sql("employee_id") + ")",
               (period["year"], bg))
    return None


