@app.route("/review/demo/reset-all", methods=["POST"])
@login_required
def review_demo_reset_all():
    """The ONE demo reset: rewind THIS ZZ demo account's whole review -- check-in, KPI
    setting, competency, development plan, career profile and the person's own 360 --
    to a clean, editable start, chats included. ZZ demo accounts only, self-scoped,
    one commit. (The check-in stays editable regardless of the setting status for a ZZ
    account -- see _review_line_editable.)"""
    u = _review_demo_user()
    if not u:
        abort(404)
    db = get_db()
    cid = active_cycle_id(db)
    _demo_reset_checkin(db, u, cid)
    # Only the KPI-setting chat -- not _demo_reset_setting, which also deletes the approver chain on their own KPI
    # lines, so after a reset their check-in never reached their manager's team review (2026-09-28).
    db.execute("DELETE FROM pm_setting_chat WHERE subject_id=? AND cycle_id=?", (u["id"], cid))
    _demo_reset_competency(db, u, cid)
    _demo_reset_ahead(db, u, cid)
    _demo_reset_career(db, u, cid)
    _demo_reset_feedback(db, u, cid)
    # Leave the KPI setting APPROVED so the reset lands on a clean, ready-to-key
    # check-in (the journey starts at the check-in, and review_home routes there when
    # the setting is done; the ZZ override keeps it editable regardless).
    db.execute("UPDATE pm_kpi_targets SET status='approved' WHERE subject_id=? AND cycle_id=?",
               (u["id"], cid))
    db.commit()
    return redirect(url_for("review_home"))


@app.route("/review/demo/mechanism", methods=["POST"])
@login_required
def review_demo_mechanism():
    """Switch the session to the pre-seeded demo account for the chosen mechanism.
    ZZ->ZZ only, target resolved through the fixed REVIEW_DEMO_MECH map."""
    u = _review_demo_user()
    if not u:
        abort(404)
    target_eid = REVIEW_DEMO_MECH.get(request.form.get("mech", ""))
    if not target_eid:
        abort(404)
    target = get_db().execute("SELECT id, employee_id FROM users WHERE employee_id=?",
                              (target_eid,)).fetchone()
