@app.route("/review/competency/save-all", methods=["POST"])
@login_required
def review_competency_save_all():
    """Bulk-record all Demonstrate/Developing selections at once -- the in-chat
    'Save answers' button, mirroring /review/kpi/save-all. Each is recorded via
    the SAME per-answer write the agent tool uses (_tc_tool_set_competency), so
    there is no new write path and the model is never in the write path. NOT a
    submit: the competency confirm card (review_competency_submit) still
    finalises. Iterates the caller's OWN competencies, so a crafted id cannot
    reach another person's line."""
    u = _review_guard()
    db = get_db()
    cid = active_cycle_id(db)
    recorded, errors = [], []
    for row in db.execute("SELECT id FROM tc_assignments WHERE subject_id=? AND cycle_id=?",
                          (u["id"], cid)).fetchall():
        aid = row["id"]
        ans = (request.form.get("answer_%d" % aid, "") or "").strip()
        if not ans:
            continue
        res = _tc_tool_set_competency(db, u, cid, {"assignment_id": aid, "answer": ans})
        if res.get("ok"):
            recorded.append({"competency": res["competency"], "answer": res.get("answer")})
        else:
            errors.append({"assignment_id": aid, "error": res.get("error")})
    ov = _competency_overview(db, u)
    return jsonify(ok=True, recorded=recorded, errors=errors,
                   overview=(ov["data"] if ov else None))


@app.route("/review/feedback/save-all", methods=["POST"])
@login_required
def review_feedback_save_all():
    """Bulk-record all 360 behaviour ratings for one colleague at once -- the
    in-chat 'Save answers' button, mirroring /review/kpi/save-all. Each is
    recorded via the SAME per-answer write the agent tool uses
    (_feedback_tool_rate), whose scoped UPDATE means a statement_id not on this
    colleague's list is refused. NOT a submit: the existing Submit
    (review_feedback_submit) still finalises."""
    u = _review_guard()
    db = get_db()
    cid = active_cycle_id(db)
    aid = request.form.get("assignment_id")
    recorded, errors = [], []
    for key, val in request.form.items():
        m = re.match(r"^answer_(\d+)$", key)
