@app.route("/review/career/save-all", methods=["POST"])
@login_required
def review_career_save_all():
    """Bulk-save the career-profile fields at once -- the in-chat Career Plan
    widget's Save. Each field goes through the SAME single write path
    (pm_career_save_field) as the standalone page and the agent tool, so the field
    whitelist, the mobility-choice check and the 4000-char cap live in one place and
    the model is never in the write path. The profile has no submit gate --
    aspirations are never locked. An ABSENT field is left unchanged (a partial poster
    is safe); a PRESENT empty field clears it."""
    u = _review_guard()
    db = get_db()
    saved, errors = [], []
    for field in PM_CAREER_FIELDS:
        if field not in request.form:
            continue
        val = (request.form.get(field) or "").strip()
        ok, err = pm_career_save_field(db, u["id"], field, val or None)
        if ok:
            saved.append(field)
        else:
            errors.append({"field": field, "error": err})
    return jsonify(ok=True, saved=saved, errors=errors,
                   overview=_career_plan_overview_data(db, u), **_career_plan_chrome(db, u))


@app.route("/review/ahead/save-all", methods=["POST"])
@login_required
def review_ahead_save_all():
    """Bulk-save the development-plan goals at once -- the in-chat Career Plan
    widget's Save. Reuses the SAME validated write tools as the agent
    (_idp_tool_add_goal / _idp_tool_set_goal_field / _idp_tool_remove_goal), so the
    editability gate, the field whitelist and the goal cap all live in one place and
    the model is never in the write path. NOT a submit: the person's Share
    (review_ahead_submit) still finalises.

    Form: g_count cards, each g<i>_id (blank = new) + g<i>_area / _experience /
    _exposure / _education / _date; remove_ids = comma-separated goal ids deleted."""
    u = _review_guard()
    db = get_db()
    if not cycle_module_on("idp", db):   # a switched-off Development plans stops its write (1b-02)
        abort(404)
    cid = active_cycle_id(db)
    saved, added, removed, errors = [], [], [], []
    # Removals first, so a re-added area cannot collide with a row being deleted.
    for gid in (request.form.get("remove_ids", "") or "").split(","):
        gid = gid.strip()
        if not gid:
            continue
        res = _idp_tool_remove_goal(db, u, cid, {"goal_id": gid})
        if res.get("ok"):
            removed.append(gid)
        else:
            errors.append({"goal_id": gid, "error": res.get("error")})
    field_map = [("area", "area"), ("experience", "action_experience"),
                 ("exposure", "action_exposure"), ("education", "action_education"),
                 ("date", "target_date")]
    try:
        n = int(request.form.get("g_count", "0"))
    except (TypeError, ValueError):
        n = 0
    for i in range(max(0, min(n, 50))):
        pre = "g%d_" % i
        gid = (request.form.get(pre + "id", "") or "").strip()
        area = (request.form.get(pre + "area", "") or "").strip()
        if not gid:
            if not area:
                continue                 # a blank new card is nothing to save
            res = _idp_tool_add_goal(db, u, cid, {"area": area})
            if not res.get("ok"):
                errors.append({"card": i, "error": res.get("error")})
                continue
            gid = str(res["goal_id"]); added.append(gid)
            fields = field_map[1:]       # area already set by add_goal
        else:
            fields = field_map
        for form_key, col in fields:
            val = (request.form.get(pre + form_key, "") or "").strip()
            if not val:
                continue                 # empty = leave unchanged (set_goal_field rejects empty)
            res = _idp_tool_set_goal_field(db, u, cid,
                                           {"goal_id": gid, "field": col, "value": val})
            if res.get("ok"):
                saved.append({"goal_id": gid, "field": col})
            else:
                errors.append({"goal_id": gid, "field": col, "error": res.get("error")})
    return jsonify(ok=True, saved=saved, added=added, removed=removed, errors=errors,
                   overview=_career_plan_overview_data(db, u), **_career_plan_chrome(db, u))


def _review_attach_one(db, u, eid, f, added_reason=None):
    """Store ONE uploaded file against a review-logged evidence item (the caller's own
    recognition item), with the evidence module's caps + extensions. Returns
    (payload, status). Shared by the per-example attach, the per-KPI direct attach and a Group People admin's
    Add a file (2026-11-07: `u` is then the ADMIN, the item the person's own, `added_reason` stored with the file)."""
    n = db.execute("SELECT COUNT(*) c FROM pm_evidence_attachments WHERE evidence_id=? AND removed_at IS NULL",
                   (eid,)).fetchone()["c"]
    if n >= EVIDENCE_MAX_ATTACH_PER_ITEM:
        return {"ok": False, "error": "That's the limit -- up to %d files each; remove one to add "
                                      "another." % EVIDENCE_MAX_ATTACH_PER_ITEM}, 400
    if not f or not f.filename:
        return {"ok": False, "error": "Choose a file."}, 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in EVIDENCE_ATTACH_EXTS:
        return {"ok": False, "error": "That kind of file can't be attached -- use %s."
                                      % EVIDENCE_ATTACH_TYPES_TEXT}, 400
    data = f.read()
    if len(data) > EVIDENCE_ATTACH_MAX_BYTES:
        return {"ok": False, "error": "That file is too large -- %d MB is the limit."
                                      % EVIDENCE_ATTACH_MAX_MB}, 400
    why = _upload_content_refusal(ext, data)   # what its name says, no macros, no password (2026-11-11)
    if why:
        return {"ok": False, "error": why}, 400
    stored, backend = evidence_store_attachment(eid, ext, data, f.content_type)
    db.execute(
        "INSERT INTO pm_evidence_attachments(evidence_id, filename, stored_path, "
        "content_type, size_bytes, storage_backend, uploaded_by, added_reason) VALUES (?,?,?,?,?,?,?,?)",
        (eid, f.filename[:200], stored, f.content_type, len(data), backend, u["id"], added_reason))
    new_id = db.execute("SELECT last_insert_rowid()").fetchone()[0]
    db.commit()
    return {"ok": True, "filename": f.filename[:200], "count": n + 1, "id": new_id}, 200


@app.route("/review/evidence/<int:eid>/attach", methods=["POST"])
@login_required
def review_evidence_attach(eid):
    """Attach a supporting file to a review-logged evidence item -- reuses the
    evidence module's storage + limits. Unlike the /evidence page (draft-only),
    this allows attaching to the person's OWN already-shared review item, since
    the chat shares evidence immediately; attachments are additive and never
    touch the words."""
    u = _review_guard()
    if not cycle_module_on("evidence"):
        abort(404)
    db = get_db()
    row = evidence_get(db, eid)
    # Only your OWN review-logged item (recognition), never anyone else's.
    if not row or row["author_id"] != u["id"] or row["kind"] != "recognition":
        abort(404)
    # An item linked to an HR-owned KPI (BU-level / HR-filled) takes no file -- a file on it
    # would surface on HR's row. (log_evidence no longer links to one; this closes legacy links
    # and crafted POSTs.)
    _hr = _review_hr_owned_ids(db, u, active_cycle_id(db))
    if _hr and any(r["ref"] and r["ref"].isdigit() and int(r["ref"]) in _hr for r in db.execute(
            "SELECT target_ref ref FROM pm_evidence_links WHERE evidence_id=? AND target_kind='kpi'",
            (eid,)).fetchall()):
        return jsonify(ok=False, error="Group People fills that KPI -- no supporting file is needed."), 400
    _cid_ = active_cycle_id(db)
    if pm_review_locked(db, u["id"], _cid_):   # confirmed: no file goes on an item of a line that was submitted (2026-11-06)
        _lnk = [int(r["ref"]) for r in db.execute(
            "SELECT l.target_ref ref FROM pm_evidence_links l JOIN pm_kpi_targets t ON CAST(t.id AS TEXT)=l.target_ref "
            "WHERE l.evidence_id=? AND l.target_kind='kpi' AND t.subject_id=? AND t.cycle_id=?", (eid, u["id"], _cid_))]
        if (_lnk and not all(k in pm_added_open_ids(db, u["id"], _cid_) for k in _lnk)) or (
                not _lnk and _added_pass_only(db, "pm_results", _cid_, u["id"])):   # an unlinked item: not on the added-item pass
            return jsonify(ok=False, error="Your check-in is locked -- files can't be added now."), 400
    payload, status = _review_attach_one(db, u, eid, request.files.get("file"))
    return jsonify(**payload), status


@app.route("/review/kpi/<int:kpi_id>/attach", methods=["POST"])
@login_required
def review_kpi_attach(kpi_id):
    """Attach a supporting file DIRECTLY to a KPI (the FILES column paperclip), with no
    need to type a written example first (Chris, 2026-09-15). Ensures the caller's own
    KPI-linked recognition evidence item exists -- reusing it if present, else creating a
    file-only one -- then stores the file on it via the shared evidence-attachment path.
    Own KPI only, this cycle, and refused once the check-in is locked."""
    u = _review_guard()
    if not cycle_module_on("evidence"):
        abort(404)
    db = get_db()
    cid = active_cycle_id(db)
    if not db.execute("SELECT 1 FROM pm_kpi_targets WHERE id=? AND subject_id=? AND cycle_id=?",
                      (kpi_id, u["id"], cid)).fetchone():
        abort(404)
    if pm_review_locked(db, u["id"], cid) and kpi_id not in pm_added_open_ids(db, u["id"], cid):
        return jsonify(ok=False, error="Your check-in is locked -- files can't be added now."), 400
    # HR-owned KPI (BU-level / HR-filled): the employee can't fill it, so it takes no file and is
    # outside the AE/OU evidence rule (Chris, 2026-09-23). Refused BEFORE the evidence item is
    # created, so no file-less item gets linked to HR's line either.
    if kpi_id in _review_hr_owned_ids(db, u, cid):
        return jsonify(ok=False, error="Group People fills this KPI -- no supporting file is needed."), 400
    eid, err = _kpi_file_item(db, u, kpi_id)
    if err:
        return jsonify(ok=False, error=err), 400
    payload, status = _review_attach_one(db, u, eid, request.files.get("file"))
    return jsonify(**payload), status


def _kpi_file_item(db, subject, kpi_id):
    """(evidence id, error): the person's own KPI-linked recognition item that a file goes on -- the latest one linked to this
    KPI, else a file-only one made, shared and linked now. ONE helper for the check-in's attach (review_kpi_attach) and a Group
    People admin's Add a file (2026-11-07): the item is always the PERSON's (author = subject), so every reader of their files
    (_pm_kpi_files, _review_kpi_attachment_ids, the evidence download) sees an added file the way it sees their own."""
    row = db.execute(
        "SELECT e.id FROM pm_evidence e JOIN pm_evidence_links l ON l.evidence_id=e.id "
        "AND l.target_kind='kpi' AND l.target_ref=? WHERE e.author_id=? AND e.kind='recognition' "
        "ORDER BY e.id DESC LIMIT 1", (str(kpi_id), subject["id"])).fetchone()
    if row:
        return row["id"], None
    # A file-only recognition item (no written words) linked to the KPI, mirroring
    # _review_tool_log_evidence's create + share + link. Its empty body is skipped by
    # the confirm card's example recap (_review_justification); the FILE still shows.
    fields = {"body": None, "impact": None, "who": None, "title": None,
              "kind": "recognition", "occurred_on": _today_myt().isoformat(),
              "occurred_precision": "day", "metric_value": None, "metric_unit": None,
              "raised_with_subject": None}
    eid, err = pm_evidence_write(db, subject, subject["id"], fields)
    if err:
        return None, err
    db.execute("UPDATE pm_evidence SET state='shared', shared_at=datetime('now'), "
               "updated_at=datetime('now') WHERE id=? AND author_id=?", (eid, subject["id"]))
    db.execute("INSERT OR IGNORE INTO pm_evidence_links(evidence_id, target_kind, target_ref) "
               "VALUES (?,'kpi',?)", (eid, str(kpi_id)))
    db.commit()
    return eid, None


@app.route("/review/evidence/attachment/<int:aid>/delete", methods=["POST"])
@login_required
def review_evidence_attachment_delete(aid):
    """Remove ONE attachment from your OWN review-logged item. Gated on AUTHORSHIP
    (the evidence row's author_id), never evidence_can_view -- so the subject's line
    manager can't delete their proof. Deletes the stored file + the row; the words
    (the evidence body) are untouched. 'Edit' a file = remove then re-attach."""
    u = _review_guard()
    if not cycle_module_on("evidence"):
        abort(404)
    db = get_db()
    att = db.execute("SELECT * FROM pm_evidence_attachments WHERE id=? AND removed_at IS NULL", (aid,)).fetchone()
    if not att:
        abort(404)
    row = evidence_get(db, att["evidence_id"])
    # 404 (not 403): don't confirm someone else's file exists.
    if not row or row["author_id"] != u["id"] or row["kind"] != "recognition":
        abort(404)
    if att["uploaded_by"] and att["uploaded_by"] != u["id"]:   # a file Group People added (2026-11-07) stays with the record
        return jsonify(ok=False, error="Group People added this file, so it stays on the record."), 400
    # A CONFIRMED check-in keeps its evidence (Chris, 2026-09-24): once submitted to the approver, a file that
    # backs a KPI rating can't be removed -- the approver would see an Above Expectation / Outstanding with no
    # proof. Only for items linked to a KPI of THIS cycle; the widget hides the x too.
    _cid = active_cycle_id(db)
    _kpi_linked = db.execute(
        "SELECT t.id FROM pm_evidence_links l JOIN pm_kpi_targets t ON CAST(t.id AS TEXT)=l.target_ref "
        "WHERE l.evidence_id=? AND l.target_kind='kpi' AND t.subject_id=? AND t.cycle_id=?",
        (att["evidence_id"], u["id"], _cid)).fetchall()
    # confirmed: a file comes off only a line added since that is still open (2026-11-06)
    if (_kpi_linked and pm_review_locked(db, u["id"], _cid) and not all(
            r[0] in pm_added_open_ids(db, u["id"], _cid) for r in _kpi_linked)) or (
            not _kpi_linked and _added_pass_only(db, "pm_results", _cid, u["id"])):
        return jsonify(ok=False, error="Your check-in is submitted -- its supporting files can't be removed now."), 400
    try:
        os.remove(os.path.join(EVIDENCE_UPLOAD_DIR, att["stored_path"]))
    except OSError:
        pass
    db.execute("DELETE FROM pm_evidence_attachments WHERE id=?", (aid,))
    db.commit()
    return jsonify(ok=True)


@app.route("/review/kpi-evidence", methods=["POST"])
@login_required
def review_kpi_evidence():
    """A compliment / justification captured in the conversation, written as a
    SHARED evidence item and optionally cited to a KPI. It goes to the evidence
    ledger on purpose: it survives the result submit-lock (a per-KPI note does
    not) and it reaches the manager's calibration room. Reuses the one evidence
    writer + the KPI link under the hood; gated on the evidence module."""
    u = _review_guard()
    if not cycle_module_on("evidence"):
        abort(404)
    db = get_db()
    body = (request.form.get("body") or "").strip()
    if not body:
        return jsonify(ok=False, error="Say a sentence."), 400
    kpi_id = None
    kpi_raw = (request.form.get("kpi_target_id") or "").strip()
    if kpi_raw.isdigit():
        cid = active_cycle_id(db)
        row = db.execute("SELECT id FROM pm_kpi_targets WHERE id=? AND subject_id=? "
                         "AND cycle_id=?", (int(kpi_raw), u["id"], cid)).fetchone()
        # Never cite to an HR-owned KPI (BU-level / HR-filled): it takes no evidence. The item is
        # still kept, just unlinked.
        if row and row["id"] not in _review_hr_owned_ids(db, u, cid):
            kpi_id = row["id"]
    _lk = pm_locked_line_refusal(db, u["id"], active_cycle_id(db), kpi_id)   # confirmed: only a line added since (2026-11-06)
    if _lk:
        return jsonify(ok=False, error=_lk), 400
    fields = {"body": body[:EVIDENCE_BODY_MAX], "impact": None, "who": None,
              "title": None, "kind": "recognition",
              "occurred_on": _today_myt().isoformat(), "occurred_precision": "day",
              "metric_value": None, "metric_unit": None, "raised_with_subject": None}
    eid, err = pm_evidence_write(db, u, u["id"], fields)
    if err:
        return jsonify(ok=False, error=err), 400
    db.execute("UPDATE pm_evidence SET state='shared', shared_at=datetime('now'), "
               "updated_at=datetime('now') WHERE id=? AND author_id=? AND state='draft'",
               (eid, u["id"]))
    if kpi_id is not None:
        db.execute("INSERT OR IGNORE INTO pm_evidence_links(evidence_id, target_kind, "
                   "target_ref) VALUES (?,'kpi',?)", (eid, str(kpi_id)))
    db.commit()
    return jsonify(ok=True, id=eid)


# ---------------------------------------------------------------------------
# The conversational KPI-SETTING agent. Same architecture as the check-in
# agent above -- the MODEL converses and proposes; these tools VALIDATE and
# perform every write, enforce the 100%-weight rule and per-line completeness,
# and resolve approvers. The model can never PROPOSE the set for approval: that
# is an explicit human click (POST /review/setting/propose), mirroring the
# check-in's /review/confirm. Library-driven -- the agent may only add KPIs the
# person is eligible for (pm_library_for_person), by library_id.
# ---------------------------------------------------------------------------
def _setting_chat_history(db, u, cid):
    rows = db.execute(
        "SELECT role, content, quick_replies, card FROM pm_setting_chat WHERE subject_id=? "
        "AND cycle_id=? ORDER BY id DESC LIMIT ?", (u["id"], cid, REVIEW_CHAT_MAX)).fetchall()
    out = []
    for r in reversed(rows):
        m = {"role": r["role"], "content": r["content"]}
        if r["quick_replies"]:
            try:
                m["quick_replies"] = json.loads(r["quick_replies"])
            except (ValueError, TypeError):
                pass
        if r["card"]:
            try:
                m["card"] = json.loads(r["card"])
            except (ValueError, TypeError):
                pass
        out.append(m)
    return out


def _setting_line_complete(t, cfg):
    """Does this proposed line carry every number its mechanism needs to score?
    The SAME check performance_kpi_setting_propose() runs per line, so the widget
    and the propose gate can never disagree about what 'complete' means."""
    if not cfg:
        return False
    if cfg["mechanism"] == "A":
        if any((t.get("rate%d" % i) if isinstance(t, dict) else t["rate%d" % i]) is None
               for i in range(1, 6)):
            return False
        return pm_ladder_monotonic(t, t["method"])
    thr = t.get("threshold") if isinstance(t, dict) else t["threshold"]
    tgt = t.get("target") if isinstance(t, dict) else t["target"]
    if thr is None or tgt is None:
        return False
    if cfg["variant"] == "excellence":
        exc = t.get("excellence") if isinstance(t, dict) else t["excellence"]
        if exc is None:
            return False
    return pm_scale_error(cfg, t.get("method") if isinstance(t, dict) else t["method"], t) is None


def _setting_overview(db, u):
    """The KPI-setting widget shown at the top of the chat: the scorecard the
    person is BUILDING -- each KPI, its weight, its target scale and whether it is
    complete -- with the running weight total and a 100% indicator. A live widget,
    rebuilt each turn from server state (never a stored snapshot). Returns None only
    when there is no active period."""
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return None
    cfg = ctx["cfg"]
    mech = cfg["mechanism"] if cfg else None
    # The working set while building; the agreed set once it is approved (read-only).
    working = ctx["mine"] if ctx["mine"] else ctx["agreed"]
    rows = []
    for t in working:
        scale = []
        if all(t.get("rate%d" % i) is not None for i in range(1, 6)):
            for n in (1, 2, 3, 4, 5):
                scale.append({"n": n, "value": _commas(t.get("rate%d" % n))})
        scale_b = []
        if mech == "B":
            if t.get("threshold") is not None:
                scale_b.append({"label": "Threshold", "value": _commas(t.get("threshold"))})
            if t.get("target") is not None:
                scale_b.append({"label": "Target", "value": _commas(t.get("target"))})
            if t.get("excellence") is not None:
                scale_b.append({"label": "Excellence", "value": _commas(t.get("excellence"))})
            elif t.get("multiple") is not None:
                scale_b.append({"label": "Multiplier", "value": "%s%%" % t.get("multiple")})
        direction = None
        if t.get("method"):
            direction = "higher is better" if t.get("method") == "more" else "lower is better"
        rows.append({
            "kpi_id": t["id"], "kpi": t["kpi_name"],
            "category": t.get("category") or "", **kpi_line_parts(t),
            "direction": direction, "mechanism": mech,
            "weight": t["weightage"], "unit": kpi_unit_normalise(t.get("unit")) or "",
            "unit_offer": _kpi_unit_offer(t) if ctx["editable"] and ctx["mine"] else None,
            "scale": scale, "scale_b": scale_b,
            "target": _commas(t["target"]) if t.get("target") is not None else None,
            "number_source": t.get("number_source"),
            "complete": _setting_line_complete(t, cfg),
            "status": t["status"],
        })
    total = ctx["total_weight"] if ctx["mine"] else ctx["agreed_weight"]
    blocked_on = None
    if ctx["state"] == "proposed" and ctx["mine"]:
        nxt = pm_setting_next_approver(db, ctx["mine"][0]["id"])
        blocked_on = nxt["approver_name"] if nxt else None
    return {"type": "setting_overview", "data": {
        "lines": rows,
        "total_weight": total,
        "weight_ok": abs((total or 0) - 100.0) <= 0.01,
        "n_incomplete": sum(1 for r in rows if not r["complete"]),
        "editable": ctx["editable"], "state": ctx["state"],
        "blocked_on": blocked_on, "library_count": len(ctx["library"]),
        "mechanism": mech,
    }}


def _setting_rail_html(st):
    """The rail fragment for the setting chat, highlighting the 'agree' stage."""
    stage = next((x for x in st["stages"] if x["key"] == "agree"), {"key": "agree"})
    return render_template("_review_rail.html", st=st, stage=stage)


def _setting_agent_system(db, u, ctx):
    period = ctx["period"]
    pname = period["name"] if period else "this period"
    cfg = ctx["cfg"]
    first = welcome_identity(u).get("first_name") or "there"
    lib = [{"library_id": r["id"], "name": r["kpi_name"],
            "category": r.get("category") or "", "scope": r.get("scope_label") or "",
            "direction": "higher is better" if r.get("method") == "more" else "lower is better",
            "already_chosen": bool(r.get("already_chosen"))} for r in ctx["library"]]
    mine = [{"kpi_id": t["id"], "name": t["kpi_name"], "weight": t["weightage"],
             "complete": _setting_line_complete(t, cfg), "status": t["status"],
             "unit": kpi_unit_normalise(t.get("unit")) or "",
             **({"better_unit": (_kpi_unit_offer(t) or {}).get("unit")} if _kpi_unit_offer(t) else {})}
            for t in ctx["mine"]]
    parts = [
        "You are OneHR's KPI-setting assistant, helping %s BUILD their performance "
        "scorecard for %s. Sound like a sharp, friendly colleague -- warm, natural, "
        "specific. One thing at a time; keep each reply to a sentence or two." % (first, pname),
        "VOICE, this matters: never repeat a sentence you have already said -- say it "
        "a new way or move forward. React to what they ACTUALLY said; if they seem "
        "unsure, explain with a tiny concrete example. Vary your openers; don't gush. "
        "NEVER expose internal machinery: do not mention library ids or KPI ids, tool "
        "names, or how weights/targets are stored. Refer to each KPI by its NAME, and "
        "talk like a person, not a system.",
        "THE SCORECARD: a set of KPIs whose WEIGHTS must total EXACTLY 100%, and each "
        "KPI needs its full scale. Help them (1) choose KPIs, (2) set a weight for each, "
        "(3) set the target and every other point of the scale for each. They may ONLY choose from their eligible KPI "
        "library below -- if they describe something in their own words, MAP it to the "
        "closest library KPI and add it by its library_id. Do NOT invent a KPI that is "
        "not in the library; if nothing fits, say so.",
        "Their eligible KPI library:\n" + json.dumps(lib, ensure_ascii=False),
        "Their scorecard so far (weights total %g%%):\n%s"
        % (ctx["total_weight"], json.dumps(mine, ensure_ascii=False)),
    ]
    if not ctx["editable"]:
        parts.append(
            "IMPORTANT: this scorecard is NOT editable right now (%s). Do not try to "
            "add, remove or change anything -- explain the situation warmly and, if it "
            "is with an approver, tell them it will reopen if it is returned."
            % _pm_setting_shut_reason(ctx))
    parts.append(
        "FIGURES: every KPI starts with blank figures and a blank weight. The PERSON sets every point of "
        "the scale and the weight; nothing is derived from a target, and the system fills in no other point. "
        "Ask for each one (the target with set_target(kpi_id, base), every other point with "
        "set_number(kpi_id, field, value), the weight with set_weight), never invent a figure, and never say "
        "the system works the rest out. If a line's figures are last year's in grey on the page, say they "
        "are only a hint to type over. Confirm the number you understood from free "
        "text (e.g. 'about 16 mil' -> 16 for a KPI measured in RM mil). Pass base and value as the bare "
        "number in the line's unit (42 for '42%' on a % KPI).")
    parts.append(
        "UNITS: each KPI on their scorecard shows its unit. When one shows better_unit, its figures are big (or small) "
        "enough to read better in that unit: offer it ONCE, in a sentence, with the example (e.g. 'Your sales targets "
        "run into millions -- shall I show them in RM (mil), so 15,900,000 reads 15.9?'), and only on their yes call "
        "set_unit(kpi_id, unit); the figures move with it, nothing changes in value. Never change a unit without "
        "their yes. A unit is one of: " + ", ".join(KPI_UNITS) + ". The card under the table offers the same.")
    parts.append(
        "If they want help or a starting point, call suggest_set{} for a balanced draft "
        "from their library (weights already summing to 100), then refine it together.")
    parts.append(
        "If they ask to SEE or BROWSE the KPI library (what they can choose from / "
        "what's available to add), call show_library{} -- it shows the eligible KPIs as "
        "a card they can add from; do NOT prose-dump the list yourself.")
    parts.append(
        'TOOLS for "action": add_kpi{library_id}; remove_kpi{kpi_id}; '
        'set_weight{kpi_id, weight}; set_target{kpi_id, base}; '
        'set_number{kpi_id, field, value}; set_unit{kpi_id, unit}; suggest_set{instruction (optional)}; '
        "show_library{}; show_scorecard{}; prepare_propose{}. If nothing is left to do, "
        "say so warmly and set action null.")
    parts.append(
        "The scorecard is ALWAYS PINNED at the top of the chat -- every KPI, its weight, "
        "its target scale and the running total. So if they ask to see it, just point "
        "them to the table at the top; do NOT list it in prose. Call show_scorecard{} "
        "only if they explicitly want it inside the conversation.")
    parts.append(
        "THE FINISH: when the weights total exactly 100% and every KPI has its target "
        "numbers, call prepare_propose{} -- it shows the final scorecard, who it will go "
        "to for approval, and a Submit button. NEVER claim it is submitted or approved "
        "yourself; ONLY their Submit click proposes it. If prepare_propose returns a "
        "reason it is not ready (weights off 100, a missing target), tell them what to "
        "fix in plain words and help them fix it.")
    parts.append(_AGENT_SCOPE_GUARD)
    return "\n\n".join(parts)


# --- Setting tools: each fn(db, u, cid, args), validates ctx['editable'] -----
def _setting_ctx_or_error(db, u):
    """(ctx, None) when the person may edit their setting, else (None, error)."""
    _w = window_closed(db, "pm_setting")
    if _w:
        return (None, {"ok": False, "error": _w})
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return None, {"ok": False, "error": "There is no active performance period."}
    if not ctx["editable"]:
        return None, {"ok": False, "error": _pm_setting_shut_reason(ctx)}
    return ctx, None


def _setting_weight_of(raw, fallback=None):
    raw = str(raw if raw is not None else "").strip().rstrip("%").replace(",", "")
    if raw == "":
        return fallback
    try:
        v = float(raw)
    except ValueError:
        return None
    return v if math.isfinite(v) and 0 < v <= 100 else None


def _setting_own_target(db, u, cid, args):
    """The caller's OWN still-editable (draft/returned) target named in args, or an
    error dict. Never trusts the posted id past this scope check."""
    try:
        kid = int(args.get("kpi_id"))
    except (TypeError, ValueError):
        return None, {"ok": False, "error": "need a kpi_id"}
    t = db.execute("SELECT * FROM pm_kpi_targets WHERE id=? AND subject_id=? AND cycle_id=?",
                   (kid, u["id"], cid)).fetchone()
    if not t:
        return None, {"ok": False, "error": "that KPI is not on your scorecard"}
    # DEMO ONLY (is_demo_account): a demo account's setting is kept editable for testing,
    # so an agreed/proposed line can be edited too. Never on production.
    _demo = is_demo_account(u)
    if not _demo and t["status"] not in ("draft", "returned"):
        return None, {"ok": False, "error": "that line is no longer editable"}
    return t, None


def _setting_tool_add_kpi(db, u, cid, args):
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    try:
        library_id = int(args.get("library_id"))
    except (TypeError, ValueError):
        return {"ok": False, "error": "need a library_id from the eligible list"}
    lib = next((r for r in ctx["library"] if r["id"] == library_id), None)
    if not lib:
        return {"ok": False, "error": "that KPI is not in your eligible library"}
    weight = _setting_weight_of(args.get("weight"), 0)   # blank until they say (the column is NOT NULL: 0 reads as not set)
    if weight is None:
        return {"ok": False, "error": "weight must be a number between 0 and 100"}
    nums, source = pm_default_numbers(db, u, ctx["period"], lib, ctx["cfg"])
    try:
        db.execute(
            "INSERT INTO pm_kpi_targets(cycle_id, subject_id, kpi_name, category, "
            "description, weightage, unit, method, rate1, rate2, rate3, rate4, rate5, "
            "threshold, target, multiple, excellence, business_group, company, "
            "department, created_by, status, library_id, number_source) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft',?,?)",
            # the library keeps a short definition, no longer copied onto the line: the line's description is the
            # person's own words (Chris, 2026-10-18)
            (ctx["period"]["id"], u["id"], lib["kpi_name"], lib["category"], None,
             weight, kpi_unit_normalise(lib["unit"]), lib["method"], nums["rate1"], nums["rate2"], nums["rate3"],
             nums["rate4"], nums["rate5"], nums["threshold"], nums["target"], nums["multiple"],
             nums["excellence"], u["business_group"], u["company"], u["department"], u["id"],
             lib["id"], source))
        db.commit()
    except sqlite3.IntegrityError:
        return {"ok": False, "error": "'%s' is already on your scorecard" % lib["kpi_name"]}
    return {"ok": True, "added": lib["kpi_name"], "weight": weight}


def _setting_tool_remove_kpi(db, u, cid, args):
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    t, err = _setting_own_target(db, u, cid, args)
    if err:
        return err
    db.execute("DELETE FROM pm_kpi_targets WHERE id=?", (t["id"],))
    db.commit()
    return {"ok": True, "removed": t["kpi_name"]}


def _setting_tool_set_weight(db, u, cid, args):
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    t, err = _setting_own_target(db, u, cid, args)
    if err:
        return err
    weight = _setting_weight_of(args.get("weight"))
    if weight is None:
        return {"ok": False, "error": "weight must be a number between 0 and 100"}
    db.execute("UPDATE pm_kpi_targets SET weightage=?, updated_at=datetime('now'), "
               "updated_by=? WHERE id=?", (weight, u["id"], t["id"]))
    db.commit()
    return {"ok": True, "kpi": t["kpi_name"], "weight": weight}


def _setting_tool_set_target(db, u, cid, args):
    """Set the line's target only. Nothing derives the other points of the scale: the person gives each (set_number)."""
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    t, err = _setting_own_target(db, u, cid, args)
    if err:
        return err
    base, ferr = _agent_figure(args.get("base"), t["unit"], arg="base")
    if ferr:
        return {"ok": False, "error": ferr}
    if base <= 0:
        return {"ok": False, "error": "the target must be a positive number"}
    db.execute("UPDATE pm_kpi_targets SET target=?, updated_at=datetime('now'), "
               "updated_by=? WHERE id=?", (round(base, 2), u["id"], t["id"]))
    db.commit()
    return {"ok": True, "kpi": t["kpi_name"], "target": _commas(round(base, 2)),
            "note": "Only the target was set. Ask for each other point of the scale and the weight; use set_number."}


def _setting_tool_set_number(db, u, cid, args):
    """Set one specific numeric field on a line, mechanism-whitelisted so a crafted
    field can't stuff the wrong mechanism's column (the autosave 'numbers' rule)."""
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    t, err = _setting_own_target(db, u, cid, args)
    if err:
        return err
    cfg = ctx["cfg"]
    if not cfg:
        return {"ok": False, "error": "your Business Group has no scoring mechanism set yet"}
    if cfg["mechanism"] == "A":
        allowed = {"rate1", "rate2", "rate3", "rate4", "rate5", "target"}
    elif cfg["variant"] == "excellence":
        allowed = {"threshold", "target", "excellence"}
    else:
        allowed = {"threshold", "target", "multiple"}
    field = (args.get("field") or "").strip()
    if field not in allowed:
        return {"ok": False, "error": "field must be one of %s" % ", ".join(sorted(allowed))}
    # the Multiple is a percentage whatever the line's unit (KPI_UNIT_FIG_COLS leaves it out)
    v, ferr = _agent_figure(args.get("value"), t["unit"], arg="value", pct_ok=(field == "multiple"))
    if ferr:
        return {"ok": False, "error": ferr}
    val = int(v) if field == "multiple" else v
    db.execute("UPDATE pm_kpi_targets SET %s=?, updated_at=datetime('now'), "
               "updated_by=? WHERE id=?" % field, (val, u["id"], t["id"]))
    db.commit()
    return {"ok": True, "kpi": t["kpi_name"], "field": field, "value": _commas(val)}


def _setting_tool_suggest_set(db, u, cid, args):
    """A balanced starter set from the person's library -- reuses draft_kpi_set +
    _pm_parse_kpi_set (weights re-normalised to 100 server-side), quota-limited."""
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    candidates = ctx["library"]
    if not candidates:
        return {"ok": False, "error": "there are no library KPIs for your role yet"}
    field_key = "kpi_set:%s" % ctx["period"]["id"]
    _used, remaining, reset_seconds = _pm_ai_draft_quota(db, u["id"], field_key)
    if remaining <= 0:
        return {"ok": False, "error": "the AI suggestion limit for this period is used up "
                                      "-- help them build it by hand instead"}
    instruction = (args.get("instruction") or "").strip()
    try:
        raw = ai_draft.draft_kpi_set(
            "for a %s role%s" % (ctx["tier"]["name"],
                                 (" in %s" % u["department"]) if u["department"] else ""),
            candidates, instruction=instruction)
    except (ai_draft.AIDraftNotConfigured, ai_draft.AIDraftError):
        return {"ok": False, "error": "couldn't draft a set just now -- add KPIs one at a time"}
    by_id = {c["id"]: c for c in candidates}
    picks = _pm_parse_kpi_set(raw, set(by_id))
    if not picks:
        return {"ok": False, "error": "couldn't draft a usable set -- add KPIs one at a time"}
    period, cfg = ctx["period"], ctx["cfg"]
    mechanism = cfg["mechanism"] if cfg else "A"
    variant = cfg["variant"] if cfg else None
    db.execute("DELETE FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
               "AND status IN ('draft','returned')", (period["id"], u["id"]))
    added = 0
    for p in picks:
        lib = by_id[p["id"]]
        nums, source = pm_default_numbers(db, u, period, lib, cfg)
        # no AI figure is stored: the person sets every point from this year's plan (Chris, 2026-11-02)
        try:
            db.execute(
                "INSERT INTO pm_kpi_targets(cycle_id, subject_id, kpi_name, category, "
                "description, weightage, unit, method, rate1, rate2, rate3, rate4, rate5, "
                "threshold, target, multiple, excellence, business_group, company, "
                "department, created_by, status, library_id, number_source) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft',?,?)",
                (period["id"], u["id"], lib["kpi_name"], lib["category"], lib["description"],
                 p["weightage"], kpi_unit_normalise(lib["unit"]), lib["method"], nums["rate1"], nums["rate2"],
                 nums["rate3"], nums["rate4"], nums["rate5"], nums["threshold"], nums["target"],
                 nums["multiple"], nums["excellence"], u["business_group"], u["company"],
                 u["department"], u["id"], lib["id"], source))
            added += 1
        except sqlite3.IntegrityError:
            continue
    db.execute("INSERT INTO pm_ai_draft_usage(user_id, field_key) VALUES (?,?)",
               (u["id"], field_key))
    db.commit()
    log_activity(db, u["id"], "pm_ai_kpi_set", "%s: suggested %d KPI(s)" % (period["name"], added))
    return {"ok": True, "suggested": added}


def _setting_scorecard_card(db, u):
    """The current scorecard as a renderable card (lines + weight total), shared by
    show_scorecard and prepare_propose. Read-only."""
    ov = _setting_overview(db, u)
    data = ov["data"] if ov else {"lines": [], "total_weight": 0}
    return {"lines": data.get("lines", []), "total_weight": data.get("total_weight", 0),
            "weight_ok": data.get("weight_ok", False),
            "n_incomplete": data.get("n_incomplete", 0)}


def _setting_tool_show_scorecard(db, u, cid, args):
    return {"ok": True, "displayed": "scorecard",
            "render": {"type": "setting_scorecard", "data": _setting_scorecard_card(db, u)}}


def _setting_tool_show_library(db, u, cid, args):
    """Show the eligible KPI LIBRARY as a browsable card, so a person can ask what
    they can choose from and pick from it. Read-only; the eligible set is the same
    `ctx["library"]` the add route validates against (pm_library_for_person)."""
    ctx = _pm_setting_context(db, u)
    lib = (ctx["library"] if ctx else []) or []
    rows = [{"library_id": r["id"], "name": r["kpi_name"],
             "category": r.get("category") or "", "scope": r.get("scope_label") or "",
              "direction": "higher is better" if r.get("method") == "more" else "lower is better",
             "already_chosen": bool(r.get("already_chosen"))} for r in lib]
    return {"ok": True, "displayed": "library",
            "render": {"type": "setting_library", "data": {"lines": rows}}}


def _setting_tool_prepare_propose(db, u, cid, args):
    """Show the final propose card -- the scorecard, who it goes to, and a Submit
    button. Writes NOTHING (the propose only happens on the human Submit click,
    POST /review/setting/propose). Refuses, in plain words, when the set is not
    ready (weights off 100, a missing/invalid number)."""
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return {"ok": False, "error": "there is no active performance period"}
    if not ctx["editable"]:
        return {"ok": False, "error": _pm_setting_shut_reason(ctx)}
    ok, errors, _warn = _pm_setting_validate(ctx)
    if not ok:
        return {"ok": False, "error": "; ".join(errors)}
    approver_ids = pm_setting_resolve_approvers(db, u)
    approver = None
    if approver_ids:
        row = db.execute("SELECT full_name FROM users WHERE id=?", (approver_ids[0],)).fetchone()
        approver = row["full_name"] if row else None
    card = _setting_scorecard_card(db, u)
    card["approver"] = approver
    return {"ok": True, "ready": True, "render": {"type": "setting_confirm", "data": card}}


def _setting_tool_set_unit(db, u, cid, args):
    """Set a line's unit, one of KPI_UNITS (2026-10-18, board 23). On the same scale its figures move with it, so
    nothing changes in value (15,900,000 RM is 15.9 RM (mil)); another unit leaves the figures as they are. The card's
    offer (review_setting_unit) and the agent's set_unit both come here."""
    ctx, err = _setting_ctx_or_error(db, u)
    if err:
        return err
    t, err = _setting_own_target(db, u, cid, args)
    if err:
        return err
    unit = kpi_unit_normalise(args.get("unit"))
    if unit not in KPI_UNITS:
        return {"ok": False, "error": "the unit must be one of: " + ", ".join(KPI_UNITS)}
    if (t["unit"] or None) == unit:
        return {"ok": True, "kpi": t["kpi_name"], "unit": unit, "note": "it is already in %s" % unit}
    block = _kpi_unit_result_block(db, t, unit)
    if block:
        return {"ok": False, "error": block}
    steps = kpi_unit_steps_between(kpi_unit_normalise(t["unit"]), unit)
    moved = kpi_unit_moved(t, steps) if steps else {}
    db.execute("UPDATE pm_kpi_targets SET unit=?%s, updated_at=datetime('now'), updated_by=? WHERE id=?" % "".join(
        ", %s=?" % c for c in moved), [unit] + list(moved.values()) + [u["id"], t["id"]])
    db.commit()
    out = {"ok": True, "kpi": t["kpi_name"], "unit": unit}
    tv = _kpi_unit_target(t)
    if steps and tv is not None:
        out["figures"] = "moved with it: %s %s is now %s %s" % (_commas(tv), kpi_unit_normalise(t["unit"]),
                                                                _commas(kpi_unit_shift(tv, steps)), unit)
    return out


def _kpi_unit_offer(t):
    """A line's unit offer for the setting card and its agent, or None: kpi_unit_suggest with the words the card says
    ("These figures are in the millions.")."""
    sg = kpi_unit_suggest(kpi_unit_normalise(_row_get(t, "unit")), t)
    if not sg:
        return None
    step = KPI_UNIT_STEP[sg["unit"]][1]
    words = ("These figures are in the %s." % ("thousands", "millions", "billions")[step - 1] if sg["steps"] > 0
             else "These figures are under one %s." % sg["from"])
    return {"unit": sg["unit"], "from": sg["from"], "was": _commas(sg["was"]), "now": _commas(sg["now"]),
            "words": words}


_SETTING_TOOLS = {
    "add_kpi": _setting_tool_add_kpi,
    "remove_kpi": _setting_tool_remove_kpi,
    "set_weight": _setting_tool_set_weight,
    "set_target": _setting_tool_set_target,
    "set_number": _setting_tool_set_number,
    "set_unit": _setting_tool_set_unit,
    "suggest_set": _setting_tool_suggest_set,
    "show_scorecard": _setting_tool_show_scorecard,
    "show_library": _setting_tool_show_library,
    "prepare_propose": _setting_tool_prepare_propose,
}


def _setting_run_tool(db, u, cid, action):
    fn = _SETTING_TOOLS.get(action.get("tool"))
    if not fn:
        return {"ok": False, "error": "unknown tool"}
    args = action.get("args") or {}
    if not isinstance(args, dict):
        args = {}
    return fn(db, u, cid, args)


def _pm_setting_validate(ctx):
    """The propose validation, as a pure check over an editable ctx: at least one
    KPI, weights total exactly 100%, a mechanism configured, every line complete.
    Returns (ok, errors, warn) and WRITES NOTHING -- shared by prepare_propose
    (render) and _pm_setting_propose (the write), so the confirm card and the
    actual submit can never disagree about what 'ready' means."""
    mine = ctx["mine"]
    if not mine:
        return False, ["Add at least one KPI before proposing."], None
    total = round(sum(t["weightage"] or 0 for t in mine), 2)
    if abs(total - 100.0) > 0.01:
        return False, ["Weightages must total exactly 100%% — yours total %g%%." % total], None
    cfg = ctx["cfg"]
    if not cfg:
        return False, ["Your Business Group has no scoring mechanism configured yet — "
                       "ask Group People to set it before proposing."], None
    errors = []
    for t in mine:
        if not (t["weightage"] or 0) > 0:   # a new line starts with no weight (Chris, 2026-11-02)
            errors.append("'%s' has no weight yet." % t["kpi_name"])
        if cfg["mechanism"] == "A":
            if any(t[f"rate{i}"] is None for i in range(1, 6)):
                errors.append("'%s' is missing its Rate 1–5 thresholds." % t["kpi_name"])
            elif pm_scale_error(cfg, t["method"], t, t["kpi_name"]):
                errors.append(pm_scale_error(cfg, t["method"], t, t["kpi_name"]))
        else:
            if t["threshold"] is None or t["target"] is None:
                errors.append("'%s' is missing its Threshold/Target." % t["kpi_name"])
            elif cfg["variant"] == "excellence" and t["excellence"] is None:
                errors.append("'%s' is missing its Excellence value." % t["kpi_name"])
            elif pm_scale_error(cfg, t["method"], t, t["kpi_name"]):
                errors.append(pm_scale_error(cfg, t["method"], t, t["kpi_name"]))
    if errors:
        return False, errors, None
    return True, [], None


def _pm_setting_propose(db, u, ctx):
    """Validate and SUBMIT the whole scorecard for approval: flip every open line
    to 'proposed', (re)build its approver chain and clear any prior verdicts.
    All-or-nothing. Returns (ok, errors, warn) and does the writes itself, so the
    form route and the chat's JSON route share ONE validation+write authority.
    Caller must have confirmed ctx['editable']."""
    ok, errors, _w = _pm_setting_validate(ctx)
    if not ok:
        return False, errors, None
    mine = ctx["mine"]
    approver_ids = pm_setting_resolve_approvers(db, u)
    unrouted = 0
    for t in mine:
        keep = pm_kpi_matrix_keep(db, t, u)
        if keep and _pm_chair_delegate_barred(db, u["manager_id"], keep):   # the delegate never moderates the chair's reports
            keep = None
        chain = [keep] if keep else approver_ids
        unrouted += not chain
        db.execute("DELETE FROM pm_kpi_target_approvers WHERE kpi_target_id=?", (t["id"],))
        db.execute("DELETE FROM pm_kpi_setting_approvals WHERE kpi_target_id=?", (t["id"],))
        for seq, aid in enumerate(chain, start=1):
            db.execute("INSERT INTO pm_kpi_target_approvers(kpi_target_id, seq, approver_id) "
                       "VALUES (?,?,?)", (t["id"], seq, aid))
        db.execute("UPDATE pm_kpi_targets SET status='proposed', updated_at=datetime('now'), "
                   "updated_by=? WHERE id=?", (u["id"], t["id"]))
    db.commit()
    log_activity(db, u["id"], "pm_kpi_proposed",
                 "%s: proposed %d KPI(s)" % (ctx["period"]["name"], len(mine)))
    warn = None
    if unrouted:
        warn = ("Proposed, but no approver could be resolved for you -- Group People will assign one.")
        if _pm_chair_unmoderated(db, u["id"], u["manager_id"]):   # (2026-11-03) HR has nobody to assign: say what is true
            warn = ("Proposed, but nobody approves a scorecard for the Executive Chairman's direct reports while his "
                    "Moderate tick is off.")
    return True, [], warn


@app.route("/review/setting")
@login_required
def review_setting():
    """KPI Setting, as a conversation. The employee builds their scorecard by
    talking to the agent; the server validates every write. Same shell as the
    check-in chat, a different agent."""
    u = _review_guard()
    db = get_db()
    st = review_state(db, u)
    stage = next((x for x in st["stages"] if x["key"] == "agree"), None)
    if not stage and st.get("period") and not kpi_setting_runs(st["period"]) and cycle_module_on("pm", db):
        flash(_KPI_SETTING_ELSEWHERE, "info")   # an old link, outside an Early Year (2026-10-15)
        return redirect(url_for("review_home"))
    if not stage or stage["state"] == REVIEW_STATE_OFF:
        abort(404)
    # on the AI+ check-in this page is only for a scorecard still being built: once it is agreed or with the approver,
    # the check-in is where they belong (Chris, 2026-10-13, after a persona switch left the Employee on it with an
    # approved scorecard)
    if stage["state"] != REVIEW_STATE_OPEN and _review_unified_on(u):
        return redirect(url_for("review_home"))
    return render_template("review_setting.html", st=st, stage=stage,
                           manages=_review_manages_team(db, u),
                           agent_available=ai_draft.review_agent_available())


@app.route("/review/setting/chat/history")
@login_required
def review_setting_chat_history():
    """The stored setting-chat transcript, so it resumes on reload."""
    u = _review_guard()
    db = get_db()
    ov = _setting_overview(db, u)
    return jsonify(ok=True, messages=_setting_chat_history(db, u, active_cycle_id(db)),
                   overview=(ov["data"] if ov else None),
                   available=ai_draft.review_agent_available())


@app.route("/review/setting/chat", methods=["POST"])
@login_required
def review_setting_chat():
    """One KPI-setting agent turn. The model converses and proposes; the server
    runs every action through a validated tool. The model is never the source of
    truth, and it can never propose the set for approval (that is the human's
    Submit click, /review/setting/propose)."""
    u = _review_guard()
    db = get_db()
    cid = active_cycle_id(db)
    # Every exit carries an `overview` (see review_chat's _degraded): a degraded turn
    # must not wipe the pinned scorecard off the screen.
    def _degraded(say, **kw):
        ov = _setting_overview(db, u)
        return jsonify(ok=True, quick_replies=[], say=say,
                       overview=(ov["data"] if ov else None), **kw)

    if not ai_draft.review_agent_available():
        return _degraded("The setting assistant isn't switched on yet -- ask your admin "
                         "to enable it, and you can still use the setting page.", done=True)
    # a closed part (its window on the admin's Calendar): the page locks the box and a message that still arrives gets
    # the sentence -- no model call, stored nowhere (Chris, 2026-10-20: "after deadline no action can be done ... the chat
    # will be disabled, user can just read the past conversation")
    _wn = window_closed(db, "pm_setting", subject_id=u["id"])
    if _wn:
        return _degraded(_wn + " You can still look through it.", window_closed=True, window_note=_wn)
    msg = (request.form.get("message") or "").strip()[:1000]
    if msg:
        db.execute("INSERT INTO pm_setting_chat(subject_id, cycle_id, role, content) "
                   "VALUES (?,?,'user',?)", (u["id"], cid, msg))
        db.commit()
    history = _setting_chat_history(db, u, cid)
    ctx = _pm_setting_context(db, u)
    system = _setting_agent_system(db, u, ctx) if ctx else ""
    say, qr, steps, renders = "", [], 0, []
    while steps <= ai_draft.REVIEW_AGENT_MAX_TOOLS:
        steps += 1
        try:
            turn = ai_draft.review_agent(system, history)
            _screen_trace(db, u, turn, "employee")
        except ai_draft.AIDraftNotConfigured:
            return _degraded("The setting assistant isn't switched on yet.", done=True)
        except ai_draft.AIDraftError:
            return _degraded("Sorry -- I lost the thread there. Could you say that again?")
        say, qr, action = turn["say"], turn["quick_replies"], turn["action"]
        if not action:
            break
        result = _setting_run_tool(db, u, cid, action)
        # ANY card render is TERMINAL: one card per turn (show_library/show_scorecard/
        # prepare_propose), so a model can't stack duplicate cards (Chris saw five).
        if isinstance(result, dict) and result.get("render"):
            renders.append(result["render"])
            break
        if isinstance(result, dict) and result.get("ready"):
            break
        feed = {k: v for k, v in result.items() if k != "render"} if isinstance(result, dict) else result
        history.append({"role": "agent", "content": say or "(took an action)"})
        history.append({"role": "tool", "content": json.dumps(feed)[:400]})
        ctx = _pm_setting_context(db, u)
        system = _setting_agent_system(db, u, ctx) if ctx else ""
    # Never offer a bare number (a weight) as a one-tap chip: a tapped value would
    # set something the person did not choose. Keep named action chips.
    qr = [q for q in (qr or [])
          if not re.match(r"^\s*[-+]?[\d.,]+\s*%?\s*$", str(q))
          and not re.search(r"type it", str(q), re.I)]
    if say:
        db.execute("INSERT INTO pm_setting_chat"
                   "(subject_id, cycle_id, role, content, quick_replies, card) "
                   "VALUES (?,?,'agent',?,?,?)",
                   (u["id"], cid, say, json.dumps(qr) if qr else None,
                    json.dumps(renders) if renders else None))
        db.commit()
    ov = _setting_overview(db, u)
    st = review_state(db, u)
    return jsonify(ok=True, say=say, quick_replies=qr, renders=renders,
                   overview=(ov["data"] if ov else None),
                   rail_html=_setting_rail_html(st))


