@app.route("/review/setting/propose", methods=["POST"])
@login_required
def review_setting_propose():
    """The employee's SUBMIT: propose the whole scorecard for approval. The ONE
    propose path from the chat -- an explicit, owner-scoped human action from the
    confirm card, server-validated (the agent can never propose). Shares the
    validation+write with the setting page's own propose route (_pm_setting_propose)."""
    u = _review_guard()
    db = get_db()
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return jsonify(ok=False, error="There is no active performance period."), 400
    if not ctx["editable"]:
        return jsonify(ok=False, error=_pm_setting_shut_reason(ctx)), 400
    ok, errors, warn = _pm_setting_propose(db, u, ctx)
    if not ok:
        return jsonify(ok=False, error="; ".join(errors)), 400
    ov = _setting_overview(db, u)
    return jsonify(ok=True, proposed=True, warn=warn,
                   overview=(ov["data"] if ov else None))


# ---------------------------------------------------------------------------
# The conversational COMPETENCY (TM) agent. Same architecture as the KPI setting
# / check-in agents: the MODEL converses and proposes; these tools VALIDATE and
# perform every write, and only the employee's explicit Submit flips the
# assessment to the manager. Competency rating is BINARY -- Demonstrate ('yes') /
# Developing ('no') -- grouped by skill category; the set is admin-generated
# (tc_assignments), so the agent never adds/removes, it only collects one answer
# per competency + optional notes. All writes reuse the module's own paths.
# ---------------------------------------------------------------------------
def _tc_self_editable(u, assessment):
    """The competency self-assessment is editable while pending. A ZZ demo account
    bypasses the setup gates so a tester can exercise the chat without admin setup,
    but a SUBMITTED assessment still LOCKS (matching the KPI check-in) -- otherwise
    submit never locks on the demo and the agent keeps re-asking. Re-testing is via
    the demo Reset. is_demo_account is never true on production, nor for a real "ZZ" +
    digits Employee ID, so this branch never touches a live one."""
    if is_demo_account(u):
        return assessment is None or _row_get(assessment, "status") not in ("submitted", "reviewed")
    return tc_can_self_edit(assessment)


def _tc_context(db, u, create=False):
    """The competency assessment context the agent + widget read. `create=False`
    (the GET default) never inserts a row, so a read surface stays write-free; the
    chat POST passes create=True where a tool is about to write."""
    cid = active_cycle_id(db)
    assignments = tc_assignments_for(db, cid, u["id"])
    if not assignments:
        return None
    if create:
        assessment = tc_get_or_create_assessment(db, cid, u["id"])
    else:
        assessment = db.execute(
            "SELECT * FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
            (cid, u["id"])).fetchone()
    aid = assessment["id"] if assessment else None
    rows, groups = _tc_rows(db, cid, u["id"], aid)
    done, total = _tc_progress(db, cid, u["id"], aid)
    editable = _tc_self_editable(u, assessment)
    # SUBMITTED, with a competency Group People added since (2026-11-06): the card, the agent and the gates see ONLY the new
    # competencies, open for answers; the remark and every other answer are final and not shown as work
    added = {r["id"] for r in tc_added_open(db, u["id"], cid)} if assessment else set()
    added_only = bool(added)
    if added_only:
        rows = [r for r in rows if r["assignment_id"] in added]
        groups = [dict(g_, rows=[r for r in g_["rows"] if r["assignment_id"] in added]) for g_ in groups]
        groups = [g_ for g_ in groups if g_["rows"]]
        total = len(rows)
        done = sum(1 for r in rows if r.get("answer") in ("yes", "no"))
        editable = True
    return {"cid": cid, "assessment": assessment, "rows": rows, "groups": groups,
            "done": done, "total": total,
            "status": assessment["status"] if assessment else "pending",
            "editable": editable, "added_only": added_only}


def _tc_chat_history(db, u, cid):
    rows = db.execute(
        "SELECT role, content, quick_replies, card FROM tc_review_chat WHERE subject_id=? "
        "AND cycle_id=? ORDER BY id DESC LIMIT ?", (u["id"], cid, REVIEW_CHAT_MAX)).fetchall()
    out = []
    for r in reversed(rows):
        m = {"role": r["role"], "content": r["content"]}
        if r["quick_replies"]:
            try:
                m["quick_replies"] = json.loads(r["quick_replies"])
            except (ValueError, TypeError):
                pass
        if r["card"]:
            try:
                m["card"] = json.loads(r["card"])
            except (ValueError, TypeError):
                pass
        out.append(m)
    return out


TC_ANSWER_LABELS = {"yes": "Demonstrate", "no": "Developing"}


def _tc_comp_pages(groups):
    """The competency card's pages (Chris, 2026-10-21, canvas LNPTK3eL11qMtAJDFmitjt option A): ONE competency a page,
    its current level and its next level side by side. A page is a category's items with one title, in the category's
    order (current levels sort first, so a next level joins its competency's page). journey_chat.js's tcPagesOf builds
    the same pages and keys from the same groups; the queue panel lists them."""
    pages, by = [], {}
    for g in groups or []:
        for it in g.get("items") or []:
            k = "%s::%s" % (g.get("category") or "", it.get("title") or "")
            if k not in by:
                by[k] = {"key": k, "category": g.get("category") or "", "title": it.get("title") or "", "items": []}
                pages.append(by[k])
            by[k]["items"].append(it)
    return pages


def _tc_remark_rule(db, cid):
    """The competency card's remark rule for the page's live ticks: High at TC_BAND_HIGH_PCT of the maximum, on the cycle's own
    competency points (Demonstrate w_current / w_future, Developing w_dev_current / w_dev_future)."""
    p = points_for(db, cid, "tc")
    return {"high_pct": TC_BAND_HIGH_PCT, "w_current": p.dc, "w_future": p.dn,
            "w_dev_current": p.vc, "w_dev_future": p.vn}


def _competency_overview(db, u):
    """The competency widget: the assigned competencies grouped by category, each
    with its yes/no answer, plus 'X of N answered' and the assessment status. A live
    widget, rebuilt each turn. Returns None when nothing is assigned."""
    ctx = _tc_context(db, u, create=False)
    if ctx is None:
        return None
    groups = []
    for g in ctx["groups"]:
        items = []
        for r in g["rows"]:
            items.append({
                "assignment_id": r["assignment_id"], "title": r["title"],
                "level": r.get("level"), "is_future": bool(r.get("is_future")),
                "detail": r.get("proficiency_description") or "",
                # The ability items are a newline/bulleted TEXT blob per competency --
                # split into a clean list to show under each (informational; the rating
                # stays per competency).
                "ability_items": [ln.strip().lstrip("-").strip()
                                  for ln in (r.get("ability_items") or "").splitlines()
                                  if ln.strip()],
                "answer": r.get("answer"),
                "answer_label": TC_ANSWER_LABELS.get(r.get("answer")),
                "has_note": bool((r.get("remark") or "").strip()),
                # The per-competency remark text, so the confirm card + pop-out can head it
                # by the competency it is about (Chris, 2026-09-15).
                "note": (r.get("remark") or "").strip(),
            })
        groups.append({"category": g["name"], "items": items})
    # AI+ Learning's line (S12, board 4F): the same evidence, without the level
    _rk = {id(it): r.get("skill_id") for g, og in zip(ctx["groups"], groups) for r, it in zip(g["rows"], og["items"])}
    lms_review_attach(db, u, groups, _rk, False)
    # The FOCUS: the first still-unanswered competency -- the one the agent is on --
    # so the section widget can follow the conversation (the check-in's "current item"
    # idea). Falls back to the first group when everything is answered.
    focus_id, focus_cat = None, (groups[0]["category"] if groups else None)
    for g in groups:
        hit = next((it for it in g["items"] if it["answer"] not in ("yes", "no")), None)
        if hit:
            focus_id, focus_cat = hit["assignment_id"], g["category"]
            break
    return {"type": "competency_overview", "data": {
        "groups": groups, "answered": ctx["done"], "total": ctx["total"],
        "editable": ctx["editable"], "status": ctx["status"], "added_only": ctx["added_only"],
        "focus_assignment_id": focus_id, "focus_category": focus_cat,
        # _tc_self_band's rule, for the card's remark wording to follow the ticks before they're saved (Chris, 2026-10-22):
        # a Demonstrate earns the cycle's competency points (dc current, dn next), a Developing vc / vn, High at
        # TC_BAND_HIGH_PCT of the maximum. Never shown.
        "remark_rule": _tc_remark_rule(db, ctx["cid"]),
        # The remark note, so the confirm card can offer a View / Redraft pop-out
        # (the board widget ignores this key). Analogue of the KPI overview's overall_remark.
        "overall_remark": _competency_overall_note(db, u),
    }}


def _competency_rail_html(st):
    """The rail fragment for the competency chat, highlighting the competency stage."""
    stage = next((x for x in st["stages"] if x["key"] == "competency"), {"key": "competency"})
    return render_template("_review_rail.html", st=st, stage=stage)


def _competency_agent_system(db, u, ctx, journey=False):
    period = active_cycle(db)
    pname = period["name"] if period else "this period"
    first = welcome_identity(u).get("first_name") or "there"
    comps = []
    for g in ctx["groups"]:
        for r in g["rows"]:
            comps.append({
                "assignment_id": r["assignment_id"], "name": r["title"],
                "category": r.get("skill_category") or "Other",
                # NB: no is_future/"stretch" flag -- current/next/stretch are INTERNAL and
                # must never reach the user; the descriptor identifies/disambiguates instead.
                # The descriptor + ability items let the agent DESCRIBE the competency to
                # guide the Demonstrate/Developing judgement, not just name it.
                "descriptor": (r.get("proficiency_description") or "")[:400],
                "ability_items": [ln.strip().lstrip("-").strip()
                                  for ln in (r.get("ability_items") or "").splitlines()
                                  if ln.strip()][:5],
                "answered": r.get("answer") in ("yes", "no"),
                "answer": TC_ANSWER_LABELS.get(r.get("answer")),
            })
    _cid = ctx["cid"]
    _jg = _tc_justify_gate(db, u, _cid)
    _sb = _tc_self_band(db, u, _cid)
    _tojust = [{"name": b["title"], "stretch_assignment_id": b["stretch_assignment_id"],
                "has_justification": b["has_note"]} for b in _jg["both"]]
    parts = [
        "You are OneHR's competency-assessment assistant, helping %s complete their OWN "
        "technical competency self-assessment for %s. Sound like a sharp, friendly "
        "colleague -- warm, natural, specific. One competency at a time; keep each reply "
        "to a sentence or two." % (first, pname),
        "VOICE, this matters: never repeat a sentence you have already said; react to what "
        "they ACTUALLY said; vary your openers; don't gush. NEVER expose internal machinery "
        "-- no ids, no tool names. Refer to each competency by its NAME.",
        "THE TASK: for EACH competency, ask whether they DEMONSTRATE it (they show it about "
        "70% of the time or more) or are still DEVELOPING it. 'Developing' is a perfectly "
        "normal, honest answer -- never push them toward 'Demonstrate'. Call "
        "set_competency(assignment_id, answer) where answer is 'yes' (Demonstrate) or 'no' "
        "(Developing); offer 'Demonstrate' and 'Developing' as the quick_replies. They may "
        "optionally add a short note or example -- if they give one, pass it as the note. "
        "You do NOT set levels, weights or numbers, and you cannot add or remove "
        "competencies (the list is fixed by Group People).",
        "Their competencies (grouped by category), each with its descriptor and ability "
        "items:\n" + json.dumps(comps, ensure_ascii=False),
        "GUIDE, don't just name: when you invite them to mark a competency (or they ask "
        "about one), briefly say what it MEANS in your own words -- one short sentence from "
        "its descriptor plus an ability item or two -- so they can judge whether they "
        "demonstrate it, THEN ask Demonstrate or Developing. When you name a competency "
        "(in prose OR as a quick reply), write it as its NAME then a dash then its descriptor "
        "-- e.g. 'Production Planning - optimise production planning across lines and shifts' "
        "-- so it is clear which one you mean. Do NOT show raw level NUMBERS or ids -- those are "
        "machinery. NEVER say the words 'current level', 'stretch level', a band or a score to the "
        "person -- those are internal; when a competency needs confirming, frame it as 'you've rated "
        "yourself as fully demonstrating <competency>'. Keep it to a sentence or two.",
        ("THE FLOW -- THREE steps (Chris, 2026-09-24). STEP 1 -- EVALUATE: an answer goes in EITHER way, "
         "whichever they prefer (Chris, 2026-10-21): they mark Demonstrate or Developing for each competency on the "
         "card in the chat and click 'Save' (on the card's last page, under the remark box -- it saves the answers "
         "and the remark together), OR they tell you here ('I demonstrate production planning', 'the first section "
         "is all Developing', 'all Demonstrate except budgeting') and YOU record it with set_competency in THIS "
         "reply -- every competency they named, in one call (items) -- then say back in one short line what you "
         "marked. Never say you can't mark it for them, and never send them to the card for an answer they've "
         "already told you. Record only what THEY decided: if they're unsure, describe the competency and let "
         "them choose -- never pick an answer for them or invent one. Invite them to work through the sections, "
         "on the card or with you; if they ask about a competency, describe what it means. "
         "STEP 2 -- ONE REMARK (required, 50-100 words): once every competency is saved, ask for their remark on "
         "their strengths and the areas they're still developing (it goes into their development plan; a STAR tip "
         "helps). If they ask what they marked, list what they marked Demonstrate -- say 'fully demonstrated' where "
         "BOTH levels are Demonstrate -- with each one's description and ability items from the data above, then "
         "what they marked Developing, as candidate development goals / areas to strengthen in their remark. "
         + _REMARK_STEP_HOWTO + " To change an answer they ask for, use set_competency. A competency can appear "
         "twice (two levels -- the second entry is the higher one): when they name it without saying which, change "
         "the LOWER one if it is Developing, and the higher one only when they clearly mean it or the lower one is "
         "already Demonstrate; a first answer for a competency named without its level goes on the LOWER one (the "
         "first entry), and on both in one call (items) when they say they fully demonstrate it. Someone can "
         "demonstrate the NEXT level while still developing the current one, and that is theirs to say: when they "
         "clearly do, record the current level Developing and the next level Demonstrate with next_level: true. Say "
         "which description you changed. STEP 3 -- "
         "REVIEW + SUBMIT, from the card itself (ONE card -- there is NO separate final list): once every "
         "competency is answered and the remark is written, call prepare_submit{} -- it checks everything is in "
         "and brings their card below your reply; then say in ONE line they can tap 'Save & submit' on the "
         "card's last page (or tell you to confirm & submit -- the system then opens the same pop-up): "
         "a pop-up shows a short summary and 'once confirmed you will not be able to make changes', and ONLY their Confirm there submits it. Saving answers is NOT the same as "
         "finishing the competency assessment: it is finished only once submitted. Do NOT leave the "
         "competency assessment (go_to_stage / next) until they have EITHER submitted OR said they'd rather "
         "come back to it later; never force it. NEVER claim it is submitted yourself before it is. Refer "
         "to sections and competencies by their names, never by number."
         if journey else
         "THE FLOW: go ONE competency at a time, and work through a whole category (section) "
         "before moving to the next. After you record an answer, briefly confirm it and ask "
         "whether they want to add a quick example/note or move on -- e.g. \"You're marking "
         "Data Analysis as Demonstrate. Want to add a quick example, or shall we go to the "
         "next one?\" (offer 'Add an example' and 'Next' as quick_replies). "
         "If they want help wording a remark ('Draft with AI'), compose a short draft grounded "
         "ONLY in this competency, its descriptor and what they have actually told you -- NEVER "
         "invent a detail -- PROPOSE the draft IN YOUR MESSAGE and ask if it captures it; ONLY once "
         "they confirm they are happy, call draft_reflection(assignment_id, text) with the agreed "
         "wording: it SHOWS the draft as a card with a Save button. Do NOT claim it is saved -- they "
         "Save it, or tell you a change and you re-propose. A tapped chip ('Draft with "
         "AI' / 'Add an example') or a bare 'yes' is NOT the remark -- never store it. When they "
         "TYPE their own remark, PROPOSE the wording, confirm, then call "
         "draft_reflection(assignment_id, text) -- there is "
         "no direct-save tool; the card's Save is the only way a remark is written; "
         "draft_reflection(assignment_id) with no text shows a remark they already saved. "
         "When every "
         "competency in a section is answered, say so and move to the next section by NAME. "
         "Refer to sections and competencies by their names, never by number."),
        ('TOOLS for "action": set_competency{assignment_id, answer, note (optional), next_level (optional: true '
         'only when they named the NEXT level)} (several in ONE call: '
         'set_competency{items: [{assignment_id, answer, next_level}, ...]}); show_progress{}; '
         'save_remark{} (saves their last message, exactly as typed, as their overall remark); prepare_submit{}. '
         "If nothing is left to do, say so warmly and set action null."
         if journey else
         'TOOLS for "action": set_competency{assignment_id, answer, note (optional)}; '
         'set_overall_note{text}; '
         'draft_reflection{assignment_id, text (optional)}; show_to_justify{}; show_progress{}; '
         'prepare_submit{}. If nothing is left to '
         "do, say so warmly and set action null."),
        ("The competency list appears INLINE in the chat as you work, with each answer and "
         "an 'X of N answered' count. If they ask to see it, point them to it in the chat; "
         "do NOT re-list it in prose."
         if journey else
         "The competency list is ALWAYS PINNED at the top of the chat, with each answer and "
         "an 'X of N answered' count. If they ask to see it, point them to the top; do NOT "
         "list it in prose. Call show_progress{} only if they explicitly want it inline."),
        ("THE FINISH: when EVERY competency has an answer and the remark is written, call prepare_submit{} -- it "
         "checks it's all in and brings their card below your reply; they submit it with the card's Save & submit "
         "and the pop-up's Confirm. NEVER claim it is submitted yourself. If prepare_submit returns a list still to "
         "answer, help them finish those."
         if journey else
         "THE FINISH: when EVERY competency has an answer, call prepare_submit{} -- it shows "
         "the final list and a Submit button. NEVER claim it is submitted yourself; ONLY "
         "their Submit click sends it to their manager. If prepare_submit returns a list "
         "still to answer, help them finish those."),
    ]
    # The ONE overall remark is REQUIRED from everyone (Chris, 2026-09-24) -- about 100 words, like the KPI
    # check-in, covering BOTH strengths and development areas, because it is carried into the IDP AI draft.
    # Gated by _tc_remark_gate in prepare_submit and the /review submit.
    _rg = _tc_remark_gate(db, u, _cid)
    _open = [r["title"] for g in ctx["groups"] for r in g["rows"] if r.get("answer") not in ("yes", "no")]
    if ctx["editable"] and _open and len(_open) < len([1 for g in ctx["groups"] for r in g["rows"]]):
        parts.append(
            "STILL TO ANSWER (AUTHORITATIVE): %d competenc%s still without an answer -- %s. The card marks each in "
            "red. Tell them plainly which are still open and ask them to choose Demonstrate or Developing for each "
            "(on the card and Save, or by telling you). Do NOT ask for the remark or head for the final list until "
            "every competency is answered."
            % (len(_open), "y is" if len(_open) == 1 else "ies are", ", ".join(dict.fromkeys(_open))[:600])
            + (" BUT if their latest message IS their remark -- their own words about their strengths and the areas "
               "they're developing, not a question or a request -- SAVE IT NOW with save_remark{} (it can come before "
               "the answers; both the card's box and the chat work, Chris 2026-09-28), then say it's saved and name the "
               "competencies still open." if journey else ""))
    if _rg["required"] and ctx["editable"]:
        if _rg["written"]:
            parts.append(
                "OVERALL REMARK (AUTHORITATIVE): written (in the remark box on their card, or sent here) -- never ask "
                "for it again; the next step is " + ("submitting from the card (prepare_submit brings it; they tap "
                                                     "Save & submit)" if journey else "the final list (prepare_submit)")
                + " once every competency is answered. "
                "If they want to redraft it, show it, give one or two specific tips -- what to ADD from their own "
                "story (an example of a strength they named; an area they're still developing, naming the "
                "competencies they rated Developing), never wording you write for them -- and save the new one with "
                + ("save_remark" if journey else "set_overall_note")
                + " when they send it." + _TC_OWN_STORY_RULE + " Their current remark: "
                + _competency_overall_note(db, u)[:900])
        else:
            parts.append(
                "OVERALL REMARK (AUTHORITATIVE): REQUIRED from everyone -- what is saved is what they typed, or a draft "
                "they said yes to "
                + ("(save_remark stores their message as typed, or the draft you showed and they approved)"
                   if journey else "(set_overall_note saves their wording, or the draft you showed and they approved)")
                + ". Never call it optional or offer to skip it." + (_REMARK_SAVE_NOW if journey else "")
                + _TC_OWN_STORY_RULE)
    if not ctx["editable"]:
        parts.append(
            "IMPORTANT: this assessment is already submitted and not editable now -- "
            "explain that warmly and do not try to change anything.")
    if ctx.get("added_only"):   # submitted, and Group People added a competency since (2026-11-06): fixed words
        _nn = [r["title"] for g in ctx["groups"] for r in g["rows"]]
        parts.append(
            "IMPORTANT -- their self-assessment was SUBMITTED, and Group People has since added %s for them: %s. ONLY %s "
            "open for them (the list above is just %s). Say plainly that a new competency was added for them. Ask "
            "Demonstrate or Developing for %s and record it with set_competency; when %s answered, call "
            "prepare_submit{} so they can tap Save & submit. Their other answers, their overall remark and their "
            "submission are FINAL: never change them, never ask for the remark again, and never offer to reopen or redo "
            "anything. NEVER claim it is submitted yourself."
            % ("a new competency" if len(_nn) == 1 else "%d new competencies" % len(_nn),
               ", ".join(dict.fromkeys(_nn))[:400], "it is" if len(_nn) == 1 else "those are",
               "the new one" if len(_nn) == 1 else "the new ones", "it" if len(_nn) == 1 else "each",
               "it is" if len(_nn) == 1 else "all are"))
    parts.append(_AGENT_SCOPE_GUARD)
    return "\n\n".join(parts)


# --- Competency tools: each fn(db, u, cid, args), validates editability ------
_TC_ANSWER_MAP = {"yes": "yes", "demonstrate": "yes", "demonstrated": "yes",
                  "no": "no", "developing": "no", "develop": "no"}

# UI-intent phrases (tapped chips) that must never be stored as a remark/example --
# passed to _reply_is_stub alongside the shared affirmation set. Short intents ("skip",
# "next", "done") are already caught by the length check.
_COMPETENCY_NOTE_STUBS = {"add example", "add an example", "add a note", "add note",
                          "add growth example", "add a growth example", "add strength example",
                          "prepare final submission", "show competency list", "show the list",
                          "i m done", "no example", "no thanks", "nothing to add",
                          "type example", "draft with ai", "draft it", "draft it for me",
                          "help me draft"}


def _tc_tool_set_competency(db, u, cid, args):
    _w = window_closed(db, "tc_self")
    if _w:
        return {"ok": False, "error": _w}
    assessment = tc_get_or_create_assessment(db, cid, u["id"])
    try:
        _aid = int(args.get("assignment_id"))
    except (TypeError, ValueError):
        _aid = None
    # submitted: only a competency Group People added since is open (tc_row_open); every other row stays refused
    if not _tc_self_editable(u, assessment) and not tc_row_open(db, u["id"], cid, _aid):
        return {"ok": False, "error": "your assessment is already submitted"}
    try:
        aid = int(args.get("assignment_id"))
    except (TypeError, ValueError):
        return {"ok": False, "error": "need an assignment_id"}
    row = db.execute(
        "SELECT a.id, s.title FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
        "WHERE a.id=? AND a.subject_id=? AND a.cycle_id=?", (aid, u["id"], cid)).fetchone()
    if not row:
        return {"ok": False, "error": "that competency is not on your list"}
    ans = _TC_ANSWER_MAP.get((args.get("answer") or "").strip().lower())
    if ans not in ("yes", "no"):
        return {"ok": False, "error": "answer must be Demonstrate (yes) or Developing (no)"}
    # Any combination of a competency's two levels is the person's to give, the next level Demonstrate over a
    # Developing current one included (Chris, 2026-10-21: "they might think they have the future skill but lack on
    # current"). This writer is the card's Save too, so a level rule here refused the card's answers; the agents'
    # guard against picking the wrong level is _tc_agent_set_competency.
    note = (args.get("note") or "").strip() or None
    # A tapped chip or bare "yes" ("Add example") is not a real note -- drop it but
    # still record the Demonstrate/Developing answer.
    if note and _reply_is_stub(note, _COMPETENCY_NOTE_STUBS):
        note = None
    _t, _serr = _store_text(note or "")
    if _serr:
        return {"ok": False, "error": _serr}
    # COALESCE the remark (unlike technical_autosave) so re-answering a competency
    # never wipes a note the person gave earlier.
    db.execute(
        "INSERT INTO tc_scores(assessment_id, assignment_id, answer, remark) VALUES (?,?,?,?) "
        "ON CONFLICT(assessment_id, assignment_id) DO UPDATE SET "
        "  answer=COALESCE(excluded.answer, tc_scores.answer), "
        "  remark=COALESCE(excluded.remark, tc_scores.remark), updated_at=datetime('now')",
        (assessment["id"], aid, ans, note))
    db.commit()
    done, total = _tc_progress(db, cid, u["id"], assessment["id"])
    return {"ok": True, "competency": row["title"],
            "answer": TC_ANSWER_LABELS[ans], "answered": done, "total": total}


def _tc_agent_set_competency(db, u, cid, args):
    """set_competency as the AGENTS call it (the competency chat and the AI+ journey). The model picks the wrong level:
    told "change Production Planning to demonstrate" it changed the higher level 6/6 (2026-09-25), and "I demonstrate
    Sales Target Achievement" marked the higher one once in three (Luna, 2026-10-21). So a next level's Demonstrate
    while its current level isn't Demonstrate goes through only with next_level=true, the agent's word that the person
    named the NEXT level (Chris, 2026-10-21: the next level Demonstrate over a Developing current one is theirs to
    give). Otherwise the refusal names the current level to record instead. The card's Save is never held back."""
    if _TC_ANSWER_MAP.get((args.get("answer") or "").strip().lower()) == "yes" \
            and str(args.get("next_level", "")).strip().lower() not in ("true", "1", "yes"):
        try:
            aid = int(args.get("assignment_id"))
        except (TypeError, ValueError):
            aid = None
        if aid is not None:
            ast = db.execute("SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                             (cid, u["id"])).fetchone()
            # levels pair by title + category, as the gate does; a read only, so a closed window still says why
            lo = db.execute(
                "SELECT lo.id, s.title, lo_s.proficiency_description AS lo_desc, sc.answer AS lo_ans "
                "FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
                "JOIN tc_skills lo_s ON lo_s.title=s.title "
                "AND COALESCE(lo_s.skill_category,'')=COALESCE(s.skill_category,'') "
                "JOIN tc_assignments lo ON lo.skill_id=lo_s.id AND lo.subject_id=a.subject_id "
                "AND lo.cycle_id=a.cycle_id AND lo.is_future=0 "
                "LEFT JOIN tc_scores sc ON sc.assignment_id=lo.id AND sc.assessment_id=? "
                "WHERE a.id=? AND a.subject_id=? AND a.cycle_id=? AND a.is_future=1",
                (ast["id"] if ast else -1, aid, u["id"], cid)).fetchone()
            if lo and lo["lo_ans"] != "yes":
                return {"ok": False, "error": (
                    "That is the NEXT level of %s, and its current level (%s, assignment_id %d) is %s. A competency "
                    "named without its level means the current one: record that instead. Only if they clearly said "
                    "they demonstrate the NEXT level (say, while still developing the current one), call again with "
                    "next_level=true. If they said they fully demonstrate it, record both in one call (items). "
                    "Nothing was changed." % (
                        lo["title"], (lo["lo_desc"] or "").strip()[:120] or "the first level", lo["id"],
                        "Developing" if lo["lo_ans"] == "no" else "not answered yet"))}
    # the note is the person's words, checked by _person_text_guard in the loop: handed on as given
    return _tc_tool_set_competency(db, u, cid, dict(args, note=args.get("note")))


def _tc_tool_set_overall_note(db, u, cid, args):
    _w = window_closed(db, "tc_self")
    if _w:
        return {"ok": False, "error": _w}
    assessment = tc_get_or_create_assessment(db, cid, u["id"])
    if not _tc_self_editable(u, assessment):
        return {"ok": False, "error": "your assessment is already submitted"}
    text = (args.get("text") or "").strip()
    if not text:
        return {"ok": False, "error": "need the note text"}
    # A tapped chip or bare agreement ("Add example", "yes") is not the remark --
    # refuse it and make the model ask for the person's actual words, not thank+advance.
    if _reply_is_stub(text, _COMPETENCY_NOTE_STUBS):
        return {"ok": False,
                "error": "That is a button tap or agreement, not the remark itself. Ask them "
                         "to type one sentence in their own words about what they did well (or what "
                         "they are working on), then call set_overall_note again with THAT text. "
                         "Do not say you have saved anything yet."}
    if _looks_like_placeholder(text):
        return {"ok": False,
                "error": "That looks like a template or placeholder, not their remark. Ask them for it in "
                         "their own words, then call set_overall_note with THAT text."}
    # Like the KPI check-in's remark (Chris, 2026-09-24): about 100 words, a GENEROUS ceiling -- an essay is
    # refused (asked to shorten), never silently trimmed mid-sentence.
    if len(text.split()) > _REVIEW_REMARK_MAX_WORDS:
        return {"ok": False,
                "error": "That runs to %d words -- keep the overall remark to around 100 (a short paragraph "
                         "on their strengths and the areas they're still developing). Help them shorten it, "
                         "then save again." % len(text.split())}
    _t, _serr = _store_text(text)
    if _serr:
        return {"ok": False, "error": _serr}
    _tc_write_overall_note(db, assessment["id"], text)
    db.commit()
    return {"ok": True, "saved": "overall note"}


def _tc_write_overall_note(db, assessment_id, text):
    """THE write of the competency overall remark (tc_assessments.overall_remark): the chat (set_overall_note / the
    journey's save_remark) and the remark box on the competency card (review_competency_remark) both come here.
    Empty text clears it (the submit gate then asks for it again). The caller commits."""
    db.execute("UPDATE tc_assessments SET overall_remark=? WHERE id=?",
               ((text or "").strip()[:2000] or None, assessment_id))
    _own = db.execute("SELECT subject_id, cycle_id FROM tc_assessments WHERE id=?", (assessment_id,)).fetchone()
    if _own:   # whoever wrote it, the pasted mark follows the text
        _paste_mark_recount(db, _own["subject_id"], _own["cycle_id"], "competency", None, (text or "").strip()[:2000])


def _tc_save_competency_note(db, u, cid, aid, text):
    """Write (or, on empty text, CLEAR) one competency's remark (tc_scores.remark). THE one
    write path, shared by the set_competency_note tool and the draft card's Save button, so the
    conversational and the deterministic-Save paths can never diverge. Own competency, editable,
    and it must be answered (the remark hangs off its score row). Returns (ok, title_or_error)."""
    _w = window_closed(db, "tc_self")
    if _w:
        return False, _w
    assessment = tc_get_or_create_assessment(db, cid, u["id"])
    try:
        aid = int(aid)
    except (TypeError, ValueError):
        aid = None
    # submitted: only a competency Group People added since is open (tc_row_open)
    if not _tc_self_editable(u, assessment) and not tc_row_open(db, u["id"], cid, aid):
        return False, "your assessment is already submitted"
    if aid is None:
        return False, "need an assignment_id"
    row = db.execute(
        "SELECT a.id, s.title FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
        "WHERE a.id=? AND a.subject_id=? AND a.cycle_id=?", (aid, u["id"], cid)).fetchone()
    if not row:
        return False, "that competency is not on your list"
    sc = db.execute(
        "SELECT sc.id FROM tc_scores sc JOIN tc_assignments a ON a.id=sc.assignment_id "
        "WHERE sc.assessment_id=? AND a.id=?", (assessment["id"], aid)).fetchone()
    if not sc:
        return False, "mark " + row["title"] + " as Demonstrate or Developing first"
    clean = (text or "").strip()[:2000]
    _t, _serr = _store_text(clean)
    if _serr:
        return False, _serr
    db.execute("UPDATE tc_scores SET remark=?, updated_at=datetime('now') "
               "WHERE assessment_id=? AND assignment_id=?", (clean or None, assessment["id"], aid))
    db.commit()
    return True, row["title"]


def _tc_tool_set_competency_note(db, u, cid, args):
    """File a remark AGAINST a specific competency (tc_scores.remark) -- the strength /
    growth remark the agent cited by name. Distinct from set_overall_note (a general
    remark). Routes through _tc_save_competency_note (the same path the draft card's Save
    uses) after a stub guard (the model must never store a button tap as the remark)."""
    text = (args.get("text") or "").strip()
    if not text:
        return {"ok": False, "error": "need the remark text"}
    aid = args.get("assignment_id")
    if _reply_is_stub(text, _COMPETENCY_NOTE_STUBS):
        nm = db.execute("SELECT s.title FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
                        "WHERE a.id=? AND a.subject_id=? AND a.cycle_id=?",
                        (aid, u["id"], cid)).fetchone()
        return {"ok": False,
                "error": "That is a button tap or agreement, not the remark itself. Ask them "
                         "to type one sentence in their own words about " +
                         ((nm["title"] if nm else None) or "this competency") + ", then call "
                         "set_competency_note again with THAT text. Do not say you have saved "
                         "anything yet."}
    ok, res = _tc_save_competency_note(db, u, cid, aid, text)
    if not ok:
        return {"ok": False, "error": res}
    return {"ok": True, "competency": res, "saved": "remark"}


# The competency self-band cutoffs (share of the weighted max). Tunable; a person who claims the
# STRETCH level across the board trends High, one meeting only current levels trends Mid/Low.
TC_BAND_HIGH_PCT = 75.0
TC_BAND_MID_PCT = 40.0


def _tc_self_band(db, u, cid):
    """The person's SELF competency band (Low/Mid/High) from the weighted point metric -- Demonstrate
    at the CURRENT level scores dc, at the STRETCH level dn, Developing vc / vn (the cycle's competency points, by default 1.0 / 1.5 / 0 / 0; tc_score, source='self'). Standalone:
    competency points only, separate from the combined 360+tech potential band. It scales how hard
    the agent coaches the justification, and dropping a stretch level lowers it (right-sizing).
    Returns {band, score, max, pct}; band is None when nothing is assessed yet."""
    a = db.execute("SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=?",
                   (cid, u["id"])).fetchone()
    if not a:
        return {"band": None, "score": 0.0, "max": 0.0, "pct": 0.0}
    score, mx = tc_score(db, a["id"], "self")
    if score is None:                       # nothing answered yet
        return {"band": None, "score": 0.0, "max": mx or 0.0, "pct": 0.0}
    pct = (score / mx * 100.0) if mx else 0.0
    band = "High" if pct >= TC_BAND_HIGH_PCT else ("Mid" if pct >= TC_BAND_MID_PCT else "Low")
    return {"band": band, "score": score, "max": mx, "pct": pct}


def _tc_justify_gate(db, u, cid):
    """Which competencies need a justification (Chris, 2026-09-20, replacing the >80% rule): those
    where BOTH the current (is_future=0) AND the stretch (is_future=1) level are answered Demonstrate
    -- claiming you already show the level you are growing INTO is a High-potential claim that must be
    defensible. The justification is a remark on the STRETCH assignment (the strong half). A ceiling
    competency (current only), or a current-Demonstrate + stretch-Developing pair, does NOT trigger.
    Returns {both:[{title, stretch_assignment_id, has_note}], missing:[title,...]}."""
    ctx = _tc_context(db, u, create=False)
    if ctx is None:
        return {"both": [], "missing": []}
    by_comp = {}
    for r in ctx["rows"]:
        key = (r.get("skill_category") or "", r["title"])
        by_comp.setdefault(key, {})[bool(r.get("is_future"))] = r
    both, missing = [], []
    for (_cat, title), lv in by_comp.items():
        cur, fut = lv.get(False), lv.get(True)
        if cur and fut and cur.get("answer") == "yes" and fut.get("answer") == "yes":
            has = bool((fut.get("remark") or "").strip())

            def _abil(row):
                return [ln.strip().lstrip("-").strip()
                        for ln in (row.get("ability_items") or "").splitlines() if ln.strip()]
            both.append({"title": title, "stretch_assignment_id": fut["assignment_id"], "has_note": has,
                         # BOTH levels' descriptors + ability items, so the card shows the person the two
                         # levels they rated as fully demonstrated, side by side (Chris, 2026-09-21). No
                         # "current/stretch" label reaches the user; `_lo` is the lower level (left
                         # column), `descriptor` the higher (right). Same split as _competency_overview.
                         "descriptor": (fut.get("proficiency_description") or "").strip(),
                         "ability_items": _abil(fut),
                         "descriptor_lo": (cur.get("proficiency_description") or "").strip(),
                         "ability_items_lo": _abil(cur)})
            if not has:
                missing.append(title)
    return {"both": both, "missing": missing}


def _tc_remark_gate(db, u, cid):
    """The competency self-assessment's ONE overall remark (tc_assessments.overall_remark) is REQUIRED
    from everyone before submit -- about 100 words, like the KPI check-in's remark (Chris, 2026-09-24),
    covering BOTH their strengths and the areas they are still developing, because it is carried into
    the IDP AI draft and their manager reads it with the ratings. Read by prepare_submit, the /review
    submit (_tc_do_submit), the prompt, the navigator and the chip hygiene. Returns {required, written,
    all_answered, all_developing}; required is False only when nothing is assigned."""
    ctx = _tc_context(db, u, create=False)
    if ctx is None or not ctx["rows"]:
        return {"required": False, "written": False, "all_answered": False, "all_developing": False}
    answers = [r.get("answer") for r in ctx["rows"]]
    if ctx["added_only"]:   # competencies added after they submitted: their remark was submitted with the rest, not asked again
        return {"required": False, "written": True, "all_answered": all(a_ in ("yes", "no") for a_ in answers),
                "all_developing": False}
    return {"required": True, "written": bool(_competency_overall_note(db, u).strip()),
            "all_answered": all(a_ in ("yes", "no") for a_ in answers),
            "all_developing": all(a_ == "no" for a_ in answers)}


# At the REMARK step -- every competency answered, no both-levels reason outstanding, the required overall
# remark not written yet (Chris, 2026-09-24): chips that skip it, go to submit, or only send "Type ..." are dead
# ends / wrong turns, and a reply that calls the remark optional or heads for the final card (gpt-5-mini did,
# 1/5 on staging) gets the fixed line instead.
_TC_REMARK_AHEAD_CHIP_RE = re.compile(r"\b(skip|prepare|submit\w*|optional|final card)\b|^\s*type\b", re.I)
_TC_REMARK_AHEAD_SAY_RE = re.compile(r"\boptional\b|\bskip\b|\bprepare\b|\bfinal (submit )?card\b", re.I)
_TC_REMARK_REQUIRED_LINE = (
    "Before you submit, please add your overall remark -- about 100 words in your own words on your "
    "strengths and the areas you're still developing. Your manager reads it with your ratings, and it's "
    "carried into your development plan.")


# A draft the agent QUOTES for approval ("does this capture it: '...'"), long enough to be the remark.
# (Chris, 2026-11-01) What a competency draft may and may not do, for the system prompt and the help steers.
_TC_OWN_STORY_RULE = (" A draft you write may be fuller than what they wrote and may explain the points they made -- what a "
                      "strength looks like in practice, why it matters -- but it never adds an example, event, person, "
                      "figure or date they did not give, nor a strength or development area they never mentioned. When "
                      "they ask you to write or elaborate it and have given you anything to work from (the server answers "
                      "the too-thin case itself), write the draft in that reply -- never a question instead of it; if more "
                      "would help, one optional \"if you'd like, add ...\" line AFTER the draft.")
# first person: I / I'm / I've / I'd (the "I" case-sensitive, so a stray "i" or "Ii" is not one), my, me
_TC_FIRST_PERSON_RE = re.compile(r"\bI(?:['\u2019](?:m|ve|d))?\b|(?i:\b(?:my|me)\b)")
_TC_QUOTED_DRAFT_RE = re.compile(r"[\"\u201c]([^\"\u201d]{60,})[\"\u201d]|(?<![A-Za-z])['\u2018]([^'\u2019]{60,})['\u2019](?![A-Za-z])")
# THE OWN-STORY LINE (Chris, 2026-11-01: "the ai agent should indicate what needs to be fixed or added from the user
# own story"). The competency remark is their own words only, so a draft that adds wording is never shown and a "Yes,
# save it" on one saves nothing -- but a bare "needs your own words" left them looping (staging screenshot: a saved
# 19-word remark, "make it longer", three padded drafts, three refusals). So the server says what was FIXED (the words
# that weren't theirs) and what to ADD from their own story: an example of a strength, and an area still developing,
# naming the competencies they rated Developing. One function, used by the backstop (a reply that quotes a bad draft)
# and by a refused "Yes, save it".
_TC_DEV_CUE_RE = re.compile(r"develop|improv|learn|work on|better at|grow|weak|still", re.I)
_RG_NOVEL_RE = re.compile(r"things they did not say: ([^;]+?)(?:;|\.|$)")


def _remark_novel_words(err):
    """The words a strict grounding refusal says they never used ([] when it was about figures only)."""
    m = _RG_NOVEL_RE.search(err or "")
    return [w.strip() for w in m.group(1).split(",") if w.strip()] if m else []


def _tc_developing_titles(db, u):
    """The competencies they rated Developing (answer 'no' on a row; _tc_developing), in card order: the level they
    hold today first, then the ones they're growing into."""
    d = _tc_developing(db, u)
    return list(dict.fromkeys(d["now"] + d["next"]))


def _tc_own_words_said(db, u, cid, history):
    """Everything they've said about their remark, for the development-cue check: the remark saved now plus their
    own messages (a help-menu prompt counts only for what they typed in its brackets -- its pre-set words say
    "areas I'm still developing" whatever they wrote)."""
    out = [_competency_overall_note(db, u)]
    for m in (history or []):
        if m.get("role") != "user":
            continue
        c = m.get("content") or ""
        hi = _remark_help_intent(c)
        out.append(((hi.get("want") or "") + " " + (hi.get("text") or "")) if hi else c)
    return " ".join(out)


def _tc_remark_own_story_line(db, u, cid, novel_words, history=None):
    """The honest path for the competency remark (Chris, 2026-11-01), all in the chat: a draft was not made because it
    would have added details they never gave (the figures or names it added, up to 4), so their remark stays as it is --
    then the one or two pieces still missing: an example of a strength (what happened, what they did) and, when they have
    competencies rated Developing and say nothing of a development area yet, that area by title (up to 3), what's getting
    in the way and what would help -- and that the fuller version follows straight away. No quotes and no "save" wording
    (so no approve chip)."""
    words = [w for w in (novel_words or []) if w][:4]
    said = _tc_own_words_said(db, u, cid, history)
    dev = _tc_developing_titles(db, u)
    covered = bool(_TC_DEV_CUE_RE.search(said)) or any(t.lower() in said.lower() for t in dev)
    fixed = ("I couldn't make that fuller without adding details you haven't given%s, so I've left your remark as it is."
             % ((" (" + ", ".join(words) + ")") if words else ""))
    add = ["an example of a strength you've named -- what happened and what you did"]
    if not covered:
        names = dev[:3]
        if names:
            listed = names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]
            add.append("an area you're still developing -- you rated %s as Developing, so say which one, what's "
                       "getting in the way and what would help" % listed)
        else:
            add.append("an area you're still developing, what's getting in the way and what would help")
    return (fixed + " Tell me here, from your own story: " + "; and ".join(add) + ". I'll write the fuller version "
            "straight away, from that and what you've already written.")


# COMPLETE FIRST (Chris, 2026-09-25): saving with competencies still unanswered, the agent went on to ask for the
# remark. While any competency is open, a reply that heads for the remark / the final list -- or the Save follow-up
# itself -- is replaced by a fixed line naming what's still open; the journey then brings the card to the reply,
# opened on the first unfinished section with those rows marked in red (like the 360).
_TC_AHEAD_OF_ANSWERS_RE = re.compile(r"\bremark\b|100[- ]?words|\bstrengths?\b.{0,40}\bdevelop|\bsubmit\w*|"
                                     r"\bfinal (list|card)\b|\bstep 2\b", re.I)
_TC_AHEAD_OF_ANSWERS_CHIP_RE = re.compile(r"\b(remark|write|writ\w+|submit\w*|final|later|skip)\b", re.I)


def _tc_unanswered(db, u):
    """The competencies still without an answer (titles, in board order), or [] (also when not editable)."""
    ctx = _tc_context(db, u, create=False)
    if not ctx or not ctx.get("editable"):
        return []
    return [r["title"] for g in ctx["groups"] for r in g["rows"] if r.get("answer") not in ("yes", "no")]


def _tc_incomplete_line(open_titles, remark_in=False):
    """What's still open on the competency card. `remark_in`: their remark is already saved (on the card or in the
    chat -- 2026-09-28, it can come first), so the line says so instead of "Before your remark"."""
    names = []
    for t in open_titles:
        if t not in names:
            names.append(t)
    n = len(open_titles)
    shown = names[:4]
    listed = (", ".join(shown[:-1]) + " and " + shown[-1]) if len(shown) > 1 else (shown[0] if shown else "")
    if len(names) > 4:
        listed += " and %d more" % (len(names) - 4)
    lead = ("Your remark is saved. Next, %s still to answer: %s." if remark_in
            else "Before your remark, %s still to answer: %s.")
    return ((lead + " %s marked in red on the card below -- choose Demonstrate or Developing for %s and Save.") % (
                "one competency is" if n == 1 else "%d competencies are" % n, listed,
                "It's" if n == 1 else "They're", "it" if n == 1 else "each"))


def _tc_complete_first(db, u, cid, say, qr, msg=None):
    """While any competency is unanswered, the reply never asks for the remark or heads for the final list: on the
    Save follow-up, or when the model reached ahead, it becomes the fixed line naming what's open, and chips that
    write / submit / put it off are dropped. Returns (say, qr, open_titles) -- open_titles non-empty only when the
    line was used (the journey then brings the card to the reply)."""
    open_titles = _tc_unanswered(db, u)
    if not open_titles:
        return say, qr, []
    # nothing about the remark / the final list while one is open; the rest of the chips stay mid-walk
    qr = [q for q in (qr or []) if not re.search(r"\b(remark|submit\w*|final)\b", str(q), re.I)]
    if (not say or re.search(r"\bsaved my competency answers\b", msg or "", re.I)
            or _TC_AHEAD_OF_ANSWERS_RE.search(say)):
        return (_tc_incomplete_line(open_titles, remark_in=bool(_competency_overall_note(db, u).strip())),
                [q for q in qr if not _TC_AHEAD_OF_ANSWERS_CHIP_RE.search(str(q))], open_titles)
    return say, qr, []


def _tc_remark_backstop(db, u, cid, say, qr, history=None, msg=None):
    """The competency STEP-2 backstop (Chris, 2026-09-24: ONE question, answered once). While the remark is
    the live step -- every competency answered, the required remark not written -- the reply IS the one
    question on the turn the step arrives (the Save turn, a nav tap, a turn about the remark) or whenever the
    model reached for STAR coaching, a draft, 'optional' or the final card; otherwise a reply that doesn't
    mention the remark gets the question appended. Chips that skip, submit or only send "Type ..." are dropped.
    A draft the agent QUOTES for approval that isn't the person's own words is never shown -- at ANY time, the remark
    already written or not (Chris, 2026-11-01: a padded draft was offered over a saved 19-word remark): it becomes the
    own-story line, what was not theirs and what to add (_tc_remark_own_story_line). Returns (say, qr)."""
    rg = _tc_remark_gate(db, u, cid)
    if not rg["required"]:
        return say, qr
    live = rg["all_answered"] and not rg["written"]   # the remark is the live step: the rest of the backstop
    if live:
        q = _tc_remark_question(db, u, cid)
        qr = _remark_step_chips(qr)
    if say and history is not None:
        # the SAME check _remark_draft_ok uses on their "yes" (_ai_draft_check: no figure or name nobody gave, within the
        # ceiling) -- a safety net behind _ai_draft_gate, which already ran in the journey turn
        # Off the live step only a first-person quote in a remark conversation is an overall-remark draft: a quoted
        # descriptor or a per-competency reason (a different field) is left alone (Chris, 2026-11-01)
        _scope = live or bool(_remark_help_episode(history)) or bool(re.search(r"remark", say, re.I))
        for m in _TC_QUOTED_DRAFT_RE.finditer(say):
            _q = m.group(1) or m.group(2) or ""
            if not live and not (_scope and _TC_FIRST_PERSON_RE.search(_q)):
                continue
            _r, _items, _k = _ai_draft_problem(db, u, cid, "competency", None, history, _q)
            if _r:
                # a draft with details they never gave is never shown -- say what to add, in the chat; a "Yes, save it"
                # chip would approve what they can no longer see
                return (_ai_refusal_line(db, u, cid, "competency", history, _k, _items),
                        [q_ for q_ in (qr or []) if not _RG_APPROVE_RE.search(str(q_))])
    if not live:
        return say, qr
    # the agent's reply stands (2026-09-25); a sentence calling the remark optional or heading for the final card
    # goes, and the question (first time) or a one-line reminder is added
    if say and _TC_REMARK_AHEAD_SAY_RE.search(say):
        say = " ".join(x for x in re.split(r"(?<=[.!?])\s+", say) if not _TC_REMARK_AHEAD_SAY_RE.search(x)).strip()
    return _remark_followup(db, u, cid, "competency", say, q, history=history), qr


def _tc_tool_show_to_justify(db, u, cid, args):
    """Render the competencies that need a justification (both levels Demonstrated) + which still
    lack a reason -- so the agent SHOWS the list (deterministic card) rather than narrating it. The
    self-band is deliberately NOT sent to the card: the person must not see how the score is
    computed (it invites gaming); the card reads as advice to confirm they really are at what they
    self-rated (Chris, 2026-09-21). Each item carries the level's descriptor so they see what they
    rated."""
    gate = _tc_justify_gate(db, u, cid)
    return {"ok": True, "displayed": "to_justify",
            "render": {"type": "competency_to_justify", "data": {
                "items": gate["both"], "missing": gate["missing"]}}}


def _tc_tool_draft_reflection(db, u, cid, args):
    """Show a competency remark as a CARD, never narrated: with `text` (the agent's composed
    draft) it proposes it with a Save button; with no `text` it shows the already-SAVED remark
    (fixing 'Read saved remark'). Writes nothing -- the card's Save persists via
    /review/competency/note. The fix for the agent claiming 'here's the draft'/'saved' while the
    text never actually appeared."""
    try:
        aid = int(args.get("assignment_id"))
    except (TypeError, ValueError):
        return {"ok": False, "error": "need an assignment_id"}
    row = db.execute(
        "SELECT a.id, s.title FROM tc_assignments a JOIN tc_skills s ON s.id=a.skill_id "
        "WHERE a.id=? AND a.subject_id=? AND a.cycle_id=?", (aid, u["id"], cid)).fetchone()
    if not row:
        return {"ok": False, "error": "that competency is not on your list"}
    text = (args.get("text") or "").strip()
    if text and _reply_is_stub(text, _COMPETENCY_NOTE_STUBS):
        return {"ok": False,
                "error": "That is a button tap, not a draft. Compose one real sentence about " +
                         row["title"] + " and call draft_reflection again with it as `text`."}
    if text and _looks_like_placeholder(text):
        return {"ok": False,
                "error": "That looks like a template or placeholder, not the remark. The card is NOT "
                         "a fill-in box -- its exact text becomes the record on Save. Ask them in "
                         "their own words about " + row["title"] + ", then call draft_reflection "
                         "again with THAT as `text`. Do not propose a card until you have their "
                         "actual words, and do not say anything is saved."}
    is_draft = bool(text)
    if not text:
        assessment = tc_get_or_create_assessment(db, cid, u["id"])
        sc = db.execute("SELECT sc.remark FROM tc_scores sc JOIN tc_assignments a ON a.id=sc.assignment_id "
                        "WHERE sc.assessment_id=? AND a.id=?", (assessment["id"], aid)).fetchone()
        text = ((sc["remark"] if sc else None) or "").strip()
        if not text:
            return {"ok": False,
                    "error": "no remark saved yet for " + row["title"] + " -- draft one first"}
    return {"ok": True, "ready": True, "render": {"type": "competency_reflection_draft", "data": {
        "assignment_id": aid, "competency": row["title"], "text": text, "is_draft": is_draft}}}


def _tc_tool_show_progress(db, u, cid, args):
    ov = _competency_overview(db, u)
    data = ov["data"] if ov else {"groups": [], "answered": 0, "total": 0}
    return {"ok": True, "displayed": "progress",
            "render": {"type": "competency_progress", "data": data}}


def _tc_tool_prepare_submit(db, u, cid, args):
    """Show the final submit card. Writes NOTHING (submit is the human click, POST
    /review/competency/submit). Blocks until every competency is answered."""
    ctx = _tc_context(db, u, create=False)
    if ctx is None:
        return {"ok": False, "error": "you have no competencies assigned this cycle"}
    if not ctx["editable"]:
        return {"ok": True, "already_submitted": True}
    unanswered = [r["title"] for g in ctx["groups"] for r in g["rows"]
                  if r.get("answer") not in ("yes", "no")]
    if unanswered:
        return {"ok": False, "error": "still to answer: " + ", ".join(unanswered[:10])}
    # The separate both-levels justification step is gone (Chris, 2026-09-24: the competency assessment is
    # 3 steps -- evaluate, ONE 50-100-word remark, confirm): a competency rated fully demonstrated at both
    # levels is named in the one remark question instead (_tc_remark_question).
    # The ONE overall remark (~100 words, strengths + development areas) is required first (Chris, 2026-09-24).
    rg = _tc_remark_gate(db, u, cid)
    if rg["required"] and not rg["written"]:
        return {"ok": False,
                "error": "The overall remark is REQUIRED before they can submit: ask for about 100 words in "
                         "their own words covering BOTH their strengths and the areas they're still "
                         "developing (it is carried into their development plan), and save it with "
                         "set_overall_note. Do not show the final card or say it's optional."}
    ov = _competency_overview(db, u)
    return {"ok": True, "ready": True,
            "render": {"type": "competency_confirm", "data": ov["data"]}}


# NB: set_competency_note is deliberately NOT registered -- a remark is PROPOSED via
# draft_reflection (the card) and written only by the person's Save (POST /review/competency/note ->
# _tc_save_competency_note). So the card is the definitive, final save step for a remark, and the
# agent cannot save-then-keep-asking (Chris, 2026-09-21). Mirrors the KPI check-in dropping its
# note direct-writer. The _tc_tool_set_competency_note helper stays defined but unreachable.
_TC_TOOLS = {
    "set_competency": _tc_agent_set_competency,
    "set_overall_note": _tc_tool_set_overall_note,
    "draft_reflection": _tc_tool_draft_reflection,
    "show_to_justify": _tc_tool_show_to_justify,
    "show_progress": _tc_tool_show_progress,
    "prepare_submit": _tc_tool_prepare_submit,
}


def _tc_run_tool(db, u, cid, action):
    fn = _TC_TOOLS.get(action.get("tool"))
    if not fn:
        return {"ok": False, "error": "unknown tool"}
    args = action.get("args") or {}
    if not isinstance(args, dict):
        args = {}
    return fn(db, u, cid, args)


@app.route("/review/competency")
@login_required
def review_competency():
    """Technical competency, as a conversation. The employee rates each competency
    Demonstrate/Developing by talking to the agent; the server validates every
    write. Same shell as the setting/check-in chat, a different agent."""
    u = _review_guard()
    db = get_db()
    st = review_state(db, u)
    stage = next((x for x in st["stages"] if x["key"] == "competency"), None)
    if not stage or stage["state"] == REVIEW_STATE_OFF:
        abort(404)
    return render_template("review_competency.html", st=st, stage=stage,
                           manages=_review_manages_team(db, u),
                           agent_available=ai_draft.review_agent_available())


@app.route("/review/competency/chat/history")
@login_required
def review_competency_chat_history():
    """The stored competency-chat transcript, so it resumes on reload."""
    u = _review_guard()
    db = get_db()
    cid = active_cycle_id(db)
    ov = _competency_overview(db, u)
    # Which reflections are already SAVED, so a REPLAYED draft card renders in its saved mode
    # (no armed Save button) instead of an active one on reload (mirror the journey history).
    comp_reflections = {r["assignment_id"]: r["remark"] for r in db.execute(
        "SELECT sc.assignment_id, sc.remark FROM tc_scores sc "
        "JOIN tc_assignments a ON a.id=sc.assignment_id "
        "WHERE a.subject_id=? AND a.cycle_id=? AND sc.remark IS NOT NULL AND TRIM(sc.remark)<>''",
        (u["id"], cid)).fetchall()}
