_PERF_SHORT = ("UA", "BE")
# supports / partly / contradicts / not_shown come from the model; found / not_found from the plain check;
# none (no file) and unread (the contents couldn't be read) from the server.
_PERF_EVIDENCE = ("supports", "partly", "contradicts", "not_shown")


def _pm_file_chips(files):
    """The client's file chips for a KPI line: id, name, gp (Group People added it) and size in bytes (the preview box's head). One shape for
    the manager's, the calibrators' and the AI+ Performance views (2026-11-07)."""
    return [dict({"id": f["id"], "name": f["name"]}, **({"gp": True} if f.get("gp") else {}),
                 **({"size": f["size"]} if f.get("size") is not None else {})) for f in (files or [])]


def _pm_kpi_files(db, subject_id, target_ids, removed=False):
    """{kpi_target_id: [{id, name, note, gp}]} -- the supporting FILES a person attached to these KPI lines
    (their own shared recognition item linked to the line, as the check-in's attach makes it). `note` is
    the item's title or description when there is one; `gp` is True for a file Group People added (uploaded
    by someone other than the person, 2026-11-07). A removed file (an admin took it off, 2026-11-07) is never
    here: every reader of this list, the AI readings and their fingerprint among them, sees the live set.
    `removed=True` is the admin page's own read of the removed ones alone (adds size, who, when and why).
    Read-only; one query."""
    ids = {str(int(t)) for t in (target_ids or []) if t is not None}
    out = {}
    if not ids:
        return out
    for r in db.execute(
        "SELECT l.target_ref ref, a.id aid, a.filename, a.size_bytes, a.uploaded_by, a.uploaded_at, a.added_reason, "
        "a.removed_at, a.removed_by, a.remove_reason, "
        "COALESCE(NULLIF(TRIM(e.title),''), NULLIF(TRIM(e.body),'')) note "
        "FROM pm_evidence e JOIN pm_evidence_links l ON l.evidence_id=e.id AND l.target_kind='kpi' "
        "JOIN pm_evidence_attachments a ON a.evidence_id=e.id "
        "WHERE e.subject_id=? AND e.author_id=? AND e.kind='recognition' AND e.state='shared' AND a.removed_at IS "
        + ("NOT " if removed else "") + "NULL ORDER BY a.id",
        (subject_id, subject_id)).fetchall():
        if r["ref"] in ids:
            f = {"id": r["aid"], "name": r["filename"] or "file", "note": (r["note"] or "").strip(),
                 "gp": bool(r["uploaded_by"] and r["uploaded_by"] != subject_id)}
            if removed:
                f.update(size=r["size_bytes"], removed_at=r["removed_at"], removed_by=r["removed_by"],
                         reason=r["remove_reason"] or "")
            else:
                f.update(size=r["size_bytes"], uploaded_by=r["uploaded_by"], uploaded_at=r["uploaded_at"],
                         added_reason=r["added_reason"] or "")
            out.setdefault(int(r["ref"]), []).append(f)
    return out


# ---- A supporting file's CONTENTS, read to text (Chris, 2026-09-25) ------------------------------------
# "the AI agent should assess the performance result keyed by the user and validate it with the attachment
# (markdown the attachment file and use that as the context to compare and contrast and verify the result)".
# Each file is read ONCE and cached per attachment (a file never changes under its id): PDF text (pypdf),
# Word paragraphs + tables, PowerPoint slide text + tables in the deck's order (2026-10-23), Excel / CSV as
# markdown tables, TXT as is, and an IMAGE transcribed by the model -- only on the summary route, never inside a
# chat turn. A SCANNED PDF (no text layer) has the largest picture on each of its first 3 pages drawn out by the same
# bounded extractor and transcribed like an image (2026-10-23). Legacy .doc / .xls / .ppt have no readable text and
# say so.
# The file is an employee's upload, so PDF / Word / Excel are parsed in a SUBPROCESS with a memory cap, a CPU
# cap and a wall timeout (2026-09-25 review: a 5 KB PDF with one huge content stream took 22 s and a 51 KB one
# ~950 MB in-process), plus per-member unzipped caps and a stop once enough text is collected. The extractor
# is this one source string: run as `python -c` for those types, exec'd in-process for TXT / CSV (cheap).
_ATTACH_TEXT_MAX = 6000        # characters kept per file
_ATTACH_CASE_MAX = 16000       # characters of file contents handed to the model per summary, all files
_ATTACH_EXTRACT_TIMEOUT = 12   # seconds, wall, per file (the child also caps its own CPU at 10 s)
_ATTACH_IMAGE_MIME = {"png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg",
                      "gif": "image/gif", "webp": "image/webp"}
# What a stored evidence file is served as, by its extension (never the uploader's claimed type), and which may
# preview in the browser rather than download (2026-10-23).
_ATTACH_SERVE_TYPES = {
    "pdf": "application/pdf", "png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg", "gif": "image/gif",
    "webp": "image/webp", "txt": "text/plain; charset=utf-8", "csv": "text/csv; charset=utf-8",
    "doc": "application/msword", "xls": "application/vnd.ms-excel", "ppt": "application/vnd.ms-powerpoint",
    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation"}
_ATTACH_INLINE_EXTS = frozenset({"pdf", "png", "jpg", "jpeg", "gif", "webp", "txt"})
_ATTACH_STATUS_WHY = {"no_text": "it has no readable text -- it may be a scan",
                      "unsupported": "that file type can't be read",
                      "too_big": "it is too large or too complex to read",
                      "unreadable": "the file couldn't be opened",
                      "unread": "it hasn't been read yet",
                      "retry": "it hasn't been read yet",
                      "flagged": "it holds words written to an AI, so the AI left it out"}
_ATTACH_EXTRACTOR_SRC = r'''
import csv, io, json, re, sys, zipfile
TEXT_MAX, PDF_PAGES, ROWS, COLS, SLIDES = 6000, 15, 60, 12, 40
UNZIP_MAX, MEMBER_MAX = 25 * 1024 * 1024, 8 * 1024 * 1024
# a scanned PDF's pages, for the model to read (2026-10-23): its first SCAN_PAGES, on each the largest of its first
# SCAN_IMAGES pictures (a logo or a stamp is never a page), redrawn at most SCAN_SIDE px a side as a JPEG of at most
# SCAN_BYTES; a picture over twice SCAN_PIXELS is refused unopened, and its stream unpacks to SCAN_ZLIB at most
SCAN_PAGES, SCAN_IMAGES, SCAN_SIDE, SCAN_MIN_SIDE, SCAN_BYTES = 3, 6, 2000, 300, 1536 * 1024
SCAN_PIXELS, SCAN_ZLIB = 30000000, 64 * 1024 * 1024


def _cell(v):
    if isinstance(v, float) and v == int(v) and abs(v) < 1e15:
        v = int(v)
    t = " ".join(str(v if v is not None else "").split()).replace("|", "\\|")
    return t[:60] + ("\u2026" if len(t) > 60 else "")


def _table(rows):
    rows = [[_cell(c) for c in list(r)[:COLS]] for r in (rows or [])]
    rows = [r for r in rows if any(c for c in r)][:ROWS]
    if not rows:
        return ""
    w = max(max((i + 1 for i, c in enumerate(r) if c), default=0) for r in rows)   # no empty trailing columns
    rows = [r[:w] for r in rows]
    rows = [r + [""] * (w - len(r)) for r in rows]
    out = ["| " + " | ".join(rows[0]) + " |", "| " + " | ".join(["---"] * w) + " |"]
    out += ["| " + " | ".join(r) + " |" for r in rows[1:]]
    return "\n".join(out)


def _ok(text, empty="no_text"):
    t = (text or "").strip()
    if not t:
        return empty, ""
    if len(t) > TEXT_MAX:
        t = t[:TEXT_MAX].rstrip() + "\n[... the rest of the file is not shown]"
    return "ok", t


def _decode(data):
    for enc in ("utf-8-sig", "cp1252", "latin-1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


import xml.etree.ElementTree as ET
_XML_UNSAFE_RE = re.compile(rb"<!(?:doctype|entity)", re.I)


class Unsafe(Exception):
    """An Office file's XML declares a DOCTYPE or an ENTITY: refused unread (extract() answers "unreadable")."""


def _xml_unsafe(raw):
    """True when this XML holds <!DOCTYPE or <!ENTITY, any letter case, also with NULs dropped (UTF-16 text). Word,
    Excel and PowerPoint never write either, and a nested-entity bomb is a few hundred bytes that cost a worker the whole
    12 s (security test 3-04, 2026-10-31): looked for in the raw bytes, before any parser sees them."""
    return bool(_XML_UNSAFE_RE.search(raw) or (b"\x00" in raw and _XML_UNSAFE_RE.search(raw.replace(b"\x00", b""))))


def _read_xml(zf, name):
    """The parsed root of one zip member, or Unsafe."""
    raw = zf.read(name)
    if _xml_unsafe(raw):
        raise Unsafe(name)
    return ET.fromstring(raw)


def extract(ext, data):
    try:
        if ext == "txt":
            return _ok(_decode(data))
        if ext == "csv":
            txt = _decode(data[:512 * 1024])
            try:
                dialect = csv.Sniffer().sniff(txt[:4096], delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
            rows = []
            for i, r in enumerate(csv.reader(io.StringIO(txt), dialect)):
                if i >= ROWS:
                    break
                rows.append(r)
            return _ok(_table(rows))
        if ext == "pptx":
            zf = zipfile.ZipFile(io.BytesIO(data))
            if sum(i.file_size for i in zf.infolist()) > UNZIP_MAX:
                return "too_big", ""
            import posixpath, re
            import xml.etree.ElementTree as ET
            P = "{http://schemas.openxmlformats.org/presentationml/2006/main}"
            A = "{http://schemas.openxmlformats.org/drawingml/2006/main}"
            R = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"
            names, order = set(zf.namelist()), []
            try:   # the deck's own order: presentation.xml's slide list, through its relationships
                for m in ("ppt/presentation.xml", "ppt/_rels/presentation.xml.rels"):
                    if zf.getinfo(m).file_size > MEMBER_MAX:
                        return "too_big", ""
                rels = {el.get("Id"): el.get("Target") or ""
                        for el in _read_xml(zf, "ppt/_rels/presentation.xml.rels")}
                for sid in _read_xml(zf, "ppt/presentation.xml").iter(P + "sldId"):
                    t = rels.get(sid.get(R + "id"), "")
                    path = t.lstrip("/") if t.startswith("/") else posixpath.normpath(posixpath.join("ppt", t))
                    if path in names and path not in order:
                        order.append(path)
            except (KeyError, ET.ParseError):
                order = []
            if not order:   # no readable slide list: the slide files by number
                order = sorted((n for n in names if re.fullmatch(r"ppt/slides/slide\d+\.xml", n)),
                               key=lambda n: int(re.sub(r"\D", "", n.rsplit("/", 1)[1])))
            parts, size = [], 0
            for path in order[:SLIDES]:
                if zf.getinfo(path).file_size > MEMBER_MAX:
                    return "too_big", ""
                root = _read_xml(zf, path)
                in_tbl, tables = set(), []
                for tbl in root.iter(A + "tbl"):
                    tables.append(_table([["".join(x.text or "" for x in tc.iter(A + "t")) for tc in tr.iter(A + "tc")]
                                          for tr in tbl.iter(A + "tr")]))
                    in_tbl.update(id(p) for p in tbl.iter(A + "p"))
                out = [t for t in ("".join(x.text or "" for x in p.iter(A + "t")).strip()
                                   for p in root.iter(A + "p") if id(p) not in in_tbl) if t]
                out += [t for t in tables if t]
                if out:
                    parts.append("\n".join(out)); size += sum(len(t) for t in out)
                if size > TEXT_MAX:
                    break
            return _ok("\n--- slide ---\n".join(parts))
        if ext in ("xlsx", "docx"):
            zf = zipfile.ZipFile(io.BytesIO(data))
            infos = zf.infolist()
            if sum(i.file_size for i in infos) > UNZIP_MAX:
                return "too_big", ""
            if ext == "docx":
                try:
                    member = zf.getinfo("word/document.xml")
                except KeyError:
                    return "unreadable", ""
                if member.file_size > MEMBER_MAX:
                    return "too_big", ""
                raw = zf.read(member)
                if _xml_unsafe(raw):   # a DOCTYPE or ENTITY: refused before any parse (3-04)
                    return "unreadable", ""
                import xml.etree.ElementTree as ET
                W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
                out, size, row, cell, rows = [], 0, None, None, None
                for ev, el in ET.iterparse(io.BytesIO(raw), events=("start", "end")):
                    if ev == "start":
                        if el.tag == W + "tbl":
                            rows = []
                        elif el.tag == W + "tr" and rows is not None:
                            row = []
                        continue
                    if el.tag == W + "p" and rows is None:
                        t = "".join(x.text or "" for x in el.iter(W + "t")).strip()
                        if t:
                            out.append(t); size += len(t)
                    elif el.tag == W + "tc" and row is not None:
                        row.append("".join(x.text or "" for x in el.iter(W + "t")))
                    elif el.tag == W + "tr" and rows is not None and row is not None:
                        rows.append(row); row = None
                    elif el.tag == W + "tbl" and rows is not None:
                        t = _table(rows)
                        if t:
                            out.append(t); size += len(t)
                        rows = None
                    if (el.tag == W + "p" and rows is None) or el.tag == W + "tbl":
                        el.clear()   # (a paragraph inside a table cell is read at the cell's end)
                    if size > TEXT_MAX:
                        break
                return _ok("\n\n".join(out))
            for i in infos:
                if (i.filename.endswith("sharedStrings.xml") and i.file_size > MEMBER_MAX) or \
                        (i.filename.startswith("xl/worksheets/") and i.file_size > 2 * MEMBER_MAX):
                    return "too_big", ""
            for i in infos:   # every XML part of the workbook is looked at before openpyxl parses any of it (3-04)
                if i.filename.endswith((".xml", ".rels")) and _xml_unsafe(zf.read(i)):
                    return "unreadable", ""
            from openpyxl import load_workbook
            wb = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
            parts, size = [], 0
            try:
                for ws in wb.worksheets[:4]:
                    rows = [["" if v is None else v for v in r]
                            for r in ws.iter_rows(max_row=ROWS, max_col=COLS, values_only=True)]
                    t = _table(rows)
                    if t:
                        parts.append("### Sheet: %s\n%s" % (ws.title, t)); size += len(t)
                    if size > TEXT_MAX:
                        break
            finally:
                wb.close()
            return _ok("\n\n".join(parts))
        if ext == "pdf":
            import pypdf
            r = pypdf.PdfReader(io.BytesIO(data))
            if r.is_encrypted:
                try:
                    r.decrypt("")
                except Exception:
                    return "unreadable", ""
            parts, size = [], 0
            for i in range(min(len(r.pages), PDF_PAGES)):
                t = (r.pages[i].extract_text() or "").strip()
                if t:
                    parts.append(t); size += len(t)
                if size > TEXT_MAX:
                    break
            return _ok("\n--- page ---\n".join(parts))
        return "unsupported", ""
    except Exception:
        return "unreadable", ""


def _page_jpeg(im, rotate):
    """One page's picture as the model will read it: upright as the page shows it, white behind see-through parts, at
    most SCAN_SIDE px a side, and at most SCAN_BYTES (the quality steps down, then the page is left out)."""
    from PIL import Image
    try:
        im.draft(im.mode, (SCAN_SIDE, SCAN_SIDE))   # a JPEG decodes straight to a nearer size
    except Exception:
        pass
    if im.mode in ("RGBA", "LA", "PA") or (im.mode == "P" and "transparency" in im.info):
        im = im.convert("RGBA")
        bg = Image.new("RGB", im.size, (255, 255, 255))
        bg.paste(im, mask=im.getchannel("A"))
        im = bg
    elif im.mode not in ("RGB", "L"):
        im = im.convert("L" if im.mode in ("1", "I", "I;16", "F") else "RGB")
    if rotate % 360:
        im = im.rotate(-(rotate % 360), expand=True)   # /Rotate turns the page clockwise, PIL anticlockwise
    im.thumbnail((SCAN_SIDE, SCAN_SIDE))
    for q in (85, 70, 55):
        buf = io.BytesIO()
        im.save(buf, "JPEG", quality=q)
        if buf.tell() <= SCAN_BYTES:
            return buf.getvalue()
    return None


def pdf_pages(data):
    """(status, [JPEG bytes]) for a PDF with no text layer: ok | no_image | unreadable. Asked only once its text read
    found nothing; never raises."""
    try:
        import pypdf
        from PIL import Image
        Image.MAX_IMAGE_PIXELS = SCAN_PIXELS
        r = pypdf.PdfReader(io.BytesIO(data))
        if r.is_encrypted:
            try:
                r.decrypt("")
            except Exception:
                return "unreadable", []
        out = []
        for i in range(min(len(r.pages), SCAN_PAGES)):
            page, best = r.pages[i], None
            try:
                ims = page.images
                for k in range(min(len(ims), SCAN_IMAGES)):
                    try:
                        im = ims[k].image
                    except Exception:   # a format PIL can't open (JBIG2 with no decoder), or past a cap
                        continue
                    if im is None or min(im.size) < SCAN_MIN_SIDE:
                        continue
                    if best is None or im.size[0] * im.size[1] > best.size[0] * best.size[1]:
                        best = im
                jpg = _page_jpeg(best, int(page.rotation or 0)) if best is not None else None
                if jpg:
                    out.append(jpg)
            except Exception:
                continue
        return ("ok" if out else "no_image"), out
    except Exception:
        return "unreadable", []


if __name__ == "__main__":
    try:
        import resource
        resource.setrlimit(resource.RLIMIT_AS, (768 << 20, 768 << 20))
        resource.setrlimit(resource.RLIMIT_CPU, (10, 10))
    except Exception:
        pass
    try:
        import pypdf.filters as _pf
        # a page's picture unpacks larger than a page's text (a colour A4 at 300 dpi is 26 MB)
        _pf.ZLIB_MAX_OUTPUT_LENGTH = SCAN_ZLIB if sys.argv[1] == "pdf_pages" else 16 * 1024 * 1024
    except Exception:
        pass
    if sys.argv[1] == "pdf_pages":
        import base64
        st, pages = pdf_pages(sys.stdin.buffer.read())
        sys.stdout.write(json.dumps({"status": st, "pages": [base64.b64encode(p).decode("ascii") for p in pages]}))
    else:
        st, tx = extract(sys.argv[1], sys.stdin.buffer.read())
        sys.stdout.write(json.dumps({"status": st, "text": tx}))
'''
_ATTACH_X = {}
exec(compile(_ATTACH_EXTRACTOR_SRC, "<attach_extractor>", "exec"), _ATTACH_X)


def _attach_ext(name):
    name = name or ""
    return name.rsplit(".", 1)[-1].lower() if "." in name else ""


def _attach_extract(ext, data):
    """(status, text) for one file's bytes, without the model: ok | no_text | unsupported | too_big |
    unreadable. TXT / CSV in-process; PDF / Word / Excel in a bounded subprocess. Never raises."""
    if ext in ("txt", "csv"):
        return _ATTACH_X["extract"](ext, data)
    if ext not in ("pdf", "docx", "xlsx", "pptx"):
        return "unsupported", ""
    import subprocess
    try:
        p = subprocess.run([sys.executable, "-c", _ATTACH_EXTRACTOR_SRC, ext], input=data,
                           capture_output=True, timeout=_ATTACH_EXTRACT_TIMEOUT)
    except subprocess.TimeoutExpired:
        return "too_big", ""
    except Exception:
        return "unreadable", ""
    if p.returncode != 0:          # killed by its own CPU / memory cap
        return "too_big", ""
    try:
        out = json.loads((p.stdout or b"{}").decode("utf-8") or "{}")
    except ValueError:
        return "unreadable", ""
    st = out.get("status") or "unreadable"
    return st, ((out.get("text") or "")[:_ATTACH_TEXT_MAX + 80] if st == "ok" else "")


def _attach_pdf_pages(data):
    """(status, [JPEG bytes]) for a scanned PDF's first pages, drawn by the bounded extractor for the model to read
    (2026-10-23): ok | no_image | too_big | unreadable. Only a JPEG within the size cap comes back. Never raises."""
    import base64
    import subprocess
    try:
        p = subprocess.run([sys.executable, "-c", _ATTACH_EXTRACTOR_SRC, "pdf_pages"], input=data,
                           capture_output=True, timeout=_ATTACH_EXTRACT_TIMEOUT)
    except subprocess.TimeoutExpired:
        return "too_big", []
    except Exception:
        return "unreadable", []
    if p.returncode != 0:          # killed by its own CPU / memory cap
        return "too_big", []
    try:
        out = json.loads((p.stdout or b"{}").decode("utf-8") or "{}")
        pages = [base64.b64decode(x, validate=True) for x in (out.get("pages") or [])[:_ATTACH_X["SCAN_PAGES"]]]
    except (ValueError, TypeError, AttributeError):
        return "unreadable", []
    pages = [b for b in pages if b[:3] == b"\xff\xd8\xff" and len(b) <= _ATTACH_X["SCAN_BYTES"]]
    if pages:
        return "ok", pages
    return (out.get("status") if out.get("status") not in (None, "", "ok") else "no_image"), []


def _attach_bytes(att):
    """The stored bytes of one evidence attachment, or None. Local storage only (the evidence ledger's
    backend), confined to EVIDENCE_UPLOAD_DIR."""
    if (att["storage_backend"] or "local") != "local" or not att["stored_path"]:
        return None
    base = os.path.realpath(EVIDENCE_UPLOAD_DIR)
    path = os.path.realpath(os.path.join(base, att["stored_path"]))
    if not path.startswith(base + os.sep) or not os.path.isfile(path):
        return None
    if os.path.getsize(path) > 4 * EVIDENCE_ATTACH_MAX_BYTES:
        return None
    with open(path, "rb") as fh:
        return fh.read()


def _attach_text_cached(db, ids):
    """{attachment_id: {status, method, text}} for the files already read. Read-only."""
    ids = [int(i) for i in (ids or [])]
    if not ids:
        return {}
    return {r["attachment_id"]: {"status": r["status"], "method": r["method"], "text": r["text"] or ""}
            for r in db.execute("SELECT attachment_id, status, method, text FROM pm_evidence_attachment_text "
                                "WHERE attachment_id IN (%s)" % ",".join("?" * len(ids)), ids)}


def _attach_scan_due(have):
    """A PDF's cached reading that leaves its pages to the model (2026-10-23): its text read found nothing (a scan) and
    the model hasn't read its pages yet, or that read timed out once."""
    return bool(have) and ((have["status"] == "no_text" and have["method"] == "local")
                           or (have["status"] == "retry" and have["method"] == "vision"))


def _attach_unread_images(db, ids):
    """How many of these files only the model can read and hasn't yet: images not yet transcribed, and scanned PDFs
    whose pages it hasn't read (2026-10-23); one whose first read timed out ('retry') counts, one that failed twice
    does not."""
    ids = [int(i) for i in (ids or [])]
    if not ids:
        return 0
    have = _attach_text_cached(db, ids)
    rows = db.execute("SELECT id, filename FROM pm_evidence_attachments WHERE removed_at IS NULL AND id IN (%s)"
                      % ",".join("?" * len(ids)), ids).fetchall()
    return sum(1 for r in rows if (_attach_ext(r["filename"]) in _ATTACH_IMAGE_MIME
                                   and (r["id"] not in have or have[r["id"]]["status"] == "retry"))
               or (_attach_ext(r["filename"]) == "pdf" and _attach_scan_due(have.get(r["id"]))))


_ATTACH_VISION_READS = 9      # model reads per reading: an image is one, a scanned PDF one a page (at most 3)
_ATTACH_VISION_WORKERS = 6


def _attach_read_all(db, ids, allow_model=False, deadline=None):
    """{attachment_id: {status, method, text}} for these files, reading any not read yet: the non-image types
    through the bounded extractor, images and a scanned PDF's pages through the model when `allow_model` (6 at a
    time, at most 9 a reading, bounded wait). NOTHING is written until every read is done -- then one short batch --
    so no database transaction is held across a parse or a model call (2026-09-25 review: the first INSERT opened the
    write lock for the whole image wait). A model failure that may pass (timeout, rate limit, 5xx, auth, a missing
    deployment) is not cached, except that a file timing out a second time is given up on (unreadable), and one whose reading is cut off
    at the model's token limit a second time is settled as too_big; a refusal about the FILE
    itself (400 / 413 / 415) is cached as unreadable. A scan is read whole or not at all: a page missing would read as
    "the figure isn't in the file". Called only from the summary route and the pre-run worker."""
    import time as _time
    ids = [int(i) for i in (ids or [])]
    out = _attach_text_cached(db, ids)
    todo = [i for i in ids if i not in out or out[i]["status"] == "retry"
            or (allow_model and _attach_scan_due(out[i]))]
    if not todo:
        return _attach_screened(db, out)
    prior = {i: (out.get(i) or {}).get("status") for i in todo}
    rows = db.execute("SELECT id, filename, stored_path, storage_backend FROM pm_evidence_attachments "
                      "WHERE removed_at IS NULL AND id IN (%s)" % ",".join("?" * len(todo)), todo).fetchall()
    writes, reads = [], []   # reads: (att, its pages as [(bytes, mime)], or None for an image read from disk)
    unread = {"status": "unread", "method": None, "text": ""}
    for att in rows:
        ext = _attach_ext(att["filename"])
        if ext in _ATTACH_IMAGE_MIME:
            if allow_model:
                reads.append((att, None))
            else:
                out[att["id"]] = dict(unread)
            continue
        have = out.get(att["id"])
        if have and not (ext == "pdf" and _attach_scan_due(have)):
            continue
        if deadline is not None and _time.monotonic() > deadline:
            out[att["id"]] = dict(unread)
            continue
        data = _attach_bytes(att)
        if not have:
            st, txt = _attach_extract(ext, data) if data is not None else ("unreadable", "")
            out[att["id"]] = {"status": st, "method": "local", "text": txt}
            writes.append((att["id"], st, "local", txt))
            if not (allow_model and ext == "pdf" and st == "no_text"):
                continue
        # a scan (2026-10-23): its pages go to the model as an image does
        if deadline is not None and _time.monotonic() > deadline:
            out[att["id"]] = dict(unread)
            continue
        _pst, pages = _attach_pdf_pages(data) if data is not None else ("unreadable", [])
        if pages:
            reads.append((att, [(p, "image/jpeg") for p in pages]))
        else:   # no page the model could read: nothing more to try
            out[att["id"]] = {"status": "no_text", "method": "vision", "text": ""}
            writes.append((att["id"], "no_text", "vision", ""))
    if reads:
        import concurrent.futures as _cf

        def _read(att, data, mime):
            if data is None:
                data = _attach_bytes(att)
                if data is None:
                    return "unreadable", ""
            try:
                # never the file's NAME to the model (2026-10-23): a name is the person's text, and the transcriber
                # needs none to copy what the image shows
                return _attach_ok(ai_draft.read_image(data, mime, "image", timeout=20))
            except ai_draft.AIDraftError as e:
                if getattr(e, "sub", None) == "cut":   # too long to finish within the model's limit (2026-11-07): ask once more, then stop
                    return "cut", ""
                return ("unreadable", "") if re.search(r"HTTP (400|413|415)\b", str(e)) else ("unread", "")
            except Exception:
                return "unread", ""
        ex = _cf.ThreadPoolExecutor(max_workers=_ATTACH_VISION_WORKERS)
        futs, n = {}, 0   # whole files, in order, while they fit; the rest wait for the next reading, nothing used up
        for att, pages in reads:
            jobs = pages or [(None, _ATTACH_IMAGE_MIME[_attach_ext(att["filename"])])]
            if n + len(jobs) > _ATTACH_VISION_READS:
                continue
            n += len(jobs)
            for data, mime in jobs:
                futs[ex.submit(_read, att, data, mime)] = att["id"]
        wait = 22 if deadline is None else max(1, min(22, deadline - _time.monotonic()))
        done, _pending = _cf.wait(futs, timeout=wait)
        ex.shutdown(wait=False, cancel_futures=True)
        got = {}
        for f, aid in futs.items():   # in each file's page order
            got.setdefault(aid, []).append(f.result() if f in done else None)
        for att, _pages in reads:
            aid = att["id"]
            res = got.get(aid)
            if res is None:
                out[aid] = dict(unread)
                continue
            if any(r is not None and r[0] == "cut" for r in res):
                # a reply cut off at the token limit (2026-11-07: 41 in a day, the same file sent again on every reading):
                # try once more next time, then settle as too_big ("too large or too complex to read"). Never taken as a
                # transcription: a figure cut off would read as the whole file.
                st, txt = ("too_big", "") if prior.get(aid) == "retry" else ("retry", "")
            elif any(r is None for r in res):   # timed out: try once more next time, then give up
                st, txt = ("unreadable", "") if prior.get(aid) == "retry" else ("retry", "")
            elif any(r[0] == "unread" for r in res):
                st, txt = "unread", ""
            elif any(r[0] == "unreadable" for r in res):
                st, txt = "unreadable", ""
            else:
                st, txt = _attach_ok("\n--- page ---\n".join(t for s_, t in res if s_ == "ok"))
            out[aid] = {"status": st, "method": "vision", "text": txt}
            if st != "unread":
                writes.append((aid, st, "vision", txt))
    if writes:
        db.executemany("INSERT OR REPLACE INTO pm_evidence_attachment_text(attachment_id, status, method, text) "
                       "VALUES (?,?,?,?)", writes)
        db.commit()
    return _attach_screened(db, out)


def _attach_screened(db, out):
    """The last step of every reading (Chris, 2026-10-23: no prompt injection through a file): a file whose text, or
    name, addresses the AI (ai_draft.screen_file_text) becomes 'flagged' with its text dropped, so no AI reading uses
    it -- the manager's insight, the calibrators', the person's own Write with AI -- and the insight tells the manager
    to open it. Screened on every read, never stored: the cache keeps what the extractor found, so a better screen
    reaches files already read."""
    ids = [int(i) for i in out]
    if not ids:
        return out
    names = {r["id"]: r["filename"] or "" for r in db.execute(
        "SELECT id, filename FROM pm_evidence_attachments WHERE id IN (%s)" % ",".join("?" * len(ids)), ids)}
    for i in ids:
        v = out[i]
        hit = ai_draft.screen_file_text(names.get(i, "")) or (
            ai_draft.screen_file_text(v.get("text")) if v.get("status") == "ok" else None)
        if hit:
            out[i] = dict(v, status="flagged", text="")
    return out


def _attach_ok(text, empty="no_text"):
    return _ATTACH_X["_ok"](text, empty)


# The figures in a file's OWN content -- not the page / sheet headers the extractor adds, not dates or times,
# not a digit glued to letters ('Q3', 'H2', 'Sheet1'); a leading minus or (brackets) is negative. Each is
# (value, has_decimals, significant_digits).
_FIG_SKIP_LINE_RE = re.compile(r"^\s*(### Sheet:.*|--- page ---|--- slide ---)\s*$", re.M)
_FIG_DATE_RE = re.compile(r"\b\d{4}-\d{1,2}-\d{1,2}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?\b|\b\d{1,2}/\d{1,2}/\d{2,4}\b|"
                          r"\b\d{1,2}:\d{2}(?::\d{2})?\b")
_FIG_NUM_RE = re.compile(r"(?<![A-Za-z0-9.])(\()?(-)?(\d[\d,]*(?:\.\d+)?)(\))?(?![0-9])")


def _fig_numbers(text):
    t = _FIG_DATE_RE.sub(" ", _FIG_SKIP_LINE_RE.sub(" ", text or ""))
    t = re.sub(r"(?i)\b(RM|USD|SGD|MYR|RMB)(?=\d)", r"\1 ", t)
    out = []
    for m in _FIG_NUM_RE.finditer(t):
        raw = m.group(3).replace(",", "")
        try:
            n = float(raw)
        except ValueError:
            continue
        if m.group(2) or (m.group(1) and m.group(4)):
            n = -n
        out.append((n, "." in raw, len(raw.replace(".", "").strip("0")) or 1))
    return out


def _figure_in_text(value, text):
    """Does a keyed figure appear in a file's own text? 15.9 matches 15.9 / 15.90 / RM15.9m / 15,900,000; a
    percentage matches its fraction and back; 0.5% tolerance for rounding. A scaled match (thousands /
    millions / a percentage) needs a specific enough figure in the file (a decimal, or two significant
    digits), so 2,000,000 never matches a stray '2'. The check behind 'the file backs the result'."""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return False
    if not math.isfinite(v):
        return False
    for n, dec, sig in _fig_numbers(text):
        if v == 0:
            if n == 0:
                return True
            continue
        if abs(n - v) <= abs(v) * 0.005:
            return True
        if dec or sig >= 2:
            for k in (1e3, 1e6, 1e9, 1e-3, 1e-6, 1e-9, 100, 0.01):
                tgt = v * k
                if abs(n - tgt) <= abs(tgt) * 0.005:
                    return True
    return False


def _pm_fig_unit(v, unit):
    """A figure with its unit: '42%' (no space before a percent sign), '13.99 RM (mil)'."""
    unit = (unit or "").strip()
    if not unit:
        return str(v)
    if (kpi_unit_normalise(unit) or "").lower() == "rating":   # a rating reads "Rating 4", never "4 Rating" (2026-10-30)
        return "Rating %s" % v
    return ("%s%s" % (v, unit)) if unit == "%" else ("%s %s" % (v, unit))


def _pm_fig(v):
    """A score as the manager's table shows it: at most 2 decimals, trailing zeros dropped (3.3333 -> '3.33',
    4.0 -> '4'). The summary and the table must quote the same figure."""
    try:
        f = round(float(v), 2)
    except (TypeError, ValueError):
        return str(v)
    return ("%d" % f) if f == int(f) else ("%.2f" % f).rstrip("0").rstrip(".")


def _pm_perf_source(db, u, report_id, scope="approver"):
    """What ONE approver may see of a direct report's performance this period (Chris, 2026-09-24/25), as
    (status, first, words, extra, facts):
      words -- the person's OWN words and files: their per-KPI notes, their submitted overall remark, and
               the supporting files they attached (name + description). Part of the cache fingerprint.
      facts -- per line: the target and scale, the keyed result, where it lands (their own rating) and the
               moderated one, their note and their files; the overall -- `self_overall` by their own results,
               `overall` as it stands (moderated), each only when EVERY line has a result; HR-set lines kept
               apart. The case file for the model is built from these + the files' text
               (_pm_perf_case_text), and the bands are always written by the SERVER, never the model.
    Scope: this approver's lines (_pm_member_previews -- the Team summary's scope), SUBMITTED results only
    (attach_pm_chains hides drafts). An HR-owned line (BU-level or HR-filled) is never "their" submission
    and HR's fill note is never "their note". status 'none' when they have submitted nothing of their own.
    Read-only (reading the files happens in _pm_perf_summary_for, on the summary route)."""
    period = active_pm_period(db)
    who = db.execute("SELECT full_name FROM users WHERE id=?", (report_id,)).fetchone()
    full = (who["full_name"] if who else "") or ""
    first = full.split()[0] if full.split() else "They"
    if not period:
        return "none", first, "", "", {}
    if scope == "calibrator":   # every line, for the person calibrating their whole rating (2026-09-28)
        mine, mine_prev, self_prev, _all = _pm_all_previews(db, report_id, period["id"])
    else:
        mine, mine_prev, self_prev, _all = _pm_member_previews(db, report_id, period["id"], u["id"])
    res = lambda t: dict(t["result"]) if t.get("result") else {}   # a sqlite Row -> a dict
    hr = [t for t in mine if _review_hr_owned(t)]
    own = [t for t in mine if not _review_hr_owned(t)]
    keyed = [t for t in own if res(t).get("actual_value") is not None]
    if not keyed:
        return "none", first, "", "", {}
    files = _pm_kpi_files(db, report_id, [t["id"] for t in keyed])
    words, rows = [], []
    for t in keyed:
        note = (res(t).get("note") or "").strip()
        if note:
            words.append("Their note on %s: %s" % (t["kpi_name"], note))
        for f in files.get(t["id"]) or []:
            words.append("Supporting file on %s: %s%s" % (t["kpi_name"], f["name"],
                                                          (" -- " + f["note"]) if f["note"] else ""))
        if not files.get(t["id"]):
            words.append("No supporting file on %s." % t["kpi_name"])
        sc, ms = (t.get("self_score") or {}), (t.get("score") or {})
        scale, scale_b = _pm_line_scale(t)
        val = res(t).get("actual_value")
        unit = (t.get("unit") or "").strip()
        mech_b = bool(scale_b)
        # The line manager's moderation (Chris, 2026-09-29: "the justification should also consider and include the
        # line manager remark and moderation") -- for a CALIBRATOR only, and only on a LOCKED line: the committed
        # pm_kpi_approvals steps (never pm_kpi_moderation_drafts, an approver's private scratch), the same rule the
        # calibration KPI report shows the moderated value and reason by.
        mods, approvers = [], []
        if scope == "calibrator" and t.get("locked"):
            names = {c["seq"]: (c["approver_name"] or "Their manager") for c in (t.get("approver_chain") or [])}
            for ap in t.get("approvals") or []:
                by = names.get(ap["seq"], "Their manager")
                approvers.append(by)
                if ap["action"] == "adjust" and ap["adjusted_value"] is not None:
                    fv = ap["original_value"] if ap["original_value"] is not None else val
                    try:   # the value they received typed back in is no moderation (_pm_calib_fit_manager agrees)
                        if abs(float(fv) - float(ap["adjusted_value"])) <= max(abs(float(fv)) * 0.0005, 1e-9):
                            continue
                    except (TypeError, ValueError):
                        pass
                    mods.append({"by": by, "from": fv, "to": ap["adjusted_value"],
                                 "from_res": _pm_fig_unit(_commas(fv), unit),
                                 "to_res": _pm_fig_unit(_commas(ap["adjusted_value"]), unit),
                                 "why": (ap["justification"] or "").strip()})
        for m in mods:
            words.append("Their line manager (%s) moderated %s from %s to %s%s" % (
                m["by"], t["kpi_name"], m["from_res"], m["to_res"],
                (" -- their reason: " + m["why"]) if m["why"] else " -- no reason given"))
        mod_value = t.get("effective_value") if mods else None
        target = (next((b["value"] for b in scale_b if b["label"] == "Target"), None) if mech_b
                  else (scale[2]["value"] if len(scale) == 5 else None))
        rows.append({"id": t["id"], "kpi": t["kpi_name"], "band": sc.get("label"), "rating": sc.get("value"),
                     "mod_band": ms.get("label"), "files": len(files.get(t["id"]) or []),
                     "file_list": files.get(t["id"]) or [], "note": note, "value": val,
                     "result": _pm_fig_unit(_commas(val), unit), "unit": unit, "target": target,
                     "target_raw": t.get("target") if mech_b else t.get("rate3"),
                     # the scale without rung numbers ('1 = ... 5 = ...' grounded any small figure)
                     "scale": (" · ".join(str(x["value"]) for x in scale) if scale
                               else " · ".join("%s %s" % (x["label"], x["value"]) for x in scale_b)),
                     "direction": "higher is better" if t.get("method") == "more" else "lower is better",
                     "weight": t.get("weightage"), "mech": t.get("mechanism"),
                     "moderation": mods, "mod_value": mod_value,
                     "mod_result": _pm_fig_unit(_commas(mod_value), unit) if mod_value is not None else None,
                     "locked": bool(t.get("locked")), "approvers": approvers})
    remark = _pm_submitted_remark(db, report_id)
    words.append(("Their overall remark, in their own words: " + remark) if remark
                 else "They wrote no overall remark.")
    # The overall only when EVERY line (HR's included) has a result -- as performance_team_member_view's
    # mine_all_scored guard does; a partial average would read as their rating.
    scored = sum(1 for t in mine if t.get("score"))
    complete = bool(mine and scored == len(mine))
    ov = (mine_prev or self_prev) if complete else None
    mgr = _pm_manager_remarks_locked(db, period["id"], report_id, _all) if scope == "calibrator" else []
    for m in mgr:
        words.append("%s overall remark (%s): %s" % ("Their line manager's" if m.get("role") == "Line manager"
                                                     else "Another approver's", m["author"], m["remark"]))
    extra = " ".join([full, first] + [t["kpi_name"] for t in mine] + [m["author"] for m in mgr]
                     + [a for r in rows for a in r["approvers"]])
    return "submitted", first, "\n".join(words), extra, {
        "mgr_remarks": mgr,
        "overall": ov, "self_overall": self_prev if complete else None,
        "scored": scored, "lines": len(mine), "rows": rows, "remark": remark,
        "hr": [{"kpi": t["kpi_name"], "band": (t.get("score") or {}).get("label")}
               for t in hr if res(t).get("actual_value") is not None]}


def _pm_perf_trail(db, subject_id, tier):
    """[{tier, label, by, from, band, note}] -- the LOCKED tiers below `tier` that moved this person (pm_calibration_trails'
    own lock rule), with who moved them: how the rating reached the calibrator (2026-09-29)."""
    period = active_pm_period(db)
    subj = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    if not period or not subj:
        return []
    out = []
    for t in pm_calibration_trails(db, [subj], period["id"], below=tier).get(subject_id) or []:
        if t.get("cal") or t.get("avg"):   # one of several calibrators, or their weighted average (2026-10-26)
            out.append(dict({"tier": t["tier"], "label": t["label"], "by": t.get("by") or "", "from": t["from"],
                             "band": t["band"], "note": (t["note"] or "").strip()},
                            **{k_: t[k_] for k_ in ("cal", "avg", "weight", "waiting") if k_ in t}))
            continue
        row = db.execute(
            "SELECT u.full_name FROM pm_calibration_adjustments a JOIN pm_calibration_sessions s ON s.id = a.session_id "
            "LEFT JOIN users u ON u.id = a.adjusted_by WHERE s.cycle_id=? AND s.tier=? AND s.locked_at IS NOT NULL "
            "AND a.subject_id=? ORDER BY a.adjusted_at DESC LIMIT 1", (period["id"], t["tier"], subject_id)).fetchone()
        out.append({"tier": t["tier"], "label": t["label"], "by": ((row["full_name"] if row else "") or ""),
                    "from": t["from"], "band": t["band"], "note": (t["note"] or "").strip()})
    return out


def _pm_submitted_remark(db, report_id):
    """The employee's SUBMITTED overall remark this period (draft=0), or ''. A draft is private."""
    period = active_pm_period(db)
    if not period:
        return ""
    rm = db.execute("SELECT remark FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=? AND draft=0 "
                    "AND TRIM(COALESCE(remark,''))<>''", (period["id"], report_id)).fetchone()
    return (rm["remark"] if rm else "").strip()


def _pm_perf_headline(facts):
    """The score part of the summary, written by the SERVER from the figures (Chris, 2026-09-24 review: a
    model restating a band passed any word check) -- the overall (or why it isn't available yet), the
    strongest and weakest KPI by their own rating, and any line HR set."""
    nm = lambda code: PM_LABEL_NAMES.get(code, code or "")
    bits = []
    ov = facts.get("overall")
    if ov and ov.get("value") is not None:
        bits.append("Overall %s (%s) so far." % (_pm_fig(ov["value"]), nm(ov.get("label"))))
    elif facts.get("lines"):
        bits.append("Overall not available yet (%d of %d lines have a result)." % (facts.get("scored") or 0,
                                                                                facts["lines"]))
    rated = [r for r in facts.get("rows") or [] if r.get("rating") is not None]
    if len(rated) == 1:
        bits.append("%s: %s by their own result." % (rated[0]["kpi"], nm(rated[0]["band"])))
    elif rated:
        hi = max(rated, key=lambda r: r["rating"]); lo = min(rated, key=lambda r: r["rating"])
        if hi["rating"] == lo["rating"]:
            bits.append("All their KPIs rated %s by their own results." % nm(hi["band"]))
        else:
            bits.append("By their own results, strongest: %s (%s); weakest: %s (%s)." % (
                hi["kpi"], nm(hi["band"]), lo["kpi"], nm(lo["band"])))
    moved = [r for r in rated if r.get("mod_band") and r["mod_band"] != r.get("band")]
    if moved:
        bits.append("Moderated so far: %s." % "; ".join("%s to %s" % (r["kpi"], nm(r["mod_band"])) for r in moved))
    for h in facts.get("hr") or []:
        bits.append("%s was set by Group People%s." % (h["kpi"], (" (%s)" % nm(h["band"])) if h.get("band") else ""))
    return " ".join(bits)


def _pm_perf_position(r):
    """'above' / 'on' / 'below' target from the FIGURES (keyed result vs target, the KPI's direction), or
    None when there is no numeric target. A Mechanism-B 'Meet Expectation' can be below target, so this --
    not the band -- decides 'on or above target' / 'went well' (2026-09-25 review)."""
    try:
        v = float(r.get("value"))
        t = float(str(r.get("target_raw")).replace(",", ""))
    except (TypeError, ValueError):
        return None
    if abs(v - t) <= abs(t) * 0.0005:
        return "on"
    better = v > t if r.get("direction") == "higher is better" else v < t
    return "above" if better else "below"


def _pm_perf_where(r):
    """Where the keyed result lands, in words. For a lower-is-better KPI it says better / worse than target:
    the model reads 'below target' numerically (46% cost 'below' a 42% target sounds good), 2026-09-25 probe."""
    pos = _pm_perf_position(r)
    lower = r.get("direction") == "lower is better"
    if pos is None:
        return _PERF_BAND_PLAIN.get(r.get("band"), "not rated")
    if pos == "on":
        return "on target"
    if lower:
        return ("better than target" if pos == "above" else "worse than target") + " (lower is better)"
    if pos == "above":
        return "well above target" if r.get("band") == "OU" else "above target"
    return "far below target" if r.get("band") == "UA" else "below target"


def _pm_perf_mod_dir(r):
    """'down' / 'up' / None: which way their line manager moderated this line (the last adjust step against the figure
    they entered, in the KPI's own direction)."""
    mv = r.get("mod_value")
    try:
        v, m = float(r.get("value")), float(mv)
    except (TypeError, ValueError):
        return None
    if abs(v - m) <= max(abs(v) * 0.0005, 1e-9):
        return None
    better = m > v if r.get("direction") == "higher is better" else m < v
    return "up" if better else "down"


def _pm_perf_mod_row(r):
    """The row as moderated: the moderated figure and band in place of theirs (for 'where it lands')."""
    return dict(r, value=r.get("mod_value"), band=r.get("mod_band") or r.get("band"))


def _pm_perf_group(r):
    pos = _pm_perf_position(r)
    if pos is not None:
        return "short" if pos == "below" else "well"
    return "well" if r.get("band") in _PERF_WELL else ("short" if r.get("band") in _PERF_SHORT else "other")


def _fence(s):
    """Untrusted text (their words, a file's contents, a filename) inside the case file's <<< >>> fences:
    fence tokens in it are neutralised so it can't close the fence and write lines that look like ours."""
    return (s or "").replace("<<<", "\u2039\u2039\u2039").replace(">>>", "\u203a\u203a\u203a")


def _pm_perf_case_text(facts, texts):
    """The CASE FILE the model assesses (Chris, 2026-09-25): the overall by their own results (and as
    moderated, when that differs), their remark, and per KPI the target and scale, the keyed result and where
    it lands (in words from the figures, never a band name), their note, and each supporting file with its
    CONTENTS read to text -- plus whether the keyed figure appears in it (the server's own check). Everything
    the person wrote or attached is fenced as data. No scaffolding numbers (KPI indexes, rung numbers, page
    numbers, spelled counts): they grounded any small figure the model made up (2026-09-25 review)."""
    rows = facts.get("rows") or []
    mechs = {r.get("mech") for r in rows}
    unit = " out of 5" if mechs == {"A"} else ("%" if mechs == {"B"} else "")
    out = []
    so, ov = facts.get("self_overall"), facts.get("overall")
    if so and so.get("value") is not None:
        out.append("OVERALL, by their own results: %s%s -- %s overall." % (
            _pm_fig(so["value"]), unit, _PERF_BAND_PLAIN.get(so.get("label"), "not rated")))
        if ov and ov.get("value") is not None and ov.get("label") != so.get("label"):
            out.append("OVERALL as moderated so far: %s%s -- %s overall." % (
                _pm_fig(ov["value"]), unit, _PERF_BAND_PLAIN.get(ov.get("label"), "not rated")))
    else:
        out.append("OVERALL: not available yet -- not every KPI has a result.")
    # several BU-level calibrators (Chris, 2026-10-26: "the AI should pick these up first"): each one's call, then the
    # weighted average, before anything else was written
    for t in [t for t in facts.get("trail") or [] if t.get("cal") or t.get("avg")]:
        came = (("it came in at %s overall" % _PERF_BAND_PLAIN[t["from"]]) if t.get("from") in _PERF_BAND_PLAIN
                else "it came in with no rating yet")
        if t.get("avg"):
            out.append("BU LEVEL, WEIGHTED: their calibrators' calls, weighted, put them at %s overall (%s)%s." % (
                _PERF_BAND_PLAIN.get(t.get("band"), "not rated"), came, (" -- still to lock: %s, so it can change"
                                                                         % _fence(", ".join(t["waiting"])))
                if t.get("waiting") else ""))
        else:
            out.append("BU LEVEL, ONE OF SEVERAL CALIBRATORS: %s, %d%% of the call, %s them at %s overall (%s). %s" % (
                _fence(t.get("by") or ""), t.get("weight") or 0, "kept" if t.get("from") == t.get("band") else "placed",
                _PERF_BAND_PLAIN.get(t.get("band"), "not rated"), came,
                ("Their note: <<<%s>>>" % _fence(t["note"])) if (t.get("note") or "").strip() else "No note given."))
    out.append("THEIR OVERALL REMARK: <<<%s>>>" % _fence(facts["remark"]) if facts.get("remark")
               else "THEIR OVERALL REMARK: none written.")
    for m in facts.get("mgr_remarks") or []:   # a calibrator's case (2026-09-28): the manager's view, once locked
        out.append("%s OVERALL REMARK (%s): <<<%s>>>" % (
            "THEIR LINE MANAGER'S" if m.get("role", "Line manager") == "Line manager" else "ANOTHER APPROVER'S",
            _fence(m["author"]), _fence(m["remark"])))
    for t in [t for t in facts.get("trail") or [] if not (t.get("cal") or t.get("avg"))]:
        # how it reached this tier: a LOCKED lower tier's move and note
        out.append("HOW IT REACHED YOU: the %s (%s) placed them at %s overall (it came in %s). %s" % (
            t["label"], _fence(t.get("by") or ""), _PERF_BAND_PLAIN.get(t.get("band"), "not rated"),
            ("at %s overall" % _PERF_BAND_PLAIN[t["from"]]) if t.get("from") in _PERF_BAND_PLAIN else "with no rating yet",
            ("Their note: <<<%s>>>" % _fence(t["note"])) if (t.get("note") or "").strip() else "No note given."))
    readable = [f["id"] for r in rows for f in r["file_list"] if (texts.get(f["id"]) or {}).get("status") == "ok"]
    budget = max(1500, min(_ATTACH_TEXT_MAX, _ATTACH_CASE_MAX // max(1, len(readable))))
    for r in rows:
        out.append("")
        out.append("KPI: %s" % r["kpi"])
        out.append("  Weight %s%% · %s%s" % (_pm_fig(r["weight"]), r["direction"],
                                           (" · unit " + r["unit"]) if r["unit"] else ""))
        if r["scale"]:
            out.append("  Rating scale, lowest to highest: %s" % r["scale"])
        if r["target"] is not None:
            out.append("  Target: %s" % r["target"])
        out.append("  Keyed result: %s -- %s" % (r["result"], _pm_perf_where(r)))
        if r.get("moderation"):
            for m in r["moderation"]:
                out.append("  THEIR LINE MANAGER'S MODERATION (%s): moved the result from %s to %s -- %s. %s" % (
                    _fence(m["by"]), m["from_res"], m["to_res"],
                    _pm_perf_where(dict(r, value=m["to"], band=r.get("mod_band") or r.get("band"))),
                    ("Their reason: <<<%s>>>" % _fence(m["why"])) if m["why"] else "No reason given."))
        elif r.get("locked") and r.get("approvers"):
            out.append("  Their line manager (%s) approved the result as entered." % _fence(", ".join(r["approvers"])))
        elif r.get("mod_band") and r["mod_band"] != r["band"]:
            out.append("  The manager's moderation so far puts it at a different level from theirs.")
        out.append("  Their note: <<<%s>>>" % _fence(r["note"]) if r["note"] else "  Their note: none.")
        if not r["file_list"]:
            out.append("  Supporting files: none.")
        for f in r["file_list"]:
            tx = texts.get(f["id"]) or {"status": "unread"}
            head = "  Supporting file <<<%s>>>%s" % (_fence(f["name"]),
                                                    (" described as <<<%s>>>" % _fence(f["note"])) if f["note"] else "")
            if tx.get("status") == "ok":
                found = _figure_in_text(r["value"], tx["text"])
                body = tx["text"] if len(tx["text"]) <= budget else tx["text"][:budget] + "\n[... more not shown]"
                mod_chk = ""
                if r.get("mod_value") is not None:
                    mod_chk = "; the moderated figure %s %s in it" % (
                        r["mod_result"], "APPEARS" if _figure_in_text(r["mod_value"], tx["text"]) else "does NOT appear")
                out.append("%s -- the server's check: the keyed figure %s %s in it%s." % (
                    head, r["result"], "APPEARS" if found else "does NOT appear", mod_chk))
                out.append("    CONTENTS%s:\n<<<\n%s\n>>>" % (
                    "" if tx.get("method") != "vision" else " (transcribed from its scanned pages)"
                    if _attach_ext(f["name"]) == "pdf" else " (transcribed from an image)", _fence(body)))
            elif tx.get("status") == "flagged":
                out.append("  Supporting file -- left out: it holds words written to an AI. Do not assess it; the "
                           "reviewer will open it themselves.")
            else:
                out.append("%s -- its contents could not be read (%s)." % (
                    head, _ATTACH_STATUS_WHY.get(tx.get("status"), "not read")))
    for h in facts.get("hr") or []:
        out.append("")
        out.append("SET BY GROUP PEOPLE, not the person's own result (do not assess it): %s." % h["kpi"])
    return "\n".join(out)


def _pm_perf_file_text(r, texts):
    return "\n".join((texts.get(f["id"]) or {}).get("text") or "" for f in r.get("file_list") or []
                     if (texts.get(f["id"]) or {}).get("status") == "ok")


def _pm_perf_evidence(r, texts, model_ev=None, model_note="", plain=False):
    """(code, note) for how one KPI's files stand against the keyed result. The server decides the cases it
    can know -- no file (none), nothing readable (unread) -- and holds the model to the ones it can check: a
    'supports' the file can't back (the keyed figure isn't in it) is downgraded (and _pm_perf_ai_check refuses
    the assessment); a 'contradicts' / 'partly' must cite figures that are really in THAT file, and
    'contradicts' needs a different figure when the keyed one is there (2026-09-25 review: a false
    'contradicts' passed the target off as the file's figure). The plain summary says only found / not_found."""
    files = r.get("file_list") or []
    if not files:
        return "none", ""
    tx = [texts.get(f["id"]) or {} for f in files]
    if any(t.get("status") == "flagged" for t in tx):   # 2026-10-23: words written to the AI -- the manager looks
        return "flagged", "A file on this KPI holds words written to an AI, so the AI left it out. Open it yourself."
    ok = [t for t in tx if t.get("status") == "ok"]
    if not ok:
        why = _ATTACH_STATUS_WHY.get((tx[0] or {}).get("status"), "not read")
        return "unread", "Couldn't read the file (%s)." % why
    ftext = _pm_perf_file_text(r, texts)
    found = _figure_in_text(r.get("value"), ftext)
    # a result their manager moderated stands at the MODERATED figure: a file that shows it backs the result as it
    # now stands (2026-09-29 review -- the check only knew the figure they entered)
    mod_found = r.get("mod_value") is not None and _figure_in_text(r.get("mod_value"), ftext)
    miss = "The keyed figure (%s) doesn't appear in the file." % r["result"]
    hit = (("found", "The keyed figure (%s) appears in the file." % r["result"]) if found else
           ("found", "The moderated figure (%s) appears in the file." % r["mod_result"]) if mod_found else None)
    if plain or model_ev not in _PERF_EVIDENCE:
        return hit or ("not_found", miss)
    if model_ev == "supports" and not (found or mod_found):
        return "not_shown", miss
    if model_ev == "contradicts" and r.get("mod_value") is not None and found and not mod_found:
        # the file shows the figure THEY entered, not the one their manager left -- it contradicts the result as it
        # stands (the prompt's own rule), so the model's verdict holds (GPT-6 Luna probe, 2026-09-30)
        return "contradicts", model_note or ("The file shows their figure (%s), not the moderated %s."
                                             % (r["result"], r["mod_result"]))
    if model_ev in ("contradicts", "partly"):
        cited = [n for n in _pm_perf_note_numbers(model_note) if not _pm_perf_is_keyed_or_target(n, r)]
        if any(not _figure_in_text(n, ftext) for n in cited) or (model_ev == "contradicts" and (found or mod_found)
                                                                and not cited):
            return hit or ("not_found", miss)
    return model_ev, model_note or ""


def _pm_perf_note_numbers(note):
    return [n for n, _dec, _sig in _fig_numbers(note)]


def _pm_perf_is_keyed_or_target(n, r):
    for v in [r.get("value"), r.get("target_raw"), r.get("mod_value")] + [
            x for m in r.get("moderation") or [] for x in (m.get("from"), m.get("to"))]:
        try:
            f = float(str(v).replace(",", ""))
        except (TypeError, ValueError):
            continue
        if abs(n - f) <= max(abs(f) * 0.005, 1e-9):
            return True
    return False


def _pm_perf_read_plain(r):
    """A KPI's line in the plain summary: their note on it, if they wrote one (older check-ins; the journey
    now takes ONE overall remark), else nothing -- the keyed result and target sit on the line above it in
    the popout, so they aren't repeated here."""
    if r.get("note"):
        n = r["note"] if len(r["note"]) <= 140 else r["note"][:140].rsplit(" ", 1)[0] + "…"
        return "Their note: \u201c%s\u201d" % n
    return ""


def _pm_perf_kpi_entry(r, read, ev, note):
    return {"kpi": r["kpi"], "band": r["band"],
            "mod_band": r["mod_band"] if (r.get("mod_band") and r["mod_band"] != r["band"]) else None,
            "group": _pm_perf_group(r), "result": r["result"], "target": r.get("target"),
            "unit": r.get("unit") or "", "direction": "lower" if "lower" in (r.get("direction") or "") else "higher",
            "their_note": r.get("note") or "",
            "mod_result": r.get("mod_result"), "mod_dir": _pm_perf_mod_dir(r),
            "mod_group": _pm_perf_group(_pm_perf_mod_row(r)) if r.get("moderation") else None,
            "mod_band_now": (r.get("mod_band") or r.get("band")) if r.get("moderation") else None,
            "moderation": [{"by": m["by"], "from": m["from_res"], "to": m["to_res"], "why": m["why"],
                            "why_short": _pm_perf_short(m["why"], 14)} for m in r.get("moderation") or []],
            "read": read, "evidence": ev, "evidence_note": note,
            "files": _pm_file_chips(r.get("file_list") or [])}


def _pm_perf_server_flags(kpis):
    """The points the SERVER can raise from the figures and its own file check -- always shown, the model can
    add to them but never remove them (2026-09-25 review: an injected 'nothing to raise' emptied 'discuss')."""
    out = []
    for k in kpis:
        if k["group"] == "well" and k.get("band") in ("AE", "OU") and k["evidence"] == "none":
            out.append("No supporting file for %s, a result above target." % k["kpi"])
        elif k["evidence"] in ("not_found", "not_shown"):
            out.append("The file on %s doesn't show their figure \u2014 worth checking." % k["kpi"])
        elif k["evidence"] == "flagged":
            out.append("A file on %s holds words written to an AI \u2014 open it and check it yourself." % k["kpi"])
        elif k["evidence"] == "contradicts" and not k.get("mod_dir"):
            out.append("The file on %s doesn't match their result \u2014 worth checking." % k["kpi"])
    return out


def _pm_perf_merge_discuss(server, model, limit=4, kpi_names=None):
    """The server's steps first, then the model's -- no exact repeats, and (with kpi_names) no second step about a
    KPI an earlier step already covers (UI audit, 2026-09-29: "No supporting file for Gross Profit ... ask for
    evidence" next to "Ask for evidence supporting the Gross Profit result")."""
    out, seen, covered = [], set(), set()
    names = [n for n in (kpi_names or []) if n]
    for d in list(server) + list(model):
        key = re.sub(r"\W+", " ", d.lower()).strip()
        if not key or key in seen:
            continue
        about = {n.lower() for n in names if n.lower() in d.lower()}
        if about and about <= covered:
            continue
        seen.add(key); covered |= about; out.append(d)
    return out[:limit]


# THE INSIGHT (Chris, 2026-09-25): "what we really need is an insight from AI to help the line manager decide ...
# AI validation on the result and use context on their inputs to verify, and from here suggest ... if this person's
# performance is well justified and why". The SERVER works out how far each result is backed from what it can
# know -- a file that shows the keyed figure, their own explanation, a strong result with nothing behind it -- and
# that is a FLOOR: the model may judge a result LESS justified (it reads the files and their words and can see a
# mismatch the server can't), never MORE. The rating itself stays the reviewer's call: this is about the evidence.
_PERF_VERDICT_RANK = {"not_justified": 0, "partly_justified": 1, "well_justified": 2}
_PERF_JUST_RANK = {"no": 0, "partly": 1, "yes": 2}
_PERF_VERDICT_LABEL = {"well_justified": "Well justified", "partly_justified": "Partly justified",
                       "not_justified": "Not justified"}


# words a KPI's name carries that say nothing of what it measures, left out when the remark is matched to it
_PERF_EXPL_STOP = {"and", "the", "of", "for", "per", "in", "on", "to", "by", "with", "an", "vs", "rate", "ratio",
                   "total", "overall", "achievement", "achieved", "kpi", "target", "actual", "number", "no", "level",
                   "index", "score", "percentage", "pct"}


def _pm_perf_explained(r, remark):
    """Their own words explain this KPI: a note on it, or the overall remark names it -- as written, by its short form
    in brackets ("GP", "PAT"), or in plain words: the name's own words without its code, Focus or brackets, all of a
    short name or at least two of a longer one and half of them (2026-10-24: 1,663 of production's 7,700 Year-End lines
    carry a bracket and 5,515 run to four words or more, so "gross profit" in a remark missed "Gross profit (GP)" and
    the line manager read "no context given"). A word matches by its first five letters ("collections")."""
    if (r.get("note") or "").strip():
        return True
    name = (r.get("kpi") or "").strip()
    if not name or not remark:
        return False
    rl = remark.lower()
    if len(name) >= 4 and name.lower() in rl:
        return True
    if any(re.search(r"\b%s\b" % re.escape(ab), remark) for ab in re.findall(r"\(([A-Z][A-Z0-9&]{1,7})\)", name)):
        return True
    core = re.sub(r"\([^)]*\)", " ", name.split(" \u00b7 ")[0])
    core = re.sub(r"^[A-Z0-9]{2,}-(?=\S)", "", core.strip())   # a code in front ("ZZPMDEMO-Gross Profit")
    words = [w for w in re.findall(r"[a-z]{3,}", core.lower()) if w not in _PERF_EXPL_STOP]
    if not words:
        return False
    said = set(re.findall(r"[a-z]{3,}", rl))
    stems = {w[:5] for w in said}
    found = sum(1 for w in words if (w in said) or (len(w) >= 5 and w[:5] in stems))
    return found == len(words) or (found >= 2 and found * 2 >= len(words))


def _pm_perf_justify_kpi(k, r, remark):
    """(code, why) -- how far ONE result is backed, from what the server knows (k: the KPI entry, r: its facts). A line
    their LINE MANAGER moderated (a calibrator's case, locked lines) is judged AS THE MANAGER LEFT IT (2026-09-29): the
    moderated figure and its band; backed when a file shows the moderated figure. Moved DOWN: never better than partly
    -- their own figure wasn't accepted as entered -- and 'with no reason given' is said, since that is what to probe;
    a file that shows THEIR figure against the manager's is a conflict to ask about. Moved UP: the manager's reason
    counts as the explanation."""
    md = _pm_perf_mod_dir(r) if r.get("moderation") else None
    if not md:
        return _pm_perf_justify_kpi_own(k, r, remark)
    m = dict(r["moderation"][-1])
    m["why"] = next((x.get("why") for x in reversed(r["moderation"]) if x.get("why")), "")   # any step's reason
    ftext = _pm_perf_file_text(r, r.get("_texts") or {})
    how = "their manager moderated it %s to %s" % (md, m["to_res"])
    if ftext and _figure_in_text(r.get("mod_value"), ftext):
        return "yes", how + ", and the file shows that figure"
    rm = _pm_perf_mod_row(r)
    if md == "up" and m.get("why"):
        rm["note"] = rm.get("note") or m["why"]
    km = dict(k, band=rm.get("band"), group=_pm_perf_group(rm), evidence="none" if k["evidence"] in (
        "supports", "found", "partly", "not_found", "not_shown") else k["evidence"])
    code, why = _pm_perf_justify_kpi_own(km, rm, remark)
    if md == "down":
        if k["evidence"] in ("supports", "found") or (k["evidence"] == "contradicts" and ftext
                                                       and _figure_in_text(r.get("value"), ftext)):
            return "partly", "the file shows their figure, but " + how + " \u2014 worth asking why"
        if _PERF_JUST_RANK.get(code, 1) > _PERF_JUST_RANK["partly"]:
            code = "partly"
        return code, how
    # moved UP: judged as moderated, the manager's reason standing in for an explanation -- said as the manager's
    return code, how + ("; no file backs it" if code != "yes" and k["evidence"] == "none" else "")


def _pm_perf_short(t, n=12):
    """A reason, cut to about n words, for a one-line 'why'."""
    w = (t or "").split()
    return " ".join(w[:n]).rstrip(",;:") + ("\u2026" if len(w) > n else "")


def _pm_perf_justify_kpi_own(k, r, remark):
    """The floor from their own evidence alone -- the file check against the figure they entered, their words."""
    ev, grp, expl = k["evidence"], k["group"], _pm_perf_explained(r, remark)
    strong = grp == "well" and k.get("band") in ("AE", "OU")
    if ev in ("supports", "found"):
        return "yes", "the file shows their figure"
    if ev == "contradicts":
        return "no", "the file doesn't match their result"
    if ev == "flagged":
        return "partly", "a file holds words written to an AI, so it wasn't read"
    if ev in ("partly", "not_found", "not_shown", "unread"):
        why = "the file couldn't be read" if ev == "unread" else "the file doesn't show their figure"
        return "partly", why + (", though they explain it" if expl else "")
    if strong:
        return (("partly", "explained in their words, but no file backs it") if expl
                else ("no", "above target with no file and no note behind it"))
    if grp == "well":
        return ("yes", "on target, and they explain it") if expl else ("partly", "on target; no note on how")
    if grp == "short":
        return (("yes", "below target, and they explain what got in the way") if expl
                else ("partly", "below target with no context given"))
    return "partly", "no file or explanation"


def _pm_perf_verdict_server(kpis, remark):
    """The server's overall verdict from the per-KPI codes: any result not justified -> not justified; every one
    justified AND a remark -> well justified; otherwise partly."""
    codes = [k.get("justified") for k in kpis if k.get("justified")]
    if not codes:
        return None
    if "no" in codes:
        return "not_justified"
    if all(c == "yes" for c in codes) and (remark or "").strip():
        return "well_justified"
    return "partly_justified"


def _pm_perf_verdict_why(kpis, remark):
    """One or two sentences from the server's own findings: the weakest results first."""
    order = sorted(kpis, key=lambda k: _PERF_JUST_RANK.get(k.get("justified"), 1))
    def _clause(w):
        w = (w or "").strip().rstrip(" .;")
        return (w[0].lower() + w[1:]) if w[:2] != w[:2].upper() or len(w) < 2 else w
    bits = ["%s: %s" % (k["kpi"], _clause(k.get("justified_why"))) for k in order[:3] if k.get("justified_why")]
    n = len((remark or "").split())
    tail = ("Their remark explains the period." if n >= 60 else
            ("Their remark is brief." if n else "They wrote no overall remark."))
    return ("; ".join(bits) + ". " + tail).strip() if bits else tail


def _pm_perf_pos_words(k):
    """Where a KPI's result lands, in words: 'above target' / 'on target' / 'below target' (from its group + band;
    not _pm_perf_position, which reads the figures)."""
    moved = bool(k.get("mod_dir"))   # a moderated result is worded where it now stands
    grp = k.get("mod_group") if moved else k.get("group")
    band = k.get("mod_band_now") if moved else k.get("band")
    if grp == "short":
        return "below target"
    return "above target" if band in ("AE", "OU") else "on target"


def _pm_perf_steps(kpis, verdict, reviewer=None):
    """What the reviewer might do next, from the server's findings -- always shown; the model can add. Worded for who
    is reading: a line manager decides on the results, a calibrator confirms a band (UI audit, 2026-09-29)."""
    calib = reviewer == "calibrator"
    out = []
    for k in sorted(kpis, key=lambda k: _PERF_JUST_RANK.get(k.get("justified"), 1)):
        j, ev = k.get("justified"), k.get("evidence")
        # a calibrator's step is one short line that says what to DO -- the table row beside it already says why
        # (UI audit, 2026-09-29: three two-line steps pushed the card past one view and repeated the rows)
        unreasoned = calib and k.get("mod_dir") and not any(m.get("why") for m in k.get("moderation") or [])
        theirs_vs_mod = "the file shows their figure, but" in (k.get("justified_why") or "")
        if ev == "flagged":
            out.append("Open the file on %s yourself \u2014 it holds words written to an AI, so the AI left it out."
                       % k["kpi"])
        elif ev == "contradicts" and not theirs_vs_mod:
            out.append(("Check the file on %s \u2014 it doesn't match their result." if calib else
                        "The file on %s doesn't match their result \u2014 check it before you decide.") % k["kpi"])
        elif unreasoned:
            out.append("Ask their manager why %s was moderated %s." % (k["kpi"], k["mod_dir"]))
        elif calib and k.get("mod_dir") == "down" and "the file shows their figure, but" in (k.get("justified_why") or ""):
            out.append("Ask their manager why %s was moderated down \u2014 the file shows their figure." % k["kpi"])
        elif j == "no":
            out.append(("Ask for evidence behind %s's %s result." % (k["kpi"], _pm_perf_pos_words(k))) if calib else
                       ("No supporting file for %s, a result %s \u2014 ask for evidence before you decide."
                        % (k["kpi"], _pm_perf_pos_words(k))))
        elif ev in ("not_found", "not_shown"):
            out.append(("Ask for a file on %s that shows their figure." if calib else
                        "The file on %s doesn't show their figure \u2014 ask for one that does.") % k["kpi"])
        elif j == "partly" and k.get("group") == "short":
            out.append(("Ask what held %s back." if calib else "Ask what held %s back \u2014 no context was given.")
                       % k["kpi"])
    if verdict == "well_justified" and not out:
        out.append("Nothing to query \u2014 every result is backed or explained." if calib
                   else "Nothing to query \u2014 you can take the results as entered.")
    return out


_VERDICT_PHRASE_RE = re.compile(r"\b(?:(?:only|just|fully|well|partly|partially|mostly|largely|not)[\s_]+)+justified\b",
                                re.I)


def _pm_perf_restate_verdict(text, verdict):
    """Every '<qualifier> justified' in the model's text says the verdict that stands (server-overruled cases)."""
    if not text:
        return text
    word = {"well_justified": "well justified", "partly_justified": "partly justified",
            "not_justified": "not justified"}.get(verdict)
    if not word:
        return text

    def _sub(m):
        return word[0].upper() + word[1:] if m.group(0)[:1].isupper() else word
    return _VERDICT_PHRASE_RE.sub(_sub, text)


def _pm_perf_apply_insight(kpis, rows, facts, model=None):
    """Set each KPI's justified / justified_why and return (verdict, verdict_why, steps). `model` (from the AI
    check): {"kpis": {row_id: {"justified", "why"}}, "verdict", "verdict_why", "steps"} -- each may only be
    as or LESS favourable than the server's; its words are kept only where its verdict is the one that stands."""
    model = model or {}
    remark = facts.get("remark") or ""
    by_id = {r["id"]: r for r in rows}
    for r in rows:
        r["_texts"] = (facts or {}).get("_texts") or {}
    for k in kpis:
        r = by_id.get(k.get("_rid")) or next((x for x in rows if x["kpi"] == k["kpi"]), {})
        code, why = _pm_perf_justify_kpi(k, r, remark)
        m = (model.get("kpis") or {}).get(r.get("id")) or {}
        mc = m.get("justified")
        # The one upgrade allowed: a result on or below target with no file, whose context the server couldn't
        # see (a remark can explain a shortfall without naming the KPI) -- the model read their words and its why
        # passed the grounding check. Never a strong result with nothing behind it, never a file issue.
        upgradable = (code == "partly" and k.get("evidence") == "none" and not k.get("mod_dir")
                      and not (k.get("group") == "well" and k.get("band") in ("AE", "OU")))
        if mc in _PERF_JUST_RANK and _PERF_JUST_RANK[mc] < _PERF_JUST_RANK[code]:
            code, why = mc, (m.get("why") or why)
        elif mc == "yes" and upgradable and m.get("why"):
            code, why = "yes", m["why"]
        elif mc == code and m.get("why"):
            why = m["why"]
        k["justified"], k["justified_why"] = code, why
        k.pop("_rid", None)
    for r in rows:
        r.pop("_texts", None)
    v_srv = _pm_perf_verdict_server(kpis, remark)
    v, why = v_srv, _pm_perf_verdict_why(kpis, remark)
    mv = model.get("verdict")
    if mv in _PERF_VERDICT_RANK and v_srv and _PERF_VERDICT_RANK[mv] <= _PERF_VERDICT_RANK[v_srv]:
        v = mv
        if model.get("verdict_why"):
            why = model["verdict_why"]
    return v, why, _pm_perf_steps(kpis, v, (facts or {}).get("reviewer_kind"))


def _pm_perf_plain(first, facts, texts):
    """The summary built ONLY from their figures, words and the server's file check -- it cannot invent.
    Used when the AI is off, fails, or its assessment doesn't hold up."""
    rows = facts.get("rows") or []
    kpis = []
    for r in rows:
        ev, note = _pm_perf_evidence(r, texts, plain=True)
        kpis.append(_pm_perf_kpi_entry(r, _pm_perf_read_plain(r), ev, note))
    rated = [k for k in kpis if k["group"] != "other"]
    on = sum(1 for k in rated if k["group"] == "well")
    read = _pm_perf_count_read(on, len(rated))
    nm = lambda c: PM_LABEL_NAMES.get(c, c or "not rated")
    bits = [read]
    well = [k for k in kpis if k["group"] == "well"]
    short = [k for k in kpis if k["group"] == "short"]
    if well:
        bits.append("On or above target: %s." % ", ".join("%s (%s, keyed %s)" % (k["kpi"], nm(k["band"]), k["result"])
                                                           for k in well))
    if short:
        bits.append("Below target: %s." % ", ".join("%s (%s, keyed %s)" % (k["kpi"], nm(k["band"]), k["result"])
                                                    for k in short))
    ev_bits = []
    for k in kpis:
        if k["evidence"] == "found":
            ev_bits.append("the file on %s has a matching figure" % k["kpi"])
        elif k["evidence"] == "not_found":
            ev_bits.append("the file on %s doesn't show the keyed figure" % k["kpi"])
        elif k["evidence"] == "unread":
            ev_bits.append("the file on %s couldn't be read" % k["kpi"])
        elif k["evidence"] == "flagged":
            ev_bits.append("a file on %s holds words written to an AI, so it was left out" % k["kpi"])
    if ev_bits:
        bits.append((ev_bits[0][0].upper() + ev_bits[0][1:] + "".join("; " + b for b in ev_bits[1:])) + ".")
    no_file = [k["kpi"] for k in kpis if k["evidence"] == "none"]
    if no_file:
        bits.append("No supporting file on %s." % " or ".join(no_file))
    for k in kpis:   # a calibrator's case: what their line manager did with the result (locked lines)
        for m in k.get("moderation") or []:
            bits.append("Their line manager (%s) moderated %s from %s to %s%s." % (
                m["by"], k["kpi"], m["from"], m["to"],
                (": \u201c%s\u201d" % _pm_perf_short(m["why"], 20)) if m["why"] else ", with no reason given"))
    for m in facts.get("mgr_remarks") or []:
        bits.append("Their line manager's remark (%s): \u201c%s\u201d" % (m["author"], _pm_perf_short(m["remark"], 28)))
    if facts.get("reviewer_kind") == "calibrator" and not (facts.get("mgr_remarks") or []) \
            and not any(k.get("moderation") for k in kpis):   # an HOD reads what the manager said, or that they didn't
        bits.append("Their line manager has not written a remark.")
    rm = facts.get("remark") or ""
    if rm:
        bits.append("Their remark: \u201c%s\u201d" % (rm if len(rm) <= 160 else rm[:160].rsplit(" ", 1)[0] + "…"))
    else:
        bits.append("They wrote no overall remark.")
    verdict, vwhy, steps = _pm_perf_apply_insight(kpis, rows, facts)
    # The one-sentence reason the card shows beside the verdict: the count, then what backs it (UI audit, 2026-09-29).
    read = _pm_perf_backing_read(read, kpis, verdict, facts.get("remark") or "", len(rated) - on)
    bits[0] = read
    if facts.get("reviewer_kind") == "calibrator":
        bits = [_pm_perf_case_plain(facts, kpis, verdict, read)]
    return {"paragraph": " ".join(bits), "read": read, "kpis": kpis, "verdict": verdict, "verdict_why": vwhy,
            "discuss": _pm_perf_merge_discuss(steps, [], limit=3, kpi_names=[k["kpi"] for k in kpis])}


_PERF_CASE_BOTTOM = {
    "well_justified": "The evidence bears out their results.",
    "partly_justified": "The evidence only partly bears out their results.",
    "not_justified": "The evidence doesn't bear out their results as they stand.",
}


def _pm_perf_degree(clause):
    """'well' / 'partly' / 'not' -- how strongly a bottom-line clause says the evidence bears the results out, or None."""
    c = (clause or "").lower()
    if re.search(r"(?:\bnot|n['\u2019]t)\s+(?:fully|entirely|completely|all)\b|\b(?:only\s+)?(?:partly|partially|in part)\b",
                 c):
        return "partly"
    if re.search(r"\b(?:not|never)\b|n['\u2019]t\b", c):
        return "not"
    if re.search(r"\b(?:fully|well|clearly|largely|mostly|borne out|bears? out|backed|supported|justified)\b", c):
        return "well"
    return None


def _pm_perf_case_bottom(text, verdict):
    """The case's BOTTOM LINE says the verdict that stands (2026-10-05 Luna probe: 3 of 8 opened 'only partly backed'
    under a 'Not justified' pill -- the model's own verdict, or the server's floor, disagreed with its first clause). The
    opening clause (to the first ':' or '.') is replaced by the server's bottom line when it states another degree; the
    rest of the paragraph is kept as written."""
    want = {"well_justified": "well", "partly_justified": "partly", "not_justified": "not"}.get(verdict)
    t = (text or "").strip()
    if not want or not t:
        return t
    m = re.search(r"[:.](?:\s|$)", t)
    head, rest = (t[:m.start()], t[m.start():]) if m else (t, "")
    got = _pm_perf_degree(head)
    if got is None or got == want:
        return t
    return _PERF_CASE_BOTTOM[verdict].rstrip(".") + rest


def _pm_perf_case_plain(facts, kpis, verdict, read):
    """A calibrator's plain summary as THE CASE (2026-10-05) -- the same order the model is asked for: the bottom line,
    what backs the results, what doesn't, then each view attributed (theirs, their line manager's, the tier below). Built
    only from the figures, the server's file check, their words and the reviewers' own notes, so it cannot invent."""
    nm = lambda c: PM_LABEL_NAMES.get(c, c or "not rated")
    q = lambda t, n: "\u201c%s\u201d" % _pm_perf_short(t, n).rstrip(".!? ")   # the sentence's own stop follows it
    out = [x for x in (_PERF_CASE_BOTTOM.get(verdict), read) if x]
    low1 = lambda t, d: (t[:1].lower() + t[1:]) if t else d   # 'the file shows ...' -- a KPI name inside keeps its case
    pro = ["%s (%s)" % (k["kpi"], low1((k.get("justified_why") or "").strip().rstrip("."), "backed"))
           for k in kpis if k.get("justified") == "yes"]
    con = ["%s (%s)" % (k["kpi"], low1((k.get("justified_why") or "").strip().rstrip("."), "not backed"))
           for k in kpis if k.get("justified") in ("partly", "no")]
    if pro:
        out.append("What backs it: %s." % "; ".join(pro))
    if con:
        out.append("What doesn't: %s." % "; ".join(con))
    for t in [t for t in facts.get("trail") or [] if t.get("cal") or t.get("avg")]:   # several calibrators, first
        if t.get("avg"):
            out.append("Weighted, their BU-level calibrators put them at %s%s." % (
                nm(t.get("band")), " so far (still to lock: %s)" % ", ".join(t["waiting"]) if t.get("waiting") else ""))
        else:
            note = (t.get("note") or "").strip()
            out.append("Their BU-level calibrator %s (%d%% of the call) %s %s%s." % (
                t.get("by") or "", t.get("weight") or 0,
                "kept them at" if t.get("from") == t.get("band") else "placed them at", nm(t.get("band")),
                (", noting %s" % q(note, 24)) if note else ", with no note"))
    rm = facts.get("remark") or ""
    if rm:
        out.append("They say: %s." % q(rm, 28))
    elif "overall remark" not in (read or ""):   # the read may already say it ('no files, no notes and no overall remark')
        out.append("They wrote no overall remark.")
    mods = [(k, m) for k in kpis for m in k.get("moderation") or []]
    for k, m in mods:
        out.append("Their line manager (%s) moderated %s from %s to %s%s." % (
            m["by"], k["kpi"], m["from"], m["to"],
            (", noting %s" % q(m["why"], 20)) if m["why"] else ", with no reason given"))
    for m in facts.get("mgr_remarks") or []:
        out.append("Their line manager's remark (%s): %s." % (m["author"], q(m["remark"], 28)))
    if not mods and not (facts.get("mgr_remarks") or []):
        out.append("Their line manager has written no remark.")
    for t in [t for t in facts.get("trail") or [] if not (t.get("cal") or t.get("avg"))]:
        note = (t.get("note") or "").strip()
        if re.match(r"\s*(Moved to fit the calibration curve|Set on their own results)", note):
            note = ""
        verb = "kept them at" if t.get("from") == t.get("band") else "placed them at"
        out.append("The %s %s %s%s." % (t["label"], verb, nm(t.get("band")),
                                          (", noting %s" % q(note, 24)) if note else ", with no note"))
    return " ".join(out)


_PM_COUNT_WORDS = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six", 7: "seven", 8: "eight"}


def _pm_perf_count_read(on, n):
    """How many KPIs met target, in words, never naming the person ('0 of 2 of ZZ's KPIs...' before)."""
    if not n:
        return "No results yet."
    if n == 1:
        return "Their one KPI %s." % ("met or beat target" if on else "came in below target")
    if on == n:
        return ("Both KPIs met or beat target" if n == 2 else "All %d KPIs met or beat target" % n) + "."
    if not on:
        return ("Both KPIs came in below target" if n == 2 else "None of the %d KPIs met target" % n) + "."
    return "%d of %d KPIs met or beat target." % (on, n)


def _pm_perf_backing_read(read, kpis, verdict, remark, n_short):
    """The count sentence with what backs it: 'Both KPIs came in below target, and their remark explains what got in
    the way.' / '..., but nothing backs them: no files, no notes and no overall remark.'"""
    if not kpis or read == "No results yet.":
        return read
    base = read.rstrip(".")
    files = sum(len(k.get("files") or []) for k in kpis)
    notes = sum(1 for k in kpis if (k.get("their_note") or "").strip())
    if verdict == "well_justified":
        tail = (", and their remark explains what got in the way" if (n_short and remark)
                else ", and the evidence backs it")
    elif not files and not notes and not remark.strip():
        tail = ", but nothing backs it: no files, no notes and no overall remark"
    elif verdict == "not_justified":
        tail = ", but not every result is backed"
    else:
        tail = ", but not all of it is backed or explained"
    return base + tail + "."


def _pm_perf_parse(raw):
    s = re.sub(r"^\s*```(?:json)?\s*|\s*```\s*$", "", (raw or "").strip())
    i, j = s.find("{"), s.rfind("}")
    if i < 0 or j <= i:
        return None
    try:
        obj = json.loads(s[i:j + 1], strict=False)   # (line breaks inside strings are common)
    except ValueError:
        return None
    return obj if isinstance(obj, dict) else None


# Words that would mislead against the server's figures (2026-09-25 review). A clause naming ONE KPI may not
# sound positive when it is below target, or negative when it is on / above target, unless the sentence is
# plainly reporting what the person claimed; a clause may not say a file backs a KPI whose file doesn't; a
# cause may be given only in the person's own words; and the rating is never discussed.
_PERF_POS_RE = re.compile(r"\b(beat|beats|beating|surpass\w*|outperform\w*|strong|stronger|strongest|"
                          r"better than (?:the |its |their )?target|ahead of (?:the |its |their )?target)\b", re.I)
_PERF_NEG_RE = re.compile(r"\b(missed|misses|fell short|falls short|short of (?:the |its |their )?target|"
                          r"underperform\w*|weak|weaker|weakest|worse than (?:the |its |their )?target|"
                          r"behind (?:the |its |their )?target)\b", re.I)
# 'above' / 'below' target read numerically -- a direction claim only on a higher-is-better KPI
_PERF_POS_HI_RE = re.compile(r"\babove (?:the |its |their )?target\b", re.I)
_PERF_NEG_HI_RE = re.compile(r"\bbelow (?:the |its |their )?target\b", re.I)
_PERF_ATTRIB_RE = re.compile(r"\b(says?|said|claims?|claimed|wrote|writes|remark|note|notes|according|"
                             r"describes?|described|believes?|reports?|reported)\b", re.I)
# a cause taken from a REVIEWER's words (the manager's remark or moderation reason, a tier's note) must be said as theirs
_PERF_REVIEWER_RE = re.compile(r"\b(manager|managers|moderat(?:ed|ion|ions|ing)|HOD|BU CEO|reviewers?|approvers?|"
                               r"calibrat\w*|tier)\b", re.I)
_PERF_BACK_RE = re.compile(r"\b(backs|backed|supports|supported|confirms|confirmed|verifies|verified|matches|"
                           r"shows the same)\b", re.I)
_PERF_NEGATION_RE = re.compile(r"\b(no|not|doesn't|does not|don't|isn't|without|neither|nor|never|fails? to|"
                               r"can't|cannot|nothing)\b", re.I)
_PERF_CAUSE_RE = re.compile(r"\b(because(?: of)?|due to|driven by|thanks to|owing to|as a result of|led to|"
                            r"caused by|on the back of|helped by|hit by|blam(?:e|es|ed|ing)|attribut\w+ (?:it |this )?to|"
                            r"credit(?:s|ed)? (?:it |this )?to)\s+([^.;:!?]+)", re.I)
_PERF_ADVICE_RE = re.compile(r"\b(rais\w*|lower\w*|mov(?:e|es|ed|ing)|bump\w*|upgrad\w*|downgrad\w*|deserv\w*|"
                             r"increas\w*|reduc\w*|higher)\b[^.]{0,40}\b(rating|rung|band|score|grade|level)\b|"
                             r"\b(rating|rung|band|score|grade)\b[^.]{0,25}\b(higher|lower|up|down|raised)\b", re.I)


def _pm_perf_clauses(text):
    for sent in re.split(r"(?<=[.!?])\s+", text or ""):
        for cl in re.split(r";|,\s*(?:and|but|while|whereas|although|though)\b|\s(?:but|while|whereas|although)\s",
                           sent):
            yield sent, cl


def _pm_perf_claim_error(text, rows, kpi=None, own_words="", ask=False, reviewer_words="", reviewer_names=()):
    """Why a field of the model's assessment misleads against the server's figures, or None. `kpi` is the row a
    per-KPI read is about (its clauses need not name it). `ask`: a point to raise (a request, not a claim) --
    'ask for a file that confirms X' isn't a claim that one does."""
    ev_ok = ("supports", "found", "partly")
    for sent, cl in _pm_perf_clauses(text):
        low = cl.lower()
        spots = [(m.start(), r) for r in rows for m in re.finditer(re.escape((r["kpi"] or "").lower()), low)
                 if r["kpi"]]
        named = list({id(r): r for _p, r in spots}.values())
        if not named and kpi is not None:
            named, spots = [kpi], [(0, kpi)]
        attributed = bool(_PERF_ATTRIB_RE.search(sent))
        if spots and not attributed:
            # each direction word is about the KPI named nearest to it in the clause
            for rx, bad, what, hi_only in (
                    (_PERF_POS_RE, "short", "positive about %s, which is below target", False),
                    (_PERF_NEG_RE, "well", "negative about %s, which is on or above target", False),
                    (_PERF_POS_HI_RE, "short", "positive about %s, which is below target", True),
                    (_PERF_NEG_HI_RE, "well", "negative about %s, which is on or above target", True)):
                for m in rx.finditer(cl):
                    r = min(spots, key=lambda sp: abs(sp[0] - m.start()))[1]
                    if hi_only and r.get("direction") != "higher is better":
                        continue
                    # a moderated KPI has two figures: a direction word true of either (theirs, or as the manager left
                    # it) isn't misleading -- 'their manager lowered it to 13.2, below target'
                    if _pm_perf_group(r) == bad and not (r.get("moderation")
                                                         and _pm_perf_group(_pm_perf_mod_row(r)) != bad):
                        return "sounds " + what % r["kpi"]
        if spots and not ask and not _PERF_NEGATION_RE.search(cl):
            # 'backed by the sign-off' is about the KPI named nearest to it in the clause -- or about every KPI
            # named when it says 'both' / 'all' / 'each'
            quant = bool(re.search(r"\b(?:backs|supports|confirms|backed|supported|confirmed)(?: by \w+(?: \w+)?)?"
                                   r"\s+(?:both|all|each)\b|\b(?:both|all|each)\b(?:\s+\w+){0,3}?\s+(?:are|were|is|"
                                   r"was)?\s*(?:backed|supported|confirmed)\b", low))
            for m in _PERF_BACK_RE.finditer(cl):
                # "their manager confirmed the result" / "their manager says it matches monthly reviews" is the manager's
                # view, not a file backing it -- unless the clause is about a file (GPT-6 Luna probe, 2026-09-30)
                near = cl[max(0, m.start() - 40):m.end() + 40]
                if re.search(r"\b(manager|approver|HOD)\b", near, re.I) and not re.search(
                        r"\b(file|files|sign-?off|report|sheet|document|attachment|evidence)\b", cl, re.I):
                    continue
                about = named if quant else [min(spots, key=lambda sp: abs(sp[0] - m.start()))[1]]
                for r in about:
                    if r.get("_evidence") not in ev_ok:
                        return "says a file backs %s, which the server's check doesn't show" % r["kpi"]
    have = {_rg_norm(w) for w in _rg_words((own_words or "") + " " + _pm_perf_word_forms(own_words))}
    have_rev = {_rg_norm(w) for w in _rg_words((reviewer_words or "") + " " + _pm_perf_word_forms(reviewer_words))}
    generic = {_rg_norm(w) for w in _PERF_SUMMARY_VOCAB.split()}
    for m in _PERF_CAUSE_RE.finditer(text or ""):
        words = [w for w in _rg_words(m.group(2))[:8] if _rg_norm(w) not in generic]
        if all(_rg_norm(w) in have for w in words):
            continue
        # a cause only a REVIEWER gave (their manager's reason, a tier's note) stands only when the sentence says so --
        # a calibrator must never read the manager's explanation as the person's own defence (2026-09-29 review)
        st = (text or "")[:m.start()]
        sent = (text or "")[max(st.rfind(". "), st.rfind("! "), st.rfind("? "), -2) + 2:]
        sent = re.split(r"(?<=[.!?])\s", sent, 1)[0]
        said_as_theirs = bool(_PERF_REVIEWER_RE.search(sent)) or any(
            n and len(n) > 3 and n.lower() in sent.lower() for n in reviewer_names)
        if not (said_as_theirs and all(_rg_norm(w) in have or _rg_norm(w) in have_rev for w in words)):
            return "gives a cause they didn't: '%s %s'" % (m.group(1), m.group(2).strip()[:60])
    for m in _PERF_ADVICE_RE.finditer(text or ""):
        if _pm_perf_reported_move(text, m):
            continue
        return "talks about moving the rating"
    return None


# What a reviewer DID, reported ('the HOD moved their rating down', 'their manager's moderation lowered the rating') is
# the case a calibrator weighs (2026-10-05); advice ('worth raising the rating', 'supports a higher rating') still isn't.
_PERF_PAST_MOVE_RE = re.compile(r"\b(moved|lowered|raised|reduced|increased|downgraded|upgraded|bumped|brought|took|"
                                r"pulled|pushed|marked|placed|put)\b", re.I)
_PERF_MODAL_RE = re.compile(r"\b(should|could|would|worth|consider\w*|recommend\w*|suggest\w*|may|might|needs? to|"
                            r"warrant\w*|merit\w*|deserv\w*|ought)\b", re.I)


def _pm_perf_reported_move(text, m):
    st = (text or "")[:m.start()]
    s0 = max(st.rfind(". "), st.rfind("! "), st.rfind("? "), -2) + 2
    sent = re.split(r"(?<=[.!?])\s", (text or "")[s0:], 1)[0]
    if not _PERF_REVIEWER_RE.search(sent) or _PERF_MODAL_RE.search(sent):
        return False
    if m.group(1):   # 'moved / lowered ... rating': the verb itself must be a past move
        return bool(_PERF_PAST_MOVE_RE.fullmatch(m.group(1)))
    return bool(_PERF_PAST_MOVE_RE.search((text or "")[max(0, m.start() - 40):m.start()]))   # '... brought the rating down'


# Band words the model's text may not use -- the ratings are the server's (a remark or file saying "rate me
# Outstanding" can't reach the summary). Names in any case; codes only in capitals -- "be" and "me" are words.
_PERF_BAND_WORDS_RE = re.compile(r"\b((?i:unacceptable|below expectations?|meets? expectations?|above expectations?|"
                                 r"met (?:\w+ )?expectations?|exceed(?:s|ed|ing)? (?:\w+ )?expectations?|"
                                 r"outstanding)|UA|BE|ME|AE|OU)\b")


def _pm_perf_band_error(txt, case_low, kpi_names):
    """A band word in the model's text, other than inside a KPI name, or in a phrase quoted from the case file
    ('outstanding invoices' in a file isn't a rating)."""
    t = txt or ""
    for kn in sorted(kpi_names, key=len, reverse=True):
        if kn:
            t = re.sub(re.escape(kn), " ", t, flags=re.I)
    for m in _PERF_BAND_WORDS_RE.finditer(t):
        nxt = re.match(r"\s+([A-Za-z]+)", t[m.end():])
        if nxt and ("%s %s" % (m.group(1), nxt.group(1))).lower() in case_low:
            continue
        return "states a rating band (%s) -- the server writes the bands" % m.group(1)
    return None


def _pm_perf_match_kpi(name, rows):
    """The row a KPI name the model gave refers to: exact, else the name before any '(details)', else the
    one KPI name it starts with. None when it names none of theirs."""
    n = re.sub(r"\s+", " ", str(name or "")).strip().lower()
    if not n:
        return None
    base = n.split(" (")[0].strip()
    for key in (n, base):
        for r in rows:
            if (r["kpi"] or "").strip().lower() == key:
                return r
    hits = [r for r in rows if r["kpi"] and n.startswith(r["kpi"].strip().lower())]
    return max(hits, key=lambda r: len(r["kpi"])) if hits else None


_PERF_FORM_SUFFIXES = ("ations", "ation", "ions", "ion", "ments", "ment", "ing", "ed", "es", "e", "s")


def _pm_perf_word_forms(text):
    """Other forms of the words in `text` ('consolidating' -> 'consolidation', 'improved' -> 'improvement'),
    so the grounding check doesn't count a reworded form of THEIR word as new. Never a new stem."""
    out = set()
    low = (text or "").lower()
    months = {"jan": "january", "feb": "february", "mar": "march", "apr": "april", "jun": "june", "jul": "july",
              "aug": "august", "sep": "september", "sept": "september", "oct": "october", "nov": "november",
              "dec": "december"}
    for ab in set(re.findall(r"\b(jan|feb|mar|apr|jun|jul|aug|sept?|oct|nov|dec)\b", low)):
        out.add(months[ab])     # 'Sep' in a sheet grounds 'September'
    for w in set(re.findall(r"[a-z]{5,}", low)):
        base = w
        for suf in _PERF_FORM_SUFFIXES:
            if w.endswith(suf) and len(w) - len(suf) >= 4:
                base = w[:-len(suf)]
                break
        for suf in ("ation", "ations", "ion", "ions", "tion", "tions", "ment", "ments", "ing", "ed", "e", "es", "s"):
            out.add(base + suf)
    return " ".join(sorted(out))


def _pm_perf_ai_check(facts, texts, raw, src, extra):
    """(parts, None) when the model's assessment holds up, else (None, why). Every text field is checked
    against the case file (no figure, name or much wording it doesn't carry), may name no rating band, and
    may not mislead against the server's figures (_pm_perf_claim_error: direction words vs target, file
    backing vs the server's check, causes only in their own words, no rating advice); KPI names must be
    theirs; a 'supports' the file can't back refuses the whole assessment, a 'contradicts' / 'partly' must
    cite figures in that file (_pm_perf_evidence). A KPI the model skipped gets the plain line. The server's
    own points are always kept in 'discuss'."""
    obj = _pm_perf_parse(raw)
    if not obj:
        return None, "not a JSON object"
    rows = facts.get("rows") or []
    case_low = (src or "").lower()
    kpi_names = [r["kpi"] for r in rows] + [h["kpi"] for h in facts.get("hr") or []]
    own = " ".join([facts.get("remark") or ""] + [r.get("note") or "" for r in rows]
                   + [f.get("note") or "" for r in rows for f in r.get("file_list") or []])
    # the REVIEWERS' words (a calibrator's case): the manager's remark and moderation reasons, and a lower tier's own note
    # (never a note the AI fit wrote -- that's the server's text, not a reviewer's). A cause from these must be said as
    # the reviewer's (_pm_perf_claim_error), never as the person's own.
    rev = " ".join([m.get("remark") or "" for m in facts.get("mgr_remarks") or []]
                   + [m.get("why") or "" for r in rows for m in r.get("moderation") or []]
                   + [t.get("note") or "" for t in facts.get("trail") or []
                      if not re.match(r"\s*(Moved to fit the calibration curve|Set on their own results)", t.get("note") or "")])
    rev_names = tuple({m.get("author") or "" for m in facts.get("mgr_remarks") or []}
                      | {m.get("by") or "" for r in rows for m in r.get("moderation") or []}
                      | {t.get("by") or "" for t in facts.get("trail") or []})
    # the server's evidence verdict per KPI, for the file-backing check (the model's own is checked below)
    for r in rows:
        r["_evidence"] = _pm_perf_evidence(r, texts, plain=True)[0]

    # word forms of words that ARE present count as present ('consolidating' grounds 'consolidation'), and
    # the first name's possessive
    initials = " ".join("".join(w[0] for w in re.findall(r"[A-Za-z]+", n)).upper() for n in kpi_names if n)
    _cnt = {len(rows), sum(len(r.get("file_list") or []) for r in rows),
            sum(1 for r in rows if r.get("moderation")),
            sum(1 for r in rows if _pm_perf_group(r) == "well"), sum(1 for r in rows if _pm_perf_group(r) == "short")}
    initials += " " + " ".join([str(c) for c in _cnt] + [_IDP_NUMWORD.get(c, "") for c in _cnt])
    extra2 = "%s KPI KPIs %s %s %s" % (extra or "", initials,
                              " ".join("%s's" % w for w in (extra or "").split() if w[:1].isalpha()),
                              _pm_perf_word_forms((src or "") + " " + own))

    def chk(txt, limit, kpi=None, ask=False):
        txt = re.sub(r"\s+", " ", str(txt or "")).strip()
        if not txt:
            return "", None
        if len(txt.split()) > limit:
            return None, "too long"
        err = (_summary_grounding_error(src, extra2, txt, _PERF_SUMMARY_VOCAB, _PERF_SUMMARY_STARTERS,
                                        "perf_summary", ratio=_PERF_INSIGHT_RATIO, floor=_PERF_INSIGHT_FLOOR)
               or _pm_perf_band_error(txt, case_low, kpi_names)
               or _pm_perf_claim_error(txt, rows, kpi=kpi, own_words=own, ask=ask, reviewer_words=rev,
                                       reviewer_names=rev_names))
        return (None, err) if err else (txt, None)
    try:
        paragraph, err = chk(obj.get("paragraph"), 160 if facts.get("reviewer_kind") == "calibrator" else 110)
        if err or not paragraph:
            return None, "paragraph: %s" % (err or "missing")
        overall, err = chk(obj.get("overall"), 80)
        if err or not overall:
            return None, "overall: %s" % (err or "missing")
        got = {}
        for k in obj.get("kpis") or []:
            if not isinstance(k, dict):
                continue
            r = _pm_perf_match_kpi(k.get("kpi"), rows)
            if not r or r["id"] in got:
                continue
            read, err = chk(k.get("read"), 55, kpi=r)
            if err:
                return None, "%s: %s" % (r["kpi"], err)
            note, err = chk(k.get("evidence_note"), 40, kpi=r)
            if err:
                return None, "%s evidence: %s" % (r["kpi"], err)
            ev = str(k.get("evidence") or "").strip().lower().replace(" ", "_").replace("-", "_")
            jwhy, err = chk(k.get("why"), 35, kpi=r)
            if err:
                return None, "%s why: %s" % (r["kpi"], err)
            jc = str(k.get("justified") or "").strip().lower()
            got[r["id"]] = {"read": read, "ev": ev, "note": note,
                            "justified": jc if jc in _PERF_JUST_RANK else None, "why": jwhy}
        if not got:
            return None, "no KPI assessed"
        discuss = []
        for d in (obj.get("discuss") or [])[:3]:
            t, err = chk(d, 28, ask=True)
            if err:
                return None, "discuss: %s" % err
            if t:
                discuss.append(t)
        vwhy_m, err = chk(obj.get("verdict_why"), 70)
        if err:
            return None, "verdict_why: %s" % err
        vm = str(obj.get("verdict") or "").strip().lower().replace(" ", "_")
        kpis = []
        for r in rows:
            g = got.get(r["id"]) or {}
            ev, note = _pm_perf_evidence(r, texts, g.get("ev"), g.get("note") or "")
            # A file it says backs the result when the keyed figure isn't in it -- or a 'contradicts' / 'partly'
            # citing figures that aren't in that file: its paragraph would repeat the claim, so the whole
            # assessment is refused (the plain summary is shown) rather than patched.
            if g.get("ev") in _PERF_EVIDENCE and ev != g.get("ev"):
                return None, "%s: the file verdict '%s' doesn't hold up against the file" % (r["kpi"], g.get("ev"))
            kpis.append(_pm_perf_kpi_entry(r, g.get("read") or _pm_perf_read_plain(r), ev, note))
    finally:
        for r in rows:
            r.pop("_evidence", None)
    verdict, vwhy, steps = _pm_perf_apply_insight(kpis, rows, facts, model={
        "kpis": {rid: {"justified": g.get("justified"), "why": g.get("why")} for rid, g in got.items()},
        "verdict": vm if vm in _PERF_VERDICT_RANK else None, "verdict_why": vwhy_m})
    # The server's evidence floor overruled the model (it said "partly", the rules say "not"): its paragraph must say
    # the verdict that stands, or the card contradicts itself -- the blind review's most common flaw, all five cases
    # this (model comparison, 2026-09-30).
    if vm in _PERF_VERDICT_RANK and verdict and verdict != vm:
        paragraph = _pm_perf_restate_verdict(paragraph, verdict)
        overall = _pm_perf_restate_verdict(overall, verdict)
    if facts.get("reviewer_kind") == "calibrator":
        paragraph = _pm_perf_case_bottom(paragraph, verdict)
    # "Nothing to query" stands alone: the model's "Accept X as entered" steps say it again, and a real question from
    # the model replaces the line (staging Luna probe, 2026-09-29: the clean line + two "Accept ..." steps).
    _clean = [x for x in steps if x.startswith("Nothing to query")]
    if _clean:
        _asks = [x for x in discuss if not re.match(r"^\s*(?:accept|take)\b", x, re.I)]
        steps = [x for x in steps if x not in _clean] + ([] if _asks else _clean)
        discuss = _asks
    return {"paragraph": paragraph, "read": overall, "kpis": kpis, "verdict": verdict, "verdict_why": vwhy,
            "discuss": _pm_perf_merge_discuss(steps, discuss, limit=3, kpi_names=[r["kpi"] for r in rows])}, None


_POLISH_VERBS = {"reports": "report", "gives": "give", "gave": "gave", "has": "have", "shows": "show",
                 "provides": "provide", "provided": "provided", "writes": "write", "wrote": "wrote",
                 "explains": "explain", "explained": "explained", "cites": "cite", "attaches": "attach",
                 "attached": "attached", "notes": "note", "claims": "claim", "states": "state", "says": "say",
                 "keyed": "keyed", "entered": "entered", "met": "met", "beat": "beat", "missed": "missed",
                 "meets": "meet", "beats": "beat", "misses": "miss", "offers": "offer", "offered": "offered"}


def _insight_polish(text, full_name=""):
    """One insight sentence as the reader sees it (UI audit, 2026-09-29). Rewrites, never refuses -- so the AI pass
    rate is unchanged: the person is 'they' (their name is on the card once, as its heading), the prompt's jargon is
    plain words ('case file', 'keyed', 'substantiated'), and the punctuation is clean ('.;', '..', ' -- ', '42 %')."""
    t = re.sub(r"\s+", " ", str(text or "")).strip()
    if not t:
        return t
    names = [w for w in re.findall(r"[A-Za-z][A-Za-z'-]*", full_name or "") if len(w) >= 2]
    first = names[0] if names else ""
    if first:
        f = re.escape(first)
        t = re.sub(r"(^|(?<=[.!?]\s))%s(?:\u2019s|'s)\b" % f, "Their", t, flags=re.I)
        t = re.sub(r"\b%s(?:\u2019s|'s)\b" % f, "their", t, flags=re.I)

        def _subj(m):
            lead, verb = m.group(1), m.group(2)
            v = _POLISH_VERBS.get(verb.lower())
            if v is None:
                return m.group(0)
            return ("They " if lead is not None else "they ") + v
        t = re.sub(r"(^|(?<=[.!?]\s))?\b%s\s+(\w+)" % f, _subj, t, flags=re.I)
    t = re.sub(r"\bthe case file\b", "their record", t, flags=re.I)
    t = re.sub(r"\bcase file\b", "record", t, flags=re.I)
    t = re.sub(r"\b(neither|either|each|every|both|any|one|a|no) keyed (result|figure)(s?)\b",
               lambda m: "%s %s%s" % (m.group(1), m.group(2), m.group(3)), t, flags=re.I)
    t = re.sub(r"\b(?:the )?keyed (result|figure)(s?)\b", lambda m: "their %s%s" % (m.group(1), m.group(2)), t,
               flags=re.I)
    t = re.sub(r"\bKeyed\b", "Entered", t)
    t = re.sub(r"\bkeyed\b", "entered", t)
    t = re.sub(r"\bindependently substantiated\b", "backed", t, flags=re.I)
    t = re.sub(r"\bsubstantiated\b", "backed", t, flags=re.I)
    t = re.sub(r"(\d) %", r"\1%", t)
    t = t.replace(" -- ", " \u2014 ").replace("--", "\u2014")
    t = re.sub(r"\.\s*;", ";", t)
    t = re.sub(r"(?<!\.)\.\.(?!\.)", ".", t)
    t = re.sub(r"(^|[.!?]\s+)([a-z])", lambda m: m.group(1) + m.group(2).upper(), t)   # a sentence starts upper-case
    return t


def _pm_perf_polish(data, full_name=""):
    """_insight_polish over every text field of a structured performance insight."""
    if not data:
        return data
    p = lambda s: _insight_polish(s, full_name)
    for key in ("verdict_why", "read", "paragraph"):
        if data.get(key):
            data[key] = p(data[key])
    for k in data.get("kpis") or []:
        for key in ("read", "justified_why", "evidence_note"):
            if k.get(key):
                k[key] = p(k[key])
        if k.get("result"):
            k["result"] = re.sub(r"(\d) %", r"\1%", k["result"])
    data["discuss"] = [p(d) for d in data.get("discuss") or []]
    return data


def _pm_perf_data(facts, source, parts, retry=False):
    ov = facts.get("overall")
    ov_ok = bool(ov and ov.get("value") is not None)
    return {"v": 5, "source": source, "retry": bool(retry), "mgr_remarks": facts.get("mgr_remarks") or [],
            "verdict": parts.get("verdict"), "verdict_label": _PERF_VERDICT_LABEL.get(parts.get("verdict")),
            "verdict_why": parts.get("verdict_why") or "",
            "overall": {"score": _pm_fig(ov["value"]) if ov_ok else None,
                        "band": ov.get("label") if ov_ok else None,
                        "scored": facts.get("scored") or 0, "lines": facts.get("lines") or 0},
            "paragraph": parts.get("paragraph") or parts["read"],
            "read": parts["read"], "kpis": parts["kpis"], "discuss": parts["discuss"],
            "hr": facts.get("hr") or [], "remark": facts.get("remark") or ""}


# How each file verdict reads in words (the popout's chip and the flat text).
_PERF_EVIDENCE_LABEL = {"supports": "File backs the result", "partly": "File partly backs it",
                        "contradicts": "File doesn't match the result", "not_shown": "File doesn't show the result",
                        "found": "Keyed figure is in the file", "not_found": "Keyed figure isn't in the file",
                        "unread": "Couldn't read the file", "none": "No supporting file",
                        "flagged": "File holds words aimed at the AI"}


def _pm_perf_text(data, headline):
    """The flat text of a structured summary: the manager agent reads it, and it is what the cache keeps
    as `summary` beside the structured `data`."""
    parts = [headline]
    if data.get("verdict"):
        parts.append("Verdict: %s -- %s" % (_PERF_VERDICT_LABEL.get(data["verdict"], data["verdict"]),
                                            data.get("verdict_why") or ""))
    parts.append(data.get("paragraph") or data.get("read") or "")
    for grp, lab in (("well", "On or above target"), ("short", "Below target"), ("other", "Other")):
        ks = [k for k in data.get("kpis") or [] if k["group"] == grp]
        if ks:
            parts.append("%s: %s" % (lab, " ".join(
                "%s (%s; keyed %s%s): %s [%s%s]%s" % (
                    k["kpi"], PM_LABEL_NAMES.get(k["band"], k["band"] or "not rated"), k["result"],
                    (", target %s" % k["target"]) if k.get("target") is not None else "", k["read"],
                    _PERF_EVIDENCE_LABEL.get(k["evidence"], ""),
                    (" -- " + k["evidence_note"]) if k.get("evidence_note") else "",
                    (" Justified: %s (%s)." % (k["justified"], k.get("justified_why") or ""))
                    if k.get("justified") else "")
                for k in ks)))
    if data.get("discuss"):
        parts.append("Suggested next steps: %s" % "; ".join(data["discuss"]))
    return " ".join(p for p in parts if p).strip()


def _pm_perf_summary_for(db, u, report_id, generate=False, calib=None, stale_ok=False):
    """{summary, data, source ('ai' | 'plain' | 'none'), pending} -- one direct report's performance, assessed
    for THIS approver (Chris, 2026-09-24/25). `data` is the structured read: a one-paragraph read (what the
    Team summary's popout shows), the overall read, each KPI grouped on/above vs below target (from the
    figures) with its band (the server's), what happened, and whether its files back the keyed result -- the
    model's assessment when on and it holds up against the case file (their figures, words and the files'
    CONTENTS), else the plain one. `summary` is the same as flat text. Cache per subject / cycle / approver,
    valid while the figures, their words and files are unchanged; a plain one made because the model FAILED
    (a timeout, an error, the time budget) or before an image could be read is retried after 10 minutes --
    one the model got wrong is not (it would fail the same way). Only generate=True (POST
    /review/team/pm-summary, never a chat turn) reads files or calls the model, within a time budget. The PM
    AI switch (ai_on('ai_pm')) governs it."""
    import time as _time
    # calib = {"tier", "scope_key", "reviewer"}: the same assessment for a CALIBRATOR (2026-09-28) -- every line, the
    # manager's locked remark, its own cache (pm_calib_summaries: never the approver rows, which a calibrator who is
    # also an approver would otherwise overwrite on every switch).
    # they didn't submit, and their line manager assessed them on their behalf (2026-10-26): nothing of theirs to
    # assess, and no model call -- said plainly, so no one reads the line manager's figures as their own account
    _per = active_pm_period(db)
    if _per and db.execute(
            "SELECT 1 FROM pm_kpi_approvals a JOIN pm_kpi_targets t ON t.id = a.kpi_target_id WHERE t.cycle_id=? "
            "AND t.subject_id=? AND a.on_behalf=1 LIMIT 1", (_per["id"], report_id)).fetchone():
        return {"summary": "They didn't submit, so their line manager assessed them on their behalf: the figures and "
                           "the remark are the line manager's, not an account in their own words.",
                "data": None, "source": "behalf", "pending": False}
    status, first, words, extra, facts = _pm_perf_source(db, u, report_id,
                                                         scope="calibrator" if calib else "approver")
    if status == "none":
        _per = active_pm_period(db)
        if _per and report_id in kpis_bu_only_ids(db, _per["id"], [report_id]):   # all Group People's (2026-10-26)
            return {"summary": "Every KPI here is a business unit result Group People fills in, so there is nothing of "
                               "theirs to weigh up.", "data": None, "source": "none", "pending": False}
        return {"summary": "No KPI results submitted yet.", "data": None, "source": "none", "pending": False}
    headline = _pm_perf_headline(facts)
    facts["reviewer_kind"] = "calibrator" if calib else "manager"
    if calib:   # how it reached this tier: the LOCKED tiers below it, with who moved and their note
        facts["trail"] = _pm_perf_trail(db, report_id, calib["tier"])
    _fullname = (db.execute("SELECT full_name FROM users WHERE id=?", (report_id,)).fetchone() or {"full_name": ""})["full_name"] or ""
    cid = active_pm_period(db)["id"]
    file_ids = [f["id"] for r in facts["rows"] for f in r["file_list"]]
    # ...and what writes it (the model and its summary reasoning effort): changing either regenerates the insight
    fp = hashlib.sha256((("v9calib\n" if calib else "v5\n") + ai_draft.summary_signature() + "\n" + headline + "\n"
                         + words + "\n" + json.dumps(
        [[r["id"], r["value"], r["target"], r["band"], r["mod_band"], [f["id"] for f in r["file_list"]]]
         + ([r.get("mod_value"), r.get("moderation"), r.get("locked"), r.get("approvers")] if calib else [])
         for r in facts["rows"]] + ([facts.get("trail")] if calib else []), default=str)).encode("utf-8")).hexdigest()
    if calib:
        row = db.execute("SELECT summary, source, fingerprint, data, "
                         "(created_at < datetime('now','-10 minutes')) AS stale FROM pm_calib_summaries "
                         "WHERE subject_id=? AND cycle_id=? AND tier=? AND scope_key=?",
                         (report_id, cid, calib["tier"], calib["scope_key"])).fetchone()
    else:
        row = db.execute("SELECT summary, source, fingerprint, data, "
                         "(created_at < datetime('now','-10 minutes')) AS stale FROM pm_perf_summaries "
                         "WHERE subject_id=? AND cycle_id=? AND approver_id=?", (report_id, cid, u["id"])).fetchone()
    ai_ok = bool(ai_on("ai_pm"))
    cached = None
    if row and row["data"]:
        try:
            cached = json.loads(row["data"])
        except ValueError:
            cached = None
    plain_due = bool(row and row["stale"] and ai_ok and cached and row["source"] == "plain" and cached.get("retry"))
    imgs_due = bool(row and row["stale"] and ai_ok and cached and not plain_due and _attach_unread_images(db, file_ids))
    # stale_ok (a page's batch read, never a request that generates): a plain reading made because the model failed is
    # served while the worker asks the model again ("retrying") -- not hidden behind a spinner for the whole outage
    if row and row["fingerprint"] == fp and cached and not imgs_due and (not plain_due or (stale_ok and not generate)):
        return {"summary": row["summary"], "data": cached, "source": row["source"], "pending": False,
                **({"retrying": True} if plain_due else {})}
    if not generate:
        return {"summary": None, "data": None, "source": None, "pending": True}
    t0 = _time.monotonic()
    texts = _attach_read_all(db, file_ids, allow_model=ai_ok, deadline=t0 + 30)
    facts["_texts"] = texts
    data, again = None, False
    if ai_ok and _time.monotonic() - t0 < 32:
        case = _pm_perf_case_text(facts, texts)
        try:
            parts, _why = _pm_perf_ai_check(facts, texts, ai_draft.assess_performance(
                first, case, timeout=22, reviewer=(calib or {}).get("reviewer") or "LINE MANAGER"), case,
                " ".join([extra] + [t.get("by") or "" for t in facts.get("trail") or []]))
            if parts:
                data = _pm_perf_data(facts, "ai", parts)
        except Exception:   # any model failure (incl. a bare timeout) -> the plain summary, tried again later
            data, again = None, True
    elif ai_ok:
        again = True        # the files used the time budget: the plain one now, the assessment next time
    if not data:
        data = _pm_perf_data(facts, "plain", _pm_perf_plain(first, facts, texts), retry=again)
    data = _pm_perf_polish(data, _fullname)
    text = _pm_perf_text(data, headline)
    if calib:
        db.execute("INSERT INTO pm_calib_summaries(subject_id, cycle_id, tier, scope_key, fingerprint, summary, source, "
                   "data, created_at) VALUES (?,?,?,?,?,?,?,?,datetime('now')) ON CONFLICT(subject_id, cycle_id, tier, "
                   "scope_key) DO UPDATE SET fingerprint=excluded.fingerprint, summary=excluded.summary, "
                   "source=excluded.source, data=excluded.data, created_at=excluded.created_at",
                   (report_id, cid, calib["tier"], calib["scope_key"], fp, text, data["source"], json.dumps(data)))
    else:
        db.execute("INSERT INTO pm_perf_summaries(subject_id, cycle_id, approver_id, fingerprint, summary, source, "
                   "data, created_at) VALUES (?,?,?,?,?,?,?,datetime('now')) ON CONFLICT(subject_id, cycle_id, "
                   "approver_id) DO UPDATE SET fingerprint=excluded.fingerprint, summary=excluded.summary, "
                   "source=excluded.source, data=excluded.data, created_at=excluded.created_at",
                   (report_id, cid, u["id"], fp, text, data["source"], json.dumps(data)))
    db.commit()
    return {"summary": text, "data": data, "source": data["source"], "pending": False}


def _journey_team_plan_data(db, u, report_id, rname):
    """One report's development-plan review -- the FULL manager surface: comment on
    each goal, on the plan overall, and on the career profile, then record the
    career conversation (which closes the plan). Read-only PROJECTION via
    pm_idp_for + the career helpers; each goal carries its `id` (the write handle)
    and an `actionable` flag equal to the /idp/team routes' own gate (plan shared,
    not draft/closed). The career comment has no plan-state gate (route gates on
    the approver relationship only), so it stays available whenever a plan does.
    Every write is button-driven to the existing /idp/team routes; this never
    writes."""
    period = active_pm_period(db)
    yr = pm_idp_plan_year(period) if period else None
    idp = pm_idp_for(db, yr, report_id) if yr else None
    status = (idp or {}).get("status")
    shared = status == "shared"     # the window goal-edit / review / close operate in
    goals = []
    # A DRAFT plan is private to its author (as on the classic pages): no goals until it is shared.
    for g in (((idp or {}).get("goals") or []) if _idp_visible_to_manager(idp) else []):
        goals.append({
            "id": g.get("id"),
            "area": g.get("area") or "",
            "target_date": g.get("target_date") or "",
            "experience": g.get("action_experience") or "",
            "exposure": g.get("action_exposure") or "",
            "education": g.get("action_education") or "",
            "progress_status": g.get("progress_status") or "",
            "progress_note": g.get("progress_note") or "",
            "manager_comment": g.get("manager_comment") or "",
            "actionable": shared,
            # the gap the goal closes (the drafter stores it on the goal): its kind and the level held / needed
            "gap_kind": g.get("gap_kind") or "",
            "have_level": g.get("have_level"), "required_level": g.get("required_level"),
        })
    # The career profile is reference for the conversation + its own manager comment
    # (available whenever you approve any of their KPI lines -- no plan-state gate).
    prof = pm_career_profile_for(db, report_id) or {}
    mob = prof.get("mobility")
    mob_label = next((m["label"] for m in PM_CAREER_MOBILITY if m["key"] == mob), mob) if mob else ""
    career = {
        "aspiration_now": prof.get("aspiration_now") or "",
        "aspiration_mid": prof.get("aspiration_mid") or "",
        "aspiration_long": prof.get("aspiration_long") or "",
        "strengths": prof.get("strengths") or "",
        "mobility": mob_label,
        "mobility_note": prof.get("mobility_note") or "",
        "preferences": prof.get("preferences") or "",
        "mentor": prof.get("mentor") or "",
        "career_comment": prof.get("manager_comment") or "",
        "career_actionable": True,
    }
    conv = pm_career_conversation_for(db, yr, report_id) if yr else None   # an older record only (none since 2026-10-21)
    # The AI summary of their plan -- read from the cache only (never generated inside a turn); the
    # client fetches a missing one per report (POST /review/team/idp-summary).
    summ = _idp_summary_for(db, report_id, generate=False, viewer=u)
    owner = _idp_remark_owner(db, report_id)
    mine = owner is None or owner == u["id"]
    # their own deadline passed with no plan shared: nothing is the manager's to do (2026-11-08); the same test as the row's
    missed = (status not in ("shared", "closed") and bool(period)
              and _behalf_part_closed(db, "idp_self", period["id"], report_id))
    return {"kind": "plan_review", "report_id": report_id, "report_name": rname, "missed": missed,
            "goals": goals, "status": status,
            "manager_comment": (idp or {}).get("manager_comment") or "",
            "ai_summary": summ.get("summary"), "summary_source": summ.get("source"),
            "summary_data": summ.get("data"),   # the FIT insight: verdict, why, scores, next steps (2026-09-28)
            "summary_pending": bool(summ.get("pending")),
            "remark_mine": mine,        # the LINE MANAGER writes the one overall IDP remark
            "remark_open": shared and mine,
            "plan_actionable": shared,
            "career": career,
            "conversation": ({"held_on": conv.get("held_on") or "",
                              "note": conv.get("note") or "",
                              "recorded_by": conv.get("recorded_by_name") or ""}
                             if conv else None),
            "aiming": _idp_plan_aiming(db, report_id, prof),
            "closed": status == "closed", "closed_at": (idp or {}).get("closed_at") or "",
            # Approve plan closes it, once the overall remark is in (Chris, 2026-10-21: no career conversation)
            "can_close": shared, "can_approve": shared and bool(((idp or {}).get("manager_comment") or "").strip())}


# A chosen role is an AIM, never a promotion (Chris, 2026-10-22: "do we mention the career track or goal user picks serves
# just as aspiration and not a guarantee promotion?"; canvas "OneHR Career Aim Wording",
# [design canvas link removed]). Said where they pick (the direction card), right after the pick,
# in the Share pop-up, on the dashboard's Career Plan panel and on the line manager's Approve card; the agents hold it.
CAREER_AIM_PICKED = "An aim guides your development; it isn't a promotion."
CAREER_AIM_RULE = ("A role they pick is where they're AIMING: it shapes their development goals. NEVER call it a "
                   "promotion, a promise of a move, or something they will get, and never imply that finishing the "
                   "plan or a full skills match earns it.")


def _career_aim_line(db, u):
    """The Share pop-up's line: the role they're aiming for (pm_career_profile.target_profile_id, with its grade), and
    that it's an aim, not a promotion. Without a pick, the plan itself is the aim."""
    t = db.execute("SELECT p.job_title, p.job_grade, p.active FROM pm_career_profile c JOIN tc_job_profiles p "
                   "ON p.id = c.target_profile_id WHERE c.subject_id=?", (u["id"],)).fetchone()
    if t and (t["job_title"] or "").strip():
        role = _tc_retired_title(t["job_title"].strip(), t["active"]) + (" (JG%s)" % t["job_grade"] if t["job_grade"] not in (None, "") else "")
        return {"role": role, "say": "It guides your development goals; it isn't a promotion or a promise of a move."}
    return {"role": None, "say": "Your Career Plan guides your development. It isn't a promotion or a promise of a move."}


def _idp_plan_aiming(db, report_id, prof):
    """Where they're aiming, for the manager's review of their plan (Chris, 2026-10-21, canvas 8J9QzZua7VGUD8rsgXcqQk):
    the role they picked in their Career Plan (pm_career_profile.target_profile_id), its grade, and how many of its
    skills they match by the career card's own reading (_career_role_skills; no count when nothing of their own job is
    assessed). A match is not a promotion decision. None when they haven't picked a role."""
    tid = (prof or {}).get("target_profile_id")
    if not tid:
        return None
    t = db.execute("SELECT id, job_title, job_grade, active FROM tc_job_profiles WHERE id=?", (tid,)).fetchone()
    if not t:
        return None
    rep = db.execute("SELECT * FROM users WHERE id=?", (report_id,)).fetchone()
    match = total = 0
    if rep:
        here, _anchor = tc_profile_for_user(db, rep, prof)
        role = _career_role_skills(db, rep, here, [{"profile_id": t["id"]}])[0]
        match, total = role.get("match") or 0, role.get("total") or 0
    return {"title": _tc_retired_title(t["job_title"] or "", t["active"]), "grade": t["job_grade"], "match": match, "total": total}


def _journey_active_team_mode(want):
    """summary (the whole-team score table) unless the client asks for one report's
    detail (its full stage table). Never stored -- echoed per request, re-derived each
    turn. The combined "Full profile" card is gone (Chris, 2026-09-24: the per-report AI
    summary replaces it); an old ?mode=profile link opens that person's detail."""
    if want in ("detail", "profile"):
        return "detail"
    return "summary"


def _pm_lm_moderated_ids(db, mid, cycle_id, subject_ids):
    """Which of these people's KPI results the manager has moderated at all: ONE batched read for the whole team.
    A line counts when this manager holds a figure for it -- a committed adjustment or a saved draft -- that differs
    from the person's own figure. A confirm, an empty draft, a figure equal to theirs, or an on-behalf figure (the
    person has none of their own) is not moderation. Feeds `lm_moderated` on the Team summary rows, which the bulk
    approve box reads to name who the AI+ check flagged that the manager has not looked at."""
    ids = [int(x) for x in subject_ids]
    if not ids:
        return set()
    ph = ",".join("?" * len(ids))
    rows = db.execute(
        "SELECT DISTINCT t.subject_id FROM pm_kpi_targets t "
        "JOIN pm_kpi_results r ON r.kpi_target_id = t.id "
        "WHERE t.cycle_id=? AND t.subject_id IN (%s) AND ("
        " EXISTS (SELECT 1 FROM pm_kpi_approvals a WHERE a.kpi_target_id=t.id AND a.acted_by=? "
        "         AND a.action='adjust' AND a.on_behalf=0 AND a.adjusted_value IS NOT NULL "
        "         AND ABS(a.adjusted_value - r.actual_value) > 0.000000001) "
        " OR EXISTS (SELECT 1 FROM pm_kpi_moderation_drafts d WHERE d.kpi_target_id=t.id AND d.approver_id=? "
        "         AND d.adjusted_value IS NOT NULL AND ABS(d.adjusted_value - r.actual_value) > 0.000000001))"
        % ph, [cycle_id] + ids + [mid, mid]).fetchall()
    return {r[0] for r in rows}


def _team_row_people(db, ids):
    """{user id: {"job_title", "department", "job_grade"}} for the Team summary's rows, ONE query. Display only: the phone's
    row names who each person is under their name (phone view, piece B, 2026-11-07); no rule reads it."""
    ids = [int(i) for i in ids]
    if not ids:
        return {}
    out = {}
    for r in db.execute("SELECT id, job_title, department, job_grade FROM users WHERE id IN (%s)" % ",".join("?" * len(ids)), ids):
        out[r["id"]] = {"job_title": r["job_title"] or "", "department": r["department"] or "",
                        "job_grade": r["job_grade"] if r["job_grade"] is not None else ""}
    return out


def _journey_team_summary(db, u, active_stage):
    """One row per direct report for the active stage -- the whole-team overview the
    manager lands on: each member's FINAL score/status, a scannable table they drill
    into. Read-only. PM reuses the overall the nav's preview already computed; TM/IDP
    aggregate per report here (only when the summary is asked for)."""
    reports = _journey_team_reports(db, u, active_stage)
    rows = []
    if active_stage == "pm_review":
        _pm_period = active_pm_period(db)
        _lm_mod = _pm_lm_moderated_ids(db, u["id"], _pm_period["id"], [r["id"] for r in reports]) if _pm_period else set()
        for r in reports:
            # can_approve = this manager has actionable lines to lock (bulk-approve eligible).
            # + the AI summary of their performance (score + their own remark), cache only (Chris,
            # 2026-09-24); the client fills a missing one per person, never inside a chat turn.
            summ = _pm_perf_summary_for(db, u, r["id"], generate=False)
            rows.append({"id": r["id"], "name": r["name"], "done": r["done"],
                         "status": r["meta"], "wait_why": r.get("wait_why"),
                         "action": r.get("action"), "can_approve": r.get("pend", 0) > 0,
                         "behalf": r.get("behalf"), "on_behalf": r.get("on_behalf"),
                         "lm_moderated": r["id"] in _lm_mod,
                         "score": r.get("score"), "band": r.get("band"),
                         "self_score": r.get("self_score"), "self_band": r.get("self_band"),
                         **({"transfer": r["transfer"]} if r.get("transfer") else {}),
                         "ai_summary": summ.get("summary"), "summary_data": summ.get("data"),
                         "summary_source": summ.get("source"),
                         "summary_pending": bool(summ.get("pending"))})
    elif active_stage == "tm_review":
        cid = active_cycle_id(db)
        for r in reports:
            a = db.execute("SELECT id, status FROM tc_assessments WHERE subject_id=? AND cycle_id=?",
                           (r["id"], cid)).fetchone()
            trows, _g = _tc_rows(db, cid, r["id"], a["id"] if a else None)
            shared = bool(a and a["status"] in ("submitted", "reviewed"))   # a draft is private to its author
            demo = sum(1 for x in trows if x.get("effective") == "yes") if shared else None
            # can_approve = submitted + every competency rated (bulk-approve eligible).
            can_appr = bool(a and a["status"] == "submitted" and trows
                            and all(x.get("effective") for x in trows))
            # The potential band with the manager's calls + their own, read as the person's card reads it
            # (_lm_potential_view: the 360 where the manager may see it, plus the competency), so the row and the
            # card never disagree (2026-10-24: the row said "Low potential" from the competency alone while the card
            # said Mid); and the AI summary of their self-assessment -- cache only (Chris, 2026-09-25).
            summ = _tc_summary_for(db, r["id"], generate=False)
            rep = db.execute("SELECT * FROM users WHERE id=?", (r["id"],)).fetchone() if shared else None
            pv = _lm_potential_view(db, u, cid, rep, a) if rep else None
            pv_pot = (pv or {}).get("pot") or {}
            rows.append({"id": r["id"], "name": r["name"], "done": r["done"],
                         "status": r["meta"], "action": r.get("action"), "can_approve": can_appr,
                         "behalf": r.get("behalf"), "on_behalf": r.get("on_behalf"),
                         "lm_moderated": any(x.get("moderated") for x in trows),   # a competency answered differently
                         "demonstrated": demo, "total": len(trows),
                         "band": (pv["move"]["to"] if pv else _tc_competency_band(db, r["id"], cid, "effective")),
                         "self_band": (pv["move"]["from"] if pv else _tc_competency_band(db, r["id"], cid, "self")),
                         "band_basis": ("combined" if pv_pot.get("basis") == "combined"
                                        else "360" if pv_pot.get("basis") == "360_only" else "competency"),
                         "ai_summary": summ.get("summary"), "summary_data": summ.get("data"),
                         "summary_source": summ.get("source"),
                         "summary_pending": bool(summ.get("pending"))})
    else:  # plan_review -- the AI summary of each person's plan (cache only; the client fills gaps)
        period = active_pm_period(db)
        yr = pm_idp_plan_year(period) if period else None
        for r in reports:
            summ = _idp_summary_for(db, r["id"], generate=False, viewer=u)
            # the Result column is the plan's goal count once it is shared (UX review F17); a draft is theirs alone
            shared = summ.get("status") in ("shared", "closed")
            goals = (db.execute("SELECT COUNT(*) FROM pm_idp_goals g JOIN pm_idp i ON i.id=g.idp_id WHERE i.subject_id=? "
                                "AND i.plan_year=? AND TRIM(COALESCE(g.area,''))!=''", (r["id"], yr)).fetchone()[0]
                     if shared and yr else None)
            rows.append({"id": r["id"], "name": r["name"], "done": r["done"], "status": r["meta"],
                         "action": r.get("action"), "shared": shared, "goals": goals,
                         "ai_summary": summ.get("summary"), "summary_data": summ.get("data"),
                         "summary_source": summ.get("source"),
                         "summary_pending": bool(summ.get("pending"))})
    # Who needs you first (Chris, 2026-09-30: "same goes to all table with action required"): the reports come by
    # name, and a stable sort keeps that order inside each group.
    # who each row is, for the phone's row (title, department, job grade: one batched read; the client words it, as the
    # Department Review's rows do)
    _who = _team_row_people(db, [r["id"] for r in rows])
    for r in rows:
        r.update(_who.get(r["id"], {}))
    rows.sort(key=_team_attention_rank)
    out = {"kind": "team_summary", "stage": active_stage, "rows": rows}
    # the people who didn't submit, theirs to assess on their behalf until their own part closes (2026-10-26)
    n_beh = sum(1 for r in rows if r.get("behalf"))
    if n_beh:
        out["behalf"] = {"n": n_beh, "closes": _when_short(window_dates(
            db, "tc_approve" if active_stage == "tm_review" else "pm_approve", active_cycle_id(db))[1])}
    if active_stage == "plan_review":   # nobody has shared a plan: one line, not a table of dashes (UX review F24)
        out["none_shared"] = bool(rows) and not any(r.get("shared") for r in rows)
    return out


def _journey_team_perf_summary(db, u):
    """A compact, read-only overview of the manager's WHOLE team, for the 'how is my
    team doing / give me an overview' inquiry (the summarize_team tool). Performance
    first (PM band spread + moderation progress + standouts / who needs attention),
    then competency and development-plan completion. Reuses the per-report summary
    builders so the numbers match the Team-summary widget, and returns a small dict the
    MODEL narrates (NO 'render'). Headline-first insertion order so the loop's 400-char
    feed cap can only ever drop the trailing name lists, never the numbers."""
    pm = _journey_team_summary(db, u, "pm_review")["rows"]

    def _eff(r):
        # The effective band: the manager's moderated band if there is one, else the
        # employee's own self-rating (some lines may not be moderated yet).
        return r.get("band") or r.get("self_band")

    graded = [r for r in pm if _eff(r) in PM_BAND_ORDER]
    dist = pm_label_distribution([{"label": _eff(r)} for r in graded])
    perf = {b: dist[b] for b in PM_BAND_ORDER if dist.get(b)}   # non-zero, worst->best
    reviewed = sum(1 for r in pm if r.get("done"))
    to_lock = sum(1 for r in pm if r.get("can_approve"))
    standouts = [r["name"] for r in graded if _eff(r) in ("AE", "OU")][:2]
    watch = [r["name"] for r in graded if _eff(r) in ("UA", "BE")][:2]
    tm = _journey_team_summary(db, u, "tm_review")["rows"]
    plan = _journey_team_summary(db, u, "plan_review")["rows"]
    # since 2026-10-21: approved (closed) / remark in, ready to approve / needs the remark
    plan_agreed = sum(1 for r in plan if r.get("status") == "Approved")
    plan_remarked = sum(1 for r in plan if r.get("status") == "Ready to approve"
                        or (r.get("status") or "").endswith("remark given"))
    plan_ready = sum(1 for r in plan if r.get("status") == "Needs your remark")
    return {
        "ok": True,
        "team": len(pm),
        "performance": perf,
        "moderation": {"reviewed": reviewed, "to_lock": to_lock,
                       "not_scored": len(pm) - len(graded)},
        "competency": {"reviewed": sum(1 for r in tm if r.get("done")), "of": len(tm),
                       "demonstrated": sum(r.get("demonstrated") or 0 for r in tm),
                       "total": sum(r.get("total") or 0 for r in tm)},
        "idp": {"agreed": plan_agreed, "remarked": plan_remarked, "ready": plan_ready,
                "not_shared": sum(1 for r in plan if r.get("status") == "Not shared yet"),
                "didnt_submit": sum(1 for r in plan if r.get("status") == "Didn't submit"), "of": len(plan)},
        "standouts": standouts,
        "watch": watch,
    }


def _journey_team_overview_core(db, u, active_stage, report_id, mode="detail"):
    """The active manager stage's widget data, tagged with the stage so ONE client
    picks the right widget. mode='summary' -> the whole-team score table; 'detail' ->
    one focused report's full table. {stage, data}; data is None when nothing to show."""
    if not active_stage:
        return {"stage": active_stage, "data": None}
    if active_stage == CHAIR_STAGE:   # the Executive Chairman's Group Talent Box: the released final bands, read only
        return {"stage": active_stage, "data": _chair_box_payload(
            db, u, (request.values.get("bg") or "").strip(), (request.values.get("company") or "").strip())}
    if active_stage == CHAIRL_STAGE:   # his leaders' Talent Box (P4)
        return {"stage": active_stage, "data": _chairlead_payload(db, u, (request.values.get("bg") or "").strip())}
    if active_stage == "talent_box":   # the BG CEO's Talent Box (2026-09-30): the page's own data, for the picked BU
        return {"stage": active_stage, "data": _journey_talent_box_overview(db, u)}
    if active_stage == "group_calib":   # the Group Chief's Talent Box, the BG CEO's card for their group (2026-10-13)
        _tb_use_group()
        return {"stage": active_stage, "data": _journey_talent_box_overview(db, u)}
    if active_stage == "calibration":   # the distribution vs the curve + the roster (the assistant's widget)
        sc = _journey_calib_scope(db, u)
        data = None
        if sc:
            data = dict(_pm_calib_assist_overview(db, u, sc[2], sc[0], sc[1])["data"])
            data["return_to"] = url_for("review_journey", view=_journey_req_view(db, u), stage="calibration")
            # a lock from the curve comes back to the curve (not to person 1)
            data["return_to_curve"] = url_for("review_journey", view=_journey_req_view(db, u), stage="calibration", phase="curve")
        return {"stage": active_stage, "data": data}
    if active_stage == "calibration_pot":   # the same card, on the potential axis
        sc = _pot_calib_scope(db, u)
        data = None
        if sc:
            data = dict(_pot_calib_overview(db, u, sc))
            data["return_to"] = url_for("review_journey", view=_journey_req_view(db, u), stage="calibration_pot")
            data["return_to_curve"] = url_for("review_journey", view=_journey_req_view(db, u), stage="calibration_pot", phase="curve")
            _tier, _ctx = sc[0], sc[2]
            _pend = (calibration_pending_children(db, _ctx["cycle_id"], _tier, _ctx["business_group"],
                                                  _ctx["scope_key"] if _tier == "buceo" else None)
                     if _tier in ("buceo", "bgceo") else [])
            data["pending"] = ([("%s (%s)" % (p[0], p[1]) if _tier == "bgceo" else p[1]) for p in _pend]
                               if _pend else [])
            data["breach_message"] = _calib_breach_message(data["breaches"]) if data.get("breaches") else ""
            data["lock_strict"] = calib_lock_strict()
            if not data.get("review"):   # a department review keeps its own order: who needs the HOD first, the
                # decided last (_pot_calib_overview). Re-sorting it by name here put the not-final people below the
                # saved ones (Chris, 2026-10-02: "the pending/unfinished doesn't stay on top"); performance never did.
                data["rows"] = sorted(data.get("rows") or [], key=lambda r: ((r.get("name") or "").lower(), r.get("id")))
            # no default band on the potential curve: say how many still have none before they lock
            data["n_unbanded"] = sum(1 for r in data["rows"] if not r.get("current_band") and not r.get("is_self"))
        return {"stage": active_stage, "data": data}
    if mode == "summary":
        return {"stage": active_stage, "data": _journey_team_summary(db, u, active_stage)}
    data = None
    if report_id:
        row = db.execute("SELECT full_name FROM users WHERE id=?", (report_id,)).fetchone()
        rname = row["full_name"] if row else "—"
        if active_stage == "pm_review":
            data = _journey_team_pm_data(db, u, report_id, rname)
        elif active_stage == "tm_review":
            data = _journey_team_tm_data(db, u, report_id, rname)
        elif active_stage == "plan_review":
            data = _journey_team_plan_data(db, u, report_id, rname)
    return {"stage": active_stage, "data": data}


MANAGER_CHAT_MAX = 40   # messages of one report's thread handed to the model


_MCHAT_SCOPED_STAGES = ("calibration", "calibration_pot", "talent_box", "group_calib")



# Each part's window (Admin > Open & close dates, 2026-10-02): the sentence the card shows when this role's window
# for the part is closed (or not open yet), so the person sees it before they type anything. An HOD's department review
# already says it through its own `closed` (_hod_review_closed reads the same window).
_JOURNEY_STAGE_CELL = {"account": "pm_results", "checkin": "pm_results", "feedback": "f360", "competency": "tc_self",
                       "career_plan": "idp_self", "pm_review": "pm_approve", "tm_review": "tc_approve",
                       "plan_review": "idp_review"}


def _journey_note_subject(db, u, stage, focus=None):
    """Whose work a journey card is, for the window and its reopen pass: the person on their own parts; the colleague
    in focus on the 360 (`focus` = the assignment id; 0 when there is none)."""
    if stage == "feedback":
        aid = focus or _feedback_focus(db, u, active_cycle_id(db), None)
        r = db.execute("SELECT subject_id FROM assignments WHERE id=? AND assessor_id=?",
                       (aid, u["id"])).fetchone() if aid else None
        return r["subject_id"] if r else 0
    return u["id"] if stage in ("account", "checkin", "competency", "career_plan") else 0


def _mine_left_unsubmitted(db, u, cell):
    """Their own KPI check-in (pm_results) or self-assessment (tc_self) closed with nothing submitted (2026-10-26)."""
    cid = active_cycle_id(db)
    if not _behalf_part_closed(db, cell, cid, u["id"]):
        return False
    if cell == "tc_self":
        a = db.execute("SELECT status FROM tc_assessments WHERE subject_id=? AND cycle_id=?", (u["id"], cid)).fetchone()
        return (not a or a["status"] not in ("submitted", "reviewed")) and bool(db.execute(
            "SELECT 1 FROM tc_assignments WHERE cycle_id=? AND subject_id=? LIMIT 1", (cid, u["id"])).fetchone())
    if pm_review_locked(db, u["id"], cid):
        return False
    # their OWN lines only (2026-11-05): a BU KPI Group People fills is not theirs to submit, so an all-BU person (or
    # one whose own lines are all in) is never "left unsubmitted"
    return _pm_own_unsubmitted(db, u["id"], cid) > 0


def _journey_window_note(db, u, stage, subject_id=None, chat=False):
    """The closed-window sentence for the part on screen, or None. `subject_id` is whose work it is (a report on the
    Team side, 0 on its summary): HR's reopen gives that one person's card a pass, never the whole team's. `chat=True`
    asks for the chat box: it also covers an HOD's department review, whose card says it through its own `closed`
    (Chris, 2026-10-20: "after deadline no action can be done ... the chat will be disabled, user can just read the past
    conversation")."""
    if stage in _JOURNEY_STAGE_CELL:
        w = window_closed(db, _JOURNEY_STAGE_CELL[stage], subject_id=subject_id)
        # their own part closed with nothing submitted: it's their line manager's now (Chris's pick, 2026-10-26: a note on
        # their card, no email; canvas 7)
        if w and subject_id == u["id"] and stage in ("account", "checkin", "competency") \
                and _mine_left_unsubmitted(db, u, "pm_results" if stage != "competency" else "tc_self"):
            w += " You didn't submit, so your line manager assesses this on your behalf."
        return w
    tier = _journey_view_tier(db, u)
    if stage == "talent_box":
        return window_closed(db, "tb_bgceo", scope=_late_screen_scopes(db, u, stage, tier))
    if stage == "group_calib":   # the Group Chief's Talent Box shares the BG CEO's dates; a late pass for THIS group opens it (2026-11-07)
        return window_closed_tier(db, "group", "both", scope=_late_screen_scopes(db, u, stage, "group"))
    if stage in ("calibration", "calibration_pot") and tier and (tier != "hod" or chat):
        # a late pass is the scope on screen's alone (2026-10-31): the other unit's card stays closed
        return window_closed_tier(db, tier, "pm" if stage == "calibration" else "pot",
                                  scope=_late_screen_scopes(db, u, stage, tier))
    return None


def _late_screen_scopes(db, u, stage, tier):
    """The scope keys of the BU / group / business group on screen in a leader stage, for a late pass (None for a tier with
    none; [] when the scope can't be resolved, so no pass opens it)."""
    if tier == "bgceo":
        return [u["bgceo_bg"]] if u["bgceo_bg"] else []
    if tier == "hod":   # an HOD's Department Review pass is their own id's (2026-11-07)
        return [str(u["id"])]
    if tier == "group":   # a Group Chief's, the group on screen
        gs = _journey_group_scope(db, u)
        return [GC_SCOPE_PREFIX + str(gs[0])] if gs else []
    if tier != "buceo":
        return None
    sc = (_journey_calib_scope(db, u, tier=tier) if stage == "calibration"
          else _pot_calib_scope(db, u, tier=tier) if stage == "calibration_pot" else None)
    return _late_ctx_scopes(sc[2] if sc else None)


def _late_note_for(db, u, stage, subject_id=None, cid=None):
    """The amber line on the card of a part Group People gave this person more time on ({text, part, until, chip} or None;
    canvas boards S1, L3, L4): "Group People gave you until {until} to finish this. {Part} closed for others on {close}."
    The person's own parts, a line manager's follow-on for the report on screen, a leader's scope on screen only (a BG
    CEO's adds the units that stay locked). `chip` is the rail's "Open for you until ..."; never says "late pass"."""
    if not u:
        return None
    cid = cid or active_cycle_id(db)
    cell, scopes = _JOURNEY_STAGE_CELL.get(stage), None
    if cell is None:
        tier = _journey_view_tier(db, u)
        if stage == "talent_box" and tier == "bgceo":
            cell, scopes = "tb_bgceo", _late_screen_scopes(db, u, stage, tier)
        elif stage in ("calibration", "calibration_pot") and tier == "buceo":
            cell, scopes = ("pm_buceo" if stage == "calibration" else "pot_buceo"), _late_screen_scopes(db, u, stage, tier)
        elif stage in ("calibration", "calibration_pot") and tier == "hod":   # the HOD's Department Review (2026-11-07)
            cell, scopes = ("pm_hod" if stage == "calibration" else "pot_hod"), _late_screen_scopes(db, u, stage, tier)
        elif stage == "group_calib":   # a Group Chief's group (2026-11-07)
            cell, scopes = "tb_bgceo", _late_screen_scopes(db, u, stage, "group")
        else:
            return None
    if cell in _LATE_SUBJECT_CELLS and not subject_id:
        return None
    cells = _LATE_CELL_ALIAS.get(cell, (cell,))
    if cell == "f360" or cell in LATE_LEADER_CELLS:
        subject_id = None
    if not any(window_state(db, x, cid) == "closed" for x in cells):
        return None   # nothing is closed for others: the pass changes nothing on screen
    rows = _late_held_rows(db, u["id"], cell, cid, subject_id if cell in _LATE_SUBJECT_CELLS else None, scopes)
    if not rows:
        return None
    r = rows[0]
    until = _late_disp(r["until_at"])
    _o, closes = window_dates(db, cell, cid)
    subj = _WINDOW_SUBJECT.get(cell, "It")
    text = "Group People gave you until %s to finish this. %s closed for others on %s" % (
        until, subj, _late_when(closes) if closes else "its date")   # '1 Nov 2026', no zero on the day, as `until`
    if cell == "tb_bgceo" and not str(r["scope_key"] or "").startswith(GC_SCOPE_PREFIX):
        locked = [display_company(r["business_group"] or "", x["company"]) for x in _late_bg_units(db, cid, r["scope_key"])[0]
                  if x["locked"]]
        if locked:
            text += "; %s stays locked" % " and ".join(locked)
    return {"part": cell, "text": text + ".", "until": until, "chip": "Open for you until " + until}


def _late_agent_note(db, u, stage):
    """The leader agents' line when Group People gave this leader more time on the scope on screen (2026-10-31): the new
    time, never "closed", never how they got it. '' when they hold none."""
    n = _late_note_for(db, u, stage, 0)
    if not n:
        return ""
    return ("MORE TIME: this part closed for everyone else, and Group People gave THIS leader until %s to finish it for the "
            "scope on screen, so it is OPEN for them now and you help them as normal (moving people, and their Lock click). "
            "Say that time if they ask when it closes. NEVER tell them it is closed, over or past its deadline, and never "
            "offer to ask for more time. Never call it a pass or an extension, and do not explain how they got it: just the "
            "time. Any other unit or group stays closed." % n["until"])


def _late_chip(stage=None, focus=None):
    """The navigator's amber chip ("Open for you until ...") for the part on screen, or ''. A template global."""
    if not has_request_context() or not session.get("user_id"):
        return ""
    try:
        db = get_db()
        u = current_user()
        if not u or not stage:
            return ""
        subj = _journey_note_subject(db, u, stage)
        if not subj and stage in ("pm_review", "tm_review", "plan_review"):
            try:
                subj = int(focus or 0)
            except (TypeError, ValueError):
                subj = 0
        n = _late_note_for(db, u, stage, subj)
        return n["chip"] if n else ""
    except Exception:   # noqa: BLE001 -- a chip never breaks the page
        return ""


app.jinja_env.globals["late_chip"] = _late_chip


def _journey_team_overview(db, u, active_stage, report_id, mode="detail"):
    """The manager-side card's payload (_journey_team_overview_core) plus its window note."""
    ov = _journey_team_overview_core(db, u, active_stage, report_id, mode)
    if isinstance(ov, dict) and ov.get("stage"):
        subj = report_id if (report_id and mode != "summary") else 0
        ov["window_note"] = _journey_window_note(db, u, ov["stage"], subj)
        # the chat box's lock: the card's note, or an HOD's closed department review (its card says so itself)
        ov["chat_lock"] = ov["window_note"] or (_journey_window_note(db, u, ov["stage"], subj, chat=True)
                                                if ov["stage"] in ("calibration", "calibration_pot") else None)
        ov["reopen_note"] = _reopen_note_for(db, u, ov["stage"], subj) if subj else None
        ov["late_note"] = _late_note_for(db, u, ov["stage"], subj)   # a late pass (2026-10-31): the amber line
        if ov["stage"] == CHAIR_STAGE:   # nothing is typed here: the box is read only (2026-10-29)
            ov["chat_lock"] = "Read only: use the box above."
        if ov["stage"] == CHAIRL_STAGE:   # his box is worked on the card, never by typing (P4)
            ov["chat_lock"] = "Move or Place a leader, then Lock."
        if ov["stage"] in ("calibration", "calibration_pot") and isinstance(ov.get("data"), dict):
            units = _journey_bu_units(db, u, ov["stage"])
            if units:
                ov["data"]["bu_units"] = units
    return ov


def _journey_bu_units(db, u, stage):
    """A BU CEO of several units, in their BU view: each unit as a pill above the calibration card -- its people,
    locked (with the day) or their turn, the one on screen lit, each a link that switches to it (?bu_unit=, kept in
    the session). Each unit is calibrated and locked on its own (admin round 4, canvas B3). [] otherwise."""
    if _journey_view_tier(db, u) != "buceo":
        return []
    seats = buceo_seats(db, u["id"])
    grps = bu_groups_of_calibrator(db, u["id"])   # their calibration groups, a pill each (2026-10-22)
    if len(seats) + len(grps) < 2:
        return []
    pick = next((k for t, k in calibration_tier_of(db, u) if t in ("buceo", "bugrp")), None)
    cid = active_cycle_id(db) or 0
    tbl = "calibration_sessions" if stage == "calibration_pot" else "pm_calibration_sessions"
    out, seen = [], set()
    for g_ in grps:
        bg, co, key = g_["business_group"], g_["company"], BU_GROUP_PREFIX + str(g_["id"])
        n = db.execute("SELECT COUNT(*) FROM users WHERE business_group=? AND %s AND role!='admin' AND %s"
                       % (bu_group_member_sql(), calibration_population_sql()), (bg, g_["id"])).fetchone()[0]
        r = db.execute("SELECT locked_at FROM %s WHERE cycle_id=? AND tier='buceo' AND scope_key=? AND business_group=?"
                       % tbl, (cid, key, bg)).fetchone()
        at = r["locked_at"] if r and r["locked_at"] else None
        out.append({"company": key, "label": bu_group_label(bg, g_), "people": n, "group": True,
                    "on": bool(pick) and len(pick) > 2 and pick[2] == g_["id"],
                    "locked": _st_day(_myt(at)) if at else None,
                    "href": url_for("review_journey", view="bu", stage=stage, bu_unit=key)})
    for bg, co in seats:
        units = _bu_units_of(db, cid, bg, co)   # units calibrated together this cycle are one pill (row 6)
        if (bg, units[0]) in seen:
            continue
        seen.add((bg, units[0]))
        j = calib_join(db, cid, bg, co)
        n = db.execute("SELECT COUNT(*) FROM users WHERE business_group=? AND company IN (%s) AND NOT %s AND role!='admin' "
                       "AND " % (",".join("?" * len(units)), bu_grouped_sql()) + calibration_population_sql(),
                       [bg] + units).fetchone()[0]
        r = db.execute("SELECT locked_at FROM %s WHERE cycle_id=? AND tier='buceo' AND scope_key=? AND business_group=?"
                       % tbl, (cid, units[0], bg)).fetchone()
        at = r["locked_at"] if r and r["locked_at"] else None
        out.append({"company": co, "label": j["label"] if j else (display_company(bg, co) or co), "people": n,
                    "on": bool(pick) and len(pick) == 2 and tuple(pick) in {(bg, m) for m in units},
                    "locked": _st_day(_myt(at)) if at else None,
                    "href": url_for("review_journey", view="bu", stage=stage, bu_unit=co)})
    return out if len(out) > 1 else []

def _mchat_scope(stage):
    """The thread scope of a manager-chat row: the leader view's tier ('hod' / 'buceo' / 'bgceo') for a calibration
    or Talent Box part, so each leader view keeps its own conversation; None for everything else. A BU CEO of several
    units keeps one conversation per unit ('buceo|<unit>', admin round 4)."""
    if stage not in _MCHAT_SCOPED_STAGES:
        return None
    tier = _journey_view_tier()
    if tier == "buceo" and has_request_context():
        cu = current_user()
        seats = buceo_seats(get_db(), cu["id"]) if cu else []
        grps = bu_groups_of_calibrator(get_db(), cu["id"]) if cu else []   # a group keeps its own thread (2026-10-22)
        if len(seats) + len(grps) > 1 or grps:
            pick = next((k for t, k in calibration_tier_of(get_db(), cu) if t in ("buceo", "bugrp")), None)
            return "buceo|%s" % bu_scope_pick_key(pick) if pick else tier
    return tier


def _manager_chat_history(db, u, cid, report_id, stage=None):
    """The manager's conversation about ONE report this cycle, oldest-first. Scoped
    to (reviewer, cycle, report) so one report's thread is never fed into another's
    context. Mirrors _review_chat_history; the stage tag is not shown to the model.
    Calibration is ONE thread for the whole scope (report NULL, stage 'calibration')."""
    if report_id is None and stage in _MCHAT_SCOPED_STAGES:
        # one thread per leader view (scope = its tier, 2026-09-30); an older untagged row belongs to the person's
        # first calibration tier, where it was said
        scope = _mchat_scope(stage)
        first = next((t for t, _k in calibration_tier_of(db, u)), None)
        rows = db.execute(
            "SELECT role, content, quick_replies, card, created_at FROM pm_manager_chat WHERE reviewer_id=? AND cycle_id=? "
            "AND report_id IS NULL AND stage=? AND (scope=? OR (scope IS NULL AND ?)) ORDER BY id DESC LIMIT ?",
            (u["id"], cid, stage, scope, 1 if (scope is None or scope == first) else 0,
             MANAGER_CHAT_MAX)).fetchall()
    elif report_id is None:
        return []
    else:
        rows = db.execute(
            "SELECT role, content, quick_replies, card, stage, created_at FROM pm_manager_chat "
            "WHERE reviewer_id=? AND cycle_id=? AND report_id=? ORDER BY id DESC LIMIT ?",
            (u["id"], cid, report_id, MANAGER_CHAT_MAX)).fetchall()
    out = []
    for r in reversed(rows):
        m = {"role": r["role"], "content": r["content"], "created_at": r["created_at"]}   # UTC; the move check reads it (4-06)
        # the part it was said in: a remark episode (the "yes" that saves a draft) never crosses from one part to
        # another -- a PM remark draft must not be saved as the IDP remark (review, 2026-09-29)
        if "stage" in r.keys() and r["stage"]:
            m["stage"] = r["stage"]
        if r["quick_replies"]:
            try:
                m["quick_replies"] = json.loads(r["quick_replies"])
            except (ValueError, TypeError):
                pass
        if r["card"]:
            try:
                m["card"] = json.loads(r["card"])
            except (ValueError, TypeError):
                pass
        out.append(m)
    return out


def _journey_team_history_response(db, u):
    """The manager journey's resume payload. Read-only; replays the manager's own
    thread for the focused report from pm_manager_chat (empty -> the client fires
    the opener turn: a warm greeting + the table)."""
    st = review_state(db, u)
    active_stage = _journey_active_team_stage(st, request.values.get("stage", ""))
    mode = _journey_active_team_mode(request.values.get("mode"))
    report = (_journey_active_report(db, u, active_stage, request.values.get("report"))
              if active_stage else None)
    ov = _journey_team_overview(db, u, active_stage, report, mode)
    _ovd = (ov or {}).get("data") or {}
    # an HOD's whole department review in: the wrap-up card closes the chat (2026-10-02); only looked for once the
    # part on screen is in, so an open review never pays for the other part's table
    _wrap = (_dept_review_wrapup(db, u, st) if active_stage in ("calibration", "calibration_pot")
             and (_ovd.get("locked") or _ovd.get("closed")) else None)
    # ...and a BU CEO's calibration, both parts locked: the chat closes (2026-10-06)
    _cdone = (_calib_done(db, u, st) if active_stage in ("calibration", "calibration_pot") and _ovd.get("locked")
              else None)
    # a Talent Box that has not opened replays nothing: an earlier line of the chat may hold its head-counts (Chris, 2026-11-04)
    _hist = ([] if (active_stage in ("talent_box", "group_calib") and _tb_hidden_msg(db, u))
             else _manager_chat_history(db, u, active_cycle_id(db), report, stage=active_stage))
    return jsonify(ok=True, messages=_hist,
                   overview=ov, stage=active_stage, report=report,
                   mode=mode, view=_journey_req_view(db, u), dept_wrapup=_wrap, calib_done=_cdone,
                   calib_locked=bool(active_stage in _MCHAT_SCOPED_STAGES
                                     and (ov.get("data") or {}).get("locked")),
                   modtabs_html=_journey_modtabs_html(db, u, st, active_stage, view=_journey_req_view(db, u)),
                   nav_html=_journey_nav_html(db, u, st, active_stage, view=_journey_req_view(db, u), report=report, mode=mode),
                   available=ai_draft.review_agent_available())


# ---------------------------------------------------------------------------
# The conversational MANAGER agent (Phase 3). The model converses and PROPOSES a
# moderation/comment; the server re-checks the SAME gate the module route enforces
# and does every write through the SAME extracted helper, so the chat and the
# widgets can never moderate differently. Mirrors the employee journey loop over the
# manager axis (a focused REPORT + the three team stages). No new route.
# ---------------------------------------------------------------------------
def _mgr_int(v):
    try:
        return int(v)
    except (TypeError, ValueError):
        return None


def _mgr_report_name(db, report_id):
    r = db.execute("SELECT full_name FROM users WHERE id=?", (report_id,)).fetchone()
    return r["full_name"] if r else "this person"


_MGR_ERR_MSG = {
    "forbidden": "you can't act on this person right now",
    "not_reviewable": "their assessment isn't submitted for review yet",
    "not_theirs": "that item isn't on this person's list",
    "bad_answer": "answer must be Demonstrate or Developing",
    "not_submitted": "their assessment isn't submitted yet",
    "not_shared": "their plan hasn't been shared yet",
    "not_actionable": "this line isn't awaiting your action",
    "conflict": "someone already acted on this line — refresh and try again",
    "bad_number": "that isn't a valid number",
    "bad_date": "use a date like 2026-09-10",
    "not_found": "I couldn't find that item",
    "gate": "you can't act on this plan right now",
}


def _mgr_err_msg(err):
    return err.get("msg") or _MGR_ERR_MSG.get(err.get("reason"), "that didn't work")


def _mgr_tool_moderate_kpi(db, u, cid, report_id, args):
    """Reversible: draft a moderated value + tell the manager the new rating."""
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    kid = _mgr_int(args.get("kpi_id"))
    if kid is None:
        return {"ok": False, "error": "which KPI?"}
    line = db.execute("SELECT subject_id FROM pm_kpi_targets WHERE id=?", (kid,)).fetchone()
    if not line or line["subject_id"] != report_id:
        return {"ok": False, "error": "that KPI isn't on this person's scorecard"}
    # value absent -> None (KEEP any value the manager typed in the cell); the field-
    # preserving _pm_moderate_draft treats None as "unchanged". So drafting only a
    # justification (the chat "why" flow) never clears a drafted/typed value.
    val = args.get("value")
    raw = None if val is None else str(val)
    result, err = _pm_moderate_draft(db, u, kid, raw, args.get("justification"))
    if err:
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "kpi": result["kpi_name"], "draft": True,
            "moderated_overall": result["mine_preview"], "band_jump": result.get("band_jump"),
            "note": "not locked yet"}


def _mgr_tool_lock_kpi(db, u, cid, report_id, args):
    """Terminal: commit + LOCK the line (the manager's drafted value, if any)."""
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    kid = _mgr_int(args.get("kpi_id"))
    if kid is None:
        return {"ok": False, "error": "which KPI?"}
    line = db.execute("SELECT subject_id FROM pm_kpi_targets WHERE id=?", (kid,)).fetchone()
    if not line or line["subject_id"] != report_id:
        return {"ok": False, "error": "that KPI isn't on this person's scorecard"}
    # Lock the value the manager most recently drafted (or an explicit value), else
    # confirm their own figure as-is -- so 'lock it' after moderating keeps the draft.
    val = args.get("value")
    if val is None or str(val).strip() == "":
        draft = db.execute("SELECT adjusted_value, justification FROM pm_kpi_moderation_drafts "
                           "WHERE kpi_target_id=? AND approver_id=?", (kid, u["id"])).fetchone()
        raw = "" if (not draft or draft["adjusted_value"] is None) else str(draft["adjusted_value"])
        just = (draft["justification"] if draft else None) or args.get("justification")
    else:
        raw, just = str(val), args.get("justification")
    result, err = _pm_moderate_commit(db, u, kid, raw, just, require_remark_on_overall_move=True)
    if err:
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "kpi": result["kpi_name"], "locked": True,
            "what_stands": result.get("score"), "band_jump": result.get("band_jump"),
            "overall": result["mine_preview"]}


def _mgr_tool_set_competency(db, u, cid, report_id, args):
    """Reversible: override one competency Demonstrate/Developing."""
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    aid = _mgr_int(args.get("assignment_id"))
    if aid is None:
        return {"ok": False, "error": "which competency?"}
    ans = _TC_ANSWER_MAP.get((args.get("answer") or "").strip().lower())
    if ans not in ("yes", "no"):
        return {"ok": False, "error": "Demonstrate or Developing?"}
    # Echo any existing per-line remark so an answer-only override can't null it.
    cur = db.execute(
        "SELECT sc.manager_remark FROM tc_scores sc JOIN tc_assessments a ON a.id=sc.assessment_id "
        "WHERE a.subject_id=? AND a.cycle_id=? AND sc.assignment_id=?",
        (report_id, cid, aid)).fetchone()
    remark = (cur["manager_remark"] if cur else None) or None
    result, err = _tc_override_one(db, u, cid, report_id, aid, ans, remark)
    if err:
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "competency": result["competency"], "your_call": result["answer"]}


def _mgr_tool_approve_competencies(db, u, cid, report_id, args):
    """Terminal: lock the whole competency review (every item must have a rating)."""
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    result, err = _tc_approve_assessment(db, u, cid, report_id)
    if err:
        if err["reason"] == "incomplete":
            n = err["blank"]
            return {"ok": False, "error": "%d competenc%s still need a rating"
                    % (n, "y" if n == 1 else "ies")}
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "reviewed": True}


def _mgr_tool_comment_goal(db, u, cid, report_id, args):
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    period = active_pm_period(db)
    if not period:
        return {"ok": False, "error": "there's no active performance period"}
    comment = (args.get("comment") or "").strip()[:1000] or None
    result, err = _idp_goal_write(db, u, period, report_id, args.get("goal_id"),
                                  "manager_comment", comment)
    if err:
        return {"ok": False, "error": _mgr_err_msg(err) if err["reason"] != "bad_goal"
                else "which goal?"}
    return {"ok": True, "commented": "goal"}


def _mgr_tool_comment_plan(db, u, cid, report_id, args):
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    period = active_pm_period(db)
    if not period:
        return {"ok": False, "error": "there's no active performance period"}
    comment = (args.get("comment") or "").strip()[:4000] or None
    # The manager's ONE overall remark on the plan (Chris, 2026-09-24): about 100 words, on a SHARED
    # plan (a closed plan is agreed and no longer changes), never a template.
    idp = pm_idp_for(db, pm_idp_plan_year(period), report_id)
    _own = _idp_remark_owner(db, report_id)
    if _own is not None and _own != u["id"]:
        return {"ok": False, "error": "only their line manager writes the overall remark on this plan"}
    if (idp or {}).get("status") != "shared":
        return {"ok": False, "error": ("their plan is closed (agreed), so the remark can't change"
                                       if (idp or {}).get("status") == "closed"
                                       else "their plan isn't shared yet -- nothing to remark on")}
    if comment and _looks_like_placeholder(comment):
        return {"ok": False, "error": "that looks like a template, not the remark -- ask them in their own words"}
    if comment and len(comment.split()) > _REVIEW_REMARK_MAX_WORDS:
        return {"ok": False, "error": ("that remark is %d words -- aim for about 100; help them tighten it"
                                       % len(comment.split()))}
    result, err = _idp_plan_comment_write(db, u, period, report_id, comment)
    if err:
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "commented": "plan", "saved": "overall IDP remark"}


