def _mgr_tool_set_report_remark(db, u, cid, report_id, args):
    """Save the line manager's own overall remark on this direct report (pm_manager_remarks).
    Uses the PM PERIOD, not the cid arg (cid is the 360 cycle)."""
    if report_id is None:
        return {"ok": False, "error": "pick a team member first"}
    period = active_pm_period(db)
    if not period:
        return {"ok": False, "error": "there's no active performance period"}
    remark = (args.get("remark") or "").strip()[:4000]
    result, err = _pm_manager_remark_write(db, u, period, report_id, remark)
    if err:
        if err["reason"] == "too_long":   # the agent offers the shorter version (Chris, 2026-10-21)
            return {"ok": False, "error": _REMARK_SHORTEN_OFFER % (len(remark.split()), _REVIEW_REMARK_MAX_WORDS)}
        return {"ok": False, "error": _mgr_err_msg(err)}
    return {"ok": True, "saved": "remark"}


