@app.route("/review/team/tbox-remark", methods=["POST"])
@login_required
def review_team_tbox_remark():
    """The BG CEO's own overall remark on ONE person in their Talent Box (Chris, 2026-10-07: "below the summary, add an
    overall BGCEO remark, so BGCEO can leave their comment on the person (optional)"). Saved as they type on the
    Summary; empty clears it. Only someone in YOUR box, never yourself; refused once their business unit is locked;
    the BG CEO's Talent Box window applies (WINDOW_CELLS tb_bgceo)."""
    u = _review_guard()
    db = get_db()
    tb = _journey_talent_box_scope(db, u)
    try:
        pid = int(request.form.get("person") or "")
    except ValueError:
        return jsonify(ok=False, error="Which person?"), 400
    subj = next((p for p in tb[2]["population"] if p["id"] == pid), None) if tb else None
    if not subj or pid == u["id"]:
        return jsonify(ok=False, error="not in your Talent Box"), 404
    ctx = tb[2]
    _w = _late_refusal(db, u, "bgceo", "both", ctx["period"]["id"], ctx)   # closed for everyone: a late pass for THIS business group only
    if _w:
        return jsonify(ok=False, error=_w, window_closed=True), 409
    if _tb_remark_locked(db, ctx, _row_get(subj, "company")):
        return jsonify(ok=False, reason="locked",
                       error="Their business unit is locked, so your remark can't change now."), 409
    text = (request.form.get("remark") or "").strip()
    n = len(text.split())
    if n > _REVIEW_REMARK_MAX_WORDS or len(text) > 4000:
        return jsonify(ok=False, reason="too_long", words=n,
                       error="That's %d words -- keep it under %d and it saves." % (n, _REVIEW_REMARK_MAX_WORDS)), 400
    if text and ai_draft.stored_text_refusal(text):
        return jsonify(ok=False, reason="not_a_remark",
                       error="That doesn't read as a remark on them, so it wasn't saved."), 400
    key = (ctx["period"]["id"], pid, _tb_store_key(ctx))
    if text:
        db.execute("INSERT INTO talent_box_remarks(cycle_id, subject_id, business_group, author_id, remark) "
                   "VALUES (?,?,?,?,?) ON CONFLICT(cycle_id, subject_id, business_group) DO UPDATE SET "
                   "remark=excluded.remark, author_id=excluded.author_id, updated_at=datetime('now')",
                   key + (u["id"], text))
    else:
        db.execute("DELETE FROM talent_box_remarks WHERE cycle_id=? AND subject_id=? AND business_group=?", key)
    _paste_mark_record(db, u, ctx["period"]["id"], "tbox", pid, text)
    db.commit()
    return jsonify(ok=True, person=pid, remark=text, words=n)


