# ---- ONE READ FOR A PAGE'S INSIGHTS (Chris, 2026-10-09: "improve the AI insight load speed when said LM, HOD,
# BUCEO, and BGCEO view their respective page"). A page used to ask for its people's insights one request at a time,
# one after another -- a BU CEO's curve of 234 people was 234 requests on every visit even when every reading was
# cached. Now it asks once: the readings already worked out come back together, and each one still to work out is
# queued for the background worker (_prerun_want), which the page then polls this same read for. The person ON
# SCREEN still has their own request (the per-person routes above), so they never wait behind the rest.
# The same authority as each per-person route, re-derived here -- never from the form -- and someone outside it is
# simply left out of the answer, the same as an id that doesn't exist.
INSIGHTS_BATCH_MAX = {"pm": 120, "tm": 120, "idp": 120, "perf": 250, "pot": 250, "tb": 120}


def _insight_light(data):
    """A calibrator's performance reading, cut to what a table needs (the verdict, the paragraph, the first step): the
    person's card asks for the full one when it opens."""
    if not isinstance(data, dict):
        return data
    out = {k: data.get(k) for k in ("v", "kind", "verdict", "verdict_label", "verdict_why", "paragraph", "read")
           if k in data}
    out["discuss"] = (data.get("discuss") or [])[:1]
    return out


@app.route("/review/team/insights", methods=["POST"])
@login_required
def review_team_insights():
    """The readings a page shows for many people at once: kind = pm | tm | idp (a line manager's Team rows), perf | pot
    (a calibrator's curve or department review, by `view`), tb (the BG CEO's Talent Box); `ids` = a comma list of the
    people on screen. {ok, kind, prerun, items: {id: {pending, summary, data, source, ..., job}}} -- `job` says what
    the background worker is doing about a reading still pending (queued / running / failed / skipped), or None when it
    isn't working them out (no model): then the page asks for them itself, as before."""
    u = _review_guard()
    db = get_db()
    kind = (request.form.get("kind") or "").strip()
    if kind not in INSIGHTS_BATCH_MAX:
        return jsonify(ok=False, error="which insights?"), 400
    ids, seen = [], set()
    for t in (request.form.get("ids") or "").split(","):
        try:
            i = int(t)
        except ValueError:
            continue
        if i > 0 and i not in seen and i != u["id"]:
            seen.add(i)
            ids.append(i)
    ids = ids[:INSIGHTS_BATCH_MAX[kind]]
    prerun = _prerun_enabled()
    items = {}
    # the page sends its people in the order it shows them: the first rows go ahead of the rest of a long roster, so a
    # BU CEO's 234 people never hold up a line manager's team of six queued after them
    first = set(ids[:PRERUN_FIRST_ROWS])

    wants = []   # (id, job key): queued for the worker after every read, so the reads hold no write lock

    def put(rid, res, job_key=None, light=False, **extra):
        it = {"pending": bool(res.get("pending")), "summary": res.get("summary"),
              "data": _insight_light(res.get("data")) if light else res.get("data"), "source": res.get("source")}
        if light:
            it["light"] = True
        if res.get("retrying"):   # a plain reading the model failed on: shown now, asked of the model again
            it["retrying"] = True
        it.update(extra)
        if (it["pending"] or it.get("retrying")) and job_key and prerun:
            wants.append((rid, job_key))
        items[str(rid)] = it

    def each(rids, fn):
        for rid in rids:
            try:
                fn(rid)
            except Exception as e:   # one malformed record never empties the rest of the answer
                app.logger.warning("insights batch (%s) failed for %s: %s", kind, rid, e)
                items[str(rid)] = {"pending": False, "error": True}

    if kind in ("pm", "idp"):
        if not cycle_module_on("pm" if kind == "pm" else "idp", db):
            abort(404)
        period = active_pm_period(db)
        if not period or (kind == "pm" and not _review_manages_team(db, u)):
            allowed = set()
        else:   # a Career Plan's reviewers include its person's line manager (2026-10-19)
            allowed = set((_pm_review_subject_ids if kind == "pm" else _idp_review_subject_ids)(db, u, period["id"])
                          or [])
        rids = [i for i in ids if i in allowed]
        if kind == "pm":
            each(rids, lambda rid: put(rid, _pm_perf_summary_for(db, u, rid, stale_ok=True),
                                       ("pm_lm", rid, period["id"], "", "", u["id"])))
        else:
            each(rids, lambda rid: (lambda res: put(rid, res, ("idp", rid, period["id"]), status=res.get("status")))(
                _idp_summary_for(db, rid, viewer=u, stale_ok=True)))
    elif kind == "tm":
        if not cycle_module_on("tm", db):
            abort(404)
        cid = active_cycle_id(db)
        allowed = {r["id"] for r in _tc_reports_for(db, u["id"], cid)} if cid else set()
        each([i for i in ids if i in allowed],
             lambda rid: (lambda res: put(rid, res, ("tc", rid, cid), status=res.get("status")))(
                 _tc_summary_for(db, rid, stale_ok=True)))
    elif kind == "perf":
        if not cycle_module_on("pm", db):
            abort(404)
        sc = _journey_calib_scope(db, u) or _tbox_insight_scope(db, u)
        if sc:
            tier, _kw, ctx = sc
            pop = {p["id"] for p in sc[2]["population"]}
            calib = {"tier": tier, "scope_key": ctx["scope_key"], "reviewer": _CALIB_REVIEWER.get(tier, "CALIBRATOR")}
            each([i for i in ids if i in pop],
                 lambda rid: put(rid, _pm_perf_summary_for(db, u, rid, calib=calib, stale_ok=True),
                                 ("pm_calib", rid, ctx["period"]["id"], tier, ctx["scope_key"], 0), light=True))
    elif kind == "pot":
        if not cycle_module_on("calibration", db):
            abort(404)
        sc = _pot_calib_scope(db, u)
        if not sc:
            _tb = _tbox_insight_scope(db, u)
            sc = (_tb[0], _tb[1].get("bg") or _tb[1].get("group_id"),
                  {"population": _tb[2]["population"], "cycle_id": _tb[2]["cycle_id"]}) if _tb else None
        if sc:
            pop, cid = {p["id"] for p in sc[2]["population"]}, sc[2]["cycle_id"]
            rv = _POT_REVIEWER.get(sc[0], "CALIBRATOR")
            each([i for i in ids if i in pop],
                 lambda rid: put(rid, _pot_summary_for(db, u, rid, cid, rv, stale_ok=True), ("pot", rid, cid)))
    elif kind == "tb":
        tb = _journey_talent_box_scope(db, u)
        if tb:
            byid = {p["id"]: p for p in tb[2]["population"]}
            skey = _tb_store_key(tb[2])   # the business group on a BG CEO's box, group:<id> on a Group Chief's
            each([i for i in ids if i in byid],
                 lambda rid: (lambda res: put(rid, res, ("tb", rid, tb[2]["cycle_id"], tb[0], skey, u["id"]),
                                              facts=res.get("facts")))(
                     _tb_insight_for(db, u, tb, byid[rid], stale_ok=True)))
    for rid, jk in wants:
        try:
            # a boss is looking at these: the first rows on their screen go ahead of every save's queue
            job = _prerun_want(db, *jk, priority=PRERUN_PRI_PAGE if rid in first else PRERUN_PRI_ROWS)
        except Exception as e:   # the reading stays pending with no job: the page asks for it itself
            app.logger.warning("insights batch (%s): not queued for %s: %s", kind, rid, e)
            continue
        items[str(rid)]["job"] = job   # pending, or a plain reading being asked of the model again
    db.commit()
    return jsonify(ok=True, kind=kind, prerun=prerun, items=items)


@app.route("/review/team/idp-remark", methods=["POST"])
@login_required
def review_team_idp_remark():
    """The line manager's ONE overall remark on a direct report's shared development plan, from the Remarks box on
    their plan (Chris, 2026-09-28: "we just need one overall remark for line manager to fill in for each IDP"). Saved
    as they type, through the same writer the chat's comment_plan uses (_idp_plan_comment_write: a reviewer of their
    plan, a shared plan -- never a draft or a closed one -- and the remark ceiling), and only by their LINE
    MANAGER (_idp_remark_owner). Empty clears it. A prompt injection is refused: the remark is read by the AI later."""
    u = _review_guard()
    db = get_db()
    if not cycle_module_on("idp", db):
        abort(404)
    period = active_pm_period(db)
    try:
        rid = int(request.form.get("report") or "")
    except ValueError:
        return jsonify(ok=False, reason="bad_request", error="which team member?"), 400
    if not period or rid not in (_idp_review_subject_ids(db, u, period["id"]) or []):
        return jsonify(ok=False, reason="forbidden", error="not one of your team members"), 404
    owner = _idp_remark_owner(db, rid)
    if owner is not None and owner != u["id"]:
        return jsonify(ok=False, reason="not_owner", error="Their line manager writes this remark."), 403
    text = (request.form.get("remark") or "").strip()[:4000]
    if text and ai_draft.stored_text_refusal(text):
        return jsonify(ok=False, reason="not_a_remark", error="That doesn't read as a remark -- please rewrite it."), 400
    res, err = _idp_plan_comment_write(db, u, period, rid, text or None)
    if err:
        msg = {"not_shared": "Their plan isn't shared yet.", "closed": "Their plan is agreed and closed.",
               "too_long": "Too long -- keep it under %d words (about 100 is the aim)." % _REVIEW_REMARK_MAX_WORDS,
               "forbidden": "Not one of your team members.", "screened": STORE_TEXT_REFUSAL}.get(err["reason"],
                                                                                              "Couldn't save it.")
        return jsonify(ok=False, reason=err["reason"], error=msg), err.get("code", 400)
    _paste_mark_record(db, u, period["id"], "plan_review", rid, text)
    db.commit()
    st = review_state(db, u)
    return jsonify(ok=True, modtabs_html=_journey_modtabs_html(db, u, st, "plan_review", view="team"),
                   nav_html=_journey_nav_html(db, u, st, "plan_review", view="team"))


@app.route("/review/feedback/submit", methods=["POST"])
@login_required
def review_feedback_submit():
    """The employee's SUBMIT of one colleague's 360 feedback, from the journey
    chat's confirm card. The ONE submit path -- server-validated (the agent can
    never submit), sharing _feedback_submit() with the /rate page so the two
    cannot disagree about 'submitted'. Owner-scoped + open-cycle gated."""
    u = _review_guard()
    db = get_db()
    try:
        _aid = int(request.form.get("assignment_id"))
    except (TypeError, ValueError):
        _aid = None
    if _aid and _signoff_done(db, u, active_cycle_id(db), "feedback_confirm", _aid):   # a double Confirm -> still ok
        _sov = _feedback_overview(db, u, _aid)
        ov = _feedback_overview(db, u)
        return jsonify(ok=True, submitted=True, already=True, overview=(ov["data"] if ov else None),
                       submitted_overview=(_sov["data"] if _sov else None))
    ok, err = _fb_do_submit(db, u, request.form.get("assignment_id"))
    if not ok:
        return jsonify(ok=False, error=err), 400
    # Focus the NEXT pending colleague (no `want`), not the one just submitted, so the
    # post-submit follow-up turn advances instead of re-engaging a locked colleague.
    # `submitted_overview`: the colleague JUST submitted, so the journey card locks in place for them first.
    ov = _feedback_overview(db, u)
    _sov = _feedback_overview(db, u, _aid) if _aid else None
    return jsonify(ok=True, submitted=True, overview=(ov["data"] if ov else None),
                   submitted_overview=(_sov["data"] if _sov else None))


def _fb_do_submit(db, u, aid):
    """THE journey 360 submit for one colleague: open-cycle + own-assignment checks, the sign-off gate,
    then _feedback_submit. Shared by the Submit button (POST /review/feedback/submit) and the typed
    "confirm & submit" -- the person's own act, never the model's. Returns (ok, error)."""
    cid, err = _feedback_open_or_error(db, u)
    if err:
        return False, err["error"]
    a, err = _feedback_own_assignment(db, u, cid, aid)
    if err:
        return False, err["error"]
    # The journey sign-off gate (every behaviour answered + the overall remark for a High rating) --
    # the SAME _fb_submit_blockers the final card uses, enforced HERE on the true write, so a crafted
    # POST can't bypass it. Journey only: the shared _feedback_submit and /rate are untouched.
    if a["status"] != "submitted":
        okb, why = _fb_submit_blockers(db, u, cid, a)
        if not okb:
            return False, why
    subject = db.execute("SELECT * FROM users WHERE id=?", (a["subject_id"],)).fetchone()
    return _feedback_submit(db, dict(a), subject)


