@app.route("/review/career/chat", methods=["POST"])
@login_required
def review_career_chat():
    """One career-agent turn. The model converses and proposes; the server runs
    every action through a validated tool. Nothing here can submit anything --
    there is nothing to submit."""
    u = _review_guard()
    db = get_db()
    cid = active_cycle_id(db)
    # Same uniform contract as the plan chat: every exit carries an overview.
    def _degraded(say, **kw):
        ov = _career_overview(db, u)
        return jsonify(ok=True, quick_replies=[], say=say,
                       overview=(ov["data"] if ov else None), **kw)

    if not _idp_agent_ready():
        return _degraded("The career assistant isn't switched on yet -- ask your admin "
                         "to enable it, and you can still use the career profile page.",
                         done=True)
    # a closed part (its window on the admin's Calendar): the page locks the box and a message that still arrives gets
    # the sentence -- no model call, stored nowhere (Chris, 2026-10-20: "after deadline no action can be done ... the chat
    # will be disabled, user can just read the past conversation")
    _wn = window_closed(db, "idp_self", subject_id=u["id"])
    if _wn:
        return _degraded(_wn + " You can still look through it.", window_closed=True, window_note=_wn)
    msg = (request.form.get("message") or "").strip()[:1000]
    if msg:
        db.execute("INSERT INTO pm_career_chat(subject_id, cycle_id, role, content) "
                   "VALUES (?,?,'user',?)", (u["id"], cid, msg))
        db.commit()
    history = _idp_chat_history(db, u, cid, "pm_career_chat")
    system = _career_agent_system(db, u, _career_context(db, u, create=False))
    say, qr, steps, renders = "", [], 0, []
    while steps <= ai_draft.REVIEW_AGENT_MAX_TOOLS:
        steps += 1
        try:
            turn = ai_draft.review_agent(system, history)
            _screen_trace(db, u, turn, "employee")
        except ai_draft.AIDraftNotConfigured:
            return _degraded("The career assistant isn't switched on yet.", done=True)
        except ai_draft.AIDraftError:
            return _degraded("Sorry -- I lost the thread there. Could you say that again?")
        say, qr, action = turn["say"], turn["quick_replies"], turn["action"]
        if not action:
            break
        # Nothing is saved as a person's words unless they said it (or approved the wording) --
        # _person_text_guard, shared by every agent loop (2026-09-24).
        _person_text_tidy(action)   # a dictated "save it as it is:" lead-in is not their words (2026-10-31)
        _gerr = (_person_text_guard(history, action, _grounding_facts(db, u, cid))
                 if action.get("tool") in _PERSON_TEXT_TOOLS else None)
        if _gerr:
            history.append({"role": "agent", "content": say or "(drafting)"})
            history.append({"role": "tool", "content": json.dumps({"ok": False, "error": _gerr})[:700]})
            if steps > ai_draft.REVIEW_AGENT_MAX_TOOLS:   # the loop ends on a refusal -> never claim it saved
                say, qr = _GUARD_FALLBACK_SAY, []
            continue
        result = _career_run_tool(db, u, cid, action)
        if isinstance(result, dict) and result.get("render"):
            renders.append(result["render"])
        feed = {k: v for k, v in result.items() if k != "render"} if isinstance(result, dict) else result
        history.append({"role": "agent", "content": say or "(took an action)"})
        history.append({"role": "tool", "content": json.dumps(feed)[:400]})
        system = _career_agent_system(db, u, _career_context(db, u, create=False))
    # Drop the redundant "I'll type it" chip; every answer here is words, so there
    # is no bare-number chip to strip.
    qr = [q for q in (qr or []) if not re.search(r"type it", str(q), re.I)]
    if say:
        db.execute("INSERT INTO pm_career_chat"
                   "(subject_id, cycle_id, role, content, quick_replies, card) "
                   "VALUES (?,?,'agent',?,?,?)",
                   (u["id"], cid, say, json.dumps(qr) if qr else None,
                    json.dumps(renders) if renders else None))
        db.commit()
    ov = _career_overview(db, u)
    st = review_state(db, u)
    return jsonify(ok=True, say=say, quick_replies=qr, renders=renders,
                   overview=(ov["data"] if ov else None),
                   rail_html=_career_rail_html(st))


