@app.route("/review/account/suggest")
@login_required
def review_account_suggest():
    """Which of the person's own shared items look relevant to one KPI, as tag
    numbers to PRE-TICK on the cite turn. Writes nothing; a tick becomes real
    only when the human confirms it through /evidence/<id>/link.

    A separate fetch, never part of a turn render, so a slow or absent model
    degrades one control rather than the conversation. AI off or down -> [],
    i.e. nothing pre-ticked, i.e. manual -- the identical safe result."""
    u = _review_guard()
    db = get_db()
    kraw = (request.args.get("kpi", "") or "").strip()
    if not kraw.isdigit():
        return jsonify(ok=False, reason="bad_kpi"), 400
    tid = int(kraw)
    # Validated against a target this person owns -- an unvalidated ref would be
    # an enumeration oracle over other people's KPI ids. Same rule as the link route.
    cid = active_cycle_id(db)
    kpi = db.execute("SELECT kpi_name FROM pm_kpi_targets WHERE id=? AND subject_id=? "
                     "AND cycle_id=?", (tid, u["id"], cid)).fetchone()
    if not kpi:
        return jsonify(ok=False, reason="not_yours"), 403
    items = _review_ai_items(db, u["id"])
    suggested = []
    if ai_on("ai_review") and items:
        _used, remaining, _reset = _pm_ai_draft_quota(db, u["id"], "review_suggest")
        if remaining > 0:
            try:
                ns = ai_draft.suggest_citations(kpi["kpi_name"],
                                                [(n, t) for n, t, _eid in items])
                by_n = {n: eid for n, _t, eid in items}
                suggested = [by_n[n] for n in ns if n in by_n]
                db.execute("INSERT INTO pm_ai_draft_usage(user_id, field_key) VALUES (?,?)",
                           (u["id"], "review_suggest"))
                db.commit()
            except ai_draft.AIDraftError:
                suggested = []   # down -> nothing pre-ticked, i.e. manual
    return jsonify(ok=True, suggested=suggested)


