@app.route("/review/team/dept-accept", methods=["POST"])
@login_required
def review_team_dept_accept():
    """The Department summary's bulk keep (Chris, 2026-09-30: "like the PM line manager view for summary HOD can decide
    to bulk select to go with the LM approved band, and if needed, go to the individual page to amend the band"). For
    each selected person -- the HOD's own, not decided yet, with a band that came in -- keep that band through the one
    write path (no remark: the band doesn't change). Never trusts the page; one refusal never stops the batch; a person
    already decided is never touched, so a bulk keep can't overwrite a change made on their page."""
    u = _review_guard()
    db = get_db()
    stage = (request.form.get("stage") or "").strip()
    if _journey_req_view(db, u) != "dept":   # the Dept view only -- a crafted view reaches nothing
        return jsonify(ok=False, error="There is no department review here for you."), 404
    axis, sc = _calib_stage_scope(db, u, stage, fresh=True)
    if not sc or sc[0] != "hod":
        return jsonify(ok=False, error="There is no department review here for you."), 404
    if axis == "pm":
        data = _pm_calib_assist_overview(db, u, sc[2], sc[0], sc[1])["data"]
    else:
        data = _pot_calib_overview(db, u, sc)
    if data.get("locked") or data.get("closed"):
        return jsonify(ok=False, error=data.get("closed") or "This department review is already submitted.")
    byid = {r["id"]: r for r in data.get("rows") or []}
    kept, skipped = [], []
    for raw in request.form.getlist("report_ids")[:500]:
        try:
            sid = int(raw)
        except (TypeError, ValueError):
            continue
        r = byid.get(sid)
        if (not r or r.get("adjusted") or r.get("is_self") or r.get("super_override") or not r.get("incoming_band")):
            skipped.append(sid)
            continue
        if axis == "pm":
            _s, err = _pm_calib_apply(db, u, sc[2], sc[0], sid, r["incoming_band"], "")
        else:
            _s, err = _pot_calib_apply(db, u, sc, sid, r["incoming_band"], "")
        (skipped if err else kept).append(sid)
    db.commit()
    return _calib_curve_reply(db, u, stage, kept=len(kept), skipped=len(skipped))


@app.route("/review/team/approve-bulk", methods=["POST"])
@login_required
def review_team_approve_bulk():
    """Bulk-approve several reports from the manager Team SUMMARY without opening each
    detail. stage=pm_review LOCKS every actionable KPI line of each selected report
    (confirm-as-is via _pm_moderate_commit, preserving any drafted value/why);
    stage=tm_review APPROVES each selected competency assessment (_tc_approve_assessment,
    submitted + all rated). Re-checks ownership + the per-line/per-report gate for EVERY
    item -- never trusts the client's eligibility flag -- and never aborts the batch on one
    failure. Returns per-report results so the client can update rows + show partial fails."""
    u = _review_guard()
    db = get_db()
    if not _review_manages_team(db, u):
        abort(404)
    stage = (request.form.get("stage") or "").strip()
    ids = []
    for raw in request.form.getlist("report_ids"):
        try:
            ids.append(int(raw))
        except (TypeError, ValueError):
            pass
    results = []
    if stage == "pm_review":
        period = active_pm_period(db)
        if not period:
            return jsonify(ok=False, error="No active period."), 400
        allowed = set(_pm_review_subject_ids(db, u, period["id"]))
        for sid in ids:
            if sid not in allowed:
                results.append({"report_id": sid, "error": "not yours"})
                continue
            mine, _mp, _sp, _al = _pm_member_previews(db, sid, period["id"], u["id"])
            # A moderation that moves the OVERALL band needs the line manager's overall remark first
            # (Chris, 2026-09-25) -- checked once for the whole report, so nothing half-locks.
            missing, sb, mb = _pm_remark_missing(db, u, sid, period["id"])
            if missing:
                results.append({"report_id": sid, "locked": 0, "errors": 0, "needs_remark": True,
                                "from_band": sb, "to_band": mb, "error": _pm_remark_missing_msg(sb, mb),
                                "all_locked": False})
                continue
            locked, errs = 0, 0
            for t in mine:
                if _pm_line_actionable_by(t, u["id"]):
                    _res, err = _pm_moderate_commit(db, u, t["id"], None, None,
                                                    require_remark_on_overall_move=True)
                    if err:
                        errs += 1
                    else:
                        locked += 1
            _m2, _mp2, _sp2, all_locked = _pm_member_previews(db, sid, period["id"], u["id"])
            results.append({"report_id": sid, "locked": locked, "errors": errs, "needs_remark": False,
                            "all_locked": all_locked})
    elif stage == "tm_review":
        cid = active_cycle_id(db)
        allowed = {r["id"] for r in _tc_reports_for(db, u["id"], cid)}
        for sid in ids:
            if sid not in allowed:
                results.append({"report_id": sid, "error": "not yours"})
                continue
            res, err = _tc_approve_assessment(db, u, cid, sid)
            results.append({"report_id": sid, "approved": bool(res and res.get("ok")),
                            "error": (err.get("reason") if err else None)})
    else:
        return jsonify(ok=False, error="Unknown stage."), 400
    return jsonify(ok=True, results=results)


