@app.route("/evidence/new", methods=["POST"])
@login_required
def evidence_new():
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    fields, err = _evidence_clean(request.form)
    if err:
        flash(err, "error")
        return redirect(url_for("evidence_home"))
    if not fields["body"]:
        flash("Say what happened -- a sentence or two is plenty.", "error")
        return redirect(url_for("evidence_home"))
    # correction_of is validated, never trusted: a correction may only ever
    # replace an item this person wrote about themselves.
    corr = (request.form.get("correction_of") or "").strip()
    corr_id = None
    if corr.isdigit():
        prev = evidence_get(db, int(corr))
        if prev and prev["author_id"] == u["id"] and prev["state"] == "shared":
            corr_id = prev["id"]
    eid, err = pm_evidence_write(db, u, u["id"], fields, correction_of=corr_id)
    if err:
        flash(err, "error")
        return redirect(url_for("evidence_home"))
    db.commit()
    log_activity(db, u["id"], "evidence_new", "entry %s" % eid)
    db.commit()
    flash("Saved as a draft. Share it when you are ready.", "success")
    return redirect(url_for("evidence_home", open=eid))


@app.route("/evidence/<int:eid>/autosave", methods=["POST"])
@login_required
def evidence_autosave(eid):
    u = current_user()
    db = get_db()
    # The row being edited, so an absent field falls back rather than blanking.
    # Ownership is NOT checked here -- pm_evidence_write() is the one writer and
    # owns that rule; this read only supplies defaults, and a row the caller does
    # not own is refused there before anything is written.
    base = db.execute("SELECT * FROM pm_evidence WHERE id=?", (eid,)).fetchone()
    fields, err = _evidence_clean(request.form, base=base)
    if err:
        return jsonify(ok=False, error=err), 400
    _row, err = pm_evidence_write(db, u, u["id"], fields, evidence_id=eid)
    if err:
        return jsonify(ok=False, error=err), 409
    db.commit()
    return jsonify(ok=True)


# target_ref is the BARE id as text, never "kpi:<id>": target_kind already
# carries the kind, and pm_evidence_links has an index on
# (target_kind, target_ref) that a prefixed form would make useless. Settled
# before the first row was ever written -- a mixed-format table is not fixable
# by a read-path change.
EVIDENCE_TARGET_KINDS = ("kpi", "principle", "competency")


def _evidence_owns(db, u, eid):
    """The item, if it is this person's own. Nobody links another person's."""
    return db.execute("SELECT * FROM pm_evidence WHERE id=? AND subject_id=?",
                      (eid, u["id"])).fetchone()


@app.route("/evidence/<int:eid>/link", methods=["POST"])
@login_required
def evidence_link(eid):
    """Cite an evidence item against a KPI line -- pm_evidence_links' FIRST
    writer. Phase A created that table and nothing has ever written to it, which
    is the very thing that commit's own message warned against.

    Under /evidence rather than /review on purpose: module_of_request()
    classifies it as evidence for free, so it dies correctly when the ledger is
    switched off, and /review keeps its shape -- GETs write nothing, and it owns
    exactly one POST."""
    u = _review_guard()
    db = get_db()
    if not _evidence_owns(db, u, eid):
        abort(404)
    kind = (request.form.get("target_kind", "kpi") or "kpi").strip()
    ref = (request.form.get("target_ref", "") or "").strip()
    if kind not in EVIDENCE_TARGET_KINDS or not ref.isdigit():
        return jsonify(ok=False, reason="bad_target"), 400
    _tgt = None
    if kind == "kpi":
        _tgt = db.execute("SELECT id, cycle_id FROM pm_kpi_targets WHERE id=? AND subject_id=?",
                          (int(ref), u["id"])).fetchone()
        if not _tgt:
            # Validated against a target this person owns. An unvalidated ref would
            # be an enumeration oracle over other people's KPI ids.
            return jsonify(ok=False, reason="not_yours"), 403
        # An HR-owned KPI (BU-level / HR-filled) takes no evidence -- matching
        # _review_cite_data, which never offers one.
        if _tgt["id"] in _review_hr_owned_ids(db, u, _tgt["cycle_id"]):
            return jsonify(ok=False, reason="bu_level"), 400
    db.execute("INSERT OR IGNORE INTO pm_evidence_links(evidence_id, target_kind, "
               "target_ref) VALUES (?,?,?)", (eid, kind, ref))
    db.commit()
    return jsonify(ok=True)


@app.route("/evidence/<int:eid>/unlink", methods=["POST"])
@login_required
def evidence_unlink(eid):
    """Remove a citation. The item itself is untouched -- an append-only ledger
    is about the WORDS; which verdict they were cited against is a different
    question, and one a person may legitimately change their mind about."""
    u = _review_guard()
    db = get_db()
    if not _evidence_owns(db, u, eid):
        abort(404)
    db.execute("DELETE FROM pm_evidence_links WHERE evidence_id=? AND target_kind=? "
               "AND target_ref=?", (eid, (request.form.get("target_kind") or "kpi").strip(),
                                    (request.form.get("target_ref") or "").strip()))
    db.commit()
    return jsonify(ok=True)


