@app.route("/evidence/<int:eid>/attach", methods=["POST"])
@login_required
def evidence_attach(eid):
    u = current_user()
    db = get_db()
    row = evidence_get(db, eid)
    if not row or row["author_id"] != u["id"]:
        abort(404)
    if row["state"] != "draft":
        flash("Attach the proof before sharing the entry.", "error")
        return redirect(url_for("evidence_home", open=eid))
    n = db.execute("SELECT COUNT(*) c FROM pm_evidence_attachments "
                   "WHERE evidence_id=? AND removed_at IS NULL", (eid,)).fetchone()["c"]
    if n >= EVIDENCE_MAX_ATTACH_PER_ITEM:
        flash("That is the most files one entry can carry.", "error")
        return redirect(url_for("evidence_home", open=eid))
    f = request.files.get("file")
    if not f or not f.filename:
        flash("Choose a file.", "error")
        return redirect(url_for("evidence_home", open=eid))
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in EVIDENCE_ATTACH_EXTS:
        flash("That kind of file cannot be attached.", "error")
        return redirect(url_for("evidence_home", open=eid))
    data = f.read()
    if len(data) > EVIDENCE_ATTACH_MAX_BYTES:
        flash("That file is too large -- %d MB is the limit." % EVIDENCE_ATTACH_MAX_MB, "error")
        return redirect(url_for("evidence_home", open=eid))
    why = _upload_content_refusal(ext, data)   # what its name says, no macros, no password (2026-11-11)
    if why:
        flash(why, "error")
        return redirect(url_for("evidence_home", open=eid))
    stored, backend = evidence_store_attachment(eid, ext, data, f.content_type)
    db.execute(
        "INSERT INTO pm_evidence_attachments(evidence_id, filename, stored_path, "
        "content_type, size_bytes, storage_backend, uploaded_by) VALUES (?,?,?,?,?,?,?)",
        (eid, f.filename[:200], stored, f.content_type, len(data), backend, u["id"]))
    db.commit()
    flash("Attached.", "success")
    return redirect(url_for("evidence_home", open=eid))


@app.route("/evidence/attachment/<int:aid>")
@login_required
def evidence_attachment_download(aid):
    u = current_user()
    db = get_db()
    att = db.execute("SELECT * FROM pm_evidence_attachments WHERE id=? AND removed_at IS NULL", (aid,)).fetchone()
    if not att:
        abort(404)
    row = evidence_get(db, att["evidence_id"])
    # 404 rather than 403: somebody else's file should not be confirmed to exist.
    if not evidence_can_view(u, row):
        abort(404)
    _out = _one_person_report_refusal(db, u, row["subject_id"], ("pm",), _row_get(row, "cycle_id"))   # out means out (1b-03)
    if _out:
        return Response(_out, 403, mimetype="text/plain")
    path = os.path.join(EVIDENCE_UPLOAD_DIR, att["stored_path"])
    if not os.path.exists(path):
        abort(404)
    with open(path, "rb") as fh:
        data = fh.read()
    # ?disp=inline previews in the browser (the preview box shows PDF/images/text, and Open in a new tab
    # does too; other types still download). Default stays attachment (download) for existing callers.
    # The type is the EXTENSION's, never the one the uploader's browser sent (2026-10-23): a crafted upload named
    # .png but declared text/html would otherwise open as a page in OneHR, as whoever clicked it. Only a PDF, an
    # image or plain text ever previews; everything else downloads.
    ext = _attach_ext(att["filename"])
    disp = "inline" if request.args.get("disp") == "inline" and ext in _ATTACH_INLINE_EXTS else "attachment"
    return Response(data, mimetype=_ATTACH_SERVE_TYPES.get(ext, "application/octet-stream"),
                    headers=_file_response_headers(att["filename"], ext, disp))


@app.route("/idp")
@login_required
def idp_view():
    """Employee: the development plan for a YEAR -- a few structured goals,
    seeded from their own released 360 feedback and their manager's remark,
    then submitted for the manager to comment on and agree.

    Forward-looking: the plan is written at Year-End for the year ahead, and
    worked (and checked in on) through that year. So Year-End shows next
    year's plan, editable; Mid-Year shows this year's, read-only. See
    pm_idp_plan_year()."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period, _periods, is_active_period = _pm_idp_period(db, u)
    plan_years = pm_idp_years_for(db, u["id"], period)
    plan_year = pm_idp_plan_year(period)
    # ?year= only ever selects one of this person's OWN reachable years, so
    # the param can't be used to probe for someone else's plan or to conjure
    # an empty page for a year nobody plans.
    want = request.args.get("year", "").strip()
    if want.isdigit() and int(want) in plan_years:
        plan_year = int(want)
    # Authoring is Year-End's job, and only for the year that Year-End writes.
    # Looking back at an earlier plan from the same page never reopens it.
    is_authoring = bool(is_active_period and pm_idp_is_authoring(period)
                        and plan_year == pm_idp_plan_year(period))
    idp = pm_idp_for(db, plan_year, u["id"]) if period else None
    subject = db.execute("SELECT * FROM users WHERE id=?", (u["id"],)).fetchone()
    suggestions = pm_idp_suggestions(db, subject) if period else {}
    # What the assessments actually recorded, so the page can say what a
    # suggestion run would be built from BEFORE anyone spends a run on it --
    # and say honestly when there is nothing to build from.
    gaps = pm_idp_gaps(db, subject) if period else {"items": [], "future": []}
    # What this plan is built from, and what is still outstanding. Shown while
    # authoring only: on a past plan year it is history, not a checklist.
    readiness = pm_idp_readiness(db, subject) if period else []
    if idp:
        pm_idp_attach_editors(db, idp["goals"])
    can_edit = pm_idp_can_edit(idp, is_authoring)
    # Checking in stays available on the year you are actually living in --
    # that is the whole point of Mid-Year -- but not on a plan year you have
    # merely navigated back to.
    can_check_in = pm_idp_can_check_in(
        idp, is_active_period and plan_year == pm_idp_plan_year(period))
    # Two independent gates: whether this server has an AI endpoint at all, and
    # whether the org wants employees drafting development actions with it
    # (Settings -> IDP). idp_draft_ai() enforces the second one as well -- this
    # only decides whether the button gets drawn.
    ai_enabled = ai_draft.is_configured() and get_idp_settings()[3]
    ai_remaining = ai_reset = None
    if ai_enabled and can_edit:
        _u, ai_remaining, ai_reset = _pm_ai_draft_quota(
            db, u["id"], f"idp:{plan_year}")
    return render_template(
        "idp.html", period=period, plan_year=plan_year, plan_years=plan_years,
        is_active_period=is_active_period, is_authoring=is_authoring,
        next_authoring_year=(pm_idp_plan_year(period) if period else None),
        idp=idp, goals=(idp or {}).get("goals", []),
        suggestions=suggestions, gaps=gaps, readiness=readiness,
        can_edit=can_edit, max_goals=pm_idp_max_goals(),
        modes=PM_IDP_MODES, can_check_in=can_check_in, progress_states=PM_IDP_PROGRESS,
        ai_enabled=ai_enabled, ai_limit=AI_DRAFT_DAILY_LIMIT,
        ai_remaining=ai_remaining, ai_reset_seconds=ai_reset, active_view="idp")


@app.route("/idp/career")
@login_required
def idp_career_view():
    """Employee: their own career profile -- where they're heading, how mobile
    they are, who they'd like to learn from.

    No period switcher and no read-only past state, unlike the IDP: the profile
    is one living document per person, so an old period would show the same row
    anyway. The career conversation recorded against the ACTIVE period is shown
    read-only beneath it, since only the manager can record one."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    profile = pm_career_profile_for(db, u["id"])
    period = active_pm_period(db)
    conversation = (pm_career_conversation_for(db, pm_idp_plan_year(period), u["id"])
                    if period else None)

    # The career map. Everything here is derived at read time from the job
    # architecture, so it stays true to whatever HR last imported without a
    # rebuild step -- and costs nothing at all on a database with no
    # architecture loaded, which is the state most of this org is in today.
    here, anchor = tc_profile_for_user(db, u, profile)
    have = tc_person_skill_map(db, u["id"]) if here else {}
    routes = tc_career_routes_for_person(db, u, here, have=have) if here else []   # their job's, then Group People's suggestions
    # Drives the "we can't rank these yet" note, and which grouping the page
    # renders. Keyed on the person's assessments, not on the routes.
    routes_ranked = bool(have)
    here_gap = tc_route_gap(db, have, here["id"]) if here else None
    target = target_gap = None
    tpid = profile["target_profile_id"] if profile else None
    if tpid:
        # Resolved rather than trusted: the architecture is re-imported wholesale,
        # so a target saved last half can simply cease to exist.
        # a job retired in OneHR stays as their target, marked retired (it shows in "Heading towards" with Clear target);
        # the architecture's re-import deactivating one used to make it vanish, so the same card carries both
        target = db.execute("SELECT * FROM tc_job_profiles WHERE id=?",
                            (tpid,)).fetchone()
        if target:
            target = dict(target)
            target["retired"] = not target["active"]
            target_gap = tc_route_gap(db, have, target["id"])
    # Only needed for the pick-your-own-role fallback, so only paid for then.
    all_profiles = [] if here else [dict(r) for r in db.execute(
        "SELECT id, department, job_title, job_grade FROM tc_job_profiles "
        "WHERE active=1 ORDER BY department, job_title, job_grade")]

    return render_template(
        "idp_career.html", profile=profile, period=period,
        conversation=conversation, horizons=PM_CAREER_HORIZONS,
        mobility_options=PM_CAREER_MOBILITY, active_view="career",
        here=here, anchor=anchor, routes=routes, here_gap=here_gap,
        routes_ranked=routes_ranked, ready_groups=TC_READY_GROUPS,
        target=target, target_gap=target_gap, all_profiles=all_profiles,
        have_count=len(have))


def tc_profile_population(db, me):
    """The people competency assignment actually covers, in this admin's scope.

    Same population rule the rest of the app uses for "a real employee":
    confirmed, still here, not a demo account -- narrowed by bg_scope() so a BG
    admin generates for their own BG and nobody else's."""
    where, params = bg_scope(me, "business_group")
    return [dict(r) for r in db.execute(
        "SELECT id, employee_id, full_name, department, job_title, job_grade, "
        "       business_group, company "
        "FROM users WHERE role != 'admin' AND COALESCE(left_at,'')='' "
        "AND COALESCE(is_demo,0)=0" + where + " ORDER BY full_name", params)]


def tc_profile_plan(db, profile_id):
    """The competencies a profile assigns, as (skill_id, is_future, seq) rows.

    A competency exists in tc_skills once per proficiency level -- "Cost
    Analysis" at level 3 and at level 4 are two rows sharing a title. A role
    sitting at level N is therefore assessed twice on each of its competencies:
    at N (what the job needs now, is_future=0) and at N+1 (the stretch the
    person is growing into, is_future=1), which is exactly what the points per answer score
    split the assessment already applies.

    The profile's own rows name the current-level skills; the future half is
    derived by looking up the same TITLE one level up, so HR curates one list
    and never has to remember to add the level above. A competency with no
    level above it simply has no future half -- it is a ceiling, not an error.
    """
    prof = db.execute("SELECT plan_mode FROM tc_job_profiles WHERE id=?", (profile_id,)).fetchone()
    if prof and prof["plan_mode"] == "explicit":
        return tc_profile_plan_explicit(db, profile_id)
    rows = db.execute(
        "SELECT s.id, s.title, COALESCE(ps.required_level, s.level) lvl, ps.sort_order "
        "FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id = ps.skill_id "
        "WHERE ps.profile_id=? AND s.active=1 AND " + TC_CURRENT_ROWS + " "
        "ORDER BY COALESCE(ps.sort_order, 9999), s.title", (profile_id,)).fetchall()
    # Two passes, because tc_assignments is UNIQUE(cycle, subject, skill) and a
    # profile may legitimately name two levels of the same competency. Claim
    # every explicitly-chosen level as current FIRST, so a level that HR ticked
    # deliberately can never be demoted into being some lower rung's stretch by
    # nothing more than insert order.
    plan = [(r["id"], 0, seq) for seq, r in enumerate(rows)]
    claimed = {r["id"] for r in rows}
    for seq, r in enumerate(rows):
        nxt = db.execute(
            "SELECT id FROM tc_skills WHERE active=1 AND title=? AND level=? LIMIT 1",
            ((r["title"] or "").strip(), (r["lvl"] or 0) + 1)).fetchone()
        if nxt and nxt["id"] not in claimed:
            plan.append((nxt["id"], 1, seq))
            claimed.add(nxt["id"])
    return plan


def tc_profile_plan_explicit(db, profile_id):
    """An architecture profile's plan, exactly as P&R reviewed it (plan_mode 'explicit', 2026-10-17): its current rows
    (is_future=0) and its future rows (is_future=1). A future row takes the seq of the current skill of the same title,
    so the card shows it beside its current level; a next-role competency (no current pair) follows the current ones."""
    rows = db.execute(
        "SELECT s.id, s.title, COALESCE(ps.is_future,0) fut, ps.sort_order FROM tc_job_profile_skills ps "
        "JOIN tc_skills s ON s.id = ps.skill_id WHERE ps.profile_id=? AND s.active=1 "
        "ORDER BY COALESCE(ps.is_future,0), COALESCE(ps.sort_order, 9999), s.title", (profile_id,)).fetchall()
    cur = [r for r in rows if not r["fut"]]
    seq_of = {(r["title"] or "").strip().lower(): seq for seq, r in enumerate(cur)}
    plan = [(r["id"], 0, seq) for seq, r in enumerate(cur)]
    nxt = len(cur)
    for r in rows:
        if r["fut"]:
            k = (r["title"] or "").strip().lower()
            if k in seq_of:
                plan.append((r["id"], 1, seq_of[k]))
            else:
                plan.append((r["id"], 1, nxt))
                nxt += 1
    return plan


def tc_pick_plan_size(db, skill_ids):
    """What a hand-made profile's picks come to, the way tc_profile_plan derives it: (current, future). Each pick is a
    current competency; its future is the same title one level up where that level is written and not itself a pick.
    The job profile panel's count (its script mirrors this) and set_skills' limit of TC_PROFILE_MAX both read it."""
    rows = []
    for sid in dict.fromkeys(str(x) for x in skill_ids):
        r = db.execute("SELECT id, title, level FROM tc_skills WHERE id=? AND active=1", (sid,)).fetchone()
        if r:
            rows.append(r)
    claimed, fut = {r["id"] for r in rows}, 0
    for r in rows:
        nxt = db.execute("SELECT id FROM tc_skills WHERE active=1 AND title=? AND level=? LIMIT 1",
                         ((r["title"] or "").strip(), (r["level"] or 0) + 1)).fetchone()
        if nxt and nxt["id"] not in claimed:
            claimed.add(nxt["id"])
            fut += 1
    return len(rows), fut


def tc_profile_pairs(db, profile_id):
    """A profile's competencies as people are assessed on them (tc_profile_plan), one entry a competency: its title and
    category, the current level and the future one (None where it has none, or for a next-role competency with no
    current pair). The job profile panel shows a job-architecture profile's five this way."""
    plan = tc_profile_plan(db, profile_id)
    sk = {r["id"]: r for r in db.execute(
        "SELECT id, title, level, skill_category FROM tc_skills WHERE id IN (%s)" % ",".join("?" * len(plan)),
        [p_[0] for p_ in plan])} if plan else {}
    out = {}
    for sid, fut, seq in plan:
        r = sk.get(sid)
        if not r:
            continue
        e = out.setdefault(seq, {"title": r["title"], "category": r["skill_category"] or "", "cur": None, "fut": None})
        e["fut" if fut else "cur"] = r["level"]
    return [out[k] for k in sorted(out)]


def tc_generate_assignments(db, me, cycle_id, commit=False):
    """Derive each person's assessed competencies from their job profile.

    Returns a report dict; writes nothing unless `commit`. Buckets are what the
    admin needs to decide, not decoration:

      assign  -- will get (or keep) a generated set
      released-- SKIPPED because their potential result is out for the cycle
      started -- SKIPPED because their assessment already has answers. This is
                 the one that matters: tc_scores cascades on tc_assignments, so
                 regenerating over a started assessment would silently delete
                 somebody's submitted answers. Never touched, ever.
      empty   -- matched a profile that lists no competencies yet
      unmapped-- no profile resolves for their role at all

    Idempotent: only rows this generator owns (source='profile') are replaced,
    so a hand-made or seeded assignment is left exactly where it is.
    """
    report = {"assign": [], "started": [], "empty": [], "unmapped": [], "not_part": [], "manual": [], "released": [],
              "rows": 0, "committed": bool(commit)}
    plans = {}
    # only people taking part in the cycle get a competency set (2026-10-02); the rest are listed, not assigned
    part = {r[0] for r in db.execute("SELECT id FROM users WHERE " + participant_sql(module='competency'))}
    for u in tc_profile_population(db, me):
        if u["id"] not in part:
            report["not_part"].append(u)
            continue
        prof, src = tc_profile_for_user(db, u)
        if not prof:
            report["unmapped"].append(u)
            continue
        if prof["id"] not in plans:
            plans[prof["id"]] = tc_profile_plan(db, prof["id"])
        plan = plans[prof["id"]]
        entry = {**u, "profile": prof, "source": src, "n_skills": len(plan)}
        if not plan:
            report["empty"].append(entry)
            continue
        if db.execute("SELECT 1 FROM tc_assignments WHERE cycle_id=? AND subject_id=? AND source='admin_profile' "
                      "LIMIT 1", (cycle_id, u["id"])).fetchone():
            report["manual"].append(entry)   # matched to another profile on their person page: HR's call stands
            continue
        if db.execute(
                "SELECT 1 FROM tc_scores sc JOIN tc_assignments a ON a.id = sc.assignment_id "
                "WHERE a.cycle_id=? AND a.subject_id=? LIMIT 1",
                (cycle_id, u["id"])).fetchone():
            report["started"].append(entry)
            continue
        if setup_released_at(db, u["id"], cycle_id, "pot"):
            report["released"].append(entry)   # their result is out: the set is final (Chris, 2026-10-18)
            continue
        report["assign"].append(entry)
        report["rows"] += len(plan)
        if commit:
            db.execute("DELETE FROM tc_assignments WHERE cycle_id=? AND subject_id=? "
                       "AND source='profile'", (cycle_id, u["id"]))
            for skill_id, is_future, seq in plan:
                db.execute(
                    "INSERT OR IGNORE INTO tc_assignments"
                    "(cycle_id, subject_id, skill_id, is_future, seq, source) "
                    "VALUES (?,?,?,?,?,'profile')",
                    (cycle_id, u["id"], skill_id, is_future, seq))
    if commit:
        db.commit()
    return report


# ---- The competency library (Chris, 2026-10-18: "ok, build them and deploy"; the libraries canvas boards 7-9 and the
# Requests board's competency tab) ------------------------------------------------------------------------------------
# Every job (a job code at its grade and scope) carries five competencies at the level it needs now and the same five
# one level up. A job held in several business groups is ONE profile, so an edit applies everywhere it is held. The
# super admin edits (a job's five, a competency's levels, P&R's sign-off of a new one); a BG or unit admin reads their
# group's jobs and proposes a new competency for a job, decided on Requests.
TC_LADDER_NOTE = ("From the ladder accepted on 17 Oct 2026: JG 12 to 14 at L3, 15 to 17 at L4, 18 to 21 at L5, 22 and "
                  "above at L6.")
TC_FIVE = 5
# A role is assessed on at most ten (Chris, 2026-10-19: "how many competencies have been selected for this role out
# of 10"): the architecture's five, each at the level now and the level above. A hand-made profile's picks count the
# same way, each pick its level plus the level above where one exists (tc_pick_plan_size).
TC_PROFILE_MAX = 2 * TC_FIVE
TC_TEXT_MAX = 2000


def tc_skill_source(code):
    """Who wrote a competency level: 'Chin Hin' (a CHG- competency, or a level Chin Hin wrote for an SSG one, its code
    carrying -CH) or 'SkillsFuture'."""
    c = (code or "").upper()
    return "Chin Hin" if c.startswith("CHG-") or re.search(r"-CH\d", c) else "SkillsFuture"


def _tc_skill_key(title):
    """A title compared: case and spaces ignored."""
    return " ".join((title or "").lower().split())


def tc_comp_key(code, title=None):
    """A competency's identity across its level rows: its code family, the code without its level digit and version
    (BEV-OPR-3005-1.1 and BEV-OPR-4005-1.1 are BEV-OPR-005; CHG-PRD-3008-1.0 is CHG-PRD-008). Not the title: two SSG
    sectors' skills share titles (production's data: 123 title-and-level clashes, never one inside a family). A code
    that doesn't parse falls back to its title."""
    m = re.match(r"^([A-Z]+-[A-Z0-9]+)-\d(\d{3})", (code or "").upper())
    return "%s-%s" % (m.group(1), m.group(2)) if m else "T:" + _tc_skill_key(title)


def _tc_lines(text, cap=30):
    """A textarea's lines as a list (bullets and blanks dropped), at most `cap`."""
    return [ln.strip().lstrip("-•").strip() for ln in (text or "").splitlines() if ln.strip().lstrip("-•").strip()][:cap]


def _tc_profile_holders(db):
    """{profile_id: [holder rows]} for every active job-code profile: the active people whose job code resolves to it by
    tc_profile_for_user's own rule (their scope's profile, else the code's scope-less one, else its first), in a few
    queries. A holder row: id, employee_id, job_grade, business_group, company."""
    by_code = {}
    for r in db.execute("SELECT id, job_code, job_scope FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL "
                        "ORDER BY id"):
        by_code.setdefault(r["job_code"], []).append(r)
    if not by_code:
        return {}
    users = db.execute("SELECT id, employee_id, job_grade, business_group, company FROM users "
                       "WHERE left_at IS NULL").fetchall()
    roles = ja_roles_map(db, [u["employee_id"] for u in users])
    out = {}
    for u in users:
        role = roles.get(ja_eid(u["employee_id"]))
        jc = ja_job_code(db, u, role) if role else None
        rows = by_code.get(jc) if jc else None
        if not rows:
            continue
        scope = (role["job_scope"] or "").strip().upper()
        r = (next((x for x in rows if scope and (x["job_scope"] or "").strip().upper() == scope), None)
             or next((x for x in rows if not (x["job_scope"] or "").strip()), None) or rows[0])
        out.setdefault(r["id"], []).append(u)
    return out


def _tc_lib_index(db):
    """The competency library in one pass (boards 7-9): every active job-code profile with its five (each competency's
    level now and next, and who wrote it), its people by business group, its job family and specialisation; the ladder
    of each specialisation; and every competency (a title across its level rows) with the jobs using it now and as their
    next level. A few queries, never one a row."""
    tax = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}
    profs = {}
    for r in db.execute("SELECT * FROM tc_job_profiles WHERE active=1 AND job_code IS NOT NULL"):
        parts = _ja_parts(r["job_code"]) or {}
        sub, spec = parts.get("sub"), parts.get("spec")
        profs[r["id"]] = {
            "id": r["id"], "code": r["job_code"], "scope": r["job_scope"] or "", "title": r["job_title"],
            "grade": parts.get("grade") or grade_num(r["job_grade"]), "sub": sub or "", "spec": spec or "",
            "base": parts.get("base") or r["job_code"],
            "sub_name": tax.get(sub) or r["department"] or sub or "Other", "spec_name": tax.get(spec) or spec or "",
            "status": r["review_status"] or "draft", "five": [], "next": {}, "people": 0, "bgs": {},
            "target": (r["source"] or "") == "target",
            # added, corrected or retired in OneHR (the super admin's; P&R's next load keeps it and lists it)
            "admin_at": r["admin_edited_at"], "admin_note": r["admin_edit_note"], "dept": r["department"]}   # a grade nobody holds yet (tc_fill_ladders, 2026-10-19)
    skills = {}
    for s in db.execute("SELECT id, skill_code, title, level, skill_category, active FROM tc_skills ORDER BY level, id"):
        k = tc_comp_key(s["skill_code"], s["title"])
        it = skills.setdefault(k, {"key": k, "title": s["title"], "category": s["skill_category"] or "Other",
                                   "rows": [], "active": False, "now": set(), "next": set()})
        it["rows"].append(dict(s))
        it["active"] = it["active"] or bool(s["active"])
    tcount = {}
    for it in skills.values():
        tcount[_tc_skill_key(it["title"])] = tcount.get(_tc_skill_key(it["title"]), 0) + 1
    for it in skills.values():
        lv = sorted({r["level"] for r in it["rows"] if r["level"]})
        it["levels"] = lv
        it["label"] = it["title"] + (" · %s" % it["key"] if tcount[_tc_skill_key(it["title"])] > 1 else "")
        it["ch"] = sum(1 for r in it["rows"] if tc_skill_source(r["skill_code"]) == "Chin Hin")
    for r in db.execute("SELECT ps.profile_id, ps.is_future, s.title, s.level, s.skill_code, s.skill_category "
                        "FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id=ps.skill_id "
                        "ORDER BY ps.profile_id, ps.is_future, ps.sort_order, ps.id"):
        p = profs.get(r["profile_id"])
        if not p:
            continue
        k = tc_comp_key(r["skill_code"], r["title"])
        if r["is_future"]:
            p["next"][k] = r["level"]
            skills[k]["next"].add(p["id"])
        else:
            p["five"].append({"key": k, "title": r["title"], "category": r["skill_category"] or "", "now": r["level"],
                              "code": r["skill_code"], "source": tc_skill_source(r["skill_code"])})
            skills[k]["now"].add(p["id"])
    holders = _tc_profile_holders(db)
    for pid, p in profs.items():
        for f in p["five"]:
            f["next"] = p["next"].get(f["key"])
        lv = [f["now"] for f in p["five"] if f["now"]]
        p["level"] = max(sorted(set(lv)), key=lv.count) if lv else None
        for h in holders.get(pid, []):
            p["people"] += 1
            bg = h["business_group"] or ""
            p["bgs"][bg] = p["bgs"].get(bg, 0) + 1
    ladders = {}   # one a job line: its unit (or specialisation) code and scope, every grade it is held at
    for p in profs.values():
        ladders.setdefault((p["base"], p["scope"].upper()), []).append(p["id"])
    for k_ in ladders:
        ladders[k_].sort(key=lambda i: (profs[i]["grade"] or 0, profs[i]["title"] or ""))
    return {"profiles": profs, "skills": skills, "ladders": ladders, "holders": holders}


def _tc_similar(skills):
    """{key: [similar competency titles]} within a category: the same name in two code families, or two names sharing
    at least two words and most of their words, for a person to look at (the catalogue's Similar names; on production's
    1,107 competencies, about 130). Never a decision."""
    stop = {"and", "of", "the", "for", "to", "in", "on", "with", "a", "an", "management", "&"}

    def words(t):
        return {w.rstrip("s") for w in re.findall(r"[a-z0-9]+", (t or "").lower()) if w not in stop}
    by_cat, out = {}, {}
    for it in skills.values():
        by_cat.setdefault(it["category"], []).append(it)
    for items in by_cat.values():
        ws = [(it, words(it["title"])) for it in items]
        for i, (a, wa) in enumerate(ws):
            for b, wb in ws[i + 1:]:
                if not wa or not wb:
                    continue
                same = _tc_skill_key(a["title"]) == _tc_skill_key(b["title"])
                if same or (len(wa & wb) >= 2 and len(wa & wb) / len(wa | wb) >= 0.6):
                    out.setdefault(a["key"], []).append(b["title"])
                    out.setdefault(b["key"], []).append(a["title"])
    return out


def _tc_save_five(db, me, prof, picks, refresh, act, commit=True):
    """Edit the five (super admin; board 7): a job's five competencies, each at the level the job needs now, the next
    level the same competency one up where that level is written (none past L6). One profile, so it applies in every
    business group that holds the job. Replaces its rows in one go, logged with before and after; a profile P&R had
    signed off goes back to draft. refresh also gives the new five to this cycle's holders who haven't started
    (_tc_assign_block / _tc_assign_from_profile). (summary, None) or (None, why). Its log row commits with the rest,
    unless the caller (Add a job, one transaction with the new profile's row) passes commit=False and commits itself."""
    if len(picks) != TC_FIVE or any(not k for k, _l in picks):
        return None, "Pick five competencies."
    if len({k for k, _l in picks}) != TC_FIVE:
        return None, "The five must be five different competencies."
    rows = {}
    for s in db.execute("SELECT id, skill_code, title, level, active FROM tc_skills WHERE active=1"):
        rows.setdefault((tc_comp_key(s["skill_code"], s["title"]), s["level"]), s)
    cur, fut = [], []
    for k, lvl in picks:
        if lvl not in range(1, 7):
            return None, "Each competency needs the level the job needs now, L1 to L6."
        r = rows.get((k, lvl))
        if not r:
            return None, "A competency you picked has no L%d written. Pick a level it has." % lvl
        cur.append(r)
        fut.append(rows.get((k, lvl + 1)) if lvl < 6 else None)
    before = [r[0] for r in db.execute(
        "SELECT s.skill_code FROM tc_job_profile_skills ps JOIN tc_skills s ON s.id=ps.skill_id WHERE ps.profile_id=? "
        "AND COALESCE(ps.is_future,0)=0 ORDER BY ps.sort_order, ps.id", (prof["id"],))]
    db.execute("DELETE FROM tc_job_profile_skills WHERE profile_id=?", (prof["id"],))
    for i, (c_, f_) in enumerate(zip(cur, fut), start=1):
        db.execute("INSERT INTO tc_job_profile_skills(profile_id, skill_id, required_level, sort_order, is_future) "
                   "VALUES (?,?,?,?,0)", (prof["id"], c_["id"], c_["level"], i))
        if f_:
            db.execute("INSERT INTO tc_job_profile_skills(profile_id, skill_id, required_level, sort_order, is_future) "
                       "VALUES (?,?,?,?,1)", (prof["id"], f_["id"], f_["level"], i))
    codes = [r[0] for r in db.execute("SELECT skill_code FROM tc_skills WHERE id IN (%s) ORDER BY id" % ",".join(
        "?" * len(cur)), [c_["id"] for c_ in cur])]
    back = (prof["review_status"] or "draft") != "draft"
    db.execute("UPDATE tc_job_profiles SET plan_mode='explicit', content_hash=?, review_status=?, updated_at="
               "datetime('now') WHERE id=?", (hashlib.sha256("|".join(sorted(codes)).encode()).hexdigest()[:16],
                                              "draft" if back else (prof["review_status"] or "draft"), prof["id"]))
    given = kept = 0
    if refresh and act:
        holders = _tc_profile_holders(db).get(prof["id"], [])
        for h in holders:
            p = db.execute("SELECT * FROM users WHERE id=?", (h["id"],)).fetchone()
            if _tc_assign_block(db, p, act):
                kept += 1
            else:
                _tc_assign_from_profile(db, act["id"], p["id"], prof["id"])
                given += 1
    after = [c_["title"] + " L%d" % c_["level"] for c_ in cur]
    log_activity(db, me["id"], "tc_profile", "%s (%s): the five changed%s: %s (was %s)%s" % (
        prof["job_title"], prof["job_code"], ", back to draft for P&R" if back else "", "; ".join(after),
        ", ".join(before) or "none", ("; this cycle's set given to %d, %d kept theirs (started)" % (given, kept))
        if refresh and act else ""), commit=commit)
    msg = "Saved: the five for %s." % prof["job_title"]
    if refresh and act:
        msg += " %d %s holding it now %s them for %s%s." % (
            given, "person" if given == 1 else "people", "has" if given == 1 else "have", act["name"],
            (" (%d had started and keep theirs)" % kept) if kept else "")
    if back:
        msg += " It goes back to P&R as a draft."
    return msg, None


def _tc_new_chg_code(db, sub, level, nnn=None):
    """A new Chin Hin competency's code at one level, CHG-<SUB>-<L><NNN>-1.0 (the pipeline's shape), NNN the next free
    number under the sub-family (every level of one competency shares it). (code, nnn)."""
    sub = re.sub(r"[^A-Z0-9]", "", (sub or "GEN").upper())[:4] or "GEN"
    if nnn is None:
        used = [int(m.group(1)) for (c,) in db.execute("SELECT skill_code FROM tc_skills WHERE skill_code LIKE ?",
                                                       ("CHG-%s-%%" % sub,))
                for m in [re.match(r"^CHG-%s-\d(\d{3})-" % re.escape(sub), c or "")] if m]
        nnn = (max(used) + 1) if used else 1
    return "CHG-%s-%d%03d-1.0" % (sub, level, nnn), nnn


def _tc_add_competency(db, me, title, cat, sub, levels, log=True):
    """THE writer of a new Chin Hin competency (the Requests approval and the super admin's Add a competency call it):
    one tc_skills row a level, CHG-<SUB>-<L><NNN>-1.0 (_tc_new_chg_code, every level sharing NNN), skill_type 'TSC',
    `active=0` until P&R sign it off (the library panel's sign-off). `levels` is [{level, description, abilities,
    knowledge}] with the two item lists as lists. A name the catalogue already holds is refused. (last code, None) or
    (None, why); the caller commits. log=False when the caller writes its own trail row (the approval does)."""
    if any(_tc_skill_key(t) == _tc_skill_key(title) for (t,) in db.execute("SELECT DISTINCT title FROM tc_skills")):
        return None, "'%s' is in the catalogue already." % title
    nnn, code, codes = None, None, []
    for lv in levels:
        code, nnn = _tc_new_chg_code(db, sub, lv["level"], nnn)
        db.execute("INSERT INTO tc_skills(skill_code, title, level, skill_type, skill_category, "
                   "proficiency_description, knowledge_items, ability_items, active) VALUES (?,?,?,?,?,?,?,?,0)",
                   (code, title, lv["level"], "TSC", cat, lv["description"],
                    "\n".join(lv["knowledge"]), "\n".join(lv["abilities"])))
        codes.append(code)
    if log:
        log_activity(db, me["id"], "tc_skill", "%s: added as a new competency (%s), off until P&R sign it off" % (
            title, ", ".join(codes)), commit=False)
    return code, None


def _comp_request_email(db, req, word, note=""):
    """The answer to a competency proposal, to the proposer's notification emails (production only). A short word for
    the flash; a failure never undoes the decision."""
    if not mailer.is_configured():
        return "No email: this server sends none."
    if not admin_notify_addresses(db, req["created_by"]):
        return "No email: they have no notification emails set."
    pl = json.loads(req["payload_json"])
    esc = lambda v: html.escape(str(v))   # noqa: E731
    n = _admin_task_email(
        db, req["created_by"], "Your competency proposal: %s" % word, "Your competency proposal: %s" % word,
        ["The super admin has %s your proposal for <b>%s</b> (%s)." % (esc(word), esc(pl.get("title")),
                                                                    esc(pl.get("job_title") or ""))],
        box=_em_box(["&ldquo;%s&rdquo;" % esc(note)]) if note else "",
        button=("Open your proposals", app_base_url() + url_for("admin_competency_requests")))
    return "Emailed them." if n else "The email to them failed to send."


def _tc_lib_scope(me):
    """The business groups an admin sees in the competency library: None for the super admin (all), else their own."""
    return None if is_super(me) else [admin_bg_of(me)]


