TC_GRADE_MAX = max(TC_LADDER_LEVELS)   # the highest grade the platform uses (JG 23: every BG CEO); a job code carries a number
TC_JOB_TEXT_MAX = 120
TC_JOB_NOTE_MAX = 500
TC_RETIRED_NOTE = "Retired: "          # admin_edit_note of a job retired in OneHR; P&R's load keeps it retired


def _tc_retired_title(title, active):
    """A job's title as people read it where a retired job can still show (a Career Plan that aims at it)."""
    return "%s (retired)" % title if title and active is not None and not active else title


def _tc_job_text(form, field, maxlen=TC_JOB_TEXT_MAX):
    """(text, why): a typed job title or scope: single-spaced, never trimmed to fit, screened as a stored note."""
    t = " ".join((form.get(field) or "").split())
    if len(t) > maxlen:
        return None, "That is %d characters; at most %d." % (len(t), maxlen)
    if ai_draft.stored_text_refusal(t, "manager"):
        return None, "That text can't be saved as written. Keep it to the job's own name."
    return t, None


def _tc_job_spec_lists(ix):
    """(specs, units, bases) read from the active job-coded profiles: {spec code: its sub / names}, {unit base: spec code},
    {base: {grades, codes: {grade: [scopes]}, starts: [profiles with their five]}}: what Add a job picks from."""
    specs, units, bases = {}, {}, {}
    for p in ix["profiles"].values():
        if not p["spec"] or not p["grade"]:
            continue
        specs.setdefault(p["spec"], {"code": p["spec"], "sub": p["sub"], "sub_name": p["sub_name"],
                                     "spec_name": p["spec_name"]})
        if p["base"] != p["spec"]:
            units[p["base"]] = p["spec"]
        b = bases.setdefault(p["base"], {"grades": set(), "codes": {}, "starts": []})
        b["grades"].add(p["grade"])
        b["codes"].setdefault(str(p["grade"]), []).append((p["scope"] or "").strip().upper())
        b["starts"].append({"id": p["id"], "grade": p["grade"], "title": p["title"], "scope": p["scope"] or "",
                            "five": [{"key": f["key"], "now": f["now"]} for f in p["five"]]})
    return specs, units, bases


def _tc_addjob_ctx(ix, pre):
    """What the Add a job panel draws from, as one JSON-able dict: the specialisations (label, units), each base's grades,
    existing scopes and the jobs to start its five from, the grade range, and what to preselect (the open job's place)."""
    specs, units, bases = _tc_job_spec_lists(ix)
    out = []
    for sp in specs.values():
        names = sp["sub_name"] + ((" › " + sp["spec_name"]) if sp["spec_name"] and sp["spec_name"] not in (
            sp["sub_name"], sp["code"]) else "")
        out.append({"code": sp["code"], "label": "%s · %s" % (names, sp["code"]),
                    "units": sorted(b for b, s in units.items() if s == sp["code"])})
    out.sort(key=lambda x: x["label"].lower())
    return {"specs": out, "bases": {b: {"grades": sorted(v["grades"]), "codes": v["codes"],
                                        "starts": sorted(v["starts"], key=lambda x: (x["grade"], x["title"] or ""))}
                                    for b, v in bases.items()},
            "gmin": JA_MIN_GRADE, "gmax": TC_GRADE_MAX, "pre": pre,
            "need": {str(g): tc_grade_proficiency(g) for g in range(JA_MIN_GRADE, TC_GRADE_MAX + 1)}}


def _tc_add_job(db, me):
    """Add a job (super admin): a job code at one grade, picked from the architecture's own lists, with its five. Code =
    unit (or specialisation) + grade, built here and never typed; refused when it (with the scope) exists, when the
    legacy (department, title, grade) key is taken, for a letter grade or a base nobody listed. Starts a draft with P&R,
    source 'admin', flagged as changed in OneHR; nobody holds it until a person is placed on it. One transaction with its
    five (_tc_save_five), the trail row inside it."""
    f = request.form
    ix = _tc_lib_index(db)
    specs, units, bases = _tc_job_spec_lists(ix)
    keep = {"panel": "addjob", "aj_spec": (f.get("spec") or "")[:40], "aj_unit": (f.get("unit") or "")[:40],
            "aj_grade": (f.get("grade") or "")[:4], "aj_title": (f.get("title") or "")[:TC_JOB_TEXT_MAX * 2],
            "aj_scope": (f.get("scope") or "")[:TC_JOB_TEXT_MAX * 2], "by": f.get("by") if f.get("by") == "jf" else None}

    def refuse(why):
        flash(why, "error")
        return redirect(url_for("admin_competency_library", **keep))
    spec = (f.get("spec") or "").strip().upper()
    if spec not in specs:
        return refuse("Pick where the job sits from the list: a specialisation of the job architecture.")
    unit = (f.get("unit") or "").strip().upper()
    if unit and units.get(unit) != spec:
        return refuse("Pick a unit under that specialisation from the list, or none.")
    base = unit or spec
    gtxt = (f.get("grade") or "").strip()
    if not gtxt.isdigit():
        return refuse("A job code ends in a number: pick a job grade from JG %d to JG %d. A letter grade is not part of "
                      "the architecture." % (JA_MIN_GRADE, TC_GRADE_MAX))
    grade = int(gtxt)
    if not JA_MIN_GRADE <= grade <= TC_GRADE_MAX:
        return refuse("Pick a job grade from JG %d to JG %d." % (JA_MIN_GRADE, TC_GRADE_MAX))
    code = "%s-%d" % (base, grade)
    pp = _ja_parts(code)
    if not pp or pp["base"] != base or pp["grade"] != grade:
        return refuse("%s is not a job code the architecture can read." % code)
    title, why = _tc_job_text(f, "title")
    if why or not title:
        return refuse("Job title: " + (why or "give the job a title."))
    scope, why = _tc_job_text(f, "scope")
    if why:
        return refuse("Job scope: " + why)
    scope_u = scope.upper()
    dup = db.execute("SELECT id, active FROM tc_job_profiles WHERE job_code=? AND UPPER(TRIM(COALESCE(job_scope,'')))=?",
                     (code, scope_u)).fetchone()
    if dup and dup["active"]:
        return refuse("%s%s is already a job: open it in the Library." % (code, (" (scope %s)" % scope) if scope else ""))
    if dup:
        return refuse("%s%s belonged to a job that has been retired, and a code can't be used twice. Give this job a job "
                      "scope to tell it apart." % (code, (" (scope %s)" % scope) if scope else ""))
    mates = [p for p in ix["profiles"].values() if p["base"] == base] or [
        p for p in ix["profiles"].values() if p["spec"] == spec]
    dept = next((p["dept"] for p in mates if p["dept"]), None) or mates[0]["sub_name"] or spec
    if db.execute("SELECT 1 FROM tc_job_profiles WHERE LOWER(department)=LOWER(?) AND LOWER(job_title)=LOWER(?) AND "
                  "job_grade=?", (dept, title, str(grade))).fetchone():
        return refuse("A job called '%s' already exists at JG %d in %s (a retired one counts). Give this job a title that "
                      "tells them apart." % (title, grade, dept))
    picks = []
    for i in range(1, TC_FIVE + 1):
        try:
            lv = int(f.get("level_%d" % i) or 0)
        except ValueError:
            lv = 0
        picks.append(((f.get("skill_%d" % i) or "").strip(), lv))
    try:
        pid = db.execute(
            "INSERT INTO tc_job_profiles(department, job_title, job_grade, proficiency_level, source, active, job_code, "
            "job_scope, plan_mode, review_status, admin_edited_at, admin_edited_by, admin_edit_note) "
            "VALUES (?,?,?,?,'admin',1,?,?, 'explicit','draft', datetime('now'), ?, 'Added in OneHR')",
            (dept, title, str(grade), tc_grade_proficiency(grade), code, scope_u or None, me["id"])).lastrowid
    except sqlite3.IntegrityError:
        db.rollback()
        return refuse("%s is already a job: open it in the Library." % code)
    prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=?", (pid,)).fetchone()
    msg, why = _tc_save_five(db, me, prof, picks, False, None, commit=False)
    if why:
        db.rollback()
        return refuse(why)
    five = [r[0] for r in db.execute("SELECT s.title || ' L' || s.level FROM tc_job_profile_skills ps JOIN tc_skills s ON "
                                     "s.id=ps.skill_id WHERE ps.profile_id=? AND ps.is_future=0 ORDER BY ps.sort_order",
                                     (pid,))]
    log_activity(db, me["id"], "tc_profile", "added the job %s (%s), JG %d%s, as a draft for P&R: %s" % (
        title, code, grade, (", scope " + scope) if scope else "", "; ".join(five)), commit=False)
    db.commit()
    flash("Added: %s, JG %d (%s). It starts as a draft with P&R, and nobody holds it until a person is placed on it "
          "(their page > Competency > Place a job)." % (title, grade, code), "ok")
    return redirect(url_for("admin_competency_library", job=pid, by=keep["by"]))


def _tc_fix_job(db, me):
    """Correct the job (super admin): its title and job scope only. The job code and grade decide who holds it, so they are
    never edited (add the right job, place its people, retire this one). A reason is required; nothing-changed, a legacy
    (department, title, grade) clash and a (code, scope) clash are refused. Sets admin_edited_*, so P&R's next load keeps
    the title and lists it. A scope change can change who resolves to the job: the flash and the trail say how many held it
    before and after."""
    f = request.form
    prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1 AND job_code IS NOT NULL",
                      (_form_int("profile_id"),)).fetchone()
    if not prof:
        abort(404)
    back = url_for("admin_competency_library", job=prof["id"], panel="fixjob", by=f.get("by") if f.get("by") == "jf" else None)

    def refuse(why):
        flash(why, "error")
        return redirect(back)
    title, why = _tc_job_text(f, "title")
    if why or not title:
        return refuse("Job title: " + (why or "give the job a title."))
    scope, why = _tc_job_text(f, "scope")
    if why:
        return refuse("Job scope: " + why)
    reason = (f.get("reason") or "").strip()
    if not reason:
        return refuse("Say why it is corrected: it goes in the audit trail and on P&R's list.")
    if len(reason) > TC_JOB_NOTE_MAX:
        return refuse("The reason is %d characters; at most %d." % (len(reason), TC_JOB_NOTE_MAX))
    if ai_draft.stored_text_refusal(reason, "manager"):
        return refuse("That reason can't be saved as written.")
    old_scope = (prof["job_scope"] or "").strip()
    if title == prof["job_title"] and scope.upper() == old_scope.upper():
        return refuse("Nothing changed on %s." % prof["job_title"])
    if scope.upper() != old_scope.upper() and db.execute(
            "SELECT 1 FROM tc_job_profiles WHERE job_code=? AND id!=? AND UPPER(TRIM(COALESCE(job_scope,'')))=?",
            (prof["job_code"], prof["id"], scope.upper())).fetchone():
        return refuse("%s already has a job with that scope (a retired one counts)." % prof["job_code"])
    if db.execute("SELECT 1 FROM tc_job_profiles WHERE id!=? AND LOWER(department)=LOWER(?) AND LOWER(job_title)=LOWER(?) "
                  "AND job_grade=?", (prof["id"], prof["department"], title, prof["job_grade"])).fetchone():
        return refuse("A job called '%s' already exists at JG %s in %s (a retired one counts). Give this job a title that "
                      "tells them apart." % (title, prof["job_grade"], prof["department"]))
    scope_change = scope.upper() != old_scope.upper()
    n_before = len(_tc_profile_holders(db).get(prof["id"], [])) if scope_change else None
    db.execute("UPDATE tc_job_profiles SET job_title=?, job_scope=?, admin_edited_at=datetime('now'), admin_edited_by=?, "
               "admin_edit_note=?, updated_at=datetime('now') WHERE id=?",
               (title, scope.upper() or None, me["id"], reason, prof["id"]))
    n_after = len(_tc_profile_holders(db).get(prof["id"], [])) if scope_change else None
    ch = []
    if title != prof["job_title"]:
        ch.append("title '%s' to '%s'" % (prof["job_title"], title))
    if scope_change:
        ch.append("scope '%s' to '%s'; people holding it %d before, %d after" % (old_scope, scope.upper(), n_before, n_after))
    log_activity(db, me["id"], "tc_profile", "corrected the job %s (%s): %s. Reason: %s" % (
        prof["job_title"], prof["job_code"], "; ".join(ch), reason), commit=False)
    db.commit()
    flash("Saved: the correction to %s (%s)%s. It stays when P&R load their next job architecture file, and is on their "
          "list." % (title, prof["job_code"], ("; %d %s hold it now (%d before)" % (
              n_after, "person" if n_after == 1 else "people", n_before)) if scope_change else ""), "ok")
    return redirect(url_for("admin_competency_library", job=prof["id"], by=f.get("by") if f.get("by") == "jf" else None))


def _tc_retire_job(db, me):
    """Retire the job (super admin): refused while anyone holds it (_tc_profile_holders), else `active=0` with the reason,
    flagged changed in OneHR. Nothing is deleted: a Career Plan or development goal that points at it keeps the id and
    reads '<title> (retired)'. P&R's next load keeps it retired."""
    f = request.form
    prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1 AND job_code IS NOT NULL",
                      (_form_int("profile_id"),)).fetchone()
    if not prof:
        abort(404)
    back = url_for("admin_competency_library", job=prof["id"], panel="fixjob", by=f.get("by") if f.get("by") == "jf" else None)
    reason = (f.get("reason") or "").strip()
    if not reason:
        flash("Say why it is retired: it goes in the audit trail.", "error")
        return redirect(back)
    if len(reason) > TC_JOB_NOTE_MAX or ai_draft.stored_text_refusal(reason, "manager"):
        flash("That reason can't be saved: keep it to %d characters of plain words." % TC_JOB_NOTE_MAX, "error")
        return redirect(back)
    n = len(_tc_profile_holders(db).get(prof["id"], []))
    if n:
        flash("%d %s hold it. Place them on another job first." % (n, "person" if n == 1 else "people"), "error")
        return redirect(back)
    db.execute("UPDATE tc_job_profiles SET active=0, admin_edited_at=datetime('now'), admin_edited_by=?, admin_edit_note=?, "
               "updated_at=datetime('now') WHERE id=?", (me["id"], TC_RETIRED_NOTE + reason, prof["id"]))
    log_activity(db, me["id"], "tc_profile", "retired the job %s (%s), JG %s. Reason: %s" % (
        prof["job_title"], prof["job_code"], prof["job_grade"], reason), commit=False)
    db.commit()
    flash("Retired: %s (%s). Career Plans that aimed at it keep it, marked retired." % (prof["job_title"], prof["job_code"]),
          "ok")
    return redirect(url_for("admin_competency_library", by=f.get("by") if f.get("by") == "jf" else None))


def _tc_chg_groups(db, ix):
    """The code groups a new Chin Hin competency can sit under, as [{code, label, next}]: every job sub-family in use and
    every sub-family the taxonomy names, by its last code segment (MFG-PRD > PRD), with the next free NNN (a preview: the
    real code is made by _tc_new_chg_code when it is saved)."""
    tax = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy WHERE level='sub'")}
    names = {}
    for p in ix["profiles"].values():
        if p["sub"]:
            names.setdefault(p["sub"], p["sub_name"])
    for code, nm in tax.items():
        names[code] = nm
    groups = {}
    for sub, nm in names.items():
        seg = re.sub(r"[^A-Z0-9]", "", sub.split("-")[-1].upper())[:4]
        if seg:
            g = groups.setdefault(seg, [])
            if nm and nm not in g:
                g.append(nm)
    used = {}
    for (c,) in db.execute("SELECT skill_code FROM tc_skills WHERE skill_code LIKE 'CHG-%'"):
        m = re.match(r"^CHG-([A-Z0-9]+)-\d(\d{3})-", c or "")
        if m:
            used[m.group(1)] = max(used.get(m.group(1), 0), int(m.group(2)))
    return [{"code": seg, "label": "%s · %s" % (seg, " / ".join(sorted(nms))) if nms else seg,
             "next": used.get(seg, 0) + 1} for seg, nms in sorted(groups.items())]


def _tc_add_comp_form(db, me):
    """Add a competency (super admin): a name, a category, the code group, and for each level chosen its description,
    abilities and knowledge (SkillsFuture's shape). Written by _tc_add_competency, the writer the Requests approval uses:
    a Chin Hin competency, `active=0` until P&R sign it off."""
    f = request.form
    ix = _tc_lib_index(db)
    back = url_for("admin_competency_catalogue")

    def refuse(why):
        flash(why, "error")
        return redirect(back + "?panel=addcomp")
    title, why = _tc_job_text(f, "title")
    if why or not title:
        return refuse("Name: " + (why or "give the competency a name."))
    cat = " ".join(_tc_cat_from_form(f).split())
    if not cat or len(cat) > TC_JOB_TEXT_MAX:
        return refuse("Pick a category, or name a new one (at most %d characters)." % TC_JOB_TEXT_MAX)
    sub = (f.get("sub") or "").strip().upper()
    if sub not in {g["code"] for g in _tc_chg_groups(db, ix)}:
        return refuse("Pick the code group from the list.")
    lvls = sorted({int(x) for x in f.getlist("lv") if x.isdigit() and 1 <= int(x) <= 6})
    if not lvls:
        return refuse("Choose at least one level to write.")
    levels = []
    for n in lvls:
        desc = (f.get("desc_%d" % n) or "").strip()
        abil, know = _tc_lines(f.get("abil_%d" % n)), _tc_lines(f.get("know_%d" % n))
        if not desc or not abil or not know:
            return refuse("Each level needs its description, at least one ability and at least one knowledge item "
                          "(L%d is missing one)." % n)
        if len(desc) > TC_TEXT_MAX:
            return refuse("L%d's description is %d characters; at most %d." % (n, len(desc), TC_TEXT_MAX))
        levels.append({"level": n, "description": desc, "abilities": abil, "knowledge": know})
    if any(ai_draft.stored_text_refusal(t_, "manager") for lv in levels
           for t_ in [lv["description"]] + lv["abilities"] + lv["knowledge"]):
        return refuse("That text can't be saved as written. Keep it to what the competency means.")
    code, why = _tc_add_competency(db, me, title, cat, sub, levels)
    if why:
        return refuse(why)
    db.commit()
    flash("Added: %s. It is in the catalogue but off until P&R sign it off; sign it off in its panel once they have "
          "approved the wording." % title, "ok")
    return redirect(url_for("admin_competency_library", skill=tc_comp_key(code), panel="skill"))


@app.route("/admin/competency/library", methods=["GET", "POST"])
@admin_required
def admin_competency_library():
    """Competency > Library (2026-10-18, boards 7 and 8): the jobs by business group (or job family first), a job's five
    with the level now and next and who wrote each, its specialisation's ladder, and a competency opened with its levels
    and every job using it. The super admin edits: Edit the five, a competency's levels, P&R's sign-off of a new one.
    A BG or unit admin reads their group's jobs and proposes a new competency for one. Double-confirmed, in the trail."""
    db = get_db()
    me = current_user()
    sup = is_super(me)
    scope = _tc_lib_scope(me)
    if request.method == "POST":
        action = request.form.get("action") or ""
        if action == "propose":
            return _tc_propose(db, me)
        if not sup:
            abort(403)
        if action == "addjob":
            return _tc_add_job(db, me)
        if action == "fixjob":
            return _tc_fix_job(db, me)
        if action == "retire":
            return _tc_retire_job(db, me)
        if action == "addcomp":
            return _tc_add_comp_form(db, me)
        if action == "five":
            prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1 AND job_code IS NOT NULL",
                              (_form_int("profile_id"),)).fetchone()
            if not prof:
                abort(404)
            picks = []
            for i in range(1, TC_FIVE + 1):
                k = (request.form.get("skill_%d" % i) or "").strip()
                try:
                    lv = int(request.form.get("level_%d" % i) or 0)
                except ValueError:
                    lv = 0
                picks.append((k, lv))
            msg, why = _tc_save_five(db, me, prof, picks, bool(request.form.get("refresh")), active_cycle(db))
            if why:
                flash(why, "error")
                return redirect(url_for("admin_competency_library", job=prof["id"], panel="five"))
            db.commit()
            flash(msg, "ok")
            return redirect(url_for("admin_competency_library", job=prof["id"], by=request.form.get("by") or None))
        key = (request.form.get("key") or "").strip()
        rows = [r for r in db.execute("SELECT * FROM tc_skills ORDER BY level, id").fetchall()
                if tc_comp_key(r["skill_code"], r["title"]) == key]
        if not rows:
            abort(404)
        back = url_for("admin_competency_library", skill=key, job=request.form.get("job") or None)
        if action == "signoff":
            n = db.execute("UPDATE tc_skills SET active=1, updated_at=datetime('now') WHERE id IN (%s) AND active=0"
                           % ",".join("?" * len(rows)), [r["id"] for r in rows]).rowcount
            log_activity(db, me["id"], "tc_skill", "%s: signed off by P&R, in use (%d level%s)" % (
                rows[0]["title"], n, "" if n == 1 else "s"))
            db.commit()
            flash("%s is signed off and can go on a job (Edit the five)." % rows[0]["title"], "ok")
            return redirect(back)
        if action != "skill":
            abort(400)
        title = " ".join((request.form.get("title") or "").split())[:120]
        cat = " ".join(_tc_cat_from_form(request.form).split())[:120] or None
        if not title:
            flash("Give the competency a name.", "error")
            return redirect(back + "&edit=1")
        nk = _tc_skill_key(title)
        if nk != _tc_skill_key(rows[0]["title"]) and any(
                _tc_skill_key(t) == nk for (t,) in db.execute("SELECT DISTINCT title FROM tc_skills")):
            flash("Another competency is called '%s' already." % title, "error")
            return redirect(back + "&edit=1")
        for r in rows:
            desc = (request.form.get("desc_%d" % r["id"]) or "").strip()
            if not desc:
                flash("Each level needs its description.", "error")
                return redirect(back + "&edit=1")
            if len(desc) > TC_TEXT_MAX:
                flash("A level's description is %d characters at most." % TC_TEXT_MAX, "error")
                return redirect(back + "&edit=1")
        changed = 0
        for r in rows:
            vals = (title, cat, request.form.get("desc_%d" % r["id"]).strip(),
                    "\n".join(_tc_lines(request.form.get("abil_%d" % r["id"]))) or None,
                    "\n".join(_tc_lines(request.form.get("know_%d" % r["id"]))) or None)
            if vals != (r["title"], r["skill_category"], r["proficiency_description"], r["ability_items"],
                        r["knowledge_items"]):
                db.execute("UPDATE tc_skills SET title=?, skill_category=?, proficiency_description=?, ability_items=?, "
                           "knowledge_items=?, updated_at=datetime('now') WHERE id=?", vals + (r["id"],))
                changed += 1
        if not changed:
            flash("Nothing changed on %s." % rows[0]["title"], "ok")
            return redirect(back)
        used = db.execute("SELECT COUNT(DISTINCT ps.profile_id) FROM tc_job_profile_skills ps WHERE ps.skill_id IN (%s)"
                          % ",".join("?" * len(rows)), [r["id"] for r in rows]).fetchone()[0]
        log_activity(db, me["id"], "tc_skill", "%s%s: %d level%s edited; used by %d job%s" % (
            rows[0]["title"], (" renamed %s" % title) if title != rows[0]["title"] else "", changed,
            "" if changed == 1 else "s", used, "" if used == 1 else "s"))
        db.commit()
        flash("Saved: %s, for all %d job%s that use it." % (title, used, "" if used == 1 else "s"), "ok")
        return redirect(url_for("admin_competency_library", skill=key, job=request.form.get("job") or None))

    ix = _tc_lib_index(db)
    profs, skills = ix["profiles"], ix["skills"]
    by = request.args.get("by") if request.args.get("by") in ("bg", "jf") else "bg"
    q = " ".join((request.args.get("q") or "").split())[:80]
    ql = q.lower()

    def seen(p):   # in this admin's groups (a BG or unit admin), and matching the search
        if scope is not None and not (set(p["bgs"]) & set(scope)):
            return False
        return not ql or ql in (p["title"] or "").lower() or ql in (p["code"] or "").lower()
    vis = [p for p in profs.values() if seen(p)]

    def nest(items):   # job family > specialisation > jobs, biggest family first
        fams = {}
        for p in items:
            f = fams.setdefault(p["sub"], {"code": p["sub"], "name": p["sub_name"], "specs": {}, "n": 0})
            s = f["specs"].setdefault(p["spec"], {"code": p["spec"], "name": p["spec_name"] or p["sub_name"],
                                                  "jobs": []})
            s["jobs"].append(p)
            f["n"] += 1
            # the title without the specialisation it sits under ("Executive, Sales" under Sales reads "Executive")
            for nm in (s["name"], p["sub_name"]):
                suf = ", " + (nm or "").lower()
                if nm and (p["title"] or "").lower().endswith(suf) and len(p["title"]) > len(suf):
                    p["short"] = p["title"][:-len(suf)]
                    break
            else:
                p["short"] = p["title"]
        out = sorted(fams.values(), key=lambda f: (-f["n"], f["name"]))
        for f in out:
            f["specs"] = sorted(f["specs"].values(), key=lambda s: (-len(s["jobs"]), s["name"]))
            for s in f["specs"]:
                s["jobs"].sort(key=lambda p: (p["base"], p["scope"], p["grade"] or 0, p["title"] or ""))
        return out
    tree = []
    if by == "bg":
        bgs = sorted({b for p in vis for b in p["bgs"] if b and (scope is None or b in scope)},
                     key=lambda b: display_bg(b))
        for b in bgs:
            items = [p for p in vis if b in p["bgs"]]
            tree.append({"bg": b, "n": len(items), "fams": nest(items)})
        unheld = [p for p in vis if not p["bgs"]] if scope is None else []
        if unheld:
            tree.append({"bg": "", "n": len(unheld), "fams": nest(unheld)})
    else:
        tree = [{"bg": None, "n": len(vis), "fams": nest(vis)}]
    jid = request.args.get("job", type=int)
    job = profs.get(jid) if jid in profs and profs[jid] in vis else None
    if not job and tree and tree[0]["fams"]:
        job = tree[0]["fams"][0]["specs"][0]["jobs"][0]
    g = request.args.get("g") or ""
    if job and (by != "bg" or g not in job["bgs"] or (scope is not None and g not in scope)):
        mine = [b for b in job["bgs"] if scope is None or b in scope]   # a BG admin reads it as their group's
        g = max(mine, key=job["bgs"].get) if mine else ""
    ladder = [profs[i] for i in ix["ladders"].get((job["base"], job["scope"].upper()), [])] if job else []
    sk = skills.get((request.args.get("skill") or "").strip()) if request.args.get("skill") else None
    opened = None
    if sk:
        uses = sorted(sk["now"] | sk["next"], key=lambda i: (profs[i]["title"] or "", profs[i]["grade"] or 0))
        uses = [{"p": profs[i], "now": next((f["now"] for f in profs[i]["five"] if f["key"] == sk["key"]), None),
                 "next": profs[i]["next"].get(sk["key"])} for i in uses
                if scope is None or set(profs[i]["bgs"]) & set(scope)]
        full = [dict(r) for r in db.execute("SELECT * FROM tc_skills WHERE id IN (%s) ORDER BY level, id" % ",".join(
            "?" * len(sk["rows"])), [r["id"] for r in sk["rows"]])]
        for r in full:
            r["source"] = tc_skill_source(r["skill_code"])
            r["abilities"] = _tc_ability_list(r["ability_items"])
            r["knowledge"] = _tc_ability_list(r["knowledge_items"])
        req = db.execute("SELECT r.*, u.full_name AS who FROM tc_library_requests r LEFT JOIN users u ON u.id=r.created_by "
                         "WHERE r.result_key=? AND r.status='approved' ORDER BY r.id DESC LIMIT 1",
                         (sk["key"],)).fetchone()
        opened = {"sk": sk, "rows": full, "uses": uses, "added": min((r["created_at"] for r in full if r["created_at"]), default=None), "n_now": len(sk["now"]), "n_next": len(sk["next"] - sk["now"]),
                  "req": dict(req) if req else None, "req_pl": json.loads(req["payload_json"]) if req else None}
    five_opts = addjob = None
    pnl = request.args.get("panel") if sup else None
    if sup and (pnl == "addjob" or (job and pnl == "five")):
        five_opts = {}
        for it in sorted(skills.values(), key=lambda x: (x["category"], x["title"])):
            lv = sorted({r["level"] for r in it["rows"] if r["active"] and r["level"]})
            if lv:
                five_opts.setdefault(it["category"], []).append({"key": it["key"], "title": it["label"], "levels": lv})
    if pnl == "addjob":   # opened from a job: its specialisation (and unit) are preselected; a refused save brings its values back
        a_ = request.args
        pre = {"spec": (a_.get("aj_spec") or (job["spec"] if job else "")).upper(),
               "unit": (a_.get("aj_unit") if "aj_spec" in a_ else (job["base"] if job and job["base"] != job["spec"] else ""))
               or "", "grade": a_.get("aj_grade") or "", "title": a_.get("aj_title") or "", "scope": a_.get("aj_scope") or ""}
        addjob = _tc_addjob_ctx(ix, pre)
    act = active_cycle(db)
    n_wait = db.execute("SELECT COUNT(*) FROM tc_library_requests WHERE status='waiting'%s" % (
        "" if sup else " AND created_by=?"), () if sup else (me["id"],)).fetchone()[0]
    cats = sorted({it["category"] for it in skills.values()})
    return render_template(
        "admin_competency_library.html", ix=ix, tree=tree, by=by, q=q, job=job, g=g, ladder=ladder, opened=opened,
        sup=sup, five_opts=five_opts, addjob=addjob, fixjob=bool(sup and job and pnl == "fixjob"), act=act, n_wait=n_wait,
        cats=cats, ladder_note=TC_LADDER_NOTE,
        n_jobs=len(vis), edit=bool(sup and request.args.get("edit")),
        holders_now=len(ix["holders"].get(job["id"], [])) if job else 0)


def _tc_propose(db, me):
    """A BG or unit admin proposes a new competency for a job held in their group (the Requests board): written in
    SkillsFuture's shape, a description, abilities and knowledge at the level the job needs now and the next one. The
    super admin decides on Requests; approved, it is added as a Chin Hin competency (CHG-), inactive until P&R sign it
    off. Their reason is required. Logged; the super admins are emailed."""
    bg = admin_bg_of(me)
    if not bg:   # the super admin edits the library directly
        abort(403)
    ix = _tc_lib_index(db)
    p = ix["profiles"].get(_form_int("profile_id"))
    if not p or bg not in p["bgs"]:
        abort(404)
    back = url_for("admin_competency_library", job=p["id"], panel="propose")
    title = " ".join((request.form.get("title") or "").split())[:120]
    cat = " ".join(_tc_cat_from_form(request.form).split())[:120]
    reason = (request.form.get("reason") or "").strip()[:500]
    if not (title and cat and reason):
        flash("Give it a name, a category and your reason.", "error")
        return redirect(back)
    if _tc_skill_key(title) in {_tc_skill_key(it["title"]) for it in ix["skills"].values()}:
        flash("'%s' is in the catalogue already: ask the super admin to put it on the job." % title, "error")
        return redirect(back)
    now = p["level"] or 3
    levels = []
    for lvl in ([now, now + 1] if now < 6 else [now]):
        desc = (request.form.get("desc_%d" % lvl) or "").strip()[:TC_TEXT_MAX]
        abil = _tc_lines(request.form.get("abil_%d" % lvl))
        know = _tc_lines(request.form.get("know_%d" % lvl))
        if not desc or not abil or not know:
            flash("Each level needs its description, at least one ability and at least one knowledge item.", "error")
            return redirect(back)
        levels.append({"level": lvl, "description": desc, "abilities": abil, "knowledge": know})
    if any(ai_draft.stored_text_refusal(t_, "manager")
           for t_ in [title, reason] + [lv["description"] for lv in levels]):
        flash("That text can't be sent as written. Keep it to what the competency means.", "error")
        return redirect(back)
    pl = {"title": title, "category": cat, "job_title": p["title"], "job_code": p["code"], "grade": p["grade"],
          "sub": p["sub"], "levels": levels}
    db.execute("INSERT INTO tc_library_requests(kind, business_group, profile_id, payload_json, reason, created_by) "
               "VALUES ('new_comp',?,?,?,?,?)", (bg, p["id"], json.dumps(pl), reason, me["id"]))
    log_activity(db, me["id"], "tc_request", "proposed a new competency: %s, for %s (%s)" % (title, p["title"],
                                                                                           p["code"]))
    db.commit()
    esc = html.escape
    _notify_super_admins(
        db, "A competency proposal is waiting for you", "A competency proposal is waiting for you",
        ["%s has proposed a new competency for %s (%s):" % (esc(me["full_name"] or me["username"]), esc(p["title"]),
                                                           esc(display_bg(bg))),
         "Approve it for P&R, or reject it with a reason. They get one email either way."],
        box=_em_box(["<b>%s</b>" % esc(title), esc(levels[0]["description"]),
                     "Their reason: &ldquo;%s&rdquo;" % esc(reason)]),
        button=("Open Requests", app_base_url() + url_for("admin_competency_requests")))
    flash("Sent to the super admin. You'll see the answer under My proposals, and by email.", "ok")
    return redirect(url_for("admin_competency_requests"))


@app.route("/admin/competency/library/requests", methods=["GET", "POST"])
@admin_required
def admin_competency_requests():
    """Requests, the Competency tab (the Requests board): the super admin approves a new competency for P&R (added as a
    Chin Hin competency, CHG-, inactive until P&R sign it off in its panel) or rejects it with a reason; a BG or unit
    admin sees their own proposals and the answers. One email to the proposer either way. Double-confirmed, logged."""
    db = get_db()
    me = current_user()
    sup = is_super(me)
    if request.method == "POST":
        if not sup:
            abort(403)
        req = db.execute("SELECT * FROM tc_library_requests WHERE id=? AND status='waiting'",
                         (_form_int("request_id"),)).fetchone()
        if not req:
            flash("That proposal has been decided already.", "error")
            return redirect(url_for("admin_competency_requests"))
        pl = json.loads(req["payload_json"])
        note = (request.form.get("note") or "").strip()[:500] or None
        act = request.form.get("action")
        result = None
        if act == "reject":
            if not note:
                flash("Say why it's rejected: the proposer reads it.", "error")
                return redirect(url_for("admin_competency_requests"))
            status, word = "rejected", "rejected"
        elif act == "approve":
            sub = (pl.get("sub") or "").split("-")[-1]
            code, why = _tc_add_competency(db, me, pl["title"], pl["category"], sub, pl["levels"], log=False)
            if why:
                flash(why, "error")
                return redirect(url_for("admin_competency_requests"))
            status, word, result = "approved", "approved for P&R", pl["title"]
        else:
            abort(400)
        db.execute("UPDATE tc_library_requests SET status=?, decided_by=?, decided_at=datetime('now'), decision_note=?, "
                   "result_title=?, result_key=? WHERE id=?", (status, me["id"], note, result,
                                                              tc_comp_key(code) if result else None, req["id"]))
        log_activity(db, me["id"], "tc_request", "request %d %s: %s%s" % (req["id"], status, pl["title"],
                                                                          ("; " + note) if note else ""))
        db.commit()
        mail = _comp_request_email(db, req, word, note or "")
        flash("%s %s.%s %s" % (pl["title"], word, " It is in the catalogue, inactive until P&R sign it off."
                               if result else "", mail), "ok")
        return redirect(url_for("admin_competency_requests"))
    tab = request.args.get("tab") if request.args.get("tab") in ("waiting", "decided") else "waiting"
    where, args = "", []
    if not sup:
        where, args = " WHERE r.created_by=?", [me["id"]]
    rows = [dict(r) for r in db.execute(
        "SELECT r.*, u.full_name AS who, d.full_name AS decider FROM tc_library_requests r LEFT JOIN users u ON "
        "u.id=r.created_by LEFT JOIN users d ON d.id=r.decided_by" + where + " ORDER BY r.id DESC", args)]
    for r in rows:
        r["pl"] = json.loads(r["payload_json"])
    n_wait = sum(1 for r in rows if r["status"] == "waiting")
    shown = [r for r in rows if (r["status"] == "waiting") == (tab == "waiting")]
    n_kpi = db.execute("SELECT COUNT(*) FROM pm_library_requests WHERE status='waiting'%s" % (
        "" if sup else " AND created_by=?"), () if sup else (me["id"],)).fetchone()[0]
    return render_template("admin_library_requests.html", lib="comp", rows=shown, tab=tab, n_wait=n_wait,
                           n_done=len(rows) - n_wait, sup=sup, n_other=n_kpi)


@app.route("/admin/competency/library/catalogue")
@admin_required
def admin_competency_catalogue():
    """Competency > Library > Catalogue (board 9): every competency by category, with how many jobs use it, where two
    names may be one (Similar names) and where a competency serves a single job. A name opens its panel on the
    library page."""
    db = get_db()
    me = current_user()
    ix = _tc_lib_index(db)
    skills, profs = ix["skills"], ix["profiles"]
    scope = _tc_lib_scope(me)
    show = request.args.get("show") if request.args.get("show") in ("one", "similar", "waiting") else "all"
    sim = _tc_similar(skills)
    for it in skills.values():
        jobs = it["now"] | it["next"]
        it["jobs"] = len(jobs)
        it["mine"] = scope is None or any(set(profs[i]["bgs"]) & set(scope) for i in jobs)
        it["similar"] = sorted(set(sim.get(it["key"], [])))
    items = [it for it in skills.values() if it["mine"]]
    if show == "one":
        items = [it for it in items if it["jobs"] == 1]
    elif show == "similar":
        items = [it for it in items if it["similar"]]
    elif show == "waiting":   # every level still off: a new competency waiting for P&R's sign-off
        items = [it for it in items if not it["active"]]
    # the search (2026-10-27, canvas "Competency catalogue search"): a name or a skill code, with the pills; every
    # category with a match opens with all its matches (no folds), the count bar says how many
    q = " ".join((request.args.get("q") or "").split())[:80]
    ql = q.lower()
    if ql:
        items = [it for it in items if ql in (it["title"] or "").lower()
                 or any(ql in (r["skill_code"] or "").lower() for r in it["rows"])]
        for it in items:   # a match on the code alone shows which code
            it["hit"] = "" if ql in (it["title"] or "").lower() else next(
                (r["skill_code"] for r in it["rows"] if ql in (r["skill_code"] or "").lower()), "")
    cats = {}
    for it in items:
        c = cats.setdefault(it["category"], {"name": it["category"], "comps": [], "jobs": set(), "one": 0})
        c["comps"].append(it)
        c["jobs"] |= it["now"] | it["next"]
        c["one"] += it["jobs"] == 1
    cats = sorted(cats.values(), key=lambda c: (-len(c["comps"]), c["name"]))
    for c in cats:
        c["comps"].sort(key=lambda it: (-it["jobs"], it["title"]))
    mine = [it for it in skills.values() if it["mine"]]
    counts = {"comps": len(mine), "rows": sum(len(it["rows"]) for it in mine), "jobs": len(profs),
              "one": sum(1 for it in mine if it["jobs"] == 1), "similar": sum(1 for it in mine if it["similar"]),
              "inactive": sum(1 for it in mine if not it["active"])}
    sup = is_super(me)
    addcomp = None
    if sup:   # Add a competency: the panel's lists (the category list is the page's own)
        addcomp = {"groups": _tc_chg_groups(db, ix), "cats": sorted({it["category"] for it in skills.values()}),
                   "open": request.args.get("panel") == "addcomp"}
    return render_template("admin_competency_catalogue.html", cats=cats, show=show, counts=counts, q=q,
                           n_match=len(items), sup=sup, addcomp=addcomp,
                           open_cat=request.args.get("cat") or (cats[0]["name"] if cats else ""))


TC_ARCH_PROFILE_MSG = ("This profile comes from the job architecture: change its five in the Competency library (Edit "
                      "the five), where one edit applies in every business group that holds the job.")


@app.route("/admin/competency/profiles", methods=["GET", "POST"])
@admin_required
def admin_competency_profiles():
    """Settings -> TM -> Competency profiles: what each role is assessed on.

    Two jobs on one screen, in the order the work actually happens: define a
    job profile and the competencies it requires, then push those out to the
    people holding that role for the active cycle.

    Profiles are org-wide (their key is department + title + grade, with no
    business_group column), so editing one is a super-admin action -- a BG
    admin would otherwise be changing what another BG assesses. Generating is
    bg_scope()d, so a BG admin can still run it for their own people."""
    db = get_db()
    me = current_user()
    sup = is_super(me)
    cyc = active_cycle(db)

    if request.method == "POST":
        action = request.form.get("action") or ""
        if action in ("add_profile", "set_skills", "toggle_active", "remove_profile") and not sup:
            abort(403)
        if action == "add_profile":
            # all three picked from the roster (2026-10-19): a profile matches people by this exact text, so a
            # spelling the roster doesn't hold would match nobody
            _pl = tc_profile_lists(db)
            _hit = lambda v, opts: next((o for o in opts if o.lower() == (v or "").strip().lower()), None)  # noqa: E731
            dept = _hit(request.form.get("department"), [d for d, _n in _pl["depts"]])
            title = _hit(request.form.get("job_title"), [t for t, _n in _pl["titles"].get(dept or "", [])])
            grade = _hit(request.form.get("job_grade"), _pl["grades"])
            if (request.form.get("department") or "").strip() and not (dept and title and grade):
                flash("Pick the department, job title and job grade from the lists: a profile matches people by how "
                      "the roster reads, so anything else would match nobody.", "error")
                return redirect(url_for("admin_competency_profiles"))
            dept, title, grade = dept or "", title or "", grade or ""
            try:
                lvl = int(request.form.get("proficiency_level") or 3)
            except ValueError:
                lvl = 0
            if not (dept and title and grade) or not 1 <= lvl <= 6:
                flash("A profile needs a department, job title, job grade and a "
                      "proficiency level between 1 and 6.", "error")
                return redirect(url_for("admin_competency_profiles"))
            try:
                db.execute(
                    "INSERT INTO tc_job_profiles(department, job_title, job_grade, "
                    "proficiency_level, source, active) VALUES (?,?,?,?,'manual',1)",
                    (dept, title, grade, lvl))
            except sqlite3.IntegrityError:
                flash("That department / job title / job grade already has a profile.",
                      "error")
                return redirect(url_for("admin_competency_profiles"))
            db.commit()
            log_activity(db, me["id"], "tc_profile",
                         "added %s / %s / JG %s at level %d" % (dept, title, grade, lvl))
            flash("Profile added. Now pick the competencies it requires.", "success")
            pid = db.execute("SELECT id FROM tc_job_profiles WHERE department=? AND "
                             "job_title=? AND job_grade=?", (dept, title, grade)).fetchone()
            return redirect(url_for("admin_competency_profiles",
                                    profile=pid["id"] if pid else None))

        if action == "set_skills":
            prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=?",
                              (request.form.get("profile_id") or "",)).fetchone()
            if not prof:
                abort(400)
            if prof["job_code"]:
                flash(TC_ARCH_PROFILE_MSG, "error")
                return redirect(url_for("admin_competency_profiles", profile=prof["id"]))
            picked = list(dict.fromkeys(request.form.getlist("skill")))
            n_cur, n_fut = tc_pick_plan_size(db, picked)
            if n_cur + n_fut > TC_PROFILE_MAX:
                flash("A role has at most %d competencies, each pick its level now plus the level above. These picks "
                      "make %d (%d current, %d future): untick %d and save again." % (
                          TC_PROFILE_MAX, n_cur + n_fut, n_cur, n_fut, n_cur + n_fut - TC_PROFILE_MAX), "error")
                return redirect(url_for("admin_competency_profiles", profile=prof["id"]))
            # Replace wholesale rather than diffing: the form always posts the
            # complete intended set, so an unchecked box IS a removal.
            db.execute("DELETE FROM tc_job_profile_skills WHERE profile_id=?", (prof["id"],))
            for i, sid in enumerate(picked):
                if db.execute("SELECT 1 FROM tc_skills WHERE id=? AND active=1",
                              (sid,)).fetchone():
                    db.execute(
                        "INSERT OR IGNORE INTO tc_job_profile_skills"
                        "(profile_id, skill_id, sort_order) VALUES (?,?,?)",
                        (prof["id"], sid, i))
            db.commit()
            log_activity(db, me["id"], "tc_profile",
                         "%s: %d competencies (%d current, %d future)" % (prof["job_title"], n_cur + n_fut, n_cur,
                                                                         n_fut))
            flash("Saved %d of %d competencies for %s: %d current, %d future."
                  % (n_cur + n_fut, TC_PROFILE_MAX, prof["job_title"], n_cur, n_fut), "success")
            return redirect(url_for("admin_competency_profiles", profile=prof["id"]))

        if action in ("toggle_active", "remove_profile"):
            prof = db.execute("SELECT * FROM tc_job_profiles WHERE id=?",
                              (request.form.get("profile_id") or "",)).fetchone()
            if not prof:
                abort(400)
            if action == "toggle_active":
                db.execute("UPDATE tc_job_profiles SET active=?, updated_at=datetime('now') "
                           "WHERE id=?", (0 if prof["active"] else 1, prof["id"]))
                msg = "deactivated" if prof["active"] else "reactivated"
            elif prof["job_code"]:   # a delete cascades its skills and routes away, and strands career targets
                flash(TC_ARCH_PROFILE_MSG + " To take it out of use, deactivate it.", "error")
                return redirect(url_for("admin_competency_profiles", profile=prof["id"]))
            else:
                db.execute("DELETE FROM tc_job_profiles WHERE id=?", (prof["id"],))
                msg = "removed"
            db.commit()
            log_activity(db, me["id"], "tc_profile",
                         "%s %s / %s" % (msg, prof["department"], prof["job_title"]))
            flash("Profile %s." % msg, "success")
            return redirect(url_for("admin_competency_profiles"))

        if action == "generate":
            if not cyc:
                abort(400)
            rep = tc_generate_assignments(db, me, cyc["id"], commit=True)
            log_activity(db, me["id"], "tc_assign",
                         "%s: %d people, %d competencies"
                         % (cyc["name"], len(rep["assign"]), rep["rows"]))
            flash("Assigned %d competenc%s across %d people. %d skipped (assessment "
                  "already started), %d had no profile, %d not taking part this cycle."
                  % (rep["rows"], "y" if rep["rows"] == 1 else "ies",
                     len(rep["assign"]), len(rep["started"]), len(rep["unmapped"]), len(rep["not_part"])),
                  "success")
            return redirect(url_for("admin_competency_profiles"))
        abort(400)

    # ---- GET ---------------------------------------------------------------
    profiles = [dict(r) for r in db.execute(
        "SELECT p.*, "
        "  (SELECT COUNT(*) FROM tc_job_profile_skills ps WHERE ps.profile_id = p.id) n_skills "
        "FROM tc_job_profiles p ORDER BY p.active DESC, p.department, p.job_title, p.job_grade")]
    sel = None
    pid = (request.args.get("profile") or "").strip()
    if pid:
        sel = next((p for p in profiles if str(p["id"]) == pid), None)
    skills, picked, pairs = [], set(), []
    if sel and sel.get("job_code"):
        # an architecture profile's five are changed in the library (set_skills refuses it): the panel reads them
        pairs = tc_profile_pairs(db, sel["id"])
    elif sel:
        # Grouped by title so the two proficiency levels of one competency sit
        # together -- HR picks "Cost Analysis at level 3", not a bare skill code.
        skills = [dict(r) for r in db.execute(
            "SELECT id, skill_code, title, level, skill_category FROM tc_skills "
            "WHERE active=1 ORDER BY COALESCE(NULLIF(skill_category,''),'~'), title, level")]
        picked = {r["skill_id"] for r in db.execute(
            "SELECT skill_id FROM tc_job_profile_skills WHERE profile_id=?", (sel["id"],))}
    # the count as people would be assessed on these picks, in the list's own order (the panel's script keeps it live)
    pick_n = tc_pick_plan_size(db, [s_["id"] for s_ in skills if s_["id"] in picked]) if skills else (0, 0)

    preview = tc_generate_assignments(db, me, cyc["id"], commit=False) if cyc else None
    # The top unmapped roles are the actual to-do list: each one is a profile
    # somebody has to write, ordered by how many people it would cover.
    gaps = {}
    for u in (preview["unmapped"] if preview else []):
        k = (u["job_title"] or "(no title)", str(u["job_grade"] or "?"))
        gaps[k] = gaps.get(k, 0) + 1
    top_gaps = sorted(({"job_title": k[0], "job_grade": k[1], "n": n}
                       for k, n in gaps.items()), key=lambda g: -g["n"])[:12]
    return _settings_shell("tm", tm_section="profiles", profiles=profiles, sel=sel,
                           skills=skills, picked=picked, pick_n=pick_n, pairs=pairs, prof_max=TC_PROFILE_MAX, preview=preview,
                           top_gaps=top_gaps, is_sup=sup, cyc=cyc, prof_lists=tc_profile_lists(db) if sup else None)


def tc_route_groups(db, profile_id, g, people=None, ctx=None):
    """The moves offered from one profile at grade g, as the career tree's Routes panel and a person's Career Plan tab
    (Career routes, 2026-10-19) both show them: [(group, rows)] nearest group first (TC_ROUTE_ORDER; a pin is HR's
    suggestion), each row its title, grade, how far up, the skills that match, and its people where `people` maps a
    profile id to a head count; and the roles HR hid. Reads only. `ctx` (tc_routes_ctx): the architecture read once, for the
    career routes download, which walks every job."""
    row = dict(db.execute("SELECT * FROM tc_job_profiles WHERE id=?", (profile_id,)).fetchone())
    groups = {}
    for r in tc_career_routes_for(db, row, limit=40, ctx=ctx):
        rp = dict(r["profile"])   # a Row from the architecture's routes, a dict from the overlap scan
        pg = _ja_parts(rp.get("job_code") or "") or {}
        up = (pg.get("grade") or grade_num(rp.get("job_grade")) or g) - g
        total = r["shared"] + r["new"]
        key = "suggested by Group People" if r["pinned"] else (r.get("route") or "related roles")
        groups.setdefault(key, []).append({
            "id": rp["id"], "title": rp["job_title"], "grade": pg.get("grade") or grade_num(rp.get("job_grade")),
            "pinned": r["pinned"], "next": r.get("next_step"), "target": r.get("target"),
            "people": (people or {}).get(rp["id"], 0),
            "jump": "same grade" if up <= 0 else "one grade up" if up == 1 else "%d grades up" % up,
            "match": ("%d of %d skills match" % (r["shared"], total)) if total else ""})
    hidden = [dict(r) for r in db.execute(
        "SELECT p.id, p.job_title, p.job_code FROM tc_career_routes c JOIN tc_job_profiles p ON p.id=c.to_profile_id "
        "WHERE c.from_profile_id=? AND c.kind='hidden' ORDER BY p.job_title", (profile_id,))]
    return [(k, groups[k]) for k in sorted(groups, key=lambda k: TC_ROUTE_ORDER.get(k, 9))], hidden


@app.route("/admin/career-routes", methods=["GET", "POST"])
@admin_required
def admin_career_routes():
    """Career Plan > Settings > Career routes as a tree (Chris, 2026-10-19: "design it similar like the library to have
    the career tree to show from top level and admin can select and see the role within"; canvas
    [design canvas link removed]). The tree is job family > sub-family > job; a job opens with its
    whole ladder, JG 23 down to its first grade (target roles and grades nobody holds marked, the leadership track
    above it); a grade opens in the side panel with the moves its people are offered, to pin or hide.

    The map itself is never stored: the page records only HR's two judgements the derivation can't make, "always offer
    this move" and "never offer this one" (tc_career_routes). Reading is open to admins; every change is the super
    admin's: routes are org-wide, so a BG admin's edit would curate every other group's map."""
    db = get_db()
    me = current_user()
    if request.method == "POST" and not is_super(me):
        abort(403)
    if request.method == "POST":
        if request.form.get("action") == "fill":
            res = tc_fill_ladders(db, me["id"])
            flash(("%d grade%s in %d job%s became target roles, every job's ladder now reaching JG %d. Each is a draft "
                   "for P&R in the competency library." % (res["created"], "" if res["created"] == 1 else "s",
                                                            res["jobs"], "" if res["jobs"] == 1 else "s", TC_LADDER_TOP))
                  if res["created"] else "No grade was missing.", "ok")
            return redirect(url_for("admin_career_routes"))
        frm = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1",
                         ((request.form.get("from_profile_id") or "").strip(),)).fetchone()
        if not frm:
            abort(400)
        to_id = (request.form.get("to_profile_id") or "").strip()
        kind = request.form.get("kind") or ""
        to = db.execute("SELECT * FROM tc_job_profiles WHERE id=? AND active=1", (to_id,)).fetchone()
        if not to or to["id"] == frm["id"]:
            abort(400)
        if kind == "clear":
            db.execute("DELETE FROM tc_career_routes WHERE from_profile_id=? AND to_profile_id=?", (frm["id"], to["id"]))
        elif kind in ("pinned", "hidden"):
            db.execute(
                "INSERT INTO tc_career_routes(from_profile_id,to_profile_id,kind,created_by) "
                "VALUES (?,?,?,?) ON CONFLICT(from_profile_id,to_profile_id) "
                "DO UPDATE SET kind=excluded.kind, created_by=excluded.created_by",
                (frm["id"], to["id"], kind, me["id"]))
        else:
            abort(400)
        db.commit()
        log_activity(db, me["id"], "career_route", "%s -> %s: %s" % (frm["job_title"], to["job_title"], kind))
        fp = _ja_parts(frm["job_code"] or "")
        return redirect(url_for("admin_career_routes", job=fp["base"] if fp else None, g=fp["grade"] if fp else None,
                                pid=frm["id"], panel="routes"))

    tree = tc_career_tree(db)
    jobs = tree["jobs"]
    # an older link (?profile=<id>) lands on its job and grade, the panel open
    old = (request.args.get("profile") or "").strip()
    if old.isdigit():
        r = db.execute("SELECT job_code FROM tc_job_profiles WHERE id=?", (int(old),)).fetchone()
        pp = _ja_parts(r["job_code"]) if r and r["job_code"] else None
        if pp:
            return redirect(url_for("admin_career_routes", job=pp["base"], g=pp["grade"], pid=int(old), panel="routes"))
    q = " ".join((request.args.get("q") or "").split())
    show = request.args.get("show") if request.args.get("show") in ("targets", "missing") else ""

    def keep(j):
        if show == "targets" and not j["targets"]:
            return False
        if show == "missing" and not j["missing"]:
            return False
        if q:
            hay = " ".join([j["name"], j["base"]] + [p_["title"] for ps in j["rungs"].values() for p_ in ps]).lower()
            return q.lower() in hay
        return True
    families = []
    for f in tree["families"]:
        subs = [dict(sb, jobs=[j for j in sb["jobs"] if keep(j)]) for sb in f["subs"]]
        subs = [sb for sb in subs if sb["jobs"]]
        if subs:
            families.append(dict(f, subs=subs, n=sum(len(sb["jobs"]) for sb in subs)))
    job = jobs.get(request.args.get("job") or "")
    ladder = []
    if job:
        capped = job["top"] < TC_LADDER_TOP
        for g in range(max(job["hi"], 23), job["lo"] - 1, -1):   # JG 23 down to its first grade, the canvas's ladder
            if capped and g == job["top"]:
                # where its own ladder stops (tc_ladder_tops): no target role above it; a role somebody holds stays
                ladder.append({"g": g, "kind": "stop", "first": False, "top": job["top"],
                               "kind_label": TC_LADDER_KINDS.get(job["top_kind"], "")})
            if capped and g > TC_LADDER_TOP and max(job["hi"], job["top"]) < TC_LADDER_TOP - 1:
                continue   # the leadership track starts at JG 19: a ladder that stops below it never reaches it
            if g in job["rungs"]:
                for i, p_ in enumerate(job["rungs"][g]):
                    ladder.append(dict(p_, g=g, kind="held", first=i == 0, level=TC_LADDER_LEVELS.get(g, "")))
            elif g in job["missing"]:
                ladder.append({"g": g, "kind": "missing", "first": True, "level": TC_LADDER_LEVELS.get(g, "")})
            elif g > TC_LADDER_TOP:
                ladder.append({"g": g, "kind": "lead", "first": True, "level": TC_LADDER_LEVELS.get(g, ""),
                               "titles": (tree["lead"].get(g) or [])[:3]})
    # a grade picked: its profile (pid, else the first at that grade) and the moves it is offered
    pick = None
    if job and request.args.get("panel") == "routes":
        try:
            g = int(request.args.get("g") or 0)
        except ValueError:
            g = 0
        at = job["rungs"].get(g) or []
        pid = request.args.get("pid", "")
        prof = next((p_ for p_ in at if str(p_["id"]) == pid), at[0] if at else None)
        if prof:
            people = {p_["id"]: p_["people"] for j in jobs.values() for ps in j["rungs"].values() for p_ in ps}
            groups, hidden = tc_route_groups(db, prof["id"], g, people)
            shown = {x["id"] for _k, v in groups for x in v} | {h["id"] for h in hidden} | {prof["id"]}
            others = [{"id": p_["id"], "title": p_["title"], "g": gg, "sub": j["sub"]}
                      for j in sorted(jobs.values(), key=lambda j: j["name"].lower())
                      for gg, ps in sorted(j["rungs"].items()) for p_ in ps if p_["id"] not in shown]
            pick = {"prof": prof, "g": g, "at": at, "groups": groups, "hidden": hidden,
                    "others": others, "n": sum(len(v) for _k, v in groups)}
    return render_template("admin_career_tree.html", families=families, check=tree["check"], job=job, ladder=ladder,
                           pick=pick, q=q, show=show, sup=is_super(me), levels=TC_LADDER_LEVELS, top=TC_LADDER_TOP,
                           n_targets=sum(1 for j in jobs.values() if j["targets"]),
                           n_missing=sum(1 for j in jobs.values() if j["missing"]),
                           names={sb["code"]: sb["name"] for f in tree["families"] for sb in f["subs"]})


@app.route("/idp/career/anchor", methods=["POST"])
@login_required
def idp_career_anchor():
    """Set the map's start (when the roster can't resolve a profile) or its
    destination. Both are the employee's own choice about their own career, so
    no approval chain -- unlike an IDP goal, wanting to look at a role commits
    nobody to anything."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    pm_career_profile_for(db, u["id"], create=True)
    field = request.form.get("field", "")
    if field not in ("self_profile_id", "target_profile_id"):
        abort(400)
    if _career_locked(db, u):   # locked with the shared plan (2026-09-28)
        flash("Your career plan is shared with your manager and locked.", "error")
        return redirect(url_for("idp_career_view"))
    raw = (request.form.get("profile_id", "") or "").strip()
    pid = None
    if raw:
        row = db.execute("SELECT id FROM tc_job_profiles WHERE id=? AND active=1",
                         (raw,)).fetchone()
        if not row:
            flash("That role is no longer in the job architecture.", "error")
            return redirect(url_for("idp_career_view"))
        pid = row["id"]
    db.execute("UPDATE pm_career_profile SET %s=?, updated_at=datetime('now') "
               "WHERE subject_id=?" % field, (pid, u["id"]))
    db.commit()
    flash("Career map updated." if pid else "Cleared.", "success")
    # Come back to the card that was just acted on, not the top of the page.
    # Picking a target is one decision inside a list people are still reading;
    # throwing them back to the page head means re-finding their place every
    # time, and the map sits well below the fold.
    anchor = ("#role-%d" % pid) if (pid and field == "target_profile_id") else "#career-map"
    return redirect(url_for("idp_career_view") + anchor)


