@app.route("/idp/team")
@login_required
def idp_team_view():
    """A manager's development view of their people: who has a plan, who is
    waiting on them, and how the agreed goals are actually moving.

    Deliberately its own page rather than a section of the Performance
    drill-down: reviewing someone's development is not the same job as
    moderating their rating, and burying it under a scorecard is how it
    quietly stops happening. Population is the same approver-chain set the
    Performance team page uses, so a manager's list of people never differs
    between the two modules."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    rows = []
    if period:
        subject_ids = _idp_review_subject_ids(db, u, period["id"])
        if subject_ids:
            ph = ",".join("?" * len(subject_ids))
            subjects = {r["id"]: r for r in db.execute(
                f"SELECT * FROM users WHERE id IN ({ph})", subject_ids).fetchall()}
            for sid in subject_ids:
                idp = pm_idp_for(db, pm_idp_plan_year(period), sid)
                goals = (idp or {}).get("goals", [])
                # A draft is the employee's own private working copy -- the
                # manager sees that a plan exists only once it's submitted,
                # exactly as the old drill-down did.
                visible = idp and idp["status"] != "draft"
                done = sum(1 for g in goals
                           if g.get("progress_status") in ("done", "dropped"))
                moving = sum(1 for g in goals
                             if g.get("progress_status") == "in_progress")
                rows.append({
                    "subject": subjects.get(sid),
                    "status": (idp["status"] if visible else "none"),
                    "goal_count": len(goals) if visible else 0,
                    "done": done if visible else 0, "moving": moving if visible else 0,
                    "conversation": pm_career_conversation_for(db, pm_idp_plan_year(period), sid),
                    "closed_at": (idp or {}).get("closed_at") if visible else None,
                })
            rows.sort(key=lambda r: (r["subject"]["full_name"] if r["subject"] else ""))
    todo = [r for r in rows if r["status"] in ("shared", "none")]
    agreed = [r for r in rows if r["status"] == "closed"]
    return render_template("idp_team.html", period=period, todo=todo,
                           agreed=agreed, active_view="team")


@app.route("/idp/team/<int:subject_id>")
@login_required
def idp_team_member_view(subject_id):
    """One person's development: their plan and its check-ins, their career
    profile, and the record of whether the conversation actually happened."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
