@app.route("/performance/setting/autosave", methods=["POST"])
@login_required
def performance_kpi_setting_autosave():
    """Add / remove / re-weight one draft KPI line. JSON, called from the
    setting page's own fetch() -- never a form navigation. Every write is
    scoped to the caller's own subject_id and refuses once the set is
    'proposed' (an approver is looking at it)."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return jsonify(ok=False, error="No active performance period."), 409
    if not ctx["editable"]:
        return jsonify(ok=False, error=_pm_setting_shut_reason(ctx)), 409
    period = ctx["period"]
    action = (request.form.get("action", "") or "").strip()

    def weight_of(raw, fallback=None):
        raw = (raw or "").strip().rstrip("%").replace(",", "")
        if raw == "":
            return fallback
        try:
            v = float(raw)
        except ValueError:
            return None
        return v if math.isfinite(v) and 0 < v <= 100 else None

    if action == "add":
        try:
            library_id = int((request.form.get("library_id", "") or "").strip())
        except ValueError:
            return jsonify(ok=False, error="Bad library id."), 400
        # Re-derive eligibility server-side through the SAME resolver the page
        # renders from -- "is this id in the set this person can actually see?"
        # is the one check that can't drift away from the offered list as the
        # scope rules grow. Never trust the posted id alone.
        lib = next((r for r in ctx["library"] if r["id"] == library_id), None)
        if not lib:
            abort(403)
        weightage = weight_of(request.form.get("weightage"), 0)   # blank until typed (NOT NULL column: 0 reads as not set)
        if weightage is None:
            return jsonify(ok=False, error="Weightage must be a number between 0 and 100."), 400
        # Every figure starts blank; last year's show as placeholders (pm_last_figures).
        nums, source = pm_default_numbers(db, u, period, lib, ctx["cfg"])
        try:
            cur = db.execute(
                "INSERT INTO pm_kpi_targets(cycle_id, subject_id, kpi_name, category, "
                "description, weightage, unit, method, rate1, rate2, rate3, rate4, rate5, "
                "threshold, target, multiple, excellence, business_group, company, "
                "department, created_by, status, library_id, number_source) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft',?,?)",
                (period["id"], u["id"], lib["kpi_name"], lib["category"], lib["description"],
                 weightage, kpi_unit_normalise(lib["unit"]), lib["method"], nums["rate1"], nums["rate2"],
                 nums["rate3"], nums["rate4"], nums["rate5"], nums["threshold"], nums["target"],
                 nums["multiple"], nums["excellence"], u["business_group"], u["company"],
                 u["department"], u["id"], lib["id"], source))
            db.commit()
        except sqlite3.IntegrityError:
            # UNIQUE(cycle_id, subject_id, kpi_name) -- already on the
            # scorecard, or an admin already imported a target of that name.
            # A user error, not a 500.
            return jsonify(ok=False,
                           error=f"'{lib['kpi_name']}' is already on your scorecard."), 409
        return jsonify(ok=True, id=cur.lastrowid, source=source)

    try:
        target_id = int((request.form.get("target_id", "") or "").strip())
    except ValueError:
        return jsonify(ok=False, error="Bad target id."), 400
    target = db.execute(
        "SELECT * FROM pm_kpi_targets WHERE id=? AND subject_id=? AND cycle_id=?",
        (target_id, u["id"], period["id"])).fetchone()
    if not target:
        abort(404)
    if target["status"] not in ("draft", "returned"):
        return jsonify(ok=False, error="That line is no longer editable."), 409

    if action == "remove":
        db.execute("DELETE FROM pm_kpi_targets WHERE id=?", (target_id,))
        db.commit()
        return jsonify(ok=True)

    if action == "numbers":
        # Direct edit of this line's own targets. Only the fields the BG's
        # mechanism actually uses are accepted, so a crafted POST can't stuff
        # Mechanism-B columns onto a Mechanism-A line (or vice versa) and
        # quietly change how it scores.
        cfg = ctx["cfg"]
        if not cfg:
            return jsonify(ok=False, error="Your Business Group has no scoring "
                                           "mechanism configured yet."), 409
        if cfg["mechanism"] == "A":
            fields = ["rate1", "rate2", "rate3", "rate4", "rate5", "target"]
        elif cfg["variant"] == "excellence":
            fields = ["threshold", "target", "excellence"]
        else:
            fields = ["threshold", "target", "multiple"]
        sets, params = [], []
        for f in fields:
            if f not in request.form:
                continue
            raw = (request.form.get(f, "") or "").strip().replace(",", "")
            if raw == "":
                sets.append(f"{f}=NULL")
                continue
            try:
                v = float(raw)
            except ValueError:
                return jsonify(ok=False, error=f"'{f}' must be a number."), 400
            if not math.isfinite(v):
                return jsonify(ok=False, error=f"'{f}' must be a real number."), 400
            sets.append(f"{f}=?")
            params.append(int(v) if f == "multiple" else v)
        if not sets:
            return jsonify(ok=False, error="Nothing to save."), 400
        params.extend([u["id"], target_id])
        db.execute(f"UPDATE pm_kpi_targets SET {', '.join(sets)}, "
                   f"updated_at=datetime('now'), updated_by=? WHERE id=?", params)
        db.commit()
        return jsonify(ok=True)

    if action == "weightage":
        weightage = weight_of(request.form.get("weightage"))
        if weightage is None:
            return jsonify(ok=False, error="Weightage must be a number between 0 and 100."), 400
        db.execute("UPDATE pm_kpi_targets SET weightage=?, updated_at=datetime('now'), "
                   "updated_by=? WHERE id=?", (weightage, u["id"], target_id))
        db.commit()
        return jsonify(ok=True)
    return jsonify(ok=False, error="Unknown action."), 400


@app.route("/performance/setting/propose", methods=["POST"])
@login_required
def performance_kpi_setting_propose():
    """Submit the whole scorecard for approval. All-or-nothing, like
    performance_kpi_submit_all(): the weightages must total exactly 100% and
    every line must carry its mechanism's numbers, or nothing changes."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        flash("No active performance period.", "error")
        return redirect(url_for("dashboard"))
    if not ctx["editable"]:
        flash(_pm_setting_shut_reason(ctx), "error")
        return redirect(url_for("performance_kpi_setting_view"))
    # ONE validation + write authority, shared with the chat's propose route
    # (_pm_setting_propose) so the page and the conversation can never disagree
    # about what a valid, submittable scorecard is.
    n = len(ctx["mine"])
    ok, errors, warn = _pm_setting_propose(db, u, ctx)
    if not ok:
        flash("Proposal rejected — no changes applied:", "error")
        for e in errors[:20]:
            flash(e, "error")
        return redirect(url_for("performance_kpi_setting_view"))
    if warn:
        # Same honest handling as the target import: the proposal stands, it
        # just has nobody to route to yet and surfaces on the Exceptions page.
        flash(f"Scorecard proposed ({n} KPI(s)), but no approver could be "
              f"resolved for you — Group People will assign one." if "Group People will assign" in warn else warn, "warn")
    else:
        flash(f"Scorecard proposed — {n} KPI(s) sent for approval.", "ok")
    return redirect(url_for("performance_kpi_setting_view"))


@app.route("/performance/setting/review")
@login_required
def performance_kpi_setting_review():
    """Approver: every proposed scorecard currently awaiting THIS person.
    Chain-driven like performance_team_view() -- a proposal only appears for
    the step whose turn it actually is."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    groups = []
    if period:
        rows = [dict(r) for r in db.execute(
            "SELECT t.*, s.full_name AS subject_name, s.employee_id AS subject_eid, "
            "s.department AS subject_dept, s.job_title AS subject_title "
            "FROM pm_kpi_targets t JOIN users s ON s.id = t.subject_id "
            "WHERE t.cycle_id=? AND t.status='proposed' "
            "AND EXISTS (SELECT 1 FROM pm_kpi_target_approvers a "
            "            WHERE a.kpi_target_id = t.id AND a.approver_id = ?) "
            "ORDER BY s.full_name, " + PM_LINE_ORDER_T, (period["id"], u["id"])).fetchall()]
        by_subject = defaultdict(list)
        for r in rows:
            nxt = pm_setting_next_approver(db, r["id"])
            # Chain membership is not "my turn" -- a later step must wait.
            if nxt and nxt["approver_id"] == u["id"]:
                # Last year's figures for this KPI, where the person had it: shown beside this year's. With no
                # earlier line nothing is marked (the library holds no numbers).
                r["earlier"] = pm_last_figures(db, r["subject_id"], r["kpi_name"], r.get("unit"), period)
                r["changed"] = sorted(pm_changed_vs_earlier(r, r["earlier"]))
                by_subject[r["subject_id"]].append(r)
        for sid, ts in by_subject.items():
            groups.append({
                "subject_id": sid, "subject": ts[0], "targets": ts,
                "total_weight": round(sum(t["weightage"] or 0 for t in ts), 2),
            })
        groups.sort(key=lambda g: g["subject"]["subject_name"] or "")
    return render_template("performance_setting_review.html",
                           period=period, groups=groups)


@app.route("/performance/setting/review/<int:subject_id>", methods=["POST"])
@login_required
def performance_kpi_setting_act(subject_id):
    """Approve or return one person's proposed scorecard, as a set (the
    weightages only mean anything together). Writes one
    pm_kpi_setting_approvals row per line, in one transaction; the set becomes
    'approved' -- and therefore open to result entry -- only when the LAST
    chain step approves."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    action = (request.form.get("action", "") or "").strip()
    if action not in ("approve", "return"):
        abort(400)
    comment = (request.form.get("comment", "") or "").strip() or None
    _t, _err = _store_text(comment or "", "manager")
    if _err:
        flash(_err, "error")
        return redirect(url_for("performance_kpi_setting_review"))
    targets = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? AND status='proposed'",
        (period["id"], subject_id)).fetchall()]
    actionable = []
    for t in targets:
        nxt = pm_setting_next_approver(db, t["id"])
        if nxt and nxt["approver_id"] == u["id"]:
            actionable.append((t, nxt))
    if not actionable:
        flash("Nothing awaiting your approval for that person.", "error")
        return redirect(url_for("performance_kpi_setting_review"))
    try:
        for t, nxt in actionable:
            db.execute(
                "INSERT INTO pm_kpi_setting_approvals(kpi_target_id, seq, action, comment, "
                "acted_by) VALUES (?,?,?,?,?)",
                (t["id"], nxt["seq"], action, comment, u["id"]))
            if action == "return":
                db.execute("UPDATE pm_kpi_targets SET status='returned', "
                           "updated_at=datetime('now'), updated_by=? WHERE id=?",
                           (u["id"], t["id"]))
            else:
                # Approved only once every step in the chain has signed off --
                # this insert is the step that may complete it.
                remaining = pm_setting_next_approver(db, t["id"])
                if remaining is None:
                    db.execute("UPDATE pm_kpi_targets SET status='approved', "
                               "updated_at=datetime('now'), updated_by=? WHERE id=?",
                               (u["id"], t["id"]))
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        flash("Someone already acted on that scorecard — refresh and try again.", "error")
        return redirect(url_for("performance_kpi_setting_review"))
    log_activity(db, u["id"], "pm_kpi_setting_" + action,
                 f"{period['name']}: {len(actionable)} KPI(s)", target_user_id=subject_id)
    flash(f"Scorecard {'approved' if action == 'approve' else 'returned'} "
          f"({len(actionable)} KPI(s)).", "ok")
    return redirect(url_for("performance_kpi_setting_review"))


@app.route("/performance/team")
@login_required
def performance_team_view():
    """A manager's (or any-depth approver's) overview of everyone with at
    least one KPI line where they appear in the approver chain this period --
    approver-chain-driven population (A4), a strict superset of manager_id
    scoping since default chains are seeded FROM manager_id at import time
    but a role like Fiamma-Sales' national manager can appear here too. One
    row per direct report with a status bucket; per-KPI detail + moderation
    lives on performance_team_member_view()."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    groups = []
    if period:
        # ...of those who take part in Performance this cycle (Chris, 2026-10-30: out means out)
        subject_ids = [r["subject_id"] for r in db.execute(
            "SELECT DISTINCT t.subject_id FROM pm_kpi_target_approvers a "
            "CROSS JOIN pm_kpi_targets t ON t.id = a.kpi_target_id "
            "CROSS JOIN users su ON su.id = t.subject_id "
            "WHERE t.cycle_id=? AND a.approver_id=? AND " + participant_sql("su", "pm"),
            (period["id"], u["id"])).fetchall()]
        if subject_ids:
            ph = ",".join("?" * len(subject_ids))
            all_targets = [dict(t) for t in db.execute(
                f"SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id IN ({ph}) "
                f"ORDER BY subject_id, {PM_LINE_ORDER}", [period["id"]] + subject_ids).fetchall()]
            attach_pm_chains(db, all_targets)
            pm_score_targets(db, all_targets)
            by_subject = defaultdict(list)
            for t in all_targets:
                by_subject[t["subject_id"]].append(t)
            # Parallel self-rated pass (one extra batch score, same cost as the
            # one above -- no per-subject query): each line re-scored off its
            # raw self-submitted value instead of effective_value, so the
            # Reviewed table can show self-rated -> moderated when a manager
            # actually changed a finalized subject's overall band. Same
            # shallow-copy-and-rescore idiom as _pm_member_previews(); dict(t)
            # is shallow and pm_score_targets reassigns st['score'] (never
            # mutates the shared result), so all_targets/overall are untouched.
            self_all = [dict(t) for t in all_targets]
            for st in self_all:
                st["effective_value"] = st["result"]["actual_value"] if st.get("result") else None
            pm_score_targets(db, self_all)
            self_by_subject = defaultdict(list)
            for t in self_all:
                self_by_subject[t["subject_id"]].append(t)
            subjects = {r["id"]: r for r in db.execute(
                f"SELECT * FROM users WHERE id IN ({ph})", subject_ids).fetchall()}
            for sid in subject_ids:
                ts_all = by_subject.get(sid, [])
                # The overall itself is still computed from every line (it's
                # gated on all-locked regardless of who's looking).
                mine = _pm_team_mine(u, ts_all)
                overall = pm_overall_for_targets(db, ts_all)
                # Self-rated overall, gated identically (require_locked=True),
                # so it's non-None only for finalized subjects -- the only
                # place the Reviewed table uses it.
                self_overall = pm_overall_for_targets(db, self_by_subject.get(sid, []))
                my_submitted = [t for t in mine if t["result"]]
                # The t["result"] guard must come first: attach_pm_chains()
                # resolves next_approver from chain/approvals counts alone,
                # independent of whether anything's been submitted yet -- a
                # not-yet-submitted line would otherwise wrongly count as
                # "awaiting your review".
                my_pending = [t for t in my_submitted if not t["locked"]
                              and t["next_approver"] and t["next_approver"]["approver_id"] == u["id"]]
                if overall:
                    status_kind = "final"
                elif my_pending:
                    status_kind = "action"
                elif not my_submitted:
                    status_kind = "none"
                else:
                    status_kind = "progress"
                groups.append({"subject": subjects[sid], "mine_count": len(mine),
                               "submitted_count": len(my_submitted),
                               "overall": overall, "self_overall": self_overall,
                               "status_kind": status_kind})
            groups.sort(key=lambda g: g["subject"]["full_name"])
    return render_template("performance_team.html", period=period, groups=groups,
                          label_names=PM_LABEL_NAMES)


@app.route("/performance/team/<int:subject_id>")
@login_required
def performance_team_member_view(subject_id):
    """One direct report's KPI lines, read-only, with a per-line Moderate
    column for the current manager to confirm/adjust -- each line commits
    independently via performance_kpi_moderate_autosave() the moment its
    value settles (debounced), or in a batch when the bottom Approve button
    is clicked. The drill-down behind performance_team_view()'s overview
    table. Mirrors performance_my_view()'s own table structure (mechanism-A/B
    split, ladder, threshold/target/multiplier) but never editable here
    except via the Moderate column's own 'New value' input."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    subject = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    if not subject:
        abort(404)
    if not _report_takes_part(db, subject_id, "pm"):   # out of Performance: no KPI page for them (2026-10-30)
        abort(403)
    ts_all_count = db.execute(
        "SELECT COUNT(*) FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=?",
        (period["id"], subject_id)).fetchone()[0]
    # This approver's in-progress moderation drafts for this subject -- feed
    # them as preview overrides (so the on-load Moderated Rating already
    # reflects the draft) and attach them to each line for the template to
    # pre-fill the Moderate input + justification. Only this approver's own
    # drafts are ever loaded (matrix-safe; no peer/employee leak).
    draft_rows = db.execute(
        "SELECT d.kpi_target_id, d.adjusted_value, d.justification "
        "FROM pm_kpi_moderation_drafts d JOIN pm_kpi_targets t ON t.id = d.kpi_target_id "
        "WHERE d.approver_id=? AND t.cycle_id=? AND t.subject_id=?",
        (u["id"], period["id"], subject_id)).fetchall()
    drafts = {r["kpi_target_id"]: {"adjusted_value": r["adjusted_value"],
                                   "justification": r["justification"]} for r in draft_rows}
    draft_overrides = {kid: d["adjusted_value"] for kid, d in drafts.items()
                       if d["adjusted_value"] is not None}
    # Single source of truth shared with performance_kpi_moderate_autosave() --
    # see _pm_member_previews()'s own docstring for why 'mine'-scoping and
    # require_locked=False both matter here.
    mine, mine_preview, self_preview, all_locked = _pm_member_previews(
        db, subject_id, period["id"], u["id"], overrides=draft_overrides)
    if not mine:
        abort(403)
    for t in mine:
        d = drafts.get(t["id"])
        t["draft_value"] = d["adjusted_value"] if d else None
        t["draft_justification"] = d["justification"] if d else None
    # Is this approver a middle step, i.e. does any line they can act on have
    # a chain step AFTER them? Drives the Approve modal's copy: telling a
    # step-1 approver their numbers are "final" is untrue whenever a later
    # step can still move them, and that claim sits on the last screen before
    # an irreversible action.
    # next_approver is a sqlite3.Row, not a dict -- no .get(), so guard on None
    # explicitly rather than defaulting through it.
    has_later_step = any(
        _pm_line_actionable_by(t, u["id"]) and t["next_approver"] is not None
        and len(t["approver_chain"]) > t["next_approver"]["seq"]
        for t in mine)
    # Every line this approver reviews must actually be scored before the
    # aggregate above them means anything. pm_overall_for_targets(
    # require_locked=False) excludes an unscored line rather than failing, so
    # a partially-submitted scorecard yields a confident-looking rating
    # computed from a subset -- its own docstring warns callers not to show
    # that. Two approvers on one person were each shown a different, and
    # wrong, band that way.
    mine_scored = sum(1 for t in mine if t.get("score"))
    mine_all_scored = bool(mine) and mine_scored == len(mine)
    remark_row = db.execute(
        "SELECT remark FROM pm_overall_remarks WHERE cycle_id=? AND subject_id=? "
        "AND draft=0 AND remark != ''", (period["id"], subject_id)).fetchone()
    # This approver's OWN remark only. It used to load whichever remark
    # existed for the subject, which in a matrix split pre-filled a peer's
    # private words into this approver's editable box.
    manager_remark_row = db.execute(
        "SELECT * FROM pm_manager_remarks "
        "WHERE cycle_id=? AND subject_id=? AND submitted_by=?",
        (period["id"], subject_id, u["id"])).fetchone()

    ai_enabled = ai_on("ai_pm")
    remark_ai_remaining = remark_ai_reset_seconds = None
    if ai_enabled:
        for t in mine:
            if _pm_line_actionable_by(t, u["id"]):
                _used, t["mgr_ai_remaining"], t["mgr_ai_reset_seconds"] = _pm_ai_draft_quota(
                    db, u["id"], f"mgr_justification:{t['id']}")
        if not all_locked:
            _used, remark_ai_remaining, remark_ai_reset_seconds = _pm_ai_draft_quota(
                db, u["id"], f"mgr_remark:{subject_id}:{period['id']}")

    return render_template("performance_team_member.html", period=period, subject=subject,
                          targets=mine, total_count=ts_all_count,
                          mine_preview=mine_preview, self_preview=self_preview, all_locked=all_locked,
                          has_later_step=has_later_step, mine_all_scored=mine_all_scored,
                          mine_scored=mine_scored, mine_total=len(mine),
                          overall_remark=remark_row["remark"] if remark_row else None,
                          manager_remark=dict(manager_remark_row) if manager_remark_row else None,
                          ai_enabled=ai_enabled, ai_limit=AI_DRAFT_DAILY_LIMIT,
                          remark_ai_remaining=remark_ai_remaining, remark_ai_reset_seconds=remark_ai_reset_seconds,
                          label_names=PM_LABEL_NAMES, me_id=u["id"])


# --- Shared manager-IDP write helpers: the ONE authority each of the four /idp/team
# write routes AND the manager agent's tools call, so the page and the chat can never
# comment / close a plan differently. Each returns (result, err); err is None or a
# {"reason","code",...} dict the route maps to its own response (JSON vs redirect).
# Every one gates on _idp_is_reviewer_of, the check the IDP pages open with: an approver of
# any of their KPI lines, or their line manager while they write a plan, KPI line or not.
def _idp_goal_write(db, u, period, subject_id, goal_id_raw, field, value):
    """One goal: a manager comment (no edited_by stamp) or a PM_IDP_FIELDS edit. Gate
    first, then parse the goal id, then scope it to this plan -- the route's order."""
    _w = window_closed(db, "idp_review", subject_id=subject_id)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = leader_ability_off(db, u, "lm.plan")
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    idp, gate_err = _idp_manager_gate(db, u, subject_id, period)
    if gate_err:
        return None, {"reason": "gate", "code": gate_err[1], "msg": gate_err[0]}
    try:
        goal_id = int(str(goal_id_raw if goal_id_raw is not None else "").strip())
    except (TypeError, ValueError):
        return None, {"reason": "bad_goal", "code": 400}
    goal = next((g for g in idp["goals"] if g["id"] == goal_id), None)
    if goal is None:
        return None, {"reason": "forbidden", "code": 403}
    if field == "manager_comment" or field in PM_IDP_FIELDS:
        _t, _serr = _store_text(value or "", "manager")   # a manager's words on someone's plan (4-03)
        if _serr:
            return None, {"reason": "screened", "code": 400, "msg": _serr}
    if field == "manager_comment":
        db.execute("UPDATE pm_idp_goals SET manager_comment=? WHERE id=?", (value, goal_id))
    elif field in PM_IDP_FIELDS:
        db.execute("UPDATE pm_idp_goals SET %s=?, edited_by=?, edited_at=datetime('now') "
                   "WHERE id=?" % field, (value, u["id"], goal_id))
    else:
        return None, {"reason": "bad_field", "code": 400}
    db.execute("UPDATE pm_idp SET updated_at=datetime('now') WHERE id=?", (idp["id"],))
    db.commit()
    return {"ok": True}, None


def _idp_plan_comment_write(db, u, period, subject_id, comment):
    """The plan-level manager comment (comment only; closing is the conversation)."""
    _w = window_closed(db, "idp_review", subject_id=subject_id)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = leader_ability_off(db, u, "lm.plan")
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    # the review population's own check, never the KPI chain alone: a line manager reviews the plan of a report with no
    # KPI line between them (Chris, 2026-10-19), and the chain-only gate refused them (the 2026-10-24 handoff, 12.2)
    if not _idp_is_reviewer_of(db, u, subject_id, period["id"]):
        return None, {"reason": "forbidden", "code": 403}
    idp = pm_idp_for(db, pm_idp_plan_year(period), subject_id)
    if not idp or idp["status"] == "draft":
        return None, {"reason": "not_shared", "code": 409}
    # The overall remark on an AGREED (closed) plan no longer changes, and it is about 100 words --
    # here, in the one helper, so the classic page and the chat agree (2026-09-24).
    if idp["status"] == "closed":
        return None, {"reason": "closed", "code": 409}
    if comment and len(comment.split()) > _REVIEW_REMARK_MAX_WORDS:
        return None, {"reason": "too_long", "code": 400}
    _t, _serr = _store_text(comment or "", "manager")
    if _serr:
        return None, {"reason": "screened", "code": 400, "msg": _serr}
    db.execute("UPDATE pm_idp SET manager_comment=?, updated_at=datetime('now') WHERE id=?",
               (comment, idp["id"]))
    db.commit()
    log_activity(db, u["id"], "idp_comment", "%s" % period["name"], target_user_id=subject_id)
    return {"ok": True}, None


def _idp_career_comment_write(db, u, period, subject_id, comment):
    """The career-profile manager comment (gated on the approver relationship only)."""
    _w = window_closed(db, "idp_review", subject_id=subject_id)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = leader_ability_off(db, u, "lm.plan")
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    if not _idp_is_reviewer_of(db, u, subject_id, period["id"]):
        return None, {"reason": "forbidden", "code": 403}
    _t, _serr = _store_text(comment or "", "manager")
    if _serr:
        return None, {"reason": "screened", "code": 400, "msg": _serr}
    pm_career_profile_for(db, subject_id, create=True)
    db.execute("UPDATE pm_career_profile SET manager_comment=?, manager_comment_by=?, "
               "manager_comment_at=datetime('now') WHERE subject_id=?",
               (comment, u["id"], subject_id))
    db.commit()
    return {"ok": True}, None


def _idp_approve_plan(db, u, period, subject_id):
    """APPROVE a shared plan, which closes it (terminal, via pm_idp_close). Chris, 2026-10-21: "remove the career
    conversation ... LM will just comment on the IDP of the person and approve it", the remark required first. The one
    writer for the card's Approve plan, the classic page and the agent's close_plan. Older career-conversation records
    stay readable (pm_career_conversations); none is written any more."""
    _w = window_closed(db, "idp_review", subject_id=subject_id)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = leader_ability_off(db, u, "lm.plan")
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    # the review population's own check, never the KPI chain alone: a line manager reviews the plan of a report with no
    # KPI line between them (Chris, 2026-10-19), and the chain-only gate refused them (the 2026-10-24 handoff, 12.2)
    if not _idp_is_reviewer_of(db, u, subject_id, period["id"]):
        return None, {"reason": "forbidden", "code": 403}
    plan_year = pm_idp_plan_year(period)
    idp = pm_idp_for(db, plan_year, subject_id) or {}
    if idp.get("status") != "shared":   # pm_idp_close would otherwise close a draft nobody shared
        return None, {"reason": "not_shared", "code": 409,
                      "msg": "Only a shared plan can be approved." if idp.get("status") != "closed"
                             else "This plan is already approved."}
    if not (idp.get("manager_comment") or "").strip():
        return None, {"reason": "needs_remark", "code": 409,
                      "msg": "Write the overall remark on the plan first: it can't be approved without it."}
    was = pm_idp_close(db, plan_year, subject_id, u["id"], "approved")
    db.commit()
    _feedback_lm_touch()
    return {"ok": True, "was": was, "plan_year": plan_year}, None


@app.route("/idp/team/<int:subject_id>/review", methods=["POST"])
@login_required
def idp_review(subject_id):
    """Manager: comment on a submitted development plan. Auth re-derives the reviewer
    relationship (`_idp_is_reviewer_of`) from the DB, not the URL. Comment only -- closing
    is the approve's job (idp_career_conversation, Approve plan)."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    comment = (request.form.get("comment", "") or "").strip()[:4000] or None
    result, err = _idp_plan_comment_write(db, u, period, subject_id, comment)
    if err:
        if err["reason"] == "forbidden":
            abort(403)
        flash({"closed": "That plan is agreed and closed -- its remark can't change.",
               "too_long": "Keep the remark to about 100 words.",
               "screened": STORE_TEXT_REFUSAL}.get(err["reason"],
                                                                      "That plan hasn't been shared yet."), "error")
        return redirect(url_for("idp_team_member_view", subject_id=subject_id))
    flash("Comment saved. Record the career conversation below to close the plan.", "ok")
    return redirect(url_for("idp_team_member_view", subject_id=subject_id))


def _idp_manager_gate(db, u, subject_id, period):
    """The plan a manager may act on for this report, or None with the reason.

    One gate for both manager write routes, so "may I touch this?" is answered
    the same way twice. The window is the one 'agreed' already implies: a DRAFT
    is private to its author and invisible here, and an AGREED plan is settled
    -- reopening it from this side would make agreement mean nothing. Auth
    re-derives the approver relationship the drill-down itself uses rather than
    trusting the URL."""
    _lo = leader_ability_off(db, u, "lm.plan")   # Roles & access › Leader roles (2026-10-20)
    if _lo:
        return None, (_lo, 409)
    if not _idp_is_reviewer_of(db, u, subject_id, period["id"]):
        return None, ("forbidden", 403)
    idp = pm_idp_for(db, pm_idp_plan_year(period), subject_id)
    if not idp or idp["status"] == "draft":
        return None, ("That plan hasn't been shared yet.", 409)
    if idp["status"] == "closed":
        return None, ("This plan is closed \u2014 reopen it with them if it needs to "
                      "change.", 409)
    return idp, None


@app.route("/idp/team/<int:subject_id>/goal-edit", methods=["POST"])
@login_required
def idp_goal_edit(subject_id):
    """Manager: change one field on a report's goal, or leave a comment beside
    it. Autosaved from the drill-down, same JSON-in/JSON-out contract the
    employee's own idp_autosave() uses.

    An edit to the goal's own wording stamps edited_by/edited_at so the
    employee is told their plan was changed and by whom -- the plan stays their
    document. A COMMENT deliberately leaves that stamp alone: saying something
    beside a goal is not rewriting it.
    """
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        return jsonify(ok=False, error="No active performance period."), 409
    field = (request.form.get("field", "") or "").strip()
    value = (request.form.get("value", "") or "").strip()[:1000] or None
    result, err = _idp_goal_write(db, u, period, subject_id,
                                  request.form.get("goal_id", ""), field, value)
    if err:
        if err["reason"] == "forbidden" or (err["reason"] == "gate" and err["code"] == 403):
            abort(403)
        if err["reason"] == "bad_goal":
            return jsonify(ok=False, error="Bad goal id."), 400
        if err["reason"] == "bad_field":
            return jsonify(ok=False, error="Unknown field."), 400
        return jsonify(ok=False, error=err["msg"]), err["code"]
    return jsonify(ok=True)


@app.route("/idp/team/<int:subject_id>/career-comment", methods=["POST"])
@login_required
def idp_career_comment(subject_id):
    """Manager: their view alongside a report's career profile. A comment, not
    an edit -- see the schema note on why the aspirations stay in the
    employee's own words.

    Gated on the approver relationship only, NOT on the plan's state: the
    profile carries across periods and has no submit/agree lifecycle of its
    own, so tying a comment on it to whether this half-year's plan happens to
    be agreed would silence the conversation exactly when it matters."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        return jsonify(ok=False, error="No active performance period."), 409
    comment = (request.form.get("comment", "") or "").strip()[:4000] or None
    result, err = _idp_career_comment_write(db, u, period, subject_id, comment)
    if err:
        if err["reason"] == "screened":   # shown on the page's save line (4-03)
            return jsonify(ok=False, reason="screened", error=err["msg"]), 400
        abort(403)
    return jsonify(ok=True)


@app.route("/idp/team/<int:subject_id>/career-conversation", methods=["POST"])
@login_required
def idp_career_conversation(subject_id):
    """Manager: APPROVE their shared plan, which closes it (Chris, 2026-10-21: the career conversation is gone; the
    endpoint keeps its name and address so every route list still classifies it). Same reviewer auth as the IDP
    review (_idp_is_reviewer_of), re-derived server-side. The overall remark comes first (_idp_approve_plan). JSON for
    the AI+ card (fetch), a flash and a redirect for the classic page."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    wants_json = request.headers.get("X-Requested-With") == "fetch"
    result, err = _idp_approve_plan(db, u, period, subject_id)
    if err:
        if err["reason"] == "forbidden":
            abort(403)
        if wants_json:
            return jsonify(ok=False, error=err.get("msg") or "That couldn't be approved."), err.get("code", 409)
        flash(err.get("msg") or "That couldn't be approved.", "error")
        return redirect(url_for("idp_team_member_view", subject_id=subject_id))
    if wants_json:
        return jsonify(ok=True, plan_year=result["plan_year"])
    flash("Plan approved: their %s plan is now closed." % result["plan_year"], "ok")
    return redirect(url_for("idp_team_member_view", subject_id=subject_id))


@app.route("/idp/conversation/acknowledge", methods=["POST"])
@login_required
def idp_conversation_acknowledge():
    """The employee confirms the conversation happened.

    Not an approval -- there is no reject, and it changes nothing about the
    plan. It exists because a conversation only one side records is a claim,
    not evidence, and this module's whole reason for recording it is that the
    conversation is the step that usually fails in practice. An optional note
    lets them add their own line to the record.

    Idempotent: acknowledging twice keeps the first timestamp, so the record
    says when they confirmed rather than when they last opened the page."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        return jsonify(ok=False, error="No active performance period."), 409
    plan_year = pm_idp_plan_year(period)
    conv = pm_career_conversation_for(db, plan_year, u["id"])
    if not conv:
        return jsonify(ok=False, error="There's no conversation recorded to confirm."), 409
    note = (request.form.get("note", "") or "").strip()[:2000] or None
    _t, _err = _store_text(note or "")
    if _err:
        return jsonify(ok=False, reason="screened", error=_err), 400
    db.execute("UPDATE pm_career_conversations SET "
               "acknowledged_at=COALESCE(acknowledged_at, datetime('now')), "
               "acknowledged_note=?, updated_at=datetime('now') WHERE id=?",
               (note, conv["id"]))
    db.commit()
    log_activity(db, u["id"], "career_conversation_ack", f"{plan_year}")
    return jsonify(ok=True)


def _pm_round_preview(preview):
    """{mechanism, value, label, label_name} rounded for JSON, or None --
    shared by performance_kpi_moderate_autosave()'s two aggregate fields so
    the rounding convention can't drift between them."""
    if not preview or preview["label"] is None:
        return None
    return {
        "mechanism": preview["mechanism"],
        "value": round(preview["value"], 2) if preview["mechanism"] == "A" else round(preview["value"], 1),
        "label": preview["label"], "label_name": PM_LABEL_NAMES[preview["label"]]}


def _pm_moderate_draft(db, u, kpi_target_id, raw, justification):
    """Reversible moderation DRAFT + the live moderated/self preview (no lock, no
    approvals row). THE ONE authority the draft route AND the manager agent's
    moderate tool share. `raw` is the adjusted-value string ('' = confirm as-is).
    Returns (result, err); err is None or {"reason","code","msg"}."""
    target = db.execute("SELECT * FROM pm_kpi_targets WHERE id=?", (kpi_target_id,)).fetchone()
    _w = window_closed(db, "pm_approve", subject_id=target["subject_id"] if target else 0)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = _pm_mod_off(db, u, target["subject_id"]) if target else leader_ability_off(db, u, None)
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    if not target:
        return None, {"reason": "not_found", "code": 404}
    if not _report_takes_part(db, target["subject_id"], "pm"):   # out means out (Chris, 2026-10-30)
        return None, {"reason": "not_actionable", "code": 409, "msg": _report_part_refusal("pm")}
    target = dict(target)
    attach_pm_chains(db, [target])
    if not _pm_line_actionable_by(target, u["id"]):
        return None, {"reason": "not_actionable", "code": 409,
                      "msg": "This line is no longer awaiting your action."}
    # Field-preserving: a None arg means "not provided -- keep what's on the draft"; ""
    # means clear (value -> confirm-as-is). This lets the moderated VALUE (typed in the
    # cell) and the JUSTIFICATION (drafted by the agent via chat) be written independently
    # without clobbering each other. The standalone page always co-sends both (never None),
    # so it is unaffected.
    existing = db.execute(
        "SELECT adjusted_value, justification FROM pm_kpi_moderation_drafts "
        "WHERE kpi_target_id=? AND approver_id=?", (kpi_target_id, u["id"])).fetchone()
    if raw is None:
        adjusted_value = existing["adjusted_value"] if existing else None
    else:
        raw = raw.strip()
        if raw:
            try:
                value = float(raw)
            except ValueError:
                value = None
            if value is None or not math.isfinite(value):
                return None, {"reason": "bad_number", "code": 400,
                              "msg": "Enter a valid number, or leave it blank to confirm as-is."}
            _rl = _rating_line_error(target, value)   # a 1-5 rating line is moderated to a whole rating only
            if _rl:
                return None, {"reason": "bad_rating", "code": 400, "msg": _rl}
            adjusted_value = value
        else:
            adjusted_value = None
    if justification is None:
        justification = existing["justification"] if existing else None
    else:
        justification = justification.strip() or None
    _t, _serr = _store_text(justification or "", "manager")   # a note about someone: 4-03
    if _serr:
        return None, {"reason": "screened", "code": 400, "msg": _serr}
    db.execute(
        "INSERT INTO pm_kpi_moderation_drafts(kpi_target_id, approver_id, adjusted_value, justification, updated_at) "
        "VALUES (?,?,?,?,datetime('now')) "
        "ON CONFLICT(kpi_target_id, approver_id) DO UPDATE SET "
        "adjusted_value=excluded.adjusted_value, justification=excluded.justification, updated_at=datetime('now')",
        (kpi_target_id, u["id"], adjusted_value, justification))
    db.commit()
    draft_overrides = {r["kpi_target_id"]: r["adjusted_value"] for r in db.execute(
        "SELECT d.kpi_target_id, d.adjusted_value FROM pm_kpi_moderation_drafts d "
        "JOIN pm_kpi_targets t ON t.id = d.kpi_target_id "
        "WHERE d.approver_id=? AND t.cycle_id=? AND t.subject_id=? AND d.adjusted_value IS NOT NULL",
        (u["id"], target["cycle_id"], target["subject_id"]))}
    _mine, mine_preview, self_preview, _all = _pm_member_previews(
        db, target["subject_id"], target["cycle_id"], u["id"], overrides=draft_overrides)
    # Per-line band jump (employee's own band vs the drafted/moderated band): 2+ is a big
    # move the agent should strongly recommend a justification for.
    self_value = target["result"]["actual_value"] if target.get("result") else None
    mod_value = adjusted_value if adjusted_value is not None else self_value
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?",
                     (target["business_group"],)).fetchone()

    def _score(v):
        return pm_score_kpi_line(cfg, target, v) if (v is not None and (cfg or _row_get(target, "rating_line"))) else None

    def _lbl_of(sc):
        return (pm_label_for_value(db, target["business_group"], sc["mechanism"], sc["value"], subject=target,
                                   cycle_id=target["cycle_id"])
                if sc else None)
    self_sc, mod_sc = _score(self_value), _score(mod_value)
    _sb, _mb = _lbl_of(self_sc), _lbl_of(mod_sc)
    band_jump = pm_band_distance(_sb, _mb)
    # An UP move (drafted band strictly higher than the employee's own): a justification is
    # required before the guided-review chat will let it lock (the page path is unchanged).
    up_move = bool(_sb in PM_BAND_ORDER and _mb in PM_BAND_ORDER
                   and PM_BAND_ORDER.index(_mb) > PM_BAND_ORDER.index(_sb))
    # ANY band change (up or down) needs the manager's remark before the journey will lock it.
    band_change = bool(_sb in PM_BAND_ORDER and _mb in PM_BAND_ORDER and _mb != _sb)
    # The per-line moderated rung/rating -- returned so the widget can move the highlight
    # (Mech A) / flip the rating pill (Mech B) LIVE as the manager types, from the server's
    # own score (the client never scores).
    mod_n = (int(round(mod_sc["value"])) if (mod_sc and mod_sc.get("mechanism") == "A"
                                             and mod_sc.get("value") is not None) else None)
    return {"ok": True, "kpi_name": target["kpi_name"], "band_jump": band_jump, "up_move": up_move,
            "band_change": band_change,
            "mod_rating": (mod_sc["value"] if mod_sc else None),
            "mod_band": _mb, "mod_n": mod_n,
            "mine_preview": _pm_round_preview(mine_preview),
            "self_preview": _pm_round_preview(self_preview)}, None


def _pm_manager_has_remark(db, u, cycle_id, subject_id):
    """Has THIS approver written their overall remark on this person's period (pm_manager_remarks)?"""
    return bool(db.execute(
        "SELECT 1 FROM pm_manager_remarks WHERE cycle_id=? AND subject_id=? AND submitted_by=? "
        "AND TRIM(COALESCE(remark,''))<>''", (cycle_id, subject_id, u["id"])).fetchone())


def _pm_overall_move(db, u, subject_id, cycle_id, line=None):
    """(their overall band, the moderated overall band) over THIS approver's lines, with the moderation as
    drafted (their drafts) and `line` = (kpi_target_id, value | None) applied on top -- None means that
    line locks at their own figure. Read-only."""
    ov = {r["kpi_target_id"]: r["adjusted_value"] for r in db.execute(
        "SELECT d.kpi_target_id, d.adjusted_value FROM pm_kpi_moderation_drafts d "
        "JOIN pm_kpi_targets t ON t.id=d.kpi_target_id WHERE d.approver_id=? AND t.cycle_id=? "
        "AND t.subject_id=? AND d.adjusted_value IS NOT NULL", (u["id"], cycle_id, subject_id))}
    if line:
        if line[1] is None:
            ov.pop(line[0], None)
        else:
            ov[line[0]] = line[1]
    _m, mine_prev, self_prev, _al = _pm_member_previews(db, subject_id, cycle_id, u["id"], overrides=ov or None)
    return (self_prev or {}).get("label"), (mine_prev or {}).get("label")


def _pm_remark_applies(db, u, subject_id):
    """The overall-band remark rule is the LINE MANAGER's (Chris, 2026-09-25) -- another approver in the chain
    isn't made to write one for a move the line manager already locked (2026-09-25 review)."""
    r = db.execute("SELECT manager_id FROM users WHERE id=?", (subject_id,)).fetchone()
    return bool(r and r["manager_id"] == u["id"])


def _pm_remark_missing(db, u, subject_id, cycle_id, line=None):
    """(missing, their band, moderated band): the line manager's overall remark is REQUIRED when their
    moderation moves the OVERALL performance band, up or down, and optional while it stays (Chris,
    2026-09-25: 'the rule for line manager remark follows the overall performance band movement'). Only the
    line manager is held to it."""
    sb, mb = _pm_overall_move(db, u, subject_id, cycle_id, line)
    moved = sb in PM_BAND_ORDER and mb in PM_BAND_ORDER and sb != mb
    return (moved and _pm_remark_applies(db, u, subject_id)
            and not _pm_manager_has_remark(db, u, cycle_id, subject_id)), sb, mb


def _pm_remark_missing_msg(sb, mb):
    nm = lambda c: PM_LABEL_NAMES.get(c, c or "")
    return ("Your moderation moves their overall band from %s to %s, so your overall remark is needed first "
            "(about 50-100 words) -- add it, then lock." % (nm(sb), nm(mb)))


def _pm_moderate_commit(db, u, kpi_target_id, raw, justification,
                        require_remark_on_overall_move=False):
    """Commit + LOCK one KPI-line moderation (a pm_kpi_approvals row -> the line
    locks). THE ONE authority the commit route AND the manager agent's lock tool
    share. `raw` is the adjusted-value string ('' = confirm as-is). Returns
    (result, err); err is None or {"reason","code","msg"}.

    require_remark_on_overall_move: when True (the review journey -- its Confirm & lock, the Team summary's
    bulk approve, and the chat lock tool), refuse to lock while the moderation as drafted moves the
    person's OVERALL band, up or down, and this approver hasn't written their overall remark (Chris,
    2026-09-25; it was a per-line justification on up-moves only, and the button didn't check at all).
    The classic moderation PAGE passes the default False, so its behaviour is unchanged."""
    target = db.execute("SELECT * FROM pm_kpi_targets WHERE id=?", (kpi_target_id,)).fetchone()
    _w = window_closed(db, "pm_approve", subject_id=target["subject_id"] if target else 0)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = _pm_mod_off(db, u, target["subject_id"]) if target else leader_ability_off(db, u, None)
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    if not target:
        return None, {"reason": "not_found", "code": 404}
    if not _report_takes_part(db, target["subject_id"], "pm"):   # out means out (Chris, 2026-10-30)
        return None, {"reason": "not_actionable", "code": 409, "msg": _report_part_refusal("pm")}
    target = dict(target)
    attach_pm_chains(db, [target])
    if not _pm_line_actionable_by(target, u["id"]):
        return None, {"reason": "not_actionable", "code": 409,
                      "msg": "This line is no longer awaiting your action."}
    # Field-preserving on lock too: a None value/justification takes it from the draft
    # (so the cell can commit the typed value while keeping the agent-drafted why, and
    # the agent's lock_kpi{} with no args locks the whole draft). "" value = confirm-as-is.
    existing = db.execute(
        "SELECT adjusted_value, justification FROM pm_kpi_moderation_drafts "
        "WHERE kpi_target_id=? AND approver_id=?", (kpi_target_id, u["id"])).fetchone()
    if raw is None:
        adjusted_value = existing["adjusted_value"] if existing else None
        action = "adjust" if adjusted_value is not None else "confirm"
    else:
        raw = raw.strip()
        if raw:
            try:
                value = float(raw)
            except ValueError:
                value = None
            if value is None or not math.isfinite(value):
                return None, {"reason": "bad_number", "code": 400,
                              "msg": "Enter a valid number, or leave it blank to confirm as-is."}
            _rl = _rating_line_error(target, value)   # a 1-5 rating line is moderated to a whole rating only
            if _rl:
                return None, {"reason": "bad_rating", "code": 400, "msg": _rl}
            action, adjusted_value = "adjust", value
        else:
            action, adjusted_value = "confirm", None
    if justification is None:
        justification = existing["justification"] if existing else None
    else:
        justification = justification.strip() or None
    _t, _serr = _store_text(justification or "", "manager")   # a note about someone: 4-03
    if _serr:
        return None, {"reason": "screened", "code": 400, "msg": _serr}
    _rl = _rating_line_error(target, adjusted_value)   # also a figure taken from an older draft (2026-10-30)
    if _rl:
        return None, {"reason": "bad_rating", "code": 400, "msg": _rl}
    # The line manager's overall remark is required once the moderation moves the OVERALL band (the
    # journey paths; the page passes the default False) -- checked with this line's value applied, before
    # any write.
    if require_remark_on_overall_move:
        missing, sb, mb = _pm_remark_missing(db, u, target["subject_id"], target["cycle_id"],
                                             line=(kpi_target_id, adjusted_value))
        if missing:
            return None, {"reason": "needs_remark", "code": 400, "msg": _pm_remark_missing_msg(sb, mb)}
    seq = len(target["approvals"]) + 1
    try:
        db.execute(
            "INSERT INTO pm_kpi_approvals(kpi_target_id, seq, action, original_value, "
            "adjusted_value, justification, acted_by) VALUES (?,?,?,?,?,?,?)",
            (target["id"], seq, action, target["effective_value"], adjusted_value,
             justification, u["id"]))
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        return None, {"reason": "conflict", "code": 409,
                      "msg": "Someone already acted on this line — refresh and try again."}
    log_activity(db, u["id"], "pm_kpi_act", "'%s': %s" % (target["kpi_name"], action))
    db.execute("DELETE FROM pm_kpi_moderation_drafts WHERE kpi_target_id=? AND approver_id=?",
               (kpi_target_id, u["id"]))
    # The rating record (2026-09-28): the manager-approved figure exists once EVERY line is locked -- this is the one
    # write every moderation path goes through (classic page, journey cell, bulk approve, the manager chat's lock).
    if pm_period_locked_for(db, target["cycle_id"], target["subject_id"]):
        _rating_record_refresh(db, target["cycle_id"], [target["subject_id"]], "pm_manager_lock", u["id"])
    # HR's reopen of this moderation is redone once every line of theirs on this person is acted on again (2026-10-16)
    if (_reopen_rows(db, target["cycle_id"], actor_id=u["id"], subject_id=target["subject_id"], parts=["pm_mod"])
            and _reopen_mod_done(db, u["id"], target["cycle_id"], target["subject_id"])):
        _reopen_close(db, target["subject_id"], ["pm_mod"], actor_id=u["id"])
    # a late pass's line manager follow-on is used once every line of theirs on this person is acted on (2026-10-31)
    if (_late_held_rows(db, u["id"], "pm_approve", target["cycle_id"], target["subject_id"])
            and _reopen_mod_done(db, u["id"], target["cycle_id"], target["subject_id"])):
        _late_close(db, u["id"], "pm_approve", "used", cycle_id=target["cycle_id"], subject_id=target["subject_id"])
    db.commit()
    target = dict(db.execute("SELECT * FROM pm_kpi_targets WHERE id=?", (kpi_target_id,)).fetchone())
    attach_pm_chains(db, [target])
    pm_score_targets(db, [target])
    self_value = target["result"]["actual_value"] if target.get("result") else None
    cfg = db.execute("SELECT * FROM pm_bg_config WHERE business_group=?",
                     (target["business_group"],)).fetchone()
    self_score = pm_score_kpi_line(cfg, target, self_value) if (cfg or _row_get(target, "rating_line")) else None
    if self_score:
        self_score["label"] = pm_label_for_value(
            db, target["business_group"], self_score["mechanism"], self_score["value"], subject=target,
            cycle_id=target["cycle_id"])
    _mine, mine_preview, self_preview, all_locked = _pm_member_previews(
        db, target["subject_id"], target["cycle_id"], u["id"])
    _feedback_lm_touch()
    # How far this moderation moved the band from the employee's own (2+ = a big move
    # the agent should strongly recommend a justification for).
    band_jump = pm_band_distance((self_score or {}).get("label"),
                                 (target.get("score") or {}).get("label"))
    return {"ok": True, "kpi_name": target["kpi_name"], "locked": target["locked"],
            "effective_value": target["effective_value"], "unit": target["unit"],
            "justification": justification, "score": target["score"], "self_score": self_score,
            "band_jump": band_jump,
            "mine_preview": _pm_round_preview(mine_preview),
            "self_preview": _pm_round_preview(self_preview), "all_locked": all_locked}, None


# ---- Assessing someone who didn't submit, on their behalf (Chris, 2026-10-26: "if a person didn't submit, it will flow
# to the LM first, if the LM didn't respond, only then it will flow to the HOD, and so on"; canvas
# [design canvas link removed], 3B, his four picks). Once the person's own part has closed with
# nothing submitted, the line manager keys in each KPI figure and writes why, then confirms: each figure is a moderation
# step flagged on_behalf (never a result of theirs, so nothing reads it as their own), final as a lock is. What the
# person saved but never submitted stays theirs, shown to the line manager beside the box as a starting point.

def _behalf_part_closed(db, cell, cycle_id, subject_id):
    """The person's own part (pm_results, tc_self) has CLOSED and they hold no open pass of HR's to redo it: from then
    their unsubmitted work is their line manager's to assess. Never before the close, so a cycle with no close date
    never gets there. Never for a person the part isn't theirs to do (their user role lacks it, an admin took them out,
    below the minimum grade; 2026-10-30): "Didn't submit" is only for someone who was meant to."""
    if not cycle_id or window_state(db, cell, cycle_id) != "closed":
        return False
    _mod = {"pm_results": "pm", "tc_self": "competency"}.get(cell)
    if _mod and not _report_takes_part(db, subject_id, _mod):
        return False
    if cell == "idp_self":   # the Career Plan is everyone's but a role without it, a leaver, below the grade (idp_participation; 2026-11-08)
        _su = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
        if not _su or not idp_participation(db, _su)[0]:
            return False
    if _late_held_rows(db, subject_id, cell, cycle_id, subject_id):   # a late pass is theirs to use: the line manager waits
        return False
    # a reopen whose days ran out leaves the part not submitted and missed (Chris, 2026-11-07): the line manager assesses it
    return not db.execute("SELECT 1 FROM submission_reopens WHERE cycle_id=? AND cell=? AND actor_id=? AND subject_id=? "
                          "AND closed_at IS NULL AND (until_at IS NULL OR until_at > datetime('now')) LIMIT 1",
                          (cycle_id, cell, subject_id, subject_id)).fetchone()


def _pm_subject_bu_names(db, subject_id, cid=None):
    """pm_bu_level_names for a person by id (set() for nobody), in cycle `cid` (default the active one)."""
    subj = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    return pm_bu_level_names(db, subj, cid) if subj else set()


def _pm_behalf_lines(u, ts):
    """Of a person's KPI lines (attach_pm_chains, drafts hidden), the ones they never submitted that wait on THIS
    approver: no result, not locked, their step next."""
    return [t for t in ts if not t.get("result") and not t.get("locked") and t.get("next_approver")
            and t["next_approver"]["approver_id"] == u["id"]]


def _pm_behalf_state(db, u, subject_id, period=None):
    """(lines, why_not) -- THE gate for a line manager's assessment on someone's behalf, which the card, its route and
    the Team counts share. `lines` are what they would assess (all of the person's lines in `ts`, scored by nothing yet);
    `why_not` is None when they may do it now, else the sentence."""
    period = period or active_pm_period(db)
    if not period:
        return [], "There's no review open."
    if not _report_takes_part(db, subject_id, "pm"):   # out means out: nothing to assess on their behalf (2026-10-30)
        return [], _report_part_refusal("pm")
    if _pm_chair_unmod_subject(db, subject_id):   # no moderator, so no step to assess in (2026-11-03): the refusal says so
        return [], ("Nobody can assess their KPI results on their behalf: their line manager is the Executive Chairman, "
                    "and nobody moderates his direct reports while his Moderate tick is off. He sets their bands in his "
                    "Talent Box.")
    if subject_id in kpis_bu_only_ids(db, period["id"], [subject_id]):
        # every KPI a BU KPI Group People fills (2026-10-26): their figures are Group People's, never assessed for them
        return [], ("Every KPI of theirs is a business unit result Group People fills in, so there's nothing to "
                    "assess on their behalf.")
    ts = [dict(t) for t in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
                                      "AND status='approved' ORDER BY " + PM_LINE_ORDER, (period["id"], subject_id))]
    attach_pm_chains(db, ts)
    # a BU KPI is Group People's figure, never the line manager's to assess for them (Chris, 2026-10-26: "line manager
    # will skip BU KPI, and they only assess/ fill in on behalf for the individual KPI")
    bu = _pm_subject_bu_names(db, subject_id, period["id"])
    lines = [t for t in _pm_behalf_lines(u, ts) if " ".join((t["kpi_name"] or "").lower().split()) not in bu]
    if not lines or pm_review_locked(db, subject_id, period["id"]):
        return [], "There's nothing of theirs waiting on you."
    if not _behalf_part_closed(db, "pm_results", period["id"], subject_id):
        return lines, "Their KPI check-in is theirs to submit until it closes."
    w = window_closed(db, "pm_approve", subject_id=subject_id)
    if w:
        return lines, w
    lo = leader_ability_off(db, u, _pm_behalf_ability(db, u, subject_id))
    return lines, lo


def _pm_behalf_drafts(db, u, line_ids):
    """{kpi_target_id: the figure this approver has typed} (their moderation drafts)."""
    if not line_ids:
        return {}
    return {r["kpi_target_id"]: r["adjusted_value"] for r in db.execute(
        "SELECT kpi_target_id, adjusted_value FROM pm_kpi_moderation_drafts WHERE approver_id=? AND kpi_target_id IN "
        "(%s)" % ",".join("?" * len(line_ids)), [u["id"]] + list(line_ids)) if r["adjusted_value"] is not None}


def _pm_behalf_preview(db, u, subject_id, period=None):
    """The card's live reading: each of the line manager's lines scored on the figure they typed, and the person's
    total once every one of their lines has a figure (never a partial total)."""
    period = period or active_pm_period(db)
    lines, _why = _pm_behalf_state(db, u, subject_id, period)
    mine_ids = {t["id"] for t in lines}
    drafts = _pm_behalf_drafts(db, u, list(mine_ids))
    ts = [dict(t) for t in db.execute("SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
                                      "AND status='approved' ORDER BY " + PM_LINE_ORDER, (period["id"], subject_id))]
    attach_pm_chains(db, ts)
    for t in ts:
        if t["id"] in mine_ids:
            t["effective_value"] = drafts.get(t["id"])
    pm_score_targets(db, ts)
    out, bu_out = [], []
    bu = _pm_subject_bu_names(db, subject_id, period["id"])
    for t in ts:
        is_bu = " ".join((t["kpi_name"] or "").lower().split()) in bu
        if t["id"] not in mine_ids and not is_bu:
            continue
        sc = t.get("score") if t["effective_value"] is not None else None
        (bu_out if is_bu and t["id"] not in mine_ids else out).append(
            {"id": t["id"], "value": t["effective_value"],
             "rating": (sc or {}).get("value"), "band": (sc or {}).get("label"),
             "n": (int(round(sc["value"])) if sc and sc.get("mechanism") == "A" and sc.get("value") is not None
                   else None)})
    total = None
    if ts and all(t.get("effective_value") is not None for t in ts):
        total = _pm_round_preview(pm_overall_for_targets(db, ts, require_locked=False))
    # the BU KPIs Group People fills (2026-10-26): shown on the card read only; the total waits for their figures too
    return {"lines": out, "total": total, "missing": sum(1 for x in out if x["value"] is None),
            "bu": bu_out, "bu_waiting": any(x["value"] is None for x in bu_out)}


def _pm_behalf_draft(db, u, subject_id, kpi_target_id, raw):
    """Save the line manager's figure for one line as they type (their moderation draft: nothing counts until they
    confirm); '' clears it. Returns (preview, err); err is None or {"reason","code","msg"}."""
    lines, why = _pm_behalf_state(db, u, subject_id)
    if why:
        return None, {"reason": "closed", "code": 409, "msg": why}
    t = next((x for x in lines if x["id"] == kpi_target_id), None)
    if not t:
        return None, {"reason": "not_actionable", "code": 409, "msg": "This KPI isn't yours to assess."}
    value = None
    if (raw or "").strip():
        value, _err = _agent_figure(raw, t.get("unit"))
        if value is None:
            return None, {"reason": "bad_number", "code": 400, "msg": "Enter a number in this KPI's unit."}
        _rl = _rating_line_error(t, value)   # a 1-5 rating line is assessed as a whole rating only
        if _rl:
            return None, {"reason": "bad_rating", "code": 400, "msg": _rl}
    db.execute("INSERT INTO pm_kpi_moderation_drafts(kpi_target_id, approver_id, adjusted_value, justification, "
               "updated_at) VALUES (?,?,?,NULL,datetime('now')) ON CONFLICT(kpi_target_id, approver_id) DO UPDATE SET "
               "adjusted_value=excluded.adjusted_value, updated_at=datetime('now')", (kpi_target_id, u["id"], value))
    db.commit()
    return _pm_behalf_preview(db, u, subject_id), None


def _pm_behalf_commit(db, u, subject_id):
    """Confirm the line manager's assessment on someone's behalf: every line of theirs the person never submitted gets
    the figure they typed as their moderation step, flagged on_behalf -- final, as a lock is. Their why (their report
    remark, pm_manager_remarks) is required (Chris's pick). Returns (result, err)."""
    period = active_pm_period(db)
    lines, why = _pm_behalf_state(db, u, subject_id, period)
    if why:
        return None, {"reason": "closed", "code": 409, "msg": why}
    drafts = _pm_behalf_drafts(db, u, [t["id"] for t in lines])
    missing = [t["kpi_name"] for t in lines if drafts.get(t["id"]) is None]
    if missing:
        return None, {"reason": "incomplete", "code": 409,
                      "msg": "Key in a figure for every KPI first: %s." % ", ".join(missing)}
    for t in lines:   # a rating line is assessed as a whole rating only, whatever the draft says (2026-10-30)
        _rl = _rating_line_error(t, drafts.get(t["id"]))
        if _rl:
            return None, {"reason": "bad_rating", "code": 400, "msg": "%s: %s" % (t["kpi_name"], _rl)}
    mr = db.execute("SELECT remark FROM pm_manager_remarks WHERE cycle_id=? AND subject_id=? AND submitted_by=?",
                    (period["id"], subject_id, u["id"])).fetchone()
    if not (mr and (mr["remark"] or "").strip()):
        return None, {"reason": "needs_remark", "code": 409,
                      "msg": "Write why first: what you based these figures on. Their HOD and CEOs read it."}
    try:
        for t in lines:
            db.execute("INSERT INTO pm_kpi_approvals(kpi_target_id, seq, action, original_value, adjusted_value, "
                       "justification, acted_by, on_behalf) VALUES (?,?,'adjust',NULL,?,NULL,?,1)",
                       (t["id"], len(t["approvals"]) + 1, drafts[t["id"]], u["id"]))
        db.execute("DELETE FROM pm_kpi_moderation_drafts WHERE approver_id=? AND kpi_target_id IN (%s)"
                   % ",".join("?" * len(lines)), [u["id"]] + [t["id"] for t in lines])
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        return None, {"reason": "conflict", "code": 409, "msg": "Someone already acted on this — refresh and try again."}
    log_activity(db, u["id"], "pm_on_behalf", "assessed %d KPI line(s) on behalf of someone who didn't submit"
                 % len(lines), target_user_id=subject_id)
    if pm_period_locked_for(db, period["id"], subject_id):
        _rating_record_refresh(db, period["id"], [subject_id], "pm_manager_lock", u["id"])
    db.commit()
    _feedback_lm_touch()
    return {"ok": True, "n": len(lines)}, None


@app.route("/review/team/behalf/pm", methods=["POST"])
@login_required
def review_team_behalf_pm():
    """The card's one route for an assessment on someone's behalf: op=draft (one line's figure, as they type) or
    op=confirm (all of them, final). The why is the report remark's own autosave route."""
    u = _review_guard()
    db = get_db()
    sid = request.form.get("report_id", type=int)
    if not sid:
        abort(404)
    if (request.form.get("op") or "") == "confirm":
        res, err = _pm_behalf_commit(db, u, sid)
    else:
        res, err = _pm_behalf_draft(db, u, sid, request.form.get("kpi_target_id", type=int),
                                    request.form.get("value"))
    if err:
        return jsonify(ok=False, error=err.get("msg") or err["reason"], reason=err["reason"]), err["code"]
    return jsonify(dict(res, ok=True))


