@app.route("/performance/team/<int:subject_id>/moderate-preview", methods=["POST"])
@login_required
def performance_team_member_preview(subject_id):
    """Read-only 'Moderated Rating' what-if preview for the drill-down page:
    the manager types values into the Moderate inputs and this recomputes the
    self->moderated aggregate WITHOUT committing anything (no pm_kpi_approvals
    write, no row lock) -- the actual commit only happens when they click the
    bottom Approve button (performance_kpi_moderate_autosave). Reuses
    _pm_member_previews()'s exact scoring via its `overrides` param, so the
    live preview and the eventually-committed result can never disagree.
    Returns only the two aggregates (never per-line peer values), scoped to
    'mine' by the helper -- matrix-case safe."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    if not _report_takes_part(db, subject_id, "pm"):   # out means out (2026-10-30)
        abort(403)
    overrides = {}
    for key, val in request.form.items():
        if not key.startswith("adjusted_value_"):
            continue
        raw = (val or "").strip()
        if not raw:
            continue
        try:
            f = float(raw)
        except ValueError:
            continue
        if math.isfinite(f):
            try:
                overrides[int(key[len("adjusted_value_"):])] = f
            except ValueError:
                continue
    _mine, mine_preview, self_preview, _all = _pm_member_previews(
        db, subject_id, period["id"], u["id"], overrides=overrides)
    return jsonify(mine_preview=_pm_round_preview(mine_preview),
                   self_preview=_pm_round_preview(self_preview))


def _pm_approver_done(u, mine):
    """This approver has acted on every step that was theirs (nothing left actionable, at least one acted):
    their review of the person is locked and final."""
    acted = any((a["acted_by"] if not isinstance(a, dict) else a.get("acted_by")) == u["id"]
                for t in mine for a in (t.get("approvals") or []))
    return bool(mine) and acted and not any(_pm_line_actionable_by(t, u["id"]) for t in mine)


def _pm_manager_remark_write(db, u, period, subject_id, remark):
    """THE ONE writer for a line manager's own overall remark on a direct report
    (pm_manager_remarks: one row per subject/period/APPROVER, no draft -- live once
    saved, held from the employee until every line this manager is chained to is
    locked). Shared by the autosave route AND the manager agent's set_report_remark
    tool. Scoped to THIS approver's own row -- a matrix co-approver's remark is never
    touched. The UNIQUE(cycle_id, subject_id, submitted_by) guard prevents a double
    INSERT race. Returns (result, err); err is None or {"reason","code","msg"}."""
    _w = window_closed(db, "pm_approve", subject_id=subject_id)
    if _w:
        return (None, {"reason": "closed", "code": 409, "msg": _w})
    # their seat's ability, switched by the super admin (Roles & access › Leader roles, 2026-10-20)
    _lo = _pm_mod_off(db, u, subject_id)
    if _lo:
        return (None, {"reason": "closed", "code": 409, "msg": _lo})
    if not _report_takes_part(db, subject_id, "pm"):   # out means out (Chris, 2026-10-30)
        return None, {"reason": "forbidden", "code": 403, "msg": _report_part_refusal("pm")}
    ts_all = [dict(t) for t in db.execute(
        "SELECT * FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? ORDER BY id",
        (period["id"], subject_id)).fetchall()]
    attach_pm_chains(db, ts_all)
    mine = _pm_team_mine(u, ts_all)
    if not mine:
        return None, {"reason": "forbidden", "code": 403}
    if all(t["locked"] for t in mine):
        return None, {"reason": "locked", "code": 409,
                      "msg": "This person's period is already locked."}
    remark = (remark or "").strip()
    # Once this approver has locked their own steps, their review is FINAL -- the same treatment as an
    # employee's final confirmation (Chris, 2026-09-25): no more edits to the remark either.
    if _pm_approver_done(u, mine):
        return None, {"reason": "locked", "code": 409,
                      "msg": "Your review of this person is locked -- it can't be changed."}
    # the remark-store rules (2026-10-21, as the competency review's remark): over the ceiling refused, never trimmed;
    # screened, because the tiers above and the AI summaries read it
    n = len(remark.split())
    if n > _REVIEW_REMARK_MAX_WORDS:
        return None, {"reason": "too_long", "code": 400,
                      "msg": "That's %d words: the limit is %d. Shorten it: it isn't saved until it fits."
                             % (n, _REVIEW_REMARK_MAX_WORDS)}
    if remark and ai_draft.stored_text_refusal(remark, "manager"):
        return None, {"reason": "screened", "code": 400,
                      "msg": "Reword the remark: part of it reads like an instruction rather than a remark."}
    try:
        existing = db.execute(
            "SELECT id FROM pm_manager_remarks "
            "WHERE cycle_id=? AND subject_id=? AND submitted_by=?",
            (period["id"], subject_id, u["id"])).fetchone()
        if existing:
            db.execute("UPDATE pm_manager_remarks SET remark=?, submitted_at=datetime('now'), "
                       "submitted_by=? WHERE id=?", (remark, u["id"], existing["id"]))
        elif remark:
            db.execute("INSERT INTO pm_manager_remarks(cycle_id, subject_id, remark, submitted_by) "
                       "VALUES (?,?,?,?)", (period["id"], subject_id, remark, u["id"]))
        _paste_mark_recount(db, u["id"], period["id"], "pm_review", subject_id, remark)   # whoever wrote it
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        return None, {"reason": "conflict", "code": 409, "msg": "Couldn't save — please try again."}
    return {"ok": True}, None


@app.route("/performance/team/<int:subject_id>/remark-autosave", methods=["POST"])
@login_required
def performance_team_member_remark_autosave(subject_id):
    """Autosave for the line manager's own remark on a direct report's period --
    a thin wrapper over the one writer _pm_manager_remark_write()."""
