@app.route("/calibration/hod/<int:hod_id>")
@login_required
def calibration_hod_view(hod_id):
    u = current_user()
    db = get_db()
    if not (is_hod_of(u, hod_id) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    _sk, _sa = _hod_review_skip_sql(db, hod_id)
    population = db.execute(
        f"SELECT * FROM users WHERE hod_id=? AND role!='admin' AND {calibration_population_sql()}{_sk} "
        f"ORDER BY full_name", [hod_id] + _sa).fetchall()
    if not population:
        abort(403)
    hod = db.execute("SELECT * FROM users WHERE id=?", (hod_id,)).fetchone()
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='hod' AND scope_key=?",
        (cid, str(hod_id))).fetchone()
    locked = bool(session_row and session_row["locked_at"])
    rows = _calibration_rows(db, population, cid, subject_band, session_row)
    dist = band_distribution_from_rows(rows)
    attach_tier_chain(db, rows, cid, population, "hod")
    return render_template(
        "calibration_hod.html", active_view="calibration", tier="hod",
        scope_label=hod["full_name"], department=hod["department"], rows=rows,
        people_count=len(rows),
        distribution=dist, gaps=calibration_target_gaps(dist, CALIBRATION_TARGET),
        target=CALIBRATION_TARGET, locked=locked, session=session_row,
        locked_by_name=_calibration_locked_by_name(db, session_row),
        hod_id=hod_id, cycle_id=cid, is_super_view=is_super(u),
    )


@app.route("/calibration/hod/<int:hod_id>/adjust", methods=["POST"])
@login_required
def calibration_hod_adjust(hod_id):
    u = current_user()
    db = get_db()
    if not (is_hod_of(u, hod_id) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    subject_id = _form_int("subject_id")
    new_band = (request.form.get("adjusted_band", "") or "").strip()
    justification = (request.form.get("justification", "") or "").strip()
    _sk, _sa = _hod_review_skip_sql(db, hod_id)   # a person the HOD calibrates higher up isn't theirs to review
    subject = db.execute(
        f"SELECT * FROM users WHERE id=? AND hod_id=? AND role!='admin' AND {calibration_population_sql()}{_sk}",
        [subject_id, hod_id] + _sa).fetchone()
    if not subject:
        return _calibration_respond(False, "That person isn't in this department.", "error",
                                     "calibration_hod_view", hod_id=hod_id)
    # Nobody calibrates themselves. The product already states this principle
    # for promotions -- "they are the one who APPROVES promotions ... the same
    # person shouldn't sit on both ends of that decision" -- but the three
    # calibration tiers never enforced it, so a BG CEO sat in his own list and
    # could set his own potential band, which then feeds the talent box and
    # merit. A super admin acting on someone else's scope is unaffected.
    if subject_id == u["id"]:
        return _calibration_respond(False, "You can't calibrate your own band. Ask the "
                                    "tier above to set it.", "error",
                                    "calibration_hod_view", hod_id=hod_id)
    if new_band not in ("Low", "Mid", "High"):
        return _calibration_respond(False, "Choose Low, Mid, or High.", "error",
                                     "calibration_hod_view", hod_id=hod_id)
    _t, _serr = _store_text(justification, "manager")   # the tiers above read it (4-03)
    if _serr:
        return _calibration_respond(False, _serr, "error", "calibration_hod_view", hod_id=hod_id)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='hod' AND scope_key=?",
        (cid, str(hod_id))).fetchone()
    if session_row and session_row["locked_at"]:
        return _calibration_respond(False, "This department's calibration is locked.", "error",
                                     "calibration_hod_view", hod_id=hod_id)
    # the department review (2026-09-30): closed once the BU is locked; a band change needs the HOD's remark (the one
    # already given is kept when the form leaves it blank)
    closed = _hod_review_closed(db, "pot", cid, db.execute(
        f"SELECT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND "
        f"{calibration_population_sql()}{_sk}", [hod_id] + _sa).fetchall(), hod_id=hod_id)
    if closed:
        return _calibration_respond(False, closed, "error", "calibration_hod_view", hod_id=hod_id)
    if _hod_saved_already(db, "pot", session_row["id"] if session_row else None, subject_id):
        return _calibration_respond(False, _hod_saved_msg(subject["full_name"]), "error", "calibration_hod_view",
                                    hod_id=hod_id)
    if not justification and session_row:
        _prev = db.execute("SELECT justification FROM calibration_adjustments WHERE session_id=? AND subject_id=?",
                           (session_row["id"], subject_id)).fetchone()
        justification = ((_prev["justification"] or "") if _prev else "").strip()
    original = subject_band(db, subject, cid)["band"] or ""
    if _hod_remark_needed("hod", new_band, original, justification):
        return _calibration_respond(False, HOD_REMARK_MSG, "error", "calibration_hod_view", hod_id=hod_id)
    hod_row = db.execute("SELECT full_name FROM users WHERE id=?", (hod_id,)).fetchone()
    session_row = _get_or_create_calibration_session(
        db, cid, "hod", str(hod_id), subject["business_group"], hod_row["full_name"])
    _calibration_upsert_adjustment(db, session_row["id"], subject_id, original, new_band,
                                    justification, u["id"])
    log_activity(db, u["id"], "calibration_adjust",
                 f"{subject['full_name']}: {original or 'No Data'} -> {new_band} (hod scope)",
                 target_user_id=subject_id)
    return _calibration_respond(True, f"{subject['full_name']}'s band set to {new_band}.", "ok",
                                 "calibration_hod_view", hod_id=hod_id)


@app.route("/calibration/hod/<int:hod_id>/reset", methods=["POST"])
@login_required
def calibration_hod_reset(hod_id):
    u = current_user()
    db = get_db()
    if not (is_hod_of(u, hod_id) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='hod' AND scope_key=?",
        (cid, str(hod_id))).fetchone()
    if session_row and session_row["locked_at"]:
        flash("This department's calibration is locked.", "error")
    elif session_row and db.execute("SELECT 1 FROM calibration_adjustments WHERE session_id=? LIMIT 1",
                                    (session_row["id"],)).fetchone():
        flash(_HOD_NO_RESET_MSG, "error")   # each person is saved once (_hod_saved_already)
    elif session_row:
        db.execute("DELETE FROM calibration_adjustments WHERE session_id=?", (session_row["id"],))
        db.commit()
        log_activity(db, u["id"], "calibration_reset", f"HOD scope reset: hod_id={hod_id}")
        flash("All adjustments cleared -- back to the raw 360 bands.", "ok")
    else:
        flash("No adjustments to reset.", "ok")
    return redirect(url_for("calibration_hod_view", hod_id=hod_id))


def _calib_scope_scored(db, population, cycle_id, session_row):
    """How many people in this scope actually have a band to calibrate.

    Locking is a claim to the tier above: calibration_pending_children() gates
    on locked_at alone and never asks whether anyone was in the scope, so an
    empty department that gets locked is indistinguishable upstream from one
    that was genuinely reviewed. Counting the same rows the page itself shows
    means the refusal below can never disagree with what the user is looking
    at."""
    rows = _calibration_rows(db, population, cycle_id, subject_band, session_row)
    return sum(band_distribution_from_rows(rows).values())


def _pot_calib_back(default):
    """Where a potential lock returns: the review journey when it was locked from there (a same-site /review/journey
    path in the form's return_to, 2026-09-28), else the classic calibration page."""
    rt = (request.form.get("return_to") or "").strip()
    if rt.startswith("/review/journey") and "//" not in rt and "\\" not in rt:
        return rt
    return default


@app.route("/calibration/hod/<int:hod_id>/lock", methods=["POST"])
@login_required
def calibration_hod_lock(hod_id):
    u = current_user()
    db = get_db()
    if not (is_hod_of(u, hod_id) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='hod' AND scope_key=?",
        (cid, str(hod_id))).fetchone()
    if session_row and session_row["locked_at"]:
        if request.form.get("ajax") == "1":
            return jsonify(ok=True, already=True)
        flash("Already locked.", "error")
    else:
        hod_row = db.execute("SELECT business_group, full_name FROM users WHERE id=?", (hod_id,)).fetchone()
        _sk, _sa = _hod_review_skip_sql(db, hod_id)
        population = db.execute(
            f"SELECT * FROM users WHERE hod_id=? AND role!='admin' AND "
            f"{calibration_population_sql()}{_sk} ORDER BY full_name", [hod_id] + _sa).fetchall()
        if not _calib_scope_scored(db, population, cid, session_row):
            return _lock_reply(False, "Nobody in this department has a potential band yet, so there is nothing to "
                                      "calibrate. Locking it would tell the tier above that it was reviewed.",
                               _pot_calib_back(url_for("calibration_hod_view", hod_id=hod_id)))
        # A department review (Chris, 2026-09-30): no curve rule on the HOD's submit -- the BU CEO fits the curve --
        # and closed once the business unit is locked (_hod_review_closed).
        closed = _hod_review_closed(db, "pot", cid, population, hod_id=hod_id)
        if closed:
            return _lock_reply(False, closed, _pot_calib_back(url_for("calibration_hod_view", hod_id=hod_id)))
        # ...and nobody goes up with no band: the HOD bands them first (Chris, 2026-09-30)
        _pop = _pot_scope_population(db, "hod", hod_id)
        _un = _dept_review_unassigned(_pot_calib_overview(db, u, _pot_calib_sc(db, cid, "hod", hod_id, _pop))["rows"],
                                      pot=True) if _pop else []
        if _un:
            return _lock_reply(False, _dept_review_unassigned_msg(_un, pot=True),
                               _pot_calib_back(url_for("calibration_hod_view", hod_id=hod_id)))
        session_row = _get_or_create_calibration_session(
            db, cid, "hod", str(hod_id), hod_row["business_group"], hod_row["full_name"])
        db.execute("UPDATE calibration_sessions SET locked_at=datetime('now'), locked_by=? WHERE id=?",
                   (u["id"], session_row["id"]))
        _rating_record_refresh(db, cid, [p["id"] for p in population], "pot_calib_lock_hod", u["id"])
        db.commit()
        log_activity(db, u["id"], "calibration_lock", f"HOD scope locked: {hod_row['full_name']}")
        _late_after_lock(db, u, "hod", hod_row["business_group"], str(hod_id))   # a late pass is used once both axes are in (2026-11-07)
        db.commit()
        return _lock_reply(True, "Department review submitted to your BU CEO.",
                           _pot_calib_back(url_for("calibration_hod_view", hod_id=hod_id)))
    return redirect(_pot_calib_back(url_for("calibration_hod_view", hod_id=hod_id)))


@app.route("/calibration/hod/<int:hod_id>/unlock", methods=["POST"])
@login_required
def calibration_hod_unlock(hod_id):
    """Super-admin escape hatch. No cascading side effects -- mirrors report_releases' own precedent exactly (unlocking a
    lower tier does NOT auto-unlock any locked tier built on top of it; that tier's own view surfaces a staleness warning
    instead, via calibration_pending_children). Since 2026-11-07 one Unlock for both axes: _unlock_scope's."""
    return _unlock_route("hod", hod_id, url_for("calibration_hod_view", hod_id=hod_id))


# --- PM Calibration: the HOD -> BUCEO -> BGCEO cascade ------------------------
# One generic implementation parameterised by tier, rather than the 360
# module's three near-duplicate route sets: PM's tiers differ only in who may
# open a scope and which people it covers, so triplicating ~150 lines of
# identical adjust/reset/lock/unlock logic would just be three places to fix
# every future bug. PM_CALIB_TIERS holds everything that actually varies.
def _pm_calib_scope_key(tier, **kw):
    """The stable string identifying one scope within a tier -- what
    pm_calibration_sessions.scope_key stores and pm_effective_band() matches
    on. Must agree exactly with pm_effective_band()'s own lookups."""
    if tier == "hod":
        return str(kw["hod_id"])
    if tier == "buceo":   # a unit, or one of its calibration groups (2026-10-22)
        return BU_GROUP_PREFIX + str(kw["grp"]) if kw.get("grp") else kw["company"]
    if tier == "group":
        return str(kw["group_id"])
    return kw["bg"]


def _pm_calib_resolve(db, u, tier, **kw):
    """Auth + population + session + approved bands for any tier, resolved in
    one place so a view and its four mutations can never disagree about who is
    in scope. Every mutation re-derives this rather than trusting posted
    values. Returns None-safe pieces or aborts."""
    period = active_pm_period(db)
    if not period:
        abort(404)
    # the seat's abilities (Roles & access › Leader roles, 2026-10-20): its view, its moves, its lock
    if not leader_can(u, leader_tier_ability(tier, "view", kw), db) or (
            request.method == "POST" and _leader_classic_post()
            and not leader_can(u, leader_tier_ability(tier, _leader_req_kind(), kw), db)):
        abort(403)
    if tier == "hod":
        hod_id = kw["hod_id"]
        if not (is_hod_of(u, hod_id) or is_super(u)):
            abort(403)
        where, params = "hod_id=?", [hod_id]
        _sk, _sa = _hod_review_skip_sql(db, hod_id)   # a calibrator is no HOD: nobody (2026-10-30)
        where, params = where + _sk, params + _sa
        row = db.execute("SELECT full_name FROM users WHERE id=?", (hod_id,)).fetchone()
        label = row["full_name"] if row else str(hod_id)
    elif tier == "buceo" and kw.get("grp"):
        # a calibration group of the unit (2026-10-22): its calibrator calibrates its departments at BU CEO level
        bg, company = kw["bg"], kw["company"]
        grp = bu_group(db, kw["grp"])
        if not grp or (grp["business_group"], grp["company"]) != (bg, company):
            abort(404)
        if not (u["id"] == grp["calibrator_id"] or is_super(u)):
            abort(403)
        where = "business_group=? AND " + bu_group_member_sql()   # every unit it reaches (2026-10-22)
        params = [bg, grp["id"]]
        label = bu_group_label(bg, grp)
    elif tier == "buceo":
        bg, company = kw["bg"], kw["company"]
        join = calib_join(db, period["id"], bg, company)   # units calibrated together this cycle (row 6)
        units = join["members"] if join else [company]
        if not (any(is_buceo_of(u, bg, c_) for c_ in units) or is_super(u)):
            abort(403)
        # a calibration group's departments are its calibrator's, never the BU CEO's (2026-10-22): read only for them
        where, params = ("business_group=? AND company IN (%s) AND NOT %s" % (",".join("?" * len(units)),
                                                                            bu_grouped_sql()), [bg] + units)
        label = join["label"] if join else display_company(bg, company)
    elif tier == "group":
        group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?",
                           (kw["group_id"],)).fetchone()
        if not group:
            abort(404)
        if not (u["id"] == group["calibrator_id"] or is_super(u)):
            abort(403)
        # Membership is an explicit list, not an org predicate -- that's the
        # whole point of a group, so it replaces the usual where-clause.
        where = ("id IN (SELECT subject_id FROM pm_calibration_group_members "
                 "WHERE group_id=?)")
        params = [kw["group_id"]]
        label = group["name"]
    else:
        bg = kw["bg"]
        if not (is_bgceo_of(u, bg) or is_super(u)):
            abort(403)
        where, params = "business_group=?", [bg]
        label = display_bg(bg)
    population = db.execute(
        f"SELECT * FROM users WHERE {where} AND role!='admin' AND "
        f"{pm_calibration_population_sql()} ORDER BY full_name",
        params + [period["id"]]).fetchall()
    if not population:
        abort(403)
    scope_key = _pm_calib_scope_key(tier, **kw)
    join = (calib_join(db, period["id"], kw.get("bg"), kw.get("company"))
            if tier == "buceo" and not kw.get("grp") else None)
    if join:
        scope_key = join["lead"]
    session_row = db.execute(
        "SELECT * FROM pm_calibration_sessions WHERE cycle_id=? AND tier=? AND scope_key=?",
        (period["id"], tier, scope_key)).fetchone()
    overalls = pm_final_overalls(db, period["id"], [p["id"] for p in population])
    out = {"period": period, "population": population, "session": session_row,
           "overalls": overalls, "scope_key": scope_key, "scope_label": label,
           "business_group": population[0]["business_group"], "actor_id": u["id"]}
    if tier == "buceo":
        out["grp"] = bu_group(db, kw["grp"]) if kw.get("grp") else None
        out["others"] = [] if kw.get("grp") else bu_unit_others(db, period["id"], kw["bg"],
                                                                  join["members"] if join else [kw["company"]])
    if join:   # each unit keeps its own session underneath; the lead's BU CEO calibrates, the others read
        out.update(join=join, member_sessions={m: db.execute(
            "SELECT * FROM pm_calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=?",
            (period["id"], m)).fetchone() for m in join["members"]},
            read_only=not (is_buceo_of(u, kw["bg"], join["lead"]) or is_super(u)))
    return out


def _pm_calib_incoming_fn(db, tier, cycle_id):
    """What band a tier INHERITS for each person. The HOD tier starts from the
    manager-approved rating; every tier above resolves through whatever the
    locked tier(s) below decided, falling through to the approved band for
    anyone those tiers never individually touched."""
    # Returns a dict, not a bare band: the row also shows WHY the band came in
    # at that value (the lower tier's justification), which is the note the
    # calibrator needs to read before overriding it.
    # None-safe (2026-09-29): an HOD or BU CEO may now band someone whose score isn't finalised, and the tier above
    # must inherit that locked band -- pm_effective_band resolves the locked tiers first and takes raw_band=None.
    if tier == "hod":
        return lambda p, ov: {"band": ov["label"] if ov else None, "source": "raw", "note": ""}
    if tier == "group":
        # A group outranks the whole line, so it inherits the manager-approved
        # band directly rather than whatever a department happened to decide --
        # otherwise the group calibrator would be starting from a number their
        # own decision is about to discard.
        return lambda p, ov: {"band": ov["label"] if ov else None, "source": "raw", "note": ""}
    if tier == "bgceo":   # a business unit locked on the Talent Box makes the BG CEO's move count downstream; their own
        # seat still inherits only what came from below (2026-10-07)
        return lambda p, ov: pm_effective_band(db, p, cycle_id, ov["label"] if ov else None, skip_tiers=("bgceo",))
    if tier == "buceo":   # nor the BU CEO's: the BG CEO's and a Group Chief's later calls reach a BU CEO only once HR
        # releases the results to leaders (2026-10-12), never on their curve
        return lambda p, ov: pm_effective_band(db, p, cycle_id, ov["label"] if ov else None,
                                               skip_tiers=("bgceo", "group"))
    return lambda p, ov: pm_effective_band(db, p, cycle_id, ov["label"] if ov else None)


def _pm_calib_redirect(tier, **kw):
    return url_for(f"pm_calibration_{tier}_view", **kw)


def _pm_calib_view(tier, **kw):
    u = current_user()
    db = get_db()
    ctx = _pm_calib_resolve(db, u, tier, **kw)
    period, population = ctx["period"], ctx["population"]
    # Company filter, BG tier only -- the tier below already IS one company.
    # Server-side, like the Talent Box's: the reference curve is a property of
    # the population you're looking at, so narrowing genuinely re-asks the
    # question rather than hiding people from an unchanged answer.
    all_companies = sorted({(p["company"] or "") for p in population if p["company"]}) \
        if tier == "bgceo" else []
    f_company = request.args.get("company", "").strip()
    if f_company not in all_companies:
        f_company = ""
    if f_company:
        population = [p for p in population if (p["company"] or "") == f_company]
    rows = _pm_calibration_rows(db, population, period["id"], ctx["overalls"],
                                 ctx["session"], _pm_calib_incoming_fn(db, tier, period["id"]),
                                 default_ua=tier in _CALIB_AXIS_TIERS, self_id=u["id"],
                                 session_ids=_calib_session_ids(ctx))
    # Super overrides outrank every tier, so they have to be visible HERE too --
    # otherwise a calibrator sees their own band on screen while the person's
    # real one is something else. One query for the whole scope.
    overrides = {r["subject_id"]: r for r in db.execute(
        "SELECT ca.* FROM pm_calibration_adjustments ca "
        "JOIN pm_calibration_sessions cs ON cs.id = ca.session_id "
        "WHERE cs.cycle_id=? AND cs.tier='super'", (period["id"],)).fetchall()}
    # Which people are owned by a cross-org group. On the group's own page this
    # is the population; on a line tier it's a warning -- the group's band wins,
    # so an HOD adjusting one of these needs to know their change won't stick.
    memberships = {r["subject_id"]: r for r in db.execute(
        "SELECT gm.subject_id, g.id AS group_id, g.name FROM pm_calibration_group_members gm "
        "JOIN pm_calibration_groups g ON g.id = gm.group_id")}
    for r in rows:
        r["group"] = memberships.get(r["user"]["id"])
        ov = overrides.get(r["user"]["id"])
        r["override"] = ov
        if ov:
            # What everyone will actually see, so the distribution below counts
            # the real spread rather than this tier's superseded view of it.
            r["current_band"] = ov["adjusted_band"]
    # Where each band has been, not just where it sits: Self -> LM -> HOD ->
    # BUCEO -> BGCEO. Self and LM come from the PM module's own record (the
    # employee's submission, then their manager's approval of it); only the
    # three calibration tiers move it from there.
    attach_pm_tier_chain(db, rows, period["id"], tier,
                         pm_self_overalls(db, period["id"], [p["id"] for p in population]))
    glock = None
    if tier == "group":   # canvas G2: the BG CEO's call beside yours, and the people / departments you have locked
        gid = kw["group_id"]
        locks = group_locks(db, period["id"], gid)
        depts = {}
        for r in rows:
            p = r["user"]
            r["glock"] = locks.get(p["id"])
            if r["glock"]:
                r["glock"]["day"] = _st_day(_myt(r["glock"]["locked_at"]))   # "10 Oct 2026", in MYT
            ov = ctx["overalls"].get(p["id"])
            r["bg_call"] = (pm_effective_band(db, p, period["id"], ov["label"], skip_tiers=("super", "group"))["band"]
                            if ov else None)
            r["lockable"] = bool(ov) and not r["glock"] and p["id"] != u["id"]
            d = depts.setdefault(((p["department"] or "").strip(), p["business_group"] or ""),
                                 {"dept": (p["department"] or "").strip(), "bg": p["business_group"] or "", "n": 0,
                                  "open": 0, "locked": 0})
            d["n"] += 1
            d["open"] += 1 if r["lockable"] else 0
            d["locked"] += 1 if r["glock"] else 0
        m = calib_group_mode(gid)
        glock = {"n": len(locks), "open": sum(1 for r in rows if r["lockable"]), "mode_word": calib_group_mode_word(m),
                 "depts": sorted(depts.values(), key=lambda d: (-d["open"], d["dept"], d["bg"]))}
    dist = pm_band_distribution(rows)
    # How many companies this scope spans -- the middle chip in the header, so
    # performance, potential and the Talent Box all read the same shape.
    company_count = len({(p["company"] or "") for p in population})
    # A BG spans companies with different PAT figures, so it gets no single
    # curve -- one panel per company, each against its own. HOD and BUCEO both
    # sit inside one company and share that company's curve.
    # ONE reference curve for the page, because there is now ONE distribution box.
    # On "All" at the BG tier that reference is the SUM of each unit's own target
    # headcount -- not a blended percentage nobody set, but real per-unit targets
    # added up, which is why the BG gap equals the sum of the per-unit gaps. Pick
    # a unit and the population narrows to it, so the same box becomes that unit
    # against its own PAT curve. The per-unit panel stack is gone: 14 stacked
    # panels answered "how does each unit look" and never "how does the BG look".
    if tier == "bgceo" and not f_company:
        by_company = defaultdict(list)
        for r in rows:
            by_company[r["user"]["company"] or ""].append(r)
        tgt = {b: 0 for b in PM_BAND_ORDER}
        for company, crows in by_company.items():
            cdist = pm_band_distribution(crows)
            ccurve = pm_curve_for(db, period["id"], ctx["business_group"], company)
            n = sum(cdist.values())
            for b in PM_BAND_ORDER:
                tgt[b] += round(ccurve["dist"][b] / 100 * n)
        placed = sum(dist.values())
        curve = {"dist": {b: (round(tgt[b] / placed * 100, 1) if placed else 0)
                          for b in PM_BAND_ORDER},
                 "aggregate": True, "units": len(by_company),
                 "mixed": False, "entered": False, "pct": None, "label": "", "note": ""}
        gaps = {b: tgt[b] - dist[b] for b in PM_BAND_ORDER}
        dist_heading = f"{display_bg(ctx['business_group'])} overall"
    elif tier == "group":
        # A group can span BGs, so there is no one PAT figure behind it. Show
        # the normal curve and say plainly that it's a default, rather than
        # picking one member's company figure and implying it applies to all.
        curve = {"key": "normal", "dist": PM_DIST_CURVES["normal"],
                 "label": PM_CURVE_LABELS["normal"][0], "note": PM_CURVE_LABELS["normal"][1],
                 "pct": None, "entered": False, "mixed": True}
        gaps = pm_calibration_target_gaps(dist, curve["dist"])
        dist_heading = "Distribution vs. reference curve"
    else:
        company = population[0]["company"]
        curve = pm_curve_for(db, period["id"], ctx["business_group"], company)
        gaps = pm_calibration_target_gaps(dist, curve["dist"])
        dist_heading = display_company(ctx["business_group"], company) \
            or "Distribution vs. reference curve"
    # Whose note is whose in the chain popover, phrased per tier -- the same
    # convention the potential templates pass to _calib_chain.html.
    PREV_LABEL = {"hod": "Manager-approved:", "buceo": "HOD note:",
                  "bgceo": "Business unit note:", "group": "Manager-approved:"}
    OWN_LABEL = {"hod": "HOD note:", "buceo": "Business unit note:",
                 "bgceo": "Business group note:", "group": "Group note:"}
    # The lock gate is enforced in _pm_calib_lock(), but the page never said so:
    # the potential-axis templates show "Waiting on department calibration to
    # lock first" up front, while here you learned by clicking Lock and failing.
    # Same helper the lock route uses, so the banner and the refusal agree.
    pending = pm_calibration_pending_children(
        db, ctx["period"]["id"], tier, ctx["business_group"],
        ctx["scope_key"]) if tier in ("buceo", "bgceo") else []
    return render_template(
        "pm_calibration_tier.html", tier=tier, period=period, pending=pending,
        scope_label=ctx["scope_label"], business_group=ctx["business_group"],
        # A BG spans companies and a group spans organisations, so neither has
        # one company to name in the curve subtitle.
        company=(None if tier in ("bgceo", "group") else population[0]["company"]),
        rows=rows, people_count=len(rows), company_count=company_count,
        distribution=dist, gaps=gaps, curve=curve,
        # calibration.js reads the reference off the box's data-target, and the
        # template draws its ticks from the same dict -- one source, so the
        # server-rendered bar and the live one can't disagree.
        target=curve["dist"], dist_heading=dist_heading,
        prev_note_label=PREV_LABEL[tier], own_note_label=OWN_LABEL[tier],
        band_order=PM_BAND_ORDER, label_names=PM_LABEL_NAMES,
        locked=bool(ctx["session"] and ctx["session"]["locked_at"]), session=ctx["session"],
        locked_by_name=_calibration_locked_by_name(db, ctx["session"]),
        is_super_view=is_super(u),
        scope_kwargs=kw, glock=glock,
        all_companies=all_companies, f_company=f_company,
        # Same short labels the Talent Box and the potential-calibration BU row
        # use, so one company reads identically wherever you meet it.
        company_labels={c: COMPANY_SHORT.get(c) or display_company(ctx["business_group"], c)
                        for c in all_companies},
        # The AI+ calibration assistant, shown only when it is switched on and only
        # for the tiers it covers (hod/buceo). The grid stays the primary surface.
        calib_assist_url=(url_for("pm_calib_assist_%s" % tier, **kw)
                          if tier in CALIB_ASSIST_TIERS and _calib_assist_on(u) else None),
    )


def _pm_calib_apply(db, u, ctx, tier, subject_id, new_band, justification, dry_run=False):
    """Validate + WRITE one performance-band adjustment. THE single write path,
    shared by the grid's adjust route (_pm_calib_adjust, from request.form) and
    the AI assistant's move_band tool (from model args), so the two can never
    disagree about what a valid move is -- the same discipline as
    _pm_setting_propose / _tc_submit / _feedback_submit. Returns
    (subject_row, None) on success or (None, error_message)."""
    population, session_row, period = ctx["population"], ctx["session"], ctx["period"]
    # a switched-off module stops its writes (1b-01): performance calibration is Performance's (the grid's routes are
    # classed pm), and every tier above the HOD's department review is the Calibration module's -- the Mid-Year HOD, who
    # has no calibration, keeps working with Calibration off
    _mo = _module_off_msg("pm", *(() if tier == "hod" else ("calibration",)), db=db, cycle_id=period["id"])
    if _mo:
        return None, _mo
    _lo = leader_ability_off(db, u, leader_tier_ability(tier, "move", ctx))   # Roles & access › Leader roles (2026-10-20)
    if _lo:
        return None, _lo
    subject = next((p for p in population if p["id"] == subject_id), None)
    shared = False
    if not subject and tier == "buceo" and not ctx.get("grp"):   # a BU group sharing the call (split under 100)
        subject = next((p for p in (ctx.get("others") or []) if p["id"] == subject_id
                        and bu_group_split(bu_group_of(db, p)) < 100), None)
        shared = bool(subject)
    if not subject:
        return None, "That person isn't in this scope."
    # Nobody calibrates their own band (2026-09-28): a BU CEO's population includes the BU CEO when they have KPI
    # lines, and the potential adjust routes already refuse this -- the performance path never did.
    if subject_id == u["id"]:   # an HOD never reviews their own either (Chris, 2026-10-06): their BU CEO does
        return None, _calib_self_msg(tier)
    # adjusted_band is TEXT NOT NULL with no CHECK, so an unrecognised band
    # would otherwise be stored verbatim and then never match the distribution
    # or the pill colours -- reject it here rather than write it.
    if new_band not in PM_BAND_ORDER:
        return None, "Choose a performance band."
    _t, _serr = _store_text((justification or "").strip(), "manager")   # a note the tiers above read (4-03)
    if _serr:
        return None, _serr
    _over = _calib_remark_over(tier, justification)
    if _over:
        return None, _over
    if session_row and session_row["locked_at"]:
        return None, ("This department review is submitted." if tier == "hod" else "This scope's calibration is locked.")
    if tier == "group" and db.execute("SELECT 1 FROM pm_group_locks WHERE cycle_id=? AND group_id=? AND subject_id=?",
                                      (period["id"], int(ctx["scope_key"]), subject_id)).fetchone():
        return None, "%s's call is locked: the super admin decides the final band now." % subject["full_name"]
    _bul = _tb_bu_lock_of(db, subject_id, period_id=period["id"]) if tier == "bgceo" else None
    if _bul:   # the BG CEO locked their business unit on the Talent Box (2026-10-07)
        return None, f"{_bul} is locked — its people can't be moved now."
    _gro = gc_reads_only(db, subject_id) if tier == "bgceo" else None
    if _gro:   # their Group Chief group takes the whole call (the split's 100 : 0, 2026-10-22)
        return None, GC_READS_ONLY_MSG % (subject["full_name"], _gro)
    skey = subject["company"] if ctx.get("join") else ctx["scope_key"]   # row 6: their unit
    _bgc = (_bg_closed(db, "pm", period["id"], ctx["business_group"], subject["company"] if ctx.get("grp") else skey)
            if tier == "buceo" else None)   # a group's person by their own unit (2026-10-22)
    if _bgc:   # ...which closes the BU CEO's calibration too: the BG CEO's decision is final (2026-10-07)
        return None, _bgc
    _w = (window_closed_tier(db, tier, "pm", period["id"], scope=_late_ctx_scopes(ctx))   # a late pass is its scope's
          if tier != "hod" else None)   # the HOD's: _hod_review_closed
    if _w:
        return None, _w
    if ctx.get("read_only"):   # units calibrated together: the lead unit's BU CEO calibrates, the others read (row 6)
        return None, _join_read_only_msg(db, ctx)
    if ctx.get("join"):   # each move on the person's own unit's session, so every reader finds it there
        session_row = (ctx.get("member_sessions") or {}).get(skey)
    overall = (pm_final_overalls(db, period["id"], [subject_id]).get(subject_id) if shared
               else ctx["overalls"].get(subject_id))
    # Measure against what this tier INHERITED, not the last saved value, so
    # two successive +-1 nudges that add up to 2 bands still resolve honestly.
    incoming = _pm_calib_incoming_fn(db, tier, period["id"])(subject, overall)
    # An HOD or BU CEO may set the band of someone whose score isn't finalised (Chris, 2026-09-29: "HOD or BUCEO ...
    # has the ability to set the band directly without the score being needed to be finalized"). A band set that way
    # counts at the tier above ("yes, everywhere"), so the BG CEO and a group may calibrate it; with neither a
    # finalised score nor a band from below, they have nothing to calibrate.
    if not overall and tier not in _CALIB_AXIS_TIERS and not (incoming and incoming.get("band")):
        return None, ("That person's rating isn't final yet — every KPI line "
                      "has to be approved before it can be calibrated.")
    if tier == "hod":   # the department review (2026-09-30): closed once the BU is locked; a change needs a remark
        closed = _hod_review_closed(db, "pm", period["id"], population, hod_id=ctx["scope_key"])
        if closed:
            return None, closed
        if _hod_saved_already(db, "pm", session_row["id"] if session_row else None, subject_id):
            return None, _hod_saved_msg(subject["full_name"])
        if _hod_remark_needed(tier, new_band, (incoming or {}).get("band"), justification):
            return None, HOD_REMARK_MSG
    if dry_run:   # every check passed; nothing written (the agent putting a band on the HOD's page, 2026-10-06)
        return subject, None
    existing = None
    if session_row:
        existing = db.execute(
            "SELECT original_band FROM pm_calibration_adjustments "
            "WHERE session_id=? AND subject_id=?", (session_row["id"], subject_id)).fetchone()
    # incoming is a dict ({band, source, note}), not a bare band -- original_band
    # is TEXT NOT NULL, so take the band out of it. Empty string, never None,
    # when the cascade has nothing to inherit.
    original = existing["original_band"] if existing else (incoming["band"] or "")
    session_row = _pm_calib_get_or_create_session(
        db, period["id"], tier, skey, subject["business_group"],
        (display_company(subject["business_group"], skey) or skey) if ctx.get("join") else ctx["scope_label"])
    if ctx.get("join"):
        ctx["member_sessions"][skey] = session_row
        if skey == ctx["scope_key"]:
            ctx["session"] = session_row
    _pm_calib_upsert_adjustment(db, session_row["id"], subject_id, original, new_band,
                                 justification, u["id"], seen_band=(incoming or {}).get("band") or "")
    log_activity(db, u["id"], "pm_calibration_adjust",
                 f"{subject['full_name']}: {original} -> {new_band} ({tier} scope)",
                 target_user_id=subject_id)
    return subject, None


def _pm_calib_adjust(tier, **kw):
    u = current_user()
    db = get_db()
    ctx = _pm_calib_resolve(db, u, tier, **kw)
    respond = lambda ok, msg, cat: _calibration_respond(
        ok, msg, cat, f"pm_calibration_{tier}_view", **kw)
    subject_id = _form_int("subject_id")
    new_band = (request.form.get("adjusted_band", "") or "").strip()
    justification = (request.form.get("justification", "") or "").strip()
    # No justification is REQUIRED at any distance -- from a BU CEO up. Performance calibration starts
    # from a manager-approved rating that has already been through an approval
    # chain, so a large move is a judgement this tier is entitled to make. A note
    # is still offered on every row, still recorded, and still shown up the chain.
    # An HOD's department review (2026-09-30) is the exception: a band they change needs their remark
    # (_pm_calib_apply) -- kept from before when this form leaves it blank.
    if tier == "hod" and not justification and ctx["session"]:
        _prev = db.execute("SELECT justification FROM pm_calibration_adjustments WHERE session_id=? AND subject_id=?",
                           (ctx["session"]["id"], subject_id)).fetchone()
        justification = ((_prev["justification"] or "") if _prev else "").strip()
    subject, err = _pm_calib_apply(db, u, ctx, tier, subject_id, new_band, justification)
    if err:
        return respond(False, err, "error")
    return respond(True, f"{subject['full_name']}'s band set to {new_band}.", "ok")


def _pm_calib_reset(tier, **kw):
    u = current_user()
    db = get_db()
    ctx = _pm_calib_resolve(db, u, tier, **kw)
    session_row = ctx["session"]
    if session_row and session_row["locked_at"]:
        flash("This scope's calibration is locked.", "error")
        return redirect(_pm_calib_redirect(tier, **kw))
    if tier == "hod" and session_row and db.execute(
            "SELECT 1 FROM pm_calibration_adjustments WHERE session_id=? LIMIT 1", (session_row["id"],)).fetchone():
        flash(_HOD_NO_RESET_MSG, "error")   # each person is saved once (_hod_saved_already)
        return redirect(_pm_calib_redirect(tier, **kw))
    _bgc = (_bg_closed(db, "pm", ctx["period"]["id"], ctx["business_group"], ctx["scope_key"])
            if tier == "buceo" else None)
    if _bgc:   # the BG CEO locked it: their decision is final (2026-10-07)
        flash(_bgc, "error")
        return redirect(_pm_calib_redirect(tier, **kw))
    _w = _late_refusal(db, u, tier, "pm", ctx["period"]["id"], ctx) if tier in ("buceo", "bgceo", "group") else None
    if _w:   # closed for everyone, and this scope holds no late pass of theirs (the gate asked with none)
        flash(_w, "error")
        return redirect(_pm_calib_redirect(tier, **kw))
    if ctx.get("read_only"):
        flash(_join_read_only_msg(db, ctx), "error")
        return redirect(_pm_calib_redirect(tier, **kw))
    if ctx.get("join"):   # units calibrated together: every unit's moves go (row 6)
        _ids = _calib_session_ids(ctx)
        if _ids:
            db.execute("DELETE FROM pm_calibration_adjustments WHERE session_id IN (%s)" % ",".join("?" * len(_ids)),
                       _ids)
            db.commit()
            log_activity(db, u["id"], "pm_calibration_reset", f"{tier} scope reset: {ctx['scope_label']}")
        flash("All adjustments cleared — everyone is back to the band they came in with.", "ok")
        return redirect(_pm_calib_redirect(tier, **kw))
    if session_row:
        # a business unit the BG CEO locked on the Talent Box keeps its moves (2026-10-07)
        keep = ("" if tier != "bgceo" else
                " AND subject_id NOT IN (SELECT u.id FROM users u JOIN talent_box_bu_locks l ON l.company=u.company "
                "AND l.business_group=u.business_group WHERE l.period_id=? AND l.business_group=?)")
        if tier == "group":   # the calls the Group Chief locked stay (pm_group_locks, 2026-10-10)
            keep = (" AND subject_id NOT IN (SELECT subject_id FROM pm_group_locks WHERE cycle_id=? AND "
                    "group_id=CAST(? AS INTEGER))")
        db.execute("DELETE FROM pm_calibration_adjustments WHERE session_id=?" + keep,
                   (session_row["id"],) + ((session_row["cycle_id"], session_row["scope_key"]) if keep else ()))
        db.commit()
        log_activity(db, u["id"], "pm_calibration_reset",
                     f"{tier} scope reset: {ctx['scope_key']}")
    flash("All adjustments cleared — everyone is back to the band they came in with"
          + (", except in business units already locked on the Talent Box." if tier == "bgceo" and session_row
             and _tb_bu_locks(db, session_row["cycle_id"], session_row["scope_key"]) else "."), "ok")
    return redirect(_pm_calib_redirect(tier, **kw))


def _pm_calib_lock_breaches(db, tier, ctx, session_row):
    """Performance-axis framework breaches for this scope right now ({} = within tolerance).
    Mirrors _pm_calib_view's distribution -- current bands (this session's moves + any super
    override) vs the BU's PAT-driven reference curve."""
    period = ctx["period"]
    rows = _pm_calibration_rows(db, ctx["population"], period["id"], ctx["overalls"],
                                session_row, _pm_calib_incoming_fn(db, tier, period["id"]),
                                default_ua=tier in _CALIB_AXIS_TIERS, self_id=ctx.get("actor_id"),
                                session_ids=_calib_session_ids(ctx) if ctx.get("join") else None)
    sup = {r["subject_id"]: r["adjusted_band"] for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band FROM pm_calibration_adjustments ca "
        "JOIN pm_calibration_sessions cs ON cs.id = ca.session_id "
        "WHERE cs.cycle_id=? AND cs.tier='super'", (period["id"],)).fetchall()}
    for r in rows:
        if r["user"]["id"] in sup:
            r["current_band"] = sup[r["user"]["id"]]
    dist = pm_band_distribution(rows)
    company = ctx["population"][0]["company"] if ctx["population"] else ""
    curve = pm_curve_for_scope(db, ctx)
    return _calib_over_framework(pm_calibration_target_gaps(dist, curve["dist"]), sum(dist.values()))


def _pot_calib_lock_breaches(db, population, cid, band_fn, session_row, session_ids=None):
    """Potential-axis (360) framework breaches vs 15-70-15 for this scope right now ({} = ok).
    Uses _calibration_rows so it reflects this session's own moves + locked-below inheritance,
    exactly like the calibration view's distribution box."""
    rows = _calibration_rows(db, population, cid, band_fn, session_row, session_ids=session_ids)
    dist = band_distribution_from_rows(rows)
    return _calib_over_framework(calibration_target_gaps(dist, CALIBRATION_TARGET), sum(dist.values()))


def _pm_calib_back(tier, **kw):
    """Where a lock returns: the review journey when it was locked from there (a same-site /review/journey path
    in the form's return_to), else the calibration grid."""
    rt = (request.form.get("return_to") or "").strip()
    if rt.startswith("/review/journey") and "//" not in rt and "\\" not in rt:
        return rt
    return _pm_calib_redirect(tier, **kw)


def _dept_review_complete(db, u, stage):
    """True once every person in this part of the HOD's department review has a band the HOD saved (kept or set),
    nobody is left with no final result, and it isn't submitted or closed -- the state in which the last Save
    finishes the review (Chris, 2026-10-01: "after HOD saved all, the performance review is deemed completed")."""
    d = (_journey_team_overview(db, u, stage, None, "summary") or {}).get("data") or {}
    if not d or d.get("locked") or d.get("closed") or d.get("unassigned"):
        return False
    rows = d.get("rows") or []
    return bool(rows) and not any(not r.get("adjusted") and not r.get("is_self") and not r.get("super_override")
                                  for r in rows)


def _dept_review_after_submit(db, u, st, stage):
    """(the part on offer next or None, the line to say, its chips) after an HOD submits one part of their department
    review -- the offer is a question and a "Go to" chip; the page stays where it is until they say yes.
    Read off each part's own overview, so it says what is true: submitted or not, and what is still open."""
    names = {"calibration": "performance", "calibration_pot": "potential"}
    other = "calibration_pot" if stage == "calibration" else "calibration"
    d = (_journey_team_overview(db, u, stage, None, "summary") or {}).get("data") or {}
    if not d.get("locked"):
        return None, ("Your %s review isn't submitted yet — when you're ready, press Save under the table."
                      % names[stage]), []
    done = "Done — your %s review is submitted to your BU CEO." % names[stage]
    live = {x["key"] for x in _journey_team_live_stages(st)}
    od = ((_journey_team_overview(db, u, other, None, "summary") or {}).get("data") or {}) if other in live else {}
    if other in live and not od.get("locked") and not od.get("closed"):
        n = len(od.get("rows") or [])
        # ASK, never move on its own (Chris, 2026-10-01: "after completion, the agent should ask the user if he/she
        # wishes to continue to the next part, instead of instantly spawn the potential calibration card")
        return other, ("%s Would you like to continue to your %s review now? It's the same %d %s."
                       % (done, names[other], n, "person" if n == 1 else "people")), \
            ["Go to %s review" % names[other].capitalize(), "Not now"]
    return None, done + " That's your whole department review with your BU CEO now — nothing more is needed here.", []


def _utc_disp(ts):
    """A stored UTC timestamp (SQLite datetime('now')) as Malaysia time, '02 Oct 2026, 14:06'; '' if unreadable."""
    s = str(ts or "").strip().replace("T", " ")[:19]
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return (datetime.strptime(s, fmt) + timedelta(hours=8)).strftime("%d %b %Y, %H:%M")
        except ValueError:
            continue
    return ""


def _dept_review_wrapup(db, u, st):
    """The department review's wrap-up card (Chris, 2026-10-02: "once done, it should disable the chat and give a wrap
    up of a summary card"), or None while any part is still open, or outside an HOD's Dept view. Once EVERY part is
    submitted (or closed by the deadline): per part, when it went up, its people, the bands as they went up, and what
    the HOD did -- kept the line manager's band, changed it, or set one where nothing final came up. Read off each
    part's own rows (_journey_team_overview), so the card says what the tables say."""
    if _journey_view_tier(db, u) != "hod":
        return None
    keys = [x["key"] for x in _journey_team_live_stages(st) if x["key"] in ("calibration", "calibration_pot")]
    if not keys:
        return None
    parts, closed_only = [], True
    for key in keys:
        d = (_journey_team_overview(db, u, key, None, "summary") or {}).get("data") or {}
        if not d or not (d.get("locked") or d.get("closed")):
            return None
        pot = key == "calibration_pot"
        order, names = list(d.get("band_order") or []), d.get("label_names") or {}
        rows = [r for r in d.get("rows") or [] if not r.get("is_self")]
        n = {b: 0 for b in order}
        kept, changed, given, as_came = 0, [], [], 0
        for r in rows:
            b = r.get("current_band")
            if b in n:
                n[b] += 1
            if r.get("super_override"):
                continue
            # what came up to the HOD when they saved it ('' = nothing final: UA / Low only by default, not a band to
            # keep) -- never a result that arrived after (2026-10-02)
            came = (r.get("came_in") or None) if r.get("adjusted") else (
                None if (r.get("band_default") or (pot and r.get("pot_final") is False)) else r.get("incoming_band"))
            if not r.get("adjusted"):
                as_came += 1
            elif came and b == came:
                kept += 1
            elif came:
                changed.append({"name": r.get("name"), "from": came, "to": b})
            else:
                given.append({"name": r.get("name"), "to": b})
        total = len(rows)
        _ax, sc = _calib_stage_scope(db, u, key)
        sess = (sc[2].get("session") if sc else None) or {}
        locked = bool(d.get("locked"))
        closed_only = closed_only and not locked
        parts.append({
            "key": key, "name": "Potential" if pot else "Performance", "total": total,
            "status": "Submitted" if locked else "Closed",
            "when": _utc_disp(sess["locked_at"]) if locked and sess and sess["locked_at"] else "",
            "note": "" if locked else (d.get("closed") or ""),
            "bands": [{"code": b, "label": names.get(b, b), "n": n[b],
                       "pct": int(round(n[b] * 100.0 / total)) if total else 0} for b in order],
            "kept": kept, "changed": changed, "given": given, "as_came": as_came})
    # closed by the BG CEO's lock of the unit: nobody calibrates next -- their decision is final (2026-10-07)
    by_bg = any("Your BG CEO has locked" in (pt.get("note") or "") for pt in parts)
    return {"title": "Department Review", "parts": parts,
            "next": ("Your department review is closed: your BG CEO has locked it, and their decision is final."
                     if by_bg else
                     "Your department review is closed. Your BU CEO calibrates next." if closed_only else
                     "Your BU CEO calibrates next — nothing more is needed from you here."),
            "placeholder": "Department review closed." if closed_only else "Department review submitted."}


_CALIB_DONE_SAY = ("Both calibrations are locked and with your BG CEO now, so nothing here can change. If a band needs "
                   "to change, ask your BG CEO.")


_CALIB_DONE_SAY_SELF = ("Both calibrations are locked and on your Talent Box now, so nothing here can change. If a band "
                        "needs to change, move it on your Talent Box (the BG tab).")


def _bu_ceo_is_bg_ceo(db, u):
    """Whether the unit this BU CEO is working on sits in the business group they are BG CEO of (a BG CEO can hold BU CEO
    seats too, 2026-10-22): their BU calibration goes on to their own Talent Box, so nothing says "your BG CEO"."""
    bg = _row_get(u, "bgceo_bg") if u else None
    if not bg:
        return False
    pick = _bu_unit_pick(db, u, buceo_seats(db, u["id"]) or _buceo_col_seat(u))
    return bool(pick) and pick[0] == bg


def _calib_done_say(db, u):
    return _CALIB_DONE_SAY_SELF if _bu_ceo_is_bg_ceo(db, u) else _CALIB_DONE_SAY


def _calib_done(db, u, st):
    """A BU CEO's calibration, every part locked (Chris, 2026-10-06: "once calibration is completed, disable the chat
    for the BUCEO"): {placeholder} -- the chat closes, the tables stay readable; else None (a part still open, or not a
    BU CEO's view). Read off each part's own table, as the department review's wrap-up is."""
    if _journey_view_tier(db, u) != "buceo":
        return None
    keys = [x["key"] for x in _journey_team_live_stages(st) if x["key"] in ("calibration", "calibration_pot")]
    if not keys:
        return None
    closed = False
    for key in keys:
        d = ((_journey_team_overview(db, u, key, None, "summary") or {}).get("data") or {})
        if not d.get("locked"):
            return None
        closed = closed or bool(d.get("closed"))   # locked by the BG CEO's lock of the unit (2026-10-07)
    if _bu_ceo_is_bg_ceo(db, u):
        return {"placeholder": "You've locked this business unit on your Talent Box — calibration is closed." if closed
                else "Calibration locked — it's on your Talent Box now."}
    return {"placeholder": "Your BG CEO has locked this business unit — calibration is closed." if closed
            else "Calibration locked and with your BG CEO."}


def _calib_after_lock(db, u, st, stage):
    """(the calibration on offer next or None, the line to say, its chips) after a BU CEO locks one of their two --
    the department review's after-submit (_dept_review_after_submit), in a calibrator's words."""
    names = {"calibration": "performance", "calibration_pot": "potential"}
    other = "calibration_pot" if stage == "calibration" else "calibration"
    d = (_journey_team_overview(db, u, stage, None, "summary") or {}).get("data") or {}
    if not d.get("locked"):
        return None, ("Your %s calibration isn't locked yet — lock it from the curve when you're ready."
                      % names[stage]), []
    _self = _bu_ceo_is_bg_ceo(db, u)
    done = ("Done — your %s calibration is locked and on your Talent Box (the BG tab)." if _self
            else "Done — your %s calibration is locked and sent up to your BG CEO.") % names[stage]
    live = {x["key"] for x in _journey_team_live_stages(st)}
    od = ((_journey_team_overview(db, u, other, None, "summary") or {}).get("data") or {}) if other in live else {}
    if other in live and od and not od.get("locked"):
        n = len(od.get("rows") or [])
        return other, ("%s Would you like to continue to your %s calibration now? %d %s on the curve."
                       % (done, names[other], n, "person" if n == 1 else "people")), \
            ["Go to %s calibration" % names[other].capitalize(), "Not now"]
    return None, done + (" That's both calibrations locked for this business unit — it's on your Talent Box now." if _self
                         else " That's both calibrations locked for this business unit — your BG CEO takes it from here."), []


def _talent_box_after_lock(db, u):
    """(the line to say, its chips) after a BG CEO locks the Talent Box -- read off the box itself."""
    d = _journey_talent_box_overview(db, u) or {}
    if d.get("group"):   # the Group Chief's (2026-10-13)
        if not d.get("both_locked"):
            return ("Your Talent Box isn't locked yet \u2014 lock it under the box when you're ready.", [])
        return ("Done \u2014 your Talent Box for %s is locked on both axes: your calls on all %d people are with the "
                "super admin, who decides each final band." % (d.get("scope_label"), d.get("bu_people") or 0), [])
    if not d.get("both_locked"):
        if d.get("bu_locked"):   # one business unit locked (2026-10-07)
            say = ("Done \u2014 %s is locked on both axes: its people's bands are final and their talent status is "
                   "recorded, and its BU CEO calibration and HOD reviews are closed. %d of %d business units locked."
                   % (d.get("company_label"), d.get("n_bu_locked") or 0, d.get("n_bu") or 0))
            # the next one still to lock, in the box's order -- the BG CEO never waits on its BU CEO (2026-10-07)
            nxt = next((c for c in d.get("companies") or [] if not c.get("tb_locked")), None)
            if nxt:
                return (say + " Next up: %s." % nxt["label"], ["Show %s" % nxt["label"]])
            return (say, [])
        return ("This business unit isn't locked yet \u2014 lock it under the box when you're ready.", [])
    say = ("Done \u2014 every business unit is locked, so the Talent Box is locked on both axes for %s: performance "
           "and potential are final, and each person's talent status is recorded."
           % (d.get("scope_label") or "your business group"))
    return (say, [])   # no PIP candidates to offer: archived 2026-10-13


def _lock_reply(ok, msg, back, **extra):
    """A submit / lock route's answer. The classic pages get the flash banner and a redirect; the department review's
    Save & submit posts in the background (ajax=1) and gets JSON instead -- no banner (Chris, 2026-10-01: "there is a
    green banner on top appears for split second, remove that. This is the job of the agent to tell the HOD your
    submission is completed")."""
    if request.form.get("ajax") == "1":
        return jsonify(ok=ok, error=None if ok else msg, **extra), (200 if ok else 400)
    flash(msg, "ok" if ok else "error")
    return redirect(back)


def _pm_calib_lock(tier, **kw):
    u = current_user()
    db = get_db()
    ctx = _pm_calib_resolve(db, u, tier, **kw)
    session_row = _pm_calib_get_or_create_session(
        db, ctx["period"]["id"], tier, ctx["scope_key"], ctx["business_group"],
        ctx["scope_label"])
    if session_row["locked_at"]:
        if request.form.get("ajax") == "1":   # a second Save on a submitted review: already done, nothing to say
            return jsonify(ok=True, already=True)
        flash("Already locked.", "error")
        return redirect(_pm_calib_back(tier, **kw))
    # Re-checked here, never trusted from a disabled button -- and enforced in
    # this shared helper rather than only in the Talent Box, so the per-axis
    # page can't be used to lock past a department that hasn't finished.
    pending = pm_calibration_pending_children(
        db, ctx["period"]["id"], tier, ctx["business_group"], ctx["scope_key"])
    if pending:
        names = ", ".join(str(p[0] if tier == "bgceo" else p[1]) for p in pending[:5])
        return _lock_reply(False, f"Can't lock yet — still waiting on: {names}"
                                  f"{' and others' if len(pending) > 5 else ''}.", _pm_calib_back(tier, **kw))
    if tier in ("buceo", "bgceo", "group"):   # closed for everyone: only a late pass for THIS scope gets through (2026-10-31); a Group Chief's follows the BG CEO's dates, and a pass for THIS group (gc:<id>) opens it (2026-11-07)
        _w = _late_refusal(db, u, tier, "pm", ctx["period"]["id"], ctx)
        if _w:
            return _lock_reply(False, _w, _pm_calib_back(tier, **kw))
    if ctx.get("read_only"):   # units calibrated together: only the lead unit's BU CEO locks them (row 6)
        return _lock_reply(False, _join_read_only_msg(db, ctx), _pm_calib_back(tier, **kw))
    if tier == "buceo":   # closed once the BG CEO locks it on the Talent Box (2026-10-07)
        for _m in (ctx["join"]["members"] if ctx.get("join") else [ctx["scope_key"]]):
            _bgc = _bg_closed(db, "pm", ctx["period"]["id"], ctx["business_group"], _m)
            if _bgc:
                return _lock_reply(False, _bgc, _pm_calib_back(tier, **kw))
    if tier == "hod":   # the department review closes once the BU is locked (2026-09-30)
        closed = _hod_review_closed(db, "pm", ctx["period"]["id"], ctx["population"], hod_id=ctx["scope_key"])
        if closed:
            return _lock_reply(False, closed, _pm_calib_back(tier, **kw))
        # ...and nobody goes up UA only by default: the HOD bands them first (Chris, 2026-09-30)
        _un = _dept_review_unassigned(_pm_calib_assist_overview(db, u, ctx, tier, kw)["data"]["rows"], pot=False)
        if _un:
            return _lock_reply(False, _dept_review_unassigned_msg(_un, pot=False), _pm_calib_back(tier, **kw))
    # FRAMEWORK GUARDRAIL (BUCEO business unit): the locked spread must sit within tolerance of the
    # PAT-driven reference curve, unless an override reason is given. Moves stayed free until here;
    # BGCEO/group/super aggregate and are not gated. An HOD's department review has no curve rule
    # (Chris, 2026-09-30: "drop it, and HOD is no longer required for the calibration").
    if tier == "buceo":
        _blk = _pm_calib_lock_breaches(db, tier, ctx, session_row)
        _ovr = "" if calib_lock_strict() else (request.form.get("override_reason") or "").strip()   # strict: no override
        if _blk and not _ovr:
            return _lock_reply(False, _calib_breach_message(_blk, PM_LABEL_NAMES), _pm_calib_back(tier, **kw))
        if _blk and _ovr:
            log_activity(db, u["id"], "pm_calibration_override",
                         f"{tier} {ctx['scope_key']} locked off-framework: {_ovr[:200]}")
    db.execute("UPDATE pm_calibration_sessions SET locked_at=datetime('now'), locked_by=? "
               "WHERE id=?", (u["id"], session_row["id"]))
    if tier == "group":   # the Group Chief calls both axes: the group's potential locks with it (row 7)
        _ps = _get_or_create_calibration_session(db, ctx["period"]["id"], "group", ctx["scope_key"],
                                                 ctx["business_group"], ctx["scope_label"])
        if not _ps["locked_at"]:
            db.execute("UPDATE calibration_sessions SET locked_at=datetime('now'), locked_by=? WHERE id=?",
                       (u["id"], _ps["id"]))
    for _m in (ctx["join"]["members"][1:] if ctx.get("join") else []):   # one lock for every unit calibrated together
        _ms = _pm_calib_get_or_create_session(db, ctx["period"]["id"], tier, _m, ctx["business_group"],
                                              display_company(ctx["business_group"], _m) or _m)
        db.execute("UPDATE pm_calibration_sessions SET locked_at=datetime('now'), locked_by=? WHERE id=?",
                   (u["id"], _ms["id"]))
    _rating_record_refresh(db, ctx["period"]["id"], [p["id"] for p in ctx["population"]],
                           "pm_calib_lock_%s" % tier, u["id"])   # the band after this tier, recorded
    db.commit()
    log_activity(db, u["id"], "pm_calibration_lock", f"{tier} scope locked: {ctx['scope_key']}")
    _late_after_lock(db, u, tier, ctx["business_group"], ctx["scope_key"], ctx)
    return _lock_reply(True, "Department review submitted to your BU CEO." if tier == "hod"
                       else "Calibration locked and submitted upward.", _pm_calib_back(tier, **kw))


# ---------------------------------------------------------------------------
# UNLOCK: one per scope, BOTH axes together, with days once the part's deadline has passed (Chris, 2026-11-07: "one unlock
# which will unlock both performance and potential"; canvas "OneHR Reopen days and HOD pass", boards U1-U3). Scopes: an HOD's
# Department Review ("hod", key = their id), a BU CEO's unit ("buceo", (bg, company)), a calibration group ("bugrp", (bg,
# company, group id)), a BG CEO's business group on the Talent Box ("bgceo", bg), a Group Chief's group ("group", id).
# `_unlock_scope` is THE one writer; the eight old URLs (performance and potential, per tier) and the Group Chief's panel are
# thin callers of it. Past the deadline (any cell of the scope closed for everyone) it also gives the leader a late pass for the
# scope until 23:59 MYT on today + days, through the late-pass writer (_late_check / _late_insert), in the SAME transaction:
# a refused pass leaves everything locked. A tier ABOVE that has locked those people wins, pass or not: refused (_unlock_higher).
# ---------------------------------------------------------------------------
UNLOCK_CELLS = {"hod": ("pm_hod", "pot_hod"), "buceo": ("pm_buceo", "pot_buceo"), "bugrp": ("pm_buceo", "pot_buceo"),
                "bgceo": ("tb_bgceo",), "group": ("tb_bgceo",)}
UNLOCK_TIERS = tuple(UNLOCK_CELLS)


def _unlock_facts(db, tier, key):
    """What one unlock scope is: {tier, key, name, who (the leader's words), leaders (users rows), cell / scope / pass_tier / bg
    (its late pass), locked_pm / locked_pot (when each axis locked, else None), unit (the label of the scope)}, or None when
    the scope isn't there. Reads only."""
    cid, pid = active_cycle_id(db), active_pm_period_id(db)
    if not cid or not pid or tier not in UNLOCK_TIERS:
        return None

    def sess(tbl, cyc, t, k, bg=None):
        r = db.execute("SELECT locked_at FROM %s WHERE cycle_id=? AND tier=? AND scope_key=? AND locked_at IS NOT NULL%s" % (
            tbl, " AND business_group=?" if bg else ""), (cyc, t, k) + ((bg,) if bg else ())).fetchone()
        return r["locked_at"] if r else None
    f = {"tier": tier, "key": key, "cid": cid, "pid": pid}
    if tier == "hod":
        try:
            hid = int(key)
        except (TypeError, ValueError):
            return None
        h = db.execute("SELECT * FROM users WHERE id=?", (hid,)).fetchone()
        if not h:
            return None
        f.update(key=hid, name=h["full_name"], who=h["full_name"], leaders=[h] if not h["left_at"] else [],
                 cell="pm_hod", scope=str(hid), pass_tier="hod", bg=h["business_group"], unit="Department Review",
                 title_of="%s's Department Review" % h["full_name"],
                 locked_pm=sess("pm_calibration_sessions", pid, "hod", str(hid)),
                 locked_pot=sess("calibration_sessions", cid, "hod", str(hid)))
    elif tier == "buceo":
        bg, company = key[0], key[1]
        units = _bu_units_of(db, pid, bg, company)
        lead = units[0]
        h = buceo_holder(db, bg, lead)
        lm = [sess("pm_calibration_sessions", pid, "buceo", k_) for k_ in units]
        lp = [sess("calibration_sessions", cid, "buceo", k_, bg) for k_ in units]
        label = _talent_box_bu_label(bg, lead) or display_company(bg, lead) or lead
        f.update(key=(bg, lead), units=units, name=label, who=(h["full_name"] if h else "the BU CEO"),
                 leaders=[h] if h and not h["left_at"] else [], cell="pm_buceo", scope=lead, pass_tier="buceo", bg=bg,
                 unit=label, title_of="%s's calibration" % label,
                 locked_pm=next((x for x in lm if x), None), locked_pot=next((x for x in lp if x), None))
    elif tier == "bugrp":
        bg, company, gid = key
        g = bu_group(db, gid)
        if not g:
            return None
        gk = BU_GROUP_PREFIX + str(g["id"])
        cal = db.execute("SELECT * FROM users WHERE id=?", (g["calibrator_id"],)).fetchone() if g["calibrator_id"] else None
        f.update(key=(bg, g["company"], g["id"]), name=g["name"], who=(cal["full_name"] if cal else "the calibrator"),
                 leaders=[cal] if cal and not cal["left_at"] else [], cell="pm_buceo", scope=gk, pass_tier="buceo", bg=bg,
                 unit=g["name"], title_of="%s's calibration" % g["name"], gid=g["id"],
                 locked_pm=sess("pm_calibration_sessions", pid, "buceo", gk),
                 locked_pot=sess("calibration_sessions", cid, "buceo", gk, g["business_group"]))
    elif tier == "bgceo":
        bg = key
        ceos = [r for r in db.execute("SELECT * FROM users WHERE bgceo_bg=? AND left_at IS NULL", (bg,))]
        tb = db.execute("SELECT MIN(locked_at) FROM talent_box_bu_locks WHERE (period_id=? OR cycle_id=?) AND business_group=?",
                        (pid, pid, bg)).fetchone()[0]
        f.update(name=display_bg(bg), who=(ceos[0]["full_name"] if ceos else "the BG CEO"), leaders=ceos, cell="tb_bgceo",
                 scope=bg, pass_tier="bgceo", bg=bg, unit=display_bg(bg), title_of="%s Talent Box" % display_bg(bg),
                 locked_pm=sess("pm_calibration_sessions", pid, "bgceo", bg) or tb,
                 locked_pot=sess("calibration_sessions", cid, "bgceo", bg) or tb)
    else:   # a Group Chief's group
        gr = db.execute("SELECT g.*, u.full_name cn FROM pm_calibration_groups g LEFT JOIN users u ON u.id=g.calibrator_id "
                        "WHERE g.id=?", (key,)).fetchone()
        if not gr:
            return None
        cal = db.execute("SELECT * FROM users WHERE id=?", (gr["calibrator_id"],)).fetchone() if gr["calibrator_id"] else None
        lk = gc_group_locks(db, gr["id"])
        f.update(key=gr["id"], name=gr["name"], who=gr["cn"] or "the Group Chief", leaders=[cal] if cal and not cal["left_at"] else [],
                 cell="tb_bgceo", scope=GC_SCOPE_PREFIX + str(gr["id"]), pass_tier="group", bg=None, unit=gr["name"],
                 title_of=gr["name"], locked_pm=lk["pm"], locked_pot=lk["pot"], people=lk["people"], gid=gr["id"])
    f.setdefault("people", 0)
    return f


def _unlock_closed(db, f):
    """Is the scope's part past its deadline for everyone (any cell of it closed)? Then an unlock gives days and a pass."""
    return any(window_state(db, c, f["cid"]) == "closed" for c in UNLOCK_CELLS[f["tier"]])


def _unlock_higher(db, f):
    """What a tier ABOVE has locked over these people, or None: {"msg", "short", "kind", "unit"} (Chris, 2026-11-07: "despite
    with late pass, the order of higher rank supersede applies"). An HOD's: their unit's BU CEO / calibrator, or the BG CEO, on
    either axis. A BU CEO's or calibrator's: the BG CEO on the Talent Box. The BG CEO's and a Group Chief's have none above
    them over the same people (the Executive Chairman locks his leaders themselves, never the people in their boxes, and the
    BG CEO's lock does not close a Group Chief group)."""
    cid, pid = f["cid"], f["pid"]
    if f["tier"] == "hod":
        _sk, _sa = _hod_review_skip_sql(db, f["key"])
        pop = db.execute("SELECT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND "
                         + calibration_population_sql() + _sk, [f["key"]] + _sa).fetchall()
        for ax in ("pm", "pot"):
            hit = _hod_higher_lock_info(db, ax, pid if ax == "pm" else cid, pop)
            if hit:
                who = {"buceo": "its BU CEO", "calibrator": "its calibrator", "bgceo": "its BG CEO"}[hit["kind"]]
                return {"msg": hit["msg"], "kind": hit["kind"], "unit": hit["unit"],
                        "short": "No unlock: %s locked %s" % (who, hit["unit"])}
    elif f["tier"] in ("buceo", "bugrp"):
        scopes = f["units"] if f["tier"] == "buceo" else [f["scope"]]
        for sc in scopes:
            msg = _bg_closed(db, "both", pid, f["bg"], sc)
            if msg:
                unit = f["unit"] if f["tier"] == "bugrp" else (display_company(f["bg"], sc) or sc)
                return {"msg": msg, "kind": "bgceo", "unit": unit, "short": "No unlock: its BG CEO locked %s" % unit}
    return None


def _unlock_scope(db, me, tier, key, days=None, remark=None):
    """THE one writer of an Unlock (every unlock URL, the lock status page, Leaders, the calibration pages and the Group Chief's
    panel call this): the super admin's alone; performance AND potential together; the same side effects the old per-axis
    routes had (a unit's joined units, the Talent Box's unit locks and pins, the Group Chief's one-by-one locks, the rating
    record refreshed); past the deadline `days` (1-14) is required and the leader gets a late pass for the scope in the same
    transaction. Returns (ok, message); on a refusal nothing is changed."""
    if not is_super(me):
        abort(403)
    f = _unlock_facts(db, tier, key)
    if not f:
        abort(404)
    cid, pid = f["cid"], f["pid"]
    if not (f["locked_pm"] or f["locked_pot"] or f.get("people")):
        return False, "%s isn't locked." % f["name"]
    if _late_leader_out(db, f["cell"], cid, f["scope"], f["bg"]):   # once results are released to leaders nothing here reopens (Chris, 2026-11-09)
        return False, "Results are released to leaders for %s, so it can't be unlocked." % f["name"]
    hi = _unlock_higher(db, f)
    if hi:
        _w = hi["short"].replace("No unlock: ", "", 1)
        return False, "%s. The higher rank's lock wins, pass or not: unlock it first." % (_w[:1].upper() + _w[1:])
    closed = _unlock_closed(db, f)
    remark = " ".join((remark or "").split()) or None
    until = days_n = None
    leaders = []
    if closed:
        when = _when_disp(window_dates(db, f["cell"], cid)[1]) or _when_disp(window_dates(db, UNLOCK_CELLS[tier][-1], cid)[1])
        days_n, bad = _days_refusal(days, when)
        if bad:
            return False, bad
        reason, bad = _late_reason_error(remark)
        if bad:
            return False, bad.replace("Give a reason: the person sees it.", "Give your remark: the leader sees it.")
        until = _days_until_myt(days_n)
        leaders = f["leaders"]
        if not leaders:
            return False, "%s has nobody holding the seat, so there is nobody to give the time to. Seat someone first." % f["name"]
    # ---- the writes, in one transaction (nothing below commits until the end)
    if tier == "hod":
        for tbl, cyc in (("pm_calibration_sessions", pid), ("calibration_sessions", cid)):
            db.execute("UPDATE %s SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='hod' AND scope_key=?" % tbl,
                       (cyc, str(f["key"])))
        _sk, _sa = _hod_review_skip_sql(db, f["key"])
        ids = [r[0] for r in db.execute("SELECT id FROM users WHERE hod_id=? AND role!='admin' AND "
                                        + calibration_population_sql() + _sk, [f["key"]] + _sa)]
    elif tier == "buceo":
        for k_ in f["units"]:   # units calibrated together unlock together (row 6)
            db.execute("UPDATE pm_calibration_sessions SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='buceo' "
                       "AND scope_key=?", (pid, k_))
            db.execute("UPDATE calibration_sessions SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='buceo' "
                       "AND business_group=? AND scope_key=?", (cid, f["bg"], k_))
        ph = ",".join("?" * len(f["units"]))
        ids = [r[0] for r in db.execute("SELECT id FROM users WHERE business_group=? AND company IN (%s) AND role!='admin' AND "
                                        % ph + calibration_population_sql(), [f["bg"]] + f["units"])]
    elif tier == "bugrp":
        db.execute("UPDATE pm_calibration_sessions SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='buceo' AND "
                   "scope_key=?", (pid, f["scope"]))
        db.execute("UPDATE calibration_sessions SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='buceo' AND "
                   "business_group=? AND scope_key=?", (cid, f["bg"], f["scope"]))
        ids = [p_["id"] for p_ in _pot_scope_population(db, "buceo", f["key"])]
    elif tier == "bgceo":
        for tbl, cyc in (("pm_calibration_sessions", pid), ("calibration_sessions", cid)):
            db.execute("UPDATE %s SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='bgceo' AND scope_key=?" % tbl,
                       (cyc, f["key"]))
        db.execute("DELETE FROM talent_box_bu_locks WHERE (period_id=? OR cycle_id=?) AND business_group=?", (pid, pid, f["key"]))
        _tb_unpin(db, f["key"], pid)   # ...and what its locks pinned
        # ...and its Talent Box Round 2 (2026-11-15): Round 1 starts again, so the rounds and the Round 1 record of the group's units are
        # cleared with the pins they described (the PAT figure stays as PAT Ref holds it: the super admin's own)
        db.execute("DELETE FROM tb_round1_marks WHERE round_id IN (SELECT id FROM tb_rounds WHERE (period_id=? OR cycle_id=?) AND "
                   "business_group=?)", (pid, pid, f["key"]))
        db.execute("DELETE FROM tb_rounds WHERE (period_id=? OR cycle_id=?) AND business_group=?", (pid, pid, f["key"]))
        ids = [r[0] for r in db.execute("SELECT id FROM users WHERE business_group=? AND role!='admin' AND "
                                        + calibration_population_sql(), (f["key"],))]
    else:   # a Group Chief group: both axes and the people locked one by one
        for tbl in ("pm_calibration_sessions", "calibration_sessions"):
            db.execute("UPDATE %s SET locked_at=NULL, locked_by=NULL WHERE cycle_id=? AND tier='group' AND scope_key=?" % tbl,
                       (pid, str(f["key"])))
        for tbl in ("pm_group_locks", "pot_group_locks"):
            db.execute("DELETE FROM %s WHERE cycle_id=? AND group_id=?" % tbl, (pid, f["key"]))
        ids = [r[0] for r in db.execute("SELECT subject_id FROM pm_calibration_group_members WHERE group_id=?", (f["key"],))]
    _rating_record_refresh(db, pid, ids, "calib_unlock_%s" % tier, me["id"])   # the record falls back with the band (never cascades)
    cyc = active_cycle(db)
    given = []   # [(pass row, leader)]
    held = []
    if closed:
        for L in leaders:
            if _late_held_rows(db, L["id"], f["cell"], cid, scope=[f["scope"]]):
                held.append(L)   # a pass of theirs is still running for this scope: it stands, no second one
                continue
            c, why = _late_check(db, cyc, L, f["cell"], f["scope"], unlocking=True)
            if why:
                db.rollback()   # the pass is refused: nothing unlocks (Chris: unlock and the pass are one step)
                return False, "%s Nothing was unlocked." % why
            row, _kid = _late_insert(db, me, cyc, L, c, until, reason)
            given.append((row, L))
    told = []   # an Unlock inside the window tells the leader too (Chris, 2026-11-09): the same note and email, no extra days
    if not closed:
        _close = _parse_when(window_dates(db, f["cell"], cid)[1] or window_dates(db, UNLOCK_CELLS[tier][-1], cid)[1])
        for L in f["leaders"]:
            row = {"id": None, "cycle_id": cid, "user_id": L["id"], "cell": f["cell"], "subject_id": L["id"],
                   "until_at": _late_utc(_close) if _close else None, "reason": remark or "", "window_open": True,
                   "stage": {"hod": "calibration", "buceo": "calibration", "bugrp": "calibration", "bgceo": "talent_box",
                             "group": "group_calib"}[tier]}
            _late_post_note(db, row, L["full_name"])
            told.append((row, L))
    what = {"hod": "Department Review", "buceo": "BU calibration", "bugrp": "calibration group", "bgceo": "Talent Box",
            "group": "Group Chief group"}[tier]
    axes = " and ".join(w for w, at in (("performance", f["locked_pm"]), ("potential", f["locked_pot"])) if at) or "its locks"
    if tier == "group":
        what_ = ", ".join(w for w, on in (("performance", f["locked_pm"]), ("potential", f["locked_pot"]),
                                          ("%d %s locked one by one" % (f["people"], "person" if f["people"] == 1 else "people"),
                                           f["people"])) if on)
        _leader_log(db, me["id"], "pm_calib_group_unlock", "%s: unlocked (%s)%s" % (
            f["name"], what_, ("; open until %s MYT (%d day%s) for the Group Chief" % (
                _late_when(until.strftime("%Y-%m-%d %H:%M")), days_n, "" if days_n == 1 else "s")) if until else ""))
    else:
        _leader_log(db, me["id"], "calibration_unlock_both", "%s unlocked (%s): %s%s" % (
            what, axes, f["name"], ("; open until %s MYT (%d day%s) for %s" % (
                _late_when(until.strftime("%Y-%m-%d %H:%M")), days_n, "" if days_n == 1 else "s",
                ", ".join(L["full_name"] for L in leaders))) if until else ""))
    db.commit()
    sent = []
    for row, L in given + told:
        sent.append(_late_email(db, row, L))
    msg = "%s is unlocked, performance and potential together." % f["name"]
    if given:
        msg += " %s has until %s MYT to finish it." % (", ".join(L["full_name"] for _r, L in given),
                                                       _late_when(until.strftime("%Y-%m-%d %H:%M")))
        if sent:
            msg += " " + ("Emailed them." if all(x == "Emailed them." for x in sent) else sent[0])
    elif told:
        msg += " %s was told in OneHR and by email." % ", ".join(L["full_name"] for _r, L in told)
        if sent and any(x != "Emailed them." for x in sent):
            msg += " " + next(x for x in sent if x != "Emailed them.")
    elif held:
        msg += " Their late pass is still open."
    elif tier == "group":
        msg += " Their Group Chief can call and lock again."
    else:
        msg += " They can move their people and lock again; what they moved stays."
    return True, msg


def _unlock_box(db, f):
    """The words of OneHR's Unlock box for one scope (canvas U1-U3): title, what happens, what else changes, the days block
    once its deadline has passed, the remark. `blocked` is why there is no Unlock at all (a tier above has locked)."""
    closed = _unlock_closed(db, f)
    tier, who, name = f["tier"], f["who"], f["name"]
    when = ""
    if closed:
        when = _when_disp(window_dates(db, f["cell"], f["cid"])[1]) or _when_disp(
            window_dates(db, UNLOCK_CELLS[tier][-1], f["cid"])[1])
    note = ("%s gets a note in OneHR and an email, with your remark and the date." % who) if closed else \
        ("%s gets a note in OneHR and an email, with your remark." % who)
    if tier == "hod":
        units = sorted({display_company(r_["business_group"], r_["company"]) or r_["company"] for r_ in db.execute(
            "SELECT DISTINCT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND COALESCE(company,'')!=''",
            (f["key"],))})
        above = ("%s's BU CEO sees a stale-data warning." % units[0]) if len(units) == 1 else \
            "Anything built on it shows a stale-data warning."
        box = {"title": "Unlock %s?" % f["title_of"],
               "msg": (("It closed on %s. This opens it for %s alone, performance and potential, so they can move people and "
                        "submit again. What they set stays." % (when, who)) if closed else
                       ("This opens it for %s again, performance and potential, so they can move people and submit again. "
                        "What they set stays." % who)),
               "items": ["Their calls stop counting towards the bands until they submit again.", "Nothing above unlocks. " + above, note],
               "ok": "Unlock Department Review",
               "help": "%d to %d days. It ends when they submit. If their BU CEO or BG CEO locks first, it closes then: the "
                       "higher tier wins." % (REOPEN_DAYS_MIN, REOPEN_DAYS_MAX)}
    elif tier in ("buceo", "bugrp"):
        box = {"title": "Unlock %s?" % f["title_of"],
               "msg": (("It closed on %s. This opens it for %s alone, performance and potential together, so they can move "
                        "their people and lock again. What they moved stays." % (when, who)) if closed else
                       ("This opens it for %s again, performance and potential together, so they can move their people and "
                        "lock again. What they moved stays." % who)),
               "items": ["A lock already made above it stays as it is.", note],
               "ok": "Unlock calibration",
               "help": "%d to %d days. It ends when they lock again. If their BG CEO locks first, it closes then: the higher "
                       "tier wins." % (REOPEN_DAYS_MIN, REOPEN_DAYS_MAX)}
    elif tier == "bgceo":
        box = {"title": "Unlock the %s?" % f["title_of"],
               "msg": (("It closed on %s. Every unit locked on the Talent Box reopens, performance and potential together, so "
                        "%s can move people and lock again. What they moved stays." % (when, who)) if closed else
                       ("Every unit locked on the Talent Box reopens, performance and potential together, so %s can move "
                        "people and lock again. What they moved stays." % who)),
               "items": [note], "ok": "Unlock Talent Box",
               "help": "%d to %d days. It ends when they lock again." % (REOPEN_DAYS_MIN, REOPEN_DAYS_MAX)}
    else:
        box = {"title": "Unlock %s?" % f["title_of"],
               "msg": ("Both axes and everyone the Group Chief locked one by one reopen, so %s can call and lock again. Their "
                       "calls stay, and so do the final bands you decided." % who),
               "items": (["Its time closed on %s (the BG CEO's Talent Box date), so they get a late pass for this group." % when,
                          note] if closed else [note]),
               "ok": "Unlock the group",
               "help": "%d to %d days. It ends when they lock the group again. They get a note in OneHR and an email with your "
                       "remark and the date." % (REOPEN_DAYS_MIN, REOPEN_DAYS_MAX)}
    box["days"] = _days_box(help_=box.pop("help")) if closed else None
    box["remark"] = "Your remark (required): why, for the audit trail. They see it and get an email."
    box["remark_max"] = LATE_REASON_MAX if closed else SUPER_BAND_REMARK_MAX
    hi = _unlock_higher(db, f)
    box["blocked"] = hi["short"] if hi else None
    box["blocked_long"] = hi["msg"] if hi else None
    box["closed"] = closed
    return box


def _unlock_row(db, me, tier, key):
    """What a lock row shows in the super admin's eyes (Lock status, Leaders): {"box", "url", "blocked", "pass"} or None (not the
    super admin, or the scope isn't locked). `pass` = a running late pass for the leader on this scope, 'Late pass until ...'."""
    if not is_super(me):
        return None
    f = _unlock_facts(db, tier, key)
    if not f:
        return None
    running = None
    for L in f["leaders"]:
        lr = _late_held_rows(db, L["id"], f["cell"], f["cid"], scope=[f["scope"]])
        if lr:
            running = "Late pass until " + _late_disp(lr[0]["until_at"])
            break
    locked = bool(f["locked_pm"] or f["locked_pot"] or f.get("people"))
    if not locked:
        return {"box": None, "url": None, "blocked": None, "pass": running, "locked": False}
    if _late_leader_out(db, f["cell"], f["cid"], f["scope"], f["bg"]):   # results are out to leaders: nothing reopens (2026-11-09)
        return {"box": None, "url": None, "blocked": None, "pass": None, "locked": False, "released": True}
    box = _unlock_box(db, f)
    url = {"hod": lambda: url_for("pm_calibration_hod_unlock", hod_id=f["key"]),
           "buceo": lambda: url_for("pm_calibration_buceo_unlock", bg=f["key"][0], company=f["key"][1]),
           "bugrp": lambda: url_for("pm_calibration_buceo_unlock", bg=f["key"][0], company=f["key"][1], grp=f["key"][2]),
           "bgceo": lambda: url_for("pm_calibration_bgceo_unlock", bg=f["key"]),
           "group": lambda: url_for("admin_pm_calibration_groups")}[tier]()
    return {"box": box, "url": url, "blocked": box["blocked"], "pass": running, "locked": True,
            "tier": tier, "group_id": f.get("gid") if tier == "group" else None}


@app.template_global()
def unlock_box(tier, *key):
    """For a template: the Unlock row of one scope ({box, url, blocked, pass, locked}) for the super admin, else None. HOD:
    unlock_box('hod', hod_id); unit: ('buceo', bg, company); calibration group: ('bugrp', bg, company, gid); business group:
    ('bgceo', bg); Group Chief group: ('group', gid)."""
    me = current_user() if has_request_context() else None
    if not me or not is_super(me):
        return None
    try:
        return _unlock_row(get_db(), me, tier, key if len(key) > 1 else key[0])
    except (TypeError, ValueError, IndexError):
        return None


@app.template_global()
def unlock_attrs(box):
    """The data-confirm-* attributes of an Unlock form, from its box (_unlock_box): OneHR's box with the list, the days block
    (past the deadline) and the remark every band action asks (field `remark`, which _super_band_remark_gate reads). The form
    writes its own data-confirm="{{ box.msg }}" beside it (test_admin_standard reads that one in the template)."""
    if not box:
        return Markup("")
    a = ['data-confirm-title="%s"' % _mescape(box["title"]),
         'data-confirm-ok="%s"' % _mescape(box["ok"]),
         'data-confirm-reason="%s"' % _mescape(box["remark"]), 'data-confirm-reason-field="remark"',
         'data-confirm-reason-max="%d"' % box["remark_max"],
         'data-confirm-reason-placeholder="What this changes and why, e.g. agreed at the group calibration meeting"']
    if box["items"]:
        a += ['data-confirm-list="%s"' % _mescape(json.dumps(box["items"])), 'data-confirm-list-label="What else changes"']
    d = box.get("days")
    if d:
        a += ['data-confirm-days="%d"' % d["default"], 'data-confirm-days-label="%s"' % _mescape(d["label"]),
              'data-confirm-days-help="%s"' % _mescape(d["help"])]
    return Markup(" " + " ".join(a))


def _unlock_route(tier, key, back):
    """An old unlock URL's body: read the box's days and remark, run _unlock_scope, flash, go back (an admin page's `next`, else
    `back`)."""
    u = current_user()
    if not is_super(u):
        abort(403)
    db = get_db()
    ok, msg = _unlock_scope(db, u, tier, key, days=request.form.get("days"), remark=request.form.get("remark"))
    flash(msg, "ok" if ok else "error")
    return _admin_next(back)


def _pm_calib_unlock(tier, **kw):
    """The performance routes' Unlock (kept as the old URLs' body): the one writer unlocks BOTH axes (2026-11-07)."""
    if tier == "hod":
        return _unlock_route("hod", kw["hod_id"], _pm_calib_redirect(tier, **kw))
    if tier == "buceo" and kw.get("grp"):
        return _unlock_route("bugrp", (kw["bg"], kw["company"], kw["grp"]), _pm_calib_redirect(tier, **kw))
    if tier == "buceo":
        return _unlock_route("buceo", (kw["bg"], kw["company"]), _pm_calib_redirect(tier, **kw))
    if tier == "group":
        return _unlock_route("group", kw["group_id"], _pm_calib_redirect(tier, **kw))
    return _unlock_route("bgceo", kw["bg"], _pm_calib_redirect(tier, **kw))


# ---- The AI+ calibration assistant (performance axis) -----------------------
# A talk-to-calibrate agent for a HOD or BUCEO, mirroring the AI+ PM/TM/IDP review
# journey (the SETTING stage's shape): a chat + a pinned live distribution widget.
# The model PROPOSES; the server VALIDATES + WRITES through _pm_calib_apply -- the
# SAME path the grid's adjust route uses -- and the Phase-1 framework guardrail
# (_pm_calib_lock_breaches) is the hard gate at lock. Standalone surface, ships OFF
# behind _calib_assist_on(); the grid pages stay the primary surface and it degrades
# to them when the model is off. Potential axis is a follow-up (Chris: performance
# first). Only the tiers the guardrail gates -- hod, buceo -- get the assistant.
CALIB_ASSIST_TIERS = ("hod", "buceo")


def _calib_assist_scope(tier, **kw):
    """The scope kwargs for url_for on a tier's grid/lock routes."""
    if tier == "hod":
        return {"hod_id": kw["hod_id"]}
    if tier == "bgceo":   # the BG CEO's one person page on the Talent Box (2026-10-05) builds this tier's rows
        return {"bg": kw["bg"]}
    out = {"bg": kw["bg"], "company": kw["company"]}
    if kw.get("grp"):   # one of the unit's calibration groups (2026-10-22)
        out["grp"] = kw["grp"]
    return out


def _calib_assist_request_scope():
    """(tier, scope_kwargs) from the request (form or query) -- never stored, echoed
    each turn like the journey's ?stage=. Aborts 404 on a bad/absent scope; the real
    authorisation is _pm_calib_resolve, which aborts 403 if the caller doesn't own it."""
    tier = (request.values.get("tier") or "").strip()
    if tier not in CALIB_ASSIST_TIERS:
        abort(404)
    if tier == "hod":
        hod_id = request.values.get("hod_id", type=int)
        if not hod_id:
            abort(404)
        return tier, {"hod_id": hod_id}
    bg = (request.values.get("bg") or "").strip()
    company = (request.values.get("company") or "").strip()
    if not bg or not company:
        abort(404)
    out = {"bg": bg, "company": company}
    if tier == "buceo" and request.values.get("grp", type=int):   # a calibration group of the unit (2026-10-22)
        out["grp"] = request.values.get("grp", type=int)
    return tier, out


def _calib_chat_history(db, u, cid, tier, scope_key):
    rows = db.execute(
        "SELECT role, content, quick_replies, card, created_at FROM pm_calib_chat "
        "WHERE actor_id=? AND cycle_id=? AND tier=? AND scope_key=? "
        "ORDER BY id DESC LIMIT ?", (u["id"], cid, tier, scope_key, REVIEW_CHAT_MAX)).fetchall()
    out = []
    for r in reversed(rows):
        m = {"role": r["role"], "content": r["content"], "created_at": r["created_at"]}   # UTC; the move check reads it (4-06)
        if r["quick_replies"]:
            try:
                m["quick_replies"] = json.loads(r["quick_replies"])
            except (ValueError, TypeError):
                pass
        if r["card"]:
            try:
                m["card"] = json.loads(r["card"])
            except (ValueError, TypeError):
                pass
        out.append(m)
    return out


def _calib_resolve_subject(ctx, val):
    """A model-proposed subject (an id or a name) -> a person in THIS scope's
    population, or (None, error). Never trusts an id outside the population, so the
    model can't reach another calibrator's people."""
    if val is None or str(val).strip() == "":
        return None, "which person do you mean?"
    s = str(val).strip()
    pop = ctx["population"]
    if s.isdigit():
        p = next((p for p in pop if p["id"] == int(s)), None)
        return (p, None) if p else (None, "that person isn't in this scope")
    low = s.lower()
    exact = [p for p in pop if (p["full_name"] or "").lower() == low]
    if len(exact) == 1:
        return exact[0], None
    partial = [p for p in pop if low in (p["full_name"] or "").lower()]
    if len(partial) == 1:
        return partial[0], None
    if not partial:
        return None, "no one by that name is in this scope"
    return None, "more than one person matches -- use their full name"


def _pm_calib_assist_rows(db, ctx, tier):
    """Calibration rows for this scope with super-overrides applied -- exactly as
    _pm_calib_view and _pm_calib_lock_breaches build them, so the widget, the
    guardrail and the grid all count the same spread."""
    period = ctx["period"]
    rows = _pm_calibration_rows(db, ctx["population"], period["id"], ctx["overalls"],
                                ctx["session"], ctx.get("incoming_fn") or _pm_calib_incoming_fn(db, tier, period["id"]),
                                default_ua=tier in _CALIB_AXIS_TIERS, self_id=ctx.get("actor_id"),
                                session_ids=_calib_session_ids(ctx))
    sup = {r["subject_id"]: r["adjusted_band"] for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band FROM pm_calibration_adjustments ca "
        "JOIN pm_calibration_sessions cs ON cs.id = ca.session_id "
        "WHERE cs.cycle_id=? AND cs.tier='super'", (period["id"],)).fetchall()}
    for r in rows:
        if r["user"]["id"] in sup:
            r["current_band"] = sup[r["user"]["id"]]
            r["super_override"] = sup[r["user"]["id"]]
    # A STABLE order (2026-09-29): the grid sorts weakest band first, so every move re-sorted the list -- the row just
    # changed jumped away, and the card's person index pointed at someone else. By name here: the curve's roster, the
    # person-by-person card and the navigator all read this order.
    rows.sort(key=lambda r: ((r["user"]["full_name"] or "").lower(), r["user"]["id"]))
    if tier == "hod":   # a department review: who still needs the HOD first, the decided last (2026-09-30)
        rows.sort(key=lambda r: _dept_review_rank(r["adjusted"], r.get("band_default"), bool(r.get("super_override"))
                                                  or r["user"]["id"] == ctx.get("actor_id")))
    return rows


def _pm_calib_chain(r, tier, selfs, trail):
    """One row's band journey up to the viewing seat -- the columns of the calibration page (Self, LM, HOD, BU CEO;
    pm_calibration_tier.html's chain): Self = their own submitted results, LM = the manager-approved band, HOD = the HOD's
    locked band (a BU CEO viewing), kept or moved; None = the HOD recorded nothing -- then THIS tier's band, the one they
    can change."""
    uid = r["user"]["id"]
    sv = selfs.get(uid) if selfs else None
    out = [{"tier": "Self", "band": sv["label"] if sv else None},
           {"tier": "LM", "band": r["overall"]["label"] if r.get("overall") else None}]
    if tier == "buceo":
        h = next((t for t in trail or [] if t.get("tier") == "hod"), None)
        # a department review can keep a band and add a remark (2026-09-30): that row is "kept", not a move
        moved = bool(h) and (h.get("band") or "") != (h.get("from") or "")
        lm_now = r["overall"]["label"] if r.get("overall") else None
        # the LM's band came in after the HOD set theirs, and disagrees (2026-10-02)
        late = lm_now if h and lm_now and lm_now != (h.get("seen") or "") and lm_now != h.get("band") else None
        # from which band the HOD moved it (Chris, 2026-10-07: "the movement for both dept review and buceo calibration")
        hfrom = (h.get("from") or None) if moved else None
        out.append(dict({"tier": "HOD", "band": h["band"] if h else None, "moved": moved,
                         "note": ((h.get("note") or "").strip()[:300] if h else "")},
                        **dict(({"late": late} if late else {}), **({"from": hfrom} if hfrom else {}))))
    out.append({"tier": {"hod": "HOD", "buceo": "BU CEO"}.get(tier, tier.upper()), "band": r.get("current_band"),
                "own": True, "default": bool(r.get("band_default")),
                # moved = a band different from what came in (set back to it is no move, whatever the row says)
                "moved": bool(r.get("adjusted")) and r.get("current_band") != r.get("incoming_band")})
    return out


def _bu_co_calls(db, axis, cycle_id, people, gid):
    """{subject_id: {mine (this calibrator's weight), others: [{who, tag, weight, band, locked}]}} of the people this
    calibrator (`gid`) shares with others (2026-10-26): what the calibrator sees on the row's second line. A band shows
    as it stands; it counts in the BU level once that calibrator locks. Only people with several calibrators."""
    out = {}
    for p in people or ():
        gs = bu_groups_of_person(db, p)
        if len(gs) < 2 or not any(g["id"] == gid for g in gs):
            continue
        parts = bu_cal_parts(db, axis, cycle_id, p, gs)
        out[p["id"]] = {"mine": next((x["weight"] for x in parts if x["gid"] == gid), 0),
                        "others": [{"who": x["who"], "tag": x["tag"], "weight": x["weight"], "band": x["band"],
                                    "locked": x["locked"]} for x in parts if x["gid"] != gid]}
    return out


def _bu_shared_calls(db, axis, cycle_id, people):
    """{subject_id: their calibrators' parts as they stand (locked or not; bu_cal_parts)} of the grouped people: what
    their BU CEO reads beside each row (2026-10-22; several calibrators, 2026-10-26)."""
    return {p["id"]: bu_cal_parts(db, axis, cycle_id, p) for p in people or () if bu_groups_of_person(db, p)}


def _bu_shared_row(db, axis, p, calls, order, came_in=None):
    """A grouped person's row on their BU CEO's roster: read only (2026-10-26: a BU CEO shares a call only as one of
    the calibrators), and the band the calibrators give as it stands: theirs for one, weighted for several (a
    calibrator who hasn't moved them counts the band that came in)."""
    parts = calls.get(p["id"]) or []
    if len(parts) > 1:
        band = bu_blend_n([(x["band"] or came_in, x["weight"]) for x in parts], order)
    else:
        band = parts[0]["band"] if parts else None
    return {"split": 100, "movable": False, "cal_band": band, "ceo_band": None, "bu_level": band}


def _pm_calib_others(db, ctx, tier):
    """The BU CEO's read-only rows (Chris's pick 4A, 2026-10-22): the unit's people whose departments a calibration
    group holds, each with their band's journey up to the HOD and who calibrates them. Never on the curve, never
    moved here."""
    op = list(ctx.get("others") or []) if tier == "buceo" else []
    if not op:
        return []
    pid = ctx["period"]["id"]
    octx = dict(ctx, population=op, session=None, member_sessions=None,
                overalls=pm_final_overalls(db, pid, [p["id"] for p in op]))
    rows = _pm_calib_assist_rows(db, octx, tier)
    ids = [r["user"]["id"] for r in rows]
    try:
        selfs = pm_self_overalls(db, pid, ids, provisional=tier in _CALIB_AXIS_TIERS) if ids else {}
    except Exception as e:
        app.logger.warning("calibration self overalls skipped: %s", e)
        selfs = {}
    trails = pm_calibration_trails(db, [r["user"] for r in rows], pid, below=tier) if ids else {}
    calls = _bu_shared_calls(db, "pm", pid, [r["user"] for r in rows])
    by = {}
    out = []
    for r in rows:
        gs_ = bu_groups_of_person(db, r["user"])   # every calibrator of theirs, one tag (2026-10-26)
        g = tuple(x_["id"] for x_ in gs_) or None
        if g and g not in by:
            by[g] = bu_groups_by(db, gs_)
        out.append(dict({"id": r["user"]["id"], "name": r["user"]["full_name"], "other": True,
                         "department": _row_get(r["user"], "department"), "job_title": _row_get(r["user"], "job_title"),
                         "job_grade": _row_get(r["user"], "job_grade"), "unit": _row_get(r["user"], "company"),
                         "incoming_band": r.get("incoming_band"),
                         "chain": _pm_calib_chain(r, tier, selfs, trails.get(r["user"]["id"], []))[:-1]},
                        **(by.get(g) if g else {}), **_bu_shared_row(db, "pm", r["user"], calls, PM_BAND_ORDER,
                                                                     r.get("incoming_band"))))
    return out


def _pm_calib_assist_overview(db, u, ctx, tier, kw):
    """The pinned live widget: the distribution vs the BU's PAT curve (per-band count
    / target / gap) + the roster (each person's current band, what they inherited,
    whether it was moved, and the Why-evidence count). Rebuilt every turn from server
    state, never a snapshot -- so a move through the chat shows up immediately."""
    rows = _pm_calib_assist_rows(db, ctx, tier)
    dist = pm_band_distribution(rows)
    company = ctx["population"][0]["company"] if ctx["population"] else ""
    curve = pm_curve_for_scope(db, ctx)
    gaps = pm_calibration_target_gaps(dist, curve["dist"])
    total = sum(dist.values())
    breaches = _calib_over_framework(gaps, total)
    tol = calib_tolerance(total)
    locked = bool(ctx["session"] and ctx["session"]["locked_at"])
    # the BG CEO's lock of the unit closes the BU CEO's calibration: it reads as locked, and says why (2026-10-07)
    bg_closed = (next((x for x in (_bg_closed(db, "pm", ctx["period"]["id"], ctx["business_group"], m_)
                                   for m_ in _ctx_units(ctx)) if x), None)
                 if tier == "buceo" and not locked else None)
    if bg_closed:
        locked = True
    # Person by person FIRST (Chris, 2026-09-28): each row carries what the person card shows -- their approved
    # score and their own, who they are, and the lower tiers' moves up to (never above) this seat. All batched.
    ids = [r["user"]["id"] for r in rows]
    try:   # one malformed line (the known Mech-B NULL-threshold scoring error) must not blank the whole card
        selfs = pm_self_overalls(db, ctx["period"]["id"], ids, provisional=tier in _CALIB_AXIS_TIERS) if ids else {}
    except Exception as e:
        app.logger.warning("calibration self overalls skipped: %s", e)
        selfs = {}
    trails = pm_calibration_trails(db, [r["user"] for r in rows], ctx["period"]["id"], below=tier) if ids else {}
    # who the HOD is, to name them beside their remark on the person's page (2026-10-05)
    _hids = sorted({h for h in (_row_get(r["user"], "hod_id") for r in rows) if h})
    hod_names = {x["id"]: x["full_name"] for x in db.execute(
        "SELECT id, full_name FROM users WHERE id IN (%s)" % ",".join("?" * len(_hids)), _hids)} if _hids else {}
    # this tier's own remark on each person (the department review's Remark column, 2026-09-30)
    _sids = _calib_session_ids(ctx)
    own = {a["subject_id"]: (a["justification"] or "") for a in db.execute(
        "SELECT subject_id, justification FROM pm_calibration_adjustments WHERE session_id IN (%s)"
        % ",".join("?" * len(_sids)), _sids).fetchall()} if _sids else {}
    review = tier == "hod"
    if review:   # a department review has no curve rule (Chris, 2026-09-30)
        breaches = {}
    newly = newly_confirmed_ids(db, ctx["period"]["id"])   # added with a Confirmation rating (2026-10-22)
    behalf_lm = lm_behalf_ids(db, ctx["period"]["id"])   # their line manager assessed them on their behalf (2026-10-26)
    nodata = nodata_map(db, ctx["period"]["id"], ids)   # no KPI lines / no 360 (2026-11-02)
    transfer = pm_split_tags(db, ctx["period"]["id"], ids, {r["user"]["id"]: r["overall"] for r in rows})   # Transferred (2026-11-03)
    people = [{
        "id": r["user"]["id"], "name": r["user"]["full_name"],
        "newly": r["user"]["id"] in newly, "behalf_lm": r["user"]["id"] in behalf_lm,
        **_nd_kw(nodata, r["user"]["id"]), **_tr_kw(transfer, r["user"]["id"]),
        "current_band": r["current_band"], "incoming_band": r["incoming_band"],
        "adjusted": r["adjusted"], "pinned": bool(r.get("pinned")),
        "overall": (r["overall"]["label"] if r["overall"] else None),
        "score": (_pm_fig(r["overall"]["value"]) if r["overall"] and r["overall"].get("value") is not None else None),
        "mechanism": (r["overall"] or {}).get("mechanism"),
        "self_score": (_pm_fig(selfs[r["user"]["id"]]["value"]) if selfs.get(r["user"]["id"]) else None),
        "self_band": (selfs.get(r["user"]["id"]) or {}).get("label"),
        "department": _row_get(r["user"], "department"), "job_title": _row_get(r["user"], "job_title"),
        "job_grade": _row_get(r["user"], "job_grade"), "unit": _row_get(r["user"], "company"),
        # the roster columns the filter line can narrow by (Cost centre, Branch; CALIB_FILTERS, 2026-10-30)
        **calib_roster_fields(r["user"]),
        # the lower tiers' moves, each remark whole: the person's page shows it with its owner (2026-10-05)
        "trail": [dict({"label": t["label"], "from": t["from"], "band": t["band"], "note": (t["note"] or "").strip(),
                        "tier": t.get("tier"),
                        "by": (hod_names.get(_row_get(r["user"], "hod_id")) or "") if t.get("tier") == "hod"
                        else (t.get("by") or "") if t.get("cal") else ""},
                       **{k_: t[k_] for k_ in ("cal", "avg", "weight", "waiting") if k_ in t})
                  for t in trails.get(r["user"]["id"], [])],
        "is_self": r["user"]["id"] == u["id"],
        "finalised": r["finalised"], "n_why": r["n_why"], "why_flag": r["why_flag"],
        # every result submitted, the line manager yet to approve: the HOD / BU CEO still sees them (2026-09-30)
        "awaiting_lm": (not r["finalised"]) and bool(selfs.get(r["user"]["id"])),
        "band_default": bool(r.get("band_default")), "came_in": r.get("came_in"), "late": r.get("late"),
        "super_override": r.get("super_override"),
        # The band's journey up to this seat, as the calibration page's columns (Self -> LM -> HOD -> this tier)
        "chain": _pm_calib_chain(r, tier, selfs, trails.get(r["user"]["id"], [])),
        "own_note": (own.get(r["user"]["id"]) or "").strip(),
        "on_curve": bool(r.get("current_band")),   # pm_band_distribution's rule: the card's filter counts it the same way
    } for r in rows]
    if ctx.get("grp"):   # a calibration group's own column: BU level, its calibrator's, never "BU CEO" (2026-10-22)
        _co = _bu_co_calls(db, "pm", ctx["period"]["id"], [r["user"] for r in rows], ctx["grp"]["id"])
        for p_ in people:
            p_["chain"][-1]["tier"] = "BU level"
            if p_["id"] in _co:   # shared with other calibrators (2026-10-26): their weights and bands beside this one
                p_["co"] = dict(_co[p_["id"]], level=bu_blend_n(
                    [(p_["current_band"], _co[p_["id"]]["mine"])] + [(o["band"] or p_.get("came_in") or p_.get("current_band"), o["weight"])
                                                                     for o in _co[p_["id"]]["others"] if o["locked"]],
                    PM_BAND_ORDER))
    # What the Lock needs before it is clicked: a lower tier still to lock (BG CEO), and the framework check. A BU CEO
    # waits on no HOD (2026-09-30); the departments still open are named, because the lock closes their reviews.
    pending = (pm_calibration_pending_children(db, ctx["period"]["id"], tier, ctx["business_group"], ctx["scope_key"])
               if tier in ("buceo", "bgceo") else [])
    _phods = {_row_get(p_, "hod_id") for p_ in ctx["population"]}   # this scope's own HODs (a group's, 2026-10-22)
    hod_open = ([n for m_ in _ctx_units(ctx) for _i, n in pm_hod_reviews_open(db, ctx["period"]["id"],
                                                                               ctx["business_group"], m_)
                 if _i in _phods]
                if tier == "buceo" else [])
    return {"type": "calib_overview", "data": {
        "review": review, "hod_open": hod_open, "join": _join_payload(ctx, curve),
        "due": _window_due_disp(db, "pm_hod", ctx["period"]["id"]) if review else "",
        "closed": ((_hod_review_closed(db, "pm", ctx["period"]["id"], ctx["population"], hod_id=ctx["scope_key"]) or "") if review
                   else (bg_closed or "")),
        "pending": [(p[0] if tier == "bgceo" else p[1]) for p in pending] if pending else [],
        "breach_message": _calib_breach_message(breaches, PM_LABEL_NAMES) if breaches else "",
        "n_default": sum(1 for r in rows if r.get("band_default")),
        "unassigned": _dept_review_unassigned(people, pot=False) if review else [],
        "lock_strict": calib_lock_strict(),
        "distribution": dist, "target": curve["dist"], "gaps": gaps,
        "curve": {"label": curve["label"], "entered": curve["entered"], "pct": curve["pct"],
                  "scope": curve.get("scope"), "note": curve.get("note") if curve.get("joined") else None},
        "band_order": PM_BAND_ORDER, "label_names": PM_LABEL_NAMES,
        "tolerance": tol, "breaches": breaches, "total": total,
        "locked": locked, "scope_label": ctx["scope_label"], "tier": tier,
        "rows": people,
        "others": _pm_calib_others(db, ctx, tier),   # grouped people, read only (4A, 2026-10-22)
        "group": bool(ctx.get("grp")),
        "lock_url": url_for("pm_calibration_%s_lock" % tier, **_calib_assist_scope(tier, **kw)),
        "mid_year": cycle_is_mid_year(db, ctx["period"]["id"]),   # the review is the last step (2026-10-12)
        "tol_rule": get_calib_rule(),   # a department's tolerance on the BU CEO's filtered curve (2026-10-13)
        # the department pill row, only where the super admin switched it on for this unit (2026-10-17); the JG row under it,
        # with the business group's grouping (2026-10-21); the filter line's chips, in registry order (2026-10-30): the
        # client narrows the rows above by each. A calibrator the super admin gave filters of its own reads those
        # (2026-11-02, calib_card_filters)
        **(calib_card_filters(db, ctx, ctx["business_group"]) if tier == "buceo"
           else {"dept_filter": False, "jg_filter": None, "filters": []}),
    }}


# THE DEPARTMENT REVIEW's prompt (Chris, 2026-09-30: "HOD is no longer required for the calibration, they just need to
# do the department review (similar like line manager role)"). No curve, no spread, no fit: the HOD reads each person's
# band journey and the AI's read, changes a band where they see it differently -- with their own remark, which the
# BU CEO reads -- and submits. The server enforces the remark (_hod_remark_needed) and refuses the curve tools.
_DEPT_REVIEW_RULES = (
    "A DEPARTMENT REVIEW, not a calibration: there is NO curve, NO expected spread and nothing to fit -- never talk "
    "about a distribution, a spread, a curve, a framework or moving people to fit one. The Department summary in the "
    "chat shows, per person, how their band came up (their own view, their line manager's) and the band they sit at "
    "now; Review on a row opens that person's page beside the folded summary: their AI summary, their KPI table, and "
    "the HOD's band and Remarks box, where 'Write with AI' drafts the remark with you in the chat (write, elaborate, refine or clarify), never adding a figure or name they did not give; the page's Save (after a "
    "confirm) saves that band and remark and returns to the summary -- once every person is saved, that last Save "
    "also FINISHES the review and sends it to their BU CEO (no second step). On the summary the HOD ticks "
    "the people whose line manager's band they agree with and presses Save at the bottom right: Save keeps those "
    "bands AND submits the department review to their BU CEO (it can't be edited after). Save is refused while anyone "
    "has no final result (UA only by default on performance, no band on potential): the HOD sets each of their bands "
    "on their page first -- UA on purpose is fine, with a remark. Help the HOD decide where "
    "they see a band differently, from the "
    "evidence. A band CHANGE needs the HOD's OWN remark -- it is what their BU CEO reads: if they have not given one, "
    "ASK for it, never make one up. When they name a person, a band AND a reason in the same message -- even a short "
    "one -- put it on their page AT ONCE with move_band, using their reason as they gave it; don't ask follow-up "
    "questions first (the remark is theirs to word, not yours to improve). move_band FILLS their page (band and remark, "
    "NOT saved): the HOD saves it with the page's Save, which asks them to confirm -- only when their message asks you "
    "to save or submit it does it save. Never say it is saved when the result says held. Keeping a band needs no "
    "remark (one is welcome). Someone "
    "whose rating isn't "
    "finalised shows UA by default; the HOD may set their band. Nobody reviews their OWN band. SAVED IS FINAL: once a "
    "person is saved (on their page, by a tick, or with move_band) their band and remark can't be changed -- not on "
    "their page, not by you (move_band refuses); if the HOD asks, say so plainly. Their BU CEO can still change any "
    "band after the review is submitted.")
# ...and at Mid-Year the review is the last step (Chris, 2026-10-12: "mid year will only have self, LM, and HOD")
_DEPT_REVIEW_MY = (
    " THIS IS A MID-YEAR REVIEW, and Mid-Year ends with it: there is no BU CEO or BG CEO step after the HOD. "
    "Submitting makes the department's bands FINAL -- this overrides every mention of the BU CEO above: never say "
    "the review goes to a BU CEO or that anyone can change a band after it.")


def _dept_review_system(db, u, ctx, journey=False, axis="pm", sc=None):
    who = welcome_identity(u).get("first_name") or "there"
    if axis == "pm":
        rows = _pm_calib_assist_rows(db, ctx, "hod")
        roster = [{"name": r["user"]["full_name"], "band": r["current_band"], "came_in_as": r["incoming_band"],
                   "changed": bool(r["adjusted"]) and r["current_band"] != (r.get("came_in") or r["incoming_band"]),
                   "lm_band_arrived_after_you_set_it": (r.get("late") or {}).get("now"),
                   "finalised": r["finalised"], "cited_evidence": r["n_why"]} for r in rows]
        closed = _hod_review_closed(db, "pm", ctx["period"]["id"], ctx["population"], hod_id=ctx["scope_key"])
        kind, bands = "performance", "Unacceptable / Below Expectation / Meets Expectation / Above Expectation / Outstanding"
        move = 'move_band{subject, band, justification}'
    else:
        ov = _pot_calib_overview(db, u, sc)
        roster = [{"name": r["name"], "band": None if r.get("band_default") else r["current_band"],
                   "came_in_as": r["incoming_band"],
                   "changed": bool(r["adjusted"]) and r["current_band"] != (r.get("came_in") or r["incoming_band"]),
                   "lm_band_arrived_after_you_set_it": (r.get("late") or {}).get("now"),
                   "potential_score": r["score"] if r.get("pot_final", True) else None, "out_of": r["score_max"],
                   "enough_feedback": r["valid"], "competency_approved": r.get("comp_status") == "reviewed",
                   "includes_competency": r.get("basis") == "combined",
                   "not_finalised_low_by_default": bool(r.get("band_default"))}
                  for r in ov["rows"]]
        closed = ov.get("closed")
        kind, bands = "potential", "Low / Mid / High"
        move = 'move_band{subject, band, justification} (band = Low / Mid / High)'
    parts = [
        "You are OneHR's department-review assistant, helping %s review the %s bands of their department (%s). "
        "Talk like a sharp, warm colleague -- specific, one thing at a time, a sentence or two per reply."
        % (who, kind, ctx["scope_label"]),
        "VOICE: never repeat a sentence; react to what they actually said; vary your openers; don't gush. NEVER expose "
        "internals -- no tool names, no ids, no talk of how bands are stored. Refer to each person by NAME and each "
        "band by its full name (%s)." % bands,
        "STAGE -- the %s DEPARTMENT REVIEW of %s." % (kind.upper(), ctx["scope_label"]),
        _DEPT_REVIEW_RULES + (_DEPT_REVIEW_MY if cycle_is_mid_year(
            db, ctx["period"]["id"] if axis == "pm" else ctx["cycle_id"]) else ""),
        "The people in the department (band = where they sit now; came_in_as = the band they came in at"
        + ("; potential_score = their 360 and the competency their line manager approved, each weighted by the admin "
           "split for their grade and added, out of out_of (the 360's maximum plus the competency's) -- shown only "
           "when BOTH are in (enough 360 raters AND the competency approved); "
           "not_finalised_low_by_default=true means one is missing, so nothing final came up: they count as Low only "
           "by default and the HOD must set their band on their page (with a remark) before the review can finish"
           if axis != "pm" else "") + "):\n"
        + json.dumps(roster, ensure_ascii=False),
        'TOOLS for "action": explain_person{subject} (their evidence and band history, so you can discuss them); '
        'open_person{subject} (opens that person\'s page in the card, just below your reply -- call it WHENEVER you '
        'open someone\'s page or they say yes to your offer to; never say a page is open without it); '
        + move + ' (record a band -- ALWAYS the HOD\'s OWN reason when the band changes; if they have not given one, '
        'ASK -- never make one up); prepare_lock{} (brings the department summary, with its Save button); '
        'search_kb{query}. If nothing is left to do, say so warmly and set action null.',
        "THE FINISH: when they're done, call prepare_lock{} -- the department summary comes down with its Save button, which "
        "sends the review to their BU CEO. NEVER claim you have submitted it; ONLY their Save does.",
    ]
    if kind == "potential":
        parts.append("360 ANONYMITY (never break it): never say who rated them, how many people said what, or which "
                     "relationship thought what; never quote a comment; talk in themes only.")
    _ln = _late_agent_note(db, u, "calibration" if axis == "pm" else "calibration_pot") if not closed else ""   # an HOD's more time (2026-11-07)
    if _ln:
        parts.append(_ln)
    if closed:
        parts.append("NOTE: " + closed + " Do not move anyone -- explain warmly and answer questions about it.")
    elif ctx["session"] and ctx["session"]["locked_at"]:
        parts.append("NOTE: this department review is already SUBMITTED. Do not move anyone -- explain warmly and "
                     "answer questions about it.")
    if journey:   # inside the team journey: its framing, voice and scope guard already lead the prompt
        return "\n\n".join(parts[2:])
    parts.append(_AGENT_SCOPE_GUARD)
    return "\n\n".join(parts)


def _bu_group_prompt_note(db, ctx, tier):
    """What a BU-level agent is told about calibration panels (2026-10-22; several calibrators, 2026-10-26), or None: a
    calibrator that they calibrate their people alone or with others by weight, on the panel's curve, with their own
    lock; a BU CEO who the greyed rows are."""
    if tier != "buceo":
        return None
    g = ctx.get("grp")
    if g:
        bg_ = g["business_group"]
        p_ = bu_panels_all(db).get(g.get("panel_id")) or {}
        others = [x for x in p_.get("groups", []) if x["id"] != g["id"]]
        pop = list(ctx.get("population") or [])
        shared = [x for x in pop if bu_shared(db, x)]
        return ("THIS IS A CALIBRATION PANEL: %s, with people in %s. Group People made this person one of its "
                "calibrators, so they calibrate ONLY the people given to them at BU level; each unit's BU CEO "
                "calibrates the rest of their unit. The curve is %s's PAT curve applied to these people alone, under the "
                "same tolerance rule, and this lock is their own. %s The BG CEO decides on the Talent Box. Call them a "
                "calibrator of the panel, never the BU CEO." % (
                    p_.get("name") or g["name"], ", ".join(display_company(bg_, c_) or c_ for c_ in g["units"]),
                    display_company(bg_, g["company"]) or g["company"],
                    ("%d of these people are shared with other calibrators (%s): each gives a band, and the BU-level "
                     "band is their bands weighted by the panel's shares, rounded, exactly halfway the lower band; a "
                     "calibrator's band counts once they lock. The roster's second line shows the others' bands."
                     % (len(shared), ", ".join(sorted({bu_groups_by(db, [x]).get("by_title", "").split(" · calibrated by ")
                                                       [-1] for x in others}))))
                    if shared and others else "Their BU CEOs read these bands."))
    if ctx.get("others"):
        names = sorted({bu_groups_by(db, bu_groups_of_person(db, p_)).get("by_title", "") for p_ in ctx["others"]} - {""})
        return ("Some people of this unit sit in calibration panels, calibrated by someone else at BU level: %s. Those "
                "%d people show on the roster below their own, greyed. They are NOT on this curve and this lock doesn't "
                "cover them; if asked, say who calibrates them. This person reads their bands only and can't move them."
                % ("; ".join(names), len(ctx["others"])))
    return None


def _pm_calib_assist_system(db, u, ctx, tier, journey=False):
    who = welcome_identity(u).get("first_name") or "there"
    if tier == "hod":   # an HOD's department review has no curve (Chris, 2026-09-30)
        return _dept_review_system(db, u, ctx, journey=journey)
    rows = _pm_calib_assist_rows(db, ctx, tier)
    dist = pm_band_distribution(rows)
    company = ctx["population"][0]["company"] if ctx["population"] else ""
    curve = pm_curve_for_scope(db, ctx)
    gaps = pm_calibration_target_gaps(dist, curve["dist"])
    total = sum(dist.values())
    breaches = _calib_over_framework(gaps, total)
    tol = calib_tolerance(total)
    roster = [{"name": r["user"]["full_name"], "band": r["current_band"],
               "inherited": r["incoming_band"], "moved": r["adjusted"],
               "cited": r["n_why"], "flag": r["why_flag"],
               "finalised": r["finalised"]} for r in rows]
    tier_word = "department" if tier == "hod" else "business unit"
    framework = {PM_LABEL_NAMES[b]: {"have": dist[b], "target_pct": curve["dist"][b],
                                     "gap": gaps[b]} for b in PM_BAND_ORDER}
    parts = [
        "You are OneHR's performance-calibration assistant, helping %s calibrate the "
        "%s (%s). Talk like a sharp, warm colleague -- specific, one thing at a time, a "
        "sentence or two per reply." % (who, tier_word, ctx["scope_label"]),
        "VOICE: never repeat a sentence; react to what they actually said; vary your "
        "openers; don't gush. NEVER expose internals -- no tool names, no ids, no talk of "
        "how bands are stored. Refer to each person by NAME and each band by its full name "
        "(Unacceptable / Below Expectation / Meets Expectation / Above Expectation / "
        "Outstanding).",
        "THE FRAMEWORK: the spread should follow the reference curve for this %s (%s), "
        "within a tolerance of %d %s in any band (a small-team floor of one person always "
        "applies). Where it stands now:\n%s"
        % (tier_word, curve["label"], tol, "person" if tol == 1 else "people",
           json.dumps(framework, ensure_ascii=False)),
        ("Bands OUTSIDE tolerance right now: %s. Help them bring it within the framework."
         % json.dumps({PM_LABEL_NAMES[b]: g for b, g in breaches.items()}, ensure_ascii=False))
        if breaches else "The spread is currently WITHIN the framework.",
        "The people in this scope (band = where they sit now; inherited = the "
        "manager-approved / rolled-up band they came in at; cited = pieces of evidence on "
        "record; flag = whether a manager endorsed/disputed it):\n"
        + json.dumps(roster, ensure_ascii=False),
        "HOW TO HELP: flag who is off the curve and by how much; suggest SPECIFIC people to "
        "move and to which band, choosing them from the evidence (someone rated high with "
        "little cited evidence, or carrying a disputed flag, is a candidate to look at "
        "again); whenever you move someone, capture a short rationale drawn from their "
        "record -- it is what the calibration review will read. Someone whose rating isn't finalised counts as "
        "UA by default on the curve; you may set their band when the calibrator asks.",
        'TOOLS for "action": show_distribution{} (show the distribution + roster as a '
        'card); explain_person{subject} (read one person\'s evidence + band history so you '
        'can discuss them); suggest_to_framework{} (the exact moves that bring each band '
        'within tolerance); move_band{subject, band, justification} (record a move -- ALWAYS '
        'include the calibrator\'s OWN reason; if they have not given one, ASK for it -- never make one '
        'up); prepare_lock{} (brings the curve down to your reply, with its Lock button); '
        'search_kb{query}. If nothing is left to do, say so warmly and set action null.',
        _MOVE_ASK_RULE,
        "The distribution + roster are ALWAYS PINNED at the top of the chat, so if they ask "
        "to see it, point them there; call show_distribution{} only if they explicitly want "
        "it inside the conversation.",
        "THE CURVE FIRST (Chris, 2026-09-30): the calibration card opens on the CURVE -- the distribution against the "
        "expected spread and the roster, where they set each person's band in place (or use 'Fit the curve with AI'). "
        "Open on a person's row brings their page in BESIDE the folded curve (there is no view toggle): "
        "their approved score and band, their own score, what came in from the tier below, and an AI insight on "
        "whether their results are justified, with a pager to the next person and a back button to the curve. Talk "
        "about the curve and its gaps; when they ask about a person, point to that person's Open on the roster. "
        "Nobody calibrates their OWN band -- if they are in the list themselves, the tier above does theirs.",
        "THE FINISH: when the spread is within the framework (or they have a defensible "
        "reason to lock it anyway), call prepare_lock{} -- the curve comes down with its Lock "
        "button under the table. NEVER claim you have locked it yourself; ONLY their Lock click "
        "locks the calibration. If it still breaches, the Lock button will ask them for an "
        "override reason.",
    ]
    if ctx["session"] and ctx["session"]["locked_at"]:
        parts.append("NOTE: this scope is already LOCKED. Do not try to move anyone -- "
                     "explain warmly that it is locked and answer questions about it.")
    _gn = _bu_group_prompt_note(db, ctx, tier)
    if _gn:
        parts.append(_gn)
    if tier in _PAST_TALENT_TIERS:   # BU / BG CEO: past years, only when asked (2026-10-22)
        parts.append('ALSO A TOOL: past_talent{subject} (their talent status in the three Year-Ends before this one). '
                     + _PAST_TALENT_BRIEF)
    _ln = _late_agent_note(db, u, "calibration") if tier == "buceo" else ""   # more time Group People gave them (2026-10-31); the HOD's is in _dept_review_system
    if _ln:
        parts.append(_ln)
    if journey:   # inside the team journey: its framing, voice and scope guard already lead the prompt
        return "\n\n".join(parts[2:])
    parts.append(_AGENT_SCOPE_GUARD)
    return "\n\n".join(parts)


# --- Calibration-assistant tools: each fn(db, u, ctx, tier, kw, args) ---------
def _calib_tool_show_distribution(db, u, ctx, tier, kw, args):
    ov = _pm_calib_assist_overview(db, u, ctx, tier, kw)
    return {"ok": True, "displayed": "distribution",
            "render": {"type": "calib_distribution", "data": ov["data"]}}


def _calib_tool_explain_person(db, u, ctx, tier, kw, args):
    subj, err = _calib_resolve_subject(ctx, args.get("subject"))
    if err:
        return {"ok": False, "error": err}
    overall = ctx["overalls"].get(subj["id"])
    _tn = _split_agent_note(db, ctx["period"]["id"], subj["id"])
    rows = _pm_calib_assist_rows(db, ctx, tier)
    row = next((r for r in rows if r["user"]["id"] == subj["id"]), None)
    ev = _pm_cited_evidence(db, subj["id"])
    trail = pm_calibration_trails(db, [subj], ctx["period"]["id"]).get(subj["id"], [])
    # Compact by design: the loop feeds tool results back truncated, and the agent
    # coaches on the SHAPE of the evidence (how much, endorsed/disputed) plus the band
    # history -- not full bodies, which live on the grid's Why report.
    person = {
        "name": subj["full_name"],
        **({"transferred": _tn} if _tn else {}),   # Transferred (2026-11-03)
        "current_band": (PM_LABEL_NAMES.get(row["current_band"], row["current_band"])
                         if row and row["current_band"] else None),
        "inherited_band": (PM_LABEL_NAMES.get(row["incoming_band"], row["incoming_band"])
                           if row and row["incoming_band"] else None),
        "n_cited": len(ev),
        "endorsed": sum(1 for e in ev if (e.get("n_endorse") or 0) > 0),
        "disputed": sum(1 for e in ev if (e.get("n_dispute") or 0) > 0),
        "evidence_titles": [e.get("title") for e in ev if e.get("title")][:4],
        "band_history": [{"tier": t["label"] if (t.get("cal") or t.get("avg")) else PM_TIER_LABEL.get(t["tier"], t["tier"]),
                          "from": t["from"], "to": t["band"],
                          "note": (t["note"] or "")[:80]} for t in trail],
    }
    return {"ok": True, "person": person}


def _calib_tool_suggest_to_framework(db, u, ctx, tier, kw, args):
    rows = _pm_calib_assist_rows(db, ctx, tier)
    dist = pm_band_distribution(rows)
    company = ctx["population"][0]["company"] if ctx["population"] else ""
    curve = pm_curve_for_scope(db, ctx)
    gaps = pm_calibration_target_gaps(dist, curve["dist"])
    total = sum(dist.values())
    breaches = _calib_over_framework(gaps, total)
    tol = calib_tolerance(total)
    if not breaches:
        return {"ok": True, "within_framework": True,
                "message": "The spread is already within the framework."}
    # For each breaching band: how many must move to reach the tolerance edge. A band
    # OVER target (gap < 0) needs some of its people moved DOWN a band; a band SHORT
    # (gap > 0) needs some moved UP into it. The agent names who from the roster.
    moves = []
    for b, gap in breaches.items():
        moves.append({"band": PM_LABEL_NAMES.get(b, b),
                      "over_by": (-gap if gap < 0 else 0),
                      "short_by": (gap if gap > 0 else 0),
                      "must_move": abs(gap) - tol})
    return {"ok": True, "within_framework": False, "tolerance": tol, "moves": moves}


# "mark them Outstanding WITH THIS REMARK" names the remark already saved -- never the words they typed before asking
# for help (2026-10-06: the agent's band move saved the HOD's original wording over the refined draft they had just
# saved). Read from the HOD's own message, never the model's.
_THIS_REMARK_RE = re.compile(r"\b(?:this|that|the|my|same|saved|approved|refined|new|current)\s+(?:remark|wording|note|"
                             r"draft|justification)\b|\bremark\s+as\s+(?:it\s+is|saved)\b", re.I)


# The chat never makes an HOD's final save on its own (Chris, 2026-10-06: "when user replies 'yes, save it', it should
# just save the remark but not the entire submission, unless the user specifies so like 'yes, save it and save the
# submission', why? because we have a confirmation pop out for the final submission"): a "yes" to a drafted remark, or
# a band the agent sets, goes onto the person's page, unsaved, for the page's Save and its confirm -- unless their
# message asks for the save itself.
_DEPT_SUBMIT_NOW_RE = re.compile(
    r"\bsubmi(?:t|ts|tted|tting|ssion)\b|\bfinali[sz]e\b"
    r"|\bsave\b[^.?!]{0,30}?\b(?:review|band|changes|person|decision)\b|\bsave\s+(?:it\s+)?(?:all|everything|both)\b",
    re.I)


def _dept_submit_asked():
    """This turn's message asks for the HOD's save itself ("yes, save it and save the submission"), not just the
    wording ("yes, save it")."""
    msg = (request.values.get("message") or "") if has_request_context() else ""
    return bool(_DEPT_SUBMIT_NOW_RE.search(msg))


def _dept_held(subject, band_label, band, justification):
    """move_band in a department review without the save asked for: it passed every check, and goes onto their page."""
    return {"ok": True, "held": True, "moved": subject["full_name"], "person_id": subject["id"], "band": band_label,
            "band_code": band, "remark": (justification or "").strip(),
            "note": "NOT saved: it is on their page, just below, for the HOD to press Save (it asks them to confirm)"}


def _hod_keep_saved_remark(justification, saved):
    msg = (request.values.get("message") or "") if has_request_context() else ""
    if (saved or "").strip() and _THIS_REMARK_RE.search(msg):
        return saved.strip()
    return justification


def _calib_tool_move_band(db, u, ctx, tier, kw, args):
    subj, err = _calib_resolve_subject(ctx, args.get("subject"))
    if err:
        return {"ok": False, "error": err}
    raw = (args.get("band") or "").strip()
    band = raw.upper()
    if band not in PM_BAND_ORDER:
        rev = {v.lower(): k for k, v in PM_LABEL_NAMES.items()}
        band = rev.get(raw.lower(), band)
    justification = (args.get("justification") or "").strip()
    held = tier == "hod" and not _dept_submit_asked()
    if tier == "hod":
        justification = _hod_keep_saved_remark(justification, _calib_existing_note(db, "pm", (tier, kw, ctx), subj["id"]))
    subject, err = _pm_calib_apply(db, u, ctx, tier, subj["id"], band, justification, dry_run=held)
    if err:
        return {"ok": False, "error": err}
    if held:
        return _dept_held(subject, PM_LABEL_NAMES.get(band, band), band, justification)
    return {"ok": True, "moved": subject["full_name"], "band": PM_LABEL_NAMES.get(band, band)}


def _calib_tool_prepare_lock(db, u, ctx, tier, kw, args):
    _lo = leader_ability_off(db, u, leader_tier_ability(tier, "lock", ctx))   # a unit's bu.lock, a group's cg.lock
    if _lo:
        return {"ok": False, "error": _lo}
    session_row = ctx["session"]
    if session_row and session_row["locked_at"]:
        return {"ok": False, "error": "This department review is already submitted." if tier == "hod"
                else "This scope's calibration is already locked."}
    # The cascade gate (a parent waiting on a child to lock first) blocks the lock
    # regardless of the framework -- surface it so the agent doesn't promise a lock
    # that cannot happen yet.
    pending = pm_calibration_pending_children(
        db, ctx["period"]["id"], tier, ctx["business_group"], ctx["scope_key"]) \
        if tier in ("buceo", "bgceo") else []
    breaches = {} if tier == "hod" else _pm_calib_lock_breaches(db, tier, ctx, session_row)   # no curve rule for HOD
    ov = _pm_calib_assist_overview(db, u, ctx, tier, kw)
    data = dict(ov["data"])
    if data.get("closed"):
        return {"ok": False, "error": data["closed"]}
    if data.get("unassigned"):   # an HOD bands everyone with no final result first (2026-09-30)
        return {"ok": True, "ready": True, "blocked": _dept_review_unassigned_msg(data["unassigned"], pot=False),
                "render": {"type": "calib_lock", "data": data}}
    data["pending"] = [(p[0] if tier == "bgceo" else p[1]) for p in pending] if pending else []
    data["breach_message"] = _calib_breach_message(breaches, PM_LABEL_NAMES) if breaches else ""
    return {"ok": True, "ready": True, "render": {"type": "calib_lock", "data": data}}


_CALIB_TOOLS = {
    "show_distribution": _calib_tool_show_distribution,
    "explain_person": _calib_tool_explain_person,
    "suggest_to_framework": _calib_tool_suggest_to_framework,
    "move_band": _calib_tool_move_band,
    "prepare_lock": _calib_tool_prepare_lock,
}


# A department review has no curve (Chris, 2026-09-30): the curve tools are refused for an HOD, so the model can't show
# one or fit to one.
_DEPT_REVIEW_NO_CURVE = ("a department review has no curve -- the table of people is pinned at the top; talk about the "
                         "people and their bands")


def _calib_run_tool(db, u, ctx, tier, kw, action):
    tool = action.get("tool")
    if tier == "hod" and tool in ("show_distribution", "suggest_to_framework"):
        return {"ok": False, "error": _DEPT_REVIEW_NO_CURVE}
    if tier == "hod" and tool == "open_person":
        args = action.get("args") or {}
        return _dept_tool_open_person(ctx, args if isinstance(args, dict) else {})
    if tool == "search_kb":
        args = action.get("args") or {}
        return _journey_tool_search_kb(db, args if isinstance(args, dict) else {})
    if tool == "past_talent":   # BU / BG CEO only, only when asked (2026-10-22)
        args = action.get("args") or {}
        return _past_talent_tool(db, tier, ctx, args if isinstance(args, dict) else {})
    fn = _CALIB_TOOLS.get(tool)
    if not fn:
        return {"ok": False, "error": "unknown tool"}
    args = action.get("args") or {}
    if not isinstance(args, dict):
        args = {}
    return fn(db, u, ctx, tier, kw, args)


# ---------------------------------------------------------------------------
# POTENTIAL calibration in the journey (Chris, 2026-09-28: "For performance and potential calibration respectively, use
# the same line manager method by providing the overall AI summary + their score of the person's performance or
# potential first with left and right navigation button, only then show the calibration curve"). A second Calibration
# tab beside the performance one, for HOD / BU CEO / BG CEO, over the SAME tables the classic potential pages write
# (calibration_sessions / calibration_adjustments). Moves go through _pot_calib_apply (the classic routes' checks);
# the lock is the classic lock route, which comes back here. The AI summary obeys every 360 anonymity rule.
# ---------------------------------------------------------------------------
_POT_BANDS = ("Low", "Mid", "High")
_POT_TIER_LABEL = {"hod": "HOD", "buceo": "BU CEO", "bgceo": "BG CEO"}
_POT_REVIEWER = {"hod": "HOD calibrating their department", "buceo": "BU CEO calibrating their business unit",
                 "bgceo": "BG CEO calibrating their business group"}


def _pot_scope_population(db, tier, key):
    if tier == "hod":
        _sk, _sa = _hod_review_skip_sql(db, key)   # a calibrator is no HOD: nobody (2026-10-30)
        return db.execute(f"SELECT * FROM users WHERE hod_id=? AND role!='admin' AND {calibration_population_sql()}{_sk} "
                          "ORDER BY full_name", [key] + _sa).fetchall()
    if tier == "buceo" and len(key) > 2 and key[2]:   # a calibration group of the unit (2026-10-22)
        return db.execute(f"SELECT * FROM users WHERE business_group=? AND {bu_group_member_sql()} "
                          f"AND role!='admin' AND {calibration_population_sql()} ORDER BY full_name",
                          [key[0], key[2]]).fetchall()
    if tier == "buceo":   # units calibrated together this cycle are one population (row 6)
        units = _bu_units_of(db, active_cycle_id(db), key[0], key[1])
        # a calibration group's departments are its calibrator's, never the BU CEO's (2026-10-22)
        return db.execute(f"SELECT * FROM users WHERE business_group=? AND company IN ({','.join('?' * len(units))}) "
                          f"AND NOT {bu_grouped_sql()} AND role!='admin' AND {calibration_population_sql()} "
                          "ORDER BY full_name", [key[0]] + units).fetchall()
    return db.execute(f"SELECT * FROM users WHERE business_group=? AND role!='admin' "
                      f"AND {calibration_population_sql()} ORDER BY full_name", (key,)).fetchall()


def _pot_calib_scope(db, u, fresh=False, tier=None):
    """(tier, key, ctx) for the Potential calibration tab: the HOD / BU CEO scope this login holds (a BG CEO
    calibrates on the Talent Box, 2026-09-29) with people in it, while the calibration assistant is on for them and
    the Calibration module is on -- else None. `tier` picks ONE of their tiers (the Dept / BU view, 2026-09-30); with
    none given it is the request's own view's tier, else the first with people (the old behaviour). The same scope
    derivation as the classic pages (calibration_tier_of), so nobody reaches a scope that isn't theirs. Cached per
    request and tier (fresh=True after a move)."""
    if not u:
        return None
    if tier is None:
        tier = _journey_view_tier(db, u)
    ck = "_jpot_%s_%s" % (u["id"], tier or "*")
    if not fresh and has_request_context() and ck in g:
        return g.get(ck)
    out = None
    want = tier
    cid = active_cycle_id(db)
    # a cycle with no potential result has nothing to review or calibrate on this axis (cycle_has_potential)
    if cid and _calib_assist_on(u) and cycle_module_on("calibration", db) and cycle_has_potential(db, cid):
        for tier, key in calibration_tier_of(db, u):
            if tier == "bugrp":   # a calibration group: the BU CEO tier, its key carrying the group (2026-10-22)
                tier = "buceo"
            if tier not in _POT_TIER_LABEL or tier not in _CALIB_AXIS_TIERS or (want and tier != want):
                continue   # a BG CEO calibrates on the Talent Box, not this tab (2026-09-29)
            if not leader_can(u, leader_tier_ability(tier, "view", key), db):
                continue   # the seat's view is switched off (Roles & access › Leader roles, 2026-10-20)
            pop = _pot_scope_population(db, tier, key)
            if not pop:
                continue
            out = _pot_calib_sc(db, cid, tier, key, pop)
            break
    if has_request_context():
        setattr(g, ck, out)
    return out


def _pot_calib_sc(db, cid, tier, key, pop):
    """(tier, key, ctx) for one potential scope with its population -- the Potential tab's and the HOD submit's."""
    if tier == "hod":
        hn = db.execute("SELECT full_name FROM users WHERE id=?", (key,)).fetchone()
        scope_key, bg, label = str(key), pop[0]["business_group"], (hn["full_name"] if hn else "Department")
    elif tier == "buceo" and len(key) > 2 and key[2]:   # a calibration group of the unit (2026-10-22)
        g = bu_group(db, key[2])
        scope_key, bg = BU_GROUP_PREFIX + str(key[2]), key[0]
        label = bu_group_label(bg, g) if g else scope_key
    elif tier == "buceo":
        scope_key, bg, label = key[1], key[0], key[1]
    else:
        scope_key, bg, label = key, key, key
    grp_scope = tier == "buceo" and len(key) > 2 and bool(key[2])
    join = calib_join(db, cid, bg, scope_key) if tier == "buceo" and not grp_scope else None   # units together (row 6)
    if join:
        scope_key, label = join["lead"], join["label"]
    session_row = db.execute("SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier=? AND scope_key=?",
                             (cid, tier, scope_key)).fetchone()
    extra = {}
    if join:
        extra = {"join": join, "member_sessions": {m: db.execute(
            "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=?", (cid, m)).fetchone()
            for m in join["members"]}}
        cu = current_user() if has_request_context() else None
        extra["read_only"] = not (cu and (is_buceo_of(cu, bg, join["lead"]) or is_super(cu)))
    if tier == "buceo":   # its calibration group, or the unit's grouped people read only (2026-10-22)
        extra["grp"] = bu_group(db, key[2]) if grp_scope else None
        extra["others"] = [] if grp_scope else bu_unit_others(db, cid, bg, join["members"] if join else [key[1]], "pot")
    return (tier, key, {"cycle_id": cid, "tier": tier, "scope_key": scope_key, "business_group": bg, **extra,
                        "scope_label": label, "population": pop, "session": session_row,
                        # the BG CEO's seat inherits what came from below, never its own move (2026-10-07)
                        "band_fn": subject_band if tier == "hod" else (
                            (lambda d_, p_, c_: effective_band(d_, p_, c_, skip_tiers=("bgceo",))) if tier == "bgceo"
                            # the BU CEO's: never the BG CEO's or a Group Chief's later call (2026-10-12)
                            else (lambda d_, p_, c_: effective_band(d_, p_, c_, skip_tiers=("bgceo", "group")))
                            if tier == "buceo" else effective_band)})


def _pot_trail(db, p, cid, tier):
    """The LOWER tiers' locked moves on this person (the case as it reached this seat, never above it)."""
    below = {"hod": (), "buceo": ("hod",), "bgceo": ("hod", "buceo")}.get(tier, ())
    keys = {"hod": str(p["hod_id"]) if p["hod_id"] else None, "buceo": bu_scope_key(db, p)}
    out = []
    for t in below:
        k = keys.get(t)
        if not k:
            continue
        if t == "buceo" and bu_shared(db, p):   # several calibrators (2026-10-26): each who locked, then the average
            out += [dict({"label": x["label"], "from": x["from"], "band": x["band"], "note": (x["note"] or "")[:300],
                          "by": x["by"], "tier": "buceo"},
                         **{k_: x[k_] for k_ in ("cal", "avg", "weight", "waiting") if k_ in x})
                    for x in bu_level_trail(db, "pot", cid, p)]
            continue
        r = db.execute("SELECT ca.original_band, ca.adjusted_band, ca.justification FROM calibration_adjustments ca "
                       "JOIN calibration_sessions cs ON cs.id=ca.session_id WHERE cs.cycle_id=? AND cs.tier=? "
                       "AND cs.scope_key=? AND cs.locked_at IS NOT NULL AND ca.subject_id=?",
                       (cid, t, k, p["id"])).fetchone()
        if r:
            by = ""
            if t == "hod" and p["hod_id"]:   # who, beside what they did, on the person's page (2026-10-05)
                h = db.execute("SELECT full_name FROM users WHERE id=?", (p["hod_id"],)).fetchone()
                by = (h["full_name"] if h else "") or ""
            out.append({"label": _POT_TIER_LABEL[t], "from": r["original_band"], "band": r["adjusted_band"],
                        "note": (r["justification"] or "")[:300], "by": by, "tier": t})
    return out


def _fig1(x):
    """One decimal, half up, read from the shortest decimal form -- so a shown potential score always equals the shown
    360 points plus the shown competency points (the competency moves in halves). Python's round() rounds 26.25 down
    and the browser's toFixed rounds it up, which showed 26.3 + 1.0 = 27.2 (2026-10-01)."""
    if x is None:
        return None
    import decimal
    return float(decimal.Decimal(repr(float(x))).quantize(decimal.Decimal("0.1"), rounding=decimal.ROUND_HALF_UP))


def _pot_shown(combo):
    """(score, 360 part, competency part) as SHOWN: each rounded once (_fig1) and the score their sum, so the AI
    insight's two parts always add up to the score on the table (2026-10-01)."""
    if (combo or {}).get("source") == "combined" and combo.get("c_360") is not None and combo.get("c_tech") is not None:
        c3, ct = _fig1(combo["c_360"]), _fig1(combo["c_tech"])
        return _fig1(c3 + ct), c3, ct
    return _fig1((combo or {}).get("score")), None, None


def _pot_self_shown(combo):
    """(score, max, 360 part, competency part) of the potential by their OWN competency answers, each rounded once and
    the score their sum, as _pot_shown does for the line manager's -- or None before they've submitted any."""
    c = combo or {}
    if c.get("self_c_360") is None or c.get("self_c_tech") is None:
        return None
    c3, ct = _fig1(c["self_c_360"]), _fig1(c["self_c_tech"])
    return _fig1(c3 + ct), _fig1(c.get("self_max")), c3, ct


def _pot_review_comp(db, cid, ids):
    """{subject_id: (assessment status or None, has competencies assigned)} for the HOD's potential review, in two
    reads over the department."""
    ids = [int(i) for i in ids]
    if not ids:
        return {}
    q = ",".join("?" * len(ids))
    nobody = _tc_chair_unreviewed_ids(db)   # a submitted one nobody reviews counts as reviewed (2026-11-06)
    st = {r["subject_id"]: ("reviewed" if (r["status"] == "submitted" and r["subject_id"] in nobody) else r["status"])
          for r in db.execute(
        "SELECT subject_id, status FROM tc_assessments WHERE cycle_id=? AND subject_id IN (%s)" % q, [cid] + ids)}
    asg = {r["subject_id"] for r in db.execute(
        "SELECT DISTINCT subject_id FROM tc_assignments WHERE cycle_id=? AND subject_id IN (%s)" % q, [cid] + ids)}
    return {i: (st.get(i), i in asg) for i in ids}


def _pot_review_final(valid_360, comp):
    """The HOD's potential review counts a potential score only when BOTH halves are in (Chris, 2026-10-01: "only show
    score if both are filled, if not deemed as not finalized - default to low, and HOD can assign a band"): a valid
    360 (enough raters) and the competency their line manager approved. Someone with no competencies assigned this
    cycle has nothing to approve, so their 360 alone is final. `comp` = (status, assigned)."""
    status, assigned = comp
    return bool(valid_360) and (status == "reviewed" or not assigned)


def _pot_sw_word(share, letter, none_seen=None):
    """The words for how much of a principle's behaviour was demonstrated, never a count or a % (the 360's anonymity,
    the AI insight's rule). Several raters: who saw it; a letter grade (one rater, their line manager): how much of it.
    `none_seen`: nothing at all was demonstrated (left out: share == 0, true until Developing earns points above 0)."""
    if none_seen is None:
        none_seen = share <= 0
    if letter:
        return ("Mostly demonstrated" if share >= 0.75 else "Partly demonstrated" if share >= 0.4
                else "Rarely demonstrated" if not none_seen else "Not demonstrated yet")
    return "Seen by most" if share >= 0.75 else "Mixed" if share >= 0.4 else "Seen by few"


def _pot_sw_gap(cur, fut, letter):
    """(note, level) for a development area: which level is short. The current level not seen is the bigger flag for
    the calibrator; the next level not seen yet is room to grow."""
    if cur is not None and cur < 0.75:
        return ("Current-level behaviour not demonstrated yet" if letter or cur == 0
                else "Current-level behaviour not consistently seen"), "current"
    if fut is not None and fut < 0.75:
        if fut == 0:
            return "Next-level behaviour not %s yet" % ("demonstrated" if letter else "seen"), "next"
        return ("Next-level behaviour partly demonstrated" if letter
                else "Next-level behaviour seen by few" if fut < 0.4
                else "Next-level behaviour not consistently seen"), "next"
    return "", None


def _pot_held_tiers(db, cid, subject_ids):
    """{subject_id: tier_n} -- the 360 tier the SUBMITTED, non-archived ratings of each subject hold this cycle (their
    answers' own statements, `_fb_assignment_tiers`): the tier holding the most ratings, a tie to the lower tier.
    A subject with no submitted rating that holds rows is absent (the caller uses the live tier). Two reads for the
    whole scope, never one per person (2026-11-09: the strengths summary after a grade moved to another tier)."""
    ids = list(dict.fromkeys(subject_ids))
    if not ids:
        return {}
    rat = []
    for k in range(0, len(ids), _FB_CHUNK):
        part = ids[k:k + _FB_CHUNK]
        rat += db.execute(
            "SELECT id, subject_id FROM assignments WHERE cycle_id=? AND status='submitted' AND archived=0 "
            "AND subject_id IN (%s)" % ",".join("?" * len(part)), [cid] + part).fetchall()
    tiers = _fb_assignment_tiers(db, [a["id"] for a in rat])
    count = defaultdict(lambda: defaultdict(int))
    for a in rat:
        tn = tiers.get(a["id"])
        if tn is not None:
            count[a["subject_id"]][tn] += 1
    return {sid: min(c, key=lambda t: (-c[t], t)) for sid, c in count.items()}


def _pot_strengths(db, rows, cid, skip=None):
    """{subject_id: {...}} -- where each person's 360 is strongest and weakest, and the competency their line manager
    reviewed, for the potential person page (Chris, 2026-10-05: "it should show the highest rated/ full demonstrated
    attributes of the person, so the CEO can see what's the person strength and weakness, maybe put top 3 and bottom 3").
    The principles are ranked the way the potential score counts them (a share of the most the cycle's 360 points allow, a
    next-level behaviour weighing dn to the current level's dc, an answered Developing earning vc / vn), a tie to the one more seen at the next level, then framework order; the top 3
    and the bottom 3 never overlap (fewer than six split between them). Fully demonstrated = every rater said
    Demonstrate on every behaviour of it, at both levels; one never sits under development areas. Words and a 0-4 step,
    never counts or % (the 360's anonymity). Only above the 360 threshold and never your own row. Two reads for the
    whole scope, not one per person."""
    want = [r for r in rows if r.get("valid") and r["user"]["id"] != skip]
    if not want:
        return {}
    ids = [r["user"]["id"] for r in want]
    q = ",".join("?" * len(ids))
    tally = defaultdict(lambda: [0, 0])   # (subject, statement) -> [yes, answered]
    for t in db.execute(
            "SELECT a.subject_id, r.statement_id, SUM(r.answer='yes') AS y, COUNT(r.answer) AS n FROM responses r "
            "JOIN assignments a ON a.id=r.assignment_id WHERE a.cycle_id=? AND a.status='submitted' "
            "AND a.archived=0 AND a.subject_id IN (%s) AND r.answer IS NOT NULL GROUP BY 1, 2" % q, [cid] + ids):
        tally[(t["subject_id"], t["statement_id"])] = [t["y"] or 0, t["n"] or 0]
    held = _pot_held_tiers(db, cid, ids)   # {subject: the tier their submitted ratings hold}: one batched read
    comp = defaultdict(list)   # the competency their line manager REVIEWED, in the order they were assessed
    for t in db.execute(
            "SELECT a.subject_id, a.is_future, s.title, sc.answer, sc.manager_answer FROM tc_assignments a "
            "JOIN tc_skills s ON s.id=a.skill_id JOIN tc_assessments t ON t.cycle_id=a.cycle_id "
            "AND t.subject_id=a.subject_id AND " + _tc_done_sql(db, "t", "t.subject_id") + " "
            "LEFT JOIN tc_scores sc ON sc.assignment_id=a.id AND sc.assessment_id=t.id "
            "WHERE a.cycle_id=? AND a.subject_id IN (%s) "
            "ORDER BY a.subject_id, COALESCE(NULLIF(s.skill_category,''), '~'), a.is_future, a.seq, s.title" % q,
            [cid] + ids):
        comp[t["subject_id"]].append(t)
    assigned = {t["subject_id"] for t in db.execute(
        "SELECT DISTINCT subject_id FROM tc_assignments WHERE cycle_id=? AND subject_id IN (%s)" % q, [cid] + ids)}
    by_tier, live_tier, out = {}, {}, {}
    pts = points_for(db, cid, "360")   # the cycle's own points: a share is earned over the most, Developing earning vc / vn
    nobody_ids = _tc_chair_unreviewed_ids(db)   # one read for the scope (2026-11-06)
    for r in want:
        p = r["user"]
        letter = min_valid_submissions(p["job_grade"]) == 1   # the 360 threshold: the LIVE grade's
        # the statements the submitted answers hold (a grade moved to another tier after the raters answered leaves
        # their answers on the old tier's statements), else the live tier as before (2026-11-09)
        tn = held.get(p["id"])
        if tn is None:
            if p["job_grade"] not in live_tier:   # per grade, as the statements were before
                live_tier[p["job_grade"]] = _cycle_tier_n(db, p["job_grade"], cid)
            tn = live_tier[p["job_grade"]]
        if tn not in by_tier:
            by_tier[tn] = statements_for_tier(db, tn, cid)
        crits = {}
        for s in by_tier[tn]:
            c = crits.setdefault(s["criterion_id"], {"name": s["criterion_name"], "lp": s["criterion_description"] or "",
                                                     "order": s["sort_order"], "lv": {0: [0, 0], 1: [0, 0]}})
            y, n = tally.get((p["id"], s["statement_id"]), (0, 0))
            lv = c["lv"][1 if s["is_future"] else 0]
            lv[0] += y; lv[1] += n
        items = []
        for c in crits.values():
            (cy, cn), (fy, fn) = c["lv"][0], c["lv"][1]
            den = cn * pts.dc + fn * pts.dn
            if not den:
                continue
            # earned over the most: a Demonstrate earns dc / dn, an answered Developing (answered - yes) vc / vn
            share = (cy * pts.dc + (cn - cy) * pts.vc + fy * pts.dn + (fn - fy) * pts.vn) / den
            none_seen = (cy + fy) == 0   # no rater said Demonstrate (share > 0 would read a Developing floor as "some")
            cur, fut = (cy / float(cn) if cn else None), (fy / float(fn) if fn else None)
            full = cy == cn and fy == fn
            items.append({"name": c["name"], "lp": c["lp"], "order": c["order"], "share": share,
                          "fut": fut if fut is not None else 0.0, "cur": cur, "full": full,
                          "label": ("Fully demonstrated" if not letter else "Demonstrated") if full
                          else _pot_sw_word(share, letter, none_seen),
                          "step": 4 if full else (3 if share >= 0.75 else 2 if share >= 0.4 else 1 if not none_seen else 0)})
        items.sort(key=lambda i: (-i["share"], -i["fut"], i["order"]))
        n_top = min(3, (len(items) + 1) // 2)
        # a tie across the line between strengths and development areas goes to the side its words belong to: seen by
        # most or better stays a strength, anything weaker is a development area (one strong principle and six seen
        # by few read as two "strengths" and "nothing stands out" on staging, 2026-10-05)
        rest = {round(i["share"], 9) for i in items[n_top:]}
        top = [i for i in items[:n_top] if i["share"] >= 0.75 or round(i["share"], 9) not in rest]
        floor = min((i["share"] for i in top), default=2.0)   # a development area is weaker than every strength
        cand = sorted((i for i in items if i not in top and not i["full"] and i["share"] < floor - 1e-9),
                      key=lambda i: (i["share"], i["fut"], i["order"]))   # the weakest first
        bottom = cand[:3]
        more = [i for i in cand[3:] if bottom and abs(i["share"] - bottom[-1]["share"]) < 1e-9]   # the rest of the tie
        clean = lambda i, dev: dict({"name": i["name"], "lp": i["lp"], "label": i["label"], "step": i["step"],
                                     "full": i["full"]},
                                    **(dict(zip(("note", "gap"), _pot_sw_gap(i["cur"], i["fut"], letter))) if dev else {}))
        blk = {"letter": letter, "top": [clean(i, False) for i in top], "bottom": [clean(i, True) for i in bottom],
               "n_full": sum(1 for i in items if i["full"]), "n": len(items), "more_same": len(more),
               "more_items": [clean(i, True) for i in more]}   # behind "+N more seen the same", opened on the page
        if len(items) > 1 and not all(i["full"] for i in items) \
                and max(i["share"] for i in items) - min(i["share"] for i in items) < 1e-9:
            # seen the same on every principle: no top or bottom to name, said once (with the level that's short)
            notes = {_pot_sw_gap(i["cur"], i["fut"], letter)[0] for i in items}
            blk.update(top=[], bottom=[], more_same=0, more_items=[], even={"label": items[0]["label"], "step": items[0]["step"],
                                               "note": notes.pop() if len(notes) == 1 else ""})
        tc = comp.get(p["id"])
        if tc:   # per competency (a title can be assessed at both levels): fully demonstrated = every level it holds
            per = {}
            for t in tc:
                e = per.setdefault(t["title"], {"title": t["title"], "levels": 0, "short": None})
                e["levels"] += 1
                if (t["manager_answer"] or t["answer"]) != TC_ANSWER_DEMONSTRATE:
                    lvl = "next" if t["is_future"] else "current"
                    e["short"] = "current" if "current" in (e["short"], lvl) else lvl
            full_c = sorted((e for e in per.values() if not e["short"]), key=lambda e: -e["levels"])
            dev_c = sorted((e for e in per.values() if e["short"]), key=lambda e: e["short"] != "current")
            blk["comp"] = {"full": [e["title"] for e in full_c], "dev": [{"title": e["title"], "level": e["short"]}
                                                                       for e in dev_c],
                           "nobody": p["id"] in nobody_ids}   # nobody reviews it: their own answers (2026-11-06)
        elif p["id"] in assigned:   # competencies to assess, not reviewed by their line manager yet: said, not shown
            blk["comp_pending"] = True
        out[p["id"]] = blk
    return out


def _pot_calib_rows(db, ctx, chain=False):
    """Each person in the scope: the band they came in with (band_fn -- raw at HOD, the locked tiers below
    otherwise), where they sit now (this session's move, if any), and the COMBINED potential score behind it.
    chain=True also attaches the band's journey (attach_tier_chain: self_band, lm_band, tier_slots) -- the classic
    pages' own reading, for the curve's roster and the AI fit."""
    cid, sess = ctx["cycle_id"], ctx["session"]
    adj = {}
    _sids = _calib_session_ids(ctx)   # units calibrated together: every unit's moves (row 6)
    if _sids:
        for r in db.execute("SELECT * FROM calibration_adjustments WHERE session_id IN (%s)" % ",".join(
                "?" * len(_sids)), _sids).fetchall():
            adj[r["subject_id"]] = r
    review = ctx.get("tier") == "hod"   # the HOD's department review: a potential score needs both halves
    # every seat knows where their competency stands (the person's page says "none this cycle" vs "not approved yet",
    # 2026-10-05); only the HOD's review makes a score wait for it
    comp = _pot_review_comp(db, cid, [p["id"] for p in ctx["population"]])
    rows = []
    for p in ctx["population"]:
        info = ctx["band_fn"](db, p, cid)
        res = subject_result(db, p, cid)
        combo = res.get("combined") or {}
        a = adj.get(p["id"])
        row = {"user": p, "band_info": info, "adjusted": a is not None, "came_in": _calib_seen(a) if a else None,
               "current_band": a["adjusted_band"] if a else info.get("band"),
               "incoming_band": info.get("band"), "justification": (a["justification"] if a else "") or "",
               "score": combo.get("score"), "max": combo.get("max") or res.get("max_score"),
               "pct_360": combo.get("pct_360"), "pct_tech": combo.get("pct_tech"), "basis": combo.get("source"),
               "pts_360": combo.get("pts_360"), "max_360": combo.get("max_360"),
               "pts_tech": combo.get("pts_tech"), "max_tech": combo.get("max_tech"),
               "tech_self": combo.get("tech_self"), "tech_self_max": combo.get("tech_self_max"),
               "c_360_max": combo.get("c_360_max"), "c_tech_max": combo.get("c_tech_max"), "shown": _pot_shown(combo),
               "self_shown": _pot_self_shown(combo),
               "w_360": combo.get("w_360"), "w_tech": combo.get("w_tech"),
               "submitted": res.get("submitted"), "valid": bool(res.get("score_valid")),
               "band_default": False, "pot_final": True}
        c = comp.get(p["id"], (None, False))
        row["comp_status"] = c[0] if c[1] else "na"
        if review:
            row["comp_pct"] = combo.get("pct_tech")
            row["pot_final"] = _pot_review_final(row["valid"], c)
            if not row["pot_final"]:   # nothing final came up: Low only by default (never stored) until the HOD sets it
                row["incoming_band"] = None
                if not a:
                    row["current_band"], row["band_default"] = "Low", True
        # a result that came up after this tier saved, and disagrees (2026-10-02)
        row["late"] = _calib_late(a, row["incoming_band"], a["adjusted_band"] if a else None,
                                  info.get("source") or "raw")
        rows.append(row)
    if chain and rows:
        attach_tier_chain(db, rows, cid, ctx["population"], ctx["tier"])
        for r in rows:   # a band that isn't final has no LM band to show (it would be the 360's alone); Self shows
            if not r["pot_final"]:   # once the 360 is in and they've submitted their own competency answers
                r["lm_band"] = None
                if not (r["valid"] and r.get("comp_status") in ("submitted", "reviewed")):
                    r["self_band"] = None
    return rows


def _pot_calib_chain(r, tier):
    """One row's POTENTIAL band journey up to the viewing seat, in the performance roster's shape (_pm_calib_chain),
    read from attach_tier_chain() so the chat curve and the classic pages share one definition (Chris, 2026-09-30:
    "the table columns didn't have the band movement like the performance calibration"). Self = the band by their own
    competency answers, LM = after their line manager's review (where the cascade starts), HOD = the HOD's locked band
    (a BU CEO viewing), kept or moved -- as on performance; None = the HOD recorded nothing -- then THIS tier's band,
    the one they can change."""
    out = [{"tier": "Self", "band": r.get("self_band")}, {"tier": "LM", "band": r.get("lm_band")}]
    if tier == "buceo":
        h = next((s for s in r.get("tier_slots") or [] if s["tier"] == "HOD"), None)
        moved = bool(h and h["changed"])
        hfrom = (h.get("from") or None) if moved else None   # from which band the HOD moved it (2026-10-07)
        # a band the HOD kept is their band too, a pill like a move (Chris, 2026-10-07: "why is 02, 03, and 04 HOD band
        # in plain text instead of the colour box?") -- it used to come through as None, a dash, on potential only
        out.append(dict({"tier": "HOD", "band": h["band"] if moved else r.get("hod_band"), "moved": moved,
                         **({"from": hfrom} if hfrom else {}),
                         "note": (r.get("hod_note") or "").strip()[:300]},   # the department review's remark (2026-09-30)
                        **({"late": r["hod_late"]} if r.get("hod_late") else {})))
    out.append({"tier": _POT_TIER_LABEL.get(tier, tier.upper()), "band": r.get("current_band"), "own": True,
                # moved = a band different from what came in (set back to it is no move, whatever the row says)
                "moved": bool(r.get("adjusted")) and r.get("current_band") != r.get("incoming_band")})
    return out


def _pot_calib_others(db, ctx, tier):
    """The potential side of _pm_calib_others: the grouped people, read only, with their journey up to the HOD."""
    op = list(ctx.get("others") or []) if tier == "buceo" else []
    if not op:
        return []
    rows = _pot_calib_rows(db, dict(ctx, population=op, session=None, member_sessions=None), chain=True)
    calls = _bu_shared_calls(db, "pot", ctx["cycle_id"], [r["user"] for r in rows])
    by = {}
    out = []
    for r in rows:
        gs_ = bu_groups_of_person(db, r["user"])   # every calibrator of theirs, one tag (2026-10-26)
        g = tuple(x_["id"] for x_ in gs_) or None
        if g and g not in by:
            by[g] = bu_groups_by(db, gs_)
        out.append(dict({"id": r["user"]["id"], "name": r["user"]["full_name"], "other": True,
                         "department": _row_get(r["user"], "department"), "job_title": _row_get(r["user"], "job_title"),
                         "job_grade": _row_get(r["user"], "job_grade"), "unit": _row_get(r["user"], "company"),
                         "incoming_band": r.get("incoming_band"),
                         "chain": _pot_calib_chain(r, tier)[:-1]}, **(by.get(g) if g else {}),
                        **_bu_shared_row(db, "pot", r["user"], calls, list(_POT_BANDS), r.get("incoming_band"))))
    return out


def _pot_calib_overview(db, u, sc):
    tier, key, ctx = sc
    rows = _pot_calib_rows(db, ctx, chain=True)
    dist = band_distribution_from_rows(rows)
    total = sum(dist.values())
    gaps = calibration_target_gaps(dist, CALIBRATION_TARGET)
    review = tier == "hod"   # a department review: no curve rule (Chris, 2026-09-30)
    breaches = {} if review else _calib_over_framework(gaps, total)
    locked = bool(ctx["session"] and ctx["session"]["locked_at"])
    # the BG CEO's lock of the unit closes the BU CEO's calibration: it reads as locked, and says why (2026-10-07)
    bg_closed = (next((x for x in (_bg_closed(db, "pot", ctx["cycle_id"], key[0], m_) for m_ in _ctx_units(ctx))
                       if x), None) if tier == "buceo" and not locked else None)
    if bg_closed:
        locked = True
    _sids = _calib_session_ids(ctx)
    own = {a["subject_id"]: (a["justification"] or "") for a in db.execute(
        "SELECT subject_id, justification FROM calibration_adjustments WHERE session_id IN (%s)"
        % ",".join("?" * len(_sids)), _sids).fetchall()} if _sids else {}
    sw = _pot_strengths(db, rows, ctx["cycle_id"], skip=u["id"])   # their strengths and development areas
    rmk = _pot_remark_entries(db, [r["user"] for r in rows if r["user"]["id"] != u["id"]], ctx["cycle_id"], tier)
    newly = newly_confirmed_ids(db, ctx["cycle_id"])   # added with a Confirmation rating (2026-10-22)
    behalf_lm = lm_behalf_ids(db, ctx["cycle_id"])   # their line manager assessed them on their behalf (2026-10-26)
    nodata = nodata_map(db, ctx["cycle_id"], [r["user"]["id"] for r in rows])   # no KPI lines / no 360 (2026-11-02)
    people = [{
        "id": r["user"]["id"], "name": r["user"]["full_name"],
        "newly": r["user"]["id"] in newly, "behalf_lm": r["user"]["id"] in behalf_lm,
        **_nd_kw(nodata, r["user"]["id"]),
        "current_band": r["current_band"], "incoming_band": r["incoming_band"], "adjusted": r["adjusted"],
        "pinned": bool(r.get("pinned")),
        "own_note": (own.get(r["user"]["id"]) or "").strip(),
        "score": r["shown"][0] if r.get("shown") else _fig1(r["score"]),
        "score_max": (_fig1(r["max"]) if r["max"] else None),
        "pct_360": r["pct_360"], "pct_tech": r["pct_tech"], "basis": r["basis"],
        "w_360": r.get("w_360"), "w_tech": r.get("w_tech"),
        "pts_360": _fig1(r.get("pts_360")), "max_360": r.get("max_360"), "pts_tech": _fig1(r.get("pts_tech")),
        "max_tech": r.get("max_tech"),
        # the competency as they answered it and as their line manager moderated it (Chris, 2026-10-01: "the
        # competency should show the self and line manager moderated score"); the two weighted parts of the score
        "tech_self": _fig1(r.get("tech_self")), "tech_self_max": r.get("tech_self_max"),
        "c_360": (r.get("shown") or (None, None, None))[1], "c_360_max": _fig1(r.get("c_360_max")),
        "c_tech": (r.get("shown") or (None, None, None))[2], "c_tech_max": _fig1(r.get("c_tech_max")),
        # their own score by their own competency answers: the Self row of the person's page (2026-10-05)
        "self_score": (r.get("self_shown") or (None,) * 4)[0], "self_max": (r.get("self_shown") or (None,) * 4)[1],
        "self_c_360": (r.get("self_shown") or (None,) * 4)[2], "self_c_tech": (r.get("self_shown") or (None,) * 4)[3],
        "raters": r["submitted"], "valid": r["valid"],
        "band_default": r.get("band_default", False), "pot_final": r.get("pot_final", True),
        "came_in": r.get("came_in"), "late": r.get("late"),
        "comp_status": r.get("comp_status"), "comp_pct": r.get("comp_pct"),
        "department": _row_get(r["user"], "department"), "job_title": _row_get(r["user"], "job_title"),
        "job_grade": _row_get(r["user"], "job_grade"), "unit": _row_get(r["user"], "company"),
        **calib_roster_fields(r["user"]),
        "trail": _pot_trail(db, r["user"], ctx["cycle_id"], tier),
        "is_self": r["user"]["id"] == u["id"],
        "finalised": bool(r["current_band"]) and r.get("pot_final", True), "n_why": None, "why_flag": None,
        "self_band": r.get("self_band"), "lm_band": r.get("lm_band"),
        # The band's journey up to this seat, as the calibration page's columns (Self -> LM -> HOD -> this tier)
        "chain": _pot_calib_chain(r, tier),
        # band_distribution_from_rows' rule, so a department's curve on the card counts exactly as the whole unit's
        "on_curve": bool((r["band_info"]["score_valid"] or r["adjusted"]
                          or (r["band_info"].get("source") or "raw") != "raw") and r["current_band"]),
        "strengths": sw.get(r["user"]["id"]),
        "remarks": rmk.get(r["user"]["id"]),   # what they, their LM (and for a BU CEO the HOD) wrote; None = own row
    } for r in rows]
    if ctx.get("grp"):   # a calibration group's own column: BU level, its calibrator's (2026-10-22)
        _co = _bu_co_calls(db, "pot", ctx["cycle_id"], [r["user"] for r in rows], ctx["grp"]["id"])
        for p_ in people:
            p_["chain"][-1]["tier"] = "BU level"
            if p_["id"] in _co:   # shared with other calibrators (2026-10-26)
                p_["co"] = dict(_co[p_["id"]], level=bu_blend_n(
                    [(p_["current_band"], _co[p_["id"]]["mine"])] + [(o["band"] or p_.get("came_in") or p_.get("current_band"), o["weight"])
                                                                     for o in _co[p_["id"]]["others"] if o["locked"]],
                    list(_POT_BANDS)))
    if review:   # the same order as its navigator (_pot_calib_people): who still needs a band first, the decided last
        people.sort(key=lambda p: ((p["name"] or "").lower(), p["id"]))
        people.sort(key=lambda p: _dept_review_rank(p["adjusted"], p["band_default"] or not p["current_band"],
                                                    p["is_self"]))
    if tier == "hod":
        lock_url = url_for("calibration_hod_lock", hod_id=key)
    elif tier == "buceo" and ctx.get("grp"):   # a calibration group locks on its own (2026-10-22)
        lock_url = url_for("calibration_bugroup_lock", gid=ctx["grp"]["id"])
    elif tier == "buceo":   # units calibrated together lock through their lead unit (row 6)
        lock_url = url_for("calibration_company_lock", bg=key[0], company=ctx["scope_key"])
    else:
        lock_url = url_for("calibration_bg_lock")
    return {"axis": "potential", "distribution": dist, "target": CALIBRATION_TARGET, "gaps": gaps,
            "curve": {"label": "15-70-15", "entered": True, "pct": None},
            "band_order": list(_POT_BANDS), "label_names": {b: b for b in _POT_BANDS},
            "tolerance": calib_tolerance(total), "breaches": breaches, "total": total,
            "locked": locked, "scope_label": ctx["scope_label"], "tier": tier, "rows": people, "lock_url": lock_url,
            "others": _pot_calib_others(db, ctx, tier), "group": bool(ctx.get("grp")),   # 4A, 2026-10-22
            "lock_bg": ctx["business_group"] if tier == "bgceo" else None,
            "mid_year": cycle_is_mid_year(db, ctx["cycle_id"]),   # the review is the last step (2026-10-12)
            "tol_rule": get_calib_rule(),   # a department's tolerance on the BU CEO's filtered curve (2026-10-13)
            # the department pill row, only where the super admin switched it on for this unit (2026-10-17); the JG row, the
            # filter line's chips (a calibrator with filters of its own reads those, 2026-11-02: calib_card_filters)
            **(calib_card_filters(db, ctx, key[0]) if tier == "buceo"
               else {"dept_filter": False, "jg_filter": None, "filters": []}),
            "review": review, "due": _window_due_disp(db, "pot_hod", ctx["cycle_id"]) if review else "",
            "unassigned": _dept_review_unassigned(people, pot=True) if review else [],
            "n_default": sum(1 for p in people if p.get("band_default")) if review else 0,
            "closed": ((_hod_review_closed(db, "pot", ctx["cycle_id"], ctx["population"], hod_id=ctx["scope_key"]) or "") if review
                       else (bg_closed or "")),
            "hod_open": ([n for m_ in _ctx_units(ctx) for _i, n in pot_hod_reviews_open(db, ctx["cycle_id"], key[0], m_)
                          if _i in {_row_get(p_, "hod_id") for p_ in ctx["population"]}]
                         if tier == "buceo" else []),
            "join": _join_payload(ctx)}


def _pot_calib_apply(db, u, sc, subject_id, band, justification, dry_run=False):
    """THE potential move from the journey -- the classic adjust routes' own checks (in scope, never yourself,
    Low/Mid/High only, not locked; the original band is the one they came in with) and their writer
    (_calibration_upsert_adjustment). (subject, None) or (None, error)."""
    tier, key, ctx = sc
    _mo = _module_off_msg("calibration", db=db, cycle_id=ctx.get("cycle_id"))   # a switched-off module stops its writes (1b-01)
    if _mo:
        return None, _mo
    _lo = leader_ability_off(db, u, leader_tier_ability(tier, "move", ctx))   # Roles & access › Leader roles (2026-10-20)
    if _lo:
        return None, _lo
    subject = next((p for p in ctx["population"] if p["id"] == subject_id), None)
    if not subject and tier == "buceo" and not ctx.get("grp"):   # a BU group sharing the call (split under 100)
        subject = next((p for p in (ctx.get("others") or []) if p["id"] == subject_id
                        and bu_group_split(bu_group_of(db, p)) < 100), None)
    if not subject:
        return None, "That person isn't in this scope."
    if subject_id == u["id"]:
        return None, _calib_self_msg(tier)
    band = (band or "").strip().capitalize()
    if band not in _POT_BANDS:
        return None, "Choose Low, Mid, or High."
    _t, _serr = _store_text((justification or "").strip(), "manager")
    if _serr:
        return None, _serr
    _over = _calib_remark_over(tier, justification)
    if _over:
        return None, _over
    sess = db.execute("SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier=? AND scope_key=?",
                      (ctx["cycle_id"], tier, ctx["scope_key"])).fetchone()
    if sess and sess["locked_at"]:
        return None, ("This department review is submitted." if tier == "hod"
                      else "This scope's potential calibration is locked.")
    if ctx.get("read_only"):   # units calibrated together: the lead unit's BU CEO calibrates, the others read (row 6)
        return None, _join_read_only_msg(db, dict(ctx, business_group=ctx["business_group"]))
    skey = subject["company"] if ctx.get("join") else ctx["scope_key"]   # each move on the person's own unit
    _bul = _tb_bu_lock_of(db, subject_id, cycle_id=ctx["cycle_id"]) if tier == "bgceo" else None
    if _bul:   # the BG CEO locked their business unit on the Talent Box (2026-10-07)
        return None, f"{_bul} is locked — its people can't be moved now."
    _bgc = (_bg_closed(db, "pot", ctx["cycle_id"], key[0], subject["company"] if ctx.get("grp") else skey)
            if tier == "buceo" else None)   # a group's person by their own unit (2026-10-22)
    if _bgc:   # ...which closes the BU CEO's calibration too: the BG CEO's decision is final (2026-10-07)
        return None, _bgc
    _w = (window_closed_tier(db, tier, "pot", ctx["cycle_id"], scope=_late_ctx_scopes(ctx))   # a late pass is its scope's
          if tier != "hod" else None)   # HOD: _hod_review_closed
    if _w:
        return None, _w
    original = ctx["band_fn"](db, subject, ctx["cycle_id"]).get("band") or ""
    if tier == "hod" and original:   # a score that isn't final brought nothing up (2026-10-01): the HOD sets it
        _res = subject_result(db, subject, ctx["cycle_id"])
        if not _pot_review_final(_res.get("score_valid"),
                                 _pot_review_comp(db, ctx["cycle_id"], [subject_id]).get(subject_id, (None, False))):
            original = ""
    if tier == "hod":   # the department review (2026-09-30): closed once the BU is locked; a change needs a remark
        closed = _hod_review_closed(db, "pot", ctx["cycle_id"], ctx["population"], hod_id=ctx["scope_key"])
        if closed:
            return None, closed
        if _hod_saved_already(db, "pot", sess["id"] if sess else None, subject_id):
            return None, _hod_saved_msg(subject["full_name"])
        if _hod_remark_needed(tier, band, original, justification):
            return None, HOD_REMARK_MSG
    if dry_run:   # every check passed; nothing written (the agent putting a band on the HOD's page, 2026-10-06)
        return subject, None
    sess = _get_or_create_calibration_session(
        db, ctx["cycle_id"], tier, skey, ctx["business_group"],
        (display_company(ctx["business_group"], skey) or skey) if ctx.get("join") else ctx["scope_label"])
    if ctx.get("join"):
        ctx["member_sessions"][skey] = sess
        if skey == ctx["scope_key"]:
            ctx["session"] = sess
    _calibration_upsert_adjustment(db, sess["id"], subject_id, original, band, (justification or "").strip(), u["id"])
    log_activity(db, u["id"], "calibration_adjust",
                 f"{subject['full_name']}: {original or 'No Data'} -> {band} ({tier} scope, journey)",
                 target_user_id=subject_id)
    return subject, None


def _pot_tool_show_distribution(db, u, sc, args):
    return {"ok": True, "displayed": "distribution",
            "render": {"type": "calib_distribution", "data": _pot_calib_overview(db, u, sc)}}


def _pot_tool_explain_person(db, u, sc, args):
    subj, err = _calib_resolve_subject(sc[2], args.get("subject"))
    if err:
        return {"ok": False, "error": err}
    row = next((r for r in _pot_calib_overview(db, u, sc)["rows"] if r["id"] == subj["id"]), None) or {}
    return {"ok": True, "name": subj["full_name"], "band_now": row.get("current_band"),
            "came_in_as": row.get("incoming_band"), "potential_score": row.get("score"),
            "out_of": row.get("score_max"), "raters_submitted": row.get("raters"),
            "includes_competency": row.get("basis") == "combined",
            "enough_feedback": row.get("valid"), "trail": row.get("trail"),
            "note": "the AI insight on the card summarises their 360 themes and competency -- point to it"}


def _pot_tool_move_band(db, u, sc, args):
    subj, err = _calib_resolve_subject(sc[2], args.get("subject"))
    if err:
        return {"ok": False, "error": err}
    just = args.get("justification")
    held = sc[0] == "hod" and not _dept_submit_asked()
    if sc[0] == "hod":
        just = _hod_keep_saved_remark((just or "").strip(), _calib_existing_note(db, "pot", sc, subj["id"]))
    s2, err = _pot_calib_apply(db, u, sc, subj["id"], args.get("band"), just, dry_run=held)
    if err:
        return {"ok": False, "error": err}
    _pb = (args.get("band") or "").strip().capitalize()
    if held:
        return _dept_held(subj, _pb, _pb, just)
    return {"ok": True, "moved": subj["full_name"], "band": _pb}


def _pot_tool_prepare_lock(db, u, sc, args):
    tier, key, ctx = sc
    _lo = leader_ability_off(db, u, leader_tier_ability(tier, "lock", ctx))   # a unit's bu.lock, a group's cg.lock
    if _lo:
        return {"ok": False, "error": _lo}
    sess = ctx["session"]
    if sess and sess["locked_at"]:
        return {"ok": False, "error": "This department review is already submitted." if tier == "hod"
                else "This scope's potential calibration is already locked."}
    pending = calibration_pending_children(db, ctx["cycle_id"], tier, ctx["business_group"],
                                           ctx["scope_key"] if tier == "buceo" else None) \
        if tier in ("buceo", "bgceo") else []
    data = dict(_pot_calib_overview(db, u, sc))
    if data.get("closed"):
        return {"ok": False, "error": data["closed"]}
    data["pending"] = [("%s (%s)" % (p[0], p[1]) if tier == "bgceo" else p[1]) for p in pending] if pending else []
    data["breach_message"] = _calib_breach_message(data["breaches"]) if data["breaches"] else ""
    data["lock_strict"] = calib_lock_strict()
    data["n_unbanded"] = sum(1 for r in data.get("rows") or [] if not r.get("current_band") and not r.get("is_self"))
    if data.get("unassigned"):   # an HOD bands everyone with no band first (2026-09-30)
        return {"ok": True, "ready": True, "blocked": _dept_review_unassigned_msg(data["unassigned"], pot=True),
                "render": {"type": "calib_lock", "data": data}}
    return {"ok": True, "ready": True, "render": {"type": "calib_lock", "data": data}}


_POT_CALIB_TOOLS = {"show_distribution": _pot_tool_show_distribution, "explain_person": _pot_tool_explain_person,
                    "move_band": _pot_tool_move_band, "prepare_lock": _pot_tool_prepare_lock}


def _pot_calib_run_tool(db, u, sc, action):
    tool = action.get("tool")
    args = action.get("args") or {}
    if not isinstance(args, dict):
        args = {}
    if sc[0] == "hod" and tool == "show_distribution":
        return {"ok": False, "error": _DEPT_REVIEW_NO_CURVE}
    if sc[0] == "hod" and tool == "open_person":
        return _dept_tool_open_person(sc[2], args)
    if tool == "search_kb":
        return _journey_tool_search_kb(db, args)
    if tool == "past_talent":   # BU / BG CEO only, only when asked (2026-10-22)
        return _past_talent_tool(db, sc[0], sc[2], args)
    fn = _POT_CALIB_TOOLS.get(tool)
    if not fn:
        return {"ok": False, "error": "unknown tool"}
    return fn(db, u, sc, args)


def _pot_calib_system(db, u, sc):
    tier, key, ctx = sc
    if tier == "hod":   # a department review has no curve (2026-09-30)
        return _dept_review_system(db, u, ctx, journey=True, axis="pot", sc=sc)
    ov = _pot_calib_overview(db, u, sc)
    tier_word = {"hod": "department", "buceo": "business unit", "bgceo": "business group"}.get(tier, "scope")
    roster = [{"name": r["name"], "band": r["current_band"], "came_in_as": r["incoming_band"], "moved": r["adjusted"],
               "potential_score": r["score"], "out_of": r["score_max"], "raters": r["raters"],
               "includes_competency": r.get("basis") == "combined",
               "enough_feedback": r["valid"], "is_you": r["is_self"]} for r in ov["rows"]]
    framework = {b: {"have": ov["distribution"][b], "target_pct": CALIBRATION_TARGET[b], "gap": ov["gaps"][b]}
                 for b in _POT_BANDS}
    parts = [
        "STAGE -- POTENTIAL CALIBRATION: help them calibrate the POTENTIAL bands (Low / Mid / High) of their %s (%s). "
        "The band comes from the 360 (how colleagues rated them on the leadership principles) and the competency "
        "assessment their line manager reviewed: the potential score on the card is the two, each weighted by the "
        "admin split for their grade, added up out of out_of; the band reads it as a share of that total. "
        "includes_competency=false "
        "means their competency isn't approved yet, so that score is the 360 alone (out of the 360's maximum) -- say "
        "so if you quote it." % (tier_word, ctx["scope_label"]),
        "THE FRAMEWORK: about 15%% Low, 70%% Mid, 15%% High, within a tolerance of %d %s in any band. Where it stands "
        "now:\n%s" % (ov["tolerance"], "person" if ov["tolerance"] == 1 else "people",
                     json.dumps(framework, ensure_ascii=False)),
        ("Bands OUTSIDE tolerance right now: %s." % json.dumps(ov["breaches"], ensure_ascii=False))
        if ov["breaches"] else "The spread is currently WITHIN the framework.",
        "The people in this scope:\n" + json.dumps(roster, ensure_ascii=False),
        "THE CURVE FIRST (Chris, 2026-09-30): the card opens on the CURVE -- the distribution and the roster, where "
        "they set each band in place (or use 'Fit the curve with AI'). Open on a person's row brings their page in BESIDE "
        "the folded curve (there is no view toggle): their potential score and band, what came in from the tier "
        "below, and an AI insight on their 360 themes and competency, with a pager and a back button. Talk about the "
        "curve; for a person, point to their Open on the roster. Nobody calibrates their OWN band.",
        "360 ANONYMITY (never break it): never say who rated them, how many people said what, or which relationship "
        "(manager, peer, direct report) thought what; never quote a comment; talk in themes only. Someone below the "
        "minimum number of raters has no valid 360 score yet -- say so, never guess.",
        'TOOLS for "action": show_distribution{} (the distribution + roster as a card); explain_person{subject} '
        '(their band, score, raters and the trail from the tier below); move_band{subject, band, justification} '
        '(band = Low / Mid / High; ALWAYS include the calibrator\'s OWN reason -- if they have not given one, ASK; '
        'never make one up); prepare_lock{} (brings the curve down to your reply, with its Lock button); '
        'search_kb{query}.',
        _MOVE_ASK_RULE,
        "THE FINISH: when the spread is within the framework (or they have a defensible reason), call prepare_lock{}. "
        "NEVER claim you have locked it; ONLY their Lock click locks it. If it still breaches, the Lock button asks "
        "for an override reason.",
    ]
    _gn = _bu_group_prompt_note(db, ctx, tier)
    if _gn:
        parts.append(_gn)
    if ctx["session"] and ctx["session"]["locked_at"]:
        parts.append("NOTE: this scope's potential calibration is already LOCKED. Do not move anyone -- explain warmly "
                     "and answer questions about it.")
    if tier in _PAST_TALENT_TIERS:   # BU / BG CEO: past years, only when asked (2026-10-22)
        parts.append('ALSO A TOOL: past_talent{subject} (their talent status in the three Year-Ends before this one). '
                     + _PAST_TALENT_BRIEF)
    _ln = _late_agent_note(db, u, "calibration_pot") if tier == "buceo" else ""   # more time Group People gave them (2026-10-31)
    if _ln:
        parts.append(_ln)
    return "\n\n".join(parts)


def _pot_calib_stage(tier=None):
    """The Potential calibration stage dict for the signed-in person's leader view (`tier`), or None."""
    if not has_request_context():
        return None
    cu = current_user()
    sc = _pot_calib_scope(get_db(), cu, tier=tier) if cu else None
    if not sc:
        return None
    ctx = sc[2]
    locked = bool(ctx["session"] and ctx["session"]["locked_at"])
    review = sc[0] == "hod"   # a department review (2026-09-30); closed once the BU is locked
    if review and not locked and _hod_review_closed(get_db(), "pot", ctx["cycle_id"], ctx["population"],
                                                     hod_id=ctx["scope_key"]):
        locked = True
    if sc[0] == "buceo" and not locked and _bg_closed(get_db(), "pot", ctx["cycle_id"], sc[1][0], sc[1][1]):
        locked = True   # closed by the BG CEO's lock (2026-10-07)
    return {"key": "calibration_pot", "module": "cal", "label": "Potential review" if review else "Potential calibration",
            "short": "Potential",
            "group": "team", "state": REVIEW_STATE_DONE if locked else REVIEW_STATE_OPEN,
            "n_open": 0 if locked else 1, "n_total": 1, "blocked_on": None, "endpoint": None,
            "tier": sc[0], "scope_label": ctx["scope_label"]}


def _pot_calib_people(db, u):
    sc = _pot_calib_scope(db, u)
    if not sc:
        return []
    locked = bool(sc[2]["session"] and sc[2]["session"]["locked_at"])
    closed = bool(sc[0] == "buceo" and not locked and _bg_closed(db, "pot", sc[2]["cycle_id"], sc[1][0], sc[1][1]))
    locked = locked or closed   # closed by the BG CEO's lock: done, as locked (2026-10-07)
    rows = _pot_calib_rows(db, sc[2])
    # a department review is done person by person (2026-10-06), as on performance
    out = [{"id": r["user"]["id"], "name": r["user"]["full_name"],
            "done": locked or (sc[0] == "hod" and bool(r.get("adjusted") or r["user"]["id"] == u["id"])),
            "scope_locked": locked, "closed": closed, "moved": sc[0] != "hod" and bool(r.get("adjusted")),
            "meta": r["current_band"] or "No band yet"} for r in rows]
    out.sort(key=lambda x: ((x["name"] or "").lower(), x["id"]))   # the card's order (by name)
    if sc[0] == "hod":   # a department review: the card's own order (_pot_calib_overview)
        rank = {r["user"]["id"]: _dept_review_rank(r["adjusted"], r.get("band_default") or not r["current_band"],
                                                   r["user"]["id"] == u["id"]) for r in rows}
        out.sort(key=lambda x: rank.get(x["id"], 1))
    return out


