@app.route("/performance/calibration/assist/chat", methods=["POST"])
@login_required
def pm_calib_chat():
    """One calibration-assistant turn. The model converses and proposes; the server
    runs every action through a validated tool and writes only via _pm_calib_apply
    (the grid's own path). The model can never lock -- that is the human's Lock click
    on the existing lock route."""
    u = current_user()
    db = get_db()
    if not _calib_assist_on(u):
        abort(404)
    tier, kw = _calib_assist_request_scope()
    ctx = _pm_calib_resolve(db, u, tier, **kw)
    cid, scope_key = ctx["period"]["id"], ctx["scope_key"]

    # Every exit carries an `overview`, so a degraded turn never wipes the pinned widget.
    def _degraded(say, **extra):
        ov = _pm_calib_assist_overview(db, u, ctx, tier, kw)
        return jsonify(ok=True, quick_replies=[], say=say, overview=ov["data"], **extra)

    # the super admin moves bands on the grid, where each change asks their remark for the audit trail (Chris,
    # 2026-10-17 / 10-18); a chat turn can't carry one, so the assistant never moves a band for them
    if is_super(u):
        return _degraded("As the super admin, change bands on the calibration grid: each change there asks your remark "
                         "for the audit trail.", done=True)
    if not ai_draft.review_agent_available():
        return _degraded("The calibration assistant isn't switched on yet -- you can still "
                         "use the calibration grid.", done=True)
    msg = (request.form.get("message") or "").strip()[:1000]
    if msg:
        db.execute("INSERT INTO pm_calib_chat(actor_id, cycle_id, tier, scope_key, role, content) "
                   "VALUES (?,?,?,?,'user',?)", (u["id"], cid, tier, scope_key, msg))
        db.commit()
    history = _calib_chat_history(db, u, cid, tier, scope_key)
    prior_history = list(history)   # the agent's last offer is read from it (4-06)
    system = _pm_calib_assist_system(db, u, ctx, tier)
    say, qr, steps, renders = "", [], 0, []
    band_refused, band_done = None, False
    while steps <= ai_draft.REVIEW_AGENT_MAX_TOOLS:
        steps += 1
        try:
            turn = ai_draft.review_agent(system, history)
            _screen_trace(db, u, turn, "leader")
        except ai_draft.AIDraftNotConfigured:
            return _degraded("The calibration assistant isn't switched on yet.", done=True)
        except ai_draft.AIDraftError:
            return _degraded("Sorry -- I lost the thread there. Could you say that again?")
        say, qr, action = turn["say"], turn["quick_replies"], turn["action"]
        if not action:
            break
        # Nothing is saved as a person's words unless they said it (or approved the wording) --
        # _person_text_guard, shared by every agent loop (2026-09-24).
        _person_text_tidy(action)   # a dictated "save it as it is:" lead-in is not their words (2026-10-31)
        _gerr = (_person_text_guard(history, action, _grounding_facts(db, u, cid))
                 if action.get("tool") in _PERSON_TEXT_TOOLS else None)
        if _gerr:
            history.append({"role": "agent", "content": say or "(drafting)"})
            history.append({"role": "tool", "content": json.dumps({"ok": False, "error": _gerr})[:700]})
            if steps > ai_draft.REVIEW_AGENT_MAX_TOOLS:   # the loop ends on a refusal -> never claim it saved
                say, qr = _GUARD_FALLBACK_SAY, []
            continue
        _bm_ok = True
        if action.get("tool") == "move_band" and tier != "hod":
            _bm_subj = (_calib_resolve_subject(ctx, (action.get("args") or {}).get("subject"))[0]
                        if isinstance(action.get("args"), dict) else None)
            _bm_ok = (_team_move_band_asked(msg, prior_history)
                      and _team_move_subject_bound(_bm_subj, msg, prior_history, _team_move_focus_id()))
            if not _bm_ok:   # ...else their EARLIER ask for this very move may carry it (4-06 follow-up, 2026-10-31)
                _bm_ok = _team_move_earlier_ask_ok(db, msg, prior_history, _bm_subj, action, "perf",
                                                   list(ctx["population"]) + list(ctx.get("others") or []))
        if not _bm_ok:
            # a band moves only on the leader's own ask, about the person they meant, here as in the journey's chat (4-06)
            band_refused = action
            history.append({"role": "agent", "content": say or "(waiting for their go-ahead)"})
            history.append({"role": "tool", "content": json.dumps(
                {"ok": False, "error": "NOT DONE -- they haven't asked for this move. OFFER it (a quick reply 'Move "
                                       "<name> to <band>') and do it only once they say yes"})})
            if steps > ai_draft.REVIEW_AGENT_MAX_TOOLS:   # the loop ends on a refusal -> never claim it moved
                say, qr = _TEAM_BAND_WAIT_SAY % "make that move", ["Move them"]
            continue
        result = _calib_run_tool(db, u, ctx, tier, kw, action)
        if action.get("tool") == "move_band" and isinstance(result, dict) and result.get("ok"):
            band_done = True
        # ANY card render is TERMINAL: one card per turn (show_distribution / prepare_lock),
        # so the model can't stack duplicate cards.
        if isinstance(result, dict) and result.get("render"):
            renders.append(result["render"])
            break
        if isinstance(result, dict) and result.get("ready"):
            break
        feed = {k: v for k, v in result.items() if k != "render"} if isinstance(result, dict) else result
        history.append({"role": "agent", "content": say or "(took an action)"})
        history.append({"role": "tool", "content": json.dumps(feed)[:400]})
        # A move may have changed the spread -> re-resolve ctx + rebuild the prompt.
        ctx = _pm_calib_resolve(db, u, tier, **kw)
        system = _pm_calib_assist_system(db, u, ctx, tier)
    if band_refused and not band_done and _TEAM_BAND_CLAIM_RE.search(say or ""):   # it claims a move that did not happen
        say, qr = _TEAM_BAND_WAIT_SAY % "make that move", ["Move them"]
    if say:
        db.execute("INSERT INTO pm_calib_chat"
                   "(actor_id, cycle_id, tier, scope_key, role, content, quick_replies, card) "
                   "VALUES (?,?,?,?,'agent',?,?,?)",
                   (u["id"], cid, tier, scope_key, say, json.dumps(qr) if qr else None,
                    json.dumps(renders) if renders else None))
        db.commit()
    ov = _pm_calib_assist_overview(db, u, ctx, tier, kw)
    return jsonify(ok=True, say=say, quick_replies=qr, renders=renders, overview=ov["data"])


@app.route("/performance/calibration")
@login_required
def pm_calibration_home():
    """Every calibration scope this login holds, for the active period.
    calibration_tier_of() is reused as-is: PM's cascade uses the same three
    roles, the same people and the same hod_id/buceo_*/bgceo_* wiring as the
    360 one, so a second resolver would only be able to drift from it."""
    u = current_user()
    db = get_db()
    period = active_pm_period(db)
    tiers = calibration_tier_of(db, u) if period else []
    scopes = []
    for tier, key in tiers:
        if tier == "bugrp":   # a BU calibration group's key is a 3-part tuple, not a business group (1b-06 / 3-09): it is
            continue          # the BU CEO tier's own page (the Performance journey), never a row of this chooser
        kw = ({"hod_id": key} if tier == "hod"
              else {"bg": key[0], "company": key[1]} if tier == "buceo"
              else {"bg": key})
        scope_key = _pm_calib_scope_key(tier, **kw)
        n = db.execute(
            f"SELECT COUNT(*) FROM users WHERE role!='admin' AND "
            f"{pm_calibration_population_sql()} AND " +
            ("hod_id=?" if tier == "hod" else
             "business_group=? AND company=?" if tier == "buceo" else "business_group=?"),
            [period["id"]] + ([key] if tier != "buceo" else [key[0], key[1]])).fetchone()[0]
        if not n:
            continue
        sess = db.execute(
            "SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier=? "
            "AND scope_key=?", (period["id"], tier, scope_key)).fetchone()
        scopes.append({
            "tier": tier, "url": _pm_calib_redirect(tier, **kw),
            "count": ("\u2014" if (tier == "bgceo" and _tb_hidden_msg(db, u)) else n),   # no head-count before the box opens
            "locked": bool(sess and sess["locked_at"]),
            "label": (db.execute("SELECT full_name FROM users WHERE id=?", (key,)).fetchone()["full_name"]
                      if tier == "hod" else
                      display_company(key[0], key[1]) if tier == "buceo" else display_bg(key)),
        })
    # Cross-org groups this person calibrates. Not part of calibration_tier_of()
    # -- that resolves the three ORG roles, and a group deliberately isn't one.
    if period:
        for g in db.execute(
                "SELECT * FROM pm_calibration_groups WHERE calibrator_id=? ORDER BY name",
                (u["id"],)).fetchall():
            n = db.execute(
                f"SELECT COUNT(*) FROM users WHERE role!='admin' AND "
                f"{pm_calibration_population_sql()} AND id IN "
                f"(SELECT subject_id FROM pm_calibration_group_members WHERE group_id=?)",
                (period["id"], g["id"])).fetchone()[0]
            if not n:
                continue
            sess = db.execute(
                "SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier='group' "
                "AND scope_key=?", (period["id"], str(g["id"]))).fetchone()
            scopes.append({
                "tier": "group", "url": _pm_calib_redirect("group", group_id=g["id"]),
                "count": ("\u2014" if _tb_hidden_msg(db, u) else n), "locked": bool(sess and sess["locked_at"]),
                "label": g["name"],
            })
    # A login with tiers but no scored population lands here, and it used to be
    # refused. The comment that stood here claimed the Hub "omits the door
    # entirely instead of showing it as restricted" -- it does not:
    # _pm_calibration_pending_count() counts unlocked tiers with no population
    # test, so the Hub badges this page as "1 awaiting your action" and then the
    # page refuses the three most senior personas mid-review. The same dead link
    # sits in the module tab strip on every calibration page they open.
    #
    # Holding a tier with nobody scored in it yet is a legitimate state, not a
    # permission error, so say that instead. This fixes the badge and the tab in
    # one place; narrowing the counter instead would have left the tab dead.
    # Someone who holds no tier at all is a different case and still refused.
    if not scopes:
        if not calibration_tier_of(db, u):
            abort(403)
        return render_template("pm_calibration_home.html", period=period, scopes=[],
                               box_scopes=[], no_population=True)
    # One scope -- which is the common case -- goes straight there. A chooser
    # whose only content is a single row is a click that asks nothing, and it
    # was the odd one out: calibration_home() and talent_box_home() both
    # redirect through already. The page below is only worth rendering when a
    # login really does hold several scopes (an HOD who is also a BUCEO, or
    # someone who also calibrates a cross-org group).
    if len(scopes) == 1:
        return redirect(scopes[0]["url"])
    # The box starts at business unit level, so an HOD-only login gets no
    # cross-link. (calibration_home() deliberately gets none at all: it
    # redirects straight through when you hold a single scope, so a link there
    # would be invisible to most of the people who'd want it. The Hub tile is
    # the discovery path.)
    return render_template("pm_calibration_home.html", period=period, scopes=scopes,
                           box_scopes=[s for s in scopes if s["tier"] != "hod"])


@app.route("/performance/calibration/override", methods=["POST"])
@login_required
def pm_calibration_override():
    """The super admin's ultimate right to set a band -- confirmed to work even
    on a scope that is already LOCKED, without unlocking it first.

    It writes to its own tier ('super', one session per period, never locked)
    rather than editing the locked tier's rows, so three things stay true: the
    tier's own record is preserved exactly as they left it, the override is
    unambiguous in the audit trail, and pm_effective_band() can rank it above
    every other tier with no special-casing.

    A super admin working inside an UNLOCKED scope can still just use the normal
    adjust control and act as that tier -- this is the deliberate, separate act,
    not a silent reinterpretation of every super-admin edit.

    The +-1 / 2+ band justification rule still applies: ultimate authority over
    the value, not an exemption from explaining a big swing."""
    u = current_user()
    if not is_super(u):
        abort(403)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    back = _local_path(request.form.get("back"), url_for("pm_calibration_home"))
    respond = lambda ok, msg, cat: (
        jsonify({"ok": ok, "error": None if ok else msg})
        if request.headers.get("X-Requested-With") == "XMLHttpRequest"
        else (flash(msg, cat), redirect(back))[1])

    subject_id = _form_int("subject_id")
    new_band = (request.form.get("adjusted_band", "") or "").strip()
    justification = (request.form.get("justification", "") or "").strip()
    subject = db.execute(
        f"SELECT * FROM users WHERE id=? AND role!='admin' AND "
        f"{pm_calibration_population_sql()}", (subject_id, period["id"])).fetchone()
    if not subject:
        return respond(False, "That person has no scorecard this period.", "error")
    # No justification is REQUIRED at any distance. Performance calibration starts
    # from a manager-approved rating that has already been through an approval
    # chain, so a large move is a judgement this tier is entitled to make --
    # confirmed decision, reversing this module's earlier 2-band rule. A note is
    # still offered on every row, still recorded, and still shown up the chain
    # when given: encouraged, not gated. (The Final bands queue asks a reason for
    # a band that isn't its suggestion; that is the queue's rule, not this tier's.)
    ok, msg = _pm_super_set(db, u, period, subject, new_band, justification)
    return respond(ok, ("Override saved — " + msg) if ok else msg, "ok" if ok else "error")


@app.route("/performance/calibration/override/clear", methods=["POST"])
@login_required
def pm_calibration_override_clear():
    """Drop a super override so the person falls back to whatever the normal
    cascade says. Also logged -- removing an override is as consequential as
    adding one."""
    u = current_user()
    if not is_super(u):
        abort(403)
    db = get_db()
    period = active_pm_period(db)
    if not period:
        abort(404)
    subject_id = _form_int("subject_id")
    back = _local_path(request.form.get("back"), url_for("pm_calibration_home"))
    db.execute(
        "DELETE FROM pm_calibration_adjustments WHERE subject_id=? AND session_id IN ("
        "SELECT id FROM pm_calibration_sessions WHERE cycle_id=? AND tier='super')",
        (subject_id, period["id"]))
    _rating_record_refresh(db, period["id"], [subject_id], "pm_super_override_clear", u["id"])
    db.commit()
    log_activity(db, u["id"], "pm_calibration_override_clear",
                 "super override cleared", target_user_id=subject_id)
    flash("Override cleared — back to the calibrated band.", "ok")
    return redirect(back)


