@app.route("/performance/calibration/group/<int:group_id>/lock-people", methods=["POST"])
@login_required
def pm_calibration_group_lock_people(group_id):
    """The Group Chief locks the people they ticked, or a whole department of their scope (canvas G2). Their own
    scope only (_pm_calib_resolve: the calibrator or the super admin); the locked calls go to Final bands."""
    u = current_user()
    db = get_db()
    ctx = _pm_calib_resolve(db, u, "group", group_id=group_id)
    back = redirect(url_for("pm_calibration_group_view", group_id=group_id))
    xhr = (request.headers.get("X-Requested-With") == "XMLHttpRequest"   # the Group view's card (canvas G2)
           or request.form.get("ajax") == "1")
    _w = window_closed_tier(db, "group", "both", scope=[str(group_id)])   # the BG CEO's Talent Box dates (Chris, 2026-11-04); a pass for THIS group opens it (2026-11-07); the super admin is not held to them
    if _w:
        if xhr:
            return jsonify({"ok": False, "error": _w, "window_closed": True})
        flash(_w, "error")
        return back
    dept = request.form.get("dept")
    if dept is not None:   # a department of one business group ("Finance, CHBM") -- and of one unit, from the card
        dbg = request.form.get("dept_bg") or ""
        dbu = request.form.get("dept_bu")
        sids = [p["id"] for p in ctx["population"]
                if (p["department"] or "").strip() == dept.strip() and (p["business_group"] or "") == dbg
                and (dbu is None or (p["company"] or "") == dbu)]
    else:
        sids = [int(x) for x in request.form.getlist("sid") if (x or "").isdigit()]
    if not sids:
        msg = "Tick the people to lock, or choose a department."
        if xhr:
            return jsonify({"ok": False, "error": msg})
        flash(msg, "error")
        return back
    done, skipped = group_lock_people(db, u, ctx, group_id, sids)
    msg = (("%d locked: their calls go to the super admin for the final band." % len(done) if done
            else "Nobody was locked.") + ((" Skipped: " + "; ".join(skipped[:5]) + ".") if skipped else ""))
    if xhr:
        return jsonify({"ok": bool(done), "locked": len(done), "message": msg, "error": None if done else msg})
    flash(msg, "ok" if done else "error")
    return back


