# ---------------------------------------------------------------------------
# GROUP CALIBRATION: a Group Chief across business groups, the super admin decides (Chris, 2026-10-10, canvas row G)
# ---------------------------------------------------------------------------
# "there might be exception for said CHGB where the Group Chief will act as BGCEO to calibrate for selected department.
# The selection should work cross BG too, e.g. CHGB Group CFO will calibrate the result of all the finance across all
# BGs" -- and later: how the two calls combine is the super admin's (replace / after / a blend like 50:50), "the final
# scoring goes to the super admin for decision ... with full audit trail", "Super admin would have the ability to choose
# the user list". Built on what exists: a scope is a pm_calibration_groups row (its calibrator is the Group Chief, a
# person sits in one), the Group Chief's calls are that group's tier rows, and the super admin's final band is the super
# tier (pm_calibration_override's, which outranks every tier). The combine mode is a per-group setting; it SUGGESTS the
# final, it never decides it.
GROUP_MODES = (("replace", "Replaces the BG CEO"), ("after", "After the BG CEO"), ("blend", "Both count"))


def calib_group_mode(gid):
    """{mode, bg, chief}: how a scope's two calls make the suggestion (default: the Group Chief comes after the BG CEO;
    a blend's weights are the BG CEO's and the Group Chief's out of 100)."""
    try:
        m = json.loads(_setting("calib_group_mode:%s" % gid, "") or "{}")
    except (TypeError, ValueError):
        m = {}
    mode = m.get("mode") if m.get("mode") in dict(GROUP_MODES) else "after"
    try:
        bg_w = max(0, min(100, int(m.get("bg", 50))))
    except (TypeError, ValueError):
        bg_w = 50
    return {"mode": mode, "bg": bg_w, "chief": 100 - bg_w}


def calib_group_mode_word(m):
    if m["mode"] == "blend":
        return "Both count, BG CEO %d : Group Chief %d" % (m["bg"], m["chief"])
    return dict(GROUP_MODES)[m["mode"]]


def _calib_group_mode_of(gid):
    """calib_group_mode, read once per request (pm_effective_band asks per person, inside loops over a whole BG)."""
    cache = _req_cache()
    k = "_cgm_%s" % gid
    if k not in cache:
        cache[k] = calib_group_mode(gid)
    return cache[k]


def group_locks(db, cycle_id, gid):
    """{subject_id: lock row (+ by_name)} -- the people whose call the Group Chief has locked this period."""
    return {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT gl.*, u.full_name AS by_name FROM pm_group_locks gl LEFT JOIN users u ON u.id=gl.locked_by "
        "WHERE gl.cycle_id=? AND gl.group_id=?", (cycle_id, gid))}


def group_lock_people(db, u, ctx, gid, sids):
    """Lock the Group Chief's call for these people (canvas G2): their group-tier band as it stands -- the band they
    moved them to, else the band they came in with, written as a kept row so the call is explicit. Only scope members
    with a final rating, never their own, never twice. Returns (locked ids, [why someone was skipped])."""
    period = ctx["period"]
    pid = period["id"]
    _w = window_closed_tier(db, "group", "both", pid, scope=[str(gid)])   # every Group Chief lock goes through here (Chris, 2026-11-04); a pass for THIS group opens it (2026-11-07)
    if _w:
        return [], [_w]
    sess = ctx["session"] or _pm_calib_get_or_create_session(db, pid, "group", str(gid), ctx["business_group"],
                                                             ctx["scope_label"])
    if sess["locked_at"]:
        return [], ["the whole group is locked already"]
    have = group_locks(db, pid, gid)
    pop = {p["id"]: p for p in ctx["population"]}
    done, skipped = [], []
    for sid in sids:
        p = pop.get(sid)
        if not p or sid in have or sid in done:
            continue
        if sid == u["id"]:
            skipped.append("your own band is the super admin's")
            continue
        ov = ctx["overalls"].get(sid)
        if not ov:
            skipped.append("%s's rating isn't final yet" % p["full_name"])
            continue
        adj = db.execute("SELECT adjusted_band FROM pm_calibration_adjustments WHERE session_id=? AND subject_id=?",
                         (sess["id"], sid)).fetchone()
        if adj:
            band = adj["adjusted_band"]
        else:
            band = (_pm_calib_incoming_fn(db, "group", pid)(p, ov) or {}).get("band")   # what the page shows
            if not band:
                skipped.append("%s has no band to lock" % p["full_name"])
                continue
            _pm_calib_upsert_adjustment(db, sess["id"], sid, band, band, "Kept as it came in", u["id"], seen_band=band)
        db.execute("INSERT INTO pm_group_locks(cycle_id, group_id, subject_id, band, locked_by) VALUES (?,?,?,?,?)",
                   (pid, gid, sid, band, u["id"]))
        _group_lock_pot(db, u, ctx, gid, p)   # both axes lock together (row 7)
        done.append(sid)
    db.commit()
    if done:
        _rating_record_refresh(db, pid, done, "pm_group_lock", u["id"], commit=True)
        log_activity(db, u["id"], "pm_group_lock", "%s: locked %d %s's call%s" % (
            ctx["scope_label"], len(done), "person" if len(done) == 1 else "people", "" if len(done) == 1 else "s"))
    return done, skipped


def _group_lock_pot(db, u, ctx, gid, p):
    """Lock the Group Chief's POTENTIAL call for one person beside their performance one (admin round 4, row 7): the
    band they moved them to on the group's potential session, else the band that came up (written as a kept row so the
    call is explicit). Nothing when there is no potential band at all."""
    cid = ctx["period"]["id"]
    if db.execute("SELECT 1 FROM pot_group_locks WHERE cycle_id=? AND group_id=? AND subject_id=?",
                  (cid, gid, p["id"])).fetchone():
        return
    sess = _get_or_create_calibration_session(db, cid, "group", str(gid), ctx["business_group"], ctx["scope_label"])
    adj = db.execute("SELECT adjusted_band FROM calibration_adjustments WHERE session_id=? AND subject_id=?",
                     (sess["id"], p["id"])).fetchone()
    if adj:
        band = adj["adjusted_band"]
    else:
        band = effective_band(db, p, cid, skip_tiers=("super", "group")).get("band")
        if not band:
            return
        _calibration_upsert_adjustment(db, sess["id"], p["id"], band, band, "Kept as it came in", u["id"])
    db.execute("INSERT INTO pot_group_locks(cycle_id, group_id, subject_id, band, locked_by) VALUES (?,?,?,?,?)",
               (cid, gid, p["id"], band, u["id"]))


def calib_suggest(bg_band, chief_band, m, order=None):
    """(suggested band or None, the two-band tie as 'ME or AE', why). Replace / after: the Group Chief's call, else the
    BG CEO's. Blend: each band counts as its place (UA 1 .. OU 5), weighted, rounded to the nearest band; exactly halfway
    is a tie the super admin picks."""
    if not chief_band:
        return bg_band, None, "only the BG CEO's call is in"
    if not bg_band or m["mode"] in ("replace", "after"):
        return chief_band, None, "the Group Chief's call" + ("" if bg_band else " (no BG CEO call)")
    if bg_band == chief_band:
        return bg_band, None, "both calls agree"
    order = list(order or PM_BAND_ORDER)   # potential: Low, Mid, High (row 7)
    a, b = order.index(bg_band), order.index(chief_band)
    x = (a * m["bg"] + b * m["chief"]) / 100.0
    lo = int(math.floor(x))
    if abs(x - lo - 0.5) < 1e-9:
        return None, "%s or %s" % (order[lo], order[lo + 1]), "halfway between the two calls"
    return order[int(round(x))], None, "the blend of the two calls"


def _pm_super_set(db, u, period, subject, new_band, justification, event="pm_super_override"):
    """THE super tier's write: set this person's band above every tier (one session per period, never locked), measured
    against what the cascade says without it, the ratings record refreshed, logged. (ok, message). Shared by the
    calibration override and the Final bands queue."""
    if new_band not in PM_BAND_ORDER:
        return False, "Choose a performance band."
    _t, _serr = _store_text((justification or "").strip(), "manager")
    if _serr:
        return False, _serr
    overall = pm_final_overalls(db, period["id"], [subject["id"]]).get(subject["id"])
    if not overall:
        return False, ("That person's rating isn't final yet — every KPI line has to be approved before it can be "
                       "calibrated.")
    session_row = _pm_calib_get_or_create_session(db, period["id"], "super", PM_SUPER_SCOPE_KEY,
                                                  subject["business_group"], "Super-admin overrides")
    existing = db.execute("SELECT original_band FROM pm_calibration_adjustments WHERE session_id=? AND subject_id=?",
                          (session_row["id"], subject["id"])).fetchone()
    incoming = pm_effective_band(db, subject, period["id"], overall["label"], skip_tiers=("super",))
    original = existing["original_band"] if existing else incoming["band"]
    _pm_calib_upsert_adjustment(db, session_row["id"], subject["id"], original, new_band, justification, u["id"],
                                seen_band=incoming["band"] or "")
    _rating_record_refresh(db, period["id"], [subject["id"]], event, u["id"], commit=True)
    log_activity(db, u["id"], "pm_calibration_override",
                 f"{subject['full_name']}: {original} -> {new_band} (super override of {incoming['source']} band)"
                 + (f" — {justification}" if justification else ""), target_user_id=subject["id"])
    return True, f"{subject['full_name']} is now {new_band}."


# P4b (2026-10-29): the Final bands queue is the super admin's, and the super admin MAY know the Executive Chairman locked a
# band (a leader's pages never say so). A person with a chair lock (a BU CEO who is also in a Group Chief's group, say) shows
# his locked band as the incoming / suggested band, labelled for the super admin only; the super tier stays above his, but
# "accept the suggestion" now accepts HIS band, never a Group Chief's or BG CEO's call written over it unseen, and the
# bulk "accept the clear ones" skips those rows (the super admin decides each one on its own).
CHAIR_QUEUE_WHY = "the Executive Chairman's lock"


def _final_bands_chair_band(db, cycle_id, axis, subject_id):
    """The Executive Chairman's LOCKED band for this person on this axis ('pm' | 'pot'), for the super admin's Final bands
    queue only (the page is super_required). None with the flag off or when he holds none."""
    return _chair_locked_band(db, cycle_id, axis, subject_id)


def _fb_members(db, gid, cycle_id, axis):
    """The people of one Group Chief's scope on one axis of the Final bands queue ('pm': with a scorecard this period; 'pot': in the
    potential calibration): the one read behind the queue's rows, the all-scopes file and the download panel's count of it."""
    if axis == "pot":
        return [dict(r) for r in db.execute(
            "SELECT u.* FROM pm_calibration_group_members gm JOIN users u ON u.id=gm.subject_id WHERE gm.group_id=? AND "
            "u.role!='admin' AND " + calibration_population_sql("u") + " ORDER BY u.business_group, u.company, "
            "u.department, u.full_name", (gid,))]
    return [dict(r) for r in db.execute(
        "SELECT u.* FROM pm_calibration_group_members gm JOIN users u ON u.id=gm.subject_id WHERE gm.group_id=? AND "
        "u.role!='admin' AND " + pm_calibration_population_sql("u") + " ORDER BY u.business_group, u.company, "
        "u.department, u.full_name", (gid, cycle_id))]


def _final_bands_rows(db, period, gid):
    """The Final bands queue for one scope: each member with a scorecard this period, their BG CEO's call (the cascade
    without the group and super tiers), the Group Chief's call, the suggestion and the final band (the super tier's)."""
    pid = period["id"]
    m = calib_group_mode(gid)
    people = _fb_members(db, gid, pid, "pm")
    ids = [p["id"] for p in people]
    overalls = pm_final_overalls(db, pid, ids) if ids else {}
    # the Group Chief's call counts once it is LOCKED -- the whole scope, or that person (pm_group_locks, canvas G2);
    # an unlocked one is a draft the super admin can see but not accept
    chief = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band, ca.justification, COALESCE(gl.locked_at, cs.locked_at) AS locked_at, "
        "gl.id AS person_lock FROM pm_calibration_adjustments ca "
        "JOIN pm_calibration_sessions cs ON cs.id=ca.session_id LEFT JOIN pm_group_locks gl ON gl.cycle_id=cs.cycle_id "
        "AND gl.group_id=? AND gl.subject_id=ca.subject_id WHERE cs.cycle_id=? AND cs.tier='group' "
        "AND cs.scope_key=?", (gid, pid, str(gid)))}
    final = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band, ca.justification, ca.adjusted_at, u.full_name AS by_name "
        "FROM pm_calibration_adjustments ca JOIN pm_calibration_sessions cs ON cs.id=ca.session_id "
        "LEFT JOIN users u ON u.id=ca.adjusted_by WHERE cs.cycle_id=? AND cs.tier='super' AND cs.scope_key=?",
        (pid, PM_SUPER_SCOPE_KEY))}
    rows = []
    for p in people:
        ov = overalls.get(p["id"])
        bg = pm_effective_band(db, p, pid, ov["label"], skip_tiers=("super", "group")) if ov else None
        c = chief.get(p["id"])
        draft = c["adjusted_band"] if (c and not c["locked_at"]) else None
        c = c if (c and c["locked_at"]) else None
        ec = _final_bands_chair_band(db, pid, "pm", p["id"])
        if ec:   # his locked band IS the incoming band (P4b): the super admin sees it, and nothing here writes over it unseen
            sug, tie, why = ec, None, CHAIR_QUEUE_WHY
        elif not ov:
            sug, tie, why = None, None, "the rating isn't final yet"
        elif not c:   # until the Group Chief locks, the person waits (canvas G2)
            sug, tie, why = None, None, ("the Group Chief hasn't locked their call" if draft
                                         else "waits on the Group Chief")
        else:
            sug, tie, why = calib_suggest(bg["band"] if bg else None, c["adjusted_band"], m)
        f = final.get(p["id"])
        rows.append({"p": p, "ready": bool(ov), "bg": bg["band"] if bg else None, "bg_src": bg["source"] if bg else None,
                     "chief": c["adjusted_band"] if c else None, "chief_why": (c["justification"] or "") if c else "",
                     "chief_at": c["locked_at"] if c else None, "person_lock": bool(c and c["person_lock"]),
                     "chief_day": _st_day(_myt(c["locked_at"])) if c else "",
                     "draft": draft, "sug": sug, "tie": tie, "why": why, "final": f, "chair": ec,
                     "agreed": bool(ov and c and sug and not tie and not f and not ec
                                    and (not bg or c["adjusted_band"] == bg["band"]
                                         or m["mode"] in ("replace", "after")))})
    return rows, m


def _pot_super_set(db, u, cycle_id, subject, new_band, justification, event="pot_final_band"):
    """THE super tier's potential write (admin round 4, row 7): the super admin's final potential band, above every tier
    (one session per cycle, never locked), measured against what the cascade says without it, the ratings record
    refreshed, logged. (ok, message). The potential twin of _pm_super_set."""
    if new_band not in TALENT_POTENTIAL_ORDER:
        return False, "Choose a potential band."
    _t, _serr = _store_text((justification or "").strip(), "manager")
    if _serr:
        return False, _serr
    sess = _get_or_create_calibration_session(db, cycle_id, "super", POT_SUPER_SCOPE_KEY, subject["business_group"],
                                              "Super-admin decisions")
    existing = db.execute("SELECT original_band FROM calibration_adjustments WHERE session_id=? AND subject_id=?",
                          (sess["id"], subject["id"])).fetchone()
    incoming = effective_band(db, subject, cycle_id, skip_tiers=("super",))
    original = existing["original_band"] if existing else (incoming.get("band") or "")
    _calibration_upsert_adjustment(db, sess["id"], subject["id"], original, new_band, justification, u["id"])
    _rating_record_refresh(db, cycle_id, [subject["id"]], event, u["id"], commit=True)
    log_activity(db, u["id"], "calibration_override",
                 f"{subject['full_name']}: potential {original or 'no band'} -> {new_band} (super, over the "
                 f"{incoming.get('source')} band)" + (f" — {justification}" if justification else ""),
                 target_user_id=subject["id"])
    return True, f"{subject['full_name']}'s potential is now {new_band}."


def _final_bands_rows_pot(db, cycle_id, gid):
    """The Final bands queue's POTENTIAL side for one scope (row 7): each member in the potential calibration, the BG
    CEO's call (the cascade without the group and super tiers), the Group Chief's call (counted once locked: the whole
    group, or that person -- pot_group_locks), the suggestion on Low / Mid / High, and the final band (the super tier's).
    The same row shape as _final_bands_rows."""
    m = calib_group_mode(gid)
    people = _fb_members(db, gid, cycle_id, "pot")
    chief = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band, ca.justification, COALESCE(gl.locked_at, cs.locked_at) AS locked_at, "
        "gl.id AS person_lock FROM calibration_adjustments ca JOIN calibration_sessions cs ON cs.id=ca.session_id "
        "LEFT JOIN pot_group_locks gl ON gl.cycle_id=cs.cycle_id AND gl.group_id=? AND gl.subject_id=ca.subject_id "
        "WHERE cs.cycle_id=? AND cs.tier='group' AND cs.scope_key=?", (gid, cycle_id, str(gid)))}
    final = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.adjusted_band, ca.justification, ca.adjusted_at, u.full_name AS by_name "
        "FROM calibration_adjustments ca JOIN calibration_sessions cs ON cs.id=ca.session_id "
        "LEFT JOIN users u ON u.id=ca.adjusted_by WHERE cs.cycle_id=? AND cs.tier='super' AND cs.scope_key=?",
        (cycle_id, POT_SUPER_SCOPE_KEY))}
    rows = []
    for p in people:
        bgb = effective_band(db, p, cycle_id, skip_tiers=("super", "group"))
        bg = bgb.get("band")
        c = chief.get(p["id"])
        draft = c["adjusted_band"] if (c and not c["locked_at"]) else None
        c = c if (c and c["locked_at"]) else None
        ec = _final_bands_chair_band(db, cycle_id, "pot", p["id"])
        if ec:   # his locked band IS the incoming band (P4b)
            sug, tie, why = ec, None, CHAIR_QUEUE_WHY
        elif not bg and not c:
            sug, tie, why = None, None, "no potential band yet"
        elif not c:
            sug, tie, why = None, None, ("the Group Chief hasn't locked their call" if draft
                                         else "waits on the Group Chief")
        else:
            sug, tie, why = calib_suggest(bg, c["adjusted_band"], m, order=TALENT_POTENTIAL_ORDER)
        f = final.get(p["id"])
        rows.append({"p": p, "ready": bool(bg or c), "bg": bg, "bg_src": bgb.get("source") if bg else None,
                     "chief": c["adjusted_band"] if c else None, "chief_why": (c["justification"] or "") if c else "",
                     "chief_at": c["locked_at"] if c else None, "person_lock": bool(c and c["person_lock"]),
                     "chief_day": _st_day(_myt(c["locked_at"])) if c else "",
                     "draft": draft, "sug": sug, "tie": tie, "why": why, "final": f, "chair": ec,
                     "agreed": bool(c and sug and not tie and not f and not ec
                                    and (not bg or c["adjusted_band"] == bg or m["mode"] in ("replace", "after")))})
    return rows, m


def _tb_initials(name):
    """The grid cell's faces: first letter of the first and last word that starts with a letter, upper case ("?" with none);
    the client's tbInitials."""
    w = [x for x in str(name or "").split() if x[:1].isalpha() and x[:1].isascii()]
    if not w:
        return "?"
    return (w[0][0] + (w[-1][0] if len(w) > 1 else "")).upper()


TB_R2_RANK = {"PIP/Improvement": 0, "Solid Core": 1, "Star": 2, "Super Star": 3}
TB_R2_POT_RANK = {"Low": 0, "Mid": 1, "High": 2}


def _tb_r2_when(raw, clock=False):
    """A stored UTC time as 'Thu 3 Dec' ('Thu 3 Dec, 10:12' with `clock`), MYT; '' when unset."""
    s_ = _myt(raw)
    try:
        d = datetime.strptime(str(s_)[:16], "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return ""
    return "%s %d %s%s" % (d.strftime("%a"), d.day, d.strftime("%b"), d.strftime(", %H:%M") if clock else "")


def _tb_r2_on(iso):
    """A MYT day 'YYYY-MM-DD' as 'Wed 9 Dec 2026'; '' when unset."""
    try:
        d = date.fromisoformat(str(iso)[:10])
    except ValueError:
        return ""
    return "%s %d %s %d" % (d.strftime("%a"), d.day, d.strftime("%b"), d.year)


def _tb_r2_curve_dict(dist, target, order, labels, label, gaps):
    """One axis's spread against its expected curve, as the Talent Box card hands the curve pop-outs (the overview's own `_curve`)."""
    n = sum(dist.values())
    return {"band_order": list(order), "label_names": labels, "distribution": dist, "target": target, "gaps": gaps,
            "total": n, "tolerance": calib_tolerance(n), "breaches": _calib_over_framework(gaps, n) if n else {},
            "curve": {"label": label}}


def _tb_r2_cell_key(perf, pot):
    return "%s|%s" % (TALENT_PERF_GROUP_OF.get(perf), pot)


def _tb_r2_as_round1(payload, marks, ru):
    """The admin card's payload as the ROUND 1 RECORD (Round 2 canvas board A / I: "Round 1 · Forecast still shows the box as the BG CEO
    locked it"): every person who has a Round 1 mark sits where the mark says, the curve cards read the forecast curve, nobody is
    shown as moved (the record keeps placements, not who moved them). Works on the page's own slim payload; writes nothing."""
    cells = {c["key"]: c for c in payload["cells"]}
    moved_in = [(c["key"], p) for c in payload["cells"] for p in c["people"]]
    for c in payload["cells"]:
        c["people"] = []
    for key, p in moved_in:
        mk = marks.get(p["id"])
        if mk and mk["perf"] and mk["pot"] and _tb_r2_cell_key(mk["perf"], mk["pot"]) in cells:
            key = _tb_r2_cell_key(mk["perf"], mk["pot"])
            p = dict(p, perf=mk["perf"], pot=mk["pot"], category=mk["category"] or p["category"])
        cells[key]["people"].append(dict(p, moved=False, up=False, from_cat="", from_key=""))
    for c in payload["cells"]:
        c["n"], c["moved"] = len(c["people"]), 0
        c["faces"] = [_tb_initials(p["name"]) for p in c["people"][:4]]
    for rw in payload["rows"]:
        rw["n"] = sum(c["n"] for c in payload["cells"] if c["pot"] == rw["key"])
    for cl in payload["cols"]:
        cl["n"] = sum(c["n"] for c in payload["cells"] if c["col"] == cl["key"])
    payload["moved_n"] = 0
    pd = {b: 0 for b in PM_BAND_ORDER}
    qd = {b: 0 for b in _POT_BANDS}
    for c in payload["cells"]:
        for p in c["people"]:
            if p["perf"] in pd:
                pd[p["perf"]] += 1
            if p["pot"] in qd:
                qd[p["pot"]] += 1
    key = ru["curve_before"] or "normal"
    live = (payload.get("perf_curve") or {}).get("curve") or {}
    perf = _tb_r2_curve_dict(pd, PM_DIST_CURVES[key], PM_BAND_ORDER, PM_LABEL_NAMES, PM_CURVE_LABELS[key][0],
                             pm_calibration_target_gaps(pd, PM_DIST_CURVES[key]))
    perf["curve"].update({"pct": ru["forecast_pct"], "entered": ru["forecast_pct"] is not None, "scope": live.get("scope")})
    payload["perf_curve"] = perf
    payload["pot_curve"] = _tb_r2_curve_dict(qd, CALIBRATION_TARGET, _POT_BANDS, {b: b for b in _POT_BANDS}, "15-70-15",
                                             calibration_target_gaps(qd, CALIBRATION_TARGET))
    payload["pat"] = ru["forecast_pct"]


def _tb_r2_moves_since_round1(payload, marks):
    """Round 2's card: `moved` / `from_cat` / `from_key` / `up` read against the Round 1 record (who moved since the BG CEO locked), the
    cells' and the foot's counts with them. A person with no Round 1 mark counts as not moved."""
    for c in payload["cells"]:
        c["moved"] = 0
        for p in c["people"]:
            mk = marks.get(p["id"])
            k1 = _tb_r2_cell_key(mk["perf"], mk["pot"]) if mk and mk["perf"] and mk["pot"] else None
            if k1 and k1 != c["key"] and mk["category"]:
                a_, b_ = (TB_R2_RANK.get(p["category"], 0), TB_R2_RANK.get(mk["category"], 0))
                up = a_ > b_ if a_ != b_ else (
                    (TALENT_PERF_GROUP_ORDER.index(c["col"]) + TB_R2_POT_RANK.get(c["pot"], 0))
                    > (TALENT_PERF_GROUP_ORDER.index(k1.split("|")[0]) + TB_R2_POT_RANK.get(k1.split("|")[1], 0)))
                p.update(moved=True, up=up, from_cat=mk["category"], from_key=k1)
                c["moved"] += 1
            else:
                p.update(moved=False, up=False, from_cat="", from_key="")
    payload["moved_n"] = sum(c["moved"] for c in payload["cells"])


def _tb_admin_round(db, me, ctx, bg, company, round_n, rs, payload, ceo_names, picked):
    """What the admin Talent Box's Round 1 / Round 2 toggle needs for the unit on screen (Talent Box Round 2, piece 2): {n, state, ...}
    for the template's strip, foot and confirm boxes, and the card's payload reworked in place (the Round 1 record for Round 1; moves
    since Round 1 for Round 2). Reads only; every write is piece 1's one writer behind the Round 2 routes."""
    pid = ctx["period"]["id"]
    sup = is_super(me)
    ru = next((x for x in rs["units"] if company in x["members"]), None)
    state = ru["state"] if ru else "none"
    r = {"n": round_n, "sup": sup, "state": state, "unit": (ru["label"] if ru else _talent_box_bu_label(bg, company)),
         "bg": bg, "bg_label": display_bg(bg), "ceo": ceo_names, "picked": bool(picked), "ru": ru, "mode": ru["mode"] if ru else None,
         "bg_locked": bool(ru and ru["bg_locked"]), "released": bool(ru and ru["released"]),
         "company": (ru["company"] if ru else company), "key": (ru["key"] if ru else company),
         "round_id": (ru["round_ids"][0] if ru and ru["round_ids"] else None), "shifted": bool(ru and ru["shifted"]),
         "forecast": (ru["forecast_text"] if ru else ""), "actual": (ru["actual_text"] if ru else ""),
         "before": (ru["curve_before_label"] if ru else ""), "after": (ru["curve_after_label"] if ru else ""),
         "remark_max": SUPER_BAND_REMARK_MAX, "hold": rs["hold"], "moved_n": 0,
         "can_write": bool(sup and round_n == 2), "editable": False,
         "opened": "", "opened_by": "", "locked": "", "locked_by": "", "due_on": "", "due_text": "", "due_default": "", "due_min": "",
         "reminded": "", "emailed": False}
    if ru and not r["before"]:   # a unit with no round row yet reads the curve its live PAT picks
        live = (payload.get("perf_curve") or {}).get("curve") or {}
        r["before"] = live.get("label") or ""
    if ru and ru["round_ids"] and state != "none":
        marks = {}
        for v in _tb_round1_view(db, ru["round_ids"]).values():
            marks.update(v["marks"])
        if round_n == 1:
            _tb_r2_as_round1(payload, marks, ru)
        else:
            _tb_r2_moves_since_round1(payload, marks)
        row = _tb_round_row(db, pid, bg, ru["key"])
        nm = lambda uid: (db.execute("SELECT full_name FROM users WHERE id=?", (uid,)).fetchone() or [""])[0] if uid else ""  # noqa: E731
        if row:
            r["opened"] = _tb_r2_when(row["opened_at"], True)
            r["opened_by"] = nm(row["opened_by"])
            r["locked"] = _tb_r2_when(row["locked_at"], True)
            r["locked_by"] = nm(row["locked_by"])
            _lr = db.execute("SELECT role FROM users WHERE id=?", (row["locked_by"],)).fetchone() if row["locked_by"] else None
            r["locked_gp"] = bool(_lr and _lr["role"] == "admin")   # finished by Group People, not by the BG CEO
            r["emailed"] = bool(row["emailed_at"])
            r["reminded"] = _tb_r2_when(row["reminded_at"], True)
            r["remark"] = row["remark"] or ""
    r["moved_n"] = payload.get("moved_n", 0) if round_n == 2 else 0
    if ru and ru["due_on"]:
        r["due_on"], r["due_text"] = ru["due_on"], _tb_r2_on(ru["due_on"])
    if sup and round_n == 2:
        d_, _w = _tb_round_due_on("")
        r["due_default"], r["due_min"] = d_.isoformat(), _today_myt().isoformat()
        r["editable"] = bool(ru and ((state == "open" and ru["mode"] == "admin") or state == "due") and not ru["released"])
    # the foot's one line: the lock state in words (the tone is the pill's border / tint)
    ft = None
    if round_n == 2 and ru:
        if state == "none" and not ru["bg_locked"]:
            ft = ("", "Round 2 starts after the BG CEO locks this unit")
        elif state == "none":
            ft = ("ok", "Round 1 locked by the BG CEO · Round 2 not started")
        elif state == "same":
            ft = ("ok", "Round 1 stands: the curve did not change")
        elif state == "waiting":
            ft = ("warn", "Round 1 locked · Round 2 not started")
        elif state == "open" and ru["mode"] == "bgceo":
            ft = ("warn", "With the BG CEO: not locked yet")
        elif state in ("open", "due") and not r["editable"]:
            ft = ("warn", "Round 2 is open: Group People are placing this unit" if state == "open"
                  else "Past its lock-by day: Group People finish it")
        elif state == "locked":
            ft = ("ok", "Round 2 locked by %s%s" % ("Group People" if (ru["mode"] == "admin" or r.get("locked_gp")) else "the BG CEO",
                                                    (", " + _tb_r2_when(ru["locked_at"])) if ru["locked_at"] else ""))
    r["foot"] = ft
    return r


@app.route("/admin/calibration/talent-box")
@admin_required
def admin_talent_box():
    """Calibration & Talent > Run > Talent Box (canvas J2, Chris 2026-10-10: "admin should have the same talent box
    view as BGCEO in the admin page"): the BG CEO's own box -- the same builder (_journey_talent_box_overview), so a
    cell, a count or a band can never differ from theirs -- one business unit at a time, read only. The BG CEO places
    and locks; an admin reads it. A BG admin sees their business group, a sub-admin their units."""
    from werkzeug.exceptions import HTTPException
    db = get_db()
    me = current_user()
    bgs = [b for b in org_bgs(db) if can_access_bg(me, b)]
    bg = (request.args.get("bg") or "").strip()
    if bg not in bgs:
        bg = admin_bg_of(me) if admin_bg_of(me) in bgs else (bgs[0] if bgs else "")
    data, ctx, why = None, None, None
    if not (active_pm_period(db) and active_cycle_id(db)):
        why = "There is no active cycle, so there is no Talent Box to show."
    elif bg:
        try:
            ctx = _talent_box_resolve(db, me, "bgceo", admin_view=True, bg=bg)
        except HTTPException:
            why = "Nobody in %s is in calibration this cycle." % display_bg(bg)
    units = [c for c in _tb_companies(ctx) if can_access(me, bg, c)] if ctx else []
    company = (request.args.get("company") or "").strip()
    round_n = 2 if request.args.get("round") == "2" else 1   # Round 1 · Forecast (today's page) | Round 2 · Actual (Talent Box Round 2, 2026-11-15)
    if ctx and units:
        if company not in units:
            bul = set(_tb_bu_locks(db, ctx["period"]["id"], bg))
            company = next((c for c in units if c not in bul), units[0])   # the next one the BG CEO has to do
        # every registry filter the unit has values for, the picks from this request (checked against the unit's own values
        # by the builder); the Settings rules govern the leaders' chips, not this page (Chris 2026-10-30, canvas board D)
        data = _journey_talent_box_overview(db, me, ("bgceo", {"bg": bg}, ctx), company=company, all_filters=True,
                                            picks={k: request.args.getlist(k) for k in CALIB_FILTER_KEYS})
    elif ctx:
        why = "None of your business units has anyone in calibration this cycle."
    lock = None
    if data and data["bu_locked"]:
        lock = db.execute("SELECT l.locked_at, u.full_name AS by_name FROM talent_box_bu_locks l LEFT JOIN users u "
                          "ON u.id=l.locked_by WHERE l.period_id=? AND l.business_group=? AND l.company=?",
                          (ctx["period"]["id"], bg, company)).fetchone()
    ceo = db.execute("SELECT full_name FROM users WHERE bgceo_bg=? AND left_at IS NULL ORDER BY full_name",
                     (bg,)).fetchall() if bg else []

    def slim(p):   # what the page draws, and nothing more (a unit can hold hundreds)
        return {"id": p["id"], "name": p["name"], "dept": p.get("dept") or "", "grade": p.get("grade") or "",
                "company": p.get("company") or "", "bu": p.get("bu") or "",
                "perf": p.get("perf"), "pot": p.get("pot"), "category": p.get("category") or "",
                "moved": bool(p.get("moved")), "up": bool(p.get("up")), "from_cat": p.get("from_cat") or "",
                "from_key": p.get("from_key") or "", "perf_src": p.get("perf_src"), "pot_src": p.get("pot_src"),
                "newly": bool(p.get("newly")), "behalf_lm": bool(p.get("behalf_lm")),
                **({"nodata": p["nodata"]} if p.get("nodata") else {}),
                **({"transfer": p["transfer"]} if p.get("transfer") else {}),
                "bugrp": ({"by": p["bugrp"].get("by") or "", "by_title": p["bugrp"].get("by_title") or ""}
                          if p.get("bugrp") else None),
                "url": url_for("admin_person", uid=p["id"], tab="history")}
    payload = None
    if data:   # the builder has already narrowed the cells, the unplaced and the counts to the picks
        cells = [{"key": c["key"], "col": c["col"], "pot": c["pot"], "label": c["label"] or "", "n": len(c["people"]),
                  "cat": re.sub(r"[^a-z]+", "-", (c["label"] or "").lower()),   # the cell's fill (the client's tbSlug)
                  "moved": sum(1 for p in c["people"] if p.get("moved")),
                  "faces": [_tb_initials(p["name"]) for p in c["people"][:4]],
                  "people": [slim(p) for p in c["people"]]} for c in data["cells"]]
        payload = {"cells": cells, "unplaced": data["unplaced"], "placed": data["placed"],
                   "cols": data["cols"], "rows": data["rows"], "band_order": data["band_order"],
                   "label_names": data["label_names"], "perf_curve": data["perf_curve"], "pot_curve": data["pot_curve"],
                   "filters": data["filters"], "show_n": data["show_n"], "show_m": data["show_m"],
                   "company": data["company"], "company_label": data["company_label"], "dept": data["dept"], "cal": data["cal"],
                   "bu_level": [{"key": x["key"], "who": x["who"]} for x in (data.get("bu_level") or [])],
                   "pat": data["pat"], "picks": data["picks"], "moved_n": sum(c["moved"] for c in cells)}
    # the kit's filter row (Chris, 2026-10-10): the business group. The unit pills, the Filter line, the grid and the people
    # panel are the BG CEO's own card (Chris 2026-10-30, canvas board F), drawn from the same data
    def href(**kw):
        return url_for("admin_talent_box", **{k: v for k, v in kw.items() if v})
    frows = []
    if len(bgs) > 1:
        frows.append({"label": "Business group", "opts": [{"label": display_bg(b), "n": None, "on": b == bg,
                                                           "href": href(bg=b, round=2 if round_n == 2 else None)} for b in bgs]})
    pills = []
    r2 = None
    if data:
        _co = {c["key"]: c for c in data["companies"]}
        # Talent Box Round 2 (piece 2): each unit's round state, for the pills, the strip, the foot and the card's own payload
        rs = _tb_rounds_for_bg(db, ctx["period"]["id"], bg)
        _ru = {m: x for x in rs["units"] for m in x["members"]}
        _tagw = {"waiting": ("warn", "Curve shifted"), "locked": ("ok", "Round 2 \u2713"), "due": ("warn", "Past lock-by day")}
        for c in units:
            ur = _ru.get(c)
            pat_ = (_co.get(c) or {}).get("pat")
            txt = _pat_text(pat_) if pat_ is not None else "PAT \u2014"
            ttl = (_pat_text(pat_) + " achievement") if pat_ is not None else "PAT achievement not entered"
            tag = None
            if ur and ur["actual_pct"] is not None:
                if round_n == 2:
                    txt = "PAT %s \u2192 %s" % (_pat_text(ur["forecast_pct"])[4:], _pat_text(ur["actual_pct"])[4:])
                    ttl = "Forecast %s, actual %s" % (_pat_text(ur["forecast_pct"])[4:], _pat_text(ur["actual_pct"])[4:])
                    tag = _tagw.get(ur["state"]) or (("navy", "With the BG CEO" if ur["mode"] == "bgceo" else "Round 2 \u00b7 admin")
                                                    if ur["state"] == "open" else None)
                else:
                    txt = _pat_text(ur["forecast_pct"]) if ur["forecast_pct"] is not None else "PAT \u2014"
                    ttl = "Forecast " + txt[4:] + " (the PAT the BG CEO locked on)"
            pills.append({"key": c, "label": _talent_box_bu_label(bg, c), "on": c == company,
                          "href": href(bg=bg, company=c, round=2 if round_n == 2 else None),
                          "locked": bool((_co.get(c) or {}).get("tb_locked")), "pat": txt, "pat_title": ttl,
                          "tag": tag[1] if tag else "", "tag_cls": tag[0] if tag else ""})
        r2 = _tb_admin_round(db, me, ctx, bg, company, round_n, rs, payload, [r_["full_name"] for r_ in ceo],
                             any(payload["picks"].get(k) for k in payload["picks"]) if payload.get("picks") else False)
        # what the card's script needs of Round 2 (the strip, the Move panel, Suggest with AI): ids and addresses, no names
        payload["round"] = round_n
        payload["r2"] = {"n": round_n, "state": r2["state"], "mode": r2["mode"], "editable": r2["editable"],
                         "can_write": r2["can_write"], "bg": bg, "company": r2["key"], "round_id": r2["round_id"],
                         "unit": r2["unit"], "before": r2["before"], "after": r2["after"], "forecast": r2["forecast"],
                         "actual": r2["actual"], "limits": data.get("limits") if r2["editable"] else None,
                         # the writes' addresses only where this card may write (the super admin's open admin round): a read only card holds none
                         **({"suggest_url": url_for("tb_round_suggest"), "apply_url": url_for("tb_round_apply"),
                             "move_url": url_for("talent_box_bgceo_move", bg=bg)} if r2["editable"] else {})}
    def _round_href(n):   # the toggle keeps the unit and every filter pick; only the round changes
        q = request.args.to_dict(flat=False)
        q.pop("round", None)
        q["bg"], q["company"] = [bg], [company]
        if n == 2:
            q["round"] = ["2"]
        return url_for("admin_talent_box") + "?" + urlencode(q, doseq=True)
    round_hrefs = {1: _round_href(1), 2: _round_href(2)} if data else {}
    lock_text = None   # Round 1's foot, in words; Round 2's is r2["foot"]
    if data:
        if r2 and r2["n"] == 1 and r2["state"] != "none":
            lock_text = "Round 1 locked by %s%s" % ((lock["by_name"] or "the BG CEO") if lock else "the BG CEO",
                                                    (" \u00b7 " + _st_day(_myt(lock["locked_at"]))) if lock else "")
        elif lock:
            lock_text = "Locked by %s \u00b7 %s" % (lock["by_name"] or "the BG CEO", _st_day(_myt(lock["locked_at"])))
        elif data["bu_locked"]:
            lock_text = "Locked by the BG CEO"
        else:
            lock_text = "Not locked yet: the BG CEO is still placing"
    return render_template("admin_talent_box.html", bgs=bgs, bg=bg, units=units, company=company, data=data,
                           frows=frows, pills=pills, payload=payload, lock=lock, why=why, r2=r2, round_n=round_n,
                           round_hrefs=round_hrefs, lock_text=lock_text, remark_max=SUPER_BAND_REMARK_MAX,
                           ceo=[r["full_name"] for r in ceo],
                           lock_day=_st_day(_myt(lock["locked_at"])) if lock else "",
                           pct_of=lambda n, tot: int(float(n) / tot * 100 + 0.5) if tot else 0,   # the client's Math.round(n / tot * 100)
                           pat_text=_pat_text)


@app.route("/admin/calibration/final-bands", methods=["GET", "POST"])
@super_required
def admin_final_bands():
    """Calibration & Talent > Run > Final bands (canvas G3): for each Group Chief's scope, the BG CEO's call and the
    Group Chief's side by side, the suggestion the scope's mode makes, and the final band, which is the super admin's:
    accept the suggestion, or choose another band. Every decision, clear and reopen carries the super admin's remark
    (_super_band_remark_gate) and is a super-tier row and an audit line; the queue downloads as CSV."""
    db = get_db()
    me = current_user()
    period = active_pm_period(db)
    groups = db.execute("SELECT g.*, u.full_name AS chief_name FROM pm_calibration_groups g JOIN users u "
                        "ON u.id=g.calibrator_id ORDER BY g.name").fetchall()
    gid = request.values.get("g", type=int) or (groups[0]["id"] if groups else None)
    group = next((x for x in groups if x["id"] == gid), None)
    # Performance | Potential (admin round 4, row 7): the super admin decides each final band on both axes
    axis = "pot" if request.values.get("axis") == "pot" else "pm"
    _rows_for = (lambda: _final_bands_rows_pot(db, period["id"], gid)) if axis == "pot" else \
        (lambda: _final_bands_rows(db, period, gid))
    _set = ((lambda p, band, why: _pot_super_set(db, me, period["id"], p, band, why)) if axis == "pot"
            else (lambda p, band, why: _pm_super_set(db, me, period, p, band, why, event="pm_final_band")))
    if request.method == "POST":
        if not (period and group):
            abort(400)
        rows, m = _rows_for()
        by = {r["p"]["id"]: r for r in rows}
        action = request.form.get("action")
        back = redirect(url_for("admin_final_bands", g=gid, **({"axis": "pot"} if axis == "pot" else {})))
        if action == "decide":
            r = by.get(_form_int("subject_id"))
            if not r:
                abort(404)
            band = (request.form.get("band") or "").strip()
            # every final band carries the super admin's remark (_super_band_remark_gate, Chris 2026-10-17 / 10-18),
            # the suggestion accepted as much as a band chosen against it
            reason = _super_remark_now()
            if not reason:
                flash("%s: write your remark first." % r["p"]["full_name"], "error")
                return back
            if band == r["sug"]:
                reason = "%s (accepted the suggestion: %s)" % (reason, r["why"])
            ok, msg = _set(r["p"], band, reason)
            flash(msg, "ok" if ok else "error")
            return back
        if action == "accept_agreed":
            done = 0
            remark = _super_remark_now()
            if not remark:
                flash("Write your remark first.", "error")
                return back
            for r in rows:
                if r["agreed"]:
                    ok, _m = _set(r["p"], r["sug"], "%s (accepted the suggestion: %s)" % (remark, r["why"]))
                    done += ok
            flash("%d final band%s accepted." % (done, "" if done == 1 else "s"), "ok")
            return back
        if action == "reopen":   # the Group Chief's lock of one person is lifted, so they can call it again
            r = by.get(_form_int("subject_id"))
            if not r or not r["person_lock"]:
                abort(404)
            db.execute("DELETE FROM %s WHERE cycle_id=? AND group_id=? AND subject_id=?"
                       % ("pot_group_locks" if axis == "pot" else "pm_group_locks"), (period["id"], gid, r["p"]["id"]))
            db.commit()
            _rating_record_refresh(db, period["id"], [r["p"]["id"]], "pm_group_reopen", me["id"], commit=True)
            log_activity(db, me["id"], "pm_group_reopen", "%s: %s reopened for the Group Chief" % (
                group["name"], r["p"]["full_name"]), target_user_id=r["p"]["id"])
            flash("%s is open again for the Group Chief." % r["p"]["full_name"], "ok")
            return back
        if action == "clear":
            r = by.get(_form_int("subject_id"))
            if not r or not r["final"]:
                abort(404)
            db.execute("DELETE FROM %s WHERE subject_id=? AND session_id IN (SELECT id FROM %s WHERE cycle_id=? AND "
                       "tier='super' AND scope_key=?)" % (("calibration_adjustments", "calibration_sessions")
                                                         if axis == "pot" else
                                                         ("pm_calibration_adjustments", "pm_calibration_sessions")),
                       (r["p"]["id"], period["id"], PM_SUPER_SCOPE_KEY))
            db.commit()
            _rating_record_refresh(db, period["id"], [r["p"]["id"]], "pm_final_band_clear", me["id"], commit=True)
            log_activity(db, me["id"], "pm_calibration_override_clear", "%s: final band cleared, back to the "
                         "cascade" % r["p"]["full_name"], target_user_id=r["p"]["id"])
            flash("%s is back to the calibrated band." % r["p"]["full_name"], "ok")
            return back
        abort(400)
    rows, m = _rows_for() if (period and group) else ([], calib_group_mode(0))
    if request.args.get("format") in ("csv", "xlsx") and group:
        return _csv_response("final_bands_%s%s.csv" % (re.sub(r"[^A-Za-z0-9]+", "_", group["name"]).strip("_"),
                                                       "_potential" if axis == "pot" else ""),
                             ["Employee ID", "Name", "Business group", "Unit", "Department", "BG CEO", "Group Chief",
                              "Group Chief locked (MYT)", "Suggested", "Final", "Reason", "Decided by",
                              "Decided at (MYT)"],
                             [[r["p"]["employee_id"], r["p"]["full_name"], r["p"]["business_group"], r["p"]["company"],
                               r["p"]["department"], r["bg"] or "", r["chief"] or "",
                               _myt(r["chief_at"]) or "", r["sug"] or r["tie"] or "",
                               (r["final"] or {}).get("adjusted_band", ""), (r["final"] or {}).get("justification") or "",
                               (r["final"] or {}).get("by_name") or "", _myt((r["final"] or {}).get("adjusted_at")) or ""]
                              for r in rows])
    locked = bool(period and group and db.execute(
        "SELECT 1 FROM %s WHERE cycle_id=? AND tier='group' AND scope_key=? AND locked_at IS NOT "
        "NULL" % ("calibration_sessions" if axis == "pot" else "pm_calibration_sessions"),
        (period["id"], str(gid))).fetchone())
    return render_template("admin_final_bands.html", period=period, groups=groups, group=group, rows=rows, mode=m,
                           mode_word=calib_group_mode_word(m), locked=locked, axis=axis,
                           bands=TALENT_POTENTIAL_ORDER if axis == "pot" else PM_BAND_ORDER,
                           n_agreed=sum(1 for r in rows if r["agreed"]),
                           n_final=sum(1 for r in rows if r["final"]),
                           n_chief=sum(1 for r in rows if r["chief"]))


def _group_people_matching(db, dept, bgs, exact=False):
    """Active, real people in the department `dept` (any case), in the chosen business groups (all when none): the scope
    builder's "Add the matching". `exact` is the department picked from the list (2026-10-19); without it, as rules
    saved before the list, the name only has to contain `dept`."""
    where, params = ["role!='admin'", "left_at IS NULL", "COALESCE(is_demo,0)=0"], []
    if dept and exact:
        where.append("LOWER(TRIM(COALESCE(department,''))) = ?")
        params.append(dept.strip().lower())
    elif dept:
        where.append("LOWER(COALESCE(department,'')) LIKE ?")
        params.append("%" + dept.lower().replace("%", "").replace("_", "") + "%")
    if bgs:
        where.append("business_group IN (%s)" % ",".join("?" * len(bgs)))
        params += list(bgs)
    return db.execute("SELECT id, full_name, employee_id, business_group, company, department FROM users WHERE "
                      + " AND ".join(where) + " ORDER BY business_group, company, full_name", params).fetchall()


def calib_dept_options(db):
    """[(department, {business group: people})] of active, real people, one name per department whatever its case: the
    calibration groups' department list (Chris, 2026-10-19: "it should run as dropdown for selection")."""
    out = {}
    for r in db.execute("SELECT LOWER(TRIM(department)) k, MAX(TRIM(department)) d, business_group bg, COUNT(*) n FROM users "
                        "WHERE role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0 AND "
                        "TRIM(COALESCE(department,''))!='' GROUP BY k, bg"):
        e = out.setdefault(r["k"], [r["d"], {}])
        e[1][r["bg"] or ""] = r["n"]
    return sorted((tuple(v) for v in out.values()), key=lambda x: x[0].lower())


def _calib_seg_from_form(form):
    """The batch name a group's add form chose: one of the group's names, a new one ("__new__" + segment_new), or none
    (their own department)."""
    seg = (form.get("segment") or "").strip()
    if seg == "__new__":
        seg = (form.get("segment_new") or "").strip()
    return seg[:60] or None


def _group_add(db, me, group, people, segment=None, source="person"):
    """Add these people to the scope: one scope per person, so anyone already in another is skipped and counted.
    `segment` is the name the super admin gives the batch (Chris, 2026-10-13); someone already in THIS group moves to
    it when one is given. (added, elsewhere)."""
    others = {r["subject_id"] for r in db.execute(
        "SELECT subject_id FROM pm_calibration_group_members WHERE group_id!=?", (group["id"],))}
    added = elsewhere = 0
    for p in people:
        if p["id"] in others:
            elsewhere += 1
            continue
        n = db.execute("INSERT OR IGNORE INTO pm_calibration_group_members(group_id, subject_id, segment, source) "
                       "VALUES (?,?,?,?)", (group["id"], p["id"], segment or None, source)).rowcount
        added += n
        if not n and segment:   # already in this group: they move to the batch's name
            db.execute("UPDATE pm_calibration_group_members SET segment=? WHERE group_id=? AND subject_id=?",
                       (segment, group["id"], p["id"]))
    if added or segment:
        _calib_group_rules_out(db, group["id"], [p["id"] for p in people], remove=True)
    return added, elsewhere


def calib_group_rules(gid):
    """{"rules": [{dept, bgs, segment, exact}], "out": [subject ids]}: the departments a group follows, each with the name
    its people show as (exact: picked from the department list, 2026-10-19; a rule from before matches by "contains"), and the people the super admin took out by hand while their department still matches (a refresh
    never adds them back). One app setting per group."""
    try:
        v = json.loads(_setting("calib_group_rules:%s" % gid, "") or "{}")
    except (TypeError, ValueError):
        v = {}
    rules = [r for r in (v.get("rules") or []) if isinstance(r, dict)]
    return {"rules": [{"dept": str(r.get("dept") or ""), "bgs": [str(b) for b in (r.get("bgs") or [])],
                       "segment": str(r.get("segment") or ""), "exact": bool(r.get("exact"))} for r in rules],
            "out": [int(x) for x in (v.get("out") or []) if str(x).isdigit()]}


def _calib_group_rules_save(db, gid, v):
    db.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES (?,?)",
               ("calib_group_rules:%s" % gid, json.dumps({"rules": v["rules"], "out": sorted(set(v["out"]))})))


def _calib_group_rules_out(db, gid, sids, remove=False):
    v = calib_group_rules(gid)
    out = set(v["out"])
    out = (out - set(sids)) if remove else (out | set(sids))
    if out != set(v["out"]):
        v["out"] = sorted(out)
        _calib_group_rules_save(db, gid, v)


def _group_refresh_plan(db, gid):
    """What Refresh from departments would do now (Chris, 2026-10-13: "2. yes"): who joins -- matching a department the
    group follows, in no other group, not taken out by hand -- and who leaves -- added by department and no longer in
    it, or gone from Chin Hin; anyone added by Employee ID stays whatever their department, and nobody whose call is
    locked or whose final band is decided leaves. Writes nothing. A fingerprint of the two lists, so Apply changes
    exactly what the preview showed."""
    v = calib_group_rules(gid)
    group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
    matched = {}
    for r in v["rules"]:
        for p in _group_people_matching(db, r["dept"], r["bgs"], r.get("exact")):
            matched.setdefault(p["id"], (p, r["segment"] or None))
    members = {m["subject_id"]: m for m in db.execute(
        "SELECT gm.subject_id, gm.segment, gm.source, u.full_name, u.department, u.business_group, u.company, "
        "u.left_at FROM pm_calibration_group_members gm JOIN users u ON u.id=gm.subject_id WHERE gm.group_id=?", (gid,))}
    others = {r[0] for r in db.execute("SELECT subject_id FROM pm_calibration_group_members WHERE group_id!=?", (gid,))}
    out = set(v["out"])
    chief = group["calibrator_id"] if group else None
    join = [{"id": sid, "name": p["full_name"], "segment": seg,
             "why": "%s in %s" % ((p["department"] or "").strip() or "no department",
                                  display_company(p["business_group"], p["company"]) or display_bg(p["business_group"]))}
            for sid, (p, seg) in sorted(matched.items(), key=lambda x: (x[1][0]["full_name"] or "").lower())
            if sid not in members and sid not in others and sid not in out and sid != chief]
    leave, held = [], []
    for sid, m in sorted(members.items(), key=lambda x: (x[1]["full_name"] or "").lower()):
        gone = bool(m["left_at"])
        if not gone and (m["source"] != "dept" or sid in matched):
            continue
        why = ("has left Chin Hin" if gone else "now in %s" % ((m["department"] or "").strip() or "no department"))
        x = {"id": sid, "name": m["full_name"], "why": why}
        (held if _calib_group_frozen(db, gid, sid) else leave).append(x)
    fp = hashlib.sha256(json.dumps([[x["id"] for x in join], [x["id"] for x in leave]]).encode()).hexdigest()[:16]
    return {"rules": v["rules"], "join": join, "leave": leave, "held": held, "fingerprint": fp,
            "elsewhere": sum(1 for sid in matched if sid in others and sid not in members),
            "out": sum(1 for sid in matched if sid in out and sid not in members)}


def _calib_group_frozen(db, gid, subject_id=None):
    """Why this calibration group (or this one member of it) can't change now, or None (Chris, 2026-10-13: "2 yes").
    Deleting a group or changing who is in it re-routes its people's bands, so once the Group Chief has locked the
    scope, nobody joins or leaves it; and a member the Group Chief locked one by one, or whose final band the super
    admin has decided, stays. (The combine mode only changes the suggestion, so it stays editable.)"""
    period = active_pm_period(db)
    if not period:
        return None
    pid, when = period["id"], _row_get(period, "name") or "this cycle"
    if db.execute("SELECT 1 FROM pm_calibration_sessions WHERE cycle_id=? AND tier='group' AND scope_key=? "
                  "AND locked_at IS NOT NULL", (pid, str(gid))).fetchone():
        return "its calibration is locked for %s" % when
    one = " AND subject_id=?" if subject_id else ""
    if db.execute("SELECT 1 FROM pm_group_locks WHERE cycle_id=? AND group_id=?" + one,
                  (pid, gid) + ((subject_id,) if subject_id else ())).fetchone():
        return ("the Group Chief has locked their call on them for %s" % when if subject_id
                else "the Group Chief has locked calls on some of its people for %s" % when)
    if db.execute("SELECT 1 FROM pm_calibration_adjustments ca JOIN pm_calibration_sessions cs ON cs.id=ca.session_id "
                  "WHERE cs.cycle_id=? AND cs.tier='super' AND cs.scope_key=? AND ca.subject_id IN (SELECT subject_id "
                  "FROM pm_calibration_group_members WHERE group_id=?)" + (" AND ca.subject_id=?" if subject_id else ""),
                  (pid, PM_SUPER_SCOPE_KEY, gid) + ((subject_id,) if subject_id else ())).fetchone():
        return ("their final band is decided for %s" % when if subject_id
                else "final bands are decided for some of its people for %s" % when)
    return None


def _gc_view(db, leaders=False):
    """The Group Chief groups' data for their panels (the groups, a matching count asked for with ?g=&dept=&gbg=, a
    refresh preview with ?refresh=): their own page's and Leaders › BG CEOs' (Chris, 2026-10-22: "move the Group Chief
    setting to the BGCEO setting page"). `leaders`: there ?bg= is the page's business group, never one to match."""
    period = active_pm_period(db)
    groups = []
    for g in db.execute(
            "SELECT g.*, u.full_name AS calibrator_name, u.employee_id AS calibrator_emp "
            "FROM pm_calibration_groups g JOIN users u ON u.id = g.calibrator_id "
            "ORDER BY g.name").fetchall():
        members = db.execute(
            "SELECT u.id, u.full_name, u.employee_id, u.business_group, u.company, u.department, gm.segment, gm.source "
            "FROM pm_calibration_group_members gm JOIN users u ON u.id = gm.subject_id "
            "WHERE gm.group_id=? ORDER BY u.full_name", (g["id"],)).fetchall()
        locked = False
        if period:
            s = db.execute("SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? "
                           "AND tier='group' AND scope_key=?",
                           (period["id"], str(g["id"]))).fetchone()
            locked = bool(s and s["locked_at"])
        # what holds the membership still: the whole group, or these members (2026-10-13)
        frozen = _calib_group_frozen(db, g["id"])
        held = set()
        if period and members:
            held = {r[0] for r in db.execute(
                "SELECT subject_id FROM pm_group_locks WHERE cycle_id=? AND group_id=?", (period["id"], g["id"]))}
            held |= {r[0] for r in db.execute(
                "SELECT ca.subject_id FROM pm_calibration_adjustments ca JOIN pm_calibration_sessions cs ON "
                "cs.id=ca.session_id WHERE cs.cycle_id=? AND cs.tier='super' AND cs.scope_key=?",
                (period["id"], PM_SUPER_SCOPE_KEY))}
        segs = {}
        for m_ in members:
            if m_["segment"]:
                segs[m_["segment"]] = segs.get(m_["segment"], 0) + 1
        groups.append({"g": g, "members": members, "locked": locked, "mode": calib_group_mode(g["id"]),
                       "locks": gc_group_locks(db, g["id"]),
                       "frozen": frozen, "held": held, "rules": calib_group_rules(g["id"])["rules"],
                       "segments": sorted(segs.items(), key=lambda x: x[0].lower()),
                       "bgs": sorted({m_["business_group"] for m_ in members if m_["business_group"]})})
    # "Add the matching": the count first, for the scope it was asked for (GET ?g=&dept=&bg=)
    preview = None
    pg_id = request.args.get("g", type=int)
    _mbgs = request.args.getlist("gbg") or ([] if leaders else request.args.getlist("bg"))   # the BGs to match
    if pg_id and (request.args.get("dept") or _mbgs):
        dept = (request.args.get("dept") or "").strip()
        bgs = [b for b in _mbgs if b in org_bgs(db)]
        exact = request.args.get("exact") == "1"
        ppl = _group_people_matching(db, dept, bgs, exact)
        others = {r["subject_id"]: r["group_id"] for r in db.execute(
            "SELECT subject_id, group_id FROM pm_calibration_group_members")}
        preview = {"g": pg_id, "dept": dept, "bgs": bgs, "exact": exact, "n": sum(1 for x in ppl if x["id"] not in others),
                   "already": sum(1 for x in ppl if others.get(x["id"]) == pg_id),
                   "elsewhere": sum(1 for x in ppl if x["id"] in others and others[x["id"]] != pg_id),
                   "by_bg": sorted({x["business_group"] for x in ppl})}
    refresh = None   # "Refresh from departments": who would join and leave, nothing written (GET ?refresh=)
    rg = request.args.get("refresh", type=int)
    if rg and db.execute("SELECT 1 FROM pm_calibration_groups WHERE id=?", (rg,)).fetchone():
        refresh = dict(_group_refresh_plan(db, rg), g=rg)
    for row in groups:   # the split (2026-10-22): the Group Chief's share; Replaces / After the BG CEO = 100
        row["share"] = gc_chief_share(row["mode"])
    return dict(groups=groups, period=period, modes=GROUP_MODES, all_bgs=org_bgs(db), preview=preview, refresh=refresh,
                dept_opts=calib_dept_options(db))


def gc_chief_share(m):
    """A Group Chief group's split as the Group Chief's share of 100 (Chris, 2026-10-22: "let admin decide the ratio
    ... Group Chief vs BGCEO"): Replaces / After the BG CEO = 100 (the BG CEO reads only), Both count = its numbers."""
    return 100 if m["mode"] in ("replace", "after") else m["chief"]


GC_READS_ONLY_MSG = ("%s is calibrated by their Group Chief (%s): you see their band, and the group's split gives "
                     "the whole call to the Group Chief.")


def gc_reads_only(db, subject_id):
    """The Group Chief group's name when this person's group takes the whole call (share 100), else None: the BG CEO
    sees their band and never moves it (Chris, 2026-10-22, the split's 100 : 0)."""
    gid = calibration_group_of(db, subject_id)
    if not gid or gc_chief_share(_calib_group_mode_of(gid)) < 100:
        return None
    r = db.execute("SELECT name FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
    return r["name"] if r else None


def bu_group_locks(db, gid):
    """{pm, pot}: when a BU group's calibration was locked this cycle on each axis, else None -- its panel's lines and
    the super admin's Unlock beside them (Chris, 2026-10-23)."""
    period, cid, key = active_pm_period(db), active_cycle_id(db), BU_GROUP_PREFIX + str(gid)
    pm = db.execute("SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=? "
                    "AND locked_at IS NOT NULL", (period["id"], key)).fetchone() if period else None
    pot = db.execute("SELECT locked_at FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' AND scope_key=? "
                     "AND locked_at IS NOT NULL", (cid, key)).fetchone() if cid else None
    return {"pm": pm["locked_at"] if pm else None, "pot": pot["locked_at"] if pot else None}


def gc_group_locks(db, gid):
    """{pm, pot, people}: a Group Chief group's locks this cycle -- the whole group on each axis (when), and how many
    people the Group Chief locked one by one (the super admin's Unlock, 2026-10-23)."""
    period = active_pm_period(db)
    if not period:
        return {"pm": None, "pot": None, "people": 0}
    pid = period["id"]
    pm = db.execute("SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier='group' AND scope_key=? "
                    "AND locked_at IS NOT NULL", (pid, str(gid))).fetchone()
    pot = db.execute("SELECT locked_at FROM calibration_sessions WHERE cycle_id=? AND tier='group' AND scope_key=? "
                     "AND locked_at IS NOT NULL", (pid, str(gid))).fetchone()
    n = db.execute("SELECT COUNT(*) FROM (SELECT subject_id FROM pm_group_locks WHERE cycle_id=? AND group_id=? UNION "
                   "SELECT subject_id FROM pot_group_locks WHERE cycle_id=? AND group_id=?)", (pid, gid, pid, gid)).fetchone()
    return {"pm": pm["locked_at"] if pm else None, "pot": pot["locked_at"] if pot else None, "people": n[0]}


def _gc_group_unlock(db, me, group, days=None, remark=None):
    """The super admin's unlock of a Group Chief group (Chris, 2026-10-23: "add an unlock button for the groups and can
    only operated by super admin"): the whole group on both axes and the people the Group Chief locked one by one, so
    they can call and lock again. Their calls stay as they left them, the super admin's Final bands stay, and nothing
    built on it unlocks with it (as a unit's unlock). Since 2026-11-07 it is _unlock_scope's "group" (days and a pass for the
    Group Chief once the Talent Box's date has passed). (ok, message)."""
    return _unlock_scope(db, me, "group", group["id"], days=days, remark=remark)


@app.route("/admin/performance/calibration-groups", methods=["GET", "POST"])
@super_required
def admin_pm_calibration_groups():
    """Super-admin: define calibration groups that cut across BG, company and
    department -- for dotted-line and multiple-reporting cases, e.g. every IT
    shared-service and business partner calibrated by the CTO.

    Super-only by design: a group deliberately overrides the normal line, so
    letting a BG admin create one would let them reassign who calibrates people
    outside their own scope."""
    db = get_db()
    me = current_user()
    _lbg = (request.form.get("return_bg") or "").strip()   # made on Leaders › BG CEOs (2026-10-22): back there

    def _here(**kw):
        return (url_for("admin_leaders", tab="bgceo", bg=_lbg, **kw) if _lbg
                else url_for("admin_pm_calibration_groups", **kw))

    def _back(gid=None):
        # a change made in a group's side panel comes back with that panel open (#group-<id>; phase 3 of the admin
        # side panels, 2026-10-17); a new group opens straight away, to add its people
        if gid and db.execute("SELECT 1 FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone():
            return redirect(_here() + "#group-%d" % gid)
        return redirect(_here())

    if request.method == "POST":
        action = request.form.get("action", "")
        # locked calls hold the membership still (2026-10-13): the whole group for an add, a delete or a scope lock,
        # the one person for a removal
        if action in ("add_member", "add_matching", "paste_ids", "remove_member", "delete", "refresh"):
            _gid = _form_int("group_id")
            _why = (_calib_group_frozen(db, _gid, _form_int("subject_id")) if action == "remove_member"
                    else _calib_group_frozen(db, _gid))
            if action in ("add_member", "add_matching", "paste_ids", "refresh") and _why and "some of its people" in _why:
                _why = None   # a person locked one by one doesn't stop others joining
            if _why:
                flash("Not changed: %s, and changing who is in the group would change bands already called." % _why,
                      "error")
                return _back(_gid)
        if action == "create":
            name = (request.form.get("name", "") or "").strip()
            emp = (request.form.get("calibrator", "") or "").strip()
            cal = db.execute("SELECT id, full_name FROM users WHERE employee_id=? "
                             "AND role!='admin' AND left_at IS NULL", (emp,)).fetchone()
            if not name:
                flash("Give the group a name.", "error")
            elif not cal:
                flash(f"No employee found with ID {emp}.", "error")
            elif db.execute("SELECT 1 FROM pm_calibration_groups WHERE name=?", (name,)).fetchone():
                flash(f"A group called {name} already exists.", "error")
            else:
                _gid = db.execute("INSERT INTO pm_calibration_groups(name, calibrator_id, created_by) "
                                  "VALUES (?,?,?)", (name, cal["id"], me["id"])).lastrowid
                _fn = _line_changed(db, [_line_seat(cal["id"], "gc", None, _gid)], me["id"])   # the Group Chief seat given (2026-11-13)
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_create",
                             f"{name} (calibrator: {cal['full_name']})")
                flash(f"Group {name} created.{_line_tail(_fn)}", "ok")
        elif action == "add_member":
            gid = _form_int("group_id")
            emp = (request.form.get("employee_id", "") or "").strip()
            group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
            sub = db.execute("SELECT id, full_name FROM users WHERE employee_id=? AND role!='admin' AND left_at IS NULL",
                             (emp,)).fetchone()
            if not group:
                abort(404)
            if not sub:
                flash(f"No employee found with ID {emp}.", "error")
            else:
                # One group per person: without this two groups could each claim
                # the same person and the precedence chain would have no
                # principled way to rank them.
                other = db.execute(
                    "SELECT g.name FROM pm_calibration_group_members gm "
                    "JOIN pm_calibration_groups g ON g.id = gm.group_id "
                    "WHERE gm.subject_id=? AND gm.group_id != ?", (sub["id"], gid)).fetchone()
                if other:
                    flash(f"{sub['full_name']} is already in {other['name']} — a person "
                          f"can only belong to one calibration group.", "error")
                else:
                    _group_add(db, me, group, [sub], _calib_seg_from_form(request.form))
                    db.commit()
                    log_activity(db, me["id"], "pm_calib_group_add",
                                 f"{sub['full_name']} -> {group['name']}",
                                 target_user_id=sub["id"])
                    flash(f"{sub['full_name']} added to {group['name']}.", "ok")
        elif action == "unlock":
            # the super admin reopens the group (2026-10-23), with the remark every band action asks
            gid = _form_int("group_id")
            group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
            if not group:
                abort(404)
            ok, msg = _gc_group_unlock(db, me, group, days=request.form.get("days"), remark=request.form.get("remark"))
            flash(msg, "ok" if ok else "error")
            return _back(gid)
        elif action in ("set_mode", "add_matching", "paste_ids"):
            # the scope's combine mode and its people list (canvas G1, 2026-10-10)
            gid = _form_int("group_id")
            group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
            if not group:
                abort(404)
            if action == "set_mode":
                if "chief_share" in request.form:   # the split (2026-10-22): the Group Chief's share of 100
                    try:
                        _sh = int(request.form.get("chief_share") or 100)
                    except ValueError:
                        _sh = -1
                    if not 1 <= _sh <= 100:
                        flash("The Group Chief's share is between 1 and 100 (the BG CEO has the rest).", "error")
                        return _back(gid)
                    mode, bg_w = ("replace", 50) if _sh == 100 else ("blend", 100 - _sh)
                else:
                    mode = request.form.get("mode")
                    if mode not in dict(GROUP_MODES):
                        abort(400)
                    try:
                        bg_w = int(request.form.get("bg_weight") or 50)
                    except ValueError:
                        bg_w = -1
                if mode == "blend" and not 0 < bg_w < 100:
                    flash("A blend needs the BG CEO's share between 1 and 99 (the Group Chief has the rest).", "error")
                    return _back(gid)
                db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",
                           ("calib_group_mode:%s" % gid, json.dumps({"mode": mode, "bg": bg_w if mode == "blend"
                                                                     else 50})))
                db.commit()
                m = calib_group_mode(gid)
                _w = ("Group Chief %d : BG CEO %d" % (gc_chief_share(m), 100 - gc_chief_share(m))
                      if "chief_share" in request.form else calib_group_mode_word(m))   # said as the split (2026-10-22)
                log_activity(db, me["id"], "pm_calib_group_mode", "%s: %s" % (group["name"], _w))
                flash("%s: %s." % (group["name"], _w), "ok")
            elif action == "add_matching":
                dept = (request.form.get("dept") or "").strip()
                bgs = [b for b in request.form.getlist("bg") if b in org_bgs(db)]
                if not dept and not bgs:
                    flash("Choose a department name or a business group to match.", "error")
                    return _back(gid)
                seg = _calib_seg_from_form(request.form)
                exact = request.form.get("dept_exact") == "1"   # picked from the department list
                added, elsewhere = _group_add(db, me, group, _group_people_matching(db, dept, bgs, exact), seg, "dept")
                if dept and request.form.get("follow") == "1":   # the group follows it: Refresh keeps it in step
                    _rv = calib_group_rules(gid)
                    _rv["rules"] = [r for r in _rv["rules"] if (r["dept"].lower(), sorted(r["bgs"])) !=
                                    (dept.lower(), sorted(bgs))] + [{"dept": dept, "bgs": bgs, "segment": seg or "",
                                                                      "exact": exact}]
                    _calib_group_rules_save(db, gid, _rv)
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_add", "%s: added %d matching department '%s' in %s" % (
                    group["name"], added, dept or "any", ", ".join(bgs) or "every business group"))
                flash("Added %d to %s.%s" % (added, group["name"], (" %d already sit in another scope and were left "
                                                                     "there." % elsewhere) if elsewhere else ""), "ok")
            else:
                raw = re.split(r"[\s,;]+", request.form.get("ids") or "")
                eids = [x.strip() for x in raw if x.strip()]
                # an ID can be another of a person's IDs (a linked ID, 2026-10-29): the person, once, under their main ID
                _res = {e_: r_ for e_, (r_, _v) in _eid_resolve_many(db, eids).items()
                        if r_["role"] != "admin" and r_["left_at"] is None}
                found = list({r_["id"]: r_ for r_ in _res.values()}.values())
                unknown = sorted(set(eids) - set(_res))
                added, elsewhere = _group_add(db, me, group, found, _calib_seg_from_form(request.form))
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_add", "%s: added %d by Employee ID" % (group["name"], added))
                flash("Added %d to %s.%s%s" % (added, group["name"], (" %d already sit in another scope." % elsewhere)
                                               if elsewhere else "",
                                               (" Not found: %s." % ", ".join(unknown[:10])) if unknown else ""),
                      "ok" if not unknown else "warn")
            return _back(gid)
        elif action == "remove_member":
            gid, sid = _form_int("group_id"), _form_int("subject_id")
            db.execute("DELETE FROM pm_calibration_group_members WHERE group_id=? AND subject_id=?",
                       (gid, sid))
            _calib_group_rules_out(db, gid, [sid])   # taken out by hand: a refresh never adds them back
            db.commit()
            log_activity(db, me["id"], "pm_calib_group_remove", f"removed from group {gid}",
                         target_user_id=sid)
            flash("Removed from the group.", "ok")
        elif action in ("rename_segment", "drop_rule", "refresh"):   # batch names and departments followed (2026-10-13)
            gid = _form_int("group_id")
            group = db.execute("SELECT * FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
            if not group:
                abort(404)
            if action == "rename_segment":
                old = (request.form.get("old") or "").strip()
                new = (request.form.get("new") or "").strip()[:60]
                if not old or not new:
                    flash("Type the new name.", "error")
                    return _back(gid)
                n = db.execute("UPDATE pm_calibration_group_members SET segment=? WHERE group_id=? AND segment=?",
                               (new, gid, old)).rowcount
                _rv = calib_group_rules(gid)
                for r in _rv["rules"]:
                    if r["segment"] == old:
                        r["segment"] = new
                _calib_group_rules_save(db, gid, _rv)
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_segment", "%s: '%s' renamed '%s' (%d people)"
                             % (group["name"], old, new, n))
                flash("%s: %d %s now show as %s." % (group["name"], n, "person" if n == 1 else "people", new), "ok")
            elif action == "drop_rule":
                i = _form_int("rule")
                _rv = calib_group_rules(gid)
                if i is None or not 0 <= i < len(_rv["rules"]):
                    abort(400)
                gone = _rv["rules"].pop(i)
                _calib_group_rules_save(db, gid, _rv)
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_mode", "%s: stopped following '%s'" % (group["name"],
                                                                                                gone["dept"]))
                flash("%s no longer follows %s; the people in it stay." % (group["name"], gone["dept"]), "ok")
            else:
                plan = _group_refresh_plan(db, gid)
                if (request.form.get("fingerprint") or "") != plan["fingerprint"]:
                    flash("Who would join or leave has changed since you looked: here it is again.", "error")
                    return redirect(_here(refresh=gid) + "#group-%d" % gid)
                for x in plan["join"]:
                    db.execute("INSERT OR IGNORE INTO pm_calibration_group_members(group_id, subject_id, segment, "
                               "source) VALUES (?,?,?, 'dept')", (gid, x["id"], x["segment"]))
                for x in plan["leave"]:
                    db.execute("DELETE FROM pm_calibration_group_members WHERE group_id=? AND subject_id=?",
                               (gid, x["id"]))
                db.commit()
                log_activity(db, me["id"], "pm_calib_group_refresh", "%s: %d joined, %d left" % (
                    group["name"], len(plan["join"]), len(plan["leave"])))
                flash("%s: %d joined, %d left." % (group["name"], len(plan["join"]), len(plan["leave"])), "ok")
            return redirect(_here() + "#group-%d" % gid)
        elif action == "delete":
            gid = _form_int("group_id")
            row = db.execute("SELECT name, calibrator_id FROM pm_calibration_groups WHERE id=?", (gid,)).fetchone()
            # Members cascade; any calibration the group already did is left in
            # place but stops resolving, since pm_effective_band() looks up the
            # membership row that no longer exists.
            db.execute("DELETE FROM pm_calibration_groups WHERE id=?", (gid,))
            _fn = []
            if row and row["calibrator_id"]:   # the Group Chief seat taken away (2026-11-13)
                _fn = _line_changed(db, [_line_seat(row["calibrator_id"], "gc", gid, None)], me["id"])
            db.commit()
            log_activity(db, me["id"], "pm_calib_group_delete", row["name"] if row else str(gid))
            flash("Group deleted.%s" % _line_tail(_fn), "ok")
            return _back()
        if action == "create":
            made = db.execute("SELECT id FROM pm_calibration_groups WHERE name=?",
                              ((request.form.get("name", "") or "").strip(),)).fetchone()
            return _back(made[0] if made else None)
        return _back(_form_int("group_id"))

    return render_template("admin_pm_calibration_groups.html", **_gc_view(db))


