# =============================================================================
# After the lock: the two decision pages
#
# The Talent Box decides bands. What FOLLOWS from a band -- who goes on a
# performance improvement plan, who goes forward for promotion -- is a separate
# conversation, held once the grid is settled, which is why these are their own
# pages reached after the lock rather than tickboxes on the calibration itself.
#
# Both pages are the same shape: a list scoped to one calibration scope, one
# toggle and one remark per person, and a percentage of the scope's own
# headcount so "4 selected" is read as "3% of this business unit" rather than as
# a bare number.
# =============================================================================

NOMINATOR_ROLE_NAMES = {"line_manager": "Line manager", "hod": "Head of department",
                        "buceo": "Business unit CEO", "bgceo": "Business group CEO"}
# Column-width abbreviations for the promotion list, where WHICH roles put a
# person forward is the actual signal -- "LM · HOD" says more than "2" does, in
# the same space. Ordered nearest-to-furthest from the person, so the chips read
# up the reporting line.
NOMINATOR_ROLE_SHORT = {"line_manager": "LM", "hod": "HOD",
                        "buceo": "BUCEO", "bgceo": "BGCEO"}
NOMINATOR_ROLE_ORDER = ("line_manager", "hod", "buceo", "bgceo")


def talent_decisions_for(db, cycle_id, subject_ids, kind):
    """{subject_id: decision row} for one kind, this period. One query for the
    page rather than one per row."""
    if not subject_ids:
        return {}
    ph = ",".join("?" * len(subject_ids))
    return {r["subject_id"]: r for r in db.execute(
        f"SELECT * FROM pm_talent_decisions WHERE cycle_id=? AND kind=? "
        f"AND subject_id IN ({ph})", [cycle_id, kind] + list(subject_ids))}


def promotion_nominations_for(db, cycle_id, subject_ids):
    """{subject_id: [nomination rows]}, oldest first, nominator name resolved.

    One row per nominator, so a person put forward by their line manager, their
    HOD and the BGCEO shows all three and counts as three -- which is the
    signal the promotion page exists to surface."""
    if not subject_ids:
        return {}
    ph = ",".join("?" * len(subject_ids))
    out = {}
    for r in db.execute(
            f"SELECT n.*, u.full_name AS nominator_name FROM pm_promotion_nominations n "
            f"LEFT JOIN users u ON u.id = n.nominated_by "
            f"WHERE n.cycle_id=? AND n.subject_id IN ({ph}) ORDER BY n.created_at",
            [cycle_id] + list(subject_ids)):
        out.setdefault(r["subject_id"], []).append(r)
    return out


def _years_since(raw, today=None):
    """Years since a date, or None when it isn't known. Same shape as
    years_in_position() and equally deliberate about None: "no promotion on
    record" is not "never promoted", and the page has to be able to say so."""
    if not raw:
        return None
    try:
        d = datetime.strptime(str(raw)[:10], "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None
    return round(((today or _today_myt()) - d).days / 365.25, 1)


def talent_decision_locks_for(db, cycle_id, tier, scope_key):
    """{'pip': row-or-None, 'promotion': row-or-None} for one scope.

    Both are fetched on every one of the three pages, not just the page that
    owns them, because the stage toggle shows each stage's state -- you can see
    the PIP list is already confirmed from the promotion page without leaving
    it."""
    out = {"pip": None, "promotion": None}
    for r in db.execute(
            "SELECT * FROM pm_talent_decision_locks WHERE cycle_id=? AND tier=? "
            "AND scope_key=?", (cycle_id, tier, scope_key)):
        out[r["kind"]] = r
    return out


def _talent_decision_ctx(db, u, tier, **kw):
    """Scope + rows + who may decide here, shared by both pages and both POSTs.

    Deciding is the BGCEO's call (and, for a calibration group, its
    calibrator's) -- a BUCEO can open the list and read it, because seeing what
    their own people are being put forward for is reasonable, but the toggle is
    not theirs. Same shape as the promotion tag on the box: refused at the
    wrong tier rather than quietly ignored.

    Both pages also require the scope to be LOCKED. Deciding who goes on a PIP
    off bands that can still move would be deciding on a draft."""
    ctx = _talent_box_resolve(db, u, tier, **kw)
    rows = talent_box_rows(db, ctx)
    ctx["row_by_id"] = {r["user"]["id"]: r for r in rows}
    ctx["locked"] = bool(ctx["pm_session"] and ctx["pm_session"]["locked_at"]) and \
                    bool(ctx["pot_session"] and ctx["pot_session"]["locked_at"])
    ctx["locks"] = talent_decision_locks_for(db, ctx["period"]["id"], tier,
                                             ctx["scope_key"])
    # "May act at all here" -- the per-list lock narrows this further, in
    # _talent_decision_can(), since the two lists close independently.
    ctx["can_decide"] = ctx["locked"] and tier in ("bgceo", "group")
    ctx["headcount"] = len(ctx["population"])
    return ctx


def _talent_decision_can(ctx, kind):
    """May this viewer still change THIS list? Locked box, right tier, and the
    list itself not yet confirmed."""
    return ctx["can_decide"] and not ctx["locks"].get(kind)


def _talent_decision_stat(people, decisions, headcount):
    """"N selected · X% of <scope>" -- the percentage is of the scope's whole
    population, not of the people on this page. A PIP rate is only meaningful
    against everyone it could have applied to."""
    selected = sum(1 for r in people
                   if decisions.get(r["user"]["id"])
                   and decisions[r["user"]["id"]]["selected"])
    pct = round(selected * 100.0 / headcount, 1) if headcount else 0.0
    return {"selected": selected, "headcount": headcount, "pct": pct,
            "considered": len(people)}


def _talent_promotion_people(db, ctx):
    """Everyone on the promotion list, and why they're on it.

    Two sources, one list:
      nominated   -- somebody put them forward (LM / HOD / BUCEO / BGCEO)
      non-nominee -- a standing rule picked them up: a sustained run at Solid
                     Core or above that nobody has acted on. Labelled as such,
                     because "nobody nominated this person and here is why that
                     might be an oversight" is a different claim from "three
                     people nominated them"."""
    ids = list(ctx["row_by_id"])
    noms = promotion_nominations_for(db, ctx["period"]["id"], ids)
    history = talent_history_for(db, ids)
    last_promo = last_promotion_for(db, ids)
    people = []
    for sid, row in ctx["row_by_id"].items():
        auto = promo_auto_reason(history.get(sid, []), last_promo.get(sid))
        if sid not in noms and not auto:
            continue
        # Which roles put them forward, in reporting-line order -- the page
        # shows the roles rather than a bare count, so "LM · HOD" reads as the
        # shape of the support and not just its size. A role appears once, with
        # a multiplier if two people in it nominated (two HODs on a matrix).
        by_role = {}
        for n in noms.get(sid, []):
            by_role[n["nominator_role"]] = by_role.get(n["nominator_role"], 0) + 1
        # Off-cycle cases sit in the same list -- they still need approving --
        # but they arrived outside the season, so they say so rather than
        # passing as one of this round's nominations.
        off = [n for n in noms.get(sid, []) if _row_get(n, "nomination_kind") == "off_cycle"]
        people.append({
            "user": row["user"], "row": row,
            "noms": noms.get(sid, []),
            "nom_roles": [(r, by_role[r]) for r in NOMINATOR_ROLE_ORDER if r in by_role],
            "off_cycle": [OFF_CYCLE_REASONS.get(_row_get(n, "off_cycle_reason") or "", "Off-cycle")
                          for n in off],
            "auto_reason": auto,
            "history": history.get(sid, []),
            "last_promotion": last_promo.get(sid),
            "years_since_promotion": _years_since(last_promo.get(sid)),
            "years_in_position": years_in_position(row["user"]),
        })
    # Nominated first, most-nominated first inside that -- the page's own
    # ordering is the argument it is making. Auto-picked people follow.
    people.sort(key=lambda p: (0 if p["noms"] else 1, -len(p["noms"]),
                               (p["user"]["full_name"] or "").lower()))
    return people


def _talent_decision_bu_filter(ctx):
    """The business-unit filter for a decision page: the companies in scope, the
    one picked (if any), and the population that pick implies.

    Narrowing genuinely re-asks the question rather than just hiding rows: the
    header's percentage is measured over the FILTERED population, so picking a
    business unit turns "3% of the business group" into "3% of that unit" --
    which is the number the rule is actually written in. Same reasoning as the
    box's own filters, which likewise re-measure the distribution.

    A BUCEO scope is one company by definition -- the company is part of its
    route -- so the row never renders there and `company` can't collide with the
    route's own argument."""
    all_companies = sorted({p["company"] for p in ctx["population"] if p["company"]})
    picked = (request.args.get("company") or "").strip()
    if picked not in all_companies:
        picked = ""
    scoped = [p for p in ctx["population"]
              if not picked or (p["company"] or "") == picked]
    return {
        "all_companies": all_companies,
        "f_company": picked,
        "headcount": len(scoped),
        # Same short labels the calibration business-unit rows use, so one
        # company reads the same across every screen in the module.
        "company_labels": {c: COMPANY_SHORT.get(c) or display_company(ctx["business_group"], c)
                           for c in all_companies},
    }


def _talent_pip_render(tier, **kw):
    db = get_db()
    u = current_user()
    ctx = _talent_decision_ctx(db, u, tier, **kw)
    bu = _talent_decision_bu_filter(ctx)
    people = [r for r in ctx["row_by_id"].values()
              if r["category"] == TALENT_PIP
              and (not bu["f_company"] or (r["user"]["company"] or "") == bu["f_company"])]
    people.sort(key=lambda r: (r["user"]["full_name"] or "").lower())
    decisions = talent_decisions_for(db, ctx["period"]["id"],
                                     [r["user"]["id"] for r in people], "pip")
    return render_template(
        "talent_pip.html", active_view="calibration", tier=tier, ctx=ctx,
        scope_kwargs=kw, people=people, decisions=decisions, bu=bu,
        can_edit=_talent_decision_can(ctx, "pip"), locks=ctx["locks"],
        stat=_talent_decision_stat(people, decisions, bu["headcount"]),
        label_names=PM_LABEL_NAMES, category_slug=TALENT_CATEGORY_SLUG,
        box_url=_talent_box_url(tier, **kw))


def _talent_promotion_render(tier, **kw):
    db = get_db()
    u = current_user()
    ctx = _talent_decision_ctx(db, u, tier, **kw)
    bu = _talent_decision_bu_filter(ctx)
    # Built over the whole scope, then narrowed: the standing rules read a
    # person's own history, so which business unit you're looking at can't
    # change whether a rule fires for them.
    people = [p for p in _talent_promotion_people(db, ctx)
              if not bu["f_company"] or (p["user"]["company"] or "") == bu["f_company"]]
    decisions = talent_decisions_for(db, ctx["period"]["id"],
                                     [p["user"]["id"] for p in people], "promotion")
    return render_template(
        "talent_promotion.html", active_view="calibration", tier=tier, ctx=ctx,
        scope_kwargs=kw, people=people, decisions=decisions, bu=bu,
        can_edit=_talent_decision_can(ctx, "promotion"), locks=ctx["locks"],
        stat=_talent_decision_stat([{"user": p["user"]} for p in people],
                                   decisions, bu["headcount"]),
        label_names=PM_LABEL_NAMES, category_slug=TALENT_CATEGORY_SLUG,
        role_names=NOMINATOR_ROLE_NAMES, role_short=NOMINATOR_ROLE_SHORT,
        off_cycle_reasons=OFF_CYCLE_REASONS, history_years=promo_history_years(db),
        box_url=_talent_box_url(tier, **kw))


def _talent_decide(tier, kind, **kw):
    """Record one PIP or promotion decision.

    Eligibility is re-derived here, never trusted from the form: a crafted
    request can't put somebody on the PIP list who isn't in the PIP category,
    or approve a promotion for somebody nobody nominated and no rule picked up.
    Unticking keeps the row (selected=0) rather than deleting it -- a
    considered "no" is a decision, and the statistic has to be able to tell it
    apart from a person nobody has looked at yet."""
    db = get_db()
    u = current_user()
    ctx = _talent_decision_ctx(db, u, tier, **kw)
    back = url_for(f"talent_{kind}_{tier}", **kw)

    if not ctx["locked"]:
        flash("Lock the calibration first — these decisions read the final bands.",
              "error")
        return redirect(back)
    if not ctx["can_decide"]:
        flash("Only the Business Group CEO can record these decisions.", "error")
        return redirect(back)
    if ctx["locks"].get(kind):
        flash("This list is already confirmed. Reopen it to make changes.", "error")
        return redirect(back)

    subject_id = _form_int("subject_id")
    row = ctx["row_by_id"].get(subject_id)
    if not row:
        flash("That person isn't in this scope.", "error")
        return redirect(back)
    if kind == "pip":
        if row["category"] != TALENT_PIP:
            flash(f"Only people in {TALENT_PIP} can be PIP candidates.", "error")
            return redirect(back)
    else:
        eligible = {p["user"]["id"] for p in _talent_promotion_people(db, ctx)}
        if subject_id not in eligible:
            flash("That person isn't on the promotion list.", "error")
            return redirect(back)

    selected = 1 if request.form.get("selected") else 0
    remark = (request.form.get("remark", "") or "").strip()[:2000] or None
    # Confirmed grade/title are the promotion's own outcome, so they are only
    # meaningful on a selected promotion row -- deselecting clears them for the
    # same reason clearing the special-reward pin clears its reason.
    grade = title = None
    if kind == "promotion" and selected:
        grade = (request.form.get("confirmed_job_grade", "") or "").strip()[:20] or None
        title = (request.form.get("confirmed_job_title", "") or "").strip()[:120] or None

    db.execute(
        "INSERT INTO pm_talent_decisions(cycle_id, subject_id, kind, selected, "
        "  confirmed_job_grade, confirmed_job_title, remark, decided_by) "
        "VALUES (?,?,?,?,?,?,?,?) "
        "ON CONFLICT(cycle_id, subject_id, kind) DO UPDATE SET "
        "  selected=excluded.selected, "
        "  confirmed_job_grade=excluded.confirmed_job_grade, "
        "  confirmed_job_title=excluded.confirmed_job_title, "
        "  remark=excluded.remark, decided_by=excluded.decided_by, "
        "  decided_at=datetime('now')",
        (ctx["period"]["id"], subject_id, kind, selected, grade, title, remark,
         u["id"]))
    db.commit()
    what = ("selected" if selected else "not selected")
    log_activity(db, u["id"], f"talent_{kind}_decision",
                 f"{row['user']['full_name']} ({ctx['scope_label']}): {what}",
                 target_user_id=subject_id)
    flash(f"{row['user']['full_name']}: {kind.upper() if kind == 'pip' else 'promotion'} "
          f"{what}.", "ok")
    return redirect(back)


# =============================================================================
# Promotion Nomination — the line manager's / HOD's / BUCEO's door
#
# The other end of the promotion page. The BGCEO's own tag on the Talent Box
# writes to the same table, so "recommended by" on the promotion page reads one
# list from four sources and can count them, rather than unioning four shapes.
# =============================================================================

# Most specific first: the relationship a nomination is made THROUGH is the
# closest one the nominator actually has to that person. Somebody who both line-
# manages a person and runs their business unit nominates as their manager --
# the nearer relationship is the one that carries the knowledge.
NOMINATOR_ROLE_RANK = ("line_manager", "hod", "buceo")

# Nominating somebody the standing rules did NOT surface is a claim the rules
# don't already support, so it has to carry an argument. Enforced server-side --
# the collapsed table is a UI nudge, this is the rule.
NOMINATION_MIN_RATIONALE = 40

# Promotions that don't wait for the season. Both are real, both need naming:
# a counteroffer is a retention decision, a special promotion is a recognition
# one, and telling them apart later is the whole point of recording which.
OFF_CYCLE_REASONS = {
    "retention": "Retention / counteroffer",
    "special": "Special promotion",
    "restructure": "Role change or restructure",
    "other": "Other",
}

# Mid-sentence forms ("nominating as their line manager"). Kept separate from
# NOMINATOR_ROLE_NAMES rather than lower-casing it, which turns "Business unit
# CEO" into "business unit ceo".
NOMINATOR_ROLE_INLINE = {"line_manager": "line manager",
                         "hod": "head of department",
                         "buceo": "business-unit CEO",
                         "bgceo": "business-group CEO"}


def nomination_population(db, u):
    """[(user row, relationship)] this login may nominate, most specific
    relationship each.

    Three sources, matching _hub_can_nominate()'s three: direct reports, an
    HOD's department tree, and a BUCEO's whole business unit. Same confirmed,
    not-demo population Calibration uses -- so the people you can nominate are
    exactly the people who appear in a calibration, no separate idea of who
    counts.

    Never yourself: a nomination is something you make about someone else."""
    found = {}                       # subject_id -> (row, rank index)
    def add(rows, role):
        rank = NOMINATOR_ROLE_RANK.index(role)
        for r in rows:
            if r["id"] == u["id"]:
                continue
            if r["id"] not in found or rank < found[r["id"]][1]:
                found[r["id"]] = (r, rank)

    base = f"role!='admin' AND left_at IS NULL AND {calibration_population_sql()}"
    add(db.execute(f"SELECT * FROM users WHERE manager_id=? AND {base}", (u["id"],)),
        "line_manager")
    add(db.execute(f"SELECT * FROM users WHERE hod_id=? AND {base}", (u["id"],)),
        "hod")
    if u["buceo_bg"] and u["buceo_company"]:
        add(db.execute(f"SELECT * FROM users WHERE business_group=? AND company=? AND {base}",
                       (u["buceo_bg"], u["buceo_company"])), "buceo")
    out = [(row, NOMINATOR_ROLE_RANK[rank]) for row, rank in found.values()]
    out.sort(key=lambda p: (p[0]["full_name"] or "").lower())
    return out


def _promotion_lists_closed(db, cycle_id):
    """The business groups whose promotion list the BGCEO has already confirmed.

    Nominating into a closed list would be a write nobody will ever read, so the
    page says so and refuses instead -- a control that silently does nothing is
    worse than one that isn't there."""
    return {r["scope_key"] for r in db.execute(
        "SELECT scope_key FROM pm_talent_decision_locks WHERE cycle_id=? "
        "AND tier='bgceo' AND kind='promotion'", (cycle_id,))}


NOMINATION_KINDS = {
    "cycle": {
        "endpoint": "promotion_nomination",
        "title": "Promotion Nomination",
        "blurb": ("The season's promotion round. A nomination puts someone on the "
                  "Business Group CEO's list for this period, alongside any nomination "
                  "from their HOD or business-unit CEO."),
    },
    "off_cycle": {
        "endpoint": "promotion_nomination_off_cycle",
        "title": "Off-Cycle Nomination",
        "blurb": ("A promotion that can't wait for the season -- a counteroffer to keep "
                  "somebody, a special promotion earned mid-period, a role change. Raised "
                  "as an exception, so it needs its occasion named and its case written, "
                  "and it stays open after the season's list is confirmed."),
    },
}


def _promotion_nomination_page(kind):
    """Everyone this login may put forward, with what the box already says about
    them and what they (and others) have already nominated.

    One builder, two doors. The season round and the off-cycle exception ask
    genuinely different questions -- one is "who is due?", answered by the
    standing rules; the other is "what has come up?", which no rule predicts --
    so they get their own pages rather than a toggle that changes what a form
    means underneath you. Everything they share (population, calibrated status,
    the higher bar) is shared here."""
    db = get_db()
    u = current_user()
    if not _hub_can_nominate(db, u):
        abort(403)
    period = active_pm_period(db)
    cycle_id = active_cycle_id(db)
    if not period or not cycle_id:
        abort(404)

    pairs = nomination_population(db, u)
    people = [p[0] for p in pairs]
    roles = {p[0]["id"]: p[1] for p in pairs}
    ids = [p["id"] for p in people]

    # The calibrated view of each person, read the same way the Talent Box reads
    # it -- via a scope-less context, so only LOCKED calibration counts. A
    # nominator should see the settled status, never some tier's working state.
    rows = {}
    if people:
        rows = {r["user"]["id"]: r for r in talent_box_rows(db, {
            "period": period, "cycle_id": cycle_id, "population": people,
            "pot_session": None, "pm_session": None})}

    # Scoped to THIS kind on both sides. A cycle nomination and an off-cycle one
    # are separate records now, so the season page must not show a counteroffer
    # as though it were this round's recommendation -- nor count it.
    mine, others, other_kind = {}, {}, {}
    if ids:
        ph = ",".join("?" * len(ids))
        for r in db.execute(
                f"SELECT * FROM pm_promotion_nominations WHERE cycle_id=? "
                f"AND subject_id IN ({ph})", [period["id"]] + ids):
            same_kind = (r["nomination_kind"] or "cycle") == kind
            if r["nominated_by"] == u["id"]:
                (mine if same_kind else other_kind)[r["subject_id"]] = r
            elif same_kind:
                others[r["subject_id"]] = others.get(r["subject_id"], 0) + 1

    # The same standing rules the BGCEO's promotion page applies -- both read
    # promo_auto_rules(), so a person the rules surface here is exactly a person
    # the rules would surface there, whatever an admin has set them to.
    history = talent_history_for(db, ids)
    last_promo = last_promotion_for(db, ids)
    auto = {sid: promo_auto_reason(history.get(sid, []), last_promo.get(sid))
            for sid in ids}
    # Splitting the page on the rules only makes sense for the season round,
    # where "who is due?" is the question. Off-cycle is an exception by
    # definition -- a counteroffer arrives for whoever it arrives for, and the
    # record having argued for them already changes nothing about the bar -- so
    # that page is one flat list and everyone on it writes their case.
    #
    # Whoever this login has already put forward comes out of those lists and
    # leads the page. A nomination is the thing you came here to do and the
    # thing you might change your mind about, so it shouldn't stay buried at
    # whatever alphabetical position the person happens to occupy inside a
    # collapsed hundred-name list. Each person appears in exactly one table --
    # two rows for one subject would mean two checkboxes over one record, and
    # the second would go stale the moment the first was used.
    nominated = [p for p in people if p["id"] in mine]
    pending = [p for p in people if p["id"] not in mine]
    if kind == "cycle":
        recommended = [p for p in pending if auto.get(p["id"])]
        rest = [p for p in pending if not auto.get(p["id"])]
    else:
        recommended, rest = [], pending

    # What each row's dialog offers: the grades this person may be proposed for,
    # and titles worth proposing at them. Computed server-side per person rather
    # than fetched on open -- the set is small, it makes the dialog instant, and
    # it keeps the offered options and the ones the save re-derives identical.
    grade_opts = {p["id"]: promo_grade_options(p["job_grade"]) for p in people}
    title_opts = {p["id"]: promo_title_suggestions(db, p, grade_opts[p["id"]])
                  for p in people}

    closed = _promotion_lists_closed(db, period["id"])
    return render_template(
        "promotion_nomination.html", active_view="promotion", period=period,
        grade_opts=grade_opts, title_opts=title_opts,
        kind=kind, kinds=NOMINATION_KINDS, page=NOMINATION_KINDS[kind],
        people=people, nominated=nominated, recommended=recommended, rest=rest, auto=auto,
        # The rules' own count, independent of what has been acted on -- the
        # header chip must not shrink just because somebody was nominated out
        # of the Recommended list.
        auto_count=sum(1 for p in people if auto.get(p["id"])),
        history=history, last_promo=last_promo, history_years=promo_history_years(db),
        roles=roles, rows=rows, mine=mine, others=others, other_kind=other_kind,
        closed=closed, role_names=NOMINATOR_ROLE_INLINE,
        off_cycle_reasons=OFF_CYCLE_REASONS, min_rationale=NOMINATION_MIN_RATIONALE,
        label_names=PM_LABEL_NAMES, category_slug=TALENT_CATEGORY_SLUG,
        nominated_count=len(mine))


# ==== succession planning ================================================
# Position-centric, unlike the two person-centric talent objects beside it:
# the question is "who could fill THIS seat", and the answer that matters is
# a critical seat with nobody behind it.


@app.route("/promotion-nomination")
@login_required
def promotion_nomination():
    """The season's round -- open until the BGCEO confirms the list."""
    return _promotion_nomination_page("cycle")


@app.route("/promotion-nomination/off-cycle")
@login_required
def promotion_nomination_off_cycle():
    """The exception -- a counteroffer or a special promotion, raised whenever
    it comes up and still available once the season's list is confirmed."""
    return _promotion_nomination_page("off_cycle")


@app.route("/promotion-nomination/nominate", methods=["POST"])
@login_required
def promotion_nomination_save():
    """Put one person forward, or withdraw.

    Withdrawing DELETEs rather than flagging: "recommended by 2" has to mean two
    live recommendations, and a withdrawn one left behind would keep inflating
    that count. The nominator's own row is the only one this can touch -- the
    UNIQUE key is (period, subject, nominated_by), so one person's withdrawal
    can never remove somebody else's."""
    db = get_db()
    u = current_user()
    if not _hub_can_nominate(db, u):
        abort(403)
    period = active_pm_period(db)
    if not period:
        abort(404)
    # Resolved before anything can fail, so EVERY path -- including the refusals
    # below -- returns to the door this came from. The two are separate pages
    # now, and landing on the other one after a save would read as the save
    # having gone somewhere else.
    off_cycle = request.form.get("nomination_kind") == "off_cycle"
    back = url_for(NOMINATION_KINDS["off_cycle" if off_cycle else "cycle"]["endpoint"])

    subject_id = _form_int("subject_id")
    pair = next((p for p in nomination_population(db, u) if p[0]["id"] == subject_id), None)
    if not pair:
        flash("That person isn't yours to nominate.", "error")
        return redirect(back)
    subject, role = pair

    # A closed list closes the SEASON's nominations, not the door entirely --
    # an off-cycle case (a counteroffer, a special promotion) is precisely the
    # thing that arrives after the list is confirmed, so it stays open.
    if not off_cycle and subject["business_group"] in _promotion_lists_closed(db, period["id"]):
        flash(f"The promotion list for {display_bg(subject['business_group'])} is "
              f"already confirmed — nominations for it are closed. An off-cycle "
              f"case can still be raised.", "error")
        return redirect(back)

    if not request.form.get("nominate"):
        # Scoped to the kind: withdrawing this season's nomination must not also
        # withdraw a live counteroffer for the same person, and vice versa.
        db.execute("DELETE FROM pm_promotion_nominations WHERE cycle_id=? AND "
                   "subject_id=? AND nominated_by=? AND nomination_kind=?",
                   (period["id"], subject_id, u["id"],
                    "off_cycle" if off_cycle else "cycle"))
        db.commit()
        log_activity(db, u["id"], "promotion_nomination_withdraw",
                     subject["full_name"], target_user_id=subject_id)
        flash(f"Nomination for {subject['full_name']} withdrawn.", "ok")
        return redirect(back)

    rationale = (request.form.get("rationale", "") or "").strip()[:2000]
    reason = (request.form.get("off_cycle_reason", "") or "").strip()

    # Does the record already argue for this person? Re-derived here, never
    # trusted from the form -- the higher bar is the point, so which side of it
    # somebody sits on can't be a posted field.
    history = talent_history_for(db, [subject_id])
    last_promo = last_promotion_for(db, [subject_id])
    recommended = bool(promo_auto_reason(history.get(subject_id, []),
                                         last_promo.get(subject_id)))

    if off_cycle:
        if reason not in OFF_CYCLE_REASONS:
            flash("Say what kind of off-cycle case this is.", "error")
            return redirect(back)
        # Off-cycle is exceptional by definition: it skips the season, so it
        # always argues for itself regardless of what the rules say.
        if len(rationale) < NOMINATION_MIN_RATIONALE:
            flash(f"An off-cycle promotion needs the case in writing "
                  f"({NOMINATION_MIN_RATIONALE} characters or more).", "error")
            return redirect(back)
    elif not recommended and len(rationale) < NOMINATION_MIN_RATIONALE:
        flash(f"{subject['full_name']} isn't on the recommended list, so the case "
              f"has to be made in writing ({NOMINATION_MIN_RATIONALE} characters "
              f"or more).", "error")
        return redirect(back)

    db.execute(
        "INSERT INTO pm_promotion_nominations(cycle_id, subject_id, nominated_by, "
        "  nominator_role, proposed_job_grade, proposed_job_title, rationale, "
        "  nomination_kind, off_cycle_reason) "
        "VALUES (?,?,?,?,?,?,?,?,?) "
        "ON CONFLICT(cycle_id, subject_id, nominated_by, nomination_kind) DO UPDATE SET "
        "  nominator_role=excluded.nominator_role, "
        "  proposed_job_grade=excluded.proposed_job_grade, "
        "  proposed_job_title=excluded.proposed_job_title, "
        "  rationale=excluded.rationale, "
        "  off_cycle_reason=excluded.off_cycle_reason",
        (period["id"], subject_id, u["id"], role,
         (request.form.get("proposed_job_grade", "") or "").strip()[:20] or None,
         (request.form.get("proposed_job_title", "") or "").strip()[:120] or None,
         rationale or None,
         "off_cycle" if off_cycle else "cycle",
         reason if off_cycle else None))
    db.commit()
    kind_note = f", off-cycle: {OFF_CYCLE_REASONS[reason]}" if off_cycle else ""
    log_activity(db, u["id"], "promotion_nomination",
                 f"{subject['full_name']} (as {role}{kind_note})", target_user_id=subject_id)
    flash(f"{subject['full_name']} nominated for promotion"
          f"{' — off-cycle' if off_cycle else ''}.", "ok")
    return redirect(back)


def _talent_decision_lock(tier, kind, **kw):
    """Confirm (or reopen) one decision list for this scope.

    Confirming is the handover: the PIP list closing is what sends the BGCEO on
    to the promotion list, the same way the box's own lock sent them to PIP.
    Reopening exists because a confirmed list is a decision, not a punishment --
    it is the same person's to take back, and it is logged either way."""
    db = get_db()
    u = current_user()
    ctx = _talent_decision_ctx(db, u, tier, **kw)
    here = url_for(f"talent_{kind}_{tier}", **kw)
    reopen = request.form.get("action") == "reopen"

    # Two different refusals, said separately: "the box isn't locked yet" is a
    # sequencing answer, "this isn't yours" is a permissions one, and one
    # message for both would send the wrong person looking for the wrong fix.
    if not ctx["locked"]:
        flash("Lock the calibration first — this list is still a preview.", "error")
        return redirect(here)
    if not ctx["can_decide"]:
        flash("Only the Business Group CEO can confirm these lists.", "error")
        return redirect(here)
    existing = ctx["locks"].get(kind)
    if reopen:
        if not existing:
            flash("That list isn't confirmed.", "error")
            return redirect(here)
        db.execute("DELETE FROM pm_talent_decision_locks WHERE id=?", (existing["id"],))
        db.commit()
        log_activity(db, u["id"], f"talent_{kind}_reopen", ctx["scope_label"])
        flash(f"{'PIP' if kind == 'pip' else 'Promotion'} list reopened.", "ok")
        return redirect(here)
    if existing:
        flash("Already confirmed.", "error")
        return redirect(here)

    db.execute(
        "INSERT INTO pm_talent_decision_locks(cycle_id, tier, scope_key, kind, locked_by) "
        "VALUES (?,?,?,?,?)",
        (ctx["period"]["id"], tier, ctx["scope_key"], kind, u["id"]))
    db.commit()
    log_activity(db, u["id"], f"talent_{kind}_lock", ctx["scope_label"])
    if kind == "pip":
        flash("PIP list confirmed. Next: the promotion list.", "ok")
        return redirect(url_for(f"talent_promotion_{tier}", **kw))
    flash("Promotion list confirmed — this scope is complete.", "ok")
    return redirect(here)


