@app.route("/calibration/company/<bg>/<path:company>")
@login_required
def calibration_company_view(bg, company):
    u = current_user()
    db = get_db()
    if not (is_buceo_of(u, bg, company) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    population = db.execute(   # a calibration group's people are its calibrator's, never the BU CEO's (2026-10-22)
        f"SELECT * FROM users WHERE business_group=? AND company=? AND role!='admin' AND NOT {bu_grouped_sql()} "
        f"AND {calibration_population_sql()} ORDER BY full_name", (bg, company)).fetchall()
    if not population:
        abort(403)
    pending = calibration_pending_children(db, cid, "buceo", bg, company)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, company)).fetchone()
    locked = bool(session_row and session_row["locked_at"])
    rows = _calibration_rows(db, population, cid, effective_band, session_row)
    dist = band_distribution_from_rows(rows)
    attach_tier_chain(db, rows, cid, population, "buceo")
    dept_options = sorted({(r["user"]["department"] or "").strip()
                           for r in rows if (r["user"]["department"] or "").strip()})
    return render_template(
        "calibration_company.html", active_view="calibration", tier="buceo",
        scope_label=company, rows=rows, distribution=dist,
        gaps=calibration_target_gaps(dist, CALIBRATION_TARGET), target=CALIBRATION_TARGET,
        dept_options=dept_options, people_count=len(rows), dept_count=len(dept_options),
        locked=locked, session=session_row,
        locked_by_name=_calibration_locked_by_name(db, session_row),
        bg=bg, company=company, cycle_id=cid,
        pending=pending, stale=locked and bool(pending), is_super_view=is_super(u),
    )


@app.route("/calibration/company/<bg>/<path:company>/adjust", methods=["POST"])
@login_required
def calibration_company_adjust(bg, company):
    u = current_user()
    db = get_db()
    if not (is_buceo_of(u, bg, company) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    subject_id = _form_int("subject_id")
    new_band = (request.form.get("adjusted_band", "") or "").strip()
    justification = (request.form.get("justification", "") or "").strip()
    subject = db.execute(   # never a calibration group's person (2026-10-22): their calibrator moves them
        f"SELECT * FROM users WHERE id=? AND business_group=? AND company=? AND role!='admin' AND NOT {bu_grouped_sql()} "
        f"AND {calibration_population_sql()}", (subject_id, bg, company)).fetchone()
    if not subject:
        return _calibration_respond(False, "That person isn't in this company.", "error",
                                     "calibration_company_view", bg=bg, company=company)
    # Nobody calibrates themselves. The product already states this principle
    # for promotions -- "they are the one who APPROVES promotions ... the same
    # person shouldn't sit on both ends of that decision" -- but the three
    # calibration tiers never enforced it, so a BG CEO sat in his own list and
    # could set his own potential band, which then feeds the talent box and
    # merit. A super admin acting on someone else's scope is unaffected.
    if subject_id == u["id"]:
        return _calibration_respond(False, "You can't calibrate your own band. Ask the "
                                    "tier above to set it.", "error",
                                    "calibration_company_view", bg=bg, company=company)
    if new_band not in ("Low", "Mid", "High"):
        return _calibration_respond(False, "Choose Low, Mid, or High.", "error",
                                     "calibration_company_view", bg=bg, company=company)
    _t, _serr = _store_text(justification or "", "manager")
    if _serr:
        return _calibration_respond(False, _serr, "error", "calibration_company_view", bg=bg, company=company)
    _bgc = _bg_closed(db, "pot", cid, bg, company)
    if _bgc:   # the BG CEO locked it: their decision is final (2026-10-07)
        return _calibration_respond(False, _bgc, "error", "calibration_company_view", bg=bg, company=company)
    _w = window_closed_tier(db, "buceo", "pot", cid, scope=_late_unit_scopes(db, cid, bg, company))   # a late pass is its unit's
    if _w:
        return _calibration_respond(False, _w, "error", "calibration_company_view", bg=bg, company=company)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, company)).fetchone()
    if session_row and session_row["locked_at"]:
        return _calibration_respond(False, "This business unit's calibration is locked.", "error",
                                     "calibration_company_view", bg=bg, company=company)
    session_row = _get_or_create_calibration_session(db, cid, "buceo", company, bg, company)
    original = effective_band(db, subject, cid)["band"] or ""
    _calibration_upsert_adjustment(db, session_row["id"], subject_id, original, new_band,
                                    justification, u["id"])
    log_activity(db, u["id"], "calibration_adjust",
                 f"{subject['full_name']}: {original or 'No Data'} -> {new_band} (company scope)",
                 target_user_id=subject_id)
    return _calibration_respond(True, f"{subject['full_name']}'s band set to {new_band}.", "ok",
                                 "calibration_company_view", bg=bg, company=company)


@app.route("/calibration/company/<bg>/<path:company>/reset", methods=["POST"])
@login_required
def calibration_company_reset(bg, company):
    u = current_user()
    db = get_db()
    if not (is_buceo_of(u, bg, company) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, company)).fetchone()
    _bgc = _bg_closed(db, "pot", cid, bg, company)
    _w = window_closed_tier(db, "buceo", "pot", cid, scope=_late_unit_scopes(db, cid, bg, company))   # a late pass is its unit's
    if session_row and session_row["locked_at"]:
        flash("This business unit's calibration is locked.", "error")
    elif _bgc:   # the BG CEO locked it: their decision is final (2026-10-07)
        flash(_bgc, "error")
    elif _w:
        flash(_w, "error")
    elif session_row:
        db.execute("DELETE FROM calibration_adjustments WHERE session_id=?", (session_row["id"],))
        db.commit()
        log_activity(db, u["id"], "calibration_reset", f"Company scope reset: {company}")
        flash("All adjustments cleared -- back to the department roll-up.", "ok")
    else:
        flash("No adjustments to reset.", "ok")
    return redirect(url_for("calibration_company_view", bg=bg, company=company))


@app.route("/calibration/company/<bg>/<path:company>/lock", methods=["POST"])
@login_required
def calibration_company_lock(bg, company):
    u = current_user()
    db = get_db()
    cid = active_cycle_id(db)
    join = calib_join(db, cid, bg, company)   # units calibrated together lock as one, through the lead (row 6)
    units = join["members"] if join else [company]
    if not (any(is_buceo_of(u, bg, c_) for c_ in units) or is_super(u)):
        abort(403)
    if join:
        company = join["lead"]
        if not (is_buceo_of(u, bg, company) or is_super(u)):
            return _lock_reply(False, _join_read_only_msg(db, {"join": join, "business_group": bg}),
                               _pot_calib_back(url_for("calibration_company_view", bg=bg, company=company)))
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, company)).fetchone()
    _back = _pot_calib_back(url_for("calibration_company_view", bg=bg, company=company))
    _bgc = next((x for x in (_bg_closed(db, "pot", cid, bg, c_) for c_ in units) if x), None)
    if session_row and session_row["locked_at"]:
        if request.form.get("ajax") == "1":   # locked already: done, nothing to say (2026-10-01)
            return jsonify(ok=True, already=True)
        flash("Already locked.", "error")
    elif _bgc:   # the BG CEO locked it: their decision is final (2026-10-07)
        return _lock_reply(False, _bgc, _back)
    elif window_closed_tier(db, "buceo", "pot", cid, scope=[company] + units):   # closed, and no late pass for THIS unit
        return _lock_reply(False, window_closed_tier(db, "buceo", "pot", cid, scope=[company] + units), _back)
    else:
        pending = calibration_pending_children(db, cid, "buceo", bg, company)
        if pending:
            names = ", ".join(name for _, name in pending)
            return _lock_reply(False, f"Waiting on department calibration to lock first: {names}.", _back)
        else:
            population = db.execute(   # the unit's own people: a calibration group locks its own (2026-10-22)
                f"SELECT * FROM users WHERE business_group=? AND company IN ({','.join('?' * len(units))}) "
                f"AND role!='admin' AND NOT {bu_grouped_sql()} AND {calibration_population_sql()} ORDER BY full_name",
                [bg] + units).fetchall()
            _msess = [db.execute("SELECT id FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' AND "
                                 "business_group=? AND scope_key=?", (cid, bg, c_)).fetchone() for c_ in units]
            _sids = [r_["id"] for r_ in _msess if r_] if join else None
            if not _calib_scope_scored(db, population, cid, session_row):
                return _lock_reply(False, "Nobody in this business unit has a potential band yet, so there is "
                                          "nothing to calibrate. Locking it would tell the tier above that it was "
                                          "reviewed.", _back)
            # FRAMEWORK GUARDRAIL (BUCEO potential): within tolerance of 15-70-15 unless overridden.
            _blk = _pot_calib_lock_breaches(db, population, cid, effective_band, session_row, session_ids=_sids)
            _ovr = "" if calib_lock_strict() else (request.form.get("override_reason") or "").strip()   # strict: no override
            if _blk and not _ovr:
                return _lock_reply(False, _calib_breach_message(_blk), _back)
            if _blk and _ovr:
                log_activity(db, u["id"], "calibration_override",
                             f"BUCEO {company} potential off-framework: {_ovr[:200]}")
            for c_ in units:   # one lock for every unit calibrated together (row 6)
                session_row = _get_or_create_calibration_session(db, cid, "buceo", c_, bg, c_)
                db.execute("UPDATE calibration_sessions SET locked_at=datetime('now'), locked_by=? WHERE id=?",
                           (u["id"], session_row["id"]))
            _rating_record_refresh(db, cid, [p["id"] for p in population], "pot_calib_lock_buceo", u["id"])
            db.commit()
            log_activity(db, u["id"], "calibration_lock", f"Company scope locked: {company}")
            _late_after_lock(db, u, "buceo", bg, company, {"scope_key": company, "join": join})
            db.commit()
            return _lock_reply(True, "Company calibration locked.", _back)
    return redirect(_back)


