def calibration_company_unlock(bg, company):
    """The business unit's Unlock: both axes together (2026-11-07), units calibrated together unlock together (row 6)."""
    return _unlock_route("buceo", (bg, company), url_for("calibration_company_view", bg=bg, company=company))


@app.route("/calibration/bu-group/<int:gid>/lock", methods=["POST"])
@login_required
def calibration_bugroup_lock(gid):
    """A calibration group's potential lock (2026-10-22): its calibrator locks it, at BU CEO level, as a BU CEO locks
    a unit -- the group on its own, on the potential curve (Chris's pick 3A)."""
    u = current_user()
    db = get_db()
    cid = active_cycle_id(db)
    grp = bu_group(db, gid)
    if not grp:
        abort(404)
    if not (u["id"] == grp["calibrator_id"] or is_super(u)):
        abort(403)
    bg, key = grp["business_group"], BU_GROUP_PREFIX + str(grp["id"])
    _back = _pot_calib_back(url_for("review_journey", view="bu", stage="calibration_pot", bu_unit=key))
    _lo = leader_ability_off(db, u, leader_tier_ability("buceo", "lock", key))   # Roles & access › Leader roles (cg.lock)
    if _lo:
        return _lock_reply(False, _lo, _back)
    session_row = db.execute("SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='buceo' AND "
                             "business_group=? AND scope_key=?", (cid, bg, key)).fetchone()
    if session_row and session_row["locked_at"]:
        if request.form.get("ajax") == "1":
            return jsonify(ok=True, already=True)
        return _lock_reply(False, "Already locked.", _back)
    _bgc = _bg_closed(db, "pot", cid, bg, key)   # every unit it reaches locked by the BG CEO
    if _bgc:   # the BG CEO locked the unit: their decision is final
        return _lock_reply(False, _bgc, _back)
    _w = window_closed_tier(db, "buceo", "pot", cid, scope=[key])   # a late pass is this group's
    if _w:
        return _lock_reply(False, _w, _back)
    population = _pot_scope_population(db, "buceo", (bg, grp["company"], grp["id"]))
    if not _calib_scope_scored(db, population, cid, session_row):
        return _lock_reply(False, "Nobody in this group has a potential band yet, so there is nothing to calibrate. "
                                  "Locking it would tell the tier above that it was reviewed.", _back)
    _blk = _pot_calib_lock_breaches(db, population, cid, effective_band, session_row)
    _ovr = "" if calib_lock_strict() else (request.form.get("override_reason") or "").strip()
    if _blk and not _ovr:
        return _lock_reply(False, _calib_breach_message(_blk), _back)
    if _blk and _ovr:
        log_activity(db, u["id"], "calibration_override", f"BU group {grp['name']} potential off-framework: {_ovr[:200]}")
    session_row = _get_or_create_calibration_session(db, cid, "buceo", key, bg, bu_group_label(bg, grp))
    db.execute("UPDATE calibration_sessions SET locked_at=datetime('now'), locked_by=? WHERE id=?",
               (u["id"], session_row["id"]))
    _rating_record_refresh(db, cid, [p["id"] for p in population], "pot_calib_lock_buceo", u["id"])
    db.commit()
    log_activity(db, u["id"], "calibration_lock", f"Calibration group locked: {bu_group_label(bg, grp)}")
    _late_after_lock(db, u, "buceo", bg, key, {"scope_key": key})   # a late pass is used (2026-10-31)
    db.commit()
    return _lock_reply(True, "Calibration locked and submitted upward.", _back)


