# --- Business Group (BGCEO) tier --------------------------------------------
def _bgceo_bg_for(u):
    """A BGCEO's scope is exactly one BG on their own login -- no path param
    needed. Super admin gets a ?bg=/form bg= fallback for support/QA access."""
    if u["bgceo_bg"]:
        return u["bgceo_bg"]
    if is_super(u):
        return (request.values.get("bg", "") or "").strip()
    return ""


@app.route("/calibration/bg")
@login_required
def calibration_bg_view():
    u = current_user()
    db = get_db()
    bg = _bgceo_bg_for(u)
    if not bg or not (is_bgceo_of(u, bg) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    population = db.execute(
        f"SELECT * FROM users WHERE business_group=? AND role!='admin' "
        f"AND {calibration_population_sql()} ORDER BY full_name", (bg,)).fetchall()
    if not population:
        abort(403)
    pending = calibration_pending_children(db, cid, "bgceo", bg)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='bgceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, bg)).fetchone()
    locked = bool(session_row and session_row["locked_at"])
    rows = _calibration_rows(db, population, cid, effective_band, session_row)
    dist = band_distribution_from_rows(rows)
    attach_tier_chain(db, rows, cid, population, "bgceo")
    company_options = sorted({(r["user"]["company"] or "").strip()
                              for r in rows if (r["user"]["company"] or "").strip()})
    company_labels = {co: COMPANY_SHORT.get(co, co) for co in company_options}
    return render_template(
        "calibration_bg.html", active_view="calibration", tier="bgceo",
        scope_label=bg, rows=rows, distribution=dist,
        gaps=calibration_target_gaps(dist, CALIBRATION_TARGET), target=CALIBRATION_TARGET,
        company_options=company_options, company_labels=company_labels,
        people_count=len(rows), company_count=len(company_options),
        locked=locked, session=session_row,
        locked_by_name=_calibration_locked_by_name(db, session_row),
        bg=bg, cycle_id=cid,
        pending=pending, stale=locked and bool(pending), is_super_view=is_super(u),
    )


@app.route("/calibration/bg/adjust", methods=["POST"])
@login_required
def calibration_bg_adjust():
    u = current_user()
    db = get_db()
    bg = _bgceo_bg_for(u)
    if not bg or not (is_bgceo_of(u, bg) or is_super(u)):
        abort(403)
    cid = active_cycle_id(db)
    subject_id = _form_int("subject_id")
    new_band = (request.form.get("adjusted_band", "") or "").strip()
    justification = (request.form.get("justification", "") or "").strip()
    subject = db.execute(
        f"SELECT * FROM users WHERE id=? AND business_group=? AND role!='admin' "
        f"AND {calibration_population_sql()}", (subject_id, bg)).fetchone()
    redirect_bg = bg if is_super(u) else None
    if not subject:
        return _calibration_respond(False, "That person isn't in this Business Group.", "error",
                                     "calibration_bg_view", bg=redirect_bg)
    # Nobody calibrates themselves. The product already states this principle
    # for promotions -- "they are the one who APPROVES promotions ... the same
    # person shouldn't sit on both ends of that decision" -- but the three
    # calibration tiers never enforced it, so a BG CEO sat in his own list and
    # could set his own potential band, which then feeds the talent box and
    # merit. A super admin acting on someone else's scope is unaffected.
    if subject_id == u["id"]:
        return _calibration_respond(False, "You can't calibrate your own band. Ask the "
                                    "tier above to set it.", "error",
                                    "calibration_bg_view", bg=redirect_bg)
    _gro = gc_reads_only(db, subject_id)
    if _gro:   # their Group Chief group takes the whole call (the split's 100 : 0, 2026-10-22)
        return _calibration_respond(False, GC_READS_ONLY_MSG % (subject["full_name"], _gro), "error",
                                    "calibration_bg_view", bg=redirect_bg)
    if new_band not in ("Low", "Mid", "High"):
        return _calibration_respond(False, "Choose Low, Mid, or High.", "error",
                                     "calibration_bg_view", bg=redirect_bg)
    _t, _serr = _store_text(justification or "", "manager")
    if _serr:
        return _calibration_respond(False, _serr, "error", "calibration_bg_view", bg=redirect_bg)
    session_row = db.execute(
        "SELECT * FROM calibration_sessions WHERE cycle_id=? AND tier='bgceo' "
        "AND business_group=? AND scope_key=?", (cid, bg, bg)).fetchone()
    if session_row and session_row["locked_at"]:
        return _calibration_respond(False, "This Business Group's calibration is locked.", "error",
                                     "calibration_bg_view", bg=redirect_bg)
    _w = window_closed_tier(db, "bgceo", "pot", cid, scope=[bg])   # a late pass is this business group's
    if _w:
        return _calibration_respond(False, _w, "error", "calibration_bg_view", bg=redirect_bg)
    _bul = _tb_bu_lock_of(db, subject_id, cycle_id=cid)
    if _bul:   # the BG CEO locked their business unit on the Talent Box (2026-10-07)
        return _calibration_respond(False, f"{_bul} is locked — its people can't be moved now.", "error",
                                     "calibration_bg_view", bg=redirect_bg)
    session_row = _get_or_create_calibration_session(db, cid, "bgceo", bg, bg, bg)
    original = effective_band(db, subject, cid)["band"] or ""
    _calibration_upsert_adjustment(db, session_row["id"], subject_id, original, new_band,
                                    justification, u["id"])
    log_activity(db, u["id"], "calibration_adjust",
                 f"{subject['full_name']}: {original or 'No Data'} -> {new_band} (bg scope)",
                 target_user_id=subject_id)
    return _calibration_respond(True, f"{subject['full_name']}'s band set to {new_band}.", "ok",
                                 "calibration_bg_view", bg=redirect_bg)


