@app.route("/rate/<int:subject_id>", methods=["GET", "POST"])
@login_required
def rate(subject_id):
    u = current_user()
    db = get_db()
    # Employees rate only within the active cycle.
    cid = active_cycle_id(db)
    a = db.execute(
        "SELECT * FROM assignments WHERE subject_id=? AND assessor_id=? "
        "AND cycle_id=? AND archived=0",
        (subject_id, u["id"], cid),
    ).fetchone()
    if not a:
        abort(403)  # you can only rate people assigned to you in the active cycle
    _out = _rater_task_refusal(db, a)   # the colleague is out of the 360 this cycle ("out means out"): nothing is written
    if _out:
        if request.method == "POST" and request.form.get("ajax") == "1":
            return _out, 403
        flash(_out, "error")
        return redirect(url_for("my_assessments"))
    rate_cycle = active_cycle(db)
    # The review may not have opened yet (pre-briefing window): people can log in
    # and look around, but no feedback can be entered until the start date. This
    # also backstops the greyed-out button on My Assessments for typed URLs/AJAX.
    if not cycle_is_open(rate_cycle) and not is_demo(u):
        opens = _parse_cycle_start(rate_cycle)
        when = opens.strftime("%d %b %Y, %H:%M") if opens else "soon"
        if request.method == "POST" and request.form.get("ajax") == "1":
            return ("", 204)  # silent no-op for an auto-save before the cycle opens
        flash(f"The {rate_cycle['name']} review hasn't opened yet — it opens on "
              f"{when}. Please wait patiently; you'll be able to give feedback then.",
              "error")
        return redirect(url_for("my_assessments"))
    _w = window_closed(db, "f360", cid, subject_id=subject_id)   # the admin's 360 window for raters (2026-10-02)
    if _w and request.method == "GET":
        flash(_w, "error")
        return redirect(url_for("my_assessments"))
    subject = db.execute("SELECT * FROM users WHERE id=?", (subject_id,)).fetchone()
    ensure_responses(db, a["id"], subject, cid)
    # Demo/briefing accounts can re-open and re-submit any number of times so the
    # full flow can be shown repeatedly during a briefing; real accounts lock.
    locked = (a["status"] == "submitted") and not is_demo(u)

    if request.method == "POST":
        if locked:
            if request.form.get("ajax") == "1":
                return ("", 204)  # silent no-op for an auto-save on a locked form
            flash("You have already submitted this assessment.", "error")
            return redirect(url_for("rate", subject_id=subject_id))
        return _save_rating(db, a, subject)

    # Build grouped view with current answers + any saved per-principle comment. A submitted rating lists the statements
    # its answers hold, not its subject's live tier (2026-11-08).
    stmts = _fb_statements_for_rating(db, a["id"], subject["job_grade"], cid)
    ans = {r["statement_id"]: r["answer"] for r in db.execute(
        "SELECT statement_id, answer FROM responses WHERE assignment_id=?",
        (a["id"],)).fetchall()}
    comments = {r["criterion_id"]: r["comment"] for r in db.execute(
        "SELECT criterion_id, comment FROM criterion_comments WHERE assignment_id=?",
        (a["id"],)).fetchall()}
    grouped = []
    seen = {}
    for s in stmts:
        cid = s["criterion_id"]
        if cid not in seen:
            seen[cid] = {"criterion_id": cid, "name": s["criterion_name"],
                         "description": s["criterion_description"],
                         "comment": comments.get(cid, ""), "statements": []}
            grouped.append(seen[cid])
        seen[cid]["statements"].append({
            "statement_id": s["statement_id"], "text": s["text"],
            "is_future": s["is_future"], "answer": ans.get(s["statement_id"]),
        })
    was_reset = bool(a["reset_at"]) and not locked
    ai_enabled = ai_on("ai_360")
    if ai_enabled and not locked:
        # Seed each principle's badge with its current remaining uses / cooldown.
        for g in grouped:
            _used, remaining, reset_seconds = _ai_draft_quota(
                db, u["id"], subject_id, g["criterion_id"])
            g["ai_remaining"] = remaining
            g["ai_reset_seconds"] = reset_seconds
    return render_template("rate.html", subject=subject, assignment=a,
                           grouped=grouped, locked=locked, was_reset=was_reset,
                           rate_cycle=rate_cycle, ai_enabled=ai_enabled,
                           ai_limit=AI_DRAFT_DAILY_LIMIT)


def _feedback_submit(db, a, subject):
    """Submit ONE 360 assignment: every statement must be answered, then flip
    assignments.status='submitted'. ONE gate+write authority, shared by the /rate
    page (via _save_rating) and the unified review chat's feedback submit -- so the
    two can never disagree about what 'submitted' means. Returns (ok, error).
    Reads the current (in-transaction) answers, so callers may write first."""
    _out = _rater_task_refusal(db, a)   # the colleague is out of the 360 this cycle: refused before any write
    if _out:
        return False, _out
    if a["status"] == "submitted":
        return False, "Your feedback on %s has already been submitted." % subject["full_name"]
    # the window, for THIS colleague: a rater Group People reopened one feedback for may resubmit that one after the 360 closed,
    # never another (the request gate let them through on their pass)
    _w = window_closed(db, "f360", _row_get(a, "cycle_id"), subject_id=_row_get(a, "subject_id"))
    if _w:
        return False, _w
    total, incomplete = _fb_completion(db, a["id"])   # the subject's CURRENT tier only (2026-11-08, OH-H-0083)
    if not total or incomplete:
        return False, ("%d item(s) are still blank. Answer every statement before submitting."
                       % (incomplete or total))
    # a rating whose subject moved tier since the rater opened it is submitted on the current tier alone: the old tier's
    # rows go before it is locked, so the stored score and every later reader see one tier
    _fb_prune_assignment(db, a["id"], subject["job_grade"], a["cycle_id"])
    db.execute("UPDATE assignments SET status='submitted', submitted_at=datetime('now') "
               "WHERE id=?", (a["id"],))
    _reopen_close(db, _row_get(a, "subject_id"), ["f360"], actor_id=_row_get(a, "assessor_id"), ref=a["id"])
    _late_close_f360(db, _row_get(a, "assessor_id"), _row_get(a, "cycle_id"))   # a late pass is used once all is rated
    _rating_record_refresh(db, _row_get(a, "cycle_id"), [_row_get(a, "subject_id")], "f360_submit",
                           _row_get(a, "assessor_id"))
    db.commit()
    log_activity(db, a["assessor_id"], "submit",
                 "Submitted feedback on %s" % subject["full_name"])
    return True, None


def _save_rating(db, a, subject):
    action = request.form.get("action", "save")
    ajax = request.form.get("ajax") == "1"   # silent auto-save (fetch / sendBeacon)
    resp = db.execute(
        "SELECT id, statement_id FROM responses WHERE assignment_id=?", (a["id"],)
    ).fetchall()
    incomplete = 0
    for r in resp:
        val = request.form.get(f"ans_{r['statement_id']}")
        val = val if val in ("yes", "no") else None
        if val is None:
            incomplete += 1
        db.execute("UPDATE responses SET answer=? WHERE id=?", (val, r["id"]))

    # Save the optional per-principle comments (UPSERT). Always persisted, on
    # both Save draft and Submit; blank is allowed. A comment that reads as an instruction to the AI is not saved
    # (4-03): the answers still are, and the reason is shown.
    _refused = None
    for key in request.form:
        if not key.startswith("comment_"):
            continue
        try:
            cid = int(key[len("comment_"):])
        except ValueError:
            continue
        text = (request.form.get(key, "") or "").strip()[:2000]
        _t, _serr = _store_text(text)
        if _serr:
            _refused = _serr
            continue
        db.execute(
            "INSERT INTO criterion_comments(assignment_id, criterion_id, comment) "
            "VALUES (?,?,?) ON CONFLICT(assignment_id, criterion_id) "
            "DO UPDATE SET comment=excluded.comment",
            (a["id"], cid, text))

    if _refused:
        db.commit()
        if ajax:
            return jsonify(ok=False, reason="screened", error=_refused), 400
        flash(_refused, "error")
        return redirect(url_for("rate", subject_id=subject["id"]))
    if action == "submit" and incomplete > 0:
        db.commit()
        flash(f"{incomplete} item(s) are still blank. Answer every statement "
              "before submitting. Your progress has been saved as a draft.", "error")
    elif action == "submit":
        # Shared gate+write with the unified chat's feedback submit (one authority).
        ok, err = _feedback_submit(db, a, subject)
        if ok:
            flash(f"Your feedback on {subject['full_name']} has been submitted.", "ok")
            return redirect(url_for("my_assessments"))
        db.commit()
        flash(err, "error")
    else:
        db.commit()
        if ajax:
            return ("", 204)   # auto-save: no flash, no redirect
        flash("Draft saved.", "ok")
    return redirect(url_for("rate", subject_id=subject["id"]))


@app.route("/demo/reset/<int:subject_id>", methods=["POST"])
@login_required
def demo_reset_assessment(subject_id):
    """DEMO accounts only: fully reset one assessment so the whole flow can be
    shown again from scratch — clear every answer + comment, reset the AI-draft
    count for this person, and move them back to the To-do list (pending)."""
    u = current_user()
    if not is_demo(u):
        abort(403)
    db = get_db()
    cid = active_cycle_id(db)
    a = db.execute(
        "SELECT id FROM assignments WHERE subject_id=? AND assessor_id=? "
        "AND cycle_id=? AND archived=0", (subject_id, u["id"], cid)).fetchone()
    if not a:
        abort(403)
    db.execute("UPDATE responses SET answer=NULL WHERE assignment_id=?", (a["id"],))
    db.execute("DELETE FROM criterion_comments WHERE assignment_id=?", (a["id"],))
    db.execute("DELETE FROM feedback_remarks WHERE assignment_id=?", (a["id"],))
    db.execute("DELETE FROM ai_draft_usage WHERE assessor_id=? AND subject_id=?",
               (u["id"], subject_id))
    db.execute("UPDATE assignments SET status='pending', submitted_at=NULL, "
               "reset_at=NULL WHERE id=?", (a["id"],))
    db.commit()
    flash("Demo assessment reset — answers, comments and AI-draft count cleared. "
          "It's back in your To-do list.", "ok")
    return redirect(url_for("my_assessments"))


# 'Draft with AI' fair-use cap: at most AI_DRAFT_DAILY_LIMIT successful drafts
# per (assessor, subject, principle) PER DAY. The allowance refreshes at local
# midnight (MYT, UTC+8) — each calendar day the assessor gets a fresh 5, rather
# than a per-use rolling cooldown. Guards against runaway loops and bounds spend.
AI_DRAFT_DAILY_LIMIT = 5
AI_RESET_TZ = "+8 hours"        # Malaysia time (MYT) — the daily reset boundary
AI_RESET_TZ_BACK = "-8 hours"   # convert that local midnight back to UTC

# Flag-only injection/abuse heuristics for the 'Draft with AI' input. We never
# block a draft on these (false positives are fine) — a match just records a
# short excerpt in ai_draft_flags, surfaced in the daily read-only report.
# Lower-cased substring checks; kept high-signal to limit noise.
_AI_FLAG_PATTERNS = [
    ("instruction-override", (
        "ignore previous", "ignore the previous", "ignore all previous", "ignore prior",
        "ignore the above", "ignore your instruction", "ignore all instruction",
        "disregard previous", "disregard the above", "disregard all previous",
        "forget the above", "forget previous", "override the instruction", "bypass the")),
    ("prompt-extraction", (
        "system prompt", "your instructions", "your system prompt", "reveal your",
        "print your instruction", "repeat your instruction", "repeat the above instruction",
        "show your prompt", "what is your prompt")),
    ("role-injection", (
        "you are now", "pretend to be", "pretend you are", "act as if you are",
        "system:", "assistant:", "<|im_start|>", "<|im_end|>")),
    ("jailbreak", (
        "jailbreak", "developer mode", "do anything now", "dan mode",
        "without any restrictions", "no restrictions apply")),
]


def _ai_injection_flags(text):
    """Return sorted reason tags for any injection/abuse patterns found in
    `text` (lower-cased substring heuristics). Empty list = clean."""
    t = (text or "").lower()
    return sorted({reason for reason, needles in _AI_FLAG_PATTERNS
                   if any(n in t for n in needles)})


def _fmt_hms(seconds):
    seconds = max(0, int(seconds or 0))
    h, m = seconds // 3600, (seconds % 3600) // 60
    if h and m:
        return f"{h}h {m}m"
    if h:
        return f"{h}h"
    if m:
        return f"{m}m"
    return "under a minute"


def _ai_draft_quota(db, assessor_id, subject_id, criterion_id):
    """Per-day usage for one (assessor, subject, principle). The allowance
    refreshes at local (MYT) midnight. Returns (used, remaining, reset_seconds);
    reset_seconds is the time until midnight (0 unless the cap is currently hit).
    created_at is stored in UTC, so 'today' = since the last MYT midnight."""
    # UTC instant of the most recent MYT midnight: shift to MYT, snap to day
    # start, shift back to UTC.
    used = db.execute(
        "SELECT COUNT(*) FROM ai_draft_usage "
        "WHERE assessor_id=? AND subject_id=? AND criterion_id=? "
        "AND created_at >= datetime('now', ?, 'start of day', ?)",
        (assessor_id, subject_id, criterion_id, AI_RESET_TZ, AI_RESET_TZ_BACK),
    ).fetchone()[0]
    remaining = max(0, AI_DRAFT_DAILY_LIMIT - used)
    reset_seconds = 0
    if remaining == 0:
        # seconds until the next MYT midnight (when the allowance refreshes)
        sec = db.execute(
            "SELECT CAST((julianday('now', ?, 'start of day', '+1 day', ?) "
            "- julianday('now')) * 86400 AS INTEGER)",
            (AI_RESET_TZ, AI_RESET_TZ_BACK),
        ).fetchone()[0]
        reset_seconds = max(0, sec or 0)
    return used, remaining, reset_seconds


@app.route("/api/draft-feedback", methods=["POST"])
@login_required
def api_draft_feedback():
    """Rewrite/edit a feedback comment with Azure OpenAI, per the assessor's
    instruction. Returns JSON {ok, text, remaining, reset_seconds} or
    {ok:false, error}. CSRF is enforced by the global guard. Text is never
    stored here; only a usage timestamp is recorded (for the fair-use cap)."""
    db = get_db()
    if not ai_on("ai_360"):
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    u = current_user()
    draft_text = request.form.get("draft", "")
    instruction = request.form.get("instruction", "")
    principle = (request.form.get("principle", "") or "").strip()[:120] or None
    try:
        subject_id = int(request.form.get("subject_id", ""))
        criterion_id = int(request.form.get("criterion_id", ""))
    except (TypeError, ValueError):
        return jsonify(ok=False, error="Couldn't identify which comment to draft."), 400
    if len(draft_text) > ai_draft.MAX_DRAFT_CHARS + 100:
        return jsonify(ok=False, error="Your draft is too long to rewrite."), 400

    # The assessor must actually own this assignment in the active cycle.
    a = db.execute(
        "SELECT id, cycle_id, subject_id FROM assignments WHERE subject_id=? AND assessor_id=? "
        "AND cycle_id=? AND archived=0",
        (subject_id, u["id"], active_cycle_id(db)),
    ).fetchone()
    if not a:
        return jsonify(ok=False, error="You can only draft for people assigned to you."), 403
    _out = _rater_task_refusal(db, a)   # the colleague is out of the 360 this cycle: no draft for them
    if _out:
        return jsonify(ok=False, error=_out), 403
    if not active_cycle_is_open(db) and not is_demo(u):
        return jsonify(ok=False, error="The review hasn't opened yet."), 403

    command = (request.form.get("command", "") or "").strip()[:20]

    # Abuse/injection audit (flag-only — never blocks the draft). A genuine,
    # authenticated assessor's input is checked against injection heuristics;
    # on a match we store a short excerpt + reason for super-admin review.
    flags = _ai_injection_flags(draft_text + "\n" + instruction)
    if flags:
        db.execute(
            "INSERT INTO ai_draft_flags(assessor_id, subject_id, principle, "
            "command, reason, excerpt) VALUES (?,?,?,?,?,?)",
            (u["id"], subject_id, principle, command, ",".join(flags),
             (draft_text + "  ¦  instruction: " + instruction).strip()[:500]))
        db.commit()
        app.logger.warning("AI-draft flagged [%s] user=%s subject=%s",
                           ",".join(flags), u["id"], subject_id)

    # Rolling-window fair-use cap, scoped to this assessor + subject + principle.
    _used, remaining, reset_seconds = _ai_draft_quota(db, u["id"], subject_id, criterion_id)
    if remaining <= 0:
        return jsonify(
            ok=False, limited=True, remaining=0, reset_seconds=reset_seconds,
            error=(f"You've used all {AI_DRAFT_DAILY_LIMIT} AI drafts for this "
                   f"principle. It resets in {_fmt_hms(reset_seconds)}.")), 429

    try:
        text = ai_draft.draft(draft_text, instruction, principle=principle)
    except ai_draft.AIDraftNotConfigured:
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    except ai_draft.AIDraftError as e:
        app.logger.warning("AI draft failed: %s", e)
        return jsonify(ok=False, error="Couldn't reach the AI service — please try again."), 502

    # A rewrite may re-word the rater's comment, not add to it (2026-09-24) -- refused uncounted.
    _rg = _rewrite_grounding_error(draft_text, instruction, principle or "", text)
    if _rg:
        return jsonify(ok=False, error=_rg), 422
    # Only a successful draft counts against the cap.
    db.execute("INSERT INTO ai_draft_usage(assessor_id, subject_id, criterion_id) "
               "VALUES (?,?,?)", (u["id"], subject_id, criterion_id))
    db.commit()
    log_activity(db, u["id"], "ai_draft",
                 (f"{command}: " if command else "") + (principle or ""))
    _used, remaining, reset_seconds = _ai_draft_quota(db, u["id"], subject_id, criterion_id)
    return jsonify(ok=True, text=text, remaining=remaining,
                   limit=AI_DRAFT_DAILY_LIMIT, reset_seconds=reset_seconds)


# ---------------------------------------------------------------------------
# 'Draft with AI' for Performance Management -- reuses the same Azure OpenAI
# plumbing/fair-use idiom as the 360 feature above, but fully isolated
# tables/quota (pm_ai_draft_usage/pm_ai_draft_flags, keyed by field_key) so
# a user's 360 usage and PM usage never cross-contaminate.
# ---------------------------------------------------------------------------
def _pm_ai_draft_quota(db, user_id, field_key):
    """Per-day usage for one (user, field_key) -- mirrors _ai_draft_quota()'s
    exact shape, just against pm_ai_draft_usage's single field_key column
    instead of 360's 3-column (assessor/subject/criterion) key."""
    used = db.execute(
        "SELECT COUNT(*) FROM pm_ai_draft_usage "
        "WHERE user_id=? AND field_key=? "
        "AND created_at >= datetime('now', ?, 'start of day', ?)",
        (user_id, field_key, AI_RESET_TZ, AI_RESET_TZ_BACK),
    ).fetchone()[0]
    remaining = max(0, AI_DRAFT_DAILY_LIMIT - used)
    reset_seconds = 0
    if remaining == 0:
        sec = db.execute(
            "SELECT CAST((julianday('now', ?, 'start of day', '+1 day', ?) "
            "- julianday('now')) * 86400 AS INTEGER)",
            (AI_RESET_TZ, AI_RESET_TZ_BACK),
        ).fetchone()[0]
        reset_seconds = max(0, sec or 0)
    return used, remaining, reset_seconds


def _pm_ai_draft_respond(db, u, field_key, context_label, draft_text, instruction, command,
                          draft_fn=ai_draft.draft_pm, module="ai_pm", ground=True):
    """Shared body for every PM 'Draft with AI' route (employee's KPI note,
    employee's overall remark, manager's Justification, manager's overall
    remark) -- injection-flag-and-log, quota check, the actual Azure call,
    success-path usage insert + activity log. Returns the same
    {ok, text, remaining, limit, reset_seconds} / {ok:false, error[, limited]}
    shape api_draft_feedback() already returns, so every caller's JS can
    share one response-handling code path. draft_fn defaults to the
    employee-voice draft_pm(); manager-facing routes pass
    ai_draft.draft_pm_manager instead, since the two need different framing
    (first-person self-comment vs. third-person evaluative note)."""
    # `module` is the AI switch that OWNS this surface, not always "ai_pm".
    # It used to be hardcoded, which broke the promise on settings/_general.html
    # that switching a module off "hides the button entirely, and its endpoint
    # refuses" -- in BOTH directions. The five /technical/* routes come through
    # here, so Technical competency switched off left every one of them live
    # (only the button was hidden, at render time); and Performance switched off
    # killed technical and IDP drafting even with their own switches on.
    # None means the caller has already gated -- currently only the IDP route,
    # which enforces its own get_idp_settings() flag before calling.
    if module and not ai_on(module):
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    if len(draft_text) > ai_draft.MAX_DRAFT_CHARS + 100:
        return jsonify(ok=False, error="Your draft is too long to rewrite."), 400

    flags = _ai_injection_flags(draft_text + "\n" + instruction)
    if flags:
        db.execute(
            "INSERT INTO pm_ai_draft_flags(user_id, field_key, command, reason, excerpt) "
            "VALUES (?,?,?,?,?)",
            (u["id"], field_key, command, ",".join(flags),
             (draft_text + "  ¦  instruction: " + instruction).strip()[:500]))
        db.commit()
        app.logger.warning("PM AI-draft flagged [%s] user=%s field=%s",
                           ",".join(flags), u["id"], field_key)

    _used, remaining, reset_seconds = _pm_ai_draft_quota(db, u["id"], field_key)
    if remaining <= 0:
        return jsonify(
            ok=False, limited=True, remaining=0, reset_seconds=reset_seconds,
            error=(f"You've used all {AI_DRAFT_DAILY_LIMIT} AI drafts for this "
                   f"field. It resets in {_fmt_hms(reset_seconds)}.")), 429

    try:
        text = draft_fn(draft_text, instruction, context=context_label)
    except ai_draft.AIDraftNotConfigured:
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    except ai_draft.AIDraftError as e:
        app.logger.warning("PM AI draft failed: %s", e)
        return jsonify(ok=False, error="Couldn't reach the AI service — please try again."), 502

    # A rewrite may re-word what they wrote; it may not add to it (2026-09-24). Refused before the
    # usage is counted -- the model's invention should not cost them a draft. ground=False only for the
    # IDP development ACTIONS, which are forward-looking plans, not claims about what happened.
    if ground:
        _rg = _rewrite_grounding_error(draft_text, instruction, context_label, text)
        if _rg:
            return jsonify(ok=False, error=_rg), 422
    db.execute("INSERT INTO pm_ai_draft_usage(user_id, field_key) VALUES (?,?)",
               (u["id"], field_key))
    db.commit()
    log_activity(db, u["id"], "pm_ai_draft",
                 (f"{command}: " if command else "") + field_key)
    _used, remaining, reset_seconds = _pm_ai_draft_quota(db, u["id"], field_key)
    return jsonify(ok=True, text=text, remaining=remaining,
                   limit=AI_DRAFT_DAILY_LIMIT, reset_seconds=reset_seconds)


def _pm_parse_kpi_set(raw, valid_ids, max_lines=8):
    """Parse the model's JSON array of {id, weightage} and keep ONLY entries
    whose id is a real candidate from this person's own library slice.

    This is what makes the feature retrieval-augmented rather than
    generative: an id the model invented, or one belonging to another BG,
    is silently dropped here and can never reach the database. The weights
    are then re-normalised server-side to total exactly 100 -- the prompt
    asks for that, but the model is never trusted to deliver it. Returns []
    on anything unparseable, which the caller turns into a clean error."""
    text = (raw or "").strip()
    if text.startswith("```"):                      # tolerate a ```json fence
        text = text.strip("`").strip()
        if text[:4].lower() == "json":
            text = text[4:].strip()
    i, j = text.find("["), text.rfind("]")          # ignore any stray prose
    if i == -1 or j == -1 or j < i:
        return []
    try:
        data = json.loads(text[i:j + 1])
    except (ValueError, TypeError):
        return []
    if not isinstance(data, list):
        return []
    picks, seen = [], set()
    for item in data:
        if not isinstance(item, dict):
            continue
        try:
            lib_id = int(item.get("id"))
            weight = float(item.get("weightage"))
        except (TypeError, ValueError):
            continue
        if lib_id not in valid_ids or lib_id in seen:
            continue
        if not math.isfinite(weight) or weight <= 0:
            continue
        # An OPTIONAL base target. The model contributes judgement (how
        # ambitious should this be?); the server derives the actual rungs from
        # the admin's ladder shape, so the LLM never does the arithmetic.
        # Anything non-numeric, non-finite or non-positive is simply dropped
        # and the normal defaulting cascade fills in instead.
        base = None
        if item.get("target") is not None:
            try:
                b = float(item.get("target"))
                base = b if (math.isfinite(b) and b > 0) else None
            except (TypeError, ValueError):
                base = None
        seen.add(lib_id)
        picks.append({"id": lib_id, "weightage": weight, "target": base})
        if len(picks) >= max_lines:
            break
    if not picks:
        return []
    total = sum(p["weightage"] for p in picks)
    if total <= 0:
        return []
    for p in picks:
        p["weightage"] = round(p["weightage"] * 100.0 / total, 2)
    # Absorb rounding drift into the last line so the set totals exactly 100
    # and the employee isn't blocked from proposing by a 99.99.
    drift = round(100.0 - sum(p["weightage"] for p in picks), 2)
    picks[-1]["weightage"] = round(picks[-1]["weightage"] + drift, 2)
    return picks


@app.route("/performance/setting/draft-ai", methods=["POST"])
@login_required
def performance_kpi_setting_draft_ai():
    """'Suggest a scorecard with AI' -- the Phase-3 capstone.

    Grounded in the KPI Library, never generative: the model is handed only
    this person's own library slice (their BG + department/'*' + tier band)
    and may only return ids from it; _pm_parse_kpi_set() whitelists every id
    it returns. The suggestion lands as ordinary DRAFT rows in the employee's
    scorecard, which they can re-weight or remove before proposing -- the AI
    never proposes anything on their behalf. Same gate/quota/injection-flag
    scaffolding as _pm_ai_draft_respond(), but returns a row count rather
    than rewritten text."""
    u = current_user()
    if u["role"] == "admin":
        abort(404)
    db = get_db()
    ctx = _pm_setting_context(db, u)
    if ctx is None:
        return jsonify(ok=False, error="No active performance period."), 409
    if not ctx["editable"]:
        return jsonify(ok=False, error=_pm_setting_shut_reason(ctx)), 409
    if not ai_on("ai_pm"):
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    candidates = ctx["library"]
    if not candidates:
        return jsonify(ok=False,
                       error="There are no library KPIs for your department and tier yet."), 409

    instruction = (request.form.get("instruction", "") or "").strip()
    field_key = f"kpi_set:{ctx['period']['id']}"
    flags = _ai_injection_flags(instruction)
    if flags:
        db.execute(
            "INSERT INTO pm_ai_draft_flags(user_id, field_key, command, reason, excerpt) "
            "VALUES (?,?,?,?,?)",
            (u["id"], field_key, "kpi_set", ",".join(flags), instruction[:500]))
        db.commit()
        app.logger.warning("PM AI kpi-set flagged [%s] user=%s", ",".join(flags), u["id"])

    _used, remaining, reset_seconds = _pm_ai_draft_quota(db, u["id"], field_key)
    if remaining <= 0:
        return jsonify(
            ok=False, limited=True, remaining=0, reset_seconds=reset_seconds,
            error=(f"You've used all {AI_DRAFT_DAILY_LIMIT} AI suggestions for this "
                   f"period. It resets in {_fmt_hms(reset_seconds)}.")), 429

    context_label = (f"for a {ctx['tier']['name']} role"
                     + (f" in {u['department']}" if u["department"] else ""))
    try:
        raw = ai_draft.draft_kpi_set(context_label, candidates, instruction=instruction)
    except ai_draft.AIDraftNotConfigured:
        return jsonify(ok=False, error="The AI draft feature isn't switched on yet."), 503
    except ai_draft.AIDraftError as e:
        app.logger.warning("PM AI kpi-set failed: %s", e)
        return jsonify(ok=False, error="Couldn't reach the AI service — please try again."), 502

    by_id = {c["id"]: c for c in candidates}
    picks = _pm_parse_kpi_set(raw, set(by_id))
    if not picks:
        return jsonify(ok=False,
                       error="The AI didn't return a usable selection — please try again."), 502

    # Replace the current editable selection with the suggestion, in one
    # transaction. Only draft/returned rows are touched -- an already-approved
    # or proposed line is never in scope here (ctx['editable'] guarantees it).
    period = ctx["period"]
    db.execute(
        "DELETE FROM pm_kpi_targets WHERE cycle_id=? AND subject_id=? "
        "AND status IN ('draft','returned')", (period["id"], u["id"]))
    added = 0
    cfg = ctx["cfg"]
    mechanism = cfg["mechanism"] if cfg else "A"
    variant = cfg["variant"] if cfg else None
    for p in picks:
        lib = by_id[p["id"]]
        nums, source = pm_default_numbers(db, u, period, lib, cfg)
        # no AI figure is stored: the person sets every point from this year's plan (Chris, 2026-11-02)
        try:
            db.execute(
                "INSERT INTO pm_kpi_targets(cycle_id, subject_id, kpi_name, category, "
                "description, weightage, unit, method, rate1, rate2, rate3, rate4, rate5, "
                "threshold, target, multiple, excellence, business_group, company, "
                "department, created_by, status, library_id, number_source) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft',?,?)",
                (period["id"], u["id"], lib["kpi_name"], lib["category"], lib["description"],
                 p["weightage"], kpi_unit_normalise(lib["unit"]), lib["method"], nums["rate1"], nums["rate2"],
                 nums["rate3"], nums["rate4"], nums["rate5"], nums["threshold"], nums["target"],
                 nums["multiple"], nums["excellence"], u["business_group"], u["company"],
                 u["department"], u["id"], lib["id"], source))
            added += 1
        except sqlite3.IntegrityError:
            # Collides with an admin-imported target of the same name -- skip
            # that one line rather than failing the whole suggestion.
            continue
    db.execute("INSERT INTO pm_ai_draft_usage(user_id, field_key) VALUES (?,?)",
               (u["id"], field_key))
    db.commit()
    log_activity(db, u["id"], "pm_ai_kpi_set", f"{period['name']}: suggested {added} KPI(s)")
    _used, remaining, reset_seconds = _pm_ai_draft_quota(db, u["id"], field_key)
    return jsonify(ok=True, added=added, remaining=remaining,
                   limit=AI_DRAFT_DAILY_LIMIT, reset_seconds=reset_seconds)


@app.route("/performance/kpi/<int:kpi_target_id>/draft-ai", methods=["POST"])
@login_required
def performance_kpi_draft_ai(kpi_target_id):
    """'Draft with AI' for one KPI's note field -- same ownership/lock gate
    as performance_kpi_autosave(); own field_key/quota, isolated from 360."""
    u = current_user()
    db = get_db()
    target = db.execute("SELECT * FROM pm_kpi_targets WHERE id=? AND subject_id=?",
                        (kpi_target_id, u["id"])).fetchone()
    if not target:
        abort(404)
    target = dict(target)
    # Past periods are read-only. The fetch above is scoped to the caller but
    # NOT to a period, and pm_can_self_edit() returns True for any line with
    # no result row -- so without this a never-submitted line from a closed
    # half stays writable once the My PM period switcher can surface it.
    if target["cycle_id"] != active_pm_period_id(db):
        return jsonify(ok=False, error="This period is closed to edits."), 409
    attach_pm_chains(db, [target], include_drafts=True)
    if not pm_can_self_edit(target):
        return jsonify(ok=False, error="This line is no longer editable."), 409

    draft_text = request.form.get("draft", "")
    instruction = request.form.get("instruction", "")
    command = (request.form.get("command", "") or "").strip()[:20]
    field_key = f"note:{kpi_target_id}"
    context_label = f'about the KPI "{target["kpi_name"]}"'
    return _pm_ai_draft_respond(db, u, field_key, context_label, draft_text, instruction, command)


