# ---------------------------------------------------------------------------
# Admin: dashboard
# ---------------------------------------------------------------------------

def _ready_state(done, total):
    """done/total -> a state string, with ONE rule that matters: total == 0 is
    never "done".

    The admin front door used to report a completely unconfigured product as
    green, because "0 of 0" satisfied every comparison it made. Nothing
    configured is the state this checklist exists to surface, so the rule is
    spelled out here once rather than re-derived per step.
    """
    if not total:
        return "todo"
    if done >= total:
        return "done"
    return "partial" if done else "todo"


def _calib_lock_scopes(db, u, cyc):
    """Every calibration scope that locks this cycle, in this admin's scope, open or locked (admin round 4, canvas row 1:
    "no admin page shows which HOD / BU CEO / BG CEO scopes are still open"). One row per scope:
      - an HOD's department review (scope_key = the HOD's id), both axes;
      - a BU CEO's calibration of a business unit (scope_key = the unit), both axes -- Year-End only;
      - a business unit on the BG CEO's Talent Box (talent_box_bu_locks, or the group's two BG sessions) -- Year-End only.
    A BU CEO calibration the BG CEO's lock closed reads closed; a Talent Box unit can be locked any time (the BG CEO never
    waits). Grouped reads, no per-person loop: the readiness checklist, read on every admin page, counts these."""
    if not cyc:
        return []
    cid = cyc["id"]
    where, params = bg_scope(u, "u.business_group")
    pop = "u.role!='admin' AND " + calibration_population_sql("u")
    mid = cycle_is_mid_year(db, cid)

    def locks(table, tier):
        return {(r["business_group"], r["scope_key"]): r["locked_at"] for r in db.execute(
            "SELECT business_group, scope_key, locked_at FROM %s WHERE cycle_id=? AND tier=?" % table, (cid, tier))}

    def closes(cell):
        c = window_dates(db, cell, cid)[1]
        return _when_disp(c) if c else ""
    names = {}

    def name_of(uid):
        if uid not in names:
            r = db.execute("SELECT full_name FROM users WHERE id=?", (uid,)).fetchone()
            names[uid] = r["full_name"] if r else ""
        return names[uid]
    rows = []
    pm_h, pot_h = locks("pm_calibration_sessions", "hod"), locks("calibration_sessions", "hod")
    pm_h = {k[1]: v for k, v in pm_h.items()}
    pot_h = {k[1]: v for k, v in pot_h.items()}
    for r in db.execute("SELECT u.hod_id hid, COUNT(*) n, GROUP_CONCAT(DISTINCT TRIM(COALESCE(u.department,''))) depts, "
                        "GROUP_CONCAT(DISTINCT COALESCE(u.company,'')) cos, MIN(u.business_group) bg, "
                        "GROUP_CONCAT(DISTINCT u.business_group) bgs FROM users u "
                        "WHERE u.hod_id IS NOT NULL AND " + pop + where + " GROUP BY u.hod_id", params):
        if not hod_has_role(db, r["hid"]):   # a calibrator is no HOD (2026-10-30): no Department Review to track
            continue
        depts = sorted(d for d in (r["depts"] or "").split(",") if d)
        cos = sorted(c for c in (r["cos"] or "").split(",") if c)
        key = str(r["hid"])
        # an HOD across business groups (2026-10-29) names every group their people are in, not the first alphabetically;
        # display only, the lock keys are untouched
        bgs = sorted(b_ for b_ in (r["bgs"] or "").split(",") if b_)
        rows.append({"tier": "hod", "tier_label": "HOD · Department review", "scope": ", ".join(depts) or "Their people",
                     "sub": " · ".join(display_bg(b_) or b_ for b_ in bgs) if len(bgs) > 1 else ", ".join(cos),
                     "bg": r["bg"] or "", "bgs": bgs or [r["bg"] or ""], "companies": cos, "who": name_of(r["hid"]),
                     "role": "HOD", "key": key, "n": r["n"], "pm": pm_h.get(key), "pot": pot_h.get(key),
                     "pm_closed": None, "pot_closed": None, "closes": closes("pm_hod")})
    if not mid:
        bu_pm, bu_pot = locks("pm_calibration_sessions", "buceo"), locks("calibration_sessions", "buceo")
        bg_pm, bg_pot = locks("pm_calibration_sessions", "bgceo"), locks("calibration_sessions", "bgceo")
        tb = {(r["business_group"], r["company"]): r["locked_at"] for r in db.execute(
            "SELECT business_group, company, locked_at FROM talent_box_bu_locks WHERE period_id=?", (cid,))}
        holders = {}
        for (hb, hc), hr in buceo_holders(db).items():
            if not hr["left_at"]:
                holders[("bu", hb, hc)] = hr["full_name"]
        for h in db.execute("SELECT full_name, bgceo_bg FROM users WHERE left_at IS NULL AND COALESCE(bgceo_bg,'')!=''"):
            if h["bgceo_bg"]:
                holders[("bg", h["bgceo_bg"])] = h["full_name"]
        units = db.execute("SELECT u.business_group bg, u.company co, COUNT(*) n FROM users u WHERE "
                           "COALESCE(u.company,'')!='' AND " + pop + where + " GROUP BY u.business_group, u.company "
                           "ORDER BY u.business_group, u.company", params).fetchall()
        # units calibrated together this cycle are one scope, under their lead (row 6)
        _un = {(r["bg"], r["co"]): r["n"] for r in units}
        _joined = []
        for r in units:
            j = calib_join(db, cid, r["bg"], r["co"])
            if j and j["lead"] != r["co"]:
                continue
            ms = j["members"] if j else [r["co"]]
            _joined.append({"bg": r["bg"], "co": r["co"], "n": sum(_un.get((r["bg"], m), 0) for m in ms),
                            "label": j["label"] if j else r["co"], "members": ms})
        units = _joined
        # a calibration group locks on its own, by its calibrator (2026-10-22), counted apart from each unit it reaches;
        # one row a group, under the unit whose PAT it follows
        _grp_n = {}
        if bu_groups_all(db):
            for g_r in db.execute("SELECT gd_.group_id gid, u.company co, COUNT(*) n FROM users u JOIN calib_bu_group_units "
                                  "gd_ ON gd_.business_group=u.business_group AND gd_.company=u.company AND "
                                  "gd_.department=TRIM(COALESCE(u.department,'')) JOIN calib_bu_groups gg_ ON "
                                  "gg_.id=gd_.group_id AND gg_.active=1 WHERE " + pop + where
                                  + " GROUP BY gd_.group_id, u.company", params):
                _grp_n[(g_r["gid"], g_r["co"])] = g_r["n"]
            # ...and the people who came by "Everyone left in <unit>" (2026-10-27): one count for each calibrator holding it
            for g_r in db.execute("SELECT gl_.group_id gid, u.company co, COUNT(*) n FROM users u JOIN calib_bu_group_left "
                                  "gl_ ON gl_.business_group=u.business_group AND gl_.company=u.company JOIN "
                                  "calib_bu_groups gg_ ON gg_.id=gl_.group_id AND gg_.active=1 WHERE "
                                  + _bu_left_tier_sql("u") + " AND " + pop + where + " GROUP BY gl_.group_id, u.company",
                                  params):
                _grp_n[(g_r["gid"], g_r["co"])] = _grp_n.get((g_r["gid"], g_r["co"]), 0) + g_r["n"]

        def _closed_of(bg, co):
            bg_whole = bg_pm.get((bg, bg)) and bg_pot.get((bg, bg))
            return tb.get((bg, co)) or (bg_whole and max(bg_pm[(bg, bg)], bg_pot[(bg, bg)]))
        _shown = set()
        for r in units:
            bg, co = r["bg"], r["co"]
            tb_at = _closed_of(bg, co)
            closed = "Closed by the BG CEO's lock" if tb_at else None
            grows = []
            for m_ in r["members"]:
                r["n"] -= sum(n_ for (gid_, c_), n_ in _grp_n.items() if c_ == m_)
            for g_ in bu_groups_of_bg(db, bg):
                n_g = sum(_grp_n.get((g_["id"], c_), 0) for c_ in g_["units"])
                if not n_g or g_["id"] in _shown or (g_["company"] != co and g_["company"] in {x["co"] for x in units}):
                    continue
                _shown.add(g_["id"])
                gk = BU_GROUP_PREFIX + str(g_["id"])
                g_closed = ("Closed by the BG CEO's lock" if all(_closed_of(bg, c_) for c_ in g_["units"]) else None)
                grows.append({"tier": "buceo", "tier_label": "BU CEO · Calibration", "scope": g_["name"],
                             "sub": "Calibration group · " + ", ".join(display_company(bg, c_) or c_ for c_ in g_["units"]),
                             "bg": bg, "companies": list(g_["units"]), "who": name_of(g_["calibrator_id"]),
                             "role": "Calibrator", "n": n_g, "pm": bu_pm.get((bg, gk)), "pot": bu_pot.get((bg, gk)),
                             "pm_closed": g_closed if not bu_pm.get((bg, gk)) else None,
                             "pot_closed": g_closed if not bu_pot.get((bg, gk)) else None, "closes": closes("pm_buceo"),
                             "group_id": g_["id"], "group_co": g_["company"]})
            rows.append({"tier": "buceo", "tier_label": "BU CEO · Calibration", "scope": r["label"],
                         "sub": display_bg(bg) + (" · together this cycle" if len(r["members"]) > 1 else ""),
                         "bg": bg, "companies": r["members"], "who": holders.get(("bu", bg, co), ""), "role": "BU CEO",
                         "n": r["n"], "pm": bu_pm.get((bg, co)), "pot": bu_pot.get((bg, co)),
                         "pm_closed": closed if not bu_pm.get((bg, co)) else None,
                         "pot_closed": closed if not bu_pot.get((bg, co)) else None, "closes": closes("pm_buceo")})
            rows.extend(grows)
        for r in units:
            bg, co = r["bg"], r["co"]
            bg_whole = bg_pm.get((bg, bg)) and bg_pot.get((bg, bg))
            tb_at = tb.get((bg, co)) or (bg_whole and max(bg_pm[(bg, bg)], bg_pot[(bg, bg)]))
            rows.append({"tier": "bgceo", "tier_label": "BG CEO · Talent Box, by business unit", "scope": r["label"],
                         "sub": display_bg(bg), "bg": bg, "companies": r["members"], "who": holders.get(("bg", bg), ""),
                         "role": "BG CEO", "n": r["n"], "pm": tb_at or None, "pot": tb_at or None,
                         "pm_closed": None, "pot_closed": None, "closes": closes("tb_bgceo"), "anytime": True})
    for r in rows:
        r["locked"] = bool((r["pm"] or r["pm_closed"]) and (r["pot"] or r["pot_closed"]))
    return rows


def _home_lock_rows(db, u, cyc):
    """_calib_lock_scopes once a request: Home reads it for the readiness card and, on the HOD / BU CEO / BG CEO stages, for the
    stage table. It loops per HOD and per unit, so it is paid once, not twice (rows are copied: a reader may add keys)."""
    cache = _req_cache()
    k = ("_home_lock_rows", u["id"], cyc["id"] if cyc else None)
    if k not in cache:
        cache[k] = _calib_lock_scopes(db, u, cyc)
    return [dict(r) for r in cache[k]]


def _cycle_readiness(db, u, cyc):
    """The ordered steps to stand a cycle up, each marked from data the app
    already holds. Returns (groups, done_count, total_count).

    Why this exists: a cycle spans the Talent Management, Performance,
    Calibration and Reward menus, and nothing anywhere said what order to visit
    them in or how far through you were. Every configuration surface in this
    product is individually well written; what was missing was the sequence.

    Deliberately cheap -- plain COUNTs, no per-subject loops, matching
    admin_overview()'s own standard. A readiness panel that costs a page-load
    of work is one people route around.

    Scoped: a BG admin sees their own BG's readiness, not the org's, so the
    numbers match what they can actually act on.

    Steps for a module the cycle has switched off are omitted rather than shown
    as outstanding -- that is what switching it off is meant to mean.
    """
    cid = cyc["id"] if cyc else None
    scoped_bg = admin_bg_of(u)
    where, params = bg_scope(u, "u.business_group")

    if scoped_bg:
        bgs = [scoped_bg]
    else:
        bgs = [r["business_group"] for r in db.execute(
            "SELECT DISTINCT business_group FROM org_units WHERE active=1").fetchall()]
    ph = ",".join("?" * len(bgs)) if bgs else "''"

    def one(sql, args=()):
        r = db.execute(sql, list(args)).fetchone()
        return (r[0] or 0) if r else 0

    def bg_covered(table):
        """How many of this admin's BGs have at least one row in a per-BG config
        table. The unit an admin actually configures is the BG, so the count is
        BGs covered, not rows written."""
        if not bgs:
            return 0
        return one("SELECT COUNT(DISTINCT business_group) FROM %s "
                   "WHERE business_group IN (%s)" % (table, ph), bgs)

    def link(ep, args):
        """The step's page, only when this admin may open it: the menu's own rule, so a BG admin is never sent to a
        super-only page that then refuses them (2026-10-10)."""
        if not ep or not _admin_nav_allowed({"ep": ep}, u):
            return None
        return url_for(ep, **(args or {}))

    def step(label, why, ep, done, total, unit="", args=None, waits=None, lst=None):
        """A step measured as a RATIO -- N of M, where M is a real denominator
        the admin can see. `waits` names who moves it when that is not the admin (employees, raters, the leaders who
        lock): such a step reads "Waiting on ..." and is never counted on the admin's to-do (canvas row 1)."""
        st = _ready_state(done, total)
        if waits and st != "done" and total:
            st = "waiting"
        return {"label": label, "why": why,
                "url": link(ep, args), "waits": waits,
                # the people it still waits on, for the list panel (2026-10-20; the template shows it to the super admin)
                "list": url_for("admin_list_view", key=lst, fragment=1) if lst and st != "done" and total else None,
                "state": st, "n": done, "of": total,
                "pct": int(100 * done / total) if total else 0,
                "detail": ("%s of %s%s" % ("{:,}".format(done), "{:,}".format(total), unit) if total
                           else "nothing yet")}

    def has(label, why, ep, n, noun, args=None, detail=None):
        """A step measured by EXISTENCE -- it is either done or it has not
        started, and the count is context rather than a denominator.

        Kept distinct from step() on purpose. Forcing these through a ratio
        printed "0 of 1 sessions", which reads as one session sitting there
        waiting to be locked when in fact there were none at all."""
        return {"label": label, "why": why,
                "url": link(ep, args), "waits": None, "n": None, "of": None, "pct": 100 if n else 0,
                "state": "done" if n else "todo",
                "detail": (detail or "%d %s" % (n, noun)) if n else "nothing yet"}

    groups = []

    n_units = one("SELECT COUNT(*) FROM org_units WHERE active=1")
    n_people = one("SELECT COUNT(*) FROM users u WHERE u.role!='admin' AND %s%s"
                   % (calibration_population_sql("u"), where), params)
    n_lm_ok = one("SELECT COUNT(*) FROM users u JOIN users m ON m.id=u.manager_id AND m.left_at IS NULL AND m.id!=u.id "
                  "WHERE u.role!='admin' AND %s%s" % (calibration_population_sql("u"), where), params)
    groups.append({"label": "Foundation", "steps": [
        has("Business groups and units",
            "Everything else is keyed on these. Config written before they exist "
            "has nothing to attach to.",
            "admin_org", n_units, "units"),
        has("An active cycle",
            "The clock every module reads. Without one there is nothing for a "
            "module to report.",
            "admin_cycles", 1 if cyc else 0, "", detail=cyc["name"] if cyc else None),
        has("People loaded",
            "The roster. Panels, KPI targets and pay all resolve against it.",
            "admin_import_roster", n_people, "people"),
        # flagged on Home (Chris, 2026-10-18: "flag inside the admin page on the KPI lines without approver or user
        # without line manager assigned"): someone taking part with no line manager on file, one who has left, or
        # themselves -- the Data integrity list opens each person to fix it
        step("Everyone taking part has a line manager",
             "The line manager moderates their KPI lines, reviews their competencies and rates them in the 360. "
             "Without one their KPI lines have no moderator, so nothing of theirs can lock.",
             "admin_data_integrity", n_lm_ok, n_people, " people taking part", {"check": "no_manager"},
             lst="ready-no-lm"),
    ]})

    if not cyc:
        # Nothing downstream can be judged without a cycle, and inventing a
        # verdict would be the fabricated-zero problem this panel exists to fix.
        tot = sum(len(g["steps"]) for g in groups)
        return groups, sum(1 for g in groups for x in g["steps"] if x["state"] == "done"), tot

    if cycle_module_on("tm", db, cid):
        n_crit = one("SELECT COUNT(*) FROM cycle_criteria WHERE cycle_id=?", (cid,))
        # 2026-10-31, "out means out" for admin progress counts: live rows (not archived) of colleagues taking part in
        # the 360 only; "Assessor panels built" (n_subj_pop) and the released count (n_rel) stay as they were
        live360 = " AND a.archived=0 AND " + rater_task_sql("a")
        n_subj = one("SELECT COUNT(DISTINCT a.subject_id) FROM assignments a "
                     "JOIN users u ON u.id=a.subject_id WHERE a.cycle_id=?" + live360 + where,
                     [cid] + params)
        n_asg = one("SELECT COUNT(*) FROM assignments a JOIN users u ON u.id=a.subject_id "
                    "WHERE a.cycle_id=?" + live360 + where, [cid] + params)
        n_sub = one("SELECT COUNT(*) FROM assignments a JOIN users u ON u.id=a.subject_id "
                    "WHERE a.cycle_id=? AND a.status='submitted'" + live360 + where, [cid] + params)
        # released, of the same people n_subj counts (live rows, taking part): numerator and denominator one population
        n_rel = one("SELECT COUNT(*) FROM report_releases r JOIN users u ON u.id=r.subject_id "
                    "WHERE r.cycle_id=? AND EXISTS (SELECT 1 FROM assignments a WHERE a.subject_id=r.subject_id "
                    "AND a.cycle_id=r.cycle_id" + live360 + ")" + where, [cid] + params)
        # of the people taking part, those with a panel: the same people the step's list leaves out (2026-10-20)
        n_subj_pop = one("SELECT COUNT(*) FROM users u WHERE u.role!='admin' AND " + calibration_population_sql("u")
                         + where + " AND " + no360_sql("u") + " AND EXISTS (SELECT 1 FROM assignments a WHERE "
                         "a.subject_id=u.id AND a.cycle_id=?)", params + [cid])
        # ...out of the people who are on a panel at all: not Grade H, who take no part in the 360 (2026-10-28)
        n_people_360 = one("SELECT COUNT(*) FROM users u WHERE u.role!='admin' AND %s%s AND %s"
                           % (calibration_population_sql("u"), where, no360_sql("u")), params)
        groups.append({"label": "360 feedback", "steps": [
            has("Leadership framework",
                "The principles and behaviours people are actually rated on.",
                "admin_framework", n_crit, "principles"),
            step("Assessor panels built",
                 "Who rates whom. Nobody can be assessed without one.",
                 "admin_panel_build", n_subj_pop, n_people_360, " people taking part", lst="ready-no-panel"),
            step("Responses in",
                 "Submitted assessments. A report needs enough of these to be valid.",
                 "admin_assessors", n_sub, n_asg, " assessments", waits="raters", lst="f360-owing"),
            # reports are released on Cycle > Release results now, with the other results (the review, canvas K6)
            step("Reports released",
                 "Until released, nobody sees their own result.",
                 "admin_talent_release", n_rel, n_subj, " people", lst="ready-unreleased"),
        ]})

    # a cycle started with its modules closed is being prepared: its Performance set-up steps show (and flag a KPI
    # line with no moderator) before the module opens; the steps that wait on people come once it does (2026-10-18)
    awaiting = cycle_awaiting_open(db, cyc)
    if cycle_module_on("pm", db, cid) or awaiting:
        n_mech = bg_covered("pm_bg_config")
        mech_b = [r["business_group"] for r in db.execute(
            "SELECT business_group FROM pm_bg_config WHERE mechanism='B' "
            "AND business_group IN (%s)" % ph, bgs).fetchall()] if bgs else []
        # the cycle's own band starts (2026-10-29), the cycle being checked
        bands_ok = sum(1 for b in mech_b if _pm_cycle_band_table(db, cid, b))
        n_tgt = one("SELECT COUNT(*) FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
                    "WHERE t.cycle_id=?" + where, [cid] + params)
        n_chainless = one(
            "SELECT COUNT(*) FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
            "WHERE t.cycle_id=? AND NOT EXISTS (SELECT 1 FROM pm_kpi_target_approvers a "
            "WHERE a.kpi_target_id=t.id)" + _pm_chair_unmod_sql(db, "u") + where, [cid] + params)   # (the chair's reports have none by design)
        # of the people taking part: those with a KPI line, and those whose whole scorecard is in -- the same people
        # the steps' lists leave out (2026-10-20; before, any subject counted, so a list could be one off its step)
        n_tsubj_pop = one("SELECT COUNT(*) FROM users u WHERE u.role!='admin' AND " + calibration_population_sql("u")
                          + where + " AND EXISTS (SELECT 1 FROM pm_kpi_targets t WHERE t.subject_id=u.id "
                          "AND t.cycle_id=?)", params + [cid])
        # own lines only (2026-11-05): a BU KPI Group People fills is not the person's to submit, so it is left out of
        # "in"; someone whose every line is one has nothing to submit and leaves the denominator too
        _pop_ids = [r[0] for r in db.execute(
            "SELECT u.id FROM users u WHERE u.role!='admin' AND " + calibration_population_sql("u") + where
            + " AND EXISTS (SELECT 1 FROM pm_kpi_targets t WHERE t.subject_id=u.id AND t.cycle_id=?)", params + [cid])]
        _own = pm_own_results_map(db, cid, _pop_ids)
        n_scored_pop = sum(1 for i in _pop_ids if pm_own_all_in(_own.get(i)))
        n_bu_only_pop = sum(1 for i in _pop_ids if pm_own_bu_only(_own.get(i)))
        # people taking part whose whole own scorecard is submitted (the same people, scoped by the admin's groups)
        n_scored = n_scored_pop
        steps = [step("Scoring mechanism per business group",
                      "Decides how a KPI is scored. A BG without one scores nobody.",
                      "admin_performance_config", n_mech, len(bgs), " BGs")]
        if mech_b:
            steps.append(step("Rating cutoffs for achievement-% business groups",
                              "Turns an achievement % into a band, for this cycle (each cycle holds its own). "
                              "Without them every band pill in that BG renders blank.",
                              "admin_performance_config", bands_ok, len(mech_b), " BGs"))
        steps += [
            step("KPI targets in",
                 "Imported, or composed by employees and approved. Nothing scores "
                 "without them.",
                 "admin_import_kpi_targets", n_tsubj_pop, n_people, " people taking part",
                 lst="ready-no-kpi"),
            step("Every KPI line has a moderator",
                 "A KPI line with no moderator can never lock, so that person's "
                 "overall rating never completes.",
                 "admin_performance_exceptions", n_tgt - n_chainless, n_tgt, " KPI lines", lst="ready-kpi-nomod"),
        ]
        if not awaiting:
            steps.append(step("Results submitted",
                              "The employee's own numbers. Moderation has nothing to act on "
                              "until these are in.",
                              "admin_module_progress", n_scored_pop, max(n_people - n_bu_only_pop, 0), " people", {"key": "pm"},
                              waits="employees",
                              lst="ready-not-scored"))
        groups.append({"label": "Performance", "steps": steps})

    if cycle_module_on("calibration", db, cid):
        n_co = one("SELECT COUNT(DISTINCT company) FROM org_units WHERE active=1 "
                   "AND COALESCE(company,'')!='' AND business_group IN (%s)" % ph,
                   bgs) if bgs else 0
        n_pbt = one("SELECT COUNT(*) FROM pm_pbt_achievement WHERE cycle_id=? AND COALESCE(company,'')!='' "
                    "AND business_group IN (%s)" % ph, [cid] + bgs) if bgs else 0
        _lock_rows = _home_lock_rows(db, u, cyc)   # once a request: Home's stage table reads the same rows (2026-11-09)
        n_scopes = len(_lock_rows)
        n_locked = sum(1 for r in _lock_rows if r["locked"])
        # anyone with a released result: final performance / potential band (result_releases) or talent status
        n_trel = one("SELECT COUNT(*) FROM users u WHERE (u.id IN (SELECT subject_id FROM talent_releases WHERE "
                     "cycle_id=?) OR u.id IN (SELECT subject_id FROM result_releases WHERE cycle_id=?))" + where,
                     [cid, cid] + params)
        groups.append({"label": "Calibration and talent", "steps": [
            step("PAT achievement per business unit",
                 "Picks the reference distribution curve. Missing, and the unit "
                 "silently calibrates against the normal curve.",
                 "admin_performance_pbt", n_pbt, n_co, " units"),
            # The only step with no admin page, and deliberately so: calibration
            # is done in the HOD / BU CEO / BG CEO logins, and calibration_tier_of()
            # returns nothing for role='admin'. Saying that is better than a row
            # that looks like a dead link.
            step("Calibration locked",
                 "Every HOD department review, BU CEO calibration and Talent Box unit, locked by the leader who holds "
                 "it, in their own login. Lock status shows which are still open.",
                 "admin_calibration_locks", n_locked, n_scopes, " scopes", waits="leaders"),
            has("Results released",
                "Until released, the final bands and the talent status are internal to the calibrators.",
                "admin_talent_release", n_trel, "people released"),
        ]})

    # (the Reward block went with the archived module's code, 2026-10-11)

    tot = sum(len(g["steps"]) for g in groups)
    done = sum(1 for g in groups for x in g["steps"] if x["state"] == "done")
    return groups, done, tot


# The Home's business group x module grid (canvas J1, Chris 2026-10-10: "the admin page should show the overview first
# instead of 360 since we have expanded our modules. The overview should show the summary of each BG and each module
# progress"). (key, label, cycle module, the window that says when it opens, its progress page)
HOME_MATRIX_COLS = (("pm", "Performance", "pm", "pm_results"), ("f360", "360 Feedback", "tm", "f360"),
                    ("competency", "Competency", "tm", "tc_self"), ("calibration", "Calibration", "calibration",
                                                                    "tb_bgceo"),
                    ("idp", "Career Plan", "idp", "idp_self"))


# Home's 360 cell: one row per rater (live person owing at least one rating in the cycle), todo = rows not yet submitted.
_HOME_F360_RATERS_SQL = (
    "SELECT u.business_group, COUNT(*), SUM(CASE WHEN x.todo=0 THEN 1 ELSE 0 END) FROM (SELECT a.assessor_id, "
    "SUM(CASE WHEN a.status='submitted' THEN 0 ELSE 1 END) todo FROM assignments a WHERE a.cycle_id=? AND a.archived=0 AND "
    + rater_task_sql("a") + " GROUP BY a.assessor_id) x JOIN users u ON u.id=x.assessor_id WHERE "
    "u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0")


def _home_cell_taking_sql(col, cyc):
    """The taking-part rule for Home's Performance and Competency cells, as ` AND <predicate>` on the alias `u` (or "").
    Chris 2026-11-08: progress counts only people taking part in that part (KPI lines or competencies set up are not enough).
    participant_sql describes the ACTIVE cycle only, so a past cycle keeps its plain read (""). The cell (_home_bg_matrix)
    and its list (_list_home_cell) both call this, so they can never disagree. Binds no parameter."""
    mod = {"pm": "pm", "competency": "competency"}.get(col)
    if not mod or not (cyc and cyc["is_active"]):
        return ""
    return " AND " + participant_sql("u", mod)


def _home_bg_matrix(db, u, cyc, stage=None):
    """{cols, rows, total, notes} -- each business group in the admin's scope, each live module's progress: KPI
    scorecards submitted, 360 raters done, competency self-assessments submitted, business units the BG CEO has locked on
    the Talent Box, Career Plans shared. Grouped COUNTs, one per module, scoped by bg_scope -- never a per-person loop,
    because Home is the page every admin opens first. A module whose window hasn't opened says when it opens,
    whatever is already done (Chris, 2026-10-30).
    The stage switch (Chris, 2026-11-09): on a Year-End or Mid-Year the table follows the cycle's stage, `stage` (?stage=) picking
    another for one visit; Employees is this table without Calibration, the others are _home_stage_matrix. An Early Year or a past
    cycle has no switch and keeps this table whole."""
    cid = cyc["id"] if cyc else None
    sw = _home_stage_info(db, cyc)
    on = _home_stage_pick(sw, stage) if sw else None
    if sw and on != "emp":
        return _home_stage_matrix(db, u, cyc, sw, on)
    ubgc, ubgp = bg_scope(u, "u.business_group")
    live = "u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0"

    def grouped(sql, args=()):
        return {(r[0] or ""): (r[1] or 0, r[2] or 0) for r in db.execute(sql, tuple(args) + tuple(ubgp))}
    # Chris 2026-11-07: People reads "taking part | all". participant_sql always describes the ACTIVE cycle, so the split is
    # worked out only when the viewed cycle is that one (a past cycle shows the total alone, as before). One grouped read.
    split = bool(cyc and cyc["is_active"])
    people = grouped("SELECT u.business_group, COUNT(*), " +
                     ("SUM(CASE WHEN " + participant_sql("u") + " THEN 1 ELSE 0 END)" if split else "0") +
                     " FROM users u WHERE " + live + ubgc + " GROUP BY u.business_group")
    cols, data = [], {}
    for key, label, mod, cell in HOME_MATRIX_COLS:
        if not cid or not cycle_module_on(mod, db, cid):
            continue
        if sw and key == "calibration":   # Calibration lives in the BG CEOs' stage only (Chris, 2026-11-09)
            continue
        if key == "pm":   # a scorecard is in when every one of the person's OWN KPI lines is submitted (BU lines Group People fills are left out)
            # Chris 2026-11-08: only people taking part in Performance (_home_cell_taking_sql); lines set up are not enough
            pmp = db.execute("SELECT DISTINCT u.id, u.business_group FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id "
                             "WHERE t.cycle_id=? AND " + live + _home_cell_taking_sql("pm", cyc) + ubgc,
                             (cid,) + tuple(ubgp)).fetchall()
            own = pm_own_results_map(db, cid, [r["id"] for r in pmp])
            d = {}
            for r in pmp:
                m = own.get(r["id"])
                if m and m["own_n"]:
                    n_, s_ = d.get(r["business_group"] or "", (0, 0))
                    d[r["business_group"] or ""] = (n_ + 1, s_ + (1 if pm_own_all_in(m) else 0))
            word = "scorecards submitted"   # the Overview counts approved ones; Home says which it counts
        elif key == "f360":
            # Chris 2026-11-06: every column counts PEOPLE; the 360 counts raters, by the RATER's group: a rater is a live
            # person who owes at least one rating this cycle, done when every one of those rows is submitted
            # ("out means out": only colleagues taking part in the 360, 2026-10-31)
            d = grouped(_HOME_F360_RATERS_SQL + ubgc + " GROUP BY u.business_group", (cid,))
            word = "raters done"
        elif key == "competency":
            d = grouped("SELECT u.business_group, COUNT(*), SUM(CASE WHEN s.submitted_at IS NOT NULL THEN 1 ELSE 0 END) "
                        "FROM (SELECT DISTINCT subject_id FROM tc_assignments WHERE cycle_id=?) x JOIN users u "
                        "ON u.id=x.subject_id LEFT JOIN tc_assessments s ON s.subject_id=x.subject_id AND s.cycle_id=? "
                        "WHERE " + live + _home_cell_taking_sql("competency", cyc)   # Chris 2026-11-08: taking part in Competency only
                        + ubgc + " GROUP BY u.business_group", (cid, cid))
            word = "self-assessed"
        elif key == "calibration":   # the BG CEO's final say: business units locked on the Talent Box
            # Chris 2026-11-08: progress counts only people taking part in that part. The units to lock are the ones the BG CEO's
            # Talent Box lists (_talent_box_resolve, bgceo tier: the calibration population, calibration_population_sql, any
            # part, no KPI-line rule; _talent_box_lock_bu locks each company of it). Active cycle only: a past cycle keeps its
            # plain read (units with a KPI line).
            if cyc["is_active"]:
                units = grouped("SELECT u.business_group, COUNT(DISTINCT u.company), 0 FROM users u WHERE " + live
                                + " AND COALESCE(u.company,'')!='' AND " + calibration_population_sql("u")
                                + ubgc + " GROUP BY u.business_group")
            else:
                units = grouped("SELECT u.business_group, COUNT(DISTINCT u.company), 0 FROM users u JOIN pm_kpi_targets t "
                                "ON t.subject_id=u.id AND t.cycle_id=? WHERE " + live + " AND COALESCE(u.company,'')!=''"
                                + ubgc + " GROUP BY u.business_group", (cid,))
            lk = {(r[0] or ""): r[1] for r in db.execute(
                "SELECT business_group, COUNT(*) FROM talent_box_bu_locks WHERE period_id=? AND company!='' GROUP BY business_group",
                (cid,))}
            d = {bg: (n, min(n, lk.get(bg, 0))) for bg, (n, _z) in units.items()}
            word = "units locked"
        else:
            year = pm_idp_plan_year(cyc)
            # Chris 2026-11-06: the Career Plan is counted over the people in the review only (idp_count_sql), as its own Progress
            counted = grouped("SELECT u.business_group, COUNT(*), 0 FROM users u WHERE " + live + " AND " + idp_count_sql("u") +
                              ubgc + " GROUP BY u.business_group")
            shared = grouped("SELECT u.business_group, COUNT(*), 0 FROM pm_idp i JOIN users u ON u.id=i.subject_id "
                             "WHERE i.plan_year=? AND i.status!='draft' AND " + live + " AND " + idp_count_sql("u") + ubgc +
                             " GROUP BY u.business_group", (year,))
            d = {bg: (n, shared.get(bg, (0, 0))[0]) for bg, (n, _z) in counted.items()}
            word = "plans shared"
        st = window_state(db, cell, cid)
        opens = window_dates(db, cell, cid)[0] if st == "not_open" else None
        cols.append({"key": key, "label": label, "word": word, "state": st, "cell": cell,
                     "opens": _st_day(opens) if opens else None,
                     "color": ADMIN_SECTION_BY_KEY.get(key, {}).get("color"), "url": _admin_module_entry(key, u)})
        data[key] = d
    sup = is_super(u)

    def link(key, bg):
        if key == "pm" or key == "competency":
            return url_for("admin_module_progress", key=key, **({"fbg": bg} if sup and bg else {}))
        if key == "f360":
            return url_for("admin_assessors", **({"fbg": bg} if sup and bg else {}))
        if key == "calibration":
            return url_for("admin_talent_box", **({"bg": bg} if bg else {}))
        return url_for("admin_module_progress", key="idp", **({"fbg": bg} if sup and bg else {}))

    def cell_of(c, n, done, bg):
        if c["state"] == "not_open":   # whatever is already in (BU KPI results filled early), a part not open says when
            return {"pct": None, "sub": "opens %s" % c["opens"] if c["opens"] else "not open yet", "url": None}
        if not n:
            return {"pct": None, "sub": "none set", "url": None}
        pct = int(done * 100 / n)    # floored: 99.6% is not done
        return {"pct": pct, "sub": "%s of %s %s" % ("{:,}".format(done), "{:,}".format(n), c["word"]),
                "url": link(c["key"], bg) if bg is not None else None,
                # its people, for the list panel (2026-10-20; calibration counts units, so it has none)
                "list": url_for("admin_list_view", key="home-cell", col=c["key"], fragment=1,
                                **({"bg": bg} if bg else {})) if c["key"] in HOME_CELL_WORDS else None,
                # the All row's cell had no page; as a list's door it goes to that list's full page
                "list_page": url_for("admin_list_view", key="home-cell", col=c["key"], **({"bg": bg} if bg else {}))
                if c["key"] in HOME_CELL_WORDS else None}
    bgs = sorted(set(people) | {bg for d in data.values() for bg in d})
    bgs = [b for b in bgs if b and can_access_bg(u, b)]
    # A row per business group that is one now: in Org structure, or with people in it. A name left only on closed
    # accounts (the old demo's "Group Office", a group renamed since) has no people and no settings, so it gets no row
    # (Chris, 2026-10-17: "why is there group office ... with 0 people? and i can't find their setting anywhere"); what
    # it still holds -- a leaver's 360 ratings count -- stays in the total, said under the table.
    real = set(org_bgs(db, active_only=False)) | {bg for bg, (n, _z) in people.items() if n}
    gone = [b for b in bgs if b not in real]
    rows = []
    for bg in bgs:
        if bg in real:
            rows.append({"bg": bg, "people": people.get(bg, (0, 0))[0],
                         "taking_part": people.get(bg, (0, 0))[1] if split else None,
                         "cells": [cell_of(c, *data[c["key"]].get(bg, (0, 0)), bg) for c in cols]})
    tot = {"people": sum(r["people"] for r in rows),
           "taking_part": sum(r["taking_part"] for r in rows) if split else None,
           "cells": [cell_of(c, sum(data[c["key"]].get(bg, (0, 0))[0] for bg in bgs),
                             sum(data[c["key"]].get(bg, (0, 0))[1] for bg in bgs), None) for c in cols]}
    gone_parts = []
    for c in cols:
        n_ = sum(data[c["key"]].get(bg, (0, 0))[0] for bg in gone)
        if n_:
            done_ = sum(data[c["key"]].get(bg, (0, 0))[1] for bg in gone)
            gone_parts.append("%s %s of %s %s" % (c["label"], "{:,}".format(done_), "{:,}".format(n_), c["word"]))
    gone_note = ("All business groups also counts people who have left under a group name no longer in Org structure "
                 "(%s): %s." % (", ".join(display_bg(b) for b in gone), "; ".join(gone_parts))) if gone_parts else ""
    notes = _home_matrix_notes(db, cid, cols, rows, tot)   # what stands out, in words
    if cid and cycle_module_on("pm", db, cid):
        notes += _home_chainless_note(db, u, cid)
    return {"cols": cols, "rows": rows, "total": tot, "notes": notes, "gone_note": gone_note,
            "stage": _home_stage_bar(sw, on) if sw else None, "who": None, "extra_cols": []}


# ---------------------------------------------------------------------------------------------------------------------------
# Home's stage switch (Chris, 2026-11-09, canvas [design canvas link removed], "Yes, as drawn"; on counting:
# "it should go by LM count, like CHBM has 170 line managers, the progress tracking should track out of these 170, how many have
# completed"). The business-group table follows the cycle's stage: Employees (today's table, Calibration taken off), Line managers,
# HODs, BU CEOs, BG CEOs. Today's stage is worked out from the cycle's dates, nothing is stored; ?stage= picks another for one
# visit. A Year-End has all five, a Mid-Year Employees / Line managers / HODs (the cells the cycle uses decide), an Early Year or a
# past cycle none (today's table). Admin page only: no new access right, no write route.
# ---------------------------------------------------------------------------------------------------------------------------
# (key, label, what the stage does, the window cells it spans)
HOME_STAGES = (
    ("emp", "Employees", "Employees check in", ("pm_results", "tc_self", "idp_self", "f360")),
    ("lm", "Line managers", "Line managers approve and review", ("pm_approve", "tc_approve", "idp_review")),
    ("hod", "HODs", "HODs submit department reviews", ("pm_hod", "pot_hod")),
    ("bu", "BU CEOs", "BU CEOs calibrate their units", ("pm_buceo", "pot_buceo")),
    ("bg", "BG CEOs", "BG CEOs lock the Talent Box", ("tb_bgceo",)))
# the columns of each stage after Employees: (key, label, cycle module, the window cell that says when it opens)
HOME_STAGE_COLS = {
    "lm": (("pm", "Performance", "pm", "pm_approve"), ("competency", "Competency", "tm", "tc_approve"),
           ("idp", "Career Plan", "idp", "idp_review")),
    "hod": (("pm", "Performance", "pm", "pm_hod"), ("pot", "Potential", "calibration", "pot_hod")),
    "bu": (("pm", "Performance", "pm", "pm_buceo"), ("pot", "Potential", "calibration", "pot_buceo")),
    "bg": (("calibration", "Talent Box", "calibration", "tb_bgceo"),)}
HOME_STAGE_WORDS = {"lm": "line managers done", "hod": "department reviews submitted", "bu": "BU CEOs done", "bg": "units locked"}
HOME_STAGE_WHO = {"lm": "Line managers", "hod": "HODs", "bu": "BU CEOs", "bg": "Units"}
# the section whose colour a stage column wears
_HOME_STAGE_COLOR = {"pot": "calibration"}
# a line manager's part -> the Progress page and the stage on it that holds what waits on them (non-super admins' cell link)
_HOME_LM_PROGRESS = {"pm": ("pm", "results"), "competency": ("competency", "submitted"), "idp": ("idp", "shared")}


def _home_stage_cols(db, cid, cyc, key):
    """The columns a stage shows in this cycle: its module is on (Potential goes with the calibration module: no potential axis, no
    column) and, after Employees, its window cell is one the cycle uses. Employees is today's table without Calibration."""
    used = set(_cycle_cells_used(cyc))
    if key == "emp":
        return [c for c in HOME_MATRIX_COLS if c[0] != "calibration" and cycle_module_on(c[2], db, cid)]
    return [c for c in HOME_STAGE_COLS.get(key, ()) if c[3] in used and cycle_module_on(c[2], db, cid)]


def _home_stage_info(db, cyc):
    """None when Home shows today's table with no switch (no cycle, a past cycle, an Early Year, or fewer than two stages the cycle
    uses), else {"stages": [{key, label, what, state, o, c}], "today": key}. A stage's window runs from the earliest opening to the
    latest close of the cells the cycle uses; its state is open / closed / not_open by those dates (a gap between its own cells
    still reads open). Today's stage = the one that opened most recently and is still open; none open: the last to close; before
    any opens: the first (Employees)."""
    if not cyc or not cyc["is_active"] or cycle_row_is_early_year(cyc):
        return None
    cid = cyc["id"]
    used = set(_cycle_cells_used(cyc))
    now = _now_myt()
    out = []
    for key, label, what, cells in HOME_STAGES:
        cu = [c for c in cells if c in used]
        if not cu or not _home_stage_cols(db, cid, cyc, key):
            continue
        ds = [window_dates(db, c, cid) for c in cu]
        os_ = [x for x in (_parse_when(d[0]) for d in ds) if x]
        cs_ = [x for x in (_parse_when(d[1]) for d in ds) if x]
        o, c_ = (min(os_) if os_ else None), (max(cs_) if cs_ else None)
        states = [window_state(db, c, cid, now) for c in cu]
        if "open" in states:
            state = "open"
        elif o and now < o:
            state = "not_open"
        elif c_ and now > c_:
            state = "closed"
        elif o and c_:
            state = "open"
        else:
            state = "not_open"
        out.append({"key": key, "label": label, "what": what, "state": state, "o": o, "c": c_})
    if len(out) < 2:
        return None
    opn = [(s["o"], i, s["key"]) for i, s in enumerate(out) if s["state"] == "open"]
    if opn:   # the most recently opened; stages with no dates (open all cycle) tell nothing, so the first of them
        dated = [x for x in opn if x[0]]
        today = max(dated)[2] if dated else opn[0][2]
    else:
        cl = [(s["c"] or datetime.min, i, s["key"]) for i, s in enumerate(out) if s["state"] == "closed"]
        today = max(cl)[2] if cl else out[0]["key"]
    return {"stages": out, "today": today, "now": now}


def _home_stage_pick(sw, stage):
    """The stage on screen: ?stage= when the cycle has it, else today's."""
    return stage if stage in {s["key"] for s in sw["stages"]} else sw["today"]


def _home_stage_bar(sw, on):
    """What the strip under the title draws: the switch (a link each, with its dot), the line beside it, and the way back."""
    now = sw["now"]
    by = {s["key"]: s for s in sw["stages"]}
    seg = [{"key": s["key"], "label": s["label"], "active": s["key"] == on, "href": url_for("admin_overview", stage=s["key"]),
            "dot": {"open": "open", "closed": "closed", "not_open": "later"}[s["state"]]} for s in sw["stages"]]
    s = by[on]
    span = _cal_span(s["o"], s["c"]) if (s["o"] or s["c"]) else ""
    if s["state"] == "open":
        left = (s["c"].date() - now.date()).days if s["c"] else None
        tail = "open" if left is None else "closes today" if left <= 0 else "%d day%s left" % (left, "" if left == 1 else "s")
    elif s["state"] == "closed":
        tail = "closed %s" % s["c"].strftime("%-d %b")
    else:
        tail = ("opens %s" % s["o"].strftime("%-d %b")) if s["o"] else "not open yet"
    today = by[sw["today"]]
    nxt = min((x for x in sw["stages"] if x["state"] == "not_open" and x["o"]), key=lambda x: x["o"], default=None)
    return {"switch": seg, "on": on, "today": sw["today"], "is_today": on == sw["today"], "what": s["what"], "span": span,
            # the header's "Open now" / "opens" chips, named by stage while the switch is on (the table on screen can be any stage)
            "open_now": [x["label"] for x in sw["stages"] if x["state"] == "open"],
            "next_opens": {"label": nxt["label"], "opens": _st_day(nxt["o"].strftime("%Y-%m-%d %H:%M"))} if nxt else None,
            "tail": tail, "tail_b": s["state"] == "open",
            "back": None if on == sw["today"] else {"label": "Back to today's stage (%s)" % today["label"],
                                                     "href": url_for("admin_overview")}}


def _home_add(tal, lm, bg, waiting):
    """One thing that reached `lm` in `bg`: counted, and waiting on them when `waiting`."""
    e = tal.setdefault(lm, {}).setdefault(bg, {"w": 0, "n": 0})
    e["n"] += 1
    e["w"] += 1 if waiting else 0


def _home_lm_work(db, u, cyc, keys):
    """{part: {line manager id: {business group: {"n": reports whose work reached them, "w": of those still waiting on them}}}}
    for the parts in `keys` ('pm' | 'competency' | 'idp'), over the people in this admin's scope, grouped by the REPORT's group.
    Batched: a handful of reads over the whole population, never one a person, a line manager or a unit. The people who count are
    the leader progress email's (lp_person_parts: taking part in that part, a submission / a self-assessment / a shared plan reached
    the manager), minus the Executive Chairman's people nobody moderates / reviews.
      pm          the line manager is the approver at STEP 1 of the report's KPI lines (pm_kpi_target_approvers.seq=1) and a line
                  waits until that step has acted (pm_kpi_approvals.seq=1): a later approver still to act holds nobody up. A BU KPI
                  Group People fills is nobody's to approve (left out as pm_own_results_map leaves it out).
      competency  the report's reviewer (the line manager, one level up past a left-out manager, _cycle_review_managers); waiting
                  until tc_assessments.reviewed_at.
      idp         the line manager: KPI step 1 or the manager (both reviewers by _idp_is_reviewer_of; a step-2 approver is not counted);
                  waiting until the plan is closed."""
    cid = cyc["id"]
    ubgc, ubgp = bg_scope(u, "u.business_group")
    live = "u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0"
    bg_of = {r[0]: r[1] or "" for r in db.execute("SELECT u.id, u.business_group FROM users u WHERE " + live + ubgc, ubgp)}
    mgr = {r[0]: r[1] for r in db.execute("SELECT u.id, u.manager_id FROM users u WHERE " + live)}   # every live person: who may lead
    out_ids = {r[0] for r in db.execute("SELECT u.id FROM users u WHERE " + live + " AND " + unit_out_sql("u"))} \
        if cycle_exclusions(db, cid) else set()

    def reviewer(s, nobody):   # the shared function's rule, batched: the manager, climbing past a left-out one
        m = mgr.get(s)
        for _ in range(6):
            if m is None or m not in mgr:
                return None
            if m not in out_ids:
                return None if (m == nobody or m == s) else m
            m = mgr.get(m)
        return None
    want = {"pm": "pm_results", "competency": "tc_self", "idp": "idp_self"}
    people = _lp_people(db)
    idp_people = _lp_people(db, idp=True) if "idp" in keys else None
    per = lp_person_parts(db, cyc, [want[k] for k in keys], people=people, idp_people=idp_people)
    out = {}
    if "pm" in keys:
        nomod = _pm_chair_unmod_ids(db)
        subm = {s for s, (_n, d, _a) in per.get("pm_results", {}).items() if d and s in bg_of and s not in nomod}
        rows, ids = [], sorted(subm)
        for i in range(0, len(ids), 500):
            rows += db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(ids[i:i + 500])), ids[i:i + 500]).fetchall()
        bun = _pm_bu_names_map(db, rows, cid) if rows else {}
        seen = {}   # (line manager, report) -> [own lines at their step, of those not yet acted on]
        for r in db.execute(
                "SELECT t.subject_id, t.kpi_name, ap.approver_id, (a.kpi_target_id IS NOT NULL) FROM pm_kpi_targets t "
                "JOIN pm_kpi_target_approvers ap ON ap.kpi_target_id=t.id AND ap.seq=1 "
                "LEFT JOIN pm_kpi_results r ON r.kpi_target_id=t.id LEFT JOIN pm_kpi_approvals a ON a.kpi_target_id=t.id AND a.seq=1 "
                "WHERE t.cycle_id=? AND COALESCE(r.admin_filled,0)=0", (cid,)):
            s, lm = r[0], r[2]
            if s not in subm or lm not in mgr or lm == s or " ".join((r[1] or "").lower().split()) in (bun.get(s) or ()):
                continue
            e = seen.setdefault((lm, s), [0, 0])
            e[0] += 1
            e[1] += 0 if r[3] else 1
        tal = {}
        for (lm, s), (_n, w) in seen.items():
            _home_add(tal, lm, bg_of[s], w > 0)
        out["pm"] = tal
    if "competency" in keys:
        subm = {s for s, (_n, d, _a) in per.get("tc_self", {}).items() if d and s in bg_of} - _tc_chair_unreviewed_ids(db)
        rev = {r[0] for r in db.execute("SELECT subject_id FROM tc_assessments WHERE cycle_id=? AND reviewed_at IS NOT NULL", (cid,))}
        nobody, tal = _chair_norev_id(db, "competency"), {}
        for s in subm:
            m = reviewer(s, nobody)
            if m:
                _home_add(tal, m, bg_of[s], s not in rev)
        out["competency"] = tal
    if "idp" in keys:
        shared = {s for s, (_n, d, _a) in per.get("idp_self", {}).items() if d and s in bg_of} - _idp_chair_unreviewed_ids(db)
        closed = {r[0] for r in db.execute("SELECT subject_id FROM pm_idp WHERE plan_year=? AND status='closed'",
                                           (pm_idp_plan_year(cyc),))}
        nobody, tal, revs = _chair_norev_id(db, "plan"), {}, {}
        # the LINE MANAGER only (Chris, 2026-11-09: Home counts line managers): KPI step 1 and the manager; a later approver (an
        # HOD at step 2) may review the plan (_idp_is_reviewer_of) but is not counted as one of this person's line managers
        for r in db.execute("SELECT DISTINCT t.subject_id, ap.approver_id FROM pm_kpi_target_approvers ap "
                            "JOIN pm_kpi_targets t ON t.id=ap.kpi_target_id WHERE t.cycle_id=? AND ap.seq=1", (cid,)):
            if r[0] in shared and r[1] in mgr and r[1] not in out_ids and r[1] != nobody and r[1] != r[0]:
                revs.setdefault(r[0], set()).add(r[1])
        for s in shared:
            m = reviewer(s, nobody)
            for lm in (revs.get(s, set()) | ({m} if m else set())):
                _home_add(tal, lm, bg_of[s], s not in closed)
        out["idp"] = tal
    return out


def _home_hod_closed_above(db, cid, hod_ids, axes):
    """{(hod id, axis): True} for the HODs whose department review a higher lock closes (_hod_higher_lock_info's rule, batched: the
    locks are read once, each person's own BU-level keys come from the cached calibrators, no query a HOD): a BU CEO / calibrator
    locked a unit or group any of their people sit in, or the BG CEO locked it on the Talent Box (the unit, or the whole group)."""
    out = {}
    if not hod_ids:
        return out
    tb = {(r[0], r[1]) for r in db.execute("SELECT business_group, company FROM talent_box_bu_locks WHERE period_id=? OR cycle_id=?",
                                           (cid, cid))}
    # a unit whose Talent Box Round 2 is open stays closed to its HOD (_bg_closed's rule, 2026-11-15): its lock row is gone until it is locked again
    tb |= {(r[0], r[1]) for r in db.execute("SELECT business_group, company FROM tb_rounds WHERE (period_id=? OR cycle_id=?) AND "
                                            "mode IS NOT NULL AND locked_at IS NULL", (cid, cid))}
    for axis, tbl, pop, args in (("pm", "pm_calibration_sessions", pm_calibration_population_sql(), [cid]),
                                 ("pot", "calibration_sessions", calibration_population_sql(), [])):
        bu = {}
        for r in db.execute("SELECT business_group, scope_key FROM %s WHERE cycle_id=? AND tier='buceo' AND locked_at IS NOT NULL" % tbl,
                            (cid,)):
            bu.setdefault(r[1], set()).add(r[0] or "")
        whole = {r[0] for r in db.execute("SELECT scope_key FROM %s WHERE cycle_id=? AND tier='bgceo' AND locked_at IS NOT NULL" % tbl,
                                          (cid,))}
        if not (bu or tb or whole):
            continue
        ids = [h for h in hod_ids if (axes.get(h) or {}).get(axis) is not None]
        for i in range(0, len(ids), 800):
            ch = ids[i:i + 800]
            for p in db.execute("SELECT id, hod_id, business_group, company, department FROM users WHERE hod_id IN (%s) AND "
                                "role!='admin' AND %s" % (",".join("?" * len(ch)), pop), ch + args):
                h = p["hod_id"]
                if out.get((h, axis)):
                    continue
                bg, co = p["business_group"] or "", p["company"] or ""
                hit = bool(co) and any(k in bu and (bg in bu[k] or "" in bu[k]) for k in bu_scope_keys(db, p))
                if hit or (bg and ((co and (bg, co) in tb) or bg in whole)):
                    out[(h, axis)] = True
    return out


def _home_hod_work(db, u, cyc, keys):
    """({axis: {HOD id: {business group: entry}}}, {HOD id: group}) for the HODs of the lock status read (_calib_lock_scopes: holding
    the HOD role, an HOD across groups counted in one, this admin's scope). An axis counts only for an HOD it applies to
    (hod_review_axes: not None); the HOD is done on it when they locked their own session (the axis's True) or a higher lock closed
    the review (_home_hod_closed_above), the latter said as "closed above"."""
    rows = [r for r in _home_lock_rows(db, u, cyc) if r["tier"] == "hod"]
    ids = sorted({int(r["key"]) for r in rows})
    axes = hod_review_axes(db, ids)
    above = _home_hod_closed_above(db, cyc["id"], ids, axes)
    out = {k: {} for k in keys}
    for r in rows:
        h = int(r["key"])
        for k in keys:
            v = (axes.get(h) or {}).get(k)
            if v is None:
                continue
            ab = (not v) and bool(above.get((h, k)))
            out[k].setdefault(h, {})[r["bg"] or ""] = {"n": 1, "w": 0 if (v or ab) else 1, "above": ab, "names": [r["scope"]]}
    return out, {int(r["key"]): r["bg"] or "" for r in rows}


def _home_bu_work(db, u, cyc, keys):
    """({axis: {BU CEO id: {business group: entry}}}, {BU CEO id: {groups}}): one scope per unit the BU CEO seat holds (the lead of
    units calibrated together) and per calibration group a calibrator holds, as the lock status read lists them
    (_calib_lock_scopes). Done on an axis when every scope of theirs in that group is locked, or closed by the BG CEO's lock
    (_calib_lock_scopes' pm_closed / pot_closed), the latter said as "closed above"."""
    rows = [r for r in _home_lock_rows(db, u, cyc) if r["tier"] == "buceo"]
    holders, groups = buceo_holders(db), bu_groups_all(db)
    lead_of, cand = {}, set()
    for i, r in enumerate(rows):
        if r.get("group_id") is not None:
            g = groups.get(r["group_id"])
            lid = g["calibrator_id"] if g else None
        else:
            hr = holders.get((r["bg"], (r["companies"] or [""])[0]))
            lid = hr["id"] if hr is not None else None
        lead_of[i] = lid
        if lid is not None:
            cand.add(lid)
    ok = set()
    cl = sorted(cand)
    for i in range(0, len(cl), 800):
        ok |= {r[0] for r in db.execute("SELECT id FROM users WHERE left_at IS NULL AND role!='admin' AND id IN (%s)"
                                        % ",".join("?" * len(cl[i:i + 800])), cl[i:i + 800])}
    out, who = {k: {} for k in keys}, {}
    for i, r in enumerate(rows):
        lid = lead_of[i]
        if lid not in ok:
            continue
        bg = r["bg"] or ""
        who.setdefault(lid, set()).add(bg)
        for k in keys:
            lk, closed = r[k], r[k + "_closed"]
            e = out[k].setdefault(lid, {}).setdefault(bg, {"n": 0, "w": 0, "above": False, "names": []})
            e["n"] += 1
            if not (lk or closed):
                e["w"] += 1
                e["names"].append(r["scope"])
            elif closed and not lk:
                e["above"] = True
    return out, who


def _home_bg_boxes(db, u, bgs, lim):
    """{business group: tb_star_limits of its BG CEO box} for the groups in `bgs`, from ONE read over their whole population
    (Chris's capacity rule: a read over a population is one batched query). Before, each group ran _talent_box_resolve and
    talent_box_rows on its own (the same batched reads, once a group); now one population query, one query for the sessions and
    ONE talent_box_rows pass (`session_by_bg` keeps each person's adjustments to their own group's session). The refusals are the
    resolve's: a group the viewer cannot reach, with nobody in the box, or with no active cycle / period is left out, as the old
    HTTPException skip did. The figures are unchanged (test_home_bg_box_batch holds the batched result equal to the per-group
    one for every group)."""
    if not bgs or not lim["stars_on"] or "bgceo" in TB_LIMIT_EXEMPT_TIERS:
        return {}
    cycle_id, period = active_cycle_id(db), active_pm_period(db)
    if not cycle_id or not period:
        return {}
    bgs = [b for b in bgs if is_bgceo_of(u, b) or is_super(u) or (is_admin(u) and can_access_bg(u, b))]
    if not bgs:
        return {}
    ph = ",".join("?" * len(bgs))
    pop = db.execute("SELECT * FROM users WHERE business_group IN (%s) AND role!='admin' AND %s ORDER BY full_name"
                     % (ph, calibration_population_sql()), bgs).fetchall()
    by_bg = {}
    for p in pop:
        by_bg.setdefault(p["business_group"], []).append(p)
    bgs = [b for b in bgs if by_bg.get(b)]
    if not bgs:
        return {}
    ph = ",".join("?" * len(bgs))
    pm_s = {r["scope_key"]: r["id"] for r in db.execute(
        "SELECT id, scope_key FROM pm_calibration_sessions WHERE cycle_id=? AND tier='bgceo' AND scope_key IN (%s)" % ph,
        [period["id"]] + bgs)}
    pot_s = {r["scope_key"]: r["id"] for r in db.execute(
        "SELECT id, scope_key FROM calibration_sessions WHERE cycle_id=? AND tier='bgceo' AND scope_key IN (%s)" % ph,
        [cycle_id] + bgs)}
    everyone = [p for b in bgs for p in by_bg[b]]
    rows = talent_box_rows(db, {"cycle_id": cycle_id, "period": period, "population": everyone, "pm_session": None,
                                "pot_session": None, "tier": "bgceo",
                                "session_by_bg": {b: (pm_s.get(_pm_calib_scope_key("bgceo", bg=b)),
                                                      pot_s.get(_pm_calib_scope_key("bgceo", bg=b))) for b in bgs}})
    rows_of = {}
    for r in rows:
        rows_of.setdefault(r["user"]["business_group"], []).append(r)
    out = {}
    for b in bgs:
        ctx = {"cycle_id": cycle_id, "period": period, "population": by_bg[b], "scope_label": display_bg(b),
               "business_group": b, "tier": "bgceo"}
        out[b] = tb_star_limits(db, ctx, rows_of.get(b, []), "bgceo", lim)
    return out


def _home_bg_work(db, u, cyc, with_limits):
    """{business group: {"units": units in the BG CEO's box (units calibrated together once), "locked": of those locked on the Talent
    Box, "moved": people the BG CEO moved, "of": people in the group's calibration population, "over": units over a Stars limit,
    "full": units at it}}. Units and locks are the lock status read's bgceo rows (_calib_lock_scopes); the moved count is
    _bg_moved_ids over the group's calibration population (ids in chunks). Star limits only when switched on (tb_star_limits needs
    the Talent Box's own rows, one box a group: that is the cost, so it is read only on this stage and only with the limit on)."""
    cid = cyc["id"]
    out = {}
    for r in _home_lock_rows(db, u, cyc):
        if r["tier"] == "bgceo":
            e = out.setdefault(r["bg"] or "", {"units": 0, "locked": 0, "moved": 0, "of": 0, "over": 0, "full": 0})
            e["units"] += 1
            e["locked"] += 1 if r["pm"] else 0
    ubgc, ubgp = bg_scope(u, "u.business_group")
    pop = {r[0]: r[1] or "" for r in db.execute("SELECT u.id, u.business_group FROM users u WHERE u.role!='admin' AND "
                                                + calibration_population_sql("u") + ubgc, ubgp)}
    for bg in pop.values():
        if bg in out:
            out[bg]["of"] += 1
    moved = _bg_moved_ids(db, cid, cid, sorted(pop))
    for s in moved:
        if pop.get(s) in out:
            out[pop[s]]["moved"] += 1
    if with_limits:
        lim = get_tb_limits()
        for bg, st in _home_bg_boxes(db, u, sorted(out), lim).items():
            e = out[bg]
            for unit in st.values():
                states = {unit["star"]["state"], unit["super"]["state"]}
                e["over"] += 1 if "over" in states else 0
                e["full"] += 1 if ("full" in states and "over" not in states) else 0
    return out


def _home_stage_matrix(db, u, cyc, sw, on):
    """Home's table for a stage after Employees: the same shape _home_bg_matrix returns, one row per business group in this admin's
    scope, counted in the stage's own people (line managers, HODs, BU CEOs: the leader, never the report) and, for the BG CEOs,
    in units. A leader in two groups counts in each row and once in All business groups, done there when nothing anywhere waits."""
    cid = cyc["id"]
    ubgc, ubgp = bg_scope(u, "u.business_group")
    live = "u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0"
    sup = is_super(u)
    specs = _home_stage_cols(db, cid, cyc, on)
    keys = [c[0] for c in specs]
    people = {(r[0] or ""): r[1] for r in db.execute("SELECT u.business_group, COUNT(*) FROM users u WHERE " + live + ubgc
                                                     + " GROUP BY u.business_group", ubgp)}
    work, who, bgw = {}, {}, {}
    if on == "lm":
        work = _home_lm_work(db, u, cyc, keys)
        for tal in work.values():
            for lid, byb in tal.items():
                who.setdefault(lid, set()).update(byb)
    elif on == "hod":
        work, hod_bg = _home_hod_work(db, u, cyc, keys)
        who = {h: {b} for h, b in hod_bg.items()}
    elif on == "bu":
        work, who = _home_bu_work(db, u, cyc, keys)
    else:
        bgw = _home_bg_work(db, u, cyc, get_tb_limits()["stars_on"])
    cols = []
    for key, label, _mod, cell in specs:
        st = window_state(db, cell, cid)
        opens = window_dates(db, cell, cid)[0] if st == "not_open" else None
        cols.append({"key": key, "label": label, "word": HOME_STAGE_WORDS[on], "state": st, "cell": cell,
                     "opens": _st_day(opens) if opens else None,
                     "color": ADMIN_SECTION_BY_KEY.get(_HOME_STAGE_COLOR.get(key, key), {}).get("color"),
                     "url": None})
    bgs_all = set(people) | set(bgw) | {b for tal in work.values() for byb in tal.values() for b in byb}
    bgs = sorted(b for b in bgs_all if b and can_access_bg(u, b))
    real = set(org_bgs(db, active_only=False)) | {bg for bg, n in people.items() if n}
    bgset = set(bgs)

    def tally(tal):
        """({bg: [n, done, closed above]}, [n, done, closed above]) of {leader: {bg: entry}}, over the groups in scope."""
        per, t = {}, [0, 0, 0]
        for byb in tal.values():
            byb = {b: e for b, e in byb.items() if b in bgset}
            if not byb:
                continue
            for b, e in byb.items():
                p = per.setdefault(b, [0, 0, 0])
                p[0] += 1
                if not e["w"]:
                    p[1] += 1
                    p[2] += 1 if e.get("above") else 0
            t[0] += 1
            if not sum(e["w"] for e in byb.values()):
                t[1] += 1
                t[2] += 1 if any(e.get("above") for e in byb.values()) else 0
        return per, t

    def links(key, bg):
        """(page url, list panel url, list page url) of one cell. The super admin's cell opens its people in the list panel
        (as Home's always has) with the page behind it; every other admin's goes to the closest page: Progress at the stage
        that waits on the line manager (Performance, Competency, Career Plan), the lock status page's open rows (HODs, BU CEOs),
        the group's Talent Box (BG CEOs)."""
        fb = {"fbg": bg} if sup and bg else {}
        if on == "lm":
            k, fst = _HOME_LM_PROGRESS[key]
            page = url_for("admin_module_progress", key=k, fstage=fst, **fb)
        elif on in ("hod", "bu"):
            page = url_for("admin_calibration_locks", show="open", **fb)
        else:
            return url_for("admin_talent_box", **({"bg": bg} if bg else {})), None, None
        if not sup:
            return (page if bg else None), None, None
        kw = dict(key="home-cell", col=key, stage=on, **({"bg": bg} if bg else {}))
        return (page if bg else None), url_for("admin_list_view", fragment=1, **kw), url_for("admin_list_view", **kw)

    def cell_of(c, n, done, above, bg):
        if c["state"] == "not_open":
            return {"pct": None, "sub": "opens %s" % c["opens"] if c["opens"] else "not open yet", "url": None}
        if not n:
            return {"pct": None, "sub": "none set", "url": None}
        pct = int(done * 100 / n)    # floored: 99.6% is not done
        url, lst, page = links(c["key"], bg or "")
        return {"pct": pct, "sub": "%s of %s %s%s" % ("{:,}".format(done), "{:,}".format(n), c["word"],
                                                     " · %d closed above" % above if above else ""),
                "url": url, "list": lst, "list_page": page}
    data = {}
    if on != "bg":
        for c in cols:
            data[c["key"]] = tally(work[c["key"]])
    per_who = {}
    for lid, bgs_of in who.items():
        for b in bgs_of & bgset:
            per_who[b] = per_who.get(b, 0) + 1
    n_who = sum(1 for bgs_of in who.values() if bgs_of & bgset)
    stars = on == "bg" and get_tb_limits()["stars_on"]
    rows = []
    for bg in bgs:
        if bg not in real:
            continue
        if on == "bg":
            e = bgw.get(bg, {"units": 0, "locked": 0, "moved": 0, "of": 0, "over": 0, "full": 0})
            cells = [cell_of(cols[0], e["units"], e["locked"], 0, bg)]
            extra = ([{"kind": "limits", "over": e["over"], "full": e["full"]}] if stars else []) + [
                {"kind": "moved", "n": e["moved"], "of": e["of"], "url": url_for("admin_talent_box", bg=bg)}]
            rows.append({"bg": bg, "people": e["units"], "taking_part": None, "cells": cells, "extra": extra})
        else:
            rows.append({"bg": bg, "people": per_who.get(bg, 0), "taking_part": None,
                         "cells": [cell_of(c, *data[c["key"]][0].get(bg, [0, 0, 0]), bg) for c in cols], "extra": []})
    if on == "bg":
        tn = sum(e["units"] for b, e in bgw.items() if b in bgset)
        tl = sum(e["locked"] for b, e in bgw.items() if b in bgset)
        tot_extra = ([{"kind": "limits", "over": sum(e["over"] for b, e in bgw.items() if b in bgset),
                       "full": sum(e["full"] for b, e in bgw.items() if b in bgset), "short": True}] if stars else []) + [
            {"kind": "moved", "n": sum(e["moved"] for b, e in bgw.items() if b in bgset),
             "of": sum(e["of"] for b, e in bgw.items() if b in bgset)}]
        tot = {"people": tn, "taking_part": None, "cells": [cell_of(cols[0], tn, tl, 0, None)], "extra": tot_extra}
    else:
        tot = {"people": n_who, "taking_part": None, "cells": [cell_of(c, *data[c["key"]][1], None) for c in cols],
               "extra": []}
    notes = _home_matrix_notes(db, cid, cols, rows, tot)
    if on == "lm":
        pm_i = next((i for i, c in enumerate(cols) if c["key"] == "pm"), None)
        if pm_i is not None and cols[pm_i]["state"] == "open":
            n_, d_ = data["pm"][1][0], data["pm"][1][1]
            if n_ - d_:
                notes.append("%s line manager%s still %s a KPI result waiting on them." % (
                    "{:,}".format(n_ - d_), "" if n_ - d_ == 1 else "s", "has" if n_ - d_ == 1 else "have"))
    if on == "bg":
        for r in rows:
            for x in r["extra"]:
                if x["kind"] == "limits" and x["over"]:
                    notes.append("%s has %d unit%s over its Stars limit: %s can't lock until a move is undone." % (
                        display_bg(r["bg"]), x["over"], "" if x["over"] == 1 else "s", "it" if x["over"] == 1 else "they"))
    for s in sw["stages"]:   # an earlier stage still open is one click away
        if s["key"] != on and s["state"] == "open" and [x["key"] for x in sw["stages"]].index(s["key"]) < [
                x["key"] for x in sw["stages"]].index(on) and s["c"]:
            notes.append("%s' stage is still open until %s." % (s["label"], s["c"].strftime("%-d %b")))
    if on == "lm" and cycle_module_on("pm", db, cid):
        notes += _home_chainless_note(db, u, cid)
    return {"cols": cols, "rows": rows, "total": tot, "notes": notes, "gone_note": "", "stage": _home_stage_bar(sw, on),
            "who": HOME_STAGE_WHO[on],
            "extra_cols": ([{"label": "Star limits"}] if stars else []) + [{"label": "People moved"}] if on == "bg" else []}


def _home_chainless_note(db, u, cid):
    """['N KPI lines have no approver.'] or []: the Employees and Line managers views' note (the chair's reports have none by design)."""
    tbgc, tbgp = bg_scope(u, "t.business_group")
    n = db.execute("SELECT COUNT(*) FROM pm_kpi_targets t JOIN users su ON su.id=t.subject_id WHERE t.cycle_id=? "
                   "AND NOT EXISTS (SELECT 1 FROM pm_kpi_target_approvers a WHERE a.kpi_target_id=t.id)"
                   + _pm_chair_unmod_sql(db, "su") + tbgc, (cid,) + tuple(tbgp)).fetchone()[0]
    return ["%s KPI line%s no approver." % ("{:,}".format(n), " has" if n == 1 else "s have")] if n else []


def _home_matrix_notes(db, cid, cols, rows, tot):
    """What stands out, in words: the business group furthest behind, the slowest open part, who is done on every open part."""
    notes = []
    open_ix = [i for i, c in enumerate(cols) if c["state"] == "open"]
    scored = [(r, [r["cells"][i] for i in open_ix if r["cells"][i]["pct"] is not None]) for r in rows]
    scored = [(r, cs) for r, cs in scored if cs]
    if len(scored) > 1:
        r, cs = min(scored, key=lambda x: sum(c["pct"] for c in x[1]) / len(x[1]))
        low = sorted(((r["cells"][i]["pct"], cols[i]["label"]) for i in open_ix if r["cells"][i]["pct"] is not None))
        notes.append("%s is furthest behind: %s." % (display_bg(r["bg"]), ", ".join(
            "%s %d%%" % (lab, p) for p, lab in low[:2])))
    opn = [(tot["cells"][i]["pct"], cols[i]) for i in open_ix if tot["cells"][i]["pct"] is not None]
    if opn:
        p, c = min(opn, key=lambda x: x[0])
        if p < 100:
            due = _parse_when(window_dates(db, c["cell"], cid)[1])
            left = (due - _now_myt()).days if due else None
            notes.append("%s is the slowest open part: %d%% %s%s." % (
                c["label"], p, c["word"], (", %d day%s to its close" % (left, "" if left == 1 else "s"))
                if left is not None and left >= 0 else ""))
    done_all = [display_bg(r["bg"]) for r, cs in scored if all(c["pct"] == 100 for c in cs)]
    if done_all and len(rows) > 1:
        notes.append("%s %s done on every open part." % (", ".join(done_all), "is" if len(done_all) == 1 else "are"))
    return notes



PRECAL_DUE_DAYS = 7   # the card turns red this many days (or fewer) before performance calibration opens


def _precal_alert(db, me):
    """Home's before-calibration card for the super admin (Chris, 2026-10-29): counts down to the BU CEOs' performance
    calibration and lists, per business group, the BU KPI results and the units' PAT still missing, both of which it
    needs. None when there is nothing to show: not the super admin, no active cycle, an Early Year, Performance off,
    calibration closed, or everything in once it has opened. Reads only: grouped queries, never one per unit or person.
    Units are those with someone taking part (participant_sql, which already leaves out the cycle's left-out units);
    a BU KPI is filled only when EVERY line carrying it has a final admin-filled result (what Fill BU KPI writes)."""
    if not is_super(me):
        return None
    per = active_pm_period(db)
    if not per:
        return None
    cid = per["id"]
    half = _row_get(per, "half")
    if half is not None and int(half) == 0:   # 0 is the Early Year (and falsy): compare, never test
        return None
    if not cycle_module_on("pm", db, cid):
        return None
    opens_raw, closes_raw = window_dates(db, "pm_buceo", cid)
    opens, closes = _parse_when(opens_raw), _parse_when(closes_raw)
    now = _now_myt()
    if closes and now >= closes:
        return None
    units = {(r[0], r[1]) for r in db.execute(
        "SELECT DISTINCT u.business_group, u.company FROM users u WHERE u.role!='admin' AND COALESCE(u.is_demo,0)=0 "
        "AND COALESCE(u.business_group,'')!='' AND COALESCE(u.company,'')!='' AND " + participant_sql("u"))}
    if not units:
        return None
    pat_in = {(r[0], r[1]) for r in db.execute(
        "SELECT business_group, company FROM pm_pbt_achievement WHERE cycle_id=? AND COALESCE(company,'')!='' "
        "AND achievement_pct IS NOT NULL", (cid,))} & units
    kpis = {}   # (bg, company) -> [(kpi name, all its lines are filled)]
    for r in db.execute(
            "SELECT k.business_group, k.company, k.kpi_name, COUNT(t.id), SUM(CASE WHEN f.kpi_target_id IS NOT NULL "
            "THEN 1 ELSE 0 END) FROM pm_bu_kpis k JOIN pm_kpi_targets t ON t.bu_kpi_id=k.id AND t.cycle_id=k.cycle_id "
            "LEFT JOIN (SELECT DISTINCT kpi_target_id FROM pm_kpi_results WHERE admin_filled=1 AND "
            "COALESCE(draft,0)=0) f ON f.kpi_target_id=t.id WHERE k.cycle_id=? GROUP BY k.id", (cid,)):
        if (r[0], r[1]) in units:
            kpis.setdefault((r[0], r[1]), []).append((r[2] or "", r[3] == r[4]))
    rows = []
    for bg in sorted({b for b, _c in units}, key=lambda b: display_bg(b).lower()):
        cos = sorted((c for b, c in units if b == bg), key=lambda c: display_company(bg, c).lower())
        bu_all = [(c, n, ok) for c in cos for n, ok in sorted(kpis.get((bg, c), []), key=lambda x: x[0].lower())]
        bu_todo = ["%s · %s" % (display_company(bg, c), n) for c, n, ok in bu_all if not ok]
        pat_todo = [display_company(bg, c) for c in cos if (bg, c) not in pat_in]
        rows.append({"name": display_bg(bg), "bg": bg,
                     "bu_n": len(bu_all), "bu_done": sum(1 for x in bu_all if x[2]), "bu_todo": ", ".join(bu_todo),
                     "pat_n": len(cos), "pat_done": len(cos) - len(pat_todo), "pat_todo": ", ".join(pat_todo)})
    bu_n, bu_done = sum(r["bu_n"] for r in rows), sum(r["bu_done"] for r in rows)
    pat_n, pat_done = sum(r["pat_n"] for r in rows), sum(r["pat_done"] for r in rows)
    missing = bu_done < bu_n or pat_done < pat_n
    no_bu = sum(1 for k in units if k not in kpis)
    out = {"rows": rows, "cycle": per["name"], "no_bu": no_bu, "missing": missing, "ready": False, "due": False,
           "chip": "Needs you", "chip_cls": "jn-wait", "lead": "", "when": "", "when_link": False,
           "opens_text": opens.strftime("%-d %b %Y, %H:%M") if opens else "",
           "bu_head": "%d of %d filled" % (bu_done, bu_n) if bu_n else "none set up",
           "pat_head": "%d of %d unit%s entered" % (pat_done, pat_n, "" if pat_n == 1 else "s")}
    lead = "Two things must be in before the BU CEOs and calibrators can calibrate performance."
    if opens and opens <= now:   # calibration has opened: red while anything is missing, then gone
        if not missing:
            return None
        out.update(due=True, chip="Calibration is open", chip_cls="pc-due", lead=(
            "Calibration is open, and these are still missing. The BU CEOs of these units are calibrating against the "
            "Normal curve, and their people's BU KPI lines have no result."),
            when="Performance calibration opened %s%s" % (out["opens_text"], (" · closes " + closes.strftime("%-d %b"))
                                                          if closes else ""))
        return out
    if not missing:
        out.update(ready=True, lead="Every BU KPI result and every unit's PAT is in.")
        return out
    out["lead"] = lead
    if not opens:
        out.update(when="Performance calibration has no opening date yet · ", when_link=True)
        return out
    days = (opens.date() - now.date()).days
    if days > PRECAL_DUE_DAYS:
        out["when"] = "Performance calibration opens %s · in %d day%s" % (out["opens_text"], days, "" if days == 1 else "s")
    else:
        out.update(due=True, chip_cls="pc-due", chip="Due today" if days <= 0 else "Due in %d day%s" % (
            days, "" if days == 1 else "s"), when="Performance calibration opens " + out["opens_text"])
    return out


# Home's Grade H Appraisal card (Chris, 2026-11-06, canvas [design canvas link removed] boards H1-H3, "ok proceed").
# The words for "who is working on it now", by the Grade H calendar cell: "<words> until <d Mon>".
_GH_HOME_OPEN_WORDS = {"gradeh_kpi": "employees send KPI achievement", "gradeh_lm": "line managers appraise",
                       "gradeh_ack": "employees acknowledge", "gradeh_hod_pot": "HODs review", "gradeh_hod_perf": "HODs review",
                       "gradeh_buceo": "BU CEOs sign off"}
# the card's stages in the drawn order (key, label, the _gh_adm_pick key behind its number); Acknowledged is its own column, not a stage
_GH_HOME_PICK = {"all": "all", "not_started": "hs:not_started", "lm": "hs:lm", "ack": "ack_sub", "cal": "hs:cal", "signed": "hs:signed",
                 "released": "hs:released"}


def _home_gradeh(db, u):
    """Home's Grade H Appraisal card, or None. Shown only while Grade H is on and offered on the active cycle, to the super admin and to a
    BG or unit admin whose role has gradeh.read (the gate of Reports > Grade H > Where it is, _hr_allowed), never the L&D admin, and only
    with someone in scope. Its people are the report's: gradeh_admin_people (already batched) through _gh_scope_people, so a count here is
    the report's and People & progress's. One row a business group (a BG or unit admin: a business unit of their group), the stages the
    report's columns group (_gh_home_stage), Acknowledged = of those whose line manager submitted (_gh_ack_sub). Reads only."""
    if not gradeh_on() or is_lnd_admin(u) or not (is_super(u) or admin_can(u, "gradeh", "read")):
        return None
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc):
        return None
    people = _gh_scope_people(gradeh_admin_people(db, cyc["id"]), u)
    if not people:
        return None
    sup = is_super(u)
    own_bg = admin_bg_of(u)
    by_unit = bool(own_bg)
    now = _now_myt()
    # the part that is open: each Grade H cell's state once; the one closing soonest is named
    opens, open_now, states = [], [], set()
    for c in GRADEH_CELL_KEYS:
        st = window_state(db, c, cyc["id"], now)
        states.add(st)
        o, cl = (_parse_when(x) for x in window_dates(db, c, cyc["id"]))
        if o:
            opens.append(o)
        if st == "open":
            open_now.append((cl, c))
    dated = sorted((cl, c) for cl, c in open_now if cl)
    open_part = ("%s until %s" % (_GH_HOME_OPEN_WORDS[dated[0][1]], dated[0][0].strftime("%-d %b"))) if dated else ""
    out = {"cycle": cyc["name"], "sup": sup, "by_unit": by_unit, "any_open": bool(open_now), "open_part": open_part,
           "report_url": url_for("admin_report_view", key="gh-where"), "note": "", "state": "table"}
    # one row per group (or per unit of the viewer's group), in one pass over the people already read
    ident = (lambda p: p["company"]) if by_unit else (lambda p: p["bg"])
    groups = {}
    for p in people:
        groups.setdefault(ident(p), []).append(p)

    def label(k):
        if by_unit:
            return (display_company(own_bg, k) or k) if k else "(no unit on file)"
        return display_bg(k) if k else "(none on file)"

    def counts(ps):
        n = len(ps)
        c = {st: sum(1 for p in ps if _gh_home_stage(p) == st) for st in _GH_HOME_STAGES}
        sub = sum(1 for p in ps if p["submitted"])
        c.update(n=n, ack=sum(1 for p in ps if _gh_ack_sub(p)), ack_of=sub)
        bar = [(st, c[st], round(100.0 * c[st] / n, 3) if n else 0) for st in _GH_HOME_STAGES]
        c["bar"] = bar
        c["bar_title"] = "Not started %d \u00b7 With LM %d \u00b7 In calibration %d \u00b7 Signed off %d \u00b7 Released %d" % (
            c["not_started"], c["lm"], c["cal"], c["signed"], c["released"])
        return c

    def links(c, bg, co):
        """A number's addresses: the super admin's list panel (and that list's full page), else People & progress with that Show choice.
        A zero is not a link."""
        res = {}
        for k, pick in _GH_HOME_PICK.items():
            if not c["n" if k == "all" else k]:
                res[k] = None
                continue
            if sup:
                kw = dict(f=pick, **({"bg": bg} if bg else {}), **({"unit": co} if co else {}))
                res[k] = {"list": url_for("admin_list_view", key="gh", fragment=1, **kw),
                          "href": url_for("admin_list_view", key="gh", **kw)}
            else:
                res[k] = {"list": None, "href": url_for("admin_gradeh", tab="people", **({"show": pick} if k != "all" else {}),
                                                       **({"bg": bg} if bg else {}), **({"bu": co} if co else {}))}
        return res
    rows = []
    for k in sorted(groups, key=lambda x: (not x, label(x).lower())):
        c = counts(groups[k])
        bg_, co_ = (own_bg, k) if by_unit else (k, "")
        rows.append(dict(c, label=label(k), links=links(c, bg_ or "", co_ or "")))
    tot = dict(counts(people), label=("All of " + display_bg(own_bg)) if by_unit else "All business groups")
    tot["links"] = links(tot, "", "")
    out.update(rows=rows, total=tot if len(rows) > 1 else None, n=tot["n"], n_groups=len(rows))
    # before Grade H opens: every part not open yet, so the card is one line (the earliest opening, if any is dated)
    if states == {"not_open"}:
        out.update(state="before", opens_text=(min(opens).strftime("%a %-d %b, %H:%M")) if opens else "")
        return out
    # What stands out: one line when anyone has not started
    if tot["not_started"]:
        worst = max(rows, key=lambda r: r["not_started"]) if len(rows) > 1 else None
        note = "Grade H: %s of %s not started" % ("{:,}".format(tot["not_started"]), "{:,}".format(tot["n"]))
        if worst:
            note += "; %s has the most, %s of %s" % (worst["label"], "{:,}".format(worst["not_started"]), "{:,}".format(worst["n"]))
        note += "."
        if open_part:
            note += " " + open_part[0].upper() + open_part[1:] + "."
        out["note"] = note
    return out


@app.route("/admin")
@admin_required
def admin_overview():
    """The admin landing page (Home): each business group, each live module's progress (_home_bg_matrix), what needs
    you across the modules, and what stands out.

    This replaced the 360 Cycle Dashboard as /admin. That dashboard was never
    wrong -- it was just one module's, sitting where the whole product's front
    door should be, which is why the app read as a 360 tool with extras. Every
    landing that sent an admin to the 360 now comes here (2026-10-10).

    Deliberately cheap: grouped COUNTs, no scoring, no per-subject loops. An
    overview that costs a page-load of work is one people route around.
    Every count is scoped to the admin's own BG (and a sub-admin's companies).
    """
    db = get_db()
    u = current_user()
    cyc = viewed_cycle(db)
    matrix = _home_bg_matrix(db, u, cyc, stage=request.args.get("stage"))   # ?stage= picks a stage for this visit (2026-11-09)
    ready_groups, ready_done, ready_total = _admin_readiness(db, u)
    # What needs you: every step not done yet, across the modules, in the readiness order (the canvas's Needs you)
    needs = []
    for gr in ready_groups:
        sec = ADMIN_SECTION_BY_KEY.get(_READY_SECTION.get(gr["label"], ""), {})
        for st in gr["steps"]:
            if st["state"] not in ("done", "waiting"):   # a step waiting on others is not the admin's to-do
                needs.append({**st, "module": sec.get("label", gr["label"]), "color": sec.get("color")})
    mods, people = admin_nav(u)
    return render_template("admin_overview.html", matrix=matrix, cycle=cyc, nav_modules=mods, needs=needs,
                           joiners=_joiner_flag(db, u),
                           precal=_precal_alert(db, u),
                           gh_home=_home_gradeh(db, u),   # the Grade H Appraisal card (2026-11-06), or None
                           wn_popout=wn_popout(db),   # What's new's pop-out (2026-11-03): this account's unseen notes, or None
                           ready_groups=ready_groups, ready_done=ready_done,
                           ready_total=ready_total,
                           nav_people=people, admin_bg=admin_bg_of(u), active_view="overview",
                           # Only ever non-empty when the app was booted with
                           # L360_ALLOW_SCHEMA_FAILURE=1 over a failed
                           # migration -- otherwise it would not be running.
                           # Shown so that state cannot be mistaken for normal.
                           schema_error=(SCHEMA_ERROR if is_super(u) else None))

@app.route("/admin/360")
@admin_required
def admin_dashboard():
    db = get_db()
    u = current_user()
    bg = admin_bg_of(u)
    # Scope to the admin's BG (and, for a sub-admin, to its companies). The
    # company dimension is carried by bg_scope automatically.
    sc, scp = bg_scope(u)                    # " AND business_group=? [AND company IN ...]"
    if sc:
        sbg = " AND subject_id IN (SELECT id FROM users WHERE 1=1" + sc + ")"
        sp = list(scp)
    else:
        sbg, sp = "", []
    pclause, pp = bg_scope(u)
    vc = viewed_cycle_id(db)   # dashboard reflects the cycle the admin is viewing

    # The demo briefing account ([[demo-briefing-account]]) is a fake subject +
    # panel for rehearsals — keep it out of every live-cycle stat below so the
    # dashboard reflects the real population only. Subjects are filtered by
    # is_demo=0; assignment counts inherit that via the subject sub-select.
    demo_x = " AND subject_id IN (SELECT id FROM users WHERE is_demo=0)"
    # 2026-10-31, "out means out" for admin progress counts: rows for colleagues not taking part in the 360 are not counted
    # here (the panel tools and the person page still list them); a row of another cycle always passes
    out_x = " AND " + rater_task_sql("assignments")

    people = db.execute(
        "SELECT COUNT(*) FROM users WHERE role!='admin' AND is_demo=0 AND left_at IS NULL"
        + pclause, pp).fetchone()[0]
    subjects = db.execute(
        "SELECT COUNT(DISTINCT subject_id) FROM assignments WHERE archived=0 AND cycle_id=?"
        + demo_x + out_x + sbg, [vc] + sp).fetchone()[0]
    assignments_total = db.execute(
        "SELECT COUNT(*) FROM assignments WHERE archived=0 AND cycle_id=?" + demo_x + out_x + sbg,
        [vc] + sp).fetchone()[0]
    assignments_done = db.execute(
        "SELECT COUNT(*) FROM assignments WHERE status='submitted' AND archived=0 AND cycle_id=?"
        + demo_x + out_x + sbg, [vc] + sp).fetchone()[0]

    # Submission progress, two-stage. Stage 2 = all assessors submitted;
    # Stage 1 = the score is "valid" (>= MIN_VALID_SUBMISSIONS submitted) but
    # not yet all in. Letter grades (JG H, panel of 1) skip the 4-threshold:
    # they're simply complete at 1/1 or not started at 0/1.
    bgsub, bsp = bg_scope(u, "u.business_group")
    brow = db.execute(
        """SELECT
             SUM(CASE WHEN sub >= tot THEN 1 ELSE 0 END) AS complete,
             SUM(CASE WHEN is_letter=0 AND sub >= ? AND sub < tot THEN 1 ELSE 0 END) AS stage1,
             SUM(CASE WHEN sub > 0 AND sub < tot
                           AND NOT (is_letter=0 AND sub >= ?) THEN 1 ELSE 0 END) AS in_progress,
             SUM(CASE WHEN sub = 0 THEN 1 ELSE 0 END) AS not_started
           FROM (
             SELECT a.subject_id,
                    COUNT(*) AS tot,
                    SUM(CASE WHEN a.status='submitted' THEN 1 ELSE 0 END) AS sub,
                    CASE WHEN typeof(u.job_grade)='text' THEN 1 ELSE 0 END AS is_letter
             FROM assignments a JOIN users u ON u.id=a.subject_id
             WHERE a.archived=0 AND a.cycle_id=? AND u.is_demo=0 AND """ + rater_task_sql("a") + bgsub + """
             GROUP BY a.subject_id
           )""",
        [min_valid(), min_valid(), vc] + bsp).fetchone()
    complete = brow["complete"] or 0
    stage1 = brow["stage1"] or 0
    in_progress = brow["in_progress"] or 0
    not_started = brow["not_started"] or 0

    # Confirmed people who don't yet have a full panel for THEIR grade. Numeric
    # grades target PANEL_TARGET (5); letter grades (e.g. JG 'H') target 1
    # (only their line manager). SQLite's INTEGER affinity stores '15' as the
    # integer 15 but leaves 'H' as text, so typeof() reliably distinguishes them.
    isc, isp = bg_scope(u, "u.business_group")
    _ssql, _sp = _f360_short_sql(vc)
    incomplete = db.execute("SELECT COUNT(*) FROM users u WHERE u.role='user' AND u.is_demo=0" + isc + _ssql,
                            isp + _sp).fetchone()[0]

    # 360 Feedback > Overview rebuilt on the kit (the review, 2026-10-10, canvas K5): the potential bands moved to
    # Results analysis (they cost one score per person here); this page says where the ratings stand and where they're
    # outstanding, by department.
    rsc, rsp = bg_scope(u, "u.business_group")
    released = db.execute("SELECT COUNT(*) FROM report_releases r JOIN users u ON u.id=r.subject_id WHERE r.cycle_id=?"
                          + rsc, [vc] + rsp).fetchone()[0]
    dept_rows = [dict(r) for r in db.execute(
        "SELECT u.business_group AS bg, u.company AS bu, TRIM(COALESCE(u.department,'')) AS dept, "
        "COUNT(DISTINCT a.subject_id) AS people, COUNT(*) AS asked, "
        "SUM(CASE WHEN a.status='submitted' THEN 1 ELSE 0 END) AS done "
        "FROM assignments a JOIN users u ON u.id=a.subject_id WHERE a.archived=0 AND a.cycle_id=? AND u.is_demo=0 AND "
        + rater_task_sql("a") + rsc + " GROUP BY u.business_group, u.company, TRIM(COALESCE(u.department,'')) "
        "HAVING SUM(CASE WHEN a.status='submitted' THEN 0 ELSE 1 END) > 0 "
        "ORDER BY SUM(CASE WHEN a.status='submitted' THEN 0 ELSE 1 END) DESC LIMIT 15", [vc] + rsp)]
    for d in dept_rows:
        d["pct"] = int(d["done"] * 100 / d["asked"]) if d["asked"] else 0
        d["href"] = url_for("admin_subjects", **{k: v for k, v in (("fbg", d["bg"] if is_super(u) else None),
                                                                    ("fcompany", d["bu"]), ("fdept", d["dept"])) if v})
    return render_template(
        "admin_dashboard.html", needs=_section_needs(db, u, "f360"),
        people=people, subjects=subjects,
        assignments_total=assignments_total, assignments_done=assignments_done,
        complete=complete, stage1=stage1, in_progress=in_progress, not_started=not_started,
        panel_target=panel_target(), incomplete=incomplete, released=released, dept_rows=dept_rows,
        min_valid=min_valid(), admin_bg=bg,
    )


def _f360_short_sql(vc):
    """The 360's "short of a full panel": confirmed, at or above the cycle's minimum grade, with fewer active raters
    than the target (a letter grade: 1). One clause the Overview's tile, its list and 360 People's filter share, so the
    number and the people behind it can't disagree. Users aliased `u`; (sql starting " AND ", params)."""
    # who is rated: their user role says so (Roles & access, 2026-10-20), as the panel build reads it
    return (" AND " + participant_sql("u", "tm_rated") + " AND " + no360_sql("u") + " AND "
            + cycle_scope_sql("u") + " AND (SELECT COUNT(*) FROM assignments a WHERE a.subject_id=u.id AND a.archived=0 "
            "AND a.cycle_id=?) < CASE WHEN typeof(u.job_grade)='text' THEN 1 ELSE ? END", [vc, panel_short_n()])


# ---------------------------------------------------------------------------
# An admin count opens its people in the right panel (Chris, 2026-10-20: "clicking on these box should open up view of
# the list with filtered users inside ... admin can straight away amend and add the panel members in the panel in one
# page view"; canvas [design canvas link removed]). A tile carries data-list-open="<this route,
# ?fragment=1>"; admin.js loads the list into the page's one "list" panel, a person opens in the same panel with Back.
# Each list is built by the same query as its count. ADMIN_LISTS: key -> {"module": the access module, "build": fn}.
# ---------------------------------------------------------------------------
ADMIN_LISTS = {}
LIST_ROWS_SHOWN = 500   # a panel's list; 2,500 rows took ~4s to lay out at 1280 (2026-10-20 QC)


def admin_list(key, module, all_admins=False):
    """all_admins: an admin whose role reads the module may open it, the builder scoping them to their own units (Chris,
    2026-10-27, Leaders > BU CEOs: "all admins can view"). Every other list is the super admin's."""
    def deco(fn):
        ADMIN_LISTS[key] = {"module": module, "build": fn, "all_admins": all_admins}
        return fn
    return deco


def _list_row(r, tab, cells, tone=""):
    """One person in a list: their identity from a users row, the cells after it as (text, tone) pairs."""
    return {"uid": r["id"], "name": r["full_name"], "eid": r["employee_id"] or "",
            "bu": display_company(r["business_group"], r["company"]) or (r["company"] or ""),
            "dept": r["department"] or "", "jg": r["job_grade"] if r["job_grade"] is not None else "",
            "href": url_for("admin_person", uid=r["id"], tab=tab), "cells": cells, "tone": tone}


def _panel_engine_state(db, cyc):
    """The roster and the cycle's 360 rows the way the capped engine reads them, in two queries: (people, id_of
    {employee ID: users.id}, load {assessor employee ID: active rows}, existing {subject: {assessor: relationship}},
    barred {subject: every assessor ever on their panel, archived rows included})."""
    people = _bpdb.load_people(db, _row_get(cyc, "min_job_grade"))
    for e in _urole_no_rate(db):   # their user role doesn't let them rate colleagues (Roles & access)
        people.pop(e, None)
    for e in _unit_out_eids(db, cyc["id"] if cyc else None):   # a unit or department the cycle leaves out
        people.pop(e, None)
    eid_of, id_of = {}, {}
    for r in db.execute("SELECT id, employee_id FROM users WHERE employee_id IS NOT NULL"):
        k = str(r[1]).strip()
        eid_of[r[0]], id_of[k] = k, r[0]
    load, existing, barred = Counter(), {}, {}
    for r in db.execute("SELECT subject_id, assessor_id, relationship, archived FROM assignments WHERE cycle_id=?",
                        (cyc["id"],)):
        se, ae = eid_of.get(r[0]), eid_of.get(r[1])
        if not se or not ae:
            continue
        barred.setdefault(se, set()).add(ae)
        if not r[3]:
            load[ae] += 1
            existing.setdefault(se, {})[ae] = r[2]
    return people, id_of, load, existing, barred


def _f360_rated_sql():
    """The people-being-rated select (users u, with n raters and d answered), shared by the rated, stage and
    ready-unreleased lists. A function, not an import-time constant: the predicate reads participant_sql, which needs the
    module's tables and constants loaded. 2026-10-31, "out means out" for admin progress counts: only live rows of
    colleagues taking part in the 360 (rater_task_sql); a row of another cycle always passes."""
    return ("SELECT u.*, x.n, x.d FROM users u JOIN (SELECT subject_id, COUNT(*) n, "
            "SUM(CASE WHEN status='submitted' THEN 1 ELSE 0 END) d FROM assignments WHERE archived=0 "
            "AND cycle_id=? AND " + rater_task_sql("assignments") + " GROUP BY subject_id) x ON x.subject_id=u.id "
            "WHERE u.is_demo=0")


@admin_list("f360-rated", "f360")
def _list_f360_rated(db, me, vc, args):
    sc, sp = bg_scope(me, "u.business_group")
    rows = db.execute(_f360_rated_sql() + sc + " ORDER BY u.full_name", [vc] + list(sp)).fetchall()
    return {"kicker": "360 Feedback", "title": "People being rated · %s" % format(len(rows), ","),
            "sub": "Everyone with a panel this cycle, and how many of their raters have answered.",
            "full": url_for("admin_subjects"), "cols": ["Raters", "Answered"],
            "rows": [_list_row(r, "f360", [(str(r["n"]), ""), ("%d of %d" % (r["d"] or 0, r["n"]), "")]) for r in rows]}


@admin_list("f360-short", "f360")
def _list_f360_short(db, me, vc, args):
    sc, sp = bg_scope(me, "u.business_group")
    ssql, ssp = _f360_short_sql(vc)
    rows = db.execute("SELECT u.*, (SELECT COUNT(*) FROM assignments a WHERE a.subject_id=u.id AND a.archived=0 "
                      "AND a.cycle_id=?) AS n FROM users u WHERE u.role='user' AND u.is_demo=0" + sc + ssql
                      + " ORDER BY n, u.full_name", [vc] + list(sp) + ssp).fetchall()
    target = panel_short_n()
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (vc,)).fetchone()
    mv = min(effective_min_valid(cyc), target) if cyc else 1
    why = {}
    if cyc and cyc["is_active"] and rows:   # why each is short, from the build's own engine (one run for all of them)
        cap = effective_assessor_cap(cyc)
        people, _id_of, _l, existing, barred = _panel_engine_state(db, cyc)
        eids = [str(r["employee_id"]).strip() for r in rows if r["employee_id"]]
        pans = _ba.build_panels_capped(people, eids, target, mv, cap=cap, existing=existing, barred=barred,
                                       prior=_bpdb.load_prior(db, cyc))
        why = {e: _ba.note_capped(p, target, mv, cap=cap) for e, p in pans.items()}
    low = sum(1 for r in rows if r["n"] < mv)
    out = []
    for r in rows:
        t = 1 if isinstance(r["job_grade"], str) else target
        w = why.get(str(r["employee_id"] or "").strip(), "")
        out.append(_list_row(r, "f360", [("%d of %d" % (r["n"], t), "low" if r["n"] < mv else "mid"),
                                         ((w[:1].upper() + w[1:]) if w else "", "")]))
    return {"kicker": "360 Feedback", "title": "%s · %s" % ("Short of a full panel" if panel_target()
                                                             else "Below the scoring minimum", format(len(rows), ",")),
            "sub": "Fewer than %d raters.%s" % (target, (" %d can't be scored yet: fewer than %d." % (low, mv))
                                                if low else ""),
            "full": url_for("admin_subjects", scope="incomplete"), "cols": [("R", "Raters"), "Why short"], "widths": [10, 32],
            "rows": out,
            "act": "Fix", "empty": "Everyone confirmed has a full panel."}


@admin_list("f360-owing", "f360")
def _list_f360_owing(db, me, vc, args):
    sc, sp = bg_scope(me, "s.business_group")
    if args.get("fbg"):   # Home's 360 cell: the raters of one group's people
        sc, sp = sc + " AND s.business_group=?", list(sp) + [args.get("fbg")]
    rows = db.execute(
        "SELECT u.*, x.todo, x.done FROM users u JOIN (SELECT a.assessor_id, "
        "SUM(CASE WHEN a.status='submitted' THEN 0 ELSE 1 END) todo, SUM(CASE WHEN a.status='submitted' THEN 1 ELSE 0 "
        "END) done FROM assignments a JOIN users s ON s.id=a.subject_id WHERE a.archived=0 AND a.cycle_id=? "
        # 2026-10-31, "out means out" for admin progress counts: only colleagues taking part in the 360
        "AND s.is_demo=0 AND " + rater_task_sql("a") + sc + " GROUP BY a.assessor_id HAVING todo > 0) x ON x.assessor_id=u.id "
        "ORDER BY x.todo DESC, u.full_name", [vc] + list(sp)).fetchall()
    todo = sum(r["todo"] for r in rows)
    return {"kicker": "360 Feedback", "title": "Ratings still to come · %s" % format(todo, ","),
            "sub": "%s people still owe ratings this cycle." % format(len(rows), ","),
            "full": url_for("admin_assessors", scope="incomplete"), "cols": [("To give", "Still to give"), "Given"],
            "rows": [_list_row(r, "f360", [(str(r["todo"]), ""), (str(r["done"] or 0), "")]) for r in rows],
            "bulk": {"href": url_for("admin_reminders"), "label": "Remind them",
                     "note": "Reminders go one email a person, with what's still open for them."},
            "empty": "Every rating is in."}


@admin_list("f360-released", "f360")
def _list_f360_released(db, me, vc, args):
    sc, sp = bg_scope(me, "u.business_group")
