@admin_list("ready-no-lm", "people")
def _list_ready_no_lm(db, me, vc, args):
    rows = _ready_people(db, me, " AND NOT EXISTS (SELECT 1 FROM users m WHERE m.id=u.manager_id AND m.left_at IS NULL "
                                 "AND m.id!=u.id)")
    left = {r[0] for r in db.execute("SELECT id FROM users WHERE left_at IS NOT NULL")}

    def why(r):
        if not r["manager_id"]:
            return "No line manager on file"
        return "Set as their own line manager" if r["manager_id"] == r["id"] else (
            "Their line manager has left" if r["manager_id"] in left else "Their line manager isn't found")
