# ---------------------------------------------------------------------------
# LEADER REVIEWS (Chris, 2026-11-09; canvas "Leader reviews on the person page", brief "Leader reviews build brief 2026-11-09.md"):
# a leader's role chip on their person page (HOD of N, BU CEO, CG / BGCFO, BG CEO, Group Chief) opens the people of their review
# in the list panel, each with where they stand on Performance and Potential, under a status box that says the state of the review
# and offers the one action that fits (Unlock both, Give late pass, End pass). `leader_review_view` is THE reader of that progress:
# every state, count and refusal comes from what already exists (_unlock_facts / _unlock_row / _unlock_higher, the late-pass
# candidates and _late_why_not, hod_review_axes, the populations the calibration pages use), and the per-person state is ONE
# batched read per axis over the review's own session(s), never a query a person. It is a read: it writes nothing and the actions
# are the existing forms (the Unlock URLs, admin_person_late_end), which stay the super admin's.
# Once results are released to leaders for anyone in the review (`_late_leader_out`), or the cycle shown is not the active one, a
# review is over: the reader returns None and the lists are today's plain ones (no box, no progress columns, no buttons).
# ---------------------------------------------------------------------------
LR_TIERS = ("hod", "buceo", "bugrp", "group", "bgceo")
LR_TITLES = {"hod": "Department Review", "buceo": "BU calibration", "bugrp": "Calibration group", "group": "Group Chief group",
             "bgceo": "Talent Box"}
LR_LIST_KEYS = {"hod": "hod-people", "buceo": "review-bu", "bugrp": "review-cg", "group": "review-group", "bgceo": "review-bg"}


def _lr_day(raw_utc):
    """A stored UTC time as the day in MYT without the year: '2 Nov'; '' when unset."""
    return " ".join(_st_day(_myt(raw_utc)).split()[:2]) if raw_utc else ""


def _lr_pairs(db, f):
    """{(business group, company)} the review's people and leader sit in: what an admin's scope must cover to read it."""
    tier = f["tier"]
    pairs = set()
    if tier == "hod":
        pairs = {(r[0], r[1]) for r in db.execute(
            "SELECT DISTINCT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND left_at IS NULL", (f["key"],))}
        h = db.execute("SELECT business_group, company FROM users WHERE id=?", (f["key"],)).fetchone()
        if h:
            pairs.add((h[0], h[1]))
    elif tier == "buceo":
        pairs = {(f["bg"], c) for c in f["units"]}
    elif tier == "bugrp":
        pairs = {(r[0], r[1]) for r in db.execute(
            "SELECT DISTINCT business_group, company FROM users WHERE business_group=? AND role!='admin' AND left_at IS NULL "
            "AND " + bu_group_member_sql("users"), (f["bg"], f["gid"]))}
        pairs.add((f["bg"], f["key"][1]))
    elif tier == "group":
        pairs = {(r[0], r[1]) for r in db.execute(
            "SELECT DISTINCT u.business_group, u.company FROM pm_calibration_group_members gm JOIN users u ON u.id=gm.subject_id "
            "WHERE gm.group_id=? AND u.left_at IS NULL", (f["key"],))}
    else:
        pairs = {(f["bg"], r[0]) for r in db.execute(
            "SELECT DISTINCT company FROM users WHERE business_group=? AND role!='admin' AND left_at IS NULL", (f["bg"],))}
    return pairs


def _lr_access(db, me, f):
    """'act' (the super admin: the progress and its actions), 'read' (an admin whose role holds Calibration's read AND whose scope
    covers every unit the review's people and leader sit in: the progress, no actions), or None (today's view). Chris, 2026-11-09:
    "read-only for an admin whose role holds calibration.read AND whose scope covers that leader's unit"."""
    if not me:
        return None
    if is_super(me):
        return "act"
    if me["role"] != "admin" or not admin_can(me, "calibration", "read"):
        return None
    return "read" if all(can_access(me, b, c) for b, c in _lr_pairs(db, f)) else None


def _lr_people(db, f):
    """(roster rows, pm ids, pot ids): everyone this review's leader is over (active, not an admin) with their 'This cycle' code,
    and who of them is IN the review on each axis (the populations the calibration pages read: the potential one is the
    confirmed-and-not-demo people, the performance one adds a scorecard). Three queries whatever the size."""
    pid, tier = f["pid"], f["tier"]
    base = "SELECT u.*, %s AS part_code FROM users u WHERE u.role!='admin' AND u.left_at IS NULL AND " % _lm_part_sql("u")
    order = " ORDER BY LOWER(u.full_name), u.id"
    if tier == "hod":
        sk, sa = _hod_review_skip_sql(db, f["key"])
        roster = db.execute(base + "u.hod_id=?" + order, (f["key"],)).fetchall()
        where, args = "hod_id=?" + sk, [f["key"]] + list(sa)
    elif tier == "buceo":
        ph = ",".join("?" * len(f["units"]))
        roster = db.execute(base + "u.business_group=? AND u.company IN (%s)" % ph + order, [f["bg"]] + f["units"]).fetchall()
        where, args = "business_group=? AND company IN (%s) AND NOT %s" % (ph, bu_grouped_sql("users")), [f["bg"]] + f["units"]
    elif tier == "bugrp":
        roster = db.execute(base + "u.business_group=? AND " + bu_group_member_sql("u") + order, (f["bg"], f["gid"])).fetchall()
        where, args = "business_group=? AND " + bu_group_member_sql("users"), [f["bg"], f["gid"]]
    else:   # a Group Chief group
        roster = db.execute(base + "u.id IN (SELECT subject_id FROM pm_calibration_group_members WHERE group_id=?)" + order,
                            (f["key"],)).fetchall()
        where, args = "id IN (SELECT subject_id FROM pm_calibration_group_members WHERE group_id=%d)" % int(f["key"]), []
    pm_ids = {r[0] for r in db.execute("SELECT id FROM users WHERE role!='admin' AND " + where + " AND "
                                       + pm_calibration_population_sql(), args + [pid])}
    pot_ids = {r[0] for r in db.execute("SELECT id FROM users WHERE role!='admin' AND " + where + " AND "
                                        + calibration_population_sql(), args)}
    return roster, pm_ids, pot_ids


def _lr_saved(db, f, axis):
    """{subject id: {original_band, adjusted_band, adjusted_at}} the review's saved calls on one axis, from its own session(s):
    ONE query. And {subject id: locked_at} of the people a Group Chief locked one by one (their own table), else {}."""
    tbl_a, tbl_s, cyc = (("pm_calibration_adjustments", "pm_calibration_sessions", f["pid"]) if axis == "pm"
                         else ("calibration_adjustments", "calibration_sessions", f["cid"]))
    tier = f["tier"]
    scopes = [str(f["key"])] if tier in ("hod", "group") else f["units"] if tier == "buceo" else [f["scope"]]
    stier = {"hod": "hod", "buceo": "buceo", "bugrp": "buceo", "group": "group"}[tier]
    out = {r["subject_id"]: dict(r) for r in db.execute(
        "SELECT ca.subject_id, ca.original_band, ca.adjusted_band, ca.adjusted_at FROM %s ca JOIN %s cs ON cs.id=ca.session_id "
        "WHERE cs.cycle_id=? AND cs.tier=? AND cs.scope_key IN (%s)" % (tbl_a, tbl_s, ",".join("?" * len(scopes))),
        [cyc, stier] + scopes)}
    locks = {}
    if tier == "group":
        locks = {r[0]: r[1] for r in db.execute("SELECT subject_id, locked_at FROM %s WHERE cycle_id=? AND group_id=?"
                                                % ("pm_group_locks" if axis == "pm" else "pot_group_locks"), (f["pid"], f["key"]))}
    return out, locks


def _lr_cell(axis, tier, applies, inpop, sess_locked, plock, adj, why=("Not in the review", "")):
    """One person's cell on one axis: {state, word, tone, what, day, sub, moved}. state: 'locked' (the leader submitted / locked
    it: Submitted for an HOD, Locked for the rest), 'saved' (calls saved, not submitted), 'none' (not looked at yet), 'out' (not in
    the review: `why` is the pill and its line), 'na' (the axis doesn't apply to this leader). Moved up / down compares the
    adjusted band with the original on the band order the code already uses; never a band name."""
    if not applies:
        return {"state": "na", "word": "Not in this review", "tone": "off", "what": "", "day": "", "sub": "", "moved": None}
    if not inpop:
        return {"state": "out", "word": why[0], "tone": "off", "what": why[1], "day": "", "sub": why[1], "moved": None}
    moved, what = None, ""
    if adj:
        o, a = adj["original_band"], adj["adjusted_band"]
        ro, ra = _BAND_RANK[axis].get(o), _BAND_RANK[axis].get(a)
        if o == a:
            moved, what = False, "Kept"
        elif ro is not None and ra is not None:
            moved, what = True, "Moved up" if ra > ro else "Moved down"
        else:
            moved, what = True, "Moved"
    locked_at = plock or sess_locked
    if locked_at:
        what = what or "Kept as it came"
        day = _lr_day(locked_at)
        return {"state": "locked", "word": "Submitted" if tier == "hod" else "Locked", "tone": "ok", "what": what, "day": day,
                "sub": what + (" · " + day if day else ""), "moved": bool(moved)}
    if adj:
        day = _lr_day(adj["adjusted_at"])
        return {"state": "saved", "word": "Saved", "tone": "mid", "what": what, "day": day,
                "sub": what + (" · " + day if day else ""), "moved": bool(moved)}
    return {"state": "none", "word": "Not started", "tone": "off", "what": "Not looked at yet", "day": "",
            "sub": "Not looked at yet", "moved": False}


def _lr_out_why(r, cyc, axis, applies_other, grouped):
    """(pill, line) of someone not in the review on an axis: why, in the list's own short words."""
    code = r["part_code"]
    if code != "in":
        if code == "below_min_grade":
            return ("Not in the review", "Below JG %s" % (_row_get(cyc, "min_job_grade") or ""))
        return ("Not in the review", {"grade_h": "Grade H Appraisal", "unit_out": "Unit left out"}.get(code, "Not taking part"))
    if grouped:
        return ("Not in the review", "In a calibration group")
    if axis == "pm" and applies_other:
        return ("Not in the review", "No KPI lines this cycle")
    return ("Not in the review", "Not taking part")


def _lr_window_close(db, f):
    """The leader's window close as '3 Nov 2026, 15:59', else ''."""
    for c in (f["cell"],) + tuple(reversed(UNLOCK_CELLS[f["tier"]])):
        raw = window_dates(db, c, f["cid"])[1]
        if raw:
            return _late_when(raw)
    return ""


def _lr_pass(db, f):
    """The running late pass of this scope's leader(s) as {id, uid, until, by, day, reason, name}, else None."""
    for L in f["leaders"]:
        rows = _late_held_rows(db, L["id"], f["cell"], f["cid"], scope=[f["scope"]])
        if rows:
            r = rows[0]
            by = db.execute("SELECT full_name FROM users WHERE id=?", (r["given_by"],)).fetchone() if r["given_by"] else None
            return {"id": r["id"], "uid": L["id"], "name": L["full_name"], "until": _late_disp(r["until_at"]),
                    "by": by["full_name"] if by else "Group People", "day": _lr_day(r["given_at"]), "reason": r["reason"] or ""}
    return None


def _lr_give_why(db, cyc, f):
    """(the sentence a late pass can't be given, or None when it can). The leader's own candidate for this scope, asked of
    _late_why_not (the one place every refusal is said)."""
    if not f["leaders"]:
        return "Nobody holds this seat, so there is nobody to give time to. Seat someone first."
    L = f["leaders"][0]
    c = next((x for x in _late_leader_cands(db, L, cyc) if x["cell"] == f["cell"] and x["scope"] == f["scope"]), None)
    if not c:
        return "No late pass can open this for %s." % L["full_name"]
    c["subject"] = L["id"]
    return _late_why_not(db, cyc, c)


def _lr_counts_words(cnt, axes, reviewed=False):
    """'performance 7 of 11 reviewed, potential 5 of 11': what is saved on each axis that applies to this leader."""
    bits = []
    if axes["pm"]:
        bits.append("performance %d of %d%s" % (cnt["pm_done"], cnt["pm_n"], " reviewed" if reviewed else ""))
    if axes["pot"]:
        bits.append("potential %d of %d" % (cnt["pot_done"], cnt["pot_n"]))
    return ", ".join(bits)


def _lr_box(db, me, f, cyc, cnt, axes, access, nxt):
    """The status box's facts: {title, state, pill {kind, tone, text}, note, line, acts [], no}. One of the states below, each
    with ONLY its action: locked past the deadline (Unlock both), locked inside the window (the same Unlock, no days), closed and
    not locked (Give late pass), a pass running (End pass), a tier above has locked (no button, its reason), window open (no
    button). Actions are the super admin's: `acts` is empty for anyone else, the lines stay."""
    tier = f["tier"]
    verb = "Submitted" if tier == "hod" else "Locked"
    notv = "Not submitted" if tier == "hod" else "Not locked"
    close = _lr_window_close(db, f)
    closed = _unlock_closed(db, f)
    both = [ax for ax in ("pm", "pot") if axes[ax]]
    fully = bool(both) and all(f["locked_" + ax] for ax in both)
    anyl = bool(f["locked_pm"] or f["locked_pot"])
    n = cnt["n"]
    title = "%s · %s" % (LR_TITLES[tier], f["unit"] if tier != "hod" else _lr_hod_unit(db, f))
    box = {"title": title, "state": "", "pill": {"kind": "pill", "tone": "off", "text": ""}, "note": "", "line": "", "acts": [],
           "no": ""}
    saved = _lr_counts_words(cnt, axes)
    saved_r = _lr_counts_words(cnt, axes, reviewed=True)
    held = f.get("people") or 0
    hi = _unlock_higher(db, f)
    if fully:
        at = max(f["locked_" + ax] for ax in both)
        box["pill"] = {"kind": "pill", "tone": "ok", "text": "%s %s" % (verb, _late_disp(at))}
        box["note"] = ("Performance and potential locked" if len(both) > 1
                       else "%s locked" % ("Performance" if both == ["pm"] else "Potential"))
        tail = "%d %s in it: %d moved, %d kept." % (n, "person" if n == 1 else "people", cnt["moved"], cnt["kept"])
        box["line"] = ("Closed for everyone %s. %s" % (close, tail)) if closed and close else (
            ("Window open until %s. %s" % (close, tail)) if close else tail)
        if hi:
            box["state"] = "locked_blocked"
            box["no"] = hi["short"]
        elif closed:
            box["state"] = "locked_closed"
            box["acts"] = [{"kind": "unlock", "muted": "Both axes, all %d %s" % (n, "person" if n == 1 else "people")}]
        else:
            box["state"] = "locked_early"
            box["acts"] = [{"kind": "unlock", "muted": ("Open again until %s, no extra days" % close) if close
                            else "Open again, no extra days"}]
        return _lr_box_done(box, access)
    run = _lr_pass(db, f)
    if run:
        box["state"] = "pass"
        box["pill"] = {"kind": "pass", "tone": "mid", "text": "Late pass until %s" % run["until"]}
        box["line"] = "Given by %s on %s: “%s”%s" % (run["by"], run["day"], run["reason"],
                                                              (" Saved: %s." % saved) if saved else "")
        box["acts"] = [{"kind": "end", "pass_id": run["id"], "uid": run["uid"], "name": run["name"]}]
        return _lr_box_done(box, access)
    st = window_state(db, f["cell"], f["cid"])
    part = ("People locked one by one: %d. " % held) if held and not anyl else ""
    half = ("%s locked, the other not. " % ("Performance" if f["locked_pm"] else "Potential")) if anyl else ""
    if st == "closed":
        box["pill"] = {"kind": "pill", "tone": "bad", "text": notv}
        box["note"] = ("closed %s" % close) if close else "closed"
        why = _lr_give_why(db, cyc, f)
        if saved and (cnt["pm_done"] or cnt["pot_done"]):
            box["line"] = "%s%sSaved, %s: %s. What they saved stays." % (part, half, notv.lower(), saved_r)
        else:
            box["line"] = "%s%sNothing saved yet. %d %s in it." % (part, half, n, "person" if n == 1 else "people")
        if not f["leaders"]:
            box["state"] = "vacant"
            box["no"] = why
        elif why:
            box["state"] = "closed_blocked"
            box["no"] = why
        else:
            box["state"] = "closed_give"
            box["acts"] = [{"kind": "give", "pick": "%s|%s" % (f["cell"], f["scope"]),
                            "muted": "Opens it for them alone, both axes"}]
    elif st == "not_open":
        opens = window_dates(db, f["cell"], f["cid"])[0]
        box["state"] = "not_open"
        box["pill"] = {"kind": "pill", "tone": "info", "text": "Opens %s" % (_late_when(opens) or "later")}
        box["line"] = "%d %s in it." % (n, "person" if n == 1 else "people")
    else:
        box["state"] = "open"
        box["pill"] = {"kind": "pill", "tone": "info", "text": ("Open until %s" % close) if close else "Open"}
        box["line"] = ("%s%s%s" % (part, half, ("Saved so far: %s." % saved) if saved else "Nothing saved yet.")).strip()
        if hi:
            box["no"] = hi["short"]
    return _lr_box_done(box, access)


def _lr_box_done(box, access):
    """The box for who is looking: an admin who only reads keeps the lines and loses every action."""
    if access != "act":
        box["acts"] = []
    return box


def _lr_hod_unit(db, f):
    """An HOD review's unit words: its people's one unit, else the first and the count of the rest."""
    units = sorted({display_company(r_["business_group"], r_["company"]) or (r_["company"] or "") for r_ in db.execute(
        "SELECT DISTINCT business_group, company FROM users WHERE hod_id=? AND role!='admin' AND left_at IS NULL AND "
        "COALESCE(company,'')!=''", (f["key"],))})
    return (units[0] + (" +%d" % (len(units) - 1) if len(units) > 1 else "")) if units else (f["name"] or "")


def _lr_live(db, cyc, f):
    """Is this review still going on: the cycle shown is the active one, a cycle that has the part (an Early Year has none; a
    Mid-Year only the HOD's), and no result is released to leaders for anyone in it."""
    act = active_cycle(db)
    if not f or not cyc or not act or cyc["id"] != act["id"] or cycle_row_is_early_year(cyc):
        return False
    if f["tier"] != "hod" and cycle_is_mid_year(db, cyc["id"]):
        return False
    return not _late_leader_out(db, f["cell"], f["cid"], f["scope"], f["bg"])


def leader_review_view(db, me, tier, key, cyc):
    """THE reader of a leader review's progress (Chris, 2026-11-09). tier / key as _unlock_facts: ('hod', hod id), ('buceo', (bg,
    company)), ('bugrp', (bg, company, group id)), ('group', group id), ('bgceo', bg). Returns None when there is nothing to show
    (the review is over: results released to leaders for anyone in it, or `cyc` isn't the active cycle; or `me` may not read it:
    access is the super admin's, or an admin with Calibration's read whose scope covers every unit in it) -- the caller shows
    today's plain view. Else {tier, key, f, title, unit, leader, access, axes, counts, box, people, units}: `people` one entry a
    person {uid, row, in_review, pm, pot} (each axis {state, word, tone, what, day, sub, moved}); for a BG CEO `people` is empty
    and `units` are its business units. Reads only; the per-person state is one query per axis over the review's session(s)."""
    if tier not in LR_TIERS:
        return None
    f = _unlock_facts(db, tier, key)
    if not f or not _lr_live(db, cyc, f):
        return None
    access = _lr_access(db, me, f)
    if not access:
        return None
    if tier == "bgceo":
        return _lr_bg_view(db, me, f, cyc, access)
    axes = _lr_axes_on(db, f)
    if not axes or not (axes["pm"] or axes["pot"]):
        return None
    roster, pm_ids, pot_ids = _lr_people(db, f)
    saved, locks = {}, {}
    for ax in ("pm", "pot"):
        saved[ax], locks[ax] = _lr_saved(db, f, ax) if axes[ax] else ({}, {})
    grouped_ids = set()
    if tier == "buceo" and bu_groups_all(db):
        ph = ",".join("?" * len(f["units"]))
        grouped_ids = {r[0] for r in db.execute("SELECT id FROM users WHERE business_group=? AND company IN (%s) AND "
                                                % ph + bu_grouped_sql("users"), [f["bg"]] + f["units"])}
    people, in_rev, moved = [], set(), set()
    for r in roster:
        uid = r["id"]
        inrev = uid in pot_ids or uid in pm_ids
        cells = {}
        for ax, ids in (("pm", pm_ids), ("pot", pot_ids)):
            why = _lr_out_why(r, cyc, ax, axes["pot" if ax == "pm" else "pm"] and uid in pot_ids, uid in grouped_ids)
            cells[ax] = _lr_cell(ax, tier, axes[ax], uid in ids, f["locked_" + ax], locks[ax].get(uid), saved[ax].get(uid), why)
            if cells[ax]["moved"] and uid in ids:
                moved.add(uid)
        if inrev:
            in_rev.add(uid)
        people.append({"uid": uid, "row": r, "in_review": inrev, "pm": cells["pm"], "pot": cells["pot"]})
    cnt = {"n": len(in_rev), "moved": len(moved & in_rev), "kept": len(in_rev) - len(moved & in_rev),
           "pm_n": len(pm_ids), "pot_n": len(pot_ids),
           "pm_done": sum(1 for u_ in pm_ids if u_ in saved["pm"] or u_ in locks["pm"]),
           "pot_done": sum(1 for u_ in pot_ids if u_ in saved["pot"] or u_ in locks["pot"])}
    leader = f["leaders"][0] if f["leaders"] else None
    box = _lr_box(db, me, f, cyc, cnt, axes, access, None)
    return {"tier": tier, "key": f["key"], "f": f, "title": box["title"], "unit": f["unit"], "leader": leader, "access": access,
            "axes": axes, "counts": cnt, "box": box, "people": people, "units": []}


def _lr_axes_on(db, f):
    """{pm, pot}: which axes apply to this leader. An HOD's are hod_review_axes' (None = doesn't apply); the others' are the module
    being on this cycle (and, for potential, the cycle having it). None when an HOD has nobody in their review."""
    if f["tier"] == "hod":
        ax = hod_review_axes(db, [f["key"]]).get(f["key"])
        return {"pm": ax.get("pm") is not None, "pot": ax.get("pot") is not None} if ax else None
    return {"pm": bool(f["pid"] and cycle_module_on("pm", db)),
            "pot": bool(f["cid"] and cycle_module_on("calibration", db) and cycle_has_potential(db, f["cid"]))}


def _lr_bg_view(db, me, f, cyc, access):
    """A BG CEO's review (the Talent Box): its rows are the business group's UNITS, each with its BU CEO, its people, the BU
    calibration's state and the Talent Box's. Counts of units. Both Give late pass (units still open) and Unlock the Talent Box
    (units locked) can show."""
    bg, cid, pid = f["bg"], f["cid"], f["pid"]
    ulist, whole = _late_bg_units(db, cid, bg)
    holders = buceo_holders(db, bg)
    sess = {}
    for ax, tbl, cyc_ in (("pm", "pm_calibration_sessions", pid), ("pot", "calibration_sessions", cid)):
        sess[ax] = {r[0]: r[1] for r in db.execute("SELECT scope_key, locked_at FROM %s WHERE cycle_id=? AND tier='buceo' AND "
                                                   "locked_at IS NOT NULL" % tbl, (cyc_,))}
    tbm = {}
    for ax, tbl, adj, cyc_ in (("pm", "pm_calibration_sessions", "pm_calibration_adjustments", pid),
                               ("pot", "calibration_sessions", "calibration_adjustments", cid)):
        for r in db.execute("SELECT u.company, ca.subject_id FROM %s ca JOIN %s cs ON cs.id=ca.session_id JOIN users u ON "
                            "u.id=ca.subject_id WHERE cs.cycle_id=? AND cs.tier='bgceo' AND cs.scope_key=? AND "
                            "ca.adjusted_band!=ca.original_band AND ca.pinned IS NULL" % (adj, tbl), (cyc_, bg)):
            tbm.setdefault(r[0], set()).add(r[1])
    units = []
    for x in ulist:
        co = x["company"]
        lead = _bu_units_of(db, pid, bg, co)[0]
        bu_pm, bu_pot = sess["pm"].get(lead) or sess["pm"].get(co), sess["pot"].get(lead) or sess["pot"].get(co)
        bu_locked = bool(bu_pm and (bu_pot or not cycle_has_potential(db, cid)))
        h = holders.get((bg, co)) or holders.get((bg, lead))
        units.append({"company": co, "label": display_company(bg, co) or co, "ceo": h["full_name"] if h else "",
                      "n": x["n"], "bu_locked": bu_locked, "bu_at": _lr_day(bu_pm or bu_pot) if (bu_pm or bu_pot) else "",
                      "tb_locked": x["locked"], "tb_at": x["at"].rsplit(" ", 1)[0] if x["at"] and x["at"].count(" ") >= 2 else x["at"],
                      "moved": len(tbm.get(co, ()))})
    nl, nu = sum(1 for u_ in units if u_["tb_locked"]), len(units)
    people = sum(u_["n"] for u_ in units)
    close = _lr_window_close(db, f)
    run = _lr_pass(db, f)
    st = window_state(db, f["cell"], cid)
    box = {"title": "Talent Box · %s" % f["unit"], "state": "", "pill": {"kind": "pill", "tone": "off", "text": ""}, "note": "",
           "line": "", "acts": [], "no": ""}
    box["pill"] = {"kind": "pill", "tone": "ok" if nl == nu and nu else ("mid" if nl else ("bad" if st == "closed" else "info")),
                   "text": "%d of %d unit%s locked" % (nl, nu, "" if nu == 1 else "s")}
    box["note"] = ("closed for everyone %s" % close if st == "closed" else "open until %s" % close) if close else ""
    open_units = [u_ for u_ in units if not u_["tb_locked"]]
    bits = ["%s locked%s." % (u_["label"], (" " + u_["tb_at"]) if u_["tb_at"] else "") for u_ in units if u_["tb_locked"]]
    if open_units:
        bits.append("%s not locked: %d %s still open." % (
            " and ".join(u_["label"] for u_ in open_units[:3]) + (" and %d more" % (len(open_units) - 3) if len(open_units) > 3 else ""),
            sum(u_["n"] for u_ in open_units), "person" if sum(u_["n"] for u_ in open_units) == 1 else "people"))
    box["line"] = " ".join(bits)
    acts = []
    if run:
        box["state"] = "pass"
        box["pill"] = {"kind": "pass", "tone": "mid", "text": "Late pass until %s" % run["until"]}
        box["line"] = "Given by %s on %s: “%s” %s" % (run["by"], run["day"], run["reason"], box["line"])
        acts.append({"kind": "end", "pass_id": run["id"], "uid": run["uid"], "name": run["name"]})
    elif st == "closed" and open_units:
        why = _lr_give_why(db, cyc, f)
        if why:
            box["no"] = why
        else:
            acts.append({"kind": "give", "pick": "%s|%s" % (f["cell"], f["scope"]),
                         "muted": "Opens the unlocked unit for them alone"})
    anyl = bool(f["locked_pm"] or f["locked_pot"])
    if anyl and not run:
        acts.append({"kind": "unlock", "muted": "Every locked unit reopens"})
    box["state"] = box["state"] or ("closed" if st == "closed" else "open")
    box["acts"] = acts if access == "act" else []
    cnt = {"n": people, "units": nu, "units_locked": nl, "moved": sum(u_["moved"] for u_ in units), "kept": 0}
    return {"tier": "bgceo", "key": f["key"], "f": f, "title": box["title"], "unit": f["unit"],
            "leader": f["leaders"][0] if f["leaders"] else None, "access": access, "axes": {"pm": True, "pot": True},
            "counts": cnt, "box": box, "people": [], "units": units}


def _lr_next_url(leader_id, list_src):
    """Where an action of the status box comes back to: the leader's page with this list panel open again."""
    return url_for("admin_person", uid=leader_id, tab="overview", panel="list", ls=list_src)


def _lr_review_for(db, me, tier, key, cyc, list_src, via=None):
    """The view plus what the template needs to draw its actions: the unlock row (the super admin's form and box), the
    end-pass confirm words, and `next`. None for today's plain view. `via`: the id of the leader whose page hosts this list when it
    was reached from another leader's list (a BG CEO's unit): the Give late pass then links to THIS leader's own page, whose Give
    panel it is, instead of opening the host page's."""
    v = leader_review_view(db, me, tier, key, cyc)
    if not v:
        return None
    box = v["box"]
    ur = None
    if any(a["kind"] == "unlock" for a in box["acts"]):
        ur = _unlock_row(db, me, tier, key)
        if not ur or not ur.get("box") or ur.get("blocked"):   # nothing to unlock with (or a tier above wins): no button
            box["acts"] = [a for a in box["acts"] if a["kind"] != "unlock"]
            ur = None
    for a in box["acts"]:
        if a["kind"] == "end":
            a["url"] = url_for("admin_person_late_end", uid=a["uid"])
            a["confirm"] = ("It closes for %s again now. What they entered stays as it is, and nothing is sent to them." % a["name"])
            a["title"] = "End %s's late pass for the %s?" % (a["name"], LR_TITLES[tier].lower())
        elif a["kind"] == "give":
            if via and v["leader"] and str(via) != str(v["leader"]["id"]):
                a["person_url"] = url_for("admin_person", uid=v["leader"]["id"], panel="latepass", late_pick=a["pick"])
    leader_id = v["leader"]["id"] if v["leader"] else None
    v["review"] = {"box": box, "unlock": ur, "next": _lr_next_url(leader_id, list_src) if leader_id else "",
                   "units": v["units"], "tier": tier, "can_act": v["access"] == "act"}
    return v


@app.template_global()
def lr_chip(cyc, tier, *key):
    """For a leader's role chip on the person page: {"page": the list's address, "frag": its ?fragment=1 address} when the chip
    opens that leader's review list, else None. The super admin's always (the list is today's plain one once the review is over);
    an admin with Calibration's read only while the review is live and their scope covers it (leader_review_view's access)."""
    if not has_request_context():
        return None
    me = current_user()
    if not me or me["role"] != "admin":
        return None
    db = get_db()
    k = key if len(key) > 1 else key[0]
    if not is_super(me):
        if not admin_can(me, "calibration", "read"):
            return None
        f = _unlock_facts(db, tier, k)
        if not f or not _lr_live(db, cyc, f) or not _lr_access(db, me, f):
            return None
    args = {}
    if tier == "hod":
        args["uid"] = k
    elif tier == "buceo":
        args.update(bg=k[0], co=k[1])
    elif tier == "bugrp":
        args.update(bg=k[0], co=k[1], gid=k[2])
    elif tier == "group":
        args["gid"] = k
    else:
        args["bg"] = k
    if cyc:
        args["cycle"] = cyc["id"]
    name = LR_LIST_KEYS[tier]
    return {"page": url_for("admin_list_view", key=name, **args), "frag": url_for("admin_list_view", key=name, fragment=1, **args)}


def _lr_cycle(db, args, vc):
    """The cycle a leader-review list is read in: ?cycle= (the person page's own pick), else the top bar's."""
    cid = args.get("cycle", type=int) if hasattr(args, "getlist") else None
    return db.execute("SELECT * FROM cycles WHERE id=?", (cid or vc,)).fetchone()


def _lr_search_ids(db, ids, qin, q, extra=()):
    """The ones of these people the list's Search in matches: the list's own clause, in chunks."""
    frag, sp = _people_search_sql(qin, q, "u.", extra)
    out = set()
    for i in range(0, len(ids), 800):
        ch = ids[i:i + 800]
        out |= {r[0] for r in db.execute("SELECT u.id FROM users u WHERE u.id IN (%s) AND %s" % (",".join("?" * len(ch)), frag),
                                         list(ch) + list(sp))}
    return out


def _lr_cell_tuple(c):
    """A progress cell as the list panel draws it: (pill word, tone, hover, the muted line under it)."""
    return (c["word"], c["tone"], ("%s: %s" % (c["word"], c["sub"])) if c["sub"] else c["word"], c["sub"])


def _lr_progress_list(db, me, v, args, list_key, hidden, kicker, title, sub, full):
    """A people list with the status box and the PERSON | PERFORMANCE | POTENTIAL | Open columns (Chris's canvas boards A1-A5, B1):
    the rows come from the one reader, so a list can never disagree with the box over it."""
    q, qin, _menu = people_search_args((), src=args)
    rows = v["people"]
    if q:
        hit = _lr_search_ids(db, [p["uid"] for p in rows], qin, q)
        rows = [p for p in rows if p["uid"] in hit]
    return {"kicker": kicker, "title": title, "sub": sub, "full": full, "no_bu": True, "head": ["Person"],
            "cols": ["Performance", "Potential"], "colw": [34, 25, 25, 16],
            "rows": [_list_row(p["row"], "overview", [_lr_cell_tuple(p["pm"]), _lr_cell_tuple(p["pot"])]) for p in rows],
            "review": v["review"], "empty": "Nobody matches that." if q else "Nobody is in this review.",
            "search": {"fields": ("all", "name", "eid", "title", "grade", "email"), "extra": (),
                       "all_ph": "Search name, ID, title, email, JG", "hidden": hidden, "label": "Search the list", "q": q,
                       "qin": qin, "action": url_for("admin_list_view", key=list_key)}}


def _lr_plain_list(db, me, f, cyc, args, list_key, hidden, kicker, title, sub, full):
    """Today's plain list of a leader's people (the review is over, or never was): the person, their unit and 'This cycle'.
    The super admin's only."""
    roster, _pm, _pot = _lr_people(db, f)
    act = active_cycle(db)
    q, qin, _menu = people_search_args((), src=args)
    if q:
        hit = _lr_search_ids(db, [r["id"] for r in roster], qin, q)
        roster = [r for r in roster if r["id"] in hit]
    return {"kicker": kicker, "title": title, "sub": sub, "full": full,
            "cols": ["This cycle"] if act else [], "colw": [26, 17, 42, 15] if act else [50, 34, 16],
            "rows": [_list_row(r, "overview", [_lm_part_cell(r["part_code"], act)] if act else []) for r in roster],
            "empty": "Nobody matches that." if q else "Nobody is here.",
            "search": {"fields": ("all", "name", "eid", "title", "grade", "email"), "extra": (),
                       "all_ph": "Search name, ID, title, email, JG", "hidden": hidden, "label": "Search the list", "q": q,
                       "qin": qin, "action": url_for("admin_list_view", key=list_key)}}


def _lr_unit_cells(u):
    """A BG CEO's unit row cells: its people, the BU calibration's state and the Talent Box's, each a pill with a line."""
    return [(str(u["n"]), ""),
            ("Locked", "ok", "Locked", u["bu_at"]) if u["bu_locked"] else ("Not locked", "off", "Not locked", ""),
            ("Locked", "ok", "Locked", ("%s · %d moved" % (u["tb_at"], u["moved"])) if u["tb_at"] else
             ("%d moved" % u["moved"])) if u["tb_locked"] else
            ("Not locked", "bad", "Not locked", ("%d moved" % u["moved"]) if u["moved"] else "")]


def _lr_bg_list(db, me, f, v, cyc, list_key, hidden, args):
    """The BG CEO's units (board C1): the unit and its BU CEO, its people, its BU calibration and its Talent Box. A unit opens its
    people in the same panel (Back returns here). With no live review (v None) it is the plain units and their people."""
    bg = f["bg"]
    if v:
        units = v["units"]
    else:
        ulist, _w = _late_bg_units(db, f["cid"], bg)
        holders = buceo_holders(db, bg)
        units = [{"company": x["company"], "label": display_company(bg, x["company"]) or x["company"], "n": x["n"],
                  "ceo": (holders.get((bg, x["company"])) or {"full_name": ""})["full_name"]} for x in ulist]
    rows = []
    for u in units:
        href = url_for("admin_list_view", key="review-bu", bg=bg, co=u["company"], **({"cycle": cyc["id"]} if cyc else {}),
                       **({"via": f["leaders"][0]["id"]} if f["leaders"] else {}))   # the BG CEO's page hosts it: its Give is not the unit's
        rows.append({"uid": None, "name": u["label"], "eid": ("BU CEO: %s" % u["ceo"]) if u["ceo"] else "No BU CEO", "bu": u["label"],
                     "dept": "", "jg": "", "eid_only": True, "href": href, "reload": href,
                     "cells": _lr_unit_cells(u) if v else [(str(u["n"]), "")], "tone": ""})
    who = f["leaders"][0]["full_name"] if f["leaders"] else ""
    return {"kicker": "BG CEO · %s" % f["unit"], "title": "Units in the %s Talent Box · %d" % (f["unit"], len(rows)),
            "sub": ("%s moves and locks them on the Talent Box." % who) if who else "Nobody holds the BG CEO seat.",
            "full": url_for("admin_leaders", bg=bg, tab="bgceo"), "no_bu": True, "no_open": True, "keep": "Back to the units",
            "head": ["Business unit"], "cols": ["People", "BU calibration", "Talent Box"] if v else ["People"],
            "colw": [31, 15, 27, 27] if v else [70, 30], "rows": rows, "review": v["review"] if v else None,
            "empty": "No units."}


def _lr_key_from_args(tier, args):
    """The scope key a review list is asked for (?bg= &co= &gid=), or 404."""
    bg, co = args.get("bg") or "", args.get("co") or ""
    gid = args.get("gid", type=int)
    if tier == "buceo" and bg and co:
        return (bg, co)
    if tier == "bugrp" and bg and co and gid:
        return (bg, co, gid)
    if tier == "group" and gid:
        return gid
    if tier == "bgceo" and bg:
        return bg
    abort(404)


def _lr_tier_list(db, me, vc, args, tier):
    """A leader-review list of the unit / calibration group / Group Chief group / business group a chip opens. The admin's access is
    _lr_access's; once the review is over it is today's plain people (super admin only)."""
    key = _lr_key_from_args(tier, args)
    f = _unlock_facts(db, tier, key)
    if not f:
        abort(404)
    if not _lr_access(db, me, f):
        abort(403)
    cyc = _lr_cycle(db, args, vc)
    keep = {"buceo": ("bg", "co"), "bugrp": ("bg", "co", "gid"), "group": ("gid",), "bgceo": ("bg",)}[tier]
    hidden = {k: args.get(k) for k in keep}
    via = (args.get("via") or "").strip()
    if via.isdigit():   # reached from another leader's list (the BG CEO's units): whose page the panel sits on
        hidden["via"] = via
    else:
        via = ""
    if cyc:
        hidden["cycle"] = cyc["id"]
    list_key = LR_LIST_KEYS[tier]
    list_src = url_for("admin_list_view", key=list_key, **hidden)
    v = _lr_review_for(db, me, tier, f["key"], cyc, list_src, via=via)
    if not is_super(me) and not v:   # over (or not theirs to read): the plain list is the super admin's
        abort(403)
    if tier == "bgceo":
        return _lr_bg_list(db, me, f, v, cyc, list_key, hidden, args)
    who = f["leaders"][0]["full_name"] if f["leaders"] else ""
    leader = f["leaders"][0] if f["leaders"] else None
    full = url_for("admin_person", uid=leader["id"], tab="overview") if leader else url_for("admin_users")
    n = len(_lr_people(db, f)[0]) if not v else len(v["people"])
    word = "person" if n == 1 else "people"
    if tier == "buceo":
        kicker, title = "BU CEO · %s" % (display_bg(f["bg"]) or f["bg"]), "People in %s’s BU calibration · %s" % (f["unit"], format(n, ","))
        sub = ("%s calibrates them as BU CEO." % who) if who else "Nobody holds this BU CEO seat."
    elif tier == "bugrp":
        kicker, title = "Calibrator · %s" % (display_bg(f["bg"]) or f["bg"]), "People in the %s calibration group · %s" % (f["unit"], format(n, ","))
        sub = ("%s calibrates them as this group's calibrator." % who) if who else "Nobody calibrates this group."
    else:
        kicker, title = "Group Chief", "People in %s · %s" % (f["unit"], format(n, ","))
        sub = ("%s calls them as Group Chief." % who) if who else "Nobody is Group Chief of this group."
    if v:
        return _lr_progress_list(db, me, v, args, list_key, hidden, kicker, title, sub, full)
    return _lr_plain_list(db, me, f, cyc, args, list_key, hidden, kicker, title, sub, full)


for _lk, _lt in (("review-bu", "buceo"), ("review-cg", "bugrp"), ("review-group", "group"), ("review-bg", "bgceo")):
    def _mk_lr_builder(tier):
        def build(db, me, vc, args):
            return _lr_tier_list(db, me, vc, args, tier)
        return build
    admin_list(_lk, "calibration", all_admins=True)(_mk_lr_builder(_lt))


