# ---- phase 3 (2026-10-20): Home, Data integrity, Lock status --------------------------------------------------------
def _users_by_eid(db, eids):
    """{employee ID: users row} for these IDs (the first account when two share one), one query a 900."""
    eids, out = [e for e in dict.fromkeys(eids) if e], {}
    for i in range(0, len(eids), 900):
        part = eids[i:i + 900]
        for r in db.execute("SELECT * FROM users WHERE employee_id IN (%s) ORDER BY id" % ",".join("?" * len(part)), part):
            out.setdefault(str(r["employee_id"]), r)
    return out


HOME_CELL_WORDS = {"pm": ("Performance", "scorecards submitted"), "f360": ("360 Feedback", "raters done"),
                   "competency": ("Competency", "self-assessed"), "idp": ("Career Plan", "plans shared"),
                   "pot": ("Potential", "department reviews submitted")}   # Potential: the HODs' and BU CEOs' stages (stage=hod|bu)


def _list_home_stage(db, me, vc, args, stage):
    """Home's stage cells (Chris, 2026-11-09): the line managers still with work in a part (each with how many reports wait on
    them), the HODs still to submit, the BU CEOs still to finish (with their units still to lock): the same per-leader read the
    cell counts (_home_lm_work / _home_hod_work / _home_bu_work), so a list can never disagree with its cell."""
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (vc,)).fetchone()
    col = args.get("col") or ""
    specs = {c[0]: c for c in _home_stage_cols(db, vc, cyc, stage)} if cyc and cyc["is_active"] else {}
    if col not in specs:
        abort(404)
    bg = args.get("bg") or ""
    if bg and not can_access_bg(me, bg):
        abort(403)
    if stage == "lm":
        work = _home_lm_work(db, me, cyc, [col])[col]
    else:
        work = (_home_hod_work if stage == "hod" else _home_bu_work)(db, me, cyc, [col])[0][col]
    n = done = 0
    todo = []
    for lid, byb in work.items():
        byb = {b: e for b, e in byb.items() if b and can_access_bg(me, b) and (not bg or b == bg)}
        if not byb:
            continue
        n += 1
        w = sum(e["w"] for e in byb.values())
        if not w:
            done += 1
        else:
            todo.append((lid, w, [x for e in byb.values() for x in e.get("names", [])]))
    users = {}
    ids = [t[0] for t in todo]
    for i in range(0, len(ids), 800):
        users.update({r["id"]: r for r in db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(ids[i:i + 800])),
                                                     ids[i:i + 800])})
    todo = [t for t in todo if t[0] in users]
    todo.sort(key=lambda t: (-t[1], (users[t[0]]["full_name"] or "").lower(), t[0]))
    if stage == "lm":
        cols_, cell = ["Waiting on them"], lambda w, nm: [("%d report%s" % (w, "" if w == 1 else "s"), "mid")]   # noqa: E731
    elif stage == "hod":
        cols_, cell = ["Review", "Department"], lambda w, nm: [("Still to submit", "mid"), (", ".join(nm), "")]   # noqa: E731
    else:
        cols_, cell = ["To lock", "Units still to lock"], lambda w, nm: [   # noqa: E731
            ("%d scope%s" % (w, "" if w == 1 else "s"), "mid"), (", ".join(nm), "")]
    full = (url_for("admin_module_progress", key=_HOME_LM_PROGRESS[col][0], fstage=_HOME_LM_PROGRESS[col][1])
            if stage == "lm" else url_for("admin_calibration_locks", show="open"))
    return {"kicker": "Home · %s" % (display_bg(bg) if bg else "All business groups"),
            "title": "%s · %s of %s %s" % (specs[col][1], format(done, ","), format(n, ","), HOME_STAGE_WORDS[stage]),
            "sub": "Still with work, the most waiting first.", "full": full, "cols": cols_,
            "rows": [_list_row(users[lid], "overview", cell(w, nm)) for lid, w, nm in todo],
            "empty": "Nobody is still waiting."}


@admin_list("home-cell", "cycle")
def _list_home_cell(db, me, vc, args):
    """Home's matrix: one business group's (or every group's) cell, by the same grouped read _home_bg_matrix counts."""
    if args.get("stage") in ("lm", "hod", "bu"):   # the stage switch's cells (2026-11-09)
        return _list_home_stage(db, me, vc, args, args.get("stage"))
    col = args.get("col") if args.get("col") in HOME_CELL_WORDS and args.get("col") != "pot" else "pm"
    bg = args.get("bg") or ""
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (vc,)).fetchone()
    if bg and not can_access_bg(me, bg):
        abort(403)
    ubgc, ubgp = bg_scope(me, "u.business_group")
    live = "u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0"
    extra, extra_p = (" AND u.business_group=?", [bg]) if bg else ("", [])
    label, word = HOME_CELL_WORDS[col]
    if col == "f360":   # the raters the cell counts (_HOME_F360_RATERS_SQL), not done first, most still owed first
        rows = db.execute(
            "SELECT u.*, x.todo, x.done FROM (SELECT a.assessor_id, SUM(CASE WHEN a.status='submitted' THEN 0 ELSE 1 END) todo, "
            "SUM(CASE WHEN a.status='submitted' THEN 1 ELSE 0 END) done FROM assignments a WHERE a.cycle_id=? AND a.archived=0 "
            "AND " + rater_task_sql("a") + " GROUP BY a.assessor_id) x JOIN users u ON u.id=x.assessor_id WHERE " + live + ubgc
            + extra + " ORDER BY (x.todo=0), x.todo DESC, u.full_name", [vc] + list(ubgp) + extra_p).fetchall()
        cells = lambda r: [("all given" if not r["todo"] else "%d of %d to give" % (r["todo"], r["todo"] + r["done"]),  # noqa
                            "" if not r["todo"] else "mid")]
        done, tab = sum(1 for r in rows if not r["todo"]), "f360"
    elif col == "pm":
        # the people the matrix cell counts: someone with a line of their own, in when every one of those is submitted
        # (a BU KPI Group People fills is left out of both sides, pm_own_results_map)
        # Chris 2026-11-08: only people taking part in Performance, as the cell counts (_home_cell_taking_sql)
        urows = db.execute("SELECT DISTINCT u.* FROM pm_kpi_targets t JOIN users u ON u.id=t.subject_id WHERE t.cycle_id=? AND "
                           + live + _home_cell_taking_sql("pm", cyc) + ubgc + extra, [vc] + list(ubgp) + extra_p).fetchall()
        own = pm_own_results_map(db, vc, [r["id"] for r in urows])
        rows = []
        for r in urows:
            m = own.get(r["id"])
            if m and m["own_n"]:
                d_ = dict(r)
                d_["n"], d_["d"] = m["own_n"], m["own_sub"]
                rows.append(d_)
        rows.sort(key=lambda r: (r["d"] == r["n"], (r["full_name"] or "").lower()))
        cells = lambda r: [("all in" if r["d"] == r["n"] else "%d of %d own lines in" % (r["d"], r["n"]),  # noqa: E731
                            "" if r["d"] == r["n"] else "mid")]
        done, tab = sum(1 for r in rows if r["d"] == r["n"]), "performance"
    elif col == "competency":
        rows = db.execute("SELECT u.*, s.submitted_at FROM (SELECT DISTINCT subject_id FROM tc_assignments WHERE "
                          "cycle_id=?) x JOIN users u ON u.id=x.subject_id LEFT JOIN tc_assessments s ON "
                          "s.subject_id=x.subject_id AND s.cycle_id=? WHERE " + live
                          + _home_cell_taking_sql("competency", cyc)   # Chris 2026-11-08: taking part in Competency only, as the cell counts
                          + ubgc + extra + " ORDER BY (s.submitted_at IS NOT NULL), u.full_name", [vc, vc] + list(ubgp) + extra_p).fetchall()
        cells = lambda r: [("submitted" if r["submitted_at"] else "not yet", "" if r["submitted_at"] else "mid")]  # noqa
        done, tab = sum(1 for r in rows if r["submitted_at"]), "competency"
    else:
        year = pm_idp_plan_year(cyc) if cyc else None
        # Chris 2026-11-06: the people the cell counts (idp_count_sql), as the matrix does
        rows = db.execute("SELECT u.*, i.status FROM users u LEFT JOIN pm_idp i ON i.subject_id=u.id AND i.plan_year=? "
                          "WHERE " + live + " AND " + idp_count_sql("u") + ubgc + extra + " ORDER BY (COALESCE(i.status,'draft')!='draft'), u.full_name",
                          [year] + list(ubgp) + extra_p).fetchall()
        cells = lambda r: [(IDP_PLAN_WORDS.get(r["status"], "No plan yet") if r["status"] else "No plan yet",  # noqa
                            "" if r["status"] and r["status"] != "draft" else "mid")]
        done, tab = sum(1 for r in rows if r["status"] and r["status"] != "draft"), "plan"
    return {"kicker": "Home · %s" % (display_bg(bg) if bg else "All business groups"),
            "title": "%s · %s of %s %s" % (label, format(done, ","), format(len(rows), ","), word),
            "sub": "Not done first.",
            # the 360 has no module Progress page: its full list is the assessors' page, as the cell's own link
            "full": (url_for("admin_assessors", scope="incomplete") if col == "f360" else
                     url_for("admin_module_progress", key=col, **({"fbg": bg} if bg else {}))),
            "cols": [("Stage", "Where they are")], "rows": [_list_row(r, tab, cells(r)) for r in rows]}


JOINER_LISTS = {"no_kpi": ("No KPI lines yet", lambda j: j["taking"] and not j["n_kpi"], "performance"),
                "no_panel": ("Short of raters on their 360 panel", lambda j: j["panel_short"], "f360"),
                "ready": ("Competencies ready from their job", lambda j: j["ready"], "competency"),
                "no_job_taking": ("Their job isn't placed", lambda j: j["taking"] and not j["role"], "competency"),
                "no_lm": ("No line manager", lambda j: not j["lm_ok"], "overview"),
                "not_taking": ("Not taking part this cycle", lambda j: not j["taking"], "overview"),
                "to_place": ("Job still to place", lambda j: not j["role"], "competency"),
                "placed": ("Job placed", lambda j: j["role"], "competency")}


