@admin_list("check", "people")
def _list_check(db, me, vc, args):
    """Data integrity: one check's findings (?check=), or every high-severity one (?severity=high), or all of them, by
    the same data_check_rows read its page lists and counts."""
    key, sev = args.get("check") or "", args.get("severity") or ""
    if key and key not in DATA_CHECKS_BY_KEY:
        abort(404)
    chks = [DATA_CHECKS_BY_KEY[key]] if key else [c for c in DATA_CHECKS if not sev or c["severity"] == sev]
    found = []
    for c in chks:
        rows_, _cap = data_check_rows(db, me, vc, c, cap=False)
        found += [(c, r) for r in rows_]
    who = _users_by_eid(db, [r["eid"] for _c, r in found])
    tab_of = lambda c: c.get("tab") or ("f360" if c["fix_ep"] in ("admin_subjects", "admin_panel_build") else "overview")  # noqa: E731
    out = []
    for c, r in found:
        u = who.get(str(r["eid"] or ""))
        cells = [(r["detail"] or "", ""), (c["label"], "low" if c["severity"] == "high" else "")]
        if u:
            out.append(_list_row(u, tab_of(c), cells))
        else:
            out.append({"uid": None, "name": r["name"] or "", "eid": r["eid"] or "", "bu": r["bu"] or "", "dept": "",
                        "jg": "", "href": url_for("admin_data_integrity", check=c["key"]), "cells": cells, "tone": ""})
    title = (DATA_CHECKS_BY_KEY[key]["label"] if key else "High severity" if sev == "high" else "Findings in total")
    return {"kicker": "Data integrity", "title": "%s · %s" % (title, format(len(out), ",")),
            "sub": DATA_CHECKS_BY_KEY[key]["why"] if key else "Every finding, each with the check it comes from.",
            "full": url_for("admin_data_integrity", **({"check": key} if key else {})),
            "cols": ["Finding", "Check"], "widths": [21, 21], "rows": out, "act": "Fix", "empty": "Nothing found."}


@admin_list("lock-tier", "calibration")
def _list_lock_tier(db, me, vc, args):
    """Lock status: one tier's scopes (the same _calib_lock_scopes read), still open first; each opens the leader who
    locks it."""
    tier = args.get("tier") or ""
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (vc,)).fetchone()
    rows = [r for r in _calib_lock_scopes(db, me, cyc) if not tier or r["tier"] == tier]
    if args.get("bg"):
        rows = [r for r in rows if args.get("bg") in r.get("bgs", [r["bg"]])]
    if args.get("bu"):
        rows = [r for r in rows if args.get("bu") in r["companies"]]
    rows.sort(key=lambda r: (r["locked"], r["scope"]))
    names = {}
    for r in db.execute("SELECT id, full_name FROM users WHERE left_at IS NULL"):
        names.setdefault(r["full_name"], r["id"])
    out = []
    for r in rows:
        uid = names.get(r["who"]) if r["who"] else None
        out.append({"uid": uid, "name": r["scope"], "eid": r["sub"] or "", "bu": r["who"] or "No one holds it",
                    "dept": "", "jg": "", "href": url_for("admin_person", uid=uid, tab="overview") if uid
                    else url_for("admin_calibration_locks"),
                    "cells": [("Locked", "") if r["locked"] else ("Open", "low"), ("%s people" % format(r["n"], ","), "")],
                    "tone": ""})
    n_open = sum(1 for r in rows if not r["locked"])
    return {"kicker": "Lock status", "title": "%s · %s of %s locked" % (
                rows[0]["tier_label"] if rows and tier else "Every scope", format(len(rows) - n_open, ","),
                format(len(rows), ",")),
            "sub": "Still open first. Each lock is the leader's own, in their login.",
            "full": url_for("admin_calibration_locks"), "cols": ["State", "People"], "rows": out,
            "head": ["Scope", "Leader"],
            "bulk": {"href": url_for("admin_reminders"), "label": "Remind them",
                     "note": "Remind the leaders still to lock."} if n_open else None,
            "empty": "No scope locks this cycle."}


@admin_list("bu-kpi-holders", "pm")
def _list_bu_kpi_holders(db, me, vc, args):
    """BU KPI setup's "N carry it" (Chris, 2026-10-23: "admin click the 32 carry it should pop out a right panel to show
    who are these 32 ppl"): the unit's people taking part who hold the KPI on the active cycle's scorecard, by its
    folded name, the same read as the count (_bu_kpi_facts). ?bg= &co= &kpi=."""
    bg, co, kpi = args.get("bg") or "", args.get("co") or "", args.get("kpi") or ""
    act = active_cycle(db)
    if not (bg and co and kpi and act) or not can_access(me, bg, co):
        abort(404)
    # the unit's people with a line of that name, plus the guests from other units whose line is linked to this unit's setup of it
    # (2026-11-07), once each; a line of someone in the unit that is linked to ANOTHER unit's setup is that unit's, not listed here
    rows = db.execute(
        "SELECT u.*, t.weightage AS w, t.bu_kpi_id, t.unit AS kunit, %s FROM pm_kpi_targets t JOIN users u ON "
        "u.id=t.subject_id WHERE t.cycle_id=? AND u.business_group=? AND u.role!='admin' AND "
        "COALESCE(u.is_demo,0)=0 AND lower(t.kpi_name)=lower(?) AND %s AND ("
        "(u.company=? AND (t.bu_kpi_id IS NULL OR t.bu_kpi_id IN (SELECT id FROM pm_bu_kpis WHERE business_group=? AND company=?)"
        " OR t.bu_kpi_id NOT IN (SELECT id FROM pm_bu_kpis))) OR "
        "(u.company!=? AND t.bu_kpi_id IN (SELECT id FROM pm_bu_kpis WHERE cycle_id=? AND business_group=? AND company=?))) "
        "ORDER BY u.full_name"
        % (", ".join("t." + c for c in _BU_SCALE_COLS), participant_sql("u", "pm")),
        (act["id"], bg, " ".join(kpi.split()), co, bg, co, co, act["id"], bg, co)).fetchall()

    def scale(r):
        if r["rate1"] is not None and r["rate5"] is not None:
            return "%g to %g" % (r["rate1"], r["rate5"])
        if r["target"] is not None:
            return "Target %g" % r["target"]
        return ""
    unit = display_company(bg, co) or co
    return {"kicker": "BU KPI setup · %s" % unit, "title": "%s · %d carry it" % (kpi, len(rows)),
            "sub": "Taking part in %s with it on their scorecard. Their own target and weight until the unit's is saved."
                   % act["name"],
            "full": url_for("admin_bu_kpis", fbg=bg, fbu=co), "cols": [("W", "Weight"), ("Target", "Target now")], "widths": [9, 33],
            # a guest (their unit is not this one) carries the outlined "From <their unit>" chip of the BU KPI card (2026-11-07), so "4 + 1" reads
            "rows": [dict(_list_row(r, "performance", [("%g%%" % r["w"] if r["w"] is not None else "", ""),
                                                       ((scale(r) + (" " + r["kunit"] if r["kunit"] else "")).strip()
                                                        + (" · the unit's" if r["bu_kpi_id"] else " · their own"), "")]),
                          **({"chip": "From %s" % (display_company(r["business_group"], r["company"]) or r["company"]),
                              "chip_title": "Works in %s, another unit of the group" % (display_company(r["business_group"], r["company"]) or r["company"])}
                             if (r["company"] or "") != co else {}))
                     for r in rows],
            "empty": "Nobody in %s carries it on %s." % (unit, act["name"])}


@admin_list("kpi-lib-people", "pm")
def _list_kpi_lib_people(db, me, vc, args):
    """A named-people library row's "N people can pick it": the people it names who still match it (active, in the row's
    business group). ?lib=<library id>."""
    try:
        lib = db.execute("SELECT * FROM pm_kpi_library WHERE id=?", (int(args.get("lib") or 0),)).fetchone()
    except ValueError:
        lib = None
    if not lib:
        abort(404)
    rows = db.execute("SELECT u.* FROM pm_kpi_library_people p JOIN users u ON u.id=p.user_id WHERE p.library_id=? AND "
                      "u.left_at IS NULL AND u.business_group=? ORDER BY LOWER(u.full_name)",
                      (lib["id"], lib["business_group"])).fetchall()
    return {"kicker": "KPI library · named people", "title": "%s · %d can pick it" % (lib["kpi_name"], len(rows)),
            "sub": "Active people in %s whom the KPI names. Nobody else is offered it." % display_bg(lib["business_group"]),
            "full": url_for("admin_kpi_library", kpi=_kpi_key(lib["kpi_name"]), panel="kpi"), "cols": [], "widths": [],
            "rows": [_list_row(r, "performance", []) for r in rows], "empty": "Nobody it names is active in the group now."}


@admin_list("chart-lines", "pm")
def _list_chart_lines(db, me, vc, args):
    """The Chart panel's "Lines with this code": the people holding a line, on the usage cycle, that reads as one chart
    node (the same read as the count, _chart_cycle_lines). ?node=<node id> &bg=<business group, optional>."""
    try:
        nid = int(args.get("node") or 0)
    except ValueError:
        nid = 0
    idx = _chart_index(db)
    node = idx["nodes"].get(nid)
    cyc = _kpi_usage_cycle(db)
    if not node or node["level"] not in ("kpi", "variant") or not cyc:
        abort(404)
    bg = args.get("bg") or ""
    held = {}
    for ln, nd in _chart_cycle_lines(db, cyc["id"], idx, _chart_aliases(db)):
        if nd and nd["id"] == nid and (not bg or (ln["business_group"] or "") == bg):
            held.setdefault(ln["subject_id"], []).append(ln["kpi_name"])
    users = []
    ids = list(held)
    for i in range(0, len(ids), 500):
        part = ids[i:i + 500]
        users += db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part).fetchall()
    users.sort(key=lambda r: (r["full_name"] or "").lower())
    return {"kicker": "Chart of KPI · %s %s" % (node["code"], "variant" if node["level"] == "variant" else "KPI"),
            "title": "%s %s · %d %s" % (node["code"], node["name"], len(users), "person" if len(users) == 1 else "people"),
            "sub": "Holding a line that reads as this code on %s%s. Each line keeps its own name." % (
                cyc["name"], " in " + display_bg(bg) if bg else ""),
            "full": url_for("admin_kpi_library", view="chart"), "cols": ["As written"], "widths": [42],
            "rows": [_list_row(r, "performance", [("; ".join(dict.fromkeys(held[r["id"]])), "clip")]) for r in users],
            "empty": "Nobody holds a line with this code on %s." % cyc["name"]}


@admin_list("band-rule-people", "pm")
def _list_band_rule_people(db, me, vc, args):
    """Scoring's band rules: the people one rule reaches ("38" on its row). ?bg= &rule=. The same read as the count
    (_band_rule_people: the department's people, or the whole unit's minus the departments that hold a rule of their own,
    plus the people the rule names, each tagged "Named" -- 2026-11-02)."""
    bg = args.get("bg") or ""
    r = db.execute("SELECT * FROM pm_cycle_band_rules WHERE id=? AND business_group=?", (_band_int(args.get("rule")), bg)).fetchone()
    if not r or not can_access(me, bg, r["company"]):
        abort(404)
    rule = _band_rule_load(db, r["cycle_id"], bg, r["id"])
    places = rule["places"]
    dept_ids, named_ids = _band_rule_reach(db, r["cycle_id"], bg, r["company"], places, r["id"])
    named_set = set(named_ids)
    rows = []
    for part in _band_chunks(dept_ids + named_ids):
        rows += db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part).fetchall()
    rows.sort(key=lambda x: ((x["department"] or ""), x["full_name"] or ""))
    unit = display_company(bg, r["company"]) or r["company"]
    # a named person reads their own rule wherever they work in the unit, so they are tagged (the department people are not)
    named_all = {x[0] for x in db.execute("SELECT user_id FROM pm_cycle_band_rule_people WHERE rule_id=?", (r["id"],))}
    return {"kicker": "Scoring \u00b7 %s" % display_bg(bg),
            "title": "%s \u00b7 %d %s" % (_band_rule_words(bg, unit, places, shown=True, named=rule["eids"]), len(rows),
                                         "person" if len(rows) == 1 else "people"),
            "sub": "Their KPI results read against this rule's bands.",
            "full": url_for("admin_performance_config", bg=bg), "cols": [],
            "rows": [dict(_list_row(x, "performance", []), tag="Named" if x["id"] in named_all else "") for x in rows],
            "empty": "Nobody works there right now."}


def _bu_cal_cells(db, rows, held_names=None):
    """The Calibrator cell of each person (Chris, 2026-10-28: "once calibrator group is set, and we have a filter to select
    the calibrator group, and the name list shown should have a column to indicate who is calibrating this person"):
    {user id: (text, tone, hover)} and {user id: [their calibrators]}. Their calibrators' names, joined with " + "
    (hover: the panel too); else, with `held_names`, the unit's BU CEO and "(BU CEO)"; else Vacant. One read of the
    calibrators' names for the whole list."""
    gs_of = {r["id"]: bu_groups_of_person(db, r) for r in rows}
    ids = sorted({g["calibrator_id"] for gs in gs_of.values() for g in gs if g.get("calibrator_id")})
    name_of = {r[0]: r[1] for r in db.execute("SELECT id, full_name FROM users WHERE id IN (%s)" % ",".join("?" * len(ids)),
                                              ids)} if ids else {}
    cells = {}
    for r in rows:
        gs = gs_of[r["id"]]
        if gs:
            names = " + ".join(name_of.get(g.get("calibrator_id")) or g["name"] for g in gs)
            pans = []
            for g in gs:
                pn = (bu_panel(db, g.get("panel_id")) or {}).get("name") or g["name"]
                if pn not in pans:
                    pans.append(pn)
            cells[r["id"]] = (names, "clip", "%s · %s" % (names, " + ".join(pans)))
        elif held_names:
            t = "%s (BU CEO)" % held_names
            cells[r["id"]] = (t, "clip", t)
        else:
            cells[r["id"]] = ("Vacant", "none", "Nobody calibrates this person")
    return cells, gs_of


def _bu_join_and(parts):
    return parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " and " + parts[-1]


def _bu_unit_note(held, left, panel_counts):
    """What the unit's side panel says about who calibrates it: the BU CEO's, the panels' (name as stored, count each, in
    the page's order) and the people nobody does (2026-10-28: it said "Nobody calibrates this unit yet" over a unit whose
    198 people sit in a panel)."""
    if not panel_counts:
        return "Who calibrates this unit." if held else "Nobody calibrates this unit yet."
    if held:
        first = "The BU CEO calibrates the %s in no panel." % ("%d %s" % (left, "person" if left == 1 else "people"))\
            if left else "The BU CEO calibrates nobody here: everyone is in a panel."
        ps = [("%d %s the %s" % (n, "is in" if n == 1 else "are in", nm)) if i == 0 else "%d in the %s" % (n, nm)
              for i, (nm, n) in enumerate(panel_counts)]
        return "%s %s." % (first, _bu_join_and(ps))
    counts = ", ".join("%d in %s" % (n, nm) for nm, n in panel_counts)
    if not left:
        return "Calibration panels cover everyone here: %s." % counts
    return "%s; nobody calibrates the other %d yet." % (counts, left)


_BU_PEOPLE_SQL = ("role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0")


@admin_list("bu-people", "leaders", all_admins=True)
def _list_bu_people(db, me, vc, args):
    """Leaders > BU CEOs: a unit's row opens the people in it (Chris, 2026-10-27: "make the BU row here clickable and open
    a side panel to show the people in the BU, their name, department, JG, and job title ... click change will go to the
    BUCEO setting"). The same rule as the page's People column (admin_leaders: active, not an admin, not a demo), so the
    count here is that number. ?bg= &co=. The Change button is drawn only where the page's own Change would be.
    2026-10-28: a Calibrator column ("once calibrator group is set, and we have a filter to select the calibrator group,
    and the name list shown should have a column to indicate who is calibrating this person"; the heading's own filter
    selects one), and the note says what the panels cover, by the page's own resolver (bu_groups_of_person)."""
    bg, co = args.get("bg") or "", args.get("co") or ""
    if not (bg and co) or not can_access(me, bg, co):
        abort(404)
    rows = db.execute("SELECT * FROM users WHERE business_group=? AND company=? AND %s "
                      "ORDER BY LOWER(TRIM(COALESCE(department,''))), LOWER(full_name)" % _BU_PEOPLE_SQL,
                      (bg, co)).fetchall()
    held = [r for (b_, c_), r in buceo_holders(db, bg).items() if c_ == co]
    unit = display_company(bg, co) or co
    ceo = " and ".join("%s (%s)" % (r["full_name"], r["employee_id"]) for r in held)
    cal, gs_of = _bu_cal_cells(db, rows, " + ".join(r["full_name"] for r in held))
    out, counts = [], {}
    for r in rows:
        row = _list_row(r, "overview", [(proper_name(r["department"] or ""), "clip"),
                                        (str(r["job_grade"]) if r["job_grade"] is not None else "", ""),
                                        (proper_name(r["job_title"] or ""), "clip"), cal[r["id"]]])
        row["eid_only"] = True
        out.append(row)
        gs = gs_of[r["id"]]
        if gs:   # the page's in_grp: under the FIRST calibrator's panel
            counts[gs[0].get("panel_id")] = counts.get(gs[0].get("panel_id"), 0) + 1
    # panels in the page's order (name, then id); a calibrator with no panel is named for itself
    def pname(pid):
        return (bu_panel(db, pid) or {}).get("name") or next(
            (gs[0]["name"] for gs in gs_of.values() if gs and gs[0].get("panel_id") == pid), "a calibrator")
    panel_counts = sorted(((pname(pid), n) for pid, n in counts.items()), key=lambda x: (x[0].lower(), x[1]))
    left = len(rows) - sum(counts.values())
    lst = {"kicker": "BU CEOs · %s" % (display_bg(bg) or bg),
           "title": "%s · %s %s" % (unit, format(len(rows), ","), "person" if len(rows) == 1 else "people"),
           "sub": ("BU CEO: %s" % ceo) if ceo else "BU CEO: Vacant",
           "full": url_for("admin_users", view="list", fbg=bg, fbu=co), "no_bu": True,
           "head": ["Person"], "cols": [("Dept", "Department"), "JG", "Job title", ("Calibrator", "Who calibrates them at BU level")],
           "widths": [15, 8, 18, 19], "rows": out,
           "empty": "Nobody is in %s right now." % unit}
    note = _bu_unit_note(bool(held), left, panel_counts)
    if not _seat_scope_error(me, "buceo", bg, co):
        lst["action"] = {"label": "Change BU CEO" if held else "Set the BU CEO", "panel": "bu-" + _org_anchor_slug(co),
                         "note": note}
    else:
        lst["info"] = note
    return lst


@admin_list("bu-panel-people", "leaders", all_admins=True)
def _list_bu_panel_people(db, me, vc, args):
    """Leaders > BU CEOs: a calibration panel's line opens the people it covers (Chris, 2026-10-28: "CHCE Finance should
    become clickable and i can click it to open the side panel to see who are the 29 people in this list"). The page's
    own count (admin_leaders: the people whose FIRST calibrator is in this panel), narrowed to the units the admin may
    see, and to one unit with ?co=. ?bg= &pid= [&co=]."""
    bg, co = args.get("bg") or "", args.get("co") or ""
    p = bu_panel(db, args.get("pid"))
    if not bg or not p or p["business_group"] != bg or not can_access_bg(me, bg) or (co and not can_access(me, bg, co)):
        abort(404)
    rows = db.execute("SELECT * FROM users WHERE business_group=? AND " + _BU_PEOPLE_SQL + (" AND company=?" if co else "")
                      + " ORDER BY LOWER(company), LOWER(TRIM(COALESCE(department,''))), LOWER(full_name)",
                      ((bg, co) if co else (bg,))).fetchall()
    mine = []
    for r in rows:
        if not can_access(me, bg, r["company"]):
            continue
        gs = bu_groups_of_person(db, r)
        if gs and gs[0].get("panel_id") == p["id"]:
            mine.append(r)
    cal, _gs = _bu_cal_cells(db, mine)
    out = []
    for r in mine:
        row = _list_row(r, "overview", [(proper_name(r["department"] or ""), "clip"),
                                        (str(r["job_grade"]) if r["job_grade"] is not None else "", ""), cal[r["id"]]])
        row["eid_only"] = True
        out.append(row)
    curve = display_company(bg, p["company"]) or p["company"] or ""
    lst = {"kicker": "BU CEOs · %s" % (display_bg(bg) or bg),
           "title": "%s · %s %s" % (p["name"], format(len(mine), ","), "person" if len(mine) == 1 else "people"),
           "sub": "Curve: %s's PAT%s" % (curve, (" · in %s" % (display_company(bg, co) or co)) if co else ""),
           "full": url_for("admin_leaders", bg=bg, tab="buceo") + "#bu-panel-%d" % p["id"],
           "cols": [("Dept", "Department"), "JG", ("Calibrator", "Who calibrates them at BU level")],
           "widths": [14, 8, 20], "rows": out, "empty": "Nobody is in %s right now." % p["name"]}
    if is_super(me) or admin_can_item(me, "leaders.calib_groups"):
        lst["action"] = {"label": "Manage panel", "panel": "bp-%d" % p["id"], "note": "Who calibrates them, and their weights."}
    return lst


@app.route("/admin/list/<key>")
@admin_required
def admin_list_view(key):
    """The people behind one admin count, for the list panel (?fragment=1); without it, the count's full page.
    The super admin's only for now (Chris, 2026-10-20, asked who may use it: "Super admin only for now", until the
    Roles & access tab is built): a BG or unit admin's count keeps its link to the full page, as before."""
    spec = ADMIN_LISTS.get(key)
    if not spec:
        abort(404)
    if not spec.get("all_admins") and not is_super(current_user()):
        abort(403)   # the module's read was checked by admin_required; the rest stay the super admin's
    db = get_db()
    lst = spec["build"](db, current_user(), viewed_cycle_id(db), request.args)
    if not request.args.get("fragment"):
        return redirect(lst["full"])
    if lst.get("template"):   # a list that is not a table of people (Email › Schedule's day panel): its own partial
        return render_template(lst["template"], lst=lst, key=key)
    # a panel holds the first LIST_ROWS_SHOWN; the title keeps the whole count and the full page has everyone
    lst["n"] = len(lst["rows"])
    lst["more"] = max(0, lst["n"] - LIST_ROWS_SHOWN)
    lst["rows"] = lst["rows"][:LIST_ROWS_SHOWN]
    sp = lst.get("search")
    if sp:   # a list with Search in (Email › Sent's runs and notices): its menu, read as every page of people reads it
        q, qin, menu = people_search_args(sp["extra"], src=request.args)
        sp["menu"] = {k: menu[k] for k in sp["fields"]}
        sp["menu"]["all"] = (sp["menu"]["all"][0], sp["all_ph"], sp["menu"]["all"][2])
        sp["q"], sp["qin"] = q, (qin if qin in sp["menu"] else "all")
    return render_template("_people_list_panel.html", lst=lst, key=key)


