def _principles_export_name(db, cyc, fbgs, fcompanies):
    """ChinHinLeadershipPrinciple_<BG>_<BU>_<cycle>.html

    Several picks collapse to a count rather than a concatenation: four unit
    names produce a filename nobody can read or search for. Same shape
    admin_export_report_pdf() already uses for its company token.
    """
    slug = lambda t: re.sub(r"[^A-Za-z0-9]+", "_", str(t)).strip("_")
    bg = "AllBGs" if not fbgs else (slug(fbgs[0]) if len(fbgs) == 1 else f"{len(fbgs)}_BGs")
    bu = "AllBUs" if not fcompanies else (
        slug(display_company(fbgs[0] if fbgs else "", fcompanies[0]))
        if len(fcompanies) == 1 else f"{len(fcompanies)}_BUs")
    return f"ChinHinLeadershipPrinciple_{bg}_{bu}_{slug(cyc['name'])}.html"


@app.route("/admin/export/principles.html")
@admin_required
def admin_export_principles():
    """The same report as a standalone HTML file.

    Deliberately INDEPENDENT of whatever the page is currently filtered to
    (confirmed): what an admin is reading and what they send to management are
    different questions, so scope comes only from this request's own arguments.

    Every argument is re-validated against what the caller may actually see --
    the same defence-in-depth admin_export_report_pdf() applies -- so a
    hand-edited query string cannot widen the export.
    """
    db = get_db()
    me = current_user()
    cid = request.args.get("cycle", type=int) or viewed_cycle_id(db)
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone()
    if not cyc:
        abort(400)

    # only the groups this caller may see (2026-11-11): a spoofed ?bg= for another group is dropped here, and the context
    # refuses it again
    valid_bgs = [b for b in org_bgs(db) if can_access_bg(me, b)]
    fbgs = [b for b in valid_bgs if b in set(request.args.getlist("bg"))]
    # Units are validated against the population of the chosen BGs, not against
    # a free-text list, so a spoofed unit name is simply dropped.
    probe = _principles_report_context(db, me, cid, fbgs or None)
    valid_bus = {r["bu"] for r in probe["rows"] if r["bu"]}
    fcompanies = [c for c in request.args.getlist("bu") if c in valid_bus]
    valid_jgs = {r["jg"] for r in probe["rows"]}
    fgrades = [g for g in request.args.getlist("jg") if g in valid_jgs]

    ctx = _principles_report_context(db, me, cid, fbgs or None,
                                     fcompanies or None, fgrades or None)
    html = render_template("principles_report_standalone.html",
                           ctx=ctx, cyc=cyc, standalone=True,
                           generated_by=me["full_name"],
                           generated_at=_now_myt().strftime("%d %b %Y, %H:%M"))
    # a BG or unit admin's file holds their own group only: name it after that group, never "AllBGs" (2026-11-11)
    fname = _principles_export_name(db, cyc, fbgs or ([admin_bg_of(me)] if admin_bg_of(me) else []), fcompanies)
    log_activity(db, me["id"], "export",
                 f"{fname} ({len(ctx['rows'])} people)")
    return Response(html, mimetype="text/html",
                    headers={"Content-Disposition": _attachment_header(fname)})


@app.route("/admin/export/report.pdf")
@admin_required
def admin_export_report_pdf():
    db = get_db()
    me = current_user()
    vc = viewed_cycle_id(db)
    cyc = viewed_cycle(db)
    tiers = effective_tiers(cyc)
    is_sup = is_super(me)
    fbg = (request.args.get("fbg", "").strip() if is_sup else (admin_bg_of(me) or ""))
    if not fbg:
        abort(400)

    # Valid companies = the exact same population-derived set the picker/
    # modal offers, already bg_scope()-gated by caller identity -- so a
    # spoofed `company=` param for a company outside the caller's access is
    # simply filtered out here, same defense-in-depth already used for the
    # page's own Company picker options.
    uwhere_a, uparams_a, _pw, _pp = _report_scope(me, fbg, "")
    subjects_a = _report_population(db, vc, uwhere_a, uparams_a)
    valid = sorted({s["company"] for s in subjects_a if s["company"]})
    requested = set(request.args.getlist("company"))
    companies = [c for c in valid if c in requested]
    if not companies:
        abort(400)

    pdf_bytes = _report_pdf_bytes(db, vc, cyc, tiers, me, fbg, companies)
    log_activity(db, me["id"], "export", "report.pdf")
    slug = lambda s: re.sub(r"[^A-Za-z0-9]+", "_", s).strip("_")
