@app.route("/admin/import", methods=["GET", "POST"])
@admin_required
def admin_import():
    """360 feedback > Panels > Import panels: subject, assessor and relationship per row, for the active cycle. In four
    steps since 2026-10-26 (file, quality, what it changes and the super admin's answers, the final preview and Apply:
    _imp_post), all or nothing (_panel_import_check). A post without the steps changes nothing (_imp_steps_only)."""
    db = get_db()
    if request.method == "POST":
        me = current_user()
        if (request.form.get("token") or "").strip():
            return _imp_post("panels", db, me)
        # Imports build the active cycle's panels; past cycles are read-only.
        if not require_active_cycle():
            return redirect(url_for("admin_import"))
        if request.form.get("preview") == "1":
            return _imp_upload("panels", db, me, {"replace": bool(request.form.get("replace_existing"))})
        return _imp_steps_only("admin_import")
    me = current_user()
    v, done = _imp_get("panels", db, me)
    return render_template("admin_import.html", v=v, done=done, is_super=is_super(me))


