DATA_CHECKS_BY_KEY = {c["key"]: c for c in DATA_CHECKS}
DATA_CHECK_GROUPS = ["Panels", "Reports", "Roster", "Org structure", _DC_AFTER]


def _data_check_source(chk):
    """A check's inner SELECT. A Python check (`py`) hands its rows over as ONE bound JSON value (:py_rows), which this
    reads back as the same (eid, name, bg, bu, detail) columns: scoping, counting and the cap stay in one place."""
    if chk.get("py"):
        return ("SELECT json_extract(j.value, '$.eid') AS eid, json_extract(j.value, '$.name') AS name, "
                "json_extract(j.value, '$.bg') AS bg, json_extract(j.value, '$.bu') AS bu, "
                "json_extract(j.value, '$.detail') AS detail FROM json_each(:py_rows) j")
    return chk["sql"]


def _data_check_args(db, chk, cid):
    """The named parameters one check needs beyond the shared bag: a Python check's rows, worked out here."""
    if chk.get("py"):
        return {"py_rows": json.dumps(chk["py"](db, cid) if cid else [])}
    return {}


def _data_check_sql(chk, me, count_only, fbg="", fbu="", cap=True):
    """Wrap a check's SELECT so scoping and counting happen in ONE place.

    Every check returns the same (eid, name, bg, bu, detail) shape, so the scope
    filter applies to the wrapper rather than to seventeen different WHERE
    clauses -- and the landing-page count is literally the drill-down query with
    a COUNT around it, so the number and the list cannot disagree."""
    inner = "SELECT * FROM (%s)" % _data_check_source(chk)
    args, where = {}, []
    mine = admin_bg_of(me)
    if mine:
        where.append("bg = :my_bg")
        args["my_bg"] = mine
        comps = admin_companies_of(me)
        if comps:   # a unit-scoped sub-admin: their units only (the admin review, 2026-10-13 -- it listed the whole BG)
            where.append("bu IN (%s)" % ",".join(":c%d" % i for i in range(len(comps))))
            args.update({"c%d" % i: c for i, c in enumerate(comps)})
    # the page's business group / unit rows, in SQL BEFORE the cap (they ran on the capped list, so a filtered list
    # could miss most of its people)
    if fbg:
        where.append("COALESCE(bg, '') = :f_bg")
        args["f_bg"] = fbg
    if fbu:
        where.append("COALESCE(bu, '') = :f_bu")
        args["f_bu"] = fbu
    if where:
        inner += " WHERE " + " AND ".join(where)
    if count_only:
        return "SELECT COUNT(*) FROM (%s)" % inner, args
    if not cap:   # the CSV: every row, as the page promises
        return inner + " ORDER BY name", args
    return inner + " ORDER BY name LIMIT :cap", dict(args, cap=DATA_CHECK_ROW_CAP + 1)


def _data_check_params(db, cid):
    """The one bag of named parameters every check is handed. A check uses what
    it needs and ignores the rest."""
    return {"cid": cid, "target": panel_target() or _ba.NO_CAP, "min_valid": min_valid(),
            # not :cap -- _data_check_sql binds that name to the page's row limit; No maximum binds a bound nobody
            # reaches (2026-10-23)
            "assessor_cap": effective_assessor_cap(
                db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone() if cid else None) or _ba.NO_CAP}


def data_check_counts(db, me, cid):
    base = _data_check_params(db, cid)
    out = []
    for chk in DATA_CHECKS:
        sql, extra = _data_check_sql(chk, me, count_only=True)
        n = db.execute(sql, dict(base, **extra, **_data_check_args(db, chk, cid))).fetchone()[0]
        out.append(dict(chk, count=n))
    return out


DATA_CHECK_HEAD = ["Employee ID", "Name", "Business group", "Business unit", "Detail"]


def data_check_rows(db, me, cid, chk, fbg="", fbu="", cap=True):
    base = _data_check_params(db, cid)
    sql, extra = _data_check_sql(chk, me, count_only=False, fbg=fbg, fbu=fbu, cap=cap)
    rows = db.execute(sql, dict(base, **extra, **_data_check_args(db, chk, cid))).fetchall()
    if not cap:
        return rows, False
    capped = len(rows) > DATA_CHECK_ROW_CAP
    return rows[:DATA_CHECK_ROW_CAP], capped


_DATA_FIX_PAGE = {"admin_subjects": "360 People", "admin_users": "Users", "admin_panel_build": "Panels",
                  "admin_talent_release": "Release results", "admin_org": "Org structure",
                  "admin_leaders": "Leaders", "admin_bu_kpis": "BU KPI", "admin_performance_exceptions": "KPI exceptions",
                  "admin_participants": "Participants", "admin_competency_profiles": "Job profiles",
                  "admin_gradeh": "Grade H Appraisal"}


@app.route("/admin/data-integrity")
@admin_required
def admin_data_integrity():
    """Read-only. Finds and explains; never fixes."""
    db = get_db()
    me = current_user()
    cid = active_cycle_id(db)
    key = (request.args.get("check") or "").strip()
    if key and key not in DATA_CHECKS_BY_KEY:
        abort(404)      # a bogus key must not fall back to showing everything

    if key:
        chk = DATA_CHECKS_BY_KEY[key]
        # business group and unit as rows over the list (the admin table standard, 2026-10-11), the CSV following them;
        # applied in the query, before the page's cap, and the CSV is every row (2026-10-13)
        frows, fsel = admin_filter_rows(db, me, "admin_data_integrity", levels=2)
        rows, capped = data_check_rows(db, me, cid, chk, fsel["bg"] or "", fsel["bu"] or "",
                                       cap=request.args.get("format") != "csv")
        if request.args.get("format") in ("csv", "xlsx"):
            fname = _export_filename("data_%s" % key, me)
            log_activity(db, me["id"], "export", "%s (%d rows)" % (fname, len(rows)))
            db.commit()
            return _csv_response(fname, DATA_CHECK_HEAD, [(r["eid"], r["name"], r["bg"], r["bu"], r["detail"]) for r in rows])
        # each row opens the person's page, on the tab where the fix is (the admin review, 2026-10-11); an Employee
        # ID two people share opens Users searched for it instead
        eids = [r["eid"] for r in rows if r["eid"]]
        uid_of = {}
        for i in range(0, len(eids), 500):
            part = eids[i:i + 500]
            for r_ in db.execute("SELECT employee_id, MIN(id), COUNT(*) FROM users WHERE employee_id IN (%s) "
                                 "GROUP BY employee_id" % ",".join("?" * len(part)), part):
                uid_of[r_[0]] = r_[1] if r_[2] == 1 else None
        tab = chk.get("tab") or ("f360" if chk["fix_ep"] in ("admin_subjects", "admin_panel_build") else "overview")
        links = {r["eid"]: (url_for("admin_person", uid=uid_of[r["eid"]], tab=tab) if uid_of.get(r["eid"])
                            else url_for("admin_users", q=r["eid"], show="all")) for r in rows if r["eid"]}
        # a row that can be fixed here (canvas D2): the person's own details beside it, and departments to pick from
        fix = "lm" if key in DATA_FIX_LM else "dept" if key in DATA_FIX_DEPT else None
        info = {}
        if fix:
            ids = [v for v in uid_of.values() if v]
            for i in range(0, len(ids), 500):
                part = ids[i:i + 500]
                for r_ in db.execute("SELECT id, employee_id, department, job_title, job_grade FROM users WHERE id IN "
                                     "(%s)" % ",".join("?" * len(part)), part):
                    info[r_["employee_id"]] = dict(r_)
        dbgc, dbgp = bg_scope(me, "business_group")
        depts = [r_[0] for r_ in db.execute(
            "SELECT TRIM(department) d FROM users WHERE TRIM(COALESCE(department,''))!='' AND left_at IS NULL" + dbgc +
            (" AND business_group=?" if fsel["bg"] else "") + " GROUP BY d ORDER BY COUNT(*) DESC LIMIT 200",
            list(dbgp) + ([fsel["bg"]] if fsel["bg"] else []))] if fix == "dept" else []
        fix_href = url_for(chk["fix_ep"], **({k: v for k, v in (("fbg", fsel["bg"]), ("fbu", fsel["bu"])) if v}
                                             if chk["fix_ep"] == "admin_users" else {}))
        return render_template("admin_data_integrity.html", checks=None, check=chk, links=links, frows=frows,
                               fix=fix, info=info, depts=depts, fix_href=fix_href,
                               fix_allowed=_admin_nav_allowed({"ep": chk["fix_ep"]}, me),
                               fix_page=_DATA_FIX_PAGE.get(chk["fix_ep"], "the page"),
                               rows=rows, capped=capped, cap=DATA_CHECK_ROW_CAP,
                               groups=DATA_CHECK_GROUPS, cid=cid)

    checks = data_check_counts(db, me, cid)
    return render_template("admin_data_integrity.html", checks=checks, check=None,
                           rows=None, capped=False, cap=DATA_CHECK_ROW_CAP,
                           groups=DATA_CHECK_GROUPS, cid=cid,
                           total=sum(c["count"] for c in checks),
                           high=sum(c["count"] for c in checks if c["severity"] == "high"))


@app.route("/admin/people/find.json")
@admin_required
def admin_people_find():
    """The people picker (admin round 4, canvas D2/D3: a manager "by name, ID or job", not an Employee ID typed from
    memory): up to 12 active people in this admin's scope matching every word of ?q= on name, Employee ID, job title,
    department or unit, each with how many people they lead. Read only."""
    db = get_db()
    me = current_user()
    q = (request.args.get("q") or "").strip()
    if len(q) < 2:
        return jsonify({"people": []})
    # an L&D admin picks from every group (AI+ Learning, 2026-10-20): bg_scope would give them nobody
    where, params = ("", []) if is_lnd_admin(me) else bg_scope(me, "u.business_group")
    if (request.args.get("bg") or "").strip():   # one business group's people only (a BU group's picks, 2026-10-22)
        where, params = where + " AND u.business_group=?", list(params) + [request.args.get("bg").strip()]
    _units = [u_ for u_ in (request.args.get("units") or "").split("||") if u_.strip()]
    if _units:   # ...of these units only (a panel's calibrators, from the units ticked; 2026-10-26)
        where, params = (where + " AND u.company IN (%s)" % ",".join("?" * len(_units)),
                         list(params) + [u_.strip() for u_ in _units])
    # BU KPI card's "From another unit" (2026-11-07, canvas B2): ?xbu=<a saved BU KPI's id> narrows this to the people who could join it as a guest
    # (its business group, not its unit, taking part: the super admin's alone) and says, per person, why one cannot (`_bu_guest_refusal`, the
    # one check the writer runs). Read only; the writer still decides.
    xrow, xact = None, None
    if (request.args.get("xbu") or "").strip():
        xact = active_cycle(db)
        xrow = db.execute("SELECT * FROM pm_bu_kpis WHERE id=? AND cycle_id=?", (int(request.args["xbu"]) if request.args["xbu"].strip().isdigit() else 0,
                                                                              xact["id"] if xact else 0)).fetchone()
        if not (xrow and is_super(me)):
            return jsonify({"people": []})
        where, params = (where + " AND u.business_group=? AND u.company!=? AND COALESCE(u.company,'')!='' AND " + participant_sql("u", "pm"),
                         list(params) + [xrow["business_group"], xrow["company"]])
    conds, args = [], []
    for w in q.lower().split()[:4]:
        conds.append("(LOWER(u.full_name) LIKE ? OR LOWER(COALESCE(u.employee_id,'')) LIKE ? OR "
                     "LOWER(COALESCE(u.job_title,'')) LIKE ? OR LOWER(COALESCE(u.department,'')) LIKE ? OR "
                     "LOWER(COALESCE(u.company,'')) LIKE ? OR u.id IN (SELECT user_id FROM user_employee_ids "
                     "WHERE removed_at IS NULL AND lower(employee_id) LIKE ?))")   # ...or a linked Employee ID (2026-10-29)
        args += ["%" + w + "%"] * 6
    rows = db.execute(
        "SELECT u.id, u.employee_id, u.full_name, u.job_title, u.department, u.company, u.business_group, "
        "(SELECT COUNT(*) FROM users r WHERE r.manager_id=u.id AND r.left_at IS NULL AND r.role!='admin') leads, "
        "(SELECT COUNT(*) FROM users r WHERE r.hod_id=u.id AND r.left_at IS NULL AND r.role!='admin') heads "
        "FROM users u WHERE u.role!='admin' AND u.left_at IS NULL AND COALESCE(u.is_demo,0)=0 AND "
        + " AND ".join(conds) + where + " ORDER BY CASE WHEN LOWER(u.full_name) LIKE ? THEN 0 WHEN LOWER(u.full_name) "
        "LIKE ? THEN 1 WHEN LOWER(COALESCE(u.employee_id,''))=? THEN 0 ELSE 2 END, leads DESC, u.full_name LIMIT 12",
        args + list(params) + [q.lower() + "%", "%" + q.lower() + "%", q.lower()]).fetchall()
    out = [{"eid": r["employee_id"], "name": r["full_name"], "title": proper_name(r["job_title"] or ""),
            "dept": proper_name(r["department"] or ""),
            "unit": display_company(r["business_group"], r["company"]) or "",
            "leads": r["leads"], "heads": r["heads"]} for r in rows]
    if xrow is not None:   # what each would hold, and the writer's own words when they cannot join: ONE read of their lines and totals
        ppl = [dict(id=r["id"], employee_id=r["employee_id"]) for r in rows]
        tot = _bu_kpi_totals(db, xact, ppl) if ppl else {}
        held = {}
        for r in (db.execute("SELECT subject_id, kpi_name, focus FROM pm_kpi_targets WHERE cycle_id=? AND subject_id IN (%s)" % ",".join(
                "?" * len(ppl)), [xact["id"]] + [x["id"] for x in ppl]) if ppl else []):
            held.setdefault(r[0], set()).add(_kpi_key(kpi_line_base(r[1], r[2])))
        full = {}   # ONE batched read of the twelve (never a query per row)
        if rows:
            full = {x["id"]: x for x in db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(rows)),
                                                    [r["id"] for r in rows])}
        for r, o in zip(rows, out):
            n_, w_ = tot.get(ja_eid(r["employee_id"]), (0, 0.0))
            g_ = grade_num(full[r["id"]]["job_grade"])
            o.update(jg=("JG %s" % g_) if g_ is not None else "", kn="%d KPI%s" % (n_, "" if n_ == 1 else "s"), w=round(w_, 2),
                     room=round(max(0.0, 100 - w_), 2),
                     why=_bu_guest_refusal(db, me, xact, xrow, full[r["id"]], None, held.get(r["id"], set()), w_))
    return jsonify({"people": out})


# The checks a row can be fixed on (admin round 4, canvas D2: "Data integrity rows that fix in place").
DATA_FIX_LM = ("no_manager", "self_manager", "manager_left", "lm_below_min")
DATA_FIX_DEPT = ("no_department",)


@app.route("/admin/data-integrity/fix", methods=["POST"])
@admin_required
def admin_data_integrity_fix():
    """Fix flagged people where they are listed: a line manager for one row or every ticked row (through
    _apply_line_manager_change, as the person page does), or a department. Each person is checked against this admin's
    scope; each change is logged on their page. Back to the same list, with its filters."""
    db = get_db()
    me = current_user()
    key = request.form.get("check") or ""
    back = _admin_next(url_for("admin_data_integrity", check=key))
    if key not in DATA_FIX_LM + DATA_FIX_DEPT:
        abort(400)
    ids = []
    for v in request.form.getlist("uid"):
        try:
            ids.append(int(v))
        except ValueError:
            pass
    if not ids:
        flash("Tick at least one person.", "error")
        return back
    people = []
    for uid in ids:
        p = db.execute("SELECT * FROM users WHERE id=? AND role!='admin'", (uid,)).fetchone()
        _system_admin_refuse(me, p, db)   # (2026-10-28)
        if not p or not can_access(me, p["business_group"], p["company"]):
            abort(403)
        people.append(p)
    if key in DATA_FIX_LM:
        act = active_cycle(db)
        if not act:
            flash("There is no active cycle: the KPI lines that follow the line manager need one.", "error")
            return back
        eid = (request.form.get("lm_eid") or "").strip()
        mgr = db.execute("SELECT * FROM users WHERE employee_id=? AND role!='admin'", (eid,)).fetchone() if eid else None
        if not mgr or mgr["left_at"]:
            flash(("Nobody active has the Employee ID %s." % eid) if eid else "Pick the line manager first.", "error")
            return back
        done = []
        lm_batch = []   # one _line_changed for everyone ticked (2026-11-13)
        for p in people:
            if p["id"] == mgr["id"]:
                flash("%s can't be their own line manager: left as it is." % p["full_name"], "error")
                continue
            r = _apply_line_manager_change(db, p["id"], mgr["id"], act["id"], disposition="reassign",
                                           actor_id=me["id"], panel=False, batch=lm_batch)   # 360 panel as filed (2026-10-30)
            _leader_log(db, me["id"], "set_manager", "%s -> %s (from Data integrity)%s" % (
                p["full_name"], mgr["full_name"], ("; %d KPI line(s) moved" % r["kpi_moved"]) if r["kpi_moved"] else ""),
                p["id"])
            done.append(p["full_name"])
        fol = _line_changed(db, lm_batch, me["id"], bulk=True)
        db.commit()
        if done:
            flash("%s is now the line manager of %s.%s" % (mgr["full_name"], done[0] if len(done) == 1 else
                                                           "%d people" % len(done), (" " + " ".join(fol)) if fol else ""), "ok")
        return back
    # a department from the list (their business groups' own), or named as new (2026-10-19)
    _bgs = sorted({p["business_group"] for p in people if p["business_group"]})
    allowed = [r_[0] for r_ in db.execute(
        "SELECT TRIM(department) d FROM users WHERE TRIM(COALESCE(department,''))!='' AND left_at IS NULL AND "
        "business_group IN (%s) GROUP BY LOWER(d)" % (",".join("?" * len(_bgs)) or "''"), _bgs)]
    dept, _new, d_err = _admin_list_choice(request.form, "department", allowed)
    if d_err or not dept:
        flash(d_err or "Pick the department first.", "error")
        return back
    for p in people:
        db.execute("UPDATE users SET department=? WHERE id=?", (dept, p["id"]))
        log_activity(db, me["id"], "set_department", "%s: department set to %s (from Data integrity)"
                     % (p["full_name"], dept), target_user_id=p["id"])
    db.commit()
    flash("Department set to %s for %s." % (dept, people[0]["full_name"] if len(people) == 1
                                            else "%d people" % len(people)), "ok")
    return back


# Clear 360 panels in the four steps (2026-10-26), the super admin's: the super admin answers for each person whose
# raters have already submitted: clear their panel too (that feedback archived, restorable) or keep it.
def _cimp_load(db, me, meta, data):
    errors, subjects, seen = [], [], {}
    act = active_cycle(db)
    if not act:
        errors.append({"row": 0, "eid": "", "why": "There's no active cycle to clear panels in."})
    cid = act["id"] if act else 0
    n = 0
    recs = _read_records(meta["filename"], data)
    id_cols = ("employee id", "eid", "id", "staff id", "subject employee id", "subject id", "subject")
    # a linked Employee ID (2026-10-29) is another of the person's IDs: read under their main ID, one batched read
    resolved = _eid_resolve_many(db, [_pick(rec, *id_cols) for rec in recs])
    linked = []
    for i, rec in enumerate(recs, start=2):
        eid = _pick(rec, *id_cols)
        if not eid:
            continue
        got = resolved.get(eid)
        row, via = got if got and got[0]["role"] != "admin" else (None, False)
        key_ = row["id"] if row else eid
        if key_ in seen:
            if seen[key_] != eid:   # their main ID and a linked ID, or two linked IDs: one person twice
                errors.append({"row": i, "eid": eid, "why": _eid_same_person(seen[key_], eid, row) + "."})
            continue
        seen[key_] = eid
        n += 1
        if not row:
            errors.append({"row": i, "eid": eid, "why": "Unknown Employee ID '%s'." % eid})
            continue
        if via:
            linked.append({"row": i, "eid": eid, "rows": [i], "detail": "Row %d: %s" % (i, _eid_note(eid, row))})
        pend, subm = db.execute(
            "SELECT COALESCE(SUM(status!='submitted'), 0), COALESCE(SUM(status='submitted'), 0) FROM assignments "
            "WHERE subject_id=? AND cycle_id=? AND archived=0", (row["id"], cid)).fetchone()
        subjects.append({"row": i, "id": row["id"], "eid": row["employee_id"], "name": row["full_name"],
                         "pending": pend, "submitted": subm})
    if not n:
        errors.append({"row": 0, "eid": "", "why": "No Employee IDs found in the file: it needs an Employee ID column "
                                                   "with at least one ID."})
    look = {"linked": linked,
            "empty": [{"row": x["row"], "eid": x["eid"], "rows": [x["row"]], "detail": "%s has no panel to clear" %
                       x["eid"]} for x in subjects if not x["pending"] and not x["submitted"]]}
    return {"errors": errors, "rows": n, "subjects": subjects, "look": look, "act": act}


def _cimp_kept(x, decisions):
    return x["submitted"] and decisions.get("clear:" + x["eid"]) == "keep"


def _cimp_says(x, decisions):
    if not x["pending"] and not x["submitted"]:
        return "No panel: nothing to clear"
    if _cimp_kept(x, decisions):
        return "Panel kept as it is"
    return "%d not rated yet removed%s" % (x["pending"], (", %d given archived (restorable)" % x["submitted"])
                                           if x["submitted"] else "")


def _cimp_changes(db, me, ctx, decisions):
    sub = ctx["subjects"]
    tiles = [(sum(1 for x in sub if x["pending"] or x["submitted"]), "panels to clear", "#2f64d6"),
             (sum(x["pending"] for x in sub), "raters removed, not rated yet", "#e0a84a"),
             (sum(x["submitted"] for x in sub), "given feedback archived, restorable", "#9aa1b5")]
    sections = [{"title": "Each panel", "dl": "changes", "head": ["Person", "Not rated yet", "Given"],
                 "rows": [[(x["name"], x["eid"]), x["pending"], x["submitted"]] for x in sub[:15]],
                 "more": max(0, len(sub) - 15)}]
    asked = [x for x in sub if x["submitted"]]
    decide = [{"title": "Their raters have already given feedback (%d)" % len(asked),
               "why": "Clear it too: the feedback given is archived (the panel editor can restore it) and the rest "
                      "removed. Keep it: their panel stays as it is.",
               "options": [("clear", "Clear it too"), ("keep", "Keep it")],
               "head": ["Person", "Not rated yet", "Given"],
               "items": [{"key": "clear:" + x["eid"], "label": "%s (%s)" % (x["name"], x["eid"]),
                          "cells": [(x["name"], x["eid"]), x["pending"], x["submitted"]]} for x in asked]}] if asked else []
    return {"tiles": tiles, "sections": sections, "decide": decide,
            "fp": [(x["eid"], x["pending"], x["submitted"]) for x in sub]}


def _cimp_after(db, me, ctx, decisions):
    sub = ctx["subjects"]
    go = [x for x in sub if (x["pending"] or x["submitted"]) and not _cimp_kept(x, decisions)]
    kept = [x for x in sub if _cimp_kept(x, decisions)]
    removed, archived = sum(x["pending"] for x in go), sum(x["submitted"] for x in go)
    tiles = [(len(go), "panels cleared", "#2f64d6"), (removed, "removed", "#e0a84a"), (archived, "archived", "#9aa1b5")]
    if kept:
        tiles.append((len(kept), "kept as they are", "#9aa1b5"))
    return {"lede": "%d %s in the file." % (len(sub), "person" if len(sub) == 1 else "people"), "tiles": tiles,
            "table_title": "Each panel after the import", "head": ["Person", "What happens"],
            "rows": [[(x["name"], x["eid"]), _cimp_says(x, decisions)] for x in sub[:30]],
            "more": max(0, len(sub) - 30),
            "confirm": "Clear %d panel%s in %s? %d rater%s not rated yet removed and %d given archived (the panel "
                       "editor can restore them)%s. The backup taken first is the way back." % (
                           len(go), "" if len(go) == 1 else "s", ctx["act"]["name"], removed,
                           "" if removed == 1 else "s", archived,
                           (", %d kept as they are" % len(kept)) if kept else "")}


def _cimp_apply(db, me, ctx, decisions):
    cid = ctx["act"]["id"]
    deleted = archived = n = 0
    kept = []
    for x in ctx["subjects"]:
        if _cimp_kept(x, decisions):
            kept.append(x["eid"])
            continue
        archived += db.execute("UPDATE assignments SET archived=1, archived_at=datetime('now'), archived_by=?, "
                               "archive_reason=? WHERE subject_id=? AND cycle_id=? AND archived=0 AND "
                               "status='submitted'", (me["id"], "bulk panel clear", x["id"], cid)).rowcount
        deleted += db.execute("DELETE FROM assignments WHERE subject_id=? AND cycle_id=? AND archived=0 AND "
                              "status!='submitted'", (x["id"], cid)).rowcount
        n += 1
    db.commit()
    log_activity(db, me["id"], "clear_panels", "%d subject(s): %d pending deleted, %d submitted archived%s" % (
        n, deleted, archived, ("; the super admin kept %d (%s)" % (len(kept), ", ".join(kept[:40]))) if kept else ""))
    return {"summary": "Cleared %d panel%s: %d not rated yet removed, %d given archived (restorable from the panel "
                       "editor)." % (n, "" if n == 1 else "s", deleted, archived),
            "lines": ["%d kept as they were, as you answered." % len(kept)] if kept else []}


def _cimp_downloads(db, me, ctx, decisions, what):
    if what == "changes":
        return "changes", ["Employee ID", "Name", "Not rated yet", "Given"], [
            [x["eid"], x["name"], x["pending"], x["submitted"]] for x in ctx["subjects"]]
    return "final-preview", ["Employee ID", "Name", "What happens"], [
        [x["eid"], x["name"], _cimp_says(x, decisions)] for x in ctx["subjects"]]


_imp_register(
    "clear", page="admin_clear_panels", dl="admin_clear_panels_check", file="clear-panels", load=_cimp_load,
    changes=_cimp_changes, after=_cimp_after, apply=_cimp_apply, downloads=_cimp_downloads,
    look=(("linked", "ID matched through a linked ID", "IDs matched through a linked ID",
           "The file uses another of their IDs: the person is read under their main ID."),
          ("empty", "person has no panel", "people have no panel", "Nothing to clear for them."),),
    look_skips=("linked", "empty"),
    fix_kinds=(("Unknown Employee ID", r"Unknown Employee ID"), ("No Employee IDs", r"No Employee IDs"),
               ("The same person twice", r"same person"), ("No active cycle", r"active cycle")),
    checks=("an Employee ID nobody has, or a file with none, or the same person twice under two of their IDs.",
            "someone with no panel to clear, or an ID that is another of the person's IDs (a linked ID)."))


@app.route("/admin/clear-panels", methods=["GET", "POST"])
@super_required
def admin_clear_panels():
    """Bulk-empty the active cycle's assessor panel for a list of subjects.

    Super-admin only. Upload a file with one Employee ID column (the subjects).
    For each: PENDING assessors (no feedback) are deleted; SUBMITTED assessors
    are ARCHIVED (feedback preserved + restorable from the panel editor), so the
    operation never loses real feedback. All-or-nothing on unknown IDs. In four
    steps since 2026-10-26 (_imp_post); a post without them changes nothing (_imp_steps_only)."""
    db = get_db()
    me = current_user()
    if request.method == "POST" and (request.form.get("token") or "").strip():
        return _imp_post("clear", db, me)
    if request.method == "POST" and request.form.get("preview") == "1":
        if not require_active_cycle():
            return redirect(url_for("admin_clear_panels"))
        return _imp_upload("clear", db, me)
    if request.method == "POST":
        return _imp_steps_only("admin_clear_panels")

    v, done = _imp_get("clear", db, me)
    return render_template("admin_clear_panels.html", v=v, done=done, is_super=True)


@app.route("/admin/clear-panels/check/<token>.xlsx")
@super_required
def admin_clear_panels_check(token):
    """A kept clear-panels file's issues, each panel, or the final preview (_imp_download)."""
    return _imp_download("clear", get_db(), current_user(), token)


