# ---------------------------------------------------------------------------
# Admin: new accounts and bulk-set user passwords
# ---------------------------------------------------------------------------
def first_password(employee_id, id_digits=None):
    """(password, error): the password a NEW account is created with. This copy holds no password scheme (accounts and
    sign-in follow the main AI-HR app): the value is random and never shown or kept, so nobody can sign in with it
    until a password is set through a reset link or by an admin. Arguments are accepted and ignored."""
    return secrets.token_urlsafe(32), None


def _admin_password_set(db, me, tid, new_pw, first_only=False, clear_lock=False):
    """(ok, message): an admin sets a person's password, the one writer for People's Reset. A new password that passes
    _password_problem. `clear_lock` also clears their failed sign-ins on every browser, so they can sign in at once.
    Recorded as how their password was set, and in the audit log."""
    t = db.execute("SELECT id, username, full_name, employee_id, business_group, company, role, left_at FROM users "
                   "WHERE id=?", (tid,)).fetchone() if tid else None
    new_pw = (new_pw or "").strip()
    if tid and _system_admin_locked(me, tid, db):   # (2026-10-28)
        return False, SYSTEM_ADMIN_LOCK_MSG
    if not t or t["role"] == "admin" or not can_access(me, t["business_group"], t["company"]):
        return False, "You can't reset that user's password."
    bad = _password_problem(new_pw, t["employee_id"], t["username"], names=t["full_name"])
    if bad:
        return False, bad
    _pw_history_push(db, t["id"])   # an admin's path records the old hash, and never reads the history (2026-10-31)
    db.execute("UPDATE users SET password_hash=?, pw_source='admin', pw_set_at=datetime('now') WHERE id=?",
               (generate_password_hash(new_pw, method="pbkdf2:sha256"), t["id"]))
    _pw_close_resets(db, t["id"])   # an emailed link from before ends with the old password (2-06)
    if clear_lock:
        db.execute("DELETE FROM login_attempts WHERE username=?", (t["username"],))
    db.commit()
    log_activity(db, me["id"], "reset_pw", f"{t['full_name']} ({t['employee_id']}): password reset"
                 + ("; failed sign-ins cleared" if clear_lock else ""),
                 target_user_id=t["id"])
    return True, f"Password for {t['full_name']} set to the one you entered."


def _admin_account_password_set(db, me, aid, new_pw, label, clear_lock=False):
    """(ok, message): the super admin sets an ADMIN account's password (a BG admin, a sub-admin, an L&D admin), the one
    writer for those three (security test 2-09, 2026-10-31). _admin_password_set refuses admin accounts, so this is its
    admin-account twin: the same rule (_password_problem), recorded as set by an admin (pw_source, pw_set_at, which also
    ends the account's open sessions and every unused reset link) and on the password trail against the account, with
    the admin who did it as the actor. `label` names the kind of admin on the Audit log. A system admin's account is
    changed by a system admin only."""
    t = db.execute("SELECT id, username, role FROM users WHERE id=?", (aid,)).fetchone() if aid else None
    if aid and _system_admin_locked(me, aid, db):   # (2026-10-28)
        return False, SYSTEM_ADMIN_LOCK_MSG
    if not t or t["role"] != "admin":
        return False, "That admin account isn't open."
    new_pw = (new_pw or "").strip()
    bad = _password_problem(new_pw, t["username"])
    if bad:
        return False, bad
    _pw_history_push(db, t["id"])
    db.execute("UPDATE users SET password_hash=?, pw_source='admin', pw_set_at=datetime('now') WHERE id=?",
               (generate_password_hash(new_pw, method="pbkdf2:sha256"), t["id"]))
    _pw_close_resets(db, t["id"])
    if clear_lock:
        db.execute("DELETE FROM login_attempts WHERE username=?", (t["username"],))
    db.commit()
    _pw_trail(db, t["id"], "reset_pw", "%s (%s): password reset" % (t["username"], label), by=me["id"])
    return True, "Password for %s updated." % t["username"]


# Set passwords in the four steps (2026-10-26), the super admin's. A password file is never kept: at step 1 each password
# becomes its hash (what Apply writes), and only the hashes wait for the later steps. The super admin answers for each
# person who has signed in before: replace their password, or leave it.
def _pimp_stage(db, me, filename, data, opts):
    rows = []
    for i, rec in enumerate(_read_records(filename, data), start=2):
        eid = _pick(rec, "employee id", "eid", "id", "staff id", "employee no")
        pw = _pick(rec, "password", "new password", "pwd", "pass")
        if not eid and not pw:
            continue
        rows.append({"row": i, "eid": eid, "hash": generate_password_hash(pw, method="pbkdf2:sha256") if pw else None})
    return json.dumps(rows).encode()


def _pimp_load(db, me, meta, data):
    errors, valid, seen = [], [], {}
    rows = json.loads(data.decode() or "[]")
    # a linked Employee ID (2026-10-29) is another of the person's IDs: the password goes to the person under their main ID
    found = {k: (dict(u), via) for k, (u, via) in _eid_resolve_many(db, [r["eid"] for r in rows if r["eid"]]).items()
             if u["role"] != "admin"}
    signed = {r[0] for r in _rpt_ids(db, "SELECT DISTINCT user_id FROM activity_log WHERE action='login' AND user_id "
                                         "IN (%s)", {u["id"] for u, _v in found.values()})}
    for r in rows:
        err = lambda why: errors.append({"row": r["row"], "eid": r["eid"] or "", "why": why})  # noqa: E731
        got = found.get(r["eid"]) if r["eid"] else None
        key_ = got[0]["id"] if got else r["eid"]
        if not r["eid"]:
            err("A row has a password but no Employee ID.")
        elif not r["hash"]:
            err("%s: no password in the file." % r["eid"])
        elif key_ in seen:
            if seen[key_] == r["eid"]:
                err("%s: appears more than once in the file." % r["eid"])
            else:   # their main ID and a linked ID, or two linked IDs: one person twice
                err("%s: the file has two passwords for them." % _eid_same_person(seen[key_], r["eid"], got[0]))
        elif not got:
            err("%s: no matching user." % r["eid"])
        else:
            u, via = got
            valid.append(dict(r, eid=u["employee_id"], file_eid=r["eid"], via=via, user_id=u["id"], name=u["full_name"],
                              signed=u["id"] in signed, source=u["pw_source"], left=bool(u["left_at"])))
        if r["eid"]:
            seen.setdefault(key_, r["eid"])
    look = {"linked": [{"row": v["row"], "eid": v["file_eid"], "rows": [v["row"]],
                        "detail": "Row %d: %s is %s (main ID %s)" % (v["row"], v["file_eid"], v["name"], v["eid"])}
                       for v in valid if v["via"]],
            "left": [{"row": v["row"], "eid": v["eid"], "rows": [v["row"]],
                      "detail": "%s has left: their sign-in is closed" % v["eid"]} for v in valid if v["left"]]}
    if not rows:
        errors.append({"row": 0, "eid": "", "why": "That file has no rows to apply."})
    return {"errors": errors, "rows": len(rows), "valid": valid, "look": look}


_PW_SOURCE_WORDS = {"own": "one they chose", "admin": "set by an admin"}


def _pimp_how(v):
    return ("Has signed in; " if v["signed"] else "Never signed in; ") + _PW_SOURCE_WORDS.get(v["source"] or "",
                                                                                          "set before OneHR kept how")


def _pimp_says(v, decisions):
    if v["signed"] and decisions.get("pw:" + v["eid"]) == "leave":
        return "Left as it is"
    return "Password replaced: their other sign-ins end" if v["signed"] else "Password set"


def _pimp_changes(db, me, ctx, decisions):
    valid = ctx["valid"]
    asked = [v for v in valid if v["signed"]]
    tiles = [(len(valid), "password%s to set" % ("" if len(valid) == 1 else "s"), "#2f64d6"),
             (len(asked), "of them %s signed in before" % ("has" if len(asked) == 1 else "have"), "#e0a84a"),
             (len(valid) - len(asked), "never signed in", "#9aa1b5")]
    sections = [{"title": "Whose password changes", "note": "The passwords themselves are never shown or kept: only "
                 "their hashes wait for Apply.", "dl": "changes", "head": ["Person", "Their sign-in now"],
                 "rows": [[(v["name"], v["eid"]), _pimp_how(v)] for v in valid[:15]],
                 "more": max(0, len(valid) - 15)}]
    decide = [{"title": "They have signed in before (%d)" % len(asked),
               "why": "Replace it: the file's password is theirs from now on, and their other sign-ins end. Leave it: "
                      "they keep the password they use now.",
               "options": [("replace", "Replace it"), ("leave", "Leave it")], "head": ["Person", "Their sign-in now"],
               "items": [{"key": "pw:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                          "cells": [(v["name"], v["eid"]), _pimp_how(v)]} for v in asked]}] if asked else []
    return {"tiles": tiles, "sections": sections, "decide": decide,
            "fp": [(v["eid"], v["user_id"], v["signed"], v["source"]) for v in valid]}


def _pimp_after(db, me, ctx, decisions):
    valid = ctx["valid"]
    keep = [v for v in valid if _pimp_says(v, decisions) == "Left as it is"]
    n = len(valid) - len(keep)
    tiles = [(n, "password%s set" % ("" if n == 1 else "s"), "#2f64d6")]
    if keep:
        tiles.append((len(keep), "left as they are", "#9aa1b5"))
    return {"lede": "%d %s in the file." % (len(valid), "account" if len(valid) == 1 else "accounts"), "tiles": tiles,
            "table_title": "Each account after the import", "head": ["Person", "What happens"],
            "rows": [[(v["name"], v["eid"]), _pimp_says(v, decisions)] for v in valid[:30]],
            "more": max(0, len(valid) - 30),
            "confirm": "Set %d password%s from this file%s? Each is replaced at once, and anyone signed in elsewhere is "
                       "signed out there. The backup taken first is the way back." % (
                           n, "" if n == 1 else "s", (", leaving %d as they are" % len(keep)) if keep else "")}


def _pimp_apply(db, me, ctx, decisions):
    done, left = [], []
    for v in ctx["valid"]:
        if _pimp_says(v, decisions) == "Left as it is":
            left.append(v["eid"])
            continue
        _system_admin_refuse(me, v["user_id"], db)   # (2026-10-28)
        _pw_history_push(db, v["user_id"])
        db.execute("UPDATE users SET password_hash=?, pw_source='admin', pw_set_at=datetime('now') WHERE id=?",
                   (v["hash"], v["user_id"]))
        done.append(v["eid"])
    db.commit()
    log_activity(db, me["id"], "password_import", "%d password(s) set: %s%s%s" % (
        len(done), ", ".join(done[:40]), (" and %d more" % (len(done) - 40)) if len(done) > 40 else "",
        ("; the super admin left %d as they were (%s)" % (len(left), ", ".join(left[:40]))) if left else ""))
    return {"summary": "Passwords set for %d account%s." % (len(done), "" if len(done) == 1 else "s"),
            "lines": ["%d left as they were, as you answered." % len(left)] if left else []}


def _pimp_downloads(db, me, ctx, decisions, what):
    if what == "changes":
        return "changes", ["Employee ID", "Name", "Their sign-in now"], [
            [v["eid"], v["name"], _pimp_how(v)] for v in ctx["valid"]]
    return "final-preview", ["Employee ID", "Name", "What happens"], [
        [v["eid"], v["name"], _pimp_says(v, decisions)] for v in ctx["valid"]]


_imp_register(
    "passwords", page="admin_import_passwords", dl="admin_import_passwords_check", file="passwords",
    stage=_pimp_stage, load=_pimp_load, changes=_pimp_changes, after=_pimp_after, apply=_pimp_apply,
    downloads=_pimp_downloads,
    look=(("linked", "ID matched through a linked ID", "IDs matched through a linked ID",
           "The file uses another of their IDs: the password is set for the person under their main ID."),
          ("left", "person has left", "people have left",
           "Their sign-in is closed, so the password only counts if they come back."),),
    look_skips=("linked",),
    fix_kinds=(("No Employee ID", r"no Employee ID"), ("No password", r"no password"), ("In the file twice", r"more than "
               "once"), ("The same person twice", r"same person"), ("Nobody with that Employee ID", r"no matching user"),
               ("An empty file", r"no rows")),
    checks=("a row with no Employee ID or no password, someone twice (also under two of their IDs), an Employee ID "
            "nobody has (admin accounts are never changed).",
            "someone who has left, or an ID that is another of the person's IDs (a linked ID)."))


@app.route("/admin/import/passwords", methods=["GET", "POST"])
@super_required
def admin_import_passwords():
    """People > Import > Passwords, the super admin's: Employee ID and a password per row. In four steps since
    2026-10-26 (_imp_post): the kept file holds only the hashes. A post without the steps changes nothing
    (_imp_steps_only)."""
    db = get_db()
    me = current_user()
    if request.method == "POST" and (request.form.get("token") or "").strip():
        return _imp_post("passwords", db, me)
    if request.method == "POST" and request.form.get("preview") == "1":
        return _imp_upload("passwords", db, me)
    if request.method == "POST":
        return _imp_steps_only("admin_import_passwords")

    v, done = _imp_get("passwords", db, me)
    return render_template("admin_import_passwords.html", total_users=_pw_import_total_users(db), v=v, done=done,
                           is_super=True)


