ROSTER_COLUMNS = ["Employee ID", "Employee Name", "Business Group", "Company",
                  "Job Grade", "Job Title", "Department", "Joined Date",
                  "Confirmation Date", "Year(s) of Service", "Employment Type",
                  "Work Email", "Cost Center", "Work Location", "Manager", "HOD",
                  # the seats (admin round 4, row 8; canvas R3): a super admin's file only. Blank leaves a seat as it
                  # is, NONE takes it away, ';' between units. Line manager and HOD come from Manager / HOD.
                  "BU CEO of", "BG CEO of", "Group Chief of"]


def _parse_grade(raw):
    """Job grade: numeric grades stay int (drive the statement level); a letter
    grade like 'H' is kept as upper-case text. Blank -> None."""
    s = (str(raw).strip() if raw is not None else "")
    if not s or s.lower() == "nan":
        return None
    try:
        return int(float(s))
    except ValueError:
        return s.upper()


# HR master exports use long-form Business Group names; map them to the canonical
# org-master names so the roster import reconciles cleanly instead of skipping.
# Keyed on the normalised (lowercased, stripped) file value.
BG_IMPORT_ALIASES = {
    "chin hin building material group of companies": "CHIN HIN BUILDING MATERIAL (CHBM)",
    "chin hin construction engineering grp of companies": "CHIN HIN CONSTRUCTION ENGINEERING (CHCE)",
    "chin hin property group of companies": "CHIN HIN GROUP PROPERTY BERHAD",
    "fiamma group of companies": "FIAMMA HOLDINGS BERHAD",
    "signature alliance group of companies": "SIGNATURE ALLIANCE GROUP BERHAD (SAG)",
    "signature group of companies": "SIGNATURE INTERNATIONAL BERHAD",
}


# The roster import in four steps (admin round 4, canvas D4; the fourth, 2026-10-26): choose the file, OneHR checks it,
# shows what it changes and asks the super admin what it shouldn't guess, then applies THAT file -- kept on the server
# under a token for a day (_imp_stage, kind "roster"), never picked again.
ROSTER_FIELDS = (("name", "Name", "full_name"), ("bg", "Business group", "business_group"),
                 ("company", "Business unit", "company"),
                 ("dept", "Department", "department"), ("title", "Job title", "job_title"),
                 ("grade", "Job grade", "job_grade"), ("email", "Work email", "email"),
                 ("mgr", "Line manager", "manager_id"), ("hod", "HOD", "hod_id"))


def _roster_staged(me, token):
    """(filename, bytes, authoritative) of a kept roster file, or None (unknown, expired, applied, or someone else's)."""
    got = _imp_staged("roster", me, token)
    if not got:
        return None
    meta, data = got
    return meta.get("filename"), data, bool(meta.get("authoritative"))


def _roster_note_refusals(db, me, chk, filename):
    """Keep each row the roster check refused, by Employee ID, the latest check winning: the import is all or nothing,
    so a refused joiner never reaches OneHR, and the Ticketing agent can then say why (2026-10-22)."""
    for e in chk.get("errors") or []:
        eid = (e.get("eid") or "").strip()
        if eid:
            db.execute("INSERT OR REPLACE INTO roster_refusals(employee_id, why, filename, checked_by, checked_at) "
                       "VALUES (?,?,?,?,datetime('now'))", (eid, (e.get("why") or "")[:300], (filename or "")[:120],
                                                           me["id"]))
    db.commit()


def _roster_seats(db, me, rec, bg):
    """A roster row's seat columns (admin round 4, row 8; canvas R3) -> ({"bu": None|[units]|"NONE", "bg": None|bg|
    "NONE", "gc": None|group id|"NONE"}, error). Blank = leave as it is. Who may set which is the Leaders page's rule
    (_seat_scope_error; Chris, 2026-10-13: a unit admin BU CEO of their units, a BG admin BU CEO and BG CEO in their
    group, the super admin all, Group Chief included). A unit must be one of the row's own business group; a group name
    must exist."""
    raw = {k: _pick(rec, *names) for k, names in (("bu", ("bu ceo of",)), ("bg", ("bg ceo of",)),
                                                   ("gc", ("group chief of",)))}
    if not any(raw.values()):
        return {"bu": None, "bg": None, "gc": None}, None
    out = {"bu": None, "bg": None, "gc": None}
    if raw["bu"]:
        if raw["bu"].strip().upper() == "NONE":
            out["bu"] = "NONE"
        else:
            units = [x.strip() for x in raw["bu"].split(";") if x.strip()]
            for unit in units:
                if not org_valid(db, bg, unit):
                    return None, "BU CEO of: '%s' isn't a unit in %s" % (unit, display_bg(bg) or bg)
                _se = _seat_scope_error(me, "buceo", bg, unit)
                if _se:
                    return None, "BU CEO of: " + _se
            out["bu"] = sorted(set(units))
    if raw["bg"]:
        v = raw["bg"].strip()
        if v.upper() == "NONE":
            out["bg"] = "NONE"
        else:
            v = BG_IMPORT_ALIASES.get(v.lower(), v)
            if v not in org_bgs(db):
                return None, "BG CEO of: '%s' isn't a business group" % v
            _se = _seat_scope_error(me, "bgceo", v)
            if _se:
                return None, "BG CEO of: " + _se
            out["bg"] = v
    if raw["gc"]:
        _se = _seat_scope_error(me, "gc", "")
        if _se:
            return None, "Group Chief of: " + _se
        v = raw["gc"].strip()
        if v.upper() == "NONE":
            out["gc"] = "NONE"
        else:
            g = db.execute("SELECT id FROM pm_calibration_groups WHERE name=?", (v,)).fetchone()
            if not g:
                return None, "Group Chief of: there's no calibration group called '%s'" % v
            out["gc"] = g["id"]
    return out, None


def _roster_seat_changes(db, valid, err, me=None):
    """What a checked roster does to the seats, person by person: [{eid, name, kind (add / swap / take / same), what,
    note, ops, existing}] -- ops are what _roster_apply writes through the Leaders page's writers. Two rows claiming the
    same seat, or a Group Chief NONE for someone who calls a group (a group always has one), are errors (err), when
    given."""
    out, claimed_bu, claimed_bg = [], {}, {}
    for r in valid:
        st = r.get("seats") or {}
        if not any(v is not None for v in st.values()):
            continue
        ex = r["_existing"]
        uid = ex["id"] if ex else None
        ops, parts, notes, kind = [], [], [], "same"
        if st.get("bu") is not None:
            have = {c for _b, c in buceo_seats(db, uid)} if uid else set()
            want = set() if st["bu"] == "NONE" else set(st["bu"])
            for unit in sorted(want):
                if (r["bg"], unit) in claimed_bu and err:
                    err(r["row"], r["eid"], "BU CEO of %s is also on row %d" % (unit, claimed_bu[(r["bg"], unit)]))
                claimed_bu[(r["bg"], unit)] = r["row"]
            for unit in sorted(want - have):
                h = buceo_holder(db, r["bg"], unit)
                ops.append(("bu_add", r["bg"], unit))
                if h and h["id"] != uid:
                    notes.append("%s stops being BU CEO of %s." % (h["full_name"], unit))
                    kind = "swap"
                elif kind == "same":
                    kind = "add"
            for b_, unit in sorted(buceo_seats(db, uid) if uid else []):
                if unit not in want:
                    _se = _seat_scope_error(me, "buceo", b_, unit, clear=True) if me else None
                    if _se and err:   # taking a seat away is the same rule as giving it (2026-10-13)
                        err(r["row"], r["eid"], "BU CEO of: they also lead %s -- %s" % (unit, _se))
                    ops.append(("bu_take", b_, unit))
                    notes.append("%s is left with no BU CEO." % unit)
                    if kind in ("same", "take"):
                        kind = "take"
            if want != have:
                parts.append(("BU CEO of %s." % " and ".join(sorted(want))) if want else "BU CEO of: NONE.")
                if have & want and want - have:
                    parts.append("Keeps %s." % ", ".join(sorted(have & want)))
        if st.get("bg") is not None:
            cur = ex["bgceo_bg"] if ex else None
            if st["bg"] == "NONE":
                if cur:
                    _se = _seat_scope_error(me, "bgceo", cur, clear=True) if me else None
                    if _se and err:
                        err(r["row"], r["eid"], "BG CEO of NONE: " + _se)
                    ops.append(("bg_take", cur))
                    parts.append("BG CEO of: NONE.")
                    notes.append("%s is left with no BG CEO." % display_bg(cur))
                    if kind in ("same", "take"):
                        kind = "take"
            elif st["bg"] != cur:
                if st["bg"] in claimed_bg and err:
                    err(r["row"], r["eid"], "BG CEO of %s is also on row %d" % (st["bg"], claimed_bg[st["bg"]]))
                claimed_bg[st["bg"]] = r["row"]
                h = db.execute("SELECT full_name FROM users WHERE bgceo_bg=? AND id!=?", (st["bg"], uid or 0)).fetchone()
                ops.append(("bg_set", st["bg"]))
                parts.append("BG CEO of %s." % display_bg(st["bg"]))
                if h:
                    notes.append("%s stops being BG CEO." % h["full_name"])
                    kind = "swap"
                elif kind == "same":
                    kind = "add"
        if st.get("gc") is not None:
            calls = [g["id"] for g in db.execute("SELECT id FROM pm_calibration_groups WHERE calibrator_id=?",
                                                 (uid or 0,))]
            if st["gc"] == "NONE":
                if calls and err:
                    err(r["row"], r["eid"], "Group Chief of NONE: a calibration group always has a Group Chief -- name "
                                            "the person who takes it over in their own row instead")
            elif st["gc"] not in calls:
                g = db.execute("SELECT g.name, u.full_name FROM pm_calibration_groups g LEFT JOIN users u ON "
                               "u.id=g.calibrator_id WHERE g.id=?", (st["gc"],)).fetchone()
                ops.append(("gc_set", st["gc"]))
                parts.append("Group Chief of %s." % g["name"])
                if g["full_name"]:
                    notes.append("%s stops calling it." % g["full_name"])
                    kind = "swap"
                elif kind == "same":
                    kind = "add"
        out.append({"eid": r["eid"], "name": r["name"], "kind": kind if ops else "same", "ops": ops,
                    "what": " ".join(parts) or "No change to their seats.", "note": " ".join(notes),
                    "existing": bool(ex)})
    return out


def _roster_leaver_scope(me, file_bgs):
    """Who an authoritative file can mark as left: the admin's own data, and for the super admin only the business
    groups the file names (2026-10-19: with BG and unit admins view only, the super admin imports every group's roster,
    and one group's full roster must never close another group's people; Chris's rule is "leavers from a full HRIS
    roster per business group"). A full roster names every group, so it still covers everyone. (sql, params)."""
    sc, sp = bg_scope(me, "business_group")
    if is_super(me):
        bgs = sorted({b for b in (file_bgs or ()) if b})
        if not bgs:
            return " AND 0", []
        sc += " AND business_group IN (%s)" % ",".join("?" * len(bgs))
        sp = list(sp) + bgs
    return sc, sp


def _roster_leader_error(db, me, existing, bg, mgr, hod):
    """Why a roster row's HOD can't be what the file says, or None (Chris, 2026-10-21, before the People with no HOD
    download: the roster's HOD column gets the Leaders page's checks -- it wrote the HOD straight in). Only a CHANGE is
    checked, so a file that repeats who they have now passes as before; someone the file names who isn't in OneHR is the
    quality step's (left as it is). The Leaders page's _hod_candidate_error, nobody their own, an active employee, and
    _hod_calib_checks' blockers through _hod_person_plan. The line manager stays the quality step's: one who has left or
    their own is worth a look there (mgr_left, mgr_self; Chris's canvas D5), not a reason to stop the file."""
    for kind, key, col, word in (("HOD", hod, "hod_id", "HOD"),):
        if not key:
            continue
        p = db.execute("SELECT * FROM users WHERE employee_id=?", (key,)).fetchone()
        if not p or (existing and p["id"] == existing[col]):
            continue
        if existing and p["id"] == existing["id"]:
            return "%s: nobody is their own %s" % (kind, word)
        if p["left_at"]:
            return "%s: %s has left -- pick someone active" % (kind, key)
        if p["role"] == "admin":
            return "%s: %s is an admin account, not an employee" % (kind, key)
        if kind == "HOD":
            e_ = _hod_candidate_error(db, me, bg, p)
            if e_:
                return "HOD: " + e_
            if existing:
                plan = _hod_person_plan(db, me, p, existing)
                if plan.get("error") or plan.get("blockers"):
                    return "HOD: " + (plan.get("error") or "; ".join(plan["blockers"]))
    return None


def _roster_check(db, me, records, authoritative):
    """Validate a roster file's rows: {errors: [{row, eid, why}], valid: [row dicts], seen: set of Employee IDs,
    changes: [{eid, name, field, from, to}], counts}. All or nothing: any error means nothing is applied. A unit that
    isn't in Org structure is an error too (it used to be skipped, though the page said all or nothing)."""
    my_bg = admin_bg_of(me)
    errors, valid, seen = [], [], set()
    file_bgs = set()   # every group the file names, its rows with errors too (an authoritative file closes only these)
    moved_rows = []   # rows filed under a unit's NEW group because HR's file still names the old one (_unit_canonical)
    check_org = org_has_any(db)
    # Linked Employee IDs (2026-10-29): a row's Employee ID, line manager and HOD may be ANOTHER of a person's IDs. One
    # batched read finds them; the row is then read under the person's MAIN ID (never renamed, nobody new added, never
    # marked left for their main ID being absent) and the file's own ID is kept for the messages and the quality step.
    _mgr_cols = ("manager id", "manager eid", "manager", "line manager employee id", "line manager id", "line manager eid")
    _hod_cols = ("hod", "hod id", "hod eid")
    linked_of = {k: v[0] for k, v in _eid_resolve_many(db, [
        _pick(rec, *c_) for rec in records for c_ in (("employee id", "eid", "id", "staff id", "employee no"), _mgr_cols,
                                                      _hod_cols)]).items() if v[1]} if records else {}
    shown = {}      # row number -> the Employee ID as the file wrote it, when the row was matched through a linked ID
    seen_as = {}    # main Employee ID -> (the ID the file used first, the person's name or None)

    def err(rowno, eid, why):
        errors.append({"row": rowno, "eid": shown.get(rowno) or eid or "", "why": why})

    def via_main(ref):
        """(main ID, (file's ID, person's name) or None): a Manager or HOD cell, read through a linked ID."""
        r_ = linked_of.get(ref) if ref else None
        return (r_["employee_id"], (ref, r_["full_name"])) if r_ is not None else (ref, None)
    # a partial download (People with no line manager, 2026-10-21) is never a full roster: as one, it would close
    # everyone in its business groups who isn't in it
    if authoritative and records and any(str(k).startswith("reference:") for k in records[0]):
        err(1, "", "This file is a partial download (it has Reference: columns), so it can't be a full roster: a full "
                   "roster closes everyone in its business groups who isn't in the file. Import it as Update only.")
    for i, rec in enumerate(records, start=2):   # row 1 is the header
        eid = _pick(rec, "employee id", "eid", "id", "staff id", "employee no")
        name = _pick(rec, "employee name", "name", "full name")
        if not eid and not name:
            continue  # blank line
        if not eid:
            err(i, "", "No Employee ID (name: %s)" % name)
            continue
        file_eid, lrow = eid, linked_of.get(eid)
        if lrow is not None:   # another of their IDs: the row is read under their MAIN ID from here on
            eid = lrow["employee_id"]
            shown[i] = file_eid
        if eid in seen:
            first, who_ = seen_as.get(eid, (eid, None))
            if file_eid == first:
                err(i, eid, "This Employee ID appears more than once in the file")
            else:   # their main ID and a linked ID, or two linked IDs: one person twice
                err(i, file_eid, _eid_same_person(first, file_eid, lrow) if lrow is not None else
                    "%s and %s are the same person (%s)" % (first, file_eid, who_ or first))
            continue
        seen.add(eid)
        seen_as[eid] = (file_eid, lrow["full_name"] if lrow is not None else None)
        if not name:
            err(i, eid, "No Employee Name")
            continue
        if file_eid.upper().startswith("EXAMPLE-"):   # the template's own rows, uploaded unchanged
            err(i, file_eid, "An example row from the template: replace it with a real person or delete it")
            continue
        bg = my_bg or _pick(rec, "business group", "bg")
        if bg:
            file_bgs.add(bg)
        if not my_bg and bg:   # normalise file's long-form BG name to canonical
            bg = BG_IMPORT_ALIASES.get(bg.strip().lower(), bg)
        company = _pick(rec, "company") or None
        if not bg:
            err(i, eid, "No Business Group")
            continue
        if not my_bg and company:   # a unit moved to another group is still named under the old one by HR's file (2026-11-06)
            _bg_now = _unit_canonical(db, bg, company)
            if _bg_now != bg:
                moved_rows.append({"row": i, "eid": eid, "name": name, "company": company, "from": bg, "to": _bg_now})
                bg = _bg_now
        if not can_access(me, bg, company):
            err(i, eid, "Outside the data you manage (business group or unit)")
            continue
        existing = db.execute("SELECT * FROM users WHERE employee_id=?", (eid,)).fetchone()
        # a unit Org structure lacks fails the row, unless it's the group and unit OneHR already holds for this person:
        # the check stops a move into a unit that doesn't exist, and refusing an unchanged placement only blocked a
        # whole file (2026-10-21: the People with no line manager download, one person in a group Org lacks)
        same_place = bool(existing) and (existing["business_group"] or "") == bg \
            and (existing["company"] or None) == company
        if check_org and not org_valid(db, bg, company) and not same_place:
            err(i, eid, "'%s' isn't a unit in Org structure: add it there first, or fix the name" % (company or bg))
            continue
        if existing and _system_admin_locked(me, existing, db):   # (2026-10-28)
            err(i, eid, SYSTEM_ADMIN_LOCK_MSG + " Not changed by the roster import")
            continue
        if existing and existing["role"] == "admin":
            err(i, eid, "Belongs to an admin account: not changed by the roster import")
            continue
        # a person already in OneHR is matched by Employee ID alone, so a BG admin's file could move someone out of
        # another group (the admin review, 2026-10-13)
        if existing and not can_access(me, existing["business_group"], existing["company"]):
            err(i, eid, "Already in OneHR outside the data you manage (business group or unit): not changed")
            continue
        # a joiner gets a random password nobody knows (first_password); the file's Password column is not read, and
        # people already in OneHR keep their passwords
        pw = None
        if not existing:
            pw, _pw_err = first_password(eid)
        mgr_raw = _pick(rec, *_mgr_cols) or None
        mgr, mgr_via = via_main(mgr_raw)
        if not existing and not mgr:
            err(i, eid, "New joiner with no line manager (Employee ID) in the file")
            continue
        # a joiner may come in with no HOD: the BG admin assigns HODs on Leaders and seats (Chris, 2026-10-16, the
        # production roster: "for HOD, leave them for now, we will get the respective BG admin to assign them"). The
        # line manager is still required: someone has to review them.
        hod_raw = _pick(rec, *_hod_cols) or None
        hod, hod_via = via_main(hod_raw)
        joined = _pick(rec, "joined date", "join date") or None
        conf_date = _pick(rec, "confirmation date", "confirmed date", "confirm date") or None
        conf_flag = _pick(rec, "confirmed?", "confirmed", "confirm status").lower()
        if not conf_date and conf_flag in ("yes", "y", "confirmed", "true", "1"):
            conf_date = joined or "1900-01-01"
        # confirming someone is the super admin's (Chris, 2026-10-20): another admin's file leaves the date as it is
        if not is_super(me):
            conf_date = None
        # dates are read as dates (2026-10-21: one typed day/month/year was stored as typed, and a confirmation date
        # decides who is Full): YYYY-MM-DD, day/month/year or an Excel date, stored YYYY-MM-DD. One OneHR can't read is
        # not written -- the person keeps what they have -- and the quality step still shows it (date_bad), as Chris's
        # canvas D5 has it: worth a look, not a reason to stop the file.
        raw_dates = {"joined": joined, "confirmed": conf_date}
        if joined:
            _d = _roster_date(joined)
            joined = _d.isoformat() if _d else None
        if conf_date and conf_date != "1900-01-01":
            _d = _roster_date(conf_date)
            conf_date = _d.isoformat() if _d else None
        lerr = _roster_leader_error(db, me, existing, bg, mgr, hod)
        if lerr:
            err(i, eid, lerr)
            continue
        seats_, serr = _roster_seats(db, me, rec, bg)
        if serr:
            err(i, eid, serr)
            continue
        valid.append({
            "row": i, "eid": eid, "name": name, "bg": bg, "company": company, "seats": seats_,
            "dept": _pick(rec, "department", "dept") or None, "title": _pick(rec, "job title", "title") or None,
            "grade": _parse_grade(rec.get("job grade")), "joined": joined, "confirmed": conf_date,
            "yos": _pick(rec, "year(s) of service", "years of service", "yos") or None,
            "etype": _pick(rec, "employment type", "type") or None, "email": _pick(rec, "work email", "email") or None,
            "cost_center": _pick(rec, "cost center", "cost centre", "costcenter", "cc") or None,
            "work_location": _pick(rec, "work location", "location", "site") or None,
            "mgr": mgr, "hod": hod, "pw": pw, "existing_id": existing["id"] if existing else None,
            "raw_dates": raw_dates, "via_eid": file_eid if lrow is not None else None, "mgr_via": mgr_via,
            "hod_via": hod_via,
            "_existing": existing})
    # the profile-change engine's refusals, for everyone this file CHANGES in group, unit or department (2026-11-08): a business
    # group move is refused for a seat holder, a calibrator, an HOD of others, a band set or a result released; a unit or department
    # change that moves who calibrates them is refused once a band is set or the result is released; a Grade H person can't move
    # into or out of a signed-off or released unit. A group change needs a unit of the new group in the same row. Like every row
    # error these stop the whole file (all or nothing). ONE read per measure over everyone changed, never a query per person.
    pairs, pair_row = [], {}
    bad_rows = set()
    for r in valid:
        ex = r["_existing"]
        if not ex:
            continue
        new_co, new_dp = r["company"] or ex["company"], r["dept"] or ex["department"]
        bg_changed = bool(_pf_val(ex["business_group"])) and _pf_val(ex["business_group"]) != _pf_val(r["bg"])
        if not (bg_changed or _pf_val(ex["company"]) != _pf_val(new_co) or _pf_val(ex["department"]) != _pf_val(new_dp)):
            continue
        if bg_changed and check_org and (not r["company"] or not org_valid(db, r["bg"], r["company"])):
            err(r["row"], r["eid"], "%s (%s): can't move to %s: the Business unit cell must name one of its units (it is %s)" % (
                r["name"], r["eid"], display_bg(r["bg"]), "blank" if not r["company"] else "'%s', not a unit of that group" % r["company"]))
            bad_rows.add(r["row"])
            continue
        pairs.append((ex, {"business_group": r["bg"], "company": new_co, "department": new_dp,
                           "job_title": r["title"] or ex["job_title"],
                           "job_grade": r["grade"] if r["grade"] not in (None, "") else ex["job_grade"]}))
        pair_row[ex["id"]] = r
    if pairs:
        refused = _profile_org_refusals_all(db, pairs, active_cycle_id(db), links=False)
        for ex, nv in pairs:
            why = [x["words"] for x in refused.get(ex["id"], [])]
            if not why:
                continue
            r = pair_row[ex["id"]]
            if _pf_val(ex["business_group"]) != _pf_val(nv["business_group"]):
                what, where = "move to", display_bg(nv["business_group"])
            elif _pf_val(ex["company"]) != _pf_val(nv["company"]):
                what, where = "move to", display_company(nv["business_group"], nv["company"]) or nv["company"] or ""
            else:
                what, where = "change department to", nv["department"] or ""
            err(r["row"], r["eid"], "%s (%s): can't %s %s: %s" % (r["name"], r["eid"], what, where, " ".join(why)))
            bad_rows.add(r["row"])
    if bad_rows:
        valid = [r for r in valid if r["row"] not in bad_rows]
    # what each update changes, field by field (preserve-on-blank: a blank cell changes nothing)
    changes = []
    eid_name = {}

    def person_of(eid):
        if eid not in eid_name:
            r = db.execute("SELECT id, full_name FROM users WHERE employee_id=?", (eid,)).fetchone()
            eid_name[eid] = (r["id"], r["full_name"]) if r else (None, None)
        return eid_name[eid]
    names_by_id = {}

    def name_by_id(uid):
        if uid and uid not in names_by_id:
            r = db.execute("SELECT full_name FROM users WHERE id=?", (uid,)).fetchone()
            names_by_id[uid] = r["full_name"] if r else ""
        return names_by_id.get(uid, "") if uid else ""
    file_names = {r["eid"]: r["name"] for r in valid}
    for r in valid:
        ex = r["_existing"]
        if not ex:
            continue
        for key, label, col in ROSTER_FIELDS:
            new = r[key]
            if new in (None, ""):
                continue
            if key in ("mgr", "hod"):
                nid, nname = person_of(new)
                nname = nname or file_names.get(new)
                if nid is not None and nid == ex[col]:
                    continue
                if nid is None and not nname:
                    changes.append({"eid": r["eid"], "name": r["name"], "field": label, "from": name_by_id(ex[col]),
                                    "to": "%s (not found: left as it is)" % new})
                    continue
                changes.append({"eid": r["eid"], "name": r["name"], "field": label, "from": name_by_id(ex[col]) or "none",
                                "to": nname or new})
            elif str(new).strip() != str(ex[col] if ex[col] is not None else "").strip():
                changes.append({"eid": r["eid"], "name": r["name"], "field": label, "from": ex[col] or "none",
                                "to": new})
        # a confirmation date the file sets (the super admin's only) shows as a change too (2026-10-21)
        if r["confirmed"] and r["confirmed"] != "1900-01-01":
            _was = _roster_date(str(ex["confirmation_date"] or ""))
            if (_was.isoformat() if _was else "") != r["confirmed"]:
                changes.append({"eid": r["eid"], "name": r["name"], "field": "Confirmation date",
                                "from": _was.isoformat() if _was else "none", "to": r["confirmed"]})
    would_leave = []
    if authoritative and seen:
        sc, sp = _roster_leaver_scope(me, file_bgs)
        ph = ",".join("?" * len(seen))
        would_leave = db.execute(f"SELECT employee_id, full_name, business_group, company, job_title FROM users "
                                 f"WHERE role='user' AND left_at IS NULL "
                                 f"AND is_demo=0 AND employee_id NOT IN ({ph})" + sc, list(seen) + sp).fetchall()
    back = [r for r in valid if r["_existing"] and r["_existing"]["left_at"]]
    by_field = {}
    for c in changes:
        by_field[c["field"]] = by_field.get(c["field"], 0) + 1
    updated_ids = {c["eid"] for c in changes}
    seat_changes = _roster_seat_changes(db, valid, err, me)
    if seat_changes:
        updated_ids |= {c["eid"] for c in seat_changes if c["kind"] != "same" and c.get("existing")}
    return {"errors": errors, "valid": valid, "seen": seen, "changes": changes, "by_field": by_field,
            "seat_changes": seat_changes,
            "would_leave": would_leave, "authoritative": authoritative, "file_bgs": sorted(file_bgs), "moved_rows": moved_rows,
            "counts": {"add": sum(1 for r in valid if not r["existing_id"]), "update": len(updated_ids),
                       "same": sum(1 for r in valid if r["existing_id"] and r["eid"] not in updated_ids),
                       "back": len(back), "errors": len(errors), "leave": len(would_leave), "rows": len(valid)}}


# The quality step before the changes (Chris, 2026-10-13: "For the roster import, have a prestep for admin to check the
# quality of the import and flag any issue"; canvas D5). 1 File -> 2 Quality -> 3 Changes -> 4 Apply. Rows that can't be
# imported are grouped by what is wrong; things that won't stop the import but are probably a mistake in the file are
# listed with why they matter. Continue needs every row to pass, and a tick when there are things to look at; Apply
# needs the quality step seen, on the same findings.
_RQ_DATE_FMTS = ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%d/%m/%Y", "%d-%m-%Y", "%d.%m.%Y", "%Y/%m/%d", "%d %b %Y",
                 "%d %B %Y")
_RQ_LOOK = (   # key, what, why it matters -- in the order the page lists them
    # a linked Employee ID (2026-10-29) is informational: OneHR reads the row right, so it never makes a row "not clean"
    ("linked", "Matched through a linked ID",
     "The file uses another of their IDs: OneHR updates them under their main ID, doesn't rename them and adds nobody new"),
    ("linked_mgr", "Line manager or HOD matched through a linked ID",
     "The Manager or HOD column uses another of their IDs; the right person is set"),
    ("mgr_missing", "Line manager not in OneHR or in this file",
     "They'd have no line manager: nobody moderates their KPIs (an existing person keeps the one they have)"),
    ("mgr_left", "Line manager has left, or would be marked as left",
     "Their reviews would wait on someone who isn't here"),
    ("mgr_self", "Their own line manager", "Nobody else would review them"),
    ("mgr_loop", "Reporting loop", "Each is the other's manager, so neither review can finish"),
    ("hod_missing", "HOD not in OneHR or in this file", "Their department review would have no HOD"),
    ("hod_left", "HOD has left, or would be marked as left", "Their department review would wait on someone who isn't here"),
    ("dept_like", "Department spelled like another", "One department would split in two (HOD, reviews, reports)"),
    ("no_email", "No work email", "Can't be sent reminders or a password reset"),
    ("email_shared", "Same email as someone else", "One inbox gets both people's reminders and resets"),
    ("grade", "Job grade not understood", "Their statements and potential scale are set by grade"),
    ("date_bad", "Date not understood", "It would be saved as typed, and service and confirmation read it wrong"),
    ("date_future", "Date in the future, or confirmed before joining", "Who takes part this cycle reads these dates"),
    ("name_diff", "Name differs from OneHR for the same ID", "Maybe the wrong Employee ID: the file would rename them"),
    ("same_person", "May be the same person as another account",
     "One person with two accounts splits their history and reviews: if it's the same person, fix the Employee ID "
     "before importing"),
    ("seat_vacant", "A unit or group left with no CEO", "Its calibration would have nobody to call it"),
    ("many_leave", "Many people would be marked as left", "Is this the complete headcount? Anyone missing loses their login"),
)


def _roster_date(s):
    """A roster date cell -> date, or None when it isn't a date OneHR can read."""
    s = (s or "").strip()
    for f in _RQ_DATE_FMTS:
        try:
            return datetime.strptime(s, f).date()
        except ValueError:
            continue
    return None


def _roster_name_key(name):
    """A name as the quality step compares it: punctuation as a space, spaces collapsed, capitals ignored."""
    return " ".join(re.sub(r"[^\w\s]", " ", name or "").split()).casefold()


def _roster_issue_kind(why):
    """An error's reason with its row numbers taken out, so rows with the same problem group together (a unit's name
    stays: two rows naming the same missing unit are one group, as the canvas drew it)."""
    return re.sub(r"\brow \d+", "another row", why or "")


def _roster_quality(db, me, chk):
    """The quality of a checked roster file: {fix: [{kind, n, rows}], look: [{key, what, why, n, found: [{row, eid,
    detail, rows}]}], rows, clean, n_fix, n_look, fingerprint}. Reads only; the findings are the same for the same file and the
    same OneHR, so the fingerprint tells Apply whether what the admin looked at still holds."""
    valid = chk["valid"]
    fix = {}
    for e in chk["errors"]:
        g = fix.setdefault(_roster_issue_kind(e["why"]), [])
        g.append(e["row"])
    fix_l = [{"kind": k, "n": len(v), "rows": sorted(set(v))} for k, v in fix.items()]
    fix_l.sort(key=lambda x: (-x["n"], x["kind"]))
    look = {k: [] for k, _w, _y in _RQ_LOOK}

    def add(key, r, detail, rows=None):
        look[key].append({"row": r["row"] if r else None, "eid": r["eid"] if r else "", "detail": detail,
                          "rows": rows if rows is not None else ([r["row"]] if r else [])})
    people = {u["employee_id"]: u for u in db.execute(
        "SELECT id, employee_id, full_name, manager_id, hod_id, left_at, email, department, company, business_group, "
        "role, joined_date, is_demo FROM users WHERE employee_id IS NOT NULL AND employee_id!=''")}
    by_id = {u["id"]: u for u in people.values()}
    in_file = {r["eid"]: r for r in valid}
    leaving = {w["employee_id"] for w in chk["would_leave"]}

    def who(eid):
        r = in_file.get(eid)
        if r:
            return r["name"]
        u = people.get(eid)
        return u["full_name"] if u else eid
    # a linked Employee ID in the ID, Manager or HOD column: read under the person's main ID (informational)
    for r in valid:
        if r.get("via_eid"):
            add("linked", r, "Row %d: %s is %s (main ID %s)" % (r["row"], r["via_eid"], r["_existing"]["full_name"], r["eid"]))
        for key, word in (("mgr_via", "line manager"), ("hod_via", "HOD")):
            if r.get(key):
                add("linked_mgr", r, "Row %d: %s %s is %s" % (r["row"], word, r[key][0], r[key][1]))
    # line manager and HOD: found, still here, not themselves
    for r in valid:
        for key, col, miss, gone in (("mgr", "Line manager", "mgr_missing", "mgr_left"),
                                     ("hod", "HOD", "hod_missing", "hod_left")):
            ref = r[key]
            if not ref:
                continue
            if key == "mgr" and ref == r["eid"]:
                add("mgr_self", r, "Row %d: %s is their own line manager" % (r["row"], r["eid"]))
                continue
            if ref not in in_file and ref not in people:
                add(miss, r, "Row %d: %s %s" % (r["row"], col.lower() if key == "mgr" else col, ref))
                continue
            u = people.get(ref)
            if ref not in in_file and u and (u["left_at"] or ref in leaving):
                add(gone, r, "Row %d: %s (%s)" % (r["row"], u["full_name"], "has left" if u["left_at"]
                                                     else "would be marked as left"))
    # reporting loops, through the file's managers and OneHR's for everyone else
    mgr_of = {}
    for eid, u in people.items():
        if u["manager_id"] and u["manager_id"] in by_id:
            mgr_of[eid] = by_id[u["manager_id"]]["employee_id"]
    for r in valid:
        if r["mgr"]:
            mgr_of[r["eid"]] = r["mgr"]
    loops = set()
    for r in valid:
        path, cur = [r["eid"]], mgr_of.get(r["eid"])
        while cur and cur not in path and len(path) < 50:
            path.append(cur)
            cur = mgr_of.get(cur)
        if cur and cur == r["eid"] and len(path) > 1:
            key = tuple(sorted(path))
            if key not in loops:
                loops.add(key)
                add("mgr_loop", r, " → ".join([who(p) for p in path] + [who(r["eid"])]),
                    rows=[in_file[p]["row"] for p in path if p in in_file])
    # departments spelled like another in the same unit: the spelling most people use (OneHR's own on a tie) stands,
    # and a row spelling it some other way is the one to look at
    spell, in_db = {}, {}

    def loose(d):
        return re.sub(r"[^0-9a-z]+", "", (d or "").casefold().replace("&", "and"))

    def unit_of(r):
        ex = r["_existing"]
        return (r["bg"], r["company"] or (ex["company"] if ex else "") or "")
    for u in people.values():
        if u["role"] != "admin" and not u["left_at"] and u["department"] and u["employee_id"] not in in_file:
            key = (u["business_group"], u["company"] or "", loose(u["department"]))
            sp = spell.setdefault(key, {})
            sp[u["department"].strip()] = sp.get(u["department"].strip(), 0) + 1
            in_db.setdefault(key, set()).add(u["department"].strip())
    for r in valid:
        if r["dept"]:
            sp = spell.setdefault(unit_of(r) + (loose(r["dept"]),), {})
            sp[r["dept"].strip()] = sp.get(r["dept"].strip(), 0) + 1
    for r in valid:
        if not r["dept"]:
            continue
        key = unit_of(r) + (loose(r["dept"]),)
        sp = spell.get(key, {})
        if len(sp) < 2:
            continue
        main = max(sp, key=lambda x: (sp[x], x in in_db.get(key, ()), x))
        if r["dept"].strip() != main:
            add("dept_like", r, "Row %d: '%s' beside '%s' (%d %s) in %s" % (
                r["row"], r["dept"].strip(), main, sp[main], "person" if sp[main] == 1 else "people",
                display_company(key[0], key[1]) or key[0]))
    # work email: none at all, or one someone else has
    owner = {}
    for eid, u in people.items():
        if u["email"] and not u["left_at"] and u["role"] != "admin" and eid not in in_file:
            owner.setdefault(u["email"].strip().lower(), set()).add(eid)
    for r in valid:
        if r["email"]:
            owner.setdefault(r["email"].strip().lower(), set()).add(r["eid"])
    for r in valid:
        ex = r["_existing"]
        if not r["email"] and not (ex and ex["email"]):
            add("no_email", r, "Row %d: %s" % (r["row"], r["name"]))
        elif r["email"]:
            also = sorted(owner.get(r["email"].strip().lower(), set()) - {r["eid"]})
            if also:
                add("email_shared", r, "Row %d: %s, also %s" % (r["row"], r["email"].strip(), who(also[0])
                                                              + (" and %d more" % (len(also) - 1) if len(also) > 1 else "")))
    # job grade, dates, a name that doesn't look like the same person
    today = _today_myt()
    for r in valid:
        g = r["grade"]
        # a number, or one letter (H, the line-manager-only grade); "G1O" or "G12" is a typo OneHR would keep as text
        if g is not None and ((isinstance(g, int) and not 1 <= g <= 40)
                              or (isinstance(g, str) and not re.fullmatch(r"[A-Z]", g.strip().upper()))):
            add("grade", r, "Row %d: '%s'" % (r["row"], g))
        jd = cd = None
        for key, label in (("joined", "Joined Date"), ("confirmed", "Confirmation Date")):
            v = (r.get("raw_dates") or {}).get(key) or r[key]   # as the file had it: one it can't read isn't written
            if not v or v == "1900-01-01":
                continue
            d = _roster_date(v)
            if d is None:
                add("date_bad", r, "Row %d: %s '%s'" % (r["row"], label, v))
                continue
            if key == "joined":
                jd = d
            else:
                cd = d
            if d > today:
                add("date_future", r, "Row %d: %s %s, after today" % (r["row"], label, d.isoformat()))
        if jd and cd and cd < jd:
            add("date_future", r, "Row %d: confirmed %s, before joining %s" % (r["row"], cd.isoformat(),
                                                                             jd.isoformat()))
        ex = r["_existing"]
        if ex and ex["full_name"]:
            a_, b_ = _roster_name_key(ex["full_name"]), _roster_name_key(r["name"])
            if a_ != b_ and difflib.SequenceMatcher(None, a_, b_).ratio() < 0.8:
                add("name_diff", r, "%s: '%s' in OneHR, '%s' here" % (r["eid"], ex["full_name"], r["name"]))
    # a new row whose name an account under another Employee ID already has (or another new row has): one person with
    # two accounts splits their history (X0006 / FL900, 2026-10-29). One index over OneHR's people, no query per row.
    def _day(v):
        v = str(v or "").strip()
        return _roster_date(v) or _roster_date(v[:10])
    by_name = {}
    for u in people.values():
        if u["role"] == "admin" or u["is_demo"] or "~" in u["employee_id"]:
            continue
        k = _roster_name_key(u["full_name"])
        if k:
            by_name.setdefault(k, []).append(u)
    new_seen = {}   # name -> the earlier new rows of this file with it
    for r in valid:
        if r["_existing"]:
            continue
        k = _roster_name_key(r["name"])
        if not k:
            continue
        jd = _day(r["joined"])
        found = []   # (same joined date, still here, employee id, where, state, row in this file)
        for u in by_name.get(k, ()):
            if u["employee_id"] == r["eid"]:
                continue
            if u["left_at"]:
                state = "left " + (_myt_date_str(u["left_at"]) or str(u["left_at"])[:10])
            elif u["employee_id"] in leaving:
                state = "would be marked as left"
            else:
                state = "active"
            found.append((bool(jd) and _day(u["joined_date"]) == jd, not u["left_at"], u["employee_id"],
                          "%s in OneHR" % u["employee_id"], state, None))
        for o in new_seen.get(k, ()):
            if o["eid"] != r["eid"]:
                found.append((bool(jd) and _day(o["joined"]) == jd, True, o["eid"],
                              "%s in row %d of this file" % (o["eid"], o["row"]), "new", o["row"]))
        new_seen.setdefault(k, []).append(r)
        if not found:
            continue
        found.sort(key=lambda f: (not f[0], not f[1], f[2]))
        same, _act, _eid, where, state, _orow = found[0]
        add("same_person", r, "Row %d: %s is new here; %s has the same name%s%s%s%s" % (
            r["row"], r["eid"], where, " and joined date" if same else "",
            "" if state == "new" else " (%s)" % state,
            ": very likely the same person" if same else "",
            "; and %d more with the same name" % (len(found) - 1) if len(found) > 1 else ""),
            rows=sorted({r["row"]} | {f[5] for f in found if f[5]}))
    # a seat taken away leaves its unit or group with nobody; a full roster that marks many as left
    vacant_by_eid = {c["eid"]: c for c in chk["seat_changes"] if c["kind"] == "take" and c.get("note")}
    for r in valid:
        c = vacant_by_eid.get(r["eid"])
        if c:
            add("seat_vacant", r, "Row %d: %s" % (r["row"], c["note"]))
    n_leave = len(chk["would_leave"])
    if chk["authoritative"] and n_leave:
        sc, sp = _roster_leaver_scope(me, chk.get("file_bgs"))   # the same people the file can close
        active = db.execute("SELECT COUNT(*) FROM users WHERE role='user' AND left_at IS NULL AND is_demo=0" + sc,
                            sp).fetchone()[0]
        if n_leave >= max(10, active // 10):
            add("many_leave", None, "%d of the %d active people in the groups this file names aren't in it" % (
                n_leave, active))
    look_l = [{"key": k, "what": w, "why": y, "n": len(look[k]), "found": look[k]} for k, w, y in _RQ_LOOK if look[k]]
    flagged = {x for g in look_l if g["key"] not in ("linked", "linked_mgr") for i in g["found"] for x in i["rows"]}
    fp = hashlib.sha256(json.dumps([[g["kind"], g["rows"]] for g in fix_l]
                                   + [[g["key"], [i["detail"] for i in g["found"]]] for g in look_l],
                                   ensure_ascii=False).encode()).hexdigest()[:16]
    n_rows = len(valid) + len({e["row"] for e in chk["errors"]})
    return {"fix": fix_l, "look": look_l, "rows": n_rows, "n_fix": len({e["row"] for e in chk["errors"]}),
            "n_look": sum(g["n"] for g in look_l), "clean": sum(1 for r in valid if r["row"] not in flagged),
            "fingerprint": fp}


def _roster_apply(db, me, chk, keep=(), skip_seats=(), handover=(), handover_reason="", ho_out=None, prof_out=None, asks=None):
    """Apply a checked roster (no errors): create new people, refresh existing ones (preserve-on-blank), link the line
    manager and HOD by Employee ID, and in authoritative mode mark the absent as left. The super admin's answers at the
    third step (2026-10-26): `keep` -- Employee IDs not in the file who stay active; `skip_seats` -- Employee IDs whose
    seats stay as they are. (created, updated, reactivated, left, unlinked, kpi_moved). A changed line manager moves
    the person's KPI lines nobody had moderated to the new one, as the person page does (_pm_lm_lines_to_move_many);
    it touches no 360 panel (Chris, 2026-10-29: the line manager need not be on it).
    `handover` (2026-10-30, the super admin's answers at step 3): Employee IDs whose OLD line manager's KPI moderation,
    competency review and Career Plan close are cleared and given to the new one, with `handover_reason` (one for the file),
    through _reopen_submission's redo_by, BEFORE the KPI lines to move are worked out (so the cleared lines follow). Each new
    line manager gets one email after the commit. `ho_out` (a dict) is filled: people, emails, skipped.
    `prof_out` (a dict, 2026-11-08) is filled with what the profile-change engine did for the people whose group, unit,
    department, title or grade the file changed (_profile_change_apply_many: people, bg_moves, bg_pending, unit_moves,
    grade_follow, picks_removed, participation_flips, retier_ratings) and `hod_refused` (HOD links _hod_candidate_error
    refused at apply: left as they were).
    `asks` (piece 3, 2026-11-08): {Employee ID: the answers to what the file's change asks of that person (_profile_asks_check's `ans`,
    with `expect`: what the super admin was shown)} from the import's step 3, or None (a script: nothing is asked). They are done in
    this same first transaction; someone whose state has moved since (they started or submitted) keeps their competencies as they
    are and is counted in `prof_out` (asks_stale, asks_undecided, comp_reassigned, comp_swapped, gh_off, gh_keep). A swap's email goes
    out after the commit (_redo_flush).
    The line follow-through (2026-11-13): every line manager and HOD this file changes is handed to _line_changed ONCE, for the
    whole file, in this same transaction (Grade H's appraiser and HOD, the rating record); `prof_out["line_notes"]` is filled with what
    it did. (An HOD link's calibration checks, _hod_person_plan, are the Changes step's own: _roster_leader_error.)"""
    valid, authoritative, seen = chk["valid"], chk["authoritative"], chk["seen"]
    created = updated = reactivated = 0
    _came = {}   # the joiners it creates, by business group: their units (for the admins' new-joiner email)
    _gr_act = active_cycle(db)
    _pf_old = []   # the users rows of people already here BEFORE the file's UPDATE: the profile-change engine's `old`, below
    for r in valid:
        try:
            yos = float(r["yos"]) if r["yos"] else None
        except ValueError:
            yos = None
        if r["existing_id"]:
            _system_admin_refuse(me, r["existing_id"], db)   # (2026-10-28)
            _was = db.execute("SELECT * FROM users WHERE id=?", (r["existing_id"],)).fetchone()
            was_left = _was["left_at"]
            _pf_old.append(dict(_was))
            # Upsert is preserve-on-blank: a column the file omits (or leaves empty) keeps the existing value rather
            # than nulling it, so a PARTIAL roster file can't wipe confirmation/email/etc. Name + BG always overwrite.
            db.execute(
                "UPDATE users SET full_name=?, business_group=?, company=COALESCE(NULLIF(?,''), company), "
                "department=COALESCE(NULLIF(?,''), department), job_title=COALESCE(NULLIF(?,''), job_title), "
                "job_grade=COALESCE(NULLIF(?,''), job_grade), joined_date=COALESCE(NULLIF(?,''), joined_date), "
                "confirmation_date=COALESCE(NULLIF(?,''), confirmation_date), "
                "years_of_service=COALESCE(?, years_of_service), "
                "employment_type=COALESCE(NULLIF(?,''), employment_type), email=COALESCE(NULLIF(?,''), email), "
                "cost_center=COALESCE(NULLIF(?,''), cost_center), "
                "work_location=COALESCE(NULLIF(?,''), work_location), left_at=NULL WHERE id=?",
                (r["name"], r["bg"], r["company"], r["dept"], r["title"], r["grade"], r["joined"], r["confirmed"],
                 yos, r["etype"], r["email"], r["cost_center"], r["work_location"], r["existing_id"]))
            updated += 1
            if was_left:
                # as the Users page's reactivate does: their assignments archived for leaving come back
                _reactivate_user(db, active_cycle_id(db), r["existing_id"])
                log_activity(db, me["id"], "reactivate", f"{r['name']} ({r['eid']}): back, by roster import",
                             target_user_id=r["existing_id"])
                reactivated += 1
        else:
            db.execute(
                "INSERT INTO users(username, full_name, password_hash, role, employee_id, business_group, company, "
                "department, job_title, job_grade, joined_date, confirmation_date, years_of_service, employment_type, "
                "email, cost_center, work_location, created_at, created_via, pw_set_at) "
                "VALUES (?,?,?, 'user', ?,?,?,?,?,?,?,?,?,?,?,?,?, datetime('now'), 'import', datetime('now'))",
                (r["eid"], r["name"], generate_password_hash(r["pw"], method="pbkdf2:sha256"), r["eid"], r["bg"],
                 r["company"], r["dept"], r["title"], r["grade"], r["joined"], r["confirmed"], yos, r["etype"],
                 r["email"], r["cost_center"], r["work_location"]))
            created += 1
            _came.setdefault(r["bg"], []).append(r["company"])
    # everything a change of group, unit, department, title or grade makes pending (the profile-change engine), for everyone
    # the file changed, in this first transaction: their pending 360 ratings follow a new tier (ONE batched pass; a submitted
    # rating is never touched; 2026-11-08), their KPI lines and BU KPIs follow the unit, a business group move's block with its
    # KPI lines set later, calibration picks, their rating record (batched). The refusals were the check's; a refusal here (the
    # state changed since the check) raises, and the whole file is rolled back (_imp_post).
    _pf_mail = []
    if _pf_old:
        _pf_pairs = []
        for o_ in _pf_old:
            n_ = dict(db.execute("SELECT * FROM users WHERE id=?", (o_["id"],)).fetchone())
            if _profile_diff(o_, n_):
                _pf_pairs.append((o_, n_))
        if _pf_pairs:
            for uid_, items_ in _profile_org_refusals_all(db, _pf_pairs, _gr_act["id"] if _gr_act else None, links=False).items():
                if items_:
                    _who = next(n_ for o_, n_ in _pf_pairs if o_["id"] == uid_)
                    raise ValueError("%s (%s) can't be moved now: %s" % (_who["full_name"], _who["employee_id"], items_[0]["words"]))
        _asks = None
        if asks is not None:
            _by_eid = {r["existing_id"]: asks.get(r["eid"]) for r in valid if r["existing_id"]}
            _asks = {pid_: a_ for pid_, a_ in _by_eid.items() if a_ is not None}
        _profile_change_apply_many(db, me, _pf_old, _gr_act, "roster", mail_out=_pf_mail, out=prof_out, answers=_asks,
                                   stale_ok=True)
    db.commit()
    _profile_mail_send(db, _pf_mail)   # the super admins' task email, after the commit
    _redo_flush(db, me["id"])   # a swap's email to the person (collected above), after the commit
    # link manager/HOD by employee_id (now that all rows exist); preserve-on-blank, and an ID that doesn't resolve
    # leaves the link as it is (only reported)
    unlinked = 0

    def _resolve_eid(eid):
        if not eid:
            return None, False
        m = db.execute("SELECT id FROM users WHERE employee_id=?", (eid,)).fetchone()
        return (m["id"] if m else None), (m is None)
    # who gets a DIFFERENT line manager (an existing person): with an active cycle, their KPI lines nobody had moderated
    # follow, worked out for all of them in one read BEFORE manager_id changes (the rule reads the old one)
    _lm_cid = active_cycle_id(db)
    _lm_new = {}
    for r in valid:
        if r["existing_id"] and r["mgr"]:
            mid, m_miss = _resolve_eid(r["mgr"])
            if not m_miss and mid != r["existing_id"]:
                _lm_new[r["existing_id"]] = mid
    _cur = {}
    _ids = list(_lm_new)
    for k in range(0, len(_ids), 500):
        part = _ids[k:k + 500]
        for u_ in db.execute("SELECT id, manager_id FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part):
            _cur[u_["id"]] = u_["manager_id"]
    _lm_new = {u: m for u, m in _lm_new.items() if _cur.get(u) != m}
    # the answered hand-overs, first: the old line manager's work cleared and given to the new one (the reopen's own writer),
    # so the KPI lines it unlocks are among the ones that follow below
    _ho_mail, _ho_audit = {}, {}   # new line manager id -> [(subject row, parts, reopen ids)]; subject id -> audit words
    _ho_cyc = active_cycle(db) if handover and _lm_cid else None
    for r in valid if _ho_cyc else ():
        if r["eid"] not in handover or r["existing_id"] not in _lm_new:
            continue
        p_ = db.execute("SELECT * FROM users WHERE id=?", (r["existing_id"],)).fetchone()
        new_ = db.execute("SELECT * FROM users WHERE id=?", (_lm_new[r["existing_id"]],)).fetchone()
        dn_ = _lm_done(db, me, p_, _ho_cyc)
        parts_ = [x["part"] for x in dn_["parts"] if x["ok"]] if not dn_["out"] else []
        info_ = {}
        ok_, _m, info_ = _lm_handover_run(db, me, p_, new_, parts_, handover_reason) if parts_ else (False, "", None)
        if not ok_:
            if ho_out is not None:
                ho_out["skipped"] = ho_out.get("skipped", 0) + 1
            continue
        _ho_mail.setdefault(new_["id"], []).append((p_, parts_, [rw["id"] for rw, _a in info_["made"]]))
        _ho_audit[p_["id"]] = _lm_handover_audit(parts_, info_, handover_reason)
    _lm_lines = _pm_lm_lines_to_move_many(db, _lm_new, _lm_cid) if _lm_new and _lm_cid else {}
    kpi_moved = 0
    _line_moves = []   # every line manager and HOD the file changed: one _line_changed for the whole file, below
    for r in valid:
        uid_row = db.execute("SELECT id FROM users WHERE employee_id=?", (r["eid"],)).fetchone()
        if not uid_row:
            continue
        if r["mgr"]:
            mid, m_miss = _resolve_eid(r["mgr"])
            if m_miss:
                unlinked += 1
            else:
                db.execute("UPDATE users SET manager_id=? WHERE id=?", (mid, uid_row["id"]))
                if _lm_new.get(uid_row["id"]) == mid:
                    _line_moves.append({"uid": uid_row["id"], "kind": "lm", "old": _cur.get(uid_row["id"]), "new": mid})
                    moved_ = _lm_lines.get(uid_row["id"], [])
                    for tid_ in moved_:
                        _pm_set_moderator(db, tid_, _pm_default_moderators(db, uid_row["id"], mid))
                    kpi_moved += len(moved_)
                    _lm_name = db.execute("SELECT full_name FROM users WHERE id=?", (mid,)).fetchone()
                    _leader_log(db, me["id"], "set_manager", "%s -> %s (roster import)%s%s" % (
                        r["name"], _lm_name["full_name"] if _lm_name else r["mgr"],
                        ("; %d KPI line(s) moved" % len(moved_)) if moved_ else "", _ho_audit.get(uid_row["id"], "")),
                        uid_row["id"])
        if r["hod"]:
            hid, h_miss = _resolve_eid(r["hod"])
            if h_miss:
                unlinked += 1
            else:
                # the Leaders page's own rule at APPLY time (2026-11-08): the check judged the HOD against OneHR as it was, and the
                # file may since have moved the HOD or the person into another group, so an HOD that can't stand is left as it
                # was and counted. Each change leaves an audit row, as the Leaders page's does.
                cur_ = db.execute("SELECT * FROM users WHERE id=?", (uid_row["id"],)).fetchone()
                if cur_["hod_id"] != hid:
                    hrow = db.execute("SELECT * FROM users WHERE id=?", (hid,)).fetchone()
                    why_ = "Pick someone else." if hid == cur_["id"] else _hod_candidate_error(db, me, cur_["business_group"], hrow)
                    if why_:
                        if prof_out is not None:
                            prof_out["hod_refused"] = prof_out.get("hod_refused", 0) + 1
                        continue
                    was_ = db.execute("SELECT full_name FROM users WHERE id=?", (cur_["hod_id"],)).fetchone() if cur_["hod_id"] else None
                    db.execute("UPDATE users SET hod_id=? WHERE id=?", (hid, uid_row["id"]))
                    _line_moves.append({"uid": uid_row["id"], "kind": "hod", "old": cur_["hod_id"], "new": hid})
                    _leader_log(db, me["id"], "hod_assign", "%s (%s): %s -> %s (roster import)" % (
                        (cur_["department"] or "no department"), display_company(cur_["business_group"], cur_["company"]) or cur_["company"] or "no unit",
                        was_["full_name"] if was_ else "none", hrow["full_name"]), uid_row["id"])
    _notes = _line_changed(db, _line_moves, me["id"], bulk=True)   # the whole file's line changes, ONE call (2026-11-13)
    if prof_out is not None:
        prof_out["line_notes"] = _notes
    db.commit()
    # the seats last, now everyone in the file exists: through the Leaders page's own writers (row 8)
    for c in _roster_seat_changes(db, valid, None):
        if c["kind"] == "same" or c["eid"] in skip_seats:
            continue
        _ur = db.execute("SELECT id FROM users WHERE employee_id=?", (c["eid"],)).fetchone()
        if not _ur:
            continue
        for op in c["ops"]:
            if op[0] == "bu_add":
                _assign_buceo(db, me, _ur["id"], op[1], op[2])
            elif op[0] == "bu_take":
                _clear_buceo_unit(db, me, op[1], op[2])
            elif op[0] == "bg_set":
                _assign_bgceo(db, me, _ur["id"], op[1])
            elif op[0] == "bg_take":
                _clear_bgceo_unit(db, me, op[1])
            elif op[0] == "gc_set":
                _set_group_chief(db, me, op[1], _ur["id"])
    db.commit()
    left = 0
    if authoritative and seen:
        sc, sp = _roster_leaver_scope(me, chk.get("file_bgs") or {r["bg"] for r in valid})
        ph = ",".join("?" * len(seen))
        # each through _mark_user_inactive, as the Users page does: their pending assessments are archived, and each
        # gets its own audit row on their page (the admin review, 2026-10-13)
        gone = db.execute(f"SELECT id, full_name, employee_id FROM users WHERE role='user' AND left_at IS NULL "
                          f"AND is_demo=0 AND employee_id NOT IN ({ph})" + sc, list(seen) + sp).fetchall()
        _lcid = active_cycle_id(db)
        gone = [g_ for g_ in gone if g_["employee_id"] not in set(keep)]
        for g_ in gone:
            n_ = _mark_user_inactive(db, me["id"], _lcid, g_["id"])
            log_activity(db, me["id"], "mark_left", f"{g_['full_name']} ({g_['employee_id']}): marked left by roster "
                         "import" + (f" ({n_} assessment(s) archived)" if n_ else ""), target_user_id=g_["id"])
        left = len(gone)
    db.commit()
    log_activity(db, me["id"], "roster_import",
                 f"{created} created, {updated} updated, {reactivated} reactivated, {left} flagged left")
    for _bg, _units in _came.items():   # the admins over them hear once (2026-10-18; never whoever imported)
        _notify_joiners(db, me["id"], _bg, _units, len(_units))
    if _ho_mail:   # each new line manager hears once, after the commit; the old ones hear nothing
        if ho_out is not None:
            ho_out["people"] = sum(len(v) for v in _ho_mail.values())
            ho_out["emails"] = 0
        for lm_id, items in _ho_mail.items():
            lm_ = db.execute("SELECT * FROM users WHERE id=?", (lm_id,)).fetchone()
            if _lm_handover_email(db, lm_, items, handover_reason, _ho_cyc["id"]) == "Emailed them." and ho_out is not None:
                ho_out["emails"] += 1
    return created, updated, reactivated, left, unlinked, kpi_moved


def _roster_counts(db, me):
    """(active, left) people on the roster page: the whole company for the super admin, a group or unit admin's own
    people for them (finding 1a-03, 2026-10-31)."""
    sc, sp = bg_scope(me, "business_group")
    q = "SELECT COUNT(*) FROM users WHERE role='user' AND left_at %s AND is_demo=0" + sc
    return (db.execute(q % "IS NULL", sp).fetchone()[0], db.execute(q % "IS NOT NULL", sp).fetchone()[0])


# The People import in the four steps (2026-10-26): its own check and quality step, and two things for the super admin
# to answer at step 3 -- in a full roster, each person it would mark as left (or keep them), and each seat the file
# gives to someone else (or leave the seats as they are, the rest of that row still going in).
def _rimp_load(db, me, meta, data):
    return _roster_check(db, me, _read_records(meta["filename"], data), bool(meta.get("authoritative")))


def _rimp_stage(db, me, filename, data, opts):
    chk = _roster_check(db, me, _read_records(filename, data), bool(opts.get("authoritative")))
    if chk["errors"]:   # once a check, as before: the Ticketing agent says why a joiner never arrived
        _roster_note_refusals(db, me, chk, filename)
    return data


def _rimp_shown(x, side):
    """A change's value on screen: a job title or department in proper case (HRIS's capitals stay stored)."""
    v = x[side]
    if x["field"] == "Business group" and v and v != "none":
        return display_bg(v)
    return proper_name(v) if x["field"] in ("Job title", "Department") and v and v != "none" else v


def _rimp_answers(decisions):
    """(Employee IDs kept though the full roster leaves them out, Employee IDs whose seats stay as they are)."""
    keep = {k[6:] for k, v in decisions.items() if k.startswith("leave:") and v == "keep"}
    skip = {k[5:] for k, v in decisions.items() if k.startswith("seat:") and v == "keep"}
    return keep, skip


def _rimp_handover_answers(decisions):
    """(Employee IDs whose old line manager's work the super admin hands to the new one, the one reason for the file)."""
    ids = {k[9:] for k, v in decisions.items() if k.startswith("handover:") and v == "handover"}
    return ids, (decisions.get("reason:handover") or "").strip()


def _rimp_handover_rows(db, chk):
    """People the file gives a DIFFERENT line manager whose current one already did a part for them in the active cycle
    (moderated their KPIs, reviewed their competencies, closed their Career Plan): [{eid, name, id, old, new, old_name,
    new_name, parts: {part: n}, words}]. The new line manager must already be in OneHR. Batched, read-only."""
    cyc = active_cycle(db)
    if not cyc:
        return []
    cand = [r for r in chk["valid"] if r["existing_id"] and r["mgr"] and r["_existing"]["manager_id"]]
    if not cand:
        return []
    people = {}   # employee id -> (id, name)
    eids = list(dict.fromkeys(r["mgr"] for r in cand))
    for k in range(0, len(eids), 500):
        part = eids[k:k + 500]
        for u_ in db.execute("SELECT id, employee_id, full_name FROM users WHERE employee_id IN (%s)" % ",".join("?" * len(part)),
                             part):
            people[u_["employee_id"]] = (u_["id"], u_["full_name"])
    cand = [r for r in cand if r["mgr"] in people and people[r["mgr"]][0] != r["_existing"]["manager_id"]
            and people[r["mgr"]][0] != r["existing_id"]]
    done = _lm_done_many(db, cyc, [r["existing_id"] for r in cand])
    olds = {}
    oids = list({r["_existing"]["manager_id"] for r in cand if r["existing_id"] in done})
    for k in range(0, len(oids), 500):
        part = oids[k:k + 500]
        for u_ in db.execute("SELECT id, full_name FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part):
            olds[u_["id"]] = u_["full_name"]
    out = []
    for r in cand:
        parts = done.get(r["existing_id"])
        if not parts:
            continue
        words = [HANDOVER_LABEL[x] + (" (%d line%s)" % (parts[x], "" if parts[x] == 1 else "s") if x == "pm_mod" else "")
                 for x in HANDOVER_PARTS if x in parts]
        out.append({"eid": r["eid"], "name": r["name"], "id": r["existing_id"], "old": r["_existing"]["manager_id"],
                    "new": people[r["mgr"]][0], "old_name": olds.get(r["_existing"]["manager_id"], ""),
                    "new_name": people[r["mgr"]][1], "parts": parts, "words": ", ".join(words)})
    return out


def _rimp_cutoff(db, chk):
    """The cycle question the file raises when the active cycle has a confirmation cut-off (2 Nov 2026): None without a
    cycle or a cut-off, else {cyc, cut, late, early, late_by}. `late` = the people the file gives a confirmation date AFTER
    the cut-off (an existing person whose date changes, or a new joiner) who are at or above the cycle's lowest grade and
    not in a unit it leaves out, each {eid, name, date, facts}: the super admin answers Add them / Not this cycle for each.
    `early` = Employee IDs given a date on or before it, in the same scope (in by the rule; a standing take-out leaves them
    out of this list). Judged on who they will be after the file (its grade, unit and department where it gives one).
    Batched, read-only; a roster read by anyone but the super admin carries no dates, so it has none."""
    cyc = active_cycle(db)
    cut = confirm_cutoff_of(cyc) if cyc else None
    if not cut:
        return None
    dated = {x["eid"] for x in chk["changes"] if x["field"] == "Confirmation date"}
    cand = []
    for r in chk["valid"]:
        d = r["confirmed"]
        if not d or d == "1900-01-01" or (r["existing_id"] and r["eid"] not in dated):
            continue
        ex = r["_existing"]
        who = {"business_group": r["bg"], "company": r["company"] or (ex["company"] if ex else None),
               "department": r["dept"] or (ex["department"] if ex else None),
               "job_grade": r["grade"] if r["grade"] not in (None, "") else (ex["job_grade"] if ex else None)}
        if below_min_grade(db, who, cyc) is not None or unit_out(db, who, cyc):
            continue
        cand.append(r)
    ids = [r["existing_id"] for r in cand if r["existing_id"]]
    facts = _confirm_cycle_facts(db, cyc, ids) if ids else {}
    held = {}
    for k in range(0, len(ids), 500):
        part = ids[k:k + 500]
        for o in db.execute("SELECT subject_id, mode FROM cycle_participants WHERE cycle_id=? AND subject_id IN (%s)"
                            % ",".join("?" * len(part)), [cyc["id"]] + part):
            held[o[0]] = o[1]
    late, early = [], set()
    for r in cand:
        if r["confirmed"] > cut:
            kp, pn = facts.get(r["existing_id"], (0, 0))
            late.append({"eid": r["eid"], "name": r["name"], "date": r["confirmed"], "kpis": kp, "panel": pn,
                         "facts": " \u00b7 ".join((("%d KPI line%s" % (kp, "" if kp == 1 else "s")) if kp else "No KPI lines",
                                                  ("360 panel of %d" % pn) if pn else "no 360 panel"))})
        elif held.get(r["existing_id"]) != "remove":
            early.add(r["eid"])
    return {"cyc": cyc, "cut": cut, "late": late, "early": early, "late_by": {x["eid"]: x for x in late}}


def _rimp_cycle_answers(decisions):
    """{Employee ID: 'add' | 'out'} for the people the file confirms after the cut-off, as the super admin answered."""
    return {k[4:]: v for k, v in decisions.items() if k.startswith("cyc:") and v in ("add", "out")}


def _rimp_new_row(r):
    """The users row of an existing person as the file's UPDATE leaves it (preserve-on-blank, as _roster_apply writes it), with their
    leaving cleared: what the profile-change engine asks about."""
    ex = r["_existing"]
    return dict(ex, business_group=r["bg"], company=r["company"] or ex["company"], department=r["dept"] or ex["department"],
                job_title=r["title"] or ex["job_title"], job_grade=r["grade"] if r["grade"] not in (None, "") else ex["job_grade"],
                left_at=None)


def _rimp_file_says(old, new):
    """'JG 14 \u203a 15 \u00b7 Operations Executive \u203a Planning Executive': what the file changes of a person, in the words the answers
    table shows."""
    bits = []
    for k in _profile_diff(old, new):
        if k == "job_grade":
            bits.append("JG %s \u203a %s" % (_pf_val(old["job_grade"]) or "none", _pf_val(new["job_grade"]) or "none"))
        elif k == "job_title":
            bits.append("%s \u203a %s" % (proper_name(_pf_val(old["job_title"])) or "none", proper_name(_pf_val(new["job_title"])) or "none"))
        elif k == "department":
            bits.append("%s \u203a %s" % (proper_name(_pf_val(old["department"])) or "none", proper_name(_pf_val(new["department"])) or "none"))
        elif k == "company":
            bits.append("%s \u203a %s" % (display_company(old["business_group"], old["company"]) or "none",
                                             display_company(new["business_group"], new["company"]) or "none"))
    return " \u00b7 ".join(bits)


def _rimp_asks(db, me, chk):
    """What the people file asks the super admin about their competencies and Grade H (piece 3, board B1), the reads batched over the people
    the file changes: {"comp_re": rows, "comp_st": rows, "gh": rows, "stay": rows, "by_eid": {eid: {"comp": kind or None, "gh": kind or
    None}}, "f360": {eid: words}}. A row = {eid, name, says (the file says), cells…}. comp_re = a set nobody has started (or HR matched by
    hand), comp_st = a started one, gh = a Grade H person the file gives another grade, stay = the competencies that stay as they are
    (submitted, reviewed, results out, no profile at the new grade). Read only."""
    act = active_cycle(db)
    out = {"comp_re": [], "comp_st": [], "gh": [], "rater": [], "left": {}, "stay": [], "by_eid": {}, "f360": {}, "act": act}
    if not act:
        return out
    pairs, who = [], {}
    for r in chk["valid"]:
        if r["existing_id"] and r.get("_existing") is not None:
            o, n = dict(r["_existing"]), _rimp_new_row(r)
            if _profile_diff(o, n):
                pairs.append((o, n))
                who[o["id"]] = r
    if not pairs:
        return out
    am = _profile_asks_many(db, me, act, pairs)
    counts = _profile_360_counts_many(db, act["id"], [o["id"] for o, _n in pairs])
    for o, n in pairs:
        r = who[o["id"]]
        eid, name = r["eid"], r["name"]
        c, g_, r_ = am[o["id"]]["comp"], am[o["id"]]["gh"], am[o["id"]]["rater"]
        out["by_eid"][eid] = {"comp": c["kind"] if c and c.get("ask") else None, "gh": g_["kind"] if g_ else None,
                              "rater": r_["kind"] if r_ and r_.get("ask") else None}
        if r_:   # into a unit the cycle leaves out (2026-11-09): what they give and moderate stops; submitted ratings are asked
            out["left"][eid] = r_
            if r_.get("ask"):
                if r_.get("path") == "unit_out":
                    unit_ = display_company(n["business_group"], n["company"]) or n["company"] or ""
                else:   # a grade below the cycle's lowest, or Grade H (2026-11-09): the cell names the grade the file gives
                    g_n = _pf_val(n["job_grade"])
                    unit_ = "Grade H" if is_grade_h(n) else ("JG " + g_n) if g_n.isdigit() else ("Grade " + g_n) if g_n else "No job grade"
                out["rater"].append({"eid": eid, "name": name, "id": o["id"], "says": _rimp_file_says(o, n), "state": r_,
                                     "unit": unit_, "main": "%d submitted" % (r_["S"] + r_["R"]),
                                     "sub": "\n".join(
                                         ["%s%s" % ("%d scores change" % r_["S"] if r_["S"] != 1 else "1 score changes",
                                                    (" \u00b7 %d below a full panel" % r_["K"]) if r_["K"] else "")]
                                         + ([("%d stays: result decided" % r_["R"]) if r_["R"] == 1 else
                                             ("%d stay: results decided" % r_["R"])] if r_["R"] else []))})
        words = _profile_tier_note(o, n, act, counts[o["id"]])
        if words and counts[o["id"]][0]:
            tier = tier_for_grade(n["job_grade"], effective_tiers(act))
            out["f360"][eid] = "%d 360 rating%s move to JG %s" % (counts[o["id"]][0], "" if counts[o["id"]][0] == 1 else "s",
                                                                 tier["grades"].replace("JG ", ""))
        says = _rimp_file_says(o, n)
        if c and c.get("ask"):
            same = c["same_titles"]
            if c["kind"] == "started":
                if c["counts"]["removed_answered"]:
                    sub = ("All %d change level, so the %d answer%s go" % (c["n_lines"], c["counts"]["removed_answered"],
                                                                         "" if c["counts"]["removed_answered"] == 1 else "s")) \
                        if same else "%d new, %d go; the %d answer%s on the ones that go go with them" % (
                            c["n_new"], c["n_go"], c["counts"]["removed_answered"], "" if c["counts"]["removed_answered"] == 1 else "s")
                else:
                    sub = "No answer goes"
                out["comp_st"].append({"eid": eid, "name": name, "id": o["id"], "says": says, "state": c,
                                       "main": "%d of %d answered" % (c["n_answered"], c["n_lines"]), "sub": sub})
            else:
                if same:
                    main = "Same %d, %s" % (c["n_in"], c["way"])
                    sub = "%s becomes %s" % (c["levels_old"], c["levels_new"])
                else:
                    main = "All %d change" % c["n_in"] if c["n_in"] - c["n_new"] == 0 else "%d of %d change" % (c["n_new"], c["n_in"])
                    sub = "%d new, %d go" % (c["n_new"], c["n_go"])
                out["comp_re"].append({"eid": eid, "name": name, "id": o["id"], "says": says, "state": c, "main": main, "sub": sub})
        elif c and c.get("stay"):
            out["stay"].append({"eid": eid, "name": name, "words": c["stay"]})
        if g_ and g_.get("ask"):
            out["gh"].append({"eid": eid, "name": name, "id": o["id"], "says": says, "state": g_, "main": g_["title"]})
    return out


def _rimp_ask_groups(asks, decisions):
    """The three decide groups of board B1 (competencies to reassign, started their self-assessment, out of Grade H) for _rimp_changes,
    from _rimp_asks's rows. No row is pre-picked: an import asks every one. The swap's reason is ONE for the file, needed when any is
    swapped; a submitted Grade H appraisal taken off the list needs one too."""
    groups = []
    if asks["comp_re"]:
        groups.append({
            "title": "Competencies to reassign (%d)" % len(asks["comp_re"]),
            "sub": "The file changes their grade or job; they haven't started their self-assessment",
            "why": "Reassign: they get the new job's set; nothing of theirs is lost. Keep their set: it stays as it is, and you can "
                   "change it on their Competency tab later.",
            "options": [("reassign", "Reassign"), ("keep", "Keep their set")],
            "head": ["Person", "The file says", "Competencies"],
            "items": [{"key": "comp:" + x["eid"], "label": "%s (%s): %s" % (x["name"], x["eid"], x["says"]),
                       "cells": [(x["name"], x["eid"]), x["says"], (x["main"], x["sub"])]} for x in asks["comp_re"]]})
    if asks["comp_st"]:
        groups.append({
            "title": "Started their self-assessment (%d)" % len(asks["comp_st"]),
            "sub": "The file changes their grade or job; they have answered some, nothing is submitted",
            "why": "Keep their set: their set and answers stay. Swap: a competency both sets hold at the same level keeps its answer; "
                   "the others go with theirs and their line manager's, and they're emailed what changed.",
            "options": [("keep", "Keep their set"), ("swap", "Swap")],
            "head": ["Person", "The file says", "Competencies"],
            "items": [{"key": "comp:" + x["eid"], "label": "%s (%s): %s" % (x["name"], x["eid"], x["says"]),
                       "cells": [(x["name"], x["eid"]), x["says"], (x["main"], x["sub"])]} for x in asks["comp_st"]],
            "reason": {"key": "reason:comp", "needs": "swap", "max": REOPEN_REASON_MAX, "rows": 2,
                       "label": "Why their competencies are swapped", "value": decisions.get("reason:comp") or "",
                       "help": "Needed when any is swapped: one reason for this file. It goes in the trail.",
                       "missing": "Give the reason for the swaps: it goes in the trail."}})
    if asks["gh"]:
        sub = {x["eid"] for x in asks["gh"] if x["state"]["kind"] == "submitted"}
        g = {"title": "Out of Grade H (%d)" % len(asks["gh"]),
             "sub": "The file gives a Grade H person a number grade",
             "why": "Take off the list: their Grade H appraisal closes (kept in the record) and they take part in the normal review. "
                    "Keep on the list: their appraisal carries on and they're out of the normal review this cycle.",
             "options": [("off", "Take off the list"), ("keep", "Keep on the list")],
             "head": ["Person", "The file says", "Their Grade H appraisal"],
             "items": [{"key": "gh:" + x["eid"], "label": "%s (%s): %s" % (x["name"], x["eid"], x["says"]),
                        "cells": [(x["name"], x["eid"]), x["says"], x["main"]]} for x in asks["gh"]]}
        if sub:
            g["reason"] = {"key": "reason:gh", "needs": "off", "only": {"gh:" + e for e in sub}, "max": REOPEN_REASON_MAX, "rows": 2,
                           "label": "Why a submitted Grade H appraisal is closed", "value": decisions.get("reason:gh") or "",
                           "help": "Needed when an appraisal someone has submitted is taken off the list: one reason for this file. It goes "
                                   "in the trail.",
                           "missing": "Give the reason for closing a submitted Grade H appraisal: it goes in the trail."}
        groups.append(g)
    if asks["rater"]:   # moved into a unit the cycle leaves out: the ratings they already submitted (2026-11-09; canvas, provisional)
        cname = asks["act"]["name"]
        n_gr = sum(1 for x in asks["rater"] if x["state"].get("path") != "unit_out")
        groups.append({
            "title": "Their submitted 360 ratings of colleagues (%d)" % len(asks["rater"]),
            "sub": ("The file moves them to a unit that isn't taking part in %s" % cname) if not n_gr else
                   ("The file gives them a job grade that isn't taking part in %s" % cname) if n_gr == len(asks["rater"]) else
                   ("The file moves them to a unit or gives them a job grade that isn't taking part in %s" % cname),
            "why": "Keep: their submitted ratings stay and still count. Archive: the ratings come out of those colleagues' 360 scores, so the "
                   "scores change; the panel editor can restore them. Ratings of colleagues whose results are decided stay either way.",
            "options": [("keep", "Keep"), ("archive", "Archive")],
            "head": ["Person", "The file says", "Their submitted ratings"],
            "recap_by": [("keep", "Keep their submitted 360 ratings"), ("archive", "Archive their submitted 360 ratings")],
            "items": [{"key": "rater:" + x["eid"], "label": "%s (%s)" % (x["name"], x["eid"]), "default": "keep",
                       "short": "%s (%s)" % (x["name"], x["eid"]),
                       "cells": [(x["name"], x["eid"]), (x["unit"], "Not taking part"), (x["main"], x["sub"])]} for x in asks["rater"]],
            "reason": {"key": "reason:rater", "needs": "archive", "max": REOPEN_REASON_MAX, "rows": 2,
                       "label": "Why their ratings are archived", "value": decisions.get("reason:rater") or "",
                       "help": "500 at most. Needed when any row is Archive. It goes in the trail with the counts.",
                       "missing": "Give the reason for archiving submitted 360 ratings: it goes in the trail."}})
    return groups


def _rimp_ask_answers(asks, decisions):
    """{Employee ID: the answers _roster_apply takes} from the super admin's decisions, with what each was shown (`expect`)."""
    out = {}
    for eid, k in asks["by_eid"].items():
        out[eid] = {"competency": decisions.get("comp:" + eid), "gradeh": decisions.get("gh:" + eid),
                    "rater360": decisions.get("rater:" + eid) or ("keep" if (k["rater"] or "") else None),
                    "reason": {"competency": decisions.get("reason:comp") or "", "gradeh": decisions.get("reason:gh") or "",
                               "rater360": decisions.get("reason:rater") or ""},
                    "notify": True, "expect": {"competency": k["comp"], "gradeh": k["gh"], "rater360": k["rater"]}}
    return out


def _rimp_line_follow(db, chk):
    """What a file's line manager and HOD changes make follow in the other modules (2026-11-13, _line_change_plan, the dry run of what
    _roster_apply hands to _line_changed): {"lm": note, "hod": note, "stays": [words]} for the Changes step. The notes are one muted phrase
    for the chip ("Grade H Appraisal follows for 12 people; stays with the old HOD for 2"), never a line a person: an import changes hundreds.
    The same changes _roster_apply makes: a person who exists and whose link the file moves. Reads only."""
    want, eids = [], set()
    for r in chk["valid"]:
        ex = r.get("_existing")
        if ex and (r.get("mgr") or r.get("hod")):
            want.append(r)
            eids |= {x for x in (r.get("mgr"), r.get("hod")) if x}
    ids = {}
    el = sorted(eids)
    for k in range(0, len(el), 500):
        part = el[k:k + 500]
        for u in db.execute("SELECT id, employee_id FROM users WHERE employee_id IN (%s)" % ",".join("?" * len(part)), part):
            ids[u["employee_id"]] = u["id"]
    changes = []
    for r in want:
        ex = r["_existing"]
        for key, kind, col in (("mgr", "lm", "manager_id"), ("hod", "hod", "hod_id")):
            new = ids.get(r.get(key)) if r.get(key) else None
            if new and new != ex[col] and new != ex["id"]:
                changes.append({"uid": ex["id"], "kind": kind, "old": ex[col], "new": new})
    out = {"lm": "", "hod": "", "stays": []}
    if not changes:
        return out
    plan = _line_change_plan(db, changes)
    for kind, key in (("lm", "lm"), ("hod", "hod")):
        moves, stays = plan["tally"].get(key, (0, 0))
        if moves or stays:
            what = "appraiser" if kind == "lm" else "HOD"
            out[key] = "Grade H Appraisal's %s follows for %s%s" % (
                what, _line_count_words(moves), ("; stays for %s (locked)" % _line_count_words(stays)) if stays else "")
    out["stays"] = list(plan.get("stays", []))
    return out


def _rimp_changes(db, me, chk, decisions):
    c = chk["counts"]
    lf = _rimp_line_follow(db, chk)
    tiles = [(c["add"], "to add", "#1a7a54"), (c["update"], "to update", "#2f64d6")]
    if c["back"]:
        tiles.append((c["back"], "back from leaving", "#2f64d6"))
    if c["same"]:
        tiles.append((c["same"], "no change", "#9aa1b5"))
    if chk["authoritative"]:
        tiles.append((c["leave"], "not in the file", "#e0a84a"))
    sections = []
    if chk["changes"]:
        sections.append({
            "title": "What the %s update%s change" % ("{:,}".format(c["update"]), "" if c["update"] == 1 else "s"),
            "dl": "changes",
            "chips": [(f, n, {"Business group": "their calibrators, KPI scale and admins follow the group",
                              "Business unit": "their BU CEO changes",
                              "HOD": "their department review moves" + ("; " + lf["hod"] if lf["hod"] else ""),
                              "Line manager": "unmoderated KPI lines move" + ("; " + lf["lm"] if lf["lm"] else "")}.get(f))
                      for f, n in sorted(chk["by_field"].items())],
            "head": ["Person", "Field", "From", "To"],
            "rows": [[(x["name"], x["eid"]), x["field"], _rimp_shown(x, "from"), _rimp_shown(x, "to")]
                     for x in chk["changes"][:12]],
            "more": max(0, len(chk["changes"]) - 12)})
    if lf["stays"]:   # information only (2026-11-13): Grade H keeps who signed, the main change still goes
        sections.append({"title": "Stays as it is in other modules (%d)" % len(lf["stays"]),
                         "note": "The line or HOD in the file still changes everywhere else. Grade H keeps who signed where it is locked; CSF items stay with whoever holds them.",
                         "list": lf["stays"][:40] + (["and %d more." % (len(lf["stays"]) - 40)] if len(lf["stays"]) > 40 else [])})
    mv = chk.get("moved_rows") or []
    if mv:   # information only (a unit moved to another group, 2026-11-06): the file still names the old group
        def _when(r):
            row = db.execute("SELECT moved_at FROM org_unit_moves WHERE company=? AND from_bg=? AND to_bg=? ORDER BY id DESC LIMIT 1",
                             (r["company"], r["from"], r["to"])).fetchone()
            d = _parse_when(_myt(row[0])) if row else None
            return " on " + d.strftime("%-d %b %Y") if d else ""
        sections.append({"title": "Filed under a unit's new group (%d)" % len(mv),
                         "note": "Group People's file still names the group these units used to belong to. OneHR files them under their new "
                                 "group until Group People's file names it.",
                         "list": ["%s (%s): filed under %s (moved from %s%s)" % (
                             r["name"], r["eid"], display_bg(r["to"]), display_bg(r["from"]), _when(r)) for r in mv[:40]]})
    plain = [x for x in chk["seat_changes"] if x["kind"] in ("add", "take")]
    if plain:
        sections.append({"title": "Role changes (%d)" % len(plain), "cls": "ri-seats",
                         "list": ["%s: %s (%s), %s%s" % ("Adds" if x["kind"] == "add" else "Takes away", x["name"],
                                                         x["eid"], x["what"], (" " + x["note"]) if x["note"] else "")
                                  for x in plain[:40]]})
    new = [r for r in chk["valid"] if not r["existing_id"]]
    if new:
        sections.append({"title": "New joiners (%d)" % len(new),
                         "head": ["Person", "Business unit", "Job", "Line manager"],
                         "rows": [[(r["name"], r["eid"]), display_company(r["bg"], r["company"]) or r["company"],
                                   proper_name(r["title"] or "") or "", r["mgr"] or ""] for r in new[:12]],
                         "more": max(0, len(new) - 12)})
    asks = _rimp_asks(db, me, chk)
    if asks["stay"]:   # information only (piece 3, board B1): the competencies that stay as they are
        sections.append({"title": "Their competencies stay as they are (%d)" % len(asks["stay"]),
                         "list": ["%s (%s): %s" % (x["name"], x["eid"], x["words"]) for x in asks["stay"][:40]]
                         + (["and %d more." % (len(asks["stay"]) - 40)] if len(asks["stay"]) > 40 else [])})
    decide = []
    swaps = [x for x in chk["seat_changes"] if x["kind"] == "swap"]
    if swaps:
        decide.append({
            "title": "A seat the file gives to someone else (%d)" % len(swaps),
            "why": "Make the change: they take the seat and the person holding it now stops. Leave the seats: nobody's "
                   "seat moves for this row, and the rest of their row still goes in.",
            "options": [("swap", "Make the change"), ("keep", "Leave the seats")],
            "head": ["Person", "The file says", "Who it's taken from"],
            "items": [{"key": "seat:" + x["eid"], "label": "%s (%s): %s" % (x["name"], x["eid"], x["what"]),
                       "cells": [(x["name"], x["eid"]), x["what"], x["note"]]} for x in swaps]})
    if chk["authoritative"] and chk["would_leave"]:
        decide.append({
            "title": "Not in the file (%d)" % len(chk["would_leave"]),
            "sub": "a full roster marks them as left",
            "why": "Mark as left: their sign-in closes and their data is kept. Keep them: they stay active, as if the "
                   "file had them.",
            "options": [("leave", "Mark as left"), ("keep", "Keep them")],
            "head": ["Person", "Business unit", "Job"],
            "items": [{"key": "leave:" + u["employee_id"], "label": "%s (%s)" % (u["full_name"], u["employee_id"]),
                       "cells": [(u["full_name"], u["employee_id"]),
                                 display_company(u["business_group"], u["company"]) or (u["company"] or ""),
                                 proper_name(u["job_title"] or "") or ""]} for u in chk["would_leave"]]})
    ho = _rimp_handover_rows(db, chk)
    if ho:   # the old line manager already did their part (Chris, 2026-10-30; canvas "Line manager change: hand over", board 4)
        decide.append({
            "title": "Their old line manager already did their part (%d)" % len(ho),
            "sub": "The file gives them a new line manager",
            "why": "Keep it: what the old line manager did stands. Hand it over: it's cleared and goes to the new line "
                   "manager to redo, even after the line manager window closes, until results are released.",
            "options": [("keep", "Keep it"), ("handover", "Hand it over")],
            "head": ["Person", "Line manager: old › new", "Already done"],
            "items": [{"key": "handover:" + x["eid"], "label": "%s (%s): %s" % (x["name"], x["eid"], x["words"]),
                       "cells": [(x["name"], x["eid"]), "%s › %s" % (x["old_name"], x["new_name"]), x["words"]]}
                      for x in ho],
            # one reason for the whole file, kept with the answers; required when any row is "Hand it over"
            "reason": {"key": "reason:handover", "needs": "handover", "max": REOPEN_REASON_MAX, "rows": 2,
                       "label": "Why they go to the new line manager", "value": decisions.get("reason:handover") or "",
                       "help": "Needed when any is handed over: one reason for this file. Each new line manager sees it in "
                               "their email.",
                       "missing": "Give the reason for the hand-overs: each new line manager sees it."}})
    cy = _rimp_cutoff(db, chk)
    if cy and cy["late"]:   # a confirmation date after the cycle's cut-off (Chris, 2 Nov 2026; canvas board 4)
        decide.append({
            "title": "Confirmed after the cycle's cut-off (%d)" % len(cy["late"]),
            "sub": "The file gives a confirmation date after %s" % _st_day(cy["cut"]),
            "why": "Add them: they take part in %s from their confirmation date. Not this cycle: no review of their own in "
                   "%s, and any 360 rows about them are archived; they keep their Career Plan, still rate colleagues on the "
                   "360 and review their team. Back to the confirmation rule on Participants undoes either." % (cy["cyc"]["name"], cy["cyc"]["name"]),
            "options": [("add", "Add them"), ("out", "Not this cycle")],
            "head": ["Person", "Confirmation date", "Already set up"],
            "items": [{"key": "cyc:" + x["eid"], "label": "%s (%s)" % (x["name"], x["eid"]),
                       "cells": [(x["name"], x["eid"]), _st_day(x["date"]), x["facts"]]} for x in cy["late"]]})
    decide += _rimp_ask_groups(asks, decisions)
    fp = [c, [(x["eid"], x["field"], x["to"]) for x in chk["changes"]],
          [(g_["title"], [(it["key"], it["cells"][2]) for it in g_["items"]]) for g_ in _rimp_ask_groups(asks, {})],
          [(x["eid"], x["ops"]) for x in chk["seat_changes"]], sorted(u["employee_id"] for u in chk["would_leave"]),
          [(x["eid"], x["old"], x["new"], sorted(x["parts"].items())) for x in ho],
          ([cy["cut"], [(x["eid"], x["date"], x["kpis"], x["panel"]) for x in cy["late"]], sorted(cy["early"])]
           if cy else None)]
    return {"tiles": tiles, "sections": sections, "decide": decide, "fp": fp}


def _rimp_people(chk, decisions, ho=None, cy=None, asks=None):
    """Each person the file touches, after the answers: [(Employee ID, name, what happens)]. `ho` is
    _rimp_handover_rows by Employee ID: those answered "Hand it over" say what goes to their new line manager. `cy` is
    _rimp_cutoff's picture: a person given a confirmation date says whether they are in the cycle. `asks` is _rimp_asks's picture:
    a person with answers says what each does (competencies, Grade H), and a pending 360 rating that follows a new tier says so."""
    keep, skip = _rimp_answers(decisions)
    asked = {}
    for grp in ("comp_re", "comp_st", "gh", "rater"):
        for x in (asks or {}).get(grp, ()):
            asked.setdefault(x["eid"], {})[grp] = x
    fields = {}
    for x in chk["changes"]:
        fields.setdefault(x["eid"], []).append(x["field"])
    seats = {x["eid"]: x for x in chk["seat_changes"] if x["kind"] != "same"}
    out = []
    for r in chk["valid"]:
        says = []
        if not r["existing_id"]:
            says.append("Added")
        elif r["_existing"]["left_at"]:
            says.append("Back from leaving")
        if fields.get(r["eid"]):
            says.append("Updated: " + ", ".join(fields[r["eid"]]))
        sc = seats.get(r["eid"])
        if sc:
            says.append(("Seats left as they are" if r["eid"] in skip else sc["what"]))
        h_ = (ho or {}).get(r["eid"])
        if h_ and decisions.get("handover:" + r["eid"]) == "handover":
            says.append("%s's %s handed to %s" % (h_["old_name"], h_["words"], h_["new_name"]))
        text = "; ".join(says)
        a_ = asked.get(r["eid"], {})
        parts = []
        for grp in ("comp_re", "comp_st"):
            x = a_.get(grp)
            if x:
                ans = decisions.get("comp:" + r["eid"])
                st = x["state"]
                job = proper_name(st["profile"]["job_title"] or "")
                parts.append(
                    ("competencies reassigned to %s%s (your answer)" % (job, (", %s" % st["levels_new"]) if st["same_titles"] else ""))
                    if ans == "reassign" else
                    ("competencies kept%s (your answer)" % ((" at %s" % st["levels_old"]) if st["same_titles"] else "")) if ans == "keep" else
                    ("competencies swapped to %s (your answer; they're emailed what changed)" % job) if ans == "swap" else
                    "competencies: not answered yet")
        x = a_.get("gh")
        if x:
            ans = decisions.get("gh:" + r["eid"])
            parts.append("off the Grade H list, in the normal review (your answer)" if ans == "off" else
                         "kept on the Grade H list, out of the normal review this cycle (your answer)" if ans == "keep" else
                         "Grade H list: not answered yet")
        x = a_.get("rater")
        lo = (asks or {}).get("left", {}).get(r["eid"])
        if lo:   # into a unit the cycle leaves out: what stops with it, then the answer about their submitted ratings
            if lo["pending"]:
                parts.append("pending ratings archived")
            if lo["lines"]:
                parts.append("%s moved one level up" % _pl(lo["lines"], "KPI line"))
        if x:
            ans = decisions.get("rater:" + r["eid"]) or "keep"
            st_ = x["state"]
            parts.append(("%s stay (your answer)" % _pl(st_["S"] + st_["R"], "submitted 360 rating")) if ans == "keep" else
                         "%s archived%s (your answer)" % (_pl(st_["S"], "submitted 360 rating"), (
                             ", %d stay%s: result decided" % (st_["R"], "s" if st_["R"] == 1 else "")) if st_["R"] else ""))
        if (asks or {}).get("f360", {}).get(r["eid"]):
            parts.append(asks["f360"][r["eid"]])
        if parts:
            text = (text + " \u00b7 " if text else "") + " \u00b7 ".join(parts)
        if cy:   # the cycle outcome of a confirmation date (2 Nov 2026), after the super admin's answer
            late = cy["late_by"].get(r["eid"])
            cname = cy["cyc"]["name"]
            if late:
                ans = decisions.get("cyc:" + r["eid"])
                says_cy = ("in %s from %s (your answer)" % (cname, _st_day(late["date"]))) if ans == "add" else (
                    ("not in %s (your answer)" % cname) if ans == "out" else "this cycle: not answered yet")
            elif r["eid"] in cy["early"]:
                says_cy = "in %s (on or before the cut-off)" % cname
            else:
                says_cy = ""
            if says_cy:
                text = (text + " \u00b7 " if text else "") + says_cy
        if text:
            out.append((r["eid"], r["name"], text))
    for u in chk["would_leave"]:
        out.append((u["employee_id"], u["full_name"], "Kept: not in the file, stays active" if u["employee_id"] in keep
                    else "Marked as left: their sign-in closes, their data is kept"))
    return out


def _rimp_after(db, me, chk, decisions):
    keep, skip = _rimp_answers(decisions)
    c = chk["counts"]
    leaving = sum(1 for u in chk["would_leave"] if u["employee_id"] not in keep)
    n_seats = sum(1 for x in chk["seat_changes"] if x["kind"] != "same" and x["eid"] not in skip)
    tiles = [(c["add"], "added", "#1a7a54"), (c["update"], "updated", "#2f64d6")]
    if c["back"]:
        tiles.append((c["back"], "back from leaving", "#2f64d6"))
    if n_seats:
        tiles.append((n_seats, "role change%s" % ("" if n_seats == 1 else "s"), "#252A59"))
    if chk["authoritative"]:
        tiles.append((leaving, "marked as left", "#e0a84a"))
        if keep:
            tiles.append((len(keep), "kept", "#9aa1b5"))
    ho = {x["eid"]: x for x in _rimp_handover_rows(db, chk)}
    cy = _rimp_cutoff(db, chk)
    asks = _rimp_asks(db, me, chk)
    people = _rimp_people(chk, decisions, ho, cy, asks)
    n_re = sum(1 for x in asks["comp_re"] + asks["comp_st"] if decisions.get("comp:" + x["eid"]) in ("reassign", "swap"))
    n_gh = sum(1 for x in asks["gh"] if decisions.get("gh:" + x["eid"]) == "off")
    if n_re:   # piece 3, board B2: two tiles more
        tiles.append((n_re, "competencies reassigned", "#252A59"))
    if n_gh:
        tiles.append((n_gh, "off the Grade H list", "#252A59"))
    n_ra = sum(x["state"]["S"] for x in asks["rater"] if decisions.get("rater:" + x["eid"]) == "archive")
    p_ra = sum(1 for x in asks["rater"] if decisions.get("rater:" + x["eid"]) == "archive")
    p_rk = sum(1 for x in asks["rater"] if (decisions.get("rater:" + x["eid"]) or "keep") == "keep")
    if p_rk:   # moved into a unit the cycle leaves out, their submitted ratings kept (grey edge) or archived (red edge, the danger red)
        tiles.append((p_rk, "keep their submitted 360 ratings", "#9aa1b5"))
    if p_ra:
        tiles.append((p_ra, "have submitted 360 ratings archived", "#b3261e"))
    n_ho = sum(1 for e in ho if decisions.get("handover:" + e) == "handover")
    if n_ho:
        tiles.append((n_ho, "handed to a new line manager", "#252A59"))
    cy_ans = _rimp_cycle_answers(decisions) if cy else {}
    n_cy_in = (len(cy["early"]) + sum(1 for x in cy["late"] if cy_ans.get(x["eid"]) == "add")) if cy else 0
    n_cy_out = sum(1 for x in cy["late"] if cy_ans.get(x["eid"]) == "out") if cy else 0
    if cy and (n_cy_in or n_cy_out):   # the cycle's two outcomes of the confirmation dates in the file (canvas board 5)
        tiles.append((n_cy_in, "in %s" % cy["cyc"]["name"], "#252A59"))
        tiles.append((n_cy_out, "not this cycle", "#9aa1b5"))
    return {"lede": "%s %s change." % ("{:,}".format(len(people)), "person" if len(people) == 1 else "people"),
            "tiles": tiles, "table_title": "Each person after the import", "head": ["Person", "What happens"],
            "rows": [[(n, e), s] for e, n, s in people[:30]], "more": max(0, len(people) - 30),
            "confirm": "%d added, %d updated%s%s%s%s. This changes the live people records; the backup taken "
                       "first is the way back." % (
                           c["add"], c["update"],
                           (", %d back from leaving" % c["back"]) if c["back"] else "",
                           (", %d role change%s" % (n_seats, "" if n_seats == 1 else "s")) if n_seats else "",
                           (", and %d marked as left (their sign-in closes; their data is kept)" % leaving)
                           if chk["authoritative"] else "",
                           (", %d put in %s and %d left out of it (their 360 rows as the person rated archived)" % (
                               n_cy_in, cy["cyc"]["name"], n_cy_out)) if cy and (n_cy_in or n_cy_out) else "")
            + ((" %d competency set%s reassigned or swapped, %d taken off the Grade H list." % (
                n_re, "" if n_re == 1 else "s", n_gh)) if n_re or n_gh else "")
            + ((" %s archived, taken out of those colleagues' 360 scores." % _pl(n_ra, "submitted 360 rating")) if n_ra else "")}


def _rimp_apply(db, me, chk, decisions):
    keep, skip = _rimp_answers(decisions)
    ho_ids, ho_reason = _rimp_handover_answers(decisions)
    ho_out, prof_out = {}, {}
    cy = _rimp_cutoff(db, chk)   # the picture the super admin answered, taken before the file's rows go in
    asks = _rimp_asks(db, me, chk)   # likewise: what the super admin was shown, so a person who has moved on since is left as they are
    created, updated, reactivated, left, unlinked, kpi_moved = _roster_apply(
        db, me, chk, keep=keep, skip_seats=skip, handover=ho_ids, handover_reason=ho_reason, ho_out=ho_out, prof_out=prof_out,
        asks=_rimp_ask_answers(asks, decisions))
    cy_in = cy_out = cy_arch = cy_skip = 0
    if cy and cy["late"]:   # the answers on confirmation dates after the cut-off, once the people rows are written
        cy_ans = _rimp_cycle_answers(decisions)
        for x in cy["late"]:
            ans = cy_ans.get(x["eid"])
            uid_ = db.execute("SELECT id FROM users WHERE employee_id=?", (x["eid"],)).fetchone()
            if not ans or not uid_:
                cy_skip += 1
                continue
            rows_, why_ = _confirm_cycle_choice(db, me, cy["cyc"], uid_["id"], x["date"], ans, "import")
            if why_:
                cy_skip += 1
                continue
            if ans == "add":
                cy_in += 1
            else:
                cy_out += 1
                cy_arch += rows_[0]
        db.commit()
    if keep or skip:
        log_activity(db, me["id"], "roster_import", "the super admin's answers: %s%s" % (
            ("kept %d not in the file (%s)" % (len(keep), ", ".join(sorted(keep)[:40]))) if keep else "",
            ("%sseats left as they are for %d (%s)" % ("; " if keep else "", len(skip), ", ".join(sorted(skip)[:40])))
            if skip else ""))
        db.commit()
    lines = []
    if ho_out.get("people"):
        log_activity(db, me["id"], "roster_import", "the super admin's answers: the old line manager's work handed to the new "
                     "one for %d (%s); reason: %s" % (ho_out["people"], ", ".join(sorted(ho_ids)[:40]), ho_reason[:300]))
        lines.append("%d %s handed over to the new line manager%s." % (
            ho_out["people"], "person's work was" if ho_out["people"] == 1 else "people's work was",
            (" (%d email%s sent)" % (ho_out["emails"], "" if ho_out["emails"] == 1 else "s")) if ho_out.get("emails") else ""))
    if cy_in or cy_out or cy_skip:
        lines.append("Confirmed after %s's cut-off: %d added to it, %d left out (%d 360 row%s as the person rated archived)%s." % (
            cy["cyc"]["name"], cy_in, cy_out, cy_arch, "" if cy_arch == 1 else "s",
            (", %d could not be done (they are below its lowest grade or in a unit it leaves out now)" % cy_skip) if cy_skip else ""))
    if ho_out.get("skipped"):
        lines.append("%d hand-over%s could not be done (what the old line manager did had changed): left as it was." % (
            ho_out["skipped"], "" if ho_out["skipped"] == 1 else "s"))
    if unlinked:
        lines.append("%d row%s had a line manager or HOD Employee ID not found in the file or OneHR: those links were "
                     "left as they were." % (unlinked, "" if unlinked == 1 else "s"))
    if chk["authoritative"]:
        lines.append("%d marked as left%s." % (left, (", %d kept" % len(keep)) if keep else ""))
    if kpi_moved:
        lines.append("%d KPI line%s nobody had moderated moved to the new line manager." % (
            kpi_moved, "" if kpi_moved == 1 else "s"))
    _ln = prof_out.get("line_notes") or []   # what the line follow-through did in the other modules (2026-11-13): a few lines, never hundreds
    lines += _ln[:6] + (["and %d more follow-through notes (each Grade H change is in the audit log)." % (len(_ln) - 6)] if len(_ln) > 6 else [])
    # what a change of group, unit, department or grade made follow (the profile-change engine, 2026-11-08), one line a kind
    n_ = prof_out.get("bg_moves")
    if n_:
        lines.append("%d %s moved business group: %s." % (
            n_, "person" if n_ == 1 else "people", ("%d with KPI lines left on the old group's scale, to set later (the super admins "
                                                    "have an email)" % prof_out["bg_pending"]) if prof_out.get("bg_pending")
            else "their KPI lines, BU KPIs and calibration followed"))
    n_ = prof_out.get("unit_moves")
    if n_:
        lines.append("%d %s KPI lines moved to their new unit or department." % (n_, "person's" if n_ == 1 else "people's"))
    n_ = prof_out.get("grade_follow")
    if n_:
        lines.append("%d %s BU KPI lines followed their new grade." % (n_, "person's" if n_ == 1 else "people's"))
    n_ = prof_out.get("picks_removed")
    if n_:
        lines.append("%d BU calibration pick%s taken away: the group doesn't hold the new unit." % (n_, "" if n_ == 1 else "s"))
    n_ = prof_out.get("participation_flips")
    if n_:
        lines.append("%d %s 360 ratings as the person rated were archived or brought back: their details changed whether they "
                     "take part." % (n_, "person's" if n_ == 1 else "people's"))
    n_ = prof_out.get("retier_ratings")
    if n_:
        lines.append("%d pending 360 rating%s moved onto their subject's new tier." % (n_, "" if n_ == 1 else "s"))
    if prof_out.get("comp_reassigned") or prof_out.get("comp_swapped"):
        lines.append("%d competency set%s reassigned to the new job's, %d swapped (a swap emails them what changed)." % (
            prof_out.get("comp_reassigned", 0), "" if prof_out.get("comp_reassigned", 0) == 1 else "s", prof_out.get("comp_swapped", 0)))
    if prof_out.get("gh_off") or prof_out.get("gh_keep"):
        lines.append("%d taken off the Grade H list (their appraisal closed, kept in the record); %d kept on it and taken out of the "
                     "normal review for this cycle." % (prof_out.get("gh_off", 0), prof_out.get("gh_keep", 0)))
    n_ = prof_out.get("left_out_people")
    if n_:
        lines.append("%d %s moved into a unit the cycle leaves out and stop%s rating and moderating: %s archived, %s moved one level up%s%s." % (
            n_, "person" if n_ == 1 else "people", "s" if n_ == 1 else "", _pl(prof_out.get("left_out_pending", 0), "pending 360 rating"),
            _pl(prof_out.get("left_out_lines", 0), "KPI line"),
            (", %d with nobody above taking part left as they are" % prof_out["left_out_stuck"]) if prof_out.get("left_out_stuck") else "",
            ("; %s archived (their colleagues' 360 scores change)" % _pl(prof_out["left_out_submitted"], "submitted 360 rating"))
            if prof_out.get("left_out_submitted") else ""))
    n_ = prof_out.get("grade_out_people")
    if n_:   # a grade below the cycle's lowest (or Grade H): they only stop rating, their KPI lines stay (2026-11-09)
        floor_ = prof_out.get("grade_out_floor")
        what_ = ("moved below JG %s" % floor_ if floor_ is not None else "moved below the cycle's lowest job grade") \
            if prof_out.get("grade_out_below") and not prof_out.get("grade_out_h") else \
            "moved to Grade H" if prof_out.get("grade_out_h") and not prof_out.get("grade_out_below") else \
            "moved below the cycle's lowest job grade or to Grade H"
        lines.append("%d %s %s and stop%s taking part and rating: %s of them archived, %s they gave archived%s." % (
            n_, "person" if n_ == 1 else "people", what_, "s" if n_ == 1 else "", _pl(prof_out.get("grade_out_rated", 0), "360 rating"),
            _pl(prof_out.get("grade_out_pending", 0), "pending 360 rating"),
            ("; %s archived (their colleagues' 360 scores change)" % _pl(prof_out["grade_out_submitted"], "submitted 360 rating"))
            if prof_out.get("grade_out_submitted") else ""))
    n_ = (prof_out.get("asks_stale", 0) + prof_out.get("asks_undecided", 0))
    if n_:
        lines.append("%d %s left as they are: they started or submitted since you answered (or had no answer)." % (
            n_, "person was" if n_ == 1 else "people were"))
    if prof_out.get("records_left"):
        lines.append(_records_left_note(prof_out["records_left"]))
    n_ = prof_out.get("hod_refused")
    if n_:
        lines.append("%d HOD link%s not changed: that HOD can't be theirs now (they have left, or are not an employee). Set it under "
                     "Leaders › HODs." % (n_, "" if n_ == 1 else "s"))
    return {"summary": "%d added, %d updated%s%s." % (created, updated, (", %d back from leaving" % reactivated)
                                                      if reactivated else "",
                                                      (", %d marked as left" % left) if left else ""),
            "lines": lines}


def _rimp_downloads(db, me, chk, decisions, what):
    if what == "changes":
        return "changes", ["Employee ID", "Name", "Field", "From", "To"], [
            [x["eid"], x["name"], x["field"], x["from"], x["to"]] for x in chk["changes"]]
    ho = {x["eid"]: x for x in _rimp_handover_rows(db, chk)}
    return "final-preview", ["Employee ID", "Name", "What happens"], [
        list(p) for p in _rimp_people(chk, decisions, ho, _rimp_cutoff(db, chk), _rimp_asks(db, me, chk))]


