def _join_unit_state(db, cid, bg, company):
    """Whether a unit can still be joined this cycle (admin round 4, row 6): not once its BU CEO has moved anyone or
    locked either axis, nor once the BG CEO has locked it on the Talent Box. (ok, reason)."""
    if bu_groups_of_unit(db, bg, company):   # a unit with calibration groups calibrates on its own (2026-10-22)
        return False, "It has calibration groups: remove them on Leaders first"
    for sess_t, adj_t in (("pm_calibration_sessions", "pm_calibration_adjustments"),
                          ("calibration_sessions", "calibration_adjustments")):
        r = db.execute("SELECT id, locked_at FROM %s WHERE cycle_id=? AND tier='buceo' AND business_group=? AND "
                       "scope_key=?" % sess_t, (cid, bg, company)).fetchone()
        if r and r["locked_at"]:
            return False, "Locked %s: can't be joined now" % _st_day(_myt(r["locked_at"]))
        if r and db.execute("SELECT 1 FROM %s WHERE session_id=? LIMIT 1" % adj_t, (r["id"],)).fetchone():
            return False, "Its BU CEO has started calibrating"
    if db.execute("SELECT 1 FROM talent_box_bu_locks WHERE cycle_id=? AND business_group=? AND company=? AND "
                  "locked_at IS NOT NULL", (cid, bg, company)).fetchone():
        return False, "Locked on the Talent Box"
    return True, ""


def _join_locked(db, cid, bg, members):
    """True once any unit of a join is locked (BU CEO on either axis, or the Talent Box): it can't be separated then."""
    for m in members:
        for t in ("pm_calibration_sessions", "calibration_sessions"):
            if db.execute("SELECT 1 FROM %s WHERE cycle_id=? AND tier='buceo' AND business_group=? AND scope_key=? AND "
                          "locked_at IS NOT NULL" % t, (cid, bg, m)).fetchone():
                return True
        if db.execute("SELECT 1 FROM talent_box_bu_locks WHERE cycle_id=? AND business_group=? AND company=?",
                      (cid, bg, m)).fetchone():
            return True
    return False


def _joins_back(bg, panel=None):
    """Where a join or a separate lands: Leaders > BU CEOs of that business group, a panel open when it names one."""
    kw = {"tab": "buceo"}
    if panel:
        kw["panel"] = panel
    if bg:
        kw["bg"] = bg
    return url_for("admin_leaders", **kw)


def _calib_joins_view(db, cyc, bg):
    """What Leaders > BU CEOs draws for units calibrated together (super admin only): the business group's units with
    who leads them, their PAT curve and whether they can still be joined, and the joins of the running cycle with their
    people, calibrator, curve, expected spread and lock. (units, joins); both empty without a running cycle."""
    cid = cyc["id"] if cyc else None
    units, joins = [], []
    if cid and bg:
        n = {r[0]: r[1] for r in db.execute(
            "SELECT company, COUNT(*) FROM users WHERE business_group=? AND role!='admin' AND COALESCE(company,'')!='' "
            "AND " + calibration_population_sql() + " GROUP BY company", (bg,))}
        for c in org_map(db).get(bg, []):
            if not n.get(c):
                continue
            h = buceo_holder(db, bg, c)
            cv = pm_curve_for(db, cid, bg, c)
            j = calib_join(db, cid, bg, c)
            ok, why = _join_unit_state(db, cid, bg, c)
            units.append({"company": c, "label": display_company(bg, c) or c, "people": n[c],
                          "ceo": h["full_name"] if h else None,
                          "curve": ("%s%% · %s" % (_pm_fig(cv["pct"]), cv["label"].lower())) if cv["entered"]
                          else "PAT not entered · normal",
                          "joined": j["label"] if j else None, "can": ok and not j, "why": why})
    for j in (calib_joins(db, cid, bg) if cid else []):
        pop = db.execute("SELECT * FROM users WHERE business_group=? AND company IN (%s) AND role!='admin' AND "
                         % ",".join("?" * len(j["members"])) + calibration_population_sql(),
                         [j["business_group"]] + j["members"]).fetchall()
        cv = pm_curve_for_scope(db, {"period": cyc, "business_group": j["business_group"], "join": j,
                                     "population": pop}) if cyc else None
        h = buceo_holder(db, j["business_group"], j["lead"])
        sess = db.execute("SELECT locked_at FROM pm_calibration_sessions WHERE cycle_id=? AND tier='buceo' AND "
                          "business_group=? AND scope_key=?", (cid, j["business_group"], j["lead"])).fetchone()
        total = len(pop)
        bgj = j["business_group"]
        joins.append(dict(j, people=total, ceo=h["full_name"] if h else None,
                          plus=" + ".join(display_company(bgj, m) or m for m in j["members"]),
                          counts=[{"label": display_company(bgj, m) or m,
                                   "n": sum(1 for r_ in pop if r_["company"] == m)} for m in j["members"]],
                          lead_label=display_company(bgj, j["lead"]) or j["lead"],
                          curve_label=display_company(bgj, j.get("curve_of") or j["lead"]) or j["lead"],
                          follows_label=(cv.get("note") or "").replace("Joined units follow one curve: ", "") if cv else "",
                          locked=_join_locked(db, cid, bgj, j["members"]),
                          locked_at=_st_day(_myt(sess["locked_at"])) if sess and sess["locked_at"] else None,
                          spread=[{"band": b, "pct": cv["dist"][b], "n": round(cv["dist"][b] / 100 * total)}
                                  for b in PM_BAND_ORDER] if cv else [],
                          note=cv.get("note") if cv else ""))
    return units, joins


@app.route("/admin/calibration/joins", methods=["GET", "POST"])
@super_required   # was @admin_required + a 403 inside: the Settings page now hides its link from a BG admin (2026-10-14)
def admin_calibration_joins():
    """Units calibrated together (admin round 4, row 6; the canvas's M1). A super admin joins two or more units of one
    business group for the running cycle: one curve (the PAT curve of the unit the super admin picks: curve_of), one BU
    CEO who calibrates (the lead unit's), one lock, one unit on the BG CEO's Talent Box. Join before the BU CEO's first
    move; once locked, the units can't be separated this cycle. Every move and lock is still stored on each unit's own
    session, so every band reader works as it is.
    Moved onto Leaders > BU CEOs (Chris, 2026-10-26: "Build it as drawn, with the shortcut, super admin only"): the
    Join units panel and each join's Manage panel post here, every answer goes back to Leaders, and the old page's
    address opens Leaders with the Join units panel."""
    db = get_db()
    me = current_user()
    cyc = active_cycle(db)
    cid = cyc["id"] if cyc else None
    if request.method == "POST":
        if not cid:
            flash("There's no running cycle to join units in.", "error")
            return redirect(_joins_back((request.form.get("business_group") or "").strip()))
        action = request.form.get("action")
        bg = (request.form.get("business_group") or "").strip()
        if action == "join":
            picked = sorted({c.strip() for c in request.form.getlist("company") if c.strip()})
            lead = (request.form.get("lead") or "").strip()
            # whose PAT curve the joined population follows (one of the ticked units; the lead's when none is sent)
            curve_of = (request.form.get("curve_of") or "").strip() or lead
            err = None
            if len(picked) < 2:
                err = "Tick two or more units to calibrate together."
            elif not all(org_valid(db, bg, c) for c in picked):
                err = "Choose units of one business group from the org master."
            elif lead not in picked:
                err = "Choose whose BU CEO calibrates them: one of the units you ticked."
            elif curve_of not in picked:
                err = "Choose whose PAT curve they follow: one of the units you ticked."
            elif not buceo_holder(db, bg, lead):
                err = "%s has no BU CEO to calibrate them. Pick a unit with one, or give it one on Leaders." % (
                    display_company(bg, lead) or lead)
            else:
                for c in picked:
                    if calib_join(db, cid, bg, c):
                        err = "%s is already calibrated together with other units. Separate it first." % (
                            display_company(bg, c) or c)
                        break
                    ok, why = _join_unit_state(db, cid, bg, c)
                    if not ok:
                        err = "%s can't be joined: %s." % (display_company(bg, c) or c, why.lower())
                        break
            if err:
                flash(err, "error")
                return redirect(_joins_back(bg, "bu-join"))
            for c in picked:
                db.execute("INSERT INTO calib_unit_joins(cycle_id, business_group, company, lead, created_by, curve_of) "
                           "VALUES (?,?,?,?,?,?)", (cid, bg, c, lead, me["id"], curve_of))
            db.commit()
            label = _join_label(bg, [lead] + [c for c in picked if c != lead])
            log_activity(db, me["id"], "calib_join", "%s (%s) for %s, calibrated by the BU CEO of %s, following the PAT "
                         "curve of %s" % (label, bg, cyc["name"], lead, curve_of))
            flash("%s are calibrated together this cycle." % label, "ok")
            return redirect(_joins_back(bg, "bj-" + _org_anchor_slug(lead)))   # its Manage panel, open
        if action == "separate":
            lead = (request.form.get("lead") or "").strip()
            j = calib_join(db, cid, bg, lead)
            if not j:
                flash("Those units aren't calibrated together.", "error")
            elif _join_locked(db, cid, bg, j["members"]):
                flash("%s are locked: they can't be separated this cycle." % j["label"], "error")
                return redirect(_joins_back(bg, "bj-" + _org_anchor_slug(j["lead"])))
            else:
                db.execute("DELETE FROM calib_unit_joins WHERE cycle_id=? AND business_group=? AND lead=?",
                           (cid, bg, j["lead"]))
                db.commit()
                log_activity(db, me["id"], "calib_separate", "%s (%s) for %s" % (j["label"], bg, cyc["name"]))
                flash("%s are calibrated separately again." % j["label"], "ok")
            return redirect(_joins_back(bg))
        abort(400)
    bg = (request.args.get("fbg") or request.args.get("bg") or "").strip()
    return redirect(_joins_back(bg if bg in org_bgs(db) else "", "bu-join"))


CALIB_LOCK_HEAD = ["Who locks", "Scope", "Within", "Name", "Role", "People", "Performance", "Potential", "Closes"]


def _calib_lock_sheet(rows):
    """The Lock status file's rows: the Lock status page's own and Reports' Lock status (2026-11-04) write the same ones."""
    def ax(at, closed):
        return ("Locked " + _st_day(at)) if at else (closed or "Open")
    return [[r["tier_label"], r["scope"], r["sub"], r["who"], r["role"], r["n"],
             "Can lock any time" if r.get("anytime") and not r["pm"] else ax(r["pm"], r["pm_closed"]),
             "Can lock any time" if r.get("anytime") and not r["pot"] else ax(r["pot"], r["pot_closed"]),
             r["closes"]] for r in rows]


@app.route("/admin/calibration/locks")
@admin_required
def admin_calibration_locks():
    """Calibration & Talent › Run › Lock status (admin round 4, canvas row 1): which calibrations are still open this
    cycle, scope by scope -- every HOD department review, BU CEO calibration and Talent Box unit, who locks it, how many
    people, each axis open or locked (with the day), and when its part closes. A lock is final for the people under it.
    Business group and unit rows narrow it; Show picks open or locked; the download is the list on screen."""
    db = get_db()
    me = current_user()
    cyc = active_cycle(db)
    frows, picked = admin_filter_rows(db, me, "admin_calibration_locks", levels=2)
    rows = _calib_lock_scopes(db, me, cyc)
    if picked["bg"]:
        rows = [r for r in rows if picked["bg"] in r.get("bgs", [r["bg"]])]
    if picked["bu"]:
        rows = [r for r in rows if picked["bu"] in r["companies"]]
    if is_super(me) and cyc and request.args.get("format") != "xlsx":
        # Unlock on every locked row, both axes at once; a running late pass; "No unlock" where a tier above locked (2026-11-07)
        for r in rows:
            try:
                tk = (("hod", int(r["key"])) if r["tier"] == "hod" else
                      ("bugrp", (r["bg"], r["group_co"], r["group_id"])) if r.get("group_id") else
                      ("buceo", (r["bg"], r["companies"][0])) if r["tier"] == "buceo" else ("bgceo", r["bg"]))
                r["unlock"] = _unlock_row(db, me, *tk)
            except (KeyError, IndexError, ValueError, TypeError):
                r["unlock"] = None
    tiers = []
    for t, label, what in (("hod", "HOD department reviews", "each locks both axes for their people"),
                           ("buceo", "BU CEO calibrations", "performance and potential, per business unit"),
                           ("bgceo", "BG CEO Talent Box", "one business unit at a time; final")):
        tr = [r for r in rows if r["tier"] == t]
        if tr:
            n_l = sum(1 for r in tr if r["locked"])
            tiers.append({"label": label, "n": n_l, "of": len(tr), "pct": int(100 * n_l / len(tr)), "what": what,
                          # its scopes, for the list panel (2026-10-20), the page's own picks
                          "list": url_for("admin_list_view", key="lock-tier", tier=t, fragment=1,
                                          **{k: v for k, v in (("bg", picked["bg"]), ("bu", picked["bu"])) if v})})
    show = request.args.get("show", "")
    if show not in ("open", "locked"):
        show = ""
    n_open = sum(1 for r in rows if not r["locked"])
    counts = {"": len(rows), "open": n_open, "locked": len(rows) - n_open}
    shown = [r for r in rows if not show or (show == "open") == (not r["locked"])]
    base = _url_args(request.args, "show", "format")
    chips = [{"label": lab, "n": counts[k], "on": show == k,
              "href": url_for("admin_calibration_locks", **(dict(base, show=k) if k else base))}
             for k, lab in (("", "Everything"), ("open", "Still open"), ("locked", "Locked"))]
    if request.args.get("format") == "xlsx":
        data = _calib_lock_sheet(shown)
        log_activity(db, me["id"], "progress_export", "Calibration lock status, %d scopes" % len(data))
        return _xlsx_response("calibration-lock-status.xlsx", [("Lock status", CALIB_LOCK_HEAD, data)])
    groups = []
    for t in ("hod", "buceo", "bgceo"):
        tr = [r for r in shown if r["tier"] == t]
        if tr:
            groups.append({"label": tr[0]["tier_label"], "rows": tr})
    return render_template("admin_calibration_locks.html", cycle=cyc, frows=frows, tiers=tiers, chips=chips,
                           groups=groups, n_open=n_open, shown=len(shown), mid=cycle_is_mid_year(db, cyc["id"])
                           if cyc else False, picked=picked,
                           remind_href=url_for("admin_reminders") if is_super(me) else None)


def _mod_person_sections(db, me, uid):
    """One line per module for a single person -- what the subject page shows.

    Runs each module's own state function against a population of exactly this
    person, so the person page can never disagree with the module's dashboard:
    same code, same answer."""
    u = db.execute(
        "SELECT id, employee_id, full_name, department, job_title, job_grade, "
        "business_group, company FROM users WHERE id=?", (uid,)).fetchone()
    if not u:
        return []
    one = {uid: dict(u)}
    out = []
    for mod in MODULE_VIEWS:
        try:
            state, note = mod["state"](db, me, one)
        except Exception:                      # a module must never break the page
            app.logger.exception("module state failed for %s", mod["key"])
            state, note = {}, "Could not be read."
        s = state.get(uid)
        out.append({"key": mod["key"], "label": mod["label"],
                    "state": s["state"] if s else None,
                    "status": s["label"] if s else "Not in this module",
                    "detail": s["detail"] if s else (note or "Nothing recorded yet."),
                    "href": url_for("admin_module_progress", key=mod["key"])})
    return out


# ---------------------------------------------------------------------------
# The admin shell (Chris, 2026-10-10: "go with your recommendation" -- the "OneHR Admin Revamp" canvas, direction A,
# module workspaces, with B's calendar for the cycle and C's search and settings sheet)
# ---------------------------------------------------------------------------
# ONE registry for the whole admin area. A SECTION is an entry in the left sidebar: Home, Cycle, each module, the
# organisation's pages, All settings, Reports. Its TABS run across the top of every page in it, and a tab holding more
# than one page lists them in a row under the tabs. Every module has the same four tabs -- Overview, Run, Settings,
# Reports -- dropping any it has nothing for. Every page keeps its own URL. A page marked hidden belongs to its tab (the
# sidebar and the tab light up on it) without a link of its own. Each page is gated by its route's own decorator
# (_admin_nav_allowed), so nothing is offered and then refused; a tab or a section with nothing left is dropped.
def _pg(ep, label, **kw):
    return {"ep": ep, "label": label, **kw}


