ADMIN_SECTION_COLORS = {**{s["key"]: s["color"] for s in ADMIN_SECTIONS if s.get("color")},
                        "cycle": "#252A59", "org": "#8a90a2"}
app.jinja_env.globals["admin_section_colors"] = ADMIN_SECTION_COLORS
# the sections each cycle module key covers -- the 360 and the competency are both "tm" on the cycle page
_SECTION_MODULE_KEY = {"pm": "pm", "f360": "tm", "competency": "tm", "calibration": "calibration", "idp": "idp"}


def _section_pages(sec):
    return [p for t in sec["tabs"] for p in t["pages"]]


# The old two-menu shape, DERIVED from the sections: the module views, the cycle page and the tests still read it.
ADMIN_MODULES = []
for _s in ADMIN_SECTIONS:
    _k = _SECTION_MODULE_KEY.get(_s["key"])
    if not _k:
        continue
    _m = next((m for m in ADMIN_MODULES if m["key"] == _k), None)
    if _m is None:
        _m = {"key": _k, "label": "Talent Management" if _k == "tm" else _s["label"], "pages": []}
        ADMIN_MODULES.append(_m)
    _m["pages"] += [p for p in _section_pages(_s) if not p.get("hidden")]
ADMIN_PEOPLE = [p for _s in ADMIN_SECTIONS if _s["group"] == "org" for p in _section_pages(_s) if not p.get("hidden")]


def _admin_nav_allowed(page, u):
    """Whether this login may open this page -- resolved from the route's own
    decorator (super_required marks itself), so a menu entry can never appear
    for someone the route will 403. Only "subadmin" is declared by hand: that
    page is @admin_required and does its own can_manage_subadmins() check
    inside, which no decorator can advertise."""
    # a hand-declared gate lives on the menu entry; a link built from the bare endpoint (a Settings card's Open, ...)
    # finds it there too, so it can't be shown to someone the page refuses (the production rehearsal, 2026-10-14)
    gate = page.get("gate") or _ADMIN_PAGE_GATES.get(page.get("ep"))
    if gate == "system":   # AI+ Connect: a system admin's alone (2026-10-28)
        return is_system(u)
    if gate == "lms" and not lms_on():   # AI+ Learning, dark unless ONEHR_LMS=1 (2026-10-20)
        return False
    if gate == "gradeh" and not gradeh_on():   # Grade H Appraisal, dark unless ONEHR_GRADEH=1 (2026-10-28)
        return False
    if gate == "gradeh" and not is_super(u) and not gradeh_cycle_offered(active_cycle()):
        return False   # a BG or BU admin sees it only while it is offered on the active cycle (2026-10-31)
    if is_lnd_admin(u):   # an L&D admin opens Learning and nothing else (phase 2)
        return gate == "lms"
    if gate == "subadmin":
        return can_manage_subadmins(u)
    if gate == "super":   # a page whose route serves others too, but this one is the super admin's (Platform)
        return is_super(u)
    fn = app.view_functions.get(page["ep"])
    if getattr(fn, "_nav_gate", None) == "system":   # AI+ Connect (2026-10-28)
        return is_system(u)
    if getattr(fn, "_nav_gate", None) == "super":
        return is_super(u)
    mod = _page_access_module(page)   # a module the super admin hasn't let them read (2026-10-19)
    if mod and is_admin(u) and not is_super(u) and not admin_can(u, mod, "read"):
        return False
    return True


def _admin_page_href(page):
    """A nav page's URL. Most are plain endpoints; the shared module dashboard
    and progress pages are one endpoint serving several modules, so they carry
    their own url_for() arguments in the descriptor."""
    return url_for(page["ep"], **page.get("args", {}))


def _admin_module_entry(key, u):
    """Where a module card should land: the first page this admin may open in the section (or the old module key's
    first section) -- the same _admin_nav_allowed() the sidebar uses, so a card never points at a page that 403s."""
    secs = [ADMIN_SECTION_BY_KEY[key]] if key in ADMIN_SECTION_BY_KEY else \
        [s for s in ADMIN_SECTIONS if _SECTION_MODULE_KEY.get(s["key"]) == key]
    for sec in secs:
        for pg in _section_pages(sec):
            if not pg.get("hidden") and _admin_nav_allowed(pg, u):
                return _admin_page_href(pg)
    return None


def admin_nav(u):
    """(modules, people) filtered to what this admin may actually open -- the old menu shape, kept for its callers.
    A module the cycle has switched off is MARKED, not removed: its settings must stay reachable."""
    mods = []
    for m in ADMIN_MODULES:
        pages = [{**p, "href": _admin_page_href(p)}
                 for p in m["pages"] if _admin_nav_allowed(p, u)]
        if pages:
            mods.append({**m, "pages": pages, "off": not cycle_module_on(m["key"])})
    return mods, [{**p, "href": _admin_page_href(p)}
                  for p in ADMIN_PEOPLE if _admin_nav_allowed(p, u)]


def _section_view(sec, u):
    """A section holding only what this admin may open, every page resolved to its href; None if nothing is left."""
    tabs = []
    for t in sec["tabs"]:
        pages = [{**p, "href": _admin_page_href(p)} for p in t["pages"] if _admin_nav_allowed(p, u)]
        if pages:
            shown = [p for p in pages if not p.get("hidden")]
            tabs.append({**t, "pages": pages, "href": (shown or pages)[0]["href"]})
    return {**sec, "tabs": tabs} if tabs else None


# readiness group -> the section whose sidebar entry counts it
_READY_SECTION = {"Foundation": "cycle", "360 feedback": "f360", "Performance": "pm",
                  "Calibration and talent": "calibration"}


def _admin_readiness(db, u):
    """The Overview's readiness, read once per request (the sidebar's counts and the Home page share it)."""
    if has_request_context() and getattr(g, "_admin_ready", None) is not None:
        return g._admin_ready
    out = _cycle_readiness(db, u, viewed_cycle(db))
    if has_request_context():
        g._admin_ready = out
    return out


def admin_shell(u, path):
    """The sidebar and the header of the page at `path`, for this admin: {side, head, section}.

    The page that owns a path is the one whose href is the path or a parent of it, longest first -- /admin/import is
    a 360 page but /admin/import/roster belongs to People. Home owns /admin itself only, never everything under it."""
    db = get_db()
    secs = [v for v in (_section_view(s, u) for s in ADMIN_SECTIONS) if v]
    best, own_sec, own_tab, own_page = -1, None, None, None
    for s in secs:
        for t in s["tabs"]:
            for p in t["pages"]:
                h = p["href"].split("?")[0]
                hit = (path in ("/admin", "/admin/")) if h == "/admin" else \
                    (path == h or path.startswith(h.rstrip("/") + "/"))
                if hit and len(h) > best:
                    best, own_sec, own_tab, own_page = len(h), s, t, p
    groups, _done, _total = _admin_readiness(db, u)
    todo = {}
    for gr in groups:
        k = _READY_SECTION.get(gr["label"])
        if k:
            todo[k] = todo.get(k, 0) + sum(1 for x in gr["steps"] if x["state"] not in ("done", "waiting"))
    side = []

    def _side_badge(s):
        badge, tone = None, None
        if s.get("module") and not cycle_module_on(s["module"]):
            badge, tone = "Off", "off"
        elif s["key"] in todo:
            badge, tone = ("%d to do" % todo[s["key"]], "todo") if todo[s["key"]] else ("Done", "ok")
        elif s["key"] == "ticketing":   # tickets nobody has picked up yet (Ticketing, 2026-10-22)
            n_tk = _tickets_open_count(db, u)
            badge, tone = (("%d to do" % n_tk, "todo") if n_tk else (None, None))
        return badge, tone

    def _side_item(s):
        badge, tone = _side_badge(s)
        return {"key": s["key"], "label": s["label"], "href": s["tabs"][0]["href"], "color": s.get("color"),
                "active": bool(own_sec) and own_sec["key"] == s["key"], "badge": badge, "tone": tone}

    for grp, label in (("top", None), ("modules", "Modules")):
        items = [_side_item(s) for s in secs if s["group"] == grp]
        if items:
            side.append({"label": label, "items": items})
    # Below the modules (Chris, 2026-10-28, canvas): one rule, no label, then the ADMIN_MENU_TAIL slots. A slot with
    # several pages this admin may open is a group row opening a flyout; with one it is that page's own link; with none
    # it is gone. Built from the already-filtered sections, so nothing is offered that the route refuses.
    by_key = {s["key"]: s for s in secs}
    tail = []
    for slot, slot_label, keys in ADMIN_MENU_TAIL:
        pages = []
        for k in keys:
            s = by_key.get(k)
            if not s:
                continue
            badge, tone = _side_badge(s)
            tabs = [t for t in s["tabs"] if any(not p.get("hidden") for p in t["pages"])]
            hint = ADMIN_MENU_HINTS.get(k) if len(tabs) <= 1 else ", ".join(t["label"] for t in tabs)
            pages.append({"key": k, "label": s["label"], "href": s["tabs"][0]["href"], "badge": badge, "tone": tone,
                          "hint": hint or (tabs[0]["label"] if tabs else ""),
                          "active": bool(own_sec) and own_sec["key"] == k})
        if len(pages) == 1:
            pg = pages[0]
            tail.append({"key": pg["key"], "label": pg["label"], "href": pg["href"], "color": None,
                         "active": pg["active"], "badge": pg["badge"], "tone": pg["tone"]})
        elif pages:
            todo_n = sum(int(pg["badge"].split()[0]) for pg in pages if pg["tone"] == "todo")
            tail.append({"kind": "group", "key": slot, "label": slot_label, "pages": pages,
                         "active": any(pg["active"] for pg in pages),
                         "badge": ("%d to do" % todo_n) if todo_n else None, "tone": "todo" if todo_n else None})
    if tail:
        side.append({"label": None, "items": tail})
    head = None
    shown = [p for p in own_tab["pages"] if not p.get("hidden")] if own_tab else []
    if own_sec and own_sec["key"] != "home" and (len(own_sec["tabs"]) > 1 or len(shown) > 1):
        cyc = active_cycle(db)
        state = None
        if own_sec.get("module"):
            state = {"on": cycle_module_on(own_sec["module"]), "cycle": cyc["name"] if cyc else None}
        head = {"key": own_sec["key"], "label": own_sec["label"], "color": own_sec.get("color"), "state": state,
                "tabs": [{"label": t["label"], "href": t["href"], "active": t is own_tab} for t in own_sec["tabs"]]
                if len(own_sec["tabs"]) > 1 else [],
                "subnav": [{"label": p["label"], "href": p["href"],
                            "active": p is own_page or (own_page or {}).get("under") == p["ep"]} for p in shown]
                if len(shown) > 1 else []}
    elif own_sec and own_page and own_page.get("hidden") and own_sec["key"] != "home":
        # a page kept under a one-page section (the report pages under Reports, 2026-10-19): a slim header, the way
        # back and the page's own name
        parent = next((p for p in (own_tab or {}).get("pages", []) if p["ep"] == own_page.get("under")), None) or \
            (shown[0] if shown else None)
        head = {"key": own_sec["key"], "label": own_sec["label"], "color": own_sec.get("color"), "state": None,
                "tabs": [], "subnav": [], "page": own_page["label"],
                "back": parent["href"] if parent else None}
    elif own_sec and own_sec["key"] in ("feedback", "whatsnew") and own_page:
        # AI+ feedback (2026-10-29, canvas): a one-page section that still carries its slot's name in the head,
        # "Reports & audit > AI+ feedback"
        slot = next((sl for _k, sl, ks in ADMIN_MENU_TAIL if own_sec["key"] in ks), own_sec["label"])
        head = {"key": own_sec["key"], "label": slot, "color": None, "state": None, "tabs": [], "subnav": [],
                "page": own_page["label"], "back": None}
    return {"side": side, "head": head, "section": own_sec["key"] if own_sec else None}


# ---------------------------------------------------------------------------
# Every setting, pinned to one home (the canvas's "every setting has one home")
# ---------------------------------------------------------------------------
# A SECTION is one card on a module's Settings page; its ROWS are the settings in it, each with how it reads now. The
# same rows make the All settings sheet and the search, so the three can never disagree. A card either holds its own
# form ("card": a partial posting to the route that already saved it, which sends you back here) or opens the page
# that edits it ("open"). "gate": "super" = only a super admin changes it (a BG admin reads the value instead).
SETTING_SCOPES = {"global": "Global", "bg": "Per business group", "cycle": "Per cycle",
                  # 2026-11-03: "viewer" = set per unit, calibrator, Group Chief group and the Chairman (Filters card)
                  "viewer": "Per viewer", "default_cycle": "Default + per cycle", "cycle_unit": "Per cycle, per unit",
                  "unit": "Per business unit", "paused": "Paused"}
SETTING_SCOPE_FILTER = {"global": "global", "bg": "bg", "cycle": "cycle", "default_cycle": "cycle",
                        "cycle_unit": "cycle", "unit": "bg", "paused": "global",
                        "viewer": "bg"}  # 2026-11-03: the Filters card still lists under business group


def _st_day(raw):
    """'2026-10-03 08:14:00' -> '3 Oct 2026'; '' when unset."""
    try:
        d = datetime.strptime(str(raw)[:10], "%Y-%m-%d")
    except (TypeError, ValueError):
        return ""
    return "%d %s" % (d.day, d.strftime("%b %Y"))


def _st_bgs(db, u):
    bg = admin_bg_of(u)
    return [bg] if bg else [r[0] for r in db.execute(
        "SELECT DISTINCT business_group FROM org_units WHERE active=1 ORDER BY 1")]


def _st_count(db, sql, args=()):
    r = db.execute(sql, list(args)).fetchone()
    return (r[0] or 0) if r else 0


def _st_dates(db, cells):
    """One line for a set of open/close cells on the active cycle: '1 Oct 2026 – 22 Dec 2026', or 'Open, no dates'."""
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    got = [window_dates(db, c, cyc["id"]) for c in cells]
    opens = sorted(o for o, _c in got if o)
    closes = sorted(c for _o, c in got if c)
    by_date = cycle_opens_by_date(db, cyc["id"])   # a part with no start date isn't open (2026-10-19)
    if not opens and not closes:
        return "Not open: no dates set" if by_date else "Open, no dates set"
    span = "%s – %s" % (_st_day(opens[0]) if opens else ("no start date" if by_date else "open now"),
                        _st_day(closes[-1]) if closes else "no close")
    n = sum(1 for o, c in got if o or c)
    return span if n == len(cells) else "%s (%d of %d dated)" % (span, n, len(cells))


def _st_date_rows(db, cells):
    """The cells as table rows for a Dates card: who, what, opens, closes, now."""
    cyc = active_cycle(db)
    label = {c[0]: c for c in WINDOW_CELLS}
    out = []
    for c in cells:
        o, cl = window_dates(db, c, cyc["id"]) if cyc else (None, None)
        st = window_state(db, c, cyc["id"]) if cyc else "open"
        out.append({"cell": c, "who": label[c][2], "what": label[c][3], "opens": _when_disp(o) or "—",
                    "closes": _when_disp(cl) or "—",
                    "now": {"open": "Open", "not_open": "Not open yet", "closed": "Closed"}[st], "state": st})
    return out


def _st_onoff(on, ai=False):
    s = "On" if on else "Off"
    if ai and on and not ai_draft.is_configured():
        s += " (no AI model on this server)"
    return s


def _st_mechanism(db, u):
    bgs = _st_bgs(db, u)
    n = _st_count(db, "SELECT COUNT(DISTINCT business_group) FROM pm_bg_config WHERE business_group IN (%s)"
                  % ",".join("?" * len(bgs)), bgs) if bgs else 0
    return "%d of %d business groups set" % (n, len(bgs)) if len(bgs) != 1 else ("Set" if n else "Not set")


def _st_cutoffs(db, u):
    bgs = _st_bgs(db, u)
    mbo = [r[0] for r in db.execute("SELECT business_group FROM pm_bg_config WHERE mechanism='B' AND business_group "
                                    "IN (%s)" % ",".join("?" * len(bgs)), bgs)] if bgs else []
    if not mbo:
        return "No business group scores by achievement %"
    vid = viewed_cycle_id(db)   # the settings overview speaks of the cycle in the top bar, whose starts the Scoring page edits
    ok = sum(1 for b in mbo if _pm_cycle_band_table(db, vid, b))
    cyc = viewed_cycle(db)
    return "%d of %d achievement-%% groups set%s" % (ok, len(mbo), (" in " + cyc["name"]) if cyc else "")


def _st_library(db, u):
    bgs = _st_bgs(db, u)
    if not bgs:
        return "None"
    r = db.execute("SELECT COUNT(*), COUNT(DISTINCT business_group) FROM pm_kpi_library WHERE active=1 AND "
                   "business_group IN (%s)" % ",".join("?" * len(bgs)), bgs).fetchone()
    return "%d KPIs for %d business group%s" % (r[0], r[1], "" if r[1] == 1 else "s") if r and r[0] else "No KPIs yet"


def _st_framework(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    n = _st_count(db, "SELECT COUNT(*) FROM cycle_criteria WHERE cycle_id=?", (cyc["id"],))
    m = _st_count(db, "SELECT COUNT(*) FROM cycle_statements WHERE cycle_id=?", (cyc["id"],))
    return "%d principles, %d behaviours (%s)" % (n, m, cyc["name"])


def _st_rules(db, u):
    tiers = ", ".join("%s–%s" % (t["min"], t["max"]) for t in default_tiers())
    cap = default_assessor_cap()
    ps = default_panel_size()
    s = "%s · valid at %d · %s · tiers JG %s" % ("%d assessors" % ps if ps else "no maximum panel", default_min_valid(),
                                                           "at most %d each" % cap if cap else "no maximum each", tiers)
    cyc = active_cycle(db)
    if cyc and any(cyc[k] is not None for k in ("panel_size", "min_valid", "tiers_json")):
        s += " · %s has its own" % cyc["name"]
    return s


def _st_points(db, kind):
    """The All settings row of a Points per answer card: the default (Demonstrate current / next, Developing current / next) and,
    when the current cycle holds its own, that."""
    d = points_default(db, kind)
    s = "%s (Demonstrate %g / %g, Developing %g / %g)" % (points_words(d), d.dc, d.dn, d.vc, d.vn)
    cyc = active_cycle(db)
    if cyc:
        c_row = db.execute("SELECT * FROM cycles WHERE id=?", (cyc["id"],)).fetchone()
        if _points_pinned(c_row, kind) and _points_own(c_row, kind) != d:
            s += " · %s keeps its own %s" % (cyc["name"], points_words(_points_own(c_row, kind)))
    return s


def _st_extremes(db, u):
    on, bonus, pen = get_extremes_adjustment_settings()
    return "%s · +%g / −%g" % ("On" if on else "Off", bonus, pen)


def _st_reminders(db, u):
    r = reminder_rules()
    if not r["enabled"]:
        return "Automatic off"
    bits = (["when a part opens"] if r["on_open"] else []) + (
        ["%s days before it closes" % ", ".join(str(d) for d in r["days_before"])] if r["days_before"] else []) + (
        [("every %d days %s" % (r["every_days"], _rm_span(_rm_date(r["every_from"]), _rm_date(r["every_to"]))))
         if (r["every_from"] or r["every_to"]) else "every %d days while open" % r["every_days"]]
        if r["every_days"] else [])
    gh = " · Grade H included" if gradeh_rm_cid(db) else ""   # the Admin Agent and All settings say Grade H is in it (2026-10-31)
    return "Automatic at %s · %s%s" % (r["send_time"], " · ".join(bits) or "no rule", gh)


def _st_email_waves(db, u):
    w = email_wave_rules()
    return ("In waves of %s, %d min apart" % ("{:,}".format(w["size"]), w["gap"])) if w["on"] else "All at once"


def _st_leader_progress(db, u):
    r = lp_rules()
    if not r["enabled"]:
        return "Automatic off"
    return "%s at %s · to %s" % (lp_schedule_words(r)[:1].upper() + lp_schedule_words(r)[1:], r["send_time"],
                                 " and ".join(l for k, l, _d in LP_ROLES if k in r["roles"]) or "nobody")


def _st_bg_admin_progress(db, u):
    r = bga_rules()
    return ("Every day at %s" % r["send_time"]) if r["enabled"] else "Automatic off"


def _st_ready_notices(db, u):
    r = ready_rules()
    return ("Checked every day at %s · to %s" % (r["send_time"], " and ".join(l for k, l, _d in READY_ROLES if k in r["roles"])
                                                 or "nobody")) if r["enabled"] else "Automatic off"


def _st_thresholds(db, u):
    """This cycle's cutoffs first (what people are banded on now), then the default (2026-10-11)."""
    lo, mi = get_thresholds()
    own = _cycle_own_cutoffs(db)
    if own:
        return "%s: Low ≤ %g · Mid ≤ %g of %g · default %g / %g" % (own["name"], own["low"], own["mid"], own["max"],
                                                                    lo, mi)
    return "Low ≤ %g · Mid ≤ %g (the default; this cycle has none of its own)" % (lo, mi)


def _st_weights(db, u):
    rows = sorted(tc_band_weights(db).items(), key=lambda kv: _jg_sort_key(kv[0]))
    runs = []
    for jg, (w360, wtech) in rows:
        if runs and runs[-1][0] == (w360, wtech):
            runs[-1][1].append(jg)
        else:
            runs.append(((w360, wtech), [jg]))
    parts = []
    for (w360, wtech), jgs in runs:
        span = str(jgs[0]) if len(jgs) == 1 else "%s–%s" % (jgs[0], jgs[-1])
        parts.append("%g : %g for JG %s" % (w360, wtech, span))
    return "360 : competency " + " · ".join(parts) if parts else "Not set"


def _st_pbt(db, u):
    cyc = active_cycle(db)
    bgs = _st_bgs(db, u)
    if not cyc or not bgs:
        return "No active cycle" if not cyc else "No units"
    ph = ",".join("?" * len(bgs))
    n_co = _st_count(db, "SELECT COUNT(DISTINCT company) FROM org_units WHERE active=1 AND COALESCE(company,'')!='' "
                     "AND business_group IN (%s)" % ph, bgs)
    n = _st_count(db, "SELECT COUNT(*) FROM pm_pbt_achievement WHERE cycle_id=? AND COALESCE(company,'')!='' "
                  "AND business_group IN (%s)" % ph,
                  [cyc["id"]] + bgs)
    s = "%d of %d units entered" % (n, n_co)
    s += (" · the rest use the Normal curve" if n < n_co else "")
    # a PAT changed after a BU CEO's lock, not fitted since (2026-10-17)
    nf = _st_count(db, "SELECT COUNT(*) FROM pm_pat_lock_flags f JOIN pm_calibration_sessions s ON s.cycle_id=f.cycle_id "
                   "AND s.tier='buceo' AND s.scope_key=f.company AND s.locked_at IS NOT NULL AND f.changed_at>=s.locked_at "
                   "WHERE f.cycle_id=? AND f.fitted_at IS NULL AND f.business_group IN (%s)" % ph, [cyc["id"]] + bgs)
    return s + (" · %d changed after the BU CEO's lock" % nf if nf else "")


def _st_calib_rule(db, u):
    r = get_calib_rule()
    tol = ("± %d %s" % (r["people"], "person" if r["people"] == 1 else "people")) if r["mode"] == "people" \
        else "%g%% of headcount" % r["pct"]
    return tol + (" · refuse the lock" if r["strict"] else " · lock with a reason")


def _st_dept_filter(db, u):
    try:
        n = dict(db.execute("SELECT view, COUNT(*) FROM calib_dept_filter WHERE shown=1 GROUP BY view").fetchall())
    except sqlite3.OperationalError:
        n = {}
    if not n:
        return "Hidden everywhere"
    units = lambda k: "%d unit%s" % (k, "" if k == 1 else "s")
    return "Shown for %s in the BU CEO calibration · %s in the BG CEO Talent Box" % (units(n.get("bu", 0)),
                                                                                   units(n.get("tb", 0)))


def _bg_tab_label(bg):
    """A business group's short name for a tab: the code in its name's brackets ("... (CHBM)"), the BG pill row's short
    label, else its display name."""
    m = re.search(r"\(([A-Za-z0-9 &]{2,12})\)\s*$", bg or "")
    if m:
        return m.group(1).strip()
    short = {v: k for k, v in BG_FILTER_OPTIONS}.get(bg)
    return short or display_bg(bg) or bg


def _dept_filter_ctx(db, want_bg):
    """The Department filter card (Chris, 2026-10-17): the business groups as tabs, and the one picked's units, each
    with its two switches (BU CEO calibration, BG CEO Talent Box) as they stand."""
    bgs = sorted({r[0] for r in db.execute("SELECT DISTINCT business_group FROM org_units WHERE active=1 AND "
                                           "COALESCE(business_group,'')!='' AND COALESCE(company,'')!=''")},
                 key=_bg_display_rank)
    bg = want_bg if want_bg in bgs else (bgs[0] if bgs else "")
    on = calib_dept_filter_map(db, bg) if bg else {}
    units = [r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                      "COALESCE(company,'')!='' ORDER BY company", (bg,))] if bg else []
    return {"bg": bg, "bg_label": display_bg(bg) if bg else "",
            "bgs": [{"key": b, "label": _bg_tab_label(b)} for b in bgs],
            "rows": [{"company": co, "short": COMPANY_SHORT.get(co) or "", "full": display_company(bg, co) or co,
                      "bu": bool(on.get((co, "bu"))), "tb": bool(on.get((co, "tb")))} for co in units]}


def _st_bu_filters(db, u):
    """Filters at BU level on All settings: where each registry filter shows, in a line."""
    def n_(f, view):
        try:
            if f["table"]:
                return db.execute("SELECT COUNT(*) FROM %s WHERE shown=1 AND view=?" % f["table"], (view,)).fetchone()[0]
            return db.execute("SELECT COUNT(*) FROM calib_filter WHERE shown=1 AND view=? AND filter_key=?",
                              (view, f["key"])).fetchone()[0]
        except sqlite3.OperationalError:
            return 0
    try:
        off = db.execute("SELECT COUNT(*) FROM calib_cal_filter WHERE shown=0").fetchone()[0]
    except sqlite3.OperationalError:
        off = 0
    units = lambda k: "%d unit%s" % (k, "" if k == 1 else "s")
    out = []
    for f in CALIB_FILTERS:
        if f["key"] == "cal":
            out.append("CAL: on where a unit has calibrators%s" % ((", off in %s" % units(off)) if off else ""))
        else:
            out.append("%s: %s" % (f["code"], " / ".join(units(n_(f, v)) for v in f["views"])))
    return " · ".join(out) + " (BU CEO / Talent Box)"


def _cf_plural(n, one, many):
    return "%d %s" % (n, one if n == 1 else many)


def _bu_filters_ctx(db, want_bg):
    """The Filters at BU level card, one rule per filter (Chris, 2026-10-30, canvas "OneHR Calibration Filter Rules",
    Option 2): the business groups as tabs, and for the one picked a row per registry filter (CALIB_FILTERS) saying which
    of its units show it, on which screens, with the side panel's rows (one per active unit, its checkbox, its coverage
    line and, where nobody has a value, why it is disabled)."""
    bgs = sorted({r[0] for r in db.execute("SELECT DISTINCT business_group FROM org_units WHERE active=1 AND "
                                           "COALESCE(business_group,'')!='' AND COALESCE(company,'')!=''")},
                 key=_bg_display_rank)
    bg = want_bg if want_bg in bgs else (bgs[0] if bgs else "")
    units = [r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                      "COALESCE(company,'')!='' ORDER BY company", (bg,))] if bg else []
    cov = calib_filter_coverage(db, bg) if bg else {}
    n_grp = {co: len(bu_groups_of_unit(db, bg, co)) for co in units} if bg else {}
    names = {co: (COMPANY_SHORT.get(co) or display_company(bg, co) or co) for co in units}
    screens = {v: (short, long_) for v, short, long_ in CALIB_FILTER_SCREENS}
    filters = []
    for f in CALIB_FILTERS if bg else ():
        key = f["key"]
        saved = calib_filter_map(db, bg, key)
        rows, on_units, on_views, union = [], [], {}, set()
        for co in units:
            c = cov.get(co) or {}
            on = {v: calib_filter_on(db, bg, key, co, v, saved) for v in f["views"]}
            for v, x in on.items():
                if x:
                    union.add(v)
            roster = f in calib_roster_filters()
            have, kinds = (c.get(key) or (0, 0)) if roster else (0, 0)
            people = c.get("people", 0)
            if roster:   # every roster-backed registry entry reads the same way (a new column needs nothing here)
                ok = have > 0
                word = (f.get("noun") or f["label"].lower(), f["plural"])
                cover = _cf_plural(kinds, *word) if f.get("cover") == "count" else \
                    "%d of %d have one · %s" % (have, people, _cf_plural(kinds, *word))
                why = "No one has %s %s" % ("an" if word[0][:1] in "aeiou" else "a", word[0])
            elif key == "jg":
                nb = c.get("jg", 0)
                ok, cover, why = nb > 0, _cf_plural(nb, "band", "bands"), "No job grades on the roster"
            else:   # cal
                ng = n_grp.get(co, 0)
                ok = ng > 0
                cover = ("BU CEO + %s" % _cf_plural(ng, "group", "groups")) if ng else "No calibrators at BU level"
                why = "No calibrators at BU level"
            any_on = any(on.values())
            if any_on:
                on_units.append(co)
            rows.append({"company": co, "name": names[co], "full": display_company(bg, co) or co, "checked": any_on,
                         "disabled": (not ok) and not any_on, "reason": "" if ok or any_on else why,
                         "cover": cover if ok or any_on else "", "people": people,
                         "kinds": (kinds if roster else c.get("jg", 0) if key == "jg" else n_grp.get(co, 0)),
                         "was": {v: bool(on.get(v)) for v in f["views"]}})
        # which screens: the union of what the ticked units show; "set differently per unit" when units disagree
        views_of = [frozenset(v for v, x in r["was"].items() if x) for r in rows if r["checked"]]
        differs = len(set(views_of)) > 1
        if len(on_units) == 0:
            units_txt, extra = "Not shown anywhere", []
        elif key == "cal" and set(on_units) == {co for co in units if n_grp.get(co)}:
            units_txt, extra = "Units with calibrators (%d)" % len(on_units), []
        elif len(on_units) == len(units) and units:
            units_txt, extra = "All %d units" % len(units), []
        else:
            units_txt, extra = "", [names[co] for co in on_units]
        scr = [screens[v][0] for v, _s, _l in CALIB_FILTER_SCREENS if v in union]
        shown_names = extra[:2] if len(extra) > 2 else extra
        filters.append({
            "key": key, "label": f["label"], "plural": f["plural"], "code": f["code"], "note": f["note"], "sub": f["sub"],
            "code_line": f["code"] + (" · " + f["note"] if f["note"] else ""),
            "views": [{"key": v, "short": screens[v][0], "long": screens[v][1], "on": v in union}
                      for v in f["views"] if v in screens],
            "units_txt": units_txt, "names": shown_names, "more": extra[2:] if len(extra) > 2 else [],
            "screens_txt": " · ".join(scr) if scr else "–", "differs": differs, "rows": rows,
            "search_min": CALIB_FILTER_SEARCH_MIN, "n_on": len(on_units),
            "preview_n": max([r["people"] for r in rows] or [0]), "preview_k": max([r["kinds"] for r in rows] or [0]),
            "any_available": any(not r["disabled"] for r in rows)})
    return {"bg": bg, "bg_label": display_bg(bg) if bg else "",
            "bgs": [{"key": b, "label": _bg_tab_label(b)} for b in bgs], "filters": filters, "n_units": len(units)}


# ---- Filters per viewer: the settings card's tabs (2026-11-02) --------------------------------------------------------
VF_TABS = (("unit", "BU CEO & Talent Box", "per unit"), ("cal", "Calibrators", "per calibrator"),
           ("gc", "Group Chiefs", "per group"), ("ec", "Executive Chairman", ""))
VF_COLS = "u.id, u.department, u.job_grade, u.cost_center, u.work_location, u.business_group, u.company"


def _vf_roster_cover(f, people, cfg=None, each=False):
    """(ok, cover words, why not) for registry filter `f` over `people` (users rows), as the unit panel says it: "4 departments",
    "29 of 31 have one · 6 cost centres", "3 bands" (a Group Chief's Job grade lists each grade: "6 grades"); a filter nobody has
    a value for says why it cannot be switched on. Returns (ok, cover, why, kinds)."""
    key = f["key"]
    n = len(people)
    if key == "jg":
        grades = [(str(_row_get(p, "job_grade") or "")).strip() for p in people]
        grades = [g for g in grades if g]
        kinds = len(set(grades)) if each else len(calib_jg_options(cfg, grades))
        word = ("grade", "grades") if each else ("band", "bands")
        return kinds > 0, _cf_plural(kinds, *word), "No job grades on the roster", kinds
    vals = [(str(_row_get(p, f["column"]) or "")).strip() for p in people]
    have = [v for v in vals if v]
    kinds = len(set(have))
    word = (f.get("noun") or f["label"].lower(), f["plural"])
    cover = _cf_plural(kinds, *word) if f.get("cover") == "count" else \
        "%d of %d have one · %s" % (len(have), n, _cf_plural(kinds, *word))
    return len(have) > 0, cover, "No one has %s %s" % ("an" if word[0][:1] in "aeiou" else "a", word[0]), kinds


def _vf_filter_rows(kind, people, own, cfg=None, each=False, bg_label=""):
    """The panel's "1. Which filters" rows for one viewer's `people`: a tick per filter it can be given (CALIB_VIEWER_KINDS),
    its code and note, its coverage line, and why one nobody has a value for is disabled (unless it is already on)."""
    out = []
    keys = CALIB_VIEWER_KINDS[kind]["keys"]
    for f in [x for x in CALIB_VIEWER_EXTRA if x["key"] == "bg"] + list(CALIB_FILTERS):
        k = f["key"]
        if k not in keys:
            continue
        on = bool((own or {}).get(k))
        if k == "bg":
            kinds = len({(_row_get(p, "business_group") or "") for p in people if _row_get(p, "business_group")})
            ok, cover, why = kinds > 0, _cf_plural(kinds, "business group", "business groups"), "No business groups"
        elif k == "dept" and kind == "gc":   # one option per department AND business group
            kinds = len({(_row_get(p, "business_group") or "", (_row_get(p, "department") or "").strip()) for p in people
                         if (_row_get(p, "department") or "").strip()})
            ok, cover, why = kinds > 0, _cf_plural(kinds, "department", "departments"), "No one has a department"
        else:
            ok, cover, why, kinds = _vf_roster_cover(f, people, cfg, each=(k == "jg" and each))
        code = {"jg": "JG · each grade" if each else "JG · %s's bands" % (bg_label or "the group")
                }.get(k) or (f["code"] + (" · " + f["note"] if f.get("note") else ""))
        out.append({"key": k, "label": f["label"], "plural": f["plural"], "code": code, "checked": on,
                    "disabled": (not ok) and not on, "reason": "" if (ok or on) else why, "cover": cover if (ok or on) else "",
                    "kinds": kinds})
    return out


def _vf_leaders(db, ids):
    """{user id: users row} of the calibrators / Group Chiefs on screen, ONE read."""
    return {r["id"]: r for r in db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(ids)),
                                           list(ids))} if ids else {}


def _vf_match(q, qin, leader):
    """Search in over a tab's table: the calibrator or Group Chief is a person, so the search reads their record (people_search_match)."""
    return not q or bool(leader and people_search_match(qin, q, leader))


def _vf_people(db, where, params):
    """Active participants (users rows: the potential axis's population) matching `where`, ONE read."""
    return db.execute("SELECT %s FROM users u WHERE u.role!='admin' AND u.left_at IS NULL AND %s AND %s" % (
        VF_COLS, calibration_population_sql("u"), where), params).fetchall()


def _vf_set_words(own, kind):
    """A viewer's set in words, the line's order: "Department · Cost centre", or "None"."""
    names = [calib_viewer_def(k)["label"] for k in calib_viewer_shown_keys(own, kind)]
    return " · ".join(names) if names else "None"


def _vf_cal_rows(db, bg, q="", qin="all"):
    """The Calibrators tab's rows for one business group: each active calibrator (a calib_bu_groups row), who they are, the
    units they reach, their people, and the filters they show -- their own (set here) or their units' (from its units)."""
    cfg = calib_jg_config(db, bg)
    out = []
    gs = bu_groups_of_bg(db, bg)
    lead = _vf_leaders(db, {g["calibrator_id"] for g in gs})
    names = {i: r["full_name"] for i, r in lead.items()}
    for g in gs:
        if not _vf_match(q, qin, lead.get(g["calibrator_id"])):
            continue
        people = _vf_people(db, "u.business_group=? AND " + bu_group_member_sql("u"), [bg, g["id"]])
        own = calib_viewer_filters(db, "cal", g["id"])
        units = [COMPANY_SHORT.get(c) or display_company(bg, c) or c for c in g["units"]]
        union = [f["key"] for f in CALIB_FILTERS if f["key"] in CALIB_VIEWER_KINDS["cal"]["keys"]
                 and calib_filter_shown(db, bg, g["units"], "bu", f["key"])]
        shown = calib_viewer_shown_keys(own, "cal") if own is not None else union
        rows = _vf_filter_rows("cal", people, {k: True for k in shown}, cfg, bg_label=_bg_tab_label(bg))
        on_units = sorted({COMPANY_SHORT.get(c) or display_company(bg, c) or c for c in g["units"]
                           if any(calib_filter_on(db, bg, k, c, "bu") for k in union)})
        out.append({"id": g["id"], "name": names.get(g["calibrator_id"]) or "Calibrator", "group": g["name"],
                    "units": units, "units_two": units[:2], "units_more": units[2:] if len(units) > 2 else [],
                    "people": len(people), "set_here": own is not None,
                    "filters": " · ".join(calib_viewer_def(k)["label"] for k in shown) or "None",
                    "union_words": [calib_viewer_def(k)["label"] for k in union], "union_units": on_units,
                    "rows": rows})
    out.sort(key=lambda r: ((r["name"] or "").lower(), r["id"]))
    return out


def _vf_gc_rows(db, q="", qin="all"):
    """The Group Chiefs tab's rows: each Group Chief group (pm_calibration_groups), its chief, its people and how many business
    groups they come from, and the filters it shows (Segment always, then its own set)."""
    out = []
    gs = db.execute("SELECT id, name, calibrator_id FROM pm_calibration_groups ORDER BY name COLLATE NOCASE, id").fetchall()
    lead = _vf_leaders(db, {g["calibrator_id"] for g in gs})
    names = {i: r["full_name"] for i, r in lead.items()}
    for g in gs:
        if not _vf_match(q, qin, lead.get(g["calibrator_id"])):
            continue
        people = _vf_people(db, "u.id IN (SELECT subject_id FROM pm_calibration_group_members WHERE group_id=?)", [g["id"]])
        segs = {r[0]: r[1] for r in db.execute("SELECT subject_id, segment FROM pm_calibration_group_members WHERE group_id=? "
                                                "AND COALESCE(segment,'')!=''", (g["id"],))}
        batch = {(segs.get(p["id"]) or "").strip() or (p["department"] or "").strip() for p in people}
        batch.discard("")
        bgs = sorted({p["business_group"] for p in people if p["business_group"]}, key=_bg_display_rank)
        own = calib_viewer_filters(db, "gc", g["id"])
        shown = calib_viewer_shown_keys(own, "gc") if own is not None else []
        rows = [{"key": "seg", "label": "Segment", "plural": "segments", "code": "always on", "checked": True,
                 "disabled": True, "reason": "", "cover": _cf_plural(len(batch), "segment", "segments"), "kinds": len(batch),
                 "always": True}] + _vf_filter_rows("gc", people, own, each=True)
        # how a department reads: its name alone where one business group holds it, else "<Department> · <group>" per group
        by_name = {}
        for p in people:
            d = proper_name((p["department"] or "").strip())
            if d:
                by_name.setdefault(d, set()).add(p["business_group"] or "")
        alone = next(((d, sorted(b)) for d, b in sorted(by_name.items()) if len(b) == 1), None)
        dup = next(((d, sorted(b, key=_bg_display_rank)) for d, b in sorted(by_name.items()) if len(b) > 1), None)
        out.append({"id": g["id"], "name": g["name"], "chief": names.get(g["calibrator_id"]) or "Group Chief",
                    "people": len(people), "bgs": [display_bg(b) or b for b in bgs],
                    "n_bgs": len(bgs), "set_here": own is not None,
                    "filters": " · ".join(["Segment"] + [calib_viewer_def(k)["label"] for k in shown]), "rows": rows,
                    "alone": alone[0] if alone else "",
                    "dup": [(dup[0], display_bg(b) or b) for b in dup[1]] if dup else []})
    return out


def _vf_ec_ctx(db):
    """The Executive Chairman tab: a tick per filter, and where anyone has a value (the business groups of everyone who takes
    part): "in every group", "in 5 of 7 groups"; a filter no group has a value for is disabled."""
    people = db.execute("SELECT %s FROM users u WHERE u.role!='admin' AND u.left_at IS NULL AND u.is_demo=0 AND "
                        "COALESCE(u.business_group,'')!='' AND %s" % (VF_COLS, calibration_population_sql("u"))).fetchall()
    bgs = {p["business_group"] for p in people}
    own = calib_viewer_filters(db, "ec", "")
    rows = []
    for f in CALIB_FILTERS:
        k = f["key"]
        if k not in CALIB_VIEWER_KINDS["ec"]["keys"]:
            continue
        col = "job_grade" if k == "jg" else f["column"]
        n = len({p["business_group"] for p in people if (str(p[col] or "")).strip()})
        on = bool((own or {}).get(k))
        cover = "in every group" if (n == len(bgs) and n) else ("in %d of %d groups" % (n, len(bgs)) if n else "")
        code = {"jg": "JG · the picked group's bands"}.get(k) or (f["code"] + (" · " + f["note"] if f.get("note") else ""))
        rows.append({"key": k, "label": f["label"], "code": code, "checked": on, "disabled": n == 0 and not on,
                     "cover": cover if (n or on) else "",
                     "reason": "" if (n or on) else "No one has a %s" % (f.get("noun") or f["label"].lower()),
                     "n_groups": n})
    return {"rows": rows, "n_bgs": len(bgs), "set_here": own is not None,
            "words": _vf_set_words(own, "ec") if own is not None else "None"}


def _viewer_filters_ctx(db, fview, want_bg, q="", qin="all"):
    """The Filters card's per-viewer tabs (2026-11-02): which tab is open (`unit` today's card, `cal`, `gc`, `ec`: the last only
    while the Executive Chairman view is on), the business groups for the unit and calibrator tabs, and the open tab's rows."""
    tabs = [t for t in VF_TABS if t[0] != "ec" or chair_on()]
    view = fview if fview in {t[0] for t in tabs} else "unit"
    bgs = sorted({r[0] for r in db.execute("SELECT DISTINCT business_group FROM org_units WHERE active=1 AND "
                                           "COALESCE(business_group,'')!='' AND COALESCE(company,'')!=''")},
                 key=_bg_display_rank)
    bg = want_bg if want_bg in bgs else (bgs[0] if bgs else "")
    out = {"view": view, "tabs": [{"key": k, "label": lbl, "sub": sub} for k, lbl, sub in tabs],
           "bg": bg, "bg_label": display_bg(bg) if bg else "",
           "bgs": [{"key": b, "label": _bg_tab_label(b)} for b in bgs]}
    if view == "cal":
        out["cal"] = _vf_cal_rows(db, bg, q, qin) if bg else []
    elif view == "gc":
        out["gc"] = _vf_gc_rows(db, q, qin)
    elif view == "ec":
        out["ec"] = _vf_ec_ctx(db)
    return out


def _st_jg_filter(db, u):
    try:
        n = dict(db.execute("SELECT view, COUNT(*) FROM calib_jg_filter WHERE shown=1 GROUP BY view").fetchall())
    except sqlite3.OperationalError:
        n = {}
    if not n:
        return "Hidden everywhere"
    units = lambda k: "%d unit%s" % (k, "" if k == 1 else "s")
    return "Shown for %s in the BU CEO calibration · %s in the BG CEO Talent Box" % (units(n.get("bu", 0)),
                                                                                   units(n.get("tb", 0)))


def _jg_floor(db):
    """The active cycle's minimum job grade (the first band must start at or under it), or None with no minimum."""
    cyc = active_cycle(db)
    return _row_get(cyc, "min_job_grade") if cyc else None


def _jg_filter_ctx(db, want_bg):
    """The Job grade filter card (Chris, 2026-10-21): the business groups as tabs; the one picked's grouping (named bands
    or each grade on its own), its active people by grade (counts only) for the bands' headcounts, and its units with
    their two switches."""
    bgs = sorted({r[0] for r in db.execute("SELECT DISTINCT business_group FROM org_units WHERE active=1 AND "
                                           "COALESCE(business_group,'')!='' AND COALESCE(company,'')!=''")},
                 key=_bg_display_rank)
    bg = want_bg if want_bg in bgs else (bgs[0] if bgs else "")
    on = calib_jg_filter_map(db, bg) if bg else {}
    units = [r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                      "COALESCE(company,'')!='' ORDER BY company", (bg,))] if bg else []
    cfg = calib_jg_config(db, bg) if bg else {"mode": "bands", "bands": [], "set": False}
    by_grade, other = {}, 0
    if bg:
        for g, n in db.execute("SELECT job_grade, COUNT(*) FROM users WHERE left_at IS NULL AND role!='admin' AND "
                               "business_group=? GROUP BY job_grade", (bg,)):
            k = grade_num(g)
            if k is None:
                other += n
            else:
                by_grade[k] = by_grade.get(k, 0) + n
    floor = _jg_floor(db)
    lo = floor if floor is not None else 1
    return {"bg": bg, "bg_label": display_bg(bg) if bg else "",
            "bgs": [{"key": b, "label": _bg_tab_label(b)} for b in bgs],
            "mode": cfg["mode"], "set": cfg["set"],
            "bands": [{"name": b["name"], "lo": b["lo"], "hi": b["hi"], "label": calib_jg_band_name(b)}
                      for b in sorted(cfg["bands"], key=lambda b: b["lo"])],
            "grades": list(range(lo, CALIB_JG_GRADE_MAX + 1)), "floor": floor, "max_bands": CALIB_JG_MAX_BANDS,
            "name_max": CALIB_JG_NAME_MAX,
            "by_grade": {str(k): v for k, v in sorted(by_grade.items())}, "other": other,
            "rows": [{"company": co, "short": COMPANY_SHORT.get(co) or "", "full": display_company(bg, co) or co,
                      "bu": bool(on.get((co, "bu"))), "tb": bool(on.get((co, "tb")))} for co in units]}


def _st_joins(db, u):
    cid = active_cycle_id(db)
    n = len(calib_joins(db, cid)) if cid else 0
    return "%d this cycle" % n if n else "None this cycle"


def _st_groups(db, u):
    n = _st_count(db, "SELECT COUNT(*) FROM pm_calibration_groups")
    return "%d group%s" % (n, "" if n == 1 else "s") if n else "None"


def _st_idp(part):
    def f(db, u):
        rule, lo, hi, ai = get_idp_settings()
        if part == "actions":
            return IDP_ACTION_RULES.get(rule, rule)
        if part == "goals":
            return ("%d to %d" % (lo, hi)) if hi else "At least %d, no ceiling" % lo
        return _st_onoff(ai, ai=True)
    return f


def _st_identity(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    half = {0: "Early Year (KPI setting)", 1: "Mid-Year (H1)", 2: "Year-End (H2)"}.get(cyc["half"], "half not set")
    return "%s · code %s · %s, %s" % (cyc["name"], cyc["code"], cyc["year"] or "year not set", half)


def _st_cycle_dates(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    return "%s → %s" % (_st_day(cyc["starts_on"]) or "open now", _st_day(cyc["ends_on"]) or "no target date")


def _st_cycle_modules(db, u):
    keys = [k for k in CYCLE_MODULE_KEYS if k not in PARKED_MODULES]
    off = [CYCLE_MODULE_LABELS[k] for k in keys if not cycle_module_on(k)]
    return "%d of %d on" % (len(keys) - len(off), len(keys)) + (" · off: " + ", ".join(off) if off else "")


def _st_participants(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    where, params = bg_scope(u, "u.business_group")
    r = db.execute("SELECT SUM(p.mode='add'), SUM(p.mode='remove') FROM cycle_participants p JOIN users u ON "
                   "u.id=p.subject_id WHERE p.cycle_id=?" + where, [cyc["id"]] + params).fetchone()
    add, rem = (r[0] or 0, r[1] or 0) if r else (0, 0)
    if not add and not rem:
        return "The confirmation rule, no admin changes"
    return "The confirmation rule · %d added, %d taken out by an admin" % (add, rem)


def _st_windows(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    keys = [c for c in WINDOW_KEYS if c not in GRADEH_CELL_KEYS or gradeh_cycle_offered(cyc)]
    n = sum(1 for c in keys if any(window_dates(db, c, cyc["id"])))
    return "%d of %d dated · the rest open all cycle" % (n, len(keys)) if n < len(keys) \
        else "All %d dated" % n


def _st_release(db, u):
    cyc = active_cycle(db)
    if not cyc:
        return "No active cycle"
    where, params = bg_scope(u, "u.business_group")
    n = _st_count(db, "SELECT COUNT(*) FROM users u WHERE (u.id IN (SELECT subject_id FROM talent_releases WHERE "
                  "cycle_id=?) OR u.id IN (SELECT subject_id FROM result_releases WHERE cycle_id=?))" + where,
                  [cyc["id"], cyc["id"]] + params)
    return "%d people released" % n if n else "Nothing released yet"


def _st_org_units(db, u):
    return "%d business groups · %d units" % (len(org_bgs(db)), _st_count(
        db, "SELECT COUNT(*) FROM org_units WHERE active=1"))


def _st_leaders(db, u):
    where, params = bg_scope(u, "business_group")
    hods = _st_count(db, "SELECT COUNT(DISTINCT hod_id) FROM users WHERE left_at IS NULL AND hod_id IS NOT NULL"
                     + where, params)
    bu = _st_count(db, "SELECT COUNT(DISTINCT s.user_id) FROM buceo_seats s JOIN users u ON u.id=s.user_id WHERE "
                       "u.left_at IS NULL" + bg_scope(u, "s.business_group")[0], bg_scope(u, "s.business_group")[1])
    bgc = _st_count(db, "SELECT COUNT(*) FROM users WHERE COALESCE(bgceo_bg,'')!='' AND left_at IS NULL" + where,
                    params)
    return "%d HODs · %d BU CEOs · %d BG CEOs" % (hods, bu, bgc)


def _st_admins(db, u):
    n = _st_count(db, "SELECT COUNT(*) FROM users WHERE role='admin' AND COALESCE(admin_bg,'')!='' AND left_at IS NULL")
    m = _st_count(db, "SELECT COUNT(DISTINCT c.admin_id) FROM admin_companies c JOIN users u ON u.id=c.admin_id "
                      "WHERE u.left_at IS NULL")
    return "%d BG admin%s · %d sub-admin%s" % (n, "" if n == 1 else "s", m, "" if m == 1 else "s")


def _st_rollout(db, u):
    return "Everyone" if _setting("review_unified") != "0" else "Off: the classic module pages for everyone"


def _st_tb_limits(db, u):
    """The All settings row for the Talent Box limits card: Off, or what is on."""
    t = get_tb_limits()
    parts = (["Moves %g%% per unit" % t["moves_pct"]] if t["moves_on"] else []) + (
        ["Stars and Super Stars on"] if t["stars_on"] else [])
    return " · ".join(parts) if parts else "Off"


def _srow(key, label, value, log=None):
    """One setting: its key, its label, how it reads now (value(db, u)), and the activity_log rows that record a
    change to it (actions, detail prefix) for its 'last changed'."""
    return {"key": key, "label": label, "value": value, "log": log}


def _ai_row(key, label):
    # its own switch's log line only ("AI drafting for <module> on/off"): a shared "AI drafting" prefix showed the last
    # change to ANY AI switch as this one's (the admin review, 2026-10-11)
    mod = dict((k, lbl) for k, lbl, _d in AI_MODULES).get(key, "")
    return _srow(key, label, lambda db, u: _st_onoff(ai_module_settings().get(key, True), ai=True),
                 (("settings",), "AI drafting for %s " % mod))


def _st_connect(db, u):
    """The All settings row: how many tokens are live."""
    n = db.execute("SELECT COUNT(*) FROM mcp_tokens WHERE user_id=? AND revoked_at IS NULL AND expires_at > datetime('now')",
                   (u["id"],)).fetchone()[0]
    return "%d live token%s" % (n, "" if n == 1 else "s") if n else "No live tokens"


