# Sidebar order, which the sheet and the search follow.
ADMIN_SETTINGS_ORDER = ("cycle", "pm", "f360", "competency", "calibration", "idp", "org")


def _setting_last_map(db):
    """The latest activity_log row per action for every action the settings name -- ONE read, matched in Python, so
    the sheet costs one query for 'last changed' rather than one per setting."""
    actions = sorted({a for m in ADMIN_SETTINGS.values() for sec in m["sections"] for r in sec["rows"]
                      if r["log"] for a in r["log"][0]})
    if not actions:
        return []
    return db.execute("SELECT a.action, a.detail, a.created_at, u.full_name FROM activity_log a LEFT JOIN users u "
                      "ON u.id=a.user_id WHERE a.action IN (%s) ORDER BY a.id DESC LIMIT 4000"
                      % ",".join("?" * len(actions)), actions).fetchall()


def _setting_last(log_rows, log):
    if not log:
        return None
    actions, prefix = log
    for r in log_rows:
        if r["action"] in actions and (not prefix or (r["detail"] or "").startswith(prefix)):
            return {"when": _st_day(r["created_at"]), "who": r["full_name"] or "an admin"}
    return None


def _settings_view(db, u, key, log_rows=None):
    """One module's settings sections, ready to render: each row with its value and last change, each section with
    whether this admin may change it here and, for a Dates card, its rows."""
    mod = ADMIN_SETTINGS[key]
    log_rows = _setting_last_map(db) if log_rows is None else log_rows
    out = []
    for sec in mod["sections"]:
        if sec.get("gate") == "system" and not is_system(u):   # AI+ Connect's row shows only to a system admin (2026-10-28)
            continue
        if sec.get("flag") == "chair" and not chair_on():   # the Executive Chairman's cards exist only while his view is on
            continue
        if sec.get("open") and not _admin_nav_allowed({"ep": sec["open"][0]}, u):
            open_ = None
        else:
            open_ = ({"href": url_for(sec["open"][0], **(sec["open"][2] if len(sec["open"]) > 2 else {})),
                      "label": sec["open"][1]} if sec.get("open") else None)
        rows = []
        for r in sec["rows"]:
            try:
                val = r["value"](db, u)
            except Exception:   # one setting that can't be read must never take the page down
                app.logger.exception("setting value failed: %s", r["key"])
                val = "Could not be read"
            rows.append({"key": r["key"], "label": r["label"], "value": val, "last": _setting_last(log_rows, r["log"])})
        lasts = [x["last"] for x in rows if x["last"]]
        out.append({**sec, "rows": rows, "open": open_, "scope_label": SETTING_SCOPES[sec["scope"]],
                    "can_edit": sec.get("gate") not in ("super", "system") or is_super(u),
                    "last": lasts[0] if lasts else None,
                    "date_rows": _st_date_rows(db, sec["cells"]) if sec.get("cells") else []})
    return out


def _settings_href(key, sec):
    """Where a setting lives: its card on the module's Settings page, or -- for the cycle, which has no such page --
    the page that edits it."""
    if key == "cycle":
        return url_for(sec["open"][0])
    return url_for("admin_module_settings", key=key) + "#" + sec["id"]


# Module order, product-wide: PM, TM, Promotion Nomination, IDP, Calibration,
# Succession Planning, Reward. General is not a module -- it is the settings
# that belong to no one module, so it leads.
#
# A tab may hold SECTIONS instead of a single endpoint. Talent Management does:
# it covers two assessments, the 360 and the technical competency assessment.
# The tab then lands on the first section this admin may actually open, which
# matters here because the 360 framework is super-only while career routes is
# not -- a fixed endpoint would 403 every BG admin who clicked TM.
SETTINGS_TABS = [
    # What is left once every module owns its own settings page: the org-wide
    # rules that belong to no single module (score thresholds, tier bands, the
    # extreme-assessor correction). Kept as its own top-level item so those
    # rules still have one obvious home.
    {"key": "general", "label": "General", "endpoint": "admin_settings", "gate": "super"},
]


def _settings_sections(tab, me):
    """The sections of a tab this admin may open (empty for a plain tab)."""
    return [x for x in tab.get("sections", ())
            if x["gate"] != "super" or is_super(me)]


def _settings_tab_endpoint(tab, me):
    """Where a settings tab lands: its own endpoint, or -- for a tab with
    sections -- the first section this admin can actually open. None when a
    sectioned tab has nothing open to them, so the tab is dropped entirely
    rather than offered and then refused."""
    if tab.get("endpoint"):
        return tab["endpoint"]
    allowed = _settings_sections(tab, me)
    return allowed[0]["endpoint"] if allowed else None


def _settings_shell(tab_key, **ctx):
    """Render one settings panel inside the shared settings shell.

    A super-only tab is hidden from a BG admin rather than shown and then
    refused -- the same rule the Hub already follows: offer only what the
    person can actually use. The gate here is presentation only; each route
    keeps its own decorator, which is what actually enforces access."""
    me = current_user()
    tabs = []
    for t in SETTINGS_TABS:
        if t["gate"] == "super" and not is_super(me):
            continue
        ep = _settings_tab_endpoint(t, me)
        if not ep:
            continue
        tabs.append({**t, "href": url_for(ep)})
    # The label comes from the MODULE now, since that is where these pages
    # live; SETTINGS_TABS only still holds General, which is not a module.
    cur = next((m for m in ADMIN_MODULES if m["key"] == tab_key), None) \
        or next((t for t in SETTINGS_TABS if t["key"] == tab_key), None)
    label = cur["label"] if cur else {"promotion": "Promotion Nomination"}.get(tab_key, "")
    # A module with sub-modules names the one being configured: the 360's
    # settings page should not head itself "Talent Management" -- the module
    # menu already said that, and the heading should say which of TM's two
    # assessments this is.
    sub = {"360": "360 Feedback", "profiles": "Competency assessment",
           "competency": "Career routes"}.get(ctx.get("tm_section"))
    if sub:
        label = sub
    return render_template("admin_settings_shell.html",
                           settings_tabs=tabs,
                           settings_tab=tab_key,
                           settings_tab_label=label,
                           settings_panel="settings/_%s.html" % tab_key,
                           tm_sections=_settings_sections(cur, me) if cur else [],
                           **ctx)


@app.route("/admin/promotion/config", methods=["GET", "POST"])
@admin_required
def admin_promotion_config():
    """Settings -> Promotion Nomination: the standing rules that put somebody
    on the list without anyone nominating them, and how far a nomination may
    reach up the grade ladder.

    A rule is fully described by its length and its floor, so that is all the
    panel asks for -- the label the page shows is generated from those two,
    and cannot drift away from what the rule actually checks."""
    db = get_db()
    # These rules are ORG-WIDE: their setter writes app_settings, which has no
    # business_group dimension, so one BG's admin saving here changes the rules
    # for every employee in the group. Viewing stays open to any admin (the
    # rules govern their own people and they should be able to read them);
    # saving is super-only. Same shape, and the same reasoning, as
    # admin_competency_profiles(), which gates its own org-wide object this way.
    if request.method == "POST" and not is_super(current_user()):
        abort(403)
    if request.method == "POST":
        rules, seen = [], set()
        for i in ("1", "2", "3"):
            raw_years = (request.form.get("rule_years_" + i, "") or "").strip()
            cat = (request.form.get("rule_cat_" + i, "") or "").strip()
            if not raw_years or raw_years == "0":
                continue        # a blank or zero-year row is a rule turned off
            if cat not in TALENT_CATEGORY_ORDER:
                flash("Pick a talent category for every rule you fill in.", "error")
                return redirect(url_for("admin_promotion_config"))
            try:
                years = int(raw_years)
            except ValueError:
                flash("Rule lengths must be whole years.", "error")
                return redirect(url_for("admin_promotion_config"))
            if not 1 <= years <= 10:
                flash("A rule length has to be between 1 and 10 years.", "error")
                return redirect(url_for("admin_promotion_config"))
            if (years, cat) in seen:
                continue        # the same rule twice is one rule
            seen.add((years, cat))
            rules.append((years, cat))
        try:
            reach = int((request.form.get("grade_reach", "") or "").strip())
        except ValueError:
            flash("Grade reach must be a whole number.", "error")
            return redirect(url_for("admin_promotion_config"))
        if not 1 <= reach <= 11:
            flash("Grade reach has to be between 1 and 11 — the ladder is JG 12 to 23.",
                  "error")
            return redirect(url_for("admin_promotion_config"))
        set_promotion_settings(rules, reach)
        log_activity(db, current_user()["id"], "settings",
                     "Promotion: rules=%s, grade reach %d"
                     % ("; ".join(f"{y}y {c}" for y, c in rules) or "none", reach))
        flash("Promotion nomination settings updated.", "ok")
        return redirect(url_for("admin_promotion_config"))

    # Back to (years, category) pairs for the form: the stored shape is the
    # frozenset the matcher wants, and its floor is the FIRST category of
    # TALENT_CATEGORY_ORDER present in it.
    live = []
    for years, cats, _label in promo_auto_rules(db):
        floor = next((c for c in TALENT_CATEGORY_ORDER if c in cats), None)
        if floor:
            live.append((years, floor))
    return _settings_shell("promotion", rules=live,
                           rule_slots=[0, 1, 2],
                           grade_reach=promo_grade_reach(db),
                           history_years=promo_history_years(db),
                           categories=TALENT_CATEGORY_ORDER,
                           category_slug=TALENT_CATEGORY_SLUG)


@app.route("/admin/idp/config", methods=["GET", "POST"])
@admin_required
def admin_idp_config():
    """Settings -> IDP: what a development plan must hold before an employee
    can share it, and whether they get AI drafting for it.

    Every default reproduces the behaviour these rules had while they were
    hardcoded in idp_submit() and PM_IDP_MAX_GOALS, so opening the panel
    changes nothing until somebody moves a control."""
    db = get_db()
    # These rules are ORG-WIDE: their setter writes app_settings, which has no
    # business_group dimension, so one BG's admin saving here changes the rules
    # for every employee in the group. Viewing stays open to any admin (the
    # rules govern their own people and they should be able to read them);
    # saving is super-only. Same shape, and the same reasoning, as
    # admin_competency_profiles(), which gates its own org-wide object this way.
    if request.method == "POST" and not is_super(current_user()):
        abort(403)
    if request.method == "POST":
        rule = (request.form.get("action_rule", "") or "").strip()
        if rule not in IDP_ACTION_RULES:
            flash("Pick a valid action requirement.", "error")
            return _settings_back("idp", "plan-rules")
        try:
            min_goals = int((request.form.get("min_goals", "") or "").strip())
            max_goals = int((request.form.get("max_goals", "") or "").strip())
        except ValueError:
            flash("Goal counts must be whole numbers.", "error")
            return _settings_back("idp", "plan-rules")
        if min_goals < 1:
            flash("A plan has to hold at least one goal.", "error")
            return _settings_back("idp", "plan-rules")
        if max_goals and max_goals < min_goals:
            flash("The maximum can't be below the minimum.", "error")
            return _settings_back("idp", "plan-rules")
        ai_on = request.form.get("ai_enabled") == "1"
        set_idp_settings(rule, min_goals, max_goals, ai_on)
        log_activity(db, current_user()["id"], "settings",
                     "IDP: actions=%s, goals %d-%s, employee AI %s"
                     % (rule, min_goals, max_goals or "unlimited",
                        "on" if ai_on else "off"))
        flash("IDP settings updated.", "ok")
        return _settings_back("idp", "plan-rules")

    # The rules now sit on the Career Plan's Settings page with its dates (2026-10-10): this address leads there.
    return redirect(url_for("admin_module_settings", key="idp") + "#plan-rules")


def _general_settings_ctx(db):
    """What the settings cards split out of the old General page read (thresholds, weighting, the rules, the AI and
    calibration switches...)."""
    low_max, mid_max = get_thresholds()
    acid = active_cycle_id(db)
    sample_max = max_score_for_grade(db, 16, acid)  # uniform across grades
    cycle_cutoffs = _cycle_own_cutoffs(db)
    acyc = active_cycle(db)
    # the cutoffs the active cycle bands on now, and whether they are its own (2026-10-11)
    this_cutoffs = None
    if acyc:
        t_lo, t_mi = thresholds_for_cycle(db, acyc["id"])
        this_cutoffs = {"name": acyc["name"], "low": t_lo, "mid": t_mi, "max": sample_max,
                        "own": bool(cycle_cutoffs)}
    _bw_rows = [(jg, w[0], w[1]) for jg, w in sorted(tc_band_weights(db).items(), key=lambda kv: _jg_sort_key(kv[0]))]
    rules_cycle = None
    if acyc:   # the active cycle's own rules fold on the Panel rules card (2026-10-27)
        rules_cycle = {"id": acyc["id"], "name": acyc["name"], **_cycle_rules_view(acyc)}
    extremes_enabled, extremes_bonus, extremes_penalty = get_extremes_adjustment_settings()
    _tb_lim, _tb_figs = get_tb_limits(), tb_curve_figures()   # the Talent Box limits card
    # AI drafting: which surfaces may offer it, plus the injection-flag counts.
    # Those two tables had three INSERTs and zero SELECTs anywhere -- the
    # "daily read-only report" the code comment promises does not exist, so the
    # audit trail was write-only. This is the first thing that reads it.
    try:
        ai_flags = db.execute(
            "SELECT (SELECT COUNT(*) FROM ai_draft_flags) a, "
            "       (SELECT COUNT(*) FROM pm_ai_draft_flags) b").fetchone()
        ai_flag_count = (ai_flags["a"] or 0) + (ai_flags["b"] or 0)
    except sqlite3.OperationalError:
        ai_flag_count = 0
    return dict(ai_modules=AI_MODULES,
                           ai_settings=ai_module_settings(),
                           ai_configured=ai_draft.is_configured(),
                           ai_flag_count=ai_flag_count,
                           low_max=low_max, mid_max=mid_max, cycle_cutoffs=cycle_cutoffs, this_cutoffs=this_cutoffs,
                           sample_max=sample_max, panel_target=panel_target(),
                           pts360=points_for(db, acid, "360"),   # the cycle's own points, for the cards' wording (Points per answer)
                           sample_tc_max=float(points_max(points_for(db, acid, "tc"), *POINTS_TC_REF)),
                           default_panel_size=default_panel_size(), default_assessor_cap=default_assessor_cap(),
                           assessor_cap_choices=ASSESSOR_CAP_CHOICES,
                           default_min_valid=default_min_valid(),
                           default_tiers=default_tiers(), rules_cycle=rules_cycle,
                           tiers=tier_breakdown(db, acid, default_tiers()),
                           extremes_enabled=extremes_enabled, extremes_bonus=extremes_bonus,
                           extremes_penalty=extremes_penalty,
                           tb_limits=_tb_lim, tb_curve_figs=_tb_figs, tb_curve_rows=TB_LIMIT_CURVE_ROWS,
                           tb_was={"moves_on": _tb_lim["moves_on"], "moves_pct": _tb_lim["moves_pct"],
                                   "stars_on": _tb_lim["stars_on"], "stars": _tb_lim["stars"], "curves": _tb_figs,
                                   "names": {k_: n_ for k_, n_, _r in TB_LIMIT_CURVE_ROWS}},   # the card's confirm box reads it
                           calib_dev_pct=get_calib_dev_pct(), calib_rule=get_calib_rule(),
                           calib_assist_on=ai_module_settings().get("ai_calib", True),
                           calib_assist_configured=ai_draft.review_agent_available(),
                           show_band=get_show_potential_band(),
                           band_weights=_bw_rows, band_split=_common_band_split(_bw_rows),
                           all_bgs=org_bgs(db),
                           review_unified_all=(_setting("review_unified") != "0"))


def _admin_next(default):
    """Back to the page an admin form came from: its `next`, when that is an admin path on this site, else default."""
    nxt = _local_path(request.form.get("next"), "")
    if nxt.startswith("/admin/"):
        return redirect(nxt)
    return redirect(default)


def _settings_back(module, anchor):
    """Where a settings save returns to: the page the form came from (its `next`), else the card's home on its
    module's Settings page."""
    return _admin_next(url_for("admin_module_settings", key=module) + "#" + anchor)


def _cycle_rules_view(c):
    """A cycle's rules as the pages show them: whether it overrides the default (panel size, reliable-at, bands, most
    one person rates) and the effective values. One function for the All cycles page and the Panel rules card."""
    return {"overrides_rules": bool(c["panel_size"] is not None or c["min_valid"] or c["tiers_json"]
                                    or c["assessor_cap"] is not None),
            "eff_panel": effective_panel_size(c), "eff_min_valid": effective_min_valid(c),
            "eff_cap": effective_assessor_cap(c),
            "eff_tiers": [{**t, "grades": _tier_grades_label(t)} for t in effective_tiers(c)]}


def _common_band_split(weights):
    """The one 360 share every grade shares, as a number, else None when the grades differ (or there are none).
    `weights` is band_weights' (jg, w360, wtech) rows."""
    vals = {round(float(w), 4) for _jg, w, _t in weights}
    return vals.pop() if len(vals) == 1 else None


def _cycle_own_cutoffs(db):
    """The active cycle's own potential cutoffs, when it has them: {name, low, mid, max}. None when it follows the
    default (both columns NULL), so the default thresholds are what it bands on."""
    cyc = active_cycle(db)
    if not cyc or cyc["low_max"] is None or cyc["mid_max"] is None:
        return None
    return {"name": cyc["name"], "low": cyc["low_max"], "mid": cyc["mid_max"],
            "max": max_score_for_grade(db, 16, cyc["id"])}


def _rating_records_follow_settings(db, actor_id, why, cycle_id=None):
    """After a change to how potential is worked out (the 360 : competency weighting, the band cutoffs), the running
    cycle's ratings record is rebuilt so it never shows a band the new rules no longer give (Chris approved, 2026-10-11:
    it used to wait for the next sign-off or a Capture). About 1 ms a person on staging (1,055 in ~1 s); a frozen
    (archived) cycle's records are never touched. The request's caches are dropped first so the rebuild reads the
    new values. Returns how many were brought up to date. `cycle_id` picks another cycle (Edit cycle's potential
    switch, 2026-10-14) -- still only its unfrozen records."""
    cid = cycle_id or active_cycle_id(db)
    if not cid:
        return 0
    for k in ("_tc_band_weights", "_cycle_thresholds", "_active_cycle", "_points_cache"):
        g.pop(k, None)
    _req_cache().pop("_hp_%s" % cid, None)   # cycle_has_potential reads the new value
    ids = [r[0] for r in db.execute("SELECT subject_id FROM rating_records WHERE cycle_id=? AND frozen_at IS NULL "
                                    "AND subject_id IS NOT NULL", (cid,))]
    n = 0
    for i in range(0, len(ids), _RR_CAPTURE_BATCH):
        n += _rating_record_refresh(db, cid, ids[i:i + _RR_CAPTURE_BATCH], why, actor_id, commit=True)
    return n


# ---------------------------------------------------------------------------
# Points per answer: the cards (360 Feedback and Competency Settings), the check and the save (Chris, 8-9 Nov 2026)
# Three settings of the same shape (the third, Grade H's, is its own piece): Demonstrate current / next, Developing current /
# next, each its own for the 360 and the competency. A default (app_settings points_360 / points_tc) plus a cycle's own four
# columns (cycles.pts360_* / ptstc_*, NULL = it follows the default), like Panel rules. A save asks WHEN IT STARTS: the current
# cycle (open only until its first potential result is released: it is re-scored at once) or from the next cycle on (the current
# cycle is pinned at its present points first). Super admin only, a reason required (the super admin's band remark).
# ---------------------------------------------------------------------------
POINTS_TC_REF = (5, 5)   # 5 competencies a person at the current level and 5 at the next (Chris, 6 Nov)
POINTS_MSG_RANGE = "Each value is 0 to 10, with at most one decimal."
POINTS_MSG_VC = "Developing must earn less than Demonstrate at the current level."
POINTS_MSG_VN = "Developing must earn less than Demonstrate at the next level."
POINTS_MSG_DN = "Demonstrate at the next level must earn at least as much as at the current level."
POINTS_MSG_VN_UP = "Developing at the next level must earn at least as much as at the current level."


def _points_decimal(v):
    """One posted figure as a Decimal: 0 to 10 with at most one decimal, else None."""
    try:
        d = Decimal(str(v).strip())
    except (InvalidOperation, ValueError):
        return None
    if not d.is_finite() or d < 0 or d > 10:
        return None
    return d if d == d.quantize(Decimal("0.1")) else None


def points_parse(raw):
    """(Points, []) for four posted values (a mapping with dc, dn, vc, vn), else (None, [messages]). THE validator of both kinds,
    mirrored live by the card's script: each 0 to 10 with one decimal at most; Developing below Demonstrate at the same level
    (vc < dc, vn < dn); the next level at least the current (dn >= dc, vn >= vc). Developing above 0 is allowed."""
    vals = [_points_decimal(raw.get(k)) for k in _PTS_PARTS]
    if any(v is None for v in vals):
        return None, [POINTS_MSG_RANGE]
    dc, dn, vc, vn = vals
    errs = []
    if vc >= dc:
        errs.append(POINTS_MSG_VC)
    if vn >= dn:
        errs.append(POINTS_MSG_VN)
    if dn < dc:
        errs.append(POINTS_MSG_DN)
    if vn < vc:
        errs.append(POINTS_MSG_VN_UP)
    if errs:
        return None, errs
    return Points(*[float(v) for v in vals]), []


def points_released_on(db, cycle_id):
    """The MYT date ('20 Nov 2026') the cycle's FIRST potential result went out, to leaders or to the person, else None.
    A cycle's points are fixed from then on. The kinds in the code: result_releases.kind 'pot' (the person's), leader_releases.kind
    'pot' and 'talent' (the leaders'; talent status carries the potential result, as setup_released_at reads it) and
    talent_releases (the person's talent status). One query."""
    if not cycle_id:
        return None
    r = db.execute(
        "SELECT MIN(t) FROM (SELECT released_at t FROM result_releases WHERE cycle_id=? AND kind='pot' "
        "UNION ALL SELECT released_at FROM leader_releases WHERE cycle_id=? AND kind IN ('pot','talent') "
        "UNION ALL SELECT released_at FROM talent_releases WHERE cycle_id=?)", (cycle_id, cycle_id, cycle_id)).fetchone()
    return _myt_date_str(r[0]) if r and r[0] else None


def _points_released_ids(db):
    """The ids of every cycle with a potential result released (points_released_on's rule over all cycles): ONE query."""
    return {r[0] for r in db.execute(
        "SELECT cycle_id FROM result_releases WHERE kind='pot' UNION SELECT cycle_id FROM leader_releases WHERE kind IN "
        "('pot','talent') UNION SELECT cycle_id FROM talent_releases")}


def _points_pinned(crow, kind):
    """True when the cycle row holds its own points of this kind (all four columns set)."""
    return all(crow[c] is not None for c in _points_cols(kind))


def _points_own(crow, kind):
    return Points(*[float(crow[c]) for c in _points_cols(kind)])


def _points_ref_cycle(db):
    """The cycle whose framework the cut-off rescale reads: the active one, else the latest that has a framework."""
    cyc = active_cycle(db)
    if cyc:
        return cyc["id"]
    r = db.execute("SELECT cycle_id FROM cycle_statements GROUP BY cycle_id ORDER BY cycle_id DESC LIMIT 1").fetchone()
    return r[0] if r else None


def _points_all_counts(db, cycle_id):
    """(behaviours at the current level, at the next level) summed over ALL tiers of the cycle's framework: the 360's maximum
    summed over its tiers is N_cur x dc + N_fut x dn, what the cut-offs' rescale factor is the ratio of."""
    if not cycle_id:
        return 0, 0
    r = db.execute("SELECT COALESCE(SUM(CASE WHEN is_future=1 THEN 0 ELSE 1 END), 0), "
                   "COALESCE(SUM(CASE WHEN is_future=1 THEN 1 ELSE 0 END), 0) FROM cycle_statements WHERE cycle_id=?",
                   (cycle_id,)).fetchone()
    return int(r[0]), int(r[1])


def points_cut_factor(db, ref_cycle_id, old, new):
    """New maximum over old, over the reference cycle's statements summed over all its tiers: the factor the 360's potential
    cut-offs are multiplied by when its points change (they keep their share of the maximum). 1 when there is nothing to scale."""
    n_cur, n_fut = _points_all_counts(db, ref_cycle_id)
    om, nm = points_max(old, n_cur, n_fut), points_max(new, n_cur, n_fut)
    return (nm / om) if om > 0 else 1.0


def _points_cut_round(v, f):
    return None if v is None else round(float(v) * f, 2)


def _points_plan(db, kind, new, when):
    """What saving `new` for `when` ('current' | 'next') does, WITHOUT writing: the check step reads it and the save runs it, so
    what the step says is what happens. Keys: old (the default now), pins (PAST cycles that follow the default: not the current
    one, and archived, released or older than the current cycle: pinned at old, with the default cut-offs where they hold none, 360), pin_current / unpin_current, cut_default
    ((low, mid) after, 360), cut_cycles (a cycle's own cut-offs rescaled), cur_cuts (the current cycle's cut-offs after)."""
    old = points_default(db, kind)
    cur = active_cycle(db)
    rel = _points_released_ids(db)
    ref = _points_ref_cycle(db)
    is360 = kind == "360"
    d_lo, d_mi = get_thresholds()
    cycles = [dict(r) for r in db.execute("SELECT * FROM cycles ORDER BY id")]
    plan = {"kind": kind, "when": when, "new": new, "old": old, "pins": [], "pin_current": False, "unpin_current": False,
            "cut_default": None, "cut_cycles": [], "cur_cuts": None, "cur": cur, "ref": ref}
    pinned = {c["id"]: all(c[x] is not None for x in _points_cols(kind)) for c in cycles}
    cut_state = {c["id"]: [c["low_max"], c["mid_max"]] for c in cycles}
    by_id = {c["id"]: c for c in cycles}
    # what the current cycle scores on before the save: its own points when it holds them, else the default
    cur_old = (_points_own(by_id[cur["id"]], kind) if pinned[cur["id"]] else old) if cur else None
    for c in cycles:   # step 2: a PAST cycle that follows the default is pinned at the OLD values first
        # past = not the current cycle and (archived, or a potential result released, or an id below the current cycle's: a cycle
        # that is closed in all but name must never be re-scored by a default save). A cycle newer than the current one (a draft,
        # a future cycle) keeps following the default. With no active cycle: archived or released only.
        is_cur = bool(cur) and c["id"] == cur["id"]
        is_past = c["archived_at"] is not None or c["id"] in rel or (bool(cur) and c["id"] < cur["id"])
        if not pinned[c["id"]] and not is_cur and is_past:
            plan["pins"].append({"id": c["id"], "name": c["name"],
                                 "fill_cuts": is360 and (c["low_max"] is None or c["mid_max"] is None)})
            pinned[c["id"]] = True
            if is360:
                cut_state[c["id"]] = [d_lo if c["low_max"] is None else c["low_max"],
                                      d_mi if c["mid_max"] is None else c["mid_max"]]
    if cur and when == "next" and not pinned[cur["id"]]:   # step 3: the current cycle keeps its present points and cut-offs
        plan["pin_current"] = True
        pinned[cur["id"]] = True
        if is360:
            cut_state[cur["id"]] = [d_lo if by_id[cur["id"]]["low_max"] is None else by_id[cur["id"]]["low_max"],
                                    d_mi if by_id[cur["id"]]["mid_max"] is None else by_id[cur["id"]]["mid_max"]]
    elif cur and when == "current":   # ...or follows the new default
        plan["unpin_current"] = pinned[cur["id"]]
        pinned[cur["id"]] = False
    if is360:   # step 5: the cut-offs keep their share of the maximum
        f_def = points_cut_factor(db, ref, old, new)
        plan["factor"] = f_def
        plan["cut_default"] = (_points_cut_round(d_lo, f_def), _points_cut_round(d_mi, f_def))
        for c in cycles:
            if pinned[c["id"]]:
                continue
            lo, mi = cut_state[c["id"]]
            if lo is None and mi is None:
                continue   # it follows the default's cut-offs, which move with it
            # the current cycle moves from what IT scored on (its own points, when it held them) to the new default
            f = points_cut_factor(db, ref, cur_old, new) if (cur and c["id"] == cur["id"]) else f_def
            plan["cut_cycles"].append({"id": c["id"], "name": c["name"], "lo": _points_cut_round(lo, f),
                                       "mi": _points_cut_round(mi, f), "lo_was": lo, "mi_was": mi})
        if cur and when == "current":
            own = next((x for x in plan["cut_cycles"] if x["id"] == cur["id"]), None)
            plan["cur_cuts"] = (own["lo"], own["mi"]) if own and own["lo"] is not None and own["mi"] is not None else plan["cut_default"]
        elif cur:
            plan["cur_cuts"] = thresholds_for_cycle(db, cur["id"])
    return plan


def _subject_assessor_scores(db, subject_id, cycle_id):
    """[(assessor_id, score)] of a subject's SUBMITTED ratings in a cycle: what subject_band and the points check score."""
    return [(r["assessor_id"], assignment_score(db, r["id"], tier=None)[0]) for r in db.execute(
        "SELECT id, assessor_id FROM assignments WHERE subject_id=? AND cycle_id=? "
        "AND status='submitted' AND archived=0", (subject_id, cycle_id)).fetchall()]


def _points_snapshot(db, user, cid, kind):
    """(the figures a points change can move, the raw potential band) for one person: their 360 average and combined potential
    score (and, for the competency, their own and the approved competency score)."""
    _raw, avg, _adj, band, combo = _score_band_adjusted(db, user, cid, _subject_assessor_scores(db, user["id"], cid))
    figs = [avg, combo.get("score"), combo.get("self_score"), combo.get("pts_tech"), combo.get("tech_self")]
    if kind == "tc":
        a = db.execute("SELECT id FROM tc_assessments WHERE cycle_id=? AND subject_id=? AND status IN ('submitted','reviewed')",
                       (cid, user["id"])).fetchone()
        if a:
            figs += [tc_score(db, a["id"], "self")[0], tc_score(db, a["id"], "effective")[0]]
    return tuple(None if x is None else round(float(x), 6) for x in figs), band


def _points_people(db, cid, kind):
    """The people of the cycle whose score the points can move: those with a submitted 360 rating (360), those whose competency
    self-assessment is in (competency). Real people only (no admin, no demo), the rows themselves."""
    if kind == "360":
        sql = ("SELECT DISTINCT a.subject_id FROM assignments a WHERE a.cycle_id=? AND a.status='submitted' AND a.archived=0")
    else:
        sql = "SELECT DISTINCT subject_id FROM tc_assessments WHERE cycle_id=? AND status IN ('submitted','reviewed')"
    ids = [r[0] for r in db.execute(sql, (cid,))]
    out = []
    for k in range(0, len(ids), 500):
        part = ids[k:k + 500]
        out += db.execute("SELECT * FROM users WHERE role!='admin' AND is_demo=0 AND id IN (%s) ORDER BY id" % ",".join("?" * len(part)),
                          part).fetchall()
    return out


def points_whatif(db, kind, cid, new, new_cuts=None):
    """{"n": people whose score changes, "m": people whose raw potential band changes} if the cycle scored on `new` (and, for the
    360, banded on `new_cuts`): the REAL scorers run twice over the cycle's people, once as they stand and once with the new
    points held in g._points_ov (and the new cut-offs in g._cycle_thresholds) for this request only. Nothing is written."""
    if not has_request_context():
        raise RuntimeError("points_whatif needs a request")
    people = _points_people(db, cid, kind)
    before = {u["id"]: _points_snapshot(db, u, cid, kind) for u in people}
    was_cuts = getattr(g, "_cycle_thresholds", None)
    g._points_ov = {(kind, cid): tuple(new)}
    g._cycle_thresholds = dict(was_cuts or {})
    if new_cuts is not None:
        g._cycle_thresholds[cid] = tuple(new_cuts)
    n = m = 0
    try:
        for u in people:
            figs, band = _points_snapshot(db, u, cid, kind)
            figs0, band0 = before[u["id"]]
            n += 1 if figs != figs0 else 0
            m += 1 if band != band0 else 0
    finally:
        g._points_ov = None
        if was_cuts is None:
            g.pop("_cycle_thresholds", None)
        else:
            g._cycle_thresholds = was_cuts
    return {"n": n, "m": m, "people": len(people)}


def _points_check(db, kind, new):
    """The "When it starts" step for `new` (the check writes nothing): the current cycle's option (open until its first potential
    result is released) with the people it re-scores and the raw potential band changes, the next-cycle option, and the cut-offs
    that move. (step, [errors])."""
    cyc = active_cycle(db)
    old = points_default(db, kind)
    cur_pinned = bool(cyc) and _points_pinned(db.execute("SELECT * FROM cycles WHERE id=?", (cyc["id"],)).fetchone(), kind)
    if new == old and not cur_pinned:
        return None, ["These are the points already in use: there is nothing to save."]
    rel = points_released_on(db, cyc["id"]) if cyc else None
    step = {"kind": kind, "new": new, "old": old, "cycle": cyc["name"] if cyc else None, "released_on": rel,
            "now_open": bool(cyc) and not rel, "next_open": new != old, "keeps": None, "keeps_cuts": None, "n": None, "m": None,
            "cuts": None, "no_cycle": not cyc}
    if cyc:
        step["keeps"] = points_for(db, cyc["id"], kind)
        if kind == "360":
            step["keeps_cuts"] = thresholds_for_cycle(db, cyc["id"])
    if step["now_open"]:
        plan = _points_plan(db, kind, new, "current")
        step["cuts"] = plan["cur_cuts"] if kind == "360" else None
        step["cut_default"] = plan["cut_default"]
        step.update({k: v for k, v in points_whatif(db, kind, cyc["id"], new, plan["cur_cuts"] if kind == "360" else None).items()
                     if k in ("n", "m")})
    if kind == "360":
        step["cut_default"] = step.get("cut_default") or _points_plan(db, kind, new, "next")["cut_default"]
    return step, []


def _points_apply(db, actor_id, kind, new, when):
    """THE writer of a points save, ONE transaction: validate the choice, PIN every PAST cycle that follows the default (not the
    current one; archived, released or older than it) at the old values (and, for the 360, with the default cut-offs where it holds none, so a later rescale never moves
    it), pin the current cycle for "next" / let it follow for "current", write the new default, rescale the 360's cut-offs (the
    default and every unpinned cycle's own) by new max / old max, audit. Then the caches drop and, for "current", the cycle's
    rating records are rebuilt. A leader's band move is never touched. Returns (ok, message)."""
    if when not in ("current", "next"):
        return False, "Pick when the points start: the current cycle, or from the next cycle on."
    cyc = active_cycle(db)
    old = points_default(db, kind)
    if when == "current":
        if not cyc:
            return False, "No cycle is open, so there is no current cycle to start in."
        rel = points_released_on(db, cyc["id"])
        if rel:
            return False, "%s's first results were released on %s, so its points are fixed. They can start from the next cycle on." % (
                cyc["name"], rel)
        if new == old and not _points_pinned(db.execute("SELECT * FROM cycles WHERE id=?", (cyc["id"],)).fetchone(), kind):
            return False, "These are the points already in use: there is nothing to save."
    elif new == old:
        return False, "These are already the default points: nothing starts from the next cycle."
    plan = _points_plan(db, kind, new, when)
    is360 = kind == "360"
    cols = _points_cols(kind)
    d_lo, d_mi = get_thresholds()
    try:
        for p_ in plan["pins"]:   # 2
            db.execute("UPDATE cycles SET %s WHERE id=?" % ", ".join("%s=?" % c for c in cols), list(old) + [p_["id"]])
            if is360 and p_["fill_cuts"]:
                db.execute("UPDATE cycles SET low_max=COALESCE(low_max, ?), mid_max=COALESCE(mid_max, ?) WHERE id=?",
                           (d_lo, d_mi, p_["id"]))
        if cyc and plan["pin_current"]:   # 3, "next": the current cycle keeps its present points and cut-offs
            db.execute("UPDATE cycles SET %s WHERE id=?" % ", ".join("%s=?" % c for c in cols), list(old) + [cyc["id"]])
            if is360:
                db.execute("UPDATE cycles SET low_max=COALESCE(low_max, ?), mid_max=COALESCE(mid_max, ?) WHERE id=?",
                           (d_lo, d_mi, cyc["id"]))
        elif cyc and when == "current":   # 3, "current": it follows the new default
            db.execute("UPDATE cycles SET %s WHERE id=?" % ", ".join("%s=NULL" % c for c in cols), (cyc["id"],))
        db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)",   # 4
                   (POINTS_KINDS[kind]["key"], json.dumps([float(x) for x in new])))
        if is360:   # 5
            for _k, _v in zip(("low_max", "mid_max"), plan["cut_default"]):   # set_thresholds' own two rows, but it commits: one transaction here
                db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?,?)", (_k, str(_v)))
            for c_ in plan["cut_cycles"]:
                db.execute("UPDATE cycles SET low_max=COALESCE(?, low_max), mid_max=COALESCE(?, mid_max) WHERE id=?",
                           (c_["lo"], c_["mi"], c_["id"]))
        label = POINTS_KINDS[kind]["label"]
        moved = []
        if is360:
            moved.append("default cut-offs Low ≤ %g, Mid ≤ %g (were %g / %g)" % (plan["cut_default"] + (d_lo, d_mi)))
            moved += ["%s Low ≤ %s, Mid ≤ %s" % (c_["name"], "%g" % c_["lo"] if c_["lo"] is not None else "-",
                                                  "%g" % c_["mi"] if c_["mi"] is not None else "-") for c_ in plan["cut_cycles"]]
        log_activity(db, actor_id, "settings",
                     "Points per answer, %s: Demonstrate %g / %g, Developing %g / %g (was %g / %g, %g / %g), %s%s%s" % (
                         label, new.dc, new.dn, new.vc, new.vn, old.dc, old.dn, old.vc, old.vn,
                         ("from %s, the current cycle" % cyc["name"]) if when == "current" else "from the next cycle on",
                         ("; pinned at the old points: " + ", ".join(p_["name"] for p_ in plan["pins"])) if plan["pins"] else "",
                         ("; " + "; ".join(moved)) if moved else ""), commit=False)
        db.commit()
    except Exception:
        db.rollback()
        raise
    points_cache_clear()
    n_rr = 0
    if when == "current":
        n_rr = _rating_records_follow_settings(db, actor_id, "settings_points")
    msg = ("Saved. %s is re-scored on %s now." % (cyc["name"], points_words(new)) if when == "current"
           else "Saved. The new points start from the next cycle%s: %s keeps %s." % (
               " on " + points_words(new), cyc["name"] if cyc else "the current cycle", points_words(old)))
    if is360 and plan["cut_default"]:
        msg += " The potential cut-offs move with them: default Low ≤ %g, Mid ≤ %g." % plan["cut_default"]
    if n_rr:
        msg += " %d ratings records brought up to date." % n_rr
    return True, msg


def _points_ref_tier(db, cyc):
    """The tier the 360 card's live numbers read: the one with the most people on a 360 panel in the current cycle (the lower
    tier on a tie), named as the Tiers card names it; JG 16's tier when nobody is on one. {name, n_cur, n_fut, cycle_id}."""
    tiers = effective_tiers(cyc) if cyc else default_tiers()
    cid = cyc["id"] if cyc else _points_ref_cycle(db)
    counts = Counter()
    if cyc:
        for jg, n in db.execute("SELECT u.job_grade, COUNT(DISTINCT a.subject_id) FROM assignments a JOIN users u ON u.id=a.subject_id "
                                "WHERE a.cycle_id=? AND a.archived=0 GROUP BY u.job_grade", (cyc["id"],)):
            counts[tier_for_grade(jg, tiers)["n"]] += n
    best = max(tiers, key=lambda t: (counts[t["n"]], -t["n"])) if counts else tier_for_grade(16, tiers)
    n_cur, n_fut = tier_statement_counts(db, cid, best["n"]) if cid else (0, 0)
    return {"name": "%s \u00b7 %s" % (best["name"], _tier_grades_label(best)), "n_cur": n_cur, "n_fut": n_fut, "cycle_id": cid}   # as the Tiers card's chip


def _points_card_ctx(db, kind, posted=None, errors=None, step=None):
    """What the Points per answer card draws for one kind: the default, the current cycle and what it scores on, the release lock,
    the reference counts the live numbers read, the posted values (after a refused check) and the open step."""
    cyc = active_cycle(db)
    default = points_default(db, kind)
    c_row = db.execute("SELECT * FROM cycles WHERE id=?", (cyc["id"],)).fetchone() if cyc else None
    today = points_for(db, cyc["id"], kind) if cyc else default
    own = bool(c_row is not None and _points_pinned(c_row, kind) and _points_own(c_row, kind) != default)
    if kind == "360":
        ref = _points_ref_tier(db, cyc)
        tot_cur, tot_fut = _points_all_counts(db, ref["cycle_id"])
        low, mid = get_thresholds()
        cu_lo, cu_mi = thresholds_for_cycle(db, cyc["id"]) if cyc else (low, mid)
        ref.update(tot_cur=tot_cur, tot_fut=tot_fut, low=low, mid=mid, cu_lo=cu_lo, cu_mi=cu_mi)
    else:
        ref = {"name": "", "n_cur": POINTS_TC_REF[0], "n_fut": POINTS_TC_REF[1], "tot_cur": 0, "tot_fut": 0,
               "high_pct": TC_BAND_HIGH_PCT, "mid_pct": TC_BAND_MID_PCT}
    show = {k: ((posted or {}).get(k) if posted else "%g" % getattr(default, k)) for k in _PTS_PARTS}   # strings: what the boxes hold
    return {"kind": kind, "label": POINTS_KINDS[kind]["label"], "default": default, "today": today, "own": own,
            "cycle": cyc["name"] if cyc else None, "released_on": points_released_on(db, cyc["id"]) if cyc else None,
            "ref": ref, "show": show, "errors": errors or [], "step": step,
            "today_max": float(points_max(today, ref["n_cur"], ref["n_fut"]))}


@app.route("/admin/settings", methods=["GET", "POST"])
@super_required
def admin_settings():
    db = get_db()
    if request.method == "POST":
        action = request.form.get("action", "thresholds")
        if action == "rules":
            # Panel size + Stage-1 threshold + tier grade-bands -> org DEFAULT.
            # Applies to the current (active) + future cycles; past (archived)
            # cycles are frozen at the previous default unless they already
            # have their own override.
            ps, mv, new_tiers, err = _parse_rules_form(request.form)
            cap, cap_err = _parse_cap_form(request.form)
            if err or cap_err:
                flash(err or cap_err, "error")
                return _settings_back("f360", "rules")
            # Freeze archived cycles at the OLD default, then set the new default.
            old_ps = default_panel_size()
            old_mv = default_min_valid()
            old_tiers = json.dumps(default_tiers())
            _ac0 = active_cycle(db)
            _t0 = effective_tiers(_ac0) if _ac0 else None
            old_cap = default_assessor_cap()
            db.execute("UPDATE cycles SET panel_size=? WHERE archived_at IS NOT NULL AND panel_size IS NULL",
                       (old_ps or 0,))     # 0 is No maximum on a frozen cycle
            db.execute("UPDATE cycles SET min_valid=? WHERE archived_at IS NOT NULL AND min_valid IS NULL", (old_mv,))
            db.execute("UPDATE cycles SET tiers_json=? WHERE archived_at IS NOT NULL AND tiers_json IS NULL", (old_tiers,))
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('panel_size', ?)",
                       (str(ps) if ps else "none",))
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('min_valid', ?)", (str(mv),))
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('tiers', ?)", (json.dumps(new_tiers),))
            if _ac0 and _t0 is not None:
                _ac1 = db.execute("SELECT * FROM cycles WHERE id=?", (_ac0["id"],)).fetchone()
                if effective_tiers(_ac1) != _t0:
                    _fb_retier_pending(db, cycle_id=_ac0["id"])   # the default moved the active cycle's tiers (2026-11-08)
            if cap is not None:      # 0 is No maximum: "none" here, 0 on a frozen cycle
                db.execute("UPDATE cycles SET assessor_cap=? WHERE archived_at IS NOT NULL AND assessor_cap IS NULL",
                           (old_cap or 0,))
                db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('assessor_cap', ?)",
                           (str(cap) if cap else "none",))
            db.commit()
            log_activity(db, current_user()["id"], "settings",
                         f"Default rules updated (panel {size_words(ps or None)}"
                         + (f" (was {size_words(old_ps)})" if (ps or None) != old_ps else "") + f", Stage-1 {mv}, "
                         + (f"rater cap {cap_words(cap or None)} (was {cap_words(old_cap)}), " if cap is not None
                            else "") + "tier bands)")
            warn = ""
            ac = active_cycle(db)
            if ac:
                n = db.execute("SELECT COUNT(*) FROM assignments WHERE cycle_id=? "
                               "AND status='submitted'", (ac["id"],)).fetchone()[0]
                if n:
                    warn = (f" Heads-up: the active cycle ({ac['name']}) already has {n} "
                            f"submitted assessment(s) — the new rules now apply to it too.")
            flash("Assessment rules updated — applied to the current and future cycles." + warn, "ok")
            return _settings_back("f360", "rules")

        if action == "extremes":
            enabled = request.form.get("extremes_enabled") == "1"
            try:
                bonus = float(request.form.get("extremes_bonus_points", "").strip())
                penalty = float(request.form.get("extremes_penalty_points", "").strip())
            except ValueError:
                flash("Bonus and penalty points must be numbers.", "error")
                return _settings_back("f360", "extremes-adjust")
            if bonus < 0 or penalty < 0:
                flash("Bonus and penalty points can't be negative.", "error")
                return _settings_back("f360", "extremes-adjust")
            set_extremes_adjustment_settings(enabled, bonus, penalty)
            log_activity(db, current_user()["id"], "settings",
                         f"Extreme-assessor correction {'enabled' if enabled else 'disabled'} "
                         f"(bonus {bonus:g}, penalty {penalty:g})")
            flash("Extreme-assessor correction settings updated.", "ok")
            return _settings_back("f360", "extremes-adjust")

        if action == "ai_module":
            # ONE surface's switch, from its module's Settings page (2026-10-10) -- the others keep their value.
            key = request.form.get("key", "")
            labels = {k: lbl for k, lbl, _d in AI_MODULES}
            if key not in labels:
                abort(400)
            vals = ai_module_settings()
            vals[key] = request.form.get("on") == "1"
            set_ai_module_settings(vals)
            log_activity(db, current_user()["id"], "settings",
                         "AI drafting for %s %s" % (labels[key], "on" if vals[key] else "off"))
            flash("AI drafting for %s is %s." % (labels[key], "on" if vals[key] else "off"), "ok")
            return _settings_back(_AI_MODULE_HOME.get(key, "org"), "ai")

        if action == "tb_limits":
            # The Talent Box limits (Chris, 2026-11-03): one card, one Save, the super admin's alone (this route is). Every
            # field is checked here whatever the form held; one bad figure refuses the lot, naming it. The remark is
            # required by _super_band_remark_gate (SUPER_BAND_ENDPOINTS) and rides on the audit line.
            vals, err = _tb_limits_parse(request.form)
            if err:
                flash(err, "error")
                return _settings_back("calibration", "tb-limits")
            was = get_tb_limits()
            changes = _tb_limits_changes(was, vals)
            if not changes:
                flash("The Talent Box limits are already set that way.", "ok")
                return _settings_back("calibration", "tb-limits")
            set_tb_limits(vals["moves_on"], vals["moves_pct"], vals["stars_on"], vals["stars"])
            log_activity(db, current_user()["id"], "settings", "Talent Box limits: " + "; ".join(changes))
            flash("Talent Box limits saved.", "ok")
            return _settings_back("calibration", "tb-limits")

        if action == "dept_filter":
            # THE DEPARTMENT FILTER (Chris, 2026-10-17): per business unit and view, off unless switched on. The card
            # posts one business group's units by index; a unit the form didn't show is left exactly as it is.
            bg = (request.form.get("bg") or "").strip()
            known = {r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                              "COALESCE(company,'')!=''", (bg,))} if bg else set()
            if not known:
                flash("Pick a business group that has business units.", "error")
                return _settings_back("calibration", "dept-filter")
            before = calib_dept_filter_map(db, bg)
            changes = []
            for k in request.form:
                if not k.startswith("unit_"):
                    continue
                idx = k[5:]
                co = (request.form.get(k) or "").strip()
                if co not in known:
                    continue
                for view, label in CALIB_DEPT_FILTER_VIEWS:
                    want = request.form.get("%s_%s" % (view, idx)) == "1"
                    if want == bool(before.get((co, view))):
                        continue
                    db.execute("INSERT INTO calib_dept_filter(business_group, company, view, shown, updated_by, "
                               "updated_at) VALUES (?,?,?,?,?, datetime('now')) ON CONFLICT(business_group, company, "
                               "view) DO UPDATE SET shown=excluded.shown, updated_by=excluded.updated_by, "
                               "updated_at=excluded.updated_at", (bg, co, view, 1 if want else 0, current_user()["id"]))
                    changes.append("%s in the %s: %s" % ("Shown" if want else "Hidden", label, co))
            # back on the same business group's tab (the card's `next` is its anchor on the page, with no group)
            back = redirect(url_for("admin_module_settings", key="calibration", dfbg=bg) + "#dept-filter")
            if not changes:
                flash("Nothing changed.", "ok")
                return back
            db.commit()
            log_activity(db, current_user()["id"], "settings", "Department filter, %s: %s" % (bg, "; ".join(changes)))
            flash("Department filter saved for %s. It shows from each leader's next page load." % display_bg(bg), "ok")
            return back

        if action == "jg_filter":
            # THE JOB GRADE FILTER (Chris, 2026-10-21): one business group's grouping (named bands, or each grade on its
            # own) and its units' switches, per view, off unless switched on. A unit the form didn't show is left as it
            # is; the grouping is the form's whole (the card always posts it). Nothing is written when a band is wrong.
            bg = (request.form.get("bg") or "").strip()
            known = {r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                              "COALESCE(company,'')!=''", (bg,))} if bg else set()
            back = redirect(url_for("admin_module_settings", key="calibration", jgbg=bg) + "#jg-filter")
            if not known:
                flash("Pick a business group that has business units.", "error")
                return _settings_back("calibration", "jg-filter")
            mode = (request.form.get("jg_mode") or "").strip()
            if mode not in ("bands", "each"):
                flash("Pick named bands or each grade on its own.", "error")
                return back
            bands = []
            if mode == "bands":
                for i in range(CALIB_JG_MAX_BANDS + 2):
                    lo_raw = (request.form.get("band_lo_%d" % i) or "").strip()
                    if not lo_raw:
                        continue
                    hi_raw = (request.form.get("band_hi_%d" % i) or "").strip()
                    name = re.sub(r"\s+", " ", (request.form.get("band_name_%d" % i) or "")).strip()
                    if not lo_raw.isdigit() or (hi_raw and not hi_raw.isdigit()):
                        flash("A band's From and To are job grades.", "error")
                        return back
                    lo, hi = int(lo_raw), (int(hi_raw) if hi_raw else None)
                    if not (1 <= lo <= CALIB_JG_GRADE_MAX) or (hi is not None and not (1 <= hi <= CALIB_JG_GRADE_MAX)):
                        flash("A band's grades run from JG 1 to JG %d." % CALIB_JG_GRADE_MAX, "error")
                        return back
                    if len(name) > CALIB_JG_NAME_MAX:
                        flash("A band's name is at most %d characters." % CALIB_JG_NAME_MAX, "error")
                        return back
                    bands.append({"name": name, "lo": lo, "hi": hi})
                err = calib_jg_bands_error(bands, _jg_floor(db))
                if err:
                    flash(err + " Nothing was saved.", "error")
                    return back
                bands.sort(key=lambda b: b["lo"])
            new_cfg = {"mode": mode, "bands": bands}
            every = request.form.get("jg_all_bgs") == "1"
            targets = sorted({r[0] for r in db.execute(
                "SELECT DISTINCT business_group FROM org_units WHERE active=1 AND COALESCE(business_group,'')!=''")}) \
                if every else [bg]
            changes = []
            words = lambda c: ("each grade on its own" if c["mode"] == "each"
                               else " · ".join(calib_jg_band_name(b) for b in sorted(c["bands"], key=lambda b: b["lo"])))
            for tb_ in targets:
                old = calib_jg_config(db, tb_)
                same = old["mode"] == mode and (mode == "each" or [
                    (b["name"], b["lo"], b["hi"]) for b in sorted(old["bands"], key=lambda b: b["lo"])] == [
                    (b["name"], b["lo"], b["hi"]) for b in bands])
                if same:
                    continue
                db.execute("INSERT INTO calib_jg_bands(business_group, mode, bands, updated_by, updated_at) VALUES "
                           "(?,?,?,?, datetime('now')) ON CONFLICT(business_group) DO UPDATE SET mode=excluded.mode, "
                           "bands=excluded.bands, updated_by=excluded.updated_by, updated_at=excluded.updated_at",
                           (tb_, mode, json.dumps(bands), current_user()["id"]))
                changes.append("%s grouped as %s" % (tb_, words(new_cfg)))
            before = calib_jg_filter_map(db, bg)
            for k in request.form:
                if not k.startswith("unit_"):
                    continue
                idx = k[5:]
                co = (request.form.get(k) or "").strip()
                if co not in known:
                    continue
                for view, label in CALIB_DEPT_FILTER_VIEWS:
                    want = request.form.get("%s_%s" % (view, idx)) == "1"
                    if want == bool(before.get((co, view))):
                        continue
                    db.execute("INSERT INTO calib_jg_filter(business_group, company, view, shown, updated_by, "
                               "updated_at) VALUES (?,?,?,?,?, datetime('now')) ON CONFLICT(business_group, company, "
                               "view) DO UPDATE SET shown=excluded.shown, updated_by=excluded.updated_by, "
                               "updated_at=excluded.updated_at", (bg, co, view, 1 if want else 0, current_user()["id"]))
                    changes.append("%s in the %s: %s" % ("Shown" if want else "Hidden", label, co))
            if not changes:
                flash("Nothing changed.", "ok")
                return back
            db.commit()
            log_activity(db, current_user()["id"], "settings", "Job grade filter, %s: %s" % (bg, "; ".join(changes)))
            flash("Job grade filter saved for %s. It shows from each leader's next page load." % (
                "every business group" if every else display_bg(bg)), "ok")
            return back

        if action == "calib_dev":
            # THE CALIBRATION CURVE RULE (2026-09-29): +-N people per band (default 1) or a % of headcount, and whether
            # a HOD / BU CEO may lock outside it with a reason.
            mode = (request.form.get("calib_tol_mode") or "people").strip()
            if mode not in ("people", "percent"):
                mode = "people"
            strict = "0" if (request.form.get("calib_lock_strict") or "1") == "0" else "1"
            try:
                people = int(request.form.get("calib_tol_people", "1").strip() or "1")
            except ValueError:
                flash("The number of people must be a whole number.", "error")
                return _settings_back("calibration", "calib-dev")
            if not (1 <= people <= 50):
                flash("The number of people must be between 1 and 50 -- each band's expected count is rounded, so "
                      "the curve can't always be met exactly.", "error")
                return _settings_back("calibration", "calib-dev")
            pct = get_calib_dev_pct()
            if mode == "percent":
                try:
                    pct = float(request.form.get("calib_dev_pct", "").strip())
                except ValueError:
                    flash("The calibration deviation must be a number.", "error")
                    return _settings_back("calibration", "calib-dev")
                if not (0 < pct <= 100):
                    flash("The calibration deviation must be between 0 and 100 percent.", "error")
                    return _settings_back("calibration", "calib-dev")
                set_calib_dev_pct(pct)
            for k, v in (("calib_tol_mode", mode), ("calib_tol_people", str(people)), ("calib_lock_strict", strict)):
                db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)", (k, v))
            db.commit()
            log_activity(db, current_user()["id"], "settings",
                         "Calibration curve rule: %s, %s" % (
                             ("+-%d people per band" % people) if mode == "people" else ("%g%% of headcount" % pct),
                             "strict (no lock outside it)" if strict == "1" else "lock with a reason allowed"))
            flash("Calibration curve rule updated.", "ok")
            return _settings_back("calibration", "calib-dev")

        if action == "ec_keys":
            # The Executive Chairman's key-people rule (2026-10-30): the super admin's alone (this route is), only while his view
            # is on, validated here whatever the form held. Stores a rule, never anything about a person.
            if not chair_on():
                abort(404)
            vals, err = _ec_key_parse(request.form)
            if err:
                flash(err, "error")
                return _settings_back("calibration", "ec-keys")
            rule = _ec_key_save(db, vals, current_user()["id"])
            flash("Key people rule saved. " + ec_key_words(rule), "ok")
            return _settings_back("calibration", "ec-keys")

        if action == "calib_assist":
            # The AI+ calibration assistant (the talk-to-calibrate chat for HOD/BUCEO).
            # A single org-wide on/off switch (calibration is org-wide by tier, so no
            # per-BG pilot); it only actually appears when a model is also reachable.
            on = request.form.get("calib_assist_on") == "1"
            db.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('ai_calib', ?)",   # the one AI store
                       ("1" if on else "0",))
            db.commit()
            log_activity(db, current_user()["id"], "settings",
                         "AI+ calibration assistant " + ("enabled" if on else "disabled"))
            flash("AI+ calibration assistant " + ("enabled." if on else "disabled."), "ok")
            return _settings_back("calibration", "calib-assist")

        if action == "band_visibility":
            show = request.form.get("show_band") == "1"
            set_show_potential_band(show)
            log_activity(db, current_user()["id"], "settings",
                         "Potential band display: " + ("shown to" if show else "hidden from")
                         + " employees and managers (My Feedback, report view, Team, HOD)")
            flash("Potential band is now "
                  + ("visible to employees and managers." if show
                     else "hidden from employees and managers — admin views still show it."),
                  "ok")
            return _admin_next(url_for("admin_talent_release") + "#band-visibility")   # its home since 2026-10-11

        if action == "review_all":
            # The AI+ review for everyone (2026-10-08) -- the org switch; off = the classic pages (the per-BG pilot list
            # is retired, 2026-10-11)
            on = request.form.get("review_all") == "1"
            db.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('review_unified', ?)",
                       ("1" if on else "0",))
            db.commit()
            log_activity(db, current_user()["id"], "settings",
                         "AI+ review " + ("on for everyone" if on else "off for everyone"))
            flash("The AI+ review is " + ("on for everyone." if on else "off: everyone uses the classic pages."), "ok")
            return _settings_back("org", "review-pilot")

        if action in ("points_360", "points_tc", "points_360_check", "points_tc_check"):
            # POINTS PER ANSWER (Chris, 9 Nov 2026), the 360's and the competency's, each its own. `_check` writes nothing: it
            # re-draws the card with the step "When it starts" open (the people re-scored, the raw potential band changes, the
            # cut-offs that move) and is NOT a band action; the save (points_360 / points_tc) is one, so the super admin's
            # reason rides in `remark` (SUPER_BAND_ENDPOINTS), asked once, in the step.
            kind = "360" if action.startswith("points_360") else "tc"
            page = POINTS_KINDS[kind]["module"]
            new, errs = points_parse(request.form)
            posted = {k: (request.form.get(k) or "").strip() for k in _PTS_PARTS}
            if action.endswith("_check"):
                step = None
                if not errs:
                    step, errs = _points_check(db, kind, new)
                return _module_settings_page(page, points_post={"kind": kind, "posted": posted, "errors": errs, "step": step})
            if errs:
                flash(errs[0], "error")
                return _settings_back(page, "points")
            ok, msg = _points_apply(db, current_user()["id"], kind, new, (request.form.get("when") or "").strip())
            flash(msg, "ok" if ok else "error")
            return _settings_back(page, "points")

        if action == "band_weights":
            # One 360/technical split per job grade. Validated as a whole
            # before anything is written -- a half-applied weighting would
            # leave some grades banding on a rule nobody chose.
            parsed = []
            for jg in sorted(tc_band_weights(db).keys(), key=_jg_sort_key):
                raw = (request.form.get(f"w360_{jg}", "") or "").strip()
                if raw == "":
                    continue
                try:
                    w360 = float(raw)
                except ValueError:
                    flash(f"JG {jg}: the 360 weighting must be a number.", "error")
                    return _settings_back("competency", "band-weights")
                if not (0 <= w360 <= 100):
                    flash(f"JG {jg}: the 360 weighting must be between 0 and 100.", "error")
                    return _settings_back("competency", "band-weights")
                parsed.append((jg, w360))
            for jg, w360 in parsed:
                db.execute("UPDATE tc_band_weights SET w_360=?, w_tech=?, "
                           "updated_at=datetime('now'), updated_by=? WHERE job_grade=?",
                           (w360, 100.0 - w360, current_user()["id"], jg))
            db.commit()
            log_activity(db, current_user()["id"], "settings",
                         "Potential band weighting updated: "
                         + ", ".join(f"JG {jg} {w:g}:{100 - w:g}" for jg, w in parsed))
            n_rr = _rating_records_follow_settings(db, current_user()["id"], "settings_weighting")
            flash("Band weighting updated." + (f" {n_rr} ratings records brought up to date." if n_rr else ""), "ok")
            return _settings_back("competency", "band-weights")

        if action == "cycle_cutoffs":
            # THIS cycle's own Low / Mid cutoffs (Chris, 2026-10-11: "super admin also can set the threshold and cutoff
            # for the potential band"). A cycle carries its own from the one it was created from, so the default below
            # never reached the running cycle and nothing on screen could change it. Points on the 360's scale.
            cyc = active_cycle(db)
            if not cyc:
                flash("No cycle is active, so there are no cutoffs of its own to set.", "error")
                return _settings_back("competency", "thresholds")
            try:
                lo = float((request.form.get("low_max") or "").strip())
                mi = float((request.form.get("mid_max") or "").strip())
            except ValueError:
                flash("The cutoffs must be numbers.", "error")
                return _settings_back("competency", "thresholds")
            mx = max_score_for_grade(db, 16, cyc["id"])
            if not (0 <= lo < mi <= mx):
                flash(f"The cutoffs must satisfy 0 ≤ Low < Mid ≤ {mx:g} (the score's maximum).", "error")
                return _settings_back("competency", "thresholds")
            was = thresholds_for_cycle(db, cyc["id"])
            db.execute("UPDATE cycles SET low_max=?, mid_max=? WHERE id=?", (lo, mi, cyc["id"]))
            db.commit()
            if has_request_context() and getattr(g, "_cycle_thresholds", None):
                g._cycle_thresholds.pop(cyc["id"], None)
            log_activity(db, current_user()["id"], "settings",
                         f"Potential cutoffs for {cyc['name']}: Low ≤ {lo:g}, Mid ≤ {mi:g} of {mx:g} "
                         f"(was {was[0]:g} / {was[1]:g})")
            n_rr = _rating_records_follow_settings(db, current_user()["id"], "settings_cutoffs")
            flash(f"{cyc['name']} now bands potential at Low ≤ {lo:g}, Mid ≤ {mi:g}, High above."
                  + (f" {n_rr} ratings records brought up to date." if n_rr else ""), "ok")
            return _settings_back("competency", "thresholds")

        # action == 'thresholds' (default). Any other action is refused here rather than read as a thresholds save (a
        # retired one, like the AI+ pilot list's review_pilot, used to fall through to it).
        if action != "thresholds":
            abort(400)
        try:
            low_max = float(request.form.get("low_max", "").strip())
            mid_max = float(request.form.get("mid_max", "").strip())
        except ValueError:
            flash("Thresholds must be numbers.", "error")
            return _settings_back("competency", "thresholds")
        mx = max_score_for_grade(get_db(), 16, active_cycle_id(get_db()))
        # The default only reaches a cycle without cutoffs of its own. When the active cycle has its own (staging's
        # Year-End: 6.0 / 12.5 out of 17.5), its maximum says nothing about the default, which used to refuse even the
        # unchanged 14 / 26 (2026-10-10).
        own = _cycle_own_cutoffs(db)
        if not (0 <= low_max < mid_max) or (not own and mid_max > mx):
            flash(("Thresholds must satisfy 0 ≤ Low < Mid." if own else
                   f"Thresholds must satisfy 0 ≤ Low < Mid ≤ {mx:g} (the maximum possible average score)."), "error")
            return _settings_back("competency", "thresholds")
        # Freeze already-ARCHIVED cycles that have no per-cycle override at the
        # OLD global, so editing the global default never silently re-bands a
        # closed cycle. (The active cycle is pinned explicitly when a rescaled
        # framework is activated; see effective_thresholds/thresholds_for_cycle.)
        old_lo, old_mi = get_thresholds()
        db.execute("UPDATE cycles SET low_max=? WHERE archived_at IS NOT NULL AND low_max IS NULL",
                   (old_lo,))
        db.execute("UPDATE cycles SET mid_max=? WHERE archived_at IS NOT NULL AND mid_max IS NULL",
                   (old_mi,))
        db.commit()
        set_thresholds(low_max, mid_max)
        log_activity(db, current_user()["id"], "settings",
                     f"Potential thresholds: Low<{low_max:g}, Mid<{mid_max:g}")
        n_rr = 0 if own else _rating_records_follow_settings(db, current_user()["id"], "settings_cutoffs")
        flash("Potential thresholds updated." + (f" {n_rr} ratings records brought up to date." if n_rr else ""), "ok")
        return _settings_back("competency", "thresholds")
    # The General page is gone (2026-10-10): each of its rules now sits on its module's Settings page, and the
    # sheet of every setting is where this address leads (the super admin's; anyone else goes Home, 2026-10-21).
    return redirect(url_for("admin_all_settings") if is_super(current_user()) else url_for("admin_overview"))

# ---------------------------------------------------------------------------
# Admin: each module's settings, the sheet of every setting, the search, the reports (2026-10-10, the admin revamp)
# ---------------------------------------------------------------------------
def calib_filter_has_values(key, cov_unit, n_groups):
    """Whether a unit has anything for filter `key` to filter by: a department / cost centre / work location on someone's
    record, a job grade, a calibration group. A unit with none cannot switch it on."""
    c = cov_unit or {}
    if any(f["key"] == key for f in calib_roster_filters()):
        return (c.get(key) or (0, 0))[0] > 0
    if key == "jg":
        return c.get("jg", 0) > 0
    if key == "cal":
        return n_groups > 0
    return False


@app.route("/admin/settings/calib-filter", methods=["POST"])
@super_required
def admin_calib_filter():
    """ONE FILTER'S RULE (Chris, 2026-10-30, canvas "OneHR Calibration Filter Rules", Option 2): the side panel of
    Calibration & Talent > Settings > Filters at BU level posts one filter (a CALIB_FILTERS key) for one business group:
    which of its units show it (a `unit_<i>` name with `on_<i>` ticked) and on which screens (`screen` = bu / tb). The
    ticked units get the filter on for every ticked screen and off for the others, an unticked unit off on both: units x
    screens, written to the filter's own table. Only the units of that group and only registry keys and screens are
    accepted -- anything else refuses the whole save, and nothing is written. A unit with no values for the column cannot
    be switched on (a unit already on may still be switched off). The audit says who, what, and what it was before."""
    db = get_db()
    me = current_user()
    bg = (request.form.get("bg") or "").strip()
    key = (request.form.get("filter") or "").strip()
    back = redirect(url_for("admin_module_settings", key="calibration", bfbg=bg) + "#bu-filters")
    f = calib_filter_def(key)
    known = {r[0] for r in db.execute("SELECT company FROM org_units WHERE business_group=? AND active=1 AND "
                                      "COALESCE(company,'')!=''", (bg,))} if bg else set()
    if not known:
        flash("Pick a business group that has business units.", "error")
        return _settings_back("calibration", "bu-filters")
    if not f:
        flash("That filter is not one of the calibration filters.", "error")
        return back
    posted = []   # [(unit, ticked)] in the form's order
    for k in request.form:
        if not k.startswith("unit_"):
            continue
        co = (request.form.get(k) or "").strip()
        if co not in known:
            flash("%s is not a business unit of %s: nothing was saved." % (co or "That unit", display_bg(bg)), "error")
            return back
        posted.append((co, request.form.get("on_" + k[5:]) == "1"))
    screens = [x.strip() for x in request.form.getlist("screen")]
    if any(x not in f["views"] for x in screens):
        flash("That screen does not take the %s filter: nothing was saved." % f["label"], "error")
        return back
    ticked = [co for co, on in posted if on]
    if ticked and not screens:
        flash("Pick at least one screen for the %s filter." % f["label"], "error")
        return back
    cov = calib_filter_coverage(db, bg)
    saved = calib_filter_map(db, bg, key)
    labels = {v: short for v, short, _l in CALIB_FILTER_SCREENS}   # "BU CEO view", "Talent Box"
    plan = []
    for co, on in posted:
        for view in f["views"]:
            want = on and view in screens
            was = calib_filter_on(db, bg, key, co, view, saved)
            if want == was:
                continue
            if want and not calib_filter_has_values(key, cov.get(co), len(bu_groups_of_unit(db, bg, co))):
                flash("%s has no values for %s, so it cannot show that filter: nothing was saved."
                      % (COMPANY_SHORT.get(co) or co, f["label"]), "error")
                return back
            plan.append((co, view, want, was))
    if not plan:
        flash("Nothing changed.", "ok")
        return back
    for co, view, want, was in plan:
        calib_filter_write(db, bg, co, view, key, want, me["id"])
    db.commit()
    log_activity(db, me["id"], "settings", "Filters at BU level, %s: %s" % (bg, "; ".join(
        "%s %s in the %s: %s (was %s)" % (f["code"], "shown" if want else "hidden", labels.get(view, view), co,
                                        "shown" if was else "hidden") for co, view, want, was in plan)))
    flash("%s filter saved for %s. It shows from each leader's next page load." % (f["label"], display_bg(bg)), "ok")
    return back


@app.route("/admin/settings/calib-viewer-filter", methods=["POST"])
@super_required
def admin_calib_viewer_filter():
    """FILTERS PER VIEWER (Chris, 2026-11-02, canvas "OneHR Calibration Filters by Viewer"): the Filters card's Calibrators, Group
    Chiefs and Executive Chairman tabs post ONE viewer's set. Fields: `kind` (cal | gc | ec), `viewer_id` (the calibrator's
    calib_bu_groups id, the Group Chief group's id, '' for the Chairman), `filter` repeated for every filter ticked, `action`
    save | follow. Save writes every key the kind offers (shown 0 or 1). Follow (calibrators only) deletes the rows, so the
    calibrator keeps what its units show again. Anything not offered refuses the whole post and nothing is written: an unknown
    kind, a calibrator or group that is not there, an unknown key, Segment (always on, never a key), a key the kind does not
    offer, a filter nobody the viewer holds has a value for (unless it is already on), Follow for any kind but a calibrator.
    The audit says which viewer, what it was and what it is."""
    db = get_db()
    me = current_user()
    kind = (request.form.get("kind") or "").strip()
    vid = (request.form.get("viewer_id") or "").strip()
    action = (request.form.get("action") or "save").strip()
    spec = CALIB_VIEWER_KINDS.get(kind)

    def back(bg=""):
        return redirect(url_for("admin_module_settings", key="calibration", fview=kind if spec else "unit",
                                **({"bfbg": bg} if bg else {})) + "#bu-filters")

    def refuse(msg, bg=""):
        flash(msg, "error")
        return back(bg)
    if not spec:
        return refuse("That is not a kind of viewer: nothing was saved.")
    if action not in ("save", "follow"):
        return refuse("Save the filters, or have the calibrator follow its units again: nothing was saved.")
    if action == "follow" and kind != "cal":
        return refuse("Only a calibrator can follow its units again: nothing was saved.")
    bg, name, people, cfg = "", spec["label"], [], None
    if kind == "ec":
        if vid:
            return refuse("The Executive Chairman has no id: nothing was saved.")
        if not chair_on():
            abort(404)
        people = db.execute("SELECT %s FROM users u WHERE u.role!='admin' AND u.left_at IS NULL AND u.is_demo=0 AND "
                            "COALESCE(u.business_group,'')!='' AND %s" % (VF_COLS, calibration_population_sql("u"))).fetchall()
    elif kind == "cal":
        g = bu_group(db, vid) if vid.isdigit() else None
        if not g:
            return refuse("That calibrator is not here any more: nothing was saved.")
        bg, name = g["business_group"], g["name"]
        people = _vf_people(db, "u.business_group=? AND " + bu_group_member_sql("u"), [bg, g["id"]])
    else:
        g = db.execute("SELECT id, name FROM pm_calibration_groups WHERE id=?", (vid,)).fetchone() if vid.isdigit() else None
        if not g:
            return refuse("That Group Chief group is not here any more: nothing was saved.")
        name = g["name"]
        people = _vf_people(db, "u.id IN (SELECT subject_id FROM pm_calibration_group_members WHERE group_id=?)", [g["id"]])
    vid = str(int(vid)) if kind != "ec" else ""
    old_rows = calib_viewer_filters(db, kind, vid)
    if kind == "cal":
        union = [f["key"] for f in CALIB_FILTERS if f["key"] in spec["keys"]
                 and calib_filter_shown(db, bg, g["units"], "bu", f["key"])]
        old_shown = calib_viewer_shown_keys(old_rows, kind) if old_rows is not None else union
    else:
        old_shown = calib_viewer_shown_keys(old_rows, kind)
    words = lambda ks: " · ".join(calib_viewer_def(k)["label"] for k in ks) or "None"   # noqa: E731
    label = (spec["label"] if kind == "ec" else "%s %s" % (spec["label"], name)) + (" (id %s)" % vid if vid else "")
    if action == "follow":
        if old_rows is None:
            flash("Nothing changed: it already follows its units.", "ok")
            return back(bg)
        db.execute("DELETE FROM calib_viewer_filter WHERE kind=? AND viewer_id=?", (kind, vid))
        db.commit()
        log_activity(db, me["id"], "settings", "Filters per viewer, %s: %s (set here) -> %s (from its units)" % (
            label, words(old_shown), words(union)))
        flash("%s follows its units again." % name, "ok")
        return back(bg)
    posted = [x.strip() for x in request.form.getlist("filter")]
    for k in posted:
        if k in ("seg", "segment"):
            return refuse("Segment is always on: it is not a filter to switch. Nothing was saved.", bg)
        if k not in spec["keys"] or not calib_viewer_def(k):
            return refuse("%s does not take that filter: nothing was saved." % spec["label"], bg)
    want = [k for k in calib_viewer_shown_keys({k: True for k in posted}, kind)]
    for k in want:   # a filter nobody the viewer holds has a value for cannot be switched on (one already on may go off)
        if k not in old_shown and not _vf_has_values(k, people):
            return refuse("No one in %s has values for %s, so it cannot show that filter: nothing was saved." % (
                name, calib_viewer_def(k)["label"]), bg)
    if want == old_shown and (old_rows is not None or kind != "cal"):
        flash("Nothing changed.", "ok")
        return back(bg)
    for k in spec["keys"]:
        db.execute("INSERT INTO calib_viewer_filter(kind, viewer_id, filter_key, shown, set_by, set_at) VALUES (?,?,?,?,?, "
                   "datetime('now')) ON CONFLICT(kind, viewer_id, filter_key) DO UPDATE SET shown=excluded.shown, "
                   "set_by=excluded.set_by, set_at=excluded.set_at", (kind, vid, k, 1 if k in want else 0, me["id"]))
    db.commit()
    log_activity(db, me["id"], "settings", "Filters per viewer, %s: %s%s -> %s (set here)" % (
        label, words(old_shown), "" if kind != "cal" else " (set here)" if old_rows is not None else " (from its units)",
        words(want)))
    flash("Filters saved for %s. They show from each leader's next page load." % name, "ok")
    return back(bg)


@app.route("/admin/m/<key>/settings")
@admin_required
def admin_module_settings(key):
    """One module's every setting on one page (the canvas's A2): a card per setting with how it reads now and when it
    last changed -- its own form where it is small enough, else a way to the page that edits it. A BG admin reads what
    only a super admin may change."""
    return _module_settings_page(key)


def _module_settings_page(key, points_post=None):
    """The page admin_module_settings draws; `points_post` (a Points per answer check, or a refused one) re-draws it with that
    card's step open and its posted values back in the boxes."""
    if key not in ADMIN_SETTINGS or key == "cycle":
        abort(404)
    db = get_db()
    me = current_user()
    if key == "org" and not is_super(me):   # Platform, under All settings: the super admin's alone (2026-10-21)
        flash("All settings, Platform included, is the super admin's.", "error")
        return redirect(url_for("admin_overview"))
    ctx = _general_settings_ctx(db)
    rule, min_goals, max_goals, ai_on = get_idp_settings()
    ctx.update(rule=rule, min_goals=min_goals, max_goals=max_goals, ai_on=ai_on, rules=IDP_ACTION_RULES,
               modes=PM_IDP_MODES, ai_labels={k: (lbl, d) for k, lbl, d in AI_MODULES})
    for _pk in ("360", "tc"):   # the Points per answer card of this module (Piece 1: 360 Feedback, Competency)
        if POINTS_KINDS[_pk]["module"] == key:
            _pp = points_post if (points_post and points_post["kind"] == _pk) else {}
            ctx["points"] = _points_card_ctx(db, _pk, posted=_pp.get("posted"), errors=_pp.get("errors"), step=_pp.get("step"))
    if key == "calibration":
        q, qin, menu = people_search_args()   # the Calibrators and Group Chiefs tabs' Search in
        _ek = ec_key_rule(db)
        ctx.update(ec_key=_ek, ec_key_words=ec_key_words(_ek),
                   dept_filter=_dept_filter_ctx(db, (request.args.get("dfbg") or "").strip()),
                   jg_filter=_jg_filter_ctx(db, (request.args.get("jgbg") or "").strip()),
                   bu_filters=_bu_filters_ctx(db, (request.args.get("bfbg") or "").strip()),
                   viewer_filters=_viewer_filters_ctx(db, (request.args.get("fview") or "").strip(),
                                                      (request.args.get("bfbg") or "").strip(), q, qin),
                   search_in=menu, qin=qin, q=q)
    return render_template("admin_module_settings.html", mod_key=key, mod_label=ADMIN_SETTINGS[key]["label"],
                           sections=[x for x in _settings_view(db, me, key) if not x.get("run")],
                           settings_next=url_for("admin_module_settings", key=key), **ctx)


def _all_setting_rows(db, me, with_last=True):
    """Every setting as one flat list, in sidebar order: module, label, how it reads now, its scope, its last change,
    and where it lives. The sheet, the search and the agent all read this."""
    log_rows = _setting_last_map(db) if with_last else []
    out = []
    for key in ADMIN_SETTINGS_ORDER:
        for sec in _settings_view(db, me, key, log_rows):
            if key == "cycle" or (sec.get("run") and sec["open"]):   # a Run page's line opens that page
                href = sec["open"]["href"] if sec["open"] else None
            else:
                href = url_for("admin_module_settings", key=key) + "#" + sec["id"]
            for r in sec["rows"]:
                out.append({"module": key, "module_label": ADMIN_SETTINGS[key]["label"], "key": r["key"],
                            "label": r["label"], "value": r["value"], "scope": sec["scope"],
                            "scope_label": sec["scope_label"], "scope_filter": SETTING_SCOPE_FILTER[sec["scope"]],
                            "last": r["last"], "href": href, "section": sec["title"], "run": bool(sec.get("run")),
                            "can_edit": sec["can_edit"]})
    return out


@app.route("/admin/all-settings")
@super_required   # the super admin's alone (Chris, 2026-10-21: "hide the All settings from bg and bu admin")
def admin_all_settings():
    """Every setting on one sheet (the canvas's C2): filter by module and scope, search by name or value, open one to
    change it where it lives."""
    db = get_db()
    me = current_user()
    rows = _all_setting_rows(db, me)
    return render_template("admin_all_settings.html", rows=rows,
                           modules=[(k, ADMIN_SETTINGS[k]["label"]) for k in ADMIN_SETTINGS_ORDER],
                           scopes=[("global", "Global"), ("bg", "Per business group"), ("cycle", "Per cycle")])


