def _fb_groups(db):
    """Every Group Chief scope with its calibrator's name, by name."""
    return db.execute("SELECT g.*, u.full_name AS chief_name FROM pm_calibration_groups g JOIN users u "
                      "ON u.id=g.calibrator_id ORDER BY g.name").fetchall()


def _final_bands_people(db):
    """The people on the Final bands file: the members of every Group Chief scope on either axis (_fb_members, the read the queue's
    own rows start from), one entry each, inside the panel's picks. Cheap: no band is worked out here."""
    period = active_pm_period(db)
    if not period:
        return []
    seen, out = set(), []
    for g_ in _fb_groups(db):
        for axis in ("pm", "pot"):
            for p in _fb_members(db, g_["id"], period["id"], axis):
                if p["id"] not in seen and dl_keep(p):
                    seen.add(p["id"])
                    out.append(p)
    return out


FINAL_BANDS_AXIS = ["BG CEO", "Group Chief", "Group Chief locked (MYT)", "Suggested", "Final band", "Remark", "Decided by",
                    "Decided at (MYT)"]
FINAL_BANDS_HEAD = (["Group Chief scope", "Group Chief", "Employee ID", "Name", "Business group", "Business unit", "Department"]
                    + ["Performance: " + h for h in FINAL_BANDS_AXIS] + ["Potential: " + h for h in FINAL_BANDS_AXIS])


def _final_bands_axis_cells(r):
    """One axis's cells of the Final bands file for a queue row (_final_bands_rows / _final_bands_rows_pot); blanks where the
    person isn't on that axis."""
    if not r:
        return [""] * len(FINAL_BANDS_AXIS)
    f = r["final"] or {}
    return [r["bg"] or "", r["chief"] or "", _myt(r["chief_at"]) or "", r["sug"] or r["tie"] or "", f.get("adjusted_band", ""),
            f.get("justification") or "", f.get("by_name") or "", _myt(f.get("adjusted_at")) or ""]


def _final_bands_all_rows(db):
    """The Final bands file's rows: every Group Chief scope of the active cycle, one row a person, performance and potential side
    by side (the two queues' own rows, so a figure here is the figure on the Final bands page), inside the panel's picks."""
    period = active_pm_period(db)
    if not period:
        return []
    out = []
    for g_ in _fb_groups(db):
        pm_rows, _m = _final_bands_rows(db, period, g_["id"])
        pot_rows, _m2 = _final_bands_rows_pot(db, period["id"], g_["id"])
        by = {}
        for r in pm_rows:
            by.setdefault(r["p"]["id"], {"p": r["p"], "pm": None, "pot": None})["pm"] = r
        for r in pot_rows:
            by.setdefault(r["p"]["id"], {"p": r["p"], "pm": None, "pot": None})["pot"] = r
        for e in sorted(by.values(), key=lambda e: (e["p"]["business_group"] or "", e["p"]["company"] or "",
                                                    e["p"]["department"] or "", e["p"]["full_name"] or "")):
            p = e["p"]
            if dl_keep(p):
                out.append([g_["name"], g_["chief_name"], p["employee_id"], p["full_name"], display_bg(p["business_group"]) or "",
                            p["company"] or "", p["department"] or ""] + _final_bands_axis_cells(e["pm"])
                           + _final_bands_axis_cells(e["pot"]))
    return out


