# ---- THE THREE LIBRARIES' DOWNLOADS (Chris, 10 Nov 2026): the KPI library, the competency library and the career routes,
# each an Excel file on Reports > Data downloads, the super admin's alone (the libraries are theirs: super_required). None is a
# cycle's or a business group's: they download straight, with no panel. Each is read through the function its page reads.
DL_LIBRARY_EPS = frozenset({"admin_export_kpi_library", "admin_export_competency_library", "admin_export_career_routes"})
KPI_LIBRARY_EXPORT_EXTRA = ("Active", "Variant of", "Last changed (MYT)", "Job grades (a list)", "Departments (a list)",
                            "Departments list means", "Names people", "Same import key as another row")


def _kpi_library_export(db):
    """(header, active rows, retired rows, counts) of the KPI library, every row, sorted business group then KPI; the retired
    ones (Active = No) apart, for a sheet of their own, so the first sheet imports back as it is. The first
    twelve columns are the library import's own (KPI_LIBRARY_IMPORT_HEAD), written as it reads them back: blank for "any"
    ('*' and tier 0), the method as More / Less, BU level as Yes / No. After them, columns the import ignores: whether the
    row is active, the KPI it is a variant of (pm_kpi_aliases), when it last changed, and the scope the import cannot say
    (a list of grades or departments, a row that names people). The library holds no numbers, so none is read here."""
    try:
        named = {r[0]: r[1] for r in db.execute("SELECT library_id, COUNT(*) FROM pm_kpi_library_people GROUP BY library_id")}
    except sqlite3.OperationalError:   # a database from before the table
        named = {}
    variants = {(r["business_group"], r["alias_key"]): r["into_name"] for r in db.execute(
        "SELECT business_group, alias_key, into_name FROM pm_kpi_aliases WHERE kind='variant'")}
    lib = [dict(r) for r in db.execute(
        "SELECT * FROM pm_kpi_library ORDER BY business_group COLLATE NOCASE, kpi_name COLLATE NOCASE, id")]
    # a key shared by two rows matters to the import only among the rows of the first sheet, the active ones
    keys = Counter((r["business_group"], r["company"], r["department"], r["tier_n"], r["job_grade"], r["kpi_name"])
                   for r in lib if r["active"])

    def any_(v):
        return "" if v in (None, "", "*") else v
    rows, retired = [], []
    for r in lib:
        key = (r["business_group"], r["company"], r["department"], r["tier_n"], r["job_grade"], r["kpi_name"])
        (rows if r["active"] else retired).append([
            r["business_group"], any_(r["company"]), any_(r["department"]), r["tier_n"] or "", str(any_(r["job_grade"])),
            r["kpi_name"], r["category"] or "", r["description"] or "", r["unit"] or "",
            "Less" if r["method"] == "less" else "More", r["perspective"] or "", "Yes" if r["bu_level"] else "No",
            "Yes" if r["active"] else "No", variants.get((r["business_group"], _kpi_key(r["kpi_name"])), ""),
            _myt(r["updated_at"] or r["created_at"]) or "",
            ", ".join(p for p in (r["job_grades"] or "").split(",") if p.strip()),
            ", ".join(p for p in (r["departments"] or "").split(",") if p.strip()),
            ("" if not (r["departments"] or "").strip() else
             "all except these" if r["department_mode"] == "exclude" else "only these"),
            named.get(r["id"], 0) or "", "Yes" if r["active"] and keys[key] > 1 else ""])
    counts = {"active": len(rows), "retired": len(retired), "shared": sum(1 for v in keys.values() if v > 1 for _ in range(v))}
    return list(KPI_LIBRARY_IMPORT_HEAD) + list(KPI_LIBRARY_EXPORT_EXTRA), rows, retired, counts


@app.route("/admin/export/kpi-library.xlsx")
@super_required
def admin_export_kpi_library():
    """Performance: the whole KPI library in one file (Reports, 10 Nov 2026): the library import's columns first, so an edited
    file goes back in on Performance > Run > Import the KPI library; then read-only columns the import ignores."""
    db, me = get_db(), current_user()
    head, rows, retired, n = _kpi_library_export(db)
    return _dl_book_many(
        db, me, "KPI library", [("KPI library", head, rows), ("Retired", head, retired)],
        "Every active KPI in the library on the first sheet, one row a scope, sorted by business group and KPI; the retired ones "
        "(Active = No) on the Retired sheet. The first twelve columns are the library "
        "import's columns, in its order: change a definition, unit, method, perspective or BU level and import the file back. "
        "The columns after them are for reading and the import ignores them. The library holds no numbers, so the file has none.",
        [("Active rows", n["active"]), ("Retired rows", n["retired"]),
         ("The Retired sheet",
          "It is for reading: the import reads only the first sheet, so the retired KPIs stay retired."),
         ("Scope the import cannot say",
          "A list of job grades or departments, and a row that names people, are in the read-only columns. The import "
          "matches a row on its single Department and Job Grade and leaves those lists as they are."),
         ("Rows sharing an import key",
          "%d. Two rows that differ only in such a list have the same Business Group, Company, Department, Tier, Job Grade "
          "and KPI, so the import reads them as one KPI twice and refuses the file until one is removed." % n["shared"])],
        scope=[["Business groups", "Every business group in the library"]])


def _competency_library_export(db):
    """([Jobs sheet header, rows], [Competencies sheet header, rows]) of the competency library, read through _tc_lib_index
    (the library page's and the catalogue's own index: each job's five, their level now and next, who wrote them, the jobs
    each competency serves), so nothing about now and next is worked out again here."""
    ix = _tc_lib_index(db)
    profs, skills = ix["profiles"], ix["skills"]
    tax = {r["code"]: r["name"] for r in db.execute("SELECT code, name FROM ja_taxonomy")}
    by_level = {}   # (competency, level) -> the written level row, an active one first
    for k, it in skills.items():
        for r in sorted(it["rows"], key=lambda r: (not r["active"], r["id"])):
            by_level.setdefault((k, r["level"]), r)
    jobs_head = ["Job code", "Job family", "Sub-family", "Specialisation", "Job title", "Job grade", "Department", "Job scope",
                 "Business groups (people holding it)", "People holding it", "Target role nobody holds",
                 "Competency code", "Competency", "Level", "Current or Next level", "Written by", "Review status"]
    jobs = []
    for p in sorted(profs.values(), key=lambda p: ((p["code"] or "").upper(), (p["scope"] or "").upper(), p["id"])):
        fam = (_ja_parts(p["code"]) or {}).get("family") or ""
        ident = [p["code"], tax.get(fam) or fam, p["sub_name"] or "", p["spec_name"] or "", p["title"] or "", p["grade"] or "",
                 p["dept"] or "", p["scope"] or "",
                 "; ".join("%s (%d)" % (bg or "No group", n) for bg, n in sorted(p["bgs"].items())), p["people"],
                 "Yes" if p["target"] else ""]
        status = "Draft, with P&R for review" if p["status"] == "draft" else "Signed off by P&R"
        if not p["five"]:
            jobs.append(ident + ["", "", "", "", "", status])
        for f in p["five"]:
            jobs.append(ident + [f["code"], f["title"], f["now"] or "", "Current", f["source"], status])
            nxt = f.get("next")
            if nxt:
                nr = by_level.get((f["key"], nxt)) or {}
                jobs.append(ident + [nr.get("skill_code") or "", nr.get("title") or f["title"], nxt, "Next",
                                     tc_skill_source(nr.get("skill_code")) if nr else "", status])
    use = {}   # (competency, level) -> the jobs asking for that level now or next
    for p in profs.values():
        for f in p["five"]:
            use.setdefault((f["key"], f["now"]), set()).add(p["id"])
            if f.get("next"):
                use.setdefault((f["key"], f["next"]), set()).add(p["id"])
    comp_of = {r["id"]: it for it in skills.values() for r in it["rows"]}
    comp_head = ["Competency code", "Competency", "Level", "Category", "Type", "Proficiency description", "Knowledge items",
                 "Ability items", "Jobs using this level", "Jobs using the competency (any level)", "Written by", "Status"]
    comps = []
    for r in db.execute("SELECT id, skill_code, title, level, skill_type, skill_category, proficiency_description, "
                        "knowledge_items, ability_items, active FROM tc_skills ORDER BY skill_category, title, level, skill_code"):
        it = comp_of[r["id"]]
        comps.append([r["skill_code"], r["title"], r["level"] or "", r["skill_category"] or "", r["skill_type"] or "",
                      r["proficiency_description"] or "", "\n".join(_tc_ability_list(r["knowledge_items"])),
                      "\n".join(_tc_ability_list(r["ability_items"])), len(use.get((it["key"], r["level"]), ())),
                      len(it["now"] | it["next"]), tc_skill_source(r["skill_code"]),
                      "Active" if r["active"] else ("Waiting for P&R sign-off" if not it["active"] else "Not active")])
    return (jobs_head, jobs), (comp_head, comps), len(profs)


