def _data_integrity_sheets(db, me, cid):
    """[(check, its rows)] for every data check of the cycle, uncapped, in this admin's scope and the panel's picks: the rows
    each check's own page lists (data_check_rows)."""
    out = []
    for chk in DATA_CHECKS:
        rows, _capped = data_check_rows(db, me, cid, chk, cap=False)
        out.append((chk, [r for r in rows if dl_keep({"business_group": r["bg"], "company": r["bu"]})]))
    return out


def _sheet_title(label, used):
    """An Excel sheet name from a check's words: at most 31 characters, none of []:*?/\\, and never one twice."""
    base = re.sub(r"[\[\]:*?/\\]", "", label).strip()[:31].strip() or "Check"
    t, n = base, 2
    while t.lower() in used:
        t = "%s %d" % (base[:28], n)
        n += 1
    used.add(t.lower())
    return t


