def _idp_pct(done, n):
    """Home's percentage, floored (int(done*100/n)); '' when nobody is counted."""
    return ("%d%%" % int(done * 100 / n)) if n else ""


def _idp_group_rows(per_bg, total_label="All business groups"):
    """[{bg, people, started, shared, closed, not_started, total}] from {bg: [people, started, shared, closed]}, biggest group
    first, and an All row at the foot when more than one group shows."""
    rows = [{"bg": bg, "people": v[0], "started": v[1], "shared": v[2], "closed": v[3], "not_started": v[0] - v[1],
             "total": False} for bg, v in per_bg.items()]
    rows.sort(key=lambda r: (-r["people"], display_bg(r["bg"]).lower()))
    if len(rows) > 1:
        t = [sum(v[i] for v in per_bg.values()) for i in range(4)]
        rows.append({"bg": total_label, "people": t[0], "started": t[1], "shared": t[2], "closed": t[3],
                     "not_started": t[0] - t[1], "total": True})
    return rows


_IDP_AGG = ("COUNT(*), SUM(i.id IS NOT NULL), SUM(COALESCE(i.status,'draft')!='draft'), SUM(COALESCE(i.status,'')='closed')")
_IDP_FROM = " FROM users u LEFT JOIN pm_idp i ON i.subject_id=u.id AND i.plan_year=? WHERE 1=1"


def _idp_overview_data(db, me, year, cname):
    """The Career Plan Overview's numbers, in three grouped reads (never a per-person loop): the people in the review (Home's
    Career Plan cell's population, per business group), the check-ins on their plans, and the people who have a plan but are
    outside the review, split by why (_idp_out_reason_sql)."""
    w_in, p_in = _idp_pop_where(me, "in")
    inn = {}
    for r in db.execute("SELECT u.business_group, " + _IDP_AGG + _IDP_FROM + w_in + " GROUP BY u.business_group",
                        [year] + p_in):
        inn[r[0] or ""] = [r[1] or 0, r[2] or 0, r[3] or 0, r[4] or 0]
    checkins = _st_count(db, "SELECT COUNT(*) FROM pm_idp_checkins c JOIN pm_idp_goals gl ON gl.id=c.goal_id "
                             "JOIN pm_idp i ON i.id=gl.idp_id JOIN users u ON u.id=i.subject_id WHERE i.plan_year=?"
                         + w_in, [year] + p_in)
    n, started, shared, closed = [sum(v[i] for v in inn.values()) for i in range(4)]
    tiles = [{"label": "Plans started", "n": started, "which": "started", "of": n, "pct": _idp_pct(started, n),
              "href": {}},
             {"label": "Shared with a manager", "n": shared, "which": "shared", "of": n, "pct": _idp_pct(shared, n),
              "href": {"fstage": "shared"}},
             {"label": "Closed by the manager", "n": closed, "which": "closed", "of": n, "pct": _idp_pct(closed, n),
              "href": {"fstage": "complete"}}]
    w_out, p_out = _idp_pop_where(me, "out")
    out_bg, out_reason = {}, {k: [0, 0, 0, 0] for k in IDP_OUT_REASON_KEYS}
    for r in db.execute("SELECT u.business_group, " + _idp_out_reason_sql("u") + ", " + _IDP_AGG + _IDP_FROM + w_out
                        + " GROUP BY u.business_group, 2", [year] + p_out):
        v = [r[2] or 0, r[3] or 0, r[4] or 0, r[5] or 0]
        t = out_bg.setdefault(r[0] or "", [0, 0, 0, 0])
        tr = out_reason.setdefault(r[1], [0, 0, 0, 0])
        for i in range(4):
            t[i] += v[i]
            tr[i] += v[i]
    out_n = sum(v[0] for v in out_bg.values())
    boxes = []
    for key, label, _short, why in IDP_OUT_REASONS:
        v = out_reason.get(key, [0, 0, 0, 0])
        if v[0] or key != "role":   # the fourth reason shows only when someone has it
            boxes.append({"key": key, "label": label, "people": v[0], "started": v[1], "shared": v[2], "closed": v[3],
                          "why": (why % cname) if "%s" in why else why})
    return {"people": n, "tiles": tiles, "checkins": checkins, "in_rows": _idp_group_rows(inn),
            "out_people": out_n, "out_boxes": boxes, "out_rows": _idp_group_rows(out_bg)}


