# ---------------------------------------------------------------------------
# The OneHR Admin Agent (Chris, 2026-10-10: "add in a OneHR Admin Agent to assist admin in navigating and linking them
# to generate the reports"; asked whether it should save settings: "go with your suggestion, agent never saves
# settings")
# ---------------------------------------------------------------------------
# A chat docked on every admin page. It FINDS where a thing is set and how it reads now, OPENS that page or the exact
# setting, and BUILDS reports from OneHR's data. It has no tool that writes: every tool below only reads, inside this
# admin's own scope (the same bg_scope and route gates the pages use), so it can never see or reach more than the
# admin can, and it never saves, sends or deletes anything -- asked to, it opens the page and says where to save.
# A report it builds is logged (activity_log, action admin_agent_report) and listed on the Reports page.
ADMIN_AGENT_TOOLS = ("find_setting", "find_page", "find_download", "open_page", "cycle_status", "build_report")
_AGENT_STOP = {"the", "a", "an", "to", "of", "for", "in", "on", "is", "are", "do", "i", "where", "what", "how", "can",
               "my", "me", "and", "or", "which", "change", "set", "see", "show", "find", "open", "it", "this", "that",
               "with", "by", "be", "page", "setting", "settings", "please", "pls", "we", "our", "go", "get"}


def _admin_index(db, me, with_values=True):
    """Everything this admin can reach -- pages, settings with how they read now, downloads: the search's and the
    agent's one source, so neither can offer what the other wouldn't."""
    items = []
    for s in ADMIN_SECTIONS:
        v = _section_view(s, me)
        if not v:
            continue
        for t in v["tabs"]:
            shown = [p for p in t["pages"] if not p.get("hidden")]
            for p in shown:
                if len(shown) == 1:
                    label, path = (t["label"], v["label"]) if t["label"] != v["label"] else (v["label"], "")
                else:
                    label, path = p["label"], "%s › %s" % (v["label"], t["label"])
                items.append({"kind": "page", "label": label, "path": path, "href": p["href"],
                              "color": v.get("color")})
    _platform = url_for("admin_module_settings", key="org")
    for r in _all_setting_rows(db, me, with_last=False) if with_values else []:
        if r["href"] and not (r["href"].startswith(_platform) and not is_super(me)):
            items.append({"kind": "setting", "label": r["label"],
                          "path": "%s › %s" % (r["module_label"], "Run" if r["run"] else "Settings"),
                          "value": r["value"], "href": r["href"], "scope": r["scope_label"], "section": r["section"],
                          "can_edit": r["can_edit"], "color": ADMIN_SECTION_COLORS.get(r["module"])})
    for gr in _reports_for(me):
        for f in gr["files"]:
            items.append({"kind": "report", "label": f["label"], "path": "%s · %s" % (gr["label"], f["fmt"]),
                          "href": f["href"], "desc": f["desc"], "color": gr["color"]})
    return items


def _agent_words(query):
    return [w for w in re.findall(r"[a-z0-9&+]+", (query or "").lower()) if len(w) > 1 and w not in _AGENT_STOP]


def _agent_find(items, query, kinds, k=5):
    """The best matches for a free-text query: a word in the label counts three times one in the path or value, and a
    plural matches its singular."""
    words = _agent_words(query)
    if not words:
        return []
    scored = []
    for it in items:
        if it["kind"] not in kinds:
            continue
        lab = it["label"].lower()
        rest = " ".join(str(it.get(x) or "") for x in ("path", "value", "section", "desc")).lower()
        sc = 0
        for w in words:
            stem = w[:-1] if len(w) > 3 and w.endswith("s") else w
            sc += 3 if (w in lab or stem in lab) else (1 if (w in rest or stem in rest) else 0)
        if sc:
            scored.append((sc, it))
    scored.sort(key=lambda x: -x[0])
    return [it for _s, it in scored[:k]]


# ---- reports the agent builds -----------------------------------------------------------------------------------
_AGENT_GROUPS = {"business_group": "Business group", "company": "Unit", "department": "Department",
                 "person": "Person"}
_AGENT_PROGRESS = {"pm": "Performance", "competency": "Competency", "calibration": "Calibration", "f360": "360 feedback"}


def _agent_bg(db, me, raw):
    """The business group a report is narrowed to: None (all this admin sees), a known group, or an error -- a BG
    admin asking for someone else's group is told it is outside their access, never shown it."""
    raw = (raw or "").strip()
    own = admin_bg_of(me)
    if not raw:
        return (own or None), None
    known = org_bgs(db)
    hit = next((b for b in known if b.lower() == raw.lower() or display_bg(b).lower() == raw.lower()), None)
    if not hit:
        hit = next((b for b in known if raw.lower() in b.lower() or raw.lower() in display_bg(b).lower()), None)
    if not hit:
        return None, "There is no business group called %s." % raw
    if own and hit != own:
        return None, "%s is outside your access: you see %s only." % (display_bg(hit), display_bg(own))
    return hit, None


def _agent_report(db, me, p):
    """One report from its parameters (as the agent asked, or as the report's own link carries them), validated here
    every time -- the link is never trusted to scope itself: {title, columns, rows, params} or {error}."""
    kind = (p.get("kind") or "").strip()
    if kind not in ("progress", "pbt", "scoring", "participants"):
        return {"error": "I can build: progress (performance, 360, competency, calibration), PAT achievement by unit, "
                         "scoring mechanism by business group, and who takes part."}
    bg, err = _agent_bg(db, me, p.get("business_group"))
    if err:
        return {"error": err}
    group = p.get("group_by") if p.get("group_by") in _AGENT_GROUPS else "business_group"
    status = p.get("status") if p.get("status") in ("all", "outstanding", "done") else "all"
    module = p.get("module") if p.get("module") in _AGENT_PROGRESS else None
    if kind == "progress" and not module:
        return {"error": "Which module: performance, 360 feedback, competency or calibration?"}
    cyc = active_cycle(db)
    params = {"kind": kind, "group_by": group, "status": status}
    if module:
        params["module"] = module
    if bg and not admin_bg_of(me):
        params["business_group"] = bg

    def keyof(u):
        return {"business_group": display_bg(u["business_group"] or ""), "company": u["company"] or "(none)",
                "department": u["department"] or "(none)"}.get(group)

    rows, columns, title = [], [], ""
    if kind == "progress" and module != "f360":
        mod = _module_view(module)
        users, state, note = _mod_collect(db, me, mod, bg or "")
        title = "%s progress" % _AGENT_PROGRESS[module]
        if group == "person":
            columns = ["Name", "Employee ID", "Business group", "Unit", "Department", "Status", "Detail"]
            for uid, u in users.items():
                st = state.get(uid)
                code = st["state"] if st else None
                if status == "outstanding" and code == "done" or status == "done" and code != "done" or not st:
                    continue
                rows.append([u["full_name"], u["employee_id"], display_bg(u["business_group"] or ""), u["company"],
                             u["department"], st["label"], st["detail"]])
        else:
            agg = {}
            for uid, st in state.items():
                u = users.get(uid)
                if not u:
                    continue
                a_ = agg.setdefault(keyof(u), {"done": 0, "active": 0, "pending": 0})
                a_[st["state"]] += 1
            columns = [_AGENT_GROUPS[group], "Complete", "In progress", "Not started", "Total", "% complete"]
            for k_, a_ in sorted(agg.items(), key=lambda kv: -(kv[1]["active"] + kv[1]["pending"])):
                tot = a_["done"] + a_["active"] + a_["pending"]
                if status == "outstanding" and a_["done"] == tot or status == "done" and a_["done"] < tot:
                    continue
                rows.append([k_, a_["done"], a_["active"], a_["pending"], tot,
                             "%d%%" % round(100.0 * a_["done"] / tot) if tot else "-"])
    elif kind == "progress":   # the 360: the rating tasks each assessor still owes, on the cycle in view
        vc = viewed_cycle(db)
        if not vc:
            return {"error": "There is no cycle to read the 360 from."}
        where, wparams = bg_scope(me, "u.business_group")
        if bg:
            where += " AND u.business_group=?"
            wparams = list(wparams) + [bg]
        q = db.execute("SELECT u.id, u.full_name, u.employee_id, u.business_group, u.company, u.department, "
                       "COUNT(*) n, SUM(a.status='submitted') sub FROM assignments a JOIN users u ON u.id=a.assessor_id "
                       "WHERE a.cycle_id=? AND a.archived=0 AND " + rater_task_sql("a") + where +
                       # 2026-10-31, "out means out" for admin progress counts: only colleagues taking part in the 360
                       " GROUP BY u.id ORDER BY u.full_name", [vc["id"]] + list(wparams)).fetchall()
        title = "360 feedback: rating tasks by assessor's %s" % _AGENT_GROUPS[group].lower()
        if group == "person":
            columns = ["Assessor", "Employee ID", "Business group", "Unit", "Department", "Submitted", "Tasks"]
            for r in q:
                if status == "outstanding" and r["sub"] >= r["n"] or status == "done" and r["sub"] < r["n"]:
                    continue
                rows.append([r["full_name"], r["employee_id"], display_bg(r["business_group"] or ""), r["company"],
                             r["department"], r["sub"] or 0, r["n"]])
        else:
            agg = {}
            for r in q:
                a_ = agg.setdefault(keyof(r), [0, 0])
                a_[0] += r["sub"] or 0
                a_[1] += r["n"]
            columns = [_AGENT_GROUPS[group], "Submitted", "Tasks", "% submitted"]
            for k_, (sub, n) in sorted(agg.items(), key=lambda kv: kv[1][0] / kv[1][1] if kv[1][1] else 1):
                if status == "outstanding" and sub >= n or status == "done" and sub < n:
                    continue
                rows.append([k_, sub, n, "%d%%" % round(100.0 * sub / n) if n else "-"])
        cyc = vc
    elif kind == "pbt":
        if not cyc:
            return {"error": "There is no active cycle."}
        bgs = [bg] if bg else _st_bgs(db, me)
        units = db.execute("SELECT DISTINCT business_group, company FROM org_units WHERE active=1 AND "
                           "COALESCE(company,'')!='' AND business_group IN (%s) ORDER BY business_group, company"
                           % ",".join("?" * len(bgs)), bgs).fetchall() if bgs else []
        got = {(r["business_group"], r["company"]): r["achievement_pct"] for r in db.execute(
            "SELECT business_group, company, achievement_pct FROM pm_pbt_achievement WHERE cycle_id=? "
            "AND COALESCE(company,'')!=''", (cyc["id"],))}
        title = "PAT achievement by unit"
        columns = ["Business group", "Unit", "PAT achievement %", "Curve"]
        for u in units:
            pct = got.get((u["business_group"], u["company"]))
            if status == "outstanding" and pct is not None or status == "done" and pct is None:
                continue
            curve = ("Normal (not entered)" if pct is None else
                     "Below 70%" if pct < 70 else "Above 130%" if pct > 130 else "70-130%")
            rows.append([display_bg(u["business_group"]), u["company"], "" if pct is None else pct, curve])
    elif kind == "scoring":
        bgs = [bg] if bg else _st_bgs(db, me)
        cfg = {r["business_group"]: r for r in db.execute("SELECT * FROM pm_bg_config")}
        title = "Scoring mechanism by business group"
        columns = ["Business group", "Mechanism", "People"]
        for b in bgs:
            c = cfg.get(b)
            mech = ("Not set" if not c else "5-point rating" if c["mechanism"] == "A" else
                    "MBO with hard cap" if c["variant"] == "excellence" else "MBO with multiplier")
            if status == "outstanding" and c or status == "done" and not c:
                continue
            n = _st_count(db, "SELECT COUNT(*) FROM users WHERE business_group=? AND role!='admin' AND left_at IS NULL",
                          (b,))
            rows.append([display_bg(b), mech, n])
    else:   # participants: who takes part in the active cycle's own review
        if not cyc:
            return {"error": "There is no active cycle."}
        where, wparams = bg_scope(me, "u.business_group")
        if bg:
            where += " AND u.business_group=?"
            wparams = list(wparams) + [bg]
        people = db.execute("SELECT u.* FROM users u WHERE " + calibration_population_sql("u") + where +
                            " ORDER BY u.full_name", list(wparams)).fetchall()
        title = "Who takes part"
        if group == "person":
            columns = ["Name", "Employee ID", "Business group", "Department", "Takes part", "Why"]
            why_txt = {"added": "Added by an admin", "removed": "Taken out by an admin", "confirmed": "Confirmed",
                       "not_confirmed": "Not confirmed", "confirmed_after_open": "Confirmed after the cycle opened",
                       "left": "Left", "below_min_grade": "Below the lowest job grade",
                       "grade_h": "Grade H: appraised in Grade H Appraisal",
                       "unit_out": "Unit or department not taking part",
                       "role": "Their user role, given by the super admin"}
            for u in people:
                ok, why = participation(db, u, cyc)
                if status == "outstanding" and ok or status == "done" and not ok:
                    continue
                rows.append([u["full_name"], u["employee_id"], display_bg(u["business_group"] or ""), u["department"],
                             "Yes" if ok else "No", why_txt.get(why, why)])
        else:
            agg = {}
            for u in people:
                ok, _w = participation(db, u, cyc)
                a_ = agg.setdefault(keyof(u), [0, 0])
                a_[0 if ok else 1] += 1
            columns = [_AGENT_GROUPS[group], "Take part", "Don't", "People"]
            for k_, (yes, no) in sorted(agg.items(), key=lambda kv: -kv[1][1]):
                if status == "outstanding" and not no or status == "done" and no:
                    continue
                rows.append([k_, yes, no, yes + no])
    if kind in ("progress", "participants") and not (kind == "progress" and module == "f360"):
        title += (" by %s" % _AGENT_GROUPS[group].lower()) if group != "person" else ", person by person"
    bits = [title]
    if cyc:
        bits.append(cyc["name"])
    if bg:
        bits.append(display_bg(bg))
    if status != "all":
        bits.append({"outstanding": "outstanding only", "done": "done only"}[status])
    return {"title": " · ".join(bits), "columns": columns, "rows": rows[:5000], "total": len(rows),
            "params": params}


def _agent_report_links(params):
    return (url_for("admin_agent_report", **params), url_for("admin_agent_report_xlsx", **params))


# ---- the tools --------------------------------------------------------------------------------------------------
def _agent_run_tool(db, me, action, cache):
    """Run one tool the model asked for. Read-only, every one: there is no tool that writes, and a name that isn't
    in ADMIN_AGENT_TOOLS is refused (a model asking to "save_setting" gets an error, and nothing changes)."""
    tool = str(action.get("tool") or "")
    args = action.get("args") if isinstance(action.get("args"), dict) else {}
    if tool not in ADMIN_AGENT_TOOLS:
        return {"ok": False, "error": "No such tool. You can only find, open and build reports; you never change "
                                      "anything -- tell them where to change it."}
    if "index" not in cache:
        cache["index"] = _admin_index(db, me)
    idx = cache["index"]
    if tool in ("find_setting", "find_page", "find_download"):
        kind = {"find_setting": "setting", "find_page": "page", "find_download": "report"}[tool]
        hits = _agent_find(idx, args.get("query"), (kind,), k=5)
        if not hits and kind == "setting":   # "where is X" may name a page rather than a setting
            hits = _agent_find(idx, args.get("query"), ("page",), k=3)
        return {"ok": True, "found": [{k_: h.get(k_) for k_ in ("kind", "label", "path", "value", "scope", "href",
                                                                 "can_edit") if h.get(k_) is not None}
                                      for h in hits],
                "cards": [{"type": h["kind"], **{k_: h.get(k_) for k_ in ("label", "path", "value", "scope", "href",
                                                                           "can_edit", "color", "desc")}}
                          for h in hits[:3]]}
    if tool == "open_page":
        href = str(args.get("href") or "").strip()
        hit = next((it for it in idx if it["href"] == href and it["kind"] != "report"), None)
        if not hit:
            return {"ok": False, "error": "That isn't a page you can open here: use an href a find tool returned."}
        return {"ok": True, "opened": hit["label"], "open": href,
                "cards": [{"type": hit["kind"], **{k_: hit.get(k_) for k_ in ("label", "path", "value", "scope",
                                                                               "href", "can_edit", "color")}}]}
    if tool == "cycle_status":
        groups, done, total = _admin_readiness(db, me)
        steps = []
        for gr in groups:
            sec = ADMIN_SECTION_BY_KEY.get(_READY_SECTION.get(gr["label"], ""), {})
            for st in gr["steps"]:
                if st["state"] != "done":
                    steps.append({"module": sec.get("label", gr["label"]), "label": st["label"], "detail": st["detail"],
                                  "href": st["url"], "waits_on": st.get("waits")})
        return {"ok": True, "done": done, "total": total, "not_done": steps,
                "cards": [{"type": "status", "label": "%d of %d steps done" % (done, total), "steps": steps[:8]}]}
    # build_report
    rep = _agent_report(db, me, args)
    if rep.get("error"):
        return {"ok": False, "error": rep["error"]}
    page, xlsx = _agent_report_links(rep["params"])
    log_activity(db, me["id"], "admin_agent_report", "%s | %s" % (rep["title"], page))
    return {"ok": True, "title": rep["title"], "rows": rep["total"], "columns": rep["columns"],
            "first_rows": rep["rows"][:5],
            "cards": [{"type": "built", "label": rep["title"], "columns": rep["columns"],
                       "rows": [[str(c) for c in r_] for r_ in rep["rows"][:6]], "total": rep["total"],
                       "page": page, "xlsx": xlsx}]}


def _agent_system(db, me):
    cyc = active_cycle(db)
    vc = viewed_cycle(db)
    own = admin_bg_of(me)
    return "\n".join([
        "You are the OneHR Admin Agent, inside the admin area of OneHR, Chin Hin Group's people platform. The person "
        "writing to you (shown as 'Employee' in the transcript) is a Group People administrator%s."
        % ((" for %s only" % display_bg(own)) if own else " with access to every business group"),
        "You do three things: find where something is set and what it reads now; open that page or setting for "
        "them; and build reports from OneHR's data. You NEVER change, save, send, release or delete anything -- no "
        "setting, date, person, email or result. Asked to change something, find it, open it, and tell them to "
        "change and save it on the page.",
        "Rules: every value, count and name you state comes from a tool result in this conversation -- never guess "
        "a number. Keep replies to one or two short sentences, and name where a thing lives as 'Module › Settings'. "
        "Open a page only with an href a tool returned. For a report call build_report, then say in one line what "
        "it holds; they download it from the card. You see only what this admin can see. Stay on the admin's work "
        "in OneHR; decline anything else in one sentence.",
        "Context: today is %s. The active cycle is %s; the cycle in view is %s. The admin area has Home, Cycle "
        "(calendar of open and close dates, participants, release results, all cycles), five modules (Performance, "
        "360 Feedback, Competency, Calibration & Talent, Career Plan) each with Overview, Run, Settings and Reports, "
        "and, below them in the admin menu, Organisation (people, leaders and admins, org structure), Ticketing, Comms "
        "(email, banner), Reports & audit (reports, audit and usage) and System (all settings). A unit's PAT achievement, "
        "which picks its calibration curve, is set on Calibration & Talent › Run › PAT Ref (not Settings), one "
        "business unit at a time; a business group has no figure of its own, and a unit with none uses the normal curve. A leader's Department Review or "
        "calibration is unlocked (Unlock both) or given more time (Give late pass) on Calibration & Talent › Run › Lock status, "
        "or from the leader's own page: their role chip opens their people with where each stands and those buttons (the super "
        "admin's).%s"
        % (_today_myt().isoformat(), cyc["name"] if cyc else "none", vc["name"] if vc else "none",
           # Grade H Appraisal (2026-10-28): a sixth module in the Modules block, only where ONEHR_GRADEH=1
           " Grade H Appraisal (the super admin's: People & progress, Imports, Final bands, Settings) is a sixth module "
           "in the Modules block." if gradeh_on() else ""),
        "Tools you can call (name and args):",
        '- find_setting {"query": "..."}: settings that match, each with its value now and where it lives',
        '- find_page {"query": "..."}: admin pages that match',
        '- find_download {"query": "..."}: ready-made downloads (CSV, Excel, PDF). A card downloads everything this '
        'admin looks after; on Reports > Data downloads, Download... asks the cycle, business group and units first (the Audit '
        'log: the dates). A module page, list or log has no Excel button of its own now: its file is here, such as Calibration '
        'progress, Lock status, Final bands, Plan progress, Late passes, Opted out of emails, Data integrity, Ask OneHR '
        'questions and AI+ feedback. '
        'Every file is named AI+OneHR_<group>_<unit>_<module>_<report>_<date> and a file about people starts with who '
        'each row is about (group, unit, name, Employee ID, grade, title, department, line manager); the KPI lines '
        'file can be edited and imported back on Performance > Run > Import KPI targets',
        '- open_page {"href": "<an href a tool returned>"}: opens it for them',
        '- cycle_status {}: what is not done yet for this cycle, by module',
        '- build_report {"kind": "progress" | "pbt" | "scoring" | "participants", "module": "pm" | "f360" | '
        '"competency" | "calibration" (progress only), "group_by": "business_group" | "company" | "department" | '
        '"person", "status": "all" | "outstanding" | "done", "business_group": "<optional>"}. For a question about '
        "what is missing or not done yet (who hasn't, which units have no figure), use status outstanding; group_by "
        "applies to progress and participants only. The kinds: progress = who has done their part of a module; pbt = "
        "each unit's PAT achievement; scoring = each business group's scoring mechanism; participants = who takes "
        "part. A question that asks WHICH groups, units or people is a report, not a setting.",
    ])


def _agent_fallback(db, me, msg, say):
    """No model (or a lost turn): a plain search of the same index, so the panel still finds things."""
    idx = _admin_index(db, me)
    hits = _agent_find(idx, msg, ("setting", "page", "report"), k=4)
    cards = [{"type": h["kind"], **{k_: h.get(k_) for k_ in ("label", "path", "value", "scope", "href", "can_edit",
                                                               "color", "desc")}} for h in hits]
    if not hits:
        say += " Nothing in the admin matches those words; try the setting's or the page's name."
    return {"ok": True, "say": say, "quick_replies": [], "cards": cards, "open": None, "mode": "search"}


_AGENT_DECLINE = {
    "injection": "I can't change how I work or share my instructions. I can find settings and pages, open them, "
                 "and build reports.",
    "not_allowed": "That isn't something I can do. I find settings and pages, open them, and build reports; I never "
                   "change anything.",
    "offtopic": "That's outside what I do here. I can find a setting or page, open it, or build a report.",
}


@app.route("/admin/agent", methods=["POST"])
@admin_required
def admin_agent():
    """One Admin Agent turn. The conversation lives in the admin's browser tab and comes back with each message (only
    their words and the agent's -- a tool result is never taken from the client); the server runs every tool, all
    read-only, in this admin's scope."""
    db = get_db()
    me = current_user()
    msg = (request.form.get("message") or "").strip()[:1000]
    try:
        raw = json.loads(request.form.get("history") or "[]")
    except ValueError:
        raw = []
    history = [{"role": h.get("role"), "content": str(h.get("content") or "")[:1000]}
               for h in (raw if isinstance(raw, list) else [])[-12:]
               if isinstance(h, dict) and h.get("role") in ("user", "agent")]
    if not msg:
        return jsonify(ok=False, error="Say what you're looking for."), 400
    kind = ai_draft.screen_message(msg)
    if kind:
        return jsonify(ok=True, say=_AGENT_DECLINE[kind], quick_replies=[], cards=[], open=None, blocked=kind)
    if not ai_draft.review_agent_available():
        return jsonify(_agent_fallback(db, me, msg, "The AI model isn't reachable here, so this is a plain search."))
    history.append({"role": "user", "content": msg})
    system = _agent_system(db, me)
    say, qr, cards, opened, steps, cache = "", [], {}, None, 0, {}
    while steps <= ai_draft.REVIEW_AGENT_MAX_TOOLS:
        steps += 1
        try:
            turn = ai_draft.review_agent(system, history)
        except ai_draft.AIDraftNotConfigured:
            return jsonify(_agent_fallback(db, me, msg, "The AI model isn't switched on, so this is a plain search."))
        except ai_draft.AIDraftError:
            return jsonify(_agent_fallback(db, me, msg, "Sorry, I lost the thread there. Here's a plain search "
                                                        "instead."))
        say, qr, action = turn["say"], turn["quick_replies"], turn["action"]
        if not action:
            break
        result = _agent_run_tool(db, me, action, cache)
        for t_ in {c["type"] for c in result.get("cards", [])}:   # the latest tool's cards stand for their kind
            cards[t_] = [c for c in result["cards"] if c["type"] == t_]
        if result.get("open"):
            opened = result["open"]
        feed = {k_: v for k_, v in result.items() if k_ != "cards"}
        history.append({"role": "agent", "content": say or "(looked something up)"})
        history.append({"role": "tool", "content": json.dumps(feed, default=str)[:1500]})
    order = ("built", "status", "setting", "page", "report")
    out_cards = [c for t_ in order for c in cards.get(t_, [])][:6]
    return jsonify(ok=True, say=say or "Done.", quick_replies=qr, cards=out_cards, open=opened)


@app.route("/admin/agent/report")
@admin_required
def admin_agent_report():
    """A report the agent built, as a page: built again from its parameters, in this admin's scope."""
    db = get_db()
    rep = _agent_report(db, current_user(), request.args)
    if rep.get("error"):
        flash(rep["error"], "error")
        return redirect(url_for("admin_reports_all"))
