@app.route("/admin/agent/report.xlsx")
@admin_required
def admin_agent_report_xlsx():
    """The same report as an Excel file."""
    from openpyxl import Workbook
    from openpyxl.styles import Font
    db = get_db()
    rep = _agent_report(db, current_user(), request.args)
    if rep.get("error"):
        abort(400)
    wb = Workbook()
    ws = wb.active
    ws.title = "Report"
    # every cell through _rr_cell, as every other download (security test 3-01, 2026-10-31): a roster name starting
    # with = would otherwise be stored as a live formula
    ws.append([_rr_cell(rep["title"])])
    ws["A1"].font = Font(bold=True, size=12)
    ws.append([])
    ws.append([_rr_cell(c) for c in rep["columns"]])
    for c in ws[3]:
        c.font = Font(bold=True)
    for r in rep["rows"]:
        ws.append([_rr_cell(v) for v in r])
    for i, col in enumerate(rep["columns"], start=1):
        width = max([len(str(col))] + [len(str(r[i - 1])) for r in rep["rows"][:300] if len(r) >= i])
        ws.column_dimensions[ws.cell(row=3, column=i).column_letter].width = min(60, max(10, width + 2))
    buf = io.BytesIO()
    wb.save(buf)
    name = (rep["title"] or "").strip()[:80] or "report"
    return Response(buf.getvalue(), mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    headers={"Content-Disposition": _attachment_header(name + ".xlsx")})


def _agent_built(db, me, days=30):
    """The reports this admin had the agent build in the last 30 days, newest first (from the activity log)."""
    out, seen = [], set()
    for r in db.execute("SELECT detail, created_at FROM activity_log WHERE user_id=? AND action='admin_agent_report' "
                        "AND created_at >= datetime('now', ?) ORDER BY id DESC LIMIT 40", (me["id"], "-%d days" % days)):
        title, _sep, page = (r["detail"] or "").partition(" | ")
        if not page.startswith("/admin/agent/report") or page in seen:
            continue
        seen.add(page)
        out.append({"title": title, "page": page, "xlsx": page.replace("/admin/agent/report", "/admin/agent/report.xlsx", 1),
                    "when": _st_day(r["created_at"])})
    return out[:10]


# ---------------------------------------------------------------------------
# Admin: edit the leadership framework (principles + behaviours) per cycle
# ---------------------------------------------------------------------------
@app.route("/admin/framework", methods=["GET", "POST"])
@super_required
def admin_framework():
    """Super-admin: edit the ACTIVE cycle's principles + per-tier behaviours.
    Scoped to one cycle (per-cycle snapshots), so edits never touch a closed
    cycle. Edits to a cycle that already has submissions are allowed with a
    warning (the chosen live-cycle policy)."""
    db = get_db()
    me = current_user()
    cyc = active_cycle(db)
    if not cyc:
        flash("No active cycle to edit.", "error")
        return redirect(url_for("admin_module_settings", key="f360"))
    cid = cyc["id"]

    def _owns_criterion(crit_id):
        return db.execute("SELECT 1 FROM cycle_criteria WHERE id=? AND cycle_id=?",
                          (crit_id, cid)).fetchone() is not None

    if request.method == "POST":
        action = request.form.get("action")
        if action == "edit_principle":
            ccid = _form_int("criterion_id")
            name = (request.form.get("name", "") or "").strip()
            desc = (request.form.get("description", "") or "").strip() or None
            if not _owns_criterion(ccid):
                flash("Principle not found in the active cycle.", "error")
            elif not name:
                flash("Principle name is required.", "error")
            else:
                db.execute("UPDATE cycle_criteria SET name=?, description=? WHERE id=?",
                           (name, desc, ccid))
                db.commit()
                log_activity(db, me["id"], "framework_edit_principle", f"{cyc['name']}: edited principle '{name}'")
                flash("Principle updated.", "ok")
        elif action == "add_principle":
            name = (request.form.get("name", "") or "").strip()
            desc = (request.form.get("description", "") or "").strip() or None
            if not name:
                flash("Give the new principle a name.", "error")
            else:
                nxt = db.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM cycle_criteria "
                                 "WHERE cycle_id=?", (cid,)).fetchone()[0]
                db.execute("INSERT INTO cycle_criteria(cycle_id,name,description,sort_order) "
                           "VALUES (?,?,?,?)", (cid, name, desc, nxt))
                db.commit()
                log_activity(db, me["id"], "framework_add_principle", f"{cyc['name']}: added principle '{name}'")
                flash(f"Added principle '{name}'. Add behaviours to it below.", "ok")
        elif action == "remove_principle":
            ccid = _form_int("criterion_id")
            if not _owns_criterion(ccid):
                flash("Principle not found in the active cycle.", "error")
            else:
                pname = db.execute("SELECT name FROM cycle_criteria WHERE id=?", (ccid,)).fetchone()["name"]
                # cascades cycle_statements -> responses (their answers are lost).
                db.execute("DELETE FROM cycle_criteria WHERE id=?", (ccid,))
                db.commit()
                log_activity(db, me["id"], "framework_remove_principle",
                             f"{cyc['name']}: removed principle '{pname}' (behaviours + answers cascaded)")
                flash("Principle removed (its behaviours and any answers to them are gone).", "warn")
        elif action == "edit_behaviour":
            sid = _form_int("statement_id")
            text = (request.form.get("text", "") or "").strip()
            row = db.execute("SELECT cc.name AS crit_name, cs.tier_n FROM cycle_statements cs "
                             "JOIN cycle_criteria cc ON cc.id=cs.criterion_id "
                             "WHERE cs.id=? AND cs.cycle_id=?", (sid, cid)).fetchone()
            if not row:
                flash("Behaviour not found in the active cycle.", "error")
            elif not text:
                flash("Behaviour text can't be empty.", "error")
            else:
                db.execute("UPDATE cycle_statements SET text=? WHERE id=?", (text, sid))
                db.commit()
                log_activity(db, me["id"], "framework_edit_behaviour",
                             f"{cyc['name']}: edited behaviour (tier {row['tier_n']}, '{row['crit_name']}')")
                flash("Behaviour updated.", "ok")
        elif action == "add_behaviour":
            ccid = _form_int("criterion_id")
            try:
                tn = int(request.form.get("tier_n", ""))
            except ValueError:
                tn = 0
            is_future = 1 if request.form.get("is_future") == "1" else 0
            text = (request.form.get("text", "") or "").strip()
            if not _owns_criterion(ccid) or tn not in (1, 2, 3, 4):
                flash("Invalid principle or tier.", "error")
            elif not text:
                flash("Enter the behaviour text.", "error")
            else:
                nxt = db.execute("SELECT COALESCE(MAX(seq),0)+1 FROM cycle_statements "
                                 "WHERE cycle_id=? AND criterion_id=? AND tier_n=? AND is_future=?",
                                 (cid, ccid, tn, is_future)).fetchone()[0]
                db.execute("INSERT INTO cycle_statements(cycle_id,criterion_id,tier_n,is_future,seq,text) "
                           "VALUES (?,?,?,?,?,?)", (cid, ccid, tn, is_future, nxt, text))
                db.commit()
                crit_name = db.execute("SELECT name FROM cycle_criteria WHERE id=?", (ccid,)).fetchone()["name"]
                log_activity(db, me["id"], "framework_add_behaviour",
                             f"{cyc['name']}: added behaviour to '{crit_name}' (tier {tn})")
                flash("Behaviour added.", "ok")
        elif action == "remove_behaviour":
            sid = _form_int("statement_id")
            row = db.execute("SELECT cc.name AS crit_name, cs.tier_n FROM cycle_statements cs "
                             "JOIN cycle_criteria cc ON cc.id=cs.criterion_id "
                             "WHERE cs.id=? AND cs.cycle_id=?", (sid, cid)).fetchone()
            if not row:
                flash("Behaviour not found in the active cycle.", "error")
            else:
                db.execute("DELETE FROM cycle_statements WHERE id=?", (sid,))  # cascades responses
                db.commit()
                log_activity(db, me["id"], "framework_remove_behaviour",
                             f"{cyc['name']}: removed behaviour from '{row['crit_name']}' "
                             f"(tier {row['tier_n']}, answers cascaded)")
                flash("Behaviour removed (any answers to it are gone).", "warn")
        return redirect(url_for("admin_framework"))

    # GET: build the editable structure for the active cycle.
    n_submitted = db.execute("SELECT COUNT(*) FROM assignments WHERE cycle_id=? "
                             "AND status='submitted' AND archived=0", (cid,)).fetchone()[0]
    tiers = effective_tiers(cyc)
    principles = []
    for cc in db.execute("SELECT * FROM cycle_criteria WHERE cycle_id=? ORDER BY sort_order, id",
                         (cid,)).fetchall():
        tier_rows = []
        for t in tiers:
            cur = db.execute("SELECT * FROM cycle_statements WHERE cycle_id=? AND criterion_id=? "
                             "AND tier_n=? AND is_future=0 ORDER BY seq",
                             (cid, cc["id"], t["n"])).fetchall()
            fut = db.execute("SELECT * FROM cycle_statements WHERE cycle_id=? AND criterion_id=? "
                             "AND tier_n=? AND is_future=1 ORDER BY seq",
                             (cid, cc["id"], t["n"])).fetchall()
            tier_rows.append({"tier": {**t, "grades": _tier_grades_label(t)},
                              "current": cur, "future": fut})
        principles.append({"crit": cc, "tiers": tier_rows})
    return _settings_shell("tm", tm_section="360", cycle=cyc, principles=principles,
                           n_submitted=n_submitted)


def _export_scope_label(me):
    """'<BG display name>' for a BG/company-scoped admin, 'All companies'
    for a true super admin (org-wide) -- used to build export filenames."""
    bg = admin_bg_of(me)
    return display_bg(bg) if bg else "All companies"


def _export_filename(base, me, ext="csv"):
    """'<base>_<BG-or-All-companies>_<YYYY-MM-DD>.<ext>', filename-safe; with the download panel's picks in place of
    the scope (2026-10-23): '<base>_<group>_<unit or N units>_<date>'."""
    slug = re.sub(r"[^A-Za-z0-9]+", "_", dl_label(short=True) or _export_scope_label(me)).strip("_")
    return f"{base}_{slug}_{_today_myt().isoformat()}.{ext}"


_XL_DECIMAL_RE = re.compile(r"^-?\d+\.\d+$")


def _xl_num(v):
    """A decimal figure written as text ('3.50') becomes a number; everything else stays as it is -- a whole number
    written as text stays text, so an Employee ID keeps its leading zeros."""
    if isinstance(v, str) and _XL_DECIMAL_RE.match(v.strip()):
        try:
            return float(v)
        except ValueError:
            return v
    return v


def _csv_response(filename, header, rows):
    """Every table download and import template, as Excel (Chris, 2026-10-19: "for consistency, make all import template
    download and export file to excel format"). Kept under its old name because every export calls it: the file's
    extension becomes .xlsx, a cell that could run as a formula keeps its guard (_rr_cell in _xlsx_response), a decimal
    figure becomes a number. The imports still take a .csv as well as a .xlsx."""
    base = re.sub(r"\.csv$", "", filename)
    title = re.sub(r"_(\d{4}-\d{2}-\d{2})$", "", base)
    title = re.sub(r"[_-]+", " ", title).strip().capitalize()[:31] or "Data"
    return _xlsx_response(base + ".xlsx", [(title, header, [[_xl_num(c) for c in r] for r in rows])])


# ---- The rating record: the admin report, Capture, and the Excel export (2026-09-28) ------------------------------
_RR_SOURCE_LABEL = {"raw": "Line manager", "hod": "HOD", "buceo": "BU CEO", "bgceo": "BG CEO",
                    "group": "Calibration group", "top": "Group level", "super": "Super admin override"}
_RR_POT_SOURCE_LABEL = {"raw": "Computed (360 + competency)", "hod": "HOD", "buceo": "BU CEO", "bgceo": "BG CEO",
                        "group": "Calibration group", "top": "Group level", "super": "Super admin"}
_RR_CAPTURE_BATCH = 300     # people per Capture click, so one request stays well inside the 60s proxy


def _rr_scope(db, me, cycle_id):
    """(WHERE fragment, params) for rating_records in this admin's scope + the page's BG / BU filters."""
    where, params = " WHERE rr.cycle_id=?", [cycle_id]
    bclause, bparams = bg_scope(me, "rr.business_group")
    where += bclause
    params += bparams
    fbg = (request.values.get("bg") or "").strip()
    fco = (request.values.get("company") or "").strip()
    if fbg:
        where += " AND rr.business_group=?"; params.append(fbg)
    if fco:
        where += " AND rr.company=?"; params.append(fco)
    return where, params, fbg, fco


def _rr_fig(v, mech=None):
    if v is None:
        return None
    return round(float(v), 1 if mech == "B" else 2)


def _rr_cell(v):
    """An Excel cell that can never run as a formula: people type names, notes and justifications, and a text cell
    starting with = + - @ would otherwise be written as a formula (CSV/formula injection)."""
    if isinstance(v, str) and v[:1] in ("=", "+", "-", "@", "\t", "\r"):
        return "'" + v
    return v


_CSV_PLAIN_NUMBER_RE = re.compile(r"^[+-]?\d+(?:[.,]\d+)*%?$")


def _csv_cell(v):
    """_rr_cell for every CSV download (handoff review, 2026-10-12: only the ratings workbook and the Ask OneHR log were
    guarded). A signed number ('-0.25', '+3') stays a number; text that could run as a formula gets the apostrophe."""
    if isinstance(v, str) and _CSV_PLAIN_NUMBER_RE.match(v.strip()):
        return v
    return _rr_cell(v)


def _xlsx_response(filename, sheets):
    """A real .xlsx from [(sheet title, header, rows)] -- openpyxl (already a dependency), write-only, in memory."""
    from openpyxl import Workbook
    wb = Workbook(write_only=True)
    for title, header, rows in sheets:
        ws = wb.create_sheet(title=title[:31])
        ws.append([_rr_cell(h) for h in header])
        for r in rows:
            ws.append([_rr_cell(v) for v in r])
    buf = io.BytesIO()
    wb.save(buf)
    return Response(buf.getvalue(),
                    mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    headers={"Content-Disposition": _attachment_header(filename)})


def _attachment_header(filename, disposition="attachment"):
    """Content-Disposition for a download: the name quoted, plus the UTF-8 form (RFC 6266) so a + or an accented letter
    in a business group's name survives every browser. `disposition="inline"` is for a preview (callers pass it only for
    an extension in _ATTACH_INLINE_EXTS); the default output for every existing caller is unchanged."""
    plain = re.sub(r'[^\x20-\x7e]', "_", filename).replace('"', "").replace("\\", "_")
    return "%s; filename=\"%s\"; filename*=UTF-8''%s" % (disposition, plain, quote(filename, safe=""))


# What every preview route sends with a stored file (2026-11-11). The type is the extension's, nosniff is explicit (not left to
# the after_request default), and an INLINE image or text file also carries a content policy of its own, so a file that is
# not quite what its name says still cannot run a script or load anything when opened in the box or in a new tab:
#   image: nothing but itself, in a sandbox (no script, no origin);
#   txt:   nothing at all, but NO sandbox: the preview box reaches into the same-origin frame to give Esc back, and a
#          sandbox without allow-same-origin would cut that off;
#   pdf:   no policy. A sandbox policy stops Chrome's built-in PDF viewer from drawing the file, and a PDF is not HTML.
# A download (attachment) needs none. The global Content-Security-Policy-Report-Only header may ride along; both hold.
_FILE_CSP_IMAGE = "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"
_FILE_CSP_TEXT = "default-src 'none'; style-src 'unsafe-inline'"


def _file_response_headers(filename, ext, disp):
    h = {"Content-Disposition": _attachment_header(filename or "file", disp), "X-Content-Type-Options": "nosniff"}
    if disp == "inline":
        if ext in _ATTACH_IMAGE_MIME:
            h["Content-Security-Policy"] = _FILE_CSP_IMAGE
        elif ext == "txt":
            h["Content-Security-Policy"] = _FILE_CSP_TEXT
    return h


