@app.route("/admin/export/pm-status.xlsx")
@admin_required
def admin_export_pm_status():
    """Performance: each person's KPI check-in -- where they are (the Progress page's own status), their lines, the
    results they have entered, whether they signed off, and how many lines their moderator has acted on."""
    db = get_db()
    me = current_user()
    cyc = active_cycle(db)
    if not cyc:
        abort(404)
    cid = cyc["id"]
    users, state, _note = _mod_collect(db, me, _module_view("pm"))
    users = {k: v for k, v in users.items() if dl_keep(v)}   # the download panel's picks
    ids = list(users)
    lines = {r[0]: (r[1], r[2]) for r in _rpt_ids(db, "SELECT subject_id, COUNT(*), SUM(weightage) FROM pm_kpi_targets "
                                                  "WHERE cycle_id=? AND subject_id IN (%s) GROUP BY subject_id", ids,
                                                  (cid,))}
    res = {r[0]: (r[1] or 0, r[2] or 0, r[3] or 0) for r in _rpt_ids(
        db, "SELECT t.subject_id, SUM(COALESCE(r.admin_filled,0)=0), SUM(COALESCE(r.admin_filled,0)=0 AND r.draft=0), "
            "SUM(COALESCE(r.admin_filled,0)=1) FROM pm_kpi_results r JOIN pm_kpi_targets t ON t.id=r.kpi_target_id "
            "WHERE t.cycle_id=? AND t.subject_id IN (%s) GROUP BY t.subject_id", ids, (cid,))}
    mod = {r[0]: r[1] for r in _rpt_ids(
        db, "SELECT t.subject_id, COUNT(DISTINCT a.kpi_target_id) FROM pm_kpi_approvals a JOIN pm_kpi_targets t ON "
            "t.id=a.kpi_target_id WHERE t.cycle_id=? AND t.subject_id IN (%s) GROUP BY t.subject_id", ids, (cid,))}
    signed = {r[0]: r[1] for r in _rpt_ids(db, "SELECT subject_id, locked_at FROM pm_review_session WHERE cycle_id=? AND "
                                              "locked_at IS NOT NULL AND subject_id IN (%s)", ids, (cid,))}
    head, ident = _dl_ident(db, me, users.values())
    rows = []
    for uid, u in sorted(users.items(), key=lambda x: (x[1]["full_name"] or "")):
        st = state.get(uid, {})
        n, w = lines.get(uid, (0, None))
        own, own_sub, hr = res.get(uid, (0, 0, 0))
        # pm_review_locked's rule, batched: their lock row, or (before the sign-off existed) every own result submitted
        is_signed = uid in signed or bool(own and own_sub == own)
        rows.append(ident(u) + [st.get("label") or "", st.get("detail") or "",
                                      n, round(w, 2) if w is not None else None, own, hr,
                                      "Yes" if is_signed else "No",
                                      _st_day(_myt(signed[uid])) if uid in signed else "", mod.get(uid, 0),
                                      _st_day(st.get("last")) if st.get("last") else ""])
    header = head + ["Status", "Detail", "KPI lines", "Weight total %",
                                 "Results entered", "Lines filled by Group People", "Signed off", "Signed off on",
                                 "Lines moderated", "Last change"]
    return _rpt_send(db, me, cyc, "Performance status", header, rows,
                     "Everyone taking part in this cycle's KPI check-in, with where they are: the same status as "
                     "Performance > Run > Progress.",
                     [("Results entered", "KPI lines with a result the person entered (a draft counts). Lines filled "
                                          "by Group People for a whole unit are counted on their own."),
                      ("Lines moderated", "Lines their line manager or matrix manager has confirmed or adjusted.")])


@app.route("/admin/export/pm-results.xlsx")
@admin_required
def admin_export_pm_results():
    """Performance: each person's overall result -- their own, their line manager's, the final band and who decided
    it, and whether it has gone to their leaders and to them."""
    db = get_db()
    me = current_user()
    cyc = _rpt_cycle(db)
    lead, emp = _rpt_released(db, cyc["id"], "leader_releases", "pm"), _rpt_released(db, cyc["id"], "result_releases",
                                                                                     "pm")
    recs = _rpt_records(db, me, cyc)
    head, ident = _dl_ident(db, me, [p for p, _r, _s in recs])
    rows = []
    for p, r, sid in recs:
        mech = _rpt_get(r, "pm_mechanism")
        tot, cov = _rpt_get(r, "pm_weight_total"), _rpt_get(r, "pm_weight_covered")
        rows.append(ident(p) + [
            mech, round(100.0 * cov / tot) if tot and cov is not None else None,
            _rr_fig(_rpt_get(r, "pm_self_value"), mech), _rpt_get(r, "pm_self_band"),
            _rr_fig(_rpt_get(r, "pm_mgr_value"), mech), _rpt_get(r, "pm_mgr_band"), _rpt_get(r, "pm_final_band"),
            _RR_SOURCE_LABEL.get(_rpt_get(r, "pm_final_source") or "", _rpt_get(r, "pm_final_source")),
            "Yes" if sid in lead else "No", "Yes" if sid in emp else "No",
            _rpt_get(r, "updated_at") if r is not None else "No result yet"])
    header = head + ["Scoring", "Weight covered %", "Own score", "Own band", "Line manager's score",
                                 "Line manager's band", "Final band", "Final band decided by", "Released to leaders",
                                 "Released to them", "Recorded at (UTC)"]
    return _rpt_send(db, me, cyc, "Performance results", header, rows,
                     "Each person's overall performance result, as recorded at their last sign-off or calibration lock.",
                     [("Scoring", "A is the 1-5 rating; B is an achievement %."),
                      ("No result yet", "Taking part, but nothing signed off or calibrated yet.")])


@app.route("/admin/export/competency-lines.xlsx")
@admin_required
def admin_export_tc_lines():
    """Competency: one row per person per competency set for them -- its level, whether it is their current or next
    level, their own answer and their line manager's."""
    db = get_db()
    me = current_user()
    cyc = _rpt_cycle(db)
    where, params = bg_scope(me, "u.business_group")
    stat = {"pending": "Started", "submitted": "Submitted", "reviewed": "Reviewed"}
    yn = {"yes": "Yes", "no": "No"}
    got = db.execute(
            "SELECT u.employee_id, u.full_name, u.business_group, u.company, u.department, u.job_grade, u.job_title, "
            "s.skill_code, s.title, s.skill_category, s.level, a.is_future, ta.status, sc.answer, sc.manager_answer "
            "FROM tc_assignments a JOIN users u ON u.id=a.subject_id JOIN tc_skills s ON s.id=a.skill_id "
            "LEFT JOIN tc_assessments ta ON ta.cycle_id=a.cycle_id AND ta.subject_id=a.subject_id "
            "LEFT JOIN tc_scores sc ON sc.assignment_id=a.id AND sc.assessment_id=ta.id "
            "WHERE a.cycle_id=? AND u.role!='admin' AND COALESCE(u.is_demo,0)=0" + where + dl_sql("u.")[0] +
            " ORDER BY u.full_name, u.id, a.is_future, a.seq, a.id", [cyc["id"]] + list(params) + dl_sql("u.")[1]
    ).fetchall()
