# ---- Who's missing, as a file for its own import (Chris, 2026-10-21: "it should also have the export for people
# without KPI line, 360 panel, competency too. so admin can export them in excel and update the list and import back.
# So the export needs to follow our import format"). Each row is one person, only their Employee ID filled, under the
# import's own columns; the "Reference:" columns after them aren't imported; a row left as it is is skipped on import
# (_import_blank_note), so a part-filled file goes in. Scoped like every download: the admin's own people.
IMPORT_REFERENCE_COLUMNS = ("Reference: name", "Reference: business group", "Reference: business unit",
                            "Reference: department", "Reference: job title", "Reference: job grade",
                            "Reference: line manager", "Reference: line manager employee ID")
JOB_IMPORT_COLUMNS = ("Employee ID", "Job code", "Job scope")


def _missing_export(db, me, what, filename, sheet, people, cols, extra=(), how=(), fill=None, refs=True):
    """The download: `people` [user dicts] under `cols` (the Employee ID first, the rest blank; or `fill(u)`, a value
    per column, for an import that needs more than the ID), the reference columns (unless `refs` is False: the
    import's own columns carry them), any `extra` (header, fn(u)) reference columns, and a How to fill sheet. Logged as
    an export. The download panel's picks narrow `people` (2026-10-23) and name the file."""
    people = [u for u in people if dl_keep(u)]
    mgr = _manager_names(db, [u.get("manager_id") for u in people])
    mgr_eid = _manager_eids(db, [u.get("manager_id") for u in people])
    rows = [(list(fill(u)) if fill else [u.get("employee_id") or ""] + [""] * (len(cols) - 1))
            + ([u.get("full_name") or "", display_bg(u.get("business_group") or "") or "", u.get("company") or "",
                u.get("department") or "", u.get("job_title") or "", u.get("job_grade") or "",
                mgr.get(u.get("manager_id"), ""), mgr_eid.get(u.get("manager_id"), "")] if refs else [])
            + [fn(u) or "" for _h, fn in extra]
            for u in sorted(people, key=lambda x: (x.get("business_group") or "", x.get("company") or "",
                                                   x.get("full_name") or ""))]
    fname = _dl_filename(me)
    log_activity(db, me["id"], "export", "%s: %s (%d people)" % (fname, what, len(rows)))
    # the import's columns come first and unchanged so the file goes back in; About goes after the How to fill sheet
    return _xlsx_response(fname, [
        (sheet, list(cols) + (list(IMPORT_REFERENCE_COLUMNS) if refs else []) + [h for h, _fn in extra], rows),
        ("How to fill", ["How to fill it in"], [[line] for line in how]),
        ("About", ["Item", "Detail"], _dl_about_rows(me, what, active_cycle(db), rows,
                                                     "The import's own columns come first, filled in where OneHR "
                                                     "knows the value, then Reference: columns that are only for "
                                                     "reading. See How to fill."))])


def _manager_eids(db, ids):
    """{users.id: Employee ID} for these line managers, one query a 900."""
    ids, out = [i for i in dict.fromkeys(ids) if i], {}
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        out.update({r[0]: r[1] for r in db.execute(
            "SELECT id, employee_id FROM users WHERE id IN (%s)" % ",".join("?" * len(part)), part)})
    return out


