@app.route("/admin/export/talent-status.xlsx")
@admin_required
def admin_export_talent():
    """Calibration: each person's talent status from their final performance and potential bands, whether it is
    released to them, and their talent status in the three Year-Ends before."""
    db = get_db()
    me = current_user()
    cyc = _rpt_cycle(db)
    y, _h = _cycle_year_half(cyc)
    years = [y - 1, y - 2, y - 3] if y else []
    recs = _rpt_records(db, me, cyc)
    rel = _rpt_released(db, cyc["id"], "talent_releases")
    lead = _rpt_released(db, cyc["id"], "leader_releases", "talent")
    ids = [sid for _p, _r, sid in recs]
    hist = {}
    if years:
        for h in _rpt_ids(db, "SELECT subject_id, year, category FROM talent_status_history WHERE year IN (?,?,?) AND "
                              "subject_id IN (%s)", [i for i in ids if i], years):
            hist[(h[0], h[1])] = h[2]
    head, ident = _dl_ident(db, me, [p for p, _r, _s in recs])
    rows = []
    for p, r, sid in recs:
        perf, pot = _rpt_get(r, "pm_final_band"), _rpt_get(r, "pot_final_band")
        cat = talent_category(perf, pot) if (perf and pot) else None
        rows.append(ident(p) + [perf, pot, cat or ("Not placed yet" if r is not None else "No result yet"),
                                      "Yes" if sid in lead else "No", "Yes" if sid in rel else "No"]
                    + [hist.get((sid, yy), "") for yy in years])
    header = head + ["Final performance band", "Final potential band", "Talent status",
                                 "Released to leaders", "Released to them"] + ["Talent status %d" % yy for yy in years]
    return _rpt_send(db, me, cyc, "Talent status", header, rows,
                     "Each person's talent status: where their final performance and potential bands place them on "
                     "the talent box.",
                     [("Not placed yet", "One of the two final bands is still missing."),
                      ("Talent status <year>", "The status recorded for that Year-End (imported for 2023 to 2025).")])


