    if cyc:
        where, params, fbg, fco = _rr_scope(db, me, cid)
        rows = db.execute("SELECT * FROM rating_records rr" + where + " ORDER BY rr.full_name", params).fetchall()
        frozen = any(r["frozen_at"] for r in rows)
