@app.route("/admin/export/results.csv")   # the old address, kept
@app.route("/admin/export/results.xlsx")
@admin_required
def admin_export_results():
    db = get_db()
    me = current_user()
    vc = _dl_cycle_id(db)   # ?cycle= from the download panel, else the top bar's
    bclause, bparams = bg_scope(me)
    dsql, dparams = dl_sql()
    subjects = db.execute(
        "SELECT * FROM users WHERE role!='admin' "
        "AND id IN (SELECT subject_id FROM assignments WHERE archived=0 AND cycle_id=?)" + bclause + dsql
        + " ORDER BY full_name", [vc] + bparams + dparams
    ).fetchall()
    head, ident = _dl_ident(db, me, subjects)
    # Each rater's submitted overall remark (Chris, 2026-11-11): "Rater 1 remark", "Rater 2 remark"... in the order they
    # submitted, never the rater's name, ID, email or relationship. One query a 900 subjects, never one a person.
    remarks = _results_rater_remarks(db, [s["id"] for s in subjects], vc)
    n_rem = max((len(v) for v in remarks.values()), default=0)
    rows = []
    for s in subjects:
        res = subject_result(db, s, vc)
        mine = remarks.get(s["id"], [])
        rows.append(ident(s) + [
            s["email"] or "",
            res["panel_size"], res["submitted"],
            "Yes" if res["score_valid"] else "No",
            "" if res["avg_score"] is None else f"{res['avg_score']:.2f}",
            f"{res['max_score']:g}", res["band"] or "",
            "" if res["avg_score_raw"] is None else f"{res['avg_score_raw']:.2f}",
            "" if not res["adjustment"] else f"{res['adjustment']:+.2f}",
        ] + [mine[i] if i < len(mine) else "" for i in range(n_rem)])
    header = head + ["Email", "Panel Size", "Assessors Submitted",
              "Score Valid (>=4)", "Avg Score", "Max Score", "Potential Band",
              "Avg Score (pre-adjustment)", "Extreme-Assessor Adjustment"] + [
              "Rater %d remark" % (i + 1) for i in range(n_rem)]
    return _dl_book(db, me, "360 results", header, rows, "Each subject's 360 result for the cycle: the panel, the "
                    "assessors who submitted, the score, the potential band it gives and any extreme-assessor "
                    "adjustment. It also carries each rater's submitted overall remark, numbered by the order the "
                    "raters submitted (Rater 1 remark is the first to submit, blank where that rater left none; the "
                    "numbers match the Rater column of the Responses download), without the rater's name.",
                    cyc=db.execute("SELECT name FROM cycles WHERE id=?", (vc,)).fetchone(), num=True)


def _results_rater_remarks(db, subject_ids, cycle_id):
    """{subject id: [remark, ...]} for the 360 Results download: slot n is the overall remark of the n-th SUBMITTED rater (the
    order _rater_order gives, the one the Responses download numbers "Rater n" by), "" where that rater left no remark;
    trailing blanks cut, a subject with no remark left out. Same filter as admin_subject_detail(): submitted, not archived,
    this cycle, stripped, non-blank. Text only: the rater is never in what this returns. Batched, 900 subjects a query."""
    out = {}
    ids = list(dict.fromkeys(subject_ids))
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        order = _rater_order(db, part, cycle_id)
        text = {}
        for r in db.execute(
                "SELECT fr.assignment_id AS aid, fr.remark FROM feedback_remarks fr JOIN assignments a ON a.id=fr.assignment_id "
                "WHERE a.cycle_id=? AND a.archived=0 AND a.status='submitted' AND TRIM(fr.remark)<>'' "
                "AND a.subject_id IN (%s)" % ",".join("?" * len(part)), [cycle_id] + part):
            text[r["aid"]] = (r["remark"] or "").strip()
        for sid, aids in order.items():
            slots = [text.get(aid, "") for aid in aids]
            while slots and not slots[-1]:
                slots.pop()
            if slots:
                out[sid] = slots
    return out


def _rater_order(db, subject_ids, cycle_id):
    """{subject id: [assignment id, ...]} -- each subject's SUBMITTED raters in RATER ORDER: submitted_at, then the assignment
    id. Pending (a draft is private to its author) and archived ratings are not in it. It is the one numbering the 360
    downloads share (Chris, 2026-11-11, "Masked, no relationship"): Responses' "Rater n" for every admin but the super
    admin, and Results' "Rater n remark". IDs only: the rater is never in what this returns. Batched, 900 subjects a query."""
    out = {}
    ids = list(dict.fromkeys(subject_ids))
    for i in range(0, len(ids), 900):
        part = ids[i:i + 900]
        for r in db.execute(
                "SELECT subject_id, id FROM assignments WHERE cycle_id=? AND archived=0 AND status='submitted' "
                "AND subject_id IN (%s) ORDER BY subject_id, submitted_at, id" % ",".join("?" * len(part)),
                [cycle_id] + part):
            out.setdefault(r["subject_id"], []).append(r["id"])
    return out


@app.route("/admin/export/responses.csv")   # the old address, kept
@app.route("/admin/export/responses.xlsx")
@admin_required
def admin_export_responses():
    """Every answer in the cycle's 360. The super admin's file names each assessor (ID, name, email, relationship). Every
    other admin's file (BG, BU, a custom role) holds the SUBMITTED raters' answers only (no draft) and ONE column, Rater,
    "Rater N" by the order the raters submitted (Chris, 2026-11-11, "Masked, no relationship"; the same N as Results'
    "Rater N remark"): the assessor's identity is never read for that file."""
    db = get_db()
    me = current_user()
    masked = not is_super(me)
    vc = _dl_cycle_id(db)   # ?cycle= from the download panel, else the top bar's
    _rsc, _rsp = bg_scope(me, "su.business_group")  # BG + sub-admin company scope
    _dsc, _dsp = dl_sql("su.")
    _rsc, _rsp = _rsc + _dsc, list(_rsp) + _dsp
    # the masked file selects, joins and orders by nothing of the assessor
    cols = ("" if masked else "ass.employee_id AS assr_eid, ass.full_name AS assr_name, ass.email AS assr_email, "
                              "a.relationship, ")
    join = "" if masked else "JOIN users ass ON ass.id = a.assessor_id\n           "
    order = ("su.full_name, su.id, c.sort_order, st.seq" if masked
             else "su.full_name, ass.full_name, c.sort_order, st.seq")
    only = " AND a.status = 'submitted'" if masked else ""   # a draft is private to its author: the masked file holds submitted raters only
    rows = db.execute(
        """SELECT su.employee_id AS subj_eid, su.id AS _sid, """ + cols + """a.status,
                  c.name AS criterion,
                  CASE WHEN st.is_future=1 THEN 'Future' ELSE 'Current' END AS type_,
                  st.text AS statement, r.answer, a.id AS _aid, st.tier_n AS _tn
           FROM responses r
           JOIN assignments a ON a.id = r.assignment_id
           JOIN users su  ON su.id = a.subject_id
           """ + join + """JOIN cycle_statements st ON st.id = r.statement_id
           JOIN cycle_criteria c ON c.id = st.criterion_id
           WHERE a.archived = 0 AND a.cycle_id = ?""" + only + _rsc + " ORDER BY " + order,
        [vc] + _rsp,
    ).fetchall()
    # a pending rating's rows of another tier (left by a job grade move) are not answers to the subject's behaviours: left out
    _live = _fb_live_tiers(db, {r["_aid"] for r in rows})
    rows = [r for r in rows if _live.get(r["_aid"]) is None or _live[r["_aid"]] == r["_tn"]]
    head, ident = _dl_ident(db, me, [{"employee_id": e} for e in dict.fromkeys(r["subj_eid"] for r in rows)])
    if masked:
        # by subject (the file's order so far), then rater number, then the criterion and statement order the query gave
        order_of = _rater_order(db, list(dict.fromkeys(r["_sid"] for r in rows)), vc)
        rank = {aid: i + 1 for lst in order_of.values() for i, aid in enumerate(lst)}
        rows = [r for r in rows if r["_aid"] in rank]   # a rating reopened between the two reads takes no number (never a 500)
        subj_pos = {}
        for r in rows:
            subj_pos.setdefault(r["_sid"], len(subj_pos))
        rows = sorted(rows, key=lambda r: (subj_pos[r["_sid"]], rank[r["_aid"]]))   # stable: statements keep their order
        out = [ident({"employee_id": r["subj_eid"]}) + ["Rater %d" % rank[r["_aid"]], r["status"], r["criterion"],
                                                        r["type_"], r["statement"], r["answer"]] for r in rows]
        header = head + ["Rater", "Status", "Principle", "Level Type", "Statement", "Answer"]
        what = ("Every submitted answer in the cycle's 360. The identity columns describe the person rated. Each rater is "
                "a number, in the order the raters submitted (Rater 1 submitted first, the same numbers as the Results "
                "download's Rater n remark); no rater is named and no relationship is given.")
    else:
        out = [ident({"employee_id": r["subj_eid"]}) + list(tuple(r)[2:11]) for r in rows]   # the subject is who the row is about
        header = head + ["Assessor ID", "Assessor", "Assessor Email",
                  "Relationship", "Status", "Principle", "Level Type", "Statement", "Answer"]
        what = ("Every submitted answer in the cycle's 360. The identity columns describe the person rated; the "
                "assessor's columns follow.")
    return _dl_book(db, me, "360 responses", header, out, what,
                    cyc=db.execute("SELECT name FROM cycles WHERE id=?", (vc,)).fetchone(), num=True)


# ---------------------------------------------------------------------------
# Admin: assessor progress (who has completed their assigned ratings)
# ---------------------------------------------------------------------------
def _assessor_progress_query(me, q, scope, cycle_id, qin="all"):
    """Build (sql, params) for the per-assessor completion aggregate, scoped to
    the admin's Business Group and one review cycle. scope='incomplete' keeps
    only assessors who still have unsubmitted ratings."""
    bclause, bparams = bg_scope(me, "u.business_group")
    # 2026-10-31, "out means out" for admin progress counts: a row for a colleague not taking part in the 360 is not a task
    where = "WHERE a.archived=0 AND a.cycle_id=? AND " + rater_task_sql("a") + bclause
    params = [cycle_id] + list(bparams)
    if q:   # the field picked in Search in (2026-10-26); All fields as before (name, ID, department) and more
        sql_, args_ = _people_search_sql(qin, q, "u.", USERS_SEARCH_EXTRA)
        where += " AND " + sql_
        params += args_
    having = " HAVING done < assigned" if scope == "incomplete" else ""
    sql = ("SELECT u.id, u.employee_id, u.full_name, u.email, u.department, u.job_grade, u.job_title, "
           "u.business_group, u.company, "
           "COUNT(*) AS assigned, "
           "SUM(CASE WHEN a.status='submitted' THEN 1 ELSE 0 END) AS done, "
           # Most recent login (Malaysia time), or NULL if they've never logged in.
           "(SELECT MAX(datetime(al.created_at, '+8 hours')) FROM activity_log al "
           " WHERE al.user_id = u.id AND al.action = 'login') AS last_login "
           "FROM assignments a JOIN users u ON u.id = a.assessor_id "
           + where + " GROUP BY u.id" + having)
    return sql, params


@app.route("/admin/assessors")
@admin_required
def admin_assessors():
    db = get_db()
    q, qin, search_in = people_search_args(USERS_SEARCH_EXTRA, request.args)
    scope = request.args.get("scope", "all")  # all | incomplete
    try:
        page = max(1, int(request.args.get("page", "1")))
    except ValueError:
        page = 1
    per_page = _per_page()
    sql, params = _assessor_progress_query(current_user(), q, scope, viewed_cycle_id(db), qin)

    # Business Group quick-filter (super-admin only; single value — see
    # BG_FILTER_OPTIONS) + server-side column filters (Company / Department) —
    # all applied to the OUTER query so they span all pages and persist
    # across pagination.
    fbg = request.args.get("fbg", "").strip()
    fcompany = request.args.getlist("fcompany")
    fdept = request.args.getlist("fdept")
    wrap = f"SELECT * FROM ({sql})"
    wparams = list(params)
    conds = []
    if fbg:
        conds.append("business_group = ?")
        wparams.append(fbg)
    for col, vals in (("company", fcompany), ("department", fdept)):
        if not vals:
            continue
        real = [v for v in vals if v != ""]
        ors = []
        if real:
            ors.append("%s IN (%s)" % (col, ",".join("?" * len(real))))
            wparams += real
        if "" in vals:
            ors.append("(%s IS NULL OR %s='')" % (col, col))
        conds.append("(%s)" % " OR ".join(ors))
    if conds:
        wrap += " WHERE " + " AND ".join(conds)
    total = db.execute(f"SELECT COUNT(*) FROM ({wrap})", wparams).fetchone()[0]
    rows = db.execute(
        wrap + " ORDER BY full_name LIMIT ? OFFSET ?",
        wparams + [per_page, (page - 1) * per_page]).fetchall()
    total_pages = max(1, (total + per_page - 1) // per_page)

    # Value lists for the filter dropdowns + base params carried by nav links.
    bclause, bparams = bg_scope(current_user(), "business_group")
    filt_companies = [(r["company"] or "") for r in db.execute(
        f"SELECT DISTINCT company FROM users WHERE role!='admin'{bclause} ORDER BY company", bparams)]
    filt_depts = [(r["department"] or "") for r in db.execute(
        f"SELECT DISTINCT department FROM users WHERE role!='admin'{bclause} ORDER BY department", bparams)]
    base_pairs = [("scope", scope), ("per_page", per_page)]
    if q:
        base_pairs += [("q", q)] + ([("qin", qin)] if qin != "all" else [])
    filt_pairs = (([("fbg", fbg)] if fbg else [])
                  + [("fcompany", v) for v in fcompany] + [("fdept", v) for v in fdept])
    base_qs = urlencode(base_pairs + filt_pairs)
    filt_qs = urlencode(filt_pairs)
    n_filters = (1 if fbg else 0) + (1 if fcompany else 0) + (1 if fdept else 0)
    # For the BG pill row: carry scope/search/other-column-filters but NOT fbg
    # itself, so each pill link can set (or omit, for "All") its own value.
    carry_qs = urlencode(base_pairs + [("fcompany", v) for v in fcompany]
                          + [("fdept", v) for v in fdept])
    frows, _pk = admin_filter_rows(db, current_user(), "admin_assessors", params=("fbg", "fcompany", "fdept"))
    return render_template("admin_assessors.html", rows=rows, q=q, qin=qin, search_in=search_in, scope=scope,
                           frows=frows,
                           page=page, total_pages=total_pages, total=total,
                           per_page=per_page, per_page_options=PER_PAGE_OPTIONS,
                           filt_companies=filt_companies, filt_depts=filt_depts,
                           active_fcompany=fcompany, active_fdept=fdept,
                           base_pairs=base_pairs, base_qs=base_qs, filt_qs=filt_qs,
                           n_filters=n_filters,
                           bg_options=BG_FILTER_OPTIONS, active_fbg=fbg,
                           carry_qs=carry_qs, is_super=is_super(current_user()))


@app.route("/admin/export/assessor-progress.csv")   # the old address, kept
@app.route("/admin/export/assessor-progress.xlsx")
@admin_required
def admin_export_assessor_progress():
    db = get_db()
    me = current_user()
    q, qin, _menu = people_search_args(USERS_SEARCH_EXTRA, request.args)
    scope = request.args.get("scope", "all")
    sql, params = _assessor_progress_query(me, q, scope, _dl_cycle_id(db), qin)
    # Honour the page's Business Group / Company / Department filters (applied
    # on the outer query) so the export mirrors exactly what's on screen.
    wrap = f"SELECT * FROM ({sql})"
    wparams = list(params)
    conds = []
    fbg = request.args.get("fbg", "").strip()
    if fbg:
        conds.append("business_group = ?")
        wparams.append(fbg)
    for col, vals in (("company", request.args.getlist("fcompany")),
                      ("department", request.args.getlist("fdept"))):
        if not vals:
            continue
        real = [v for v in vals if v != ""]
        ors = []
        if real:
            ors.append("%s IN (%s)" % (col, ",".join("?" * len(real))))
            wparams += real
        if "" in vals:
            ors.append("(%s IS NULL OR %s='')" % (col, col))
        conds.append("(%s)" % " OR ".join(ors))
    if conds:
        wrap += " WHERE " + " AND ".join(conds)
    got = db.execute(wrap + " ORDER BY full_name", wparams).fetchall()
    head, ident = _dl_ident(db, me, got)
    out = []
    for r in got:
        assigned, done = r["assigned"], r["done"]
        remaining = assigned - done
        status = ("Done" if done == assigned
                  else "Not started" if done == 0 else "In progress")
        out.append(ident(r) + [r["email"] or "", assigned, done, remaining, status,
                               r["last_login"] or "Never logged in"])
    header = head + ["Email", "Assigned", "Done", "Remaining", "Status", "Last login (MYT)"]
    return _dl_book(db, me, "Assessor progress", header, out, "Everyone assigned to rate someone in the cycle's 360 "
                    "and how far they have got. The identity columns describe the assessor.",
                    cyc=db.execute("SELECT name FROM cycles WHERE id=?", (_dl_cycle_id(db),)).fetchone(), num=True)


def _assessor_extremes_classify(db, vc, fbg, fcompany, fdept):
    """Shared by the page and its CSV export: classify every assessor whose
    ENTIRE submitted panel this cycle is 100% one answer, then split into
    always-no / always-yes, honouring the active fbg/fcompany/fdept filters.
    Returns (always_no, always_yes, always_no_all, always_yes_all, subj_links)
    -- the _all lists are unfiltered, needed by the page to build each
    column's own filter-value checklist (see admin_assessor_extremes)."""
    agg_all = _extreme_assessor_agg(db, vc)

    always_no_all = [r for r in agg_all if r["no_count"] == r["total_responses"]]
    always_yes_all = [r for r in agg_all if r["yes_count"] == r["total_responses"]]

    def _matches(r, skip=None):
        for col, active in (("business_group", fbg), ("company", fcompany), ("department", fdept)):
            if col == skip or not active:
                continue
            if (r[col] or "") not in active:
                return False
        return True

    always_no = [r for r in always_no_all if _matches(r)]
    always_yes = [r for r in always_yes_all if _matches(r)]

    # Per-assessor (subject, assignment_id) links for the "click through to
    # responses" affordance -- a small follow-up query scoped to just the
    # flagged (displayed) assessor IDs, grouped in Python (avoids fragile
    # GROUP_CONCAT text-parsing for names that could contain the separator
    # characters).
    flagged_ids = [r["id"] for r in always_no] + [r["id"] for r in always_yes]
    subj_links = {}
    if flagged_ids:
        ph = ",".join("?" * len(flagged_ids))
        for r in db.execute(f"""
            SELECT a.assessor_id, a.id AS assignment_id, s.id AS subject_id, s.full_name AS subject_name
            FROM assignments a JOIN users s ON s.id = a.subject_id
            WHERE a.assessor_id IN ({ph}) AND a.cycle_id=? AND a.status='submitted' AND a.archived=0
            ORDER BY s.full_name
        """, flagged_ids + [vc]).fetchall():
            subj_links.setdefault(r["assessor_id"], []).append(r)

    return always_no, always_yes, always_no_all, always_yes_all, subj_links


@app.route("/admin/assessor-extremes")
@super_required
def admin_assessor_extremes():
    """Assessors whose ENTIRE submitted panel this cycle is 100% one answer --
    a possible rater-quality signal (not proof of anything by itself). Super-
    admin only; BGHR/sub-admins are already restricted to one BG elsewhere and
    this is an org-wide monitoring view, not a workflow tool."""
    db = get_db()
    vc = viewed_cycle_id(db)
    # business group, unit and department rows (the admin review, 2026-10-10), in place of three column menus that
    # listed raw group and unit names; both tables follow the one choice
    frows, fsel = admin_filter_rows(db, current_user(), "admin_assessor_extremes", params=("fbg", "fcompany", "fdept"))
    fbg = [fsel["bg"]] if fsel["bg"] else []
    fcompany = [fsel["bu"]] if fsel["bu"] else []
    fdept = [fsel["dept"]] if fsel["dept"] else []

    always_no, always_yes, _no_all, _yes_all, subj_links = \
        _assessor_extremes_classify(db, vc, fbg, fcompany, fdept)

    base_pairs = [("fbg", v) for v in fbg] + [("fcompany", v) for v in fcompany] + [("fdept", v) for v in fdept]
    extremes_enabled, extremes_bonus, extremes_penalty = get_extremes_adjustment_settings()
    return render_template(
        "admin_assessor_extremes.html", frows=frows,
        always_no=always_no, always_yes=always_yes, subj_links=subj_links,
        active_fbg=fbg, active_fcompany=fcompany, active_fdept=fdept,
        base_pairs=base_pairs,
        extremes_enabled=extremes_enabled, extremes_bonus=extremes_bonus, extremes_penalty=extremes_penalty,
    )


@app.route("/admin/export/assessor-extremes.csv")   # the old address, kept
@app.route("/admin/export/assessor-extremes.xlsx")
@super_required
def admin_export_assessor_extremes():
    """CSV mirror of /admin/assessor-extremes, honouring the same active
    fbg/fcompany/fdept filters. One row per (assessor, subject) -- matches
    the page's one-subject-per-row table layout."""
    db = get_db()
    me = current_user()
    vc = _dl_cycle_id(db)   # ?cycle= from the download panel, else the top bar's
    fbg = request.args.getlist("fbg")
    fcompany = request.args.getlist("fcompany")
    fdept = request.args.getlist("fdept")

    always_no, always_yes, _, _, subj_links = \
        _assessor_extremes_classify(db, vc, fbg, fcompany, fdept)

    head, ident = _dl_ident(db, me, always_no + always_yes)   # the assessor is who the row is about
    out = []
    for label, rows in (("Always says No", always_no), ("Always says Yes", always_yes)):
        for r in rows:
            subs = subj_links.get(r["id"], [])
            if not subs:
                out.append(ident(r) + [label, ""])
                continue
            for s in subs:
                out.append(ident(r) + [label, s["subject_name"]])
    header = head + ["Type", "Subject"]
    return _dl_book(db, me, "Rater extremes", header, out, "Assessors whose whole submitted panel is one answer, a "
                    "row for each person they rated. The identity columns describe the assessor.",
                    cyc=db.execute("SELECT name FROM cycles WHERE id=?", (vc,)).fetchone(), num=True)


USER_ROLES = (("", "Everyone"), ("leads", "Anyone who leads"), ("lm", "Line managers"), ("hod", "HODs"),
              ("buceo", "BU CEOs"), ("cg", "Calibrators"), ("bgceo", "BG CEOs"), ("gc", "Group Chiefs"),
              ("none", "No role yet"))
USER_ROLE_KEYS = tuple(k for k, _l in USER_ROLES)


def _user_role_sql(key, alias="users"):
    """A users-row predicate for a role on the Users page (admin round 4, row 8): what the person leads TODAY -- line
    manager and HOD from the reporting lines, BU CEO / BG CEO / Group Chief from their seats."""
    t = alias
    each = {
        "lm": "EXISTS (SELECT 1 FROM users x WHERE x.manager_id=%s.id AND x.left_at IS NULL AND x.role!='admin')" % t,
        "hod": "EXISTS (SELECT 1 FROM users x WHERE x.hod_id=%s.id AND x.left_at IS NULL AND x.role!='admin')" % t,
        "buceo": "EXISTS (SELECT 1 FROM buceo_seats s WHERE s.user_id=%s.id)" % t,
        "cg": "EXISTS (SELECT 1 FROM calib_bu_groups cg_ WHERE cg_.calibrator_id=%s.id AND cg_.active=1)" % t,
        "bgceo": "COALESCE(%s.bgceo_bg,'')!=''" % t,
        "gc": "EXISTS (SELECT 1 FROM pm_calibration_groups g WHERE g.calibrator_id=%s.id)" % t}
    if key in each:
        return each[key]
    anyl = "(" + " OR ".join(each.values()) + ")"
    return anyl if key == "leads" else ("NOT " + anyl if key == "none" else "1=1")


@app.route("/admin/export/users.csv")   # the old address, kept
@app.route("/admin/export/users.xlsx")
@admin_required
def admin_export_users():
    """All users in the admin's scope (BG/companies), honouring the Users page's
    search + Business Group / Company / Status column filters. Columns: ID, name,
    BG, company, department, job grade, confirmation status, line manager."""
    db = get_db()
    me = current_user()
    bclause, bparams = bg_scope(me, "u.business_group")
    where = "WHERE u.role!='admin'" + bclause
    params = list(bparams)
    q = request.args.get("q", "").strip()
    if q:
        # the list's own search: the field picked in Search in, else all of them (2026-10-20; it used to look in
        # name, Employee ID and department only, so the download could hold fewer people than the list)
        sql_, args_ = _people_search_sql(request.args.get("qin", "all"), q, "u.")
        where += " AND " + sql_
        params += args_
    show = request.args.get("show", "all")     # menu export = everyone in scope
    if show == "active":
        where += " AND u.left_at IS NULL"
    elif show == "left":
        where += " AND u.left_at IS NOT NULL"
    elif show == "linked":   # anyone with an active linked Employee ID, leavers included (2026-10-30)
        where += " AND u.id IN (SELECT user_id FROM user_employee_ids WHERE removed_at IS NULL)"
    femail = request.args.get("femail", "")
    if femail == "missing":
        where += " AND (u.email IS NULL OR u.email='' OR u.email NOT LIKE '%@%')"
    elif femail == "has":
        where += " AND u.email LIKE '%@%'"
    fbg = [v for v in request.args.getlist("fbg") if v]
    fcompany = request.args.getlist("fcompany")
    fdept = [v for v in request.args.getlist("fdept") if v]
    if request.args.get("role") in USER_ROLE_KEYS and request.args.get("role"):   # the Users page's Role row (row 8)
        where += " AND " + _user_role_sql(request.args["role"], "u")
    fstatus = [v for v in request.args.getlist("fstatus") if v]
    if fdept:
        where += " AND TRIM(COALESCE(u.department,'')) IN (%s)" % ",".join("?" * len(fdept))
        params += fdept
    if fbg:
        where += " AND u.business_group IN (%s)" % ",".join("?" * len(fbg))
        params += fbg
    if fcompany:
        cvals = [c for c in fcompany if c != ""]
        ors = []
        if cvals:
            ors.append("u.company IN (%s)" % ",".join("?" * len(cvals)))
            params += cvals
        if "" in fcompany:
            ors.append("(u.company IS NULL OR u.company='')")
        where += " AND (%s)" % " OR ".join(ors)
    if fstatus:
        smap = {
            "Inactive": "u.left_at IS NOT NULL",
            "Confirmed": "(u.left_at IS NULL AND (u.confirmation_date IS NOT NULL OR u.years_of_service>1))",
            "Not confirmed": "(u.left_at IS NULL AND u.confirmation_date IS NULL "
                             "AND (u.years_of_service IS NULL OR u.years_of_service<=1))",
        }
        conds = [smap[s] for s in fstatus if s in smap]
        if conds:
            where += " AND (%s)" % " OR ".join(conds)
    got = db.execute(
        "SELECT u.id, u.employee_id, u.full_name, u.business_group, u.company, u.department, u.job_grade, u.job_title, "
        "u.email, u.employment_type, u.cost_center, u.work_location, u.joined_date, u.confirmation_date, "
        "u.years_of_service, u.user_role_id, u.bgceo_bg, u.left_at, h.full_name AS hod_name, h.employee_id AS hod_eid "
        "FROM users u LEFT JOIN users h ON h.id=u.hod_id " + where + " ORDER BY u.full_name", params).fetchall()
    head, ident = _dl_ident(db, me, got)
    # everything on the person's page, each read once for the whole list (never a query a person)
    ac = active_cycle(db)
    taking = {r[0] for r in db.execute("SELECT u.id FROM users u WHERE u.role!='admin' AND " + participant_sql("u"))} \
        if ac else set()
    n_hod = dict(db.execute("SELECT hod_id, COUNT(*) FROM users WHERE hod_id IS NOT NULL AND role!='admin' AND "
                            "left_at IS NULL GROUP BY hod_id").fetchall())
    n_lm = dict(db.execute("SELECT manager_id, COUNT(*) FROM users WHERE manager_id IS NOT NULL AND role!='admin' "
                           "AND left_at IS NULL GROUP BY manager_id").fetchall())
    bu_seats, chief = {}, {}
    for r in db.execute("SELECT user_id, business_group, company FROM buceo_seats ORDER BY business_group, company"):
        bu_seats.setdefault(r[0], []).append(display_company(r[1], r[2]) or r[2])
    for r in db.execute("SELECT calibrator_id, name FROM pm_calibration_groups WHERE calibrator_id IS NOT NULL "
                        "ORDER BY name"):
        chief.setdefault(r[0], []).append(r[1])
    cals = _calibrator_group_names(db)
    linked = _eid_linked_map(db, [u["id"] for u in got])   # Linked IDs column, one query for the list
    out = []
    for u in got:
        svc = person_service(u)
        confirmed = bool(u["confirmation_date"] or (u["years_of_service"] or 0) > 1)
        out.append(ident(u) + [
            u["hod_name"] or "", u["hod_eid"] or "", u["email"] or "", u["employment_type"] or "",
            u["cost_center"] or "", u["work_location"] or "", u["joined_date"] or "", svc["length"],
            u["confirmation_date"] or "", "Confirmed" if confirmed else "Not confirmed", urole_name(u, db)[0]]
            + ([("Yes" if u["id"] in taking else "No")] if ac else [])
            + ["; ".join(bu_seats.get(u["id"], [])), (display_bg(u["bgceo_bg"]) or "") if u["bgceo_bg"] else "",
               "; ".join(chief.get(u["id"], [])), "; ".join(cals.get(u["id"], [])),
               n_hod.get(u["id"], 0), n_lm.get(u["id"], 0),
               ("Left " + _myt(u["left_at"])[:10]) if u["left_at"] else "Active", ", ".join(linked.get(u["id"], []))])
    header = head + ["HOD", "HOD employee ID", "Work email", "Employment type", "Cost center", "Work location",
                     "Joined date", "Years of service", "Confirmation date", "Confirmation status", "User role"] \
        + (["Taking part in %s" % ac["name"]] if ac else []) \
        + ["BU CEO of", "BG CEO of", "Group Chief of", "Calibration group", "HOD of", "Line manager of", "Status", "Linked IDs"]
    return _dl_book(db, me, "Users", header, out,
                    "The roster as it stands today, one row a person, with what is on their page in the admin portal: "
                    "who leads them, their record, their user role, whether they take part in the active cycle and "
                    "what they lead. It never holds an ID or passport number, a password or a private display name.",
                    [("Years of service", "Counted from the joined date to today, as the person's page says it."),
                     ("HOD of / Line manager of", "People still here who report to them."),
                     ("Linked IDs", "Their other Employee IDs still linked to them, comma-separated; empty when none.")],
                    num=True)


@app.route("/admin/export/panels.csv")   # the old address, kept
@app.route("/admin/export/panels.xlsx")
@admin_required
def admin_export_panels():
    """Every panel pairing (subject × assessor) in the admin's scope for the
    viewed cycle, honouring the Subjects page's search + BG/Company/Department/
    Job grade filters. One row per assessor on each subject's panel."""
    db = get_db()
    me = current_user()
    vc = _dl_cycle_id(db)   # ?cycle= from the download panel, else the top bar's
    bclause, bparams = bg_scope(me, "su.business_group")
    where = "WHERE su.role!='admin' AND a.archived=0 AND a.cycle_id=?" + bclause
    params = [vc] + list(bparams)
    q, qin, _menu = people_search_args(PROGRESS_SEARCH_EXTRA, request.args)
    if q:   # the page's search, in the field it picked (2026-10-26)
        sql_, args_ = _people_search_sql(qin, q, "su.", PROGRESS_SEARCH_EXTRA)
        where += " AND " + sql_
        params += args_
    fbg = request.args.get("fbg", "").strip()
    if fbg:
        where += " AND su.business_group = ?"
        params.append(fbg)
    for col, vals in (("su.company", request.args.getlist("fcompany")),
                      ("su.department", request.args.getlist("fdept")),
                      ("CAST(su.job_grade AS TEXT)", request.args.getlist("fjg"))):
        if not vals:
            continue
        real = [v for v in vals if v != ""]
        ors = []
        if real:
            ors.append("%s IN (%s)" % (col, ",".join("?" * len(real))))
            params += real
        if "" in vals:
            ors.append("(%s IS NULL OR %s='')" % (col, col))
        where += " AND (%s)" % " OR ".join(ors)
    rows = db.execute(
        "SELECT su.employee_id, ass.full_name AS a_name, ass.employee_id AS a_eid, "
        "ass.job_grade AS a_jg, ass.department AS a_dept, a.relationship "
        "FROM assignments a JOIN users su ON su.id=a.subject_id "
        "JOIN users ass ON ass.id=a.assessor_id " + where
        + " ORDER BY su.full_name, a.relationship, ass.full_name", params).fetchall()
    relmap = {"line_manager": "Line Manager", "peer": "Peer/Stakeholder", "direct_report": "Direct Report"}
    head, ident = _dl_ident(db, me, [{"employee_id": e} for e in dict.fromkeys(r["employee_id"] for r in rows)])
    out = [ident({"employee_id": r["employee_id"]}) + [r["a_name"], r["a_eid"], r["a_jg"], r["a_dept"],
                                                       relmap.get(r["relationship"], r["relationship"])]
           for r in rows]   # the subject is who the row is about; one row an assessor
    header = head + ["Assessor Name", "Assessor ID", "Assessor JG", "Assessor Department", "Relationship"]
    return _dl_book(db, me, "360 panels", header, out, "Who rates whom in the cycle's 360: a row for each assessor on "
                    "each subject's panel. The identity columns describe the person rated.",
                    cyc=db.execute("SELECT name FROM cycles WHERE id=?", (vc,)).fetchone(), num=True)


