def ready_rules_save(db, me, rules):
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('ready_notice_rules', ?)", (json.dumps(rules),))
    db.commit()
    log_activity(db, me["id"], "ready_notice_schedule", "on=%s, checked every day at %s, to %s" % (
        rules["enabled"], rules["send_time"], ", ".join(rules["roles"]) or "nobody"))
