def gradeh_switch_set(db, me, on):
    """(ok, message): the Grade H switch. One setting, one audit row ('gradeh_reminders_switch')."""
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)", (GRADEH_SWITCH_KEY, "1" if on else "0"))
    db.commit()
    log_activity(db, me["id"], "gradeh_reminders_switch", "on=%s, from Email › Schedule: the staff email, the Grade H lines in "
                 "Everyone's reminder, Grade H progress and the Grade H ready notes" % bool(on))
    return True, ("Grade H reminders are on: the staff email, the Grade H lines in Everyone's reminder, Grade H progress and the "
                  "ready notes go on their days." if on else
                  "Grade H reminders are off: none of the Grade H emails goes. Everyone's reminder carries on without its Grade H lines.")


EMAIL_SWITCHES = {"reminder": reminder_switch_set, "gradeh": gradeh_switch_set, "lp": lp_switch_set, "bga": bga_switch_set,
                  "ready": ready_switch_set}


@app.route("/admin/email/switch", methods=["POST"])
@super_required
def admin_email_switch():
    """One schedule's switch on Email › Schedule's top card (2026-11-09): `email` = reminder | gradeh | lp | bga | ready, `enabled` =
    on | off. Each writes the SAME setting its Set it up page saves, through that email's one writer (EMAIL_SWITCHES). The super
    admin's alone, behind OneHR's confirm box."""
    fn = EMAIL_SWITCHES.get(request.form.get("email", ""))
    if not fn or request.form.get("enabled") not in ("on", "off"):
        abort(400)
    db = get_db()
    if request.form.get("email") == "gradeh" and not gradeh_rm_cid(db):
        abort(404)   # Grade H has no switch where it does not run
    ok, said = fn(db, current_user(), request.form.get("enabled") == "on")
    flash(said, "ok" if ok else "error")
    return redirect(url_for("admin_email_schedule"))


def _gradeh_lead_rows(db, u, cid):
    """What waits on `u` as a Grade H leader in the parts open now: [(role, text, detail, cells, url, extra)]. The appraiser
    (the people gradeh_lm_people gives, the lm.gradeh ability, while the appraisal part is open and someone is not yet
    submitted), the HOD (gradeh_hod_can, which follows gradeh_hod_has_role; while a review stage is open and not signed off) and the
    BU CEO (a unit with Grade H people, not yet signed off or released, while the sign-off is open). ONE reader for the
    reminder email and the bar's Grade H lines, so the two never disagree. [] where Grade H does not run."""
    out = []
    if not u or is_admin(u) or not gradeh_module_on(db, cid):
        return out
    if _reminder_open(db, ("gradeh_lm",), cid):
        people = gradeh_lm_people(db, u, cid)
        if people:
            bulk = _gh_lm_bulk(db, cid, people)
            kw = gradeh_window_closed(db, GRADEH_CELL_KPI, cid)
            kpi_closed = bool(kw and kw[0] == "closed")
            ready = kpi = 0
            for p in people:
                a_ = bulk[p["id"]]["app"]
                if a_ and a_["lm_submitted_at"]:
                    continue
                if gradeh_lm_status(db, p, bulk[p["id"]], kpi_closed)["kind"] == "wait_kpi":
                    kpi += 1
                else:
                    ready += 1
            if ready or kpi:
                out.append(("gradeh_lm", "Appraise your Grade H team",
                            " \u00b7 ".join(x for x in (
                                "%d ready for you" % ready if ready or not kpi else "",
                                "%d waiting for their KPI achievement" % kpi if kpi else "") if x),
                            ("gradeh_lm",), url_for("review_gradeh"), {"n_ready": ready, "n_kpi": kpi}))
    if gradeh_hod_can(db, u):
        st = gradeh_hod_state(db, cid, u["id"])
        pend = tuple(cell for stg, cell in (("pot", "gradeh_hod_pot"), ("perf", "gradeh_hod_perf"))
                     if st[stg] is None and window_state(db, cell, cid) == "open"
                     and gradeh_hod_open_for(db, cid, u["id"], stg)["open"])   # open for THIS HOD (the early-opening rule)
        if pend:
            n = sum(1 for r_ in gradeh_hod_scope(db, u["id"], cid) if not r_["disagree_at"])   # a person who does not agree is not reviewed
            out.append(("gradeh_hod", "Review your Grade H people: potential, then performance",
                        "%d %s" % (n, "person" if n == 1 else "people"), pend, url_for("calib_gradeh_hod"), {"n": n}))
    if _reminder_open(db, ("gradeh_buceo",), cid):
        for bg, co in gradeh_buceo_units(db, u):
            if _gh_cal_lock_text(db, cid, co):   # signed off by the BU CEO, or released
                continue
            if not gradeh_bu_open_for(db, cid, co, bg)["open"]:   # inside the cell, but not open for this unit yet (the early-opening rule)
                continue
            n = sum(1 for r_ in gradeh_unit_scope(db, cid, bg, co) if not r_["disagree_at"])
            out.append(("gradeh_buceo", "Sign off Grade H for %s" % (display_company(bg, co) or co),
                        "%d %s" % (n, "person" if n == 1 else "people"), ("gradeh_buceo",),
                        url_for("calib_gradeh_unit", unit=co), {"n": n, "unit": (bg, co)}))
    return out


def gradeh_ack_deadline_dates(db, cid):
    """The days (dates, MYT) by which a Grade H person still to acknowledge must, for the schedule and the send days: the
    earlier of their deemed deadline (gradeh_deemed_deadline, the one reader: none with the switch off) and the acknowledge
    part's close. With a fixed deemed date that is one day for everyone; with N days after the line manager submits it is
    one for each day someone was submitted, and the part's close for anyone submitted later."""
    close = _parse_when(window_dates(db, "gradeh_ack", cid)[1])
    cd = close.date() if close else None
    if gradeh_deemed_on(cid) and gradeh_setting("gradeh_deemed_mode", cid) == "fixed":
        fx = _gh_myt(gradeh_deemed_deadline(db, cid, "2000-01-01 00:00:00"))
        got = [d for d in (fx.date() if fx else None, cd) if d]
        return [min(got)] if got else []
    out = {cd} if cd else set()
    if gradeh_deemed_on(cid):   # each still-waiting submission's own deadline, from the one reader
        for r in db.execute("SELECT DISTINCT lm_submitted_at FROM gradeh_appraisals WHERE cycle_id=? AND lm_submitted_at IS NOT NULL "
                            "AND acknowledged_at IS NULL AND deemed_at IS NULL AND ack_in_person=0", (cid,)):
            dl = _gh_myt(gradeh_deemed_deadline(db, cid, r[0]))
            if dl:
                out.add(min(dl.date(), cd) if cd else dl.date())
    return sorted(out)


def gradeh_ack_deadline(db, cid, lm_submitted_at):
    """The MYT date-time one person must acknowledge by: the earlier of their deemed deadline and the acknowledge part's
    close; None when neither exists."""
    close = _parse_when(window_dates(db, "gradeh_ack", cid)[1])
    dl = _gh_myt(gradeh_deemed_deadline(db, cid, lm_submitted_at))
    got = [x for x in (dl, close) if x]
    return min(got) if got else None


def reminder_day_parts(db, cyc, day, rules=None, ignore_switch=False):
    """Which emails `day` sends under the rules: {'regular': Everyone's reminder (any part but the staff's own Grade H
    ones), 'staff': Grade H staff's own email}. With Grade H off, regular is simply "is it a send day". `ignore_switch` reads the
    day as if Everyone's reminder's own switch were on: the Grade H staff email follows the Grade H switch only (2026-11-09)."""
    rules = rules or reminder_rules()
    if ignore_switch:
        rules = dict(rules, enabled=True)
    why = reminder_why(db, cyc, day, rules)
    return {"regular": any(c not in GRADEH_STAFF_CELLS for _k, c, _w in why),
            "staff": any(c in GRADEH_STAFF_CELLS for _k, c, _w in why)}


def reminder_items(db, u):
    """What is waiting on `u` in the parts open NOW: [{group, role, text, detail, closes, url}]. Read from the
    dashboard's own sources -- the Your review panel's open parts, the Your team card's people waiting, the leader rows
    with something left -- and only where that part's window is open. Empty for an admin, a leaver, or nobody waiting.
    The bar, the page's counts and the previews read it as it is, so what waits is shown whatever the day; the email asks
    reminder_items_email, which keeps a Grade H leader's item to that leader's own three days."""
    cyc = active_cycle(db)
    if not cyc or not u or is_admin(u) or _row_get(u, "left_at"):
        return []
    cid = cyc["id"]
    review = dash_review_summary(db, u)
    panel = dash_review_panel(db, u, review)
    team = dash_team_card(db, u, review) if panel else None
    leaders = _dash_leader_rows(dash_cards(db, u, review, dash_leadership(db, u), None))
    out = []

    def item(group, role, text, detail, cells, url, people=None, late=None):
        d = {"group": group, "role": role, "text": text, "detail": detail or "",
             "closes": _reminder_closes(db, cells, cid), "closes_on": _reminder_close_date(db, cells, cid),
             "url": url, "people": people or []}
        if late:   # a late pass (2026-10-31): the part is closed for others, and open for them until the pass's time
            until = _parse_when(_myt(late["until_at"]))
            left = (until.date() - _today_myt()).days
            d.update(closes="open for you until %d %s%s" % (until.day, until.strftime("%b"), " · today" if left == 0 else
                                                            " · 1 day" if left == 1 else " · %d days" % left),
                     closes_on=until.date(), late_until=until)
        out.append(d)
    for m_ in (panel or {}).get("modules") or []:
        for p in m_["parts"]:
            if p["state"] != "open":       # the panel already marks a part outside its window 'closed'
                continue
            cell = _DASH_PART_CELL.get(p["key"])
            lt = _reminder_late(db, u, (cell,), cid) if cell and not _reminder_open(db, (cell,), cid) else None
            if cell and not lt and not _reminder_open(db, (cell,), cid):
                continue
            own = "f360" if p["key"] == "feedback" else "own"
            item(own, own, _REMINDER_OWN_TEXT.get(p["key"], p["name"]), p.get("count"), (cell,) if cell else (),
                 panel["url"], late=lt)
    split = None
    for p in (team or {}).get("parts") or []:
        if not p["turn"]:
            continue
        cells = _REMINDER_TEAM_CELLS.get(p["key"], ())
        if p["key"] == "pm_review":
            # the KPI team part holds two kinds of work, each with its own window: results to moderate
            # (pm_approve) and proposed targets to approve (pm_setting_approve) -- only the ones actually waiting count
            split = split or _pm_pending_split(db, u, cid)
            cells = tuple(c for c, n in (("pm_approve", split["team_pending"]),
                                         ("pm_setting_approve", split["setting_review_pending"])) if n) or cells
        lt = _reminder_late(db, u, cells, cid) if not _reminder_open(db, cells, cid) else None   # a follow-on's time
        if not lt and not _reminder_open(db, cells, cid):
            continue
        names = [r["name"] for r in p["turn"]]
        item("team", "team", _REMINDER_TEAM_TEXT.get(p["key"], p["name"]),
             "%d %s waiting on you: %s%s" % (len(names), "person" if len(names) == 1 else "people",
                                            ", ".join(names[:3]), " and %d more" % (len(names) - 3)
                                            if len(names) > 3 else ""), cells, p["url"],
             people=[r.get("id") or r["name"] for r in p["turn"]], late=lt)
    for c in leaders:
        if _dash_lead_state(c) != "turn":
            continue
        role, cells = _REMINDER_LEAD.get(c.get("dest"), ("lead", ()))
        lt = _reminder_late(db, u, cells, cid) if not _reminder_open(db, cells, cid) else None   # a leader's pass
        if not lt and not _reminder_open(db, cells, cid):
            continue
        item("lead", role, _DASH_LEAD_NAME.get(c.get("dest"), c.get("dest") or c.get("name") or ""), c.get("sub"),
             cells, c["url"], late=lt)
    if gradeh_on():   # Grade H's leaders (2026-10-31): one more item in the email they already get
        for role, text, detail, cells, url, extra in _gradeh_lead_rows(db, u, cid):
            item("gradeh", role, text, detail, cells, url)
            out[-1].update(extra, cells=tuple(cells))   # the cells (and a BU CEO's unit): what reminder_items_email reads
    return out


def _bgceo_seat_ids(db):
    """The ids of everyone seated as a BG CEO (users.bgceo_bg set; active, not an admin: lp_leaders' own test), in ONE query."""
    return {r[0] for r in db.execute("SELECT id FROM users WHERE TRIM(COALESCE(bgceo_bg,''))!='' AND left_at IS NULL AND role!='admin'")}


def _reminder_drop_bu_lead(u, items):
    """`items` without the BU CEO's Calibration line when `u` holds a BG CEO seat (read off the row: no query)."""
    if not (_row_get(u, "bgceo_bg") or "").strip():
        return items
    # a BG CEO who is also a BU CEO gets no BU CEO email (Chris, 2026-11-11)
    return [i for i in items if not (i.get("group") == "lead" and i.get("role") == "buceo")]


def reminder_items_email(db, u, items=None, honour_skips=True, progress=True):
    """What goes in `u`'s reminder EMAIL: reminder_items, except that
      * the Grade H lines (every item of the group 'gradeh') are not in it at all while the Grade H switch is off or Grade H does not run,
        nor on a day the super admin skipped the Grade H reminders (`honour_skips`; Send now passes False, an explicit act): Everyone's
        reminder carries on without them (2026-11-09);
      * a Grade H leader's item (the appraiser's, the HOD's, the BU CEO's) is in it only on that leader's own three days (Chris,
        2026-11-06; gradeh_lead_send_days: the day the part first opened for them, 3 days before it closes, its last day), checked at the
        send's own day, so the send-time recheck holds it too;
      * an HOD or BU CEO who gets Grade H progress that day (or whose ready note went) has no Grade H lead line for that role in it
        (`progress`; one email, not two; gradeh_prog_served is the same decision the send makes, 2026-11-09).
    `items` = the list already read. Every other item is kept as read."""
    items = reminder_items(db, u) if items is None else items
    items = _reminder_drop_bu_lead(u, items)   # a BG CEO who is also a BU CEO gets no BU CEO email (Chris, 2026-11-11)
    if not any(i.get("group") == "gradeh" for i in items):
        return items
    cyc = active_cycle(db)
    if not gradeh_mail_ok(db, cyc, honour_skips=honour_skips):
        return [i for i in items if i.get("group") != "gradeh"]
    if not any(i.get("group") == "gradeh" and i.get("role") in GRADEH_LEAD_ROLES and i.get("cells") for i in items):
        return items
    today, send_t = _today_myt(), _rm_send_time(reminder_rules())
    served = gradeh_prog_served(db, cyc, u, today, honour_skips) if progress and any(
        i.get("group") == "gradeh" and i.get("role") in ("gradeh_hod", "gradeh_buceo") for i in items) else {}
    out = []
    for i in items:
        if i.get("group") == "gradeh" and i.get("role") in GRADEH_LEAD_ROLES and i.get("cells"):
            if today not in gradeh_lead_send_days(db, cyc["id"], u["id"], i["cells"], i.get("unit"), send_t):
                continue
            if (i.get("role") == "gradeh_hod" and served.get("hod")) or (i.get("role") == "gradeh_buceo" and served.get("buceo")):
                continue
        out.append(i)
    return out


# --- when it goes out (the super admin's rules) ------------------------------
def _rm_date(raw):
    """A 'YYYY-MM-DD' string as a date, else None (a reminder's date range)."""
    try:
        return date.fromisoformat(raw) if raw and re.match(r"^\d{4}-\d\d-\d\d$", str(raw)) else None
    except ValueError:
        return None


def _rm_span(f, t):
    """'from 1 Oct 2026 to 10 Oct 2026' / 'from 1 Oct 2026' / 'until 10 Oct 2026' / '' for a date range."""
    d = lambda x: "%d %s %d" % (x.day, x.strftime("%b"), x.year)   # noqa: E731
    return ("from %s to %s" % (d(f), d(t)) if f and t else "from %s" % d(f) if f else "until %s" % d(t) if t else "")


def reminder_range_from(form):
    """((from, to) as ISO strings or None, error or '') from a schedule form's two date fields (Chris, 2026-10-19:
    "admin should be able to configure from 1 Oct to 10 Oct to send out the employee reminder every day at 9am")."""
    raw = [(form.get(k) or "").strip() for k in ("range_from", "range_to")]
    got = [_rm_date(x) for x in raw]
    if any(r and not g for r, g in zip(raw, got)):
        return (None, None), "Enter the dates as day, month and year, or leave them blank."
    if got[0] and got[1] and got[1] < got[0]:
        return (None, None), "The last day comes before the first."
    return tuple(g.isoformat() if g else None for g in got), ""


def reminder_rules():
    """{enabled, on_open, days_before, every_days, send_time, every_from, every_to}. enabled / days_before / send_time
    are the old schedule's keys, kept; days_before now counts back from each PART's closing date (the cycle's own target
    date when no part has one). every_from / every_to bound the repeat to a date range (2026-10-19): it then counts from
    the first day, every N days, whatever part is open; blank, it repeats while each part is open, from its opening.
    cc_lm (2026-11-06, off until switched on): Everyone's reminder copies the person's line manager while their own part
    or 360 ratings wait (reminder_lm_cc)."""
    s = reminder_schedule()
    try:
        every = max(0, min(REMINDER_EVERY_MAX, int(_setting("reminder_every_days", "0") or 0)))
    except (TypeError, ValueError):
        every = 0
    f, t = _rm_date(_setting("reminder_every_from")), _rm_date(_setting("reminder_every_to"))
    return dict(s, on_open=_setting("reminder_on_open", "1") == "1", every_days=every,
                every_from=f.isoformat() if f else None, every_to=t.isoformat() if t else None,
                cc_lm=_setting("reminder_cc_lm", "0") == "1")


def _rm_send_time(rules):
    """The rules' send time ('09:00') as a time of day."""
    try:
        h, m = (int(x) for x in str(rules.get("send_time") or "09:00").split(":")[:2])
        return datetime.min.replace(hour=h, minute=m).time()
    except (TypeError, ValueError):
        return datetime.min.replace(hour=9).time()


def set_reminder_rules(enabled, on_open, days_before, every_days, send_time, every_from=None, every_to=None, cc_lm=None):
    """Save the schedule. cc_lm None = leave the line-manager copy as it is (every other caller); True / False sets it."""
    set_reminder_schedule(enabled, days_before, send_time)
    db = get_db()
    if cc_lm is not None:
        db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_cc_lm', ?)", ("1" if cc_lm else "0",))
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_on_open', ?)", ("1" if on_open else "0",))
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_every_days', ?)", (str(every_days),))
    for key, v in (("reminder_every_from", every_from), ("reminder_every_to", every_to)):
        if v:
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)", (key, v))
        else:
            db.execute("DELETE FROM app_settings WHERE key=?", (key,))
    db.commit()


# --- the line manager on cc (Chris, 2026-11-06) ------------------------------------------------------------
# Everyone's reminder copies the person's line manager, in the same single email, only while one of the person's OWN tasks
# waits: their own parts (item group "own": KPI check-in, competency self-assessment, Career Plan) or 360 ratings they owe
# ("f360"). Leader / team / Grade H items never trigger it, and Grade H staff's own email never carries it. Off until the
# super admin ticks "Copy their line manager" on Email › Reminders. Never copied (Chris, 2026-11-07): the Executive Chairman
# (the stored seat, whether or not ONEHR_CHAIR is on) or a BG CEO as the line manager; the person's email still goes, with no
# cc. ONE rule, here: reminder_send and the send-time recheck both ask it.
REMINDER_CC_GROUPS = ("own", "f360")
_LM_LOOKUP = object()   # reminder_lm_cc's `lm`: not read yet, look the manager up (None = the run read them and there is none)


def reminder_cc_lm_on(db):
    """Is the line-manager copy switched on (app_settings 'reminder_cc_lm' = '1')? Read through `db`."""
    r = db.execute("SELECT value FROM app_settings WHERE key='reminder_cc_lm'").fetchone()
    return bool(r) and r[0] == "1"


def reminder_managers(db):
    """Every line manager's {id: row(id, email, left_at)} in ONE query, for a run to hand to reminder_lm_cc."""
    return {r["id"]: r for r in db.execute("SELECT id, email, left_at, bgceo_bg FROM users WHERE id IN "
                                           "(SELECT manager_id FROM users WHERE manager_id IS NOT NULL)")}


def reminder_cc_chair_id(db):
    """The Executive Chairman's users.id as STORED (app_settings exec_chair_id), or None when unset or unreadable. Read
    straight from the setting, never through _chair_state: the line-manager copy must never reach him whether or not
    ONEHR_CHAIR is on (Chris, 2026-11-07)."""
    r = db.execute("SELECT value FROM app_settings WHERE key=?", (CHAIR_SETTING_ID,)).fetchone()
    try:
        return int(str(r[0]).strip()) if r and r[0] is not None else None
    except (TypeError, ValueError):
        return None


def reminder_lm_cc(db, u, items, lm=_LM_LOOKUP, on=None, off=None, chair=_LM_LOOKUP):
    """The line manager's email to copy on `u`'s Everyone's reminder, or None. None unless ALL hold: the setting is on; an
    item waiting is in group own or f360 (team, lead and gradeh items never count, a Grade H staff item folded in
    included); `u` has a manager_id; that manager has not left and has a work email (an @ in it, as gradeh_has_email);
    they are not opted out of Everyone's reminder; their address is not the person's own (case-insensitive); and they are
    neither the Executive Chairman (the stored seat, flag on or off) nor a BG CEO (a bgceo_bg), who are never copied
    (Chris, 2026-11-07; the person's own email still goes). `lm` = the manager's row when the run read the managers in one
    query (reminder_managers), `on` / `off` / `chair` = the setting, email_optout_ids(db, "reminder") and
    reminder_cc_chair_id(db) when the run read them once; any left out is read here (the recheck's one row)."""
    if not u or not _row_get(u, "manager_id"):
        return None
    if not any(i.get("group") in REMINDER_CC_GROUPS for i in (items or [])):
        return None
    if not (reminder_cc_lm_on(db) if on is None else on):
        return None
    if lm is _LM_LOOKUP:
        lm = db.execute("SELECT id, email, left_at, bgceo_bg FROM users WHERE id=?", (u["manager_id"],)).fetchone()
    if not lm or lm["left_at"]:
        return None
    if _row_get(lm, "bgceo_bg"):   # a BG CEO is never copied (2026-11-07)
        return None
    if lm["id"] == (reminder_cc_chair_id(db) if chair is _LM_LOOKUP else chair):   # nor the Executive Chairman
        return None
    addr = (lm["email"] or "").strip()
    if not gradeh_has_email(addr) or addr.lower() == (u["email"] or "").strip().lower():
        return None
    if lm["id"] in (email_optout_ids(db, "reminder") if off is None else off):
        return None
    return addr


def reminder_reasons(db, cyc, day, rules=None):
    """Why the reminder goes out on `day` (a date): [sentences], empty when it isn't a send day (or the rules are off).
    Two rules on the same day make one email: the reasons only explain it."""
    seen = set()
    return [w for _k, _c, w in reminder_why(db, cyc, day, rules) if not (w in seen or seen.add(w))]


def reminder_why(db, cyc, day, rules=None):
    """reminder_reasons' rule, kept structured: [(kind, cell, sentence)], kind 'open' | 'close' | 'every' | 'range' |
    'target' and cell the window cell it is about (None for a range or the target date). Email › Schedule reads it
    (email_plan), so the page and the sender never disagree about a send day."""
    rules = rules or reminder_rules()
    if not cyc or not rules["enabled"]:
        return []
    cid, out, any_dates, any_open = cyc["id"], [], False, False
    by_date = cycle_opens_by_date(db, cid)   # a part with no start date isn't open there (2026-10-19)
    f, t = _rm_date(rules.get("every_from")), _rm_date(rules.get("every_to"))
    every = rules["every_days"]
    gh_cid = gradeh_rm_active(db, cyc)   # Grade H's parts follow the rule only where Grade H runs on this cycle (2026-10-31) and its switch is on (2026-11-09)
    for cell in WINDOW_KEYS:
        if cell in GRADEH_CELL_KEYS and not gh_cid:
            continue   # elsewhere they are on the calendar only: no reminder follows them
        staff_cell = cell in GRADEH_STAFF_CELLS   # a Grade H staff part: the day it opens and the last calls, nothing repeated
        lead_cell = cell in GRADEH_LEAD_CELLS   # a Grade H leader's part (2026-11-06): its own three days, never the every-N rule
        days_before = GRADEH_LEAD_DAYS_BEFORE if lead_cell else rules["days_before"]
        mod = _REMINDER_CELL_MODULE.get(cell)
        if mod and not cycle_module_on(mod, db, cid):
            continue
        o_raw, c_raw = window_dates(db, cell, cid)
        o, c = _parse_when(o_raw), _parse_when(c_raw)
        any_dates = any_dates or bool(o or c)
        subj = _WINDOW_SUBJECT[cell]
        is_open = (bool(o) or not by_date) and (not o or o.date() <= day) and (not c or c.date() >= day)
        any_open = any_open or (is_open and not staff_cell and not lead_cell)
        if (rules["on_open"] or lead_cell) and o and o.date() == day:
            out.append(("open", cell, "%s opens" % subj))
        if lead_cell and cell in (GRADEH_CELL_HOD_POT, GRADEH_CELL_HOD_PERF, GRADEH_CELL_BUCEO) and is_open:
            fb = _gh_fallback(GRADEH_BU_FALLBACK if cell == GRADEH_CELL_BUCEO else GRADEH_HOD_FALLBACK, cid)
            if fb and (not o or fb > o) and _gh_first_send_day(fb, _rm_send_time(rules)) == day:
                out.append(("fallback", cell, "%s opens for those still waiting" % subj))   # the early-opening rule's last day
        if is_open and cell == "gradeh_ack":   # the earlier of the deemed deadline and the part's close, per person
            for n in sorted({(e - day).days for e in gradeh_ack_deadline_dates(db, cid)} & set(rules["days_before"])):
                out.append(("close", cell, "%s closes %s" % (subj, "today" if n == 0 else "tomorrow" if n == 1
                                                             else "in %d days" % n)))
        elif is_open and c and (c.date() - day).days in days_before:
            n = (c.date() - day).days
            out.append(("close", cell, "%s closes %s" % (subj, "today" if n == 0 else "tomorrow" if n == 1
                                                         else "in %d days" % n)))
        # every N days while each part is open, from its opening -- up to the range's last day when only that is set
        if not f and is_open and every and o and (day - o.date()).days > 0 and (day - o.date()).days % every == 0 \
                and (not t or day <= t) and not staff_cell and not lead_cell:
            out.append(("every", cell, "every %d days while %s is open" % (every, _lc_first(subj))))
    # ...or every N days across a date range, counted from its first day, while any part is open (Chris, 2026-10-19:
    # "from 1 Oct to 10 Oct to send out the employee reminder every day at 9am")
    if f and every and any_open and f <= day and (not t or day <= t) and (day - f).days % every == 0:
        out.append(("range", None, "%s %s" % ("every day" if every == 1 else "every %d days" % every, _rm_span(f, t))))
    if not any_dates and not by_date:   # a cycle with no part dates keeps the old rule: N days before its target date
        left = days_until_deadline(cyc, today=day)
        if left is not None and left in rules["days_before"]:
            out.append(("target", None, "%d day%s before %s's target date" % (left, "" if left == 1 else "s",
                                                                           cyc["name"])))
    return out


def _lc_first(s):
    """'The results check-in' -> 'the results check-in', but 'KPI setting' stays: for a reason inside a sentence."""
    return s if (not s or s[:2].isupper() or not s[0].isalpha()) else s[0].lower() + s[1:]


def reminder_next_send(db, cyc, today=None, horizon=90, now=None):
    """(date, reasons) of the next automatic send of EVERYONE'S REMINDER from today on, or (None, []). A candidate day is a send day
    of the regular reminder (a day only Grade H staff's own email goes on is Grade H's, gradeh_next_send), not a day it already went
    (reminder_auto_last: today's page said "Next: Mon 9 Nov" on the public holiday), today only while its send time is to come or
    within the grace hours of it, and not a skipped day (2026-11-09): the same reader the sender asks."""
    today = today or _today_myt()
    now = now or (_now_myt() if today == _today_myt() else datetime.combine(today, datetime.min.time()))
    rules = reminder_rules()
    send_t = _rm_send_time(rules)
    for i in range(horizon):
        d = today + timedelta(days=i)
        if not _email_day_open(now, d, send_t, "reminder_auto_last") or email_skip_row(db, "reminder", d):
            continue
        why = reminder_reasons(db, cyc, d, rules)
        if why and reminder_day_parts(db, cyc, d, rules)["regular"]:
            return d, why
    return None, []


# --- Email › Schedule (Chris, 2026-10-24: "merge reminder and email into email, and place them as a menu item on the left
# panel ... since this email eventually will serve all modules at any time (including learning)"; canvas
# [design canvas link removed], option A): what everyone's reminder sends, day by day ------------
_EMAIL_AUDIENCE = {"pm_setting": "Employees", "pm_results": "Employees", "tc_self": "Employees",
                   "idp_self": "Employees", "f360": "360 raters", "pm_setting_approve": "Line managers",
                   "pm_approve": "Line managers", "tc_approve": "Line managers", "idp_review": "Line managers",
                   "pm_hod": "HODs", "pot_hod": "HODs", "pm_buceo": "BU CEOs", "pot_buceo": "BU CEOs",
                   "tb_bgceo": "BG CEOs"}
_EMAIL_AUDIENCES = ("Employees", "360 raters", "Line managers", "HODs", "BU CEOs", "BG CEOs")


def _email_span(a, b):
    """'Mon 2 Nov', or 'Tue 3 – Sun 8 Nov' for a run of days (a month each side when they differ)."""
    if a == b:
        return _em_day(a)
    if a.month == b.month:
        return "%s %d – %s" % (a.strftime("%a"), a.day, _em_day(b))
    return "%s – %s" % (_em_day(a), _em_day(b))


def email_parts(db, cyc):
    """[{who, from, to}] for each audience with a dated part in the cycle (its module on): the earliest opening and the
    latest close among its cells. The Schedule's strip of who is asked when."""
    if not cyc:
        return []
    span = {}
    for cell in WINDOW_KEYS:
        if cell in GRADEH_CELL_KEYS:
            continue
        who, mod = _EMAIL_AUDIENCE.get(cell), _REMINDER_CELL_MODULE.get(cell)
        if not who or (mod and not cycle_module_on(mod, db, cyc["id"])):
            continue
        o, c = (_parse_when(x) for x in window_dates(db, cell, cyc["id"]))
        if not o or not c:
            continue
        a, b = span.get(who, (o, c))
        span[who] = (min(a, o), max(b, c))
    return [{"who": w, "span": _email_span(span[w][0].date(), span[w][1].date())} for w in _EMAIL_AUDIENCES if w in span]


def gradeh_no_email_count(db, day, rules=None):
    """How many Grade H staff would have something waiting on `day` and the day's rule would email, but have no work email
    (gradeh_has_email): reached by the bar on My Appraisal only. 0 where Grade H does not run."""
    cyc = active_cycle(db)
    cid = gradeh_rm_cid(db, cyc)
    if not cid:
        return 0
    rules = rules or reminder_rules()
    h, m = (int(x) for x in rules["send_time"].split(":"))
    at = datetime.combine(day, datetime.min.time()).replace(hour=h, minute=m)   # the case is asked as of that day's send time
    n = 0
    for p in db.execute("SELECT p.*, uu.email AS email FROM gradeh_people p JOIN users uu ON uu.id=p.user_id WHERE p.cycle_id=? "
                        "AND p.private_company=0 AND uu.left_at IS NULL AND uu.role!='admin'", (cid,)):
        if gradeh_has_email(p["email"]):
            continue
        case = gradeh_staff_case(db, p, cid, now=at)
        if case and gradeh_staff_due(db, cid, case, day, rules):
            n += 1
    return n


def gradeh_parts_line(db, cyc):
    """[{who, span}] for the Schedule's Grade H line (board E1): staff (the KPI achievement, then acknowledging), line managers,
    HODs and BU CEOs, each with the dates of its part, only the dated ones. [] where Grade H does not run."""
    if not gradeh_rm_cid(db, cyc):
        return []

    def span(*cells):
        got = [(_parse_when(o), _parse_when(c)) for o, c in (window_dates(db, x, cyc["id"]) for x in cells)]
        got = [(o, c) for o, c in got if o and c]
        return _email_span(min(o for o, _c in got).date(), max(c for _o, c in got).date()) if got else ""
    kpi, ack = span("gradeh_kpi"), span("gradeh_ack")
    staff = ", ".join(x for x in (("KPI " + kpi) if kpi else "", ("acknowledge " + ack) if ack else "") if x)
    out = [{"who": "Grade H staff", "span": staff}, {"who": "Line managers", "span": span("gradeh_lm")},
           {"who": "HODs", "span": span("gradeh_hod_pot", "gradeh_hod_perf")}, {"who": "BU CEOs", "span": span("gradeh_buceo")}]
    return [x for x in out if x["span"]]


# Grade H on Email › Schedule (2026-10-31, board E1): the words each Grade H part gets on a send day, who it reaches, and the
# staff chip. Used only where Grade H runs on the cycle; the rest of the page never sees them.
GRADEH_STAFF_CHIP = "Grade H reminder \u00b7 BM / EN"
_GH_PLAN_OPEN = {"gradeh_kpi": "the KPI achievement", "gradeh_lm": "the line manager appraisal", "gradeh_ack": "acknowledging",
                 "gradeh_hod_pot": "the HOD potential review", "gradeh_hod_perf": "the HOD performance review",
                 "gradeh_buceo": "calibration and sign-off"}
_GH_PLAN_OPEN_WHO = {"gradeh_kpi": "Grade H staff on the KPI route", "gradeh_lm": "their line managers",
                     "gradeh_ack": "Grade H staff whose appraisal is in", "gradeh_hod_pot": "HODs", "gradeh_hod_perf": "HODs",
                     "gradeh_buceo": "BU CEOs"}
_GH_PLAN_CLOSE = {"gradeh_kpi": ("Grade H KPI achievement", True), "gradeh_lm": ("Grade H appraisals", False),
                  "gradeh_hod_pot": ("the Grade H potential review", True), "gradeh_hod_perf": ("the Grade H performance review", True),
                  "gradeh_buceo": ("Grade H sign-off", True)}   # (the noun, singular)
_GH_PLAN_PLURAL = tuple(v[0] for v in _GH_PLAN_CLOSE.values() if not v[1])   # nouns that take "close", not "closes"
_GH_PLAN_CLOSE_WHO = {"gradeh_kpi": "Only those with something still waiting", "gradeh_lm": "Line managers with someone still to submit",
                      "gradeh_ack": "Grade H staff not yet acknowledged", "gradeh_hod_pot": "HODs with something still to sign off",
                      "gradeh_hod_perf": "HODs with something still to sign off", "gradeh_buceo": "Only those with something still waiting"}


def _gh_plan_open_words(cells):
    """'Grade H: the KPI achievement and the line manager appraisal open' for the Grade H cells that open the same day, in
    the calendar's order; the HOD's two reviews read as one when both open."""
    cells = [c for c in GRADEH_CELL_KEYS if c in cells]
    both = "gradeh_hod_pot" in cells and "gradeh_hod_perf" in cells
    nouns = []
    for c in cells:
        if c == "gradeh_hod_perf" and both:
            continue
        nouns.append("the HOD potential and performance reviews" if (c == "gradeh_hod_pot" and both) else _GH_PLAN_OPEN[c])
    lst = nouns[0] if len(nouns) == 1 else ", ".join(nouns[:-1]) + " and " + nouns[-1]
    return "Grade H: %s %s" % (lst, "open" if len(nouns) > 1 or both else "opens")


def _gh_plan_fallback_words(cells):
    """(words, who) for the Grade H leader parts that open on their fallback day for those still waiting (reminder_why's 'fallback'
    entries: the early-opening rule's last day): ("", "") with none."""
    bits, who = [], []
    if any(c in (GRADEH_CELL_HOD_POT, GRADEH_CELL_HOD_PERF) for c in cells):
        bits.append("the HOD reviews open for HODs still waiting on acknowledgements")
        who.append("HODs still waiting")
    if GRADEH_CELL_BUCEO in cells:
        bits.append("sign-off opens for BU CEOs whose HODs have not all finished")
        who.append("BU CEOs still waiting")
    return ("Grade H: " + "; ".join(bits)) if bits else "", "; ".join(who)


def _gh_plan_close_words(db, cid, why, d, rules):
    """([clauses], [who]) for the Grade H parts that close or fall due on day `d`, from reminder_why's entries: one clause
    for each number of days left ("Grade H KPI achievement closes in 3 days"), and acknowledging named by the earlier of the
    deemed deadline and the part's close ("Acknowledge by Fri 11 Dec, 23:59, or it counts as agreed"). ([], []) with none."""
    by_n, bits, whos = {}, [], []
    for k, c, _w in why:
        if k != "close" or c not in GRADEH_CELL_KEYS:
            continue
        whos.append(_GH_PLAN_CLOSE_WHO[c])
        if c == "gradeh_ack":
            for n in sorted({(e - d).days for e in gradeh_ack_deadline_dates(db, cid)} & set(rules["days_before"])):
                bits.append("Acknowledge by %s, 23:59%s" % (_em_day(d + timedelta(days=n)),
                                                            ", or it counts as agreed" if gradeh_deemed_on(cid) else ""))
        else:
            n = (_parse_when(window_dates(db, c, cid)[1]).date() - d).days
            by_n.setdefault(n, []).append(_GH_PLAN_CLOSE[c][0])
    out = []
    for n in sorted(by_n):
        subs = list(dict.fromkeys(by_n[n]))
        out.append("%s close%s %s" % (subs[0] if len(subs) == 1 else ", ".join(subs[:-1]) + " and " + subs[-1],
                                      "s" if len(subs) == 1 and subs[0] not in _GH_PLAN_PLURAL else "",
                                      "that day" if n == 0 else "the next day" if n == 1 else "in %d days" % n))
    return out + bits, list(dict.fromkeys(whos))


def email_plan(db, cyc, rules=None, today=None, horizon=120):
    """Everyone's reminder day by day, from today until the last part closes: [{frm, to, day, kind, who, words, tpl,
    dated}], read from reminder_why with the switch taken as on (whether it really goes out is said apart, from
    rules['enabled']). Plain repeat days in a row with the same template fold into one row; a day a part opens stands
    alone. `tpl` is the template that day uses (Email › Emails and templates), `dated` when it isn't the usual one."""
    if not cyc:
        return []
    rules = dict(rules or reminder_rules(), enabled=True)
    today = today or _today_myt()
    gh = bool(gradeh_rm_active(db, cyc))   # Grade H runs on this cycle, its switch on: its parts are in the plan too (2026-10-31)
    closes = [_parse_when(window_dates(db, c, cyc["id"])[1]) for c in WINDOW_KEYS if gh or c not in GRADEH_CELL_KEYS]
    last = min(max([c.date() for c in closes if c] or [today]), today + timedelta(days=horizon))
    if gh:   # the acknowledge part's deadlines (a deemed date can fall before or after the part's own close)
        last = min(max([last] + gradeh_ack_deadline_dates(db, cyc["id"])), today + timedelta(days=horizon))
    tpls = email_tpl_rows(db, "reminder")
    days, d = [], today
    while d <= last:
        why = reminder_why(db, cyc, d, rules)
        if why:
            opens = [c for k, c, _w in why if k == "open"]
            closing = [w for k, _c, w in why if k in ("close", "target")]
            fbw, fbwho = _gh_plan_fallback_words([c for k, c, _w in why if k == "fallback"])   # the early-opening rule's last day
            reg_opens = [c for c in opens if c not in GRADEH_CELL_KEYS]
            gh_opens = [c for c in opens if c in GRADEH_CELL_KEYS]
            if opens:
                kind = "open"
                who = _lc_join(sorted({_EMAIL_AUDIENCE.get(c, "Everyone") for c in reg_opens},
                                      key=lambda w: _EMAIL_AUDIENCES.index(w) if w in _EMAIL_AUDIENCES else 9))
                subs = list(dict.fromkeys(_lc_first(_WINDOW_SUBJECT[c]) for c in reg_opens))   # the HOD's two parts: one name
                words = (_lc_join(subs) + (" open" if len(subs) > 1 else " opens")) if subs else ""
                if gh_opens:
                    gw = list(dict.fromkeys(_GH_PLAN_OPEN_WHO[c] for c in gh_opens))
                    who = "; ".join(x for x in (who, "; ".join(gw)) if x)
                    words = "; ".join(x for x in (words, _gh_plan_open_words(gh_opens)) if x)
                gcb, gcw = _gh_plan_close_words(db, cyc["id"], why, d, rules)   # the Grade H calls that fall on an opening day too
                if gcb:
                    words = "; ".join([words] + gcb) if words else gcb[0][:1].upper() + "; ".join(gcb)[1:]
                    who = "; ".join(x for x in [who] + gcw if x)
                if fbw:
                    words, who = "; ".join(x for x in (words, fbw) if x), "; ".join(x for x in (who, fbwho) if x)
            elif closing:   # one clause a closing day, said of that day, not of today
                kind, who = "close", "Only those with something still waiting"
                by_n, bits = {}, [w for k, _c, w in why if k == "target"]
                for k, c, _w in why:
                    if k == "close" and c not in GRADEH_CELL_KEYS:
                        n = (_parse_when(window_dates(db, c, cyc["id"])[1]).date() - d).days
                        by_n.setdefault(n, []).append(_lc_first(_WINDOW_SUBJECT[c]))
                for n in sorted(by_n):
                    subs = list(dict.fromkeys(by_n[n]))
                    bits.append("%s close%s %s" % (
                        subs[0] if len(subs) == 1 else ", ".join(subs[:-1]) + " and " + subs[-1],
                        "s" if len(subs) == 1 else "", "that day" if n == 0 else "the next day" if n == 1
                        else "in %d days" % n))
                gcb, gcw = _gh_plan_close_words(db, cyc["id"], why, d, rules)
                bits += gcb
                words = "; ".join(bits)
                words = words[:1].upper() + words[1:]
                if gcw:   # Grade H's own words for who is reached (a day with two parts closing names both)
                    who = "; ".join(dict.fromkeys(gcw))
                if fbw:
                    words, who = words + "; " + fbw[:1].lower() + fbw[1:], "; ".join(x for x in (who, fbwho) if x)
            elif fbw:   # only the early-opening rule's last day: the part opens for those it was still waiting on
                kind, words, who = "open", fbw, fbwho
            else:
                every = max(rules["every_days"], 1)
                kind, who = "every", "Only those with something still waiting"
                words = ("Every day" if every == 1 else "Every %d days" % every) + " while a part is open"
            regular = any(c not in GRADEH_STAFF_CELLS for _k, c, _w in why)   # Everyone's reminder goes that day
            tpl = email_tpl_pick(tpls, d)
            days.append({"frm": d, "to": d, "kind": kind, "who": who, "words": words,
                         "tpl": tpl["name"] if tpl else None, "dated": bool(tpl and not tpl["usual"]),
                         "regular": regular, "gh_staff": any(c in GRADEH_STAFF_CELLS for _k, c, _w in why),
                         "gh": any(c in GRADEH_CELL_KEYS for _k, c, _w in why)})
        d += timedelta(days=1)
    rows = []
    for r in days:
        p = rows[-1] if rows else None
        if p and r["kind"] == p["kind"] == "every" and r["tpl"] == p["tpl"] \
                and (r["frm"] - p["to"]).days <= max(rules["every_days"], 1):
            p["to"] = r["frm"]
            continue
        rows.append(r)
    for r in rows:
        r["day"] = _email_span(r["frm"], r["to"])
    return rows


def email_glance(db, plan, rules=None):
    """The Schedule's side card for the plan's first send day: {day, time, tpl, people, waves, first, last}. people is
    everyone the reminder could reach (reminder_people's rule, counted): who really gets it is decided as it sends."""
    if not plan:
        return None
    rules = rules or reminder_rules()
    n = db.execute("SELECT COUNT(*) FROM users WHERE role!='admin' AND left_at IS NULL AND "
                         "COALESCE(is_demo,0)=0").fetchone()[0]
    plan_w = email_wave_plan(n)
    h, m = (int(x) for x in rules["send_time"].split(":"))
    last = datetime(2000, 1, 1, h, m) + timedelta(minutes=plan_w["last_min"])
    first = plan[0]
    # Grade H's staff email that day, and how many of those it can reach only by the bar (no work email): board E1's amber row
    gh_no_email = gradeh_no_email_count(db, plan[0]["frm"], rules) if first.get("gh_staff") else 0
    return {"day": plan[0]["day"], "first": _em_day(plan[0]["frm"]), "time": rules["send_time"],
            "tpl": plan[0]["tpl"], "dated": plan[0]["dated"],
            "people": n, "waves": plan_w["waves"], "last": last.strftime("%H:%M"),
            "wave_rule": plan_w["rule"], "gh_staff": bool(first.get("gh_staff")), "regular": first.get("regular", True),
            "gh_no_email": gh_no_email}


# --- the email -----------------------------------------------------------------
# The super admin edits every word of it (canvas board Main): subject, heading, greeting, opening, the four section
# names, the button, the closing line and the footer, with placeholders. Each item's own line (what is waiting, how
# many, when it closes) is written by OneHR from what is really open, so it can't go stale. Kept as one JSON value in
# app_settings ('reminder_template'); the older subject / opening keys still count until it is saved.
REMINDER_PLACEHOLDERS = ("display_name", "first_name", "full_name", "count", "things", "cycle", "closes", "days_left",
                        "tasks")
REMINDER_TPL_FIELDS = (   # (key, label, ceiling, required)
    ("subject", "Subject", 200, True), ("heading", "Heading", 120, True), ("greeting", "Greeting", 80, True),
    ("button", "Button", 40, True), ("opening", "Opening", 500, False),
    ("sec_f360", "360 feedback", 40, True), ("sec_team", "Your team", 40, True), ("sec_own", "Your own review", 40, True),
    ("sec_lead", "What you lead", 40, True), ("closing", "Closing line", 300, False), ("footer", "Footer", 500, False))
REMINDER_TPL_DEFAULT = {   # the daily reminder Chris approved on 2026-10-24 (Launch Comms/Email wording drafts, 1b)
    "subject": DEFAULT_REMINDER_ALL_SUBJECT,
    "heading": "{count} {things} still waiting on you",
    "greeting": "Hi {display_name},",
    "button": "Continue in AI+ OneHR",
    "opening": _REMINDER_OPENING_COUNTDOWN,   # DEFAULT_REMINDER_ALL_OPENING + the deadline line (Chris, 4 Nov 2026)
    "sec_f360": "360 feedback you give", "sec_team": "Your team's reviews", "sec_own": "Your own check-in",
    "sec_lead": "What you lead",
    "closing": "Your AI agent picks up where you left off. Check your results before you press Save & submit, because "
               "a submitted part is final.",
    "footer": "You get this because these parts are open and waiting on you. AI+ OneHR sends at most one reminder a "
              "day. Need help? Open Get Help in the account menu at the top right of AI+ OneHR, or write to Group "
              "People at group.people@example.com.",
}


def reminder_template():
    """Every word of the reminder today: the template in use (Cycle > Emails, 2026-10-24), else the older saved words
    over the defaults."""
    return email_tpl_words("reminder")


def reminder_words():
    """(subject, opening): the two words the older page edited."""
    t = reminder_template()
    return t["subject"], t["opening"]


def reminder_template_from(form, base=None):
    """(template, errors) from a posted form over `base` (the words in use), by _tpl_words_from's rules."""
    return _tpl_words_from(form, REMINDER_TPL_FIELDS, REMINDER_PLACEHOLDERS, base or reminder_template(),
                           ("opening", "footer", "closing"))


def _tpl_fill(text, vals):
    return re.sub(r"\{(\w+)\}", lambda m: vals.get(m.group(1), m.group(0)), text or "")


def _reminder_fill(text, u, items, cyc, db=None):
    """A template line with its placeholders filled for `u` (kept for the older callers)."""
    return _tpl_fill(text, _reminder_vals(db or get_db(), u, items, cyc))


def _reminder_vals(db, u, items, cyc):
    n = len(items)
    dated = sorted(i["closes_on"] for i in items if i.get("closes_on"))
    # days_left follows the email's "Closes first" callout: left = days from today (MYT) to the earliest closing date;
    # "N+1 days left" while left > 0, "Last day" at 0 or less; no dated item reads "Reminder" so a subject still makes sense
    left = _reminder_days_left(dated[0]) if dated else None
    days_left = "Reminder" if left is None else ("%d days left" % left) if left > 0 else "Last day"
    return dict(email_names(db, u), count=str(n), things="thing is" if n == 1 else "things are",
                cycle=cyc["name"] if cyc else "", closes=_em_day(dated[0]) if dated else "", days_left=days_left,
                tasks="1 thing" if n == 1 else "%d things" % n)


# --- The HOD's reminder carries where their line managers stand (Chris, 2026-11-12: "1: Progress in reminder", canvas
# [design canvas link removed] boards E2 and E3) ----------------------------------------------------
_REM_HOD_CELLS = ("pm_approve", "tc_approve")
_REM_HOD_WAVE = {"key": None, "at": 0.0, "val": None}   # the send-time recheck's context, shared for a few minutes
_REM_HOD_WAVE_TTL = 300


def reminder_hod_progress(db, cyc, only=None):
    """The figures behind the HOD's reminder block, worked out ONCE for everyone: {'by_hod': {HOD user id: [section dicts]},
    'open': line managers' parts open now, 'closes': the latest close of the open ones (date or None), 'open_parts':
    [(part, closes)] the table's columns}. The leader progress email's own path (lp_counts, lp_hods, lp_hod_teams,
    _lp_hod_section), over parts pm_approve / tc_approve. Nobody the super admin took off Leader progress is in it, nor the
    Executive Chairman. `only` = user ids to keep (a preview): the counts are still the population's. Counts only."""
    out = {"by_hod": {}, "open": False, "closes": None, "open_parts": []}
    if not cyc:
        return out
    is_open, closes = _lp_cells_state(db, cyc, _REM_HOD_CELLS)
    out["open"], out["closes"] = is_open, closes
    cid, used = cyc["id"], set(_cycle_cells_used(cyc))
    out["open_parts"] = [(LP_PART[k], _reminder_close_date(db, (LP_PART[k][4],), cid)) for k in _REM_HOD_CELLS
                         if LP_PART[k][4] in used and cycle_module_on(LP_PART[k][5], db, cid)
                         and window_state(db, LP_PART[k][4], cid) == "open"]
    hods = lp_hods(db)
    if only is not None:
        hods = [x for x in hods if x[0]["id"] in only]
    off, chair = email_optout_ids(db, "leader_progress"), chair_user_id(db)
    hods = [x for x in hods if x[0]["id"] not in off and x[0]["id"] != chair]
    if not hods:
        return out
    counts = lp_counts(db, cyc, list(_REM_HOD_CELLS))
    counts["_hodteams"], counts["_mgr"] = lp_hod_teams(db, counts, [u["id"] for u, _s in hods])
    keys = list(_REM_HOD_CELLS)
    for u, scopes in hods:
        secs = []
        for sc in scopes:
            sec, nt, nd = _lp_hod_section_n(sc, counts, keys)
            if sec:
                secs.append(dict(sec, teams=nt, teams_done=nd))
        names = {}
        for sec in secs:
            names[sec["name"]] = names.get(sec["name"], 0) + 1
        for sec in secs:   # the same department name in two companies: told apart by the company
            if names[sec["name"]] > 1 and sec["co"]:
                sec["name"] = "%s (%s)" % (sec["name"], display_company(sec["bg"], sec["co"]))
        if secs:
            out["by_hod"][u["id"]] = secs
    return out


def _reminder_hod_wave_ctx(db, cyc):
    """The context for the send-time recheck: worked out again for a few minutes' worth of rechecks (a wave), never once a row."""
    key = (cyc["id"] if cyc else None, _today_myt())
    c = _REM_HOD_WAVE
    if c["key"] != key or time.time() - c["at"] > _REM_HOD_WAVE_TTL or c["val"] is None:
        c.update(key=key, at=time.time(), val=reminder_hod_progress(db, cyc))
    return c["val"]


def _reminder_hod_lazy(db, cyc, wave=False):
    """A zero-argument reader of the context that works it out the first time it is asked (so a run with no HOD in it reads
    nothing) and remembers it. `wave`: the recheck's shared one."""
    box = []

    def get():
        if not box:
            box.append(_reminder_hod_wave_ctx(db, cyc) if wave else reminder_hod_progress(db, cyc))
        return box[0]
    return get


def _reminder_hod_block_html(sec, closes, open_parts):
    """One department's box under the HOD's Department review line (canvas E2 / E3): still working while the line managers'
    parts are open and a team is left; 'every line manager has finished' once all are done."""
    done = sec["all_done"]
    bd, ac, kc = ("#b9dcc8", "#1f7a4d", "#1f7a4d") if done else ("#c9cde3", "#252A59", "#5f6678")
    if done:
        title = "Every line manager has finished"
        line = ("All %d team%s %s finished KPI moderation and Competency review. You can start your Department Review now."
                % (sec["teams"], "" if sec["teams"] == 1 else "s", "has" if sec["teams"] == 1 else "have"))
        table = _ready_hod_table_html({"name": sec["name"], "teams": sec["teams"], "people": sec["people"],
                                       "total": sec["total"], "kind": "hod"}, stacked=True)
    else:
        title = "Your line managers: %d of %d teams done" % (sec["teams_done"], sec["teams"])
        line = ("Line managers moderate KPIs and review competencies%s. A team still in progress can change what you review, "
                "so check where each one stands first." % ((" until %s" % _em_day(closes)) if closes else ""))
        table = _lp_table_html(sec, open_parts, "Line manager's team", stacked=True)
    return ('<table role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" bgcolor="#ffffff" '
            'class="oh-box" style="margin:0 0 6px;background:#ffffff;border:1px solid %s;border-left:4px solid %s;'
            'border-radius:10px;border-collapse:separate"><tr><td style="padding:14px 16px 4px">'
            '<span style="font:800 11px/1.3 %s;letter-spacing:.08em;color:%s;text-transform:uppercase">%s &middot; %s</span><br>'
            '<span class="oh-t1" style="font:700 15.5px/1.4 %s;color:#252A59">%s</span><br>'
            '<span class="oh-mut" style="font:13px/1.5 %s;color:#5f6678">%s</span>'
            '<div style="height:12px;line-height:12px;font-size:1px">&nbsp;</div>%s</td></tr></table>'
            % (bd, ac, _EM_FONT, kc, "Ready for you" if done else "Before you start", _em_esc(sec["name"]), _EM_FONT,
               _em_esc(title), _EM_FONT, _em_esc(line), table))


def _reminder_hod_apply(db, u, items, cyc, ctx):
    """(items, {item index: block html}) for the HOD's email: their Department review line (group 'lead', role 'hod') gets
    "· 2 of 6 line managers' teams done" / "· every line manager is done" on its detail and one box a department under it.
    A department gets a box while the line managers' parts are open (still working, or all done), or, once they closed, only
    when every team finished. Nothing for someone with no such line, someone off Leader progress, the Chairman, or a
    department with nobody to count. Only the email: reminder_items (the dashboard, the bar) is not touched."""
    idx = [n for n, i in enumerate(items) if i.get("group") == "lead" and i.get("role") == "hod"]
    if not idx or not ctx:
        return items, {}
    ctx = ctx() if callable(ctx) else ctx
    secs = ctx["by_hod"].get(u["id"])
    if not secs or not cyc:
        return items, {}
    shown = [s_ for s_ in secs if ctx["open"] or s_["all_done"]]
    if not shown:
        return items, {}
    teams, done = sum(s_["teams"] for s_ in secs), sum(s_["teams_done"] for s_ in secs)
    if not ctx["open"] and len(shown) < len(secs):   # closed and some department unfinished: no word on the line that could mislead
        suffix = ""
    elif all(s_["all_done"] for s_ in secs):
        suffix = "every line manager is done"
    else:
        suffix = "%d of %d line managers' teams done" % (done, teams)
    out = list(items)
    n = idx[0]
    if suffix:
        out[n] = dict(out[n], detail=" · ".join(x for x in (out[n].get("detail"), suffix) if x))
    return out, {n: "".join(_reminder_hod_block_html(s_, ctx["closes"], ctx["open_parts"]) for s_ in shown)}


def reminder_mail(u, items, cyc, tpl=None, db=None, hod_ctx=None):
    """(subject, html) of one person's reminder (board E): the heading and when the first part closes, the greeting
    and opening, "Closes first" with the days left (two or more items), their items under the section names, each
    with its countdown chip, the button and the closing line. Every link is absolute."""
    db = db or get_db()
    t = tpl or reminder_template()
    blocks = {}
    if any(i.get("group") == "lead" and i.get("role") == "hod" for i in items):
        # an HOD's Department review line says where their line managers stand (2026-11-12). `hod_ctx`: the run's figures
        # (a dict, or a reader that works them out on first use); none = worked out for this one email (a preview, a test send)
        try:
            items, blocks = _reminder_hod_apply(db, u, items, cyc, hod_ctx if hod_ctx is not None
                                                else (lambda: reminder_hod_progress(db, cyc, only={u["id"]})))
        except Exception:   # noqa: BLE001 -- the reminder still goes, as it was
            db.rollback()
            blocks = {}
    vals = _reminder_vals(db, u, items, cyc)
    fill = lambda k: _tpl_fill(t[k], vals)   # noqa: E731
    base = app_base_url()
    today = _today_myt()
    dated = sorted((i for i in items if i.get("closes_on")), key=lambda i: i["closes_on"])
    first = dated[0] if dated else None
    sub = ""
    if first:
        left = (first["closes_on"] - today).days
        k = _reminder_days_left(first["closes_on"], today)
        sub = ("The first closes today." if left <= 0 else
               "The first closes tomorrow, %s: %d days left." % (_em_day(first["closes_on"]), k) if left == 1 else
               "The first closes on %s: %d days left." % (_em_day(first["closes_on"]), k))
    body = [_em_greet(fill("greeting"))]
    if fill("opening"):
        body.append(_em_p(_em_esc(fill("opening"))))
    if first and len(items) > 1:
        left = (first["closes_on"] - today).days
        k = _reminder_days_left(first["closes_on"], today)
        body.append(_em_callout(
            "Closes first", first["text"], " · ".join(x for x in (first.get("detail"), _em_day(first["closes_on"])) if x),
            str(k) if k > 0 else "Today", "days left" if k > 0 else "last day",
            "r" if left <= 0 else "w" if left <= 3 else ""))
    for key, _label in REMINDER_GROUPS:
        mine = [i for i in items if i["group"] == key]
        if not mine:
            continue
        body.append(_em_label(t.get("sec_" + key) or _label))
        for i in mine:
            chip = _em_chip(*_em_left(i["closes_on"], today)) if i.get("closes_on") else ""
            body.append(_em_row(i["text"], base + (i["url"] or "/"), i.get("detail") or "", chip))
            at = next((n for n, x in enumerate(items) if x is i), None)
            if at in blocks:
                body.append(blocks[at])
    tail = _em_p(_em_esc(fill("closing")), gap=12) if fill("closing") else ""
    return fill("subject"), onehr_email(fill("heading"), "".join(body), button=(fill("button"), base + url_for("dashboard")),
                                        sub=sub, cycle=vals["cycle"], footer=fill("footer"), after_html=tail)


# --- who, and the send ----------------------------------------------------------
def reminder_people(db, me=None):
    """Everyone a reminder could go to (active, real, not an admin), in `me`'s scope when given. In business group,
    unit and department order (2026-10-21), so the waves keep a team's emails together."""
    where, params = bg_scope(me, "business_group") if me else ("", [])
    return db.execute("SELECT * FROM users WHERE role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0" + where
                      + " ORDER BY COALESCE(business_group,''), COALESCE(company,''), COALESCE(department,''), id",
                      list(params)).fetchall()


def reminder_send(db, cyc, people, why, actor_id=None, live=True, test_to=None, limit=0, rate=0, log=None, regular=True,
                  gh_staff=None, honour_skips=False):
    """Each person's email of their own items (the runner and Send now both come here). Live, it is QUEUED in the
    outbox in waves (2026-10-21, email_wave_rules: the first wave now, then one every N minutes) for the sender to send
    at 30 a minute, never sent here; a redirected test (test_to) still sends now, and the dry run only logs. Skips:
    nothing waiting, no email on file, emailed or queued within the cooldown (unless test_to). Each skip and test send
    goes in the notifications log (the outbox logs its own sends); the run's totals go in the activity log as
    'reminder_run'. Returns {sent, failed, skipped, nothing, dry, queued, waves}. Where Grade H runs on the cycle
    (2026-10-31) a Grade H person's own email is in the same pass: gh_staff 'day' = to those whose day it is under the
    rules, 'all' = to everyone with something waiting (Send now), None = none; regular False = no Everyone's reminder
    (a day only the staff's own email goes on). One email a person: a Grade H person who also has leader items gets their
    own item inside that email, and no second one. The Grade H switch (gradeh_mail_ok) holds for every send: off, no Grade H person's own
    email and no Grade H lines in anyone's (2026-11-09). `honour_skips`: the automatic run honours a skip of the Grade H reminders
    (the lines and the staff emails go nowhere that day); Send now does not (an explicit act)."""
    tally = {"sent": 0, "failed": 0, "skipped": 0, "nothing": 0, "dry": 0, "queued": 0, "waves": 0, "opted_out": 0}
    queue = live and not test_to
    token = mailer.get_token() if live and not queue else None
    interval = 60.0 / rate if (live and rate and not queue) else 0
    rules, start = email_wave_rules(), _utc_now()
    batch = ("reminder-" + secrets.token_hex(6)) if queue else None
    cc_on = not test_to and reminder_cc_lm_on(db)   # the line manager on cc (2026-11-06): never on a redirected test
    mgrs = reminder_managers(db) if cc_on else {}   # every line manager in ONE query, only when the copy is on
    cc_chair = reminder_cc_chair_id(db) if cc_on else None   # the Executive Chairman's id, read once (never copied)
    hod_ctx = _reminder_hod_lazy(db, cyc)   # the HODs' line-manager figures: worked out once, at the first HOD of the run
    tpl = reminder_template()   # the template in use today (Cycle > Emails), read once for the whole run
    gh = {}   # Grade H people by user id, only where Grade H runs on the cycle: one read for the whole run
    if gradeh_mail_ok(db, cyc, honour_skips=honour_skips):
        gh = {r["user_id"]: r for r in db.execute("SELECT * FROM gradeh_people WHERE cycle_id=? AND private_company=0 AND "
                                                  "user_id IS NOT NULL", (cyc["id"],))}
    gh_tpl, gh_day, gh_rules = (email_tpl_words(GRADEH_REMINDER_KIND, db=db), _today_myt(), reminder_rules()) if gh else (None,) * 3
    off = email_optout_ids(db, "reminder")   # the people the super admin took off this email, read once per run
    done = 0
    for u in people:
        items = reminder_items_email(db, u, honour_skips=honour_skips) if regular else []   # regular False: a day only Grade H staff's own email is sent on
        staff = None   # a Grade H person's OWN email (no leader items to carry it): the case, in their language
        case = gradeh_staff_case(db, gh[u["id"]], cyc["id"]) if gh and u["id"] in gh else None
        if case and items:
            items = items + [_gradeh_staff_item(case)]   # ONE email: their own item goes in the one they already get
        elif case and (gh_staff == "all" or (gh_staff == "day" and gradeh_staff_due(db, cyc["id"], case, gh_day, gh_rules))):
            staff = case
        if not items and not staff:
            tally["nothing"] += 1
            continue
        if u["id"] in off and (items or staff) and not test_to:   # a redirected test goes to the admin's own address, so it still goes; Everyone's reminder also stops a Grade H person's own email (staff, no items; Chris 2026-11-03)
            log_notification(db, cyc["id"], u["id"], u["email"], "skipped", len(items) if items else 1, "opted out",
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["opted_out"] += 1
            continue
        n_wait = len(items) if items else 1
        if not (gradeh_has_email(u["email"]) if staff else (u["email"] or "").strip()) and not test_to:
            log_notification(db, cyc["id"], u["id"], None, "skipped", n_wait, "no email on file",
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["skipped"] += 1
            continue
        if not test_to and (gradeh_reminder_in_cooldown(db, u["id"], cyc["id"]) if staff
                            else reminder_in_cooldown(db, u["id"], cyc["id"])):
            # logged so Email › Sent can name them (2026-11-03); a 'skipped' row is never read by the cooldown (status 'sent' only)
            log_notification(db, cyc["id"], u["id"], u["email"], "skipped", n_wait, REMINDER_COOLDOWN_WHY,
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["skipped"] += 1
            continue
        if limit and done >= limit:
            break
        done += 1
        to = test_to or u["email"]
        kind = GRADEH_REMINDER_KIND if staff else REMINDER_KIND
        if staff:
            lang = gh[u["id"]]["language"] if gh[u["id"]]["language"] in GRADEH_LANGS else "bm"
            subject, body = _gradeh_reminder_mail(db, u, lang, staff, cyc["name"], tpl=gh_tpl)
        else:
            subject, body = reminder_mail(u, items, cyc, tpl=tpl, db=db, hod_ctx=hod_ctx)
        cc = None if (staff or not cc_on) else reminder_lm_cc(db, u, items, lm=mgrs.get(_row_get(u, "manager_id")),
                                                              on=True, off=off, chair=cc_chair)
        if not live:
            log_notification(db, cyc["id"], u["id"], u["email"], "dryrun", n_wait, why[:300],
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["dry"] += 1
            if log:
                log("  would email %s (%d waiting%s%s)" % (u["employee_id"] or u["id"], n_wait,
                                                           ", Grade H staff, " + gh[u["id"]]["language"] if staff else "",
                                                           ", cc line manager" if cc else ""))
            continue
        if queue:   # one short write per person: the loop's reading never holds the database's write lock
            _outbox_add(db, kind, to.strip(), subject, body, user_id=u["id"], cycle_id=cyc["id"],
                        detail=why[:300], actor_id=actor_id, send_after=_email_wave_at(tally["queued"], rules, start),
                        batch=batch, cc_email=cc)
            db.commit()
            tally["queued"] += 1
            continue
        try:
            mailer.send_mail(to, subject, body, token=token)
            log_notification(db, cyc["id"], u["id"], to, "sent", n_wait,
                             ("redirected test; " if test_to else "") + why[:280],
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["sent"] += 1
        except mailer.MailerError as e:
            log_notification(db, cyc["id"], u["id"], to, "failed", n_wait, str(e)[:300],
                             kind=GRADEH_REMINDER_KIND if staff else None)
            tally["failed"] += 1
        if interval:
            time.sleep(interval)
    if queue:
        plan = email_wave_plan(tally["queued"], rules)
        tally["waves"] = plan["waves"]
        if log:
            log("  queued %d %s" % (tally["queued"], plan["text"] or "(nobody new)"))
        log_activity(db, actor_id, "reminder_run", "%s | %d queued%s | %d skipped%s%s" % (
            why[:200], tally["queued"], (" " + plan["text"]) if plan["text"] else "", tally["skipped"],
            (" | %d opted out" % tally["opted_out"]) if tally["opted_out"] else "",
            (" | batch %s" % batch) if tally["queued"] else ""))   # the batch key: Email › Sent opens the run's people by it
        if tally["queued"]:
            _outbox_kick()
        return tally
    log_activity(db, actor_id, "reminder_run", "%s | %d sent | %d failed | %d skipped%s%s" % (
        why[:200], tally["sent"], tally["failed"], tally["skipped"], (" | %d dry run" % tally["dry"]) if tally["dry"]
        else "", (" | %d opted out" % tally["opted_out"]) if tally["opted_out"] else ""))
    return tally


def _run_log_rows(db, action, limit, run_id=None, since=None, until=None):
    """The activity rows of one run kind, newest first: [id, created_at, detail]. run_id = that one run; since / until = a window of
    UTC stored times (>= since, < until), which the email calendar reads a month of runs by, in one query."""
    q, args = "SELECT id, created_at, detail FROM activity_log WHERE action=?", [action]
    if run_id is not None:
        q += " AND id=?"
        args.append(run_id)
    if since:
        q += " AND created_at>=?"
        args.append(since)
    if until:
        q += " AND created_at<?"
        args.append(until)
    return db.execute(q + " ORDER BY id DESC LIMIT ?", args + [limit]).fetchall()


def reminder_runs(db, limit=8, run_id=None, since=None, until=None):
    """The last sends, newest first: [{when, why, sent, failed, skipped, dry, queued, plan}] (from the activity log's
    'reminder_run'). A run that queued its emails in waves (2026-10-21) reads "450 queued in 3 waves (200 every 30
    min)": queued is the 450, plan the words after it. "N opted out" (2026-11-01) is the people the super admin took off it."""
    out = []
    for r in _run_log_rows(db, "reminder_run", limit, run_id, since, until):
        bits = [b.strip() for b in (r["detail"] or "").split("|")]
        run = {"when": _when_disp(_myt(r["created_at"])), "why": bits[0] if bits else "", "sent": 0, "failed": 0,
               "skipped": 0, "dry": 0, "queued": 0, "plan": "", "opted_out": 0,
               "id": r["id"], "at": r["created_at"], "batch": _es_batch_bit(bits)}   # id, at, batch: Email › Sent's People ›
        for b in bits[1:]:
            w = b.split()
            if len(w) < 2 or not w[0].isdigit():
                continue
            key = "dry" if w[1] == "dry" else "opted_out" if w[1] == "opted" else w[1]
            if key in ("sent", "failed", "skipped", "dry", "queued", "opted_out"):
                run[key] = int(w[0])
            if key == "queued":
                run["plan"] = " ".join(w[2:])
        out.append(run)
    return out


