# --- the release emails (Chris, 2026-10-17: "it will auto send to the BUCEO, similarly like once super admin released a
# BU result to employees, it would notify employees as well") ----------------------------------------------------------
# A release sends its own emails, never a revoke: step 1 tells each leader it reached (line manager, HOD, BU CEO) once,
# with how many of their people it covers, and a BU CEO also how many of those the BG CEO moved from the bands they
# calibrated; step 2 tells each person their results are ready. A count and a link only: no band, no name of anyone
# else. Never twice for the same result: release_emails remembers each (step, recipient, person, result).
RELEASE_LEAD_KIND = "release_leaders"
RELEASE_PERSON_KIND = "release_person"
_RELEASE_WHAT = (("pm", "your final performance band"), ("pot", "your potential band"),
                 ("talent", "your talent status"), ("report", "your 360 report"))


def _release_leaders_of(db, subs):
    """{subject_id: {leader_id: set(roles)}}: who release 1 reaches for each person -- their line manager, their HOD,
    their unit's BU CEO -- active, not an admin, never the person themselves."""
    seats = {k: r for k, r in buceo_holders(db).items() if not r["left_at"]}
    out = {}
    for s_ in subs:
        lead = {}
        for role, lid in (("lm", s_["manager_id"]), ("hod", s_["hod_id"]),
                          ("buceo", (seats.get((s_["business_group"], s_["company"])) or {"id": None})["id"])):
            if lid and lid != s_["id"]:
                lead.setdefault(lid, set()).add(role)
        out[s_["id"]] = lead
    ids = sorted({lid for d in out.values() for lid in d})
    ok = set()
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        ok |= {r[0] for r in db.execute("SELECT id FROM users WHERE left_at IS NULL AND role!='admin' AND id IN (%s)"
                                        % ",".join("?" * len(chunk)), chunk)}
    return {sid: {lid: r for lid, r in d.items() if lid in ok} for sid, d in out.items()}


def _bg_moved_ids(db, period_id, cycle_id, ids):
    """{subject_id: set('pm'|'pot')} the BG CEO moved: a move of theirs, not a pin, to another band."""
    out = {}
    if not ids:
        return out
    for adj, sess, cid, axis in (("pm_calibration_adjustments", "pm_calibration_sessions", period_id, "pm"),
                                 ("calibration_adjustments", "calibration_sessions", cycle_id, "pot")):
        for i in range(0, len(ids), 900):
            chunk = ids[i:i + 900]
            for r in db.execute(
                    "SELECT a.subject_id FROM %s a JOIN %s s ON s.id=a.session_id WHERE s.cycle_id=? AND "
                    "s.tier='bgceo' AND a.pinned IS NULL AND COALESCE(a.adjusted_band,'')!='' AND "
                    "a.adjusted_band != COALESCE(a.original_band,'') AND a.subject_id IN (%s)"
                    % (adj, sess, ",".join("?" * len(chunk))), [cid] + chunk):
                out.setdefault(r[0], set()).add(axis)
    return out


def _release_emailed(db, period_id, step, pairs):
    """The (recipient, subject, kind) triples already emailed for this release step."""
    seen = set()
    rows = db.execute("SELECT recipient_id, subject_id, kind FROM release_emails WHERE cycle_id=? AND step=?",
                      (period_id, step)).fetchall()
    for r in rows:
        seen.add((r[0], r[1], r[2]))
    return seen


def _release_lead_mail(db, lead, n, moved, units, period, mid_year, both, tpl=None):
    """(subject, html) of one leader's release email in the words of the template in use (Cycle > Emails): how many of
    their people, with the BG CEO's moves in their units for a BU CEO, and whether their people see theirs yet."""
    t = tpl or email_tpl_words("release_lead", db=db)
    vals = dict(email_names(db, lead), cycle=period["name"], count=str(n), moved=str((moved or {}).get("n") or ""),
                units=_lp_join(list(units or [])) or "your unit")
    fill = lambda k: _tpl_fill(t.get(k) or "", vals)   # noqa: E731
    body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill("opening")))]
    if moved and fill("moved"):
        body.append(_em_p(_em_esc(fill("moved"))))
    if fill("both" if both else "not_yet"):
        body.append(_em_p(_em_esc(fill("both" if both else "not_yet"))))
    return fill("subject"), onehr_email(
        fill("heading"), "".join(body),
        button=(fill("button"), app_base_url() + url_for("dashboard", panel="led", cycle=period["id"])),
        sub=fill("sub_both" if both else "sub_not_yet"), cycle=period["name"], footer=fill("footer"))


def _release_person_mail(db, person, kinds, period, tpl=None):
    """(subject, html) of one person's release email in the words of the template in use: what was released to them,
    never the result itself."""
    t = tpl or email_tpl_words("release_person", db=db)
    parts = [w for k, w in _RELEASE_WHAT if k in kinds]
    what = parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " and " + parts[-1]
    vals = dict(email_names(db, person), cycle=period["name"], what=what)
    fill = lambda k: _tpl_fill(t.get(k) or "", vals)   # noqa: E731
    body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill("opening")))]
    if fill("closing"):
        body.append(_em_p(_em_esc(fill("closing"))))
    return fill("subject"), onehr_email(
        fill("heading"), "".join(body),
        button=(fill("button"), app_base_url() + url_for("dashboard", record=period["id"])),
        sub=fill("sub"), cycle=period["name"], footer=fill("footer"))


def release_email_queue(db, me, period, cyc, done, to):
    """Queue the emails one release owes (called after the release committed; never for a revoke). done = {kind:
    [subject ids released]} as the release wrote them; to = 'leaders' | 'employees' | 'both'. The release's emails go
    in waves (2026-10-21, email_wave_rules), the leaders' first and then the people's, counted over the whole list.
    Returns {leaders, people, no_email, waves} counts, or None when this server sends no email."""
    if not mailer.is_configured():
        return None
    out = {"leaders": 0, "people": 0, "no_email": 0, "waves": 0}
    rules, start, batch = email_wave_rules(), _utc_now(), "release-" + secrets.token_hex(6)
    lead_tpl, person_tpl = email_tpl_words("release_lead", db=db), email_tpl_words("release_person", db=db)
    pid = period["id"]
    all_ids = sorted({i for v in done.values() for i in v})
    if not all_ids:
        return out
    subs = {}
    for i in range(0, len(all_ids), 900):
        chunk = all_ids[i:i + 900]
        subs.update({r["id"]: r for r in db.execute("SELECT * FROM users WHERE id IN (%s)" % ",".join("?" * len(chunk)),
                                                    chunk)})
    mid_year = cycle_is_mid_year(db, pid)
    if to in ("leaders", "both"):
        lead_done = {k: v for k, v in done.items() if k in LEADER_RELEASE_KINDS and v}
        lead_ids = sorted({i for v in lead_done.values() for i in v})
        reach = _release_leaders_of(db, [subs[i] for i in lead_ids if i in subs])
        seen = _release_emailed(db, pid, "leaders", None)
        moved = {} if mid_year else _bg_moved_ids(db, pid, cyc["id"], lead_ids)
        per = {}   # leader -> {"subs": set, "rows": [(sid, kind)], "bu": set(subject ids as BU CEO)}
        for kind, sids in lead_done.items():
            for sid in sids:
                for lid, roles in reach.get(sid, {}).items():
                    if (lid, sid, kind) in seen:
                        continue
                    d = per.setdefault(lid, {"subs": set(), "rows": [], "bu": set()})
                    d["subs"].add(sid)
                    d["rows"].append((sid, kind))
                    if "buceo" in roles:
                        d["bu"].add(sid)
        for lid, d in per.items():
            lead = db.execute("SELECT * FROM users WHERE id=?", (lid,)).fetchone()
            if not lead or not (lead["email"] or "").strip():
                out["no_email"] += 1
                continue
            mv = None
            bu_moved = [s for s in d["bu"] if moved.get(s)]
            if d["bu"] and not mid_year and bu_moved:
                mv = {"n": len(bu_moved)}
            units = sorted({display_company(subs[s]["business_group"], subs[s]["company"]) for s in d["bu"]
                            if subs.get(s) and subs[s]["company"]})
            subj, body = _release_lead_mail(db, lead, len(d["subs"]), mv, units, period, mid_year, to == "both",
                                            tpl=lead_tpl)
            oid = _outbox_add(db, RELEASE_LEAD_KIND, lead["email"].strip(), subj, body, user_id=lid, cycle_id=pid,
                              detail="%d people" % len(d["subs"]), actor_id=me["id"],
                              send_after=_email_wave_at(out["leaders"], rules, start), batch=batch)
            for sid, kind in d["rows"]:
                db.execute("INSERT OR IGNORE INTO release_emails(cycle_id, step, recipient_id, subject_id, kind, "
                           "outbox_id) VALUES (?,?,?,?,?,?)", (pid, "leaders", lid, sid, kind, oid))
            out["leaders"] += 1
    if to in ("employees", "both"):
        seen = _release_emailed(db, pid, "person", None)
        mine = {}
        for kind, sids in done.items():
            for sid in sids:
                if (sid, sid, kind) not in seen:
                    mine.setdefault(sid, set()).add(kind)
        for sid, kinds in mine.items():
            p = subs.get(sid)
            if not p or p["left_at"]:
                continue
            if not urole_allows(p, "results", db):   # their user role doesn't show them results: no email either
                continue
            if not (p["email"] or "").strip():
                out["no_email"] += 1
                continue
            subj, body = _release_person_mail(db, p, kinds, period, tpl=person_tpl)
            oid = _outbox_add(db, RELEASE_PERSON_KIND, p["email"].strip(), subj, body, user_id=sid, cycle_id=pid,
                              detail=",".join(sorted(kinds)), actor_id=me["id"],
                              send_after=_email_wave_at(out["leaders"] + out["people"], rules, start), batch=batch)
            for kind in kinds:
                db.execute("INSERT OR IGNORE INTO release_emails(cycle_id, step, recipient_id, subject_id, kind, "
                           "outbox_id) VALUES (?,?,?,?,?,?)", (pid, "person", sid, sid, kind, oid))
            out["people"] += 1
    db.commit()
    out["waves"] = email_wave_plan(out["leaders"] + out["people"], rules)["waves"]
    if out["leaders"] or out["people"]:
        _outbox_kick()
    return out


def release_email_who(db, rows):
    """For the release page's confirm boxes: {leader_id: [name, has_email]} for the leaders of the people shown, and
    whether this server sends email."""
    reach = _release_leaders_of(db, [r["u"] for r in rows])
    ids = sorted({lid for d in reach.values() for lid in d})
    who = {}
    for i in range(0, len(ids), 900):
        chunk = ids[i:i + 900]
        for r in db.execute("SELECT id, full_name, email FROM users WHERE id IN (%s)" % ",".join("?" * len(chunk)),
                            chunk):
            who[r["id"]] = [r["full_name"], bool((r["email"] or "").strip())]
    return reach, who


