def release_rules():
    """The release window's set-up (Admin › Notices), over its defaults; cells None = every part of the calendar."""
    r = dict(RELEASE_WINDOW_DEFAULT)
    try:
        saved = json.loads(_setting("release_window", "") or "{}") or {}
    except (TypeError, ValueError):
        saved = {}
    if isinstance(saved, dict):
        r.update({k: v for k, v in saved.items() if k in RELEASE_WINDOW_DEFAULT})
    for k in ("downtime", "bar_lead", "warn_lead", "fix_lead", "reopen_after"):
        if r[k] not in RELEASE_OPTIONS[k]:
            r[k] = RELEASE_WINDOW_DEFAULT[k]
    if r["start"] not in RELEASE_OPTIONS["start"]:
        r["start"] = RELEASE_WINDOW_DEFAULT["start"]
    if r["mode"] not in ("cycle", "dates"):
        r["mode"] = "cycle"
    if r["cells"] is not None:
        r["cells"] = [c for c in r["cells"] if c in _WINDOW_SUBJECT]
    return r


def _rw_dmy(raw):
    """A stored date or date-time -> date, or None."""
    dt = _parse_when(raw)
    return dt.date() if dt else None


def _rw_span(a, b):
    """'2 – 8 Nov', '30 Oct – 2 Nov', '8 Nov'."""
    if not a or not b:
        return ""
    if a == b:
        return "%d %s" % (a.day, a.strftime("%b"))
    if (a.year, a.month) == (b.year, b.month):
        return "%d – %d %s" % (a.day, b.day, b.strftime("%b"))
    return "%d %s – %d %s" % (a.day, a.strftime("%b"), b.day, b.strftime("%b"))


def release_parts(db, cyc, rules=None):
    """The active cycle's parts by module, each with its role and calendar dates and whether the release window
    follows it: [{name, parts: [{cell, name, who, opens, closes, dates, dated, on}]}]."""
    rules = rules or release_rules()
    who = {c[0]: NOTICE_WHO.get(c[2], c[2].lower()) for c in WINDOW_CELLS}
    who.update(_NOTICE_GH_WHO)
    gh = bool(cyc and gradeh_rm_cid(db, cyc))   # the Grade H group is there only where Grade H runs on the cycle
    out = []
    for gname, cells in NOTICE_GROUPS:
        if not gh and cells == GRADEH_CELL_KEYS:
            continue
        parts = []
        for cell in cells:
            o, c = window_dates(db, cell, cyc["id"]) if cyc else (None, None)
            od, cd = _rw_dmy(o), _rw_dmy(c)
            if cell in ("pm_setting", "pm_setting_approve") and not (od or cd):
                continue   # KPI setting runs in the Early Year only: no row unless it's dated
            parts.append({"cell": cell, "name": NOTICE_CELL_NAMES[cell], "who": who[cell],
                          "opens": od.isoformat() if od else "", "closes": cd.isoformat() if cd else "",
                          "dates": _rw_span(od, cd) if (od and cd) else "Not dated yet", "dated": bool(od and cd),
                          "on": rules["cells"] is None or cell in rules["cells"]})
        if parts:
            out.append({"name": gname, "parts": parts})
    return out


def release_range(db, rules=None, cyc=None):
    """(first day, last day) the release window applies, or (None, None): following the cycle's timeline, from the
    first ticked part's opening to the last one's close; or the dates set by hand."""
    rules = rules or release_rules()
    if rules["mode"] == "dates":
        a, b = _rw_dmy(rules["from"]), _rw_dmy(rules["until"])
        return (a, b) if a and b and a <= b else (None, None)
    cyc = cyc if cyc is not None else active_cycle(db)
    ticked = [p for g in release_parts(db, cyc, rules) for p in g["parts"] if p["on"] and p["dated"]]
    if not ticked:
        return None, None
    return (min(date.fromisoformat(p["opens"]) for p in ticked),
            max(date.fromisoformat(p["closes"]) for p in ticked))


def release_window_open(db, day=None):
    """True when release evenings apply on `day` (today, MYT): switched on, and inside its dates."""
    rules = release_rules()
    if not rules["on"]:
        return False
    a, b = release_range(db, rules)
    d = day or _today_myt()
    return bool(a and b and a <= d <= b)


def release_blackouts(db, rules=None, cyc=None):
    """The days with no planned release: the launch freeze, then each followed part's last day and the day before
    (by the dates it is followed for; dates set by hand follow every dated part). [{from, to, text}] by date."""
    rules = rules or release_rules()
    cyc = cyc if cyc is not None else active_cycle(db)
    out = []
    ff, ft = _rw_dmy(rules["freeze_from"]), _rw_dmy(rules["freeze_to"])
    if ff and ft:
        out.append({"from": ff, "to": ft, "text": "%s · launch freeze" % _rw_span(ff, ft)})
    closing = {}
    for g in release_parts(db, cyc, rules):
        for p in g["parts"]:
            if p["dated"] and (rules["mode"] == "dates" or p["on"]):
                d = date.fromisoformat(p["closes"])
                closing.setdefault(d, [])
                if p["who"] not in closing[d]:
                    closing[d].append(p["who"])
    for d in sorted(closing):
        who = closing[d]
        names = who[0] if len(who) == 1 else ", ".join(who[:-1]) + " and " + who[-1]
        out.append({"from": d - timedelta(days=1), "to": d,
                    "text": "%s · %s close" % (_rw_span(d - timedelta(days=1), d), names)})
    return out


def release_blackout_on(db, day, rules=None):
    """The words of the no-release day `day` falls in, or None."""
    for b in release_blackouts(db, rules):
        if b["from"] <= day <= b["to"]:
            return b["text"]
    return None


# --- a notice's times and words -----------------------------------------------------------------------------------
def notice_times(n, rules=None):
    """{start, end, show_from, warn_at} (MYT datetimes) of one notice: the bar shows from an hour before (a retired
    urgent fix row, from 15 minutes before), turns red ten minutes before, and the notice ends when OneHR is due back."""
    rules = rules or release_rules()
    start = _parse_when(n["starts_at"])
    end = start + timedelta(minutes=int(n["downtime_min"]))
    lead = rules["fix_lead"] if n["kind"] == "fix" else rules["bar_lead"]
    return {"start": start, "end": end, "show_from": start - timedelta(minutes=lead),
            "warn_at": start - timedelta(minutes=rules["warn_lead"])}


def _notice_hm(dt):
    return dt.strftime("%H:%M")


def notice_when_word(start, now, cap=True):
    """'Tonight' / 'Today' / 'Tomorrow' / 'Wed 4 Nov' (lower-case 'tonight' etc. when cap is False)."""
    if start.date() == now.date():
        w = "Tonight" if start.hour >= 18 else "Today"
    elif start.date() == now.date() + timedelta(days=1):
        w = "Tomorrow"
    else:
        return "%s %d %s" % (start.strftime("%a"), start.day, start.strftime("%b"))
    return w if cap else w.lower()


def _epoch_ms(myt_dt):
    """A MYT wall-clock datetime as milliseconds since the epoch, for the page's countdown."""
    return int((myt_dt - timedelta(hours=8) - datetime(1970, 1, 1)).total_seconds() * 1000)


def notice_in(secs):
    """The time left before the closure, as the navy bar counts it down: '52 min', '1 hr', '1 hr 5 min' (rounded up,
    never 0). static/notice.js says it the same way (inWords)."""
    h, m = divmod(max(1, (int(secs) + 59) // 60), 60)
    return ("%d hr" % h + (" %d min" % m if m else "")) if h else "%d min" % m


def notice_words(n, now=None, auth=False, rules=None):
    """Every line the bar says for one notice, in each of its states: {lead, info, info_on, warn, closed, saved, pill,
    pill_on, red}. info and pill carry {in}, the countdown to the closure (Chris, 2026-10-26: "can the notice panel
    shows the countdown to the closure?"), and warn {left}, both filled in by the page; a retired urgent fix's lead (an old
    stored row only) carries {mins}. info_on / pill_on are what a notice that keeps OneHR open says once its work has started."""
    now = now or _now_myt()
    k = NOTICE_KIND[n["kind"]]
    t = notice_times(n, rules)
    fr, to = _notice_hm(t["start"]), _notice_hm(t["end"])
    fix = n["kind"] == "fix"   # retired kind (2026-11-08): kept only so an old stored row still renders
    closes = bool(n["closes"]) or fix
    if fix and t["start"].date() == now.date():
        lead = "In {mins}, %s – %s" % (fr, to)
    else:
        lead = "%s, %s – %s" % (notice_when_word(t["start"], now), fr, to)
    what = k["what"][:1].upper() + k["what"][1:]
    # the urgent fix's lead already counts its minutes ("In 12 minutes, …"), so its sentence doesn't again
    closing = "OneHR closes for %s." % k["what"] if fix else "OneHR closes in {in} for %s." % k["what"]
    if not closes:
        info = "%s starts in {in}. OneHR stays open; some pages may be slow." % what
    elif auth:
        info = "%s Anything you save before %s is kept." % (closing, fr)
    else:
        info = "%s Save your work before %s." % (closing, fr)
    if auth:
        warn = "OneHR closes in {left} for %s, until about %s. If you sign in now, save before %s." % (k["what"], to, fr)
    else:
        warn = "OneHR closes in {left}. Save your work now. Closed %s – %s for %s." % (fr, to, k["what"])
    return {"lead": lead, "info": info, "warn": warn if closes else "",
            "info_on": "" if closes else "%s is under way. OneHR stays open; some pages may be slow." % what,
            "closed": ("OneHR is closed for %s until %s. What you've typed stays on this page." % (k["what"], to))
            if closes else "",
            "saved": ("Not saved yet. OneHR is closed for %s until %s. Keep this page open, or copy what you typed, "
                      "and press Save again once OneHR is back." % (k["what"], to)) if closes else "",
            "pill": ("Closes in {in} · until %s" % to) if closes else "%s in {in} · OneHR stays open" % k["label"],
            "pill_on": "" if closes else "%s until %s · OneHR stays open" % (k["label"], to),
            "red": fix}


def notice_current(db, now=None):
    """The notice the bar shows now: scheduled, its bar due, and not yet over (nor reopened early). The earliest
    first. None when there's nothing to say."""
    now = now or _now_myt()
    rules = release_rules()
    for n in db.execute("SELECT * FROM site_notices WHERE status='scheduled' ORDER BY starts_at, id"):
        t = notice_times(n, rules)
        if t["show_from"] <= now < t["end"] and not n["reopened_at"]:
            return n
    return None


def notice_next(db, now=None, days=7):
    """The next notice not yet over, within `days` (Ask OneHR's answer), or None."""
    now = now or _now_myt()
    for n in db.execute("SELECT * FROM site_notices WHERE status='scheduled' ORDER BY starts_at, id"):
        t = notice_times(n)
        if t["end"] > now and not n["reopened_at"] and t["start"] <= now + timedelta(days=days):
            return n
    return None


def notice_bar(db, now=None, auth=False):
    """What the page needs to draw the bar, or None: the notice's words, its times as epoch ms for the countdown, and
    whether it may be hidden (only before the closing warning)."""
    try:
        now = now or _now_myt()
        n = notice_current(db, now)
    except sqlite3.Error:
        return None
    if not n:
        return None
    rules = release_rules()
    t = notice_times(n, rules)
    w = notice_words(n, now, auth, rules)
    closes = bool(n["closes"]) or n["kind"] == "fix"
    # the state as the page first draws it (static/notice.js keeps it current): before the warning, red with the
    # countdown, or closed (a tab left open past the start)
    state = "closed" if closes and now >= t["start"] else "warn" if closes and now >= t["warn_at"] else "info"
    left = max(0, int((t["start"] - now).total_seconds()))
    mins = max(1, (left + 59) // 60)
    return {"id": n["id"], "kind": n["kind"], "closes": closes, "words": w, "state": state,
            "lead_now": w["lead"].replace("{mins}", "%d minute%s" % (mins, "" if mins == 1 else "s")),
            "text_now": (w["closed"] if state == "closed" else
                         w["warn"].replace("{left}", "%d:%02d" % (left // 60, left % 60)) if state == "warn"
                         else w["info_on"] if w["info_on"] and now >= t["start"]
                         else w["info"].replace("{in}", notice_in(left))),
            "start": _epoch_ms(t["start"]), "end": _epoch_ms(t["end"]), "warn": _epoch_ms(t["warn_at"]),
            "now": _epoch_ms(now), "auth": bool(auth)}


@app.context_processor
def _site_notice_ctx():
    """The bar on every page that draws one (base.html), read once per page."""
    if not has_request_context() or request.endpoint in (None, "static") or request.path.startswith("/static/"):
        return {}
    auth = request.endpoint in ("login", "forgot_password", "reset_password", "signin_help")
    db = get_db()
    place = "signin" if auth else bar_place()
    # announcements and the deadline reminder meant for this page (bar_items: none while a notice is current, it
    # stands alone)
    return {"site_notice": notice_bar(db, auth=auth), "site_place": place,
            "site_ann": bar_items(db, None if auth else current_user(), auth=auth, place=place)}


@app.route("/favicon.ico")
def favicon_ico():
    """Browsers ask for /favicon.ico on every page; answer 200 with an empty body (cached a day) rather than a
    404 in the log. Needs no sign-in. 200, not 204: the deploy route probe accepts only 200 / 301 / 302 / 303."""
    resp = Response(b"", status=200, mimetype="image/x-icon")
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


@app.route("/notice.json")
def site_notice_json():
    """The bar's state for a page left open (static/notice.js asks every few minutes), signed in or not: the sign-in
    page shows the bar too (Chris, 2026-10-26: "add the notification bar on our login page/landing page too")."""
    auth = request.args.get("auth") == "1"
    place = request.args.get("place") if request.args.get("place") in BAR_PLACE else "other"
    db = get_db()
    resp = jsonify({"notice": notice_bar(db, auth=auth),
                    "ann": bar_items(db, None if auth else current_user(), auth=auth, place=place)})
    resp.headers["Cache-Control"] = "no-store"
    return resp


