_DL_CACHE_SECONDS = 300


def deadline_rules():
    """The deadline reminder's set-up (Banner): on, from how many days before a part closes, and the pages it shows on
    (the dashboard unless more are ticked)."""
    r = dict(DEADLINE_RULES_DEFAULT)
    try:
        saved = json.loads(_setting("deadline_reminder", "") or "{}") or {}
    except (TypeError, ValueError):
        saved = {}
    if isinstance(saved, dict):
        r.update({k: v for k, v in saved.items() if k in DEADLINE_RULES_DEFAULT})
    r["on"] = bool(r["on"])
    if r["days"] not in DEADLINE_DAYS:
        r["days"] = DEADLINE_RULES_DEFAULT["days"]
    pl = [p for p in DL_PLACES if isinstance(r.get("places"), list) and p in r["places"]]
    r["places"] = pl or list(DEADLINE_RULES_DEFAULT["places"])
    return r


def _dl_days_phrase(days):
    """The setting in words, for the audit trail."""
    return "the whole time a part is open" if days == DEADLINE_WHOLE else "from %d day%s before" % (
        days, "" if days == 1 else "s")


def _dl_left_words(left):
    """"7 days left." for `left` days to the closing date (> 0): today counts, so one more than `left`."""
    shown = max(left, 0) + 1
    return "%d day%s left." % (shown, "" if shown == 1 else "s")


def deadline_words(role, close, left, n=None, early=False):
    """The bar's words for one part's deadline: (lead, body). `left` = days to its closing date (each part closes at
    23:59 MYT on its last day); 0 = the last day. The count shown includes today (2026-11-01): on 2 Nov a part closing
    8 Nov reads "7 days left" (left = 6). n = how many of a line manager's people still wait."""
    _r, part, verb, _b = _DL_PART[role]
    if role == "own" and early:
        part = "your KPI setting"
    submit = "Submit" if (role == "own" and early) else "Save & submit"
    do = {"own": "", "f360": "Submit it for each colleague you rate.",
          "team": ("%d %s still to review." % (n, "person" if n == 1 else "people")) if n
          else "Confirm each person once you've checked them.",
          "hod": "Save each person when you've decided.", "buceo": "Lock each unit once you're done.",
          "bgceo": "Lock each business unit once you're done."}[role]
    if left <= 0:
        lead = "Last day: %s %s tonight at 23:59" % (part, verb)
        if role == "own":
            return lead, "Check your answers, then press %s." % submit
        if role == "team" and n:
            return lead, do + " Confirm each one once you've checked it."
        return lead, do
    lead = "%s %s %s %d %s, 23:59" % (part[:1].upper() + part[1:], verb, close.strftime("%a"), close.day,
                                      close.strftime("%b"))
    left_s = _dl_left_words(left)
    if role == "own":
        return lead, "%s Save as you go; only %s sends it to your line manager." % (left_s, submit)
    return lead, "%s %s" % (left_s, do)


def _dl_items(db, u, cyc, now):
    """reminder_items for `u` (what waits on them in the parts open now), kept a few minutes per process: it reads the
    dashboard's own sources. A POST of theirs drops it (_dl_cache_drop), so what they just submitted comes off."""
    key = (u["id"], cyc["id"], now.date())
    hit = _DL_CACHE.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    items = reminder_items(db, u)
    if len(_DL_CACHE) > 20000:
        _DL_CACHE.clear()
    _DL_CACHE[key] = (time.monotonic() + _DL_CACHE_SECONDS, items)
    return items


@app.after_request
def _dl_cache_drop(resp):
    """A save by someone (any POST) drops their cached deadline reminder, so it reads what's left at their next page."""
    try:
        if _DL_CACHE and has_request_context() and request.method == "POST":
            ids = {session.get("user_id"), session.get("demo_as")} - {None}
            for k in [k for k in list(_DL_CACHE) if k[0] in ids]:
                _DL_CACHE.pop(k, None)
    except Exception:   # never let the cache spoil a response
        pass
    return resp


def _gh_dl_when(dt, lang):
    """A closing date-time in the person's language for the bar: 'Sun 29 Nov, 23:59' / 'Ahad 29 Nov, 11:59 malam'."""
    return gh_day_words(dt, lang, time=True) if lang == "bm" else "%s, %s" % (gh_day_words(dt, "en"), dt.strftime("%H:%M"))


def _gh_deadline_item(db, person, rules, now, place=None):
    """A Grade H person's deadline reminder (Chris, 2026-10-28; its words are board E3's, 2026-10-31), or None: only their own
    page's date, read through gradeh_staff_deadline (the page's "Now . by 15 Nov" reads the same one: for acknowledging that is
    the deemed deadline, so the bar names it only while the switch is on) and in their language. Within the rules' days, red on
    the last day. No button on their home (My Appraisal counts as the dashboard place); elsewhere it opens it."""
    nxt = gradeh_staff_deadline(db, person)
    if not nxt:
        return None
    kind, dt = nxt
    today = now.date()
    left = (dt.date() - today).days
    if not 0 <= left <= rules["days"]:
        return None
    lang = person["language"] if person["language"] in GRADEH_LANGS else "bm"
    if left <= 0:
        lead = gh_t(lang, "dl_%s_last" % kind, t=_gh_time(dt, lang) if lang == "bm" else dt.strftime("%H:%M"))
        body = gh_t(lang, "dl_%s_last_body" % kind)
    else:
        lead = gh_t(lang, "dl_%s_lead" % kind, d=_gh_dl_when(dt, lang))
        shown = left + 1   # today counts (as _dl_left_words does for everyone else): an 8 Nov close on 2 Nov reads "7 days left"
        body = gh_t(lang, "dl_kpi_body_1" if (kind == "kpi" and shown == 1) else "dl_%s_body" % kind, n=shown)
    return {"key": "dl.gradeh_%s.%s.%s" % (kind, dt.date().isoformat(), today.isoformat()), "kind": "deadline", "icon": "cal",
            "lead": lead, "body": body, "red": left <= 0,
            "button": None if place == "dashboard" else {"label": gh_t(lang, "app"), "url": url_for("my_appraisal")}}


# The leaders' Grade H lines in the bar (board E3, 2026-10-31): the appraiser, the HOD and the BU CEO, in English like the rest of
# the leaders' bar. role -> (the part in a sentence, what to do, its button). Read by the live bar and by Banner's preview.
GRADEH_LEAD_DL = {
    "gradeh_lm": ("Your Grade H appraisals", "Submit each person once you have talked it through.", "Open my Grade H team"),
    "gradeh_hod": ("Your Grade H review", "Sign off potential, then performance.", "Open my Grade H review"),
    "gradeh_buceo": ("Your Grade H sign-off", "Sign off each unit once you are done.", "Open my Grade H sign-off"),
}


def gradeh_lead_deadline_words(role, close, left, n_ready=None):
    """The bar's words for one Grade H leader part: (lead, body). `left` = days to its closing date (23:59 MYT that day); 0 =
    the last day. n_ready = for the appraiser, how many of their people are ready for them."""
    part, do, _b = GRADEH_LEAD_DL[role]
    if left <= 0:
        return "Last day: %s close%s tonight at 23:59" % (part[:1].lower() + part[1:], "" if role == "gradeh_lm" else "s"), do
    lead = "%s close%s %s %d %s, 23:59" % (part, "" if role == "gradeh_lm" else "s", close.strftime("%a"), close.day, close.strftime("%b"))
    left_s = _dl_left_words(left)   # today counts, as for every other part
    if role == "gradeh_lm":
        r = n_ready or 0
        return lead, "%s %s" % (left_s, ("%d %s ready for you." % (r, "is" if r == 1 else "are")) if r else "None are ready for you yet.")
    return lead, "%s %s" % (left_s, do)


def deadline_item(db, u, now=None, place=None, only_gh=False):
    """Their own deadline in the bar, or None: from the set number of days before a part of theirs closes (or, set to
    DEADLINE_WHOLE, from the day it opens; its date on the cycle's calendar, as the top bar's pill reads it) until it
    closes, while something of theirs in it still waits. The soonest-closing part, the most direct first on the same day; red on the last day. Never for an admin,
    nor when nothing closes within the days. A person on the Grade H list (the module on) gets only their Grade H
    reminder, the date their own page shows (_gh_deadline_item), in their language. A Grade H leader (the appraiser, the HOD,
    the BU CEO) has their Grade H part among the candidates, the soonest closing winning as for every part; only_gh = the Grade H
    pages' own bar, where only a Grade H line shows (2026-10-31)."""
    now = now or _now_myt()
    rules = deadline_rules()
    if not rules["on"] or not u or is_admin(u):
        return None
    cyc = active_cycle(db)
    if not cyc:
        return None
    person = gradeh_staff_person(db, u, cyc["id"])
    if person:
        return _gh_deadline_item(db, person, rules, now, place)
    today = now.date()
    soon = False   # cheap first: does any part open now close within the days? (else nobody has a reminder)
    for c in _notice_open_cells(db, cyc, now):
        d = _rw_dmy(window_dates(db, c, cyc["id"])[1])
        if d and 0 <= (d - today).days <= rules["days"]:
            soon = True
            break
    # ...or does a late pass of theirs run out within them (2026-10-31)?
    if not soon:
        try:
            soon = any(0 <= (_parse_when(_myt(r[0])).date() - today).days <= rules["days"] for r in db.execute(
                "SELECT until_at FROM late_passes WHERE cycle_id=? AND user_id=? AND closed_at IS NULL AND "
                "until_at > datetime('now')", (cyc["id"], u["id"])))
        except sqlite3.OperationalError:
            soon = False
    if not soon:
        return None
    items = _dl_items(db, u, cyc, now)
    best = None
    for it in items:
        d, role = it.get("closes_on"), it.get("role")
        if not d or not 0 <= (d - today).days <= rules["days"]:
            continue
        if role in GRADEH_LEAD_DL:   # Grade H's parts rank after the cycle's own on the same day
            k = (d, len(_DL_ORDER) + list(GRADEH_LEAD_DL).index(role))
        elif role in _DL_PART and not only_gh:
            k = (d, _DL_ORDER.index(role))
        else:
            continue
        if best is None or k < best[0]:
            best = (k, it)
    if not best:
        return None
    (d, _o), it = best
    role, left = it["role"], (d - today).days
    if role in GRADEH_LEAD_DL:
        lead, body = gradeh_lead_deadline_words(role, d, left, n_ready=it.get("n_ready"))
        url = it.get("url") or ""
        return {"key": "dl.%s.%s.%s" % (role, d.isoformat(), today.isoformat()), "kind": "deadline", "icon": "cal",
                "lead": lead, "body": body, "red": left <= 0,
                "button": {"label": GRADEH_LEAD_DL[role][2], "url": url} if url.startswith("/") else None}
    people = set()
    if role == "team":
        for x in items:
            if x.get("role") == "team" and x.get("closes_on") == d:
                people.update(x.get("people") or [])
    lead, body = deadline_words(role, d, left, n=len(people) or None, early=bool(cycle_row_is_early_year(cyc)))
    if it.get("late_until"):   # a late pass: its time, not the calendar's 23:59 (2026-10-31)
        lu = it["late_until"]
        part = _DL_PART[role][1]
        lead = "%s is open for you until %s %d %s, %s" % (part[:1].upper() + part[1:], lu.strftime("%a"), lu.day,
                                                          lu.strftime("%b"), lu.strftime("%H:%M"))
        body = ("Last day for you." if left <= 0 else _dl_left_words(left)) + \
            " It closed for others; nothing you entered has changed."
    url = it.get("url") or ""
    return {"key": "dl.%s.%s.%s" % (role, d.isoformat(), today.isoformat()), "kind": "deadline", "icon": "cal",
            "lead": lead, "body": body, "red": left <= 0,
            "button": {"label": _DL_PART[role][3], "url": url} if url.startswith("/") else None}


def deadline_preview(db, rules=None):
    """Admin › Notices: what each role's reminder says, from the active cycle's calendar ([] with nothing dated)."""
    rules = rules or deadline_rules()
    cyc = active_cycle(db)
    if not cyc:
        return []
    early = bool(cycle_row_is_early_year(cyc))
    out = []
    for role, who, cells in _DL_PREVIEW:
        dated = [(_rw_dmy(o), _rw_dmy(c)) for o, c in (window_dates(db, x, cyc["id"]) for x in cells)]
        dated = [(o, c) for o, c in dated if o and c]
        if not dated:
            continue
        a, b = min(o for o, _c in dated), max(c for _o, c in dated)
        # what a person reads on the first day the bar shows: the setting, or the window's own length if shorter
        lead, body = deadline_words(role, b, min(rules["days"], (b - a).days), early=early)
        last_lead, last_body = deadline_words(role, b, 0, early=early)
        out.append({"who": who, "dates": _rw_span(a, b), "lead": lead, "body": body,
                    "last_lead": last_lead, "last_body": last_body, "last_day": "%s %d %s" % (
                        b.strftime("%a"), b.day, b.strftime("%b"))})
    return out


def deadline_preview_gh(db, rules=None):
    """Banner's preview of Grade H's lines (board E3): [{who, dates, lead, body, last_lead, last_body, last_day}] for staff in
    English (the KPI achievement), staff in Bahasa Melayu (acknowledging), the appraisers, the HODs and the BU CEOs, from the
    cycle's calendar, in the words the live bar uses. [] where Grade H does not run."""
    rules = rules or deadline_rules()
    cyc = active_cycle(db)
    cid = gradeh_rm_cid(db, cyc)
    if not cid:
        return []

    def span(cells):
        got = [(_rw_dmy(o), _rw_dmy(c)) for o, c in (window_dates(db, x, cid) for x in cells)]
        got = [(o, c) for o, c in got if o and c]
        return (min(o for o, _c in got), max(c for _o, c in got)) if got else None
    out = []
    for who, cells, kind, lang in (("Grade H staff \u00b7 EN", ("gradeh_kpi",), "kpi", "en"),
                                   ("Grade H staff \u00b7 BM", ("gradeh_ack",), "ack", "bm"),
                                   ("Grade H line managers", ("gradeh_lm",), "gradeh_lm", "en"),
                                   ("HODs \u00b7 Grade H", ("gradeh_hod_pot", "gradeh_hod_perf"), "gradeh_hod", "en"),
                                   ("BU CEOs \u00b7 Grade H", ("gradeh_buceo",), "gradeh_buceo", "en")):
        sp = span(cells)
        if not sp:
            continue
        a, b = sp
        close = datetime.combine(b, datetime.min.time()).replace(hour=23, minute=59)
        if kind in ("kpi", "ack"):
            n = min(rules["days"], (b - a).days) + 1   # what a person reads on the first day the bar shows; today counts
            lead = gh_t(lang, "dl_%s_lead" % kind, d=_gh_dl_when(close, lang))
            body = gh_t(lang, "dl_kpi_body_1" if (kind == "kpi" and n == 1) else "dl_%s_body" % kind, n=n)
            tm = _gh_time(close, lang) if lang == "bm" else close.strftime("%H:%M")
            last_lead, last_body = gh_t(lang, "dl_%s_last" % kind, t=tm), gh_t(lang, "dl_%s_last_body" % kind)
        else:
            lead, body = gradeh_lead_deadline_words(kind, b, min(rules["days"], (b - a).days), n_ready=3)
            last_lead, last_body = gradeh_lead_deadline_words(kind, b, 0, n_ready=3)
        out.append({"who": who, "dates": _rw_span(a, b), "lead": lead, "body": body, "last_lead": last_lead,
                    "last_body": last_body, "last_day": "%s %d %s" % (b.strftime("%a"), b.day, b.strftime("%b"))})
    return out


def _bar_ann_roles(db, u):
    """The roles a signed-in person holds, for an announcement to picked roles."""
    if is_admin(u):
        return {"admin"}
    uid = u["id"]
    one = lambda sql, *a: db.execute(sql, a).fetchone() is not None   # noqa: E731
    out = {"employee"}
    if one("SELECT 1 FROM users WHERE manager_id=? AND left_at IS NULL AND role!='admin' LIMIT 1", uid):
        out.add("lm")
    if one("SELECT 1 FROM users WHERE hod_id=? AND left_at IS NULL AND role!='admin' LIMIT 1", uid) and \
            _hod_ids_with_review(db, [uid]):   # not a calibrator (2026-10-30)
        out.add("hod")
    if one("SELECT 1 FROM buceo_seats WHERE user_id=? LIMIT 1", uid) or one(
            "SELECT 1 FROM calib_bu_groups WHERE calibrator_id=? AND active=1 LIMIT 1", uid):
        out.add("buceo")
    if (_row_get(u, "bgceo_bg") or "").strip() or one(
            "SELECT 1 FROM pm_calibration_groups WHERE calibrator_id=? LIMIT 1", uid):
        out.add("bgceo")
    return out


def _bar_part_button(db, u, cyc, open_cells):
    """'Their own part': the person's most direct part open now, or None (nothing of theirs open, or an admin)."""
    if not cyc or is_admin(u):
        return None
    mine = _pill_my_cells(db, u, cyc) & open_cells
    for cells, label, kw in _BAR_PART_LINKS:
        if mine & set(cells):
            return {"label": label, "url": url_for("review_journey", **kw)}
    return None


def _bar_cycle(db, a=None):
    """The cycle an announcement follows: the one it was posted in, else the active one."""
    cid = _row_get(a, "cycle_id") if a is not None else None
    return (db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone() if cid else None) or active_cycle(db)


def _bar_cycle_opens(db, cyc):
    """The day the cycle's first part opens on its calendar (a date), or None while nothing is dated."""
    if not cyc:
        return None
    days = [_rw_dmy(window_dates(db, c, cyc["id"])[0] or "") for c in _cycle_cells_used(cyc)]
    return min((d for d in days if d), default=None)


def _bar_part_dates(db, cyc, part):
    """(first day, last day) of a part on the cycle's calendar, or (None, None) while it isn't dated."""
    if not cyc or part not in BAR_ANN_PART:
        return None, None
    spans = [(_rw_dmy(o or ""), _rw_dmy(c or "")) for o, c in (window_dates(db, x, cyc["id"])
                                                                 for x in BAR_ANN_PART[part][3])]
    spans = [(o, c) for o, c in spans if o and c]
    return (min(o for o, _c in spans), max(c for _o, c in spans)) if spans else (None, None)


def bar_ann_window(db, a):
    """(start, end) in MYT that an announcement shows, read from its timing every time, or None while the calendar
    can't say: until the cycle opens ends at 23:59 the day before its first part opens; while a part is open runs from
    its first day 00:00 to its last 23:59; dates by hand are as stored."""
    timing = _row_get(a, "timing") or "dates"
    start, end = _bar_hm(a["starts_at"]), _bar_hm(a["ends_at"])
    if timing == "until_open":
        d = _bar_cycle_opens(db, _bar_cycle(db, a))
        if d:
            end = datetime(d.year, d.month, d.day) - timedelta(minutes=1)
    elif timing == "part":
        o, c = _bar_part_dates(db, _bar_cycle(db, a), a["part"])
        if not o:
            return None
        start, end = datetime(o.year, o.month, o.day), datetime(c.year, c.month, c.day, 23, 59)
    return (start, end) if start and end else None


def _bar_day(d):
    return "%s %d %s" % (d.strftime("%a"), d.day, d.strftime("%b"))


def bar_ann_fill(db, a, text):
    """{dates}, {opens} and {closes} in an announcement's words, from the calendar it follows: a part's dates ('2 – 8
    Nov'), the day the cycle opens, or its own dates by hand. Left as written while nothing is dated."""
    if "{" not in (text or ""):
        return text
    timing = _row_get(a, "timing") or "dates"
    if timing == "part":
        o, c = _bar_part_dates(db, _bar_cycle(db, a), a["part"])
        dates = _rw_span(o, c) if o else None
    elif timing == "until_open":
        o = c = _bar_cycle_opens(db, _bar_cycle(db, a))
        dates = ("from " + _bar_day(o)) if o else None
    else:
        w = bar_ann_window(db, a)
        o, c = (w[0].date(), w[1].date()) if w else (None, None)
        dates = _rw_span(o, c) if o else None
    if not o:
        return text
    return text.replace("{dates}", dates).replace("{opens}", _bar_day(o)).replace("{closes}", _bar_day(c))


def bar_place(endpoint=None, path=None):
    """Which of an announcement's pages this one is: the dashboard (and My Appraisal, which is Grade H staff's home:
    Chris, 2026-10-28), the AI+ check-in (/review: the journey and the leaders' views), an admin page, or every other
    page. The sign-in pages are 'signin' (the context processor)."""
    endpoint = request.endpoint if endpoint is None else endpoint
    path = request.path if path is None else path
    if endpoint in ("dashboard", "my_appraisal"):
        return "dashboard"
    if path == "/review" or path.startswith("/review/"):
        return "checkin"
    if path == "/admin" or path.startswith("/admin/"):
        return "admin"
    return "other"


def _gh_leader_page():
    """Is this request one of Grade H's leader pages (the appraiser's /review/gradeh, the calibration pages)?"""
    if not has_request_context():
        return False
    p = request.path
    return any(p == x or p.startswith(x + "/") for x in ("/review/gradeh", "/calibration/gradeh"))


def bar_ann_places(a):
    """The pages an announcement shows on, as a set of BAR_PLACES keys. One posted before it had pages (26 Oct): the
    sign-in page if it was written or ticked for it, and the dashboard if it was for people signed in (Chris,
    2026-10-26: "keep it permanent on login page and dashboard only"). The sign-in page only ever for Everyone."""
    raw = _row_get(a, "places")
    got = {p for p in (raw or "").split(",") if p in BAR_PLACE}
    if not got:
        if a["audience"] == "signin":
            return {"signin"}
        got = {"dashboard"} | ({"signin"} if (a["audience"] == "everyone" and _row_get(a, "on_signin")) else set())
    if a["audience"] not in ("everyone", "signin"):
        got.discard("signin")
    return got


def bar_ann_where(a):
    """'Sign-in page and dashboard' / 'Dashboard, AI+ check-in and admin pages' for one announcement."""
    names = [label for k, label, _h in BAR_PLACES if k in bar_ann_places(a)]
    names = names[:1] + [n if n.startswith("AI+") else n[:1].lower() + n[1:] for n in names[1:]]
    return (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]) if names else "Nowhere"


def bar_link_targets(db):
    """Every page a button can open, for Banner's picker: [{key, name, kind, words}], OneHR's pages first, then AI+
    Learning's and its published programmes by name while Learning is on."""
    out = [{"key": k, "name": n, "kind": "Page", "words": w} for k, n, w, _f in _BAR_LINK_PAGES]
    if lms_on():
        out += [{"key": k, "name": n, "kind": "AI+ Learning", "words": w} for k, n, w, _f in _BAR_LINK_LEARNING]
        try:
            out += [{"key": "prog:%d" % p["id"], "name": p["title"], "kind": "Learning programme",
                     "words": "View the programme"} for p in db.execute(
                "SELECT id, title FROM lms_programmes WHERE status='published' ORDER BY title COLLATE NOCASE")]
        except sqlite3.Error:
            pass
    return out


def bar_link_url(db, key):
    """The page a button's pick opens now, or None: a programme no longer published, or Learning switched off, takes
    the button away rather than leading somewhere that isn't there."""
    key = key or ""
    for k, _n, _w, f in _BAR_LINK_PAGES:
        if k == key:
            return f()
    if not lms_on():
        return None
    for k, _n, _w, f in _BAR_LINK_LEARNING:
        if k == key:
            return f()
    m = re.fullmatch(r"prog:(\d+)", key)
    if not m:
        return None
    try:
        ok = db.execute("SELECT 1 FROM lms_programmes WHERE id=? AND status='published'", (int(m.group(1)),)).fetchone()
    except sqlite3.Error:
        ok = None
    return url_for("learning_programme", pid=int(m.group(1))) if ok else None


def bar_link_name(db, key):
    """The pick's name as the picker lists it, or None once it's gone from the list."""
    return next((t["name"] for t in bar_link_targets(db) if t["key"] == key), None)


def bar_ann_live(db, now=None):
    """The announcements showing now, newest first, each by the window its timing gives today."""
    now = now or _now_myt()
    live = []
    for a in db.execute("SELECT * FROM site_announcements WHERE status='live'"):
        w = bar_ann_window(db, a)
        if w and w[0] <= now < w[1] + timedelta(minutes=1):
            live.append((w[0], a["id"], a))
    live.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return [a for _s, _i, a in live]


def _bar_ann_item(db, a, button=None, signin=False):
    return {"key": "a%d.%d" % (a["id"], a["version"]), "kind": "ann", "icon": "mega",
            "lead": bar_ann_fill(db, a, a["headline"]), "body": bar_ann_fill(db, a, a["message"]), "red": False,
            "button": None if signin else button}


def bar_items(db, u=None, auth=False, now=None, place="other"):
    """What the bar says on this page (`place`, a BAR_PLACES key) besides a notice, in order: a deadline reminder on
    its last day (red, first), the live announcements meant for this person and posted for this page (newest first),
    then their deadline reminder where it's set to show. The sign-in page, or anyone not signed in, gets only the
    announcements posted for it. [] while a notice before OneHR closes is current: it stands alone."""
    now = now or _now_myt()
    place = "signin" if (auth or not u) else (place if place in BAR_PLACE else "other")
    try:
        if notice_current(db, now):
            return []
        rows = [a for a in bar_ann_live(db, now) if place in bar_ann_places(a)]
    except sqlite3.Error:
        return []
    if place == "signin":
        return [_bar_ann_item(db, a, signin=True) for a in rows]
    cyc = active_cycle(db)
    open_cells = set(_notice_open_cells(db, cyc, now)) if cyc else set()
    mine, roles, out = None, None, []
    for a in rows:
        aud = a["audience"]
        if aud == "signin":
            continue
        if aud == "open":
            if mine is None:
                mine = _pill_my_cells(db, u, cyc) if (cyc and not is_admin(u)) else set()
            if not (mine & open_cells):
                continue
        elif aud == "roles":
            if roles is None:
                roles = _bar_ann_roles(db, u)
            try:
                want = set(json.loads(a["roles"] or "[]"))
            except (TypeError, ValueError):
                want = set()
            if not (roles & want):
                continue
        button = None
        if a["button"] == "profile" and not is_admin(u):
            button = {"label": "Check my details", "url": url_for("my_settings")}
        elif a["button"] == "help":
            button = {"label": "Get Help", "help": True}
        elif a["button"] == "part":
            button = _bar_part_button(db, u, cyc, open_cells)
        elif _row_get(a, "link_target") and _row_get(a, "link_label"):
            url = bar_link_url(db, a["link_target"])
            button = {"label": a["link_label"], "url": url} if url else None
        out.append(_bar_ann_item(db, a, button))
    try:
        # the Grade H pages (the appraiser's, the HOD's and the BU CEO's) show a leader's Grade H line whichever pages are ticked
        gh_page = gradeh_on() and _gh_leader_page()
        in_places = place in deadline_rules()["places"]
        dl = deadline_item(db, u, now, place, only_gh=(gh_page and not in_places)) if (in_places or gh_page) else None
    except sqlite3.Error:
        dl = None
    if dl:
        out = [dl] + out if dl["red"] else out + [dl]
    return out


def _bar_hm(raw):
    """'YYYY-MM-DD HH:MM' (MYT) as a datetime, or None."""
    try:
        return datetime.strptime(raw or "", "%Y-%m-%d %H:%M")
    except ValueError:
        return None


def _bar_when(raw, now=None):
    """'Mon 26 Oct, 15:10' for a stored MYT time."""
    d = _bar_hm(raw)
    return "%s %d %s, %s" % (d.strftime("%a"), d.day, d.strftime("%b"), d.strftime("%H:%M")) if d else ""


def bar_ann_form(form, now, db=None):
    """(values, None) from Post an announcement's form, or (None, what's wrong). Its timing follows the calendar of the
    active cycle (until it opens, or while a part is open) or takes dates by hand."""
    head = " ".join((form.get("headline") or "").split())
    msg = " ".join((form.get("message") or "").split())
    if not head:
        return None, "Write a headline."
    if len(head) > BAR_ANN_HEADLINE_MAX:
        return None, "Keep the headline to %d characters." % BAR_ANN_HEADLINE_MAX
    if not msg:
        return None, "Write the message."
    if len(msg) > BAR_ANN_MESSAGE_MAX:
        return None, "Keep the message to %d characters." % BAR_ANN_MESSAGE_MAX
    aud = form.get("audience") or ""
    if form.get("places_sent"):
        places = [k for k, _l, _h in BAR_PLACES if k in form.getlist("places")]
    else:   # a page open from before it had pages: as it was then, the dashboard and the sign-in page if ticked
        places = ["signin"] * (aud == "everyone" and form.get("on_signin") == "1") + list(BAR_PLACES_DEFAULT)
    if aud == "signin":   # Sign-in page only, as it was: Everyone, on the sign-in page
        aud, places = "everyone", ["signin"]
    if aud not in dict(BAR_ANN_AUDIENCES):
        return None, "Pick who sees it."
    roles = [r for r in form.getlist("roles") if r in BAR_ANN_ROLE] if aud == "roles" else []
    if aud == "roles" and not roles:
        return None, "Tick at least one role."
    if "signin" in places and aud != "everyone":
        return None, "The sign-in page is only for Everyone: before signing in, OneHR doesn't know anyone's role."
    if not places:
        return None, "Tick at least one page it shows on."
    button = form.get("button") if form.get("button") in dict(BAR_ANN_BUTTONS) else "none"
    if places == ["signin"]:
        button = "none"   # nobody is signed in there: nothing of theirs to open
    link_label = link_target = None
    if button == "link":   # stored as 'none' plus its words and the pick (the column's CHECK is older than the link)
        link_label = " ".join((form.get("link_label") or "").split())
        if not link_label:
            return None, "Write the button's words."
        if len(link_label) > BAR_LINK_LABEL_MAX:
            return None, "Keep the button's words to %d characters." % BAR_LINK_LABEL_MAX
        link_target = (form.get("link_target") or "").strip()
        if not link_target:
            return None, "Pick the page the button opens."
        if db is None or not bar_link_url(db, link_target):
            return None, "Pick the page from the list: that one isn't there."
        button = "none"
    timing = form.get("timing") or "dates"
    if timing not in BAR_ANN_TIMING:
        return None, "Pick when it shows."
    hm = re.compile(r"([01]\d|2[0-3]):[0-5]\d")
    part, cyc = None, None
    if timing == "dates":
        fd, ft = _rw_dmy(form.get("from_date", "")), form.get("from_time", "")
        if not fd:
            return None, "Pick the date it shows from."
        if ft == "now":
            start = now.replace(second=0, microsecond=0) if fd <= now.date() else datetime(fd.year, fd.month, fd.day)
        elif hm.fullmatch(ft or ""):
            start = datetime(fd.year, fd.month, fd.day, int(ft[:2]), int(ft[3:]))
        else:
            return None, "Pick the time it shows from."
        ud, ut = _rw_dmy(form.get("until_date", "")), form.get("until_time", "")
        if not ud or not hm.fullmatch(ut or ""):
            return None, "Pick the date and time it ends."
        end = datetime(ud.year, ud.month, ud.day, int(ut[:2]), int(ut[3:]))
        if end <= start:
            return None, "Pick an end after it starts."
        if end <= now:
            return None, "Pick an end later than now."
        if (end - start).days > BAR_ANN_DAYS_MAX:
            return None, "An announcement runs at most %d days. Post another one after it." % BAR_ANN_DAYS_MAX
    else:
        cyc = active_cycle(db) if db is not None else None
        if not cyc:
            return None, "No cycle is running, so there's no calendar to follow: pick dates by hand."
        if timing == "until_open":
            d = _bar_cycle_opens(db, cyc)
            if not d:
                return None, "The cycle has no part dated on its calendar yet: pick dates by hand."
            start = now.replace(second=0, microsecond=0)
            end = datetime(d.year, d.month, d.day) - timedelta(minutes=1)
            if end <= now:
                return None, "The cycle has already opened."
        else:
            part = form.get("part") or ""
            if part not in BAR_ANN_PART:
                return None, "Pick the part it follows."
            o, c = _bar_part_dates(db, cyc, part)
            if not o:
                return None, "That part has no dates on the calendar yet."
            start, end = datetime(o.year, o.month, o.day), datetime(c.year, c.month, c.day, 23, 59)
            if end <= now:
                return None, "That part has already closed."
    return {"headline": head, "message": msg, "audience": aud, "roles": json.dumps(roles) if roles else None,
            "on_signin": 1 if "signin" in places else 0, "places": ",".join(places), "button": button,
            "link_label": link_label, "link_target": link_target,
            "starts_at": start.strftime("%Y-%m-%d %H:%M"), "ends_at": end.strftime("%Y-%m-%d %H:%M"),
            "timing": timing, "part": part, "cycle_id": cyc["id"] if cyc else None}, None


def bar_ann_who(a):
    """'Everyone' / 'HODs and BU CEOs' / … for one announcement (where it shows: bar_ann_where)."""
    if a["audience"] == "roles":
        try:
            names = [BAR_ANN_ROLE[r] for r in json.loads(a["roles"] or "[]") if r in BAR_ANN_ROLE]
        except (TypeError, ValueError):
            names = []
        return (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]) if names else "Nobody"
    return BAR_ANN_AUDIENCE.get(a["audience"], a["audience"])


def bar_ann_save(db, me, form, aid=None):
    """Post an announcement, or change one that hasn't ended (its version goes up). (ok, what to say)."""
    now = _now_myt()
    v, err = bar_ann_form(form, now, db)
    if err:
        return False, err
    cols = ("headline", "message", "audience", "roles", "on_signin", "places", "button", "link_label", "link_target",
            "starts_at", "ends_at", "timing", "part", "cycle_id")
    if aid:
        a = db.execute("SELECT * FROM site_announcements WHERE id=? AND status='live'", (aid,)).fetchone()
        if not a:
            return False, "That announcement has ended."
        db.execute("UPDATE site_announcements SET %s, version=version+1, updated_by=?, updated_at=datetime('now') "
                   "WHERE id=?" % ", ".join("%s=?" % c for c in cols), [v[c] for c in cols] + [me["id"], aid])
        log_activity(db, me["id"], "bar_announce_change", "#%d %s · %s · %s · %s – %s" % (
            aid, v["headline"], bar_ann_who(v), bar_ann_where(v), v["starts_at"], v["ends_at"]))
        said = "Changed. It reads the new way at everyone's next page."
    else:
        cur = db.execute("INSERT INTO site_announcements(%s, created_by) VALUES (%s)" % (
            ", ".join(cols), ", ".join("?" * (len(cols) + 1))), [v[c] for c in cols] + [me["id"]])
        aid = cur.lastrowid
        log_activity(db, me["id"], "bar_announce_post", "#%d %s · %s · %s · %s – %s" % (
            aid, v["headline"], bar_ann_who(v), bar_ann_where(v), v["starts_at"], v["ends_at"]))
        said = "Posted. It shows on the %s from %s until %s%s." % (
            bar_ann_where(v).replace("Sign-in", "sign-in").replace("Dashboard", "dashboard").replace(
                "Admin", "admin").replace("Every", "every"), _bar_when(v["starts_at"]), _bar_when(v["ends_at"]),
            ", and moves with the calendar" if v["timing"] != "dates" else "")
    db.commit()
    return True, said


def bar_ann_end(db, me, aid):
    """End an announcement now (it leaves the bar at everyone's next page or within five minutes)."""
    a = db.execute("SELECT * FROM site_announcements WHERE id=? AND status='live'", (aid,)).fetchone()
    if not a:
        return False, "That announcement has already ended."
    db.execute("UPDATE site_announcements SET status='ended', ended_by=?, ended_at=datetime('now') WHERE id=?",
               (me["id"], aid))
    log_activity(db, me["id"], "bar_announce_end", "#%d %s" % (aid, a["headline"]))
    db.commit()
    return True, "Ended. It leaves the bar at everyone's next page."


def bar_ann_view(db, a, now):
    """One announcement as Admin › Notices lists it."""
    w = bar_ann_window(db, a)
    timing = _row_get(a, "timing") or "dates"
    state = ("ended" if a["status"] == "ended" or (w and now >= w[1] + timedelta(minutes=1)) else
             "showing" if w and w[0] <= now else "coming")
    s, e = (w if w else (_bar_hm(a["starts_at"]), _bar_hm(a["ends_at"])))
    fmt = lambda d: "%s %d %s, %s" % (d.strftime("%a"), d.day, d.strftime("%b"), d.strftime("%H:%M")) if d else ""  # noqa: E731
    if timing == "part":
        when_label = "While the %s is open" % BAR_ANN_PART.get(a["part"], ("", "", "part"))[2]
        when_span = _rw_span(s.date(), e.date()) if w else "Not dated on the calendar yet"
    elif timing == "until_open":
        when_label, when_span = "Until the cycle opens", ("%s – %s" % (fmt(s), fmt(e)) if w else "")
    else:
        when_label, when_span = fmt(s), "until " + fmt(e)
    try:
        roles = json.loads(a["roles"] or "[]")
    except (TypeError, ValueError):
        roles = []
    return {"id": a["id"], "headline": a["headline"], "message": a["message"], "audience": a["audience"],
            "roles": roles, "places": sorted(bar_ann_places(a)), "where": bar_ann_where(a),
            "audience_form": "everyone" if a["audience"] == "signin" else a["audience"],
            "button": "link" if _row_get(a, "link_target") else a["button"],
            "link_label": _row_get(a, "link_label") or "", "link_target": _row_get(a, "link_target") or "",
            "link_name": (bar_link_name(db, a["link_target"]) or "No longer there") if _row_get(a, "link_target")
            else "",
            "state": state,
            "who": bar_ann_who(a), "from": _bar_when(a["starts_at"]), "until": _bar_when(a["ends_at"]),
            "timing": timing, "part": a["part"] or "", "when_label": when_label, "when_span": when_span,
            "headline_shown": bar_ann_fill(db, a, a["headline"]), "message_shown": bar_ann_fill(db, a, a["message"]),
            "from_date": s.date().isoformat() if s else "", "from_time": s.strftime("%H:%M") if s else "",
            "until_date": e.date().isoformat() if e else "", "until_time": e.strftime("%H:%M") if e else "",
            "by": "Super admin",   # only the super admin posts one (Admin › Notices)
            "button_label": dict(BAR_ANN_BUTTONS).get(a["button"], "None")}


# --- What's new, the release log (Chris, 2026-11-03: "Approve, build it"; "Super admin only"; canvas
# [design canvas link removed] boards F1, P1, P2, M1, M2, S1, S2, S3) -----------------------------------
# A note is about ONE user-facing feature (never an admin or back-end change); the feature decides who sees it. The audiences
# are written here in code, each beside the feature's OWN gate (WN_AUDIENCES: key, label, words, predicate, count): the
# predicate CALLS the gate the feature itself uses and never copies it, so a note can't reach someone who can't use the
# feature. A new user-facing feature adds its row in the same change. Only the super admin and the system admin (who is one)
# write, publish, take down and put back (Admin › Comms › What's new); nothing is ever deleted.
#   * a person sees a note that is `live`, whose `shows_from` has come, and whose audience predicate is true for their REAL
#     account (never a demo persona);
#   * it pops out ONCE (dashboard for staff, admin Home for admins; never the AI+ check-in): unseen = shows_from after the
#     person's users.whatsnew_seen_at AND no whatsnew_seen row. Closing the box, or opening the panel, stamps both
#     (_wn_mark_seen, the one writer). A first sign-in sets whatsnew_seen_at (_wn_signed_in), so nothing published before pops;
#   * editing a published note never re-pops it; put back does not pop it for anyone who has seen it.
WN_TITLE_MAX = 60
WN_BODY_MAX = 600
WN_STATE_LABEL = {"draft": "Draft", "sched": "Scheduled", "live": "Showing", "down": "Taken down"}
WN_EMPTY = "Nothing new yet. When AI+ OneHR adds something you can use, it shows here."
# the navy tile's icon, by audience (mega = the notice bar's own megaphone); a new audience may add one
WN_ICONS = {"subs": "list", "idle": "clock", "lm": "list"}


def _is_team_manager(db, uid, cid):
    """Does this person lead anyone in the cycle: the Team tab's own test (the context processor's nav_is_manager, and What's
    new's `lm` audience). A report who is confirmed, not a demo account and on a 360 panel in the cycle."""
    return bool(db.execute("SELECT 1 FROM users WHERE manager_id=? AND role!='admin' AND %s LIMIT 1" % team_hod_member_sql(),
                           (uid, cid)).fetchone())


def _wn_cands(db):
    """The accounts that could hold a Who has submitted seat (an HOD, a BU CEO, a calibrator, a BG CEO, a Group Chief), once
    a request: the candidate set a per-person gate is evaluated over for a count."""
    cache = _req_cache()
    if "_wn_cands" not in cache:
        sql = ("SELECT * FROM users WHERE role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0 AND ("
               "id IN (SELECT hod_id FROM users WHERE hod_id IS NOT NULL) OR id IN (SELECT user_id FROM buceo_seats) OR "
               "COALESCE(bgceo_bg,'')!='' OR COALESCE(buceo_company,'')!=''")
        for extra in ("id IN (SELECT calibrator_id FROM calib_bu_groups WHERE active=1 AND calibrator_id IS NOT NULL)",
                      "id IN (SELECT calibrator_id FROM pm_calibration_groups WHERE calibrator_id IS NOT NULL)"):
            try:
                db.execute("SELECT 1 FROM users WHERE " + extra + " LIMIT 1")
                sql += " OR " + extra
            except sqlite3.OperationalError:   # a database from before the table
                pass
        cache["_wn_cands"] = db.execute(sql + ")").fetchall()
    return cache["_wn_cands"]


def _wn_g_everyone(db, u):
    return bool(u) and not is_admin(u)


def _wn_g_subs(db, u):
    return bool(lp_subs_scope_defs(db, u))


def _wn_g_idle(db, u):
    return bool(u) and _idle_applies(u)


def _wn_g_lm(db, u):
    cid = active_cycle_id(db)
    return bool(u) and not is_admin(u) and bool(cid) and _is_team_manager(db, u["id"], cid)


def _wn_g_gradeh(db, u):
    return bool(gradeh_staff_person(db, u))


def _wn_n_everyone(db):
    return db.execute("SELECT COUNT(*) FROM users WHERE role!='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0").fetchone()[0]


def _wn_n_subs(db):
    return sum(1 for r in _wn_cands(db) if _wn_g_subs(db, r))


def _wn_n_idle(db):
    """Staff (every staff account is covered while the limit is on) plus the admins _idle_applies says are covered: a handful of
    rows, so the gate itself is asked of each."""
    n = _wn_n_everyone(db) if SESSION_IDLE_MIN else 0
    return n + sum(1 for r in db.execute("SELECT * FROM users WHERE role='admin' AND left_at IS NULL AND COALESCE(is_demo,0)=0")
                   if _idle_applies(r))


def _wn_n_lm(db):
    cid = active_cycle_id(db)
    if not cid:
        return 0
    return db.execute("SELECT COUNT(*) FROM users m WHERE m.role!='admin' AND m.left_at IS NULL AND COALESCE(m.is_demo,0)=0 AND "
                      "EXISTS (SELECT 1 FROM users x WHERE x.manager_id=m.id AND x.role!='admin' AND %s)"
                      % team_hod_member_sql("x"), (cid,)).fetchone()[0]


def _wn_n_gradeh(db):
    cid = active_cycle_id(db)
    if not (gradeh_on() and cid and gradeh_module_on(db, cid)):
        return 0
    return db.execute("SELECT COUNT(*) FROM gradeh_people p JOIN users u ON u.id=p.user_id WHERE p.cycle_id=? AND "
                      "p.private_company=0 AND u.left_at IS NULL AND u.role!='admin'", (cid,)).fetchone()[0]


WN_AUDIENCES = (
    ("everyone", "Everyone who uses AI+ OneHR", "Every staff account, not admin accounts.", _wn_g_everyone, _wn_n_everyone),
    ("subs", "Leaders who can see Who has submitted",
     "HODs, BU CEOs, calibrators, BG CEOs and Group Chiefs whose \"See who has submitted\" is on.", _wn_g_subs, _wn_n_subs),
    ("idle", "Everyone signed out after an hour",
     "Staff, and admins whose role has Inactivity sign-out on. Never the super admin, system admin or L&D admin.",
     _wn_g_idle, _wn_n_idle),
    ("lm", "Line managers", "Anyone with people reporting to them in this cycle.", _wn_g_lm, _wn_n_lm),
    ("gradeh", "Grade H staff", "Only while the Grade H Appraisal module is on.", _wn_g_gradeh, _wn_n_gradeh),
)
WN_AUDIENCE = {a_[0]: a_ for a_ in WN_AUDIENCES}


def wn_audience_counts(db):
    """{key: {n, off}}: how many accounts each audience reaches today, one batched read each (never a model, never one query a
    person except the per-person gate over its candidate set), once a request. `off` = the feature's module is off."""
    cache = _req_cache()
    if "_wn_counts" not in cache:
        out = {}
        for key, _lab, _words, _pred, count in WN_AUDIENCES:
            out[key] = {"n": int(count(db)), "off": False}
        cid = active_cycle_id(db)
        out["gradeh"]["off"] = not (gradeh_on() and cid and gradeh_module_on(db, cid))
        cache["_wn_counts"] = out
    return cache["_wn_counts"]


def _wn_verdict(db, u, key):
    """Is this audience's gate true for this REAL account? Asked once a request for each (account, audience)."""
    a_ = WN_AUDIENCE.get(key)
    if not a_ or not u:
        return False
    cache = _req_cache()
    ck = ("_wn_v", u["id"], key)
    if ck not in cache:
        cache[ck] = bool(a_[3](db, u))
    return cache[ck]


def wn_visible(db, u):
    """The notes this REAL account may read now, newest first: live, their time has come, and their audience's own gate says
    yes. A draft, a scheduled note before its time and a taken-down one show to nobody."""
    if not u:
        return []
    now = _utc_str_now()
    return [n for n in db.execute("SELECT * FROM whatsnew_notes WHERE state='live' AND shows_from IS NOT NULL AND "
                                  "shows_from<=? ORDER BY shows_from DESC, id DESC", (now,))
            if _wn_verdict(db, u, n["audience"])]


def wn_unseen(db, u):
    """The visible notes the pop-out still owes this person: shown after their whatsnew_seen_at (NULL = never signed in since the
    log was built: nothing) and with no seen row. ONE cheap query decides, so a page with nothing new pays for nothing else
    (the account menu's count asks this on every page); a gate is asked only of the notes that come back."""
    since = _row_get(u, "whatsnew_seen_at") if u else None
    if not u or not since:
        return []
    cache = _req_cache()
    ck = ("_wn_unseen", u["id"], since)
    if ck not in cache:
        cache[ck] = [n for n in db.execute(
            "SELECT n.* FROM whatsnew_notes n WHERE n.state='live' AND n.shows_from<=? AND n.shows_from>? AND NOT EXISTS "
            "(SELECT 1 FROM whatsnew_seen s WHERE s.note_id=n.id AND s.user_id=?) ORDER BY n.shows_from DESC, n.id DESC",
            (_utc_str_now(), since, u["id"])) if _wn_verdict(db, u, n["audience"])]
    return cache[ck]


def _wn_mark_seen(db, u, ids):
    """THE writer of what a person has seen (the pop-out's close and the panel's open both call it): a seen row for each of
    `ids` that is really visible to them, and their whatsnew_seen_at = now. Returns the ids stamped."""
    if not u:
        return []
    now = _utc_str_now()
    ok = {n["id"] for n in wn_visible(db, u)}
    took = [i for i in dict.fromkeys(ids) if i in ok]
    for i in took:
        db.execute("INSERT OR IGNORE INTO whatsnew_seen(note_id, user_id, seen_at) VALUES (?,?,?)", (i, u["id"], now))
    db.execute("UPDATE users SET whatsnew_seen_at=? WHERE id=?", (now, u["id"]))
    db.commit()
    return took


def _wn_signed_in(db, uid):
    """Every successful sign-in (_session_start, the one place a session is made) calls this: a person who has never had a
    stamp gets one now, so a note published before their first sign-in never pops for them (it is in their list, not new)."""
    db.execute("UPDATE users SET whatsnew_seen_at=? WHERE id=? AND whatsnew_seen_at IS NULL", (_utc_str_now(), uid))
    db.commit()


def _wn_day(raw):
    """'5 Nov 2026' (MYT) from a stored UTC time."""
    dt = _parse_when(_myt(raw))
    return "%d %s %d" % (dt.day, dt.strftime("%b"), dt.year) if dt else ""


def _wn_view(db, n, new=False):
    """One note as the pop-out, the panel and the admin preview draw it: the tile, the words, and the button (its page now,
    or none if that page has gone)."""
    url = bar_link_url(db, n["link_target"]) if n["link_target"] else None
    return {"id": n["id"], "title": n["title"], "body": n["body"], "icon": WN_ICONS.get(n["audience"], "mega"), "new": bool(new),
            "link": {"label": n["link_label"] or "Open", "url": url} if url else None}


def wn_list(db, u):
    """({days: [{label, iso, new, notes: [view]}]}, [new ids]) for this REAL account: their notes newest first, grouped by the
    day they were published (MYT). A note is new while unseen (wn_unseen's rule). Writes nothing."""
    since = _row_get(u, "whatsnew_seen_at")
    seen = {r[0] for r in db.execute("SELECT note_id FROM whatsnew_seen WHERE user_id=?", (u["id"],))}
    days, new_ids = [], []
    for n in wn_visible(db, u):
        new = bool(since) and n["shows_from"] > since and n["id"] not in seen
        if new:
            new_ids.append(n["id"])
        label = _wn_day(n["shows_from"])
        if not days or days[-1]["label"] != label:
            days.append({"label": label, "iso": _myt(n["shows_from"])[:10], "new": False, "notes": []})
        days[-1]["notes"].append(_wn_view(db, n, new))
        days[-1]["new"] = days[-1]["new"] or new
    return days, new_ids


def wn_popout(db):
    """What the dashboard and admin Home draw as the pop-out, or None: the REAL account's unseen notes. Never for a demo persona
    over another account, nor while the first sign-in steps (name, picture, tour) are due; only those two pages ask, so never
    the AI+ check-in."""
    actor = demo_actor()
    cur = current_user()
    if not actor or not cur or cur["id"] != actor["id"] or (not is_admin(actor) and onboarding_step(actor)):
        return None
    notes = wn_unseen(db, actor)
    if not notes:
        return None
    return {"notes": [_wn_view(db, n, True) for n in notes], "ids": ",".join(str(n["id"]) for n in notes),
            "date": _wn_day(notes[0]["shows_from"])}


def wn_unseen_count():
    """The account menu's count (base.html), on every page: how many notes are unseen for the real account. Cached for the
    request; the one cheap query of wn_unseen, so a page with nothing new asks nothing more."""
    actor = demo_actor() if session.get("user_id") else None
    return len(wn_unseen(get_db(), actor)) if actor else 0


@app.route("/me/whats-new")
@login_required
def whats_new_list():
    """The account menu's What's new panel: this person's notes, newest first, by the day each went out, as JSON. A GET that
    writes nothing (the panel's open posts /me/whats-new/seen itself)."""
    actor = demo_actor()
    days, new_ids = wn_list(get_db(), actor)
    return jsonify(ok=True, days=days, new_ids=new_ids, empty=WN_EMPTY)


@app.route("/me/whats-new/seen", methods=["POST"])
@login_required
def whats_new_seen():
    """The pop-out was closed, or the panel opened: stamp what the person has seen (ids of the notes drawn; only ones really
    visible to them count). The same writer for both."""
    ids = [int(x) for x in re.split(r"[,\s]+", request.form.get("ids", "")) if x.isdigit()][:100]
    took = _wn_mark_seen(get_db(), demo_actor(), ids)
    return jsonify(ok=True, seen=took)


def wn_form(db, form, note=None):
    """(values, None) from the note form, or (None, what is wrong). Over the limit is refused, never trimmed; the words go
    through the one stored-text screen; the audience is a WN_AUDIENCES key; the button a page in the Banner's list; once
    published the audience can't change. `shows_from` comes back as a UTC string, or None for "when I publish"."""
    title = " ".join((form.get("title") or "").split())
    body = " ".join((form.get("body") or "").split())
    if not title:
        return None, "Give the note a title."
    if len(title) > WN_TITLE_MAX:
        return None, "The title is over %d characters (it is %d). Shorten it." % (WN_TITLE_MAX, len(title))
    if not body:
        return None, "Write the words of the note."
    if len(body) > WN_BODY_MAX:
        return None, "The words are over %d characters (they are %d). Shorten them." % (WN_BODY_MAX, len(body))
    for t in (title, body):
        if _store_text(t)[1]:
            return None, STORE_TEXT_REFUSAL
    aud = (form.get("audience") or "").strip()
    if aud not in WN_AUDIENCE:
        return None, "Pick who the note is for, from the list."
    if note is not None and note["published_at"] and aud != note["audience"]:
        return None, "Who it's for can't change once a note is published. Write a new note to reach more people."
    link, label = None, None
    key = (form.get("link_target") or "").strip()
    if key:
        hit = next((t for t in bar_link_targets(db) if t["key"] == key), None)
        if not hit:
            return None, "Pick the button's page from the list."
        link, label = key, hit["words"][:BAR_LINK_LABEL_MAX]
    shows = None
    if form.get("shows") == "at":
        dt = _parse_when(form.get("shows_at") or "")
        if not dt:
            return None, "Pick the date and time it shows from, or choose When I publish."
        shows = _late_utc(dt)
    return {"title": title, "body": body, "audience": aud, "link_target": link, "link_label": label, "shows_from": shows}, None


def wn_save(db, me, form, nid=None, publish=False):
    """Write a note: a new draft, a change to one, or (publish=True) publish it. (ok, what to say, the note's id). A published
    note's change touches its words and button (and its time while it has not come): it never re-pops, and who it is for
    stays. Every change is audited."""
    note = db.execute("SELECT * FROM whatsnew_notes WHERE id=?", (nid,)).fetchone() if nid else None
    if nid and not note:
        return False, "That note was not found.", None
    if publish and note and note["state"] != "draft":
        return False, "That note is already published.", note["id"]
    v, err = wn_form(db, form, note)
    if err:
        return False, err, nid
    now = _utc_str_now()
    started = bool(note and note["state"] in ("live", "down") and note["shows_from"] and note["shows_from"] <= now)
    if started:   # its time has come: the time stays, so no one is shown it afresh
        v["shows_from"] = note["shows_from"]
    elif v["shows_from"] and v["shows_from"] < (_utc_now() - timedelta(minutes=2)).strftime("%Y-%m-%d %H:%M:%S") and (
            publish or (note and note["state"] != "draft")):
        return False, "Pick a time that has not passed, or choose When I publish.", nid
    cols = ("title", "body", "audience", "link_target", "link_label", "shows_from")
    if publish:
        v["shows_from"] = v["shows_from"] or now
        if note:
            db.execute("UPDATE whatsnew_notes SET %s, state='live', published_by=?, published_at=?, updated_by=?, updated_at=? "
                       "WHERE id=?" % ", ".join("%s=?" % c for c in cols), [v[c] for c in cols] + [me["id"], now, me["id"], now, nid])
        else:
            nid = db.execute("INSERT INTO whatsnew_notes(%s, state, created_by, published_by, published_at) VALUES (%s)" % (
                ", ".join(cols), ", ".join(["?"] * len(cols) + ["'live'", "?", "?", "?"])),
                [v[c] for c in cols] + [me["id"], me["id"], now]).lastrowid
        log_activity(db, me["id"], "whatsnew_publish", "#%d %s · %s · from %s" % (
            nid, v["title"], WN_AUDIENCE[v["audience"]][1], _late_disp(v["shows_from"])), commit=False)
        said = "Published. It shows from %s (Malaysia time)." % _late_disp(v["shows_from"]) if v["shows_from"] > now else \
            "Published. It pops out at each person's next visit."
    elif note:
        db.execute("UPDATE whatsnew_notes SET %s, updated_by=?, updated_at=? WHERE id=?" % ", ".join("%s=?" % c for c in cols),
                   [v[c] for c in cols] + [me["id"], now, nid])
        log_activity(db, me["id"], "whatsnew_change" if note["published_at"] else "whatsnew_save",
                     "#%d %s · %s" % (nid, v["title"], WN_AUDIENCE[v["audience"]][1]), commit=False)
        said = ("Changed. It reads the new way for everyone it is for, and does not pop out again."
                if note["published_at"] else "Saved as a draft. It shows to nobody until you publish it.")
    else:
        nid = db.execute("INSERT INTO whatsnew_notes(%s, state, created_by) VALUES (%s)" % (
            ", ".join(cols), ", ".join(["?"] * len(cols) + ["'draft'", "?"])), [v[c] for c in cols] + [me["id"]]).lastrowid
        log_activity(db, me["id"], "whatsnew_save", "#%d %s · %s" % (nid, v["title"], WN_AUDIENCE[v["audience"]][1]),
                     commit=False)
        said = "Saved as a draft. It shows to nobody until you publish it."
    db.commit()
    return True, said, nid


def wn_set_state(db, me, nid, to):
    """Take a showing note down ('down') or put a taken-down one back ('live'). Never a delete; the seen rows stay, so a
    put-back does not pop it for anyone who has seen it. (ok, what to say)."""
    n = db.execute("SELECT * FROM whatsnew_notes WHERE id=?", (nid,)).fetchone()
    if not n:
        return False, "That note was not found."
    if to == "down" and n["state"] != "live":
        return False, "That note is not showing."
    if to == "live" and (n["state"] != "down" or not n["published_at"]):
        return False, "That note is not taken down."
    db.execute("UPDATE whatsnew_notes SET state=?, updated_by=?, updated_at=? WHERE id=?", (to, me["id"], _utc_str_now(), nid))
    log_activity(db, me["id"], "whatsnew_takedown" if to == "down" else "whatsnew_putback", "#%d %s" % (nid, n["title"]),
                 commit=False)
    db.commit()
    return True, ("Taken down. It has left everyone's What's new." if to == "down"
                  else "Put back. It is in everyone's What's new again; it does not pop out again for anyone who has seen it.")


def wn_state_of(n, now=None):
    """'draft' | 'sched' | 'live' | 'down' for a row: Scheduled is a live note whose time has not come."""
    if n["state"] == "live" and n["shows_from"] and n["shows_from"] > (now or _utc_str_now()):
        return "sched"
    return n["state"]


def wn_admin_rows(db):
    """The notes as the admin list draws them: [{id, title, excerpt, audience (label), from, seen (the "n of m"), state, key,
    ...}]. Showing and scheduled first, then drafts, then taken down. A count, never a name."""
    now = _utc_str_now()
    counts = wn_audience_counts(db)
    seen = {r[0]: r[1] for r in db.execute("SELECT note_id, COUNT(*) FROM whatsnew_seen GROUP BY note_id")}
    out = []
    for n in db.execute("SELECT * FROM whatsnew_notes ORDER BY CASE state WHEN 'live' THEN 0 WHEN 'draft' THEN 1 ELSE 2 END, "
                        "shows_from DESC, id DESC"):
        st = wn_state_of(n, now)
        a_ = WN_AUDIENCE.get(n["audience"])
        m = counts[n["audience"]]["n"] if a_ else 0
        sh = _parse_when(_myt(n["shows_from"])) if n["shows_from"] else None
        out.append({"id": n["id"], "title": n["title"], "excerpt": n["body"] if len(n["body"]) <= 60 else n["body"][:57].rstrip() + "…",
                    "audience": a_[1] if a_ else n["audience"], "key": st, "state": WN_STATE_LABEL[st],
                    "from": ("%d %s, %s" % (sh.day, sh.strftime("%b"), sh.strftime("%H:%M"))) if sh else "–",
                    "seen_n": seen.get(n["id"], 0), "seen_m": m, "has_seen": st != "draft", "raw": n,
                    "when": ("%s %d %s, %s" % (sh.strftime("%a"), sh.day, sh.strftime("%b"), sh.strftime("%H:%M"))) if sh else ""})
    return out


@app.route("/admin/whats-new", methods=["GET", "POST"])
@super_required
def admin_whats_new():
    """Admin › Comms › What's new (Chris, 2026-11-03: "Super admin only"; canvas boards S1-S3): the notes with their state and how
    many of the people each is for have seen it, and the right-hand panel that writes one. Publish, Take down and Put back are
    double-confirmed and audited; a note is never deleted. A refused save draws the page again with what they typed."""
    db = get_db()
    me = current_user()
    vals, status, edit_id = None, 200, request.args.get("edit", type=int)
    if request.method == "POST":
        action = request.form.get("action", "")
        nid = request.form.get("nid", type=int)
        if action in ("save", "publish"):
            ok, said, new_id = wn_save(db, me, request.form, nid, publish=(action == "publish"))
            flash(said, "ok" if ok else "error")
            if ok:
                return redirect(url_for("admin_whats_new"))
            vals, edit_id = request.form, nid   # what they typed comes back, the panel open
        elif action in ("takedown", "putback"):
            ok, said = wn_set_state(db, me, nid or 0, "down" if action == "takedown" else "live")
            flash(said, "ok" if ok else "error")
            return redirect(url_for("admin_whats_new"))
        else:
            abort(400)
    rows = wn_admin_rows(db)
    note = db.execute("SELECT * FROM whatsnew_notes WHERE id=?", (edit_id,)).fetchone() if edit_id else None
    counts = wn_audience_counts(db)
    now_myt = _now_myt()
    targets = bar_link_targets(db)
    # the preview's first look: what they typed (a refused save), else the note, else a blank one; the box is drawn from the
    # shared macro and static/whatsnew_admin.js keeps it in step
    pv = (lambda k: (vals.get(k) if vals is not None else (note[k] if note else "")) or "")   # noqa: E731
    hit = next((t for t in targets if t["key"] == pv("link_target")), None)
    preview = [{"id": 0, "title": " ".join(pv("title").split()) or "Your title", "icon": WN_ICONS.get(pv("audience"), "mega"),
                "body": " ".join(pv("body").split()) or "What you write shows here, as people will read it.", "new": True,
                "link": {"label": hit["words"], "url": "#"} if hit else None}]
    return render_template(
        "admin_whats_new.html", rows=rows, note=note, vals=vals, audiences=WN_AUDIENCES, counts=counts, icons=WN_ICONS,
        panel_open=bool(vals) or request.args.get("panel") == "write" or bool(note), link_targets=targets,
        title_max=WN_TITLE_MAX, body_max=WN_BODY_MAX, today=now_myt.strftime("%Y-%m-%d"),
        default_at=(now_myt + timedelta(hours=1)).strftime("%Y-%m-%dT%H:00"), day=_wn_day(_utc_str_now()),
        now_utc=_utc_str_now(), preview_notes=preview,
        shows_at_input=_when_input(_myt(note["shows_from"])) if note and note["shows_from"] else "",
        e_from=_late_disp(note["shows_from"]) if note and note["shows_from"] else "",
        state_label=WN_STATE_LABEL, empty=WN_EMPTY), status



# --- who the emails go to -----------------------------------------------------------------------------------------
def _notice_open_cells(db, cyc, now):
    """The calendar's parts open now, in the active cycle."""
    if not cyc:
        return []
    gh = bool(gradeh_rm_cid(db, cyc))   # Grade H's parts count only where Grade H runs on the cycle (2026-10-31)
    return [c for c in WINDOW_KEYS if window_state(db, c, cyc["id"], now) == "open" and (gh or c not in GRADEH_CELL_KEYS)
            and (c not in ("pm_setting", "pm_setting_approve") or kpi_setting_runs(cyc))]


def notice_recipients(db, cyc=None, now=None):
    """Who the email before goes to: only the roles whose window is open now (Chris, 2026-10-26: "once the employee
    submission window is closed, we don't need to send the system email to them ... now we are in line manager window,
    only line manager will receive the email"). [(user row, part line)] in business group, unit and department order;
    the part line names their most direct open part and when it closes ("Your team's reviews are open until 15 Nov")."""
    now = now or _now_myt()
    cyc = cyc if cyc is not None else active_cycle(db)
    open_cells = set(_notice_open_cells(db, cyc, now))
    if not open_cells:
        return []
    takers = "SELECT id FROM users WHERE role!='admin' AND COALESCE(is_demo,0)=0 AND " + participant_sql()
    role_sql = {
        "own": takers if open_cells & {"pm_results", "tc_self", "pm_setting"} else None,
        "plan": ("SELECT id FROM users WHERE role!='admin' AND COALESCE(is_demo,0)=0 AND " + idp_participant_sql())
        if "idp_self" in open_cells else None,
        "rater": "SELECT DISTINCT assessor_id FROM assignments WHERE cycle_id=%d AND archived=0 AND %s"
        % (cyc["id"], rater_task_sql("assignments")),
        "lm": "SELECT DISTINCT manager_id FROM users WHERE manager_id IS NOT NULL AND id IN (%s)" % takers,
        "hod": "SELECT DISTINCT hod_id FROM users WHERE hod_id IS NOT NULL AND id IN (%s)" % takers,
        "buceo": "SELECT DISTINCT user_id FROM buceo_seats",
        "bgceo": "SELECT id FROM users WHERE COALESCE(bgceo_bg,'')!=''",
    }
    if open_cells & set(GRADEH_CELL_KEYS):   # Grade H's roles (open_cells holds its cells only where it runs)
        gp = "FROM gradeh_people p JOIN users uu ON uu.id=p.user_id WHERE p.cycle_id=%d AND p.private_company=0 AND uu.left_at IS NULL" % cyc["id"]
        role_sql.update({
            "gh_staff": "SELECT p.user_id " + gp + " AND uu.email LIKE '%@%'",   # gradeh_has_email's rule: no address, no email
            "gh_lm": "SELECT DISTINCT COALESCE(p.appraiser_id, uu.manager_id) " + gp,
            "gh_hod": "SELECT DISTINCT " + _GH_HOD_SQL + " " + gp + " AND " + _GH_HOD_SQL + " IS NOT NULL" + _GH_CAL_NOT_BU
                      + " UNION SELECT DISTINCT " + _GH_HOD2_SQL + " " + gp + " AND " + _GH_HOD2_SQL + " IS NOT NULL" + _GH_CAL_NOT_BU2,   # a second HOD too
            "gh_buceo": "SELECT DISTINCT bs.user_id FROM buceo_seats bs WHERE EXISTS (SELECT 1 " + gp + " AND uu.company=bs.company "
                        "AND uu.business_group=bs.business_group)"})
    by_role = {}
    for key, cells, _line in NOTICE_PART_LINES:
        live = [c for c in cells if c in open_cells]
        if not live:
            continue
        ids = set()
        for src in (("own", "plan") if key == "own" else (key,)):
            if role_sql.get(src):
                ids |= {r[0] for r in db.execute(role_sql[src]) if r[0]}
        if key == "hod":   # a calibrator is no HOD (2026-10-30): no Department Review, so no HOD notice
            ids = set(_hod_ids_with_review(db, sorted(ids)))
        elif key == "gh_hod":   # Grade H: only a BU CEO / BG CEO seat takes the HOD role away (2026-11-03)
            ids = set(_gh_hod_ids_with_role(db, sorted(ids)))
        by_role[key] = (ids, max(_rw_dmy(window_dates(db, c, cyc["id"])[1]) or date.max for c in live))
    if not by_role:
        return []
    every = sorted({i for ids, _d in by_role.values() for i in ids})
    rows = {}
    for i in range(0, len(every), 900):
        chunk = every[i:i + 900]
        for u in db.execute("SELECT * FROM users WHERE id IN (%s) AND role!='admin' AND left_at IS NULL AND "
                            "COALESCE(is_demo,0)=0" % ",".join("?" * len(chunk)), chunk):
            rows[u["id"]] = u
    for key, ability in _NOTICE_GH_ABILITY.items():   # a seat whose Grade H ability is switched off is not told about it
        if key in by_role:
            by_role[key] = ({i for i in by_role[key][0] if i in rows and leader_learn_can(rows[i], ability, db)}, by_role[key][1])
    told = {i for ids, _d in by_role.values() for i in ids}   # who is still on a list once the abilities are asked
    out = []
    for u in sorted((r for r in rows.values() if r["id"] in told), key=lambda r: (r["business_group"] or "", r["company"] or "",
                                                                                   r["department"] or "", r["id"])):
        line = ""
        for key, _cells, words in NOTICE_PART_LINES:
            if key in by_role and u["id"] in by_role[key][0]:
                d = by_role[key][1]
                line = (words % ("%d %s" % (d.day, d.strftime("%b")))) if d != date.max else ""
                break
        out.append((u, line))
    return out


def notice_recipients_text(db, now=None):
    """'line managers (their window is open, 9 – 15 Nov)' for the panel, from the roles open now."""
    now = now or _now_myt()
    cyc = active_cycle(db)
    cells = _notice_open_cells(db, cyc, now)
    if not cells:
        return "nobody: no part of the cycle is open now"
    who = {c[0]: NOTICE_WHO.get(c[2], c[2].lower()) for c in WINDOW_CELLS}
    who.update(_NOTICE_GH_WHO)
    names, spans = [], []
    for c in cells:
        if who[c] not in names:
            names.append(who[c])
        o, cl = window_dates(db, c, cyc["id"])
        if _rw_dmy(o) and _rw_dmy(cl):
            spans.append((_rw_dmy(o), _rw_dmy(cl)))
    lst = names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]
    span = _rw_span(min(a for a, _b in spans), max(b for _a, b in spans)) if spans else ""
    return "%s (their window is open%s)" % (lst, (", " + span) if span else "")


