def _notice_vals(db, n, user, part_line, now=None, after=False, reopened=None):
    now = now or _now_myt()
    k = NOTICE_KIND[n["kind"]]
    t = notice_times(n)
    closes = bool(n["closes"]) or n["kind"] == "fix"
    when = notice_when_word(t["start"], now, cap=False)
    when_on = when if when in ("tonight", "today", "tomorrow") else "on " + when
    mins = int(n["downtime_min"])
    downtime = {60: "1 hour", 90: "1½ hours", 120: "2 hours"}.get(mins, "%d minutes" % mins)
    vals = dict(email_names(db, user), what=k["what"], what_short=k["short"], planned=k["planned"], when=when_on,
                day="%s %d %s" % (t["start"].strftime("%A"), t["start"].day, t["start"].strftime("%b")),
                date="%s %d %s" % (t["start"].strftime("%a"), t["start"].day, t["start"].strftime("%b")),
                downtime=downtime, length=("about " + downtime) if closes else "OneHR stays open",
                being=k["being"], **{"from": _notice_hm(t["start"]), "until": _notice_hm(t["end"])})
    if after:
        back = reopened or t["end"]
        vals["reopened"] = _notice_hm(back)
        vals["done"] = (("Tonight's " if t["start"].hour >= 18 else "Today's ") + k["short"]) \
            if t["start"].date() == back.date() else "The %s on %s" % (k["short"], vals["date"])
        vals["part_line"] = (part_line + ".") if part_line else ""
    else:
        vals["part_line"] = (part_line + ", so there's still time." if part_line else "") + \
            (" We'll email you again as soon as OneHR is back." if closes and n["email_after"] else "")
        vals["part_line"] = vals["part_line"].strip()
    return vals


def notice_mail(db, key, n, user, part_line="", tpl=None, now=None, reopened=None):
    """(subject, html) of one notice email (key 'notice_before' or 'notice_after') to `user`, in the words of the
    template in use: the window, the expected downtime and their own part's line."""
    after = key == "notice_after"
    t = tpl or email_tpl_words(key, db=db)
    vals = _notice_vals(db, n, user, part_line, now=now, after=after, reopened=reopened)
    fill = lambda f: _tpl_fill(t.get(f) or "", vals)   # noqa: E731
    cyc = active_cycle(db)
    cname = cyc["name"] if cyc else ""
    if after:
        body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill("opening")))]
        if fill("closing"):
            body.append(_em_p(_em_esc(fill("closing"))))
        return fill("subject"), onehr_email(fill("heading"), "".join(body),
                                            button=(fill("button"), app_base_url() + url_for("home")),
                                            sub=fill("sub"), cycle=cname, footer=fill("footer"))
    closes = bool(n["closes"]) or n["kind"] == "fix"
    cell = "padding:%s;font:14.5px/1.5 %s;vertical-align:top;color:%s"
    rows = (("When", "%s, %s – %s" % (vals["date"], vals["from"], vals["until"]), True),
            ("Expected downtime", ("About " + vals["downtime"]) if closes else "None, OneHR stays open", True),
            ("Your work", fill("work") if closes else "Nothing changes for your work.", False))
    table = ('<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 14px;'
             'border-collapse:separate;background:#F5F6FA;border:1px solid #e4e7ef;border-radius:10px">%s</table>' % "".join(
                 '<tr><td style="%s;width:170px">%s</td><td style="%s%s">%s</td></tr>' % (
                     cell % ("12px 16px 6px" if i == 0 else "6px 16px 12px" if i == 2 else "6px 16px", _EM_FONT,
                             "#5f6678"), _em_esc(lbl),
                     cell % ("12px 16px 6px" if i == 0 else "6px 16px 12px" if i == 2 else "6px 16px", _EM_FONT,
                             "#1f2330"), ";font-weight:600" if bold else "", _em_esc(val))
                 for i, (lbl, val, bold) in enumerate(rows)))
    body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill("opening" if closes else "opening_open"))), table,
            _em_p(_em_esc(fill("advice" if closes else "advice_open")))]
    if fill("closing"):
        body.append(_em_p(_em_esc(fill("closing"))))
    return fill("subject"), onehr_email(fill("heading"), "".join(body), sub=fill("sub"), cycle=cname,
                                        footer=fill("footer"))


def _notice_queue(db, n, key, people, actor_id, reopened=None):
    """Queue one notice email to each of `people` [(user, part line)]: no waves (it asks nobody to sign in; the
    canvas, approved by Chris: "Sent at 30 a minute"), the sender's own pace. Returns (queued, batch)."""
    if not mailer.is_configured():
        return 0, None
    tpl = email_tpl_words(key, db=db)
    batch = "%s-%d-%s" % (key, n["id"], secrets.token_hex(4))
    cyc = active_cycle(db)
    now = _now_myt()
    queued = 0
    for u, line in people:
        to = (u["email"] or "").strip()
        if not to:
            continue
        subject, body = notice_mail(db, key, n, u, line, tpl=tpl, now=now, reopened=reopened)
        _outbox_add(db, key, to, subject, body, user_id=u["id"], cycle_id=cyc["id"] if cyc else None,
                    detail="notice %d" % n["id"], actor_id=actor_id, batch=batch)
        queued += 1
    db.commit()
    if queued:
        _outbox_kick()
    return queued, batch


def notice_send_before(db, n, actor_id=None):
    """The email before, to the roles open now; the ids are kept so the email after reaches the same people."""
    if not n["email_before"] or n["kind"] == "fix" or n["before_at"]:
        return 0
    people = notice_recipients(db)
    queued, batch = _notice_queue(db, n, "notice_before", people, actor_id)
    db.execute("UPDATE site_notices SET before_batch=?, before_count=?, before_at=?, recipients=? WHERE id=?",
               (batch, queued, _now_myt().strftime("%Y-%m-%d %H:%M"),
                json.dumps([[u["id"], line] for u, line in people]), n["id"]))
    db.commit()
    return queued


def notice_send_after(db, n, actor_id=None, reopened=None):
    """The email after, to the people the email before went to, once OneHR is back."""
    if not n["email_after"] or n["kind"] == "fix" or n["after_at"] or not (bool(n["closes"])):
        return 0
    try:
        kept = json.loads(n["recipients"] or "[]") or []
    except (TypeError, ValueError):
        kept = []
    if not kept:   # no email went before (switched off, or no server mail then): the roles open now
        people = notice_recipients(db)
    else:
        ids = [int(i) for i, _l in kept]
        lines = {int(i): l for i, l in kept}
        rows = {}
        for i in range(0, len(ids), 900):
            chunk = ids[i:i + 900]
            for u in db.execute("SELECT * FROM users WHERE id IN (%s) AND left_at IS NULL" % ",".join("?" * len(chunk)),
                                chunk):
                rows[u["id"]] = u
        people = [(rows[i], lines[i]) for i in ids if i in rows]
    queued, batch = _notice_queue(db, n, "notice_after", people, actor_id, reopened=reopened)
    db.execute("UPDATE site_notices SET after_batch=?, after_count=?, after_at=? WHERE id=?",
               (batch, queued, _now_myt().strftime("%Y-%m-%d %H:%M"), n["id"]))
    db.commit()
    return queued


# --- posting, changing and cancelling a notice; closing and reopening --------------------------------------------
def _notice_form(form, rules, now):
    """(values, error) from Post a notice's form: every field picked from its list, never typed."""
    kind = form.get("kind", "")
    if kind not in NOTICE_KIND or kind in NOTICE_KINDS_RETIRED:
        return None, NOTICE_KIND_REFUSAL
    day = _rw_dmy(form.get("date", ""))
    if not day or not (now.date() <= day <= now.date() + timedelta(days=NOTICE_DAYS_AHEAD)):
        return None, "Pick a date from the list."
    hm = form.get("from", "")
    if not re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", hm or "") or int(hm[3:]) % 5:
        return None, "Pick a start time from the list."
    try:
        mins = int(form.get("downtime", ""))
    except ValueError:
        mins = 0
    if mins not in NOTICE_DOWNTIMES:
        return None, "Pick the expected downtime from the list."
    start = datetime.strptime("%s %s" % (day.isoformat(), hm), "%Y-%m-%d %H:%M")
    lead = rules["bar_lead"]
    if start < now + timedelta(minutes=lead):
        earliest = now + timedelta(minutes=lead + 4)
        earliest = earliest.replace(minute=earliest.minute - earliest.minute % 5, second=0, microsecond=0)
        return None, "A planned notice needs at least %d minutes' notice: start it at %s or later." % (
            lead, earliest.strftime("%H:%M"))
    off = release_blackout_on(get_db(), day, rules)
    if off:
        return None, "No planned release on %s (%s). Pick another day." % (
            "%d %s" % (day.day, day.strftime("%b")), off)
    closes = form.get("closes") == "1"
    return {"kind": kind, "starts_at": start.strftime("%Y-%m-%d %H:%M"), "downtime_min": mins,
            "closes": 1 if closes else 0,
            "email_before": 1 if form.get("email_before") == "1" else 0,
            "email_after": 0 if not closes else (1 if form.get("email_after") == "1" else 0)}, None


def notice_overlaps(db, start, end, skip_id=None):
    for n in db.execute("SELECT * FROM site_notices WHERE status='scheduled' AND id!=?", (skip_id or 0,)):
        t = notice_times(n)
        if start < t["end"] and t["start"] < end:
            return n
    return None


def notice_save(db, me, form, nid=None, source="admin"):
    """Post a notice (or change one not yet started): (ok, what to say, notice id). Its email before goes now, to the
    roles open now. One writer for Admin › Notices and the release run."""
    rules = release_rules()
    now = _now_myt()
    vals, err = _notice_form(form, rules, now)
    if err:
        return False, err, None
    start = _parse_when(vals["starts_at"])
    clash = notice_overlaps(db, start, start + timedelta(minutes=vals["downtime_min"]), nid)
    if clash:
        return False, "Another notice is posted for that time (%s). Change or cancel that one first." % (
            notice_row_view(clash)["when"]), None
    k = NOTICE_KIND[vals["kind"]]
    if nid:
        old = db.execute("SELECT * FROM site_notices WHERE id=? AND status='scheduled'", (nid,)).fetchone()
        if not old:
            return False, "That notice isn't posted any more.", None
        if notice_times(old)["start"] <= now:
            return False, "That notice has started: it can't be changed now.", None
        db.execute("UPDATE site_notices SET kind=?, starts_at=?, downtime_min=?, closes=?, email_before=?, "
                   "email_after=? WHERE id=?", (vals["kind"], vals["starts_at"], vals["downtime_min"], vals["closes"],
                                                vals["email_before"], vals["email_after"], nid))
        db.commit()
        log_activity(db, me["id"] if me else None, "notice_change",
                     "notice %d: %s, %s for %d min, closes=%s" % (nid, k["label"], vals["starts_at"],
                                                                 vals["downtime_min"], vals["closes"]))
        n = db.execute("SELECT * FROM site_notices WHERE id=?", (nid,)).fetchone()
        said = "Changed: %s, %s." % (k["label"], notice_row_view(n)["when"])
        if n["email_before"] and n["before_at"]:
            said += " The email before had already gone out; it isn't sent again."
        elif n["email_before"]:
            q = notice_send_before(db, n, me["id"] if me else None)
            said += " The email before is going out to %d people." % q if q else ""
        return True, said, nid
    cur = db.execute("INSERT INTO site_notices(kind, starts_at, downtime_min, closes, email_before, email_after, "
                     "source, created_by) VALUES (?,?,?,?,?,?,?,?)",
                     (vals["kind"], vals["starts_at"], vals["downtime_min"], vals["closes"], vals["email_before"],
                      vals["email_after"], source, me["id"] if me else None))
    nid = cur.lastrowid
    db.commit()
    n = db.execute("SELECT * FROM site_notices WHERE id=?", (nid,)).fetchone()
    q = notice_send_before(db, n, me["id"] if me else None)
    log_activity(db, me["id"] if me else None, "notice_post",
                 "notice %d (%s): %s, %s for %d min, closes=%s, email before to %d" % (
                     nid, source, k["label"], vals["starts_at"], vals["downtime_min"], vals["closes"], q))
    v = notice_row_view(n)
    said = "Posted: %s, %s. The bar shows from %s." % (k["label"], v["when"], v["bar"])
    if n["email_before"]:
        said += (" The email before is going out to %d people." % q) if q else \
            " No email went: %s." % ("this server sends no email" if not mailer.is_configured()
                                     else "no part of the cycle is open now")
    return True, said, nid


def notice_cancel(db, me, nid):
    n = db.execute("SELECT * FROM site_notices WHERE id=? AND status='scheduled'", (nid,)).fetchone()
    if not n:
        return False, "That notice isn't posted any more."
    db.execute("UPDATE site_notices SET status='cancelled', cancelled_by=?, cancelled_at=datetime('now') WHERE id=?",
               (me["id"] if me else None, nid))
    db.commit()
    log_activity(db, me["id"] if me else None, "notice_cancel", "notice %d (%s, %s)" % (
        nid, NOTICE_KIND[n["kind"]]["label"], n["starts_at"]))
    return True, "Cancelled. The bar is gone%s." % (
        "; if OneHR was closed for it, it reopens within a minute" if n["closed_at"] else "")


def notice_reopen(db, n, by=None):
    """OneHR is back: the notice is done (the bar goes) and the email after goes to the same people."""
    now = _now_myt()
    db.execute("UPDATE site_notices SET status='done', reopened_at=? WHERE id=? AND status='scheduled'",
               (now.strftime("%Y-%m-%d %H:%M"), n["id"]))
    db.commit()
    n = db.execute("SELECT * FROM site_notices WHERE id=?", (n["id"],)).fetchone()
    q = notice_send_after(db, n, by, reopened=now)
    log_activity(db, by, "notice_reopen", "notice %d: OneHR back at %s, email after to %d" % (
        n["id"], now.strftime("%H:%M"), q))
    return q


def notice_flag_want(db, now=None):
    """What the server's closed switch should be now: (notice row, until 'HH:MM') while a notice closes OneHR --
    from its start until it's reopened, its end time passes (unless the release run holds it), or the cap after its
    start passes (reopen_after, or the downtime and 15 minutes when that's longer; whatever holds it) -- else
    (None, None)."""
    now = now or _now_myt()
    rules = release_rules()
    hold = _setting(NOTICE_HOLD_KEY, "") or ""
    for n in db.execute("SELECT * FROM site_notices WHERE status='scheduled' AND (closes=1 OR kind='fix') "
                        "ORDER BY starts_at, id"):
        t = notice_times(n, rules)
        if not (t["start"] <= now):
            continue
        # the cap leaves a held release at least 15 minutes past the expected downtime
        cap = t["start"] + timedelta(minutes=max(rules["reopen_after"], int(n["downtime_min"]) + 15))
        held = hold == str(n["id"])
        if now < cap and (now < t["end"] or held):
            return n, _notice_hm(t["end"])
    return None, None


# --- the admin page ------------------------------------------------------------------------------------------------
def notice_row_view(n, now=None):
    now = now or _now_myt()
    t = notice_times(n)
    k = NOTICE_KIND[n["kind"]]
    when = "%s, %s – %s" % (notice_when_word(t["start"], now), _notice_hm(t["start"]), _notice_hm(t["end"]))
    mins = int(n["downtime_min"])
    emails = []
    if n["email_before"]:
        emails.append(("Before: sent %s to %d people" % (n["before_at"][11:16], n["before_count"] or 0))
                      if n["before_at"] else "Before: not sent")
    if n["email_after"]:
        emails.append(("After: sent %s to %d people" % (n["after_at"][11:16], n["after_count"] or 0))
                      if n["after_at"] else "After: when it reopens")
    if not emails:
        emails.append("Bar only, no email")
    closed = ""
    if n["reopened_at"] and n["closed_at"]:
        a, b = _parse_when(n["closed_at"]), _parse_when(n["reopened_at"])
        if a and b:
            closed = "Closed %d minutes" % max(1, int((b - a).total_seconds() // 60))
    return {"id": n["id"], "kind": n["kind"], "what": k["label"], "when": when,
            "day": "%s %d %s" % (t["start"].strftime("%a"), t["start"].day, t["start"].strftime("%b")),
            "span": "%s – %s" % (_notice_hm(t["start"]), _notice_hm(t["end"])),
            "downtime": ("About %d min" % mins) if (n["closes"] or n["kind"] == "fix") else "None, stays open",
            "bar": _notice_hm(t["show_from"]), "emails": emails,
            "by": "The release run" if n["source"] == "release" else "Super admin",
            "started": t["start"] <= now, "closed": closed, "status": n["status"],
            "date": t["start"].date().isoformat(), "from": _notice_hm(t["start"]), "mins": mins,
            "closes": bool(n["closes"]), "email_before": bool(n["email_before"]), "email_after": bool(n["email_after"])}


def notice_preview(db, args, now=None):
    """Post a notice's preview, from its picks as they stand: the bar, and each email to the admin themself (made-up
    part line from the roles open now). Writes nothing."""
    now = now or _now_myt()
    rules = release_rules()
    me = current_user()
    kind = args.get("kind") if args.get("kind") in NOTICE_KIND and args.get("kind") not in NOTICE_KINDS_RETIRED else "upgrade"
    day = _rw_dmy(args.get("date", "")) or now.date()
    hm = args.get("from", "") if re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", args.get("from", "") or "") else rules["start"]
    try:
        mins = int(args.get("downtime", ""))
    except ValueError:
        mins = rules["downtime"]
    mins = mins if mins in NOTICE_DOWNTIMES else rules["downtime"]
    closes = args.get("closes", "1") == "1"
    n = {"id": 0, "kind": kind, "starts_at": "%s %s" % (day.isoformat(), hm), "downtime_min": mins,
         "closes": 1 if closes else 0, "email_before": 1 if args.get("email_before", "1") == "1" else 0,
         "email_after": 0 if not closes else (1 if args.get("email_after", "1") == "1" else 0)}
    w = notice_words(n, now, False, rules)
    t = notice_times(n, rules)
    cells = _notice_open_cells(db, active_cycle(db), now)
    line = ""
    for key, cs, words in NOTICE_PART_LINES:
        live = [c for c in cs if c in cells]
        if live:
            d = max(_rw_dmy(window_dates(db, c, active_cycle_id(db))[1]) or date.max for c in live)
            line = (words % ("%d %s" % (d.day, d.strftime("%b")))) if d != date.max else ""
            break
    # the bar as it first shows: its lead time ahead, counting down from there
    ahead = rules["bar_lead"] * 60
    out = {"lead": w["lead"],
           "info": w["info"].replace("{in}", notice_in(ahead)), "red": w["red"],
           "shown": _notice_hm(t["show_from"]), "recipients": notice_recipients_text(db, now), "cancel_by": hm}
    for key, on, off in (("notice_before", n["email_before"], "Email before is off for this notice."),
                         ("notice_after", n["email_after"],
                          "No email after: OneHR stays open, so there's nothing to come back to." if not closes
                          else "Email after is off for this notice.")):
        if on:
            s, html = notice_mail(db, key, n, me, line, now=now)
            out[key] = {"subject": s, "html": html}
        else:
            out[key] = {"off": off}
    return out


@app.route("/admin/notices", methods=["GET", "POST"])
@super_required
def admin_notices():
    """Admin › Notices (Chris, 2026-10-26: "build the release window and notices as drawn on the canvas ... Notices
    page super admin only"; canvas [design canvas link removed], boards 10-11): what's coming up,
    the release window's set-up (following the cycle's timeline, by the parts ticked, or dates by hand), and what went
    before. Post a notice opens beside it. Every change is audited."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        action = request.form.get("action", "")
        if action == "save_window":
            r = release_rules()
            before = dict(r)
            r["on"] = request.form.get("on") == "1"
            r["mode"] = "dates" if request.form.get("mode") == "dates" else "cycle"
            for k in ("start",):
                if request.form.get(k) in RELEASE_OPTIONS[k]:
                    r[k] = request.form.get(k)
            for k in ("downtime", "bar_lead", "warn_lead", "reopen_after"):   # fix_lead is retired: kept as stored
                try:
                    v = int(request.form.get(k, ""))
                except ValueError:
                    continue
                if v in RELEASE_OPTIONS[k]:
                    r[k] = v
            r["email_before"] = request.form.get("email_before") == "1"
            r["email_after"] = request.form.get("email_after") == "1"
            if "cells_sent" in request.form:   # absent = unchanged; present with none ticked = none
                r["cells"] = [c for c in request.form.getlist("cells") if c in _WINDOW_SUBJECT]
            if r["mode"] == "dates":
                a, b = _rw_dmy(request.form.get("from", "")), _rw_dmy(request.form.get("until", ""))
                if not a or not b or a > b:
                    flash("Pick a From date on or before the Until date.", "error")
                    return redirect(url_for("admin_notices", tab="notices"))
                r["from"], r["until"] = a.isoformat(), b.isoformat()
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('release_window',?)", (json.dumps(r),))
            db.commit()
            changed = [k for k in r if r[k] != before.get(k)]
            log_activity(db, me["id"], "release_window", "changed: %s" % (", ".join(changed) or "nothing"))
            a, b = release_range(db, r)
            flash(("Saved. Release evenings run %s, from %s." % (_rw_span(a, b), r["start"])) if (r["on"] and a)
                  else "Saved. Release evenings are off: fixes ship when they're ready." if not r["on"]
                  else "Saved. No ticked part is dated yet, so release evenings don't apply.", "ok")
            return redirect(url_for("admin_notices", tab="notices"))
        if action in ("post", "update"):
            nid = request.form.get("nid", "")
            ok, said, _nid = notice_save(db, me, request.form, int(nid) if action == "update" and nid.isdigit() else None)
            flash(said, "ok" if ok else "error")
            if not ok:
                return redirect(url_for("admin_notices", tab="notices", panel="post",
                                        **({"edit": nid} if action == "update" else {})))
            return redirect(url_for("admin_notices", tab="notices"))
        if action == "cancel":
            nid = request.form.get("nid", "")
            ok, said = notice_cancel(db, me, int(nid) if nid.isdigit() else 0)
            flash(said, "ok" if ok else "error")
            return redirect(url_for("admin_notices", tab="notices"))
        if action in ("ann_post", "ann_update"):
            aid = request.form.get("aid", "")
            ok, said = bar_ann_save(db, me, request.form, int(aid) if action == "ann_update" and aid.isdigit() else None)
            flash(said, "ok" if ok else "error")
            if not ok:
                return redirect(url_for("admin_notices", tab="announcements", panel="announce",
                                        **({"aedit": aid} if action == "ann_update" else {})))
            return redirect(url_for("admin_notices", tab="announcements"))
        if action == "ann_end":
            aid = request.form.get("aid", "")
            ok, said = bar_ann_end(db, me, int(aid) if aid.isdigit() else 0)
            flash(said, "ok" if ok else "error")
            return redirect(url_for("admin_notices", tab="announcements"))
        if action == "save_deadline":
            r = deadline_rules()
            before = dict(r)
            r["on"] = request.form.get("on") == "1"
            try:
                days = int(request.form.get("days", ""))
            except ValueError:
                days = r["days"]
            r["days"] = days if days in DEADLINE_DAYS else r["days"]
            if request.form.get("places_sent"):   # absent = unchanged
                pl = [p for p in DL_PLACES if p in request.form.getlist("places")]
                if not pl:
                    flash("Tick at least one page for the reminder, or switch it off.", "error")
                    return redirect(url_for("admin_notices", tab="announcements"))
                r["places"] = pl
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('deadline_reminder',?)", (json.dumps(r),))
            db.commit()
            where = lambda x: "+".join(x["places"])   # noqa: E731
            log_activity(db, me["id"], "deadline_reminder", "%s, %s, on %s (was %s, %s, %s)" % (
                "on" if r["on"] else "off", _dl_days_phrase(r["days"]), where(r),
                "on" if before["on"] else "off", _dl_days_phrase(before["days"]), where(before)))
            flash(("Saved. Each person sees their own deadline %s." % (
                "the whole time their part is open" if r["days"] == DEADLINE_WHOLE else
                "from %d day%s before their part closes" % (r["days"], "" if r["days"] == 1 else "s")))
                  if r["on"] else "Saved. The deadline reminder is off.", "ok")
            return redirect(url_for("admin_notices", tab="announcements"))
        abort(400)
    now = _now_myt()
    rules = release_rules()
    cyc = active_cycle(db)
    coming, past = [], []
    for n in db.execute("SELECT * FROM site_notices ORDER BY starts_at DESC, id DESC LIMIT 60"):
        v = notice_row_view(n, now)
        if n["status"] == "scheduled" and notice_times(n, rules)["end"] > now and not n["reopened_at"]:
            coming.append(v)
        elif n["status"] != "cancelled" or n["before_at"]:
            past.append(v)
    coming.reverse()
    a, b = release_range(db, rules, cyc)
    edit = None
    if request.args.get("edit", "").isdigit():
        e = db.execute("SELECT * FROM site_notices WHERE id=? AND status='scheduled'",
                       (int(request.args["edit"]),)).fetchone()
        edit = notice_row_view(e, now) if e and not notice_row_view(e, now)["started"] else None
    days = [now.date() + timedelta(days=i) for i in range(NOTICE_DAYS_AHEAD + 1)]
    # announcements: showing and coming first, then the five that ended last
    anns = [bar_ann_view(db, a, now) for a in db.execute(
        "SELECT * FROM site_announcements ORDER BY starts_at DESC, id DESC LIMIT 60")]
    anns = ([x for x in anns if x["state"] == "showing"] + sorted([x for x in anns if x["state"] == "coming"],
                                                                   key=lambda x: (x["from_date"], x["from_time"]))
            + [x for x in anns if x["state"] == "ended"][:5])
    # Banner's two tabs (Chris, 2026-10-26: "rename it as Banner, and put a two tabs: Announcement | Notice"; canvas
    # boards 15-15b): it opens on the tab asked for, else Announcements unless only a notice is live or coming
    ann_live = [x for x in anns if x["state"] != "ended"]
    tab = request.args.get("tab") if request.args.get("tab") in ("announcements", "notices") else (
        "notices" if (coming and not ann_live) else "announcements")
    cyc_opens = _bar_cycle_opens(db, cyc)
    ann_parts = []
    for k, label, words, _cells in BAR_ANN_PARTS:
        o, c = _bar_part_dates(db, cyc, k)
        ann_parts.append({"key": k, "label": label, "words": words, "dated": bool(o),
                          "dates": _rw_span(o, c) if o else "not dated yet",
                          "first": _bar_day(o) if o else "", "last": _bar_day(c) if o else ""})
    ann_edit = None
    if request.args.get("aedit", "").isdigit():
        e = db.execute("SELECT * FROM site_announcements WHERE id=? AND status='live'",
                       (int(request.args["aedit"]),)).fetchone()
        ann_edit = bar_ann_view(db, e, now) if e else None
    return render_template(
        "admin_notices.html", coming=coming, past=past[:12], rules=rules, options=RELEASE_OPTIONS, cycle=cyc,
        groups=release_parts(db, cyc, rules), range=(a.isoformat() if a else "", b.isoformat() if b else ""),
        range_text=_rw_span(a, b), blackouts=release_blackouts(db, rules, cyc), kinds=NOTICE_KINDS_POSTABLE,
        downtimes=NOTICE_DOWNTIMES, times=["%02d:%02d" % (h, m) for h in range(24) for m in range(0, 60, 5)],
        days=[{"value": d.isoformat(), "label": "%s %d %s%s" % (d.strftime("%a"), d.day, d.strftime("%b"),
                                                                   " (today)" if d == now.date() else "")}
              for d in days],
        edit=edit, recipients=notice_recipients_text(db, now), mail_on=mailer.is_configured(),
        anns=anns, ann_edit=ann_edit, tab=tab, ann_showing=sum(1 for x in anns if x["state"] == "showing"),
        ann_timings=BAR_ANN_TIMINGS, ann_parts=ann_parts,
        cyc_opens=_bar_day(cyc_opens) if cyc_opens else "",
        cyc_stops=_bar_day(cyc_opens - timedelta(days=1)) if cyc_opens else "", ann_audiences=BAR_ANN_AUDIENCES, ann_roles=BAR_ANN_ROLES,
        ann_places=BAR_PLACES, ann_places_default=BAR_PLACES_DEFAULT, dl_places=[BAR_PLACE[p] for p in DL_PLACES],
        ann_buttons=BAR_ANN_BUTTONS, ann_head_max=BAR_ANN_HEADLINE_MAX, ann_msg_max=BAR_ANN_MESSAGE_MAX,
        ann_link_max=BAR_LINK_LABEL_MAX, ann_link_targets=bar_link_targets(db),
        today=now.date().isoformat(), ann_until=(now.date() + timedelta(days=7)).isoformat(), half_hours=["%02d:%02d" % (h, m) for h in range(24) for m in (0, 30)] + ["23:59"],
        dl_rules=deadline_rules(), dl_days=DEADLINE_DAYS, dl_whole=DEADLINE_WHOLE, dl_preview=deadline_preview(db),
        dl_gh=deadline_preview_gh(db))


@app.route("/admin/notices/preview")
@super_required
def admin_notices_preview():
    """Post a notice's live preview (JSON): the bar and both emails in the words the picks give. Writes nothing."""
    if request.args.get("kind") in NOTICE_KINDS_RETIRED:
        return jsonify({"error": NOTICE_KIND_REFUSAL}), 400
    return jsonify(notice_preview(get_db(), request.args))


# --- "Something changed on your check-in" (Chris, 2026-11-06: "if we change a person's KPI or competency, where a person
# will need to redo, send an email to the affected person") ---------------------------------------------------------------
# Three changes email the person, and only when they must do something: a competency SWAP on a started set, a competency
# ADDED after they started or submitted, and a KPI line ADDED after they started or confirmed. Not emailed (the in-app note
# stays): a BU KPI retarget, a method or unit change, a weight change, a KPI line deleted, a line manager hand-over, and a
# Reopen (it has its own email, _reopen_email). ONE helper writes it (_redo_notice): every trigger collects what it did
# for a person in the request (_redo_collect) and the end of the save sends ONE email a person naming every change
# (_redo_flush). It never sends inline: it queues in the outbox (a bulk save in waves, like every mass email) and the
# sender re-checks it just before it goes (_outbox_redo_recheck): dropped when nothing is waiting on the person any more.
# The super admin's switch (Email > Emails and templates) is on unless saved off. No model, and the words never say Reopen.
REDO_KIND = "redo_notice"
REDO_SWITCH_KEY = "redo_email_enabled"   # app_settings; no row = on
REDO_NOTHING_LEFT = "nothing left for them to fill in when it was due"   # a queued notice not sent (_outbox_redo_recheck)
REDO_SWITCHED_OFF = "switched off by the super admin before it was due"
REDO_PLACEHOLDERS = ("display_name", "first_name", "full_name", "cycle")
REDO_TPL_FIELDS = (   # (key, label, ceiling, required)
    ("subject", "Subject", 200, True), ("heading", "Heading", 120, True), ("greeting", "Greeting", 80, True),
    ("opening", "Opening", 500, True), ("instruction", "What to do", 500, True), ("button", "Button", 40, True),
    ("closing", "Closing line", 300, False))
REDO_TPL_MULTILINE = ("opening", "instruction", "closing")
REDO_TPL_DEFAULT = {
    "subject": "Something new to fill in on your {cycle} check-in",
    "heading": "Something changed on your check-in",
    "greeting": "Hi {display_name},",
    "opening": "Group People changed your KPI or competency in the {cycle} check-in, and there is something for you to "
               "fill in. This is what changed:",
    "instruction": "Open OneHR, fill in the new item and submit it. Everything else you have already entered or "
                   "submitted stays as it is.",
    "button": "Open OneHR",
    "closing": "If this looks wrong, contact Group People.",
}
_REDO_LOCAL = threading.local()


def redo_email_on():
    """The super admin's switch for the "something changed" email: on unless it was saved off."""
    return (_setting(REDO_SWITCH_KEY, "1") or "1") != "0"


def _redo_names(names):
    """'“A”, “B” and “C”' for a short list of names."""
    q = ["“%s”" % n for n in names]
    return q[0] if len(q) == 1 else ", ".join(q[:-1]) + " and " + q[-1] if q else ""


def _redo_change_text(ch):
    """One change in the person's words: what Group People changed and nothing about anyone else."""
    if ch["kind"] == "kpi":
        return "KPI added: “%s”" % ch.get("name", "")
    if ch["kind"] == "tc_add":
        return "Competency added: “%s”" % ch.get("title", "")
    bits = []
    if ch.get("added"):
        bits.append("added %s" % _redo_names(ch["added"]))
    if ch.get("removed"):
        bits.append("removed %s" % _redo_names(ch["removed"]))
    return "Competencies updated to match your job: %s. Your other answers are kept." % (
        ", ".join(bits) or "nothing new to answer")


def _redo_row_html(text):
    """One change as a white box with a navy edge (Outlook darkens tints; the border carries the tone)."""
    return ('<table role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" class="oh-row" '
            'bgcolor="#ffffff" style="margin:0 0 6px;background:#ffffff;border:1px solid #e3e6ee;border-left:4px solid '
            '#252A59;border-radius:10px;border-collapse:separate"><tr><td class="oh-t" style="padding:12px 14px;'
            'font:14.5px/1.5 %s;color:#3a4060">%s</td></tr></table>' % (_EM_FONT, _em_esc(text)))


def _redo_mail(db, person, changes, cyc, tpl=None):
    """(subject, html) of the "something changed" email to `person`, in `tpl`'s words (the template of the day), the list
    of `changes` added by OneHR. Their own items only; no band, no rating, no other name."""
    t = _email_tpl_default(REDO_KIND)
    t.update(tpl or email_tpl_words(REDO_KIND, db=db))
    cname = (cyc["name"] if cyc else "") or ""
    vals = dict(email_names(db, person), cycle=cname)
    fill = lambda k: _tpl_fill(t.get(k) or "", vals)   # noqa: E731
    body = (_em_greet(fill("greeting")) + _em_p(_em_esc(fill("opening")))
            + "".join(_redo_row_html(_redo_change_text(c)) for c in changes)
            + _em_p(_em_esc(fill("instruction")), style="margin-top:12px;font:15px/1.6 %s;color:#3a4060" % _EM_FONT))
    if fill("closing"):
        body += _em_p(_em_esc(fill("closing")))
    return fill("subject"), onehr_email(fill("heading"), body, button=(fill("button"), app_base_url() + url_for("review_home")),
                                        cycle=cname)


def _redo_bucket():
    """The changes collected so far in this request (or this thread outside one): {cycle id: {user id: [change]}}."""
    if has_request_context():
        b = getattr(g, "_redo_pending", None)
        if b is None:
            b = g._redo_pending = {}
        return b
    if not hasattr(_REDO_LOCAL, "pending"):
        _REDO_LOCAL.pending = {}
    return _REDO_LOCAL.pending


def _redo_collect(db, act, p, change):
    """A writer calls this for a KPI line or competency it just added for `p`: nothing is sent here. `change` is
    {"kind": "kpi", "tid", "name"} | {"kind": "tc_add", "aid", "title"} | {"kind": "tc_swap", "added", "removed", "aids"}.
    _redo_flush (the end of the save) works out who must actually do something and sends one email each."""
    _redo_bucket().setdefault(act["id"], {}).setdefault(p["id"], []).append(change)


def _redo_started_kpi(db, uid, cid):
    """Has the person started their KPI check-in this cycle: any result of their own entered (a draft counts), or the
    check-in confirmed. HR's own fill (admin_filled) is never theirs."""
    if db.execute("SELECT 1 FROM pm_kpi_results r JOIN pm_kpi_targets t ON t.id=r.kpi_target_id WHERE t.cycle_id=? AND "
                  "t.subject_id=? AND COALESCE(r.admin_filled,0)=0 LIMIT 1", (cid, uid)).fetchone():
        return True
    return bool(pm_review_locked(db, uid, cid))


def _redo_started_tc(db, uid, cid):
    """Has the person started their competency self-assessment: any answer of their own, or it is submitted."""
    if db.execute("SELECT 1 FROM tc_scores sc JOIN tc_assignments a ON a.id=sc.assignment_id JOIN tc_assessments ta ON "
                  "ta.id=sc.assessment_id WHERE a.cycle_id=? AND a.subject_id=? AND ta.cycle_id=a.cycle_id AND "
                  "ta.subject_id=a.subject_id AND sc.answer IS NOT NULL LIMIT 1", (cid, uid)).fetchone():
        return True
    return db.execute("SELECT 1 FROM tc_assessments WHERE cycle_id=? AND subject_id=? AND status!='pending'",
                      (cid, uid)).fetchone() is not None


# --- The "Email them" tick in the admin's confirm box (Chris, 2026-11-07, canvas "Yes, as drawn") ---------------------------
# Three admin person-page actions can email the person (competency Add, Swap to their job's set, Add KPI). Where the email WOULD
# go (redo_tick_shown), the confirm box carries a ticked "Email {name} about this change"; unticked posts notify_person=0 and
# _redo_withhold takes that person's collected changes back out before the save's _redo_flush. Absent or "1" = emails as before.
REDO_TICK_WORDS = {
    "tc_add": ("One email naming what was added. Untick to make the change without emailing them.",
               "They won't be emailed. They still see the new competency when they next open OneHR, and the trail notes it."),
    "tc_swap": ("One email naming what was added and removed. Untick to swap without emailing them.",
                "They won't be emailed. They still see the new set when they next open OneHR, and the trail notes it."),
    "kpi": ("One email naming the new KPI. Untick to add it without emailing them.",
            "They won't be emailed. They still see the new KPI when they next open OneHR, and the trail notes it."),
}
REDO_NOT_EMAILED = "; not emailed (unticked)"


def redo_tick_shown(db, p, cyc, kind):
    """Does an admin's change of this `kind` ("kpi" | "tc_add" | "tc_swap") to person `p` in cycle `cyc` email them: the switch
    is on, they are neither an admin nor a leaver, they take part in the module (pm for a KPI, competency for the others), and
    for a KPI / competency add they have started (_redo_started_kpi / _redo_started_tc); a swap always. The confirm box shows
    its "Email them" tick only then."""
    if not cyc or not p or kind not in REDO_TICK_WORDS or not redo_email_on():
        return False
    if _row_get(p, "role") == "admin" or _row_get(p, "left_at"):
        return False
    if not _report_takes_part(db, p["id"], "pm" if kind == "kpi" else "competency", cyc):
        return False
    if kind == "kpi":
        return bool(_redo_started_kpi(db, p["id"], cyc["id"]))
    if kind == "tc_add":
        return bool(_redo_started_tc(db, p["id"], cyc["id"]))
    return True


def redo_notify_attrs(p, kind, cyc=None):
    """The confirm box's tick as HTML attributes for a form or submit button (empty when no email would go): data-confirm-notify
    and its two sub-lines, in the person's official name. Used by the three person-page templates."""
    db = get_db()
    cyc = cyc or active_cycle(db)
    if not redo_tick_shown(db, p, cyc, kind):
        return Markup("")
    on, off = REDO_TICK_WORDS[kind]
    return Markup('data-confirm-notify="%s" data-confirm-notify-sub="%s" data-confirm-notify-off="%s"' % (
        _mescape("Email %s about this change" % p["full_name"]), _mescape(on), _mescape(off)))


def _redo_withhold(db, act, p, actor_id):
    """The admin unticked "Email them": take everything collected for person `p` in this request back out of the bucket, so
    _redo_flush has nothing to send. When an email WOULD have gone (_redo_applies for any of those changes, switch on, not an admin
    or a leaver) one notifications row says so ("skipped", "the admin chose not to email") and this returns True so the caller
    adds "not emailed" to its trail line and flash; otherwise False. One function for all three paths."""
    mine = _redo_bucket().get(act["id"], {})
    changes = mine.pop(p["id"], [])
    if not mine:
        _redo_bucket().pop(act["id"], None)
    if not changes or not redo_email_on():
        return False
    u = db.execute("SELECT * FROM users WHERE id=?", (p["id"],)).fetchone()
    if not u or u["role"] == "admin" or _row_get(u, "left_at"):
        return False
    if not any(_redo_applies(db, act, u, c) for c in changes):
        return False
    log_notification(db, act["id"], p["id"], (_row_get(u, "email") or "").strip() or None, "skipped",
                     detail="the admin chose not to email", kind=REDO_KIND)
    if has_request_context():
        g._redo_withheld = True
    return True


def _redo_withheld_now():
    """Did this request withhold an email (the unticked box)? For the flash after the save."""
    return bool(has_request_context() and getattr(g, "_redo_withheld", False))


def _redo_applies(db, cyc, u, ch, facts=None):
    """True when this change makes the person do something (the three triggers' conditions, read now from what is stored):
      * a KPI line: the person fills it (not a BU-level KPI Group People fills), its setting is approved, it has no result
        yet, and they have already started their check-in or confirmed it;
      * a competency added: the line is there and their self-assessment is started or submitted;
      * a competency swap: always (a swap is only ever made on a started set).
    `facts` (from _redo_facts, a whole save's people in a few reads): who has started, who takes part, each one's BU-level names;
    without it each is read for this person alone."""
    cid, uid = cyc["id"], u["id"]
    part = (lambda m: uid in facts["part"][m]) if facts and facts["part"] else (lambda m: _report_takes_part(db, uid, m, cyc))
    if ch["kind"] == "tc_swap":
        return bool(part("competency"))
    if ch["kind"] == "tc_add":
        return bool(db.execute("SELECT 1 FROM tc_assignments WHERE id=? AND subject_id=? AND cycle_id=?",
                               (ch["aid"], uid, cid)).fetchone()
                    and part("competency")
                    and ((uid in facts["started_tc"]) if facts else _redo_started_tc(db, uid, cid)))
    t = db.execute("SELECT * FROM pm_kpi_targets WHERE id=? AND subject_id=? AND cycle_id=?",
                   (ch["tid"], uid, cid)).fetchone()
    if not t or not pm_result_entry_open(t):
        return False
    bu = facts["bu"][uid] if facts else pm_bu_level_names(db, u, cid)
    if " ".join((t["kpi_name"] or "").lower().split()) in bu:
        return False
    if db.execute("SELECT 1 FROM pm_kpi_results WHERE kpi_target_id=?", (t["id"],)).fetchone():
        return False
    return bool(part("pm") and ((uid in facts["started_kpi"]) if facts else _redo_started_kpi(db, uid, cid)))


def _redo_change_waiting(db, uid, cid, ch):
    """Is there still something to fill in for this change (the recheck just before the email goes, and the filter when it
    is queued): a KPI line still without a submitted result, a competency still to answer or to submit. Nothing once the
    person's results are released."""
    if _results_out(db, uid, cid):
        return False
    if ch["kind"] == "kpi":
        r = db.execute("SELECT r.draft FROM pm_kpi_targets t LEFT JOIN pm_kpi_results r ON r.kpi_target_id=t.id WHERE "
                       "t.id=? AND t.subject_id=? AND t.cycle_id=?", (ch["tid"], uid, cid)).fetchone()
        return bool(r) and (r["draft"] is None or bool(r["draft"]))
    asm = db.execute("SELECT status FROM tc_assessments WHERE cycle_id=? AND subject_id=?", (cid, uid)).fetchone()
    aids = [ch["aid"]] if ch["kind"] == "tc_add" else list(ch.get("aids") or [])
    if ch["kind"] == "tc_swap" and not aids:
        return bool(asm and asm["status"] == "pending")
    for aid in aids:
        r = db.execute("SELECT a.added_open FROM tc_assignments a WHERE a.id=? AND a.subject_id=? AND a.cycle_id=?",
                       (aid, uid, cid)).fetchone()
        if r and (bool(r["added_open"]) or (asm is not None and asm["status"] == "pending")):
            return True
    return False


def _redo_notice(db, act, items, actor_id, bulk=None):
    """THE writer of the "something changed" email: `items` = [(person row, [change, ...])]. ONE email a person naming every
    change for them, queued in the outbox (never sent here), and one line in the notifications trail for each person it did not
    go to. Nothing is queued with the super admin's switch off, for an admin, a leaver or someone with no address, or when this
    server sends no email (staging: logged as skipped). A change with nothing left to fill in is dropped. `bulk` (default:
    more than one person) queues in waves: send_after from _email_wave_at and one batch key, as Everyone's reminder does.
    The caller commits (_redo_flush does). Returns {queued, skipped}."""
    tally = {"queued": 0, "skipped": 0}
    if not redo_email_on():
        return tally
    rows = []
    for p, changes in items:
        keep = [c for c in changes if _redo_change_waiting(db, p["id"], act["id"], c)]
        if keep and not _row_get(p, "left_at") and _row_get(p, "role") != "admin":
            rows.append((p, keep))
    if not rows:
        return tally
    bulk = len(rows) > 1 if bulk is None else bulk
    tpl = email_tpl_words(REDO_KIND, db=db)
    rules, start = email_wave_rules(), _utc_now()
    waiting = db.execute("SELECT COUNT(*) FROM email_outbox WHERE kind=? AND status='queued'", (REDO_KIND,)).fetchone()[0]
    batch = ("redo-%s-%s" % (start.strftime("%Y%m%d%H%M%S"), secrets.token_hex(3))) if bulk else None
    for p, changes in rows:
        to = (_row_get(p, "email") or "").strip()
        if not to:
            log_notification(db, act["id"], p["id"], None, "skipped", detail="no email on file", kind=REDO_KIND)
            tally["skipped"] += 1
            continue
        if not mailer.is_configured():
            log_notification(db, act["id"], p["id"], to, "skipped", detail="this server sends no email", kind=REDO_KIND)
            tally["skipped"] += 1
            continue
        subject, body = _redo_mail(db, p, changes, act, tpl=tpl)
        ids = {"k": [c["tid"] for c in changes if c["kind"] == "kpi"],
               "c": [c["aid"] for c in changes if c["kind"] == "tc_add"]
                    + [a_ for c in changes if c["kind"] == "tc_swap" for a_ in (c.get("aids") or [])],
               "s": int(any(c["kind"] == "tc_swap" for c in changes))}
        words = "; ".join(_redo_change_text(c) for c in changes)
        _outbox_add(db, REDO_KIND, to, subject, body, user_id=p["id"], cycle_id=act["id"],
                    detail="%s | %s" % (words[:300], json.dumps(ids, separators=(",", ":"))), actor_id=actor_id,
                    send_after=_email_wave_at(waiting + tally["queued"], rules, start) if bulk else None, batch=batch)
        tally["queued"] += 1
    return tally


def _redo_chunks(ids, n=400):
    ids = list(ids)
    return [ids[i:i + n] for i in range(0, len(ids), n)]


def _redo_facts(db, cyc, people):
    """What _redo_flush needs about everyone a save collected for, in a few reads for the whole population (never one read a
    person): {users: {id: row}, started_kpi, started_tc, part: {"pm": ids, "competency": ids} or None, bu: {id: names}}.
    Started = any own result (HR's fill is never theirs) or a locked check-in; any own answer or a self-assessment that is
    not pending. `part` is one participant_sql read, for the active cycle only (another cycle: None, read per person).
    Only people with something to do get the rest: the ones who have not started cost nothing more."""
    cid = cyc["id"]
    users, k_st, t_st = {}, set(), set()
    for ch in _redo_chunks(people):
        ph = ",".join("?" * len(ch))
        for r in db.execute("SELECT * FROM users WHERE id IN (%s)" % ph, ch):
            users[r["id"]] = r
        k_st |= {r[0] for r in db.execute(
            "SELECT t.subject_id FROM pm_kpi_results r JOIN pm_kpi_targets t ON t.id=r.kpi_target_id WHERE t.cycle_id=? AND "
            "COALESCE(r.admin_filled,0)=0 AND t.subject_id IN (%s) UNION SELECT subject_id FROM pm_review_session WHERE "
            "cycle_id=? AND locked_at IS NOT NULL AND subject_id IN (%s)" % (ph, ph), [cid] + ch + [cid] + ch)}
        t_st |= {r[0] for r in db.execute(
            "SELECT a.subject_id FROM tc_scores sc JOIN tc_assignments a ON a.id=sc.assignment_id JOIN tc_assessments ta ON "
            "ta.id=sc.assessment_id WHERE a.cycle_id=? AND ta.cycle_id=a.cycle_id AND ta.subject_id=a.subject_id AND "
            "sc.answer IS NOT NULL AND a.subject_id IN (%s) UNION SELECT subject_id FROM tc_assessments WHERE cycle_id=? AND "
            "status!='pending' AND subject_id IN (%s)" % (ph, ph), [cid] + ch + [cid] + ch)}
    # who could still get an email: a swap always, a KPI or a competency only for someone who has started
    need = {uid for uid, chs in people.items() if any(
        c["kind"] == "tc_swap" or (c["kind"] == "kpi" and uid in k_st) or (c["kind"] == "tc_add" and uid in t_st) for c in chs)}
    part = bu = None
    if need and cid == active_cycle_id(db):
        part = {"pm": set(), "competency": set()}
        for ch in _redo_chunks(need):
            ph = ",".join("?" * len(ch))
            for m in part:
                part[m] |= {r[0] for r in db.execute("SELECT u.id FROM users u WHERE u.id IN (%s) AND %s" % (
                    ph, participant_sql("u", m)), ch)}
    kpi_need = [users[u_] for u_ in need if u_ in users and u_ in k_st and (part is None or u_ in part["pm"])]
    bu = _pm_bu_names_map(db, kpi_need, cid) if kpi_need else {}
    for u_ in need:   # a person with no KPI line to check still reads an empty set
        bu.setdefault(u_, set())
    return {"users": users, "started_kpi": k_st, "started_tc": t_st, "part": part, "bu": bu, "need": need}


def _redo_flush(db, actor_id=None):
    """The end of a save: work out, for each person something was collected for, which changes make them do something
    (_redo_applies), and send ONE email each (_redo_notice; in waves when more than one person). Commits what it queued and
    starts the sender. Safe to call twice: what was collected is taken once. Never raises into the save it follows.
    A population is read in a few batched queries (_redo_facts): people who have not started cost nothing beyond that."""
    bucket = _redo_bucket()
    pending = dict(bucket)
    bucket.clear()
    queued = 0
    for cid, people in pending.items():
        try:
            cyc = db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone()
            if not cyc or not redo_email_on():
                continue
            facts = _redo_facts(db, cyc, people)
            items = []
            for uid, changes in people.items():
                u = facts["users"].get(uid)
                if not u or u["role"] == "admin" or _row_get(u, "left_at") or uid not in facts["need"]:
                    continue
                keep = [c for c in changes if _redo_applies(db, cyc, u, c, facts)]
                if keep:
                    items.append((u, keep))
            if items:
                queued += _redo_notice(db, cyc, items, actor_id)["queued"]
                db.commit()
        except Exception:   # noqa: BLE001 -- an email never undoes the change it follows
            db.rollback()
            app.logger.exception("redo notice failed for cycle %s", cid)
    if queued:
        _outbox_kick()
    return queued


@app.after_request
def _redo_after_request(resp):
    """A save that collected a change but did not reach its own _redo_flush (the many callers of the BU KPI writer) is flushed
    here, once the response is made; a failed request drops what it collected. _redo_flush checks every change against what
    is stored, so a line a rolled-back save never wrote is never emailed."""
    try:
        if has_request_context() and getattr(g, "_redo_pending", None):
            if resp.status_code < 400:
                _redo_flush(get_db(), session.get("user_id"))
            else:
                g._redo_pending.clear()
    except Exception as e:   # noqa: BLE001 -- never fail a response
        app.logger.warning("redo notice flush failed: %s", e)
    return resp


app.jinja_env.globals["redo_notify_attrs"] = redo_notify_attrs


def _outbox_redo_recheck(db, row):
    """A claimed "something changed" email, worked out again just before it goes: dropped ('cancelled', logged as skipped, None
    comes back) when the super admin switched the email off since it was queued, or when nothing it names is waiting on the
    person now (the line answered and submitted, or taken off, or their results out). The words are as they were queued."""
    why = None
    if not redo_email_on():
        why = REDO_SWITCHED_OFF
    else:
        try:
            ids = json.loads((row["detail"] or "").rsplit(" | ", 1)[-1])
        except (TypeError, ValueError):
            ids = None
        if ids is not None:
            cid, uid = row["cycle_id"], row["user_id"]
            ch = [{"kind": "kpi", "tid": t} for t in ids.get("k") or []] + \
                 [{"kind": "tc_add", "aid": a_} for a_ in ids.get("c") or []]
            if ids.get("s") and not ids.get("c"):
                ch.append({"kind": "tc_swap", "aids": []})
            if not any(_redo_change_waiting(db, uid, cid, c) for c in ch):
                why = REDO_NOTHING_LEFT
    if why is None:
        return row
    db.execute("UPDATE email_outbox SET status='cancelled', error=? WHERE id=?", (why, row["id"]))
    log_notification(db, row["cycle_id"], row["user_id"], row["to_email"], "skipped", 0, why, kind=REDO_KIND)
    return None


