def own_id_of(key):
    """The id an own email's key names ('own:12' -> 12), else None."""
    m = re.fullmatch(r"own:(\d{1,9})", str(key or ""))
    return int(m.group(1)) if m else None


def email_tpl_kind(key, db=None):
    """THE resolver of an email's template spec (what EMAIL_TPL_KIND[key] was): a built-in key gives its row; "own:<id>" gives the shared
    "own" spec with that email's name as its title (its schedule in words as its who). KeyError for anything else, as the dict was, so a
    caller that checks first asks email_tpl_valid. Every place that reads a kind for an email it did not name itself comes through here."""
    k = EMAIL_TPL_KIND.get(key)
    if k is not None:
        return k
    oid = own_id_of(key)
    row = (db or get_db()).execute("SELECT * FROM email_own WHERE id=?", (oid,)).fetchone() if oid else None
    if row is None:
        raise KeyError(key)
    return dict(EMAIL_TPL_KIND["own"], key=key, title=row["name"] + (" (removed)" if row["removed_at"] else ""), who=email_own_who(row),
                own=oid, page="admin_email_schedule")


def email_tpl_valid(key, db=None):
    """Is `key` an email that has templates of its own: a built-in one (never the shared 'own' spec) or an own email that exists."""
    k = EMAIL_TPL_KIND.get(key)
    if k is not None:
        return not k.get("shared")
    oid = own_id_of(key)
    return bool(oid and (db or get_db()).execute("SELECT 1 FROM email_own WHERE id=?", (oid,)).fetchone())


def _email_tpl_default(key):
    """OneHR's own words for `key`'s email."""
    if key == "own" or own_id_of(key):
        return dict(OWN_TPL_DEFAULT)
    if key == "reminder":
        return dict(REMINDER_TPL_DEFAULT)
    if key.startswith("lp_"):
        return dict(LP_TPL_DEFAULT[key[3:]])
    if key in ("notice_before", "notice_after"):
        return dict(NOTICE_BEFORE_TPL_DEFAULT if key == "notice_before" else NOTICE_AFTER_TPL_DEFAULT)
    if key == "gradeh_ready":
        return dict(GRADEH_READY_TPL_DEFAULT)
    if key == "gradeh_result":
        return dict(GRADEH_RESULT_TPL_DEFAULT)
    if key == "gradeh_reminder":
        return dict(GRADEH_REMINDER_TPL_DEFAULT)
    if key == REDO_KIND:
        return dict(REDO_TPL_DEFAULT)
    if key == TB_ROUND_KIND:
        return dict(TB_ROUND_TPL_DEFAULT)
    if key in (GH_PROG_KIND["hod"], GH_PROG_KIND["buceo"]):   # Grade H progress for HODs / BU CEOs (2026-11-09)
        return dict(GH_PROG_DEFAULT[key.rsplit("_", 1)[1]])
    if key in (GH_READY_KIND["hod"], GH_READY_KIND["buceo"]):   # Grade H ready notes
        return dict(GH_READY_DEFAULT[key.rsplit("_", 1)[1]])
    if key.startswith("ready_"):
        return dict(READY_TPL_DEFAULT[key[6:]])
    return dict(RELEASE_LEAD_TPL_DEFAULT if key == "release_lead" else RELEASE_PERSON_TPL_DEFAULT)


def _email_tpl_clean(key, saved):
    t = _email_tpl_default(key)
    t.update({k: v for k, v in (saved or {}).items() if k in t and isinstance(v, str)})
    return t


def _email_tpl_legacy(key):
    """`key`'s words before it had a template: the older settings (the reminder's and the leader progress's saved
    words) over OneHR's own, else OneHR's own."""
    saved = {}
    try:
        if key == "reminder":
            for k, old in (("subject", "reminder_all_subject"), ("opening", "reminder_all_opening")):
                if _setting(old):
                    saved[k] = _setting(old)
            saved.update(json.loads(_setting("reminder_template", "") or "{}") or {})
        elif key.startswith("lp_"):
            saved = (json.loads(_setting("leader_progress_template", "") or "{}") or {}).get(key[3:]) or {}
    except (TypeError, ValueError, AttributeError):
        saved = {}
    return _email_tpl_clean(key, saved)


def email_tpl_rows(db, key):
    """`key`'s templates still in use (not retired): the usual one first, then by their dates."""
    return db.execute("SELECT * FROM email_templates WHERE email=? AND retired_at IS NULL ORDER BY usual DESC, "
                      "COALESCE(date_from, '9999-12-31'), id", (key,)).fetchall()


def email_tpl_pick(rows, day):
    """The template for `day` (an MYT date): the one whose dates cover it, else the usual one, else None."""
    d = day.isoformat()
    for r in rows:
        if r["date_from"] and r["date_to"] and r["date_from"] <= d <= r["date_to"]:
            return r
    return next((r for r in rows if r["usual"]), None)


def email_tpl_saved(row):
    """Every word of one template, its own over OneHR's (a field added later reads OneHR's until it is edited)."""
    try:
        saved = json.loads(row["words"] or "{}") or {}
    except (TypeError, ValueError):
        saved = {}
    return _email_tpl_clean(row["email"], saved if isinstance(saved, dict) else {})


def email_tpl_words(key, day=None, db=None):
    """Every word of `key`'s email on `day` (today, MYT): the template in use that day, or, before the email has any
    template, its older settings. Every send reads it once, when the emails are written."""
    db = db or get_db()
    row = email_tpl_pick(email_tpl_rows(db, key), day or _today_myt())
    return email_tpl_saved(row) if row else _email_tpl_legacy(key)


def email_tpl_changes(rows, day, horizon=120):
    """[(date, row)]: each day after `day`, within `horizon` days, on which another template takes over (a dated one
    starting, or the usual one coming back the day after one ends)."""
    cur = email_tpl_pick(rows, day)
    edges = set()
    for r in rows:
        if r["date_from"] and r["date_to"]:
            edges.add(date.fromisoformat(r["date_from"]))
            edges.add(date.fromisoformat(r["date_to"]) + timedelta(days=1))
    out = []
    for e in sorted(edges):
        if e <= day or (e - day).days > horizon:
            continue
        nxt = email_tpl_pick(rows, e)
        if nxt is not None and (cur is None or nxt["id"] != cur["id"]):
            out.append((e, nxt))
            cur = nxt
    return out


def _email_tpl_ensure(db, key, by=None):
    """Give `key` its usual template, made from its words of today (the older settings, else OneHR's), when it has
    none yet. True when it made one. Cycle > Emails and every change to a template call it; a send never does."""
    if EMAIL_TPL_KIND.get(key, {}).get("shared"):   # the shared spec of the own emails has no template of its own
        return False
    if db.execute("SELECT 1 FROM email_templates WHERE email=? AND usual=1 AND retired_at IS NULL", (key,)).fetchone():
        return False
    db.execute("INSERT INTO email_templates(email, name, words, usual, created_by, updated_at, updated_by) "
               "VALUES (?,?,?,1,?,datetime('now'),?)",
               (key, email_tpl_kind(key, db)["first"], json.dumps(_email_tpl_legacy(key)), by, by))
    db.commit()
    return True


def email_tpl_today(db, key, by=None):
    """The template `key` uses today (MYT): what the Reminders and Leader progress pages edit."""
    _email_tpl_ensure(db, key, by)
    return email_tpl_pick(email_tpl_rows(db, key), _today_myt())


def _tpl_words_from(form, fields, placeholders, base, multiline):
    """(words, errors) from a posted form over `base`. Absent is not empty: a field the form didn't send stays as it
    is; a required one sent empty is refused; text over its ceiling is refused, never trimmed; a placeholder OneHR
    doesn't fill is refused, naming the ones it does."""
    t = dict(base)
    errs = []
    known = set(placeholders)
    for key, label, cap, req in fields:
        if key not in form:
            continue
        v = str(form.get(key) or "").strip() if key in multiline else " ".join(str(form.get(key) or "").split())
        if req and not v:
            errs.append("%s can't be empty." % label)
            continue
        if len(v) > cap:
            errs.append("Keep %s under %d characters." % (label.lower(), cap))
            continue
        bad = sorted(set(re.findall(r"\{(\w+)\}", v)) - known)
        if bad:
            errs.append("%s uses {%s}, which OneHR doesn't fill in. You can use %s." % (
                label, bad[0], ", ".join("{%s}" % p for p in placeholders)))
            continue
        t[key] = v
    return t, errs


def email_tpl_words_from(form, row):
    """(words, errors) for one template from a posted form, over its saved words."""
    k = email_tpl_kind(row["email"])
    return _tpl_words_from(form, k["fields"], k["placeholders"], email_tpl_saved(row), k["multiline"])


def email_tpl_set_words(db, row, words, by, name=None):
    """Save one template's words (and its name): [labels of what changed], [] when nothing did. The caller writes the
    audit line."""
    before = email_tpl_saved(row)
    fields = email_tpl_kind(row["email"], db)["fields"]
    changed = [lbl for k, lbl, _c, _r in fields if words.get(k) != before.get(k)]
    if name is not None and name != row["name"]:
        changed.insert(0, "Name")
    if changed:
        db.execute("UPDATE email_templates SET words=?, name=?, updated_at=datetime('now'), updated_by=? WHERE id=?",
                   (json.dumps({k: words.get(k, before[k]) for k in before}), name if name is not None else row["name"],
                    by, row["id"]))
        db.commit()
    return changed


def _email_tpl_name(db, key, raw, tid=None):
    """(name, error): a template's name, one line, unique among the email's templates still in use."""
    name = " ".join(str(raw or "").split())
    if not name:
        return None, "Give the template a name."
    if len(name) > EMAIL_TPL_NAME_MAX:
        return None, "Keep the name under %d characters." % EMAIL_TPL_NAME_MAX
    if db.execute("SELECT 1 FROM email_templates WHERE email=? AND retired_at IS NULL AND lower(name)=lower(?) AND "
                  "id IS NOT ?", (key, name, tid)).fetchone():
        return None, "This email already has a template called “%s”." % name
    return name, None


def _email_tpl_dates(db, row, raw_from, raw_to):
    """((from, to), error) for giving `row` dates: both days, the first not after the last, not over in the past, at
    most EMAIL_TPL_SPAN_MAX days, and no day another of this email's templates already covers."""
    f, t = _rm_date(raw_from), _rm_date(raw_to)
    if not f or not t:
        return None, "Give both days: the first and the last it's used."
    if t < f:
        return None, "The last day comes before the first."
    if t < _today_myt():
        return None, "Those days are over, so it would never be used."
    if (t - f).days + 1 > EMAIL_TPL_SPAN_MAX:
        return None, "Dates cover %d days at most." % EMAIL_TPL_SPAN_MAX
    for o in email_tpl_rows(db, row["email"]):
        if o["id"] != row["id"] and o["date_from"] and o["date_to"] and \
                o["date_from"] <= t.isoformat() and f.isoformat() <= o["date_to"]:
            return None, "“%s” already covers %s. Two templates can't cover the same day." % (
                o["name"], _email_tpl_span(o["date_from"], o["date_to"]))
    return (f.isoformat(), t.isoformat()), None


def _email_tpl_span(d_from, d_to):
    """'Mon 2 Nov' or 'Mon 2 Nov to Sun 8 Nov'."""
    f, t = date.fromisoformat(d_from), date.fromisoformat(d_to)
    return _em_day(f) if f == t else "%s to %s" % (_em_day(f), _em_day(t))


def email_tpl_when(db, key):
    """When `key`'s email goes, in words, for Cycle > Emails."""
    if own_id_of(key):   # an own email: its own schedule, from the row (a removed series says so)
        o = db.execute("SELECT * FROM email_own WHERE id=?", (own_id_of(key),)).fetchone()
        return email_own_when(o) if o else ""
    if key == "reminder":
        r = reminder_rules()
        if not r["enabled"]:
            return "Off: it goes only with Send now"
        bits = []
        if r["on_open"]:
            bits.append("when a part opens")
        early = sorted((d for d in r["days_before"] if d), reverse=True)
        if early:
            bits.append("%s day%s before a part closes" % (
                _lc_join([str(d) for d in early]), "" if early == [1] else "s"))
        if 0 in r["days_before"]:   # Email's "the day a part closes" (2026-10-24)
            bits.append("the day a part closes")
        if r["every_days"]:
            bits.append(("every day" if r["every_days"] == 1 else "every %d days" % r["every_days"])
                        + ((" " + _rm_span(_rm_date(r["every_from"]), _rm_date(r["every_to"])))
                           if (r["every_from"] or r["every_to"]) else ""))
        return "%s, at %s" % (_lc_join(bits) or "on no rule yet", r["send_time"])
    if key == "lp_bgadmin":
        r = bga_rules()
        return ("Every day at %s, from the day after a part opens, while it is open" % r["send_time"]) if r["enabled"] \
            else "Off: it doesn't go out on its own"
    if key.startswith("lp_"):
        r = lp_rules()
        if not r["enabled"] or key[3:] not in r["roles"]:
            return "Off: it goes only with Send now"
        return "%s, at %s" % (lp_schedule_words(r), r["send_time"])
    if key.startswith("ready_"):
        r = ready_rules()
        if not r["enabled"] or key[6:] not in r["roles"]:
            return "Off: it doesn't go out on its own"
        return "Once for each place, at the first check at or after %s once everyone below has finished" % r["send_time"]
    if key == "notice_before":
        return "When a notice is posted (Admin › Notices)"
    if key == "notice_after":
        return "When OneHR is back after a notice that closed it"
    if key == REDO_KIND:
        return ("When Group People adds a KPI line or a competency after someone started, or swaps their competencies" if redo_email_on()
                else "Off: the super admin switched it off, so nothing goes out")
    if key == TB_ROUND_KIND:
        return "When Group People pushes a unit's Talent Box Round 2 to the BG CEO, and on Remind (Talent Box › Round 2 · Actual)"
    if key in (GH_PROG_KIND["hod"], GH_PROG_KIND["buceo"]):
        return ("The day their part opens for them, 3 days before it closes and on its last day, at %s (Email › Schedule)"
                % reminder_rules()["send_time"]) if gradeh_reminders_on(db) else "Off: the Grade H switch on Email › Schedule is off"
    if key in (GH_READY_KIND["hod"], GH_READY_KIND["buceo"]):
        return ("Once for each place, at the first check at or after %s once everyone below has finished" % ready_rules()["send_time"]
                ) if gradeh_reminders_on(db) else "Off: the Grade H switch on Email › Schedule is off"
    if key == "gradeh_ready":
        return "When the line manager submits a Grade H appraisal"
    if key == "gradeh_result":
        return "When Group People releases a unit's Grade H results (Cycle > Release results)"
    if key == "gradeh_reminder":
        return "The day their KPI achievement or acknowledging opens, then the last calls (Email › Schedule)"
    return ("When results are released to the leaders" if key == "release_lead"
            else "When results are released to them")


def _lc_join(bits):
    bits = [b for b in bits if b]
    s = bits[0] if len(bits) == 1 else ", ".join(bits[:-1]) + " and " + bits[-1] if bits else ""
    return s[:1].upper() + s[1:]


def email_tpl_sample(db, key, words, me, cyc=None, lang=None, case=None):
    """(subject, html) of `key`'s email in `words`, as an example addressed to `me` (the admin's own name, never
    anyone else's): the made-up parts, units and counts Cycle > Emails previews and sends as a test."""
    cyc = cyc or active_cycle(db) or {"id": 0, "name": "%d Year-End" % _today_myt().year}
    today = _today_myt()
    if own_id_of(key):   # an own email: made-up items, addressed to the admin (never anyone else's name)
        return email_own_mail(db, me, _own_sample_items(db, cyc, today), cyc, words, day=today)

    def closes(cell):
        d = _reminder_close_date(db, (cell,), cyc["id"]) if cyc["id"] else None
        return d if d and d >= today else today + timedelta(days=6)
    if key == "reminder":
        items = [{"group": "f360", "role": "f360", "text": _REMINDER_OWN_TEXT["feedback"], "detail": "2 colleagues left",
                  "closes": "", "closes_on": closes("f360"), "url": "/review"},
                 {"group": "own", "role": "own", "text": _REMINDER_OWN_TEXT["account"], "detail": "",
                  "closes": "", "closes_on": closes("pm_results"), "url": "/review"},
                 {"group": "own", "role": "own", "text": _REMINDER_OWN_TEXT["competency"], "detail": "",
                  "closes": "", "closes_on": closes("tc_self"), "url": "/review"}]
        return reminder_mail(me, items, cyc, tpl=words, db=db)
    if key.startswith("lp_"):
        role = key[3:]
        open_parts = [(LP_PART["pm_results"], closes("pm_results")), (LP_PART["tc_self"], closes("tc_self"))]
        places = (("Finance", 14, 5, 9), ("Operations", 22, 13, 15), ("Sales", 18, 18, 12)) if role in ("buceo", "cg") else \
            (("Line manager A's team", 14, 5, 9), ("Line manager B's team", 22, 13, 15),
             ("Line manager C's team", 18, 18, 12)) if role == "hod" else \
            (("Sample unit A", 140, 61, 88), ("Sample unit B", 96, 70, 81))
        rows = [{"name": n, "people": p, "cells": [_lp_cell(p, a), _lp_cell(p, b)]} for n, p, a, b in places]
        tot = sum(p for _n, p, _a, _b in places)
        sec = {"bg": None, "co": None, "name": {"buceo": "Sample unit", "cg": "Sample calibration group",
                                                "hod": "Sample department"}.get(role, "Sample group"), "rows": rows,
               "people": tot, "gid": 1 if role == "cg" else None,
               "total": [_lp_cell(tot, sum(a for _n, _p, a, _b in places)),
                                        _lp_cell(tot, sum(b for _n, _p, _a, b in places))]}
        note = ({"lm_closes": _em_day(closes("pm_approve"))} if role == "hod" else   # the overlap note, made up
                {"hod_closes": _em_day(closes("pm_hod")), "scope_noun": "Calibration Group" if role == "cg" else "unit"}
                if role in LP_NOTE_ROLES else None)
        return lp_mail(db, role, me, [sec], open_parts, [], cyc, tpl=words,
                       rules=bga_rules() if role == "bgadmin" else None, note=note)
    if key.startswith("ready_"):   # made-up: the window the preview's chip picks ('open', else 'later'), nobody real
        role = key[6:]
        cell = "pm_hod" if role == "hod" else "pm_buceo"
        later = case == "later"
        win = {"mode": "later" if later else "open", "opens": today + timedelta(days=3) if later else None,
               "closes": closes(cell) if not later else today + timedelta(days=9)}
        return ready_mail(db, role, me, _ready_sample_places(role), win, cyc, tpl=words)
    if key in (GH_PROG_KIND["hod"], GH_PROG_KIND["buceo"]):   # made-up counts, addressed to the admin: no person, no real team
        kind = key.rsplit("_", 1)[1]
        return gradeh_prog_mail(db, gradeh_prog_sample(db, kind, me, cyc, closes("gradeh_hod_pot" if kind == "hod" else "gradeh_buceo")),
                                cyc, tpl=words)
    if key in (GH_READY_KIND["hod"], GH_READY_KIND["buceo"]):   # made-up: the window the preview's chip picks ('open', else 'later')
        kind = key.rsplit("_", 1)[1]
        later = case == "later"
        close = datetime.combine(closes("gradeh_hod_pot" if kind == "hod" else "gradeh_buceo"), datetime.min.time()).replace(hour=23, minute=59)
        win = {"mode": "later" if later else "open", "ahead_of": None if later else today + timedelta(days=7),
               "opens": today + timedelta(days=3) if later else None, "closes": close}
        return gradeh_ready_mail(db, {"kind": kind, "user": me, "scope": "Sample unit", "key": "Sample unit", "win": win,
                                      "people": 46 if kind == "buceo" else 30, "hods": 4}, cyc, tpl=words)
    if key == "release_lead":
        return _release_lead_mail(db, me, 12, {"n": 2}, ["Sample unit"], cyc, False, False, tpl=words)
    if key in ("notice_before", "notice_after"):   # a made-up upgrade tonight at the window's time
        r = release_rules()
        n = {"id": 0, "kind": "upgrade", "starts_at": "%s %s" % (today.isoformat(), r["start"]),
             "downtime_min": r["downtime"], "closes": 1, "email_before": 1, "email_after": 1}
        return notice_mail(db, key, n, me, "Your check-in is open until %d %s" % (
            closes("pm_results").day, closes("pm_results").strftime("%b")), tpl=words)
    if key == REDO_KIND:   # made-up items, addressed to the admin
        return _redo_mail(db, me, [{"kind": "kpi", "name": "Sample KPI"}, {"kind": "tc_add", "title": "Sample competency"},
                                   {"kind": "tc_swap", "added": ["Sample competency A"], "removed": ["Sample competency B"]}],
                          cyc, tpl=words)
    if key == TB_ROUND_KIND:   # made-up units and figures, addressed to the admin
        due = _late_utc(datetime.combine(today + timedelta(days=5), datetime.min.time()).replace(hour=23, minute=59, second=59))
        sample = [{"period_id": 0, "company": "Sample unit A", "forecast_pct": 85.0, "actual_pct": 62.0, "curve_before": "normal",
                   "curve_after": "negative", "due_at": due},
                  {"period_id": 0, "company": "Sample unit B", "forecast_pct": 118.0, "actual_pct": 140.0, "curve_before": "normal",
                   "curve_after": "positive", "due_at": due}]
        lines = [{"label": r["company"], "forecast": _tb_round_pct(r["forecast_pct"]), "actual": _tb_round_pct(r["actual_pct"]),
                  "before": PAT_CURVE_SHORT[r["curve_before"]], "after": PAT_CURVE_SHORT[r["curve_after"]],
                  "due_at": r["due_at"]} for r in sample]
        return _tb_round_mail_from_lines(db, me, lines, cyc, tpl=words)
    if key == "gradeh_ready":
        return _gradeh_ready_mail(db, me, "en", cyc["name"], tpl=words)
    if key == "gradeh_result":
        return _gradeh_result_mail(db, me, "en", cyc["name"], tpl=words)
    if key == "gradeh_reminder":   # made-up dates: the KPI close six days out, the deemed date a day after it
        dt = datetime.combine(closes("gradeh_kpi"), datetime.min.time()).replace(hour=23, minute=59)
        case = {"case": case or "kpi", "cell": "gradeh_kpi", "closes": dt, "deemed": dt + timedelta(days=1)}
        return _gradeh_reminder_mail(db, me, lang if lang in GRADEH_LANGS else "en", case, cyc["name"], tpl=words)
    return _release_person_mail(db, me, {"pm", "pot", "talent", "report"}, cyc, tpl=words)


def email_tpl_view(db, key, today=None):
    """One email's line on Cycle > Emails and its panel: its templates, the one in use today, what takes over next."""
    today = today or _today_myt()
    k = email_tpl_kind(key, db)
    rows = email_tpl_rows(db, key)
    cur = email_tpl_pick(rows, today)
    ids = sorted({r["updated_by"] for r in rows if r["updated_by"]})
    who = {r[0]: r[1] for r in db.execute("SELECT id, full_name FROM users WHERE id IN (%s)" % ",".join("?" * len(ids)),
                                          ids)} if ids else {}
    tpls = []
    for r in rows:
        w = email_tpl_saved(r)
        if r["date_from"] and r["date_to"]:
            when = _email_tpl_span(r["date_from"], r["date_to"])
            past = r["date_to"] < today.isoformat()
        else:
            when, past = ("The usual one" if r["usual"] else "Not in use"), False
        tpls.append({"id": r["id"], "name": r["name"], "usual": bool(r["usual"]), "from": r["date_from"] or "",
                     "to": r["date_to"] or "", "when": when, "past": past,
                     "in_use": bool(cur is not None and cur["id"] == r["id"]),
                     "mode": "usual" if r["usual"] else "dates" if r["date_from"] else "none",
                     "subject": w["subject"],
                     "edited": _when_disp(_myt(r["updated_at"] or r["created_at"])),
                     "by": who.get(r["updated_by"]) or ""})
    return {"key": key, "title": k["title"], "who": k["who"], "lists": k["lists"], "when": email_tpl_when(db, key),
            "page": k["page"], "role": k.get("role"), "in_use": cur["name"] if cur else None,
            "next": [{"day": _em_day(d), "name": r["name"]} for d, r in email_tpl_changes(rows, today)][:4],
            "templates": tpls}


# --- when the server's job may send: the super admin's time (Chris's Reminders page, "Send at") ----------------------
# The timer checks every 15 minutes (the reminders timer unit); `--auto` sends on a send day once the
# chosen time has come, once a day, and not more than REMINDER_LATE_HOURS after it (a box that was down all morning
# doesn't email everyone at night). Each run leaves a heartbeat, so the page can say how often the server checks.
REMINDER_LATE_HOURS = 3


def reminder_due_now(db, rules=None, now=None):
    """(True, '') when the daily job should send now, else (False, why)."""
    rules = rules or reminder_rules()
    now = now or _now_myt()
    hh, mm = (int(x) for x in rules["send_time"].split(":"))
    at = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
    if now < at:
        return False, "Not yet: the reminder goes at %s." % rules["send_time"]
    sk = email_skip_row(db, "reminder", now.date())   # the super admin skipped today (2026-11-09): nothing written, so it is not "sent"
    if sk:
        return False, email_skip_words(sk)
    if _setting("reminder_auto_last") == now.date().isoformat():
        return False, "Already sent today."
    if now - at > timedelta(hours=REMINDER_LATE_HOURS):
        return False, "More than %d hours after today's %s: it goes on the next send day instead." % (
            REMINDER_LATE_HOURS, rules["send_time"])
    return True, ""


def reminder_mark_sent_today(db, now=None):
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_auto_last', ?)",
               ((now or _now_myt()).date().isoformat(),))
    db.commit()


def gradeh_staff_last_key(db):
    """The setting the Grade H staff email's once-a-day check reads: its own `gradeh_staff_last` once that row exists; until then (the
    first run after the key was introduced) Everyone's reminder's `reminder_auto_last`, so a deploy on a staff day after the reminder
    has gone does not send the staff email a second time."""
    return GRADEH_STAFF_LAST_KEY if db.execute("SELECT 1 FROM app_settings WHERE key=?", (GRADEH_STAFF_LAST_KEY,)).fetchone() \
        else "reminder_auto_last"


def gradeh_staff_mark_today(db, now=None):
    """The Grade H staff email's turn ran today (its own *_last, as Everyone's reminder has reminder_auto_last): written before sending."""
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)",
               (GRADEH_STAFF_LAST_KEY, (now or _now_myt()).date().isoformat()))
    db.commit()


def reminder_auto_plan(db, cyc, now=None):
    """What the server job's reminder turn sends now (send_reminders.py --auto): {regular: Everyone's reminder goes, staff: the Grade H
    staff email goes, why: the sentence of reasons, notes: the lines to print}. TWO tracks, since 2026-11-09:
      * Everyone's reminder: its own switch on, due now (reminder_due_now: its time, once a day, and no skip of 'reminder'), and a day
        its rules pick that is not a day only Grade H staff's email goes on;
      * the Grade H staff email: the Grade H switch on (gradeh_rm_active) and NOT Everyone's reminder's, due at the same time, once
        a day (its own gradeh_staff_last), no skip of 'gradeh', and a day the rules give Grade H staff (read with Everyone's reminder's
        switch ignored).
    Nothing is marked here: the caller marks what it sends before sending it."""
    now = now or _now_myt()
    today = now.date()
    rules = reminder_rules()
    out = {"regular": False, "staff": False, "why": "", "notes": []}
    if not rules["enabled"]:
        out["notes"].append("Automatic reminders are off on Cycle > Reminders — nothing to do.")
    else:
        due, why_not = reminder_due_now(db, rules, now)
        if not due:
            out["notes"].append(why_not)
        else:
            reasons = reminder_reasons(db, cyc, today, rules)
            if not reasons:
                out["notes"].append("Not a send day under the rules — nothing to do.")
            elif reminder_day_parts(db, cyc, today, rules)["regular"]:
                out["regular"], out["why"] = True, "; ".join(reasons)
                out["notes"].append("Send day: " + out["why"])
    if gradeh_rm_active(db, cyc):
        due, why_not = lp_due_now(db, {"send_time": rules["send_time"]}, now, last_key=gradeh_staff_last_key(db),
                                  what="the Grade H staff reminders", skip_key="gradeh")
        if not due:
            if why_not.startswith("Skipped today"):
                out["notes"].append("Grade H staff reminders: " + why_not)
        elif reminder_day_parts(db, cyc, today, rules, True)["staff"]:
            out["staff"] = True
            if not out["why"]:
                out["why"] = "; ".join(dict.fromkeys(w for _k, c, w in reminder_why(db, cyc, today, dict(rules, enabled=True))
                                                      if c in GRADEH_STAFF_CELLS))
                out["notes"].append("Send day: " + out["why"])
    return out


def reminder_runner_seen(db, now=None):
    """The server's job ran: keep its last three times (MYT)."""
    try:
        runs = json.loads(_setting("reminder_runner_runs", "[]") or "[]")
    except (TypeError, ValueError):
        runs = []
    runs = (runs + [(now or _now_myt()).strftime("%Y-%m-%d %H:%M")])[-3:]
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_runner_runs', ?)", (json.dumps(runs),))
    db.commit()


def reminder_runner_cadence():
    """'none' (this server's job has never run), 'often' (it checks every few minutes, so any send time works) or
    'daily' (the old once-a-day timer: only its own hour works)."""
    try:
        runs = [_parse_when(x) for x in json.loads(_setting("reminder_runner_runs", "[]") or "[]")]
    except (TypeError, ValueError):
        runs = []
    runs = [r for r in runs if r]
    if not runs:
        return "none"
    if len(runs) >= 2 and (runs[-1] - runs[-2]) <= timedelta(minutes=30):
        return "often"
    return "daily"


# --- the page's count of who's waiting: computed in the background, kept in app_settings ---------------------
REMINDER_SNAPSHOT_FRESH_MIN = 10
REMINDER_SNAPSHOT_STALE_MIN = 10   # a "counting" flag older than this is a crashed count


def _reminder_snapshot_compute(db):
    """{cycle, at, people: {uid: [bg, company, roles, n, has_email]}} for everyone with something waiting."""
    cyc = active_cycle(db)
    people = {}
    for u in reminder_people(db):
        items = _reminder_drop_bu_lead(u, reminder_items(db, u))   # a BG CEO who is also a BU CEO gets no BU CEO email (Chris, 2026-11-11): the count agrees with the send
        if items:
            people[str(u["id"])] = [u["business_group"], u["company"] or "", sorted({i["role"] for i in items}),
                                    len(items), bool((u["email"] or "").strip())]
    return {"cycle": cyc["id"] if cyc else None, "at": _now_myt().strftime("%Y-%m-%d %H:%M"), "people": people}


def _reminder_snapshot_job(flask_app):
    with flask_app.test_request_context("/", base_url=app_base_url()):
        db = get_db()
        try:
            snap = _reminder_snapshot_compute(db)
            db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_snapshot', ?)",
                       (json.dumps(snap),))
        except Exception:   # noqa: BLE001 -- a failed count must not leave the page counting forever
            flask_app.logger.exception("reminder count failed")
        finally:
            db.execute("DELETE FROM app_settings WHERE key='reminder_snapshot_running'")
            db.commit()


def reminder_snapshot(db, start=True):
    """(snapshot or None, counting). Starts a background count when there is none fresh for the active cycle and none
    already running (the flag lives in app_settings, so every worker sees it)."""
    try:
        snap = json.loads(_setting("reminder_snapshot", "") or "null")
    except (TypeError, ValueError):
        snap = None
    cyc = active_cycle(db)
    at = _parse_when(snap.get("at")) if snap else None
    fresh = bool(snap and cyc and snap.get("cycle") == cyc["id"] and at
                 and _now_myt() - at < timedelta(minutes=REMINDER_SNAPSHOT_FRESH_MIN))
    running = _parse_when(_setting("reminder_snapshot_running", "") or "")
    counting = bool(running and _now_myt() - running < timedelta(minutes=REMINDER_SNAPSHOT_STALE_MIN))
    if not fresh and not counting and start and cyc:
        db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_snapshot_running', ?)",
                   (_now_myt().strftime("%Y-%m-%d %H:%M:%S"),))
        db.commit()
        threading.Thread(target=_reminder_snapshot_job, args=(app,), daemon=True).start()
        counting = True
    if snap and cyc and snap.get("cycle") != cyc["id"]:
        snap = None
    return snap, counting


def reminder_waiting(db, me, snap):
    """The page's 'Who's waiting' for this admin's scope: {roles: [{key, label, n, what}], total, no_email, opted_out, at}.
    People the super admin took off Everyone's reminder (2026-11-01) are left out of the tiles and the total and counted
    in opted_out: they have something waiting but get no email."""
    off = {str(i) for i in email_optout_ids(db, "reminder")}
    mine = [(i, p) for i, p in (snap or {}).get("people", {}).items() if can_access(me, p[0], p[1] or None)]
    ppl = [p for i, p in mine if str(i) not in off]
    opted = sum(1 for i, _p in mine if str(i) in off)
    cyc = active_cycle(db)
    roles = []
    for key, label, what, cells in REMINDER_ROLES:
        n = sum(1 for p in ppl if key in p[2])
        if not n and cyc:
            opens = [_parse_when(window_dates(db, c, cyc["id"])[0]) for c in cells]
            later = sorted(o for o in opens if o and o > _now_myt())
            if later and not any(window_state(db, c, cyc["id"]) == "open" for c in cells):
                what = "%s opens %d %s" % (what, later[0].day, later[0].strftime("%b"))
        roles.append({"key": key, "label": label, "n": n, "what": what})
    return {"roles": roles, "total": len(ppl), "no_email": sum(1 for p in ppl if not p[4]), "opted_out": opted,
            "at": (snap or {}).get("at")}


def _reminder_send_job(flask_app, cid, people_ids, why, actor_id):
    """Send now, on a background thread: working out everyone's items outlasts the proxy's timeout. It only queues
    (2026-10-21): each email goes in the outbox with its wave's time, committed as it goes, and the sender sends them.
    The cooldown skips anyone already emailed or queued, so a crash part-way is safe to repeat."""
    with flask_app.test_request_context("/", base_url=app_base_url()):
        db = get_db()
        try:
            cyc = db.execute("SELECT * FROM cycles WHERE id=?", (cid,)).fetchone()
            ppl = [db.execute("SELECT * FROM users WHERE id=?", (i,)).fetchone() for i in people_ids]
            reminder_send(db, cyc, [p for p in ppl if p], why, actor_id=actor_id, live=True, gh_staff="all")
        except Exception:   # noqa: BLE001
            flask_app.logger.exception("Background reminder send crashed")
        finally:
            _clear_bulk_send_running()


# A stuck "running" flag (e.g. from a crash) shouldn't permanently block new
# bulk sends — treat it as stale past this many hours.
BULK_SEND_STALE_HOURS = 2


def bulk_send_status():
    """Whether a background bulk send is currently running, plus its
    {total, started_at, started_by} metadata. A flag left behind by a crashed
    process is treated as stale (not running) after BULK_SEND_STALE_HOURS."""
    running = _setting("reminder_bulk_running", "0") == "1"
    meta = {}
    if running:
        try:
            meta = json.loads(_setting("reminder_bulk_meta", "{}") or "{}")
        except (ValueError, TypeError):
            meta = {}
        started = _parse_when(meta.get("started_at"))  # stored as MYT wall-clock, see below
        if started and (_now_myt() - started) > timedelta(hours=BULK_SEND_STALE_HOURS):
            running = False
    return running, meta


def _set_bulk_send_running(total, actor_name, cycle_id):
    db = get_db()
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_bulk_running','1')")
    db.execute(
        "INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_bulk_meta', ?)",
        # started_at is MYT wall-clock (matches how the rest of the admin UI
        # displays times to admins), not the DB's usual UTC storage convention.
        (json.dumps({"total": total, "started_at": _now_myt().strftime("%Y-%m-%d %H:%M:%S"),
                    "started_by": actor_name, "cycle_id": cycle_id}),))
    db.commit()


def _clear_bulk_send_running():
    db = get_db()
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES ('reminder_bulk_running','0')")
    db.commit()


@app.route("/admin/email")
@super_required
def admin_email_schedule():
    """Email › Schedule (Chris, 2026-10-24: "merge reminder and email into email, and place them as a menu item on the left
    panel ... since this email eventually will serve all modules at any time (including learning)"; 2026-11-09: "can we have a
    calendar view for email"; canvas [design canvas link removed], "Yes, as drawn"): the top card (a switch,
    the next send and Set it up for each email) and the calendar, a month from ONE plan (email_cal_plan) with the emails that go on
    an action instead under it. ?m=YYYY-MM is the month, ?show= a chip. A day opens in the list panel (email-day). The super admin's
    only, as the whole Email menu is. Writes nothing."""
    db = get_db()
    me = current_user()
    cyc = active_cycle(db)
    rules = reminder_rules()
    now = _now_myt()
    first = email_cal_month(request.args.get("m"))
    last = _cal_shift(first, 1) - timedelta(days=1)
    show = request.args.get("show") if request.args.get("show") in dict(EMAIL_CAL_CHIPS) else "all"
