# ---- the calendar's view of a series (the plan and the day panel read these) ------------------------------------------------------------------
def _own_cal_meta(own_rows):
    """{own key: (name, the chip's short name, group)} for own emails: a series that repeats wears ↻, as the canvas draws it."""
    return {_own_key(o["id"]): (o["name"], ("↻ " + o["name"]) if o["repeat"] != "once" else o["name"], "own") for o in own_rows}


def _own_cal_card(db, cyc, e, day, now, ctx):
    """The day panel's extras for an own email's card: its tag, Sends line and the series' actions."""
    own = ctx["memo"].setdefault("own:%s" % e["key"], email_own_row(db, own_id_of(e["key"]), live=False))
    if not own:
        return {}
    to_come = email_own_to_come(db, cyc, own, now) if not own["removed_at"] else []
    return {"own": {"id": own["id"], "tag": email_own_tag(own), "sends": _own_sends_words(db, cyc, own, now) if not own["removed_at"] else "",
                    "live": not own["removed_at"],
                    "edit_url": url_for("admin_list_view", key="email-own", id=own["id"], day=day.isoformat()),
                    "remove_confirm": "Remove %s? Its %d send%s still to come won't go. What was already sent stays in Email › Sent." % (
                        own["name"], len(to_come), "" if len(to_come) == 1 else "s")}}


# --- Email › Sent: every run opens its people (Chris, 2026-11-03: "for sent, add in email sent to admin too, and can we keep
# each item open into right panel to show the person and email successfully send, or failed"; canvas
# [design canvas link removed], boards A to E, "Yes, as drawn"; he picked "BG admin + notices") -----------
# A run is one 'reminder_run' / 'leader_progress_run' / 'bg_admin_progress_run' activity row. Its emails are the outbox rows of
# its batch key (named in the row's detail since this release: "... | batch <key>"), else, for a run from before, the rows of its
# kind queued after the run before it and up to its own row; its run-time skips (the cooldown, nothing to report, no email,
# opted out, a dry run) are the notifications rows of its kind in that same window. ONE classification (_es_state_of / _es_why)
# serves the page's second lines and the panel's chips and rows, so the numbers on the page can't disagree with the panel.
# Counts come from grouped reads (a card is one outbox query and one notifications query, never one per run); the panel reads
# one run's rows, 500 shown. Staff addresses show only in these super admin panels.
ES_NAMED_FROM = "4 Nov"   # the release that began logging every skipped person: a run before it can't name them all
ES_RUNS = {
    "reminder": {"action": "reminder_run", "kinds": (REMINDER_KIND, GRADEH_REMINDER_KIND), "list": "email-run",
                 "label": "Everyone's reminder", "noun": ("person", "people")},
    "lp": {"action": "leader_progress_run", "kinds": (LP_KIND,), "list": "email-lp-run", "label": "Leader progress",
           "noun": ("leader", "leaders")},
    "bga": {"action": "bg_admin_progress_run", "kinds": (BGA_KIND,), "list": "email-bga-run", "label": "BG admin status",
            "noun": ("BG admin", "BG admins")},
    # Grade H progress (2026-11-09, the email calendar): its run row is 'gradeh_lp_run', its emails the two progress kinds
    "ghp": {"action": "gradeh_lp_run", "kinds": (GH_PROG_KIND["hod"], GH_PROG_KIND["buceo"]), "list": "email-ghp-run",
            "label": "Grade H progress", "noun": ("leader", "leaders")},
    # Your own emails (2026-11-09, piece C): its run row is 'email_own_run', its emails the OWN_KIND rows of the run's batch
    "own": {"action": "email_own_run", "kinds": (OWN_KIND,), "list": "email-own-run", "label": "Your own emails", "noun": ("person", "people")},
}
ES_RECHECK_WHY = (REMINDER_NOTHING_LEFT, REMINDER_OPTED_OUT, REMINDER_OPTOUT_UNREAD)   # logged at send time, from cancelled rows
ES_WHY = (   # (what the log says, lower case, its start) -> the words on screen
    (REMINDER_NOTHING_LEFT.lower(), "Nothing left to do by their wave"),
    (OWN_REMOVED.lower(), "Removed before it went"),
    (OWN_SKIPPED_SINCE.lower(), "Skipped before it went"),
    (REDO_NOTHING_LEFT.lower(), "Nothing left to fill in by then"),
    (REDO_SWITCHED_OFF.lower(), "Switched off before it was due"),
    (REMINDER_OPTOUT_UNREAD.lower(), "Opt-out couldn't be read"),
    ("opted out", "Opted out"),
    ("no email on file", "No email on file"),
    ("already emailed", "Already emailed in the last %d hours" % REMINDER_COOLDOWN_HOURS),
    ("nothing to report", "Nothing to report"),
    ("no notification email", "No notification email"),
)
# an admin-task email's subject -> what it is on the Admin notices card (the first that is in the subject, lower case)
ES_NOTICE_TYPES = (
    ("new joiner", "New joiners to set up"), ("kpi lines to set", "KPI lines to set"),
    ("library proposal", "KPI library proposal"), ("competency proposal", "Competency proposal"),
    ("a test from onehr", "Test email"),
)
ES_NOTICE_KINDS = {HELP_KIND: "Help report", SIGNIN_HELP_KIND: "Sign-in help"}
ES_SHOW = ("all", "sent", "failed", "waiting", "not_sent")
ES_SHOW_LABEL = {"all": "All", "sent": "Sent", "failed": "Failed", "waiting": "Waiting", "not_sent": "Not sent"}
ES_TONE = {"sent": "ok", "failed": "bad", "waiting": "info", "not_sent": "off"}
ES_RANK = {"failed": 0, "waiting": 1, "not_sent": 2, "sent": 3}   # the panel's order: what needs a look first
ES_NOTICE_DAYS = 14


def _es_batch_bit(bits):
    """The batch key an activity row names ("batch reminder-1a2b3c4d5e6f"), or ''. `bits` are its '|' parts."""
    return next((b[6:].strip() for b in bits[1:] if b.startswith("batch ")), "")


def _es_state_of(status):
    """The chip an outbox row is under: sent, failed, not sent (cancelled) or waiting (queued, or being sent now)."""
    return {"sent": "sent", "failed": "failed", "cancelled": "not_sent"}.get(status, "waiting")


def _es_why(detail):
    """The plain words for why a person was not emailed, from what the log says."""
    d = (detail or "").strip()
    low = d.lower()
    for key, words in ES_WHY:
        if low.startswith(key):
            return words
    return d[:90] or "Not sent"


def _es_err(text, n=90):
    """A failure's reason, short and never a stack trace: its first line, cut at n characters."""
    t = " ".join(str(text or "").split("\n")[0].split())
    return "Send failed" if (not t or "Traceback" in t) else (t[:n] + ("…" if len(t) > n else ""))


def _es_fmt_when(raw):
    """'3 Nov 2026, 09:02' (MYT) from a stored UTC time."""
    t = _parse_when(raw)
    if not t:
        return ""
    t += timedelta(hours=8)
    return "%d %s %d, %s" % (t.day, t.strftime("%b"), t.year, t.strftime("%H:%M"))


def _es_clock(raw):
    """(HH:MM, the day when it is not today or '') in MYT from a stored UTC time."""
    t = _parse_when(raw)
    if not t:
        return "", ""
    t += timedelta(hours=8)
    return t.strftime("%H:%M"), ("" if t.date() == _today_myt() else _em_day(t))


def _es_window(kind, run, prev):
    """`run` (a reminder_runs / lp_runs / bga_runs row) with the window its emails sit in: prev, the time of the run before it
    ('' for the first ever), and, for a reminder, direct: it sent straight, not through the outbox (a redirected test, or a run
    before the waves)."""
    return dict(run, kind=kind, prev=prev or "",
                direct=bool(kind == "reminder" and not run["batch"] and not run["queued"] and (run["sent"] or run["failed"])))


def _es_prev(db, kind, run_id):
    """The time of the run of this kind written before run_id, or ''."""
    return (db.execute("SELECT created_at FROM activity_log WHERE action=? AND id<? ORDER BY id DESC LIMIT 1",
                       (ES_RUNS[kind]["action"], run_id)).fetchone() or [""])[0]


def _es_runs_of(db, kind, runs):
    """`runs` (newest first) as windows: each one's prev is the next one's time (one extra read for the oldest shown)."""
    return [_es_window(kind, r, runs[i + 1]["at"] if i + 1 < len(runs) else _es_prev(db, kind, r["id"]))
            for i, r in enumerate(runs)]


# a batched email is grouped by its batch (its first row's time stands for it: the window match reads that), only a row with no
# batch (a leader or BG admin run from before this release) by its own second: a 20-run card reads tens of groups, not an email each
_ES_OB_GROUPS = ("SELECT batch, kind, MIN(created_at) AS created_at, status, COALESCE(send_after > datetime('now'), 0) AS later, "
                 "COALESCE(error,'') AS error, COUNT(*) AS n FROM email_outbox WHERE kind IN (%s) AND created_at > ? "
                 "GROUP BY batch, kind, CASE WHEN batch IS NULL THEN created_at END, status, later, error")
_ES_NF_GROUPS = ("SELECT kind, created_at, status, COALESCE(detail,'') AS detail, COUNT(*) AS n FROM notifications WHERE kind "
                 "IN (%s) AND created_at > ? AND ((status IN ('skipped','dryrun') AND COALESCE(detail,'') NOT IN (?,?,?))"
                 "%s) GROUP BY kind, created_at, status, detail")
_ES_DIRECT = " OR (status IN ('sent','failed') AND pending_count IS NOT NULL)"   # a reminder sent straight logs how many waited


def _es_tallies(db, kind, runs):
    """{run id: {sent, failed, waiting, not_sent, all, rows, ob}} for the runs of one card (from _es_runs_of), in two grouped
    reads over everything since the oldest run's window began, never one per run. `rows` = outbox rows (BG admins: addresses);
    `ob` = the same counted by state, without the skipped people."""
    spec = ES_RUNS[kind]
    out = {r["id"]: {"sent": 0, "failed": 0, "waiting": 0, "not_sent": 0, "all": 0, "rows": 0,
                     "ob": {"sent": 0, "failed": 0, "waiting": 0, "not_sent": 0}} for r in runs}
    if not runs:
        return out
    since = min(r["prev"] or "" for r in runs)
    ph = ",".join("?" * len(spec["kinds"]))
    ob = db.execute(_ES_OB_GROUPS % ph, list(spec["kinds"]) + [since]).fetchall()
    nf = db.execute(_ES_NF_GROUPS % (ph, _ES_DIRECT if kind == "reminder" else ""),
                    list(spec["kinds"]) + [since] + list(ES_RECHECK_WHY)).fetchall()
    by_batch = {r["batch"]: r for r in runs if r["batch"]}
    for g in ob:
        r = by_batch.get(g["batch"]) if g["batch"] else None
        if r is None:
            r = next((c for c in runs if not c["batch"] and c["prev"] < g["created_at"] <= c["at"]), None)
        if r is not None:
            out[r["id"]][_es_state_of(g["status"])] += g["n"]
            out[r["id"]]["ob"][_es_state_of(g["status"])] += g["n"]   # the emails themselves (a BG admin's: addresses), not the skips
            out[r["id"]]["rows"] += g["n"]
    for g in nf:
        r = next((c for c in runs if c["prev"] < g["created_at"] <= c["at"]), None)
        if r is None or (g["status"] in ("sent", "failed") and not r["direct"]):
            continue
        out[r["id"]]["not_sent" if g["status"] in ("skipped", "dryrun") else g["status"]] += g["n"]
    for t in out.values():
        t["all"] = t["sent"] + t["failed"] + t["waiting"] + t["not_sent"]
    return out


def _es_unlisted(run, named):
    """How many skips a run counted that its log never named (the runs before ES_NAMED_FROM): what its activity row says it
    left out, minus the skipped rows the notifications log names for it. 0 for a dry run or a direct send."""
    if run["kind"] == "own":   # an own email's skips are counts on its run row, not people its log names
        return 0
    if run["kind"] == "reminder":
        if run["dry"] or run["direct"]:
            return 0
        claimed = run["skipped"] + run["opted_out"]
    else:
        claimed = run["nothing"] + run["no_email"] + (run.get("opted_out") or 0)
    return max(0, claimed - named)


def es_cards(db, kind, runs):
    """`runs` with, on each: es (its tally), people_url / people_full (the panel's address and the page's) and unlisted: the
    page's second lines and People › links, from the same classification as the panel."""
    spec = ES_RUNS[kind]
    runs = _es_runs_of(db, kind, runs)
    tallies = _es_tallies(db, kind, runs)
    for r in runs:
        r["es"] = tallies[r["id"]]
        r["people_url"] = url_for("admin_list_view", key=spec["list"], run=r["id"], fragment=1) if r["es"]["all"] else ""
        r["people_full"] = url_for("admin_list_view", key=spec["list"], run=r["id"]) if r["es"]["all"] else ""
    return runs


def es_notices(db):
    """The Admin notices card: the last ES_NOTICE_DAYS MYT days that had an admin email, newest first: [{day, label, what,
    n, sent, failed, url, full}]. Which emails: every admin-task email; the admin copies of a Help report and of sign-in help
    (the person's own copy goes to their own address, so a row whose to_email is not the users.email of its user_id, trimmed,
    lower case, with no user counting as an admin copy). One read."""
    rows = db.execute(
        "WITH m AS (SELECT date(n.created_at, '+8 hours') AS day, n.kind, n.status, COALESCE(n.detail,'') AS detail "
        "FROM notifications n LEFT JOIN users u ON u.id=n.user_id WHERE n.status IN ('sent','failed') AND n.created_at > datetime('now','-60 days') AND (n.kind=? OR "
        "(n.kind IN (?,?) AND (n.user_id IS NULL OR lower(trim(COALESCE(n.to_email,''))) != lower(trim(COALESCE(u.email,'')))))))"
        " SELECT * FROM m WHERE day >= COALESCE((SELECT MIN(day) FROM (SELECT DISTINCT day FROM m ORDER BY day DESC LIMIT ?)), '')",
        (ADMIN_TASK_KIND, HELP_KIND, SIGNIN_HELP_KIND, ES_NOTICE_DAYS)).fetchall()
    days = {}
    for r in rows:
        d = days.setdefault(r["day"], {"day": r["day"], "n": 0, "sent": 0, "failed": 0, "types": {}})
        d["n"] += 1
        d[r["status"]] += 1
        what = _es_notice_what(r["kind"], _es_task_parts(r["kind"], r["status"], r["detail"])[0])
        d["types"][what] = d["types"].get(what, 0) + 1
    out = []
    for day in sorted(days, reverse=True):
        d = days[day]
        dt = datetime.strptime(day, "%Y-%m-%d")
        d["label"] = "%s %d %s" % (dt.strftime("%a"), dt.day, dt.strftime("%b"))
        d["what"] = " · ".join("%d %s" % (n, w) for w, n in sorted(d["types"].items(), key=lambda x: (-x[1], x[0])))
        d["url"] = url_for("admin_list_view", key="email-notices", day=day, fragment=1)
        d["full"] = url_for("admin_list_view", key="email-notices", day=day)
        out.append(d)
    return out


def _es_task_parts(kind, status, detail):
    """(subject, error) of an admin notice's notifications row: a sent row's detail is its subject; a failed admin task's is
    "<subject> · error: <error>" (ADMIN_TASK_ERR_SEP; an older failed row, and a failed Help copy, is the error alone)."""
    d = detail or ""
    if status == "sent":
        return d, ""
    if kind == ADMIN_TASK_KIND and ADMIN_TASK_ERR_SEP in d:
        subj, err = d.split(ADMIN_TASK_ERR_SEP, 1)
        return subj, err
    return "", d


def _es_notice_what(kind, subject):
    """What an admin email is, for the Admin notices card: its type by kind, an admin task's by its subject (ES_NOTICE_TYPES)."""
    if kind in ES_NOTICE_KINDS:
        return ES_NOTICE_KINDS[kind]
    low = (subject or "").lower()
    return next((w for k, w in ES_NOTICE_TYPES if k in low), "Other notice")


# ---- the panel -------------------------------------------------------------------------------------------------------------
def _es_search_args(args, kind):
    """(q, qin) the panel was asked for, read as every list of people reads its search (people_search_args)."""
    q, qin, _menu = people_search_args(("what",) if kind == "notices" else (), src=args)
    return q, (qin if qin in _es_search_spec(kind, {})["fields"] else "all")


def _es_search_spec(kind, hidden):
    """The panel's Search in: its menu (drawn by admin_list_view through people_search_args), what is kept on a new search."""
    return {"fields": ("all", "name", "what", "email") if kind == "notices" else ("all", "name", "eid", "email"),
            "extra": ("what",) if kind == "notices" else (),
            "all_ph": "Search name, what, email" if kind == "notices" else "Search name, ID, email",
            "hidden": hidden, "label": "Search the list"}


def _es_user(r, tab="overview"):
    """A people-list row's identity from an outbox / notifications read that joined the user (u_* columns), or a row with
    no account (an address no account holds)."""
    if r["user_id"] and r["u_name"] is not None:
        return _list_row({"id": r["user_id"], "full_name": r["u_name"], "employee_id": r["u_eid"],
                          "business_group": r["u_bg"], "company": r["u_company"], "department": r["u_dept"],
                          "job_grade": r["u_jg"]}, tab, [])
    return {"uid": None, "name": "No account", "eid": "", "bu": "", "dept": "", "jg": "", "href": "", "cells": [], "tone": ""}


def _es_status(state, ts, send_after="", later=0, error="", dry=False):
    """The Status cell: (pill words, tone, hover words, the muted line under it)."""
    if state == "sent":
        clock, day = _es_clock(ts)
        return ("Sent · %s" % clock, "ok", "", day)
    if state == "failed":
        return ("Failed", "bad", _es_err(error, 300), _es_err(error))
    if state == "waiting":
        if later:
            clock, day = _es_clock(send_after)
            return ("Waiting · wave %s" % clock, "info", "", day)
        return ("Going out now", "info", "", "")
    return ("Not sent", "off", "", "Dry run: nothing was sent" if dry else _es_why(error))


_ES_USER_COLS = ("u.full_name AS u_name, u.employee_id AS u_eid, u.business_group AS u_bg, u.company AS u_company, "
                 "u.department AS u_dept, u.job_grade AS u_jg, u.admin_bg AS u_adminbg, u.email AS u_email")


def _es_resolve(db, kind, args):
    """The run a panel was opened on, as es_cards would give it: ?run=<activity id> or, from the progress bar, ?batch=<key>
    (the run that names it, else the first run written after its first email). Aborts 404 for anything else."""
    spec = ES_RUNS[kind]
    rid, batch = (args.get("run") or "").strip(), (args.get("batch") or "").strip()
    row = None
    if rid.isdigit():
        row = db.execute("SELECT id, created_at, detail FROM activity_log WHERE id=? AND action=?",
                         (int(rid), spec["action"])).fetchone()
    elif kind == "reminder" and re.fullmatch(r"reminder-[0-9a-f]{6,24}", batch):
        row = db.execute("SELECT id, created_at, detail FROM activity_log WHERE action=? AND detail LIKE ? ORDER BY id DESC "
                         "LIMIT 1", (spec["action"], "%| batch " + batch)).fetchone()
        first = None if row else db.execute("SELECT MIN(created_at) FROM email_outbox WHERE batch=?", (batch,)).fetchone()[0]
        if first:   # a run from before the key was written: the first run row at or after its first email
            row = db.execute("SELECT id, created_at, detail FROM activity_log WHERE action=? AND created_at >= ? ORDER BY id "
                             "LIMIT 1", (spec["action"], first)).fetchone()
    if not row:
        abort(404)
    parse = {"reminder": reminder_runs, "lp": lp_runs, "bga": bga_runs, "ghp": gh_prog_runs, "own": own_runs}[kind]
    runs = parse(db, run_id=row["id"])
    if not runs:
        abort(404)
    return _es_window(kind, runs[0], _es_prev(db, kind, row["id"]))


def _es_run_rows(db, run):
    """Every person of one run as list rows, unsorted: [{..., state, ts, pk, _search}] and the number of skips it counted that
    its log never named. The outbox rows of the run's batch (or window), then the notifications rows of its window."""
    kind = run["kind"]
    spec = ES_RUNS[kind]
    ph = ",".join("?" * len(spec["kinds"]))
    if run["batch"]:
        ob_sql, ob_args = "o.batch=?", [run["batch"]]
    else:
        ob_sql, ob_args = "o.created_at > ? AND o.created_at <= ?", [run["prev"] or "", run["at"]]
    rows = []
    for o in db.execute("SELECT o.id, o.kind, o.status, o.created_at, o.sent_at, o.send_after, COALESCE(o.send_after > "
                        "datetime('now'), 0) AS later, COALESCE(o.error,'') AS error, o.detail, o.to_email, o.cc_email, o.user_id, "
                        + _ES_USER_COLS + " FROM email_outbox o LEFT JOIN users u ON u.id=o.user_id WHERE o.kind IN (" + ph
                        + ") AND " + ob_sql + " ORDER BY o.id", list(spec["kinds"]) + ob_args):
        state = _es_state_of(o["status"])
        rows.append(_es_row(kind, o, state, _es_status(state, o["sent_at"] or o["created_at"], o["send_after"], o["later"],
                                                       o["error"]), o["to_email"], o["sent_at"] or o["created_at"]))
    named = 0
    nf_sql = ("n.kind IN (" + ph + ") AND n.created_at > ? AND n.created_at <= ? AND ((n.status IN ('skipped','dryrun') AND "
              "COALESCE(n.detail,'') NOT IN (?,?,?))" + (_ES_DIRECT.replace("status", "n.status").replace("pending_count", "n.pending_count")
                                                          if kind == "reminder" and run["direct"] else "") + ")")
    for n in db.execute("SELECT n.id, n.kind, n.status, n.created_at, COALESCE(n.detail,'') AS detail, n.to_email, n.user_id, "
                        + _ES_USER_COLS + " FROM notifications n LEFT JOIN users u ON u.id=n.user_id WHERE " + nf_sql
                        + " ORDER BY n.id", list(spec["kinds"]) + [run["prev"] or "", run["at"]] + list(ES_RECHECK_WHY)):
        if n["status"] in ("skipped", "dryrun"):
            named += n["status"] == "skipped"
            state, st = "not_sent", _es_status("not_sent", n["created_at"], error=n["detail"], dry=n["status"] == "dryrun")
        else:
            state = n["status"]
            st = _es_status(state, n["created_at"], error=n["detail"])
        rows.append(_es_row(kind, n, state, st, n["to_email"], n["created_at"], skipped=n["status"] in ("skipped", "dryrun")))
    return rows, _es_unlisted(run, named)


def _es_row(kind, r, state, status, email, ts, skipped=False):
    """One list row for an outbox / notifications read. LP: Person / Role / Email / Status; BG admin: BG admin / Group / ...;
    reminder: Person / BU / Email / Status. The address shows only here (the super admin's panel)."""
    row = _es_user(r)
    addr = (email or "").strip()
    cells = []
    if kind in ("lp", "ghp"):
        det = (r["detail"] or "") if "detail" in r.keys() else ""
        # an outbox row's detail is "<role>; why", a skipped row's "why; <role>" (the words stay first, _es_why reads them by prefix)
        role = (det.split(";", 1)[1 if skipped else 0]).strip() if ";" in det else ""
        label = next((lab[:-1] for k, lab, _d in LP_ROLES if k == role), "")   # "BG CEOs" -> "BG CEO": the page's own labels
        row["dept"], row["jg"] = row["bu"], ""   # Person (ID · unit): the unit under the name, no BU column
        cells.append((label or "–", ""))
    elif kind == "bga":
        grp = ((r["detail"] or "").split(";", 1)[0] if ";" in (r["detail"] or "") else "") or display_bg(r["u_adminbg"] or "")
        cells.append((grp, "clip", grp))
    cc = ((r["cc_email"] or "").strip() if "cc_email" in r.keys() else "")   # Everyone's reminder's line manager copy (outbox rows only)
    cells.append((addr or "–", "clip", addr + (" (cc %s)" % cc if cc else ""), "cc " + cc) if cc else (addr or "–", "clip", addr))
    cells.append(status)
    row["cells"] = cells
    row.update(state=state, ts=ts or "", pk=row["uid"] or addr,
               _s={"full_name": row["name"], "employee_id": row["eid"], "email": addr})
    row["eid_only"] = kind not in ("lp", "ghp")
    return row


def _es_counts_chips(key, base, counts, show, q, qin, only=ES_SHOW):
    """The chips row: All / Sent / Failed / Waiting / Not sent with their counts over the WHOLE run, the chosen one on. A
    chip is a link that reloads the same panel (data-list-reload); Waiting only while something waits."""
    out = []
    for k in only:
        if k == "waiting" and not counts.get("waiting"):
            continue
        args = dict(base, **({"show": k} if k != "all" else {}), **({"q": q} if q else {}),
                    **({"qin": qin} if q and qin != "all" else {}))
        out.append({"key": k, "label": ES_SHOW_LABEL[k], "n": counts["all" if k == "all" else k],
                    "on": show == k, "href": url_for("admin_list_view", key=key, **args)})
    return out


def _es_finish(db, key, kind, args, run, rows, unlisted, head):
    """The list the panel shows: chips, search, the rows (filtered, sorted failed / waiting / not sent / sent, newest first
    inside each), the head. `head` = {kicker, title_noun, cols, colw, head, no_bu, sub_extra}."""
    q, qin = _es_search_args(args, kind)
    show = args.get("show") if args.get("show") in ES_SHOW else "all"
    counts = {k: sum(1 for r in rows if r["state"] == k) for k in ES_SHOW if k != "all"}
    counts["all"] = len(rows)
    base = {k: args[k] for k in ("run", "batch") if args.get(k)}
    shown = [r for r in rows if show == "all" or r["state"] == show]
    if q:
        shown = [r for r in shown if people_search_match(qin, q, r["_s"], head.get("extra", ()))]
    shown.sort(key=lambda r: r["ts"], reverse=True)
    shown.sort(key=lambda r: ES_RANK[r["state"]])
    noun = ES_RUNS[kind]["noun"]
    people = len({r["pk"] for r in rows})
    note = ("%s skipped before %s can't be named." % ("{:,}".format(unlisted), ES_NAMED_FROM)) if unlisted else ""
    sub = " · ".join(x for x in ((run["why"] or ""), note) if x)
    hidden = dict(base, **({"show": show} if show != "all" else {}))
    lst = {"kicker": "Email › Sent · %s" % ES_RUNS[kind]["label"],
           "title": "%s · %s %s" % (_es_fmt_when(run["at"]), "{:,}".format(people), noun[0] if people == 1 else noun[1]),
           "sub": sub, "full": url_for("admin_email_sent") + "#sent", "act": "Open", "more_text": "Narrow it with a chip or the search.",
           "cols": head["cols"], "colw": head["colw"], "no_bu": head["no_bu"], "head": head["head"], "rows": shown,
           "chips": _es_counts_chips(key, base, counts, show, q, qin), "empty": "Nobody matches that.",
           "search": dict(_es_search_spec(kind, hidden), q=q, qin=qin, action=url_for("admin_list_view", key=key))}
    return lst


def _es_cols(kind):
    """(cols, colw, head) of each panel: the columns after the person, every column's width (Open 16%: at 11% its button ran 10px
    past the 720px panel's edge, as at 10% on 2026-10-23, and at the largest text size 13% was 9px short), the first column's heading."""
    if kind in ("reminder", "own"):
        return {"cols": ["Email", "Status"], "colw": [24, 14, 20, 26, 16], "head": ["Person", "BU"], "extra": (), "no_bu": False}
    if kind in ("lp", "ghp"):
        return {"cols": ["Role", "Email", "Status"], "colw": [22, 17, 19, 26, 16], "head": ["Person"], "extra": (), "no_bu": True}
    return {"cols": ["Group", "Email", "Status"], "colw": [22, 14, 20, 28, 16], "head": ["BG admin"], "extra": (), "no_bu": True}


def _es_run_list(db, key, kind, args):
    run = _es_resolve(db, kind, args)
    rows, unlisted = _es_run_rows(db, run)
    cols = _es_cols(kind)
    return _es_finish(db, key, kind, args, run, rows, unlisted, cols)


@admin_list("email-run", "people")
def _list_email_run(db, me, vc, args):
    """Email › Sent › Everyone's reminder: the people behind one run (?run=<activity id>, or ?batch=<key> from the progress
    bar), each with Sent, Failed (and why), Waiting or Not sent (and why). ?show=failed|sent|waiting|not_sent, ?q= ?qin=.
    The super admin's only."""
    return _es_run_list(db, "email-run", "reminder", args)


@admin_list("email-lp-run", "people")
def _list_email_lp_run(db, me, vc, args):
    """Email › Sent › Leader progress: the leaders behind one run (?run=<activity id>)."""
    return _es_run_list(db, "email-lp-run", "lp", args)


@admin_list("email-ghp-run", "people")
def _list_email_ghp_run(db, me, vc, args):
    """Email › Sent › Grade H progress: the HODs and BU CEOs behind one run (?run=<activity id>, a 'gradeh_lp_run' row)."""
    return _es_run_list(db, "email-ghp-run", "ghp", args)


@admin_list("email-own-run", "people")
def _list_email_own_run(db, me, vc, args):
    """Email › Sent › Your own emails: the people behind one send (?run=<activity id>, an 'email_own_run' row), each with Sent, Failed, Waiting or
    Not sent (and why: finished by their wave, opted out, removed, skipped since)."""
    return _es_run_list(db, "email-own-run", "own", args)


@admin_list("email-bga-run", "people")
def _list_email_bga_run(db, me, vc, args):
    """Email › Sent › BG admin status: the BG admins behind one run (?run=<activity id>), one row per address."""
    return _es_run_list(db, "email-bga-run", "bga", args)


@admin_list("email-notices", "people")
def _list_email_notices(db, me, vc, args):
    """Email › Sent › Admin notices: the emails of one MYT day (?day=YYYY-MM-DD), the admin-task emails and the admin copies of
    Help and sign-in help (es_notices' rule), Sent or Failed."""
    day = (args.get("day") or "").strip()
    try:
        dt = datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        abort(404)
    holders = {}   # an address -> the admin account that holds it (notification emails first), for a help copy's Admin
    for r in db.execute("SELECT lower(trim(email)) AS a, user_id FROM admin_notify_emails ORDER BY id"):
        holders.setdefault(r["a"], r["user_id"])
    rows = []
    for n in db.execute(
            "SELECT n.id, n.kind, n.status, n.created_at, COALESCE(n.detail,'') AS detail, n.to_email, n.user_id, "
            "u.email AS u_email FROM notifications n LEFT JOIN users u ON u.id=n.user_id WHERE n.status IN ('sent','failed') "
            "AND n.created_at >= datetime(?, '-8 hours') AND n.created_at < datetime(?, '+16 hours') "
            "AND date(n.created_at, '+8 hours')=? AND (n.kind=? OR (n.kind IN (?,?) AND (n.user_id IS NULL OR "
            "lower(trim(COALESCE(n.to_email,''))) != lower(trim(COALESCE(u.email,''))))))  ORDER BY n.id",
            (day, day, day, ADMIN_TASK_KIND, HELP_KIND, SIGNIN_HELP_KIND)):   # the day's UTC span too, so the index is used
        rows.append(n)
    aid = {n["id"]: (n["user_id"] if n["kind"] == ADMIN_TASK_KIND else holders.get((n["to_email"] or "").strip().lower()))
           for n in rows}
    admins = {r["id"]: r for r in db.execute("SELECT id, full_name, employee_id, business_group, company, department, job_grade "
                                              "FROM users WHERE id IN (%s)" % ",".join("?" * len({a for a in aid.values() if a})),
                                              sorted({a for a in aid.values() if a}))} if any(aid.values()) else {}
    out = []
    for n in rows:
        a = admins.get(aid[n["id"]])
        row = _list_row(a, "overview", []) if a else {"uid": None, "name": "No admin account", "eid": "", "bu": "", "dept": "",
                                                       "jg": "", "href": "", "cells": [], "tone": ""}
        state = n["status"]
        subject, err = _es_task_parts(n["kind"], state, n["detail"])
        what = _es_notice_what(n["kind"], subject)
        addr = (n["to_email"] or "").strip()
        row["cells"] = [((subject or what), "clip", (subject or what)), (addr or "–", "clip", addr),
                        _es_status(state, n["created_at"], error=err)]
        row.update(state=state, ts=n["created_at"], pk=n["id"], eid_only=True,
                   _s={"full_name": row["name"], "employee_id": row["eid"], "email": addr, "what": subject or what})
        out.append(row)
    return _es_finish_notices(db, args, day, dt, out)


def _es_finish_notices(db, args, day, dt, rows):
    key = "email-notices"
    q, qin = _es_search_args(args, "notices")
    show = args.get("show") if args.get("show") in ("all", "sent", "failed") else "all"
    counts = {"sent": sum(1 for r in rows if r["state"] == "sent"), "failed": sum(1 for r in rows if r["state"] == "failed"),
              "all": len(rows)}
    shown = [r for r in rows if show == "all" or r["state"] == show]
    if q:
        shown = [r for r in shown if people_search_match(qin, q, r["_s"], ("what",))]
    shown.sort(key=lambda r: r["ts"], reverse=True)
    shown.sort(key=lambda r: ES_RANK[r["state"]])
    base = {"day": day}
    return {"kicker": "Email › Sent · Admin notices",
            "title": "%d %s %d · %s %s" % (dt.day, dt.strftime("%b"), dt.year, "{:,}".format(len(rows)),
                                           "email" if len(rows) == 1 else "emails"),
            "sub": "The emails OneHR sent an admin that day when something waited on them.",
            "full": url_for("admin_email_sent") + "#notices", "act": "Open", "more_text": "Narrow it with a chip or the search.",
            "cols": ["What", "Email", "Status"], "colw": [21, 23, 20, 20, 16], "head": ["Admin"], "no_bu": True, "rows": shown,
            "chips": _es_counts_chips(key, base, counts, show, q, qin, only=("all", "sent", "failed")),
            "empty": "Nobody matches that.",
            "search": dict(_es_search_spec("notices", dict(base, **({"show": show} if show != "all" else {}))), q=q, qin=qin,
                           action=url_for("admin_list_view", key=key))}



