@app.route("/admin/reminders/preview", methods=["GET", "POST"])
@super_required
def admin_reminders_preview():
    """One person's email exactly as it would go out now (by Employee ID, in this admin's scope). A POST carries the
    editor's words not saved yet, so the preview follows the typing; it writes nothing."""
    db = get_db()
    me = current_user()
    # Email › Schedule (2026-10-24): ?day= previews in that day's template; with no one picked, made-up parts
    day = _rm_date(request.args.get("day"))
    day_words = email_tpl_words("reminder", day, db) if day else None
    eid = (request.values.get("eid") or "").strip()
    if not eid and day and request.method == "GET":
        subject, body = email_tpl_sample(db, "reminder", day_words, me)
        bar = ('<p style="font:13px Arial,sans-serif;color:#3a4060;padding:10px 14px;margin:0;background:#ffffff;'
               'border-bottom:1px solid #e4e7ef"><b>Subject:</b> %s</p>' % html.escape(subject))
        head = '<body class="oh-bg" style="margin:0;padding:0;background:#eef0f5">'
        return Response(body.replace(head, head + bar, 1), mimetype="text/html")
    u = db.execute("SELECT * FROM users WHERE employee_id=? AND role!='admin'", (eid,)).fetchone() if eid else None
    if not u or not can_access(me, u["business_group"], u["company"]):
        return Response("<p style=\"font:14px Arial;color:#5f6678;padding:12px\">No one with that Employee ID that you "
                        "manage.</p>", mimetype="text/html")
    items = _reminder_drop_bu_lead(u, reminder_items(db, u))   # as the email (Chris, 2026-11-11)
    if not items:
        return Response("<p style=\"font:14px Arial;color:#5f6678;padding:12px\">Nothing is waiting on %s in the parts "
                        "open now, so they get no email.</p>" % html.escape(u["full_name"] or ""), mimetype="text/html")
    tpl, errs = reminder_template_from(request.form) if request.method == "POST" else (day_words, [])
    subject, body = reminder_mail(u, items, active_cycle(db), tpl=tpl)
    bar = ('<p style="font:13px Arial,sans-serif;color:#3a4060;padding:10px 14px;margin:0;background:#ffffff;'
           'border-bottom:1px solid #e4e7ef"><b>Subject:</b> %s</p>' % html.escape(subject))
    if errs:
        bar += ('<p style="font:13px Arial,sans-serif;color:#b0141c;padding:8px 14px;margin:0;background:#fff5f5">%s</p>'
                % html.escape(" ".join(errs)))
    head = '<body class="oh-bg" style="margin:0;padding:0;background:#eef0f5">'
    return Response(body.replace(head, head + bar, 1), mimetype="text/html")


@app.route("/admin/reminders/people.json")
@super_required
def admin_reminders_people():
    """Preview as: people in this admin's scope matching a name or Employee ID (8 at most), each with how much is
    waiting on them by the background count."""
    db = get_db()
    me = current_user()
    q = " ".join((request.args.get("q") or "").split())
    if len(q) < 2:
        return jsonify(results=[])
    where, params = bg_scope(me, "business_group")
    like = "%" + q.lower() + "%"
    rows = db.execute("SELECT id, employee_id, full_name, business_group, company FROM users WHERE role!='admin' AND "
                      "left_at IS NULL AND COALESCE(is_demo,0)=0 AND employee_id IS NOT NULL AND "
                      "(lower(full_name) LIKE ? OR lower(employee_id) LIKE ? OR id IN (SELECT user_id FROM "
                      "user_employee_ids WHERE removed_at IS NULL AND lower(employee_id) LIKE ?))" + where +
                      " ORDER BY full_name LIMIT 40", [like, like, like] + list(params)).fetchall()
    snap, _c = reminder_snapshot(db, start=False)
    waiting = (snap or {}).get("people") or {}
    out = [{"eid": r["employee_id"], "name": r["full_name"], "n": (waiting.get(str(r["id"])) or [0, 0, 0, None])[3]}
           for r in rows if can_access(me, r["business_group"], r["company"])][:8]
    return jsonify(results=out)


def _lp_who(raw):
    """(role, user id) from a 'role:id' value (a role of LP_ROLES), or None."""
    role, _s, uid = (raw or "").partition(":")
    return (role, int(uid)) if role in LP_RANK and uid.isdigit() else None


@app.route("/admin/reminders/leaders", methods=["GET", "POST"])
@super_required
def admin_reminders_leaders():
    """Cycle > Reminders > Leader progress (canvas [design canvas link removed], board 1): when the
    leader progress email goes out, who gets it, what it counts, its words, one leader's email as it would go out now,
    a test, Send now and the sends so far. The super admin changes it; other admins read it."""
