    cyc = active_cycle(db)
    status = mailer.config_status()
    role = request.values.get("role") if request.values.get("role") in LP_RANK else "buceo"
    if request.method == "POST":
        if not is_super(me):
            abort(403)
        action = request.form.get("action", "")
