# --- the needs analysis (LNA) ----------------------------------------------------------------------------------------
def _lms_scope_people(db, me, bg=None, company=None, band=None):
    """{user id: row dict} of the active, non-admin people in this admin's scope and the filters, each with its job
    family (`jf_code`, `jf_name`: the architecture's sub-family; None below JG 12 or not mapped). Batched. An L&D admin
    sees every group (bg_scope would give them none: their admin_bg is LMS_ADMIN_BG)."""
    clause, params = ("", []) if is_lnd_admin(me) else bg_scope(me, "u.business_group")
    sql = ("SELECT u.id, u.employee_id, u.business_group, u.company, u.job_grade FROM users u WHERE u.left_at IS NULL "
           "AND u.role!='admin'" + clause)
    if bg:
        sql += " AND u.business_group=?"
        params = params + [bg]
    if company:
        sql += " AND u.company=?"
        params = params + [company]
    rng = next(((lo, hi) for k, _l, lo, hi in LMS_BANDS if k == band), None)
    out = {}
    for r in db.execute(sql, params):
        gn = grade_num(r["job_grade"])
        if rng and (gn is None or not (rng[0] <= gn <= rng[1])):
            continue
        out[r["id"]] = dict(r, gn=gn)
    jf = _lms_jf_of(db, [ja_eid(r["employee_id"]) for r in out.values()
                         if r["gn"] is not None and r["gn"] >= JA_MIN_GRADE])
    for r in out.values():
        code, name = jf.get(ja_eid(r["employee_id"]), (None, None)) if r["gn"] is not None and \
            r["gn"] >= JA_MIN_GRADE else (None, None)
        r["jf_code"], r["jf_name"] = code, name
    return out


def lms_population_needs(db, people):
    """{user id: {family key: set(sources)}} for these people, from three batched reads: the goals of each one's
    latest SHARED (or closed) Career Plan -- a draft is private to its author --, the gaps of each one's latest
    submitted competency assessment, and the interest they marked (a programme counts as the families it builds)."""
    by_id = lms_catalogue(db)["by_id"]
    need = defaultdict(lambda: defaultdict(set))
    latest = {}
    goals = db.execute("SELECT i.subject_id, i.plan_year, g.skill_id FROM pm_idp i JOIN pm_idp_goals g "
                       "ON g.idp_id=i.id WHERE i.status IN ('shared','closed') AND g.skill_id IS NOT NULL").fetchall()
    for r in goals:
        if r["subject_id"] in people:
            latest[r["subject_id"]] = max(latest.get(r["subject_id"], 0), r["plan_year"] or 0)
    for r in goals:
        if r["subject_id"] in people and (r["plan_year"] or 0) == latest.get(r["subject_id"]):
            k, _lv = by_id.get(r["skill_id"], (None, None))
            if k:
                need[r["subject_id"]][k].add("plan")
    last_cyc = {r[0]: r[1] for r in db.execute("SELECT subject_id, MAX(cycle_id) FROM tc_assessments "
                                               "WHERE status IN ('submitted','reviewed') GROUP BY subject_id")}
    for r in db.execute(
            "SELECT t.subject_id, t.cycle_id, s.skill_code, s.title FROM tc_assessments t "
            "JOIN tc_assignments a ON a.cycle_id=t.cycle_id AND a.subject_id=t.subject_id AND a.is_future=0 "
            "JOIN tc_scores sc ON sc.assessment_id=t.id AND sc.assignment_id=a.id JOIN tc_skills s ON s.id=a.skill_id "
            "WHERE t.status IN ('submitted','reviewed') AND COALESCE(sc.manager_answer, sc.answer)='no'"):
        if r["subject_id"] in people and r["cycle_id"] == last_cyc.get(r["subject_id"]):
            need[r["subject_id"]][tc_comp_key(r["skill_code"], r["title"])].add("assessed")
    prog_keys = defaultdict(set)
    for r in db.execute("SELECT programme_id, comp_key FROM lms_programme_competencies WHERE confirmed=1"):
        prog_keys[r["programme_id"]].add(r["comp_key"])
    for r in db.execute("SELECT user_id, kind, programme_id, comp_key FROM lms_interest"):
        if r["user_id"] not in people:
            continue
        for k in (prog_keys.get(r["programme_id"], set()) if r["kind"] == "programme" else {r["comp_key"]}):
            if k:
                need[r["user_id"]][k].add("interest")
    return need


def _lms_stars(db, people):
    """The people whose latest talent status is Star or Super Star."""
    last = {}
    for r in db.execute("SELECT subject_id, year, category FROM talent_status_history ORDER BY year, id"):
        if r["subject_id"] in people:
            last[r["subject_id"]] = r["category"]
    return {k for k, v in last.items() if v in PM_SUCCESSION_ELIGIBLE}


def lms_lna(db, me, bg=None, company=None, band=None, view=None, jf=None):
    """The live learning-needs analysis for this admin's scope: who needs which competency family, by business group,
    by business unit or by job family (`view`; by group by default, by unit once a group is chosen or the admin is a
    group's, who has no group view), how many of them are Stars, and what the published calendar covers. `jf` narrows
    it to one job family (LMS_LNA_NONE: "No job family yet"), after the admin's own scope, so it never widens it.
    Counts only."""
    fam = lms_catalogue(db)["fam"]
    own_bg = lms_scope_bg(me)
    bg = own_bg or bg or None
    default_view = "bu" if bg else "bg"
    if view not in dict(LMS_LNA_VIEWS) or (view == "bg" and own_bg):
        view = default_view
    people = _lms_scope_people(db, me, bg, company, band)
    jf_opts = sorted({(p["jf_code"], p["jf_name"]) for p in people.values() if p["jf_code"]},
                     key=lambda x: (x[1] or "").lower())
    if jf:
        people = {k: p for k, p in people.items() if (p["jf_code"] or LMS_LNA_NONE) == jf}
    need = lms_population_needs(db, people)
    stars = _lms_stars(db, people)
    none_col = {"bg": "(no group)", "bu": "(no unit)", "jf": LMS_NO_JF}[view]

    def col_of(r):
        return (r["business_group"] if view == "bg" else r["company"] if view == "bu" else r["jf_name"]) or none_col
    unit_bg = {p["company"]: p["business_group"] for p in people.values() if p["company"]}
    labels = {}
    agg, col_n = {}, defaultdict(int)
    for uid, keys in need.items():
        if not keys:
            continue
        c = col_of(people[uid])
        col_n[c] += 1
        if c not in labels:
            labels[c] = (c if c == none_col else display_bg(c) if view == "bg" else
                         display_company(unit_bg.get(c), c) if view == "bu" else c)
        for k, srcs in keys.items():
            a = agg.setdefault(k, {"key": k, "title": (fam.get(k) or {}).get("title") or k, "people": set(),
                                   "cells": defaultdict(int), "stars": 0, "plan": 0, "assessed": 0, "interest": 0})
            a["people"].add(uid)
            a["cells"][c] += 1
            a["stars"] += uid in stars
            for s_ in srcs:
                a[s_] += 1
    # every column, the most need first and "none" last (the download); on screen the first LMS_LNA_COLS, the rest as
    # one "Other" column -- never an "Other" of one
    cols = sorted((c for c in col_n if c != none_col), key=lambda c: (-col_n[c], labels[c].lower()))
    shown, hidden = (list(cols), []) if len(cols) <= LMS_LNA_COLS + 1 else (cols[:LMS_LNA_COLS], cols[LMS_LNA_COLS:])
    if none_col in col_n:
        cols.append(none_col)
    shown_cols = [{"key": c, "label": labels[c]} for c in shown]
    if hidden:
        shown_cols.append({"key": "__other__", "label": "Other %d" % len(hidden)})
    if none_col in col_n:
        shown_cols.append({"key": none_col, "label": labels[none_col]})
    cover = defaultdict(lambda: {"programmes": 0, "seats": 0})
    for p in lms_programmes(db, status="published"):
        for c in p["comps"]:
            if c["confirmed"]:
                cover[c["comp_key"]]["programmes"] += 1
                cover[c["comp_key"]]["seats"] += sum(s_["seats"] or 0 for s_ in p["upcoming"])
    rows = sorted(agg.values(), key=lambda a: (-len(a["people"]), a["title"].lower()))
    for a in rows:
        a["n"] = len(a["people"])
        a["cover"] = cover.get(a["key"], {"programmes": 0, "seats": 0})
        if hidden:
            a["cells"]["__other__"] = sum(a["cells"].get(c, 0) for c in hidden)
        del a["people"]
    peak = max((a["cells"].get(c["key"], 0) for a in rows[:LMS_LNA_ROWS] for c in shown_cols), default=0)
    with_need = [uid for uid in need if need[uid]]
    # who the tiles count, for their lists (2026-10-23): with a need, with a Career Plan goal among them, Stars
    ids = {"need": with_need, "plan": [uid for uid in with_need if any("plan" in s_ for s_ in need[uid].values())],
           "stars": [uid for uid in with_need if uid in stars]}
    tiles = {"people": len(people), "with_need": len(with_need),
             "plan": sum(1 for uid in with_need if any("plan" in s_ for s_ in need[uid].values())),
             "stars": sum(1 for uid in with_need if uid in stars),
             "interest": sum(1 for uid in with_need if any("interest" in s_ for s_ in need[uid].values())),
             "families": len(rows), "uncovered": sum(1 for a in rows if not a["cover"]["programmes"]),
             "jfs": len({people[uid]["jf_code"] for uid in with_need if people[uid]["jf_code"]})}
    jf_label = (LMS_NO_JF if jf == LMS_LNA_NONE else dict(jf_opts).get(jf, jf)) if jf else ""
    scope = " · ".join(x for x in (display_bg(bg) if bg else "All business groups",
                                   display_company(bg, company) if company else "",
                                   next((lab for k, lab, _a, _b in LMS_BANDS if k == band), ""), jf_label) if x)
    key = "lna|%s|%s|%s" % (bg or "", company or "", band or "")
    if view != default_view:
        key += "|v=%s" % view
    if jf:
        key += "|jf=%s" % jf
    return {"rows": rows, "cols": cols, "shown_cols": shown_cols, "labels": labels, "peak": peak, "tiles": tiles,
            "ids": ids, "need": need,
            "view": view, "view_label": dict(LMS_LNA_VIEWS)[view], "by_unit": view == "bu", "scope": scope,
            "bg": bg, "company": company, "band": band, "jf": jf, "jf_opts": jf_opts, "own_bg": own_bg,
            "default_view": default_view, "scope_key": key}


def _lms_cell_tone(n, peak):
    """A heat-map cell's shade, 0 (none) to 4 (the most), relative to the busiest cell shown."""
    if not n or not peak:
        return 0
    r = n / float(peak)
    return 4 if r > 0.75 else 3 if r > 0.5 else 2 if r > 0.25 else 1


app.jinja_env.globals["lms_cell_tone"] = _lms_cell_tone


def _lms_needs_facts(lna):
    """The plain-text facts the AI read is written from (and checked against): counts and names only."""
    t = lna["tiles"]
    lines = ["Scope: %s, by %s. People in scope: %d. People with a learning need: %d, of whom %d are Stars or Super "
             "Stars. Competency families needed: %d; with no programme on the calendar: %d."
             % (lna["scope"], lna["view_label"].lower(), t["people"], t["with_need"], t["stars"], t["families"],
                t["uncovered"])]
    for a in lna["rows"][:8]:
        cells = ", ".join("%s %d" % (lna["labels"].get(c, c), a["cells"][c])
                          for c in sorted((c for c in a["cells"] if c != "__other__"), key=lambda c: -a["cells"][c])[:4])
        cov = ("%d programme(s), %d seats coming up" % (a["cover"]["programmes"], a["cover"]["seats"])
               if a["cover"]["programmes"] else "no programme on the calendar")
        lines.append("- %s: %d people need it (%d Stars or Super Stars); most in %s; calendar: %s."
                     % (a["title"], a["n"], a["stars"], cells or "none", cov))
    return "\n".join(lines)


def _lms_fingerprint(facts):
    return hashlib.sha256((facts + "|" + ai_draft.summary_signature()).encode("utf-8")).hexdigest()


def lms_needs_read_get(db, lna):
    """The cached AI read for this scope: {findings, at, fresh} or None."""
    r = db.execute("SELECT * FROM lms_reads WHERE scope_key=?", (lna["scope_key"],)).fetchone()
    if not r:
        return None
    try:
        found = json.loads(r["body"])
    except (TypeError, ValueError):
        return None
    return {"findings": found, "at": r["created_at"],
            "fresh": r["fingerprint"] == _lms_fingerprint(_lms_needs_facts(lna))}


def lms_needs_read_write(db, me, lna):
    """Write the AI read of this scope's needs and cache it. Every number a finding states must be one the facts hold,
    or the finding is dropped. (ok, message)."""
    if not ai_draft.is_configured():
        return False, "AI isn't set up on this server."
    if not lna["rows"]:
        return False, "Nobody in this scope has a learning need yet, so there's nothing to read."
    facts = _lms_needs_facts(lna)
    try:
        found = ai_draft.lms_needs_read(facts)
    except ai_draft.AIDraftError as e:
        app.logger.warning("lms needs read failed: %s", e)
        return False, "The AI couldn't write the read just now. Try again in a minute."
    allowed = set(re.findall(r"\d+", facts))
    kept = [f for f in found if set(re.findall(r"\d+", f)) <= allowed]
    if not kept:
        return False, "The read didn't hold to the figures, so it wasn't kept. Try again."
    db.execute("INSERT INTO lms_reads(scope_key, fingerprint, body, created_by, created_at) VALUES (?,?,?,?,"
               "datetime('now')) ON CONFLICT(scope_key) DO UPDATE SET fingerprint=excluded.fingerprint, "
               "body=excluded.body, created_by=excluded.created_by, created_at=excluded.created_at",
               (lna["scope_key"], _lms_fingerprint(facts), json.dumps(kept), me["id"]))
    log_activity(db, me["id"], "lms_needs_read", "Learning needs read: %s (%d finding%s)"
                 % (lna["scope"], len(kept), "" if len(kept) == 1 else "s"))
    db.commit()
    return True, "The read is written."


def _lms_lna_args(me):
    """The needs page's filters: {bg, company, band, view, jf}. A group's admin has no group to pick."""
    bg = (request.values.get("bg") or "").strip() or None
    if lms_scope_bg(me):
        bg = None
    elif bg and bg not in org_bgs(get_db()):
        bg = None
    company = (request.values.get("company") or "").strip() or None
    band = request.values.get("band") if request.values.get("band") in [k for k, *_r in LMS_BANDS] else None
    view = request.values.get("view") if request.values.get("view") in dict(LMS_LNA_VIEWS) else None
    jf = (request.values.get("jf") or "").strip()[:40] or None
    return {"bg": bg, "company": company, "band": band, "view": view, "jf": jf}


def _lms_lna_url_args(lna, **over):
    """The needs page's address for this view, the defaults left out."""
    a = {"bg": lna["bg"] if not lna["own_bg"] else None, "company": lna["company"], "band": lna["band"],
         "view": lna["view"] if lna["view"] != lna["default_view"] else None, "jf": lna["jf"]}
    a.update(over)
    return {k: v for k, v in a.items() if v}


app.jinja_env.globals["lms_lna_url_args"] = _lms_lna_url_args


def _lms_needs_sheet(lna):
    """(header, rows) of the needs file: the page's own download and Reports' Learning needs (2026-11-04) write the same ones."""
    head = ["Competency", "People who need it", "Stars or Super Stars", "From Career Plans",
            "From assessments", "From interest", "Programmes on the calendar", "Seats coming up"] + \
        [lna["labels"][c] for c in lna["cols"]]
    body = [[a["title"], a["n"], a["stars"], a["plan"], a["assessed"], a["interest"], a["cover"]["programmes"],
             a["cover"]["seats"]] + [a["cells"].get(c, 0) for c in lna["cols"]] for a in lna["rows"]]
    return head, body


@app.route("/admin/learning/needs")
@admin_required
def admin_learning_needs():
    """Learning › Needs: the live LNA, its AI read and its Excel download (counts only)."""
    db = get_db()
    me = current_user()
    lna = lms_lna(db, me, **_lms_lna_args(me))
    if request.args.get("format") == "xlsx":
        head, body = _lms_needs_sheet(lna)
        return _xlsx_response("learning-needs.xlsx", [("Learning needs", head, body)])
    units = sorted({r["company"] for r in db.execute("SELECT company FROM org_units WHERE active=1 AND "
                                                      "business_group=?", (lna["bg"],))}) if lna["bg"] else []
    views = [(k, lab) for k, lab in LMS_LNA_VIEWS if not (k == "bg" and lna["own_bg"])]
    return render_template("admin_learning_needs.html", lna=lna, read=lms_needs_read_get(db, lna), bands=LMS_BANDS,
                           bgs=org_bgs(db), units=units, ai_ok=ai_draft.is_configured(), rows_shown=LMS_LNA_ROWS,
                           is_su=lms_can_admin(me), views=views, no_jf=LMS_NO_JF, jf_none=LMS_LNA_NONE,
                           cols_cap=LMS_LNA_COLS)


@app.route("/admin/learning/needs/read", methods=["POST"])
@admin_required
def admin_learning_needs_read():
    """Write the AI read of the needs for the scope the page shows (the super admin or an L&D admin)."""
    db = get_db()
    me = current_user()
    if not lms_can_admin(me):
        abort(403)
    lna = lms_lna(db, me, **_lms_lna_args(me))
    ok, msg = lms_needs_read_write(db, me, lna)
    flash(msg, "ok" if ok else "error")
    return redirect(url_for("admin_learning_needs", **_lms_lna_url_args(lna)))


# --- the programme catalogue (the super admin's until the L&D admin role, phase 2) ----------------------------------
def _lms_float(v, lo, hi):
    try:
        f = float(str(v).replace(",", "").strip())
    except (TypeError, ValueError):
        return None
    return f if lo <= f <= hi else None


LMS_ORGANISER_GROUP = "Group People COE"


def lms_organisers(db):
    """Who can organise a programme: the Group's L&D team, or a business group."""
    return [LMS_ORGANISER_GROUP] + org_bgs(db)


def lms_category_lists(db):
    """The CHART categories and sub-categories already in use (a new one is added through "A new …")."""
    rows = db.execute("SELECT DISTINCT category, sub_category FROM lms_programmes").fetchall()
    return {"category": sorted({r["category"] for r in rows if r["category"]}, key=str.lower),
            "sub_category": sorted({r["sub_category"] for r in rows if r["sub_category"]}, key=str.lower)}


def lms_programme_save(db, me, pid, form):
    """The one writer of a programme's details (new when pid is None). (ok, message, id)."""
    title = " ".join((form.get("title") or "").split())[:160]
    if not title:
        return False, "A programme needs a title.", pid
    kind = form.get("kind") if form.get("kind") in LMS_KIND_LABEL else "inhouse"
    eff = "1,3"   # every programme asks at 1 and 3 months; the 6-month tick is gone (Chris, 2026-10-23)
    aud = {"grade_min": _lms_float(form.get("grade_min"), 1, 30), "grade_max": _lms_float(form.get("grade_max"), 1, 30),
           "bgs": [b for b in form.getlist("bgs") if b in org_bgs(db)] if hasattr(form, "getlist") else [],
           # the units it's for (2026-10-23: the form had no unit picker, so saving wiped any set elsewhere)
           "companies": [c for c in form.getlist("companies") if c in {x for xs in org_map(db).values() for x in xs}]
           if hasattr(form, "getlist") else []}
    aud = {k: (int(v) if isinstance(v, float) else v) for k, v in aud.items()}
    if aud["grade_min"] is not None and aud["grade_max"] is not None and aud["grade_min"] > aud["grade_max"]:
        return False, "The lowest grade is above the highest.", pid
    # CHART category and sub-category, and the organiser, are picked from lists (admin fields are picked, not typed)
    held = dict(db.execute("SELECT category, sub_category, organiser FROM lms_programmes WHERE id=?", (pid,)).fetchone()
                or {}) if pid else {}
    cats = lms_category_lists(db)
    cat, _new, err = _admin_list_choice(form, "category", cats["category"], held.get("category"), "category")
    if err:
        return False, err, pid
    sub, _new, err = _admin_list_choice(form, "sub_category", cats["sub_category"], held.get("sub_category"),
                                        "sub-category")
    if err:
        return False, err, pid
    org = (form.get("organiser") or "").strip()
    if org and org not in lms_organisers(db) and org != (held.get("organiser") or ""):
        return False, "Pick the organiser from the list.", pid
    vals = {"title": title, "kind": kind,
            "description": (form.get("description") or "").strip()[:1500] or None,
            "category": cat, "sub_category": sub, "organiser": org or None,
            "vendor": " ".join((form.get("vendor") or "").split())[:120] or None,
            "trainer": " ".join((form.get("trainer") or "").split())[:120] or None,
            "trainer_email": ((form.get("trainer_email") or "").strip()[:160] or None)
            if re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", (form.get("trainer_email") or "").strip()) else None,
            "days": _lms_float(form.get("days"), 0, 60), "hours": _lms_float(form.get("hours"), 0, 500),
            "cost_per_pax": _lms_float(form.get("cost_per_pax"), 0, 1000000),
            "hrdc_claimable": 1 if form.get("hrdc_claimable") else 0, "effectiveness": eff,
            "audience_json": json.dumps(aud) if any(aud.values()) else None}
    if "cert_mode" in form:   # who gives its certificate (2026-10-23, section 20); blank = by its kind; absent = as is
        vals["cert_mode"] = form.get("cert_mode") if form.get("cert_mode") in LMS_CERT_MODE_LABEL else None
    if pid is None:
        cur = db.execute("INSERT INTO lms_programmes(%s, created_by) VALUES (%s, ?)"
                         % (", ".join(vals), ",".join("?" * len(vals))), list(vals.values()) + [me["id"]])
        pid = cur.lastrowid
        log_activity(db, me["id"], "lms_programme_add", "Programme added: %s" % title)
    else:
        if not db.execute("SELECT 1 FROM lms_programmes WHERE id=?", (pid,)).fetchone():
            return False, "That programme isn't there.", pid
        db.execute("UPDATE lms_programmes SET %s, updated_at=datetime('now') WHERE id=?"
                   % ", ".join("%s=?" % k for k in vals), list(vals.values()) + [pid])
        log_activity(db, me["id"], "lms_programme_edit", "Programme changed: %s" % title)
    db.commit()
    return True, "Saved.", pid


def lms_programme_status(db, me, pid, status):
    p = db.execute("SELECT * FROM lms_programmes WHERE id=?", (pid,)).fetchone()
    if not p or status not in LMS_STATUS_LABEL:
        return False, "That programme isn't there."
    if p["status"] == status:
        return True, "No change."
    # every programme builds at least one competency at a level from the library before people can see it (Chris,
    # 2026-10-22: "each training is supposed to bind to one or more competency and with defined level"), briefings too
    if status == "published" and not _lms_n_confirmed(db, pid):
        return False, ("Confirm at least one competency, with its level, before publishing: it's how the programme "
                       "reaches the people whose Career Plan or needs it builds.")
    if status in ("draft", "archived"):   # nobody holds a place on a programme that's gone (2026-10-23)
        live = db.execute("SELECT COUNT(*) FROM lms_sessions WHERE programme_id=? AND status='planned' AND ends_on>=?",
                          (pid, _today_myt().isoformat())).fetchone()[0]
        if live:
            return False, "It has %d run%s still to come. Cancel or move %s first." % (
                live, "" if live == 1 else "s", "it" if live == 1 else "them")
    db.execute("UPDATE lms_programmes SET status=?, updated_at=datetime('now') WHERE id=?", (status, pid))
    log_activity(db, me["id"], "lms_programme_status", "%s: %s -> %s" % (p["title"], p["status"], status))
    db.commit()
    return True, {"published": "Published: people it's for see it now.", "draft": "Withdrawn to a draft.",
                  "archived": "Archived."}[status]


def _lms_n_confirmed(db, pid):
    """How many competencies L&D has confirmed for a programme."""
    return db.execute("SELECT COUNT(*) FROM lms_programme_competencies WHERE programme_id=? AND confirmed=1",
                      (pid,)).fetchone()[0]


def lms_competency_set(db, me, pid, key, level, action):
    """Add (confirmed: an admin chose it), confirm an AI-proposed one, or remove a programme's competency. Only a
    catalogue family, at a level that family has. A published programme keeps at least one confirmed competency."""
    p = db.execute("SELECT title, status FROM lms_programmes WHERE id=?", (pid,)).fetchone()
    if not p:
        return False, "That programme isn't there."
    if action == "remove":
        row = db.execute("SELECT confirmed FROM lms_programme_competencies WHERE programme_id=? AND comp_key=?",
                         (pid, key)).fetchone()
        if row and row["confirmed"] and p["status"] == "published" and _lms_n_confirmed(db, pid) <= 1:
            return False, ("It's the programme's only confirmed competency: add or confirm another first, or withdraw "
                           "the programme to a draft.")
        db.execute("DELETE FROM lms_programme_competencies WHERE programme_id=? AND comp_key=?", (pid, key))
        msg = "Taken off."
    else:
        f = lms_catalogue(db)["fam"].get(key)
        if not f:
            return False, "That competency isn't in the catalogue."
        try:
            level = int(level)
        except (TypeError, ValueError):
            level = None
        if level not in f["levels"]:
            return False, "%s has no level %s. It has %s." % (f["title"], level or "?",
                                                              ", ".join("L%d" % x for x in sorted(f["levels"])))
        if action == "confirm":
            if not db.execute("UPDATE lms_programme_competencies SET confirmed=1, level=? WHERE programme_id=? AND "
                              "comp_key=?", (level, pid, key)).rowcount:
                return False, "That competency isn't proposed for this programme."
            msg = "Confirmed."
        else:
            db.execute("INSERT INTO lms_programme_competencies(programme_id, comp_key, level, confirmed) VALUES "
                       "(?,?,?,1) ON CONFLICT(programme_id, comp_key) DO UPDATE SET level=excluded.level, confirmed=1",
                       (pid, key, level))
            msg = "Added."
    log_activity(db, me["id"], "lms_competency", "%s: %s %s" % (p["title"], action, key))
    db.commit()
    return True, msg


def lms_session_cancel(db, me, sid, reason):
    """L&D cancels a run (2026-10-23, the LMS gap check): refused once it has started or closed; the reason is required
    and everyone on it reads it. Every open place and request on it closes ('cancelled', session), invites are
    cancelled, the waiting list goes with it; an HRDC filing already made stays on the board, marked. (ok, message)."""
    s_ = _lms_session_row(db, sid)
    if not s_ or s_["status"] != "planned":
        return False, "That session isn't planned."
    if s_["closed_at"] or (s_["starts_on"] or "") <= _today_myt().isoformat():
        return False, "It has started, so it can't be cancelled now. Close it after its last day."
    reason = " ".join((reason or "").split())[:300]
    if not reason:
        return False, "Give the reason: everyone on it reads it."
    db.execute("UPDATE lms_sessions SET status='cancelled' WHERE id=?", (sid,))
    n = 0
    for r_ in db.execute("SELECT id, user_id, status, level FROM lms_registrations WHERE session_id=? AND status IN "
                         "('pending','waitlisted','approved','returned')", (sid,)).fetchall():
        if r_["status"] == "approved":
            _lms_invite_cancel(db, r_["id"])
        db.execute("UPDATE lms_registrations SET status='cancelled', closed_kind='session', remark=?, "
                   "updated_at=datetime('now') WHERE id=?", (reason, r_["id"]))
        _lms_log(db, r_["id"], r_["level"], "", me["id"], "cancelled", "the session was cancelled: " + reason)
        _lms_mail(db, "changed", _lms_user(db, r_["user_id"]), "sess:%d:cancel" % sid, "Cancelled: %s" % s_["title"],
                  ["L&D has cancelled %s, %s." % (s_["title"], _lms_session_line(dict(s_))),
                   "L&D's reason: “%s”" % reason, "Look for another run from AI+ Learning's calendar."],
                  ("Open AI+ Learning", app_base_url() + "/learning"), prog=s_["title"])
        n += 1
    log_activity(db, me["id"], "lms_session", "%s: session %s cancelled, %d on it: %s" % (s_["title"], sid, n, reason))
    db.commit()
    return True, ("Cancelled. The %d on it are told." % n) if n else "Cancelled."


def lms_session_save(db, me, pid, form, sid=None, cancel=False):
    """Add a session, or cancel one. Dates are ISO; the cut-off defaults to the session clock's registration close
    (Learning › Settings, LMS_REG_CUTOFF_DAYS before day one unless L&D changed it)."""
    p = db.execute("SELECT title FROM lms_programmes WHERE id=?", (pid,)).fetchone()
    if not p:
        return False, "That programme isn't there."
    if cancel:
        s_c = _lms_session_row(db, sid)
        if not s_c or s_c["programme_id"] != pid:
            return False, "That session isn't there."
        return lms_session_cancel(db, me, sid, (form or {}).get("reason"))
    try:
        a = date.fromisoformat((form.get("starts_on") or "").strip())
        b = date.fromisoformat((form.get("ends_on") or "").strip() or a.isoformat())
    except ValueError:
        return False, "Give the first and last day as dates."
    if b < a:
        return False, "The last day is before the first."
    if a < _today_myt():
        return False, "Day one can't be in the past."
    try:
        cut = date.fromisoformat((form.get("reg_cutoff") or "").strip()) if form.get("reg_cutoff") else \
            a - timedelta(days=lms_clock_days(db)["reg_close"])
    except ValueError:
        return False, "The registration cut-off isn't a date."
    if form.get("reg_cutoff") and cut >= a:
        return False, "Registration must close before day one."
    tm = [(form.get(k) or "").strip()[:5] for k in ("start_time", "end_time")]
    tm = [x if re.match(r"^\d{2}:\d{2}$", x) else None for x in tm]
    seats = _lms_float(form.get("seats"), 1, 5000)
    tr, tr_email = _lms_trainer_fields(form)
    db.execute("INSERT INTO lms_sessions(programme_id, run_label, starts_on, ends_on, start_time, end_time, venue, "
               "seats, reg_cutoff, created_by, needs_out, trainer_s, trainer_email_s) VALUES (?,?,?,?,?,?,?,?,?,?,1,?,?)",
               (pid, " ".join((form.get("run_label") or "").split())[:40] or None, a.isoformat(), b.isoformat(),
                tm[0], tm[1], " ".join((form.get("venue") or "").split())[:120] or None,
                int(seats) if seats else None, cut.isoformat(), me["id"], tr, tr_email))
    log_activity(db, me["id"], "lms_session", "%s: session %s added" % (p["title"], a.isoformat()))
    db.commit()
    return True, "Session added."


_LMS_CAND_STOP = {"and", "the", "for", "with", "of", "in", "to", "a", "an", "on", "at", "by", "or", "as", "is", "be",
                  "are", "its", "it", "this", "that", "from", "into", "their", "they", "you", "your", "our", "who",
                  "how", "what", "all", "can", "will", "one", "use", "new", "day", "days", "per", "via", "not", "own",
                  "has", "have", "able", "skill", "skills", "management", "manage", "level", "levels", "work",
                  "include", "including", "using", "such", "other", "more", "also", "each", "within", "across"}
_LMS_CAND_SUFFIXES = ("ations", "ation", "ments", "ment", "ings", "ing", "ates", "ate", "ers", "er", "ies", "es", "ed",
                      "s")
_LMS_CAND_INDEX = {}            # per process: {"sig": the library's signature, "docs": [...], "idf": {...}}


def _lms_words(text):
    """Words of 3+ letters, stop words out, each lightly stemmed (a suffix off, a final e off, at most 6 letters), so
    "negotiation" / "negotiating" and "HSE" / "BIM" / "ESG" all count (2026-10-22: the old 4-letter rule lost them)."""
    out = []
    for w in re.findall(r"[a-z]{3,}", (text or "").lower()):
        if w in _LMS_CAND_STOP:
            continue
        for suf in _LMS_CAND_SUFFIXES:
            if w.endswith(suf) and len(w) - len(suf) >= 3:
                w = w[:-len(suf)]
                break
        if w.endswith("e") and len(w) >= 5:
            w = w[:-1]
        w = w[:6]
        if w not in _LMS_CAND_STOP:
            out.append(w)
    return out


def _lms_cand_index(db):
    """The library as documents for the shortlist, built once per process and again whenever the library changes:
    each active family's title (weight 3), category (1.5) and level wording (1), with each word's IDF."""
    sig = tuple(db.execute("SELECT COUNT(*), MAX(id), SUM(COALESCE(active, 1)) FROM tc_skills").fetchone())
    if _LMS_CAND_INDEX.get("sig") == sig:
        return _LMS_CAND_INDEX
    docs, df = [], defaultdict(int)
    for f in lms_catalogue(db)["fam"].values():
        if not f["levels"]:
            continue
        w = {}
        for t in _lms_words(" ".join(d["desc"] for d in f["levels"].values())):
            w[t] = 1.0
        for t in _lms_words(f["category"]):
            w[t] = max(w.get(t, 0), 1.5)
        for t in _lms_words(f["title"]):
            w[t] = 3.0
        if not w:
            continue
        docs.append((f, w))
        for t in w:
            df[t] += 1
    n = float(len(docs) or 1)
    idf = {t: math.log((n + 1) / (c + 0.5)) for t, c in df.items()}
    _LMS_CAND_INDEX.clear()
    _LMS_CAND_INDEX.update({"sig": sig, "docs": docs, "idf": idf})
    return _LMS_CAND_INDEX


def lms_candidates(db, text, n=40, title="", category=""):
    """The competency families a programme most plausibly builds: the closed list the AI may choose from. The
    programme's title counts three times, its description, outline or brochure and its category once, against each
    family's title, category and level wording, weighted by how rare each word is in the library (2026-10-22). Each
    candidate carries its levels and the library's own wording for each."""
    q = {}
    for t in _lms_words(" ".join([text or "", category or ""])):
        q[t] = max(q.get(t, 0), 1.0)
    for t in _lms_words(title):
        q[t] = 3.0
    if not q:
        return []
    ix = _lms_cand_index(db)
    scored = []
    for f, w in ix["docs"]:
        sc = sum(qw * w[t] * ix["idf"].get(t, 0) for t, qw in q.items() if t in w)
        if sc > 0:
            scored.append((sc / math.sqrt(len(w) + 4), f))
    scored.sort(key=lambda x: (-x[0], x[1]["title"]))
    return [{"key": f["key"], "title": f["title"], "category": f["category"], "levels": sorted(f["levels"]),
             "desc": {lv: d["desc"] for lv, d in f["levels"].items()}} for _s, f in scored[:n]]


def _lms_comp_propose(db, pid, got, cands, text, replace=False):
    """Keep the AI's proposed competencies for a programme, each checked: a candidate's key, at a level its family has,
    at most 4, never confirmed. Its evidence is kept only when it is the programme's own words. `replace` first drops
    the rows still waiting for L&D (a confirmed one is never touched). How many were kept."""
    allowed = {c["key"]: set(c["levels"]) for c in cands}
    flat = " ".join((text or "").lower().split())
    if replace:
        db.execute("DELETE FROM lms_programme_competencies WHERE programme_id=? AND confirmed=0", (pid,))
    n = 0
    for c in (got or [])[:12]:
        if n >= 4:
            break
        if not isinstance(c, dict):
            continue
        k = str(c.get("key") or "").strip()
        # a level as the listing names it ("L3") or a number: staging's Luna answered "L3" every time (2026-10-22)
        m = re.match(r"^\s*[Ll]?\s*(\d)\s*$", "" if c.get("level") is None else str(c.get("level")))
        if not m:
            continue
        lv = int(m.group(1))
        if k not in allowed or lv not in allowed[k]:
            continue
        strength = c.get("strength") if c.get("strength") in ("strong", "medium") else "medium"
        ev = " ".join(str(c.get("evidence") or "").split()).strip(" \"'“”")[:200]
        if ev and ev.lower() not in flat:
            ev = ""
        n += db.execute("INSERT OR IGNORE INTO lms_programme_competencies(programme_id, comp_key, level, strength, "
                        "evidence, confirmed) VALUES (?,?,?,?,?,0)", (pid, k, lv, strength, ev or None)).rowcount
    return n


def lms_suggest_competencies(db, me, pid):
    """The L&D AI agent tags a programme (Chris, 2026-10-22: "when admin registered a new program, our L&D AI agent
    will process and recommend the tagging competency and respective proficiency level"; board 6B): it reads the
    programme's title, details and brochure against the library's shortlist, with each level's own wording, and
    proposes up to 4 competencies at the level each builds people to. Proposals only: L&D confirms each, at the level
    they pick. Replaces only the proposals still waiting; never a confirmed one. (ok, message, how many)."""
    p = db.execute("SELECT * FROM lms_programmes WHERE id=?", (pid,)).fetchone()
    if not p:
        return False, "That programme isn't there.", 0
    if not ai_draft.is_configured():
        return False, "AI isn't set up on this server.", 0
    body = "\n".join(x for x in (p["summary"], p["description"], p["outcomes"], p["outline"], p["audience_text"],
                                 p["prereq"], lms_brochure_text(p)[:6000]) if x)
    text = "%s\n%s" % (p["title"], body)
    cands = lms_candidates(db, body, title=p["title"],
                           category=" ".join(x for x in (p["category"], p["sub_category"]) if x))
    if not cands:
        return False, "Nothing in the competency library shares its words. Add one yourself from the library.", 0
    try:
        got = ai_draft.lms_suggest_competencies(text, cands, kind=LMS_KIND_LABEL.get(p["kind"], p["kind"]))
    except ai_draft.AIDraftError as e:
        app.logger.warning("lms competency suggestion failed: %s", e)
        return False, "The AI couldn't suggest competencies just now. Try Suggest again in a minute.", 0
    n = _lms_comp_propose(db, pid, got, cands, text, replace=True)
    log_activity(db, me["id"], "lms_programme_suggest", "Suggested competencies with AI: %s (%d proposed)"
                 % (p["title"], n))
    db.commit()
    if not n:
        return True, "The AI found nothing in the library this programme clearly builds. Add one yourself.", 0
    return True, ("The AI proposed %d competenc%s. Pick the level each builds, then confirm."
                  % (n, "y" if n == 1 else "ies")), n


def lms_read_proposal(db, me, filename, data):
    """Read a vendor proposal with AI into a DRAFT programme, its competencies proposed and not confirmed. Every field
    checked here: a competency only from the candidates, at a level its family has. (ok, message, programme id)."""
    ext = _attach_ext(filename)
    if ext not in LMS_PROPOSAL_EXTS:
        return False, "Upload a PDF, a Word file (.docx) or a text file.", None
    if not data or len(data) > LMS_PROPOSAL_MAX_BYTES:
        return False, "The file is empty or over 5 MB.", None
    if not ai_draft.is_configured():
        return False, "AI isn't set up on this server.", None
    st, text = _attach_extract(ext, data)
    if st != "ok" or not (text or "").strip():
        return False, "No text could be read from that file (a scanned PDF has none).", None
    # screened as a KPI file is (the 2026-10-24 handoff, 12.2): words written to the AI never reach the model
    flag = ai_draft.screen_file_text(filename) or ai_draft.screen_file_text(text)
    if flag:
        log_activity(db, me["id"], "lms_programme_read_flagged", "Proposal not read: %s has words written to the AI "
                     "(\"%s\")" % (filename[:80], flag))
        db.commit()
        return False, ("That file wasn't read: it has words written to the AI (\"%s\"). Open it to check, or add the "
                       "programme by hand." % flag), None
    cands = lms_candidates(db, text)
    try:
        got = ai_draft.lms_read_proposal(text, cands)
    except ai_draft.AIDraftError as e:
        app.logger.warning("lms proposal read failed: %s", e)
        return False, "The AI couldn't read it just now. Try again in a minute.", None
    title = " ".join(str(got.get("title") or "").split())[:160] or os.path.splitext(filename)[0][:160]
    form = {"title": title, "kind": got.get("kind"), "description": str(got.get("description") or "")[:1500],
            "days": got.get("days"), "hours": got.get("hours"), "cost_per_pax": got.get("cost_per_pax"),
            "hrdc_claimable": "1" if got.get("hrdc_claimable") is True else ""}
    ok, msg, pid = lms_programme_save(db, me, None, form)
    if not ok:
        return False, msg, None
    db.execute("UPDATE lms_programmes SET source='proposal', source_file=? WHERE id=?", (filename[:160], pid))
    n = _lms_comp_propose(db, pid, got.get("competencies"), cands, text)
    log_activity(db, me["id"], "lms_programme_read", "Proposal read with AI: %s (%s, %d competencies proposed)"
                 % (title, filename[:80], n))
    db.commit()
    return True, "Read. Check what the AI took from it, confirm the competencies, then publish.", pid


@app.route("/admin/learning/programmes", methods=["GET", "POST"])
@admin_required
def admin_learning_programmes():
    """Learning › Programmes: the catalogue, each programme's details, competencies and sessions in its panel. Writes
    are the super admin's (ADMIN_ACCESS_MAP)."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        act = request.form.get("action") or ""
        pid = _lms_opt_int("programme_id")
        ok, msg = False, "Nothing to do."
        if act == "save":
            new = pid is None
            ok, msg, pid = lms_programme_save(db, me, pid, request.form)
            # the L&D AI agent tags a new programme straight away; the draft is already saved, so a failure loses
            # nothing (2026-10-22, board 6B)
            if ok and new and ai_draft.is_configured():
                try:
                    _ok2, msg2, _n = lms_suggest_competencies(db, me, pid)
                except Exception:  # noqa: BLE001 -- never lose the draft to the AI
                    app.logger.exception("lms competency suggestion failed")
                    msg2 = "The AI couldn't suggest competencies just now. Try Suggest again."
                msg = "Saved as a draft. " + msg2
        elif act == "comp_suggest":
            ok, msg, _n = lms_suggest_competencies(db, me, pid)
        elif act in ("publish", "draft", "archive"):
            ok, msg = lms_programme_status(db, me, pid, {"publish": "published", "draft": "draft",
                                                         "archive": "archived"}[act])
        elif act in ("comp_add", "comp_confirm", "comp_remove"):
            ok, msg = lms_competency_set(db, me, pid, (request.form.get("comp_key") or "").strip(),
                                         request.form.get("level"), act[5:])
        elif act == "session_add":
            ok, msg = lms_session_save(db, me, pid, request.form)
        elif act == "session_cancel":
            ok, msg = lms_session_save(db, me, pid, request.form, sid=_lms_opt_int("session_id"), cancel=True)
        flash(msg, "ok" if ok else "error")
        return redirect(url_for("admin_learning_programmes", programme=pid, panel="prog") if pid else
                        url_for("admin_learning_programmes"))
    show = request.args.get("show") if request.args.get("show") in ("draft", "published", "archived", "all", "nocomp") \
        else "published"
    allp = lms_programmes(db)
    for p in allp:
        p["no_comp"] = not any(c["confirmed"] for c in p["comps"])
    counts = {k: sum(1 for p in allp if p["status"] == k) for k in LMS_STATUS_LABEL}
    # published before every programme had to build a competency (2026-10-22): flagged, not withdrawn
    counts["nocomp"] = sum(1 for p in allp if p["status"] == "published" and p["no_comp"])
    if not counts["published"] and show == "published" and not request.args.get("show"):
        show = "all"
    progs = (allp if show == "all" else [p for p in allp if p["status"] == "published" and p["no_comp"]]
             if show == "nocomp" else [p for p in allp if p["status"] == show])
    q = " ".join((request.args.get("q") or "").lower().split())[:80]
    if q:
        progs = [p for p in progs if q in p["title"].lower() or q in (p["category"] or "").lower()
                 or any(q in c["title"].lower() for c in p["comps"])]
    pick = None
    pid = request.args.get("programme", type=int)
    if pid:
        pick = next((p for p in allp if p["id"] == pid), None)
    fam = lms_catalogue(db)["fam"]
    comp_opts = sorted(({"key": f["key"], "title": f["title"], "levels": sorted(f["levels"])}
                        for f in fam.values() if f["levels"]), key=lambda f: f["title"].lower())
    return render_template("admin_learning_programmes.html", progs=progs, counts=counts, show=show, q=q, pick=pick,
                           n_lib=len(fam),
                           kinds=LMS_KINDS, bgs=org_bgs(db), units=org_map(db), comp_opts=comp_opts,
                           ai_ok=ai_draft.is_configured(),
                           is_su=lms_can_admin(me), cutoff_days=LMS_REG_CUTOFF_DAYS, cats=lms_category_lists(db),
                           organisers=lms_organisers(db), cert_modes=LMS_CERT_MODES, cert_label=LMS_CERT_MODE_LABEL)


@app.route("/admin/learning/programmes/read", methods=["POST"])
@admin_required
def admin_learning_proposal_read():
    """Read a vendor proposal with AI into a draft programme, then open it (the super admin or an L&D admin)."""
    if not lms_can_admin(current_user()):
        abort(403)
    f = request.files.get("proposal")
    if not f or not f.filename:
        flash("Choose the proposal file first.", "error")
        return redirect(url_for("admin_learning_programmes", panel="read"))
    data = f.read(LMS_PROPOSAL_MAX_BYTES + 1)
    ok, msg, pid = lms_read_proposal(get_db(), current_user(), os.path.basename(f.filename), data)
    flash(msg, "ok" if ok else "error")
    return redirect(url_for("admin_learning_programmes", programme=pid, panel="prog") if ok else
                    url_for("admin_learning_programmes", panel="read"))


