def is_lnd_admin(u):
    """An L&D admin: group-wide, Learning only (Chris, 2026-10-20, decision 4). Never a super admin."""
    return bool(u and u["role"] == "admin" and _row_get(u, "admin_bg") == LMS_ADMIN_BG)


def lms_can_admin(u):
    """Who runs Learning: the super admin or an L&D admin."""
    return is_super(u) or is_lnd_admin(u)


def lms_scope_bg(u):
    """The business group an admin's Learning pages are held to: None for the super admin and an L&D admin."""
    return None if lms_can_admin(u) else admin_bg_of(u)


def lms_people_scope(u, col="u.business_group"):
    """SQL fragment + params holding a Learning read to this admin's people: nothing for the super admin and an L&D
    admin, else their group and, for a BU admin, their units (bg_scope; 2026-10-23, the LMS gap check)."""
    return ("", []) if lms_can_admin(u) else bg_scope(u, col)


def lms_scope_label(u):
    """What lms_people_scope covers, in words: 'All business groups', a group, or a group's units."""
    bg = lms_scope_bg(u)
    if not bg:
        return "All business groups"
    comps = admin_companies_of(u)
    return display_bg(bg) + (": " + ", ".join(display_company(bg, c) for c in sorted(comps)) if comps else "")


@app.before_request
def _lnd_fence():
    """An L&D admin opens the Learning pages and nothing else in the admin area (and nothing at all while Learning is
    dark): a page elsewhere goes to Learning, a write elsewhere is refused."""
    if not session.get("user_id"):
        return None
    p = request.path
    if not (p == "/admin" or p.startswith("/admin/")):
        return None
    u = current_user()
    if not is_lnd_admin(u):
        return None
    if lms_on() and any(p == x or p.startswith(x + "/") for x in _LND_FENCE_OPEN):
        return None
    if request.method == "GET" and lms_on():
        return redirect(url_for("admin_learning_needs"))
    abort(403 if lms_on() else 404)


def lms_chains(db):
    """The approval chain for each kind of programme: the L&D admin's settings (app_settings lms_chains) over the
    defaults. {kind: {levels: [{role, days, escalate, above?}], hod_counts}}."""
    try:
        saved = json.loads(_setting("lms_chains") or "{}")
    except (TypeError, ValueError):
        saved = {}
    out = {}
    for k in LMS_KIND_LABEL:
        c = saved.get(k) if isinstance(saved.get(k), dict) else None
        out[k] = c if c and isinstance(c.get("levels"), list) else json.loads(json.dumps(LMS_CHAIN_DEFAULT[k]))
    return out


# Malaysia's national public holidays (Chris, 2026-10-24: "national 2026-2027 built in, L&D adds state/company days on
# Settings"). The days Learning's working-day clocks skip besides weekends: an approval step's days, the HRDC query's five,
# the reminders and L&D's digest. The federal list's weekdays, Sunday replacements included (a national day a few states
# don't keep, New Year, is in: the head offices keep it). 2026 as gazetted; 2027 from the published calendars, its Islamic
# dates and Deepavali provisional until the Cabinet gazettes them, so L&D can switch a built-in day off. State days
# (Thaipusam, Nuzul Al-Quran, a Sultan's birthday) and company days are L&D's to add (app_settings lms_holidays).
LMS_HOLIDAYS_MY = {
    "2026-01-01": "New Year's Day", "2026-02-17": "Chinese New Year", "2026-02-18": "Chinese New Year, second day",
    "2026-03-20": "Hari Raya Aidilfitri holiday", "2026-03-23": "Hari Raya Aidilfitri, replacement",
    "2026-05-01": "Labour Day", "2026-05-27": "Hari Raya Haji", "2026-06-01": "Agong's Birthday",
    "2026-06-02": "Wesak Day, replacement", "2026-06-17": "Awal Muharram", "2026-08-25": "Prophet Muhammad's Birthday",
    "2026-08-31": "National Day", "2026-09-16": "Malaysia Day", "2026-11-09": "Deepavali, replacement",
    "2026-12-25": "Christmas Day",
    "2027-01-01": "New Year's Day", "2027-02-08": "Chinese New Year, replacement", "2027-03-10": "Hari Raya Aidilfitri",
    "2027-03-11": "Hari Raya Aidilfitri, second day", "2027-05-17": "Hari Raya Haji", "2027-05-20": "Wesak Day",
    "2027-06-07": "Agong's Birthday", "2027-06-08": "Awal Muharram, replacement",
    "2027-08-16": "Prophet Muhammad's Birthday, replacement", "2027-08-31": "National Day", "2027-09-16": "Malaysia Day",
    "2027-10-28": "Deepavali",
}
LMS_HOLIDAYS_PROVISIONAL = frozenset(("2027-03-10", "2027-03-11", "2027-05-17", "2027-05-20", "2027-06-08", "2027-08-16",
                                      "2027-10-28"))


def lms_holiday_cfg():
    """L&D's own: {"add": {iso: name}, "off": [iso of a national day switched off]}. Outside the app (a bare date sum)
    there are none: the national days only."""
    if not has_app_context():
        return {"add": {}, "off": []}
    try:
        c = json.loads(_setting("lms_holidays") or "{}")
    except (TypeError, ValueError):
        c = {}
    add = c.get("add") if isinstance(c.get("add"), dict) else {}
    off = c.get("off") if isinstance(c.get("off"), list) else []
    return {"add": {str(k): str(v) for k, v in add.items()}, "off": [str(x) for x in off]}


def lms_holidays():
    """{iso: {name, src: national | ld, provisional}}: the national days L&D hasn't switched off, and L&D's own. Read
    once a request."""
    rc = _req_cache()
    if "lms_holidays" in rc:
        return rc["lms_holidays"]
    cfg = lms_holiday_cfg()
    out = {d: {"name": n, "src": "national", "provisional": d in LMS_HOLIDAYS_PROVISIONAL}
           for d, n in LMS_HOLIDAYS_MY.items() if d not in cfg["off"]}
    for d, n in cfg["add"].items():
        out[d] = {"name": n, "src": "ld", "provisional": False}
    rc["lms_holidays"] = out
    return out


def lms_holiday_rows(today=None):
    """Learning › Settings' list (2026-10-24): this year's days from today on, then next year's, each {iso, name, src,
    provisional, off} -- a national day L&D switched off stays listed, to switch back on."""
    today = today or _today_myt()
    cfg, live = lms_holiday_cfg(), lms_holidays()
    days = dict(live)
    for d in cfg["off"]:
        if d in LMS_HOLIDAYS_MY:
            days[d] = {"name": LMS_HOLIDAYS_MY[d], "src": "national", "provisional": d in LMS_HOLIDAYS_PROVISIONAL,
                       "off": True}
    out = []
    for y in (today.year, today.year + 1):
        rows = [dict(v, iso=d, off=v.get("off", False)) for d, v in sorted(days.items())
                if d[:4] == str(y) and d >= today.isoformat()]
        out.append({"year": y, "rows": rows, "n": sum(1 for r in rows if not r["off"])})
    return out


def lms_holiday_set(db, me, op, iso, name=None):
    """L&D adds a day of its own, removes one, or switches a national day off or back on. (ok, message)."""
    if not lms_can_admin(me):
        return False, "Only Group People L&D changes the holidays."
    try:
        d = date.fromisoformat(str(iso or "").strip()[:10])
    except ValueError:
        return False, "Pick a date."
    iso, cfg = d.isoformat(), lms_holiday_cfg()
    if op == "add":
        name = " ".join((name or "").split())[:80]
        if not name:
            return False, "Give the holiday's name, e.g. Thaipusam (Selangor)."
        if not _today_myt() - timedelta(days=366) <= d <= _today_myt() + timedelta(days=3 * 366):
            return False, "Pick a date within the next three years."
        if d.weekday() >= 5:
            return False, "%s is a weekend: the clocks skip it already." % _lms_day(iso)
        if iso in LMS_HOLIDAYS_MY and iso not in cfg["off"]:
            return False, "%s is already a national holiday (%s)." % (_lms_day(iso), LMS_HOLIDAYS_MY[iso])
        cfg["add"][iso] = name
        if iso in cfg["off"]:
            cfg["off"].remove(iso)
        word = "added"
    elif op == "remove" and iso in cfg["add"]:
        name = cfg["add"].pop(iso)
        word = "removed"
    elif op == "off" and iso in LMS_HOLIDAYS_MY and iso not in cfg["off"]:
        name = LMS_HOLIDAYS_MY[iso]
        cfg["off"].append(iso)
        word = "switched off"
    elif op == "on" and iso in cfg["off"]:
        name = LMS_HOLIDAYS_MY.get(iso, "")
        cfg["off"].remove(iso)
        word = "switched back on"
    else:
        return False, "Nothing to change."
    db.execute("INSERT INTO app_settings(key, value) VALUES ('lms_holidays', ?) ON CONFLICT(key) DO UPDATE SET "
               "value=excluded.value", (json.dumps({"add": cfg["add"], "off": sorted(cfg["off"])}),))
    log_activity(db, me["id"], "lms_settings", "Public holiday %s: %s, %s" % (word, name, iso))
    db.commit()
    _req_cache().pop("lms_holidays", None)
    return True, "%s, %s: %s. The working-day clocks follow it from now." % (name, _lms_day(iso), word)


def lms_workday(d):
    """A working day: Monday to Friday and not a public holiday."""
    return d.weekday() < 5 and d.isoformat() not in lms_holidays()


def _lms_workdays(d, n):
    """The date n working days after d (weekends and public holidays skipped)."""
    while n > 0:
        d += timedelta(days=1)
        if lms_workday(d):
            n -= 1
    return d


def _lms_user(db, uid):
    return db.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone() if uid else None


def _lms_active(db, uid):
    r = _lms_user(db, uid)
    return r if r and not r["left_at"] else None


def lms_chain_for(db, person, kind, cost=None, nomination="self", nominator=None):
    """The levels a request goes through, resolved for this person now. A line manager or HOD level with nobody on
    record is skipped (said so); a nomination by the line manager approves their own level, and an HOD's nomination
    counts as the line manager's and the HOD's where the chain says so."""
    cfg = lms_chains(db).get(kind) or lms_chains(db)["inhouse"]
    out = []
    for lv in cfg["levels"]:
        role = lv.get("role")
        if role not in LMS_ROLE_LABEL:
            continue
        if lv.get("above") not in (None, "") and (cost or 0) <= float(lv["above"]):
            continue
        step = {"role": role, "days": int(lv.get("days") or 3), "escalate": lv.get("escalate") or None,
                "approver": None, "state": "waiting", "by": None, "at": None, "note": ""}
        if role in ("lm", "hod"):
            ap = _lms_active(db, person["manager_id"] if role == "lm" else person["hod_id"])
            ap = ap if ap and not is_admin(ap) else None   # an admin account can't act in AI+ Learning
            step["approver"] = ap["id"] if ap else None
            if not ap:   # nobody on record (Chris, 2026-10-23): their HOD decides, else Group People L&D
                later = [lv_.get("role") for lv_ in cfg["levels"][cfg["levels"].index(lv) + 1:]]
                hod = _lms_active(db, person["hod_id"]) if role == "lm" else None
                hod = hod if hod and not is_admin(hod) else None
                what = "no %s on record" % LMS_ROLE_LABEL[role].lower()
                if role == "lm" and hod and "hod" in later:
                    step["state"], step["note"] = "skipped", what + ": their HOD decides"
                elif role == "lm" and hod:
                    step.update(role="hod", approver=hod["id"], escalate=None, note=what + ": their HOD decides")
                elif "pp" in later or "lnd" in later:
                    step["state"], step["note"] = "skipped", what + ": Group People L&D decides"
                else:
                    step.update(role="lnd", approver=None, escalate=None, note=what + ": Group People L&D decides")
        if nomination == "manager" and role == "lm":
            step.update(state="approved", by=nominator, note="nominated by their line manager")
        if nomination == "hod" and cfg.get("hod_counts") and role in ("lm", "hod"):
            step.update(state="approved", by=nominator, note="nominated by their HOD")
        if nomination == "hr":
            step.update(state="approved", by=nominator, note="added by L&D")
        out.append(step)
    return out


def _lms_reg(db, rid):
    r = db.execute("SELECT * FROM lms_registrations WHERE id=?", (rid,)).fetchone()
    if not r:
        return None
    d = dict(r)
    try:
        d["chain"] = json.loads(d["chain_json"] or "[]")
    except (TypeError, ValueError):
        d["chain"] = []
    return d


def _lms_level_due(reg):
    """The date the current level is due (its working days from the day it started), or None."""
    ch = reg.get("chain") or []
    if reg["status"] != "pending" or reg["level"] >= len(ch) or not reg.get("level_since"):
        return None
    try:
        start = date.fromisoformat(reg["level_since"][:10])
    except ValueError:
        return None
    return _lms_workdays(start, ch[reg["level"]]["days"])


def _lms_save_chain(db, rid, chain, level, status=None, since=True):
    db.execute("UPDATE lms_registrations SET chain_json=?, level=?, level_since=CASE WHEN ? THEN ? ELSE level_since END,"
               " status=COALESCE(?, status), updated_at=datetime('now') WHERE id=?",
               (json.dumps(chain), level, 1 if since else 0, _today_myt().isoformat(), status, rid))


def _lms_log(db, rid, level, role, actor, action, remark=None):
    db.execute("INSERT INTO lms_approvals(registration_id, level, role, actor_id, action, remark) VALUES (?,?,?,?,?,?)",
               (rid, level, role, actor, action, remark))


def _lms_advance(db, rid, chain, actor=None):
    """Move to the first level still waiting; none left = approved. Returns the new status."""
    nxt = next((i for i, s_ in enumerate(chain) if s_["state"] == "waiting"), None)
    if nxt is None:
        # the last approval on a run already full (seats cut, or more approved than places): the waiting list, with its
        # approvals kept, so a freed place confirms it without asking again (2026-10-23, the LMS gap check)
        reg = _lms_reg(db, rid)
        s_ = _lms_session_row(db, reg["session_id"]) if reg and reg["session_id"] else None
        if s_ and s_["seats"] and db.execute(
                "SELECT COUNT(*) FROM lms_registrations r JOIN users u ON u.id=r.user_id WHERE r.session_id=? AND "
                "r.status='approved' AND u.left_at IS NULL AND r.id!=?", (s_["id"], rid)).fetchone()[0] >= s_["seats"]:
            _lms_save_chain(db, rid, chain, len(chain), "waitlisted")
            _lms_log(db, rid, len(chain), "", None, "waitlisted", "approved, but the run is full")
            return "waitlisted"
        _lms_save_chain(db, rid, chain, len(chain), "approved")
        _lms_notify_approved(db, rid)
        _lms_invite_auto(db, rid)   # the calendar invite goes at once (2026-10-24)
        return "approved"
    _lms_save_chain(db, rid, chain, nxt, "pending")
    _lms_notify_level(db, rid, chain[nxt])
    return "pending"


def _lms_session_row(db, sid):
    """A session with its programme's fields; its trainer is the session's own where L&D set one (2026-10-23), else
    the programme's."""
    return db.execute("SELECT s.*, p.title, p.kind, p.status AS p_status, p.audience_json, p.cost_per_pax, p.hours AS "
                      "p_hours, p.days AS p_days, p.hrdc_claimable, p.vendor, COALESCE(s.trainer_s, p.trainer) AS "
                      "trainer, COALESCE(s.trainer_email_s, p.trainer_email) AS trainer_email FROM lms_sessions s JOIN "
                      "lms_programmes p ON "
                      "p.id=s.programme_id WHERE s.id=?", (sid,)).fetchone()


def _lms_trainer_fields(form):
    """(trainer, trainer email) for a session from a form: the run's own trainer, optional; a malformed email is
    dropped."""
    t = " ".join((form.get("trainer_s") or "").split())[:120] or None
    e = (form.get("trainer_email_s") or "").strip()[:160]
    return t, (e if re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", e) else None)


def _lms_seats_taken(db, sid, but=None):
    """Places held: confirmed, or waiting for approval. `but` leaves out one request (the one being placed)."""
    return db.execute("SELECT COUNT(*) FROM lms_registrations r JOIN users u ON u.id=r.user_id WHERE r.session_id=? AND "
                      "r.status IN ('pending','approved') AND u.left_at IS NULL AND r.id!=?",
                      (sid, but or 0)).fetchone()[0]


def lms_session_open(db, s_, today=None):
    """(open, why not) for registering for a session: planned, its programme published, before its cut-off."""
    today = today or _today_myt().isoformat()
    if not s_ or s_["status"] != "planned" or s_["p_status"] != "published":
        return False, "That session isn't open."
    if s_["starts_on"] <= today:
        return False, "That session has started."
    if s_["reg_cutoff"] and today > s_["reg_cutoff"]:
        return False, "Registration closed on %s." % _lms_day(s_["reg_cutoff"])
    return True, ""


def _lms_start(db, rid, person, kind, cost, nomination, nominator, sid=None, actor_label="sent"):
    """Give a registration its chain and its first step, or a waiting-list place when the session is full."""
    chain = lms_chain_for(db, person, kind, cost, nomination, nominator)
    if sid:
        s_ = _lms_session_row(db, sid)
        if s_ and s_["seats"] and _lms_seats_taken(db, sid, but=rid) >= s_["seats"]:
            _lms_save_chain(db, rid, chain, 0, "waitlisted")
            _lms_log(db, rid, 0, "", nominator or person["id"], "waitlisted")
            _lms_mail(db, "waitlist", person, "reg:%d:wait" % rid, "You're on the waiting list",
                      ["%s is full, so you're on its waiting list." % s_["title"],
                       "If a place comes up it's yours, in turn, and your request starts its approval then."],
                      ("Open AI+ Learning", app_base_url() + "/learning#flight"), prog=s_["title"])
            return "waitlisted"
    _lms_log(db, rid, 0, "", nominator or person["id"], actor_label)
    return _lms_advance(db, rid, chain)


def lms_register(db, person, sid, goal_id=None, why=None, nomination="self", nominator=None, round_id=None,
                 late_reason=None):
    """The one writer of a registration for a catalogue session. (ok, message, id)."""
    s_ = _lms_session_row(db, sid)
    ok, why_not = lms_session_open(db, s_)
    if not ok and not late_reason:
        return False, why_not, None
    aud = lms_audience(s_["audience_json"])
    aud_ok = lms_audience_ok(aud, person)
    if not aud_ok and nomination == "self":
        return False, "That programme isn't open to you.", None
    off_aud = not aud_ok and nomination in ("manager", "hod")   # a leader's nomination outside it, with a reason
    if db.execute("SELECT 1 FROM lms_registrations WHERE user_id=? AND session_id=? AND status IN "
                  "('pending','waitlisted','approved','returned')", (person["id"], sid)).fetchone():
        return False, ("You already have a request for this session." if nomination == "self" else
                       "%s already has a request for this session." % person["full_name"]), None
    other = db.execute("SELECT s.starts_on FROM lms_registrations r JOIN lms_sessions s ON s.id=r.session_id WHERE "
                       "r.user_id=? AND s.programme_id=? AND r.session_id!=? AND r.status IN ('pending','waitlisted',"
                       "'approved','returned') AND s.status='planned' AND s.ends_on>=? ORDER BY s.starts_on LIMIT 1",
                       (person["id"], s_["programme_id"], sid, _today_myt().isoformat())).fetchone()
    if other:   # one run of a programme at a time (2026-10-23, the LMS gap check)
        return False, "%s already %s a place on the %s run of this programme. Withdraw that one first." % (
            "You" if nomination == "self" else person["full_name"], "have" if nomination == "self" else "has",
            _lms_day(other["starts_on"])), None
    why = " ".join((why or "").split())[:500] or None
    if why and ai_draft.stored_text_refusal(why):
        return False, "Say why in your own words, about the training.", None
    if off_aud and not why:
        return False, "%s isn't in this programme's audience (%s). Say why you're nominating them." % (
            person["full_name"], lms_audience_text(aud)), None
    comp, goal = None, None
    if goal_id:
        goal = db.execute("SELECT g.id, g.skill_id FROM pm_idp_goals g JOIN pm_idp i ON i.id=g.idp_id WHERE g.id=? AND "
                          "i.subject_id=?", (goal_id, person["id"])).fetchone()
        if goal:
            comp = lms_catalogue(db)["by_id"].get(goal["skill_id"], (None, None))[0]
    if not goal:   # every request for a programme a plan goal needs is tied to that goal, whoever makes it
        gid, comp = _lms_plan_goal_for(db, person, s_["programme_id"], shared_only=nomination != "self")
        goal = {"id": gid} if gid else None
    pre = _lms_pre(db, person, s_["programme_id"], comp)
    cur = db.execute("INSERT INTO lms_registrations(user_id, session_id, programme_id, cost, hrdc_claimable, goal_id, "
                     "comp_key, why, nomination, nominated_by, round_id, remark, pre_comp, pre_level, off_audience) "
                     "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                     (person["id"], sid, s_["programme_id"], s_["cost_per_pax"], s_["hrdc_claimable"],
                      goal["id"] if goal else None, comp, why, nomination, nominator, round_id, late_reason) + pre +
                     (1 if off_aud else None,))
    rid = cur.lastrowid
    st = _lms_start(db, rid, person, s_["kind"], s_["cost_per_pax"], nomination, nominator, sid)
    db.commit()
    if nomination != "self":   # said to whoever added them (L&D, a leader), about them (the 2026-10-24 Learning QC)
        return True, {"approved": "Confirmed: %s is on the list." % person["full_name"],
                      "waitlisted": "The session is full, so %s is on the waiting list and moves up when a place frees."
                      % person["full_name"], "pending": "Sent for approval."}[st], rid
    return True, {"approved": "Confirmed: you're on the list.", "waitlisted": "The session is full, so you're on the "
                  "waiting list. You move up when a place frees.", "pending": "Sent for approval."}[st], rid


LMS_EXT_FILE_MAX = 10 * 1024 * 1024     # a quotation, a brochure or a certificate (2026-10-23, boards 18E / 18F)
LMS_EXT_STATES = (("to_check", "Certificate in · to check"), ("cert_due", "Awaiting certificate"),
                  ("upcoming", "Approved, still to come"), ("checked", "Checked"), ("not_attended", "Didn't attend"))
LMS_EXT_STATE_LABEL = dict(LMS_EXT_STATES)


def _lms_ext_store(file, prefix, kinds):
    """(stored name, the file's own name, None) for an uploaded PDF (or, where `kinds` allows, a JPG or PNG photo) of
    LMS_EXT_FILE_MAX at most, checked by its first bytes; or (None, None, why not)."""
    ext = _attach_ext(file.filename)
    data = file.read(LMS_EXT_FILE_MAX + 1)
    if ext not in kinds:
        return None, None, "It must be a PDF%s." % (" or a photo (JPG or PNG)" if "png" in kinds else "")
    if not data or len(data) > LMS_EXT_FILE_MAX:
        return None, None, "The file is empty or over %d MB." % (LMS_EXT_FILE_MAX // (1024 * 1024))
    if not (data[:5] == b"%PDF-" if ext == "pdf" else data[:3] == b"\xff\xd8\xff" if ext in ("jpg", "jpeg")
            else data[:8] == b"\x89PNG\r\n\x1a\n"):
        return None, None, "That file isn't the PDF or photo its name says."
    os.makedirs(LMS_UPLOAD_DIR, exist_ok=True)
    name = "%s-%s.%s" % (prefix, secrets.token_hex(8), "jpg" if ext == "jpeg" else ext)
    with open(os.path.join(LMS_UPLOAD_DIR, name), "wb") as fh:
        fh.write(data)
    return name, os.path.basename(file.filename)[:120], None


def lms_ext_state(reg, today=None):
    """Where an approved external course stands (2026-10-23, boards 18E / 18F): 'upcoming' (not over yet), 'cert_due'
    (over, no certificate), 'to_check' (its certificate is in), 'checked' (L&D checked it: its hours count) or
    'not_attended'. None for anything else."""
    if _row_get(reg, "session_id") or _row_get(reg, "status") != "approved":
        return None
    today = (today or _today_myt().isoformat())
    if _row_get(reg, "outcome") == "absent":
        return "not_attended"
    if _row_get(reg, "outcome") in ("attended", "partial"):
        return "checked"
    if (_row_get(reg, "ext_ends_on") or "9") >= today:
        return "upcoming"
    return "to_check" if _row_get(reg, "cert_path") else "cert_due"


def _lms_own_ext(db, person, rid):
    """This person's own approved external course whose certificate is still to come or to check, or None."""
    reg = _lms_reg(db, rid) if rid else None
    if not reg or reg["user_id"] != person["id"] or lms_ext_state(reg) not in ("cert_due", "to_check"):
        return None
    return reg


def lms_ext_cert(db, person, rid, file):
    """The person sends their certificate for an external course that's over (a PDF or a photo, 10 MB): Group People
    L&D checks it, and its hours count then. Sending again replaces it, until it's checked. (ok, message)."""
    reg = _lms_own_ext(db, person, rid)
    if not reg:
        return False, "That course isn't waiting for a certificate."
    if file is None or not file.filename:
        return False, "Choose the certificate: a PDF or a photo."
    name, orig, err = _lms_ext_store(file, "cert-%d" % rid, ("pdf", "jpg", "jpeg", "png"))
    if err:
        return False, err
    db.execute("UPDATE lms_registrations SET cert_path=?, cert_name=?, cert_at=datetime('now'), "
               "updated_at=datetime('now') WHERE id=?", (name, orig, rid))
    log_activity(db, person["id"], "lms_registration", "%s: certificate sent" % reg["ext_title"],
                 target_user_id=person["id"])
    db.commit()
    return True, "Sent to Group People L&D. Your hours count once they've checked it."


def lms_ext_not_going(db, person, rid, reason):
    """The person says they didn't go, with why: the course closes with no hours, and L&D reads why. (ok, msg)."""
    reg = _lms_own_ext(db, person, rid)
    if not reg:
        return False, "That course isn't waiting for a certificate."
    reason = " ".join((reason or "").split())[:300]
    if not reason:
        return False, "Say why you didn't go."
    if ai_draft.stored_text_refusal(reason):
        return False, "Say why in your own words."
    db.execute("UPDATE lms_registrations SET outcome='absent', hours=0, ext_note=?, updated_at=datetime('now') WHERE id=?",
               (reason, rid))
    log_activity(db, person["id"], "lms_registration", "%s: didn't go (%s)" % (reg["ext_title"], reason),
                 target_user_id=person["id"])
    db.commit()
    return True, "Noted. Group People L&D reads why."


def lms_ext_check(db, actor, rid, action, form):
    """Group People L&D checks an external course's certificate: 'checked' credits its hours (asked for on the request,
    or as L&D gives them) and starts the 1- and 3-month check-ins; 'not_attended', with the reason, closes it with
    none. L&D and the super admin only; in the audit log. (ok, message)."""
    if not lms_can_admin(actor):
        return False, "Only Group People L&D checks certificates."
    reg = _lms_reg(db, rid) if rid else None
    st = lms_ext_state(reg) if reg else None
    if action == "checked":
        if st != "to_check":
            return False, "That course has no certificate waiting to be checked."
        hours = _lms_float(form.get("hours"), 0.5, 500) if (form.get("hours") or "").strip() else reg["ext_hours"]
        if not hours:
            return False, "Give the hours to credit."
        db.execute("UPDATE lms_registrations SET outcome='attended', hours=?, checked_by=?, checked_at=datetime('now'), "
                   "ext_note=NULL, updated_at=datetime('now') WHERE id=?", (hours, actor["id"], rid))
        log_activity(db, actor["id"], "lms_registration", "%s: certificate checked, %g h credited" % (
            reg["ext_title"], hours), target_user_id=reg["user_id"])
        db.commit()
        return True, "Checked: %g h credited, and the check-ins follow." % hours
    if action == "not_attended":
        if st not in ("cert_due", "to_check"):
            return False, "That course isn't waiting for a certificate."
        reason = " ".join((form.get("reason") or "").split())[:300]
        if not reason:
            return False, "Give the reason they read."
        db.execute("UPDATE lms_registrations SET outcome='absent', hours=0, checked_by=?, checked_at=datetime('now'), "
                   "ext_note=?, updated_at=datetime('now') WHERE id=?", (actor["id"], reason, rid))
        log_activity(db, actor["id"], "lms_registration", "%s: marked didn't attend (%s)" % (reg["ext_title"], reason),
                     target_user_id=reg["user_id"])
        db.commit()
        return True, "Marked didn't attend, with your reason."
    return False, "Nothing to do."


def lms_ext_list(db, me, state=None, today=None):
    """Learning › Requests › External courses (board 18F): every approved external course in this admin's scope, the
    certificates to check first, with {state, state_label}; and the count of each state. ({rows, counts})."""
    today = (today or _today_myt()).isoformat()
    clause, params = lms_people_scope(me)
    order = {k: i for i, (k, _l) in enumerate(LMS_EXT_STATES)}
    rows = []
    for r in db.execute("SELECT r.id, u.full_name, u.business_group, u.company, u.employee_id FROM lms_registrations r "
                        "JOIN users u ON u.id=r.user_id WHERE r.session_id IS NULL AND r.status='approved'" + clause +
                        " ORDER BY r.ext_ends_on DESC, r.id DESC LIMIT 400", params).fetchall():
        reg = _lms_reg(db, r["id"])
        d = dict(_lms_reg_view(db, reg, today), person=dict(r))
        d["state"] = lms_ext_state(reg, today)
        d["state_label"] = LMS_EXT_STATE_LABEL.get(d["state"], "")
        rows.append(d)
    counts = {k: sum(1 for d in rows if d["state"] == k) for k, _l in LMS_EXT_STATES}
    if state in counts:
        rows = [d for d in rows if d["state"] == state]
    rows.sort(key=lambda d: order.get(d["state"], 9))
    return {"rows": rows, "counts": counts}


def lms_request_external(db, person, form, file=None):
    """A request for an external course not in the catalogue: what, who runs it, when, the cost, why, and the
    quotation or brochure if they have one, for the approvers to read (2026-10-23). (ok, msg, id)."""
    title = " ".join((form.get("ext_title") or "").split())[:160]
    prov = " ".join((form.get("ext_provider") or "").split())[:120]
    why = " ".join((form.get("why") or "").split())[:500]
    try:
        a = date.fromisoformat((form.get("ext_starts_on") or "").strip())
        b = date.fromisoformat((form.get("ext_ends_on") or "").strip() or a.isoformat())
    except ValueError:
        return False, "Give the first and last day as dates.", None
    cost = _lms_float(form.get("cost"), 0, 1000000)
    hours = _lms_float(form.get("ext_hours"), 0, 500)
    if not title or not prov:
        return False, "Say what the course is and who runs it.", None
    if a <= _today_myt() or b < a:
        return False, "The course must start after today, and end on or after its first day.", None
    if cost is None:
        return False, "Give the cost per person in RM (0 if it's free).", None
    if not why or ai_draft.stored_text_refusal(why):
        return False, "Say in your own words why you need it.", None
    if db.execute("SELECT 1 FROM lms_registrations WHERE user_id=? AND session_id IS NULL AND lower(ext_title)=lower(?) "
                  "AND ext_starts_on=? AND status IN ('pending','approved','returned')",
                  (person["id"], title, a.isoformat())).fetchone():
        return False, "You've already asked for this course on these dates. Withdraw that one to change it.", None
    doc, doc_name = None, None
    if file is not None and file.filename:   # the quotation or brochure, a PDF (2026-10-23, board 18E)
        doc, doc_name, err = _lms_ext_store(file, "quote-%d" % person["id"], ("pdf",))
        if err:
            return False, "The quotation: " + err[0].lower() + err[1:], None
    goal_id = _lms_opt_int("goal_id")
    goal = db.execute("SELECT g.id, g.skill_id FROM pm_idp_goals g JOIN pm_idp i ON i.id=g.idp_id WHERE g.id=? AND "
                      "i.subject_id=?", (goal_id, person["id"])).fetchone() if goal_id else None
    comp = lms_catalogue(db)["by_id"].get(goal["skill_id"], (None, None))[0] if goal else None
    pre = _lms_pre(db, person, None, comp)
    cur = db.execute("INSERT INTO lms_registrations(user_id, ext_title, ext_provider, ext_starts_on, ext_ends_on, "
                     "ext_hours, cost, hrdc_claimable, goal_id, comp_key, why, pre_comp, pre_level, ext_doc, "
                     "ext_doc_name) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                     (person["id"], title, prov, a.isoformat(), b.isoformat(), hours, cost,
                      1 if form.get("hrdc_claimable") else 0, goal["id"] if goal else None, comp, why) + pre +
                     (doc, doc_name))
    rid = cur.lastrowid
    _lms_start(db, rid, person, "external", cost, "self", None)
    db.commit()
    return True, "Sent for approval.", rid


def _lms_reg_started(db, reg, today=None):
    """Whether a request's run has started (day one today or before) or its session is no longer planned; an external
    course, its first day (2026-10-23, the LMS gap check)."""
    today = (today or _today_myt()).isoformat()
    if reg.get("session_id"):
        s_ = _lms_session_row(db, reg["session_id"])
        return not s_ or s_["status"] != "planned" or (s_["starts_on"] or "9") <= today
    return bool(reg.get("ext_starts_on") and reg["ext_starts_on"] <= today)


def lms_lapse_started(db, today=None):
    """Requests still waiting when their run starts lapse: pending, on the waiting list or returned, now closed
    ('cancelled', lapsed). lms_auto's turn; until it runs, the space already shows them lapsed. Returns how many."""
    today = (today or _today_myt()).isoformat()
    rows = db.execute(
        "SELECT r.id, r.level FROM lms_registrations r LEFT JOIN lms_sessions s ON s.id=r.session_id WHERE r.status IN "
        "('pending','waitlisted','returned') AND ((r.session_id IS NOT NULL AND (s.status!='planned' OR s.starts_on<=?)) "
        "OR (r.session_id IS NULL AND r.ext_starts_on IS NOT NULL AND r.ext_starts_on<=?))", (today, today)).fetchall()
    for r in rows:
        db.execute("UPDATE lms_registrations SET status='cancelled', closed_kind='lapsed', remark=COALESCE(remark, ?), "
                   "updated_at=datetime('now') WHERE id=?", ("It started before it was approved.", r["id"]))
        _lms_log(db, r["id"], r["level"], "", None, "lapsed")
    db.commit()
    return len(rows)


def lms_close_leavers(db):
    """A leaver's open requests and places on runs not over yet close ('cancelled', left): invites cancelled, the
    waiting list moves up. lms_auto's turn. A place on a run that's over stays as the record. Returns how many."""
    rows = db.execute(
        "SELECT r.id, r.session_id, r.status, r.level FROM lms_registrations r JOIN users u ON u.id=r.user_id LEFT JOIN "
        "lms_sessions s ON s.id=r.session_id WHERE u.left_at IS NOT NULL AND r.status IN ('pending','waitlisted',"
        "'approved','returned') AND COALESCE(s.ends_on, r.ext_ends_on, '9999') >= ?",
        (_today_myt().isoformat(),)).fetchall()
    for r in rows:
        if r["status"] == "approved":
            _lms_invite_cancel(db, r["id"])
        db.execute("UPDATE lms_registrations SET status='cancelled', closed_kind='left', updated_at=datetime('now') "
                   "WHERE id=?", (r["id"],))
        _lms_log(db, r["id"], r["level"], "", None, "left")
        if r["session_id"] and r["status"] in ("pending", "approved"):
            _lms_promote(db, r["session_id"])
    db.commit()
    return len(rows)


def lms_actor_role(db, actor, reg, today=None):
    """The step this person may act on now, as {role, as, escalated}, or None. The approver named at the step; once
    it is past due, also whom it escalates to. A People Partner or an L&D admin step: an L&D admin or the super
    admin."""
    if not actor or reg["status"] != "pending" or reg["level"] >= len(reg["chain"]) or _lms_reg_started(db, reg, today):
        return None
    st = reg["chain"][reg["level"]]
    person = _lms_user(db, reg["user_id"])
    due = _lms_level_due(reg)
    late = bool(due and (today or _today_myt()) > due)

    def fits(role):
        if role == "lm":
            if not leader_learn_can(actor, "lm.learn_approve", db):   # switched off for the seat (Leader roles)
                return False
            # whoever is their line manager now (Chris, 2026-10-23): a new one can act, one who moved on can't
            return actor["id"] == person["manager_id"] and not is_admin(actor)
        if role == "hod":
            return actor["id"] == person["hod_id"] and not is_admin(actor) and \
                leader_learn_can(actor, "hod.learn_approve", db)
        if role == "pp":   # the People Partner step is L&D's (Chris, 2026-10-20: "L&D admins only")
            return lms_can_admin(actor)
        if role == "lnd":
            return lms_can_admin(actor)
        return False
    if fits(st["role"]):
        return {"role": st["role"], "as": st["role"], "escalated": False}
    if late and st.get("escalate") and fits(st["escalate"]):
        return {"role": st["role"], "as": st["escalate"], "escalated": True}
    # a stuck step (Chris, 2026-10-23): nobody can act on it, or it's past its clock with nobody to pass it to.
    # Group People L&D decides it for them, with a reason the person reads (lms_decide)
    if lms_can_admin(actor) and _lms_step_stuck(db, reg, st, late):
        return {"role": st["role"], "as": "lnd", "escalated": False, "override": True}
    return None


LMS_STEP_ABILITY = {"lm": "lm.learn_approve", "hod": "hod.learn_approve"}


def _lms_step_stuck(db, reg, st, late):
    """Whether nobody can act on a request's step: no one holds it (or the seat's ability is switched off), or it's past
    its clock with nobody to pass it to."""
    def can(role):
        ab = LMS_STEP_ABILITY.get(role)
        return any(leader_learn_can(p, ab, db) for p in _lms_step_people(db, reg, role)) if ab else \
            bool(_lms_step_people(db, reg, role))
    if st["role"] in ("pp", "lnd"):
        return False   # L&D's own step: theirs anyway
    if not can(st["role"]):
        return True
    return bool(late and not (st.get("escalate") and can(st["escalate"])))


def lms_decide(db, actor, rid, action, remark=None):
    """Approve or return the step a request is at. Returning needs a remark the person reads. (ok, message)."""
    reg = _lms_reg(db, rid)
    if not reg:
        return False, "That request isn't there."
    if reg["status"] == "pending" and _lms_reg_started(db, reg):
        return False, "Its run has started or was cancelled, so it can't be decided now."
    who = lms_actor_role(db, actor, reg)
    if who and who.get("override"):   # L&D decides a stuck step: the reason is required, whatever the decision
        reason = " ".join((remark or "").split())[:500]
        if not reason:
            return False, "Give the reason: they read it, and it's in the audit log."
        if ai_draft.stored_text_refusal(reason, "manager"):
            return False, "Keep the reason to the request."
        log_activity(db, actor["id"], "lms_registration", "Request %d: %s for the %s step: %s" % (
            rid, {"approve": "approved", "return": "returned", "decline": "declined"}.get(action, action),
            LMS_ROLE_LABEL.get(who["role"], who["role"]).lower(), reason), target_user_id=reg["user_id"])
        if action == "approve":
            reg["chain"][reg["level"]]["note"] = "decided by Group People L&D: %s" % reason
    if not who:
        person = _lms_user(db, reg["user_id"])
        ab = "lm.learn_approve" if person and person["manager_id"] == actor["id"] else \
            "hod.learn_approve" if person and person["hod_id"] == actor["id"] else None
        return False, (ab and leader_learn_off(actor, ab, db)) or "That request isn't waiting on you."
    st = reg["chain"][reg["level"]]
    remark = " ".join((remark or "").split())[:500] or None
    if remark and ai_draft.stored_text_refusal(remark, "manager"):
        return False, "Keep the remark to the request."
    if action == "approve":
        st.update(state="approved", by=actor["id"], at=_now_myt().strftime("%Y-%m-%d %H:%M"),
                  note=("escalated to the %s" % LMS_ROLE_LABEL[who["as"]]) if who["escalated"] else st.get("note", ""))
        _lms_log(db, rid, reg["level"], st["role"], actor["id"], "approved", remark)
        status = _lms_advance(db, rid, reg["chain"])
        db.commit()
        if status == "waitlisted":
            return True, "Approved, but the run is full: they're on its waiting list, confirmed when a place frees."
        return True, "Approved." if status == "approved" else "Approved. It goes to %s next." % \
            LMS_ROLE_NEXT[reg["chain"][next(i for i, s_ in enumerate(reg["chain"]) if s_["state"] == "waiting")]["role"]]
    if action == "decline":   # final (Chris, 2026-10-23): closed with the reason they read, the place freed
        if not remark:
            return False, "Say why you're declining it: they read it."
        st.update(state="declined", by=actor["id"], at=_now_myt().strftime("%Y-%m-%d %H:%M"))
        db.execute("UPDATE lms_registrations SET chain_json=?, status='cancelled', closed_kind='declined', remark=?, "
                   "updated_at=datetime('now') WHERE id=?", (json.dumps(reg["chain"]), remark, rid))
        _lms_log(db, rid, reg["level"], st["role"], actor["id"], "declined", remark)
        _lms_mail(db, "returned", _lms_user(db, reg["user_id"]), "reg:%d:declined" % rid,
                  "Your learning request was declined", ["Your request for %s was declined, with this remark:"
                                                         % _lms_reg_title(db, reg), "“%s”" % remark,
                                                         "Ask your line manager if you'd like to talk it over."],
                  ("Open AI+ Learning", app_base_url() + "/learning#closed"), prog=_lms_reg_title(db, reg))
        if reg["session_id"]:
            _lms_promote(db, reg["session_id"])
        db.commit()
        return True, "Declined with your remark."
    if action == "return":
        if not remark:
            return False, "Say why you're returning it: they read it."
        st.update(state="returned", by=actor["id"], at=_now_myt().strftime("%Y-%m-%d %H:%M"))
        db.execute("UPDATE lms_registrations SET chain_json=?, status='returned', remark=?, updated_at=datetime('now') "
                   "WHERE id=?", (json.dumps(reg["chain"]), remark, rid))
        _lms_log(db, rid, reg["level"], st["role"], actor["id"], "returned", remark)
        n_ret = db.execute("SELECT COUNT(*) FROM lms_approvals WHERE registration_id=? AND action='returned'",
                           (rid,)).fetchone()[0]
        _lms_mail(db, "returned", _lms_user(db, reg["user_id"]), "reg:%d:%d" % (rid, n_ret),
                  "Your learning request came back", ["Your request for %s came back to you, with this remark:"
                                                      % _lms_reg_title(db, reg), "“%s”" % remark,
                                                      "Change it and send it again, or withdraw it, from AI+ Learning."],
                  ("Open AI+ Learning", app_base_url() + "/learning#flight"), prog=_lms_reg_title(db, reg))
        if reg["session_id"]:
            _lms_promote(db, reg["session_id"])
        db.commit()
        return True, "Returned with your remark."
    return False, "Approve, return or decline."


def lms_decide_many(db, actor, rids, action, remark=None):
    """Bulk decisions (Chris, 2026-10-23: "ensure we allow bulk approval/rejection"): each request through lms_decide on
    its own, one note for all; one that can't be decided doesn't stop the rest. (ok, message)."""
    rids = [r for r in dict.fromkeys(rids) if r][:200]
    if not rids:
        return False, "Tick at least one request."
    if action not in ("approve", "return", "decline"):
        return False, "Approve, return or decline."
    if action in ("return", "decline") and not " ".join((remark or "").split()):
        return False, "Give the note everyone ticked reads."
    done, notes = 0, []
    for rid in rids:
        reg = _lms_reg(db, rid)
        ok, msg = lms_decide(db, actor, rid, action, remark)
        if ok:
            done += 1
        else:
            who = _lms_user(db, reg["user_id"]) if reg else None
            notes.append("%s: %s" % (who["full_name"] if who else "#%d" % rid, msg))
    verb = {"approve": "approved", "return": "returned", "decline": "declined"}[action]
    out = "%d %s." % (done, verb) if done else "None %s." % verb
    if notes:
        out += " Not done: " + "; ".join(notes[:3]) + (" and %d more." % (len(notes) - 3) if len(notes) > 3 else "")
    return bool(done), out


def _lms_promote(db, sid):
    """A place freed: the longest-waiting person on the list moves up and their request starts."""
    s_ = _lms_session_row(db, sid)
    if not s_ or (s_["seats"] and _lms_seats_taken(db, sid) >= s_["seats"]):
        return
    w = db.execute("SELECT r.* FROM lms_registrations r JOIN users u ON u.id=r.user_id WHERE r.session_id=? AND "
                   "r.status='waitlisted' AND u.left_at IS NULL ORDER BY r.id LIMIT 1", (sid,)).fetchone()
    if not w:
        return
    person = _lms_user(db, w["user_id"])
    _lms_log(db, w["id"], 0, "", None, "promoted")
    _lms_mail(db, "waitlist", person, "reg:%d:up" % w["id"], "A place came up for you",
              ["A place came up on %s, %s, and it's yours." % (s_["title"], _lms_session_line(dict(s_))),
               "Your request now goes for approval as usual."],
              ("Open AI+ Learning", app_base_url() + "/learning#flight"), prog=s_["title"])
    old = _lms_reg(db, w["id"])["chain"]   # approved already, then full: confirmed now without asking again
    _lms_advance(db, w["id"], old if old and all(st_["state"] in ("approved", "skipped") for st_ in old) else
                 lms_chain_for(db, person, s_["kind"], s_["cost_per_pax"], w["nomination"], w["nominated_by"]))


LMS_WITHDRAW_KINDS = (("clash", "A work clash I can't move"), ("leave", "Leave or medical"),
                      ("role", "No longer relevant to my role"), ("other", "Something else"))


def lms_mine_act(db, person, rid, action, form=None):
    """The person's own: withdraw (before it starts, with a reason their line manager and L&D read: Chris, 2026-10-22,
    "any withdrawal ... requires justification") or send again after it was returned. (ok, message)."""
    reg = _lms_reg(db, rid)
    if not reg or reg["user_id"] != person["id"]:
        return False, "That request isn't yours."
    today = _today_myt().isoformat()
    s_ = _lms_session_row(db, reg["session_id"]) if reg["session_id"] else None
    starts = s_["starts_on"] if s_ else reg["ext_starts_on"]
    if action == "withdraw":
        if reg["status"] not in ("pending", "waitlisted", "approved", "returned"):
            return False, "There's nothing to withdraw."
        if starts and starts <= today:
            return False, "It has started; ask L&D to take you off."
        form = form or {}
        kind = (form.get("why_kind") or "").strip()
        why = " ".join((form.get("why") or "").split())[:300]
        if kind not in dict(LMS_WITHDRAW_KINDS) or not why:
            return False, "Say why you're withdrawing: pick a reason and add a line. Your line manager and L&D read it."
        was = reg["status"]
        db.execute("UPDATE lms_registrations SET status='withdrawn', remark=?, withdraw_kind=?, updated_at=datetime('now') "
                   "WHERE id=?", (why, kind, rid))
        _lms_log(db, rid, reg["level"], "", person["id"], "withdrawn", "%s: %s" % (dict(LMS_WITHDRAW_KINDS)[kind], why))
        _lms_invite_cancel(db, rid)
        if person["manager_id"]:
            _lms_mail(db, "withdrew", _lms_user(db, person["manager_id"]), "reg:%d" % rid,
                      "%s withdrew from training" % person["full_name"],
                      ["%s withdrew from %s." % (person["full_name"], _lms_reg_title(db, reg)),
                       "Their reason: %s: “%s”" % (dict(LMS_WITHDRAW_KINDS)[kind], why)],
                      ("Open AI+ Learning", app_base_url() + "/learning?view=team#absent"),
                      prog=_lms_reg_title(db, reg))
        if s_ and was in ("pending", "approved"):
            _lms_promote(db, s_["id"])
        db.commit()
        return True, "Withdrawn."
    if action == "resend":
        if reg["status"] != "returned":
            return False, "Only a returned request can be sent again."
        if s_:
            ok, why_not = lms_session_open(db, s_)
            if not ok:
                return False, why_not
        # they change it before sending it again, as the line manager's Return promises (the 2026-10-24 Learning QC):
        # the why (their answer to the remark) and the goal. A field the form didn't send stays as it is.
        form = form or {}
        why, goal_id, comp = reg["why"], reg["goal_id"], reg["comp_key"]
        if "why" in form:
            why = " ".join((form.get("why") or "").split())[:500] or None
            if why and ai_draft.stored_text_refusal(why):
                return False, "Say why in your own words, about the training."
            if not why and (not s_ or reg["off_audience"]):
                return False, "Say why: your line manager reads it before deciding."
        if "goal_id" in form:
            raw = (form.get("goal_id") or "").strip()
            gid = int(raw) if raw.isdigit() else None
            if gid:
                g = db.execute("SELECT g.id, g.skill_id FROM pm_idp_goals g JOIN pm_idp i ON i.id=g.idp_id WHERE g.id=? "
                               "AND i.subject_id=?", (gid, person["id"])).fetchone()
                if not g:
                    return False, "Pick one of your own Career Plan goals."
                goal_id = g["id"]
                comp = lms_catalogue(db)["by_id"].get(g["skill_id"], (None, None))[0] or comp
            else:
                goal_id = None
        db.execute("UPDATE lms_registrations SET remark=NULL, why=?, goal_id=?, comp_key=? WHERE id=?",
                   (why, goal_id, comp, rid))
        st = _lms_start(db, rid, person, s_["kind"] if s_ else "external", s_["cost_per_pax"] if s_ else reg["cost"],
                        reg["nomination"], reg["nominated_by"], s_["id"] if s_ else None, "resent")
        db.commit()
        if st == "waitlisted":
            return True, "Sent again. The session is full, so you're on the waiting list: you move up when a place frees."
        return True, "Sent again." if st != "approved" else "Sent again, and confirmed."
    return False, "Withdraw or send again."


def lms_admin_cancel(db, actor, rid, reason):
    reg = _lms_reg(db, rid)
    reason = " ".join((reason or "").split())[:300]
    if not reg or reg["status"] in ("withdrawn", "cancelled"):
        return False, "That request isn't open."
    if not reason:
        return False, "Give the reason: the person reads it."
    db.execute("UPDATE lms_registrations SET status='cancelled', closed_kind='removed', remark=?, "
               "updated_at=datetime('now') WHERE id=?", (reason, rid))
    _lms_log(db, rid, reg["level"], "", actor["id"], "cancelled", reason)
    _lms_invite_cancel(db, rid)
    _who = _lms_user(db, reg["user_id"])
    for _to in [_who] + ([_lms_user(db, _who["manager_id"])] if _who and _who["manager_id"] else []):
        _lms_mail(db, "removed", _to, "reg:%d" % rid, "Taken off: %s" % _lms_reg_title(db, reg),
                  ["%s %s been taken off %s by L&D." % ("You" if _to is _who else _who["full_name"],
                                                         "have" if _to is _who else "has", _lms_reg_title(db, reg)),
                   "L&D's reason: “%s”" % reason],
                  ("Open AI+ Learning", app_base_url() + "/learning"), prog=_lms_reg_title(db, reg))
    if reg["session_id"] and reg["status"] in ("pending", "approved"):
        _lms_promote(db, reg["session_id"])
    log_activity(db, actor["id"], "lms_registration", "Request %d cancelled: %s" % (rid, reason),
                 target_user_id=reg["user_id"])
    db.commit()
    return True, "Cancelled."


def _lms_notify(db, user_row, subject, lines, button=None):
    """One email to one person, through the outbox, where the server sends email at all (production): never on
    staging. Plain lines, escaped here."""
    if not mailer.is_configured() or not user_row or not (user_row["email"] or "").strip():
        return
    body = "".join("<p>%s</p>" % _mescape(x) for x in lines)
    try:
        _outbox_add(db, "lms", user_row["email"], subject, onehr_email(subject, body, button=button),
                    user_id=user_row["id"])
    except Exception as e:   # noqa: BLE001 -- a request never fails on its email
        app.logger.warning("lms email not queued: %s", e)


def _lms_reg_title(db, reg):
    if reg["session_id"]:
        s_ = _lms_session_row(db, reg["session_id"])
        return "%s, %s" % (s_["title"], _lms_session_line(dict(s_))) if s_ else "a session"
    return "%s (%s)" % (reg["ext_title"], reg["ext_provider"])


def _lms_step_ref(db, reg):
    """The approval emails' reference for the step a request is at: its first round keeps the old shape, and each time
    it comes back after a return the round is in it, so the approver is told again (2026-10-23, the LMS gap check)."""
    n = db.execute("SELECT COUNT(*) FROM lms_approvals WHERE registration_id=? AND action='returned'",
                   (reg["id"],)).fetchone()[0]
    return ("reg:%d:r%d:L%d" % (reg["id"], n, reg["level"])) if n else ("reg:%d:L%d" % (reg["id"], reg["level"]))


def _lms_notify_level(db, rid, step):
    """A request reaching a step tells whoever holds it now: the line manager or HOD, or Group People L&D's admins for
    the People Partner and L&D steps (2026-10-23)."""
    reg = _lms_reg(db, rid)
    person = _lms_user(db, reg["user_id"])
    if step["role"] in ("pp", "lnd"):
        for who in _lms_step_people(db, reg, step["role"]):
            _lms_mail(db, "approve", who, _lms_step_ref(db, reg), "A learning request from %s" % person["full_name"],
                      ["%s asks to attend %s. It's at the %s step." % (person["full_name"], _lms_reg_title(db, reg),
                                                                       LMS_ROLE_LABEL[step["role"]]),
                       "Please approve, return or decline it within %d working days." % step["days"]],
                      ("Open Learning › Requests", app_base_url() + "/admin/learning/requests"),
                      prog=_lms_reg_title(db, reg))
        return
    if step["role"] not in ("lm", "hod"):
        return
    for _who in [w for w in _lms_step_people(db, reg, step["role"]) if _lms_may_mail_step(db, w, step["role"])][:1]:
        _lms_mail(db, "approve", _who, _lms_step_ref(db, reg),
                  "A learning request from %s" % person["full_name"],
                  ["%s asks to attend %s." % (person["full_name"], _lms_reg_title(db, reg)),
                   "Please approve, return or decline it within %d working days." % step["days"]],
                  ("Open AI+ Learning", app_base_url() + "/learning?view=%s" % ("dept" if step["role"] == "hod"
                                                                                else "team")),
                  prog=_lms_reg_title(db, reg))


def _lms_role_link(role, base=None):
    """Where someone deciding a step decides it, by the step's role: a line manager's Team, an HOD's Dept, L&D's
    Requests (2026-10-23)."""
    base = base if base is not None else app_base_url()
    return base + {"lm": "/learning?view=team#waiting", "hod": "/learning?view=dept#waiting"}.get(
        role, "/admin/learning/requests")


def _lms_may_mail_step(db, who, role):
    """Whether a step's holder hears about it: not a line manager or HOD whose ability for it is switched off
    (2026-10-23)."""
    ab = LMS_STEP_ABILITY.get(role)
    return not (ab and leader_learn_off(who, ab, db))


def _lms_notify_approved(db, rid):
    reg = _lms_reg(db, rid)
    if not reg:
        return
    _lms_mail(db, "confirmed", _lms_user(db, reg["user_id"]), "reg:%d" % rid, "Your place is confirmed",
              ["You're confirmed for %s." % _lms_reg_title(db, reg),
               "Your calendar invite comes in its own email and goes into your Outlook calendar. On the day, clock in "
               "with the QR code in the room."],
              ("Open AI+ Learning", app_base_url() + "/learning#upcoming"), prog=_lms_reg_title(db, reg))


# --- Attendees, calendar invites, absences (Chris, 2026-10-22; canvas boards 8D, 8E, 15C) -----------------------------
# "admin can issue calendar invite after confirming the training attendee, and remove the invite if the attendee
# withdraws or admin removes them ... Absentism to the training should also be tracked and flagged to admin and LM."
# An invite is one row per confirmed place: emailed with the calendar file where the server sends email, else ready on
# the person's page; withdrawing, being taken off, or the session being cancelled cancels it (a CANCEL with a later
# sequence). An absence is a confirmed place on a day whose clock-in has closed, with no clock-in and no withdrawal
# before it; the person is asked why, their line manager and L&D see it and can excuse it, and two or more not excused
# in a year are flagged. Never part of a performance or potential rating.
LMS_ABSENCE_FLAG = 2


def _ics_text(t):
    return (t or "").replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,").replace("\n", "\\n")


def _ics_fold(line):
    """RFC 5545: a content line is at most 75 octets; longer ones go on with a space."""
    out, cur = [], ""
    for ch in line:
        if len((cur + ch).encode("utf-8")) > 75:
            out.append(cur)
            cur = " " + ch
        else:
            cur += ch
    return "\r\n".join(out + [cur])


# Declining the meeting in Outlook isn't withdrawing (Chris, 2026-10-24: "tell them in the invite"): OneHR reads no
# replies, and a withdrawal needs its reason, so the invite says where to withdraw.
LMS_INVITE_DECLINE_LINE = ("Declining this in Outlook doesn't free your place. Can't come? Withdraw in AI+ Learning with "
                           "your reason, so someone waiting gets it.")


def lms_ics_meeting(db, reg, method, seq, person):
    """A confirmed place as one Outlook meeting (2026-10-24; Chris: "a real meeting request"): the run's first day at
    its times, repeating daily to its last (a run's days are consecutive), organised by OneHR's sender, the person its
    one attendee with no reply asked of them (RSVP=FALSE, so Group People's inbox gets no answers). One UID per place, so
    a later REQUEST (a new SEQUENCE) moves it and a CANCEL removes it."""
    s_ = _lms_session_row(db, reg["session_id"])
    days = _lms_days(dict(s_))
    st = datetime.strptime("%s %s" % (days[0], s_["start_time"] or "09:00"), "%Y-%m-%d %H:%M") - timedelta(hours=8)
    en = datetime.strptime("%s %s" % (days[0], s_["end_time"] or "17:00"), "%Y-%m-%d %H:%M") - timedelta(hours=8)
    stamp = (_now_myt().replace(tzinfo=None) - timedelta(hours=8)).strftime("%Y%m%dT%H%M%SZ")
    org = mailer.sender_address()
    desc = ("Clock in with the QR code on the room's screen, and sign the HRDC T3 at the door. Your place: %s/learning"
            % app_base_url()) if s_["kind"] != "elearning" else "An e-learning course: complete it online by its last day."
    desc += " " + LMS_INVITE_DECLINE_LINE
    lines = ["BEGIN:VCALENDAR", "PRODID:-//OneHR//AI+ Learning//EN", "VERSION:2.0", "CALSCALE:GREGORIAN",
             "METHOD:%s" % method, "BEGIN:VEVENT", "UID:onehr-lms-%d@%s" % (reg["id"], _lms_uid_host()),
             "SEQUENCE:%d" % seq, "DTSTAMP:%s" % stamp, "DTSTART:%s" % st.strftime("%Y%m%dT%H%M%SZ"),
             "DTEND:%s" % en.strftime("%Y%m%dT%H%M%SZ")]
    if len(days) > 1:
        lines.append("RRULE:FREQ=DAILY;COUNT=%d" % len(days))
    lines += ["SUMMARY:%s" % _ics_text(s_["title"]), "LOCATION:%s" % _ics_text(s_["venue"]),
              "DESCRIPTION:%s" % _ics_text(desc), "ORGANIZER;CN=Group People L&D:mailto:%s" % org,
              "ATTENDEE;CN=%s;ROLE=REQ-PARTICIPANT;PARTSTAT=NEEDS-ACTION;RSVP=FALSE:mailto:%s" % (
                  _ics_text(person["full_name"]).replace(":", " "), (person["email"] or "").strip()),
              "STATUS:%s" % ("CANCELLED" if method == "CANCEL" else "CONFIRMED"), "TRANSP:OPAQUE",
              "END:VEVENT", "END:VCALENDAR"]
    return "\r\n".join(_ics_fold(x) for x in lines) + "\r\n"


def _lms_invite_mail(db, reg, s_, person, method, seq):
    """Queue the invite (REQUEST) or its cancellation (CANCEL) as an Outlook meeting request: the calendar is the
    email's own part, so it goes into their calendar by itself (2026-10-24; was an attached file to open)."""
    ics = lms_ics_meeting(db, reg, method, seq, person)
    if method == "CANCEL":
        subj = "Cancelled: %s" % s_["title"]
        lines = ["Your place on %s, %s, is no longer in your calendar." % (s_["title"], _lms_session_line(dict(s_)))]
    else:
        subj = "%s: %s" % ("Updated" if seq else "Calendar invite", s_["title"])
        lines = ["You're confirmed for %s." % s_["title"], "When: %s" % _lms_session_line(dict(s_))]
        if s_["venue"]:
            lines.append("Where: %s" % s_["venue"])
        if s_["trainer"] or s_["vendor"]:
            lines.append("Trainer: %s" % ", ".join(x for x in (s_["trainer"], s_["vendor"]) if x))
        lines += ["It's in your Outlook calendar now. On the day, scan the room's QR to clock in.", LMS_INVITE_DECLINE_LINE]
    try:
        _outbox_add(db, "lms", person["email"], subj, onehr_email(
            subj, "".join("<p>%s</p>" % _mescape(x) for x in lines),
            button=("Your learning", app_base_url() + "/learning")), user_id=person["id"],
            attach=[{"meeting": method, "content": ics}])
    except Exception as e:   # noqa: BLE001 -- an invite never fails the page that sent it
        app.logger.warning("lms invite not queued: %s", e)


def _lms_invite_send(db, actor, reg):
    """Send one confirmed place its invite (no commit). (ok, message)."""
    if not reg or reg["status"] != "approved" or not reg["session_id"]:
        return False, "Only a confirmed place on a OneHR session gets an invite."
    s_ = _lms_session_row(db, reg["session_id"])
    if not s_ or s_["status"] != "planned" or s_["ends_on"] < _today_myt().isoformat():
        return False, "That session isn't coming up."
    inv = db.execute("SELECT * FROM lms_invites WHERE registration_id=?", (reg["id"],)).fetchone()
    if inv and inv["status"] == "sent":
        return True, "Already sent."
    person = _lms_user(db, reg["user_id"])
    seq = (inv["seq"] + 1) if inv else 0
    via = "email" if (mailer.is_configured() and person and (person["email"] or "").strip()) else "page"
    if via == "email":
        _lms_invite_mail(db, reg, s_, person, "REQUEST", seq)
    by = actor["id"] if actor else None   # None: sent by OneHR on confirming the place (2026-10-24)
    if inv:
        db.execute("UPDATE lms_invites SET status='sent', seq=?, via=?, sent_at=datetime('now'), sent_by=?, "
                   "cancelled_at=NULL WHERE id=?", (seq, via, by, inv["id"]))
    else:
        db.execute("INSERT INTO lms_invites(registration_id, seq, via, sent_by) VALUES (?,?,?,?)",
                   (reg["id"], seq, via, by))
    log_activity(db, by, "lms_invite", "Session %d: calendar invite %s%s" % (
        s_["id"], "emailed" if via == "email" else "ready on their page (no email here)",
        "" if actor else ", sent by OneHR on confirming the place"), target_user_id=reg["user_id"])
    return True, "Invite sent." if via == "email" else "Invite ready on their page (this server sends no email)."


def lms_invite_send(db, actor, rid):
    ok, msg = _lms_invite_send(db, actor, _lms_reg(db, rid))
    db.commit()
    return ok, msg


def _lms_invite_auto(db, rid):
    """A place just confirmed gets its calendar invite at once (Chris, 2026-10-24: "automatically on confirm"; it waited
    for L&D's Send invites): a OneHR session still to come, not e-learning, no invite out yet. No commit; never fails
    what confirmed it."""
    try:
        reg = _lms_reg(db, rid)
        if not reg or reg["status"] != "approved" or not reg["session_id"]:
            return False
        s_ = _lms_session_row(db, reg["session_id"])
        if not s_ or s_["kind"] == "elearning" or s_["starts_on"] < _today_myt().isoformat():
            return False
        if db.execute("SELECT 1 FROM lms_invites WHERE registration_id=?", (rid,)).fetchone():
            return False
        return _lms_invite_send(db, None, reg)[0]
    except Exception as e:   # noqa: BLE001
        app.logger.warning("lms invite on confirm not sent: %s", e)
        return False


def lms_invites_auto(db):
    """The scheduler's sweep (lms_auto): every confirmed place on a run still to come with no invite yet, e.g. confirmed
    while this server sent no email. Returns how many went."""
    n = 0
    for r_ in db.execute("SELECT r.id FROM lms_registrations r JOIN lms_sessions s ON s.id=r.session_id JOIN "
                         "lms_programmes p ON p.id=s.programme_id WHERE r.status='approved' AND s.status='planned' AND "
                         "p.kind!='elearning' AND s.starts_on>=? AND NOT EXISTS (SELECT 1 FROM lms_invites i WHERE "
                         "i.registration_id=r.id) ORDER BY s.starts_on, r.id LIMIT 500",
                         (_today_myt().isoformat(),)).fetchall():
        n += 1 if _lms_invite_auto(db, r_["id"]) else 0
    db.commit()
    return n


def lms_invites_send_all(db, actor, sid):
    """Every confirmed place on the session that has no invite out yet. (ok, message)."""
    n = 0
    for r_ in db.execute("SELECT r.id FROM lms_registrations r LEFT JOIN lms_invites i ON i.registration_id=r.id WHERE "
                         "r.session_id=? AND r.status='approved' AND (i.id IS NULL OR i.status!='sent') ORDER BY r.id",
                         (sid,)).fetchall():
        ok, _m = _lms_invite_send(db, actor, _lms_reg(db, r_["id"]))
        n += 1 if ok else 0
    db.commit()
    return (True, "%d invite%s sent." % (n, "" if n == 1 else "s")) if n else (False, "Everyone confirmed has one.")


def _lms_invite_cancel(db, rid):
    """Cancel a place's invite, if one went out (no commit): by email where the server sends it."""
    inv = db.execute("SELECT * FROM lms_invites WHERE registration_id=? AND status='sent'", (rid,)).fetchone()
    if not inv:
        return False
    seq = inv["seq"] + 1
    db.execute("UPDATE lms_invites SET status='cancelled', seq=?, cancelled_at=datetime('now') WHERE id=?",
               (seq, inv["id"]))
    reg = _lms_reg(db, rid)
    person = _lms_user(db, reg["user_id"]) if reg else None
    s_ = _lms_session_row(db, reg["session_id"]) if reg and reg["session_id"] else None
    if s_ and person and inv["via"] == "email" and mailer.is_configured() and (person["email"] or "").strip():
        _lms_invite_mail(db, reg, s_, person, "CANCEL", seq)
    return True


def lms_invite_of(db, rids):
    """{registration id: its invite row (dict)}."""
    out = {}
    for ch in _lms_chunks(list(rids)):
        for r in db.execute("SELECT * FROM lms_invites WHERE registration_id IN (%s)" % ",".join("?" * len(ch)), ch):
            out[r["registration_id"]] = dict(r)
    return out


def _lms_day_over(s_, day, now):
    """Whether a day's clock-in has closed: a past day, or today after half an hour past its end."""
    today = now.date().isoformat()
    if day < today:
        return True
    if day > today or not s_.get("end_time"):
        return False
    try:
        end = datetime.strptime("%s %s" % (day, s_["end_time"]), "%Y-%m-%d %H:%M")
    except ValueError:
        return False
    return now.replace(tzinfo=None) > end + timedelta(minutes=LMS_CHECKIN_LATE_MIN)


def lms_absence_scan(db, sid=None, now=None):
    """Find absences, once each (UNIQUE request and day); a flagged one with a clock-in since is voided. A session run
    since clock-out (needs_out) is read day by day from its clock-ins; an older one, once closed, from its result
    (absent), dated its first day, since its days weren't clocked. E-learning has no room to come to. Returns the
    number new."""
    now = now or _now_myt()
    today = now.date().isoformat()
    new = 0
    q = ("SELECT s.* FROM lms_sessions s JOIN lms_programmes p ON p.id=s.programme_id WHERE s.status='planned' AND "
         "p.kind!='elearning' AND s.starts_on<=? AND (s.needs_out=1 OR s.closed_at IS NOT NULL)")
    args = [today]
    if sid:
        q += " AND s.id=?"
        args.append(sid)
    for s_ in db.execute(q, args).fetchall():
        sd = dict(s_)
        if not sd["needs_out"]:
            for r in db.execute("SELECT id FROM lms_registrations WHERE session_id=? AND status='approved' AND "
                                "outcome='absent'", (sd["id"],)).fetchall():
                new += db.execute("INSERT OR IGNORE INTO lms_absences(registration_id, on_date) VALUES (?,?)",
                                  (r["id"], sd["starts_on"])).rowcount
            continue
        days = [d for d in _lms_days(sd) if _lms_day_over(sd, d, now)]
        if not days:
            continue
        came = {(r["user_id"], r["on_date"]) for r in db.execute(
            "SELECT user_id, on_date FROM lms_attendance WHERE session_id=?", (sd["id"],))}
        for r in db.execute("SELECT id, user_id, created_at, nomination FROM lms_registrations WHERE session_id=? AND "
                            "status='approved'", (sd["id"],)).fetchall():
            made = ""   # a place L&D made on day two (a late add, a walk-in) never misses day one (2026-10-23)
            if r["nomination"] in ("hr", "walkin"):
                try:
                    made = (datetime.strptime(r["created_at"][:19], "%Y-%m-%d %H:%M:%S") +
                            timedelta(hours=8)).date().isoformat()
                except (TypeError, ValueError):
                    made = ""
            for d in [d_ for d_ in days if d_ >= made]:
                if (r["user_id"], d) in came:
                    db.execute("UPDATE lms_absences SET status='void', updated_at=datetime('now') WHERE registration_id=? "
                               "AND on_date=? AND status IN ('open','explained')", (r["id"], d))
                else:
                    new += db.execute("INSERT OR IGNORE INTO lms_absences(registration_id, on_date) VALUES (?,?)",
                                      (r["id"], d)).rowcount
    db.commit()
    return new


def lms_absences(db, uids=None, sid=None, year=None, active=True):
    """Absences as dicts, newest first: {id, registration_id, on_date, status, reason, note, user_id, title, session_id,
    name, ...}. active leaves out voided ones."""
    q = ("SELECT a.*, r.user_id, r.session_id, p.title, u.full_name AS name, u.business_group, u.company, u.manager_id "
         "FROM lms_absences a JOIN lms_registrations r ON r.id=a.registration_id JOIN lms_sessions s ON s.id=r.session_id "
         "JOIN lms_programmes p ON p.id=s.programme_id JOIN users u ON u.id=r.user_id WHERE 1=1")
    args = []
    if active:
        q += " AND a.status!='void'"
    if uids is not None:
        if not uids:
            return []
        q += " AND r.user_id IN (%s)" % ",".join("?" * len(uids))
        args += list(uids)
    if sid:
        q += " AND r.session_id=?"
        args.append(sid)
    if year:
        q += " AND substr(a.on_date, 1, 4)=?"
        args.append(str(year))
    return [dict(r) for r in db.execute(q + " ORDER BY a.on_date DESC, a.id DESC", args)]


def lms_absence_counts(db, uids, year=None):
    """{user id: absences this year not excused} (open or explained)."""
    year = str(year or _today_myt().year)
    out = {u_: 0 for u_ in uids}
    for a in lms_absences(db, list(uids), year=year):
        if a["status"] in ("open", "explained"):
            out[a["user_id"]] = out.get(a["user_id"], 0) + 1
    return out


def lms_absence_explain(db, person, aid, reason, was_there=False):
    """The person says why (their line manager and L&D read it), or that they were there (L&D checks)."""
    a = db.execute("SELECT a.*, r.user_id FROM lms_absences a JOIN lms_registrations r ON r.id=a.registration_id WHERE "
                   "a.id=?", (aid,)).fetchone()
    if not a or a["user_id"] != person["id"] or a["status"] not in ("open", "explained"):
        return False, "There's nothing of yours to explain there."
    why = " ".join((reason or "").split())[:300]
    if was_there:
        why = ("I was there: " + why) if why else "I was there: please check the T3."
    if not why:
        return False, "Tell us why, in a line."
    db.execute("UPDATE lms_absences SET status='explained', reason=?, updated_at=datetime('now') WHERE id=?", (why, aid))
    db.commit()
    return True, "Thank you. Your line manager and L&D can see it."


def lms_absence_excuse(db, actor, aid, note):
    """L&D (or the super admin), or the person's line manager, excuses an absence, with the reason: it stays on the
    record and stops counting toward the flag."""
    a = db.execute("SELECT a.*, r.user_id, u.manager_id FROM lms_absences a JOIN lms_registrations r ON "
                   "r.id=a.registration_id JOIN users u ON u.id=r.user_id WHERE a.id=?", (aid,)).fetchone()
    if not a or a["status"] not in ("open", "explained"):
        return False, "That absence isn't open."
    if not (lms_can_admin(actor) or (actor["role"] != "admin" and a["manager_id"] == actor["id"])):
        return False, "Only L&D or their line manager can excuse it."
    if not lms_can_admin(actor) and leader_learn_off(actor, "lm.learn_excuse", db):
        return False, leader_learn_off(actor, "lm.learn_excuse", db)
    note = " ".join((note or "").split())[:300]
    if not note:
        return False, "Give the reason (e.g. medical leave, MC on file)."
    db.execute("UPDATE lms_absences SET status='excused', note=?, excused_by=?, updated_at=datetime('now') WHERE id=?",
               (note, actor["id"], aid))
    log_activity(db, actor["id"], "lms_absence", "Absence %d excused: %s" % (aid, note), target_user_id=a["user_id"])
    db.commit()
    return True, "Excused."


# --- Every Learning email (Chris, 2026-10-22: "reminder for training, like email reminder to attend training, reminder
# for LM to approve, and evaluate after their direct report attended the training, and whatever is required an email
# communication"; canvas boards 9A, 16A) ------------------------------------------------------------------------------
# One registry, one sender. Each email goes once (lms_sent: kind + what it's about + to whom), only while its kind is on
# in Learning › Settings › Emails, in OneHR's wording or L&D's (a subject and an opening line per kind). Recorded even
# where the server sends no email (staging), so switching email on later never sends a backlog. Every one of them also
# has its row on the dashboard or in AI+ Learning, so nobody depends on email alone.
