@app.route("/learning/register", methods=["GET", "POST"])
@login_required
def learning_register():
    """Register for a session: the request card, filled in from the Career Plan (GET), then sent (POST)."""
    u = current_user()
    if is_admin(u):
        abort(404)
    db = get_db()
    sid = request.values.get("session", type=int)
    if request.method == "POST":
        ok, msg, _rid = lms_register(db, u, sid, _lms_opt_int("goal_id"), request.form.get("why"))
        flash(msg, "ok" if ok else "error")
        return redirect(url_for("learning_home", tab="find") + "#flight" if ok else url_for("learning_register", session=sid))
    s_ = _lms_session_row(db, sid) if sid else None
    ok, why_not = lms_session_open(db, s_) if s_ else (False, "Pick a session from the catalogue.")
    if ok and not lms_audience_ok(lms_audience(s_["audience_json"]), u):
        ok, why_not = False, "That programme isn't open to you."
    needs = {n["key"]: n for n in lms_person_needs(db, u)}
    comps = [dict(c) for c in db.execute("SELECT comp_key, level FROM lms_programme_competencies WHERE programme_id=? "
                                         "AND confirmed=1", (s_["programme_id"],))] if s_ else []
    goals = []
    plan = db.execute("SELECT id FROM pm_idp WHERE subject_id=? ORDER BY plan_year DESC LIMIT 1", (u["id"],)).fetchone()
    if plan:
        by_id = lms_catalogue(db)["by_id"]
        for gl in db.execute("SELECT id, area, skill_id, required_level, have_level FROM pm_idp_goals WHERE idp_id=? "
                             "ORDER BY seq", (plan["id"],)):
            k = by_id.get(gl["skill_id"], (None, None))[0] if gl["skill_id"] else None
            goals.append({"id": gl["id"], "area": gl["area"], "fits": bool(k and any(c["comp_key"] == k for c in comps)),
                          "level": gl["required_level"], "have": gl["have_level"]})
    fit_need = next((needs[c["comp_key"]] for c in comps if c["comp_key"] in needs), None)
    chain = lms_chain_for(db, u, s_["kind"], s_["cost_per_pax"]) if s_ else []
    full = bool(s_ and s_["seats"] and _lms_seats_taken(db, s_["id"]) >= s_["seats"])
    ctx_ = lms_space(db, u, "mine")
    return render_template("learning/shell.html", shell=lms_shell(db, u, ctx_, "find"), **dict(
        ctx_, mode="register", s=dict(s_) if s_ else None, s_line=_lms_session_line(dict(s_))
        if s_ else "", open_ok=ok, why_not=why_not, goals=goals, fit_need=fit_need, chain=chain, full=full))


@app.route("/learning/coach", methods=["GET", "POST"])
@login_required
def learning_coach():
    """The learning coach (2026-10-22, boards 8B, 8C, 2C): GET its opening and this page's conversation, POST a turn.
    Its own route under /learning, so _lms_gate keeps it dark unless Learning is on and open to the person."""
    u = current_user()
    db = get_db()
    if not lms_coach_ctx(db, u, "mine"):
        abort(404)
    page = _lms_coach_page(db, u, request.values.get("page"))
    if request.method == "GET":
        if request.args.get("month"):    # the month card's arrows: the month redrawn in place, nothing kept
            return jsonify(ok=True, card=lms_coach_month(db, u, _lms_month_arg(request.args.get("month"))))
        return jsonify(ok=True, page=page, opening=lms_coach_opening(db, u, page),
                       messages=_lms_coach_history(db, u, page), available=ai_draft.review_agent_available())
    msg = " ".join((request.form.get("message") or "").split())[:600]
    show = (request.form.get("show") or "").strip()[:40]
    if not msg and not show:
        return jsonify(ok=False, say="", quick_replies=[], cards=[])
    n = db.execute("SELECT COUNT(*) FROM activity_log WHERE user_id=? AND action='lms_coach' AND "
                   "created_at >= datetime('now','-60 seconds')", (u["id"],)).fetchone()[0]
    if n >= LMS_COACH_PER_MIN:
        return jsonify(ok=True, say="That's a few questions at once. Give me a moment, then ask again.",
                       quick_replies=[], cards=[], slowed=True)
    if show:
        return jsonify(ok=True, **lms_coach_show(db, u, page, show))
    return jsonify(ok=True, **lms_coach_reply(db, u, page, msg))


