@app.route("/learning/req/<int:rid>/<any(quote, cert):kind>")
@login_required
def learning_req_file(rid, kind):
    """A request's quotation (the person, Group People L&D, and whoever holds its step now) or certificate (the person
    and Group People L&D; nobody else)."""
    u = current_user()
    db = get_db()
    reg = _lms_reg(db, rid)
    if not reg:
        abort(404)
    ok = reg["user_id"] == u["id"] or lms_can_admin(u) or (kind == "quote" and lms_actor_role(db, u, reg) is not None)
    path = _lms_media_path(reg["ext_doc"] if kind == "quote" else reg["cert_path"]) if ok else None
    if not path:
        abort(404)
    ext = path.rsplit(".", 1)[-1].lower()
    with open(path, "rb") as fh:
        data = fh.read()
    resp = Response(data, mimetype=LMS_MIME.get(ext, "application/octet-stream"))
    resp.headers["Cache-Control"] = "private, no-store"
    safe = ((reg["ext_doc_name"] if kind == "quote" else reg["cert_name"]) or "%s.%s" % (kind, ext)).strip()[:120] \
        or "%s.%s" % (kind, ext)
    resp.headers["Content-Disposition"] = _attachment_header(safe, "inline")
    return resp


@app.route("/learning/certificate/<int:cid>")
@login_required
def learning_certificate(cid):
    """A CHART certificate as a PDF (2026-10-23, section 20): the person, Group People L&D and the super admin, and a BG
    or BU admin for their own people. Only an issued one, except for L&D. The person opening theirs counts as seen."""
    u = current_user()
    db = get_db()
    cert = db.execute("SELECT * FROM lms_certificates WHERE id=?", (cid,)).fetchone()
    if not cert or not lms_cert_can_read(db, u, cert) or (cert["status"] != "issued" and not lms_can_admin(u)):
        abort(404)
    data, fname = lms_cert_file(db, cert)
    if not data:
        abort(404)
    if u["id"] == cert["user_id"] and not cert["seen_at"]:
        db.execute("UPDATE lms_certificates SET seen_at=datetime('now') WHERE id=?", (cid,))
        db.commit()
    resp = Response(data, mimetype="application/pdf")
    resp.headers["Cache-Control"] = "private, no-store"
    resp.headers["Content-Disposition"] = _attachment_header(fname, "attachment" if request.args.get("dl") else "inline")
    return resp


