@app.route("/learning/in/<int:sid>", methods=["GET", "POST"])
def learning_checkin(sid):
    """Clock in, from the session's QR (on a phone) or its 6-digit code. Scanned before signing in, a good code is
    held for five minutes in a signed cookie, and sign-in lands back here."""
    db = get_db()
    s_ = _lms_session_row(db, sid)
    if not s_:
        abort(404)
    u = current_user()
    code = (request.values.get("c") or "").strip()
    if not u:
        if code and lms_code_try(db, sid, code, "in", _lms_code_who()) == "ok":
            resp = redirect(url_for("login"))
            resp.set_cookie(_LMS_CI_COOKIE, _lms_ci_signer().dumps({"s": sid}), max_age=300, httponly=True,
                            secure=request.is_secure, samesite="Lax")
            return resp
        return redirect(url_for("login"))
    if is_admin(u):
        abort(404)
    state, msg, ok = None, "", False
    if request.args.get("pre") and _lms_pending_checkin() == sid:
        ok, msg, state = lms_checkin(db, u, sid, "qr")
    elif code:
        tried = lms_code_try(db, sid, code, "in", _lms_code_who(u))
        if tried == "ok":
            ok, msg, state = lms_checkin(db, u, sid, "qr" if request.method == "GET" else "code")
        elif tried == "blocked":
            msg = lms_code_blocked_msg("in")
        else:
            msg = "That code has changed. Scan the QR again, or type the code on the screen now."
    resp = app.make_response(render_template("learning/checkin.html", s=dict(s_), line=_lms_session_line(dict(s_)), ok=ok,
                                         msg=msg, state=state, day=_today_myt().isoformat()))
    if request.cookies.get(_LMS_CI_COOKIE):
        resp.delete_cookie(_LMS_CI_COOKIE)
    return resp


@app.route("/learning/out/<int:sid>", methods=["GET", "POST"])
def learning_checkout(sid):
    """Clock out, from the room's clock-out QR (on a phone) or its 6-digit code (Chris, 2026-10-22, board 3D). A good
    scan is held, signed, for the tap, or on the last day for the rating that clocks them out. Scanned before signing
    in, it's held in the same five-minute cookie as a clock-in, and sign-in lands back here."""
    db = get_db()
    s_ = _lms_session_row(db, sid)
    if not s_:
        abort(404)
    u = current_user()
    code = (request.values.get("c") or "").strip()
    if not u:
        if code and lms_code_try(db, sid, code, "out", _lms_code_who()) == "ok":
            resp = redirect(url_for("login"))
            resp.set_cookie(_LMS_CI_COOKIE, _lms_ci_signer().dumps({"s": sid, "k": "out"}), max_age=300,
                            httponly=True, secure=request.is_secure, samesite="Lax")
            return resp
        return redirect(url_for("login"))
    if is_admin(u):
        abort(404)
    ok, msg, state, ctx, hold = False, "", None, None, None
    method = None
    if request.method == "POST" and request.form.get("hold"):
        held = _lms_out_held(request.form.get("hold"), u, sid)
        if not held:
            msg = "That clock-out has run out. Scan the clock-out code again."
        else:
            ok, msg, state, ctx = lms_checkout(db, u, sid, request.form, method=held[1], day=held[0])
            if state == "rate":   # an answer missing: the form again, still held
                hold = request.form.get("hold")
    else:
        if request.args.get("pre") and _lms_pending_checkin("out") == sid:
            method = "qr"
        elif code:
            tried = lms_code_try(db, sid, code, "out", _lms_code_who(u))
            if tried == "ok":
                method = "qr" if request.method == "GET" else "code"
            elif tried == "blocked":
                msg = lms_code_blocked_msg("out")
            else:
                msg = "That code has changed. Scan the clock-out QR again, or type the code on the screen now."
        if method:
            ctx, msg = _lms_out_ctx(db, u, sid)
            if ctx and ctx["att"]["out_at"] and not ctx["rate"]:
                ok, state, msg = True, "again", "You're already clocked out for today."
            elif ctx:
                state = "rate" if ctx["rate"] else "tap"
                hold = _lms_out_hold(u, sid, ctx["day"], method)
    resp = app.make_response(render_template(
        "learning/checkout.html", s=dict(s_), line=_lms_session_line(dict(s_)), ok=ok, msg=msg, state=state, ctx=ctx,
        hold=hold, questions=LMS_RATE_QUESTIONS, form=request.form if state == "rate" else {},
        now_hm=_now_myt().strftime("%H:%M")))
    if request.cookies.get(_LMS_CI_COOKIE):
        resp.delete_cookie(_LMS_CI_COOKIE)
    return resp


