@app.route("/learning/programme/<int:pid>/<any(photo, brochure):kind>")
@login_required
def learning_programme_file(pid, kind):
    """A programme's photo or brochure, for anyone who can see its page."""
    u = current_user()
    db = get_db()
    p = db.execute("SELECT * FROM lms_programmes WHERE id=?", (pid,)).fetchone()
    if not p or (p["status"] != "published" and not lms_can_admin(u)) or (is_admin(u) and not lms_can_admin(u)):
        abort(404)
    path = _lms_media_path(p["photo_path"] if kind == "photo" else p["brochure_path"])
    if not path:
        abort(404)
    ext = path.rsplit(".", 1)[-1].lower()
    with open(path, "rb") as fh:
        data = fh.read()
    resp = Response(data, mimetype=LMS_MIME.get(ext, "application/octet-stream"))
    resp.headers["Cache-Control"] = "private, max-age=3600"
    if kind == "brochure":
        safe = (p["brochure_name"] or "brochure.pdf").strip()[:120] or "brochure.pdf"
        resp.headers["Content-Disposition"] = _attachment_header(safe, "inline")
    return resp


