# --- the admin side: sessions, the session screen, requests, nominations, settings ----------------------------------
def _lms_admin_session_list(db, me, show):
    today = _today_myt().isoformat()
    rows = []
    for r in db.execute("SELECT s.*, p.title, p.kind FROM lms_sessions s JOIN lms_programmes p ON p.id=s.programme_id "
                        "ORDER BY s.starts_on, s.id"):
        d = dict(r)
        past = d["ends_on"] < today
        if (show == "upcoming" and past) or (show == "past" and not past):
            continue
        cnt = dict(db.execute("SELECT status, COUNT(*) FROM lms_registrations WHERE session_id=? GROUP BY status",
                              (d["id"],)).fetchall())
        d["n"] = {k: cnt.get(k, 0) for k in ("approved", "pending", "waitlisted")}
        d["line"] = _lms_session_line(d)
        d["past"] = past
        d["running"] = not past and d["starts_on"] <= today
        d["cut_days"] = (date.fromisoformat(d["reg_cutoff"]) - _today_myt()).days if d["reg_cutoff"] else None
        rows.append(d)
    return rows


