@admin_required
def admin_learning_paxlist(sid):
    """The final pax list as Excel (S14): name, Employee ID, the IC column left blank (OneHR never holds it), unit,
    group, department, job title, grade. A BG or unit admin gets their own group's people."""
    db = get_db()
    me = current_user()
    s_ = _lms_session_row(db, sid)
    if not s_:
        abort(404)
    rows = [[i + 1, r["full_name"], r["employee_id"], "", display_company(r["business_group"], r["company"]),
             display_bg(r["business_group"]), proper_name(r["department"]), proper_name(r["job_title"]), r["job_grade"],
             r["in_place_of"]] for i, r in enumerate(lms_pax_rows(db, me, sid))]
    log_activity(db, me["id"], "lms_session", "%s: the final pax list downloaded" % s_["title"])
    db.commit()
    return _xlsx_response("pax-list-%s-%s.xlsx" % (re.sub(r"[^A-Za-z0-9]+", "-", s_["title"]).strip("-")[:40],
                                                   s_["starts_on"]),
                          [("Pax list", ["No", "Name", "Employee ID", "IC number", "Business unit", "Business group",
                                         "Department", "Job title", "Job grade", "In place of"], rows)])


@app.route("/admin/learning/sessions/<int:sid>/t3.xlsx")
@admin_required
def admin_learning_t3_xlsx(sid):
    """The HRDC T3 for one day as Excel (S14), pre-filled with the confirmed names, the IC column blank. L&D's."""
    db = get_db()
    me = current_user()
    if not lms_can_admin(me):
        abort(403)
    s_ = _lms_session_row(db, sid)
    day = request.args.get("day")
    if not s_ or day not in _lms_days(dict(s_)):
        abort(404)
    rows = [[i + 1, r["full_name"] + (" (in place of %s)" % r["in_place_of"] if r["in_place_of"] else ""), "",
             r["employee_id"], display_company(r["business_group"], r["company"]), ""]
            for i, r in enumerate(lms_pax_rows(db, me, sid))]
    return _xlsx_response("T3-%s-%s.xlsx" % (re.sub(r"[^A-Za-z0-9]+", "-", s_["title"]).strip("-")[:40], day),
                          [("T3 " + day, ["No", "Name", "IC number", "Employee ID", "Company", "Signature"], rows)])


@app.route("/admin/learning/sessions/<int:sid>/t3/scan")
@admin_required
def admin_learning_t3_scan(sid):
    """The signed T3's scan for a day, as uploaded (L&D and the super admin)."""
    db = get_db()
    if not lms_can_admin(current_user()):
        abort(403)
    row = db.execute("SELECT stored_path, filename FROM lms_t3 WHERE session_id=? AND on_date=?",
                     (sid, request.args.get("day") or "")).fetchone()
    path = os.path.join(LMS_UPLOAD_DIR, row["stored_path"]) if row and row["stored_path"] else None
    if not path or not os.path.exists(path):
        abort(404)
    with open(path, "rb") as fh:
        data = fh.read()
    ext = row["stored_path"].rsplit(".", 1)[-1]
    name = (row["filename"] or "t3." + ext).strip() or "t3." + ext
    return Response(data, mimetype={"pdf": "application/pdf", "png": "image/png"}.get(ext, "image/jpeg"),
                    headers={"Content-Disposition": _attachment_header(name, "inline")})


@app.route("/admin/learning/requests", methods=["GET", "POST"])
@admin_required
def admin_learning_requests():
    """Learning › Requests: what waits on this admin (the People Partner and L&D steps, an L&D admin's), and every
    request in flight with its clock (a BG or unit admin: their own group's)."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        act = request.form.get("action")
        if act == "bulk":   # the ticked ones (Chris, 2026-10-23)
            ok, msg = lms_decide_many(db, me, [int(x) for x in request.form.getlist("rid") if str(x).isdigit()],
                                      request.form.get("bulk"), request.form.get("remark"))
        elif act in ("eval_confirm", "eval_kept"):   # a 3-month check-in nobody else can confirm
            ok, msg = lms_eval_confirm(db, me, _lms_opt_int("eval_id"), "confirm" if act == "eval_confirm" else "kept",
                                       request.form.get("level"), request.form.get("note"))
        elif act in ("ojt_confirm", "ojt_decline"):
            ok, msg = lms_ojt_decide(db, me, _lms_opt_int("ojt_id"), "confirm" if act == "ojt_confirm" else "decline",
                                     request.form.get("note"))
        elif act in ("ext_checked", "ext_absent"):   # an external course's certificate (2026-10-23, board 18F)
            rid = _lms_opt_int("registration_id")
            ok, msg = lms_ext_check(db, me, rid, "checked" if act == "ext_checked" else "not_attended", request.form)
            flash(msg, "ok" if ok else "error")
            return redirect(url_for("admin_learning_requests", view="external") + "#ext-%d" % (rid or 0))
        else:
            ok, msg = lms_decide(db, me, _lms_opt_int("registration_id"), {"approve": "approve", "ret": "return",
                                                                           "decline": "decline"}[act],
                                 request.form.get("remark")) if act in ("approve", "ret", "decline") else \
                (False, "Nothing to do.")
        flash(msg, "ok" if ok else "error")
        return redirect(url_for("admin_learning_requests"))
    today = _today_myt().isoformat()
    if request.args.get("view") == "external":
        st = request.args.get("state")
        ext = lms_ext_list(db, me, st if st in LMS_EXT_STATE_LABEL else None)
        return render_template("admin_learning_requests.html", view="external", ext=ext, states=LMS_EXT_STATES,
                               state=st if st in LMS_EXT_STATE_LABEL else None, can=lms_can_admin(me),
                               n_to_check=ext["counts"]["to_check"])
    waiting = [dict(_lms_reg_view(db, w, today), who=w["who"], person=_lms_user(db, w["user_id"]))
               for w in lms_waiting_on(db, me)]
    clause, params = ("", []) if lms_can_admin(me) else bg_scope(me, "u.business_group")
    flight = [dict(_lms_reg_view(db, _lms_reg(db, r["id"]), today), person=r) for r in db.execute(
        "SELECT r.id, u.full_name, u.business_group, u.company FROM lms_registrations r JOIN users u ON u.id=r.user_id "
        "WHERE r.status IN ('pending','waitlisted','returned')" + clause + " ORDER BY r.level_since, r.id LIMIT 300",
        params)]
    nobody = {"evals": [e for e in lms_eval_to_confirm(db, me) if e["as"] == "lnd"],
              "ojt": [o for o in lms_ojt_to_confirm(db, me) if o["as"] == "lnd"]} if lms_can_admin(me) else None
    return render_template("admin_learning_requests.html", waiting=[w for w in waiting if not w["who"].get("override")],
                           stuck=[w for w in waiting if w["who"].get("override")], nobody=nobody, flight=flight,
                           can=lms_can_admin(me), view="waiting",
                           n_to_check=lms_ext_list(db, me)["counts"]["to_check"])


@app.route("/admin/learning/rounds", methods=["GET", "POST"])
@admin_required
def admin_learning_rounds():
    """Learning › Nominations: rounds the L&D admin opens for HODs, with the sessions in each and how far along each
    business group's HODs are."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        act = request.form.get("action")
        if act == "create":
            title = " ".join((request.form.get("title") or "").split())[:120]
            try:
                closes = date.fromisoformat((request.form.get("closes_on") or "").strip())
            except ValueError:
                closes = None
            sids = [int(x) for x in request.form.getlist("session_ids") if x.isdigit()]
            if not title or not closes or closes < _today_myt() or not sids:
                flash("Give the round a name, a closing date from today, and at least one session.", "error")
            else:
                rid = db.execute("INSERT INTO lms_rounds(title, closes_on, created_by) VALUES (?,?,?)",
                                 (title, closes.isoformat(), me["id"])).lastrowid
                for x in sids:
                    db.execute("INSERT OR IGNORE INTO lms_round_sessions(round_id, session_id) VALUES (?,?)", (rid, x))
                log_activity(db, me["id"], "lms_round", "Nomination round opened: %s (%d sessions, closes %s)" % (
                    title, len(sids), closes.isoformat()))
                db.commit()
                flash("Round opened: HODs see it in AI+ Learning, Dept.", "ok")
        elif act == "close":
            db.execute("UPDATE lms_rounds SET status='closed' WHERE id=?", (_lms_opt_int("round_id"),))
            log_activity(db, me["id"], "lms_round", "Nomination round %s closed" % request.form.get("round_id"))
            db.commit()
            flash("Round closed.", "ok")
        return redirect(url_for("admin_learning_rounds"))
    rounds = []
    hods_by_bg = defaultdict(set)
    for r in db.execute("SELECT DISTINCT u.hod_id, h.business_group FROM users u JOIN users h ON h.id=u.hod_id WHERE "
                        "u.left_at IS NULL AND h.left_at IS NULL AND u.role!='admin'"):
        hods_by_bg[r["business_group"] or "(no group)"].add(r["hod_id"])
    own = lms_scope_bg(me)
    for rd in db.execute("SELECT * FROM lms_rounds ORDER BY status, closes_on DESC").fetchall():
        nom = lms_round_answered(db, rd["id"])   # an HOD counts in their own group, as hods_by_bg does
        bgs = [{"bg": b, "done": len(nom & hods), "of": len(hods)}
               for b, hods in sorted(hods_by_bg.items()) if not own or b == own]
        n_nom = db.execute("SELECT COUNT(*) FROM lms_registrations WHERE round_id=?", (rd["id"],)).fetchone()[0]
        sess = []
        for x in db.execute("SELECT session_id FROM lms_round_sessions WHERE round_id=?", (rd["id"],)).fetchall():
            srow = _lms_session_row(db, x["session_id"])
            if srow:
                sess.append({"title": srow["title"], "line": _lms_session_line(dict(srow))})
        rounds.append({"r": dict(rd), "bgs": bgs, "n": n_nom, "sessions": sess})
    return render_template("admin_learning_rounds.html", rounds=rounds, open_sessions=lms_open_sessions(db),
                           can=lms_can_admin(me))


@app.route("/admin/learning/programmes/page", methods=["GET", "POST"])
@admin_required
def admin_learning_programme_page():
    """A programme's page, edited by L&D (2026-10-22, board 15B): the photo, the brochure, the details staff see, and the
    AI's proposals from the brochure, red until kept."""
    db = get_db()
    me = current_user()
    pid = request.values.get("pid", type=int)
    p = db.execute("SELECT * FROM lms_programmes WHERE id=?", (pid,)).fetchone() if pid else None
    if not p:
        return redirect(url_for("admin_learning_programmes"))
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        act = request.form.get("action") or ""
        if act in ("photo", "brochure"):
            ok, msg = lms_programme_media(db, me, pid, act, request.files.get("file"))
        elif act in ("photo_remove", "brochure_remove"):
            ok, msg = lms_programme_media(db, me, pid, act.split("_")[0], remove=True)
        elif act == "details":
            ok, msg = lms_programme_details_save(db, me, pid, request.form)
        elif act == "ai_fill":
            ok, msg = lms_programme_ai_fill(db, me, pid)
        elif act in ("keep", "drop"):
            ok, msg = lms_programme_ai_keep(db, me, pid, request.form.get("field"), act == "keep")
        else:
            ok, msg = False, "Nothing to do."
        flash(msg, "ok" if ok else "error")
