    try:
        prop = json.loads(p["details_ai_json"] or "{}")
    except ValueError:
        prop = {}
    # the brochure as the AI reads it: a flagged one shows as flagged, and Fill reads the description instead
    prog = dict(p, brochure_text=lms_brochure_text(p), brochure_flag=lms_brochure_flag(p))
    return render_template("admin_learning_programme_page.html", prog=prog, fields=LMS_DETAIL_FIELDS, proposed=prop,
                           can=lms_can_admin(me), ai_on=ai_draft.is_configured())


