@app.route("/admin/learning/announce", methods=["GET", "POST"])
@admin_required
def admin_learning_announce():
    """Announce a published programme (2026-10-22, board 16B): who gets it (everyone, or by business group, business
    unit, department, job grade, job family), counted before sending; the message drafted by the AI from the programme,
    L&D's to edit; now or at a time, in waves. L&D or the super admin."""
    db = get_db()
    me = current_user()
    src = request.form if request.method == "POST" else request.args
    try:
        pid = int(src.get("programme_id") or src.get("pid") or "")
    except ValueError:
        pid = None
    p = db.execute("SELECT * FROM lms_programmes WHERE id=?", (pid,)).fetchone() if pid else None
    if not p:
        return redirect(url_for("admin_learning_programmes"))
    pick = lms_announce_pick(src)
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        if request.form.get("action") == "cancel":   # a scheduled one, before it goes (2026-10-24)
            ok, msg = lms_announce_cancel(db, me, _lms_opt_int("announcement_id"))
            flash(msg, "ok" if ok else "error")
            return redirect(url_for("admin_learning_announce", pid=pid) + "#sent")
        when = (request.form.get("when") or "now")
        at = None
        if when == "later":
            at = "%s %s" % ((request.form.get("send_date") or "").strip(), (request.form.get("send_time") or "").strip())
        ok, msg, _aid = lms_announce_send(db, me, pid, pick, request.form.get("subject"), request.form.get("message"),
                                          send_at=at)
        flash(msg, "ok" if ok else "error")
        if ok:
            return redirect(url_for("admin_learning_announce", pid=pid) + "#sent")
        subject, message = request.form.get("subject") or "", request.form.get("message") or ""
    else:
        subject, message = (lms_announce_draft(db, pid) if request.args.get("draft") else
                            (request.args.get("subject") or "", request.args.get("message") or ""))
    people, left_out, not_open = lms_announce_audience(db, pid, pick) if (pick["all"] or any(
        pick[k] for k, _l in LMS_ANNOUNCE_ROWS)) else ([], 0, 0)
    n_email = sum(1 for u in people if (u["email"] or "").strip())
    times = ["%02d:%02d" % (h, m) for h in range(7, 20) for m in (0, 15, 30, 45)]
    return render_template("admin_learning_announce.html", prog=dict(p), pick=pick, rows=LMS_ANNOUNCE_ROWS,
                           options=lms_announce_options(db), n=len(people), n_email=n_email, left_out=left_out,
                           not_open=not_open, aud_rule=lms_audience_text(lms_audience(p["audience_json"])),
                           subject=subject, message=message, sent=lms_announcements(db, pid), can=lms_can_admin(me),
                           mail_on=mailer.is_configured(), waves=email_wave_rules(), runs=_lms_announce_runs(db, pid),
                           times=times, today=_today_myt().isoformat(), ai_on=ai_draft.is_configured(),
                           total=len(_lms_announce_pool(db)))


@app.route("/admin/learning/emails", methods=["GET", "POST"])
@admin_required
def admin_learning_emails():
    """Learning › Settings › Emails (2026-10-22, board 16A): every email Learning sends, to whom and when, switched on
    or off and worded by L&D (a subject, an opening line). The last 7 days' count beside each."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        kind = request.form.get("kind")
        if kind not in LMS_EMAIL_KINDS:
            abort(400)
        act = request.form.get("action")
        if act == "toggle":
            on = 0 if lms_email_on(db, kind) else 1
            db.execute("INSERT INTO lms_email_settings(kind, enabled, updated_by, updated_at) VALUES (?,?,?,datetime('now')) "
                       "ON CONFLICT(kind) DO UPDATE SET enabled=excluded.enabled, updated_by=excluded.updated_by, "
                       "updated_at=excluded.updated_at", (kind, on, me["id"]))
            msg = "%s: %s." % (LMS_EMAIL_KINDS[kind][2], "on" if on else "off")
        elif act == "words":
            subj = " ".join((request.form.get("subject") or "").split())[:160] or None
            intro = " ".join((request.form.get("intro") or "").split())[:400] or None
            db.execute("INSERT INTO lms_email_settings(kind, subject, intro, updated_by, updated_at) VALUES "
                       "(?,?,?,?,datetime('now')) ON CONFLICT(kind) DO UPDATE SET subject=excluded.subject, "
                       "intro=excluded.intro, updated_by=excluded.updated_by, updated_at=excluded.updated_at",
                       (kind, subj, intro, me["id"]))
            msg = "%s: wording saved." % LMS_EMAIL_KINDS[kind][2]
        else:
            abort(400)
        log_activity(db, me["id"], "lms_email", msg)
        db.commit()
        flash(msg, "ok")
        return redirect(url_for("admin_learning_emails") + "#e-" + kind)
    sent = defaultdict(lambda: [0, 0])
    for r in db.execute("SELECT kind, COUNT(*) AS n, SUM(emailed) AS e FROM lms_sent WHERE created_at>=datetime('now', "
                        "'-7 days') GROUP BY kind"):
        sent[r["kind"]] = [r["n"], r["e"] or 0]
    rows = [dict(zip(("group", "kind", "title", "to", "when"), e), setting=lms_email_setting(db, e[1]),
                 before=e[1] in LMS_EMAILS_BEFORE, sent=sent[e[1]]) for e in LMS_EMAILS]
    return render_template("admin_learning_emails.html", rows=rows, groups=LMS_EMAIL_GROUPS, can=lms_can_admin(me),
                           mail_on=mailer.is_configured(), waves=email_wave_rules())


