@app.route("/admin/learning/settings", methods=["GET", "POST"])
@admin_required
def admin_learning_settings():
    """Learning › Settings: the approval chain for each kind of programme (the L&D admin's to set, Chris 2026-10-20),
    and the L&D admins (the super admin's to add or close)."""
    db = get_db()
    me = current_user()
    if request.method == "POST":
        if not lms_can_admin(me):
            abort(403)
        act = request.form.get("action")
        if act == "clock":   # the session clock's days (S14, board 10B)
            vals = {}
            for k, label, _d in LMS_CLOCK_DEFAULT:
                try:
                    vals[k] = int(request.form.get(k))
                except (TypeError, ValueError):
                    vals[k] = -1
            if any(not 0 <= v <= 365 for v in vals.values()) or not (
                    vals["approve"] <= vals["file"] <= vals["pack"] <= vals["reg_close"]):
                flash("Give each step as days before day one: registration closes first, then the pack, the filing, "
                      "and the grant's approval last.", "error")
            else:
                db.execute("INSERT INTO app_settings(key, value) VALUES ('lms_clock', ?) ON CONFLICT(key) DO UPDATE SET "
                           "value=excluded.value", (json.dumps(vals),))
                log_activity(db, me["id"], "lms_settings", "The session clock: %s" % ", ".join(
                    "%s D-%d" % (k, v) for k, v in vals.items()))
                db.commit()
                flash("Saved. Sessions with their own days keep them; new sessions close registration D-%d."
                      % vals["reg_close"], "ok")
            return redirect(url_for("admin_learning_settings") + "#lm-clock")
        if act == "hrdc_owners":   # who replies to HRDC's queries (2026-10-24)
            ok, msg = lms_hrdc_owners_set(db, me, request.form.get("owners"))
            flash(msg, "ok" if ok else "error")
            return redirect(url_for("admin_learning_settings") + "#lm-owners")
        if act == "holiday":   # public holidays in the working-day clocks (2026-10-24)
            ok, msg = lms_holiday_set(db, me, request.form.get("op"), request.form.get("date"), request.form.get("name"))
            flash(msg, "ok" if ok else "error")
            return redirect(url_for("admin_learning_settings") + "#lm-hols")
        if act == "chain":
            kind = request.form.get("kind")
            if kind not in LMS_KIND_LABEL:
                abort(400)
            levels = []
            for i in range(4):
                role = request.form.get("role_%d" % i)
                if role not in LMS_ROLE_LABEL:
                    continue
                try:
                    days = max(1, min(20, int(request.form.get("days_%d" % i) or 3)))
                except ValueError:
                    days = 3
                esc = request.form.get("esc_%d" % i)
                above = _lms_float(request.form.get("above_%d" % i), 0, 10000000)
                levels.append({"role": role, "days": days, "escalate": esc if esc in LMS_ROLE_LABEL and esc != role
                               else None, **({"above": above} if above else {})})
            if not levels and not request.form.get("none_ok"):   # no steps = no approval at all (2026-10-23)
                flash("A chain with no steps confirms every request at once, with no approval. Tick that box to save "
                      "it so.", "error")
                return redirect(url_for("admin_learning_settings"))
            chains = lms_chains(db)
            old = chains.get(kind)
            chains[kind] = {"levels": levels, "hod_counts": bool(request.form.get("hod_counts"))}
            db.execute("INSERT OR REPLACE INTO app_settings(key, value) VALUES ('lms_chains', ?)", (json.dumps(chains),))
            log_activity(db, me["id"], "lms_chain", "Approval chain for %s: %s (was %s)" % (
                LMS_KIND_LABEL[kind], " > ".join(LMS_ROLE_LABEL[x["role"]] for x in levels) or "no approval",
                " > ".join(LMS_ROLE_LABEL[x["role"]] for x in old["levels"]) or "no approval"))
            db.commit()
            flash("Saved. Requests already sent keep the chain they started with.", "ok")
        elif act == "auto_run":
            # the check-in schedule's turn, now (staging has no timer: Chris's QC, plan §5)
            words = lms_auto_words(lms_auto(db))
            log_activity(db, me["id"], "lms_auto", words)
            db.commit()
            flash(words, "ok")
        elif act == "lnd_pw":   # the super admin sets an L&D admin's password (2026-10-23, the LMS gap check)
            if not is_super(me):
                abort(403)
            uid = _lms_opt_int("user_id")
            row = db.execute("SELECT * FROM users WHERE id=? AND role='admin' AND admin_bg=? AND left_at IS NULL",
                             (uid, LMS_ADMIN_BG)).fetchone()
            np = (request.form.get("new_password") or "").strip()
            _system_admin_refuse(me, row, db)   # (2026-10-28)
            if not row:
                flash("That L&D admin account isn't open.", "error")
            else:
                ok_, msg_ = _admin_account_password_set(db, me, uid, np, "L&D admin", clear_lock=True)
                flash(("Password for %s set to the one you entered. Give it to them yourself." % row["username"])
                      if ok_ else msg_, "ok" if ok_ else "error")
        elif act in ("lnd_add", "lnd_close"):
            if not is_super(me):
                abort(403)
            if act == "lnd_add":
                uname = (request.form.get("username") or "").strip()
                pw = (request.form.get("password") or "").strip()
                name = " ".join((request.form.get("full_name") or "").split())[:80] or uname
                email = (request.form.get("email") or "").strip().lower()
                if not uname or _password_problem(pw, uname):
                    flash(_password_problem(pw, uname) or "Give a username and a password.", "error")
                elif email and (not re.fullmatch(r"[^@\s,;]+@[^@\s,;]+\.[^@\s,;]+", email) or len(email) > 200):
                    flash("Give one email address, or leave it empty.", "error")
                elif db.execute("SELECT 1 FROM users WHERE username=?", (uname,)).fetchone() or _eid_link_owner(db, uname):
                    flash("Username '%s' already exists." % uname, "error")
                else:
                    cur = db.execute("INSERT INTO users(username, full_name, password_hash, role, admin_bg, pw_source, "
                                     "pw_set_at) VALUES (?,?,?, 'admin', ?, 'admin', datetime('now'))",
                                     (uname, "L&D admin — %s" % name, generate_password_hash(pw, method="pbkdf2:sha256"),
                                      LMS_ADMIN_BG))
                    if email:   # where Learning's emails to L&D reach them (2026-10-23, the LMS gap check)
                        db.execute("INSERT INTO admin_notify_emails(user_id, email, added_by) VALUES (?,?,?)",
                                   (cur.lastrowid, email, me["id"]))
                    log_activity(db, me["id"], "lms_admin_add", "%s: L&D admin added%s" % (
                        uname, (", emails to " + email) if email else ""), target_user_id=cur.lastrowid)
                    db.commit()
                    flash("Added %s: they open Learning and nothing else.%s" % (
                        uname, "" if email else " Add their email below, or Learning's emails to L&D won't reach "
                        "them."), "ok")
            else:
                uid = _lms_opt_int("user_id")
                row = db.execute("SELECT * FROM users WHERE id=? AND role='admin' AND admin_bg=?",
                                 (uid, LMS_ADMIN_BG)).fetchone()
                _system_admin_refuse(me, row, db)   # (2026-10-28)
                if row:
                    db.execute("UPDATE users SET left_at=datetime('now') WHERE id=?", (uid,))
                    log_activity(db, me["id"], "lms_admin_close", "%s: L&D admin closed" % row["username"],
                                 target_user_id=uid)
                    db.commit()
                    flash("Closed %s's L&D admin account." % row["username"], "ok")
        return redirect(url_for("admin_learning_settings"))
    admins = [dict(r) for r in db.execute(
        "SELECT id, username, full_name, left_at FROM users WHERE role='admin' AND admin_bg=? ORDER BY left_at IS NOT "
        "NULL, username", (LMS_ADMIN_BG,))] if is_super(me) else []
    for a_ in admins:   # where Learning's emails to L&D go (their notification emails)
        a_["emails"] = [dict(r) for r in db.execute("SELECT id, email FROM admin_notify_emails WHERE user_id=? ORDER BY "
                                                    "id", (a_["id"],))]
    n_due = db.execute("SELECT COUNT(*) FROM lms_evaluations WHERE status='due'").fetchone()[0]
    return render_template("admin_learning_settings.html", chains=lms_chains(db), kinds=LMS_KINDS, roles=LMS_ROLES,
                           admins=admins, can=lms_can_admin(me), is_su=is_super(me), n_due=n_due,
                           notify_max=ADMIN_NOTIFY_MAX, hols=lms_holiday_rows(), owners=lms_hrdc_owners(),
                           clock=[(k, label, lms_clock_days(db)[k]) for k, label, _d in LMS_CLOCK_DEFAULT])


# ---------------------------------------------------------------------------
# AI+ Connect: a system admin's tokens (Chris, 2026-10-28; canvas [design canvas link removed] ... "AI+ Connect: your
# tokens", approved). The tokens read OneHR's admin data from Claude through POST /mcp (onehr_mcp.py). System admin ONLY:
# a super admin, any other admin and anyone signed out get a 404, as if the page did not exist (is_system is the gate;
# ADMIN_ACCESS_MAP says "always" only so the generic role gate does not answer first). The token is shown ONCE, in the
# response to the create POST: never in the session (a client-side cookie), a flash, a redirect or a log.
# ---------------------------------------------------------------------------
def _connect_me():
    me = current_user()
    if not is_system(me):
        abort(404)
    return me


def _connect_url():
    """The address Claude adds: this request's own host (production's public address where it is production)."""
    return (app_base_url() if _PROD else request.url_root.rstrip("/")) + "/mcp"


def _connect_command():
    return 'claude mcp add --transport http onehr %s --header "Authorization: Bearer <your token>"' % _connect_url()


def _connect_tokens(db, me):
    """The viewer's own tokens, newest first, ready to show (dates in MYT)."""
    out = []
    for r in db.execute("SELECT * FROM mcp_tokens WHERE user_id=? ORDER BY id DESC", (me["id"],)):
        exp = _parse_when(_myt(r["expires_at"])) if r["expires_at"] else None
        state = "revoked" if r["revoked_at"] else ("expired" if r["expires_at"] and r["expires_at"] <= _utc_str_now() else "active")

        def when(raw, year=False):
            d = _parse_when(_myt(raw)) if raw else None
            return (d.strftime("%d %b %Y" if year else "%d %b, %H:%M").lstrip("0") if d else "")
        out.append({"id": r["id"], "name": r["name"], "last4": _row_get(r, "token_last4") or "", "state": state,
                    "created": when(r["created_at"], True), "expires": when(r["expires_at"], True),
                    "last_used": when(r["last_used_at"]), "last_ip": r["last_used_ip"] or "",
                    "revoked": when(r["revoked_at"])})
    return out


def _utc_str_now():
    return _utc_now().strftime("%Y-%m-%d %H:%M:%S")


def _connect_page(shown=None, repeat=False):
    db = get_db()
    me = _connect_me()
    resp = app.make_response(render_template("admin_connect.html", tokens=_connect_tokens(db, me),
                                             command=_connect_command(), shown=shown, endpoint=_connect_url(),
                                             repeat=repeat, create_key=secrets.token_hex(16)))
    resp.headers["Cache-Control"] = "no-store"   # a token shown once is never kept by the browser
    return resp


@app.route("/admin/connect")
@admin_required
def admin_connect():
    return _connect_page()


admin_connect._nav_gate = "system"   # read by _admin_nav_allowed: a system admin's alone


@app.route("/admin/connect/create", methods=["POST"])
@admin_required
def admin_connect_create():
    db = get_db()
    me = _connect_me()
    name = " ".join((request.form.get("name") or "").split())[:80]
    days = request.form.get("days", type=int)
    # one-time key from the form: a re-post (a refresh of the page that showed the token) makes nothing and says so
    key = (request.form.get("create_key") or "").strip()[:64]
    if not re.fullmatch(r"[0-9a-f]{32}", key):
        flash("That form is out of date. Open Create a token again.", "error")
        return redirect(url_for("admin_connect"))
    if db.execute("SELECT 1 FROM mcp_tokens WHERE create_key=?", (key,)).fetchone():
        return _connect_page(repeat=True)
    if not name:
        flash("Give the token a name, e.g. the device or app it is for.", "error")
        return redirect(url_for("admin_connect"))
    if days not in (30, 7):
        flash("Choose how long it lasts: 30 or 7 days.", "error")
        return redirect(url_for("admin_connect"))
    try:
        plain = onehr_mcp.mcp_token_create(db, me["id"], name, me["id"], days, create_key=key)
    except sqlite3.IntegrityError:   # the same key arrived twice at once
        db.rollback()
        return _connect_page(repeat=True)
    exp = _parse_when(_myt(db.execute("SELECT expires_at FROM mcp_tokens WHERE token_hash=?",
                                      (onehr_mcp.token_hash(plain),)).fetchone()[0]))
    return _connect_page({"name": name, "token": plain, "until": exp.strftime("%d %b %Y").lstrip("0") if exp else "",
                          "command": _connect_command().replace("<your token>", plain)})


@app.route("/admin/connect/<int:tid>/revoke", methods=["POST"])
@admin_required
def admin_connect_revoke(tid):
    db = get_db()
    me = _connect_me()
    row = db.execute("SELECT * FROM mcp_tokens WHERE id=? AND user_id=?", (tid, me["id"])).fetchone()
    if not row:
        abort(404)
    if onehr_mcp.mcp_token_revoke(db, tid, me["id"]):
        flash("Revoked the token %s. Claude on that device stops reaching OneHR at once." % row["name"], "ok")
    else:
        flash("That token was already revoked.", "info")
    return redirect(url_for("admin_connect"))


# ---------------------------------------------------------------------------
# Grade H Appraisal, piece 2 (2026-10-28): the admin shell and its two imports (spec OneHR/JG H Appraisal/BUILD-SPEC.md,
# canvas A1). The super admin's, every page: /admin/gradeh (tabs: GRADEH_TABS; all four are built: People & progress, Imports,
# Final bands and Settings, the last two filled by the later pieces), and the two imports on the shared four-step engine
# (_imp_register): the Grade H list (who, route, appraiser) and the Strada8 KPI lines (weights total 100%).
# ---------------------------------------------------------------------------
GRADEH_LIST_KIND = "gradeh_list"
GRADEH_KPI_KIND = "gradeh_kpi"
GRADEH_LIST_IMPORT_COLUMNS = ("Employee ID", "Route", "Appraiser employee ID", "HOD employee ID", "Second HOD employee ID", "HOD split %",
                              "Supervisor name", "Company", "Private company")
_GHL_HOD2_NAMES = ("second hod employee id", "second hod id", "second hod", "hod 2 employee id", "hod2 employee id")
_GHL_SPLIT_NAMES = ("hod split %", "hod split", "split %", "split")
GRADEH_KPI_IMPORT_COLUMNS = ("Employee ID", "KPI name", "Weight %", "Group scale")
GRADEH_TABS = (("people", "People & progress"), ("imports", "Imports"), ("bands", "Final bands"),
               ("settings", "Settings"))
_GH_ROUTE_WORDS = {"A": ("kpi", "a", "route a", "kpi route", "kpi form", "kpis"),
                   "B": ("line manager", "lm", "b", "route b", "line manager route", "manager", "standard form",
                         "standard")}
_GH_SCALE_WORDS = {"FIAMMA": "FIAMMA", "SIGNATURE": "SIGNATURE", "OTHER": "OTHER"}


def _gh_route(raw):
    v = " ".join((raw or "").lower().split())
    for code, words in _GH_ROUTE_WORDS.items():
        if v in words:
            return code
    return None


def _gh_route_word(code):
    return {"A": "KPI", "B": "Line manager"}.get(code, "")


def _gh_cycle_error(db):
    """(cycle row, why) : the active cycle, or why Grade H data can't be loaded now (none, or not a Year-End)."""
    cyc = active_cycle(db)
    if not cyc:
        return None, "There's no active cycle to load Grade H Appraisal people into."
    if not gradeh_cycle_offered(cyc):
        return cyc, "Grade H Appraisal runs on a Year-End cycle only: %s isn't one." % cyc["name"]
    return cyc, None


def _gh_users(db, eids):
    """{Employee ID: user dict} for these Employee IDs (one batched read), admins left out."""
    eids = [e for e in dict.fromkeys(eids) if e]
    return {r["employee_id"]: dict(r) for r in _rpt_ids(
        db, "SELECT id, employee_id, full_name, job_grade, manager_id, company, business_group, department, job_title, "
            "left_at, hod_id, is_demo FROM users WHERE role!='admin' AND employee_id IN (%s)", eids)}


def _gh_users_by_id(db, ids):
    ids = [i for i in dict.fromkeys(ids) if i]
    return {r["id"]: dict(r) for r in _rpt_ids(
        db, "SELECT id, employee_id, full_name, left_at FROM users WHERE id IN (%s)", ids)}


def _gh_progress(db, cycle_id, person_ids):
    """{person id: True} for anyone on the list who has started: a KPI figure, an attribute rating or an appraisal."""
    ids = [i for i in dict.fromkeys(person_ids) if i]
    out = {}
    for sql in ("SELECT DISTINCT person_id FROM gradeh_kpi_entries WHERE (staff_pct IS NOT NULL OR lm_pct IS NOT NULL "
                "OR lm_rating IS NOT NULL) AND person_id IN (%s)",
                "SELECT DISTINCT person_id FROM gradeh_ratings WHERE person_id IN (%s)",
                "SELECT DISTINCT person_id FROM gradeh_appraisals WHERE person_id IN (%s)"):
        for r in _rpt_ids(db, sql, ids):
            out[r[0]] = True
    return out


def _gh_weight(raw):
    v = (raw or "").strip().replace("%", "").replace(",", "")
    try:
        w = float(v)
    except ValueError:
        return None
    return w if w == w and 0 < w <= 100 else None


def _gh_fmt_w(w):
    return ("%.2f" % w).rstrip("0").rstrip(".")


# ---- the Grade H list import ------------------------------------------------------------------------------------
def _ghl_load(db, me, meta, data):
    errors, valid, look, private, seen = [], [], {"no_appraiser": [], "company": [], "no_lines": [], "has_lines": [], "hod_bg": [],
                                                  "hod_norole": [], "hod2_norole": [], "hod2_bg": []}, [], set()
    cyc, cerr = _gh_cycle_error(db)
    if cerr:
        errors.append({"row": 0, "eid": "", "why": cerr})
    recs = []
    for i, rec in enumerate(_read_records(meta["filename"], data), start=2):
        recs.append((i, rec))
    eids = [e for _i, r in recs for e in (_pick(r, "employee id", "eid", "id", "staff id", "employee no"),
                                          _pick(r, "appraiser employee id", "appraiser id", "appraiser")) if e]
    users = _gh_users(db, eids)
    mgr = _gh_users_by_id(db, [u["manager_id"] for u in users.values()])
    # the HOD column: resolved like every import's IDs (a linked ID finds its person), one batched read
    hods = _eid_resolve_many(db, [_pick(r, "hod employee id", "hod id", "hod") for _i, r in recs]
                             + [_pick(r, *_GHL_HOD2_NAMES) for _i, r in recs])   # the second HOD too (2026-11-03)
    cols2 = any(c in rec for _i, rec in recs for c in _GHL_HOD2_NAMES + _GHL_SPLIT_NAMES)   # does the file carry the two new columns?
    main_hod = _gh_users_by_id(db, [u["hod_id"] for u in users.values()])
    cid = cyc["id"] if cyc else 0
    existing = {r["employee_id"]: dict(r) for r in db.execute(
        "SELECT * FROM gradeh_people WHERE cycle_id=?", (cid,))}
    n_lines = {r[0]: r[1] for r in db.execute("SELECT person_id, COUNT(*) FROM gradeh_kpi_lines WHERE cycle_id=? "
                                              "GROUP BY person_id", (cid,))}
    blank = rows = 0
    for i, rec in recs:
        eid = _pick(rec, "employee id", "eid", "id", "staff id", "employee no")
        route_raw = _pick(rec, "route")
        appr = _pick(rec, "appraiser employee id", "appraiser id", "appraiser")
        hod_raw = _pick(rec, "hod employee id", "hod id", "hod")
        sup = " ".join(_pick(rec, "supervisor name", "supervisor").split())
        sup_eid = _pick(rec, "supervisor employee id", "supervisor eyee id")
        company = " ".join(_pick(rec, "company").split())
        priv_col = _pick(rec, "private company", "private")
        kind = _pick(rec, "type of assessment")
        hod2_raw = _pick(rec, *_GHL_HOD2_NAMES)
        split_raw = _pick(rec, *_GHL_SPLIT_NAMES)
        if eid and not (route_raw or appr or hod_raw or hod2_raw or split_raw or sup or company or priv_col or kind):
            blank += 1
            continue
        if not eid and not (route_raw or appr or sup or company):
            continue
        rows += 1
        err = lambda why, e=eid, n=i: errors.append({"row": n, "eid": e or "", "why": why})  # noqa: E731
        if not eid:
            err("A row has no Employee ID.")
            continue
        if eid.upper().startswith("EXAMPLE-"):
            err("%s: this is the template's example row: replace it with a real Employee ID." % eid)
            continue
        if priv_col.lower() in ("yes", "y", "true", "1", "private") or kind.upper() == "OFFLINE":
            private.append({"row": i, "eid": eid, "company": company})   # skipped and counted, never loaded
            continue
        if eid in seen:
            err("%s: appears more than once in the file." % eid)
            continue
        seen.add(eid)
        u = users.get(eid)
        if not u:
            err("%s: no employee with this Employee ID in OneHR." % eid)
            continue
        if u["left_at"]:
            err("%s: has left, so isn't on the list." % eid)
            continue
        if str(u["job_grade"] if u["job_grade"] is not None else "").strip().upper() != "H":
            err("%s: isn't Grade H in OneHR (their grade is %s)." % (eid, u["job_grade"] or "empty"))
            continue
        route = _gh_route(route_raw)
        if not route:
            err("%s: Route must be KPI or Line manager%s." % (eid, (", not “%s”" % route_raw) if route_raw else ""))
            continue
        appr_u = None
        if appr:
            appr_u = users.get(appr)
            if not appr_u or appr_u["left_at"]:
                err("%s: appraiser %s isn't a current employee in OneHR." % (eid, appr))
                continue
            if appr_u["id"] == u["id"]:
                err("%s: can't be their own appraiser." % eid)
                continue
        hod_u = None
        if hod_raw:
            hod_u = (hods.get(hod_raw) or (None, False))[0]
            if not hod_u or hod_u["role"] == "admin" or hod_u["left_at"]:
                err("%s: the HOD %s isn't a current employee in OneHR." % (eid, hod_raw))
                continue
            if hod_u["is_demo"]:
                err("%s: the HOD %s is a demo login." % (eid, hod_raw))
                continue
            if hod_u["id"] == u["id"]:
                err("%s: can't be their own HOD." % eid)
                continue
        ex = existing.get(eid)
        # the second HOD and the split (2026-11-03). A file WITHOUT the columns never touches a second HOD already set; WITH them a blank cell
        # takes it away (the super admin answers on the Changes step); the split is the FIRST HOD's share, 10 to 90 in 10s, blank = 50
        hod2_u, split_v = None, None
        has2col = any(c in rec for c in _GHL_HOD2_NAMES)
        ex2 = (ex["hod2_user_id"] if ex else None) or None
        if hod2_raw:
            hod2_u = (hods.get(hod2_raw) or (None, False))[0]
            if not hod2_u or hod2_u["role"] == "admin" or hod2_u["left_at"]:
                err("%s: the second HOD %s isn't a current employee in OneHR." % (eid, hod2_raw))
                continue
            if hod2_u["is_demo"]:
                err("%s: the second HOD %s is a demo login." % (eid, hod2_raw))
                continue
            if hod2_u["id"] == u["id"]:
                err("%s: can't be their own second HOD." % eid)
                continue
            first_id = hod_u["id"] if hod_u else ((ex["hod_user_id"] if ex else None) or u["hod_id"])
            if first_id and hod2_u["id"] == first_id:
                err("%s: the second HOD %s is the same person as the HOD." % (eid, hod2_raw))
                continue
        if split_raw:
            try:
                sp_f = float(split_raw.replace("%", "").replace(",", "").strip())
            except ValueError:
                sp_f = None
            if sp_f is None or sp_f != int(sp_f) or int(sp_f) not in GRADEH_SPLITS:
                err("%s: the HOD split must be the first HOD's share, 10 to 90 in steps of 10 (“%s”)." % (eid, split_raw))
                continue
            if not (hod2_raw or (not has2col and ex2)):
                err("%s: a HOD split needs a second HOD (the cell is blank)." % eid)
                continue
            split_v = int(sp_f)
        lm = mgr.get(u["manager_id"]) if u["manager_id"] else None
        lm_ok = bool(lm and not lm["left_at"])
        mh = main_hod.get(u["hod_id"]) if u["hod_id"] else None
        v = {"row": i, "eid": eid, "uid": u["id"], "name": u["full_name"], "route": route, "unit": u["company"] or "",
             "hod_id": hod_u["id"] if hod_u else None, "hod_name": hod_u["full_name"] if hod_u else None,
             "main_hod_name": mh["full_name"] if (mh and not mh["left_at"]) else None,
             "appraiser_id": appr_u["id"] if appr_u else None, "appraiser_eid": appr, "lm_ok": lm_ok,
             "appraiser_name": appr_u["full_name"] if appr_u else None, "lm_name": lm["full_name"] if lm_ok else None,
             "sup_name": sup, "sup_eid": sup_eid, "company": company, "ex": ex,
             "lines": n_lines.get(ex["id"], 0) if ex else 0,
             "hod2_id": hod2_u["id"] if hod2_u else None, "hod2_name": hod2_u["full_name"] if hod2_u else None,
             "split": split_v, "mode2": "set" if hod2_u else ("clear" if has2col else "none"), "cols2": cols2}
        valid.append(v)
        if hod2_u and (hod2_u["business_group"] or "").strip().upper() != (u["business_group"] or "").strip().upper():
            look["hod2_bg"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: the second HOD %s is in %s, the person is in %s" % (
                eid, hod2_u["full_name"], display_bg(hod2_u["business_group"] or "") or "no business group",
                display_bg(u["business_group"] or "") or "no business group")})
        if hod2_u and not gradeh_hod_has_role(db, hod2_u["id"]):
            look["hod2_norole"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: the second HOD %s holds a BU CEO or BG CEO "
                                        "seat, so has no Grade H HOD role: the HOD takes 100%%" % (eid, hod2_u["full_name"])})
        if hod_u and (hod_u["business_group"] or "").strip().upper() != (u["business_group"] or "").strip().upper():
            look["hod_bg"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: the HOD %s is in %s, the person is in %s" % (
                eid, hod_u["full_name"], display_bg(hod_u["business_group"] or "") or "no business group",
                display_bg(u["business_group"] or "") or "no business group")})
        if hod_u and not gradeh_hod_has_role(db, hod_u["id"]):
            look["hod_norole"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: the HOD %s holds a BU CEO or BG CEO "
                                       "seat, so has no Grade H HOD role" % (eid, hod_u["full_name"])})
        if not appr_u and not lm_ok:
            look["no_appraiser"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: %s" % (eid, (
                "no line manager on OneHR: the supervisor named in the file (%s) is kept as text until someone is set "
                "as their appraiser" % sup) if sup else "no appraiser and no line manager: set one on People & progress")})
        if company and company.upper() != (u["company"] or "").upper():
            look["company"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: the file says %s, OneHR says %s" % (
                eid, company, u["company"] or "no company")})
        if route == "A" and not v["lines"]:
            look["no_lines"].append({"row": i, "eid": eid, "rows": [i],
                                     "detail": "%s: KPI route with no KPI lines yet" % eid})
        if route == "B" and v["lines"]:
            look["has_lines"].append({"row": i, "eid": eid, "rows": [i], "detail": "%s: Line manager route, yet %d KPI "
                                      "lines are loaded for them: the lines stay, unused" % (eid, v["lines"])})
    if not rows and not private and not errors:
        errors.append({"row": 0, "eid": "", "why": "That file has no rows to apply."})
    prog = _gh_progress(db, cid, [v["ex"]["id"] for v in valid if v["ex"]])
    for v in valid:
        v["progress"] = bool(v["ex"] and prog.get(v["ex"]["id"]))
    return {"errors": errors, "rows": rows + 0, "valid": valid, "look": look, "private": private, "cyc": cyc,
            "blank_rows": blank, "cols2": cols2}


def _ghl_change(v):
    """What a row does: added / updated / same."""
    ex = v["ex"]
    if not ex:
        return "added"
    same = (ex["route"] == v["route"] and (ex["appraiser_id"] or None) == (v["appraiser_id"] or None)
            and (ex["hr_supervisor_name"] or "") == (v["sup_name"] or "")
            and (ex["hr_supervisor_employee_id"] or "") == (v["sup_eid"] or "")
            and (v["hod_id"] is None or (ex["hod_user_id"] or None) == v["hod_id"])   # a blank HOD never changes anything
            and _ghl_want2(v) == ((ex["hod2_user_id"] or None, ex["hod_split"] if ex["hod2_user_id"] else None)))
    return "same" if same else "updated"


def _ghl_want2(v):
    """(second HOD id, split) the FILE asks for: the file's second HOD with its split (blank = 50); a blank cell under a second-HOD column
    asks for none; a file without the columns asks for what is set now (a split alone moves the one set now)."""
    ex = v["ex"]
    ex2, exs = ((ex["hod2_user_id"] or None) if ex else None), (ex["hod_split"] if ex else None)
    if v["mode2"] == "set":
        return v["hod2_id"], (v["split"] or 50)
    if v["mode2"] == "clear":
        return None, None
    if ex2 and v["split"]:
        return ex2, v["split"]
    return ex2, (exs if ex2 else None)


def _ghl_final_hod2(v, decisions):
    """The second HOD (user id or None) and the split a row ends with, given the super admin's answer: the file's (_ghl_want2), unless a
    second HOD is set now and the file names a different one, or none, and the super admin kept the one set now. A blank is never
    undone without an answer (the Changes step asks)."""
    ex = v["ex"]
    ex2 = (ex["hod2_user_id"] or None) if ex else None
    want = _ghl_want2(v)
    if ex2 and want[0] != ex2 and decisions.get("hod2:" + v["eid"]) != "file":
        return ex2, (ex["hod_split"] or 50)
    return want


def _ghl_ask(v):
    """The decisions a row needs from the super admin, as [(key, kind)]."""
    ex = v["ex"]
    out = []
    if ex and v["progress"] and ex["route"] != v["route"]:
        out.append(("route:" + v["eid"], "route"))
    if ex and ex["appraiser_id"] and v["appraiser_id"] and ex["appraiser_id"] != v["appraiser_id"]:
        out.append(("appr:" + v["eid"], "appr"))
    if ex and ex["hod_user_id"] and v["hod_id"] and ex["hod_user_id"] != v["hod_id"]:
        out.append(("hod:" + v["eid"], "hod"))
    if ex and ex["hod2_user_id"] and _ghl_want2(v)[0] != ex["hod2_user_id"]:   # a different second HOD, or none, where one is set now
        out.append(("hod2:" + v["eid"], "hod2"))
    return out


def _ghl_final(v, decisions):
    """The route and appraiser a row ends with, given the super admin's answers: (route, appraiser_id)."""
    ex = v["ex"]
    route, appr = v["route"], v["appraiser_id"]
    if ex:
        if decisions.get("route:" + v["eid"]) == "keep":
            route = ex["route"]
        if decisions.get("appr:" + v["eid"]) == "keep" or (appr is None and ex["appraiser_id"]):
            appr = ex["appraiser_id"]   # a blank in the file never wipes an appraiser set by hand
    return route, appr


def _ghl_final_hod(v, decisions):
    """The Grade H HOD (user id, or None = their OneHR HOD) a row ends with: the file's, unless the super admin kept the one set now;
    a blank in the file never wipes an HOD set earlier (as for the appraiser)."""
    ex = v["ex"]
    hod = v["hod_id"]
    if ex and ex["hod_user_id"] and (hod is None or decisions.get("hod:" + v["eid"]) == "keep"):
        hod = ex["hod_user_id"]
    return hod


def _ghl_hod_words(v, hod_id=None):
    """Who the person's Grade H HOD is, in words: the file's (or the one set now), else their OneHR HOD, else the BU CEO."""
    if hod_id and hod_id == v["hod_id"]:
        return v["hod_name"]
    if hod_id:
        return "the one set now"
    if v["main_hod_name"]:
        return "OneHR HOD (%s)" % v["main_hod_name"]
    return "No HOD (the BU CEO covers them)"


def _ghl_appraiser_words(v, appr_id=None):
    if v["appraiser_name"] and (appr_id is None or appr_id == v["appraiser_id"]):
        return v["appraiser_name"]
    if appr_id and appr_id != v["appraiser_id"]:
        return "the one set now"
    if v["lm_name"]:
        return "Line manager (%s)" % v["lm_name"]
    return ("Supervisor in the file: %s" % v["sup_name"]) if v["sup_name"] else "None yet"


def _ghl_changes(db, me, ctx, decisions):
    valid = ctx["valid"]
    kinds = {"added": 0, "updated": 0, "same": 0}
    for v in valid:
        kinds[_ghl_change(v)] += 1
    n_a = sum(1 for v in valid if v["route"] == "A")
    tiles = [(kinds["added"], "to add to the list", "#2f64d6"), (kinds["updated"], "already on it, changed", "#e0a84a"),
             (kinds["same"], "already on it, the same", "#9aa1b5"), (len(ctx["private"]), "private company, skipped",
                                                                   "#d0716a")]
    cols2 = bool(ctx.get("cols2"))
    if cols2:   # the file carries the second-HOD columns: how many people share two HODs, how many lose their second HOD
        tiles += [(sum(1 for v in valid if _ghl_want2(v)[0]), "HOD shared (two HODs)", "#6a55b8"),
                  (sum(1 for v in valid if v["ex"] and v["ex"]["hod2_user_id"] and _ghl_want2(v)[0] is None), "second HOD removed", "#d0716a")]
    word = {"added": "Added", "updated": "Changed", "same": "No change"}
    sections = [{"title": "Who goes on the list", "dl": "changes",
                 "note": "%d on the KPI route, %d on the Line manager route. A blank Appraiser means their line manager on "
                         "OneHR; a blank HOD means their OneHR HOD." % (n_a, len(valid) - n_a),
                 "head": ["Person", "Route", "Appraiser", "HOD"] + (["Second HOD"] if cols2 else []) + ["What happens"],
                 "rows": [[(v["name"], v["eid"]), _gh_route_word(v["route"]), _ghl_appraiser_words(v),
                           _ghl_hod_words(v, _ghl_final_hod(v, {}))] + ([_ghl_hod2_words(v, {})] if cols2 else []) + [word[_ghl_change(v)]]
                          for v in valid[:15]], "more": max(0, len(valid) - 15)}]
    if ctx["private"]:
        sections.append({"title": "Skipped: private company", "note": "These rows are not loaded: Grade H Appraisal "
                         "does not cover them. They are counted here and in the final preview.",
                         "head": ["Employee ID", "Company"], "rows": [[p["eid"], p["company"] or ""]
                                                                    for p in ctx["private"][:10]],
                         "more": max(0, len(ctx["private"]) - 10)})
    decide = []
    rt = [v for v in valid if ("route:" + v["eid"], "route") in _ghl_ask(v)]
    ap = [v for v in valid if ("appr:" + v["eid"], "appr") in _ghl_ask(v)]
    hd = [v for v in valid if ("hod:" + v["eid"], "hod") in _ghl_ask(v)]
    h2 = [v for v in valid if ("hod2:" + v["eid"], "hod2") in _ghl_ask(v)]
    if rt:
        decide.append({"title": "Their route changes and they have started (%d)" % len(rt),
                       "why": "Change it: they go on the file's route; what they entered stays on record but no longer "
                              "counts. Keep it: they stay on the route they are on now.",
                       "options": [("change", "Change their route"), ("keep", "Keep their route")],
                       "head": ["Person", "Route now", "Route in the file"],
                       "items": [{"key": "route:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                                  "cells": [(v["name"], v["eid"]), _gh_route_word(v["ex"]["route"]),
                                            _gh_route_word(v["route"])]} for v in rt]})
    if ap:
        decide.append({"title": "The file names a different appraiser from the one set now (%d)" % len(ap),
                       "why": "Use the file's: the appraiser changes. Keep the one set now: it stays.",
                       "options": [("file", "Use the file's appraiser"), ("keep", "Keep the one set now")],
                       "head": ["Person", "In the file"],
                       "items": [{"key": "appr:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                                  "cells": [(v["name"], v["eid"]), v["appraiser_name"]]} for v in ap]})
    if hd:
        decide.append({"title": "The file names a different HOD from the one set now (%d)" % len(hd),
                       "why": "Use the file's: their Grade H HOD changes. Keep the one set now: it stays.",
                       "options": [("file", "Use the file's HOD"), ("keep", "Keep the one set now")],
                       "head": ["Person", "HOD in the file"],
                       "items": [{"key": "hod:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                                  "cells": [(v["name"], v["eid"]), v["hod_name"]]} for v in hd]})
    if h2:
        decide.append({"title": "The file's second HOD differs from the one set now (%d)" % len(h2),
                       "why": "Use the file's: their second HOD changes (or is taken away where the cell is blank); the HODs' bands already set stay. "
                              "Keep the one set now: it stays.",
                       "options": [("file", "Use the file's second HOD"), ("keep", "Keep the one set now")],
                       "head": ["Person", "Second HOD now", "In the file"],
                       "items": [{"key": "hod2:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                                  "cells": [(v["name"], v["eid"]), _ghl_hod2_name_now(db, v), v["hod2_name"] or "None: take it away"]} for v in h2]})
    return {"tiles": tiles, "sections": sections, "decide": decide,
            "fp": [(v["eid"], v["uid"], v["route"], v["appraiser_id"], v["sup_name"], v["ex"]["id"] if v["ex"] else 0,
                    v["ex"]["route"] if v["ex"] else "", v["ex"]["appraiser_id"] if v["ex"] else 0, v["progress"],
                    v["hod_id"], v["ex"]["hod_user_id"] if v["ex"] else 0, v["hod2_id"], v["split"], v["mode2"],
                    v["ex"]["hod2_user_id"] if v["ex"] else 0, v["ex"]["hod_split"] if v["ex"] else 0)
                   for v in valid] + [("private", p["eid"]) for p in ctx["private"]]}


def _ghl_hod2_words(v, decisions):
    """The second HOD a row ends with, in words ('Name, 60 : 40', or a dash)."""
    h2, sp = _ghl_final_hod2(v, decisions)
    if not h2:
        return "–"
    nm = v["hod2_name"] if h2 == v["hod2_id"] else "the one set now"
    return "%s, %d : %d" % (nm, sp or 50, 100 - (sp or 50))


def _ghl_hod2_name_now(db, v):
    r = db.execute("SELECT full_name FROM users WHERE id=?", (v["ex"]["hod2_user_id"],)).fetchone() if v["ex"] and v["ex"]["hod2_user_id"] else None
    return r["full_name"] if r else ""


def _ghl_says(v, decisions):
    ch = _ghl_change(v)
    route, appr = _ghl_final(v, decisions)
    if ch == "added":
        return "Added, %s route" % _gh_route_word(route)
    if ch == "same":
        return "No change"
    kept = [k for k in ("route:" + v["eid"], "appr:" + v["eid"], "hod:" + v["eid"], "hod2:" + v["eid"]) if decisions.get(k) == "keep"]
    return "Changed, %s route%s" % (_gh_route_word(route), ("; kept what is set now (%d)" % len(kept)) if kept else "")


def _ghl_after(db, me, ctx, decisions):
    valid = ctx["valid"]
    kinds = {"added": 0, "updated": 0, "same": 0}
    for v in valid:
        kinds[_ghl_change(v)] += 1
    tiles = [(kinds["added"], "added", "#2f64d6"), (kinds["updated"], "changed", "#e0a84a"),
             (kinds["same"], "no change", "#9aa1b5"), (len(ctx["private"]), "private company, skipped", "#d0716a")]
    cols2 = bool(ctx.get("cols2"))
    if cols2:
        fin2 = [_ghl_final_hod2(v, decisions)[0] for v in valid]
        tiles += [(sum(1 for x in fin2 if x), "HOD shared (two HODs)", "#6a55b8"),
                  (sum(1 for v, x in zip(valid, fin2) if v["ex"] and v["ex"]["hod2_user_id"] and not x), "second HOD removed", "#d0716a")]
    return {"lede": "%d %s on the Grade H list from this file, %d private-company %s skipped." % (
        len(valid), "person" if len(valid) == 1 else "people", len(ctx["private"]),
        "row" if len(ctx["private"]) == 1 else "rows"), "tiles": tiles,
            "table_title": "Each person after the import", "head": ["Person", "Route", "Appraiser", "HOD"] + (["Second HOD"] if cols2 else []) + ["What happens"],
            "rows": [[(v["name"], v["eid"]), _gh_route_word(_ghl_final(v, decisions)[0]),
                      _ghl_appraiser_words(v, _ghl_final(v, decisions)[1]), _ghl_hod_words(v, _ghl_final_hod(v, decisions))]
                     + ([_ghl_hod2_words(v, decisions)] if cols2 else []) + [_ghl_says(v, decisions)] for v in valid[:30]],
            "more": max(0, len(valid) - 30),
            "confirm": "Put %d %s on the Grade H list for %s (%d added, %d changed)? %d private-company %s skipped. The "
                       "backup taken first is the way back." % (
                           len(valid), "person" if len(valid) == 1 else "people", ctx["cyc"]["name"], kinds["added"],
                           kinds["updated"], len(ctx["private"]), "row is" if len(ctx["private"]) == 1 else "rows are")}


def _ghl_apply(db, me, ctx, decisions):
    cid = ctx["cyc"]["id"]
    added = changed = same = 0
    for v in ctx["valid"]:
        ch = _ghl_change(v)
        route, appr = _ghl_final(v, decisions)
        hod = _ghl_final_hod(v, decisions)   # the Grade H HOD only: users.hod_id (the main review's) is never written here
        hod2, split2 = _ghl_final_hod2(v, decisions)   # the second HOD and the split (2026-11-03)
        if ch == "same":
            same += 1
            continue
        if v["ex"]:
            db.execute("UPDATE gradeh_people SET route=?, appraiser_id=?, hr_supervisor_employee_id=?, "
                       "hr_supervisor_name=?, user_id=?, hod_user_id=?, hod2_user_id=?, hod_split=?, private_company=0, updated_at=datetime('now') WHERE id=?",
                       (route, appr, v["sup_eid"] or None, v["sup_name"] or None, v["uid"], hod, hod2, split2 if hod2 else None, v["ex"]["id"]))
            if v["ex"]["hod2_user_id"] and hod2 != v["ex"]["hod2_user_id"]:   # the old second HOD leaves: bands already agreed stay (one-HOD place)
                _gh_hod_ticks_fold(db, cid, v["ex"]["id"], hod or gradeh_hod_of(db, dict(v["ex"], hod_user_id=hod)))
            changed += 1
        else:
            db.execute("INSERT INTO gradeh_people(cycle_id, employee_id, user_id, route, appraiser_id, "
                       "hr_supervisor_employee_id, hr_supervisor_name, hod_user_id, hod2_user_id, hod_split, private_company) VALUES (?,?,?,?,?,?,?,?,?,?,0)",
                       (cid, v["eid"], v["uid"], route, appr, v["sup_eid"] or None, v["sup_name"] or None, hod, hod2, split2 if hod2 else None))
            added += 1
    db.commit()
    kept = [k.split(":", 1)[1] for k, o in decisions.items() if o == "keep" and k.split(":", 1)[0] in ("route", "appr", "hod", "hod2")]
    log_activity(db, me["id"], "gradeh_import_list", "%s: %d added, %d changed, %d unchanged, %d private-company rows "
                 "skipped%s" % (ctx["cyc"]["name"], added, changed, same, len(ctx["private"]),
                                ("; the super admin kept what was set for %d (%s)" % (len(kept), ", ".join(kept[:40])))
                                if kept else ""))
    return {"summary": "%d added and %d changed on the Grade H list; %d unchanged; %d private-company rows skipped." % (
        added, changed, same, len(ctx["private"])),
            "lines": ["%d kept as they were, as you answered." % len(kept)] if kept else []}


def _ghl_downloads(db, me, ctx, decisions, what):
    c2 = bool(ctx.get("cols2"))
    if what == "changes":
        return "changes", ["Employee ID", "Name", "Route", "Appraiser", "HOD"] + (["Second HOD"] if c2 else []) + ["Change"], [
            [v["eid"], v["name"], _gh_route_word(v["route"]), _ghl_appraiser_words(v), _ghl_hod_words(v, _ghl_final_hod(v, {}))]
            + ([_ghl_hod2_words(v, {})] if c2 else []) + [_ghl_change(v)]
            for v in ctx["valid"]] + [[p["eid"], "", "", "", ""] + (["" ] if c2 else []) + ["Skipped: private company"] for p in ctx["private"]]
    return "final-preview", ["Employee ID", "Name", "Route", "Appraiser", "HOD"] + (["Second HOD"] if c2 else []) + ["What happens"], [
        [v["eid"], v["name"], _gh_route_word(_ghl_final(v, decisions)[0]),
         _ghl_appraiser_words(v, _ghl_final(v, decisions)[1]), _ghl_hod_words(v, _ghl_final_hod(v, decisions))]
        + ([_ghl_hod2_words(v, decisions)] if c2 else []) + [_ghl_says(v, decisions)] for v in ctx["valid"]] + [
        [p["eid"], "", "", "", ""] + (["" ] if c2 else []) + ["Skipped: private company"] for p in ctx["private"]]


_imp_register(
    GRADEH_LIST_KIND, page="admin_gradeh_import_list", dl="admin_gradeh_import_list_check", file="grade-h-list",
    load=_ghl_load, changes=_ghl_changes, after=_ghl_after, apply=_ghl_apply, downloads=_ghl_downloads,
    look=(("no_appraiser", "person has no appraiser", "people have no appraiser",
           "Nobody can appraise them until an appraiser is set (People & progress) or their line manager is added."),
          ("company", "company differs from OneHR's", "companies differ from OneHR's",
           "The company comes from OneHR; the file's is only checked against it."),
          ("no_lines", "KPI-route person has no KPI lines yet", "KPI-route people have no KPI lines yet",
           "Import the Strada8 KPI lines next, or they can't enter achievement."),
          ("has_lines", "Line-manager-route person has KPI lines loaded", "Line-manager-route people have KPI lines loaded",
           "The lines stay but go unused on that route."),
          ("hod_bg", "HOD is in a different business group", "HODs are in a different business group",
           "I've looked at these: a Grade H HOD from another business group is allowed, so it goes on as the file says."),
          ("hod_norole", "HOD holds a BU CEO or BG CEO seat", "HODs hold a BU CEO or BG CEO seat",
           "A BU CEO or BG CEO is no Grade H HOD: their people go to the BU CEO instead. A calibrator of the normal review is an HOD here."),
          ("hod2_norole", "second HOD holds a BU CEO or BG CEO seat", "second HODs hold a BU CEO or BG CEO seat",
           "A BU CEO or BG CEO holds no Grade H HOD role: the HOD takes 100% of the person."),
          ("hod2_bg", "second HOD is in a different business group", "second HODs are in a different business group",
           "I've looked at these: a second Grade H HOD from another business group is allowed, so it goes on as the file says.")),
    look_skips=("company",),
    fix_kinds=(("The template's example row", r"example row"), ("No Employee ID", r"no Employee ID"),
               ("Unknown Employee ID", r"no employee with"), ("Someone who has left", r"has left"),
               ("Not Grade H in OneHR", r"isn't Grade H"), ("In the file twice", r"more than once"),
               ("A route that isn't KPI or Line manager", r"Route must be"),
               ("An appraiser OneHR can't use", r"appraiser|own appraiser"),
               ("A second HOD OneHR can't use, or a split that doesn't fit", r"second HOD|HOD split"), ("An HOD OneHR can't use", r"\bHOD\b"),
               ("Not a Year-End cycle", r"Year-End|active cycle"),
               ("An empty file", r"no rows")),
    checks=("an Employee ID nobody has, someone who has left, someone who isn't Grade H in OneHR, a route that isn't KPI or "
            "Line manager, an appraiser or HOD OneHR doesn't know (or who has left, or a demo login) or the person themselves, a second HOD who is the HOD "
            "or the person, a HOD split that isn't 10 to 90 in 10s or has no second HOD, someone twice, the template's "
            "example row, no active Year-End cycle. Rows for a private company are skipped and counted.",
            "someone with no appraiser and no line manager, a company that differs from OneHR's, a KPI-route person with "
            "no KPI lines yet, an HOD or second HOD in another business group or one who holds a BU CEO or BG CEO seat."))


# ---- the Strada8 KPI lines import ---------------------------------------------------------------------------------
def _gkl_load(db, me, meta, data):
    errors, look = [], {"to_kpi": [], "has_lines": []}
    cyc, cerr = _gh_cycle_error(db)
    if cerr:
        errors.append({"row": 0, "eid": "", "why": cerr})
    cid = cyc["id"] if cyc else 0
    recs = list(enumerate(_read_records(meta["filename"], data), start=2))
    eids = [_pick(r, "employee id", "eid", "id", "staff id", "employee no") for _i, r in recs]
    users = _gh_users(db, eids)
    people = {r["employee_id"]: dict(r) for r in db.execute(
        "SELECT * FROM gradeh_people WHERE cycle_id=? AND private_company=0", (cid,))}
    by = {}
    order = []
    blank = rows = 0
    for i, rec in recs:
        eid = _pick(rec, "employee id", "eid", "id", "staff id", "employee no")
        name = " ".join(_pick(rec, "kpi name", "kpi").split())
        w_raw = _pick(rec, "weight %", "weight", "weightage", "weight percent")
        sc_raw = " ".join(_pick(rec, "group scale", "scale", "group").split()).upper()
        if eid and not (name or w_raw or sc_raw):
            blank += 1
            continue
        if not eid and not (name or w_raw):
            continue
        rows += 1
        err = lambda why, e=eid, n=i: errors.append({"row": n, "eid": e or "", "why": why})  # noqa: E731
        if not eid:
            err("A KPI line (%s) has no Employee ID." % (name or "no name"))
            continue
        if eid.upper().startswith("EXAMPLE-"):
            err("%s: this is the template's example row: replace it with a real Employee ID." % eid)
            continue
        if not name:
            err("%s: a line has no KPI name." % eid)
            continue
        w = _gh_weight(w_raw)
        if w is None:
            err("%s: the weight for %s must be a number above 0 and up to 100 (“%s”)." % (eid, name, w_raw))
            continue
        if sc_raw not in _GH_SCALE_WORDS:
            err("%s: the group scale for %s must be FIAMMA or SIGNATURE (“%s”)." % (eid, name, sc_raw))
            continue
        p = by.setdefault(eid, {"eid": eid, "lines": [], "rows": [], "scales": set()})
        if eid not in order:
            order.append(eid)
        if any(ln["name"].lower() == name.lower() for ln in p["lines"]):
            err("%s: the KPI %s is in the file more than once." % (eid, name))
            continue
        p["lines"].append({"name": name, "weight": w, "scale": _GH_SCALE_WORDS[sc_raw]})
        p["rows"].append(i)
        p["scales"].add(_GH_SCALE_WORDS[sc_raw])
    valid = []
    ex_lines = {}
    for r in db.execute("SELECT person_id, kpi_name, weight, group_scale FROM gradeh_kpi_lines WHERE cycle_id=? "
                        "ORDER BY person_id, sort_order, id", (cid,)):
        ex_lines.setdefault(r["person_id"], []).append((r["kpi_name"], round(r["weight"], 2), r["group_scale"]))
    shared_old = {}   # a KPI line that shares a unit's BU KPI result (2026-11-03): its name key, by person
    shared_scale = {}   # ... and the scale it is on, by (person, name key): a file may not move it between a % scale and a rating (2026-11-06)
    for r in db.execute("SELECT person_id, kpi_name, group_scale FROM gradeh_kpi_lines WHERE cycle_id=? AND bu_kpi_id IS NOT NULL", (cid,)):
        shared_old.setdefault(r["person_id"], []).append(r["kpi_name"])
        shared_scale[(r["person_id"], _kpi_key(r["kpi_name"]))] = r["group_scale"]
    prog = _gh_progress(db, cid, [people[e]["id"] for e in order if e in people])
    for eid in order:
        p = by[eid]
        first = p["rows"][0] if p["rows"] else 0
        u = users.get(eid)
        pr = people.get(eid)
        if not pr:
            errors.append({"row": first, "eid": eid, "why": "%s: isn't on the Grade H list for %s (import the list first)."
                           % (eid, cyc["name"] if cyc else "this cycle")})
            continue
        # replacing a person's lines would drop a link to a BU KPI: the link is KEPT when the file has the same line (name, case aside), else the
        # person is refused, never a link lost silently
        lost = [n_ for n_ in shared_old.get(pr["id"], []) if _kpi_key(n_) not in {_kpi_key(ln["name"]) for ln in p["lines"]}]
        if lost:
            errors.append({"row": first, "eid": eid, "why": "%s: the line %s follows a BU KPI's result and is not in the file. Keep that line in the "
                           "file, or take it off the BU KPI first." % (eid, lost[0])})
            continue
        moved = [ln["name"] for ln in p["lines"] if (pr["id"], _kpi_key(ln["name"])) in shared_scale
                 and (shared_scale[(pr["id"], _kpi_key(ln["name"]))] in GRADEH_BU_RATED_SCALES) != (ln["scale"] in GRADEH_BU_RATED_SCALES)]
        if moved:
            errors.append({"row": first, "eid": eid, "why": "%s: the line %s follows a BU KPI's result, which cannot give it a different kind of scale (a %% "
                           "scale or a rating). Take it off the BU KPI first, or keep its scale." % (eid, moved[0])})
            continue
        total = round(sum(ln["weight"] for ln in p["lines"]), 2)
        if abs(total - 100) > 0.01:
            errors.append({"row": first, "eid": eid, "why": "%s: weights total %s%%, they must total 100%%." % (
                eid, _gh_fmt_w(total))})
            continue
        if len(p["scales"]) > 1:
            errors.append({"row": first, "eid": eid, "why": "%s: lines mix group scales (%s): one person has one scale." % (
                eid, ", ".join(sorted(p["scales"])))})
            continue
        new = [(ln["name"], round(ln["weight"], 2), ln["scale"]) for ln in p["lines"]]
        old = ex_lines.get(pr["id"], [])
        v = {"eid": eid, "uid": pr["user_id"], "pid": pr["id"], "name": u["full_name"] if u else eid,
             "lines": p["lines"], "rows": p["rows"], "total": total, "scale": next(iter(p["scales"])),
             "route": pr["route"], "had": len(old), "same": old == new, "progress": bool(prog.get(pr["id"]))}
        valid.append(v)
        if pr["route"] != "A":
            look["to_kpi"].append({"row": first, "eid": eid, "rows": p["rows"],
                                   "detail": "%s: on the Line manager route now: they move to the KPI route" % eid})
        if old and not v["same"]:
            look["has_lines"].append({"row": first, "eid": eid, "rows": p["rows"],
                                      "detail": "%s: already has %d KPI lines: they are replaced" % (eid, len(old))})
    if not rows and not errors:
        errors.append({"row": 0, "eid": "", "why": "That file has no rows to apply."})
    return {"errors": errors, "rows": rows, "valid": valid, "look": look, "cyc": cyc, "blank_rows": blank}


def _gkl_asks(v):
    return v["progress"] and not v["same"] and (v["had"] or v["route"] != "A")


def _gkl_leave(v, decisions):
    return _gkl_asks(v) and decisions.get("kpi:" + v["eid"]) == "leave"


def _gkl_says(v, decisions):
    if v["same"] and v["route"] == "A":
        return "No change"
    if _gkl_leave(v, decisions):
        return "Left as it is"
    if v["same"]:
        return "Route becomes KPI; lines the same"
    return "%d line%s %s%s" % (len(v["lines"]), "" if len(v["lines"]) == 1 else "s",
                               "replace %d" % v["had"] if v["had"] else "added",
                               "; route becomes KPI" if v["route"] != "A" else "")


def _gkl_changes(db, me, ctx, decisions):
    valid = ctx["valid"]
    n_new = sum(1 for v in valid if not v["had"])
    n_chg = sum(1 for v in valid if v["had"] and not v["same"])
    n_same = sum(1 for v in valid if v["same"] and v["route"] == "A")
    tiles = [(len(valid), "people with KPI lines", "#2f64d6"), (n_new, "getting lines for the first time", "#1a7a54"),
             (n_chg, "having their lines replaced", "#e0a84a"), (n_same, "no change", "#9aa1b5")]
    sections = [{"title": "Each person's lines", "dl": "changes", "note": "Every person's weights total 100%.",
                 "head": ["Person", "Lines", "Scale", "Weights", "What happens"],
                 "rows": [[(v["name"], v["eid"]), len(v["lines"]), v["scale"],
                           " + ".join(_gh_fmt_w(ln["weight"]) for ln in v["lines"]) + " = " + _gh_fmt_w(v["total"]),
                           _gkl_says(v, {})] for v in valid[:15]], "more": max(0, len(valid) - 15)}]
    asked = [v for v in valid if _gkl_asks(v)]
    decide = [{"title": "They have started, and their lines or route change (%d)" % len(asked),
               "why": "Replace: their KPI lines and route become the file's, and the achievement they entered for the old "
                      "lines is cleared. Leave them: their lines and route stay as they are.",
               "options": [("replace", "Replace their lines"), ("leave", "Leave them")],
               "head": ["Person", "Lines now", "Lines in the file"],
               "items": [{"key": "kpi:" + v["eid"], "label": "%s (%s)" % (v["name"], v["eid"]),
                          "cells": [(v["name"], v["eid"]), v["had"], len(v["lines"])]} for v in asked]}] if asked else []
    return {"tiles": tiles, "sections": sections, "decide": decide,
            "fp": [(v["eid"], v["pid"], v["had"], v["same"], v["progress"], v["route"],
                    [(ln["name"], ln["weight"], ln["scale"]) for ln in v["lines"]]) for v in valid]}


def _gkl_after(db, me, ctx, decisions):
    valid = ctx["valid"]
    go = [v for v in valid if not _gkl_leave(v, decisions) and not (v["same"] and v["route"] == "A")]
    left = [v for v in valid if _gkl_leave(v, decisions)]
    n_lines = sum(len(v["lines"]) for v in go if not v["same"])
    tiles = [(len(go), "people changed", "#2f64d6"), (n_lines, "KPI lines written", "#1a7a54"),
             (len(valid) - len(go) - len(left), "no change", "#9aa1b5")]
    if left:
        tiles.append((len(left), "left as they are", "#9aa1b5"))
    return {"lede": "%d %s with KPI lines in the file." % (len(valid), "person" if len(valid) == 1 else "people"),
            "tiles": tiles, "table_title": "Each person after the import", "head": ["Person", "Scale", "Total", "What happens"],
            "rows": [[(v["name"], v["eid"]), v["scale"], _gh_fmt_w(v["total"]) + "%", _gkl_says(v, decisions)]
                     for v in valid[:30]], "more": max(0, len(valid) - 30),
            "confirm": "Write %d KPI line%s for %d %s in %s%s? Each person's weights total 100%% and they go on the KPI "
                       "route. The backup taken first is the way back." % (
                           n_lines, "" if n_lines == 1 else "s", len(go), "person" if len(go) == 1 else "people",
                           ctx["cyc"]["name"], (", leaving %d as they are" % len(left)) if left else "")}


def _gkl_apply(db, me, ctx, decisions):
    cid = ctx["cyc"]["id"]
    # the weights rule again, at the writer: a person whose lines don't total 100% is refused, whatever the page said
    for v in ctx["valid"]:
        if abs(sum(ln["weight"] for ln in v["lines"]) - 100) > 0.01:
            raise ValueError("%s's weights total %s%%, not 100%%." % (v["eid"], _gh_fmt_w(
                sum(ln["weight"] for ln in v["lines"]))))
    people = lines = left = 0
    for v in ctx["valid"]:
        if _gkl_leave(v, decisions):
            left += 1
            continue
        if v["same"]:
            if v["route"] != "A":
                db.execute("UPDATE gradeh_people SET route='A', updated_at=datetime('now') WHERE id=?", (v["pid"],))
                people += 1
            continue
        links = {_kpi_key(r["kpi_name"]): (r["bu_kpi_id"], r["bu_pct"], r["bu_filled_at"], r["bu_filled_by"], r["bu_value"], r["bu_rating"]) for r in db.execute(
            "SELECT kpi_name, bu_kpi_id, bu_pct, bu_filled_at, bu_filled_by, bu_value, bu_rating FROM gradeh_kpi_lines WHERE person_id=? AND cycle_id=? "
            "AND bu_kpi_id IS NOT NULL", (v["pid"], cid))}
        db.execute("DELETE FROM gradeh_kpi_entries WHERE person_id=? AND cycle_id=?", (v["pid"], cid))
        db.execute("DELETE FROM gradeh_kpi_lines WHERE person_id=? AND cycle_id=?", (v["pid"], cid))
        for n, ln in enumerate(v["lines"], start=1):
            lk = links.pop(_kpi_key(ln["name"]), (None, None, None, None, None, None))   # the link to a BU KPI and its shared result (a % or a rating) carry over to the same line
            db.execute("INSERT INTO gradeh_kpi_lines(cycle_id, person_id, kpi_name, weight, group_scale, sort_order, bu_kpi_id, bu_pct, bu_filled_at, "
                       "bu_filled_by, bu_value, bu_rating) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)", (cid, v["pid"], ln["name"], ln["weight"], ln["scale"], n) + lk)
            lines += 1
        if links:   # the preview refuses this; if the file changed under it, nothing is half-written
            raise ValueError("%s: a line that follows a BU KPI is not in the file." % v["eid"])
        db.execute("UPDATE gradeh_people SET route='A', updated_at=datetime('now') WHERE id=?", (v["pid"],))
        people += 1
    db.commit()
    kept = [v["eid"] for v in ctx["valid"] if _gkl_leave(v, decisions)]
    log_activity(db, me["id"], "gradeh_import_kpi", "%s: %d KPI lines for %d people (route KPI)%s" % (
        ctx["cyc"]["name"], lines, people, ("; the super admin left %d as they were (%s)" % (
            len(kept), ", ".join(kept[:40]))) if kept else ""))
    return {"summary": "%d KPI lines written for %d %s; every person's weights total 100%%." % (
        lines, people, "person" if people == 1 else "people"),
            "lines": ["%d left as they were, as you answered." % left] if left else []}


def _gkl_downloads(db, me, ctx, decisions, what):
    if what == "changes":
        return "changes", ["Employee ID", "Name", "KPI name", "Weight %", "Group scale"], [
            [v["eid"], v["name"], ln["name"], ln["weight"], ln["scale"]] for v in ctx["valid"] for ln in v["lines"]]
    return "final-preview", ["Employee ID", "Name", "Lines", "Total %", "What happens"], [
        [v["eid"], v["name"], len(v["lines"]), v["total"], _gkl_says(v, decisions)] for v in ctx["valid"]]


def _gkl_err_kind(why):
    """The quality step's heading for a refused row: a person whose weights miss 100% is named by the total (Weights total 85%,
    not 100%); every other kind is its fix_kinds label."""
    m = re.search(r"weights total ([\d.]+)%", why or "")
    if m:
        return "Weights total %s%%, not 100%%" % m.group(1)
    for label, pat in _GKL_KINDS:
        if re.search(pat, why or "", re.I):
            return label
    return "Other"


_GKL_KINDS = (("Not on the Grade H list", r"isn't on the Grade H"),
              ("The template's example row", r"example row"), ("A weight that isn't a number", r"weight for"),
              ("A group scale that isn't FIAMMA or SIGNATURE", r"group scale for"), ("Lines mixing scales", r"mix group"),
              ("A KPI twice", r"more than once"), ("No Employee ID or KPI name", r"no Employee ID|no KPI name"),
              ("Not a Year-End cycle", r"Year-End|active cycle"), ("An empty file", r"no rows"))

_imp_register(
    GRADEH_KPI_KIND, page="admin_gradeh_import_kpi", dl="admin_gradeh_import_kpi_check", file="grade-h-kpi-lines",
    load=_gkl_load, changes=_gkl_changes, after=_gkl_after, apply=_gkl_apply, downloads=_gkl_downloads,
    look=(("to_kpi", "person moves to the KPI route", "people move to the KPI route",
           "Loading KPI lines puts a person on the KPI route; they were on the Line manager route."),
          ("has_lines", "person already has KPI lines", "people already have KPI lines",
           "Their lines are replaced by the file's.")),
    err_kind=lambda why: _gkl_err_kind(why),
    fix_kinds=(("Not on the Grade H list", r"isn't on the Grade H"),
               ("The template's example row", r"example row"), ("A weight that isn't a number", r"weight for"),
               ("A group scale that isn't FIAMMA or SIGNATURE", r"group scale for"), ("Lines mixing scales", r"mix group"),
               ("A KPI twice", r"more than once"), ("No Employee ID or KPI name", r"no Employee ID|no KPI name"),
               ("Not a Year-End cycle", r"Year-End|active cycle"), ("An empty file", r"no rows")),
    checks=("a person's weights not totalling 100% (it names the total, for example 85%), a person not on the Grade H list, a "
            "weight that isn't a number above 0 and up to 100, a group scale that isn't FIAMMA or SIGNATURE, lines of one "
            "person on two scales, a KPI twice, the template's example row, no active Year-End cycle.",
            "a person who moves from the Line manager route to the KPI route, a person whose lines are replaced."))


# ---- the pages -----------------------------------------------------------------------------------------------------
def _gh_counts(db):
    cyc = active_cycle(db)
    cid = cyc["id"] if cyc else 0
    one = lambda sql, *a_: db.execute(sql, a_).fetchone()[0]  # noqa: E731
    return {"cycle": cyc, "offered": bool(cyc and gradeh_cycle_offered(cyc)),
            "on_list": one("SELECT COUNT(*) FROM gradeh_people WHERE cycle_id=? AND private_company=0", cid),
            "route_a": one("SELECT COUNT(*) FROM gradeh_people WHERE cycle_id=? AND private_company=0 AND route='A'", cid),
            "route_b": one("SELECT COUNT(*) FROM gradeh_people WHERE cycle_id=? AND private_company=0 AND route='B'", cid),
            "with_lines": one("SELECT COUNT(DISTINCT person_id) FROM gradeh_kpi_lines WHERE cycle_id=?", cid),
            "grade_h": one("SELECT COUNT(*) FROM users WHERE role!='admin' AND left_at IS NULL AND UPPER(TRIM(job_grade))='H'"),
            "a_no_lines": one("SELECT COUNT(*) FROM gradeh_people p WHERE p.cycle_id=? AND p.private_company=0 AND "
                              "p.route='A' AND NOT EXISTS (SELECT 1 FROM gradeh_kpi_lines l WHERE l.person_id=p.id)", cid)}


@app.route("/admin/gradeh/import/list", methods=["GET", "POST"])
@super_required
def admin_gradeh_import_list():
    """Grade H Appraisal > Imports > the Grade H list, in four steps (_imp_post): who is on it, their route and appraiser;
    rows for a private company are skipped and counted."""
    db, me = get_db(), current_user()
    if request.method == "POST":
        if (request.form.get("token") or "").strip():
            return _imp_post(GRADEH_LIST_KIND, db, me)
        if request.form.get("preview") == "1":
            return _imp_upload(GRADEH_LIST_KIND, db, me)
        flash("Choose the file first: it is checked in four steps before anything changes.", "error")
        return redirect(url_for("admin_gradeh_import_list"))
    v, done = _imp_get(GRADEH_LIST_KIND, db, me)
    return render_template("admin_gradeh_import_list.html", v=v, done=done, is_super=True, n=_gh_counts(db),
                           cols=GRADEH_LIST_IMPORT_COLUMNS)


