def _gh_missing_book(db, me, what, export, sheet, cols, people, how):
    """A who's-missing download for one of the two imports: its own columns first (the Employee ID filled, the rest blank),
    then Reference: columns that are not imported, and How to fill. Logged as an export."""
    mgr = _manager_names(db, [u.get("manager_id") for u in people])
    rows = [[u["employee_id"] or ""] + [""] * (len(cols) - 1) + [
        u.get("full_name") or "", display_bg(u.get("business_group") or "") or "", u.get("company") or "",
        u.get("department") or "", u.get("job_title") or "", u.get("job_grade") or "", mgr.get(u.get("manager_id"), "")]
        for u in sorted(people, key=lambda x: (x.get("business_group") or "", x.get("company") or "",
                                               x.get("full_name") or ""))]
    head = list(cols) + ["Reference: name", "Reference: business group", "Reference: business unit",
                         "Reference: department", "Reference: job title", "Reference: job grade",
                         "Reference: line manager"]
    bg, unit = _gh_dl_name_parts(me, people, infer=False)   # the Reports panel's picks name the file (2026-11-04), as for every download
    fname = gradeh_results_filename(bg or None, unit or None, export)
    cyc = active_cycle(db)
    log_activity(db, me["id"], "export", "%s: %s (%d people)" % (fname, what, len(rows)))
    about = [["Report", what], ["Cycle", cyc["name"] if cyc else ""],
             ["Scope", _export_scope_label(me)]] + _gh_dl_about() + [
            ["Generated (MYT)", _now_myt().strftime("%Y-%m-%d %H:%M")], ["Rows", len(rows)],
            ["What this is", "%s, in the columns of the import that fills them in. Never share it with staff." % what]]
    return _xlsx_response(fname, [(sheet, head, rows), ("How to fill", ["How to fill it in"], [[h] for h in how]),
                                  ("About", ["Item", "Detail"], about)])


def _gh_not_on_list(db, cid):
    """Grade H people in OneHR who aren't on this cycle's Grade H list, as user rows: the one rule behind the Not on the list
    download and the download panel's count of it."""
    return [dict(r) for r in db.execute(
        "SELECT * FROM users WHERE role!='admin' AND left_at IS NULL AND UPPER(TRIM(job_grade))='H' AND employee_id "
        "IS NOT NULL AND employee_id NOT IN (SELECT employee_id FROM gradeh_people WHERE cycle_id=?)", (cid,))]


def _gh_no_kpi_lines(db, cid):
    """KPI-route people on the list with no KPI line, as user rows: the one rule behind the No KPI lines download and the download
    panel's count of it."""
    return [dict(r) for r in db.execute(
        "SELECT u.* FROM gradeh_people p JOIN users u ON u.id=p.user_id WHERE p.cycle_id=? AND p.private_company=0 AND "
        "p.route='A' AND NOT EXISTS (SELECT 1 FROM gradeh_kpi_lines l WHERE l.person_id=p.id)", (cid,))]


_GH_MISSING_TAIL = ("Columns headed Reference: are there to help you; they aren't imported.",
                    "A row you leave as it is (only its Employee ID) is skipped on import, so you can import what you've "
                    "filled in and come back for the rest.")


