def gh_t(lang, key, **kw):
    """One string of the staff page in `lang` ('bm' | 'en'); {fields} filled from kw."""
    pair = GRADEH_STAFF_T[key]
    txt = pair[1] if lang == "bm" else pair[0]
    return txt.format(**kw) if kw else txt


# The look around (Chris, 2026-10-28): (id, CSS selector, the selector on a phone or None, string key stem, which step it belongs
# to or None). gradeh_staff.js runs them over the real page, only those whose element is on screen, numbered over those shown.
GRADEH_TOUR_STOPS = (
    ("steps", ".gh-steps-card", None, "tour_s1", None),
    ("kpis", ".gh-kpi", None, "tour_s2", "kpi_form"),
    ("send", "#gh-kpi > .gh-btn", None, "tour_s3", "kpi_open"),
    ("ask", ".gh-ask", ".gh-askcard", "tour_s4", None),
    ("acct", ".gh-acct-btn", None, "tour_s5", None),
)


def gradeh_tour(lang, v):
    """The look around's words and stops for this page, in the person's language: {"stops": [...], "ui": {...}}. The server
    leaves out a stop the step has no element for (no KPI stops once the KPIs are sent); the script also skips one that is not
    on screen. Words only: it reads nothing about the person."""
    have = {"kpi_form": bool(v.get("kpi_lines")), "kpi_open": bool(v.get("kpi_lines")) and bool(v.get("kpi_open"))}
    stops = [{"id": sid, "sel": sel, "sel_phone": ph, "t": gh_t(lang, key + "_t"), "x": gh_t(lang, key)}
             for sid, sel, ph, key, need in GRADEH_TOUR_STOPS if need is None or have.get(need)]
    ui = {k: gh_t(lang, "tour_" + k) for k in ("k", "next", "done", "skip", "rest")}
    ui["sub"] = gh_t(lang, "tour_h")
    return {"stops": stops, "ui": ui}


def _gh_myt(utc_raw):
    """A stored UTC 'YYYY-MM-DD HH:MM[:SS]' as a MYT datetime, or None."""
    dt = _parse_when(utc_raw)
    return dt + timedelta(hours=8) if dt else None


def _gh_time(dt, lang):
    h12 = (dt.hour % 12) or 12
    if lang == "bm":
        part = "pagi" if dt.hour < 12 else "tengah hari" if dt.hour < 14 else "petang" if dt.hour < 19 else "malam"
    else:
        part = "am" if dt.hour < 12 else "pm"
    return "%d:%02d %s" % (h12, dt.minute, part)


def gh_when(dt, lang, time=True, year=True):
    """'18 Nov 2026, 11:59 pm' / '18 Nov 2026, 11:59 malam' (a datetime already in MYT); '' for None."""
    if not dt:
        return ""
    out = "%d %s" % (dt.day, _GH_MONTHS[lang][dt.month - 1])
    if year:
        out += " %d" % dt.year
    return out + (", " + _gh_time(dt, lang) if time else "")


def _gh_pct_str(v):
    """96.0 -> '96', 96.5 -> '96.5'."""
    if v is None:
        return ""
    return ("%.2f" % float(v)).rstrip("0").rstrip(".")


def gradeh_staff_person(db, u, cycle_id=None):
    """This person's Grade H row for the cycle (the active one by default), or None: the module is on for the cycle, they
    are not an admin, they are on the imported list and the row is not a private-company skip."""
    if not gradeh_on() or not u or is_admin(u):
        return None
    cid = cycle_id or active_cycle_id(db)
    if not cid or not gradeh_module_on(db, cid):
        return None
    return db.execute("SELECT * FROM gradeh_people WHERE cycle_id=? AND user_id=? AND private_company=0",
                      (cid, u["id"])).fetchone()


def gradeh_window_closed(db, cell, cycle_id=None, now=None):
    """None while this part is open, else ('closed' | 'not_open', the stored MYT date-time, None when the part has no start
    date). THE window check for the staff and line manager pages: window_state, so a Grade H part follows the cycle's
    open_by_date like every other part (2026-10-31): undated on a cycle that opens by date = not open; undated on one
    that does not = open all cycle."""
    st = window_state(db, cell, cycle_id, now)
    if st == "open":
        return None
    opens, closes = window_dates(db, cell, cycle_id)
    return (st, opens if st == "not_open" else closes)


def gradeh_parse_pct(raw):
    """A typed achievement: (float or None for blank, None) or (None, 'range'). Takes 96, 96.5, 96,5 and 96%; at most 2
    decimals; 0 to GRADEH_PCT_MAX."""
    t = str(raw if raw is not None else "").strip().replace(",", ".")
    if t.endswith("%"):
        t = t[:-1].rstrip()
    if t == "":
        return None, None
    if not re.fullmatch(r"\d{1,4}(\.\d{1,2})?", t):
        return None, "range"
    v = float(t)
    return (v, None) if v <= GRADEH_PCT_MAX else (None, "range")


def _gh_lines(db, person):
    return db.execute(
        "SELECT l.id, l.kpi_name, l.weight, l.group_scale, l.bu_kpi_id, l.bu_pct, l.bu_rating, l.bu_filled_at, e.staff_pct, e.lm_pct, e.lm_reason, e.lm_rating "
        "FROM gradeh_kpi_lines l LEFT JOIN gradeh_kpi_entries e ON e.line_id=l.id "
        "WHERE l.cycle_id=? AND l.person_id=? ORDER BY l.sort_order, l.id", (person["cycle_id"], person["id"])).fetchall()


def _gh_appraisal(db, person):
    return db.execute("SELECT * FROM gradeh_appraisals WHERE cycle_id=? AND person_id=?",
                      (person["cycle_id"], person["id"])).fetchone()


def gradeh_staff_deemed_for(db, person, now=None):
    """The lazy, idempotent deemed-acknowledgement step for this person alone (documented in piece 3's notes): marks their
    submitted, unacknowledged appraisal once its deadline has passed. Commits only when it marked something."""
    n = gradeh_apply_deemed(db, person["cycle_id"], now=now, person_id=person["id"])
    if n:
        db.commit()
    return n


def gradeh_staff_state(db, person):
    """Where this person is on their page: {"step": 'kpi'|'wait'|'ack'|'done'|'final', "app": row|None, "kind": None|'self'|'deemed'
    |'person', "route": 'A'|'B', "lines": rows, "sent": bool}. Reads only. 'final' (Chris 2026-10-30, "Show final result"): the
    person's unit is released and their line manager never submitted, whatever the KPI state: there is no line manager appraisal to
    read or acknowledge, so no deadline, no reminder and no deemed step; the page shows the released band. A submitted appraisal
    keeps 'ack' / 'done' even after release. Taking a release back puts the person on 'kpi' / 'wait' again."""
    app_row = _gh_appraisal(db, person)
    lines = _gh_lines(db, person) if person["route"] == "A" else []
    sent = bool(app_row and app_row["staff_submitted_at"])
    kind = None
    if app_row and app_row["lm_submitted_at"]:
        kind = ("self" if app_row["acknowledged_at"] else "person" if app_row["ack_in_person"]
                else "deemed" if app_row["deemed_at"] else None)
        step = "done" if kind else "ack"
    elif gradeh_is_released(db, person["cycle_id"], person["id"]):
        step = "final"   # the unit is released and the line manager never submitted: the pinned band is the result, nothing to acknowledge
    elif person["route"] == "A" and not sent:
        step = "kpi"
    else:
        step = "wait"
    return {"step": step, "app": app_row, "kind": kind, "route": person["route"], "lines": lines, "sent": sent,
            "dis": gradeh_is_disagreed(app_row)}


def gradeh_staff_deadline(db, person, st=None):
    """The one date this person's page is waiting on them for, as ('kpi' | 'ack', a MYT datetime), or None. THE reader of it:
    the page's "Now . by 15 Nov" line and the bar's deadline reminder both call this, so they can never differ.
    KPI step (Route A, nothing sent yet), window open, a close date set -> the KPI window's close; the acknowledge step ->
    the deemed-acknowledgement deadline. Anything else (waiting, done, final, a closed or not-yet-open window, no date) -> None.
    Reads only."""
    st = st or gradeh_staff_state(db, person)
    if st["step"] == "kpi" and person["route"] == "A" and not st["sent"]:
        if gradeh_window_closed(db, GRADEH_CELL_KPI, person["cycle_id"]):
            return None
        _o, closes = window_dates(db, GRADEH_CELL_KPI, person["cycle_id"])
        dt = _parse_when(closes)
        return ("kpi", dt) if dt else None
    if st["step"] == "ack" and st["app"] and st["app"]["lm_submitted_at"]:
        dt = _gh_myt(gradeh_deemed_deadline(db, person["cycle_id"], st["app"]["lm_submitted_at"]))
        return ("ack", dt) if dt else None
    return None


def _gh_form_values(person, lines, form):
    """{line_id: raw text} from a posted form (fields k_<line id>). A field for a line that is not this person's is a refusal
    (None returned): nothing of that request is saved."""
    mine = {l["id"] for l in lines}
    out = {}
    for k, v in form.items():
        if not k.startswith("k_"):
            continue
        try:
            lid = int(k[2:])
        except ValueError:
            return None
        if lid not in mine:
            return None
        out[lid] = v
    return out


def _gh_kpi_merge(lines, values):
    """(per-line value or None, first bad line or None): the submitted text over what is stored."""
    vals = {}
    for l in lines:
        if l["id"] in values:
            v, err = gradeh_parse_pct(values[l["id"]])
            if err:
                return None, l
            vals[l["id"]] = v
        else:
            vals[l["id"]] = l["staff_pct"]
    return vals, None


def gradeh_kpi_preview(db, u, values):
    """The server's weighted KPI result for what is typed now: (ok, percent or None, key). Never stored. None = not every
    KPI is filled in yet (key 'result_wait'). THE only place the weighted figure is worked out for the page."""
    person = gradeh_staff_person(db, u)
    if not person or person["route"] != "A":
        return False, None, "e_no_record"
    lines = _gh_lines(db, person)
    if not lines:
        return False, None, "no_lines"
    vals, bad = _gh_kpi_merge(lines, values)
    if bad is not None:
        return False, None, "e_range"
    if any(_gh_shared_wait(l) for l in lines):   # a shared line Group People has not filled: no total is printed
        return True, None, "result_wait_shared"
    if any(l["bu_kpi_id"] and l["group_scale"] in GRADEH_BU_RATED_SCALES for l in lines):
        return True, None, "result_rated_shared"   # a rating cannot be weighted into the person's own achievement %: no total is printed
    if any(vals[l["id"]] is None for l in lines if not l["bu_kpi_id"]):
        return True, None, "result_wait"
    try:
        return True, gradeh_weighted_achievement([(l["weight"], l["bu_pct"] if l["bu_kpi_id"] else vals[l["id"]]) for l in lines]), None
    except GradehRefusal:
        return False, None, "e_weights"


def gradeh_staff_save_kpi(db, u, values, note=None, send=False, now_utc=None):
    """THE writer of the person's KPI achievements (draft and send). `values` = {line id: typed text}. Returns (ok, key,
    args): a key of GRADEH_STAFF_T the caller says in the person's language. The person is always the signed-in one (never
    named by the request); a line that is not theirs, a figure out of range, the closed window, an already-sent record, or
    (send) a KPI left blank or weights that miss 100 refuses the WHOLE request: nothing is saved. A draft keeps what is
    typed (a blank clears that line); a send also stores the note and ends the person's part."""
    person = gradeh_staff_person(db, u)
    if not person:
        return False, "e_no_record", {}
    if person["route"] != "A":
        return False, "e_not_route", {}
    cid = person["cycle_id"]
    lines = _gh_lines(db, person)
    if not lines:
        return False, "no_lines", {}
    if values is None:   # a field for a line that is not theirs
        return False, "e_no_record", {}
    if any(l["bu_kpi_id"] and l["id"] in values for l in lines):   # a line that shares a unit's result is Group People's: no figure of theirs is kept (2026-11-03)
        return False, "e_shared", {}
    st = gradeh_staff_state(db, person)
    if st["step"] == "final":   # the unit is released: the result is final, nothing of theirs changes now
        return False, "e_final", {}
    if st["sent"] or st["app"] and st["app"]["lm_submitted_at"]:
        return False, "e_sent", {}
    w = gradeh_window_closed(db, GRADEH_CELL_KPI, cid)
    if w:
        return False, ("kpi_closed" if w[0] == "closed" else "kpi_not_open"), {"_when": _parse_when(w[1])}
    vals, bad = _gh_kpi_merge(lines, values)
    if bad is not None:
        return False, "e_range", {"max": GRADEH_PCT_MAX, "kpi": bad["kpi_name"], "line": bad["id"]}
    clean_note = None
    if note is not None:
        clean_note, nerr = gradeh_text_check(note, "note", required=False)
        if nerr:
            return False, "e_note", {}
    if send:
        miss = [l["kpi_name"] for l in lines if vals[l["id"]] is None and not l["bu_kpi_id"]]
        if miss:
            return False, "e_missing", {"kpi": ", ".join(miss)}
        try:   # the weights only: a shared line has no figure of theirs to send, Group People fills it (it is 0 here, never stored)
            gradeh_weighted_achievement([(l["weight"], 0 if l["bu_kpi_id"] else vals[l["id"]]) for l in lines])
        except GradehRefusal:
            return False, "e_weights", {}
    now = now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    for l in lines:
        if l["id"] not in values:
            continue   # not on this form: what is stored stays
        v = vals[l["id"]]
        cur = db.execute("UPDATE gradeh_kpi_entries SET staff_pct=?, staff_at=? WHERE line_id=?",
                         (v, now if v is not None else None, l["id"]))
        if not cur.rowcount:
            db.execute("INSERT INTO gradeh_kpi_entries(cycle_id, person_id, line_id, staff_pct, staff_at) VALUES (?,?,?,?,?)",
                       (cid, person["id"], l["id"], v, now if v is not None else None))
    db.execute("INSERT OR IGNORE INTO gradeh_appraisals(cycle_id, person_id) VALUES (?,?)", (cid, person["id"]))
    if clean_note is not None:
        db.execute("UPDATE gradeh_appraisals SET staff_note=?, updated_at=datetime('now') WHERE cycle_id=? AND person_id=?",
                   (clean_note or None, cid, person["id"]))
    if send:
        db.execute("UPDATE gradeh_appraisals SET staff_submitted_at=?, updated_at=datetime('now') "
                   "WHERE cycle_id=? AND person_id=?", (now, cid, person["id"]))
    db.commit()
    if send:
        log_activity(db, u["id"], "gradeh_kpi_send")
    return True, "ok_sent" if send else "ok_saved", {}


GRADEH_ACK_GATE_STAFF = {"not_ready": "e_ack_not_ready", "final": "e_ack_final", "done": "e_ack_done", "deemed": "e_ack_closed",
                         "closed": "e_ack_closed", "not_open": "e_ack_not_open"}
GRADEH_ACK_GATE_LM = {"not_ready": "m_ack_not_ready", "done": "m_ack_done", "deemed": "m_ack_deemed", "not_open": "m_ack_not_open"}


def _gh_ack_gate(db, person, now, as_staff):
    """THE gates of the acknowledge step, shared by acknowledging, telling us one does not agree, and the line manager recording
    either in person: None when it may be done now, else (code, args) with code one of GRADEH_ACK_GATE_STAFF / _LM. The deemed step
    runs first (committed when it marked someone), so a person past the deadline is marked and refused in one go. Refused: the line
    manager has not submitted (a released unit with no submit is 'final' on the staff side); already acknowledged, deemed or recorded
    in person (once only); the deemed deadline passed; the acknowledge window not open yet, and, on the staff side, closed. The line
    manager's side is not refused for a closed window (the deadline's own deemed step covers it)."""
    cid = person["cycle_id"]
    if gradeh_apply_deemed(db, cid, now=now, person_id=person["id"]):
        db.commit()
    a = _gh_appraisal(db, person)
    if not a or not a["lm_submitted_at"]:
        if as_staff and gradeh_is_released(db, cid, person["id"]):   # a released unit with no line manager appraisal: nothing to acknowledge
            return "final", {}
        return "not_ready", {}
    if a["acknowledged_at"] or a["ack_in_person"]:
        return "done", {}
    if a["deemed_at"]:
        return "deemed", {"_when": _gh_myt(a["deemed_at"])}
    if as_staff:
        dl = gradeh_deemed_deadline(db, cid, a["lm_submitted_at"])
        if dl and dl <= now:
            return "deemed", {"_when": _gh_myt(dl)}
    w = gradeh_window_closed(db, GRADEH_CELL_ACK, cid, now=_parse_when(now) + timedelta(hours=8))
    if w and (as_staff or w[0] == "not_open"):   # not yet open says when it opens; closed says when it closed
        return ("closed" if w[0] == "closed" else "not_open"), {"_when": _parse_when(w[1])}
    return None


def gradeh_staff_acknowledge(db, u, confirm, now_utc=None):
    """THE writer of the acknowledgement. (ok, key, args). Refused: not on the list; the line manager has not submitted; already
    acknowledged / deemed / acknowledged in person (once only); the box not ticked; the deemed deadline or the acknowledge
    window has passed (the gates are _gh_ack_gate, shared with "I do not agree"). The deemed step runs first, so a person past
    the deadline is marked and refused in one go."""
    person = gradeh_staff_person(db, u)
    if not person:
        return False, "e_no_record", {}
    cid = person["cycle_id"]
    now = now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    gate = _gh_ack_gate(db, person, now, True)
    if gate:
        return False, GRADEH_ACK_GATE_STAFF[gate[0]], gate[1]
    a = _gh_appraisal(db, person)
    if not confirm:
        return False, "e_ack_confirm", {}
    db.execute("UPDATE gradeh_appraisals SET acknowledged_at=?, updated_at=datetime('now') WHERE id=? "
               "AND acknowledged_at IS NULL", (now, a["id"]))
    db.commit()
    log_activity(db, u["id"], "gradeh_ack")
    return True, "ok_ack", {}


def gradeh_staff_disagree(db, u, reason, confirm, now_utc=None):
    """THE staff entry of "I do not agree" (the writer is gradeh_record_disagree, shared with the line manager's in-person route).
    (ok, key, args), a key of GRADEH_STAFF_T. The person is always the signed-in one."""
    person = gradeh_staff_person(db, u)
    if not person:
        return False, "e_no_record", {}
    return gradeh_record_disagree(db, person, u, reason, via="staff", now_utc=now_utc, confirm=bool(confirm))


# ---- "I do not agree" (Chris, 2 Nov 2026; plan OneHR/Grade H disagree plan 2026-11-02.md) --------------------------------
# At the acknowledge step a person may tell us they do not agree with their result, instead of acknowledging. It counts as their
# acknowledgement (final: no route takes it back; deemed no longer applies), opens one Get Help ticket for the SUPER ADMIN ONLY, and
# takes the person out of calibration: the line manager's band stands (or the super admin's Final change), enforced in the ONE band
# picker (_gh_band_pick), so no stray HOD / BU CEO row can move them. The reason they type goes to the ticket and to this row and to
# nobody else: not the line manager, HOD or BU CEO (pages, tools, emails), and NEVER to a model (the ticket agent refuses the topic).
GRADEH_DISAGREE_ABOUT = "gradeh_disagree"                 # help_requests.about (HELP_SYSTEM_ABOUT)
GRADEH_DISAGREE_LABEL = HELP_SYSTEM_ABOUT[GRADEH_DISAGREE_ABOUT]
GRADEH_DISAGREE_REASON_WORDS = GRADEH_REMARK_MAX_WORDS    # 300: over is refused, never trimmed


def gradeh_is_disagreed(row):
    """Did this appraisal row (gradeh_appraisals, or a calibration row carrying its disagree_at) record "I do not agree"?"""
    try:
        return bool(row is not None and row["disagree_at"])
    except (KeyError, IndexError):
        return False


def _gh_disagree_reason(reason):
    """(clean reason, None) or (None, code): code 'need' (blank), 'long' (over 300 words, refused never trimmed) or 'reword' (an
    instruction-like or file-pattern text, as every stored remark)."""
    t = " ".join((reason or "").split())
    if not t:
        return None, "need"
    if len(t.split()) > GRADEH_DISAGREE_REASON_WORDS:
        return None, "long"
    if ai_draft.screen_message(t) in ("injection", "not_allowed") or ai_draft.stored_text_refusal(t):
        return None, "reword"
    return t, None


def gradeh_record_disagree(db, person, actor, reason, via="staff", day=None, now_utc=None, confirm=True):
    """THE writer of "I do not agree", used by the staff route (`actor` = the person, via 'staff') and by the line manager's
    "Acknowledged in person" (`actor` = the line manager, via 'lm', `day` = the date of the talk). Returns (ok, key, args): a key of
    GRADEH_STAFF_T (staff) or GRADEH_LM_T (lm), said in the reader's language by the caller. Refused: every gate of the
    acknowledge step (_gh_ack_gate); on the staff side, the box not ticked (`confirm`); no reason; over 300 words; an unscreened text. In ONE transaction it sets acknowledged_at
    (staff) or the ack_in_person fields (lm) as acknowledging does, the disagree columns, and inserts the Get Help ticket (topic
    GRADEH_DISAGREE_ABOUT, detail = the reason, user = the person); then, outside the transaction, tells the super admins (no
    reason in the email) and writes the audit row (no reason in it). No route of the person's takes it back; only the super admin's Reopen
    clears it, with the acknowledgement it came with (the ticket stays). Never holds a write across the email."""
    now = now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    staff = via == "staff"
    gate = _gh_ack_gate(db, person, now, staff)
    if gate:
        return False, (GRADEH_ACK_GATE_STAFF if staff else GRADEH_ACK_GATE_LM)[gate[0]], gate[1]
    if staff and not confirm:
        return False, "e_ack_confirm", {}
    clean, bad = _gh_disagree_reason(reason)
    if bad:
        n = len(" ".join((reason or "").split()).split())
        return False, ("e_dis_" if staff else "m_dis_") + bad, {"n": n, "max": GRADEH_DISAGREE_REASON_WORDS}
    a = _gh_appraisal(db, person)
    cid, pid = person["cycle_id"], person["id"]
    try:
        # one transaction: the acknowledgement, the disagreement and the ticket together or none of them
        if staff:
            cur = db.execute("UPDATE gradeh_appraisals SET acknowledged_at=?, disagree_at=?, disagree_reason=?, disagree_by=?, "
                             "updated_at=datetime('now') WHERE id=? AND acknowledged_at IS NULL AND deemed_at IS NULL "
                             "AND ack_in_person=0 AND disagree_at IS NULL", (now, now, clean, actor["id"], a["id"]))
        else:
            cur = db.execute("UPDATE gradeh_appraisals SET ack_in_person=1, ack_in_person_on=?, ack_in_person_by=?, disagree_at=?, "
                             "disagree_reason=?, disagree_by=?, updated_at=datetime('now') WHERE id=? AND acknowledged_at IS NULL "
                             "AND deemed_at IS NULL AND ack_in_person=0 AND disagree_at IS NULL",
                             (day.isoformat(), actor["id"], now, clean, actor["id"], a["id"]))
        if not cur.rowcount:   # lost a race with an acknowledgement or a deemed step
            db.rollback()
            return False, GRADEH_ACK_GATE_STAFF["done"] if staff else GRADEH_ACK_GATE_LM["done"], {}
        rid = db.execute("INSERT INTO help_requests(user_id, about, detail, where_label) VALUES (?,?,?,?)",
                         (person["user_id"], GRADEH_DISAGREE_ABOUT, clean,
                          "My Appraisal" if staff else "Line manager, in person")).lastrowid
        db.execute("UPDATE gradeh_appraisals SET disagree_ticket_id=? WHERE id=?", (rid, a["id"]))
        db.commit()
    except Exception:
        db.rollback()
        raise
    log_activity(db, actor["id"], "gradeh_disagree", "person %d, ticket %s" % (pid, help_ref(rid)), target_user_id=person["user_id"])
    try:   # the email names the person and the ticket, never the reason; a failure never undoes the record
        who = db.execute("SELECT full_name, employee_id, business_group FROM users WHERE id=?", (person["user_id"],)).fetchone()
        _notify_super_admins(
            db, "Grade H: someone does not agree with their result (%s)" % help_ref(rid), "Someone does not agree with their result",
            ["%s (%s) told us they do not agree with their Grade H result%s. It is ticket <b>%s</b> in Ticketing, which only a super admin "
             "can open. Their result will not go to calibration."
             % (_em_esc(proper_name(who["full_name"]) if who else "A person"), _em_esc((who["employee_id"] if who else "") or ""),
                "" if staff else ", recorded in person by their line manager", help_ref(rid))],
            button=("Open the ticket", app_base_url() + "/admin/tickets?show=all&panel=tk-help-%d" % rid))
    except Exception as e:   # noqa: BLE001
        app.logger.warning("grade h disagree email failed: %s", e)
    return True, "ok_dis" if staff else "m_dis_ok", {"ref": help_ref(rid), "d": gh_when(datetime(day.year, day.month, day.day), "en", time=False) if day else ""}


def gradeh_staff_set_language(db, u, lang):
    """THE writer of the page language: 'bm' | 'en', for a Grade H person on the list only. (ok, key)."""
    person = gradeh_staff_person(db, u)
    if not person or lang not in GRADEH_LANGS:
        return False, "e_no_record"
    db.execute("UPDATE gradeh_people SET language=?, language_set_at=COALESCE(language_set_at, datetime('now')), "
               "updated_at=datetime('now') WHERE id=?", (lang, person["id"]))
    db.commit()
    log_activity(db, u["id"], "gradeh_language", lang)
    return True, "ok_saved"


def gradeh_staff_setup_step(u, person):
    """'language' | 'name' | 'picture' | 'tour' while a Grade H person is getting started, else None. The Language step comes
    first (canvas H1b); the rest are the dashboard's own steps (onboarding_step), run on this page. Off with onboarding."""
    if not person or not onboarding_on():
        return None
    if not person["language_set_at"]:
        return "language"
    return onboarding_step(u)


def _gh_staff_faq(cycle_id=None, shared=False):
    """The staff page's fixed questions: the deadline one ("What if I do not acknowledge in time?") only while deemed acknowledgement
    is switched on; off, there is no deadline, so the question is neither offered nor answered (2026-10-31). The shared-KPI one
    ("Why can't I enter Company performance?") only for a person who has a KPI that shares a unit's result (2026-11-03)."""
    return tuple(f for f in GRADEH_STAFF_FAQ if (f[0] != "deadline" or gradeh_deemed_on(cycle_id)) and (f[0] != "kpi_shared" or shared))


def gradeh_staff_ask(step, lang, message, deadline_text="", cycle_id=None, dis=False, shared=False):
    """One question to Ask OneHR on this page, answered from fixed words (no model, nothing logged, no result read out):
    (answer or None, [the questions offered on this step]). `dis`: the person has told us they do not agree, so the answers that
    would talk about the HOD and BU CEO's review say what is true for them (GRADEH_STAFF_FAQ_DIS)."""
    i = 1 if lang == "bm" else 0
    msg = " ".join((message or "").lower().split())[:300]
    faq = _gh_staff_faq(cycle_id, shared)
    offered = [f[2][i] for f in faq if step in f[1]]
    def answer(a, key=None):
        if dis and key in GRADEH_STAFF_FAQ_DIS:
            return GRADEH_STAFF_FAQ_DIS[key][i]
        return a[i] if a[i] else (gh_t(lang, "deemed_note", d=deadline_text) if deadline_text else
                                  {"en": "If the deadline passes and you have neither acknowledged nor told us you do not agree, we "
                                         "treat the appraisal as acknowledged. Acknowledge, or tell us, as soon as you have had your talk.",
                                   "bm": "Jika tarikh akhir berlalu dan anda tidak mengesahkan atau memberitahu kami bahawa anda "
                                         "tidak bersetuju, penilaian dianggap telah anda sahkan. Sahkan, atau beritahu kami, sebaik "
                                         "sahaja anda berbincang."}[lang])
    for key, steps, q, a, kws in faq:   # this step's own questions first (two steps may offer the same words)
        if step in steps and (msg == q[0].lower() or msg == q[1].lower() or (msg and any(k in msg for k in kws))):
            return answer(a, key), offered
    for key, steps, q, a, kws in faq:   # then a chip's exact words from an earlier step of theirs (as before), never on 'final'
        if step != "final" and (msg == q[0].lower() or msg == q[1].lower()):
            return answer(a, key), offered
    return None, offered


def _gh_shared_fig(l, lang):
    """A shared KPI line's figure as the person reads it: '92%' once Group People has filled it ('Rating 4' for a line rated 1-5, the
    `kpi_rated` string), '' before (a line that is not shared: '')."""
    if not l["bu_kpi_id"] or not _gh_shared_filled(l):
        return ""
    if l["group_scale"] in GRADEH_BU_RATED_SCALES:
        return gh_t(lang, "kpi_rated", n=l["bu_rating"])
    return "%s%%" % _gh_pct_str(l["bu_pct"])


def _gh_wait_kw(lines, key):
    """The {kpi} a 'result_wait_shared' / 'result_wait' string needs: the shared KPIs Group People has not filled yet."""
    return {"kpi": ", ".join(l["kpi_name"] for l in lines if _gh_shared_wait(l))} if key == "result_wait_shared" else {}


def gradeh_staff_view(db, u, person, lang, dis_open=False, dis_reason=None):
    """Everything the page draws, worked out here (the template and the page compute nothing): the greeting, the step list,
    the step's own card, the result as the line manager's submit stored it, the comments, the acknowledgement note and the
    final result once the person's unit is released. Never the promotion nomination, never the Leadership Principle answers."""
    st = gradeh_staff_state(db, person)
    step, a, kind, lines = st["step"], st["app"], st["kind"], st["lines"]
    i = 1 if lang == "bm" else 0
    cyc = db.execute("SELECT * FROM cycles WHERE id=?", (person["cycle_id"],)).fetchone()
    m = re.search(r"(20\d\d)", str(_row_get(cyc, "name") or "")) or re.search(r"(20\d\d)", str(_row_get(cyc, "starts_on") or ""))
    year = m.group(1) if m else str(_today_myt().year)
    # the line manager's name: the appraiser set, else their line manager on OneHR, else HR's supervisor text
    lm = None
    for uid in (person["appraiser_id"], _row_get(u, "manager_id")):
        if uid:
            r = db.execute("SELECT full_name FROM users WHERE id=?", (uid,)).fetchone()
            if r and (r["full_name"] or "").strip():
                lm = proper_name(r["full_name"].strip())
                break
    lm = lm or (proper_name((person["hr_supervisor_name"] or "").strip()) if (person["hr_supervisor_name"] or "").strip()
                else None)
    # deadlines, in the person's words
    nxt = gradeh_staff_deadline(db, person, st)   # the date the page waits on them for (the bar's reminder reads it too)
    dl = nxt[1] if nxt and nxt[0] == "ack" else None
    kpi_close = nxt[1] if nxt and nxt[0] == "kpi" else None
    kw = gradeh_window_closed(db, GRADEH_CELL_KPI, person["cycle_id"])
    _o2, lm_closes = window_dates(db, GRADEH_CELL_LM, person["cycle_id"])
    short = lambda raw: gh_when(_parse_when(raw), lang, time=False, year=False)  # noqa: E731
    v = {"lang": lang, "step": step, "route": person["route"], "year": year, "lm": lm, "kind": kind, "dis": st["dis"],
         "cycle_line": gh_t(lang, "cycle_line", year=year), "kpi_msg": None, "deemed_note": None, "deadline": None}
    # --- the step list
    steps = []
    if step == "final":
        # no line manager appraisal and nothing to acknowledge: the KPI step only if they sent figures; the line manager step is
        # shown without a tick (it did not happen); the result step is the current one and ticked
        if person["route"] == "A" and st["sent"]:
            steps.append({"state": "done", "label": gh_t(lang, "s_kpi_done"),
                          "sub": gh_when(_gh_myt(a["staff_submitted_at"]), lang, year=False) if a and a["staff_submitted_at"] else ""})
        steps.append({"state": "todo", "label": gh_t(lang, "s_lm_none"), "sub": gh_t(lang, "s_lm_none_sub")})
        steps.append({"state": "done", "cur": True, "label": gh_t(lang, "s_final"), "sub": ""})
    elif person["route"] == "A":
        if st["sent"] or step != "kpi":
            steps.append({"state": "done", "label": gh_t(lang, "s_kpi_done"),
                          "sub": gh_when(_gh_myt(a["staff_submitted_at"]), lang, year=False) if a and a["staff_submitted_at"] else ""})
        else:
            sub = (gh_t(lang, "now_close", d=gh_when(kpi_close, lang, time=False, year=False)) if kpi_close
                   else gh_t(lang, "now"))
            steps.append({"state": "now", "label": gh_t(lang, "s_kpi"), "sub": sub})
    lm_done = step in ("ack", "done")
    if step == "final":
        pass
    elif lm_done:
        steps.append({"state": "done", "label": gh_t(lang, "s_lm_done"),
                      "sub": gh_when(_gh_myt(a["lm_submitted_at"]), lang, time=False, year=False)})
    elif step == "wait":
        steps.append({"state": "now", "label": gh_t(lang, "s_lm"),
                      "sub": gh_t(lang, "now_by", d=short(lm_closes)) if lm_closes else gh_t(lang, "now")})
    else:
        steps.append({"state": "todo", "label": gh_t(lang, "s_lm"), "sub": gh_t(lang, "s_lm_sub")})
    if step == "final":
        pass
    elif step == "done":
        steps.append({"state": "done", "label": gh_t(lang, "s_ack_dis" if st["dis"] else
                                                     {"self": "s_ack_done", "deemed": "s_ack_deemed", "person": "s_ack_person"}[kind]),
                      "sub": ""})
    elif step == "ack":
        steps.append({"state": "now", "label": gh_t(lang, "s_ack"),
                      "sub": gh_t(lang, "now_by", d=gh_when(dl, lang, time=False, year=False)) if dl else gh_t(lang, "now")})
    else:
        steps.append({"state": "todo", "label": gh_t(lang, "s_ack"), "sub": gh_t(lang, "s_ack_sub")})
    n0 = 1
    for s_ in steps:
        s_["n"] = n0
        n0 += 1
    v["steps"] = steps
    # --- KPI entry
    if step == "kpi":
        if not lines:
            v["kpi_msg"] = gh_t(lang, "no_lines")
        elif kw:
            v["kpi_msg"] = (gh_t(lang, "kpi_closed", d=gh_when(_parse_when(kw[1]), lang, year=True)) if kw[0] == "closed"
                            else gh_t(lang, "kpi_not_open", d=gh_when(_parse_when(kw[1]), lang, year=True)) if _parse_when(kw[1])
                            else gh_t(lang, "kpi_not_open_u"))
        v["kpi_lines"] = [{"id": l["id"], "name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]),
                           "value": _gh_pct_str(l["staff_pct"]), "saved": l["staff_pct"] is not None,
                           "shared": bool(l["bu_kpi_id"]), "shared_fig": _gh_shared_fig(l, lang)} for l in lines]
        v["kpi_open"] = bool(lines) and not kw
        v["note"] = (a["staff_note"] if a else "") or ""
        ok, pct, key = gradeh_kpi_preview(db, u, {})
        v["result_pct"] = pct
        v["result_wait_text"] = gh_t(lang, key or "result_wait", **_gh_wait_kw(lines, key)) if pct is None else ""
    # --- what was sent (waiting, Route A)
    if (step == "wait" or step == "final" and st["sent"]) and person["route"] == "A":
        v["sent_lines"] = [{"name": l["kpi_name"], "value": _gh_pct_str(l["staff_pct"]),
                            "shown": ((_gh_shared_fig(l, lang) or gh_t(lang, "shared_pill")) if l["bu_kpi_id"] else "%s%%" % _gh_pct_str(l["staff_pct"]))}
                           for l in lines]
    # --- the result and the comments (as the line manager's submit stored them)
    if step in ("ack", "done"):
        band = a["perf_band"]
        n = {c_: k_ for k_, c_ in GRADEH_BCODE.items()}.get(band)
        rating = a["perf_rating"]
        perf = {"rating": _gh_pct_str(rating) if rating is not None else "", "label": GRADEH_RATING_LABELS[n][i] if n else "",
                "value": a["perf_value"], "wait": ""}
        if person["route"] == "A" and band is None and any(_gh_shared_wait(l) for l in lines):
            perf["wait"] = gh_t(lang, "perf_wait_shared")   # the line manager submitted before Group People filled a shared KPI
        yes = db.execute("SELECT COUNT(*) FROM gradeh_lp_answers WHERE cycle_id=? AND person_id=? AND answer='yes'",
                         (person["cycle_id"], person["id"])).fetchone()[0]
        pot = {"band": GRADEH_POT_WORDS.get(a["pot_band"], ("", ""))[i], "of": gh_t(lang, "pot_of", n=yes, m=14)}
        v["perf"], v["pot"] = perf, pot
        if person["route"] == "B":
            rs = {r["attr_key"]: r["rating"] for r in db.execute(
                "SELECT attr_key, rating FROM gradeh_ratings WHERE cycle_id=? AND person_id=?",
                (person["cycle_id"], person["id"]))}
            v["attrs"] = [{"name": at["title"][i], "rating": rs.get(at["key"], "")} for at in GRADEH_ATTRIBUTES]
        else:
            v["kpis"] = []
            for l in lines:
                if l["bu_kpi_id"]:   # a KPI Group People fills for everyone who shares it: its figure, and when it was filled after the submit
                    row = {"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]), "figure": _gh_shared_fig(l, lang) or gh_t(lang, "shared_pill"),
                           "changed": None, "updated": ""}
                    if _gh_shared_filled(l) and a["lm_submitted_at"] and (l["bu_filled_at"] or "") >= a["lm_submitted_at"]:
                        row["updated"] = gh_t(lang, "updated_on", d=gh_when(_gh_myt(l["bu_filled_at"]), lang, time=False, year=False))
                    v["kpis"].append(row)
                    continue
                fig = l["lm_pct"] if l["lm_pct"] is not None else l["staff_pct"]
                row = {"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]),
                       "figure": (gh_t(lang, "kpi_rated", n=l["lm_rating"]) if l["group_scale"] == "OTHER" and l["lm_rating"]
                                  else "%s%%" % _gh_pct_str(fig)), "changed": None}
                if l["lm_pct"] is not None and l["staff_pct"] is not None and abs(l["lm_pct"] - l["staff_pct"]) > 1e-9:
                    row["changed"] = gh_t(lang, "kpi_you", v=_gh_pct_str(l["staff_pct"]))
                    if (l["lm_reason"] or "").strip():
                        row["why"] = l["lm_reason"].strip()
                v["kpis"].append(row)
        v["comments"] = [(gh_t(lang, "cm_ach"), a["b_achievements"] or ""), (gh_t(lang, "cm_str"), a["b_strengths"] or ""),
                         (gh_t(lang, "cm_dev"), a["b_development"] or "")]
    if step == "ack" and dl:
        v["deadline"] = gh_when(dl, lang)
        v["deemed_note"] = gh_t(lang, "deemed_note", d=v["deadline"])
        v["ack_talk"] = gh_t(lang, "ack_talk", d=gh_when(dl, lang, time=False, year=False))
    elif step == "ack":
        v["ack_talk"] = gh_t(lang, "ack_talk_nodl")
    # --- done
    if step == "done":
        if st["dis"]:   # told us they do not agree: what they sent and what happens next (never their reason)
            dd = _gh_myt(a["disagree_at"])
            v["done_h"] = gh_t(lang, "d_h")
            v["done_p"] = (gh_t(lang, "d_p_dis_person", d=gh_when(_parse_when(a["ack_in_person_on"]), lang, time=False))
                           if kind == "person" else gh_t(lang, "d_p_dis", d=gh_when(dd, lang)))
            v["dis_chip"] = gh_t(lang, "d_dis_chip", d=gh_when(dd, lang, time=False, year=False))
        elif kind == "self":
            v["done_h"], v["done_p"] = gh_t(lang, "d_h"), gh_t(lang, "d_p_ack", d=gh_when(_gh_myt(a["acknowledged_at"]), lang))
        elif kind == "deemed":
            v["done_h"] = gh_t(lang, "d_h_deemed")
            v["done_p"] = gh_t(lang, "d_p_deemed", d=gh_when(_gh_myt(a["deemed_at"]), lang, time=False))
        else:
            v["done_h"] = gh_t(lang, "d_h")
            v["done_p"] = gh_t(lang, "d_p_person", d=gh_when(_parse_when(a["ack_in_person_on"]), lang, time=False))
    if step in ("ack", "done", "final"):   # a released unit shows the final result even to someone who has not acknowledged yet (piece 6)
        v["released"] = gradeh_is_released(db, person["cycle_id"], person["id"])
        if v["released"]:
            fb, _s = gradeh_effective_band(db, person["cycle_id"], person["id"], "perf")
            fp, _s2 = gradeh_effective_band(db, person["cycle_id"], person["id"], "pot")
            fn = {c_: k_ for k_, c_ in GRADEH_BCODE.items()}.get(fb)
            v["final"] = {"rating": fn or "", "label": GRADEH_RATING_LABELS[fn][i] if fn else "",
                          "pot": GRADEH_POT_WORDS.get(fp, ("", ""))[i] if fp else ""}
    # --- Ask OneHR's opening line
    first = welcome_identity(u).get("first_name") or ""
    v["ask_hi"] = gh_t(lang, "ask_hi_" + step, name=first)
    v["final_wait"] = gh_t(lang, "final_wait_dis" if st["dis"] else "final_wait")
    v["not_final"] = gh_t(lang, "not_final_dis" if st["dis"] else "not_final")
    v["res_h"] = gh_t(lang, "res_h" if (step == "ack" or st["dis"]) else "d_what")
    v["dis_open"] = bool(dis_open) and step == "ack"
    v["dis_reason"] = dis_reason or ""
    v["dis_n"] = len((dis_reason or "").split())
    v["ask_chips"] = [f[2][i] for f in _gh_staff_faq(person["cycle_id"], any(l["bu_kpi_id"] for l in lines)) if step in f[1]]
    v["first"] = first
    # a Grade H supervisor also appraises Grade H staff (piece 4): a way to those pages from their own
    mine = len(gradeh_lm_people(db, u, person["cycle_id"]))
    v["appraise"] = {"n": mine, "text": gh_t(lang, "appraise_n", n=mine), "open": gh_t(lang, "appraise_open"),
                     "url": url_for("review_gradeh")} if mine else None
    return v


def _gh_say(lang, key, args=None):
    """A writer's (key, args) as the person's sentence; a '_when' arg is a MYT datetime shown as 'd', and a '%s' left in
    the args for a window's date is filled by the caller (kpi_closed / kpi_not_open)."""
    args = dict(args or {})
    if "_when" in args:
        if args["_when"] is None and key + "_u" in GRADEH_STAFF_T:   # a part with no start date: "isn't open yet"
            key = key + "_u"
        args["d"] = gh_when(args.pop("_when"), lang)
    return gh_t(lang, key, **args) if args else gh_t(lang, key)


def _gh_staff_ctx():
    """(db, user, person, lang) for a staff route, or a 404: not signed in as someone on the Grade H list for the cycle."""
    u = current_user()
    db = get_db()
    person = gradeh_staff_person(db, u)
    if not person:
        abort(404)
    return db, u, person, (person["language"] if person["language"] in GRADEH_LANGS else "bm")


def _gh_wants_json():
    return request.form.get("json") == "1"


@app.route("/my-appraisal")
@login_required
def my_appraisal():
    """The staff page. A GET writes nothing except the lazy deemed-acknowledgement step for this person alone
    (gradeh_staff_deemed_for: idempotent, only once their deadline has passed). ?disagree=1 opens "I do not agree" in the
    acknowledge card (the button works with no script)."""
    db, u, person, lang = _gh_staff_ctx()
    gradeh_staff_deemed_for(db, person)
    return _my_appraisal_render(db, u, person, lang, dis_open=request.args.get("disagree") == "1")


def _my_appraisal_render(db, u, person, lang, dis_open=False, dis_reason=None):
    setup = gradeh_staff_setup_step(u, person)
    first = welcome_identity(u).get("first_name") or ""
    ctx = {"gh_bar": True, "html_lang": "ms" if lang == "bm" else "en", "lang": lang, "setup": setup,
           "T": (lambda key, **kw: gh_t(lang, key, **kw)), "first": first}
    nm = (_row_get(u, "display_name") or "").strip() or (u["full_name"] or "").strip()
    ctx["me"] = {"initials": welcome_identity(u)["initials"], "avatar": avatar_url(_row_get(u, "avatar")),
                 "name": nm.title() if nm.isupper() else nm, "eid": _row_get(u, "employee_id") or "",
                 "title": proper_name((_row_get(u, "job_title") or "").strip()), "lang_code": "BM" if lang == "bm" else "EN"}
    if setup:
        step_no = {"language": 0, "name": 1, "picture": 2, "tour": 3}[setup]
        pics = _avatar_options(u, _row_get(u, "avatar")) if setup == "picture" else []
        ctx.update(setup_no=step_no, hris_name=_hris_first_name(u) if setup == "name" else None,
                   official=(u["full_name"] or "").strip(), display=_row_get(u, "display_name") or "",
                   groups=_avatar_groups(pics) if pics else [], language_now=lang)
        return render_template("my_appraisal.html", **ctx)
    v = gradeh_staff_view(db, u, person, lang, dis_open=dis_open, dis_reason=dis_reason)
    ctx.update(v=v)
    if request.args.get("tour") == "1":   # the look around over the real page; this GET writes nothing (the Start button's POST did)
        ctx["tour"] = gradeh_tour(lang, v)
    return render_template("my_appraisal.html", **ctx)


@app.route("/my-appraisal/language", methods=["POST"])
@login_required
def my_appraisal_language():
    db, u, person, lang = _gh_staff_ctx()
    gradeh_staff_set_language(db, u, (request.form.get("lang") or "").strip())
    nxt = (request.form.get("next") or "").strip()
    if nxt == GRADEH_LM_PATH:   # a Grade H supervisor switching language on the Grade H Appraisal pages stays there
        return redirect(url_for("review_gradeh"), 303)
    return redirect(url_for("my_appraisal"), 303)


@app.route("/my-appraisal/setup", methods=["POST"])
@login_required
def my_appraisal_setup():
    """The first sign-in's name, picture and look-around steps on this page, through the dashboard's own writers."""
    db, u, person, lang = _gh_staff_ctx()
    step = request.form.get("step")
    if step == "name":
        name, why = _save_display_name(db, u, request.form.get("name") or "")
        if not name:
            flash(gh_t(lang, "e_name"), "error")
    elif step == "picture":
        if not _save_avatar(db, u, request.form.get("avatar") if request.form.get("keep") != "1" else 0):
            flash(gh_t(lang, "e_picture"), "error")
    elif step == "tour":
        db.execute("UPDATE users SET onboard_tour_at=COALESCE(onboard_tour_at, datetime('now')) WHERE id=?", (u["id"],))
        db.commit()
        return redirect(url_for("my_appraisal", tour=1), 303)   # the page opens with the tour running over it
    else:
        abort(400)
    return redirect(url_for("my_appraisal"), 303)


def _gh_kpi_post(send):
    db, u, person, lang = _gh_staff_ctx()
    lines = _gh_lines(db, person) if person["route"] == "A" else []
    values = _gh_form_values(person, lines, request.form)
    ok, key, args = gradeh_staff_save_kpi(db, u, values, note=request.form.get("note"), send=send)
    say = _gh_say(lang, key, args)
    if _gh_wants_json():
        pct = gradeh_kpi_preview(db, u, {})[1]
        return jsonify(ok=ok, say=say, key=key, result=pct, line=(args or {}).get("line"),
                       saved=[l["id"] for l in _gh_lines(db, person) if l["staff_pct"] is not None]), (200 if ok else 400)
    flash(say, "ok" if ok else "error")
    return redirect(url_for("my_appraisal"), 303)


@app.route("/my-appraisal/kpi/save", methods=["POST"])
@login_required
def my_appraisal_kpi_save():
    return _gh_kpi_post(False)


@app.route("/my-appraisal/kpi/send", methods=["POST"])
@login_required
def my_appraisal_kpi_send():
    return _gh_kpi_post(True)


@app.route("/my-appraisal/kpi/preview", methods=["POST"])
@login_required
def my_appraisal_kpi_preview():
    """The weighted result for what is typed now, worked out here (the page never computes it). Stores nothing."""
    db, u, person, lang = _gh_staff_ctx()
    lines = _gh_lines(db, person) if person["route"] == "A" else []
    values = _gh_form_values(person, lines, request.form)
    if values is None:
        abort(404)
    ok, pct, key = gradeh_kpi_preview(db, u, values)
    return jsonify(ok=ok, result=pct, label=gh_t(lang, "result_l"),
                   text=(gh_t(lang, "weighted_l", v=pct) if pct is not None
                         else gh_t(lang, key or "result_wait", **({"max": GRADEH_PCT_MAX, "kpi": ""} if key == "e_range" else _gh_wait_kw(lines, key)))))


@app.route("/my-appraisal/acknowledge", methods=["POST"])
@login_required
def my_appraisal_acknowledge():
    db, u, person, lang = _gh_staff_ctx()
    ok, key, args = gradeh_staff_acknowledge(db, u, request.form.get("confirm") == "1")
    flash(_gh_say(lang, key, args), "ok" if ok else "error")
    return redirect(url_for("my_appraisal"), 303)


@app.route("/my-appraisal/disagree", methods=["POST"])
@login_required
def my_appraisal_disagree():
    """"I do not agree" (Chris, 2 Nov 2026): the person's own words and the tick, through gradeh_staff_disagree. A refusal about the words
    or the tick shows the page again with the card open and what they wrote kept (never lose 300 words); the other refusals (the
    deadline passed, already acknowledged, not ready) redirect to the page as it is now."""
    db, u, person, lang = _gh_staff_ctx()
    reason = request.form.get("reason")
    ok, key, args = gradeh_staff_disagree(db, u, reason, request.form.get("confirm") == "1")
    flash(_gh_say(lang, key, args), "ok" if ok else "error")
    if not ok and key in ("e_dis_need", "e_dis_long", "e_dis_reword", "e_ack_confirm"):
        return _my_appraisal_render(db, u, person, lang, dis_open=True, dis_reason=reason)
    return redirect(url_for("my_appraisal"), 303)


@app.route("/my-appraisal/ask", methods=["POST"])
@login_required
def my_appraisal_ask():
    """Ask OneHR on the staff page: fixed answers about this page (no model, no result read out, nothing stored)."""
    db, u, person, lang = _gh_staff_ctx()
    st = gradeh_staff_state(db, person)
    a = st["app"]
    dl = _gh_myt(gradeh_deemed_deadline(db, person["cycle_id"], a["lm_submitted_at"])) if a and a["lm_submitted_at"] else None
    ans, offered = gradeh_staff_ask(st["step"], lang, request.form.get("message"), gh_when(dl, lang) if dl else "",
                                 cycle_id=person["cycle_id"], dis=st["dis"], shared=any(l["bu_kpi_id"] for l in st["lines"]))
    return jsonify(ok=True, say=ans or gh_t(lang, "ask_none"), found=bool(ans), chips=offered)


# ---------------------------------------------------------------------------------------------------------------------
# Grade H Appraisal, piece 4: the LINE MANAGER side, "Grade H Appraisal" on the AI+ journey (2026-10-28; spec OneHR/JG H
# Appraisal/BUILD-SPEC.md, canvases L0-L7). Routes under /review/gradeh. The appraiser of a person is the one set on the
# list, else their OneHR line manager (gradeh_people.appraiser_id / users.manager_id): a person acts on their appraisees
# only, never on their own record. Year-End only, behind the module gate. The server works out every figure and band
# (gradeh_computed); the page and the AI never do, and the AI never submits or picks a rating. One writer per write; the
# page and any later chat call the same function. A submit is stored exactly as gradeh_computed reads it, with
# lm_submitted_at set last. Staff never see the promotion nomination (it goes to Group People with the result).
# ---------------------------------------------------------------------------------------------------------------------
