def gh_lm_t(lang, key, **kw):
    """One string of the line manager's pages in `lang` ('bm' | 'en'); {fields} filled from kw."""
    pair = GRADEH_LM_T[key]
    txt = pair[1] if lang == "bm" else pair[0]
    return txt.format(**kw) if kw else txt


def _gh_lm_say(lang, key, args=None):
    args = dict(args or {})
    if "_when" in args:
        if args["_when"] is None and key + "_u" in GRADEH_LM_T:   # a part with no start date: "isn't open yet"
            key = key + "_u"
        args["d"] = gh_when(args.pop("_when"), lang)
    return gh_lm_t(lang, key, **args) if args else gh_lm_t(lang, key)


