def gh_lm_chips(lang):
    """The three questions the page offers, in the page's language."""
    i = 1 if lang == "bm" else 0
    return [f[2][i] for f in GRADEH_LM_FAQ[:3]]


def gradeh_lm_ask(message, lang="en"):
    """(answer in `lang` or None, [chips in `lang`]): Ask OneHR on the line manager's pages. Fixed answers by keyword (either
    language's words and either language's chip text find an entry); reads no result and stores nothing."""
    i = 1 if lang == "bm" else 0
    m = " ".join((message or "").lower().split())
    if ai_draft.screen_message(message or "") in ("injection", "not_allowed"):
        return None, gh_lm_chips(lang)
    # the language question is looked at first: "can I change the language" would otherwise be taken for "change" (the submit answer)
    for _k, words, q, ans in GRADEH_LM_FAQ:   # a chip's exact words (either language) first: a Malay chip holds other entries' keywords
        if m and (m == q[0].lower() or m == q[1].lower()):
            return ans[i], [f[2][i] for f in GRADEH_LM_FAQ[:3] if f[3] != ans]
    for _k, words, q, ans in sorted(GRADEH_LM_FAQ, key=lambda f: f[0] != "language"):
        if m and any(w in m for w in words):
            return ans[i], [f[2][i] for f in GRADEH_LM_FAQ[:3] if f[3] != ans]
    return None, gh_lm_chips(lang)


def gradeh_lm_cycle_id(db):
    """The active cycle's id while the module is running in it, else None."""
    cid = active_cycle_id(db)
    return cid if cid and gradeh_module_on(db, cid) else None


def gradeh_lm_can(db, u):
    """May this account use the line manager pages at all: signed in, not an admin, and the super admin has not switched
    the ability off for their seat (Leader roles, "lm.gradeh")."""
    return bool(u and not is_admin(u) and leader_learn_can(u, "lm.gradeh", db))


_GH_LM_PEOPLE_SQL = (
    "SELECT p.*, uu.full_name AS full_name, uu.job_title AS job_title, uu.business_group AS business_group, "
    "uu.company AS company, uu.email AS email FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
    "WHERE p.cycle_id=? AND p.private_company=0 AND uu.left_at IS NULL AND p.user_id != ? "
    "AND (p.appraiser_id=? OR (p.appraiser_id IS NULL AND uu.manager_id=?))")


def gradeh_lm_people(db, u, cycle_id=None):
    """The Grade H people this account appraises in the cycle: where they are the appraiser set on the list, or, with none
    set, their OneHR line manager. Never themselves. [] when the module is off, or for an admin."""
    cid = cycle_id or gradeh_lm_cycle_id(db)
    if not cid or not gradeh_lm_can(db, u):
        return []
    return db.execute(_GH_LM_PEOPLE_SQL + " ORDER BY lower(uu.full_name), p.id", (cid, u["id"], u["id"], u["id"])).fetchall()


def gradeh_lm_person(db, u, person_id, cycle_id=None):
    """One of this account's appraisees (the row, with the person's name fields), else None: someone else's record, a
    private-company row, someone who has left, themselves, or the module off."""
    cid = cycle_id or gradeh_lm_cycle_id(db)
    if not cid or not gradeh_lm_can(db, u):
        return None
    try:
        pid = int(person_id)
    except (TypeError, ValueError):
        return None
    return db.execute(_GH_LM_PEOPLE_SQL + " AND p.id=?", (cid, u["id"], u["id"], u["id"], pid)).fetchone()


def _gh_in(db, sql, ids, extra=()):
    """sql with one %s for an IN list, run over the ids in chunks; the rows."""
    out = []
    for i in range(0, len(ids), 800):
        chunk = ids[i:i + 800]
        out += db.execute(sql % ",".join("?" * len(chunk)), tuple(extra) + tuple(chunk)).fetchall()
    return out


def _gh_lm_bulk(db, cid, plist):
    """{person id: {"app": row|None, "n_attr", "n_lp", "lines": [rows with the entry's columns]}} for many people in a
    fixed number of queries (a read over a population is batched)."""
    ids = [p["id"] for p in plist]
    out = {i: {"app": None, "n_attr": 0, "n_lp": 0, "lines": []} for i in ids}
    if not ids:
        return out
    for r in _gh_in(db, "SELECT * FROM gradeh_appraisals WHERE cycle_id=? AND person_id IN (%s)", ids, (cid,)):
        out[r["person_id"]]["app"] = r
    for r in _gh_in(db, "SELECT person_id, COUNT(*) AS n FROM gradeh_ratings WHERE cycle_id=? AND person_id IN (%s) "
                        "GROUP BY person_id", ids, (cid,)):
        out[r["person_id"]]["n_attr"] = r["n"]
    for r in _gh_in(db, "SELECT person_id, COUNT(*) AS n FROM gradeh_lp_answers WHERE cycle_id=? AND person_id IN (%s) "
                        "GROUP BY person_id", ids, (cid,)):
        out[r["person_id"]]["n_lp"] = r["n"]
    for r in _gh_in(db, "SELECT l.person_id AS person_id, l.id AS id, l.kpi_name AS kpi_name, l.weight AS weight, "
                        "l.group_scale AS group_scale, l.bu_kpi_id AS bu_kpi_id, l.bu_pct AS bu_pct, l.bu_rating AS bu_rating, l.bu_filled_at AS bu_filled_at, "
                        "e.staff_pct AS staff_pct, e.lm_pct AS lm_pct, e.lm_reason AS lm_reason, "
                        "e.lm_rating AS lm_rating, e.lm_at AS lm_at FROM gradeh_kpi_lines l LEFT JOIN gradeh_kpi_entries e "
                        "ON e.line_id=l.id WHERE l.cycle_id=? AND l.person_id IN (%s) ORDER BY l.sort_order, l.id", ids, (cid,)):
        out[r["person_id"]]["lines"].append(r)
    return out


def gradeh_lm_ready(person, d, kpi_closed=False):
    """Can the line manager start on this person: a Line manager route always; a KPI route once the person has sent their
    achievement, or once the KPI window has closed (the line manager then enters the figures)."""
    if person["route"] != "A":
        return True
    return bool((d["app"] and d["app"]["staff_submitted_at"]) or kpi_closed)


def _gh_lm_fig_ok(l):
    """Does this KPI line have a figure the line manager has seen: checked (lm_at) and a figure, or a rating on a line
    that is rated 1-5. A line that shares a unit's result has nothing for the line manager to see or check: it counts as done."""
    if l["bu_kpi_id"]:
        return True
    if l["lm_at"] is None:
        return False
    if l["group_scale"] == "OTHER":
        return l["lm_rating"] is not None
    return l["lm_pct"] is not None or l["staff_pct"] is not None


def _gh_lm_comments_n(a):
    if not a:
        return 0
    return sum(1 for v in ((a["b_achievements"] or "").strip(), (a["b_strengths"] or "").strip(),
                           (a["b_development"] or "").strip()) if v)


def gradeh_lm_progress(person, d):
    """What is done on each step of this person's appraisal: {"attrs"|"kpis", "lp", "comments"} each {n, m, done}."""
    a = d["app"]
    if person["route"] == "B":
        first = ("attrs", {"n": d["n_attr"], "m": GRADEH_ATTR_COUNT, "done": d["n_attr"] == GRADEH_ATTR_COUNT})
    else:
        n = sum(1 for l in d["lines"] if _gh_lm_fig_ok(l))
        first = ("kpis", {"n": n, "m": len(d["lines"]), "done": bool(d["lines"]) and n == len(d["lines"])})
    ncm = _gh_lm_comments_n(a)
    return dict([first, ("lp", {"n": d["n_lp"], "m": 14, "done": d["n_lp"] == 14}),
                 ("comments", {"n": ncm, "m": 3, "done": ncm == 3})])


def _gh_lm_deemed_now(db, person, a, now_utc=None):
    """Display only: has this person's deemed deadline passed (no write; the staff page writes it for the person looking)."""
    if not a or not a["lm_submitted_at"] or a["acknowledged_at"] or a["ack_in_person"]:
        return bool(a and a["deemed_at"])
    if a["deemed_at"]:
        return True
    dl = gradeh_deemed_deadline(db, person["cycle_id"], a["lm_submitted_at"])
    return bool(dl and dl <= (now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")))


def gradeh_lm_status(db, person, d, kpi_closed=False):
    """Where one person is, for the line manager: {"group": 'ready'|'staff'|'done', "key": the status text key, "args": {...},
    "kind": 'wait_kpi'|'ready'|'draft'|'submitted'|'ack'}. 'ready' = the line manager's turn (including a draft), 'staff' =
    with the person (their KPI achievement, or their acknowledgement), 'done' = acknowledged, deemed or in person."""
    a = d["app"]
    if a and a["lm_submitted_at"]:
        dis = gradeh_is_disagreed(a)   # told us they do not agree (the tag; never the reason)
        if a["acknowledged_at"]:
            return {"group": "done", "kind": "ack", "key": "st_ack_self", "when": a["acknowledged_at"], "args": {}, "dis": dis}
        if a["ack_in_person"]:
            return {"group": "done", "kind": "ack", "key": "st_ack_person", "when": a["ack_in_person_on"], "args": {}, "dis": dis}
        if _gh_lm_deemed_now(db, person, a):
            dl = a["deemed_at"] or gradeh_deemed_deadline(db, person["cycle_id"], a["lm_submitted_at"])
            return {"group": "done", "kind": "ack", "key": "st_ack_deemed", "when": dl, "args": {}}
        return {"group": "staff", "kind": "submitted", "key": "st_ack_wait", "when": None, "args": {}}
    if not gradeh_lm_ready(person, d, kpi_closed):
        return {"group": "staff", "kind": "wait_kpi", "key": "st_wait_kpi", "when": None, "args": {}}
    prog = gradeh_lm_progress(person, d)
    started = (d["n_attr"] or d["n_lp"] or _gh_lm_comments_n(a) or any(l["lm_at"] for l in d["lines"]))
    if not started:
        return {"group": "ready", "kind": "ready", "key": "st_kpi_in" if person["route"] == "A" else "st_ready",
                "when": None, "args": {}}
    for k_, w_ in (("attrs", "w_attr"), ("kpis", "w_kpi"), ("lp", "w_lp"), ("comments", "w_cm")):
        if k_ in prog and not prog[k_]["done"]:
            return {"group": "ready", "kind": "draft", "key": "st_draft", "when": None,
                    "args": {"n": prog[k_]["n"], "m": prog[k_]["m"], "what_key": w_}}
    return {"group": "ready", "kind": "draft", "key": "st_draft_done", "when": None, "args": {}}


def gradeh_lm_status_text(db, person, st, lang):
    """The status as the table says it (kind of date in MYT, the person's KPI window for a person still to send)."""
    if st["key"] == "st_draft":
        return gh_lm_t(lang, "st_draft", n=st["args"]["n"], m=st["args"]["m"], what=gh_lm_t(lang, st["args"]["what_key"]))
    if st["key"] == "st_wait_kpi":
        _o, closes = window_dates(db, GRADEH_CELL_KPI, person["cycle_id"])
        dt = _parse_when(closes)
        return gh_lm_t(lang, "st_wait_kpi", d=(" · " + gh_when(dt, lang, time=False, year=False)) if dt else "")
    if st["key"] in ("st_ack_self", "st_ack_deemed", "st_ack_person"):
        raw = st["when"]
        dt = _parse_when(raw) if st["key"] == "st_ack_person" else _gh_myt(raw)
        return gh_lm_t(lang, st["key"], d=gh_when(dt, lang, time=False, year=False) if dt else "")
    return gh_lm_t(lang, st["key"])


def gradeh_lm_team(db, u, flt="all", lang="en"):
    """Everything the team list (L1) draws: {"rows", "counts", "n", "closes", "filters"} for this account's appraisees. A row:
    {id, name, title, unit, route, status text, group, kind, rating, band, pot, action 'appraise'|'continue'|'view'|None,
    ack_open bool (the in-person tick is offered)}. Reads only."""
    cid = gradeh_lm_cycle_id(db)
    people = gradeh_lm_people(db, u, cid)
    bulk = _gh_lm_bulk(db, cid, people) if cid else {}
    kw = gradeh_window_closed(db, GRADEH_CELL_KPI, cid) if cid else None
    kpi_closed = bool(kw and kw[0] == "closed")
    rows, counts = [], {"ready": 0, "staff": 0, "done": 0, "kpi": 0, "ack": 0, "noemail": 0, "ack_noemail": 0}
    for p in people:
        d = bulk[p["id"]]
        st = gradeh_lm_status(db, p, d, kpi_closed)
        counts[st["group"]] += 1
        if st["kind"] == "wait_kpi":
            counts["kpi"] += 1
        no_email = not gradeh_has_email(p["email"])   # the admin page's "Can sign in" rule (gradeh_has_email)
        if no_email:
            counts["noemail"] += 1
        if st["kind"] == "submitted":
            counts["ack"] += 1
            counts["ack_noemail"] += 1 if no_email else 0
        a = d["app"]
        sub = bool(a and a["lm_submitted_at"])
        action = ("view" if sub else "continue" if st["kind"] == "draft" else "appraise" if st["kind"] == "ready" else None)
        band = a["perf_band"] if sub else None
        n = {c_: k_ for k_, c_ in GRADEH_BCODE.items()}.get(band)
        rows.append({"id": p["id"], "name": proper_name((p["full_name"] or "").strip()),
                     "title": proper_name((p["job_title"] or "").strip()),
                     "unit": display_company(p["business_group"], p["company"]) if p["company"] else "",
                     "route": p["route"], "group": st["group"], "kind": st["kind"], "no_email": no_email, "dis": bool(st.get("dis")),
                     "status": gradeh_lm_status_text(db, p, st, lang), "action": action,
                     "rating": (n, band) if sub and n else None,
                     "pot": GRADEH_POT_WORDS.get(a["pot_band"], ("", ""))[1 if lang == "bm" else 0] if sub and a["pot_band"] else "",
                     "ack_open": bool(sub and st["kind"] == "submitted")})
    keep = {"all": lambda r: True, "ready": lambda r: r["group"] == "ready", "kpi": lambda r: r["kind"] == "wait_kpi",
            "ack": lambda r: r["kind"] == "submitted", "noemail": lambda r: r["no_email"], "done": lambda r: r["group"] == "done"}
    flt = flt if flt in keep else "all"
    _o, lm_closes = window_dates(db, GRADEH_CELL_LM, cid) if cid else (None, None)
    closes = gh_when(_parse_when(lm_closes), lang, time=False, year=False) if lm_closes else ""
    filters = [("all", "f_all", len(rows)), ("ready", "f_ready", counts["ready"]), ("kpi", "f_kpi", counts["kpi"]),
               ("ack", "f_ack", counts["ack"]), ("noemail", "f_noemail", counts["noemail"]), ("done", "f_done", counts["done"])]
    return {"rows": [r for r in rows if keep[flt](r)], "counts": counts, "n": len(rows), "closes": closes, "filter": flt,
            "filters": [{"key": k, "label": gh_lm_t(lang, lk), "n": n_} for k, lk, n_ in filters]}


def gradeh_lm_dash(db, u):
    """The line manager's dashboard card and rail step (L0): None unless the module is on and they have appraisees, else
    {n, ready, staff, done, closes_label, closes_full, url, state ('turn'|'waiting'|'done')}."""
    if not gradeh_on() or not u or is_admin(u):
        return None
    cid = gradeh_lm_cycle_id(db)
    if not cid:
        return None
    people = gradeh_lm_people(db, u, cid)
    if not people:
        return None
    bulk = _gh_lm_bulk(db, cid, people)
    kw = gradeh_window_closed(db, GRADEH_CELL_KPI, cid)
    kpi_closed = bool(kw and kw[0] == "closed")
    c = {"ready": 0, "staff": 0, "done": 0}
    for p in people:
        c[gradeh_lm_status(db, p, bulk[p["id"]], kpi_closed)["group"]] += 1
    _o, lm_closes = window_dates(db, GRADEH_CELL_LM, cid)
    dt = _parse_when(lm_closes)
    return {"n": len(people), "ready": c["ready"], "staff": c["staff"], "done": c["done"],
            "closes_label": gh_when(dt, "en", time=False, year=False) if dt else "",
            "closes_full": gh_when(dt, "en", time=False, year=True) if dt else "",
            "url": url_for("review_gradeh"),
            "state": "turn" if c["ready"] else ("waiting" if c["staff"] else "done")}


def _gradeh_lm_door():
    """The journey rail's "Your team" door for Grade H Appraisal: {n_open, label, url} or None. Cheap when the module is off."""
    if not gradeh_on() or not session.get("user_id"):
        return None
    try:
        db = get_db()
        d = gradeh_lm_dash(db, current_user())
    except Exception:   # a door never breaks the page it sits on
        return None
    return {"n_open": d["ready"], "label": GRADEH_LABEL, "url": d["url"]} if d else None


app.jinja_env.globals["gradeh_lm_door"] = _gradeh_lm_door


def gradeh_audiences(db=None, u=None):
    """The Grade H seats this account holds, as a frozenset of "staff" (on the list), "lm" (appraises someone on it), "hod"
    and "buceo" (calibrate Grade H people): what the agents, Ask OneHR, Help and the KB tell a person about Grade H follows
    this, so nobody is told about a seat they do not hold. Empty with the server switch off (ONEHR_GRADEH) or for an admin or
    no one signed in; worked out once a request (2026-10-28)."""
    if not gradeh_on():
        return frozenset()
    u = u or (current_user() if has_request_context() else None)
    if not u or is_admin(u):
        return frozenset()
    cache = getattr(g, "_gh_aud", None) if has_request_context() else None
    if cache and cache[0] == u["id"]:
        return cache[1]
    db = db or get_db()
    out = set()
    if gradeh_staff_person(db, u):
        out.add("staff")
    if gradeh_lm_people(db, u):
        out.add("lm")
    if gradeh_hod_can(db, u):
        out.add("hod")
    if gradeh_buceo_units(db, u):
        out.add("buceo")
    out = frozenset(out)
    if has_request_context():
        g._gh_aud = (u["id"], out)
    return out


def gradeh_lm_lang(db, u):
    """THE reader of the line manager pages' language ('bm' | 'en'): a Grade H supervisor reads their own (gradeh_people.language);
    every other line manager reads what they chose with the switch on the pages (users.gradeh_lm_lang), English until they do
    (2026-10-30)."""
    p = gradeh_staff_person(db, u) if u else None
    if p:
        return p["language"] if p["language"] in GRADEH_LANGS else "bm"
    mine = _row_get(u, "gradeh_lm_lang") if u else None
    return mine if mine in GRADEH_LANGS else "en"


def gradeh_lm_set_language(db, u, lang):
    """THE writer of the line manager pages' language, for any account that may use them (gradeh_lm_can): a Grade H supervisor's
    choice goes through gradeh_staff_set_language (their own gradeh_people.language, so the staff page and these pages agree);
    anyone else's is kept on their account (users.gradeh_lm_lang). (ok, key)."""
    if lang not in GRADEH_LANGS or not gradeh_lm_can(db, u):
        return False, "e_no_record"
    if gradeh_staff_person(db, u):
        return gradeh_staff_set_language(db, u, lang)
    db.execute("UPDATE users SET gradeh_lm_lang=? WHERE id=?", (lang, u["id"]))
    db.commit()
    log_activity(db, u["id"], "gradeh_language", lang)
    return True, "ok_saved"


# --- the writers: one function per write. Each returns (ok, key, args): key is a GRADEH_LM_T key the caller says in the
# page's language. The person is never named by a form field alone: gradeh_lm_person checks the account is their appraiser.
def _gh_lm_guard(db, u, pid, editing=True):
    """(person, bundle, None, {}) for a request that may go on, else (None, None, key, args). The module is on, the person is
    this account's appraisee, the appraisal is not submitted (editing), the line manager's window is open, and a KPI-route
    person is ready (their achievement is in, or the KPI window has closed)."""
    if not gradeh_module_on(db):
        return None, None, "m_off", {}
    p = gradeh_lm_person(db, u, pid)
    if not p:
        return None, None, "m_not_yours", {}
    if gradeh_is_released(db, p["cycle_id"], p["id"]):   # a released unit: nothing changes (piece 6)
        return None, None, "m_released", {}
    d = _gh_lm_bulk(db, p["cycle_id"], [p])[p["id"]]
    if editing:
        if d["app"] and d["app"]["lm_submitted_at"]:
            return None, None, "m_locked", {}
        w = gradeh_window_closed(db, GRADEH_CELL_LM, p["cycle_id"])
        if w:
            return None, None, ("m_closed" if w[0] == "closed" else "m_not_open"), {"_when": _parse_when(w[1])}
        kw = gradeh_window_closed(db, GRADEH_CELL_KPI, p["cycle_id"])
        if not gradeh_lm_ready(p, d, bool(kw and kw[0] == "closed")):
            return None, None, "m_wait_staff", {}
    return p, d, None, {}


def _gh_lm_touch(db, p):
    db.execute("INSERT OR IGNORE INTO gradeh_appraisals(cycle_id, person_id) VALUES (?,?)", (p["cycle_id"], p["id"]))
    db.execute("UPDATE gradeh_appraisals SET updated_at=datetime('now') WHERE cycle_id=? AND person_id=?",
               (p["cycle_id"], p["id"]))


def gradeh_lm_save_ratings(db, u, pid, values):
    """THE writer of the line manager's attribute ratings (Line manager route). `values` = {attribute key: 1..5 as typed}. One
    bad value refuses the WHOLE request: nothing is saved. An attribute not in `values` keeps what it had."""
    p, d, key, args = _gh_lm_guard(db, u, pid)
    if key:
        return False, key, args
    if p["route"] != "B":
        return False, "m_route", {}
    known = {at["key"] for at in GRADEH_ATTRIBUTES}
    clean = {}
    for k, v in (values or {}).items():
        if k not in known:
            return False, "m_bad_attr", {}
        t = str(v).strip()
        if not re.fullmatch(r"[1-5]", t):
            return False, "m_bad_rating", {}
        clean[k] = int(t)
    for k, v in clean.items():
        cur = db.execute("UPDATE gradeh_ratings SET rating=?, updated_at=datetime('now') WHERE cycle_id=? AND person_id=? "
                         "AND attr_key=?", (v, p["cycle_id"], p["id"], k))
        if not cur.rowcount:
            db.execute("INSERT INTO gradeh_ratings(cycle_id, person_id, attr_key, rating) VALUES (?,?,?,?)",
                       (p["cycle_id"], p["id"], k, v))
    _gh_lm_touch(db, p)
    db.commit()
    return True, "m_saved", {}


def gradeh_lm_save_lp(db, u, pid, answers):
    """THE writer of the 14 Leadership Principle answers. `answers` = {(lp 1-7, statement 1|2): 'yes' | 'not_yet'}. One bad
    value refuses the whole request. A statement not in `answers` keeps what it had."""
    p, d, key, args = _gh_lm_guard(db, u, pid)
    if key:
        return False, key, args
    clean = {}
    for (lp, st), v in (answers or {}).items():
        if lp not in range(1, 8) or st not in (1, 2) or v not in ("yes", "not_yet"):
            return False, "m_bad_answer", {}
        clean[(lp, st)] = v
    for (lp, st), v in clean.items():
        cur = db.execute("UPDATE gradeh_lp_answers SET answer=?, updated_at=datetime('now') WHERE cycle_id=? AND person_id=? "
                         "AND lp=? AND stmt=?", (v, p["cycle_id"], p["id"], lp, st))
        if not cur.rowcount:
            db.execute("INSERT INTO gradeh_lp_answers(cycle_id, person_id, lp, stmt, answer) VALUES (?,?,?,?,?)",
                       (p["cycle_id"], p["id"], lp, st, v))
    _gh_lm_touch(db, p)
    db.commit()
    return True, "m_saved", {}


def gradeh_lm_save_kpis(db, u, pid, figures):
    """THE writer of the line manager's KPI moderation (KPI route). `figures` = {line id: {"pct": typed text, "reason": text,
    "rating": typed 1-5}}. Every line posted is checked: a figure is 0 to GRADEH_PCT_MAX; changing the person's own figure
    needs a reason (screened, 300 words); a line on another group's scale needs the line manager's own 1-5 rating. A figure
    that equals theirs is stored as no change (lm_pct NULL) and the line is marked checked (lm_at). Nothing here works out
    a total: gradeh_computed does, from what is stored. One bad line refuses the whole request."""
    p, d, key, args = _gh_lm_guard(db, u, pid)
    if key:
        return False, key, args
    if p["route"] != "A":
        return False, "m_route", {}
    lines = {l["id"]: l for l in d["lines"]}
    plan = []
    for lid, f in (figures or {}).items():
        l = lines.get(lid)
        if l is None:
            return False, "m_not_line", {}
        nm = l["kpi_name"]
        if l["bu_kpi_id"]:   # a line that shares a unit's result is Group People's: nothing typed here is kept (Chris, 2026-11-03)
            return False, "m_shared", {"kpi": nm}
        if l["group_scale"] == "OTHER":
            t = str((f or {}).get("rating") or "").strip()
            if not re.fullmatch(r"[1-5]", t):
                return False, "m_rating_need", {"kpi": nm}
            plan.append((l, None, None, int(t)))
            continue
        v, err = gradeh_parse_pct((f or {}).get("pct"))
        if err:
            return False, "m_fig_range", {"max": GRADEH_PCT_MAX, "kpi": nm}
        if v is None:
            v = l["staff_pct"]   # left blank: theirs stands
        if v is None:
            return False, "m_fig_need", {"kpi": nm}
        changed = l["staff_pct"] is None or abs(v - l["staff_pct"]) > 1e-9
        reason_raw = " ".join(str((f or {}).get("reason") or "").split())
        reason = None
        if changed and l["staff_pct"] is not None and not reason_raw:
            return False, "m_reason", {"kpi": nm, "v": _gh_pct_str(l["staff_pct"])}
        if changed and reason_raw:
            reason, rerr = gradeh_text_check(reason_raw, "reason", required=True)
            if rerr:
                return (False, "m_reason_bad", {"kpi": nm}) if "instruction" in rerr else (False, "m_text", {"err": rerr})
        plan.append((l, v if changed else None, reason if changed else None, None))
    now = _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    for l, v, reason, rating in plan:
        cur = db.execute("UPDATE gradeh_kpi_entries SET lm_pct=?, lm_reason=?, lm_rating=?, lm_at=? WHERE line_id=?",
                         (v, reason, rating, now, l["id"]))
        if not cur.rowcount:
            db.execute("INSERT INTO gradeh_kpi_entries(cycle_id, person_id, line_id, lm_pct, lm_reason, lm_rating, lm_at) "
                       "VALUES (?,?,?,?,?,?,?)", (p["cycle_id"], p["id"], l["id"], v, reason, rating, now))
    _gh_lm_touch(db, p)
    db.commit()
    return True, "m_saved", {}


# Section B and the two answers beside it live in one writer: the three comments, the promotion nomination (Group People
# only) and the performance-conversation tick. A field the request does not send keeps what it had (absent is not empty).
GRADEH_B_TEXT = (("ach", "b_achievements", "achievements"), ("str", "b_strengths", "strengths"),
                 ("dev", "b_development", "development plan"),
                 ("promo_reason", "promo_reason", "reason"))


def gradeh_lm_save_sectionb(db, u, pid, fields, commit=True):
    """THE writer of Section B (achievements, strengths, development plan),
    the promotion nomination ('no' | 'yes' + reason) and the conversation tick. `fields` keys: ach, str, dev,
    promo, promo_reason, conv ('1'/'0'). A draft may leave texts blank; each is at most 300 words and screened. The
    nomination reason is cleared when the nomination is No. Does not submit."""
    p, d, key, args = _gh_lm_guard(db, u, pid)
    if key:
        return False, key, args
    sets = {}
    for f, col, what in GRADEH_B_TEXT:
        if f in fields:
            clean, err = gradeh_text_check(fields.get(f), what, required=False)
            if err:
                return False, "m_text", {"err": err}
            sets[col] = clean or None
    if "promo" in fields:
        t = str(fields.get("promo") or "").strip()
        if t not in ("no", "yes"):
            return False, "m_bad_promo", {}
        sets["promo_nominate"] = t
        if t == "no":
            sets["promo_reason"] = None
    if "conv" in fields:
        sets["conversation_held"] = 1 if str(fields.get("conv")) in ("1", "on", "true", "yes") else 0
    if sets:
        _gh_lm_touch(db, p)
        db.execute("UPDATE gradeh_appraisals SET %s, updated_at=datetime('now') WHERE cycle_id=? AND person_id=?"
                   % ", ".join("%s=?" % c for c in sets), list(sets.values()) + [p["cycle_id"], p["id"]])
    if commit:
        db.commit()
    return True, "m_saved", {}


def gradeh_lm_blockers(db, person, d=None):
    """[(todo key, args)] still in the way of a submit: every step's answers, Section B, the nomination's reason, the tick, and
    anything gradeh_computed cannot work out (weights, a missing figure). Empty = ready. Reads only."""
    d = d or _gh_lm_bulk(db, person["cycle_id"], [person])[person["id"]]
    a = d["app"]
    out = []
    prog = gradeh_lm_progress(person, d)
    if person["route"] == "B" and not prog["attrs"]["done"]:
        out.append(("todo_attr", {"n": prog["attrs"]["n"]}))
    if person["route"] == "A" and not prog["kpis"]["done"]:
        out.append(("todo_kpi", {"n": prog["kpis"]["n"], "m": prog["kpis"]["m"]}))
    if not prog["lp"]["done"]:
        out.append(("todo_lp", {"n": prog["lp"]["n"]}))
    if not prog["comments"]["done"]:
        out.append(("todo_cm", {"n": prog["comments"]["n"]}))
    if a and a["promo_nominate"] == "yes" and not (a["promo_reason"] or "").strip():
        out.append(("todo_promo", {}))
    if not (a and a["conversation_held"]):
        out.append(("todo_conv", {}))
    if not out:
        c = gradeh_computed(db, person["cycle_id"], person["id"])
        for pr in c["problems"]:
            out.append(("todo_calc", {"what": pr.rstrip(".")}))
    return out


_GH_WEEKDAYS = {"en": ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"),
                "bm": ("Isn", "Sel", "Rab", "Kha", "Jum", "Sab", "Ahad")}   # Max's draft: a BM speaker checks them


def gh_day_words(dt, lang, time=False):
    """'Sun 29 Nov' / 'Ahad 29 Nov' (a MYT datetime), with ', 11:59 pm' / ', 11:59 malam' when `time`; '' for None."""
    if not dt:
        return ""
    lang = lang if lang in GRADEH_LANGS else "en"
    out = "%s %d %s" % (_GH_WEEKDAYS[lang][dt.weekday()], dt.day, _GH_MONTHS[lang][dt.month - 1])
    return out + (", " + _gh_time(dt, lang)) if time else out


def gradeh_staff_case(db, person, cid, now=None):
    """What waits on one Grade H person, for their reminder: {case 'kpi'|'ack', cell, closes (MYT datetime), deemed (MYT
    datetime or None)} or None. 'kpi' = Route A, nothing sent, the KPI part open, a close date; 'ack' = the line manager has
    submitted, nobody has acknowledged, the acknowledge part is open and its deadline (the earlier of the deemed deadline,
    which gradeh_deemed_deadline alone knows, and the part's close) has not passed. A person with no date to name gets none."""
    now = now or _now_myt()
    st = gradeh_staff_state(db, person)
    if st["step"] == "kpi" and person["route"] == "A" and not st["sent"]:
        if window_state(db, GRADEH_CELL_KPI, cid, now) != "open":
            return None
        c = _parse_when(window_dates(db, GRADEH_CELL_KPI, cid)[1])
        return {"case": "kpi", "cell": GRADEH_CELL_KPI, "closes": c, "deemed": None} if c else None
    if st["step"] == "ack" and st["app"] and st["app"]["lm_submitted_at"]:
        if window_state(db, GRADEH_CELL_ACK, cid, now) != "open":
            return None
        at = st["app"]["lm_submitted_at"]
        dl = gradeh_ack_deadline(db, cid, at)
        if not dl or dl < now:
            return None
        return {"case": "ack", "cell": GRADEH_CELL_ACK, "closes": dl, "deemed": _gh_myt(gradeh_deemed_deadline(db, cid, at))}
    return None


def gradeh_staff_due(db, cid, case, day, rules):
    """Is `day` a day this person's own email goes: the day their part opens (the reminder's on-open rule), or the days
    before it closes (the rule's days; for acknowledging, before the earlier of their deemed deadline and the part's close)."""
    o = _parse_when(window_dates(db, case["cell"], cid)[0])
    if rules["on_open"] and o and o.date() == day:
        return True
    return (case["closes"].date() - day).days in rules["days_before"]


def _gradeh_staff_item(case):
    """A Grade H person's own thing as an item in the leader email they already get (one email a day, in English like the
    rest of that email)."""
    return {"group": "gradeh", "role": "gradeh_staff", "text": "Enter your KPI achievement" if case["case"] == "kpi"
            else "Read and acknowledge your appraisal", "detail": "", "closes": "", "closes_on": case["closes"].date(),
            "url": url_for("my_appraisal"), "people": []}


def reminder_items_with_staff(db, u, cyc, honour_skips=True):
    """The items Everyone's reminder lists for `u`, and, when they have any and are on the Grade H list with something
    waiting, that one more: their own Grade H item rides in the email they already get, so a Grade H supervisor who is also
    a leader gets ONE email, not two. Nothing added where Grade H does not run or nobody else's item is waiting."""
    items = reminder_items_email(db, u, honour_skips=honour_skips)   # the email: a Grade H leader's item only on their own days (2026-11-06)
    if items and cyc and gradeh_mail_ok(db, cyc, honour_skips=honour_skips):
        person = gradeh_staff_person(db, u, cyc["id"])
        case = gradeh_staff_case(db, person, cyc["id"]) if person else None
        if case:
            items = items + [_gradeh_staff_item(case)]
    return items


def gradeh_reminder_in_cooldown(db, user_id, cycle_id, hours=REMINDER_COOLDOWN_HOURS):
    """One email a person a day across both reminders: true if either kind was queued or sent to them in the window."""
    kinds = (REMINDER_KIND, GRADEH_REMINDER_KIND)
    ph = ",".join("?" * len(kinds))
    if db.execute("SELECT 1 FROM email_outbox WHERE user_id=? AND cycle_id=? AND kind IN (%s) AND (status IN ('queued','sending') "
                  "OR (status='sent' AND created_at > datetime('now', ?))) LIMIT 1" % ph,
                  (user_id, cycle_id) + kinds + ("-%d hours" % hours,)).fetchone():
        return True
    return bool(db.execute("SELECT 1 FROM notifications WHERE user_id=? AND cycle_id=? AND kind IN (%s) AND status='sent' AND "
                           "pending_count IS NOT NULL AND created_at > datetime('now', ?) LIMIT 1" % ph,
                           (user_id, cycle_id) + kinds + ("-%d hours" % hours,)).fetchone())


def _gradeh_reminder_mail(db, person_user, lang, case, cycle_name, tpl=None):
    """(subject, html) of a Grade H person's own reminder, in their language: the KPI achievement not sent, or the appraisal
    to acknowledge (with the amber deemed line only while a deemed deadline exists). A link only: no band, rating or comment."""
    t = tpl or email_tpl_words(GRADEH_REMINDER_KIND, db=db)
    lang = lang if lang in GRADEH_LANGS else "bm"
    sfx = "_bm" if lang == "bm" else ""
    kind = case["case"]
    vals = dict(email_names(db, person_user), cycle=cycle_name, closes=gh_day_words(case["closes"], lang),
                closes_at=gh_day_words(case["closes"], lang, time=True),
                deemed_at=gh_day_words(case.get("deemed"), lang, time=True))
    fill = lambda k: _tpl_fill(t.get(k + sfx) or t.get(k) or "", vals)   # noqa: E731
    one = (lambda k: k) if kind == "kpi" else (lambda k: k + "_ack")   # the KPI case's words are the plain keys
    body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill(one("opening"))))]
    if kind == "ack" and case.get("deemed") and fill("deemed_ack"):
        body.append('<table role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" class="oh-warn" '
                    'style="margin:0 0 14px;background:#fdf3df;border:1px solid #f1dfb5;border-radius:8px;border-collapse:separate">'
                    '<tr><td class="oh-warn-t" style="padding:8px 10px;font:13px/1.5 %s;color:#7a4b00">%s</td></tr></table>'
                    % (_EM_FONT, _em_esc(fill("deemed_ack"))))
    return fill(one("subject")), onehr_email(
        fill("heading"), "".join(body), button=(fill("button"), app_base_url() + url_for("my_appraisal")),
        sub=fill(one("sub")), cycle=cycle_name, footer=fill("footer"))


GRADEH_READY_KIND = "gradeh_ready"


def _gradeh_ready_mail(db, person_user, lang, cycle_name, tpl=None):
    """(subject, html) of the staff "your appraisal is ready to read" email, in the person's language. A link only: no band, no
    rating, no comment, no name but their own."""
    t = tpl or email_tpl_words(GRADEH_READY_KIND, db=db)
    sfx = "_bm" if lang == "bm" else ""
    vals = dict(email_names(db, person_user), cycle=cycle_name)
    fill = lambda k: _tpl_fill(t.get(k + sfx) or t.get(k) or "", vals)   # noqa: E731
    body = [_em_greet(fill("greeting")), _em_p(_em_esc(fill("opening")))]
    if fill("closing"):
        body.append(_em_p(_em_esc(fill("closing"))))
    return fill("subject"), onehr_email(
        fill("heading"), "".join(body), button=(fill("button"), app_base_url() + url_for("my_appraisal")),
        sub=fill("sub"), cycle=cycle_name, footer=fill("footer"))


def gradeh_queue_ready_email(db, person, now_utc=None):
    """Queue the staff "your result is ready to read" email once for this person and cycle, in waves like every mass email
    (the count of this kind still waiting sets the wave). Returns 'queued' | 'no_email' | 'no_mail' (this server sends none) |
    'already'. Does not commit."""
    if not mailer.is_configured():
        return "no_mail"
    pu = db.execute("SELECT * FROM users WHERE id=?", (person["user_id"],)).fetchone()
    if not pu or not (pu["email"] or "").strip():
        return "no_email"
    if db.execute("SELECT 1 FROM email_outbox WHERE kind=? AND user_id=? AND cycle_id=? AND status!='cancelled'",
                  (GRADEH_READY_KIND, pu["id"], person["cycle_id"])).fetchone():
        return "already"
    cyc = db.execute("SELECT name FROM cycles WHERE id=?", (person["cycle_id"],)).fetchone()
    lang = person["language"] if person["language"] in GRADEH_LANGS else "bm"
    subj, body = _gradeh_ready_mail(db, pu, lang, (cyc["name"] if cyc else "") or "")
    waiting = db.execute("SELECT COUNT(*) FROM email_outbox WHERE kind=? AND status='queued'", (GRADEH_READY_KIND,)).fetchone()[0]
    start = _parse_when(now_utc) if now_utc else _utc_now()
    _outbox_add(db, GRADEH_READY_KIND, pu["email"].strip(), subj, body, user_id=pu["id"], cycle_id=person["cycle_id"],
                detail="appraisal ready", send_after=_email_wave_at(waiting, email_wave_rules(), start),
                batch="gradeh-ready-" + _utc_now().strftime("%Y%m%d"))
    return "queued"


def gradeh_lm_submit(db, u, pid, fields=None, now_utc=None):
    """THE writer of the line manager's submit (final). Checks everything again from what is stored: every attribute / KPI line
    and the 14 statements answered, the four Section B answers, a reason for a nomination, the conversation tick, KPI weights
    that total 100 (gradeh_computed). `fields` (the promotion nomination and the tick posted with the button) are saved by
    gradeh_lm_save_sectionb in the same step. Stores the computed result exactly as gradeh_computed returns it and sets
    lm_submitted_at LAST; then queues the staff email once. Returns (ok, key, args); args carries the email outcome."""
    p, d, key, args = _gh_lm_guard(db, u, pid)
    if key:
        return False, key, args
    if fields:
        ok, key, args = gradeh_lm_save_sectionb(db, u, pid, fields, commit=False)
        if not ok:
            db.rollback()
            return False, key, args
    d = _gh_lm_bulk(db, p["cycle_id"], [p])[p["id"]]
    todo = gradeh_lm_blockers(db, p, d)
    if todo:
        db.rollback()
        return False, "m_needs", {"what": "; ".join(gh_lm_t("en", k, **a_) for k, a_ in todo)}
    c = gradeh_computed(db, p["cycle_id"], p["id"])
    # a line that shares a unit's BU KPI result still waiting for Group People's figure does NOT stop the submit (Chris, 2026-11-03: the
    # line manager submits as today): the performance result is stored empty and Group People's fill works it out (gradeh_bu_fill)
    if c["problems"] or (c["perf_band"] is None and not c["shared_wait"]) or c["pot_band"] is None:
        db.rollback()
        return False, "m_needs", {"what": "; ".join(c["problems"]) or "the result cannot be worked out"}
    now = now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    _gh_lm_touch(db, p)
    _gh_store_perf(db, p["cycle_id"], p["id"], c)   # the one place a performance result is stored (the shared-figure re-score calls it too)
    db.execute("UPDATE gradeh_appraisals SET pot_score=?, pot_band=?, lm_submitted_by=?, updated_at=datetime('now') "
               "WHERE cycle_id=? AND person_id=?", (c["pot_score"], c["pot_band"], u["id"], p["cycle_id"], p["id"]))
    db.execute("UPDATE gradeh_appraisals SET lm_submitted_at=? WHERE cycle_id=? AND person_id=? AND lm_submitted_at IS NULL",
               (now, p["cycle_id"], p["id"]))
    email = gradeh_queue_ready_email(db, p, now_utc=now_utc)
    db.commit()
    if email == "queued":
        _outbox_kick()
    log_activity(db, u["id"], "gradeh_lm_submit", "person %d" % p["id"], target_user_id=p["user_id"])
    return True, "m_submitted", {"email": email}


def gradeh_lm_ack_in_person(db, u, pid, on_raw, now_utc=None, agrees=True, reason=None):
    """THE writer of "Acknowledged in person" with the date of the talk, by the line manager after the submit. `agrees`: whether the
    person agreed (the default, as before); False records "They do not agree" with `reason` (their words, required) through
    gradeh_record_disagree: the same ticket and the same lock out of calibration as the person's own "I do not agree". Refused: not
    their appraisee; not submitted yet; already acknowledged, deemed acknowledged (the deadline has passed) or recorded; a date
    that is not a date, in the future, or more than a year ago (the gates are _gh_ack_gate). The deemed step runs first, as on the
    staff page."""
    p, d, key, args = _gh_lm_guard(db, u, pid, editing=False)
    if key:
        return False, key, args
    now = now_utc or _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    gate = _gh_ack_gate(db, p, now, False)
    if gate:
        return False, GRADEH_ACK_GATE_LM[gate[0]], gate[1]
    try:
        day = datetime.strptime(str(on_raw or "").strip()[:10], "%Y-%m-%d").date()
    except ValueError:
        return False, "m_ack_date", {}
    today = (_parse_when(now) + timedelta(hours=8)).date()
    if day > today or day < today - timedelta(days=366):
        return False, "m_ack_date", {}
    if not agrees:
        return gradeh_record_disagree(db, p, u, reason, via="lm", day=day, now_utc=now)
    a = _gh_appraisal(db, p)
    db.execute("UPDATE gradeh_appraisals SET ack_in_person=1, ack_in_person_on=?, ack_in_person_by=?, "
               "updated_at=datetime('now') WHERE id=? AND acknowledged_at IS NULL AND deemed_at IS NULL AND ack_in_person=0",
               (day.isoformat(), u["id"], a["id"]))
    db.commit()
    log_activity(db, u["id"], "gradeh_lm_ack", "person %d" % p["id"], target_user_id=p["user_id"])
    return True, "m_ack_ok", {"d": gh_when(datetime(day.year, day.month, day.day), "en", time=False)}


# "Help me word this": the AI drafts words into the box, only. It never rates, never saves and never submits. The draft is
# screened like every message (screen_message first), carries the OneHR scope guard, and the caller puts the text in the box
# for the line manager to keep, change or throw away. Without the AI, or on any failure, the route says so and nothing is lost.
GRADEH_HELP_FIELDS = {"ach": "what this person achieved in the period", "str": "this person's strengths",
                      "dev": "a development plan for this person for the coming year",
                      "promo_reason": "why this person is nominated for promotion, with examples of work already done at "
                                      "the higher level"}


def gradeh_lm_help(db, u, pid, field, text, instruction=""):
    """(ok, text_or_key, args): a drafted wording for one comment box. The text is the model's words only (never stored here);
    a refusal is a GRADEH_LM_T key. Uses ai_draft.draft_pm_manager; the caller's draft and instruction are screened first."""
    p, d, key, args = _gh_lm_guard(db, u, pid, editing=True)
    if key:
        return False, key, args
    if field not in GRADEH_HELP_FIELDS:
        return False, "m_bad_attr", {}
    text = " ".join((text or "").split())[:2000]
    instruction = " ".join((instruction or "").split())[:300]
    if ai_draft.screen_message(text) or ai_draft.screen_message(instruction):
        return False, "m_text", {"err": "Reword that: it reads like an instruction rather than a comment."}
    ctx = ("about a Grade H (non-executive, operations) colleague's year-end appraisal: write %s. Plain, specific and "
           "factual, short sentences a supervisor would use. Do not invent facts, names, numbers or events; if the draft "
           "has none, give a short frame the writer fills with a real example. Never give a rating or a promotion "
           "decision. " % GRADEH_HELP_FIELDS[field]) + _AGENT_SCOPE_GUARD
    if not ai_draft.is_configured():
        return False, "help_off", {}
    try:
        out = ai_draft.draft_pm_manager(text, instruction or "Help me word this.", context=ctx, max_tokens=500, timeout=25)
    except ai_draft.AIDraftNotConfigured:
        return False, "help_off", {}
    except ai_draft.AIDraftError as e:
        app.logger.warning("Grade H word help failed: %s", e)
        return False, "help_fail", {}
    out = " ".join((out or "").split())
    clean, err = gradeh_text_check(out, "wording", required=True)
    if err:
        return False, "help_fail", {}
    log_activity(db, u["id"], "ai_draft", "gradeh " + field)
    return True, clean, {}


# --- what the person's appraisal page draws (L2-L7). Built here; the template computes nothing. ---------------------------
GRADEH_SCALE_RULE = {
    "FIAMMA": {1: "up to 60%", 2: "61-80%", 3: "81-100%", 4: "101-120%", 5: "121% and over"},
    "SIGNATURE": {1: "under 80%", 2: "80% to under 95%", 3: "95% to under 110%", 4: "110% to under 130%", 5: "130% and over"},
}
_GH_NUM_OF = {c_: k_ for k_, c_ in GRADEH_BCODE.items()}


def _gh_band_words(band, lang):
    """'3 · Meets Expectation' for a performance band code, else ''."""
    n = _GH_NUM_OF.get(band)
    return ("%d · %s" % (n, GRADEH_RATING_LABELS[n][1 if lang == "bm" else 0])) if n else ""


def gradeh_lm_default_step(person, prog, submitted):
    if submitted:
        return "submit"
    first = "attrs" if person["route"] == "B" else "kpis"
    for k in (first, "lp", "comments"):
        if not prog[k]["done"]:
            return k
    return "submit"


def gradeh_lm_person_view(db, u, p, step, lang, form=None, open_item=None):
    """Everything one person's appraisal page draws. `form` = values to show instead of the stored ones (a refused save keeps what
    was typed). `open_item` = the attribute / Principle the page opens (else the first not done). Reads only."""
    form = form or {}
    cid = p["cycle_id"]
    d = _gh_lm_bulk(db, cid, [p])[p["id"]]
    a = d["app"]
    submitted = bool(a and a["lm_submitted_at"])
    prog = gradeh_lm_progress(p, d)
    first = "attrs" if p["route"] == "B" else "kpis"
    step = step if step in GRADEH_LM_STEPS and (step != ("kpis" if first == "attrs" else "attrs")) else None
    step = step or gradeh_lm_default_step(p, prog, submitted)
    if submitted:
        step = "submit"
    name = proper_name((p["full_name"] or "").strip())
    i = 1 if lang == "bm" else 0
    kw = gradeh_window_closed(db, GRADEH_CELL_KPI, cid)
    kpi_closed = bool(kw and kw[0] == "closed")
    st = gradeh_lm_status(db, p, d, kpi_closed)
    comp = gradeh_computed(db, cid, p["id"]) if not submitted else None
    v = {"lang": lang, "id": p["id"], "name": name, "route": p["route"], "step": step, "submitted": submitted,
         "title": proper_name((p["job_title"] or "").strip()),
         "unit": display_company(p["business_group"], p["company"]) if p["company"] else "",
         "chip": gh_lm_t(lang, "chip_kpi" if p["route"] == "A" else "chip_lm"), "status": st,
         "status_text": gradeh_lm_status_text(db, p, st, lang), "kpi_closed": kpi_closed}
    # --- the stepper: short labels, one line each, with how far each is
    keys = [first, "lp", "comments", "submit"]
    cur_i = keys.index(step)
    steps = []
    for n_, k in enumerate(keys):
        pr = prog.get(k)
        if k == "kpis":
            cnt = ("%d / %d" % (pr["n"], pr["m"])) if (pr["done"] or submitted) else gh_lm_t(lang, "s_lines", n=pr["m"]) if pr["m"] != 1 else gh_lm_t(lang, "s_line")
        elif pr:
            cnt = "%d / %d" % (pr["n"], pr["m"])
        else:
            cnt = ""
        done = bool(pr and pr["done"]) or (k == "submit" and submitted)
        steps.append({"key": k, "label": gh_lm_t(lang, {"attrs": "s_attrs", "kpis": "s_kpis", "lp": "s_lp",
                                                         "comments": "s_cm", "submit": "s_sub"}[k]),
                      "title": gh_lm_t(lang, {"attrs": "s_attrs_t", "kpis": "s_kpis_t", "lp": "s_lp_t", "comments": "s_cm_t",
                                              "submit": "s_sub_t"}[k]),
                      "count": cnt, "state": "now" if k == step else ("done" if done else "todo"),
                      "url": url_for("review_gradeh_person", pid=p["id"], step=k)})
    v["steps"] = steps
    v["next_labels"] = [s_["title"] for s_ in steps[cur_i + 1:]]
    # a KPI line that shares a unit's result (2026-11-03) and Group People has not filled: no weighted achievement, no rating, "Waiting for
    # 1 line" (a partial figure is never a total); the line manager still submits
    sh_wait = [l for l in d["lines"] if _gh_shared_wait(l)] if p["route"] == "A" else []
    scale0 = d["lines"][0]["group_scale"] if d["lines"] else "FIAMMA"
    v["wait"] = ({"head": gh_lm_t(lang, "wait_line1") if len(sh_wait) == 1 else gh_lm_t(lang, "wait_lines", n=len(sh_wait)),
                  "sub": gh_lm_t(lang, "wait_sub", kpi=", ".join(l["kpi_name"] for l in sh_wait),
                                 w=_gh_pct_str(sum(l["weight"] for l in sh_wait))),
                  "rating_sub": (gh_lm_t(lang, "rating_wait_rated") if scale0 in GRADEH_BU_RATED_SCALES
                                 else gh_lm_t(lang, "rating_wait", scale=scale0)),
                  "not_final": gh_lm_t(lang, "not_final_wait")} if sh_wait else None)
    # --- results as the server works them out (a draft's, from what is stored; a submit's, as it was stored)
    def result(perf_band, perf_rating, perf_value, pot_band, pot_score, problems):
        out = {"perf": None, "pot": None, "perf_wait": None, "pot_wait": None, "perf_wait_sub": ""}
        if perf_band:
            n = _GH_NUM_OF.get(perf_band)
            note = ""
            if p["route"] == "B":
                note = gh_lm_t(lang, "perf_attr_note", avg="%.2f" % float(perf_rating))
            elif perf_value is not None:
                scale = (d["lines"][0]["group_scale"] if d["lines"] else "FIAMMA")
                note = gh_lm_t(lang, "perf_kpi_note", scale=scale, rule="%s is %d" % (GRADEH_SCALE_RULE.get(scale, {}).get(n, ""), n))
            else:
                note = gh_lm_t(lang, "perf_kpi_other", avg="%.2f" % float(perf_rating))
            out["perf"] = {"words": _gh_band_words(perf_band, lang), "band": perf_band, "note": note,
                           "value": ("%s%%" % _gh_pct_str(perf_value)) if perf_value is not None else None}
        elif sh_wait:
            out["perf_wait"], out["perf_wait_sub"] = "—", v["wait"]["rating_sub"]
        else:
            out["perf_wait"] = gh_lm_t(lang, "perf_wait_attr" if p["route"] == "B" else "perf_kpi_wait")
        if pot_band:
            yes = d["n_lp"] and db.execute("SELECT COUNT(*) FROM gradeh_lp_answers WHERE cycle_id=? AND person_id=? AND "
                                           "answer='yes'", (cid, p["id"])).fetchone()[0]
            out["pot"] = {"word": GRADEH_POT_WORDS[pot_band][i], "band": pot_band,
                          "note": gh_lm_t(lang, "pot_note", n=yes, s=("%g" % pot_score), m=("%g" % gradeh_lp_max(cid)))}
        else:
            out["pot_wait"] = gh_lm_t(lang, "pot_wait")
        return out
    if submitted:
        v["result"] = result(a["perf_band"], a["perf_rating"], a["perf_value"], a["pot_band"], a["pot_score"], [])
    else:
        v["result"] = result(comp["perf_band"], comp["perf_rating"], comp["perf_value"], comp["pot_band"], comp["pot_score"],
                             comp["problems"])
    # --- step 1 (Route B): the eight attributes
    if step == "attrs":
        rs = {r["attr_key"]: r["rating"] for r in db.execute(
            "SELECT attr_key, rating FROM gradeh_ratings WHERE cycle_id=? AND person_id=?", (cid, p["id"]))}
        want = open_item if open_item in range(1, 9) else next((n_ for n_, at in enumerate(GRADEH_ATTRIBUTES, 1)
                                                                if at["key"] not in rs), None)
        attrs = []
        for n_, at in enumerate(GRADEH_ATTRIBUTES, 1):
            r_ = rs.get(at["key"])
            attrs.append({"n": n_, "key": at["key"], "title": at["title"][i], "question": at["question"][i], "rating": r_,
                          "label": ("%d · %s" % (r_, GRADEH_RATING_LABELS[r_][i])) if r_ else "",
                          "said": at["descriptors"][r_][i] if r_ else "", "open": n_ == want,
                          "next": n_ == (want or 0) + 1 and want is not None,
                          "levels": [{"r": k_, "label": GRADEH_RATING_LABELS[k_][i], "text": at["descriptors"][k_][i]}
                                     for k_ in (1, 2, 3, 4, 5)]})   # 1 to 5 across; a phone stacks the best first
        unrated = [x["n"] for x in attrs if not x["rating"]]
        for x in attrs:   # after a pick the page goes to the first one still to rate (not this one), else stays put
            x["next_a"] = next((m for m in unrated if m != x["n"]), "")
        v["attrs"] = attrs
        v["attrs_rest"] = ", ".join(at["title"][i] for n_, at in enumerate(GRADEH_ATTRIBUTES, 1) if want and n_ > want + 1)
        v["prev_url"] = None
    # --- step 1 (Route A): KPI moderation
    if step == "kpis":
        v["kpis"] = []
        for l in d["lines"]:
            fv = form.get("f_%d" % l["id"])
            eff = l["lm_pct"] if l["lm_pct"] is not None else l["staff_pct"]
            changed = l["lm_pct"] is not None and (l["staff_pct"] is None or abs(l["lm_pct"] - l["staff_pct"]) > 1e-9)
            if fv is not None:   # a refused save comes back with what was typed: "same" follows the typed figure, not the stored one
                tv, terr = gradeh_parse_pct(fv)
                changed = bool(terr) or (tv is not None and (l["staff_pct"] is None or abs(tv - l["staff_pct"]) > 1e-9))
            shared = bool(l["bu_kpi_id"])
            v["kpis"].append({"id": l["id"], "name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]), "scale": l["group_scale"],
                              "shared": shared, "shared_fig": _gh_shared_fig(l, lang) if shared else "",
                              "shared_why": (gh_lm_t(lang, "shared_why_on", d=gh_when(_gh_myt(l["bu_filled_at"]), lang, time=False, year=False))
                                             if shared and _gh_shared_filled(l) and l["bu_filled_at"] else gh_lm_t(lang, "shared_why")) if shared else "",
                              "staff": _gh_pct_str(l["staff_pct"]) if l["staff_pct"] is not None else "",
                              "yours": fv if fv is not None else (_gh_pct_str(eff) if eff is not None else ""),
                              "reason": form.get("w_%d" % l["id"], l["lm_reason"] or "" if changed else ""),
                              "rating": form.get("r_%d" % l["id"], l["lm_rating"] or ""), "changed": changed,
                              "checked": l["lm_at"] is not None})
        v["kpi_note"] = (a["staff_note"] or "").strip() if a else ""
        v["kpi_scale"] = d["lines"][0]["group_scale"] if d["lines"] else "FIAMMA"
        v["kpi_other"] = v["kpi_scale"] == "OTHER"
        v["kpi_pending"] = any(l["staff_pct"] is None and not l["bu_kpi_id"] for l in d["lines"]) and v["kpi_scale"] != "OTHER"
    # --- step 2: the 14 statements
    if step == "lp":
        ans = {(r["lp"], r["stmt"]): r["answer"] for r in db.execute(
            "SELECT lp, stmt, answer FROM gradeh_lp_answers WHERE cycle_id=? AND person_id=?", (cid, p["id"]))}
        want = open_item if open_item in range(1, 8) else next((lp["n"] for lp in GRADEH_LP
                                                                if any((lp["n"], s_["n"]) not in ans for s_ in lp["statements"])), None)
        lps = []
        for lp in GRADEH_LP:
            yes = sum(1 for s_ in lp["statements"] if ans.get((lp["n"], s_["n"])) == "yes")
            no = sum(1 for s_ in lp["statements"] if ans.get((lp["n"], s_["n"])) == "not_yet")
            lps.append({"n": lp["n"], "title": lp["title"][i], "yes": yes, "no": no, "answered": yes + no,
                        "open": lp["n"] == want, "done": yes + no == 2,
                        "note": lp["manager_note"][i],
                        "stmts": [{"n": s_["n"], "text": s_["text"][i], "answer": ans.get((lp["n"], s_["n"])),
                                   "examples": [e[i] for e in s_["examples"]]} for s_ in lp["statements"]]})
        v["lps"] = lps
    # --- step 3: the comments
    ach_v = (a["b_achievements"] if a else None) or ""
    if step in ("comments", "submit"):
        def pick(k, col):
            return form[k] if k in form else ((a[col] if a else None) or "")
        v["cm"] = {"ach": pick("ach", "b_achievements"), "str": pick("str", "b_strengths"),
                   "dev": pick("dev", "b_development")}
    # --- step 4: nomination, the tick, what is still in the way
    if step == "submit":
        v["promo"] = form.get("promo") or ((a["promo_nominate"] if a else None) or "no")
        v["promo_reason"] = form["promo_reason"] if "promo_reason" in form else ((a["promo_reason"] if a else None) or "")
        v["conv"] = (str(form.get("conv")) in ("1", "on")) if "conv" in form else bool(a and a["conversation_held"])
        if not submitted:
            todo = gradeh_lm_blockers(db, p, d)
            # the nomination's reason and the tick travel with the Submit button, so the page does not list them
            todo = [t_ for t_ in todo if t_[0] not in ("todo_promo", "todo_conv")]
            v["todo"] = [gh_lm_t(lang, k, **a_) if k != "todo_calc" else a_["what"] for k, a_ in todo]
            v["can_submit"] = not todo
        else:
            sub_at = _gh_myt(a["lm_submitted_at"])
            v["submitted_on"] = gh_when(sub_at, lang, time=False)
            v["promo_yes"] = bool(a["promo_nominate"] == "yes")
            kind = st["key"]
            v["dis"] = bool(st.get("dis"))
            v["ack"] = {"open": st["kind"] == "submitted", "kind": st["kind"],
                        "text": (gh_lm_t(lang, {"st_ack_self": "ack_dis_self" if v["dis"] else "ack_done", "st_ack_deemed": "ack_deemed",
                                                "st_ack_person": "ack_dis_person" if v["dis"] else "ack_person"}[kind],
                                         d=(gh_when(_parse_when(st["when"]) if kind == "st_ack_person" else _gh_myt(st["when"]),
                                                    lang, time=False) if st["when"] else ""), name=name)
                                 if kind in ("st_ack_self", "st_ack_deemed", "st_ack_person") else ""),
                        "today": _today_myt().isoformat()}
            # the read-only recap of what was rated
            if p["route"] == "B":
                rs = {r["attr_key"]: r["rating"] for r in db.execute(
                    "SELECT attr_key, rating FROM gradeh_ratings WHERE cycle_id=? AND person_id=?", (cid, p["id"]))}
                v["recap_attrs"] = [{"title": at["title"][i], "rating": rs.get(at["key"]),
                                     "label": GRADEH_RATING_LABELS[rs[at["key"]]][i] if rs.get(at["key"]) else ""}
                                    for at in GRADEH_ATTRIBUTES]
            else:
                v["recap_kpis"] = []
                for l in d["lines"]:
                    if l["bu_kpi_id"]:   # Group People's figure, and "Updated on" when it came after the submit
                        upd = ""
                        if _gh_shared_filled(l) and (l["bu_filled_at"] or "") >= a["lm_submitted_at"]:
                            upd = gh_lm_t(lang, "updated_on", d=gh_when(_gh_myt(l["bu_filled_at"]), lang, time=False, year=False))
                        v["recap_kpis"].append({"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]), "theirs": "",
                                                "figure": _gh_shared_fig(l, lang) or gh_lm_t(lang, "shared_pill"),
                                                "reason": upd})
                        continue
                    eff = l["lm_pct"] if l["lm_pct"] is not None else l["staff_pct"]
                    v["recap_kpis"].append({"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]),
                                            "theirs": _gh_pct_str(l["staff_pct"]) if l["staff_pct"] is not None else "",
                                            "figure": (gh_lm_t(lang, "kpi_rate") and ("%d" % l["lm_rating"]) if l["group_scale"] == "OTHER" and l["lm_rating"]
                                                       else ("%s%%" % _gh_pct_str(eff) if eff is not None else "")),
                                            "reason": (l["lm_reason"] or "") if l["lm_pct"] is not None else ""})
    v["ask"] = {"hi": gh_lm_t(lang, "ask_hi_person"), "chips": gh_lm_chips(lang)}
    return v


# --- routes ---------------------------------------------------------------------------------------------------------------
def _gh_lm_ctx():
    """(db, user, lang) for a line manager route, or a 404: the module is not running, or an account that may not use it."""
    u = current_user()
    db = get_db()
    if not gradeh_lm_cycle_id(db) or not gradeh_lm_can(db, u):
        abort(404)
    return db, u, gradeh_lm_lang(db, u)


def _gh_lm_page_ctx(db, u, lang):
    """The context every line manager page shares. A line manager who is themselves on the Grade H list keeps the staff bar
    (their language button), as on a phone (canvas L6); everyone else has OneHR's own top bar."""
    own = gradeh_staff_person(db, u)
    ctx = {"lang": lang, "html_lang": "ms" if lang == "bm" else "en", "L": (lambda key, **kw: gh_lm_t(lang, key, **kw)),
           "gh_bar": bool(own), "T": (lambda key, **kw: gh_t(lang, key, **kw)), "gh_next": GRADEH_LM_PATH,
           "lm_next": request.full_path.rstrip("?")}   # the page the BM | EN switch comes back to (_gh_lm_return checks it)
    if own:
        nm = (_row_get(u, "display_name") or "").strip() or (u["full_name"] or "").strip()
        ctx["me"] = {"initials": welcome_identity(u)["initials"], "avatar": avatar_url(_row_get(u, "avatar")),
                     "name": nm.title() if nm.isupper() else nm, "eid": _row_get(u, "employee_id") or "",
                     "title": proper_name((_row_get(u, "job_title") or "").strip()), "lang_code": "BM" if lang == "bm" else "EN"}
    return ctx


def _gh_lm_render(db, u, lang, **kw):
    ctx = _gh_lm_page_ctx(db, u, lang)
    ctx.update(kw)
    return render_template("gradeh_lm.html", **ctx)


@app.route("/review/gradeh")
@login_required
def review_gradeh():
    """L1, the team list: this account's Grade H appraisees, with where each is. Reads only."""
    db, u, lang = _gh_lm_ctx()
    t = gradeh_lm_team(db, u, request.args.get("f", "all"), lang)
    first = (welcome_identity(u).get("first_name") or "")
    by = gh_lm_t(lang, "ask_hi_team_by", d=t["closes"]) if t["closes"] else ""
    hi = gh_lm_t(lang, "ask_hi_team", n=t["n"], by=by, r=t["counts"]["ready"]) if t["n"] else gh_lm_t(lang, "none_yet")
    hi2 = gh_lm_t(lang, "ask_hi_team2") if t["n"] else ""
    w_, k_ = t["counts"]["ack"], t["counts"]["ack_noemail"]
    if w_ and k_:   # people wait to acknowledge and some have no work email: no reminder reaches them (2026-10-31, canvas L1)
        hi += " " + (gh_lm_t(lang, "ask_hi_noemail1") if w_ == 1 else
                       gh_lm_t(lang, "ask_hi_noemail_k1", w=w_) if k_ == 1 else gh_lm_t(lang, "ask_hi_noemail", w=w_, k=k_))
        hi2 = gh_lm_t(lang, "ask_hi_noemail2") + " " + hi2
    cyc = active_cycle(db)
    return _gh_lm_render(db, u, lang, view="team", t=t, first=first, cyc_name=(cyc["name"] if cyc else ""),
                         ask={"hi": hi, "hi2": hi2,
                              "chips": gh_lm_chips(lang)},
                         today=_today_myt().isoformat())


@app.route("/review/gradeh/<int:pid>")
@login_required
def review_gradeh_person(pid):
    """One person's appraisal: the step in ?step=, the open attribute / Principle in ?a= / ?lp=. Reads only."""
    db, u, lang = _gh_lm_ctx()
    p = gradeh_lm_person(db, u, pid)
    if not p:
        abort(404)
    item = request.args.get("a", type=int) or request.args.get("lp", type=int)
    v = gradeh_lm_person_view(db, u, p, request.args.get("step"), lang, open_item=item)
    return _gh_lm_render(db, u, lang, view="person", v=v, ask=v["ask"])


def _gh_lm_back(pid, step, **kw):
    return redirect(url_for("review_gradeh_person", pid=pid, step=step, **kw), 303)


def _gh_lm_after(db, u, lang, pid, ok, key, args, step, nxt=None, form=None, quiet=False, **kw):
    """After a save: say it, then go on to the next step on success, or show the same step again with what was typed (a
    refused save keeps the words). A pick that saves as it is made (a rating, an answer) is quiet: the page moving on says it."""
    say = _gh_lm_say(lang, key, args)
    if ok:
        if not quiet:
            flash(say, "ok")
        return _gh_lm_back(pid, nxt or step, **kw)
    flash(say, "error")
    p = gradeh_lm_person(db, u, pid)
    if not p:
        abort(404)
    v = gradeh_lm_person_view(db, u, p, step, lang, form=form)
    return _gh_lm_render(db, u, lang, view="person", v=v, ask=v["ask"])


@app.route("/review/gradeh/<int:pid>/ratings", methods=["POST"])
@login_required
def review_gradeh_ratings(pid):
    db, u, lang = _gh_lm_ctx()
    vals = {k[2:]: v for k, v in request.form.items() if k.startswith("r_")}
    ok, key, args = gradeh_lm_save_ratings(db, u, pid, vals)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    nxt = request.form.get("next_a", type=int)
    return _gh_lm_after(db, u, lang, pid, ok, key, args, "attrs", quiet=True, **({"a": nxt} if nxt and ok else {}))


@app.route("/review/gradeh/<int:pid>/lp", methods=["POST"])
@login_required
def review_gradeh_lp(pid):
    db, u, lang = _gh_lm_ctx()
    ans = {}
    for k, v in request.form.items():
        m = re.fullmatch(r"lp_(\d)_(\d)", k)
        if m:
            ans[(int(m.group(1)), int(m.group(2)))] = v
    ok, key, args = gradeh_lm_save_lp(db, u, pid, ans)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    p = gradeh_lm_person(db, u, pid)
    nxt = None
    if ok and p:
        prog = gradeh_lm_progress(p, _gh_lm_bulk(db, p["cycle_id"], [p])[p["id"]])
        nxt = "comments" if prog["lp"]["done"] and request.form.get("go") == "next" else None
    return _gh_lm_after(db, u, lang, pid, ok, key, args, "lp", nxt=nxt, quiet=request.form.get("go") != "next")


@app.route("/review/gradeh/<int:pid>/kpis", methods=["POST"])
@login_required
def review_gradeh_kpis(pid):
    db, u, lang = _gh_lm_ctx()
    figs = {}
    for k, v in request.form.items():
        m = re.fullmatch(r"([fwr])_(\d+)", k)
        if m:
            figs.setdefault(int(m.group(2)), {})[{"f": "pct", "w": "reason", "r": "rating"}[m.group(1)]] = v
    ok, key, args = gradeh_lm_save_kpis(db, u, pid, figs)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    return _gh_lm_after(db, u, lang, pid, ok, key, args, "kpis", nxt="lp", form=dict(request.form.items()))


@app.route("/review/gradeh/<int:pid>/comments", methods=["POST"])
@login_required
def review_gradeh_comments(pid):
    db, u, lang = _gh_lm_ctx()
    f = {k: request.form[k] for k in ("ach", "str", "dev") if k in request.form}
    ok, key, args = gradeh_lm_save_sectionb(db, u, pid, f)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    if request.form.get("json") == "1":   # the page's draft autosave: no flash, no redirect
        return jsonify(ok=ok, say=_gh_lm_say(lang, key, args), key=key), (200 if ok else 400)
    p = gradeh_lm_person(db, u, pid)
    nxt = None
    if ok and p and request.form.get("go") == "next":
        prog = gradeh_lm_progress(p, _gh_lm_bulk(db, p["cycle_id"], [p])[p["id"]])
        nxt = "submit" if prog["comments"]["done"] else None
    return _gh_lm_after(db, u, lang, pid, ok, key, args, "comments", nxt=nxt, form=dict(request.form.items()))


@app.route("/review/gradeh/<int:pid>/submit", methods=["POST"])
@login_required
def review_gradeh_submit(pid):
    """The final submit. Needs the box's own confirm (confirm=1 from the double-confirm), the nomination and the tick posted
    with it. A refusal says what is still missing and keeps what was typed."""
    db, u, lang = _gh_lm_ctx()
    f = {k: request.form[k] for k in ("promo", "promo_reason") if k in request.form}
    f["conv"] = "1" if request.form.get("conv") else "0"
    if request.form.get("confirm") != "1":
        abort(400)
    ok, key, args = gradeh_lm_submit(db, u, pid, fields=f)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    p = gradeh_lm_person(db, u, pid)
    if ok:
        em = args.get("email")
        flash(_gh_lm_say(lang, key, {"name": proper_name((p["full_name"] or "").strip())}) + (
            " " + gh_lm_t(lang, "email_q", name=proper_name((p["full_name"] or "").strip())) if em == "queued" else
            " " + gh_lm_t(lang, "email_none", name=proper_name((p["full_name"] or "").strip())) if em == "no_email" else ""), "ok")
        return _gh_lm_back(pid, "submit")
    return _gh_lm_after(db, u, lang, pid, ok, key, args, "submit", form=dict(request.form.items()))


@app.route("/review/gradeh/<int:pid>/ack", methods=["POST"])
@login_required
def review_gradeh_ack(pid):
    db, u, lang = _gh_lm_ctx()
    if not gradeh_module_on(db) or not gradeh_lm_person(db, u, pid):   # not their appraisee (or the module off): a 404 before anything else is read
        abort(404)
    choice = request.form.get("agrees")   # nothing is pre-picked: an absent or unknown answer is refused, never read as "agrees"
    if choice not in ("1", "0"):
        ok, key, args = False, "m_ack_choose", {}
    else:
        ok, key, args = gradeh_lm_ack_in_person(db, u, pid, request.form.get("on"), agrees=(choice == "1"),
                                                reason=request.form.get("reason") if choice == "0" else None)
    if not ok and key in ("m_not_yours", "m_off"):
        abort(404)
    flash(_gh_lm_say(lang, key, args), "ok" if ok else "error")
    ret = request.form.get("return")
    return redirect(url_for("review_gradeh") if ret == "team" else url_for("review_gradeh_person", pid=pid, step="submit"), 303)


@app.route("/review/gradeh/<int:pid>/help", methods=["POST"])
@login_required
def review_gradeh_help(pid):
    """"Help me word this": drafts words into one comment box (JSON). Stores nothing, rates nothing, submits nothing."""
    db, u, lang = _gh_lm_ctx()
    ok, out, args = gradeh_lm_help(db, u, pid, request.form.get("field", ""), request.form.get("text", ""),
                                   request.form.get("instruction", ""))
    if not ok and out in ("m_not_yours", "m_off"):
        abort(404)
    if ok:
        return jsonify(ok=True, text=out)
    code = 503 if out == "help_off" else 502 if out == "help_fail" else 400
    return jsonify(ok=False, key=out, say=_gh_lm_say(lang, out, args)), code


@app.route("/review/gradeh/language", methods=["POST"])
@login_required
def review_gradeh_language():
    """The BM / EN switch in the header of these pages, for every line manager: gradeh_lm_set_language writes it (a Grade H
    supervisor's own page language, anyone else's on their account). Goes back to the page it was pressed on (the team list or one
    of this account's people, with its step), never anywhere else."""
    db, u, lang = _gh_lm_ctx()
    gradeh_lm_set_language(db, u, (request.form.get("lang") or "").strip())
    return redirect(_gh_lm_return(db, u, request.form.get("next")), 303)


def _gh_lm_return(db, u, nxt):
    """Where a form on these pages goes back to: the team list (with its filter) or one of this account's people (with its
    step / open item). Anything else, and a person who is not theirs, is the team list."""
    team = url_for("review_gradeh")
    try:
        parts = urlsplit(nxt or "")
    except ValueError:
        return team
    if parts.scheme or parts.netloc:
        return team
    m = re.fullmatch(re.escape(GRADEH_LM_PATH) + r"(?:/(\d+))?", parts.path.rstrip("/"))
    if not m:
        return team
    q = {k: v for k, v in parse_qsl(parts.query) if k in ("f", "step", "a", "lp") and re.fullmatch(r"[a-z0-9]{1,12}", v)}
    if m.group(1):
        if not gradeh_lm_person(db, u, int(m.group(1))):
            return team
        return url_for("review_gradeh_person", pid=int(m.group(1)), **q)
    return url_for("review_gradeh", **q)


@app.route("/review/gradeh/ask", methods=["POST"])
@login_required
def review_gradeh_ask():
    """Ask OneHR on the line manager's Grade H pages: fixed answers, no model, no result read out, nothing stored."""
    db, u, lang = _gh_lm_ctx()
    ans, chips = gradeh_lm_ask(request.form.get("message"), lang)
    return jsonify(ok=True, say=ans or gh_lm_t(lang, "ask_none"), found=bool(ans), chips=chips)


# =====================================================================================================================
# Grade H Appraisal, piece 5 (2026-10-28): the HOD and BU CEO calibration stages (canvases C1b, C1, C2, C2b).
# HOD (the people whose users.hod_id is the account): Grade H potential first, signed off, then Grade H performance, signed off.
# BU CEO (a seat in buceo_seats, one unit = users.company): the Grade H Talent Box on both axes, person by person, then ONE sign-off
# that never waits for the HODs or the line managers (2026-10-30: a higher tier supersedes a lower one; a person with no line manager
# input shows the default band, GRADEH_DEFAULT_BAND, which the tier may agree or move). Moves go through gradeh_record_move (the one writer); the
# gates that writer does not hold (who may move whom, stage order, locks) are HERE. Group People's final bands and the release are
# the next piece: it reads gradeh_unit_signoff_state(). Pages are under /calibration/gradeh (classified to the gradeh module).
# What each tier may read: the HOD sees the line manager's bands, score and figure; the BU CEO also the line manager's comments and
# the promotion nomination (canvas C2b: for calibrators); neither sees acknowledgement text beyond Yes / In person / Deemed.
GRADEH_CALIB_PATH = "/calibration/gradeh"
GRADEH_CAL_HOD_ABILITY = "hod.gradeh"
GRADEH_CAL_BU_ABILITY = "bu.gradeh"
GRADEH_CAL_STAGES = ("pot", "perf")                      # the HOD's two stages, in order
GRADEH_CAL_AXIS = {"pot": "pot", "perf": "perf"}         # a stage is its axis
GRADEH_CAL_RANK = {v: k for k, v in GRADEH_BCODE.items()}   # UA -> 1 ... OU -> 5
GRADEH_CAL_COLS = (("low", "Low", ("UA", "BE")), ("mid", "Mid", ("ME",)), ("high", "High", ("AE", "OU")))
GRADEH_CAL_ROWS = ("High", "Mid", "Low")                 # potential, top to bottom


def gradeh_settings_cycle_id(db):
    """The active cycle's id while Grade H Appraisal is OFFERED on it (the server switch is on and it is a Year-End), ticked or
    not (2026-10-31): the Settings tab saves before the module is ticked, so the super admin can set it up first. The settings
    rows themselves are org-wide (gradeh_set_setting keys no cycle); the id only scopes the dry-run count and the band
    re-work, which touch nobody until people are on the list. Else None."""
    cyc = active_cycle(db)
    return cyc["id"] if cyc and gradeh_cycle_offered(cyc) else None


def gradeh_calib_cycle_id(db):
    """The active cycle's id while the module runs in it (Year-End, ticked), else None."""
    return gradeh_lm_cycle_id(db)


def _gh_cal_chunks(seq, n=400):
    seq = list(seq)
    for i in range(0, len(seq), n):
        yield seq[i:i + n]


# A person's Grade H HOD (Chris, 2026-11-02: "set the HOD as per the HR file"): the HOD the Grade H list names (gradeh_people.hod_user_id),
# else their OneHR HOD (users.hod_id). users.hod_id itself is never written by Grade H: the main review's HOD stays as it is. The other way
# round, Grade H now follows a main HOD change (Chris, 2026-11-13, _line_changed): the override is cleared when the main HOD changes, or pinned
# where Grade H is locked for the person, so the list's HOD is only ever what was set by hand AFTER the latest main change. Nobody (NULL)
# when that account has left or is the person themselves: they go to the BU CEO. THE ONE place that says it: every Grade H reader of an
# HOD (the scope, the sign-off, the early opening, the reminders, the notices, People & progress) selects or compares this fragment
# (aliases p = gradeh_people, uu = the person's users row); the Python twin is gradeh_hod_of.
_GH_HOD_RAW = "COALESCE(p.hod_user_id, uu.hod_id)"
_GH_HOD_SQL = ("(CASE WHEN " + _GH_HOD_RAW + " IS NULL OR " + _GH_HOD_RAW + "=uu.id THEN NULL WHEN EXISTS (SELECT 1 FROM users hh "
               "WHERE hh.id=" + _GH_HOD_RAW + " AND hh.left_at IS NOT NULL) THEN NULL ELSE " + _GH_HOD_RAW + " END)")


# The SECOND Grade H HOD (Chris, 2026-11-03: "HOD A and B needs to calibrate person A"): gradeh_people.hod2_user_id, the same rules as the
# first (never the person, never one who has left) and never the same account as the first. Selected beside _GH_HOD_SQL (`hod2_id`, with
# `hod_split`, the FIRST HOD's share); a person with none has NULL here and every reader behaves as it did with one HOD.
_GH_HOD2_SQL = ("(CASE WHEN p.hod2_user_id IS NULL OR p.hod2_user_id=uu.id OR p.hod2_user_id=" + _GH_HOD_RAW + " THEN NULL WHEN EXISTS "
                "(SELECT 1 FROM users hh WHERE hh.id=p.hod2_user_id AND hh.left_at IS NOT NULL) THEN NULL ELSE p.hod2_user_id END)")


def gradeh_hod_of(db, person):
    """The Grade H HOD's user id of one Grade H person (a gradeh_people row: `hod_user_id`, `user_id`), or None: the list's HOD,
    else the person's OneHR HOD (users.hod_id); None when that account has left or is the person themselves (the BU CEO covers
    them). The Python twin of _GH_HOD_SQL; an HOD who holds a BU CEO or BG CEO seat is dropped later, by gradeh_hod_has_role.
    Grade H follows a main HOD change (2026-11-13: _line_changed clears `hod_user_id`, or pins it where Grade H is locked), so this reads
    the list's HOD only when it was set by hand after the latest main change; users.hod_id itself is still never written by Grade H."""
    u = db.execute("SELECT hod_id FROM users WHERE id=?", (person["user_id"],)).fetchone()
    hid = person["hod_user_id"] or (u["hod_id"] if u else None)
    if not hid or hid == person["user_id"]:
        return None
    h = db.execute("SELECT left_at FROM users WHERE id=?", (hid,)).fetchone()
    return hid if h and not h["left_at"] else None


# The line manager's result, WITHOUT the comments and the nomination (those are read by the BU CEO's person page only).
_GH_CAL_SQL = (
    "SELECT p.id, p.cycle_id, p.employee_id, p.user_id, p.route, uu.full_name AS full_name, uu.job_title AS job_title, "
    "uu.department AS department, uu.business_group AS business_group, uu.company AS company, " + _GH_HOD_SQL + " AS hod_id, "
    + _GH_HOD2_SQL + " AS hod2_id, p.hod_split AS hod_split, "
    "a.lm_submitted_at, a.perf_value, a.perf_rating, a.perf_band, a.pot_score, a.pot_band, a.acknowledged_at, a.deemed_at, "
    "a.ack_in_person, a.disagree_at, "
    "(SELECT COUNT(*) FROM gradeh_kpi_lines kl WHERE kl.person_id=p.id AND kl.cycle_id=p.cycle_id AND kl.bu_kpi_id IS NOT NULL "
    "AND ((kl.group_scale='OTHER' AND kl.bu_rating IS NULL) OR (kl.group_scale!='OTHER' AND kl.bu_pct IS NULL))) AS shared_wait "
    "FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
    "LEFT JOIN gradeh_appraisals a ON a.cycle_id=p.cycle_id AND a.person_id=p.id "
    "WHERE p.cycle_id=? AND p.private_company=0 AND uu.left_at IS NULL ")


# A person whose OneHR HOD is the BU CEO of their own unit has no department HOD: they go to the BU CEO directly (no HOD stage).
_GH_CAL_NOT_BU = " AND NOT EXISTS (SELECT 1 FROM buceo_seats bs WHERE bs.user_id=" + _GH_HOD_SQL + " AND bs.company=uu.company) "
_GH_CAL_NOT_BU2 = " AND NOT EXISTS (SELECT 1 FROM buceo_seats bs WHERE bs.user_id=" + _GH_HOD2_SQL + " AND bs.company=uu.company) "
# the people of ONE HOD, as either of their person's two HODs (one placeholder each: the first slot, the second slot), the person not the HOD:
# "AND p.user_id != ? AND ((first = ? AND not-BU) OR (second = ? AND not-BU))". THE scope every HOD reader asks (gradeh_hod_scope, the
# dashboard counts, the reminders, can_use): a person with a second HOD is in both HODs' scope.
_GH_HOD_SCOPE_SQL = ("AND p.user_id != ? AND ((" + _GH_HOD_SQL + "=?" + _GH_CAL_NOT_BU + ") OR (" + _GH_HOD2_SQL + "=?" + _GH_CAL_NOT_BU2 + ")) ")


def gradeh_hod_scope(db, hod_id, cycle_id):
    """The Grade H people of this HOD's own departments: those whose Grade H HOD (_GH_HOD_SQL: the Grade H list's HOD, else their
    OneHR HOD, never one who has left) is this account, never the
    account's own record, and never a person whose "HOD" is their unit's BU CEO (they go to the BU CEO directly). In Grade H only a
    BU CEO or BG CEO seat takes the HOD role away (Chris, 2026-11-03; gradeh_hod_has_role): an account that holds one has no Grade H
    people as an HOD, and the people it is hod_id of go to the BU CEO like people with no HOD. A calibrator of the normal review (a
    calibration group, a Group Chief group) is an HOD here: Grade H has no calibrator step."""
    if not gradeh_hod_has_role(db, hod_id):
        return []
    return db.execute(_GH_CAL_SQL + _GH_HOD_SCOPE_SQL + "ORDER BY lower(uu.full_name), p.id",
                      (cycle_id, hod_id, hod_id, hod_id)).fetchall()


def gradeh_unit_scope(db, cycle_id, business_group, company):
    return db.execute(_GH_CAL_SQL + "AND uu.business_group=? AND uu.company=? ORDER BY lower(uu.full_name), p.id",
                      (cycle_id, business_group, company)).fetchall()


def _gh_cal_load(db, cid, rows):
    """(moves, reviews, yes) for these people in four batched reads: the latest move per (person, axis, stage), the agree
    ticks per (person, axis, tier), and (yes, answered) of the 14 statements per person. `revs` also carries the cycle's sign-offs
    (.hod_signs, .bu_signs: one small read), which the band order needs, and each HOD's own call for the people who have a second
    HOD (.hod_moves, .hod_ticks, .seats: one more read of the ticks and of the seats, only when someone in `rows` is shared)."""
    moves, revs, yes = {}, _GhRevs(), {}
    revs.hod_signs, revs.bu_signs = _gh_signoff_maps(db, cid)
    revs.hod_moves, revs.hod_ticks = {}, {}
    mrows = []
    for ch in _gh_cal_chunks(r["id"] for r in rows):
        ph = ",".join("?" * len(ch))
        for m in db.execute("SELECT * FROM gradeh_band_moves WHERE cycle_id=? AND person_id IN (%s) ORDER BY id" % ph, [cid] + ch):
            moves[(m["person_id"], m["axis"], m["stage"])] = m   # the latest of a stage wins
            mrows.append(m)
        for r_ in db.execute("SELECT * FROM gradeh_reviews WHERE cycle_id=? AND person_id IN (%s)" % ph, [cid] + ch):
            revs[(r_["person_id"], r_["axis"], r_["tier"])] = r_
        for r_ in db.execute("SELECT person_id, SUM(answer='yes') AS y, COUNT(*) AS n FROM gradeh_lp_answers "
                             "WHERE cycle_id=? AND person_id IN (%s) GROUP BY person_id" % ph, [cid] + ch):
            yes[r_["person_id"]] = (r_["y"] or 0, r_["n"])
    shared = [r["id"] for r in rows if r["hod2_id"]]
    if shared:   # the second HOD's own calls (a person with one HOD never needs them)
        _gh_hod_calls_load(db, cid, revs, [m for m in mrows if m["person_id"] in set(shared)], shared)
        revs.seats = _gh_seat_pairs(db)
    return moves, revs, yes


def _gh_cal_person(r, moves, revs, yes, show_default=True, as_hod=None):
    """One person as the calibration pages read them. b_hod / b_bu = the band on each axis at the HOD's and at the BU CEO's level
    (the order of _gh_band_pick, stopping at that stage: a lower tier never reads a higher one's move), the default band
    (GRADEH_DEFAULT_BAND) where nobody has put one (show_default; the admin pages pass False: they never show a band nobody set);
    b_fin = the band all the way up, None until someone decides. hod_done = the HOD moved them, or ticked Agree on the band they
    are looking at (a tick the line manager's later submission has changed is stale, unless the stage is signed off). late = the
    line manager submitted after the HOD's (or the BU CEO's) sign-off: the signed-off band stands.
    A person with a SECOND HOD (r["hod2_id"], 2026-11-03): b_hod is the blend of the two HODs' signed calls (_gh_hod_level), or, when
    `as_hod` names one of them (their own page, sign-off and curve), THEIR call as it stands; hod_moved / hod_done / hod_signed / late
    are that HOD's own then, and for the admin and BU CEO readers (no as_hod) the person's HOD level as a whole. "hods" lists each live
    HOD with their share and their call on each axis. A person with one HOD is read exactly as before."""
    pid = r["id"]
    sub = bool(r["lm_submitted_at"])
    lm = {"perf": r["perf_band"] if sub else None, "pot": r["pot_band"] if sub else None}
    hs, bs = getattr(revs, "hod_signs", {}), getattr(revs, "bu_signs", {})
    co = r["company"]
    two = bool(r["hod2_id"])
    slots = []
    if two:
        seats = revs.seats if revs.seats is not None else _gh_seat_pairs(get_db())
        slots = _gh_slots(get_db(), r["hod_id"], r["hod2_id"], r["hod_split"], r["user_id"], co, seats)
        hod_ok = bool(slots)
    else:
        hod_ok = bool(r["hod_id"]) and gradeh_hod_has_role(get_db(), r["hod_id"])

    dis = gradeh_is_disagreed(r)   # does not agree: never calibrated, so no HOD / BU CEO row reaches their band (_gh_band_pick)

    def at(axis, upto):
        if two:
            lvl = _gh_hod_level(axis, pid, slots, revs, hs, as_hod if upto == "hod" else None)
            return _gh_band_pick(axis, upto, pid, co, lm[axis], moves, revs, hs, bs, dis, lvl)
        return _gh_band_pick(axis, upto, pid, co, lm[axis], moves, revs, hs, bs, dis)
    d = {"id": pid, "name": (r["full_name"] or "").strip(), "title": proper_name(r["job_title"] or ""),
         "dept": proper_name(r["department"] or ""), "company": r["company"], "bg": r["business_group"], "hod_id": r["hod_id"],
         "hod2_id": r["hod2_id"], "uid": r["user_id"], "route": r["route"], "submitted": sub, "lm": lm,
         "perf_value": r["perf_value"], "perf_rating": r["perf_rating"], "pot_score": r["pot_score"],
         "shared_wait": bool(sub and _row_get(r, "shared_wait")),   # submitted, but a KPI line that shares a unit's result is still waiting for Group People's figure: no performance band from the line manager yet
         "yes": yes.get(pid), "ack": ("person" if r["ack_in_person"] else "yes" if r["acknowledged_at"]
                                      else "deemed" if r["deemed_at"] else ""),
         "b_hod": {}, "b_bu": {}, "b_fin": {}, "hod_moved": {}, "bu_moved": {}, "hod_done": {}, "hod_signed": {},
         "shared": len(slots) == 2, "hods": [],
         "disagree": dis, "disagree_on": (_gh_cal_when(r["disagree_at"]) if dis else "")}
    late_hod = False
    late_by, own_all = {}, {}
    for ax in GRADEH_AXES:
        dflt = GRADEH_DEFAULT_BAND[ax] if show_default else None
        d["b_hod"][ax] = at(ax, "hod")[0] or dflt
        d["b_bu"][ax] = at(ax, "buceo")[0] or dflt
        d["b_fin"][ax] = at(ax, "final")[0]
        if dis:   # not calibrated: no HOD / BU CEO move, tick or sign-off belongs to them, whatever a stray row says
            d["hod_moved"][ax] = d["bu_moved"][ax] = None
            d["hod_done"][ax] = d["hod_signed"][ax] = False
            continue
        if two:
            d["bu_moved"][ax] = moves.get((pid, ax, "buceo"))
            own = {}
            for h, _sh in slots:
                mvh, tk = revs.hod_moves.get((pid, ax, h)), revs.hod_ticks.get((pid, ax, h))
                sg = (str(h), ax) in hs
                own[h] = {"moved": mvh, "signed": sg, "done": bool(mvh or (tk and (sg or tk == (lm[ax] or GRADEH_DEFAULT_BAND[ax])))),
                          "band": mvh["band"] if mvh else tk}
                if sub and sg and str(hs[(str(h), ax)])[:19] < str(r["lm_submitted_at"])[:19]:
                    late_by[h] = True
            own_all[ax] = own
            mine = own.get(as_hod) if as_hod else (own[slots[0][0]] if len(slots) == 1 else None)   # one live HOD: theirs, as for one HOD
            if mine:
                d["hod_moved"][ax], d["hod_signed"][ax], d["hod_done"][ax] = mine["moved"], mine["signed"], mine["done"]
            else:   # the person's HOD level as a whole: the latest move, done once a HOD has acted, signed once every live HOD has
                d["hod_moved"][ax] = moves.get((pid, ax, "hod"))
                d["hod_done"][ax] = any(o["done"] for o in own.values())
                d["hod_signed"][ax] = bool(own) and all(o["signed"] for o in own.values())
            continue
        d["hod_moved"][ax] = moves.get((pid, ax, "hod"))
        d["bu_moved"][ax] = moves.get((pid, ax, "buceo"))
        rev = revs.get((pid, ax, "hod"))
        hod_key = (str(rev["by_user_id"] if rev else r["hod_id"]), ax)
        signed = hod_key in hs and (rev is not None or hod_ok)   # a calibrator holds no HOD role: nobody's sign-off covers them
        d["hod_signed"][ax] = bool(rev and signed)
        d["hod_done"][ax] = bool(d["hod_moved"][ax] or (rev and (signed or rev["band"] == (lm[ax] or GRADEH_DEFAULT_BAND[ax]))))
        if sub and signed and str(hs[hod_key])[:19] < str(r["lm_submitted_at"])[:19]:
            late_hod = True
    if two:
        d["hod_split"] = _gh_split(r["hod_split"])
        d["hods"] = [{"id": h, "share": sh,
                      **{ax: {"band": (own_all.get(ax, {}).get(h) or {}).get("band"),
                              "moved": bool((own_all.get(ax, {}).get(h) or {}).get("moved")),
                              "signed": bool((own_all.get(ax, {}).get(h) or {}).get("signed"))} for ax in GRADEH_AXES}}
                     for h, sh in slots]
        d["late_by"] = dict(late_by)
        late_hod = bool(late_by.get(as_hod)) if (as_hod and any(h == as_hod for h, _s in slots)) else any(late_by.values())
    late_bu = bool(sub and not dis and co in bs and str(bs[co])[:19] < str(r["lm_submitted_at"])[:19])
    d["late"] = {"hod": late_hod, "bu": late_bu}
    d["late_text"] = "Late: line manager submitted after sign-off" if (late_hod or late_bu) else ""
    return d


def gradeh_calib_label(perf_band, pot_band):
    """A person's talent label (None until both bands exist). Group People's own grid is pending: gradeh_talent_label holds the hook."""
    if not perf_band or not pot_band:
        return None
    return gradeh_talent_label(perf_band, pot_band)


def gradeh_cell_label(col_key, pot):
    """A box's label: OneHR's 9-box (TALENT_BOX_9_CATEGORIES); Group People's grid would replace it where its hook is set."""
    return TALENT_BOX_9_CATEGORIES[(col_key, pot)]


def _gh_cal_curve_target(db, cid, axis, business_group=None, company=None):
    """(order, expected % by band, the curve's name) for one axis: the potential curve (default 15 / 70 / 15), or the performance
    curve by the super admin's mode: normal (5 / 10 / 70 / 10 / 5), follow the unit's PAT Ref, or custom. A stored list that is
    not the right length or not numbers falls back to the default."""
    def ok(v, n):
        return isinstance(v, list) and len(v) == n and all(isinstance(x, (int, float)) and not isinstance(x, bool) and x >= 0 for x in v)
    if axis == "pot":
        order = list(GRADEH_POT_BANDS)
        v = gradeh_setting("gradeh_pot_curve", cid)
        v = v if ok(v, 3) else GRADEH_DEFAULTS["gradeh_pot_curve"]
        return order, dict(zip(order, v)), "Potential curve"
    order = list(GRADEH_PERF_BANDS)
    mode = gradeh_setting("gradeh_perf_curve_mode", cid)
    if mode == "pat":
        pc = pm_curve_for(db, cid, business_group, company)
        return order, {b: pc["dist"][b] for b in order}, "Follows the unit's PAT Ref: %s" % pc["label"]
    if mode == "custom":
        v = gradeh_setting("gradeh_perf_curve_custom", cid)
        v = v if ok(v, 5) else GRADEH_DEFAULTS["gradeh_perf_curve_custom"]
        return order, dict(zip(order, v)), "Custom"
    v = gradeh_setting("gradeh_perf_curve_normal", cid)
    v = v if ok(v, 5) else GRADEH_DEFAULTS["gradeh_perf_curve_normal"]
    return order, dict(zip(order, v)), "Normal"


def gradeh_calib_curve(db, cid, axis, bands, business_group=None, company=None):
    """The curve box's data (what calibDistBox draws), for the bands of the people counted: {order, labels, dist, target, gaps, total,
    tol, breaches, name, text, off}. gaps = expected people - actual (positive: fewer than expected). A band is off the curve when
    its gap is more than calib_tolerance(total) people: the same rule the leaders' curve uses. Sign-off off the curve asks a reason."""
    order, target, name = _gh_cal_curve_target(db, cid, axis, business_group, company)
    dist = {b: 0 for b in order}
    for b in bands:
        if b in dist:
            dist[b] += 1
    total = sum(dist.values())
    gaps = {b: (round(target[b] / 100.0 * total) if total else 0) - dist[b] for b in order}
    breaches = _calib_over_framework(gaps, total) if total else {}
    labels = {b: (GRADEH_BAND_NAMES.get(b) or b) for b in order}
    return {"axis": axis, "order": order, "labels": labels, "dist": dist, "target": target, "gaps": gaps, "total": total,
            "tol": calib_tolerance(total), "breaches": breaches, "name": name, "off": sorted(breaches, key=order.index)}


def gradeh_hod_state(db, cid, hod_id):
    """{stage: the sign-off row or None} for one HOD."""
    return {stg: db.execute("SELECT * FROM gradeh_signoffs WHERE cycle_id=? AND tier='hod' AND stage=? AND scope_key=?",
                            (cid, stg, str(hod_id))).fetchone() for stg in GRADEH_CAL_STAGES}


def gradeh_buceo_signoff_row(db, cid, unit):
    return db.execute("SELECT * FROM gradeh_signoffs WHERE cycle_id=? AND tier='buceo' AND stage='all' AND scope_key=?",
                      (cid, unit)).fetchone()


def _gh_cal_lock_text(db, cid, company, memo=None):
    """Why nothing in this unit can move now, else None: the BU CEO has signed off, or Group People has released the unit.
    `memo` (a dict, optional): a caller asking about many people keeps one answer a unit (the line follow-through's batch)."""
    key = ("lock", company)
    if memo is not None and key in memo:
        return memo[key]
    if db.execute("SELECT 1 FROM gradeh_releases WHERE cycle_id=? AND unit=?", (cid, company)).fetchone():
        out = "This unit's results have been released, so nothing changes now."
    elif gradeh_buceo_signoff_row(db, cid, company):
        out = "The BU CEO has signed off this unit, so nothing changes now."
    else:
        out = None
    if memo is not None:
        memo[key] = out
    return out


def _gh_row_hods(db, r, seats):
    """The user ids of the HODs who take this person's HOD stage (a row of _GH_CAL_SQL or _GH_ADM_SQL; `seats` = {(user id, company)}
    of the BU CEO seats): the Grade H HOD and the second one, as _gh_slots keeps them (not the person, not their unit's BU CEO, holding
    the HOD role). [] = no HOD stage: the BU CEO covers them. THE reader behind every "who is this person's HOD" count that is not a band."""
    return [h for h, _sh in _gh_slots(db, r["hod_id"], r["hod2_id"], r["hod_split"], r["user_id"], r["company"], seats)]


def gradeh_unit_signoff_state(db, cycle_id, unit):
    """Where one unit (its users.company) stands, for the BU CEO's sign-off and the next piece (final bands, release):
    {unit, people (all on the list), submitted, hods: [{id, name, n, submitted, pot, perf, done}], hods_total, hods_signed,
    blocking (names of the HODs who have not signed both stages: INFORMATION for the sign-off's confirm box, it never stops the
    sign-off), ready (people are on the list and the unit is not signed off yet), signed, signed_at, signed_by, reason, released}.
    A person with no HOD goes to the BU CEO directly."""
    rows = db.execute(_GH_CAL_SQL + "AND uu.company=?", (cycle_id, unit)).fetchall()
    sub = [r for r in rows if r["lm_submitted_at"]]
    bu_ids = {r["user_id"] for r in db.execute("SELECT user_id FROM buceo_seats WHERE company=?", (unit,))}
    seats = {(i, unit or "") for i in bu_ids}
    by = {}
    for r in rows:
        for h in _gh_row_hods(db, r, seats):   # a person with a second HOD waits on both (2026-11-03)
            by.setdefault(h, []).append(r)
    hods = []
    for hid, rs in sorted(by.items()):
        st = gradeh_hod_state(db, cycle_id, hid)
        nm = db.execute("SELECT full_name FROM users WHERE id=?", (hid,)).fetchone()
        ns = sum(1 for r in rs if r["lm_submitted_at"])
        hods.append({"id": hid, "name": (nm["full_name"] if nm else "#%d" % hid), "n": len(rs), "submitted": ns,
                     "pot": st["pot"] is not None, "perf": st["perf"] is not None,
                     "done": st["pot"] is not None and st["perf"] is not None})
    so = gradeh_buceo_signoff_row(db, cycle_id, unit)
    blocking = [h["name"] for h in hods if not h["done"]]
    return {"unit": unit, "people": len(rows), "submitted": len(sub), "hods": hods, "hods_total": len(hods),
            "hods_signed": sum(1 for h in hods if h["done"]), "blocking": blocking,
            "ready": bool(rows) and so is None, "signed": so is not None,
            "signed_at": so["signed_at"] if so else None, "signed_by": so["signed_by"] if so else None,
            "reason": (so["off_curve_reason"] if so else None),
            "released": db.execute("SELECT 1 FROM gradeh_releases WHERE cycle_id=? AND unit=?", (cycle_id, unit)).fetchone() is not None}


# ---- who may use the pages ---------------------------------------------------------------------------------------------
def gradeh_hod_can(db, u):
    """An HOD of Grade H people (their Grade H HOD: the list's, else their OneHR HOD; need not be an HOD in the main review), not an admin, not a BU CEO or BG CEO (gradeh_hod_has_role: a calibrator of the
    normal review is an HOD in Grade H), with the leader ability on."""
    if not u or is_admin(u) or not gradeh_hod_has_role(db, u["id"]) or not leader_learn_can(u, GRADEH_CAL_HOD_ABILITY, db):
        return False
    cid = gradeh_calib_cycle_id(db)
    return bool(cid and db.execute(
        "SELECT 1 FROM gradeh_people p JOIN users uu ON uu.id=p.user_id WHERE p.cycle_id=? AND p.private_company=0 "
        "AND uu.left_at IS NULL " + _GH_HOD_SCOPE_SQL + "LIMIT 1",
        (cid, u["id"], u["id"], u["id"])).fetchone())


def gradeh_hod_only(db, u):
    """An HOD for Grade H whose journey has no Department Review (Chris, 2026-11-02: the Grade H list can name an HOD who heads no one in the
    main review): they have no Grade H tab beside a Department Review, so the dashboard's Your next step and the journey's Mine view carry
    the Grade H entry for them (gradeh_hod_dash, _journey_modtabs.html). False for anyone with a Department Review, whose tab is there."""
    try:
        return bool(gradeh_on() and u and gradeh_hod_can(db, u) and "dept" not in _journey_leader_views(db, u))
    except Exception:   # an entry never breaks the page it sits on
        return False


def gradeh_hod_dash(db, u):
    """The dashboard's Grade H row for an HOD with no Department Review (same pattern as the line manager's, under Your next step):
    None unless gradeh_hod_only and a stage is still to sign off, else {n, sub, url}. n = their Grade H people (gradeh_hod_scope); sub = why
    it is not open yet (the early-opening words), else the order of the two stages."""
    if not gradeh_hod_only(db, u):
        return None
    cid = gradeh_calib_cycle_id(db)
    st = gradeh_hod_state(db, cid, u["id"])
    if st["pot"] and st["perf"]:
        return None
    n = sum(1 for r_ in gradeh_hod_scope(db, u["id"], cid) if not r_["disagree_at"])   # a person who does not agree is not reviewed
    return {"n": n, "url": url_for("calib_gradeh_hod"),
            "sub": gradeh_hod_gate(db, cid, u["id"], "perf" if st["pot"] else "pot") or "Potential first, then performance."}


app.jinja_env.globals["gradeh_hod_only"] = lambda: gradeh_hod_only(get_db(), current_user()) if session.get("user_id") else False


def gradeh_buceo_units(db, u):
    """[(business_group, company)] this BU CEO holds that have Grade H people, in seat order; [] for an admin, with the
    ability off, or when the module is not running."""
    if not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_BU_ABILITY, db):
        return []
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return []
    out = []
    for bg, co in (buceo_seats(db, u["id"]) or _buceo_col_seat(u)):
        if db.execute("SELECT 1 FROM gradeh_people p JOIN users uu ON uu.id=p.user_id WHERE p.cycle_id=? AND p.private_company=0 "
                      "AND uu.left_at IS NULL AND uu.business_group=? AND uu.company=? LIMIT 1", (cid, bg, co)).fetchone():
            out.append((bg, co))
    return out


# ---- early opening of the HOD and BU CEO stages (Chris, 2026-11-02) --------------------------------------------------------
# A stage is open for a leader when the date is inside the part's calendar cell AND (everyone it waits on has finished OR the part's
# fallback date has come). Per HOD and per unit, never per person. A blank fallback is no early opening: the cell alone decides, as
# before. Closing stays the cell's end. THE two readers: the gates below, the pages' words, the reminder and the bar all ask them.
GRADEH_HOD_FALLBACK = "gradeh_hod_fallback_at"
GRADEH_BU_FALLBACK = "gradeh_bu_fallback_at"


def _gh_fallback(name, cid):
    """The fallback as a MYT datetime, or None (blank = no early opening)."""
    return _gh_myt(gradeh_setting(name, cid) or None)


def _gh_ack_state(r, rule, now_utc, inperson=None):
    """(counts, at) for one Grade H person (a row of _GH_CAL_SQL): does the person count as acknowledged (on their own, in person, or
    deemed: recorded, or past the deemed deadline, as the deemed step runs only when someone opens a page), and the UTC datetime it
    FIRST counted (the earliest of the recorded acknowledgement, the recorded deemed step and the deemed deadline; in person, the
    time the line manager recorded it: the disagreement's time, else `inperson`'s {person id: updated_at}). `at` None = counts but no
    time is on record. A person whose line manager has not submitted has nothing to acknowledge and does not count (False, None).
    THE rule behind _gh_acked_count and the first-opened moment of an HOD's stage (gradeh_hod_first_open)."""
    if not r["lm_submitted_at"]:
        return False, None
    ats = [r[k] for k in ("acknowledged_at", "deemed_at") if r[k]]
    dl = rule(r["lm_submitted_at"])
    if dl and dl <= now_utc:
        ats.append(dl)
    counts = bool(ats)
    if r["ack_in_person"]:
        counts = True
        got = r["disagree_at"] or (inperson or {}).get(r["id"])
        if got:
            ats.append(got)
    at = [x for x in (_parse_when(v) for v in ats) if x]
    return counts, (min(at) if at else None)


def _gh_acked_count(rows, cid, now, rule=None):
    """How many of these Grade H people (rows of _GH_CAL_SQL) have acknowledged: on their own, in person, or deemed (recorded, or
    past the deemed deadline: the deemed step runs only when someone opens a page, so the rule is read here too). A person whose
    line manager has not submitted has nothing to acknowledge and does not count."""
    rule = rule or gradeh_deemed_rule(cid)   # a reader over many HODs reads the rule once and hands it in
    now_utc = (now - timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
    return sum(1 for r in rows if _gh_ack_state(r, rule, now_utc)[0])


def _gh_open_result(db, cid, cell, fb, now, count):
    """The shared shape: {open, done, total, fallback_at, inside, cell}. `inside` = the date is inside the cell. Not inside: open
    only through a reopen or late pass (window_closed says), never before the cell opens. Inside with no fallback set: open (the cell
    alone decides) and nothing is counted. Inside with one: open once everyone has finished (`count()` gives done, total) or the
    fallback has come."""
    out = {"open": False, "done": 0, "total": 0, "fallback_at": fb, "inside": False, "cell": cell}
    if window_state(db, cell, cid, now) != "open":
        out["open"] = window_closed(db, cell, cid, now) is None
        return out
    out["inside"] = True
    if fb is None:
        out["open"] = True
        return out
    out["done"], out["total"] = count()
    out["open"] = bool(now >= fb or out["done"] >= out["total"])
    return out


_GH_FB_READ = object()   # "read the fallback setting yourself" (the default of gradeh_hod_open_for's `fb`)


def gradeh_hod_open_for(db, cid, hod_id, stage="pot", now=None, rows=None, fb=_GH_FB_READ, rule=None):
    """Is this HOD's Grade H stage ('pot' | 'perf') open for them: {open, done, total, fallback_at, inside, cell}. done / total =
    their Grade H people (gradeh_hod_scope: one read) who have acknowledged, of all of them. The people leave out private-company
    rows and leavers (the scope does). `rows` = those people already read (a page over many HODs, the By HOD table, reads the whole
    population once and hands each HOD their own rows: never a read a HOD). `fb` = the fallback date already read, `rule` = the deemed rule
    already read (gradeh_deemed_rule): that page reads each once."""
    now = now or _now_myt()
    cell = GRADEH_CELL_HOD_PERF if stage == "perf" else GRADEH_CELL_HOD_POT

    def count():
        rs = rows if rows is not None else gradeh_hod_scope(db, hod_id, cid)
        return _gh_acked_count(rs, cid, now, rule), len(rs)
    return _gh_open_result(db, cid, cell, _gh_fallback(GRADEH_HOD_FALLBACK, cid) if fb is _GH_FB_READ else fb, now, count)


def gradeh_bu_open_for(db, cid, company, business_group=None, now=None):
    """Is the BU CEO's Grade H sign-off open for this unit: {open, done, total, fallback_at, inside, cell}. done / total = the
    unit's Grade H people (one read; private-company rows and leavers are not in it) who have finished the HOD stage: both stages
    signed off by their HOD, or no HOD stage (no HOD, their own unit's BU CEO, or an HOD who holds a BU CEO / BG CEO seat, as _gh_hod_stage reads it). Two
    more reads for the whole unit: its BU CEO seats and the HODs' sign-offs (the calibrators are read once per request)."""
    now = now or _now_myt()

    def count():
        st = _gh_bu_people_done(db, cid, company, business_group)
        return sum(1 for d, _at in st if d), len(st)
    return _gh_open_result(db, cid, GRADEH_CELL_BUCEO, _gh_fallback(GRADEH_BU_FALLBACK, cid), now, count)


_GH_FROM_START = datetime.min   # "done from the start": nothing to wait for (the first-opened moment's floor)


def _gh_bu_people_done(db, cid, company, business_group=None):
    """[(done, at)] for the unit's people (see _gh_bu_people_state, which also hands back their rows)."""
    return _gh_bu_people_state(db, cid, company, business_group)[1]


def _gh_bu_people_state(db, cid, company, business_group=None):
    """(rows, [(done, at)]) for the unit's Grade H people (private-company rows and leavers are not in it), one pair each: done = they have
    finished the HOD stage (both stages signed by every HOD of theirs, a second one too; or no HOD stage: no HOD, their own unit's BU
    CEO, an HOD who holds a seat; or they told us they do not agree, so there is no HOD stage to wait for), and `at` = the UTC datetime
    it first held (the later of their HODs' two sign-offs; a disagreement's own time when that came first), _GH_FROM_START for no HOD
    stage, None when not done. THE count behind gradeh_bu_open_for and the first-opened moment of the BU CEO's sign-off. Two more
    reads for the whole unit: its BU CEO seats and the HODs' sign-offs."""
    q, a = _GH_CAL_SQL + "AND uu.company=?", [cid, company]
    if business_group is not None:
        q, a = q + " AND uu.business_group=?", a + [business_group]
    rows = db.execute(q, a).fetchall()
    seats = {(r[0], company or "") for r in db.execute("SELECT user_id FROM buceo_seats WHERE company=?", (company,))}
    signed = {}
    for r in db.execute("SELECT scope_key, stage, signed_at FROM gradeh_signoffs WHERE cycle_id=? AND tier='hod'", (cid,)):
        signed.setdefault(r[0], {})[r[1]] = r[2]
    out = []
    for r in rows:
        hs = _gh_row_hods(db, r, seats)   # every HOD of the person, a second one too, must have signed both stages
        at = []
        if r["disagree_at"]:   # told us they do not agree: not calibrated
            at.append(_parse_when(r["disagree_at"]))
        if not hs:
            at.append(_GH_FROM_START)
        elif all(set(GRADEH_CAL_STAGES) <= set(signed.get(str(h), {})) for h in hs):
            at.append(max([_parse_when(signed[str(h)][stg]) or _GH_FROM_START for h in hs for stg in GRADEH_CAL_STAGES]))
        at = [x for x in at if x]
        out.append((bool(at) or bool(r["disagree_at"]), min(at) if at else None))
    return rows, out


def _gh_early_date(dt):
    """'19 Nov', or '19 Nov, 7:30 pm' when the fallback has a time of day."""
    return gh_when(dt, "en", time=bool(dt.hour or dt.minute), year=False)


def gradeh_hod_gate(db, cid, hod_id, stage, now=None, rows=None, fb=_GH_FB_READ, rule=None):
    """None when this HOD's stage is open for them, else the words why not: the calendar's (closed / not open yet), or, inside the
    cell, 'Opens on 19 Nov, or sooner once all your Grade H people have acknowledged: 24 of 30 so far.' THE gate of the HOD's moves,
    agree and sign-off, and the line the page shows."""
    cell = GRADEH_CELL_HOD_PERF if stage == "perf" else GRADEH_CELL_HOD_POT
    shut = window_closed(db, cell, cid, now)   # the calendar's dates (piece 6)
    if shut:
        return shut
    r = gradeh_hod_open_for(db, cid, hod_id, stage, now, rows, fb, rule)
    if r["open"]:
        return None
    return "Opens on %s, or sooner once all your Grade H people have acknowledged: %d of %d so far." % (
        _gh_early_date(r["fallback_at"]), r["done"], r["total"])


def gradeh_bu_gate(db, cid, business_group, company, now=None):
    """None when the BU CEO's sign-off is open for this unit, else the words why not (see gradeh_hod_gate): 'Opens on 22 Nov, or from
    19 Nov once every HOD in <unit> has signed off: 3 of 4 people done.' THE gate of the BU CEO's moves and sign-off."""
    shut = window_closed(db, GRADEH_CELL_BUCEO, cid, now)
    if shut:
        return shut
    r = gradeh_bu_open_for(db, cid, company, business_group, now)
    if r["open"]:
        return None
    opens = _parse_when(window_dates(db, GRADEH_CELL_BUCEO, cid)[0])
    return "Opens on %s, or %s once every HOD in %s has signed off: %d of %d people done." % (
        _gh_early_date(r["fallback_at"]), ("from " + _gh_early_date(opens)) if opens else "sooner",
        display_company(business_group, company) or company, r["done"], r["total"])


# ---- the leaders' three reminder days (Chris, 2026-11-06) ---------------------------------------------------------------------------
# A Grade H leader's item rides in the reminder email only on the day its part FIRST OPENED for them, 3 days before it closes and on its
# last day (GRADEH_LEAD_DAYS_BEFORE). "First opened for them" reads the same two rules the gates read (gradeh_hod_open_for,
# gradeh_bu_open_for) from the stored times: the later of the cell's start and the earlier of the fallback and the moment everyone they
# wait on had finished. An opening after the day's send time counts from the next day (the send could not have seen it open).
def _gh_first_send_day(moment, send_t):
    """The first send day (a date) on which something that opened at `moment` (MYT datetime) is open at the send time `send_t`."""
    return moment.date() + timedelta(days=1) if moment.time() > send_t else moment.date()


def _gh_utc_to_myt(at):
    """A UTC datetime (or the from-the-start floor) as MYT; None = no time on record = from the start."""
    return _GH_FROM_START if at is None or at <= _GH_FROM_START else at + timedelta(hours=8)


def gradeh_hod_first_open(db, cid, hod_id, cell, now=None, rows=None):
    """The MYT datetime this HOD's stage (`cell`: gradeh_hod_pot / gradeh_hod_perf) first opened for them: the later of the cell's start
    and the earlier of the fallback and the moment the last of their Grade H people had acknowledged (gradeh_hod_open_for's rule; a
    person with no time on record counts from the start). A blank fallback is no early opening: the cell's start. None = no start date
    and no fallback (nothing to say it opened on a day)."""
    now = now or _now_myt()
    o = _parse_when(window_dates(db, cell, cid)[0])
    fb = _gh_fallback(GRADEH_HOD_FALLBACK, cid)
    if fb is None:
        return o
    rows = gradeh_hod_scope(db, hod_id, cid) if rows is None else rows   # `rows` = the HOD's people already read (a page over many HODs)
    inperson = {}
    ids = [r["id"] for r in rows if r["ack_in_person"] and not r["disagree_at"]]
    if ids:   # an acknowledgement recorded in person: the time the line manager recorded it (the row's last update)
        inperson = {r[0]: r[1] for r in db.execute(
            "SELECT person_id, updated_at FROM gradeh_appraisals WHERE cycle_id=? AND person_id IN (%s)" % ",".join("?" * len(ids)),
            [cid] + ids)}
    rule, now_utc = gradeh_deemed_rule(cid), (now - timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
    st = [_gh_ack_state(r, rule, now_utc, inperson) for r in rows]
    cand = [fb]
    if all(c for c, _at in st):   # everyone has finished: the moment the last one did
        cand.append(max([_gh_utc_to_myt(at) for _c, at in st], default=_GH_FROM_START))
    first = min(cand)
    return max(first, o) if o else first


def gradeh_bu_first_open(db, cid, company, business_group=None):
    """The MYT datetime the BU CEO's sign-off first opened for this unit: the later of the cell's start and the earlier of the fallback
    and the moment the last of the unit's people had finished the HOD stage (gradeh_bu_open_for's rule, from _gh_bu_people_done)."""
    o = _parse_when(window_dates(db, GRADEH_CELL_BUCEO, cid)[0])
    fb = _gh_fallback(GRADEH_BU_FALLBACK, cid)
    if fb is None:
        return o
    st = _gh_bu_people_done(db, cid, company, business_group)
    cand = [fb]
    if all(d for d, _at in st):
        cand.append(max([_gh_utc_to_myt(at) for _d, at in st], default=_GH_FROM_START))
    first = min(cand)
    return max(first, o) if o else first


def gradeh_lead_send_days(db, cid, user_id, cells, unit=None, send_t=None, rows=None):
    """The dates (MYT) a Grade H leader's item goes in the reminder email: the first send day its part was open for them, 3 days before
    the part closes and its last day (a day before it first opened for them is dropped, so an HOD whose stage opens on the fallback
    19 Nov, closing 21 Nov, gets 19 and 21). `cells` = the item's cells (an HOD's pending stages: the union), `unit` = (business group,
    company) for a BU CEO's item, `rows` = an HOD's people when the caller has read them. ONE reader: reminder_items asks it for the send
    and its recheck, and so does Grade H progress (gradeh_prog_leaders)."""
    send_t = send_t or _rm_send_time(reminder_rules())
    days = set()
    for cell in cells:
        c = _parse_when(window_dates(db, cell, cid)[1])
        if cell == GRADEH_CELL_BUCEO and unit:
            first = gradeh_bu_first_open(db, cid, unit[1], unit[0])
        elif cell in (GRADEH_CELL_HOD_POT, GRADEH_CELL_HOD_PERF):
            first = gradeh_hod_first_open(db, cid, user_id, cell, **({"rows": rows} if rows is not None else {}))
        else:
            first = _parse_when(window_dates(db, cell, cid)[0])
        fd = _gh_first_send_day(first, send_t) if first else None
        if fd:
            days.add(fd)
        if c:
            for n in GRADEH_LEAD_DAYS_BEFORE:
                d = c.date() - timedelta(days=n)
                if fd is None or d >= fd:
                    days.add(d)
    return days


# ---- Grade H leader progress, the ready notes, and the Grade H "Next" (Chris, 2026-11-09; canvas boards A4 and A5) -----------------------
# PROGRESS (gradeh_lp_hod, gradeh_lp_buceo): to a Grade H HOD (with the role, with Grade H people, not signed off BOTH stages) and to a
# Grade H unit's BU CEO (the unit not signed off or released) on THEIR three days: the day their part first opened FOR THEM (an early
# opening counts), 3 days before it closes and its last day (gradeh_lead_send_days: the very reader Everyone's reminder's Grade H lines
# use), at Everyone's reminder's send time, in its 15-minute job. Counts only: the HOD's table is one row a line manager's team, the BU
# CEO's one row a department. A leader with both roles gets each. The leader's opt-outs (Everyone's reminder OR Leader progress) and the
# Executive Chairman rule hold, as in lp_leaders. ONE decision, gradeh_prog_plan, feeds the send, the Schedule's Next, and the reminder:
# a leader who gets progress today loses their Grade H lead lines from Everyone's reminder today (reminder_items_email).
# READY NOTES (gradeh_ready_hod, gradeh_ready_buceo): once per place per cycle (ready_notices), when all an HOD's Grade H people have
# acknowledged, or every HOD in a unit has finished both stages, before the part's own day: checked daily at Ready for you's time by
# gradeh_ready_auto. A leader whose ready note went today does not also get progress today (the note served).
# Both follow the Grade H switch only (gradeh_rm_active), not Everyone's reminder's or Ready for you's.
GH_PROG_HOD_CELLS = ("gradeh_hod_pot", "gradeh_hod_perf")   # GRADEH_CELL_HOD_POT / _PERF, which are defined further down the file
_GHP_STAGE_CELL = {"pot": "gradeh_hod_pot", "perf": "gradeh_hod_perf"}
_GHP_STAGE_WORD = {"pot": "Potential", "perf": "Performance"}


def gradeh_prog_pop(db, cid):
    """What Grade H progress and its ready notes read about the population, in a few batched reads (never one a person):
    {rows: every Grade H person (gradeh_people with their users columns, _GH_CAL_SQL), by_hod: {HOD id: their rows (a person with a
    second HOD is in both)}, by_unit: {(business group, company): rows}, lm: {person id: their line manager / appraiser id}, hod_signed:
    {str(HOD id): {stages signed}}, bu_signed: {companies the BU CEO signed off}, released: {companies Group People released}}."""
    seats = _gh_seat_pairs(db)
    rows = db.execute(_GH_CAL_SQL + "ORDER BY p.id", (cid,)).fetchall()
    lm = {r[0]: r[1] for r in db.execute("SELECT p.id, COALESCE(p.appraiser_id, uu.manager_id) FROM gradeh_people p JOIN users uu "
                                         "ON uu.id=p.user_id WHERE p.cycle_id=?", (cid,))}
    by_hod, by_unit = {}, {}
    for r in rows:
        for h in _gh_row_hods(db, r, seats):
            by_hod.setdefault(h, []).append(r)
        by_unit.setdefault((r["business_group"], r["company"]), []).append(r)
    hod_signed, bu_signed = {}, set()
    for r in db.execute("SELECT tier, stage, scope_key FROM gradeh_signoffs WHERE cycle_id=?", (cid,)):
        if r[0] == "hod":
            hod_signed.setdefault(r[2], set()).add(r[1])
        elif r[0] == "buceo":
            bu_signed.add(r[2])
    released = {r[0] for r in db.execute("SELECT unit FROM gradeh_releases WHERE cycle_id=?", (cid,))}
    return {"rows": rows, "by_hod": by_hod, "by_unit": by_unit, "lm": lm, "hod_signed": hod_signed, "bu_signed": bu_signed,
            "released": released}


def gradeh_prog_leaders(db, cyc, pop=None, now=None, only=None, with_days=True, kinds=("hod", "buceo")):
    """[{kind 'hod' | 'buceo', user, rows (an HOD's people) | units: [{unit: (bg, company), rows, days}], days}] for every leader Grade H
    progress could reach: not an admin, not left, not the Executive Chairman, not opted out of Everyone's reminder or Leader progress,
    with the leader ability on, and something still to do (an HOD who has not signed off both stages; a unit not signed off or released).
    `days` = the dates (MYT) of their three sends (gradeh_lead_send_days). `only` = one user id. [] with Grade H off. One read of the
    population (gradeh_prog_pop, or `pop` when the caller has it)."""
    cid = gradeh_rm_active(db, cyc)
    if not cid:
        return []
    now = now or _now_myt()
    pop = pop or gradeh_prog_pop(db, cid)
    send_t = _rm_send_time(reminder_rules())
    off = email_optout_ids(db, "reminder") | email_optout_ids(db, "leader_progress")
    chair = chair_user_id(db)
    out = []

    def ok(u, ability):
        return bool(u and not u["left_at"] and u["role"] != "admin" and u["id"] != chair and u["id"] not in off
                    and leader_learn_can(u, ability, db))
    if "hod" in kinds:
        ids = [h for h in sorted(pop["by_hod"]) if only is None or h == only]
        users = {r["id"]: r for r in _gh_in(db, "SELECT * FROM users WHERE id IN (%s)", ids)}
        for h in ids:
            u = users.get(h)
            if not ok(u, GRADEH_CAL_HOD_ABILITY) or pop["hod_signed"].get(str(h), set()) >= set(GRADEH_CAL_STAGES):
                continue
            days = gradeh_lead_send_days(db, cid, h, GH_PROG_HOD_CELLS, None, send_t, rows=pop["by_hod"][h]) if with_days else set()
            out.append({"kind": "hod", "user": u, "rows": pop["by_hod"][h], "days": days})
    if "buceo" in kinds:
        holders = buceo_holders(db)
        by_user = {}
        for unit, rows in sorted(pop["by_unit"].items(), key=lambda x: (x[0][0] or "", x[0][1] or "")):
            u = holders.get(unit)
            if not u or (only is not None and u["id"] != only) or unit[1] in pop["bu_signed"] or unit[1] in pop["released"]:
                continue
            if not ok(u, GRADEH_CAL_BU_ABILITY):
                continue
            days = gradeh_lead_send_days(db, cid, u["id"], (GRADEH_CELL_BUCEO,), unit, send_t) if with_days else set()
            e = by_user.setdefault(u["id"], {"kind": "buceo", "user": u, "units": [], "days": set()})
            e["units"].append({"unit": unit, "rows": rows, "days": days})
            e["days"] |= days
        out += list(by_user.values())
    return out


def gradeh_prog_served_by_note(db, cid, day):
    """{(kind 'hod' | 'buceo', user id)} of the leaders whose Grade H ready note went on `day` (MYT): the note served that day."""
    rev = {v: k for k, v in GH_READY_KIND.items()}
    return {(rev[r[0]], r[1]) for r in db.execute(
        "SELECT kind, user_id FROM ready_notices WHERE cycle_id=? AND kind IN (?,?) AND date(sent_at, '+8 hours')=?",
        (cid, GH_READY_KIND["hod"], GH_READY_KIND["buceo"], _skip_day(day)))}


def gradeh_prog_plan(db, cyc, day, now=None, pop=None, only=None, honour_skips=True):
    """THE decision (one function for the send, the Schedule's Next, the preview and Everyone's reminder): who gets Grade H progress on
    `day` (a date, MYT): {'hod': [entry], 'buceo': [entry], 'skipped': {skip key: the live skip row}}. An entry is a gradeh_prog_leaders
    entry (a BU CEO's `units` cut to the units whose day it is) with `note_served` True when their ready note went that day: the send
    leaves them out, but they count as served (no Grade H lead lines in Everyone's reminder that day either). A kind skipped that day
    (its own key or 'gradeh', when honour_skips) has no entries. Empty with the Grade H switch off or Grade H not running."""
    out = {"hod": [], "buceo": [], "skipped": {}}
    cid = gradeh_rm_active(db, cyc)
    if not cid:
        return out
    kinds = []
    for kind in ("hod", "buceo"):
        sk = email_skip_any(db, ("gradeh", GH_PROG_SKIP[kind]), day) if honour_skips else None
        if sk:
            out["skipped"][GH_PROG_SKIP[kind]] = sk
        else:
            kinds.append(kind)
    if not kinds:
        return out
    served = gradeh_prog_served_by_note(db, cid, day)
    for e in gradeh_prog_leaders(db, cyc, pop, now, only, True, tuple(kinds)):
        if e["kind"] == "hod":
            if day not in e["days"]:
                continue
            ent = dict(e)
        else:
            units = [x for x in e["units"] if day in x["days"]]
            if not units:
                continue
            ent = dict(e, units=units)
        ent["note_served"] = (e["kind"], e["user"]["id"]) in served
        out[e["kind"]].append(ent)
    return out


def gradeh_prog_served(db, cyc, u, day=None, honour_skips=True):
    """{'hod': bool, 'buceo': bool}: is this leader served by Grade H progress (or by its ready note) today? Everyone's reminder leaves
    out the Grade H lead lines of the roles it says True for (one email, not two)."""
    plan = gradeh_prog_plan(db, cyc, day or _today_myt(), only=u["id"], honour_skips=honour_skips)
    return {k: any(e["user"]["id"] == u["id"] for e in plan[k]) for k in ("hod", "buceo")}


def _gh_prog_days_left(close_day, day):
    """'3 days left' / '1 day left' on the leader's 3-days-before send, 'Last day' on the last, else 'Now open' (the opening day)."""
    n = (close_day - day).days
    if n <= 0:
        return "Last day"
    return "%d day%s left" % (n, "" if n == 1 else "s") if n in GRADEH_LEAD_DAYS_BEFORE else "Now open"


def _gh_prog_when(dt):
    """'Sat 21 Nov, 23:59' for a MYT datetime."""
    return "%s, %s" % (_em_day(dt.date()), dt.strftime("%H:%M")) if dt else ""


def gradeh_prog_view(db, cyc, entry, day, pop, prog=None, now=None):
    """Fill one plan entry for its email: entry['sections'] (counts only), entry['vals'] (the template's placeholders), entry['button']
    (the page it opens), entry['closes'] (the first close, a MYT datetime). `prog` = gradeh_hod_progress, read once for all HODs."""
    cid, now = cyc["id"], now or _now_myt()
    u, kind = entry["user"], entry["kind"]
    rule, now_utc = gradeh_deemed_rule(cid), (now - timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")
    names_cache = {}

    def lm_names(ids):
        need = sorted(i for i in ids if i and i not in names_cache)
        for r in _gh_in(db, "SELECT id, full_name FROM users WHERE id IN (%s)", need):
            names_cache[r["id"]] = _em_case(r["full_name"] or "")
        return names_cache
    vals = dict(email_names(db, u), cycle=cyc["name"])
    if kind == "hod":
        rows = entry["rows"]
        teams = {}
        for r in rows:
            teams.setdefault(pop["lm"].get(r["id"]), []).append(r)
        nm = lm_names({t for t in teams if t})
        for t in [t for t in teams if t and not nm.get(t)]:   # a line manager with no name on file is no line manager: one team, not two
            teams.setdefault(None, []).extend(teams.pop(t))
        cells = {}
        for t, rs in teams.items():
            sub = sum(1 for r in rs if r["lm_submitted_at"])
            ack = sum(1 for r in rs if _gh_ack_state(r, rule, now_utc)[0])
            cells[t] = (len(rs), sub, ack)
        done = [t for t, (n, sub, ack) in cells.items() if sub == n and ack == n]
        left = sorted(((("%s's team" % nm[t]) if t else "No line manager on file", cells[t], t) for t in cells if t not in done),
                      key=lambda x: (x[1][2] * 100 // x[1][0], x[1][1] * 100 // x[1][0], x[0].lower(), x[2] or 0))
        srows = [{"name": n, "people": c[0], "cells": [_lp_cell(c[0], c[1]), _lp_cell(c[0], c[2])]} for n, c, _t in left[:LP_HOD_ROWS]]
        rest = left[LP_HOD_ROWS:]
        if rest:
            n_, s_, a_ = (sum(c[i] for _n, c, _t in rest) for i in range(3))
            srows.append({"name": "%d more team%s" % (len(rest), "" if len(rest) == 1 else "s"), "more": True, "people": n_,
                          "cells": [_lp_cell(n_, s_), _lp_cell(n_, a_)]})
        tn = sum(c[0] for c in cells.values())
        ts, ta = sum(c[1] for c in cells.values()), sum(c[2] for c in cells.values())
        fin = sorted(done, key=lambda t: (nm.get(t) or "~").lower() + str(t or 0))
        st = pop["hod_signed"].get(str(u["id"]), set())
        pg = (prog or {}).get(u["id"]) or {}
        stages, pend_close = [], []
        for stg in GRADEH_CAL_STAGES:
            cell = _GHP_STAGE_CELL[stg]
            c = _parse_when(window_dates(db, cell, cid)[1])
            if stg in st:
                stages.append((_GHP_STAGE_WORD[stg], "signed off"))
                continue
            sm = pg.get(stg) or {}
            reviewed = (" (%d of %d reviewed)" % (sm["reviewed"], sm["n"])) if sm.get("n") else ""
            stages.append((_GHP_STAGE_WORD[stg], "not signed off yet%s%s" % (reviewed, (" · closes " + _gh_prog_when(c)) if c else "")))
            if c:
                pend_close.append(c)
        closes = min(pend_close) if pend_close else None
        scope = _lp_join(sorted({display_company(r["business_group"], r["company"]) or (r["company"] or "") for r in rows})) \
            or "your department"
        vals.update(scope=scope, closes=_em_day(closes.date()) if closes else "", people=str(tn), acknowledged=str(ta),
                    days_left=_gh_prog_days_left(closes.date(), day) if closes else "Now open")
        entry.update(sections=[{"name": scope, "rows": srows, "people": tn, "total": [_lp_cell(tn, ts), _lp_cell(tn, ta)],
                                "finished": [nm.get(t) or None for t in fin], "stages": stages}],
                     button=url_for("calib_gradeh_hod"), closes=closes, counts={"people": tn, "submitted": ts, "acknowledged": ta})
    else:
        secs, closes_all, tp, tf = [], [], 0, 0
        for x in entry["units"]:
            bg, co = x["unit"]
            urows, st = _gh_bu_people_state(db, cid, co, bg)
            depts = {}
            for r, (done_, _at) in zip(urows, st):
                d_ = depts.setdefault(proper_name((r["department"] or "").strip()) or "No department on file", [0, 0])
                d_[0] += 1
                d_[1] += 1 if done_ else 0
            order = sorted(depts.items(), key=lambda kv: (kv[1][1] * 100 // kv[1][0], kv[0].lower()))
            n_, f_ = len(urows), sum(1 for d_, _a in st if d_)
            tp, tf = tp + n_, tf + f_
            c = _parse_when(window_dates(db, GRADEH_CELL_BUCEO, cid)[1])
            if c:
                closes_all.append(c)
            secs.append({"name": display_company(bg, co) or co, "rows": [{"name": k, "people": v[0], "cells": [_lp_cell(v[0], v[1])]}
                                                                         for k, v in order],
                         "people": n_, "total": [_lp_cell(n_, f_)], "co": co, "closes": c})
        closes = min(closes_all) if closes_all else None
        scope = _lp_join([s_["name"] for s_ in secs])
        vals.update(scope=scope, closes=_em_day(closes.date()) if closes else "", people=str(tp), finished=str(tf),
                    days_left=_gh_prog_days_left(closes.date(), day) if closes else "Now open")
        entry.update(sections=secs, closes=closes, counts={"people": tp, "finished": tf},
                     button=url_for("calib_gradeh_unit", unit=secs[0]["co"]) if len(secs) == 1 else url_for("dashboard"))
    entry["vals"] = vals
    return entry


_GH_PROG_TH = 'style="padding:6px 8px 6px 0;border-bottom:1px solid #e1e4ec;font:700 11.5px/1.3 %s;color:#5f6678"' % _EM_FONT


def _gh_prog_cell_html(c):
    """One cell: the share (its colour the status), 'N of M' and the bar under them (the leader progress email's look)."""
    if c["pct"] is None:
        return "None to count"
    color = _LP_TONE.get(c["tone"], "#252A59")
    return '<b%s style="font-size:13.5px;color:%s">%d%%</b>&nbsp; %s of %s%s' % (
        ' class="oh-pct-n"' if not c["tone"] else "", color, c["pct"], "{:,}".format(c["done"]), "{:,}".format(c["n"]),
        _lp_bar(c["pct"], c["tone"]))


def _gh_prog_table_html(first_head, heads, sec):
    """One section's table: the place (a line manager's team, a department), People, then a column a count (each a share, 'N of M'
    and a bar), a plain total row. Counts only. Light only: colours by attribute, as the leader progress email."""
    th = "".join('<th align="left" class="oh-mut" %s>%s</th>' % (_GH_PROG_TH, _em_esc(t)) for t in [first_head, "People"] + list(heads))
    body = []
    for r in sec["rows"] + [{"name": "Whole department" if first_head.startswith("Line") else "All departments", "people": sec["people"],
                             "cells": sec["total"], "total": True}]:
        tot, more = r.get("total"), r.get("more")
        plain = tot or more
        td = ('<td valign="top" class="oh-mut"%s style="padding:8px 8px 8px 0;%s font:12px/1.4 %s;color:#5f6678%s">%%s</td>' % (
            ' bgcolor="#f7f8fb"' if more else "", "border-top:1px solid #e1e4ec;" if tot else "border-bottom:1px solid #f0f1f5;",
            _EM_FONT, ";background:#f7f8fb" if more else ""))
        row = td % ('<span class="oh-t1" style="font-size:13.5px;%scolor:#1f2330">%s</span>' % ("font-weight:700;" if tot else "",
                                                                                              _em_esc(r["name"])))
        row += td % ("{:,}".format(r["people"]))
        for c in r["cells"]:
            row += td % (("<b class=\"oh-t1\" style=\"font-size:13.5px;color:#1f2330\">%d%%</b>&nbsp; %s of %s" % (
                c["pct"], "{:,}".format(c["done"]), "{:,}".format(c["n"])) if c["pct"] is not None else "None to count")
                if plain else _gh_prog_cell_html(c))
        body.append("<tr>%s</tr>" % row)
    return ('<table role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 14px;'
            'border-collapse:collapse"><thead><tr>%s</tr></thead><tbody>%s</tbody></table>' % (th, "".join(body)))


def _gh_prog_box(pairs):
    """The stages' box: a WHITE box with a navy left border (Outlook darkens tints), one line a stage, its name bold."""
    inner = "<br>".join("<b>%s</b>: %s" % (_em_esc(k), _em_esc(v)) for k, v in pairs)
    return ('<table role="presentation" width="100%%" cellpadding="0" cellspacing="0" border="0" class="oh-row" bgcolor="#ffffff" '
            'style="margin:0 0 14px;background:#ffffff;border:1px solid #e1e4ec;border-left:4px solid #252A59;border-radius:8px;'
            'border-collapse:separate"><tr><td class="oh-t" style="padding:10px 14px;font:14px/1.55 %s;color:#3a4060">%s</td></tr>'
            '</table>' % (_EM_FONT, inner))


def gradeh_prog_sample(db, kind, me, cyc, closes_day):
    """A made-up entry for the template's preview and test (gradeh_prog_mail): invented teams or departments and counts, addressed to
    the admin, never a real person or place."""
    close = datetime.combine(closes_day, datetime.min.time()).replace(hour=23, minute=59)
    vals = dict(email_names(db, me), cycle=cyc["name"], scope="Sample unit", closes=_em_day(closes_day), days_left="3 days left")
    if kind == "hod":
        rows = [{"name": "Line manager A's team", "people": 14, "cells": [_lp_cell(14, 14), _lp_cell(14, 9)]},
                {"name": "Line manager B's team", "people": 22, "cells": [_lp_cell(22, 20), _lp_cell(22, 13)]}]
        vals.update(people="54", acknowledged="40")
        secs = [{"name": "Sample unit", "rows": rows, "people": 54, "total": [_lp_cell(54, 52), _lp_cell(54, 40)],
                 "finished": ["Line manager C"], "stages": [("Potential", "signed off"),
                                                            ("Performance", "not signed off yet (11 of 40 reviewed) \u00b7 closes "
                                                             + _gh_prog_when(close))]}]
        return {"kind": kind, "user": me, "vals": vals, "sections": secs, "button": url_for("calib_gradeh_hod")}
    rows = [{"name": "Finance", "people": 14, "cells": [_lp_cell(14, 14)]}, {"name": "Operations", "people": 22, "cells": [_lp_cell(22, 13)]},
            {"name": "Sales", "people": 18, "cells": [_lp_cell(18, 9)]}]
    vals.update(people="54", finished="36")
    return {"kind": kind, "user": me, "vals": vals, "button": url_for("dashboard"),
            "sections": [{"name": "Sample unit", "rows": rows, "people": 54, "total": [_lp_cell(54, 36)], "closes": close}]}


def gradeh_prog_mail(db, entry, cyc, now=None, tpl=None):
    """(subject, html) of one leader's Grade H progress email from a gradeh_prog_view entry: the leader progress email's shell, the
    opening, the table (a line manager's team for an HOD, a department for a BU CEO), the HOD's two stages, the button. Counts only:
    the only names are the greeting's and the line managers' own, as the HOD's leader progress email labels its teams."""
    kind = entry["kind"]
    key = GH_PROG_KIND[kind]
    t = _email_tpl_default(key)   # a template saved before a field existed reads OneHR's own words for it
    t.update(tpl or email_tpl_words(key, db=db))
    vals, now = entry["vals"], now or _now_myt()
    fill = lambda k: _tpl_fill(t[k], vals)   # noqa: E731
    as_at = "%s %d %s %d, %s" % (now.strftime("%a"), now.day, now.strftime("%b"), now.year, now.strftime("%H:%M"))
    body = [_em_greet(fill("greeting"))]
    if fill("opening"):
        body.append(_em_p(_em_esc(fill("opening"))))
    for sec in entry["sections"]:
        if kind == "buceo" and len(entry["sections"]) > 1:
            body.append(_ready_title(sec["name"]))
        if kind == "hod":
            body.append(_gh_prog_table_html("Line manager's team", ("Appraisal submitted", "Acknowledged"), sec))
            if sec.get("finished"):
                body.append('<p class="oh-mut" style="margin:0 0 14px;font:12.5px/1.5 %s;color:#5f6678">%s</p>'
                            % (_EM_FONT, _em_esc(_lp_finished_line(sec["finished"]))))
            body.append(_gh_prog_box(sec["stages"]))
        else:
            body.append(_gh_prog_table_html("Department", ("HOD finished (both stages)",), sec))
            if sec.get("closes"):
                body.append(_gh_prog_box([("Sign-off closes", _gh_prog_when(sec["closes"]))]))
    tail = _em_p(_em_esc(fill("closing")), gap=12) if fill("closing") else ""
    what = ("you are the HOD of Grade H people in " if kind == "hod" else "you are the BU CEO of ") + vals["scope"]
    footer = ("You get this because %s. It goes the day your part opens for you, 3 days before it closes and on its last day." % what)
    return fill("subject"), onehr_email(fill("heading"), "".join(body), button=(fill("button"), app_base_url() + entry["button"]),
                                        sub="%s · as at %s" % (vals["scope"], as_at), cycle=vals["cycle"], footer=footer,
                                        after_html=tail)


def gradeh_prog_send(db, cyc, day, why, actor_id=None, now=None, live=True, plan=None, pop=None):
    """Queue the day's Grade H progress emails (the job comes here): one email a leader (a leader with both roles gets each), through
    _outbox_add in waves, batch 'gradeh-lp-<date>'; a leader with no email address is logged 'skipped'. The plan (gradeh_prog_plan) is
    the one decision; a leader whose ready note went today is left out. One activity row, 'gradeh_lp_run', with counts. Returns
    {hods, buceos, emailed, no_email, note_served, skipped: [keys]}."""
    now = now or _now_myt()
    cid = cyc["id"]
    pop = pop or gradeh_prog_pop(db, cid)
    plan = plan or gradeh_prog_plan(db, cyc, day, now, pop)
    tally = {"hods": 0, "buceos": 0, "emailed": 0, "no_email": 0, "note_served": 0, "skipped": sorted(plan["skipped"])}
    entries = [e for k in ("hod", "buceo") for e in plan[k]]
    prog = gradeh_hod_progress(db, cid, now=now) if any(e["kind"] == "hod" and not e["note_served"] for e in entries) else None
    rules, start = email_wave_rules(), _utc_now()
    batch = "gradeh-lp-" + _skip_day(day)
    n = 0
    for e in entries:
        u = e["user"]
        if e["note_served"]:
            tally["note_served"] += 1
            continue
        tally["hods" if e["kind"] == "hod" else "buceos"] += 1
        to = (u["email"] or "").strip()
        kind = GH_PROG_KIND[e["kind"]]
        if not to:
            log_notification(db, cid, u["id"], None, "skipped", detail="no email on file; %s" % e["kind"], kind=kind)
            tally["no_email"] += 1
            continue
        gradeh_prog_view(db, cyc, e, day, pop, prog, now)
        subject, body = gradeh_prog_mail(db, e, cyc, now)
        if live:
            _outbox_add(db, kind, to, subject, body, user_id=u["id"], cycle_id=cid, detail="%s; %s" % (e["kind"], why[:200]),
                        actor_id=actor_id, send_after=_email_wave_at(n, rules, start), batch=batch)
            db.commit()
        n += 1
        tally["emailed"] += 1
    log_activity(db, actor_id, "gradeh_lp_run", "%s | %d HODs | %d BU CEOs | %d emailed | %d no email%s%s%s" % (
        why[:200], tally["hods"], tally["buceos"], tally["emailed"], tally["no_email"],
        (" | %d served by their ready note" % tally["note_served"]) if tally["note_served"] else "",
        (" | skipped: %s" % ", ".join(tally["skipped"])) if tally["skipped"] else "",
        (" | batch %s" % batch) if live and tally["emailed"] else ""))
    if live and tally["emailed"]:
        _outbox_kick()
    return tally


def gradeh_prog_auto(db, cyc, log=None, now=None):
    """The server job's turn (send_reminders.py --auto, in the 15-minute job): Grade H progress at Everyone's reminder's send time, once
    a day, within the grace hours, gated by the Grade H switch only. Returns what it did, in words; a skipped kind says 'Skipped
    today: <reason>.'. The day is marked before sending, so a second tick can't start another."""
    now = now or _now_myt()
    if not gradeh_rm_active(db, cyc):
        return "Grade H progress: the Grade H switch is off, or Grade H does not run on this cycle."
    due, why_not = lp_due_now(db, {"send_time": reminder_rules()["send_time"]}, now, last_key=GRADEH_PROG_LAST_KEY,
                              what="Grade H progress")
    if not due:
        return why_not
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)", (GRADEH_PROG_LAST_KEY, now.date().isoformat()))
    db.commit()
    day = now.date()
    plan = gradeh_prog_plan(db, cyc, day, now)
    said = [email_skip_words(sk) for sk in plan["skipped"].values()]
    if not plan["hod"] and not plan["buceo"]:
        return " ".join(["Grade H progress: nobody's day today."] + said)
    if not mailer.is_configured():
        return "Email isn't set up on this server: no Grade H progress email went out."
    t = gradeh_prog_send(db, cyc, day, "On schedule: the day their part opens, 3 days before it closes and its last day", now=now,
                         plan=plan)
    return " ".join(["Grade H progress: %d HODs, %d BU CEOs, %d emailed, %d with no email address." % (
        t["hods"], t["buceos"], t["emailed"], t["no_email"])] + said)


def gradeh_ready_build(db, cyc, now=None, pop=None, only=None):
    """[{kind, user, key (the place's ready_notices scope_key), name, win, people, hods}] for the Grade H places ready now and not told
    yet (ready_notices): an HOD whose Grade H people have ALL acknowledged (_gh_acked_count, > 0), who has not signed off both stages and
    whose calibration has not closed; a BU CEO's unit where every Grade H person has been through the HOD stage (_gh_bu_people_state,
    > 0, at least one HOD to wait on), not signed off or released, the window not closed. win: mode 'open' (the gate says it is open for
    them now: gradeh_hod_open_for / gradeh_bu_open_for) with `ahead_of` the date it would have opened (the fallback) when that is
    still ahead, or 'later' with the date it opens. Same eligibility as progress (role, ability, opt-outs, the Chairman)."""
    cid = gradeh_rm_active(db, cyc)
    if not cid:
        return []
    now = now or _now_myt()
    pop = pop or gradeh_prog_pop(db, cid)
    told = {(r[0], r[1], r[2]) for r in db.execute("SELECT kind, scope_key, user_id FROM ready_notices WHERE cycle_id=? AND kind IN (?,?)",
                                                   (cid, GH_READY_KIND["hod"], GH_READY_KIND["buceo"]))}
    out = []
    rule, seats = gradeh_deemed_rule(cid), _gh_seat_pairs(db)
    for e in gradeh_prog_leaders(db, cyc, pop, now, only, with_days=False):
        u = e["user"]
        if e["kind"] == "hod":
            rows = e["rows"]
            if not rows or (GH_READY_KIND["hod"], str(u["id"]), u["id"]) in told or _gh_acked_count(rows, cid, now, rule) != len(rows):
                continue
            signed = pop["hod_signed"].get(str(u["id"]), set())
            stage = "pot" if "pot" not in signed else "perf"
            cell = _GHP_STAGE_CELL[stage]
            if window_state(db, cell, cid, now) == "closed":   # their calibration has closed
                continue
            op = gradeh_hod_open_for(db, cid, u["id"], stage, now, rows=rows)
            o, c = (_parse_when(x) for x in window_dates(db, cell, cid))
            fb = _gh_fallback(GRADEH_HOD_FALLBACK, cid)
            win = ({"mode": "open", "ahead_of": fb.date() if fb and now < fb else None, "opens": None, "closes": c} if op["open"]
                   else {"mode": "later", "ahead_of": None, "opens": o or fb, "closes": c})
            scope = _lp_join(sorted({display_company(r["business_group"], r["company"]) or (r["company"] or "") for r in rows}))
            out.append({"kind": "hod", "user": u, "key": str(u["id"]), "name": scope, "win": win, "people": len(rows), "hods": 0,
                        "scope": scope or "your department"})
            continue
        for x in e["units"]:
            bg, co = x["unit"]
            if (GH_READY_KIND["buceo"], co, u["id"]) in told:
                continue
            urows, st = _gh_bu_people_state(db, cid, co, bg)
            hods = {h for r in urows for h in _gh_row_hods(db, r, seats)}
            if not urows or not hods or not all(d for d, _a in st) or window_state(db, GRADEH_CELL_BUCEO, cid, now) == "closed":
                continue
            op = gradeh_bu_open_for(db, cid, co, bg, now)
            o, c = (_parse_when(v) for v in window_dates(db, GRADEH_CELL_BUCEO, cid))
            fb = _gh_fallback(GRADEH_BU_FALLBACK, cid)
            win = ({"mode": "open", "ahead_of": fb.date() if fb and now < fb else None, "opens": None, "closes": c} if op["open"]
                   else {"mode": "later", "ahead_of": None, "opens": o or fb, "closes": c})
            name = display_company(bg, co) or co
            out.append({"kind": "buceo", "user": u, "key": co, "name": name, "win": win, "people": len(urows), "hods": len(hods),
                        "scope": name})
    return out


def gradeh_ready_mail(db, entry, cyc, now=None, tpl=None):
    """(subject, html) of one Grade H ready note (canvas board A5): the leader progress email's shell, the opening of the window the
    leader is in (open now, or the day it opens), the button, and the once-per-place line. Counts and the unit's name only."""
    kind = entry["kind"]
    key = GH_READY_KIND[kind]
    t = _email_tpl_default(key)
    t.update(tpl or email_tpl_words(key, db=db))
    win, now = entry["win"], now or _now_myt()
    day = lambda d: _em_day(d.date() if isinstance(d, datetime) else d) if d else ""   # noqa: E731
    vals = dict(email_names(db, entry["user"]), scope=entry["scope"], cycle=cyc["name"] if cyc else "", people=str(entry["people"]),
                opens=day(win.get("opens")), closes=_gh_prog_when(win["closes"]) if win.get("closes") else "",
                ahead_of=day(win.get("ahead_of")))
    if kind == "buceo":
        vals["hods"] = str(entry["hods"])
    later = win["mode"] == "later"
    fill = lambda k: _ready_fill(t[k], vals)   # noqa: E731
    as_at = "%s %d %s %d, %s" % (now.strftime("%a"), now.day, now.strftime("%b"), now.year, now.strftime("%H:%M"))
    body = [_em_greet(fill("greeting"))]
    opening = fill("opening_later" if later else "opening_open")
    if opening:
        body.append(_em_p(_em_esc(opening)))
    tail = _em_p(_em_esc(fill("closing")), gap=12) if fill("closing") else ""
    button = url_for("calib_gradeh_hod") if kind == "hod" else url_for("calib_gradeh_unit", unit=entry["key"])
    footer = "You get this because you are %s %s in AI+ OneHR by Chin Hin." % (
        "the HOD of Grade H people in" if kind == "hod" else "the BU CEO of", entry["scope"])
    return fill("subject"), onehr_email(fill("heading"), "".join(body),
                                        button=(fill("button_later" if later else "button_open"), app_base_url() + button),
                                        sub="%s · as at %s" % (entry["scope"], as_at), cycle=vals["cycle"], footer=footer,
                                        after_html=tail)


def gradeh_ready_send(db, cyc, why, actor_id=None, now=None, live=True):
    """Queue the Grade H ready notes that are due (the job comes here): one email a place. The ready_notices row is written in the SAME
    transaction as the outbox add, so a place is told once and a failed add leaves no row; a leader with no email address is logged
    'skipped'. A dry run (live=False) writes nothing. One activity row, 'gradeh_ready_run'. Returns {places, emailed, hods, buceos,
    no_email}."""
    now = now or _now_myt()
    built = gradeh_ready_build(db, cyc, now)
    tally = {"places": len(built), "emailed": 0, "hods": 0, "buceos": 0, "no_email": 0}
    for e in built:
        u = e["user"]
        to = (u["email"] or "").strip()
        kind = GH_READY_KIND[e["kind"]]
        if not to:
            log_notification(db, cyc["id"], u["id"], None, "skipped", detail="no email on file; %s" % e["kind"], kind=kind)
            tally["no_email"] += 1
            continue
        subject, body = gradeh_ready_mail(db, e, cyc, now)
        if live:
            if not db.execute("INSERT OR IGNORE INTO ready_notices(cycle_id, kind, scope_key, user_id) VALUES (?,?,?,?)",
                              (cyc["id"], kind, e["key"], u["id"])).rowcount:   # another run told this place first
                db.rollback()
                continue
            _outbox_add(db, kind, to, subject, body, user_id=u["id"], cycle_id=cyc["id"], detail="%s; %s" % (e["kind"], why[:200]),
                        actor_id=actor_id)
            db.commit()
        tally["emailed"] += 1
        tally["hods" if e["kind"] == "hod" else "buceos"] += 1
    log_activity(db, actor_id, "gradeh_ready_run", "%s | %d places | %d emailed | %d HODs | %d BU CEOs | %d no email" % (
        why[:200], tally["places"], tally["emailed"], tally["hods"], tally["buceos"], tally["no_email"]))
    if live and tally["emailed"]:
        _outbox_kick()
    return tally


def gradeh_ready_auto(db, cyc, log=None, now=None):
    """The server job's turn, right after ready_auto's (the same job): the Grade H ready notes, checked every day at Ready for you's
    time, once a day, gated by the Grade H switch ONLY (not Ready for you's own switch). Each place is told once a cycle."""
    now = now or _now_myt()
    if not gradeh_rm_active(db, cyc):
        return "Grade H ready notes: the Grade H switch is off, or Grade H does not run on this cycle."
    due, why_not = lp_due_now(db, {"send_time": ready_rules()["send_time"]}, now, last_key=GRADEH_READY_LAST_KEY,
                              what="the Grade H ready notes check")
    if not due:
        return why_not
    db.execute("INSERT OR REPLACE INTO app_settings(key,value) VALUES (?, ?)", (GRADEH_READY_LAST_KEY, now.date().isoformat()))
    db.commit()
    if not mailer.is_configured():
        return "Email isn't set up on this server: no Grade H ready note went out."
    t = gradeh_ready_send(db, cyc, "On schedule: checked every day at " + ready_rules()["send_time"], now=now)
    return "Grade H ready notes: %d places ready, %d emailed (%d HODs, %d BU CEOs), %d with no email address." % (
        t["places"], t["emailed"], t["hods"], t["buceos"], t["no_email"])


def gradeh_next_send(db, cyc, now=None, horizon=62):
    """The Grade H row's next automatic send (a datetime at Everyone's reminder's time), or None: the earlier of the next staff email
    day (a day only Grade H staff's own email goes on, or the reminder's day with Grade H staff: reminder_day_parts, read with the
    Everyone's reminder switch ignored) and the next day a Grade H leader gets progress (gradeh_prog_leaders' days), each not skipped
    ('gradeh', or the progress kind's own key), not a day its own *_last key says it went, today only while its time is to come."""
    cid = gradeh_rm_active(db, cyc)
    if not cid:
        return None
    now = now or _now_myt()
    rules = reminder_rules()
    send_t = _rm_send_time(rules)
    leaders = gradeh_prog_leaders(db, cyc, None, now)
    best = None
    for i in range(horizon):
        d = now.date() + timedelta(days=i)
        if email_skip_row(db, "gradeh", d):
            continue
        staff = _email_day_open(now, d, send_t, gradeh_staff_last_key(db)) and reminder_day_parts(db, cyc, d, rules, True)["staff"]
        prog = _email_day_open(now, d, send_t, GRADEH_PROG_LAST_KEY) and any(
            d in e["days"] and not email_skip_row(db, GH_PROG_SKIP[e["kind"]], d) for e in leaders)
        if staff or prog:
            best = datetime.combine(d, send_t)
            break
    return best


# ---- the writers: one each, (ok, message); none commits ------------------------------------------------------------------
GH_DISAGREE_CAL_MSG = "This person does not agree with their result, so it is not calibrated. Their band stays as it is."


def _gh_cal_audit(db, u, action, detail, target=None):
    log_activity(db, u["id"], action, detail, target_user_id=target, commit=False)


def _gh_cal_hod_person(db, u, cid, pid):
    """(person dict, moves, revs, yes, row) when this account is that person's HOD (submitted or not), else (None, ...)."""
    row = next((r for r in gradeh_hod_scope(db, u["id"], cid) if r["id"] == pid), None)
    if not row:
        return None, None, None, None, None
    mv, rv, ys = _gh_cal_load(db, cid, [row])
    return _gh_cal_person(row, mv, rv, ys, as_hod=u["id"]), mv, rv, ys, row


def _gh_cal_hod_stage_gate(db, cid, hod_id, company, stage):
    """None when the HOD may still change this stage, else the words: the unit locked, the stage signed, or potential unsigned."""
    lock = _gh_cal_lock_text(db, cid, company)
    if lock:
        return lock
    shut = gradeh_hod_gate(db, cid, hod_id, stage)   # the calendar's dates (piece 6), then the early-opening rule
    if shut:
        return shut
    st = gradeh_hod_state(db, cid, hod_id)
    if st[stage]:
        return "You have signed off %s, so it can't change now." % ("potential" if stage == "pot" else "performance")
    if stage == "perf" and not st["pot"]:
        return "Sign off Grade H potential first: performance opens after it."
    return None


def gradeh_hod_move(db, u, pid, stage, band, remark):
    """THE HOD's move of one person's band on one stage's axis. The HOD never waits for the line manager: a person nobody has
    submitted for shows the default band (GRADEH_DEFAULT_BAND) and can be moved from it. Refused: not their person; a stage out of
    order or signed off; the unit signed off by the BU CEO or released; the band they already have; and everything
    gradeh_record_move refuses (their own band, no remark, an over-long or unscreened remark)."""
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_HOD_ABILITY, db):
        return False, "Grade H Appraisal isn't open to you."
    if stage not in GRADEH_CAL_STAGES:
        return False, "That is not a stage."
    own = db.execute("SELECT 1 FROM gradeh_people WHERE id=? AND cycle_id=? AND user_id=?", (pid, cid, u["id"])).fetchone()
    if own:
        return False, _calib_self_msg("hod")
    p, _mv, _rv, _ys, _row = _gh_cal_hod_person(db, u, cid, pid)
    if not p:
        return False, "That person isn't in your department."
    if p["disagree"]:   # told us they do not agree: not calibrated, on either axis (no HOD move reaches them)
        return False, GH_DISAGREE_CAL_MSG
    gate = _gh_cal_hod_stage_gate(db, cid, u["id"], p["company"], stage)
    if gate:
        return False, gate
    axis = GRADEH_CAL_AXIS[stage]
    if band == p["b_hod"][axis]:
        return False, "That is the band they already have. Tick Agree to keep it."
    ok, msg = gradeh_record_move(db, cid, pid, axis, "hod", band, remark, u)
    if ok:
        _gh_cal_audit(db, u, "gradeh_hod_move", "person %d, %s %s to %s" % (pid, axis, p["b_hod"][axis], band), p["uid"])
    return ok, msg


def gradeh_hod_agree(db, u, stage, shown, ticked):
    """The HOD's ticks on one stage: for the people on screen (`shown`), a tick is "I agree with the band they have" and an
    untick takes it back. A moved person keeps their move. A person with no line manager input is agreed at the default band they
    are shown (stored as the HOD's agreed band, never as the line manager's). Returns (ok, message). Nothing outside their
    department or after sign-off changes."""
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_HOD_ABILITY, db):
        return False, "Grade H Appraisal isn't open to you."
    if stage not in GRADEH_CAL_STAGES:
        return False, "That is not a stage."
    rows = {r["id"]: r for r in gradeh_hod_scope(db, u["id"], cid)}
    shown = [x for x in shown if x in rows]
    if not shown:
        return False, "No one to save."
    mv, rv, ys = _gh_cal_load(db, cid, [rows[x] for x in shown])
    people = {x: _gh_cal_person(rows[x], mv, rv, ys, as_hod=u["id"]) for x in shown}
    if any(people[x]["disagree"] for x in shown):   # not calibrated: no tick for them, and nothing of theirs is saved with it
        return False, GH_DISAGREE_CAL_MSG
    gate = _gh_cal_hod_stage_gate(db, cid, u["id"], people[shown[0]]["company"], stage)
    if gate:
        return False, gate
    axis = GRADEH_CAL_AXIS[stage]
    n = 0
    for x in shown:
        p = people[x]
        if p["hod_moved"][axis]:
            continue
        if rows[x]["hod2_id"]:
            # a person with a second HOD: each HOD's tick is their own (gradeh_hod_reviews, one a HOD, person and axis); a tick of this HOD's
            # left in gradeh_reviews from before the second HOD came is moved here, the other HOD's is never touched
            db.execute("DELETE FROM gradeh_reviews WHERE cycle_id=? AND person_id=? AND axis=? AND tier='hod' AND by_user_id=?",
                       (cid, x, axis, u["id"]))
            if x in ticked:
                db.execute("INSERT INTO gradeh_hod_reviews(cycle_id, person_id, axis, by_user_id, band) VALUES (?,?,?,?,?) "
                           "ON CONFLICT(cycle_id, person_id, axis, by_user_id) DO UPDATE SET band=excluded.band, "
                           "created_at=datetime('now')", (cid, x, axis, u["id"], p["b_hod"][axis]))
                n += 1
            else:
                db.execute("DELETE FROM gradeh_hod_reviews WHERE cycle_id=? AND person_id=? AND axis=? AND by_user_id=?",
                           (cid, x, axis, u["id"]))
            continue
        if x in ticked:
            db.execute("INSERT INTO gradeh_reviews(cycle_id, person_id, axis, tier, band, by_user_id) VALUES (?,?,?,?,?,?) "
                       "ON CONFLICT(cycle_id, person_id, axis, tier) DO UPDATE SET band=excluded.band, by_user_id=excluded.by_user_id, "
                       "created_at=datetime('now')", (cid, x, axis, "hod", p["b_hod"][axis], u["id"]))
            n += 1
        else:
            db.execute("DELETE FROM gradeh_reviews WHERE cycle_id=? AND person_id=? AND axis=? AND tier='hod'", (cid, x, axis))
    _gh_cal_audit(db, u, "gradeh_hod_agree", "%s, %d agreed" % (stage, n))
    return True, "Saved: %d agreed." % n


def gradeh_hod_signoff(db, u, stage, reason=None):
    """The HOD signs off one stage for their department, whoever has or has not been submitted (they never wait for a line
    manager). Refused: nobody in the department; a stage signed already or out of order; the unit locked; someone neither agreed
    nor moved; a spread off the curve with no reason (then the reason is stored). The curve is over everyone. Once signed, each
    person's agreed band stands over anything a line manager submits later. Returns (ok, message)."""
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_HOD_ABILITY, db):
        return False, "Grade H Appraisal isn't open to you."
    if stage not in GRADEH_CAL_STAGES:
        return False, "That is not a stage."
    rows = gradeh_hod_scope(db, u["id"], cid)
    if not rows:
        return False, "You have no Grade H people to sign off."
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    ALL = [_gh_cal_person(r, mv, rv, ys, as_hod=u["id"]) for r in rows]
    P = [p for p in ALL if not p["disagree"]]   # a person who does not agree is not calibrated: they neither hold up the sign-off nor count on the curve
    for co in {p["company"] for p in ALL}:
        gate = _gh_cal_hod_stage_gate(db, cid, u["id"], co, stage)
        if gate:
            return False, gate
    axis = GRADEH_CAL_AXIS[stage]
    todo = [p for p in P if not p["hod_done"][axis]]
    if todo:
        return False, "%d still to review: tick Agree or change the band, then Save." % len(todo)
    c0 = rows[0]
    cv = gradeh_calib_curve(db, cid, axis, [p["b_hod"][axis] for p in P], c0["business_group"], c0["company"])
    clean = None
    if cv["breaches"]:
        clean, err = gradeh_text_check(reason, "reason")
        if err:
            return False, "The spread is off the %s curve: %s" % ("potential" if axis == "pot" else "performance", err)
    db.execute("INSERT INTO gradeh_signoffs(cycle_id, tier, stage, scope_key, signed_by, off_curve_reason) VALUES (?,?,?,?,?,?)",
               (cid, "hod", stage, str(u["id"]), u["id"], clean))
    _gh_cal_audit(db, u, "gradeh_hod_signoff", "%s, %d people%s%s" % (stage, len(P), ", off the curve" if clean else "",
                                                                     (", %d not calibrated (do not agree)" % (len(ALL) - len(P))) if len(ALL) != len(P) else ""))
    return True, "Signed off Grade H %s." % ("potential" if stage == "pot" else "performance")


def _gh_cal_unit_person(db, u, cid, pid):
    """(person dict, row) when this BU CEO holds the person's unit, else (None, None)."""
    for bg, co in gradeh_buceo_units(db, u):
        row = next((r for r in gradeh_unit_scope(db, cid, bg, co) if r["id"] == pid), None)
        if row:
            mv, rv, ys = _gh_cal_load(db, cid, [row])
            return _gh_cal_person(row, mv, rv, ys), row
    return None, None


def gradeh_buceo_move(db, u, pid, perf, pot, remark):
    """THE BU CEO's move of one person: performance and / or potential, one remark for both. Each axis is a move of its own
    (stage 'buceo') only when it differs from the band they have at this level. Once the sign-off is open (gradeh_bu_gate) the BU CEO
    waits for neither the HOD nor the line manager (a person with no input shows the default band, GRADEH_DEFAULT_BAND). Refused:
    not their unit; their own band; the unit signed off or released; the sign-off not open for the unit (the calendar, or the early rule); nothing changed; and everything gradeh_record_move refuses. All or nothing."""
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_BU_ABILITY, db):
        return False, "Grade H Appraisal isn't open to you."
    own = db.execute("SELECT 1 FROM gradeh_people WHERE id=? AND cycle_id=? AND user_id=?", (pid, cid, u["id"])).fetchone()
    if own:
        return False, _calib_self_msg("buceo")
    p, _row = _gh_cal_unit_person(db, u, cid, pid)
    if not p:
        return False, "That person isn't in your unit."
    if p["disagree"]:   # told us they do not agree: not calibrated, on either axis (no BU CEO move reaches them)
        return False, GH_DISAGREE_CAL_MSG
    lock = _gh_cal_lock_text(db, cid, p["company"])
    if lock:
        return False, lock
    shut = gradeh_bu_gate(db, cid, p["bg"], p["company"])   # the calendar's dates (piece 6), then the early-opening rule
    if shut:
        return False, shut
    sets = []
    for axis, band in (("perf", perf), ("pot", pot)):
        if band in (None, ""):
            continue
        if not gradeh_band_valid(axis, band):
            return False, "That is not a band this stage can set."
        if band != p["b_bu"][axis]:
            sets.append((axis, band))
    if not sets:
        return False, "Nothing changed: pick a different band."
    try:
        for axis, band in sets:
            ok, msg = gradeh_record_move(db, cid, pid, axis, "buceo", band, remark, u)
            if not ok:
                db.rollback()
                return False, msg
    except Exception:
        db.rollback()
        raise
    _gh_cal_audit(db, u, "gradeh_buceo_move", "person %d, %s" % (pid, ", ".join("%s %s to %s" % (a_, p["b_bu"][a_], b_) for a_, b_ in sets)),
                  p["uid"])
    return True, "Saved."


def gradeh_buceo_signoff(db, u, unit, reason=None):
    """The BU CEO signs off one unit's Grade H Appraisal (both axes, every person on the list). They wait for no HOD and no line
    manager: the HODs who have not signed off are named in the page's confirm box, and signing off makes everyone's band as it
    stands final for the unit. Refused: not their unit; signed or released; the sign-off not open for the unit (gradeh_bu_gate); nobody on the unit's list; a spread
    off either curve (over everyone) with no reason (stored). Writes the BU CEO's agreed band (gradeh_reviews, tier 'buceo') for
    every person and both axes, the default included, except the BU CEO's own record (nobody sets their own band): from then on
    that band supersedes anything a lower tier or a line manager adds. Returns (ok, message)."""
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u or is_admin(u) or not leader_learn_can(u, GRADEH_CAL_BU_ABILITY, db):
        return False, "Grade H Appraisal isn't open to you."
    seat = next(((bg, co) for bg, co in gradeh_buceo_units(db, u) if co == unit), None)
    if not seat:
        return False, "That isn't your unit."
    lock = _gh_cal_lock_text(db, cid, unit)
    if lock:
        return False, lock
    shut = gradeh_bu_gate(db, cid, seat[0], seat[1])   # the calendar's dates (piece 6), then the early-opening rule
    if shut:
        return False, shut
    rows = gradeh_unit_scope(db, cid, seat[0], seat[1])
    if not rows:
        return False, "Nobody is on the Grade H list for this unit, so there is nothing to sign off."
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    ALL = [_gh_cal_person(r, mv, rv, ys) for r in rows]
    P = [p for p in ALL if not p["disagree"]]   # a person who does not agree is neither on the curve nor given a BU CEO band
    off = []
    for axis in ("perf", "pot"):
        cv = gradeh_calib_curve(db, cid, axis, [p["b_bu"][axis] for p in P], seat[0], seat[1])
        if cv["breaches"]:
            off.append("potential" if axis == "pot" else "performance")
    clean = None
    if off:
        clean, err = gradeh_text_check(reason, "reason")
        if err:
            return False, "The spread is off the %s curve: %s" % (" and ".join(off), err)
    db.execute("INSERT INTO gradeh_signoffs(cycle_id, tier, stage, scope_key, signed_by, off_curve_reason) VALUES (?,?,?,?,?,?)",
               (cid, "buceo", "all", unit, u["id"], clean))
    db.executemany(
        "INSERT INTO gradeh_reviews(cycle_id, person_id, axis, tier, band, by_user_id) VALUES (?,?,?,?,?,?) "
        "ON CONFLICT(cycle_id, person_id, axis, tier) DO UPDATE SET band=excluded.band, by_user_id=excluded.by_user_id, "
        "created_at=datetime('now')",
        [(cid, p["id"], ax, "buceo", p["b_bu"][ax], u["id"]) for p in P if p["uid"] != u["id"] for ax in GRADEH_AXES])
    _gh_cal_audit(db, u, "gradeh_buceo_signoff", "%s, %d people%s%s" % (unit, len(P), ", off the curve" if clean else "",
                                                                      (", %d not calibrated (do not agree)" % (len(ALL) - len(P))) if len(ALL) != len(P) else ""))
    return True, "Signed off Grade H Appraisal for %s." % unit


# ---- the pages' data -------------------------------------------------------------------------------------------------------
def _gh_cal_band_text(band, axis):
    """'3 ME' for a performance band, 'High' for a potential band; '' for none."""
    if not band:
        return ""
    return ("%d %s" % (GRADEH_CAL_RANK[band], band)) if axis == "perf" else band


def _gh_cal_initials(name):
    bits = [b for b in re.split(r"\s+", (name or "").strip()) if b]
    return ((bits[0][0] + (bits[-1][0] if len(bits) > 1 else "")) if bits else "?").upper()


def _gh_cal_fig(p):
    """The line manager's figure in one short chip: 'KPI 96%' (a % scale) or 'LM 3.38' (an average of ratings)."""
    if p["perf_value"] is not None:
        return "KPI %s%%" % _gh_pct_str(p["perf_value"])
    if p["perf_rating"] is not None:
        return "LM %.2f" % float(p["perf_rating"])
    return ""


def _gh_cal_when(utc_raw):
    dt = _gh_myt(utc_raw)
    return gh_when(dt, "en", time=False, year=False) if dt else ""


def _gh_cal_curve_view(cv, picked=None, links=None):
    """The curve's rows for the template (what calibDistBox draws): per band the count, %, expected %, the gap words, whether it
    is a filter link and lit. `links` = {band: url} (a band nobody sits in is not a link)."""
    rows = []
    for b in cv["order"]:
        n, tgt, gap = cv["dist"][b], cv["target"][b], cv["gaps"][b]
        pct = int(round(n * 100.0 / cv["total"])) if cv["total"] else 0
        tgt_s = _gh_pct_str(tgt)
        rows.append({"band": b, "label": cv["labels"][b], "n": n, "pct": pct, "tgt": tgt_s, "tgt_pos": min(100, float(tgt)),
                     "fill": min(100, pct), "on": picked == b,
                     "gap": ("–" if not cv["total"] else ("%d fewer than expected" % gap) if gap > 0
                             else ("%d more than expected" % -gap) if gap < 0 else "As expected"),
                     "gap_kind": "short" if gap > 0 else "over" if gap < 0 else "ok",
                     "url": (links or {}).get(b) if (n or picked == b) else None})
    return rows


def _gh_cal_verdict(cv):
    """The curve's one-line verdict, in the leaders' words."""
    tol = cv["tol"]
    tolw = "%d %s" % (tol, "person" if tol == 1 else "people")
    if not cv["total"]:
        return "empty", "No one is on the curve yet."
    if not cv["off"]:
        return "ok", "Every band is within %s of the expected spread." % tolw
    return "off", "Outside the expected spread in %s (by more than %s)." % (", ".join(cv["labels"][b] for b in cv["off"]), tolw)


def _gh_dis_line(n_curve, n_dis):
    """The line over a curve when someone in it does not agree: how many are on the curve and why the others are not. '' for none."""
    if not n_dis:
        return ""
    return "%d %s on the curve. %d %s with their result: shown below, not calibrated and not counted." % (
        n_curve, "person" if n_curve == 1 else "people", n_dis, "person does not agree" if n_dis == 1 else "people do not agree")


def _gh_hod_names(db, people):
    """{user id: name} of every live HOD of these people (dicts of _gh_cal_person): one batched read, {} when nobody is shared."""
    ids = sorted({h["id"] for p in people for h in p["hods"]})
    return {r["id"]: (r["full_name"] or "").strip() for r in _gh_in(db, "SELECT id, full_name FROM users WHERE id IN (%s)", ids)} if ids else {}


def _gh_blend_words(parts, order):
    """(band, words) of a HOD-level blend: the band bu_blend_n gives and why, 'ME and AE at 50 : 50, exactly halfway takes the lower
    band'. One part: that band alone."""
    band = bu_blend_n(parts, order)
    ps = [(b, w) for b, w in parts if b in order and (w or 0) > 0]
    if len(ps) < 2:
        return band, ""
    x = sum(order.index(b) * w for b, w in ps) / float(sum(w for _b, w in ps))
    half = abs((x - math.floor(x + 1e-9)) - 0.5) < 1e-9
    return band, "%s at %s%s" % (" and ".join(b for b, _w in ps), " : ".join(str(w) for _b, w in ps),
                                 ", exactly halfway takes the lower band" if half else "")


def _gh_shared_row(p, u_id, axis, names, rv):
    """What a HOD of a SHARED person sees under the person's row (canvas H3): the other HOD's call as it stands (signed or not) and what
    the person's HOD band will be. None for a person with one HOD. Words only; the band is _gh_hod_level's, computed in code."""
    if not p["shared"]:
        return None
    me = next((h for h in p["hods"] if h["id"] == u_id), None)
    ot = next((h for h in p["hods"] if h["id"] != u_id), None)
    if not me or not ot:
        return None
    order = GRADEH_PERF_BANDS if axis == "perf" else GRADEH_POT_BANDS
    ob = ot[axis]
    parts = [(p["b_hod"][axis], me["share"])] + ([(ob["band"], ot["share"])] if ob["band"] else [])
    will, why = _gh_blend_words(parts, order)
    when = _gh_cal_when(getattr(rv, "hod_signs", {}).get((str(ot["id"]), axis))) if ob["signed"] else ""
    return {"chip": "Shared %d : %d" % (me["share"], ot["share"]), "share": ot["share"], "name": names.get(ot["id"], "the other HOD"),
            "band": ob["band"] or "", "band_text": _gh_cal_band_text(ob["band"], axis),
            "state": ("signed off" + ((" " + when) if when else "")) if ob["signed"] else ("not signed off yet" if ob["band"] else "no call yet"),
            "signed": ob["signed"], "will": _gh_cal_band_text(will, axis),
            "will_when": "once you sign off" if ob["signed"] or not ob["band"] else "once you both sign off",
            "will_why": why or ("your band alone until %s has called them" % names.get(ot["id"], "the other HOD") if not ob["band"] else "")}


def gradeh_hod_stage_summary(people, stage, signoff=None):
    """THE count behind "k of n reviewed" and "Signed off 13 Nov" on one HOD's Grade H stage: `people` are the dicts _gh_cal_person gives
    for THAT HOD's own people read as that HOD (as_hod=their id); `signoff` is their sign-off of the stage (a row or any mapping with
    "signed_at") or None. n = the people who are calibrated (a person who does not agree is not); reviewed = those the HOD has moved or
    agreed (hod_done: a tick the line manager's later submission has made stale does not count). The HOD's own page, the progress
    beside the unit and the admin's By HOD table all call this and nothing else."""
    ax = GRADEH_CAL_AXIS[stage]
    sub = [p for p in people if not p["disagree"]]
    return {"n": len(sub), "reviewed": sum(1 for p in sub if p["hod_done"][ax]),
            "signed": signoff is not None, "signed_on": _gh_cal_when(signoff["signed_at"]) if signoff is not None else ""}


def gradeh_hod_view(db, u, cid, stage_req=None, band_f=None):
    """Everything the HOD's page (C1b potential, C1 performance) draws, read-only."""
    rows = gradeh_hod_scope(db, u["id"], cid)
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    ALL = [_gh_cal_person(r, mv, rv, ys, as_hod=u["id"]) for r in rows]
    lp_max = gradeh_lp_max(cid)   # the cycle's own most (Points per answer): "score / most"
    P = [p for p in ALL if not p["disagree"]]   # on the curve and in the counts: everyone but a person who does not agree (not calibrated)
    n_dis = len(ALL) - len(P)
    sub = P   # everyone calibrated in the department: the HOD never waits for a line manager (those with no input show the default band)
    st = gradeh_hod_state(db, cid, u["id"])
    stage = stage_req if stage_req in GRADEH_CAL_STAGES else ("perf" if st["pot"] else "pot")
    if stage == "perf" and not st["pot"]:
        stage = "pot"
    axis = GRADEH_CAL_AXIS[stage]
    c0 = rows[0] if rows else None
    cos = sorted({p["company"] for p in ALL})
    gates = {stg: next(filter(None, (_gh_cal_hod_stage_gate(db, cid, u["id"], co, stg) for co in cos)), None) for stg in GRADEH_CAL_STAGES}
    summary = {}
    for stg in GRADEH_CAL_STAGES:
        ax = GRADEH_CAL_AXIS[stg]
        summary[stg] = dict(gradeh_hod_stage_summary(ALL, stg, st[stg]), locked=gates[stg] if not st[stg] else None)
    cv = gradeh_calib_curve(db, cid, axis, [p["b_hod"][axis] for p in sub], c0["business_group"] if c0 else None,
                            c0["company"] if c0 else None)
    cur = summary[stage]
    picked = band_f if band_f in cv["order"] else None
    tbl = []
    names = _gh_hod_names(db, ALL)
    for p in ALL:   # a person who does not agree stays in the list, with their line manager's band, but is not calibrated
        if picked and p["b_hod"][axis] != picked:
            continue
        mvd = p["hod_moved"][axis]
        yes = p["yes"]
        tbl.append({"shared": None if p["disagree"] else _gh_shared_row(p, u["id"], axis, names, rv),
                    "dis": p["disagree"], "dis_on": p["disagree_on"], "id": p["id"], "name": p["name"], "title": p["title"], "fig": _gh_cal_fig(p),
                    "score": ("%s / %s" % (_gh_pct_str(p["pot_score"]), _gh_pct_str(lp_max)) if p["pot_score"] is not None else ""),
                    "yes": ("%d of 14 Yes" % yes[0]) if yes else "",
                    "lm": _gh_cal_band_text(p["lm"][axis], axis), "lm_band": p["lm"][axis], "nolm": not p["submitted"],
                    "shared_wait": p["shared_wait"] and axis == "perf", "late": p["late_text"],
                    "pot_now": p["b_hod"]["pot"] or "", "perf_now": _gh_cal_band_text(p["b_hod"]["perf"], "perf"),
                    "hod": _gh_cal_band_text(p["b_hod"][axis], axis) if p["hod_done"][axis] else "",
                    "hod_band": p["b_hod"][axis] if p["hod_done"][axis] else "", "now": p["b_hod"][axis],
                    "moved": bool(mvd), "agreed": p["hod_done"][axis] and not mvd,
                    "remark": mvd["remark"] if mvd else "",
                    "ack": "Disagrees" if p["disagree"] else {"yes": "Yes", "person": "In person", "deemed": "Deemed"}.get(p["ack"], "–")})
    lm_missing = sum(1 for p in P if not p["submitted"])
    unsigned_nonempty = bool(ALL)   # a department whose only people do not agree can still sign off (nobody to calibrate)
    ready = (not cur["signed"]) and not cur["locked"] and unsigned_nonempty and cur["reviewed"] == len(sub)
    kind, verdict = _gh_cal_verdict(cv)
    next_up = [{"id": p["id"], "name": p["name"], "sub": p["title"], "now": _gh_cal_band_text(p["b_hod"][axis], axis)}
               for p in sub if not p["hod_done"][axis]]
    pc = gradeh_setting("gradeh_pot_cuts", cid)
    fit_on = bool(P) and not cur["signed"] and not cur["locked"] and leader_learn_can(u, GRADEH_FIT_HOD_ABILITY, db)   # the AI fit: only while the stage can change
    return {"fit_on": fit_on, "pot_cuts": [_gh_pct_str(x) for x in pc], "pot_max": _gh_pct_str(lp_max), "curve_text": " · ".join(_gh_pct_str(cv["target"][b]) for b in cv["order"]),
            "stage": stage, "axis": axis, "summary": summary, "cur": cur, "curve": cv, "verdict": verdict, "verdict_kind": kind,
            "picked": picked, "rows": tbl, "n_shown": len(tbl), "n_sub": len(P), "n_all": len(ALL), "n_people": len(ALL),
            "n_dis": n_dis, "dis_line": _gh_dis_line(len(P), n_dis), "lm_missing": lm_missing,
            "default_text": "%s / %s" % (GRADEH_DEFAULT_BAND["perf"], GRADEH_DEFAULT_BAND["pot"]),
            "ready": ready, "reason_needed": bool(cv["breaches"]), "off_text": ", ".join(cv["labels"][b] for b in cv["off"]),
            "next_up": next_up, "unit": (c0["company"] if c0 else ""), "bg": (c0["business_group"] if c0 else ""),
            "depts": sorted({p["dept"] for p in P if p["dept"]}), "unit_name": proper_name(c0["company"]) if c0 else "",
            "unit_signed": bool(cos and any(gradeh_buceo_signoff_row(db, cid, co) for co in cos)),
            "curve_rows": _gh_cal_curve_view(cv, picked,
                                             {b: url_for("calib_gradeh_hod", stage=stage, band=b) for b in cv["order"]}
                                             if not picked else {b: url_for("calib_gradeh_hod", stage=stage) if b == picked
                                                                 else url_for("calib_gradeh_hod", stage=stage, band=b) for b in cv["order"]})}


def gradeh_hod_progress(db, cid, pids=None, now=None):
    """What each HOD's own page says about their two stages, for every HOD at once: {HOD user id: {"n": their calibrated people, "pot": s,
    "perf": s}} for each HOD who takes at least one of these Grade H people (`pids` = gradeh_people ids, None = all on the cycle's list).
    Each s is gradeh_hod_stage_summary (n, reviewed, signed, signed_on; THE definition the HOD's page uses, over the people read as that HOD,
    `_gh_cal_person(as_hod=)`) plus "gate": the words why the stage is not open for them (gradeh_hod_gate, the calendar and the early-opening
    rule; for performance also "potential first"), None when it is open or signed off. The whole population is read ONCE (the people, the moves,
    the ticks, the sign-offs: _gh_cal_load) and each HOD is handed their own rows: never a read a HOD. A HOD is a slot of _gh_slots (not the
    person, not their unit's BU CEO, holding the HOD role), the same people gradeh_hod_scope gives them."""
    now = now or _now_myt()
    rows = [r for r in db.execute(_GH_CAL_SQL + "ORDER BY p.id", (cid,)) if pids is None or r["id"] in pids]
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    seats = _gh_seat_pairs(db)
    by, rws = {}, {}
    for r in rows:
        for h, _sh in _gh_slots(db, r["hod_id"], r["hod2_id"], r["hod_split"], r["user_id"], r["company"], seats):
            by.setdefault(h, []).append(_gh_cal_person(r, mv, rv, ys, as_hod=h))
            rws.setdefault(h, []).append(r)
    signs = rv.hod_signs   # {(scope_key, stage): signed_at}: a HOD has signed a stage when their row is there (gradeh_hod_state's rule)
    fb = _gh_fallback(GRADEH_HOD_FALLBACK, cid)   # one read each for every HOD
    rule = gradeh_deemed_rule(cid)
    out = {}
    for h, ps in by.items():
        d = {"n": sum(1 for p_ in ps if not p_["disagree"])}
        for stg in GRADEH_CAL_STAGES:
            k = (str(h), stg)
            sm = gradeh_hod_stage_summary(ps, stg, {"signed_at": signs[k]} if k in signs else None)
            gate = None
            if not sm["signed"]:
                gate = gradeh_hod_gate(db, cid, h, stg, now, rws[h], fb, rule)
                if not gate and stg == "perf" and (str(h), "pot") not in signs:
                    gate = "Sign off Grade H potential first: performance opens after it."
            sm["gate"] = gate
            d[stg] = sm
        out[h] = d
    return out


def gradeh_buceo_person_detail(db, cid, prow):
    """One person for the BU CEO's page: the line manager's facts (what they rated, answered and wrote, the promotion nomination
    for calibrators), and the HOD's and BU CEO's moves with their remarks."""
    pid = prow["id"]
    a = db.execute("SELECT b_achievements, b_strengths, b_development, conversation_held, promo_nominate, promo_reason FROM gradeh_appraisals "
                   "WHERE cycle_id=? AND person_id=?", (cid, pid)).fetchone()   # named columns: never disagree_reason (the super admin's alone)
    out = {"route": prow["route"], "attrs": [], "kpis": [], "lps": [], "b": {}, "promo": None, "moves": []}
    if prow["route"] == "B":
        rs = {r["attr_key"]: r["rating"] for r in db.execute(
            "SELECT attr_key, rating FROM gradeh_ratings WHERE cycle_id=? AND person_id=?", (cid, pid))}
        out["attrs"] = [{"title": at["title"][0], "rating": rs.get(at["key"]),
                         "label": GRADEH_RATING_LABELS[rs[at["key"]]][0] if rs.get(at["key"]) else ""} for at in GRADEH_ATTRIBUTES]
    else:
        for l in db.execute("SELECT l.kpi_name, l.weight, l.group_scale, l.bu_kpi_id, l.bu_pct, l.bu_rating, e.staff_pct, e.lm_pct, e.lm_reason, e.lm_rating "
                            "FROM gradeh_kpi_lines l LEFT JOIN gradeh_kpi_entries e ON e.line_id=l.id "
                            "WHERE l.cycle_id=? AND l.person_id=? ORDER BY l.sort_order, l.id", (cid, pid)):
            if l["bu_kpi_id"]:   # a line that shares a unit's result: Group People's figure (or that it is still to come), never an entry of theirs
                out["kpis"].append({"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]), "theirs": "",
                                    "figure": _gh_shared_fig(l, "en") or "Waiting for Group People",
                                    "reason": "Shared unit result, filled by Group People"})
                continue
            eff = l["lm_pct"] if l["lm_pct"] is not None else l["staff_pct"]
            out["kpis"].append({"name": l["kpi_name"], "weight": _gh_pct_str(l["weight"]),
                                "theirs": _gh_pct_str(l["staff_pct"]) if l["staff_pct"] is not None else "",
                                "figure": ("%s%%" % _gh_pct_str(eff)) if eff is not None else (str(l["lm_rating"]) if l["lm_rating"] else ""),
                                "reason": (l["lm_reason"] or "") if l["lm_pct"] is not None else ""})
    ans = {(r["lp"], r["stmt"]): r["answer"] for r in db.execute(
        "SELECT lp, stmt, answer FROM gradeh_lp_answers WHERE cycle_id=? AND person_id=?", (cid, pid))}
    pts_ = gradeh_points(cid)   # a statement's number is what a Yes earns in this cycle (Points per answer), not its fixed weight
    for lp in GRADEH_LP:
        out["lps"].append({"n": lp["n"], "title": lp["short"][0],
                           "st": [{"n": s_["n"], "w": _gh_pct_str(gradeh_statement_yes_points(s_, pts_)), "text": s_["text"][0] if isinstance(s_["text"], (tuple, list)) else s_["text"],
                                   "yes": ans.get((lp["n"], s_["n"])) == "yes"} for s_ in lp["statements"]]})
    if a:
        out["b"] = {"ach": a["b_achievements"] or "", "str": a["b_strengths"] or "", "dev": a["b_development"] or "",
                    "conv": bool(a["conversation_held"])}
        out["promo"] = {"yes": a["promo_nominate"] == "yes", "reason": a["promo_reason"] or ""}
    for m in ([] if gradeh_is_disagreed(prow) else db.execute(   # a person who does not agree is not calibrated: no HOD / BU CEO move is theirs to show
            "SELECT m.*, uu.full_name AS by_name FROM gradeh_band_moves m LEFT JOIN users uu ON uu.id=m.by_user_id "
            "WHERE m.cycle_id=? AND m.person_id=? AND m.stage IN ('hod','buceo') ORDER BY m.id", (cid, pid))):
        out["moves"].append({"stage": m["stage"], "axis": m["axis"], "band": m["band"], "came_in": m["came_in"], "remark": m["remark"],
                             "by": (m["by_name"] or ""), "when": _gh_cal_when(m["created_at"])})
    return out


def gradeh_unit_view(db, u, cid, unit=None, view="grid", box=None, dept=None, q="", pid=None, tab="sum", moved=False):
    """Everything the BU CEO's page draws (C2 the box, C2b one person), read-only."""
    units = gradeh_buceo_units(db, u)
    seat = next((s_ for s_ in units if s_[1] == unit), units[0])
    bg, co = seat
    rows = gradeh_unit_scope(db, cid, bg, co)
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    P = [_gh_cal_person(r, mv, rv, ys) for r in rows]
    names = _gh_hod_names(db, P)
    sub = P   # everyone in the unit: the BU CEO never waits for an HOD or a line manager (no input shows the default band)
    cal = [p for p in P if not p["disagree"]]   # the curves count only the people who are calibrated (the box counts everyone)
    n_dis = len(P) - len(cal)
    n_lm = sum(1 for p in P if p["submitted"])
    state = gradeh_unit_signoff_state(db, cid, co)
    hod_open = {h["id"] for h in state["hods"] if not h["done"]}

    def hod_open_for(p):   # information only: this person's HOD has not signed off both stages (not for a person who does not agree)
        return bool(((p["hod_id"] and p["hod_id"] in hod_open) or (p["hod2_id"] and p["hod2_id"] in hod_open)) and not p["disagree"])
    depts = {}
    for p in sub:
        d_ = depts.setdefault(p["dept"] or "No department", {"name": p["dept"] or "No department", "n": 0, "hod_open": False})
        d_["n"] += 1
        d_["hod_open"] = d_["hod_open"] or hod_open_for(p)
    dept_list = sorted(depts.values(), key=lambda x: x["name"].lower())
    if dept and dept not in depts:
        dept = None
    fp = [p for p in sub if not dept or (p["dept"] or "No department") == dept]
    lock = _gh_cal_lock_text(db, cid, co)
    gate = None if lock else gradeh_bu_gate(db, cid, bg, co)   # why the sign-off is not open for this unit yet (the calendar, or the early rule)

    def item(p):
        mvb, mvh = p["bu_moved"], p["hod_moved"]
        by = "you" if (mvb["perf"] or mvb["pot"]) else "HOD" if (mvh["perf"] or mvh["pot"]) else ""
        perf, pot = p["b_bu"]["perf"], p["b_bu"]["pot"]
        return {"dis": p["disagree"], "dis_on": p["disagree_on"], "id": p["id"], "name": p["name"], "title": p["title"], "dept": p["dept"], "route": p["route"], "perf": perf, "pot": pot,
                "perf_t": _gh_cal_band_text(perf, "perf"), "label": gradeh_calib_label(perf, pot),
                "moved_by": by, "hod_open": hod_open_for(p), "nolm": not p["submitted"], "shared_wait": p["shared_wait"], "late": p["late_text"],
                # a person with two HODs (2026-11-03, canvas H3): each HOD's call and share, as it stands and whether they have signed
                "hods": [{"id": h["id"], "name": names.get(h["id"], "HOD"), "share": h["share"],
                          "perf": _gh_cal_band_text(h["perf"]["band"], "perf"), "pot": h["pot"]["band"] or "",
                          "perf_signed": h["perf"]["signed"], "pot_signed": h["pot"]["signed"]} for h in p["hods"]] if p["shared"] else [],
                "initials": _gh_cal_initials(p["name"]),
                "self": p["uid"] == u["id"], "hod_perf": _gh_cal_band_text(p["b_hod"]["perf"], "perf"), "hod_pot": p["b_hod"]["pot"] or "",
                "lm_perf": _gh_cal_band_text(p["lm"]["perf"], "perf"), "lm_pot": p["lm"]["pot"] or "",
                "fig": _gh_cal_fig(p), "ack": "Disagrees" if p["disagree"] else {"yes": "Yes", "person": "In person", "deemed": "Deemed"}.get(p["ack"], "–"),
                "col": next((c[0] for c in GRADEH_CAL_COLS if perf in c[2]), None)}
    items = [item(p) for p in fp]
    placed = [i for i in items if i["col"] and i["pot"]]
    total = len(placed)
    cells = []
    for pot in GRADEH_CAL_ROWS:
        for ckey, clabel, bands in GRADEH_CAL_COLS:
            ppl = [i for i in placed if i["col"] == ckey and i["pot"] == pot]
            cells.append({"key": "%s|%s" % (ckey, pot), "col": ckey, "col_label": clabel, "bands": bands, "pot": pot,
                          "label": gradeh_cell_label(ckey, pot), "n": len(ppl), "pct": int(round(len(ppl) * 100.0 / total)) if total else 0,
                          "moved": sum(1 for i in ppl if i["moved_by"] == "you"), "faces": [i["initials"] for i in ppl[:4]],
                          "more": max(0, len(ppl) - 4), "people": ppl})
    rowh = [{"pot": pot, "n": sum(c["n"] for c in cells if c["pot"] == pot),
             "pct": int(round(sum(c["n"] for c in cells if c["pot"] == pot) * 100.0 / total)) if total else 0} for pot in GRADEH_CAL_ROWS]
    colf = [{"key": ck, "label": cl, "bands": bs, "n": sum(c["n"] for c in cells if c["col"] == ck),
             "pct": int(round(sum(c["n"] for c in cells if c["col"] == ck) * 100.0 / total)) if total else 0}
            for ck, cl, bs in GRADEH_CAL_COLS]
    keys = [c["key"] for c in cells]
    pitem = next((i for i in items if i["id"] == pid), None) if pid else None
    sel = box if box in keys else None
    if pitem and pitem["col"] and pitem["pot"]:   # a person's page folds the box THEY are in now (a move changes it)
        sel = "%s|%s" % (pitem["col"], pitem["pot"])
    if not sel:
        sel = next((c["key"] for c in cells if c["n"]), keys[0])
    selc = next(c for c in cells if c["key"] == sel)
    n_moved = sum(1 for p in sub if p["bu_moved"]["perf"] or p["bu_moved"]["pot"])
    qn = (q or "").strip().lower()
    drawer = [i for i in selc["people"] if not qn or qn in (i["name"] + " " + i["title"] + " " + i["dept"]).lower()]
    listing = [i for i in items if (not moved or i["moved_by"] == "you") and (not qn or qn in (i["name"] + " " + i["title"] + " " + i["dept"]).lower())]
    curves = {ax: gradeh_calib_curve(db, cid, ax, [p["b_bu"][ax] for p in cal], bg, co) for ax in ("perf", "pot")}
    off = [(ax, cv) for ax, cv in curves.items() if cv["breaches"]]
    off_text = ""
    if off:
        ax, cv = off[0]
        b = cv["off"][0]
        g_ = cv["gaps"][b]
        off_text = "%s: %s has %d %s than the %s curve expects. Sign-off will ask you for a reason." % (
            "Potential" if ax == "pot" else "Performance", cv["labels"][b], abs(g_), "more" if g_ < 0 else "fewer", cv["name"] if ax == "perf" else "potential")
    curve_line = ""   # the box counts everyone; the curves leave out who does not agree, and this line says so
    if n_dis:
        curve_line = "%s: %d on the curve, %d not calibrated (%s)." % (
            ("Potential" if off[0][0] == "pot" else "Performance") if off else "Both curves", len(cal), n_dis,
            "does not agree" if n_dis == 1 else "do not agree")
        if off:
            curve_line += " " + off_text.split(": ", 1)[1]
    person = None
    if pitem:
        prow = next(r for r in rows if r["id"] == pitem["id"])
        person = {"item": pitem, "detail": gradeh_buceo_person_detail(db, cid, prow), "tab": tab if tab in ("sum", "perf", "pot", "comments") else "sum",
                  "box": sel, "can_move": (not lock) and (not gate) and not pitem["self"] and not pitem["dis"]}
        order = [i["id"] for i in selc["people"]] or [pitem["id"]]
        ix = order.index(pitem["id"]) if pitem["id"] in order else 0
        person["pager"] = {"i": ix + 1, "n": len(order), "prev": order[ix - 1] if ix > 0 else None,
                           "next": order[ix + 1] if ix + 1 < len(order) else None}
        person["box_label"] = selc["label"]
        person["why_locked"] = lock or (gate[0].lower() + gate[1:].rstrip(".") if gate else "") or ("this is your own record" if pitem["self"] else "")
        person["dis_note"] = ("%s does not agree with their result, and Group People are handling it. Their result is not calibrated: "
                              "the line manager's rating stays unless Group People change it after their talk." % pitem["name"]) if pitem["dis"] else ""
    fit_on = bool(P) and not lock and not gate and not state["signed"] and leader_learn_can(u, GRADEH_FIT_BU_ABILITY, db)   # only while the sign-off is open
    return {"fit_on": fit_on, "units": [{"bg": b_, "company": c_, "name": proper_name(c_)} for b_, c_ in units], "unit": co, "unit_name": proper_name(co),
            "bg": bg, "view": "list" if view == "list" else "grid", "cells": cells, "rowh": rowh, "colf": colf, "sel": sel, "selc": selc,
            "total": total, "n_sub": n_lm, "n_all": len(P), "depts": dept_list, "dept": dept, "q": q or "", "drawer": drawer,
            "listing": listing, "moved_only": bool(moved), "n_moved": n_moved, "state": state, "lock": lock, "gate": gate, "off_text": off_text,
            "reason_needed": bool(off), "curves": curves, "curve_line": curve_line, "n_dis": n_dis, "person": person, "super_stars": sum(c["n"] for c in cells if c["label"] == "Super Star"),
            "pip": sum(c["n"] for c in cells if c["label"] == TALENT_PIP),
            "signed_on": _gh_cal_when(state["signed_at"]) if state["signed_at"] else "",
            "signoff_note": _gh_unit_signoff_note(state),
            "default_text": "%s / %s" % (GRADEH_DEFAULT_BAND["perf"], GRADEH_DEFAULT_BAND["pot"])}


def _gh_unit_signoff_note(state):
    """The words the BU CEO's sign-off confirm box adds when HODs of the unit have not signed off both stages ("" when all have):
    the sign-off never waits for them, it makes everyone's band as it stands final for the unit."""
    names = state["blocking"]
    if not names:
        return ""
    return "%d %s signed off (%s). Signing off now makes everyone's band as it stands final for this unit." % (
        len(names), "HOD hasn't" if len(names) == 1 else "HODs haven't", ", ".join(names))


# ---- AI+ fit to curve (Chris, 2 Nov 2026; canvas "AI fit to curve 2026-11-02") ------------------------------------------------------
# On the HOD's stage page and the BU CEO's Talent Box: "Fit the curve with AI" suggests the fewest one-band moves that bring each band
# within the expected spread, a case for each person made only of what Grade H holds, and nothing changes until the leader applies. A FIXED
# RULE like the main review's fit (_calib_fit_greedy; no model, nothing leaves OneHR). Who moves is ranked by where the person sits in
# their band: going down the one nearest the band's lower line, going up the one nearest its upper line; someone already moved off
# their line manager's band by a lower tier goes back first. Never suggested: the leader themselves, a person with no line manager input
# (they stay at the default band and still count on the curve), a person the leader already moved on this axis. Every move is written
# by the SAME writer a manual move uses (gradeh_hod_move / gradeh_buceo_move), with the leader's own remark (never written by the
# server: the suggestion is placeholder text in the browser only), one commit per move, one summary audit row per batch.
GRADEH_FIT_HOD_ABILITY = "hod.gradeh_fit"
GRADEH_FIT_BU_ABILITY = "bu.gradeh_fit"
# the % bands of a KPI scale (rating 1..5 = below the first, ..., above the last); gradeh_kpi_rating holds the same numbers
GRADEH_FIT_PCT_CUTS = {"FIAMMA": (60, 80, 100, 120), "SIGNATURE": (80, 95, 110, 130)}
GRADEH_FIT_MAX_MOVES = 200
_GH_FIT_AXIS_NAME = {"pot": "Potential", "perf": "Performance"}


def _gh_fit_num(x):
    """13.5 -> '13.5', 15.0 -> '15', 3.875 -> '3.88'."""
    return ("%.2f" % float(x)).rstrip("0").rstrip(".")


def _gh_fit_measure(axis, band, p, scale, cid):
    """Where one person sits in `band`: {kind, value, lo, hi, pos}, or None when the figure that places them is missing. kind 'pot' (score
    out of the cycle's most, 17.5 on the default points, against the settable cut-offs), 'kpi' (Route A on a % scale: the weighted % against the scale's rating bands) or 'avg' (the
    line manager's average against the performance cut-offs). pos is 0 (at the band's lower line) to 1 (at its upper), clamped."""
    if axis == "pot":
        cuts = [float(x) for x in gradeh_setting("gradeh_pot_cuts", cid)]
        edges = [0.0] + cuts + [gradeh_lp_max(cid)]   # the cycle's own most
        i = GRADEH_POT_BANDS.index(band)
        kind, v = "pot", p["pot_score"]
    else:
        i = GRADEH_PERF_BANDS.index(band)
        if p["perf_value"] is not None and scale in GRADEH_FIT_PCT_CUTS:
            c = [float(x) for x in GRADEH_FIT_PCT_CUTS[scale]]
            edges, kind, v = [0.0] + c + [c[3] + 20.0], "kpi", p["perf_value"]
        else:
            edges = [1.0] + [float(x) for x in gradeh_setting("gradeh_perf_cuts", cid)] + [5.0]
            kind, v = "avg", p["perf_rating"]
    if v is None:
        return None
    lo, hi, v = edges[i], edges[i + 1], float(v)
    return {"kind": kind, "value": v, "lo": lo, "hi": hi, "hi_max": edges[-1],   # hi_max: a potential score's most in this cycle (Points per answer)
            "pos": max(0.0, min(1.0, (v - lo) / (hi - lo))) if hi > lo else 0.5}


def _gh_fit_extras(db, cid, ids):
    """({person id: KPI scale}, {person id: [attribute ratings]}) in batched reads."""
    scales, attrs = {}, {}
    for ch in _gh_cal_chunks(ids):
        ph = ",".join("?" * len(ch))
        for r in db.execute("SELECT person_id, MIN(group_scale) AS s FROM gradeh_kpi_lines WHERE cycle_id=? AND person_id IN (%s) "
                            "GROUP BY person_id" % ph, [cid] + ch):
            scales[r["person_id"]] = r["s"]
        for r in db.execute("SELECT person_id, rating FROM gradeh_ratings WHERE cycle_id=? AND person_id IN (%s) ORDER BY id" % ph,
                            [cid] + ch):
            attrs.setdefault(r["person_id"], []).append(r["rating"])
    return scales, attrs


def _gh_fit_line(axis, band, direction, p, m, attrs):
    """The case in one short line, from what Grade H holds (canvas 5) -> (figure parts, distance to the band line)."""
    order = GRADEH_POT_BANDS if axis == "pot" else GRADEH_PERF_BANDS
    line_band = band if direction == "down" else order[order.index(band) + 1]
    line_v = m["lo"] if direction == "down" else m["hi"]
    d = (m["value"] - line_v) if direction == "down" else (line_v - m["value"])
    word = "above" if (direction == "down") == (d >= 0) else "below"
    if m["kind"] == "pot":
        parts = ["%s of %s" % (_gh_fit_num(m["value"]), _gh_fit_num(m["hi_max"]))]
        if p["yes"]:
            parts.append("%d of 14 Yes" % p["yes"][0])
        gap = "%s %s the %s line (%s)" % (_gh_fit_num(abs(d)), word, line_band, _gh_fit_num(line_v))
    elif m["kind"] == "kpi":
        parts = ["KPI %s%% (rating %d)" % (_gh_fit_num(m["value"]), int(round(float(p["perf_rating"] or 0))))]
        gap = "%s point%s %s the %s%% line" % (_gh_fit_num(abs(d)), "" if abs(d) == 1 else "s", word, _gh_fit_num(line_v))
    else:
        parts = ["Line manager's average %s" % _gh_fit_num(m["value"])]
        if attrs:
            parts.append("%d attributes, lowest %d" % (len(attrs), min(attrs)))
        gap = "%s %s the %s line" % (_gh_fit_num(abs(d)), word, _gh_fit_num(line_v))
    return parts, gap


def _gh_fit_figure(m):
    """A person's figure as short text, for the nearest-the-line list."""
    return ("%s%%" % _gh_fit_num(m["value"])) if m["kind"] == "kpi" else _gh_fit_num(m["value"])


def _gh_fit_moves(db, cid, rows, kind, axis, uid, bg, co):
    """The fit's suggestion for one axis, write-free: {moves, order, before, after, expected, total, within_after, state, message, note,
    held_n, mine_n}. `rows` come from gradeh_hod_scope / gradeh_unit_scope only (never a hod_id query of our own), so the people are
    exactly the ones the page shows. kind 'hod' reads and moves the HOD's band (b_hod); 'bu' the BU CEO's (b_bu)."""
    key, mkey = ("b_hod", "hod_moved") if kind == "hod" else ("b_bu", "bu_moved")
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    # a person who does not agree is not calibrated (the pages' own reader: _gh_cal_person's "disagree"): never proposed, never moved, and
    # not counted in the curve's totals, exactly as the pages leave them off the curve
    ALLP = [_gh_cal_person(r, mv, rv, ys, as_hod=(uid if kind == "hod" else None)) for r in rows]
    P = [p for p in ALLP if not p["disagree"]]
    n_dis = len(ALLP) - len(P)             # the same count the pages' own line gives (_gh_dis_line): said in the fit's notes too
    order, target, cname = _gh_cal_curve_target(db, cid, axis, bg, co)
    order = list(order)
    counts = {b: 0 for b in order}
    for p in P:
        counts[p[key][axis]] += 1
    total = sum(counts.values())
    expected = {b: (int(round(target[b] / 100.0 * total)) if total else 0) for b in order}
    scales, attrs = _gh_fit_extras(db, cid, [p["id"] for p in P])
    eids = {r["id"]: (r["employee_id"] or "") for r in rows}
    people, held, mine = {}, 0, 0
    for p in P:
        if p["uid"] == uid:
            continue                       # nobody sets their own band (the writers refuse it as well)
        if not p["submitted"]:
            held += 1                      # no line manager input: stays at the default band, still counted on the curve
            continue
        if p[mkey][axis]:
            mine += 1                      # the leader's own decision on this axis is never overridden
            continue
        band = p[key][axis]
        m = _gh_fit_measure(axis, band, p, scales.get(p["id"]), cid)
        if m is None:
            held += 1
            continue
        lmb = p["lm"][axis]
        off = (order.index(band) - order.index(lmb)) if lmb in order else 0
        # "name" is the greedy's last sort key: the Employee ID, so equal cases are ordered by Employee ID
        people[p["id"]] = {"id": p["id"], "name": eids.get(p["id"]) or str(p["id"]).zfill(9), "full": p["name"], "band": band,
                           "start": band, "score": m["pos"], "m": m, "off": off, "p": p, "lm": lmb}
    c0 = dict(counts)
    after = dict(counts)

    def case_fn(pp, band):
        inb = [q for q in pp if q["band"] == band]
        for q in inb:
            q["case"] = q["score"] - 1.0 * q["off"]
        return inb

    def gaps_fn(c):
        n = sum(c.values())
        return {b: (int(round(target[b] / 100.0 * n)) if n else 0) - c[b] for b in order}

    raw, br_after = _calib_fit_greedy(order, after, list(people.values()), gaps_fn, case_fn, lambda q, d, src, peers: None, len(P))
    out = []
    for mvx in raw:
        q = people[mvx["id"]]
        frm, to = mvx["from"], mvx["to"]
        direction = "up" if order.index(to) > order.index(frm) else "down"
        parts, gap = _gh_fit_line(axis, frm, direction, q["p"], q["m"], attrs.get(q["id"]))
        mine_case = q["score"] - 1.0 * q["off"]
        sib = [x for x in people.values() if x["start"] == frm]
        ranked = sorted(sib, key=lambda x: ((x["score"] - 1.0 * x["off"]) * (1 if direction == "down" else -1), x["name"]))
        near = ["%s (%s)" % (x["full"], _gh_fit_figure(x["m"])) for x in ranked[:4]]
        ties = [x for x in sib if x is not q and abs((x["score"] - 1.0 * x["off"]) - mine_case) < 1e-9]
        pp = q["p"]
        why = ["Line manager's band: %s. %s." % (q["lm"] or "not set", ", ".join(parts[:2] if q["m"]["kind"] == "pot" else parts))]
        why.append("%s in %s: %s." % ("Lowest" if direction == "down" else "Highest", frm, ", then ".join(near)))
        why.append("%s has %d %s and the curve expects %d; %s has %d and expects %d. The ones nearest the line move first." % (
            frm, c0[frm], "person" if c0[frm] == 1 else "people", expected[frm], to, c0[to], expected[to]))
        if ties:
            why.append("Tied with %s; ordered by Employee ID." % ", ".join(x["full"] for x in ties[:3]))
        if kind == "bu" and pp["hod_moved"][axis]:
            why.append("Your HOD moved this person to %s (the line manager had %s)." % (pp["hod_moved"][axis]["band"], q["lm"] or "no band"))
        elif q["off"]:
            why.append("Their band here (%s) is not the line manager's (%s)." % (frm, q["lm"]))
        if axis == "pot" and pp["perf_rating"] is not None:
            why.append("For context, not used to choose: performance %s (%s)." % (
                GRADEH_BAND_NAMES.get(pp["lm"]["perf"], pp["lm"]["perf"] or "no band"),
                ("KPI %s%%" % _gh_fit_num(pp["perf_value"])) if pp["perf_value"] is not None else "average %s" % _gh_fit_num(pp["perf_rating"])))
        elif axis == "perf" and pp["pot_score"] is not None:
            why.append("For context, not used to choose: potential %s of %s (%s)." % (
                _gh_fit_num(pp["pot_score"]), _gh_fit_num(gradeh_lp_max(cid)), pp["lm"]["pot"] or "no band"))
        out.append({"id": q["id"], "name": q["full"], "from": frm, "to": to, "dir": direction, "line": " · ".join(parts + [gap]),
                    "why": why, "ph": "Moved to %s to fit the expected spread: %s, %s." % (to, parts[0], gap)})
    within = not br_after
    n = len(out)
    if out:
        state = "ok"
        msg = ("%d move%s bring%s every band within the expected spread." % (n, "" if n == 1 else "s", "s" if n == 1 else "")
               if within else "These moves bring it closer; the rest needs your judgement.")
    elif within:
        state, msg = "empty", "Your curve is already within the expected spread. No moves suggested."
    else:
        state, msg = "stuck", "AI+ can't bring this within the expected spread by moving the people it may move. The rest needs your judgement."
    notes = []
    if held:
        notes.append("%d %s no line manager input. AI+ leaves them where they are; they still count on the curve." % (
            held, "person has" if held == 1 else "people have"))
    if mine:
        notes.append("%d %s you already moved stay as you set them." % (mine, "person" if mine == 1 else "people"))
    if n_dis:
        notes.append("%d %s with their result %s not in this fit: they keep their line manager's rating." % (
            n_dis, "person who does not agree" if n_dis == 1 else "people who do not agree", "is" if n_dis == 1 else "are"))
    return {"moves": out, "order": order, "before": c0, "after": after, "expected": expected, "total": total, "within_after": within,
            "state": state, "message": msg, "note": " ".join(notes), "held_n": held, "mine_n": mine, "dis_n": n_dis, "curve": cname,
            "axis_name": _GH_FIT_AXIS_NAME[axis]}


def _gh_fit_setup(kind):
    """(context, None) for a fit POST, or (None, (json, status)): the seat, the fit's own ability, then every gate the writers hold, so a
    closed, signed-off, locked or not-yet-open stage gives no suggestion and writes nothing."""
    db, u, cid = _gh_cal_ctx(kind)
    ab = GRADEH_FIT_HOD_ABILITY if kind == "hod" else GRADEH_FIT_BU_ABILITY
    if not leader_learn_can(u, ab, db):
        return None, (jsonify(ok=False, error=leader_learn_off(u, ab, db)), 403)
    f = request.form
    if kind == "hod":
        stage = f.get("stage") or ""
        if stage not in GRADEH_CAL_STAGES:
            return None, (jsonify(ok=False, error="That is not a stage."), 400)
        rows = gradeh_hod_scope(db, u["id"], cid)
        if not rows:
            return None, (jsonify(ok=False, error="You have no Grade H people in your department."), 409)
        for co in sorted({r["company"] for r in rows}):
            gate = _gh_cal_hod_stage_gate(db, cid, u["id"], co, stage)
            if gate:
                return None, (jsonify(ok=False, error=gate), 409)
        return {"db": db, "u": u, "cid": cid, "kind": kind, "axis": GRADEH_CAL_AXIS[stage], "stage": stage, "rows": rows,
                "bg": rows[0]["business_group"], "co": rows[0]["company"]}, None
    axis = f.get("axis") or ""
    if axis not in GRADEH_AXES:
        return None, (jsonify(ok=False, error="That is not an axis."), 400)
    seat = next(((bg, co) for bg, co in gradeh_buceo_units(db, u) if co == (f.get("unit") or "")), None)
    if not seat:
        return None, (jsonify(ok=False, error="That isn't your unit."), 404)
    gate = _gh_cal_lock_text(db, cid, seat[1]) or gradeh_bu_gate(db, cid, seat[0], seat[1])
    if gate:
        return None, (jsonify(ok=False, error=gate), 409)
    rows = gradeh_unit_scope(db, cid, seat[0], seat[1])
    if not rows:
        return None, (jsonify(ok=False, error="Nobody is on the Grade H list for this unit."), 409)
    return {"db": db, "u": u, "cid": cid, "kind": kind, "axis": axis, "stage": None, "rows": rows, "bg": seat[0], "co": seat[1]}, None


def _gh_fit_apply(cx, wanted):
    """Write the moves the leader saw, each through the same writer a manual move uses, with the leader's own remark -> (applied, skipped).
    One commit per move: gradeh_buceo_move rolls the transaction back when gradeh_record_move refuses (a remark the screen refuses), which
    would otherwise throw away the moves made before it. A move whose person has changed since (band, a move of the leader's own, no
    line manager input, not theirs) is skipped with the reason; the rest are kept."""
    db, u, cid, kind, axis = cx["db"], cx["u"], cx["cid"], cx["kind"], cx["axis"]
    key, mkey = ("b_hod", "hod_moved") if kind == "hod" else ("b_bu", "bu_moved")
    scope = {r["id"]: r for r in cx["rows"]}
    applied, skipped = [], []
    for m in (wanted if isinstance(wanted, list) else [])[:GRADEH_FIT_MAX_MOVES]:
        try:
            pid, frm, to = int(m.get("id")), str(m.get("from") or ""), str(m.get("to") or "")
            remark = m.get("remark")
        except (TypeError, ValueError, AttributeError):
            continue
        why = None
        row = scope.get(pid)
        if not row:
            why = "That person isn't in your scope."
        else:
            mv, rv, ys = _gh_cal_load(db, cid, [row])
            p = _gh_cal_person(row, mv, rv, ys, as_hod=(u["id"] if kind == "hod" else None))
            if p["uid"] == u["id"]:
                why = _calib_self_msg("hod" if kind == "hod" else "buceo")
            elif p["disagree"]:
                why = GH_DISAGREE_CAL_MSG
            elif not p["submitted"]:
                why = "Their line manager has not submitted: AI+ leaves them where they are."
            elif p[mkey][axis]:
                why = "You have already moved them."
            elif p[key][axis] != frm:
                why = "Their band has changed since the suggestion."
            elif to == frm or not gradeh_band_valid(axis, to):
                why = "That is not a band this stage can set."
        if not why:
            if kind == "hod":
                ok, msg = gradeh_hod_move(db, u, pid, cx["stage"], to, remark)
            else:
                ok, msg = gradeh_buceo_move(db, u, pid, to if axis == "perf" else None, to if axis == "pot" else None, remark)
            if ok:
                db.commit()
                applied.append(pid)
                continue
            db.rollback()
            why = msg
        skipped.append({"id": pid, "name": (row["full_name"] if row else ""), "why": why})
    _gh_cal_audit(db, u, "gradeh_fit_apply", "%s %s: %d applied, %d skipped" % (
        "HOD" if kind == "hod" else "BU CEO", axis, len(applied), len(skipped)))
    db.commit()
    return applied, skipped


# ---- the routes ------------------------------------------------------------------------------------------------------------
def _gh_cal_ctx(kind):
    """(db, user, cycle id) for a calibration route, or a 404: the module is not running, or an account without that seat."""
    db = get_db()
    u = current_user()
    cid = gradeh_calib_cycle_id(db)
    if not cid or not u:
        abort(404)
    if kind == "hod" and not gradeh_hod_can(db, u):
        abort(404)
    if kind == "unit" and not gradeh_buceo_units(db, u):
        abort(404)
    return db, u, cid


def _gh_cal_topbar(db, u, kind, v):
    """The Grade H pages' top row, the journey's own (2026-10-30; canvas 42gRB6b3xwPm7YHSH3BQWK): the view tray (Mine | Dept, or
    Mine | BU, from the journey's own views), the leaders' tab (DR for an HOD, CAL for a BU CEO; ticked when that part is done) and the
    Grade H tab with its stages as steps. None when the journey's view is not theirs, so the page then simply has no row."""
    try:
        view = "dept" if kind == "hod" else "bu"
        keys = _journey_views(db, u)
        if view not in keys:
            return None
        views = [{"key": x, "short": _view_short(db, u, x), "title": _view_title(db, u, x), "off": _view_not_open(db, u, x)}
                 for x in keys]
        live = _journey_team_live_stages(review_state(db, u), view)
        steps = []
        if kind == "hod":
            S = v["summary"]
            for i, (stg, lbl) in enumerate((("pot", "Potential"), ("perf", "Performance")), 1):
                reach = stg == "pot" or S["pot"]["signed"]
                steps.append({"n": i, "label": lbl, "done": S[stg]["signed"], "href": url_for("calib_gradeh_hod", stage=stg) if reach else None,
                              "now": v["stage"] == stg,
                              "tip": "Grade H %s: %s" % (lbl.lower(), "signed off" if S[stg]["signed"] else
                                                         "%d of %d reviewed" % (S[stg]["reviewed"], S[stg]["n"]) if reach else
                                                         "opens when you have signed off potential")})
        else:
            signed = v["state"]["signed"]
            steps.append({"n": 1, "label": "Talent Box", "done": signed, "href": url_for("calib_gradeh_unit", unit=v["unit"]), "now": True,
                          "tip": "Grade H Talent Box: " + ("signed off" if signed else "%d of %d departments signed off by their HOD" % (
                              v["state"]["hods_signed"], v["state"]["hods_total"]))})
        cur = next((x for x in steps if not x["done"]), None)
        for x in steps:
            x["state"] = "done" if x["done"] else ("cur" if x is cur else "todo")
        return {"views": views, "view": view, "steps": steps,
                "leaders": {"code": "DR" if kind == "hod" else "CAL", "icon": "clipboard-check" if kind == "hod" else "sliders",
                            "full": "Department Review" if kind == "hod" else "Calibration",
                            "done": bool(live) and all(x["state"] == REVIEW_STATE_DONE for x in live),
                            "url": url_for("review_journey", view=view)}}
    except Exception:   # the row never breaks the page it sits on
        return None


def _gh_cal_render(db, u, cid, kind, v):
    cyc = active_cycle(db)
    return render_template("gradeh_calib.html", kind=kind, v=v, cyc_name=(cyc["name"] if cyc else ""),
                           has_hod=gradeh_hod_can(db, u), has_unit=bool(gradeh_buceo_units(db, u)),
                           leaders_url=url_for("review_journey", view="dept" if kind == "hod" else "bu"),
                           top=_gh_cal_topbar(db, u, kind, v))


def _gh_cal_done(ok, msg):
    flash(msg, "ok" if ok else "error")


