def _gh_fit_route(kind):
    """The fit's one POST for each seat: mode=preview (default; write-free) lists the moves and why, mode=apply writes the moves the
    leader saw. CSRF is checked by the app's before_request, the seat by _gh_cal_ctx, the ability and every gate by _gh_fit_setup."""
    cx, err = _gh_fit_setup(kind)
    if err:
        return err
    db = cx["db"]
    if (request.form.get("mode") or "preview") != "apply":
        r = _gh_fit_moves(db, cx["cid"], cx["rows"], kind, cx["axis"], cx["u"]["id"], cx["bg"], cx["co"])
        r["scope"] = ("your department, %d people" % len(cx["rows"])) if kind == "hod" else "%s, %d people" % (
            proper_name(cx["co"]), len(cx["rows"]))
        return jsonify(ok=True, **r)
    try:
        wanted = json.loads(request.form.get("moves") or "[]")
    except ValueError:
        return jsonify(ok=False, error="Which moves?"), 400
    applied, skipped = _gh_fit_apply(cx, wanted)
    axis_name = _GH_FIT_AXIS_NAME[cx["axis"]].lower()
    if applied:
        msg = "%d move%s applied to Grade H %s, each with your remark. Check the curve, then %s." % (
            len(applied), "" if len(applied) == 1 else "s", axis_name,
            "sign off when everyone is reviewed" if kind == "hod" else "sign off when you are ready")
        if skipped:
            msg += " %d skipped (%s)." % (len(skipped), "; ".join("%s: %s" % (x["name"], x["why"]) for x in skipped[:3]))
        flash(msg, "ok")
    return jsonify(ok=True, applied=len(applied), skipped=skipped)


