def _gh_door_badge(n):
    """The number on the Grade H tab: "" for none, the count, "99+" from 100 (the 20px pill holds three characters)."""
    n = int(n or 0)
    return "" if n <= 0 else ("99+" if n >= 100 else str(n))


def _gradeh_cal_door(kind=None):
    """The door to Grade H calibration, for an HOD or a BU CEO of Grade H people, else None: {n_open, done, badge, label, url, kind,
    title}. kind "hod" / "unit" asks for that seat's door only (the journey's Dept / BU view); None is the first seat they hold.
    n_open is the people still to review: for an HOD the open stage's people (submitted or not) they have not yet agreed or moved;
    for a BU CEO the people in their units, not yet signed off (never their own record), because the BU CEO's one sign-off is the
    only thing that closes them and waits for no HOD or line manager. done is every stage signed off (the HOD's two, every unit of a BU CEO)."""
    if not gradeh_on() or not session.get("user_id"):
        return None
    try:
        db = get_db()
        u = current_user()
        out = None
        if kind in (None, "hod") and gradeh_hod_can(db, u):
            cid = gradeh_calib_cycle_id(db)
            st = gradeh_hod_state(db, cid, u["id"])
            stage = "perf" if st["pot"] else "pot"
            done = bool(st["pot"] and st["perf"])
            n = 0
            if not done:
                rows = gradeh_hod_scope(db, u["id"], cid)
                mv, rv, ys = _gh_cal_load(db, cid, rows)
                n = sum(1 for p in (_gh_cal_person(r, mv, rv, ys, as_hod=u["id"]) for r in rows)
                        if not p["disagree"] and not p["hod_done"][GRADEH_CAL_AXIS[stage]])
            out = {"n_open": n, "done": done, "url": url_for("calib_gradeh_hod"), "kind": "hod"}
        elif kind in (None, "unit"):
            units = gradeh_buceo_units(db, u)
            if units:
                cid = gradeh_calib_cycle_id(db)
                n, done = 0, True
                for bg, co in units:
                    state = gradeh_unit_signoff_state(db, cid, co)
                    if state["signed"]:
                        continue
                    done = False
                    n += sum(1 for r in gradeh_unit_scope(db, cid, bg, co) if r["user_id"] != u["id"] and not r["disagree_at"])   # a person who does not agree is not reviewed
                out = {"n_open": n, "done": done, "url": url_for("calib_gradeh_unit"), "kind": "unit"}
        if out:
            out["badge"] = "" if out["done"] else _gh_door_badge(out["n_open"])
            out["label"] = "Grade H calibration"
            out["title"] = ("Grade H calibration: signed off" if out["done"] else
                            "Grade H calibration: %d %s to review" % (out["n_open"], "person" if out["n_open"] == 1 else "people")
                            if out["n_open"] else "Grade H calibration")
        return out
    except Exception:   # a door never breaks the page it sits on
        return None


app.jinja_env.globals["gradeh_cal_door"] = _gradeh_cal_door


def _gh_cal_opener_line(db, u, tier):
    """The one fixed sentence the HOD's Dept view and the BU CEO's BU view add to their opening line when this person has Grade H
    people (2026-10-30): where those people are reviewed. "" for no Grade H people, another tier, or the module off. No model."""
    try:
        if not gradeh_on() or not u:
            return ""
        cid = gradeh_calib_cycle_id(db)
        if not cid:
            return ""
        if tier == "hod" and gradeh_hod_can(db, u):
            n = len(gradeh_hod_scope(db, u["id"], cid))
            return (" Your %d Grade H %s reviewed under Grade H, at the top." % (n, "person is" if n == 1 else "people are")) if n else ""
        if tier == "buceo":
            units = gradeh_buceo_units(db, u)
            n = sum(len(gradeh_unit_scope(db, cid, bg, co)) for bg, co in units)
            return (" Your %d Grade H %s their own box under Grade H, at the top." % (n, "person has" if n == 1 else "people have")) if n else ""
    except Exception:
        return ""
    return ""


# ---------------------------------------------------------------------------------------------------------------------
# Grade H Appraisal, piece 6: the super admin's side (2026-10-28; canvases A1-A5 in OneHR/JG H Appraisal/canvas). Every route
# is under /admin/gradeh (so _gradeh_gate covers it) and is the super admin's alone: @super_required, "super" in
# ADMIN_ACCESS_MAP. People & progress (route, appraiser, where each appraisal is, Reopen), Final bands (LM -> HOD -> BU CEO ->
# final, a super admin's change with a mandatory remark), Settings (deemed deadline, performance bands and curve, potential
# bands and curve), the calendar group (WINDOW_CELLS), and the Release step on Cycle > Release results (by unit, after the BU
# CEO's sign-off) with its Excel. One writer each; none commits except where its docstring says.
# ---------------------------------------------------------------------------------------------------------------------
GRADEH_CELL_HOD_POT = "gradeh_hod_pot"
GRADEH_CELL_HOD_PERF = "gradeh_hod_perf"
GRADEH_CELL_BUCEO = "gradeh_buceo"
GRADEH_ADM_PAGE = 50   # rows a page of People & progress / Final bands

GRADEH_STATUS = (("blocked", "Blocked"), ("not_started", "Not started"), ("kpi_keyed", "KPI keyed"),
                 ("sent", "With the line manager"), ("lm_part", "Line manager part-way"), ("submitted", "Submitted"),
                 ("hod", "With the HOD"), ("bu", "With the BU CEO"), ("signed", "Signed off"), ("released", "Released"))
GRADEH_STATUS_LABEL = dict(GRADEH_STATUS)
# the Stage column's words, short enough to stay on one line at the largest text size (the full words are the cell's title; the Show filter,
# the list panel and the Excel keep the full ones)
GRADEH_STATUS_SHORT = {"blocked": "Blocked", "not_started": "Not started", "kpi_keyed": "KPI keyed", "sent": "With LM", "lm_part": "LM part-way",
                       "submitted": "Submitted", "hod": "With HOD", "bu": "With BU CEO", "signed": "Signed off", "released": "Released"}
GRADEH_ACK_LABEL = {"self": "Acknowledged", "person": "Acknowledged in person", "deemed": "Deemed acknowledged",
                    "wait": "Waiting to acknowledge", "": ""}
GRADEH_BAND_LONG = {"UA": "1 · Unacceptable", "BE": "2 · Below Expectation", "ME": "3 · Meets Expectation",
                    "AE": "4 · Above Expectation", "OU": "5 · Outstanding", "Low": "Low", "Mid": "Mid", "High": "High"}

_GH_ADM_SQL = (
    "SELECT p.id, p.cycle_id, p.employee_id, p.user_id, p.route, p.appraiser_id, p.hr_supervisor_name, p.language, "
    "uu.full_name AS full_name, uu.job_title AS job_title, uu.job_grade AS job_grade, uu.department AS department, "
    "uu.business_group AS business_group, uu.company AS company, " + _GH_HOD_SQL + " AS hod_id, uu.hod_id AS main_hod_id, "
    + _GH_HOD2_SQL + " AS hod2_id, p.hod_split AS hod_split, p.hod2_user_id AS hod2_user_id, "
    "p.hod_user_id AS hod_user_id, uu.manager_id AS manager_id, uu.email AS email, uu.left_at AS left_at, "
    "a.lm_submitted_at, a.staff_submitted_at, a.perf_value, a.perf_rating, a.perf_band, a.pot_score, a.pot_band, "
    "a.acknowledged_at, a.deemed_at, a.ack_in_person, a.ack_in_person_on, a.promo_nominate, a.promo_reason, "
    "a.b_achievements, a.b_strengths, a.b_development, a.reopened_at, a.disagree_at, a.disagree_ticket_id, "
    "ap.full_name AS ap_name, ap.employee_id AS ap_eid, mg.full_name AS mg_name, mg.employee_id AS mg_eid "
    "FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
    "LEFT JOIN gradeh_appraisals a ON a.cycle_id=p.cycle_id AND a.person_id=p.id "
    "LEFT JOIN users ap ON ap.id=p.appraiser_id LEFT JOIN users mg ON mg.id=uu.manager_id "
    "WHERE p.cycle_id=? AND p.private_company=0 ")


def _gh_adm_day(utc_raw):
    """A stored UTC time as the MYT day people read ('12 Nov 2026'), '' for None."""
    d = _gh_myt(utc_raw)
    return "%d %s %d" % (d.day, d.strftime("%b"), d.year) if d else ""


def gradeh_admin_people(db, cid, only=None):
    """Everyone on the Grade H list for this cycle (private-company rows are never on it), with where each appraisal stands, in
    seven batched reads (never a query a person). One dict a person; the pages, the counts, the list panel and the Excel all read
    this, so a count and its list can never disagree. Status, in order: released (the unit's release), signed (the BU CEO signed
    the unit off), bu (the person's HOD signed both stages, or they have no HOD stage), hod (the HOD has agreed or moved a band
    of theirs), submitted (the line manager submitted), blocked (a KPI-route person whose lines are missing or do not total
    100%), lm_part, sent (the KPI figures are with the line manager), kpi_keyed, not_started. The acknowledgement is its own
    column (wait / self / person / deemed; a passed deadline reads as deemed before the staff page records it).
    `only` = one gradeh_people id: the same dict for that one person alone (the admin person page), every read narrowed to them."""
    one_ = (" AND p.id=?", " AND l.person_id=?", " AND person_id=?") if only else ("", "", "")
    ob = (only,) if only else ()
    rows = db.execute(_GH_ADM_SQL + one_[0], (cid,) + ob).fetchall()
    kpi = {r["person_id"]: r for r in db.execute(
        "SELECT l.person_id, COUNT(*) AS n, SUM(l.weight) AS w, SUM(CASE WHEN e.staff_pct IS NOT NULL THEN 1 ELSE 0 END) AS keyed, "
        "SUM(CASE WHEN e.lm_at IS NOT NULL THEN 1 ELSE 0 END) AS checked FROM gradeh_kpi_lines l "
        "LEFT JOIN gradeh_kpi_entries e ON e.line_id=l.id WHERE l.cycle_id=?" + one_[1] + " GROUP BY l.person_id", (cid,) + ob)}
    nrat = {r[0]: r[1] for r in db.execute("SELECT person_id, COUNT(*) FROM gradeh_ratings WHERE cycle_id=?" + one_[2] + " GROUP BY person_id", (cid,) + ob)}
    nlp = {r[0]: r[1] for r in db.execute("SELECT person_id, COUNT(*) FROM gradeh_lp_answers WHERE cycle_id=?" + one_[2] + " GROUP BY person_id", (cid,) + ob)}
    mv, rv, ys = _gh_cal_load(db, cid, rows)
    hod_sign = {}
    for r in db.execute("SELECT scope_key, stage FROM gradeh_signoffs WHERE cycle_id=? AND tier='hod'", (cid,)):
        hod_sign.setdefault(r["scope_key"], set()).add(r["stage"])
    bu_sign = {r["scope_key"]: r for r in db.execute(
        "SELECT * FROM gradeh_signoffs WHERE cycle_id=? AND tier='buceo' AND stage='all'", (cid,))}
    released = {r["unit"]: r for r in db.execute("SELECT * FROM gradeh_releases WHERE cycle_id=?", (cid,))}
    seat_rows = gradeh_unit_seats(db)
    seats = {(r["user_id"], r["company"]) for r in seat_rows}
    unit_seat = {}
    for r_ in seat_rows:
        unit_seat.setdefault((r_["business_group"], r_["company"]), r_)
    hod_of = {r_["id"]: r_ for r_ in _gh_in(db, "SELECT id, full_name, employee_id FROM users WHERE id IN (%s)",
                                            sorted({r_[k_] for r_ in rows for k_ in ("hod_id", "main_hod_id", "hod2_id") if r_[k_]}))}
    now_utc = _utc_now().strftime("%Y-%m-%d %H:%M:%S")
    out = []
    for r in rows:
        cal = _gh_cal_person(r, mv, rv, ys, show_default=False)
        pid, co = r["id"], r["company"] or ""
        sub = bool(r["lm_submitted_at"])
        k = kpi.get(pid)
        slots = _gh_slots(db, r["hod_id"], r["hod2_id"], r["hod_split"], r["user_id"], co, seats)   # the live HODs, a second one too
        hod_stage = bool(slots)
        hd = hod_of.get(slots[0][0]) if hod_stage else None
        hods = []
        calh = {c_["id"]: c_ for c_ in cal["hods"]}   # each HOD's own call, for a person with two
        for h_, sh_ in slots:
            hr_ = hod_of.get(h_)
            hods.append({"id": h_, "name": ((hr_["full_name"] or "").strip() if hr_ else ""), "eid": ((hr_["employee_id"] or "") if hr_ else ""),
                         "share": sh_, "perf": (calh.get(h_) or {}).get("perf"), "pot": (calh.get(h_) or {}).get("pot"),
                         "signed": {st_: st_ in hod_sign.get(str(h_), set()) for st_ in GRADEH_CAL_STAGES}})
        # the Grade H HOD is not the person's OneHR HOD (the Grade H list named one, or the OneHR one has left): say whose it is
        mh = hod_of.get(r["main_hod_id"]) if (hod_stage and r["main_hod_id"] != r["hod_id"]) else None
        bs = unit_seat.get((r["business_group"], r["company"]))
        hod_signed = (not hod_stage) or all({"pot", "perf"} <= hod_sign.get(str(h_), set()) for h_, _sh in slots)
        blocked = ""
        if r["route"] == "A" and not sub:
            if not k or not k["n"]:
                blocked = "No KPI lines yet"
            elif abs((k["w"] or 0) - 100) > 0.01:
                blocked = "KPI weights must total 100%% (now %s%%)" % _gh_pct_str(k["w"])
        if co in released:
            st = "released"
        elif sub and co in bu_sign:
            st = "signed"
        elif sub and hod_signed:
            st = "bu"
        elif sub and any(cal["hod_done"].values()):
            st = "hod"
        elif sub:
            st = "submitted"
        elif blocked:
            st = "blocked"
        elif nrat.get(pid) or nlp.get(pid) or (k and k["checked"]) or any(
                (r[c] or "").strip() for c in ("b_achievements", "b_strengths", "b_development")):
            st = "lm_part"
        elif r["route"] == "A" and r["staff_submitted_at"]:
            st = "sent"
        elif r["route"] == "A" and k and k["keyed"]:
            st = "kpi_keyed"
        else:
            st = "not_started"
        ack, ack_on = "", ""
        if sub:
            if r["ack_in_person"]:
                ack, ack_on = "person", r["ack_in_person_on"] or ""
                if ack_on:
                    try:
                        d_ = datetime.strptime(ack_on[:10], "%Y-%m-%d")
                        ack_on = "%d %s %d" % (d_.day, d_.strftime("%b"), d_.year)
                    except ValueError:
                        pass
            elif r["acknowledged_at"]:
                ack, ack_on = "self", _gh_adm_day(r["acknowledged_at"])
            elif r["deemed_at"]:
                ack, ack_on = "deemed", _gh_adm_day(r["deemed_at"])
            else:
                dl = gradeh_deemed_deadline(db, cid, r["lm_submitted_at"])
                if dl and dl <= now_utc:
                    ack, ack_on = "deemed", _gh_adm_day(dl)
                else:
                    ack, ack_on = "wait", ("by " + _gh_adm_day(dl)) if dl else ""
        if r["ap_name"]:
            appr = {"kind": "set", "name": r["ap_name"], "eid": r["ap_eid"] or ""}
        elif r["mg_name"]:
            appr = {"kind": "lm", "name": r["mg_name"], "eid": r["mg_eid"] or ""}
        elif (r["hr_supervisor_name"] or "").strip():
            appr = {"kind": "sup", "name": r["hr_supervisor_name"].strip(), "eid": ""}
        else:
            appr = {"kind": "none", "name": "", "eid": ""}
        route_text = ("KPI · %d %s" % (k["n"], "line" if k["n"] == 1 else "lines")) if (r["route"] == "A" and k) else \
            ("KPI · no lines" if r["route"] == "A" else "Line manager")
        out.append({
            "pid": pid, "uid": r["user_id"], "eid": r["employee_id"] or "", "name": (r["full_name"] or "").strip(),
            "title": proper_name(r["job_title"] or ""), "dept": proper_name(r["department"] or ""),
            "bg": r["business_group"] or "", "company": co, "unit": display_company(r["business_group"], co) or co,
            "grade": r["job_grade"], "route": r["route"], "route_text": route_text, "blocked": blocked,
            "status": st, "status_text": GRADEH_STATUS_LABEL[st], "status_short": GRADEH_STATUS_SHORT[st], "submitted": sub, "ack": ack, "ack_text": GRADEH_ACK_LABEL[ack],
            "ack_on": ack_on, "appr": appr, "need": appr["kind"] in ("sup", "none"), "has_email": gradeh_has_email(r["email"]),
            "email": (r["email"] or "").strip(), "left": bool(r["left_at"]), "language": r["language"],
            "lm": cal["lm"], "b_hod": cal["b_hod"], "b_bu": cal["b_bu"], "b_fin": cal["b_fin"],
            "hod_moved": {ax: bool(cal["hod_moved"][ax]) for ax in GRADEH_AXES},
            "bu_moved": {ax: bool(cal["bu_moved"][ax]) for ax in GRADEH_AXES},
            "fin_moved": {ax: mv.get((pid, ax, "final")) for ax in GRADEH_AXES},
            "signed": co in bu_sign, "signed_at": bu_sign[co]["signed_at"] if co in bu_sign else None,
            "released": co in released, "released_at": released[co]["released_at"] if co in released else None,
            "perf_rating": r["perf_rating"], "perf_value": r["perf_value"], "pot_score": r["pot_score"],
            "staff_at": r["staff_submitted_at"], "lm_at": r["lm_submitted_at"], "kpi_n": (k["n"] if k else 0), "kpi_w": (k["w"] if k else None),
            "promo": r["promo_nominate"] or "", "promo_reason": r["promo_reason"] or "",
            "cycle_id": cid, "manager_id": r["manager_id"], "hod_id": r["hod_id"], "reopened": bool(r["reopened_at"]),
            # "I do not agree": the fact, its day and its ticket (never the reason: that is read in the ticket, the super admin's)
            "dis": bool(r["disagree_at"]), "dis_on": _gh_adm_day(r["disagree_at"]) if r["disagree_at"] else "",
            "dis_date": _gh_myt(r["disagree_at"]).strftime("%Y-%m-%d") if r["disagree_at"] and _gh_myt(r["disagree_at"]) else "",
            "dis_ref": help_ref(r["disagree_ticket_id"]) if r["disagree_ticket_id"] else "",
            "dis_tid": r["disagree_ticket_id"] or 0,
            # who leads them (2026-10-31, canvas A1): the HOD stage as the sign-off reads it, the HOD's name, the unit's BU CEO
            "hod_stage": hod_stage, "hod_name": ((hd["full_name"] or "").strip() if hd else ""), "hod_eid": (hd["employee_id"] or "") if hd else "",
            # two HODs on one person (2026-11-03): every live HOD with their share (and, for a shared person, their call), whether the person
            # is shared, the first HOD's share, and who the list names as the first and second HOD whether or not they can take the stage
            "hods": hods, "shared": len(slots) == 2, "split": _gh_split(r["hod_split"]), "hod2_set": bool(r["hod2_user_id"]),
            "hod2_id": r["hod2_id"], "hod2_name": ((hod_of[r["hod2_id"]]["full_name"] or "").strip() if r["hod2_id"] in hod_of else ""),
            "hod2_eid": ((hod_of[r["hod2_id"]]["employee_id"] or "") if r["hod2_id"] in hod_of else ""),
            "hod1_name": ((hod_of[r["hod_id"]]["full_name"] or "").strip() if r["hod_id"] in hod_of else ""),
            "hod1_eid": ((hod_of[r["hod_id"]]["employee_id"] or "") if r["hod_id"] in hod_of else ""),
            "hod_listed": bool(hod_stage and r["hod_user_id"] and r["hod_user_id"] == r["hod_id"] and r["hod_id"] != r["main_hod_id"]),
            "hod_set": bool(r["hod_user_id"]),   # the list (or Set HOD) names an HOD, whether or not they can take the stage now
            "hod_main_name": ((mh["full_name"] or "").strip() if mh else (
                "no HOD" if (hod_stage and not r["main_hod_id"]) else "")),
            "bu_seated": bs is not None, "bu_name": ((bs["full_name"] or "").strip() if bs else ""), "bu_eid": (bs["employee_id"] or "") if bs else ""})
    out.sort(key=lambda p: (not p["need"], p["name"].lower(), p["pid"]))
    return out


def gradeh_unit_seats(db):
    """Every BU CEO seat as rows (business_group, company, user_id, full_name, employee_id): `buceo_seats` is the truth for who sits
    in a unit (the sign-off's gradeh_buceo_units reads the same table). A unit with no row here has no BU CEO seated, so nobody can
    sign it off and it cannot be released. One read."""
    return db.execute("SELECT s.business_group, s.company, s.user_id, u.full_name, u.employee_id FROM buceo_seats s "
                      "JOIN users u ON u.id=s.user_id ORDER BY s.business_group, s.company, s.user_id").fetchall()


def gradeh_has_email(email):
    """Does this person have a work email on OneHR (an address with an @ in it)? The ONE rule (2026-10-31): the admin People & progress
    "Can sign in" column, its Show filter, the line manager's "No work email" tag and filter, Grade H staff's own reminder, the notice
    emails (their SQL reads LIKE '%@%') and the Schedule's no-email count all ask it. A person without one is never emailed: the bar on
    My Appraisal reminds them."""
    return "@" in (email or "").strip()


def _gh_hod_stage(db, hod_id, user_id, company, seats):
    """Does this person go through an HOD stage: they have an HOD, who is not themselves, not their unit's BU CEO (`seats` is
    {(user id, company)} of every BU CEO seat) and holds the Grade H HOD role (a BU CEO or BG CEO holds none: the BU CEO covers them;
    a calibrator of the normal review does hold it, 2026-11-03).
    The one rule behind the Leaders line, the Show filter, the LEADERS column and the Excel, as the sign-off reads it."""
    return bool(hod_id and hod_id != user_id and (hod_id, company or "") not in seats and gradeh_hod_has_role(db, hod_id))


def _gh_adm_pick(people, key):
    """The people a tile, a Show choice or a list-panel link names. One definition for the count and its list."""
    key = key or "all"
    if key == "all":
        return list(people)
    if key in ("route_a", "route_b"):
        return [p for p in people if p["route"] == key[-1].upper()]
    if key == "submitted":
        return [p for p in people if p["submitted"]]
    if key == "acked":
        return [p for p in people if p["ack"] in ("self", "person", "deemed")]
    if key == "need":
        return [p for p in people if p["need"]]
    if key == "disagree":   # told us they do not agree with their result (not calibrated)
        return [p for p in people if p["dis"]]
    if key == "nohod":   # no HOD stage: their BU CEO covers them (the sign-off's rule, gradeh_admin_people's hod_stage)
        return [p for p in people if not p["hod_stage"]]
    if key == "shared":   # two HODs calibrate them, each live (a second HOD who holds a BU CEO or BG CEO seat leaves one: not shared)
        return [p for p in people if p["shared"]]
    if key == "nobu":    # their unit has no BU CEO seated: nobody can sign it off, so it can't be released
        return [p for p in people if not p["bu_seated"]]
    if key.startswith("hs:"):   # Home's card: its five grouped stages (_gh_home_stage, the card's own mapping)
        return [p for p in people if _gh_home_stage(p) == key[3:]]
    if key == "ack_sub":   # Home's Acknowledged: of those their line manager submitted, acknowledged and not disagreeing
        return [p for p in people if _gh_ack_sub(p)]
    if key.startswith("st:"):
        return [p for p in people if p["status"] == key[3:]]
    if key.startswith("ack:"):
        return [p for p in people if p["ack"] == key[4:]]
    if key == "ack_wait_noemail":
        return [p for p in people if p["ack"] == "wait" and not p["has_email"]]
    # Final bands
    if key == "signed_off":
        return [p for p in people if p["signed"]]
    if key == "not_signed":
        return [p for p in people if not p["signed"]]
    if key == "perf_moved":
        return [p for p in people if any((p["hod_moved"]["perf"], p["bu_moved"]["perf"], p["fin_moved"]["perf"]))]
    if key == "pot_moved":
        return [p for p in people if any((p["hod_moved"]["pot"], p["bu_moved"]["pot"], p["fin_moved"]["pot"]))]
    if key == "moved":
        return [p for p in people if any(p["hod_moved"].values()) or any(p["bu_moved"].values()) or any(p["fin_moved"].values())]
    if key == "super":
        return [p for p in people if any(p["fin_moved"].values())]
    if key == "released":
        return [p for p in people if p["released"]]
    return []


GRADEH_LIST_TITLES = {
    "all": "On the Grade H list", "route_a": "KPI route", "route_b": "Line manager route",
    "submitted": "Submitted by line managers", "acked": "Acknowledged (own sign-in, in person or deemed)",
    "need": "Need an appraiser", "disagree": "Do not agree with their result (not calibrated)", "nohod": "No HOD (their BU CEO covers them)", "shared": "Shared by two HODs (both calibrate them)", "nobu": "No BU CEO seated (their unit can't be signed off)",
    "ack:wait": "Submitted, not yet acknowledged", "ack_wait_noemail": "Not yet acknowledged, no work email",
    "signed_off": "Signed off by a BU CEO", "perf_moved": "Performance moved", "pot_moved": "Potential moved",
    "super": "Final band changed by the super admin", "released": "Released", "not_signed": "Not signed off",
    # Home's Grade H card (2026-11-06): the card's grouped stages and its Acknowledged
    "hs:not_started": "Not started", "hs:lm": "With the line manager (any step)", "hs:cal": "In calibration (with the HOD or BU CEO)",
    "hs:signed": "Signed off", "hs:released": "Released", "ack_sub": "Acknowledged, of those their line manager submitted"}
# the same words as extra choices on People & progress's Show picker: shown (selected) only when the page is opened from Home's card, so the
# picker's own list is unchanged and the page is never silently reset to Everyone
GRADEH_SHOW_HOME = {k: GRADEH_LIST_TITLES[k] for k in ("hs:not_started", "hs:lm", "hs:cal", "hs:signed", "hs:released", "ack_sub")}


@admin_list("gh", "cycle")
def _list_gh(db, me, vc, args):
    """Every Grade H count on the admin pages opens its people here (ADMIN_LISTS; the super admin's). ?f= names the count
    (_gh_adm_pick); the rows are the same dicts the page counted."""
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc):
        abort(404)
    f = args.get("f") or "all"
    people = gradeh_admin_people(db, cyc["id"])
    bgq, unitq = (args.get("bg") or "").strip(), (args.get("unit") or "").strip()   # Home's card: one row's people (a group, or a unit of it)
    if bgq:
        people = [p for p in people if p["bg"] == bgq]
    if unitq:
        people = [p for p in people if p["company"] == unitq]
    people = _gh_adm_pick(people, f)
    hodq = (args.get("hod") or "").strip()
    if f.startswith("st:"):
        title = GRADEH_STATUS_LABEL.get(f[3:], "Grade H")
    else:
        title = GRADEH_LIST_TITLES.get(f, "Grade H")
    if hodq:   # By HOD's People count: one HOD's people (first or second HOD), or "none" = nobody named
        people = _gh_hod_filter(people, hodq)
        hu = db.execute("SELECT full_name FROM users WHERE id=?", (int(hodq),)).fetchone() if hodq.isdigit() else None
        title = "No Grade H HOD (the BU CEO covers them)" if hodq == "none" else ("Grade H people of %s" % ((hu["full_name"] or "").strip() if hu else "that HOD"))
    out = []
    for p in people:
        u = {"id": p["uid"], "full_name": p["name"], "employee_id": p["eid"], "business_group": p["bg"],
             "company": p["company"], "department": p["dept"], "job_grade": p["grade"]}
        cells = [(p["status_text"] + ((" · " + p["blocked"]) if p["blocked"] else ""), "clip"),
                 (("Disagrees" if p["dis"] else {"self": "Acknowledged", "person": "In person", "deemed": "Deemed", "wait": "Waiting"}.get(p["ack"], "")), "clip")]
        out.append(_list_row(u, "overview", cells))
    tab = "bands" if f in ("signed_off", "perf_moved", "pot_moved", "super", "released", "not_signed") else "people"
    full = url_for("admin_gradeh", tab=tab, **({"hod": hodq} if hodq else {}))
    if f in GRADEH_SHOW_HOME:   # Home's card: the full page is People & progress with that Show choice and that row's group / unit
        full = url_for("admin_gradeh", tab="people", show=f, **({"bg": bgq} if bgq else {}), **({"bu": unitq} if unitq else {}))
    return {"kicker": "Grade H Appraisal · " + cyc["name"], "title": "%s · %s" % (title, format(len(out), ",")),
            "sub": "The same people the count on the page counts.",
            "full": full, "cols": ["Where it is", "Acknowledged"], "widths": [30, 24], "rows": out,
            "empty": "Nobody."}


# ---- Set appraiser ----------------------------------------------------------------------------------------------------
def gradeh_appraiser_block(db, cid, pid, appraiser_uid=None, ctx=None):
    """Why this person's appraiser cannot be changed now: (their row with `nm`, kind, words), kind None and words None when it can.
    The ONE check behind Set appraiser, one at a time or for several (the bulk panel's "left out" is exactly what this refuses):
    not on the Grade H list; the unit released; the appraisal submitted (reopen it first); and, once an appraiser is chosen
    (`appraiser_uid`), that person themselves. Reads only. `ctx` (a _GhCtx, optional): the line follow-through asks it for many
    people, whose rows, released units and submitted appraisals it has read in one batch; the rule is this same code."""
    if ctx is not None and pid in ctx.by_pid:
        p = ctx.by_pid[pid]
    else:
        p = db.execute("SELECT p.*, uu.full_name AS nm FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
                       "WHERE p.id=? AND p.cycle_id=? AND p.private_company=0", (pid, cid)).fetchone()
    if not p:
        return None, "missing", "That person is not on the Grade H list for this cycle."
    released = (bool(p["company"]) and p["company"] in ctx.released) if ctx is not None else gradeh_is_released(db, cid, pid)
    if released:
        return p, "released", "This unit's results have been released, so nothing changes now."
    submitted = (pid in ctx.submitted) if ctx is not None else bool(db.execute(
        "SELECT 1 FROM gradeh_appraisals WHERE cycle_id=? AND person_id=? AND lm_submitted_at IS NOT NULL", (cid, pid)).fetchone())
    if submitted:
        return p, "submitted", "%s's appraisal has been submitted: reopen it before changing the appraiser." % p["nm"]
    if appraiser_uid is not None and appraiser_uid == p["user_id"]:
        return p, "self", "Nobody appraises themselves: pick someone else."
    return p, None, None


_GH_FOLLOW_TXT = " (follows the main %s change)"


def _gh_set_appraiser_core(db, actor_id, cid, pid, eid, follow=None, ctx=None):
    """The guard and the write of an appraiser set by hand, with no super-admin check and no commit: Set appraiser (gradeh_set_appraiser,
    which holds the gate and commits) and the line follow-through (`follow`="line manager": clears the override when the main line
    manager changes) both call it. `eid` '' = clear it. Audited. Returns (ok, message)."""
    p, _kind, why = gradeh_appraiser_block(db, cid, pid, None, ctx)
    if why:
        return False, why
    tail = (_GH_FOLLOW_TXT % follow) if follow else ""
    eid = (eid or "").strip()
    if not eid:
        db.execute("UPDATE gradeh_people SET appraiser_id=NULL, updated_at=datetime('now') WHERE id=?", (pid,))
        log_activity(db, actor_id, "gradeh_set_appraiser", "%s: appraiser cleared, their line manager again%s" % (p["nm"], tail),
                     target_user_id=p["user_id"], commit=False)
        return True, "%s's appraiser is their line manager on OneHR again." % p["nm"]
    a_ = db.execute("SELECT * FROM users WHERE employee_id=? AND role!='admin' AND left_at IS NULL", (eid,)).fetchone()
    if not a_:
        return False, "Pick the appraiser from the list: that person isn't an active member of OneHR."
    _p, _kind, why = gradeh_appraiser_block(db, cid, pid, a_["id"], ctx)
    if why:
        return False, why
    db.execute("UPDATE gradeh_people SET appraiser_id=?, updated_at=datetime('now') WHERE id=?", (a_["id"], pid))
    log_activity(db, actor_id, "gradeh_set_appraiser", "%s: appraiser set to %s (%s)%s" % (p["nm"], a_["full_name"], eid, tail),
                 target_user_id=p["user_id"], commit=False)
    return True, "%s is now %s's appraiser." % (a_["full_name"], p["nm"])


def gradeh_set_appraiser(db, me, pid, eid):
    """THE writer of an appraiser set by hand. `eid` is the Employee ID a picker returned ('' = clear it: the line manager on
    OneHR is the appraiser again). Refused: not the super admin; no active Year-End cycle with the module on; not on the list;
    the unit released; the appraisal already submitted (reopen it first); a person unknown to OneHR, an admin, someone who has
    left, or the person themselves (gradeh_appraiser_block). Audited. Commits. Returns (ok, message). The guard and the write are
    _gh_set_appraiser_core's, which the line follow-through shares."""
    if not me or not is_super(me):
        return False, "Only the super admin sets an appraiser."
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return False, "Grade H Appraisal is not running on the active cycle."
    ok, msg = _gh_set_appraiser_core(db, me["id"], cid, pid, eid)
    if ok:
        db.commit()
    return ok, msg


def _gh_hod_signed(db, cid, hid, memo=None):
    """Has this HOD signed off a Grade H stage this cycle? (`memo`: one answer an HOD, for a caller asking about many people.)"""
    key = ("signed", hid)
    if memo is not None and key in memo:
        return memo[key]
    out = any(gradeh_hod_state(db, cid, hid).values())
    if memo is not None:
        memo[key] = out
    return out


def _gh_hod_leave_refusal(db, cid, p, cur, memo=None):
    """Why a person's Grade H HOD cannot change now (the words), else None: the unit released or signed off by the BU CEO, or their
    CURRENT HOD (`cur`) has already signed off a stage (their sign-off would then miss or wrongly cover this person). `p` = their
    gradeh_people row with `nm` and `company`. THE first two checks of Set HOD, and of the line follow-through, which asks
    whether Grade H can follow a main HOD change."""
    lock = _gh_cal_lock_text(db, cid, p["company"], memo)
    if lock:
        return lock
    if cur and _gh_hod_signed(db, cid, cur, memo):
        return "%s's HOD has already signed off a Grade H stage, so the HOD cannot change now." % p["nm"]
    return None


def _gh_hod_take_refusal(db, cid, hid, name, memo=None):
    """Why this account cannot take on a Grade H person now (the words), else None: they have already signed off a stage."""
    if hid and _gh_hod_signed(db, cid, hid, memo):
        return "%s has already signed off a Grade H stage, so they cannot take on another person now." % name
    return None


def _gh_set_hod_core(db, actor_id, cid, p, eid, cur=None, cur_given=False, follow=None, memo=None):
    """The guard and the write of a person's Grade H HOD set by hand, with no super-admin check and no commit: Set HOD (gradeh_set_hod,
    which holds the gate and commits) and the line follow-through (`follow`="HOD": clears the override when the main HOD changes)
    both call it. `p` = the person's gradeh_people row with `nm` and `company`; `cur` = their current Grade H HOD when the caller
    knows it (the follow-through asks after users.hod_id has moved), else gradeh_hod_of. `eid` '' = clear it. Audited. Returns
    (ok, message)."""
    if not cur_given:
        cur = gradeh_hod_of(db, p)
    why = _gh_hod_leave_refusal(db, cid, p, cur, memo)
    if why:
        return False, why
    tail = (_GH_FOLLOW_TXT % follow) if follow else ""
    pid = p["id"]
    eid = (eid or "").strip()
    if not eid:
        db.execute("UPDATE gradeh_people SET hod_user_id=NULL, updated_at=datetime('now') WHERE id=?", (pid,))
        log_activity(db, actor_id, "gradeh_set_hod", "%s: Grade H HOD cleared, their OneHR HOD again%s" % (p["nm"], tail),
                     target_user_id=p["user_id"], commit=False)
        return True, "%s's Grade H HOD is their OneHR HOD again." % p["nm"]
    h_ = _eid_resolve(db, eid)[0]
    if not h_ or h_["role"] == "admin" or h_["left_at"] or h_["is_demo"]:
        return False, "Pick the HOD from the list: that person isn't an active member of OneHR."
    if h_["id"] == p["user_id"]:
        return False, "Nobody is their own HOD: pick someone else."
    if p["hod2_user_id"] and h_["id"] == p["hod2_user_id"]:
        return False, "%s is already their second Grade H HOD: pick someone else, or change the pair with Set Grade H HODs." % h_["full_name"]
    why = _gh_hod_take_refusal(db, cid, h_["id"], h_["full_name"], memo)
    if why:
        return False, why
    db.execute("UPDATE gradeh_people SET hod_user_id=?, updated_at=datetime('now') WHERE id=?", (h_["id"], pid))
    log_activity(db, actor_id, "gradeh_set_hod", "%s: Grade H HOD set to %s (%s)%s" % (p["nm"], h_["full_name"], h_["employee_id"], tail),
                 target_user_id=p["user_id"], commit=False)
    return True, "%s is now %s's Grade H HOD.%s" % (h_["full_name"], p["nm"], (
        "" if gradeh_hod_has_role(db, h_["id"]) else " They hold a BU CEO or BG CEO seat, so the BU CEO covers this person instead."))


def gradeh_set_hod(db, me, pid, eid):
    """THE writer of a person's Grade H HOD set by hand (gradeh_people.hod_user_id; users.hod_id is never touched BY IT). `eid` is the
    Employee ID a picker returned ('' = clear it: their OneHR HOD is their Grade H HOD again). Refused: not the super admin; no
    running module; not on the list; the unit released or signed off by the BU CEO; their current HOD, or the one picked, has already
    signed off a stage (their sign-off would then miss or wrongly cover this person); an unknown, admin, left or demo account, or
    the person themselves. Audited. Commits. Returns (ok, message). The guard and the write are _gh_set_hod_core's, which the line
    follow-through shares (a main HOD change clears the person's override, 13 Nov 2026)."""
    if not me or not is_super(me):
        return False, "Only the super admin sets a Grade H HOD."
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return False, "Grade H Appraisal is not running on the active cycle."
    p = db.execute("SELECT p.*, uu.full_name AS nm, uu.company AS company FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
                   "WHERE p.id=? AND p.cycle_id=? AND p.private_company=0", (pid, cid)).fetchone()
    if not p:
        return False, "That person is not on the Grade H list for this cycle."
    ok, msg = _gh_set_hod_core(db, me["id"], cid, p, eid)
    if ok:
        db.commit()
    return ok, msg


def _gh_hod_ticks_fold(db, cid, pid, keep_uid):
    """A person goes back to ONE HOD: that HOD's Agree ticks in gradeh_hod_reviews are put back in gradeh_reviews (the one-HOD reader's
    place, band and who) where it holds none, and the person's rows in gradeh_hod_reviews are dropped (the removed HOD's tick has no
    place). A band already agreed and signed stays what it was. Does not commit."""
    if keep_uid:
        for r in db.execute("SELECT axis, band FROM gradeh_hod_reviews WHERE cycle_id=? AND person_id=? AND by_user_id=?", (cid, pid, keep_uid)).fetchall():
            db.execute("INSERT INTO gradeh_reviews(cycle_id, person_id, axis, tier, band, by_user_id) VALUES (?,?,?,?,?,?) "
                       "ON CONFLICT(cycle_id, person_id, axis, tier) DO UPDATE SET band=excluded.band, by_user_id=excluded.by_user_id",
                       (cid, pid, r["axis"], "hod", r["band"], keep_uid))
    db.execute("DELETE FROM gradeh_hod_reviews WHERE cycle_id=? AND person_id=?", (cid, pid))


def _gh_hod_account_error(h_, what):
    """Why this picked account cannot be a Grade H HOD at all (the words), else None: not a member, an admin, left, or a demo login."""
    if not h_ or h_["role"] == "admin" or h_["left_at"] or h_["is_demo"]:
        return "Pick the %s from the list: that person isn't an active member of OneHR." % what
    return None


def _gh_hod_signed_words(db, cid, p):
    """The words when this person's CURRENT Grade H HOD has already signed off a stage (their sign-off would then miss or wrongly cover
    the person, so the HOD cannot change), else None. `p` = the person's gradeh_people row with `nm`. THE check Set HODs makes when the
    first HOD changes, and the bulk panel's "left out" reads."""
    cur = gradeh_hod_of(db, p)
    if cur and any(gradeh_hod_state(db, cid, cur).values()):
        return "%s's HOD has already signed off a Grade H stage, so the HOD cannot change now." % p["nm"]
    return None


def gradeh_hods_block(db, cid, pid):
    """Why this person's Grade H HODs cannot be set now, whoever is picked: (their row with `nm`, `company`, `hod2_user_id`, kind, words),
    kind None and words None when they can. Not on the list ("missing"); the unit signed off by the BU CEO or released ("locked"). THE
    first two checks of gradeh_set_hods and the bulk panel's "left out" (the writer's own check, as gradeh_appraiser_block is Set
    appraiser's). Reads only."""
    p = db.execute("SELECT p.*, uu.full_name AS nm, uu.company AS company FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
                   "WHERE p.id=? AND p.cycle_id=? AND p.private_company=0", (pid, cid)).fetchone()
    if not p:
        return None, "missing", "That person is not on the Grade H list for this cycle."
    lock = _gh_cal_lock_text(db, cid, p["company"])
    if lock:
        return p, "locked", lock
    return p, None, None


def _gh_hod_pick_error(db, cid, h_, person_uid, what):
    """Why this picked account cannot be a Grade H HOD (the words), else None: not a member, an admin, left, a demo login, the person
    themselves, or someone who has already signed off a Grade H stage (their sign-off would miss this person)."""
    why = _gh_hod_account_error(h_, what)
    if why:
        return why
    if h_["id"] == person_uid:
        return "Nobody is their own HOD: pick someone else."
    if any(gradeh_hod_state(db, cid, h_["id"]).values()):
        return "%s has already signed off a Grade H stage, so they cannot take on another person now." % h_["full_name"]
    return None


def gradeh_set_hods(db, me, pid, hod_eid=None, hod2_eid=None, split=None, clear2=False, commit=True):
    """THE writer of a person's Grade H HODs as a pair (2026-11-03, Chris: "HOD A and B needs to calibrate person A"): the first HOD
    (blank = unchanged), the SECOND HOD (a picked Employee ID; `clear2` removes it) and the split, the FIRST HOD's share (10 to 90 in 10s;
    blank with a second HOD = what it is now, else 50). Refused: not the super admin; no running module; not on the list; the unit
    signed off by the BU CEO or released; a second HOD who is the same account as the first or is the person; an unknown, admin, left or
    demo account; a HOD (the one leaving, the one coming) who has already signed off a Grade H stage; a split with no second HOD or one
    outside 10..90 in 10s; a pair with no first HOD; nothing to change. Taking the second HOD away puts the first HOD's ticks back
    (_gh_hod_ticks_fold); bands already set stay. Audited, naming both HODs and the split. Commits (`commit=False`: the caller commits, as
    Set HOD for several does so that the whole batch is one transaction; a refusal never writes). Returns (ok, message)."""
    if not me or not is_super(me):
        return False, "Only the super admin sets a Grade H HOD."
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return False, "Grade H Appraisal is not running on the active cycle."
    return _gh_set_hods_core(db, me["id"], cid, pid, hod_eid, hod2_eid, split, clear2, commit)


def _gh_set_hods_core(db, actor_id, cid, pid, hod_eid=None, hod2_eid=None, split=None, clear2=False, commit=True, follow=None, p=None):
    """The guard and the write of gradeh_set_hods, with no super-admin check: the Grade H page's Set HODs (which holds the gate) and the
    line follow-through (`follow`="HOD", `p` = the person's row as the follow-through holds it: a main HOD change that lands on their
    second Grade H HOD takes them back to one HOD, ticks folded) both call it. Everything is gradeh_set_hods's, word for word."""
    if p is None:
        p, _kind, why = gradeh_hods_block(db, cid, pid)
        if why:
            return False, why
    hod_eid, hod2_eid = (hod_eid or "").strip(), (hod2_eid or "").strip()
    split_raw = ("" if split is None else str(split)).strip()
    if hod2_eid and clear2:
        return False, "Pick a second HOD or take it away, not both."
    # the first HOD
    cur1 = gradeh_hod_of(db, p)
    new1 = None
    if hod_eid:
        h1 = _eid_resolve(db, hod_eid)[0]
        why = _gh_hod_pick_error(db, cid, h1, p["user_id"], "HOD")
        if why:
            return False, why
        if cur1 != h1["id"]:
            why = _gh_hod_signed_words(db, cid, p)
            if why:
                return False, why
        new1 = h1
    first = new1["id"] if new1 else cur1
    # the second HOD
    cur2 = p["hod2_user_id"] or None
    new2, drop2 = None, False
    if hod2_eid:
        h2 = _eid_resolve(db, hod2_eid)[0]
        if h2 and h2["id"] != cur2:
            why = _gh_hod_pick_error(db, cid, h2, p["user_id"], "second HOD")
            if why:
                return False, why
        elif not h2 or h2["role"] == "admin" or h2["left_at"] or h2["is_demo"]:
            return False, "Pick the second HOD from the list: that person isn't an active member of OneHR."
        elif h2["id"] == p["user_id"]:
            return False, "Nobody is their own HOD: pick someone else."
        if first and h2["id"] == first:
            return False, "The second HOD is the same person as the HOD: pick someone else."
        if cur2 and cur2 != h2["id"] and any(gradeh_hod_state(db, cid, cur2).values()):
            return False, "%s has already signed off a Grade H stage, so they cannot be taken off now." % (
                db.execute("SELECT full_name FROM users WHERE id=?", (cur2,)).fetchone()["full_name"])
        new2 = h2
    elif clear2:
        if not cur2:
            return False, "%s has no second Grade H HOD to take away." % p["nm"]
        if any(gradeh_hod_state(db, cid, cur2).values()):
            return False, "%s's second HOD has already signed off a Grade H stage, so they cannot be taken off now." % p["nm"]
        drop2 = True
    final2 = new2["id"] if new2 else (None if drop2 else cur2)
    if final2 and final2 == first:
        return False, "The second HOD is the same person as the HOD: pick someone else."
    # the split
    if split_raw:
        try:
            sp = int(split_raw)
        except ValueError:
            return False, "The split is the first HOD's share: 10 to 90, in steps of 10."
        if sp not in GRADEH_SPLITS:
            return False, "The split is the first HOD's share: 10 to 90, in steps of 10."
        if not final2:
            return False, "A split needs a second HOD: pick one, or leave the split out."
    elif final2:
        sp = _gh_split(p["hod_split"]) if cur2 == final2 else 50
    else:
        sp = None
    if final2 and not first:
        return False, "Set the person's HOD first: a second HOD shares the work of one."
    if not (new1 or drop2 or (new2 and new2["id"] != cur2) or (final2 and final2 == cur2 and sp != _gh_split(p["hod_split"]))):
        return False, "Nothing to change."
    sets = {}
    if new1:
        sets["hod_user_id"] = new1["id"]
    if new2 or drop2:
        sets["hod2_user_id"] = final2
    sets["hod_split"] = sp if final2 else None
    db.execute("UPDATE gradeh_people SET %s, updated_at=datetime('now') WHERE id=?" % ", ".join("%s=?" % k for k in sets),
               list(sets.values()) + [pid])
    if cur2 and final2 != cur2:   # the old second HOD leaves: the first HOD's own ticks go back to the one-HOD place
        _gh_hod_ticks_fold(db, cid, pid, first)
    nm = {r["id"]: (r["full_name"], r["employee_id"]) for r in db.execute(
        "SELECT id, full_name, employee_id FROM users WHERE id IN (%s)" % ",".join("?" * len([x for x in (first, final2) if x])),
        [x for x in (first, final2) if x])} if (first or final2) else {}
    if final2:
        detail = "%s: Grade H HODs %s (%s) %d%% and %s (%s) %d%%" % (
            p["nm"], nm[first][0], nm[first][1], sp, nm[final2][0], nm[final2][1], 100 - sp)
    else:
        detail = "%s: second Grade H HOD taken away%s" % (p["nm"], (", HOD %s (%s)" % nm[first]) if first else "")
    log_activity(db, actor_id, "gradeh_set_hods", detail + ((_GH_FOLLOW_TXT % follow) if follow else ""),
                 target_user_id=p["user_id"], commit=False)
    if commit:
        db.commit()
    if not final2:
        return True, "%s has one Grade H HOD again." % p["nm"]
    live = [h for h in (first, final2) if gradeh_hod_has_role(db, h)]
    if len(live) == 2:
        note = ""
    elif live:
        note = " %s holds a BU CEO or BG CEO seat, so %s takes them at 100%%." % (nm[(set((first, final2)) - set(live)).pop()][0], nm[live[0]][0])
    else:
        note = " Neither holds the HOD role, so the BU CEO covers them."
    return True, "%s and %s are now %s's Grade H HODs, %d : %d.%s" % (nm[first][0], nm[final2][0], p["nm"], sp, 100 - sp, note)


GRADEH_BULK_MAX = 200   # people one Set appraiser can name (a page of the table is 50)
_GH_LEFT_WORD = {"released": "released", "submitted": "submitted", "self": "is the appraiser", "missing": "not on the list"}


def gradeh_set_appraiser_bulk(db, me, pids, eid):
    """Set ONE appraiser for several people (the table's ticks). Validates everything first: the super admin, a module running,
    at least one person, a picked appraiser (an empty or typed name is refused here, never read as "clear"), who is an active member of
    OneHR; then asks gradeh_appraiser_block of every person (the same check the one-at-a-time writer makes). Only then calls
    gradeh_set_appraiser once per person who can be changed (ONE writer: audited and committed per person). Returns (ok, message):
    "Set for M; left out: Name (submitted), ..." (ok when at least one was set)."""
    if not me or not is_super(me):
        return False, "Only the super admin sets an appraiser."
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return False, "Grade H Appraisal is not running on the active cycle."
    ids = []
    for x in pids or []:
        try:
            x = int(x)
        except (TypeError, ValueError):
            continue
        if x not in ids:
            ids.append(x)
    if not ids:
        return False, "Pick at least one person."
    if len(ids) > GRADEH_BULK_MAX:
        return False, "Pick up to %d people at a time." % GRADEH_BULK_MAX
    eid = (eid or "").strip()
    if not eid:
        return False, "Pick the appraiser from the list: a typed name that is not a pick is refused."
    a_ = db.execute("SELECT * FROM users WHERE employee_id=? AND role!='admin' AND left_at IS NULL", (eid,)).fetchone()
    if not a_:
        return False, "Pick the appraiser from the list: that person isn't an active member of OneHR."
    todo, left = [], []
    for pid in ids:
        p, kind, why = gradeh_appraiser_block(db, cid, pid, a_["id"])
        if why:
            left.append("%s (%s)" % ((p["nm"] if p else "someone not on the list"), _GH_LEFT_WORD[kind]))
        else:
            todo.append(pid)
    done = 0
    for pid in todo:
        ok, msg = gradeh_set_appraiser(db, me, pid, eid)
        if ok:
            done += 1
        else:
            p = db.execute("SELECT uu.full_name FROM gradeh_people p JOIN users uu ON uu.id=p.user_id WHERE p.id=?", (pid,)).fetchone()
            left.append("%s (%s)" % (p[0] if p else "someone", msg.rstrip(".")))
    if not done:
        return False, "Nobody was changed; left out: %s." % "; ".join(left)
    return True, "Set for %d%s." % (done, ("; left out: " + ", ".join(left)) if left else "")


def gradeh_set_hods_bulk(db, me, pids, hod_eid=None, hod2_eid=None, split=None, clear2=False):
    """Set the Grade H HOD (and, optionally, a second HOD and the split, or take every second HOD away) for several people at once (People &
    progress, By person: "Set HOD for N"; the super admin's). ONE rule: every person goes through gradeh_set_hods, which makes all the
    checks and writes its own audit row; nothing is re-checked here except what is the same for the whole batch and is read before any write:
    the super admin, a module running, at least one person (GRADEH_BULK_MAX at most), a HOD that was PICKED (a blank or typed name that is not
    a pick is refused) and is an active member who has not signed off a stage, a second HOD that is one too and not the same account, "pick a
    second HOD or take it away, not both", and a split in 10..90 (GRADEH_SPLITS) that goes only with a second HOD. A blank second HOD keeps
    each person's own second HOD; `clear2` takes it away from those who have one (a person with none is not "left out" for it). All in ONE
    transaction: committed once at the end when at least one person changed, rolled back otherwise (and on any error). A person the writer
    refuses (the unit signed off or released, their HOD has signed a stage, the same person, nothing to change) is left out with its words.
    Returns (ok, message, done, left): ok when at least one was set; `left` = [(name, reason)]."""
    if not me or not is_super(me):
        return False, "Only the super admin sets a Grade H HOD.", 0, []
    cid = gradeh_calib_cycle_id(db)
    if not cid:
        return False, "Grade H Appraisal is not running on the active cycle.", 0, []
    ids = []
    for x in pids or []:
        try:
            x = int(x)
        except (TypeError, ValueError):
            continue
        if x not in ids:
            ids.append(x)
    if not ids:
        return False, "Pick at least one person.", 0, []
    if len(ids) > GRADEH_BULK_MAX:
        return False, "Pick up to %d people at a time." % GRADEH_BULK_MAX, 0, []
    hod_eid, hod2_eid = (hod_eid or "").strip(), (hod2_eid or "").strip()
    split_raw = ("" if split is None else str(split)).strip()
    if not hod_eid:
        return False, "Pick the HOD from the list: a typed name that is not a pick is refused.", 0, []
    h1 = _eid_resolve(db, hod_eid)[0]
    why = _gh_hod_pick_error(db, cid, h1, None, "HOD")
    if why:
        return False, why, 0, []
    if hod2_eid and clear2:
        return False, "Pick a second HOD or take it away, not both.", 0, []
    if hod2_eid:
        h2 = _eid_resolve(db, hod2_eid)[0]
        why = _gh_hod_account_error(h2, "second HOD")
        if why:
            return False, why, 0, []
        if h2["id"] == h1["id"]:
            return False, "The second HOD is the same person as the HOD: pick someone else.", 0, []
    if split_raw:
        try:
            ok_split = int(split_raw) in GRADEH_SPLITS
        except ValueError:
            ok_split = False
        if not ok_split:
            return False, "The split is the first HOD's share: 10 to 90, in steps of 10.", 0, []
        if not hod2_eid:
            return False, "A split needs a second HOD: pick one, or leave the split out.", 0, []
    done, left = 0, []
    try:
        for pid in ids:
            p, _kind, _why = gradeh_hods_block(db, cid, pid)
            c2 = bool(clear2 and p is not None and p["hod2_user_id"])
            ok, msg = gradeh_set_hods(db, me, pid, hod_eid, hod2_eid, split_raw, c2, commit=False)
            if ok:
                done += 1
            else:
                left.append((p["nm"] if p is not None else "Someone not on the list", msg.rstrip(".")))
        if done:
            db.commit()
        else:
            db.rollback()
    except Exception:
        db.rollback()
        raise
    left_txt = "; left out: " + ", ".join("%s (%s)" % x for x in left[:8]) + ((" and %d more" % (len(left) - 8)) if len(left) > 8 else "") if left else ""
    if not done:
        return False, "Nobody was changed%s." % (left_txt or ""), 0, left
    who = ("%s and %s are now the Grade H HODs of" % (h1["full_name"], h2["full_name"])) if hod2_eid else ("%s is now the Grade H HOD of" % h1["full_name"])
    return True, "%s %d %s%s%s." % (who, done, "person" if done == 1 else "people",
                                    (", %d : %d" % (int(split_raw), 100 - int(split_raw))) if (hod2_eid and split_raw) else "", left_txt), done, left


