GRADEH_RESULTS_HEAD = ["Business group", "Business unit", "Employee name", "Employee ID", "Job grade", "Job title", "Department",
                       "Line manager", "Line manager employee ID", "Route", "Appraiser", "Line manager performance rating",
                       "Line manager performance band", "Line manager potential score", "Line manager potential band",
                       "HOD performance band", "HOD potential band", "BU CEO performance band", "BU CEO potential band",
                       "Final performance band", "Final potential band", "Talent label", "Moves and remarks",
                       "Acknowledgement", "Acknowledgement date", "Disagrees", "Promotion nomination", "Promotion reason",
                       "Unit signed off by the BU CEO (MYT)", "Released (MYT)"]
_GH_STAGE_WORD = {"hod": "HOD", "buceo": "BU CEO", "final": "Super admin"}


def gradeh_results_rows(db, cid, people):
    """The Excel's rows, one a person: the calibration trail (every move, oldest first, as 'HOD performance ME -> AE: remark')
    in one cell, the acknowledgement as it stands, the promotion nomination and its reason. Moves are read in batches."""
    pids = [p["pid"] for p in people]
    trail = {}
    for i in range(0, len(pids), 400):
        part = pids[i:i + 400]
        for m in db.execute("SELECT m.*, u.full_name AS by_name FROM gradeh_band_moves m LEFT JOIN users u ON u.id=m.by_user_id "
                            "WHERE m.cycle_id=? AND m.person_id IN (%s) ORDER BY m.id" % ",".join("?" * len(part)), [cid] + part):
            trail.setdefault(m["person_id"], []).append(m)
    mgr = {r[0]: (r[1], r[2]) for r in db.execute(
        "SELECT p.id, m.full_name, m.employee_id FROM gradeh_people p JOIN users uu ON uu.id=p.user_id "
        "LEFT JOIN users m ON m.id=uu.manager_id WHERE p.cycle_id=?", (cid,))}
    rows = []
    for p in people:
        mv_ = "; ".join("%s %s %s -> %s%s%s" % (_GH_STAGE_WORD.get(m["stage"], m["stage"]), "performance" if m["axis"] == "perf" else "potential",
                                                m["came_in"] or "?", m["band"], (" (" + m["by_name"] + ")") if m["by_name"] else "",
                                                (": " + m["remark"]) if m["remark"] else "") for m in trail.get(p["pid"], []))
        label = gradeh_calib_label(p["b_fin"]["perf"], p["b_fin"]["pot"]) or ""
        ack = (GRADEH_ACK_LABEL[p["ack"]] if p["ack"] and p["ack"] != "wait" else ("Waiting" if p["ack"] == "wait" else ""))
        m_ = mgr.get(p["pid"]) or (None, None)
        appr = p["appr"]["name"] + ((" (" + p["appr"]["eid"] + ")") if p["appr"]["eid"] else "")
        rows.append([p["bg"], p["company"], p["name"], p["eid"], p["grade"], p["title"], p["dept"],
                     m_[0] or "", m_[1] or "", "KPI" if p["route"] == "A" else "Line manager",
                     appr + ("" if p["appr"]["kind"] != "sup" else " (supervisor, no line manager in the source file)"),
                     p["perf_rating"] if p["submitted"] else None, p["lm"]["perf"] or "", p["pot_score"] if p["submitted"] else None,
                     p["lm"]["pot"] or "", p["b_hod"]["perf"] if p["submitted"] else "", p["b_hod"]["pot"] if p["submitted"] else "",
                     p["b_bu"]["perf"] if p["submitted"] else "", p["b_bu"]["pot"] if p["submitted"] else "",
                     p["b_fin"]["perf"] or "", p["b_fin"]["pot"] or "", label, mv_, ack, p["ack_on"] if p["ack"] != "wait" else "",
                     p["dis_date"],
                     ("Yes" if p["promo"] == "yes" else "No") if p["submitted"] else "", p["promo_reason"] if p["promo"] == "yes" else "",
                     _gh_myt(p["signed_at"]).strftime("%Y-%m-%d %H:%M") if p["signed_at"] else "",
                     _gh_myt(p["released_at"]).strftime("%Y-%m-%d %H:%M") if p["released_at"] else ""])
    return rows


def gradeh_results_filename(bg=None, unit=None, what="Results"):
    """AI+OneHR_<BG>_<BU>_GradeH_Results_<date>.xlsx, the data downloads' pattern (_dl_filename): the one group and unit in the
    file, else AllBGs / AllBUs; the date in Malaysia. `what` names the file (Results, People)."""
    bgw = _dl_slug(display_bg(bg) or bg) if bg else "AllBGs"
    buw = _dl_slug(display_company(bg, unit) or unit) if (bg and unit) else ("AllBUs" if not unit else _dl_slug(unit))
    return _DL_NAME_UNSAFE_RE.sub("", "AI+OneHR_%s_%s_GradeH_%s_%s.xlsx" % (bgw or "AllBGs", buw or "AllBUs", what, _today_myt().isoformat()))


def _gh_dl_keep(people):
    """The download panel's picks (dl_picks: one business group, the units ticked in it) over Grade H people, user rows or
    gradeh_admin_people dicts. They narrow what the route already scoped to this admin; they never widen it."""
    if not dl_picks():
        return list(people)
    return [p for p in people if dl_keep({"business_group": p.get("bg", p.get("business_group")) or "",
                                          "company": p.get("company") or ""})]


def _gh_dl_name_parts(me, people, bg="", unit="", infer=True):
    """(business group, unit) for a Grade H download's file name: the one group (picked, else the legacy filter's, else the admin's
    own, else the one every row is in: `infer`) and the one unit (the single one ticked, else the legacy filter's); several units
    name none."""
    p = dl_picks()
    units = p.get("units") or []
    bg = p.get("bg") or bg or admin_bg_of(me) or ""
    if not bg and infer:
        bgs = {x.get("bg", x.get("business_group")) or "" for x in people}
        bg = next(iter(bgs)) if len(bgs) == 1 else ""
    unit = (units[0] if len(units) == 1 else "") if units else unit
    return bg, unit


def _gh_dl_about(bg="", units=()):
    """The About sheet's group and unit rows for a Grade H download: the panel's picks, else the legacy filters, else everything the
    admin may see."""
    p = dl_picks()
    bg = p.get("bg") or bg
    units = p.get("units") or list(units)
    return [["Business group", (display_bg(bg) or bg) if bg else "Every business group you look after"],
            ["Business units", ", ".join(display_company(bg, c) or c for c in units) if units else "Every unit you look after"]]


