def _gh_match_row(p):
    return {"full_name": p["name"], "employee_id": p["eid"], "job_title": p["title"], "email": p["email"], "company": p["company"],
            "department": p["dept"], "job_grade": "" if p["grade"] is None else str(p["grade"])}


def _gh_narrow(db, cid, people, q, qin):
    """(rows, filter rows, picked) after the business group / unit pills and the Search in box."""
    me = current_user()
    frows, pk = admin_filter_rows(db, me, "admin_gradeh", params=("bg", "bu", "dept"), levels=2,
                                  people_sql="id IN (SELECT user_id FROM gradeh_people WHERE cycle_id=%d AND private_company=0)" % int(cid))
    rows = people
    if pk["bg"]:
        rows = [p for p in rows if p["bg"] == pk["bg"]]
    if pk["bu"]:
        rows = [p for p in rows if p["company"] == pk["bu"]]
    if q:
        rows = [p for p in rows if people_search_match(qin, q, _gh_match_row(p), ("unit", "dept"))]
    return rows, frows, pk


def _gh_scope_label(me):
    """Who a BG or BU admin's Grade H page is about, in words for its intro: their business group, or their units (up to three), else ''
    (the super admin, or a whole-company role: the page names no one)."""
    bg = admin_bg_of(me)
    if is_super(me) or not bg:
        return ""
    comps = admin_companies_of(me)
    if comps:
        names = sorted(display_company(bg, c) or c for c in comps)
        return _lp_join(names) if len(names) <= 3 else "%d units of %s" % (len(names), display_bg(bg))
    return display_bg(bg)


def _gh_scope_people(people, me):
    """A BG admin's people are their own business group's, a BU admin's their units' (can_access, the scope every admin reader uses);
    the super admin (and a whole-company role) sees everyone."""
    if is_super(me):
        return people
    return [p for p in people if can_access(me, p["bg"], p["company"])]


def _gh_bulk_ctx(db, cid, people, raw):
    """The Set appraiser for several panel (canvas A1b): the ticked people (?pick=1,2,3, those on this list), each with what their
    appraiser is now and whether Set appraiser would leave them out (gradeh_appraiser_block, the writer's own check)."""
    want = []
    for x in raw.split(",")[:GRADEH_BULK_MAX]:
        if x.strip().isdigit() and int(x) not in want:
            want.append(int(x))
    by = {p["pid"]: p for p in people}
    rows = []
    for pid in want:
        p = by.get(pid)
        if not p:
            continue
        _r, kind, _why = gradeh_appraiser_block(db, cid, pid)
        ap = p["appr"]
        now = ("%s (no OneHR account)" % ap["name"]) if ap["kind"] == "sup" else (ap["name"] if ap["kind"] != "none" else "no appraiser yet")
        rows.append({"pid": pid, "name": p["name"], "eid": p["eid"], "title": p["title"], "unit": p["unit"], "key": (p["bg"], p["company"]),
                     "now": now, "kind": kind, "left_out": bool(kind)})
    keys = []
    for r in rows:
        if r["key"] not in keys:
            keys.append(r["key"])
    ok_ = [r for r in rows if not r["left_out"]]
    notes = []
    for kind, words in (("submitted", "already submitted, so %s left out (Reopen first)"), ("released", "in a unit that has been released, so %s left out")):
        names = [r["name"] for r in rows if r["kind"] == kind]
        if names:
            notes.append("%s %s %s." % (_lp_join(names), "is" if len(names) == 1 else "are", words % ("they are" if len(names) > 1 else "they are")))
    return {"people": rows, "n": len(rows), "n_ok": len(ok_), "n_units": len(keys), "unit": rows[0]["unit"] if rows else "", "notes": notes,
            "names_ok": [r["name"] for r in ok_]}


def _gh_hods_bulk_ctx(db, cid, people, raw):
    """The Set HOD for several panel (board H5): the ticked people (?pick=1,2,3, those on this list), each with their Grade H HOD now and whether
    Set HODs would leave them out whoever is picked (gradeh_hods_block, the writer's own first checks; their current HOD having signed off a
    stage is read by the same _gh_hod_signed_words, left out unless the HOD picked is that same one)."""
    want = []
    for x in raw.split(",")[:GRADEH_BULK_MAX]:
        if x.strip().isdigit() and int(x) not in want:
            want.append(int(x))
    by = {p["pid"]: p for p in people}
    rows = []
    for pid in want:
        p = by.get(pid)
        if not p:
            continue
        row, kind, _why = gradeh_hods_block(db, cid, pid)
        if not kind and row is not None and _gh_hod_signed_words(db, cid, row):
            kind = "hod_signed"
        if p["shared"]:
            now = "%s + %s" % (p["hods"][0]["name"], p["hods"][1]["name"])
        elif p["hod_stage"]:
            now = p["hod_name"]
        elif p["hod_id"] or p["hod2_id"]:
            now = "holds a BU CEO or BG CEO seat: BU CEO covers"
        else:
            now = "no HOD yet"
        rows.append({"pid": pid, "name": p["name"], "eid": p["eid"], "title": p["title"], "unit": p["unit"], "key": (p["bg"], p["company"]),
                     "now": now, "kind": kind, "left_out": bool(kind), "has2": p["hod2_set"]})
    keys = []
    for r in rows:
        if r["key"] not in keys:
            keys.append(r["key"])
    ok_ = [r for r in rows if not r["left_out"]]
    notes = []
    for kind, words in (("locked", "in a unit the BU CEO has signed off or Group People has released, so %s left out"),
                        ("hod_signed", "with a HOD who has already signed off a stage, so %s left out unless you pick that same HOD")):
        names = [r["name"] for r in rows if r["kind"] == kind]
        if names:
            notes.append("%s %s %s." % (_lp_join(names), "is" if len(names) == 1 else "are", words % ("they are" if len(names) > 1 else "they are")))
    return {"people": rows, "n": len(rows), "n_ok": len(ok_), "n_units": len(keys), "unit": rows[0]["unit"] if rows else "", "notes": notes,
            "names_ok": [r["name"] for r in ok_], "n_has2": sum(1 for r in ok_ if r["has2"]), "splits": GRADEH_SPLITS}


def _gh_leaders(people):
    """The Leaders line under the tiles (canvas A1), over these people: how many have no HOD stage (their BU CEO covers them) and
    how many units have no BU CEO seated (nobody can sign them off, so they cannot be released). The same two rules the Show choice
    and the list panel pick by (_gh_adm_pick 'nohod' / 'nobu'), so a count and its list cannot disagree."""
    units = {(p["bg"], p["company"]) for p in _gh_adm_pick(people, "nobu")}
    return {"nohod": len(_gh_adm_pick(people, "nohod")), "shared": len(_gh_adm_pick(people, "shared")),
            "nobu_units": len(units), "nobu_people": len(_gh_adm_pick(people, "nobu"))}


GRADEH_BYHOD_FILTERS = (("all", "All HODs"), ("shared", "Shared"), ("norole", "No HOD role"), ("unsigned", "Not signed off"),
                        ("none", "No Grade H HOD"))


def _gh_hod_filter(people, hod):
    """The people of one HOD as the By HOD table counts them (and the list panel, and By person's ?hod=): everyone whose first or second Grade H
    HOD is this account (a user id), whether or not it holds the HOD role; "none" = nobody is named (no live Grade H HOD: the BU CEO covers
    them). Anything else = nobody. The same dicts the page counted, so a count and its list cannot disagree."""
    hod = str(hod or "").strip()
    if hod == "none":
        return [p for p in people if not p["hod_id"] and not p["hod2_id"]]
    if hod.isdigit():
        h = int(hod)
        return [p for p in people if p["hod_id"] == h or p["hod2_id"] == h]
    return []


def _gh_no_role_reasons(db, ids):
    """{user id: the words why this account holds no Grade H HOD role}: 'holds a BU CEO seat' or 'holds a BG CEO seat'. In Grade H only those two take the HOD
    role away (Chris, 2026-11-03: gradeh_hod_has_role; a calibration group's or Group Chief group's calibrator is an HOD here), so no other reason exists. Who holds
    none is the twin's (_hod_seat_kinds, one request-cached read); this only names which seat, in one batched read for the few HODs that need it."""
    ids = sorted({i for i in ids if i})
    if not ids:
        return {}
    bu_ids = {r[0] for r in db.execute("SELECT DISTINCT user_id FROM buceo_seats")}
    col = {r["id"]: r for r in _gh_in(db, "SELECT id, COALESCE(bgceo_bg,'') AS bgb, COALESCE(buceo_company,'') AS buc FROM users WHERE id IN (%s)", ids)}
    out = {}
    for i in ids:
        c = col.get(i)
        out[i] = "holds a BG CEO seat" if (c and c["bgb"] and i not in bu_ids and not c["buc"]) else "holds a BU CEO seat"
    return out


def _gh_people_places(ps):
    """(unit names, department names) of these people (the By person dicts), each sorted and unique: the unit as the page names it, the
    department proper-cased."""
    return sorted({p["unit"] for p in ps if p["unit"]}, key=str.lower), sorted({p["dept"] for p in ps if p["dept"]}, key=str.lower)


def gradeh_by_hod(db, cid, people, now=None):
    """The By HOD table (People & progress, ?view=hod): {"rows": one a HOD, "none": the "No Grade H HOD" row or None} over these people (the
    dicts of gradeh_admin_people, already narrowed to the viewer's scope). A HOD is anyone the Grade H list (or OneHR) names as the first or
    second HOD of one of them, live (not left, not the person): their people = _gh_hod_filter, the same as By person's ?hod=. A HOD who takes
    their people (holds the Grade H HOD role: gradeh_hod_has_role) reads their two stages from gradeh_hod_progress (what their own page says); one who holds a BU CEO
    or BG CEO seat reads "No HOD role" with why, how many of their people go to the BU CEO and how many to the other HOD. Two batched reads beyond the people:
    the HODs' names and the progress (which reads the population once)."""
    now = now or _now_myt()
    named = {}
    for p in people:
        for h in {p["hod_id"], p["hod2_id"]} - {None}:
            named.setdefault(h, []).append(p)
    ids = sorted(named)
    info = {r["id"]: r for r in _gh_in(db, "SELECT id, full_name, employee_id, job_title, job_grade, email FROM users WHERE id IN (%s)", ids)} if ids else {}
    live_ = set(_gh_hod_ids_with_role(db, ids))   # Grade H's own twin of hod_has_role (a calibrator of the normal review is an HOD here), one batched set
    roleless = [h for h in ids if h not in live_]
    why_no = _gh_no_role_reasons(db, roleless)
    prog = gradeh_hod_progress(db, cid, {p["pid"] for p in people}, now) if len(roleless) < len(ids) else {}
    rows = []
    for h in ids:
        ps = named[h]
        u = info.get(h)
        units, depts = _gh_people_places(ps)
        no_role = h in why_no
        r = {"uid": h, "name": ((u["full_name"] or "").strip() if u else "#%d" % h), "eid": ((u["employee_id"] or "") if u else ""),
             "title": proper_name(u["job_title"] or "") if u else "", "units": units, "depts": depts, "n": len(ps), "no_role": no_role,
             "reason": why_no.get(h, ""), "shared": 0, "with": [], "to_bu": 0, "to_other": [], "pot": None, "perf": None, "unsigned": False,
             "match": {"id": h, "full_name": ((u["full_name"] or "") if u else ""), "employee_id": ((u["employee_id"] or "") if u else ""),
                       "job_title": ((u["job_title"] or "") if u else ""), "email": ((u["email"] or "") if u else ""),
                       "job_grade": "" if (not u or u["job_grade"] is None) else str(u["job_grade"]),
                       "company": " ".join(units), "department": " ".join(depts)}}
        if no_role:
            r["to_bu"] = sum(1 for p in ps if not p["hod_stage"])
            others = {}
            for p in ps:
                if p["hod_stage"]:   # the other HOD takes them (at 100%: this one holds no role)
                    o = p["hods"][0]["name"] or "the other HOD"
                    others[o] = others.get(o, 0) + 1
            r["to_other"] = sorted(others.items(), key=lambda kv: kv[0].lower())
        else:
            sh = [p for p in ps if p["shared"]]
            r["shared"] = len(sh)
            r["with"] = sorted({h2["name"] or "the other HOD" for p in sh for h2 in p["hods"] if h2["id"] != h}, key=str.lower)
            pr = prog.get(h)
            for stg in GRADEH_CAL_STAGES:
                sm = pr[stg] if pr else None
                if sm and sm["signed"]:
                    r[stg] = {"kind": "signed", "text": "Signed off " + sm["signed_on"] if sm["signed_on"] else "Signed off", "title": ""}
                elif sm and not sm["gate"]:
                    r[stg] = {"kind": "review", "text": "%d of %d reviewed" % (sm["reviewed"], sm["n"]), "title": ""}
                else:
                    r[stg] = {"kind": "closed", "text": "Not open", "title": (sm["gate"] if sm else "")}
            r["unsigned"] = not all(r[stg]["kind"] == "signed" for stg in GRADEH_CAL_STAGES)
        rows.append(r)
    rows.sort(key=lambda r: (r["name"].lower(), r["uid"]))
    nh = _gh_hod_filter(people, "none")
    none = None
    if nh:
        units, depts = _gh_people_places(nh)
        none = {"uid": "none", "name": "No Grade H HOD", "n": len(nh), "units": units, "depts": depts, "match": {
            "id": 0, "full_name": "", "employee_id": "", "job_title": "", "email": "", "job_grade": "", "company": " ".join(units),
            "department": " ".join(depts)}}
    return {"rows": rows, "none": none}


def _gh_byhod_filter_pick(board, key):
    """The By HOD rows one filter names, as (rows, show the "No Grade H HOD" row): All HODs, Shared, No HOD role, Not signed off (a HOD with a
    stage still to sign), No Grade H HOD (that row alone). The count beside each choice is len() of this."""
    rows = board["rows"]
    if key == "shared":
        return [r for r in rows if r["shared"]], False
    if key == "norole":
        return [r for r in rows if r["no_role"]], False
    if key == "unsigned":
        return [r for r in rows if not r["no_role"] and r["unsigned"]], False
    if key == "none":
        return [], board["none"] is not None
    return list(rows), board["none"] is not None


def _gh_byhod_ctx(db, cid, people, q, qin, hf):
    """The By HOD table's page context: the filter choices with their counts (after the search), the rows to draw and the "No Grade H HOD"
    row. Search in matches a HOD's own name, Employee ID, title, email and grade, their units and their people's departments."""
    board = gradeh_by_hod(db, cid, people)
    if q:
        board = {"rows": [r for r in board["rows"] if people_search_match(qin, q, r["match"], ("unit", "dept"))],
                 "none": board["none"] if (board["none"] and people_search_match(qin, q, board["none"]["match"], ("unit", "dept"))) else None}
    if hf not in dict(GRADEH_BYHOD_FILTERS):
        hf = "all"
    opts = []
    for k, l_ in GRADEH_BYHOD_FILTERS:
        rr, _nn = _gh_byhod_filter_pick(board, k)
        opts.append((k, l_, (board["none"]["n"] if board["none"] else 0) if k == "none" else len(rr)))   # "No Grade H HOD": its people
    rows, show_none = _gh_byhod_filter_pick(board, hf)
    return {"hod_rows": rows, "hod_none": board["none"] if show_none else None, "hf": hf, "hf_opts": opts}


def _gh_pages(rows, per=GRADEH_ADM_PAGE, page=None):
    """`page` = the page to show instead of ?page= (the person panel's own, see _gh_page_ctx)."""
    try:
        page = int(page or request.args.get("page") or 1)
    except ValueError:
        page = 1
    n = len(rows)
    last = max(1, (n + per - 1) // per)
    page = min(max(1, page), last)
    return rows[(page - 1) * per: page * per], {"page": page, "last": last, "n": n, "from": (page - 1) * per + 1 if n else 0,
                                                "to": min(n, page * per)}


def _gh_page_ctx(db, tab, q, qin, menu):
    """Everything the Grade H admin page draws for one tab."""
    n = _gh_counts(db)
    cyc = n["cycle"]
    cid = cyc["id"] if cyc else 0
    me = current_user()
    ctx = {"tab": tab, "tabs": GRADEH_TABS if is_super(me) else tuple(t for t in GRADEH_TABS if t[0] == "people"), "n": n,
           "view_only": not is_super(me), "can_write": is_super(me), "can_open": admin_can(me, "people", "read"),
           "scope_label": _gh_scope_label(me), "list_cols": GRADEH_LIST_IMPORT_COLUMNS, "kpi_cols": GRADEH_KPI_IMPORT_COLUMNS,
           "q": q, "qin": qin, "search_in": menu, "on_cycle": bool(cid and gradeh_module_on(db, cid)),
           "list_url": lambda f: url_for("admin_list_view", key="gh", f=f, fragment=1)}
    if tab == "imports" or not (cyc and n["offered"]):
        return ctx
    people = _gh_scope_people(gradeh_admin_people(db, cid), me)   # a BG or BU admin: their own group or units only
    ctx["all"] = people
    if tab == "people":
        byhod = request.args.get("view") == "hod"   # By HOD (2026-11-03, board H5): one row a HOD; By person is the page as it was
        hodq = (request.args.get("hod") or "").strip() if not byhod else ""
        rows, frows, pk = _gh_narrow(db, cid, people, "" if byhod else q, qin)
        ctx["byhod"] = byhod
        ctx["seg_url"] = {v_: url_for("admin_gradeh", **dict({k: x for k, x in request.args.items() if k in ("bg", "bu", "q", "qin")},
                                                              tab="people", **({"view": "hod"} if v_ == "hod" else {})))
                          for v_ in ("person", "hod")}
        if byhod:
            ctx.update(_gh_byhod_ctx(db, cid, rows, q, qin, request.args.get("hf") or "all"))
            ctx["list_hod_url"] = lambda h: url_for("admin_list_view", key="gh", hod=h, fragment=1)
            ctx["person_hod_url"] = lambda h: url_for("admin_gradeh", **dict({k: x for k, x in request.args.items() if k in ("bg", "bu")},
                                                                              tab="people", hod=h))
        if hodq:
            rows = _gh_hod_filter(rows, hodq)
            hu = db.execute("SELECT full_name, employee_id FROM users WHERE id=?", (int(hodq),)).fetchone() if hodq.isdigit() else None
            ctx["hod_filter"] = {"label": "No Grade H HOD" if hodq == "none" else ((hu["full_name"] + (" · " + hu["employee_id"] if hu["employee_id"] else "")) if hu else "That HOD"),
                                 "clear_url": url_for("admin_gradeh", **dict({k: x for k, x in request.args.items() if k not in ("hod", "page", "panel", "set", "pick")}, tab="people"))}
        show = request.args.get("show") or "all"
        if show not in dict(GRADEH_SHOW_OPTIONS) and show not in GRADEH_SHOW_HOME:
            show = "all"
        ctx["show_opts"] = [(k, l_, len(_gh_adm_pick(rows, k))) for k, l_ in GRADEH_SHOW_OPTIONS]
        if show in GRADEH_SHOW_HOME:   # opened from Home's card: that choice is the picker's selected option, after Everyone
            ctx["show_opts"].insert(1, (show, GRADEH_SHOW_HOME[show], len(_gh_adm_pick(rows, show))))
        rows = _gh_adm_pick(rows, show)
        # the person panel's address (?panel=person&pp=<id>), as a save in it comes back: the list is on the page that person is on NOW (a change of
        # appraiser re-sorts the list, so they can have moved), or the panel is dropped when the Show choice no longer holds them
        pp_, pp_page = request.args.get("pp", ""), None
        if request.args.get("panel") == "person" and pp_.isdigit():
            at_ = next((i for i, r_ in enumerate(rows) if r_["pid"] == int(pp_)), None)
            if at_ is None:
                ctx["pp_gone"] = True
            else:
                pp_page = at_ // GRADEH_ADM_PAGE + 1
        page_rows, pg = _gh_pages(rows, page=pp_page)
        ctx.update(rows=page_rows, pg=pg, frows=frows, show=show,
                   tiles=[("all", "On OneHR", "var(--accent-ink)"), ("route_a", "KPI route", "var(--info-ink)"), ("route_b", "Line manager route", "var(--ok-ink)"),
                          ("submitted", "Submitted by line managers", ""), ("acked", "Acknowledged", ""), ("disagree", "Disagree", ""),
                          ("need", "Need an appraiser", "need")])
        ctx["tile_n"] = {k: len(_gh_adm_pick(people, k)) for k in ("all", "route_a", "route_b", "submitted", "acked", "disagree", "need")}
        ctx["leaders"] = _gh_leaders(people)
        ctx["bulk_url"] = url_for("admin_gradeh", **dict({k: v for k, v in request.args.items() if k not in ("page", "panel", "set", "pick")},
                                                         tab="people", panel="bulk"))
        ctx["bulk_hod_url"] = url_for("admin_gradeh", **dict({k: v for k, v in request.args.items() if k not in ("page", "panel", "set", "pick")},
                                                             tab="people", panel="bulkhod"))
        sp = request.args.get("set")
        if request.args.get("panel") == "appraiser" and sp and sp.isdigit() and ctx["can_write"]:
            ctx["set_person"] = next((p for p in people if p["pid"] == int(sp)), None)
        if request.args.get("panel") == "hod" and sp and sp.isdigit() and ctx["can_write"]:
            ctx["hod_person"] = next((p for p in people if p["pid"] == int(sp)), None)
        if request.args.get("panel") == "bulk" and ctx["can_write"]:
            ctx["bulk"] = _gh_bulk_ctx(db, cid, people, request.args.get("pick") or "")
        if request.args.get("panel") == "bulkhod" and ctx["can_write"]:
            ctx["bulkhod"] = _gh_hods_bulk_ctx(db, cid, people, request.args.get("pick") or "")
    elif tab == "bands":
        rows, frows, pk = _gh_narrow(db, cid, people, q, qin)
        scope = request.args.get("scope") or "all"
        if scope not in dict(GRADEH_BANDS_SCOPE):
            scope = "all"
        ctx["scope_opts"] = [(k, l_, len(_gh_adm_pick(rows, k))) for k, l_ in GRADEH_BANDS_SCOPE]
        rows = _gh_adm_pick(rows, scope)
        page_rows, pg = _gh_pages(rows)
        for p in page_rows:
            p["label"] = gradeh_calib_label(p["b_fin"]["perf"], p["b_fin"]["pot"]) or ""
        ctx.update(rows=page_rows, pg=pg, frows=frows, scope=scope, band_long=GRADEH_BAND_LONG, perf_bands=GRADEH_PERF_BANDS,
                   pot_bands=GRADEH_POT_BANDS,
                   tiles=[("signed_off", "Signed off by a BU CEO", ""), ("perf_moved", "Performance moved", ""), ("pot_moved", "Potential moved", ""),
                          ("super", "Changed by super admin", ""), ("released", "Released", "")])
        ctx["tile_n"] = {k: len(_gh_adm_pick(people, k)) for k in ("signed_off", "perf_moved", "pot_moved", "super", "released")}
        fp = request.args.get("fp")
        if request.args.get("panel") == "final" and fp and fp.isdigit():
            sp_ = next((p for p in people if p["pid"] == int(fp)), None)
            if sp_:
                sp_["label"] = gradeh_calib_label(sp_["b_fin"]["perf"], sp_["b_fin"]["pot"]) or ""
            ctx["final_person"] = sp_
    elif tab == "settings":
        ctx.update(_gh_settings_ctx(db, cid, people))
    return ctx


def _gh_release_ctx(db):
    """The Release results page's Grade H card, or None while the module is not running."""
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc) or not gradeh_module_on(db, cyc["id"]):
        return None
    st = gradeh_release_state(db, cyc["id"])
    st["cycle"] = cyc
    st["mail_on"] = mailer.is_configured()
    return st


@app.route("/admin/gradeh")
@admin_required
def admin_gradeh():
    """Grade H Appraisal: the super admin's People & progress, Imports, Final bands and Settings; a BG or BU admin whose role has
    gradeh.read (admin_required checks it) gets People & progress alone, view only, for their own group or units (2026-10-31, canvas
    R2: "BG / BU admins read Grade H progress; nobody but the super admin writes"). Every other tab refuses them."""
    db = get_db()
    tab = request.args.get("tab") or "people"
    if tab not in dict(GRADEH_TABS):
        tab = "people"
    if tab != "people" and not is_super(current_user()):
        abort(403)
    q, qin, menu = people_search_args(("unit", "dept"))
    ctx = _gh_page_ctx(db, tab, q, qin, menu)
    if ctx.get("pp_gone"):   # the person panel's address, for someone the list no longer shows (a save moved them out of the Show choice): the list, panel closed
        return redirect(url_for("admin_gradeh", **{k: v for k, v in request.args.items() if k not in ("panel", "pp")}))
    return render_template("admin_gradeh.html", **ctx)


GRADEH_PEEK_VIEWS = ("appraiser", "hod")   # the person panel's Change views (the super admin's)


@app.route("/admin/gradeh/person/<int:pid>")
@admin_required
def admin_gradeh_person(pid):
    """One Grade H person for the People & progress list's side panel (2026-11-03, board H6b; the People > Users peek's own mechanism: admin.js loads
    this address with ?fragment=1 into the page's one person panel). READ ONLY, no write on GET, no model call, one batched read (the list's own
    row, gradeh_admin_people(only=)): where it stands, who appraises them (Change, the super admin's, opens the SAME appraiser / HOD forms as the
    Set appraiser / Set HOD panels, in the panel: ?view=appraiser | hod), their appraisal (the person page's Grade H tab blocks) and Reopen
    (the super admin's, once submitted and until released). Scoped as the list is: the super admin, and admin roles with gradeh.read for their
    own people; anyone else 404. Without ?fragment=1 (a new tab, "Open their full page") it is the person's full page."""
    db, me = get_db(), current_user()
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc) or not (is_super(me) or admin_can(me, "gradeh", "read")):
        abort(404)
    g_ = next(iter(_gh_scope_people(gradeh_admin_people(db, cyc["id"], only=pid), me)), None)
    if not g_:
        abort(404)
    can_open = bool(admin_can(me, "people", "read"))
    if not request.args.get("fragment"):
        return redirect(url_for("admin_person", uid=g_["uid"], tab="gradeh") if can_open
                        else url_for("admin_gradeh", tab="people", panel="person", pp=pid))
    p = db.execute("SELECT * FROM users WHERE id=?", (g_["uid"],)).fetchone()
    gh = _person_gradeh(db, me, p, cyc, g_row=g_)
    if not gh or not gh.get("g"):
        abort(404)
    view = request.args.get("view") if (is_super(me) and request.args.get("view") in GRADEH_PEEK_VIEWS and not g_["released"]) else ""
    sub = " · ".join(x for x in (g_["eid"], g_["title"], ("JG " + str(g_["grade"])) if g_["grade"] else "", g_["dept"], g_["unit"]) if x)
    return render_template("_gradeh_adm_person.html", gh=gh, g=g_, sub=sub, view=view, can_write=bool(is_super(me)), can_open=can_open,
                           lm_when=_gh_cal_when(g_["lm_at"]) if g_["lm_at"] else "",
                           self_url=url_for("admin_gradeh_person", pid=pid))


def _gh_back(tab=None):
    return _admin_next(url_for("admin_gradeh", tab=tab) if tab else url_for("admin_gradeh"))


