@super_required
def admin_gradeh_appraiser_bulk():
    """Set one appraiser for the people ticked on People & progress (canvas A1b): everything is checked first, then each person who
    can be changed goes through gradeh_set_appraiser (audited a person); the rest are named. The super admin's."""
    db, me = get_db(), current_user()
    ok, msg = gradeh_set_appraiser_bulk(db, me, request.form.getlist("pid"), request.form.get("appraiser_eid"))
    flash(msg, "ok" if ok else "error")
    return _gh_back("people")


GRADEH_LIST_HEAD = ["Employee ID", "Name", "Business group", "Unit", "Department", "Route", "Appraiser", "HOD", "Second HOD", "HOD split %", "BU CEO",
                    "Where it is", "Acknowledgement", "Disagrees", "Can sign in"]


def gradeh_list_rows(people):
    """The people-and-progress Excel's rows, one a person, as the page shows them: who leads them and where it stands. Never a band, a
    rating, a potential or a nomination (those are Final bands and the results Excel, the super admin's)."""
    rows = []
    for p in people:
        ap = p["appr"]
        appr = (ap["name"] + ((" (" + ap["eid"] + ")") if ap["eid"] else "")) if ap["kind"] != "none" else "Needs an appraiser"
        if ap["kind"] == "sup":
            appr += " (supervisor, no line manager in the source file)"
        hod = (p["hod_name"] + ((" (" + p["hod_eid"] + ")") if p["hod_eid"] else "")) if p["hod_stage"] else "No HOD (BU CEO covers)"
        hod2, split = "", ""
        if p["shared"]:   # two live HODs: the first is `hod` above, the second and the first's share (the second has the rest)
            h2 = p["hods"][1]
            hod2 = h2["name"] + ((" (" + h2["eid"] + ")") if h2["eid"] else "")
            split = p["hods"][0]["share"]
        bu = (p["bu_name"] + ((" (" + p["bu_eid"] + ")") if p["bu_eid"] else "")) if p["bu_seated"] else "No BU CEO seated"
        ack = (p["ack_text"] + ((" · " + p["ack_on"]) if p["ack_on"] else "")) if p["ack"] else ""
        rows.append([_csv_cell(v) for v in (
            p["eid"], p["name"], p["bg"], p["company"], p["dept"], "KPI" if p["route"] == "A" else "Line manager", appr, hod, hod2, split, bu,
            p["status_text"] + ((": " + p["blocked"]) if p["blocked"] else ""), ack, p["dis_date"], "Yes" if p["has_email"] else "No work email")])
    return rows


@app.route("/admin/gradeh/list.xlsx")
@admin_required
def admin_gradeh_list_xlsx():
    """Download this list: the rows People & progress shows under its filters (business group, unit, Search in, Show), as Excel. The
    super admin's, or a BG / BU admin whose role has gradeh.read, within their own group or units. Columns: who, route, appraiser, HOD,
    BU CEO, where it is, acknowledgement, can sign in. Never a band, rating, potential or nomination."""
    db, me = get_db(), current_user()
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc):
        abort(404)
    people = _gh_scope_people(gradeh_admin_people(db, cyc["id"]), me)
    q, qin, _menu = people_search_args(("unit", "dept"))
    rows, _frows, pk = _gh_narrow(db, cyc["id"], people, q, qin)
    if request.args.get("hod"):   # By HOD's "People" fallback: one HOD's people (or none named), as the page filters them
        rows = _gh_hod_filter(rows, request.args.get("hod"))
    show = request.args.get("show") or "all"
    if show not in dict(GRADEH_SHOW_OPTIONS) and show not in GRADEH_SHOW_HOME:
        show = "all"
    rows = _gh_dl_keep(_gh_adm_pick(rows, show))   # then the Reports panel's picks, inside the admin's own scope (2026-11-04)
    data = gradeh_list_rows(rows)
    fbg, fbu = _gh_dl_name_parts(me, rows, pk["bg"], pk["bu"], infer=False)
    fname = gradeh_results_filename(fbg or None, fbu or None, "People")
    log_activity(db, me["id"], "export", "%s (%s, %d rows)" % (fname, cyc["name"], len(data)))
    about = [["Report", "Grade H Appraisal: people and progress"], ["Cycle", cyc["name"]]] + \
            _gh_dl_about(pk["bg"], [pk["bu"]] if pk["bu"] else []) + [
             ["Show", dict(GRADEH_SHOW_OPTIONS).get(show) or GRADEH_SHOW_HOME[show]], ["Search", q or ""],
             ["Generated (MYT)", _now_myt().strftime("%Y-%m-%d %H:%M")], ["Rows", len(data)],
             ["What this is", "One row a person on the Grade H list, as People & progress shows them: who appraises them, their HOD and "
                              "BU CEO, where the appraisal is and how it was acknowledged. For people who run Grade H: never share it with staff."]]
    return _xlsx_response(fname, [("Grade H people", GRADEH_LIST_HEAD, data), ("About", ["Item", "Detail"], about)])


