@app.route("/admin/gradeh/settings", methods=["POST"])
@super_required
def admin_gradeh_settings():
    """The Settings saves (action = deemed | deemed_on | early | perf_cuts | perf_curve | pot | points). perf_cuts, pot and points re-work
    bands, so they are in SUPER_BAND_ENDPOINTS (a remark first)."""
    db, me = get_db(), current_user()
    action = request.form.get("action")
    cid = gradeh_settings_cycle_id(db)
    if action not in ("deemed", "deemed_on", "early", "perf_cuts", "perf_curve", "pot", "points"):
        abort(400)
    if not cid:
        flash("Grade H Appraisal is not offered on the active cycle (it needs a Year-End cycle, on a server where it is switched on), "
              "so there is nothing to save yet.", "error")
        return _gh_back("settings")
    if action == "deemed":
        ok, msg = gradeh_save_deemed(db, me, request.form)
    elif action == "deemed_on":
        ok, msg = gradeh_save_deemed_switch(db, me, request.form)
    elif action == "early":
        ok, msg = gradeh_save_early(db, me, cid, request.form)
    elif action == "perf_cuts":
        ok, msg = gradeh_save_perf_cuts(db, me, cid, request.form)
    elif action == "perf_curve":
        ok, msg = gradeh_save_perf_curve(db, me, request.form)
    elif action == "points":
        ok, msg = gradeh_save_points(db, me, cid, request.form)
    else:
        ok, msg = gradeh_save_pot(db, me, cid, request.form)
    flash(msg, "ok" if ok else "error")
    return _gh_back("settings")


@app.route("/admin/gradeh/release", methods=["POST"])
@super_required
def admin_gradeh_release():
    """Release (or take back) Grade H results by unit, from Cycle > Release results."""
    db, me = get_db(), current_user()
    cid = gradeh_calib_cycle_id(db)
    back = lambda: _admin_next(url_for("admin_talent_release"))   # noqa: E731
    if not cid:
        flash("Grade H Appraisal is not running on the active cycle.", "error")
        return back()
    action = request.form.get("action")
    if action == "revoke":
        ok, msg = gradeh_revoke(db, me, cid, request.form.get("unit"))
    elif action == "release":
        units = request.form.getlist("unit")
        ok, msg, _d = gradeh_release(db, me, cid, units, expect=request.form.get("expect"))
        if ok:
            _outbox_kick()
    else:
        abort(400)
    flash(msg, "ok" if ok else "error")
    return back()


@app.route("/admin/gradeh/results.xlsx")
@super_required
def admin_gradeh_results_xlsx():
    """Group People's Excel: one row a person, the calibration trail, the acknowledgement and the promotion nomination. ?unit= (one
    unit) narrows it; named AI+OneHR_<BG>_<BU>_GradeH_Results_<date>.xlsx."""
    db, me = get_db(), current_user()
    cyc = active_cycle(db)
    if not cyc or not gradeh_cycle_offered(cyc):
        abort(404)
    people = gradeh_admin_people(db, cyc["id"])
    # the Reports panel's picks (one business group, the units ticked in it) narrow it; a legacy ?unit= only where nothing was picked
    unit = (request.args.get("unit") or "").strip() if not dl_picks() else ""
    if unit:
        people = [p for p in people if p["company"] == unit]
    else:
        people = _gh_dl_keep(people)
    bg, funit = _gh_dl_name_parts(me, people, "", unit)
    if unit and not bg:
        bg = people[0]["bg"] if people else ""
    rows = gradeh_results_rows(db, cyc["id"], people)
    fname = gradeh_results_filename(bg or None, funit or None)
    log_activity(db, me["id"], "export", "%s (%s, %d rows)" % (fname, cyc["name"], len(rows)))
    about = [["Report", "Grade H Appraisal results"], ["Cycle", cyc["name"]], ["Scope", unit or "Every unit with Grade H people"]] + \
            _gh_dl_about(bg, [funit] if funit else []) + [
             ["Generated (MYT)", _now_myt().strftime("%Y-%m-%d %H:%M")], ["Rows", len(rows)],
             ["What this is", "One row a person on the Grade H list: the line manager's result, each calibration stage, the final result as it stands "
                              "now (a unit's is final once released), the talent label, every move and its remark, how they acknowledged and when, "
                              "and the line manager's promotion nomination. For Group People: never share it with staff."],
             ["Talent label", "OneHR's 9-box until Group P&R's own grid is set."]]
    return _xlsx_response(fname, [("Grade H results", GRADEH_RESULTS_HEAD, rows), ("About", ["Item", "Detail"], about)])


